if not DB[803] then DB[803]={id=803,zoneId=1637,name="<UNUSED>",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=803",image="assets/images/quests/placeholder.png"} end
if not DB[804] then DB[804]={id=804,zoneId=363,name="Sarkoth",level=5,minLevel=1,giver="Hana'zua",giverType="NPC",giverId=3287,ender="Gornek",enderType="NPC",enderId=3143,poiX=-398,poiY=-4109,wowhead="https://www.wowhead.com/wotlk/quest=804",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure!$b$bBut it remains that I cannot make the trek back to the Den unassisted. Please, $n, return to the Den and tell Gornek of my situation. Perhaps he can help me.",logDesc="Bring the news of Hana'zua's plight to Gornek at the Den.",choiceRewards={{id=4916,qty=1},{id=4917,qty=1}}} end
if not DB[805] then DB[805]={id=805,zoneId=363,name="Report to Sen'jin Village",level=5,minLevel=1,giver="Zureetha Fargaze",giverType="NPC",giverId=3145,ender="Master Gadrin",enderType="NPC",enderId=3188,poiX=-629,poiY=-4228,wowhead="https://www.wowhead.com/wotlk/quest=805",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Your trials against the Burning Blade are finished... here in the Valley.  But I want you to report your findings.$B$BGo to the troll village of Sen'jin and seek out Master Gadrin.  Sen'jin Village is east out of the valley, then right at the fork.$B$BTell Gadrin of the Burning Blade, and that they have reached the Valley of Trials.  Discover from him if they have yet reached Sen'jin.$B$BGo, $N, and be swift.  I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...",logDesc="Speak with Master Gadrin in Sen'jin Village."} end
if not DB[806] then DB[806]={id=806,zoneId=14,name="Dark Storms",level=12,minLevel=4,giver="Orgnil Soulscar",giverType="NPC",giverId=3142,ender="Orgnil Soulscar",enderType="NPC",enderId=3142,poiX=287,poiY=-4725,wowhead="https://www.wowhead.com/wotlk/quest=806",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We cannot allow the Burning Blade a foothold in Durotar!  We must destroy them before their evil festers!$B$BI have undergone my own investigations and found that a Burning Blade warlock, the goblin Fizzle Darkstorm, has camped within Thunder Ridge to the northwest.  There he and his cultist minions spread chaos.$B$BFind and defeat Fizzle, and bring me his dead claw!",logDesc="Bring Fizzle's Claw to Orgnil Soulscar in Razor Hill.",rewards={{id=4942,qty=1}}} end
if not DB[807] then DB[807]={id=807,zoneId=14,name="<UNUSED>",level=11,minLevel=4,wowhead="https://www.wowhead.com/wotlk/quest=807",image="assets/images/quests/placeholder.png",xpDiff=6,desc="My scouts report that some of the Durotar wildlife have become infected with a demonic taint.  They were seen to the north and west.$B$BThey wander among their brethren as normal beasts,but evil powers flow through them,and burning within each one is a heart scorched by black magic.$B$BThese beasts must be destroyed!$B$BIf you find such an animal while you explore Durotar,kill it and collect its Scorched Heart.  Bring the hearts to me and I will have them studied,then destroyed.",logDesc="Bring 5 Scorched Hearts to Orgnil Soulscar in Razor Hill."} end
if not DB[808] then DB[808]={id=808,zoneId=14,name="Minshina's Skull",level=9,minLevel=4,giver="Master Gadrin",giverType="NPC",giverId=3188,ender="Master Gadrin",enderType="NPC",enderId=3188,poiX=-826,poiY=-4921,wowhead="https://www.wowhead.com/wotlk/quest=808",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I hear the voice of my brother, Minshina, calling to me in my dreams.$B$BHe was taken by Zalazane, the warlock on the Echo Isles to the east. And he is dead.$B$BBut death is not freedom for my brother. Minshina's spirit was trapped within his own skull by Zalazane's magics. In my dreams I see it with other skulls, in a circle of power on the largest Echo Isle. As long as it remains there my brother's soul is doomed.$B$BPlease, $N. Find the circle and retrieve Minshina's skull. Bring it to me.$B$BFree him!",logDesc="Retrieve Minshina's skull from the circle of power on the Echo Isles.$B$BBring it to Master Gadrin in Sen'jin Village.",rewards={{id=4945,qty=1}}} end
if not DB[809] then DB[809]={id=809,zoneId=14,name="Ak'Zeloth",level=13,minLevel=4,giver="Neeru Fireblade",giverType="NPC",giverId=3216,ender="Ak'Zeloth",enderType="NPC",enderId=3521,rewardNextId=924,poiX=1801,poiY=-4375,wowhead="https://www.wowhead.com/wotlk/quest=809",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.$B$BIt belongs to the Burning Blade, a cult that rallies around an item of demonic power.  It is called the Demon Seed, and it resides in the Barrens atop Dreadmist Peak.  It must be destroyed!$B$BGo to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  He will direct you further.",logDesc="Speak with Ak'Zeloth in the Barrens."} end
if not DB[810] then DB[810]={id=810,zoneId=14,name="<UNUSED>",level=5,minLevel=4,rewardNextId=811,wowhead="https://www.wowhead.com/wotlk/quest=810",image="assets/images/quests/placeholder.png",xpDiff=5,money=100,desc="You would do well to learn how dangerous this land can be,$c.$B$BThe wildlife here can teach us such things... if we are wise and observant.$B$BThe scorpids are a perfect example of survival in Durotar. If you are to survive,it would be wise to take on some of their characteristics as your own. Their hardened carapaces can protect you from the harshness of the sun,or even a deadly weapon.$B$BBring me 6 Small Scorpid Carapaces from the Clattering Scorpids,$N,and I shall see about rewarding you justly.",logDesc="Bring 6 Small Scorpid Carapaces to Kor'ghan in Sen'jin Village."} end
if not DB[811] then DB[811]={id=811,zoneId=14,name="<UNUSED>",level=7,minLevel=4,wowhead="https://www.wowhead.com/wotlk/quest=811",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One of the other traits of the scorpids is their fierce loyalty. They will protect one another if they are in danger--you've probably already seen this behavior in your first scorpid hunt.$B$BYou would do well to heed that lesson and adapt it for yourself: we are stronger as one; we are weak when we are divided into many.$B$BBring me 8 Large Scorpid Carapaces from the Armored Scorpids and I shall reward you for learning this wisdom.",logDesc="Bring 8 Large Scorpid Carapaces to Kor'ghan in Sen'jin Village."} end
if not DB[812] then DB[812]={id=812,zoneId=14,name="Need for a Cure",level=9,minLevel=7,giver="Rhinag",giverType="NPC",giverId=3190,ender="Rhinag",enderType="NPC",enderId=3190,poiX=1279,poiY=-4189,wowhead="https://www.wowhead.com/wotlk/quest=812",image="assets/images/quests/placeholder.png",xpDiff=6,desc="$N... your timing is perfect. I just hope I can compliment your haste as well.$B$BI was careless while fighting a few of the venomtails nearby, and one of them stung me deeply. I can feel its poison weakening me even as we speak. At this rate, I got maybe an hour left to live. But I'll need your help if I'm to do so...$B$BKor'ghan in Orgrimmar knows how to make the antidote. Find him... and hurry, $N. I won't be able to last much longer. He should be in the Cleft of Shadow.",logDesc="Find Kor'ghan in Orgrimmar and get the Venomtail Antidote. Then bring the antidote to Rhinag near the northwestern border of Durotar.",choiceRewards={{id=4937,qty=1},{id=4929,qty=1}}} end
if not DB[813] then DB[813]={id=813,zoneId=14,name="Finding the Antidote",level=9,minLevel=7,giver="Kor'ghan",giverType="NPC",giverId=3189,ender="Kor'ghan",enderType="NPC",enderId=3189,poiX=1773,poiY=-4343,wowhead="https://www.wowhead.com/wotlk/quest=813",image="assets/images/quests/placeholder.png",desc="Venomtails are some of the deadliest scorpids in Durotar. It was unwise for Rhinag to hunt them without having some of the antidote with him, but right now, chastising is the last thing he needs.$B$BBring me a few venomtail poison sacs from any of the venomtails near the entrance of Orgrimmar and I'll make an antidote for him.$B$BMake haste, $N. One of our own needs your help.",logDesc="Bring 4 Venomtail Poison Sacs to Kor'ghan in Orgrimmar.",rewards={{id=4904,qty=1}}} end
if not DB[814] then DB[814]={id=814,zoneId=14,name="<UNUSED>",level=6,minLevel=4,wowhead="https://www.wowhead.com/wotlk/quest=814",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Cook and clean--that's all I do!$B$BYou want to eat,you get me some more meat! I don't have all day to hunt and prepare food for all these louses. You got to learn to pull your own weight around here if you wanna be treated equal.$B$BGet me some Chunks of Boar Meat if you want to make yourself useful... or you don't want to starve to death.",logDesc="Bring 10 Chunks of Boar Meat to Cook Torka in Razor Hill."} end
if not DB[815] then DB[815]={id=815,zoneId=14,name="Break a Few Eggs",level=8,minLevel=6,giver="Cook Torka",giverType="NPC",giverId=3191,ender="Cook Torka",enderType="NPC",enderId=3191,poiX=312,poiY=-4665,wowhead="https://www.wowhead.com/wotlk/quest=815",image="assets/images/quests/placeholder.png",xpDiff=5,money=225,desc="Bah! I almost forgot I need to get breakfast ready.$B$B$N, get yourself movin' and get me some taillasher eggs. I'll need at least three of them if I'm going to have enough for tomorrow's meal.$B$BThe Bloodtalon taillashers can be fierce, and protect their eggs to the death more often than not. They sometimes bury their eggs too deep in the earth to uncover safely, but if you head to the Echo Isles to the southeast of Sen'jin Village, you can usually find them all over those islands.",logDesc="Bring 3 Taillasher Eggs to Cook Torka in Razor Hill.",rewards={{id=4540,qty=5},{id=117,qty=5}}} end
if not DB[816] then DB[816]={id=816,zoneId=14,name="Lost But Not Forgotten",level=11,minLevel=8,giver="Misha Tor'kren",giverType="NPC",giverId=3193,ender="Misha Tor'kren",enderType="NPC",enderId=3193,poiX=742,poiY=-4242,wowhead="https://www.wowhead.com/wotlk/quest=816",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N, please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River. I fear the worst.$B$BAs strong as he was, his stubborn pride has always drawn him into trouble. I warned him that the crocolisks were powerful and vicious. He grew angry and stormed off.$B$BIf you can't find him, at least bring me a sign of his fate... even if you have to open up the stomach of every crocolisk along the Southfury's banks.",logDesc="Bring a sign of Kron's fate to Misha Tor'kren at the farmstead northwest of Razor Hill.",rewards={{id=4944,qty=1}}} end
if not DB[817] then DB[817]={id=817,zoneId=14,name="Practical Prey",level=8,minLevel=5,giver="Vel'rin Fang",giverType="NPC",giverId=3194,ender="Vel'rin Fang",enderType="NPC",enderId=3194,poiX=-798,poiY=-4921,wowhead="https://www.wowhead.com/wotlk/quest=817",image="assets/images/quests/placeholder.png",xpDiff=5,money=225,desc="Many of the hides we use come from Durotar tigers, $N. Blankets, armor, tents: there are a great many reasons we hunt the beasts, and many reasons we let them thrive at the same time.$B$BThe time has come for us to cull the flock, so to speak. Our numbers grow, and our needs are beginning to overwhelm our stocks. I need more hides if I'm to prepare suitable goods for our people.$B$BBring me 4 Durotar tiger furs, and I shall reward you. You can find them on the islands south of here.",logDesc="Bring 4 Durotar Tiger Furs to Vel'rin Fang in Sen'jin Village."} end
if not DB[818] then DB[818]={id=818,zoneId=14,name="A Solvent Spirit",level=7,minLevel=5,giver="Master Vornal",giverType="NPC",giverId=3304,ender="Master Vornal",enderType="NPC",enderId=3304,poiX=-814,poiY=-4921,wowhead="https://www.wowhead.com/wotlk/quest=818",image="assets/images/quests/placeholder.png",xpDiff=5,money=175,desc="Although my eyes fail me, I still can see clearly enough. More often I must rely on my alchemical skills to aid me in magics that once came easily. But I refuse to take on an apprentice--no troll or orc worthy enough has ever come forward.$B$BAre you worthy? Yes, of course you are... of course you think you are.$B$BI need a few things. Will you get them for me?$B$BI need intact makrura eyes, and vials of crawler mucus. You can find them on any makrura or crawler in Durotar. We shall speak again soon.",logDesc="Bring 4 Intact Makrura Eyes and 8 vials of Crawler Mucus to Master Vornal in Sen'jin Village.",rewards={{id=4941,qty=10}}} end
if not DB[819] then DB[819]={id=819,zoneId=17,name="Chen's Empty Keg",level=15,minLevel=11,ender="Brewmaster Drohn",enderType="NPC",enderId=3292,rewardNextId=821,wowhead="https://www.wowhead.com/wotlk/quest=819",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A small placard on one of the ends of the keg says,$B$B\"Chen Stormstout-$B$BMay your spirit be raised and always raise your spirits.\"",logDesc="Find someone who knows about Chen's Empty Keg."} end
if not DB[820] then DB[820]={id=820,zoneId=14,name="<UNUSED>",level=9,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=820",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Truly a spirit of strength resides in your body--or maybe it was only luck,yes?$B$BThat is what the young rely on these days: luck... and the generosity of those more powerful than they. Not many take the time to find their own path. It's always begging for help... always the reward,and never the quest. I'm sure you'll be the same.$B$BBut there is hope. I need one other thing for my potion,$N: 8 shimmerweed herbs. They can be found in Thunder Ridge to the northwest of Razor Hill.",logDesc="Bring 8 Shimmerweed to Master Vornal in Sen'jin Village."} end
if not DB[821] then DB[821]={id=821,zoneId=17,name="Chen's Empty Keg",level=15,minLevel=11,giver="Brewmaster Drohn",giverType="NPC",giverId=3292,ender="Brewmaster Drohn",enderType="NPC",enderId=3292,rewardNextId=822,poiX=-981,poiY=-3686,wowhead="https://www.wowhead.com/wotlk/quest=821",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Would you like a taste of Chen's namesake? Ahh, the stormstout is a mighty brew. Chen taught the recipe to my mentor, and my mentor passed it on to me. I'll need you to get me a few things, but I can tell you this: the kick is worth it.$B$BBring me 5 savannah lion tusks from any savannah lion, 5 plainstrider kidneys from any plainstrider, and 1 thunder lizard horn from any species of thunder lizard. That should do the trick nicely.$B$BYou can find these ingredients throughout the Barrens.",logDesc="Bring 5 Savannah Lion Tusks, 5 Plainstrider Kidneys, and 1 Thunder Lizard Horn to Brewmaster Drohn in Ratchet.",rewards={{id=4952,qty=5}}} end
if not DB[822] then DB[822]={id=822,zoneId=17,name="Chen's Empty Keg",level=24,minLevel=11,giver="Brewmaster Drohn",giverType="NPC",giverId=3292,ender="Brewmaster Drohn",enderType="NPC",enderId=3292,poiX=-981,poiY=-3686,wowhead="https://www.wowhead.com/wotlk/quest=822",image="assets/images/quests/placeholder.png",desc="Good stuff, that stormstout, huh?$B$BI have another recipe that I learned from Chen. Would you be interested? It won't take long to make, and it might be useful if you plan on adventuring some more.$B$BBring me 5 lightning glands from any stormhide, 1 thunderhawk saliva gland from greater thunderhawks, and a kodo liver from any of the Barrens' kodos.$B$BLike I said, this stuff has kick; it's the trogg ale that I mentioned to you before.",logDesc="Bring 5 Lightning Glands, 1 Thunderhawk Saliva Gland and 1 Kodo Liver to Brewmaster Drohn in Ratchet.",rewards={{id=4953,qty=5}}} end
if not DB[823] then DB[823]={id=823,zoneId=14,name="Report to Orgnil",level=7,minLevel=4,giver="Master Gadrin",giverType="NPC",giverId=3188,ender="Orgnil Soulscar",enderType="NPC",enderId=3142,poiX=-826,poiY=-4921,wowhead="https://www.wowhead.com/wotlk/quest=823",image="assets/images/quests/placeholder.png",xpDiff=3,desc="We at Sen'jin Village are not without our own troubles, and we thank you for your aid.  But the news you bring regarding the Burning Blade could be trouble for everyone.$B$BThere is an orc stationed at Razor Hill, Orgnil Soulscar, who polices Durotar from evils such as the Burning Blade!  Go to Orgnil and tell him of our plight, as well as your news from the Valley of Trials.  He will want to know these things.$B$BRazor Hill lies to the north.",logDesc="Speak with Orgnil Soulscar in Razor Hill."} end
if not DB[824] then DB[824]={id=824,zoneId=331,name="Je'neu of the Earthen Ring",level=27,minLevel=23,giver="Mastok Wrilehiss",giverType="NPC",giverId=12737,ender="Je'neu Sancrea",enderType="NPC",enderId=12736,poiX=2366,poiY=-2548,wowhead="https://www.wowhead.com/wotlk/quest=824",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements.  They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know.$B$BLucky for you, I know someone in the Earthen Ring here in Ashenvale.  Head over to Zoram'gar Outpost on the coast of the Zoram Strand; show Je'neu Sancrea what you found.  If anyone can figure out that globe's significance, it'd be him.",logDesc="Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",choiceRewards={{id=16659,qty=1},{id=16660,qty=1},{id=16661,qty=1}}} end
if not DB[825] then DB[825]={id=825,zoneId=14,name="From The Wreckage....",level=8,minLevel=3,giver="Gar'Thok",giverType="NPC",giverId=3139,ender="Gar'Thok",enderType="NPC",enderId=3139,poiX=275,poiY=-4709,wowhead="https://www.wowhead.com/wotlk/quest=825",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep.$b$bIt is no secret that the humans, in alliance with those foul little creatures known as gnomes, have an advanced knowledge of mechanics. We must have a complete understanding of all our potential enemies. And our people will benefit from this new knowledge as well.$b$bSwim through the wreckage, $n, and retrieve for me the tools of the Alliance.",logDesc="Gar'Thok of Razor Hill wants you to retrieve 3 Gnomish Tools from the wreckage off the coast.",choiceRewards={{id=4936,qty=1},{id=4928,qty=1},{id=4935,qty=1}}} end
if not DB[826] then DB[826]={id=826,zoneId=14,name="Zalazane",level=10,minLevel=4,giver="Master Gadrin",giverType="NPC",giverId=3188,ender="Master Gadrin",enderType="NPC",enderId=3188,poiX=-826,poiY=-4921,wowhead="https://www.wowhead.com/wotlk/quest=826",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The witchdoctor Zalazane dwells on the Echo Isles to the east.  They are the isles we once called home.$B$BFrom there he sends his trolls to the mainland, to hex our people and drag more of them under his sway.$B$BHe must be stopped.$B$BDefeat Zalazane and his minions -- former Darkspear trolls, now lost to us.  Bring me his head and I will know his reign of evil is over.",logDesc="Defeat Zalazane.$B$BKill 8 Voodoo Trolls and 8 Hexed Trolls.$B$BBring Zalazane's Head to Gadrin.",choiceRewards={{id=4946,qty=1},{id=4940,qty=1}}} end
if not DB[827] then DB[827]={id=827,zoneId=14,name="Skull Rock",level=12,minLevel=4,giver="Margoz",giverType="NPC",giverId=3208,ender="Margoz",enderType="NPC",enderId=3208,poiX=1102,poiY=-4945,wowhead="https://www.wowhead.com/wotlk/quest=827",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.$B$BBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.$B$BGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.",logDesc="Gather Searing Collars from the cultists in Skull Rock.$B$BBring them to Margoz at his camp.",choiceRewards={{id=4947,qty=1},{id=4939,qty=1},{id=4948,qty=1}}} end
if not DB[828] then DB[828]={id=828,zoneId=14,name="Margoz",level=12,minLevel=4,giver="Orgnil Soulscar",giverType="NPC",giverId=3142,ender="Margoz",enderType="NPC",enderId=3208,rewardNextId=827,poiX=287,poiY=-4725,wowhead="https://www.wowhead.com/wotlk/quest=828",image="assets/images/quests/placeholder.png",xpDiff=1,desc="One of our Shamans, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains - just outside Orgrimmar! - that shelters a large band of Burning Blade cultists.$B$BBefore you go to Skull Rock speak with Margoz.  He is wise and his council is valued.$B$BHe is camped to the northeast, between the coast and Drygulch Ravine.$B$BFollow his advice, but whatever Margoz says, $N, I still want you to crush those cultists!",logDesc="Speak with Margoz."} end
if not DB[829] then DB[829]={id=829,zoneId=14,name="Neeru Fireblade",level=12,minLevel=4,giver="Margoz",giverType="NPC",giverId=3208,ender="Neeru Fireblade",enderType="NPC",enderId=3216,rewardNextId=809,poiX=1102,poiY=-4945,wowhead="https://www.wowhead.com/wotlk/quest=829",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The Searing Collars you brought me are powerful, demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.$B$BTake a searing collar to Neeru Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.$B$BYou may find Neeru in Orgrimmar in the Cleft of Shadow.",logDesc="Bring an Example Collar to Neeru Fireblade in Orgrimmar."} end
if not DB[830] then DB[830]={id=830,zoneId=14,name="The Admiral's Orders",level=7,minLevel=1,ender="Gar'Thok",enderType="NPC",enderId=3139,rewardNextId=831,wowhead="https://www.wowhead.com/wotlk/quest=830",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You open the aged and weathered envelope and discover an official looking document. You recognize the seal of Admiral Proudmoore.$b$bThis looks important. Perhaps Gar'Thok, the commander of Razor Hill, would be interested in having this information.",logDesc="Take Admiral Proudmoore's Orders to Gar'Thok in Razor Hill."} end
if not DB[831] then DB[831]={id=831,zoneId=14,name="The Admiral's Orders",level=7,minLevel=1,giver="Gar'Thok",giverType="NPC",giverId=3139,ender="Vol'jin",enderType="NPC",enderId=10540,poiX=275,poiY=-4709,wowhead="https://www.wowhead.com/wotlk/quest=831",image="assets/images/quests/placeholder.png",xpDiff=5,money=175,desc="Humans cannot be trusted. We fought alongside them with a weary heart, knowing they would betray us one day.$b$bAdmiral Proudmoore's death was not enough to stop his legacy of deceit. The human scum had his plans well laid out before he ever met his demise.$b$bHis reign won't even die with Benedict it seems. Who knows how long it will be before the next waves of Proudmoore's men land upon our shores.$b$bWe need to get these orders to Vol'jin in Orgrimmar immediately! He can be found in Thrall's chamber.",logDesc="Deliver Admiral Proudmoore's Orders to Vol'jin in Thrall's chamber in Orgrimmar."} end
if not DB[832] then DB[832]={id=832,zoneId=14,name="Burning Shadows",level=12,minLevel=4,ender="Neeru Fireblade",enderType="NPC",enderId=3216,wowhead="https://www.wowhead.com/wotlk/quest=832",image="assets/images/quests/placeholder.png",xpDiff=4,desc="<Words emanate from the pendant and into your mind.>$B$BGazz'uz?$B$BGazz'uz...report!$B$BThere is word of your discovery in Skull Rock.  You must prepare for an attack!$B$BGazz'uz, I order you to speak!  Speak or I will make sure Neeru Fireblade knows of your presence, and he will descend on you with swift brutality.$B$BDo not test your skills against Neeru...$B$B...Gazz'uz, are you there...?",logDesc="Take this eye to Neeru Fireblade in Orgrimmar."} end
if not DB[833] then DB[833]={id=833,zoneId=215,name="A Sacred Burial",level=10,minLevel=7,giver="Lorekeeper Raintotem",giverType="NPC",giverId=3233,ender="Lorekeeper Raintotem",enderType="NPC",enderId=3233,poiX=-1150,poiY=-1027,wowhead="https://www.wowhead.com/wotlk/quest=833",image="assets/images/quests/placeholder.png",xpDiff=4,money=250,desc="Only the most valiant tauren are laid to rest at Red Rocks, our sacred burial ground. It is an honor bestowed upon the great warriors who helped found and defend Thunder Bluff and those who have given their lives for the greater good of their tribes and chieftains.$b$bBut it appears a foul menace has made its way onto our holy land. A band of Bristleback Interlopers is ravaging the grave site and I am too old and past my prime to drive them away.$b$bThey must be driven off with force, $n.",logDesc="Lorekeeper Raintotem wants you to kill 8 Bristleback Interlopers at Red Rocks."} end
if not DB[834] then DB[834]={id=834,zoneId=14,name="Winds in the Desert",level=9,minLevel=7,giver="Rezlak",giverType="NPC",giverId=3293,ender="Rezlak",enderType="NPC",enderId=3293,rewardNextId=835,poiX=1000,poiY=-4414,wowhead="https://www.wowhead.com/wotlk/quest=834",image="assets/images/quests/placeholder.png",xpDiff=5,money=300,desc="I'm Rezlak, one of Gazlowe's boys. Boss sent me to help the orcs here in Durotar. Things'd been going good except for the caravans. Can't manage to keep them safe! Makes my job a little harder, you know?$b$bThe last shipment--they promised it'd get through!--was snatched by the Dustwind harpies of...where was it...Razorwind Canyon?$b$bI gotta have those supplies or I'll never get anything done! Follow the big canyon to the south, you'll find the ravine cut right into the west and east sides of the walls.",logDesc="Retrieve 5 Sacks of Supplies and return them to Rezlak near Orgrimmar."} end
if not DB[835] then DB[835]={id=835,zoneId=14,name="Securing the Lines",level=11,minLevel=7,giver="Rezlak",giverType="NPC",giverId=3293,ender="Rezlak",enderType="NPC",enderId=3293,poiX=1000,poiY=-4414,wowhead="https://www.wowhead.com/wotlk/quest=835",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\"$b$bI can't deal with losing all our caravans, so I'm just going to take matters into my own hands. Drygulch Ravine lies through the eastern part of Razorwind Canyon. If we kill all the harpies there, the routes will be safe.$b$bOf course, there was one other thing that Gazlowe taught me, and that's \"You can get anything done for a price.\" So, going to help me out, $n?",logDesc="Kill 12 Dustwind Savages and 8 Dustwind Storm Witches for Rezlak near Drygulch Ravine.",choiceRewards={{id=4932,qty=1},{id=4931,qty=1},{id=4938,qty=1}}} end
if not DB[836] then DB[836]={id=836,zoneId=47,name="Rescue OOX-09/HL!",level=48,minLevel=43,giver="Homing Robot OOX-09/HL",giverType="NPC",giverId=7806,ender="Oglethorpe Obnoticus",enderType="NPC",enderId=7406,poiX=500,poiY=-3475,wowhead="https://www.wowhead.com/wotlk/quest=836",image="assets/images/quests/placeholder.png",xpDiff=8,desc="The gnome's voice crackles once again from the robot:$B$B\"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, some big rocks that obscure visibility! That should be a perfect place, and long enough, to get things online!\"$B$B\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"",logDesc="Escort OOX-09/HL to safety, then report to Oglethorpe Obnoticus in Booty Bay.",choiceRewards={{id=9645,qty=1},{id=9646,qty=1}}} end
if not DB[837] then DB[837]={id=837,zoneId=14,name="Encroachment",level=10,minLevel=6,giver="Gar'Thok",giverType="NPC",giverId=3139,ender="Gar'Thok",enderType="NPC",enderId=3139,poiX=275,poiY=-4709,wowhead="https://www.wowhead.com/wotlk/quest=837",image="assets/images/quests/placeholder.png",xpDiff=4,money=250,desc="When we arrived, the Razormane quilboars possessed much of the land, and proved a thorn in our sides. Through our efforts we have driven out the largest part of their numbers, but still they remain well-fortified in some areas.$b$bIt has gone on long enough, however. For our own protection, we cannot allow the Razormane any hold in our lands. Their camps can be found to the west of here. Look for the brambles and you will find them. Today we drive them from Durotar, tomorrow, perhaps from all of Kalimdor.",logDesc="Kill 4 Razormane Quilboars, 4 Razormane Scouts, 4 Razormane Dustrunners and 4 Razormane Battleguards for Gar'Thok at Razor Hill."} end
if not DB[838] then DB[838]={id=838,zoneId=28,name="Scholomance",level=55,minLevel=55,giver="High Executor Derrington",giverType="NPC",giverId=10837,ender="Apothecary Dithers",enderType="NPC",enderId=11057,rewardNextId=964,poiX=1761,poiY=-723,wowhead="https://www.wowhead.com/wotlk/quest=838",image="assets/images/quests/placeholder.png",xpDiff=1,desc="On the island of Caer Darrow lies Scholomance - a school that serves as a stronghold for the Scourge.  Our enemy dwells within, safely allowed to pursue research that strengthens their power.  A door bars the way, and try as we might no entry is to be had without a proper key.$B$BApothecary Dithers is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your value to me as someone who can get things done; I now entrust this task to you.  Speak with him on this matter.",logDesc="Speak with Apothecary Dithers at the Bulwark, Western Plaguelands."} end
if not DB[839] then DB[839]={id=839,zoneId=0,name="<UNUSED>",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=839",image="assets/images/quests/placeholder.png",xpDiff=1,money=2} end
if not DB[840] then DB[840]={id=840,zoneId=14,name="Conscript of the Horde",level=12,minLevel=10,giver="Takrin Pathseeker",giverType="NPC",giverId=3336,ender="Kargal Battlescar",enderType="NPC",enderId=3337,rewardNextId=842,poiX=272,poiY=-4651,wowhead="https://www.wowhead.com/wotlk/quest=840",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Hmm, you look pretty strong.$B$BListen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance.$B$BTake this recruitment letter to Kargal and see if he'll sign it.",logDesc="Follow the western road from Razor Hill to the Barrens over a bridge.$B$BStop at the orc outpost across the bridge.$B$BGive Kargal Battlescar at the Barrens outpost your recruitment letter."} end
if not DB[841] then DB[841]={id=841,zoneId=440,name="Another Power Source?",level=46,minLevel=38,giver="Chief Engineer Bilgewhizzle",giverType="NPC",giverId=7407,ender="Chief Engineer Bilgewhizzle",enderType="NPC",enderId=7407,poiX=-7187,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=841",image="assets/images/quests/placeholder.png",desc="Let me guess - you didn't get whatever world-ending, nefarious deed you were doing done in time.  No wait, better still... you dropped it in the sand!  Well, whatever the reason, I do have additional power sources I will sell to you.  This time, however, it will cost you ten, YES TEN Wastewander Water Pouches!$B$BTimes are tough all around, $n, and power sources don't grow on trees!  Hrm, but what if they did.  Maybe we could MAKE a power source tree...",logDesc="Bring 10 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan in exchange for another power source.",rewards={{id=8524,qty=1}}} end
if not DB[842] then DB[842]={id=842,zoneId=14,name="Crossroads Conscription",level=12,minLevel=10,giver="Kargal Battlescar",giverType="NPC",giverId=3337,ender="Sergra Darkthorn",enderType="NPC",enderId=3338,poiX=303,poiY=-3686,wowhead="https://www.wowhead.com/wotlk/quest=842",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Take this signed recruitment letter to the Crossroads.$B$BSergra Darkthorn, curse her hide, is in charge there. She's a nasty shaman who will talk your head in circles before she lets you do anything useful. Thrall is convinced she's something special, but I'm not so sure.$B$BYou'll just have to decide for yourself, pup...",logDesc="Follow the western road from Kargal's Far Watch Outpost.$B$BAt the T intersection, turn left and follow the road south. $B$BFind Sergra Darkthorn at the crossing of roads within the Crossroads."} end
if not DB[843] then DB[843]={id=843,zoneId=17,name="Gann's Reclamation",level=23,minLevel=17,giver="Gann Stonespire",giverType="NPC",giverId=3341,ender="Gann Stonespire",enderType="NPC",enderId=3341,rewardNextId=846,poiX=-3590,poiY=-2028,wowhead="https://www.wowhead.com/wotlk/quest=843",image="assets/images/quests/placeholder.png",xpDiff=5,money=1500,desc="In solitude I wander these roads.$b$bThe dwarves of Bael Modan show no respect for my land. Horrendous blasts drive holes deep into the ground as noisy machines rip apart the hills. Lands which once served as home and provider to my tribe are now riddled with destructive dwarves.$b$bAttempts at reaching a diplomatic resolution have failed. Now is the time for decisive action.$b$bDrive the dwarves from the Bael Modan excavation by force and bring to me the journal of their leader, Prospector Khazgorm.",logDesc="Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.$b$bBring Khazgorm's Journal to Gann Stonespire."} end
if not DB[844] then DB[844]={id=844,zoneId=17,name="Plainstrider Menace",level=12,minLevel=10,giver="Sergra Darkthorn",giverType="NPC",giverId=3338,ender="Sergra Darkthorn",enderType="NPC",enderId=3338,rewardNextId=845,poiX=-482,poiY=-2670,wowhead="https://www.wowhead.com/wotlk/quest=844",image="assets/images/quests/placeholder.png",xpDiff=5,money=500,desc="Your first prey will be easy.$B$BThe plainstriders to the east have been harassing our food supplies and have become a nuisance.$B$BPut down the plainstriders and return to me with their beaks.",logDesc="Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads."} end
if not DB[845] then DB[845]={id=845,zoneId=17,name="The Zhevra",level=13,minLevel=10,giver="Sergra Darkthorn",giverType="NPC",giverId=3338,ender="Sergra Darkthorn",enderType="NPC",enderId=3338,rewardNextId=903,poiX=-482,poiY=-2670,wowhead="https://www.wowhead.com/wotlk/quest=845",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="The zhevra, although not the fiercest beast in the Barrens, are a shade tougher than the plainstriders.  Don't worry -- we'll send you against bigger prey in good time, but for now your teeth could use a little more cutting.$B$BHunt the zhevra to the north and south, and collect their hooves.  Bring them to me and perhaps we'll next send you against something tougher.",logDesc="Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads."} end
if not DB[846] then DB[846]={id=846,zoneId=17,name="Revenge of Gann",level=26,minLevel=17,giver="Gann Stonespire",giverType="NPC",giverId=3341,ender="Gann Stonespire",enderType="NPC",enderId=3341,rewardNextId=849,poiX=-3590,poiY=-2028,wowhead="https://www.wowhead.com/wotlk/quest=846",image="assets/images/quests/placeholder.png",xpDiff=5,money=2000,desc="It is clear the prospector depended on explosives and those noisy vehicles to rip the ground apart. We can expect a new foreman to take over soon.$b$bI want to give the dwarves a taste of their own medicine. According to these plans if we combine nitroglycerin with wood pulp and sodium nitrate we can create an explosive charge. The rifleman, soldiers and officers in the Keep are known to have the supplies.$b$bCollect these items and bring them to me. I will fashion a charge that the dwarves won't forget!",logDesc="Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate."} end
if not DB[847] then DB[847]={id=847,zoneId=45,name="Guile of the Raptor",level=37,minLevel=29,giver="Gor'mul",giverType="NPC",giverId=2792,ender="Tor'gan",enderType="NPC",enderId=2706,poiX=-948,poiY=-3482,wowhead="https://www.wowhead.com/wotlk/quest=847",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This... this power.... Is this the power of the shamans that Tor'gan tried to show me? I must say, it is interesting. Tell Tor'gan that he has convinced me... for the time being. I will listen to what he has to say.",logDesc="Speak with Tor'gan at Hammerfall in Arathi Highlands.",rewards={{id=4546,qty=1}}} end
if not DB[848] then DB[848]={id=848,zoneId=17,name="Fungal Spores",level=15,minLevel=10,giver="Apothecary Helbrim",giverType="NPC",giverId=3390,ender="Apothecary Helbrim",enderType="NPC",enderId=3390,poiX=-425,poiY=-2590,wowhead="https://www.wowhead.com/wotlk/quest=848",image="assets/images/quests/placeholder.png",xpDiff=5,money=700,desc="The oases of the Barrens hide a mystery.  Life energy flows from their waters, invigorating the plants and beasts that drink it.$B$BInvigorating, and altering.$B$BThere is a mushroom that grows near these oases.  Its spores hold properties that we, the apothecaries of Lordaeron, find useful.$B$BBring me these spores and you will earn our gratitude.",logDesc="Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads."} end
if not DB[849] then DB[849]={id=849,zoneId=17,name="Revenge of Gann",level=26,minLevel=17,giver="Gann Stonespire",giverType="NPC",giverId=3341,ender="Gann Stonespire",enderType="NPC",enderId=3341,poiX=-3590,poiY=-2028,wowhead="https://www.wowhead.com/wotlk/quest=849",image="assets/images/quests/placeholder.png",xpDiff=5,money=2000,desc="Following Khazgorm's plans it should be no problem to fashion an explosive charge$b$bAh, there we go.$b$bNow, $n, I am going to entrust you with a special task. Take this explosive stick and use it to blow up the flying machine at Bael Modan.$b$bNot only is the flying machine a key part of the site's infrastructure it also serves as a weapon of war. More importantly it is an icon of power and an insult to the memory of my tribe.$b$bMake me proud by completing this heroic task and you shall be rewarded.",logDesc="Destroy the flying machine at Bael Modan and return to Gann Stonespire.",rewards={{id=5313,qty=1}}} end
if not DB[850] then DB[850]={id=850,zoneId=17,name="Kolkar Leaders",level=16,minLevel=11,giver="Regthar Deathgate",giverType="NPC",giverId=3389,ender="Regthar Deathgate",enderType="NPC",enderId=3389,poiX=-307,poiY=-1972,wowhead="https://www.wowhead.com/wotlk/quest=850",image="assets/images/quests/placeholder.png",xpDiff=4,money=800,desc="The centaurs have plagued the Tauren for years.  And recently, the Kolkar centaurs of the Barrens have grown into a real threat.  Normally they were disorganized in these lands, but new leaders have risen among them.  Rallying them.$B$BTo preserve our holdings here, these centaur leaders must be destroyed.$B$BBring me the head of Barak Kodobane.  He camps near the Forgotten Pools to the north.$B$BDefeat him, then return to me.",logDesc="Bring Barak's Head to Regthar Deathgate, west of the Crossroads."} end
if not DB[851] then DB[851]={id=851,zoneId=17,name="Verog the Dervish",level=18,minLevel=11,giver="Regthar Deathgate",giverType="NPC",giverId=3389,ender="Regthar Deathgate",enderType="NPC",enderId=3389,rewardNextId=852,poiX=-307,poiY=-1972,wowhead="https://www.wowhead.com/wotlk/quest=851",image="assets/images/quests/placeholder.png",xpDiff=4,money=1000,desc="The centaur Verog the Dervish wanders the Barrens, and will be difficult to find.  But he is based at the centaur command tent at the Stagnant Oasis to the southeast.  It may be possible to draw him to you.$B$BTravel to the Stagnant Oasis to the southeast and attack centaur near the command tent.  It will be dangerous, but if you can kill enough centaur then they should raise an alarm.  And Verog will come.$B$BBring me his head and I will place it with Barak Kodobane's.",logDesc="Bring Verog's Head to Regthar Deathgate, west of the Crossroads."} end
if not DB[852] then DB[852]={id=852,zoneId=17,name="Hezrul Bloodmark",level=19,minLevel=11,giver="Regthar Deathgate",giverType="NPC",giverId=3389,ender="Regthar Deathgate",enderType="NPC",enderId=3389,poiX=-307,poiY=-1972,wowhead="https://www.wowhead.com/wotlk/quest=852",image="assets/images/quests/placeholder.png",xpDiff=4,money=800,desc="Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens.  He is fierce, brutal and cunning.  Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us.$B$BSo kill him.  As with Barak and Verog, bring me Hezrul's Head.$B$BHe leads his people from the Lushwater Oasis, to the south.",logDesc="Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads.",rewards={{id=5351,qty=1}}} end
if not DB[853] then DB[853]={id=853,zoneId=17,name="Apothecary Zamah",level=15,minLevel=10,giver="Apothecary Helbrim",giverType="NPC",giverId=3390,ender="Apothecary Zamah",enderType="NPC",enderId=3419,poiX=-425,poiY=-2590,wowhead="https://www.wowhead.com/wotlk/quest=853",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I have rendered the spores you gave me into an emulsion.  I must now send it to my associate, Apothecary Zamah.  If you were to carry this to her, she can offer you something from our stores of alchemical goods.$B$BShe is in the Pools of Vision, a cave beneath the shamans of Thunder Bluff.  The path to this cave is well hidden, but you may find it on the Spirit Rise bluff.$B$BDo hurry.  This emulsion will maintain its potency for only a short time, and must be resealed and processed before then.",logDesc="Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up.",rewards={{id=5340,qty=1}},choiceRewards={{id=2458,qty=4},{id=2457,qty=4},{id=2456,qty=3},{id=2459,qty=2}}} end
if not DB[854] then DB[854]={id=854,zoneId=215,name="Journey to the Crossroads",level=12,minLevel=9,giver="Kirge Sternhorn",giverType="NPC",giverId=3418,ender="Thork",enderType="NPC",enderId=3429,poiX=-2347,poiY=-1925,wowhead="https://www.wowhead.com/wotlk/quest=854",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I have foreseen your arrival, young $c. Though perhaps you are not so young anymore.$B$BI think that it is time for you to move deeper into this land. I can sense that you are destined for great things.$B$BIt is the Crossroads that you must seek out, for our lives with the orcs have become intertwined and they need assistance. Continue down this road towards the east and follow it north to the Crossroads. Find Thork within its walls, he has the Earthmother's blessing.",logDesc="Speak with Thork at the Crossroads in the Barrens."} end
if not DB[855] then DB[855]={id=855,zoneId=17,name="Centaur Bracers",level=14,minLevel=9,giver="Regthar Deathgate",giverType="NPC",giverId=3389,ender="Regthar Deathgate",enderType="NPC",enderId=3389,poiX=-307,poiY=-1972,wowhead="https://www.wowhead.com/wotlk/quest=855",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops.  And so, I have a bounty task for you.$B$BWhile in Kolkar territories, slay their warriors and collect centaur bracers.  Return when you have a heap of bracers and the Horde will reward you well.",logDesc="Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads.",choiceRewards={{id=5346,qty=1},{id=5344,qty=1},{id=5345,qty=1}}} end
if not DB[856] then DB[856]={id=856,zoneId=0,name="<UNUSED>",level=12,minLevel=9,wowhead="https://www.wowhead.com/wotlk/quest=856",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Though you have reached the Barrens, your journey is not complete. You must continue on to the Crossroads, where you are needed most.$B$BFollow the road as you were, and turn left where the path gives you the choice. Follow it North until you see the walls of the Crossroads.$B$BJust before you enter, you should see the Ancestral Sage, he will have words of wisdom for you.",logDesc="Continue down the road from Camp Taurajo.$B$BTurn left at the T intersection and continue North.$B$BFollow the path to the Ancestral Sage outside the Crossroads."} end
if not DB[857] then DB[857]={id=857,zoneId=17,name="The Tear of the Moons",level=30,minLevel=22,giver="Feegly the Exiled",giverType="NPC",giverId=3421,ender="Feegly the Exiled",enderType="NPC",enderId=3421,poiX=-4218,poiY=-2341,wowhead="https://www.wowhead.com/wotlk/quest=857",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="The power was mine! In my very hands! And I want it back! Back I say!$b$bThose dirty excavators uncovered it... so beautiful it was. Deemed the Tear of the Moons, it was the first great discovery we made at Bael Modan.$b$bIt should have been mine! Mine I say!$b$bGeneral Twinbraid grew jealous of the power it gave me. He locked it away in the Keep. Called it cursed, he did! The fool!$b$bOthers wanted it and they had to be stopped! That fiend Twinbraid drove me off.$b$bNow I want it back. Back I say!",logDesc="Feegly the Exiled wants you to retrieve for him the Tear of the Moons."} end
if not DB[858] then DB[858]={id=858,zoneId=17,name="Ignition",level=18,minLevel=13,giver="Wizzlecrank's Shredder",giverType="NPC",giverId=3439,ender="Wizzlecrank's Shredder",enderType="NPC",enderId=3439,poiX=1109,poiY=-3104,wowhead="https://www.wowhead.com/wotlk/quest=858",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I don't suppose Sputtervalve sent you? I'm in a bind here. I hopped in without realizing that I need a key to unlock the shredder's movement column. One of the other shredder operators asked me if everything was okay, and I panicked! Instead of telling him that I was missing my key, I told him there was some sort of mechanical problem.$b$bWe need to get out of here on the double! Go up to the control room at the top of the derrick, the supervisor should have a key for this shredder.$b$bHelp me out here!",logDesc="Get the Ignition Key and bring it to Wizzlecrank."} end
if not DB[859] then DB[859]={id=859,zoneId=17,name="<UNUSED>",level=18,minLevel=13,wowhead="https://www.wowhead.com/wotlk/quest=859",image="assets/images/quests/placeholder.png"} end
if not DB[860] then DB[860]={id=860,zoneId=17,name="Sergra Darkthorn",level=10,minLevel=10,giver="Melor Stonehoof",giverType="NPC",giverId=3441,ender="Sergra Darkthorn",enderType="NPC",enderId=3338,rewardNextId=844,poiX=-1413,poiY=-126,wowhead="https://www.wowhead.com/wotlk/quest=860",image="assets/images/quests/placeholder.png",xpDiff=1,desc="If you wish to walk the hunter's path, then your journey leads to the Barrens.  Its beasts are strong-willed and fierce.  You will learn much by hunting there, and your spirit will grow.$B$BSpeak with Sergra Darkthorn.  She will be your first guide in the Barrens.$B$BSergra is at the Crossroads.  To reach her, travel east from Bloodhoof Village into the Barrens, then north as the road forks.  And have care as you travel--the Barrens holds great danger for the unprepared and unwary.",logDesc="Speak with Sergra Darkthorn at the Crossroads in the Barrens."} end
if not DB[861] then DB[861]={id=861,zoneId=215,name="The Hunter's Way",level=10,minLevel=10,giver="Skorn Whitecloud",giverType="NPC",giverId=3052,ender="Melor Stonehoof",enderType="NPC",enderId=3441,poiX=-2336,poiY=-354,wowhead="https://www.wowhead.com/wotlk/quest=861",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You are eager to explore, I can tell.  I too had the lust to wander, once...$B$BWander, and hunt.  For hunting is a Tauren's greatest honor.$B$BIf you truly wish to follow the ways of the hunter, then Melor Stonehoof can show you the path.  He is in Thunder Bluff, on the Hunter's Rise.$B$BAnd to show him your skill and resolve, bring him the claws of the flatland prowlers of Mulgore.  They are tough and cunning -- fitting prey for a young $c on the hunter's path.",logDesc="Bring 4 Flatland Prowler Claws to Melor Stonehoof in Thunder Bluff."} end
if not DB[862] then DB[862]={id=862,zoneId=-304,name="Dig Rat Stew",level=23,minLevel=15,giver="Grub",giverType="NPC",giverId=3443,ender="Grub",enderType="NPC",enderId=3443,poiX=-535,poiY=-2982,wowhead="https://www.wowhead.com/wotlk/quest=862",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A $c like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long.$b$bTell you what, I'll fix you up a nice stew. Just need a few dig rats.$b$bSeems those filthy dwarves at Bael Modan are overrun with everyone's favorite feast. Now head on down south to Bael Modan and bring me back some dig rats.$b$bYou can't call yourself a seasoned adventurer until you've spent some time killing rats! Haw!",logDesc="Bring 8 Dig Rats to Grub east of the Crossroads.",rewards={{id=5487,qty=1},{id=5478,qty=5},{id=10919,qty=1}}} end
if not DB[863] then DB[863]={id=863,zoneId=17,name="The Escape",level=18,minLevel=13,giver="Wizzlecrank's Shredder",giverType="NPC",giverId=3439,ender="Sputtervalve",enderType="NPC",enderId=3442,poiX=1109,poiY=-3104,wowhead="https://www.wowhead.com/wotlk/quest=863",image="assets/images/quests/placeholder.png",xpDiff=6,money=2000,desc="I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?",logDesc="Protect Wizzlecrank and the stolen goblin shredder on the way to Sputtervalve in Ratchet.",choiceRewards={{id=5326,qty=1},{id=5327,qty=1}}} end
if not DB[864] then DB[864]={id=864,zoneId=1497,name="Return to Apothecary Zinge",level=46,minLevel=38,giver="Chief Engineer Bilgewhizzle",giverType="NPC",giverId=7407,ender="Apothecary Zinge",enderType="NPC",enderId=5204,poiX=-7187,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=864",image="assets/images/quests/placeholder.png",xpDiff=6,money=13000,desc="\"Here you go, the power source is safely removed and the data is preserved.  Well, safe journeys and all that.  Hope the nefarious science experiment worked out for you and all.\"$B$BThe goblin turns away from you to attend to the demands of the Gadgetzan Water Company.  You secure the sealed testing kit for the journey back to the Undercity.  Apothecary Zinge waits for you and the sealed field testing kit there.",logDesc="Bring the Sealed Field Testing Kit to Apothecary Zinge in the Undercity.",choiceRewards={{id=9634,qty=1},{id=9635,qty=1},{id=11502,qty=1}}} end
if not DB[865] then DB[865]={id=865,zoneId=17,name="Raptor Horns",level=18,minLevel=13,giver="Mebok Mizzyrix",giverType="NPC",giverId=3446,ender="Mebok Mizzyrix",enderType="NPC",enderId=3446,poiX=-929,poiY=-3697,wowhead="https://www.wowhead.com/wotlk/quest=865",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The raptors of the Barrens are smarter than raptors in other lands.  And I think all that smarts is hiding in their horns!  If so, then I could grind their horns into powder and use it to make \"smart drinks.\"  I could sell them for a fortune!!!$B$BAnd you can help me.  Find me intact raptor horns from sunscale scytheclaws.  They roam in the southern Barrens, and in the northern Barrens near the border of Ashenvale Forest.",logDesc="Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet.",rewards={{id=5342,qty=5},{id=5343,qty=1}}} end
if not DB[866] then DB[866]={id=866,zoneId=-24,name="Root Samples",level=16,minLevel=9,giver="Mebok Mizzyrix",giverType="NPC",giverId=3446,ender="Mebok Mizzyrix",enderType="NPC",enderId=3446,poiX=-929,poiY=-3697,wowhead="https://www.wowhead.com/wotlk/quest=866",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="The herbs of the Barrens are not quite like herbs in other lands.  Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different.$B$BI want to study those differences... to see if they're exploitable!$B$BIf you are skilled in herbalism, then gather root samples off the herbs you find in the Barrens.  Bring back these samples so that I may compare them with herbs from other regions.",logDesc="Bring 8 Root Samples to Mebok Mizzyrix in Ratchet.",rewards={{id=5341,qty=1}}} end
if not DB[867] then DB[867]={id=867,zoneId=17,name="Harpy Raiders",level=15,minLevel=12,giver="Darsok Swiftdagger",giverType="NPC",giverId=3449,ender="Darsok Swiftdagger",enderType="NPC",enderId=3449,rewardNextId=875,poiX=-475,poiY=-2608,wowhead="https://www.wowhead.com/wotlk/quest=867",image="assets/images/quests/placeholder.png",xpDiff=5,money=700,desc="The blasted harpies have been ravaging our caravan supplies for too long. It's time we slit a few of their throats and diminished their numbers.$B$BI've been snooping around their nests and figured out who leads who. The most devastating attack will destroy a good section of their lower chain of command and then we can work our way to the top.$B$BI'll start you off slow, take out Witchwing Harpies and Witchwing Roguefeathers in the Northwest and bring me 8 Witchwing talons. That should be a good start...",logDesc="Collect 8 Witchwing talons.$B$BReturn them to Darsok Swiftdagger at the Crossroads."} end
if not DB[868] then DB[868]={id=868,zoneId=17,name="Egg Hunt",level=22,minLevel=17,giver="Korran",giverType="NPC",giverId=3428,ender="Korran",enderType="NPC",enderId=3428,poiX=-389,poiY=-2552,wowhead="https://www.wowhead.com/wotlk/quest=868",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hey, $N. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar.$B$BOne object of my studies are the insect-like creatures found to the south in the Field of Giants. We know little of the creatures, so I be makin' it a point to discover more. They seem to have intelligence to them, more so than any normal animal.$B$BTake this digging claw and collect some of the creatures' eggs from their mounds, but be careful: if alerted, they will attack you.",logDesc="Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads.",choiceRewards={{id=6503,qty=1},{id=6502,qty=1}}} end
if not DB[869] then DB[869]={id=869,zoneId=17,name="Raptor Thieves",level=13,minLevel=9,giver="Gazrog",giverType="NPC",giverId=3464,ender="Gazrog",enderType="NPC",enderId=3464,rewardNextId=3281,poiX=-436,poiY=-2639,wowhead="https://www.wowhead.com/wotlk/quest=869",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="Not long ago, a shipment of silver was stolen from our guard tower.  It was meant as payroll to the Crossroads' guards, and we want that silver back.$B$BThe strange thing is... we caught one of the thieves on the night of the theft.  And... it was a raptor!  Unbelievable!$B$BI don't know what raptors would want with silver.  But I don't care -- I want the raptors dead so they won't steal from us again!$B$BHunt raptors in the Barrens.  Collect for me their heads!",logDesc="Bring 12 Raptor Heads to Gazrog at the Crossroads."} end
if not DB[870] then DB[870]={id=870,zoneId=17,name="The Forgotten Pools",level=13,minLevel=10,giver="Tonga Runetotem",giverType="NPC",giverId=3448,ender="Tonga Runetotem",enderType="NPC",enderId=3448,rewardNextId=877,poiX=-545,poiY=-2673,wowhead="https://www.wowhead.com/wotlk/quest=870",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Long ago, the Barrens was a lush place, teeming with life.  But war and cataclysm raged across the land, scorching it and leaving a dry husk.  Such is the way of things, and it saddens my heart.$B$BBut within the past few years, new oases have formed in the Barrens, and life stirs.  And deep down, we druids sense a power leaking its way to the surface.$B$BWe must find its source.  Travel to the Forgotten Pools, northwest of the Crossroads.  Search its waters for a source of power, then return here.",logDesc="Report back to Tonga Runetotem with your findings."} end
if not DB[871] then DB[871]={id=871,zoneId=17,name="Disrupt the Attacks",level=12,minLevel=9,giver="Thork",giverType="NPC",giverId=3429,ender="Thork",enderType="NPC",enderId=3429,poiX=-473,poiY=-2596,wowhead="https://www.wowhead.com/wotlk/quest=871",image="assets/images/quests/placeholder.png",xpDiff=5,desc="All the quilboars are our enemies, $N. Some just prove to be more of a nuisance than others.$B$BThe Razormane tribe has been attacking our supply lines from Durotar, causing us no end of annoyance. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us.$B$BStart in the northeast towards Durotar. You can always tell their dens from the huge thorny vines that come up from the earth. Seek them out, and slay them.",logDesc="Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads."} end
if not DB[872] then DB[872]={id=872,zoneId=17,name="The Disruption Ends",level=15,minLevel=9,giver="Thork",giverType="NPC",giverId=3429,ender="Thork",enderType="NPC",enderId=3429,poiX=-473,poiY=-2596,wowhead="https://www.wowhead.com/wotlk/quest=872",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One of my scouts witnessed an attack on a caravan from Durotar, $N. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout. He was seen northeast of here, just south of the road from Durotar. If the threat is to be ended, then Kreenig must die.$B$BTo be sure the attacks cease, though, I say we add insult to their injury. Kill Kreenig along with more of their tribe, and return to me when you have his tusk.",logDesc="Kill 8 Razormane Geomancers, 8 Razormane Defenders, and Kreenig Snarlsnout.$B$BThen bring Kreenig Snarlsnout's Tusk to Thork at the Crossroads.",choiceRewards={{id=5275,qty=1},{id=5328,qty=1}}} end
if not DB[873] then DB[873]={id=873,zoneId=17,name="Isha Awak",level=27,minLevel=10,giver="Mahren Skyseer",giverType="NPC",giverId=3388,ender="Mahren Skyseer",enderType="NPC",enderId=3388,poiX=-1351,poiY=-4048,wowhead="https://www.wowhead.com/wotlk/quest=873",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The grand Isha Awak is lord of these waters.  Great is his strength, and solemn his pride.  The humans on the coast fear him, for he has consumed many of their number.$B$BBut I do not fear him.  I am grateful he is here.  He is a worthy challenge, and honorable prey.$B$BIf you are ready, then swim out and search for Isha Awak, the Deep Doom.$B$BHis spirit dwells in his heart, and to hear its beat is to know your fate.",logDesc="Bring the Heart of Isha Awak to Mahren Skyseer.",rewards={{id=5355,qty=1}},choiceRewards={{id=5356,qty=1},{id=5357,qty=1}}} end
if not DB[874] then DB[874]={id=874,zoneId=17,name="Mahren Skyseer",level=27,minLevel=9,giver="Jorn Skyseer",giverType="NPC",giverId=3387,ender="Mahren Skyseer",enderType="NPC",enderId=3388,rewardNextId=873,poiX=-2383,poiY=-1923,wowhead="https://www.wowhead.com/wotlk/quest=874",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You have hunted the beasts of the Barrens.  Your spirit is strong.  But a hunter must always be prepared.  A true hunter can stalk prey down any path.  Mountains and swamps will not sway $ghim:her;.$B$BNot even the sea.$B$BFind my sister, Mahren.  She hunts the great water beasts along the coast.  She will be your teacher in their ways.$B$BBut be wary in your search for her, for the Barrens' coast is held by humans.",logDesc="Speak with Mahren Skyseer."} end
if not DB[875] then DB[875]={id=875,zoneId=17,name="Harpy Lieutenants",level=16,minLevel=12,giver="Darsok Swiftdagger",giverType="NPC",giverId=3449,ender="Darsok Swiftdagger",enderType="NPC",enderId=3449,rewardNextId=876,poiX=-475,poiY=-2608,wowhead="https://www.wowhead.com/wotlk/quest=875",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="Hahaha, $n. Back for more? Good, I like to hear that.$B$BThis time I want you to assassinate some of the harpy lieutenants in the Dry Hills. Only Witchwing Slayers can be lieutenants, and you can tell them apart by the rings they carry. They are a nasty bunch, but they lead some of the underlings in that area. Taking out 6 of them will be a decisive strike against their matriarchy.$B$BMake sure they die painfully, $n. We want those harpy wenches to know the idiocy of picking fights with the Horde.",logDesc="Collect 6 Harpy Lieutenant Rings from Witchwing Slayers and return them to Darsok Swiftdagger at the Crossroads."} end
if not DB[876] then DB[876]={id=876,zoneId=17,name="Serena Bloodfeather",level=20,minLevel=12,giver="Darsok Swiftdagger",giverType="NPC",giverId=3449,ender="Darsok Swiftdagger",enderType="NPC",enderId=3449,poiX=-475,poiY=-2608,wowhead="https://www.wowhead.com/wotlk/quest=876",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You did so well with the lieutenants and underlings that I'd like you to do one last thing for me.$B$BSerena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago. Apparently, these attacks on the Horde caravans are revenge for her sister's death.$B$BI need you to slit her throat and bring me back her head. I want to place it on the next caravan we send out... Give those harpies something to think about.",logDesc="Slay Serena Bloodfeather and return her head to Darsok Swiftdagger at the Crossroads.",choiceRewards={{id=5321,qty=1},{id=5279,qty=1},{id=5318,qty=1}}} end
if not DB[877] then DB[877]={id=877,zoneId=17,name="The Stagnant Oasis",level=16,minLevel=10,giver="Tonga Runetotem",giverType="NPC",giverId=3448,ender="Tonga Runetotem",enderType="NPC",enderId=3448,rewardNextId=880,poiX=-545,poiY=-2673,wowhead="https://www.wowhead.com/wotlk/quest=877",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Like the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens.  If so, then perhaps the fissures are the oases' source of life.$B$BWe must test this.$B$BHere, take these seeds.  They are dead and infertile, but take them to the Stagnant Oasis to the southeast.  If there is a fissure there, then place the seeds within it...and observe.",logDesc="Return to Tonga at The Crossroads, after investigating the Stagnant Oasis."} end
if not DB[878] then DB[878]={id=878,zoneId=17,name="Tribes at War",level=21,minLevel=14,giver="Mangletooth",giverType="NPC",giverId=3430,ender="Mangletooth",enderType="NPC",enderId=3430,poiX=-2392,poiY=-1891,wowhead="https://www.wowhead.com/wotlk/quest=878",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You must strike my enemies. <snort> You must help Mangletooth and the Razormane by weakening the Bristlebacks. Both tribes are very spiritual--tied to the earth and its power. <snort> It gives us strength in all things... especially war.$B$BIf you want to find out who really causes Thork <snort> and the Horde such anguish, then help Mangletooth! You attack the spiritual leaders of the Bristlebacks to the north; weaken them so the Razormanes can defeat them and rule the Barrens.",logDesc="Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens."} end
if not DB[879] then DB[879]={id=879,zoneId=17,name="Betrayal from Within",level=25,minLevel=17,giver="Mangletooth",giverType="NPC",giverId=3430,ender="Mangletooth",enderType="NPC",enderId=3430,rewardNextId=906,poiX=-2392,poiY=-1891,wowhead="https://www.wowhead.com/wotlk/quest=879",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Three of my tribe came out of the Kraul to lead the raids against the Horde, $r. <snort> They are ruthless and cunning, and if you defeat them, then your Crossroads and even most of the Barrens will learn peace... <snort> at least from the Razormane tribe. <snort>$B$BNak, Kuz, and Lok Orcbane are the ones you seek. They are far to the south  of the Barrens. One is a spell caster, another a tracker, and their leader, the one called Orcbane, <snort> a warrior. Kill them, $r, like they have killed me.",logDesc="Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens."} end
if not DB[880] then DB[880]={id=880,zoneId=17,name="Altered Beings",level=16,minLevel=10,giver="Tonga Runetotem",giverType="NPC",giverId=3448,ender="Tonga Runetotem",enderType="NPC",enderId=3448,poiX=-545,poiY=-2673,wowhead="https://www.wowhead.com/wotlk/quest=880",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="Your findings are incredible, $N.  These oases hold properties that must come from an outside source.  Or perhaps an inside one.$B$BI want to know how these fissures are affecting the beasts who drink from the oases' water.$B$BHunt oasis snapjaws at the Lushwater and Stagnant Oases.  Bring me their shells so I may examine them.",logDesc="Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads."} end
if not DB[881] then DB[881]={id=881,zoneId=17,name="Echeyakee",level=16,minLevel=10,giver="Sergra Darkthorn",giverType="NPC",giverId=3338,ender="Sergra Darkthorn",enderType="NPC",enderId=3338,rewardNextId=905,poiX=-482,poiY=-2670,wowhead="https://www.wowhead.com/wotlk/quest=881",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Whitemist, Echeyakee in the Tauren tongue, is the king of the savannah cats.  He hunts with such stealth, they say he's like a thin, white mist on the earth.  And he kills so fast his prey have no time for fear, or pain.$B$BThe Tauren say he is both mercy and death.$B$BYou will learn if that's true, for I now set you on the path to hunt Echeyakee.  His lair is northeast of the Crossroads, among the bones of giant Kodo$B$BGo.  Blow this horn when you reach his lair.  Blow the horn, and he will come.",logDesc="Bring Echeyakee's Hide to Sergra Darkthorn at the Crossroads."} end
if not DB[882] then DB[882]={id=882,zoneId=17,name="Ishamuhale",level=19,minLevel=10,giver="Jorn Skyseer",giverType="NPC",giverId=3387,ender="Jorn Skyseer",enderType="NPC",enderId=3387,rewardNextId=907,poiX=-2383,poiY=-1923,wowhead="https://www.wowhead.com/wotlk/quest=882",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Ishamuhale, Speartooth, is the fiercest sunscale raptor of the Barrens.  He does not hunt for sport, nor for food.  He hunts because hunting is his passion.  He kills because it is his nature to kill.$B$BAnd you will learn of his nature, $N, for your path now follows the taloned tracks of Ishamuhale.$B$BBegin the hunt.  Slay his favorite prey, a zhevra, then bring its carcass to the dead tree northwest of Ratchet.  Ishamuhale will smell the carcass and be drawn to it.$B$BBe ready when he comes.",logDesc="Bring Ishamuhale's Fang to Jorn at Camp Taurajo."} end
if not DB[883] then DB[883]={id=883,zoneId=17,name="Lakota'mani",level=22,minLevel=10,ender="Jorn Skyseer",enderType="NPC",enderId=3387,wowhead="https://www.wowhead.com/wotlk/quest=883",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The Hoof of Lakota'mani is a symbol of the strength of the great kodo.",logDesc="Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo."} end
if not DB[884] then DB[884]={id=884,zoneId=17,name="Owatanka",level=24,minLevel=10,ender="Jorn Skyseer",enderType="NPC",enderId=3387,wowhead="https://www.wowhead.com/wotlk/quest=884",image="assets/images/quests/placeholder.png",xpDiff=4,desc="When touched, sparks fly from the tailspike of Owatanka.",logDesc="Bring Owatanka's Tailspike to Jorn at Camp Taurajo."} end
if not DB[885] then DB[885]={id=885,zoneId=17,name="Washte Pawne",level=25,minLevel=10,ender="Jorn Skyseer",enderType="NPC",enderId=3387,wowhead="https://www.wowhead.com/wotlk/quest=885",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The feather of Washte Pawne is painful to the touch.",logDesc="Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo."} end
if not DB[886] then DB[886]={id=886,zoneId=17,name="The Barrens Oases",level=10,minLevel=10,giver="Arch Druid Hamuul Runetotem",giverType="NPC",giverId=5769,ender="Tonga Runetotem",enderType="NPC",enderId=3448,rewardNextId=870,poiX=-1049,poiY=-304,wowhead="https://www.wowhead.com/wotlk/quest=886",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The druids of Thunder Bluff sense a strange power leaking into the Barrens, east of Mulgore.$B$BTonga Runetotem was sent to discover the source of this power, but we fear he will need aid.$B$BTravel to the Barrens and speak with Tonga.  He will be at the Crossroads.  To reach there, take the road east out of Bloodhoof village.  Enter the Barrens, then turn north when the road forks.  Continue north and  you will find the Crossroads.$B$BAnd do not leave the road, $N, for the Barrens is a harsh land.",logDesc="Speak with Tonga Runetotem at the Crossroads in the Barrens."} end
if not DB[887] then DB[887]={id=887,zoneId=17,name="Southsea Freebooters",level=14,minLevel=9,giver="Gazlowe",giverType="NPC",giverId=3391,ender="Gazlowe",enderType="NPC",enderId=3391,rewardNextId=890,poiX=-836,poiY=-3729,wowhead="https://www.wowhead.com/wotlk/quest=887",image="assets/images/quests/placeholder.png",xpDiff=4,money=500,desc="I sure wish Vice Admiral Grezzlik did a better job of keeping the seas safe for our trading vessels. With all the gold the trade princes have poured into the Trade Fleets, it ticks me off to see so many pirates running willy-nilly, raiding my ships and stealing my goods!$b$bI heard that the Southsea Freebooters have set up a camp just south of here. They've been a real thorn in my side and if Grezzlik won't take care of them, well, maybe you can help me get rid of them.",logDesc="Kill 12 Southsea Brigands and 6 Southsea Cannoneers for Gazlowe in Ratchet."} end
if not DB[888] then DB[888]={id=888,zoneId=17,name="Stolen Booty",level=16,minLevel=9,giver="Gazlowe",giverType="NPC",giverId=3391,ender="Gazlowe",enderType="NPC",enderId=3391,poiX=-836,poiY=-3729,wowhead="https://www.wowhead.com/wotlk/quest=888",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have!$b$bAs you see, my observatory is ready to go, but it needs the smaller of the two lenses. The first arrived by caravan from Durotar, but the second was bound by ship, and never arrived. Also, I never got my boot shipment from Drizzlik in Booty Bay!$b$bHead down to the pirate camp and see if you can find them.",logDesc="Retrieve the Shipment of Boots and Telescopic Lens for Gazlowe in Ratchet.",choiceRewards={{id=5337,qty=1},{id=5320,qty=1}}} end
if not DB[889] then DB[889]={id=889,zoneId=17,name="Spirit of the Wind",level=20,minLevel=14,giver="Mangletooth",giverType="NPC",giverId=3430,ender="Mangletooth",enderType="NPC",enderId=3430,poiX=-2392,poiY=-1891,wowhead="https://www.wowhead.com/wotlk/quest=889",image="assets/images/quests/placeholder.png"} end
if not DB[890] then DB[890]={id=890,zoneId=17,name="The Missing Shipment",level=14,minLevel=9,giver="Gazlowe",giverType="NPC",giverId=3391,ender="Wharfmaster Dizzywig",enderType="NPC",enderId=3453,rewardNextId=892,poiX=-836,poiY=-3729,wowhead="https://www.wowhead.com/wotlk/quest=890",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I've been waiting forever for my last shipment of goods from Booty Bay! I'm pretty sure that it must have been stolen by the Freebooters, but just to make sure, will you go down to the dockside and ask Dizzywig if my goods were already put into my warehouse without my knowledge?$b$bHere, take my ledger down to Dizzywig and have him double check my inventory records against his logs.",logDesc="Bring Gazlowe's Ledger to Wharfmaster Dizzywig."} end
if not DB[891] then DB[891]={id=891,zoneId=17,name="The Guns of Northwatch",level=20,minLevel=13,giver="Captain Thalo'thas Brightsun",giverType="NPC",giverId=3339,ender="Captain Thalo'thas Brightsun",enderType="NPC",enderId=3339,poiX=-1025,poiY=-3689,wowhead="https://www.wowhead.com/wotlk/quest=891",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold!$b$bThose pests must be dealt with. Their paranoia has them in a state of frenzy. Trigger happy, reckless louts are shooting at anything in their sights.$b$bTravel south along the Merchant Coast to the Hold and lay siege to their forces. Bring me the medals of their soldiers as proof. And for the love of my fleet, slay Captain Fairmount and her overzealous cannoneers!",logDesc="Captain Thalo'thas Brightsun of Ratchet wants you to collect 10 Theramore Medals and slay Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe.",choiceRewards={{id=5309,qty=1},{id=5310,qty=1}}} end
if not DB[892] then DB[892]={id=892,zoneId=17,name="The Missing Shipment",level=14,minLevel=9,giver="Wharfmaster Dizzywig",giverType="NPC",giverId=3453,ender="Gazlowe",enderType="NPC",enderId=3391,rewardNextId=888,poiX=-986,poiY=-3797,wowhead="https://www.wowhead.com/wotlk/quest=892",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Everything looks square from my records, $n. Go on back and tell Gazlowe he's out of luck. I wouldn't be surprised if it was the pirates that nabbed his goodies.$b$bNothing else I can do for him. Oh... though you could tell him that I've got some things from Undermine for him, when he has the time to come pick them up.",logDesc="Return Gazlowe's Ledger to Gazlowe in Ratchet."} end
if not DB[893] then DB[893]={id=893,zoneId=17,name="Weapons of Choice",level=24,minLevel=17,giver="Tatternack Steelforge",giverType="NPC",giverId=3433,ender="Tatternack Steelforge",enderType="NPC",enderId=3433,poiX=-2285,poiY=-1947,wowhead="https://www.wowhead.com/wotlk/quest=893",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons. I'd like to get my hands on a few different types to learn their techniques if possible.$B$BIf you wish to help bring honor to the Horde, then bring me examples of their weapons. Find me a dagger from their stalkers, a wand from their seers, and a shield from their warfrenzy. That should do nicely!",logDesc="Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.",choiceRewards={{id=5322,qty=1},{id=5323,qty=1}}} end
if not DB[894] then DB[894]={id=894,zoneId=17,name="Samophlange",level=14,minLevel=10,giver="Sputtervalve",giverType="NPC",giverId=3442,rewardNextId=900,poiX=-902,poiY=-3759,wowhead="https://www.wowhead.com/wotlk/quest=894",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The Venture Company set up a small research facility far to the north of here, southwest of the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".$b$bNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.$b$bI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.",logDesc="Access the control console at the Venture Company research site."} end
if not DB[895] then DB[895]={id=895,zoneId=17,name="WANTED: Baron Longshore",level=16,minLevel=9,ender="Gazlowe",enderType="NPC",enderId=3391,wowhead="https://www.wowhead.com/wotlk/quest=895",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="WANTED!$b$bBaron Longshore, Captain of the Heedless$b$bCaptain Longshore of Gilneas leads vessels of the Southsea Freebooters, and is wanted on charges of piracy. Remains must be in identifiable condition!$b$b-- Gazlowe",logDesc="Bring the head of Baron Longshore to Gazlowe in Ratchet."} end
if not DB[896] then DB[896]={id=896,zoneId=17,name="Miner's Fortune",level=18,minLevel=13,giver="Wharfmaster Dizzywig",giverType="NPC",giverId=3453,ender="Wharfmaster Dizzywig",enderType="NPC",enderId=3453,poiX=-986,poiY=-3797,wowhead="https://www.wowhead.com/wotlk/quest=896",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Being Wharfmaster of a busy port like Ratchet, I keep my finger on the pulse of information. I know all about the exchange of goods and money between here and Booty Bay.$b$bThe latest bit of news I've heard is about the Venture Company's Boulder Lode mine northeast of the Sludge Fen. One of the miners discovered an emerald the size of your fist. I know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale.",logDesc="Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers for Wharfmaster Dizzywig at Ratchet.",rewards={{id=5335,qty=1}}} end
if not DB[897] then DB[897]={id=897,zoneId=17,name="The Harvester",level=24,minLevel=10,ender="Jorn Skyseer",enderType="NPC",enderId=3387,wowhead="https://www.wowhead.com/wotlk/quest=897",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This strange, insect-like creature looks outside of the natural order, as though it does not belong in the Barrens.",logDesc="Bring the Harvester's Head to Jorn Skyseer."} end
if not DB[898] then DB[898]={id=898,zoneId=17,name="Free From the Hold",level=20,minLevel=13,giver="Gilthares Firebough",giverType="NPC",giverId=3465,ender="Captain Thalo'thas Brightsun",enderType="NPC",enderId=3339,poiX=-2101,poiY=-3656,wowhead="https://www.wowhead.com/wotlk/quest=898",image="assets/images/quests/placeholder.png",xpDiff=6,money=2500,desc="Finally! Someone to rescue me!$b$bI can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor. I was called an enemy and threat to the Alliance.$b$bMe! A threat to their great sham of an Alliance? I was a deckhand on a moonshine transport between Ratchet and Booty Bay.$b$bEnough talk. Help me get back to Ratchet will you? Let me know when you're ready and we'll make our break.",logDesc="Safely escort Gilthares Firebough back to Captain Brightsun in Ratchet.",choiceRewards={{id=5311,qty=1},{id=5312,qty=1}}} end
if not DB[899] then DB[899]={id=899,zoneId=17,name="Consumed by Hatred",level=20,minLevel=14,giver="Mankrik",giverType="NPC",giverId=3432,ender="Mankrik",enderType="NPC",enderId=3432,poiX=-521,poiY=-2641,wowhead="https://www.wowhead.com/wotlk/quest=899",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Perhaps you know the pain of uncertainty, perhaps not, $c. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched. Perhaps instead of heading north to the Crossroads I should have headed to Taurajo.$B$BYou, $c--you  could help me.$B$BKill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths together.",logDesc="Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads.",choiceRewards={{id=5314,qty=1},{id=6477,qty=1}}} end
if not DB[900] then DB[900]={id=900,zoneId=17,name="Samophlange",level=14,minLevel=10,rewardNextId=901,wowhead="https://www.wowhead.com/wotlk/quest=900",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.",logDesc="Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again."} end
if not DB[901] then DB[901]={id=901,zoneId=17,name="Samophlange",level=14,minLevel=10,rewardNextId=902,wowhead="https://www.wowhead.com/wotlk/quest=901",image="assets/images/quests/placeholder.png",xpDiff=4,desc="With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.",logDesc="Get the Console Key from Tinkerer Sniggles to use on the control console."} end
if not DB[902] then DB[902]={id=902,zoneId=17,name="Samophlange",level=16,minLevel=10,ender="Sputtervalve",enderType="NPC",enderId=3442,wowhead="https://www.wowhead.com/wotlk/quest=902",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing.",logDesc="Return the Samophlange to Sputtervalve in Ratchet.",choiceRewards={{id=5324,qty=1},{id=5325,qty=1}}} end
if not DB[903] then DB[903]={id=903,zoneId=17,name="Prowlers of the Barrens",level=15,minLevel=10,giver="Sergra Darkthorn",giverType="NPC",giverId=3338,ender="Sergra Darkthorn",enderType="NPC",enderId=3338,rewardNextId=881,poiX=-482,poiY=-2670,wowhead="https://www.wowhead.com/wotlk/quest=903",image="assets/images/quests/placeholder.png",xpDiff=5,money=700,desc="Now it's time to go after something that really bites.  The prowlers of the Barrens are a tough breed.  Tough, resourceful, sly... and deadly.  You'll find them among the tall grasses.  You'll find many to the southwest of the Crossroads.$B$BBe wary as you hunt them, $n, or you may find yourself no longer the predator, but instead the prey.",logDesc="Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads."} end
if not DB[904] then DB[904]={id=904,zoneId=0,name="<UNUSED>",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=904",image="assets/images/quests/placeholder.png"} end
if not DB[905] then DB[905]={id=905,zoneId=17,name="The Angry Scytheclaws",level=17,minLevel=10,giver="Sergra Darkthorn",giverType="NPC",giverId=3338,ender="Sergra Darkthorn",enderType="NPC",enderId=3338,rewardNextId=3261,poiX=-482,poiY=-2670,wowhead="https://www.wowhead.com/wotlk/quest=905",image="assets/images/quests/placeholder.png",xpDiff=5,money=900,desc="Now, $N, the hunt deepens.  Now you must defeat your prey, and then find your way to its lair.$B$BHunt the sunscale raptors to the south.  Slay them and remove the feathers they wear.  Place the feathers on the scytheclaw nests southwest of the Stagnant Oasis. Show their brethren you do not fear them!",logDesc="Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads."} end
if not DB[906] then DB[906]={id=906,zoneId=17,name="Betrayal from Within",level=25,minLevel=17,giver="Mangletooth",giverType="NPC",giverId=3430,ender="Thork",enderType="NPC",enderId=3429,poiX=-2392,poiY=-1891,wowhead="https://www.wowhead.com/wotlk/quest=906",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Take Lok's head to Thork in the Crossroads, $r. <snort> He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in <snort> such things. But I am sure he'll reward you for carrying out such a great deed. <snort>$B$BI will continue to bless you with Agamaggan's power for as long as I remain in this cage, $r. Until then, farewell.",logDesc="Bring Lok's Skull to Thork at the Crossroads in the Barrens.",choiceRewards={{id=5316,qty=1},{id=5317,qty=1}}} end
if not DB[907] then DB[907]={id=907,zoneId=17,name="Enraged Thunder Lizards",level=18,minLevel=10,giver="Jorn Skyseer",giverType="NPC",giverId=3387,ender="Jorn Skyseer",enderType="NPC",enderId=3387,rewardNextId=913,poiX=-2383,poiY=-1923,wowhead="https://www.wowhead.com/wotlk/quest=907",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Now, $N, you must face the great thunder lizards.  So large are the beasts, the ground rumbles as they stomp across the plains.  Take care as you fight them, for one false step and you may find yourself beneath their feet.$B$BYou will find the thunder lizards in the southern Barrens.  They are known as Stormsnouts, Stormhides and Thunderheads.  Return to me after you have bested them.",logDesc="Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo."} end
if not DB[908] then DB[908]={id=908,zoneId=331,name="Amongst the Ruins",level=27,minLevel=25,wowhead="https://www.wowhead.com/wotlk/quest=908",image="assets/images/quests/placeholder.png",xpDiff=6,money=4500,desc="The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.$B$B$N, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!",logDesc="Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."} end
if not DB[909] then DB[909]={id=909,zoneId=331,name="Baron Aquanis",level=30,minLevel=25,wowhead="https://www.wowhead.com/wotlk/quest=909",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.$B$BIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.",logDesc="Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",choiceRewards={{id=16886,qty=1},{id=16887,qty=1}}} end
if not DB[910] then DB[910]={id=910,zoneId=-284,name="Down at the Docks",level=-1,minLevel=10,ender="Orcish Orphan",enderType="NPC",enderId=14444,wowhead="https://www.wowhead.com/wotlk/quest=910",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I have heard tales of the mighty ships that sail between Ratchet and Booty Bay!  That would be so cool to sail on the ocean and fight in many great sea battles.  Maybe I will be a mighty Horde sailor when I grow up!  Yeah!$B$BWould you take me to see the Ratchet docks, please?  I promise I won't get into the water or cause any trouble - I just want to see the big boats and smell the salty sea water!  Yeah!",logDesc="Take your ward to the docks of Ratchet in the Barrens."} end
if not DB[911] then DB[911]={id=911,zoneId=-284,name="Gateway to the Frontier",level=-1,minLevel=10,ender="Orcish Orphan",enderType="NPC",enderId=14444,wowhead="https://www.wowhead.com/wotlk/quest=911",image="assets/images/quests/placeholder.png",xpDiff=1,desc="They say that Ashenvale is the new frontier, and that the Mor'shan Rampart in the Barrens is the gateway to it.  That would be so cool to be a pioneer, carving everything you need out of the untamed wilds!  They say that this is where the Horde and Alliance will clash the most in the future, and I want to be there $N!$B$BWould you take me to the Mor'shan Rampart so I can see what the frontier looks like, please?  I wanna see where the Horde is driving out those smelly night elves!",logDesc="Take your ward to the Mor'shan Rampart in the northern part of the Barrens, just before entering Ashenvale."} end
if not DB[912] then DB[912]={id=912,zoneId=38,name="Stonesplinter Trogg Disguise",level=12,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=912",image="assets/images/quests/placeholder.png",xpDiff=2,rewards={{id=5131,qty=1}}} end
if not DB[913] then DB[913]={id=913,zoneId=17,name="Cry of the Thunderhawk",level=20,minLevel=10,giver="Jorn Skyseer",giverType="NPC",giverId=3387,ender="Jorn Skyseer",enderType="NPC",enderId=3387,rewardNextId=874,poiX=-2383,poiY=-1923,wowhead="https://www.wowhead.com/wotlk/quest=913",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The thunderhawk, $N, is a fierce beast.  It is time for you to face them.  You must find where it roams, and bring me its wings as proof of your successful hunt.$B$BDo this, and your time with me will near its end.",logDesc="Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo.",rewards={{id=5299,qty=1}},choiceRewards={{id=5302,qty=1},{id=5306,qty=1}}} end
if not DB[914] then DB[914]={id=914,zoneId=718,name="Leaders of the Fang",level=22,minLevel=10,giver="Nara Wildmane",giverType="NPC",giverId=5770,ender="Nara Wildmane",enderType="NPC",enderId=5770,poiX=-1070,poiY=-273,wowhead="https://www.wowhead.com/wotlk/quest=914",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The druids in the Wailing Caverns, the Druids of the Fang, are an aberration.  They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams.$B$BThe Druids of the Fang have four leaders, and each possesses a dream gem.  Even now their faces haunt me!  Defeat the leaders and bring me their gems, and the Barrens may again know peace.$B$BGo, $N.  You will find them lurking deep within the Wailing Caverns.",logDesc="Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.",choiceRewards={{id=6505,qty=1},{id=6504,qty=1}}} end
if not DB[915] then DB[915]={id=915,zoneId=-284,name="You Scream, I Scream...",level=-1,minLevel=10,ender="Orcish Orphan",enderType="NPC",enderId=14444,wowhead="https://www.wowhead.com/wotlk/quest=915",image="assets/images/quests/placeholder.png",xpDiff=1,desc="ICE CREAM!  Oh please please please could you get me some ice cream?!  Strawberry is my favorite flavor, and there's no better strawberry ice cream in the world than Tigule and Foror's Strawberry Ice Cream!  It's my favorite ice cream in the whole wide world!$B$BI had it once a long time ago when I was at the Shimmering Flats race track, but I heard that they might be selling them in town now!  Please?  Pretty please?  With Tigule and Foror's Strawberry Ice Cream on top??!?!",logDesc="Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream."} end
if not DB[916] then DB[916]={id=916,zoneId=188,name="Webwood Venom",level=4,minLevel=3,giver="Gilshalan Windwalker",giverType="NPC",giverId=2082,ender="Gilshalan Windwalker",enderType="NPC",enderId=2082,rewardNextId=917,poiX=10418,poiY=871,wowhead="https://www.wowhead.com/wotlk/quest=916",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave.  They are cousin to a much smaller variety of spider; I believe the world tree has had a profound effect on them, and I would like specimens to study to confirm this.$B$BFirst, I would like some of their venom.  Gather Webwood venom sacs from the spiders in and around the Shadowthread Cave, to the north.  I can then examine them for similarities with their smaller cousin's venom.",logDesc="Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil.",choiceRewards={{id=10544,qty=1},{id=5392,qty=1},{id=5393,qty=1},{id=5586,qty=1}}} end
if not DB[917] then DB[917]={id=917,zoneId=188,name="Webwood Egg",level=5,minLevel=1,giver="Gilshalan Windwalker",giverType="NPC",giverId=2082,ender="Gilshalan Windwalker",enderType="NPC",enderId=2082,rewardNextId=920,poiX=10418,poiY=871,wowhead="https://www.wowhead.com/wotlk/quest=917",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Now that I have the spiders' venom, I'd like some live specimens to study.  Unfortunately, capturing a living, giant spider is more than I can ask of you, young $c.  And a giant spider is more than I could handle myself!$B$BBut if you can find an unhatched egg, then delivering specimens will be much easier, and I can then arrange for the unhatched spiders to be contained.$B$BThere must be a nest deep in the Shadowthread Cave.  Please, search for an egg in the nest and return it to me.",logDesc="Bring a Webwood Egg to Gilshalan in Aldrassil.",choiceRewards={{id=5395,qty=1},{id=4907,qty=1},{id=11189,qty=1}}} end
if not DB[918] then DB[918]={id=918,zoneId=141,name="Timberling Seeds",level=7,minLevel=4,giver="Denalan",giverType="NPC",giverId=2080,ender="Denalan",enderType="NPC",enderId=2080,rewardNextId=922,poiX=9507,poiY=714,wowhead="https://www.wowhead.com/wotlk/quest=918",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The timberlings of Teldrassil are elementals of nature.  In some ways they reflect the natural order of plants and animals on our great tree.$B$BSo it is disturbing to see how angry the timberlings have become.$B$BI believe it has something to do with the soil.  I have been working on different methods of nurturing plants and would like to try them on timberling seeds.  Please, can you gather seeds from timberlings around Lake Al'Ameth and bring them to me?",logDesc="Bring 8 Timberling Seeds to Denelan at Lake Al'Ameth.",rewards={{id=4604,qty=10}}} end
if not DB[919] then DB[919]={id=919,zoneId=141,name="Timberling Sprouts",level=7,minLevel=4,giver="Denalan",giverType="NPC",giverId=2080,ender="Denalan",enderType="NPC",enderId=2080,poiX=9507,poiY=714,wowhead="https://www.wowhead.com/wotlk/quest=919",image="assets/images/quests/placeholder.png",xpDiff=6,money=350,desc="Small timberlings are sprouting around the waters of Lake Al'Ameth.  I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble.$B$BWhen you're wandering the lake, if you see any timberling sprouts please take them.  Help keep our land clean!",logDesc="Bring 12 Timberling Sprouts to Denalan at Lake Al'Ameth.",choiceRewards={{id=5606,qty=1},{id=6061,qty=1}}} end
if not DB[920] then DB[920]={id=920,zoneId=188,name="Tenaron's Summons",level=5,minLevel=1,giver="Gilshalan Windwalker",giverType="NPC",giverId=2082,ender="Tenaron Stormgrip",enderType="NPC",enderId=3514,rewardNextId=921,poiX=10418,poiY=871,wowhead="https://www.wowhead.com/wotlk/quest=920",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$n, is it? I heard that Tenaron has been asking for you. You'll find him in the highest room atop Aldrassil.$b$bWe may live long lives, but it's best you not keep him waiting too long.",logDesc="Speak with Tenaron Stormgrip atop Aldrassil in Shadowglen."} end
if not DB[921] then DB[921]={id=921,zoneId=188,name="Crown of the Earth",level=5,minLevel=1,giver="Tenaron Stormgrip",giverType="NPC",giverId=3514,ender="Tenaron Stormgrip",enderType="NPC",enderId=3514,rewardNextId=928,poiX=10493,poiY=807,wowhead="https://www.wowhead.com/wotlk/quest=921",image="assets/images/quests/placeholder.png",xpDiff=4,desc="It is time for you to set out to seek your destiny, $n. But before you are ready to set out into the world beyond our enchanted forests, there is much you must learn about our recent history.$b$bMuch has changed with our people since the Battle of Mount Hyjal. Nordrassil lies a pale shadow of what it once was, its power used to defeat Archimonde and drive back the Burning Legion...$b$bThere is a task you must perform. Go to the moonwell north of Aldrassil and return me a phial of its water.",logDesc="Fill the Crystal Phial and bring it back to Tenaron Stormgrip atop Aldrassil."} end
if not DB[922] then DB[922]={id=922,zoneId=141,name="Rellian Greenspyre",level=7,minLevel=4,giver="Denalan",giverType="NPC",giverId=2080,ender="Rellian Greenspyre",enderType="NPC",enderId=3517,rewardNextId=923,poiX=9507,poiY=714,wowhead="https://www.wowhead.com/wotlk/quest=922",image="assets/images/quests/placeholder.png",xpDiff=3,desc="$N, can you take one of the seeds you brought me to my friend, Rellian Greenspyre?  He is a druid in Darnassus, and when last we spoke he revealed his interest in my work with the Timberlings.  He had some ideas himself, and he will appreciate a specimen seed to work with.$B$BThank you, $N.  You have been a great help to me.  I hope that, some day, you will see the fruit of my labors.$B$BYou will usually find Rellian walking the pathways of the Cenarion Enclave in Darnassus.",logDesc="Bring a Timberling Seed to Rellian Greenspyre in Darnassus."} end
if not DB[923] then DB[923]={id=923,zoneId=141,name="Tumors",level=9,minLevel=4,giver="Rellian Greenspyre",giverType="NPC",giverId=3517,ender="Rellian Greenspyre",enderType="NPC",enderId=3517,rewardNextId=2498,poiX=10086,poiY=2534,wowhead="https://www.wowhead.com/wotlk/quest=923",image="assets/images/quests/placeholder.png",xpDiff=6,money=600,desc="There is a malevolence growing in the timberlings.  We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help.  Those that wander Wellspring Lake in northern Teldrassil are the most tainted.  They must be removed!$B$BDestroy the Timberlings you find there, and gather the mossy tumors growing upon them.  Bring the tumors to me so that they may be burned.",logDesc="Bring 5 Mossy Tumors to Rellian Greenspyre in Darnassus.",rewards={{id=5605,qty=1}}} end
if not DB[924] then DB[924]={id=924,zoneId=14,name="The Demon Seed",level=14,minLevel=9,giver="Ak'Zeloth",giverType="NPC",giverId=3521,ender="Ak'Zeloth",enderType="NPC",enderId=3521,poiX=256,poiY=-3694,wowhead="https://www.wowhead.com/wotlk/quest=924",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire.$B$BI have prepared power stones that when placed near the Seed will disrupt its connection to the Legion.$B$BTake a stone from the table and bring it to the altar of fire atop Dreadmist Peak. Travel west, then north when the road forks. The Peak will be to your left. The safest climb to the top is on its northern face.$B$BAnd hurry--the stone's power will consume itself in time.",logDesc="Grab a Flawed Power Stone.  Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth.",rewards={{id=5420,qty=1}}} end
if not DB[925] then DB[925]={id=925,zoneId=-284,name="Cairne's Hoofprint",level=-1,minLevel=10,ender="Orcish Orphan",enderType="NPC",enderId=14444,wowhead="https://www.wowhead.com/wotlk/quest=925",image="assets/images/quests/placeholder.png",xpDiff=1,desc="They say that Cairne Bloodhoof is one of the greatest heroes the Horde has ever seen.  When I grow up, I wanna be a hero of the Horde too!$B$BDo you know Cairne, $N?  Could you do me a favor, please?  Could you get his hoofprint for me?  I dunno how to ask him, and he'd probably be too busy for someone like me... but you!  You're an adventurer just like he is!  I bet he'd give you his hoofprint easy!$B$BPlease?",logDesc="Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward."} end
if not DB[926] then DB[926]={id=926,zoneId=14,name="Flawed Power Stone",level=14,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=926",image="assets/images/quests/placeholder.png",rewards={{id=4986,qty=1}}} end
if not DB[927] then DB[927]={id=927,zoneId=141,name="The Moss-twined Heart",level=12,minLevel=5,ender="Denalan",enderType="NPC",enderId=2080,wowhead="https://www.wowhead.com/wotlk/quest=927",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The heart of Blackmoss the Fetid is covered with a dark, oily moss.  In fact, the only way to tell this is a heart is from its slow, rhythmic beat... A beat that continues even now.$B$BPerhaps Denalan will want to see this heart.",logDesc="Bring the Moss-twined Heart to Denalan at Lake Al'Ameth."} end
if not DB[928] then DB[928]={id=928,zoneId=188,name="Crown of the Earth",level=5,minLevel=1,giver="Tenaron Stormgrip",giverType="NPC",giverId=3514,ender="Corithras Moonrage",enderType="NPC",enderId=3515,rewardNextId=929,poiX=10493,poiY=807,wowhead="https://www.wowhead.com/wotlk/quest=928",image="assets/images/quests/placeholder.png",xpDiff=3,desc="While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.$b$bSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.$b$bMind you stay on the road though, $n. There are dangerous beasts in the forests of late.",logDesc="Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar."} end
if not DB[929] then DB[929]={id=929,zoneId=141,name="Crown of the Earth",level=5,minLevel=1,giver="Corithras Moonrage",giverType="NPC",giverId=3515,ender="Corithras Moonrage",enderType="NPC",enderId=3515,rewardNextId=933,poiX=9737,poiY=956,wowhead="https://www.wowhead.com/wotlk/quest=929",image="assets/images/quests/placeholder.png",xpDiff=4,desc="First, let me tell you more of the task you must complete. The druids in Darnassus use the water of the moonwells of Teldrassil, and their moonwell must be replenished from time to time. Using these specially crafted phials, you can collect the water of the moonwells.$b$bTake this vessel to the moonwell outside of Starbreeze Village to the east, and fill it with some of its waters, then return to me. When you have completed your task, I shall continue the story where Tenaron left off...",logDesc="Fill the Jade Phial and bring it back to Corithras Moonrage in Dolanaar."} end
if not DB[930] then DB[930]={id=930,zoneId=141,name="The Glowing Fruit",level=10,minLevel=4,ender="Denalan",enderType="NPC",enderId=2080,wowhead="https://www.wowhead.com/wotlk/quest=930",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="Hanging from beneath its fronds of this glowing plant is a large, round fruit.$B$BDenalan would want to study this fruit, you are certain.",logDesc="Bring the glowing fruit to Denalan at Lake Al'Ameth."} end
if not DB[931] then DB[931]={id=931,zoneId=141,name="The Shimmering Frond",level=10,minLevel=4,ender="Denalan",enderType="NPC",enderId=2080,wowhead="https://www.wowhead.com/wotlk/quest=931",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="The fronds on this plant shimmer in the forest light, giving it a twisting, pulsing aura.$B$BYou believe that Denalan would want a specimen of this.",logDesc="Bring a Shimmering Frond to Denalan at Lake Al'Ameth"} end
if not DB[932] then DB[932]={id=932,zoneId=141,name="Twisted Hatred",level=7,minLevel=4,giver="Tallonkai Swiftroot",giverType="NPC",giverId=3567,ender="Tallonkai Swiftroot",enderType="NPC",enderId=3567,poiX=9899,poiY=985,wowhead="https://www.wowhead.com/wotlk/quest=932",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I must warn you, $n, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home.$B$BHe is called Lord Melenas. He resides in the nearby cave of Fel Rock where he has gathered a large group of grell warriors. His heart is black as night, and he plots something most foul.$B$BYou must find him within his nearby cave just to the north of here, and bring me his head.",logDesc="Kill Lord Melenas and bring his head to Tallonkai Swiftroot in Dolanaar.",choiceRewards={{id=5419,qty=1},{id=2571,qty=1}}} end
if not DB[933] then DB[933]={id=933,zoneId=141,name="Crown of the Earth",level=9,minLevel=1,giver="Corithras Moonrage",giverType="NPC",giverId=3515,ender="Corithras Moonrage",enderType="NPC",enderId=3515,rewardNextId=7383,poiX=9737,poiY=956,wowhead="https://www.wowhead.com/wotlk/quest=933",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There is another moonwell southeast of the entrance to Darnassus, on the shores of the Pools of Arlithrien. The Sentinels are having problems patrolling the area because of attacks and the growing ill-temperedness of the Gnarlpine furbolgs.$b$bBe wary as you seek out the well, and keep your weapons close at hand.",logDesc="Fill the Tourmaline Phial and bring it back to Corithras Moonrage in Dolanaar."} end
if not DB[934] then DB[934]={id=934,zoneId=141,name="Crown of the Earth",level=11,minLevel=1,rewardNextId=935,wowhead="https://www.wowhead.com/wotlk/quest=934",image="assets/images/quests/placeholder.png",xpDiff=4,desc="All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed.$b$bHowever, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.",logDesc="Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar."} end
if not DB[935] then DB[935]={id=935,zoneId=141,name="Crown of the Earth",level=11,minLevel=1,giver="Corithras Moonrage",giverType="NPC",giverId=3515,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,poiX=9737,poiY=956,wowhead="https://www.wowhead.com/wotlk/quest=935",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw. Strange beasts have been reported arising from the very ground of the tree, and crazed furbolgs attack passing travelers.$b$bI can only hope that the solution the Arch Druid is looking for will be found quickly. I will pour all the phials you brought into this vessel, for you to deliver to Darnassus.$b$bBring it to Fandral Staghelm, you will find him in the druid grove.",logDesc="Bring the Filled Vessel to Arch Druid Fandral Staghelm in Darnassus.",choiceRewards={{id=5596,qty=1},{id=5595,qty=1}}} end
if not DB[936] then DB[936]={id=936,zoneId=1637,name="Assisting Arch Druid Runetotem",level=50,minLevel=47,giver="Innkeeper Gryshka",giverType="NPC",giverId=6929,ender="Arch Druid Hamuul Runetotem",enderType="NPC",enderId=5769,rewardNextId=3761,poiX=1634,poiY=-4439,wowhead="https://www.wowhead.com/wotlk/quest=936",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excuse me $c, but I'd like just a moment of your time if possible.$B$BThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.$B$BPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.",logDesc="Speak with Arch Druid Hamuul Runetotem in Thunder Bluff."} end
if not DB[937] then DB[937]={id=937,zoneId=141,name="The Enchanted Glade",level=11,minLevel=6,giver="Sentinel Arynia Cloudsbreak",giverType="NPC",giverId=3519,ender="Sentinel Arynia Cloudsbreak",enderType="NPC",enderId=3519,rewardNextId=940,poiX=10665,poiY=1864,wowhead="https://www.wowhead.com/wotlk/quest=937",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade. Little by little we are trying to push them back.$b$bWhen the Oracle Tree attempted to send a runner to Darnassus with a report, the messenger was attacked and killed by a group of the harpies.$b$bIf you feel up to the task, go to their nests, slay them, and return their belts to me as proof of your deeds.",logDesc="Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade.",choiceRewards={{id=5592,qty=1},{id=5591,qty=1}}} end
if not DB[938] then DB[938]={id=938,zoneId=141,name="Mist",level=12,minLevel=7,giver="Mist",giverType="NPC",giverId=3568,ender="Sentinel Arynia Cloudsbreak",enderType="NPC",enderId=3519,poiX=10758,poiY=2209,wowhead="https://www.wowhead.com/wotlk/quest=938",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach.$b$bShe raises her head and gazes at you, bright intelligence shining in blue eyes. She seems to wish to follow you.",logDesc="Escort Mist to Sentinel Arynia Cloudsbreak at the moon well near the Oracle Tree.",choiceRewards={{id=5590,qty=1},{id=5593,qty=1},{id=5618,qty=1}}} end
if not DB[939] then DB[939]={id=939,zoneId=361,name="Flute of Xavaric",level=54,minLevel=49,ender="Eridan Bluewind",enderType="NPC",enderId=9116,rewardNextId=4441,wowhead="https://www.wowhead.com/wotlk/quest=939",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You study the simple wooden flute you picked up after defeating Xavaric.$B$BThe knotted wood feels solid, but it seems as if the spirals and patterns in the surface begin to spin and move as you turn it over in your hands. Suddenly, you feel a sense of dread...$B$BYou shake your head, sure that your mind is playing tricks on you.$B$BIt's possible that other satyrs carry clues as to what you have found. Bring your findings to the druid, Eridan Bluewind, that lives in southern Felwood.",logDesc="Bring the Flute of Xavaric and 5 Jadefire Felbind samples to Eridan Bluewind in southern Felwood."} end
if not DB[940] then DB[940]={id=940,zoneId=141,name="Teldrassil",level=11,minLevel=6,giver="Sentinel Arynia Cloudsbreak",giverType="NPC",giverId=3519,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,rewardNextId=952,poiX=10665,poiY=1864,wowhead="https://www.wowhead.com/wotlk/quest=940",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The forest whispers of your feats of valor, $n. As I felt the harpies forced from their nests, a greater calm spread across the forest, its creatures once again feeling safe. I have feared sending another messenger to the Arch Druid, but I know that you will see my message safely to him.$b$bDeliver this to him and know that the forest will see you safely along its paths to the forest of stone.",logDesc="Deliver the Oracle Tree's report to Arch Druid Fandral Staghelm in Darnassus."} end
if not DB[941] then DB[941]={id=941,zoneId=141,name="Planting the Heart",level=12,minLevel=9,giver="Denalan",giverType="NPC",giverId=2080,poiX=9507,poiY=714,wowhead="https://www.wowhead.com/wotlk/quest=941",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I have removed that foul moss from the heart, but it remains tainted...$B$BTry placing the heart in my planter.  It is filled with a nutritive soil that may cleanse and heal the heart.",logDesc="Plant the Tainted Heart in Denalan's Planter.",rewards={{id=5218,qty=1}}} end
if not DB[942] then DB[942]={id=942,zoneId=148,name="The Absent Minded Prospector",level=20,minLevel=15,giver="Chief Archaeologist Greywhisker",giverType="NPC",giverId=2912,ender="Archaeologist Flagongut",enderType="NPC",enderId=2911,rewardNextId=943,poiX=9642,poiY=2608,wowhead="https://www.wowhead.com/wotlk/quest=942",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This fossil bears a striking resemblance to one I once saw in Ironforge. An archaeologist by the name of Flagongut brought it to our annual Explorers' League conference. He believed the fossil had a power which could be unlocked somehow.$b$bLast I heard Flagongut had holed up in the Deepwater Tavern in Menethil Harbor, awaiting escort to the Whelgar Excavation Site. Seek him out and show him Remtravel's fossil. Perhaps he can reveal the secrets of the past.$b$bGood luck findin' your way there!",logDesc="Take the mysterious fossil to Archaeologist Flagongut in Menethil Harbor."} end
if not DB[943] then DB[943]={id=943,zoneId=148,name="The Absent Minded Prospector",level=24,minLevel=15,giver="Archaeologist Flagongut",giverType="NPC",giverId=2911,ender="Archaeologist Flagongut",enderType="NPC",enderId=2911,poiX=-3814,poiY=-838,wowhead="https://www.wowhead.com/wotlk/quest=943",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Prospector Whelgar now holds the original fossil at his site in the Wetlands. When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil.$b$bWhile I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost. I don't know which one of the mottled beasts swallowed the relic but if you can retrieve it, I can unleash the power of these artifacts.$B$BBring me both the Stone of Relu, and the original fossil he holds.",logDesc="Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil.",choiceRewards={{id=5627,qty=1},{id=5626,qty=1}}} end
if not DB[944] then DB[944]={id=944,zoneId=148,name="The Master's Glaive",level=17,minLevel=12,giver="Onu",giverType="NPC",giverId=3616,rewardNextId=949,poiX=5002,poiY=89,wowhead="https://www.wowhead.com/wotlk/quest=944",image="assets/images/quests/placeholder.png",xpDiff=3,desc="It is strange that the naga are here, in Darkshore.  But stranger still...are the Twilight's Hammer.  That cult worships the old, old lords of the earth.  Lords defeated long ago.$B$BThe Master's Glaive, to the south, is a place where such an old lord fell.$B$BGo there and look for more Twilight's Hammer cultists.$B$BTake this phial of scrying.  Use it to create a scrying bowl after searching the Master's Glaive.  Then speak to me through the bowl.",logDesc="Gather information, then use the Phial of Scrying to create a Scrying Bowl.  Use the bowl to speak with Onu."} end
if not DB[945] then DB[945]={id=945,zoneId=148,name="Therylune's Escape",level=18,minLevel=10,giver="Therylune",giverType="NPC",giverId=3584,ender="Therysil",enderType="NPC",enderId=3585,poiX=4520,poiY=410,wowhead="https://www.wowhead.com/wotlk/quest=945",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="Help!$B$BI was wandering around the Master's Glaive, and these dirty cultists surrounded me.  Lucky I'm good at hiding!!$B$BCan you help me out of here?  And I need to send word to my sister Therysil that I'm all right.  She's in Ashenvale to the south, at the Shrine of Aessina.",logDesc="Help Therylune escape, then tell Therysil at the Shrine of Aessina in Ashenvale that her sister is safe."} end
if not DB[946] then DB[946]={id=946,zoneId=0,name="<UNUSED>",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=946",image="assets/images/quests/placeholder.png"} end
if not DB[947] then DB[947]={id=947,zoneId=148,name="Cave Mushrooms",level=17,minLevel=12,giver="Barithras Moonshade",giverType="NPC",giverId=3583,ender="Barithras Moonshade",enderType="NPC",enderId=3583,rewardNextId=948,poiX=6428,poiY=497,wowhead="https://www.wowhead.com/wotlk/quest=947",image="assets/images/quests/placeholder.png",xpDiff=5,money=900,desc="I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave.  The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains.$B$BI would go there myself, but I was advised by the Grove of the Ancients to stay away from that place.  Our venerable allies sense that the cave is the hiding place for a new evil in Darkshore.$B$BPlease, $N, gather the mushrooms for me.  And while doing so, scout the cave to confirm the Ancients' fears.",logDesc="Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine.",rewards={{id=5610,qty=1},{id=4605,qty=10}}} end
if not DB[948] then DB[948]={id=948,zoneId=148,name="Onu",level=17,minLevel=12,giver="Barithras Moonshade",giverType="NPC",giverId=3583,ender="Onu",enderType="NPC",enderId=3616,rewardNextId=944,poiX=6428,poiY=497,wowhead="https://www.wowhead.com/wotlk/quest=948",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Onu, an Ancient of Lore at the Grove of the Ancients, knows of your journey to Cliffwater Falls and wishes to speak with you.  The grove lies to the south, nestled near the mountains.$B$BThe Ancients are patient and wise, $N.  But if Onu seeks your counsel concerning what you saw in the falls, then I fear it is urgent.",logDesc="Speak with Onu at the Grove of the Ancients."} end
if not DB[949] then DB[949]={id=949,zoneId=148,name="The Twilight Camp",level=17,minLevel=12,rewardNextId=950,wowhead="https://www.wowhead.com/wotlk/quest=949",image="assets/images/quests/placeholder.png",xpDiff=5,money=900,desc="The Twilight's Hammer's purpose at the Master's Glaive is not known.  But it must be dark.$B$BSearch through their camp at the Glaive... Search for some thing that may teach us their intentions.$B$BFor we must learn their intentions before a plan is made.",logDesc="Find a clue in the Twilight's Hammer camp at the Master's Glaive."} end
if not DB[950] then DB[950]={id=950,zoneId=148,name="Return to Onu",level=17,minLevel=12,ender="Onu",enderType="NPC",enderId=3616,wowhead="https://www.wowhead.com/wotlk/quest=950",image="assets/images/quests/placeholder.png",xpDiff=4,money=700,desc="Peering into the Twilight Tome is maddening.  Text begins to swim and dance after only a moment's glance, and once beautiful scrollwork twists into grotesque shapes.$B$BTearing away one page of insane scribbles is all that is possible before a swoon overtakes you.",logDesc="Bring Onu the recovered Insane Scribbles."} end
if not DB[951] then DB[951]={id=951,zoneId=148,name="Mathystra Relics",level=20,minLevel=12,giver="Onu",giverType="NPC",giverId=3616,ender="Onu",enderType="NPC",enderId=3616,poiX=5002,poiY=89,wowhead="https://www.wowhead.com/wotlk/quest=951",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!  It is heavily cursed and tainted by the corruption of the Twilight's Hammer, but it seems the cult is using ancient elven magic to bring their old masters back to our world.$B$BTravel to the ruins of Mathystra to the northeast, and search for ancient relics among the grass and broken stones.  Through their study, we may divine how the Twilight's Hammer intends to exploit the magic of the elves.",logDesc="Bring 6 Mathystra Relics to Onu at the Grove of the Ancients.",choiceRewards={{id=5757,qty=1},{id=5615,qty=1}}} end
if not DB[952] then DB[952]={id=952,zoneId=1657,name="Grove of the Ancients",level=11,minLevel=6,giver="Arch Druid Fandral Staghelm",giverType="NPC",giverId=3516,ender="Onu",enderType="NPC",enderId=3616,poiX=10173,poiY=2570,wowhead="https://www.wowhead.com/wotlk/quest=952",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If you had enough time to run messages for the Oracle Tree, then I'm sure that I can press you into service to deliver a message to the Grove of the Ancients in Darkshore, due south of Auberdine.$b$bYou will most likely have to secure transport on a hippogryph, but I have faith enough in you that you can manage that. Take this to Onu, the Ancient of Lore. He has been awaiting word from me, even as I waited for news from the Oracle Glade.",logDesc="Deliver Fandral's message to Onu in the Grove of the Ancients in Darkshore, south of Auberdine."} end
if not DB[953] then DB[953]={id=953,zoneId=148,name="The Fall of Ameth'Aran",level=12,minLevel=9,giver="Sentinel Tysha Moonblade",giverType="NPC",giverId=3639,ender="Sentinel Tysha Moonblade",enderType="NPC",enderId=3639,poiX=5725,poiY=302,wowhead="https://www.wowhead.com/wotlk/quest=953",image="assets/images/quests/placeholder.png",xpDiff=5,money=500,desc="To the east you will find the ruins of Ameth'Aran. It is now inhabited by the restless spirits of the Highborne that once dwelt within its walls, but once it was a place where the servants of Azshara freely practiced their powerful magics.$b$bI was sent to explore the ruins and came across two large tablets, scrawled with the stories of Ameth'Aran and its fall. While I read the runes, I was accosted by the spirits, and fled.$b$bPlease, if you can, venture to the ruins and decipher the tablets in my place.",logDesc="Study the tablets which tell of Ameth'Aran and of its fall, then return to Sentinel Tysha Moonblade in Darkshore."} end
if not DB[954] then DB[954]={id=954,zoneId=148,name="Bashal'Aran",level=12,minLevel=7,giver="Thundris Windweaver",giverType="NPC",giverId=3649,ender="Asterion",enderType="NPC",enderId=3650,rewardNextId=955,poiX=6581,poiY=492,wowhead="https://www.wowhead.com/wotlk/quest=954",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The ruins of Bashal'Aran to the east are overrun with demonic minions. The sprites and satyrs that have taken up residence in the area feed upon the magical energies of the area, their powers growing from continued exposure.$b$bEven with that, I have noticed that there is one shrine they will not approach. On the western side of the ruins, atop a small bluff, a strange blue aura permeates... There must be an explanation to the demons' reluctance.$b$bI would like you to investigate it.",logDesc="Find the source of the strange blue aura in the ruins of Bashal'Aran."} end
if not DB[955] then DB[955]={id=955,zoneId=148,name="Bashal'Aran",level=12,minLevel=7,giver="Asterion",giverType="NPC",giverId=3650,ender="Asterion",enderType="NPC",enderId=3650,rewardNextId=956,poiX=6749,poiY=49,wowhead="https://www.wowhead.com/wotlk/quest=955",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If I were to relate the story of my life, I have no doubt it would surpass the limits of your patience. Let us say that mine has been a long and painful life, and this spectral form is perhaps the worst torment of all.$b$bI am held here by the means of magic. Though my words may seem disingenuous, I assure you I would be grateful beyond words if you would help me find the means of my imprisonment. A seal binds me, and by examining the earpieces of the sprites and grells, I may find a trace of it.",logDesc="Acquire 8 Grell Earrings for Asterion in Bashal'Aran."} end
if not DB[956] then DB[956]={id=956,zoneId=148,name="Bashal'Aran",level=13,minLevel=7,giver="Asterion",giverType="NPC",giverId=3650,ender="Asterion",enderType="NPC",enderId=3650,rewardNextId=957,poiX=6749,poiY=49,wowhead="https://www.wowhead.com/wotlk/quest=956",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If the grells have come into close contact with the seal that binds my eternal prison, I suspect I know the cause. No doubt the seal has come into the possession of the satyr that lead them.$b$bI feel strongly that this must be true, $n. One of the satyr must surely possess it. If you can obtain it, you would bring me so close to passing the bars of my prison that tears would come to my eyes.",logDesc="Obtain the Ancient Moonstone Seal and bring it to Asterion in Bashal'Aran."} end
if not DB[957] then DB[957]={id=957,zoneId=148,name="Bashal'Aran",level=13,minLevel=7,giver="Asterion",giverType="NPC",giverId=3650,ender="Asterion",enderType="NPC",enderId=3650,poiX=6749,poiY=49,wowhead="https://www.wowhead.com/wotlk/quest=957",image="assets/images/quests/placeholder.png",xpDiff=4,desc="It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color. In this flame this seal could be destroyed.$b$bBe wary in the ruins, $n...",logDesc="Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran.",choiceRewards={{id=7229,qty=1},{id=5617,qty=1},{id=5604,qty=1}}} end
if not DB[958] then DB[958]={id=958,zoneId=148,name="Tools of the Highborne",level=12,minLevel=9,giver="Thundris Windweaver",giverType="NPC",giverId=3649,ender="Thundris Windweaver",enderType="NPC",enderId=3649,poiX=6581,poiY=492,wowhead="https://www.wowhead.com/wotlk/quest=958",image="assets/images/quests/placeholder.png",xpDiff=5,money=500,desc="$C. A task I would ask of you.$b$bHave you seen the ruins of Ameth'Aran? If not, you will find them on the eastern side of the main road, some ways to the south. Once they were the home of many powerful Highborne, now they are a testament to the destruction their dabblings produced.$b$bI have been told by the Sentinels that the spirits of the Highborne persist, and that they wield their ancient magical implements. Those relics must be appropriated, so that we might destroy them.",logDesc="Retrieve 7 Highborne Relics for Thundris Windweaver in Auberdine.",rewards={{id=5612,qty=1}}} end
if not DB[959] then DB[959]={id=959,zoneId=718,name="Trouble at the Docks",level=18,minLevel=14,giver="Crane Operator Bigglefuzz",giverType="NPC",giverId=3665,ender="Crane Operator Bigglefuzz",enderType="NPC",enderId=3665,poiX=-928,poiY=-3770,wowhead="https://www.wowhead.com/wotlk/quest=959",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="Oops!$b$bHad a little mishap, as you can see! The morning cargo shipment from Booty Bay was huge. Huge I say! Never seen so many crates. Well, I was trying to expedite things so I started unloading a bit more than I could handle. That's when everything came tumbling down.$b$bBefore I knew what was going on, I saw that menace, Mad Magglish, go running off with a bottle of 99-year-old port. Chased him all the way to Wailing Caverns. No way I was going in there.$b$bMaybe you're brave enough to find him?",logDesc="Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns."} end
if not DB[960] then DB[960]={id=960,zoneId=148,name="Onu is meditating",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=960",image="assets/images/quests/placeholder.png",rewards={{id=5251,qty=1}}} end
if not DB[961] then DB[961]={id=961,zoneId=148,name="Onu is meditating",level=1,minLevel=1,giver="Onu",giverType="NPC",giverId=3616,ender="Onu",enderType="NPC",enderId=3616,poiX=5002,poiY=89,wowhead="https://www.wowhead.com/wotlk/quest=961",image="assets/images/quests/placeholder.png",rewards={{id=5251,qty=1}}} end
if not DB[962] then DB[962]={id=962,zoneId=718,name="Serpentbloom",level=18,minLevel=14,giver="Apothecary Zamah",giverType="NPC",giverId=3419,ender="Apothecary Zamah",enderType="NPC",enderId=3419,poiX=-995,poiY=279,wowhead="https://www.wowhead.com/wotlk/quest=962",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="The Royal Apothecary Society, based in the great Undercity of Lordaeron, has sent me here for a very specific service, $n. Perhaps you wish to aid me, and in turn The Dark Lady in our efforts to advance the Forsaken.$b$bRecently I studied a rare specimen of flora named Serpentbloom. I believe in greater quantities this herb has great potential.$b$bUnfortunately Serpentbloom can only be found in the darkest recesses of the Wailing Caverns, a dangerous cave system located in the Barrens.",logDesc="Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.",rewards={{id=10919,qty=1}}} end
if not DB[963] then DB[963]={id=963,zoneId=148,name="For Love Eternal",level=16,minLevel=11,giver="Cerellean Whiteclaw",giverType="NPC",giverId=3644,ender="Cerellean Whiteclaw",enderType="NPC",enderId=3644,poiX=6425,poiY=600,wowhead="https://www.wowhead.com/wotlk/quest=963",image="assets/images/quests/placeholder.png",xpDiff=4,desc="In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya.$b$bI would never have thought, thousands of years later, that memories of Anaya would still haunt my dreams. Wandering the woods of Darkshore in a stupor, I found myself in the ruins of Ameth'Aran... where I saw the haunted spirit of my beloved.$b$bShe must be freed, but I lack the heart to do it. Her spirit must be destroyed.",logDesc="Free the spirit of Anaya Dawnrunner and bring her pendant back to Cerellean Whiteclaw in Auberdine.",rewards={{id=5611,qty=1}}} end
if not DB[964] then DB[964]={id=964,zoneId=28,name="Skeletal Fragments",level=57,minLevel=55,giver="Apothecary Dithers",giverType="NPC",giverId=11057,ender="Apothecary Dithers",enderType="NPC",enderId=11057,rewardNextId=5514,poiX=1752,poiY=-730,wowhead="https://www.wowhead.com/wotlk/quest=964",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.$B$BFirst thing's first though, $N.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.",logDesc="Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands."} end
if not DB[965] then DB[965]={id=965,zoneId=148,name="The Tower of Althalaxx",level=18,minLevel=13,giver="Sentinel Elissa Starbreeze",giverType="NPC",giverId=3657,ender="Balthule Shadowstrike",enderType="NPC",enderId=3661,rewardNextId=966,poiX=6432,poiY=384,wowhead="https://www.wowhead.com/wotlk/quest=965",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Hail, young $r. I am Elissa Starbreeze, and it is my charge to protect Auberdine from harm.$b$bTo this end, I sent Balthule Shadowstrike to observe the strange happenings around the Tower of Althalaxx to the northeast.$b$bIt is past time that he should have returned. I worry that he has encountered some unforeseen danger in the forest. I would be most appreciative if you would find him and see that he is doing well.",logDesc="Find Balthule Shadowstrike near the Tower of Althalaxx in Darkshore."} end
if not DB[966] then DB[966]={id=966,zoneId=148,name="The Tower of Althalaxx",level=18,minLevel=13,giver="Balthule Shadowstrike",giverType="NPC",giverId=3661,ender="Balthule Shadowstrike",enderType="NPC",enderId=3661,rewardNextId=967,poiX=7247,poiY=-659,wowhead="https://www.wowhead.com/wotlk/quest=966",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="A group of warlocks has taken up residence around and inside the tower. I would have returned to Auberdine to report to Elissa earlier, but I was afraid that I might miss something while I was away.$b$bDelgren suspected such a company might be gathering at the tower, but did not know why.$b$bA few scraps of parchment that the warlocks carry have found their way to my hands, but I need more to complete the puzzle. I warn you not to venture into the tower, however, the warlocks there are much more powerful!",logDesc="Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx."} end
if not DB[967] then DB[967]={id=967,zoneId=148,name="The Tower of Althalaxx",level=18,minLevel=13,giver="Balthule Shadowstrike",giverType="NPC",giverId=3661,ender="Delgren the Purifier",enderType="NPC",enderId=3663,rewardNextId=970,poiX=7247,poiY=-659,wowhead="https://www.wowhead.com/wotlk/quest=967",image="assets/images/quests/placeholder.png",xpDiff=4,desc="My master, Delgren the Purifier, is a paladin who has graciously offered his assistance in defending our forests from the forces of the demons and undead. He has taught me much about the Holy Light and the art of battle.$b$bDelgren must know of the cult's operations immediately.$b$bYou will find him far south of here at Maestra's Post in Ashenvale Forest. Be swift, I fear the Dark Strand's threat grows with each passing hour.",logDesc="Deliver Balthule's letter to Delgren the Purifier in Ashenvale Forest."} end
if not DB[968] then DB[968]={id=968,zoneId=148,name="The Powers Below",level=20,minLevel=10,ender="Gerrig Bonegrip",enderType="NPC",enderId=2786,wowhead="https://www.wowhead.com/wotlk/quest=968",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Although terribly worn and scratched, the title of this book can still be read upon its cover:$B$BThe Powers Below$B$BInside the book is a listing of unpronounceable names with foreboding titles, methods of worship, and preferred sacrifices...many of which include living, humanoid creatures.$B$BOn the inside cover of the book are the words: \"Bonegrip's Runes and Dooms, The Forlorn Cavern, Ironforge.  Proprietor: Gerrig Bonegrip.\"$B$BIf Bonegrip sells books like this, perhaps he'll buy this one back.",logDesc="Bring the Book: The Powers Below to Gerrig Bonegrip in the Forlorn Cavern, Ironforge."} end
if not DB[969] then DB[969]={id=969,zoneId=618,name="Luck Be With You",level=60,minLevel=55,giver="Witch Doctor Mau'ari",giverType="NPC",giverId=10307,ender="Witch Doctor Mau'ari",enderType="NPC",enderId=10307,rewardNextId=975,poiX=6721,poiY=-4713,wowhead="https://www.wowhead.com/wotlk/quest=969",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="Ah, I can tell just by lookin' at ya -- you be wantin' to make a lucky charm. Mau'ari always knows!$B$BTo da south. you'll find a canyon, an' giants made a' solid ice. The giants sometimes be carryin' dem, but ya can always gather da shards yerself from da canyon. These shards have a powerful reflective quality.$B$BBring back 4 frostmaul shards, and my lucky charm will be yours.",logDesc="Collect 4 Frostmaul Shards for Witch Doctor Mau'ari in Everlook."} end
if not DB[970] then DB[970]={id=970,zoneId=148,name="The Tower of Althalaxx",level=21,minLevel=13,giver="Delgren the Purifier",giverType="NPC",giverId=3663,ender="Delgren the Purifier",enderType="NPC",enderId=3663,poiX=3185,poiY=189,wowhead="https://www.wowhead.com/wotlk/quest=970",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Balthule's letter is dire. This Cult of the Dark Strand is a thorn in my side that must be removed. I have been dealing with some of the Dark Strand scum northeast of here at Ordil'Aran. One of their number possesses a soul gem that I believe holds the secret to the cult's power.$b$bBring it to me, and I will be able to decipher the secrets held within.",logDesc="Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post."} end
if not DB[971] then DB[971]={id=971,zoneId=719,name="Knowledge in the Deeps",level=23,minLevel=19,giver="Gerrig Bonegrip",giverType="NPC",giverId=2786,ender="Gerrig Bonegrip",enderType="NPC",enderId=2786,poiX=-4599,poiY=-1115,wowhead="https://www.wowhead.com/wotlk/quest=971",image="assets/images/quests/placeholder.png",xpDiff=7,desc="As you might know, I collect lore.  Old lore.  Powerful lore.  Lore that opens doorways, and lore that can awaken Those Who Sleep.$B$BThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of Blackfathom Deeps in Ashenvale.  That place is the old dwelling of long-dead elves.  Elves who held great knowledge before their city fell to ruin.$B$BSearch Blackfathom Deeps for the manuscript.  Do this, and I will not forget it.  Not even after ... the end days.",logDesc="Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.",rewards={{id=6743,qty=1}}} end
if not DB[972] then DB[972]={id=972,zoneId=-82,name="Water Sapta",level=-1,minLevel=20,giver="Islen Waterseer",giverType="NPC",giverId=5901,ender="Islen Waterseer",enderType="NPC",enderId=5901,poiX=-1345,poiY=-4048,wowhead="https://www.wowhead.com/wotlk/quest=972",image="assets/images/quests/placeholder.png",rewards={{id=6637,qty=1}}} end
if not DB[973] then DB[973]={id=973,zoneId=148,name="The Tower of Althalaxx",level=24,minLevel=13,giver="Delgren the Purifier",giverType="NPC",giverId=3663,ender="Delgren the Purifier",enderType="NPC",enderId=3663,rewardNextId=1140,poiX=3185,poiY=189,wowhead="https://www.wowhead.com/wotlk/quest=973",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine,  a place of great evil in southwestern Ashenvale.$b$bHe had been little more than an annoyance until now, and I had not dealt with him, but it seems that his time has come.",logDesc="Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post.",choiceRewards={{id=5622,qty=1},{id=5613,qty=1}}} end
if not DB[974] then DB[974]={id=974,zoneId=490,name="Finding the Source",level=55,minLevel=51,giver="Krakle",giverType="NPC",giverId=10302,ender="Krakle",enderType="NPC",enderId=10302,rewardNextId=980,poiX=-7211,poiY=-611,wowhead="https://www.wowhead.com/wotlk/quest=974",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The hot springs here are a source of mystery to me. Where does the heat come from?$B$BLooking at how close the pools are to Fire Plume Ridge, I really wonder if the volcano might have something to do with it. I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest part. It gives the measurements in degrees Kraklenheit!$B$BHere, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!",logDesc="Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.$B$BWhenever you find a hot spot, right click the thermometer to check the temperature. Keep looking until you find the hottest one."} end
if not DB[975] then DB[975]={id=975,zoneId=618,name="Cache of Mau'ari",level=60,minLevel=55,giver="Witch Doctor Mau'ari",giverType="NPC",giverId=10307,ender="Witch Doctor Mau'ari",enderType="NPC",enderId=10307,poiX=6721,poiY=-4713,wowhead="https://www.wowhead.com/wotlk/quest=975",image="assets/images/quests/placeholder.png",desc="Now, before I give ya dis charm, I better explain how ta use it.$B$BIf you carry da charm with ya, you'll find dat certain items will drop from creatures ya fight. If you don't have da charm with you, you won't find them. Understand?$B$BYou'll know these special items by the name -- they be called E'ko. If you find any of these items, just bring dem to ol' Mau'ari, and she help ya out.$B$BWait here while I fix your charm.",logDesc="Speak to Witch Doctor Mau'ari again in a moment to receive the lucky charm.",rewards={{id=12384,qty=1}}} end
if not DB[976] then DB[976]={id=976,zoneId=331,name="Supplies to Auberdine",level=24,minLevel=19,giver="Feero Ironhand",giverType="NPC",giverId=4484,ender="Delgren the Purifier",enderType="NPC",enderId=3663,poiX=3179,poiY=189,wowhead="https://www.wowhead.com/wotlk/quest=976",image="assets/images/quests/placeholder.png",xpDiff=7,money=5000,desc="Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own. Dangerous foes operate in the forest, and I do not wish to risk letting these supplies and information fall into the wrong hands.$b$bIf you and others could act as my guards, I could leave now. With your protection, I have no doubt that we can see these goods safely to Auberdine.",logDesc="Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest.",choiceRewards={{id=5323,qty=1},{id=6721,qty=1}}} end
if not DB[977] then DB[977]={id=977,zoneId=618,name="Are We There, Yeti?",level=58,minLevel=52,giver="Umi Rumplesnicker",giverType="NPC",giverId=10305,ender="Umi Rumplesnicker",enderType="NPC",enderId=10305,rewardNextId=5163,poiX=6753,poiY=-4639,wowhead="https://www.wowhead.com/wotlk/quest=977",image="assets/images/quests/placeholder.png",xpDiff=4,money=9000,desc="Now that I have what I need to cover the mechanical moving parts, I only need one other thing. Well, actually two. Two horns!$B$BThe ice thistle patriarchs and matriarchs have the largest horns, so of course, those are the ones I want. That type of yeti inhabits a cave to the southeast. There are plenty of them there; you shouldn't have any problem finding them.$B$BRemember, I only want the best looking ones -- no beat up or broken horns, please!",logDesc="Collect 2 Pristine Yeti Horns for Umi Rumplesnicker in Everlook."} end
if not DB[978] then DB[978]={id=978,zoneId=702,name="Moontouched Wildkin",level=55,minLevel=52,giver="Erelas Ambersky",giverType="NPC",giverId=7916,ender="Erelas Ambersky",enderType="NPC",enderId=7916,rewardNextId=979,poiX=8707,poiY=989,wowhead="https://www.wowhead.com/wotlk/quest=978",image="assets/images/quests/placeholder.png",xpDiff=5,money=8500,desc="Wildkin feathers from the Hinterlands appear to contain traces of magical qualities. These powers... they don't seem to be wielded by the creatures, it's more like they are simply inherent to the species -- part of their very essence.$B$BDuring my studies, I heard that a large population of wildkin inhabit the snowy lands of Winterspring. Could these creatures have the same powers? Please help me find an answer, $N. Go to Winterspring and gather feathers that have dropped to the ground, then return to me.",logDesc="Collect 10 Moontouched Feathers from Winterspring, then return to Erelas Ambersky in Rut'theran Village."} end
if not DB[979] then DB[979]={id=979,zoneId=702,name="Find Ranshalla",level=57,minLevel=52,giver="Erelas Ambersky",giverType="NPC",giverId=7916,ender="Ranshalla",enderType="NPC",enderId=10300,poiX=8707,poiY=989,wowhead="https://www.wowhead.com/wotlk/quest=979",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Yes, yes, these feathers seem to hold the same magical enchantment that I noticed previously... While I am not certain what we might find, I urge you to continue searching for answers, $N.$B$BA colleague of mine recently traveled into Winterspring to observe the wildkin there, in their own habitat. Why don't you catch up with her and see what she has found?",logDesc="Find Ranshalla in eastern Winterspring."} end
if not DB[980] then DB[980]={id=980,zoneId=490,name="The New Springs",level=55,minLevel=51,giver="Krakle",giverType="NPC",giverId=10302,ender="Donova Snowden",enderType="NPC",enderId=9298,rewardNextId=4842,poiX=-7211,poiY=-611,wowhead="https://www.wowhead.com/wotlk/quest=980",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Now, I've heard about other hot springs in a place called Winterspring, far to the north of here. The strange thing is, there are no volcanoes anywhere near them. Interesting, I know.$B$BWell, if you want to find out more, you should head to Winterspring and speak to a friend of mine. Her name is Donova Snowden, and she is currently staying by the hot springs there.$B$BThanks again for helping me with my thermometer! See you later!",logDesc="Travel to Winterspring and speak with Donova Snowden."} end
if not DB[981] then DB[981]={id=981,zoneId=148,name="The Tower of Althalaxx",level=31,minLevel=13,giver="Balthule Shadowstrike",giverType="NPC",giverId=3661,ender="Delgren the Purifier",enderType="NPC",enderId=3663,poiX=7247,poiY=-659,wowhead="https://www.wowhead.com/wotlk/quest=981",image="assets/images/quests/placeholder.png",xpDiff=5,desc="For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered.",logDesc="Talk to Delgren the Purifier at Maestra's Post.",choiceRewards={{id=10043,qty=1},{id=5614,qty=1}}} end
if not DB[982] then DB[982]={id=982,zoneId=148,name="Deep Ocean, Vast Sea",level=17,minLevel=13,giver="Gorbold Steelhand",giverType="NPC",giverId=6301,ender="Gorbold Steelhand",enderType="NPC",enderId=6301,poiX=6536,poiY=446,wowhead="https://www.wowhead.com/wotlk/quest=982",image="assets/images/quests/placeholder.png",xpDiff=5,money=1800,desc="Off the coast of Darkshore to our north are two wrecked ships - the Silver Dawning and the Mist Veil.  Some time ago, both ships ran afoul of the blasted murlocs as they sailed across the vast sea into Auberdine.  They now lie at the bottom of the ocean as trophies for those fiends.$B$BBoth captains didn't make it out that night, and their logs and other effects are still below in lockboxes.  I'd like for you to recover them for us; it would mean a lot to the crew members still around these parts.",logDesc="Recover the Silver Dawning's Lockbox and the Mist Veil's Lockbox for Gorbold Steelhand in Auberdine.  Both items should be found aboard the wreckage of the ships to the north of the village.",choiceRewards={{id=15401,qty=1},{id=15402,qty=1}}} end
if not DB[983] then DB[983]={id=983,zoneId=148,name="Buzzbox 827",level=10,minLevel=7,giver="Wizbang Cranktoggle",giverType="NPC",giverId=3666,rewardNextId=1001,poiX=6406,poiY=520,wowhead="https://www.wowhead.com/wotlk/quest=983",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="Hey! Help me with my latest invention, the buzzbox. You can talk to people far away!$B$BMaybe you've already seen them, they're boxes with levers on them. The only problem is they need constant maintenance.$B$BEach one suffers from a different problem, but I made a really smart decision. I placed each one near creatures that have the proper parts to fix that particular machine. Right now Buzzbox 827 is on the fritz. It's just south of Auberdine, real close. It takes 6 Crawler Legs to fix it. I'll pay ya...",logDesc="Collect 6 Crawler Legs and place them in Buzzbox 827."} end
if not DB[984] then DB[984]={id=984,zoneId=148,name="How Big a Threat?",level=14,minLevel=10,giver="Terenthis",giverType="NPC",giverId=3693,ender="Terenthis",enderType="NPC",enderId=3693,rewardNextId=985,poiX=6435,poiY=363,wowhead="https://www.wowhead.com/wotlk/quest=984",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Some of my brethren were rescued from a corrupt furbolg in Teldrassil, and I've vowed to stop any more atrocities before more of our kind are injured... or worse.$B$BI have seen a couple hints of corruption in Darkshore already, but I have yet to find any widespread signs. I think it would be logical if the investigation continued with the furbolgs. Would you find one of their camps, and return to me if you see any signs of corruption?",logDesc="Find a corrupt furbolg camp in Darkshore and return to Terenthis in Auberdine."} end
if not DB[985] then DB[985]={id=985,zoneId=148,name="How Big a Threat?",level=14,minLevel=10,giver="Terenthis",giverType="NPC",giverId=3693,ender="Terenthis",enderType="NPC",enderId=3693,poiX=6435,poiY=363,wowhead="https://www.wowhead.com/wotlk/quest=985",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You've already proven adept at scouting our enemy, $N. Do you have what it takes to fight them as well?$B$BNot all adventurers prefer straightforward combat to the art of stealth and evasion.$B$BIf you think you're up for the task, then the furbolg camp south of Auberdine is currently the biggest threat to our people. You'll find some of the Blackwood tribe there. Kill 8 pathfinders and 5 windtalkers, and return to me here.",logDesc="Kill 8 Blackwood Pathfinders and 5 Windtalkers and return to Terenthis in Auberdine."} end
if not DB[986] then DB[986]={id=986,zoneId=148,name="A Lost Master",level=20,minLevel=10,giver="Terenthis",giverType="NPC",giverId=3693,ender="Terenthis",enderType="NPC",enderId=3693,poiX=6435,poiY=363,wowhead="https://www.wowhead.com/wotlk/quest=986",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N, your skills have already helped me in my endeavor. Could I impose on you again to help Grimclaw and his master Volcor? In addition, I can craft you a magical cloak that will allow you to walk unhindered by Darkshore's creatures while you look for him.$B$BTo create the cloak, I'll need five fine moonstalker pelts from a moonstalker sire or matriarch to have enough material. The cats can be found near Wildbend River to the south, or even farther south near Ashenvale.",logDesc="Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine."} end
if not DB[987] then DB[987]={id=987,zoneId=-82,name="<UNUSED>",level=30,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=987",image="assets/images/quests/placeholder.png"} end
if not DB[988] then DB[988]={id=988,zoneId=148,name="<UNUSED>",level=20,minLevel=10,rewardNextId=995,wowhead="https://www.wowhead.com/wotlk/quest=988",image="assets/images/quests/placeholder.png",desc="I noticed the cloak you are wearing,$N. If you'd be willing to sacrifice it,I can renew its magics,and use it to escape. The problem with that,though,is you'll be left here in the cave alone.$B$BAre you able to make it out of here on your own if we choose that course?$B$BI can assure you that Terenthis will reward you for aiding me,if that is your concern.$B$BThe choice is yours,but I could really use your help.",logDesc="Speak to Volcor."} end
if not DB[989] then DB[989]={id=989,zoneId=148,name="<UNUSED>",level=22,minLevel=10,rewardNextId=994,wowhead="https://www.wowhead.com/wotlk/quest=989",image="assets/images/quests/placeholder.png",desc="If we decide to fight our way out,the plan is simple: we'll make our way down to the road and kill any furbolgs that get in our way... or anything else that decides it wants to stop us.$B$BI wish there was another way,but sooner or later the furbolg threat would have to be dealt with. Better it be by our own hands,so we know the job is done.$B$BTake a moment to prepare any magic or weapons you have at your disposal,then speak to me again.",logDesc="Speak to Volcor."} end
if not DB[990] then DB[990]={id=990,zoneId=331,name="Trek to Ashenvale",level=19,minLevel=15,giver="Sentinel Selarin",giverType="NPC",giverId=3694,ender="Raene Wolfrunner",enderType="NPC",enderId=3691,wowhead="https://www.wowhead.com/wotlk/quest=990",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, my mistress, Raene Wolfrunner, awaits you in the city of Astranaar within Ashenvale. With your help, perhaps we can at least ease some of the corruption that's taken hold there.$B$BHead south from here and stay close to the road--you'll find your way there without issue if you follow those directions.",logDesc="Find Raene Wolfrunner in Ashenvale."} end
if not DB[991] then DB[991]={id=991,zoneId=331,name="Raene's Cleansing",level=19,minLevel=18,giver="Raene Wolfrunner",giverType="NPC",giverId=3691,ender="Teronis' Corpse",enderType="NPC",enderId=3891,rewardNextId=1023,poiX=2767,poiY=-412,wowhead="https://www.wowhead.com/wotlk/quest=991",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N, a longtime friend of mine is also aiding the Sentinels here in Ashenvale, but he has yet to return.$B$BHe had leads on finding an item that he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.$B$BBefore he left here, he mentioned seeking out a gem for the rod.$B$BHe mentioned the gem possibly being hidden at the shrine in Lake Falathim at the base of the mountain to the west. The gem was being held there before it was overrun.$B$BFind my friend, $N, please.",logDesc="Find Teronis in Ashenvale."} end
if not DB[992] then DB[992]={id=992,zoneId=440,name="Gadgetzan Water Survey",level=46,minLevel=38,giver="Senior Surveyor Fizzledowser",giverType="NPC",giverId=7724,ender="Senior Surveyor Fizzledowser",enderType="NPC",enderId=7724,rewardNextId=82,poiX=-7139,poiY=-3683,wowhead="https://www.wowhead.com/wotlk/quest=992",image="assets/images/quests/placeholder.png",xpDiff=4,money=3500,desc="We've got a position open for a temporary junior-grade surveyor in the Gadgetzan Water Company, if you're interested!$B$BWith the nomads seizing all our wells, we need to exploit more free sources of water!  There is water to be had in the desert, but only to those smart enough to survey them first.$B$BTake this dowsing widget and tap a sample of the water by the pool near Sandsorrow Watch.  It's right in sight of the trolls around there.  Bring the tapped widget back to me when you're done!",logDesc="Use the untapped dowsing widget near the pool of water by Sandsorrow Watch.  Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan."} end
if not DB[993] then DB[993]={id=993,zoneId=148,name="A Lost Master",level=20,minLevel=10,giver="Terenthis",giverType="NPC",giverId=3693,ender="Volcor",enderType="NPC",enderId=3692,poiX=6435,poiY=363,wowhead="https://www.wowhead.com/wotlk/quest=993",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The cloak is complete, $N. The time has come to find Volcor. I can only hope we are in time.$B$BThe cloak's magic, once invoked, will not last long; perhaps five minutes. It will be up to you to know when to use it: I would suggest waiting until you find Grimclaw.$B$BIf what he has told me is true, you will find his master in a cave south of here. Grimclaw will be alongside the road waiting for you. Signal to him by waving when you see him, and he'll point the way towards his master.",logDesc="Find Volcor in Darkshore and give him the Enchanted Moonstalker Cloak."} end
if not DB[994] then DB[994]={id=994,zoneId=148,name="Escape Through Force",level=22,minLevel=10,giver="Volcor",giverType="NPC",giverId=3692,ender="Terenthis",enderType="NPC",enderId=3693,poiX=4608,poiY=-6,wowhead="https://www.wowhead.com/wotlk/quest=994",image="assets/images/quests/placeholder.png",xpDiff=5,money=1400,desc="All right, $N, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there. Once there, we can part ways.$B$BTerenthis will want to hear your version of the story immediately, so head to Auberdine after we make it out of here.",logDesc="Protect Volcor until you reach the road, then speak to Terenthis in Auberdine.",rewards={{id=5609,qty=1}}} end
if not DB[995] then DB[995]={id=995,zoneId=148,name="Escape Through Stealth",level=20,minLevel=10,giver="Volcor",giverType="NPC",giverId=3692,ender="Terenthis",enderType="NPC",enderId=3693,poiX=4608,poiY=-6,wowhead="https://www.wowhead.com/wotlk/quest=995",image="assets/images/quests/placeholder.png",xpDiff=3,money=600,desc="All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready.$B$BRemember, after you've escaped, meet Terenthis back in Auberdine. I'll head there on my own since I'll probably be moving faster than you.",logDesc="Escape the Furbolg cave and meet Terenthis in Auberdine.",rewards={{id=6659,qty=1}}} end
if not DB[996] then DB[996]={id=996,zoneId=361,name="Corrupted Windblossom",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=996",image="assets/images/quests/placeholder.png"} end
if not DB[997] then DB[997]={id=997,zoneId=141,name="Denalan's Earth",level=5,minLevel=4,giver="Syral Bladeleaf",giverType="NPC",giverId=2083,ender="Denalan",enderType="NPC",enderId=2080,poiX=9872,poiY=959,wowhead="https://www.wowhead.com/wotlk/quest=997",image="assets/images/quests/placeholder.png",xpDiff=3,money=50,desc="Are you heading to the south?  To Lake Al'Ameth?  If so, then I have a task I might ask of you...$B$BMy colleague Denalan has a camp along the eastern end of the lake, where he is studying and experimenting on the plant life of Teldrassil.  He requested a package of rare earths from Darnassus and it was late, only recently arriving here in Dolanaar.$B$BCan you take the package to him?",logDesc="Bring the package of Rare Earth to Denalan at Lake Al'Ameth."} end
if not DB[998] then DB[998]={id=998,zoneId=361,name="Corrupted Windblossom",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=998",image="assets/images/quests/placeholder.png"} end
if not DB[999] then DB[999]={id=999,zoneId=718,name="When Dreams Turn to Nightmares",level=25,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=999",image="assets/images/quests/placeholder.png"} end
if not DB[1000] then DB[1000]={id=1000,zoneId=1638,name="The New Frontier",level=55,minLevel=54,giver="Bluff Runner Windstrider",giverType="NPC",giverId=10881,ender="Arch Druid Hamuul Runetotem",enderType="NPC",enderId=5769,rewardNextId=1123,poiX=-1231,poiY=137,wowhead="https://www.wowhead.com/wotlk/quest=1000",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!",logDesc="Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor."} end
if not DB[1001] then DB[1001]={id=1001,zoneId=148,name="Buzzbox 411",level=12,minLevel=7,rewardNextId=1002,wowhead="https://www.wowhead.com/wotlk/quest=1001",image="assets/images/quests/placeholder.png",xpDiff=6,money=1000,desc="A tiny voice crackles from deep within the machine.$B$B\"Wizbang here! The next Buzzbox is north of Auberdine, on the beach$B$BSo, that Buzzbox is number 411 and it needs 3 Thresher Eyes for its repairs. They're just off the coast! The darkshore threshers... *Hic*... Sorry about that...$B$BJust like last time, when you give the Buzzbox the goods, it'll spit out your reward. *Hic*... What? No, I'm fine!\"",logDesc="Collect 3 Thresher Eyes from Darkshore Threshers in the deep sea near Buzzbox 411."} end
if not DB[1002] then DB[1002]={id=1002,zoneId=148,name="Buzzbox 323",level=14,minLevel=7,rewardNextId=1003,wowhead="https://www.wowhead.com/wotlk/quest=1002",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="The Buzzbox gives a burst of static as you hear Wizbang begin to speak.$B$B\"The next Buzzbox is number 323. Ish north of Auberdine but... where's the ale? Wha? Oh, ish on the road sho ya shouldn't have trouble finding it near the bridge.\"$B$BWizbang mumbles something incoherent before you hear a loud gulping sound.$B$B\"Thish one needs Moonstalker Fangs... 6 of 'em.\"",logDesc="Collect 6 Moonstalker Fangs and place them in Buzzbox 323."} end
if not DB[1003] then DB[1003]={id=1003,zoneId=148,name="Buzzbox 525",level=16,minLevel=7,wowhead="https://www.wowhead.com/wotlk/quest=1003",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="Over the boiling noises and dripping sounds coming from the machine, you hear Wizbang's wavering voice call out.$B$B\"Nexsht onesh far south down the road. Shouldn't be hard to find... jusht off to the shide... near a fensh. I think I hid it in shum bushesh... Bushessh. Hehehe... Yesh, Buzzbox 525 takes grizzled scalps from thoshe grizzled thistle bears. Boy thash a mouthful. Grizzshled... Hehehe...\"$B$BYou hear more gulping sounds as the machine cuts out. Then, suddenly, it bursts back to life.$B$B\"4!\"",logDesc="Collect 4 Grizzled Scalps from Grizzled Thistle Bears to the south of Auberdine and place them in Buzzbox 525.",rewards={{id=2082,qty=1},{id=11846,qty=5}}} end
if not DB[1004] then DB[1004]={id=1004,zoneId=1497,name="The New Frontier",level=55,minLevel=54,giver="Harbinger Balthazad",giverType="NPC",giverId=10879,ender="Arch Druid Hamuul Runetotem",enderType="NPC",enderId=5769,rewardNextId=1123,poiX=1570,poiY=215,wowhead="https://www.wowhead.com/wotlk/quest=1004",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!",logDesc="Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor."} end
if not DB[1005] then DB[1005]={id=1005,zoneId=236,name="What Lurks Beyond",level=20,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=1005",image="assets/images/quests/placeholder.png"} end
if not DB[1006] then DB[1006]={id=1006,zoneId=236,name="What Lies Beyond",level=18,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=1006",image="assets/images/quests/placeholder.png"} end
if not DB[1007] then DB[1007]={id=1007,zoneId=331,name="The Ancient Statuette",level=20,minLevel=19,giver="Talen",giverType="NPC",giverId=3846,ender="Talen",enderType="NPC",enderId=3846,poiX=3470,poiY=847,wowhead="https://www.wowhead.com/wotlk/quest=1007",image="assets/images/quests/placeholder.png",xpDiff=4,money=900,desc="I would charge you with a task, $N.$B$BI was on my small vessel, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws!  I fled, carrying what supplies I could to make this meager camp.$B$BBut when I reached the shore and ran... my prized possession was lost.$B$BPlease, $N, find the site of my ambush, along the coast to the north, and search for an ancient statuette.  It is the reason I have braved the dangers of the Zoram Strand.",logDesc="Bring the Ancient Statuette to Talen, in his camp near the Zoram Strand."} end
if not DB[1008] then DB[1008]={id=1008,zoneId=331,name="The Zoram Strand",level=19,minLevel=14,giver="Shindrell Swiftfire",giverType="NPC",giverId=3845,ender="Shindrell Swiftfire",enderType="NPC",enderId=3845,poiX=2796,poiY=-299,wowhead="https://www.wowhead.com/wotlk/quest=1008",image="assets/images/quests/placeholder.png",xpDiff=5,money=1100,desc="There is evil lurking on our northwestern coast, known as the Zoram Strand.$B$BIt is the resting place of the doomed city of Zoram, destroyed during the Sundering and submerged beneath the seas.  It has been lost to the night elves for ages.  Lost, and nearly forgotten.$B$BNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must slay these fiends and throw them back to the depths!$B$BReturn to me when your mission is complete.",logDesc="Bring 20 Wrathtail Heads to Shindrell Swiftfire in Astranaar."} end
if not DB[1009] then DB[1009]={id=1009,zoneId=331,name="Ruuzel",level=25,minLevel=20,giver="Talen",giverType="NPC",giverId=3846,ender="Talen",enderType="NPC",enderId=3846,poiX=3470,poiY=847,wowhead="https://www.wowhead.com/wotlk/quest=1009",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I fear the ancient statuette's secrets will remain forever hidden unless you find the key to its ancient lock.$B$BThat key is a ring, the Ring of Zoram.  It belonged to the rulers of this city before the waves of the Sundering drowned it.$B$BFor years the ring was lost, but the naga have recently found it.$B$BTheir leader, Ruuzel, dwells on an isle on the northern edge of Zoram.  Please, $N, retrieve the ring for me!",logDesc="Bring the Ring of Zoram to Talen near the Zoram Strand.",rewards={{id=5812,qty=1}}} end
if not DB[1010] then DB[1010]={id=1010,zoneId=331,name="Bathran's Hair",level=20,minLevel=20,giver="Orendil Broadleaf",giverType="NPC",giverId=3847,ender="Orendil Broadleaf",enderType="NPC",enderId=3847,poiX=3190,poiY=175,wowhead="https://www.wowhead.com/wotlk/quest=1010",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There is a plant that once grew in the old ruins of Bathran's Haunt to the north.  The plant was called Bathran's Hair and was known to cure ailments of the spirit.$B$BThere is a sick child in the village, and I believe it is more than just a physical illness.  Will you go to Bathran's Haunt and search it for Bathran's Hair?  I may need it to properly treat the child.$B$BBathran's Haunt lies north of Maestra's Post and just south of the border to Darkshore.",logDesc="Bring 5 Bathran's Hair to Orendil Broadleaf in Ashenvale."} end
if not DB[1011] then DB[1011]={id=1011,zoneId=331,name="Forsaken Diseases",level=29,minLevel=24,giver="Kayneth Stillwind",giverType="NPC",giverId=3848,ender="Kayneth Stillwind",enderType="NPC",enderId=3848,poiX=2954,poiY=-3215,wowhead="https://www.wowhead.com/wotlk/quest=1011",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Forsaken, the undead arm of the Horde, have crept into Ashenvale, lurking at our ruins and our barrows.  We believe their goal is to spread disease amongst the lands of the night elves.  We must confirm this!$B$BThe Forsaken have a camp south of here, near the Dor'Danil Barrow Den, where they create poisons and diseases and place them in bottles.  Fight your way into that camp and steal a bottle of disease.  Return with such a bottle.  I will test it and find its purpose.",logDesc="Bring a Bottle of Disease to Kayneth Stillwind in Forest Song."} end
if not DB[1012] then DB[1012]={id=1012,zoneId=331,name="Insane Druids",level=32,minLevel=24,giver="Kayneth Stillwind",giverType="NPC",giverId=3848,ender="Kayneth Stillwind",enderType="NPC",enderId=3848,poiX=2954,poiY=-3215,wowhead="https://www.wowhead.com/wotlk/quest=1012",image="assets/images/quests/placeholder.png",xpDiff=6,desc="When I struggled with the Forsaken's poisons, I had a vision.  I had a vision of the druids in the Dor'danil Barrow Den, poisoned... murdered by the undead!  They are now errant ghosts, severed from their bodies and driven mad.$B$BSo that the druids' spirits might some day find peace, you must enter the Dor'danil Barrow Den and destroy its once great leaders: Taneel Darkwood, Uthil Mooncall and Mavoris Cloudsbreak.$B$BDo this, then return to me.",logDesc="Kill the druids: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; then return to Kayneth Stillwind in Forest Song.",rewards={{id=5813,qty=1}}} end
if not DB[1013] then DB[1013]={id=1013,zoneId=209,name="The Book of Ur",level=26,minLevel=16,giver="Keeper Bel'dugur",giverType="NPC",giverId=2934,ender="Keeper Bel'dugur",enderType="NPC",enderId=2934,poiX=1529,poiY=358,wowhead="https://www.wowhead.com/wotlk/quest=1013",image="assets/images/quests/placeholder.png",xpDiff=7,desc="$N, Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection.  Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to ... certain parties among the Forsaken.$B$BEnter Shadowfang Keep and find the book.  Bring it to me, and I will report your service to our Dark Lady...",logDesc="Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.",choiceRewards={{id=6335,qty=1},{id=4534,qty=1}}} end
if not DB[1014] then DB[1014]={id=1014,zoneId=209,name="Arugal Must Die",level=27,minLevel=18,giver="Dalar Dawnweaver",giverType="NPC",giverId=1938,ender="Dalar Dawnweaver",enderType="NPC",enderId=1938,poiX=553,poiY=1594,wowhead="https://www.wowhead.com/wotlk/quest=1014",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain.$b$bI shall see to it that his magic is eradicated, $n. But I leave it in your hands to see that Arugal meets the death he so deserves.$b$bTravel to Shadowfang Keep and put an end to Arugal's foul spells once and for all. Bring to me the vile wizard's head!",logDesc="Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.",rewards={{id=6414,qty=1}}} end
if not DB[1015] then DB[1015]={id=1015,zoneId=1519,name="The New Frontier",level=55,minLevel=54,giver="Crier Goodman",giverType="NPC",giverId=2198,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,rewardNextId=6761,poiX=-8854,poiY=743,wowhead="https://www.wowhead.com/wotlk/quest=1015",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!",logDesc="Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor."} end
if not DB[1016] then DB[1016]={id=1016,zoneId=331,name="Elemental Bracers",level=24,minLevel=20,giver="Sentinel Velene Starstrike",giverType="NPC",giverId=3885,ender="Sentinel Velene Starstrike",enderType="NPC",enderId=3885,rewardNextId=1017,poiX=2090,poiY=-1172,wowhead="https://www.wowhead.com/wotlk/quest=1016",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Take this divining scroll--it can determine the creator of these elementals. But you will need something from them to use as a reagent to focus scroll's magic--their bracers should do nicely.$B$BA few intact bracers from the creatures should be enough. The other bracers will be useless for our purposes, but they may be worth something to a merchant if you wish to sell them. Once you have the intact bracers attempt to use the scroll. Return to me with the results and we shall proceed from there.",logDesc="Collect 5 Intact Elemental Bracers and use the Divining Scroll on them. Afterwards, bring the Divined Scroll to Sentinel Velene Starstrike at the Silverwind Refuge."} end
if not DB[1017] then DB[1017]={id=1017,zoneId=331,name="Mage Summoner",level=25,minLevel=20,giver="Sentinel Velene Starstrike",giverType="NPC",giverId=3885,ender="Sentinel Velene Starstrike",enderType="NPC",enderId=3885,poiX=2090,poiY=-1172,wowhead="https://www.wowhead.com/wotlk/quest=1017",image="assets/images/quests/placeholder.png",xpDiff=6,desc="There's only one undead mage in the Barrens capable of defiling this many water elementals. He's also the only one foolish enough to try. Sarilus Foulborne is probably sitting at the top of Dreadmist Peak, laughing at me.$B$B$n, you must go into enemy territory and destroy this miscreant. I have had enough of his idiocy and we must show him what happens to those who annoy the Sentinels.$B$BDestroy him and bring me his head. Be wary though, the Horde may be watching for you.",logDesc="Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge.",rewards={{id=5816,qty=1}}} end
if not DB[1018] then DB[1018]={id=1018,zoneId=1637,name="The New Frontier",level=55,minLevel=54,giver="Warcaller Gorlach",giverType="NPC",giverId=10880,ender="Arch Druid Hamuul Runetotem",enderType="NPC",enderId=5769,rewardNextId=1123,poiX=1569,poiY=-4207,wowhead="https://www.wowhead.com/wotlk/quest=1018",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!",logDesc="Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor."} end
if not DB[1019] then DB[1019]={id=1019,zoneId=1537,name="The New Frontier",level=55,minLevel=54,giver="Courier Hammerfall",giverType="NPC",giverId=10877,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,rewardNextId=6761,poiX=-4999,poiY=-1156,wowhead="https://www.wowhead.com/wotlk/quest=1019",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!",logDesc="Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor."} end
if not DB[1020] then DB[1020]={id=1020,zoneId=331,name="Orendil's Cure",level=20,minLevel=20,giver="Orendil Broadleaf",giverType="NPC",giverId=3847,ender="Pelturas Whitemoon",enderType="NPC",enderId=3894,poiX=3190,poiY=175,wowhead="https://www.wowhead.com/wotlk/quest=1020",image="assets/images/quests/placeholder.png",xpDiff=6,money=2500,desc="$N, I have created a cure that I believe will help the afflicted child.  Take it to Astranaar and give it to the child's parent, Pelturas Whitemoon.$B$BTo reach Astranaar, follow the road south, then east.",logDesc="Bring Orendil's Cure to Pelturas Whitemoon in Astranaar."} end
if not DB[1021] then DB[1021]={id=1021,zoneId=331,name="Vile Satyr! Dryads in Danger!",level=32,minLevel=26,giver="Illiyana",giverType="NPC",giverId=3901,ender="Anilia",enderType="NPC",enderId=3920,rewardNextId=1031,poiX=3001,poiY=-3323,wowhead="https://www.wowhead.com/wotlk/quest=1021",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days!$B$B$n, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.",logDesc="Find Anilia in Xavian in Ashenvale."} end
if not DB[1022] then DB[1022]={id=1022,zoneId=331,name="The Howling Vale",level=30,minLevel=25,giver="Sentinel Melyria Frostshadow",giverType="NPC",giverId=3880,ender="Sentinel Melyria Frostshadow",enderType="NPC",enderId=3880,rewardNextId=1037,poiX=2977,poiY=-3261,wowhead="https://www.wowhead.com/wotlk/quest=1022",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="Though we have put many resources and much effort into driving the remaining demons from the Felwood to the north, our successes have been few. We have been able to keep much of the demonic presence from Ashenvale.$b$bTo the north, near the Felwood border, the ruined shrine of Mel'Thandris has been overtaken by mysterious wolf-men. Their chilling calls have led the area to be known as the Howling Vale. The Tome of Mel'Thandris kept at the shrine may shed some light on why these wolf-men have come.",logDesc="Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song."} end
if not DB[1023] then DB[1023]={id=1023,zoneId=331,name="Raene's Cleansing",level=21,minLevel=18,giver="Teronis' Corpse",giverType="NPC",giverId=3891,ender="Raene Wolfrunner",enderType="NPC",enderId=3691,poiX=3046,poiY=529,wowhead="https://www.wowhead.com/wotlk/quest=1023",image="assets/images/quests/placeholder.png",xpDiff=4,desc="As you rummage through Teronis' belongings, you find a journal that is still in good condition.$B$BYou take the journal and leave Teronis' corpse as is.$B$BThe only thing left to do is find the gem Teronis was seeking. Raene mentioned it being in the area. Perhaps the murlocs have it...",logDesc="Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal."} end
if not DB[1024] then DB[1024]={id=1024,zoneId=331,name="Raene's Cleansing",level=21,minLevel=18,giver="Raene Wolfrunner",giverType="NPC",giverId=3691,ender="Shael'dryn",enderType="NPC",enderId=3916,rewardNextId=1026,poiX=2767,poiY=-412,wowhead="https://www.wowhead.com/wotlk/quest=1024",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You'll have to do the research yourself, but from what notes Teronis has made, it sounds like your next course of action is to find the other pieces of the rod Dartol created. I would start by heading to the moonwell east of Iris Lake. When you're ready, follow the road and turn north when you reach a small sitting area on your left.$B$BA dryad there named Shael'dryn is better suited to guide you. Seek her out.$B$BKeep the gem with you--Shael'dryn will need it if she's to help you recreate the rod.",logDesc="Find Shael'dryn at the moonwell to the northeast."} end
if not DB[1025] then DB[1025]={id=1025,zoneId=331,name="An Aggressive Defense",level=24,minLevel=18,giver="Raene Wolfrunner",giverType="NPC",giverId=3691,ender="Raene Wolfrunner",enderType="NPC",enderId=3691,poiX=2767,poiY=-412,wowhead="https://www.wowhead.com/wotlk/quest=1025",image="assets/images/quests/placeholder.png",xpDiff=5,money=1700,desc="Before you travel to the moonwell I have another task that will aid the people of Ashenvale if you would like to test your skills.$B$BAlong the road heading east before the Falfarren River, furbolgs have been attacking travelers. Their tortured minds feeding upon fear, and their appetites satiated by the blood of innocents.$B$BAid the Sentinels in protecting the lands by showing those monsters the same mercy they have shown our kind.$B$BI believe their camps are south of the road... be careful.",logDesc="Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar.",rewards={{id=4542,qty=10},{id=1205,qty=10}}} end
if not DB[1026] then DB[1026]={id=1026,zoneId=331,name="Raene's Cleansing",level=27,minLevel=18,giver="Shael'dryn",giverType="NPC",giverId=3916,ender="Shael'dryn",enderType="NPC",enderId=3916,rewardNextId=1027,poiX=2896,poiY=-1387,wowhead="https://www.wowhead.com/wotlk/quest=1026",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I wish your tidings were better.$B$BRaene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted.$B$BIf your goal is to find the next piece of the rod, then you'll have to find the key to open the chest it's in.$B$BThe wooden key is on one of the treants northeast of here, near Felwood. Once you have it, look for a small glade west of the road near the Felwood border... the chest should be hidden around there.",logDesc="Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell."} end
if not DB[1027] then DB[1027]={id=1027,zoneId=331,name="Raene's Cleansing",level=28,minLevel=18,giver="Shael'dryn",giverType="NPC",giverId=3916,ender="Shael'dryn",enderType="NPC",enderId=3916,rewardNextId=1028,poiX=2896,poiY=-1387,wowhead="https://www.wowhead.com/wotlk/quest=1027",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The final piece of the rod was given to the druids of Dor'danil for safekeeping. I have no idea where they hid it. I'm sorry I can't help you more than that.$B$BAll I can tell you is to follow the road that leads towards the Barrens. The druids took shelter to the east of that road, but they won't be of much help to you: they were killed recently... it's something I don't like to think about much.$B$BWhen you find the final piece, bring it to me and I will help you reconstruct the rod.",logDesc="Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell."} end
if not DB[1028] then DB[1028]={id=1028,zoneId=331,name="Raene's Cleansing",level=28,minLevel=18,giver="Shael'dryn",giverType="NPC",giverId=3916,rewardNextId=1055,poiX=2896,poiY=-1387,wowhead="https://www.wowhead.com/wotlk/quest=1028",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Here is the completed rod, $N. Reconstructing it was simple... it's finding the shrine that has the power to recharge it that will be the hard part.$B$BWith some focus and effort it shouldn't be too hard for someone like you, who's already accomplished so much.$B$BHead southeast of here--there are very few paths, so be careful--and keep your eyes to the north. The shrine is hidden within the mountains that surround this glade.$B$BOnce there, place the rod within the shrine... the rest is magic. Hehe.",logDesc="Find the hidden shrine and re-enchant Dartol's Rod.",rewards={{id=5462,qty=1}}} end
if not DB[1029] then DB[1029]={id=1029,zoneId=331,name="Raene's Cleansing",level=28,minLevel=18,giver="Shael'dryn",giverType="NPC",giverId=3916,ender="Raene Wolfrunner",enderType="NPC",enderId=3691,rewardNextId=1030,poiX=2896,poiY=-1387,wowhead="https://www.wowhead.com/wotlk/quest=1029",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be.$B$BGood luck, $N.",logDesc="Return to Raene Wolfrunner in Astranaar."} end
if not DB[1030] then DB[1030]={id=1030,zoneId=331,name="Raene's Cleansing",level=28,minLevel=18,giver="Raene Wolfrunner",giverType="NPC",giverId=3691,ender="Krolg",enderType="NPC",enderId=3897,rewardNextId=1045,poiX=2767,poiY=-412,wowhead="https://www.wowhead.com/wotlk/quest=1030",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Alas, I'm not completely certain what he had in mind next.$B$BIf what he said was true about the rod's power, then it will allow you to take on another form altogether. Which form, I do not know.$B$BPerhaps he meant to use its powers to get closer to the tainted furbolgs, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was safe from the effects of Fel Moss.$B$BI would start your search southeast of Mystral Lake.",logDesc="Find an uncorrupted furbolg, and using the power of Dartol's Rod of Transformation, speak to him."} end
if not DB[1031] then DB[1031]={id=1031,zoneId=331,name="The Branch of Cenarius",level=32,minLevel=26,giver="Anilia",giverType="NPC",giverId=3920,ender="Illiyana",enderType="NPC",enderId=3901,poiX=2950,poiY=-2817,wowhead="https://www.wowhead.com/wotlk/quest=1031",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. \"He has taken it... Geltharis...\" You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.",logDesc="Kill Geltharis and return the Branch of Cenarius to Illiyana at Forest Song.",choiceRewards={{id=5820,qty=1},{id=11229,qty=1}}} end
if not DB[1032] then DB[1032]={id=1032,zoneId=331,name="Satyr Slaying!",level=32,minLevel=26,giver="Illiyana",giverType="NPC",giverId=3901,ender="Illiyana",enderType="NPC",enderId=3901,poiX=3001,poiY=-3323,wowhead="https://www.wowhead.com/wotlk/quest=1032",image="assets/images/quests/placeholder.png",xpDiff=5,money=3000,desc="I can't believe that Anilia is gone... We used to play together in the forests all the time. I almost feel... sad.$B$BI know something that might make me feel better. Please, slay the satyrs that took Anilia from me! Bring me their horns as proof of your actions and you will forever have my gratitude.$B$B",logDesc="Bring 16 Satyr Horns to Illiyana in Forest Song."} end
if not DB[1033] then DB[1033]={id=1033,zoneId=331,name="Elune's Tear",level=22,minLevel=20,giver="Pelturas Whitemoon",giverType="NPC",giverId=3894,ender="Pelturas Whitemoon",enderType="NPC",enderId=3894,poiX=2682,poiY=-455,wowhead="https://www.wowhead.com/wotlk/quest=1033",image="assets/images/quests/placeholder.png",xpDiff=5,money=1400,desc="I had hoped Orendil's cure would save Relara, but I fear it only slowed the disease running through my child.  We must find more powerful medicine!  Thankfully, Orendil spoke to me of further remedies to try should his first one fail.$B$BElune's Tear is a type of stone that rests in only one place: the isle on Iris Lake, east of Astranaar.  Orendil said the stone will wash away corruption... please, $N, bring me Elune's Tear and pray it will end my child's sickness!",logDesc="Bring Elune's Tear to Pelturas in Astranaar."} end
if not DB[1034] then DB[1034]={id=1034,zoneId=331,name="The Ruins of Stardust",level=23,minLevel=20,giver="Pelturas Whitemoon",giverType="NPC",giverId=3894,ender="Pelturas Whitemoon",enderType="NPC",enderId=3894,poiX=2682,poiY=-455,wowhead="https://www.wowhead.com/wotlk/quest=1034",image="assets/images/quests/placeholder.png",xpDiff=5,money=1500,desc="Elune's Tear washed clear some of my daughter's sickness.  Her nightmares are lessened and I thank the goddess for her blessing.  But ... fever still rages within her.$B$BOrendil told me of a frosted dust found among the Ruins of Stardust.  Perhaps it will abate Relara's fever.  Gather some of the dust, then please return to me.$B$BThe Ruins of Stardust lie to the south, $N.  May Elune speed your journey.",logDesc="Bring 5 Handfuls of Stardust to Pelturas in Astranaar."} end
if not DB[1035] then DB[1035]={id=1035,zoneId=331,name="Fallen Sky Lake",level=30,minLevel=20,giver="Pelturas Whitemoon",giverType="NPC",giverId=3894,ender="Pelturas Whitemoon",enderType="NPC",enderId=3894,poiX=2682,poiY=-455,wowhead="https://www.wowhead.com/wotlk/quest=1035",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Relara's fever has passed, but she is still very weak.  I do not believe time alone will give her back the strength she has lost.  I believe it will take the power of a moonstone.$B$BWe used to gather moonstones at Fallen Sky Lake to the southeast... until the Shadethickets came.$B$BTheir leader, a Shadethicket Oracle, gathered up all the fallen moonstones and hoards them.  Now, you must retrieve a moonstone from the Oracle.$B$BAnd to do that, I fear that you must slay him.",logDesc="Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar.",choiceRewards={{id=5814,qty=1},{id=6722,qty=1},{id=17047,qty=1}}} end
if not DB[1036] then DB[1036]={id=1036,zoneId=33,name="Avast Ye, Scallywag",level=60,minLevel=55,giver="\"Pretty Boy\" Duncan",giverType="NPC",giverId=2545,ender="Fleet Master Firallon",enderType="NPC",enderId=2546,rewardNextId=4621,poiX=-14122,poiY=474,wowhead="https://www.wowhead.com/wotlk/quest=1036",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N... yeah, I've heard of you.  I've heard that you're no friend of Booty Bay - just like us Bloodsail Buccaneers.  Fleet Master Firallon is looking for hale and hearty $g men : women; just like you for a special mission.$B$BIf you're interested, head on out to the Crimson Veil and speak with him below decks.  She's anchored off the Wild Coast east of here, next to the Riptide and the Damsel's Luck.",logDesc="Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale."} end
if not DB[1037] then DB[1037]={id=1037,zoneId=331,name="Velinde Starsong",level=30,minLevel=25,giver="Sentinel Melyria Frostshadow",giverType="NPC",giverId=3880,ender="Thyn'tel Bladeweaver",enderType="NPC",enderId=8026,rewardNextId=1038,poiX=2977,poiY=-3261,wowhead="https://www.wowhead.com/wotlk/quest=1037",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Velinde Starsong was my predecessor here in Ashenvale Forest. At first it seemed she had the situation in Felwood under control, but little by little her efforts faltered. One day, she simply disappeared.$b$bI was sent here to continue her work. I'm afraid I know nothing of the priestess, however. Perhaps Thyn'tel Bladeweaver, one of the commanders of the Sentinels, knows further details of her disappearance that I was not a party to.$b$bSurely she will understand the import of such information.",logDesc="Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus."} end
if not DB[1038] then DB[1038]={id=1038,zoneId=331,name="Velinde's Effects",level=30,minLevel=25,giver="Thyn'tel Bladeweaver",giverType="NPC",giverId=8026,ender="Thyn'tel Bladeweaver",enderType="NPC",enderId=8026,rewardNextId=1039,poiX=9962,poiY=2285,wowhead="https://www.wowhead.com/wotlk/quest=1038",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The Tome of Mel'Thandris showed you this? I suppose there would be little harm in allowing you to examine her belongings. This key will allow you to open the chest where we stored her things in the Sentinels' bunkhouse. She kept a journal of her duties, if there is anything to be learned, it will be from that.$b$bI should tell you, the Sentinels believe that she had her own reasons for leaving, and expect that she could return at any time. The priestess has done much in the past to earn our trust.",logDesc="Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus."} end
if not DB[1039] then DB[1039]={id=1039,zoneId=331,name="The Barrens Port",level=30,minLevel=25,giver="Thyn'tel Bladeweaver",giverType="NPC",giverId=8026,ender="Wharfmaster Dizzywig",enderType="NPC",enderId=3453,rewardNextId=1040,poiX=9962,poiY=2285,wowhead="https://www.wowhead.com/wotlk/quest=1039",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ratchet is the only port in the Barrens. Most likely Velinde found a trading vessel in Ratchet to take her to Blackwater Cove in Azeroth. We've had limited dealings with the goblins that run the port, but the master of the dock should have information about the comings and goings of ship passengers.$b$bFollow the road southeast through Ashenvale and you will find yourself in the Barrens. Watch your step, $n, warriors of the Horde patrol the land. You will be safe at the port, though.",logDesc="Speak with Wharfmaster Dizzywig at Ratchet in the Barrens."} end
if not DB[1040] then DB[1040]={id=1040,zoneId=331,name="Passage to Booty Bay",level=30,minLevel=25,giver="Wharfmaster Dizzywig",giverType="NPC",giverId=3453,ender="Caravaneer Ruzzgot",enderType="NPC",enderId=3945,rewardNextId=1041,poiX=-986,poiY=-3797,wowhead="https://www.wowhead.com/wotlk/quest=1040",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Ah yes, finally found it. Should have told me she passed through here that long ago. Let's see.$b$bVelinde. Booked passage to Booty Bay on the Black Osprey. I don't have anything here saying otherwise, so I'd assume it arrived in port safely.$b$bNot much more help I can be to you, but she asked about overland travel over on that side of the world, and I mentioned Ruzzgot, a caravan driver based out of Booty Bay. Might be that this Velinde traveled with him.$b$bMove along, now. I haven't all day for you.",logDesc="Take a boat to Booty Bay and speak with Caravaneer Ruzzgot."} end
if not DB[1041] then DB[1041]={id=1041,zoneId=331,name="The Caravan Road",level=30,minLevel=25,giver="Caravaneer Ruzzgot",giverType="NPC",giverId=3945,ender="Clerk Daltry",enderType="NPC",enderId=267,rewardNextId=1042,poiX=-14320,poiY=474,wowhead="https://www.wowhead.com/wotlk/quest=1041",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Turns out I was wrong about you, and that isn't something that happens everyday.$b$bIt just so happens that I remember this Velinde you're looking for. Isn't every day that a night elf priestess that wants to travel with a dirty old--but great for your shipping needs!--caravan like my own.$b$bWe split up on the way north, she was headed for Darkshire. The clerk there keeps all sorts of records. Might know something useful.$b$bBe careful in the jungle, it is a deadly place even at the best of times.",logDesc="Speak with Clerk Daltry in Darkshire."} end
if not DB[1042] then DB[1042]={id=1042,zoneId=331,name="The Carevin Family",level=30,minLevel=25,giver="Clerk Daltry",giverType="NPC",giverId=267,ender="Jonathan Carevin",enderType="NPC",enderId=661,rewardNextId=1043,poiX=-10560,poiY=-1125,wowhead="https://www.wowhead.com/wotlk/quest=1042",image="assets/images/quests/placeholder.png",xpDiff=1,desc="No, I don't have any records of a Velinde Starsong staying in Darkshire... though, if you don't mind me saying, I can hardly imagine a night elf priestess taking a room in the inn, if you get my meaning?$b$bThese wolf-men you mentioned though, that's something I've heard about. Just the other day, Calor came into town with a string of their heads. He works with the Carevin family. Hunters of demons, undead, and other monstrosities. Speak with Jonathan, he's the head of the household.",logDesc="Speak with Jonathan Carevin in Darkshire."} end
if not DB[1043] then DB[1043]={id=1043,zoneId=331,name="The Scythe of Elune",level=30,minLevel=25,giver="Jonathan Carevin",giverType="NPC",giverId=661,ender="Jonathan Carevin",enderType="NPC",enderId=661,rewardNextId=1044,poiX=-10599,poiY=-1200,wowhead="https://www.wowhead.com/wotlk/quest=1043",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="Your story rings true... I do not entirely understand your motives, but if your business here in Duskwood involves ridding the forest of worgen in any number, then I can forgo understanding for results.$b$bThere is a mine to the south that has been overrun with worgen... They appeared out of nowhere, but from what we know, that is where they first were found.$b$bGo about your business, but I would ask that if you find anything of import, you share it with me. We will accept any aid in our war against evil.",logDesc="Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire."} end
if not DB[1044] then DB[1044]={id=1044,zoneId=331,name="Answered Questions",level=30,minLevel=25,giver="Jonathan Carevin",giverType="NPC",giverId=661,ender="Thyn'tel Bladeweaver",enderType="NPC",enderId=8026,poiX=-10599,poiY=-1200,wowhead="https://www.wowhead.com/wotlk/quest=1044",image="assets/images/quests/placeholder.png",xpDiff=6,desc="We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions. Strange events are afoot in these times, $n, and the darkness knows no respite.$b$bI will keep you no longer. I suspect that there are others that should hear of what you have found in the mines of Duskwood.",logDesc="Return to Thyn'tel Bladeweaver in Darnassus.",choiceRewards={{id=5817,qty=1},{id=5818,qty=1}}} end
if not DB[1045] then DB[1045]={id=1045,zoneId=331,name="Raene's Cleansing",level=30,minLevel=18,giver="Krolg",giverType="NPC",giverId=3897,ender="Krolg",enderType="NPC",enderId=3897,rewardNextId=1046,poiX=1787,poiY=-1232,wowhead="https://www.wowhead.com/wotlk/quest=1045",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The night elves are as old as time, but their arrogance destroys their very world. And now it destroys our lives too. But that can no longer be controlled...$B$BI blame the elves for much, but we are still responsible for our actions. Even beyond the corruption, we are capable of great evil.$B$BRan Bloodtooth is one such evil. Power hungry, lusting... the corruption has only made him stronger. My hatred for the elves burns, but I do not wish ill upon their children, so we must police our own.",logDesc="Kill Ran Bloodtooth, 4 Bloodtooth Guards and collect Ran Bloodtooth's Skull. Return to Krolg near Lake Mystral should you succeed."} end
if not DB[1046] then DB[1046]={id=1046,zoneId=331,name="Raene's Cleansing",level=30,minLevel=18,giver="Krolg",giverType="NPC",giverId=3897,ender="Raene Wolfrunner",enderType="NPC",enderId=3691,poiX=1787,poiY=-1232,wowhead="https://www.wowhead.com/wotlk/quest=1046",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Return to your own tribe and let them know of your victory here.$B$BShow them your trophy, and bask in the glory...",logDesc="Bring Ran Bloodtooth's Skull to Raene Wolfrunner in Astranaar.",rewards={{id=1116,qty=1}},choiceRewards={{id=5815,qty=1},{id=17046,qty=1}}} end
if not DB[1047] then DB[1047]={id=1047,zoneId=1657,name="The New Frontier",level=55,minLevel=54,giver="Herald Moonstalker",giverType="NPC",giverId=10878,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,rewardNextId=6761,poiX=9660,poiY=2432,wowhead="https://www.wowhead.com/wotlk/quest=1047",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!",logDesc="Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor."} end
if not DB[1048] then DB[1048]={id=1048,zoneId=796,name="Into The Scarlet Monastery",level=42,minLevel=30,giver="Varimathras",giverType="NPC",giverId=2425,ender="Varimathras",enderType="NPC",enderId=2425,wowhead="https://www.wowhead.com/wotlk/quest=1048",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Whilst the Dark Lady tends to the pressing issue of the Lich King's advance to the north, I am seeing to it that matters closer to home are being taken care of accordingly.$b$bNo doubt, the human pests who call themselves the Scarlet Crusade are proving to be the sharpest thorn in our side domestically. Tirisfal Glades is literally crawling with the little red ants.$b$bTravel to the Monastery, $c, and lay waste to High Inquisitor Whitemane and her top lieutenants.",logDesc="Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.",choiceRewards={{id=6802,qty=1},{id=6803,qty=1},{id=10711,qty=1}}} end
if not DB[1049] then DB[1049]={id=1049,zoneId=796,name="Compendium of the Fallen",level=38,minLevel=28,giver="Sage Truthseeker",giverType="NPC",giverId=3978,ender="Sage Truthseeker",enderType="NPC",enderId=3978,poiX=-1176,poiY=158,wowhead="https://www.wowhead.com/wotlk/quest=1049",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?$b$bThe Forsaken whom we have allied with have a history wrought with deceit. Too hasty was our pact. Perhaps Cairne would have been wise to heed the warnings from Orgrimmar.$b$bDeep within the Scarlet Monastery lies the Compendium of the Fallen, guarded by crazed human zealots. Their method is forged from insanity but their research might prove useful.",logDesc="Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.",choiceRewards={{id=7747,qty=1},{id=17508,qty=1},{id=7749,qty=1}}} end
if not DB[1050] then DB[1050]={id=1050,zoneId=796,name="Mythology of the Titans",level=38,minLevel=28,giver="Librarian Mae Paledust",giverType="NPC",giverId=3979,ender="Librarian Mae Paledust",enderType="NPC",enderId=3979,poiX=-4635,poiY=-1306,wowhead="https://www.wowhead.com/wotlk/quest=1050",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea.$b$bBut perhaps, by studying the past, we can know what to expect and be better prepared for the unknown.$b$bBefore dire troubles fell upon Lordaeron, there was a bastion of knowledge tucked away in the Tirisfal Glades. It is rumored that a book called Mythology of the Titans was housed in the library of the old Monastery.$b$bBring it to me and perhaps together we can unlock the secrets of the past!",logDesc="Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.",rewards={{id=7746,qty=1}}} end
if not DB[1051] then DB[1051]={id=1051,zoneId=796,name="Vorrel's Revenge",level=33,minLevel=25,giver="Vorrel Sengutz",giverType="NPC",giverId=3981,ender="Monika Sengutz",enderType="NPC",enderId=3982,poiX=1786,poiY=1119,wowhead="https://www.wowhead.com/wotlk/quest=1051",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered.$b$bInterrogator Vishas did this to me! Tortured me for weeks! Took my wedding ring and gave it to his wife. The monster!$b$bRevenge... I want revenge!$b$bThe pompous fool bragged about his precious wife, Nancy, who lived along Lake Lordamere. Track the wench down, slay her and return my wedding ring to my wife, Monika in Tarren Mill.$b$bHeed my last wishes....",logDesc="Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.",rewards={{id=7751,qty=1}},choiceRewards={{id=7750,qty=1},{id=4643,qty=1}}} end
if not DB[1052] then DB[1052]={id=1052,zoneId=405,name="Down the Scarlet Path",level=40,minLevel=34,giver="Brother Anton",giverType="NPC",giverId=1182,ender="Raleigh the Devout",enderType="NPC",enderId=3980,poiX=215,poiY=1243,wowhead="https://www.wowhead.com/wotlk/quest=1052",image="assets/images/quests/placeholder.png",xpDiff=3,desc="We of the Scarlet Crusade lay claim to strongholds from Hearthglen to Tirisfal Glades. We are quite proud of our bastions of cleansing throughout Lordaeron.$b$bYou have proven yourself against the undead in Desolace. But the true threat of the plague lies in Lordaeron.$b$bTravel to the town of Southshore, in the Eastern Kingdoms. Seek out a crusader named Raleigh the Devout. Give him this letter of commendation bearing my seal and he will escort you to a place of honor in our Scarlet Monastery.",logDesc="Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore."} end
if not DB[1053] then DB[1053]={id=1053,zoneId=796,name="In the Name of the Light",level=40,minLevel=34,giver="Raleigh the Devout",giverType="NPC",giverId=3980,ender="Raleigh the Devout",enderType="NPC",enderId=3980,poiX=-845,poiY=-580,wowhead="https://www.wowhead.com/wotlk/quest=1053",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead.$b$bBut as I spent time at the Monastery in Tirisfal Glades I realized that their grasp on reality was slipping. They now think everyone is plagued who doesn't wear the tabard of the Crusade. Innocent men and women were tortured because they were supposedly plagued. $b$bThe Scarlet Crusade must be crushed in the name of the Light. You, $n, must destroy the deranged regime.",logDesc="Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.",choiceRewards={{id=6829,qty=1},{id=6830,qty=1},{id=6831,qty=1},{id=11262,qty=1}}} end
if not DB[1054] then DB[1054]={id=1054,zoneId=331,name="Culling the Threat",level=25,minLevel=18,giver="Raene Wolfrunner",giverType="NPC",giverId=3691,ender="Raene Wolfrunner",enderType="NPC",enderId=3691,poiX=2767,poiY=-412,wowhead="https://www.wowhead.com/wotlk/quest=1054",image="assets/images/quests/placeholder.png",xpDiff=5,money=1800,desc="Directly to the north of Astranaar are the Thistlefur furbolg. My scouts report that their numbers have grown greatly over the past few months. If they grow too great, they may find the courage to attack Astranaar directly.$B$BKill as many of their kind as you can, but bring me their chieftain's skull as proof that their efforts have been stifled... for now.$B$BI shall remain here in Astranaar and await word from you. Elune be with you.",logDesc="Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar.",rewards={{id=1970,qty=2}}} end
if not DB[1055] then DB[1055]={id=1055,zoneId=331,name="Raene's Cleansing",level=28,minLevel=18,ender="Shael'dryn",enderType="NPC",enderId=3916,rewardNextId=1029,wowhead="https://www.wowhead.com/wotlk/quest=1055",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The rod, now complete, lies in your hands. Shael'dryn will want to hear of your success.",logDesc="Return to Shael'dryn at the moonwell."} end
if not DB[1056] then DB[1056]={id=1056,zoneId=331,name="Journey to Stonetalon Peak",level=18,minLevel=18,giver="Faldreas Goeth'Shael",giverType="NPC",giverId=3996,ender="Keeper Albagorm",enderType="NPC",enderId=3994,poiX=2785,poiY=-362,wowhead="https://www.wowhead.com/wotlk/quest=1056",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The forest spirits tell me you are brave and willing to travel.$b$bTo the south, not far from Mystral Lake, there lies a tunnel named The Talondeep Path. Through this tunnel you will come to an area known as Windshear Crag in the Stonetalon Mountains. Once there, journey to the southwest past Cragpool Lake and then north, up the steep slope until you reach Stonetalon Peak.$b$bThere awaits Keeper Albagorm. Heed his bidding, $r.$b$bThe journey will be perilous.",logDesc="Travel to Keeper Albagorm on Stonetalon Peak."} end
if not DB[1057] then DB[1057]={id=1057,zoneId=406,name="Reclaiming the Charred Vale",level=27,minLevel=20,giver="Keeper Albagorm",giverType="NPC",giverId=3994,ender="Keeper Albagorm",enderType="NPC",enderId=3994,rewardNextId=1059,poiX=2653,poiY=1434,wowhead="https://www.wowhead.com/wotlk/quest=1057",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As a protector of the forest spirits you can undoubtedly guess why I am alarmed.$b$bYou have traveled through these mountains to reach this peak. Surely you have seen the travesty which has befallen the land. Greed has led to the destruction of these sacred hills.$b$bThe Charred Vale to the south was set afire by the greedy mechanized army of industrialists. Worse yet, the Bloodfuries that have encroached on the land refuse us passage in to begin regrowth.$b$bDrive the wretched harpies out, $n!",logDesc="Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers."} end
if not DB[1058] then DB[1058]={id=1058,zoneId=406,name="Jin'Zil's Forest Magic",level=26,minLevel=20,giver="Witch Doctor Jin'Zil",giverType="NPC",giverId=3995,ender="Witch Doctor Jin'Zil",enderType="NPC",enderId=3995,poiX=-272,poiY=-394,wowhead="https://www.wowhead.com/wotlk/quest=1058",image="assets/images/quests/placeholder.png",xpDiff=5,desc="So excited I am!$b$bThree little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of... what do they call it... forest magic!$b$bI'll need a good mess of Stonetalon sap. From those horrid felines, bring me some twilight whiskers. This calls for plenty of courser eyes, of course -- can never have enough eyes. Oh, and lest we forget, a precious scale from a fey dragon.$b$bHurry to Stonetalon Peak, $n, so I can brew some forest magic!",logDesc="Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.",choiceRewards={{id=6664,qty=1},{id=6665,qty=1}}} end
if not DB[1059] then DB[1059]={id=1059,zoneId=406,name="Reclaiming the Charred Vale",level=27,minLevel=20,giver="Keeper Albagorm",giverType="NPC",giverId=3994,ender="Falfindel Waywarder",enderType="NPC",enderId=4048,poiX=2653,poiY=1434,wowhead="https://www.wowhead.com/wotlk/quest=1059",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken.$b$bFar south of the Barrens lies a land known as Thousand Needles. If you travel west in Thousand Needles until you reach the lush forest's edge of Feralas, you will find a druid named Falfindel Waywarder.$b$bThis great and wise druid is capable of calling forth great forest spirits which can aid in the reclamation of the Charred Vale.$b$bSend word of our need! Seek him out at once!",logDesc="Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.",choiceRewards={{id=6675,qty=1},{id=6676,qty=1}}} end
if not DB[1060] then DB[1060]={id=1060,zoneId=17,name="Letter to Jin'Zil",level=20,minLevel=15,giver="Darsok Swiftdagger",giverType="NPC",giverId=3449,ender="Witch Doctor Jin'Zil",enderType="NPC",enderId=3995,poiX=-475,poiY=-2608,wowhead="https://www.wowhead.com/wotlk/quest=1060",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You've done so well for me, $n. You're a regular lucky rabbit's foot and there's something I want you to see.$B$BThe harpies are not from around the Barrens. They come from a place called Stonetalon, far to the northwest of here. Though it is probably a dangerous place for you, I need this letter delivered to an old friend of mine who lives there, a witch doctor by the name of Jin'Zil.$B$BHe'll be happy to know that Serena Bloodfeather is dead, and I think you'll find Stonetalon an interesting place.",logDesc="Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon."} end
if not DB[1061] then DB[1061]={id=1061,zoneId=406,name="The Spirits of Stonetalon",level=17,minLevel=13,giver="Zor Lonetree",giverType="NPC",giverId=4047,ender="Seereth Stonebreak",enderType="NPC",enderId=4049,rewardNextId=1062,poiX=1915,poiY=-4227,wowhead="https://www.wowhead.com/wotlk/quest=1061",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The spirits of the Stonetalon Mountains are angered, for goblins and their servants are plundering and burning the land.  So the land has cried out, and those who listen for such things... have heard.$B$BSeereth Stonebreak, a promising shaman of the Horde, was sent to Stonetalon.  She reports massive deforestation at the hands of the goblins, and requests aid.$B$BMeet Seereth in Stonetalon.  To reach her, follow the road west of the Barrens' Crossroads.  She is camped near the Greatwood Vale.",logDesc="Speak with Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens."} end
if not DB[1062] then DB[1062]={id=1062,zoneId=406,name="Goblin Invaders",level=19,minLevel=13,giver="Seereth Stonebreak",giverType="NPC",giverId=4049,ender="Seereth Stonebreak",enderType="NPC",enderId=4049,poiX=-270,poiY=-951,wowhead="https://www.wowhead.com/wotlk/quest=1062",image="assets/images/quests/placeholder.png",xpDiff=5,money=1100,desc="The goblin-run Venture Company moved into the Stonetalon Mountains, chopping down trees and burning huge stretches of forest.  The spirits of this place are nearly blind with pain and rage.  We must stop the Venture Company!$B$BHead northwest, beyond the Greatwood Vale and into the Windshear Crag.  You will find the goblins and their servants at work--show them the Horde will not allow the exploitation of Stonetalon.  Show them in the language they best understand...$B$BViolence.",logDesc="Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens."} end
if not DB[1063] then DB[1063]={id=1063,zoneId=406,name="The Elder Crone",level=18,minLevel=13,giver="Seereth Stonebreak",giverType="NPC",giverId=4049,ender="Magatha Grimtotem",enderType="NPC",enderId=4046,poiX=-270,poiY=-951,wowhead="https://www.wowhead.com/wotlk/quest=1063",image="assets/images/quests/placeholder.png",xpDiff=3,desc="To truly tend the spirits of Stonetalon we must consult the tauren elders.$B$BI do not know many of their leaders' names, but I do know of one: Magatha.  I have heard that she is very old, and she knows much.  If anyone can marshal spiritual aid from the tauren, it is she.$B$BMagatha resides in the tauren capital of Thunder Bluff, on Elder Rise -- the city's northeastern bluff.  Speak with Magatha, and tell her of the peril of Stonetalon Mountains.",logDesc="Speak with Magatha in Thunder Bluff."} end
if not DB[1064] then DB[1064]={id=1064,zoneId=1638,name="Forsaken Aid",level=18,minLevel=13,giver="Magatha Grimtotem",giverType="NPC",giverId=4046,ender="Apothecary Zamah",enderType="NPC",enderId=3419,rewardNextId=1065,poiX=-1065,poiY=-212,wowhead="https://www.wowhead.com/wotlk/quest=1064",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The tauren have a bond with the land, and it pains me to hear of Stonetalon's plight.  But I fear that to heal the land, we must first remove the disease upon it.$B$BIs it not fortunate, then, that the Forsaken are allied with us?  They know much of disease.  I believe they can aid us, and by doing so they will strengthen the trust between our people.$B$BSpeak with Apothecary Zamah.  She is a scholar and an emissary of the Forsaken.  You will find her in the Pools of Vision below the Spirit Rise.",logDesc="Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff."} end
if not DB[1065] then DB[1065]={id=1065,zoneId=1638,name="Journey to Tarren Mill",level=18,minLevel=13,giver="Apothecary Zamah",giverType="NPC",giverId=3419,ender="Apothecary Lydon",enderType="NPC",enderId=2216,rewardNextId=1066,poiX=-995,poiY=279,wowhead="https://www.wowhead.com/wotlk/quest=1065",image="assets/images/quests/placeholder.png",xpDiff=5,desc="To rid Stonetalon of the Venture Company, we must take extreme measures.  Extreme, but without bloodshed.$B$BA colleague of mine may have just the tool we need.  His name is Lydon; he dwells in the town of Tarren Mill in the Hillsbrad Foothills, in the distant land of Lordaeron.$B$BTo reach Hillsbrad, travel by zeppelin to our capital, the Undercity.  Then go north to Tirisfal Glades, southwest to Silverpine, and south to Hillsbrad.$B$BSeek Lydon and bring him this note.  It details our needs to him.",logDesc="Bring Zamah's Note to Apothecary Lydon in Tarren Mill."} end
if not DB[1066] then DB[1066]={id=1066,zoneId=1638,name="Blood of Innocents",level=23,minLevel=13,giver="Apothecary Lydon",giverType="NPC",giverId=2216,ender="Apothecary Lydon",enderType="NPC",enderId=2216,poiX=-7,poiY=-899,wowhead="https://www.wowhead.com/wotlk/quest=1066",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I will create a toxin to bleed the violence from the Venture Company, rendering them weak and docile.  That should fix the Horde's problem in Stonetalon, yes?$B$BBut to create the toxin, I will need the blood of innocents, a difficult ingredient to obtain.$B$BFortunately the Syndicate, a group of human brigands in this area, employ shadow mages... and those mages collect innocent blood for their own, unsavory purposes.$B$BYou can find the Syndicate shadow mages in Durnholde Keep to the southeast.",logDesc="Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill."} end
if not DB[1067] then DB[1067]={id=1067,zoneId=1638,name="Return to Thunder Bluff",level=23,minLevel=13,giver="Apothecary Lydon",giverType="NPC",giverId=2216,ender="Apothecary Zamah",enderType="NPC",enderId=3419,poiX=-7,poiY=-899,wowhead="https://www.wowhead.com/wotlk/quest=1067",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Here is the toxin.  If you use it against the Venture Company it should produce favorable, perhaps even contagious, results.  I must say, it is quite exciting to see my work applied in the field!$B$BBut before using it, take it to Apothecary Zamah.  She must create a delivery method for the toxin to maximize its effect.",logDesc="Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff."} end
if not DB[1068] then DB[1068]={id=1068,zoneId=406,name="Shredding Machines",level=23,minLevel=13,giver="Seereth Stonebreak",giverType="NPC",giverId=4049,ender="Seereth Stonebreak",enderType="NPC",enderId=4049,poiX=-270,poiY=-951,wowhead="https://www.wowhead.com/wotlk/quest=1068",image="assets/images/quests/placeholder.png",xpDiff=5,money=1500,desc="There is a relation to the spiritual magic of shaman and the natural magic of druids.  This is why we shaman can hear the plea of the spirits of Stonetalon.  Many of their whisperings are lost to me, but one message, one vision, is clear...$B$BI saw a vision of two man-shaped machines in Windshear Crag, northwest of Greatwood Vale, felling trees with impossible speed.  These metal beasts must be stopped!$B$BIn my vision, the machines were marked with strange symbols:$B$BXT:4 and XT:9.",logDesc="Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens."} end
if not DB[1069] then DB[1069]={id=1069,zoneId=17,name="Deepmoss Spider Eggs",level=20,minLevel=15,giver="Mebok Mizzyrix",giverType="NPC",giverId=3446,ender="Mebok Mizzyrix",enderType="NPC",enderId=3446,poiX=-929,poiY=-3697,wowhead="https://www.wowhead.com/wotlk/quest=1069",image="assets/images/quests/placeholder.png",xpDiff=6,money=2500,desc="Spider egg omelettes are a new fad in Booty Bay!  The problem is... Booty Bay's got no eggs.$B$BI smell an opportunity!$B$BIn Windshear Crag and Sishir Canyon, in the Stonetalon Mountains to the northwest, lives the deepmoss spider.  Bring me its eggs and I'll pay a bundle!$B$BIn Windshear Crag, the eggs will be clustered under what trees remain.$B$BIn Sishir Canyon... well, if you have a weak stomach then maybe you should just collect the eggs at Windshear Crag...",logDesc="Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet."} end
if not DB[1070] then DB[1070]={id=1070,zoneId=331,name="On Guard in Stonetalon",level=21,minLevel=17,giver="Sentinel Thenysil",giverType="NPC",giverId=4079,ender="Kaela Shadowspear",enderType="NPC",enderId=4080,rewardNextId=1085,poiX=2759,poiY=-312,wowhead="https://www.wowhead.com/wotlk/quest=1070",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Hello, $N.$B$BYou seem to be full of wanderlust by the looks of you. Have you been to the Stonetalon Mountains? It is a land plagued by the Venture Co. and other enemies of the night elves.$B$BRecently, Sentinel Wolfrunner sent my friend Kaela Shadowspear there to investigate what's happening to the land, but I have yet to hear word back from her. I'm even more concerned because the Alliance sent a gnome mage along with her... a sign of trouble for sure.$B$BWould you find her and report back to me?",logDesc="Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains."} end
if not DB[1071] then DB[1071]={id=1071,zoneId=406,name="A Gnome's Respite",level=21,minLevel=17,giver="Gaxim Rustfizzle",giverType="NPC",giverId=4077,ender="Gaxim Rustfizzle",enderType="NPC",enderId=4077,poiX=730,poiY=340,wowhead="https://www.wowhead.com/wotlk/quest=1071",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You see, $N, I'm a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and it's my goal... nay, my DUTY! to show the night elves that a blend of magic, mixtures, and mechanisms can help save their forests.$B$BBut it's a hard fought war, and the goblins reproduce like rabbits it seems. I haven't even had time to build my newest inventions!$B$BI need some time to plan and organize. But to do that, I need your help keeping the goblins at bay in Windshear Crag to the east...",logDesc="Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon."} end
if not DB[1072] then DB[1072]={id=1072,zoneId=406,name="An Old Colleague",level=21,minLevel=17,giver="Gaxim Rustfizzle",giverType="NPC",giverId=4077,ender="Lomac Gearstrip",enderType="NPC",enderId=4081,rewardNextId=1073,poiX=730,poiY=340,wowhead="https://www.wowhead.com/wotlk/quest=1072",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The device I'm thinking about is my most advanced version to date. But we'll need a special potion if it's to work. I'm thinking we might as well get the good stuff since this mission could be your last.$B$BAnd for that, we're going to need some potent explosives: Nitromirglyceronium.$B$BThe only person who can make NG-5 is an old friend of mine: Lomac Gearstrip. Look for him in Tinker Town.$B$BYou talk him into making us some NG-5, I'll get to work on placement for my devices.",logDesc="Speak to Lomac Gearstrip in Ironforge."} end
if not DB[1073] then DB[1073]={id=1073,zoneId=406,name="Ineptitude + Chemicals = Fun",level=21,minLevel=17,giver="Lomac Gearstrip",giverType="NPC",giverId=4081,ender="Lomac Gearstrip",enderType="NPC",enderId=4081,rewardNextId=1074,poiX=-4843,poiY=-1284,wowhead="https://www.wowhead.com/wotlk/quest=1073",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hahaha... you need Nitromirglyceronium to stop goblins from destroying a forest?!$B$BI don't care if you know Gaxim or not... I'll give you the stuff just to see you or them explode into itty bitty pieces.$B$BThere's a problem though: I'm all out.$B$BBut I'll tell you what, you bring me the correct potions, and I'll make some up for you right away.$B$BThe least you can do is prove you've got some skill as an alchemist before I just give you a sample of my greatest creation.",logDesc="Bring 4 Minor Mana Potions and 2 Elixirs of Minor Fortitude to Lomac Gearstrip in Ironforge."} end
if not DB[1074] then DB[1074]={id=1074,zoneId=406,name="Ineptitude + Chemicals = Fun",level=21,minLevel=17,giver="Lomac Gearstrip",giverType="NPC",giverId=4081,ender="Gaxim Rustfizzle",enderType="NPC",enderId=4077,poiX=-4843,poiY=-1284,wowhead="https://www.wowhead.com/wotlk/quest=1074",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Here you go, stranger. Take heed with it though... it's volatile stuff.$B$BIf you're really a friend of Gaxim's, then tell him I say hello. If you're not, then have fun blowin' yerself up.",logDesc="Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon."} end
if not DB[1075] then DB[1075]={id=1075,zoneId=406,name="A Scroll from Mauren",level=21,minLevel=17,giver="Gaxim Rustfizzle",giverType="NPC",giverId=4077,ender="Collin Mauren",enderType="NPC",enderId=4078,rewardNextId=1076,poiX=730,poiY=340,wowhead="https://www.wowhead.com/wotlk/quest=1075",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Okay, now for the remote detonation part of my plan... oh, I haven't explained that yet, have I?$B$BOkay, so the short of it is this: with a little magic, I can make it so the explosives go off while you're not around. I'm putting together a device that'll allow you to push just one button and have the NG-5 explode when you're ready.$B$BBut I need a spell from a friend in Stormwind--Collin Mauren is his name. You can find him in the mage quarter there. He's human, so he shouldn't be hard to miss.",logDesc="Find Collin Mauren in Stormwind."} end
if not DB[1076] then DB[1076]={id=1076,zoneId=406,name="Devils in Westfall",level=21,minLevel=17,giver="Collin Mauren",giverType="NPC",giverId=4078,ender="Collin Mauren",enderType="NPC",enderId=4078,poiX=-8999,poiY=802,wowhead="https://www.wowhead.com/wotlk/quest=1076",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Ah, I think I have it. A messaging spell... I believe that's the effect he's looking for.$B$BI'll have to create a scroll with the spell impressed upon it. To do that I'll need debris from a dust devil.$B$BWhile I gather the rest of the components, why don't you head to Westfall and find one of the foul creatures? They are dangerous, but I'm sure it's nothing you can't handle if you're willing to subject yourself to one of Gaxim's experiments.$B$BI'll be here when you return.",logDesc="Bring Dust Devil Debris to Collin Mauren in Stormwind."} end
if not DB[1077] then DB[1077]={id=1077,zoneId=406,name="Special Delivery for Gaxim",level=21,minLevel=17,giver="Collin Mauren",giverType="NPC",giverId=4078,ender="Gaxim Rustfizzle",enderType="NPC",enderId=4077,poiX=-8999,poiY=802,wowhead="https://www.wowhead.com/wotlk/quest=1077",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Here you are, $N. This should do nicely.$B$BPlease give my regards to Gaxim when next you see him. I look forward to hearing about this adventure when it sees its completion.$B$BFare well.",logDesc="Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon."} end
if not DB[1078] then DB[1078]={id=1078,zoneId=406,name="Retrieval for Mauren",level=26,minLevel=17,giver="Collin Mauren",giverType="NPC",giverId=4078,ender="Collin Mauren",enderType="NPC",enderId=4078,poiX=-8999,poiY=802,wowhead="https://www.wowhead.com/wotlk/quest=1078",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co.$B$BWithin the Charred Vale, deep in Stonetalon, there used to be a species of basilisks whose scales, when ground to dust, made a wonderful reagent for some spells I've created.$B$BIf those basilisks still live, I would love to have a few of their scales.$B$BTake your time, it is no rush, but I can pay well.",logDesc="Bring 8 Crystalized Scales to Collin Mauren in Stormwind.",rewards={{id=6677,qty=1}}} end
if not DB[1079] then DB[1079]={id=1079,zoneId=406,name="Covert Ops - Alpha",level=22,minLevel=17,giver="Gaxim Rustfizzle",giverType="NPC",giverId=4077,ender="Gaxim Rustfizzle",enderType="NPC",enderId=4077,poiX=730,poiY=340,wowhead="https://www.wowhead.com/wotlk/quest=1079",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This is it, $N. Pay close attention. The devices are done, and ready to be used.$B$BTake these pages--they'll explain more about the detonators and explosives, and where you should place them.$B$BRemember, the success of your mission doesn't depend on how much destruction you cause. Plan Alpha's success depends on you bringing back the Venture Co.'s engineering plans from inside the lumber mill south of Cragpool Lake.",logDesc="Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag."} end
if not DB[1080] then DB[1080]={id=1080,zoneId=406,name="Covert Ops - Beta",level=22,minLevel=17,giver="Gaxim Rustfizzle",giverType="NPC",giverId=4077,ender="Gaxim Rustfizzle",enderType="NPC",enderId=4077,poiX=730,poiY=340,wowhead="https://www.wowhead.com/wotlk/quest=1080",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Plan Beta's just like Plan Alpha, $N.$B$BWe cause a distraction and then steal their precious letters.$B$BThe key is to get their letters... remember that.$B$BThe pages I gave you already will tell you where to plant the explosives. Just get back here alive and with those letters....",logDesc="Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag."} end
if not DB[1081] then DB[1081]={id=1081,zoneId=406,name="Reception from Tyrande",level=28,minLevel=17,giver="Sentinel Thenysil",giverType="NPC",giverId=4079,ender="3",enderType="NPC",enderId=7999,poiX=2759,poiY=-312,wowhead="https://www.wowhead.com/wotlk/quest=1081",image="assets/images/quests/placeholder.png",xpDiff=7,desc="$N, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission.$B$BIt may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains.$B$BIf you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus.",logDesc="Find Tyrande Whisperwind in Darnassus.",rewards={{id=6678,qty=1}},choiceRewards={{id=7334,qty=1},{id=7335,qty=1},{id=7336,qty=1}}} end
if not DB[1082] then DB[1082]={id=1082,zoneId=406,name="Update for Sentinel Thenysil",level=22,minLevel=17,giver="Kaela Shadowspear",giverType="NPC",giverId=4080,ender="Sentinel Thenysil",enderType="NPC",enderId=4079,rewardNextId=1081,poiX=740,poiY=321,wowhead="https://www.wowhead.com/wotlk/quest=1082",image="assets/images/quests/placeholder.png",xpDiff=3,desc="$N, you have done a great deed by lending a hand here.$B$BThe Sentinels of Ashenvale will reward you well if you informed them that Gaxim and I are alive. Tell them we are well on our way to stopping the Venture Co. and healing the lands.$B$BFind Tara Thenysil in Astranaar; she will be pleased to see you've returned with good news.",logDesc="Return to Sentinel Thenysil in Ashenvale."} end
if not DB[1083] then DB[1083]={id=1083,zoneId=406,name="Enraged Spirits",level=26,minLevel=20,giver="Kaela Shadowspear",giverType="NPC",giverId=4080,ender="Kaela Shadowspear",enderType="NPC",enderId=4080,poiX=740,poiY=321,wowhead="https://www.wowhead.com/wotlk/quest=1083",image="assets/images/quests/placeholder.png",xpDiff=5,money=2000,desc="I'm unsure what the Venture Co. did to the Vale, but it's obvious they were overpowered by the creatures there.$B$BThey set the forest aflame, and used their inventions of destruction to decimate as much of the Vale as possible.$B$BBut in their ignorance they also released something else: burning spirits, elementals of flame, stone and rage.$B$BThe land has no chance to see Elune's smile while these creatures roam free.$B$BBring me their smoldering embers to show you've reduced their numbers.",logDesc="Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon."} end
if not DB[1084] then DB[1084]={id=1084,zoneId=406,name="Wounded Ancients",level=28,minLevel=22,giver="Kaela Shadowspear",giverType="NPC",giverId=4080,ender="Kaela Shadowspear",enderType="NPC",enderId=4080,poiX=740,poiY=321,wowhead="https://www.wowhead.com/wotlk/quest=1084",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="It seems obvious to me that the protectors of the Vale--the treants--had something to do with the Venture Co. being driven back. Unfortunately, even those once great guardians have now become corrupt.$B$BGaxim thinks their corruption is somehow linked to the weapons the goblins used during their retreat.$B$BI told him I'd collect a sample from a wounded treant and allow him to study it in order to figure out if that's true.$B$BBring me some of the shrapnel so the gnome can tell me more...",logDesc="Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon."} end
if not DB[1085] then DB[1085]={id=1085,zoneId=331,name="On Guard in Stonetalon",level=21,minLevel=17,giver="Kaela Shadowspear",giverType="NPC",giverId=4080,ender="Gaxim Rustfizzle",enderType="NPC",enderId=4077,rewardNextId=1071,poiX=740,poiY=321,wowhead="https://www.wowhead.com/wotlk/quest=1085",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The situation here in Stonetalon is obviously grave for a night elf and gnome to be working together.$B$BThe Venture Co. has devastated these lands and I've spent most of my time putting an end to the destruction.$B$BDo not judge Gaxim prematurely; he understands the need for us to work together.$B$BIf you wish to aid us, then start by speaking to Gaxim.$B$BI'm sorry I cannot send you back to Tara with good news yet. Perhaps soon.",logDesc="Speak to Gaxim in Stonetalon Mountains."} end
if not DB[1086] then DB[1086]={id=1086,zoneId=1638,name="The Flying Machine Airport",level=23,minLevel=13,giver="Apothecary Zamah",giverType="NPC",giverId=3419,ender="Apothecary Zamah",enderType="NPC",enderId=3419,poiX=-995,poiY=279,wowhead="https://www.wowhead.com/wotlk/quest=1086",image="assets/images/quests/placeholder.png",xpDiff=6,money=3000,desc="The toxin is ready.  All that remains is its delivery.  You, $N, must make that delivery.$B$BThe Venture Company must have a means of sending messages and light cargo between its headquarters and its operations in Stonetalon.  It is likely a small sky port -- not big enough for a zeppelin, but perhaps for a flying machine.  You must search the areas in Stonetalon under control of the Venture Company and find this sky port, if it exists.  If you find it, then place the toxin there.$B$BPlace it, and run.",logDesc="Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah."} end
if not DB[1087] then DB[1087]={id=1087,zoneId=406,name="Cenarius' Legacy",level=25,minLevel=20,giver="Braelyn Firehand",giverType="NPC",giverId=4198,ender="Braelyn Firehand",enderType="NPC",enderId=4198,rewardNextId=1088,poiX=949,poiY=1002,wowhead="https://www.wowhead.com/wotlk/quest=1087",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You cannot imagine the hatred I possess for this wretched land. The ilk of Cenarius and the kaldorei druids at the peak employ their pathetic powers to stifle the flow of magic, even so far south of their pathetic holdings... their beloved forests.$b$bWould that I could return to Jaedenar and exult in the flow of magic, but my master will not allow me to return until my work is done.$b$bI have no doubt you love the night elves and their allies as little as I. Aid me, and both our ends might be satisfied.",logDesc="Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat."} end
if not DB[1088] then DB[1088]={id=1088,zoneId=406,name="Ordanus",level=29,minLevel=20,giver="Braelyn Firehand",giverType="NPC",giverId=4198,ender="Braelyn Firehand",enderType="NPC",enderId=4198,rewardNextId=1089,poiX=949,poiY=1002,wowhead="https://www.wowhead.com/wotlk/quest=1088",image="assets/images/quests/placeholder.png",xpDiff=5,desc="They thought that they could halt the flow of magic. They were mistaken. They thought that they could hide Ordanus, but I will have his head!$b$bMagic grants me true sight. Yes... there he is. A crossroads... At the top of a great tree in Ashenvale Forest. A name... Raynewood. One of the eldest sons of the forest god. They spirited him away from the peak before I could find him, but his time runs short.$b$bBring it to me and I will share with you a mighty gift.",logDesc="Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat."} end
if not DB[1089] then DB[1089]={id=1089,zoneId=406,name="The Den",level=29,minLevel=20,giver="Braelyn Firehand",giverType="NPC",giverId=4198,poiX=949,poiY=1002,wowhead="https://www.wowhead.com/wotlk/quest=1089",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items.$b$bThey devised a complex scheme to keep them from falling into the wrong hands.$b$bLuckily, I managed to... extract some details from one of them.$b$bHidden in a small lantern at the entrance of the Den, you will find the Gatekeeper's Key--with it you will be able to open caches around the Den. The items from these caches will allow you to open their hoard, located in one of the central areas.",logDesc="Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard. ",rewards={{id=6669,qty=1},{id=6670,qty=1},{id=6671,qty=1}}} end
if not DB[1090] then DB[1090]={id=1090,zoneId=406,name="Gerenzo's Orders",level=22,minLevel=17,giver="Piznik",giverType="NPC",giverId=4276,ender="Piznik",enderType="NPC",enderId=4276,rewardNextId=1092,poiX=963,poiY=-264,wowhead="https://www.wowhead.com/wotlk/quest=1090",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You know, I was once the second most important person here at this site. That all changed when Gerenzo took over. Fired my boss, Ziz Fizziks, and sent me down to work in the mines. Ziz told me to stay here and gather information, though. His new boss will pay us well if we can find out what Gerenzo's plans are.$b$bAnyways, what I do know is that Gerenzo has ordered large amounts of this gold-green ore to be mined. I can get you a sample to bring to Ziz, but you'll have to watch for patrols while I get it.",logDesc="Get the mysterious ore from Piznik after he finishes mining it."} end
if not DB[1091] then DB[1091]={id=1091,zoneId=406,name="Kaela's Update",level=22,minLevel=17,giver="Gaxim Rustfizzle",giverType="NPC",giverId=4077,ender="Kaela Shadowspear",enderType="NPC",enderId=4080,poiX=730,poiY=340,wowhead="https://www.wowhead.com/wotlk/quest=1091",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N, take these letters to Kaela. I'm sure she'll want to know about this. Or at least the Sentinels will.$B$BMake sure you tell her how successful we were and how we couldn't have done it without a little bit of magic.",logDesc="Bring the Venture Co. Letters to Kaela Shadowspear in Stonetalon Mountains."} end
if not DB[1092] then DB[1092]={id=1092,zoneId=406,name="Gerenzo's Orders",level=22,minLevel=17,giver="Piznik",giverType="NPC",giverId=4276,ender="Ziz Fizziks",enderType="NPC",enderId=4201,poiX=963,poiY=-264,wowhead="https://www.wowhead.com/wotlk/quest=1092",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again.$b$bI'll sneak out and meet with Ziz. Hopefully, he'll be able to find me a new job!$b$bI'll try and clean up this mess a little, but you should take the ore sample to Ziz right away. He told me that he'd set up camp somewhere on the western side of Windshear Crag. Good luck.",logDesc="Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains.",rewards={{id=6666,qty=1}}} end
if not DB[1093] then DB[1093]={id=1093,zoneId=406,name="Super Reaper 6000",level=21,minLevel=16,giver="Ziz Fizziks",giverType="NPC",giverId=4201,ender="Ziz Fizziks",enderType="NPC",enderId=4201,rewardNextId=1094,poiX=878,poiY=365,wowhead="https://www.wowhead.com/wotlk/quest=1093",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Terrible what the Venture Company has done here, eh? What were they thinking? Goblin company hiring a gnome!$b$bLucky for me, Sputtervalve knows a genius when he sees one. Hired me just after I'd been kicked out!$b$bTells me they built some enormous woodcutting machine, and Sput' wants me to steal the plans for him. Unfortunately, Gerenzo--bloody gnome--wants me dead on sight... maybe you could steal the plans for me? You should be able to find them on one of their operators.",logDesc="Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains."} end
if not DB[1094] then DB[1094]={id=1094,zoneId=406,name="Further Instructions",level=21,minLevel=16,giver="Ziz Fizziks",giverType="NPC",giverId=4201,ender="Sputtervalve",enderType="NPC",enderId=3442,rewardNextId=1095,poiX=878,poiY=365,wowhead="https://www.wowhead.com/wotlk/quest=1094",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.$b$bSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow.",logDesc="Deliver the Sealed Envelope to Sputtervalve at Ratchet in the Barrens."} end
if not DB[1095] then DB[1095]={id=1095,zoneId=406,name="Further Instructions",level=27,minLevel=16,giver="Sputtervalve",giverType="NPC",giverId=3442,ender="Ziz Fizziks",enderType="NPC",enderId=4201,rewardNextId=1096,poiX=-902,poiY=-3759,wowhead="https://www.wowhead.com/wotlk/quest=1095",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.$b$bRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.$b$bWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him.",logDesc="Bring the new orders to Ziz Fizziks in the Stonetalon Mountains."} end
if not DB[1096] then DB[1096]={id=1096,zoneId=406,name="Gerenzo Wrenchwhistle",level=27,minLevel=16,giver="Ziz Fizziks",giverType="NPC",giverId=4201,ender="Ziz Fizziks",enderType="NPC",enderId=4201,poiX=878,poiY=365,wowhead="https://www.wowhead.com/wotlk/quest=1096",image="assets/images/quests/placeholder.png",xpDiff=5,money=2200,desc="I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones.$b$bNortheast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it.$b$bIf you kill him for me, I'll make it worth your while!",logDesc="Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.",choiceRewards={{id=6667,qty=1},{id=6668,qty=1}}} end
if not DB[1097] then DB[1097]={id=1097,zoneId=1519,name="Elmore's Task",level=15,minLevel=9,giver="Verner Osgood",giverType="NPC",giverId=415,ender="Grimand Elmore",enderType="NPC",enderId=1416,rewardNextId=353,poiX=-9259,poiY=-2243,wowhead="https://www.wowhead.com/wotlk/quest=1097",image="assets/images/quests/placeholder.png",xpDiff=1,desc="There's a dwarven weaponsmith in Stormwind, Grimand Elmore, who sent word that he needs help with a delivery.  I believe he wants a package sent to his homeland in the north.$B$BYou have a sturdy pair on you!  So if you're interested in some legwork then speak with Grimand.  We could use you down here, but we must also keep our ties strong with the dwarves.$B$BYou can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.",logDesc="Speak with Grimand Elmore in Stormwind."} end
if not DB[1098] then DB[1098]={id=1098,zoneId=209,name="Deathstalkers in Shadowfang",level=25,minLevel=18,giver="High Executor Hadrec",giverType="NPC",giverId=1952,ender="Deathstalker Vincent",enderType="NPC",enderId=4444,poiX=522,poiY=1626,wowhead="https://www.wowhead.com/wotlk/quest=1098",image="assets/images/quests/placeholder.png",xpDiff=7,money=1800,desc="In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence.  It has been many days and they have not returned, but we must receive their report if we're to have any hope of a successful attack!$B$BSo here is your task, $N.  Go to Shadowfang Keep to the south and find the Deathstalkers Adamant and Vincent.  Find them, and if they require aid then give it.$B$BThis mission is as dangerous as is it critical, $N.  Do not fail.",logDesc="Find the Deathstalker Adamant and Deathstalker Vincent.",rewards={{id=3324,qty=1}}} end
if not DB[1099] then DB[1099]={id=1099,zoneId=400,name="Goblins Win!",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=1099",image="assets/images/quests/placeholder.png",rewards={{id=5858,qty=1}}} end
if not DB[1100] then DB[1100]={id=1100,zoneId=400,name="Lonebrow's Journal",level=27,minLevel=23,ender="Falfindel Waywarder",enderType="NPC",enderId=4048,rewardNextId=1101,wowhead="https://www.wowhead.com/wotlk/quest=1100",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You slowly open the weathered journal of Henrig Lonebrow....",logDesc="Read Henrig Lonebrow's Journal."} end
if not DB[1101] then DB[1101]={id=1101,zoneId=1717,name="The Crone of the Kraul",level=27,minLevel=23,giver="Falfindel Waywarder",giverType="NPC",giverId=4048,ender="Falfindel Waywarder",enderType="NPC",enderId=4048,poiX=-4524,poiY=-788,wowhead="https://www.wowhead.com/wotlk/quest=1101",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was.$b$bWe must not let their valiance go for naught. This crone... Charlga Razorflank ... must be stopped.$b$bSurely, infiltrating the Kraul will be perilous. There isn't time to send word to Darnassus. $n, assemble a party to slay the crone.$b$bBring me Razorflank's Medallion as proof of demise.",logDesc="Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.",rewards={{id=29200,qty=1}},choiceRewards={{id=4197,qty=1},{id=6742,qty=1},{id=6725,qty=1}}} end
if not DB[1102] then DB[1102]={id=1102,zoneId=1717,name="A Vengeful Fate",level=27,minLevel=23,giver="Auld Stonespire",giverType="NPC",giverId=4451,ender="Auld Stonespire",enderType="NPC",enderId=4451,poiX=-1267,poiY=141,wowhead="https://www.wowhead.com/wotlk/quest=1102",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Cairne is a noble leader for uniting our people here on Thunder Bluff.$b$bBut I cannot forgive those who drove us from our ancestral lands as easily as some. My people inhabited the southern Barrens for decades. The land was holy to us. But we were driven off by numerous foes.$b$bA vengeful fate awaits the crone, Charlga Razorflank, who musters a foul army from within Razorfen Kraul.$b$bBring me Razorflank's heart and I can die in peace, $n.",logDesc="Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.",choiceRewards={{id=4197,qty=1},{id=6742,qty=1},{id=6725,qty=1}}} end
if not DB[1103] then DB[1103]={id=1103,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Tiev Mordune",giverType="NPC",giverId=7007,ender="Tiev Mordune",enderType="NPC",enderId=7007,poiX=430,poiY=1882,wowhead="https://www.wowhead.com/wotlk/quest=1103",image="assets/images/quests/placeholder.png",desc="Greetin's, $g brotha:sista;! Have you too come to purify the waters here and prove your understandin' to Islen?$B$BI've just defeated the corrupt water spirit meself, and I'm just 'bout to put da bracers and remaining drops o' water on the brazier.$B$BWhat's dat? Ahhh. Tiev understan' all too well when somethin' goes wrong. Well, Tiev can help you plenty if you be needin' to see the pure water spirit again.$B$BBring me a water sapta from Islen as proof that you be ready, an' I'll wait to turn in me parts.",logDesc="Bring a Water Sapta to Tiev Mordune in Silverpine Forest if you failed to speak to the Minor Manifestation of Water."} end
if not DB[1104] then DB[1104]={id=1104,zoneId=400,name="Salt Flat Venom",level=30,minLevel=28,giver="Fizzle Brassbolts",giverType="NPC",giverId=4454,ender="Fizzle Brassbolts",enderType="NPC",enderId=4454,poiX=-6229,poiY=-3868,wowhead="https://www.wowhead.com/wotlk/quest=1104",image="assets/images/quests/placeholder.png",xpDiff=4,money=2500,desc="I have so many designs for our rocket car!  So many!  And I must try them all!!$B$BI'm working on a new type of fuel.  One that burns really really really hot!!  I haven't gotten the mixture perfect, but I think I know what I need...$B$BThe scorpids who wander the Shimmering Flats have a venom with lots and lots of salt in it.  It's very unique!  And it's just what I need!$B$BBring me venom and trust me -- our car will fly!!",logDesc="Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats."} end
if not DB[1105] then DB[1105]={id=1105,zoneId=400,name="Hardened Shells",level=30,minLevel=28,giver="Wizzle Brassbolts",giverType="NPC",giverId=4453,ender="Wizzle Brassbolts",enderType="NPC",enderId=4453,poiX=-6229,poiY=-3872,wowhead="https://www.wowhead.com/wotlk/quest=1105",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="My brother is working on a new fuel for his rocket car.  He's brilliant, he really is.  So brilliant that... I think that new fuel he's designing is strong enough to eat right through the car's chassis!$B$BI want to reinforce its fuel tanks before that happens.$B$BThe tortoises out on the flats have very hard shells.  I want to use them to create new tanks for our rocket car.  Tanks that can hold my brother's new fuel.$B$BYou look responsible enough.  Will you get me those shells?",logDesc="Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats."} end
if not DB[1106] then DB[1106]={id=1106,zoneId=400,name="Martek the Exiled",level=35,minLevel=26,giver="Fizzle Brassbolts",giverType="NPC",giverId=4454,ender="Martek the Exiled",enderType="NPC",enderId=4618,rewardNextId=1108,poiX=-6229,poiY=-3868,wowhead="https://www.wowhead.com/wotlk/quest=1106",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I'm developing a new engine that'll make the car go so fast!  Fast enough to fly, I know it!  I just need to make pistons that can handle very very heavy stress.  All my trials have failed because I can't make pistons hard enough!$B$BBut there is someone who might know how.$B$BHis name is Martek the Exiled.  He is a great smith and knows more about metal than anyone.  Take him this letter, I know he can help!$B$BBut he's far far away -- in Azeroth, in the Badlands, in a camp, with a goblin!$B$BFind him!",logDesc="Bring Fizzle's Letter to Martek the Exiled in the Badlands."} end
if not DB[1107] then DB[1107]={id=1107,zoneId=400,name="Encrusted Tail Fins",level=35,minLevel=28,giver="Wizzle Brassbolts",giverType="NPC",giverId=4453,ender="Wizzle Brassbolts",enderType="NPC",enderId=4453,poiX=-6229,poiY=-3872,wowhead="https://www.wowhead.com/wotlk/quest=1107",image="assets/images/quests/placeholder.png",xpDiff=5,money=3500,desc="Our rocket car is the fastest thing on the flats!  So fast that ... I'm afraid friction is going to tear it apart!$B$BTo prevent that I need to create a composite to coat the car's moving parts.  It must be hard but not brittle, and must be resistant to salt corrosion, or time spent on the Shimmering Flats will eat it away.$B$BHave you heard of the Vile Reef, $N?  It's off the coast of Stranglethorn Vale.  Saltscale murlocs live there, and their tail fins are a crucial ingredient of my composite.",logDesc="Bring 10 Encrusted Tail Fins to Wizzle Brassbolts in the Shimmering Flats."} end
if not DB[1108] then DB[1108]={id=1108,zoneId=400,name="Indurium",level=39,minLevel=28,giver="Martek the Exiled",giverType="NPC",giverId=4618,ender="Martek the Exiled",enderType="NPC",enderId=4618,poiX=-6763,poiY=-3129,wowhead="https://www.wowhead.com/wotlk/quest=1108",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'm not out here just to stay away from people.  There is a wealth of metal in the Badlands, $N, if you have the guts to get it.$B$BThe metal's called indurium and as luck would have it, it is rumored to possess high resistance to heat and stress.  It might work for Fizzle's car.$B$BBut let's make sure.  Get me samples of indurium and I'll test its properties.$B$BTrue indurium ore lies deep in Uldaman, but the Stonevault troggs of the Badlands sometimes have flakes of it on them.  Bring me those flakes.",logDesc="Bring 10 Indurium Flakes to Martek the Exiled in the Badlands."} end
if not DB[1109] then DB[1109]={id=1109,zoneId=1717,name="Going, Going, Guano!",level=26,minLevel=22,giver="Master Apothecary Faranell",giverType="NPC",giverId=2055,ender="Master Apothecary Faranell",enderType="NPC",enderId=2055,rewardNextId=1113,poiX=1434,poiY=405,wowhead="https://www.wowhead.com/wotlk/quest=1109",image="assets/images/quests/placeholder.png",xpDiff=7,desc="As you can see, $n, we're up to some very.... interesting experiments at the Royal Apothecary Society.$b$bAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!$b$bYou look well traveled for a $c. Perhaps you can aid me.$b$bI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...",logDesc="Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity."} end
if not DB[1110] then DB[1110]={id=1110,zoneId=400,name="Rocket Car Parts",level=31,minLevel=28,giver="Kravel Koalbeard",giverType="NPC",giverId=4452,ender="Kravel Koalbeard",enderType="NPC",enderId=4452,poiX=-6233,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=1110",image="assets/images/quests/placeholder.png",xpDiff=5,money=3000,desc="Heh heh, with all the races they're running here, it's no surprise that a few mishaps happen along the way.  If you look around the Shimmering Flats then you'll see evidence of past crashes -- scraps of rocket car parts are littered everywhere!$B$BAnd those parts are worth money to the gnomes and goblins.  They're always looking for more contraptions to slap onto their cars.$B$BSo go out and get me parts.  Bring me a heap and I'll pay you well.",logDesc="Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats."} end
if not DB[1111] then DB[1111]={id=1111,zoneId=400,name="Wharfmaster Dizzywig",level=36,minLevel=30,giver="Kravel Koalbeard",giverType="NPC",giverId=4452,ender="Wharfmaster Dizzywig",enderType="NPC",enderId=3453,rewardNextId=1112,poiX=-6233,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=1111",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I make it my job to get people what they need, and the gnomes over there need a parts order filled.  Their parts were shipped to Ratchet a week ago, but I haven't been able to make the trip.$B$BSo, are you ready for some legwork?  Go to Ratchet and give this parts order to Wharfmaster Dizzywig -- he'll probably be at the docks.$B$BDo this for me, and I'll have more jobs for you.$B$BJobs, my friend, with serious profit potential...",logDesc="Bring Kravel's Parts Order to Wharfmaster Dizzywig at Ratchet in the Barrens."} end
if not DB[1112] then DB[1112]={id=1112,zoneId=400,name="Parts for Kravel",level=36,minLevel=30,giver="Wharfmaster Dizzywig",giverType="NPC",giverId=3453,ender="Kravel Koalbeard",enderType="NPC",enderId=4452,poiX=-986,poiY=-3797,wowhead="https://www.wowhead.com/wotlk/quest=1112",image="assets/images/quests/placeholder.png",xpDiff=3,money=2000,desc="Here's Kravel's package, $N.  And when you deliver it, tell him... if he wants more special orders, then he'll have to pay his tab!",logDesc="Bring Kravel's Parts to Kravel Koalbeard on the Shimmering Flats in Thousand Needles."} end
if not DB[1113] then DB[1113]={id=1113,zoneId=796,name="Hearts of Zeal",level=33,minLevel=30,giver="Master Apothecary Faranell",giverType="NPC",giverId=2055,ender="Master Apothecary Faranell",enderType="NPC",enderId=2055,poiX=1434,poiY=405,wowhead="https://www.wowhead.com/wotlk/quest=1113",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Why do I need a rare type of guano, you might ask. Well, for this experiment I want to see what effect two diametrically opposed chemical substances can have on each other, especially when both are combined with an ever-toxic agent to ensure the most... ghastly results.$b$bIn the northeastern peaks of Tirisfal Glades lies the Scarlet Monastery. There the crazed disciples of the Scarlet Crusade congregate, both inside and outside the halls. Which you slay matters not, any of them may have the heart I need.",logDesc="Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal."} end
if not DB[1114] then DB[1114]={id=1114,zoneId=400,name="Delivery to the Gnomes",level=36,minLevel=30,giver="Kravel Koalbeard",giverType="NPC",giverId=4452,ender="Fizzle Brassbolts",enderType="NPC",enderId=4454,poiX=-6233,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=1114",image="assets/images/quests/placeholder.png",xpDiff=2,money=1000,desc="Now that I have what I need, give these parts to Fizzle Brassbolts.  He's been waiting a long time for them -- I'm sure he won't miss the little piece I removed from his order...$B$BAnd I wouldn't bother mentioning it to him.  It was small and worthless.$B$BTrust me.",logDesc="Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats."} end
if not DB[1115] then DB[1115]={id=1115,zoneId=400,name="The Rumormonger",level=36,minLevel=30,giver="Kravel Koalbeard",giverType="NPC",giverId=4452,ender="Krazek",enderType="NPC",enderId=773,rewardNextId=1116,poiX=-6233,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=1115",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Now that we've done a service for the gnomes, it's time to do the goblins a favor!  $B$BI hear that the goblin racer pilot, Nazz Steamboil, didn't always use that name.  I wonder why he changed it.  I wonder if it's a secret, and... I wonder if he values that secret.$B$BIf anyone knows the truth, then it's Krazek of Booty Bay, on the southern tip of Stranglethorn.  Speak with Krazek and ask him about our goblin pilot.$B$BIf you can get useful information from him, then we might just turn a profit from it.",logDesc="Talk to Krazek at Booty Bay in Stranglethorn Vale."} end
if not DB[1116] then DB[1116]={id=1116,zoneId=8,name="Dream Dust in the Swamp",level=36,minLevel=30,giver="Krazek",giverType="NPC",giverId=773,ender="Krazek",enderType="NPC",enderId=773,rewardNextId=1117,poiX=-14453,poiY=501,wowhead="https://www.wowhead.com/wotlk/quest=1116",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Getting the information on Nazz is quite a favor, $N.  Yes, quite a favor.  But you've come all the way from the Shimmering Flats to get it... are you willing to travel some more?$B$BWhile I contact my sources, why don't you gather something for me, eh?$B$BHm... what will it be?  How about dream dust, from the dragon whelps of the Swamp of Sorrows.  Yes, I'd love some dream dust for my snuff pouch!$B$BGet it for me, $N, and I'll give you the information you seek.",logDesc="Bring 10 Specks of Dream Dust to Krazek in Booty Bay.  Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows."} end
if not DB[1117] then DB[1117]={id=1117,zoneId=400,name="Rumors for Kravel",level=36,minLevel=30,giver="Krazek",giverType="NPC",giverId=773,ender="Kravel Koalbeard",enderType="NPC",enderId=4452,poiX=-14453,poiY=501,wowhead="https://www.wowhead.com/wotlk/quest=1117",image="assets/images/quests/placeholder.png",xpDiff=6,money=7500,desc="I had to use some of my favors, and gave away a rare bottle of elven wine, and did some heavy deducing myself!  But I found the information you seek.$B$BHere, I wrote a letter with some very interesting bits on our friend, Nazz Steamboil.  Do with it what you will -- it's too dangerous for me to use.$B$BJust don't tell anyone where you got it!",logDesc="Bring the Goblin Rumors to Kravel Koalbeard on the Shimmering Flats in Thousand Needles."} end
if not DB[1118] then DB[1118]={id=1118,zoneId=400,name="Back to Booty Bay",level=43,minLevel=35,giver="Kravel Koalbeard",giverType="NPC",giverId=4452,ender="Crank Fizzlebub",enderType="NPC",enderId=2498,poiX=-6233,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=1118",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, you're a $c I can trust, both to get the job done and to keep your mouth shut while doing it.$B$BI've been brewing up a new scheme.  It's risky, but if it works then we could both make a bundle!  And I think you're just the person to see it through.$B$BTo start, you must go back to Booty Bay.  I apologize, good $N.  I know my last task took you there.  But this time, speak with Crank Fizzlebub.$B$BGive him this letter.  And if he requires aid, do your best to help him.  It will be worth the effort.",logDesc="Bring Kravel's Scheme to Crank Fizzlebub at Booty Bay in Stranglethorn Vale."} end
if not DB[1119] then DB[1119]={id=1119,zoneId=400,name="Zanzil's Mixture and a Fool's Stout",level=44,minLevel=35,giver="Crank Fizzlebub",giverType="NPC",giverId=2498,ender="Kravel Koalbeard",enderType="NPC",enderId=4452,poiX=-14453,poiY=490,wowhead="https://www.wowhead.com/wotlk/quest=1119",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I figured out how to use Zanzil's mixture with stout to make a powerful libation.  A Fool's Stout.  I think it'll be just what Kravel needs, but try it out and let me know how it works.$B$BAnd $N, don't keep this stuff too long without using it.  Zanzil's mixture has a weird effect on the stout's yeast, kicking it into high gear.  So it won't stay fresh forever.",logDesc="Bring the Fool's Stout back to Kravel on the Shimmering Flats in Thousand Needles."} end
if not DB[1120] then DB[1120]={id=1120,zoneId=400,name="Get the Gnomes Drunk",level=44,minLevel=35,giver="Kravel Koalbeard",giverType="NPC",giverId=4452,ender="Gnome Pit Boss",enderType="NPC",enderId=4495,poiX=-6233,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=1120",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the gnomes, then here -- take the stout and give it to the gnome pit boss.$B$BAnd don't wait too long.  This stout will go bad eventually.",logDesc="Bring the Fool's Stout to the Gnome Pit Boss at Mirage Raceway in Thousand Needles."} end
if not DB[1121] then DB[1121]={id=1121,zoneId=400,name="Get the Goblins Drunk",level=44,minLevel=35,giver="Kravel Koalbeard",giverType="NPC",giverId=4452,ender="Goblin Pit Boss",enderType="NPC",enderId=4496,poiX=-6233,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=1121",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the goblins, then here -- take the stout and give it to the goblin pit boss.$B$BAnd don't wait too long.  This stout will go bad eventually.",logDesc="Bring the Fool's Stout to the Goblin Pit Boss at Mirage Raceway in Thousand Needles."} end
if not DB[1122] then DB[1122]={id=1122,zoneId=400,name="Report Back to Fizzlebub",level=44,minLevel=35,giver="Kravel Koalbeard",giverType="NPC",giverId=4452,ender="Crank Fizzlebub",enderType="NPC",enderId=2498,poiX=-6233,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=1122",image="assets/images/quests/placeholder.png",xpDiff=3,desc="That Fool's Stout worked great!  I placed a bet on the next race, and... let's hope the crew you got drunk did a number on their car!$B$BThere's only one more task for you -- take this note back to Crank Fizzlebub in Booty Bay.  He'll want to know of the successful test.$B$BAnd hopefully we can get more of that Fool's Stout for future races!",logDesc="Bring the Fool's Stout report to Crank Fizzlebub at Booty Bay in Stranglethorn Vale."} end
if not DB[1123] then DB[1123]={id=1123,zoneId=1638,name="Rabine Saturna",level=55,minLevel=54,giver="Arch Druid Hamuul Runetotem",giverType="NPC",giverId=5769,ender="Rabine Saturna",enderType="NPC",enderId=11801,rewardNextId=1124,poiX=-1049,poiY=-304,wowhead="https://www.wowhead.com/wotlk/quest=1123",image="assets/images/quests/placeholder.png",xpDiff=2,desc="For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris and Un'Goro.  He is located in Nighthaven, the main village of Moonglade.$B$BI want to impart on you the importance of your presence.  There are growing tensions between the night elves of Darnassus and the Cenarion Circle in Moonglade.  Look beyond racial boundaries and tap into the wisdom of your ancestors in dealings with the Circle there, $N.  Good luck.",logDesc="Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold."} end
if not DB[1124] then DB[1124]={id=1124,zoneId=493,name="Wasteland",level=55,minLevel=54,giver="Rabine Saturna",giverType="NPC",giverId=11801,ender="Layo Starstrike",enderType="NPC",enderId=13220,rewardNextId=1125,poiX=7797,poiY=-2574,wowhead="https://www.wowhead.com/wotlk/quest=1124",image="assets/images/quests/placeholder.png",xpDiff=3,desc="West of Un'Goro Crater, via the northwestern ridge, is a harsh wasteland - Silithus.  Few know that an ancient war was waged there between the night elves and a malign, alien power.  The evil was sealed, but now we suspect that forces work to stir this... unspeakable horror.$B$BSeek out Layo Starstrike, one of our agents in Silithus; look for him at Valor's Rest, the final resting spot for the fallen of the wastes.  Give him this letter, and he will give you his trust accordingly.",logDesc="Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter."} end
if not DB[1125] then DB[1125]={id=1125,zoneId=1377,name="The Spirits of Southwind",level=55,minLevel=54,giver="Layo Starstrike",giverType="NPC",giverId=13220,ender="Layo Starstrike",enderType="NPC",enderId=13220,rewardNextId=1126,poiX=-6398,poiY=-314,wowhead="https://www.wowhead.com/wotlk/quest=1125",image="assets/images/quests/placeholder.png",xpDiff=5,desc="To our southwest lies a tragic site - the ruins of Southwind Village.  This is where our work should begin, $N.$B$BFrom what we've learned, this village was once a night elf base of operations for Silithus.  It's long since overrun by the silithid hives that infest the wastes.  I can only imagine the horror of the village's initial sundering...$B$BThe tortured spirits of fallen druids and sentinels wander the ruins aimlessly.  Explore this locale, freeing the souls of these wretched beings as needed.",logDesc="Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village, and then return to Layo Starstrike at the Valor's Rest graveyard of Silithus."} end
if not DB[1126] then DB[1126]={id=1126,zoneId=1377,name="Hive in the Tower",level=57,minLevel=54,giver="Layo Starstrike",giverType="NPC",giverId=13220,ender="Layo Starstrike",enderType="NPC",enderId=13220,rewardNextId=6844,poiX=-6398,poiY=-314,wowhead="https://www.wowhead.com/wotlk/quest=1126",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The hive needs to be addressed in Southwind Village, and I think I know a way to get at them.  It's been my experience that the silithid hives are very sensitive to their environment; this explains their attacks when hearing the death wails of the spirits.$B$BThe silithid are strongest in the tower - the one with the mass of wasps circling it.  Scale the tower and jostle the hive into activity.  Report back what you learn, but be careful!  If you uncover anything that might help, bring it to me.",logDesc="Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity.  Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus."} end
if not DB[1127] then DB[1127]={id=1127,zoneId=33,name="Fool's Stout",level=44,minLevel=35,giver="Crank Fizzlebub",giverType="NPC",giverId=2498,ender="Crank Fizzlebub",enderType="NPC",enderId=2498,poiX=-14453,poiY=490,wowhead="https://www.wowhead.com/wotlk/quest=1127",image="assets/images/quests/placeholder.png",desc="So you want some Fool's Stout, eh?  Thinking of heading back to the races...?$B$BAll right, bring me more of Zanzil's mixture and I'll make some more stout for you.",logDesc="Bring 12 of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.",rewards={{id=5806,qty=1}}} end
if not DB[1128] then DB[1128]={id=1128,zoneId=400,name="<NYI> The Gnome Pit Crew is Thirsty",level=44,minLevel=35,wowhead="https://www.wowhead.com/wotlk/quest=1128",image="assets/images/quests/placeholder.png"} end
if not DB[1129] then DB[1129]={id=1129,zoneId=400,name="<NYI> The Goblin Pit Crew is Thirsty",level=44,minLevel=35,wowhead="https://www.wowhead.com/wotlk/quest=1129",image="assets/images/quests/placeholder.png"} end
if not DB[1130] then DB[1130]={id=1130,zoneId=1638,name="Melor Sends Word",level=30,minLevel=20,giver="Jorn Skyseer",giverType="NPC",giverId=3387,ender="Melor Stonehoof",enderType="NPC",enderId=3441,rewardNextId=1131,poiX=-2383,poiY=-1923,wowhead="https://www.wowhead.com/wotlk/quest=1130",image="assets/images/quests/placeholder.png",desc="$N, Melor Stonehoof has heard of your deeds, and has set a path before you.$B$BIf you wish to take it, then go to Thunder Bluff and speak with Melor.  You will find him on Hunter's Rise.",logDesc="Speak with Melor Stonehoof in Thunder Bluff."} end
if not DB[1131] then DB[1131]={id=1131,zoneId=1638,name="Steelsnap",level=30,minLevel=20,giver="Melor Stonehoof",giverType="NPC",giverId=3441,ender="Melor Stonehoof",enderType="NPC",enderId=3441,poiX=-1413,poiY=-126,wowhead="https://www.wowhead.com/wotlk/quest=1131",image="assets/images/quests/placeholder.png",xpDiff=5,desc="At times we hunt for food.  At times we hunt for honor.  And at times we hunt to earn the Earthmother's teachings.$B$BBut the hunt I now set upon you is none of these things.  It is to slay a creature outside the Earthmother's blessing.$B$BThe hyena Steelsnap roams the Thousand Needles, south of the Barrens.  He is a tyrant, attracting other hyenas to him and spreading fear and bloodshed among more peaceful beasts.$B$BFind Steelsnap, $N.  Find him, and defeat him.",logDesc="Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff."} end
if not DB[1132] then DB[1132]={id=1132,zoneId=11,name="Fiora Longears",level=20,minLevel=18,rewardNextId=1133,wowhead="https://www.wowhead.com/wotlk/quest=1132",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Oh, to be at sea once again!  To feel the kiss of the wind, and to have the waves rock me like my blessed mother, long ago!$B$BOh, I wish I had your fortune, good $c, for I see the sea in your future!$B$BIt's my job to tell eager souls of the land of Kalimdor, the land of opportunity!  If you're willing to try your luck across the sea, then take a ship from here to the lovely port of Auberdine.  Speak there with my partner, the elf, Fiora Longears.$B$BShe'll start you on your Kalimdor adventure!",logDesc="Speak with Fiora Longears on the docks at Auberdine in Darkshore."} end
if not DB[1133] then DB[1133]={id=1133,zoneId=148,name="Journey to Astranaar",level=20,minLevel=18,wowhead="https://www.wowhead.com/wotlk/quest=1133",image="assets/images/quests/placeholder.png",desc="$N, go to Astranaar.  I'm sure an eager member of the Alliance such as you can do some real good there.  Speak with Shindrell Swiftfire and offer your services.$B$BBut don't bother mentioning who sent you.  Shindrell does not know me...",logDesc="Speak with Shindrell Swiftfire in Astranaar."} end
if not DB[1134] then DB[1134]={id=1134,zoneId=331,name="Pridewings of Stonetalon",level=21,minLevel=18,giver="Shindrell Swiftfire",giverType="NPC",giverId=3845,ender="Shindrell Swiftfire",enderType="NPC",enderId=3845,poiX=2796,poiY=-299,wowhead="https://www.wowhead.com/wotlk/quest=1134",image="assets/images/quests/placeholder.png",xpDiff=5,money=1300,desc="We are not in open war with the Horde, but our peace is fragile.  We often find their agents moving against us, but they do so covertly.$B$BOne such advance was revealed to us from hidden sources in Theramore, claiming that the orcs collect venom from the pridewings near Mirkfallon Lake, in the Stonetalon Mountains to the south.  Orc assassins then use the venom on their secret death raids against the Alliance!$B$BIf this is true, then we must stop them, $N.  We must deny them their source of venom.",logDesc="Bring 12 Pridewing Venom Sacs to Shindrell Swiftfire in Astranaar."} end
if not DB[1135] then DB[1135]={id=1135,zoneId=15,name="Highperch Venom",level=30,minLevel=25,wowhead="https://www.wowhead.com/wotlk/quest=1135",image="assets/images/quests/placeholder.png",xpDiff=7,desc="As you may know, wyverns are often tamed by orcs for use as mounts.  But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself.  So if you're not afraid to do a little wyvern hunting, then... I have a job for you.$B$BThere is a place called Highperch in the land of a Thousand Needles, west of here.  The Highperch wyverns have a potent venom.  Potent, and valuable.",logDesc="Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore.",rewards={{id=6719,qty=1}}} end
if not DB[1136] then DB[1136]={id=1136,zoneId=1638,name="Frostmaw",level=37,minLevel=26,giver="Melor Stonehoof",giverType="NPC",giverId=3441,ender="Melor Stonehoof",enderType="NPC",enderId=3441,poiX=-1413,poiY=-126,wowhead="https://www.wowhead.com/wotlk/quest=1136",image="assets/images/quests/placeholder.png",xpDiff=7,desc="$N, it is now time for you to travel to far-off lands.  You are ready.$B$BYou now hunt Frostmaw, a yeti in the Alterac Mountains.  He is elusive, his white coat blending into the snows of his mountain home.  He rarely shows himself.$B$BBut I will show you how to entice a creature such as he.  Here, take this scroll.  On it I have written how Frostmaw may be lured.$B$BNow go, $N.  Your journey is long and many challenges lay waiting.  When you return with Frostmaw's mane, only then is your task complete.",logDesc="Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.",rewards={{id=6720,qty=1}}} end
if not DB[1137] then DB[1137]={id=1137,zoneId=400,name="News for Fizzle",level=38,minLevel=28,giver="Martek the Exiled",giverType="NPC",giverId=4618,ender="Fizzle Brassbolts",enderType="NPC",enderId=4454,poiX=-6763,poiY=-3129,wowhead="https://www.wowhead.com/wotlk/quest=1137",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Indurium has an amazing resistance to heat!  I'm sure it will work for Fizzle's pistons.  But he'll need true indurium ore, not just the flakes.$B$BTo get the ore, it must be mined from deep within Uldaman, on the northern borders of the Badlands.  That is the true source of indurium.$B$BSend Fizzle Brassbolts my regards, and tell him what I told you.$B$BSafe travels, $N.  And it won't surprise me if we meet again -- once Fizzle learns of indurium he'll probably send you to Uldaman to acquire it!",logDesc="Speak with Fizzle Brassbolts on the Shimmering Flats in Thousand Needles.",choiceRewards={{id=6729,qty=1},{id=6732,qty=1}}} end
if not DB[1138] then DB[1138]={id=1138,zoneId=148,name="Fruit of the Sea",level=17,minLevel=15,giver="Gubber Blump",giverType="NPC",giverId=10216,ender="Gubber Blump",enderType="NPC",enderId=10216,poiX=6371,poiY=577,wowhead="https://www.wowhead.com/wotlk/quest=1138",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I love crab.  Crabs are the fruit of the sea!  You can bake it, barbecue it, boil it, and broil it.  They're pan fried, deep fried, and stir fried.  There's crab salad, crab soup, crab stew, pepper crab, lemon crab, whipper root crab, and Ironforge surprise crab.  That's... that's about it.$B$BI'm here fishing right now, so I can't get any fine crab chunks.  You can pick them out of reef crawlers and encrusted tide crawlers.  You can make a lot with it.  You can bake it, barbecue it, boil it...",logDesc="Collect 6 Fine Crab Chunks for Gubber Blump in Auberdine.",choiceRewards={{id=15405,qty=1},{id=15406,qty=1}}} end
if not DB[1139] then DB[1139]={id=1139,zoneId=1517,name="The Lost Tablets of Will",level=45,minLevel=35,giver="Advisor Belgrum",giverType="NPC",giverId=2918,ender="Advisor Belgrum",enderType="NPC",enderId=2918,poiX=-4620,poiY=-1325,wowhead="https://www.wowhead.com/wotlk/quest=1139",image="assets/images/quests/placeholder.png",xpDiff=7,money=13000,desc="We've slowed the Shadowforge clan by cutting them off from Blackrock Spire, but Hammertoe's quest is still unfulfilled. His death must not be in vain. He dreamt of finding the Tablet of Will: a stone shard inscribed with magic by the titans themselves to help imbue their creations with life--making them have a will of their own, or so the legends say.$B$BWe must still recover the Tablet before the Shadowforge clan finds it.$B$BReturn to Uldaman, find the tablet, and return here immediately.",logDesc="Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.",rewards={{id=6723,qty=1}}} end
if not DB[1140] then DB[1140]={id=1140,zoneId=148,name="The Tower of Althalaxx",level=28,minLevel=13,giver="Delgren the Purifier",giverType="NPC",giverId=3663,ender="Delgren the Purifier",enderType="NPC",enderId=3663,rewardNextId=1167,poiX=3185,poiY=189,wowhead="https://www.wowhead.com/wotlk/quest=1140",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The writing of the orcs is little better than the scribblings of a child. Many of my order scoffed when I chose to learn their tongue, but I have found it beneficial to gain further understanding of my enemies.$b$bFrom Ilkrud's scribblings, it appears that Athrikus still possesses two soulgems, and they are being held in Night Run and Satyrnaar, satyr-held areas in northeast Ashenvale.$b$bBe careful out there, $n, the satyrs' blood-soaked temples can be unsettling even for a seasoned $c such as yourself.",logDesc="Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post."} end
if not DB[1141] then DB[1141]={id=1141,zoneId=148,name="The Family and the Fishing Pole",level=14,minLevel=10,giver="Gubber Blump",giverType="NPC",giverId=10216,ender="Gubber Blump",enderType="NPC",enderId=10216,poiX=6371,poiY=577,wowhead="https://www.wowhead.com/wotlk/quest=1141",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I love fishing.  The Blump family is known for fishing.  My name is Gubber Blump; I fish.$B$BThere's a kind of fish I like to catch around these parts called Darkshore grouper.  I used to go out on a boat to fish for grouper, but no boats have been going out since them mean ol' murlocs moved in.  I bet they been eating up all the grouper too.$B$BSay, you wanna help me catch Darkshore grouper?  I'd give you a bona fide Blump Family Fishing Pole if you did!  It's a real good pole to catch fish with.",logDesc="Catch 6 Darkshore Grouper for Gubber Blump in Auberdine.",rewards={{id=12225,qty=1}}} end
if not DB[1142] then DB[1142]={id=1142,zoneId=1717,name="Mortality Wanes",level=30,minLevel=25,giver="Heralath Fallowbrook",giverType="NPC",giverId=4510,ender="Treshala Fallowbrook",enderType="NPC",enderId=4521,poiX=2187,poiY=1789,wowhead="https://www.wowhead.com/wotlk/quest=1142",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I have not long to live... so... so... weak.$b$b...the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel...$b$bBut before I... d-d-die...$b$b...my wife, Treshala... her pendant of bonding to me... stolen... by one of the f-f-foul aggressors...$b$bFind it p-p-please... and return it to Treshala in Darnassus...$b$b...along with w-w-word of my lonely... death.",logDesc="Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.",choiceRewards={{id=6751,qty=1},{id=6752,qty=1}}} end
if not DB[1143] then DB[1143]={id=1143,zoneId=148,name="The Tower of Althalaxx",level=31,minLevel=13,giver="Balthule Shadowstrike",giverType="NPC",giverId=3661,ender="Balthule Shadowstrike",enderType="NPC",enderId=3661,rewardNextId=981,poiX=7247,poiY=-659,wowhead="https://www.wowhead.com/wotlk/quest=1143",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I see. Well, if what you say is true, then now is the time to strike. I believe Athrikus resides at the top of the tower. Be careful though, he is surrounded by many powerful warlocks, much more deadly than the ones you faced before.",logDesc="Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx."} end
if not DB[1144] then DB[1144]={id=1144,zoneId=1717,name="Willix the Importer",level=30,minLevel=22,giver="Willix the Importer",giverType="NPC",giverId=4508,ender="Willix the Importer",enderType="NPC",enderId=4508,poiX=2194,poiY=1792,wowhead="https://www.wowhead.com/wotlk/quest=1144",image="assets/images/quests/placeholder.png",xpDiff=7,desc="At last, help has arrived!$b$bYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.$b$bYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that Mebok Mizzyrix was paying well for Blueleaf Tuber from this here pig pen. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!$b$bAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.",logDesc="Escort Willix the Importer to the exit of Razorfen Kraul.",choiceRewards={{id=6748,qty=1},{id=6750,qty=1},{id=6749,qty=1}}} end
if not DB[1145] then DB[1145]={id=1145,zoneId=17,name="The Swarm Grows",level=33,minLevel=29,giver="Korran",giverType="NPC",giverId=3428,ender="Belgrom Rockmaul",enderType="NPC",enderId=4485,rewardNextId=1146,poiX=-389,poiY=-2552,wowhead="https://www.wowhead.com/wotlk/quest=1145",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Many travelers who've come through the Crossroads helped me gather eggs from the Field of Giants, and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought.$B$BI need a courier to travel to Orgrimmar to meet Belgrom Rockmaul. It be no simple matter, and someone who would take the task seriously should go.$B$BBelgrom usually be found outside the warriors' guild house.",logDesc="Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar."} end
if not DB[1146] then DB[1146]={id=1146,zoneId=1637,name="The Swarm Grows",level=33,minLevel=29,giver="Belgrom Rockmaul",giverType="NPC",giverId=4485,ender="Moktar Krin",enderType="NPC",enderId=4483,rewardNextId=1147,poiX=1954,poiY=-4736,wowhead="https://www.wowhead.com/wotlk/quest=1146",image="assets/images/quests/placeholder.png",xpDiff=4,desc="So, Korran has come to a similar conclusion about these insects--they seem to be a larger threat than we assumed.$B$BA few days ago a hunter returned to me from Thousand Needles nearly dead. He was with a raiding party sent to drive a dwarven excavation team out of the Shimmering Flats. During the attack, more of these insects erupted from a cave in the dig site and nearly killed the party.$B$BThey were led by Moktar Krin, and they've taken refuge on the border of the Shimmering Flats. Bring him this note.",logDesc="Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles."} end
if not DB[1147] then DB[1147]={id=1147,zoneId=400,name="The Swarm Grows",level=35,minLevel=29,giver="Moktar Krin",giverType="NPC",giverId=4483,ender="Moktar Krin",enderType="NPC",enderId=4483,poiX=-5842,poiY=-3407,wowhead="https://www.wowhead.com/wotlk/quest=1147",image="assets/images/quests/placeholder.png",xpDiff=5,money=3500,desc="Hmm. Seems Belgrom thinks those monsters are a threat. He wants them pushed back into whatever depths they crawled up out of.$B$BI guess killing the dwarves sent by the Explorers' League wasn't enough--now I have to send a half-dead war party into another battle. We won't be able to do it ourselves; not while we're in this condition. The dig site's to the south of here. There shouldn't be anymore dwarves to deal with. Feel up to wielding a blade or staff and doing your part to aid us?",logDesc="Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles."} end
if not DB[1148] then DB[1148]={id=1148,zoneId=400,name="Parts of the Swarm",level=35,minLevel=28,ender="Korran",enderType="NPC",enderId=3428,rewardNextId=1184,wowhead="https://www.wowhead.com/wotlk/quest=1148",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You inspect the carapace carefully. As you turn it over in your hands you realize that the chitinous plating is interlaced in such a way that makes it incredibly strong. It's unlike anything you've ever seen. You inspect the rest of the corpse further and realize that these creatures are very powerful and highly evolved.$B$BLooking down at the carapace again, you think that Korran would enjoy studying more of these creatures. It could help him figure out what these creatures are, and where they come from.",logDesc="Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads."} end
if not DB[1149] then DB[1149]={id=1149,zoneId=400,name="Test of Faith",level=26,minLevel=25,giver="Dorn Plainstalker",giverType="NPC",giverId=2986,ender="Dorn Plainstalker",enderType="NPC",enderId=2986,rewardNextId=1150,poiX=-5184,poiY=-2807,wowhead="https://www.wowhead.com/wotlk/quest=1149",image="assets/images/quests/placeholder.png",xpDiff=3,desc="So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew.$B$BMany facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you.$B$BIf you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether.$B$BThe first is a Test of Faith.",logDesc="If you have faith, leap from the planks overlooking Thousand Needles."} end
if not DB[1150] then DB[1150]={id=1150,zoneId=400,name="Test of Endurance",level=30,minLevel=25,giver="Dorn Plainstalker",giverType="NPC",giverId=2986,ender="Dorn Plainstalker",enderType="NPC",enderId=2986,rewardNextId=1151,poiX=-5184,poiY=-2807,wowhead="https://www.wowhead.com/wotlk/quest=1150",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'm pleased to see your courage remains steadfast in light of what you've already done. Since your faith is intact, the time has come to test your body.$B$BFirst is a test of endurance. Go to the Roguefeather Den west of Freewind Post. Make your way to the depths of their lair and destroy their foodstuffs. By then you should have provoked their fury, and if you are able to survive long enough, Grenka Bloodscreech herself will come for you--kill her and bring me her claw to complete your test.",logDesc="Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles."} end
if not DB[1151] then DB[1151]={id=1151,zoneId=400,name="Test of Strength",level=30,minLevel=25,giver="Dorn Plainstalker",giverType="NPC",giverId=2986,ender="Dorn Plainstalker",enderType="NPC",enderId=2986,rewardNextId=1152,poiX=-5184,poiY=-2807,wowhead="https://www.wowhead.com/wotlk/quest=1151",image="assets/images/quests/placeholder.png",xpDiff=6,desc="During the time of the Old Gods, elementals inhabited much of this world. They worshipped the Old Gods, and the Gods, through their power, kept the elementals bound to this world. When the Old Gods were banished, the elementals faded from our world and now only return at the bidding of powerful mages.$B$BThere are exceptions though. Some elementals were powerful enough to remain here on their own. One such elemental is Rok'Alim.$B$BTo test your strength, find Rok'Alim in Thousand Needles and slay him.",logDesc="Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles."} end
if not DB[1152] then DB[1152]={id=1152,zoneId=400,name="Test of Lore",level=30,minLevel=25,giver="Dorn Plainstalker",giverType="NPC",giverId=2986,ender="Braug Dimspirit",enderType="NPC",enderId=4489,rewardNextId=1154,poiX=-5184,poiY=-2807,wowhead="https://www.wowhead.com/wotlk/quest=1152",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.$B$BIf you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, $N.$B$BWhen you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, $N, the night elves may wish to impede your test.",logDesc="Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."} end
if not DB[1153] then DB[1153]={id=1153,zoneId=17,name="A New Ore Sample",level=29,minLevel=25,giver="Tatternack Steelforge",giverType="NPC",giverId=3433,ender="Tatternack Steelforge",enderType="NPC",enderId=3433,poiX=-2285,poiY=-1947,wowhead="https://www.wowhead.com/wotlk/quest=1153",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="$C, you have done well in helping me in the past. The warchief is pleased thus far with what I've accomplished, and asks me to continue with renewed determination. My honor dictates that I give you proper recognition to the warchief for all you have done, but first I would ask you for your help again.$B$BTravelers recently came from the south from a place called Thousand Needles. There they killed a kobold who had an unusual ore sample, but they would not sell it. I want a sample of that ore to examine.",logDesc="Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.",rewards={{id=6741,qty=1}}} end
if not DB[1154] then DB[1154]={id=1154,zoneId=400,name="Test of Lore",level=30,minLevel=25,giver="Braug Dimspirit",giverType="NPC",giverId=4489,ender="Braug Dimspirit",enderType="NPC",enderId=4489,rewardNextId=6627,poiX=1429,poiY=-602,wowhead="https://www.wowhead.com/wotlk/quest=1154",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You have passed Dorn's tests, and now you seek to pass your next trial. Very good. But up until now, your challenges have been childish. It is easy to test your body--your mind is another matter completely.$B$BI shall explain it simply: find the book I name, study it, and answer my question about its contents.$B$BWhat book, you must be asking? The Legacy of the Aspects. It can be found at the bottom of Dor'danil in southern Ashenvale, protected by the dead druids and their slayers.",logDesc="Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."} end
if not DB[1155] then DB[1155]={id=1155,zoneId=1377,name="<NYI> <TXT> bug crystal side quest",level=55,minLevel=54,wowhead="https://www.wowhead.com/wotlk/quest=1155",image="assets/images/quests/placeholder.png",desc="x",logDesc="x"} end
