if not DB[1159] then DB[1159]={id=1159,zoneId=400,name="Test of Lore",level=30,minLevel=25,giver="Braug Dimspirit",giverType="NPC",giverId=4489,ender="Parqual Fintallas",enderType="NPC",enderId=4488,rewardNextId=1160,poiX=1429,poiY=-602,wowhead="https://www.wowhead.com/wotlk/quest=1159",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Well done, $N. You have passed the first portion of the Test of Lore, but there is still another question to be answered. But that question is not mine to ask.$B$BSeek out Parqual Fintallas in Lordaeron City. He was a great historian for the humans before the Plague overtook him. Now he continues to seek enlightenment, but of a different nature.$B$BHe will have another requirement of you before he asks you anything, but you have done masterfully thus far--I'm sure you will overcome his obstacle.",logDesc="Find Parqual Fintallas in Undercity."} end
if not DB[1160] then DB[1160]={id=1160,zoneId=796,name="Test of Lore",level=36,minLevel=25,giver="Parqual Fintallas",giverType="NPC",giverId=4488,ender="Parqual Fintallas",enderType="NPC",enderId=4488,rewardNextId=6628,poiX=1459,poiY=319,wowhead="https://www.wowhead.com/wotlk/quest=1160",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I will tell you what you must seek, and I will even ask you my question, but not because you wish to prove yourself. Knowledge is far more important than strength. Even as others seem to pass you by in ability, your knowledge of the world will be more valuable.$B$BGo to the Monastery in the north of Tirisfal Glades. In the library there, a book called Beginnings of the Undead Threat resides. It was used by the now-corrupt paladins there to train them to fight my kind.$B$BBring it to me.",logDesc="Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity."} end
