if not DB[1163] then DB[1163]={id=1163,zoneId=1377,name="<NYI> <TXT> speak to tyrande whisperwind",level=58,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=1163",image="assets/images/quests/placeholder.png",desc="x",logDesc="x"} end
if not DB[1164] then DB[1164]={id=1164,zoneId=1497,name="To Steal From Thieves",level=36,minLevel=27,giver="Genavie Callow",giverType="NPC",giverId=4486,ender="Genavie Callow",enderType="NPC",enderId=4486,poiX=1561,poiY=261,wowhead="https://www.wowhead.com/wotlk/quest=1164",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!$B$BMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, her and her lousy children had the audacity to steal the only precious belongings I had left.$B$BI don't care about the things they stole any more. What I want now are their heads!$B$BKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.",logDesc="Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.",choiceRewards={{id=4443,qty=1},{id=2032,qty=1}}} end
if not DB[1165] then DB[1165]={id=1165,zoneId=400,name="<NYI> Ore for the Races",level=42,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1165",image="assets/images/quests/placeholder.png"} end
if not DB[1166] then DB[1166]={id=1166,zoneId=15,name="Overlord Mok'Morokk's Concern",level=41,minLevel=37,giver="Overlord Mok'Morokk",giverType="NPC",giverId=4500,ender="Overlord Mok'Morokk",enderType="NPC",enderId=4500,poiX=-3133,poiY=-2880,wowhead="https://www.wowhead.com/wotlk/quest=1166",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Bow before Overlord Mok'Morokk!$b$bRexxar make me mighty leader of Stonemaul Clan!$b$bMe good leader. Me keep clan safe.$b$bBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.$b$bLeave old home so fast, me forget stuff. Tiny $r, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!",logDesc="Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp.",rewards={{id=10702,qty=1}}} end
if not DB[1167] then DB[1167]={id=1167,zoneId=148,name="The Tower of Althalaxx",level=28,minLevel=13,giver="Delgren the Purifier",giverType="NPC",giverId=3663,ender="Balthule Shadowstrike",enderType="NPC",enderId=3661,rewardNextId=1143,poiX=3185,poiY=189,wowhead="https://www.wowhead.com/wotlk/quest=1167",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Before confronting Athrikus, it would probably be wise for you to consult with Balthule. I have no doubt he has been vigilant in his watch of the Tower, and he may have information about recent developments.",logDesc="Speak with Balthule Shadowstrike near the Tower of Althalaxx."} end
if not DB[1168] then DB[1168]={id=1168,zoneId=15,name="Army of the Black Dragon",level=41,minLevel=37,giver="Tharg",giverType="NPC",giverId=4502,ender="Tharg",enderType="NPC",enderId=4502,poiX=-3132,poiY=-2937,wowhead="https://www.wowhead.com/wotlk/quest=1168",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.$b$bBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.$b$bOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.$b$bMe call Stonemaul Ruins home. Me like it in the south. This place not home.$b$bHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.",logDesc="Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.",choiceRewards={{id=9705,qty=1},{id=9706,qty=1}}} end
if not DB[1169] then DB[1169]={id=1169,zoneId=15,name="Identifying the Brood",level=41,minLevel=37,giver="Draz'Zilb",giverType="NPC",giverId=4501,ender="Draz'Zilb",enderType="NPC",enderId=4501,poiX=-3191,poiY=-2926,wowhead="https://www.wowhead.com/wotlk/quest=1169",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.$b$bWhy the puzzled stare, $n? Expecting me to speak like an uncouth ruffian merely because I am an ogre?$b$bNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...",logDesc="Draz'Zilb in Brackenwall Village would like you to bring him 7 Searing Tongues and 7 Searing Hearts.",choiceRewards={{id=9703,qty=1},{id=9704,qty=1}}} end
if not DB[1170] then DB[1170]={id=1170,zoneId=15,name="The Brood of Onyxia",level=41,minLevel=37,giver="Draz'Zilb",giverType="NPC",giverId=4501,ender="Overlord Mok'Morokk",enderType="NPC",enderId=4500,rewardNextId=1171,poiX=-3191,poiY=-2926,wowhead="https://www.wowhead.com/wotlk/quest=1170",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?$b$bThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.$b$bNotify Mok'Morokk at once! Action must be taken.",logDesc="Speak with Overlord Mok'Morokk in Brackenwall Village."} end
if not DB[1171] then DB[1171]={id=1171,zoneId=15,name="The Brood of Onyxia",level=41,minLevel=37,giver="Overlord Mok'Morokk",giverType="NPC",giverId=4500,ender="Draz'Zilb",enderType="NPC",enderId=4501,rewardNextId=1172,poiX=-3133,poiY=-2880,wowhead="https://www.wowhead.com/wotlk/quest=1171",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.",logDesc="Speak with Draz'Zilb in Brackenwall Village."} end
if not DB[1172] then DB[1172]={id=1172,zoneId=15,name="The Brood of Onyxia",level=41,minLevel=37,giver="Draz'Zilb",giverType="NPC",giverId=4501,ender="Draz'Zilb",enderType="NPC",enderId=4501,poiX=-3191,poiY=-2926,wowhead="https://www.wowhead.com/wotlk/quest=1172",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.$b$bMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.$b$bWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.$b$bAs for Mok'Morokk... I have other plans for the sod.",logDesc="Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia.",choiceRewards={{id=10700,qty=1},{id=10701,qty=1}}} end
if not DB[1173] then DB[1173]={id=1173,zoneId=15,name="Challenge Overlord Mok'Morokk",level=45,minLevel=38,giver="Overlord Mok'Morokk",giverType="NPC",giverId=4500,ender="Draz'Zilb",enderType="NPC",enderId=4501,poiX=-3133,poiY=-2880,wowhead="https://www.wowhead.com/wotlk/quest=1173",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You dare challenge Overlord Mok'Morokk?$b$bHaw!$b$bMe crush tiny $r!$b$bYou tell me when ready for good beating.",logDesc="Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.",choiceRewards={{id=10703,qty=1},{id=10704,qty=1}}} end
if not DB[1174] then DB[1174]={id=1174,zoneId=400,name="Gnomes Win!",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=1174",image="assets/images/quests/placeholder.png",rewards={{id=5857,qty=1}}} end
if not DB[1175] then DB[1175]={id=1175,zoneId=400,name="A Bump in the Road",level=33,minLevel=28,giver="Trackmaster Zherin",giverType="NPC",giverId=4629,ender="Trackmaster Zherin",enderType="NPC",enderId=4629,poiX=-6253,poiY=-4025,wowhead="https://www.wowhead.com/wotlk/quest=1175",image="assets/images/quests/placeholder.png",xpDiff=5,money=3500,desc="After the big crash with the goblins' Red Thunder racer and a basilisk, Kronkrider hired me on to take care of the track. I don't know what all the animals out on the flats are feeding on to grow so big, but we have to be careful to thin them out so they won't wander onto the track when a race is going on.$b$bTell you what. If you want to go out and make a little profit, go out and remove the basilisks from the area.",logDesc="Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats."} end
if not DB[1176] then DB[1176]={id=1176,zoneId=400,name="Load Lightening",level=30,minLevel=29,giver="Pozzik",giverType="NPC",giverId=4630,ender="Pozzik",enderType="NPC",enderId=4630,rewardNextId=1178,poiX=-6193,poiY=-3961,wowhead="https://www.wowhead.com/wotlk/quest=1176",image="assets/images/quests/placeholder.png",xpDiff=4,money=2500,desc="When it comes to racing, every bit counts! Whether it's a minor tweaking on the power output, a slight slackening on the tension coils, or lightening the weight of the frame, you have to take everything into account.$b$bWe use vulture bones for a lot of the minor structural tweaks we make to our racers, which offer the perfect balance of strength and weight. Even better, it's easy for us to get more, as the salt flats are littered with vultures.$b$bBring me some and I'll give you a good price on them.",logDesc="Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats."} end
if not DB[1177] then DB[1177]={id=1177,zoneId=15,name="Hungry!",level=36,minLevel=32,giver="Mudcrush Durtfeet",giverType="NPC",giverId=4503,ender="Mudcrush Durtfeet",enderType="NPC",enderId=4503,poiX=-3372,poiY=-2821,wowhead="https://www.wowhead.com/wotlk/quest=1177",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Mud big ogre.$b$bMe hungry.$b$bGo bash fishy. Bring Mud food.$b$bYou feed Mud or Mud eat you.",logDesc="Mudcrush Durtfeet in northern Dustwallow wants 8 Mirefin Heads.",choiceRewards={{id=9518,qty=1},{id=9519,qty=1}}} end
if not DB[1178] then DB[1178]={id=1178,zoneId=400,name="Goblin Sponsorship",level=37,minLevel=29,giver="Pozzik",giverType="NPC",giverId=4630,ender="Gazlowe",enderType="NPC",enderId=3391,rewardNextId=1180,poiX=-6193,poiY=-3961,wowhead="https://www.wowhead.com/wotlk/quest=1178",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Our racing team is the pride of goblins everywhere. You'd be surprised at some of the people who contribute in one way or another to our team.$b$bYou know Gazlowe? He tracks down parts from around the world for us. He even came down to work on one of our rigs once!$b$bA few weeks ago, he said he'd send us a new prototype fuel regulator but it hasn't come yet. He's usually very prompt... Maybe you wouldn't mind going to Ratchet to ask him about it? I wouldn't be so pushy, but the gnomes are gaining on us!",logDesc="Speak to Gazlowe at Ratchet in The Barrens."} end
if not DB[1179] then DB[1179]={id=1179,zoneId=400,name="The Brassbolts Brothers",level=30,minLevel=28,giver="Pilot Longbeard",giverType="NPC",giverId=2092,ender="Wizzle Brassbolts",enderType="NPC",enderId=4453,poiX=-5065,poiY=-1289,wowhead="https://www.wowhead.com/wotlk/quest=1179",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You ever heard of the Shimmering Flats?  It's a stretch of salt flats way over in Kalimdor, just south of the Thousand Needles canyon.  It's a great place for racing because, well, it's so flat!$B$BA couple of gnome brothers are out there, friends of mine, trying out their new rocket car, and from what I hear it's fast!  Heh, so fast that their pilots keep crashing.  Giving themselves concussions.$B$BSo they asked me for some Siege Engine helmets, but I have duties here.  I can't make the trip!$B$BCan you?",logDesc="Bring the crate of crash helmets to Wizzle Brassbolts at Mirage Raceway in Thousand Needles."} end
if not DB[1180] then DB[1180]={id=1180,zoneId=400,name="Goblin Sponsorship",level=37,minLevel=29,giver="Gazlowe",giverType="NPC",giverId=3391,ender="Wharfmaster Lozgil",enderType="NPC",enderId=4631,rewardNextId=1181,poiX=-836,poiY=-3729,wowhead="https://www.wowhead.com/wotlk/quest=1180",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Back to what you came here about. I know I promised Pozzik that I'd deliver a new fuel regulator for him, but I still haven't received it yet. Revilgaz over in Booty Bay said he'd have it shipped over, but it might be it slipped through the cracks somehow.$b$bIf that's true, there's not much we can do about it. We can at least find out if it was dispatched from Booty Bay.$b$bCheck in with Wharfmaster Lozgil over there, he should be able to check the cargo records.",logDesc="Speak with Wharfmaster Lozgil at Booty Bay in Stranglethorn Vale."} end
if not DB[1181] then DB[1181]={id=1181,zoneId=400,name="Goblin Sponsorship",level=37,minLevel=29,giver="Wharfmaster Lozgil",giverType="NPC",giverId=4631,ender="Baron Revilgaz",enderType="NPC",enderId=2496,rewardNextId=1182,poiX=-14298,poiY=540,wowhead="https://www.wowhead.com/wotlk/quest=1181",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I'm afraid I can't be of much more help to you, $n. If you'd like to follow up on it more, I'd suggest you go hit up the Baron himself. If there's anyone who knows Revilgaz's business, it's Revilgaz.$b$bYou'll find him at the tavern across the harbor, top floor.",logDesc="Speak with Baron Revilgaz in Booty Bay."} end
if not DB[1182] then DB[1182]={id=1182,zoneId=400,name="Goblin Sponsorship",level=37,minLevel=29,giver="Baron Revilgaz",giverType="NPC",giverId=2496,ender="Baron Revilgaz",enderType="NPC",enderId=2496,rewardNextId=1183,poiX=-14439,poiY=483,wowhead="https://www.wowhead.com/wotlk/quest=1182",image="assets/images/quests/placeholder.png",xpDiff=5,money=4000,desc="See, the Venture Company shredders out in Lake Nazferiti (in northern Stranglethorn) have been equipped with a new model fuel regulator. I was thinking that Pozzik would be able to take advantage of it, if he could get some details. Unfortunately, Cozzle, the foreman out there, appears to be a little more clever than I gave him credit for.$b$bYou seem like you might have more luck finding the blueprints though. I know he keeps them in his house, but they're almost certainly under lock and key.",logDesc="Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay."} end
if not DB[1183] then DB[1183]={id=1183,zoneId=400,name="Goblin Sponsorship",level=37,minLevel=29,giver="Baron Revilgaz",giverType="NPC",giverId=2496,ender="Pozzik",enderType="NPC",enderId=4630,rewardNextId=1186,poiX=-14439,poiY=483,wowhead="https://www.wowhead.com/wotlk/quest=1183",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You should be all set to go. Give Pozzik my regards and tell him that if he ever needs anything, not to hesitate to ask. I'll be waiting for the news that he breaks the track record soon!",logDesc="Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats."} end
if not DB[1184] then DB[1184]={id=1184,zoneId=400,name="Parts of the Swarm",level=35,minLevel=28,giver="Korran",giverType="NPC",giverId=3428,ender="Belgrom Rockmaul",enderType="NPC",enderId=4485,poiX=-389,poiY=-2552,wowhead="https://www.wowhead.com/wotlk/quest=1184",image="assets/images/quests/placeholder.png",xpDiff=3,money=1800,desc="Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly.",logDesc="Return to Belgrom Rockmaul in Orgrimmar.",choiceRewards={{id=6737,qty=1},{id=6738,qty=1}}} end
if not DB[1185] then DB[1185]={id=1185,zoneId=493,name="Under the Chitin Was...",level=57,minLevel=54,giver="Umber",giverType="NPC",giverId=11939,ender="Umber",enderType="NPC",enderId=11939,poiX=7944,poiY=-2417,wowhead="https://www.wowhead.com/wotlk/quest=1185",image="assets/images/quests/placeholder.png",xpDiff=3} end
if not DB[1186] then DB[1186]={id=1186,zoneId=400,name="The Eighteenth Pilot",level=37,minLevel=29,giver="Pozzik",giverType="NPC",giverId=4630,ender="Razzeric",enderType="NPC",enderId=4706,rewardNextId=1187,poiX=-6193,poiY=-3961,wowhead="https://www.wowhead.com/wotlk/quest=1186",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I'm going to be busy with working on integrating this new fuel regulator to our racer designs, but if you'd like to help out the team some more, talk to Razzeric. He's our pilot--well, our eighteenth pilot, to be exact--and he likes to add his own little modifications to the racers.$b$bHe's a little off his rocker, though, so try not to act too surprised.",logDesc="Speak with Razzeric on the Shimmering Flats in Thousand Needles."} end
if not DB[1187] then DB[1187]={id=1187,zoneId=400,name="Razzeric's Tweaking",level=41,minLevel=29,giver="Razzeric",giverType="NPC",giverId=4706,ender="Razzeric",enderType="NPC",enderId=4706,rewardNextId=1188,poiX=-6199,poiY=-3968,wowhead="https://www.wowhead.com/wotlk/quest=1187",image="assets/images/quests/placeholder.png",xpDiff=5,money=5500,desc="Pozzik's a great mechanic, I know that, but he's afraid to just load on the firepower and grab on for the ride. Not me, though.$b$bAfter Pozzik finishes with a racer, I take a little time to put my own modifications on--you know, loosening up the controls, removing parts of the frame, and adding more juice!$b$bI ordered a seaforium booster from Shreev at the Gizmorium in Gadgetzan, but apparently the zeppelin it was being sent on crashed in Dustwallow Marsh! I gotta have it, $n!",logDesc="Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats."} end
if not DB[1188] then DB[1188]={id=1188,zoneId=400,name="Safety First",level=41,minLevel=29,giver="Razzeric",giverType="NPC",giverId=4706,ender="Shreev",enderType="NPC",enderId=4708,rewardNextId=1189,poiX=-6199,poiY=-3968,wowhead="https://www.wowhead.com/wotlk/quest=1188",image="assets/images/quests/placeholder.png",xpDiff=2,desc="But wait, what's this? Shreev left the safety on. That will limit the amount of power I can draw from the booster at any time. I told him I wanted it off! This is no good.$b$bYou have to take this to the Gadgetzan Gizmorium in the Tanaris Desert and have Shreev remove this.",logDesc="Bring the Seaforium Booster to Shreev at Gadgetzan in Tanaris."} end
if not DB[1189] then DB[1189]={id=1189,zoneId=400,name="Safety First",level=41,minLevel=29,giver="Shreev",giverType="NPC",giverId=4708,ender="Razzeric",enderType="NPC",enderId=4706,poiX=-7128,poiY=-3735,wowhead="https://www.wowhead.com/wotlk/quest=1189",image="assets/images/quests/placeholder.png",xpDiff=2,desc="There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track.$b$bWould be a shame, too, if that happened. Who knows if our nineteenth driver would be any good?",logDesc="Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats in Thousand Needles.",choiceRewards={{id=6726,qty=1},{id=6727,qty=1}}} end
if not DB[1190] then DB[1190]={id=1190,zoneId=400,name="Keeping Pace",level=41,minLevel=29,giver="Pozzik",giverType="NPC",giverId=4630,rewardNextId=1194,poiX=-6193,poiY=-3961,wowhead="https://www.wowhead.com/wotlk/quest=1190",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The Brassbolts brothers have discovered a new building material, that's the only explanation that makes sense. Their cars have been operating faster than before, but their designs, and all the other data we've gathered from their runs is identical.$b$bWhat we do know, is that Rizzle Brassbolts has been focused on the plans for this new discovery almost constantly.$b$bZamek can create a diversion for you, so that you can steal those plans from them.",logDesc="Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats in Thousand Needles."} end
if not DB[1191] then DB[1191]={id=1191,zoneId=400,name="Zamek's Distraction",level=41,minLevel=29,giver="Zamek",giverType="NPC",giverId=4709,ender="Zamek",enderType="NPC",enderId=4709,poiX=-6226,poiY=-3945,wowhead="https://www.wowhead.com/wotlk/quest=1191",image="assets/images/quests/placeholder.png"} end
if not DB[1192] then DB[1192]={id=1192,zoneId=400,name="Indurium Ore",level=42,minLevel=29,giver="Pozzik",giverType="NPC",giverId=4630,ender="Pozzik",enderType="NPC",enderId=4630,poiX=-6193,poiY=-3961,wowhead="https://www.wowhead.com/wotlk/quest=1192",image="assets/images/quests/placeholder.png",money=600} end
if not DB[1193] then DB[1193]={id=1193,zoneId=2557,name="A Broken Trap",level=60,minLevel=56,wowhead="https://www.wowhead.com/wotlk/quest=1193",image="assets/images/quests/placeholder.png"} end
if not DB[1194] then DB[1194]={id=1194,zoneId=400,name="Rizzle's Schematics",level=41,minLevel=29,ender="Pozzik",enderType="NPC",enderId=4630,wowhead="https://www.wowhead.com/wotlk/quest=1194",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Rizzle's schematics describe the process of the refinement of indurium ore. From his scrawls, it is apparent that indurium ore is being obtained from the dwarven excavation site of Uldaman in the Badlands.$b$bMuch of the other notes relate to the heat resistant properties.$b$bUsed as a paperweight for the plans is a hunk of what appears to be unrefined indurium ore.",logDesc="Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats in Thousand Needles."} end
if not DB[1195] then DB[1195]={id=1195,zoneId=1638,name="The Sacred Flame",level=25,minLevel=20,giver="Zangen Stonehoof",giverType="NPC",giverId=4721,ender="Zangen Stonehoof",enderType="NPC",enderId=4721,rewardNextId=1196,poiX=-1208,poiY=-57,wowhead="https://www.wowhead.com/wotlk/quest=1195",image="assets/images/quests/placeholder.png",xpDiff=6,money=3500,desc="The Galak centaur in the Thousand Needles are protecting an artifact from the time of the centaurs' creation.$b$bWe would like to retrieve it, but we require a phial of water from one of the night elves' moonwells.$b$bTo collect the water, you will first need to obtain one of the phials carried by the dryads near the Raynewood Retreat in the heart of Ashenvale Forest. There is a moonwell near the western bank of the Falfarren River, south of the main road, where you can fill the phial.",logDesc="Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff."} end
if not DB[1196] then DB[1196]={id=1196,zoneId=1638,name="The Sacred Flame",level=29,minLevel=20,giver="Zangen Stonehoof",giverType="NPC",giverId=4721,ender="Rau Cliffrunner",enderType="NPC",enderId=4722,rewardNextId=1197,poiX=-1208,poiY=-57,wowhead="https://www.wowhead.com/wotlk/quest=1196",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Bring the filled phial to Rau Cliffrunner at the Freewind Post in southeastern Thousand Needles. You can get to the Thousand Needles by taking the Great Lift at the southern edge of the Barrens.$b$bI wouldn't be surprised if you can help us out further.",logDesc="Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post."} end
if not DB[1197] then DB[1197]={id=1197,zoneId=1638,name="The Sacred Flame",level=29,minLevel=20,giver="Rau Cliffrunner",giverType="NPC",giverId=4722,ender="Rau Cliffrunner",enderType="NPC",enderId=4722,poiX=-5484,poiY=-2463,wowhead="https://www.wowhead.com/wotlk/quest=1197",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it.$b$bYou will find Splithoof Crag, the centaurs' stronghold, to the north of here. The flame is kept in Splithoof Hold, a heavily guarded part of the crag.$b$bBe careful, though, the Galak centaur have great numbers here, and will be rather reluctant to surrender something so dear to them.",logDesc="Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.",choiceRewards={{id=6739,qty=1},{id=6740,qty=1}}} end
if not DB[1198] then DB[1198]={id=1198,zoneId=719,name="In Search of Thaelrid",level=24,minLevel=18,giver="Dawnwatcher Shaedlass",giverType="NPC",giverId=4786,ender="Argent Guard Thaelrid",enderType="NPC",enderId=4787,rewardNextId=1200,poiX=10062,poiY=2352,wowhead="https://www.wowhead.com/wotlk/quest=1198",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps on the coasts of Ashenvale.$b$bMy role here with the Argent Dawn is to collect as much information as I can, so we know when and where help is needed.$b$bIt has been weeks now since I sent a scout to check on the activity at Blackfathom Deeps. Argent Guard Thaelrid has not yet reported back.$b$bMy other scouts are preoccupied with pressing matters.$b$bSeek out and aid Thaelrid for me, $n.",logDesc="Seek out Argent Guard Thaelrid in Blackfathom Deeps."} end
if not DB[1199] then DB[1199]={id=1199,zoneId=719,name="Twilight Falls",level=25,minLevel=20,giver="Argent Guard Manados",giverType="NPC",giverId=4784,ender="Argent Guard Manados",enderType="NPC",enderId=4784,poiX=10069,poiY=2354,wowhead="https://www.wowhead.com/wotlk/quest=1199",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.$b$bWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps on the coast of Ashenvale.$b$bWhatever evil plan brews in the depths of the old temple must be thwarted.$b$bWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.",logDesc="Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.",rewards={{id=6998,qty=1},{id=7000,qty=1}}} end
if not DB[1200] then DB[1200]={id=1200,zoneId=719,name="Blackfathom Villainy",level=27,minLevel=18,giver="Argent Guard Thaelrid",giverType="NPC",giverId=4787,ender="Dawnwatcher Selgorm",enderType="NPC",enderId=4783,poiX=-532,poiY=319,wowhead="https://www.wowhead.com/wotlk/quest=1200",image="assets/images/quests/placeholder.png",xpDiff=7,money=6500,desc="Strength has left me. Your help is needed!$b$bLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.$b$bAku'Mai, servant of the Old God, rose from the waters.$b$bThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.$b$bSlay Kelris and bring his head to Selgorm in Darnassus, $N, please.",logDesc="Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.",choiceRewards={{id=7001,qty=1},{id=7002,qty=1}}} end
if not DB[1201] then DB[1201]={id=1201,zoneId=15,name="Theramore Spies",level=35,minLevel=30,giver="Nazeer Bloodpike",giverType="NPC",giverId=4791,ender="Nazeer Bloodpike",enderType="NPC",enderId=4791,rewardNextId=1202,poiX=-3106,poiY=-2824,wowhead="https://www.wowhead.com/wotlk/quest=1201",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Horde and Alliance hold an uneasy truce.  Outlying skirmishes and covert actions are taken by one side against the other, and it is our duty to ensure the Horde is on top!$B$BNow is the chance to do just that.$B$BAlliance infiltrators have taken positions east of Brackenwall Village.  They spy on the village and report our movements to Theramore, which we cannot allow.$B$BHunt down the infiltrators and slay them.  Send a clear message to their superiors that we will not tolerate their spies' presence!",logDesc="Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village."} end
if not DB[1202] then DB[1202]={id=1202,zoneId=15,name="The Theramore Docks",level=35,minLevel=30,giver="Nazeer Bloodpike",giverType="NPC",giverId=4791,ender="Nazeer Bloodpike",enderType="NPC",enderId=4791,poiX=-3106,poiY=-2824,wowhead="https://www.wowhead.com/wotlk/quest=1202",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N, two of our spies were sent to steal documents from a ship at the Theramore docks.  They gained the papers but were discovered, and were forced to throw the documents into the sea.$B$BOne spy later escaped, but was unable to recover the prize.  He reported his failure to me, and I now charge the task to you.$B$BThe documents are in a footlocker, in the waters somewhere beneath the Theramore docks.  Find those documents, $N, and bring them to me.",logDesc="Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village."} end
if not DB[1203] then DB[1203]={id=1203,zoneId=15,name="Jarl Needs a Blade",level=35,minLevel=30,giver="\"Swamp Eye\" Jarl",giverType="NPC",giverId=4792,ender="\"Swamp Eye\" Jarl",enderType="NPC",enderId=4792,poiX=-2953,poiY=-3885,wowhead="https://www.wowhead.com/wotlk/quest=1203",image="assets/images/quests/placeholder.png",xpDiff=6,money=3500,desc="I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...$B$BSome people call it a sword.  I call it a swing blade.$B$BYou help me?  Those fish-men, you know, murlocs or whatever they're called.... There's one they call Razorspine, carries a big sword, lives north of here near the beach. That's the sword I need!$B$BBut don't sleep on this.  What I'm cutting won't keep forever...",logDesc="Bring Razorspine's Sword to \"Swamp Eye\" Jarl at Swamplight Manor.",rewards={{id=9622,qty=1},{id=5016,qty=1}}} end
if not DB[1204] then DB[1204]={id=1204,zoneId=15,name="Mudrock Soup and Bugs",level=38,minLevel=33,giver="Morgan Stern",giverType="NPC",giverId=4794,ender="Morgan Stern",enderType="NPC",enderId=4794,rewardNextId=1258,poiX=-3625,poiY=-4458,wowhead="https://www.wowhead.com/wotlk/quest=1204",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'm working on a dish I call \"Mudrock Soup and Bugs.\"  I still need the major ingredients, and... well, I don't think I'd last long trudging through Dustwallow Marsh!$B$BSo, $N, can you do some hunting for me?  First, I need the tongues of Mudrock turtles.  You can find Mudrocks along the coast, mostly around the bay.$B$BBut I don't want just any tongues!  I hear that the tongues of some Mudrocks are forked...$B$BThey say the forked tongues have a distinct flavor, and I want that flavor in my dish...",logDesc="Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore."} end
if not DB[1205] then DB[1205]={id=1205,zoneId=15,name="Deadmire",level=41,minLevel=35,giver="Melor Stonehoof",giverType="NPC",giverId=3441,ender="Melor Stonehoof",enderType="NPC",enderId=3441,poiX=-1413,poiY=-126,wowhead="https://www.wowhead.com/wotlk/quest=1205",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Deadmire is an ancient crocolisk in Dustwallow marsh.  And it is his time to die.$B$BOld bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver.$B$BYet now he lives in constant, maddening pain.  You must end the life of this noble creature, $N.  You must lead Deadmire to peace.",logDesc="Bring Deadmire's Tooth to Melor in Thunder Bluff."} end
if not DB[1206] then DB[1206]={id=1206,zoneId=15,name="Jarl Needs Eyes",level=35,minLevel=30,giver="\"Swamp Eye\" Jarl",giverType="NPC",giverId=4792,ender="\"Swamp Eye\" Jarl",enderType="NPC",enderId=4792,rewardNextId=1203,poiX=-2953,poiY=-3885,wowhead="https://www.wowhead.com/wotlk/quest=1206",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Eye juice is good juice for drinking.  Too bad most critters only have two eyes.$B$BBut spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already.$B$BDarkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?",logDesc="Bring 20 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor."} end
if not DB[1218] then DB[1218]={id=1218,zoneId=15,name="Marsh Frog Legs",level=35,minLevel=30,giver="\"Swamp Eye\" Jarl",giverType="NPC",giverId=4792,ender="\"Swamp Eye\" Jarl",enderType="NPC",enderId=4792,rewardNextId=1206,poiX=-2953,poiY=-3885,wowhead="https://www.wowhead.com/wotlk/quest=1218",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I like cooking.  Good swamp cooking.  Fried green frog legs and the like.$B$BAnd I'm all out of legs. The manor is overrun with frogs, though. Giant marsh frogs. Think you could bring me some of those legs? Nothin' to it, really. Just bop 'em on the head and bring me the legs.$B$BThen I'll make a stew and stew it up and suck it down and give you some too.$B$BDo you like stew?",logDesc="Bring 10 Marsh Frog Legs to \"Swamp Eye\" Jarl in Dustwallow Marsh.",rewards={{id=6807,qty=20}}} end
if not DB[1219] then DB[1219]={id=1219,zoneId=15,name="The Orc Report",level=35,minLevel=30,ender="Lieutenant Aden",enderType="NPC",enderId=23951,rewardNextId=1220,wowhead="https://www.wowhead.com/wotlk/quest=1219",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.$B$BThe parchment is written in orcish... and it looks important.",logDesc="Bring the Spy's Report to Lieutenant Aden in Theramore."} end
if not DB[1220] then DB[1220]={id=1220,zoneId=15,name="Captain Vimes",level=35,minLevel=30,giver="Theramore Lieutenant",giverType="NPC",giverId=4947,ender="Captain Garran Vimes",enderType="NPC",enderId=4944,wowhead="https://www.wowhead.com/wotlk/quest=1220",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Captain Vimes should see the orc report you found, $N.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!$B$BThe captain is in the barracks, on the northeastern side of Theramore Isle.",logDesc="Bring the Spy's Report to Captain Garran Vimes."} end
if not DB[1221] then DB[1221]={id=1221,zoneId=1717,name="Blueleaf Tubers",level=26,minLevel=20,giver="Mebok Mizzyrix",giverType="NPC",giverId=3446,ender="Mebok Mizzyrix",enderType="NPC",enderId=3446,poiX=-929,poiY=-3697,wowhead="https://www.wowhead.com/wotlk/quest=1221",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.$B$BAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.$B$BIt won't be easy, but if you get me some tubers I'll pay you handsomely.",logDesc="Grab a Crate with Holes.$BGrab a Snufflenose Command Stick.$BGrab and read the Snufflenose Owner's Manual.$B$BIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.$B$BBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.",rewards={{id=6755,qty=1}}} end
if not DB[1222] then DB[1222]={id=1222,zoneId=15,name="Stinky's Escape",level=37,minLevel=30,giver="\"Stinky\" Ignatz",giverType="NPC",giverId=4880,ender="Morgan Stern",enderType="NPC",enderId=4794,poiX=-2646,poiY=-3436,wowhead="https://www.wowhead.com/wotlk/quest=1222",image="assets/images/quests/placeholder.png",xpDiff=5,money=4000,desc="Great, finally something that doesn't want to eat me!$B$BI need help handling the critters around here, and you fit the mold, $gbuddy:lady;.$B$BThe cook Morgan Stern is researching a new recipe, and he sent me out here to gather bogbean leaves.  I guess he thinks they're tasty.$B$BAnyway, while looking for a bogbean plant... I got myself surrounded!  Can you help me out of here, and watch my back as I look for the bogbean?",logDesc="Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.",rewards={{id=3825,qty=1}}} end
if not DB[1238] then DB[1238]={id=1238,zoneId=15,name="The Lost Report",level=35,minLevel=30,ender="Nazeer Bloodpike",enderType="NPC",enderId=4791,wowhead="https://www.wowhead.com/wotlk/quest=1238",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.$B$BThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.$B$BAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.",logDesc="Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village."} end
if not DB[1239] then DB[1239]={id=1239,zoneId=15,name="The Severed Head",level=35,minLevel=30,ender="Nazeer Bloodpike",enderType="NPC",enderId=4791,rewardNextId=1240,wowhead="https://www.wowhead.com/wotlk/quest=1239",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Vigorous digging reveals the head of a male orc, raggedly severed at the neck.  His lips are frozen in a snarl, and its dark eyes stare defiantly.",logDesc="Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village."} end
if not DB[1240] then DB[1240]={id=1240,zoneId=15,name="The Troll Witchdoctor",level=35,minLevel=30,giver="Nazeer Bloodpike",giverType="NPC",giverId=4791,ender="Kin'weelay",enderType="NPC",enderId=2519,poiX=-3106,poiY=-2824,wowhead="https://www.wowhead.com/wotlk/quest=1240",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We must know the events surrounding Marg's death!  And the only way to do that, $N, is through the witch-magic of trolls.$B$BBring Marg's head to Kin'weelay in Stranglethorn Vale, at the Grom'gol Base Camp.$B$BKin'weelay is the most powerful witchdoctor of the Darkspear trolls.  If anyone can speak to Marg Nighteye's spirit, it is he.",logDesc="Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale."} end
if not DB[1241] then DB[1241]={id=1241,zoneId=1519,name="The Missing Diplomat",level=28,minLevel=28,giver="Bishop DeLavey",giverType="NPC",giverId=4960,ender="Jorgen",enderType="NPC",enderId=4959,rewardNextId=1242,poiX=-8507,poiY=328,wowhead="https://www.wowhead.com/wotlk/quest=1241",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Recently a diplomat was sent to Theramore to meet with Jaina Proudmoore. That diplomat never arrived.$B$BI believe the Defias are involved in this plot, but I'm not sure how. The diplomat's disappearance still eludes public attention, but it can't remain that way for long.$B$BAgents of the king are already scouring the city for clues, but I have my own contacts I would like involved.$B$BIn the Valley of Heroes is an old friend of mine named Jorgen. Find him, give him this note, and follow his instructions.",logDesc="Find Jorgen in Stormwind City."} end
if not DB[1242] then DB[1242]={id=1242,zoneId=1519,name="The Missing Diplomat",level=28,minLevel=28,giver="Jorgen",giverType="NPC",giverId=4959,ender="Elling Trias",enderType="NPC",enderId=482,rewardNextId=1243,poiX=-8982,poiY=397,wowhead="https://www.wowhead.com/wotlk/quest=1242",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Take this here note to Elling Trias. Don't say nothin' else to him. Just be polite and wait for him to respond. And don't worry, he will.$B$BI'm gonna only impress this on ya once more, $N: treat this matter seriously, and keep your yapper shut.$B$BYa can find Trias at his cheese shop, Trias' Cheese, in the Trade District. Good luck.",logDesc="Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City."} end
if not DB[1243] then DB[1243]={id=1243,zoneId=1519,name="The Missing Diplomat",level=28,minLevel=28,giver="Elling Trias",giverType="NPC",giverId=482,ender="Watcher Backus",enderType="NPC",enderId=840,rewardNextId=1244,poiX=-8854,poiY=576,wowhead="https://www.wowhead.com/wotlk/quest=1243",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Jorgen, you ol' sonuva.... So, that's how it's going to be, huh?$B$BAll right, I can deal with that. I hope he finds the Twisting Nether that much sooner!$B$BHere's what's gonna happen, $N. I'll start using my contacts here, but you're doing most of the footwork so I save some coin.$B$BHead to Darkshire in Duskwood and find Watcher Backus--he usually patrols the north road right outside of town. Just tell him you're looking into any Defias activity for me and he'll help you out with any information he can.",logDesc="Give the Sealed Note to Watcher Backus in Duskwood."} end
if not DB[1244] then DB[1244]={id=1244,zoneId=1519,name="The Missing Diplomat",level=30,minLevel=28,giver="Watcher Backus",giverType="NPC",giverId=840,ender="Watcher Backus",enderType="NPC",enderId=840,rewardNextId=1245,poiX=-10320,poiY=-1126,wowhead="https://www.wowhead.com/wotlk/quest=1244",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Defias activity? Well, there's always some activity; even if they keep to themselves we consider them a threat.$B$BBut now that I think about it, there was a recent sighting that seemed odd. It must have been a couple weeks ago, but some of their agents had gathered around Addle's Stead. From the report, I'd guessed something big went down.$B$BWhy don't you check there first and bring me back anything you find?$B$BThe farmstead is south of the road from Westfall just as you enter Duskwood.",logDesc="Find the Defias Docket and return it to Watcher Backus in Duskwood."} end
if not DB[1245] then DB[1245]={id=1245,zoneId=1519,name="The Missing Diplomat",level=30,minLevel=28,giver="Watcher Backus",giverType="NPC",giverId=840,ender="Elling Trias",enderType="NPC",enderId=482,rewardNextId=1246,poiX=-10320,poiY=-1126,wowhead="https://www.wowhead.com/wotlk/quest=1245",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Whoa, this looks way too complex to be something to just lead you astray. I shouldn't even be looking at this stuff. Take it to Trias--he'll be able to make sense of it. And DON'T let anyone get in your way. This is bigger than me. It might even be bigger than him, but we'll see.$B$BAnd do me a favor, $N, don't tell anyone I helped you. If my superiors found out I knew about any of this and didn't share it with them they'd probably hang me.",logDesc="Bring the Defias Docket to Elling Trias in Stormwind."} end
if not DB[1246] then DB[1246]={id=1246,zoneId=1519,name="The Missing Diplomat",level=31,minLevel=28,giver="Elling Trias",giverType="NPC",giverId=482,ender="Dashel Stonefist",enderType="NPC",enderId=4961,rewardNextId=1447,poiX=-8854,poiY=576,wowhead="https://www.wowhead.com/wotlk/quest=1246",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Yeah, now that I think about it... Dashel... Dashel something... What was his name? FIST! Dashel Stonefist. They call him Fist in some circles--probably on account that he likes to get in brawls.$B$BYou can find him in Old Town usually--right smack dab in the center of it. Go talk to him. If you have to, use a sword or something heavy and blunt to persuade him to open up some. And don't hesitate. If he's in this as deep as these papers suggest, then he's not going to give you any information willingly.",logDesc="Speak to Dashel Stonefist in Stormwind."} end
if not DB[1247] then DB[1247]={id=1247,zoneId=1519,name="The Missing Diplomat",level=31,minLevel=28,giver="Dashel Stonefist",giverType="NPC",giverId=4961,ender="Elling Trias",enderType="NPC",enderId=482,rewardNextId=1248,poiX=-8681,poiY=433,wowhead="https://www.wowhead.com/wotlk/quest=1247",image="assets/images/quests/placeholder.png",xpDiff=1,desc="So yeah... um... I might know something 'bout that meeting at Addle's Stead. Happened a few weeks back I think. I really didn't have any part in it. Me part was done when plan A failed... damn adventurers.$B$BThe guy we got on the inside for plan B came out of Menethil; guy called Slim. That's all I know regarding their backup plan.",logDesc="Speak to Elling Trias in Stormwind."} end
if not DB[1248] then DB[1248]={id=1248,zoneId=1519,name="The Missing Diplomat",level=33,minLevel=28,giver="Elling Trias",giverType="NPC",giverId=482,ender="Mikhail",enderType="NPC",enderId=4963,rewardNextId=1249,poiX=-8854,poiY=576,wowhead="https://www.wowhead.com/wotlk/quest=1248",image="assets/images/quests/placeholder.png",xpDiff=2,desc="A contact of mine retired in the Wetlands at the harbor city of Menethil. He should be willing to help on your word alone if you tell him you're working for me. His name is Mikhail. He mentioned becoming a bartender before leaving Stormwind a few years ago.$B$BSpeak to him, find this Slim, and find out if there's anything else to know about this kidnapped diplomat. We need to find out where they've taken him, or at least who he is. The docket doesn't mention anything about their plans after he's captured.",logDesc="Speak to Mikhail in the Wetlands."} end
if not DB[1249] then DB[1249]={id=1249,zoneId=1519,name="The Missing Diplomat",level=33,minLevel=28,giver="Mikhail",giverType="NPC",giverId=4963,ender="Mikhail",enderType="NPC",enderId=4963,poiX=-3823,poiY=-828,wowhead="https://www.wowhead.com/wotlk/quest=1249",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You say Elling sent you here? Well then, the hospitality I expressed is now tenfold. Anything you need, just ask. I will do my best to aid you.$B$BHmm, Slim, you say? Not sure the name sounds familiar, but I'll keep my eyes out for him.$B$BDon't look now, $N, but the gentleman over by the exit is looking over here. He's listening to our conversation a little too intently if you catch my meaning? If I were you, I'd do what you can to subdue him before he makes a break for the door.",logDesc="Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil."} end
if not DB[1250] then DB[1250]={id=1250,zoneId=1519,name="The Missing Diplomat",level=33,minLevel=28,giver="Tapoke \"Slim\" Jahn",giverType="NPC",giverId=4962,ender="Mikhail",enderType="NPC",enderId=4963,rewardNextId=1264,poiX=-3809,poiY=-826,wowhead="https://www.wowhead.com/wotlk/quest=1250",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Defias didn't pay me well enough to die for their cause. They took the king. Yeah, the king of Stormwind, not some lowly diplomat. He was on his way to Theramore to meet with Jaina Proudmore--it was a big deal apparently, and a big secret. But it's not just the Defias that are involved. They're working with someone. I think they knew this was bigger than them.$B$BMy part was just to get their man on board the king's ship while it was in the harbor. The guy's name was Hendel. That's all I know. I swear!",logDesc="Speak to Mikhail in the Wetlands."} end
if not DB[1251] then DB[1251]={id=1251,zoneId=15,name="The Black Shield",level=35,minLevel=30,ender="Krog",enderType="NPC",enderId=4926,rewardNextId=1321,wowhead="https://www.wowhead.com/wotlk/quest=1251",image="assets/images/quests/placeholder.png",xpDiff=2,desc="An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.$b$bThe shield can be removed from the brick of the chimney.",logDesc="Bring the Blackened Iron Shield to Krog in Brackenwall Village."} end
if not DB[1252] then DB[1252]={id=1252,zoneId=15,name="Lieutenant Paval Reethe",level=35,minLevel=30,ender="Captain Garran Vimes",enderType="NPC",enderId=4944,rewardNextId=1259,wowhead="https://www.wowhead.com/wotlk/quest=1252",image="assets/images/quests/placeholder.png",xpDiff=2,desc="A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.$b$bUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".",logDesc="Bring Reethe's Badge to Captain Garran Vimes in Theramore."} end
if not DB[1253] then DB[1253]={id=1253,zoneId=15,name="The Black Shield",level=35,minLevel=30,ender="Captain Garran Vimes",enderType="NPC",enderId=4944,rewardNextId=1319,wowhead="https://www.wowhead.com/wotlk/quest=1253",image="assets/images/quests/placeholder.png",xpDiff=2,desc="An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.$b$bThe shield can be removed from the brick of the chimney.",logDesc="Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore."} end
if not DB[1258] then DB[1258]={id=1258,zoneId=15,name="... and Bugs",level=40,minLevel=33,giver="Morgan Stern",giverType="NPC",giverId=4794,ender="Morgan Stern",enderType="NPC",enderId=4794,poiX=-3625,poiY=-4458,wowhead="https://www.wowhead.com/wotlk/quest=1258",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Another component of my new recipe is the shelled leg of a giant crab.  And the crabs they have in Dustwallow -- Muckshells they call them -- just won't do!  I'm afraid the only suitable crabs live far away, in the Swamp of Sorrows.$B$BThe shell of the crab leg is a key element of the dish's presentation so I need pristine, unscarred legs.  An adult crab might only have one or two such legs, and I need a lot in order to research my dish.$B$BSo, $N... are you willing to travel?",logDesc="Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore.",rewards={{id=6801,qty=1}}} end
if not DB[1259] then DB[1259]={id=1259,zoneId=15,name="Lieutenant Paval Reethe",level=40,minLevel=30,giver="Captain Garran Vimes",giverType="NPC",giverId=4944,ender="Adjutant Tesoran",enderType="NPC",enderId=4948,rewardNextId=1285,poiX=-3735,poiY=-4556,wowhead="https://www.wowhead.com/wotlk/quest=1259",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.$b$bHe should be able to tell you who this Reethe is with a quick check of his books.",logDesc="Find out more about Reethe from Adjutant Tesoran in Theramore."} end
if not DB[1260] then DB[1260]={id=1260,zoneId=15,name="Morgan Stern",level=38,minLevel=33,giver="Angus Stern",giverType="NPC",giverId=1141,ender="Morgan Stern",enderType="NPC",enderId=4794,rewardNextId=1204,poiX=-9080,poiY=823,wowhead="https://www.wowhead.com/wotlk/quest=1260",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I'm developing a new menu for the restaurant.  It will be filled with rural dishes with a \"bayou\" theme.  I think my clientele at the Blue Recluse will love them!$B$BI sent my nephew Morgan to Theramore, a city on the edge of the Dustwallow Marsh.  He's there gathering recipes from the locals, and I must know what he found so far.$B$BThe trip to Theramore is long.  Too long for me.  But I bet a young $c like yourself would jump at the chance to travel, yes?",logDesc="Speak with Morgan Stern in Theramore."} end
if not DB[1261] then DB[1261]={id=1261,zoneId=15,name="Marg Speaks",level=40,minLevel=30,ender="Nazeer Bloodpike",enderType="NPC",enderId=4791,rewardNextId=1262,wowhead="https://www.wowhead.com/wotlk/quest=1261",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Cursed muckshell!  You can't kill Marg!  Ah, but I am dead.  So it must have slain me...$B$BBut my mission!  My mission!  You, $N, must complete it.$B$BWhile near Theramore, I spied a group of Alliance soldiers camped on the beach.  And one soldier wore a pendant... a pendant laden with more gems than any soldier could afford!$B$BThat night I snuck into their camp and stole the pendant, but on my return to base a muckshell crab-man killed me!$B$B$N, you must find that muckshell and recover the pendant!",logDesc="Bring the Jeweled Pendant to Nazeer in Brackenwall Village."} end
if not DB[1262] then DB[1262]={id=1262,zoneId=15,name="Report to Zor",level=40,minLevel=30,giver="Nazeer Bloodpike",giverType="NPC",giverId=4791,ender="Zor Lonetree",enderType="NPC",enderId=4047,poiX=-3106,poiY=-2824,wowhead="https://www.wowhead.com/wotlk/quest=1262",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is strange that the pendant Marg stole was in the hands of common soldiers.  Perhaps its owner was in disguise, or perhaps the soldiers themselves stole it!$B$BRegardless of which is true, this is a noble's pendant and we must discover its true owner if we are to unravel its mystery.$B$BTake the pendant to Zor Lonetree in Orgrimmar.  He is well schooled in Alliance politics, and will know if this pendant has a history among the nobles of Stormwind.",logDesc="Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar."} end
if not DB[1263] then DB[1263]={id=1263,zoneId=15,name="The Burning Inn <CHANGE TO GOSSIP>",level=35,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1263",image="assets/images/quests/placeholder.png"} end
if not DB[1264] then DB[1264]={id=1264,zoneId=1519,name="The Missing Diplomat",level=33,minLevel=28,giver="Mikhail",giverType="NPC",giverId=4963,ender="Commander Samaul",enderType="NPC",enderId=4964,rewardNextId=1265,poiX=-3823,poiY=-828,wowhead="https://www.wowhead.com/wotlk/quest=1264",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The beginning of every month the Kul Tiras Marines all get paid and usually leave Theramore for somewhere else. A lot of them come here to womanize, carouse, and just have a good time. One of those groups I'd consider regulars here at the tavern, and I believe this Hendel is among them.$B$BCommander Samaul in Theramore would be able to help you find him if Hendel's still stationed there. He's completely loyal to Proudmoore, but if you drop Elling's name, he should help you out... discreetly.",logDesc="Find Commander Samaul in Dustwallow Marsh."} end
if not DB[1265] then DB[1265]={id=1265,zoneId=1519,name="The Missing Diplomat",level=35,minLevel=28,giver="Commander Samaul",giverType="NPC",giverId=4964,ender="Archmage Tervosh",enderType="NPC",enderId=4967,rewardNextId=1266,poiX=-3738,poiY=-4546,wowhead="https://www.wowhead.com/wotlk/quest=1265",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hendel? Yes, I know the man. But why would you need one of my soldiers?$B$BElling sent you to find him? Hmm, I don't like the sound of that. Elling wouldn't have you come to me first if your business wasn't troubling. I understand if you can't tell me what this is about, but know this: I have a duty to protect these lands. If you're going to cause a disturbance, then I suggest you inform me of whatever you can.$B$BI believe Hendel was stationed at the first tower outside of Theramore. Be cautious.",logDesc="Search Sentry Point for any sign of Private Hendel."} end
if not DB[1266] then DB[1266]={id=1266,zoneId=1519,name="The Missing Diplomat",level=36,minLevel=28,giver="Archmage Tervosh",giverType="NPC",giverId=4967,ender="Private Hendel",enderType="NPC",enderId=4966,poiX=-3757,poiY=-4462,wowhead="https://www.wowhead.com/wotlk/quest=1266",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Private Hendel is to the west of here. He's currently on guard duty protecting some of Theramore's infiltrators while they rest. They've been keeping tabs on the Horde base, Brackenwall, and looking for anything else that might threaten our borders.$B$BYou should have no problem finding him; just look for the tents along the road.$B$BI have another matter to attend to, but I shall catch up to you soon enough. You can always find me in the Lady Proudmoore's tower if you have any problems.",logDesc="Find Private Hendel in Dustwallow Marsh."} end
if not DB[1267] then DB[1267]={id=1267,zoneId=1519,name="The Missing Diplomat",level=38,minLevel=28,giver="3",giverType="NPC",giverId=4968,ender="3",enderType="NPC",enderId=4968,poiX=-3750,poiY=-4454,wowhead="https://www.wowhead.com/wotlk/quest=1267",image="assets/images/quests/placeholder.png",xpDiff=7,money=13000,logDesc="Speak to Jaina Proudmore in Dustwallow Swamp.",rewards={{id=6757,qty=1}}} end
if not DB[1268] then DB[1268]={id=1268,zoneId=15,name="Suspicious Hoofprints",level=35,minLevel=30,ender="Krog",enderType="NPC",enderId=4926,wowhead="https://www.wowhead.com/wotlk/quest=1268",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.",logDesc="Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village."} end
if not DB[1269] then DB[1269]={id=1269,zoneId=15,name="Lieutenant Paval Reethe",level=37,minLevel=30,ender="Krog",enderType="NPC",enderId=4926,wowhead="https://www.wowhead.com/wotlk/quest=1269",image="assets/images/quests/placeholder.png",xpDiff=2,desc="A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.$b$bUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".",logDesc="Bring Reethe's Badge to Krog in Brackenwall Village."} end
if not DB[1270] then DB[1270]={id=1270,zoneId=15,name="Stinky's Escape",level=37,minLevel=30,giver="\"Stinky\" Ignatz",giverType="NPC",giverId=4880,ender="Mebok Mizzyrix",enderType="NPC",enderId=3446,poiX=-2646,poiY=-3436,wowhead="https://www.wowhead.com/wotlk/quest=1270",image="assets/images/quests/placeholder.png",xpDiff=5,money=4000,desc="Great, finally something that doesn't want to eat me!!$B$BI need help handling the critters around here, and you fit the mold, $gbuddy:lady;.$B$BA goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am.$B$BToo bad I got myself surrounded before I found the bogbean!  Can you help me out of here, and watch my back as I look for Mebok's plant?",logDesc="Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.",rewards={{id=3825,qty=1}}} end
if not DB[1271] then DB[1271]={id=1271,zoneId=15,name="Feast at the Blue Recluse",level=37,minLevel=30,giver="Angus Stern",giverType="NPC",giverId=1141,ender="Angus Stern",enderType="NPC",enderId=1141,poiX=-9080,poiY=823,wowhead="https://www.wowhead.com/wotlk/quest=1271",image="assets/images/quests/placeholder.png",rewards={{id=5951,qty=1}}} end
if not DB[1272] then DB[1272]={id=1272,zoneId=15,name="Finding Reethe <CHANGE INTO GOSSIP>",level=37,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1272",image="assets/images/quests/placeholder.png"} end
if not DB[1273] then DB[1273]={id=1273,zoneId=15,name="Questioning Reethe",level=37,minLevel=30,giver="Ogron",giverType="NPC",giverId=4983,ender="Krog",enderType="NPC",enderId=4926,poiX=-3318,poiY=-3125,wowhead="https://www.wowhead.com/wotlk/quest=1273",image="assets/images/quests/placeholder.png",xpDiff=6,desc="It took a long time, but I found Reethe. He hide good for a human.$b$bOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.",logDesc="Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.",choiceRewards={{id=6797,qty=1},{id=6798,qty=1}}} end
if not DB[1274] then DB[1274]={id=1274,zoneId=1519,name="The Missing Diplomat",level=28,minLevel=28,giver="Thomas",giverType="NPC",giverId=4982,ender="Bishop DeLavey",enderType="NPC",enderId=4960,rewardNextId=1241,poiX=-8511,poiY=860,wowhead="https://www.wowhead.com/wotlk/quest=1274",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excuse me, $g sir : madam;. Bishop DeLavey asked me to approach adventurers that might be able to help him with a delicate matter.$B$BIf you could quietly head to Stormwind Keep and speak to him at your earliest convenience, I'm sure he would appreciate your help. Again, please be discreet. It is a matter of some importance.",logDesc="Find Bishop DeLavey in Stormwind Keep."} end
if not DB[1275] then DB[1275]={id=1275,zoneId=719,name="Researching the Corruption",level=24,minLevel=18,giver="Gershala Nightwhisper",giverType="NPC",giverId=8997,ender="Gershala Nightwhisper",enderType="NPC",enderId=8997,poiX=6454,poiY=431,wowhead="https://www.wowhead.com/wotlk/quest=1275",image="assets/images/quests/placeholder.png",xpDiff=7,money=3500,desc="Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?$b$bI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.$b$bI wish to study the brain stems of the satyr and naga so that I might deduce what fate the elves are headed toward. In Blackfathom Deeps, on the coast of Ashenvale, you will find both satyr and naga.$b$b'Tis a long journey, $n.",logDesc="Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.",choiceRewards={{id=7003,qty=1},{id=7004,qty=1}}} end
if not DB[1276] then DB[1276]={id=1276,zoneId=15,name="The Black Shield",level=37,minLevel=30,giver="Krog",giverType="NPC",giverId=4926,ender="Mosarn",enderType="NPC",enderId=4943,poiX=-3149,poiY=-2887,wowhead="https://www.wowhead.com/wotlk/quest=1276",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.$b$bIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.$b$bPerhaps he can tell you more about the shield he crafted.$b$bIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.",logDesc="Show the Blackened Iron Shield to Mosarn in Thunder Bluff."} end
