if not DB[1282] then DB[1282]={id=1282,zoneId=15,name="They Call Him Smiling Jim",level=35,minLevel=30,giver="Guard Byron",giverType="NPC",giverId=4921,ender="Captain Garran Vimes",enderType="NPC",enderId=4944,rewardNextId=11123,poiX=-3646,poiY=-4448,wowhead="https://www.wowhead.com/wotlk/quest=1282",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place.$b$bLook, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to. He's stationed on the top floor of Foothold Citadel, the large barracks to the east of Lady Jaina's tower.",logDesc="Speak with Captain Garran Vimes on the top floor of Foothold Citadel."} end
