if not DB[1284] then DB[1284]={id=1284,zoneId=15,name="Suspicious Hoofprints",level=35,minLevel=30,ender="Captain Garran Vimes",enderType="NPC",enderId=4944,wowhead="https://www.wowhead.com/wotlk/quest=1284",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.",logDesc="Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore."} end
if not DB[1285] then DB[1285]={id=1285,zoneId=15,name="Daelin's Men",level=38,minLevel=30,giver="Adjutant Tesoran",giverType="NPC",giverId=4948,ender="Captain Garran Vimes",enderType="NPC",enderId=4944,rewardNextId=1286,poiX=-3717,poiY=-4547,wowhead="https://www.wowhead.com/wotlk/quest=1285",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.$b$bJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...$b$bListed as missing.",logDesc="Return the information about Reethe to Captain Garran Vimes in Theramore."} end
if not DB[1286] then DB[1286]={id=1286,zoneId=15,name="The Deserters",level=38,minLevel=30,giver="Captain Garran Vimes",giverType="NPC",giverId=4944,ender="Balos Jacken",enderType="NPC",enderId=5089,rewardNextId=1287,poiX=-3735,poiY=-4556,wowhead="https://www.wowhead.com/wotlk/quest=1286",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.$b$bThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.$b$bThe local lieutenant seems to be Balos Jacken. See if you can get some information out of him.$b$bBe warned, $n. He may be a tough nut to crack.",logDesc="Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh."} end
if not DB[1287] then DB[1287]={id=1287,zoneId=15,name="The Deserters",level=38,minLevel=30,giver="Balos Jacken",giverType="NPC",giverId=5089,ender="Captain Garran Vimes",enderType="NPC",enderId=4944,poiX=-3934,poiY=-2870,wowhead="https://www.wowhead.com/wotlk/quest=1287",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Reethe? That coward?$b$bWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.$b$bHe crossed the line one too many times, so we left him to fend for himself.$b$bNow, I helped you out... So, why don't you help us out and forget you bumped into us?",logDesc="Speak with Captain Garran Vimes in Theramore about Reethe."} end
if not DB[1288] then DB[1288]={id=1288,zoneId=15,name="Vimes's Report",level=38,minLevel=30,rewardNextId=1289,wowhead="https://www.wowhead.com/wotlk/quest=1288",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You've done some good work, $n, best I've seen from an amateur.$b$bLady Proudmoore asked that I keep her apprised of this delicate situation, and I haven't spoken to her for some time now.$b$bI was going to deliver my report to her later, but it seems more fitting that you should be the one to speak with her about it. You can probably answer her questions better than I could.",logDesc="Bring Vimes's Report to Lady Jaina Proudmoore in Theramore."} end
if not DB[1289] then DB[1289]={id=1289,zoneId=15,name="<nyi> Vimes's Report",level=38,minLevel=30,rewardNextId=1390,wowhead="https://www.wowhead.com/wotlk/quest=1289",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Well, judging from Captain Vimes's report, you've been a huge help to his investigation, and for that I thank you.$b$bI can put my mind more at ease knowing that the matter is in such capable hands. If you would, I would request that you return to Captain Vimes and help him in getting to the bottom of this mystery.",logDesc="Return to Captain Garran Vimes in Theramore."} end
