if not DB[1301] then DB[1301]={id=1301,zoneId=1519,name="James Hyal",level=35,minLevel=30,giver="Connor Rivers",giverType="NPC",giverId=5081,ender="Vincent Hyal",enderType="NPC",enderId=5082,rewardNextId=1302,poiX=-9102,poiY=835,wowhead="https://www.wowhead.com/wotlk/quest=1301",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.$b$bI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.$b$bIf you ever happen to be headed in that direction, maybe you could say hello to him for me?",logDesc="Speak with Vincent Hyal in Menethil Harbor."} end
if not DB[1302] then DB[1302]={id=1302,zoneId=11,name="James Hyal",level=35,minLevel=30,giver="Vincent Hyal",giverType="NPC",giverId=5082,ender="Clerk Lendry",enderType="NPC",enderId=5083,poiX=-3850,poiY=-736,wowhead="https://www.wowhead.com/wotlk/quest=1302",image="assets/images/quests/placeholder.png",xpDiff=2,desc="My brother James went with Lady Proudmoore across the sea. Last I heard, the fighting had settled down over there, and James was setting up an inn somewhere on the continent. Wherever he is, I'm sure he's doing good business. Damn fine cook he was.$b$bI haven't heard from him for a while now--too busy with his inn, I'd wager--but the clerk in Theramore could probably point you to him. Look for him on the top floor of that keep near the middle of the city. What's it called... Foothold Citadel, that's it.",logDesc="Speak with Clerk Lendry at Foothold Citadel in Theramore."} end
if not DB[1318] then DB[1318]={id=1318,zoneId=2557,name="Unfinished Gordok Business",level=60,minLevel=56,giver="3",giverType="NPC",giverId=14325,ender="3",enderType="NPC",enderId=14325,poiX=613,poiY=482,wowhead="https://www.wowhead.com/wotlk/quest=1318",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince!  Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king!$B$BArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever!  Yar, I show you!",logDesc="Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.$B$BAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.",choiceRewards={{id=18366,qty=1},{id=18367,qty=1},{id=18368,qty=1},{id=18369,qty=1}}} end
if not DB[1319] then DB[1319]={id=1319,zoneId=15,name="The Black Shield",level=35,minLevel=30,giver="Captain Garran Vimes",giverType="NPC",giverId=4944,ender="Caz Twosprocket",enderType="NPC",enderId=4941,rewardNextId=1320,poiX=-3735,poiY=-4556,wowhead="https://www.wowhead.com/wotlk/quest=1319",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I'm sorry I can't be of much help, $n, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.$b$bTake the shield to him, and see what he can tell you.",logDesc="Show the Blackened Iron Shield to Caz Twosprocket in Theramore."} end
if not DB[1320] then DB[1320]={id=1320,zoneId=15,name="The Black Shield",level=35,minLevel=30,giver="Caz Twosprocket",giverType="NPC",giverId=4941,ender="Captain Garran Vimes",enderType="NPC",enderId=4944,poiX=-3798,poiY=-4375,wowhead="https://www.wowhead.com/wotlk/quest=1320",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.$b$bThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.",logDesc="Speak with Captain Garran Vimes in Theramore."} end
if not DB[1321] then DB[1321]={id=1321,zoneId=15,name="The Black Shield",level=35,minLevel=30,giver="Krog",giverType="NPC",giverId=4926,ender="Do'gol",enderType="NPC",enderId=5087,rewardNextId=1322,poiX=-3149,poiY=-2887,wowhead="https://www.wowhead.com/wotlk/quest=1321",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...",logDesc="Show the Blackened Iron Shield to Do'gol in Brackenwall Village."} end
if not DB[1322] then DB[1322]={id=1322,zoneId=15,name="The Black Shield",level=37,minLevel=30,giver="Do'gol",giverType="NPC",giverId=5087,ender="Do'gol",enderType="NPC",enderId=5087,rewardNextId=1323,poiX=-3111,poiY=-2893,wowhead="https://www.wowhead.com/wotlk/quest=1322",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.$b$bI need acid to make it clear. Venom from the darkmist spiders would do good. The spiders have taken over an old mine, the Darkmist Cavern, northwest of the village. Get me some of their sacs and I can clean this up.",logDesc="Acquire 5 Acidic Venom Sacs for Do'gol in Brackenwall Village."} end
if not DB[1323] then DB[1323]={id=1323,zoneId=15,name="The Black Shield",level=37,minLevel=30,giver="Do'gol",giverType="NPC",giverId=5087,ender="Krog",enderType="NPC",enderId=4926,poiX=-3111,poiY=-2893,wowhead="https://www.wowhead.com/wotlk/quest=1323",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...$b$bHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.",logDesc="Talk with Krog in Brackenwall Village."} end
if not DB[1324] then DB[1324]={id=1324,zoneId=1519,name="The Missing Diplomat",level=38,minLevel=28,giver="Private Hendel",giverType="NPC",giverId=4966,ender="Archmage Tervosh",enderType="NPC",enderId=4967,poiX=-2895,poiY=-3351,wowhead="https://www.wowhead.com/wotlk/quest=1324",image="assets/images/quests/placeholder.png",xpDiff=4,desc="What?! You come here accusing me of allying with the Defias, and think I'll just stand here while you insult me?! Something tells me you've had this coming for a long time.",logDesc="Defeat Private Hendel in Dustwallow Marsh."} end
if not DB[1338] then DB[1338]={id=1338,zoneId=38,name="Stormpike's Order",level=14,minLevel=9,giver="Mountaineer Stormpike",giverType="NPC",giverId=1343,ender="Furen Longbeard",enderType="NPC",enderId=5413,poiX=-4826,poiY=-2677,wowhead="https://www.wowhead.com/wotlk/quest=1338",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="There is a dwarven armorsmith whose work I admire greatly.  His name is Furen Longbeard, and his skill is unmatched.  I need a new shield, and I must have one of his!$B$BThe problem is... Furen is far to the south, in the dwarven district within Stormwind.  In human lands!  I can't imagine why he would live there, so far from Ironforge.  The humans must pay him a king's ransom to keep him there!$B$BSo, if you want to travel and don't mind making some money, then will you send Furen my request for a shield?",logDesc="Bring Stormpike's Request to Furen Longbeard in Stormwind."} end
if not DB[1339] then DB[1339]={id=1339,zoneId=38,name="Mountaineer Stormpike's Task",level=15,minLevel=9,giver="Mountaineer Kadrell",giverType="NPC",giverId=1340,ender="Mountaineer Stormpike",enderType="NPC",enderId=1343,rewardNextId=1338,poiX=-5365,poiY=-2939,wowhead="https://www.wowhead.com/wotlk/quest=1339",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I hear Mountaineer Stormpike is looking for a runner.  Someone to do a little traveling for him.  How about it?  Are you the $r for the job?$B$BIf so, then you'll find Stormpike at the top of the northern guard tower.",logDesc="Speak with Mountaineer Stormpike."} end
if not DB[1358] then DB[1358]={id=1358,zoneId=1497,name="Sample for Helbrim",level=15,minLevel=10,giver="Apothecary Zinge",giverType="NPC",giverId=5204,ender="Apothecary Helbrim",enderType="NPC",enderId=3390,poiX=1443,poiY=392,wowhead="https://www.wowhead.com/wotlk/quest=1358",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor.  He would be very interested in a sample of the wolf hearts Renferrel sent me.$B$BHelbrim is stationed in the Barrens, in a village known as the Crossroads.  To reach him, you must travel via zeppelin to the orc capital of Orgrimmar, then travel south, by foot, to Durotar.  Head west into the Barrens, and you will soon reach the Crossroads.",logDesc="Bring the Wolf Heart Sample to Apothecary Helbrim in the Barrens.",choiceRewards={{id=10637,qty=1},{id=10638,qty=1}}} end
if not DB[1359] then DB[1359]={id=1359,zoneId=1497,name="Zinge's Delivery",level=15,minLevel=10,giver="Apothecary Renferrel",giverType="NPC",giverId=1937,ender="Apothecary Zinge",enderType="NPC",enderId=5204,rewardNextId=1358,poiX=522,poiY=1652,wowhead="https://www.wowhead.com/wotlk/quest=1359",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The wolf hearts you acquired possess a quality unseen in similar specimens.  There is a toxicity to them that should be deadly to the very wolves in which the hearts beat!$B$BIt's quite incredible, and we must study it further.  I kept a few samples of the hearts acquired.  Take them to my colleague, Apothecary Zinge.  You will find her in our headquarters in the Undercity.",logDesc="Bring the Wolf Heart Samples to Apothecary Zinge in the Undercity."} end
if not DB[1360] then DB[1360]={id=1360,zoneId=1517,name="Reclaimed Treasures",level=43,minLevel=33,giver="Krom Stoutarm",giverType="NPC",giverId=6294,ender="Krom Stoutarm",enderType="NPC",enderId=6294,poiX=-4619,poiY=-1300,wowhead="https://www.wowhead.com/wotlk/quest=1360",image="assets/images/quests/placeholder.png",xpDiff=5,money=6000,desc="I had myself a fine job as a digger at the Uldaman excavation site in the Badlands... that is until those blasted troggs showed up.  I escaped with my hide barely intact, and nothing else.  In the chaos, I left my most treasured possession.  It's safe from the troggs in my chest, sure, but it's right in the thick of 'em.$B$BI'd be in your debt, both in honor and coin, if you could fetch it for me!  A chest with my name on it is at the end of the North Common Hall.  That's the one you need to get in.",logDesc="Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge."} end
if not DB[1361] then DB[1361]={id=1361,zoneId=405,name="Regthar Deathgate",level=32,minLevel=30,giver="Krusk",giverType="NPC",giverId=2229,ender="Regthar Deathgate",enderType="NPC",enderId=3389,rewardNextId=1362,poiX=-41,poiY=-957,wowhead="https://www.wowhead.com/wotlk/quest=1361",image="assets/images/quests/placeholder.png",xpDiff=2,desc="A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads.$B$BAnd sharpen your weapons.  Desolace is a place torn by war.",logDesc="Speak with Regthar Deathgate in the Barrens."} end
if not DB[1362] then DB[1362]={id=1362,zoneId=405,name="The Kolkar of Desolace",level=32,minLevel=30,giver="Regthar Deathgate",giverType="NPC",giverId=3389,ender="Felgur Twocuts",enderType="NPC",enderId=5395,poiX=-307,poiY=-1972,wowhead="https://www.wowhead.com/wotlk/quest=1362",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The Kolkar centaur live in Desolace, and their forces have spread into the Barrens.  This is a known fact and we have Horde agents dealing with them here.$B$BBut as long as the centaur are strong in Desolace, they will always pose a threat.  It is time we rid ourselves of that threat.$B$BSpeak with Felgur Twocuts at Ghost Walker Post in Desolace.  He was sent to gather intelligence on the centaur.  He will know how to best deal with the Kolkar of Desolace.",logDesc="Speak with Felgur Twocuts at Ghost Walker Post in Desolace."} end
if not DB[1363] then DB[1363]={id=1363,zoneId=1519,name="Mazen's Behest",level=41,minLevel=37,giver="Mazen Mac'Nadir",giverType="NPC",giverId=338,ender="Acolyte Dellis",enderType="NPC",enderId=5386,rewardNextId=1364,poiX=-8856,poiY=823,wowhead="https://www.wowhead.com/wotlk/quest=1363",image="assets/images/quests/placeholder.png",xpDiff=1,desc="As caretaker of the works here in the library of the Academy of Arcane Arts and Sciences, it is my responsibility to ensure all the magical tomes and scrolls are accounted for at all times. Who knows what folly would unfold if some of these enchanted texts were to fall into the wrong hands?$b$bWhich reminds me... my assistant, Dellis, made a horrible mistake last week. He's quite able in the library but incompetent when he leaves the gates of Stormwind. Be a hero, and help old Dellis out, would you?",logDesc="Speak with Acolyte Dellis in Stormwind."} end
if not DB[1364] then DB[1364]={id=1364,zoneId=1519,name="Mazen's Behest",level=41,minLevel=37,giver="Acolyte Dellis",giverType="NPC",giverId=5386,ender="Watcher Mahar Ba",enderType="NPC",enderId=5385,poiX=-8851,poiY=830,wowhead="https://www.wowhead.com/wotlk/quest=1364",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep.$b$bBut I had never been to the Blasted Lands before! The journey was frightening!$b$bWhen I got to the Swamp of Sorrows, I made a wrong turn and ended up surrounded by horrible plant-like swamp creatures. They lurched as if to attack me so I ran. But in my haste I dropped the essay. One of the beasts took it I am sure.$b$bCould you please try to retrieve it and deliver it to Mahar Ba?",logDesc="Retrieve Khadgar's Essays on Dimensional Convergence and deliver them to Watcher Mahar Ba in Nethergarde Keep.",choiceRewards={{id=10747,qty=1},{id=10748,qty=1}}} end
if not DB[1365] then DB[1365]={id=1365,zoneId=405,name="Khan Dez'hepah",level=35,minLevel=30,giver="Felgur Twocuts",giverType="NPC",giverId=5395,ender="Felgur Twocuts",enderType="NPC",enderId=5395,poiX=-1334,poiY=1707,wowhead="https://www.wowhead.com/wotlk/quest=1365",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The Kolkar are not the only centaur of Desolace.  Many clans wander these dry plains, fighting and dying against each other.  And it is good that they fight among themselves, for they are strong and brutal.  If the centaur united against us, they would be a fierce foe.$B$BWe must deal with them before they unite.$B$BYour first task is to disrupt the Kolkar clan.  Do this by killing its leader, Khan Dez'hepah.$B$BThe Kolkar Village is northeast of here.  Go, and may fortune go with you.",logDesc="Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace."} end
if not DB[1366] then DB[1366]={id=1366,zoneId=405,name="Centaur Bounty",level=31,minLevel=30,giver="Felgur Twocuts",giverType="NPC",giverId=5395,ender="Felgur Twocuts",enderType="NPC",enderId=5395,poiX=-1334,poiY=1707,wowhead="https://www.wowhead.com/wotlk/quest=1366",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Now that you scared the centaur clans, it's time to bleed them.  When traveling Desolace, hunt centaur.  I don't care which clan you hunt.  Just gather ears.  A hoard of ears.$B$BBy weakening their numbers you will weaken their resolve, and stamp out any thoughts of expansion.$B$BGood hunting, $N.",logDesc="Bring 15 Centaur Ears to Felgur Twocuts in Desolace.",choiceRewards={{id=6780,qty=1},{id=6784,qty=1}}} end
if not DB[1367] then DB[1367]={id=1367,zoneId=405,name="Magram Alliance",level=33,minLevel=30,giver="Gurda Wildmane",giverType="NPC",giverId=5412,ender="Warug",enderType="NPC",enderId=5398,rewardNextId=1369,poiX=-1337,poiY=1703,wowhead="https://www.wowhead.com/wotlk/quest=1367",image="assets/images/quests/placeholder.png",xpDiff=2,desc="To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.$B$BIf you choose to ally with the Magram then slay their foes, the Gelkis.  This will earn you respect among the Magram.  When you earn enough, then meet with the Magram spokesman Warug, on the outskirts of the Magram Village, in southeast Desolace.",logDesc="Gain a Friendly reputation with the Magram, then speak with Warug."} end
if not DB[1368] then DB[1368]={id=1368,zoneId=405,name="Gelkis Alliance",level=33,minLevel=30,giver="Gurda Wildmane",giverType="NPC",giverId=5412,ender="Uthek the Wise",enderType="NPC",enderId=5397,rewardNextId=1370,poiX=-1337,poiY=1703,wowhead="https://www.wowhead.com/wotlk/quest=1368",image="assets/images/quests/placeholder.png",xpDiff=2,desc="To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.$B$BIf you choose to ally with the Gelkis then slay their most hated rival, the Magram.  After you earn the respect of the Gelkis, meet with the Gelkis shaman Uthek the Wise, on the outskirts of the Gelkis Village, in southwest Desolace.",logDesc="Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise."} end
if not DB[1369] then DB[1369]={id=1369,zoneId=405,name="Broken Tears",level=33,minLevel=30,giver="Warug",giverType="NPC",giverId=5398,ender="Warug",enderType="NPC",enderId=5398,rewardNextId=1371,poiX=-1591,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1369",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Gelkis think our centaur mother, Theradras, protects us.  They are stupid.  No one protects the centaur.  The Magram do not need protection!  We are the strongest!$B$BShow the Gelkis they are stupid.  Go to the cave in their village.  They hoard crystals in that cave, the tears of Theradras.  Destroy the tears and bring me the broken pieces!",logDesc="Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village."} end
if not DB[1370] then DB[1370]={id=1370,zoneId=405,name="Stealing Supplies",level=35,minLevel=30,giver="Uthek the Wise",giverType="NPC",giverId=5397,ender="Uthek the Wise",enderType="NPC",enderId=5397,rewardNextId=1373,poiX=-1924,poiY=2605,wowhead="https://www.wowhead.com/wotlk/quest=1370",image="assets/images/quests/placeholder.png",xpDiff=3,desc="When we are not at war, we hunt for meat.  Meat gives us strength, and full bellies fight harder than empty ones.$B$BIt is the same with the Magram.  They store extra meat so they may fight longer between hunts.  If you raid their village to the east and take their stores of meat, then their strength will fail.",logDesc="Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village.",choiceRewards={{id=32378,qty=1},{id=3464,qty=200},{id=3465,qty=200}}} end
if not DB[1371] then DB[1371]={id=1371,zoneId=405,name="Gizmo for Warug",level=35,minLevel=30,giver="Warug",giverType="NPC",giverId=5398,ender="Warug",enderType="NPC",enderId=5398,poiX=-1591,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1371",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Long ago, a little gnome came to Desolace.  He had horses and a cart, and the cart held strange things.  Funny things.  Things that burned different colors.  Things that moved and weren't alive.  I killed the little gnome, but before that... he made me laugh.$B$BI kept my favorite thing from his cart.  It was a human made of wood and it waved at me until I hit it and broke it.$B$BI want a new one.  Get me a new one!",logDesc="Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace."} end
if not DB[1372] then DB[1372]={id=1372,zoneId=10,name="Nothing But The Truth",level=42,minLevel=37,giver="Deathstalker Zraedus",giverType="NPC",giverId=5418,ender="Apothecary Faustin",enderType="NPC",enderId=5414,rewardNextId=1383,poiX=-10358,poiY=-1538,wowhead="https://www.wowhead.com/wotlk/quest=1372",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Our expeditionary force was sent at Varimathras's behest to survey lower Azeroth.$b$bWhile out scouting I noticed a human Infiltrator spying on Beggar's Haunt. Before I could apprehend him, some of our orcish... brethren... captured him and took him to Stonard, their stronghold in Swamp of Sorrows.$b$bI want to... help... our orcish allies. They did not see our camp here but nonetheless I want to lend a hand.$b$bWork with Faustin here to develop a... truth serum for our friend in Stonard.",logDesc="Speak with Apothecary Faustin at Beggar's Haunt."} end
if not DB[1373] then DB[1373]={id=1373,zoneId=405,name="Ongeku",level=37,minLevel=30,giver="Uthek the Wise",giverType="NPC",giverId=5397,ender="Uthek the Wise",enderType="NPC",enderId=5397,rewardNextId=1374,poiX=-1924,poiY=2605,wowhead="https://www.wowhead.com/wotlk/quest=1373",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have more to prove, and your next task will take you far, so for now the Gelkis will fight the Magram without you.$B$BThe earth whispers many secrets to those who listen.  One secret I hear is of a red crystal.  It is called draenethyst, and it is new to our earth.  It comes from a place where mountains fly, and where demons rule.$B$BBring me a shard of draenethyst, and it will make my magic strong!  The shard is in a place called the Swamp of Sorrows, held by the lost one Ongeku.",logDesc="Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace."} end
if not DB[1374] then DB[1374]={id=1374,zoneId=405,name="Khan Jehn",level=37,minLevel=30,giver="Uthek the Wise",giverType="NPC",giverId=5397,ender="Uthek the Wise",enderType="NPC",enderId=5397,rewardNextId=1380,poiX=-1924,poiY=2605,wowhead="https://www.wowhead.com/wotlk/quest=1374",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The earth speaks to me, and it says that the Magram grow weak.  Now it is time to kill their Khan!$B$BBring me the head of the Magram Khan, Jehn!",logDesc="Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace."} end
if not DB[1375] then DB[1375]={id=1375,zoneId=405,name="Khan Shaka",level=37,minLevel=30,giver="Warug",giverType="NPC",giverId=5398,ender="Warug",enderType="NPC",enderId=5398,rewardNextId=1381,poiX=-1591,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1375",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You help the Magram, and I like you.  Now, kill the Khan of the Gelkis!  He is Khan Shaka, and I want his head!  I want to stare at his head and laugh at him!",logDesc="Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace."} end
if not DB[1380] then DB[1380]={id=1380,zoneId=405,name="Khan Hratha",level=42,minLevel=30,giver="Uthek the Wise",giverType="NPC",giverId=5397,ender="Uthek the Wise",enderType="NPC",enderId=5397,poiX=-1924,poiY=2605,wowhead="https://www.wowhead.com/wotlk/quest=1380",image="assets/images/quests/placeholder.png",xpDiff=6,desc="$N, you helped us against the Magram.  Now, help us beat the Maraudine!  Kill the head of their clan, Khan Hratha!$B$BTo face him, blow the Maraudine War Horn.  It is atop a high bluff in the Valley of Spears.$B$BBut to blow the horn, you must gain a warhorn mouthpiece.  These are rare, carried only by trusted Maraudine centaur.$B$BAfter the horn is blown, centaur will come.  Kill them until Hratha appears.$B$BKhan Hratha holds the piece of... a key.  Bring it to me...",logDesc="Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village.",choiceRewards={{id=6773,qty=1},{id=6774,qty=1}}} end
if not DB[1381] then DB[1381]={id=1381,zoneId=405,name="Khan Hratha",level=42,minLevel=30,giver="Warug",giverType="NPC",giverId=5398,ender="Warug",enderType="NPC",enderId=5398,poiX=-1591,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1381",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The Gelkis Khan is dead, and now the Maraudine will fall!  Kill the Maraudine Khan, Hratha!$B$BTo face him, blow the horn on the high bluff in the Valley of Spears.  But to blow the horn, you need a mouthpiece.  To get a mouthpiece, kill Maraudine centaur.  Keep killing until you find a mouthpiece.  Then blow the horn.$B$BDo this and Maraudine centaur will come to the tower.  Kill them until Khan Hratha appears.  Hratha holds the piece of a key.  Give this piece to me...",logDesc="Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace.",choiceRewards={{id=6788,qty=1},{id=6789,qty=1}}} end
if not DB[1382] then DB[1382]={id=1382,zoneId=405,name="Strange Alliance",level=35,minLevel=30,giver="Captain Pentigast",giverType="NPC",giverId=5396,ender="Uthek the Wise",enderType="NPC",enderId=5397,rewardNextId=1384,poiX=124,poiY=1236,wowhead="https://www.wowhead.com/wotlk/quest=1382",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We are fortunate the centaur clans fight among themselves, for if they joined into a single force then they would be unstoppable.  Yes, we are fortunate, and we should press our advantage.$B$BOne of the centaur clans, the Gelkis clan, is in brutal war with the Magram clan.  If we attack the Magram, then perhaps an alliance may be struck with the Gelkis.$B$BSpeak with Uthek the Wise, in the outskirts of the Gelkis camps in southwestern Desolace.  Through her we might strike an alliance with the Gelkis.",logDesc="Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise."} end
if not DB[1383] then DB[1383]={id=1383,zoneId=10,name="Nothing But The Truth",level=42,minLevel=37,giver="Apothecary Faustin",giverType="NPC",giverId=5414,ender="Apothecary Faustin",enderType="NPC",enderId=5414,poiX=-10351,poiY=-1528,wowhead="https://www.wowhead.com/wotlk/quest=1383",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I have just the right serum in mind. It will deal with the truth in precisely the way the truth should be dealt with.$b$bFor this concoction I will need several Shadow Panther hearts from the Swamp. I also require the enchanted fungus off of the Mire Lord who resides there. I am sure one as able as you, $n, can persuade him to part with some.$b$bThe last item I'll need for the serum is the blood of a dreaming whelp, like the ones that live outside Itharius' cave in the swamp.$b$bNow, off you go!",logDesc="Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and some Green Whelp Blood.",choiceRewards={{id=6832,qty=1},{id=11265,qty=1}}} end
if not DB[1384] then DB[1384]={id=1384,zoneId=405,name="Raid on the Kolkar",level=32,minLevel=30,giver="Uthek the Wise",giverType="NPC",giverId=5397,ender="Uthek the Wise",enderType="NPC",enderId=5397,rewardNextId=1370,poiX=-1924,poiY=2605,wowhead="https://www.wowhead.com/wotlk/quest=1384",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Kolkar centaurs think their magic is strong.  They do not know magic!  They would not know magic if it bit them!$B$BYou will show them their magic is weak.  Go to the Kolkar  to the northeast and kill them.  Take their charms.  Bring me the charms and I will throw them in the fire and laugh!",logDesc="Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace."} end
if not DB[1385] then DB[1385]={id=1385,zoneId=405,name="Brutal Politics",level=35,minLevel=30,giver="Captain Pentigast",giverType="NPC",giverId=5396,ender="Warug",enderType="NPC",enderId=5398,rewardNextId=1386,poiX=124,poiY=1236,wowhead="https://www.wowhead.com/wotlk/quest=1385",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Desolace is a land at war.  The centaurs wage war with each other, and we believe the victor among them will spill out and threaten our strongholds.  That, we cannot allow$B$BWe must learn how to beat the centaurs, and to do that... we must ally with one of the clans.  The Magram centaurs war with the Gelkis.  If you fight the Gelkis then the Magram might consider an alliance.$B$BEarn the favor of the Magrams then speak with Warug, in the Magram village in southeastern Desolace.",logDesc="Gain a Friendly reputation with the Magram, then speak with Warug."} end
if not DB[1386] then DB[1386]={id=1386,zoneId=405,name="Assault on the Kolkar",level=32,minLevel=30,giver="Warug",giverType="NPC",giverId=5398,ender="Warug",enderType="NPC",enderId=5398,rewardNextId=1369,poiX=-1591,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1386",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Kolkar think they are strong, but we laugh at them!  We laugh and we kill them!  You kill them too.  Show me you can kill Kolkar like we do. Head north and slay them all!",logDesc="Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace."} end
if not DB[1387] then DB[1387]={id=1387,zoneId=405,name="Centaur Bounty",level=31,minLevel=30,giver="Corporal Melkins",giverType="NPC",giverId=5752,ender="Corporal Melkins",enderType="NPC",enderId=5752,poiX=126,poiY=1233,wowhead="https://www.wowhead.com/wotlk/quest=1387",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Many clans make up the centaur race.  Each has its own leader and agenda, but all the clans have one thing in common.  Cruelty.$B$BIf we are to ever find peace, then the centaurs must be removed.  And so I put you on the task to do just that.$B$BWhile wandering Desolace, hunt centaur and take their ears.  Bring me many, many ears.$B$BDo this in service of the Alliance, $N, and we will be one step closer to war's end.",logDesc="Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace.",rewards={{id=6790,qty=1}}} end
if not DB[1388] then DB[1388]={id=1388,zoneId=10,name="Nothing But The Truth",level=42,minLevel=37,giver="Apothecary Faustin",giverType="NPC",giverId=5414,ender="Deathstalker Zraedus",enderType="NPC",enderId=5418,rewardNextId=1391,poiX=-10351,poiY=-1528,wowhead="https://www.wowhead.com/wotlk/quest=1388",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Everything is proceeding according to plan, $n. I want you to give this truth serum to Deathstalker Zraedus and he'll show you how to administer it.... properly.$b$bHaha!",logDesc="Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt."} end
if not DB[1389] then DB[1389]={id=1389,zoneId=8,name="Draenethyst Crystals",level=35,minLevel=30,giver="Magtoor",giverType="NPC",giverId=1776,ender="Magtoor",enderType="NPC",enderId=1776,poiX=-10101,poiY=-2819,wowhead="https://www.wowhead.com/wotlk/quest=1389",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the east, catching or killing any who wander near.$B$BAnd they have stolen something sacred to us--draenethyst crystals.$B$BWe lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.",logDesc="Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows."} end
if not DB[1390] then DB[1390]={id=1390,zoneId=15,name="<nyi> Oops, We Killed Them Again.",level=1,minLevel=1,rewardNextId=1397,wowhead="https://www.wowhead.com/wotlk/quest=1390",image="assets/images/quests/placeholder.png",xpDiff=5} end
if not DB[1391] then DB[1391]={id=1391,zoneId=10,name="Nothing But The Truth",level=42,minLevel=37,giver="Deathstalker Zraedus",giverType="NPC",giverId=5418,ender="Infiltrator Marksen",enderType="NPC",enderId=5416,poiX=-10358,poiY=-1538,wowhead="https://www.wowhead.com/wotlk/quest=1391",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We need to operate with a certain amount of discretion. After all, it's not like you're going to waltz in there and convince the fool to drink Faustin's concoction here, right?$b$bBut if there's one thing those humans cannot deny it's the booze. I'll take Faustin's serum and mix it into this ale. I guarantee the poor sap will show no reluctance when it comes to chug-a-lugging a brew.$b$bMake haste to Stonard in the Swamp of Sorrows, $n. And keep our little mission nice and quiet...",logDesc="Take Zraedus's Brew to Infiltrator Marksen in Stonard."} end
if not DB[1392] then DB[1392]={id=1392,zoneId=8,name="Noboru the Cudgel",level=39,minLevel=29,ender="Magtoor",enderType="NPC",enderId=1776,wowhead="https://www.wowhead.com/wotlk/quest=1392",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Noboru has plagued the Draenei of the Harborage for months, and his cudgel is a symbol of the brutality they have suffered at the hands of the lost ones.",logDesc="Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows."} end
if not DB[1393] then DB[1393]={id=1393,zoneId=8,name="Galen's Escape",level=38,minLevel=30,giver="Galen Goodward",giverType="NPC",giverId=5391,poiX=-9899,poiY=-3725,wowhead="https://www.wowhead.com/wotlk/quest=1393",image="assets/images/quests/placeholder.png",xpDiff=5,money=8500,desc="Please help!  These creatures are going to eat me!$B$BHelp me out of here, and I'll give you a great treasure!  It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know.$B$BIf you help me escape, then I'll teach it to you.",logDesc="Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.",rewards={{id=6828,qty=1}}} end
if not DB[1394] then DB[1394]={id=1394,zoneId=400,name="Final Passage",level=36,minLevel=25,giver="Parqual Fintallas",giverType="NPC",giverId=4488,ender="Dorn Plainstalker",enderType="NPC",enderId=2986,poiX=1459,poiY=319,wowhead="https://www.wowhead.com/wotlk/quest=1394",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have done well, $N. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles. He will sense the change within you, and see that your mind, body and spirit are strong enough that you should be rewarded for your efforts.$B$BStay true to the balance you've shown throughout these trials, $N. Dorn will test you again in the future if you do.",logDesc="Speak to Dorn Plainstalker in Thousand Needles.",choiceRewards={{id=6804,qty=1},{id=6806,qty=1}}} end
if not DB[1395] then DB[1395]={id=1395,zoneId=10,name="Supplies for Nethergarde",level=45,minLevel=40,giver="Watchmaster Sorigal",giverType="NPC",giverId=5464,ender="Quartermaster Lungertz",enderType="NPC",enderId=5393,poiX=-10547,poiY=-1212,wowhead="https://www.wowhead.com/wotlk/quest=1395",image="assets/images/quests/placeholder.png",xpDiff=4,money=5000,desc="This crate of powerstones needs to go to Nethergarde Keep, in the Blasted Lands.  They won't hold their power for long, so we can't ship them with the next caravan.$B$BYou must take them, and you must take them quickly.$B$BBring them to Quartermaster Lungertz in Nethergarde Keep.  To reach the keep, you must travel east through Deadwind Pass, then east through the Swamp of Sorrows, then south through the Blasted Lands.$B$BUse caution, $N.  You will travel through dangerous lands, yet you must not fail.",logDesc="Bring the Crate of Powerstones to Quartermaster Lungertz, before the powerstones expire."} end
if not DB[1396] then DB[1396]={id=1396,zoneId=8,name="Encroaching Wildlife",level=37,minLevel=30,giver="Watcher Biggs",giverType="NPC",giverId=5476,ender="Watcher Biggs",enderType="NPC",enderId=5476,rewardNextId=1421,poiX=-10536,poiY=-2836,wowhead="https://www.wowhead.com/wotlk/quest=1396",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My caravan was destined for the eastern coast, but we did not reach our goal.  Lost Ones attacked us, killing guards and dashing supplies.$B$BI alone survived their assault.  I have sworn to protect what supplies remain, but wild creatures skulk near.  Please, help me defend my camp from the beasts!",logDesc="Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows."} end
if not DB[1397] then DB[1397]={id=1397,zoneId=0,name="<nyi> Saved!",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=1397",image="assets/images/quests/placeholder.png"} end
if not DB[1398] then DB[1398]={id=1398,zoneId=8,name="Driftwood",level=42,minLevel=30,giver="Watcher Biggs",giverType="NPC",giverId=5476,ender="Watcher Biggs",enderType="NPC",enderId=5476,rewardNextId=1425,poiX=-10536,poiY=-2836,wowhead="https://www.wowhead.com/wotlk/quest=1398",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I owe you greatly, $N.  An honorable heart beats within you.  And now I have another task for which I humbly ask your aid.$B$BIf I'm ever to reach Nethergarde, then I must fix this wagon.  And for that... I will need wood.  Strong, dry wood--not the spongy, tangled wood of the swamp's trees.$B$B$N, go east to the coast and search for driftwood that has been dried by the sun.  Bring it to me.",logDesc="Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows."} end
if not DB[1418] then DB[1418]={id=1418,zoneId=8,name="Neeka Bloodscar",level=35,minLevel=30,giver="Helgrum the Swift",giverType="NPC",giverId=1442,ender="Neeka Bloodscar",enderType="NPC",enderId=5394,rewardNextId=1420,poiX=-10465,poiY=-3318,wowhead="https://www.wowhead.com/wotlk/quest=1418",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The Badlands is harsh and lies close to the Alliance-held land of Loch Modan, so communication between Stonard and the Badlands outpost of Kargath is often cut.$B$BProve yourself, $N.  Travel to the Badlands and speak with Neeka Bloodscar, head scout of the Kargath outpost.  Speak with her, and then send her report back to me.",logDesc="Speak with Neeka Bloodscar."} end
if not DB[1419] then DB[1419]={id=1419,zoneId=3,name="Coyote Thieves",level=40,minLevel=30,giver="Neeka Bloodscar",giverType="NPC",giverId=5394,ender="Neeka Bloodscar",enderType="NPC",enderId=5394,poiX=-6672,poiY=-2240,wowhead="https://www.wowhead.com/wotlk/quest=1419",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Have you spent many days in the Badlands, $c?  Have you felt its heat? Have you faced the beasts that wander its dusty plains?  It's time you did.$B$BCrag coyotes are a tough breed.  Tough, and bold enough to creep into Kargath and steal from our food supplies.  Help rid the outpost of these thieves!$B$BHunt crag coyotes, $N.  Hunt them and bring me their jawbones.  Bring me enough, and maybe I'll believe it when you say you know the Badlands.",logDesc="Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath."} end
if not DB[1420] then DB[1420]={id=1420,zoneId=3,name="Report to Helgrum",level=40,minLevel=30,giver="Neeka Bloodscar",giverType="NPC",giverId=5394,ender="Helgrum the Swift",enderType="NPC",enderId=1442,poiX=-6672,poiY=-2240,wowhead="https://www.wowhead.com/wotlk/quest=1420",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I wrote a fresh report for Helgrum in Stonard.  Bring it to him.$B$BAnd if you consider yourself an outrunner, then don't lose your way.  Or fall to an enemy.",logDesc="Bring Neeka's Report to Helgrum the Swift in Stonard."} end
if not DB[1421] then DB[1421]={id=1421,zoneId=8,name="The Lost Caravan",level=35,minLevel=30,giver="Watcher Biggs",giverType="NPC",giverId=5476,ender="Watcher Biggs",enderType="NPC",enderId=5476,rewardNextId=1398,poiX=-10536,poiY=-2836,wowhead="https://www.wowhead.com/wotlk/quest=1421",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I was stunned during the attack by the Lost Ones, but before my sight went black I spied one of our wagons being dragged to the Fallow Sanctuary, the lost one village to the north.$B$BA caravan chest with valuable reagents was in that wagon, reagents vital to the studies of the wizards of Nethergarde Keep.  Find the chest and get those reagents, $N.  Get them and bring them to me.",logDesc="Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs."} end
if not DB[1422] then DB[1422]={id=1422,zoneId=8,name="Threat From the Sea",level=45,minLevel=35,giver="Tok'Kar",giverType="NPC",giverId=5592,ender="Katar",enderType="NPC",enderId=5593,rewardNextId=1426,poiX=-10859,poiY=-4088,wowhead="https://www.wowhead.com/wotlk/quest=1422",image="assets/images/quests/placeholder.png",desc="While I begin work on your weapon, why don't you talk to Katar? He mentioned needing help with patrols along the beach, and I'd rather see you keep your wits and weapons prepared instead of getting drunk with some of the other louses I share this camp with.",logDesc="Speak to Katar in the Swamp of Sorrows."} end
if not DB[1423] then DB[1423]={id=1423,zoneId=8,name="The Lost Supplies",level=40,minLevel=30,ender="Quartermaster Lungertz",enderType="NPC",enderId=5393,wowhead="https://www.wowhead.com/wotlk/quest=1423",image="assets/images/quests/placeholder.png",desc="This barrel is small yet sturdy.  Its seams are sealed with a yellow, pungent wax.  Stamped on the bottom of the barrel are the words:$B$BQUARTERMASTER LUNGERTZ$B$BNETHERGARDE KEEP",logDesc="Bring the Lost Supplies to Quartermaster Lungertz.",rewards={{id=6827,qty=1}}} end
if not DB[1424] then DB[1424]={id=1424,zoneId=8,name="Pool of Tears",level=43,minLevel=38,giver="Fel'zerul",giverType="NPC",giverId=1443,ender="Fel'zerul",enderType="NPC",enderId=1443,rewardNextId=1429,poiX=-10458,poiY=-3322,wowhead="https://www.wowhead.com/wotlk/quest=1424",image="assets/images/quests/placeholder.png",xpDiff=6,money=12000,desc="The Warchief sent us to investigate strange happenings at The Temple of Atal'Hakkar.$b$bThe Atal'ai trolls are a tribe of dark casters, known for practicing forbidden magic. You can imagine how astonished we were when we arrived here to discover the temple had been sunk.$b$bThe green dragons now guard the site, claiming to be protectors of Azeroth.$b$bWe need to discover what happened. Explore around the Pool of Tears and gather Atal'ai artifacts. From those I can begin to piece together this puzzle.",logDesc="Fel'zerul in Stonard wants you to gather 5 Atal'ai Artifacts."} end
if not DB[1425] then DB[1425]={id=1425,zoneId=8,name="Deliver the Shipment",level=42,minLevel=30,giver="Watcher Biggs",giverType="NPC",giverId=5476,ender="Quartermaster Lungertz",enderType="NPC",enderId=5393,poiX=-10536,poiY=-2836,wowhead="https://www.wowhead.com/wotlk/quest=1425",image="assets/images/quests/placeholder.png",xpDiff=4,desc="While I fix this wagon, $N, I have one last task for you.$B$BI have packed the most vital supplies saved from the ogre attacks.  Take them to Nethergarde Keep.  The keep is nestled in the northern hills of the Blasted Lands, keeping watch over the Dark Portal.$B$BTo reach Nethergard, follow the road east.  When it branches head south into the Blasted Lands, then turn left at the next fork.  Follow the road, $N, and be wary.",logDesc="Bring the Shipment to Nethergarde to Quartermaster Lungertz in Nethergarde Keep."} end
if not DB[1426] then DB[1426]={id=1426,zoneId=8,name="Threat From the Sea",level=43,minLevel=35,giver="Katar",giverType="NPC",giverId=5593,ender="Katar",enderType="NPC",enderId=5593,rewardNextId=1427,poiX=-10850,poiY=-4144,wowhead="https://www.wowhead.com/wotlk/quest=1426",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I have no love for the sea, nor any creature I've seen come from its depths. It is a powerful but blind mistress; callous and brutal. It would bring me great pleasure to slay the fish men by the hundreds if it were within my power. But I garner some pleasure from watching their deaths at the hands of any who do the Horde's will.$B$BWhich brings us to you, $c. How many can you slay? Would you test yourself against their most powerful kind?",logDesc="Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows."} end
if not DB[1427] then DB[1427]={id=1427,zoneId=8,name="Threat From the Sea",level=43,minLevel=35,giver="Katar",giverType="NPC",giverId=5593,ender="Tok'Kar",enderType="NPC",enderId=5592,poiX=-10850,poiY=-4144,wowhead="https://www.wowhead.com/wotlk/quest=1427",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you. You would do well to test its strength against the fish men when you are ready... but only to please me further.",logDesc="Speak with Tok'Kar in the Swamp of Sorrows.",choiceRewards={{id=9680,qty=1},{id=9678,qty=1},{id=9679,qty=1}}} end
if not DB[1428] then DB[1428]={id=1428,zoneId=8,name="Continued Threat",level=45,minLevel=35,giver="Katar",giverType="NPC",giverId=5593,ender="Katar",enderType="NPC",enderId=5593,poiX=-10850,poiY=-4144,wowhead="https://www.wowhead.com/wotlk/quest=1428",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It pleases me to see your hatred for the fish men grows with mine.$B$BFind more of their kind along the beach, and when you've had your fill of combat, return to me. We shall speak then of a reward for your diligence.",logDesc="Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows."} end
if not DB[1429] then DB[1429]={id=1429,zoneId=8,name="The Atal'ai Exile",level=44,minLevel=38,giver="Fel'zerul",giverType="NPC",giverId=1443,ender="Atal'ai Exile",enderType="NPC",enderId=5598,rewardNextId=1444,poiX=-10458,poiY=-3322,wowhead="https://www.wowhead.com/wotlk/quest=1429",image="assets/images/quests/placeholder.png",xpDiff=5,desc="While you were braving the dangers of the Pool of Tears, one of my scouts returned with a scroll written in blood on dried flesh. It seems to be a judicial sentence against a priest of the Atal'ai tribe.$b$bThis priest was sentenced to a fate worse than death amongst the Atal'ai.$b$bHe was exiled to live far north in the Hinterlands, with the Witherbark trolls.$b$bI will bundle these artifacts. You are to seek out the exile and discover their true use. Return to me once your journey is complete.",logDesc="Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands."} end
if not DB[1430] then DB[1430]={id=1430,zoneId=8,name="Fresh Meat",level=44,minLevel=35,giver="Dar",giverType="NPC",giverId=5591,ender="Dar",enderType="NPC",enderId=5591,poiX=-10496,poiY=-3248,wowhead="https://www.wowhead.com/wotlk/quest=1430",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers.$B$BIf you plan on heading to the coast, then I could easily make it worth your while to bring me back some of their legs to have transported back to Orgrimmar.$B$BThe coast is to the east from here, and you should have no problem finding the creatures scurrying along the beaches and under the sea.",logDesc="Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.",rewards={{id=9681,qty=10},{id=9682,qty=1}}} end
if not DB[1431] then DB[1431]={id=1431,zoneId=1637,name="Alliance Relations",level=30,minLevel=30,giver="Craven Drok",giverType="NPC",giverId=5639,ender="Keldran",enderType="NPC",enderId=5640,rewardNextId=1432,poiX=1844,poiY=-4400,wowhead="https://www.wowhead.com/wotlk/quest=1431",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Be still, $c, and allow me to share with you something important to our people, but far from obvious.$B$BWe are a proud race, and the war with the humans tried even Thrall's great patience. You see, our Warchief is wise and prudent, and he continues to put his people first. Ultimately, he is a diplomat, and in his time with the humans he learned much of their ways.$B$BIf the tale I've started piques your interest, then find Keldran near the western exit of the city. His hovel is there.",logDesc="Speak to Keldran in Orgrimmar."} end
if not DB[1432] then DB[1432]={id=1432,zoneId=1637,name="Alliance Relations",level=30,minLevel=30,giver="Keldran",giverType="NPC",giverId=5640,ender="Takata Steelblade",enderType="NPC",enderId=5641,poiX=1782,poiY=-3997,wowhead="https://www.wowhead.com/wotlk/quest=1432",image="assets/images/quests/placeholder.png",xpDiff=3,desc="As the Alliance progresses deeper and deeper into Kalimdor, incorrect conclusions may be drawn about the Horde making pacts with the Burning Legion. The Warchief cannot allow that to happen. And with his blessing, I am taking control of overseeing them removed.$B$BI have agents in the area of Desolace at the Ghost Walker Post north of the great Kodo Graveyard. Head south of the Charred Vale in the Stonetalon Mountains and you shall come across it. When you arrive, seek out Takata Steelblade.",logDesc="Speak to Takata Steelblade in Desolace."} end
if not DB[1433] then DB[1433]={id=1433,zoneId=1637,name="Alliance Relations",level=33,minLevel=30,giver="Takata Steelblade",giverType="NPC",giverId=5641,ender="Maurin Bonesplitter",enderType="NPC",enderId=4498,rewardNextId=1435,poiX=-1178,poiY=1870,wowhead="https://www.wowhead.com/wotlk/quest=1433",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Burning Blade have many agendas, but know that they are evil to their core, their spirits corrupted, and their destruction is the only way to thwart their objectives.$B$BKeldran sent Maurin with me because of his knowledge of the Blade and their warlock ways.$B$BHe has control of our plots against the Blade while I deal with the other demonic threats here in Desolace.$B$BSpeak to him, and he will guide you in his designs.",logDesc="Speak to Maurin Bonesplitter in Desolace."} end
if not DB[1434] then DB[1434]={id=1434,zoneId=1637,name="Befouled by Satyr",level=33,minLevel=25,giver="Takata Steelblade",giverType="NPC",giverId=5641,ender="Takata Steelblade",enderType="NPC",enderId=5641,poiX=-1178,poiY=1870,wowhead="https://www.wowhead.com/wotlk/quest=1434",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A demon infestation does not occur without other influences--something else allows evil to gain a foothold.$B$BIt may start with a weakened spirit, a needless desire for power; perhaps it's a thirst for revenge, or the appeal for final justice. When we are beset by pain, evil takes advantage of us--evil such as the satyr.$B$BTies have been made between them and the Burning Blade, and Thrall would have them slain. Seek them out to the northeast of here, and return to me when you've driven them back.",logDesc="Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace."} end
if not DB[1435] then DB[1435]={id=1435,zoneId=1637,name="The Burning of Spirits",level=33,minLevel=25,giver="Maurin Bonesplitter",giverType="NPC",giverId=4498,ender="Maurin Bonesplitter",enderType="NPC",enderId=4498,poiX=-1150,poiY=1884,wowhead="https://www.wowhead.com/wotlk/quest=1435",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Death is most desirable for those despicable creatures that turn their back on their liege for such selfish reasons. But death is not enough when dealing with those that have given themselves over to the darkness.$B$BTake this gem. When one of the Burning Blade's near death, activate its magic. The spell shall pull the corrupted spirit out of its victim, leaving an infused gem behind.$B$BBring me these infused gems so I may dispose of them properly.$B$BGo now, and may you elude death.",logDesc="Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace."} end
if not DB[1436] then DB[1436]={id=1436,zoneId=1637,name="Alliance Relations",level=33,minLevel=30,giver="Takata Steelblade",giverType="NPC",giverId=5641,ender="Keldran",enderType="NPC",enderId=5640,poiX=-1178,poiY=1870,wowhead="https://www.wowhead.com/wotlk/quest=1436",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The fight goes well, $N. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings.$B$BReturn to Keldran and let him know what we have done. I am sure he will reward you for your efforts here. His cause is important to him, and he will take pride in knowing that the Warchief respects his concerns.",logDesc="Speak to Keldran in Orgrimmar.",choiceRewards={{id=6744,qty=1},{id=6745,qty=1}}} end
if not DB[1437] then DB[1437]={id=1437,zoneId=405,name="Vahlarriel's Search",level=33,minLevel=30,giver="Vahlarriel Demonslayer",giverType="NPC",giverId=5642,rewardNextId=1465,poiX=98,poiY=1246,wowhead="https://www.wowhead.com/wotlk/quest=1437",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I am Vahlarriel, $N. I've come here to discover the whereabouts of two missing nobles of a Darnassian merchant family--House Malem. The father of the house fears the worst, and I am to do everything I can to find his missing children. I have yet to start my search for Tyranis or Dalinda, but I am hopeful I shall not be here long.$B$BLast word tells of them passing through the Stonetalon Mountains a few weeks ago.$B$BIf you find their wagon, please, come find me immediately.",logDesc="Find and search Tyranis and Dalinda Malem's wagon in Desolace."} end
if not DB[1438] then DB[1438]={id=1438,zoneId=405,name="Vahlarriel's Search",level=33,minLevel=30,giver="Vahlarriel Demonslayer",giverType="NPC",giverId=5642,ender="Dalinda Malem",enderType="NPC",enderId=5644,rewardNextId=1439,poiX=98,poiY=1246,wowhead="https://www.wowhead.com/wotlk/quest=1438",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Find both Dalinda and Tyranis if you can and come back to me with your findings. Start your search at this fortress. I will contact my superiors in Darnassus immediately and let them know the situation.$B$B$N, there is something else I wish to impress upon you. My superiors have shown some concern over Tyranis' and his motives for coming here. It is more important to them that Dalinda is found and brought back safely. Tyranis is to be... gauged before he is taken home.",logDesc="Find Dalinda Malem in Desolace."} end
if not DB[1439] then DB[1439]={id=1439,zoneId=405,name="Search for Tyranis",level=33,minLevel=30,giver="Dalinda Malem",giverType="NPC",giverId=5644,ender="Dalinda Malem",enderType="NPC",enderId=5644,poiX=-331,poiY=1767,wowhead="https://www.wowhead.com/wotlk/quest=1439",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We were brought here after the orcs slaughtered all our guards and servants. Oh, the terrible things they did to them! I thought surely they would kill us right there and then, but it became obvious they had other plans.$B$BTyranis attempted to speak to them. I think he wanted to impress them with his knowledge of the arcane... I'm not sure why.$B$BPlease, I can't leave here until I know what's happened to my brother. Find him, then come back for me when his fate is known.",logDesc="Find Tyranis Malem in Desolace."} end
if not DB[1440] then DB[1440]={id=1440,zoneId=405,name="Return to Vahlarriel",level=33,minLevel=30,giver="Dalinda Malem",giverType="NPC",giverId=5644,ender="Vahlarriel Demonslayer",enderType="NPC",enderId=5642,poiX=-331,poiY=1767,wowhead="https://www.wowhead.com/wotlk/quest=1440",image="assets/images/quests/placeholder.png",xpDiff=6,desc="So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family. If you're ready, then there is nothing else for me here--we can leave when you feel the time is right.",logDesc="Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.",choiceRewards={{id=9687,qty=1},{id=9698,qty=1},{id=9699,qty=1},{id=11884,qty=1}}} end
if not DB[1441] then DB[1441]={id=1441,zoneId=405,name="<UNUSED>",level=33,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1441",image="assets/images/quests/placeholder.png",xpDiff=6} end
if not DB[1442] then DB[1442]={id=1442,zoneId=-141,name="Seeking the Kor Gem",level=22,minLevel=20,giver="Thundris Windweaver",giverType="NPC",giverId=3649,ender="Thundris Windweaver",enderType="NPC",enderId=3649,poiX=6581,poiY=492,wowhead="https://www.wowhead.com/wotlk/quest=1442",image="assets/images/quests/placeholder.png",desc="Greetings, $N. What can I do for one who follows a holy path?$B$BAh, yes, Stilwell, the blacksmith... from long ago. I remember him well, though, I have not heard his name in some time.$B$BHe never struck me as an impudent man, so I can only assume his desire for a Kor gem is noble.$B$BIf you truly wish for one of the gems, then you must head to the northwest of Ashenvale. You will find Blackfathom Deeps there within some ancient ruins. The naga who still use the gems are down below. Do not go alone, $c.",logDesc="Bring a Kor Gem to Thundris Windweaver in Darkshore.",rewards={{id=7083,qty=1}}} end
if not DB[1443] then DB[1443]={id=1443,zoneId=1638,name="<nyi> The Shakedown",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=1443",image="assets/images/quests/placeholder.png"} end
if not DB[1444] then DB[1444]={id=1444,zoneId=47,name="Return to Fel'Zerul",level=44,minLevel=38,giver="Atal'ai Exile",giverType="NPC",giverId=5598,ender="Fel'zerul",enderType="NPC",enderId=1443,rewardNextId=1445,poiX=-464,poiY=-2874,wowhead="https://www.wowhead.com/wotlk/quest=1444",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader.$b$bHis unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already.$b$bWhen I expressed my concerns, I was labeled an infidel and ousted from the temple.$b$bThose artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril....",logDesc="Return to Fel'Zerul in Stonard."} end
if not DB[1445] then DB[1445]={id=1445,zoneId=1417,name="The Temple of Atal'Hakkar",level=50,minLevel=38,giver="Fel'zerul",giverType="NPC",giverId=1443,ender="Fel'zerul",enderType="NPC",enderId=1443,poiX=-10458,poiY=-3322,wowhead="https://www.wowhead.com/wotlk/quest=1445",image="assets/images/quests/placeholder.png",xpDiff=7,desc="So he spoke of Jammal'an's prophecy?$b$bThe Atal'ai spiritual leader believes once Hakkar returns to Azeroth from the Nether, the god will grant the Atal'ai tribe immortality.$b$bFoolish trickery to bring about a premature doomsday if you ask me.$b$bBut you say the exile spoke of enchanted fetishes? This concerns me greatly. If these are in fact the key to the Atal'ai ritual which caused this mess, we must understand their intrinsic powers.$b$bVenture into the Temple, and seize the fetishes!",logDesc="Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.",rewards={{id=1490,qty=1}}} end
if not DB[1446] then DB[1446]={id=1446,zoneId=1417,name="Jammal'an the Prophet",level=53,minLevel=38,giver="Atal'ai Exile",giverType="NPC",giverId=5598,ender="Atal'ai Exile",enderType="NPC",enderId=5598,poiX=-464,poiY=-2874,wowhead="https://www.wowhead.com/wotlk/quest=1446",image="assets/images/quests/placeholder.png",xpDiff=7,desc="My Witherbark companions don't take kindly to strangers around their home.$b$bMe? I don't have a home anymore. I was exiled from my people, the great Atal'ai tribe of the Swamp of Sorrows.$b$bOur spiritual leader, Jammal'an, had what he called a prophecy. He believes the summoning of the god, Hakkar will bring the Atal'ai immortality.$b$bBut I urged caution. What if the prophecy was nothing more than manipulation?$b$bI want revenge for my exile. Bring me Jammal'an's head. Maybe then my people will be free.",logDesc="The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.",choiceRewards={{id=11123,qty=1},{id=11124,qty=1}}} end
if not DB[1447] then DB[1447]={id=1447,zoneId=1519,name="The Missing Diplomat",level=31,minLevel=28,giver="Dashel Stonefist",giverType="NPC",giverId=4961,ender="Dashel Stonefist",enderType="NPC",enderId=4961,rewardNextId=1247,poiX=-8681,poiY=433,wowhead="https://www.wowhead.com/wotlk/quest=1447",image="assets/images/quests/placeholder.png",xpDiff=3,desc=" Yeah, you're obviously not the smartest $c to come into Stormwind, but you're about to be one of the dumbest to never leave.$B$BHave you met me friends?",logDesc="Defeat Dashel Stonefist in Stormwind."} end
if not DB[1448] then DB[1448]={id=1448,zoneId=1519,name="In Search of The Temple",level=43,minLevel=38,giver="Brohann Caskbelly",giverType="NPC",giverId=5384,ender="Brohann Caskbelly",enderType="NPC",enderId=5384,rewardNextId=1449,poiX=-8464,poiY=516,wowhead="https://www.wowhead.com/wotlk/quest=1448",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There was a time when I was young and full of vigor like you, $c.$b$bBut now I'm old and unable to explore the world like I once did. Ah, the things I saw!$b$bBut there was one mystery that eluded me. For my final quest, the Explorers' League sent me in search of The Temple of Atal'Hakkar. It was rumored to be located in the Swamp of Sorrows.$b$bBecause of my frail state, I traveled the skies by gryphon in search of it but never found it.$b$bHelp an old dwarf out? Perhaps you will have better luck on foot.",logDesc="Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar."} end
if not DB[1449] then DB[1449]={id=1449,zoneId=1519,name="To The Hinterlands",level=43,minLevel=38,giver="Brohann Caskbelly",giverType="NPC",giverId=5384,ender="Falstad Wildhammer",enderType="NPC",enderId=5635,rewardNextId=1450,poiX=-8464,poiY=516,wowhead="https://www.wowhead.com/wotlk/quest=1449",image="assets/images/quests/placeholder.png",xpDiff=3,desc="As I mentioned earlier, I attempted to scout the temple on my own from the air. Well, I wasn't exactly alone.$b$bI traveled to the renowned gryphon aviary at Aerie Peak in The Hinterlands. There I enlisted the aid of one of their finest pilots. The pilot fell off his mount, down into the swamp...$b$bIn my old age the poor fellow's name eludes me. The master of the aviary would remember, no doubt.$b$bJourney there and seek out Falstad Wildhammer.$b$bWe need to find out what happened to that pilot.",logDesc="Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands."} end
if not DB[1450] then DB[1450]={id=1450,zoneId=47,name="Gryphon Master Talonaxe",level=43,minLevel=38,giver="Falstad Wildhammer",giverType="NPC",giverId=5635,ender="Gryphon Master Talonaxe",enderType="NPC",enderId=5636,rewardNextId=1451,poiX=267,poiY=-2030,wowhead="https://www.wowhead.com/wotlk/quest=1450",image="assets/images/quests/placeholder.png",xpDiff=2,desc="So you're a glorified errand $g boy:girl; for some old Explorers' League geezer, eh?$b$bWell you listen to me, $c. I don't know who your old buddy was flying around with down in Azeroth. Do I look like Gryphon Master Talonaxe to you? Do I?$b$bIf you're so interested in the flight assignments why don't you ask the gryphon master? If I catch you idling around here for much longer, I'm going to put you to some real work.$b$bNow get a move on.",logDesc="Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary."} end
if not DB[1451] then DB[1451]={id=1451,zoneId=47,name="Rhapsody Shindigger",level=43,minLevel=38,giver="Gryphon Master Talonaxe",giverType="NPC",giverId=5636,ender="Rhapsody Shindigger",enderType="NPC",enderId=5634,rewardNextId=1452,poiX=325,poiY=-1950,wowhead="https://www.wowhead.com/wotlk/quest=1451",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Rhapsody took quite a liking to the booze. Now don't get me wrong -- all of us dwarves up here at the aviary love a good ale when the time is right.$b$bBut ol' Shindigger took to the liquor like a gryphon takes to the skies. And a damned shame it was, too. No one could fly like Rhapsody.$b$bFirst sign of trouble was when he came stumbling back from that mission with your buddy, Brohann. All went down hill quickly after that. Had to let him go.$b$bLast I heard, he's set up a brew camp to the east of here...",logDesc="Seek out Rhapsody Shindigger in The Hinterlands."} end
if not DB[1452] then DB[1452]={id=1452,zoneId=47,name="Rhapsody's Kalimdor Kocktail",level=43,minLevel=38,giver="Rhapsody Shindigger",giverType="NPC",giverId=5634,ender="Rhapsody Shindigger",enderType="NPC",enderId=5634,poiX=220,poiY=-2612,wowhead="https://www.wowhead.com/wotlk/quest=1452",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hiccup!$b$bSo that crazy fool Brohann sent ya? My we had quite an adventure...Hiccup!$b$bIf ya want me to tell ya what happened down in the swamp, I'm gonna need me something stiff to drink. It wasn't a pretty scene, ya see. Hiccup!$b$bTell ya what... bring me what I need to whip up a Kalimdor Kocktail and I'll tell ya all about it.$b$bGonna need some Roc gizzards from Tanaris... and let's see... some Groddoc and Ironfur livers from Feralas...$b$bA nice stiff Kalimdor Kocktail... that'll get me talking!",logDesc="Rhapsody Shindigger in The Hinterlands wants you to bring him 3 Roc Gizzards, 3 Groddoc Livers and 3 Ironfur Livers."} end
if not DB[1453] then DB[1453]={id=1453,zoneId=1537,name="Reclaimers' Business in Desolace",level=33,minLevel=30,giver="Roetten Stonehammer",giverType="NPC",giverId=5637,ender="Kreldig Ungor",enderType="NPC",enderId=5638,poiX=-4681,poiY=-1267,wowhead="https://www.wowhead.com/wotlk/quest=1453",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There's work to be done in Desolace, $N. It's an atrocious place, befouled by centaur and other nasties. But if you're looking for a good week's honest work, then head there, meet with Kreldig Ungor, and tell him I sentcha.$B$BYou can find him holed up at Nijel's Point--it's a little cozy camp hidden in the mountains of northern Desolace. Just head east if you enter from the Stonetalon Mountains. It's easy to miss, so be on the lookout.",logDesc="Speak to Kreldig Ungor at Nijel's Point in Desolace."} end
if not DB[1454] then DB[1454]={id=1454,zoneId=405,name="The Karnitol Shipwreck",level=39,minLevel=30,giver="Kreldig Ungor",giverType="NPC",giverId=5638,rewardNextId=1455,poiX=163,poiY=1257,wowhead="https://www.wowhead.com/wotlk/quest=1454",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My first order of business is for the mage Karnitol--a noble of some sort in Stormwind. Seems his ship was attacked by sea giants while off the coast in the northwest of Desolace. He and his servants tried to bring one of his more valuable chests ashore, but when the sea giants attacked in droves, he chose to abandon it and teleport himself and his servants to safety.$B$BHe wants us to find the chest and its contents, and return it to him in Stormwind.",logDesc="Find Karnitol's Chest in Desolace."} end
if not DB[1455] then DB[1455]={id=1455,zoneId=405,name="The Karnitol Shipwreck",level=39,minLevel=30,ender="Kreldig Ungor",enderType="NPC",enderId=5638,rewardNextId=1456,wowhead="https://www.wowhead.com/wotlk/quest=1455",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You take a few moments to figure out what pried the chest open, and you notice along the sides and top of the chest, long, deep scratches that reveal that something other than a man or giant took interest in it. The marks don't appear as if they were caused by dagger or sword.$B$BAfter going through the chest you find it to be completely empty.$B$BNot having another course of action, you close the chest and prepare to leave. Kreldig will be disappointed.",logDesc="Return to Kreldig Ungor at Nijel's Point in Desolace."} end
if not DB[1456] then DB[1456]={id=1456,zoneId=405,name="The Karnitol Shipwreck",level=39,minLevel=30,giver="Kreldig Ungor",giverType="NPC",giverId=5638,ender="Kreldig Ungor",enderType="NPC",enderId=5638,rewardNextId=1457,poiX=163,poiY=1257,wowhead="https://www.wowhead.com/wotlk/quest=1456",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Intriguing.$B$BWell, we might not be without hope quite yet.$B$BAlong that same coast, but to the north near Ranazjar Isle, there're night elf ruins at the bottom of the ocean. A tribe of naga, the Slitherblade, make that their home. I think that'd be our best bet.$B$BIf a scouting party went that far south, then they must've been pretty powerful. If you're gonna find Karnitol's belongings, I'd start with the more powerful naga: the tidehunters or sea witches.",logDesc="Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace."} end
if not DB[1457] then DB[1457]={id=1457,zoneId=405,name="The Karnitol Shipwreck",level=39,minLevel=30,giver="Kreldig Ungor",giverType="NPC",giverId=5638,ender="Roetten Stonehammer",enderType="NPC",enderId=5637,poiX=163,poiY=1257,wowhead="https://www.wowhead.com/wotlk/quest=1457",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done.$B$BHaha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time.$B$BAgain, great job, $N.$B$BBe careful on your way back, and don't take too much time--Karnitol's not the most of patient of men, but he's very generous nonetheless.",logDesc="Bring Karnitol's Satchel to Roetten Stonehammer in Ironforge.",choiceRewards={{id=6791,qty=1},{id=6792,qty=1}}} end
if not DB[1458] then DB[1458]={id=1458,zoneId=405,name="Reagents for Reclaimers Inc.",level=33,minLevel=30,giver="Kreldig Ungor",giverType="NPC",giverId=5638,ender="Kreldig Ungor",enderType="NPC",enderId=5638,rewardNextId=1459,poiX=163,poiY=1257,wowhead="https://www.wowhead.com/wotlk/quest=1458",image="assets/images/quests/placeholder.png",xpDiff=5,money=3500,desc="One of my tasks out here involves picking up some reagents for Leftwitch, a gnome mage in Kharanos . Roetten seems to think it's easy coin in the bank since we're out here already. He doesn't really care that we're short-handed as is.$B$BThe first few items on his list should be easy enough to get, and it'd be a good chunk of coin for anyone helping me out.$B$BI need some horns and claws from the Hatefury satyr to the east of here. Bring 'em back to me and we'll get started on the rest of the list.",logDesc="Bring 10 Hatefury Claws, and 10 Hatefury Horns to Kreldig Ungor in Desolace."} end
if not DB[1459] then DB[1459]={id=1459,zoneId=405,name="Reagents for Reclaimers Inc.",level=35,minLevel=30,giver="Kreldig Ungor",giverType="NPC",giverId=5638,ender="Kreldig Ungor",enderType="NPC",enderId=5638,rewardNextId=1466,poiX=163,poiY=1257,wowhead="https://www.wowhead.com/wotlk/quest=1459",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="Next on Leftwitch's list is... let's see... hmm. Oh, here it is.$B$BSimple enough, but pretty explicit in his directions. He needs venom from the scorpashi, and hide from some kodo. The fine print says both are from specific creatures: the venom's got to come from any of the scorpashi, and the hide's got to come from an aged kodo, not the dying or ancient ones.$B$BMages, I tell ya, some of the stuff they want... it's just weird.",logDesc="Bring 7 vials of Scorpashi Venom and 3 Aged Kodo Hides to Kreldig Ungor in Desolace."} end
if not DB[1460] then DB[1460]={id=1460,zoneId=405,name="<UNUSED>",level=37,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1460",image="assets/images/quests/placeholder.png"} end
if not DB[1461] then DB[1461]={id=1461,zoneId=405,name="<UNUSED>",level=37,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1461",image="assets/images/quests/placeholder.png"} end
