if not DB[1463] then DB[1463]={id=1463,zoneId=-82,name="Earth Sapta",level=4,minLevel=4,giver="Canaga Earthcaller",giverType="NPC",giverId=5887,ender="Canaga Earthcaller",enderType="NPC",enderId=5887,poiX=-630,poiY=-4205,wowhead="https://www.wowhead.com/wotlk/quest=1463",image="assets/images/quests/placeholder.png",logDesc="Speak to Canaga Earthcaller for another Earth Sapta.",rewards={{id=6635,qty=1}}} end
if not DB[1464] then DB[1464]={id=1464,zoneId=-82,name="Fire Sapta",level=-1,minLevel=10,giver="Telf Joolam",giverType="NPC",giverId=5900,ender="Telf Joolam",enderType="NPC",enderId=5900,poiX=-270,poiY=-4001,wowhead="https://www.wowhead.com/wotlk/quest=1464",image="assets/images/quests/placeholder.png",logDesc="Speak to Telf Joolam for another Fire Sapta.",rewards={{id=6636,qty=1}}} end
if not DB[1465] then DB[1465]={id=1465,zoneId=405,name="Vahlarriel's Search",level=33,minLevel=30,ender="Vahlarriel Demonslayer",enderType="NPC",enderId=5642,rewardNextId=1438,wowhead="https://www.wowhead.com/wotlk/quest=1465",image="assets/images/quests/placeholder.png",xpDiff=4,desc="As you continue your search of the wagon you find not only a pendant, but also footprints leading off towards the south. In the distance you can see smoke rising from a large fort. The smoke is from a kept fire, not the burning of buildings, and your instincts tell you that the Malems, if still alive, were taken that direction.$B$BYou think Vahlarriel at Nijel's Point should not only see the pendant you've found, but also know about the signs of life to the south.",logDesc="Return the Malem Pendant to Vahlarriel Demonslayer at Nijel's Point in Desolace."} end
if not DB[1466] then DB[1466]={id=1466,zoneId=405,name="Reagents for Reclaimers Inc.",level=40,minLevel=30,giver="Kreldig Ungor",giverType="NPC",giverId=5638,ender="Kreldig Ungor",enderType="NPC",enderId=5638,rewardNextId=1467,poiX=163,poiY=1257,wowhead="https://www.wowhead.com/wotlk/quest=1466",image="assets/images/quests/placeholder.png",xpDiff=5,money=3500,desc="This is the last of the items, and I won't lie, it ain't pretty. I'm also expecting this to take you a little bit longer than the other items.$B$BSo, enough with the warning, let's get this started. Leftwitch says he needs: ten brains from either mana eaters, mage hunters, or ley hunters. Ten nether wings from a nether maiden, sister or sorceress. And... ten vials of doomwarder blood from a doomwarder captain, or lord.$B$BSimple enough, huh? Sheesh... if you wanna pass on this one, I'd understand.",logDesc="Bring 10 Felhound Brains, 10 Nether Wings, and 10 vials of Doomwarder Blood to Kreldig Ungor in Desolace."} end
if not DB[1467] then DB[1467]={id=1467,zoneId=405,name="Reagents for Reclaimers Inc.",level=40,minLevel=30,giver="Kreldig Ungor",giverType="NPC",giverId=5638,ender="Roetten Stonehammer",enderType="NPC",enderId=5637,poiX=163,poiY=1257,wowhead="https://www.wowhead.com/wotlk/quest=1467",image="assets/images/quests/placeholder.png",xpDiff=5,money=3500,desc="To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway. Just give him this and it should be enough to get your booty.$B$BAnd don't worry, I'm still going to put in a good word for you when I get back. I shouldn't be in Desolace much longer.",logDesc="Bring Leftwitch's Package back to Roetten Stonehammer in Ironforge.",choiceRewards={{id=6793,qty=1},{id=6794,qty=1}}} end
if not DB[1468] then DB[1468]={id=1468,zoneId=-284,name="Children's Week",level=-1,minLevel=10,ender="Human Orphan",enderType="NPC",enderId=14305,wowhead="https://www.wowhead.com/wotlk/quest=1468",image="assets/images/quests/placeholder.png",desc="You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable.$B$BTake this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child.$B$BBy all means $N - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.",logDesc="Use the Human Orphan Whistle to talk with the child you will be looking after during Children's Week."} end
if not DB[1469] then DB[1469]={id=1469,zoneId=47,name="Rhapsody's Tale",level=43,minLevel=38,giver="Rhapsody Shindigger",giverType="NPC",giverId=5634,ender="Brohann Caskbelly",enderType="NPC",enderId=5384,rewardNextId=1475,poiX=220,poiY=-2612,wowhead="https://www.wowhead.com/wotlk/quest=1469",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Before the flight, I drank me a whole keg of stout. Hiccup!$b$bAnd what a flight it was. Zipping around with Brohann following me. Didn't see no temple though. Hiccup!$b$bWell, didn't see no temple till I got a little too tipsy and fell off my mount. I plunged right into the water and was sucked down. Found myself surrounded by a bunch of creepy trolls. Sure swam out of there fast! Even made off with this troll souvenir. Here, take it to Brohann and let him know his temple is down there, indeed. Hiccup!",logDesc="Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind."} end
if not DB[1470] then DB[1470]={id=1470,zoneId=-61,name="Piercing the Veil",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=1470",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Greetings, child. I can see that you are still young in the ways of the warlock, power still eluding your grasp. I can sense your eagerness to learn.$b$bAnd you will learn.$b$bThere is no strength in ignorance. Knowledge is our greatest power. Through its application, we can control the chaotic magics and beings of the void, bending them to our will.$b$bI will show you how to bind a servant to your will, but first you must bring me three skulls of the rattlecage skeletons near the abandoned smithy.",logDesc="Bring Venya Marthand 3 Rattlecage Skulls."} end
if not DB[1471] then DB[1471]={id=1471,zoneId=-61,name="The Binding",level=-1,minLevel=10,giver="Carendin Halgar",giverType="NPC",giverId=5675,ender="Carendin Halgar",enderType="NPC",enderId=5675,poiX=1712,poiY=57,wowhead="https://www.wowhead.com/wotlk/quest=1471",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Surely you have seen the circle of summoning below us? Only there will you be able to draw forth an unbound voidwalker.$b$bUsing these runes, you will be able to draw it forth, and then you must dominate it through strength of arms and magic.$b$bWhen it is subdued, it will be indentured to you. Come to me then, and I will elucidate the spell of summoning, so that it may serve you to whatever end you wish.",logDesc="Using the Runes of Summoning, summon and subdue a voidwalker, then return the Runes of Summoning to Carendin Halgar in the Magic Quarter of the Undercity."} end
if not DB[1472] then DB[1472]={id=1472,zoneId=-61,name="Devourer of Souls",level=-1,minLevel=20,giver="Carendin Halgar",giverType="NPC",giverId=5675,ender="Godrick Farsan",enderType="NPC",enderId=5693,rewardNextId=1476,poiX=1712,poiY=57,wowhead="https://www.wowhead.com/wotlk/quest=1472",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A succubus is a devourer of souls, destroyer of hearts, tempter of men. A creature of profound evil and of singular mind.$b$bIt cannot be brought into our world without a stimulus.$b$bThus we use its own strength against it. With the hearts of good men, pure men, loving men, the succubus will be unable to resist, and will cross into our world. Then you can dominate it, and make it your own.$b$bSpeak with my assistant, Godrick Farsan, within the Temple. He will help you find your bait.",logDesc="Speak with Godrick Farsan in the Temple of the Damned."} end
if not DB[1473] then DB[1473]={id=1473,zoneId=-61,name="Creature of the Void",level=-1,minLevel=10,giver="Carendin Halgar",giverType="NPC",giverId=5675,ender="Carendin Halgar",enderType="NPC",enderId=5675,rewardNextId=1471,poiX=1712,poiY=57,wowhead="https://www.wowhead.com/wotlk/quest=1473",image="assets/images/quests/placeholder.png",xpDiff=4,desc="It seems the consensus that you are ready to learn to summon a voidwalker.$b$bA being created of the chaos that lies beyond, if you summon one but cannot control it, you will be torn asunder.$b$bThe first voidwalker was summoned by Egalin, and in his grimoire is the process explained.$b$bUnfortunately, it was stolen from us by an agent of the Scarlet Crusade who has it secreted away in his base at a tower to the west. Bring it to me, and I will impart the knowledge to you.",logDesc="Recover Egalin's Grimoire and bring it to Carendin Halgar in the Temple of the Damned."} end
if not DB[1474] then DB[1474]={id=1474,zoneId=-61,name="The Binding",level=-1,minLevel=20,giver="Carendin Halgar",giverType="NPC",giverId=5675,ender="Carendin Halgar",enderType="NPC",enderId=5675,poiX=1712,poiY=57,wowhead="https://www.wowhead.com/wotlk/quest=1474",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Using these hearts, cast a spell at the summoning circle to open a doorway for the succubus to come through. Your powers are greater now, and you will need all of them to defeat the succubus. $b$bBeware its charms, $n, many a strong mind has been bound to its will. When overcome, the succubus will be returned to the void, and I will teach you the spell to summon it forth at your command.",logDesc="Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity.",rewards={{id=22243,qty=1}}} end
if not DB[1475] then DB[1475]={id=1475,zoneId=1417,name="Into The Temple of Atal'Hakkar",level=50,minLevel=38,giver="Brohann Caskbelly",giverType="NPC",giverId=5384,ender="Brohann Caskbelly",enderType="NPC",enderId=5384,poiX=-8464,poiY=516,wowhead="https://www.wowhead.com/wotlk/quest=1475",image="assets/images/quests/placeholder.png",xpDiff=7,desc="According to legend, The Temple of Atal'Hakkar is a holy shrine dedicated to the ancient god, Hakkar the Soulflayer. Maintained by a vicious tribe of trolls named the Atal'ai, the temple is rumored to be impenetrable.$b$bNow sunk beneath the Pool of Tears, retrieving artifacts from the temple is even more difficult. But that's what I need you to do, $n.$b$bAid me by gathering the intact Atal'ai Tablets. Bring them to me and I will return to the Explorers' Guild a hero. Together we will share the glory.",logDesc="Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind.",rewards={{id=1490,qty=1}}} end
if not DB[1476] then DB[1476]={id=1476,zoneId=-61,name="Hearts of the Pure",level=-1,minLevel=20,giver="Godrick Farsan",giverType="NPC",giverId=5693,ender="Carendin Halgar",enderType="NPC",enderId=5675,rewardNextId=1474,poiX=1783,poiY=60,wowhead="https://www.wowhead.com/wotlk/quest=1476",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Men of honor and goodness? Does such a man exist?$b$bIt took much research, but through bits of overheard stories, I managed to find two men that should do.$b$bThe first is Dalin Forgewright, who has dedicated himself to the care of the Lordaeron refugees, whom are refused by their kin at the Greymane Wall.$b$bThe other is Comar Villard, a man who remains faithful to his lost love, wandering the Wetlands for a sign of his wife.$b$bDeliver their hearts to Carendin. But first, let me show you your quarry.",logDesc="Bring the hearts of Dalin Forgewright and Comar Villard to Carendin Halgar in the Temple of the Damned."} end
if not DB[1477] then DB[1477]={id=1477,zoneId=1519,name="Vital Supplies",level=45,minLevel=40,giver="High Sorcerer Andromath",giverType="NPC",giverId=5694,ender="Watchmaster Sorigal",enderType="NPC",enderId=5464,rewardNextId=1395,poiX=-9011,poiY=877,wowhead="https://www.wowhead.com/wotlk/quest=1477",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Our mages are conducting research at Nethergarde Keep in the Blasted Lands, research vital to our understanding of the Dark Portals. They require nearly constant supplies, but our supply line to Nethergarde is tenuous.$B$BYou must help ensure the supplies make it to Nethergard.  Report to Watchmaster Sorigal in Darkshire, and do as he asks.  This task will take you into hostile lands, $N.  Prepare yourself.",logDesc="Speak with Watchmaster Sorigal at Darkshire in Duskwood."} end
if not DB[1478] then DB[1478]={id=1478,zoneId=-61,name="Halgar's Summons",level=-1,minLevel=10,giver="Ageron Kargal",giverType="NPC",giverId=5724,ender="Carendin Halgar",enderType="NPC",enderId=5675,rewardNextId=1473,poiX=2251,poiY=249,wowhead="https://www.wowhead.com/wotlk/quest=1478",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Ah, $n! I just received word from Carendin Halgar that he would like to see you for further training.$b$bYou should be proud of yourself, $n. It's not every day that Master Halgar personally sees fit to instruct a young warlock.$b$bYou'll be able to find him in the Magic Quarter of the Undercity, near the Temple of the Damned.",logDesc="Speak with Carendin Halgar in the Undercity."} end
if not DB[1479] then DB[1479]={id=1479,zoneId=-284,name="The Bough of the Eternals",level=-1,minLevel=10,ender="Human Orphan",enderType="NPC",enderId=14305,wowhead="https://www.wowhead.com/wotlk/quest=1479",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I've heard stories about how the night elves have their bank in a tree - one that looks like a bear!  That's so cool!  Night elves are neat how they like nature and stuff, but bears are just totally awesome!$B$BWould you take me to see the bear-tree in Darnassus, please?  There's a boat that will take us close to there, and it shouldn't take very long.  Please, please, please!",logDesc="Take the orphan to the bank of Darnassus.  The bank itself is hollowed out of a tree known as the Bough of the Eternals."} end
if not DB[1480] then DB[1480]={id=1480,zoneId=405,name="The Corrupter",level=33,minLevel=25,ender="Maurin Bonesplitter",enderType="NPC",enderId=4498,rewardNextId=1481,wowhead="https://www.wowhead.com/wotlk/quest=1480",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The torn skin smells rotten, and is remarkably pliable for something that appears to be dry and fragile.$B$BAs you unroll it, you can clearly see the red markings of some kind of language on one side. At the bottom of the skin is a very clear symbol that you guess is a signature of some kind.$B$BPerhaps it is something Maurin could tell you more about?",logDesc="Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace."} end
if not DB[1481] then DB[1481]={id=1481,zoneId=405,name="The Corrupter",level=33,minLevel=25,giver="Maurin Bonesplitter",giverType="NPC",giverId=4498,ender="Maurin Bonesplitter",enderType="NPC",enderId=4498,rewardNextId=1482,poiX=-1150,poiY=1884,wowhead="https://www.wowhead.com/wotlk/quest=1481",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I believe I can find this demon lord given the proper reagents.$B$BIf he is indeed as powerful as I suspect, I will need items gathered from deadly creatures. But you act in the Warchief's name, so I am sure you will accept my task.$B$BFirst, I will have to break any wards he has against scrying. For this, I will need the scalp from a satyr--but not any satyr. The scalp must come from a Hatefury shadowstalker.$B$BSearch for them among the ancient ruins in the northeast of Desolace.",logDesc="Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace."} end
if not DB[1482] then DB[1482]={id=1482,zoneId=405,name="The Corrupter",level=35,minLevel=25,giver="Maurin Bonesplitter",giverType="NPC",giverId=4498,ender="Maurin Bonesplitter",enderType="NPC",enderId=4498,poiX=-1150,poiY=1884,wowhead="https://www.wowhead.com/wotlk/quest=1482",image="assets/images/quests/placeholder.png",xpDiff=5,desc="An oracle crystal would do nicely. They are crafted by the naga for their oracles to use.$B$BNorthwest of here, along the coast, is a vast coral reef that the naga have taken as their home when this close to the shore. You can find their oracles there. The Slitherblade are deadly and will not react kindly to your intrusions, so be careful and make haste.$B$BWhen you return, we shall see about finding this demon lord Azrethoc.",logDesc="Bring an Oracle Crystal to Maurin Bonesplitter in Desolace."} end
if not DB[1483] then DB[1483]={id=1483,zoneId=17,name="Ziz Fizziks",level=21,minLevel=16,giver="Sputtervalve",giverType="NPC",giverId=3442,ender="Ziz Fizziks",enderType="NPC",enderId=4201,rewardNextId=1093,poiX=-902,poiY=-3759,wowhead="https://www.wowhead.com/wotlk/quest=1483",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The Venture Company stole many of the best goblin minds, but from time to time, we get the opportunity to steal some back.$b$bA while ago, the Venture Company outfit in the Stonetalon Mountains hired Gerenzo Wrenchwhistle--a gnome! Their other engineer, Ziz Fizziks, was so taken aback by this, he pleaded with me to find him new employment with the Tinkers' Union. I set him on a few tasks, but he might need help.$b$bMaybe you could look in on him for me? He's stationed at the western edge of Windshear Crag.",logDesc="Speak with Ziz Fizziks in Windshear Crag in Stonetalon Mountains."} end
if not DB[1484] then DB[1484]={id=1484,zoneId=405,name="The Corrupter",level=33,minLevel=25,giver="Maurin Bonesplitter",giverType="NPC",giverId=4498,ender="Takata Steelblade",enderType="NPC",enderId=5641,poiX=-1150,poiY=1884,wowhead="https://www.wowhead.com/wotlk/quest=1484",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This creature is far more dangerous than I had anticipated.  No doubt Takata questions my abilities to take on such a creature, and it would insult his honor if he were not informed about what just happened.$B$BSpeak to the swordsman, tell him you are willing to slay the demon if he would allow it, but do not press too hard. It is better if he thinks it his own idea.",logDesc="Speak to Takata Steelblade in Desolace."} end
if not DB[1485] then DB[1485]={id=1485,zoneId=-61,name="Vile Familiars",level=-1,minLevel=1,rewardNextId=1499,wowhead="https://www.wowhead.com/wotlk/quest=1485",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Those warlocks who came before us have earned the distrust of the Horde, and while we are tolerated, we are not loved.$b$bThis has not brought the warlocks closer together, however, as many choose to live reclusively, dabbling in their magics alone. I will not seek to lead you down one path or the other, but only help you in your maturation.$b$bBefore I teach you the art of summoning, bring me six heads of the vile familiars from the cave to the northeast.",logDesc="Bring 6 Vile Familiar Heads to Ruzan."} end
if not DB[1486] then DB[1486]={id=1486,zoneId=718,name="Deviate Hides",level=17,minLevel=13,giver="Nalpak",giverType="NPC",giverId=5767,ender="Nalpak",enderType="NPC",enderId=5767,poiX=-797,poiY=-2037,wowhead="https://www.wowhead.com/wotlk/quest=1486",image="assets/images/quests/placeholder.png",xpDiff=7,money=1800,desc="As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.$b$bThese deviate creatures have strange, otherworldly properties. While evil in nature, it is my opinion that some good can come from their existence here in Kalimdor. I believe their hides will be of particular use in the ways of leatherworking.$b$bIf you feel up to the task, venture into the caves below and retrieve some deviate hides.",logDesc="Nalpak in the Wailing Caverns wants 20 Deviate Hides.",choiceRewards={{id=6480,qty=1},{id=918,qty=1}}} end
if not DB[1487] then DB[1487]={id=1487,zoneId=718,name="Deviate Eradication",level=21,minLevel=15,giver="Ebru",giverType="NPC",giverId=5768,ender="Ebru",enderType="NPC",enderId=5768,poiX=-802,poiY=-2039,wowhead="https://www.wowhead.com/wotlk/quest=1487",image="assets/images/quests/placeholder.png",xpDiff=7,money=2500,desc="Naralex had a noble goal.$b$bOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was. But something went terribly wrong.$b$bNaralex's dream turned into a nightmare and corrupt creatures began to inhabit the caverns.$b$bWhile some Disciples of Naralex seek to awake our master, my concern is with ridding these caves of the evil beasts.$b$bBrave the caverns, $n, and eradicate the deviate spawn.",logDesc="Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.",choiceRewards={{id=6476,qty=1},{id=8071,qty=1},{id=6481,qty=1}}} end
if not DB[1488] then DB[1488]={id=1488,zoneId=405,name="The Corrupter",level=40,minLevel=25,giver="Takata Steelblade",giverType="NPC",giverId=5641,ender="Takata Steelblade",enderType="NPC",enderId=5641,poiX=-1178,poiY=1870,wowhead="https://www.wowhead.com/wotlk/quest=1488",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals.$B$BYou have already shown you wish to aid the Warchief, and I would trust you to gather a party to slay the demon lord and his warlock servant.$B$BWhen you are ready, head directly south,  and return to me when the threat has been ended.",logDesc="Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.",choiceRewards={{id=6746,qty=1},{id=6747,qty=1}}} end
if not DB[1489] then DB[1489]={id=1489,zoneId=718,name="Hamuul Runetotem",level=16,minLevel=10,giver="Tonga Runetotem",giverType="NPC",giverId=3448,ender="Arch Druid Hamuul Runetotem",enderType="NPC",enderId=5769,rewardNextId=1490,poiX=-545,poiY=-2673,wowhead="https://www.wowhead.com/wotlk/quest=1489",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The shells you brought me have a taint, one I have never before seen.  I am certain the water of the Oases is the cause, and I can sense the confusion they cause this land.  It is as if the land dreams and cannot awake.$B$BThe Wailing Caverns must be the source of the taint.  But before you go there, speak with Hamuul Runetotem, the elder druid.  I sent word to him of the happenings in the Barrens.  He is wise, and can offer you counsel.$B$BYou will find him in Thunder Bluff, on the Elder Rise.",logDesc="Speak with Hamuul Runetotem."} end
if not DB[1490] then DB[1490]={id=1490,zoneId=718,name="Nara Wildmane",level=16,minLevel=10,giver="Arch Druid Hamuul Runetotem",giverType="NPC",giverId=5769,ender="Nara Wildmane",enderType="NPC",enderId=5770,rewardNextId=914,poiX=-1049,poiY=-304,wowhead="https://www.wowhead.com/wotlk/quest=1490",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I entered the land of dreams, and dreamed of a cult of druids who dwell in the Wailing Caverns.  I saw that their goals were once noble, but they have lost their way.  They are now servants of the taint seeping through the Barrens.$B$BI am old and my strength fails.  I could not long dwell in that dreaming place and know little more of the tainted druids.  But Nara is young and her spirit is fierce.  She remained in the dreaming when I fled.$B$BSpeak with Nara.  She is in the tent, over yonder.",logDesc="Speak with Nara Wildmane."} end
if not DB[1491] then DB[1491]={id=1491,zoneId=718,name="Smart Drinks",level=18,minLevel=13,giver="Mebok Mizzyrix",giverType="NPC",giverId=3446,ender="Mebok Mizzyrix",enderType="NPC",enderId=3446,poiX=-929,poiY=-3697,wowhead="https://www.wowhead.com/wotlk/quest=1491",image="assets/images/quests/placeholder.png",xpDiff=7,money=1000,desc="Ok, so the raptor horns didn't work so well.  But that's all right -- no one got rich on their first try!  And besides, I think I found something that'll work even better in my smart drinks!$B$BThere is a substance called Wailing Essence, and I think it is the cause of the strange plants and animals in the Barrens.  Get me some and I'll try it in my drink!$B$BI heard the essence gathers in ectoplasmic creatures in the Wailing Caverns to the west.  Hunt those creatures and gather the essence.",logDesc="Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet."} end
if not DB[1492] then DB[1492]={id=1492,zoneId=17,name="Wharfmaster Dizzywig",level=11,minLevel=9,giver="Apothecary Helbrim",giverType="NPC",giverId=3390,ender="Wharfmaster Dizzywig",enderType="NPC",enderId=3453,poiX=-425,poiY=-2590,wowhead="https://www.wowhead.com/wotlk/quest=1492",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I have need to send a crate of potions, reagents and other items to my associates in the Old World. Little time I have to actually see them to the dock at Ratchet, and the last caravan has already left.$b$bIf you could, please take this to Wharfmaster Dizzywig. He will ensure that it is placed on the next boat to Blackwater Cove.",logDesc="Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet."} end
if not DB[1498] then DB[1498]={id=1498,zoneId=-81,name="Path of Defense",level=-1,minLevel=10,giver="Uzzek",giverType="NPC",giverId=5810,ender="Uzzek",enderType="NPC",enderId=5810,rewardNextId=1502,poiX=186,poiY=-3597,wowhead="https://www.wowhead.com/wotlk/quest=1498",image="assets/images/quests/placeholder.png",xpDiff=4,desc="As a warrior, one of our most crucial tasks is... protection.  We are the shield of the Horde, and we keep our weaker brethren safe.  If you are to join in our ranks, then you must prove your mettle to me.$B$BGo to Thunder Ridge in Durotar, where live the lightning hides and thunder lizards.  Hunt the beasts!  Show me you are tougher than they!  Brave their assaults and bring me a stack of their singed scales as proof.$B$BDo this, and then I will teach you.",logDesc="Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens."} end
if not DB[1499] then DB[1499]={id=1499,zoneId=-61,name="Vile Familiars",level=-1,minLevel=1,giver="Ruzan",giverType="NPC",giverId=5765,ender="Zureetha Fargaze",enderType="NPC",enderId=3145,rewardNextId=794,poiX=-624,poiY=-4214,wowhead="https://www.wowhead.com/wotlk/quest=1499",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Zureetha has been sending novices like yourself to help cull the numbers of the creatures in the cave near where you fought the vile familiars.$b$bI think it would be good for you to gain experience by assisting her. Be sure to tell her that you assisted with the imp problem, she'll probably have a reward for you.",logDesc="Speak with Zureetha Fargaze.",choiceRewards={{id=4925,qty=1},{id=5778,qty=1}}} end
if not DB[1500] then DB[1500]={id=1500,zoneId=718,name="Waking Naralex",level=25,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=1500",image="assets/images/quests/placeholder.png"} end
if not DB[1501] then DB[1501]={id=1501,zoneId=-61,name="Creature of the Void",level=-1,minLevel=10,giver="Gan'rul Bloodeye",giverType="NPC",giverId=5875,ender="Gan'rul Bloodeye",enderType="NPC",enderId=5875,rewardNextId=1504,poiX=1850,poiY=-4357,wowhead="https://www.wowhead.com/wotlk/quest=1501",image="assets/images/quests/placeholder.png",xpDiff=5,desc="So few warlocks remain... We risk much, but the risks are warranted. You must quickly reach maturity in your ability if you are to be of use to the Horde and to the Warchief.$b$bIt is time that you learned a new summoning spell.$b$bFirst, you must recover the Tablet of Verga, which was stolen by warlocks of the Burning Blade and is now kept at their lair in Skull Rock to the east of the city. With the tablet, I will show you the runes necessary to summoning a voidwalker.",logDesc="Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar."} end
if not DB[1502] then DB[1502]={id=1502,zoneId=-81,name="Thun'grim Firegaze",level=10,minLevel=10,giver="Uzzek",giverType="NPC",giverId=5810,ender="Thun'grim Firegaze",enderType="NPC",enderId=5878,rewardNextId=1503,poiX=186,poiY=-3597,wowhead="https://www.wowhead.com/wotlk/quest=1502",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It is vital that a warrior's weapon is one of quality.  And if there is an orc who can craft quality weapons, then that orc is Thun'grim Firegaze.  He is a hermit who dwells atop the hills east of the Crossroads.$B$BIf you seek a weapon, warrior, then you should seek Thun'grim.  To find him, first travel to the Crossroads to the west, then strike east into the hills.  His camp is high on a hilltop.",logDesc="Speak with Thun'grim Firegaze in the Barrens."} end
if not DB[1503] then DB[1503]={id=1503,zoneId=-81,name="Forged Steel",level=10,minLevel=10,giver="Thun'grim Firegaze",giverType="NPC",giverId=5878,ender="Thun'grim Firegaze",enderType="NPC",enderId=5878,poiX=-438,poiY=-3176,wowhead="https://www.wowhead.com/wotlk/quest=1503",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I will give you a weapon, $N, but first you must aid me.  The Razormanes to the northwest came into my camp a few nights past.  They would not meet me in combat, but they know my eyes are bad--a few distracted me with snorts while others stole from me!  The cowards!$B$BThey took an iron chest, and within it were some forged steel bars.  If you can recover them then I will give you the weapon you seek.$B$BSearch for the iron box within the quilboar camps, and return with the forged steel bars.",logDesc="Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens.",choiceRewards={{id=7326,qty=1},{id=7328,qty=1},{id=7327,qty=1},{id=7329,qty=1}}} end
if not DB[1504] then DB[1504]={id=1504,zoneId=-61,name="The Binding",level=-1,minLevel=10,giver="Gan'rul Bloodeye",giverType="NPC",giverId=5875,ender="Gan'rul Bloodeye",enderType="NPC",enderId=5875,poiX=1850,poiY=-4357,wowhead="https://www.wowhead.com/wotlk/quest=1504",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Now, observe the Tablet of Verga, for it contains the glyphs you will need for the summoning. Take them to the circle in Neeru Fireblade's tent on the other side of the cavern. There you will be able to call for the voidwalker.$b$bYou must defeat it using whatever physical and magical means you have at your disposal. When this is completed, return to me with the glyphs of summoning and I will demonstrate how you may bind the creature to your will.",logDesc="Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar."} end
if not DB[1505] then DB[1505]={id=1505,zoneId=-81,name="Veteran Uzzek",level=-1,minLevel=10,giver="Krang Stonehoof",giverType="NPC",giverId=3063,ender="Uzzek",enderType="NPC",enderId=5810,rewardNextId=1498,poiX=-2348,poiY=-496,wowhead="https://www.wowhead.com/wotlk/quest=1505",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Horde honors its warriors because their strength is unquestioned.  But the truly great warriors are great students as well.$B$BSeek out Uzzek.  He is a veteran of many battles and now instructs young warriors in the ways of combat.  You will find him south of Far Watch Post, the orc garrison on the border of the Barrens and Durotar.",logDesc="Speak with Uzzek at Far Watch Post in the Barrens."} end
if not DB[1506] then DB[1506]={id=1506,zoneId=-61,name="Gan'rul's Summons",level=-1,minLevel=10,giver="Ophek",giverType="NPC",giverId=3294,ender="Gan'rul Bloodeye",enderType="NPC",enderId=5875,rewardNextId=1501,poiX=353,poiY=-4837,wowhead="https://www.wowhead.com/wotlk/quest=1506",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You there. $n, right?$b$bI hope your schedule isn't busy, because Gan'rul wants to see you right away. You'll find him with the senior warlocks in the Cleft of Shadow.$b$bBased on my past dealings with Gan'rul, your summons is either a very good thing or a very bad thing.",logDesc="Speak with Gan'rul Bloodeye in Orgrimmar."} end
if not DB[1507] then DB[1507]={id=1507,zoneId=-61,name="Devourer of Souls",level=-1,minLevel=20,giver="Gan'rul Bloodeye",giverType="NPC",giverId=5875,ender="Cazul",enderType="NPC",enderId=5909,rewardNextId=1508,poiX=1850,poiY=-4357,wowhead="https://www.wowhead.com/wotlk/quest=1507",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The time has come for you to learn more of the summoning magics. You will learn to summon a succubus, a creature of incredible mental powers. It can lull those of weak minds into its servitude--but have no fear! I feel certain that you will be equal to the challenge.$b$bA succubus can only be summoned when baited with an item that represents great devotion and love. I leave it to you to find such an object.$b$bA suggestion? Speak with Cazul... There seems to be little the ancient warlock does not know.",logDesc="Speak with Cazul in the Cleft of Shadow."} end
if not DB[1508] then DB[1508]={id=1508,zoneId=-61,name="Blind Cazul",level=-1,minLevel=20,giver="Cazul",giverType="NPC",giverId=5909,ender="Zankaja",enderType="NPC",enderId=5910,rewardNextId=1509,poiX=1840,poiY=-4341,wowhead="https://www.wowhead.com/wotlk/quest=1508",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hmm... But, of course, that is not why you have come to speak with me.$b$bIf Gan'rul has sent you to me, it must be that you are to summon a succubus, and need an object to use for enticement.$b$bHmm... If you trust a blind man to lead you, $n, then listen. In the bluffs of Orgrimmar, west of the wind rider tower, lives Zankaja. She waits for the return of her mate.$b$bGo to her.",logDesc="Speak with Zankaja in Orgrimmar."} end
if not DB[1509] then DB[1509]={id=1509,zoneId=-61,name="News of Dogran",level=-1,minLevel=20,giver="Zankaja",giverType="NPC",giverId=5910,ender="Gazrog",enderType="NPC",enderId=3464,rewardNextId=1510,poiX=1718,poiY=-4200,wowhead="https://www.wowhead.com/wotlk/quest=1509",image="assets/images/quests/placeholder.png",xpDiff=2,desc="My mate, Dogran, was recently sent to the Crossroads for duty. It was a promotion, and he was very proud.$b$bI was sad, of course, but I didn't let him know that. And worried, too. The Barrens is a more dangerous place than Orgrimmar, and I feared the worst.$b$bNow it's been a week after he should have returned, and I have received no word from him...$b$bPerhaps you could go to the Crossroads and see if they have any news? He worked with Gazrog, who should still be stationed there.",logDesc="Speak with Gazrog at the Crossroads."} end
if not DB[1510] then DB[1510]={id=1510,zoneId=-61,name="News of Dogran",level=-1,minLevel=20,giver="Gazrog",giverType="NPC",giverId=3464,ender="Ken'zigla",enderType="NPC",enderId=4197,rewardNextId=1511,poiX=-436,poiY=-2639,wowhead="https://www.wowhead.com/wotlk/quest=1510",image="assets/images/quests/placeholder.png",xpDiff=3,desc="He was stationed at Camp Taurajo, where we've been trying to weed out the quilboar. He led a few grunts to one of their camps, where he was hurt bad. The others made it back and tried to rescue him. He was in bad shape, his wounds festered, so they were afraid to move him without patching him up first.$b$bThey sent a message here, requesting a healing draught from the trolls at the Malaka'jin at the base of the Stonetalon Mountains. We sent someone to get it, but they haven't returned yet.",logDesc="Speak with Ken'zigla at the Malaka'jin."} end
if not DB[1511] then DB[1511]={id=1511,zoneId=-61,name="Ken'zigla's Draught",level=-1,minLevel=20,giver="Ken'zigla",giverType="NPC",giverId=4197,ender="Grunt Logmar",enderType="NPC",enderId=5911,rewardNextId=1515,poiX=-181,poiY=-331,wowhead="https://www.wowhead.com/wotlk/quest=1511",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I figured there might be another coming to get the draught, so I prepared it anyways.$b$bHere you go, $n. Mind you, you should only give half of it to him! That will give him enough strength to move without bleeding himself dry. Wait a night, then give him the other half.$b$bAnyways, you'll want to bring this to Logmar at Camp Taurajo. From what the first one told me, he should have an idea where this Dogran is.",logDesc="Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo."} end
if not DB[1512] then DB[1512]={id=1512,zoneId=-61,name="Love's Gift",level=-1,minLevel=20,giver="Grunt Dogran",giverType="NPC",giverId=5908,ender="Gan'rul Bloodeye",enderType="NPC",enderId=5875,rewardNextId=1513,poiX=-1623,poiY=-1765,wowhead="https://www.wowhead.com/wotlk/quest=1512",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Zankaja is young and beautiful. To be chained to an invalid... I will not allow her to suffer that injustice.$b$bLeave me, $n. And thank you. I may end my life in glorious battle, instead of a lifeless husk.$b$bAnd please, I would ask you not to tell my mate of this... I do not want guilt on her conscience.",logDesc="Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar."} end
if not DB[1513] then DB[1513]={id=1513,zoneId=-61,name="The Binding",level=-1,minLevel=20,giver="Gan'rul Bloodeye",giverType="NPC",giverId=5875,ender="Gan'rul Bloodeye",enderType="NPC",enderId=5875,poiX=1850,poiY=-4357,wowhead="https://www.wowhead.com/wotlk/quest=1513",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Take this to the summoning circle in Neeru's tent, $n. Summon forth a foul succubus, then show it your mastery. I believe in the strength of your magic. As always, though, be wary, for pride and overconfidence has overcome many a promising warlock.$b$bWhen you have defeated it, return the pendant to me so that I might deliver the news to Zankaja.",logDesc="Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar.",rewards={{id=22243,qty=1}}} end
if not DB[1514] then DB[1514]={id=1514,zoneId=361,name="Corrupted Windblossom",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=1514",image="assets/images/quests/placeholder.png"} end
if not DB[1515] then DB[1515]={id=1515,zoneId=-61,name="Dogran's Captivity",level=-1,minLevel=20,giver="Grunt Logmar",giverType="NPC",giverId=5911,ender="Grunt Dogran",enderType="NPC",enderId=5908,rewardNextId=1512,poiX=-2392,poiY=-1899,wowhead="https://www.wowhead.com/wotlk/quest=1515",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You've made it this far, so if you want to see this through to the end, I won't stop you. I can't spare you any additional manpower though, you'll be on your own.$b$bDogran is being held in a quilboar camp to the north of here. Look for a group of two huts. He'll be heavily guarded--that is, if they haven't killed him yet, or he hasn't succumbed to his wounds.$b$bGood luck.",logDesc="Bring Ken'zigla's Draught to Dogran in the Barrens."} end
if not DB[1516] then DB[1516]={id=1516,zoneId=-82,name="Call of Earth",level=4,minLevel=4,giver="Canaga Earthcaller",giverType="NPC",giverId=5887,ender="Canaga Earthcaller",enderType="NPC",enderId=5887,poiX=-630,poiY=-4205,wowhead="https://www.wowhead.com/wotlk/quest=1516",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The time is now, young $c. You've grown strong and your spirit endures like the earth. Following the shaman's path shows you have wisdom before even proving yourself.$B$BThe element of earth will guide your destiny, becoming part of you if you are ready. But you must stand before the earth itself. If you are ready, then you will see things only shaman know of.$B$BSeek out the Felstalkers to the north, and take from them two of their hooves. Return to me then, and we shall speak more of your future.$B",logDesc="Bring 2 Felstalker Hooves to Canaga Earthcaller in the Valley of Trials."} end
if not DB[1517] then DB[1517]={id=1517,zoneId=-82,name="Call of Earth",level=4,minLevel=4,giver="Canaga Earthcaller",giverType="NPC",giverId=5887,ender="Minor Manifestation of Earth",enderType="NPC",enderId=5891,poiX=-630,poiY=-4205,wowhead="https://www.wowhead.com/wotlk/quest=1517",image="assets/images/quests/placeholder.png",xpDiff=4,desc="A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.$B$BThe sapta is always drunk in a holy place, and never anywhere else--remember that.$B$BSeek out Spirit Rock southwest of here--it is found at the end of the Hidden Path. Drink your sapta there, and... well, you shall see.",logDesc="Find Spirit Rock and drink the Earth Sapta."} end
if not DB[1518] then DB[1518]={id=1518,zoneId=-82,name="Call of Earth",level=4,minLevel=4,giver="Minor Manifestation of Earth",giverType="NPC",giverId=5891,ender="Canaga Earthcaller",enderType="NPC",enderId=5887,poiX=-878,poiY=-4290,wowhead="https://www.wowhead.com/wotlk/quest=1518",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Take this rough quartz from me and bring it to Canaga Earthcaller as proof of our meeting. He will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.$B$BBe patient, $N. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.",logDesc="Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials.",rewards={{id=5175,qty=1}}} end
if not DB[1519] then DB[1519]={id=1519,zoneId=-82,name="Call of Earth",level=4,minLevel=4,giver="Seer Ravenfeather",giverType="NPC",giverId=5888,ender="Seer Ravenfeather",enderType="NPC",enderId=5888,poiX=-2882,poiY=-250,wowhead="https://www.wowhead.com/wotlk/quest=1519",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The time has come, young $c. Your body ages and grows strong, and your spirit endures like the earth. I see it within you-you have wisdom already.$B$BThe earth guides our people, and it speaks to us, as it will to you in time. But you must be tested. If you are ready, then you shall see things only our kind know of.$B$BSeek out the Bristleback shamans in their ravine to the east, and take from them a salve they use in their rituals. Return to me only when you have enough for your own potion.",logDesc="Bring 2 applications of Ritual Salve to Seer Ravenfeather in Camp Narache."} end
if not DB[1520] then DB[1520]={id=1520,zoneId=-82,name="Call of Earth",level=4,minLevel=4,giver="Seer Ravenfeather",giverType="NPC",giverId=5888,ender="Minor Manifestation of Earth",enderType="NPC",enderId=5891,poiX=-2882,poiY=-250,wowhead="https://www.wowhead.com/wotlk/quest=1520",image="assets/images/quests/placeholder.png",xpDiff=3,desc="A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the open minded to see the elements as no one has seen them before. Your spirit will forever be tied to the element the sapta was created for, and only a select few of our kind know the secrets of its creation.$B$BThe sapta is always imbibed in a holy place, and never anywhere else.$B$BSeek out the shaman shrine to the east of here and drink of the sapta.",logDesc="Find Kodo Rock and drink the Earth Sapta."} end
if not DB[1521] then DB[1521]={id=1521,zoneId=-82,name="Call of Earth",level=4,minLevel=4,giver="Minor Manifestation of Earth",giverType="NPC",giverId=5891,ender="Seer Ravenfeather",enderType="NPC",enderId=5888,poiX=-878,poiY=-4290,wowhead="https://www.wowhead.com/wotlk/quest=1521",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Take this rough quartz from me and bring it to Seer Ravenfeather as proof of our meeting. She will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast mountains.$B$BBe patient, $N. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.",logDesc="Bring the Rough Quartz to Seer Ravenfeather in Camp Narache.",rewards={{id=5175,qty=1}}} end
if not DB[1522] then DB[1522]={id=1522,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Searn Firewarder",giverType="NPC",giverId=5892,ender="Kranal Fiss",enderType="NPC",enderId=5907,rewardNextId=1524,poiX=1921,poiY=-4213,wowhead="https://www.wowhead.com/wotlk/quest=1522",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Fire be witcha, mon. I see you be strong in da ways of earth already, an' me tinkin' you be ready to talk to Kranal.$B$BKranal live north of da Crossroads in da Barrens. He be strong in da ways of da elements and can teach ya da ways of fire... if you tink you be ready.$B$BHe be easy ta find, just don' go too far--ya go too far an' ya find yerself in da elves' lands.",logDesc="Find Kranal Fiss in the Barrens."} end
if not DB[1523] then DB[1523]={id=1523,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Beram Skychaser",giverType="NPC",giverId=3032,ender="Kranal Fiss",enderType="NPC",enderId=5907,rewardNextId=1524,poiX=-981,poiY=287,wowhead="https://www.wowhead.com/wotlk/quest=1523",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.$B$BSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.",logDesc="Find Kranal Fiss in the Barrens."} end
if not DB[1524] then DB[1524]={id=1524,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Kranal Fiss",giverType="NPC",giverId=5907,ender="Telf Joolam",enderType="NPC",enderId=5900,rewardNextId=1525,poiX=269,poiY=-3055,wowhead="https://www.wowhead.com/wotlk/quest=1524",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You are powerful enough to wield the totem of fire, but that does not mean you are ready.$B$BAlong the Southfury River in Durotar, before the Great Sea, lies a hidden trail to one of the highest peaks in the land. Find your way to the top and you shall find one of our holy shrines watched over by Telf Joolam--the Shrine of the Dormant Flame.$B$BTake this torch to him--it marks that you attempt to tame fire. Return it to me aflame by the brazier at the shrine and I will see you are given the totem of fire.",logDesc="Bring the Torch of the Dormant Flame to Telf Joolam in Durotar."} end
if not DB[1525] then DB[1525]={id=1525,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Telf Joolam",giverType="NPC",giverId=5900,ender="Telf Joolam",enderType="NPC",enderId=5900,rewardNextId=1526,poiX=-270,poiY=-4001,wowhead="https://www.wowhead.com/wotlk/quest=1525",image="assets/images/quests/placeholder.png",xpDiff=5,desc="But you did not come here for a history lesson, did you? You came for the Eternal Flame and fire totem.$B$BThe first step is to create a sapta and bind you to the flame.$B$BI can create the fire sapta for you if you bring me two items. The first is fire tar, a simple item usually carried by Razormane spellcasters in eastern Barrens.$B$BThe second item will be more dangerous: a reagent pouch from one of the cultists of the Burning Blade. You can find them in a cave above the ravines northeast of Razor Hill.",logDesc="Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar.",rewards={{id=6636,qty=1}}} end
if not DB[1526] then DB[1526]={id=1526,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Telf Joolam",giverType="NPC",giverId=5900,rewardNextId=1527,poiX=-270,poiY=-4001,wowhead="https://www.wowhead.com/wotlk/quest=1526",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The fire sapta is finished. The time has come for you to face the flame. Use the sapta at the shrine and head to the top of the mountain to face the manifestation there. He will not attack until you are ready, but he will realize you are able to see him.$B$BStrike him down swiftly, $N, for he shall only grow in power the longer you take to slay him. Once he is defeated, place his glowing embers within the brazier and light the torch.",logDesc="Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.",rewards={{id=6654,qty=1}}} end
if not DB[1527] then DB[1527]={id=1527,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,ender="Kranal Fiss",enderType="NPC",enderId=5907,wowhead="https://www.wowhead.com/wotlk/quest=1527",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Torch firmly in hand, you turn away from the brazier and look out over Durotar. You feel an excitement tugging at your spirit as the wind picks up and forces the flame to dance violently.$B$BYou start off down the path back to the Barrens in search of Kranal Fiss.",logDesc="Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens.",rewards={{id=5176,qty=1}}} end
if not DB[1528] then DB[1528]={id=1528,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Searn Firewarder",giverType="NPC",giverId=5892,ender="Islen Waterseer",enderType="NPC",enderId=5901,rewardNextId=1530,poiX=1921,poiY=-4213,wowhead="https://www.wowhead.com/wotlk/quest=1528",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Water be in ya future, mon. I see you be strong in da ways of fire already, an' me tinkin' you be ready to talk to Islen.$B$BIslen live along the coast of da Barrens. If ya head south along the Southfury River, ya canna miss her--look fer da big shark! She be strong in da ways of da elements and can teach ya da ways of water... if you tink you be ready.$B$BShe be easy ta find, just don' go too far south--she be jus' beyond Ratchet.",logDesc="Find Islen Waterseer in the Barrens."} end
if not DB[1529] then DB[1529]={id=1529,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Xanis Flameweaver",giverType="NPC",giverId=5906,ender="Islen Waterseer",enderType="NPC",enderId=5901,rewardNextId=1530,poiX=-993,poiY=254,wowhead="https://www.wowhead.com/wotlk/quest=1529",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.$B$BSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, $N.",logDesc="Find Islen Waterseer in the Barrens."} end
if not DB[1530] then DB[1530]={id=1530,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Islen Waterseer",giverType="NPC",giverId=5901,ender="Brine",enderType="NPC",enderId=5899,rewardNextId=1535,poiX=-1345,poiY=-4048,wowhead="https://www.wowhead.com/wotlk/quest=1530",image="assets/images/quests/placeholder.png",xpDiff=2,desc="If there is one lesson you must learn of water, it is this: water means rebirth.$B$BIts power flows, erodes, and makes clean all manner of things. You will find its ability to heal and replenish incomparable, but only when it is pure.$B$BWhen you understand that water, when polluted, can devastate all that it touches, you will appreciate how vital a resource it is.$B$BIf you wish the water sapta, find Brine deep in Southern Barrens. Her home is continually molested by the quilboar there.",logDesc="Find Brine at Blackthorn Ridge in Southern Barrens."} end
if not DB[1531] then DB[1531]={id=1531,zoneId=-82,name="Call of Air",level=-1,minLevel=30,giver="Searn Firewarder",giverType="NPC",giverId=5892,ender="Prate Cloudseer",enderType="NPC",enderId=5905,poiX=1921,poiY=-4213,wowhead="https://www.wowhead.com/wotlk/quest=1531",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You be makin' headway now, mon. Your be ready to prove yerself worthy of the air totem, but first, ya must fin' Prate Cloudseer in Thousand Needles. She be willin' ta tell ya how to get yer air totem if ya treat her wit enough respect.$B$BHead south through the Barrens, and after ya reach Thousand Needles, head east. You'll find her hiddin' in a hole wit' her boyfriend--haha, don' tell her I be dissin' her none--she not take it too kindly.",logDesc="Find Prate Cloudseer in Thousand Needles.",rewards={{id=5178,qty=1}}} end
if not DB[1532] then DB[1532]={id=1532,zoneId=-82,name="Call of Air",level=-1,minLevel=30,giver="Xanis Flameweaver",giverType="NPC",giverId=5906,ender="Prate Cloudseer",enderType="NPC",enderId=5905,poiX=-993,poiY=254,wowhead="https://www.wowhead.com/wotlk/quest=1532",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The winds of Kalimdor rush to meet you and you shall be counted among some of our most powerful $g brothers:sisters;. I am proud to see you have come this far and have such a promising future.$B$BThe element of air is a difficult one to control, but I have faith that your skills will overcome any obstacles that are placed in front of you.$B$BHead to the very south of the Barrens, and enter Thousand Needles. It is there, far to the east, that you will find Prate Cloudseer. She will teach you more.",logDesc="Find Prate Cloudseer in Thousand Needles.",rewards={{id=5178,qty=1}}} end
if not DB[1533] then DB[1533]={id=1533,zoneId=-82,name="<NYI> Call of Air",level=30,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1533",image="assets/images/quests/placeholder.png"} end
if not DB[1534] then DB[1534]={id=1534,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Brine",giverType="NPC",giverId=5899,ender="Brine",enderType="NPC",enderId=5899,rewardNextId=220,poiX=-3618,poiY=-1777,wowhead="https://www.wowhead.com/wotlk/quest=1534",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Take this waterskin and head deep into the lush forest the night elves call Ashenvale. It is to the far north of the Barrens.$B$BOnce you've entered the forest, travel west. Along the mountains that separate Stonetalon and Ashenvale, and beyond Lake Mystral, you will find a holy place: the Ruins of Stardust. At the center of the lake you will find a small fountain.$B$BBring me a sample of the fountain's water. It will be the final component you'll need before I send you back to Islen.",logDesc="Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens."} end
if not DB[1535] then DB[1535]={id=1535,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Brine",giverType="NPC",giverId=5899,ender="Brine",enderType="NPC",enderId=5899,rewardNextId=1536,poiX=-3618,poiY=-1777,wowhead="https://www.wowhead.com/wotlk/quest=1535",image="assets/images/quests/placeholder.png",xpDiff=3,desc="To find understanding and gain the sapta from me, you must seek out only the purest forms of water. As you fetch the samples for me, take note of your surroundings. Be aware of the creatures that rely on the water, that protect it. See how it affects forests and deserts. Witness how the very substance that sustains life will force creatures to take lives.$B$BWe shall start with a simple task: down below my hut there is a pond of the precious liquid. Fill this skin with it and return to me.",logDesc="Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens."} end
if not DB[1536] then DB[1536]={id=1536,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Brine",giverType="NPC",giverId=5899,ender="Brine",enderType="NPC",enderId=5899,rewardNextId=1534,poiX=-3618,poiY=-1777,wowhead="https://www.wowhead.com/wotlk/quest=1536",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Long ago I followed some companions into the Hillsbrad Foothills. We defended ourselves from some tenacious humans who make their home there and we found ourselves in a small town the Forsaken had taken over: Tarren Mill.$B$BIt was there I found a most peculiar thing: in the center of town was a small well of fresh spring water. I'm not sure the plagued citizens of the town even realize its value--it's a small holy vestige in an unhallowed sea.$B$BBring me a sample of that water in this waterskin.",logDesc="Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens."} end
if not DB[1537] then DB[1537]={id=1537,zoneId=-82,name="<NYI> Call of Air",level=30,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1537",image="assets/images/quests/placeholder.png"} end
if not DB[1538] then DB[1538]={id=1538,zoneId=-82,name="<NYI> Call of Air",level=30,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1538",image="assets/images/quests/placeholder.png"} end
if not DB[1558] then DB[1558]={id=1558,zoneId=-284,name="The Stonewrought Dam",level=-1,minLevel=10,ender="Human Orphan",enderType="NPC",enderId=14305,wowhead="https://www.wowhead.com/wotlk/quest=1558",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Ironforge is where all the dwarves and gnomes live.  Near there is a place called Loch Modan, and the dwarves built a HUGE dam there.  They say it's one of the biggest things anyone's ever made.  Wow!$B$BCould you take me to Loch Modan and see the dam there, please?  I think it is the Stone... um... Stonewrench Dam?  Stonewrought?  It's big - that's for sure.  I'd like to look out over the big waterfall.  I promise I won't lean over too far!",logDesc="Take the orphan to the Stonewrought Dam in Loch Modan.  You should take him to the middle of the dam so he can see out over the giant waterfall."} end
if not DB[1559] then DB[1559]={id=1559,zoneId=-201,name="Flash Bomb Recipe",level=37,minLevel=30,giver="Rigglefuzz",giverType="NPC",giverId=2817,ender="Rigglefuzz",enderType="NPC",enderId=2817,poiX=-6767,poiY=-3134,wowhead="https://www.wowhead.com/wotlk/quest=1559",image="assets/images/quests/placeholder.png",rewards={{id=6672,qty=1}}} end
if not DB[1560] then DB[1560]={id=1560,zoneId=440,name="Tooga's Quest",level=50,minLevel=40,giver="Tooga",giverType="NPC",giverId=5955,ender="Torta",enderType="NPC",enderId=6015,poiX=-9286,poiY=-2413,wowhead="https://www.wowhead.com/wotlk/quest=1560",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I am so lost!$b$bMy wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere.$b$bWould you be so kind as to lead me back to Torta? She's waiting for me just south of Steamwheedle Port.",logDesc="Show Tooga the way back to his wife, Torta.",choiceRewards={{id=9638,qty=1},{id=9642,qty=1}}} end
if not DB[1578] then DB[1578]={id=1578,zoneId=-121,name="Supplying the Front",level=12,minLevel=1,giver="Tormus Deepforge",giverType="NPC",giverId=6031,ender="Thorvald Deepforge",enderType="NPC",enderId=6030,poiX=-4793,poiY=-1098,wowhead="https://www.wowhead.com/wotlk/quest=1578",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The mountaineers of Loch Modan are fighting troggs, and having a busy time of it!  They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs.$B$BThat's why my colleague Thorvald is there, trying to keep the mountaineers in good gear.  So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged.  He might even share his knowledge with you.$B$BThorvald is in Loch Modan's southern guard tower.",logDesc="Bring 6 Copper Axes and 6 Copper Chain Belts to Thorvald in the southern guard tower of Loch Modan.",rewards={{id=33792,qty=1}}} end
if not DB[1579] then DB[1579]={id=1579,zoneId=-101,name="Gaffer Jacks",level=12,minLevel=10,giver="Wizbang Cranktoggle",giverType="NPC",giverId=3666,ender="Wizbang Cranktoggle",enderType="NPC",enderId=3666,rewardNextId=1580,poiX=6406,poiY=520,wowhead="https://www.wowhead.com/wotlk/quest=1579",image="assets/images/quests/placeholder.png",xpDiff=3,money=250,desc="I came to Auberdine because of the quiet.  I want to invent my inventions where it's quiet, because after a night of drinking I don't like all the noise of Ironforge!$B$BSo I took a ship to Auberdine and had a little too much to drink on the way.  I dropped my box of gaffer jacks overboard!  I need my gaffer jacks!$B$BI don't know exactly where I dropped them, but if you fish for them in the ocean you might get lucky...",logDesc="Bring 8 Gaffer Jacks to Wizbang Cranktoggle in Auberdine."} end
if not DB[1580] then DB[1580]={id=1580,zoneId=-101,name="Electropellers",level=12,minLevel=10,giver="Wizbang Cranktoggle",giverType="NPC",giverId=3666,ender="Wizbang Cranktoggle",enderType="NPC",enderId=3666,poiX=6406,poiY=520,wowhead="https://www.wowhead.com/wotlk/quest=1580",image="assets/images/quests/placeholder.png",xpDiff=5,money=500,desc="We know you're lucky, but... just how lucky are you, $N?$B$BOne night I was wandering the roads of Darkshore.  I was looking for a good river or lake to try my new self-propelled, exploding duck decoy and I think I was a little tipsy... because I passed out and awoke hours later in Auberdine.  My hair was singed and my bag of electropellers was gone!  I must have dropped them in the water!$B$BI need those electropellers!  Maybe you can fish them out of some lake or stream in Darkshore...",logDesc="Bring 12 Electropellers to Wizbang Cranktoggle in Auberdine.",rewards={{id=6811,qty=20}}} end
if not DB[1581] then DB[1581]={id=1581,zoneId=-181,name="Elixirs for the Bladeleafs",level=8,minLevel=4,giver="Syral Bladeleaf",giverType="NPC",giverId=2083,ender="Syral Bladeleaf",enderType="NPC",enderId=2083,poiX=9872,poiY=959,wowhead="https://www.wowhead.com/wotlk/quest=1581",image="assets/images/quests/placeholder.png",xpDiff=5,money=225,desc="Our herb and alchemy shop is booming, but my husband spends so much time mixing potions that we never have time for each other.$B$BCan you help us?$B$BIf you can bring me a supply of pre-made elixirs, then I would be happy to trade with you.  I have some rare herbs that you might find useful.",logDesc="Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar.",rewards={{id=2449,qty=6},{id=785,qty=6}}} end
if not DB[1582] then DB[1582]={id=1582,zoneId=-182,name="Moonglow Vest",level=18,minLevel=8,giver="Lotherias",giverType="NPC",giverId=6034,ender="Lotherias",enderType="NPC",enderId=6034,poiX=10082,poiY=2257,wowhead="https://www.wowhead.com/wotlk/quest=1582",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We in Darnassus, especially we craftsman, are quite busy.  Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies.$B$BIf you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.",logDesc="Bring 1 Embossed Leather Gloves, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus.",rewards={{id=6710,qty=1}}} end
if not DB[1598] then DB[1598]={id=1598,zoneId=-61,name="The Stolen Tome",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=1598",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You there! $n, right?$b$bI hope you're sure about becoming a warlock, because if you can't hold your own, you're likely to get pulled under.$b$bI'm to teach you, but I need to make sure you're strong enough first.$b$bThere was a novice studying at the Abbey who ran off to join the Defias Brotherhood. Why do I care? Well, he stole some important books.$b$bOne of those happens to be a book I've wanted for myself, the Powers of the Void. Steal it for me, they have it hidden at their tent in the Vineyards.",logDesc="Retrieve the Powers of the Void for Drusilla La Salle."} end
if not DB[1599] then DB[1599]={id=1599,zoneId=-61,name="Beginnings",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=1599",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You must be the new warlock everyone's been whispering about. Must be someone's taken a liking to you if they've asked me to take time away from my research to start your training.$b$bDon't worry, I won't hold it against you.$b$bThe simplest of the summoning spells you will learn is that of the imp. Before I impart this to you, however, you must prove that you have the necessary magical and physical ability.$b$bBring me three feather charms from the frostmane novices from the cave to the southwest.",logDesc="Bring 3 Feather Charms to Alamar Grimm in Anvilmar."} end
if not DB[1618] then DB[1618]={id=1618,zoneId=-121,name="Gearing Redridge",level=16,minLevel=1,giver="Tormus Deepforge",giverType="NPC",giverId=6031,ender="Verner Osgood",enderType="NPC",enderId=415,poiX=-4793,poiY=-1098,wowhead="https://www.wowhead.com/wotlk/quest=1618",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We dwarves aren't the only ones fighting.  Our human allies have their hands full too!$B$BRedridge is under periodic attack from blackrock orcs, and their supply of equipment is always low.  If you were to help them out, I'm sure their resident blacksmith, Verner Osgood, would teach you a trick or two.",logDesc="Tormus Deepforge wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge.",rewards={{id=6735,qty=1}}} end
if not DB[1638] then DB[1638]={id=1638,zoneId=-81,name="A Warrior's Training",level=-1,minLevel=10,giver="Lyria Du Lac",giverType="NPC",giverId=913,ender="Harry Burlguard",enderType="NPC",enderId=6089,rewardNextId=1639,poiX=-9462,poiY=109,wowhead="https://www.wowhead.com/wotlk/quest=1638",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You've shown yourself to be a competent warrior, $N.  But you're still young and have a lot to learn.$B$BSpeak with Harry Burlguard--he's usually in the Pig and Whistle tavern, in the Old Town of Stormwind.  Harry is an old veteran and a good teacher.  He can show you a few moves that'll keep you breathing longer.",logDesc="Speak with Harry Burlguard in Stormwind."} end
if not DB[1639] then DB[1639]={id=1639,zoneId=-81,name="Bartleby the Drunk",level=-1,minLevel=10,giver="Harry Burlguard",giverType="NPC",giverId=6089,ender="Bartleby",enderType="NPC",enderId=6090,rewardNextId=1640,poiX=-8613,poiY=383,wowhead="https://www.wowhead.com/wotlk/quest=1639",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Yeah, I can teach you.  But first I wanna see what moves you have already.$B$BSee that drunk over there at the end of the bar?  Bartleby?  I want you to get his mug.$B$BHah, and if you know Bartleby then you know he won't just give it to you.",logDesc="Speak with Bartleby."} end
if not DB[1640] then DB[1640]={id=1640,zoneId=-81,name="Beat Bartleby",level=-1,minLevel=10,giver="Bartleby",giverType="NPC",giverId=6090,ender="Bartleby",enderType="NPC",enderId=6090,rewardNextId=1665,poiX=-8604,poiY=389,wowhead="https://www.wowhead.com/wotlk/quest=1640",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You want what??  You're crazy!$B$BThe only way you'll get this mug is if you pry it from my cold, dead fingers...",logDesc="Beat Bartleby, then talk to him."} end
if not DB[1641] then DB[1641]={id=1641,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Duthorian Rall",giverType="NPC",giverId=6171,ender="Duthorian Rall",enderType="NPC",enderId=6171,poiX=-8546,poiY=846,wowhead="https://www.wowhead.com/wotlk/quest=1641",image="assets/images/quests/placeholder.png",rewards={{id=6775,qty=1}}} end
if not DB[1642] then DB[1642]={id=1642,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,ender="Duthorian Rall",enderType="NPC",enderId=6171,rewardNextId=1643,wowhead="https://www.wowhead.com/wotlk/quest=1642",image="assets/images/quests/placeholder.png",xpDiff=1,desc="In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.$B$BAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.$B$BKnow this well, and never forget it.",logDesc="Speak to Duthorian Rall in Stormwind."} end
if not DB[1643] then DB[1643]={id=1643,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Duthorian Rall",giverType="NPC",giverId=6171,ender="Stephanie Turner",enderType="NPC",enderId=6174,rewardNextId=1644,poiX=-8546,poiY=846,wowhead="https://www.wowhead.com/wotlk/quest=1643",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Your task then, $N, is to find someone here in Stormwind that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.$B$BDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light.",logDesc="Search the Trade District of Stormwind for Stephanie Turner."} end
if not DB[1644] then DB[1644]={id=1644,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Stephanie Turner",giverType="NPC",giverId=6174,ender="Stephanie Turner",enderType="NPC",enderId=6174,rewardNextId=1780,poiX=-8832,poiY=614,wowhead="https://www.wowhead.com/wotlk/quest=1644",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Bless their hearts, most of them have no families because of the Scourge attacks in the last decade.$B$BMy husband John collects the materials for me to make the shirts and pants for the children, but I haven't even had time to do that. I've been too focused on keeping food on their plates, and a roof over their heads.$B$BWhat's that? You'd be willing to help? Oh, thank the Light, and thank you, $N.$B$BIf you could bring me some linen cloth so I can sew clothes for the kids, that would help me out so much.",logDesc="Bring 10 Linen Cloth to Stephanie Turner in Stormwind."} end
if not DB[1645] then DB[1645]={id=1645,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Tiza Battleforge",giverType="NPC",giverId=6179,ender="Tiza Battleforge",enderType="NPC",enderId=6179,poiX=-4634,poiY=-932,wowhead="https://www.wowhead.com/wotlk/quest=1645",image="assets/images/quests/placeholder.png",rewards={{id=6916,qty=1}}} end
if not DB[1646] then DB[1646]={id=1646,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,ender="Tiza Battleforge",enderType="NPC",enderId=6179,rewardNextId=1647,wowhead="https://www.wowhead.com/wotlk/quest=1646",image="assets/images/quests/placeholder.png",xpDiff=1,desc="In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.$B$BAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.$B$BKnow this well, and never forget it.",logDesc="Speak to Tiza Battleforge in Ironforge."} end
if not DB[1647] then DB[1647]={id=1647,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Tiza Battleforge",giverType="NPC",giverId=6179,ender="John Turner",enderType="NPC",enderId=6175,rewardNextId=1648,poiX=-4634,poiY=-932,wowhead="https://www.wowhead.com/wotlk/quest=1647",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Your task then, $N, is to find someone here in Ironforge that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.$B$BDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light. I will remain here in the temple for your return. Other paladins will need my guidance also.",logDesc="Search the outer ring of Ironforge for John Turner."} end
if not DB[1648] then DB[1648]={id=1648,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="John Turner",giverType="NPC",giverId=6175,ender="John Turner",enderType="NPC",enderId=6175,rewardNextId=1778,poiX=-4896,poiY=-898,wowhead="https://www.wowhead.com/wotlk/quest=1648",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My wife and I run an orphanage in Stormwind, mostly for children who have lost parents due to the attacks by the Scourge in the last decade. I come to Ironforge every month or so to see about collecting more supplies from the citizens here, and talk to the various groups to see if they can do anything to help.$B$BThis trip's been agonizingly slow, and not very productive.$B$BIf I could just get some more linen for my wife to make some clothes, I could finally send a shipment home.",logDesc="Bring 10 Linen Cloth to John Turner in Ironforge."} end
if not DB[1649] then DB[1649]={id=1649,zoneId=-141,name="The Tome of Valor",level=-1,minLevel=20,ender="Duthorian Rall",enderType="NPC",enderId=6171,rewardNextId=1650,wowhead="https://www.wowhead.com/wotlk/quest=1649",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Valor, and all the virtues that go along with it, are like rare minerals: you must cherish them when you find them because of their value, but you must also take time to harvest them... refine them. When mixed together properly, a strong alloy is formed, sometimes unbreakable by even the most powerful blows.$B$BThis strength, your faith, your bravery, must be tested. You must learn to never lose faith and realize that with the power of the Light, you can overcome things that most others cannot.",logDesc="Speak to Duthorian Rall in Stormwind."} end
if not DB[1650] then DB[1650]={id=1650,zoneId=-141,name="The Tome of Valor",level=-1,minLevel=20,giver="Duthorian Rall",giverType="NPC",giverId=6171,ender="Daphne Stilwell",enderType="NPC",enderId=6182,poiX=-8546,poiY=846,wowhead="https://www.wowhead.com/wotlk/quest=1650",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Good! Your lack of hesitation is a sure sign that you are prepared and eager to test yourself. So be it.$B$BAt the very ends of Westfall's Longshore, a small house overlooks the ocean. There, a couple lives, the Stilwells. Jordan is an incredible smith, and he's gone to Ironforge to meet with the dwarves for a while. But this has left Daphne, his wife, alone and unprotected.$B$BReports suggest that the Defias have all but taken over the area, Daphne may need some protection from the villains. Go there.",logDesc="Find Daphne Stilwell in Westfall."} end
if not DB[1651] then DB[1651]={id=1651,zoneId=-141,name="The Tome of Valor",level=-1,minLevel=20,giver="Daphne Stilwell",giverType="NPC",giverId=6182,ender="Daphne Stilwell",enderType="NPC",enderId=6182,rewardNextId=1652,poiX=-11482,poiY=1557,wowhead="https://www.wowhead.com/wotlk/quest=1651",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Now, they'll be coming again soon, I'd wager, so get yourself ready.$B$BI've got myself a gun in the house. I'll grab it and be ready to help you out, but for the most part, you're on your own.$B$BI've no idea how many they'll send, but I'm sure it'll be more than the few they sent earlier.$B$BAsk the Light for whatever blessings you can because... did you hear that? I think they're coming.$B$BWe make our stand near the house!",logDesc="Defend Daphne Stilwell from the Defias attack.$B$BNeither of your spirits must be released from their mortal coils if you wish to succeed.$B$BAfter you are successful, speak to Daphne Stilwell again."} end
if not DB[1652] then DB[1652]={id=1652,zoneId=-141,name="The Tome of Valor",level=-1,minLevel=20,giver="Daphne Stilwell",giverType="NPC",giverId=6182,ender="Duthorian Rall",enderType="NPC",enderId=6171,rewardNextId=1653,poiX=-11482,poiY=1557,wowhead="https://www.wowhead.com/wotlk/quest=1652",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that.$B$BHe'll send word to Ironforge to let my Jordan know that he has nothing to fear.$B$BOh, how I miss my husband. I can't wait till he returns.",logDesc="Speak to Duthorian Rall in Stormwind.",rewards={{id=9607,qty=1}}} end
if not DB[1653] then DB[1653]={id=1653,zoneId=-141,name="The Test of Righteousness",level=-1,minLevel=20,giver="Duthorian Rall",giverType="NPC",giverId=6171,ender="Jordan Stilwell",enderType="NPC",enderId=6181,rewardNextId=1654,poiX=-8546,poiY=846,wowhead="https://www.wowhead.com/wotlk/quest=1653",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Actually, I have no doubt that Jordan himself would like to thank you, and seeing as I need a messenger to send word that his wife is safe, I think you'd be a perfect choice.$B$BJordan was to be a paladin of the Light before his dedication to his father's craft took him on another path--he's intimately familiar with our way of life and is considered among our most faithful.$B$BHe should still be in Ironforge--he likes to work outside the gates during the day, something about the cool mountain air.",logDesc="Speak to Jordan Stilwell in Ironforge"} end
if not DB[1654] then DB[1654]={id=1654,zoneId=-141,name="The Test of Righteousness",level=22,minLevel=20,giver="Jordan Stilwell",giverType="NPC",giverId=6181,ender="Jordan Stilwell",enderType="NPC",enderId=6181,rewardNextId=1806,poiX=-5089,poiY=-783,wowhead="https://www.wowhead.com/wotlk/quest=1654",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I'd like to reward you if you'd be willing to accept such a thing? Don't misunderstand me, my generosity is dependent on how much help you can be, but I see us both benefiting greatly from such an alliance.$B$BI will craft for you a weapon worthy of what you've accomplished, a symbol of paladinhood and the Light, but you must gather the items I need to craft it. I've already started taking notes on the items, it just requires someone brave and skilled enough to recover them. What do you say, $c?",logDesc="Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge."} end
if not DB[1655] then DB[1655]={id=1655,zoneId=-141,name="Bailor's Ore Shipment",level=22,minLevel=20,giver="Bailor Stonehand",giverType="NPC",giverId=6241,ender="Bailor Stonehand",enderType="NPC",enderId=6241,poiX=-5314,poiY=-2985,wowhead="https://www.wowhead.com/wotlk/quest=1655",image="assets/images/quests/placeholder.png",desc="Ach, ya startled me, $G man:woman;! Can't ya see I was lost in thought?$B$BWhat's that? Jordan's shipment... fer Ironforge. Ahhh, yeah, I know whatcha speak of. Mo'grosh ogres... dat's who took me ol' friend's ore shipment. Caravan was headin' here from the Wetlands and was ambushed. The guard who survived their attack just passed away a few days ago--healer couldn't get to 'em fast enough.$B$BIf you want the shipment, you'll have to head northeast across the Loch. It's got to be there somewhere.",logDesc="Bring Jordan's Ore Shipment to Bailor Stonehand in Loch Modan.",rewards={{id=6993,qty=1}}} end
if not DB[1656] then DB[1656]={id=1656,zoneId=220,name="A Task Unfinished",level=5,minLevel=1,giver="Antur Fallow",giverType="NPC",giverId=6775,ender="Innkeeper Kauth",enderType="NPC",enderId=6747,poiX=-3066,poiY=69,wowhead="https://www.wowhead.com/wotlk/quest=1656",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, please, I beg of you, can you help me? I have not finished my tasks here on the Mesa--I'm in the middle of my Rite of Strength--and my father asked me to deliver these furs to the inn in Bloodhoof.$B$BI'm far from rested enough to complete both my rite and this task for my father. Would you mind going on for me?$B$BThe inn is pleasant and a perfect place to rest during your long travels. I'm sure you'll agree once you see it.",logDesc="Bring the Bundle of Furs to Innkeeper Kauth in Bloodhoof Village.",choiceRewards={{id=4540,qty=5},{id=159,qty=5}}} end
if not DB[1657] then DB[1657]={id=1657,zoneId=-22,name="Stinking Up Southshore",level=-1,minLevel=25,giver="Darkcaller Yanka",giverType="NPC",giverId=15197,ender="Darkcaller Yanka",enderType="NPC",enderId=15197,poiX=1732,poiY=522,wowhead="https://www.wowhead.com/wotlk/quest=1657",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Celebrate Hallow's End in style... by bringing grief to our enemies in Southshore!$B$BTake one of these specially crafted stink bombs.  It is filled with an odiferous funk that no human - or any weak-willed beast for that matter - can stand to smell.  You'll need to throw it right in the heart of Southshore for it to do its job, so be prepared for a fight against the Alliance!$B$BWhen you've completed this task... this tribute to our liberation, return to me!",logDesc="Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.",rewards={{id=20557,qty=15}}} end
if not DB[1658] then DB[1658]={id=1658,zoneId=-22,name="Crashing the Wickerman Festival",level=-1,minLevel=25,giver="Sergeant Hartman",giverType="NPC",giverId=15199,ender="Sergeant Hartman",enderType="NPC",enderId=15199,poiX=-814,poiY=-547,wowhead="https://www.wowhead.com/wotlk/quest=1658",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I need brave individuals to head up to Tirisfal Glades and check out the Wickerman Festival.  I'm not going to lie - heading up there will be dangerous.  The guards at the festival will be exceptionally vicious.  Still, we need to know how big the festival is this year, and how much trouble the Forsaken are going to cause us during Hallow's End.$B$BIf you're up for it, head to Tirisfal and scout out the festival.  Return to me with the information, and I'll make sure you're well compensated.",logDesc="Locate the Forsaken's Wickerman Festival in Tirisfal Glades.  Return to Sergeant Hartman in Southshore once you've done so.",rewards={{id=20557,qty=15}}} end
if not DB[1659] then DB[1659]={id=1659,zoneId=-141,name="<UNUSED>",level=30,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1659",image="assets/images/quests/placeholder.png"} end
if not DB[1660] then DB[1660]={id=1660,zoneId=-141,name="<UNUSED>",level=30,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1660",image="assets/images/quests/placeholder.png"} end
if not DB[1661] then DB[1661]={id=1661,zoneId=-141,name="The Tome of Nobility",level=-1,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=1661",image="assets/images/quests/placeholder.png",desc="I greet you once again, $N. I am more proud to call you $g brother:sister; than ever before--your dedication is a tribute to us all.$B$BThe time has come for me to bestow a great gift upon you. But know this, for now I give you this freely, but later, when time permits, this will be a much greater challenge to all paladins who choose to undertake my quest.$B$BSpeak to me again and I shall grant you a great boon.",logDesc="Speak to Duthorian Rall in Stormwind."} end
if not DB[1662] then DB[1662]={id=1662,zoneId=-141,name="<UNUSED>",level=40,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=1662",image="assets/images/quests/placeholder.png"} end
if not DB[1663] then DB[1663]={id=1663,zoneId=-141,name="<UNUSED>",level=40,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=1663",image="assets/images/quests/placeholder.png"} end
if not DB[1664] then DB[1664]={id=1664,zoneId=-141,name="<UNUSED>",level=40,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=1664",image="assets/images/quests/placeholder.png"} end
if not DB[1665] then DB[1665]={id=1665,zoneId=-81,name="Bartleby's Mug",level=-1,minLevel=10,giver="Bartleby",giverType="NPC",giverId=6090,ender="Harry Burlguard",enderType="NPC",enderId=6089,poiX=-8604,poiY=389,wowhead="https://www.wowhead.com/wotlk/quest=1665",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ok, here's my mug.  Wait!  Let me finish what's in it first... there we go.",logDesc="Bring Bartleby's Mug to Burlguard"} end
if not DB[1666] then DB[1666]={id=1666,zoneId=-81,name="Marshal Haggard",level=10,minLevel=10,giver="Harry Burlguard",giverType="NPC",giverId=6089,ender="Marshal Haggard",enderType="NPC",enderId=294,rewardNextId=1667,poiX=-8613,poiY=383,wowhead="https://www.wowhead.com/wotlk/quest=1666",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You've learned a few moves, but you could still use a decent weapon.  I bet if you spoke with Marshal Haggard he could help you.$B$BMarshal Haggard lives in a manor in Elwynn Forest, at the Eastvale Lumber Camp.  He's retired now but he collected a lot of gear during his career.$B$BLet him know I sent you, and with luck he'll have a spare weapon to offer.",logDesc="Speak with Marshal Haggard."} end
if not DB[1667] then DB[1667]={id=1667,zoneId=-81,name="Dead-tooth Jack",level=10,minLevel=10,giver="Marshal Haggard",giverType="NPC",giverId=294,ender="Marshal Haggard",enderType="NPC",enderId=294,poiX=-9545,poiY=-1401,wowhead="https://www.wowhead.com/wotlk/quest=1667",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Burlguard sent you, did he?  Yes, I have spare weapons around here, but first I have a task for you...$B$BA while ago a Defias villain Dead-tooth Jack tricked me.  It was dark and he was wearing a Stormwind tabard and I thought he was Marshal Dughan.  He said he needed my old Stormwind Marshal's badge and I gave it to him... and then he laughed and ran off before I could catch him!$B$BGet back my badge!  Dead-tooth Jack probably has it stowed in his camp to the south.",logDesc="Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard.",choiceRewards={{id=6979,qty=1},{id=6983,qty=1},{id=6980,qty=1},{id=6985,qty=1}}} end
if not DB[1678] then DB[1678]={id=1678,zoneId=-81,name="Vejrek",level=-1,minLevel=10,giver="Muren Stormpike",giverType="NPC",giverId=6114,ender="Muren Stormpike",enderType="NPC",enderId=6114,rewardNextId=1680,poiX=-5046,poiY=-1273,wowhead="https://www.wowhead.com/wotlk/quest=1678",image="assets/images/quests/placeholder.png",xpDiff=6,desc="If you want to rise in the ranks of the warriors, then you better be tough.  I can teach you new moves but before that, prove to me you can handle yourself against real foes.$B$BVejrek is the toughest troll you'll find in these parts, and he's who you have to beat.  He has a hut in the foothills just south of Frostmane Hold.$B$BBring me Vejrek's head and I'll know you have mettle.",logDesc="Bring Vejrek's Head to Muren Stormpike in Ironforge."} end
if not DB[1679] then DB[1679]={id=1679,zoneId=-81,name="Muren Stormpike",level=-1,minLevel=10,giver="Granis Swiftaxe",giverType="NPC",giverId=1229,ender="Muren Stormpike",enderType="NPC",enderId=6114,rewardNextId=1678,poiX=-5606,poiY=-530,wowhead="https://www.wowhead.com/wotlk/quest=1679",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, warrior!  You show a lot of promise, but you still need to learn some tricks and Muren Stormpike is just the dwarf to teach you.$B$BYou can find Muren at the Hall of Arms in the Military Ward of Ironforge.  Talk to him when you're ready to learn what it is to be a warrior.",logDesc="Speak with Muren Stormpike."} end
if not DB[1680] then DB[1680]={id=1680,zoneId=-81,name="Tormus Deepforge",level=11,minLevel=10,giver="Muren Stormpike",giverType="NPC",giverId=6114,ender="Tormus Deepforge",enderType="NPC",enderId=6031,rewardNextId=1681,poiX=-5046,poiY=-1273,wowhead="https://www.wowhead.com/wotlk/quest=1680",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Now that you've learned some moves, it's time to get you a decent weapon.  Speak with Tormus Deepforge.  He can make you a weapon I'm sure you'll like.$B$BYou'll find Tormus here in Ironforge, at the Great Forge.",logDesc="Speak with Tormus Deepforge."} end
if not DB[1681] then DB[1681]={id=1681,zoneId=-81,name="Ironband's Compound",level=11,minLevel=10,giver="Tormus Deepforge",giverType="NPC",giverId=6031,ender="Tormus Deepforge",enderType="NPC",enderId=6031,poiX=-4793,poiY=-1098,wowhead="https://www.wowhead.com/wotlk/quest=1681",image="assets/images/quests/placeholder.png",xpDiff=4,desc="My mentor, Sturgy Ironband, had a compound south of Helm's Bed Lake in eastern Dun Morogh.  There he taught blacksmithing and he was the best.$B$BBut one day, one of his students brought him a load of strange ore.  Master Ironband called it umbral ore and was eager to work with it, but soon after it arrived... a band of Dark Iron dwarves attacked his compound.  They killed everyone!$B$BEnter Ironband's compound, $N, and avenge my master's death.  And bring me the load of umbral ore that caused it.",logDesc="Bring a load of Umbral Ore to Tormus Deepforge in Ironforge."} end
if not DB[1682] then DB[1682]={id=1682,zoneId=-81,name="Grey Iron Weapons",level=10,minLevel=10,giver="Tormus Deepforge",giverType="NPC",giverId=6031,ender="Tormus Deepforge",enderType="NPC",enderId=6031,poiX=-4793,poiY=-1098,wowhead="https://www.wowhead.com/wotlk/quest=1682",image="assets/images/quests/placeholder.png",xpDiff=4,choiceRewards={{id=6978,qty=1},{id=6982,qty=1},{id=6981,qty=1},{id=6984,qty=1}}} end
if not DB[1683] then DB[1683]={id=1683,zoneId=-81,name="Vorlus Vilehoof",level=-1,minLevel=10,giver="Elanaria",giverType="NPC",giverId=4088,ender="Elanaria",enderType="NPC",enderId=4088,poiX=9994,poiY=2332,wowhead="https://www.wowhead.com/wotlk/quest=1683",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Before I can teach you, you must show me your resolve.$B$BThe satyr Vorlus Vilehoof has found one of our remote moonwells, southeast of the Ban'ethil Barrow Den.  He now splashes within it, defiling its pure waters with his filth.$B$BFind Vorlus at the moonwell and destroy him.  Bring me his horn as proof and I will begin your advanced training as a warrior.$B$BThe path to the moonwell is hidden well, $N, but stay focused and alert and you will find it.",logDesc="Bring the Horn of Vorlus to Elanaria in Darnassus."} end
if not DB[1684] then DB[1684]={id=1684,zoneId=-81,name="Elanaria",level=-1,minLevel=10,giver="Moon Priestess Amara",giverType="NPC",giverId=2151,ender="Elanaria",enderType="NPC",enderId=4088,rewardNextId=1683,poiX=9837,poiY=966,wowhead="https://www.wowhead.com/wotlk/quest=1684",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Greetings, warrior.  Your skill grows, but there is more to your profession than you may believe.  To further progress, you must soon find a teacher.$B$BThe warrior Elanaria dwells in Darnassus, at the Warrior's Terrace.  She can instruct you.",logDesc="Speak with Elanaria."} end
if not DB[1685] then DB[1685]={id=1685,zoneId=-61,name="Gakin's Summons",level=-1,minLevel=10,giver="Remen Marcot",giverType="NPC",giverId=6121,ender="Gakin the Darkbinder",enderType="NPC",enderId=6122,rewardNextId=1688,poiX=-9473,poiY=-9,wowhead="https://www.wowhead.com/wotlk/quest=1685",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Isn't that how it always works? Was looking for you all day and couldn't find you, now when I'm not expecting it, you come and walk right up to me.$b$bI've wasted enough time trying to find you, so I won't delay you any longer. Master Gakin's summoned you for additional training. Seems to me you should seek him out as soon as possible.$b$bYou'll find him in the basement of the Slaughtered Lamb tavern. By the way, you might want to keep that particular location quiet. Don't want word spreading about it.",logDesc="Report to Gakin the Darkbinder in the Mage Quarter of Stormwind."} end
if not DB[1686] then DB[1686]={id=1686,zoneId=-81,name="The Shade of Elura",level=10,minLevel=10,giver="Elanaria",giverType="NPC",giverId=4088,ender="Elanaria",enderType="NPC",enderId=4088,rewardNextId=1692,poiX=9994,poiY=2332,wowhead="https://www.wowhead.com/wotlk/quest=1686",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have learned much, $N.  Now we will craft you a weapon.  A warrior's weapon.$B$BTo do this, you must travel to Darkshore.$B$BLong ago a ship crashed upon the rocks near the Auberdine lighthouse, scattering many crates of elunite ore along the ocean floor.$B$BFirst, you must defeat the elunite's guardian, the Shade of Elura.  Once the ship's captain, she cursed herself to roam the deeps and protect her shipment for all time.  Defeat her, gain her medallion, and gather the crates of lost Elunite.",logDesc="Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus."} end
if not DB[1687] then DB[1687]={id=1687,zoneId=-284,name="Spooky Lighthouse",level=-1,minLevel=10,ender="Human Orphan",enderType="NPC",enderId=14305,wowhead="https://www.wowhead.com/wotlk/quest=1687",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Sometimes late at night, our matrons at the orphanage will tell us spooky stories.  Those RULE!  There's one about a ghost that haunts a lighthouse in Westfall.  They say he was a pirate captain who had his ship taken from him by other pirates.  Wow!$B$BCould you please take me to the lighthouse in Westfall?  I wanna see if the ghost of that captain is there!  I promise to stay close to you; I won't run off or anything!",logDesc="Take the orphan to see the lighthouse off the coast of Westfall.$B"} end
if not DB[1688] then DB[1688]={id=1688,zoneId=-61,name="Surena Caledon",level=-1,minLevel=10,giver="Gakin the Darkbinder",giverType="NPC",giverId=6122,ender="Gakin the Darkbinder",enderType="NPC",enderId=6122,rewardNextId=1689,poiX=-8983,poiY=1042,wowhead="https://www.wowhead.com/wotlk/quest=1688",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I had a student named Surena Caledon. She stood where you stand now, eager to learn of warlock magic, and possessing no small bit of talent. More than that she was young and pleasing to the eye. Had I seen it then, the traitorous trollop!$b$bThe thieving wench ran off with one of the Defias, Erlan Drudgemoor. While her loss is of little importance, I gifted her a bloodstone choker that I must have.$b$bHer life means nothing to me now. You will find her at the Brackwell Pumpkin Patch. Retrieve what is mine.",logDesc="Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind."} end
if not DB[1689] then DB[1689]={id=1689,zoneId=-61,name="The Binding",level=-1,minLevel=10,giver="Gakin the Darkbinder",giverType="NPC",giverId=6122,ender="Gakin the Darkbinder",enderType="NPC",enderId=6122,poiX=-8983,poiY=1042,wowhead="https://www.wowhead.com/wotlk/quest=1689",image="assets/images/quests/placeholder.png",xpDiff=4,desc="By retrieving my choker and besting Surena, you've proven that you're at least as capable as she was.$b$bWith that said, I can tell you're direly in need of training. You can manage the flows of magic, yes, but being a warlock is much more than that.$b$bI will show you how to command a voidwalker, but before I can, you must call one forth at a summoning circle and subdue it using whatever weapons--physical and magical--you have at your disposal. Use the magic of this choker at the summoning circle below.",logDesc="Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind."} end
if not DB[1690] then DB[1690]={id=1690,zoneId=440,name="Wastewander Justice",level=43,minLevel=40,giver="Chief Engineer Bilgewhizzle",giverType="NPC",giverId=7407,ender="Chief Engineer Bilgewhizzle",enderType="NPC",enderId=7407,rewardNextId=1691,poiX=-7187,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=1690",image="assets/images/quests/placeholder.png",xpDiff=5,money=6000,desc="You there!  It's time for you to be a big helper to the Gadgetzan Water Company.$B$BThe Wastewander nomads out in the Tanaris desert have seized almost all the water wells!  Without access to them, our water supply will dry up in no time.  If you want to get in our good graces, then you'll help us bring justice to those nomads!$B$BHead east of here and bring down ten Wastewander Bandits and Thieves, then report back to me on the double.  Justice waits for no man... goblin... bah, just get on it!",logDesc="Take down 10 Wastewander Bandits and Thieves east of Gadgetzan, then report back to Chief Engineer Bilgewhizzle."} end
if not DB[1691] then DB[1691]={id=1691,zoneId=440,name="More Wastewander Justice",level=44,minLevel=40,giver="Chief Engineer Bilgewhizzle",giverType="NPC",giverId=7407,ender="Chief Engineer Bilgewhizzle",enderType="NPC",enderId=7407,poiX=-7187,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=1691",image="assets/images/quests/placeholder.png",xpDiff=5,money=6500,desc="We need you to take on the stronger ranks of the Wastewander nomads now.  You've done a good job thus far, but if we are to take back those water wells, then it only makes sense to do it against as few nomads as possible!$B$BThis time around we need you to take down their rogues, assassins, and shadow mages.  You'll find them east and southeast of here.$B$BI'm not going to lie to you - they're a nasty lot.  Do this for us though, and we'll be on our way to taking back what is rightfully ours!",logDesc="Take down 10 Wastewander Shadow Mages, 8 Wastewander Rogues, and 6 Wastewander Assassins for Chief Engineer Bilgewhizzle in Gadgetzan.$B"} end
if not DB[1692] then DB[1692]={id=1692,zoneId=-81,name="Smith Mathiel",level=10,minLevel=10,giver="Elanaria",giverType="NPC",giverId=4088,ender="Mathiel",enderType="NPC",enderId=6142,poiX=9994,poiY=2332,wowhead="https://www.wowhead.com/wotlk/quest=1692",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I have placed the elunite you gathered into a case.  Take it to the blacksmith Mathiel, and he will craft for you an elunite weapon.$B$BMathiel is to the south, on the other side of this building.",logDesc="Bring the Case of Elunite to Smith Mathiel. "} end
if not DB[1693] then DB[1693]={id=1693,zoneId=-81,name="Weapons of Elunite",level=10,minLevel=10,giver="Mathiel",giverType="NPC",giverId=6142,ender="Mathiel",enderType="NPC",enderId=6142,poiX=9918,poiY=2309,wowhead="https://www.wowhead.com/wotlk/quest=1693",image="assets/images/quests/placeholder.png",xpDiff=4,choiceRewards={{id=6966,qty=1},{id=6968,qty=1},{id=6969,qty=1},{id=6967,qty=1}}} end
if not DB[1698] then DB[1698]={id=1698,zoneId=-81,name="Yorus Barleybrew",level=20,minLevel=20,giver="Wu Shen",giverType="NPC",giverId=5479,ender="Yorus Barleybrew",enderType="NPC",enderId=6166,rewardNextId=1699,poiX=-8689,poiY=323,wowhead="https://www.wowhead.com/wotlk/quest=1698",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Yorus Barleybrew has issued a challenge to all able warriors of the Alliance.  He waits at the Lakeshire Inn, in Redridge, and pledges a grand reward to anyone able to pass his trial.",logDesc="Speak with Yorus Barleybrew."} end
if not DB[1699] then DB[1699]={id=1699,zoneId=-81,name="The Rethban Gauntlet",level=22,minLevel=20,giver="Yorus Barleybrew",giverType="NPC",giverId=6166,ender="Yorus Barleybrew",enderType="NPC",enderId=6166,poiX=-9223,poiY=-2148,wowhead="https://www.wowhead.com/wotlk/quest=1699",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I call my challenge the Rethban Gauntlet.  To pass the trial, all you must do is enter the Rethban Caverns, to the first fork, then return here.  Easy!  Except there are a few wrinkles...$B$BYou have to return within an hour.$B$BThere are whole heaps of Redridge Gnolls in the way.$B$BBefore you start, you have to take a swig of my family's signature drink: Barleybrew Scalder!$B$BSo what do you say?  The Rethban Caverns are in the foothills north of Lakeshire.  Are you ready to run the Rethban Gauntlet?",logDesc="Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed.$B$BYou must not die and release your spirit."} end
if not DB[1700] then DB[1700]={id=1700,zoneId=-81,name="Grimand Elmore",level=28,minLevel=20,giver="Furen Longbeard",giverType="NPC",giverId=5413,ender="Grimand Elmore",enderType="NPC",enderId=1416,rewardNextId=1705,poiX=-8427,poiY=600,wowhead="https://www.wowhead.com/wotlk/quest=1700",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I made a copy of my notes on the techniques I learned while making your armor, and I need them sent to Grimand Elmore.  He's here in the Dwarven District, in the weapon shop.$B$BAnd duck when you give these to him.  He's fiercely proud of his skills, and won't like the idea of learning something from me...",logDesc="Bring Furen's Notes to Grimand Elmore."} end
if not DB[1701] then DB[1701]={id=1701,zoneId=-81,name="Fire Hardened Mail",level=28,minLevel=20,giver="Furen Longbeard",giverType="NPC",giverId=5413,ender="Furen Longbeard",enderType="NPC",enderId=5413,poiX=-8427,poiY=600,wowhead="https://www.wowhead.com/wotlk/quest=1701",image="assets/images/quests/placeholder.png",xpDiff=5,desc="So I gave you a nice shield, but we don't have to stop there.  I know the secrets to make extremely hard mail armor.  It's not easy and it takes very rare materials, but if you're willing to do the legwork then I'll make a piece for you.$B$BWhat do you say, $N?  If you're up for the challenge, then I'll give you a list of what to get and where to get them.",logDesc="Gather the materials Furen Longbeard requires, and bring them to him in Stormwind."} end
if not DB[1702] then DB[1702]={id=1702,zoneId=-81,name="The Shieldsmith",level=22,minLevel=20,giver="Yorus Barleybrew",giverType="NPC",giverId=6166,ender="Furen Longbeard",enderType="NPC",enderId=5413,rewardNextId=1701,poiX=-9223,poiY=-2148,wowhead="https://www.wowhead.com/wotlk/quest=1702",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You really showed what you were made of when you ran the Rethban Gauntlet, $N.  And I'm true to my word.  I'll get you the reward I promised...$B$BExcept it's in Stormwind.$B$BTalk to my friend, Furen Longbeard, in the Dwarven District of Stormwind.  He's the best shieldsmith you'll ever meet, and he owes me a big favor.$B$BHere, take Furen this cask of Barleybrew Scalder and ask him for a shield.  He'll give you a nice one.",logDesc="Bring the Cask of Scalder to Furen Longbeard.",rewards={{id=6970,qty=1}}} end
if not DB[1703] then DB[1703]={id=1703,zoneId=-81,name="Mathiel",level=28,minLevel=20,giver="Furen Longbeard",giverType="NPC",giverId=5413,ender="Mathiel",enderType="NPC",enderId=6142,rewardNextId=1710,poiX=-8427,poiY=600,wowhead="https://www.wowhead.com/wotlk/quest=1703",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I made a copy of my notes on the techniques I learned while making your armor, and need them sent to the blacksmith Mathiel.  He lives in Darnassus which is quite a long way off, but I'm sure he'll be very grateful to learn what I've learned.",logDesc="Bring Furen's Notes to Mathiel."} end
if not DB[1704] then DB[1704]={id=1704,zoneId=-81,name="Klockmort Spannerspan",level=28,minLevel=20,giver="Furen Longbeard",giverType="NPC",giverId=5413,ender="Klockmort Spannerspan",enderType="NPC",enderId=6169,rewardNextId=1708,poiX=-8427,poiY=600,wowhead="https://www.wowhead.com/wotlk/quest=1704",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I made a copy of my notes on the techniques I learned while making your armor, and need someone to take them to Klockmort Spannerspan.  He's a gnomish blacksmith in Ironforge and when he learns what I've learned... I bet he'll pull off his own beard in excitement.",logDesc="Bring Furen's Notes to Klockmort Spannerspan."} end
if not DB[1705] then DB[1705]={id=1705,zoneId=-81,name="Burning Blood",level=28,minLevel=20,giver="Grimand Elmore",giverType="NPC",giverId=1416,ender="Grimand Elmore",enderType="NPC",enderId=1416,poiX=-8387,poiY=685,wowhead="https://www.wowhead.com/wotlk/quest=1705",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I hate to admit that Furen might have really found something.  But to be sure I'll need to try his techniques on a new piece of armor.  If you help me with the materials, $N, then you can have the armor.$B$BTo make this armor, I need samples of burning blood and a burning rock.$B$BThe only place I know to get them is Duskwood.  The Nightbane worgen based in the Roland's Doom mine have burning blood, and their leader Gutspill will have the rock.$B$BMay fortune grant you speed, $N.",logDesc="Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind."} end
if not DB[1706] then DB[1706]={id=1706,zoneId=-81,name="Grimand's Armor",level=30,minLevel=20,giver="Grimand Elmore",giverType="NPC",giverId=1416,ender="Grimand Elmore",enderType="NPC",enderId=1416,poiX=-8387,poiY=685,wowhead="https://www.wowhead.com/wotlk/quest=1706",image="assets/images/quests/placeholder.png",xpDiff=6,rewards={{id=6971,qty=1}}} end
if not DB[1707] then DB[1707]={id=1707,zoneId=440,name="Water Pouch Bounty",level=44,minLevel=40,giver="Spigot Operator Luglunket",giverType="NPC",giverId=7408,ender="Spigot Operator Luglunket",enderType="NPC",enderId=7408,poiX=-7183,poiY=-3840,wowhead="https://www.wowhead.com/wotlk/quest=1707",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Greetings $n - the name's Luglunket, and we've got an important job for you if you're up for it!  Huzzah!$B$BNothing would please me more as a seasoned spigot operator to take any Wastewander water pouches you might find out in the desert.  That's our water anyway - the nomads have just stolen it is all!  The Gadgetzan Water Company will offer you an official care package for every five you turn in.  Most importantly though, you're helping Gadgetzan help itself!",logDesc="Bring 5 Wastewander Water Pouches to Spigot Operator Luglunket in Gadgetzan.",rewards={{id=8484,qty=1}}} end
if not DB[1708] then DB[1708]={id=1708,zoneId=-81,name="Iron Coral",level=29,minLevel=20,giver="Klockmort Spannerspan",giverType="NPC",giverId=6169,ender="Klockmort Spannerspan",enderType="NPC",enderId=6169,poiX=-4812,poiY=-1251,wowhead="https://www.wowhead.com/wotlk/quest=1708",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I want to try Furen Longbeard's new techniques on my own piece of armor.  And because you helped Furen and he helped me, you're welcome to the armor after I make it!$B$BTo finish the piece, I need a special coral, searing coral.  It grows in only one place--along the coast south of Menethil Harbor in the Wetlands.$B$BBring me enough searing coral and I'll get right to work on the armor.  And hurry, $N.  I'm so eager to get started it's making my toes twist!",logDesc="Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge."} end
if not DB[1709] then DB[1709]={id=1709,zoneId=-81,name="Klockmort's Creation",level=30,minLevel=20,giver="Klockmort Spannerspan",giverType="NPC",giverId=6169,ender="Klockmort Spannerspan",enderType="NPC",enderId=6169,poiX=-4812,poiY=-1251,wowhead="https://www.wowhead.com/wotlk/quest=1709",image="assets/images/quests/placeholder.png",xpDiff=6,rewards={{id=6974,qty=1}}} end
if not DB[1710] then DB[1710]={id=1710,zoneId=-81,name="Sunscorched Shells",level=30,minLevel=20,giver="Mathiel",giverType="NPC",giverId=6142,ender="Mathiel",enderType="NPC",enderId=6142,poiX=9918,poiY=2309,wowhead="https://www.wowhead.com/wotlk/quest=1710",image="assets/images/quests/placeholder.png",xpDiff=4,desc="My colleague, Furen Longbeard, made a discovery which I am eager to test.  I wish to try it on a new armor that I am researching, for I believe Furen's techniques will produce superior results.$B$BWill you help me?  If you gather what I need to make the armor, then I will make an extra piece for you.$B$BI need the sunscorched egg shells of the Highperch Wyverns who dwell at Highperch, in Thousand Needles.  Search for the shells below their nests, and return to me when you have a sufficient amount.",logDesc="Bring 20 Sunscorched Shells to Mathiel in Darnassus."} end
if not DB[1711] then DB[1711]={id=1711,zoneId=-81,name="Mathiel's Armor",level=30,minLevel=20,giver="Mathiel",giverType="NPC",giverId=6142,ender="Mathiel",enderType="NPC",enderId=6142,poiX=9918,poiY=2309,wowhead="https://www.wowhead.com/wotlk/quest=1711",image="assets/images/quests/placeholder.png",xpDiff=6,rewards={{id=6973,qty=1}}} end
if not DB[1712] then DB[1712]={id=1712,zoneId=-81,name="Cyclonian",level=40,minLevel=30,giver="Bath'rah the Windwatcher",giverType="NPC",giverId=6176,ender="Bath'rah the Windwatcher",enderType="NPC",enderId=6176,rewardNextId=1713,poiX=251,poiY=-1471,wowhead="https://www.wowhead.com/wotlk/quest=1712",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I have spent ages watching this site.  I watch, so that one day I might see the great Cyclonian fall.  But I have not yet found a champion to defeat the wind lord.$B$BPerhaps you are that champion.$B$BProve it to me.  Gather the items I need to summon Cyclonian, and I will know you are a great warrior.  Perhaps then you can defeat him and gain his whirlwind heart.$B$BIf so, then I will infuse the heart's power in a weapon, and I will give that weapon to you.$B$BHere is a parchment with the items I need.",logDesc="Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac."} end
if not DB[1713] then DB[1713]={id=1713,zoneId=-81,name="The Summoning",level=40,minLevel=30,giver="Bath'rah the Windwatcher",giverType="NPC",giverId=6176,ender="Bath'rah the Windwatcher",enderType="NPC",enderId=6176,poiX=251,poiY=-1471,wowhead="https://www.wowhead.com/wotlk/quest=1713",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I am ready to perform the ritual to summon Cyclonian.  When he is summoned, you must defeat him and take his whirlwind heart.  This I will use to instill a weapon with Cyclonian's power.$B$B$N, are you ready to face the wind lord?",logDesc="Bring the Whirlwind Heart to Bath'rah Windwatcher."} end
if not DB[1714] then DB[1714]={id=1714,zoneId=-81,name="Essence of the Exile",level=37,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=1714",image="assets/images/quests/placeholder.png",rewards={{id=6851,qty=1}}} end
if not DB[1715] then DB[1715]={id=1715,zoneId=-61,name="The Slaughtered Lamb",level=-1,minLevel=10,giver="Lago Blackwrench",giverType="NPC",giverId=6120,ender="Gakin the Darkbinder",enderType="NPC",enderId=6122,poiX=-4618,poiY=-1090,wowhead="https://www.wowhead.com/wotlk/quest=1715",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Hmph. Times past, all warlocks in Khaz Modan were trained under the auspices of the masters of Gnomeregan, but now that we've all been forced to relocate into this rat's hole in Ironforge, and Magni's decided to keep a careful watch on us, we're forced to send our novices to Stormwind for training.$b$bLuckily, Gakin's no slouch, so you'll still learn what you need to know, but it burns my blood!$b$bAnyways, you'll find Gakin in the basement of the Slaughtered Lamb in Stormwind.",logDesc="Report to Gakin the Darkbinder in the Mage Quarter of Stormwind."} end
if not DB[1716] then DB[1716]={id=1716,zoneId=-61,name="Devourer of Souls",level=-1,minLevel=20,giver="Gakin the Darkbinder",giverType="NPC",giverId=6122,ender="Takar the Seer",enderType="NPC",enderId=6244,rewardNextId=1738,poiX=-8983,poiY=1042,wowhead="https://www.wowhead.com/wotlk/quest=1716",image="assets/images/quests/placeholder.png",xpDiff=3,desc="A succubus is a devourer of souls, destroyer of hearts, and dominator of minds. It knows nothing but evil.$b$bThis will be the creature you will learn to summon and control, but it cannot be brought into our world without a stimulus.$b$bWith a symbol of love as bait, it will surely answer your call. Then you can defeat it, and make it your tool.$b$bIt will be hard to find something of this nature, though. You should speak with Takar the Seer. You will find him in the Barrens of Kalimdor near Camp Taurajo.",logDesc="Speak with Takar the Seer in the Barrens."} end
if not DB[1717] then DB[1717]={id=1717,zoneId=-61,name="Gakin's Summons",level=-1,minLevel=20,giver="Lago Blackwrench",giverType="NPC",giverId=6120,ender="Gakin the Darkbinder",enderType="NPC",enderId=6122,rewardNextId=1716,poiX=-4618,poiY=-1090,wowhead="https://www.wowhead.com/wotlk/quest=1717",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$n! Didn't expect to see you around these parts, but I was instructed to keep an eye out for you.$b$bIt's past time you got some more training, so you should stop in to see Gakin the next time you're in Stormwind. He'll be waiting for you.",logDesc="Report to Gakin the Darkbinder in the Mage Quarter of Stormwind."} end
if not DB[1718] then DB[1718]={id=1718,zoneId=-81,name="The Islander",level=-1,minLevel=30,giver="Torm Ragetotem",giverType="NPC",giverId=3041,ender="Klannoc Macleod",enderType="NPC",enderId=6236,rewardNextId=1719,poiX=-1458,poiY=-81,wowhead="https://www.wowhead.com/wotlk/quest=1718",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Your renown as a warrior grows, $N.  Now it is time to pit yourself against your peers and see where you stand.$B$BThere is an island off the coast of the Barrens, south of Ratchet.  It is called Fray Island and it is a place where warriors meet.$B$BMeet, and fight.$B$BSpeak with the chief warrior of Fray Island, Klannoc Macleod.  If he finds you worthy, then Klannoc will lead you further down the warrior's path.$B$BTo reach Fray Island, search for the sand bar shallows along the Merchant Coast.",logDesc="Speak with Klannoc Macleod."} end
if not DB[1719] then DB[1719]={id=1719,zoneId=-81,name="The Affray",level=-1,minLevel=30,giver="Klannoc Macleod",giverType="NPC",giverId=6236,ender="Klannoc Macleod",enderType="NPC",enderId=6236,poiX=-1709,poiY=-4330,wowhead="https://www.wowhead.com/wotlk/quest=1719",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If you want to learn from me, then you must first pass The Affray.  It is a challenge we on Fray Island like to offer rising warriors who think they're tough, and if you can pass this test then I'll know you are.$B$BTo begin, walk into the middle of that crowd yonder and step on the grate.  That'll tell Twiggy Flathead you're ready, and he'll send challengers against you.$B$BBeat all the challengers and he'll call out Big Will.  Kill Big Will, and return to me in the time we allow.",logDesc="Kill Big Will, then speak to Klannoc Macleod on Fray Island."} end
if not DB[1738] then DB[1738]={id=1738,zoneId=-61,name="Heartswood",level=-1,minLevel=20,giver="Takar the Seer",giverType="NPC",giverId=6244,ender="Gakin the Darkbinder",enderType="NPC",enderId=6122,rewardNextId=1739,poiX=-2245,poiY=-2374,wowhead="https://www.wowhead.com/wotlk/quest=1738",image="assets/images/quests/placeholder.png",xpDiff=5,desc="In preparation for your coming, I used my sight to look over the world and through the mists of time. I have found what it is you seek.$b$bIn the War of the Ancients, two lovers fell together in battle. Where they took their last breaths, a tree known as the heartswood grew, a symbol of their undying love.$b$bThat should be enough to tempt a succubus. You will find it in the ruins of Ordil'Aran in the northwestern part of the forest of Ashenvale.",logDesc="Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind."} end
if not DB[1739] then DB[1739]={id=1739,zoneId=-61,name="The Binding",level=-1,minLevel=20,giver="Gakin the Darkbinder",giverType="NPC",giverId=6122,ender="Gakin the Darkbinder",enderType="NPC",enderId=6122,poiX=-8983,poiY=1042,wowhead="https://www.wowhead.com/wotlk/quest=1739",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Using the heartswood core, you will be able to cast a spell at the summoning circle in the crypt below to open a portal for the succubus to pass through.$b$bBe careful, $n, succubi have overrun even the strongest of minds.$b$bOnce you have bested and returned it to the void, return to me and I will show you how to call and control it.",logDesc="Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb.",rewards={{id=22243,qty=1}}} end
if not DB[1740] then DB[1740]={id=1740,zoneId=-61,name="The Orb of Soran'ruk",level=25,minLevel=20,giver="Doan Karhan",giverType="NPC",giverId=6247,ender="Doan Karhan",enderType="NPC",enderId=6247,poiX=-2252,poiY=-2374,wowhead="https://www.wowhead.com/wotlk/quest=1740",image="assets/images/quests/placeholder.png",xpDiff=7,desc="When demons of the Legion fall out of favor, their spirits are imprisoned within orbs and distributed to their mages and warlocks.$b$bMany were carried by their servants in Azeroth. Even fragmented, they still possess the powers of the demons trapped inside.$b$bThe orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps. The other, larger piece, was possessed by a wizard in Shadowfang Keep. Find them and I can reform it.",logDesc="Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.",choiceRewards={{id=6898,qty=1},{id=15109,qty=1}}} end
if not DB[1758] then DB[1758]={id=1758,zoneId=-61,name="Tome of the Cabal",level=-1,minLevel=30,giver="Strahad Farsan",giverType="NPC",giverId=6251,ender="Krom Stoutarm",enderType="NPC",enderId=6294,rewardNextId=1802,poiX=-786,poiY=-3723,wowhead="https://www.wowhead.com/wotlk/quest=1758",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.$b$bMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.$b$bPerhaps Krom Stoutarm can help you with this. An itinerant warlock these days, he spends his days hoarding ancient texts and skulking about the library in Ironforge.",logDesc="Speak with Krom Stoutarm in Ironforge."} end
if not DB[1778] then DB[1778]={id=1778,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="John Turner",giverType="NPC",giverId=6175,ender="Tiza Battleforge",enderType="NPC",enderId=6179,rewardNextId=1779,poiX=-4896,poiY=-898,wowhead="https://www.wowhead.com/wotlk/quest=1778",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I'm going to see about making plans to return home soon. Hopefully, Stephanie is doing well back in Stormwind. I can't wait to see her again. Till next we meet, $c.",logDesc="Speak to Tiza Battleforge in Ironforge."} end
if not DB[1779] then DB[1779]={id=1779,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Tiza Battleforge",giverType="NPC",giverId=6179,ender="Muiredon Battleforge",enderType="NPC",enderId=6178,rewardNextId=1783,poiX=-4634,poiY=-932,wowhead="https://www.wowhead.com/wotlk/quest=1779",image="assets/images/quests/placeholder.png",desc="I want you to take this, $N. It is called the Symbol of Life.$B$BYou've proven charitable and patient, and now I want you to prove just how adept you've become in both combat, and power.$B$BMy husband Muiredon returned recently from an encounter with some Dark Iron dwarves, and he barely escaped with his life--he's over there having his wounds healed by one of our priests.$B$BTake the Symbol and speak to him. If you can help him, then we will speak again soon. May the Light shine upon you.",logDesc="Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge."} end
if not DB[1780] then DB[1780]={id=1780,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Stephanie Turner",giverType="NPC",giverId=6174,ender="Duthorian Rall",enderType="NPC",enderId=6171,rewardNextId=1781,poiX=-8832,poiY=614,wowhead="https://www.wowhead.com/wotlk/quest=1780",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I'll take these to the children this very day. Please be safe, good $c. It is not often $G men:women; of your character show their faces in the city, but you've proven that the paladins here in Stormwind shall never turn their backs on those in need.$B$BFarewell.",logDesc="Speak to Duthorian Rall in Stormwind."} end
if not DB[1781] then DB[1781]={id=1781,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Duthorian Rall",giverType="NPC",giverId=6171,ender="Gazin Tenorm",enderType="NPC",enderId=6173,rewardNextId=1786,poiX=-8546,poiY=846,wowhead="https://www.wowhead.com/wotlk/quest=1781",image="assets/images/quests/placeholder.png",desc="Take this, $N. It is called the Symbol of Life.$B$BYou've proven charitable and patient, and now the time has come to see if you're powerful enough to focus one of the Light's greatest gifts.$B$BMy friend Gazin returned recently from an encounter with some Defias in Elwynn near Heroes' Vigil--he barely escaped with his life. He's near the altar having his wounds healed by our priests.$B$BTake the Symbol and speak to him. If you can help him, then we will speak again soon. May you bask in the Light's glory.",logDesc="Take the Symbol of Life to Gazin Tenorm in Stormwind."} end
if not DB[1782] then DB[1782]={id=1782,zoneId=0,name="Furen's Armor",level=28,minLevel=20,giver="Furen Longbeard",giverType="NPC",giverId=5413,ender="Furen Longbeard",enderType="NPC",enderId=5413,poiX=-8427,poiY=600,wowhead="https://www.wowhead.com/wotlk/quest=1782",image="assets/images/quests/placeholder.png",xpDiff=7,rewards={{id=6972,qty=1}}} end
if not DB[1783] then DB[1783]={id=1783,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Muiredon Battleforge",giverType="NPC",giverId=6178,ender="Narm Faulk",enderType="NPC",enderId=6177,rewardNextId=1784,poiX=-4613,poiY=-900,wowhead="https://www.wowhead.com/wotlk/quest=1783",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We was spyin' on some of the Dark Iron dwarves that've bunkered down south of Helm's Bed Lake. We knew they was up to no good, so Narm an' me thought we'd take a closer look--got ta see their leader given orders to some o' his men.$B$BNarm an' me took the chance to kill a few of 'em, but they proved tougher than we thought, an' more of 'em got the jump on us. Narm tol' me to run an' get support, so 'ere I am.$B$BNarm needs help, an' I'll not rest till he gets it.$B$BC'n ya help, $N?",logDesc="Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh."} end
if not DB[1784] then DB[1784]={id=1784,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Narm Faulk",giverType="NPC",giverId=6177,ender="Muiredon Battleforge",enderType="NPC",enderId=6178,rewardNextId=1785,poiX=-5784,poiY=-2055,wowhead="https://www.wowhead.com/wotlk/quest=1784",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Before I fell in battle, Muiredon and I had almost defeated one of the Dark Iron spies near that small house. We witnessed their captain passing orders to them, and sought to kill him and take the orders.$B$BSome of the council in Ironforge do not yet believe the presence of Dark Iron dwarves exists in Dun Morogh. By attaining one of those scripts, we'll not only have proof of their movements, but possibly an idea of what they're planning.$B$BGet one of those scripts and take it back to Muiredon, $N.",logDesc="Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge."} end
if not DB[1785] then DB[1785]={id=1785,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Muiredon Battleforge",giverType="NPC",giverId=6178,ender="Tiza Battleforge",enderType="NPC",enderId=6179,poiX=-4613,poiY=-900,wowhead="https://www.wowhead.com/wotlk/quest=1785",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I c'n see me wife's o'er there beamin' wit pride already. Ya better get yer tuchus o'er there pronto. I be thinkin' she'd have some words wit ya.$B$BLight be witcha, mighty $c. I'll be lookin' fer ya on the battlefield against the Scourge and dem Dark Irons when the time comes.",logDesc="Speak to Tiza Battleforge in Ironforge."} end
if not DB[1786] then DB[1786]={id=1786,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Gazin Tenorm",giverType="NPC",giverId=6173,ender="Henze Faulk",enderType="NPC",enderId=6172,rewardNextId=1787,poiX=-8516,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1786",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Henze and I had made it to Heroes' Vigil, an island in the middle of Stone Cairn Lake in northeastern Elwynn. We'd heard the Defias had infiltrated our borders and we wanted proof to take to the king's advisors.$B$BWe caught sight of a couple of the scum going over some documents, and we attacked. Unfortunately, we were quickly overwhelmed by more of the mages.$B$BHenze held them off for me while I escaped... the daft fool, going and being brave.$B$BHe's out there now, Henze is. Can you help us, $N?",logDesc="Take the Symbol of Life and resurrect Henze Faulk in Elwynn."} end
if not DB[1787] then DB[1787]={id=1787,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Henze Faulk",giverType="NPC",giverId=6172,ender="Gazin Tenorm",enderType="NPC",enderId=6173,rewardNextId=1788,poiX=-9130,poiY=-984,wowhead="https://www.wowhead.com/wotlk/quest=1787",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We'll have time to talk more about the Symbol at a later time. What's important now is to get those papers we saw the Defias going over. If we can get our hands on them, we'll be able to prove the Defias have infiltrated Elwynn and hopefully gain some insight into what their plans are.$B$BI'm in no shape for battle as of now, $N. Do you think you're strong enough to get those papers from the Defias here on the island?$B$BIf you're able to get them, bring them back to Gazin and let him know I'm all right.",logDesc="Retrieve a Defias Script from the Defias Rogue Wizards in Elwynn, and return to Gazin Tenorm in Stormwind."} end
if not DB[1788] then DB[1788]={id=1788,zoneId=-141,name="The Tome of Divinity",level=-1,minLevel=12,giver="Gazin Tenorm",giverType="NPC",giverId=6173,ender="Duthorian Rall",enderType="NPC",enderId=6171,poiX=-8516,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1788",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I'll take the script to the King's advisors after Duthorian's taken a look at them, but in the meantime, you should go speak to Duthorian now. He'll be wanting to pat you on the back for sure!$B$BThank you again, $N. I hope we meet again. You're surely an ally I'm proud to call friend.",logDesc="Speak to Duthorian Rall in Stormwind."} end
if not DB[1789] then DB[1789]={id=1789,zoneId=-141,name="The Symbol of Life",level=-1,minLevel=12,giver="Tiza Battleforge",giverType="NPC",giverId=6179,ender="Tiza Battleforge",enderType="NPC",enderId=6179,poiX=-4634,poiY=-932,wowhead="https://www.wowhead.com/wotlk/quest=1789",image="assets/images/quests/placeholder.png",rewards={{id=6866,qty=1}}} end
if not DB[1790] then DB[1790]={id=1790,zoneId=-141,name="The Symbol of Life",level=-1,minLevel=12,giver="Duthorian Rall",giverType="NPC",giverId=6171,ender="Duthorian Rall",enderType="NPC",enderId=6171,poiX=-8546,poiY=846,wowhead="https://www.wowhead.com/wotlk/quest=1790",image="assets/images/quests/placeholder.png",rewards={{id=6866,qty=1}}} end
if not DB[1791] then DB[1791]={id=1791,zoneId=-81,name="The Windwatcher",level=30,minLevel=30,giver="Klannoc Macleod",giverType="NPC",giverId=6236,ender="Bath'rah the Windwatcher",enderType="NPC",enderId=6176,rewardNextId=1712,poiX=-1709,poiY=-4330,wowhead="https://www.wowhead.com/wotlk/quest=1791",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Now that you've learned your berserker's stance, you'll want a nice weapon to use it with.$B$BTalk to Bath'rah the Windwatcher, a troll hermit who lives between the Alterac Mountains and the Western Plaguelands.  He is a skilled weapon maker and a powerful shaman.$B$BTo find Bath'rah, go to the river that flows along Tarren Mill's eastern flank.  Follow it north--Bath'rah is camped near ruins that rest along the river's eastern bank.",logDesc="Speak with Bath'rah the Windwatcher."} end
if not DB[1792] then DB[1792]={id=1792,zoneId=-81,name="Whirlwind Weapon",level=40,minLevel=30,giver="Bath'rah the Windwatcher",giverType="NPC",giverId=6176,ender="Bath'rah the Windwatcher",enderType="NPC",enderId=6176,poiX=251,poiY=-1471,wowhead="https://www.wowhead.com/wotlk/quest=1792",image="assets/images/quests/placeholder.png",xpDiff=6,choiceRewards={{id=6975,qty=1},{id=6977,qty=1},{id=6976,qty=1}}} end
if not DB[1793] then DB[1793]={id=1793,zoneId=-141,name="The Tome of Valor",level=-1,minLevel=20,giver="Duthorian Rall",giverType="NPC",giverId=6171,ender="Duthorian Rall",enderType="NPC",enderId=6171,poiX=-8546,poiY=846,wowhead="https://www.wowhead.com/wotlk/quest=1793",image="assets/images/quests/placeholder.png",rewards={{id=6776,qty=1}}} end
if not DB[1794] then DB[1794]={id=1794,zoneId=-141,name="The Tome of Valor",level=-1,minLevel=20,giver="Brandur Ironhammer",giverType="NPC",giverId=5149,ender="Brandur Ironhammer",enderType="NPC",enderId=5149,poiX=-4602,poiY=-896,wowhead="https://www.wowhead.com/wotlk/quest=1794",image="assets/images/quests/placeholder.png",rewards={{id=6776,qty=1}}} end
if not DB[1795] then DB[1795]={id=1795,zoneId=-61,name="The Binding",level=-1,minLevel=30,giver="Strahad Farsan",giverType="NPC",giverId=6251,ender="Strahad Farsan",enderType="NPC",enderId=6251,poiX=-786,poiY=-3723,wowhead="https://www.wowhead.com/wotlk/quest=1795",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If you are sufficiently prepared, then we should begin. Let me explain the process to you.$b$bI will begin by creating the basic summoning circle. When that is finished, my acolytes will use the rods of channeling to create the greater circle.$b$bOnce that is done, read the incantation from the Tome of the Cabal, and the felhunter will be pulled forth. Be careful, $n. A felhunter is a powerful foe, and I'd like to see you keep your head on your shoulders.",logDesc="Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.",rewards={{id=22244,qty=1}}} end
if not DB[1796] then DB[1796]={id=1796,zoneId=-61,name="Components for the Enchanted Gold Bloodrobe",level=31,minLevel=31,giver="Menara Voidrender",giverType="NPC",giverId=6266,ender="Menara Voidrender",enderType="NPC",enderId=6266,rewardNextId=4781,poiX=-783,poiY=-3711,wowhead="https://www.wowhead.com/wotlk/quest=1796",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The first item I will aid you in creating is a robe. You will gather the items for me, and we will put them together. Afterwards, assuming you succeed, you will have the first of many items that will make you more powerful and aid you in your struggles.$B$BTo start, you must have crafted Robes of Arcana. A tailor can make this for you, or perhaps you can purchase one from someone else--I'd be most impressed if you could make it yourself--but regardless, bring me the robes, and we shall go from there.",logDesc="Bring Robes of the Arcana to Menara Voidrender in the Barrens."} end
if not DB[1798] then DB[1798]={id=1798,zoneId=-61,name="Seeking Strahad",level=-1,minLevel=30,giver="Lago Blackwrench",giverType="NPC",giverId=6120,ender="Strahad Farsan",enderType="NPC",enderId=6251,rewardNextId=1758,poiX=-4618,poiY=-1090,wowhead="https://www.wowhead.com/wotlk/quest=1798",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It is time you learned the felhunter summoning, $n. I do not have the reagents and items necessary to teach you here, so you will have to seek out another, Strahad Farsan, another of our inner circle.$b$bHe makes his residence in the goblin port of Ratchet. I will send word ahead of you to inform him of your coming.",logDesc="Speak with Strahad Farsan in the Barrens."} end
if not DB[1799] then DB[1799]={id=1799,zoneId=-61,name="Fragments of the Orb of Orahil",level=40,minLevel=35,giver="Menara Voidrender",giverType="NPC",giverId=6266,ender="Tabetha",enderType="NPC",enderId=6546,rewardNextId=4961,poiX=-783,poiY=-3711,wowhead="https://www.wowhead.com/wotlk/quest=1799",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Good, then we shall begin.$B$BThe first thing you must do is speak to my acolytes inside. Choose one of their paths to follow--they will explain more.$B$BSecond, you must travel to Desolace and find an Infernal Orb from one of the warlocks of Mannoroc Coven. It is that orb that you will cleanse with the help of a mage named Tabetha deep in southern Dustwallow Marsh. She will aid you because of our history together.$B$BAgain, do not come back until you have done both things I've asked.",logDesc="Speak to Menara's acolytes inside the tower above Ratchet and choose one of their paths to follow.$B$BAfterwards, bring an Infernal Orb to Tabetha in Dustwallow Marsh."} end
if not DB[1800] then DB[1800]={id=1800,zoneId=-284,name="Lordaeron Throne Room",level=-1,minLevel=10,ender="Orcish Orphan",enderType="NPC",enderId=14444,wowhead="https://www.wowhead.com/wotlk/quest=1800",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The orphan matrons at my home tell mighty stories of battle and lore at night if we are good and do our chores.  One story was about how Lordaeron fell, and about how the evil Arthas took his own father's life to become ruler.$B$BHe had no honor, $N!  When I grow up and become a mighty Horde warrior, my blade will be guided by honor - never evil!$B$BWould you take me to see the throne room, please?  It is just before where you would go down into the Undercity.",logDesc="Take your ward to the old Lordaeron Throne Room that lies just before descending into the Undercity.$B"} end
if not DB[1801] then DB[1801]={id=1801,zoneId=-61,name="Tome of the Cabal",level=-1,minLevel=30,giver="Strahad Farsan",giverType="NPC",giverId=6251,ender="Jorah Annison",enderType="NPC",enderId=6293,rewardNextId=1803,poiX=-786,poiY=-3723,wowhead="https://www.wowhead.com/wotlk/quest=1801",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.$b$bMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.$b$bPerhaps Jorah Annison can help you with this. He's employed as a cartographer in the Undercity these days, but still knows more of ancient texts than any I know.",logDesc="Speak with Jorah Annison in the Undercity."} end
if not DB[1802] then DB[1802]={id=1802,zoneId=-61,name="Tome of the Cabal",level=-1,minLevel=30,giver="Krom Stoutarm",giverType="NPC",giverId=6294,ender="Krom Stoutarm",enderType="NPC",enderId=6294,rewardNextId=1804,poiX=-4619,poiY=-1300,wowhead="https://www.wowhead.com/wotlk/quest=1802",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It was lost, but there's some idea as to where it might be found.$b$bThere was only one copy ever made and it was vandalized at some point, a large portion of it ripped from the binding. Rumor has it that it somehow passed into the hands of the centaur of Thousand Needles.$b$bThe rest was lost off the coast west of Southshore, where it was to be transported to Menethil Harbor by boat. It never arrived.$b$bIn exchange for this knowledge, all I ask is that if you find it, bring it to me to see.",logDesc="Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge."} end
if not DB[1803] then DB[1803]={id=1803,zoneId=-61,name="Tome of the Cabal",level=-1,minLevel=30,giver="Jorah Annison",giverType="NPC",giverId=6293,ender="Jorah Annison",enderType="NPC",enderId=6293,rewardNextId=1805,poiX=1635,poiY=145,wowhead="https://www.wowhead.com/wotlk/quest=1803",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Ah! I see that you are a warlock of similar tastes to mine. Indeed, acquiring the Tome of the Cabal is a worthy aspiration. Did you know that it was once held within the walls of Lordaeron? It was vandalized though, almost half its pages removed. Who would commit such a heinous act?$b$bThat half is lost, though rumor says that it fell into the hands of the centaur of the Thousand Needles.$b$bThe rest of the text was to be transferred to Ironforge, but was lost in transit on the coast west of Southshore.",logDesc="Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity."} end
if not DB[1804] then DB[1804]={id=1804,zoneId=-61,name="Tome of the Cabal",level=-1,minLevel=30,giver="Krom Stoutarm",giverType="NPC",giverId=6294,ender="Strahad Farsan",enderType="NPC",enderId=6251,rewardNextId=1795,poiX=-4619,poiY=-1300,wowhead="https://www.wowhead.com/wotlk/quest=1804",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Well, ah, it's hard to let it go. But you found it, and you have more important things to do with it, of course. Just, please, be sure to mention to Strahad that I wanted a copy.$b$bWhile you were out, he sent a message for you. He wanted me to tell you that for his acolytes to assist with the summoning, you'll have to acquire three rods of channeling.$b$bHe might not know where to find them, but I do! They were last used by the orcs of the Dragonmaw clan in the Wetlands. I'd check their spellcasters!",logDesc="Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet."} end
if not DB[1805] then DB[1805]={id=1805,zoneId=-61,name="Tome of the Cabal",level=-1,minLevel=30,giver="Jorah Annison",giverType="NPC",giverId=6293,ender="Strahad Farsan",enderType="NPC",enderId=6251,rewardNextId=1795,poiX=1635,poiY=145,wowhead="https://www.wowhead.com/wotlk/quest=1805",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This is one of the most interesting texts I have perused in the last few years. The selection here is sparse--mostly books on geography--and I have already read them all. I should hope that Strahad would send me a copy of this tome when he has the chance.$b$bSpeaking of him, he sent word to me while you were away. For your task, you must obtain three rods of channeling.$b$bFor allowing me to look at this text, I will share a secret: You can find the rods on orcs of the Dragonmaw Clan in the Wetlands.",logDesc="Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet."} end
if not DB[1806] then DB[1806]={id=1806,zoneId=-141,name="The Test of Righteousness",level=22,minLevel=20,giver="Jordan Stilwell",giverType="NPC",giverId=6181,ender="Jordan Stilwell",enderType="NPC",enderId=6181,poiX=-5089,poiY=-783,wowhead="https://www.wowhead.com/wotlk/quest=1806",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all.$B$BWhen we're done, you'll be far more prepared to defend the Light than you have been, this much I swear.$B$BI'll be somewhat honest, $N, seeing the results of your exploits makes me somewhat envious. But knowing that I can contribute to your adventures in my own significant way does bring me some joy.",logDesc="Wait for Jordan Stilwell to finish forging a weapon for you.",rewards={{id=6953,qty=1}}} end
if not DB[1818] then DB[1818]={id=1818,zoneId=-81,name="Speak with Dillinger",level=-1,minLevel=10,giver="Austil de Mon",giverType="NPC",giverId=2131,ender="Deathguard Dillinger",enderType="NPC",enderId=1496,rewardNextId=1819,poiX=2255,poiY=238,wowhead="https://www.wowhead.com/wotlk/quest=1818",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I was told Deathguard Dillinger has a job for someone like you.  If you're willing to show your value to the Dark Lady's forces, then report to Dillinger immediately.$B$BDeathguard Dillinger's post is on the west end of Brill, near the graveyard.",logDesc="Speak with Deathguard Dillinger in Brill."} end
if not DB[1819] then DB[1819]={id=1819,zoneId=-81,name="Ulag the Cleaver",level=-1,minLevel=10,giver="Deathguard Dillinger",giverType="NPC",giverId=1496,ender="Deathguard Dillinger",enderType="NPC",enderId=1496,rewardNextId=1820,poiX=2288,poiY=403,wowhead="https://www.wowhead.com/wotlk/quest=1819",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When the Scourge swept through Tirisfal Glades, we captured one to study.  He had a free mind, and called himself Ulag the Cleaver.  But, although his will was free, he was still enthralled by the Lich King.$B$BWe hoped to find a way to break the king's control over Ulag, but we failed.  Now, finally, it is time to free him.  $B$BFree him, and kill him.$B$BActivate the skull stone trigger near the mausoleum to the north.  This will lift the magical seal that binds him.$B$BThen... be ready, $N.",logDesc="Kill Ulag the Cleaver, then speak with Deathguard Dillinger."} end
if not DB[1820] then DB[1820]={id=1820,zoneId=-81,name="Speak with Coleman",level=10,minLevel=10,giver="Deathguard Dillinger",giverType="NPC",giverId=1496,ender="Coleman Farthing",enderType="NPC",enderId=1500,rewardNextId=1821,poiX=2288,poiY=403,wowhead="https://www.wowhead.com/wotlk/quest=1820",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You have proven your value to the Dark Lady, now perhaps you can prove yourself to one of her subjects.$B$BColeman Farthing awaits a warrior who is willing to be his instrument of revenge against the Forsaken's enemies.$B$BYou will find him in the Gallow's End Tavern in eastern Brill.",logDesc="Speak with Coleman Farthing."} end
if not DB[1821] then DB[1821]={id=1821,zoneId=-81,name="Agamand Heirlooms",level=11,minLevel=10,giver="Coleman Farthing",giverType="NPC",giverId=1500,ender="Coleman Farthing",enderType="NPC",enderId=1500,poiX=2262,poiY=244,wowhead="https://www.wowhead.com/wotlk/quest=1821",image="assets/images/quests/placeholder.png",xpDiff=4,money=300,desc="The Agamand family were my employers in life, and they were the cause of my death!  It is fitting that the Agamands are now mindless minions of the Lich King.$B$BNow I would have their last vestiges of honor.  Go into their family crypt and rob them of their family heirlooms: a sword, an axe, a dagger and a mace.  Bring them to me!$B$BThe Agamand family crypt is at the north end of the Agamand mills, protected by lurking Scourge and dead Agamands.",logDesc="Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger."} end
if not DB[1822] then DB[1822]={id=1822,zoneId=-81,name="Heirloom Weapon",level=11,minLevel=10,giver="Coleman Farthing",giverType="NPC",giverId=1500,ender="Coleman Farthing",enderType="NPC",enderId=1500,poiX=2262,poiY=244,wowhead="https://www.wowhead.com/wotlk/quest=1822",image="assets/images/quests/placeholder.png",xpDiff=5,choiceRewards={{id=7115,qty=1},{id=7117,qty=1},{id=7116,qty=1},{id=7118,qty=1}}} end
if not DB[1823] then DB[1823]={id=1823,zoneId=-81,name="Speak with Ruga",level=20,minLevel=20,giver="Sorek",giverType="NPC",giverId=3354,ender="Ruga Ragetotem",enderType="NPC",enderId=6394,rewardNextId=1824,poiX=1971,poiY=-4808,wowhead="https://www.wowhead.com/wotlk/quest=1823",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You are a warrior of skill and growing renown.  Perhaps you are ready for Ruga Ragetotem's trial?  If so, then find Ruga in Camp Taurajo in the Barrens.$B$BHe awaits those warriors who answer his call.",logDesc="Speak with Ruga Ragetotem."} end
if not DB[1824] then DB[1824]={id=1824,zoneId=-81,name="Trial at the Field of Giants",level=20,minLevel=20,giver="Ruga Ragetotem",giverType="NPC",giverId=6394,ender="Ruga Ragetotem",enderType="NPC",enderId=6394,rewardNextId=1825,poiX=-2402,poiY=-1904,wowhead="https://www.wowhead.com/wotlk/quest=1824",image="assets/images/quests/placeholder.png",xpDiff=5,desc="To pass this trial, you must travel south to the Field of Giants.  There you will find a host of crawling, insect creatures.  They are new to the Barrens and I do not like what they herald.$B$BBring me their still-twitching antennae, and waste no time, $N, for harvested antennae will not twitch for long.  Bring me the antennae in the time allowed, and you will pass the trial.",logDesc="Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo",rewards={{id=7120,qty=1}}} end
if not DB[1825] then DB[1825]={id=1825,zoneId=-81,name="Speak with Thun'grim",level=20,minLevel=20,giver="Ruga Ragetotem",giverType="NPC",giverId=6394,ender="Thun'grim Firegaze",enderType="NPC",enderId=5878,rewardNextId=1838,poiX=-2402,poiY=-1904,wowhead="https://www.wowhead.com/wotlk/quest=1825",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Thun'grim Firegaze, an orc blacksmith of renown, has heard of your continued deeds of valor in service of the Horde.  He would like to fashion for you a suit of armor, and bids you speak with him immediately.$B$BThun'grim is camped east of the Crossroads in the Barrens.",logDesc="Speak with Thun'grim Firegaze in the Barrens."} end
if not DB[1838] then DB[1838]={id=1838,zoneId=-81,name="Brutal Armor",level=30,minLevel=20,giver="Thun'grim Firegaze",giverType="NPC",giverId=5878,ender="Thun'grim Firegaze",enderType="NPC",enderId=5878,poiX=-438,poiY=-3176,wowhead="https://www.wowhead.com/wotlk/quest=1838",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I have heard tales of your strength and valor, and wish to make for you a suit of armor, a companion to aid you as tales of your great deeds grow.$B$BBut the fashioning of this armor will be a quest unto itself, $N.  I will need your help, and the help of other smiths of the Horde.$B$BHere, take this scroll.  I spent many nights, struggling with near-blind eyes, writing that which I need for the armor.  Bring me the items on this scroll and I will create for you the first piece of the suit.",logDesc="Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston."} end
if not DB[1839] then DB[1839]={id=1839,zoneId=-81,name="Ula'elek and the Brutal Gauntlets",level=30,minLevel=20,giver="Thun'grim Firegaze",giverType="NPC",giverId=5878,ender="Ula'elek",enderType="NPC",enderId=6408,rewardNextId=1842,poiX=-438,poiY=-3176,wowhead="https://www.wowhead.com/wotlk/quest=1839",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The troll smith Ula'elek will craft for you the brutal gauntlets.  He dwells in Durotar, in Sen'jin Village with his Darkspear brethren, and he awaits your coming.",logDesc="Speak with Ula'elek in Durotar."} end
if not DB[1840] then DB[1840]={id=1840,zoneId=-81,name="Orm Stonehoof and the Brutal Helm",level=30,minLevel=20,giver="Thun'grim Firegaze",giverType="NPC",giverId=5878,ender="Orm Stonehoof",enderType="NPC",enderId=6410,rewardNextId=1844,poiX=-438,poiY=-3176,wowhead="https://www.wowhead.com/wotlk/quest=1840",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Orm Stonehoof is respected greatly for his skill.  He will make for you the brutal helm.$B$BSeek him out in Thunder Bluff, near the pool by the city's great, central totem.",logDesc="Speak with Orm Stonehoof in Thunder Bluff."} end
if not DB[1841] then DB[1841]={id=1841,zoneId=-81,name="Velora Nitely and the Brutal Legguards",level=30,minLevel=20,giver="Thun'grim Firegaze",giverType="NPC",giverId=5878,ender="Velora Nitely",enderType="NPC",enderId=6411,rewardNextId=1846,poiX=-438,poiY=-3176,wowhead="https://www.wowhead.com/wotlk/quest=1841",image="assets/images/quests/placeholder.png",xpDiff=3,desc="It is said that, before her death, Velora Nitely was one of the finest armorsmiths in Lordaeron.  Death, it seems, has not decreased her talents.  Speak with Velora--she will make your brutal legguards.$B$BVelora plies her trade in the Undercity of Lordaeron, in the trade quarter.",logDesc="Speak with Velora Nitely in the Undercity."} end
if not DB[1842] then DB[1842]={id=1842,zoneId=-81,name="Satyr Hooves",level=30,minLevel=20,giver="Ula'elek",giverType="NPC",giverId=6408,ender="Ula'elek",enderType="NPC",enderId=6408,poiX=-811,poiY=-4940,wowhead="https://www.wowhead.com/wotlk/quest=1842",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I can make you a pair of brutal gauntlets, and great magic will they hold.  But first, you must collect this magic and bring it to me.$B$BThe satyrs dwell in northeastern Ashenvale because of the forest's power.  They feed off its purity, leeching and corrupting.  You can tell which satyrs have drawn the most of Ashenvale's magic by their swollen, uncloven hooves.$B$BThese hooves hold great power.  I will need them for your gauntlets' crafting.",logDesc="Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar."} end
if not DB[1843] then DB[1843]={id=1843,zoneId=-81,name="Brutal Gauntlets",level=30,minLevel=20,giver="Ula'elek",giverType="NPC",giverId=6408,ender="Ula'elek",enderType="NPC",enderId=6408,poiX=-811,poiY=-4940,wowhead="https://www.wowhead.com/wotlk/quest=1843",image="assets/images/quests/placeholder.png",xpDiff=4,rewards={{id=7129,qty=1}}} end
if not DB[1844] then DB[1844]={id=1844,zoneId=-81,name="Chimaeric Horn",level=30,minLevel=20,giver="Orm Stonehoof",giverType="NPC",giverId=6410,ender="Orm Stonehoof",enderType="NPC",enderId=6410,poiX=-1240,poiY=110,wowhead="https://www.wowhead.com/wotlk/quest=1844",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I will make you the helm, but you must show me you are worthy of it.$B$BNestled in the southwestern reaches of the Stonetalon Mountains lies the Charred Vale.  It was once a verdant place, but is now defiled and ashen, and what creatures remain there are mad with pain and despair.$B$BThat place is where I send you, $N.$B$BYou must go to the Charred Vale and find a chimaera matriarch.  Slay her, free her of her misery.  Bring me her galvanized horn as proof, and I shall make for you the helm. ",logDesc="Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff."} end
if not DB[1845] then DB[1845]={id=1845,zoneId=-81,name="Brutal Helm",level=30,minLevel=20,giver="Orm Stonehoof",giverType="NPC",giverId=6410,ender="Orm Stonehoof",enderType="NPC",enderId=6410,poiX=-1240,poiY=110,wowhead="https://www.wowhead.com/wotlk/quest=1845",image="assets/images/quests/placeholder.png",xpDiff=4,rewards={{id=7130,qty=1}}} end
if not DB[1846] then DB[1846]={id=1846,zoneId=-81,name="Dragonmaw Shinbones",level=30,minLevel=20,giver="Velora Nitely",giverType="NPC",giverId=6411,ender="Velora Nitely",enderType="NPC",enderId=6411,poiX=1627,poiY=277,wowhead="https://www.wowhead.com/wotlk/quest=1846",image="assets/images/quests/placeholder.png",xpDiff=3,desc="To make the brutal leg guards, I need a brace of sturdy shinbones.  The Dragonmaw orcs of the Wetlands have nice, thick shinbones.  I'll need theirs.$B$BBut they must be sturdy.  Be sure to test the shinbones as you collect them.  If you can break them with your bare hands, then they won't be sturdy enough to work with.",logDesc="Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity."} end
if not DB[1847] then DB[1847]={id=1847,zoneId=-81,name="Brutal Legguards",level=30,minLevel=20,giver="Velora Nitely",giverType="NPC",giverId=6411,ender="Velora Nitely",enderType="NPC",enderId=6411,poiX=1627,poiY=277,wowhead="https://www.wowhead.com/wotlk/quest=1847",image="assets/images/quests/placeholder.png",xpDiff=4,rewards={{id=7132,qty=1}}} end
if not DB[1848] then DB[1848]={id=1848,zoneId=-81,name="Brutal Hauberk",level=30,minLevel=20,giver="Thun'grim Firegaze",giverType="NPC",giverId=5878,ender="Thun'grim Firegaze",enderType="NPC",enderId=5878,poiX=-438,poiY=-3176,wowhead="https://www.wowhead.com/wotlk/quest=1848",image="assets/images/quests/placeholder.png",xpDiff=6,rewards={{id=7133,qty=1}}} end
if not DB[1858] then DB[1858]={id=1858,zoneId=-162,name="The Shattered Hand",level=13,minLevel=10,giver="Therzok",giverType="NPC",giverId=6446,ender="Therzok",enderType="NPC",enderId=6446,poiX=1773,poiY=-4280,wowhead="https://www.wowhead.com/wotlk/quest=1858",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I'll leave it to you to get Tazan's satchel open, and return to me with its contents. The locking mechanism is complex, so it would probably be easiest if you obtained the key.$b$bAs you didn't find it on Tazan's body, I can only assume that he left the key in the care of another... Ah, yes, that's right. He had an assistant named Gamon. A drunkard, you'll most likely find him at the tavern. Perhaps you could quietly relieve him of the key.",logDesc="Steal Tazan's key, then use it to open his Satchel and deliver its contents to Therzok in the Cleft of Shadow in Orgrimmar.",rewards={{id=7298,qty=1}}} end
if not DB[1859] then DB[1859]={id=1859,zoneId=-162,name="Therzok",level=10,minLevel=10,giver="Kaplak",giverType="NPC",giverId=3170,ender="Therzok",enderType="NPC",enderId=6446,rewardNextId=1963,poiX=268,poiY=-4711,wowhead="https://www.wowhead.com/wotlk/quest=1859",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Lower your voice, $n. Yeah, I know your name. Was told to keep an eye out for an orc by your description.$b$bFrom what we've heard about you, you can handle yourself in combat, and aren't opposed to a little sneakery from time to time.$b$bAm I right?$b$bAnyways, you should go see Therzok in Orgrimmar. He's got an offer for you to hear.",logDesc="Speak with Therzok in the Cleft of Shadow in Orgrimmar."} end
if not DB[1860] then DB[1860]={id=1860,zoneId=-161,name="Speak with Jennea",level=10,minLevel=10,giver="Zaldimar Wefhellt",giverType="NPC",giverId=328,ender="Jennea Cannon",enderType="NPC",enderId=5497,rewardNextId=1861,poiX=-9472,poiY=34,wowhead="https://www.wowhead.com/wotlk/quest=1860",image="assets/images/quests/placeholder.png",xpDiff=3,desc="We mages have a task that needs doing.  One that is vital to the safety of Stormwind and Elwynn forest.$B$BJennea Cannon has the details.  She studies in the wizard's sanctum, in the mage district of Stormwind.  You should make your way to her with haste.",logDesc="Speak with Jennea Cannon in Stormwind."} end
if not DB[1861] then DB[1861]={id=1861,zoneId=-161,name="Mirror Lake",level=10,minLevel=10,giver="Jennea Cannon",giverType="NPC",giverId=5497,ender="Jennea Cannon",enderType="NPC",enderId=5497,poiX=-8990,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1861",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This world has been victim to massive mystic struggles, which tore magic currents from once stable channels.  We struggle to determine the effects these changes have caused, and some of us fear the worst!$B$BBut I will reveal more of this later.  Right now, we need you to gather information.$B$BHere, take this flask.  Go to the base of the waterfall at Mirror Lake, southwest of the Stormwind gates, and retrieve a sample of the water there.  Return it to me so that I might test it for magical taints.",logDesc="Bring a Mirror Lake sample to Jennea Cannon in Stormwind.",choiceRewards={{id=7508,qty=1},{id=9513,qty=1}}} end
if not DB[1878] then DB[1878]={id=1878,zoneId=440,name="Water Pouch Bounty",level=44,minLevel=40,giver="Spigot Operator Luglunket",giverType="NPC",giverId=7408,ender="Spigot Operator Luglunket",enderType="NPC",enderId=7408,poiX=-7183,poiY=-3840,wowhead="https://www.wowhead.com/wotlk/quest=1878",image="assets/images/quests/placeholder.png",rewards={{id=8484,qty=1}}} end
if not DB[1879] then DB[1879]={id=1879,zoneId=-161,name="Speak with Bink",level=10,minLevel=10,giver="Magis Sparkmantle",giverType="NPC",giverId=1228,ender="Bink",enderType="NPC",enderId=5144,rewardNextId=1880,poiX=-5587,poiY=-537,wowhead="https://www.wowhead.com/wotlk/quest=1879",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N!  Bink, my gnome colleague in Ironforge, sends word.  She has a task that needs doing and won't rely on anyone but a mage to do it!  Are you that mage, $N?$B$BIf so, then speak with Bink.  She spends her time in the Hall of Mysteries in the Mystic Ward of Ironforge.",logDesc="Speak with Bink in Ironforge."} end
if not DB[1880] then DB[1880]={id=1880,zoneId=-161,name="Mage-tastic Gizmonitor",level=10,minLevel=10,giver="Bink",giverType="NPC",giverId=5144,ender="Bink",enderType="NPC",enderId=5144,poiX=-4613,poiY=-929,wowhead="https://www.wowhead.com/wotlk/quest=1880",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We mages do more than just waggle our fingers and make pretty sparks!  We control magic, the base fabric of our world!  And that takes great care, and resolve.  And knowledge... so much knowledge!$B$BOne of my devices, the mage-tastic gizmonitor, collects and stores that knowledge in huge amounts!  But it's lost!  When we fled our home of Gnomeregan, I left it in a chest in one of our huts outside the city, and now the place is crawling with leper gnomes!$B$BPlease, $N, retrieve my gizmonitor!",logDesc="Bring Bink her Mage-tastic Gizmonitor.",choiceRewards={{id=7507,qty=1},{id=9514,qty=1}}} end
if not DB[1881] then DB[1881]={id=1881,zoneId=-161,name="Speak with Anastasia",level=10,minLevel=10,giver="Cain Firesong",giverType="NPC",giverId=2128,ender="Anastasia Hartwell",enderType="NPC",enderId=4568,rewardNextId=1882,poiX=2257,poiY=233,wowhead="https://www.wowhead.com/wotlk/quest=1881",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N, Anastasia Hartwell has a task for someone of your talents.  Speak with her in the Magic Quarter of the Undercity, and prepare yourself for your first task for the mages of the Forsaken.",logDesc="Speak with Anastasia Hartwell."} end
if not DB[1882] then DB[1882]={id=1882,zoneId=-161,name="The Balnir Farmstead",level=10,minLevel=10,giver="Anastasia Hartwell",giverType="NPC",giverId=4568,ender="Anastasia Hartwell",enderType="NPC",enderId=4568,poiX=1814,poiY=56,wowhead="https://www.wowhead.com/wotlk/quest=1882",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Plaguelands to the east are an aberration.  Devised by the Lich King, they spread their magic into the soil, corrupting and killing all that live.  Although there is a certain charm to the destructive forces of the plague, we, the mages of the Forsaken, believe it is unruly and must be curtailed.$B$BBut first, we must measure how far it has spread into Tirisfal.  Go to the Balnir Farmstead in eastern Tirisfal.  In the garden are flowers--snapdragons.  Gather these and return.",logDesc="Bring Balnir Snapdragons to Anastasia Hartwell in the Mage Quarter of the Undercity.",choiceRewards={{id=7507,qty=1},{id=9514,qty=1}}} end
if not DB[1883] then DB[1883]={id=1883,zoneId=-161,name="Speak with Un'thuwa",level=10,minLevel=10,giver="Uthel'nay",giverType="NPC",giverId=7311,ender="Un'Thuwa",enderType="NPC",enderId=5880,rewardNextId=1884,poiX=1467,poiY=-4230,wowhead="https://www.wowhead.com/wotlk/quest=1883",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Un'thuwa, tribal mage of Sen'jin Village, detects a disturbance in the magic currents of Durotar and asks for aid.  Speak with Un'thuwa and do what you can to help him.$B$BDo this, and in time further secrets will be revealed to you.",logDesc="Speak with Un'thuwa."} end
if not DB[1884] then DB[1884]={id=1884,zoneId=-161,name="Ju-Ju Heaps",level=10,minLevel=10,giver="Un'Thuwa",giverType="NPC",giverId=5880,ender="Un'Thuwa",enderType="NPC",enderId=5880,poiX=-839,poiY=-4940,wowhead="https://www.wowhead.com/wotlk/quest=1884",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The warlock Zalazane of the Echo Isles has disrupted the normal flow of magic in Durotar.  He does this through tainted fetishes, ju-ju heaps, which he has placed among his huts on the main Echo Isle.$B$BThese heaps corrupt our wildlife and give power to the warlocks and infernal creatures that lurk in the land's dark corners.$B$BYou must destroy the ju-ju heaps, $N, before the flow of magic is forever altered.",logDesc="Destroy 4 Ju-Ju Heaps, then return to Un'thuwa in Sen'jin Village.",choiceRewards={{id=7508,qty=1},{id=9513,qty=1}}} end
if not DB[1885] then DB[1885]={id=1885,zoneId=-162,name="Mennet Carkad",level=10,minLevel=10,giver="Marion Call",giverType="NPC",giverId=2130,ender="Mennet Carkad",enderType="NPC",enderId=6467,rewardNextId=1886,poiX=2271,poiY=243,wowhead="https://www.wowhead.com/wotlk/quest=1885",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$n? Not quite what I was expecting, considering Carkad himself has taken an interest to you. Looks can be deceiving though, right?$b$bEither way, you should go see him as soon as possible. You wouldn't want to know what happened to the last few that chose to ignore his summons.",logDesc="Speak with Mennet Carkad in the Rogues' Quarter of the Undercity."} end
if not DB[1886] then DB[1886]={id=1886,zoneId=-162,name="The Deathstalkers",level=13,minLevel=10,rewardNextId=14419,wowhead="https://www.wowhead.com/wotlk/quest=1886",image="assets/images/quests/placeholder.png",xpDiff=4,desc="If you wish to join the Deathstalkers, Lord Varimathras' elite guard, you will have to prove your worth.$b$bI will not lie to you, $n, this task could mean your death.$b$bI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion.$b$bIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more.",logDesc="Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter."} end
if not DB[1898] then DB[1898]={id=1898,zoneId=-162,name="The Deathstalkers",level=13,minLevel=10,rewardNextId=14421,wowhead="https://www.wowhead.com/wotlk/quest=1898",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious.$b$bLord Varimathras suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it.$b$bI want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium.",logDesc="Speak with Andron Gant in the Undercity."} end
if not DB[1899] then DB[1899]={id=1899,zoneId=-162,name="The Deathstalkers",level=13,minLevel=10,rewardNextId=14418,wowhead="https://www.wowhead.com/wotlk/quest=1899",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement.",logDesc="Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity."} end
if not DB[1918] then DB[1918]={id=1918,zoneId=331,name="The Befouled Element",level=27,minLevel=23,ender="Mastok Wrilehiss",enderType="NPC",enderId=12737,rewardNextId=824,wowhead="https://www.wowhead.com/wotlk/quest=1918",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The slain elemental has produced an intensely glowing globe of water.  The contents of the globe are, at best, disgusting.  It would be safe to assume that whatever has befouled the water of Mystral Lake is most likely present in the water of the globe.$B$BIt's not exactly common knowledge who might be interested in such a find; perhaps the person who originally sent you out to the lake, Mastok Wrilehiss at Splintertree Post, might have an idea.",logDesc="Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale."} end
if not DB[1919] then DB[1919]={id=1919,zoneId=-161,name="Report to Jennea",level=15,minLevel=15,giver="Zaldimar Wefhellt",giverType="NPC",giverId=328,ender="Jennea Cannon",enderType="NPC",enderId=5497,rewardNextId=1920,poiX=-9472,poiY=34,wowhead="https://www.wowhead.com/wotlk/quest=1919",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Your knowledge of the craft grows, young $N.  Are you now ready to begin your true lessons?  Are you ready to take your place in the secret war we wage?$B$BIf so, then speak with Jennea Cannon, in the wizard's sanctum in the mage district of Stormwind.  She has a task for you which will open your first window into the invisible world.",logDesc="Speak with Jennea Cannon in Stormwind."} end
if not DB[1920] then DB[1920]={id=1920,zoneId=-161,name="Investigate the Blue Recluse",level=16,minLevel=15,giver="Jennea Cannon",giverType="NPC",giverId=5497,ender="Jennea Cannon",enderType="NPC",enderId=5497,rewardNextId=1921,poiX=-8990,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1920",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A disturbance has been reported at the Blue Recluse tavern in the Mage Quarter.  Strange, invisible creatures now wander the tavern, and I fear a mana rift has formed there.$B$BI want you to investigate the tavern and capture those creatures.  Use the cantation of manifestation in the tavern to make the creatures visible, subdue them then use a containment coffer to capture them.  When you have enough, return to me with your filled coffers, your empty coffers and the cantation.",logDesc="Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon.  Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum."} end
if not DB[1921] then DB[1921]={id=1921,zoneId=-161,name="Gathering Materials",level=15,minLevel=15,giver="Jennea Cannon",giverType="NPC",giverId=5497,ender="Wynne Larson",enderType="NPC",enderId=1309,poiX=-8990,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1921",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You have served your fellow mages well, and now it is time to don your wizard's robe.  Wynne Larson can make your robe, but you must bring her the needed materials  $B$BThe robe will be made of linen which is easy to find, but you must also gain charged rift gems, and the only known location of the gems is in the Silver Stream Mine of Loch Modan, left in crates by the dwarven miners' league.$B$BGather the linen and the gems and bring them to Wynne Larson at the Larson Clothiers in the Mage District.",logDesc="Bring 10 Linen Cloth and the 6 Charged Rift Gems to Wynne Larson in Stormwind."} end
if not DB[1938] then DB[1938]={id=1938,zoneId=-161,name="Ur's Treatise on Shadow Magic",level=28,minLevel=26,giver="High Sorcerer Andromath",giverType="NPC",giverId=5694,ender="High Sorcerer Andromath",enderType="NPC",enderId=5694,rewardNextId=1940,poiX=-9011,poiY=877,wowhead="https://www.wowhead.com/wotlk/quest=1938",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Long ago, three mages studied in this tower until one fell to the dark arts.  He was urged to turn away from that evil magic, but he could not resist.  And so he was banished.$B$BThe fallen mage's new domain is the tower of Ilgalar in Redridge, and he took with him a powerful book--Ur's Treatise on Shadow Magic.$B$BWe, the mages of Stormwind, would have that book returned.  Enter the tower of Ilgalar, find the tome in his library, and bring it to me.",logDesc="Bring Ur's Treatise on Shadow Magic to High Sorcerer Andromath in Stormwind."} end
if not DB[1939] then DB[1939]={id=1939,zoneId=-161,name="High Sorcerer Andromath",level=26,minLevel=26,giver="Bink",giverType="NPC",giverId=5144,ender="High Sorcerer Andromath",enderType="NPC",enderId=5694,rewardNextId=1938,poiX=-4613,poiY=-929,wowhead="https://www.wowhead.com/wotlk/quest=1939",image="assets/images/quests/placeholder.png",xpDiff=3,desc="High Sorcerer Andromath wishes to speak with you, $N.  He is at the top of the wizard's sanctum, in the mage's district of Stormwind.$B$BIt would be wise to speak with him, for Andromath is one of the most powerful mages not locked away in Dalaran.  Council with him is high council indeed.",logDesc="Speak with High Sorcerer Andromath."} end
if not DB[1940] then DB[1940]={id=1940,zoneId=-161,name="Pristine Spider Silk",level=26,minLevel=26,giver="High Sorcerer Andromath",giverType="NPC",giverId=5694,ender="Wynne Larson",enderType="NPC",enderId=1309,poiX=-9011,poiY=877,wowhead="https://www.wowhead.com/wotlk/quest=1940",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Your service has been unwavering, $N.  I think, perhaps, it is time you had a finer garment, one more suiting your station as an adept mage.  If you gather the needed materials, then we will arrange the robe made.$B$BYou must enter Duskwood and hunt carrion recluse spiders.  Extract their silk, but only the finest, most pristine silk will do.  When you have enough, take it to Wynne Larson, here in the mage district at the Larson Clothiers.  She will craft your robe.",logDesc="Bring 8 Pristine Spider Silk to Wynne Larson in Stormwind."} end
if not DB[1941] then DB[1941]={id=1941,zoneId=-161,name="Manaweave Robe",level=15,minLevel=15,giver="Wynne Larson",giverType="NPC",giverId=1309,ender="Wynne Larson",enderType="NPC",enderId=1309,poiX=-8963,poiY=823,wowhead="https://www.wowhead.com/wotlk/quest=1941",image="assets/images/quests/placeholder.png",xpDiff=5,rewards={{id=7509,qty=1}}} end
if not DB[1942] then DB[1942]={id=1942,zoneId=-161,name="Astral Knot Garment",level=26,minLevel=26,giver="Wynne Larson",giverType="NPC",giverId=1309,ender="Wynne Larson",enderType="NPC",enderId=1309,poiX=-8963,poiY=823,wowhead="https://www.wowhead.com/wotlk/quest=1942",image="assets/images/quests/placeholder.png",xpDiff=5,choiceRewards={{id=7511,qty=1},{id=9516,qty=1}}} end
if not DB[1943] then DB[1943]={id=1943,zoneId=-161,name="Speak with Deino",level=26,minLevel=26,giver="Anastasia Hartwell",giverType="NPC",giverId=4568,ender="Deino",enderType="NPC",enderId=5885,rewardNextId=1944,poiX=1814,poiY=56,wowhead="https://www.wowhead.com/wotlk/quest=1943",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The troll mage Deino has need of your assistance, $N.  She resides in Orgrimmar, in the Darkbriar Lodge.",logDesc="Speak with Deino."} end
if not DB[1944] then DB[1944]={id=1944,zoneId=-161,name="Waters of Xavian",level=26,minLevel=26,giver="Deino",giverType="NPC",giverId=5885,ender="Deino",enderType="NPC",enderId=5885,rewardNextId=1945,poiX=1468,poiY=-4220,wowhead="https://www.wowhead.com/wotlk/quest=1944",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The fabled city of Xavian lies nestled deep within eastern Ashenvale, and tales of its ancient knowledge are well known among the learned.  It is said that the waters of Xavian hold vast magical powers.$B$BI would have a sample of those waters, from their source.$B$BTake this flask and go to Xavian.  Gather water from the bottom of its highest waterfall, and return to me.  And use care as you move through that ancient city--satyrs now hold the ruins and do not like mages prying into their affairs.",logDesc="Bring the Xavian Water Sample to Deino in Orgrimmar."} end
if not DB[1945] then DB[1945]={id=1945,zoneId=-161,name="Laughing Sisters",level=26,minLevel=26,giver="Deino",giverType="NPC",giverId=5885,ender="Kil'hala",enderType="NPC",enderId=3484,poiX=1468,poiY=-4220,wowhead="https://www.wowhead.com/wotlk/quest=1945",image="assets/images/quests/placeholder.png",xpDiff=4,desc="For your services, I have arranged for the creation of your new robes, provided you can gather the needed materials...$B$BFor these robes, you must return to Ashenvale for the locks of hair from laughing sisters--dryads who gather near the Raynewood Retreat.$B$BWhen you have their hair, bring it to Kil'hala, a troll tailor at the Crossroads in the Barrens.  He will be expecting you, and will fashion your robes.",logDesc="Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads."} end
if not DB[1946] then DB[1946]={id=1946,zoneId=-161,name="Nether-lace Garment",level=26,minLevel=26,giver="Kil'hala",giverType="NPC",giverId=3484,ender="Kil'hala",enderType="NPC",enderId=3484,poiX=-529,poiY=-2667,wowhead="https://www.wowhead.com/wotlk/quest=1946",image="assets/images/quests/placeholder.png",xpDiff=5,choiceRewards={{id=7512,qty=1},{id=9515,qty=1}}} end
if not DB[1947] then DB[1947]={id=1947,zoneId=-161,name="Journey to the Marsh",level=38,minLevel=30,giver="Jennea Cannon",giverType="NPC",giverId=5497,ender="Tabetha",enderType="NPC",enderId=6546,poiX=-8990,poiY=863,wowhead="https://www.wowhead.com/wotlk/quest=1947",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Now it is time for you to earn your mage's wand.  To begin this quest, speak with the human hermit Tabetha in Dustwallow Marsh.  You will find her shack deep in the marsh, west of Theramore.$B$BSpeak with her, for her knowledge is vast.  You will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruins.",logDesc="Speak with Tabetha."} end
if not DB[1948] then DB[1948]={id=1948,zoneId=-161,name="Items of Power",level=40,minLevel=30,giver="Tabetha",giverType="NPC",giverId=6546,ender="Tabetha",enderType="NPC",enderId=6546,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=1948",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The building of a mage's wand is not easy.  Rare substances are required, and a vessel must be made that can store great quantities of magical energy.  You must gather these things and bring them to me.$B$BI have written onto this parchment that which you need, and instructions on how to get it.  Bring me exactly what is on this list, and follow my written directions to the letter, for if you do not then when we make your wand things might go... badly.",logDesc="Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh."} end
if not DB[1949] then DB[1949]={id=1949,zoneId=-161,name="Hidden Secrets",level=38,minLevel=30,giver="Tabetha",giverType="NPC",giverId=6546,ender="Magus Tirth",enderType="NPC",enderId=6548,rewardNextId=1950,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=1949",image="assets/images/quests/placeholder.png",xpDiff=3,desc="To make your wand, there are key passages in a certain book that I must read.  The book is called Rituals of Power, written by the Magus Tirth.$B$BI do not have a copy of his book, and none of the world's great libraries possess it.  So you must speak with Tirth and gain it from him.$B$BGood luck.  Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling.",logDesc="Speak with Magus Tirth in the Shimmering Flats."} end
if not DB[1950] then DB[1950]={id=1950,zoneId=-161,name="Get the Scoop",level=30,minLevel=30,giver="Magus Tirth",giverType="NPC",giverId=6548,ender="Magus Tirth",enderType="NPC",enderId=6548,rewardNextId=1951,poiX=-6187,poiY=-3878,wowhead="https://www.wowhead.com/wotlk/quest=1950",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I can help you with the book, but first you have to help me!$B$BThe tome you seek is in my magically locked strongbox.  To open it a special phrase must be uttered, and I can't remember the phrase!  Normally my assistant helps me remember these things but he's nowhere to be found.$B$BIf you want my book, then find my apprentice!  Ask around the race track--if you're lucky then someone has seen him.  Either drag him back here, or at least get my magic phrase from him so we can open my box!",logDesc="Find the phrase to Tirth's strongbox, then return to Tirth."} end
if not DB[1951] then DB[1951]={id=1951,zoneId=-161,name="Rituals of Power",level=40,minLevel=30,giver="Magus Tirth",giverType="NPC",giverId=6548,ender="Tabetha",enderType="NPC",enderId=6546,poiX=-6187,poiY=-3878,wowhead="https://www.wowhead.com/wotlk/quest=1951",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Hm... now that I think about it, I don't have my book!  You see, I had some gambling debts and to pay them off I sold the last copy of Rituals of Power to a member of the clergy....$B$BA member of the Scarlet Brotherhood.  He must have taken it to their library in the Scarlet Monastery in Tirisfal Glades!$B$BIf you want that book, then you'll have to go to the monastery to find it.  And sorry about all the trouble.  I'm not myself these days...",logDesc="Bring the book Rituals of Power to Tabetha in Dustwallow Marsh."} end
if not DB[1952] then DB[1952]={id=1952,zoneId=-161,name="Mage's Wand",level=40,minLevel=30,giver="Tabetha",giverType="NPC",giverId=6546,ender="Tabetha",enderType="NPC",enderId=6546,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=1952",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'll go make the wands now.",logDesc="Speak with Tabetha after her ritual.",choiceRewards={{id=7514,qty=1},{id=11263,qty=1},{id=7513,qty=1}}} end
if not DB[1953] then DB[1953]={id=1953,zoneId=-161,name="Return to the Marsh",level=40,minLevel=35,giver="Anastasia Hartwell",giverType="NPC",giverId=4568,ender="Tabetha",enderType="NPC",enderId=6546,rewardNextId=1954,poiX=1814,poiY=56,wowhead="https://www.wowhead.com/wotlk/quest=1953",image="assets/images/quests/placeholder.png",xpDiff=1,desc="It is time, $N, for you to speak with Tabetha... the hermit of Dustwallow Marsh.  She will instruct you on the creation of a powerful mage's implement.$B$BTabetha's shack lies deep in Dustwallow Marsh, west of Theramore.",logDesc="Speak with Tabetha."} end
if not DB[1954] then DB[1954]={id=1954,zoneId=-161,name="The Infernal Orb",level=40,minLevel=35,giver="Tabetha",giverType="NPC",giverId=6546,ender="Tabetha",enderType="NPC",enderId=6546,rewardNextId=1955,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=1954",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The first step is to acquire an orb with power.  The warlocks of the Burning Blade have nice, high quality orbs... it's too bad they've bound demons into them!  But we can fix that, yes we can.$B$BGo to Desolace and snatch an infernal orb from a Burning Blade summoner.  You'll find summoners at the Mannoroc Coven.$B$BWhen you have the orb, return to me.",logDesc="Bring an Infernal Orb to Tabetha in Dustwallow Marsh."} end
if not DB[1955] then DB[1955]={id=1955,zoneId=-161,name="The Exorcism",level=40,minLevel=35,giver="Tabetha",giverType="NPC",giverId=6546,ender="Tabetha",enderType="NPC",enderId=6546,rewardNextId=1956,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=1955",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Now that we have a summoner's orb, we must exorcise the demon within it.  I can do that.  That's the easy part.$B$BYou're the one who has the hard job.  You're the one who has to kill the demon once it's out.$B$BAnd you'll have to be quick.  If you take too long then he'll jump back in the orb and we'll have to start over!$B$BSo get yourself ready.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty.",logDesc="Kill the Demon of the Orb, then speak with Tabetha."} end
if not DB[1956] then DB[1956]={id=1956,zoneId=-161,name="Power in Uldaman",level=40,minLevel=35,giver="Tabetha",giverType="NPC",giverId=6546,ender="Tabetha",enderType="NPC",enderId=6546,rewardNextId=1957,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=1956",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Now that the demon has been removed, we must gain a power source.  Unfortunately, the best power sources are usually the oldest and the hardest to get.  It's neat how fate likes to take a bite out of you sometimes, isn't it?$B$BSo you're going to need to go to Uldaman and defeat the obsidian sentinel there.  He's big, he's tough, and his power source packs a punch!$B$BI wish you the best of luck, $N.  And if you don't get lucky then, well... it was nice knowing you.",logDesc="Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh."} end
if not DB[1957] then DB[1957]={id=1957,zoneId=-161,name="Mana Surges",level=40,minLevel=35,giver="Tabetha",giverType="NPC",giverId=6546,ender="Tabetha",enderType="NPC",enderId=6546,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=1957",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We are almost finished, but this last step is the most perilous, $N.$B$BI have the empty summoner's orb and am ready to empower it.  We will do this by harnessing the energy of a mana rift.  I'll cast a spell that will temporarily open a rift, from which creatures, mana surges, will pour out.  You must defeat the mana surges and their power will be released, which I will then collect.$B$BKill enough mana surges before the rift closes and I will place all their collected energy in your orb.",logDesc="Kill 12 Mana Surges in the allowed time limit."} end
if not DB[1958] then DB[1958]={id=1958,zoneId=-161,name="Celestial Power",level=40,minLevel=35,giver="Tabetha",giverType="NPC",giverId=6546,ender="Tabetha",enderType="NPC",enderId=6546,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=1958",image="assets/images/quests/placeholder.png",xpDiff=5,choiceRewards={{id=7515,qty=1},{id=9517,qty=1}}} end
if not DB[1959] then DB[1959]={id=1959,zoneId=-161,name="Report to Anastasia",level=15,minLevel=15,giver="Cain Firesong",giverType="NPC",giverId=2128,ender="Anastasia Hartwell",enderType="NPC",enderId=4568,rewardNextId=1960,poiX=2257,poiY=233,wowhead="https://www.wowhead.com/wotlk/quest=1959",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The mages of the Undercity have noted a magical disturbance within the city, and have sent word for mages of the Horde to investigate.$B$BAnastasia Hartwell can tell you more.  Speak with her in the Magic Quarter in the Undercity.",logDesc="Speak with Anastasia Hartwell."} end
if not DB[1960] then DB[1960]={id=1960,zoneId=-161,name="Investigate the Alchemist Shop",level=16,minLevel=15,giver="Anastasia Hartwell",giverType="NPC",giverId=4568,ender="Anastasia Hartwell",enderType="NPC",enderId=4568,rewardNextId=1961,poiX=1814,poiY=56,wowhead="https://www.wowhead.com/wotlk/quest=1960",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Algernon's alchemist shop in the Apothecarium is the locus of a strange disturbance.  Invisible creatures, made solely of magic, wander the shop--there must be a reason, and we must find it!$B$BInvestigate the disturbance and capture those creatures.  Take a chest of coffers and a scroll from behind me.  Use the scroll at the shop to make the creatures visible, subdue them with your spells, then throw down a coffer to capture them.  Return with the filled coffers, the empty coffers and the cantation.",logDesc="Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell.  Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity."} end
if not DB[1961] then DB[1961]={id=1961,zoneId=-161,name="Gathering Materials",level=15,minLevel=15,giver="Anastasia Hartwell",giverType="NPC",giverId=4568,ender="Josef Gregorian",enderType="NPC",enderId=4576,poiX=1814,poiY=56,wowhead="https://www.wowhead.com/wotlk/quest=1961",image="assets/images/quests/placeholder.png",xpDiff=4,desc="It is time for you to don your first mage's robes, $N.  They are a sign of your station, and a testament to your worth.$B$BTo gain the robes, you must gather the mana gems from the Dalaran mages of Silverpine.  Their beliefs are similar to ours and so killing them is somewhat distasteful, but if they lack the strength to resist us, then they do not deserve their lives.$B$BBring the gems and a supply of linen to Josef Gregorian at the Magic Quarter's tailor shop.",logDesc="Bring 10 Linen Cloth and 6 Dalaran Mana Gems to Josef Gregorian."} end
if not DB[1962] then DB[1962]={id=1962,zoneId=-161,name="Spellfire Robes",level=15,minLevel=15,giver="Josef Gregorian",giverType="NPC",giverId=4576,ender="Josef Gregorian",enderType="NPC",enderId=4576,poiX=1681,poiY=194,wowhead="https://www.wowhead.com/wotlk/quest=1962",image="assets/images/quests/placeholder.png",xpDiff=5,rewards={{id=7510,qty=1}}} end
if not DB[1963] then DB[1963]={id=1963,zoneId=-162,name="The Shattered Hand",level=13,minLevel=10,giver="Therzok",giverType="NPC",giverId=6446,ender="Therzok",enderType="NPC",enderId=6446,rewardNextId=1858,poiX=1773,poiY=-4280,wowhead="https://www.wowhead.com/wotlk/quest=1963",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The Warchief is too subtle in his methods. He is cautious to unleash the might of the Horde. Once we were stronger, mighty conquerors all. That pride we must regain, and the Shattered Hand will do so.$b$bWe build strength from the shadows and strike at the exposed, secretly laying our enemies low. A task you must complete for me, to prove your worth.$b$bThe troll Tazan trades with the pirates near Ratchet. He has information I must have. Kill him and bring me his satchel.",logDesc="Kill Tazan and bring his Satchel to Therzok in the Cleft of Shadow in Orgrimmar."} end
if not DB[1978] then DB[1978]={id=1978,zoneId=-162,name="The Deathstalkers",level=13,minLevel=10,giver="Mennet Carkad",giverType="NPC",giverId=6467,ender="Varimathras",enderType="NPC",enderId=2425,poiX=1436,poiY=72,wowhead="https://www.wowhead.com/wotlk/quest=1978",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.$b$bLord Varimathras will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.$b$bAh, and how could I forget?$b$bWelcome to the Deathstalkers.",logDesc="Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity.",rewards={{id=7298,qty=1}}} end
if not DB[1998] then DB[1998]={id=1998,zoneId=-162,name="Fenwick Thatros",level=16,minLevel=16,giver="Mennet Carkad",giverType="NPC",giverId=6467,ender="Mennet Carkad",enderType="NPC",enderId=6467,rewardNextId=1999,poiX=1436,poiY=72,wowhead="https://www.wowhead.com/wotlk/quest=1998",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Lord Varimathras has just sent me a missive about a threat to the Forsaken that must be immediately removed. His name is Fenwick Thatros, one whom Lord Varimathras believes is a leader of the undead that have taken root in Silverpine Forest.$b$bYour name came to mind immediately, $n. I have faith enough in your abilities that you will carry out this mission flawlessly.$b$bThe latest reports from the Deathstalkers in Silverpine indicate that Thatros can be found near the decrepit dock on Lordamere.",logDesc="Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity."} end
if not DB[1999] then DB[1999]={id=1999,zoneId=-162,name="Tools of the Trade",level=20,minLevel=16,giver="Mennet Carkad",giverType="NPC",giverId=6467,ender="Mennet Carkad",enderType="NPC",enderId=6467,poiX=1436,poiY=72,wowhead="https://www.wowhead.com/wotlk/quest=1999",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The wizards of the Kirin Tor at Ambermill have stored away important documents pertaining to the current state of Dalaran. This we know from the admissions of one of our prisoners. Lord Varimathras has placed the duty of recovering them in the hands of the Deathstalkers.$b$bThis task falls to you, $n. You will need some equipment, however, and the knowledge of lockpicking. Speak with Estelle Gendry, our outfitter, and ask her for a set of tools before you set out.",logDesc="Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity."} end
if not DB[2000] then DB[2000]={id=2000,zoneId=-162,name="Rokar Bladeshadow",level=16,minLevel=16,rewardNextId=2018,wowhead="https://www.wowhead.com/wotlk/quest=2000",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Too much idle time for you, $n. It's time that you learned more of our trade. Just last night, five of our number were found dead in one of the cracks in Orgrimmar, with few leads. There are those that oppose us, using our own methods against us.$b$bSo it is I've decided you should learn the art of lockpicking.$b$bUnfortunately, it is a skill that my hands are not well suited to. You should seek out Rokar, who lives in the hills near Durotar. Even in his old age, I suspect he still has the touch for it.",logDesc="Speak with Rokar Bladeshadow in Durotar."} end
if not DB[2018] then DB[2018]={id=2018,zoneId=-162,name="Rokar's Test",level=16,minLevel=16,rewardNextId=2019,wowhead="https://www.wowhead.com/wotlk/quest=2018",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Ah, so now Therzok sends me his budding students, hm? Well, I suppose I can teach you a thing or two. Not that I care much of your business, but I'd not want it on my conscious that I sent you to your death.$b$bBut you must first prove yourself worthy.$b$bI will tell you, $n. I do not much like this Venture Company. This land reminds me of Draenor, and I do not like the thought of those goblins destroying it. Perhaps if their overseer at the Sludge Fen is killed, their operation will be hamstrung.",logDesc="Kill Overseer Glibby and return his Whistle to Rokar Bladeshadow in Durotar."} end
if not DB[2019] then DB[2019]={id=2019,zoneId=-162,name="Tools of the Trade",level=16,minLevel=16,giver="Mennet Carkad",giverType="NPC",giverId=6467,ender="Therzok",enderType="NPC",enderId=6446,rewardNextId=2020,poiX=1436,poiY=72,wowhead="https://www.wowhead.com/wotlk/quest=2019",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Here you go, $n. These should serve you well. Crafted by my own hand, I swear you'll find none better.$b$bDo not bother to tell me your business, however. I have no interest in Therzok's schemes, I wish only to live out my retirement in peace.$b$bIf you should ever need another set of tools, come back to me, and I will furnish you with a new set. But have a care with them!",logDesc="Return to Therzok in the Cleft of Shadow in Orgrimmar."} end
if not DB[2020] then DB[2020]={id=2020,zoneId=-162,name="<UNUSED>",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=2020",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now here's the locky lock."} end
if not DB[2038] then DB[2038]={id=2038,zoneId=38,name="Bingles' Missing Supplies",level=15,minLevel=12,giver="Bingles Blastenheimer",giverType="NPC",giverId=6577,ender="Bingles Blastenheimer",enderType="NPC",enderId=6577,poiX=-5369,poiY=-3747,wowhead="https://www.wowhead.com/wotlk/quest=2038",image="assets/images/quests/placeholder.png",xpDiff=5,money=700,desc="As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives. With no gyrocopter and no explosives, the movement has no chance!$B$BGet my tools back and find my Blastencapper explosives, $N. For Gnomeregan! ",logDesc="Find and return Bingles' supplies:$B$BBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.",rewards={{id=12522,qty=1}}} end
if not DB[2039] then DB[2039]={id=2039,zoneId=1537,name="Find Bingles",level=15,minLevel=12,giver="Gnoarn",giverType="NPC",giverId=6569,ender="Bingles Blastenheimer",enderType="NPC",enderId=6577,rewardNextId=2038,poiX=-4836,poiY=-1261,wowhead="https://www.wowhead.com/wotlk/quest=2039",image="assets/images/quests/placeholder.png",xpDiff=2,desc="We've lost contact with Bingles! He was sent on a reconnaissance mission over Gnomeregan and hasn't reported back in over a week. I just know he's gone and blown himself up.$B$BHe was last seen flying over the Loch. Perhaps you can investigate, $N.",logDesc="Find Bingles Blastenheimer in Loch Modan."} end
if not DB[2040] then DB[2040]={id=2040,zoneId=1581,name="Underground Assault",level=20,minLevel=15,giver="Shoni the Shilent",giverType="NPC",giverId=6579,ender="Shoni the Shilent",enderType="NPC",enderId=6579,poiX=-8391,poiY=635,wowhead="https://www.wowhead.com/wotlk/quest=2040",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help, $N.$B$BDeep in the Deadmines is a functional goblin shredder. Find that shredder and bring back the intact power supply. With the shredder's power supply, we can give our gyrodrillmatic excavationators the power they need to break through the rocky underground borders of Gnomeregan, opening the way for a gnomish assault!",logDesc="Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.",choiceRewards={{id=7606,qty=1},{id=7607,qty=1}}} end
if not DB[2041] then DB[2041]={id=2041,zoneId=1537,name="Speak with Shoni",level=15,minLevel=15,giver="Gnoarn",giverType="NPC",giverId=6569,ender="Shoni the Shilent",enderType="NPC",enderId=6579,rewardNextId=2040,poiX=-4836,poiY=-1261,wowhead="https://www.wowhead.com/wotlk/quest=2041",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Perhaps... Perhaps you can help us in the battle for Gnomeregan.$B$BIn Stormwind you will find the commander of our underground assault crew, Shoni the Shilent. Shoni needs assistance with her gyrodrillmatic excavationators.$B$BYou will probably find her amongst the dwarves in Stormwind.$B$BGood luck, $N. ",logDesc="Speak with Shoni the Shilent at the Dwarven District in Stormwind.$B"} end
if not DB[2058] then DB[2058]={id=2058,zoneId=-162,name="<UNUSED>",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=2058",image="assets/images/quests/placeholder.png",desc="Kill a guy,member of the Assassins' League. He killed the old leader of the Deathstalkers."} end
if not DB[2059] then DB[2059]={id=2059,zoneId=-162,name="<UNUSED>",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=2059",image="assets/images/quests/placeholder.png",desc="Well guess what,we're interested in you."} end
if not DB[2078] then DB[2078]={id=2078,zoneId=148,name="Gyromast's Revenge",level=20,minLevel=14,giver="Gelkak Gyromast",giverType="NPC",giverId=6667,ender="Gelkak Gyromast",enderType="NPC",enderId=6667,poiX=7745,poiY=-769,wowhead="https://www.wowhead.com/wotlk/quest=2078",image="assets/images/quests/placeholder.png",xpDiff=4,money=900,desc="Landlubber, ye needs to find me first mate.$B$BTake this'n key, puts it in his gulliver an' bring him back here to serve the Cap'n.$B$BThem murlocs an' their chief ain't gonna be too happy once me first mate gets a hold of em!",logDesc="Find Gelkak's First Mate, the Threshwackonator 4100, and lead it back to Gelkak.",rewards={{id=5996,qty=5}}} end
if not DB[2098] then DB[2098]={id=2098,zoneId=148,name="Gyromast's Retrieval",level=20,minLevel=14,giver="Gelkak Gyromast",giverType="NPC",giverId=6667,ender="Gelkak Gyromast",enderType="NPC",enderId=6667,rewardNextId=2078,poiX=7745,poiY=-769,wowhead="https://www.wowhead.com/wotlk/quest=2098",image="assets/images/quests/placeholder.png",xpDiff=5,money=1200,desc="A pirate's life ain't an easy one, landlubber. It ain't all about plunderin' and booze! Alas, me ship be sunk just off shore thanks to them pesky Threshadons.$B$BWhat I be needin' is me first mate back in workin' order!$B$BWhen I washed up'n shore, the key for me first mate broke on the rocks and was pilfered by the beasties of Darkshore. Out of the corner of me eyes I saw some of them Ragin' Crawlers, Ferocious Foreststrider, and murloc rummaging through the wreckage....",logDesc="Find and return the three pieces of Gelkak's Key to Gelkak Gyromast."} end
if not DB[2118] then DB[2118]={id=2118,zoneId=148,name="Plagued Lands",level=14,minLevel=10,giver="Tharnariun Treetender",giverType="NPC",giverId=3701,ender="Tharnariun Treetender",enderType="NPC",enderId=3701,rewardNextId=2138,poiX=6437,poiY=397,wowhead="https://www.wowhead.com/wotlk/quest=2118",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="A sickness spreads across the Darkshore, gripping the minds and bodies of all it touches.$B$BThe Thistle Bears have been hit the hardest by this plague. The once noble beasts are now an instrument of destruction - rabid and frenzied. I may have a cure for this ailment.$B$BTake this trap to the forest and lay it on the ground. Any Rabid Thistle Bear that crosses the light shall become docile for a short time. Once the bear is docile, it shall follow you. Lead it back here, $N.",logDesc="Capture a living Rabid Thistle Bear and bring it back to Tharnariun.$B$BShould you fail to capture a Rabid Thistle Bear and lose your trap, return to Tharnariun Treetender and request another trap."} end
if not DB[2138] then DB[2138]={id=2138,zoneId=148,name="Cleansing of the Infected",level=16,minLevel=10,giver="Tharnariun Treetender",giverType="NPC",giverId=3701,ender="Tharnariun Treetender",enderType="NPC",enderId=3701,poiX=6437,poiY=397,wowhead="https://www.wowhead.com/wotlk/quest=2138",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As I had feared, the cure does not work.$B$BIt saddens me greatly to order the death of any of nature's beasts, but the sick and tainted thistle bears must be put down.$B$BReturn to the forest and destroy 20 rabid thistle bears, $N. It will most certainly not put a stop to the plague but it will slow down the damage the animals are doing to our forest and its inhabitants for a short time.",logDesc="Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore."} end
if not DB[2139] then DB[2139]={id=2139,zoneId=148,name="Tharnariun's Hope",level=18,minLevel=10,giver="Tharnariun Treetender",giverType="NPC",giverId=3701,ender="Tharnariun Treetender",enderType="NPC",enderId=3701,poiX=6437,poiY=397,wowhead="https://www.wowhead.com/wotlk/quest=2139",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The survival of our people and lands comes at unfortunate costs, $N.$B$BYou have spilled the blood of nature's servants; many sick animals you have felled. The people of Auberdine are indebted to you, for the forest's pain is eased - even if only for a moment.$B$BI have one final task for you, but be warned, you will have to kill again. It is my hope that this will be the last time I call upon you, $N.$B$BIn a cave to the northeast, near Bashal'Aran, resides the Den Mother. Slay her.",logDesc="Find and kill the Den Mother.",choiceRewards={{id=7738,qty=1},{id=7739,qty=1}}} end
if not DB[2158] then DB[2158]={id=2158,zoneId=12,name="Rest and Relaxation",level=5,minLevel=1,giver="Falkhaan Isenstrider",giverType="NPC",giverId=6774,ender="Innkeeper Farley",enderType="NPC",enderId=295,poiX=-9045,poiY=-46,wowhead="https://www.wowhead.com/wotlk/quest=2158",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!$B$BMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.$B$BTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!",logDesc="Speak with Innkeeper Farley at the Lion's Pride Inn.",choiceRewards={{id=4656,qty=5},{id=159,qty=5}}} end
if not DB[2159] then DB[2159]={id=2159,zoneId=141,name="Dolanaar Delivery",level=5,minLevel=1,giver="Porthannius",giverType="NPC",giverId=6780,ender="Innkeeper Keldamyr",enderType="NPC",enderId=6736,poiX=10214,poiY=701,wowhead="https://www.wowhead.com/wotlk/quest=2159",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Greetings, young $c.  Can you offer me aid?  I have a package of herbs that I must deliver to the town of Dolanaar.  But I still have business with the druids of Shadowglen and cannot yet leave.$B$BCan you deliver this package for me?  It must be sent to Innkeeper Keldamyr, at the Dolanaar inn.  It lies along the road, to the south.",logDesc="Bring the Dolanaar Delivery to Innkeeper Keldamyr.",choiceRewards={{id=2070,qty=5},{id=159,qty=5}}} end
if not DB[2160] then DB[2160]={id=2160,zoneId=1,name="Supplies to Tannok",level=5,minLevel=1,giver="Hands Springsprocket",giverType="NPC",giverId=6782,ender="Tannok Frosthammer",enderType="NPC",enderId=6806,poiX=-6249,poiY=135,wowhead="https://www.wowhead.com/wotlk/quest=2160",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hey! You look like a hearty adventurer. If you're planning on braving the pass, do you suppose you could bring a package to the inn in Kharanos?$b$bYou were planning on stopping at the inn, right? If you make it through the pass, you'll definitely want to take a breather there.$b$bAnyways, bring this to Tannok Frosthammer, the innkeeper's assistant. I can't get through the pass myself, and it'll be days until a Mountaineer escort comes through!",logDesc="Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos.",choiceRewards={{id=117,qty=5},{id=159,qty=5}}} end
if not DB[2161] then DB[2161]={id=2161,zoneId=14,name="A Peon's Burden",level=5,minLevel=1,giver="Ukor",giverType="NPC",giverId=6786,ender="Innkeeper Grosk",enderType="NPC",enderId=6928,poiX=-599,poiY=-4715,wowhead="https://www.wowhead.com/wotlk/quest=2161",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Excuse me?  Can you help me?$B$BI have a load of food here.  I walked along the road and braved scorpids and spiders and worse!  I brought the food to the Valley of Trials because I thought they needed it and I like to help out.  But they don't need any food!  Now I have to take it back to Razor Hill and I'm afraid of all the beasts along the way...$B$BCan you take it for me?  I'm just a peon, but you're a hero.  You fear nothing!$B$BTake it to Innkeeper Grosk at the Razor Hill inn.  Thank you!",logDesc="Bring Ukor's Burden to Innkeeper Grosk in Razor Hill.",choiceRewards={{id=4540,qty=5},{id=159,qty=5}}} end
if not DB[2178] then DB[2178]={id=2178,zoneId=-304,name="Easy Strider Living",level=12,minLevel=9,giver="Alanndarian Nightsong",giverType="NPC",giverId=3702,ender="Alanndarian Nightsong",enderType="NPC",enderId=3702,poiX=6558,poiY=473,wowhead="https://www.wowhead.com/wotlk/quest=2178",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Do you smell that delicious aroma? It's my secret recipe, $N--fresh strider stew. Delicious!$B$BPerhaps you would be interested in learning the recipe?$B$BBefore I teach you the recipe, you will need to prove that you can handle the beasts.$B$BNow, I don't expect you to go out and tame one and ride it back to me, but if you can kill a few and bring back some of their succulent meat, I may be persuaded to show you the ways of strider stew.",logDesc="Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine.",rewards={{id=5486,qty=1},{id=5477,qty=5}}} end
if not DB[2198] then DB[2198]={id=2198,zoneId=1517,name="The Shattered Necklace",level=41,minLevel=37,ender="Talvash del Kissel",enderType="NPC",enderId=6826,rewardNextId=2199,wowhead="https://www.wowhead.com/wotlk/quest=2198",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have found a tarnished necklace, though the tarnish belies intricate and magical craftsmanship.  The necklace has been shattered, as its setting appears to be missing three gems.  On the underside of the necklace is the faint imprint of the city seal for Ironforge.  Below the seal are three tiny, engraved letters: \"TdK\".$B$BIf there is anything to be gleaned from the necklace, you will need to learn about its origins.  Perhaps the seal and the initials are a start...",logDesc="Search for the original creator of the shattered necklace to learn of its potential value."} end
if not DB[2199] then DB[2199]={id=2199,zoneId=1517,name="Lore for a Price",level=41,minLevel=37,giver="Talvash del Kissel",giverType="NPC",giverId=6826,ender="Talvash del Kissel",enderType="NPC",enderId=6826,rewardNextId=2200,poiX=-4588,poiY=-1001,wowhead="https://www.wowhead.com/wotlk/quest=2199",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I am a jeweler of great renown here in Ironforge!  Well, former renown anyway... I have fallen onto hard times due to the chicanery of a competitor!  A bad reputation in this business spells financial disaster.  As a result, I find myself without a copper to my good-though-currently-sullied name.$B$BI want you to get me five silver bars to finish an order I received - the first in what seems like an eternity.$B$BYou get me those five silver bars, and I'll answer your questions on the necklace.",logDesc="Bring five silver bars to Talvash del Kissel in Ironforge."} end
if not DB[2200] then DB[2200]={id=2200,zoneId=1517,name="Back to Uldaman",level=42,minLevel=37,giver="Talvash del Kissel",giverType="NPC",giverId=6826,ender="Remains of a Paladin",enderType="NPC",enderId=6912,rewardNextId=2201,poiX=-4588,poiY=-1001,wowhead="https://www.wowhead.com/wotlk/quest=2200",image="assets/images/quests/placeholder.png",xpDiff=7,desc="A competitor of mine started a rumor that my necklace cursed the paladin.  Needless to say, no one wants to buy cursed items from a jeweler.$B$B$N, I'll make you a deal - find the gems and I'll reassemble the necklace, so long as you'll advertise that I do NOT make cursed items!$B$BTry looking for clues in Uldaman; maybe see if the paladin's body is down there, since he's the one who we know had it last!  When you find the gems you should use this; it'll allow you to contact me here in Ironforge.",logDesc="Search for clues as to the current disposition of Talvash's necklace within Uldaman.  The slain paladin he mentioned was the person who had it last."} end
if not DB[2201] then DB[2201]={id=2201,zoneId=1517,name="Find the Gems",level=43,minLevel=37,giver="Remains of a Paladin",giverType="NPC",giverId=6912,ender="Talvash del Kissel",enderType="NPC",enderId=6826,rewardNextId=2204,poiX=-176,poiY=169,wowhead="https://www.wowhead.com/wotlk/quest=2201",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The paladin's journal has provided perhaps the only clues that Uldaman will yield as to the location of the necklace's gems.  If the paladin's scribing remains accurate, then the Shadowforge dwarves and the troggs that vie for control of the dig site will need to be dealt with.$B$BArmed with this knowledge, the search for the gems begins in earnest.  When all the gems have been acquired, Talvash in Ironforge should be notified via the Phial of Scrying as per his instructions.",logDesc="Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B$B* The sapphire has been claimed by Grimlok, the trogg leader."} end
if not DB[2202] then DB[2202]={id=2202,zoneId=1517,name="Uldaman Reagent Run",level=42,minLevel=36,giver="Jarkal Mossmeld",giverType="NPC",giverId=6868,ender="Jarkal Mossmeld",enderType="NPC",enderId=6868,poiX=-6653,poiY=-2139,wowhead="https://www.wowhead.com/wotlk/quest=2202",image="assets/images/quests/placeholder.png",xpDiff=5,money=5500,desc="I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters at the Uldaman dig site and can be found in the early tunnels and deep within the less-explored areas.  I want to study their potential use in alchemy, and that's where you come in.$B$BFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.$B$BDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!",logDesc="Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.",rewards={{id=9030,qty=5}}} end
if not DB[2203] then DB[2203]={id=2203,zoneId=3,name="Badlands Reagent Run II",level=44,minLevel=40,giver="Jarkal Mossmeld",giverType="NPC",giverId=6868,ender="Jarkal Mossmeld",enderType="NPC",enderId=6868,poiX=-6653,poiY=-2139,wowhead="https://www.wowhead.com/wotlk/quest=2203",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have been most helpful to me, $c.  I would reward you with the very recipe for the brew I gave you earlier... but I would ask of you a task that is quite dangerous.  Hear my request.$B$BThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be warned.  Once you have all three filled, bring them to me.$B$BDo this, and the recipe will be yours.",logDesc="Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Jarkal Mossmeld in Kargath."} end
if not DB[2204] then DB[2204]={id=2204,zoneId=1517,name="Restoring the Necklace",level=44,minLevel=37,giver="Talvash del Kissel",giverType="NPC",giverId=6826,ender="Talvash del Kissel",enderType="NPC",enderId=6826,poiX=-4588,poiY=-1001,wowhead="https://www.wowhead.com/wotlk/quest=2204",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You are going to need to find some \"oomph\" for the necklace, and Uldaman is probably the best place for it, actually.  I guess there are a lot of constructs running around in there, yeah?  Well, take out the biggest, baddest construct in that place and grab its power source!  I am pretty sure I can fuse that source into the necklace.$B$BWithout that power source, fixing the necklace will be impossible.  Come back to me here to Ironforge when you have it, and we'll get it all fixed up for you!",logDesc="Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge."} end
if not DB[2205] then DB[2205]={id=2205,zoneId=-162,name="Seek out SI: 7",level=10,minLevel=10,giver="Keryn Sylvius",giverType="NPC",giverId=917,ender="Master Mathias Shaw",enderType="NPC",enderId=332,poiX=-9466,poiY=13,wowhead="https://www.wowhead.com/wotlk/quest=2205",image="assets/images/quests/placeholder.png",xpDiff=2,money=85,desc="The badge? Oh, it's nothing, fish - nothing you could handle anyhow. By the looks of you, I'd say Mathias is likely to mistake you for the cheese delivery $g boy:girl; instead of a proper rogue. Regardless, I've been assigned a job and I've made a promise to deliver on that job.$B$BSpeaking of which, deliver this package to Mathias and he may give you a small task or two.$B$BGet cracking. $B",logDesc="Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks."} end
if not DB[2206] then DB[2206]={id=2206,zoneId=-162,name="Snatch and Grab",level=10,minLevel=10,giver="Master Mathias Shaw",giverType="NPC",giverId=332,ender="Master Mathias Shaw",enderType="NPC",enderId=332,poiX=-8815,poiY=362,wowhead="https://www.wowhead.com/wotlk/quest=2206",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Our operatives in the field are reporting heavy Defias activity south of Goldshire. The reports indicate that the Defias have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall.$B$BI need you to infiltrate the dock house and get me that shipping schedule, $N. You will probably find it buried deep in the pockets of the Dockmaster.$B$B...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence.",logDesc="Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw.$B",rewards={{id=7298,qty=1}}} end
if not DB[2218] then DB[2218]={id=2218,zoneId=-162,name="Road to Salvation",level=10,minLevel=10,giver="Hogral Bakkan",giverType="NPC",giverId=1234,ender="Hulfdan Blackbeard",enderType="NPC",enderId=5165,rewardNextId=2238,poiX=-5604,poiY=-540,wowhead="https://www.wowhead.com/wotlk/quest=2218",image="assets/images/quests/placeholder.png",xpDiff=3,money=175,desc="Another lost soul looking for guidance, eh? I suppose you want to find a purpose - your purpose. I've seen it a thousand times, another hero looking for work.$B$BWell, today's your lucky day, friend. Hogral's got the cure for your ailment.$B$BHere's what you do: Take this road here up to Ironforge and make your way to the Forlorn Cavern. Once there, locate the thieves' guild and speak with Hulfdan Blackbeard. He'll put you on the road to salvation.$B",logDesc="Speak with Hulfdan Blackbeard in Ironforge."} end
if not DB[2238] then DB[2238]={id=2238,zoneId=-162,name="Simple Subterfugin'",level=10,minLevel=10,giver="Hulfdan Blackbeard",giverType="NPC",giverId=5165,ender="Onin MacHammar",enderType="NPC",enderId=6886,rewardNextId=2239,poiX=-4648,poiY=-1124,wowhead="https://www.wowhead.com/wotlk/quest=2238",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Ye see, the King be strip mining the quarry fer ore and gems. More riches than any one dwarf should see in ten lifetimes.$B$BThe Hidden Circle has values, $N. We value valuables. Can ye understand?$B$BNow we feels the King should be sharing some of that booty, but we don't want ol' 'Stinkbeard' to know he's sharin' - if ye catch me drift.$B$BWe needs ye to speak with Onin MacHammar over by Gnomeregan and bring back a report. The crafty dwarf has hidden hisself amongst the lepers. Be careful.",logDesc="Find Onin MacHammar by Gnomeregan."} end
if not DB[2239] then DB[2239]={id=2239,zoneId=-162,name="Onin's Report",level=10,minLevel=10,giver="Onin MacHammar",giverType="NPC",giverId=6886,ender="Hulfdan Blackbeard",enderType="NPC",enderId=5165,poiX=-5337,poiY=563,wowhead="https://www.wowhead.com/wotlk/quest=2239",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Quarry? Yap, I see those monstrous armored steam tanks come by this post near every day.$B$BMy contacts to the east tell me that the tank starts off at Ironforge, makes a pickup at the Gol'Bolar Quarry, stops over at Kharanos to refuel and then for some blasted reason, it takes the long way around past Gnomeregan, before reaching Ironforge to drop off the shipment.$B$BIt's all in the report, $r. Take it back to Hulfdan so he can plan the next step.$B",logDesc="Take Onin's Report back to Hulfdan in Ironforge.",rewards={{id=7298,qty=1}}} end
if not DB[2240] then DB[2240]={id=2240,zoneId=1517,name="The Hidden Chamber",level=40,minLevel=35,giver="3",giverType="NPC",giverId=6906,ender="Prospector Stormpike",enderType="NPC",enderId=1356,poiX=-353,poiY=117,wowhead="https://www.wowhead.com/wotlk/quest=2240",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Now for the task at hand.$B$BThere is a secret chamber, the Chamber of Khaz'mul, that must be explored.  The problem is that the chamber's behind a huge, locked door!  It's a lucky thing I know how to open it.$B$BI've described everything in my journal, here on the table.  My band and I are stuck here for now... so you, $N, must find the chamber of Khaz'mul for us!$B$BRead my journal, explore the chamber, then report to Prospector Stormpike at the Explorers' League in Ironforge.",logDesc="Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.",choiceRewards={{id=9626,qty=1},{id=9627,qty=1}}} end
if not DB[2241] then DB[2241]={id=2241,zoneId=-162,name="The Apple Falls",level=10,minLevel=10,giver="Jannok Breezesong",giverType="NPC",giverId=3599,ender="Syurna",enderType="NPC",enderId=4163,poiX=9790,poiY=944,wowhead="https://www.wowhead.com/wotlk/quest=2241",image="assets/images/quests/placeholder.png",xpDiff=3,desc="They say I'm 'lovestruck,' whatever that means.$B$BSure, I spend my every waking moment thinking about Syurna. Sure, my home is full of paintings and drawings of Syurna. Sure, I often go days without eating, sleeping, or drinking, while I lament about the love we could have had. Is that so wrong?$B$BNow she won't see me! ME! I've tried sending her messages but she won't even talk to another person unless they are a rogue.$B$BCould you deliver this flower to her? Don't forget to tell her it's from Jannok.",logDesc="Take Jannok's Rose to Syurna in Darnassus."} end
if not DB[2242] then DB[2242]={id=2242,zoneId=-162,name="Destiny Calls",level=10,minLevel=10,giver="Syurna",giverType="NPC",giverId=4163,ender="Syurna",enderType="NPC",enderId=4163,poiX=10084,poiY=2547,wowhead="https://www.wowhead.com/wotlk/quest=2242",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We believe there is one being that may be able to help us understand what is happening to the forests of Teldrassil. Unfortunately, getting the creature to cooperate has proven disastrous.$B$BHe hides on a branch at the outskirts of the Oracle Glade. All who have so far approached the satyr, whether through force or diplomacy, have met with doom. Perhaps stealth is the answer, $N.$B$BFind what Sethir the Ancient carries in his packs and report back to me.$B",logDesc="Find Sethir the Ancient and bring back any clues that you may discover to Syurna.$B",rewards={{id=7298,qty=1}}} end
if not DB[2258] then DB[2258]={id=2258,zoneId=3,name="Badlands Reagent Run",level=39,minLevel=36,giver="Jarkal Mossmeld",giverType="NPC",giverId=6868,ender="Jarkal Mossmeld",enderType="NPC",enderId=6868,rewardNextId=2202,poiX=-6653,poiY=-2139,wowhead="https://www.wowhead.com/wotlk/quest=2258",image="assets/images/quests/placeholder.png",xpDiff=5,money=4500,desc="$N, I could use your aid if you're up for it.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.$B$BI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.$B$BAcquire these items for me, you'll get some coin out of the deal.  Watcha wanna do?",logDesc="Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands."} end
if not DB[2259] then DB[2259]={id=2259,zoneId=-162,name="Erion Shadewhisper",level=16,minLevel=16,giver="Jannok Breezesong",giverType="NPC",giverId=3599,ender="Erion Shadewhisper",enderType="NPC",enderId=4214,rewardNextId=2260,poiX=9790,poiY=944,wowhead="https://www.wowhead.com/wotlk/quest=2259",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Do not worry, $N, I am not sending you to see Syurna. Erion requires your presence at the Cenarion Enclave. Make haste!",logDesc="Contact Erion Shadewhisper in Darnassus.$B"} end
if not DB[2260] then DB[2260]={id=2260,zoneId=-162,name="Erion's Behest",level=16,minLevel=16,giver="Erion Shadewhisper",giverType="NPC",giverId=4214,ender="Renzik \"The Shiv\"",enderType="NPC",enderId=6946,poiX=10055,poiY=2573,wowhead="https://www.wowhead.com/wotlk/quest=2260",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Word of your deeds has spread far and wide, $N. So far, in fact, that Stormwind Intelligence has asked for you by name.$B$BThe journey is taxing and not without peril, but an opportunity to train under SI:7 should not be taken lightly.$B$BA new world awaits you, $N. Make your way to Old Town in Stormwind and speak with Renzik \"The Shiv\" at SI:7 headquarters.$B",logDesc="Travel to Stormwind City and seek council with Renzik \"The Shiv.\""} end
if not DB[2278] then DB[2278]={id=2278,zoneId=1517,name="The Platinum Discs",level=47,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=2278",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.$B$B\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"$B$BYou have uncovered a wealth of previously undiscovered worldly lore!",logDesc="Speak with stone watcher and learn what ancient lore it keeps.  Once you have learned what lore it has to offer, activate the Discs of Norgannon."} end
if not DB[2279] then DB[2279]={id=2279,zoneId=1517,name="The Platinum Discs",level=47,minLevel=40,ender="High Explorer Magellas",enderType="NPC",enderId=5387,rewardNextId=2439,wowhead="https://www.wowhead.com/wotlk/quest=2279",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.$B$BYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!$B$BNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The Explorers' League in Ironforge is such a group, known throughout the Alliance; perhaps they can make good use of it.",logDesc="Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge."} end
if not DB[2280] then DB[2280]={id=2280,zoneId=1517,name="The Platinum Discs",level=47,minLevel=40,ender="Sage Truthseeker",enderType="NPC",enderId=3978,wowhead="https://www.wowhead.com/wotlk/quest=2280",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.$B$BYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!$B$BNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The sages of Thunder Bluff are such historians, known throughout the Horde; perhaps they can make good use of it.",logDesc="Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff."} end
if not DB[2281] then DB[2281]={id=2281,zoneId=-162,name="Redridge Rendezvous",level=16,minLevel=16,giver="Renzik \"The Shiv\"",giverType="NPC",giverId=6946,ender="Lucius",enderType="NPC",enderId=6966,rewardNextId=2282,poiX=-8820,poiY=363,wowhead="https://www.wowhead.com/wotlk/quest=2281",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Sending you out in the field now would be suicide. Renzik doesn't need another dead rogue on his hands. Don't fret, though, $N - Renzik is going to get you up to speed.$B$BMake your way to the Redridge Mountains and speak with an associate of SI:7 named Lucius. You will find him hanging around the docks of Lakeshire with the other shady good-for-nothings.",logDesc="Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius."} end
if not DB[2282] then DB[2282]={id=2282,zoneId=-162,name="Alther's Mill",level=20,minLevel=16,giver="Lucius",giverType="NPC",giverId=6966,ender="Lucius",enderType="NPC",enderId=6966,poiX=-9328,poiY=-2180,wowhead="https://www.wowhead.com/wotlk/quest=2282",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We've been training thieves here for years! After all, not every rapscallion is born with the grace and finesse of old Lucius.$B$BUp off the road here you'll find Alther's Mill. I got a chest up there with something important inside. Go get it for me! Bring back that token and you'll receive your Certificate of Thievery!",logDesc="Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire.",rewards={{id=7907,qty=1}}} end
if not DB[2283] then DB[2283]={id=2283,zoneId=1517,name="Necklace Recovery",level=41,minLevel=37,giver="Dran Droffers",giverType="NPC",giverId=6986,ender="Dran Droffers",enderType="NPC",enderId=6986,rewardNextId=2284,poiX=1932,poiY=-4515,wowhead="https://www.wowhead.com/wotlk/quest=2283",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We've got work for you, that is if you've got the guts to do it!$B$BDeep in the Badlands is the Uldaman dig site.  We've heard a tale about some idiot paladin who died there recently.  Why we even care is that he had a very valuable necklace on him.  It's supposedly got three large gems: a ruby, a sapphire, and a topaz.$B$BThe shot: we want it, and we're payin' TOP SILVER to get it.  It may be damaged, but that's neither here nor there; we'll fix whatever scratches are on it.",logDesc="Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar.  The necklace may be damaged."} end
if not DB[2284] then DB[2284]={id=2284,zoneId=1517,name="Necklace Recovery, Take 2",level=41,minLevel=37,giver="Dran Droffers",giverType="NPC",giverId=6986,ender="Remains of a Paladin",enderType="NPC",enderId=6912,rewardNextId=2318,poiX=1932,poiY=-4515,wowhead="https://www.wowhead.com/wotlk/quest=2284",image="assets/images/quests/placeholder.png",xpDiff=7,desc="As sure as Malton is a dummy, those gems are still in Uldaman somewhere.  You're going to have to go back there and look for them.$B$BLike I said before, if the information we have is correct then there's a ruby, a sapphire, and a topaz that go with the necklace.  Find them and put them in the necklace.$B$BAs to where the gems are, who knows?  Maybe you'll get lucky and find the corpse of the Paladin.  If he's not been stripped clean already, then maybe he's got them on him still.",logDesc="Find a clue as to the gems' whereabouts in the depths of Uldaman."} end
if not DB[2298] then DB[2298]={id=2298,zoneId=-162,name="Kingly Shakedown",level=16,minLevel=16,giver="Hulfdan Blackbeard",giverType="NPC",giverId=5165,ender="Renzik \"The Shiv\"",enderType="NPC",enderId=6946,poiX=-4648,poiY=-1124,wowhead="https://www.wowhead.com/wotlk/quest=2298",image="assets/images/quests/placeholder.png",xpDiff=1,desc="So there we were, about to start plottin' out phase III when a couple o' Magni's blockheads come bargin' in here talkin' bout some kind o' heist and arresting some o' the Hidden Circle.$B$BWell nobody puts the iron on old Blackbeard! The argumentations got heavy and thick and somehow yer name weres blurted out!$B$BMe advice? Take the first Gryphon out o' Ironforge and get to Stormwind. Get yerself to Old Town and once there, talk to an old friend o' mine named Renzik \"The Shiv.\"",logDesc="Travel to Stormwind and seek out Renzik \"The Shiv.\""} end
if not DB[2299] then DB[2299]={id=2299,zoneId=-162,name="To Hulfdan!",level=16,minLevel=16,giver="Hogral Bakkan",giverType="NPC",giverId=1234,ender="Hulfdan Blackbeard",enderType="NPC",enderId=5165,rewardNextId=2298,poiX=-5604,poiY=-540,wowhead="https://www.wowhead.com/wotlk/quest=2299",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Where have you been, $N? Hulfdan's been looking all over the place for you. We thought the king may have put you in irons.$B$BGet to Ironforge as soon as possible and speak with Hulfdan!",logDesc="Travel to Ironforge and speak with Hulfdan Blackbeard."} end
if not DB[2300] then DB[2300]={id=2300,zoneId=-162,name="SI:7",level=16,minLevel=16,giver="Keryn Sylvius",giverType="NPC",giverId=917,ender="Renzik \"The Shiv\"",enderType="NPC",enderId=6946,rewardNextId=2281,poiX=-9466,poiY=13,wowhead="https://www.wowhead.com/wotlk/quest=2300",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Renzik was looking for you, fish.$B$BI wouldn't keep Mathias's second in command waiting if I were you.$B",logDesc="Travel to Stormwind and seek out Renzik \"The Shiv.\""} end
if not DB[2318] then DB[2318]={id=2318,zoneId=1517,name="Translating the Journal",level=42,minLevel=37,giver="Remains of a Paladin",giverType="NPC",giverId=6912,ender="Jarkal Mossmeld",enderType="NPC",enderId=6868,rewardNextId=2338,poiX=-176,poiY=169,wowhead="https://www.wowhead.com/wotlk/quest=2318",image="assets/images/quests/placeholder.png",xpDiff=5,desc="At an impasse of sorts, you know that you will need the book translated into a language you can understand.  There certainly are a number of people in the world who could do it; the closest location that might have someone who could, however, is the Kargath outpost in the Badlands.  Perhaps that is a good place to start.$B",logDesc="Find someone who can translate the paladin's journal.  The closest location that might have someone is Kargath, in the Badlands."} end
if not DB[2338] then DB[2338]={id=2338,zoneId=1517,name="Translating the Journal",level=42,minLevel=37,giver="Jarkal Mossmeld",giverType="NPC",giverId=6868,ender="Jarkal Mossmeld",enderType="NPC",enderId=6868,poiX=-6653,poiY=-2139,wowhead="https://www.wowhead.com/wotlk/quest=2338",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Droffers and Son Salvage aren't smart enough to restore the magic in the necklace, but I am.  All I want to do is study the necklace so I can learn to make them myself.  To do that, I will need your necklace.  Let me borrow it, and in exchange for the time I get to study it I will translate the journal for you.  While you are searching for the gems, I should have enough time to learn what I need to.$B$BIt's a simple deal, and no one else will be the wiser.  Whatcha wanna do?",logDesc="Let Jarkal borrow the necklace.  In exchange, he will translate the journal for you."} end
if not DB[2339] then DB[2339]={id=2339,zoneId=1517,name="Find the Gems and Power Source",level=44,minLevel=37,giver="Jarkal Mossmeld",giverType="NPC",giverId=6868,ender="Jarkal Mossmeld",enderType="NPC",enderId=6868,poiX=-6653,poiY=-2139,wowhead="https://www.wowhead.com/wotlk/quest=2339",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Here is the journal, translated for you to read on your own.  The crux of it says dwarves hid the ruby, the troggs hid the topaz, and a trogg named Grimlok has the sapphire.$B$BLook - you're going to need a power source to make the necklace work again.  Dran Droffers doesn't know this.  To find one, here's what I'd do: go as deep as you can in Uldaman and kill whatever construct there is the strongest.  No doubt whatever that is would have it.$B$BWhen you have everything collected, come back here!",logDesc="Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath.  Jarkal believes a power source might be found on the strongest construct present in Uldaman.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B* The sapphire has been claimed by Grimlok, the trogg leader."} end
if not DB[2340] then DB[2340]={id=2340,zoneId=1517,name="Deliver the Gems",level=44,minLevel=37,giver="Jarkal Mossmeld",giverType="NPC",giverId=6868,ender="Dran Droffers",enderType="NPC",enderId=6986,rewardNextId=2341,poiX=-6653,poiY=-2139,wowhead="https://www.wowhead.com/wotlk/quest=2340",image="assets/images/quests/placeholder.png",xpDiff=3,money=12500,desc="Any necklace setting and gem will work, so long as they are the same material.  This power source, however, is what will bring the magic back to the necklace... I hope.$B$BI'll gladly supply the gems needed for your version of the necklace, so long as the power source actually works.$B$BHead to Orgrimmar and keep your end of the bargain with Droffers and Son Salvage.  Just keep your mouth shut about our deal, and when you get back I might have a wonderful surprise for you.",logDesc="Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar."} end
if not DB[2341] then DB[2341]={id=2341,zoneId=1517,name="Necklace Recovery, Take 3",level=44,minLevel=37,giver="Dran Droffers",giverType="NPC",giverId=6986,ender="Jarkal Mossmeld",enderType="NPC",enderId=6868,poiX=1932,poiY=-4515,wowhead="https://www.wowhead.com/wotlk/quest=2341",image="assets/images/quests/placeholder.png",xpDiff=7,desc="As Dran and Malton Droffers begin to squabble over their new salvage, half of the deal is now complete.  A trip to the Badlands is now in order to finish things up, as Jarkal Mossmeld in Kargath might have a special reward waiting for you there.",logDesc="Visit Jarkal Mossmeld in Kargath to see if he was successful.",rewards={{id=7888,qty=1}}} end
if not DB[2342] then DB[2342]={id=2342,zoneId=1517,name="Reclaimed Treasures",level=43,minLevel=33,giver="Patrick Garrett",giverType="NPC",giverId=5651,ender="Patrick Garrett",enderType="NPC",enderId=5651,poiX=1567,poiY=275,wowhead="https://www.wowhead.com/wotlk/quest=2342",image="assets/images/quests/placeholder.png",xpDiff=5,money=6000,desc="Sweeping the bat pens with this broom is not befitting a Garrett!  I've earned a little coin from this accursed job, and I'm willing to spend it on you to better my station.$B$BThe Garrett family weapon of choice is locked away in our chest in the South Common Hall of Uldaman from when we Garretts toiled there as diggers.  Without it, I will be stuck here forever - literally - sweeping up after these infernal bats.$B$BReclaim my family's treasure and bring it to me!  Help me restore my birthright!",logDesc="Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity."} end
if not DB[2358] then DB[2358]={id=2358,zoneId=-162,name="Horns of Nez'ra",level=22,minLevel=16,giver="Arantir",giverType="NPC",giverId=7009,ender="Arantir",enderType="NPC",enderId=7009,poiX=-9333,poiY=-2180,wowhead="https://www.wowhead.com/wotlk/quest=2358",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Many years ago, the Horns of Nez'ra were stolen from Ravenholdt manor. Across continents and oceans I have searched, only to discover that these insignificant beasts have had it in their possession all along.$B$BSlay every Blackrock orc you cross until the Horns of Nez'ra are recovered. Should you recover the horns, find me in Lakeshire.$B$BDo this for me and your name shall be known to Ravenholdt, $N.",logDesc="Return the Horns of Nez'ra to Arantir in Lakeshire.",rewards={{id=7676,qty=10}}} end
if not DB[2359] then DB[2359]={id=2359,zoneId=-162,name="Klaven's Tower",level=-1,minLevel=20,giver="4",giverType="NPC",giverId=7024,ender="Master Mathias Shaw",enderType="NPC",enderId=332,rewardNextId=2607,poiX=-11035,poiY=619,wowhead="https://www.wowhead.com/wotlk/quest=2359",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've been staking out this tower for weeks, $N. Recently a major shipment came through from Duskwood, and along with it came those guards.$B$BWhat are they? Your guess is as good as mine. I can tell you one thing - they aren't human.$B$BAnyhow, the shipment had a chest - which is what I assume those abominations are guarding. The zombie with the spikes holds a key we'll need.$B$BGet that key, get in the tower, and uncover whatever is in that chest. Take your findings back to Mathias.",logDesc="Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower.$B",rewards={{id=18160,qty=1}}} end
if not DB[2360] then DB[2360]={id=2360,zoneId=-162,name="Mathias and the Defias",level=-1,minLevel=20,giver="Master Mathias Shaw",giverType="NPC",giverId=332,ender="4",enderType="NPC",enderId=7024,rewardNextId=2359,poiX=-8815,poiY=362,wowhead="https://www.wowhead.com/wotlk/quest=2360",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Not a moment too soon, $N. SI:7 reconnaissance is reporting unusually heavy Defias activity in Westfall.$B$BIt would seem that the Defias have taken over an abandoned Alliance watch tower southeast of Sentinel Hill and are using it as a base of operations to smuggle in goods from the Redridge supply route.$B$BGet to Westfall and contact Agent Kearnen for your debriefing. You will find her hidden near the tower.$B$B...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence. ",logDesc="Travel to Westfall and find Agent Kearnen for your debriefing."} end
if not DB[2361] then DB[2361]={id=2361,zoneId=1517,name="Restoring the Necklace",level=44,minLevel=37,giver="Talvash del Kissel",giverType="NPC",giverId=6826,ender="Talvash del Kissel",enderType="NPC",enderId=6826,poiX=-4588,poiY=-1001,wowhead="https://www.wowhead.com/wotlk/quest=2361",image="assets/images/quests/placeholder.png",xpDiff=7,rewards={{id=7673,qty=1}}} end
if not DB[2378] then DB[2378]={id=2378,zoneId=-162,name="Find the Shattered Hand",level=16,minLevel=16,giver="Mennet Carkad",giverType="NPC",giverId=6467,ender="Shenthul",enderType="NPC",enderId=3401,rewardNextId=2379,poiX=1436,poiY=72,wowhead="https://www.wowhead.com/wotlk/quest=2378",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You have served the Deathstalkers well, $N, but perhaps it is time for you to venture outward. While you have shown aptitude in the ways of stealth and deception, you still require much training.$B$BThe Deathstalkers have allies within the Shattered Hand. Seek out those that would assist us - find Shenthul in Orgrimmar.$B",logDesc="Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.$B"} end
if not DB[2379] then DB[2379]={id=2379,zoneId=-162,name="Zando'zan",level=16,minLevel=16,giver="Shenthul",giverType="NPC",giverId=3401,ender="Zando'zan",enderType="NPC",enderId=3402,rewardNextId=2382,poiX=1771,poiY=-4284,wowhead="https://www.wowhead.com/wotlk/quest=2379",image="assets/images/quests/placeholder.png",desc="Your determination alone is not enough to overcome the obstacles that lay ahead of us.$B$BSpeak with Zando'zan to begin your training as an operative of the Shattered Hand.$B$BIt is only when you have mastered the practices of stealth and thievery that you may take the next step towards your destiny.$B",logDesc="Speak with Zando'zan at the Cleft of Shadow."} end
if not DB[2380] then DB[2380]={id=2380,zoneId=-162,name="To Orgrimmar!",level=16,minLevel=16,giver="Kaplak",giverType="NPC",giverId=3170,ender="Shenthul",enderType="NPC",enderId=3401,rewardNextId=2379,poiX=268,poiY=-4711,wowhead="https://www.wowhead.com/wotlk/quest=2380",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A master of stealth and deception you are not, however, all of that can and will change. You've obviously impressed those in charge with your meager skills, as the great Shenthul has asked for you by name.$B$BTake the road north of here to Orgrimmar and speak with Shenthul in the Cleft of Shadow.$B",logDesc="Speak with Shenthul at the Cleft of Shadow in Orgrimmar."} end
if not DB[2381] then DB[2381]={id=2381,zoneId=-162,name="Plundering the Plunderers",level=18,minLevel=16,giver="Wrenix the Wretched",giverType="NPC",giverId=7161,ender="Wrenix the Wretched",enderType="NPC",enderId=7161,poiX=-841,poiY=-3768,wowhead="https://www.wowhead.com/wotlk/quest=2381",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I don't mean to scare you, $N, but the last five thieves I sent to steal the southsea treasure came back to me in pieces.$B$BSouth along the coast you'll find Tide Razor, the southsea freebooter's ship. Nestled in the hold is the payoff - the southsea treasure. On the second level of that ship is the pirate's den, a place where they train all of their thieves.$B$BBoard that ship, steal the treasure, and bring it back to me. Use the pirate's den if you need to practice your thievery, but be careful!$B",logDesc="Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.$B$BShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!$B$B",rewards={{id=7676,qty=10}}} end
if not DB[2382] then DB[2382]={id=2382,zoneId=-162,name="Wrenix of Ratchet",level=16,minLevel=16,giver="Zando'zan",giverType="NPC",giverId=3402,ender="Wrenix the Wretched",enderType="NPC",enderId=7161,rewardNextId=2381,poiX=1779,poiY=-4280,wowhead="https://www.wowhead.com/wotlk/quest=2382",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Zando'zan has seen it! Yes, the day comes! Thrall's death... the dagger in his back, poison seeping through to his every vein... Zando'zan has said too much.$B$B$N! Zando'zan has a task for $N! $N must travel to Ratchet, east of the Crossroads, and speak with Wrenix the Wretched. Go!$B",logDesc="Travel to Ratchet in the Barrens and speak with Wrenix the Wretched."} end
if not DB[2383] then DB[2383]={id=2383,zoneId=-81,name="Simple Parchment",level=1,minLevel=1,giver="Gornek",giverType="NPC",giverId=3143,ender="Frang",enderType="NPC",enderId=3153,poiX=-600,poiY=-4186,wowhead="https://www.wowhead.com/wotlk/quest=2383",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ah, while you were gone a parchment came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.",logDesc="Read the Simple Parchment and speak to Frang in the Valley of Trials."} end
if not DB[2398] then DB[2398]={id=2398,zoneId=1517,name="The Lost Dwarves",level=40,minLevel=35,giver="Prospector Stormpike",giverType="NPC",giverId=1356,ender="3",enderType="NPC",enderId=6906,rewardNextId=2240,poiX=-4631,poiY=-1304,wowhead="https://www.wowhead.com/wotlk/quest=2398",image="assets/images/quests/placeholder.png",xpDiff=1,money=500,desc="The dig site at Uldaman wasn't always overrun.  We Ironforge dwarves used to control the area, but... that was before the troggs came.  They came so fast and in such numbers that not even dwarven might could stop them!$B$BIn fact, their attack was so sudden that I fear some of our people may be trapped behind enemy lines.$B$BMy friend Baelog led a small band of dwarves deep within the site just before the troggs showed up.  If he and his company live, then I want you to find them.",logDesc="Find Baelog in Uldaman."} end
if not DB[2399] then DB[2399]={id=2399,zoneId=141,name="The Sprouted Fronds",level=10,minLevel=4,wowhead="https://www.wowhead.com/wotlk/quest=2399",image="assets/images/quests/placeholder.png",xpDiff=1,rewards={{id=5205,qty=5}}} end
if not DB[2418] then DB[2418]={id=2418,zoneId=1517,name="Power Stones",level=36,minLevel=30,giver="Rigglefuzz",giverType="NPC",giverId=2817,ender="Rigglefuzz",enderType="NPC",enderId=2817,poiX=-6767,poiY=-3134,wowhead="https://www.wowhead.com/wotlk/quest=2418",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A while ago, I had an incident with the Shadowforge Dwarves.  They brought me to Angor Fortress to study two types of strange stones from Uldaman.  I discovered that the stones were sustained, stable power sources if treated correctly.  It's amazing the things one can find in that old dig site!$B$BAnyway, after I told them the secret of the stones they kicked me out of Angor Fortress and began digging for more in Uldaman.$B$BI want those stones for myself!  Bring me both types and I'll pay you plenty!",logDesc="Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.",choiceRewards={{id=9522,qty=1},{id=10358,qty=1},{id=10359,qty=1}}} end
if not DB[2438] then DB[2438]={id=2438,zoneId=141,name="The Emerald Dreamcatcher",level=6,minLevel=1,giver="Tallonkai Swiftroot",giverType="NPC",giverId=3567,ender="Tallonkai Swiftroot",enderType="NPC",enderId=3567,rewardNextId=2459,poiX=9899,poiY=985,wowhead="https://www.wowhead.com/wotlk/quest=2438",image="assets/images/quests/placeholder.png",xpDiff=4,money=100,desc="I was once given an emerald dreamcatcher from Gaerolas Talvethen, the warden of the druids in the Ban'ethil Barrow Den. This powerful amulet is able to siphon energy from the Emerald Dream, bestowing luck upon those who carry it.$B$BSadly, I have not been able to retrieve it from my dresser in Starbreeze Village... Although Starbreeze was once a tranquil place, it has now succumbed to the corruption of the furbolg that reside there.$B$BPerhaps you would be willing to recover my dreamcatcher, $c? ",logDesc="Bring the Emerald Dreamcatcher to Tallonkai Swiftroot in Dolanaar."} end
if not DB[2439] then DB[2439]={id=2439,zoneId=1537,name="The Platinum Discs",level=47,minLevel=40,giver="High Explorer Magellas",giverType="NPC",giverId=5387,ender="Dinita Stonemantle",enderType="NPC",enderId=7292,poiX=-4667,poiY=-1266,wowhead="https://www.wowhead.com/wotlk/quest=2439",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This object is an incredible find.  The ancient Titans, or the Creators as these discs refer to them as, are the link to our enchanted creation, if the lore stored in here is correct!  We'll need to invest as much research time into this as possible.$B$BAs for you, heroic $c, take this voucher to Dinita Stonemantle at the vault.  It grants you what I think is a fitting for such a tremendous find!$B$BReturn to me directly when you are ready; there is much more to do for the Explorers' League!",logDesc="Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge.",rewards={{id=9587,qty=1}},choiceRewards={{id=3928,qty=5},{id=6149,qty=5}}} end
if not DB[2440] then DB[2440]={id=2440,zoneId=1638,name="The Platinum Discs",level=47,minLevel=40,giver="Sage Truthseeker",giverType="NPC",giverId=3978,ender="Bena Winterhoof",enderType="NPC",enderId=3009,poiX=-1176,poiY=158,wowhead="https://www.wowhead.com/wotlk/quest=2440",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I shall focus my energies on these discs; they will reveal their true workings to me in due time.$B$BAs for you $N, I will now reward you for your diligence in bringing this to my attention.  Take this voucher to Bena Winterhoof, the alchemy trainer for Thunder Bluff.  She will give you a special item I believe you will find appealing, and she will supply you with a choice of potions from my personal stock.$B$BReturn to me soon, as I sense there is much more at hand for us to do regarding this find.",logDesc="Take the reward voucher to Bena Winterhoof in Thunder Bluff.",rewards={{id=9587,qty=1}},choiceRewards={{id=3928,qty=5},{id=6149,qty=5}}} end
if not DB[2458] then DB[2458]={id=2458,zoneId=-162,name="Deep Cover",level=-1,minLevel=20,giver="Shenthul",giverType="NPC",giverId=3401,ender="Taskmaster Fizzule",enderType="NPC",enderId=7233,poiX=1771,poiY=-4284,wowhead="https://www.wowhead.com/wotlk/quest=2458",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The Venture Company... Perhaps you have heard of them?$B$BFor one year we have worked on planting an agent deep within their ranks. Through much hard work and careful planning, we succeeded.$B$BRecently we received word that the Venture Co. are planning something on a grand scale. Go north of the Sludge Fen to the Venture Co. tower and contact our undercover agent, Taskmaster Fizzule.$B$BWhen you find the tower, use this flare gun, then approach Fizzule and show him the salute of the Shattered Hand.$B",logDesc="Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.$B$BWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.$B$BThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.",rewards={{id=8066,qty=1}}} end
if not DB[2459] then DB[2459]={id=2459,zoneId=141,name="Ferocitas the Dream Eater",level=8,minLevel=1,giver="Tallonkai Swiftroot",giverType="NPC",giverId=3567,ender="Tallonkai Swiftroot",enderType="NPC",enderId=3567,poiX=9899,poiY=985,wowhead="https://www.wowhead.com/wotlk/quest=2459",image="assets/images/quests/placeholder.png",xpDiff=6,money=450,desc="The emerald... It is missing! My dreamcatcher has been damaged!$B$BThere is a band of Gnarlpine mystics located to the north of Starbreeze. I have heard reports that their leader, Ferocitas the Dream Eater has been wearing a necklace that glows green in the night. Now seeing my dreamcatcher, I am sure that he has stolen my emerald... He would never realize that its power is useless to him.$B$BFind this missing jewel, $N. And, while you're there, clear out some of the corrupted mystics as well.",logDesc="Tallonkai Swiftroot in Dolanaar wants you to kill 7 Gnarlpine Mystics and find the Missing Jewel."} end
if not DB[2460] then DB[2460]={id=2460,zoneId=-162,name="The Shattered Salute",level=-1,minLevel=20,giver="Shenthul",giverType="NPC",giverId=3401,ender="Shenthul",enderType="NPC",enderId=3401,rewardNextId=2458,poiX=1771,poiY=-4284,wowhead="https://www.wowhead.com/wotlk/quest=2460",image="assets/images/quests/placeholder.png",xpDiff=1,desc="As a rogue of the Shattered Hand, it is imperative that you learn the Shattered Salute. It is the only way to truly identify another member of the Hand.$B$BWatch, learn, repeat.",logDesc="Perform the Shattered Salute on Shenthul."} end
if not DB[2478] then DB[2478]={id=2478,zoneId=-162,name="Mission: Possible But Not Probable",level=-1,minLevel=20,giver="Taskmaster Fizzule",giverType="NPC",giverId=7233,ender="Shenthul",enderType="NPC",enderId=3401,rewardNextId=2479,poiX=1237,poiY=-2995,wowhead="https://www.wowhead.com/wotlk/quest=2478",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You will need to steal the tower key from Foreman Silixiz, $N. Once you've got the key in your possession, hold on to it - I may need it later.$B$BRemember, the poison has weakened everything in this tower. Use your abilities to bring chaos and destruction to its inhabitants. Slay them all -- show no mercy!$B$BOnce everything inside lays in a bloodied heap, pick Gallywix's lockbox and steal the cache of Zanzil's mixture held inside. Take both the head of Gallywix and the mixture to Shenthul in Orgrimmar.",logDesc="Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.$B$BAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.$B",rewards={{id=18160,qty=1}}} end
if not DB[2479] then DB[2479]={id=2479,zoneId=-162,name="Hinott's Assistance",level=-1,minLevel=20,giver="Shenthul",giverType="NPC",giverId=3401,ender="Serge Hinott",enderType="NPC",enderId=2391,rewardNextId=2480,poiX=1771,poiY=-4284,wowhead="https://www.wowhead.com/wotlk/quest=2479",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Take a sample of the mixture to Serge Hinott in Tarren Mill.$B$BIf anyone can cure you, it's Serge. Live long enough and Serge will show you the ways of poison creation and use.",logDesc="Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.$B$BTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!$B$B"} end
if not DB[2480] then DB[2480]={id=2480,zoneId=-162,name="Hinott's Assistance",level=-1,minLevel=20,giver="Serge Hinott",giverType="NPC",giverId=2391,ender="Serge Hinott",enderType="NPC",enderId=2391,poiX=-9,poiY=-905,wowhead="https://www.wowhead.com/wotlk/quest=2480",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I have never seen such wondrous results from a poison! Zanzil you say? Never heard of him, however, I must commend him on the creation of this concoction.$B$BSo, I am to cure you of this and then teach you how to make use of the poison?$B$BGive me a few moments to examine the toxin, $N.",logDesc="Wait for Serge Hinott to complete the cure.",rewards={{id=8095,qty=1}}} end
if not DB[2498] then DB[2498]={id=2498,zoneId=141,name="Return to Denalan",level=9,minLevel=4,giver="Rellian Greenspyre",giverType="NPC",giverId=3517,ender="Denalan",enderType="NPC",enderId=2080,rewardNextId=2499,poiX=10086,poiY=2534,wowhead="https://www.wowhead.com/wotlk/quest=2498",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I have just received word that  Denalan at Lake Al'Ameth has discovered what may be the cause of the tumors that plague the timberlings. Please speak with him, and tell him I sent you.$B$BMake haste, $N; he needs our help.",logDesc="Rellian Greenspyre wants you to speak with Denalan at Lake Al'Ameth."} end
if not DB[2499] then DB[2499]={id=2499,zoneId=141,name="Oakenscowl",level=9,minLevel=4,giver="Denalan",giverType="NPC",giverId=2080,ender="Denalan",enderType="NPC",enderId=2080,poiX=9507,poiY=714,wowhead="https://www.wowhead.com/wotlk/quest=2499",image="assets/images/quests/placeholder.png",xpDiff=5,money=300,desc="In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home.$B$BI dared not get too close, but even from a distance, it is obvious: Oakenscowl is being poisoned by the largest tumor I have ever seen...  I would call it gargantuan, even.$B$B$N, you have already done much to aid my efforts, but I ask of you one more task. Hunt down Oakenscowl and collect the tumor; remove this source of corruption from my home.",logDesc="Denalan at Lake Al'Ameth wants you to collect the Gargantuan Tumor from Oakenscowl.",choiceRewards={{id=5458,qty=1},{id=5589,qty=1}}} end
if not DB[2500] then DB[2500]={id=2500,zoneId=38,name="Badlands Reagent Run",level=39,minLevel=36,giver="Ghak Healtouch",giverType="NPC",giverId=1470,ender="Ghak Healtouch",enderType="NPC",enderId=1470,poiX=-5396,poiY=-3016,wowhead="https://www.wowhead.com/wotlk/quest=2500",image="assets/images/quests/placeholder.png",xpDiff=5,money=4500,desc="$C, I would make use of your services.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.$B$BI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.$B$BAcquire these items for me, you'll get some coin out of the deal.$B$BWell, what say ye?",logDesc="Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar."} end
if not DB[2501] then DB[2501]={id=2501,zoneId=38,name="Badlands Reagent Run II",level=44,minLevel=40,giver="Ghak Healtouch",giverType="NPC",giverId=1470,ender="Ghak Healtouch",enderType="NPC",enderId=1470,poiX=-5396,poiY=-3016,wowhead="https://www.wowhead.com/wotlk/quest=2501",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have been most helpful to me, $N.  I would like to reward you with the very recipe for the brew I gave you earlier, but I must ask of you a favor that is quite dangerous.$B$BThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be careful.  Once you have all three filled, bring them to me.$B$BDo this, and the recipe will be yours.",logDesc="Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Ghak Healtouch in Thelsamar."} end
if not DB[2518] then DB[2518]={id=2518,zoneId=1657,name="Tears of the Moon",level=12,minLevel=5,giver="Priestess A'moora",giverType="NPC",giverId=7313,ender="Priestess A'moora",enderType="NPC",enderId=7313,rewardNextId=2520,poiX=9632,poiY=2550,wowhead="https://www.wowhead.com/wotlk/quest=2518",image="assets/images/quests/placeholder.png",xpDiff=6,money=1000,desc="Lady Sathrah was once beloved of Elune. Graceful and pure, the spider spun her silver threads through the moonlight, catching the evening mist. The silvery dew had strong healing powers and was kept here in the temple.$B$BBut of late, Sathrah has descended into madness. Her future generations are now threatened as well.$B$BFind Lady Sathrah, $N, and end her suffering. She dwells along the northern borders of Teldrassil, near Wellspring Lake. Gather her silvery spinnerets and bring them back to me.",logDesc="Priestess A'moora in the Temple of the Moon at Darnassus wants you to bring her Lady Sathrah's Silvery Spinnerets."} end
if not DB[2519] then DB[2519]={id=2519,zoneId=1657,name="The Temple of the Moon",level=10,minLevel=5,giver="Sister Aquinne",giverType="NPC",giverId=7316,ender="Priestess A'moora",enderType="NPC",enderId=7313,rewardNextId=2518,poiX=9915,poiY=2632,wowhead="https://www.wowhead.com/wotlk/quest=2519",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A once great creature of the forest is in need of help, $r.$B$BThere is a difficult task that must be done.$B$BPlease seek out Priestess A'moora; she will explain things to you. Find her to the southeast of here, inside the Temple of the Moon.",logDesc="Sister Aquinne wants you to speak with Priestess A'moora in the Temple of the Moon."} end
if not DB[2520] then DB[2520]={id=2520,zoneId=1657,name="Sathrah's Sacrifice",level=12,minLevel=5,giver="Priestess A'moora",giverType="NPC",giverId=7313,ender="Priestess A'moora",enderType="NPC",enderId=7313,poiX=9632,poiY=2550,wowhead="https://www.wowhead.com/wotlk/quest=2520",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest.$B$BInside this temple, find the central fountain. There is where you may leave the sacrifice.  The holy waters will purify and cleanse the corruption that drove Sathrah mad.$B$BWhen you have completed this, return to me.",logDesc="Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her.",choiceRewards={{id=9600,qty=1},{id=9601,qty=1}}} end
if not DB[2521] then DB[2521]={id=2521,zoneId=4,name="To Serve Kum'isha",level=55,minLevel=45,giver="Kum'isha the Collector",giverType="NPC",giverId=7363,ender="Kum'isha the Collector",enderType="NPC",enderId=7363,poiX=-11363,poiY=-2983,wowhead="https://www.wowhead.com/wotlk/quest=2521",image="assets/images/quests/placeholder.png",xpDiff=7,desc="$R, can your miniscule brain comprehend the rarity of a flawless sphere of draenethyst? Draenei have spent lifetimes in search of just one of these crystals, only to meet horrible fates, their purpose unfulfilled.$B$BSo you stand before Kum'isha, knowing what Kum'isha has requested and still wish to assist? Very well, $r... At any time during your travels across these lands, should you find a flawless sphere of draenethyst, return it to me and I shall reward you with riches beyond your wildest dreams.  ",logDesc="In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.$B$BBe warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.$B$BYou will be rewarded for each Flawless Draenethyst Sphere you have collected.",rewards={{id=10752,qty=1}}} end
if not DB[2522] then DB[2522]={id=2522,zoneId=4,name="Kum'isha's Endeavors",level=55,minLevel=45,giver="Kum'isha the Collector",giverType="NPC",giverId=7363,ender="Kum'isha the Collector",enderType="NPC",enderId=7363,poiX=-11363,poiY=-2983,wowhead="https://www.wowhead.com/wotlk/quest=2522",image="assets/images/quests/placeholder.png",desc="Even though the portal conjuration was a failure, I remain hopeful that my next attempt will be successful.$B$BThe hope of the Draenei is as fervent as your greed for trinkets, $r. Go back out into these cursed lands and recover another flawless draenethyst sphere.$B$BOf course, the choice to take on this task is completely left to you *grin*.",logDesc="Find and return a Flawless Draenethyst Sphere to Kum'isha the Collector.",rewards={{id=10752,qty=1}}} end
if not DB[2523] then DB[2523]={id=2523,zoneId=361,name="Corrupted Songflower",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=2523",image="assets/images/quests/placeholder.png"} end
if not DB[2541] then DB[2541]={id=2541,zoneId=141,name="The Sleeping Druid",level=8,minLevel=3,giver="Oben Rageclaw",giverType="NPC",giverId=7317,ender="Oben Rageclaw",enderType="NPC",enderId=7317,rewardNextId=2561,poiX=9741,poiY=1526,wowhead="https://www.wowhead.com/wotlk/quest=2541",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Gnarlpine shaman that inhabit this place have discovered a way of separating a sleeping druid's spirit from the physical body. The furbolg have animated my physical form and are using it to attack anyone that attempts to explore the Ban'ethil Barrow Den. I am now trapped in the Emerald Dream, powerless to stop this.$B$BYou must help me. The Gnarlpine shaman carry a strange charm which is used to perform this ritual, and I'd like to examine it. Please, $N, bring one to me.",logDesc="Bring a Shaman Voodoo Charm to Oben Rageclaw in the Ban'ethil Barrow Den."} end
if not DB[2561] then DB[2561]={id=2561,zoneId=141,name="Druid of the Claw",level=10,minLevel=3,giver="Oben Rageclaw",giverType="NPC",giverId=7317,ender="Oben Rageclaw",enderType="NPC",enderId=7317,poiX=9741,poiY=1526,wowhead="https://www.wowhead.com/wotlk/quest=2561",image="assets/images/quests/placeholder.png",xpDiff=6,desc="After examining this charm, $N, I see now what must be done. Please take it, and do as I ask.$B$BYou are to explore the deepest areas of the Ban'ethil Barrow Den. There, you will find my soulless body... Although I regret what I am about to tell you, I see no other way to free myself from the control of the Gnarlpine.$B$BIn order for me to escape them, you must kill my physical form.  Once that is done, use the voodoo charm on my fallen body. After you have completed this task, please return to me.",logDesc="Oben Rageclaw wants you to kill his soulless body, and then use the Voodoo Charm.",choiceRewards={{id=9598,qty=1},{id=18957,qty=1}}} end
if not DB[2581] then DB[2581]={id=2581,zoneId=4,name="Snickerfang Jowls",level=50,minLevel=45,giver="Bloodmage Drazial",giverType="NPC",giverId=7505,ender="Bloodmage Drazial",enderType="NPC",enderId=7505,poiX=-10884,poiY=-2935,wowhead="https://www.wowhead.com/wotlk/quest=2581",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is a well known fact that hyenas possess tremendous strength in their jowls, but the strength to snap through three inches of thorium steel? Impossible, improbable, and yet I have seen this demonstrated with my own eyes.$B$BVenture forth, into the Blasted Lands, and bring me three snickerfang jowls. As you search for the snickerfang, be on the lookout for boars and scorpoks: The initial assay also requires two blasted boar lungs and one scorpok pincer to complete.",logDesc="Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.",rewards={{id=8410,qty=1}}} end
if not DB[2582] then DB[2582]={id=2582,zoneId=4,name="Rage of Ages",level=50,minLevel=45,giver="Bloodmage Drazial",giverType="NPC",giverId=7505,ender="Bloodmage Drazial",enderType="NPC",enderId=7505,poiX=-10884,poiY=-2935,wowhead="https://www.wowhead.com/wotlk/quest=2582",image="assets/images/quests/placeholder.png",desc="Ah, $N, welcome back. It seems you enjoyed the effect of the robust, operational imbue, derived from snickerfang. Be warned, while the immediate effect is a titanic burst of strength, the long term effects on your spirit and intelligence could be hazardous.$B$BWith that said, do you require more? If so, bring me another three snickerfang jowls, two blasted boar lungs, and one scorpok pincer.",logDesc="Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.",rewards={{id=8410,qty=1}}} end
if not DB[2583] then DB[2583]={id=2583,zoneId=4,name="A Boar's Vitality",level=50,minLevel=45,giver="Bloodmage Drazial",giverType="NPC",giverId=7505,ender="Bloodmage Drazial",enderType="NPC",enderId=7505,poiX=-10884,poiY=-2935,wowhead="https://www.wowhead.com/wotlk/quest=2583",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Within these blasted lands exists two species of boar: the ash-mane boar and the helboar.$B$BIt would appear that the stamina of these beasts renders them nearly immune to harm, as the other animals find them too difficult to kill and consequently, not worth the effort.$B$BWe need to perform further analysis, $N. Should you bring me three blasted boar lungs, two scorpok pincers, and one basilisk brain, I shall create a divine elixir from the residue of the assay. You will be my first test subject!",logDesc="Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.$B",rewards={{id=8411,qty=1}}} end
if not DB[2584] then DB[2584]={id=2584,zoneId=4,name="Spirit of the Boar",level=50,minLevel=45,giver="Bloodmage Drazial",giverType="NPC",giverId=7505,ender="Bloodmage Drazial",enderType="NPC",enderId=7505,poiX=-10884,poiY=-2935,wowhead="https://www.wowhead.com/wotlk/quest=2584",image="assets/images/quests/placeholder.png",desc="When I first administered the elixir, $N, I could tell that one or two applications would not satiate your appetite. Even now, I can see the hunger in your eyes. The concoction has addictive properties of which, seemingly, the most strong of will cannot resist.$B$BSo be it! Should you require more of the lung juice cocktail, venture back into the wasteland and find for me three blasted boar lungs, two scorpok pincers, and one basilisk brain.",logDesc="Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.$B",rewards={{id=8411,qty=1}}} end
if not DB[2585] then DB[2585]={id=2585,zoneId=4,name="The Decisive Striker",level=50,minLevel=45,giver="Bloodmage Drazial",giverType="NPC",giverId=7505,ender="Bloodmage Drazial",enderType="NPC",enderId=7505,poiX=-10884,poiY=-2935,wowhead="https://www.wowhead.com/wotlk/quest=2585",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Have you ever watched them in battle, $N? The scorpoks, I mean. Have you ever seen the grace and agility with which they move? The decisiveness of their strikes?$B$BIf only we could somehow isolate that agility and encapsulate it, we would be wealthy beyond our... I mean... it would be a boon for the scientific community.$B$BAssist me, $N, and I shall allow you a sampling of the assay.$B$BIn order to create a stable sample, I will need three scorpok pincers, two vulture gizzards, and one blasted boar lung.",logDesc="Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.$B",rewards={{id=8412,qty=1}}} end
if not DB[2586] then DB[2586]={id=2586,zoneId=4,name="Salt of the Scorpok",level=50,minLevel=45,giver="Bloodmage Drazial",giverType="NPC",giverId=7505,ender="Bloodmage Drazial",enderType="NPC",enderId=7505,poiX=-10884,poiY=-2935,wowhead="https://www.wowhead.com/wotlk/quest=2586",image="assets/images/quests/placeholder.png",desc="You live! This is good news, indeed. I assume you are back for more of the scorpok assay?$B$BVery well, $N, back to the wasteland with you and do not return until you have collected three scorpok pincers, two vulture gizzards, and one blasted boar lung.",logDesc="Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.",rewards={{id=8412,qty=1}}} end
if not DB[2601] then DB[2601]={id=2601,zoneId=4,name="The Basilisk's Bite",level=50,minLevel=45,giver="Bloodmage Lynnore",giverType="NPC",giverId=7506,ender="Bloodmage Lynnore",enderType="NPC",enderId=7506,poiX=-10886,poiY=-2938,wowhead="https://www.wowhead.com/wotlk/quest=2601",image="assets/images/quests/placeholder.png",xpDiff=5,desc="These wastelands are riddled with redstone basilisk, $N. These basilisk have adapted and flourished, more so than any of the other wildlife within the region.$B$BI have watched from afar as they hunt and go about their daily activities - the beasts exhibit a thought process more complex than even some humanoids.$B$BI must study their brains!$B$BRetrieve ten of their brains for me, $N. The compound cannot be complete, however, without two vulture gizzards to form the base of the solution.",logDesc="Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.$B",rewards={{id=8423,qty=1}}} end
if not DB[2602] then DB[2602]={id=2602,zoneId=4,name="Infallible Mind",level=50,minLevel=45,giver="Bloodmage Lynnore",giverType="NPC",giverId=7506,ender="Bloodmage Lynnore",enderType="NPC",enderId=7506,poiX=-10886,poiY=-2938,wowhead="https://www.wowhead.com/wotlk/quest=2602",image="assets/images/quests/placeholder.png",desc="Your focused concentration has dwindled so soon? More research must be done!$B$BOh yes, the price remains the same, $N. Venture forth into the blasted lands and return to me with ten brains from the redstone and two vulture gizzards.$B",logDesc="Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.",rewards={{id=8423,qty=1}}} end
if not DB[2603] then DB[2603]={id=2603,zoneId=4,name="Vulture's Vigor",level=50,minLevel=45,giver="Bloodmage Lynnore",giverType="NPC",giverId=7506,ender="Bloodmage Lynnore",enderType="NPC",enderId=7506,poiX=-10886,poiY=-2938,wowhead="https://www.wowhead.com/wotlk/quest=2603",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Death does indeed have wings in these blasted lands, $r. I have witnessed the black slayers and bonepickers feasting upon the corpse of many a fallen explorer - sometimes feeding upon the most vile and disease ridden of carcasses. It is a wonder, then, how their internal systems overcome the pestilence that claims these lands.$B$BAssist me in my studies, $N! Gizzards I need! Two snickerfang jowls will also be required for the base of the concoction.$B$BYou shall be rewarded two-fold for your efforts.",logDesc="Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.$B",rewards={{id=8424,qty=1}}} end
if not DB[2604] then DB[2604]={id=2604,zoneId=4,name="Spiritual Domination",level=50,minLevel=45,giver="Bloodmage Lynnore",giverType="NPC",giverId=7506,ender="Bloodmage Lynnore",enderType="NPC",enderId=7506,poiX=-10886,poiY=-2938,wowhead="https://www.wowhead.com/wotlk/quest=2604",image="assets/images/quests/placeholder.png",desc="I see that the inner fire has dwindled. Would you say the spiritual euphoria lasted an hour?$B$BIf it's more of the gizzard gum you desire, then more of the gizzards I require. Back to the wastelands, $N. Do not return until you have recovered ten gizzards and two jowls.",logDesc="Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.$B",rewards={{id=8424,qty=1}}} end
if not DB[2605] then DB[2605]={id=2605,zoneId=440,name="The Thirsty Goblin",level=49,minLevel=44,giver="Marin Noggenfogger",giverType="NPC",giverId=7564,ender="Marin Noggenfogger",enderType="NPC",enderId=7564,rewardNextId=2606,poiX=-7193,poiY=-3793,wowhead="https://www.wowhead.com/wotlk/quest=2605",image="assets/images/quests/placeholder.png",xpDiff=5,money=7000,desc="I've got an idea, see. I've heard of some strange creatures called dew collectors that live to the southwest... and that they are able to store water in special glands.$B$BI think that if I could get one of these glands, I could create a drink that would quench my terrible thirst! Do you think you could help me, $N?$B$BLook for the cactus garden, $N; that's where you'll find the dew collectors.",logDesc="Collect a Laden Dew Gland and bring it to Marin Noggenfogger in Gadgetzan."} end
if not DB[2606] then DB[2606]={id=2606,zoneId=440,name="In Good Taste",level=49,minLevel=44,giver="Marin Noggenfogger",giverType="NPC",giverId=7564,ender="Sprinkle",enderType="NPC",enderId=7583,rewardNextId=2641,poiX=-7193,poiY=-3793,wowhead="https://www.wowhead.com/wotlk/quest=2606",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Blech! This stuff tastes terrible! So much for that idea...$B$BWait, what's that? Oh, I know, I know, you think I shouldn't give up on this stuff. Well, okay then.$B$BUhhhh, I have an idea! Brilliant! Take this dew to my friend Sprinkle -- she's an excellent chef. Tell her what we're up to here and that we want to make it go down a little easier.$B$BI mean, if it's going to taste that bad, it at least should have some kick to it... And I'm just not feeling it... ",logDesc="Marin Noggenfogger wants you to speak with Sprinkle in Gadgetzan."} end
if not DB[2607] then DB[2607]={id=2607,zoneId=-162,name="The Touch of Zanzil",level=20,minLevel=20,giver="Master Mathias Shaw",giverType="NPC",giverId=332,ender="Doc Mixilpixil",enderType="NPC",enderId=7207,poiX=-8815,poiY=362,wowhead="https://www.wowhead.com/wotlk/quest=2607",image="assets/images/quests/placeholder.png",desc="It appears as if you've brought back more information than even I expected. This certainly is a strange turn of events, $N.$B$BA cure? Hrm... Go down to the cellar and speak with Doc Mixilpixil - he may be able to help.",logDesc="Speak with Doc Mixilpixil in the cellar of the Barracks."} end
if not DB[2608] then DB[2608]={id=2608,zoneId=-162,name="The Touch of Zanzil",level=20,minLevel=20,giver="Doc Mixilpixil",giverType="NPC",giverId=7207,ender="Doc Mixilpixil",enderType="NPC",enderId=7207,poiX=-8806,poiY=332,wowhead="https://www.wowhead.com/wotlk/quest=2608",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Oh my, you look like death. Correction - I've seen death, you look worse than death. You, $g sir:miss;, would be what death coughed up at his last physical.$B$BHah! You hear that Noarm? Write that one down!$B$B*Cough* Hrm yes, in order for me to help you, I'll need to draw some blood. Don't worry, it only hurts the first few... fifty times or so... /lay down when you're ready for the treatment, $N.",logDesc="/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?$B"} end
if not DB[2609] then DB[2609]={id=2609,zoneId=-162,name="The Touch of Zanzil",level=20,minLevel=20,giver="Doc Mixilpixil",giverType="NPC",giverId=7207,ender="Doc Mixilpixil",enderType="NPC",enderId=7207,poiX=-8806,poiY=332,wowhead="https://www.wowhead.com/wotlk/quest=2609",image="assets/images/quests/placeholder.png",xpDiff=4,desc="It's unanimous, $N. You've got the 'itis.'$B$BLuckily, I have a cure for the 'itis.'$B$BHere's what I need: One bundle of simple wildflowers, one leaded vial, one bronze tube, and last but certainly not least, one spool of light chartreuse silk thread. Ol' Emma left a spool of it for me at 'The Finest Thread.' You can find the shop along the canals.$B$BHurry along now, $N, and try not to touch anyone until you're cured. Oh, and Dr. Montgomery says you need a shower -- his words, not mine.",logDesc="Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young $g fella:lady;. ",rewards={{id=8432,qty=1}}} end
if not DB[2621] then DB[2621]={id=2621,zoneId=4,name="The Disgraced One",level=50,minLevel=45,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Dispatch Commander Ruag",enderType="NPC",enderId=7623,rewardNextId=2622,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=2621",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Regret. It is all I have now. One bad decision resulting in several horrible outcomes. If only I had waited for those orders. Maybe they would have detailed the horrors that awaited us in those cursed lands! Maybe they were to redirect us to another detail? Ultimately, it was my fault. All of it was my fault.$B$BSo here I stand, awaiting orders. I must know. I must have those orders.$B$BDispatch Commander Ruag resides in Stonard. Find him and find out what became of the orders.$B",logDesc="Speak to Dispatch Commander Ruag at Stonard in Swamp of Sorrows."} end
if not DB[2622] then DB[2622]={id=2622,zoneId=8,name="The Missing Orders",level=50,minLevel=45,giver="Dispatch Commander Ruag",giverType="NPC",giverId=7623,ender="Bengor",enderType="NPC",enderId=7643,rewardNextId=2623,poiX=-10461,poiY=-3319,wowhead="https://www.wowhead.com/wotlk/quest=2622",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The orders? What could you possibly want with the orders?$B$BWhat are you implying, $N? Of course I relayed those orders! The soldiers I sent the orders with were ambushed and brutally beaten by murlocs. Only one survived, if you can call that surviving. He can hardly speak, cannot walk, and must be fed through a tube. If you want to know what happened to those orders, speak with Bengor. I'm sure he is around here somewhere... and, $N, be mindful of what you stick your nose into - it may get bitten off.",logDesc="Speak to Bengor at Stonard in Swamp of Sorrows."} end
if not DB[2623] then DB[2623]={id=2623,zoneId=8,name="The Swamp Talker",level=55,minLevel=45,giver="Bengor",giverType="NPC",giverId=7643,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,poiX=-10498,poiY=-3254,wowhead="https://www.wowhead.com/wotlk/quest=2623",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Orders were given by the dispatch commander. We took... took orders. On way to Blasted Lands, ambushed.$B$BMurlocs... Many murlocs... One named Swamp Talker. Took orders from my hands as spear thrust into my skull. East... cave....$B$B<Bengor passes out.>$B",logDesc="Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde."} end
if not DB[2641] then DB[2641]={id=2641,zoneId=440,name="Sprinkle's Secret Ingredient",level=49,minLevel=44,giver="Sprinkle",giverType="NPC",giverId=7583,ender="Sprinkle",enderType="NPC",enderId=7583,poiX=-7111,poiY=-3742,wowhead="https://www.wowhead.com/wotlk/quest=2641",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When I was a kid, my sister used to do all the cooking. It was horrible! I could barely stomach some of her concoctions -- until I found what I like to call my \"secret\" ingredient! Add it to anything, and... WOW! It tastes great!$B$BWhat is it, you ask? It's a mushroom called the Violet Tragan. If you want me to help you turn this horrid-tasting brew into something edible, head to the Hinterlands, and look for a small lake there.$B$BOh, and remember, the Violet Tragan can only be found underwater.",logDesc="Sprinkle in Gadgetzan wants you to collect a Violet Tragan and return it to her."} end
if not DB[2661] then DB[2661]={id=2661,zoneId=440,name="Delivery for Marin",level=49,minLevel=44,giver="Sprinkle",giverType="NPC",giverId=7583,ender="Marin Noggenfogger",enderType="NPC",enderId=7564,rewardNextId=2662,poiX=-7111,poiY=-3742,wowhead="https://www.wowhead.com/wotlk/quest=2661",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Here's the Violet Powder, $N. Take it to Marin and tell him he owes me a favor!",logDesc="Sprinkle wants to you take the Violet Powder to Marin Noggenfogger in Gadgetzan."} end
if not DB[2662] then DB[2662]={id=2662,zoneId=440,name="Noggenfogger Elixir",level=49,minLevel=44,giver="Marin Noggenfogger",giverType="NPC",giverId=7564,ender="Marin Noggenfogger",enderType="NPC",enderId=7564,poiX=-7193,poiY=-3793,wowhead="https://www.wowhead.com/wotlk/quest=2662",image="assets/images/quests/placeholder.png",money=7000,desc="Now, to mix this powder in with the dew.$B$BCome back and talk to me in a minute... after I have perfected the fabulous Noggenfogger Elixir!",logDesc="Marin Noggenfogger wants you to speak to him again after he creates his elixir.",rewards={{id=8529,qty=5}}} end
if not DB[2681] then DB[2681]={id=2681,zoneId=4,name="The Stones That Bind Us",level=57,minLevel=45,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,rewardNextId=2702,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=2681",image="assets/images/quests/placeholder.png",xpDiff=6,desc="It will take more than you alone to overcome the forces of Razelikh and his subordinates.$B$BGather a suitable group of adventurers and free my men of their eternal torture! Eighteen stones you must shatter.$B$BFight hard and die with honor, $N.",logDesc="Free nine Servants of Razelikh, three Servants of Sevine, three Servants of Allistarj, and three Servants of Grol. Return to the Fallen Hero when your task is complete. You must remain within close proximity of the stones or the process will fail."} end
if not DB[2701] then DB[2701]={id=2701,zoneId=4,name="Heroes of Old",level=57,minLevel=45,giver="Corporal Thund Splithoof",giverType="NPC",giverId=7750,wowhead="https://www.wowhead.com/wotlk/quest=2701",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Please, take from this a relic of old. We no longer have a use for the item.$B$BMay it serve you well in your fight against the legion.$B",logDesc="Open the chest and claim your reward.",rewards={{id=10659,qty=1}}} end
if not DB[2702] then DB[2702]={id=2702,zoneId=4,name="Heroes of Old",level=57,minLevel=45,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Corporal Thund Splithoof",enderType="NPC",enderId=7750,rewardNextId=2701,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=2702",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You have honored me with your nobility and heroism, $N.$B$BYou have also honored them...",logDesc="Speak to Corporal Thund Splithoof."} end
if not DB[2721] then DB[2721]={id=2721,zoneId=4,name="Kirith",level=58,minLevel=45,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Spirit of Kirith",enderType="NPC",enderId=7729,rewardNextId=2743,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=2721",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As one chapter of your adventure closes, another one begins, $N.$B$BOne of my men is still unaccounted for, lost somewhere in the Blasted Lands. I am talking about Lieutenant Kirith, of course.$B$BAs I had mentioned earlier, we were both imprisoned and tortured by Allistarj, but poor Kirith, his strength of will faltered. I could hear the experiments from my cage; the tortured screams rang through the halls of the cave. That was the last I saw or heard of Kirith.",logDesc="Find out what became of Lieutenant Kirith."} end
if not DB[2741] then DB[2741]={id=2741,zoneId=440,name="The Super Egg-O-Matic",level=47,minLevel=42,wowhead="https://www.wowhead.com/wotlk/quest=2741",image="assets/images/quests/placeholder.png",xpDiff=5,rewards={{id=8647,qty=1}}} end
if not DB[2742] then DB[2742]={id=2742,zoneId=47,name="Rin'ji is Trapped!",level=47,minLevel=42,giver="Rin'ji",giverType="NPC",giverId=7780,rewardNextId=2782,poiX=263,poiY=-2758,wowhead="https://www.wowhead.com/wotlk/quest=2742",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hey $r!$B$BRin'ji lost axe and was captured! Please, help Rin'ji escape. Me know that $r like you don't like Rin'ji's kind, but Rin'ji begs! Must get out of here!$B$BGot something for nice $r if $Ghe helps Rin'ji out of here:she helps Rin'ji out of here;...$B$BRin'ji is hiding something secret at the Overlook Cliffs.",logDesc="Escort Rin'ji out of the Quel'Danil Lodge, then find his hidden secret at the Overlook Cliffs to the east."} end
if not DB[2743] then DB[2743]={id=2743,zoneId=4,name="The Cover of Darkness",level=60,minLevel=45,giver="Spirit of Kirith",giverType="NPC",giverId=7729,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,rewardNextId=2744,wowhead="https://www.wowhead.com/wotlk/quest=2743",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Let us not mince words, $r; my time here is limited.$B$BYou must destroy the triad of power which protects the demon lord, Razelikh. Doing so will not be as simple a task as freeing a damned soul.$B$B<Kirith grins.>$B$BYou see, each of Razelikh's underlings wears a third of an amulet of Razelikh's creation around their neck. The very same amulet you will need in order to summon the arch demon.$B$BReturn to Trebor and tell him what is required to summon Razelikh. He will be able to instruct you further.",logDesc="Return to the Fallen Hero of the Horde with your findings."} end
if not DB[2744] then DB[2744]={id=2744,zoneId=4,name="The Demon Hunter",level=60,minLevel=45,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Loramus Thalipedes",enderType="NPC",enderId=7783,rewardNextId=3141,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=2744",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The triad is protected by Razelikh.$B$BIn exchange for their servitude, Razelikh granted each of them nearly unlimited power within the Blasted Lands. The amulet pieces are each attuned to the lifeforce of their owner, granting them immortality. As long as they remain within the Blasted Lands, they cannot be slain, their life spans extended until the end of days.$B$BThere is one who may be able to assist you further, $N. Travel to Azshara and find the demon hunter, Loramus Thalipedes. Search the islands.",logDesc="Speak with Loramus Thalipedes in Azshara."} end
if not DB[2745] then DB[2745]={id=2745,zoneId=1519,name="Infiltrating the Castle",level=31,minLevel=16,giver="Elling Trias",giverType="NPC",giverId=482,ender="Tyrion",enderType="NPC",enderId=7766,rewardNextId=2746,poiX=-8854,poiY=576,wowhead="https://www.wowhead.com/wotlk/quest=2745",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hmm, an interesting tale, and not one to be taken lightly. Yeah, I can help you, but what you need to do is divvy out a form of justice that's not... legal, if you're to see this through to the end.$B$BLescovar and Marzon need to be dealt with, and swiftly. Do you think you're capable of such a thing?$B$BYou decide. If so, then make haste to the castle and find an old friend of mine, a gnome named Tyrion. He's been watching Lescovar now for a couple weeks. He should be able to help you end this.",logDesc="Speak to Tyrion in Stormwind Castle."} end
if not DB[2746] then DB[2746]={id=2746,zoneId=1519,name="Items of Some Consequence",level=31,minLevel=16,giver="Tyrion",giverType="NPC",giverId=7766,ender="Tyrion",enderType="NPC",enderId=7766,poiX=-8409,poiY=451,wowhead="https://www.wowhead.com/wotlk/quest=2746",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Trias wants the timetable pushed up some, huh? Okay, we can do that, but I'm not ready. And know this, I'm doing the hard part, but you're the one that's going to get $g his:her; hands dirty, understand? Good.$B$BOkay, I'll need you to get me a few things before I can put my plan into effect. I got the perfect disguise that'll get Spybot past those guards.$B$BBring me some silk and a couple apples. The silk's up to you, but Clara's little farm right outside the city has the perfect sized apples.",logDesc="Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind."} end
if not DB[2747] then DB[2747]={id=2747,zoneId=440,name="An Extraordinary Egg",level=60,minLevel=42,giver="Curgle Cranklehop",giverType="NPC",giverId=7763,ender="Curgle Cranklehop",enderType="NPC",enderId=7763,poiX=-7113,poiY=-3831,wowhead="https://www.wowhead.com/wotlk/quest=2747",image="assets/images/quests/placeholder.png",rewards={{id=9541,qty=1}}} end
if not DB[2748] then DB[2748]={id=2748,zoneId=440,name="A Fine Egg",level=60,minLevel=42,giver="Curgle Cranklehop",giverType="NPC",giverId=7763,ender="Curgle Cranklehop",enderType="NPC",enderId=7763,poiX=-7113,poiY=-3831,wowhead="https://www.wowhead.com/wotlk/quest=2748",image="assets/images/quests/placeholder.png",rewards={{id=9540,qty=1}}} end
if not DB[2749] then DB[2749]={id=2749,zoneId=440,name="An Ordinary Egg",level=60,minLevel=42,giver="Curgle Cranklehop",giverType="NPC",giverId=7763,ender="Curgle Cranklehop",enderType="NPC",enderId=7763,poiX=-7113,poiY=-3831,wowhead="https://www.wowhead.com/wotlk/quest=2749",image="assets/images/quests/placeholder.png",rewards={{id=9539,qty=1}}} end
if not DB[2750] then DB[2750]={id=2750,zoneId=440,name="A Bad Egg",level=60,minLevel=42,giver="Curgle Cranklehop",giverType="NPC",giverId=7763,ender="Curgle Cranklehop",enderType="NPC",enderId=7763,poiX=-7113,poiY=-3831,wowhead="https://www.wowhead.com/wotlk/quest=2750",image="assets/images/quests/placeholder.png",money=900} end
if not DB[2751] then DB[2751]={id=2751,zoneId=-121,name="Barbaric Battlements",level=32,minLevel=32,giver="Orokk Omosh",giverType="NPC",giverId=7790,ender="Orokk Omosh",enderType="NPC",enderId=7790,poiX=2064,poiY=-4792,wowhead="https://www.wowhead.com/wotlk/quest=2751",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Twenty generations of Omosh have held this hammer, $N. A hundred thousand tons of metal we have molded. Tragically, it all ends at Orokk, failure of the Omosh: Without kin and incapable of producing offspring.$B$BI cannot let the secret recipes of Omosh die with me! Someone must continue the legacy, Omosh or not!$B$BProve to Orokk you are capable, $N. Bring for Orokk the following: Two patterned bronze bracers, two bronze greatswords, and two sharp claws. Bring them for Orokk and we shall continue.",logDesc="Bring two Patterned Bronze Bracers, two Bronze Greatswords, and two Sharp Claws to Orokk Omosh in Orgrimmar.$B",rewards={{id=7979,qty=1}}} end
if not DB[2752] then DB[2752]={id=2752,zoneId=-121,name="On Iron Pauldrons",level=32,minLevel=32,giver="Orokk Omosh",giverType="NPC",giverId=7790,ender="Orokk Omosh",enderType="NPC",enderId=7790,poiX=2064,poiY=-4792,wowhead="https://www.wowhead.com/wotlk/quest=2752",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Orokk sees the eagerness in your eyes, $N. Like a sponge you soak in the wisdom of the Omosh.$B$BThree lessons I shall teach!$B$BReturn to the anvil, soak in the heat of the forge, create for Orokk four bronze battleaxes and four bronze warhammers. Only then will you learn of the iron pauldron.",logDesc="Bring four Bronze Battleaxes and four Bronze Warhammers to Orokk Omosh in Orgrimmar.",rewards={{id=7978,qty=1}}} end
if not DB[2753] then DB[2753]={id=2753,zoneId=-121,name="Trampled Under Foot",level=36,minLevel=32,giver="Orokk Omosh",giverType="NPC",giverId=7790,ender="Orokk Omosh",enderType="NPC",enderId=7790,poiX=2064,poiY=-4792,wowhead="https://www.wowhead.com/wotlk/quest=2753",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Only two more lessons Orokk will teach, $N. Your muscles ache, I know, but continue on for the Omosh!$B$BBring to Orokk four green iron helms, four green iron bracers, and two green iron leggings - for this you learn and your enemies suffer!",logDesc="Bring four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings to Orokk Omosh in Orgrimmar.",rewards={{id=7981,qty=1}}} end
if not DB[2754] then DB[2754]={id=2754,zoneId=-121,name="Horns of Frenzy",level=36,minLevel=32,giver="Orokk Omosh",giverType="NPC",giverId=7790,ender="Orokk Omosh",enderType="NPC",enderId=7790,poiX=2064,poiY=-4792,wowhead="https://www.wowhead.com/wotlk/quest=2754",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The final lesson Orokk teaches you, $N. To the sacred anvil and forge you return! Bring for Orokk two solid iron mauls, two silvered bronze boots, and two silvered bronze gauntlets.$B$BSee the fear in their eyes as you approach!$B",logDesc="Bring two Solid Iron Mauls, two Silvered Bronze Boots, and two Silvered Bronze Gauntlets to Orokk Omosh in Orgrimmar.",rewards={{id=7980,qty=1}}} end
if not DB[2755] then DB[2755]={id=2755,zoneId=-121,name="Joys of Omosh",level=36,minLevel=32,giver="Orokk Omosh",giverType="NPC",giverId=7790,ender="Orokk Omosh",enderType="NPC",enderId=7790,poiX=2064,poiY=-4792,wowhead="https://www.wowhead.com/wotlk/quest=2755",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Orokk is not crying, $N. Soot is in eye.$B$B<Orokk wipes a tear away.>$B$BThere is one last Omosh family secret Orokk will teach you. Orokk will die happy, thanks to $N.$B$BLearn Omosh dance of joy and then you learn fist of iron!$B",logDesc="Watch and learn the Omosh Dance of Joy.",rewards={{id=7982,qty=1}}} end
if not DB[2756] then DB[2756]={id=2756,zoneId=-121,name="The Old Ways",level=40,minLevel=40,giver="Aturk the Anvil",giverType="NPC",giverId=7792,ender="Aturk the Anvil",enderType="NPC",enderId=7792,poiX=2056,poiY=-4816,wowhead="https://www.wowhead.com/wotlk/quest=2756",image="assets/images/quests/placeholder.png",xpDiff=5,desc="In the time of legends, Aturk would crush the skulls of his enemies and grind the bone into a fine powder for use in filament. Long gone are those days, $r. The Warchief calls for peace among the clans. Old enemies are now only watched with weary eyes!$B$BUnbelievable, I know, but such is the will of Thrall.$B$BEnough lamenting! You are here to learn, and learn you will! Bring me four steel breastplates and four steel helms and you will gain a taste of war!",logDesc="Bring four Steel Breastplates and four Steel Plate Helms to Aturk the Anvil in Orgrimmar.$B"} end
if not DB[2757] then DB[2757]={id=2757,zoneId=-121,name="Booty Bay or Bust!",level=40,minLevel=40,giver="Ox",giverType="NPC",giverId=7793,ender="McGavan",enderType="NPC",enderId=7794,rewardNextId=2760,poiX=2054,poiY=-4809,wowhead="https://www.wowhead.com/wotlk/quest=2757",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Listen, kid, you're not gonna learn anything hanging around here.$B$BI know a guy who knows a guy. He hangs around the smithy in Booty Bay. If you show him this insignia, he'll tell you all about mithril.$B$BSo whadd'ya say? Leave this kid stuff to the babies in diapers, $N -- it's time to move on.$B$BIf you're interested, his name's McGavan. Show him this trinket and he'll recognize your commitment.",logDesc="Speak with McGavan in Booty Bay."} end
if not DB[2758] then DB[2758]={id=2758,zoneId=-121,name="The Origins of Smithing",level=40,minLevel=40,giver="Hank the Hammer",giverType="NPC",giverId=7798,ender="Hank the Hammer",enderType="NPC",enderId=7798,rewardNextId=2759,poiX=-8417,poiY=628,wowhead="https://www.wowhead.com/wotlk/quest=2758",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When I was about your age, a dwarf by the name of Galvan took me under his wing and trained me in the ways of the armorsmith. Before he left for Booty Bay, he made me promise to train all those with the desire and determination to advance in the craft of blacksmithing -- so here I am -- all these years later.$B$BSo, now it's time for you to learn a little something. Make me six golden scale bracers and you will learn where smithing comes from, $N.",logDesc="Bring six Golden Scale Bracers to Hank the Hammer in Stormwind.",rewards={{id=9367,qty=1}}} end
if not DB[2759] then DB[2759]={id=2759,zoneId=-121,name="In Search of Galvan",level=40,minLevel=40,giver="Hank the Hammer",giverType="NPC",giverId=7798,ender="McGavan",enderType="NPC",enderId=7794,rewardNextId=2760,poiX=-8417,poiY=628,wowhead="https://www.wowhead.com/wotlk/quest=2759",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Although Galvan left Booty Bay many years ago, members of the order still remain in town, hoping to one day find another worthy of Galvan's tutelage.$B$BTake this insignia and present it to McGavan in Booty Bay.$B$BIf you actually make it that far, he'll know that you are worthy. I have faith, $N!",logDesc="Speak with McGavan in Booty Bay."} end
if not DB[2760] then DB[2760]={id=2760,zoneId=-121,name="The Mithril Order",level=40,minLevel=40,giver="McGavan",giverType="NPC",giverId=7794,ender="Galvan the Ancient",enderType="NPC",enderId=7802,poiX=-14377,poiY=378,wowhead="https://www.wowhead.com/wotlk/quest=2760",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Most of our recruits never make it to Booty Bay, $N. The shine of the insignia is enough to trigger the loot lust in even the staunchest of blacksmiths. Fools they be, as the insignia is a drop in the bucket compared to the wealth of items you'll see!$B$BFind Galvan the Ancient and show him this pin. His residence is far to the north, between Zul Gurub and the Mosh'Ogg ogre mound.$B",logDesc="Speak with Galvan the Ancient in Stranglethorn Vale.$B"} end
if not DB[2761] then DB[2761]={id=2761,zoneId=-121,name="Smelt On, Smelt Off",level=45,minLevel=40,giver="Galvan the Ancient",giverType="NPC",giverId=7802,ender="Galvan the Ancient",enderType="NPC",enderId=7802,poiX=-12033,poiY=-1004,wowhead="https://www.wowhead.com/wotlk/quest=2761",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Many blacksmiths believe that mining and smithing are separate, independent jobs; but can there be blacksmithing without mining? Ah ha -- it is an impossibility! The accomplished blacksmith must also be an accomplished miner.$B$BShow Galvan that you are capable, $N. Bring me forty bars of iron and forty bars of mithril. For this, Galvan will teach you the ways of the ornate mithril pants!",logDesc="Bring forty Mithril Bars and forty Iron Bars to Galvan the Ancient in Stranglethorn.",rewards={{id=7983,qty=1}}} end
if not DB[2762] then DB[2762]={id=2762,zoneId=-121,name="The Great Silver Deceiver",level=45,minLevel=40,giver="Galvan the Ancient",giverType="NPC",giverId=7802,ender="Galvan the Ancient",enderType="NPC",enderId=7802,poiX=-12033,poiY=-1004,wowhead="https://www.wowhead.com/wotlk/quest=2762",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is said that truesilver is stronger and more durable than mithril. Galvan does not disagree with this assessment of the minerals, but contrary to its name, truesilver is not true! Mithril is a far nobler mineral! HAH! Regardless, for this lesson you will need to find the great silver deceiver, $N.$B$BBring me forty bars of mithril and five bars of truesilver. In exchange, you will be taught the secret of ornate mithril gloves and more importantly, learn that truesilver is a liar!",logDesc="Bring forty Mithril Bars and five Truesilver Bars to Galvan the Ancient in Stranglethorn.",rewards={{id=7984,qty=1}}} end
if not DB[2763] then DB[2763]={id=2763,zoneId=-121,name="The Art of the Imbue",level=45,minLevel=40,giver="Galvan the Ancient",giverType="NPC",giverId=7802,ender="Galvan the Ancient",enderType="NPC",enderId=7802,poiX=-12033,poiY=-1004,wowhead="https://www.wowhead.com/wotlk/quest=2763",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The harvesting of precious gems is of utmost importance to our craft, $N. Few gems are more precious than the citrine. The magical properties we imbue into our goods are amplified greatly by the presence of citrine.$B$BFor this lesson, we will fortify forty bars of mithril with four citrines. The result will be a better understanding of magical gemology and the knowledge to create ornate mithril shoulders.",logDesc="Bring forty Mithril Bars and four Citrines to Galvan the Ancient in Stranglethorn.",rewards={{id=7985,qty=1}}} end
if not DB[2764] then DB[2764]={id=2764,zoneId=-121,name="Galvan's Finest Pupil",level=45,minLevel=40,giver="Galvan the Ancient",giverType="NPC",giverId=7802,ender="Trenton Lighthammer",enderType="NPC",enderId=7804,poiX=-12033,poiY=-1004,wowhead="https://www.wowhead.com/wotlk/quest=2764",image="assets/images/quests/placeholder.png",xpDiff=4,desc="If you are ready to conclude your training with Galvan, you should journey to Gadgetzan.$B$BThere, you will find my finest pupil: Trenton Lighthammer. He has much to teach you in the ways of ornate mithril. Otherwise, remain here and learn!$B$BOh, Gadgetzan is in Tanaris, of course!",logDesc="Speak with Trenton Lighthammer at Gadgetzan in Tanaris."} end
if not DB[2765] then DB[2765]={id=2765,zoneId=-121,name="Expert Blacksmith!",level=45,minLevel=40,giver="Galvan the Ancient",giverType="NPC",giverId=7802,ender="Galvan the Ancient",enderType="NPC",enderId=7802,poiX=-12033,poiY=-1004,wowhead="https://www.wowhead.com/wotlk/quest=2765",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When you first came to me, I knew that you would turn out to be one of my finest pupils! It was without hesitancy that you gave up a trinket of some power to McGavan. You did this only so that you could meet me. Such blind faith and devotion to the craft should be rewarded.$B$BYou have attained expertise over blacksmithing, $N. Reap the rewards!",logDesc="Claim your reward from Galvan the Ancient!",rewards={{id=8703,qty=1}}} end
if not DB[2766] then DB[2766]={id=2766,zoneId=357,name="Find OOX-22/FE!",level=45,minLevel=40,ender="Homing Robot OOX-22/FE",enderType="NPC",enderId=7807,rewardNextId=2767,wowhead="https://www.wowhead.com/wotlk/quest=2766",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.$B$B\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"$B$B\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"",logDesc="Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale."} end
if not DB[2767] then DB[2767]={id=2767,zoneId=357,name="Rescue OOX-22/FE!",level=45,minLevel=40,giver="Homing Robot OOX-22/FE",giverType="NPC",giverId=7807,ender="Oglethorpe Obnoticus",enderType="NPC",enderId=7406,poiX=-4947,poiY=1734,wowhead="https://www.wowhead.com/wotlk/quest=2767",image="assets/images/quests/placeholder.png",xpDiff=8,desc="The gnome's voice crackles once again from the robot:$B$B\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the main road!  That should be a perfect place, and long enough, to get things online!\"$B$B\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"",logDesc="Escort OOX-22/FE to safety, then report to Oglethorpe Obnoticus in Booty Bay.",choiceRewards={{id=9647,qty=1},{id=9648,qty=1}}} end
if not DB[2768] then DB[2768]={id=2768,zoneId=978,name="Divino-matic Rod",level=47,minLevel=40,giver="Chief Engineer Bilgewhizzle",giverType="NPC",giverId=7407,ender="Chief Engineer Bilgewhizzle",enderType="NPC",enderId=7407,poiX=-7187,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=2768",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Sergeant Bly stole from me!  He said he'd only borrow it, but he stole my cherished divino-matic rod!!  Without that rod how will I know where to dig new water holes??$B$BFind Bly and bring me my rod!  I heard he led his band of ill-reputed adventurers to go treasure hunting in Zul'Farrak to the west.  I bet you'll find him there.$B$BLet's hope the trolls took care of him, because if you have to fight him for the rod then you're in for a serious fight.",logDesc="Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.",choiceRewards={{id=9533,qty=1},{id=9534,qty=1}}} end
if not DB[2769] then DB[2769]={id=2769,zoneId=400,name="The Brassbolts Brothers",level=46,minLevel=40,giver="Klockmort Spannerspan",giverType="NPC",giverId=6169,ender="Wizzle Brassbolts",enderType="NPC",enderId=4453,rewardNextId=2770,poiX=-4812,poiY=-1251,wowhead="https://www.wowhead.com/wotlk/quest=2769",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Have you met the Brassbolts brothers?  They're over in the Shimmering Flats, in Kalimdor, racing their rocket car against the goblins.  They usually win which is no surprise--the goblin car blows up so much it barely ever crosses the finish line!$B$BBut even then, the Brassbolts brothers are always looking for new ways to make their car go faster, and Wizzle told me he needs a very rare component for his next experiment.$B$BHe probably needs help getting that part.  Speak to him and find out.",logDesc="Speak with Wizzle Brassbolts in the Shimmering Flats."} end
if not DB[2770] then DB[2770]={id=2770,zoneId=978,name="Gahz'rilla",level=50,minLevel=40,giver="Wizzle Brassbolts",giverType="NPC",giverId=4453,ender="Wizzle Brassbolts",enderType="NPC",enderId=4453,poiX=-6229,poiY=-3872,wowhead="https://www.wowhead.com/wotlk/quest=2770",image="assets/images/quests/placeholder.png",xpDiff=7,money=7500,desc="Deep in Zul'Farrak, the sand troll city in Tanaris, there is a sacred pool.  From that pool the trolls summon a huge beast!  Gahz'rilla!  He's so fierce that even his scales crackle with energy.  It's that energy I want to harness for my car!$B$BBring me the electrified scale of Gahz'rilla!$B$BBut the summoning of Gahz'rilla is a well-kept secret of the trolls.  To face him, you must first wrest the secret from them.",logDesc="Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.",rewards={{id=11122,qty=1}}} end
if not DB[2771] then DB[2771]={id=2771,zoneId=-121,name="A Good Head On Your Shoulders",level=45,minLevel=40,giver="Trenton Lighthammer",giverType="NPC",giverId=7804,ender="Trenton Lighthammer",enderType="NPC",enderId=7804,poiX=-7198,poiY=-3766,wowhead="https://www.wowhead.com/wotlk/quest=2771",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It seems as if master had this planned from the start. I was not taught to create the items which you learned to create and you were not taught the items which I learned to create.$B$BThe master is wise, $N. We shall teach each other!$B$BShow me how to make a mithril coif and ornate mithril shoulders and I shall show you how to create an ornate mithril helm.",logDesc="Bring two Mithril Coifs and one Ornate Mithril Shoulder to Trenton Lighthammer."} end
if not DB[2772] then DB[2772]={id=2772,zoneId=-121,name="The World At Your Feet",level=45,minLevel=40,giver="Trenton Lighthammer",giverType="NPC",giverId=7804,ender="Trenton Lighthammer",enderType="NPC",enderId=7804,poiX=-7198,poiY=-3766,wowhead="https://www.wowhead.com/wotlk/quest=2772",image="assets/images/quests/placeholder.png",xpDiff=5,desc="At last year's All-Valley Blacksmithing Championship, all those who watched saw my leg get swept from under me by a cowardly dog from the Venture Co. Foundry. What they didn't know, however, was the reason I was able to continue and ultimately win the tournament: That's right, ornate mithril boots!$B$BI will need to learn how to craft ornate mithril pants for this year's tournament, however, as a Venture Co. shredder is an entrant! Teach me the way of the pants and learn the way of the boot!",logDesc="Bring two Heavy Mithril Boots and one Ornate Mithril Pants to Trenton Lighthammer.$B"} end
if not DB[2773] then DB[2773]={id=2773,zoneId=-121,name="The Mithril Kid",level=45,minLevel=40,giver="Trenton Lighthammer",giverType="NPC",giverId=7804,ender="Trenton Lighthammer",enderType="NPC",enderId=7804,poiX=-7198,poiY=-3766,wowhead="https://www.wowhead.com/wotlk/quest=2773",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Around these parts I am known as the Mithril Kid. I supply ornate mithril to adventurers from around the world.$B$B<Trenton whispers.>$B$BLittle do they know that I do not know the technique to fashion ornate mithril gloves. Shhhh! This will be our little secret.$B$BTeach me the technique to create ornate mithril gloves, $N, and in exchange, I will show you the resultant of the culmination of my training under Galvan: the ornate mithril breastplate.",logDesc="Bring two Heavy Mithril Breastplates and one Ornate Mithril Gloves to Trenton Lighthammer."} end
if not DB[2781] then DB[2781]={id=2781,zoneId=440,name="WANTED: Caliph Scorpidsting",level=46,minLevel=38,ender="Chief Engineer Bilgewhizzle",enderType="NPC",enderId=7407,wowhead="https://www.wowhead.com/wotlk/quest=2781",image="assets/images/quests/placeholder.png",xpDiff=6,money=13000,desc="WANTED: Caliph Scorpidsting!$B$BThe Gadgetzan Water Company of Gadgetzan, Tanaris will pay a high bounty for the head of Caliph Scorpidsting, leader of the Wastewander outlaws.  His crimes include:$B$B1.  Murdering Gadgetzan Water Co. employees!$B2.Stealing Gadgetzan Water Co. resources!$B3.Seizing Gadgetzan Water Co. property!$B$BBring proof of Caliph Scorpidsting's demise to Chief Engineer Bilgewhizzle for an immediate reward!",logDesc="Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan."} end
if not DB[2782] then DB[2782]={id=2782,zoneId=47,name="Rin'ji's Secret",level=47,minLevel=42,ender="Oran Snakewrithe",enderType="NPC",enderId=7825,wowhead="https://www.wowhead.com/wotlk/quest=2782",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The tablet is covered with Witherbark troll markings. Rin'ji's secret truly is a mystery... $B$BIt's possible that you might have something quite valuable on your hands here. On the other hand, quite the opposite is also possible. A Witherbark troll in distress would probably do anything to find his way out of trouble...",logDesc="Oran Snakewrithe, a well known scholar on matters concerning the Witherbark trolls, may be able to decipher the tablet. She is known to reside within the Magic Quarter of the Undercity."} end
if not DB[2783] then DB[2783]={id=2783,zoneId=4,name="Petty Squabbles",level=57,minLevel=50,giver="Ambassador Ardalan",giverType="NPC",giverId=7826,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,rewardNextId=2801,poiX=-10997,poiY=-3505,wowhead="https://www.wowhead.com/wotlk/quest=2783",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We fight the wrong enemy, $N.$B$BThe true power in these lands continues to grow in strength and number while we squabble over scorched earth with orcs.$B$BDo we continue to fight a war in these lands against the Horde, only to be routed one day by the armies of the Burning Legion? It is futile.$B$BPut your differences aside, $N, speak with the fallen hero of the Horde. He knows the truth behind the Blasted Lands.",logDesc="Speak with the Fallen Hero of the Horde at the border of the Blasted Lands and the swamp."} end
if not DB[2784] then DB[2784]={id=2784,zoneId=4,name="Fall From Grace",level=50,minLevel=45,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,rewardNextId=2621,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=2784",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hear my story, $r.",logDesc="Listen to the Fallen Hero of the Horde tell his story."} end
if not DB[2801] then DB[2801]={id=2801,zoneId=4,name="A Tale of Sorrow",level=57,minLevel=45,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,rewardNextId=2681,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=2801",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Before we may continue, you must hear my story.",logDesc="Listen to the Fallen Hero of the Horde tell his story."} end
if not DB[2821] then DB[2821]={id=2821,zoneId=357,name="The Mark of Quality",level=46,minLevel=40,giver="Pratt McGrubben",giverType="NPC",giverId=7852,ender="Pratt McGrubben",enderType="NPC",enderId=7852,poiX=-4345,poiY=3313,wowhead="https://www.wowhead.com/wotlk/quest=2821",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My philosophy on leatherworking is that the work must be the best quality possible - no compromises.  Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!$B$BIn my latest pursuit of high-quality materials, I have run across thick yeti hides.  The Yeti are native to Feralas, with many found in Feral Scar Vale.  I want some, and I'll give you a choice of one of my leather goods for a stack of ten.  If that sounds fair to you, then we're in business.",logDesc="Bring 10 Thick Yeti Hides to Pratt McGrubben in Feathermoon Stronghold.",choiceRewards={{id=9630,qty=1},{id=9631,qty=1}}} end
if not DB[2822] then DB[2822]={id=2822,zoneId=357,name="The Mark of Quality",level=46,minLevel=40,giver="Jangdor Swiftstrider",giverType="NPC",giverId=7854,ender="Jangdor Swiftstrider",enderType="NPC",enderId=7854,poiX=-4355,poiY=269,wowhead="https://www.wowhead.com/wotlk/quest=2822",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!$B$BIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found west of here in Feral Scar Vale.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!",logDesc="Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache.",choiceRewards={{id=9633,qty=1},{id=9632,qty=1}}} end
if not DB[2841] then DB[2841]={id=2841,zoneId=133,name="Rig Wars",level=35,minLevel=25,giver="Nogg",giverType="NPC",giverId=3412,ender="Nogg",enderType="NPC",enderId=3412,poiX=2036,poiY=-4746,wowhead="https://www.wowhead.com/wotlk/quest=2841",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined. I need the blueprints, $N!$B$BUnfortunately, the plans are locked away in a safe near Mekgineer Thermaplugg. To make matters worse, the combination to the safe is only known by Mekgineer Thermaplugg.$B$BDo whatever you have to do to get that combination, $N. Then crack open that safe and bring back those blueprints!$B",logDesc="Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.$B",choiceRewards={{id=9623,qty=1},{id=9624,qty=1},{id=9625,qty=1}}} end
if not DB[2842] then DB[2842]={id=2842,zoneId=133,name="Chief Engineer Scooty",level=35,minLevel=20,giver="Sovik",giverType="NPC",giverId=3413,ender="Scooty",enderType="NPC",enderId=7853,rewardNextId=2843,poiX=2037,poiY=-4739,wowhead="https://www.wowhead.com/wotlk/quest=2842",image="assets/images/quests/placeholder.png",xpDiff=1,desc="As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.$B$BIt's finally ready for passengers to board, $N. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.$B$BOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!",logDesc="Speak with Scooty in Booty Bay."} end
if not DB[2843] then DB[2843]={id=2843,zoneId=133,name="Gnomer-gooooone!",level=35,minLevel=20,giver="Scooty",giverType="NPC",giverId=7853,ender="Scooty",enderType="NPC",enderId=7853,poiX=-14465,poiY=460,wowhead="https://www.wowhead.com/wotlk/quest=2843",image="assets/images/quests/placeholder.png",desc="As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.$B$BYou may experience some unusual side effects, but none of those should be permanent... anymore.$B$BI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!$B$BNow to calibrate the transponder to your size and weight.$B",logDesc="Wait for Scooty to calibrate the Goblin Transponder.",rewards={{id=9173,qty=1}}} end
if not DB[2844] then DB[2844]={id=2844,zoneId=357,name="The Giant Guardian",level=49,minLevel=44,giver="Rockbiter",giverType="NPC",giverId=7765,ender="Shay Leafrunner",enderType="NPC",enderId=7774,rewardNextId=2845,poiX=-3386,poiY=2496,wowhead="https://www.wowhead.com/wotlk/quest=2844",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I am no good, $N. I was 'spose to be watchin' over my little friend, Shay, and somehow, she got away from me. I'm not all that sure what happened, really, but last time I saw her, we was walkin' through the ruins just north of here.$B$BEverythin' was goin' fine, but then I turned around, and... she was gone.$B$BNow I jus can't quite figure out what I should do here. Got any ideas, $N? I'm awful worried.$B$BHey, how 'bout you go look fer Shay? Yer legs can travel much faster 'n mine.",logDesc="Locate the lost night elf girl."} end
if not DB[2845] then DB[2845]={id=2845,zoneId=357,name="Wandering Shay",level=49,minLevel=44,giver="Shay Leafrunner",giverType="NPC",giverId=7774,ender="Rockbiter",enderType="NPC",enderId=7765,poiX=-2844,poiY=2785,wowhead="https://www.wowhead.com/wotlk/quest=2845",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then. There are just so many things to see, and I get so distracted.$B$BThere is one thing that will always work to get my attention, though.$B$BInside this chest, you'll find a bell that is very precious to me. I just love the sound of it. You have my word, if I wander off, all you have to do is ring it and I'll come running back.",logDesc="Pick up Shay's Bell from the chest.$B$BEscort Shay Leafrunner to Rockbiter's camp.",choiceRewards={{id=9656,qty=1},{id=9657,qty=1}}} end
if not DB[2846] then DB[2846]={id=2846,zoneId=978,name="Tiara of the Deep",level=46,minLevel=40,giver="Tabetha",giverType="NPC",giverId=6546,ender="Tabetha",enderType="NPC",enderId=6546,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=2846",image="assets/images/quests/placeholder.png",xpDiff=7,money=6500,desc="Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep.  And not only was it pretty--it held great power for those with the knowledge to use it.$B$BSo when word of the tiara reached the Hydromancer Velratha, she had to have it.  She sent agents to my home and they stole it while I was away.  The thieves!$B$BI want my tiara back!  Go to Zul'Farrak, the troll city in Tanaris, find Velratha and wrench the tiara from her.  Return it to me and you'll earn my favor.",logDesc="Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.",rewards={{id=9527,qty=1},{id=9531,qty=1}}} end
if not DB[2847] then DB[2847]={id=2847,zoneId=-182,name="Wild Leather Armor",level=45,minLevel=30,giver="Pratt McGrubben",giverType="NPC",giverId=7852,ender="Pratt McGrubben",enderType="NPC",enderId=7852,poiX=-4345,poiY=3313,wowhead="https://www.wowhead.com/wotlk/quest=2847",image="assets/images/quests/placeholder.png",xpDiff=3,desc="$n, you're becoming quite skilled as a leatherworker!  I know some patterns you might be interested in... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  The armor made using it is second to none for people of your skill, guaranteed.$B$BI'll teach this to you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.",logDesc="Bring 10 Thick Leather to Pratt McGrubben in Feathermoon Stronghold."} end
if not DB[2848] then DB[2848]={id=2848,zoneId=-182,name="Wild Leather Shoulders",level=45,minLevel=30,giver="Pratt McGrubben",giverType="NPC",giverId=7852,ender="Pratt McGrubben",enderType="NPC",enderId=7852,poiX=-4345,poiY=3313,wowhead="https://www.wowhead.com/wotlk/quest=2848",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Wild Leather shoulders support the wearer's frame extremely well, offering top notch protection of the upper arms and the shoulders themselves.  As with all Wild Leather armor, a potent but random benefit is applied to the item as the wildvine is stitched in.$B$BFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.",logDesc="Bring 6 Thick Armor Kits and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",rewards={{id=8403,qty=1}}} end
if not DB[2849] then DB[2849]={id=2849,zoneId=-182,name="Wild Leather Vest",level=45,minLevel=30,giver="Pratt McGrubben",giverType="NPC",giverId=7852,ender="Pratt McGrubben",enderType="NPC",enderId=7852,poiX=-4345,poiY=3313,wowhead="https://www.wowhead.com/wotlk/quest=2849",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest blends with the wildvine to produce a product that offers maximum protection of the torso while allowing for the potent magic to work its way through the garment.$B$BFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  It's a tall order, but one you should have little difficulty in filling for me.",logDesc="Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",rewards={{id=8404,qty=1}}} end
if not DB[2850] then DB[2850]={id=2850,zoneId=-182,name="Wild Leather Helmet",level=45,minLevel=30,giver="Pratt McGrubben",giverType="NPC",giverId=7852,ender="Pratt McGrubben",enderType="NPC",enderId=7852,poiX=-4345,poiY=3313,wowhead="https://www.wowhead.com/wotlk/quest=2850",image="assets/images/quests/placeholder.png",xpDiff=4,desc="A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random enhancement to the frame of the helm.  Leather wearers will definitely want this piece!$B$BFor this pattern, I will need two Nightscape tunics, two Nightscape headbands, and a wildvine.  Complete this order and the pattern will be yours!",logDesc="Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",rewards={{id=8405,qty=1}}} end
if not DB[2851] then DB[2851]={id=2851,zoneId=-182,name="Wild Leather Boots",level=45,minLevel=30,giver="Pratt McGrubben",giverType="NPC",giverId=7852,ender="Pratt McGrubben",enderType="NPC",enderId=7852,poiX=-4345,poiY=3313,wowhead="https://www.wowhead.com/wotlk/quest=2851",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You've learned quite a bit now, $n; still, there is more for you to learn.  Next are Wild Leather boots, the cornerstone of any set.$B$BThese boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.$B$BFor this pattern, I need an order of two Nightscape pants and two Nightscape boots filled.  I also will require two wildvines... not just one.  When you have all this, let me know.",logDesc="Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.",rewards={{id=8406,qty=1}}} end
if not DB[2852] then DB[2852]={id=2852,zoneId=-182,name="Wild Leather Leggings",level=45,minLevel=30,giver="Pratt McGrubben",giverType="NPC",giverId=7852,ender="Pratt McGrubben",enderType="NPC",enderId=7852,poiX=-4345,poiY=3313,wowhead="https://www.wowhead.com/wotlk/quest=2852",image="assets/images/quests/placeholder.png",xpDiff=4,desc="With the basics down, you are ready to master more complex fare, $n.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.$B$BFor this pattern, I need an order of two Turtle Scale helms, two Turtle Scale bracers, and two wildvines filled.",logDesc="Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.",rewards={{id=8407,qty=1}}} end
if not DB[2853] then DB[2853]={id=2853,zoneId=-182,name="Master of the Wild Leather",level=45,minLevel=30,giver="Pratt McGrubben",giverType="NPC",giverId=7852,ender="Telonis",enderType="NPC",enderId=4212,poiX=-4345,poiY=3313,wowhead="https://www.wowhead.com/wotlk/quest=2853",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Well $n, you are the definition of diligence.  There is one pattern left for Wild Leather armor; you've mastered the others.  I won't require you to toil needlessly for the pattern.  You've earned it outright, and then some... but I cannot give it to you myself.  My teacher, the one who brought me into the craft, is the one who must reward you.$B$BTake this letter to Telonis; he teaches leatherworking in Darnassus.  Show him the letter, and let him acknowledge you as an equal, as I do.",logDesc="Give Pratt's Letter to Telonis, the master leatherworker of Darnassus.",rewards={{id=8408,qty=1}}} end
if not DB[2854] then DB[2854]={id=2854,zoneId=-182,name="Wild Leather Armor",level=45,minLevel=30,giver="Jangdor Swiftstrider",giverType="NPC",giverId=7854,ender="Jangdor Swiftstrider",enderType="NPC",enderId=7854,poiX=-4355,poiY=269,wowhead="https://www.wowhead.com/wotlk/quest=2854",image="assets/images/quests/placeholder.png",xpDiff=3,desc="$n, your skill as a leatherworker precedes you.  I possess leatherworking lore you would be wise to acquire... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  Armor made using it is second to none for a crafter of your skill, guaranteed.$B$BI'll teach you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.",logDesc="Bring 10 Thick Leather to Jangdor Swiftstrider in Camp Mojache."} end
if not DB[2855] then DB[2855]={id=2855,zoneId=-182,name="Wild Leather Shoulders",level=45,minLevel=30,giver="Jangdor Swiftstrider",giverType="NPC",giverId=7854,ender="Jangdor Swiftstrider",enderType="NPC",enderId=7854,poiX=-4355,poiY=269,wowhead="https://www.wowhead.com/wotlk/quest=2855",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Wild Leather shoulders support a wearer's frame extremely well, offering superior protection of the upper arms as well as the shoulders.  As with all Wild Leather armor, a random yet very potent enhancement is imbued within the item as the wildvine is stitched in.$B$BFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.",logDesc="Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",rewards={{id=8403,qty=1}}} end
if not DB[2856] then DB[2856]={id=2856,zoneId=-182,name="Wild Leather Vest",level=45,minLevel=30,giver="Jangdor Swiftstrider",giverType="NPC",giverId=7854,ender="Jangdor Swiftstrider",enderType="NPC",enderId=7854,poiX=-4355,poiY=269,wowhead="https://www.wowhead.com/wotlk/quest=2856",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest and the wildvine weave within it produces a product that offers maximum protection of the torso while allowing for potent magic to work its way through the garment.$B$BFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  This is not an easy lesson, but it is one you certainly have the skill to complete.",logDesc="Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",rewards={{id=8404,qty=1}}} end
if not DB[2857] then DB[2857]={id=2857,zoneId=-182,name="Wild Leather Helmet",level=45,minLevel=30,giver="Jangdor Swiftstrider",giverType="NPC",giverId=7854,ender="Jangdor Swiftstrider",enderType="NPC",enderId=7854,poiX=-4355,poiY=269,wowhead="https://www.wowhead.com/wotlk/quest=2857",image="assets/images/quests/placeholder.png",xpDiff=4,desc="A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random magic imbuement to the helm's frame.  Leather wearers will definitely want this piece!$B$BFor this pattern, I will need two Nightscape tunics, 2 Nightscape headbands, and a wildvine.  Complete this lesson and the pattern will be yours!",logDesc="Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",rewards={{id=8405,qty=1}}} end
if not DB[2858] then DB[2858]={id=2858,zoneId=-182,name="Wild Leather Boots",level=45,minLevel=30,giver="Jangdor Swiftstrider",giverType="NPC",giverId=7854,ender="Jangdor Swiftstrider",enderType="NPC",enderId=7854,poiX=-4355,poiY=269,wowhead="https://www.wowhead.com/wotlk/quest=2858",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Your knowledge of Wild Leather armor grows, $n; still, there is more for you to learn.$B$BWild Leather boots are the cornerstone of any set.  Such boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.$B$BFor this pattern, I need two Nightscape pants and two Nightscape boots crafted.  I also will require two wildvines... not just one.  When you have these items, we will proceed.",logDesc="Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.",rewards={{id=8406,qty=1}}} end
if not DB[2859] then DB[2859]={id=2859,zoneId=-182,name="Wild Leather Leggings",level=45,minLevel=30,giver="Jangdor Swiftstrider",giverType="NPC",giverId=7854,ender="Jangdor Swiftstrider",enderType="NPC",enderId=7854,poiX=-4355,poiY=269,wowhead="https://www.wowhead.com/wotlk/quest=2859",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You are ready to master more complex lessons, $n.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.$B$BFor you to gain this pattern, I need two Turtle Scale helms, two Turtle Scale bracers, and two wildvines.",logDesc="Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.",rewards={{id=8407,qty=1}}} end
if not DB[2860] then DB[2860]={id=2860,zoneId=-182,name="Master of the Wild Leather",level=45,minLevel=30,giver="Jangdor Swiftstrider",giverType="NPC",giverId=7854,ender="Una",enderType="NPC",enderId=3007,poiX=-4355,poiY=269,wowhead="https://www.wowhead.com/wotlk/quest=2860",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$n, you have learned all I am able to teach you.  There is, however, one remaining pattern for Wild Leather armor.  I will not require you to toil needlessly for this; you've earned it outright, and then some.  This pattern, however, is one that I cannot freely share with you.$B$BMy teacher, the one who brought me into the craft, is the one who must reward you.  Take this note to Una; she teaches leatherworking in Thunder Bluff.  Show her the letter, and let her acknowledge you as an equal, as I do.",logDesc="Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff.",rewards={{id=8408,qty=1}}} end
if not DB[2861] then DB[2861]={id=2861,zoneId=978,name="Tabetha's Task",level=46,minLevel=40,giver="Ursyn Ghull",giverType="NPC",giverId=3048,ender="Tabetha",enderType="NPC",enderId=6546,rewardNextId=2846,poiX=-949,poiY=248,wowhead="https://www.wowhead.com/wotlk/quest=2861",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Rumor is that Tabetha, a mage colleague who lives deep in Dustwallow Marsh, has a bone to pick with a certain sand troll in Zul'Farrak.  If you speak with Tabetha she can tell you more.$B$BAnd bring some friends with you, $N.  If Tabetha has you go to Zul'Farrak then you're not going to want to go alone.$B$BYou will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruin.",logDesc="Speak with Tabetha in Dustwallow Marsh."} end
if not DB[2862] then DB[2862]={id=2862,zoneId=357,name="War on the Woodpaw",level=42,minLevel=39,giver="Hadoken Swiftstrider",giverType="NPC",giverId=7875,ender="Hadoken Swiftstrider",enderType="NPC",enderId=7875,rewardNextId=2863,poiX=-4334,poiY=236,wowhead="https://www.wowhead.com/wotlk/quest=2862",image="assets/images/quests/placeholder.png",xpDiff=4,money=4500,desc="The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.$B$BThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.$B$BGo!",logDesc="Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache."} end
if not DB[2863] then DB[2863]={id=2863,zoneId=357,name="Alpha Strike",level=43,minLevel=39,giver="Hadoken Swiftstrider",giverType="NPC",giverId=7875,ender="Hadoken Swiftstrider",enderType="NPC",enderId=7875,rewardNextId=2902,poiX=-4334,poiY=236,wowhead="https://www.wowhead.com/wotlk/quest=2863",image="assets/images/quests/placeholder.png",xpDiff=4,money=4500,desc="The plan is for various leaders of the gnolls - Alphas as they call themselves - to be taken down within rapid succession.  If we're able to execute this sort of swift and precise devastation against them, it would cause chaos in their ranks.  Perhaps it would also drive a message through their thick flea-bitten heads that we can and will destroy them!$B$BI want you to be the messenger of my will; eliminate five of their Alphas within one hour for this to work $N, or we'll remain at this impasse!",logDesc="Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour."} end
if not DB[2864] then DB[2864]={id=2864,zoneId=978,name="Tran'rek",level=45,minLevel=40,giver="Krazek",giverType="NPC",giverId=773,ender="Tran'rek",enderType="NPC",enderId=7876,rewardNextId=2865,poiX=-14453,poiY=501,wowhead="https://www.wowhead.com/wotlk/quest=2864",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My cousin Tran'rek is in a tight spot.  He promised me a load of scarab shells weeks ago and he hasn't delivered.  He's my cousin, so I'd hate to have to send someone to Gadgetzan to break something on him.$B$BCan you speak to Tran'rek for me?  Let him know he needs to get that delivery together before I do something rash?$B$BGadgetzan is in northern Tanaris, in Kalimdor.",logDesc="Speak with Tran'rek in Gadgetzan."} end
if not DB[2865] then DB[2865]={id=2865,zoneId=978,name="Scarab Shells",level=45,minLevel=40,giver="Tran'rek",giverType="NPC",giverId=7876,ender="Tran'rek",enderType="NPC",enderId=7876,poiX=-7106,poiY=-3777,wowhead="https://www.wowhead.com/wotlk/quest=2865",image="assets/images/quests/placeholder.png",xpDiff=7,money=6500,desc="The scarabs of Tanaris have very hard shells!  Hard enough to use as a building material for lots of things.  So many things!$B$BIn fact, those shells are so useful... the scarabs were hunted all to near extinction!$B$BI know where there are more scarabs, and if you promise to bring me their shells then I'll tell you where they are.  Promise?$B$BOk, the scarabs have a colony in Zul'Farrak.  I guess the trolls don't hunt them for their shells.$B$BBut you can!  Go to Zul'Farrak and get me uncracked shells!",logDesc="Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan."} end
if not DB[2866] then DB[2866]={id=2866,zoneId=357,name="The Ruins of Solarsal",level=43,minLevel=40,giver="3",giverType="NPC",giverId=3936,rewardNextId=2867,poiX=-4506,poiY=3337,wowhead="https://www.wowhead.com/wotlk/quest=2866",image="assets/images/quests/placeholder.png",xpDiff=4,desc="To our south are the Ruins of Solarsal; this is an area that far pre-dates modern times.  We explored the ruins initially and found nothing of note; as such, we left it in peace.$B$BVery recently, the Hatecrest naga have occupied these ruins in alarming numbers.  At first, we considered it as the precursor for an attack.  Though that threat is still possible, we believe there might be something else going on.$B$BGo there, explore the ruins, and look for anything that stands out to you. Good luck, $n.",logDesc="Explore the Ruins of Solarsal and investigate the presence of the naga there."} end
if not DB[2867] then DB[2867]={id=2867,zoneId=357,name="Return to Feathermoon Stronghold",level=43,minLevel=40,ender="3",enderType="NPC",enderId=3936,wowhead="https://www.wowhead.com/wotlk/quest=2867",image="assets/images/quests/placeholder.png",xpDiff=3,money=4500,desc="With the discovery of the strange gazebo in the heart of the Ruins of Solarsal, the time has come to return to Feathermoon Stronghold and report to General Shandris Feathermoon what has been discovered here.",logDesc="Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings."} end
if not DB[2868] then DB[2868]={id=2868,zoneId=1417,name="<TXT> The Shriveled Heart",level=50,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=2868",image="assets/images/quests/placeholder.png",desc="Turn this badboy into some troll tomb in the Sunken Temple,and get something cool!"} end
if not DB[2869] then DB[2869]={id=2869,zoneId=357,name="Against the Hatecrest",level=43,minLevel=40,giver="Latronicus Moonspear",giverType="NPC",giverId=7877,ender="Latronicus Moonspear",enderType="NPC",enderId=7877,rewardNextId=2870,poiX=-4506,poiY=3330,wowhead="https://www.wowhead.com/wotlk/quest=2869",image="assets/images/quests/placeholder.png",xpDiff=4,money=4500,desc="The best course of action at this point is to assume that, regardless of what the naga are up to, they will eventually move to secure the island for their own.  We need to take aggressive steps to counter that threat before it is too late.$B$BBring me ten Hatecrest Scales that are in good condition; it should be obvious to you how to acquire them.  You'll cut your teeth on the naga for the first time, and we'll have a weakened naga presence on Sardor Isle - both are prospects that play to our advantage.",logDesc="Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold."} end
if not DB[2870] then DB[2870]={id=2870,zoneId=357,name="Against Lord Shalzaru",level=45,minLevel=40,giver="Latronicus Moonspear",giverType="NPC",giverId=7877,ender="Latronicus Moonspear",enderType="NPC",enderId=7877,rewardNextId=2871,poiX=-4506,poiY=3330,wowhead="https://www.wowhead.com/wotlk/quest=2870",image="assets/images/quests/placeholder.png",xpDiff=4,money=5000,desc="$n, new scouting reports have given us a good idea on the naga chain of command.  Royalty is present amongst their rank and file, and they're the ones calling all the shots.$B$BSpecifically, we've identified one of the crueler royals as Lord Shalzaru.  Scouts report that he himself has uncovered an odd relic during a recent naga excavation in a cave south of the main ruins, across the water on the Isle of Dread.$B$BPut a stop to it by putting a stop to him, and bring me his relic so we can study it.",logDesc="Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold."} end
if not DB[2871] then DB[2871]={id=2871,zoneId=357,name="Delivering the Relic",level=45,minLevel=40,giver="Latronicus Moonspear",giverType="NPC",giverId=7877,ender="Vestia Moonspear",enderType="NPC",enderId=7878,poiX=-4506,poiY=3330,wowhead="https://www.wowhead.com/wotlk/quest=2871",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it.  She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere.  I couldn't make heads or tails of this device even if there was a wager involved.  My wife though, if anyone can figure out what this thing is, she could... and we need to know!$B$BShe's just around the bend, no doubt studying.  Thanks, $n.",logDesc="Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.",choiceRewards={{id=9663,qty=1},{id=9664,qty=1}}} end
if not DB[2872] then DB[2872]={id=2872,zoneId=440,name="Stoley's Debt",level=45,minLevel=40,giver="\"Sea Wolf\" MacKinley",giverType="NPC",giverId=2501,ender="Stoley",enderType="NPC",enderId=7881,rewardNextId=2873,poiX=-14447,poiY=448,wowhead="https://www.wowhead.com/wotlk/quest=2872",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My old buddy Stoley owes me a very special bottle of rum.  He tends the bar at Steamwheedle Port in Tanaris, Kalimdor,  and he promised me that the rum there is stronger than anything we can find in Booty Bay.  He's so confident that he says if I try that rum and don't agree with him, then he'll double the money he owes me!$B$BWell, I think he's not as confident as he was when last we spoke, and now he's afraid to give me that rum.  But I don't back down from wagers, so why don't you talk to him for me...",logDesc="Speak with Stoley in Steamwheedle Port."} end
if not DB[2873] then DB[2873]={id=2873,zoneId=440,name="Stoley's Shipment",level=45,minLevel=40,giver="Stoley",giverType="NPC",giverId=7881,ender="Stoley",enderType="NPC",enderId=7881,rewardNextId=2874,poiX=-6978,poiY=-4849,wowhead="https://www.wowhead.com/wotlk/quest=2873",image="assets/images/quests/placeholder.png",xpDiff=5,money=5000,desc="I owe \"Sea Wolf\" MacKinley in Booty Bay some rum, to settle a bet, but I'm all out of rum!  Captain Cuergo stole my last shipment, and he has it stowed in that walled pirate town to the south.$B$BIf you can find my shipment of rum and return it to me, then I can prove to MacKinley that Kalimdor's booze beats the dirt out of Booty Bay!",logDesc="Bring Stoley's Shipment to Stoley in Steamwheedle Port."} end
if not DB[2874] then DB[2874]={id=2874,zoneId=440,name="Deliver to MacKinley",level=45,minLevel=40,giver="Stoley",giverType="NPC",giverId=7881,ender="\"Sea Wolf\" MacKinley",enderType="NPC",enderId=2501,poiX=-6978,poiY=-4849,wowhead="https://www.wowhead.com/wotlk/quest=2874",image="assets/images/quests/placeholder.png",xpDiff=5,money=5000,desc="Thanks again for your help, $N.  Here's a bottle of Steamwheedle bilge rum.  Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze.",logDesc="Bring Stoley's Bottle to \"Sea Wolf\" MacKinley in Booty Bay.",choiceRewards={{id=9636,qty=1},{id=9637,qty=1}}} end
if not DB[2875] then DB[2875]={id=2875,zoneId=440,name="WANTED: Andre Firebeard",level=45,minLevel=38,ender="Security Chief Bilgewhizzle",enderType="NPC",enderId=7882,wowhead="https://www.wowhead.com/wotlk/quest=2875",image="assets/images/quests/placeholder.png",xpDiff=5,money=13000,desc="The vile pirate Andre Firebeard is wanted for crimes against Steamwheedle and Gadgetzan.$B$BBy decree of governing counsel, any who read this are hereby authorized to use lethal force during the apprehension of Andre and his abettors.$B$BBy further decree, should Andre be deceased, or otherwise indisposed, during the time of his hearing, his head may act as proxy, and deliverance of such head to Security Chief Bilgewhizzle constitutes a binding, and tenderable, contract.",logDesc="Bring Andre's Head to Security Chief Bilgewhizzle in Steamwheedle Port."} end
if not DB[2876] then DB[2876]={id=2876,zoneId=440,name="Ship Schedules",level=45,minLevel=40,ender="Security Chief Bilgewhizzle",enderType="NPC",enderId=7882,wowhead="https://www.wowhead.com/wotlk/quest=2876",image="assets/images/quests/placeholder.png",xpDiff=6,money=13000,desc="This scroll contains the schedules of shipments between Steamwheedle Port and Booty Bay. Both past and future shipments are included, along with ship names, with large 'X's next to some ships' journeys, and annotations like \"GREAT LOOT\" and \"HARD FIGHT\" next to others.$B$BSomeone at Steamwheedle Port would want to see this document.",logDesc="Report the Ship Schedules to an authority in Steamwheedle Port."} end
if not DB[2877] then DB[2877]={id=2877,zoneId=47,name="Skulk Rock Clean-up",level=48,minLevel=40,giver="Fraggar Thundermantle",giverType="NPC",giverId=7884,ender="Fraggar Thundermantle",enderType="NPC",enderId=7884,poiX=323,poiY=-2146,wowhead="https://www.wowhead.com/wotlk/quest=2877",image="assets/images/quests/placeholder.png",xpDiff=5,money=5000,desc="We Wildhammers remember the past, more than our brothers in Ironforge.  If you want to make friends here, then you get your hands dirty for us!$B$BThe Horde abandoned their positions in the Hinterlands around Skulk Rock; it's now overrun with nasty sludges and oozes.  We've got plans on that area, but first we need a clean-up crew to make a hole for us.$B$BThat's where you come in, Sunshine!  Head down there and take out ten green sludges and ten jade oozes, then report back to me here.  Move out!",logDesc="Kill 10 Green Sludges and 10 Jade Oozes, and then report back to Fraggar Thundermantle in Aerie Peak."} end
if not DB[2878] then DB[2878]={id=2878,zoneId=357,name="Corrupted Songflower",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=2878",image="assets/images/quests/placeholder.png"} end
if not DB[2879] then DB[2879]={id=2879,zoneId=357,name="The Stave of Equinex",level=50,minLevel=42,giver="Troyas Moonbreeze",giverType="NPC",giverId=7764,rewardNextId=2942,poiX=-4475,poiY=3233,wowhead="https://www.wowhead.com/wotlk/quest=2879",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This stave might be the Stave of Equinex! The Stave of Equinex is actually a key, used to unlock the Equinex Monolith in the Ruins of Ravenwind, on the mainland west of the Dream Bough.$B$BFind the four flames that still burn in those ruins: Samha, Imbel, Byltan, and Lahassa. Retrieve their essence and then while standing by the Equinex Monolith, use the essences to energize the stave. If this is truly is the Stave of Equinex, you will be able to unlock the Monolith and gather a sacred artifact from it.",logDesc="Energize Troyas' Stave and find the Equinex Monolith.",rewards={{id=9307,qty=1}}} end
if not DB[2880] then DB[2880]={id=2880,zoneId=47,name="Troll Necklace Bounty",level=45,minLevel=40,giver="Fraggar Thundermantle",giverType="NPC",giverId=7884,ender="Fraggar Thundermantle",enderType="NPC",enderId=7884,poiX=323,poiY=-2146,wowhead="https://www.wowhead.com/wotlk/quest=2880",image="assets/images/quests/placeholder.png",xpDiff=5,money=6500,desc="Get this straight, $r - we are NOT part of the Alliance!  The Wildhammers are independent, relying on deeds and actions to prove one's worth, rather than the blather of those who use jibber-jabber to bolster their do-nothing attitudes!$B$BIf you're looking for friends here, then prove your worth to us first!  The foul trolls that choke the hillsides of the Hinterlands sometimes carry tribal necklaces.  Bring five of them to me, and we'll mark it down as a step in the right direction for you.",logDesc="Bring 5 Troll Tribal Necklaces to Fraggar Thundermantle in Aerie Peak."} end
if not DB[2881] then DB[2881]={id=2881,zoneId=47,name="Troll Necklace Bounty",level=45,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=2881",image="assets/images/quests/placeholder.png"} end
if not DB[2882] then DB[2882]={id=2882,zoneId=-221,name="Cuergo's Gold",level=45,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=2882",image="assets/images/quests/placeholder.png",desc="This map shows a stretch of beach with a southern face.  Below the map are words, elegantly written...$B$B$BSouth of Wheedle$BSouth of home$BFind a mast and flag and bones$BDig you there, if you be bold$BDig and claim Cuergo's gold!$BA key you'll need and a key you'll see$BThe men you face take blood as fee.",logDesc="Find Cuergo's gold!",rewards={{id=9265,qty=1}}} end
if not DB[2902] then DB[2902]={id=2902,zoneId=357,name="Woodpaw Investigation",level=43,minLevel=39,giver="Hadoken Swiftstrider",giverType="NPC",giverId=7875,rewardNextId=2903,poiX=-4334,poiY=236,wowhead="https://www.wowhead.com/wotlk/quest=2902",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity.  If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.$B$BI want you to head back to the Woodpaw and find anything that might resemble their battle plans.  They have to have something; their attacks have been too coordinated to be done without them.  Find them, and return to me when you have them.",logDesc="Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache."} end
if not DB[2903] then DB[2903]={id=2903,zoneId=357,name="The Battle Plans",level=43,minLevel=39,ender="Hadoken Swiftstrider",enderType="NPC",enderId=7875,wowhead="https://www.wowhead.com/wotlk/quest=2903",image="assets/images/quests/placeholder.png",xpDiff=5,desc="With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.",logDesc="Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.",choiceRewards={{id=9661,qty=1},{id=9662,qty=1}}} end
if not DB[2904] then DB[2904]={id=2904,zoneId=133,name="A Fine Mess",level=30,minLevel=20,giver="Kernobee",giverType="NPC",giverId=7850,ender="Scooty",enderType="NPC",enderId=7853,poiX=-640,poiY=72,wowhead="https://www.wowhead.com/wotlk/quest=2904",image="assets/images/quests/placeholder.png",xpDiff=7,desc="<Kernobee groans.> Wha.. What happened?$B$BThe last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs.$B$BGet me out of here, $N!$B$BHere's the plan: Lead me to the exit; if we make it out alive, you go to Booty Bay and let Scooty know that I went to Ratchet to warn Tinkerwiz of the dark iron's involvement in the making of that super rig.$B$BLet's get going!",logDesc="Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.",choiceRewards={{id=9535,qty=1},{id=9536,qty=1}}} end
if not DB[2922] then DB[2922]={id=2922,zoneId=133,name="Save Techbot's Brain!",level=26,minLevel=20,giver="Tinkmaster Overspark",giverType="NPC",giverId=7944,ender="Tinkmaster Overspark",enderType="NPC",enderId=7944,poiX=-4835,poiY=-1263,wowhead="https://www.wowhead.com/wotlk/quest=2922",image="assets/images/quests/placeholder.png",xpDiff=6,money=2000,desc="When our beloved city Gnomeregan fell, a rogue spark must have jolted my poor creation, Techbot.  It once aided me and my associates with its countless gizmos and limitless store of information, but its positronic brain has polarized.  Now it's negatronic... and Techbot's behaviors are reversed.  It roams Gnomeregan in a frenzy!$B$BBut perhaps it can be salvaged.  Perhaps, if you can retrieve Techbot's memory core and bring it to me, I can discover the cause of the polarization and fix my poor Techbot.$B$B",logDesc="Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge."} end
if not DB[2923] then DB[2923]={id=2923,zoneId=133,name="Tinkmaster Overspark",level=26,minLevel=20,giver="Brother Sarno",giverType="NPC",giverId=7917,ender="Tinkmaster Overspark",enderType="NPC",enderId=7944,rewardNextId=2922,poiX=-8556,poiY=836,wowhead="https://www.wowhead.com/wotlk/quest=2923",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot.  I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.$B$BVery sad.  But with luck perhaps he can be fixed!$B$BSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge.  He would welcome your help.",logDesc="Speak with Tinkmaster Overspark in Ironforge."} end
if not DB[2924] then DB[2924]={id=2924,zoneId=133,name="Essential Artificials",level=30,minLevel=24,giver="Klockmort Spannerspan",giverType="NPC",giverId=6169,ender="Klockmort Spannerspan",enderType="NPC",enderId=6169,poiX=-4812,poiY=-1251,wowhead="https://www.wowhead.com/wotlk/quest=2924",image="assets/images/quests/placeholder.png",xpDiff=7,money=5500,desc="A nigh-universal mechanical component--the essential artificial--was of great use to the tinkers and smiths of Gnomeregan.  But during the frantic exodus from our city, no one remembered to take any of these devices with them!  And I need a large supply of them for work I will soon undertake.$B$BPlease, go into Gnomeregan and get me some essential artificials.  You'll find them in the deeper areas of our city, held in containers called artificial extrapolators.$B$BThank you, $N, and please hurry!",logDesc="Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge."} end
if not DB[2925] then DB[2925]={id=2925,zoneId=133,name="Klockmort's Essentials",level=30,minLevel=24,giver="Mathiel",giverType="NPC",giverId=6142,ender="Klockmort Spannerspan",enderType="NPC",enderId=6169,rewardNextId=2924,poiX=9918,poiY=2309,wowhead="https://www.wowhead.com/wotlk/quest=2925",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A gnome friend, Klockmort Spannerspan, sent word to me from Ironforge.  He tells me he needs help on a dangerous, but essential, mission into Gnomeregan, the once great gnome city now contaminated and filled with mad gnomes and their devices.$B$BI must stay here, but my heart aches to help my friend.  If you can go in my stead, then I would be much indebted to you.$B$BYou may find Klockmort in Tinkertown, in Ironforge.",logDesc="Speak with Klockmort Spannerspan in Ironforge."} end
if not DB[2926] then DB[2926]={id=2926,zoneId=133,name="Gnogaine",level=27,minLevel=20,giver="Ozzie Togglevolt",giverType="NPC",giverId=1268,ender="Ozzie Togglevolt",enderType="NPC",enderId=1268,poiX=-5498,poiY=-458,wowhead="https://www.wowhead.com/wotlk/quest=2926",image="assets/images/quests/placeholder.png",xpDiff=7,money=2200,desc="Since the accident, all Gnoarn thinks about or talks about is cleansing Gnomeregan of the trogg infestation and finding a cure for the sickness that plagues it, $N.$B$BLuckily, Razzle and I are close to some kind of cure - either that or the recipe for a really powerful rum. We won't know until we test! Naturally, in order to test our theory, we're going to need a few things; namely, fallout from the irradiated troggs in Gnomeregan. Fill up this phial with the green glow and bring it back!",logDesc="Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos."} end
if not DB[2927] then DB[2927]={id=2927,zoneId=133,name="The Day After",level=27,minLevel=20,giver="Gnoarn",giverType="NPC",giverId=6569,ender="Ozzie Togglevolt",enderType="NPC",enderId=1268,poiX=-4836,poiY=-1261,wowhead="https://www.wowhead.com/wotlk/quest=2927",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You don't think I was always bald, do you? No $g sir:ma'am;! It was the radiation leak in Gnomeregan that caused this tragic hair loss. Before that day, I had the only gnomefro in all of Azeroth.$B$B<Gnoarn shakes his fist in the air.>$B$BDamn those damned dirty troggs - damn them all!!$B$BPerhaps it's not too late, $N. We may still be able to save it - the city I mean! Speak to Ozzie Togglevolt in Kharanos. He and his partner Razzle are working on a solution.",logDesc="Speak with Ozzie Togglevolt at Kharanos in Dun Morogh."} end
if not DB[2928] then DB[2928]={id=2928,zoneId=133,name="Gyrodrillmatic Excavationators",level=30,minLevel=20,giver="Shoni the Shilent",giverType="NPC",giverId=6579,ender="Shoni the Shilent",enderType="NPC",enderId=6579,poiX=-8391,poiY=635,wowhead="https://www.wowhead.com/wotlk/quest=2928",image="assets/images/quests/placeholder.png",xpDiff=7,desc="It's terrible, $N. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh.$B$BWhat we need are spare parts, $N. What better place to get the spare parts for our vehicles than Gnomeregan? I hear that bots and mechs roam around that place like cattle on an open range.$B$BWhat I need you to do is go to Gnomeregan and tear apart those robots. Bring me back their robot guts. Two dozen should be sufficient.$B",logDesc="Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.",choiceRewards={{id=9608,qty=1},{id=9609,qty=1}}} end
if not DB[2929] then DB[2929]={id=2929,zoneId=133,name="The Grand Betrayal",level=35,minLevel=25,giver="High Tinker Mekkatorque",giverType="NPC",giverId=7937,ender="High Tinker Mekkatorque",enderType="NPC",enderId=7937,poiX=-4828,poiY=-1257,wowhead="https://www.wowhead.com/wotlk/quest=2929",image="assets/images/quests/placeholder.png",xpDiff=7,money=3500,desc="I trusted Thermaplugg, $r. Never did I expect that he would betray me and the entire gnomish people. And for what? Power? Wealth? All things that he would have had in time. Now we have been displaced from our home and that madman is in charge. The king of nothing....$B$BWe will retake Gnomeregan, $N. We will not stop until the city is back in our control. If you wish to join in our fight, a simple task I ask of you: Kill the betrayer. Destroy Mekgineer Thermaplugg.",logDesc="Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.",choiceRewards={{id=9623,qty=1},{id=9624,qty=1},{id=9625,qty=1}}} end
if not DB[2930] then DB[2930]={id=2930,zoneId=133,name="Data Rescue",level=30,minLevel=25,giver="Master Mechanic Castpipe",giverType="NPC",giverId=7950,ender="Master Mechanic Castpipe",enderType="NPC",enderId=7950,poiX=-4823,poiY=-1266,wowhead="https://www.wowhead.com/wotlk/quest=2930",image="assets/images/quests/placeholder.png",xpDiff=7,money=2500,desc="When we fled Gnomeregan, we left so much data behind!  Vitally important data!$B$BI need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan.  You must access the terminal, but to do that you first need clearance... and to get that you must access lower security terminals-- models -A, -B and -C.  And to do THAT you need security punch cards, starting with white... and we left all the punch cards in the city.$B$BIt's a catastrophe!  Can you help?",logDesc="Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.",rewards={{id=9605,qty=1},{id=9604,qty=1}}} end
if not DB[2931] then DB[2931]={id=2931,zoneId=133,name="Castpipe's Task",level=28,minLevel=25,giver="Gaxim Rustfizzle",giverType="NPC",giverId=4077,ender="Master Mechanic Castpipe",enderType="NPC",enderId=7950,rewardNextId=2930,poiX=730,poiY=340,wowhead="https://www.wowhead.com/wotlk/quest=2931",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Master Mechanic Castpipe in Ironforge has need of adventurers!  He's organizing bands to reenter Gnomeregan on a data retrieval mission of top security and importance.$B$BCastpipe might not be a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences like I am, but he's still a smart gnome so if he thinks it's important, then by my calculations there's an eighty-four percent probability that it really is important!$B$BThose are good odds!",logDesc="Speak with Master Mechanic Castpipe in Ironforge."} end
if not DB[2932] then DB[2932]={id=2932,zoneId=47,name="Grim Message",level=42,minLevel=35,giver="Nimboya",giverType="NPC",giverId=2497,ender="Nimboya",enderType="NPC",enderId=2497,poiX=-12348,poiY=169,wowhead="https://www.wowhead.com/wotlk/quest=2932",image="assets/images/quests/placeholder.png",xpDiff=5,money=5500,desc="The Witherbark trolls were once allies to the Horde, but they betrayed Thrall... and that must be punished!$B$BHere, take my pike and go to the Hinterlands, far to the north.  You will find it northeast of Tarren Mill, a village held by our allies, the Forsaken.$B$BWhen you enter the Hinterlands, hunt Witherbark trolls.  Gather their skulls and drive my pike into the ground at one of their smaller villages, Hiri'watha or Zun'watha.$B$BShow them their vile actions are of consequence!",logDesc="Gather Witherbark Skulls and place on Nimboya's Pike.  Place Nimboya's Laden Pike at one of the Witherbark Villages in the Hinterlands, then return to Nimboya in Stranglethorn."} end
if not DB[2933] then DB[2933]={id=2933,zoneId=47,name="Venom Bottles",level=43,minLevel=40,ender="Apothecary Lydon",enderType="NPC",enderId=2216,rewardNextId=2934,wowhead="https://www.wowhead.com/wotlk/quest=2933",image="assets/images/quests/placeholder.png",xpDiff=5,desc="These bottles hold a vile, green venom.$B$BConsidering the number of bottles in this village, the Witherbarks must deem it very important.  Perhaps an apothecary in nearby Tarren Mill would like a sample.",logDesc="Bring a Venom Bottle to an apothecary in Tarren Mill."} end
if not DB[2934] then DB[2934]={id=2934,zoneId=47,name="Undamaged Venom Sac",level=45,minLevel=40,giver="Apothecary Lydon",giverType="NPC",giverId=2216,ender="Apothecary Lydon",enderType="NPC",enderId=2216,rewardNextId=2935,poiX=-7,poiY=-899,wowhead="https://www.wowhead.com/wotlk/quest=2934",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I must have a fresh sample of the venom you brought me.  The spiders from which it was gathered must dwell in the Hinterlands -- hunt them until you find an undamaged venom sac and bring it to me.  You will find many spiders near the troll city of Shadra'Alor.$B$BDo not tarry, $N, for the venom sac must be fresh when you deliver it.",logDesc="Bring an Undamaged Venom Sac to Apothecary Lydon in Tarren Mill."} end
if not DB[2935] then DB[2935]={id=2935,zoneId=47,name="Consult Master Gadrin",level=45,minLevel=40,giver="Apothecary Lydon",giverType="NPC",giverId=2216,ender="Master Gadrin",enderType="NPC",enderId=3188,rewardNextId=2936,poiX=-7,poiY=-899,wowhead="https://www.wowhead.com/wotlk/quest=2935",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The venom from the broodguards wasn't as potent as the venom you brought originally.  It must have come from a different spider.$B$BI want a fresh sample of that venom.  To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village.  Travel to Durotar and speak with Gadrin.  With luck, he'll know where the Witherbarks get their venom.",logDesc="Speak with Master Gadrin in Sen'jin Village."} end
if not DB[2936] then DB[2936]={id=2936,zoneId=978,name="The Spider God",level=45,minLevel=40,giver="Master Gadrin",giverType="NPC",giverId=3188,ender="Master Gadrin",enderType="NPC",enderId=3188,rewardNextId=2937,poiX=-826,poiY=-4921,wowhead="https://www.wowhead.com/wotlk/quest=2936",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The Witherbarks worship a spider god, and from her they collect their most potent venom.  So if you want the venom, then you must summon their god!$B$BTo do that, you must know her true name, and that name is on a tablet buried in Tanaris, in the troll city of Zul'Farrak, in a tomb guarded by Theka the Martyr.$B$BDefeat Theka and find and read his tablet to discover the spider god's name.  When you know it, return to me.",logDesc="Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin."} end
if not DB[2937] then DB[2937]={id=2937,zoneId=47,name="Summoning Shadra",level=55,minLevel=40,giver="Master Gadrin",giverType="NPC",giverId=3188,ender="Apothecary Lydon",enderType="NPC",enderId=2216,poiX=-826,poiY=-4921,wowhead="https://www.wowhead.com/wotlk/quest=2937",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Take his parchment, and read it at the altar of Shadra'Alor, deep within the witherbark realm in the Hinterlands.  This will summon Shadra the spider god.",logDesc="Defeat Shadra at the altar of Shadra'Alor, then bring her venom to Apothecary Lydon in Tarren Mill."} end
if not DB[2938] then DB[2938]={id=2938,zoneId=47,name="Venom to the Undercity",level=55,minLevel=40,giver="Apothecary Lydon",giverType="NPC",giverId=2216,ender="Master Apothecary Faranell",enderType="NPC",enderId=2055,poiX=-7,poiY=-899,wowhead="https://www.wowhead.com/wotlk/quest=2938",image="assets/images/quests/placeholder.png",xpDiff=7,money=25000,desc="The venom you gathered from the Witherbark's spider god is quite a find!  I've been able to kill nearly two dozen rabbits with just a drop of the stuff.  Granted, some of those rabbits were very young and small enough to fit in the palm of one's hand so I'm certain their resistance to toxins was low, but it can't be denied that this poison is powerful!$B$BI'd like a sample sent to my superior, Apothecary Faranell in the Apothecarium of the Undercity.  I am positive he would want to test this himself.",logDesc="Bring Faranell's Parcel to Master Apothecary Faranell in the Undercity.",choiceRewards={{id=9649,qty=1},{id=9650,qty=1},{id=10686,qty=1}}} end
if not DB[2939] then DB[2939]={id=2939,zoneId=357,name="In Search of Knowledge",level=47,minLevel=42,giver="Troyas Moonbreeze",giverType="NPC",giverId=7764,ender="Daryn Lightwind",enderType="NPC",enderId=7907,poiX=-4475,poiY=3233,wowhead="https://www.wowhead.com/wotlk/quest=2939",image="assets/images/quests/placeholder.png",xpDiff=1,desc="While the ruins of Feralas can be quite dangerous, they have much to tell of what has happened here.$B$BSearching through the rubble to the south a few days ago, I discovered what appears to be a normal stave. However, I just can't shake the feeling that there is something more to it. Angelas and I have been poring over our books here, but we can't find a thing about it.$B$BI have a colleague in Darnassus that may be able to tell us what this is, $N. Why don't you go talk to her and see if she can help us?",logDesc="Talk to Daryn Lightwind in Rut'theran Village."} end
if not DB[2940] then DB[2940]={id=2940,zoneId=357,name="Feralas: A History",level=47,minLevel=42,ender="Daryn Lightwind",enderType="NPC",enderId=7907,rewardNextId=2941,wowhead="https://www.wowhead.com/wotlk/quest=2940",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This book looks as if no one has opened it for quite a long time. Its covers are quite worn, and its pages yellowed, but after examining it, you notice that it might be just what Troyas is looking for.$B$BYou pick it up, but realize you should probably ask before borrowing it.",logDesc="Ask Daryn Lightwind if you may borrow her book."} end
if not DB[2941] then DB[2941]={id=2941,zoneId=357,name="The Borrower",level=48,minLevel=42,giver="Daryn Lightwind",giverType="NPC",giverId=7907,ender="Curgle Cranklehop",enderType="NPC",enderId=7763,rewardNextId=2944,poiX=8701,poiY=993,wowhead="https://www.wowhead.com/wotlk/quest=2941",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I have studied many subjects in my time, and my latest fascination is with the snapjaw that occupy the beach in the Hinterlands. There's one in particular I'd like to see, a giant snapjaw named Gammerita. I'd like to go myself, but my research keeps me here. I think a picture of her would be the next best thing.$B$BTake this letter to Curgle Cranklehop in Tanaris. She has created an invention for me that can capture a picture. She called it a \"snapshot,\" I think...",logDesc="Take the letter to Curgle Cranklehop in Tanaris."} end
if not DB[2942] then DB[2942]={id=2942,zoneId=357,name="The Morrow Stone",level=50,minLevel=42,ender="Troyas Moonbreeze",enderType="NPC",enderId=7764,wowhead="https://www.wowhead.com/wotlk/quest=2942",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade.",logDesc="Return the Sparkling Stone and the Stave of Equinex to Troyas Moonbreeze in Feathermoon Stronghold. ",choiceRewards={{id=9654,qty=1},{id=9655,qty=1}}} end
if not DB[2943] then DB[2943]={id=2943,zoneId=357,name="Return to Troyas",level=48,minLevel=42,giver="Daryn Lightwind",giverType="NPC",giverId=7907,ender="Troyas Moonbreeze",enderType="NPC",enderId=7764,poiX=8701,poiY=993,wowhead="https://www.wowhead.com/wotlk/quest=2943",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Here it is, $N. Please, take care of my book.$B$BNow, hurry along. I'm sure Troyas is eager for your return.",logDesc="Deliver the book to Troyas Moonbreeze in Feathermoon Stronghold."} end
if not DB[2944] then DB[2944]={id=2944,zoneId=357,name="The Super Snapper FX",level=48,minLevel=42,giver="Curgle Cranklehop",giverType="NPC",giverId=7763,ender="Daryn Lightwind",enderType="NPC",enderId=7907,rewardNextId=2943,poiX=-7113,poiY=-3831,wowhead="https://www.wowhead.com/wotlk/quest=2944",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Have the first look at my new invention, $N. All you need to do is target whatever it is you'd like to take a picture of, and push the button.$B$BWhat was that creature from the Hinterlands that you mentioned? Gammerita? Well, good luck finding her. I'm sure Daryn will be quite pleased with the snapshot you return to her.$B$BIn any case, here's the Super Snapper. Have fun!",logDesc="Use the Super Snapper FX to take a snapshot of Gammerita, then return to Daryn Lightwind in Rut'theran Village."} end
if not DB[2945] then DB[2945]={id=2945,zoneId=133,name="Grime-Encrusted Ring",level=34,minLevel=28,wowhead="https://www.wowhead.com/wotlk/quest=2945",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves.  It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible.  You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue.$B$BIf you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it.",logDesc="Figure out a way to remove the grime from the Grime-Encrusted Ring."} end
if not DB[2946] then DB[2946]={id=2946,zoneId=1537,name="Seeing What Happens",level=50,minLevel=45,giver="Historian Karnik",giverType="NPC",giverId=2916,poiX=-4632,poiY=-1327,wowhead="https://www.wowhead.com/wotlk/quest=2946",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We want you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.$B$BThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.$B$BWhen you've found out what happens, return to Ironforge.  We'll have a lot to analyze when you're done!",logDesc="Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two."} end
if not DB[2947] then DB[2947]={id=2947,zoneId=133,name="Return of the Ring",level=34,minLevel=28,ender="Talvash del Kissel",enderType="NPC",enderId=6826,rewardNextId=2948,wowhead="https://www.wowhead.com/wotlk/quest=2947",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Opening the box produced by the Sparklematic 5200 reveals what you had suspected - a shiny ring!  Wearing the ring, you feel magic power surge through you body.$B$BInside the band is a small but nonetheless discernable imprint of the seal of Ironforge.  Next to that, three small initials are engraved: \"TdK\".  This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or return it to this person.  Decisions, decisions...",logDesc="You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band."} end
if not DB[2948] then DB[2948]={id=2948,zoneId=1537,name="Gnome Improvement",level=35,minLevel=28,giver="Talvash del Kissel",giverType="NPC",giverId=6826,ender="Talvash del Kissel",enderType="NPC",enderId=6826,poiX=-4588,poiY=-1001,wowhead="https://www.wowhead.com/wotlk/quest=2948",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Listen $n, that ring is yours, sure... but I can make you a better one!  That design, like I said, is really simple.  I am a lot more skilled now, and for the mere fee of thirty silver coins I'll spruce it up for you!  Well, a little more than thirty, actually...$B$BI'm in a tight spot right now; all my material stock is all dried up.  If you bring me a bar of silver and a moss agate, I'll add a silver and agate lattice to the ring that will give it a little more pizzazz!$B$BTrust me!",logDesc="Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge.",rewards={{id=9538,qty=1}}} end
if not DB[2949] then DB[2949]={id=2949,zoneId=133,name="Return of the Ring",level=34,minLevel=28,ender="Nogg",enderType="NPC",enderId=3412,rewardNextId=2950,wowhead="https://www.wowhead.com/wotlk/quest=2949",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Opening the box produced by the Sparklematic 5200 reveals a shiny ring!  Donning the ring, you feel magic power surge through your body.$B$BInside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar.  Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\"$B$BThis may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or find \"NOG\" - decisions, decisions...",logDesc="You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band."} end
if not DB[2950] then DB[2950]={id=2950,zoneId=1637,name="Nogg's Ring Redo",level=35,minLevel=28,giver="Nogg",giverType="NPC",giverId=3412,ender="Nogg",enderType="NPC",enderId=3412,poiX=2036,poiY=-4746,wowhead="https://www.wowhead.com/wotlk/quest=2950",image="assets/images/quests/placeholder.png",xpDiff=5,desc="No, no, no - I'm not all of the sudden saying that the ring is mine.  I normally don't do this, but your information about the Dark Irons was very useful.  I'll improve your ring for you, better than whomever made this simple little thing could have ever done.  Probably some gnome...$B$BIf you bring me a bar of silver, a moss agate, and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it.  Interested?",logDesc="Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.",rewards={{id=9588,qty=1}}} end
if not DB[2951] then DB[2951]={id=2951,zoneId=133,name="The Sparklematic 5200!",level=30,minLevel=25,wowhead="https://www.wowhead.com/wotlk/quest=2951",image="assets/images/quests/placeholder.png",desc="This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:$B$B\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"",logDesc="Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine."} end
if not DB[2952] then DB[2952]={id=2952,zoneId=133,name="The Sparklematic 5200!",level=30,minLevel=25,wowhead="https://www.wowhead.com/wotlk/quest=2952",image="assets/images/quests/placeholder.png",xpDiff=5,rewards={{id=9363,qty=1}}} end
if not DB[2953] then DB[2953]={id=2953,zoneId=133,name="More Sparklematic Action",level=30,minLevel=25,wowhead="https://www.wowhead.com/wotlk/quest=2953",image="assets/images/quests/placeholder.png",rewards={{id=9363,qty=1}}} end
if not DB[2954] then DB[2954]={id=2954,zoneId=440,name="The Stone Watcher",level=50,minLevel=45,giver="Stone Watcher of Norgannon",giverType="NPC",giverId=7918,wowhead="https://www.wowhead.com/wotlk/quest=2954",image="assets/images/quests/placeholder.png",xpDiff=5,desc="\"Salutations - I am a guardian of entry.  Unless you have the Plates of Uldum already integrated with your disc set, I will not allow for entry into the Uldum compound.\"$B$BThe appearance of the Stone Watcher of Norgannon must be the reaction that was hoped for in sending you out to the Tanaris desert with the platinum discs.  As instructed, you will need to find out what the story behind the Stone Watcher is before continuing on.",logDesc="Learn the purpose of the Stone Watcher of Norgannon, and then interact with the Uldum Pedestal in the Tanaris desert."} end
if not DB[2962] then DB[2962]={id=2962,zoneId=133,name="The Only Cure is More Green Glow",level=30,minLevel=20,giver="Ozzie Togglevolt",giverType="NPC",giverId=1268,ender="Ozzie Togglevolt",enderType="NPC",enderId=1268,poiX=-5498,poiY=-458,wowhead="https://www.wowhead.com/wotlk/quest=2962",image="assets/images/quests/placeholder.png",xpDiff=7,money=2500,desc="Not only was your sample insufficient in quantity, it was also impure.$B$BWhat we require is more green glow. The troggs are obviously not irradiated sufficiently to fulfill our needs. You will have to go into Gnomeregan and bring back some radioactive fallout, straight from the tap. I am speaking of the irradiated slimes, lurkers and horrors. Be warned, the containment of this type of fallout is difficult. You may need to make several attempts with the phial until a suitable sampling is recovered.",logDesc="Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.$B$BOzzie will also require your Heavy Leaden Collection Phial when the task is complete.$B"} end
if not DB[2963] then DB[2963]={id=2963,zoneId=1537,name="Portents of Uldum",level=50,minLevel=45,giver="High Explorer Magellas",giverType="NPC",giverId=5387,ender="Historian Karnik",enderType="NPC",enderId=2916,rewardNextId=2946,poiX=-4667,poiY=-1266,wowhead="https://www.wowhead.com/wotlk/quest=2963",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Greetings once again, $n!  Your discovery inside Uldaman has set the Explorers' League abuzz with excitement.  The League has been working to unlock the secrets of the miniature platinum discs you found.  Your fortuitous arrival here in the Hall allows me to share with you that we are quite possibly on to something!$B$BHistorian Karnik has uncovered some important clues as to the true origins of the Valley of the Watchers in the Tanaris desert.  He would like to speak with you as soon as possible!",logDesc="Speak with Historian Karnik in the Hall of Explorers within Ironforge."} end
if not DB[2964] then DB[2964]={id=2964,zoneId=1537,name="A Future Task",level=50,minLevel=45,giver="Historian Karnik",giverType="NPC",giverId=2916,ender="High Explorer Magellas",enderType="NPC",enderId=5387,poiX=-4632,poiY=-1327,wowhead="https://www.wowhead.com/wotlk/quest=2964",image="assets/images/quests/placeholder.png",xpDiff=5,money=22000,desc="Well $n... we seem to be at a temporary dead end here.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We'll need to do quite a bit of research on this to come up with a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to head out and recover them.$B$BThe High Explorer needs to be informed on this, $n; no doubt, he also wants to thank you personally for once again aiding the League.",logDesc="Speak with High Explorer Magellas in Ironforge.",choiceRewards={{id=34418,qty=1},{id=34419,qty=1}}} end
if not DB[2965] then DB[2965]={id=2965,zoneId=1638,name="Portents of Uldum",level=50,minLevel=45,giver="Sage Truthseeker",giverType="NPC",giverId=3978,ender="Nara Wildmane",enderType="NPC",enderId=5770,rewardNextId=2966,poiX=-1176,poiY=158,wowhead="https://www.wowhead.com/wotlk/quest=2965",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Ah, $n, it is fortuitous that you have come to me again.  Your revelations at the Uldaman dig site have certainly given us sages much discuss.  I was doing just that with one of the druids, Nara Wildmane, when it dawned on me that her past adventuring experiences may have some great importance as to the next step we need to take.$B$BI would like for you to speak with her concerning her travels to the Valley of the Watchers in the Tanaris desert.  She waits for you on the Elder Rise.",logDesc="Speak with Nara Wildmane on the Elder Rise in Thunder Bluff."} end
if not DB[2966] then DB[2966]={id=2966,zoneId=1638,name="Seeing What Happens",level=50,minLevel=45,giver="Nara Wildmane",giverType="NPC",giverId=5770,poiX=-1070,poiY=-273,wowhead="https://www.wowhead.com/wotlk/quest=2966",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Sage Truthseeker and I would like you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.$B$BThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.$B$BLearn what you can, then return to me. We will have much to discuss.",logDesc="Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two."} end
if not DB[2967] then DB[2967]={id=2967,zoneId=1638,name="Return to Thunder Bluff",level=50,minLevel=45,ender="Nara Wildmane",enderType="NPC",enderId=5770,rewardNextId=2968,wowhead="https://www.wowhead.com/wotlk/quest=2967",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You access the pedestal again; the platinum discs suddenly appear once more in your backpack.$B$BWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Thunder Bluff and inform the Nara Wildmane of your discovery.",logDesc="Speak with Nara Wildmane in Thunder Bluff."} end
if not DB[2968] then DB[2968]={id=2968,zoneId=1638,name="A Future Task",level=50,minLevel=45,giver="Nara Wildmane",giverType="NPC",giverId=5770,ender="Sage Truthseeker",enderType="NPC",enderId=3978,poiX=-1070,poiY=-273,wowhead="https://www.wowhead.com/wotlk/quest=2968",image="assets/images/quests/placeholder.png",xpDiff=5,money=22000,desc="Well $n... we seem to be at an unfortunate impasse.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We will research this, and then devise a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to rejoin our efforts to discover the truth.$B$BSage Truthseeker needs to be informed on this, $n; no doubt, he also wants to thank you personally for once again heeding the call.",logDesc="Speak with Sage Truthseeker in Thunder Bluff.",choiceRewards={{id=34421,qty=1},{id=34422,qty=1}}} end
if not DB[2969] then DB[2969]={id=2969,zoneId=357,name="Freedom for All Creatures",level=47,minLevel=38,giver="Kindal Moonweaver",giverType="NPC",giverId=7956,ender="Kindal Moonweaver",enderType="NPC",enderId=7956,poiX=-4482,poiY=859,wowhead="https://www.wowhead.com/wotlk/quest=2969",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The filthy Grimtotem clan are capturing faerie dragons, $N. Jer'kai and I have no idea what they plan on doing with them, but they're obviously up to no good.$B$BWe're not powerful enough to fight our way into the camp and free the captured dragons, but perhaps with your help...$B$BIf you're willing, and you have some strong friends, release the creatures from their cage with this key and make sure they escape with their lives. I'll be by your side the entire time. Jer'kai will remain here.",logDesc="Using the Bamboo Cage Key, free the Sprite Darters from the pen in the Grimtotem camp. At least 6 Sprite Darters and Kindal Moonweaver must survive.$B$BYou have 6 minutes before Kindal decides it is time to retreat and you fail the quest."} end
if not DB[2970] then DB[2970]={id=2970,zoneId=357,name="Doling Justice",level=47,minLevel=38,giver="Jer'kai Moonweaver",giverType="NPC",giverId=7957,ender="Jer'kai Moonweaver",enderType="NPC",enderId=7957,poiX=-4480,poiY=858,wowhead="https://www.wowhead.com/wotlk/quest=2970",image="assets/images/quests/placeholder.png",xpDiff=4,desc="As she's already told you, Kindal and I will now take the fight to the Grimtotem. Together, we should still be able to pick off some of the tauren without much threat to ourselves, but we'd love some help if you're willing and able.$B$BYou've seen the camp below us, but there are more to the east. Using your own tactics, deal as much damage to the tauren as you can. We can all meet back here after they've felt the sting of Kindal's arrows and your own weapons.",logDesc="Kill 12 Grimtotem Naturalists, 10 Grimtotem Raiders, and 6 Grimtotem Shamans before returning to Jer'kai Moonweaver in Feralas."} end
if not DB[2971] then DB[2971]={id=2971,zoneId=133,name="<UNUSED>",level=32,minLevel=23,wowhead="https://www.wowhead.com/wotlk/quest=2971",image="assets/images/quests/placeholder.png",xpDiff=6,money=6500,desc="[PH] Description",logDesc="[PH] Log Description"} end
if not DB[2972] then DB[2972]={id=2972,zoneId=357,name="Doling Justice",level=47,minLevel=38,giver="Jer'kai Moonweaver",giverType="NPC",giverId=7957,ender="3",enderType="NPC",enderId=7999,poiX=-4480,poiY=858,wowhead="https://www.wowhead.com/wotlk/quest=2972",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring. If you ever find yourself in the boughs of Teldrassil, go to the Temple of the Moon in the heart of Darnassus. There you will find my High Priestess Tyrande Whisperwind. The ring will let her know that we are well and give credit to your story.$B$BWe both thank you, $N.",logDesc="Take Jer'kai's Signet Ring to High Priestess Tyrande Whisperwind in Darnassus.",choiceRewards={{id=10705,qty=1},{id=10706,qty=1}}} end
if not DB[2973] then DB[2973]={id=2973,zoneId=357,name="A New Cloak's Sheen",level=45,minLevel=38,giver="Krueg Skullsplitter",giverType="NPC",giverId=4544,ender="Krueg Skullsplitter",enderType="NPC",enderId=4544,rewardNextId=2974,poiX=-4347,poiY=164,wowhead="https://www.wowhead.com/wotlk/quest=2973",image="assets/images/quests/placeholder.png",xpDiff=5,money=6500,desc="Well met, $c. I've traveled with my companions down to the Feralas on a mission for our Orgrimmar masters.$B$BMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with gorgeous wings I want are west of Camp Mojache.",logDesc="Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache."} end
if not DB[2974] then DB[2974]={id=2974,zoneId=357,name="A Grim Discovery",level=45,minLevel=38,giver="Krueg Skullsplitter",giverType="NPC",giverId=4544,ender="Krueg Skullsplitter",enderType="NPC",enderId=4544,rewardNextId=2976,poiX=-4347,poiY=164,wowhead="https://www.wowhead.com/wotlk/quest=2974",image="assets/images/quests/placeholder.png",xpDiff=5,money=6500,desc="What!? You came across tauren in the area? You're joking! What did they look like!?$B$BThe Grimtotem clan! You found some of them? Belgrom, one of our masters, has an interest in their kind... he's even put a bounty on them.$B$BYou have to go back, $c. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.",logDesc="Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache."} end
if not DB[2975] then DB[2975]={id=2975,zoneId=357,name="The Ogres of Feralas",level=43,minLevel=38,giver="Rok Orhan",giverType="NPC",giverId=7777,ender="Rok Orhan",enderType="NPC",enderId=7777,rewardNextId=2980,poiX=-4386,poiY=173,wowhead="https://www.wowhead.com/wotlk/quest=2975",image="assets/images/quests/placeholder.png",xpDiff=4,money=4500,desc="The effects of the Gordunni Ogre tribe can hardly go unnoticed in this area. Look around, $N; their very presence scars this land. We must push them back before they expand even further into Feralas.$B$BFollow the river north, and you will find their outpost. Decrease their numbers, $N. We must show them that their kind is not wanted here.",logDesc="Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes."} end
if not DB[2976] then DB[2976]={id=2976,zoneId=357,name="A Grim Discovery",level=45,minLevel=37,giver="Krueg Skullsplitter",giverType="NPC",giverId=4544,ender="Belgrom Rockmaul",enderType="NPC",enderId=4485,poiX=-4347,poiY=164,wowhead="https://www.wowhead.com/wotlk/quest=2976",image="assets/images/quests/placeholder.png",xpDiff=6,money=6500,desc="What?!$B$BAh, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it?$B$BYou did the work, so I suppose it is only right you reap the greatest reward from it. Take the horns, I'll have them put in a crate for you. Find Belgrom Rockmaul in the Valley of Honor, he'll want to know what you saw and he'll reward you for your hard work.$B$BBe well, $c, and thank you again for everything you've done.",logDesc="Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar.",choiceRewards={{id=11858,qty=1},{id=11859,qty=1}}} end
if not DB[2977] then DB[2977]={id=2977,zoneId=1537,name="Return to Ironforge",level=50,minLevel=45,ender="Historian Karnik",enderType="NPC",enderId=2916,rewardNextId=2964,wowhead="https://www.wowhead.com/wotlk/quest=2977",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You access the pedestal again; the platinum discs suddenly appear once more in your backpack.$B$BWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Ironforge and inform the Explorers' League of your discovery.",logDesc="Speak with Historian Karnik in Ironforge."} end
if not DB[2978] then DB[2978]={id=2978,zoneId=357,name="The Gordunni Scroll",level=43,minLevel=38,ender="Rok Orhan",enderType="NPC",enderId=7777,rewardNextId=2979,wowhead="https://www.wowhead.com/wotlk/quest=2978",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Picking up the soiled scroll, you notice that it seems to be depicting some sort of meeting or ceremony. Rok Orhan would be interested in this scroll, and what it might mean to the Gordunni.",logDesc="Bring the Gordunni Scroll to Rok Orhan in Camp Mojache."} end
if not DB[2979] then DB[2979]={id=2979,zoneId=357,name="Dark Ceremony",level=46,minLevel=38,giver="Rok Orhan",giverType="NPC",giverId=7777,ender="Rok Orhan",enderType="NPC",enderId=7777,rewardNextId=3002,poiX=-4386,poiY=173,wowhead="https://www.wowhead.com/wotlk/quest=2979",image="assets/images/quests/placeholder.png",xpDiff=5,desc="These seem to be plans for some sort of dark ceremony, $N. From what I can make out, this ritual is conducted by the Gordunni mage-lords.$B$BFind one of these mage-lords, and from him, gather an orb.$B$BThe orb of a mage contains great power, and will help us discover more about this ceremony and the magic that the Gordunni wield.",logDesc="Rok Orhan in Camp Mojache wants you to find a Gordunni Orb."} end
if not DB[2980] then DB[2980]={id=2980,zoneId=357,name="The Ogres of Feralas",level=44,minLevel=38,giver="Rok Orhan",giverType="NPC",giverId=7777,ender="Rok Orhan",enderType="NPC",enderId=7777,poiX=-4386,poiY=173,wowhead="https://www.wowhead.com/wotlk/quest=2980",image="assets/images/quests/placeholder.png",xpDiff=5,money=12500,desc="Now that you have proven that you are a true fighter, I trust that you possess the courage to continue with the task at hand.$B$BTravel to the High Wilderness, southwest of here. There lie some abandoned and destroyed structures, on land that once belonged to the night elves. Look for these ruins, and when you see the withered trees and desecrated terrain, you will find the Gordunni. Push them back.$B$BThese ogres are much stronger than the ones you faced previously, $N. Be aware.",logDesc="Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers."} end
if not DB[2981] then DB[2981]={id=2981,zoneId=1637,name="A Threat in Feralas",level=43,minLevel=38,giver="Belgrom Rockmaul",giverType="NPC",giverId=4485,ender="Rok Orhan",enderType="NPC",enderId=7777,rewardNextId=2975,poiX=1954,poiY=-4736,wowhead="https://www.wowhead.com/wotlk/quest=2981",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Feralas is an ideal location for an accomplished $c to prove $Ghimself:herself;. A tribe of ogres called the Gordunni are the dominant military force there, and their numbers are growing. They must be stopped before they threaten our presence in Feralas.$B$BA warrior I know of named Rok Orhan resides at Camp Mojache in Feralas; go to her. She will tell you more of the situation when you arrive.",logDesc="Belgrom Rockmaul wants you to speak with Rok Orhan in Camp Mojache."} end
if not DB[2982] then DB[2982]={id=2982,zoneId=357,name="The High Wilderness",level=44,minLevel=39,giver="Angelas Moonbreeze",giverType="NPC",giverId=7900,ender="Angelas Moonbreeze",enderType="NPC",enderId=7900,poiX=-4480,poiY=3230,wowhead="https://www.wowhead.com/wotlk/quest=2982",image="assets/images/quests/placeholder.png",xpDiff=5,money=6500,desc="Although it is dangerous, Troyas and I have been investigating the ruins that cover the forests of Feralas.$B$BLately, though, Troyas has been going on his own to the High Wilderness, and I really worry about him. The Gordunni Ogres have taken over that area, and they don't take kindly to anyone that enters their territory.$B$BI was hoping you might be willing to travel to the ruins to the southeast and clear out some of the ogres. Make it a little safer for my Troyas, and I will be extremely grateful.",logDesc="Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes."} end
if not DB[2983] then DB[2983]={id=2983,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Swart",giverType="NPC",giverId=3173,ender="Kranal Fiss",enderType="NPC",enderId=5907,rewardNextId=1524,poiX=307,poiY=-4840,wowhead="https://www.wowhead.com/wotlk/quest=2983",image="assets/images/quests/placeholder.png",xpDiff=3,desc="It's been some time since you were tested last, $N. You've been patient thus far in your studies, but it's time for you to learn about greater powers... it's time you learn real power. The element of fire is yours if you're prepared to pay for it.$B$BSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the blasted night elf lands, you've gone way too far.",logDesc="Find Kranal Fiss in the Barrens."} end
if not DB[2984] then DB[2984]={id=2984,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Narm Skychaser",giverType="NPC",giverId=3066,ender="Kranal Fiss",enderType="NPC",enderId=5907,rewardNextId=1524,poiX=-2299,poiY=-438,wowhead="https://www.wowhead.com/wotlk/quest=2984",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.$B$BSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.",logDesc="Find Kranal Fiss in the Barrens."} end
if not DB[2985] then DB[2985]={id=2985,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Swart",giverType="NPC",giverId=3173,ender="Islen Waterseer",enderType="NPC",enderId=5901,rewardNextId=1530,poiX=307,poiY=-4840,wowhead="https://www.wowhead.com/wotlk/quest=2985",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You look ready for your next test, $N. You've been patient in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.$B$BSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, $N.",logDesc="Find Islen Waterseer in the Barrens."} end
if not DB[2986] then DB[2986]={id=2986,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Narm Skychaser",giverType="NPC",giverId=3066,ender="Islen Waterseer",enderType="NPC",enderId=5901,rewardNextId=1530,poiX=-2299,poiY=-438,wowhead="https://www.wowhead.com/wotlk/quest=2986",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.$B$BSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, $N.",logDesc="Find Islen Waterseer in the Barrens."} end
if not DB[2987] then DB[2987]={id=2987,zoneId=357,name="Gordunni Cobalt",level=43,minLevel=38,giver="Orwin Gizzmick",giverType="NPC",giverId=8021,ender="Orwin Gizzmick",enderType="NPC",enderId=8021,poiX=-4420,poiY=181,wowhead="https://www.wowhead.com/wotlk/quest=2987",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff! They don't leave it just lying around; no, they bury it to protect folks like me from getting their hands on it.$B$BIf you'd be willing, I'll give you my shovel. Go to the Gordunni Outpost north of here and dig me up some Gordunni cobalt. Look for the blue glow, then start digging!",logDesc="Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.",choiceRewards={{id=9658,qty=1},{id=9660,qty=1}}} end
if not DB[2988] then DB[2988]={id=2988,zoneId=47,name="Witherbark Cages",level=45,minLevel=40,giver="Gryphon Master Talonaxe",giverType="NPC",giverId=5636,ender="Gryphon Master Talonaxe",enderType="NPC",enderId=5636,rewardNextId=2989,poiX=325,poiY=-1950,wowhead="https://www.wowhead.com/wotlk/quest=2988",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The son of our mightiest gryphon is gone! Swiftwing's heir, Sharpbeak, was lost while hunting with his parents a few days ago, and we believe it was the trolls who took him.$B$BYou must aid us!  Search the cages in the two Witherbark troll villages to see if Sharpbeak is there.",logDesc="Check the cages at the two Witherbark villages, then return to Gryphon  Master Talonaxe."} end
if not DB[2989] then DB[2989]={id=2989,zoneId=47,name="The Altar of Zul",level=48,minLevel=40,giver="Gryphon Master Talonaxe",giverType="NPC",giverId=5636,ender="Gryphon Master Talonaxe",enderType="NPC",enderId=5636,rewardNextId=2990,poiX=325,poiY=-1950,wowhead="https://www.wowhead.com/wotlk/quest=2989",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Sharpbeak was not with the Witherbark trolls.  Perhaps the Vilebranch trolls took him.  Go to the Altar of Zul on the western edge of Vilebranch territory and search for the gryphon child. ",logDesc="Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe."} end
if not DB[2990] then DB[2990]={id=2990,zoneId=47,name="Thadius Grimshade",level=47,minLevel=40,giver="Gryphon Master Talonaxe",giverType="NPC",giverId=5636,ender="Thadius Grimshade",enderType="NPC",enderId=8022,rewardNextId=2991,poiX=325,poiY=-1950,wowhead="https://www.wowhead.com/wotlk/quest=2990",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Take this feather to Thadius Grimshade, the diviner.  He left Aerie Peak years ago to pursue darker knowledge, but in his heart he is still a Wildhammer!$B$BAnd perhaps his talents can help us find Sharpbeak.$B$BThis feather was taken from the nest where the gryphon child sleeps.  If you give it to Thadius then, with luck, he can use his divining magics to find Sharpbeak.$B$BGood luck, $N.  You will find Thadius in the Blasted Lands, in the mage tower of Nethergarde Keep.",logDesc="Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands."} end
if not DB[2991] then DB[2991]={id=2991,zoneId=978,name="Nekrum's Medallion",level=47,minLevel=40,giver="Thadius Grimshade",giverType="NPC",giverId=8022,ender="Thadius Grimshade",enderType="NPC",enderId=8022,rewardNextId=2992,poiX=-11001,poiY=-3483,wowhead="https://www.wowhead.com/wotlk/quest=2991",image="assets/images/quests/placeholder.png",xpDiff=7,money=7000,desc="I'll find out where your gryphon is, but first you have to do something for me.  There's a troll in Zul'Farrak, Nekrum Gutchewer, who possesses a medallion I would very much like to study.  Bring me that Medallion and I'll use my powers to find Sharpbeak.$B$BZul'Farrak is across the ocean to the west, in the desert of Tanaris.",logDesc="Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands."} end
if not DB[2992] then DB[2992]={id=2992,zoneId=47,name="The Divination",level=47,minLevel=40,giver="Thadius Grimshade",giverType="NPC",giverId=8022,ender="Thadius Grimshade",enderType="NPC",enderId=8022,rewardNextId=2993,poiX=-11001,poiY=-3483,wowhead="https://www.wowhead.com/wotlk/quest=2992",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Give me room while I perform a ritual of divination.  I will find the connection between the feather you brought me and its owner, and follow that connection to Sharpbeak himself.$B$BThat is... I will if all goes according to plan.  If it does not, then... you better close your eyes.",logDesc="Wait until Grimshade performs the ritual of divination."} end
if not DB[2993] then DB[2993]={id=2993,zoneId=47,name="Return to the Hinterlands",level=47,minLevel=40,giver="Thadius Grimshade",giverType="NPC",giverId=8022,ender="Gryphon Master Talonaxe",enderType="NPC",enderId=5636,rewardNextId=2994,poiX=-11001,poiY=-3483,wowhead="https://www.wowhead.com/wotlk/quest=2993",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Sharpbeak is held in a cage, high on a cliff at the top of Jintha'Alor in the Hinterlands.  The key to this cage is possessed by the high priestess of the Vilebranch trolls, Vile Priestess Hexx.$B$BThere.  I have done my part.  I bid you fortune on your quest, $N.",logDesc="Speak with Gryphon Master Talonaxe."} end
if not DB[2994] then DB[2994]={id=2994,zoneId=47,name="Saving Sharpbeak",level=51,minLevel=40,giver="Gryphon Master Talonaxe",giverType="NPC",giverId=5636,ender="Gryphon Master Talonaxe",enderType="NPC",enderId=5636,poiX=325,poiY=-1950,wowhead="https://www.wowhead.com/wotlk/quest=2994",image="assets/images/quests/placeholder.png",xpDiff=7,money=22500,desc="We must save Sharpbeak!$B$BFight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!",logDesc="Fight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak.",choiceRewards={{id=9651,qty=1},{id=9652,qty=1}}} end
if not DB[2995] then DB[2995]={id=2995,zoneId=1497,name="Lines of Communication",level=47,minLevel=42,giver="Oran Snakewrithe",giverType="NPC",giverId=7825,ender="Oran Snakewrithe",enderType="NPC",enderId=7825,poiX=1668,poiY=172,wowhead="https://www.wowhead.com/wotlk/quest=2995",image="assets/images/quests/placeholder.png",xpDiff=4,money=7000,desc="The Quel'Danil Lodge is a center of communication for the high elves of the Hinterlands. Their ambassadors are working to establish relationships with other races, with whom they share their knowledge of the Witherbark trolls that inhabit the area in the southern Hinterlands. All of the documents regarding the communications are kept at the lodge.$B$BWe don't need the Highvale building alliances with others, $N.$B$BDestroy the Highvale documents.  We need to burn their lines of communication... literally.",logDesc="Oran Snakewrithe in Undercity wants you to travel to the Hinterlands and burn the Highvale Records, Highvale Report, and Highvale Notes."} end
if not DB[2996] then DB[2996]={id=2996,zoneId=-61,name="Seeking Strahad",level=-1,minLevel=30,giver="Gan'rul Bloodeye",giverType="NPC",giverId=5875,ender="Strahad Farsan",enderType="NPC",enderId=6251,poiX=1850,poiY=-4357,wowhead="https://www.wowhead.com/wotlk/quest=2996",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak. He is powerful even though he may be small. He can teach you about more powerful summonings--I feel you are ready. Go to him now. He is in Ratchet... above the port town next to his tower.",logDesc="Speak to Strahad Farsan in Ratchet."} end
if not DB[2997] then DB[2997]={id=2997,zoneId=-141,name="Tome of Divinity",level=-1,minLevel=12,giver="Azar Stronghammer",giverType="NPC",giverId=1232,ender="Tiza Battleforge",enderType="NPC",enderId=6179,poiX=-5587,poiY=-542,wowhead="https://www.wowhead.com/wotlk/quest=2997",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, $N. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should make your way up to Ironforge to speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.$B$BYou can find her upstairs in the Hall of Mysteries. If you've never been there, it's in the Mystic Ward. Good luck to ya, $N.",logDesc="Speak to Tiza Battleforge in Ironforge."} end
if not DB[2998] then DB[2998]={id=2998,zoneId=-141,name="Tome of Divinity",level=-1,minLevel=12,giver="Brother Wilhelm",giverType="NPC",giverId=927,ender="Duthorian Rall",enderType="NPC",enderId=6171,poiX=-9468,poiY=109,wowhead="https://www.wowhead.com/wotlk/quest=2998",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Greetings, $Gbrother:sister;. Duthorian Rall, one of our most influential paladins, was speaking about you recently. I overheard him talking about how it was time you be put to the test some... along with some very complimentary things about how well you've performed thus far.$B$BIf I were you, I'd head to Stormwind and speak to him when you have time. I'm sure he's in the Cathedral of Light--that's where he spends most of his time.",logDesc="Speak to Duthorian Rall in Stormwind."} end
if not DB[2999] then DB[2999]={id=2999,zoneId=-141,name="Tome of Divinity",level=-1,minLevel=12,giver="Brandur Ironhammer",giverType="NPC",giverId=5149,ender="Tiza Battleforge",enderType="NPC",enderId=6179,poiX=-4602,poiY=-896,wowhead="https://www.wowhead.com/wotlk/quest=2999",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, $N. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should go upstairs and speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.",logDesc="Speak to Tiza Battleforge in Ironforge"} end
if not DB[3000] then DB[3000]={id=3000,zoneId=-141,name="Tome of Divinity",level=-1,minLevel=12,giver="Lord Grayson Shadowbreaker",giverType="NPC",giverId=928,ender="Tiza Battleforge",enderType="NPC",enderId=6179,poiX=-8577,poiY=882,wowhead="https://www.wowhead.com/wotlk/quest=3000",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hello, $N. I know you're busy helping out the people of Azeroth, but when you have the time, you should return to Ironforge and speak to one of the most respected paladins of your home: Tiza Battleforge. She's the one the younger dwarven paladins go to when it is time they learn more about the Light and what's expected of all of us.$B$BYou can find her upstairs in the Hall of Mysteries which is located in the Mystic Ward.",logDesc="Speak to Tiza Battleforge in Ironforge."} end
if not DB[3001] then DB[3001]={id=3001,zoneId=-61,name="Seeking Strahad",level=-1,minLevel=30,giver="Carendin Halgar",giverType="NPC",giverId=5675,ender="Strahad Farsan",enderType="NPC",enderId=6251,poiX=1712,poiY=57,wowhead="https://www.wowhead.com/wotlk/quest=3001",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak, nor is he your enemy... at least for now. He is powerful and should be respected. He can teach you about greater summonings, summonings I feel you are prepared for. Go to him now.$B$BYou can find him in Ratchet... above the port town next to the tower there.",logDesc="Find Strahad Farsan in Ratchet."} end
if not DB[3002] then DB[3002]={id=3002,zoneId=357,name="The Gordunni Orb",level=47,minLevel=38,giver="Rok Orhan",giverType="NPC",giverId=7777,ender="Uthel'nay",enderType="NPC",enderId=7311,poiX=-4386,poiY=173,wowhead="https://www.wowhead.com/wotlk/quest=3002",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Although I know my enemy well, I am a warrior, $N. I cannot begin to tell you what this orb is capable of.$B$BI know of a mage in Orgrimmar that will be able to tell us more about the orb. Take it to him. ",logDesc="Bring the Gordunni Orb to Uthel'nay in the Darkbriar Lodge in Orgrimmar."} end
if not DB[3022] then DB[3022]={id=3022,zoneId=440,name="Handle With Care",level=47,minLevel=42,giver="Curgle Cranklehop",giverType="NPC",giverId=7763,ender="Erelas Ambersky",enderType="NPC",enderId=7916,poiX=-7113,poiY=-3831,wowhead="https://www.wowhead.com/wotlk/quest=3022",image="assets/images/quests/placeholder.png",xpDiff=3,money=5000,desc="$N, I can see you yearn to be dedicated to my worthwhile cause. Yes, of course, you can do something for me!$B$BTake this crate of eggs to Erelas Ambersky. He is a druid that cares for these eggs, helping them to hatch and then training the young hippogryphs. You will find him in Teldrassil, in a small village to the south called Rut'theran.",logDesc="Bring the Carefully-packed Crate to Erelas Ambersky in Rut'theran Village."} end
if not DB[3023] then DB[3023]={id=3023,zoneId=-141,name="<UNUSED>",level=30,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=3023",image="assets/images/quests/placeholder.png"} end
if not DB[3042] then DB[3042]={id=3042,zoneId=978,name="Troll Temper",level=45,minLevel=40,giver="Trenton Lighthammer",giverType="NPC",giverId=7804,ender="Trenton Lighthammer",enderType="NPC",enderId=7804,poiX=-7198,poiY=-3766,wowhead="https://www.wowhead.com/wotlk/quest=3042",image="assets/images/quests/placeholder.png",xpDiff=7,money=19500,desc="The Sandfury trolls of Zul'Farrak make a tempering agent from sandstones, and I can use that to temper the goods I craft, yes I can!  It is highly prized by connoisseurs, so if you bring me a good supply of the temper, then I'll reward you well.$B$BZul'Farrak is northwest of Gadgetzan.  Good luck.",logDesc="Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan."} end
if not DB[3062] then DB[3062]={id=3062,zoneId=357,name="Dark Heart",level=50,minLevel=45,giver="Talo Thornhoof",giverType="NPC",giverId=7776,ender="Talo Thornhoof",enderType="NPC",enderId=7776,poiX=-4398,poiY=147,wowhead="https://www.wowhead.com/wotlk/quest=3062",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.$B$BI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.$B$BImagine her surprise when it is not her kin calling her, but her death.",logDesc="Talo Thornhoof in Camp Mojache wants Edana Hatetalon's Dark Heart.",choiceRewards={{id=9665,qty=1},{id=9666,qty=1}}} end
if not DB[3063] then DB[3063]={id=3063,zoneId=357,name="Vengeance on the Northspring",level=50,minLevel=45,giver="Talo Thornhoof",giverType="NPC",giverId=7776,ender="Talo Thornhoof",enderType="NPC",enderId=7776,poiX=-4398,poiY=147,wowhead="https://www.wowhead.com/wotlk/quest=3063",image="assets/images/quests/placeholder.png",xpDiff=4,money=5500,desc="In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...$B$BI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.$B$BEven now, I can still hear their cries echoing...$B$BI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.$B$BThe Northspring harpies can be found to the west of here. $N, get my revenge. ",logDesc="Talo Thornhoof wants you to kill 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers, and 4 Northspring Slayers."} end
if not DB[3064] then DB[3064]={id=3064,zoneId=440,name="<NYI> <TXT> Pirate Hats",level=45,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=3064",image="assets/images/quests/placeholder.png",desc="I need pirate hats for my shop.  Get me lots!",logDesc="Bring 20 Untorn Pirate Hats to Yorba Screwspigot."} end
if not DB[3065] then DB[3065]={id=3065,zoneId=-81,name="Simple Tablet",level=1,minLevel=1,giver="Gornek",giverType="NPC",giverId=3143,ender="Frang",enderType="NPC",enderId=3153,poiX=-600,poiY=-4186,wowhead="https://www.wowhead.com/wotlk/quest=3065",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ah, while you were gone a parchment came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.",logDesc="Read the Simple Tablet and speak to Frang in the Valley of Trials."} end
