if not DB[3090] then DB[3090]={id=3090,zoneId=-61,name="Tainted Parchment",level=1,minLevel=1,giver="Gornek",giverType="NPC",giverId=3143,ender="Nartok",enderType="NPC",enderId=3156,poiX=-600,poiY=-4186,wowhead="https://www.wowhead.com/wotlk/quest=3090",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ah, while you were gone a parchment came for you, $N.$B$BI usually avoid dealing with warlocks if I can help it, but I think you should read it when you have time. If I'm not mistaken, it came from your newly-appointed trainer Nartok. He would have words with you when you're ready.",logDesc="Read the Tainted Parchment and speak to Nartok inside the Den in the Valley of Trials."} end
if not DB[3091] then DB[3091]={id=3091,zoneId=-81,name="Simple Note",level=1,minLevel=1,giver="Grull Hawkwind",giverType="NPC",giverId=2980,ender="Harutt Thunderhorn",enderType="NPC",enderId=3059,poiX=-2913,poiY=-258,wowhead="https://www.wowhead.com/wotlk/quest=3091",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Just a moment ago a messenger was looking for you, $N. I believe she was sent by the warrior trainer Harutt. If this note is from Harutt, I wouldn't take long in reading it's contents.$B",logDesc="Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache."} end
