if not DB[3100] then DB[3100]={id=3100,zoneId=-81,name="Simple Letter",level=1,minLevel=1,giver="Marshal McBride",giverType="NPC",giverId=197,ender="Llane Beshere",enderType="NPC",enderId=911,poiX=-8903,poiY=-163,wowhead="https://www.wowhead.com/wotlk/quest=3100",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Llane, our local warrior trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.",logDesc="Read the Simple Letter and speak to Llane Beshere in Northshire Abbey."} end
