if not DB[3106] then DB[3106]={id=3106,zoneId=-81,name="Simple Rune",level=1,minLevel=1,giver="Sten Stoutarm",giverType="NPC",giverId=658,ender="Thran Khorman",enderType="NPC",enderId=912,poiX=-6237,poiY=331,wowhead="https://www.wowhead.com/wotlk/quest=3106",image="assets/images/quests/placeholder.png",xpDiff=3,desc="While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar when you've a chance.",logDesc="Read the Simple Rune and speak to Thran Khorman in Coldridge Valley."} end
