if not DB[3111] then DB[3111]={id=3111,zoneId=-161,name="<UNUSED>",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=3111",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Long ago high elves taught us the secrets of magic along with our human allies. They preached to us about rules and how magic can make ya go mad! But don't believe it. We're not like the elves; we don't have the same weaknesses. Just keep yourself on the right path and you'll find magic is as powerful a tool as it is a weapon.$B$BWhen you're ready,come find me inside Anvilmar. I'll be waiting for ya!$B$B- Marrek Stromnur,Mage Trainer",logDesc="Speak to Marrek Stromnur inside Anvilmar."} end
if not DB[3112] then DB[3112]={id=3112,zoneId=-81,name="Simple Memorandum",level=1,minLevel=1,giver="Sten Stoutarm",giverType="NPC",giverId=658,ender="Thran Khorman",enderType="NPC",enderId=912,poiX=-6237,poiY=331,wowhead="https://www.wowhead.com/wotlk/quest=3112",image="assets/images/quests/placeholder.png",xpDiff=3,desc="While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar when you've a chance.",logDesc="Read the Simple Memorandum and speak to Thran Khorman in Coldridge Valley."} end
