if not DB[3115] then DB[3115]={id=3115,zoneId=-61,name="Tainted Memorandum",level=1,minLevel=1,giver="Sten Stoutarm",giverType="NPC",giverId=658,ender="Alamar Grimm",enderType="NPC",enderId=460,poiX=-6237,poiY=331,wowhead="https://www.wowhead.com/wotlk/quest=3115",image="assets/images/quests/placeholder.png",xpDiff=3,desc="While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warlock trainer Alamar. Take a gander at it and go find him inside Anvilmar when you've a chance.$B$BAnd watch yerself, $N, your kind ain't too trusted 'round these parts.",logDesc="Read the Tainted Memorandum and speak to Alamar Grimm inside Anvilmar above Coldridge Valley."} end
if not DB[3116] then DB[3116]={id=3116,zoneId=-81,name="Simple Sigil",level=1,minLevel=1,giver="Conservator Ilthalaine",giverType="NPC",giverId=2079,ender="Alyissia",enderType="NPC",enderId=3593,poiX=10314,poiY=830,wowhead="https://www.wowhead.com/wotlk/quest=3116",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This sigil was given to me by a messenger from our warrior trainer, Alyissia. It seems Alyissia would have words with you when you have a moment. Read it and bring it to her afterwards.",logDesc="Read the Simple Sigil and speak to Alyissia in Shadowglen."} end
