if not DB[3121] then DB[3121]={id=3121,zoneId=357,name="A Strange Request",level=45,minLevel=40,giver="Witch Doctor Uzer'i",giverType="NPC",giverId=8115,ender="Xerash Fireblade",enderType="NPC",enderId=36208,rewardNextId=3122,poiX=-4376,poiY=270,wowhead="https://www.wowhead.com/wotlk/quest=3121",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Xerash Fireblade, located at the Lariss Pavilion, north of Camp Mojache,  has what I need to get started here! He has mixed up a concoction that I need for my... well, you'll see.$B$BOff with you now -- to Xerash. Here, take this with you. It's a shrunken head that I promised Xerash in exchange for the herbs. It's the head of some poor dwarf I ventured across in the forest. I'm sure he will be pleased.",logDesc="Take the Shrunken Head to Xerash Fireblade at the Lariss Pavilion in Feralas."} end
if not DB[3122] then DB[3122]={id=3122,zoneId=357,name="Return to Witch Doctor Uzer'i",level=45,minLevel=40,giver="Xerash Fireblade",giverType="NPC",giverId=36208,ender="Witch Doctor Uzer'i",enderType="NPC",enderId=8115,poiX=-4103,poiY=107,wowhead="https://www.wowhead.com/wotlk/quest=3122",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Here are the herbs, $N. Take them to Witch Doctor Uzer'i.$B$BPlease let him know that I am satisfied with the shrunken head.",logDesc="Deliver Xerash's Herb Pouch to Witch Doctor Uzer'i in Feralas."} end
if not DB[3123] then DB[3123]={id=3123,zoneId=357,name="Testing the Vessel",level=47,minLevel=40,giver="Witch Doctor Uzer'i",giverType="NPC",giverId=8115,ender="Witch Doctor Uzer'i",enderType="NPC",enderId=8115,rewardNextId=3124,poiX=-4376,poiY=270,wowhead="https://www.wowhead.com/wotlk/quest=3123",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This will be a test; both of the ritual I performed, and of your abilities. Take this vessel, $N. With it, you will have the power to shrink and capture a creature inside of it.$B$BTravel to the wilderness east of here and look for beasts. The vicious, ironfur bears and longtooth runners are your targets, $N. Kill them, and use the muisek vessel to shrink and capture them before their spirits can escape.",logDesc="Kill 10 Ironfur Bears or Longtooth Runners, and use the Beast Muisek Vessel to shrink and capture the fallen beasts.$B$BBring 10 Beast Muiseks and the Beast Muisek Vessel to Witch Doctor Uzer'i in Feralas."} end
if not DB[3124] then DB[3124]={id=3124,zoneId=357,name="Hippogryph Muisek",level=47,minLevel=40,giver="Witch Doctor Uzer'i",giverType="NPC",giverId=8115,ender="Witch Doctor Uzer'i",enderType="NPC",enderId=8115,rewardNextId=3125,poiX=-4376,poiY=270,wowhead="https://www.wowhead.com/wotlk/quest=3124",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Since you have proven that you are both trustworthy and gifted with the ability to use the muisek vessel, I now wish you to capture another creature.$B$BHippogryphs have been loyal companions to the night elves for many years; their spirits are loyal and steadfast.$B$BYour task is to kill 10 frayfeather hippogryphs, and quickly, shrink and capture them with the vessel, so that their muisek may be preserved. You will find the hippogryphs in the High Wilderness, to the south of here. ",logDesc="Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them."} end
if not DB[3125] then DB[3125]={id=3125,zoneId=357,name="Faerie Dragon Muisek",level=45,minLevel=40,giver="Witch Doctor Uzer'i",giverType="NPC",giverId=8115,ender="Witch Doctor Uzer'i",enderType="NPC",enderId=8115,rewardNextId=3126,poiX=-4376,poiY=270,wowhead="https://www.wowhead.com/wotlk/quest=3125",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.$B$BHere is the muisek, $N. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.",logDesc="Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons."} end
if not DB[3126] then DB[3126]={id=3126,zoneId=357,name="Treant Muisek",level=50,minLevel=40,giver="Witch Doctor Uzer'i",giverType="NPC",giverId=8115,ender="Witch Doctor Uzer'i",enderType="NPC",enderId=8115,rewardNextId=3127,poiX=-4376,poiY=270,wowhead="https://www.wowhead.com/wotlk/quest=3126",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The wandering forest walkers that can be found meandering through the forest are our next target, $N. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.$B$BSoon we will be able to use this power for our own benefit.$B$BFind 3 wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.",logDesc="Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants."} end
if not DB[3127] then DB[3127]={id=3127,zoneId=357,name="Mountain Giant Muisek",level=50,minLevel=40,giver="Witch Doctor Uzer'i",giverType="NPC",giverId=8115,ender="Witch Doctor Uzer'i",enderType="NPC",enderId=8115,poiX=-4376,poiY=270,wowhead="https://www.wowhead.com/wotlk/quest=3127",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The last task I will require of you is to travel to the northwest and find the final enemy.$B$BThe mountain giants left the mountains to aid the night elves when the burning legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.$B$BI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.",logDesc="Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants."} end
if not DB[3128] then DB[3128]={id=3128,zoneId=357,name="Natural Materials",level=50,minLevel=40,giver="Witch Doctor Uzer'i",giverType="NPC",giverId=8115,ender="Witch Doctor Uzer'i",enderType="NPC",enderId=8115,poiX=-4376,poiY=270,wowhead="https://www.wowhead.com/wotlk/quest=3128",image="assets/images/quests/placeholder.png",xpDiff=5,money=5500,desc="I will need certain materials to complete my endeavor... You may do this alongside the other tasks I will give you.$B$BI'll need a splintered log from a treant of Feralas. Encrusted minerals, these can be found on the mountain giants and faerie dragons to the west. Also, find me some resilient sinew from the owlbeasts of the Hinterlands or hippogryphs of Feralas. Finally, I'll need a large amount of metallic fragments from any of these creatures I mentioned.",logDesc="Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache."} end
if not DB[3129] then DB[3129]={id=3129,zoneId=357,name="Weapons of Spirit",level=50,minLevel=40,giver="Witch Doctor Uzer'i",giverType="NPC",giverId=8115,ender="Witch Doctor Uzer'i",enderType="NPC",enderId=8115,poiX=-4376,poiY=270,wowhead="https://www.wowhead.com/wotlk/quest=3129",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.",logDesc="Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.",choiceRewards={{id=9684,qty=1},{id=9686,qty=1},{id=9683,qty=1},{id=10652,qty=1}}} end
if not DB[3130] then DB[3130]={id=3130,zoneId=357,name="Against the Hatecrest",level=43,minLevel=40,giver="3",giverType="NPC",giverId=3936,ender="Latronicus Moonspear",enderType="NPC",enderId=7877,rewardNextId=2869,poiX=-4506,poiY=3337,wowhead="https://www.wowhead.com/wotlk/quest=3130",image="assets/images/quests/placeholder.png",xpDiff=1,desc="At this point, I am going to direct you to my second, Latronicus.  He's been keeping a close eye on the naga forces to date.  I'll assess the general situation here in regards to the naga; as much as I want to commit a full force to move against them, leaving the stronghold open to direct attack from the Horde - or worse - seems less than optimal.$B$BAnyway, Latronicus awaits.  Good work thus far, $n.  Keep it up.$B$BYou're dismissed.",logDesc="Report to Latronicus Moonspear in Feathermoon Stronghold."} end
if not DB[3141] then DB[3141]={id=3141,zoneId=16,name="Loramus",level=57,minLevel=45,giver="Loramus Thalipedes",giverType="NPC",giverId=7783,ender="Loramus Thalipedes",enderType="NPC",enderId=7783,rewardNextId=3508,poiX=3098,poiY=-6361,wowhead="https://www.wowhead.com/wotlk/quest=3141",image="assets/images/quests/placeholder.png",xpDiff=1,desc="So you wish to battle demons? You would do well to listen to my tale. ",logDesc="Listen to Loramus Thalipedes tell his story."} end
if not DB[3161] then DB[3161]={id=3161,zoneId=440,name="Gahz'ridian",level=48,minLevel=43,giver="Marvon Rivetseeker",giverType="NPC",giverId=7771,ender="Marvon Rivetseeker",enderType="NPC",enderId=7771,poiX=-7988,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=3161",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N, I'm a scientist, but also a treasure hunter at heart!$B$BLong ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity. These ornaments are carved out of an element that I call \"Gahz'ridian,\" after the hydra god.$B$BI did find some myself, but I'd like to have some more to study -- maybe you can find some?$B$BI even invented a detector that makes finding the Gahz'ridian a snap! Just put it on, and the search begins! ",logDesc="Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments.",choiceRewards={{id=10827,qty=1},{id=10826,qty=1}}} end
if not DB[3181] then DB[3181]={id=3181,zoneId=51,name="The Horn of the Beast",level=43,minLevel=40,ender="Mountaineer Pebblebitty",enderType="NPC",enderId=3836,rewardNextId=3182,wowhead="https://www.wowhead.com/wotlk/quest=3181",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The gigantic horn has numerous scratches and cracks. An unusual metal object is lodged into the rough surface.$B$BUpon further examination, you notice that the metal is actually a broken axe head. On the metal, the following words are etched:$B$BProperty of Mountaineer Pebblebitty.$B$BWhen you try and dislodge the broken axe head, it shatters into a million pieces.$B$BWoops!",logDesc="Take Margol's Gigantic Horn to Mountaineer Pebblebitty.$B"} end
if not DB[3182] then DB[3182]={id=3182,zoneId=38,name="Proof of Deed",level=43,minLevel=40,giver="Mountaineer Pebblebitty",giverType="NPC",giverId=3836,ender="Curator Thorius",enderType="NPC",enderId=8256,poiX=-6033,poiY=-2495,wowhead="https://www.wowhead.com/wotlk/quest=3182",image="assets/images/quests/placeholder.png",xpDiff=5,money=12000,desc="You expect me to believe a story like that? The real horn would have had my broken axe head still lodged into its surface.$B$BListen, take that obvious fake to Curator Thorius in Ironforge. If he can validate your claim, you will receive a proof of deed. Bring that proof back to me and I'll give you the key to the Searing Gorge.$B$BGet going! ",logDesc="Take Margol's Gigantic Horn to Curator Thorius in Ironforge."} end
if not DB[3201] then DB[3201]={id=3201,zoneId=1537,name="At Last!",level=43,minLevel=40,giver="Curator Thorius",giverType="NPC",giverId=8256,ender="Mountaineer Pebblebitty",enderType="NPC",enderId=3836,poiX=-4654,poiY=-1282,wowhead="https://www.wowhead.com/wotlk/quest=3201",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I can't believe Pebblebitty doubted the authenticity of the horn. Between you and me, I think she's just jealous. I know she really wanted to kill that beast herself, what with the 'incident' and all.$B$BSo you need a proof of deed? After the contribution you just made to the museum, it won't be a problem.$B$B<Curator Thorius begins to fill out a large document.>$B$BThere we go! You can take that back to Pebblebitty.",logDesc="Take the Proof of Deed back to Mountaineer Pebblebitty.",rewards={{id=5396,qty=1}}} end
if not DB[3221] then DB[3221]={id=3221,zoneId=130,name="Speak with Renferrel",level=12,minLevel=10,giver="High Executor Hadrec",giverType="NPC",giverId=1952,ender="Apothecary Renferrel",enderType="NPC",enderId=1937,rewardNextId=1359,poiX=522,poiY=1626,wowhead="https://www.wowhead.com/wotlk/quest=3221",image="assets/images/quests/placeholder.png",xpDiff=1,desc="While you were out helping our deathstalkers, Apothecary Renferrel sent you a summons.  He did not give me details, but he wanted to speak with you about the wolf hearts you had given him.",logDesc="Speak with Apothecary Renferrel at the Sepulcher."} end
if not DB[3241] then DB[3241]={id=3241,zoneId=0,name="<NYI> <TXT><redux> Dreadmist Peak",level=11,minLevel=8,wowhead="https://www.wowhead.com/wotlk/quest=3241",image="assets/images/quests/placeholder.png",desc="Collect the totems from Dreadmist Peak,because it's icky there now and no place for shiny clean totems.",logDesc="Bring them to Tonga Runetotem."} end
if not DB[3261] then DB[3261]={id=3261,zoneId=17,name="Jorn Skyseer",level=18,minLevel=10,giver="Sergra Darkthorn",giverType="NPC",giverId=3338,ender="Jorn Skyseer",enderType="NPC",enderId=3387,rewardNextId=882,poiX=-482,poiY=-2670,wowhead="https://www.wowhead.com/wotlk/quest=3261",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Your time with me is over, $N.  To learn more, you must go to Camp Taurajo to the south and speak with Jorn Skyseer.  He will continue your guidance.",logDesc="Speak with Jorn Skyseer at Camp Taurajo."} end
if not DB[3281] then DB[3281]={id=3281,zoneId=17,name="Stolen Silver",level=18,minLevel=9,giver="Gazrog",giverType="NPC",giverId=3464,ender="Gazrog",enderType="NPC",enderId=3464,poiX=-436,poiY=-2639,wowhead="https://www.wowhead.com/wotlk/quest=3281",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="You may have killed the raptors, but the silver they stole must be recovered!  I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds.  It is likely that they brought our stolen silver there.$B$BGo to this raptor haven and search for the stolen silver.  When you find it, return it to me.",logDesc="Bring the Stolen Silver to Gazrog in the Crossroads.",choiceRewards={{id=11853,qty=1},{id=2694,qty=1}}} end
if not DB[3301] then DB[3301]={id=3301,zoneId=17,name="Mura Runetotem",level=15,minLevel=10,giver="Tonga Runetotem",giverType="NPC",giverId=3448,ender="Mura Runetotem",enderType="NPC",enderId=8385,poiX=-545,poiY=-2673,wowhead="https://www.wowhead.com/wotlk/quest=3301",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies.  Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life.  Perhaps the strange life found here in the Barrens can help her work in Silverpine.$B$BTake a sample of the shells you gathered, and bring it to Mura in Silverpine.  She is staying at the Sepulcher.  With luck, studying the shell will give her the insight she needs to heal that dying place.",logDesc="Speak with Mura Runetotem at the Sepulcher in Silverpine Forest.",choiceRewards={{id=10820,qty=1},{id=10821,qty=1}}} end
if not DB[3321] then DB[3321]={id=3321,zoneId=-121,name="Did You Lose This?",level=50,minLevel=40,giver="Trenton Lighthammer",giverType="NPC",giverId=7804,ender="Trenton Lighthammer",enderType="NPC",enderId=7804,poiX=-7198,poiY=-3766,wowhead="https://www.wowhead.com/wotlk/quest=3321",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have done much for the Order, $N. The sheer dedication it takes to get this far would have turned away any ordinary person. There is no doubt in my mind, or in the mind of Galvan, that you are one of us.$B$BWhich is why I think you deserve a little reward. It is nothing really, just a trinket. You may be familiar with its properties, as I do believe it is what brought you to us in the first place.",logDesc="Wait for Trenton to finish his work.",rewards={{id=10418,qty=1}}} end
if not DB[3341] then DB[3341]={id=3341,zoneId=722,name="Bring the End",level=37,minLevel=33,giver="Andrew Brownell",giverType="NPC",giverId=2308,ender="Andrew Brownell",enderType="NPC",enderId=2308,poiX=1665,poiY=163,wowhead="https://www.wowhead.com/wotlk/quest=3341",image="assets/images/quests/placeholder.png",xpDiff=7,desc="In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious...$B$BThe quilboar of Razorfen Downs have aligned themselves with the Scourge. A Lich named Amnennar the Coldbringer rules them now, using the power of his massive consciousness to control their every move.$B$BAmnennar has a direct telepathic link to Ner'zhul; we must sever this bond, $N. An end must come to the Coldbringer.",logDesc="Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.",rewards={{id=10823,qty=1},{id=10824,qty=1}}} end
if not DB[3361] then DB[3361]={id=3361,zoneId=132,name="A Refugee's Quandary",level=3,minLevel=3,giver="Felix Whindlebolt",giverType="NPC",giverId=8416,ender="Felix Whindlebolt",enderType="NPC",enderId=8416,poiX=-6098,poiY=396,wowhead="https://www.wowhead.com/wotlk/quest=3361",image="assets/images/quests/placeholder.png",xpDiff=5,money=50,desc="We drove the troggs out of Gnomeregan, but then it all went so horribly wrong!  Now our home is completely irradiated, and we gnomes have been scattered all over Dun Morogh.$B$BIn my haste to get away from the radiation, I lost all my personal belongings and tools.  It was the trolls that got them.  They stole my chest, my box, and my bucket of bolts!  They took them back to their camps southwest of Anvilmar.$B$BI'm no adventurer - could you find my things and bring them here to me, please?",logDesc="Bring Felix's Box, Felix's Chest and Felix's Bucket of Bolts to Felix Whindlebolt in Anvilmar."} end
if not DB[3362] then DB[3362]={id=3362,zoneId=440,name="Thistleshrub Valley",level=50,minLevel=45,giver="Tran'rek",giverType="NPC",giverId=7876,ender="Tran'rek",enderType="NPC",enderId=7876,poiX=-7106,poiY=-3777,wowhead="https://www.wowhead.com/wotlk/quest=3362",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="Have you ever seen Thistleshrub Valley? It's a mighty dangerous place, $N.$B$BThose strange beasts there, I don't trust them for a minute! Gnarled thistleshrubs and thistleshrub rootshapers, that's what I think they were called...$B$BAnyhow, I want to get into the valley, but with so many of those thistleshrubs around, there's no way I'm going back there. But here's where you come in -- if you clear some of them out, I just might think about going back. What do you think, $N? Help me out?",logDesc="Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers."} end
if not DB[3363] then DB[3363]={id=3363,zoneId=361,name="Corrupted Songflower",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=3363",image="assets/images/quests/placeholder.png"} end
if not DB[3364] then DB[3364]={id=3364,zoneId=132,name="Scalding Mornbrew Delivery",level=5,minLevel=4,giver="Nori Pridedrift",giverType="NPC",giverId=12738,ender="Durnan Furcutter",enderType="NPC",enderId=836,poiX=-6371,poiY=572,wowhead="https://www.wowhead.com/wotlk/quest=3364",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Gah!  I was supposed to get this delicious scalding mornbrew to Durnan Furcutter inside Anvilmar a while ago now, but I had to deliver one to Grelin here first.  I'll never make it to Anvilmar before the brew runs cold!$B$BYou look fast.  Maybe you can make it.  This cup will only stay hot for a few more minutes, and Durnan didn't order \"chilly\" mornbrew, so get going.  Anvilmar is to the northeast, a settlement dug into the mountain.$B$BThanks, $N, and don't forget to bring me back my mug!",logDesc="Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold!"} end
if not DB[3365] then DB[3365]={id=3365,zoneId=132,name="Bring Back the Mug",level=5,minLevel=4,giver="Durnan Furcutter",giverType="NPC",giverId=836,ender="Nori Pridedrift",enderType="NPC",enderId=12738,poiX=-6056,poiY=385,wowhead="https://www.wowhead.com/wotlk/quest=3365",image="assets/images/quests/placeholder.png",xpDiff=5,money=50,desc="Now that hit the spot!  Nothing like a piping hot - nay, SCALDING mornbrew on a cold winter's day to warm your cackles of yer soul.$B$BHere ya go $N - be a pal and take this empty mug back to Nori for me, would ya now.",logDesc="Return Nori's Mug to Nori Pridedrift in Coldridge Valley."} end
if not DB[3366] then DB[3366]={id=3366,zoneId=718,name="The Glowing Shard",level=25,minLevel=15,wowhead="https://www.wowhead.com/wotlk/quest=3366",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.$B$BMaybe you should see if anyone in Ratchet can tell you more about this strange shard.",logDesc="Travel to Ratchet to find the meaning behind the Nightmare Shard."} end
if not DB[3367] then DB[3367]={id=3367,zoneId=51,name="Suntara Stones",level=46,minLevel=40,giver="Dorius Stonetender",giverType="NPC",giverId=8284,rewardNextId=3368,poiX=-7007,poiY=-1749,wowhead="https://www.wowhead.com/wotlk/quest=3367",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Dorius groans.>$B$BI'm badly injured, $r. Feel... light headed... World spinning... Bleeding... internally.$B$BI must get back to Ironforge. Help me, $N.$B",logDesc="Help Dorius get back to Ironforge.$B"} end
if not DB[3368] then DB[3368]={id=3368,zoneId=51,name="Suntara Stones",level=46,minLevel=40,ender="Curator Thorius",enderType="NPC",enderId=8256,rewardNextId=3371,wowhead="https://www.wowhead.com/wotlk/quest=3368",image="assets/images/quests/placeholder.png",xpDiff=5,money=13000,desc="Brother,$B$BIf you are reading this letter, I am no more. How it got to you, I do not know, but thank and reward the ones responsible.$B$BAbout the stones: They exist and the Dark Irons have them in their possession. Their leader, Lathoric the Black, is using the power of the stones to enslave my excavation team. They were taken to the cauldron. Their minds are twisted, working night and day to complete something called Obsidion.$B$BHelp them, brother. It is the final wish of a dead man.$B$B-Dorius$B",logDesc="Take the Singed Letter to Thorius in Ironforge. He is in the Hall of Explorers."} end
if not DB[3369] then DB[3369]={id=3369,zoneId=17,name="In Nightmares",level=25,minLevel=10,giver="Falla Sagewind",giverType="NPC",giverId=8418,ender="Arch Druid Hamuul Runetotem",enderType="NPC",enderId=5769,poiX=-602,poiY=-2260,wowhead="https://www.wowhead.com/wotlk/quest=3369",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.$B$BI do not wish to alarm you, $N, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can.$B$BHamuul Runetotem on Elder Rise is who you need to find. Head to Thunder Bluff. I cannot say more. ",logDesc="Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise.",choiceRewards={{id=10657,qty=1},{id=10658,qty=1}}} end
if not DB[3370] then DB[3370]={id=3370,zoneId=17,name="In Nightmares",level=25,minLevel=10,giver="Falla Sagewind",giverType="NPC",giverId=8418,ender="Mathrengyl Bearwalker",enderType="NPC",enderId=4217,poiX=-602,poiY=-2260,wowhead="https://www.wowhead.com/wotlk/quest=3370",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.$B$BI do not wish to alarm you, $N, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can... $B$BMathrengyl Bearwalker in the Cenarion Circle is who you need to find. Head to Darnassus. I cannot say more.",logDesc="Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus.",choiceRewards={{id=10657,qty=1},{id=10658,qty=1}}} end
if not DB[3371] then DB[3371]={id=3371,zoneId=1537,name="Dwarven Justice",level=46,minLevel=40,giver="Curator Thorius",giverType="NPC",giverId=8256,ender="Dying Archaeologist",enderType="NPC",enderId=8417,rewardNextId=3372,poiX=-4654,poiY=-1282,wowhead="https://www.wowhead.com/wotlk/quest=3371",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There is an empty, vacuous hole, where my heart used to be, $N. The loss of Dorius is not one that I will soon recover from. I must see his final wish through - the perpetrators of this cold blooded murder must be brought to justice.$B$BReturn to the Searing Gorge and fulfill his last request: Free his men. The Dark Iron dwarves force their slaves to work in a sweltering mine called the Slag Pits. Search there for Dorius' men.",logDesc="Return to the Searing Gorge and find Dorius's archaeology unit. "} end
if not DB[3372] then DB[3372]={id=3372,zoneId=51,name="Release Them",level=46,minLevel=40,giver="Dying Archaeologist",giverType="NPC",giverId=8417,poiX=-6480,poiY=-1241,wowhead="https://www.wowhead.com/wotlk/quest=3372",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Release them, $r. Even after their bodies give out, the power of the Suntara forces them to complete their tasks.$B$BThe altar of Suntara is the key. Go northwest; in the hills above the cave... Twilight's Hammer guard a relic. Retrieve it and place it on the altar of Suntara.$B$B<The dying archaeologist collapses.>",logDesc="Find the Mysterious Artifact being guarded by the Twilight's Hammer Idolaters in the northwest quadrant of the Searing Gorge and bring it to the Altar of Suntara in the Slag Pit.$B"} end
if not DB[3373] then DB[3373]={id=3373,zoneId=1417,name="The Essence of Eranikus",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=3373",image="assets/images/quests/placeholder.png",xpDiff=3,desc="As you touch the gem, a deep voice resonates in your mind.$B$B\"Mortal, heed this plea.  I am Eranikus of the Green Dragonflight, keeper of this accursed temple.  My charge to ensure that the trolls never again bring forth their abomination of a god has for now ended in failure.  As I imbue this gem with part of my essence, I sense my grip on the Dream twisting into chaos.  Please - place this gem into the essence font in my lair, and let our magic there purge the taint from my psyche so that I may rest.\"",logDesc="Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.",rewards={{id=10455,qty=1}}} end
if not DB[3374] then DB[3374]={id=3374,zoneId=8,name="The Essence of Eranikus",level=55,minLevel=48,ender="Itharius",enderType="NPC",enderId=5353,wowhead="https://www.wowhead.com/wotlk/quest=3374",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You engage the Oathstone, and Itharius speaks directly to your mind through the stone.$B$B\"By accepting the charge placed in this Oathstone, you agree to aid my cause and the cause of Ysera's Dragonflight in redeeming the corrupted soul of Eranikus.  The first sacrifice, one of many you and I will no doubt make, will be to relinquish the gem to me that has chained what free-willed part of Eranikus' psyche remains.\"$B$B\"Do this $N, and we will work together to redeem a soul worthy of redemption.\"",logDesc="Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows.  It is there that you will make your choice to aid Ysera's Dragonflight or not."} end
if not DB[3375] then DB[3375]={id=3375,zoneId=1517,name="Replacement Phial",level=42,minLevel=37,giver="Talvash del Kissel",giverType="NPC",giverId=6826,ender="Talvash del Kissel",enderType="NPC",enderId=6826,poiX=-4588,poiY=-1001,wowhead="https://www.wowhead.com/wotlk/quest=3375",image="assets/images/quests/placeholder.png",desc="Um... you need another phial of scrying?  You're kidding, right?  What did you do with the first one?!  We have a lot of work ahead of us here, $r.  Those phials don't grow on trees!  Actually, I wish they did, because I'd go there and pick one off since I don't have another one!!$B$Bin order to make you one, I need the following: a mana potion, a piece of coal, and some sweet nectar.  Don't ask why, just bring me what I ask and I'll make you a new one.",logDesc="Bring a Mana Potion, Coal, and Sweet Nectar to Talvash del Kissel in Ironforge to get a replacement for Talvash's Phial of Scrying.",rewards={{id=7667,qty=1}}} end
if not DB[3376] then DB[3376]={id=3376,zoneId=220,name="Break Sharptusk!",level=5,minLevel=3,giver="Brave Windfeather",giverType="NPC",giverId=3209,ender="Brave Windfeather",enderType="NPC",enderId=3209,poiX=-2893,poiY=-240,wowhead="https://www.wowhead.com/wotlk/quest=3376",image="assets/images/quests/placeholder.png",xpDiff=7,desc="$N - I have heard of you, newcomer.  Perhaps it is you that will help us, where others have failed.$B$BWe tauren have carved a home out of this land, but not without a cost.  The Bristleback quilboars of Brambleblade Ravine, led by Chief Sharptusk Thornmantle, have made our lives difficult with their continued war against us.  I charge you to bring me the chief's head!$B$BHe will be found in the ravine to the east in their makeshift village.",logDesc="Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa.",choiceRewards={{id=10635,qty=1},{id=10636,qty=1}}} end
if not DB[3377] then DB[3377]={id=3377,zoneId=51,name="Prayer to Elune",level=50,minLevel=40,giver="Zamael Lunthistle",giverType="NPC",giverId=8436,ender="Zamael Lunthistle",enderType="NPC",enderId=8436,rewardNextId=3378,poiX=-6491,poiY=-983,wowhead="https://www.wowhead.com/wotlk/quest=3377",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Will you assist me, mortal? Hear my tale.",logDesc="Hear Zamael tell his tale."} end
if not DB[3378] then DB[3378]={id=3378,zoneId=51,name="Prayer to Elune",level=50,minLevel=40,giver="Zamael Lunthistle",giverType="NPC",giverId=8436,ender="Astarii Starseeker",enderType="NPC",enderId=4090,poiX=-6491,poiY=-983,wowhead="https://www.wowhead.com/wotlk/quest=3378",image="assets/images/quests/placeholder.png",xpDiff=6,money=14500,desc="Will you assist me, mortal? Will you find the prayer to Elune?$B$BAs I stated, the prayer was etched onto a golden tablet. One of these idol worshipping scoundrels must have it on their person.$B$BIf you do recover my prayer, take it to Astarii Starseeker in Darnassus. It matters little that my faith has been rekindled after the countless malevolent actions that I have taken against this world and its inhabitants, but my prayer must be heard. Absolution is the last thing I expect.",logDesc="Find the Prayer to Elune and take it to Astarii Starseeker in Darnassus.$B",choiceRewards={{id=10745,qty=1},{id=10746,qty=1}}} end
if not DB[3379] then DB[3379]={id=3379,zoneId=-264,name="Shadoweaver",level=50,minLevel=40,giver="Nilith Lokrav",giverType="NPC",giverId=8439,ender="Nilith Lokrav",enderType="NPC",enderId=8439,rewardNextId=3385,poiX=-7215,poiY=-1237,wowhead="https://www.wowhead.com/wotlk/quest=3379",image="assets/images/quests/placeholder.png",xpDiff=5,money=14500,desc="The spiders of the Searing Gorge are an invaluable source of shadow silk. As you know, shadow silk is highly sought after by the artisans of our trade.$B$BRecently, a group of poachers has encroached upon these lands, carelessly slaying spiders en masse without so much as a thought as to the long term effect of their actions. The first task I ask of you, then, is a simple one: Find them... and end them.$B$BBegin your search to the north.$B$BIf you require assistance, speak with Raze.",logDesc="Kill the group of Shadow Silk Poachers that wander the Searing Gorge. Nilith has reason to believe that there are five of them that need to be exterminated. Return to Nilith in the Searing Gorge when this task is complete.$B",rewards={{id=10461,qty=1}}} end
if not DB[3380] then DB[3380]={id=3380,zoneId=1417,name="The Sunken Temple",level=51,minLevel=46,giver="Witch Doctor Uzer'i",giverType="NPC",giverId=8115,ender="Marvon Rivetseeker",enderType="NPC",enderId=7771,rewardNextId=3444,poiX=-4376,poiY=270,wowhead="https://www.wowhead.com/wotlk/quest=3380",image="assets/images/quests/placeholder.png",xpDiff=4,desc="There are restless spirits in this world, $N. There are spirits that have been tainted by their isolation, bound to an ancient evil...$B$BI have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.$B$BIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. He has studied many ancient areas of the world, and was last known to have left his home in Ratchet to study the troll ruins in Tanaris.",logDesc="Find Marvon Rivetseeker in Tanaris."} end
if not DB[3381] then DB[3381]={id=3381,zoneId=16,name="A Meeting with the Master",level=48,minLevel=45,wowhead="https://www.wowhead.com/wotlk/quest=3381",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ah, a young $r come to speak to Sanath. What a wonderful day! I am so honored to have you grace me with your presence. Thank you!$B$BPlease... do not be so arrogant to assume my sarcasm was a compliment. Let us get one thing straight: I don't like you. But this little conversation doesn't have anything to do with us--it has to do with my master.$B$BBring me a couple hippogryph feathers for my arrows and I'll give you leave to see him. He's asked that I send adventurers to him if they proved worthy enough.",logDesc="Bring 2 Undamaged Hippogryph Feathers to Sanath Lim-yo in Azshara if you wish to speak to his master."} end
if not DB[3382] then DB[3382]={id=3382,zoneId=16,name="A Crew Under Fire",level=57,minLevel=48,giver="Captain Vanessa Beltis",giverType="NPC",giverId=8380,ender="Captain Vanessa Beltis",enderType="NPC",enderId=8380,poiX=2374,poiY=-5968,wowhead="https://www.wowhead.com/wotlk/quest=3382",image="assets/images/quests/placeholder.png",desc="We were just off the coast looking for a safe haven to make anchor. The sun hadn't been down for more than an hour when they attacked... those damned naga!$B$BI'm not sure what they were looking for, but it's clear they didn't find it--they've already come back once. A couple of my scouts are on watch at the entrance of the valley to give us fair warning when the next attack comes.$B$BI'm sorry you've come along now, $N, but it's out of my hands.$B$BAre you ready for the fight of your life?",logDesc="Defend Captain Vanessa Beltis, her crew and the Horizon Scout's passengers against the naga attack. Captain Vanessa Beltis must survive."} end
if not DB[3383] then DB[3383]={id=3383,zoneId=16,name="<UNUSED>",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=3383",image="assets/images/quests/placeholder.png",xpDiff=5} end
if not DB[3384] then DB[3384]={id=3384,zoneId=16,name="<UNUSED>",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=3384",image="assets/images/quests/placeholder.png",xpDiff=1} end
if not DB[3385] then DB[3385]={id=3385,zoneId=-264,name="The Undermarket",level=50,minLevel=40,giver="Nilith Lokrav",giverType="NPC",giverId=8439,ender="Nilith Lokrav",enderType="NPC",enderId=8439,rewardNextId=3402,poiX=-7215,poiY=-1237,wowhead="https://www.wowhead.com/wotlk/quest=3385",image="assets/images/quests/placeholder.png",xpDiff=5,desc="They call themselves the Undermarket: Cutthroat traders that will sell, move, trade and do just about anything for the right price.$B$BIt gets worse, $N. They have set up a base of operations here in the Searing Gorge. Trade Master Kovic is heading up the operation and has close ties with the Dark Iron dwarves of the region.$B$BWe must strike hard and send a message to their leadership. Slay Trade Master Kovic and his minion Clunk. Bring back his trader's satchel when the job is done.$B$BTo the Cauldron!",logDesc="Slay Trade Master Kovic and his minion Clunk. Retrieve the Trader's Satchel from his corpse and return it to Nilith.$B",rewards={{id=10462,qty=1},{id=10479,qty=1}}} end
if not DB[3401] then DB[3401]={id=3401,zoneId=16,name="<UNUSED>",level=48,minLevel=53,wowhead="https://www.wowhead.com/wotlk/quest=3401",image="assets/images/quests/placeholder.png"} end
if not DB[3402] then DB[3402]={id=3402,zoneId=-264,name="The Undermarket",level=50,minLevel=40,giver="Nilith Lokrav",giverType="NPC",giverId=8439,ender="Vizzklick",enderType="NPC",enderId=6568,poiX=-7215,poiY=-1237,wowhead="https://www.wowhead.com/wotlk/quest=3402",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="I want you to personally deliver the news of Kovic's defeat to Vizzklick in Gadgetzan. He will be so happy to hear that Kovic is dead that I'm certain he'll give you some grand reward.",logDesc="Speak with Vizzklick in Gadgetzan.$B",rewards={{id=10463,qty=1}}} end
