if not DB[3441] then DB[3441]={id=3441,zoneId=51,name="Divine Retribution",level=48,minLevel=40,giver="Kalaran Windblade",giverType="NPC",giverId=8479,ender="Kalaran Windblade",enderType="NPC",enderId=8479,poiX=-6680,poiY=-1194,wowhead="https://www.wowhead.com/wotlk/quest=3441",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hear my tale, adventurer.",logDesc="Listen as Kalaran Windblade tells his story."} end
if not DB[3442] then DB[3442]={id=3442,zoneId=51,name="The Flawless Flame",level=48,minLevel=40,giver="Kalaran Windblade",giverType="NPC",giverId=8479,ender="Kalaran Windblade",enderType="NPC",enderId=8479,rewardNextId=3443,poiX=-6680,poiY=-1194,wowhead="https://www.wowhead.com/wotlk/quest=3442",image="assets/images/quests/placeholder.png",xpDiff=5,money=14000,desc="You have made the right decision, $N.$B$BWe must strike where we will do the most damage: the four sentry towers.$B$BWith the four towers in flames, we can initiate an offensive before they have time to react.$B$BYou will need the proper tool to set the towers ablaze. To make the tool requires some materials.$B$BBring me four hearts of flame and four golem oil and I shall craft the torch of flawless flame.$B$BThe golems and elementals in these lands should be your first target.",logDesc="Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade."} end
if not DB[3443] then DB[3443]={id=3443,zoneId=51,name="Forging the Shaft",level=48,minLevel=40,giver="Kalaran Windblade",giverType="NPC",giverId=8479,ender="Kalaran Windblade",enderType="NPC",enderId=8479,rewardNextId=3452,poiX=-6680,poiY=-1194,wowhead="https://www.wowhead.com/wotlk/quest=3443",image="assets/images/quests/placeholder.png",xpDiff=5,money=14000,desc="To hold the flawless flame, we will need a shaft and a casing. You must first find a suitable shaft.$B$BThe Dark Iron taskmasters and slavers of the cauldron use weapons of enchanted thorium, an extremely sturdy alloy. If you bring me eight thorium plated daggers, I can break the alloy down and reforge a shaft.$B",logDesc="Bring 8 Thorium Plated Daggers to Kalaran Windblade."} end
if not DB[3444] then DB[3444]={id=3444,zoneId=440,name="The Stone Circle",level=51,minLevel=46,giver="Marvon Rivetseeker",giverType="NPC",giverId=7771,ender="Marvon Rivetseeker",enderType="NPC",enderId=7771,poiX=-7988,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=3444",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I once entered the foreboding chambers of the Sunken Temple. The evil in that place penetrates all that enter; I barely managed to find my way out, wading through the ooze that now covers the floors. All I can remember is stumbling through a large circular room, filled with serpent statues...$B$BRecently, I discovered a round stone that appeared to have the same serpent symbol imprinted on it. I had it packed up and shipped to my workshop in Ratchet. Retrieve it, and I might be able to tell you more.",logDesc="Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet."} end
if not DB[3445] then DB[3445]={id=3445,zoneId=357,name="The Sunken Temple",level=51,minLevel=46,giver="Angelas Moonbreeze",giverType="NPC",giverId=7900,ender="Marvon Rivetseeker",enderType="NPC",enderId=7771,rewardNextId=3444,poiX=-4480,poiY=3230,wowhead="https://www.wowhead.com/wotlk/quest=3445",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.$B$BIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. Much like Troyas and I, he has studied many ancient areas of the world. He was last known to have left his home in Ratchet to study the troll ruins in Tanaris.$B$BGood luck finding him; he hasn't been heard from in some time.",logDesc="Find Marvon Rivetseeker in Tanaris."} end
if not DB[3446] then DB[3446]={id=3446,zoneId=1417,name="Into the Depths",level=51,minLevel=46,giver="Marvon Rivetseeker",giverType="NPC",giverId=7771,poiX=-7988,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=3446",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Inside the temple, I found a circular room with six balconies, each one with a serpent statue on the edge. Curious, I pushed one of them to see what would happen, and it was a trap! I nearly fell to my death from the explosion. Laying there on the ledge, I looked down and noticed that there was another statue at the base of the room; an altar of sorts... Hakkar, I think it was called.$B$BI think that this altar is the secret -- you must bring this token to the altar in the Sunken Temple.",logDesc="Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows."} end
if not DB[3447] then DB[3447]={id=3447,zoneId=1417,name="Secret of the Circle",level=51,minLevel=46,giver="Marvon Rivetseeker",giverType="NPC",giverId=7771,poiX=-7988,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=3447",image="assets/images/quests/placeholder.png",xpDiff=7,desc="My memories are cloudy, but I will tell you what I can. The circle of statues in the Sunken Temple, while dangerous, I believe that they hold the secret to unlock an even greater treasure.$B$BFrom the main altar, I was able to activate a series of lights. I think that if you can uncover what these lights mean, you might be able to unlock whatever secrets are hiding in this room.$B$BI warn you though, $N. Great evil lies in the temple. It's likely that anything valuable will be fervently guarded...",logDesc="Travel into the Sunken Temple and discover the secret hidden in the circle of statues.",rewards={{id=10773,qty=1}}} end
if not DB[3448] then DB[3448]={id=3448,zoneId=1537,name="Passing the Burden",level=52,minLevel=45,giver="Historian Karnik",giverType="NPC",giverId=2916,ender="Tymor",enderType="NPC",enderId=8507,rewardNextId=3449,poiX=-4632,poiY=-1327,wowhead="https://www.wowhead.com/wotlk/quest=3448",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I've recently been handed the responsibility of investigating Azshara--a once beautiful area the elves called home. This would be back when they practiced magic. It's now a more dangerous place than it is beautiful, but that doesn't stop us from turning over every stone for answers to our past.$B$BA companion of mine named Tymor offered to help me investigate the area since he takes a particular interest in such things.$B$BHe owns a small place to the right of the Hall of Mysteries here in the city.",logDesc="Speak to Tymor in Ironforge."} end
if not DB[3449] then DB[3449]={id=3449,zoneId=1537,name="Arcane Runes",level=52,minLevel=45,giver="Tymor",giverType="NPC",giverId=8507,ender="Pilot Xiggs Fuselighter",enderType="NPC",enderId=8392,rewardNextId=3461,poiX=-4595,poiY=-958,wowhead="https://www.wowhead.com/wotlk/quest=3449",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Magic was once as revered as Elune herself to some elves. Some of their most powerful mages created runes and tablets citing rules of the arcane and insights into their findings. They would leave these for all to ponder in public places.$B$BI would very much like rubbings of these runes from the Ruins of Eldarath. I have a kit for you to make the rubbings with, but it will be up to you to find them. Be careful though, the Explorer's League isn't the only one interested in Eldarath.",logDesc="Using the Drawing Kit, make rubbings of the Rune of Beth'Amara, the Rune of Jin'yael, the Rune of Markri, and the Rune of Sael'hai before heading to the small island off of the southern peninsula of Azshara and signaling Pilot Xiggs Fuselighter to pick them up."} end
if not DB[3450] then DB[3450]={id=3450,zoneId=1537,name="An Easy Pickup",level=52,minLevel=45,giver="Tymor",giverType="NPC",giverId=8507,ender="Xiggs Fuselighter",enderType="NPC",enderId=8517,rewardNextId=3451,poiX=-4595,poiY=-958,wowhead="https://www.wowhead.com/wotlk/quest=3450",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I want the rubbings delivered to my tower, but there's no need to have you go all the way there. I'll just have them air-lifted out of Azshara.$B$BXiggs Fuselighter owes me a favor or two and will be in the area soon--he's signed on to patrol the coast. Speak to him before you leave. He can give you a flare gun to signal him with. When you have the rubbings, just head to wherever he tells you and then give them to him so he can get them to my tower safely. He should be in the hangar in the Military Ward.",logDesc="Speak to Xiggs Fuselighter in Ironforge."} end
if not DB[3451] then DB[3451]={id=3451,zoneId=1537,name="Signal for Pickup",level=52,minLevel=45,giver="Xiggs Fuselighter",giverType="NPC",giverId=8517,ender="Xiggs Fuselighter",enderType="NPC",enderId=8517,poiX=-5068,poiY=-1274,wowhead="https://www.wowhead.com/wotlk/quest=3451",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Ah, so Tymor sent you, huh? Yeah, I owe him a favor or two. What's that? Why, that little devil. Yeah, I can help him out with that. So you'll need a flare gun and a location... easy enough.$B$BThere's a small island off the southern peninsula of Azshara that we've made a landing pad on. You take this flare gun, and use it there. I'll see your signal and come by to pick up this... whatever it is he wants.",logDesc="Speak to Xiggs Fuselighter and get a Standard Issue Flare Gun from him in Ironforge.",rewards={{id=10444,qty=1}}} end
if not DB[3452] then DB[3452]={id=3452,zoneId=51,name="The Flame's Casing",level=50,minLevel=40,giver="Kalaran Windblade",giverType="NPC",giverId=8479,ender="Kalaran Windblade",enderType="NPC",enderId=8479,rewardNextId=3453,poiX=-6680,poiY=-1194,wowhead="https://www.wowhead.com/wotlk/quest=3452",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="We need one final piece to form the torch.$B$BIn the mountains to the northwest you will find a large encampment of Twilight's Hammer. It is rumored that they carry symbols and idols that pay homage to their god. These symbols and idols could carry sufficient enchantment to form a magical casing. Bring me a single symbol of Ragnaros and I will try to extract the magic from the item to create the casing.",logDesc="Find and return a Symbol of Ragnaros to Kalaran Windblade."} end
if not DB[3453] then DB[3453]={id=3453,zoneId=51,name="The Torch of Retribution",level=50,minLevel=40,giver="Kalaran Windblade",giverType="NPC",giverId=8479,ender="Kalaran Windblade",enderType="NPC",enderId=8479,rewardNextId=3454,poiX=-6680,poiY=-1194,wowhead="https://www.wowhead.com/wotlk/quest=3453",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Give me a moment to combine the pieces and apply the necessary enchantments.$B",logDesc="Wait for Kalaran Windblade to complete the Torch of Retribution.$B"} end
if not DB[3454] then DB[3454]={id=3454,zoneId=51,name="The Torch of Retribution",level=50,minLevel=40,giver="Kalaran Windblade",giverType="NPC",giverId=8479,poiX=-6680,poiY=-1194,wowhead="https://www.wowhead.com/wotlk/quest=3454",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The torch must now be bound to its owner. Pick up the torch, $N. ",logDesc="Take the Torch of Retribution.",rewards={{id=10515,qty=1}}} end
if not DB[3461] then DB[3461]={id=3461,zoneId=1537,name="Return to Tymor",level=52,minLevel=45,giver="Pilot Xiggs Fuselighter",giverType="NPC",giverId=8392,ender="Tymor",enderType="NPC",enderId=8507,wowhead="https://www.wowhead.com/wotlk/quest=3461",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward. Just go knockin' and make sure he pays you good. This place ain't no picnic... that's for sure.$B$BThanks again for helping him out though, and good luck.$B$BOh, and I don't need the drawing kit. Why don't you just bring it back to Tymor when you go to see him?",logDesc="Return Tymor's Drawing Kit to him in Ironforge.",choiceRewards={{id=10707,qty=1},{id=10708,qty=1}}} end
if not DB[3462] then DB[3462]={id=3462,zoneId=51,name="Squire Maltrake",level=50,minLevel=40,giver="Kalaran Windblade",giverType="NPC",giverId=8479,ender="Squire Maltrake",enderType="NPC",enderId=8509,rewardNextId=3463,poiX=-6680,poiY=-1194,wowhead="https://www.wowhead.com/wotlk/quest=3462",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Speak with my envoy, Squire Maltrake. He will further instruct you as to the use of the Torch of Retribution.",logDesc="Speak with Squire Maltrake."} end
if not DB[3463] then DB[3463]={id=3463,zoneId=51,name="Set Them Ablaze!",level=52,minLevel=40,giver="Squire Maltrake",giverType="NPC",giverId=8509,ender="Squire Maltrake",enderType="NPC",enderId=8509,poiX=-6680,poiY=-1197,wowhead="https://www.wowhead.com/wotlk/quest=3463",image="assets/images/quests/placeholder.png",xpDiff=7,money=23000,desc="Listen well, $N. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue.$B$BWhile they are ablaze, no guard or sentry unit can inhabit the watch posts and thus, their first line of defense is nullified.$B$BYou must enter each tower and use the Torch of Retribution within their fortifications. Beware the lookouts posted by the Dark Irons, $N.",logDesc="Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings. $B",choiceRewards={{id=10742,qty=1},{id=10743,qty=1},{id=10744,qty=1}}} end
if not DB[3481] then DB[3481]={id=3481,zoneId=51,name="Trinkets...",level=50,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=3481",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The chest appears locked.",logDesc="Open the chest.",rewards={{id=10569,qty=1}}} end
if not DB[3482] then DB[3482]={id=3482,zoneId=0,name="<NYI> <TXT> The Pocked Black Box",level=35,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=3482",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This is the horde version of the black box quest.",logDesc="Take this box to Kravel."} end
if not DB[3483] then DB[3483]={id=3483,zoneId=1537,name="Signal for Pickup",level=52,minLevel=45,giver="Xiggs Fuselighter",giverType="NPC",giverId=8517,ender="Xiggs Fuselighter",enderType="NPC",enderId=8517,poiX=-5068,poiY=-1274,wowhead="https://www.wowhead.com/wotlk/quest=3483",image="assets/images/quests/placeholder.png",rewards={{id=10444,qty=1}}} end
if not DB[3501] then DB[3501]={id=3501,zoneId=4,name="Everything Counts In Large Amounts",level=55,minLevel=45,giver="Kum'isha the Collector",giverType="NPC",giverId=7363,ender="Kum'isha the Collector",enderType="NPC",enderId=7363,rewardNextId=3502,poiX=-11363,poiY=-2983,wowhead="https://www.wowhead.com/wotlk/quest=3501",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Although you may never find a flawless sphere of draenethyst, you will undoubtedly uncover various imperfect fragments of the draenethyst in your exploration of these lands.$B$BWhile it is doubtful that Kum'isha will be able to use the flawed fragments to return home, the pieces may serve other, useful purposes for the draenei.$B$BReturn any piece of flawed draenethyst fragments that you may find and I shall reward you.",logDesc="Bring Kum'isha Imperfect Draenethyst Fragments and be rewarded for each one you turn in.$B",rewards={{id=12122,qty=1}}} end
if not DB[3502] then DB[3502]={id=3502,zoneId=4,name="One Draenei's Junk...",level=55,minLevel=45,giver="Kum'isha the Collector",giverType="NPC",giverId=7363,ender="Kum'isha the Collector",enderType="NPC",enderId=7363,poiX=-11363,poiY=-2983,wowhead="https://www.wowhead.com/wotlk/quest=3502",image="assets/images/quests/placeholder.png",desc="Well, after that display of voracious greed, I feel nauseous.$B$BRegardless, I shall not dwell too long on your material addiction.$B$BFor each imperfect draenethyst fragment you turn in, I shall reward you with more junk. My junk heap gets smaller while your junk heap gets larger. On Draenor we call this a 'win-win' situation.$B",logDesc="Bring Kum'isha Imperfect Draenethyst Fragments. Any form of monster in the Blasted Lands could be carrying a fragment.$B",rewards={{id=12122,qty=1}}} end
if not DB[3503] then DB[3503]={id=3503,zoneId=16,name="Meeting with the Master",level=55,minLevel=45,giver="Sanath Lim-yo",giverType="NPC",giverId=8395,ender="Sanath Lim-yo",enderType="NPC",enderId=8395,poiX=3648,poiY=-4703,wowhead="https://www.wowhead.com/wotlk/quest=3503",image="assets/images/quests/placeholder.png"} end
if not DB[3504] then DB[3504]={id=3504,zoneId=1637,name="Betrayed",level=53,minLevel=44,giver="Belgrom Rockmaul",giverType="NPC",giverId=4485,ender="Ag'tor Bloodfist",enderType="NPC",enderId=8576,rewardNextId=3505,poiX=1954,poiY=-4736,wowhead="https://www.wowhead.com/wotlk/quest=3504",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Betraying, thieving woman! That's what I call her--that's all she'll ever be!$B$BI may have made a grave mistake, $N. I trusted a blood elf. What's worse, I trusted a woman!$B$BShe claimed Azshara would hold great riches... powerful items. I simply send some warriors with her to protect her and I would be rewarded. Well, look who's the fool--she's killed them all.$B$BI want vengeance, $N, but I can't afford to send anyone else. Find Ag'tor at Valormok, north of the Haldarr Encampment. He'll tell you more.",logDesc="Deliver the Sealed Letter to Ag'tor to Ag'tor Bloodfist in Azshara."} end
if not DB[3505] then DB[3505]={id=3505,zoneId=1637,name="Betrayed",level=53,minLevel=44,giver="Ag'tor Bloodfist",giverType="NPC",giverId=8576,rewardNextId=3506,poiX=3601,poiY=-4406,wowhead="https://www.wowhead.com/wotlk/quest=3505",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I thought as much.$B$BWe start our crusade against her workers along the southern bluffs on the northern peninsula of Azshara. Kill them with bloody rage--let them know they've betrayed the wrong allies.$B$BDo not concern yourself with her yet--she spends most of her time with her bodyguards searching Azshara. It would be prudent after you've slain her workers to find her personal camp. Scouting out where we can attack her would be wise. Perhaps there is something there we can use to provoke her.",logDesc="Kill 10 Blood Elf Reclaimers, and 10 Blood Elf Surveyors before seeking out Magus Rimtori's camp. Once you've found it, look for something that might be important to her that can be used to draw her into a fight."} end
if not DB[3506] then DB[3506]={id=3506,zoneId=1637,name="Betrayed",level=56,minLevel=44,ender="Ag'tor Bloodfist",enderType="NPC",enderId=8576,rewardNextId=3507,wowhead="https://www.wowhead.com/wotlk/quest=3506",image="assets/images/quests/placeholder.png",xpDiff=4,desc="A few more moments of thought brings a few ideas to mind, one of which brings a smile to your face: perhaps destroying the crystals would upset the blood elf responsible for the slaughter of so many orcs and the betrayal of Belgrom?$B$BYou continue to decipher more of the script and pictures and realize that one of the crystals is tied to the creator of the circle--the others are tied to something far more sinister.$B$BYou close the book and begin to decide which crystal to destroy. ",logDesc="Destroy the arcane focusing crystal tied to Magus Rimtori and then slay her. Afterwards, take the Head of Magus Rimtori to Ag'tor Bloodfist in Azshara."} end
if not DB[3507] then DB[3507]={id=3507,zoneId=1637,name="Betrayed",level=56,minLevel=44,giver="Ag'tor Bloodfist",giverType="NPC",giverId=8576,ender="Belgrom Rockmaul",enderType="NPC",enderId=4485,poiX=3601,poiY=-4406,wowhead="https://www.wowhead.com/wotlk/quest=3507",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Return to Belgrom in Orgrimmar. He will want to see her head for himself! We'll return there shortly.$B$BAh, this is indeed a good day. Thank you for your help, $N.",logDesc="Speak to Belgrom Rockmaul in Orgrimmar.",choiceRewards={{id=10709,qty=1},{id=11120,qty=1}}} end
if not DB[3508] then DB[3508]={id=3508,zoneId=16,name="Breaking the Ward",level=58,minLevel=45,giver="Loramus Thalipedes",giverType="NPC",giverId=7783,ender="Loramus Thalipedes",enderType="NPC",enderId=7783,rewardNextId=3509,poiX=3098,poiY=-6361,wowhead="https://www.wowhead.com/wotlk/quest=3508",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You are foolhardy, $N. It is an admirable quality of your kind - to blindly enter battle when you have little to no chance of success. I will assist you, if only to see just one of Razelikh's minions fall.$B$BTo break the ward placed over Razelikh's subordinates will take time and require the acquisition of rare artifacts.$B$BBe still, I must first perform the enlightenment ritual. The information I gather will assist me in forging weapons of great power.",logDesc="Wait for Loramus to complete the enlightenment spell."} end
if not DB[3509] then DB[3509]={id=3509,zoneId=16,name="The Name of the Beast",level=58,minLevel=45,giver="Loramus Thalipedes",giverType="NPC",giverId=7783,ender="Lord Arkkoroc",enderType="NPC",enderId=6134,rewardNextId=3510,poiX=3098,poiY=-6361,wowhead="https://www.wowhead.com/wotlk/quest=3509",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There is only one way to harm the demon lord and his minions. A weapon of power must be forged bearing his true name.$B$BWhen such a weapon is forged, the demon and all under his command are vulnerable.$B$BA lesser deity resides in Azshara: Lord Arkkoroc. You must seek him out but be warned, his minions will stop at nothing to destroy you if you are discovered.$B$BUndoubtedly, you will have to pay a price for such information. ",logDesc="Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran."} end
if not DB[3510] then DB[3510]={id=3510,zoneId=16,name="The Name of the Beast",level=58,minLevel=45,giver="Lord Arkkoroc",giverType="NPC",giverId=6134,ender="Lord Arkkoroc",enderType="NPC",enderId=6134,rewardNextId=3511,poiX=3895,poiY=-7188,wowhead="https://www.wowhead.com/wotlk/quest=3510",image="assets/images/quests/placeholder.png",xpDiff=5,money=26500,desc="She kills my children, mortal. She that calls herself the ruler of these oceans. A false god, nothing more. Crush her and bring back all of her heads.$B$BFor that, you will be given the name that you seek and something else of equal importance.$B$BShe roams the clutch... Hetaera she is called.$B$B<Lord Arkkoroc points to the southwest.>$B$BGo!$B",logDesc="Slay Hetaera and bring back Hetaera's Bloodied Head, Hetaera's Beaten Head, and Hetaera's Bruised Head to Lord Arkkoroc."} end
if not DB[3511] then DB[3511]={id=3511,zoneId=16,name="The Name of the Beast",level=58,minLevel=45,giver="Lord Arkkoroc",giverType="NPC",giverId=6134,ender="Loramus Thalipedes",enderType="NPC",enderId=7783,rewardNextId=3602,poiX=3895,poiY=-7188,wowhead="https://www.wowhead.com/wotlk/quest=3511",image="assets/images/quests/placeholder.png",xpDiff=3,desc="As promised, I will reveal the name of the demon lord, Razelikh the Defiler. First, however, I must prepare something of utmost importance for your journey.$B$BThe weapon you seek to create requires a temper. Give me a moment to drain the blood from these heads.$B$B<Lord Arkkoroc squeezes the heads in between his gigantic fists, draining them of their blood.>$B$BTake the temper back to Loramus along with the name of the beast: Rakh'likh.",logDesc="Take the temper back to Loramus Thalipedes.$B"} end
if not DB[3512] then DB[3512]={id=3512,zoneId=8,name="In Eranikus' Own Words",level=55,minLevel=48,giver="Itharius",giverType="NPC",giverId=5353,ender="Umbranse the Spiritspeaker",enderType="NPC",enderId=8588,poiX=-10717,poiY=-2536,wowhead="https://www.wowhead.com/wotlk/quest=3512",image="assets/images/quests/placeholder.png",xpDiff=4,desc="$N, our first step will be to devise a method to speak with Eranikus through the gem.  He lies in a precarious state between sleep and death now, twisted within a weave of nightmares.  Though the essence you have given me is badly tainted, there is a chance we can reach him.$B$BTravel far to the icy lands of eastern Winterspring and seek one of our mortal allies, Umbranse the Spiritspeaker.  He is a human medium who speaks for the dead.  Though Eranikus is not truly dead, he may be of aid to us still.",logDesc="Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker."} end
if not DB[3513] then DB[3513]={id=3513,zoneId=17,name="The Runed Scroll",level=25,minLevel=15,ender="Kadrak",enderType="NPC",enderId=8582,rewardNextId=3514,wowhead="https://www.wowhead.com/wotlk/quest=3513",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The official-looking scroll is wrapped tightly with a silvery ribbon. You're sure someone would be interested in seeing this, but who?$B$BThere is an outpost close to the Ashenvale border to the north, and if the information on this scroll involves the night elves, this would be the place to take it.",logDesc="Take the Runed Scroll to the northern guard tower in the Barrens."} end
if not DB[3514] then DB[3514]={id=3514,zoneId=17,name="Horde Presence",level=29,minLevel=15,giver="Kadrak",giverType="NPC",giverId=8582,ender="Kadrak",enderType="NPC",enderId=8582,poiX=1246,poiY=-2253,wowhead="https://www.wowhead.com/wotlk/quest=3514",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak.$B$BShe'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here. The Horde will not tolerate her outrunners here.$B$B$N, travel to the Talon Den. Kill Rynthariel, and then put up a symbol for all to see. Take this Horde flag, $N. Put it up in the Talon Den so that they will not be so rash as to send another messenger through our territory again.",logDesc="Kill the leader of the Talon Den, Rynthariel the Keymaster.",choiceRewards={{id=10653,qty=1},{id=10654,qty=1}}} end
if not DB[3515] then DB[3515]={id=3515,zoneId=16,name="<UNUSED>",level=42,minLevel=45,rewardNextId=3516,wowhead="https://www.wowhead.com/wotlk/quest=3515",image="assets/images/quests/placeholder.png",xpDiff=5} end
if not DB[3516] then DB[3516]={id=3516,zoneId=16,name="<UNUSED>",level=42,minLevel=45,wowhead="https://www.wowhead.com/wotlk/quest=3516",image="assets/images/quests/placeholder.png",xpDiff=5} end
if not DB[3517] then DB[3517]={id=3517,zoneId=16,name="Stealing Knowledge",level=52,minLevel=45,giver="Jediga",giverType="NPC",giverId=8587,ender="Jediga",enderType="NPC",enderId=8587,poiX=3603,poiY=-4421,wowhead="https://www.wowhead.com/wotlk/quest=3517",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I admit, $N, I've made the most of my situation in Azshara. Belgrom's punishment has had its share of benefits.$B$BBefore I left, I did some research and you would be surprised how many valuable items are lying around.$B$BI'll tell you more about my deals, and even give you a cut of the profits, if you help me gather some of them.$B$BThere are tablets throughout the Ruins of Eldarath to the east that I need. All four are named after Highborne wizards. Get them for me and we'll talk some more.",logDesc="Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara."} end
if not DB[3518] then DB[3518]={id=3518,zoneId=16,name="Delivery to Magatha",level=52,minLevel=45,giver="Jediga",giverType="NPC",giverId=8587,ender="Magatha Grimtotem",enderType="NPC",enderId=4046,rewardNextId=3562,poiX=3603,poiY=-4421,wowhead="https://www.wowhead.com/wotlk/quest=3518",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The first tablet goes to a tauren female... one called Magatha. She is among the elders in Thunder Bluff, and is one of the proponents of the alliance between the tauren and the Forsaken. She, more than anyone among the elders, feels the tauren and their ways can help the Forsaken find a path back to being human.$B$BBring her the Tablet of Beth'Amara. The tablet may be the link she needs in finding a way to help the Forsaken... or so she claims.",logDesc="Bring the Tablet of Beth'Amara to Magatha in Thunder Bluff."} end
if not DB[3519] then DB[3519]={id=3519,zoneId=188,name="A Friend in Need",level=4,minLevel=2,giver="Iverron",giverType="NPC",giverId=8584,ender="Dirania Silvershine",enderType="NPC",enderId=8583,rewardNextId=3521,poiX=10712,poiY=1035,wowhead="https://www.wowhead.com/wotlk/quest=3519",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Ughhh... I was bitten very badly by a spider named Githyiss the Vile while exploring the spider cave very close to here. I am sure I have been seriously poisoned; you must help me.$B$BPlease tell Dirania Silvershine. She will be able to help me.$B$BHurry... I'm so dizzy...",logDesc="Speak to Dirania Silvershine in Shadowglen."} end
if not DB[3520] then DB[3520]={id=3520,zoneId=440,name="Screecher Spirits",level=44,minLevel=40,giver="Yeh'kinya",giverType="NPC",giverId=8579,ender="Yeh'kinya",enderType="NPC",enderId=8579,rewardNextId=3527,poiX=-6903,poiY=-4841,wowhead="https://www.wowhead.com/wotlk/quest=3520",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I seek the spirits of the vale screechers of Feralas.  They are the cousins of an old, old god, and their spirits are linked to him.$B$BTake this bramble wand and go to Feralas.  Find and defeat vale screechers in southern and central Feralas, then wave my bramble over their fallen bodies.  This will coax their spirit to reveal itself.  Touch the spirit and collect its essence.$B$BReturn to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke.",logDesc="Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port."} end
if not DB[3521] then DB[3521]={id=3521,zoneId=188,name="Iverron's Antidote",level=4,minLevel=2,giver="Dirania Silvershine",giverType="NPC",giverId=8583,ender="Dirania Silvershine",enderType="NPC",enderId=8583,rewardNextId=3522,poiX=10407,poiY=714,wowhead="https://www.wowhead.com/wotlk/quest=3521",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We may be able to help Iverron, as I know of an antidote that should help with the poison. It requires some ingredients, though, before I can make it.$B$BI'll need Hyacinth mushrooms. You can find these growing under trees, or you may collect them from the grell south of here; they seem to have taken a liking to them. I'll also need Moonpetal lilies, which only grow around watery pools.$B$BThe last ingredient may prove the most difficult. From the very spiders that poisoned Iverron, collect Webwood ichor.",logDesc="Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor for Dirania Silveshine in Shadowglen."} end
if not DB[3522] then DB[3522]={id=3522,zoneId=188,name="Iverron's Antidote",level=4,minLevel=2,giver="Dirania Silvershine",giverType="NPC",giverId=8583,ender="Iverron",enderType="NPC",enderId=8584,poiX=10407,poiY=714,wowhead="https://www.wowhead.com/wotlk/quest=3522",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The antidote is ready, $N. Please see that Iverron drinks it.$B$BThere is something that you should know -- the antidote -- it will only remain viable for 5 minutes. You must get it to him in time.$B$BSpeed be with you, $N.",logDesc="Bring Iverron's Antidote to Iverron before the time limit is up. Iverron can be found by the cave to the north.",choiceRewards={{id=10655,qty=1},{id=10656,qty=1}}} end
if not DB[3523] then DB[3523]={id=3523,zoneId=722,name="Scourge of the Downs",level=37,minLevel=32,giver="Belnistrasz",giverType="NPC",giverId=8516,ender="Belnistrasz",enderType="NPC",enderId=8516,rewardNextId=3525,poiX=2611,poiY=731,wowhead="https://www.wowhead.com/wotlk/quest=3523",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.  Yes - I said Scourge all right; they've brokered some sort of deal with the Quilboar here, and this nightmare is a result.$B$BListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but you seem to be the type not to worry about that too much.",logDesc="If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him."} end
if not DB[3524] then DB[3524]={id=3524,zoneId=148,name="Washed Ashore",level=13,minLevel=11,giver="Gwennyth Bly'Leggonde",giverType="NPC",giverId=10219,ender="Gwennyth Bly'Leggonde",enderType="NPC",enderId=10219,rewardNextId=4681,poiX=6342,poiY=543,wowhead="https://www.wowhead.com/wotlk/quest=3524",image="assets/images/quests/placeholder.png",xpDiff=4,money=400,desc="Majestic sea creatures are known to launch themselves at the Darkshore coastline, beached there until they die. Lately, these beasts have been washing ashore in ever-increasing numbers.  I've been sent here by the Temple of the Moon to investigate, but the presence of murlocs along the water has made my research difficult.$B$BThere is a giant creature washed ashore just south of Auberdine that is ringed by the foul Greymist murlocs.  Could you go there and retrieve bones from the creature for our study?",logDesc="Recover Sea Creature Bones from the beached sea creature just south of Auberdine, and then return with it to Gwennyth Bly'Leggonde in Auberdine."} end
if not DB[3525] then DB[3525]={id=3525,zoneId=722,name="Extinguishing the Idol",level=37,minLevel=32,giver="Belnistrasz",giverType="NPC",giverId=8516,poiX=2611,poiY=731,wowhead="https://www.wowhead.com/wotlk/quest=3525",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Near the entrance is an idol that functions as a macabre oven for the Quilboar; the beasts... they literally consume their abductees from the Barrens.  I can shut down the idol and bind them from using it again, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.  If they take me down, then it's all over for us.$B$BAre you with me?!",logDesc="Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.$B$BProtect Belnistrasz while he performs the ritual to shut down the idol.",rewards={{id=10710,qty=1}}} end
if not DB[3526] then DB[3526]={id=3526,zoneId=-201,name="Goblin Engineering",level=-1,minLevel=10,giver="Graham Van Talen",giverType="NPC",giverId=4586,ender="Nixx Sprocketspring",enderType="NPC",enderId=8126,poiX=1410,poiY=150,wowhead="https://www.wowhead.com/wotlk/quest=3526",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!$B$B$N, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.",logDesc="If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."} end
if not DB[3527] then DB[3527]={id=3527,zoneId=978,name="The Prophecy of Mosh'aru",level=47,minLevel=40,giver="Yeh'kinya",giverType="NPC",giverId=8579,ender="Yeh'kinya",enderType="NPC",enderId=8579,rewardNextId=4787,poiX=-6903,poiY=-4841,wowhead="https://www.wowhead.com/wotlk/quest=3527",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence.  It was written on two tablets and taken to the troll city of Zul'Farrak, west of Gadgetzan.$B$BBring me the Mosh'aru tablets!$B$BThe first tablet is held by the long-dead troll Theka the Martyr.  It is said his persecutors were cursed into scarabs and now scuttle about his shrine.$B$BThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.$B$BWhen you have the tablets, bring them to me.",logDesc="Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris."} end
if not DB[3528] then DB[3528]={id=3528,zoneId=1417,name="The God Hakkar",level=53,minLevel=40,giver="Yeh'kinya",giverType="NPC",giverId=8579,ender="Yeh'kinya",enderType="NPC",enderId=8579,poiX=-6903,poiY=-4841,wowhead="https://www.wowhead.com/wotlk/quest=3528",image="assets/images/quests/placeholder.png",xpDiff=7,money=24000,desc="Now it is time to capture the essence of the avatar of Hakkar.$B$BTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.$B$BHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.$B$BDefeat him, and place his essence within the egg of Hakkar.",logDesc="Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.",choiceRewards={{id=10749,qty=1},{id=10750,qty=1},{id=10751,qty=1}}} end
if not DB[3529] then DB[3529]={id=3529,zoneId=16,name="<UNUSED>",level=52,minLevel=45,wowhead="https://www.wowhead.com/wotlk/quest=3529",image="assets/images/quests/placeholder.png"} end
if not DB[3530] then DB[3530]={id=3530,zoneId=16,name="<UNUSED>",level=52,minLevel=45,wowhead="https://www.wowhead.com/wotlk/quest=3530",image="assets/images/quests/placeholder.png"} end
if not DB[3531] then DB[3531]={id=3531,zoneId=16,name="<UNUSED>",level=52,minLevel=45,wowhead="https://www.wowhead.com/wotlk/quest=3531",image="assets/images/quests/placeholder.png"} end
if not DB[3541] then DB[3541]={id=3541,zoneId=16,name="Delivery to Jes'rimon",level=52,minLevel=45,giver="Jediga",giverType="NPC",giverId=8587,ender="Jes'rimon",enderType="NPC",enderId=8659,rewardNextId=3563,poiX=3603,poiY=-4421,wowhead="https://www.wowhead.com/wotlk/quest=3541",image="assets/images/quests/placeholder.png",xpDiff=3,money=4000,desc="I have a fence in Orgrimmar. He resides in The Drag. He's difficult to nail down if you don't know where to look, but if you go looking in one of the highest buildings there you should have no problem finding him.$B$BDo me a favor though, don't go shouting to all of Kalimdor that he's there and what his business is--it'd be bad for both of us.$B$BHe'll give us more than a fair price for the Tablet of Jin'yael. I'm not sure why, but you should have seen how excited he was to hear about its whereabouts.",logDesc="Bring the Tablet of Jin'yael to Jes'rimon in Orgrimmar."} end
if not DB[3542] then DB[3542]={id=3542,zoneId=16,name="Delivery to Andron Gant",level=52,minLevel=45,giver="Jediga",giverType="NPC",giverId=8587,ender="Andron Gant",enderType="NPC",enderId=6522,rewardNextId=3564,poiX=3603,poiY=-4421,wowhead="https://www.wowhead.com/wotlk/quest=3542",image="assets/images/quests/placeholder.png",xpDiff=3,money=6000,desc="Andron Gant is my next contact. He usually holds himself up in the Undercity... right near the Apothecarium.$B$BHe was a little more loose-lipped when it came to speaking about what he wanted the Tablet for. Apparently some of the mages of Undercity are looking to study some of the arcane spells the highborne used. They think this tablet will help them. Markri was adept at summoning creatures; especially elementals.$B$BTake the Tablet of Markri and return to me for your part of the reward.",logDesc="Bring the Tablet of Markri to Andron Gant in Undercity."} end
if not DB[3561] then DB[3561]={id=3561,zoneId=16,name="Delivery to Archmage Xylem",level=52,minLevel=45,giver="Jediga",giverType="NPC",giverId=8587,ender="Archmage Xylem",enderType="NPC",enderId=8379,rewardNextId=3565,poiX=3603,poiY=-4421,wowhead="https://www.wowhead.com/wotlk/quest=3561",image="assets/images/quests/placeholder.png",xpDiff=3,money=4000,desc="This final tablet goes to someone very dangerous, $N. Heed me when I tell you that I trust this person far less than anyone else I've asked you to meet with.$B$BArchmage Xylem has a tower up in the hills overlooking Azshara. He's human, but he acts like no human I've met... or killed. He exudes power, and I dare not ask him what he plans on doing with the tablet.$B$BHe came to me, but told me that his bodyguard Sanath would help me get to the tower when I was ready to meet him. Look north for Sanath.",logDesc="Bring the Tablet of Sael'hai to Archmage Xylem in Azshara."} end
if not DB[3562] then DB[3562]={id=3562,zoneId=16,name="Magatha's Payment to Jediga",level=52,minLevel=45,giver="Magatha Grimtotem",giverType="NPC",giverId=4046,ender="Jediga",enderType="NPC",enderId=8587,poiX=-1065,poiY=-212,wowhead="https://www.wowhead.com/wotlk/quest=3562",image="assets/images/quests/placeholder.png",xpDiff=4,money=6000,desc="Take this note to Jediga. Tell her the payment will be here for her when she returns. And tell her I am pleased with her work.$B$BGo swiftly, $N. Tell your master I will be awaiting her here.",logDesc="Deliver Magatha's Note to Jediga in Azshara."} end
if not DB[3563] then DB[3563]={id=3563,zoneId=16,name="Jes'rimon's Payment to Jediga",level=52,minLevel=45,giver="Jes'rimon",giverType="NPC",giverId=8659,ender="Jediga",enderType="NPC",enderId=8587,poiX=1955,poiY=-4459,wowhead="https://www.wowhead.com/wotlk/quest=3563",image="assets/images/quests/placeholder.png",xpDiff=4,money=6000,desc="Take this letter to Jediga. Let her know that our deal has been beneficial and I be pleased with her work.$B$BYou tell her she come back to Orgrimmar fast and Jes'rimon make sure he take good care of her.$B$BTell her that, and maybe in the future I have need of your services again, $N.",logDesc="Deliver Jes'rimon's Note to Jediga in Azshara."} end
if not DB[3564] then DB[3564]={id=3564,zoneId=16,name="Andron's Payment to Jediga",level=52,minLevel=45,giver="Andron Gant",giverType="NPC",giverId=6522,ender="Jediga",enderType="NPC",enderId=8587,poiX=1389,poiY=347,wowhead="https://www.wowhead.com/wotlk/quest=3564",image="assets/images/quests/placeholder.png",xpDiff=4,money=7500,desc="Here... take... <hic> this to Jediga. Good luck to ya!",logDesc="Deliver Andron's Note to Jediga in Azshara."} end
if not DB[3565] then DB[3565]={id=3565,zoneId=16,name="Xylem's Payment to Jediga",level=52,minLevel=45,giver="Archmage Xylem",giverType="NPC",giverId=8379,ender="Jediga",enderType="NPC",enderId=8587,poiX=3982,poiY=-4760,wowhead="https://www.wowhead.com/wotlk/quest=3565",image="assets/images/quests/placeholder.png",xpDiff=4,money=6000,desc="What is it? Oh yes, your payment. Of course.$B$BTake this and be off with you. I'm sure Jediga is awaiting oh so patiently for your return.",logDesc="Deliver Xylem's Note to Jediga in Azshara."} end
if not DB[3566] then DB[3566]={id=3566,zoneId=51,name="Rise, Obsidion!",level=46,minLevel=40,giver="Dying Archaeologist",giverType="NPC",giverId=8417,ender="Curator Thorius",enderType="NPC",enderId=8256,poiX=-6480,poiY=-1241,wowhead="https://www.wowhead.com/wotlk/quest=3566",image="assets/images/quests/placeholder.png",xpDiff=7,money=13000,desc="It... It... It was all a trap.$B$BForgive... me.$B$BKill the traitor... Kill him for us... for Thorius.",logDesc="Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion. ",choiceRewards={{id=10740,qty=1},{id=10741,qty=1},{id=10739,qty=1}}} end
if not DB[3567] then DB[3567]={id=3567,zoneId=357,name="To the Top",level=25,minLevel=25,giver="Marli Wishrunner",giverType="NPC",giverId=7773,ender="Marli Wishrunner",enderType="NPC",enderId=7773,poiX=-3130,poiY=2257,wowhead="https://www.wowhead.com/wotlk/quest=3567",image="assets/images/quests/placeholder.png"} end
if not DB[3568] then DB[3568]={id=3568,zoneId=1497,name="Seeping Corruption",level=52,minLevel=45,giver="Chemist Cuely",giverType="NPC",giverId=8390,ender="Chemist Cuely",enderType="NPC",enderId=8390,poiX=1421,poiY=406,wowhead="https://www.wowhead.com/wotlk/quest=3568",image="assets/images/quests/placeholder.png",xpDiff=3,money=4000,desc="See that tauren behind me--the one who looks like she's going to be ill at any moment? She was in Azshara recently. She claims she was wounded by some naga while making her way through the Ruins of Eldarath.$B$BAfter fighting off a few of them, she took a break on the beach and drank from one of the tide pools. Now she's feeling nauseous... among other things.$B$BI'd like to find out what she drank. Take this box, in it are some empty vials I labeled. Fill each at different pools and come back.",logDesc="Fill all 4 Empty Vials at the tide pools along the coast of the Ruins of Eldarath in Azshara before returning to Chemist Cuely."} end
if not DB[3569] then DB[3569]={id=3569,zoneId=1497,name="Seeping Corruption",level=52,minLevel=45,giver="Chemist Cuely",giverType="NPC",giverId=8390,ender="Thersa Windsong",enderType="NPC",enderId=8393,poiX=1421,poiY=406,wowhead="https://www.wowhead.com/wotlk/quest=3569",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Give this to Thersa. Perhaps it will cure her... perhaps not. We really won't know until after she drinks it.",logDesc="Give Cuely's Elixir to Thersa Windsong in Undercity."} end
if not DB[3570] then DB[3570]={id=3570,zoneId=1497,name="Seeping Corruption",level=52,minLevel=45,giver="Chemist Cuely",giverType="NPC",giverId=8390,ender="Chemist Cuely",enderType="NPC",enderId=8390,poiX=1421,poiY=406,wowhead="https://www.wowhead.com/wotlk/quest=3570",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500} end
if not DB[3581] then DB[3581]={id=3581,zoneId=1638,name="<UNUSED>",level=40,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=3581",image="assets/images/quests/placeholder.png",desc="Imagine yourself racing across the plains,through forests and over mountains,the wind in your face... Traveling over unseen territory; the wonder of the road ahead,your destiny resting just over the horizon.$B$BAlways remember that on hoof,many things are achievable; as a Tauren,you will be granted the swiftness of Plainsrunning. There is no limit to the distances you might go.",logDesc="Speak to Saern Priderunner again to learn the Plainsrunning skill."} end
if not DB[3601] then DB[3601]={id=3601,zoneId=16,name="Kim'jael Indeed!",level=53,minLevel=47,giver="Kim'jael",giverType="NPC",giverId=8420,ender="Kim'jael",enderType="NPC",enderId=8420,poiX=4604,poiY=-5988,wowhead="https://www.wowhead.com/wotlk/quest=3601",image="assets/images/quests/placeholder.png",xpDiff=6,money=800,desc="Kim'jael indeed!! Do you know what Kim'jael means to the Blood elves, $N? Little rat... or something like that. The big bullies!$B$BThey hired me to help them scout the area looking for some sort of lost treasures. Of course I jumped aboard the moment they said \"treasure\" and the amount they were willing to pay, but of course, they turned on me and tried to kill me... ME!$B$BGoes to show you, you can't trust a Blood elf.$B$BThe problem is, they still have my equipment and I can't get it back. Help me out?",logDesc="Search the Thalassian Base Camp for Kim'jael's Compass, Scope, Stuffed Chicken and Wizzlegoober, then return them to him in Azshara.",rewards={{id=10830,qty=3}}} end
if not DB[3602] then DB[3602]={id=3602,zoneId=16,name="Azsharite",level=58,minLevel=45,giver="Loramus Thalipedes",giverType="NPC",giverId=7783,ender="Loramus Thalipedes",enderType="NPC",enderId=7783,poiX=3098,poiY=-6361,wowhead="https://www.wowhead.com/wotlk/quest=3602",image="assets/images/quests/placeholder.png",xpDiff=6,money=26500,desc="The ancient cliff giants of the southern region of Azshara consume the rock and buildings of the land for sustenance. The excrement from their consumption is a highly malleable and extremely strong crystal known as Azsharite.$B$BThe formations litter the southern arc, but few are ever recovered due to the extremely violent nature of the giants.$B$BYou are to venture south and recover enough of the Azsharite for the creation of the weapon's body. My felhounds will aid in the recovery of the crystal.",logDesc="Recover twenty Crystallized Azsharite from southern Azshara. You may use the Felhound to assist you in 'sniffing' out the location of cleverly hidden deposits.$B$BReturn to Loramus when the task is complete.$B"} end
if not DB[3621] then DB[3621]={id=3621,zoneId=16,name="The Formation of Felbane",level=58,minLevel=45,giver="Loramus Thalipedes",giverType="NPC",giverId=7783,ender="Galvan the Ancient",enderType="NPC",enderId=7802,rewardNextId=3625,poiX=3098,poiY=-6361,wowhead="https://www.wowhead.com/wotlk/quest=3621",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The weapons are ready to be forged. You must take the tempered azsharite to one with the ability to harness fel energy.$B$BIn Stranglethorn Vale such a blacksmith exists. Galvan the Ancient, leader of the Mithril Order, will craft the weapons to your specifications. You will find his encampment between Zul'Gurub and the Mosh'Ogg ogre mound.$B$BMay your determination and faith carry you through this ordeal. Should you fail, know that your God smiles down upon you, mortal.",logDesc="Take the Shipment to Galvan the Ancient in Stranglethorn Vale."} end
if not DB[3622] then DB[3622]={id=3622,zoneId=1657,name="<UNUSED>",level=41,minLevel=41,wowhead="https://www.wowhead.com/wotlk/quest=3622",image="assets/images/quests/placeholder.png"} end
if not DB[3623] then DB[3623]={id=3623,zoneId=1657,name="<UNUSED>",level=41,minLevel=41,wowhead="https://www.wowhead.com/wotlk/quest=3623",image="assets/images/quests/placeholder.png"} end
if not DB[3624] then DB[3624]={id=3624,zoneId=1657,name="<UNUSED>",level=41,minLevel=41,wowhead="https://www.wowhead.com/wotlk/quest=3624",image="assets/images/quests/placeholder.png"} end
if not DB[3625] then DB[3625]={id=3625,zoneId=33,name="Enchanted Azsharite Fel Weaponry",level=58,minLevel=45,giver="Galvan the Ancient",giverType="NPC",giverId=7802,ender="Galvan the Ancient",enderType="NPC",enderId=7802,rewardNextId=3626,poiX=-12033,poiY=-1004,wowhead="https://www.wowhead.com/wotlk/quest=3625",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N, the creation of each weapon will take some time.$B$BAdditionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration. This is why you must release the Felcurse only when the moment is right!$B$BNow give me a moment to craft your weapon, $N.$B",logDesc="Wait for Galvan to finish forging the weaponry.",choiceRewards={{id=10697,qty=1},{id=10698,qty=1},{id=10696,qty=1}}} end
if not DB[3626] then DB[3626]={id=3626,zoneId=33,name="Return to the Blasted Lands",level=58,minLevel=45,giver="Galvan the Ancient",giverType="NPC",giverId=7802,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,rewardNextId=3627,poiX=-12033,poiY=-1004,wowhead="https://www.wowhead.com/wotlk/quest=3626",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The hour of redemption is near, $N. You must return to the Blasted Lands with your new-found weaponry and speak with the Fallen Hero of the Horde to receive your final objective.$B",logDesc="Return to the Fallen Hero of the Horde at Splinterspear Junction in Swamp of Sorrows."} end
if not DB[3627] then DB[3627]={id=3627,zoneId=4,name="Uniting the Shattered Amulet",level=60,minLevel=45,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,rewardNextId=3628,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=3627",image="assets/images/quests/placeholder.png",xpDiff=6,desc="To reach the Defiler, you must first destroy the triad of power and recover the amulet pieces. When you recover all three pieces, return to me and I shall give you further instruction.$B$BGo $N! To the Blasted Lands! Sevine, Allistarj, and Grol must fall!$B",logDesc="Slay Grol the Destroyer, Lady Sevine, and Archmage Allistarj. From their corpses take the Amulet of Grol, the Amulet of Sevine, and the Amulet of Allistarj.$B$BRemember to USE your Enchanted Azsharite Fel Weaponry to weaken the triad. They cannot be killed otherwise - but use them wisely...$B"} end
if not DB[3628] then DB[3628]={id=3628,zoneId=4,name="You Are Rakh'likh, Demon",level=60,minLevel=45,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=3628",image="assets/images/quests/placeholder.png",xpDiff=7,money=27000,desc="Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain. As long as you hold the amulet, you can freely transport up to the lair. Once you reach the lair, you must conjure the beast. The amulet is your key, $N. Use it on the Altar of the Defiler.$B$BShould you defeat the Defiler, bring back his horn. It will become a symbol of hope for all that view it - proof that heroes do exist in this war torn world.$B",logDesc="Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands.$B",rewards={{id=10778,qty=1},{id=10779,qty=1},{id=10959,qty=1}}} end
if not DB[3629] then DB[3629]={id=3629,zoneId=-201,name="Goblin Engineering",level=-1,minLevel=10,giver="Springspindle Fizzlegear",giverType="NPC",giverId=5174,ender="Nixx Sprocketspring",enderType="NPC",enderId=8126,poiX=-4799,poiY=-1255,wowhead="https://www.wowhead.com/wotlk/quest=3629",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.$B$B$N, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.",logDesc="If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."} end
if not DB[3630] then DB[3630]={id=3630,zoneId=-201,name="Gnome Engineering",level=-1,minLevel=10,giver="Lilliam Sparkspindle",giverType="NPC",giverId=5518,ender="Tinkmaster Overspark",enderType="NPC",enderId=7944,poiX=-8347,poiY=644,wowhead="https://www.wowhead.com/wotlk/quest=3630",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!$B$B$N, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!",logDesc="If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge."} end
if not DB[3631] then DB[3631]={id=3631,zoneId=-61,name="Summon Felsteed",level=-1,minLevel=40,rewardNextId=4490,wowhead="https://www.wowhead.com/wotlk/quest=3631",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hmph. I say you're not prepared, but that is not my decision. Strahad feels otherwise, and it is his decision to make... this time.$B$BHe wishes to speak to you, and quickly. You'll find him still above Ratchet in the Barrens, at his little tower there with his acolytes.$B$BDo not dawdle long.",logDesc="Speak to Strahad Farsan in the Barrens."} end
if not DB[3632] then DB[3632]={id=3632,zoneId=-201,name="Gnome Engineering",level=-1,minLevel=10,giver="Springspindle Fizzlegear",giverType="NPC",giverId=5174,ender="Tinkmaster Overspark",enderType="NPC",enderId=7944,poiX=-4799,poiY=-1255,wowhead="https://www.wowhead.com/wotlk/quest=3632",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!$B$B$N, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark here in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!",logDesc="If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge."} end
if not DB[3633] then DB[3633]={id=3633,zoneId=-201,name="Goblin Engineering",level=-1,minLevel=10,giver="Tinkerwiz",giverType="NPC",giverId=3494,ender="Nixx Sprocketspring",enderType="NPC",enderId=8126,poiX=-841,poiY=-3727,wowhead="https://www.wowhead.com/wotlk/quest=3633",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!$B$B$N, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.",logDesc="If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan in Tanaris."} end
if not DB[3634] then DB[3634]={id=3634,zoneId=-201,name="Gnome Engineering",level=-1,minLevel=10,giver="Tinkerwiz",giverType="NPC",giverId=3494,ender="Tinkmaster Overspark",enderType="NPC",enderId=7944,poiX=-841,poiY=-3727,wowhead="https://www.wowhead.com/wotlk/quest=3634",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely often work.$B$B$N, read this manual.  If you wish to learn how to make metal paper weights, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!",logDesc="If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge."} end
if not DB[3635] then DB[3635]={id=3635,zoneId=-201,name="Gnome Engineering",level=-1,minLevel=10,giver="Graham Van Talen",giverType="NPC",giverId=4586,ender="Oglethorpe Obnoticus",enderType="NPC",enderId=7406,poiX=1410,poiY=150,wowhead="https://www.wowhead.com/wotlk/quest=3635",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.$B$B$N, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.",logDesc="If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay."} end
if not DB[3636] then DB[3636]={id=3636,zoneId=722,name="Bring the Light",level=37,minLevel=32,giver="3",giverType="NPC",giverId=1284,ender="3",enderType="NPC",enderId=1284,poiX=-8523,poiY=849,wowhead="https://www.wowhead.com/wotlk/quest=3636",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The Scourge is a persistent threat to the Alliance, a fact I am sure you know quite well. Recently, we have come across some very peculiar findings, $N.$B$BIn the Barrens lies a horrid tangle of briars called Razorfen Downs. While once it was the home of simple quilboar, now it has become apparent that a pact was made with the Scourge, creating creatures far worse... They are now ruled by the lich, Amnennar the Coldbringer.$B$BAlign yourself with the Light, $N; put an end to this evil union.",logDesc="Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.",rewards={{id=10823,qty=1},{id=10824,qty=1}}} end
if not DB[3637] then DB[3637]={id=3637,zoneId=-201,name="Gnome Engineering",level=-1,minLevel=10,giver="Tinkerwiz",giverType="NPC",giverId=3494,ender="Oglethorpe Obnoticus",enderType="NPC",enderId=7406,poiX=-841,poiY=-3727,wowhead="https://www.wowhead.com/wotlk/quest=3637",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.$B$B$N, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.",logDesc="If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay."} end
if not DB[3638] then DB[3638]={id=3638,zoneId=-201,name="The Pledge of Secrecy",level=47,minLevel=30,giver="Nixx Sprocketspring",giverType="NPC",giverId=8126,ender="Nixx Sprocketspring",enderType="NPC",enderId=8126,rewardNextId=3639,poiX=-7132,poiY=-3840,wowhead="https://www.wowhead.com/wotlk/quest=3638",image="assets/images/quests/placeholder.png",desc="Goblin engineering is about practical uses for high profit and higher explosive power!  Our schemata allow us to make powerful bombs and mighty weaponry; the manual you read covered this.$B$BThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a goblin engineer, that's that.  There is no access to gnome engineering at all.$B$BIf you still want to become a goblin engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.",logDesc="If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan."} end
if not DB[3639] then DB[3639]={id=3639,zoneId=-201,name="Show Your Work",level=-1,minLevel=10,giver="Nixx Sprocketspring",giverType="NPC",giverId=8126,ender="Nixx Sprocketspring",enderType="NPC",enderId=8126,poiX=-7132,poiY=-3840,wowhead="https://www.wowhead.com/wotlk/quest=3639",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The gleam in your eye tells me everything; you want to blow things up.  You have budding talent, $N, but I'd like to get some samples of your work so I might examine it for ways to emphasize goblin-oriented techniques.  I'll need the following: twenty big iron bombs, twenty sticks of solid dynamite, and five explosive sheep - and keep the safeties armed!$b$bSubmit these items to me and you'll be an official goblin engineer!",logDesc="Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to Nixx Sprocketspring in Gadgetzan."} end
if not DB[3640] then DB[3640]={id=3640,zoneId=-201,name="The Pledge of Secrecy",level=47,minLevel=30,giver="Tinkmaster Overspark",giverType="NPC",giverId=7944,ender="Tinkmaster Overspark",enderType="NPC",enderId=7944,rewardNextId=3641,poiX=-4835,poiY=-1263,wowhead="https://www.wowhead.com/wotlk/quest=3640",image="assets/images/quests/placeholder.png",desc="Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.$B$BThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.$B$BIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.",logDesc="If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge."} end
if not DB[3641] then DB[3641]={id=3641,zoneId=-201,name="Show Your Work",level=-1,minLevel=10,giver="Tinkmaster Overspark",giverType="NPC",giverId=7944,ender="Tinkmaster Overspark",enderType="NPC",enderId=7944,poiX=-4835,poiY=-1263,wowhead="https://www.wowhead.com/wotlk/quest=3641",image="assets/images/quests/placeholder.png",xpDiff=4,desc="If you're ready to make some truly fantastic devices, then you've come to the right place.  And I can see you're a skilled engineer, but I want some samples of your work.  What I hope to do though is to analyze your craftmanship for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.$B$BSubmit these items to me and you'll be an official gnomish engineer with access to all the schematics!",logDesc="Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to Tinkmaster Overspark in Ironforge."} end
if not DB[3642] then DB[3642]={id=3642,zoneId=-201,name="The Pledge of Secrecy",level=47,minLevel=30,giver="Oglethorpe Obnoticus",giverType="NPC",giverId=7406,ender="Oglethorpe Obnoticus",enderType="NPC",enderId=7406,rewardNextId=3643,poiX=-14417,poiY=411,wowhead="https://www.wowhead.com/wotlk/quest=3642",image="assets/images/quests/placeholder.png",desc="Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.$B$BThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.$B$BIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.",logDesc="If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Oglethrope Obnoticus in Booty bay."} end
if not DB[3643] then DB[3643]={id=3643,zoneId=-201,name="Show Your Work",level=-1,minLevel=10,giver="Oglethorpe Obnoticus",giverType="NPC",giverId=7406,ender="Oglethorpe Obnoticus",enderType="NPC",enderId=7406,poiX=-14417,poiY=411,wowhead="https://www.wowhead.com/wotlk/quest=3643",image="assets/images/quests/placeholder.png",xpDiff=4,desc="If you're ready to make some truly fantastic devices, then you've come to the right place.  And I can see you're a skilled engineer, but I want some samples of your work.  What I hope to do though is to analyze your craftmanship for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.$B$BSubmit these items to me and you'll be an official gnomish engineer with access to all the schematics!",logDesc="Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay."} end
