if not DB[3661] then DB[3661]={id=3661,zoneId=702,name="Favored of Elune?",level=47,minLevel=42,giver="Erelas Ambersky",giverType="NPC",giverId=7916,ender="Erelas Ambersky",enderType="NPC",enderId=7916,poiX=8707,poiY=989,wowhead="https://www.wowhead.com/wotlk/quest=3661",image="assets/images/quests/placeholder.png",xpDiff=5,money=13500,desc="Wildkin are quite unpredictable creatures, $N. Capable of incredible gentleness, these creatures will show extreme ferocity if something they deem important is threatened.$B$BThese beasts are rumored to have been created by Elune, and I am interested in finding if this is really the truth.$B$BRecently, I heard about a population of wildkin living in the Hinterlands -- Vicious, Primitive, and Savage Owlbeasts. They can be found amongst the wildlife there. Will you gather some wildkin feathers for me?",logDesc="Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village."} end
if not DB[3681] then DB[3681]={id=3681,zoneId=-141,name="Tome of Divinity",level=-1,minLevel=12,giver="Brandur Ironhammer",giverType="NPC",giverId=5149,ender="Duthorian Rall",enderType="NPC",enderId=6171,poiX=-4602,poiY=-896,wowhead="https://www.wowhead.com/wotlk/quest=3681",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Sorry to interrupt your travels, $r, but I thought you should know that word was sent from Stormwind recently asking that paladins report there for training.$B$BIf I didn't know any better, I'd say your close to reaching a special time and it's time you started studying the Tomes.$B$BLook for Duthorian Rall in Stormwind. He usually trains paladins in the Cathedral of Light.",logDesc="Speak with Duthorian Rall in Stormwind."} end
if not DB[3701] then DB[3701]={id=3701,zoneId=1537,name="The Smoldering Ruins of Thaurissan",level=54,minLevel=50,giver="Royal Historian Archesonus",giverType="NPC",giverId=8879,ender="Royal Historian Archesonus",enderType="NPC",enderId=8879,poiX=-4861,poiY=-1017,wowhead="https://www.wowhead.com/wotlk/quest=3701",image="assets/images/quests/placeholder.png",xpDiff=5,money=16500,desc="Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.$B$BIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, $N. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.",logDesc="Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.",rewards={{id=12102,qty=1}}} end
if not DB[3702] then DB[3702]={id=3702,zoneId=1537,name="The Smoldering Ruins of Thaurissan",level=54,minLevel=50,giver="Royal Historian Archesonus",giverType="NPC",giverId=8879,ender="Royal Historian Archesonus",enderType="NPC",enderId=8879,rewardNextId=3701,poiX=-4861,poiY=-1017,wowhead="https://www.wowhead.com/wotlk/quest=3702",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Would you like to hear a brief history of the Dark Iron dwarves?",logDesc="Listen to Royal Historian Archesonus recant the history of Thaurissan."} end
