if not DB[3741] then DB[3741]={id=3741,zoneId=44,name="Hilary's Necklace",level=15,minLevel=12,giver="Shawn",giverType="NPC",giverId=8965,ender="Hilary",enderType="NPC",enderId=8962,poiX=-9352,poiY=-2207,wowhead="https://www.wowhead.com/wotlk/quest=3741",image="assets/images/quests/placeholder.png",xpDiff=6,desc="My friend Hilary lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.$B$BCould you find it for her, please?",logDesc="Find Hilary's Necklace, and return it to Hilary in Lakeshire."} end
if not DB[3761] then DB[3761]={id=3761,zoneId=1638,name="Un'Goro Soil",level=50,minLevel=47,giver="Arch Druid Hamuul Runetotem",giverType="NPC",giverId=5769,ender="Ghede",enderType="NPC",enderId=9076,poiX=-1049,poiY=-304,wowhead="https://www.wowhead.com/wotlk/quest=3761",image="assets/images/quests/placeholder.png",xpDiff=5,money=14500,desc="The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  The Cenarion Circle wants to study this soil in large quantities; go into the wilds of Un'Goro and acquire enough of it for our continued research.$B$BThe rich soil will stick out in piles from time to time, and some of the beasts might have usable samples on their being.  Take them all outside to Ghede; just look for the piles of dirt and the tauren barking orders.  He means well, just don't get him riled up though!",logDesc="Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff."} end
if not DB[3762] then DB[3762]={id=3762,zoneId=1638,name="Assisting Arch Druid Runetotem",level=50,minLevel=47,giver="Innkeeper Pala",giverType="NPC",giverId=6746,ender="Arch Druid Hamuul Runetotem",enderType="NPC",enderId=5769,rewardNextId=3761,poiX=-1300,poiY=38,wowhead="https://www.wowhead.com/wotlk/quest=3762",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excuse me $c, but I'd like just a moment of your time if possible.$B$BThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.$B$BPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.",logDesc="Speak with Arch Druid Hamuul Runetotem in Thunder Bluff."} end
if not DB[3763] then DB[3763]={id=3763,zoneId=1657,name="Assisting Arch Druid Staghelm",level=50,minLevel=47,giver="Innkeeper Saelienne",giverType="NPC",giverId=6735,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,rewardNextId=3764,poiX=10128,poiY=2225,wowhead="https://www.wowhead.com/wotlk/quest=3763",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excuse me $c, but I'd like just a moment of your time if possible.$B$BThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.$B$BPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.",logDesc="Speak with Arch Druid Fandral Staghelm in Darnassus."} end
if not DB[3764] then DB[3764]={id=3764,zoneId=1657,name="Un'Goro Soil",level=50,minLevel=47,giver="Arch Druid Fandral Staghelm",giverType="NPC",giverId=3516,ender="Jenal",enderType="NPC",enderId=9047,poiX=10173,poiY=2570,wowhead="https://www.wowhead.com/wotlk/quest=3764",image="assets/images/quests/placeholder.png",xpDiff=5,money=14500,desc="The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  I want to know facts from falsehoods; go into the wilds of Un'Goro and acquire enough quality samples of soil for our continued study.$B$BYou may think that collection tasks are beneath you; that sort of attitude does not endear yourself to me or the Cenarion Circle.  Bring the samples to Jenal, who is no doubt wasting time outside behind this tree; just look for the piles of dirt.  He will handle the logistics - not I.",logDesc="Bring 20 Un'Goro Soil samples to Jenal at the Cenarion Enclave in Darnassus."} end
if not DB[3765] then DB[3765]={id=3765,zoneId=1519,name="The Corruption Abroad",level=24,minLevel=18,giver="Argos Nightwhisper",giverType="NPC",giverId=4984,ender="Gershala Nightwhisper",enderType="NPC",enderId=8997,rewardNextId=1275,poiX=-8779,poiY=1093,wowhead="https://www.wowhead.com/wotlk/quest=3765",image="assets/images/quests/placeholder.png",xpDiff=4,money=1300,desc="Stormwind -- such a bustling hub of activity.$b$bI have traveled from afar to seek help. Often it is heard that brave adventurers roam these city streets.$b$bMy brother, Gershala, requires assistance in Darkshore. He resides in the seaside town of Auberdine.$b$bThe journey is a long and epic one. It is for this reason that I ask the help of a seasoned $c such as yourself.",logDesc="Travel to Gershala Nightwhisper in Auberdine."} end
if not DB[3781] then DB[3781]={id=3781,zoneId=1657,name="Morrowgrain Research",level=50,minLevel=47,giver="Arch Druid Fandral Staghelm",giverType="NPC",giverId=3516,ender="Mathrengyl Bearwalker",enderType="NPC",enderId=4217,rewardNextId=3785,poiX=10173,poiY=2570,wowhead="https://www.wowhead.com/wotlk/quest=3781",image="assets/images/quests/placeholder.png",xpDiff=1,desc="With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds blossom into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I intend to unravel this mystery.$B$BTake this to Mathrengyl downstairs, and he will give you some seeds so you can get started.  If you run out, you will need to purchase more from him.",logDesc="Take the Arch Druid's Seed Voucher to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus.",rewards={{id=11022,qty=20}}} end
if not DB[3782] then DB[3782]={id=3782,zoneId=1638,name="Morrowgrain Research",level=50,minLevel=47,giver="Arch Druid Hamuul Runetotem",giverType="NPC",giverId=5769,ender="Bashana Runetotem",enderType="NPC",enderId=9087,rewardNextId=3786,poiX=-1049,poiY=-304,wowhead="https://www.wowhead.com/wotlk/quest=3782",image="assets/images/quests/placeholder.png",xpDiff=1,desc="With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds have blossomed into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I very much hope to unravel this mystery for the Circle.$B$BTake this voucher over to my daughter Bashana, and she will give you some seeds so you may assist us.  If you run out, you will need to purchase more from her.",logDesc="Take the Seed Voucher to Bashana Runetotem in Thunder Bluff.",rewards={{id=11022,qty=20}}} end
if not DB[3783] then DB[3783]={id=3783,zoneId=618,name="Are We There, Yeti?",level=56,minLevel=52,giver="Umi Rumplesnicker",giverType="NPC",giverId=10305,ender="Umi Rumplesnicker",enderType="NPC",enderId=10305,rewardNextId=977,poiX=6753,poiY=-4639,wowhead="https://www.wowhead.com/wotlk/quest=3783",image="assets/images/quests/placeholder.png",xpDiff=4,money=8500,desc="My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret... $B$BI'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed!$B$BI need thick yeti fur from the ice thistle yeti to start with. Will you help? You'll find them to the southeast.",logDesc="Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook."} end
if not DB[3784] then DB[3784]={id=3784,zoneId=1497,name="Assisting Arch Druid Runetotem",level=50,minLevel=47,giver="Innkeeper Norman",giverType="NPC",giverId=6741,ender="Arch Druid Hamuul Runetotem",enderType="NPC",enderId=5769,rewardNextId=3761,poiX=1635,poiY=223,wowhead="https://www.wowhead.com/wotlk/quest=3784",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excuse me $c, but I'd like just a moment of your time if possible.$B$BThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.$B$BPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.",logDesc="Speak with Arch Druid Hamuul Runetotem in Thunder Bluff."} end
if not DB[3785] then DB[3785]={id=3785,zoneId=1657,name="Morrowgrain Research",level=50,minLevel=47,giver="Mathrengyl Bearwalker",giverType="NPC",giverId=4217,ender="Mathrengyl Bearwalker",enderType="NPC",enderId=4217,poiX=10179,poiY=2564,wowhead="https://www.wowhead.com/wotlk/quest=3785",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.$B$BWhen you have enough morrowgrain, bring them here to me in the enclave.  Please don't bother the Arch Druid; he's a very busy man, and he doesn't need to be disturbed every time someone returns with another batch of morrowgrain!",logDesc="Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.$B$BBring 10 Morrowgrain to Mathrengyl Bearwalker in Darnassus.",rewards={{id=11887,qty=1}}} end
if not DB[3786] then DB[3786]={id=3786,zoneId=1638,name="Morrowgrain Research",level=50,minLevel=47,giver="Bashana Runetotem",giverType="NPC",giverId=9087,ender="Bashana Runetotem",enderType="NPC",enderId=9087,poiX=-1088,poiY=-225,wowhead="https://www.wowhead.com/wotlk/quest=3786",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.$B$BWhen you have enough morrowgrain, bring them to me here on Elder Rise.  Please don't bother the Arch Druid; he'll be very busy with the research, as well as the multitude of concerns he has!",logDesc="Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.$B$BBring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff.",rewards={{id=11887,qty=1}}} end
if not DB[3787] then DB[3787]={id=3787,zoneId=1519,name="Jonespyre's Request",level=50,minLevel=47,giver="Tannysa",giverType="NPC",giverId=5566,ender="Quintis Jonespyre",enderType="NPC",enderId=7879,rewardNextId=3791,poiX=-8970,poiY=780,wowhead="https://www.wowhead.com/wotlk/quest=3787",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Excuse me, friend...$B$BA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.$B$BIf you're interested, speak with him; no doubt, all will be revealed once you do.",logDesc="Speak with Quintis Jonespyre in Feathermoon Stronghold."} end
if not DB[3788] then DB[3788]={id=3788,zoneId=1116,name="Jonespyre's Request",level=50,minLevel=47,giver="Innkeeper Shyria",giverType="NPC",giverId=7736,ender="Quintis Jonespyre",enderType="NPC",enderId=7879,rewardNextId=3791,poiX=-4382,poiY=3289,wowhead="https://www.wowhead.com/wotlk/quest=3788",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excuse me, friend...$B$BA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides here in Feathermoon Stronghold.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.$B$BIf you're interested, speak with him; no doubt, all will be revealed once you do.",logDesc="Speak with Quintis Jonespyre in Feathermoon Stronghold."} end
if not DB[3789] then DB[3789]={id=3789,zoneId=1519,name="Assisting Arch Druid Staghelm",level=50,minLevel=47,giver="Innkeeper Allison",giverType="NPC",giverId=6740,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,rewardNextId=3764,poiX=-8868,poiY=674,wowhead="https://www.wowhead.com/wotlk/quest=3789",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excuse me $c, but I'd like just a moment of your time if possible.$B$BThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.$B$BPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.",logDesc="Speak with Arch Druid Fandral Staghelm in Darnassus."} end
if not DB[3790] then DB[3790]={id=3790,zoneId=1537,name="Assisting Arch Druid Staghelm",level=50,minLevel=47,giver="Innkeeper Firebrew",giverType="NPC",giverId=5111,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,rewardNextId=3764,poiX=-4841,poiY=-857,wowhead="https://www.wowhead.com/wotlk/quest=3790",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excuse me $c, but I'd like just a moment of your time if possible.$B$BThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.$B$BPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.",logDesc="Speak with Arch Druid Fandral Staghelm in Darnassus."} end
if not DB[3791] then DB[3791]={id=3791,zoneId=1116,name="The Mystery of Morrowgrain",level=50,minLevel=47,giver="Quintis Jonespyre",giverType="NPC",giverId=7879,ender="Quintis Jonespyre",enderType="NPC",enderId=7879,poiX=-4396,poiY=3187,wowhead="https://www.wowhead.com/wotlk/quest=3791",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Let me to be frank with you, $N.  I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain.  I'm a researcher - curses are my specialty.  I've heard that morrowgrain, under the right conditions, exude qualities like other herbs used in primitive curses.$B$BI want to know more, and I ask for your help.  Bring me ten morrowgrain, and I will be sure to take care of you.",logDesc="Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold.",choiceRewards={{id=11888,qty=1},{id=11889,qty=1}}} end
if not DB[3792] then DB[3792]={id=3792,zoneId=1116,name="Morrowgrain to Feathermoon Stronghold",level=55,minLevel=47,giver="Quintis Jonespyre",giverType="NPC",giverId=7879,ender="Quintis Jonespyre",enderType="NPC",enderId=7879,poiX=-4396,poiY=3187,wowhead="https://www.wowhead.com/wotlk/quest=3792",image="assets/images/quests/placeholder.png",rewards={{id=11022,qty=10}}} end
if not DB[3801] then DB[3801]={id=3801,zoneId=1584,name="Dark Iron Legacy",level=52,minLevel=48,giver="Franclorn Forgewright",giverType="NPC",giverId=8888,ender="Franclorn Forgewright",enderType="NPC",enderId=8888,rewardNextId=3802,poiX=-7596,poiY=-1115,wowhead="https://www.wowhead.com/wotlk/quest=3801",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Greetings, $N. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.$B$BYou are probably wondering why I am here and what it is that I want from you - both valid questions.$B$BI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.",logDesc="Speak with Franclorn Forgewright at Forgewright's Tomb in Blackrock Mountain if you are interested in obtaining a key to the city major."} end
if not DB[3802] then DB[3802]={id=3802,zoneId=1584,name="Dark Iron Legacy",level=52,minLevel=48,giver="Franclorn Forgewright",giverType="NPC",giverId=8888,poiX=-7596,poiY=-1115,wowhead="https://www.wowhead.com/wotlk/quest=3802",image="assets/images/quests/placeholder.png",xpDiff=7,money=23000,desc="You will find Fineous Darkvire beyond the Ring of Law, in the Hall of Crafting. Kill the miserable cur and recover Ironfel.$B$BTake Ironfel to the Shrine of Thaurissan and place the hammer in its rightful place: In the hands of the statue erected in my honor.$B$BWhen this is done, the compartment in which I stored the master key will open. More importantly, Ironfel will remain forever in my grasp. Should they make an attempt to remove the hammer; both the statue and hammer will shatter, lost forever.",logDesc="Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.$B",rewards={{id=11000,qty=1}}} end
if not DB[3803] then DB[3803]={id=3803,zoneId=1657,name="Morrowgrain to Darnassus",level=55,minLevel=47,giver="Mathrengyl Bearwalker",giverType="NPC",giverId=4217,ender="Mathrengyl Bearwalker",enderType="NPC",enderId=4217,poiX=10179,poiY=2564,wowhead="https://www.wowhead.com/wotlk/quest=3803",image="assets/images/quests/placeholder.png",rewards={{id=11887,qty=1}}} end
if not DB[3804] then DB[3804]={id=3804,zoneId=1638,name="Morrowgrain to Thunder Bluff",level=55,minLevel=47,giver="Bashana Runetotem",giverType="NPC",giverId=9087,ender="Bashana Runetotem",enderType="NPC",enderId=9087,poiX=-1088,poiY=-225,wowhead="https://www.wowhead.com/wotlk/quest=3804",image="assets/images/quests/placeholder.png",rewards={{id=11887,qty=1}}} end
if not DB[3821] then DB[3821]={id=3821,zoneId=3,name="Dreadmaul Rock",level=52,minLevel=48,giver="Thal'trak Proudtusk",giverType="NPC",giverId=9082,ender="Sha'ni Proudtusk",enderType="NPC",enderId=9136,rewardNextId=3822,poiX=-6687,poiY=-2163,wowhead="https://www.wowhead.com/wotlk/quest=3821",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Sha'ni was sent to investigate reports of strange ritualistic activity coming from the Firegut ogres of the Burning Steppes over three weeks ago.$B$BGoretooth tells me that he hasn't heard from anyone in that platoon and that it's best that I move on and focus on the task at hand. Can you believe it? That's my wife!$B$BI can't leave my post, $N, but I must know what became of Sha'ni. Travel to the Burning Steppes and search for her.",logDesc="Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk."} end
if not DB[3822] then DB[3822]={id=3822,zoneId=46,name="Krom'Grul",level=53,minLevel=48,giver="Sha'ni Proudtusk",giverType="NPC",giverId=9136,ender="Thal'trak Proudtusk",enderType="NPC",enderId=9082,wowhead="https://www.wowhead.com/wotlk/quest=3822",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My whole platoon was captured, $N. All were slain - except me.$B$BTheir leader, Krom'Grul, wanted to save me for some sort of ritual.$B$BI was chained to this altar and brutalized by the beast. My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger. I had never seen such savagery!$B$BFind Krom'Grul and kill him! Take my ring back to Thal'trak.$B$BAnd $N, tell him that we will meet again... in another life. ",logDesc="Recover Sha'ni's Nose-Ring from Krom'Grul and return it to Thal'trak in Kargath. Search the various caves and mines in Dreadmaul Rock.$B",rewards={{id=11869,qty=1}}} end
if not DB[3823] then DB[3823]={id=3823,zoneId=46,name="Extinguish the Firegut",level=52,minLevel=48,giver="Oralius",giverType="NPC",giverId=9177,ender="Oralius",enderType="NPC",enderId=9177,rewardNextId=3824,poiX=-8372,poiY=-2743,wowhead="https://www.wowhead.com/wotlk/quest=3823",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We must strike at our enemies before they strike at us!$B$BI'll make this brief, soldier.$B$BThe Firegut ogres of the Burning Steppes are allies of the Blackrock orcs. They work closely with those vile orcs, keeping the mineral rich Dreadmaul Rock guarded and the supply lines open at all times.$B$BLeave your mark, $N. Cripple their forces and return to me when the job is done.$B$B<Oralius grabs at the air and makes a choking motion.>$B$BI WILL KILL YOU, WINKY!",logDesc="Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes."} end
if not DB[3824] then DB[3824]={id=3824,zoneId=46,name="Gor'tesh the Brute Lord",level=53,minLevel=48,giver="Oralius",giverType="NPC",giverId=9177,ender="Oralius",enderType="NPC",enderId=9177,rewardNextId=3825,poiX=-8372,poiY=-2743,wowhead="https://www.wowhead.com/wotlk/quest=3824",image="assets/images/quests/placeholder.png",xpDiff=5,desc="They're reeling I tell you! Our next strike must be decisive.$B$BThe brute lord, Gor'tesh, must be slain. More importantly, his head must be returned to me so that I may prepare the third phase of our attack on the Firegut ogres.$B$BBe warned, soldier, Gor'tesh rules not from Dreadmaul Rock but from a Blackrock orc structure to the west of Dreadmaul Rock.$B$BYour orders, then, are simple. Find Gor'tesh and chop off his fat head. Return to me when the job is done.$B$BSHUT UP, WINKY!",logDesc="Collect Gor'tesh's Lopped Off Head.$B"} end
if not DB[3825] then DB[3825]={id=3825,zoneId=46,name="Ogre Head On A Stick = Party",level=53,minLevel=48,giver="Oralius",giverType="NPC",giverId=9177,ender="Oralius",enderType="NPC",enderId=9177,poiX=-8372,poiY=-2743,wowhead="https://www.wowhead.com/wotlk/quest=3825",image="assets/images/quests/placeholder.png",xpDiff=5,money=24000,desc="Just one last thing you must do, soldier.$B$BI've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground. Once you do that, watch as those cowardly ogres run for their lives! After you've had your fun, come back to me and I'll reward you for all of your hard work.$B$B<Oralius seems to be losing touch with reality.>",logDesc="Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike.",choiceRewards={{id=11867,qty=1},{id=11868,qty=1}}} end
if not DB[3841] then DB[3841]={id=3841,zoneId=357,name="An Orphan Looking For a Home",level=47,minLevel=38,giver="Kindal Moonweaver",giverType="NPC",giverId=7956,ender="Quentin",enderType="NPC",enderId=9238,rewardNextId=3842,poiX=-4482,poiY=859,wowhead="https://www.wowhead.com/wotlk/quest=3841",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Oh, hello, $N. I'm so glad to see you again. How was your trip to Darnassus?$B$BWell, you'll be happy to know that we've made quite a bit of progress while you've been gone. We even saved a nest full of eggs. Unfortunately, the mother died before we got to her.$B$BSay, would you want one for a pet? They look to hatch soon, so they'll need a good $Gfather:mother;. What do you say?$B$BIf you're really interested, take one of the eggs to Quentin at the race tracks in Shimmering Flats. He'll tell you more.",logDesc="Speak to Quentin in Thousand Needles."} end
if not DB[3842] then DB[3842]={id=3842,zoneId=357,name="A Short Incubation",level=47,minLevel=38,giver="Quentin",giverType="NPC",giverId=9238,ender="Quentin",enderType="NPC",enderId=9238,poiX=-6159,poiY=-3881,wowhead="https://www.wowhead.com/wotlk/quest=3842",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The Moonweavers, huh? Most intriguing. I wish the sprite darters could truly appreciate what it means to have those two look after them. They are both quite capable.$B$BSo, they gave you the egg as a gift. Well, then you should be responsible for it for as long as you desire. It appears it's almost ready to hatch, but we should ensure it's healthy and no damage has been done to it.$B$BI only need two elixirs of fortitude for a small spell to protect the egg. I have the rest of the components here with me.",logDesc="Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles."} end
if not DB[3843] then DB[3843]={id=3843,zoneId=357,name="The Newest Member of the Family",level=47,minLevel=38,giver="Quentin",giverType="NPC",giverId=9238,ender="Agnar Beastamer",enderType="NPC",enderId=9660,rewardNextId=4297,poiX=-6159,poiY=-3881,wowhead="https://www.wowhead.com/wotlk/quest=3843",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A magnificent specimen, $N. If this creature survives gestation, then it'll be a healthy pet indeed!$B$BThere is one last thing I would suggest doing if you plan on following through with this--head to Aerie Peak in the Hinterlands. Speak to a dwarf there named Agnar Beastamer, he's a master animal handler and should be able to guide you in the final steps of incubation.$B$BBut hurry, $N, this egg is fragile and will not last long without proper care.",logDesc="Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies."} end
if not DB[3844] then DB[3844]={id=3844,zoneId=490,name="It's a Secret to Everybody",level=52,minLevel=47,rewardNextId=3845,wowhead="https://www.wowhead.com/wotlk/quest=3844",image="assets/images/quests/placeholder.png",xpDiff=2,desc="A destroyed raft rests along the shoreline. Considering this is only a small pond, it is not clear as to how it ended up here, although looking at the trees tells you that the water level may not be constant.$B$BPerhaps a little exploration in the area might uncover more clues...",logDesc="Look around in the pond for a clue about who this wrecked raft may belong to."} end
if not DB[3845] then DB[3845]={id=3845,zoneId=490,name="It's a Secret to Everybody",level=52,minLevel=47,ender="Linken",enderType="NPC",enderId=8737,rewardNextId=3908,wowhead="https://www.wowhead.com/wotlk/quest=3845",image="assets/images/quests/placeholder.png",xpDiff=5,desc=" Grabbing onto it, you pull the pack back to the shore. Perhaps if you examine the items inside the pack, you might find out more about who it belongs to.$B$BThere are a few stray travelers at Marshal's Refuge. Perhaps you might find out more there.",logDesc="Examine the items inside the pack and bring them to their owner."} end
if not DB[3861] then DB[3861]={id=3861,zoneId=-284,name="CLUCK!",level=1,minLevel=1,giver="Chicken",giverType="NPC",giverId=620,ender="Chicken",enderType="NPC",enderId=620,poiX=-4714,poiY=-12375,wowhead="https://www.wowhead.com/wotlk/quest=3861",image="assets/images/quests/placeholder.png",desc="\"Cluck... cluck... cluck... BACAW!$B$BCluck... cluck... cluck.\"$B$BThe chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.",logDesc="Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed."} end
if not DB[3881] then DB[3881]={id=3881,zoneId=490,name="Expedition Salvation",level=53,minLevel=48,giver="Williden Marshal",giverType="NPC",giverId=9270,ender="Williden Marshal",enderType="NPC",enderId=9270,poiX=-6143,poiY=-1093,wowhead="https://www.wowhead.com/wotlk/quest=3881",image="assets/images/quests/placeholder.png",xpDiff=5,money=4000,desc="I don't know how you made it here, but you're a sight for sore eyes!  I'm Williden Marshal, and I lead a non-aligned expedition troupe.  Our latest and greatest endeavor has met with what seems like countless disasters, the most serious of which being that we underestimated the savagery of Un'Goro Crater!$B$BAs we fled our base camps in the southwestern and northeastern parts of the crater, we left behind vital supplies.  You look like you're capable enough - can you help us by getting them back?",logDesc="Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater."} end
if not DB[3882] then DB[3882]={id=3882,zoneId=490,name="Roll the Bones",level=51,minLevel=49,giver="Spark Nilminer",giverType="NPC",giverId=9272,ender="Spark Nilminer",enderType="NPC",enderId=9272,poiX=-6150,poiY=-1076,wowhead="https://www.wowhead.com/wotlk/quest=3882",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.$B$BWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.",logDesc="Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater.",choiceRewards={{id=11908,qty=1},{id=11909,qty=1}}} end
if not DB[3883] then DB[3883]={id=3883,zoneId=490,name="Alien Ecology",level=52,minLevel=48,giver="Hol'anyee Marshal",giverType="NPC",giverId=9271,ender="Hol'anyee Marshal",enderType="NPC",enderId=9271,poiX=-6145,poiY=-1091,wowhead="https://www.wowhead.com/wotlk/quest=3883",image="assets/images/quests/placeholder.png",xpDiff=5,money=4000,desc="Just because we've suffered a setback doesn't mean that research must stop!  We were investigating the Gorishi insects in the southern part of the crater before winding up here.  Their presence is alien to the ecology of Un'Goro, and we want to find out why.$B$BIn their hive network must be larval hatcheries.  You can identify these places by their hanging larval spawns.  Use this vial to take a sample of the hive wall near any of the hatcheries.  Bring it back to me for study, but be careful!",logDesc="Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater.  Look for the chambers with the hanging larval spawns.$B$BBring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater."} end
if not DB[3884] then DB[3884]={id=3884,zoneId=490,name="Williden's Journal",level=50,minLevel=48,ender="Williden Marshal",enderType="NPC",enderId=9270,wowhead="https://www.wowhead.com/wotlk/quest=3884",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You have uncovered a mangled journal.  Parts of it remain legible, with a Williden Marshal claiming ownership over the contents therein.  If the journal is accurate, then Williden may be found somewhere in the northern part of the Crater; according to the journal, he and his companions sought higher ground from the savage beasts of the Crater once their base camps were overrun.",logDesc="Return the journal to Williden Marshal somewhere in Un'Goro Crater."} end
if not DB[3885] then DB[3885]={id=3885,zoneId=490,name="<NYI> <TXT> The Gadgetzan Run",level=55,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=3885",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Escort Me and Dadanga!",logDesc="Escort Petra and Dadanga!"} end
if not DB[3901] then DB[3901]={id=3901,zoneId=154,name="Rattling the Rattlecages",level=3,minLevel=1,giver="Shadow Priest Sarvis",giverType="NPC",giverId=1569,ender="Shadow Priest Sarvis",enderType="NPC",enderId=1569,poiX=1843,poiY=1640,wowhead="https://www.wowhead.com/wotlk/quest=3901",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You've shown your potential to the Forsaken under normal circumstances $N - now let's see you under pressure.$B$BThe Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far.  Again, thin their numbers and prove yourself to the Forsaken.  Do not tarry - when you are done, speak to me again.",logDesc="Kill 8 Rattlecage Skeletons, and then return to Shadow Priest Sarvis in Deathknell when you are done.",choiceRewards={{id=3274,qty=1},{id=11851,qty=1},{id=11852,qty=1}}} end
if not DB[3902] then DB[3902]={id=3902,zoneId=154,name="Scavenging Deathknell",level=3,minLevel=2,giver="Deathguard Saltain",giverType="NPC",giverId=1740,ender="Deathguard Saltain",enderType="NPC",enderId=1740,poiX=1861,poiY=1605,wowhead="https://www.wowhead.com/wotlk/quest=3902",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You there!  If you're looking for something to make yourself useful, then listen up!$B$BWe need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment.  Most likely, they'll be in stacks of boxes.  We expect more recruits to be rising soon, and unless we want them to stumble about naked we had better get to scavenging!$B$BWell get to work, you miserable bag of bones!  I'm not going to reward those without some hustle.",logDesc="Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.",choiceRewards={{id=11848,qty=1},{id=11849,qty=1},{id=11850,qty=1}}} end
if not DB[3903] then DB[3903]={id=3903,zoneId=9,name="Milly Osworth",level=4,minLevel=2,giver="Deputy Willem",giverType="NPC",giverId=823,ender="Milly Osworth",enderType="NPC",enderId=9296,rewardNextId=3904,poiX=-8948,poiY=-132,wowhead="https://www.wowhead.com/wotlk/quest=3903",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You've shown yourself a dependable $c, $N.  Dependable, and not afraid to get your hands dirty, eh?$B$BI have a friend, Milly Osworth, who's in some trouble.  She's over with her wagon on the other side of the abbey, near the stable.  I'm sure she could use a pair of hands like yours.",logDesc="Speak with Milly Osworth."} end
if not DB[3904] then DB[3904]={id=3904,zoneId=9,name="Milly's Harvest",level=4,minLevel=2,giver="Milly Osworth",giverType="NPC",giverId=9296,ender="Milly Osworth",enderType="NPC",enderId=9296,poiX=-8850,poiY=-224,wowhead="https://www.wowhead.com/wotlk/quest=3904",image="assets/images/quests/placeholder.png",xpDiff=3,desc="A gang of brigands, the Defias, moved into the Northshire Vineyards while I was harvesting!  I reported it to the Northshire guards and they assured me they'd take care of things, but... I'm afraid for my crop of grapes!  If the Defias don't steal them then I fear our guards will trample them when they chase away the thugs.$B$BPlease, you must help me!  I gathered most of my grapes into buckets, but I left them in the vineyards to the southeast.$B$BBring me those buckets!  Save my harvest!",logDesc="Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey."} end
if not DB[3905] then DB[3905]={id=3905,zoneId=9,name="Grape Manifest",level=4,minLevel=2,giver="Milly Osworth",giverType="NPC",giverId=9296,ender="Brother Neals",enderType="NPC",enderId=952,poiX=-8850,poiY=-224,wowhead="https://www.wowhead.com/wotlk/quest=3905",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now that my crop is saved, take this Grape Manifest to Brother Neals.  He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes.$B$BYou'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine.",logDesc="Bring the Grape Manifest to Brother Neals in Northshire Abbey.",choiceRewards={{id=11475,qty=1},{id=2690,qty=1}}} end
if not DB[3906] then DB[3906]={id=3906,zoneId=25,name="Disharmony of Flame",level=52,minLevel=48,giver="Thunderheart",giverType="NPC",giverId=9084,ender="Thunderheart",enderType="NPC",enderId=9084,rewardNextId=3907,poiX=-6690,poiY=-2162,wowhead="https://www.wowhead.com/wotlk/quest=3906",image="assets/images/quests/placeholder.png",xpDiff=5,money=15500,desc="The elders have felt a disturbance amongst the elements. The Dark Iron dwarves have summoned a foul spirit into our world that threatens to plague our lands with an eternal draught. This disharmony of flame must be investigated.$B$BTravel to Blackrock Mountain, through the Chasm of Flame, into the quarry. It is there that you shall find this lord of fire: Overmaster Pyron.$B$BEnd the disruption and return to me.",logDesc="Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment.$B"} end
if not DB[3907] then DB[3907]={id=3907,zoneId=1584,name="Disharmony of Fire",level=56,minLevel=48,giver="Thunderheart",giverType="NPC",giverId=9084,ender="Thunderheart",enderType="NPC",enderId=9084,poiX=-6690,poiY=-2162,wowhead="https://www.wowhead.com/wotlk/quest=3907",image="assets/images/quests/placeholder.png",xpDiff=7,money=25500,desc="I can taste the foulness in the air that surrounds you, $N. There is another, hidden in the depths of Blackrock, who does control this foulness.$B$BThe wind and earth cry his name: Lord Incendius... but someone... something... commands this being. He is merely an emissary.$B$BFind him and discover where his master hides. Return to me when you have collected this information.$B",logDesc="Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.$B",choiceRewards={{id=12113,qty=1},{id=12114,qty=1},{id=12112,qty=1},{id=12115,qty=1}}} end
if not DB[3908] then DB[3908]={id=3908,zoneId=490,name="It's a Secret to Everybody",level=52,minLevel=47,giver="Linken",giverType="NPC",giverId=8737,ender="Donova Snowden",enderType="NPC",enderId=9298,poiX=-6166,poiY=-1119,wowhead="https://www.wowhead.com/wotlk/quest=3908",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You see, I have no idea how I ended up here. No one really knows -- it's a secret to everybody! I just can't seem to remember anything...$B$BThese items you brought to me, though... I am remembering something.$B$BMy sword. I am supposed to strengthen it somehow, but I'm really not sure why. Sorry I can't tell you more, but I just don't remember!$B$BAnyhoo, I do know where you can take it -- Donova Snowden in Winterspring. You'll find her by the hot springs. She can temper the sword by the pools there.",logDesc="Take Linken's Sword to Donova Snowden in Winterspring."} end
if not DB[3909] then DB[3909]={id=3909,zoneId=490,name="The Videre Elixir",level=52,minLevel=47,giver="Donova Snowden",giverType="NPC",giverId=9298,ender="Donova Snowden",enderType="NPC",enderId=9298,rewardNextId=3912,poiX=6396,poiY=-2537,wowhead="https://www.wowhead.com/wotlk/quest=3909",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now, what's this? Linken... FORGOT?$B$BOh, I see... Lost his memory...$B$BWell, here is his sword. It's not complete, though. I know of the one that can finish it, but... speaking with him may prove difficult.$B$BListen, I know of someone that will be able to help you. It's too much to explain right now, but you must somehow acquire a Videre Elixir. The only one I know that can help you with that is Gregan Brewspewer. He's hard to track down, but last I knew he was camping in the wilds of Feralas.",logDesc="Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring."} end
if not DB[3910] then DB[3910]={id=3910,zoneId=440,name="<NYI> <TXT> The Un'Goro Run",level=55,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=3910",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Welcome to Gadgetzan!  Take us home...",logDesc="Escort Petra and Dadanga back to Un'Goro."} end
if not DB[3911] then DB[3911]={id=3911,zoneId=1584,name="The Last Element",level=54,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=3911",image="assets/images/quests/placeholder.png",xpDiff=5,money=24500,desc="There is work to be had for those venturing into the depths, $N.$B$BThe Dark Irons have mastered creation of extremely powerful golems.$B$BInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.$B$BJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.",logDesc="Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.$B",rewards={{id=12038,qty=1}}} end
if not DB[3912] then DB[3912]={id=3912,zoneId=490,name="Meet at the Grave",level=52,minLevel=47,giver="Donova Snowden",giverType="NPC",giverId=9298,ender="Gaeriyan",enderType="NPC",enderId=9299,rewardNextId=3913,poiX=6396,poiY=-2537,wowhead="https://www.wowhead.com/wotlk/quest=3912",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This elixir will allow you to speak with one that you would not normally even see...$B$BTake the Videre elixir, along with Linken's sword, to the graveyard just outside Gadgetzan in Tanaris. Once there, drink the potion. You may be quite surprised at the results, but do not be alarmed.$B$BIn your \"other\" form, head due north until you reach the mountains. You'll find the one you need to speak with in one of the rocky crevices. His name is Gaeriyan.$B$BRemember, he will only speak to you in that form...",logDesc="Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan."} end
if not DB[3913] then DB[3913]={id=3913,zoneId=490,name="A Grave Situation",level=52,minLevel=47,giver="Gaeriyan",giverType="NPC",giverId=9299,rewardNextId=3914,poiX=-6948,poiY=-3939,wowhead="https://www.wowhead.com/wotlk/quest=3913",image="assets/images/quests/placeholder.png",xpDiff=3,desc="If you return to the graveyard, $N, you will find a gravestone there... Not just any gravestone; this one will stand out from the others. Secrets lie within it.$B$BPush on the stone, and you will learn of these secrets...",logDesc="Resurrect, then look for the gravestone that Gaeriyan told you to find."} end
if not DB[3914] then DB[3914]={id=3914,zoneId=490,name="Linken's Sword",level=52,minLevel=47,ender="Linken",enderType="NPC",enderId=8737,rewardNextId=3941,wowhead="https://www.wowhead.com/wotlk/quest=3914",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="After a strong flash of light, you are able to pick up the sword again. It has been transformed!",logDesc="Deliver Linken's Superior Sword to Linken in Un'Goro Crater."} end
if not DB[3921] then DB[3921]={id=3921,zoneId=17,name="Wenikee Boltbucket",level=14,minLevel=10,giver="Sputtervalve",giverType="NPC",giverId=3442,ender="Wenikee Boltbucket",enderType="NPC",enderId=9316,rewardNextId=3922,poiX=-902,poiY=-3759,wowhead="https://www.wowhead.com/wotlk/quest=3921",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I think I might have broken that Samophlange.  That's not good, because I already told some colleagues in Undermine about it and they were very intrigued.  We must find a way to fix it!$B$BTake the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, the horde outpost between the Barrens and Ashenvale.  She is very clever and inquisitive.  If you show her the samophlange I bet she'd jump at the chance to fix it.",logDesc="Bring the Broken Samophlange to Wenikee Boltbucket."} end
if not DB[3922] then DB[3922]={id=3922,zoneId=17,name="Nugget Slugs",level=15,minLevel=10,giver="Wenikee Boltbucket",giverType="NPC",giverId=9316,ender="Wenikee Boltbucket",enderType="NPC",enderId=9316,poiX=858,poiY=-2348,wowhead="https://www.wowhead.com/wotlk/quest=3922",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I want to fix this samophlange, but to do that I'm going to need some supplies.  I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.$B$BThe closest place to get them is the Sludge Fen to the east.  The Venture Company usually keeps them in their tool buckets.  Go to the Sludge Fen and look in the tool buckets you find there, then return to me when you've gathered enough nugget slugs.",logDesc="Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens."} end
if not DB[3923] then DB[3923]={id=3923,zoneId=17,name="Rilli Greasygob",level=18,minLevel=10,giver="Wenikee Boltbucket",giverType="NPC",giverId=9316,ender="Rilli Greasygob",enderType="NPC",enderId=9317,rewardNextId=3924,poiX=858,poiY=-2348,wowhead="https://www.wowhead.com/wotlk/quest=3923",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Well, that didn't work.  I put some extra gauges on the samophlange to measure its structural integrity, and they read the integrity at an all-time low.  I could add some more dials and maybe a lever or two to try and fix it, but... I think that might make things even worse.$B$BYou should take the samophlange to Rilli Greasygob.  He used to work for the Venture Company -- if anyone knows how to fix it, it's Rilli.$B$BYou can find him at Nogg's Machine Shop in Orgrimmar, in the Valley of Honor.",logDesc="Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar."} end
if not DB[3924] then DB[3924]={id=3924,zoneId=17,name="Samophlange Manual",level=19,minLevel=10,giver="Rilli Greasygob",giverType="NPC",giverId=9317,ender="Rilli Greasygob",enderType="NPC",enderId=9317,poiX=2046,poiY=-4754,wowhead="https://www.wowhead.com/wotlk/quest=3924",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I think I can fix the samophlange, but I'm going to need the user's manual first.  When I was in the Venture Company I had a rival, Boss Copperplug, who hoarded the secrets of the samophlange, giving out small bits of knowledge on the device to those he trusted.  I wasn't one of the trusted few...$B$BBoss Copperplug used to stay at the Boulder Lode Mine in northeastern Barrens.  Get the manual from him, and if he's given pages from it to anyone, you'll have to collect them too.",logDesc="Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar.",choiceRewards={{id=11855,qty=1},{id=11854,qty=1}}} end
if not DB[3941] then DB[3941]={id=3941,zoneId=490,name="A Gnome's Assistance",level=52,minLevel=47,giver="Linken",giverType="NPC",giverId=8737,ender="J.D. Collie",enderType="NPC",enderId=9117,poiX=-6166,poiY=-1119,wowhead="https://www.wowhead.com/wotlk/quest=3941",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Thinking... Thinking... I know I came here for something important...$B$BI have an idea, $N. In the cave over there is a gnome named J.D. that was very kind to me when I first arrived here. Perhaps in my disoriented state, I might have mentioned something to her.$B$BWhy don't you go ask her if she knows anything? Oh, but be careful -- she's always messing with those crazy glowing crystals I've seen in the crater. I'm not quite sure what she's up to in there!",logDesc="Find J.D. Collie in the cave at Marshal's Refuge."} end
if not DB[3942] then DB[3942]={id=3942,zoneId=490,name="Linken's Memory",level=54,minLevel=47,giver="J.D. Collie",giverType="NPC",giverId=9117,ender="Eridan Bluewind",enderType="NPC",enderId=9116,rewardNextId=4084,poiX=-6033,poiY=-1018,wowhead="https://www.wowhead.com/wotlk/quest=3942",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Oh... Linken? Yeah, he's a funny one. When he first got here, he was mumbling about all kinds of strange things. Probably got bumped on the head pretty hard, I imagine.$B$BSomething he said kinda stuck with me though -- that he was making some sort of totem; said he had to talk to someone named Eridan Bluewind... in a place called Felwood, I think?$B$BI doubt he could tell you much now, though. If you want to know more, maybe you should look for Eridan yourself?",logDesc="Find Eridan Bluewind in southern Felwood."} end
if not DB[3961] then DB[3961]={id=3961,zoneId=490,name="Linken's Adventure",level=54,minLevel=47,giver="J.D. Collie",giverType="NPC",giverId=9117,ender="Linken",enderType="NPC",enderId=8737,rewardNextId=3962,poiX=-6033,poiY=-1018,wowhead="https://www.wowhead.com/wotlk/quest=3961",image="assets/images/quests/placeholder.png",xpDiff=3,desc="To think all this time that the reason Linken came here was to rid us of Blazerunner... He seems like such an ordinary guy, but I did notice that he's not at all interested in any of my experiments or gadgets like most gnomes would be. He must be a true warrior at heart.$B$BBring the totem to him. See if that helps him remember why he came here.",logDesc="Take the Silver Totem of Aquementas to Linken in Marshal's Refuge."} end
if not DB[3962] then DB[3962]={id=3962,zoneId=490,name="It's Dangerous to Go Alone",level=56,minLevel=47,giver="Linken",giverType="NPC",giverId=8737,ender="Linken",enderType="NPC",enderId=8737,poiX=-6166,poiY=-1119,wowhead="https://www.wowhead.com/wotlk/quest=3962",image="assets/images/quests/placeholder.png",xpDiff=6,desc="$N, I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step.$B$BBut I am no longer the hero... You are. All that you have done -- you must finish this now, not me.$B$BBlazerunner guards an artifact called the Golden Flame. It provides power more vast than anything else I have ever known, and it is dangerous in the hands of one with an evil heart.$B$BYou will want to bring others with you -- it's dangerous to go alone. Take this as my advice.",logDesc="Travel to Fire Plume Ridge, south of Marshal's Refuge.$B$BFind Blazerunner and use the totem to remove his protective aura. Once he has been defeated, acquire the Golden Flame from the cave.",rewards={{id=11905,qty=1}},choiceRewards={{id=11902,qty=1},{id=11904,qty=1}}} end
if not DB[3981] then DB[3981]={id=3981,zoneId=1584,name="Commander Gor'shak",level=52,minLevel=48,giver="Galamav the Marksman",giverType="NPC",giverId=9081,ender="Commander Gor'shak",enderType="NPC",enderId=9020,rewardNextId=3982,poiX=-6681,poiY=-2227,wowhead="https://www.wowhead.com/wotlk/quest=3981",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Poor Gargal... didn't even see it coming. WHAM! The arrow landed dead center on the top of his head. He was no genius before but now...$B$B<Galamav grimaces.>$B$BWhen we dislodged the arrow, we noticed a rolled up note attached to the shaft. On the note was a crudely drawn picture of an orc behind bars with the signature of Commander Gor'shak attached.$B$BIf he's still alive in the Depths, you'll have to find him.$B$BA trap you say? Well no kidding, numb hooves! That's why you're going!$B",logDesc="Find Commander Gor'shak in Blackrock Depths.$B$BYou recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort."} end
if not DB[3982] then DB[3982]={id=3982,zoneId=1584,name="What Is Going On?",level=54,minLevel=48,giver="Commander Gor'shak",giverType="NPC",giverId=9020,ender="Commander Gor'shak",enderType="NPC",enderId=9020,rewardNextId=4001,poiX=372,poiY=-178,wowhead="https://www.wowhead.com/wotlk/quest=3982",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I was sent here under the auspices of Thrall. Do you actually think these buffoons could capture me? I allowed myself to be captured so that I could gather intelligence.$B$B<Gor'shak whispers.>$B$BThe Princess of Ironforge has been kidnapped by Emperor Thaurissan. Princess Bronzebeard is in this very city! I bet old Magni's heart almost stopped when he heard that news.$B$B<Gor'shak laughs.>$B$BShhh! Do you hear that? Guards coming! DEFEND YOURSELF!",logDesc="Defend Gor'shak."} end
if not DB[4001] then DB[4001]={id=4001,zoneId=1584,name="What Is Going On?",level=54,minLevel=48,giver="Commander Gor'shak",giverType="NPC",giverId=9020,ender="Thrall",enderType="NPC",enderId=4949,rewardNextId=4002,poiX=372,poiY=-178,wowhead="https://www.wowhead.com/wotlk/quest=4001",image="assets/images/quests/placeholder.png",xpDiff=6,desc="So far, my communication with the dwarf, Kharan, in the cell across the hall, has been limited. I have, however, managed to convince him that I, rather -we- mean him no harm.$B$BGo speak with him and gather as much information about the Princess and her captors as possible. Take that information back to the Warchief.$B$BThrall does not want the Princess harmed, but instead, has some grand plan laid out, which includes her being safely returned to Ironforge. Kharan already knows all of this... Go!$B",logDesc="Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.$B$BYou recall Gor'shak mentioning that Kharan is being held in a cell nearby.$B"} end
if not DB[4002] then DB[4002]={id=4002,zoneId=1584,name="The Eastern Kingdoms",level=54,minLevel=48,giver="Thrall",giverType="NPC",giverId=4949,ender="Thrall",enderType="NPC",enderId=4949,rewardNextId=4003,poiX=1920,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=4002",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You bring excellent information, $N.$B$BAs Warchief, it is my duty to do what is best for the Horde. To ensure that the generations that come after us are not forced into a hopeless existence.$B$BThe opportunity to shape our future alliances has fallen into our collective laps. A move to help the dwarves could greatly strengthen our relationships in the Eastern Kingdoms. This, then, is why you must not fail!$B$BAre you prepared?",logDesc="Speak with Thrall if you are prepared to take on the mission he has planned."} end
if not DB[4003] then DB[4003]={id=4003,zoneId=1584,name="The Royal Rescue",level=59,minLevel=48,giver="Thrall",giverType="NPC",giverId=4949,ender="3",enderType="NPC",enderId=8929,rewardNextId=4004,poiX=1920,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=4003",image="assets/images/quests/placeholder.png",xpDiff=7,desc="This strike against the Dark Iron dwarves, if successful, will send a shockwave throughout their entire kingdom.$B$BPrincess Bronzebeard is under the control of Emperor Thaurissan. To free her, you must kill the Emperor. Be warned, your task is doubly dangerous, as Bronzebeard will attack you without question while under the control of the Emperor.$B$BDO NOT HARM HER!",logDesc="Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell. $B"} end
if not DB[4004] then DB[4004]={id=4004,zoneId=1584,name="The Princess Saved?",level=60,minLevel=48,giver="3",giverType="NPC",giverId=8929,ender="Thrall",enderType="NPC",enderId=4949,poiX=1385,poiY=-831,wowhead="https://www.wowhead.com/wotlk/quest=4004",image="assets/images/quests/placeholder.png",xpDiff=7,money=27000,desc="You have slain my husband, $r! My child will be born into this world without a father.$B$B<Princess Moira points directly at you.>$B$BI assure you, this child will be the next ruler of the kingdom of Ironforge. You and your kind shall be hunted down until the end of days for this wrongful act.$B$B<You think that Princess Moira may be suffering from the residual effect of Thaurissan's spell.>$B$BLeave me be, $r. I am certain your warchief will be eager to hear the results of his meddling.$B",logDesc="Return to Thrall at Grommash Hold in Orgrimmar.$B",choiceRewards={{id=12544,qty=1},{id=12545,qty=1}}} end
if not DB[4005] then DB[4005]={id=4005,zoneId=490,name="Aquementas",level=54,minLevel=47,giver="Eridan Bluewind",giverType="NPC",giverId=9116,ender="J.D. Collie",enderType="NPC",enderId=9117,poiX=4009,poiY=-1311,wowhead="https://www.wowhead.com/wotlk/quest=4005",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Take this bag of supplies with you to Tanaris. Travel to Lost Rigger Cove, and look for a circle of stones.$B$BThe eastmost peninsula is the secret...$B$BFrom this circle only, read from the book of Aquor; summon the only creature that can transform the items you collected into a totem to fight Blazerunner.$B$BAquementas will not be pleased to be awakened, but remember, you must remain in the circle for him to transform the items.",logDesc="Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris.$B$BUse the Book of Aquor to summon Aquementas.$B$BAfter you have the completed totem, take it to J.D. Collie in Marshal's Refuge."} end
if not DB[4021] then DB[4021]={id=4021,zoneId=17,name="Counterattack!",level=20,minLevel=11,giver="Regthar Deathgate",giverType="NPC",giverId=3389,ender="Regthar Deathgate",enderType="NPC",enderId=3389,poiX=-307,poiY=-1972,wowhead="https://www.wowhead.com/wotlk/quest=4021",image="assets/images/quests/placeholder.png",xpDiff=6,money=2500,desc="The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened.  I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance.  My latest report was that, even now, they move against these bunkers, from the west!$B$BFace the Kolkar invaders, and end their threat in the Barrens.  Kill them until their leader, Warlord Krom'zar, appears.  Defeat him and bring me a piece of his banner as proof.$B$BWe're counting on you, $N.",logDesc="Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads."} end
if not DB[4022] then DB[4022]={id=4022,zoneId=46,name="A Taste of Flame",level=54,minLevel=52,giver="Cyrus Therepentous",giverType="NPC",giverId=9459,ender="Cyrus Therepentous",enderType="NPC",enderId=9459,rewardNextId=4024,poiX=-7647,poiY=-3052,wowhead="https://www.wowhead.com/wotlk/quest=4022",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The flight is aware of your work in the Searing Gorge.$B$BShow it to me, $r. The molt, imbecile.",logDesc="Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalaran Windblade.$B"} end
if not DB[4023] then DB[4023]={id=4023,zoneId=46,name="A Taste of Flame",level=54,minLevel=52,giver="Cyrus Therepentous",giverType="NPC",giverId=9459,ender="Cyrus Therepentous",enderType="NPC",enderId=9459,rewardNextId=4024,poiX=-7647,poiY=-3052,wowhead="https://www.wowhead.com/wotlk/quest=4023",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You seek out the Flight? Present to me proof of your worth, mortal.",logDesc="Show Cyrus Therepentous proof of your worth.$B$BYou have a feeling that Cyrus already knows that you are unworthy."} end
if not DB[4024] then DB[4024]={id=4024,zoneId=1584,name="A Taste of Flame",level=58,minLevel=52,giver="Cyrus Therepentous",giverType="NPC",giverId=9459,ender="Cyrus Therepentous",enderType="NPC",enderId=9459,poiX=-7647,poiY=-3052,wowhead="https://www.wowhead.com/wotlk/quest=4024",image="assets/images/quests/placeholder.png",xpDiff=7,money=26500,desc="I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave.$B$BBael'Gar resides in the Depths of Blackrock: A being of pure flame, born of the fires of Ragnaros. Slay Bael'Gar and from his smoldering remains bring for me a piece of his inner fire.$B$BUse the molt on his remains to safely extract the inner flame.$B$BSucceed and be rewarded.",logDesc="Travel to Blackrock Depths and slay Bael'Gar.$B$BYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.$B$BReturn the Encased Fiery Essence to Cyrus Therepentous.$B",choiceRewards={{id=12066,qty=1},{id=12082,qty=1},{id=12083,qty=1}}} end
if not DB[4041] then DB[4041]={id=4041,zoneId=357,name="The Videre Elixir",level=52,minLevel=47,giver="Gregan Brewspewer",giverType="NPC",giverId=7775,ender="Gregan Brewspewer",enderType="NPC",enderId=7775,poiX=-3551,poiY=2306,wowhead="https://www.wowhead.com/wotlk/quest=4041",image="assets/images/quests/placeholder.png",rewards={{id=11243,qty=3}}} end
if not DB[4061] then DB[4061]={id=4061,zoneId=46,name="The Rise of the Machines",level=54,minLevel=52,giver="Hierophant Theodora Mulvadania",giverType="NPC",giverId=9079,ender="Hierophant Theodora Mulvadania",enderType="NPC",enderId=9079,rewardNextId=4062,poiX=-6682,poiY=-2154,wowhead="https://www.wowhead.com/wotlk/quest=4061",image="assets/images/quests/placeholder.png",xpDiff=7,money=16500,desc="The machines made themselves known to us during our initial forays into the Searing Gorge. Upon further investigation we discovered that they were being imported from Burning Steppes, possibly Blackrock Depths. That is what we need you for, $N.$B$BYour first task is to venture to the Burning Steppes and recover elemental shards from the rock automatons and lesser rock creations of the region. Once you have collected a sufficient amount, return to me and I shall determine their source of origin.$B",logDesc="Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.$B$BYou recall Theodora mentioning the golems and elementals of that region as being a source for these shards."} end
if not DB[4062] then DB[4062]={id=4062,zoneId=3,name="The Rise of the Machines",level=54,minLevel=52,giver="Hierophant Theodora Mulvadania",giverType="NPC",giverId=9079,ender="Lotwil Veriatus",enderType="NPC",enderId=2921,rewardNextId=4063,poiX=-6682,poiY=-2154,wowhead="https://www.wowhead.com/wotlk/quest=4062",image="assets/images/quests/placeholder.png",xpDiff=2,desc="G.L.A.$B$BThose are the 'initials' imprinted on the elemental shards. Below the initials are a rank marking of some sort. The machinations you destroyed in the Burning Steppes were of 'Rank IV.' I assume that this is a lowly rank.$B$BTake this shard sample to Lotwil Veriatus in the camp to the east. He is a scholar of some renown in the field of elemental sciences. He may be able to assist us in our search.",logDesc="Take the Elemental Shard Sample to Lotwil Veriatus.$B$BYou recall Theodora saying that Lotwil was stationed in a camp to the east.$B"} end
if not DB[4063] then DB[4063]={id=4063,zoneId=1584,name="The Rise of the Machines",level=58,minLevel=52,giver="Lotwil Veriatus",giverType="NPC",giverId=2921,ender="Lotwil Veriatus",enderType="NPC",enderId=2921,poiX=-6634,poiY=-2725,wowhead="https://www.wowhead.com/wotlk/quest=4063",image="assets/images/quests/placeholder.png",xpDiff=7,money=26500,desc="This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him.$B$BHe was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs. It seems that the wicked always find a way to escape justice.$B$BIf this is Argelmach's handiwork then he must be destroyed. I will need samplings of his latest creations. With the proper samples, I may be able to stop this uprising. The creations guard Argelmach in Blackrock Depths.",logDesc="Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic. ",choiceRewards={{id=12109,qty=1},{id=12110,qty=1},{id=12108,qty=1},{id=12111,qty=1}}} end
if not DB[4081] then DB[4081]={id=4081,zoneId=1584,name="KILL ON SIGHT: Dark Iron Dwarves",level=52,minLevel=48,ender="Warlord Goretooth",enderType="NPC",enderId=9077,wowhead="https://www.wowhead.com/wotlk/quest=4081",image="assets/images/quests/placeholder.png",xpDiff=7,money=15500,desc="By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:$B$BAny and all of General Angerforge's forces within Blackrock Depths must be annihilated.$B$BAngerforge's men are ruthless killers, responsible for the mass murder of the 109th division of the Kargath Expeditionary Force. Heroes are warned to exercise extreme caution when confronting these brutes.$B$BAny person who destroys the first line of General Angerforge's forces in Blackrock Depths shall receive a tribute.",logDesc="Venture to Blackrock Depths and destroy the vile aggressors!$B$BWarlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.$B"} end
if not DB[4082] then DB[4082]={id=4082,zoneId=1584,name="KILL ON SIGHT: High Ranking Dark Iron Officials",level=54,minLevel=48,ender="Warlord Goretooth",enderType="NPC",enderId=9077,wowhead="https://www.wowhead.com/wotlk/quest=4082",image="assets/images/quests/placeholder.png",xpDiff=7,money=16500,desc="By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:$B$BHead of the K.E.F. reconnaissance division, Grandmaster Lexlort, has returned with news of the whereabouts of high ranking Dark Iron officials. Through locked gate, near the heart of the city, they train their forces to snuff out our men. Travel to Blackrock Depths and destroy them!$B$BCompletion of this mission will result in a tribute.$B",logDesc="Venture to Blackrock Depths and destroy the vile aggressors!$B$BWarlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete."} end
if not DB[4083] then DB[4083]={id=4083,zoneId=1584,name="The Spectral Chalice",level=55,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=4083",image="assets/images/quests/placeholder.png",xpDiff=5} end
if not DB[4084] then DB[4084]={id=4084,zoneId=490,name="Silver Heart",level=54,minLevel=47,giver="Eridan Bluewind",giverType="NPC",giverId=9116,ender="Eridan Bluewind",enderType="NPC",enderId=9116,rewardNextId=4005,poiX=4009,poiY=-1311,wowhead="https://www.wowhead.com/wotlk/quest=4084",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I do not know the one you speak of, $N.$B$BBut worry not; if your friend was on a journey to find me, I do know what it was he desired.$B$BIn the heart of Un'Goro Crater dwells evil of the purest form. This evil takes the shape of an elemental called Blazerunner... protected by an aura that none can dispel...$B$BNone... except those with enough power to do so. I can teach you of this power, $N.$B$BFirst, do as I ask. Collect 11 Silvery Claws and 1 Irontree Heart from the creatures in Felwood, then return.",logDesc="Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood."} end
if not DB[4101] then DB[4101]={id=4101,zoneId=361,name="Cleansing Felwood",level=55,minLevel=48,giver="Arathandris Silversky",giverType="NPC",giverId=9528,ender="Arathandris Silversky",enderType="NPC",enderId=9528,poiX=3805,poiY=-1472,wowhead="https://www.wowhead.com/wotlk/quest=4101",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!$B$BTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.",logDesc="Bring 15 Blood Amber to Arathandris Silversky in Felwood."} end
if not DB[4102] then DB[4102]={id=4102,zoneId=361,name="Cleansing Felwood",level=55,minLevel=48,giver="Maybess Riverbreeze",giverType="NPC",giverId=9529,ender="Maybess Riverbreeze",enderType="NPC",enderId=9529,poiX=3947,poiY=-1046,wowhead="https://www.wowhead.com/wotlk/quest=4102",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!$B$BTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.",logDesc="Bring 15 Blood Amber to Maybess Riverbreeze in Felwood."} end
