if not DB[4120] then DB[4120]={id=4120,zoneId=357,name="The Strength of Corruption",level=52,minLevel=47,giver="Talo Thornhoof",giverType="NPC",giverId=7776,ender="Talo Thornhoof",enderType="NPC",enderId=7776,poiX=-4398,poiY=147,wowhead="https://www.wowhead.com/wotlk/quest=4120",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Being a hunter, I strive to emulate the strengths I see in my opponents. It is possible to turn the battle in your favor by simply knowing your enemy well, $N.$B$BIn a place called Felwood, north of Ashenvale, the creatures have been tainted by a substance called fel. The bears and wolves have been driven mad by it, but I believe that they have also grown even stronger as well.$B$BGo, $N. Travel to Felwood and face these beasts. Learn for yourself if they are truly as strong as I believe.",logDesc="Talo Thornhoof at Camp Mojache in Feralas wants you to kill 12 Angerclaw Grizzlies and 12 Felpaw Ravagers in Felwood."} end
if not DB[4121] then DB[4121]={id=4121,zoneId=1584,name="Precarious Predicament",level=58,minLevel=52,giver="Grark Lorkrub",giverType="NPC",giverId=9520,ender="Lexlort",enderType="NPC",enderId=9080,poiX=-7700,poiY=-1444,wowhead="https://www.wowhead.com/wotlk/quest=4121",image="assets/images/quests/placeholder.png",xpDiff=6,money=26500,desc="Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence?$B$BYou will be destroyed!$B",logDesc="Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.$B$BYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.$B$BYou will also be required to hand over your Thorium Shackles to Lexlort."} end
if not DB[4122] then DB[4122]={id=4122,zoneId=1584,name="Grark Lorkrub",level=58,minLevel=52,giver="Lexlort",giverType="NPC",giverId=9080,ender="Grark Lorkrub",enderType="NPC",enderId=9520,poiX=-6679,poiY=-2225,wowhead="https://www.wowhead.com/wotlk/quest=4122",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I tracked him across the Searing Gorge, through the mountain, and into the Burning Steppes. That traitor was caught red-handed giving the Blackrock orcs vital information about our day to day operations. I'm speaking of Grark Lorkrub.$B$BHe now sits in the Burning Steppes, safely under their protection - or so he thinks.$B$BTake these shackles, $N. Find Grark, place the shackles on him and lead him through Blackrock Mountain. Do this and a tribute is yours.$B",logDesc="Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.$B$BWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.$B"} end
if not DB[4123] then DB[4123]={id=4123,zoneId=1584,name="The Heart of the Mountain",level=55,minLevel=50,giver="Maxwort Uberglint",giverType="NPC",giverId=9536,ender="Maxwort Uberglint",enderType="NPC",enderId=9536,poiX=-7498,poiY=-2175,wowhead="https://www.wowhead.com/wotlk/quest=4123",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.$B$BSo I must resort to force.$B$BFight your way to the Lower Vault of Blackrock Depths, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!$B$BGood luck.",logDesc="Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes."} end
if not DB[4124] then DB[4124]={id=4124,zoneId=357,name="The Missing Courier",level=43,minLevel=40,giver="Latronicus Moonspear",giverType="NPC",giverId=7877,ender="Ginro Hearthkindle",enderType="NPC",enderId=7880,rewardNextId=4125,poiX=-4506,poiY=3330,wowhead="https://www.wowhead.com/wotlk/quest=4124",image="assets/images/quests/placeholder.png",xpDiff=1,desc="An associate of mine, Ginro Hearthkindle, is looking for assistance concerning the location of a courier and the parcels he was carrying.  It has been a week or so since the courier went missing; our own searches have proved fruitless, and we're at an impasse.  Unfortunately, I have had to declare the courier as missing in action.$B$BIf you have the time and resources to spare, please speak with Ginro.  He should be here in the Stronghold - perhaps in his quarters.",logDesc="Speak with Ginro Hearthkindle in Feathermoon Stronghold."} end
if not DB[4125] then DB[4125]={id=4125,zoneId=357,name="The Missing Courier",level=43,minLevel=40,giver="Ginro Hearthkindle",giverType="NPC",giverId=7880,rewardNextId=4127,poiX=-4458,poiY=3227,wowhead="https://www.wowhead.com/wotlk/quest=4125",image="assets/images/quests/placeholder.png",xpDiff=4,desc="It's been about a week since Raschal, the courier, set out for Thalanaar.  He knows Feralas well; he's been with us since General Feathermoon led the expeditionary forces here.  I know his plan was to take a row boat down the coast and try and traverse across southern Feralas to avoid the Horde camp.$B$BI couldn't find his boat, but maybe you can.  Maybe it is hidden, or maybe it was sunk.  Regardless, it might hold a clue as to where he is.  If you uncover something, please let me know.",logDesc="Locate the courier's boat somewhere along the coast of Feralas."} end
if not DB[4126] then DB[4126]={id=4126,zoneId=1584,name="Hurley Blackbreath",level=55,minLevel=50,giver="Ragnar Thunderbrew",giverType="NPC",giverId=1267,ender="Ragnar Thunderbrew",enderType="NPC",enderId=1267,poiX=-5596,poiY=-504,wowhead="https://www.wowhead.com/wotlk/quest=4126",image="assets/images/quests/placeholder.png",xpDiff=7,money=16500,desc="The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager.  The villains!  They don't deserve such a fine brew!$B$B$N, I have a tough task for you.  Go to the Blackrock Depths in the Burning Steppes, destroy any kegs of Thunderbrew Lager you find, and bring back our recipe for Thunderbrew Lager!$B$BPlease, get that recipe back, even if you have to turn Blackrock Depths upside down to do it!",logDesc="Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.",rewards={{id=12003,qty=10}},choiceRewards={{id=11964,qty=1},{id=12000,qty=1}}} end
if not DB[4127] then DB[4127]={id=4127,zoneId=357,name="Boat Wreckage",level=44,minLevel=40,ender="Ginro Hearthkindle",enderType="NPC",enderId=7880,rewardNextId=4129,wowhead="https://www.wowhead.com/wotlk/quest=4127",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Running your hand along the mud, your fingers graze the handle of a knife.  It looks well cared for, and it might be safe to assume that whoever was on the boat might have lost it.  Perhaps the large chunk of the missing boat might have something to do with the loss.$B$BYou grab the knife, remembering that Ginro Hearthkindle in the Feathermoon Stronghold instructed you to return to him with any found clues.  You get the feeling, however, that you are not quite alone in the water...",logDesc="Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found."} end
if not DB[4128] then DB[4128]={id=4128,zoneId=1584,name="Ragnar Thunderbrew",level=55,minLevel=50,giver="Enohar Thunderbrew",giverType="NPC",giverId=9540,ender="Ragnar Thunderbrew",enderType="NPC",enderId=1267,rewardNextId=4126,poiX=-11027,poiY=-3373,wowhead="https://www.wowhead.com/wotlk/quest=4128",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Ho, $n.  I heard that Ragnar Thunderbrew is steaming mad about someone stealing his ale.  He's looking for stalwart adventurers, and willing to pay plenty.$B$BTalk to Ragnar if you're interested.  He's at the Thunderbrew Distillery in Kharanos, in Dun Morogh.",logDesc="Speak with Ragnar Thunderbrew."} end
if not DB[4129] then DB[4129]={id=4129,zoneId=357,name="The Knife Revealed",level=44,minLevel=40,giver="Ginro Hearthkindle",giverType="NPC",giverId=7880,ender="Quintis Jonespyre",enderType="NPC",enderId=7879,poiX=-4458,poiY=3227,wowhead="https://www.wowhead.com/wotlk/quest=4129",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Stronghold's resident druid, Quintis Jonespyre, has some... unusual skills.  One of them involves psychometry - the ability to reveal an item's history by touch.  Don't ask me how he does it; I chalk it up to magic I do not and choose not to understand.  I do know, however, two things: one, I've seen it work and two, the bum owes me.$B$BTake the knife up to Quint in his little tree-house here, and tell him for me that his Kalimdor Hold 'Em debt will be paid if he works his mojo on that knife.",logDesc="Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold."} end
if not DB[4130] then DB[4130]={id=4130,zoneId=357,name="Psychometric Reading",level=44,minLevel=40,giver="Quintis Jonespyre",giverType="NPC",giverId=7879,ender="Ginro Hearthkindle",enderType="NPC",enderId=7880,rewardNextId=4131,poiX=-4396,poiY=3187,wowhead="https://www.wowhead.com/wotlk/quest=4130",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I'm a little wobbly still, sorry.  Anyway, I received some useful visions.$B$BRaschal takes two large leather backpacks from his boat and goes inland; he returns to the boat, however.  I see gnoll scalps... he ran into some gnolls - Woodpaw I think they're called.  He's very worried - almost terrified - about something.  So much so, that he is not paying attention to water elementals forming behind him.  The images... stop there.$B$BI need to rest, sorry $N.  Tell Gin what I've seen.  He needs to know.",logDesc="Speak with Ginro Hearthkindle in Feathermoon Stronghold."} end
if not DB[4131] then DB[4131]={id=4131,zoneId=357,name="The Woodpaw Gnolls",level=44,minLevel=40,giver="Ginro Hearthkindle",giverType="NPC",giverId=7880,rewardNextId=4135,poiX=-4458,poiY=3227,wowhead="https://www.wowhead.com/wotlk/quest=4131",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Our \"friends\" the Woodpaw might have gotten Raschal in the end, but something tells me that's not what occurred.  Still, they're the best place to start looking.$B$BI wish I had clearer insight as to what to do, but all I have right now is 'Search the Woodpaw camps - go.'  I do know that gnolls will keep items they scavenge and fight over them; maybe they ran across the backpacks Quint mentioned.  I hadn't risked a head-on fight in past searches, but with Quint's vision on this I say rip into them.",logDesc="Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself."} end
if not DB[4132] then DB[4132]={id=4132,zoneId=1584,name="Operation: Death to Angerforge",level=58,minLevel=52,giver="Warlord Goretooth",giverType="NPC",giverId=9077,ender="Warlord Goretooth",enderType="NPC",enderId=9077,poiX=-6678,poiY=-2224,wowhead="https://www.wowhead.com/wotlk/quest=4132",image="assets/images/quests/placeholder.png",xpDiff=7,money=26500,desc="You have done an exemplary job, $N. It is now time to send you on your last mission.$B$BGeneral Angerforge, the Dark Iron responsible for coordinating the attacks on the 109th division of the K.E.F. and the mass slaughter of our forces must be brought to justice.$B$BThis will undoubtedly be your most grueling mission, but should you succeed, you will be richly rewarded.$B",logDesc="Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.",rewards={{id=12059,qty=1}}} end
if not DB[4133] then DB[4133]={id=4133,zoneId=1584,name="Vivian Lagrave",level=55,minLevel=50,giver="Apothecary Zinge",giverType="NPC",giverId=5204,ender="Shadowmage Vivian Lagrave",enderType="NPC",enderId=9078,rewardNextId=4134,poiX=1443,poiY=392,wowhead="https://www.wowhead.com/wotlk/quest=4133",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Shadowmaster Vivian Lagrave is in need of your services.  She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths.$B$BSpeak with Vivian.  She awaits you.",logDesc="Speak with Shadowmaster Vivian Lagrave in Kargath."} end
if not DB[4134] then DB[4134]={id=4134,zoneId=1584,name="Lost Thunderbrew Recipe",level=55,minLevel=50,giver="Shadowmage Vivian Lagrave",giverType="NPC",giverId=9078,ender="Shadowmage Vivian Lagrave",enderType="NPC",enderId=9078,poiX=-6682,poiY=-2151,wowhead="https://www.wowhead.com/wotlk/quest=4134",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="It is rumored that the Dark Iron Hurley Blackbreath has stolen a recipe for ale.  This ale, Thunderbrew Lager, is said to infuse its imbiber with great strength and courage.  We wish to study the drink.  Perhaps, we will find other applications for its virtues... applications more in line with Forsaken objectives.$B$BDelve into Blackrock Depths, find Hurley, take from him the recipe for Thunderbrew lager and bring it to me.$B$BAnd to find him, you may have to entice him by threatening his precious ale.",logDesc="Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.",rewards={{id=3928,qty=5},{id=6149,qty=5}},choiceRewards={{id=11964,qty=1},{id=12000,qty=1}}} end
if not DB[4135] then DB[4135]={id=4135,zoneId=357,name="The Writhing Deep",level=46,minLevel=40,rewardNextId=4265,wowhead="https://www.wowhead.com/wotlk/quest=4135",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Inside the backpacks are two items: the first is a parcel of goods that was bound for Thalanaar, and the second is a note hastily penned to an unknown reader.$B$BThe note tells of discovering insidious bug-like creatures south of the gnoll camps in a place called the Writhing Deep.  The author felt the need to investigate it personally, as though it was a serious threat to all of Feralas.  The note is signed, \"Raschal of Feathermoon\".$B$BIt would seem that you have located where Raschal ultimately went.",logDesc="Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep.  According to the note, it is located to the south of the Woodpaw gnoll camps."} end
if not DB[4136] then DB[4136]={id=4136,zoneId=1584,name="Ribbly Screwspigot",level=53,minLevel=48,giver="Yuka Screwspigot",giverType="NPC",giverId=9544,ender="Yuka Screwspigot",enderType="NPC",enderId=9544,poiX=-7460,poiY=-2202,wowhead="https://www.wowhead.com/wotlk/quest=4136",image="assets/images/quests/placeholder.png",xpDiff=7,money=6000,desc="My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another.$B$BWell, his last scheme must have been his worst, because Baron Revilgaz of Booty Bay just put a price on poor Ribbly's head.  I can't tell you how happy this makes the Screwspigots!  Our little Ribbly's finally worth something!$B$BBut now he's hiding out, deep in Blackrock Depths.  Please, find him and bring him to me!$B$BOr, if he won't come, then that's ok... just bring me his head.",logDesc="Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.",choiceRewards={{id=11865,qty=1},{id=11963,qty=1},{id=12049,qty=1}}} end
if not DB[4141] then DB[4141]={id=4141,zoneId=490,name="Muigin and Larion",level=52,minLevel=47,giver="Muigin",giverType="NPC",giverId=9119,ender="Muigin",enderType="NPC",enderId=9119,rewardNextId=4142,poiX=-6204,poiY=-1055,wowhead="https://www.wowhead.com/wotlk/quest=4141",image="assets/images/quests/placeholder.png",xpDiff=5,desc="See Larion over there? It's HIS fault we're here!$B$BI told him we were going the wrong way, but would he listen? And would you believe that he's the one that won't speak to me? Well, until he changes his mind, let's have a bit of fun with him.$B$BHave you noticed the strange plant-like creatures around here? They're nothing but trouble, really, but I think if trained properly, I could get them to obey commands.$B$BFirst thing though, I'll need some samples to study. Do you think you could collect some?",logDesc="Collect 15 Bloodpetals and return to Muigin."} end
if not DB[4142] then DB[4142]={id=4142,zoneId=490,name="A Visit to Gregan",level=52,minLevel=47,giver="Muigin",giverType="NPC",giverId=9119,ender="Gregan Brewspewer",enderType="NPC",enderId=7775,rewardNextId=4143,poiX=-6204,poiY=-1055,wowhead="https://www.wowhead.com/wotlk/quest=4142",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I'm not quite sure what to make of this, $N. The plants... they seem to have some minimal intelligence.$B$BI'm no expert, though. But, I do know someone that is!$B$BHead to northern Feralas, and look for a buddy of mine named Gregan Brewspewer. He's an expert on this sort of thing.$B$BI'm sure Gregan can help us out here. You'll find him out in the wilderness; he's not the type to live in a big city.",logDesc="Take a Bloodpetal to Gregan Brewspewer in Feralas."} end
if not DB[4143] then DB[4143]={id=4143,zoneId=490,name="Haze of Evil",level=52,minLevel=47,giver="Gregan Brewspewer",giverType="NPC",giverId=7775,ender="Muigin",enderType="NPC",enderId=9119,poiX=-3551,poiY=2306,wowhead="https://www.wowhead.com/wotlk/quest=4143",image="assets/images/quests/placeholder.png",xpDiff=7,money=7500,desc="To tell you the truth, $N, I've never seen any plants like this in my travels. Perhaps I should take a trip to this crater...$B$BAt any rate, I think I know just the thing Muigin's looking for -- Atal'ai haze. It's horrid stuff, hard to collect, but it's just what he needs to control the little monsters.$B$BYou'll need to visit the temple of Atal'Hakkar in the Swamp of Sorrows. The Atal'ai Haze can be collected from the deep lurkers, murk worms, or oozes found there. Good luck, $N!",logDesc="Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater."} end
if not DB[4144] then DB[4144]={id=4144,zoneId=490,name="Bloodpetal Sprouts",level=53,minLevel=47,giver="Muigin",giverType="NPC",giverId=9119,ender="Muigin",enderType="NPC",enderId=9119,poiX=-6204,poiY=-1055,wowhead="https://www.wowhead.com/wotlk/quest=4144",image="assets/images/quests/placeholder.png",xpDiff=4} end
if not DB[4145] then DB[4145]={id=4145,zoneId=490,name="Larion and Muigin",level=52,minLevel=47,giver="Larion",giverType="NPC",giverId=9118,ender="Larion",enderType="NPC",enderId=9118,rewardNextId=4147,poiX=-6182,poiY=-1151,wowhead="https://www.wowhead.com/wotlk/quest=4145",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="See Muigin over there? It's HIS fault we're lost!$B$BI'm the one that knew the way, but he insisted he knew a shortcut, and we ended up here!$B$BTo make matters worse, now he keeps sending his crazy plant pests to annoy me. I'm so angry that I'm not planning on talking to him any time soon, but these pests are too much to handle.$B$BWhy don't we try to limit his supply, first thing. Go out and hunt some Bloodpetals, then return to me.",logDesc="Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge."} end
if not DB[4146] then DB[4146]={id=4146,zoneId=1417,name="Zapper Fuel",level=52,minLevel=47,giver="Liv Rizzlefix",giverType="NPC",giverId=8496,ender="Larion",enderType="NPC",enderId=9118,poiX=-1004,poiY=-3705,wowhead="https://www.wowhead.com/wotlk/quest=4146",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You're in luck, $n! I've been working on some of my own experiments while Marvon's been gone, and one of them is a short range bug zapper. With just a few adjustments, it should be great for ridding yourself of those Bloodpetal pests.$B$BI can let you have one of my zapper prototypes, but you'll still need to collect the fuel. You can get the necessary Atal'ai haze that the zapper needs in the temple of Atal'Hakkar. The deep lurkers, murk worms, or oozes are the ones you'll need to get it from.",logDesc="Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge."} end
if not DB[4147] then DB[4147]={id=4147,zoneId=490,name="Marvon's Workshop",level=52,minLevel=47,giver="Larion",giverType="NPC",giverId=9118,ender="Liv Rizzlefix",enderType="NPC",enderId=8496,rewardNextId=4146,poiX=-6182,poiY=-1151,wowhead="https://www.wowhead.com/wotlk/quest=4147",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I managed to spy on what Muigin was doing, and he's actually growing the darn things over there!$B$BI think the only solution here is to... no, not go talk to him... What are you thinking? The solution is to fight back!$B$BWe'll need the help of my friend, Marvon, who has a workshop in Ratchet.  I'm sure he'll be able to create some sort of gadget that will help us.",logDesc="Travel to Marvon Rivetseeker's workshop in Ratchet."} end
if not DB[4148] then DB[4148]={id=4148,zoneId=490,name="Bloodpetal Zapper",level=53,minLevel=47,giver="Larion",giverType="NPC",giverId=9118,ender="Larion",enderType="NPC",enderId=9118,poiX=-6182,poiY=-1151,wowhead="https://www.wowhead.com/wotlk/quest=4148",image="assets/images/quests/placeholder.png",xpDiff=4,money=16000,rewards={{id=11320,qty=1}}} end
if not DB[4161] then DB[4161]={id=4161,zoneId=-304,name="Recipe of the Kaldorei",level=7,minLevel=1,giver="Zarrin",giverType="NPC",giverId=6286,ender="Zarrin",enderType="NPC",enderId=6286,poiX=9751,poiY=906,wowhead="https://www.wowhead.com/wotlk/quest=4161",image="assets/images/quests/placeholder.png",xpDiff=5,money=85,desc="Long ago, the night elves were called the kaldorei, a name that means \"children of the stars.\" Learning of the past is an important step in your path as a $c, $N, so listen well to what I have to tell you.$B$BThe kaldorei have always taken much pride in their harmonious relationship with nature. This means that we only take from nature what is necessary, and that we return in kind. This balance has afforded us much, $N.$B$BGo out and collect seven small spider legs -- no more than that, and return to me.",logDesc="Collect 7 Small Spider Legs for Zarrin in Dolanaar.",rewards={{id=5482,qty=1},{id=5472,qty=3}}} end
if not DB[4181] then DB[4181]={id=4181,zoneId=-201,name="Goblin Engineering",level=-1,minLevel=10,giver="Lilliam Sparkspindle",giverType="NPC",giverId=5518,ender="Nixx Sprocketspring",enderType="NPC",enderId=8126,poiX=-8347,poiY=644,wowhead="https://www.wowhead.com/wotlk/quest=4181",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.$B$B$N, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.",logDesc="If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."} end
if not DB[4182] then DB[4182]={id=4182,zoneId=46,name="Dragonkin Menace",level=54,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4182",image="assets/images/quests/placeholder.png",xpDiff=5,money=16500,desc="Life in the Burning Steppes is rife with conflict.$B$BJust look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range.$B$BEnough lamenting! We have a problem, $N. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things.$B",logDesc="Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake."} end
if not DB[4183] then DB[4183]={id=4183,zoneId=46,name="The True Masters",level=54,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4183",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We had always assumed that the Blackrock orcs were a product of their savage upbringing. What we have found here, in their homeland, tells us another story.$B$BIndeed, it is bloodlust and thirst for conflict that empowers them, but the black dragonflight are the beings whom control the orcs of Blackrock. We suspect that it is the black dragonflight that fuels them with rage and hostility.$B$BTake this letter to Magistrate Solomon. He will know what must be done.$B$B<Helendis hands you a sealed letter.>",logDesc="Travel to Lakeshire in Redridge Mountains and deliver Helendis Riverhorn's Letter to Magistrate Solomon. "} end
if not DB[4184] then DB[4184]={id=4184,zoneId=46,name="The True Masters",level=54,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4184",image="assets/images/quests/placeholder.png",xpDiff=4,desc="This is grim news, $N. To discover that our mortal enemies are merely pawns of a much greater threat is disheartening. There is no possible way that Lakeshire could survive an attack from both the Blackrock orcs and the black dragonflight. Should Lakeshire fall to this menace, Darkshire would fall next, and then what? Goldshire? Stormwind itself?$B$BYou must take this information to King Varian Wrynn in Stormwind at once! If this does not merit the aid of Stormwind, nothing will and all is lost.$B",logDesc="Travel to Stormwind and deliver Solomon's Plea to King Varian Wrynn.$B$BKing Varian Wrynn resides in Stormwind Keep."} end
if not DB[4185] then DB[4185]={id=4185,zoneId=46,name="The True Masters",level=54,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4185",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Solomon paints a dreary picture. Still, we cannot afford to send our thinly spread troops to the aid of Lakeshire on speculation. I will need proof of these claims before I can act.$B$BSpeak with Lady Prestor, $N. She is a learned woman and knows much of dragons and dragonkin. She may be able to shed some light on this situation.$B",logDesc="Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor."} end
if not DB[4186] then DB[4186]={id=4186,zoneId=46,name="The True Masters",level=54,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4186",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I am going to empower you as an acting deputy of Stormwind, $N.$B$BReturn to Magistrate Solomon in Lakeshire and deliver this decree.",logDesc="Take Wrynn's Decree to Magistrate Solomon in Lakeshire.$B"} end
if not DB[4201] then DB[4201]={id=4201,zoneId=1584,name="The Love Potion",level=54,minLevel=50,giver="Mistress Nagmara",giverType="NPC",giverId=9500,ender="Mistress Nagmara",enderType="NPC",enderId=9500,poiX=867,poiY=-201,wowhead="https://www.wowhead.com/wotlk/quest=4201",image="assets/images/quests/placeholder.png",xpDiff=7,money=8000,desc="Oh, the pains of love!  My dear Private Rocknot is immune to my charms.  I am spurned!  It's maddening!$B$BYou must help me!  We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart.  To make it, I need these items: the herb gromsblood, giant silver veins from the cliff giants of Azshara, and water from the Golakka Springs Crater in Un'Goro.  You can place the water in this vial.$B$BPlease, $N, help a poor soul in her quest for happiness!",logDesc="Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.",choiceRewards={{id=11962,qty=1},{id=11866,qty=1}}} end
if not DB[4221] then DB[4221]={id=4221,zoneId=361,name="Corrupted Windblossom",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4221",image="assets/images/quests/placeholder.png"} end
if not DB[4222] then DB[4222]={id=4222,zoneId=361,name="Corrupted Windblossom",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4222",image="assets/images/quests/placeholder.png"} end
if not DB[4223] then DB[4223]={id=4223,zoneId=46,name="The True Masters",level=54,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4223",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Magistrate Solomon sighs.>$B$BYou must return to the Burning Steppes, $N. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck.",logDesc="Speak with Marshal Maxwell in the Burning Steppes."} end
if not DB[4224] then DB[4224]={id=4224,zoneId=46,name="The True Masters",level=54,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4224",image="assets/images/quests/placeholder.png",xpDiff=1,desc="What? You thought you were the first? How many soldiers must we lose before Stormwind acts?$B$BWe had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information.$B$BWhat we need is that documentation. Speak with Ragged John, $N. He was with Windsor when they were attacked by a Blackrock raiding party.  He was last seen in a cave to the north.",logDesc="Speak with Ragged John."} end
if not DB[4241] then DB[4241]={id=4241,zoneId=1584,name="Marshal Windsor",level=54,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4241",image="assets/images/quests/placeholder.png",xpDiff=7,desc="So that good for nothing coward says that Windsor is alive, eh?$B$BSuit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof.$B$B<Maxwell laughs.>$B$BI bet you are getting tired of hearing that, aren't you?",logDesc="Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.$B$BYou recall Ragged John talking about Windsor being dragged off to a prison."} end
if not DB[4242] then DB[4242]={id=4242,zoneId=1584,name="Abandoned Hope",level=54,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4242",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat.$B$BHe is a blind buffoon. Proof stands two feet away from him and he does not see.$B$BAs for my data, it's lost. Gone. Unrecoverable.$B$BShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes.$B$BLeave me, $N.",logDesc="Give Marshal Maxwell at Morgan's Vigil in the Burning Steppes the bad news.",choiceRewards={{id=12018,qty=1},{id=12021,qty=1},{id=12041,qty=1}}} end
if not DB[4243] then DB[4243]={id=4243,zoneId=490,name="Chasing A-Me 01",level=53,minLevel=48,giver="Karna Remtravel",giverType="NPC",giverId=9618,ender="A-Me 01",enderType="NPC",enderId=9623,rewardNextId=4244,poiX=-6298,poiY=-1183,wowhead="https://www.wowhead.com/wotlk/quest=4243",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Unfortunately, something's happened to one of my greatest inventions. You've seen mechanical squirrels, yes? Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.$B$BShe has scrying gems for eyes so I could see everything she saw. She made it to Fungal Rock--the apes' lair--just east of here, and that's when I lost contact. The last thing I saw was one of their alpha males rushing up to say hello to her!$B$BCan you help me find her?",logDesc="Find A-Me 01 in Un'Goro Crater."} end
if not DB[4244] then DB[4244]={id=4244,zoneId=490,name="Chasing A-Me 01",level=53,minLevel=48,giver="A-Me 01",giverType="NPC",giverId=9623,ender="A-Me 01",enderType="NPC",enderId=9623,poiX=-6380,poiY=-1970,wowhead="https://www.wowhead.com/wotlk/quest=4244",image="assets/images/quests/placeholder.png",xpDiff=4,desc="A little further investigation shows a panel that slides open. Clearly written above some wiring is the statement, \"Replace Mithril Casing And Turn Power Off Then On.\"$B$BTaking a moment to replace the panel, you wonder if it'll be that simple to fix A-Me 01 and get her back to Karna Remtravel near Marshall's Refuge.$B$BOnly trying it will tell.",logDesc="Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater."} end
if not DB[4245] then DB[4245]={id=4245,zoneId=490,name="Chasing A-Me 01",level=53,minLevel=48,giver="A-Me 01",giverType="NPC",giverId=9623,ender="Karna Remtravel",enderType="NPC",enderId=9618,poiX=-6380,poiY=-1970,wowhead="https://www.wowhead.com/wotlk/quest=4245",image="assets/images/quests/placeholder.png",xpDiff=6,money=16000,desc="Checking to see if you're prepared to lead A-Me 01 back to Karna Remtravel, you flip the switch to the \"Off\" position. Glancing around once again to make sure none of the gorillas are coming, you prepare to see what happens when you flip the switch back to the \"On\" position.$B$BThis is your last chance... are you sure this is what you want to do?",logDesc="Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater."} end
if not DB[4261] then DB[4261]={id=4261,zoneId=361,name="Ancient Spirit",level=56,minLevel=49,giver="Arei",giverType="NPC",giverId=9598,ender="Kayneth Stillwind",enderType="NPC",enderId=3848,wowhead="https://www.wowhead.com/wotlk/quest=4261",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos...$B$BThe skull of Gul'dan ensured that none were spared here. All fell to the corruption.$B$BEven now, as a spirit, I still find myself trapped, bearing the suffering of this land. Help me find my way home. Please, $N, tell me you will lead an ancient spirit away from here, where I may finally rest.$B$BOnce I am free, seek out Kayneth Stillwind, a druid that resides in Forest Song, to the east.",logDesc="Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale.",choiceRewards={{id=11873,qty=1},{id=11874,qty=1}}} end
if not DB[4262] then DB[4262]={id=4262,zoneId=25,name="Overmaster Pyron",level=52,minLevel=48,giver="Jalinda Sprig",giverType="NPC",giverId=9561,ender="Jalinda Sprig",enderType="NPC",enderId=9561,rewardNextId=4263,poiX=-8399,poiY=-2769,wowhead="https://www.wowhead.com/wotlk/quest=4262",image="assets/images/quests/placeholder.png",xpDiff=5,money=15500,desc="The last five of my mages that went snooping around in Blackrock Mountain came back extra crispy with a permanent orange gnomefro - or worse.$B$B<Jalinda picks up some ashes from the ground and releases them into the air.>$B$BOne nasty bugger in particular, Overmaster Pyron, seems to be causing quite a bit of trouble. We need that elemental terminated so that our expedition crew can make its way into Blackrock Depths!$B$BHe guards the entrance at the Blackrock Quarry.",logDesc="Slay Overmaster Pyron.$B$BYou recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?"} end
if not DB[4263] then DB[4263]={id=4263,zoneId=1584,name="Incendius!",level=56,minLevel=48,giver="Jalinda Sprig",giverType="NPC",giverId=9561,ender="Jalinda Sprig",enderType="NPC",enderId=9561,poiX=-8399,poiY=-2769,wowhead="https://www.wowhead.com/wotlk/quest=4263",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="Are you sure Pyron said 'Incendius' when he died?$B$B<Jalinda swallows hard.>$B$BLord Incendius is purported to be a minion of Ragnaros! Oh dear, oh dear... whatever will we do?$B$BDo you think you can handle another mission? I don't have anybody else to send, $N!$B$BWe will never get a team in if Incendius continues to raise Pyron from the ashes.$B$BYou'll have to find and destroy Lord Incendius!$B",logDesc="Find Lord Incendius in Blackrock Depths and destroy him!",choiceRewards={{id=12113,qty=1},{id=12114,qty=1},{id=12112,qty=1},{id=12115,qty=1}}} end
if not DB[4264] then DB[4264]={id=4264,zoneId=1584,name="A Crumpled Up Note",level=58,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=4264",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The note has stains covering its surface. The text is barely legible, but you make out the following:$B$B...sweet irony...$B$B...the fall of the broken Alliance...$B$B...if it were not for General Angerforge's diligence, we may have never discovered the pattern to the encryption...$B$B...Argelmach is almost done with the decryption of Windsor's notes.$B$BOur lord will rise from the depths and crush any that remain...$B$B-Emperor Dagran Thaurissan.$B",logDesc="You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all."} end
if not DB[4265] then DB[4265]={id=4265,zoneId=357,name="Freed from the Hive",level=46,minLevel=40,ender="Ginro Hearthkindle",enderType="NPC",enderId=7880,rewardNextId=4266,wowhead="https://www.wowhead.com/wotlk/quest=4265",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The pod splits opens some when you touch it, revealing a night elven male who is surprisingly still alive.  He seems to be in good health, though deeply stunned.  As you help him down from the pod, he stirs to life.$B$B\"Thank Elune - you've saved me, friend!  I... I'm Raschal, and I awoke paralyzed inside this pod after these bugs overwhelmed me.  Were you sent by the Stronghold?\"$B$BIt would seem that you've found the missing courier!",logDesc="Free Raschal from the Zukk'ash hive.$B$BReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well."} end
if not DB[4266] then DB[4266]={id=4266,zoneId=357,name="A Hero's Welcome",level=46,minLevel=40,giver="Ginro Hearthkindle",giverType="NPC",giverId=7880,ender="3",enderType="NPC",enderId=3936,rewardNextId=4267,poiX=-4458,poiY=3227,wowhead="https://www.wowhead.com/wotlk/quest=4266",image="assets/images/quests/placeholder.png",xpDiff=7,desc="$N, General Shandris Feathermoon would like to speak with you personally.  No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas.  The reports of those Zukk'ash insects are... frightening, to say the least.$B$BGeneral Feathermoon is waiting for you in the main compound.",logDesc="Speak with Shandris Feathermoon in Feathermoon Stronghold.",choiceRewards={{id=11856,qty=1},{id=11857,qty=1}}} end
if not DB[4267] then DB[4267]={id=4267,zoneId=357,name="Rise of the Silithid",level=46,minLevel=40,giver="3",giverType="NPC",giverId=3936,ender="Gracina Spiritmight",enderType="NPC",enderId=7740,poiX=-4506,poiY=3337,wowhead="https://www.wowhead.com/wotlk/quest=4267",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas.  While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate.  Her name is Gracina Spiritmight; she is a priestess who dwells in the Temple of the Moon in Darnassus.  She has broad knowledge on these kinds of creatures, and her receiving this report would benefit us all.$B$BYou're dismissed - good luck, $N; may Elune watch over us all.",logDesc="Bring Raschal's Report to Gracina Spiritmight in Darnassus.",choiceRewards={{id=34416,qty=1},{id=34417,qty=1}}} end
if not DB[4281] then DB[4281]={id=4281,zoneId=357,name="Thalanaar Delivery",level=44,minLevel=40,ender="Falfindel Waywarder",enderType="NPC",enderId=4048,wowhead="https://www.wowhead.com/wotlk/quest=4281",image="assets/images/quests/placeholder.png",xpDiff=4,money=6500,desc="This parcel of goods you found in the Woodpaw gnoll camps was supposed to be delivered to the small way-station of Thalanaar in southeastern Feralas.  Regardless of the missing courier's fate, the task of delivering the parcel remains unfinished.$B$BExamining the parcel in detail reveals a hand written name of \"Falfindel Waywarder\" on the outside of the packaging.  Perhaps this is the parcel's ultimate recipient.",logDesc="Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar."} end
if not DB[4282] then DB[4282]={id=4282,zoneId=1584,name="A Shred of Hope",level=58,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=4282",image="assets/images/quests/placeholder.png",xpDiff=7,money=9000,desc="<Marshal Windsor shakes the note excitedly.>$B$BDo you realize what this means, $N?$B$BPerhaps all is not lost! From what I can ascertain, the information is being held by two Dark Iron dwarves: General Angerforge and the golem lord, Argelmach. I have a feeling that they won't just hand over the information if we ask nicely.$B$BI hope you are ready to battle.$B$BVenture forth and find these two villains! Destroy them and return my lost information.",logDesc="Return Marshal Windsor's Lost Information.$B$BMarshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge."} end
if not DB[4283] then DB[4283]={id=4283,zoneId=46,name="FIFTY! YEP!",level=56,minLevel=50,giver="Oralius",giverType="NPC",giverId=9177,ender="Oralius",enderType="NPC",enderId=9177,poiX=-8372,poiY=-2743,wowhead="https://www.wowhead.com/wotlk/quest=4283",image="assets/images/quests/placeholder.png",xpDiff=5,money=8500,desc="I'm going to let you in on a little secret, soldier. Come a little closer.$B$BI'M THE ONLY SANE ONE HERE!$B$BLook at these people! Would you believe that they're all insane!? Well they are! NUTS! CRAZY!$B$B<Oralius lowers his voice.>$B$BLet's just keep that between me, you, and my pal Captain Winky.$B$B<Oralius grabs at the air and squeezes.>$B$BAnyhooooo... I'm collecting badges to go along with my ogre ear collection. Orc is the flavor of the day. Fifty. GO!$B$B<Oralius blows into a horn.>$B$BSHIP IT!",logDesc="Collect 50 Blackrock Medallions."} end
if not DB[4284] then DB[4284]={id=4284,zoneId=490,name="Crystals of Power",level=53,minLevel=47,giver="J.D. Collie",giverType="NPC",giverId=9117,ender="J.D. Collie",enderType="NPC",enderId=9117,poiX=-6033,poiY=-1018,wowhead="https://www.wowhead.com/wotlk/quest=4284",image="assets/images/quests/placeholder.png",xpDiff=5,money=8000,desc="I'm sure you've noticed 'em, $N. They're everywhere!$B$BWhat am I talking about? Why, the crystals, of course!$B$BThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them. I've been doing experiments here with them for a while, but I can't seem to find anything. Well, I haven't yet, anyway.$B$BSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?",logDesc="Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge."} end
if not DB[4285] then DB[4285]={id=4285,zoneId=490,name="The Northern Pylon",level=53,minLevel=47,giver="J.D. Collie",giverType="NPC",giverId=9117,ender="J.D. Collie",enderType="NPC",enderId=9117,poiX=-6033,poiY=-1018,wowhead="https://www.wowhead.com/wotlk/quest=4285",image="assets/images/quests/placeholder.png",xpDiff=4,desc="What could they be for? I can't get the thought out of my head!$B$BIt's driving me crazy --  that the rumors I have heard about the crystal pylons are all true. Call me gullible, but I'll usually believe anything people tell me.$B$BAnyway, I have heard that there is one of the crystal pylons fairly close. Somewhere in the north... Please locate it, $N. I just know they exist.",logDesc="Discover the location of the Northern Crystal Pylon in Un'Goro Crater."} end
if not DB[4286] then DB[4286]={id=4286,zoneId=1584,name="The Good Stuff",level=56,minLevel=50,giver="Oralius",giverType="NPC",giverId=9177,ender="Oralius",enderType="NPC",enderId=9177,poiX=-8372,poiY=-2743,wowhead="https://www.wowhead.com/wotlk/quest=4286",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="Captain Winky tells me that the Dark Irons in the Depths got all the good stuff. Ain't that right, Winky?$B$B<Oralius does his best impersonation of a pirate.>$B$BARRR MATEY! IT BE RIGHT!$B$BSee what I'm saying? You need to get in there and bring me back some samples of the good stuff.$B$BGet in there and shake your moneymaker!$B",logDesc="Collect 20 Dark Iron Fanny Packs.",rewards={{id=11883,qty=1}}} end
if not DB[4287] then DB[4287]={id=4287,zoneId=490,name="The Eastern Pylon",level=53,minLevel=47,giver="J.D. Collie",giverType="NPC",giverId=9117,ender="J.D. Collie",enderType="NPC",enderId=9117,poiX=-6033,poiY=-1018,wowhead="https://www.wowhead.com/wotlk/quest=4287",image="assets/images/quests/placeholder.png",xpDiff=4,desc="During my stay here, I have heard strange rumors about mysterious pylons existing out in the wilderness of the crater, $N. I guess that they are quite large, with crystals lining their interiors.$B$BAlthough I've never seen one, I can't help but think that the rumors are true -- and that the pylons have something to do with all the crystals we found$B$BSo why don't you help me put my curiosity to rest? Supposedly, there is one in the eastern area of the crater. Do you think you can find it?",logDesc="Discover the location of the Eastern Crystal Pylon in Un'Goro Crater."} end
if not DB[4288] then DB[4288]={id=4288,zoneId=490,name="The Western Pylon",level=53,minLevel=47,giver="J.D. Collie",giverType="NPC",giverId=9117,ender="J.D. Collie",enderType="NPC",enderId=9117,poiX=-6033,poiY=-1018,wowhead="https://www.wowhead.com/wotlk/quest=4288",image="assets/images/quests/placeholder.png",xpDiff=4,desc="My experiments so far have not yielded any positive results, $N. I can't help but hope that you can find a solution by searching for one of the pylons that I have heard exist.$B$BPerhaps if we combine certain colors at them... but I get ahead of myself. Let's find them first!$B$B$N, search the western area of the crater; a pylon is said to be somewhere in that area.",logDesc="Discover the location of the Western Crystal Pylon."} end
if not DB[4289] then DB[4289]={id=4289,zoneId=490,name="The Apes of Un'Goro",level=55,minLevel=47,giver="Torwa Pathfinder",giverType="NPC",giverId=9619,ender="Torwa Pathfinder",enderType="NPC",enderId=9619,poiX=-7840,poiY=-2117,wowhead="https://www.wowhead.com/wotlk/quest=4289",image="assets/images/quests/placeholder.png",xpDiff=5,money=8500,desc="This crater has many strange creatures--they seem to be nobler versions of the creatures found throughout my homeland and beyond. I cannot explain it, but this place cries of the Earth Mother. I pay homage to her every time I track one of her beautiful creatures across its basin.$B$BIf you too wish to feel the enlightenment that accompanies such a great feat, then head to the north. There you'll find great apes who are a test for any mortal's strength. Bring me their pelts... prove your strength.",logDesc="Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater."} end
if not DB[4290] then DB[4290]={id=4290,zoneId=490,name="The Fare of Lar'korwi",level=53,minLevel=48,giver="Torwa Pathfinder",giverType="NPC",giverId=9619,ender="Torwa Pathfinder",enderType="NPC",enderId=9619,rewardNextId=4291,poiX=-7840,poiY=-2117,wowhead="https://www.wowhead.com/wotlk/quest=4290",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.$B$BLar'korwi killed him not far from this spot.$B$BIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.$B$BReturn to me afterwards.",logDesc="Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater."} end
if not DB[4291] then DB[4291]={id=4291,zoneId=490,name="The Scent of Lar'korwi",level=53,minLevel=48,giver="Torwa Pathfinder",giverType="NPC",giverId=9619,ender="Torwa Pathfinder",enderType="NPC",enderId=9619,rewardNextId=4292,poiX=-7840,poiY=-2117,wowhead="https://www.wowhead.com/wotlk/quest=4291",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'm actually surprised he has not come for you yet, $N. But all is well, for I have a final plan that will bring the monster to us.$B$BBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.",logDesc="Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater."} end
if not DB[4292] then DB[4292]={id=4292,zoneId=490,name="The Bait for Lar'korwi",level=56,minLevel=48,giver="Torwa Pathfinder",giverType="NPC",giverId=9619,ender="Torwa Pathfinder",enderType="NPC",enderId=9619,poiX=-7840,poiY=-2117,wowhead="https://www.wowhead.com/wotlk/quest=4292",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains. It was here I saw Lar'korwi last. You will know you are in the right area because of all the bones from massive creatures that once wandered nearby. Take the meat you recovered and place it there. Then, rub this mixture I created on the meat. If both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.",logDesc="Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.",choiceRewards={{id=11876,qty=1},{id=11882,qty=1}}} end
if not DB[4293] then DB[4293]={id=4293,zoneId=1497,name="A Sample of Slime...",level=52,minLevel=48,giver="Chemist Fuely",giverType="NPC",giverId=10136,ender="Chemist Fuely",enderType="NPC",enderId=10136,poiX=1408,poiY=418,wowhead="https://www.wowhead.com/wotlk/quest=4293",image="assets/images/quests/placeholder.png",xpDiff=5,money=6000,desc="Felwood is a forest far north of the Barrens, even farther than Ashenvale. There, slimes are found all around pools of water blessed by the touch of Fel. The Scourge decimated the area with attacks of Infernals and other demonic magics--the slimes supposedly crept up through the earth during these attacks.$B$BGather samples of Felwood slimes and we will use the testing equipment next to me to create a control group for our tests against other samples you gather.",logDesc="Gather Felwood Slime Samples from any of the slimes in Felwood. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most corrupt. Bring 5 of the Corrupted Felwood Samples you find to Chemist Fuely."} end
if not DB[4294] then DB[4294]={id=4294,zoneId=1497,name="... and a Batch of Ooze",level=56,minLevel=48,giver="Chemist Fuely",giverType="NPC",giverId=10136,ender="Chemist Fuely",enderType="NPC",enderId=10136,poiX=1408,poiY=418,wowhead="https://www.wowhead.com/wotlk/quest=4294",image="assets/images/quests/placeholder.png",xpDiff=5,money=6500,desc="Have you heard of the Un'Goro Crater, $N? It is near the Tanaris desert, and it is a magnificent place: lush, vibrant, full of creatures and plant life.$B$BIt is there you must go. Word has reached me that the place seems completely untainted by outside hands. Explorers are just now discovering its secrets.$B$BI would like to test the slimes or oozes there. If it is true--that they are uncorrupt--then I would like to see how such creatures have evolved.",logDesc="Gather Un'Goro Slime Samples from any of the slimes in Un'Goro Crater. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most pure. Bring 5 of the Pure Un'Goro Samples you find to Chemist Fuely."} end
if not DB[4295] then DB[4295]={id=4295,zoneId=1584,name="Rocknot's Ale",level=1,minLevel=1,giver="Private Rocknot",giverType="NPC",giverId=9503,ender="Private Rocknot",enderType="NPC",enderId=9503,poiX=891,poiY=-198,wowhead="https://www.wowhead.com/wotlk/quest=4295",image="assets/images/quests/placeholder.png"} end
if not DB[4296] then DB[4296]={id=4296,zoneId=46,name="Tablet of the Seven",level=50,minLevel=50,giver="Maxwort Uberglint",giverType="NPC",giverId=9536,ender="Maxwort Uberglint",enderType="NPC",enderId=9536,poiX=-7498,poiY=-2175,wowhead="https://www.wowhead.com/wotlk/quest=4296",image="assets/images/quests/placeholder.png",xpDiff=3,money=7500,desc="I came to the Burning Steppes, following the legends of the Seven.  They were dwarves of great knowledge and power, and if you have knowledge and power, then wealth is sure to follow.$B$BThat's what I want.  Wealth!$B$BIf we can learn more of the Seven, then maybe we can get rich together.  The ruins of Thaurissan is rumored to keep the Tablet of the Seven, which holds knowledge of the ancient dwarves.  Find this tablet, copy its text and bring it to me.  Let's discover its secrets together!",logDesc="Collect the Tablet Transcript."} end
if not DB[4297] then DB[4297]={id=4297,zoneId=357,name="Food for Baby",level=47,minLevel=38,giver="Agnar Beastamer",giverType="NPC",giverId=9660,ender="Agnar Beastamer",enderType="NPC",enderId=9660,rewardNextId=4298,poiX=347,poiY=-2120,wowhead="https://www.wowhead.com/wotlk/quest=4297",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Sprite darters are omnivores--that means they eat both meat and vegetation. If your egg here's gonna hatch, we best be prepared. Some good eats for these little guys are flanks of meat, raw and juicy, believe it or not. I was never able to find out why, but it has somethin' to do with Elune's plan for the elves... maybe they were to be protectors or somethin', I don't know.$B$BI'll take care of the egg for now, why don't you get me some good Silvermane stalker flanks for 'em to eat when he's hatched.",logDesc="Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands."} end
if not DB[4298] then DB[4298]={id=4298,zoneId=357,name="Becoming a Parent",level=48,minLevel=37,giver="Agnar Beastamer",giverType="NPC",giverId=9660,ender="Agnar Beastamer",enderType="NPC",enderId=9660,poiX=347,poiY=-2120,wowhead="https://www.wowhead.com/wotlk/quest=4298",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Whoa, it was a lot more ready than I thought...",logDesc="Speak to Agnar Beastamer in the Hinterlands.",rewards={{id=11474,qty=1}}} end
if not DB[4299] then DB[4299]={id=4299,zoneId=1584,name="<NYI> <TXT>The Tomb of the Seven",level=50,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=4299",image="assets/images/quests/placeholder.png",xpDiff=5,money=22000,desc="Find the Tomb of the Seven,and place this PX83-Enigmatron there.  ",logDesc="Place the PX83-Enigmatron in the Tomb of the Seven,then return to Maxwort Uberglint."} end
if not DB[4300] then DB[4300]={id=4300,zoneId=1637,name="Bone-Bladed Weapons",level=52,minLevel=48,giver="Jes'rimon",giverType="NPC",giverId=8659,ender="Jes'rimon",enderType="NPC",enderId=8659,poiX=1955,poiY=-4459,wowhead="https://www.wowhead.com/wotlk/quest=4300",image="assets/images/quests/placeholder.png",xpDiff=5,money=4000,desc="Hmm, maybe there be somethin' you can do for the Hand now that me think 'bout it. Yes, Jes'rimon could use your help for sure.$B$BIn Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death. The Hand have... clients... that like weapons crafted from these claws. Bring me many of those white claws, and me pay you good coin. Do it fast enough, and maybe me help you in other ways.",logDesc="Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar.",choiceRewards={{id=11862,qty=1},{id=11863,qty=1},{id=11864,qty=1}}} end
if not DB[4301] then DB[4301]={id=4301,zoneId=490,name="The Mighty U'cha",level=55,minLevel=50,giver="Torwa Pathfinder",giverType="NPC",giverId=9619,ender="Torwa Pathfinder",enderType="NPC",enderId=9619,poiX=-7840,poiY=-2117,wowhead="https://www.wowhead.com/wotlk/quest=4301",image="assets/images/quests/placeholder.png",xpDiff=5,desc="While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north. You have been to that cave before, but this time, I wonder if you'll survive the encounter if you accept my task.$B$BI call him U'cha, and he is one of the Earth Mother's greatest sons, of that you can be sure. Defeat U'cha and bring me his pelt. Do this, and I will defend your right to call yourself a great hunter.",logDesc="Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.",choiceRewards={{id=11906,qty=1},{id=11907,qty=1}}} end
if not DB[4321] then DB[4321]={id=4321,zoneId=490,name="Making Sense of It",level=53,minLevel=47,giver="J.D. Collie",giverType="NPC",giverId=9117,ender="J.D. Collie",enderType="NPC",enderId=9117,poiX=-6033,poiY=-1018,wowhead="https://www.wowhead.com/wotlk/quest=4321",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The information you have given me about the pylons is very interesting...$B$BGive me a moment to do some calculations, $N. Speak to me again in a moment and I should be able to give you the answer we have been looking for.",logDesc="Speak with J.D. Collie in a moment.",rewards={{id=11482,qty=1}}} end
if not DB[4322] then DB[4322]={id=4322,zoneId=1584,name="Jail Break!",level=58,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=4322",image="assets/images/quests/placeholder.png",xpDiff=7,money=17500,desc="We need to get out of here, $N. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell. He will give you further instruction.",logDesc="Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.",rewards={{id=12065,qty=1}},choiceRewards={{id=12061,qty=1},{id=12062,qty=1}}} end
if not DB[4323] then DB[4323]={id=4323,zoneId=400,name="<NYI> <TXT> Get those Hyenas!!!",level=26,minLevel=24,wowhead="https://www.wowhead.com/wotlk/quest=4323",image="assets/images/quests/placeholder.png",xpDiff=5,money=2000,desc="I want some Hyena Pelts,and only the best will do!  Get me spotted Hyena pelts and I'll give you phat lewtz,yo.",logDesc="Bring 7 Spotted Hyena Pelts to TESTTAUREN at Freewind Post."} end
if not DB[4324] then DB[4324]={id=4324,zoneId=1584,name="Yuka Screwspigot",level=53,minLevel=48,giver="Yorba Screwspigot",giverType="NPC",giverId=9706,ender="Yuka Screwspigot",enderType="NPC",enderId=9544,rewardNextId=4136,poiX=-6980,poiY=-4844,wowhead="https://www.wowhead.com/wotlk/quest=4324",image="assets/images/quests/placeholder.png",desc="Although my little brother Ribbly has been worthless his whole life, I think, finally, he has some value!  But... we might need your help to capitalize on Ribbly's newfound worth.$B$BMy sister Yuka has been looking for him for weeks, and tracked him to the Burning Steppes.  She sent word to me, asking for some hired hands.$B$BSo, what do you say?  Want to help?  If so, then speak with my sister.  You'll find her holed up in Flame Crest, a cave northwest of Dreadmaul Rock.",logDesc="Speak with Yuka Screwspigot in the Burning Steppes."} end
if not DB[4341] then DB[4341]={id=4341,zoneId=1584,name="Kharan Mighthammer",level=59,minLevel=50,giver="King Magni Bronzebeard",giverType="NPC",giverId=2784,ender="Kharan Mighthammer",enderType="NPC",enderId=9021,poiX=-4866,poiY=-1023,wowhead="https://www.wowhead.com/wotlk/quest=4341",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!$B$B<The King sobs.>$B$BAnd now she's gone, $N!$B$BI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!$B$BKharan is supposedly being held prisoner there... find him! I want answers!",logDesc="Travel to Blackrock Depths and find Kharan Mighthammer.$B$BThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison."} end
if not DB[4342] then DB[4342]={id=4342,zoneId=1584,name="Kharan's Tale",level=59,minLevel=50,giver="Kharan Mighthammer",giverType="NPC",giverId=9021,ender="Kharan Mighthammer",enderType="NPC",enderId=9021,rewardNextId=4361,poiX=418,poiY=-210,wowhead="https://www.wowhead.com/wotlk/quest=4342",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Please, hear me out before passing judgement!$B",logDesc="Listen as Kharan Mighthammer tells his story."} end
if not DB[4343] then DB[4343]={id=4343,zoneId=361,name="Corrupted Windblossom",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4343",image="assets/images/quests/placeholder.png"} end
if not DB[4361] then DB[4361]={id=4361,zoneId=1584,name="The Bearer of Bad News",level=59,minLevel=50,giver="Kharan Mighthammer",giverType="NPC",giverId=9021,ender="King Magni Bronzebeard",enderType="NPC",enderId=2784,rewardNextId=4362,poiX=418,poiY=-210,wowhead="https://www.wowhead.com/wotlk/quest=4361",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You must take this information back to King Magni, $N. He will know what to do!$B",logDesc="Return to Ironforge and deliver the bad news to King Magni Bronzebeard."} end
if not DB[4362] then DB[4362]={id=4362,zoneId=1584,name="The Fate of the Kingdom",level=59,minLevel=50,giver="King Magni Bronzebeard",giverType="NPC",giverId=2784,ender="3",enderType="NPC",enderId=8929,rewardNextId=4363,poiX=-4866,poiY=-1023,wowhead="https://www.wowhead.com/wotlk/quest=4362",image="assets/images/quests/placeholder.png",xpDiff=7,desc="It would seem as if my old adversary, Dagran Thaurissan, has me and the kingdom of Ironforge at his mercy.$B$BYou may be my last hope, $N. You must rescue my dear daughter, Moira!$B$BThere is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him.$B$BAnd $N, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan's evil spell!",logDesc="Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.$B"} end
if not DB[4363] then DB[4363]={id=4363,zoneId=1584,name="The Princess's Surprise",level=59,minLevel=50,giver="3",giverType="NPC",giverId=8929,ender="King Magni Bronzebeard",enderType="NPC",enderId=2784,poiX=1385,poiY=-831,wowhead="https://www.wowhead.com/wotlk/quest=4363",image="assets/images/quests/placeholder.png",xpDiff=7,money=26500,desc="Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child!$B$B<You think that Princess Bronzebeard may still be suffering from the residual effect of the Emperor's spell.>$B$BReturn to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf.$B$BWhether he approves or not, it shall be.",logDesc="Return to Ironforge and speak with King Magni Bronzebeard.",choiceRewards={{id=12548,qty=1},{id=12543,qty=1}}} end
