if not DB[4402] then DB[4402]={id=4402,zoneId=363,name="Galgar's Cactus Apple Surprise",level=3,minLevel=1,giver="Galgar",giverType="NPC",giverId=9796,ender="Galgar",enderType="NPC",enderId=9796,poiX=-562,poiY=-4222,wowhead="https://www.wowhead.com/wotlk/quest=4402",image="assets/images/quests/placeholder.png",xpDiff=7,money=50,desc="It sure gets hot out here in the Valley of Trials.$B$B<Galgar wipes his brow.>$B$BIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.$B$BI'll tell you what, $N. If you bring me 6 cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.",logDesc="Bring Galgar 6 Cactus Apples. You remember him saying that they could be found near cactuses.",rewards={{id=11584,qty=10}}} end
if not DB[4403] then DB[4403]={id=4403,zoneId=361,name="Corrupted Windblossom",level=55,minLevel=48,wowhead="https://www.wowhead.com/wotlk/quest=4403",image="assets/images/quests/placeholder.png"} end
if not DB[4421] then DB[4421]={id=4421,zoneId=361,name="The Corruption of the Jadefire",level=54,minLevel=49,giver="Eridan Bluewind",giverType="NPC",giverId=9116,ender="Eridan Bluewind",enderType="NPC",enderId=9116,poiX=4009,poiY=-1311,wowhead="https://www.wowhead.com/wotlk/quest=4421",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Not many seek adventure here... Felwood's corruption is widespread and indiscriminate.$B$BAs part of the Emerald Circle, I seek to heal this land, but there are some that wish it to fester.$B$BThe ones I speak of are the Jadefire satyrs that dwell to the northwest of here, at the Ruins of Constellas. Led by a particularly cruel satyr named Xavathras, they continue to spread the disease to any creatures they encounter.$B$BWe must defend this land that was once ours. Defeat Xavathras and destroy his minions.",logDesc="Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed."} end
if not DB[4441] then DB[4441]={id=4441,zoneId=361,name="Felbound Ancients",level=54,minLevel=49,giver="Eridan Bluewind",giverType="NPC",giverId=9116,ender="Eridan Bluewind",enderType="NPC",enderId=9116,poiX=4009,poiY=-1311,wowhead="https://www.wowhead.com/wotlk/quest=4441",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The flute you found was carved from an ancient protector, the treant allies that have faithfully protected the night elves.$B$BThe satyrs have been able to corrupt anything they come in contact with, which includes the ancients that made Felwood their home. By the use of the fel, the spirit of the ancient has been bound and tortured, never completely released. The felbind you found is no doubt related.$B$BWe must try to purify the flute, $N. Bring me blessed water from the Temple of the Moon in Darnassus.",logDesc="Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial."} end
if not DB[4442] then DB[4442]={id=4442,zoneId=361,name="Purified!",level=54,minLevel=49,giver="Eridan Bluewind",giverType="NPC",giverId=9116,ender="Eridan Bluewind",enderType="NPC",enderId=9116,poiX=4009,poiY=-1311,wowhead="https://www.wowhead.com/wotlk/quest=4442",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Using the water of Elune, I will attempt to purify the flute. We must end this suffering...$B$BMay Elune guide my hands and heart.$B$BSpeak with me again in a moment.",logDesc="Speak to Eridan again in a moment.",rewards={{id=11445,qty=1}}} end
