if not DB[4805] then DB[4805]={id=4805,zoneId=618,name="Ice Thistle E'ko",level=60,minLevel=55,giver="Witch Doctor Mau'ari",giverType="NPC",giverId=10307,ender="Witch Doctor Mau'ari",enderType="NPC",enderId=10307,poiX=6721,poiY=-4713,wowhead="https://www.wowhead.com/wotlk/quest=4805",image="assets/images/quests/placeholder.png",rewards={{id=12459,qty=3}}} end
if not DB[4806] then DB[4806]={id=4806,zoneId=618,name="Frostmaul E'ko",level=60,minLevel=55,giver="Witch Doctor Mau'ari",giverType="NPC",giverId=10307,ender="Witch Doctor Mau'ari",enderType="NPC",enderId=10307,poiX=6721,poiY=-4713,wowhead="https://www.wowhead.com/wotlk/quest=4806",image="assets/images/quests/placeholder.png",rewards={{id=12460,qty=3}}} end
if not DB[4807] then DB[4807]={id=4807,zoneId=618,name="Wildkin E'ko",level=60,minLevel=55,giver="Witch Doctor Mau'ari",giverType="NPC",giverId=10307,ender="Witch Doctor Mau'ari",enderType="NPC",enderId=10307,poiX=6721,poiY=-4713,wowhead="https://www.wowhead.com/wotlk/quest=4807",image="assets/images/quests/placeholder.png",rewards={{id=12458,qty=3}}} end
if not DB[4808] then DB[4808]={id=4808,zoneId=46,name="Felnok Steelspring",level=54,minLevel=50,giver="Tinkee Steamboil",giverType="NPC",giverId=10267,ender="Felnok Steelspring",enderType="NPC",enderId=10468,rewardNextId=4809,poiX=-7500,poiY=-2178,wowhead="https://www.wowhead.com/wotlk/quest=4808",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I have another favor to ask of you.$B$BMy initial study of the essence you collected shows that it might be possible to freeze dragon whelp eggs and preserve them!  I want to test this theory, but first I need specially made engineering components.  My colleague, Felnok Steelspring, can make them.$B$BHere, take this letter to Felnok.  It tells him what I need.  You'll find Felnok in Winterspring, in the town of Everlook.",logDesc="Give Tinkee's Letter to Felnok Steelspring at Everlook in Winterspring."} end
if not DB[4809] then DB[4809]={id=4809,zoneId=618,name="Chillwind Horns",level=54,minLevel=50,giver="Felnok Steelspring",giverType="NPC",giverId=10468,ender="Felnok Steelspring",enderType="NPC",enderId=10468,rewardNextId=4810,poiX=6706,poiY=-4692,wowhead="https://www.wowhead.com/wotlk/quest=4809",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I have most of what Tinkee needs, but I'm missing one important component, and that's chillwind horns.  The horns of the chillwind chimaera in Winterspring are a concentrated source of cold, but only pristine, uncracked horns will do!  I'll need a supply of those to complete Tinkee's order.$B$BBring me the uncracked chillwind horns, and I'll prepare a package for Tinkee.",logDesc="Collect 8 Uncracked Chillwind Horns."} end
if not DB[4810] then DB[4810]={id=4810,zoneId=618,name="Return to Tinkee",level=54,minLevel=50,giver="Felnok Steelspring",giverType="NPC",giverId=10468,ender="Tinkee Steamboil",enderType="NPC",enderId=10267,poiX=6706,poiY=-4692,wowhead="https://www.wowhead.com/wotlk/quest=4810",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ok, everything is prepared and packed and ready for transport!  Good luck in your journey, and make sure you tell Tinkee that she owes me!",logDesc="Bring Felnok's Package to Tinkee Steamboil at Flame Crest in the Burning Steppes.",choiceRewards={{id=15862,qty=1},{id=15863,qty=1}}} end
if not DB[4811] then DB[4811]={id=4811,zoneId=148,name="The Red Crystal",level=14,minLevel=12,giver="Sentinel Glynda Nal'Shea",giverType="NPC",giverId=2930,ender="Sentinel Glynda Nal'Shea",enderType="NPC",enderId=2930,rewardNextId=4812,poiX=6439,poiY=472,wowhead="https://www.wowhead.com/wotlk/quest=4811",image="assets/images/quests/placeholder.png",xpDiff=3,money=600,desc="Hostile moonkin roam in ever increasing numbers to our east.  They once were thought to be gentle, almost mystical creatures.  While some continue to hold reverence for them, the safety of Auberdine forces me to keep a more realistic view.$B$BI've received reports that moonkin are being drawn to a large red crystal along Darkshore's eastern mountain range.  No one has any idea what that crystal is, or even if it really exists.  I want you to locate it over there and report back to me what you find.",logDesc="Travel east of Auberdine and look for a large, red crystal along Darkshore's eastern mountain range.  Report back what you find to Sentinel Glynda Nal'Shea in Auberdine."} end
if not DB[4812] then DB[4812]={id=4812,zoneId=148,name="As Water Cascades",level=14,minLevel=12,giver="Sentinel Glynda Nal'Shea",giverType="NPC",giverId=2930,rewardNextId=4813,poiX=6439,poiY=472,wowhead="https://www.wowhead.com/wotlk/quest=4812",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Use this empty vial and fill up on some moonwell water here in Auberdine.  Such potent magic should provide a clue as to the composition of the crystal.  To do that, you'll pour the liquid over the crystal; it should take care of the rest.$B$BWhile I don't anticipate anything bad happening to you, I still want you to be careful.  Above us to the east is Felwood; if that crystal is tied to that place as I suspect it is, then it could prove to be very dangerous.",logDesc="Fill the Empty Water Tube at the Auberdine moonwell, and then investigate the red crystal along Darkshore's eastern mountain wall."} end
if not DB[4813] then DB[4813]={id=4813,zoneId=148,name="The Fragments Within",level=14,minLevel=12,ender="Sentinel Glynda Nal'Shea",enderType="NPC",enderId=2930,wowhead="https://www.wowhead.com/wotlk/quest=4813",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone.  The jawbone appears to be from a humanoid, but it is unclear without breaking open the crystal - a feat that even the strongest of magic would find near impossible.$B$BWith the task at hand complete, all that remains is to report back to Sentinel Glynda Nal'Shea in Auberdine.",logDesc="Report back what you have found to Sentinel Glynda Nal'Shea in Auberdine.",choiceRewards={{id=15335,qty=1},{id=15396,qty=1},{id=15397,qty=1}}} end
if not DB[4821] then DB[4821]={id=4821,zoneId=400,name="Alien Egg",level=26,minLevel=24,giver="Hagar Lightninghoof",giverType="NPC",giverId=10539,ender="Hagar Lightninghoof",enderType="NPC",enderId=10539,poiX=-5442,poiY=-2397,wowhead="https://www.wowhead.com/wotlk/quest=4821",image="assets/images/quests/placeholder.png",xpDiff=5,money=1500,desc="A rumor has surfaced about an alien egg here in Thousand Needles. Those that report seeing this egg have failed to even get close enough to examine it in detail. Serpents guard the egg as if it's one of their own.$B$BI want you to seek out this alien egg and bring it to me so that I may examine it. Reports say the egg is located within a serpent den, but there are several serpent dens along the base of the cliff walls south and northeast of Freewind Post.",logDesc="Return the Alien Egg to Hagar Lightninghoof in Freewind Post."} end
if not DB[4822] then DB[4822]={id=4822,zoneId=-284,name="You Scream, I Scream...",level=-1,minLevel=10,ender="Human Orphan",enderType="NPC",enderId=14305,wowhead="https://www.wowhead.com/wotlk/quest=4822",image="assets/images/quests/placeholder.png",xpDiff=1,desc="ICE CREAM!  Oh please please please could you get me some ice cream?!  Strawberry is my favorite flavor, and there's no better strawberry ice cream in the world than Tigule and Foror's Strawberry Ice Cream!  It's my favorite ice cream in the whole wide world!$B$BI had it once a long time ago when I was at the Shimmering Flats race track, but I heard that they might be selling them in town now!  Please?  Pretty please?  With Tigule and Foror's Strawberry Ice Cream on top??!?!",logDesc="Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream."} end
if not DB[4841] then DB[4841]={id=4841,zoneId=400,name="Pacify the Centaur",level=25,minLevel=23,giver="Cliffwatcher Longhorn",giverType="NPC",giverId=10537,ender="Cliffwatcher Longhorn",enderType="NPC",enderId=10537,rewardNextId=5064,poiX=-5455,poiY=-2443,wowhead="https://www.wowhead.com/wotlk/quest=4841",image="assets/images/quests/placeholder.png",xpDiff=5,money=1800,desc="$N, I entreat you to hunt these centaur down. They shall feel the wrath of our revenge. Attack the centaur camp to the north of Freewind Post!  Let wrath guide your hand!$B",logDesc="Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post."} end
if not DB[4842] then DB[4842]={id=4842,zoneId=618,name="Strange Sources",level=56,minLevel=51,giver="Donova Snowden",giverType="NPC",giverId=9298,ender="Donova Snowden",enderType="NPC",enderId=9298,poiX=6396,poiY=-2537,wowhead="https://www.wowhead.com/wotlk/quest=4842",image="assets/images/quests/placeholder.png",xpDiff=5,desc="To tell you the truth, although there are no volcanoes here in Winterspring, I believe that there are far more threatening reasons for these hot springs...$B$BWell, I think you'll want to see it for yourself. You'll need to travel the length of Winterspring, and head to the very south. When the air becomes thick and muggy, and the sky turns dark, you'll have found what I believe to be the source of the hot springs.$B$BHave a look. I'm sure you'll have many questions when you return.",logDesc="Follow Donova Snowden's instructions, then report back.",rewards={{id=15789,qty=1}}} end
if not DB[4861] then DB[4861]={id=4861,zoneId=618,name="Enraged Wildkin",level=59,minLevel=53,giver="Jaron Stoneshaper",giverType="NPC",giverId=10301,rewardNextId=4863,poiX=7093,poiY=-4019,wowhead="https://www.wowhead.com/wotlk/quest=4861",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Hey there, $Glad:lass;! I was chased from my camp in southern Winterspring by some bloodthirsty wildkin! Well, I suppose I got too close to something the wildkin were guarding.$B$BI barely managed to get away safely; I fear a buddy of mine wasn't as lucky. Would you mind braving the wildkin and heading to the camp? I really need my supplies, and I'd also like to get back the amulet I unearthed yesterday at the dig site.",logDesc="Locate Jaron Stoneshaper's wrecked camp and supplies in southern Winterspring."} end
if not DB[4862] then DB[4862]={id=4862,zoneId=1583,name="En-Ay-Es-Tee-Why",level=59,minLevel=55,giver="Kibler",giverType="NPC",giverId=10260,ender="Kibler",enderType="NPC",enderId=10260,poiX=-7459,poiY=-2197,wowhead="https://www.wowhead.com/wotlk/quest=4862",image="assets/images/quests/placeholder.png",xpDiff=7,money=9000,desc="Believe it or not, there are people out there willing to pay for the most vile of domesticated beast!$B$BI'd sent Bijou into the Spire to try and collect some of those spire spider eggs but I haven't heard from her in weeks. Maybe you can help me out?$B$BI'll tell you what, $N. Go to Blackrock Spire and collect some spire spider eggs for me. Bring them back here and not only will I give you a little cash, but I'll even domesticate one for you!",logDesc="Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.$B$BBy the sound of it, these eggs could be found near spiders.$B",rewards={{id=12529,qty=1}}} end
if not DB[4863] then DB[4863]={id=4863,zoneId=618,name="Enraged Wildkin",level=59,minLevel=53,rewardNextId=4864,wowhead="https://www.wowhead.com/wotlk/quest=4863",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Looking around, you don't see much that Jaron could want here. However, you do notice that the crate you found has been smashed open, almost as if this was what the wildkin were after...$B$BLooking to the east, you can barely make out an abandoned wagon. Perhaps you might find Jaron's things there. It's worth a look.",logDesc="Find Jaron Stoneshaper's wrecked wagon."} end
if not DB[4864] then DB[4864]={id=4864,zoneId=618,name="Enraged Wildkin",level=59,minLevel=53,ender="Jaron Stoneshaper",enderType="NPC",enderId=10301,wowhead="https://www.wowhead.com/wotlk/quest=4864",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="After inspecting the contents of the box, you decide that Jaron could make use of the tools and other items inside. However, there is no sign of the amulet.$B$BIt appears that the wildkin inhabit the lands to the north and east of here, so you decide that the next step is to face the creatures and reclaim the amulet from them.",logDesc="Pick up Jaron's Supplies from the snow, then find the wildkin that stole the amulet Jaron spoke of.$B$BBring Jaron's Supplies and the Blue-feathered Amulet to Jaron Stoneshaper at the lodge in Winterspring."} end
if not DB[4865] then DB[4865]={id=4865,zoneId=400,name="Serpent Wild",level=26,minLevel=24,giver="Hagar Lightninghoof",giverType="NPC",giverId=10539,ender="Motega Firemane",enderType="NPC",enderId=10428,rewardNextId=5062,poiX=-5442,poiY=-2397,wowhead="https://www.wowhead.com/wotlk/quest=4865",image="assets/images/quests/placeholder.png",xpDiff=3,desc="If I did not see that with my own eyes I would never have believed it to be true. Vengeance has come to Thousand Needles!$B$B<Hagar wipes his brow.>$B$B$N, you must act quickly! Go now and seek out Motega Firemane; he is located at Whitereach Post just northwest of Freewind Post along the road. He will know what to do!",logDesc="Report your findings to Motega Firemane at Whitereach Post in Thousand Needles."} end
if not DB[4866] then DB[4866]={id=4866,zoneId=1583,name="Mother's Milk",level=60,minLevel=55,giver="Ragged John",giverType="NPC",giverId=9563,ender="Ragged John",enderType="NPC",enderId=9563,poiX=-7495,poiY=-2171,wowhead="https://www.wowhead.com/wotlk/quest=4866",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="It's probably one of the most potent poisons in the world, $r!$B$BI've overheard the Blackrock speaking about its lethality in my jaunts into the Spire. They call it 'Mother's Milk', named after Mother Smolderweb, the big nasty spider in the Skitterweb cave.$B$BNow here's what I need from you: A live sample of the Milk, flowing through YOUR veins. Just bringing me the gland won't be enough! Get her to poison you and come back to me!$B$BThen... I get to milk ya!$B$B<Rubs his hands together in anticipation.>",logDesc="In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.",rewards={{id=15873,qty=1}}} end
if not DB[4867] then DB[4867]={id=4867,zoneId=1583,name="Urok Doomhowl",level=60,minLevel=55,giver="Warosh",giverType="NPC",giverId=10799,ender="Warosh",enderType="NPC",enderId=10799,poiX=81,poiY=-480,wowhead="https://www.wowhead.com/wotlk/quest=4867",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Argh!  So hard to speak!$B$BTake this note!  Get me my mojo!",logDesc="Read Warosh's Scroll.  Bring Warosh's Mojo to Warosh.",rewards={{id=15867,qty=1}}} end
if not DB[4881] then DB[4881]={id=4881,zoneId=400,name="Assassination Plot",level=28,minLevel=23,ender="Kanati Greycloud",enderType="NPC",enderId=10638,rewardNextId=4966,wowhead="https://www.wowhead.com/wotlk/quest=4881",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Tauren, Kanati Greycloud is bold to set up a hunting camp in Thousand Needles. We must kill him to rid this hunting camp and all who may follow him. We will converge at the small post Southwest of the Great Lift.$B",logDesc="Warn Kanati Greycloud at Whitereach Post of the plot to kill him."} end
if not DB[4882] then DB[4882]={id=4882,zoneId=618,name="Guarding Secrets",level=59,minLevel=52,ender="Trull Failbane",enderType="NPC",enderId=10306,rewardNextId=4883,wowhead="https://www.wowhead.com/wotlk/quest=4882",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You are unsure of the significance of the necklace that fell from the neck of the recently-slain wildkin. It glows brightly, slowly fading in and out.$B$BTrull Failbane might be able to tell you more, since his knowledge of the wildkin seems extensive. Perhaps you should ask him about it.",logDesc="Take the Blue-feathered Necklace to Trull Failbane at Bloodvenom Post."} end
if not DB[4883] then DB[4883]={id=4883,zoneId=618,name="Guarding Secrets",level=59,minLevel=52,giver="Trull Failbane",giverType="NPC",giverId=10306,ender="Nara Wildmane",enderType="NPC",enderId=5770,poiX=5110,poiY=-355,wowhead="https://www.wowhead.com/wotlk/quest=4883",image="assets/images/quests/placeholder.png",xpDiff=5,desc="While I do possess much knowledge about the owlbeasts you defeated in Winterspring, I am not very learned on the subject of the magics they wield. But I do believe I know of one that would be able to examine the necklace and most likely tell you what it is.$B$BNara Wildmane in Thunder Bluff is an expert in this field; see her. Good luck, $N.",logDesc="Take the Blue-feathered Necklace to Nara Wildmane.",choiceRewards={{id=15796,qty=1},{id=15797,qty=1}}} end
if not DB[4901] then DB[4901]={id=4901,zoneId=618,name="Guardians of the Altar",level=59,minLevel=52,giver="Ranshalla",giverType="NPC",giverId=10300,ender="Erelas Ambersky",enderType="NPC",enderId=7916,poiX=5718,poiY=-4795,wowhead="https://www.wowhead.com/wotlk/quest=4901",image="assets/images/quests/placeholder.png",xpDiff=4,desc="At the very top of the ridge lies what I believe to be an altar of the goddess Elune. From what I can tell, we need to light the five torches in each cave, and then we will be able to access the altar directly.$B$BI transcribed some incantations carved into the stone in the ancient ruins of Kel'Theril, which I believe are the secret to unlocking the altar. I'll need your help to light each torch, while I recite the spell.$B$BIf we are successful, you'll be able to report our findings to Erelas!",logDesc="Protect Ranshalla while she attempts to reactivate the Altar of Elune. Report your findings to Erelas Ambersky in Rut'theran Village."} end
if not DB[4902] then DB[4902]={id=4902,zoneId=618,name="Wildkin of Elune",level=57,minLevel=52,giver="Erelas Ambersky",giverType="NPC",giverId=7916,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,poiX=8707,poiY=989,wowhead="https://www.wowhead.com/wotlk/quest=4902",image="assets/images/quests/placeholder.png",xpDiff=5,desc="That's fascinating!$B$BI have always wondered about the truth... Well, you must share this knowledge, definitely! Go to Arch Druid Fandral Staghelm right away -- you'll find him in Darnassus, in the Cenarion Circle. Explain to him what happened, just the same as you told me. I'm sure he will be just as interested!$B$BThis is important information, $N!",logDesc="Speak with Arch Druid Fandral Staghelm in Darnassus.",choiceRewards={{id=16622,qty=1},{id=16623,qty=1}}} end
if not DB[4903] then DB[4903]={id=4903,zoneId=1583,name="Warlord's Command",level=60,minLevel=55,ender="Warlord Goretooth",enderType="NPC",enderId=9077,rewardNextId=4941,wowhead="https://www.wowhead.com/wotlk/quest=4903",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="By order of Warlord Goretooth, the following inhabitants of Blackrock Spire must be destroyed:$B$BThe rotund menace, Highlord Omokk.$B$BThe cruel and ruthless troll, War Master Voone.$B$BOverlord Wyrmthalak, taskmaster of the lesser city.$B$BYou will also be required to return any important documents that you may find.$B$BSucceed and be honored.$B$BFail and be forgotten.",logDesc="Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.",choiceRewards={{id=13958,qty=1},{id=13959,qty=1},{id=13961,qty=1},{id=13962,qty=1},{id=13963,qty=1}}} end
if not DB[4904] then DB[4904]={id=4904,zoneId=400,name="Free at Last",level=29,minLevel=25,giver="Lakota Windsong",giverType="NPC",giverId=10646,ender="Thalia Amberhide",enderType="NPC",enderId=10645,poiX=-4743,poiY=-2103,wowhead="https://www.wowhead.com/wotlk/quest=4904",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong. He... he slew my brother and then brought me here.  My poor brother...$B$B$N, could you escort me out of the Darkcloud Pinnacle?  Please... I need to get back to Thalia! She must be worried sick about me.",logDesc="Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post.",choiceRewards={{id=15469,qty=1},{id=15468,qty=1}}} end
if not DB[4905] then DB[4905]={id=4905,zoneId=0,name="<UNUSED>",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=4905",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Defend Kanati Greycloud against the Centaur Assassins.",logDesc="Defend Kanati Greycloud"} end
if not DB[4906] then DB[4906]={id=4906,zoneId=361,name="Further Corruption",level=54,minLevel=49,giver="Eridan Bluewind",giverType="NPC",giverId=9116,ender="Eridan Bluewind",enderType="NPC",enderId=9116,poiX=4009,poiY=-1311,wowhead="https://www.wowhead.com/wotlk/quest=4906",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A second encampment of satyrs threatens the land of Felwood towards the north, led by the cruel Xavaric. The vile betrayers and tricksters feed upon the corruption of the native creatures of Felwood.$B$BXavathras and his minions were only part of a larger plan -- to cultivate a corrupted moonwell, and then provide the spoils to Xavaric.$B$BNow that Xavathras is out of the way, finish this task, $N. Head to the north and defeat Xavaric.",logDesc="Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters, and Xavaric. Return to Eridan when the task is completed.",rewards={{id=11875,qty=1}}} end
if not DB[4907] then DB[4907]={id=4907,zoneId=1583,name="Tinkee Steamboil",level=60,minLevel=57,giver="Felnok Steelspring",giverType="NPC",giverId=10468,ender="Tinkee Steamboil",enderType="NPC",enderId=10267,rewardNextId=4734,poiX=6706,poiY=-4692,wowhead="https://www.wowhead.com/wotlk/quest=4907",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hi, $N.  Remember Tinkee Steamboil?  Well, she remembers you!  She sent me a message to keep an eye out for you, because... she needs your help again.  I think it has something to do with her studies on dragons.$B$BYou should speak to her in the Burning Steppes, at the Flame Crest.",logDesc="Speak with Tinkee Steamboil at Flame Crest in the Burning Steppes."} end
if not DB[4921] then DB[4921]={id=4921,zoneId=17,name="Lost in Battle",level=20,minLevel=14,giver="Mankrik",giverType="NPC",giverId=3432,ender="Mankrik",enderType="NPC",enderId=3432,poiX=-521,poiY=-2641,wowhead="https://www.wowhead.com/wotlk/quest=4921",image="assets/images/quests/placeholder.png",xpDiff=4,money=900,desc="We battled in a small tauren camp when we were separated--she held three of the Bristlebacks off by herself. But the odds began to overwhelm us. I led some away only to see her overwhelmed by newcomers. In my rage, I turned to face my enemies, but they brought me down easily with their vast numbers.$B$BI awoke to a tauren druid tending my wounds--he had come across me on the Gold Road as I fell.$B$BPlease, $c, find some sign of my wife.",logDesc="Find Mankrik's wife and then return to him in the Crossroads."} end
if not DB[4941] then DB[4941]={id=4941,zoneId=1637,name="Eitrigg's Wisdom",level=60,minLevel=55,giver="Warlord Goretooth",giverType="NPC",giverId=9077,ender="Thrall",enderType="NPC",enderId=4949,rewardNextId=4974,poiX=-6678,poiY=-2224,wowhead="https://www.wowhead.com/wotlk/quest=4941",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Rend lives?$B$BImpossible!$B$BIt had been thought that Rend  was slain decades ago.$B$BSeek out the wisdom of Eitrigg, $N. None know the workings of the Blackrock better than he and if what is written here bares truth, Eitrigg should be informed. No person should be denied the right of vengeance.$B$BYou will find him in Orgrimmar.$B$BOnce you have spoken with Eitrigg, confer with the Warchief to find out what he wishes to do about this problem.",logDesc="Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall.$B$BYou recall having seen Eitrigg in Thrall's chamber."} end
if not DB[4961] then DB[4961]={id=4961,zoneId=-61,name="Cleansing of the Orb of Orahil",level=40,minLevel=35,giver="Tabetha",giverType="NPC",giverId=6546,ender="Tabetha",enderType="NPC",enderId=6546,rewardNextId=4976,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=4961",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Ah, a summoner's orb--this is where the taint must be coming from. We must exorcise the demon within it if you're to use it. That I can do easily.$B$BYou're the one who has the hard job.  You must kill the demon once I release it.$B$BAnd you'll have to be quick.  If you take too long then he'll return to the orb and we'll have to start over!$B$BSo get yourself ready, $N.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty.",logDesc="Kill the Demon of the Orb, then speak with Tabetha.",rewards={{id=12642,qty=1}}} end
if not DB[4962] then DB[4962]={id=4962,zoneId=-61,name="Shard of a Felhound",level=40,minLevel=35,giver="Acolyte Wytula",giverType="NPC",giverId=6254,ender="Menara Voidrender",enderType="NPC",enderId=6266,poiX=-773,poiY=-3725,wowhead="https://www.wowhead.com/wotlk/quest=4962",image="assets/images/quests/placeholder.png",xpDiff=4,desc="So, you have chosen to capture the soul of a felhound, good.$B$BTake this ruby--with it, you will be able to capture the creature's soul. It works very similar to spells you already know: when the creature is close to dying, use the gem and it should do the rest of the work for you.$B$BI would suggest going to Desolace and trying your hand at any of the felhounds there. Those should do nicely.$B$BAfter you're successful, take both the captured spirit and your ruby to Menara.",logDesc="Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens."} end
if not DB[4963] then DB[4963]={id=4963,zoneId=-61,name="Shard of an Infernal",level=40,minLevel=35,giver="Acolyte Magaz",giverType="NPC",giverId=6252,ender="Menara Voidrender",enderType="NPC",enderId=6266,poiX=-768,poiY=-3717,wowhead="https://www.wowhead.com/wotlk/quest=4963",image="assets/images/quests/placeholder.png",xpDiff=4,desc="So, you have chosen to capture the soul of an infernal, good.$B$BTake this emerald--with it, you will be able to capture the creature's soul. It works very similar to spells you already know: when the creature is close to dying, use the gem and it should do the rest of the work for you.$B$BI would suggest going to Desolace and trying your hand at any of the infernals there. Those should do nicely.$B$BAfter you're successful, take both the captured spirit and your emerald to Menara.",logDesc="Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens."} end
if not DB[4964] then DB[4964]={id=4964,zoneId=-61,name="The Completed Orb of Dar'Orahil",level=40,minLevel=35,giver="Menara Voidrender",giverType="NPC",giverId=6266,ender="Menara Voidrender",enderType="NPC",enderId=6266,poiX=-783,poiY=-3711,wowhead="https://www.wowhead.com/wotlk/quest=4964",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb. I always felt it was important to cater to a warlock's chosen weapon... I see no reason not to continue that practice.",logDesc="Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.",choiceRewards={{id=15108,qty=1},{id=15106,qty=1}}} end
if not DB[4965] then DB[4965]={id=4965,zoneId=-61,name="Knowledge of the Orb of Orahil",level=35,minLevel=35,giver="Briarthorn",giverType="NPC",giverId=5172,ender="Menara Voidrender",enderType="NPC",enderId=6266,rewardNextId=1799,poiX=-4599,poiY=-1112,wowhead="https://www.wowhead.com/wotlk/quest=4965",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Well, well, well... a pleasure to see you're growing in power, $N. I'd wager you'd be about ready to speak to Menara Voidrender in the Barrens. If you haven't spoken to her before, then let me tell you, I don't think I've ever met another expert in the creation of items--orbs specifically--that can inprison even a demon to serve our will so easily.$B$BIf you're interested, she's in Strahad's tower above Ratchet in the Barrens.",logDesc="Speak to Menara Voidrender in the Barrens."} end
if not DB[4966] then DB[4966]={id=4966,zoneId=400,name="Protect Kanati Greycloud",level=28,minLevel=23,giver="Kanati Greycloud",giverType="NPC",giverId=10638,ender="Kanati Greycloud",enderType="NPC",enderId=10638,poiX=-4906,poiY=-1367,wowhead="https://www.wowhead.com/wotlk/quest=4966",image="assets/images/quests/placeholder.png",xpDiff=5,desc="But, there may be more centaur than I thought, I ask you, $n, to fight with me against these vile assassins.",logDesc="Protect Kanati Greycloud from the centaur attack.",choiceRewards={{id=15461,qty=1},{id=15462,qty=1},{id=15463,qty=1}}} end
if not DB[4967] then DB[4967]={id=4967,zoneId=-61,name="Knowledge of the Orb of Orahil",level=35,minLevel=35,giver="Zevrost",giverType="NPC",giverId=3326,ender="Menara Voidrender",enderType="NPC",enderId=6266,rewardNextId=1799,poiX=1849,poiY=-4360,wowhead="https://www.wowhead.com/wotlk/quest=4967",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Still a fool, and still seeking the trappings of mortals. Yes, I speak to you with arrogance. I see you before me and I laugh. You're pathetic!$B$BBut it matters not what I think. It only matters what those willing to deal with you thinks!  And in this case, against my better judgment, those with some portion of power feel you deserve more.$B$BIf this is something you strive for then you should speak with Menara Voidrender in the tower above Ratchet. I believe you have met her before some time ago.",logDesc="Speak to Menara Voidrender in the Barrens."} end
if not DB[4968] then DB[4968]={id=4968,zoneId=-61,name="Knowledge of the Orb of Orahil",level=35,minLevel=35,giver="Demisette Cloyce",giverType="NPC",giverId=461,ender="Menara Voidrender",enderType="NPC",enderId=6266,rewardNextId=1799,poiX=-8980,poiY=1041,wowhead="https://www.wowhead.com/wotlk/quest=4968",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Hmm, you've made it this far... truly astonishing. I would have thought the corruption of channeling the arcane would have seeped into your very soul and driven you mad by now. How about we try and push you further then?$B$BIf you want to test your skill, seek out Menara Voidrender above Ratchet in Strahad's tower. She will guide you.",logDesc="Speak to Menara Voidrender in the Barrens."} end
if not DB[4969] then DB[4969]={id=4969,zoneId=-61,name="Knowledge of the Orb of Orahil",level=35,minLevel=35,giver="Kaal Soulreaper",giverType="NPC",giverId=4563,ender="Menara Voidrender",enderType="NPC",enderId=6266,rewardNextId=1799,poiX=1776,poiY=46,wowhead="https://www.wowhead.com/wotlk/quest=4969",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Haha! You're doing very well for yourself, young $c.$B$BGiven time, infernals and dreadlords will bow before you!$B$BBut until that time comes, you must still rely on weapons forged by the hands of the mortal races.$B$BYou seem prepared for another such creation, and if you are willing, Menara Voidrender would speak with you! She is near Strahad's tower overlooking the port town of Ratchet. Go there when you are ready.",logDesc="Speak to Menara Voidrender in the Barrens."} end
if not DB[4970] then DB[4970]={id=4970,zoneId=618,name="Frostsaber Provisions",level=60,minLevel=58,giver="Rivern Frostwind",giverType="NPC",giverId=10618,ender="Rivern Frostwind",enderType="NPC",enderId=10618,poiX=8067,poiY=-3862,wowhead="https://www.wowhead.com/wotlk/quest=4970",image="assets/images/quests/placeholder.png",desc="If you wish to prove yourself, you may begin by doing a very simple, but very important task.$B$BGather meat from the chimaera and from the shardtooth bears in the area. Bring it to me so that I may use it to feed the frostsabers that are being trained.",logDesc="Collect 5 Shardtooth Meats and 5 Chillwind Meats for Rivern Frostwind in Winterspring."} end
if not DB[4971] then DB[4971]={id=4971,zoneId=28,name="A Matter of Time",level=56,minLevel=53,giver="Chromie",giverType="NPC",giverId=10667,ender="Chromie",enderType="NPC",enderId=10667,poiX=1453,poiY=-1280,wowhead="https://www.wowhead.com/wotlk/quest=4971",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Tampering of the timeline by a sinister force - most likely the Scourge - has occurred in Andorhal!  I can try to keep the passage of time here intact and mend what has been damaged, but I'll need your help to do so uninterrupted.$B$BTemporal parasites - carrion that feed on the strands of time's altered flow - now infest the silos of Andorhal.  A blue pulse of distortion is their only visual marker.  They slow my auguries; please $N, help me by using this temporal displacer to root out these parasites.",logDesc="Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites.$B$BSlay 10 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands.",choiceRewards={{id=15812,qty=1},{id=15813,qty=1}}} end
if not DB[4972] then DB[4972]={id=4972,zoneId=28,name="Counting Out Time",level=56,minLevel=53,giver="Chromie",giverType="NPC",giverId=10667,ender="Chromie",enderType="NPC",enderId=10667,poiX=1453,poiY=-1280,wowhead="https://www.wowhead.com/wotlk/quest=4972",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I need you to reach into the world beyond this room, $N.  Allow me to explain.$B$BYou see the difference in this room compared to the rest of Andorhal.  My dragonflight works in many different ways and in many different timelines.  To mend Andorhal's damage, I now act from a different timeline as not to overly contaminate it.  To continue this though I need time trinkets, ones trapped from when the plague hit.  Find them in lockboxes found in the ruined buildings that make up this once proud city.",logDesc="Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city.  Return with them to Chromie in the Andorhal Inn, Western Plaguelands.",rewards={{id=12650,qty=1}}} end
if not DB[4973] then DB[4973]={id=4973,zoneId=28,name="Counting Out Time",level=56,minLevel=53,giver="Chromie",giverType="NPC",giverId=10667,ender="Chromie",enderType="NPC",enderId=10667,poiX=1453,poiY=-1280,wowhead="https://www.wowhead.com/wotlk/quest=4973",image="assets/images/quests/placeholder.png",desc="If you are willing to help once more, I can certainly use your assistance.  I'll gladly take more watches you might uncover from the ruins of Andorhal.  They certainly help me in maintaining a balance against whatever malign force is meddling with the timeline here.$B$BIn exchange for those watches, I'll give you another item that, in the future, I suspect you'll find quite the use for.",logDesc="Locate 5 Andorhal Watches amongst the rubble of the city, and return with them to Chromie in the Andorhal Inn, Western Plaguelands.",rewards={{id=12650,qty=1}}} end
if not DB[4974] then DB[4974]={id=4974,zoneId=1583,name="For The Horde!",level=60,minLevel=55,giver="Thrall",giverType="NPC",giverId=4949,ender="Thrall",enderType="NPC",enderId=4949,poiX=1920,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=4974",image="assets/images/quests/placeholder.png",xpDiff=7,money=27000,desc="Rend dares make such grand claims because of the protection he is afforded by the black flight.$B$BYou, $N, will find a way to pass through the Halls of Ascension. You will then find 'Warchief' Rend Blackhand and you will destroy him - FOR THE HORDE!$B$B<Thrall slams a fist down upon his throne.>$B$BThe next time you return to my chambers, you will hold his head high in triumph and then you shall present it to your Warchief. Do this and be honored as a hero of the Horde.",logDesc="Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.",choiceRewards={{id=13966,qty=1},{id=13968,qty=1},{id=13965,qty=1}}} end
if not DB[4975] then DB[4975]={id=4975,zoneId=-61,name="The Completed Orb of Noh'Orahil",level=40,minLevel=35,giver="Menara Voidrender",giverType="NPC",giverId=6266,ender="Menara Voidrender",enderType="NPC",enderId=6266,poiX=-783,poiY=-3711,wowhead="https://www.wowhead.com/wotlk/quest=4975",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb. I always felt it was important to cater to a warlock's chosen weapon... I see no reason not to continue that practice.",logDesc="Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again.",choiceRewards={{id=15107,qty=1},{id=15105,qty=1}}} end
if not DB[4976] then DB[4976]={id=4976,zoneId=-61,name="Returning the Cleansed Orb",level=40,minLevel=35,giver="Tabetha",giverType="NPC",giverId=6546,ender="Menara Voidrender",enderType="NPC",enderId=6266,poiX=-4032,poiY=-3393,wowhead="https://www.wowhead.com/wotlk/quest=4976",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Take the cleansed orb back to Menara in Ratchet, $N. Give her my regards and be safe. I truly hope you are able to withstand the temptation and corruption that is sure to come as you follow your path.$B$BGood luck.",logDesc="Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens."} end
if not DB[4981] then DB[4981]={id=4981,zoneId=1583,name="Operative Bijou",level=59,minLevel=55,giver="Lexlort",giverType="NPC",giverId=9080,ender="Bijou",enderType="NPC",enderId=10257,rewardNextId=4982,poiX=-6679,poiY=-2225,wowhead="https://www.wowhead.com/wotlk/quest=4981",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Never trust a goblin. That's what it comes down to, $N.$B$BBijou is her name - one of our slipperiest operatives. I found out she was working for some shady exotic pet dealer out of the Burning Steppes named Kibler, in essence, two timing us. Worse yet, she was using Horde funds to finance her operations.$B$BI want her brought back here alive.$B$BShe was last seen entering Blackrock Spire. Find her and bring her back.$B$BAnd $N, do not let her sweet talk you.",logDesc="Travel to Blackrock Spire and find out what happened to Bijou."} end
if not DB[4982] then DB[4982]={id=4982,zoneId=1583,name="Bijou's Belongings",level=59,minLevel=55,giver="Bijou",giverType="NPC",giverId=10257,ender="Bijou",enderType="NPC",enderId=10257,rewardNextId=4983,poiX=-11,poiY=-551,wowhead="https://www.wowhead.com/wotlk/quest=4982",image="assets/images/quests/placeholder.png",xpDiff=7,desc="At night when this place is lightly guarded, I sneak around the city, taking notes and writing down anything I see that could be of some strategic value to the K.E.F.$B$BLast night, however, things went dreadfully wrong. I stumbled across a tripwire and set off an alarm. I stashed my recon gear and ran for cover! Unfortunately, I can't get back to that gear. They've doubled and tripled up the patrols! All that information is lost.$B$BGet my belongings back and I'll return to the K.E.F. peacefully.",logDesc="Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city.$B"} end
if not DB[4983] then DB[4983]={id=4983,zoneId=1583,name="Bijou's Reconnaissance Report",level=59,minLevel=55,giver="Bijou",giverType="NPC",giverId=10257,ender="Lexlort",enderType="NPC",enderId=9080,poiX=-11,poiY=-551,wowhead="https://www.wowhead.com/wotlk/quest=4983",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="Take this report back to Lexlort. It will redeem my good name and will surely give the K.E.F. a strategic advantage in dealing with these orcs.$B$BCome with you? I've got way too much work to do. Get going, they need these reports as soon as possible!$B",logDesc="Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath.$B",choiceRewards={{id=15858,qty=1},{id=15859,qty=1}}} end
if not DB[4984] then DB[4984]={id=4984,zoneId=28,name="The Wildlife Suffers Too",level=54,minLevel=51,giver="Mulgris Deepriver",giverType="NPC",giverId=10739,ender="Mulgris Deepriver",enderType="NPC",enderId=10739,rewardNextId=4985,poiX=1513,poiY=-1894,wowhead="https://www.wowhead.com/wotlk/quest=4984",image="assets/images/quests/placeholder.png",xpDiff=4,desc="While there was little I could do alone to thwart the Scourge, I nevertheless came to these lands to try and heal the damage done to nature.  Animals suffer from the plague that continues to choke these lands, unable to find mercy and peace.  I ask for you to continue what I could not finish here.$B$BThere is no salvation for the suffering animals but a sweet and merciful release.  Seek out diseased wolves nearby and put them down.  Please $N, end their misery - doing so will surely soothe mine.",logDesc="Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.$B$B"} end
if not DB[4985] then DB[4985]={id=4985,zoneId=28,name="The Wildlife Suffers Too",level=56,minLevel=51,giver="Mulgris Deepriver",giverType="NPC",giverId=10739,ender="Mulgris Deepriver",enderType="NPC",enderId=10739,poiX=1513,poiY=-1894,wowhead="https://www.wowhead.com/wotlk/quest=4985",image="assets/images/quests/placeholder.png",xpDiff=4,desc="To the east of where we are, near where the Eastern Plaguelands begin, once proud and majestic grizzlies roamed the countryside.  The plague released by the Scourge has sundered these beasts too.  They wander the countryside, agonized by the stiffening of their muscles and the rotting of their fur and flesh.$B$BI ask of you to end their misery as well.  The only cure for their suffering is a swift death, one that must be ministered by your hand.  ",logDesc="Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands."} end
if not DB[4986] then DB[4986]={id=4986,zoneId=28,name="Glyphed Oaken Branch",level=56,minLevel=51,giver="Mulgris Deepriver",giverType="NPC",giverId=10739,ender="Mathrengyl Bearwalker",enderType="NPC",enderId=4217,poiX=1513,poiY=-1894,wowhead="https://www.wowhead.com/wotlk/quest=4986",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch.  Examining the branch reveals glyphs of a druidic nature carved into the bark.$B$BAs you grasp the branch, you notice it is warm to the touch, more than it should be.  The image of the Teldrassil tree enters your mind - Darnassus specifically - and the words \"Cenarion Circle\" are on the tip of your tongue.  It would appear that the suggestion of where to take the branch has been placed within it.",logDesc="Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought.  Seek one of the druids there for assistance.",rewards={{id=15804,qty=1}}} end
if not DB[4987] then DB[4987]={id=4987,zoneId=28,name="Glyphed Oaken Branch",level=56,minLevel=51,giver="Mulgris Deepriver",giverType="NPC",giverId=10739,ender="Nara Wildmane",enderType="NPC",enderId=5770,poiX=1513,poiY=-1894,wowhead="https://www.wowhead.com/wotlk/quest=4987",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch.  Examining the branch reveals glyphs of a druidic nature carved into the bark.$B$BAs you grasp the branch, you notice it is warm to the touch, more than it should be.  The image of Thunder Bluff in Mulgore enters your mind - Elder Rise specifically - and the words \"Cenarion Circle\" are on the tip of your tongue.  It would appear that the suggestion of where to take the branch has been placed within it.",logDesc="Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Thunder Bluff is the next step the tauren druid sought.  Seek one of the druids there for assistance.",rewards={{id=15804,qty=1}}} end
if not DB[5001] then DB[5001]={id=5001,zoneId=1583,name="Bijou's Belongings",level=59,minLevel=55,giver="Bijou",giverType="NPC",giverId=10257,ender="Bijou",enderType="NPC",enderId=10257,rewardNextId=5002,poiX=-11,poiY=-551,wowhead="https://www.wowhead.com/wotlk/quest=5001",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Ordinarily I don't deal with $rs but it seems that I'm stuck between a troll and a hard place. You see, my mission here is one of utmost importance to the Horde. The information I've discovered, however, applies to the well being of the Alliance as well. Now believe me, I'm no Alliance sympathizer, but the Blackrock threat is bigger than just a bunch of orcs.$B$BYou help me out by finding my belongings and I'll help you out with some information that could prove useful to your kind.$B$BDeal?",logDesc="Find Bijou's Belongings and return them to her. Good luck!$B"} end
if not DB[5002] then DB[5002]={id=5002,zoneId=1583,name="Message to Maxwell",level=59,minLevel=55,giver="Bijou",giverType="NPC",giverId=10257,ender="Marshal Maxwell",enderType="NPC",enderId=9560,rewardNextId=5081,poiX=-11,poiY=-551,wowhead="https://www.wowhead.com/wotlk/quest=5002",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="I'm a goblin of my word, $r. Now listen closely:$B$BThese orcs are used primarily as beasts of burden and cannon fodder for the black dragonflight!$B$BTheir true leader is none other than Nefarian, brood of Deathwing. I've also discovered the location of Nefarian's subordinates in this part of the citadel.$B$BTake this map to Marshal Maxwell in the Burning Steppes. It has the location of these fiends marked for easy identification.",logDesc="Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell."} end
if not DB[5021] then DB[5021]={id=5021,zoneId=28,name="Better Late Than Never",level=52,minLevel=50,giver="Janice Felstone",giverType="NPC",giverId=10778,poiX=1817,poiY=-1235,wowhead="https://www.wowhead.com/wotlk/quest=5021",image="assets/images/quests/placeholder.png",xpDiff=3,desc="\"The package must be delivered... delivered before I'm trapped here!\"$B$BThe cries of a panicked woman feel almost like a whisper floating through the house.  Cowered in the upstairs corner is the apparition of a woman.  She does not seem to be fully cognizant of her surroundings, and she is only vaguely aware of you.$B$B\"Are you here to deliver my package?  Please, before it gets much worse!  I was going to ride out of here.  It should still be by my horse... or am I too late?\"",logDesc="The ramblings of the ghostly woman indicated that she needed a package delivered.  She claimed that it was where her horse was.  As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible."} end
if not DB[5022] then DB[5022]={id=5022,zoneId=28,name="Better Late Than Never",level=52,minLevel=50,ender="Royal Factor Bathrilor",enderType="NPC",enderId=10782,rewardNextId=5048,wowhead="https://www.wowhead.com/wotlk/quest=5022",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You pick up the package, wiping off a small layer of dust and grime that had settled on it.  It is addressed in a hurried hand to an Emma Felstone of Stormwind; the delivery of the package is dated for well over four years ago.$B$BThough it is unclear if Emma Felstone is even alive, it is widely known that the Stormwind City Hall keep records on the populace of the city.  This is handled through the Royal Factors of the Stormwind Census.",logDesc="Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone.  There is usually a census officer located in City Hall."} end
if not DB[5023] then DB[5023]={id=5023,zoneId=28,name="Better Late Than Never",level=52,minLevel=50,ender="Royal Overseer Bauhaus",enderType="NPC",enderId=10781,rewardNextId=5049,wowhead="https://www.wowhead.com/wotlk/quest=5023",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You pick up the package, wiping off a small layer of dust and grime that had settled on it.  It is addressed in a hurried hand to a Jeremiah Felstone of Lordaeron; the delivery of the package is dated for well over four years ago.$B$BThough it is unclear if Jeremiah Felstone is even alive, it is widely known that the Undercity, formerly known as Lordaeron, keeps records on the populace of the city.  This is handled through the Royal Overseers of the Undercity Census.",logDesc="Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone.  There is usually a census officer located near guild and tabard registration."} end
if not DB[5041] then DB[5041]={id=5041,zoneId=17,name="Supplies for the Crossroads",level=14,minLevel=9,giver="Thork",giverType="NPC",giverId=3429,ender="Thork",enderType="NPC",enderId=3429,poiX=-473,poiY=-2596,wowhead="https://www.wowhead.com/wotlk/quest=5041",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="That attack on the caravan contained supplies we desperately needed.$B$BYou've been brave enough to take on the Razormane tribe so far, and I will ask you to do so again, but this time, I wonder if I could ask you to keep your eyes open for some of our lost supplies. You can probably find them throughout their camps, the quilboar getting fat off their dishonorable acts.$B$BThe people of the Crossroads would be in your debt.",logDesc="Find and return Crossroads' Supply Crates to Thork in the Barrens."} end
if not DB[5042] then DB[5042]={id=5042,zoneId=17,name="Agamaggan's Strength",level=20,minLevel=14,giver="Mangletooth",giverType="NPC",giverId=3430,ender="Mangletooth",enderType="NPC",enderId=3430,poiX=-2392,poiY=-1891,wowhead="https://www.wowhead.com/wotlk/quest=5042",image="assets/images/quests/placeholder.png"} end
if not DB[5043] then DB[5043]={id=5043,zoneId=17,name="Agamaggan's Agility",level=20,minLevel=14,giver="Mangletooth",giverType="NPC",giverId=3430,ender="Mangletooth",enderType="NPC",enderId=3430,poiX=-2392,poiY=-1891,wowhead="https://www.wowhead.com/wotlk/quest=5043",image="assets/images/quests/placeholder.png"} end
if not DB[5044] then DB[5044]={id=5044,zoneId=17,name="Wisdom of Agamaggan",level=20,minLevel=14,giver="Mangletooth",giverType="NPC",giverId=3430,ender="Mangletooth",enderType="NPC",enderId=3430,poiX=-2392,poiY=-1891,wowhead="https://www.wowhead.com/wotlk/quest=5044",image="assets/images/quests/placeholder.png"} end
if not DB[5045] then DB[5045]={id=5045,zoneId=17,name="Rising Spirit",level=20,minLevel=14,giver="Mangletooth",giverType="NPC",giverId=3430,ender="Mangletooth",enderType="NPC",enderId=3430,poiX=-2392,poiY=-1891,wowhead="https://www.wowhead.com/wotlk/quest=5045",image="assets/images/quests/placeholder.png"} end
if not DB[5046] then DB[5046]={id=5046,zoneId=17,name="Razorhide",level=20,minLevel=14,giver="Mangletooth",giverType="NPC",giverId=3430,ender="Mangletooth",enderType="NPC",enderId=3430,poiX=-2392,poiY=-1891,wowhead="https://www.wowhead.com/wotlk/quest=5046",image="assets/images/quests/placeholder.png"} end
if not DB[5047] then DB[5047]={id=5047,zoneId=1583,name="Finkle Einhorn, At Your Service!",level=60,minLevel=57,giver="Finkle Einhorn",giverType="NPC",giverId=10776,ender="Malyfous Darkhammer",enderType="NPC",enderId=10637,wowhead="https://www.wowhead.com/wotlk/quest=5047",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You'll find Malyfous Darkhammer in Everlook, $c. Tell him that 'Finkle is A-OK' and that the suit works perfectly.$B$BThen hand him this:$B$B<Finkle hands you a glowing piece of flesh.>$B$BI snatched it from the beast's innards during my 'vacation.'$B$BI bet Malyfous could give you a fairly accurate assessment of what he can do with parts from a monster like this!$B$BOh, I suppose you don't know where Everlook is, do you? To Winterspring, $g fella:lady;!",logDesc="Talk to Malyfous Darkhammer in Everlook."} end
if not DB[5048] then DB[5048]={id=5048,zoneId=1519,name="Good Natured Emma",level=52,minLevel=50,giver="Royal Factor Bathrilor",giverType="NPC",giverId=10782,ender="Ol' Emma",enderType="NPC",enderId=3520,rewardNextId=5050,poiX=-8553,poiY=729,wowhead="https://www.wowhead.com/wotlk/quest=5048",image="assets/images/quests/placeholder.png",xpDiff=5,desc="She's a tad ornery, and quite possibly out of her gourd... but the records indicate that Ol' Emma does fit the framework of who Emma Felstone might be.$B$BPerhaps you've seen Ol' Emma wander the city - she talks to herself, most often in nonsensical jibber-jabber.  Still, she doesn't hurt anything or anyone, so folks pretty much leave her be.$B$BAll things considered, I would say that Ol' Emma is in fact Emma Felstone.  You might try asking if her last name is indeed Felstone.",logDesc="Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone.  If she is, then perhaps she'd like the package Janice Felstone made for her."} end
if not DB[5049] then DB[5049]={id=5049,zoneId=1497,name="The Jeremiah Blues",level=52,minLevel=50,giver="Royal Overseer Bauhaus",giverType="NPC",giverId=10781,ender="Jeremiah Payson",enderType="NPC",enderId=8403,rewardNextId=5050,poiX=1602,poiY=204,wowhead="https://www.wowhead.com/wotlk/quest=5049",image="assets/images/quests/placeholder.png",xpDiff=5,desc="From the evidence I am able to muster, the person you seek - and the intended recipient of the parcel - is Jeremiah Payson, the Undercity cockroach vendor.$B$BI've always been of the opinion that it takes a special gift to sell... cockroaches.  No doubt you are on quite the epic sojourn now, mighty $c.  I will leave you to your world-shaping endeavors.  Allow me, however, to be a part of your magnum opus and reveal that he is located near the bank, suitably groveling under one of the walkways.",logDesc="Find Jeremiah Payson in the Undercity and see if he is in fact Jeremiah Felstone.  If he is, then perhaps he'd like the package Janice Felstone made for him."} end
if not DB[5050] then DB[5050]={id=5050,zoneId=28,name="Good Luck Charm",level=52,minLevel=50,giver="Ol' Emma",giverType="NPC",giverId=3520,ender="Janice Felstone",enderType="NPC",enderId=10778,rewardNextId=5051,poiX=-8656,poiY=677,wowhead="https://www.wowhead.com/wotlk/quest=5050",image="assets/images/quests/placeholder.png",xpDiff=3,desc="It would seem that I was wrong about you $N, and for that I owe you an apology.  My sister sent me a number of personal effects, including humorously enough the deed to the Felstone farm.  I think I'll pass on reclaiming it right now.$B$BIf my sister's spirit remains tethered to the farm and cannot rest, please... could you return this to her?  It is half of a good luck charm she had, with her husband having the other half.$B$BMaybe her knowing I have these things will now put her soul to rest.",logDesc="Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm."} end
if not DB[5051] then DB[5051]={id=5051,zoneId=28,name="Two Halves Become One",level=54,minLevel=50,giver="Janice Felstone",giverType="NPC",giverId=10778,ender="Janice Felstone",enderType="NPC",enderId=10778,poiX=1817,poiY=-1235,wowhead="https://www.wowhead.com/wotlk/quest=5051",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The ramblings of the poor ghost continue:$B$B\"I'm so cold, John.  Bring me your charm, and we'll be together!  Quickly John, before the plague comes to change us into hideous beasts!  I can't see you John... but I know you're near.  I feel you near me.\"$B$BPerhaps if the second half of the charm was found and reassembled, this would constitute what the spirit of Janice Felstone is seeking.",logDesc="Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.$B$BGive the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands.",rewards={{id=13473,qty=1}}} end
if not DB[5052] then DB[5052]={id=5052,zoneId=17,name="Blood Shards of Agamaggan",level=21,minLevel=14,giver="Mangletooth",giverType="NPC",giverId=3430,ender="Mangletooth",enderType="NPC",enderId=3430,poiX=-2392,poiY=-1891,wowhead="https://www.wowhead.com/wotlk/quest=5052",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Along with the thorns, the blood affected <snort> other aspects of the earth: blood red stones mixed in with other minerals. The Bristleback dig up these shards and carry them as totems <snort> for strength in battle and as totems for their magics. <snort>$B$BI know the secrets of that magic.$B$BBring Mangletooth one of these blood shards to show you understand. Bring Mangletooth many of the shards, and he will bless you with quilboar magic--the magic of Agamaggan! <snort>",logDesc="Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.$B$BCollect more Blood Shards if you want him to bless you with Agamaggan's power."} end
if not DB[5053] then DB[5053]={id=5053,zoneId=1939,name="<UNUSED>",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=5053",image="assets/images/quests/placeholder.png",desc="This quest will send you mail to your mail box. Just hit complete.",logDesc="Test quest to see if mail is sent to your mailbox. Just hit complete,then go check your mail.$B$BHave a nice day."} end
if not DB[5054] then DB[5054]={id=5054,zoneId=618,name="Ursius of the Shardtooth",level=56,minLevel=53,giver="Storm Shadowhoof",giverType="NPC",giverId=10303,ender="Storm Shadowhoof",enderType="NPC",enderId=10303,rewardNextId=5055,poiX=6717,poiY=-4714,wowhead="https://www.wowhead.com/wotlk/quest=5054",image="assets/images/quests/placeholder.png",xpDiff=5,desc="In the snowy mountains of Winterspring, to the northwest, a skilled hunter stalks his prey... I speak of Ursius of the shardtooth bears, an agile and clever beast.$B$BI send you now against him. He roams the sloping hills to the northwest of Everlook. Find and hunt him, before he discovers your intent.$B$BAll that have gone up against Ursius have quickly found themselves to be the prey, and he, the hunter. Stay on your guard.",logDesc="Storm Shadowhoof at Everlook in Winterspring wants you to kill Ursius."} end
if not DB[5055] then DB[5055]={id=5055,zoneId=618,name="Brumeran of the Chillwind",level=58,minLevel=53,giver="Storm Shadowhoof",giverType="NPC",giverId=10303,ender="Storm Shadowhoof",enderType="NPC",enderId=10303,rewardNextId=5056,poiX=6717,poiY=-4714,wowhead="https://www.wowhead.com/wotlk/quest=5055",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Swift, and clever, Brumeran glides silently across the snowy landscape of southern Winterspring. But do not let her graceful appearance convince you that she is harmless. All that cross her pay considerably, and often with their own lives.$B$BSeek out Brumeran of the chillwind among the chimera. Defeat her, then return again to me.",logDesc="Storm Shadowhoof at Everlook in Winterspring wants you to kill Brumeran."} end
if not DB[5056] then DB[5056]={id=5056,zoneId=618,name="Shy-Rotam",level=60,minLevel=53,giver="Storm Shadowhoof",giverType="NPC",giverId=10303,ender="Storm Shadowhoof",enderType="NPC",enderId=10303,poiX=6717,poiY=-4714,wowhead="https://www.wowhead.com/wotlk/quest=5056",image="assets/images/quests/placeholder.png",xpDiff=6,desc="In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam. Defeating the matriarch of the frostsabers would grant you much respect in the eyes of your fellow $r.$B$BGo again to the harsh wilds, and once there, gather sacred meat from the frostsabers. Find the stone of Shy-Rotam, and place it there. Placing the meat of her kin before her will summon Shy-Rotam, in anger.$B$BBe ready for her fury, and defeat her.",logDesc="Storm Shadowhoof at Everlook in Winterspring wants you to defeat Shy-Rotam.",choiceRewards={{id=15783,qty=1},{id=15782,qty=1}}} end
if not DB[5057] then DB[5057]={id=5057,zoneId=618,name="Past Endeavors",level=60,minLevel=53,giver="Storm Shadowhoof",giverType="NPC",giverId=10303,ender="Storm Shadowhoof",enderType="NPC",enderId=10303,poiX=6717,poiY=-4714,wowhead="https://www.wowhead.com/wotlk/quest=5057",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Before you spoke to me, $N, I had heard of your endeavors... that you had an unyielding desire to prove yourself, that you had an exceptional ability as a $c, and I now know these things to be the truth.$B$BThose that excel as you do are worthy of recognition. Take this marker to a friend of mine in Thunder Bluff named Melor Stonehoof. I'm sure he will remember you, and what you accomplished so long ago. Speak to him of you recent victories, and do not ever forget what you have accomplished today.",logDesc="Bring Storm Shadowhoof's Marker to Melor Stonehoof in Thunder Bluff.",rewards={{id=15704,qty=1}}} end
if not DB[5058] then DB[5058]={id=5058,zoneId=28,name="Mrs. Dalson's Diary",level=55,minLevel=52,wowhead="https://www.wowhead.com/wotlk/quest=5058",image="assets/images/quests/placeholder.png"} end
if not DB[5059] then DB[5059]={id=5059,zoneId=28,name="Locked Away",level=55,minLevel=52,wowhead="https://www.wowhead.com/wotlk/quest=5059",image="assets/images/quests/placeholder.png"} end
if not DB[5060] then DB[5060]={id=5060,zoneId=28,name="Locked Away",level=55,minLevel=52,wowhead="https://www.wowhead.com/wotlk/quest=5060",image="assets/images/quests/placeholder.png",xpDiff=6,money=25000,rewards={{id=13474,qty=1},{id=13475,qty=1}}} end
if not DB[5061] then DB[5061]={id=5061,zoneId=-263,name="Aquatic Form",level=-1,minLevel=16,giver="Dendrite Starblaze",giverType="NPC",giverId=11802,ender="Mathrengyl Bearwalker",enderType="NPC",enderId=4217,poiX=8020,poiY=-2679,wowhead="https://www.wowhead.com/wotlk/quest=5061",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect.  Go now back to your trainer, Mathrengyl Bearwalker, in Darnassus.  Show him your pendant and prove to him you are ready to learn what he has to teach you.  He will complete your training, allowing you to become one with the water.$B$BGoodbye, young druid.  We shall speak again.",logDesc="Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion.",rewards={{id=16608,qty=1}}} end
if not DB[5062] then DB[5062]={id=5062,zoneId=400,name="Sacred Fire",level=27,minLevel=24,giver="Motega Firemane",giverType="NPC",giverId=10428,ender="Magatha Grimtotem",enderType="NPC",enderId=4046,poiX=-4916,poiY=-1381,wowhead="https://www.wowhead.com/wotlk/quest=5062",image="assets/images/quests/placeholder.png",xpDiff=5,money=2200,desc="Arikara is a deadly creature that must be dealt with swiftly. In order to hunt her down you will need to light the sacred fire of life - this will summon Arikara.$B$BGo now and harvest the rare Incendia agave plant. Once you have harvested enough agave, seek council with Magatha Grimtotem on Elder Rise in Thunder Bluff. She is a powerful shaman that can enchant the agave plant to create a powder that will light the fire.$B$BTravel northeast to the Boiling Pool and gather Incendia Agave.",logDesc="Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff."} end
if not DB[5063] then DB[5063]={id=5063,zoneId=618,name="Cap of the Scarlet Savant",level=60,minLevel=57,ender="Malyfous Darkhammer",enderType="NPC",enderId=10637,wowhead="https://www.wowhead.com/wotlk/quest=5063",image="assets/images/quests/placeholder.png",desc="A finer cap you may never see. From the pristine hide of the beast, our expert crafters will create the most phenomenal hat a prestidigitator could ever hope to don!$B$BFifty gold pieces along with the listed items and your head shall be graced with the Cap of the Scarlet Savant:$B$B*The pristine hide of the Beast.$B$B*Frayed abomination stitchings.$B$B*Arcane crystals.$B$B*Enchanted scarlet thread.$B$BBEHOLD!",logDesc="In order to create the Cap of the Scarlet Savant, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread. $B$BYou will also be required to pay 50 gold pieces for the crafting of the item.",rewards={{id=12752,qty=1}}} end
if not DB[5064] then DB[5064]={id=5064,zoneId=400,name="Grimtotem Spying",level=28,minLevel=24,giver="Cliffwatcher Longhorn",giverType="NPC",giverId=10537,ender="Cliffwatcher Longhorn",enderType="NPC",enderId=10537,poiX=-5455,poiY=-2443,wowhead="https://www.wowhead.com/wotlk/quest=5064",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N, you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks. We discovered that separate chests in Darkcloud Pinnacle hold these guarded messages.$b$b$N, if you succeed in this dangerous mission, I will reward you in kind.$B",logDesc="Locate and retrieve the three Secret Notes in Darkcloud Pinnacle.",choiceRewards={{id=15457,qty=1},{id=15458,qty=1},{id=15459,qty=1}}} end
if not DB[5065] then DB[5065]={id=5065,zoneId=139,name="The Lost Tablets of Mosh'aru",level=58,minLevel=40,giver="Prospector Ironboot",giverType="NPC",giverId=10460,ender="Prospector Ironboot",enderType="NPC",enderId=10460,rewardNextId=4788,poiX=-6980,poiY=-4834,wowhead="https://www.wowhead.com/wotlk/quest=5065",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The troll with whom you spoke did not tell the truth.  The two tablets you gained for him spoke of containing the essence of Hakkar, but there is more to that legend.  I have studied long, and found that there are six Tablets of Mosh'aru, not two!  Six!$B$BAnd I fear that we will not like what secrets the others hold..$B$BFind the third and fourth tablets of Mosh'aru.  They're in the Eastern Plaguelands, held by the mossflayer trolls. Find them, and bring them to me.",logDesc="Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris."} end
if not DB[5066] then DB[5066]={id=5066,zoneId=1519,name="A Call to Arms: The Plaguelands!",level=50,minLevel=50,giver="Crier Goodman",giverType="NPC",giverId=2198,ender="Commander Ashlam Valorfist",enderType="NPC",enderId=10838,rewardNextId=5092,poiX=-8854,poiY=743,wowhead="https://www.wowhead.com/wotlk/quest=5066",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hear ye, hear ye!  All heroes are called upon to heed these words!$B$BA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!$B$BHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!",logDesc="Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains."} end
if not DB[5067] then DB[5067]={id=5067,zoneId=618,name="Leggings of Arcana",level=60,minLevel=57,ender="Malyfous Darkhammer",enderType="NPC",enderId=10637,wowhead="https://www.wowhead.com/wotlk/quest=5067",image="assets/images/quests/placeholder.png",desc="While the crafting of such an item has never successfully been accomplished, it is thought to be possible - under the right circumstance.$B$BShould the seeker of arcanum desire to imbue leggings with immense power, the following they must find:$B$B* The pristine hide of the Beast.$B$B* Frayed abomination stitchings.$B$B*Arcanite Bars.$B$B*Frostwhisper's embalming fluid.$B$BBEHOLD!",logDesc="In order to create the Leggings of Arcana, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Frostwhisper's Embalming Fluid.$B$BYou will also be required to pay 50 gold pieces for the crafting of the item.",rewards={{id=12756,qty=1}}} end
if not DB[5068] then DB[5068]={id=5068,zoneId=618,name="Breastplate of Bloodthirst",level=60,minLevel=57,ender="Malyfous Darkhammer",enderType="NPC",enderId=10637,wowhead="https://www.wowhead.com/wotlk/quest=5068",image="assets/images/quests/placeholder.png",desc="It is said that only one Breastplate of Bloodthirst has ever been created and that it was made for the legendary assassin, Garona. Whether this world will ever see another is doubtful.$B$BRegardless! Our master crafters can reproduce the item given the necessary components:$B$B*The pristine hide of the Beast.$B$B*Frayed abomination stitchings.$B$B*Arcanite bars.$B$B*The skin of shadow.$B$BBEHOLD!",logDesc="In order to create the Breastplate of Bloodthirst, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 10 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Skin of Shadow.$B$BYou will also be required to pay 50 gold pieces for the crafting of the item.",rewards={{id=12757,qty=1}}} end
if not DB[5081] then DB[5081]={id=5081,zoneId=1583,name="Maxwell's Mission",level=60,minLevel=55,giver="Marshal Maxwell",giverType="NPC",giverId=9560,ender="Marshal Maxwell",enderType="NPC",enderId=9560,poiX=-8379,poiY=-2749,wowhead="https://www.wowhead.com/wotlk/quest=5081",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="This information fills in the gaps to our otherwise impeccable intelligence of Blackrock Spire.$B$BThe attack must be decisive, $N.$B$BFirst their war master, the troll Voone, must be destroyed. Without his battle plans, the Blackrock orcs will be thrown into chaos.$B$BYou must then take out the ogre Highlord, Omokk. The cowardly ogres of Blackrock are powerless without his leadership.$B$BLastly, the overlord of the citadel: Wyrmthalak. With Wyrmthalak dead, their central command unit is without a conduit.",logDesc="Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak.",choiceRewards={{id=13958,qty=1},{id=13959,qty=1},{id=13961,qty=1},{id=13962,qty=1},{id=13963,qty=1}}} end
if not DB[5082] then DB[5082]={id=5082,zoneId=618,name="Threat of the Winterfall",level=56,minLevel=52,giver="Donova Snowden",giverType="NPC",giverId=9298,ender="Donova Snowden",enderType="NPC",enderId=9298,poiX=6396,poiY=-2537,wowhead="https://www.wowhead.com/wotlk/quest=5082",image="assets/images/quests/placeholder.png",xpDiff=5,money=8500,desc="I came to Winterspring to investigate the Frostfire Hot Springs. I've noticed that the water seems to have ...strange qualities. I haven't yet been able to discover the source, and to tell you the truth, I've had some difficulty lately, due to the Winterfall furbolg.$B$BThey seem to be drawn to the springs, just as I am. They have become extremely protective of the water, and won't let me come near the two larger springs to the north of here.$B$BI'd like to continue my studies, so won't you help me?",logDesc="Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics."} end
if not DB[5083] then DB[5083]={id=5083,zoneId=618,name="Winterfall Firewater",level=56,minLevel=52,ender="Donova Snowden",enderType="NPC",enderId=9298,rewardNextId=5084,wowhead="https://www.wowhead.com/wotlk/quest=5083",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This vial that you picked up from the Winterfall furbolg is empty, but you can detect a few drops of a strange green liquid inside; it almost glows.$B$BIs it something important?$B$BDonova Snowden would probably be able to tell you more, since she has been camped by the hot springs in Winterspring for some time now.",logDesc="Bring the Empty Firewater Flask to Donova Snowden in Winterspring."} end
if not DB[5084] then DB[5084]={id=5084,zoneId=618,name="Falling to Corruption",level=56,minLevel=52,giver="Donova Snowden",giverType="NPC",giverId=9298,rewardNextId=5085,poiX=6396,poiY=-2537,wowhead="https://www.wowhead.com/wotlk/quest=5084",image="assets/images/quests/placeholder.png",xpDiff=4,desc="This greenish liquid... it reminds me a bit of the sludge I saw when traveling through Felwood. And I have seen some Winterfall Runners passing into Timbermaw... Perhaps these things have something to do with the flask you found, $N.$B$BThere is a large group of furbolg just past Timbermaw Hold, in Felwood. Called the Deadwood tribe, they have been corrupted and driven mad by the fel. Why don't you look around there and see if you can find any evidence of dealings between the Winterfall and the Deadwood?",logDesc="Search the Deadwood furbolg camp in northern Felwood for a clue."} end
if not DB[5085] then DB[5085]={id=5085,zoneId=618,name="Mystery Goo",level=56,minLevel=52,ender="Donova Snowden",enderType="NPC",enderId=9298,rewardNextId=5086,wowhead="https://www.wowhead.com/wotlk/quest=5085",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The greenish substance inside the cauldron appears to be similar to what you found in the flask. This strange gooey stuff could be as corrupted as the furbolg that created it...$B$BIf the Winterfall furbolg are using it, does this mean that they will soon be as corrupted as the Deadwood tribe?$B$BIt would be best to report back to Donova with your findings, along with a sample of the liquid in the cauldron.",logDesc="Report back to Donova Snowden with your findings."} end
if not DB[5086] then DB[5086]={id=5086,zoneId=618,name="Toxic Horrors",level=56,minLevel=52,giver="Donova Snowden",giverType="NPC",giverId=9298,ender="Donova Snowden",enderType="NPC",enderId=9298,rewardNextId=5087,poiX=6396,poiY=-2537,wowhead="https://www.wowhead.com/wotlk/quest=5086",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've studied the sample you returned with, and while I can't say for sure, I believe it contains traces of toxic elements. However, the only way to know for sure is to gather some as a comparison.$B$BI believe that the Deadwood furbolg may be gathering these elements from other corrupted creatures in Felwood; in particular, the elementals living in the Irontree Woods, called toxic horrors.$B$BCollect a few samples for me to compare, but be careful -- it's very dangerous there!",logDesc="Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring."} end
if not DB[5087] then DB[5087]={id=5087,zoneId=618,name="Winterfall Runners",level=57,minLevel=52,giver="Donova Snowden",giverType="NPC",giverId=9298,ender="Donova Snowden",enderType="NPC",enderId=9298,rewardNextId=5121,poiX=6396,poiY=-2537,wowhead="https://www.wowhead.com/wotlk/quest=5087",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Very interesting, $N...$B$BWhen this toxic substance is mixed with the water from the hot springs, it loses its toxicity, only retaining the ability to temporarily affect those that ingest it. This must be why the Winterfall protect the hot springs so fervently -- they need them to purify their firewater.$B$BWe need to stop this -- cut off contact between the Winterfall and the Deadwood. A group of runners walks the distance between their village and Felwood. Find and defeat them, and steal their shipment.",logDesc="Find the Winterfall Runners and stop them from delivering their shipment to Winterfall Village."} end
if not DB[5088] then DB[5088]={id=5088,zoneId=400,name="Arikara",level=28,minLevel=24,giver="Magatha Grimtotem",giverType="NPC",giverId=4046,ender="Motega Firemane",enderType="NPC",enderId=10428,poiX=-1065,poiY=-212,wowhead="https://www.wowhead.com/wotlk/quest=5088",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead.$B$BThe enchantment that I have weaved into the Incendia powder will summon Arikara to you, $N.$B$BI fear she may be stalking Cairne Bloodhoof; too much Tauren lore has changed, and I fear this has angered Arikara. Move quickly before all is lost, $c!",logDesc="Slay Arikara. Bring her remains and the Incendia powder to Motega Firemane in Whitereach Post as proof of your deed.",choiceRewards={{id=15464,qty=1},{id=15465,qty=1},{id=15466,qty=1}}} end
if not DB[5089] then DB[5089]={id=5089,zoneId=1583,name="General Drakkisath's Command",level=60,minLevel=55,ender="Marshal Maxwell",enderType="NPC",enderId=9560,rewardNextId=5102,wowhead="https://www.wowhead.com/wotlk/quest=5089",image="assets/images/quests/placeholder.png",xpDiff=7,desc="From the corpse of the defeated serpent you uncover what appears to be a note of some importance: A letter from his superior, General Drakkisath, concerning protocol.$B$BYour instinct tells you that you should take it to Marshal Maxwell.",logDesc="Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes."} end
if not DB[5090] then DB[5090]={id=5090,zoneId=1537,name="A Call to Arms: The Plaguelands!",level=50,minLevel=50,giver="Courier Hammerfall",giverType="NPC",giverId=10877,ender="Commander Ashlam Valorfist",enderType="NPC",enderId=10838,rewardNextId=5092,poiX=-4999,poiY=-1156,wowhead="https://www.wowhead.com/wotlk/quest=5090",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hear ye, hear ye!  All heroes are called upon to heed these words!$B$BA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!$B$BHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!",logDesc="Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains."} end
if not DB[5091] then DB[5091]={id=5091,zoneId=1657,name="A Call to Arms: The Plaguelands!",level=50,minLevel=50,giver="Herald Moonstalker",giverType="NPC",giverId=10878,ender="Commander Ashlam Valorfist",enderType="NPC",enderId=10838,rewardNextId=5092,poiX=9660,poiY=2432,wowhead="https://www.wowhead.com/wotlk/quest=5091",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hear ye, hear ye!  All heroes are called upon to heed these words!$B$BA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!$B$BHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!",logDesc="Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains."} end
if not DB[5092] then DB[5092]={id=5092,zoneId=28,name="Clear the Way",level=52,minLevel=50,giver="Commander Ashlam Valorfist",giverType="NPC",giverId=10838,ender="Commander Ashlam Valorfist",enderType="NPC",enderId=10838,poiX=958,poiY=-1419,wowhead="https://www.wowhead.com/wotlk/quest=5092",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="With Andorhal's western and northern roads into the city well fortified, I'm looking to strike at it from the less defended eastern road.  The Scourge relies on the buffer of undead that infests Sorrow Hill as a first line of defense.  If we are to advance on Andorhal, we will need to do it through Sorrow Hill.$B$BYour first assignment will be to clear the way through Sorrow Hill.  Thin out the skeletons and ghouls that haunt the area; report back to me when this is done!",logDesc="Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill.$B$BReturn to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands."} end
if not DB[5093] then DB[5093]={id=5093,zoneId=28,name="A Call to Arms: The Plaguelands!",level=50,minLevel=50,giver="Warcaller Gorlach",giverType="NPC",giverId=10880,ender="High Executor Derrington",enderType="NPC",enderId=10837,rewardNextId=5096,poiX=1569,poiY=-4207,wowhead="https://www.wowhead.com/wotlk/quest=5093",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Heroes of the realm, hear me - the Horde calls upon you for swift action!$B$BA call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands!$B$BHeroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glade!",logDesc="Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity."} end
if not DB[5094] then DB[5094]={id=5094,zoneId=28,name="A Call to Arms: The Plaguelands!",level=50,minLevel=50,giver="Harbinger Balthazad",giverType="NPC",giverId=10879,ender="High Executor Derrington",enderType="NPC",enderId=10837,rewardNextId=5096,poiX=1570,poiY=215,wowhead="https://www.wowhead.com/wotlk/quest=5094",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Heroes of the realm, hear me - the Horde calls upon you for swift action!$B$BA call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands!$B$BHeroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glade!",logDesc="Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity."} end
if not DB[5095] then DB[5095]={id=5095,zoneId=28,name="A Call to Arms: The Plaguelands!",level=50,minLevel=50,giver="Bluff Runner Windstrider",giverType="NPC",giverId=10881,ender="High Executor Derrington",enderType="NPC",enderId=10837,rewardNextId=5096,poiX=-1231,poiY=137,wowhead="https://www.wowhead.com/wotlk/quest=5095",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Heroes of the realm, hear me - the Horde calls upon you for swift action!$B$BA call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands!$B$BHeroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glades!",logDesc="Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glades and the Undercity."} end
if not DB[5096] then DB[5096]={id=5096,zoneId=28,name="Scarlet Diversions",level=53,minLevel=50,giver="High Executor Derrington",giverType="NPC",giverId=10837,ender="High Executor Derrington",enderType="NPC",enderId=10837,poiX=1761,poiY=-723,wowhead="https://www.wowhead.com/wotlk/quest=5096",image="assets/images/quests/placeholder.png",xpDiff=5,money=8000,desc="Before Andorhal, we must tackle the advancing Scarlet Crusade menace from Hearthglen.  They've made camp between Felstone Field and Dalson's Tears, making us risk conflict against both the Scourge and the Crusade at once.$B$BMy plan is to play them off of each other by sending you to destroy the command tent they've set up; use some Flame in a Bottle from this box of incendiaries.  Once razed, plant this Scourge banner by the tent.  With some luck, they'll ignore us and focus on the Scourge for vengeance.",logDesc="Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent.$B$BPlace the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands."} end
if not DB[5097] then DB[5097]={id=5097,zoneId=28,name="All Along the Watchtowers",level=56,minLevel=50,giver="Commander Ashlam Valorfist",giverType="NPC",giverId=10838,ender="Commander Ashlam Valorfist",enderType="NPC",enderId=10838,poiX=958,poiY=-1419,wowhead="https://www.wowhead.com/wotlk/quest=5097",image="assets/images/quests/placeholder.png",xpDiff=5,money=8500,desc="Through the use of a magical device known as a beacon torch, we can mark targets of our choosing for future actions by our troops.  To that end, we think the Scourge are using Andorhal's watchtowers as a means to control their troop movements.$B$BYour mission: breach Andorhal's defenses to plant beacons at all four watchtowers.  You'll need to be in the doorway of each tower to plant the beacon; it will then proceed to mark the tower.  There are only five charges on the beacon torch, so use them wisely!",logDesc="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.$B$BOnce all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands."} end
if not DB[5098] then DB[5098]={id=5098,zoneId=28,name="All Along the Watchtowers",level=56,minLevel=50,giver="High Executor Derrington",giverType="NPC",giverId=10837,ender="High Executor Derrington",enderType="NPC",enderId=10837,poiX=1761,poiY=-723,wowhead="https://www.wowhead.com/wotlk/quest=5098",image="assets/images/quests/placeholder.png",xpDiff=5,money=8500,desc="Through the use of a magical device known as a beacon torch, we can mark targets of our choosing for future actions by our troops.  To that end, we think the Scourge are using Andorhal's watchtowers as a means to control their troop movements.$B$BYour mission: breach Andorhal's defenses to plant beacons at all four watchtowers.  You'll need to be in the doorway of each tower to plant the beacon; it will then proceed to mark the tower.  There are only five charges on the beacon torch, so use them wisely!",logDesc="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.$B$BOnce all four towers are marked, return the Beacon Torch to High Executor Derrington at the Bulwark, Western Plaguelands."} end
if not DB[5101] then DB[5101]={id=5101,zoneId=-284,name="Lee's Ultimate Test Quest... of Doom!",level=5,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=5101",image="assets/images/quests/placeholder.png",xpDiff=5,money=25,desc="Bah! What do think this is, some kind of Test Quest? I be there even be typos in it!$B$BIf ya be thinkin' my quest is goin' ta be easy, then ya got another thing coming!$B$BKill me ten sheep (1933) and don't come back until you do!",logDesc="Kill 6 sheep for Benny and then run like hell!$B$B$B$B$BJust kidding... about the running part.",rewards={{id=864,qty=1}}} end
if not DB[5102] then DB[5102]={id=5102,zoneId=1583,name="General Drakkisath's Demise",level=60,minLevel=55,giver="Marshal Maxwell",giverType="NPC",giverId=9560,ender="Marshal Maxwell",enderType="NPC",enderId=9560,poiX=-8379,poiY=-2749,wowhead="https://www.wowhead.com/wotlk/quest=5102",image="assets/images/quests/placeholder.png",xpDiff=7,money=27000,desc="We battle against these beasts on two fronts: From our capital of Stormwind we fight them from the inside out and here, in the Burning Steppes, we take the battle to their doorstep. We must be vigilant, $N. None should be spared our wrath as none of our own were spared when they struck at our homes and families.$B$BFind this General Drakkisath and destroy him!$B$BThe task certainly will not be a simple one, but the rewards shall be extravagant.",logDesc="Travel to Blackrock Spire and slay General Drakkisath.",choiceRewards={{id=13966,qty=1},{id=13968,qty=1},{id=13965,qty=1}}} end
if not DB[5103] then DB[5103]={id=5103,zoneId=-121,name="Hot Fiery Death",level=60,minLevel=55,ender="Malyfous Darkhammer",enderType="NPC",enderId=10637,rewardNextId=5124,wowhead="https://www.wowhead.com/wotlk/quest=5103",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The only thing that remains of this human are some charred bones. He seems to have died within arms reach of what he was after - unfired plate gauntlets.$B$BPerhaps you should grab the gauntlets and get out of the fire?",logDesc="Someone in this world must know what to do with these gauntlets. Good luck!"} end
if not DB[5121] then DB[5121]={id=5121,zoneId=618,name="High Chief Winterfall",level=59,minLevel=52,giver="Donova Snowden",giverType="NPC",giverId=9298,ender="Donova Snowden",enderType="NPC",enderId=9298,poiX=6396,poiY=-2537,wowhead="https://www.wowhead.com/wotlk/quest=5121",image="assets/images/quests/placeholder.png",xpDiff=6,desc="While we still know very little about why the furbolg have been ingesting this strange substance, I do think it's best that we put a stop to it before it gets out of hand.$B$BThe Winterfall furbolg are not a normally aggressive tribe, and this change in their behavior leads me to think that they must be under orders from their chief. We most likely can't undo the damage that has already been done, but I think that if their leader is slain, they will not get any worse.$B$BHead east to Winterfall Village.",logDesc="Donova Snowden in Winterspring wants you to defeat High Chief Winterfall.",choiceRewards={{id=15784,qty=1},{id=15786,qty=1},{id=15787,qty=1}}} end
if not DB[5122] then DB[5122]={id=5122,zoneId=2017,name="The Medallion of Faith",level=60,minLevel=55,giver="Aurius",giverType="NPC",giverId=10917,ender="Aurius",enderType="NPC",enderId=10917,poiX=3681,poiY=-3644,wowhead="https://www.wowhead.com/wotlk/quest=5122",image="assets/images/quests/placeholder.png"} end
if not DB[5123] then DB[5123]={id=5123,zoneId=618,name="The Final Piece",level=59,minLevel=52,ender="Donova Snowden",enderType="NPC",enderId=9298,wowhead="https://www.wowhead.com/wotlk/quest=5123",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The log you found on the high chief looks extensive, but after looking through a couple of the pages, you find that you cannot read the text. The markings are so crude and poorly-formed that you are not sure if anyone would be able to read them.$B$BBut perhaps Donova will be able to tell you what it says... ",logDesc="Bring the Crudely-written Log to Donova Snowden in Winterspring."} end
if not DB[5124] then DB[5124]={id=5124,zoneId=618,name="Fiery Plate Gauntlets",level=60,minLevel=55,giver="Malyfous Darkhammer",giverType="NPC",giverId=10637,ender="Malyfous Darkhammer",enderType="NPC",enderId=10637,poiX=6698,poiY=-4647,wowhead="https://www.wowhead.com/wotlk/quest=5124",image="assets/images/quests/placeholder.png",xpDiff=6,desc="By Thaurissan's beard!$B$BWhere did you find them?$B$BMore importantly, are you willing to part with them? Naturally, I would pay you for such a noble gesture.$B$BI'll tell you what, $N. If you give me those unfired gauntlets, I will teach you how to make a set all your own. All you need to do is collect the parts for me so that I may narrow down the exact recipe.$B$BDo we have a deal??$B$BHere's the list of what I need, I'll front the non-enchanted thorium myself since you're supplying the gauntlets.$B",logDesc="Bring Malyfous Darkhammer 6 Enchanted Thorium Bars, 2 Essence of Fire, and 4 Star Rubies. You will also need to turn in your Unfired Plate Gauntlets.",rewards={{id=12699,qty=1},{id=12631,qty=1}}} end
if not DB[5125] then DB[5125]={id=5125,zoneId=2017,name="Aurius' Reckoning",level=60,minLevel=55,giver="Aurius",giverType="NPC",giverId=10917,ender="Aurius",enderType="NPC",enderId=10917,poiX=3681,poiY=-3644,wowhead="https://www.wowhead.com/wotlk/quest=5125",image="assets/images/quests/placeholder.png",xpDiff=7,choiceRewards={{id=17044,qty=1},{id=17045,qty=1}}} end
if not DB[5126] then DB[5126]={id=5126,zoneId=618,name="Lorax's Tale",level=60,minLevel=55,giver="Lorax",giverType="NPC",giverId=10918,ender="Lorax",enderType="NPC",enderId=10918,poiX=5042,poiY=-4846,wowhead="https://www.wowhead.com/wotlk/quest=5126",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Satyr paces about and talks to himself. Do you wish to question him?",logDesc="Speak with Lorax. Listen to what he has to say.$B"} end
if not DB[5127] then DB[5127]={id=5127,zoneId=1583,name="The Demon Forge",level=60,minLevel=55,giver="Lorax",giverType="NPC",giverId=10918,ender="Lorax",enderType="NPC",enderId=10918,poiX=5042,poiY=-4846,wowhead="https://www.wowhead.com/wotlk/quest=5127",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Lorax makes deals, he does not accept them from insignificant mortals.$B$BA deal I shall make with you, however... take this pike, it is imbued with powerful Fel energies. When you find Goraluk Anvilcrack, slay him and drive this pike through his dying heart. His soul he bartered, his soul I shall have. Return the pike and return the breastplate that the thief stole and I shall teach you what it is that he was to learn.",logDesc="Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.$B$BYou must also find the Unforged Rune Covered Breastplate.$B$BReturn both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.",rewards={{id=12696,qty=1},{id=9224,qty=5},{id=12849,qty=1}}} end
if not DB[5128] then DB[5128]={id=5128,zoneId=618,name="Words of the High Chief",level=59,minLevel=52,giver="Donova Snowden",giverType="NPC",giverId=9298,ender="Kelek Skykeeper",enderType="NPC",enderId=10920,poiX=6396,poiY=-2537,wowhead="https://www.wowhead.com/wotlk/quest=5128",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Winterfall are no longer a threat to me, but if you still want to find out what was driving the furbolg to create and consume this strange firewater, I think you should seek out Kelek Skykeeper.$B$BHe is part of a group known as the Emerald Circle, druids that are committed to their work in Felwood, healing the land from the corruption.$B$BKelek has much experience with the furbolgs in Felwood, and may be able to tell you more about the log.$B$BThank you, again, $N.",logDesc="Take the Crudely-written Log to Kelek Skykeeper in southern Felwood.",choiceRewards={{id=34423,qty=1},{id=34424,qty=1}}} end
if not DB[5141] then DB[5141]={id=5141,zoneId=-182,name="Dragonscale Leatherworking",level=55,minLevel=40,giver="Peter Galen",giverType="NPC",giverId=7866,ender="Peter Galen",enderType="NPC",enderId=7866,poiX=3130,poiY=-5183,wowhead="https://www.wowhead.com/wotlk/quest=5141",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Dragonscale leatherworking isn't easy, but it's extremely rewarding.  I'll teach you how to make this fine mail armor, but only if you agree to certain conditions.$B$BBy choosing this path, you agree never to learn elemental or tribal leatherworking; there is only room for one of the three at the apex of the craft.  Furthermore, I'll need some samples of your best work involving scorpid armor.  Finally, I'll need proof of your ability to acquire the staple of the trade: scales of the dragonkin.",logDesc="Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Peter Galen in Azshara.$B$BCompleting this quest will give you access to the Dragonscale Leatherworking arts.$B$BThe completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so."} end
if not DB[5142] then DB[5142]={id=5142,zoneId=139,name="Little Pamela",level=55,minLevel=50,giver="Marlene Redpath",giverType="NPC",giverId=10927,ender="Pamela Redpath",enderType="NPC",enderId=10926,rewardNextId=5149,poiX=1114,poiY=-1697,wowhead="https://www.wowhead.com/wotlk/quest=5142",image="assets/images/quests/placeholder.png",xpDiff=3,desc="So many of us died at the battle of Darrowshire.  So many died... and worse.$B$BWhen the battle began I hid my niece Pamela, and I do not know what happened to her.  I am but a wandering spirit, but my heart still longs to know Pamela's fate.$B$BPlease, good $c.  Will you go to Darrowshire and search for her?  It is to the east, beyond Gahrron's Withering.",logDesc="Find Pamela Redpath in Darrowshire."} end
if not DB[5143] then DB[5143]={id=5143,zoneId=-182,name="Tribal Leatherworking",level=55,minLevel=40,giver="Caryssia Moonhunter",giverType="NPC",giverId=7870,ender="Caryssia Moonhunter",enderType="NPC",enderId=7870,poiX=-4524,poiY=-773,wowhead="https://www.wowhead.com/wotlk/quest=5143",image="assets/images/quests/placeholder.png",xpDiff=4,desc="To learn tribal leatherworking demands an understanding of how primal nature truly is; I know that you have already mastered the art of making wild leather armor, and I am willing to complete your training.$B$BKnow this, $c: by choosing this path you agree never to learn dragonscale or elemental leatherworking; there is only room for practice of one of the three arts.  Furthermore, bring to me the finest samples of your wild leather armor.  From there, we will begin your mastery.",logDesc="Bring a Wild Leather Vest and a Wild Leather Helmet to Caryssia Moonhunter in Feralas.$B$BCompleting this quest will give you access to the Tribal Leatherworking arts.$B$BThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so."} end
if not DB[5144] then DB[5144]={id=5144,zoneId=-182,name="Elemental Leatherworking",level=55,minLevel=40,giver="Sarah Tanner",giverType="NPC",giverId=7868,ender="Sarah Tanner",enderType="NPC",enderId=7868,poiX=-7230,poiY=-1741,wowhead="https://www.wowhead.com/wotlk/quest=5144",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Elemental leatherworking is what I know, and if you're willing to open your mind to the greater powers of substance, I will share with you all there is to learn.$B$BKnow this, $c: by choosing this path you agree never to learn dragonscale or tribal leatherworking; there is only room for practice of one of the three arts.  Furthermore, I'll need adequate proof that you are in tune with the elements of nature; to that end, bring me the purest essences of fire, water, earth, and wind.",logDesc="Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Sarah Tanner in Searing Gorge.$B$BCompleting this quest will give you access to the Elemental Leatherworking arts.$B$BThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so."} end
if not DB[5145] then DB[5145]={id=5145,zoneId=-182,name="Dragonscale Leatherworking",level=55,minLevel=40,giver="Thorkaf Dragoneye",giverType="NPC",giverId=7867,ender="Thorkaf Dragoneye",enderType="NPC",enderId=7867,poiX=-6842,poiY=-3639,wowhead="https://www.wowhead.com/wotlk/quest=5145",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Dragonscale leatherworking isn't easy, but it's extremely rewarding.  I'll teach you how to make this fine mail armor, but only if you agree to certain conditions.$B$BBy choosing this path, you agree never to learn elemental or tribal leatherworking; there is only room for one of the three at the apex of the craft.  Furthermore, I'll need some samples of your best work involving scorpid armor.  Finally, I'll need proof of your ability to acquire the staple of the trade: scales of the dragonkin.",logDesc="Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Thorkaf Dragoneye in the Badlands.$B$BCompleting this quest will give you access to the Dragonscale Leatherworking arts.$B$BThe completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so."} end
if not DB[5146] then DB[5146]={id=5146,zoneId=-182,name="Elemental Leatherworking",level=55,minLevel=40,giver="Brumn Winterhoof",giverType="NPC",giverId=7869,ender="Brumn Winterhoof",enderType="NPC",enderId=7869,poiX=-1215,poiY=-1884,wowhead="https://www.wowhead.com/wotlk/quest=5146",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Elemental leatherworking is what I know, and if you're willing to open your mind to the greater powers of substance, I will share with you all there is to learn.$B$BKnow this, $c: by choosing this path you agree never to learn dragonscale or tribal leatherworking; there is only room for practice of one of the three arts.  Furthermore, I'll need adequate proof that you are in tune with the elements of nature; to that end, bring me the purest essences of fire, water, earth, and wind.",logDesc="Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Brumn Winterhoof in the Arathi Mountains.$B$BCompleting this quest will give you access to the Elemental Leatherworking arts.$B$BThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so."} end
if not DB[5147] then DB[5147]={id=5147,zoneId=400,name="Wanted - Arnak Grimtotem",level=29,minLevel=20,ender="Cliffwatcher Longhorn",enderType="NPC",enderId=10537,wowhead="https://www.wowhead.com/wotlk/quest=5147",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Wanted: Arnak Grimtotem$B$BArnak the outcast is wanted for the heinous crimes of murder and kidnapping. Handsome rewards will be given to those brave enough to bring this criminal to justice.$B$BArnak was last seen on the cliffs near the Darkcloud Pinnacle. Show the proof of your deed to Cliffwatcher Longhorn in Freewind Post in order to claim the reward.",logDesc="Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post.",choiceRewards={{id=15471,qty=1},{id=15470,qty=1}}} end
if not DB[5148] then DB[5148]={id=5148,zoneId=-182,name="Tribal Leatherworking",level=55,minLevel=40,giver="Se'Jib",giverType="NPC",giverId=7871,ender="Se'Jib",enderType="NPC",enderId=7871,poiX=-12619,poiY=-111,wowhead="https://www.wowhead.com/wotlk/quest=5148",image="assets/images/quests/placeholder.png",xpDiff=4,desc="To learn tribal leatherworking demands an understanding of how primal nature truly is; I know that you have already mastered the art of making wild leather armor, and I am willing to complete your training.$B$BKnow this, $c: by choosing this path you agree never to learn dragonscale or elemental leatherworking; there is only room for practice of one of the three arts.  Furthermore, bring to me the finest samples of your wild leather armor.  From there, we will begin your mastery.",logDesc="Bring a Wild Leather Vest and a Wild Leather Helmet to Se'Jib in Stranglethorn Vale.$B$BCompleting this quest will give you access to the Tribal Leatherworking arts.$B$BThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so."} end
if not DB[5149] then DB[5149]={id=5149,zoneId=139,name="Pamela's Doll",level=55,minLevel=50,giver="Pamela Redpath",giverType="NPC",giverId=10926,ender="Pamela Redpath",enderType="NPC",enderId=10926,poiX=1456,poiY=-3596,wowhead="https://www.wowhead.com/wotlk/quest=5149",image="assets/images/quests/placeholder.png",xpDiff=3,desc="My auntie Marlene told me to stay here in our house because my father had to go and fight.  My father's the bravest man in the whole world!$B$BBut I've been here for a long time, and he hasn't come for me.  Sometimes bad people come and whisper to me and I want my dad to make them go away, but he's not here!$B$BAnd sometimes when it gets dark I want to play with my doll but I can't because I left it in town.$B$BWill you find my doll for me?",logDesc="Find Pamela's doll."} end
if not DB[5150] then DB[5150]={id=5150,zoneId=490,name="Dadanga is Hungry!",level=55,minLevel=47,giver="Dadanga",giverType="NPC",giverId=9274,ender="Dadanga",enderType="NPC",enderId=9274,poiX=-6143,poiY=-1081,wowhead="https://www.wowhead.com/wotlk/quest=5150",image="assets/images/quests/placeholder.png",rewards={{id=15699,qty=1}}} end
if not DB[5151] then DB[5151]={id=5151,zoneId=400,name="Hypercapacitor Gizmo",level=30,minLevel=24,giver="Wizlo Bearingshiner",giverType="NPC",giverId=10941,ender="Wizlo Bearingshiner",enderType="NPC",enderId=10941,poiX=-4922,poiY=-1376,wowhead="https://www.wowhead.com/wotlk/quest=5151",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I am the only survivor from our caravan attack by the centaur! A rare yet mighty panther is guarding my best gizmo, which is around his neck. Hah! Even the centaur tremble in the presence of this ferocious beast!$B$BHere is the key to the cage. They took everything there, but left him alone. Slay this beast and bring back my hypercapacitor, and I shall reward you.$b$bThe wrecked caravan is just north of here.$B",logDesc="Slay the beast and bring back the Hypercapacitor Gizmo and Panther Cage Key to Wizlo Bearingshiner.",rewards={{id=15467,qty=1}}} end
if not DB[5152] then DB[5152]={id=5152,zoneId=139,name="Auntie Marlene",level=56,minLevel=50,giver="Pamela Redpath",giverType="NPC",giverId=10926,ender="Marlene Redpath",enderType="NPC",enderId=10927,rewardNextId=5153,poiX=1456,poiY=-3596,wowhead="https://www.wowhead.com/wotlk/quest=5152",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Oh, I'm so lonely!  Where is my family?  Auntie Marlene told me to stay here, but then she left and never came back!  And my dad... have you seen him?$B$BMaybe Auntie Marlene knows where he is.  She lives near Andorhal, in a house to the south.  I think it was on a hill... she said it was on a hill.$B$BPlease, $N.  You're my new friend!  Will you talk to my Auntie for me?",logDesc="Speak with Marlene, south of the Ruins of Andorhal."} end
if not DB[5153] then DB[5153]={id=5153,zoneId=139,name="A Strange Historian",level=56,minLevel=50,giver="Marlene Redpath",giverType="NPC",giverId=10927,ender="Chromie",enderType="NPC",enderId=10667,rewardNextId=5154,poiX=1114,poiY=-1697,wowhead="https://www.wowhead.com/wotlk/quest=5153",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I wish Joseph could again be with his daughter, but it cannot be so.  His soul was twisted by the Scourge, and he became a monster.  Oh, he is doomed!$B$BBut perhaps we can change his fate.$B$BSearch the graves outside for Joseph's monument.  His body's not there, for it was trampled and destroyed years ago, but under the monument is his wedding ring.  Take that ring to Chromie... a strange gnome with very strange powers.$B$BChromie is staying in the ruined inn at the northwest corner of Andorhal.",logDesc="Bring Joseph's Wedding Ring to Chromie."} end
if not DB[5154] then DB[5154]={id=5154,zoneId=28,name="The Annals of Darrowshire",level=56,minLevel=50,giver="Chromie",giverType="NPC",giverId=10667,ender="Chromie",enderType="NPC",enderId=10667,poiX=1453,poiY=-1280,wowhead="https://www.wowhead.com/wotlk/quest=5154",image="assets/images/quests/placeholder.png",xpDiff=5,desc="To save Joseph Redpath, we must first discover his past.  We can learn this in the Annals of Darrowshire, a book held in the city hall of Andorhal.$B$BBring me that book.  We can then learn Joseph's fate, and with luck... change it!",logDesc="Bring the Annals of Darrowshire to Chromie in Andorhal."} end
if not DB[5155] then DB[5155]={id=5155,zoneId=361,name="Forces of Jaedenar",level=51,minLevel=48,giver="Greta Mosshoof",giverType="NPC",giverId=10922,ender="Greta Mosshoof",enderType="NPC",enderId=10922,rewardNextId=5157,poiX=3986,poiY=-1303,wowhead="https://www.wowhead.com/wotlk/quest=5155",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If I am to trust you in this matter, you will first have to prove yourself.$B$BI must know that you are an enemy of the Shadow Council--the ones responsible for many evils here and abroad.$B$BTravel deeper into Felwood. To the west you will see a path leading to Jaedenar. It is there that the Council plots with the Burning Legion.$B$BEnter the depths of one of the corrupted Barrow Dens they inhabit and slay their kind. Return to me after you've done this. Then I will know you truly seek to help us.",logDesc="Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood."} end
if not DB[5156] then DB[5156]={id=5156,zoneId=361,name="Verifying the Corruption",level=54,minLevel=48,giver="Taronn Redfeather",giverType="NPC",giverId=10921,ender="Taronn Redfeather",enderType="NPC",enderId=10921,poiX=4005,poiY=-1284,wowhead="https://www.wowhead.com/wotlk/quest=5156",image="assets/images/quests/placeholder.png",xpDiff=6,money=16500,desc="To the north, along the east of the road in what's called Shatter Scar Vale, is an area where infernals were called down during the last great war--the craters still scar the land, as do the infernals themselves.$B$BI am curious about two things. First, are there still entropic elementals roaming the area? And second, are the craters still filled with the corrupt, fetid water that gathered there years ago? Will you help me and check, $N? Be careful though, the infernals destroy anything in their path.",logDesc="Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood."} end
if not DB[5157] then DB[5157]={id=5157,zoneId=361,name="Collection of the Corrupt Water",level=52,minLevel=48,giver="Greta Mosshoof",giverType="NPC",giverId=10922,ender="Greta Mosshoof",enderType="NPC",enderId=10922,rewardNextId=5158,poiX=3986,poiY=-1303,wowhead="https://www.wowhead.com/wotlk/quest=5157",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Deep within Jaedenar lies Shadow Hold--the main fortress of their corruption and evil.$B$BThe Shadow Council has protective spells surrounding their lair in the form of braziers. If I am to find out any more information about our enemy through scrying, then those braziers must be extinguished. By doing so, I should be able to spy on the Council and find out who leads them.$B$BIf you can, take this canteen and fill it at the Moon Well in the center of Jaedenar. Return to me afterwards.",logDesc="Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood."} end
if not DB[5158] then DB[5158]={id=5158,zoneId=361,name="Seeking Spiritual Aid",level=52,minLevel=48,giver="Greta Mosshoof",giverType="NPC",giverId=10922,ender="Islen Waterseer",enderType="NPC",enderId=5901,poiX=3986,poiY=-1303,wowhead="https://www.wowhead.com/wotlk/quest=5158",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Take the corrupt water to the Barrens, $N. South of Ratchet, hidden along the shore, is an old friend of mine, a shaman named Islen Waterseer. She is a powerful shaman who will help us. Her relationship with the spirits of water has always been strong. Our task being a noble one should be enough to persuade her and the spirits of water to aid us in this task.$B$BYou should find her at a small camp right along the water's edge. And, $N, ignore the pirates... they are but a nuisance and no threat to you.",logDesc="Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens."} end
if not DB[5159] then DB[5159]={id=5159,zoneId=361,name="Cleansed Water Returns to Felwood",level=54,minLevel=48,giver="Islen Waterseer",giverType="NPC",giverId=5901,ender="Greta Mosshoof",enderType="NPC",enderId=10922,rewardNextId=5165,poiX=-1345,poiY=-4048,wowhead="https://www.wowhead.com/wotlk/quest=5159",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Thank the spirits, $N. They are the ones that have come to your aid, not me.$B$BI give this purified water to you now. Please give my regards to Greta and my best wishes. She is tackling something greater than many of us... as I'm sure she will soon find out.$B$BThe Shadow Council is not a force to be trifled with, $N. Remember that.$B$BGo now. Take the water and return to Greta.",logDesc="Take the Purified Moon Well Water to Greta Mosshoof in Felwood."} end
if not DB[5160] then DB[5160]={id=5160,zoneId=1583,name="The Matron Protectorate",level=60,minLevel=57,giver="Awbee",giverType="NPC",giverId=10740,ender="Haleh",enderType="NPC",enderId=10929,rewardNextId=5161,poiX=71,poiY=-420,wowhead="https://www.wowhead.com/wotlk/quest=5160",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Travel to Kalimdor, $r. Our flight makes its home in the frigid landscape of Winterspring. Once you reach Winterspring, find the caves of Mazthoril.$B$BUpon the icy floors of Mazthoril you will find cobalt runes. Hold one of my scales and stand upon a rune and you shall be transported to Haleh, our matron protectorate.$B$BGive her the scale so that she may scry what it is I have seen and felt, here in this doomed place.",logDesc="Travel to Winterspring and find Haleh. Give her Awbee's scale."} end
if not DB[5161] then DB[5161]={id=5161,zoneId=618,name="Wrath of the Blue Flight",level=60,minLevel=57,giver="Haleh",giverType="NPC",giverId=10929,ender="Haleh",enderType="NPC",enderId=10929,rewardNextId=5162,poiX=6110,poiY=-4189,wowhead="https://www.wowhead.com/wotlk/quest=5161",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We understand what the cursed brood of Deathwing attempts to do and we know that it cannot be allowed.$B$BBecause of the protection Blackrock mountain affords Nefarian, it has become increasingly difficult for us to intercede.$B$BWe can, however, empower you, mortal - should you so choose.$B$BThe path before you is one full of peril. You must decide whether to accept our help. Ponder this and speak with me again when a decision has been made.",logDesc="Speak with Haleh if you wish to continue."} end
if not DB[5162] then DB[5162]={id=5162,zoneId=28,name="Wrath of the Blue Flight",level=60,minLevel=57,giver="Haleh",giverType="NPC",giverId=10929,ender="Jeziba",enderType="NPC",enderId=10976,rewardNextId=5164,poiX=6110,poiY=-4189,wowhead="https://www.wowhead.com/wotlk/quest=5162",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is the arcane that I control and the arcane which will send you to your next destination.$B$BWhen you are ready, the journey will begin. To the Plaguelands you will go and to Jeziba you will speak.$B$BHe is a mortal as wise as the ancients and as patient as the immovable earth. Find him in Andorhal.$B",logDesc="Speak with Jeziba in the Plaguelands. He resides in Andorhal."} end
if not DB[5163] then DB[5163]={id=5163,zoneId=618,name="Are We There, Yeti?",level=58,minLevel=52,giver="Umi Rumplesnicker",giverType="NPC",giverId=10305,ender="Umi Rumplesnicker",enderType="NPC",enderId=10305,poiX=6753,poiY=-4639,wowhead="https://www.wowhead.com/wotlk/quest=5163",image="assets/images/quests/placeholder.png",xpDiff=6,money=9000,desc="It's all ready, $N!$B$BNow, I sent some mail to my friends already, telling them that I have a surprise for them. This is where you come in!$B$BI'm going to give you my mechanical yeti, and you need to surprise them by paying each of my friends a visit, turning the yeti on and sending it towards them.$B$B Once you have shown Legacki in Everlook, Sprinkle in Gadgetzan, and Quixxil in Marshal's Refuge, come back and tell me what happened!$B$BPlease bring my yeti back to me then, too.",logDesc="Take Umi's Mechanical Yeti and scare her friends with it:$B$BLegacki in Everlook (Winterspring)$BSprinkle in Gadgetzan (Tanaris)$BQuixxil in Marshal's Refuge (Un'Goro Crater)$B$BWhen you are done, bring the Mechanical Yeti back to Umi.",rewards={{id=15778,qty=1}}} end
if not DB[5164] then DB[5164]={id=5164,zoneId=28,name="Catalogue of the Wayward",level=60,minLevel=57,giver="Jeziba",giverType="NPC",giverId=10976,poiX=1452,poiY=-1276,wowhead="https://www.wowhead.com/wotlk/quest=5164",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A finer instrument of justice, Haleh could not have chosen. Read from the catalogue of the wayward and be enlightened.$B$BShould you persist... should you do what is asked of you... should you survive... a hero you will make.",logDesc="Read from the Catalogue of the Wayward.$B"} end
if not DB[5165] then DB[5165]={id=5165,zoneId=361,name="Dousing the Flames of Protection",level=55,minLevel=48,giver="Greta Mosshoof",giverType="NPC",giverId=10922,ender="Greta Mosshoof",enderType="NPC",enderId=10922,poiX=3986,poiY=-1303,wowhead="https://www.wowhead.com/wotlk/quest=5165",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now, you must return to Jaedenar. The braziers are more than likely spread throughout Shadow Hold. Douse each of their flames and the protections the Council has set up will fall for at least a short period of time. I will be waiting for that to happen. When it does, I will look deep within the Hold and try to find out who the head of this beast is. Then, and only then, will we see about attacking them directly.",logDesc="Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary."} end
if not DB[5166] then DB[5166]={id=5166,zoneId=28,name="Breastplate of the Chromatic Flight",level=60,minLevel=57,ender="Jeziba",enderType="NPC",enderId=10976,wowhead="https://www.wowhead.com/wotlk/quest=5166",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The forging of a powerful breastplate to protect against the unrelenting attacks of the chromatic flight is one built upon irony.$B$BThe scales of the very beasts we battle must be sewn to the pristine carapace of an elder chromatic drake or dragon. None are known to exist at this time and we should hope that none will ever exist.$B$BLastly, perhaps the most difficult of all components: the blood of heroes.$B$BThe Sculptor must ultimately forge this creation.",logDesc="To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':$B$B1 Chromatic Carapace.$B$B10 Brilliant Chromatic Scales.$B$B10 Blood of Heroes.$B$B10 Frayed Abomination Stitchings.",rewards={{id=12895,qty=1}}} end
if not DB[5167] then DB[5167]={id=5167,zoneId=28,name="Legplates of the Chromatic Defier",level=60,minLevel=57,ender="Jeziba",enderType="NPC",enderId=10976,wowhead="https://www.wowhead.com/wotlk/quest=5167",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The carapace of a mature chromatic drake is needed to form the foundation of the leggings. Brilliant chromatic scales are then layered upon the wire frame and enchanted in the blood of heroes. Finally, the supple skin of shadow must be applied to the inner greaves.",logDesc="To forge the Legplates of the Chromatic Defier, you will be required to bring the following items to Jeziba the 'Sculptor':$B$B1 Chromatic Carapace.$B$B10 Brilliant Chromatic Scales.$B$B10 Blood of Heroes.$B$B5 Skin of Shadow.",choiceRewards={{id=12903,qty=1},{id=12945,qty=1}}} end
if not DB[5168] then DB[5168]={id=5168,zoneId=139,name="Heroes of Darrowshire",level=56,minLevel=50,giver="Carlin Redpath",giverType="NPC",giverId=11063,ender="Carlin Redpath",enderType="NPC",enderId=11063,poiX=2257,poiY=-5341,wowhead="https://www.wowhead.com/wotlk/quest=5168",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The heroes of Darrowshire hold a place in my heart, and the book you brought me, the Annals of Darrowshire, tells their tales.$B$BIt tells of the paladin Davil Lightfire and how the Crusade took his libram to the town hall of Hearthglen.$B$BIts passages also speak of my brother, Captain Redpath.  After his betrayal, his shield was cracked and discarded and now lies in the most unlikely of places -- near the barn of Gahrron's Withering.$B$BGather these relics, $N.  For fate and tragedy surrounds them.",logDesc="Bring Davil's Libram and Redpath's Shield to Carlin Redpath."} end
if not DB[5181] then DB[5181]={id=5181,zoneId=139,name="Villains of Darrowshire",level=57,minLevel=50,giver="Carlin Redpath",giverType="NPC",giverId=11063,ender="Carlin Redpath",enderType="NPC",enderId=11063,poiX=2257,poiY=-5341,wowhead="https://www.wowhead.com/wotlk/quest=5181",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  His body was cast into a lake, northwest of Corin's Crossing, and his skull remains there.$B$BMarduk the Black was never defeated, but his fabled sword was shattered and lost.  It lies at the bottom of the gorge west of Corin's Crossing.$B$BRetrieve these items, $N.  I know not why, but I am certain their fate lies with you.",logDesc="Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel."} end
if not DB[5201] then DB[5201]={id=5201,zoneId=618,name="Winterfall Intrusion",level=60,minLevel=58,giver="Rivern Frostwind",giverType="NPC",giverId=10618,ender="Rivern Frostwind",enderType="NPC",enderId=10618,poiX=8067,poiY=-3862,wowhead="https://www.wowhead.com/wotlk/quest=5201",image="assets/images/quests/placeholder.png",desc="My presence goes unnoticed by most, $N. However, there is an annoyance that seems firmly rooted here in Winterspring: the Winterfall furbolg.$B$BAlthough I have never directly attacked the furbolg, they seem crazed, fearful of anything in their path. I have watched them slay countless creatures that had the misfortune to simply be in the wrong place at the wrong time.$B$BI am weary of their meddling -- please, help me by fighting back. Slay the furbolg and keep them away from Frostsaber Rock.",logDesc="Rivern Frostwind wants you to slay 5 Winterfall Shaman and 5 Winterfall Ursa."} end
if not DB[5202] then DB[5202]={id=5202,zoneId=361,name="A Strange Red Key",level=55,minLevel=49,ender="Captured Arko'narin",enderType="NPC",enderId=11016,wowhead="https://www.wowhead.com/wotlk/quest=5202",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The small red key seems to be made of some kind of bone material. It is heavy in your hand, but appears very fragile. Why would a member of the Shadow Council have such a thing? Perhaps there is something within Jaedenar that this strange key unlocks.",logDesc="Search through Jaedenar to discover what the Blood Red Key is used for."} end
if not DB[5203] then DB[5203]={id=5203,zoneId=361,name="Rescue From Jaedenar",level=55,minLevel=49,giver="Captured Arko'narin",giverType="NPC",giverId=11016,ender="Jessir Moonbow",enderType="NPC",enderId=11019,rewardNextId=5204,poiX=5007,poiY=-440,wowhead="https://www.wowhead.com/wotlk/quest=5203",image="assets/images/quests/placeholder.png",xpDiff=5,desc="But, as much as it pains me, there is one thing that must be done first: I have to find Trey's sword Lightforge and escape Shadow Hold to tell my superiors what's happening here. Can you help me, $N?$B$BOur equipment isn't far from here, and you've already proven you can survive the path to the top.$B$BAfter we escape, I'll head to Darnassus if you can find my friend Jessir near the Ashenvale border. She was to meet us at the Emerald Circle's camp near there.$B$BWhat do you say, $N? Can you help me again?",logDesc="Escort Arko'narin to where Lightforge and her equipment are being held, and then protect her as you escape Shadow Hold. Afterwards, seek out Jessir Moonbow in Felwood to let her know what's happened to her friends."} end
if not DB[5204] then DB[5204]={id=5204,zoneId=361,name="Retribution of the Light",level=57,minLevel=49,giver="Jessir Moonbow",giverType="NPC",giverId=11019,ender="Remains of Trey Lightforge",enderType="NPC",enderId=11020,rewardNextId=5385,poiX=3990,poiY=-1311,wowhead="https://www.wowhead.com/wotlk/quest=5204",image="assets/images/quests/placeholder.png",xpDiff=4,desc="She would like to pretend that she's fine. She'd love for me to think that she's strong enough to deal with all of this on her own, but I know better than that. Trey's death and hearing the torture he was put through is going to haunt her for a long time, and there's nothing we can do to stop that. But we can give her some peace!$B$B$N, return to Shadow Hold, kill Trey's torturer and find his remains. There is no reason we can't tie off all these loose ends while Arko'narin mourns in her own private way.",logDesc="Return to Jaedenar and kill the succubus Rakaiah before finding the Remains of Trey Lightforge.",rewards={{id=13562,qty=1}}} end
if not DB[5205] then DB[5205]={id=5205,zoneId=0,name="<UNUSED>",level=49,minLevel=49,wowhead="https://www.wowhead.com/wotlk/quest=5205",image="assets/images/quests/placeholder.png"} end
if not DB[5206] then DB[5206]={id=5206,zoneId=139,name="Marauders of Darrowshire",level=60,minLevel=50,giver="Carlin Redpath",giverType="NPC",giverId=11063,ender="Carlin Redpath",enderType="NPC",enderId=11063,rewardNextId=5941,poiX=2257,poiY=-5341,wowhead="https://www.wowhead.com/wotlk/quest=5206",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Chromie said the relics you gathered are reagents to a powerful spell, and one more is required: skulls from the scourge who took part in the battle of Darrowshire.$B$BTake this crystal and hunt scourge champions for their skulls.  The crystal is enchanted; if a champion took part in the battle, then when you pass the crystal over its skull it will resonate.  Bring me those resonating skulls.$B$BGo, $N.  You'll find scourge champions in the Noxious Glade to the north and the Fungal Vale to the west.",logDesc="Bring 5 Resonating Skulls and the Mystic Crystal to Carlin Redpath in Eastern Plaguelands."} end
if not DB[5207] then DB[5207]={id=5207,zoneId=361,name="<NYI> <TXT> The True Summoner",level=49,minLevel=49,wowhead="https://www.wowhead.com/wotlk/quest=5207",image="assets/images/quests/placeholder.png"} end
if not DB[5208] then DB[5208]={id=5208,zoneId=361,name="<NYI> <TXT> The Blessing of Evil",level=49,minLevel=49,wowhead="https://www.wowhead.com/wotlk/quest=5208",image="assets/images/quests/placeholder.png"} end
if not DB[5209] then DB[5209]={id=5209,zoneId=361,name="<UNUSED>",level=49,minLevel=49,wowhead="https://www.wowhead.com/wotlk/quest=5209",image="assets/images/quests/placeholder.png"} end
if not DB[5210] then DB[5210]={id=5210,zoneId=139,name="Brother Carlin",level=56,minLevel=50,giver="Chromie",giverType="NPC",giverId=10667,ender="Carlin Redpath",enderType="NPC",enderId=11063,rewardNextId=5181,poiX=1453,poiY=-1280,wowhead="https://www.wowhead.com/wotlk/quest=5210",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The Annals of Darrowshire, through my magic, has gained pages at its end, and now it extends its history beyond the battle.  One of the extra passages tells of another Redpath, Carlin, who survived Joseph's betrayal.  Carlin's now in the Plaguelands to the east, at the Light's Hope Chapel.$B$BTake the book and speak with him.",logDesc="Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands."} end
if not DB[5211] then DB[5211]={id=5211,zoneId=139,name="Defenders of Darrowshire",level=55,minLevel=50,giver="Carlin Redpath",giverType="NPC",giverId=11063,ender="Carlin Redpath",enderType="NPC",enderId=11063,poiX=2257,poiY=-5341,wowhead="https://www.wowhead.com/wotlk/quest=5211",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Many of the defenders fell at the battle of Darrowshire.  And many roam again as the ghastly servants of the Scourge!  Find these poor souls and end their misery!$B$BHunt cannibal ghouls, gibbering ghouls and diseased flayers.  Many of these fiends were once the good folk of Darrowshire and destroying their forms now will set their souls free.$B$BYou will find them in Plaguewood and Corin's Crossing, and in other Scourge strongholds of Eastern Plaguelands.",logDesc="Free 15 Darrowshire Spirits and return to Carlin Redpath."} end
if not DB[5212] then DB[5212]={id=5212,zoneId=2017,name="The Flesh Does Not Lie",level=60,minLevel=55,giver="Betina Bigglezink",giverType="NPC",giverId=11035,ender="Betina Bigglezink",enderType="NPC",enderId=11035,rewardNextId=5213,poiX=2260,poiY=-5339,wowhead="https://www.wowhead.com/wotlk/quest=5212",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="The Forsaken apothecaries are not the only beings in this world schooled in the sciences.$B$BI have been studying the plague for years, $r. We had previously thought that the potency of the plague was dwindling, but what I have discovered here in the Plaguelands is startling. The plague seems to be growing in strength!$B$BI need to run more tests! The most potent source of the plague is from the tainted flesh of the most recently infected. Travel to Stratholme and bring me samples, $N.$B",logDesc="Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample."} end
if not DB[5213] then DB[5213]={id=5213,zoneId=2017,name="The Active Agent",level=60,minLevel=55,giver="Betina Bigglezink",giverType="NPC",giverId=11035,ender="Betina Bigglezink",enderType="NPC",enderId=11035,poiX=2260,poiY=-5339,wowhead="https://www.wowhead.com/wotlk/quest=5213",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You will have to delve deeper into Stratholme, $N.$B$BBeyond the first gates you will find the ziggurats. We know that the Scourge draws great power from these structures. Search the Ziggurats and return with any information that you may discover.$B",logDesc="Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.$B",choiceRewards={{id=13209,qty=1},{id=19812,qty=1}}} end
if not DB[5214] then DB[5214]={id=5214,zoneId=2017,name="The Great Fras Siabi",level=60,minLevel=55,giver="Smokey LaRue",giverType="NPC",giverId=11033,ender="Smokey LaRue",enderType="NPC",enderId=11033,poiX=2303,poiY=-5306,wowhead="https://www.wowhead.com/wotlk/quest=5214",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Terrible thing... what happened to Fras. You see, the town was sacked and Fras didn't want to leave his precious goods behind. The last thing I remember him saying was, 'I'll burn every last leaf before they get their damned, dirty hands on them!'$B$BI may love a good stogie but I'm no fool. I left Fras and his delightful store that day. I assume he went down in flames but if there's a chance that even one box of his famous tobacco is still intact...$B$BWhat do you say, $N? Find a box for ol' Smokey?",logDesc="Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done.$B",rewards={{id=13171,qty=1}}} end
if not DB[5215] then DB[5215]={id=5215,zoneId=28,name="The Scourge Cauldrons",level=53,minLevel=50,giver="Commander Ashlam Valorfist",giverType="NPC",giverId=10838,ender="High Priestess MacDonnell",enderType="NPC",enderId=11053,rewardNextId=5216,poiX=958,poiY=-1419,wowhead="https://www.wowhead.com/wotlk/quest=5215",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Within the lands of former Lordaeron are eight cauldrons - four here in the west, and four more ensconced in the east.  These cauldrons spew poisons into the air, propagating the plague throughout the land for the Scourge.$B$BThe necromantic might of Kel'Thuzad is too strong to outright shut down these cauldrons, but we think we might have a way to subvert them to our advantage.  My second, High Priestess MacDonnell, will be your point on this assignment; she'll continue the briefing from here.",logDesc="Speak with High Priestess MacDonnell at Chillwind Point, Western Plaguelands."} end
if not DB[5216] then DB[5216]={id=5216,zoneId=28,name="Target: Felstone Field",level=53,minLevel=50,giver="High Priestess MacDonnell",giverType="NPC",giverId=11053,rewardNextId=5217,poiX=944,poiY=-1431,wowhead="https://www.wowhead.com/wotlk/quest=5216",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Of the four cauldrons here in the west, the one located at Felstone Field may be the easiest one in obtaining access to.  The Scourge have greener troops positioned here, though they should not be underestimated.$B$BGo to Felstone Field, northwest of Andorhal, and engage the cauldron lord there.  We think it has a key that will unlock access to the cauldron.  When unlocked, use this bottle to obtain a sample of the poisons inside the cauldron; we'll need it for study in developing a counter agent.",logDesc="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there.  It may have a key that will allow access to the cauldron.  You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron."} end
if not DB[5217] then DB[5217]={id=5217,zoneId=28,name="Return to Chillwind Camp",level=53,minLevel=50,ender="High Priestess MacDonnell",enderType="NPC",enderId=11053,rewardNextId=5219,wowhead="https://www.wowhead.com/wotlk/quest=5217",image="assets/images/quests/placeholder.png",xpDiff=3,money=8000,desc="You fill the bottle with enough of the cauldron's poisonous concoction for a suitable sample to be studied.$B$BWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.",logDesc="Bring the Filled Felstone Field Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."} end
if not DB[5218] then DB[5218]={id=5218,zoneId=28,name="Felstone Field Cauldron",level=53,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=5218",image="assets/images/quests/placeholder.png"} end
if not DB[5219] then DB[5219]={id=5219,zoneId=28,name="Target: Dalson's Tears",level=55,minLevel=50,giver="High Priestess MacDonnell",giverType="NPC",giverId=11053,rewardNextId=5220,poiX=944,poiY=-1431,wowhead="https://www.wowhead.com/wotlk/quest=5219",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One of the plague cauldrons is located in the field of a former farmhouse now referred to as Dalson's Tears.  Well, we shall shed no tears this day as we thwart the Scourge and have them choke on their own fumes!$B$BGo to Dalson's Tears, almost due north of Andorhal, and eliminate the cauldron lord there.  It should have a key like the last one did, allowing you into the cauldron.  Use this bottle to obtain a sample from inside the cauldron; each cauldron has its own distinct brew of toxins it uses.",logDesc="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron."} end
if not DB[5220] then DB[5220]={id=5220,zoneId=28,name="Return to Chillwind Camp",level=55,minLevel=50,ender="High Priestess MacDonnell",enderType="NPC",enderId=11053,rewardNextId=5222,wowhead="https://www.wowhead.com/wotlk/quest=5220",image="assets/images/quests/placeholder.png",xpDiff=3,money=8500,desc="You carefully fill the bottle with enough of the cauldron's ichors for what you consider to be suitably sized sample.$B$BWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.",logDesc="Bring the Filled Dalson's Tears Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."} end
if not DB[5221] then DB[5221]={id=5221,zoneId=28,name="Dalson's Tears Cauldron",level=55,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=5221",image="assets/images/quests/placeholder.png"} end
if not DB[5222] then DB[5222]={id=5222,zoneId=28,name="Target: Writhing Haunt",level=55,minLevel=50,giver="High Priestess MacDonnell",giverType="NPC",giverId=11053,rewardNextId=5223,poiX=944,poiY=-1431,wowhead="https://www.wowhead.com/wotlk/quest=5222",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Two cauldrons have been successfully opened; while you will be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent!$B$BThis time, you'll be hitting the Writhing Haunt's cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron.$B$BGood hunting, $N!",logDesc="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron."} end
if not DB[5223] then DB[5223]={id=5223,zoneId=28,name="Return to Chillwind Camp",level=55,minLevel=50,ender="High Priestess MacDonnell",enderType="NPC",enderId=11053,rewardNextId=5225,wowhead="https://www.wowhead.com/wotlk/quest=5223",image="assets/images/quests/placeholder.png",xpDiff=3,money=8500,desc="You delicately top off the empty bottle; a sample of the foul substance that churns under the platform of the cauldron now oozes back and forth inside the fragile glass container.$B$BWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.",logDesc="Bring the Filled Writhing Haunt Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."} end
if not DB[5224] then DB[5224]={id=5224,zoneId=28,name="Writhing Haunt Cauldron",level=55,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=5224",image="assets/images/quests/placeholder.png"} end
if not DB[5225] then DB[5225]={id=5225,zoneId=28,name="Target: Gahrron's Withering",level=58,minLevel=50,giver="High Priestess MacDonnell",giverType="NPC",giverId=11053,rewardNextId=5226,poiX=944,poiY=-1431,wowhead="https://www.wowhead.com/wotlk/quest=5225",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The last cauldron that remains is located on a farm now called Gahrron's Withering.  It is guarded by some of the Scourge's tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, $N.$B$BGahrron's Withering is due northeast of our position here, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the Light protect you in this dangerous mission, $c.",logDesc="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron."} end
if not DB[5226] then DB[5226]={id=5226,zoneId=28,name="Return to Chillwind Camp",level=58,minLevel=50,ender="High Priestess MacDonnell",enderType="NPC",enderId=11053,wowhead="https://www.wowhead.com/wotlk/quest=5226",image="assets/images/quests/placeholder.png",xpDiff=3,money=9000,desc="You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle.$B$BWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.",logDesc="Bring the Filled Gahrron's Withering Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."} end
if not DB[5227] then DB[5227]={id=5227,zoneId=28,name="Gahrron's Withering Cauldron",level=58,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=5227",image="assets/images/quests/placeholder.png"} end
if not DB[5228] then DB[5228]={id=5228,zoneId=28,name="The Scourge Cauldrons",level=53,minLevel=50,giver="High Executor Derrington",giverType="NPC",giverId=10837,ender="Shadow Priestess Vandis",enderType="NPC",enderId=11055,rewardNextId=5229,poiX=1761,poiY=-723,wowhead="https://www.wowhead.com/wotlk/quest=5228",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Within the lands of former Lordaeron are eight cauldrons - four in the west, and four more entrenched in the east.  These cauldrons spew poisons into the air, propagating the plague throughout the land for the Scourge.$B$BThe necromantic might of Kel'Thuzad is too strong to outright shut down these cauldrons, but we think we might have a way to subvert them to our advantage.  My second, Shadow Priestess Vandis, will be your point on this assignment; she'll continue the briefing from here.",logDesc="Speak with Shadow Priestess Vandis at the Bulwark, Western Plaguelands."} end
if not DB[5229] then DB[5229]={id=5229,zoneId=28,name="Target: Felstone Field",level=53,minLevel=50,giver="Shadow Priestess Vandis",giverType="NPC",giverId=11055,rewardNextId=5230,poiX=1671,poiY=-719,wowhead="https://www.wowhead.com/wotlk/quest=5229",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Of the four cauldrons in the Western Plaguelands, the one at Felstone Field may be the easiest one to gain access to.  The Scourge have greener troops positioned here, though they should not be underestimated.$B$BGo to Felstone Field, due east of here and northwest of Andorhal, and engage the cauldron lord there.  On it is a key that will unlock access to the cauldron.  When unlocked, use this bottle to get a sample of the cauldron's toxins; we'll need it for study in developing a counter agent.",logDesc="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there.  It may have a key that will allow access to the cauldron.  You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron."} end
if not DB[5230] then DB[5230]={id=5230,zoneId=28,name="Return to the Bulwark",level=53,minLevel=50,ender="Shadow Priestess Vandis",enderType="NPC",enderId=11055,rewardNextId=5231,wowhead="https://www.wowhead.com/wotlk/quest=5230",image="assets/images/quests/placeholder.png",xpDiff=3,money=8000,desc="You fill the bottle with enough of the cauldron's poisonous concoction for a suitable sample to be studied.$B$BWith the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.",logDesc="Bring the Filled Felstone Field Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."} end
if not DB[5231] then DB[5231]={id=5231,zoneId=28,name="Target: Dalson's Tears",level=55,minLevel=50,giver="Shadow Priestess Vandis",giverType="NPC",giverId=11055,rewardNextId=5232,poiX=1671,poiY=-719,wowhead="https://www.wowhead.com/wotlk/quest=5231",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One of the plague cauldrons is located in the field of a former farmhouse now referred to as Dalson's Tears.  No tears will be shed this day, $c; we must strike at this cauldron and gain access to it!$B$BGo to Dalson's Tears, almost due north of Andorhal, and eliminate the cauldron lord there.  It should have a key like the last one did, allowing you inside the cauldron's innards.  Use this bottle to obtain a sample from inside the cauldron; each cauldron has its own distinct brew of toxins it uses.",logDesc="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron."} end
if not DB[5232] then DB[5232]={id=5232,zoneId=28,name="Return to the Bulwark",level=55,minLevel=50,ender="Shadow Priestess Vandis",enderType="NPC",enderId=11055,rewardNextId=5233,wowhead="https://www.wowhead.com/wotlk/quest=5232",image="assets/images/quests/placeholder.png",xpDiff=3,money=8500,desc="You carefully fill the bottle with enough of the cauldron's ichors for what you consider to be suitably sized sample.$B$BWith the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.",logDesc="Bring the Filled Dalson's Tears Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."} end
if not DB[5233] then DB[5233]={id=5233,zoneId=28,name="Target: Writhing Haunt",level=55,minLevel=50,giver="Shadow Priestess Vandis",giverType="NPC",giverId=11055,rewardNextId=5234,poiX=1671,poiY=-719,wowhead="https://www.wowhead.com/wotlk/quest=5233",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Two cauldrons have been successfully opened; while you'll be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent!$B$BThis time, you'll be hitting the Writhing Haunt's cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron.$B$BGood hunting, $N!",logDesc="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron."} end
if not DB[5234] then DB[5234]={id=5234,zoneId=28,name="Return to the Bulwark",level=55,minLevel=50,ender="Shadow Priestess Vandis",enderType="NPC",enderId=11055,rewardNextId=5235,wowhead="https://www.wowhead.com/wotlk/quest=5234",image="assets/images/quests/placeholder.png",xpDiff=3,money=8500,desc="You delicately top off the empty bottle; a sample of the foul substance that churns under the platform of the cauldron now oozes back and forth inside the fragile glass container.$B$BWith the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.",logDesc="Bring the Filled Writhing Haunt Bottle to Shadow Priestess Vandis at The Bulwark, Western Plaguelands."} end
if not DB[5235] then DB[5235]={id=5235,zoneId=28,name="Target: Gahrron's Withering",level=58,minLevel=50,giver="Shadow Priestess Vandis",giverType="NPC",giverId=11055,rewardNextId=5236,poiX=1671,poiY=-719,wowhead="https://www.wowhead.com/wotlk/quest=5235",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The last cauldron that remains is located on a farm now called Gahrron's Withering.  It is guarded by some of the Scourge's tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, $N.$B$BGahrron's Withering is far to the east of the Bulwark, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the shadows cloak you in safety for this dangerous mission, $c.",logDesc="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron."} end
if not DB[5236] then DB[5236]={id=5236,zoneId=28,name="Return to the Bulwark",level=58,minLevel=50,ender="Shadow Priestess Vandis",enderType="NPC",enderId=11055,wowhead="https://www.wowhead.com/wotlk/quest=5236",image="assets/images/quests/placeholder.png",xpDiff=3,money=9000,desc="You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle.$B$BWith the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.",logDesc="Bring the Filled Gahrron's Withering Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."} end
if not DB[5237] then DB[5237]={id=5237,zoneId=28,name="Mission Accomplished!",level=58,minLevel=50,giver="Commander Ashlam Valorfist",giverType="NPC",giverId=10838,ender="Commander Ashlam Valorfist",enderType="NPC",enderId=10838,poiX=958,poiY=-1419,wowhead="https://www.wowhead.com/wotlk/quest=5237",image="assets/images/quests/placeholder.png",xpDiff=7,rewards={{id=15799,qty=1}},choiceRewards={{id=15801,qty=1},{id=15800,qty=1}}} end
if not DB[5238] then DB[5238]={id=5238,zoneId=28,name="Mission Accomplished!",level=58,minLevel=50,giver="High Executor Derrington",giverType="NPC",giverId=10837,ender="High Executor Derrington",enderType="NPC",enderId=10837,poiX=1761,poiY=-723,wowhead="https://www.wowhead.com/wotlk/quest=5238",image="assets/images/quests/placeholder.png",xpDiff=7,rewards={{id=15799,qty=1}},choiceRewards={{id=15801,qty=1},{id=15800,qty=1}}} end
if not DB[5241] then DB[5241]={id=5241,zoneId=139,name="Uncle Carlin",level=56,minLevel=50,giver="Pamela Redpath",giverType="NPC",giverId=10926,ender="Carlin Redpath",enderType="NPC",enderId=11063,rewardNextId=5211,poiX=1456,poiY=-3596,wowhead="https://www.wowhead.com/wotlk/quest=5241",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Sometimes, when it's nighttime, I can hear my Uncle Carlin crying.  It sounds like he's far away, to the east.$B$BI hope he's not crying for me!  $N, will you find my uncle and tell him I'm alright?$B$BIf you find him say I'm waiting for him, and I want to hear the story he used to tell... the one about the rabbits and the berry jam!  That story's so funny!",logDesc="Find Carlin Redpath."} end
if not DB[5242] then DB[5242]={id=5242,zoneId=361,name="A Final Blow",level=58,minLevel=48,giver="Greta Mosshoof",giverType="NPC",giverId=10922,ender="Greta Mosshoof",enderType="NPC",enderId=10922,poiX=3986,poiY=-1303,wowhead="https://www.wowhead.com/wotlk/quest=5242",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside. The straight path down to the bottom is the only way... and I also know who you should seek out. His name is Fel'dan... Shadow Lord Fel'dan. He is the mortal in power down below... he is the head of the serpent. Kill him and his two succubus servants and return to me. Fel'dan is the one making pacts with the Legion. He must be stopped.",logDesc="Kill Moora and Salia, and bring Shadow Lord Fel'dan's Head to Greta Mosshoof in Felwood.",choiceRewards={{id=15707,qty=1},{id=15708,qty=1},{id=15709,qty=1}}} end
if not DB[5243] then DB[5243]={id=5243,zoneId=2017,name="Houses of the Holy",level=60,minLevel=55,giver="Leonid Barthalomew the Revered",giverType="NPC",giverId=11036,ender="Leonid Barthalomew the Revered",enderType="NPC",enderId=11036,poiX=2307,poiY=-5349,wowhead="https://www.wowhead.com/wotlk/quest=5243",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="I look at my undeath as a malady, $r. An illness that merely requires treatment; however, it is also a great blessing for the Argent Dawn. What better vessel to smite the heathens of the Scourge than through the undead?$B$BI am revered by my colleagues because of the sacrifices I have made, but the accolades mean nothing to me.$B$BIf you are interested in assisting the Argent Dawn, then a job I can offer.$B$BVenture to Stratholme and recover our surplus of holy water. Search the supply crates.$B",logDesc="Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.",rewards={{id=3928,qty=5},{id=6149,qty=5}},choiceRewards={{id=13216,qty=1},{id=13217,qty=1}}} end
if not DB[5244] then DB[5244]={id=5244,zoneId=618,name="The Ruins of Kel'Theril",level=56,minLevel=53,giver="Wynd Nightchaser",giverType="NPC",giverId=11079,ender="Jaron Stoneshaper",enderType="NPC",enderId=10301,rewardNextId=5245,poiX=7095,poiY=-4007,wowhead="https://www.wowhead.com/wotlk/quest=5244",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The story behind Kel'Theril is one of a cursed race, bound to the place where they attempted an unfortunate ritual...$B$BThe highborne that you will find there once stole a sacred artifact, believing that they could siphon its power for themselves, becoming even more powerful. In their efforts, the relic shattered in a huge explosion, driving the pieces below the ice of the lake...$B$BSpeak with Jaron Stoneshaper if you'd like to learn more; he has recently visited the area and can tell you more.",logDesc="Speak with Jaron Stoneshaper in Starfall Village."} end
if not DB[5245] then DB[5245]={id=5245,zoneId=618,name="Troubled Spirits of Kel'Theril",level=56,minLevel=53,giver="Jaron Stoneshaper",giverType="NPC",giverId=10301,ender="Aurora Skycaller",enderType="NPC",enderId=10304,rewardNextId=5246,poiX=7093,poiY=-4019,wowhead="https://www.wowhead.com/wotlk/quest=5245",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The highborne spirits are miserable creatures, that's for sure. They are still searching for pieces of the very thing that has cursed them to Kel'Theril forever -- the stolen relic.$B$BIf you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice.$B$BNow, I can't tell you a thing about what you find, but I do know of someone who might... Aurora Skycaller; she dwells near the Northpass Tower in the northern part of Eastern Plaguelands.",logDesc="Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands."} end
if not DB[5246] then DB[5246]={id=5246,zoneId=139,name="Fragments of the Past",level=56,minLevel=53,giver="Aurora Skycaller",giverType="NPC",giverId=10304,ender="Aurora Skycaller",enderType="NPC",enderId=10304,rewardNextId=5247,poiX=3232,poiY=-4256,wowhead="https://www.wowhead.com/wotlk/quest=5246",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I did not realize... Forgive my callous words, $c.$B$BThe mistakes of my ancestors are not what I wish to dwell on, but if your request is truly genuine, then I will help you.$B$B<Aurora examines the fragments.>$B$BI believe this is the Crystal of Zin-Malor, an artifact that can contain and control strong arcane forces. It could have been used for good, but the evil intentions of those that stole it caused it to shatter.$B$BGo to the Temple of Zin-Malor in Azshara - I can only hope the book is still there.",logDesc="Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."} end
if not DB[5247] then DB[5247]={id=5247,zoneId=139,name="Fragments of the Past",level=57,minLevel=53,giver="Aurora Skycaller",giverType="NPC",giverId=10304,ender="Aurora Skycaller",enderType="NPC",enderId=10304,poiX=3232,poiY=-4256,wowhead="https://www.wowhead.com/wotlk/quest=5247",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I will be able to help you, if recreating the artifact is truly what you wish to do.$B$BTo seal the pieces back together, I will need items with strong magical qualities. An enchanted thorium bar and five crystal restore... You'll also need to collect some water from what might seem an unlikely place... Find the dire pool along Eldreth Row at Dire Maul in Feralas, and fill this vial.$B$BWhile you are gone, I will attempt to glean from these pages the knowledge I need to repair the damage done to the relic.",logDesc="Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."} end
if not DB[5248] then DB[5248]={id=5248,zoneId=139,name="Tormented By the Past",level=58,minLevel=53,giver="Aurora Skycaller",giverType="NPC",giverId=10304,ender="Remorseful Highborne",enderType="NPC",enderId=10684,rewardNextId=5252,poiX=3232,poiY=-4256,wowhead="https://www.wowhead.com/wotlk/quest=5248",image="assets/images/quests/placeholder.png",xpDiff=4,desc="$N, I weep for what has happened in the past. Like this crystal, the elves, as a race, have been shattered. I do not know if the pieces will ever again be reunited into one, but my sorrow has been eased by being able to help you with this one small task. $B$BWe must not forget the past, $N...$B$BPlease take the Crystal of Zin-Malor back to Lake Kel'Theril. You must find a highborne spirit that realizes the error of what was done so long ago. Show the spirit that we have made things right again.",logDesc="Take the Crystal of Zin-Malor to Lake Kel'Theril in Winterspring and find a highborne spirit that will speak to you."} end
if not DB[5249] then DB[5249]={id=5249,zoneId=361,name="To Winterspring!",level=56,minLevel=53,giver="Ivy Leafrunner",giverType="NPC",giverId=10924,ender="Wynd Nightchaser",enderType="NPC",enderId=11079,rewardNextId=5244,poiX=4006,poiY=-1288,wowhead="https://www.wowhead.com/wotlk/quest=5249",image="assets/images/quests/placeholder.png",xpDiff=1,desc="In Winterspring, to the north of here, there are many ancient elven ruins. It's a harsh land, but it holds many secrets and places to explore.$B$BWith all my work to do here in Felwood, I have not had the opportunity to travel to Winterspring. But there's no reason why you shouldn't!$B$BWhile you're there, look for Wynd Nightchaser. He spends most of his time in Starfall Village and he knows a lot about the area.",logDesc="Find Starfall Village in Winterspring and speak with Wynd Nightchaser."} end
if not DB[5250] then DB[5250]={id=5250,zoneId=702,name="Starfall",level=56,minLevel=53,giver="Daryn Lightwind",giverType="NPC",giverId=7907,ender="Wynd Nightchaser",enderType="NPC",enderId=11079,rewardNextId=5244,poiX=8701,poiY=993,wowhead="https://www.wowhead.com/wotlk/quest=5250",image="assets/images/quests/placeholder.png",xpDiff=1,desc="In Winterspring, to the north of Felwood, there are many ancient elven ruins. It's a harsh land, but it holds many secrets and places to explore.$B$BMy studies here keep me so busy that I have not had the opportunity to travel to Winterspring for some time. But there's no reason why you shouldn't travel there and study the ruins.$B$BWhile you're there, look for Wynd Nightchaser. He spends most of his time in Starfall and he knows a lot about the area.$B$BTell him that you are a student of mine...",logDesc="Find Starfall in Winterspring and speak with Wynd Nightchaser."} end
if not DB[5251] then DB[5251]={id=5251,zoneId=2017,name="The Archivist",level=60,minLevel=55,giver="Duke Nicholas Zverenhoff",giverType="NPC",giverId=11039,ender="Duke Nicholas Zverenhoff",enderType="NPC",enderId=11039,poiX=2256,poiY=-5338,wowhead="https://www.wowhead.com/wotlk/quest=5251",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="Anything taken to an extreme is hazardous to our world, $N. Take for example, the Scarlet Crusade. Do you believe that their blind zealotry serves a greater good? How many innocents have they destroyed in the name of the Light?$B$BBlasphemers, one and all!$B$BOne in particular interests me, though; the Archivist Galford of Stratholme: A man that watches over the Crusade's most valued documents. Destroy him and burn down his archives! Should you succeed, return to me and be rewarded.",logDesc="Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive."} end
if not DB[5252] then DB[5252]={id=5252,zoneId=618,name="Remorseful Highborne",level=58,minLevel=53,giver="Remorseful Highborne",giverType="NPC",giverId=10684,ender="Wynd Nightchaser",enderType="NPC",enderId=11079,rewardNextId=5253,poiX=6434,poiY=-4302,wowhead="https://www.wowhead.com/wotlk/quest=5252",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The... the crystal...$B$BThe highborne here are clouded by their own misssery...$B$BI am sorrrrrowful, but I realize the errorrrr of what happened so long ago. Even though there is no waaaay to change the past, I am now at peacccce knowing that you have recovered the crystal of Zin-Malor...$B$BYouuu must return it...$B$BIt muuuussst be returrrned.",logDesc="Speak with Wynd Nightchaser in Starfall Village, and ask about the proper place for the Crystal of Zin-Malor."} end
if not DB[5253] then DB[5253]={id=5253,zoneId=618,name="The Crystal of Zin-Malor",level=58,minLevel=53,giver="Wynd Nightchaser",giverType="NPC",giverId=11079,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,poiX=7095,poiY=-4007,wowhead="https://www.wowhead.com/wotlk/quest=5253",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Quite impressive, $N.$B$BThe crystal of Zin-Malor can never be returned to the temple which, as you know, lies in ruin. But I believe that your effort to undo the evil of the past should not go unrewarded.$B$BSeek out Arch Druid Fandral Staghelm in Darnassus, and bring the crystal to him, $N. It should be in the hands of those that will not abuse its power. From the looks of it, only a handful of the strongest magic users would be able to control such a power. ",logDesc="Deliver the Crystal of Zin-Malor to Arch Druid Fandral Staghelm in Darnassus.",choiceRewards={{id=15791,qty=1},{id=15792,qty=1},{id=15795,qty=1}}} end
if not DB[5261] then DB[5261]={id=5261,zoneId=9,name="Eagan Peltskinner",level=2,minLevel=1,giver="Deputy Willem",giverType="NPC",giverId=823,ender="Eagan Peltskinner",enderType="NPC",enderId=196,rewardNextId=33,poiX=-8948,poiY=-132,wowhead="https://www.wowhead.com/wotlk/quest=5261",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Eagan Peltskinner is looking for someone to hunt diseased wolves for him.  That's good news, because we're seeing a lot more diseased wolves in Northshire Valley lately.$B$BIf you're interested then speak with Eagan.  He's around the side of the abbey, to the left.",logDesc="Speak with Eagan Peltskinner."} end
if not DB[5262] then DB[5262]={id=5262,zoneId=2017,name="The Truth Comes Crashing Down",level=60,minLevel=55,ender="Duke Nicholas Zverenhoff",enderType="NPC",enderId=11039,rewardNextId=5263,wowhead="https://www.wowhead.com/wotlk/quest=5262",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You try and gather your thoughts as the dust settles across the chamber. You go over the events that just transpired and still cannot comprehend the gravity of the situation.$B$BThe Grand Crusader of the Scarlet Crusade a demon? And not just any demon but brother to Varimathras, arch lord of the Undercity?$B$BYou carefully stow the severed head of the dreadlord into your pack. Surely, none would believe the tale you would tell without proof.$B$BDuke Nicholas Zverenhoff must be told at once!",logDesc="Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands."} end
if not DB[5263] then DB[5263]={id=5263,zoneId=2017,name="Above and Beyond",level=60,minLevel=55,giver="Duke Nicholas Zverenhoff",giverType="NPC",giverId=11039,ender="Duke Nicholas Zverenhoff",enderType="NPC",enderId=11039,poiX=2256,poiY=-5338,wowhead="https://www.wowhead.com/wotlk/quest=5263",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You display a natural aptitude for destruction and you follow orders. It is rare to see the two coexist. I am beginning to think that you may make an excellent vehicle of divine justice.$B$B<Zverenhoff clasps his hands together in front of his face.>$B$BKel'Thuzad's errand boy rules over Stratholme. Prove to me that you are a champion - my champion. Destroy Baron Rivendare and return to me with his head. $B",logDesc="Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.$B"} end
if not DB[5264] then DB[5264]={id=5264,zoneId=139,name="Lord Maxwell Tyrosus",level=60,minLevel=55,giver="Duke Nicholas Zverenhoff",giverType="NPC",giverId=11039,ender="Lord Maxwell Tyrosus",enderType="NPC",enderId=11034,rewardNextId=5265,poiX=2256,poiY=-5338,wowhead="https://www.wowhead.com/wotlk/quest=5264",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I am about to bestow a great honor upon you, $N.$B$BLord Maxwell wishes to reward you for your service to the Argent Dawn!$B$BIt has been years since Maxwell has granted audience to outsiders.$B",logDesc="Speak with Lord Maxwell Tyrosus. He is inside the church."} end
if not DB[5265] then DB[5265]={id=5265,zoneId=139,name="The Argent Hold",level=60,minLevel=55,giver="Lord Maxwell Tyrosus",giverType="NPC",giverId=11034,poiX=2304,poiY=-5349,wowhead="https://www.wowhead.com/wotlk/quest=5265",image="assets/images/quests/placeholder.png",xpDiff=7,money=27000,desc="Through the years the Argent Hold has remained locked. None have been worthy to reach inside and take from it the power of the Argent Dawn - until today.$B$BThe Argent Hold is now open to you, $N.",logDesc="Open the Argent Hold and claim your reward.",choiceRewards={{id=13246,qty=1},{id=13243,qty=1},{id=13249,qty=1}}} end
if not DB[5281] then DB[5281]={id=5281,zoneId=139,name="The Restless Souls",level=60,minLevel=55,giver="Caretaker Alen",giverType="NPC",giverId=11038,ender="Egan",enderType="NPC",enderId=11140,rewardNextId=5282,poiX=2152,poiY=-5265,wowhead="https://www.wowhead.com/wotlk/quest=5281",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There are those that died tragically in the fall of Stratholme. Many took their own lives, opting to hurl themselves into the myriad flames of the smoldering city rather than become one of the Scourge.$B$BThey now walk the streets of Stratholme as restless spirits.$B$BWe must aid them, $N!$B$BI have an associate named Egan who has been doing miraculous work with ghosts and souls. Seek him out. He walks the eastern Plaguelands, near Stratholme, testing his innovations.",logDesc="Find Egan. You only know that he was last seen around Stratholme."} end
if not DB[5282] then DB[5282]={id=5282,zoneId=2017,name="The Restless Souls",level=60,minLevel=55,giver="Egan",giverType="NPC",giverId=11140,ender="Egan",enderType="NPC",enderId=11140,poiX=2929,poiY=-2745,wowhead="https://www.wowhead.com/wotlk/quest=5282",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done. I am, however, no zealot. There are those, like the Scarlet Crusade, who would sooner destroy the innocent undead than lend them even an ounce of compassion.$B$BWhich brings me to this: My blaster. It will unchain the tortured souls from Stratholme.$B$BUse it on the ghosts that haunt the ransacked streets. Free their souls.",logDesc="Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!$B$BFree 15 Restless Souls and return to Egan.",rewards={{id=13315,qty=1}}} end
if not DB[5283] then DB[5283]={id=5283,zoneId=-121,name="The Art of the Armorsmith",level=40,minLevel=40,giver="Grumnus Steelshaper",giverType="NPC",giverId=5164,ender="Grumnus Steelshaper",enderType="NPC",enderId=5164,poiX=-4795,poiY=-1109,wowhead="https://www.wowhead.com/wotlk/quest=5283",image="assets/images/quests/placeholder.png",xpDiff=5,desc="So ye made the smart decision.$B$BThere ain't no love lost betwixt me an old Ironus here. That good for nothing toy maker knows who the true craftsmen round here be.$B$BThe truly great wars are won with a good defense. When it be go time, no offense is gonna be helping ye out.$B$BRight, so let's get to work. All ye need to do is show me that ye've got some raw talent. After that, I'll yank whatever impurities be left in ye and mold ye into an armorsmith. Ye do know how to make ornate mithril, don't ye?",logDesc="To become an Armorsmith, you must make the following items and return them to Grumnus: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate."} end
if not DB[5284] then DB[5284]={id=5284,zoneId=-121,name="The Way of the Weaponsmith",level=40,minLevel=40,giver="Ironus Coldsteel",giverType="NPC",giverId=11146,ender="Ironus Coldsteel",enderType="NPC",enderId=11146,poiX=-4799,poiY=-1111,wowhead="https://www.wowhead.com/wotlk/quest=5284",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As a weaponsmith you'll find that more often than not, heroes and adventurers will be coming to you for gear. While the workload can be unbearable at times, the riches more than make up for the back strain and ash lung.$B$BOh yes, $N, weaponsmiths are the ones with all the gold!$B$BIf you wish to join our ranks, you'll need to show me that you can make me a silver or two - I mean, show me that you've got what it takes to be the go to $g guy:girl; when people need superior quality weapons. Get to work!",logDesc="To become a Weaponsmith, you must make the following items and return them to Ironus: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces.$B"} end
if not DB[5301] then DB[5301]={id=5301,zoneId=-121,name="The Art of the Armorsmith",level=40,minLevel=40,giver="Okothos Ironrager",giverType="NPC",giverId=11177,ender="Okothos Ironrager",enderType="NPC",enderId=11177,poiX=2049,poiY=-4800,wowhead="https://www.wowhead.com/wotlk/quest=5301",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Satisfaction. It is what I draw from the hammer and the anvil. To see a proud Horde warrior protected under my steel reminds me of what it is to be alive. It is an addiction that I dare never give up, $N.$B$BI can not grant you this satisfaction, merely set you upon the path. As with all of life's endeavors, the path of the armorsmith is a journey.$B$BIf you wish to be one of the select few, you need only to ask and I shall train, but, a task you must first complete.",logDesc="To become an armorsmith, you must make the following items and return them to Okothos: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate."} end
if not DB[5302] then DB[5302]={id=5302,zoneId=-121,name="The Way of the Weaponsmith",level=40,minLevel=40,giver="Borgosh Corebender",giverType="NPC",giverId=11178,ender="Borgosh Corebender",enderType="NPC",enderId=11178,poiX=2052,poiY=-4794,wowhead="https://www.wowhead.com/wotlk/quest=5302",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One day, I will create a legendary hammer. A hammer fit for a Warchief!$B$BIt is my life's work, $N. My passion. I recognize that you have the potential to be among us, one of us - a weaponsmith. I am the one that can help you harness that potential.$B$BA simple task is all that you must complete. Simple for one of your exceptional skill. ",logDesc="To become a Weaponsmith, you must make the following items and return them to Borgosh: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces.$B"} end
if not DB[5303] then DB[5303]={id=5303,zoneId=139,name="<UNUSED>",level=58,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=5303",image="assets/images/quests/placeholder.png"} end
if not DB[5304] then DB[5304]={id=5304,zoneId=139,name="<UNUSED>",level=58,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=5304",image="assets/images/quests/placeholder.png"} end
if not DB[5305] then DB[5305]={id=5305,zoneId=-121,name="Sweet Serenity",level=60,minLevel=50,giver="Lilith the Lithe",giverType="NPC",giverId=11191,ender="Lilith the Lithe",enderType="NPC",enderId=11191,poiX=6776,poiY=-4671,wowhead="https://www.wowhead.com/wotlk/quest=5305",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Within the confines of the Scarlet Bastion lies sweet Serenity. The Crimson Hammersmith guards the recipe with his life. Defeat him and bring me his apron. For that, I shall reward you with the knowledge required to create an enchanted battlehammer!",logDesc="Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith.$B",rewards={{id=12824,qty=1}}} end
if not DB[5306] then DB[5306]={id=5306,zoneId=-121,name="Snakestone of the Shadow Huntress",level=60,minLevel=50,giver="Kilram",giverType="NPC",giverId=11192,ender="Kilram",enderType="NPC",enderId=11192,poiX=6779,poiY=-4669,wowhead="https://www.wowhead.com/wotlk/quest=5306",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Don't let her beauty fool you, $c. The shadow huntress, Vosh'gajin is deadly and deranged.$B$B<Kilram points to the scar on his face.>$B$BAye, she gave me that - a love tap, she called it.$B$BThe time for vengeance has finally come.$B$BYou can find Vosh'gajin in Blackrock Spire. Slay her and return to me with her snakestone. Do this and I will teach you the secret to crafting Dawn's Edge!",logDesc="Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.",rewards={{id=12821,qty=1}}} end
if not DB[5307] then DB[5307]={id=5307,zoneId=-121,name="Corruption",level=60,minLevel=50,giver="Seril Scourgebane",giverType="NPC",giverId=11193,ender="Seril Scourgebane",enderType="NPC",enderId=11193,poiX=6773,poiY=-4671,wowhead="https://www.wowhead.com/wotlk/quest=5307",image="assets/images/quests/placeholder.png",xpDiff=7,desc="If I am short with you, it is for a reason. The plans for the creation of the great blade, Corruption, have been stolen by the Black Guard: Elite skeletal units of Baron Rivendare.$B$BYes, Baron Rivendare of Stratholme.$B$BThe Black Guard swordsmith now guards those plans with his... undeath.$B$BSlay him and return proof of this deed and I shall grant you the knowledge required to create a blazing rapier!",logDesc="Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane.",rewards={{id=12825,qty=1}}} end
if not DB[5321] then DB[5321]={id=5321,zoneId=148,name="The Sleeper Has Awakened",level=20,minLevel=17,giver="Kerlonian Evershade",giverType="NPC",giverId=11218,ender="Liladris Moonriver",enderType="NPC",enderId=11219,poiX=4996,poiY=34,wowhead="https://www.wowhead.com/wotlk/quest=5321",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I was on my way to Maestra's Post to meet Liladris Moonriver, but I decided to stop here and take a short nap. Ever since I awoke from the emerald dream, I have been so sleepy...$B$B<yawn>$B$BWould you mind showing me the way? I understand that Maestra's Post is south of here, along the road in Ashenvale. It can be dangerous, so I hope you have some friends that will join us.$B$BLastly, I may fall asleep so if you ever need to wake me, please use my horn. You'll find it in the chest here.",logDesc="Escort Kerlonian Evershade to Liladris Moonriver at Maestra's Post in Ashenvale.",choiceRewards={{id=15205,qty=1},{id=15206,qty=1},{id=15207,qty=1}}} end
if not DB[5341] then DB[5341]={id=5341,zoneId=2057,name="Barov Family Fortune",level=60,minLevel=52,giver="Alexi Barov",giverType="NPC",giverId=11022,ender="Alexi Barov",enderType="NPC",enderId=11022,rewardNextId=5342,poiX=1681,poiY=-720,wowhead="https://www.wowhead.com/wotlk/quest=5341",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="Within the Scholomance lays the Barov family fortune. I, Alexi Barov, am one of the last two remaining heirs of the house Barov. My brother, Weldon, is the other.$B$BWeldon, the miserable coward, fled during the war and thus retained his worthless existence as a human.$B$BHe now searches for the deeds so that he may claim the fortune for his own. Recover the deeds before my brother does and I shall make you wealthy beyond your wildest dreams!",logDesc="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task."} end
if not DB[5342] then DB[5342]={id=5342,zoneId=28,name="The Last Barov",level=60,minLevel=52,giver="Alexi Barov",giverType="NPC",giverId=11022,ender="Alexi Barov",enderType="NPC",enderId=11022,poiX=1681,poiY=-720,wowhead="https://www.wowhead.com/wotlk/quest=5342",image="assets/images/quests/placeholder.png",xpDiff=6,money=18000,desc="Naturally, with my brother still alive, there may be some contention as to the primary beneficiary of the family's fortune. This cannot be.$B$BA low down guttersnipe like you isn't above a little cold-blooded murder, I hope.$B$BIt's a simple task and one that I expect you will complete; that is, if you wish to claim your reward.$B$BWeldon sits under Alliance protection at Chillwind Camp, to the east. Slay him, return his head.$B$B<Alexi yawns.>$B$BHurry along now.",logDesc="Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.$B$BBe warned, Weldon will probably be well protected by Alliance scum.",rewards={{id=14022,qty=1}}} end
if not DB[5343] then DB[5343]={id=5343,zoneId=2057,name="Barov Family Fortune",level=60,minLevel=52,giver="Weldon Barov",giverType="NPC",giverId=11023,ender="Weldon Barov",enderType="NPC",enderId=11023,rewardNextId=5344,poiX=966,poiY=-1452,wowhead="https://www.wowhead.com/wotlk/quest=5343",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="My dear brother Alexi. What a fool I was to spare his life. I looked into the face of the enemy, one of the undead, and let him live.$B$B<Weldon spits.>$B$BHe now searches for MY inheritance. This simply cannot happen.$B$BFind my family's deeds before that vile retch gets his boney hands upon them and I shall reward you with vast riches. They lay in the ruins of the Scholomance. Make haste!",logDesc="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task."} end
if not DB[5344] then DB[5344]={id=5344,zoneId=28,name="The Last Barov",level=60,minLevel=52,giver="Weldon Barov",giverType="NPC",giverId=11023,ender="Weldon Barov",enderType="NPC",enderId=11023,poiX=966,poiY=-1452,wowhead="https://www.wowhead.com/wotlk/quest=5344",image="assets/images/quests/placeholder.png",xpDiff=6,money=18000,desc="With the deeds recovered, there is but one thing left to do. Alexi must be killed. With him dead, I need not ever worry about an unscrupulous gang of mercenaries seeking my head.$B$BIt's a simple task. Alexi hides under the protection of the Horde - at the Bulwark.$B$BNo, I do not expect you to just walk up and kill him, I want his head! How you get it... well, that part is up to you. That type of behavior is below one of my noble upbringing.",logDesc="Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.$B$BBe warned, Alexi will probably be well protected by Horde filth.",rewards={{id=14023,qty=1}}} end
if not DB[5361] then DB[5361]={id=5361,zoneId=400,name="Family Tree",level=35,minLevel=32,giver="Cliffwatcher Longhorn",giverType="NPC",giverId=10537,ender="Nataka Longhorn",enderType="NPC",enderId=11259,poiX=-5455,poiY=-2443,wowhead="https://www.wowhead.com/wotlk/quest=5361",image="assets/images/quests/placeholder.png",xpDiff=4,money=2500,desc="My brother Nataka is stationed at Ghost Walker Post over in Desolace. I'd like to ask you... could you give this report to him for me? A year has passed since the last time I wrote, there has been unusual centaur activity since then and he should be informed.$B$BJourney to Stonetalon Mountain north of the Crossroads, and then head west into Charred Vale. From there, head south into Desolace; there you will find a road going south to Ghost Walker Post.",logDesc="Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace."} end
if not DB[5381] then DB[5381]={id=5381,zoneId=405,name="Hand of Iruxos",level=38,minLevel=32,giver="Taiga Wisemane",giverType="NPC",giverId=11624,ender="Taiga Wisemane",enderType="NPC",enderId=11624,rewardNextId=5581,poiX=-1593,poiY=3073,wowhead="https://www.wowhead.com/wotlk/quest=5381",image="assets/images/quests/placeholder.png",xpDiff=5,money=4500,desc="The Burning Blade possesses the Demon Box. Within it lies the powerful Hand of Iruxos. The Burning Blade uses it to open demonic portals at Mannoroc Coven. We must stop the tide of demons entering our world, $n!$B$BUse this demon pick on the red crystal in Thunder Axe Fortress to gain access to the Demon Box.$B",logDesc="Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village.$B"} end
if not DB[5382] then DB[5382]={id=5382,zoneId=2057,name="Doctor Theolen Krastinov, the Butcher",level=60,minLevel=55,giver="Eva Sarkhoff",giverType="NPC",giverId=11216,ender="Eva Sarkhoff",enderType="NPC",enderId=11216,rewardNextId=5515,poiX=1254,poiY=-2603,wowhead="https://www.wowhead.com/wotlk/quest=5382",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Krastinov is responsible for the deaths of thousands. He must be punished, justice must be meted out.$B$BFind him and exact upon him the agony he has inflicted upon countless innocents. Once he is destroyed, burn our remains. Turn them to ashes, $N.",logDesc="Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.$B"} end
if not DB[5383] then DB[5383]={id=5383,zoneId=2057,name="Krastinov's Bag of Horrors",level=60,minLevel=55,rewardNextId=5384,wowhead="https://www.wowhead.com/wotlk/quest=5383",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You open the bag to discover various instruments of torture. Amidst the paraphernalia, an odd object catches your eye: A vial of blood - still warm to the touch.$B$BYou think that the Sarkhoff's might be interested in your discovery.",logDesc="Take the Bag of Horrors to Eva Sarkhoff on Caer Darrow."} end
if not DB[5384] then DB[5384]={id=5384,zoneId=2057,name="Kirtonos the Herald",level=60,minLevel=55,giver="Eva Sarkhoff",giverType="NPC",giverId=11216,ender="Eva Sarkhoff",enderType="NPC",enderId=11216,poiX=1254,poiY=-2603,wowhead="https://www.wowhead.com/wotlk/quest=5384",image="assets/images/quests/placeholder.png",xpDiff=7,desc="This is it, $N.$B$B<Eva points to the vial inside the bag.>$B$BThe blood of innocents. The purest blood, used to appease Krastinov's master.$B$BIt is with this blood that Kirtonos may be summoned. It is with this blood, then, that Kirtonos must be destroyed.$B$BTake the blood to the porch. Place it upon the brazier. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.$B$BShould you succeed, you will earn more than just our gratitude.",logDesc="Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.$B$BFight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.$B",rewards={{id=13544,qty=1}},choiceRewards={{id=15805,qty=1},{id=15806,qty=1}}} end
if not DB[5385] then DB[5385]={id=5385,zoneId=361,name="The Remains of Trey Lightforge",level=57,minLevel=49,giver="Remains of Trey Lightforge",giverType="NPC",giverId=11020,ender="Jessir Moonbow",enderType="NPC",enderId=11019,poiX=5201,poiY=-572,wowhead="https://www.wowhead.com/wotlk/quest=5385",image="assets/images/quests/placeholder.png",xpDiff=6,money=2200,desc="You pick up the sack carefully and prepare to make your way back to Jessir Moonbow on the border of Felwood and Ashenvale. Hopefully the paladin will be given the proper respects once you've passed his remains on to his friends.",logDesc="Return the Remains of Trey Lightforge to Jessir Moonbow in Felwood.",choiceRewards={{id=15706,qty=1},{id=15705,qty=1}}} end
if not DB[5386] then DB[5386]={id=5386,zoneId=405,name="Catch of the Day",level=37,minLevel=32,giver="Nataka Longhorn",giverType="NPC",giverId=11259,ender="Nataka Longhorn",enderType="NPC",enderId=11259,poiX=-1221,poiY=1742,wowhead="https://www.wowhead.com/wotlk/quest=5386",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The smell of cooked fish has long been missing here at Ghost Walker Post. The trolls at Shadowprey Village are the best at catching fish... but alas, with all the centaur activities I have little time to make a journey to the trolls. Hrm...$B$BDo me a favor and journey to Shadowprey Village. Talk to the local fisherman Jinar'Zillen and bring me back my favorite, Bloodbelly fish. The road south of here will take you west to the troll village.",logDesc="Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish.",choiceRewards={{id=3858,qty=3},{id=4304,qty=5},{id=4338,qty=5}}} end
