if not DB[5421] then DB[5421]={id=5421,zoneId=405,name="Fish in a Bucket",level=25,minLevel=25,giver="Jinar'Zillen",giverType="NPC",giverId=11317,ender="Jinar'Zillen",enderType="NPC",enderId=11317,poiX=-1740,poiY=3224,wowhead="https://www.wowhead.com/wotlk/quest=5421",image="assets/images/quests/placeholder.png",rewards={{id=13546,qty=1}}} end
if not DB[5441] then DB[5441]={id=5441,zoneId=363,name="Lazy Peons",level=4,minLevel=3,giver="Foreman Thazz'ril",giverType="NPC",giverId=11378,ender="Foreman Thazz'ril",enderType="NPC",enderId=11378,rewardNextId=6394,poiX=-612,poiY=-4322,wowhead="https://www.wowhead.com/wotlk/quest=5441",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Cursed peons!  They work hard gathering lumber from the trees of the valley, but they're always taking naps!  I need someone to help keep the peons in line.$B$BYou look like the right $r for my task.  Here, you take this blackjack and use it on any lazy peons you find sleeping on the job.  A good smack will get them right back to work!  Return the blackjack when you're done.$B$BLousy slacking peons...",logDesc="Use the Foreman's Blackjack on Lazy Peons when they're sleeping.  Wake up 5 peons, then return the Foreman's Blackjack to Foreman Thazz'ril in the Valley of Trials."} end
if not DB[5461] then DB[5461]={id=5461,zoneId=28,name="The Human, Ras Frostwhisper",level=60,minLevel=57,giver="Magistrate Marduke",giverType="NPC",giverId=11286,ender="Magistrate Marduke",enderType="NPC",enderId=11286,rewardNextId=5462,poiX=1242,poiY=-2618,wowhead="https://www.wowhead.com/wotlk/quest=5461",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The undead fear life just as the living fear death. It is not unusual for a sentient undead being to completely destroy all remnants of his or her previous life after having turned.$B$BUnfortunately, in order to create an artifact capable of reverting Ras Frostwhisper to a mortal, we must have a keepsake from his years among the living.$B$BYou must venture to the ruined city of Stromgarde, Frostwhisper's home, and search for such an item. May luck be with you, $N.",logDesc="Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke."} end
if not DB[5462] then DB[5462]={id=5462,zoneId=28,name="The Dying, Ras Frostwhisper",level=60,minLevel=57,giver="Magistrate Marduke",giverType="NPC",giverId=11286,ender="Leonid Barthalomew the Revered",enderType="NPC",enderId=11036,rewardNextId=5463,poiX=1242,poiY=-2618,wowhead="https://www.wowhead.com/wotlk/quest=5462",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Upon tainted soil, the keepsake must be attuned.$B$BIt is rumored that Stratholme is where Frostwhisper succumbed to the Lich King. Upon those bloodied grounds he gave his life - freely and with motive - to become one of the undying.$B$BIt is those grounds that must be found.$B$BThere is one, an undead dissenter of the Scourge, freed by the Banshee Queen but loyal to the cause of the Argent Dawn. Find him: Leonid Barthalomew the Revered. He may know more. Seek out Light's Hope, $N. ",logDesc="Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered."} end
if not DB[5463] then DB[5463]={id=5463,zoneId=2017,name="Menethil's Gift",level=60,minLevel=57,giver="Leonid Barthalomew the Revered",giverType="NPC",giverId=11036,rewardNextId=5464,poiX=2307,poiY=-5349,wowhead="https://www.wowhead.com/wotlk/quest=5463",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I watched as the human, Ras Frostwhisper, pledged his undying soul to the Lich King. He drew the dagger to his own throat and with a smile, cut from ear to ear. His body collapsed inside the borders of the pentagram. The Lich King stood over the fallen mage and with a single motion, Ras Frostwhisper the lich, was born.$B$B<Leonid gazes at the ground and then looks up at you.>$B$BYes, $r, I remember. What you seek has a name - Menethil's Gift: The ground blessed by the Lich King - holy ground to Scourge.$B",logDesc="Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground. "} end
if not DB[5464] then DB[5464]={id=5464,zoneId=139,name="Menethil's Gift",level=60,minLevel=57,ender="Leonid Barthalomew the Revered",enderType="NPC",enderId=11036,rewardNextId=5465,wowhead="https://www.wowhead.com/wotlk/quest=5464",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The soul of the fallen clings to that which represents its former life and transforms the item into a soulbound keepsake. You pick the item up and place it in your pack.",logDesc="Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands."} end
if not DB[5465] then DB[5465]={id=5465,zoneId=28,name="Soulbound Keepsake",level=60,minLevel=57,giver="Leonid Barthalomew the Revered",giverType="NPC",giverId=11036,ender="Magistrate Marduke",enderType="NPC",enderId=11286,rewardNextId=5466,poiX=2307,poiY=-5349,wowhead="https://www.wowhead.com/wotlk/quest=5465",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Return to Marduke with the keepsake, $N. He will instruct you in its use.",logDesc="Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake."} end
if not DB[5466] then DB[5466]={id=5466,zoneId=2057,name="The Lich, Ras Frostwhisper",level=60,minLevel=57,giver="Magistrate Marduke",giverType="NPC",giverId=11286,ender="Magistrate Marduke",enderType="NPC",enderId=11286,poiX=1242,poiY=-2618,wowhead="https://www.wowhead.com/wotlk/quest=5466",image="assets/images/quests/placeholder.png",xpDiff=7,desc="There is but one task remaining, $N. Confront the lich, Ras Frostwhisper, in his lair.$B$BUse the power of the keepsake against the beast -  be unrelenting in your actions!  Weather the blows that the flailing beast will surely bring down upon you. Do not give in to the pain!$B$BWhen the ritual is complete, Ras will be mortal once more. It is at that point that he must be slain. Strike him down and take his human head.",logDesc="Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.",rewards={{id=14002,qty=1}},choiceRewards={{id=13982,qty=1},{id=13986,qty=1},{id=13984,qty=1}}} end
if not DB[5481] then DB[5481]={id=5481,zoneId=85,name="Gordo's Task",level=5,minLevel=5,giver="Gordo",giverType="NPC",giverId=10666,ender="Junior Apothecary Holland",enderType="NPC",enderId=10665,rewardNextId=5482,poiX=2242,poiY=599,wowhead="https://www.wowhead.com/wotlk/quest=5481",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.$b$bWhen you have gloom weed you take to Master Holland in Brill graveyard.$B",logDesc="Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in the Brill graveyard."} end
if not DB[5482] then DB[5482]={id=5482,zoneId=85,name="Doom Weed",level=6,minLevel=5,giver="Junior Apothecary Holland",giverType="NPC",giverId=10665,ender="Junior Apothecary Holland",enderType="NPC",enderId=10665,poiX=2326,poiY=399,wowhead="https://www.wowhead.com/wotlk/quest=5482",image="assets/images/quests/placeholder.png",xpDiff=5,money=125,desc="So you can see the predicament that I'm in, $N. That thing is out there collecting the wrong weeds! I'll make it worth your while to gather what I need. Bring back to me enough doom weed and I'll give you a suitable reward.$B$BIt is my understanding that they like to plague the flora near the mass gravesite, to the north of the Brill graveyard. Hurry and be mindful of the gnolls in the area.",logDesc="Collect 10 Doom Weed and deliver them back to Junior Apothecary Holland.$B"} end
if not DB[5501] then DB[5501]={id=5501,zoneId=405,name="Bone Collector",level=32,minLevel=29,giver="Bibbly F'utzbuckle",giverType="NPC",giverId=11438,ender="Bibbly F'utzbuckle",enderType="NPC",enderId=11438,poiX=-717,poiY=1431,wowhead="https://www.wowhead.com/wotlk/quest=5501",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We're sitting on a goldmine here, I tell you - a goldmine!  Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them.$B$BThere's a caravan that comes by and picks up my kodo bones and then sells them at Shadowprey Village.  If you can travel to the kodo graveyard south of here and bring me ten kodo bones, I'll give you something in return.  Is it a deal?",logDesc="Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut.",rewards={{id=15690,qty=1}}} end
if not DB[5502] then DB[5502]={id=5502,zoneId=-284,name="A Warden of the Horde",level=-1,minLevel=10,ender="Orphan Matron Battlewail",enderType="NPC",enderId=14451,wowhead="https://www.wowhead.com/wotlk/quest=5502",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You have been so very kind to me, $N.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.  I won't be sad about what's happened to me - my parents always told me to rise above anything bad that happens.  I'll be a hero... just like you.$B$BI'm sad to say this, but it's time for me to go home.  Let's go back and I'll tell the matron what an awesome person you are!",logDesc="Return your ward to the Orgrimmar orphanage by handing in the Orcish Orphan Whistle to Orphan Matron Battlewail in the Valley of Honor.",choiceRewards={{id=23007,qty=1},{id=23015,qty=1},{id=23002,qty=1},{id=23022,qty=1}}} end
if not DB[5503] then DB[5503]={id=5503,zoneId=139,name="Argent Dawn Commission",level=55,minLevel=50,giver="Argent Officer Garush",giverType="NPC",giverId=10839,ender="Argent Officer Garush",enderType="NPC",enderId=10839,poiX=1775,poiY=-726,wowhead="https://www.wowhead.com/wotlk/quest=5503",image="assets/images/quests/placeholder.png",rewards={{id=12846,qty=1}}} end
if not DB[5504] then DB[5504]={id=5504,zoneId=28,name="Mantles of the Dawn",level=60,minLevel=55,giver="Argent Quartermaster Hasana",giverType="NPC",giverId=10856,ender="Argent Quartermaster Hasana",enderType="NPC",enderId=10856,poiX=1785,poiY=-729,wowhead="https://www.wowhead.com/wotlk/quest=5504",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Your service to the Argent Dawn is to be commended, $N.  You are truly revered amongst us.  I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles.$B$BApplication of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways.  As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.",logDesc="Bring 10 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands."} end
