if not DB[5513] then DB[5513]={id=5513,zoneId=139,name="Mantles of the Dawn",level=60,minLevel=55,giver="Quartermaster Miranda Breechlock",giverType="NPC",giverId=11536,ender="Quartermaster Miranda Breechlock",enderType="NPC",enderId=11536,poiX=2251,poiY=-5345,wowhead="https://www.wowhead.com/wotlk/quest=5513",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Your service to the Argent Dawn is to be commended, $N.  You are truly revered amongst us.  I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles.$B$BApplication of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways.  As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.",logDesc="Bring 10 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands."} end
if not DB[5514] then DB[5514]={id=5514,zoneId=28,name="Mold Rhymes With...",level=57,minLevel=55,giver="Apothecary Dithers",giverType="NPC",giverId=11057,ender="Krinkle Goodsteel",enderType="NPC",enderId=5411,rewardNextId=5802,poiX=1752,poiY=-730,wowhead="https://www.wowhead.com/wotlk/quest=5514",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.$B$BI'm an apothecary, not a banker.  If I had gold lying around, I certainly wouldn't be here.$B$BI guess I said the quiet part out loud again.  Oops.$B$BGadgetzan awaits you!  Good luck!",logDesc="Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan."} end
if not DB[5515] then DB[5515]={id=5515,zoneId=2057,name="Krastinov's Bag of Horrors",level=60,minLevel=55,giver="Eva Sarkhoff",giverType="NPC",giverId=11216,ender="Eva Sarkhoff",enderType="NPC",enderId=11216,rewardNextId=5384,poiX=1254,poiY=-2603,wowhead="https://www.wowhead.com/wotlk/quest=5515",image="assets/images/quests/placeholder.png",xpDiff=7,desc="A great weight has been lifted from our hearts, $N, but your task is not yet complete. Krastinov's master, Kirtonos, still lives.$B$BBefore you may face Kirtonos, however, you must first secure a method in which to summon him.$B$BIt is said that Jandice Barov stewards the blood of innocents from Krastinov to Kirtonos.$B$BFind her in the sunken catacombs of Scholomance and strike her down. Bring back any clues that you may find.",logDesc="Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff."} end
if not DB[5516] then DB[5516]={id=5516,zoneId=0,name="<UNUSED>",level=58,minLevel=53,wowhead="https://www.wowhead.com/wotlk/quest=5516",image="assets/images/quests/placeholder.png"} end
if not DB[5517] then DB[5517]={id=5517,zoneId=139,name="Chromatic Mantle of the Dawn",level=60,minLevel=55,giver="Quartermaster Miranda Breechlock",giverType="NPC",giverId=11536,ender="Quartermaster Miranda Breechlock",enderType="NPC",enderId=11536,poiX=2251,poiY=-5345,wowhead="https://www.wowhead.com/wotlk/quest=5517",image="assets/images/quests/placeholder.png",xpDiff=6,desc="$G Brother : Sister; $N - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!$B$BBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.",logDesc="Bring 25 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands.",rewards={{id=18182,qty=1}}} end
if not DB[5518] then DB[5518]={id=5518,zoneId=2557,name="The Gordok Ogre Suit",level=60,minLevel=56,giver="Knot Thimblejack",giverType="NPC",giverId=14338,ender="Knot Thimblejack",enderType="NPC",enderId=14338,poiX=581,poiY=523,wowhead="https://www.wowhead.com/wotlk/quest=5518",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If you're going to fight the king of this dump - and I think that's what you're bound to do - then you're going to need to get by Captain Kromcrush.  Now, you can get by him by killing him, sure.  You might actually want to leave him alive.$B$BHow, you ask?  Since I've been here, I think I know how to make an ogre suit that will last just long enough to fool these bozos.  The only problem is stability - ten minutes tops.  Bring me what I need, and I'll make you one.  I'm not going anywhere...",logDesc="Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack.  He is currently chained inside the Gordok wing of Dire Maul.",rewards={{id=18258,qty=1}}} end
if not DB[5519] then DB[5519]={id=5519,zoneId=2557,name="The Gordok Ogre Suit",level=60,minLevel=56,giver="Knot Thimblejack",giverType="NPC",giverId=14338,ender="Knot Thimblejack",enderType="NPC",enderId=14338,poiX=581,poiY=523,wowhead="https://www.wowhead.com/wotlk/quest=5519",image="assets/images/quests/placeholder.png",rewards={{id=18258,qty=1}}} end
