if not DB[5521] then DB[5521]={id=5521,zoneId=28,name="Chromatic Mantle of the Dawn",level=60,minLevel=55,giver="Argent Quartermaster Lightspark",giverType="NPC",giverId=10857,ender="Argent Quartermaster Lightspark",enderType="NPC",enderId=10857,poiX=967,poiY=-1425,wowhead="https://www.wowhead.com/wotlk/quest=5521",image="assets/images/quests/placeholder.png",xpDiff=6,desc="$G Brother : Sister; $N - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!$B$BBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.",logDesc="Bring 25 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands.",rewards={{id=18182,qty=1}}} end
if not DB[5522] then DB[5522]={id=5522,zoneId=46,name="Leonid Barthalomew",level=60,minLevel=57,giver="Tinkee Steamboil",giverType="NPC",giverId=10267,ender="Leonid Barthalomew the Revered",enderType="NPC",enderId=11036,rewardNextId=5531,poiX=-7500,poiY=-2178,wowhead="https://www.wowhead.com/wotlk/quest=5522",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I received a message from my master, Vectus.  Well, the message wasn't really from Vectus...it was from someone named Leonid Barthalomew.  I don't know Leonid, but he knew my master, and no one knows my master unless he allows it.$B$BLeonid says Vectus wants the dragon eggs.  He wants you to deliver them to him at the Light's Hope Chapel in the Eastern Plaguelands.$B$BThat hurts!  Why you?  Doesn't Vectus trust me?  Oh, never mind... just take the eggs and tell Leonid that I did what our master commanded.",logDesc="Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands."} end
if not DB[5523] then DB[5523]={id=5523,zoneId=0,name="<UNUSED>",level=58,minLevel=53,wowhead="https://www.wowhead.com/wotlk/quest=5523",image="assets/images/quests/placeholder.png"} end
if not DB[5524] then DB[5524]={id=5524,zoneId=28,name="Chromatic Mantle of the Dawn",level=60,minLevel=55,giver="Argent Quartermaster Hasana",giverType="NPC",giverId=10856,ender="Argent Quartermaster Hasana",enderType="NPC",enderId=10856,poiX=1785,poiY=-729,wowhead="https://www.wowhead.com/wotlk/quest=5524",image="assets/images/quests/placeholder.png",xpDiff=6,desc="$G Brother : Sister; $N - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!$B$BBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.",logDesc="Bring 25 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands.",rewards={{id=18182,qty=1}}} end
if not DB[5525] then DB[5525]={id=5525,zoneId=2557,name="Free Knot!",level=60,minLevel=56,giver="Knot Thimblejack",giverType="NPC",giverId=14338,ender="Knot Thimblejack",enderType="NPC",enderId=14338,poiX=581,poiY=523,wowhead="https://www.wowhead.com/wotlk/quest=5525",image="assets/images/quests/placeholder.png",xpDiff=5} end
if not DB[5526] then DB[5526]={id=5526,zoneId=493,name="Shards of the Felvine",level=60,minLevel=56,giver="Rabine Saturna",giverType="NPC",giverId=11801,ender="Rabine Saturna",enderType="NPC",enderId=11801,poiX=7797,poiY=-2574,wowhead="https://www.wowhead.com/wotlk/quest=5526",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Your knowledge of Eldre'Thalas - Dire Maul - in Feralas will now come into play, $N.  In the eastern part of the ruined city is where Alzzin the Wildshaper has exerted his corrupt dominion.  Go there with all due haste and brave whatever challenges await you.$B$BThe Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin.  When he falls, capture whatever essence of the Felvine you can.  Seal it in the Reliquary, and bring it to me.$B$BGood luck, and Cenarion's speed.",logDesc="Find the Felvine in Dire Maul and acquire a shard from it.  Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper.  Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.",choiceRewards={{id=18535,qty=1},{id=18536,qty=1}}} end
if not DB[5527] then DB[5527]={id=5527,zoneId=493,name="A Reliquary of Purity",level=60,minLevel=56,giver="Rabine Saturna",giverType="NPC",giverId=11801,ender="Rabine Saturna",enderType="NPC",enderId=11801,rewardNextId=5526,poiX=7797,poiY=-2574,wowhead="https://www.wowhead.com/wotlk/quest=5527",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The first step is to find a container capable of holding an extremely corruptible substance without the handler suffering ill effects.  There is only one sort device I am aware of that could possibly contain something as vile as the Felvine: a Reliquary of Purity.$B$BDeep in the wasteland of Silithus is the remnants of the night elf village known as Southwind.  I know one was there many, many years ago.  If we are to succeed, I need you to scour those ruins in the hopes of reclaiming it.",logDesc="Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village.  If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade."} end
if not DB[5528] then DB[5528]={id=5528,zoneId=2557,name="The Gordok Taste Test",level=60,minLevel=56,giver="3",giverType="NPC",giverId=14322,ender="3",enderType="NPC",enderId=14322,poiX=478,poiY=90,wowhead="https://www.wowhead.com/wotlk/quest=5528",image="assets/images/quests/placeholder.png",rewards={{id=18269,qty=5},{id=18284,qty=5}}} end
if not DB[5529] then DB[5529]={id=5529,zoneId=2057,name="Plagued Hatchlings",level=58,minLevel=55,giver="Betina Bigglezink",giverType="NPC",giverId=11035,ender="Betina Bigglezink",enderType="NPC",enderId=11035,poiX=2260,poiY=-5339,wowhead="https://www.wowhead.com/wotlk/quest=5529",image="assets/images/quests/placeholder.png",xpDiff=7,money=9000,desc="The Argent Dawn recently learned that the Scourge are creating their own plagued dragonflight!  We must stop them -- if the Scourge gain a force of dragons they'll sweep across Azeroth unchecked!$B$BTheir necromancers are breeding plagued dragons at the Scholomance, in the middle of Darrowmere Lake.$B$BGo to the Scholomance and kill as many hatchlings as you can... before they get any bigger!",logDesc="Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel."} end
if not DB[5530] then DB[5530]={id=5530,zoneId=139,name="<NYI> <TXT> Necklace of the Dawn",level=60,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=5530",image="assets/images/quests/placeholder.png",rewards={{id=13811,qty=1}}} end
if not DB[5531] then DB[5531]={id=5531,zoneId=2057,name="Betina Bigglezink",level=60,minLevel=57,giver="Leonid Barthalomew the Revered",giverType="NPC",giverId=11036,ender="Betina Bigglezink",enderType="NPC",enderId=11035,rewardNextId=4771,poiX=2307,poiY=-5349,wowhead="https://www.wowhead.com/wotlk/quest=5531",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The eggs you brought were to be used in Scourge experiments to create a plagued dragonflight.  These frozen black dragon eggs would have been invaluable in their studies, and would have assuredly quickened their timetable.$B$BNow, it is time we ended their research.$B$BTake the frozen eggs to Betina Bigglezink outside.  She is well-learned in science and alchemy, and has produced a weapon we can use against the Scourge.  With your help, we will deal them a heavy blow.",logDesc="Bring the Frozen Eggs to Betina Bigglezink."} end
if not DB[5532] then DB[5532]={id=5532,zoneId=139,name="<NYI> <TXT> Ring of the Dawn",level=58,minLevel=53,wowhead="https://www.wowhead.com/wotlk/quest=5532",image="assets/images/quests/placeholder.png",rewards={{id=13812,qty=1}}} end
if not DB[5533] then DB[5533]={id=5533,zoneId=28,name="Scholomance",level=55,minLevel=55,giver="Commander Ashlam Valorfist",giverType="NPC",giverId=10838,ender="Alchemist Arbington",enderType="NPC",enderId=11056,rewardNextId=5537,poiX=958,poiY=-1419,wowhead="https://www.wowhead.com/wotlk/quest=5533",image="assets/images/quests/placeholder.png",xpDiff=1,desc="On the island of Caer Darrow lies Scholomance - a wretched center of Scourge necromancy and evil.  Our enemy dwells within, conducting unspeakable acts of depravity on unwitting victims... at least, we surmise as much.  A door bars the way, and try as we might no entry is to be had without a proper key.$B$BAlchemist Arbington is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your worth to me, and now I entrust this task to you.  Speak with him on this matter.",logDesc="Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands."} end
if not DB[5534] then DB[5534]={id=5534,zoneId=16,name="Kim'jael's \"Missing\" Equipment",level=53,minLevel=47,giver="Kim'jael",giverType="NPC",giverId=8420,ender="Kim'jael",enderType="NPC",enderId=8420,poiX=4604,poiY=-5988,wowhead="https://www.wowhead.com/wotlk/quest=5534",image="assets/images/quests/placeholder.png",xpDiff=6,money=16000,desc="What?! What?!$B$BThat wasn't good enough for you? You know how expensive those explosives are? They sell for... oh, nevermind. Fine, you want to make some real money? Cause that's how business is done: you prove you're a valuable employee and then you're rewarded adequately after you stick it out some.$B$BIf you're a \"valuable\" employee, then hit the Ruins of Eldarath and find me some rune that them Blood elves were lookin' for. The naga apparently have it in their possession.",logDesc="Find Some Rune that the naga have in their possession in the Ruins of Eldarath and return it to Kim'jael in Azshara."} end
if not DB[5535] then DB[5535]={id=5535,zoneId=16,name="Spiritual Unrest",level=47,minLevel=45,giver="Loh'atu",giverType="NPC",giverId=11548,ender="Loh'atu",enderType="NPC",enderId=11548,poiX=2699,poiY=-3854,wowhead="https://www.wowhead.com/wotlk/quest=5535",image="assets/images/quests/placeholder.png",xpDiff=5,money=5000,desc="Long ago, the Highborne were some of the most powerful students of the arcane the night elves ever produced. The corruption that comes along with such studies caused much harm to night elf society and greatly affected all of Azeroth... as I'm sure you well know.$B$BI promised the Sentinels that I would release the spirits from their mortal bonds as I find them. If you would do the same, then I am sure I can reward you some.$B$BThe spirits haunt the Shadowsong Shrine to the northeast of here.",logDesc="Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara."} end
if not DB[5536] then DB[5536]={id=5536,zoneId=16,name="A Land Filled with Hatred",level=47,minLevel=45,giver="Loh'atu",giverType="NPC",giverId=11548,ender="Loh'atu",enderType="NPC",enderId=11548,poiX=2699,poiY=-3854,wowhead="https://www.wowhead.com/wotlk/quest=5536",image="assets/images/quests/placeholder.png",xpDiff=5,money=7000,desc="The satyr, a disfigured, evil aspect of the night elves, now infect the sacred lands once traveled by Cenarius. I cannot speak for the night elves when it comes to all the atrocities those demonic creatures have committed, but I have sworn an oath to the Earthmother to aid the elves in ridding the land of such a nuisance.$B$BI am sure you would prove yourself if you aided me in purging them.$B$BNortheast of here, you can find the Haldarr clan. Return to me after you've tested yourself against their power.",logDesc="Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale."} end
if not DB[5537] then DB[5537]={id=5537,zoneId=28,name="Skeletal Fragments",level=57,minLevel=55,giver="Alchemist Arbington",giverType="NPC",giverId=11056,ender="Alchemist Arbington",enderType="NPC",enderId=11056,rewardNextId=5538,poiX=965,poiY=-1418,wowhead="https://www.wowhead.com/wotlk/quest=5537",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.$B$BFirst thing's first though, $N.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.",logDesc="Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands."} end
if not DB[5538] then DB[5538]={id=5538,zoneId=28,name="Mold Rhymes With...",level=57,minLevel=55,giver="Alchemist Arbington",giverType="NPC",giverId=11056,ender="Krinkle Goodsteel",enderType="NPC",enderId=5411,rewardNextId=5801,poiX=965,poiY=-1418,wowhead="https://www.wowhead.com/wotlk/quest=5538",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.$B$BI'm an alchemist, not a banker.  If I had gold lying around, I certainly wouldn't be here.$B$BI guess I said the quiet part out loud again.  Oops.$B$BGadgetzan awaits you!  Good luck!",logDesc="Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan."} end
if not DB[5541] then DB[5541]={id=5541,zoneId=1,name="Ammo for Rumbleshot",level=6,minLevel=5,giver="Loslor Rudge",giverType="NPC",giverId=1694,ender="Hegnar Rumbleshot",enderType="NPC",enderId=1243,poiX=-5500,poiY=-665,wowhead="https://www.wowhead.com/wotlk/quest=5541",image="assets/images/quests/placeholder.png",xpDiff=5,money=125,desc="Hegnar Rumbleshot sells guns off the road to Anvilmar.  Riflemen and mortar teams spend a lot of time practicing out near his shop, and he's always needing fresh ammunition.$B$BBut... the last crate of ammo I sent him got lost along the way.  My courier said he was camped near the Grizzled Den when wendigo chased him away... and the fool left Rumbleshot's ammo behind!$B$B$N, can you get that ammo and take it to Rumbleshot?  He's been waiting on it and I'm sure he's running low.",logDesc="Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh."} end
if not DB[5542] then DB[5542]={id=5542,zoneId=139,name="Demon Dogs",level=56,minLevel=52,giver="Tirion Fordring",giverType="NPC",giverId=1855,ender="Tirion Fordring",enderType="NPC",enderId=1855,poiX=2672,poiY=-2478,wowhead="https://www.wowhead.com/wotlk/quest=5542",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If you are going to remain here, I ask only that you earn your keep. We have many nuisances that could use some 'discipline.'$B$BYou can start with the Plaguehounds and their runts.$B$BI cannot offer much in return, but you are guaranteed a warm meal and some conversation should you succeed.",logDesc="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete."} end
if not DB[5543] then DB[5543]={id=5543,zoneId=139,name="Blood Tinged Skies",level=56,minLevel=52,giver="Tirion Fordring",giverType="NPC",giverId=1855,ender="Tirion Fordring",enderType="NPC",enderId=1855,poiX=2672,poiY=-2478,wowhead="https://www.wowhead.com/wotlk/quest=5543",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Woe to those that foolishly wander into the Plaguelands. All manner of foulness inhabit these woods - from the fanatical Scarlet Crusade, who will kill any that do not bear the mark of the Crusade, to the murderous Scourge, who only look to bolster their numbers by adding more undead to their ranks.$B$BEven the wildlife have been transformed into rapacious, man eating beasts. I ask that you destroy those that would strike from the skies: The Plaguebats.",logDesc="Slay 30 Plaguebats and return to Tirion Fordring."} end
if not DB[5544] then DB[5544]={id=5544,zoneId=139,name="Carrion Grubbage",level=56,minLevel=52,giver="Tirion Fordring",giverType="NPC",giverId=1855,ender="Tirion Fordring",enderType="NPC",enderId=1855,poiX=2672,poiY=-2478,wowhead="https://www.wowhead.com/wotlk/quest=5544",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My food supplies are running low, $r. I am ashamed to admit that I might not have enough food to share with you.$B$BCould you assist an old man with a simple task? Around here, the only manner of beast unaffected by the ravages of the Plague are the Carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. I will need several hundred pounds to restock for the coming winter!",logDesc="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.$B"} end
if not DB[5545] then DB[5545]={id=5545,zoneId=12,name="A Bundle of Trouble",level=9,minLevel=5,giver="Supervisor Raelen",giverType="NPC",giverId=10616,ender="Supervisor Raelen",enderType="NPC",enderId=10616,poiX=-9470,poiY=-1289,wowhead="https://www.wowhead.com/wotlk/quest=5545",image="assets/images/quests/placeholder.png",xpDiff=5,money=300,desc="I've got a real problem on my hands. I have a deadline looming for an order of lumber, and I'm running out of time. The wolves and bears north of here have chased my workers away from the bundles of wood that they've already chopped.$B$BI've already talked to Deputy Rainer about clearing the animals, but I need someone to go collect the wood for me. If you could collect eight bundles of wood for me I might just make my deadline.",logDesc="Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp."} end
if not DB[5561] then DB[5561]={id=5561,zoneId=405,name="Kodo Roundup",level=34,minLevel=30,giver="Smeed Scrabblescrew",giverType="NPC",giverId=11596,ender="Smeed Scrabblescrew",enderType="NPC",enderId=11596,poiX=-1402,poiY=1497,wowhead="https://www.wowhead.com/wotlk/quest=5561",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Bibbly thinks he is the only goblin in Desolace who knows how to make money.  Well, the only caravan brave enough to travel these parts relies on me.  Ever since I learned how to rejuvenate and control aged and dying kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership.$B$BTake the kombobulator and use it on any ancient, aged, or dying kodos; it will jolt the beast into a tamed kodo and force it to follow you.  Once you have a kodo tamed, bring it back to me.",logDesc="Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.",choiceRewards={{id=15697,qty=1},{id=15698,qty=1}}} end
if not DB[5581] then DB[5581]={id=5581,zoneId=405,name="Portals of the Legion",level=38,minLevel=32,giver="Taiga Wisemane",giverType="NPC",giverId=11624,ender="Taiga Wisemane",enderType="NPC",enderId=11624,poiX=-1593,poiY=3073,wowhead="https://www.wowhead.com/wotlk/quest=5581",image="assets/images/quests/placeholder.png",xpDiff=6,money=4500,desc="Behold - the Hand of Iruxos. A gruesome sight indeed.$B$BYou must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do. The Demon threat is increasing and we must close these portals to stem the tide of demons to this world. Good luck, $N... and be wary of the portal guardians.$B",logDesc="Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village.$B",choiceRewards={{id=16794,qty=1},{id=16873,qty=1}}} end
if not DB[5582] then DB[5582]={id=5582,zoneId=2057,name="Healthy Dragon Scale",level=58,minLevel=55,ender="Betina Bigglezink",enderType="NPC",enderId=11035,wowhead="https://www.wowhead.com/wotlk/quest=5582",image="assets/images/quests/placeholder.png",desc="This is a scale shed from a plagued dragon hatchling.  But unlike the other pocked, oozing scales on the infant beast, this rare scale is healthy and unmarred.$B$BBetina Bigglezink will want a sample of this to study.",logDesc="Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands."} end
if not DB[5601] then DB[5601]={id=5601,zoneId=139,name="Sister Pamela",level=55,minLevel=50,giver="Jessica Redpath",giverType="NPC",giverId=11629,ender="Pamela Redpath",enderType="NPC",enderId=10926,rewardNextId=5149,poiX=6688,poiY=-4668,wowhead="https://www.wowhead.com/wotlk/quest=5601",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I fled Lordaeron during the great war, and was lucky to escape before the Scourge swept through my homeland and turned it into a plagued nightmare!  I was lucky, but my family was not.  I fear they were all killed during the battle of Darrowshire.$B$BDarrowshire is a village in the Eastern Kingdoms, nestled in the southern hills of what is now the Eastern Plaguelands.  Will you go there and search for my family?  I miss them so much, especially my little sister Pamela.$B$BPlease, find her for me!",logDesc="Find Pamela Redpath in Darrowshire."} end
if not DB[5621] then DB[5621]={id=5621,zoneId=-262,name="Garments of the Moon",level=4,minLevel=5,giver="Laurna Morninglight",giverType="NPC",giverId=3600,ender="Laurna Morninglight",enderType="NPC",enderId=3600,poiX=9905,poiY=985,wowhead="https://www.wowhead.com/wotlk/quest=5621",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I need your help, $N. I am needed here to train the other students, but you, you can help one of our injured Sentinels just south of Dolanaar. She was hurt patrolling the town and could use our aid. Her name is Shaya.$B$BWhen you find her, heal her wounds, and then fortify her body with your spells. This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune.",logDesc="Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar.",rewards={{id=16604,qty=1}}} end
if not DB[5622] then DB[5622]={id=5622,zoneId=-262,name="In Favor of Elune",level=4,minLevel=5,giver="Shanda",giverType="NPC",giverId=3595,ender="Laurna Morninglight",enderType="NPC",enderId=3600,rewardNextId=5621,poiX=10459,poiY=802,wowhead="https://www.wowhead.com/wotlk/quest=5622",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, you must travel to Dolanaar when your business here in Shadowglen is done. There, you will find Laurna Morninglight. She will instruct you further in the ways of Elune, and it is with her that you will earn your first garments denoting your station as a $gpriest:priestess; of Elune.$B$BTake care, and may you be protected in your journeys.",logDesc="Speak to Laurna Morninglight in Teldrassil."} end
if not DB[5623] then DB[5623]={id=5623,zoneId=-262,name="In Favor of the Light",level=4,minLevel=5,giver="Priestess Anetta",giverType="NPC",giverId=375,ender="Priestess Josetta",enderType="NPC",enderId=377,rewardNextId=5624,poiX=-8854,poiY=-193,wowhead="https://www.wowhead.com/wotlk/quest=5623",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hello again, young $gpriest:priestess;. The time has come for you to learn more about our religion. After you've completed whatever tasks you have here in Northshire, please seek out Priestess Josetta in Goldshire. She has more to teach you and has heard that you are growing strong in the ways of the Light. She looks forward to tutoring you more.",logDesc="Speak to Priestess Josetta in Elwynn Forest."} end
if not DB[5624] then DB[5624]={id=5624,zoneId=-262,name="Garments of the Light",level=4,minLevel=5,giver="Priestess Josetta",giverType="NPC",giverId=377,ender="Priestess Josetta",enderType="NPC",enderId=377,poiX=-9461,poiY=33,wowhead="https://www.wowhead.com/wotlk/quest=5624",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Normally I put forth a small challenge to followers of the Light to test their skill. I want to see if they are worthy of wearing their first robes--a sign that the church outwardly approves of the $gpriest:priestess; and supports $ghim:her;.$B$BBut this situation is a bit different. One of Goldshire's citizens saw an injured guard near the lake to the east of here. His name is Roberts. Find him, heal him, fortify his body and return here. If you can do that for me, then I will consider your test complete.",logDesc="Find Guard Roberts and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Priestess Josetta in Goldshire.",rewards={{id=16605,qty=1}}} end
if not DB[5625] then DB[5625]={id=5625,zoneId=-262,name="Garments of the Light",level=4,minLevel=5,giver="Maxan Anvol",giverType="NPC",giverId=1226,ender="Maxan Anvol",enderType="NPC",enderId=1226,poiX=-5591,poiY=-530,wowhead="https://www.wowhead.com/wotlk/quest=5625",image="assets/images/quests/placeholder.png",xpDiff=4,desc="It's usually about this time that one of your power is tested to see if they're worthy of wearing robes denoting their place in the church. But to be honest, I got more pressing matters to look into. Citizen of Kharanos' just came in here and told me 'bout a hurt mountaineer just outside town to the south--name's Dolf.$B$BYou heal Dolf and give him Fortitude, and I'll consider you done with proving yourself. How's that sound?",logDesc="Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.",rewards={{id=16605,qty=1}}} end
if not DB[5626] then DB[5626]={id=5626,zoneId=-262,name="In Favor of the Light",level=4,minLevel=5,giver="Branstock Khalder",giverType="NPC",giverId=837,ender="Maxan Anvol",enderType="NPC",enderId=1226,rewardNextId=5625,poiX=-6057,poiY=394,wowhead="https://www.wowhead.com/wotlk/quest=5626",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hey! $N! Got a minute?!$B$BYa been following the Light now for long enough that you find your way to Maxan Anvol in Kharanos. He'll teach ya more about the path yer following, and if you prove worthy, give ya yer first set of robes to denote your station as a $gpriest:priestess;.$B$BNow get goin'! As soon as yer done here, head through the tunnel--he'll be waitin' for ya.",logDesc="Speak to Maxan Anvol in Dun Morogh."} end
if not DB[5627] then DB[5627]={id=5627,zoneId=-262,name="Stars of Elune",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5627",image="assets/images/quests/placeholder.png"} end
if not DB[5628] then DB[5628]={id=5628,zoneId=-262,name="Returning Home",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5628",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Ah, yes, hello, $N? I'm glad you stopped to talk for a moment. You are a far way from home at such a young age--I admire such ambition. I wish when I was younger I could have mustered the courage to travel the world.$B$BThere was a priestess of your order here looking for you not too long ago. She said it was very urgent you returned to the Temple of the Moon in Darnassus and speak to Priestess Alathea--it had something to do with your training. I wouldn't dally too long if you can help it.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5629] then DB[5629]={id=5629,zoneId=-262,name="Returning Home",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5629",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hello again, $N. I know you've been busy aiding our people, but you must take some time for yourself also. Priestess Alathea sent someone here looking for you. It seems that you've caught the attention of our elders and they feel you are prepared for greater things. Head to the Temple of the Moon in Darnassus and look for Alathea there. She will be waiting. Good luck, and may Elune be with you.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5630] then DB[5630]={id=5630,zoneId=-262,name="Returning Home",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5630",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hello there, $gladdy:lassy;. Good to see you travelin' far and wide to distant lands. No offense meant, but a lot o' your kind don't take well to these cold climates usually. Glad to see you're made of tougher stuff.$B$BNot too long ago one of your priestesses was in here lookin' for you--said somethin' about you finding a Priestess Alathea in the Temple of the Moon back in Darnassus. Said it was important and you should head back there soon.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5631] then DB[5631]={id=5631,zoneId=-262,name="Returning Home",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5631",image="assets/images/quests/placeholder.png",xpDiff=2,desc="A priestess recently visited our halls seeking you out, young $r. She said that she was on a mission to find you and that you should return to the Temple of the Moon in Darnassus as soon as possible. When you arrive, seek out a Priestess Alathea--she will tell you more.$B$BThe Light be with you, $N.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5632] then DB[5632]={id=5632,zoneId=-262,name="Returning Home",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5632",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Oh, yes, of course. Hello, $N. A messenger from our order was here not too long ago looking for you. She mentioned something important happening back in Darnassus and that you should return to the Temple of the Moon as soon as you can. When you arrive, speak to Priestess Alathea. I believe it has something to do with your progressing so well in our ways.$B$BAgain, return to Darnassus when you can.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5633] then DB[5633]={id=5633,zoneId=-262,name="Returning Home",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5633",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Greetings, $gladdy:lass;. Good to see you here in our great halls. A blessing be on you and your kind.$B$BWhile you were traveling through our lands, a priestess of your temple came here seeking you. She said that you were to return to the Temple of the Moon as soon as possible. I'm sorry I can't tell you more, but it did sound important. When you get to the temple, speak to a Priestess Alathea.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5634] then DB[5634]={id=5634,zoneId=-262,name="Desperate Prayer",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5634",image="assets/images/quests/placeholder.png"} end
if not DB[5635] then DB[5635]={id=5635,zoneId=-262,name="Desperate Prayer",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5635",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You've caught the attention of our superiors, $N. They've asked you travel to the Cathedral of Light in Stormwind as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Laurena. She will be able to guide you further. Good luck, and may the Light be with you.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5636] then DB[5636]={id=5636,zoneId=-262,name="Desperate Prayer",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5636",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Elune bless you, good $r. I hope your Light finds you and protects you well this day.$B$BOne of your priests was here not long ago looking for you. He mentioned you returning to the Cathedral of Light as soon as possible to speak with High Priestess Laurena. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5637] then DB[5637]={id=5637,zoneId=-262,name="Desperate Prayer",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5637",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Time's come for you to head to Stormwind, $N. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya.$B$BBut don't waste too much time 'round here. I'd head there as soon as you can.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5638] then DB[5638]={id=5638,zoneId=-262,name="Desperate Prayer",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5638",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Just a short time ago, one of your priests was here looking for you, $r. He said that if I were to see you, I should direct you towards the Cathedral of Light. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you.$B$BElune be with you, good $r.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5639] then DB[5639]={id=5639,zoneId=-262,name="Desperate Prayer",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5639",image="assets/images/quests/placeholder.png",desc="You're needed in Stormwind, $N. The High Priestess there, Laurena, says it's time for you to prove you're worthy of the next level of your training. Don't waste too much time finding your way there. You can find her in the Cathedral of Light in the center of the city. Give her my regards, and prove how worthy you are of such a calling. The Light be with you, $N.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5640] then DB[5640]={id=5640,zoneId=-262,name="Desperate Prayer",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5640",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Praise be to Elune, and to your Light, $N.$B$BAbout this time, many of our order learn abilities reflecting their faith in Elune. If knowledge serves me, I believe the same holds true for your order also.$B$BWhen your business in Darnassus is complete, I would seek out one of your High Priestesses for further training.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5641] then DB[5641]={id=5641,zoneId=-262,name="A Lack of Fear",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5641",image="assets/images/quests/placeholder.png"} end
if not DB[5642] then DB[5642]={id=5642,zoneId=-262,name="Shadowguard",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5642",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Something important is up in Orgrimmar, $N.$B$BThe normal messengers that come through here looking for troll priests usually are very casual. This time, they seemed to be in much more a hurry. Don't dally too long in Thunder Bluff. I'd return to the Valley of Spirits as soon as possible.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5643] then DB[5643]={id=5643,zoneId=-262,name="Shadowguard",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5643",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Like many of our own priests, your own tribe puts you through rites of passage. These rites often teach priests special abilities that are vital to their survival. I sense that time is upon you even as we speak. You must return to the Valley of Spirits in Orgrimmar and speak to Ur'kyo. What he teaches you might be very important for the future.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5644] then DB[5644]={id=5644,zoneId=-262,name="Devouring Plague",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5644",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Ah, a wonderful day for you, $N. I can see by the lessons you've learned that the time has come to send you back to Aelthalyste. There are things only she can teach you, and even then, only if you prove worthy.$B$BI will not spoil the surprise for you, but I remember when I was a young priest learning about true power... divine power. Yes, those were the days.$B$BGo back to Aelthalyste in the Undercity, $N. She will be awaiting you in the War Quarter.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5645] then DB[5645]={id=5645,zoneId=-262,name="A Lack of Fear",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5645",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, your High Priest Rohan would have an audience with you in Ironforge. Make haste, my strong friend, your next test quickly approaches. Although I wish I could bear witness to your race's own special rites, my place is here. But may the Light go with you in your travels. Rohan should still be in the Mystic Ward once you reach the city. He will be waiting.",logDesc="Speak to High Priest Rohan in Ironforge."} end
if not DB[5646] then DB[5646]={id=5646,zoneId=-262,name="Devouring Plague",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5646",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Aelthalyste show our people great respect by sending them back to me for more training, and now I do the same for her tribe.$B$BYou return to the Undercity, $N. There, in the War Quarter, she be ready to teach you more 'bout your people and their ways. Go there, and do not wait long.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5647] then DB[5647]={id=5647,zoneId=-262,name="A Lack of Fear",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5647",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Your race is so very strong, $N. We are proud to call you allies. And as each day's sun sets, you and your kin grow closer to not only finding your true origins, but find great confidence that you are on the right path in so many things. That feeling must make you feel so triumphant.$B$BWord came from Ironforge just recently. It asked that you return there and speak to High Priest Rohan in the Mystic Ward. I would not keep him waiting. May Elune guide your travels.",logDesc="Speak to High Priest Rohan in Ironforge."} end
if not DB[5648] then DB[5648]={id=5648,zoneId=-262,name="Garments of Spirituality",level=4,minLevel=5,giver="Tai'jin",giverType="NPC",giverId=3706,ender="Tai'jin",enderType="NPC",enderId=3706,poiX=295,poiY=-4831,wowhead="https://www.wowhead.com/wotlk/quest=5648",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You be ready for your first test, $N. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops. She not doin' too well, an' she benefit much if one of our kind could help her. Find her--her name be Kor'ja--heal her wounds, an' give her the blessin' of our ancestors.$B$BYou do this, an' me thinks that be sufficient proof that you ready to move on in our ways.",logDesc="Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill.",rewards={{id=16606,qty=1}}} end
if not DB[5649] then DB[5649]={id=5649,zoneId=-262,name="In Favor of Spirituality",level=4,minLevel=5,giver="Ken'jai",giverType="NPC",giverId=3707,ender="Tai'jin",enderType="NPC",enderId=3706,rewardNextId=5648,poiX=-617,poiY=-4202,wowhead="https://www.wowhead.com/wotlk/quest=5649",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Aye, mon. Our kind have joined the Horde because they be good for us. They loyal, and they teach us much 'bout tings like honor. But our old ways die hard. The orcs may not approve of all our traditions, but that not mean we can't continue to practice some them in secret.$B$BYou know this, an' that's why I send you to Tai'jin in Razor Hill. She teach you more 'bout our history. She teach you the ways of our tribe. Go to her when you be ready.",logDesc="Speak to Tai'jin in Durotar."} end
if not DB[5650] then DB[5650]={id=5650,zoneId=-262,name="Garments of Darkness",level=4,minLevel=5,giver="Dark Cleric Beryl",giverType="NPC",giverId=2129,ender="Dark Cleric Beryl",enderType="NPC",enderId=2129,poiX=2265,poiY=251,wowhead="https://www.wowhead.com/wotlk/quest=5650",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Our power comes from darkness and shadow, $N, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts. This is wise. But before you can know the dark, you must also know the light. And for this, I have a test for you.$B$BNorth of the cemetery is a wounded Deathguard--Deathguard Kel. He has protected us from gnolls for some time, and needs healing. But, you must also fortify his body before he can return to duty. Do both with your spells, and then return to me.",logDesc="Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill.",rewards={{id=16607,qty=1}}} end
if not DB[5651] then DB[5651]={id=5651,zoneId=-262,name="In Favor of Darkness",level=4,minLevel=5,giver="Dark Cleric Duesten",giverType="NPC",giverId=2123,ender="Dark Cleric Beryl",enderType="NPC",enderId=2129,rewardNextId=5650,poiX=1848,poiY=1628,wowhead="https://www.wowhead.com/wotlk/quest=5651",image="assets/images/quests/placeholder.png",xpDiff=2,desc="There are many lessons that the Forsaken have learned through experience--things that some races can only begin to fathom. And although our path lies in darkness, you will find that a great many things rely on both the light and the dark. Your lessons shall teach you to use both... and with discretion. But heed my words: never forget we were forged in corruption and left to rot like so much carrion. The Darkness is our home.$B$BSeek out Dark Cleric Beryl in Brill when you're ready to learn more.",logDesc="Speak to Dark Cleric Beryl in Tirisfal Glades."} end
if not DB[5652] then DB[5652]={id=5652,zoneId=-262,name="Hex of Weakness",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5652",image="assets/images/quests/placeholder.png"} end
if not DB[5653] then DB[5653]={id=5653,zoneId=-262,name="<NYI> Hex of Weakness",level=-1,minLevel=10,rewardNextId=5652,wowhead="https://www.wowhead.com/wotlk/quest=5653",image="assets/images/quests/placeholder.png",xpDiff=2,desc="One of your priests sent word to us that if we see you that we were to tell you to return to Orgrimmar, $N. It seems one of your kind--a priest named Ur'kyo, if I'm not mistaken--believes you are ready for more training. It has to do with some of your cultures practices he said, and he wanted you to find this Ur'kyo in the Valley of Spirits.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5654] then DB[5654]={id=5654,zoneId=-262,name="Hex of Weakness",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5654",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It be time for you to meet with Ur'kyo, $N. He be in the Valley of Spirits in the orc city. Go there and speak to him. It is time you learn more of the old ways of our kind. It time you be brought into the circle and made a true priest of our tribe.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5655] then DB[5655]={id=5655,zoneId=-262,name="Hex of Weakness",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5655",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I sent here to make sure that you not wander too far from home, $N. They send me to make sure you return home because Ur'kyo, greatest of our priests, wish to speak to you. You go there. You go to the Valley of Spirits in the orc city and you speak to Ur'kyo. He wait for you now.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5656] then DB[5656]={id=5656,zoneId=-262,name="Hex of Weakness",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5656",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It always warms my undying heart to see priests from all cultures wander the world. To know that power exists that is not arcane and well within our grasp. That's why it is my honor to direct you home, $N.$B$BUr'kyo, your great priest in Orgrimmar, has asked for your presence. You can find him in the Valley of Spirits.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5657] then DB[5657]={id=5657,zoneId=-262,name="Hex of Weakness",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5657",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Home. Return home, young $r.$B$BYour spiritual leader Ur'kyo begs you to return to him and speak about the path you travel.$B$BGo to the Valley of Spirits in the great Horde city of Orgrimmar. You will find him there.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5658] then DB[5658]={id=5658,zoneId=-262,name="Touch of Weakness",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5658",image="assets/images/quests/placeholder.png"} end
if not DB[5659] then DB[5659]={id=5659,zoneId=-262,name="<NYI> Touch of Weakness",level=-1,minLevel=10,rewardNextId=5658,wowhead="https://www.wowhead.com/wotlk/quest=5659",image="assets/images/quests/placeholder.png",xpDiff=2,desc="This isn't the place for you, $N. You should head to the War Quarter in Undercity as soon as possible. Aelthalyste has called all her priests and priestesses there as soon as they are ready. It's time they learn more about their power and how to harness it.$B$BShe will not tolerate tardiness or excuses, so you'd best be on your way.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5660] then DB[5660]={id=5660,zoneId=-262,name="Touch of Weakness",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5660",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You be far from home, $c. You be needed there, back in your city under the ground. Your mistress, the one you be callin' Aelthalyste be needin' you back there. Like my tribe, there things you must learn only from her. Don't be stayin' here too long. You should be headin' to the War Quarter as fast as a zeppelin can carry you.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5661] then DB[5661]={id=5661,zoneId=-262,name="Touch of Weakness",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5661",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You be far from home out here in the Bloodhoof Village, $N. I be sent here to find priests of my own tribe to send back to speak to our leaders, but that not mean I cannot help you too.$B$BI hear word that your head priestess spirit want all Forsaken to come to her--there are things you must learn.$B$BGo to meet Aelthalyste in the War Quarter in that city of yours.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5662] then DB[5662]={id=5662,zoneId=-262,name="Touch of Weakness",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5662",image="assets/images/quests/placeholder.png",xpDiff=2,desc="My respect to you and your kind, $N. I normally teach only those of my own tribe. Your lessons come from Aelthalyste in the city once called Lordaeron.$B$BYou should return to her if you're to learn those abilities that set you apart from other faiths.$B$BGo to the War Quarter in the Undercity and find your mistress there.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5663] then DB[5663]={id=5663,zoneId=-262,name="Touch of Weakness",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=5663",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Aelthalyste sent word out to all her priests. We're to direct the younger of our order to the Undercity for more training. If you truly count yourself among our faithful, then you should return there also.$B$BYou can find Aelthalyste in the War Quarter deep in the Undercity.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5664] then DB[5664]={id=5664,zoneId=-262,name="<UNUSED>",level=15,minLevel=15,wowhead="https://www.wowhead.com/wotlk/quest=5664",image="assets/images/quests/placeholder.png"} end
if not DB[5665] then DB[5665]={id=5665,zoneId=-262,name="<UNUSED>",level=15,minLevel=15,rewardNextId=5664,wowhead="https://www.wowhead.com/wotlk/quest=5665",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Word was sent here from Darnassus,$N. It seems one of your priestesses wants you to return home. Speak to Priestess Alathea at the Temple of the Moon whenever you're able. It seems she is pleased with your progress. I am sure she takes great pride in seeing one of Elune's servants take such great strides in $ghis:her; faith.$B$BThe Light be with you.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5666] then DB[5666]={id=5666,zoneId=-262,name="<UNUSED>",level=15,minLevel=15,rewardNextId=5664,wowhead="https://www.wowhead.com/wotlk/quest=5666",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Oh,$N,I am pleased to catch you. There has been talk that you are prepared for your next test at the Temple of the Moon. Priestess Alathea herself wishes to speak to you. You should return to Darnassus as quickly as you can. Finish whatever business you have here and make haste.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5667] then DB[5667]={id=5667,zoneId=-262,name="<UNUSED>",level=15,minLevel=15,rewardNextId=5664,wowhead="https://www.wowhead.com/wotlk/quest=5667",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Aye,good to see you're doing well in your training,young $gpriest:priestess;. One of your kind was here looking for you not too long ago. It seems you're wanted back in Darnassus. Something about Priestess Alathea and the Temple of the Moon. It sounded important. Perhaps you should return there soon.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5668] then DB[5668]={id=5668,zoneId=-262,name="<NYI> A Blessing of Light",level=15,minLevel=15,wowhead="https://www.wowhead.com/wotlk/quest=5668",image="assets/images/quests/placeholder.png"} end
if not DB[5669] then DB[5669]={id=5669,zoneId=-262,name="<NYI> A Blessing of Light",level=15,minLevel=15,rewardNextId=5668,wowhead="https://www.wowhead.com/wotlk/quest=5669",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Ah,$N,I'm glad you stopped to talk to me for a moment. One of your priests of Light was here a few moments ago looking for you. High Priestess Laurena in the Cathedral of Light wants to meet with you. I would not be surprised if it was about the progress you've made so far. Many of my order are continuously tested and given greater responsibilities as we progress in our studies.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5670] then DB[5670]={id=5670,zoneId=-262,name="<NYI> A Blessing of Light",level=15,minLevel=15,rewardNextId=5668,wowhead="https://www.wowhead.com/wotlk/quest=5670",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You just missed a messenger here from Stormwind that was looking for you,$N. You've done well for yourself it seems. The High Priestess Laurena wants to talk to you. I think the church feels you're ready for the next step of your training.$B$BWhen you're all set and done with your business here,head to Stormwind,the Cathedral of Light,and speak to her. I'm sure she's waitin' for you.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5671] then DB[5671]={id=5671,zoneId=-262,name="<NYI> A Blessing of Light",level=15,minLevel=15,rewardNextId=5668,wowhead="https://www.wowhead.com/wotlk/quest=5671",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Young $gpriest:priestess;,your church has sent word for you to return to Stormwind. The High Priestess Laurena would have words with you when you are ready. It seems your superiors feel you are ready for the next step of your training.$B$BI believe you can find your High Priestess in the Cathedral of Light. Elune go with you on your journey and peace be with you.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5672] then DB[5672]={id=5672,zoneId=-262,name="Elune's Grace",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5672",image="assets/images/quests/placeholder.png"} end
if not DB[5673] then DB[5673]={id=5673,zoneId=-262,name="Elune's Grace",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5673",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You know you have access to any of our trainers at any time, $N, but there are some things that we cannot pass on to you. One of those things are the teachings of your goddess Elune. She gives special abilities to her faithful, and if I'm not mistaken, it is time for you to return home to your Temple of the Moon to be tested.$B$BReturn there when you can and speak to Priestess Alathea.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5674] then DB[5674]={id=5674,zoneId=-262,name="Elune's Grace",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5674",image="assets/images/quests/placeholder.png",xpDiff=2,desc="A wonderful day has come, $N. You've reached the age in which our $gpriests:priestesses; are trained in abilities only Night elves know. But it is not for me to train you. You must return to the Temple of the Moon and speak to Priestess Alathea as soon as your business here is concluded. She will test you to ensure you're prepared, and only then will she teach you Elune's Grace.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5675] then DB[5675]={id=5675,zoneId=-262,name="Elune's Grace",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5675",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Time's a wastin', $glad:lass;. It's time for you to return home to Darnassus. Priestess Alathea's sent word here that you're to return there for training. Seems they feel you're ready to be tested much like those who serve the Light. You should head out whenever you can. Alathea's message said that she'd be waitin' for you in the Temple of the Moon. Good luck.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5676] then DB[5676]={id=5676,zoneId=-262,name="Arcane Feedback",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5676",image="assets/images/quests/placeholder.png"} end
if not DB[5677] then DB[5677]={id=5677,zoneId=-262,name="Arcane Feedback",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5677",image="assets/images/quests/placeholder.png",xpDiff=2,desc="As much as I'd like to show you our own special teachings of the Light, it is not our place. Your place is back in Stormwind with your own kind, $N... for now. Believe me, I mean no offense. When you return to High Priestess Laurena in the Cathedral of Light you'll understand what I'm talking about--the time has come for your race to prepare you for the future; to separate yourself from others that follow a similar path.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5678] then DB[5678]={id=5678,zoneId=-262,name="Arcane Feedback",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5678",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It is time for you to return to Stormwind, young one. Your superiors there have called you back for more training. And although it disturbs me some, your race and mine are allies and I would not betray that.$B$BI do not mean to be so coy with you--my distrust of arcane magics, be they divine inspired or not, is still strong within me.$B$BYou will know of what I speak after you return to your Cathedral of Light. Speak to High Priestess Laurena when you arrive.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5679] then DB[5679]={id=5679,zoneId=-262,name="Devouring Plague",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5679",image="assets/images/quests/placeholder.png"} end
if not DB[5680] then DB[5680]={id=5680,zoneId=-262,name="Shadowguard",level=-1,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=5680",image="assets/images/quests/placeholder.png"} end
if not DB[5681] then DB[5681]={id=5681,zoneId=-262,name="<UNUSED>",level=25,minLevel=25,wowhead="https://www.wowhead.com/wotlk/quest=5681",image="assets/images/quests/placeholder.png"} end
if not DB[5682] then DB[5682]={id=5682,zoneId=-262,name="<UNUSED>",level=25,minLevel=25,rewardNextId=5681,wowhead="https://www.wowhead.com/wotlk/quest=5682",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The time has come for you to return to Darnassus again,$N. Speak to High Priestess Alathea in the Temple of the Moon. She will tell you what you need to know.$B$BIf I am not mistaken,it will be something about new garments for your station within your order. May the Light be with you.",logDesc="Speak with High Priestess Alathea in Darnassus."} end
if not DB[5683] then DB[5683]={id=5683,zoneId=-262,name="<UNUSED>",level=25,minLevel=25,rewardNextId=5681,wowhead="https://www.wowhead.com/wotlk/quest=5683",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Oh,$gbrother:sister;,I am so pleased for you! It is time for you to return to Darnassus and speak to High Priestess Alathea once again. Her messenger was almost certain it had to do with earning your newest garments of our order.$B$BWhen you can,return home,and give our order my very best.$B$BElune be with you.",logDesc="Speak to High Priestess Alathea in Darnassus."} end
if not DB[5684] then DB[5684]={id=5684,zoneId=-262,name="<UNUSED>",level=25,minLevel=25,rewardNextId=5681,wowhead="https://www.wowhead.com/wotlk/quest=5684",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hmph,good to see you're doin' so well for yourself,$gpriest:priestess;. Bet you're wonderin' when it's time for you to be called back home to Darnassus for some kind of celebration for your greatness,huh? Well,not today... well,not any kind of celebration anyway.$B$BHigh Priestess Alathea's sent word to me that I should direct you to her if I came across you. You can find her in the Temple of the Moon still... in case you forgot. Haha.",logDesc="Speak to High Priestess Alathea in Darnassus."} end
if not DB[5685] then DB[5685]={id=5685,zoneId=-262,name="<NYI> <TXT> The Light Protects You",level=25,minLevel=25,wowhead="https://www.wowhead.com/wotlk/quest=5685",image="assets/images/quests/placeholder.png"} end
if not DB[5686] then DB[5686]={id=5686,zoneId=-262,name="<NYI> The Light Protects You",level=25,minLevel=25,rewardNextId=5685,wowhead="https://www.wowhead.com/wotlk/quest=5686",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The time has come again for you to journey to Stormwind,young $gpriest:priestess;. The High Priestess Laurena would reward you for your time spent in the service of the Light. She is still in the Cathedral of Light--look for her there.$B$BUntil then,you're welcome to stay here and train as much as you'd like. If there is anything I can do for you,please,just ask.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5687] then DB[5687]={id=5687,zoneId=-262,name="<NYI> The Light Protects You",level=25,minLevel=25,rewardNextId=5685,wowhead="https://www.wowhead.com/wotlk/quest=5687",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The time has come again for you to return to the Cathedral of Light in Stormwind,$N. High Priestess Laurena would have you meet with her when you're ready. It is more than likely to repay you for all you have done for your people and the Light.$B$BGood luck,and may Elune be with you in your travels.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5688] then DB[5688]={id=5688,zoneId=-262,name="<NYI> <TXT> A Touch of Voodoo",level=15,minLevel=15,wowhead="https://www.wowhead.com/wotlk/quest=5688",image="assets/images/quests/placeholder.png"} end
if not DB[5689] then DB[5689]={id=5689,zoneId=-262,name="<NYI> A Touch of Voodoo",level=15,minLevel=15,rewardNextId=5688,wowhead="https://www.wowhead.com/wotlk/quest=5689",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hey,$r. A messenger came through here not too long ago looking for you. Said you were to return to Orgrimmar to speak to Ur'kyo in the Valley of Spirits. He didn't sound angry,but it did sound important. Might want to check it out.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5690] then DB[5690]={id=5690,zoneId=-262,name="<NYI> <TXT> A Touch of Voodoo",level=15,minLevel=15,rewardNextId=5688,wowhead="https://www.wowhead.com/wotlk/quest=5690",image="assets/images/quests/placeholder.png",xpDiff=2} end
if not DB[5691] then DB[5691]={id=5691,zoneId=-262,name="<NYI> <TXT> In the Dark it was Created",level=15,minLevel=15,wowhead="https://www.wowhead.com/wotlk/quest=5691",image="assets/images/quests/placeholder.png"} end
if not DB[5692] then DB[5692]={id=5692,zoneId=-262,name="<NYI> In the Dark It was Created",level=15,minLevel=15,rewardNextId=5691,wowhead="https://www.wowhead.com/wotlk/quest=5692",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I would teach you all you need know,$N,but there things that only your own tribe can show you. One be how to create a new robe for you... one that reflect your place in your faith.$B$BAelthalyste say that I direct you to her in the Undercity. She be in the War Quarter waiting for you. If you not go then she be very displeased with both of us.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5693] then DB[5693]={id=5693,zoneId=-262,name="<NYI> In the Dark It was Created",level=15,minLevel=15,rewardNextId=5691,wowhead="https://www.wowhead.com/wotlk/quest=5693",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Glad to see you're... alive,$N.$B$BAelthalyste has asked you to return to the Undercity when you've finished your business here in Thunder Bluff. It seems you've grown powerful enough that she thinks you're due new garments... a robe,I believe.$B$BShe'll be waiting for you in the War Quarter.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5694] then DB[5694]={id=5694,zoneId=-262,name="<UNUSED>",level=35,minLevel=35,wowhead="https://www.wowhead.com/wotlk/quest=5694",image="assets/images/quests/placeholder.png"} end
if not DB[5695] then DB[5695]={id=5695,zoneId=-262,name="<UNUSED>",level=35,minLevel=35,rewardNextId=5694,wowhead="https://www.wowhead.com/wotlk/quest=5695",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Your temple asks for your presence in Darnassus,$N. Return to the Temple of the Moon and speak to Priestess Alathea. She will be waiting for you there.$B$BThe time has come for you to earn your next robe if you feel you are ready.",logDesc="Speak to Priestesss Alathea in Darnassus."} end
if not DB[5696] then DB[5696]={id=5696,zoneId=-262,name="<UNUSED>",level=35,minLevel=35,rewardNextId=5694,wowhead="https://www.wowhead.com/wotlk/quest=5696",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It is always a joyous day when I can direct one of our kind back to our home because the time has come for them to earn their next set of robes.$B$BPriestess Alathea is in the Temple of the Moon and wishes to speak to you. When you can,return to Darnassus for your next test,and Elune be with you,$N.",logDesc="Speak to Prietess Alathea in Darnassus."} end
if not DB[5697] then DB[5697]={id=5697,zoneId=-262,name="<UNUSED>",level=35,minLevel=35,rewardNextId=5694,wowhead="https://www.wowhead.com/wotlk/quest=5697",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You keep up this rate of success,an' you'll be makin' me jealous that we don't have more of your $gpriests:priestesses; here in Ironforge,$N. You do your people proud.$B$BPriestess Alathea would like to speak to you again if you have time. She's in the Temple of the Moon in Darnassus. Go there,an' the Light be with you.",logDesc="Speak to Priestess Alathea in Darnassus."} end
if not DB[5698] then DB[5698]={id=5698,zoneId=-262,name="<NYI> <TXT> A Small Amount of Hope",level=35,minLevel=35,wowhead="https://www.wowhead.com/wotlk/quest=5698",image="assets/images/quests/placeholder.png"} end
if not DB[5699] then DB[5699]={id=5699,zoneId=-262,name="<NYI> A Small Amount of Hope",level=35,minLevel=35,rewardNextId=5698,wowhead="https://www.wowhead.com/wotlk/quest=5699",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Haha! Off to Stormwind with you,$N. High Priestess Laurena wants you there to be tested again. Head to the Cathedral of Light and don't dally. There's a lot to do and more and more pressure's gonna fall on your shoulders the more powerful you get. It's the nature of our order--people start to look to you more often the more you prove yourself worthy.$B$BThe Light's with ya,you don't need me to tell you that.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5700] then DB[5700]={id=5700,zoneId=-262,name="<NYI> A Small Amount of Hope",level=35,minLevel=35,rewardNextId=5698,wowhead="https://www.wowhead.com/wotlk/quest=5700",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Your temple wishes you to return to them once again,$N. High Priestess Laurena in Stormwind specifically. There is much activity in the Cathedral of Light these days,but that does not surprise me at all; so much going on between the Scourge,the Horde and our own problems internally.$B$BGo to the Cathedral when you're ready.",logDesc="Speak to High Priestess Laurena in Stormwind."} end
if not DB[5701] then DB[5701]={id=5701,zoneId=-262,name="<NYI> <TXT> The Rites of Old",level=25,minLevel=25,wowhead="https://www.wowhead.com/wotlk/quest=5701",image="assets/images/quests/placeholder.png"} end
if not DB[5702] then DB[5702]={id=5702,zoneId=-262,name="<NYI> The Rites of Old",level=25,minLevel=25,rewardNextId=5701,wowhead="https://www.wowhead.com/wotlk/quest=5702",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hey there,$r! I'll teach you whatever it is you want to know,but you should know that Ur'kyo--that's his name,right?--is looking for you. Something was said about you coming back to the Valley of Trials... no,that wasn't it. It was the Valley of Spirits... in Orgrimmar. Yeah,that's it!$B$BYeah,so,Ur'kyo... Valley of Spirits. He wants to talk to you.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5703] then DB[5703]={id=5703,zoneId=-262,name="<NYI> The Rites of Old",level=25,minLevel=25,rewardNextId=5701,wowhead="https://www.wowhead.com/wotlk/quest=5703",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Your spiritual leader Ur'kyo seeks audience with you,$N. Do not keep him waiting.$B$BYou will find him in the Valley of Spirits in the great Horde city of Orgrimmar. Do your people proud.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5704] then DB[5704]={id=5704,zoneId=-262,name="<NYI> <TXT> Undead Priest Robe",level=25,minLevel=25,wowhead="https://www.wowhead.com/wotlk/quest=5704",image="assets/images/quests/placeholder.png"} end
if not DB[5705] then DB[5705]={id=5705,zoneId=-262,name="<NYI> No Longer a Shadow",level=25,minLevel=25,rewardNextId=5704,wowhead="https://www.wowhead.com/wotlk/quest=5705",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I welcome you back to the Valley of Spirits,$N,but I must tell you,you are wanted back in your Undercity. Your head priestess there would be wantin' to speak to you.$B$BYou already know where she at: the War Quarter deep in your city.$B$BGo there and do not forget,you are always welcome to train here with my people.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5706] then DB[5706]={id=5706,zoneId=-262,name="<NYI> No Longer a Shadow",level=25,minLevel=25,rewardNextId=5704,wowhead="https://www.wowhead.com/wotlk/quest=5706",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Good to see you again,$N. But I'm gonna have to cut our reunion short--Aelthalyste sent word that you were to return to her in the Undercity. She's still in the War Quarter.$B$BDon't worry though--I think it's a good thing. It was mentioned that she was pleased with your progress,so don't fret too much.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5707] then DB[5707]={id=5707,zoneId=-262,name="<NYI> <TXT> Flirting With Darkness",level=35,minLevel=35,wowhead="https://www.wowhead.com/wotlk/quest=5707",image="assets/images/quests/placeholder.png"} end
if not DB[5708] then DB[5708]={id=5708,zoneId=-262,name="<NYI> Flirting With Darkness",level=35,minLevel=35,rewardNextId=5707,wowhead="https://www.wowhead.com/wotlk/quest=5708",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Talk is spreading that your faith is taking up more active measures to protect and lead the Forsaken. It seems Aelthalyste either be knowin' something that Sylvanas does not,or your Dark Lady be wantin' Aelthalyste to be a little less patient in her measures.$B$BYou best be headin' home to the Undercity to speak to her. She be in the War Quarter as always.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5709] then DB[5709]={id=5709,zoneId=-262,name="<NYI> Flirting With Darkness",level=35,minLevel=35,rewardNextId=5707,wowhead="https://www.wowhead.com/wotlk/quest=5709",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The time's come again,$N. You're needed in the Undercity. Aelthalyste has grown... fond of some of the Forsaken's priests,and in the interest of protecting Lady Sylvanas,she wants to ensure that all of us are as well prepared as possible.$B$BFind her in the War Quarter and be prepared for whatever task it is she sets for you.",logDesc="Speak to Aelthalyste in the Undercity."} end
if not DB[5710] then DB[5710]={id=5710,zoneId=-262,name="<NYI> <TXT> Troll Priest Robe",level=35,minLevel=35,wowhead="https://www.wowhead.com/wotlk/quest=5710",image="assets/images/quests/placeholder.png"} end
if not DB[5711] then DB[5711]={id=5711,zoneId=-262,name="<NYI> The Lost Ways",level=35,minLevel=35,rewardNextId=5710,wowhead="https://www.wowhead.com/wotlk/quest=5711",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I wonder how many times I've seen your kind around here,but never really spoken to you. I've trained a few,given some directions,but I don't think anyone's ever waited around long enough to chat.$B$BOh well,now's a bad time anyway--I'm supposed to tell you that Ur'kyo wants to speak to you in Orgrimmar. He's in the Valley of Spirits waiting for you.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5712] then DB[5712]={id=5712,zoneId=-262,name="<NYI> The Lost Ways",level=35,minLevel=35,rewardNextId=5710,wowhead="https://www.wowhead.com/wotlk/quest=5712",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Good fortune be with you,young one.$B$BTroll messengers arrived in the Undercity not more than a day or so ago. They spoke of young priests returning to the Valley of Spirits to speak to Ur'kyo. I would suggest you investigate the matter on your own in case his business pertains to you. I am sure you remember the way back to Orgrimmar.",logDesc="Speak to Ur'kyo in Orgrimmar."} end
if not DB[5713] then DB[5713]={id=5713,zoneId=148,name="One Shot.  One Kill.",level=15,minLevel=10,giver="Sentinel Aynasha",giverType="NPC",giverId=11711,ender="Sentinel Onaeya",enderType="NPC",enderId=11806,poiX=4391,poiY=-67,wowhead="https://www.wowhead.com/wotlk/quest=5713",image="assets/images/quests/placeholder.png",xpDiff=5,money=1400,desc="I was traveling to Auberdine with an important message when I was attacked by the furbolg Marosh and his trackers. During the attack I was poisoned, leaving me barely able to stand. I can make an antidote, but it will take time before it is ready.$B$BI would ask that you defend me until I can apply the antidote. I will aid you with my bow as best I can.$B$BShould we survive, I will be able to deliver my message to Auberdine, while you speak with Onaeya at Maestra's Post to inform her of this incident.",logDesc="Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale."} end
if not DB[5721] then DB[5721]={id=5721,zoneId=139,name="The Battle of Darrowshire",level=60,minLevel=55,giver="Chromie",giverType="NPC",giverId=10667,ender="Pamela Redpath",enderType="NPC",enderId=10926,rewardNextId=5942,poiX=1453,poiY=-1280,wowhead="https://www.wowhead.com/wotlk/quest=5721",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Now, $N, you will take part in battle of Darrowshire, and you will save Joseph Redpath.$B$BPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.$B$BAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.",logDesc="Place the Relic Bundle at the Darrowshire town square.$B$BPrevent Davil Lightfire's death until the death of Horgus.$B$BPrevent Captain Redpath's death until Redpath the Corrupted appears.$B$BDefeat Redpath the Corrupted.$B$BSpeak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.",rewards={{id=15723,qty=1}}} end
if not DB[5722] then DB[5722]={id=5722,zoneId=2437,name="Searching for the Lost Satchel",level=16,minLevel=9,giver="Rahauro",giverType="NPC",giverId=11833,ender="Maur Grimtotem",enderType="NPC",enderId=11834,rewardNextId=5724,poiX=-1056,poiY=-217,wowhead="https://www.wowhead.com/wotlk/quest=5722",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.$B$BReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.$B$BAgain, seek the Chasm in the darkest areas of Orgrimmar.",logDesc="Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest."} end
if not DB[5723] then DB[5723]={id=5723,zoneId=2437,name="Testing an Enemy's Strength",level=15,minLevel=9,giver="Rahauro",giverType="NPC",giverId=11833,ender="Rahauro",enderType="NPC",enderId=11833,poiX=-1056,poiY=-217,wowhead="https://www.wowhead.com/wotlk/quest=5723",image="assets/images/quests/placeholder.png",xpDiff=7,money=700,desc="Beneath the city of Orgrimmar, stout creatures known as troggs started coming to the surface from deep below the lava filled tunnels. In her ever-benevolence, Magatha sought to make peace with the creatures, but they turned on her diplomats, killing them. She will not allow such treatment of the tauren people and now consider the creatures a threat to all of the Horde.$B$BShe asks that you put an end to this trogg threat before it overwhelms the Horde from below. Find Ragefire Chasm and destroy them all.",logDesc="Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff."} end
if not DB[5724] then DB[5724]={id=5724,zoneId=2437,name="Returning the Lost Satchel",level=16,minLevel=9,giver="Maur Grimtotem",giverType="NPC",giverId=11834,ender="Rahauro",enderType="NPC",enderId=11833,poiX=-148,poiY=24,wowhead="https://www.wowhead.com/wotlk/quest=5724",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs.$B$BRemoving the satchel from his vice-like grip, you stow it with your own equipment and prepare to make your way out of the tunnels and back to Rahauro in Thunder Bluff.",logDesc="Take the Grimtotem Satchel to Rahauro in Thunder Bluff.",choiceRewards={{id=15452,qty=1},{id=15453,qty=1}}} end
if not DB[5725] then DB[5725]={id=5725,zoneId=2437,name="The Power to Destroy...",level=16,minLevel=9,giver="Varimathras",giverType="NPC",giverId=2425,ender="Varimathras",enderType="NPC",enderId=2425,wowhead="https://www.wowhead.com/wotlk/quest=5725",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with... lesser vision.$B$BA sect of the Shadow Council hidden in caverns below Orgrimmar known as the Searing Blade are a prime example. The Lady tells me that members of the Searing Blade have come into the possession of two powerful spell books--she would like to \"borrow\" these books from them. You will get them for her.",logDesc="Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.",choiceRewards={{id=15449,qty=1},{id=15450,qty=1},{id=15451,qty=1}}} end
if not DB[5726] then DB[5726]={id=5726,zoneId=1637,name="Hidden Enemies",level=12,minLevel=9,giver="Thrall",giverType="NPC",giverId=4949,ender="Thrall",enderType="NPC",enderId=4949,poiX=1920,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=5726",image="assets/images/quests/placeholder.png",xpDiff=5,money=250,desc="One thing I will not tolerate are traitors in our midst, $N. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.$B$BBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.$B$BIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to me.",logDesc="Bring a Lieutenant's Insignia to Thrall in Orgrimmar."} end
if not DB[5727] then DB[5727]={id=5727,zoneId=1637,name="Hidden Enemies",level=12,minLevel=9,giver="Thrall",giverType="NPC",giverId=4949,ender="Thrall",enderType="NPC",enderId=4949,rewardNextId=5728,poiX=1920,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=5727",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Now let us see if this insignia you found is worth the effort.$B$BThere is a warlock within the city who believes he has my trust. He does not know that I realize where his true loyalties lie. He is in fact the leader of the Burning Blade. But do not rush off to do battle with him; he has a purpose, and we shall use him against our enemies.$B$BTake this insignia to him in the Cleft of Shadow here in Orgrimmar, speak to him and see if he believes you are one of his own, then return to me here.",logDesc="Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar."} end
if not DB[5728] then DB[5728]={id=5728,zoneId=2437,name="Hidden Enemies",level=16,minLevel=9,giver="Thrall",giverType="NPC",giverId=4949,ender="Thrall",enderType="NPC",enderId=4949,rewardNextId=5729,poiX=1920,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=5728",image="assets/images/quests/placeholder.png",xpDiff=7,money=800,desc="Hmm, leaders of the Searing Blade... this concerns me most. If they are the ones of value to Neeru, then those are who we must target first. This satyr... Bazzalan, and the other Neeru mentioned--what was he, a warlock?--must be slain.$B$BReturn to the Cleft of Shadow and enter Ragefire Chasm, $N. Find these two leaders of the Searing Blade, and kill them. But be careful not to let Neeru know it was you who did this. You must retain your identity as one of his $gbrothers:sisters; in arms.",logDesc="Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar."} end
if not DB[5729] then DB[5729]={id=5729,zoneId=1637,name="Hidden Enemies",level=15,minLevel=9,giver="Thrall",giverType="NPC",giverId=4949,ender="Neeru Fireblade",enderType="NPC",enderId=3216,rewardNextId=5730,poiX=1920,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=5729",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I think our next step should be to have you placed close to Neeru. If he is as agitated as reports suggest, then we may accomplish two things. One, you may be able to gain some greater knowledge about the Council or at least the Burning Blade, and two, he may just begin to trust you enough that he asks you to start to aid him. He may very well look at you as someone who can fill the void now that some of the leadership is in turmoil.$B$BReturn to the Cleft and speak to him again, but do not be too overt.",logDesc="Speak to Neeru Fireblade in Orgrimmar."} end
if not DB[5730] then DB[5730]={id=5730,zoneId=1637,name="Hidden Enemies",level=16,minLevel=9,giver="Neeru Fireblade",giverType="NPC",giverId=3216,ender="Thrall",enderType="NPC",enderId=4949,poiX=1801,poiY=-4375,wowhead="https://www.wowhead.com/wotlk/quest=5730",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You are one of my lieutenants! Prepare yourself, $c. I will call upon you soon.$B$BMy time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer. I will do what I can to minimize the damage here in Ragefire Chasm. In the meantime, I will have my agents in the Barrens and Ashenvale begin work on our newest agenda. Return to me soon.",logDesc="Speak to Thrall in Orgrimmar and tell him what you've learned.",choiceRewards={{id=15443,qty=1},{id=15445,qty=1},{id=15424,qty=1},{id=15444,qty=1}}} end
if not DB[5741] then DB[5741]={id=5741,zoneId=405,name="Sceptre of Light",level=33,minLevel=30,giver="Azore Aldamort",giverType="NPC",giverId=11863,ender="Azore Aldamort",enderType="NPC",enderId=11863,rewardNextId=6027,poiX=-362,poiY=2485,wowhead="https://www.wowhead.com/wotlk/quest=5741",image="assets/images/quests/placeholder.png",xpDiff=5,money=3500,desc="The Burning Blade in Thunder Axe Fortress to the east is rumored to have acquired the Sceptre of Light from the Naga. Legend tells that the sceptre is able to sink entire cities under the great seas. The Burning Blade must not be allowed to possess such power.$B$BTo that end, you must retrieve the sceptre yourself!  It is held by a Burning Blade seer, who studies the sceptre from atop one of the Thunder Axe watchtowers.$B",logDesc="Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor.$B"} end
if not DB[5742] then DB[5742]={id=5742,zoneId=139,name="Redemption",level=56,minLevel=52,giver="Tirion Fordring",giverType="NPC",giverId=1855,ender="Tirion Fordring",enderType="NPC",enderId=1855,rewardNextId=5781,poiX=2672,poiY=-2478,wowhead="https://www.wowhead.com/wotlk/quest=5742",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You have worked hard, friend. Rest your weary bones and allow me to properly introduce myself.$B",logDesc="Listen to what Tirion Fordring has to say."} end
if not DB[5761] then DB[5761]={id=5761,zoneId=2437,name="Slaying the Beast",level=16,minLevel=9,giver="Neeru Fireblade",giverType="NPC",giverId=3216,ender="Neeru Fireblade",enderType="NPC",enderId=3216,poiX=1801,poiY=-4375,wowhead="https://www.wowhead.com/wotlk/quest=5761",image="assets/images/quests/placeholder.png",xpDiff=7,money=800,desc="The primary task set upon me by our great Warchief is to root out the creatures responsible for infesting our lord's great city with demonic influence. The Burning Blade is one threat, but there are others; the Searing Blade for instance, who make their home in Ragefire Chasm, secretly attempting to subvert innocent members of the Horde.$B$BIf they are to be stopped, then their leader must be slain--a Felguard named Taragaman the Hungerer.$B$BKill him, and his heart will appease Thrall, of this I'm sure.",logDesc="Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar."} end
if not DB[5762] then DB[5762]={id=5762,zoneId=400,name="Hemet Nesingwary Jr.",level=31,minLevel=28,giver="Kravel Koalbeard",giverType="NPC",giverId=4452,ender="Hemet Nesingwary Jr.",enderType="NPC",enderId=715,poiX=-6233,poiY=-3856,wowhead="https://www.wowhead.com/wotlk/quest=5762",image="assets/images/quests/placeholder.png",xpDiff=3,money=3000,desc="I have a package for a new customer of mine, a dwarf named Hemet Nesingwary Jr..  The package took weeks to arrive, and Hemet's long gone by now.  He said he was going to Stranglethorn to take his father's place and hunt the beasts there, but he left me some money to send his delivery when I could.  $B$BJunior's a rich dwarf and it's a good idea to keep up relations with the rich ones, yeah?  So... you want to deliver the package for me?$B$BI heard he has a camp in Stranglethorn, north of Grom'gol.",logDesc="Take Kravel's Crate to Hemet Nesingwary Jr. in Stranglethorn Vale."} end
if not DB[5763] then DB[5763]={id=5763,zoneId=405,name="Hunting in Stranglethorn",level=31,minLevel=28,giver="Roon Wildmane",giverType="NPC",giverId=11877,ender="Hemet Nesingwary Jr.",enderType="NPC",enderId=715,poiX=-1715,poiY=3107,wowhead="https://www.wowhead.com/wotlk/quest=5763",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Long ago, a dwarf came to this land.  His name was Hemet and he wished to hunt great beasts.  His skills with the rifle were uncanny, and we spent many days hunting together.  Even the enmity between our peoples was forgotten.$B$BWhen he left for Stranglethorn, I vowed to one day welcome him back.  Now he has gone on to hunt in lands unknown, but his son has taken his place.$B$BTake this kodo horn as a gift to Hemet Jr..  You will find him in Stranglethorn, north of the Grom'gol Base camp.",logDesc="Bring Roon's Kodo Horn to Hemet Nesingwary Jr. in Stranglethorn Vale."} end
if not DB[5781] then DB[5781]={id=5781,zoneId=139,name="Of Forgotten Memories",level=57,minLevel=52,giver="Tirion Fordring",giverType="NPC",giverId=1855,ender="Tirion Fordring",enderType="NPC",enderId=1855,rewardNextId=5845,poiX=2672,poiY=-2478,wowhead="https://www.wowhead.com/wotlk/quest=5781",image="assets/images/quests/placeholder.png",xpDiff=5,desc="To help Taelan regain what he has lost, you must gather items from his past.$B$BThe first such item is a toy that I gave to him on his 7th birthday. It was his most cherished possession: A miniature war hammer; an exact replica of my very own.$B$BAfter I was banished for treason, his mother told him that I had died. He was taken to my false grave at the Undercroft, where he buried the hammer along with my memory - forever.$B$BYou must venture to the Undercroft and recover Taelan's hammer.",logDesc="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective."} end
if not DB[5801] then DB[5801]={id=5801,zoneId=440,name="Fire Plume Forged",level=57,minLevel=55,giver="Krinkle Goodsteel",giverType="NPC",giverId=5411,ender="Alchemist Arbington",enderType="NPC",enderId=11056,rewardNextId=5803,poiX=-7200,poiY=-3770,wowhead="https://www.wowhead.com/wotlk/quest=5801",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.$B$BTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.$B$BThat's it on my end.  To finish your key, you'll need to talk to Arbington again.",logDesc="Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater.  Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.$B$BBring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands."} end
if not DB[5802] then DB[5802]={id=5802,zoneId=440,name="Fire Plume Forged",level=57,minLevel=55,giver="Krinkle Goodsteel",giverType="NPC",giverId=5411,ender="Apothecary Dithers",enderType="NPC",enderId=11057,rewardNextId=5804,poiX=-7200,poiY=-3770,wowhead="https://www.wowhead.com/wotlk/quest=5802",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.$B$BTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.$B$BThat's it on my end.  To finish your key, you'll need to talk to Dithers again.",logDesc="Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater.  Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.$B$BBring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands."} end
if not DB[5803] then DB[5803]={id=5803,zoneId=28,name="Araj's Scarab",level=60,minLevel=55,giver="Alchemist Arbington",giverType="NPC",giverId=11056,ender="Alchemist Arbington",enderType="NPC",enderId=11056,poiX=965,poiY=-1418,wowhead="https://www.wowhead.com/wotlk/quest=5803",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Araj the Summoner lords over Andorhal from the ruined city's heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.$B$BMake your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery!$B$BThe Key to Scholomance awaits, $N!",logDesc="Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands."} end
if not DB[5804] then DB[5804]={id=5804,zoneId=28,name="Araj's Scarab",level=60,minLevel=55,giver="Apothecary Dithers",giverType="NPC",giverId=11057,ender="Apothecary Dithers",enderType="NPC",enderId=11057,poiX=1752,poiY=-730,wowhead="https://www.wowhead.com/wotlk/quest=5804",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Araj the Summoner lords over Andorhal from the ruined city's heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.$B$BMake your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery!$B$BThe Key to Scholomance awaits, $N!",logDesc="Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands."} end
if not DB[5805] then DB[5805]={id=5805,zoneId=24,name="Welcome!",level=1,minLevel=1,ender="Merissa Stilwell",enderType="NPC",enderId=11940,wowhead="https://www.wowhead.com/wotlk/quest=5805",image="assets/images/quests/placeholder.png",desc="Welcome to the World of Warcraft!$B$BAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Merissa Stilwell in Goldshire.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.$B$BThanks again, and enjoy your stay in the World of Warcraft!$B",logDesc="Bring the Goldshire Gift Voucher to Merissa Stilwell in Goldshire.",choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}} end
if not DB[5821] then DB[5821]={id=5821,zoneId=405,name="Bodyguard for Hire",level=35,minLevel=30,giver="Cork Gizelton",giverType="NPC",giverId=11625,ender="Smeed Scrabblescrew",enderType="NPC",enderId=11596,poiX=-1291,poiY=1231,wowhead="https://www.wowhead.com/wotlk/quest=5821",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop. It's not good for business to be dead!$B$BI'll tell you what $c, if you protect us past the Kolkar village we'll make it worth your while.$B$BIt's just a short distance, all you need to do is keep the caravan intact and you can pick up your reward from Smeed Scrabblescrew - he is down the road a bit. We do a little business together.",logDesc="Escort the Gizelton Caravan past the Kolkar Centaur village. Talk with Smeed at Scrabblescrew's Camp for your reward.",rewards={{id=15689,qty=1}}} end
if not DB[5841] then DB[5841]={id=5841,zoneId=132,name="Welcome!",level=1,minLevel=1,ender="Yori Crackhelm",enderType="NPC",enderId=11941,wowhead="https://www.wowhead.com/wotlk/quest=5841",image="assets/images/quests/placeholder.png",desc="Welcome to the World of Warcraft!$B$BAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Yori Crackhelm in Kharanos.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.$B$BThanks again, and enjoy your stay in the World of Warcraft!",logDesc="Bring the Kharanos Gift Voucher to Yori Crackhelm in Kharanos.",choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}} end
if not DB[5842] then DB[5842]={id=5842,zoneId=188,name="Welcome!",level=1,minLevel=1,ender="Orenthil Whisperwind",enderType="NPC",enderId=11942,wowhead="https://www.wowhead.com/wotlk/quest=5842",image="assets/images/quests/placeholder.png",desc="Welcome to the World of Warcraft!$B$BAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Orenthil Whisperwind in Dolanaar.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.$B$BThanks again, and enjoy your stay in the World of Warcraft!",logDesc="Bring the Dolanaar Gift Voucher to Orenthil Whisperwind in Dolanaar.",choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}} end
if not DB[5843] then DB[5843]={id=5843,zoneId=363,name="Welcome!",level=1,minLevel=1,ender="Magga",enderType="NPC",enderId=11943,wowhead="https://www.wowhead.com/wotlk/quest=5843",image="assets/images/quests/placeholder.png",desc="Welcome to the World of Warcraft!$B$BAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Magga in Razor Hill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.$B$BThanks again, and enjoy your stay in the World of Warcraft!",logDesc="Bring the Razor Hill Gift Voucher to Magga in Razor Hill.",choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}} end
if not DB[5844] then DB[5844]={id=5844,zoneId=221,name="Welcome!",level=1,minLevel=1,ender="Vorn Skyseer",enderType="NPC",enderId=11944,wowhead="https://www.wowhead.com/wotlk/quest=5844",image="assets/images/quests/placeholder.png",desc="Welcome to the World of Warcraft!$B$BAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Vorn Skyseer in Bloodhoof Village.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.$B$BThanks again, and enjoy your stay in the World of Warcraft!",logDesc="Bring the Bloodhoof Village Gift Voucher to Vorn Skyseer in Bloodhoof Village.",choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}} end
if not DB[5845] then DB[5845]={id=5845,zoneId=139,name="Of Lost Honor",level=58,minLevel=52,giver="Tirion Fordring",giverType="NPC",giverId=1855,ender="Tirion Fordring",enderType="NPC",enderId=1855,rewardNextId=5846,poiX=2672,poiY=-2478,wowhead="https://www.wowhead.com/wotlk/quest=5845",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Order of the Silver Hand was utterly decimated when Uther was slain.$B$BThe boy held out for as long as he could. Pushed to the war torn hamlet of Northdale, he made his final stand.$B$BWere any of the Order left alive, he thought - and did it matter?$B$BIt was with that thought that Taelan threw down the standard of the Order and renounced all that he had known. His honor left upon the blood soaked ground of Northdale.$B$BYou must travel to Northdale and recover that symbol of lost honor.",logDesc="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective."} end
if not DB[5846] then DB[5846]={id=5846,zoneId=139,name="Of Love and Family",level=58,minLevel=52,giver="Tirion Fordring",giverType="NPC",giverId=1855,ender="Artist Renfray",enderType="NPC",enderId=11936,rewardNextId=5848,poiX=2672,poiY=-2478,wowhead="https://www.wowhead.com/wotlk/quest=5846",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When Taelan was a child, we would oft visit Caer Darrow on family excursions. On our last visit, an artist by the name of Renfray painted a portrait of us poised along the beachside. It is my fondest memory of both Taelan and Karandra. For it was at that moment, with my wife and son in my arms, that I felt a bond of love and family that I would never know again.$B$BIf this painting still exists, you must find it.$B$BTravel to the ruined island of Caer Darrow and see if the painting or the artist remain.",logDesc="Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."} end
if not DB[5847] then DB[5847]={id=5847,zoneId=154,name="Welcome!",level=1,minLevel=1,ender="Claire Willower",enderType="NPC",enderId=11945,wowhead="https://www.wowhead.com/wotlk/quest=5847",image="assets/images/quests/placeholder.png",desc="Welcome to the World of Warcraft!$B$BAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Claire Willower in Brill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.$B$BThanks again, and enjoy your stay in the World of Warcraft!",logDesc="Bring the Brill Gift Voucher to Claire Willower in Brill.",choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}} end
if not DB[5848] then DB[5848]={id=5848,zoneId=2017,name="Of Love and Family",level=60,minLevel=52,giver="Artist Renfray",giverType="NPC",giverId=11936,ender="Tirion Fordring",enderType="NPC",enderId=1855,rewardNextId=5861,poiX=1206,poiY=-2412,wowhead="https://www.wowhead.com/wotlk/quest=5848",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The painting... It hung on the wall of my workshop - inside the Order's barracks - for years.$B$BAfter Tirion's trial was over, I knew that I could no longer keep the painting visible. I hid it in a place that they would never think to look.$B$BTravel to Stratholme and make your way deep inside what is now the Scarlet Bastion, search for a painting of our twin moons. Chip away at the paint until you uncover my master work, 'Of Love and Family.'$B$BMay the Light guide your actions.",logDesc="Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.$B$BReturn the painting to Tirion Fordring."} end
if not DB[5861] then DB[5861]={id=5861,zoneId=28,name="Find Myranda",level=60,minLevel=52,giver="Tirion Fordring",giverType="NPC",giverId=1855,ender="Myranda the Hag",enderType="NPC",enderId=11872,rewardNextId=5862,poiX=2672,poiY=-2478,wowhead="https://www.wowhead.com/wotlk/quest=5861",image="assets/images/quests/placeholder.png",xpDiff=4,desc="$N, you have done all that I have asked thus far. Only one step remains in your quest of redemption.$B$BYou must deliver the items you have collected to Taelan. Unfortunately, Taelan and his Scarlet Crusaders will attack you on sight.$B$BThere is only one way in which to deliver my message and that is through a guise of deception.$B$BTo the south you will find Uther's tomb. An old and trusted confidant of mine, Myranda, now resides there - seek her out. Show her the items and she will assist you.",logDesc="Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift."} end
if not DB[5862] then DB[5862]={id=5862,zoneId=28,name="Scarlet Subterfuge",level=60,minLevel=52,giver="Myranda the Hag",giverType="NPC",giverId=11872,ender="Highlord Taelan Fordring",enderType="NPC",enderId=1842,poiX=1135,poiY=-1767,wowhead="https://www.wowhead.com/wotlk/quest=5862",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I am what you would call, an illusionist. Though I may be able to create an illusion to allow you entry into Hearthglen, be warned; my powers have their limitations.$B$BShould you travel too far from these lands, the effects of the illusion will cease. The spell itself takes a great amount of concentration and power from me, and thus, I can only sustain the effect for a short time.$B$BSpeak to me again when you are ready.",logDesc="Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.$B$BHearthglen is to the north, Taelan should be inside of Mardenholde Keep."} end
if not DB[5863] then DB[5863]={id=5863,zoneId=440,name="The Dunemaul Compound",level=49,minLevel=44,giver="Andi Lynn",giverType="NPC",giverId=11758,ender="Andi Lynn",enderType="NPC",enderId=11758,poiX=-7135,poiY=-3863,wowhead="https://www.wowhead.com/wotlk/quest=5863",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Just recently, a large band of nomadic ogres arrived in Tanaris. South of here, they have taken over a large area of the desert and formed a compound. Several smaller bands are currently wandering the desert, some of which have invaded the old troll ruins.$B$BThe Dunemaul Compound must be destroyed! We cannot allow these ogres to build up a force.$B$BThe leader of this band is named Gor'marok the Ravager; I believe that putting an end to his leadership will be the beginning of the end for the ogres.",logDesc="Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.",choiceRewards={{id=16738,qty=1},{id=16739,qty=1}}} end
if not DB[5881] then DB[5881]={id=5881,zoneId=406,name="Calling in the Reserves",level=28,minLevel=23,giver="Maggran Earthbinder",giverType="NPC",giverId=11860,ender="Grish Longrunner",enderType="NPC",enderId=12576,poiX=925,poiY=941,wowhead="https://www.wowhead.com/wotlk/quest=5881",image="assets/images/quests/placeholder.png",xpDiff=3,money=1200,desc="The Horde does well keeping our troops fresh... since the Great War we have been prosperous here in Kalimdor.$B$BI need you to do me a favor, I have a lad by the name of Grish Longrunner protecting the Great Lift in the southern barrens. Give him this letter; the letter will let him know that I have a reserve warrior coming to relieve him of duty so that he can visit his family. He requested this sometime ago and he would be happy to hear the news.",logDesc="Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens."} end
