if not DB[6661] then DB[6661]={id=6661,zoneId=2257,name="Deeprun Rat Roundup",level=12,minLevel=10,giver="Monty",giverType="NPC",giverId=12997,ender="Monty",enderType="NPC",enderId=12997,poiX=-20,poiY=40,wowhead="https://www.wowhead.com/wotlk/quest=6661",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Avast ye scallywag. Arrrr... Arrrr ye looking fer work? We gots a serious rat problem down here an' not enough hands on the poop deck.$B$BWhat do ye say? All ye needs to do is take this here rat catchin' flute and play the melody around the vermin. They'll follow ye to the ends of the world!$B$BJust capture five of the little buggers and bring em back here. We needs em alive.$B$BArrrrr...",logDesc="Capture 5 Deeprun Rats by using the Rat Catcher's Flute. Lead the rats back to Monty. Don't forget to turn in the flute when you're finished."} end
if not DB[6662] then DB[6662]={id=6662,zoneId=2257,name="Me Brother, Nipsy",level=12,minLevel=10,giver="Monty",giverType="NPC",giverId=12997,ender="Nipsy",enderType="NPC",enderId=13018,poiX=-20,poiY=40,wowhead="https://www.wowhead.com/wotlk/quest=6662",image="assets/images/quests/placeholder.png",xpDiff=1,money=500,desc="Me brother, Nipsy, runs a rat kabob operation on the other side of Deeprun. Ye needs to take this here crate o' rats to him before they go bad. Get a move on!$B$BYe have ridden a tram before, aye? It's easy. Just step aboard when she arrives and enjoy the ride. An' keep yer arms and legs inside durin' the ride, lest ye be peglegged fer life.",logDesc="Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot.",rewards={{id=17119,qty=10}}} end
if not DB[6681] then DB[6681]={id=6681,zoneId=-162,name="The Manor, Ravenholdt",level=24,minLevel=24,ender="Fahrad",enderType="NPC",enderId=6707,wowhead="https://www.wowhead.com/wotlk/quest=6681",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N,$B$BRavenholdt has taken an interest in you, young thief. We have been watching. Your style is a bit awkward but nothing we couldn't fix.$B$BShould you be prepared to embark on a career as a disciple of Master Ravenholdt and member of the Assassin's League, you have only to bring the Seal of Ravenholdt (attached to this letter) to Ravenholdt Manor.$B$BYour first task is to find the manor, hidden away in the hills of Hillsbrad and demonstrate your cunning.$B$BRegards,$B$BFahrad",logDesc="Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.$B$BYour cunning will be tested along the way. Be prepared."} end
