if not DB[6721] then DB[6721]={id=6721,zoneId=1537,name="The Hunter's Path",level=-1,minLevel=10,giver="Regnus Thundergranite",giverType="NPC",giverId=5117,ender="Dazalar",enderType="NPC",enderId=3601,rewardNextId=6063,poiX=-5007,poiY=-1266,wowhead="https://www.wowhead.com/wotlk/quest=6721",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.$B",logDesc="Speak with Dazalar at Dolanaar in Teldrassil."} end
if not DB[6722] then DB[6722]={id=6722,zoneId=131,name="The Hunter's Path",level=-1,minLevel=10,giver="Einris Brightspear",giverType="NPC",giverId=5515,ender="Dazalar",enderType="NPC",enderId=3601,rewardNextId=6063,poiX=-8415,poiY=553,wowhead="https://www.wowhead.com/wotlk/quest=6722",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.",logDesc="Speak with Dazalar at Dolanaar in Teldrassil."} end
if not DB[6741] then DB[6741]={id=6741,zoneId=2597,name="More Booty!",level=-1,minLevel=51,giver="Smith Regzar",giverType="NPC",giverId=13176,ender="Smith Regzar",enderType="NPC",enderId=13176,wowhead="https://www.wowhead.com/wotlk/quest=6741",image="assets/images/quests/placeholder.png"} end
if not DB[6761] then DB[6761]={id=6761,zoneId=1657,name="The New Frontier",level=55,minLevel=54,giver="Arch Druid Fandral Staghelm",giverType="NPC",giverId=3516,ender="Mathrengyl Bearwalker",enderType="NPC",enderId=4217,rewardNextId=6762,poiX=10173,poiY=2570,wowhead="https://www.wowhead.com/wotlk/quest=6761",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I have relegated my second, Mathrengyl Bearwalker, to deal with Moonglade's call for aid.  Speak to him on this matter - NOT me.$B$BLet me give you some... friendly... advice.  It is I who led us out of the darkness - NOT the Cenarion Circle in Moonglade - when all was lost for our race.  Teldrassil gives us all new life!  They would have you believe otherwise, and to believe their propaganda would be a fool's task.$B$BI'll leave it to you to decide whether or not you're a fool.",logDesc="Speak with Mathrengyl Bearwalker at the Cenarion Enclave of Darnassus."} end
if not DB[6762] then DB[6762]={id=6762,zoneId=1657,name="Rabine Saturna",level=55,minLevel=54,giver="Mathrengyl Bearwalker",giverType="NPC",giverId=4217,ender="Rabine Saturna",enderType="NPC",enderId=11801,rewardNextId=1124,poiX=10179,poiY=2564,wowhead="https://www.wowhead.com/wotlk/quest=6762",image="assets/images/quests/placeholder.png",xpDiff=2,desc="For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris... and even further west of Un'Goro.  You should find him in Nighthaven, the main village of Moonglade.$B$BWhile your work will no doubt be of tremendous benefit to us all, I advise you to tread gingerly.  There are tensions between Darnassus and Moonglade... ones that may grow over the course of time.",logDesc="Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold."} end
