if not DB[6801] then DB[6801]={id=6801,zoneId=2597,name="Lokholar the Ice Lord",level=-1,minLevel=51,giver="Primalist Thurloga",giverType="NPC",giverId=13236,ender="Primalist Thurloga",enderType="NPC",enderId=13236,wowhead="https://www.wowhead.com/wotlk/quest=6801",image="assets/images/quests/placeholder.png"} end
if not DB[6804] then DB[6804]={id=6804,zoneId=16,name="Poisoned Water",level=56,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=6804",image="assets/images/quests/placeholder.png",xpDiff=4,desc="A force of elemental scouts was sent to the eastern plaguelands of Lordaeron, and the disease of that place twisted and infected them.  The Waterlords cannot allow this affront to our purity!$B$BTake this vial.  In it is a quantity of one aspect of Neptulon.  If used on the plagued elementals it will fight the poison within their bodies and cure them!  But their inner conflict will drive them into a surging madness.$B$BDefeat the discordant surges and bring me their bracers of binding.",logDesc="Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands.  Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara."} end
if not DB[6805] then DB[6805]={id=6805,zoneId=16,name="Stormers and Rumblers",level=57,minLevel=55,giver="Duke Hydraxis",giverType="NPC",giverId=13278,ender="Duke Hydraxis",enderType="NPC",enderId=13278,poiX=2850,poiY=-7297,wowhead="https://www.wowhead.com/wotlk/quest=6805",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We, the elementals of water, wage war with those beings of the lesser elements.  If you are truly our ally in this conflict, then show me your conviction!$B$BFar to the south, in the desert land of Silithus, the servants of air and earth scurry in a corner of rock named the Crystal Vale.  They protect items of power from smaller beings, mortals, and although I do not know why they do this, I wish to foil their efforts.$B$BGo to the Crystal Vale in Silithus and defeat our enemies, then return to me.",logDesc="Kill 15 Dust Stormers and 15 Desert Rumblers and then return to Duke Hydraxis in Azshara."} end
if not DB[6821] then DB[6821]={id=6821,zoneId=16,name="Eye of the Emberseer",level=60,minLevel=55,giver="Duke Hydraxis",giverType="NPC",giverId=13278,ender="Duke Hydraxis",enderType="NPC",enderId=13278,rewardNextId=6822,poiX=2850,poiY=-7297,wowhead="https://www.wowhead.com/wotlk/quest=6821",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You have shown me that you can defeat our enemies and perform missions to further the cause of the Waterlords.  But until now you have only faced lesser foes... if pitted against a powerful enemy, can you prevail?$B$BThat is your new task.$B$BHigh up in Blackrock Spire the orcs have captured a servant of fire, the Pyroguard Emberseer.  Find his place of imprisonment, slay his captors, and then slay the emberseer.  Bring me his eye and it will show me your worth.",logDesc="Bring the Eye of the Emberseer to Duke Hydraxis in Azshara."} end
if not DB[6822] then DB[6822]={id=6822,zoneId=16,name="The Molten Core",level=60,minLevel=55,giver="Duke Hydraxis",giverType="NPC",giverId=13278,ender="Duke Hydraxis",enderType="NPC",enderId=13278,rewardNextId=6823,poiX=2850,poiY=-7297,wowhead="https://www.wowhead.com/wotlk/quest=6822",image="assets/images/quests/placeholder.png",xpDiff=7,desc="$n, perhaps it is time to give you a real test.  Are you ready?$B$BAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.$B$BGo to the Molten Core, $N.  Show me you have the strength and the will to defeat what you find there.$B$BAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live.",logDesc="Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara."} end
if not DB[6823] then DB[6823]={id=6823,zoneId=16,name="Agent of Hydraxis",level=60,minLevel=55,giver="Duke Hydraxis",giverType="NPC",giverId=13278,ender="Duke Hydraxis",enderType="NPC",enderId=13278,rewardNextId=6824,poiX=2850,poiY=-7297,wowhead="https://www.wowhead.com/wotlk/quest=6823",image="assets/images/quests/placeholder.png",xpDiff=7,desc="If you truly wish an allegiance with us, then I invite you to wage war on our foes, the servants of air and earth and fire.  Each defeat you heap upon them will weaken their foothold here, and further prove your adherence to our cause.$B$BThe campaign will be long, but if you persevere then your glory and honor will be great.",logDesc="Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara."} end
if not DB[6824] then DB[6824]={id=6824,zoneId=16,name="Hands of the Enemy",level=60,minLevel=55,giver="Duke Hydraxis",giverType="NPC",giverId=13278,ender="Duke Hydraxis",enderType="NPC",enderId=13278,poiX=2850,poiY=-7297,wowhead="https://www.wowhead.com/wotlk/quest=6824",image="assets/images/quests/placeholder.png",xpDiff=7,desc="$N, your service is of great value to us, so we are reluctant to send you on this last mission for we do not want to lose such a useful agent.$B$BBut its success would further our war efforts tremendously and... it was deemed worth risking you.$B$BWe want these captains in the Molten Core destroyed: Lucifron, Sulfuron, Gehennas and Shazzrah.  Kill them and bring me their hands!$B$BThis task will take every resource you possess, $N, but if can do it then the Firelords will be dealt a terrible blow.",logDesc="Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara."} end
