if not DB[6844] then DB[6844]={id=6844,zoneId=1377,name="Umber, Archivist",level=57,minLevel=54,giver="Layo Starstrike",giverType="NPC",giverId=13220,ender="Umber",enderType="NPC",enderId=11939,rewardNextId=6845,poiX=-6398,poiY=-314,wowhead="https://www.wowhead.com/wotlk/quest=6844",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There's plenty to do here still, but I think taking this back to the Circle for analysis is key.  Trust me - the work will still be here once this is all said and done.  If it's a journal inside this sticky chitin, then the Circle would finally have a window into the past!$B$BTake this to the Circle's archivist in Nighthaven.  His name is Umber, and the man's brilliant.  Touched, sure, but brilliant nonetheless!  Umber's salvaged tomes in far worse shape than this.  If it can be saved, he can do it.",logDesc="Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade."} end
if not DB[6845] then DB[6845]={id=6845,zoneId=493,name="Uncovering Past Secrets",level=57,minLevel=54,giver="Umber",giverType="NPC",giverId=11939,ender="Rabine Saturna",enderType="NPC",enderId=11801,poiX=7944,poiY=-2417,wowhead="https://www.wowhead.com/wotlk/quest=6845",image="assets/images/quests/placeholder.png",xpDiff=6,money=17000,desc="Anyway, you should check back with me relatively soon... that is if you want to know what was in here.  As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you.$B$BIn the meantime, I'd check in with the den mother of this little bear camp, Rabine.  No doubt he'll want to know what crazy antics you've been up to.  Never leave the den mother waiting, $N... that is, unless you want to be doused in honey.$B$BIt's happened, trust me.",logDesc="Speak with Rabine Saturna in the village of Nighthaven, Moonglade.",choiceRewards={{id=18400,qty=1},{id=18402,qty=1}}} end
if not DB[6846] then DB[6846]={id=6846,zoneId=2597,name="Begin the Attack!",level=-1,minLevel=1,giver="Field Marshal Teravaine",giverType="NPC",giverId=13446,ender="Field Marshal Teravaine",enderType="NPC",enderId=13446,wowhead="https://www.wowhead.com/wotlk/quest=6846",image="assets/images/quests/placeholder.png"} end
if not DB[6847] then DB[6847]={id=6847,zoneId=2597,name="Master Ryson's All Seeing Eye",level=60,minLevel=51,giver="Syndicate Master Ryson",giverType="NPC",giverId=13151,ender="Syndicate Master Ryson",enderType="NPC",enderId=13151,wowhead="https://www.wowhead.com/wotlk/quest=6847",image="assets/images/quests/placeholder.png",desc="Your war in the heart of Alterac means nothing to the Syndicate, $c. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.$B$BThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.$B$BRecover the Eye and our services shall be yours - for whatever time remains for your side.$B$BReturn to me once you acquire the eye so that I may examine you.$B$B<Master Ryson grins.>",logDesc="Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.$B$BBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!"} end
if not DB[6848] then DB[6848]={id=6848,zoneId=2597,name="Master Ryson's All Seeing Eye",level=60,minLevel=50,giver="Syndicate Master Ryson",giverType="NPC",giverId=13151,ender="Syndicate Master Ryson",enderType="NPC",enderId=13151,wowhead="https://www.wowhead.com/wotlk/quest=6848",image="assets/images/quests/placeholder.png",desc="Your war in the heart of Alterac means nothing to the Syndicate, $c. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.$B$BThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.$B$BRecover the Eye and our services shall be yours - for whatever time remains for your side.$B$BReturn to me once you acquire the eye so that I may examine you.$B$B<Master Ryson grins.>",logDesc="Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.$B$BBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!"} end
if not DB[6861] then DB[6861]={id=6861,zoneId=2597,name="Zinfizzlex's Portable Shredder Unit",level=60,minLevel=51,giver="Master Engineer Zinfizzlex",giverType="NPC",giverId=13377,ender="Master Engineer Zinfizzlex",enderType="NPC",enderId=13377,wowhead="https://www.wowhead.com/wotlk/quest=6861",image="assets/images/quests/placeholder.png",desc="I'm as anxious as you are to try out my portable shredder unit, $r, but before I can make the kit, I'm going to need materials - lots of materials!$B$BTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.$B$BWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.",logDesc="Master Engineer Zinfizzlex wants you to bring him the following:$B$B*30 Thorium Bars.$B$B*50 Mithril Bars.$B$B*75 Iron bars.$B$B*1 Steamsaw.$B",rewards={{id=17384,qty=1}}} end
if not DB[6862] then DB[6862]={id=6862,zoneId=2597,name="Zinfizzlex's Portable Shredder Unit",level=60,minLevel=51,giver="Master Engineer Zinfizzlex",giverType="NPC",giverId=13377,ender="Master Engineer Zinfizzlex",enderType="NPC",enderId=13377,wowhead="https://www.wowhead.com/wotlk/quest=6862",image="assets/images/quests/placeholder.png",desc="I'm as anxious as you are to try out my portable shredder unit, $r, but before I can make the kit, I'm going to need materials - lots of materials!$B$BTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.$B$BWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.",logDesc="Master Engineer Zinfizzlex wants you to bring him the following:$B$B*30 Thorium Bars.$B$B*50 Mithril Bars.$B$B*75 Iron bars.$B$B*1 Steamsaw.$B",rewards={{id=17410,qty=1}}} end
