if not DB[6901] then DB[6901]={id=6901,zoneId=2597,name="Launch the Attack!",level=-1,minLevel=1,giver="Warmaster Garrick",giverType="NPC",giverId=13449,ender="Warmaster Garrick",enderType="NPC",enderId=13449,wowhead="https://www.wowhead.com/wotlk/quest=6901",image="assets/images/quests/placeholder.png"} end
if not DB[6921] then DB[6921]={id=6921,zoneId=719,name="Amongst the Ruins",level=27,minLevel=21,giver="Je'neu Sancrea",giverType="NPC",giverId=12736,ender="Je'neu Sancrea",enderType="NPC",enderId=12736,poiX=3355,poiY=1033,wowhead="https://www.wowhead.com/wotlk/quest=6921",image="assets/images/quests/placeholder.png",xpDiff=7,money=4500,desc="The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.$B$B$N, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!",logDesc="Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."} end
if not DB[6922] then DB[6922]={id=6922,zoneId=331,name="Baron Aquanis",level=30,minLevel=21,ender="Je'neu Sancrea",enderType="NPC",enderId=12736,wowhead="https://www.wowhead.com/wotlk/quest=6922",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.$B$BIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.",logDesc="Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",choiceRewards={{id=16886,qty=1},{id=16887,qty=1}}} end
if not DB[6941] then DB[6941]={id=6941,zoneId=2597,name="Call of Air - Vipore's Fleet",level=-1,minLevel=51,giver="Wing Commander Vipore",giverType="NPC",giverId=13439,ender="Wing Commander Vipore",enderType="NPC",enderId=13439,wowhead="https://www.wowhead.com/wotlk/quest=6941",image="assets/images/quests/placeholder.png"} end
