if not DB[6943] then DB[6943]={id=6943,zoneId=2597,name="Call of Air - Ichman's Fleet",level=-1,minLevel=51,giver="Wing Commander Ichman",giverType="NPC",giverId=13437,ender="Wing Commander Ichman",enderType="NPC",enderId=13437,wowhead="https://www.wowhead.com/wotlk/quest=6943",image="assets/images/quests/placeholder.png"} end
if not DB[6961] then DB[6961]={id=6961,zoneId=-22,name="Great-father Winter is Here!",level=-1,minLevel=10,giver="Kaymard Copperpinch",giverType="NPC",giverId=13418,ender="Great-father Winter",enderType="NPC",enderId=13445,poiX=1652,poiY=-4429,wowhead="https://www.wowhead.com/wotlk/quest=6961",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!$B$BAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",logDesc="Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar."} end
if not DB[6962] then DB[6962]={id=6962,zoneId=-22,name="Treats for Great-father Winter",level=-1,minLevel=10,giver="Great-father Winter",giverType="NPC",giverId=13445,ender="Great-father Winter",enderType="NPC",enderId=13445,poiX=1627,poiY=-4417,wowhead="https://www.wowhead.com/wotlk/quest=6962",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hey, can you do Greatfather Winter a favor, um, little $g boy : girl;?$B$BNot to needlessly talk about myself in the third person, but Greatfather Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Greatfather and fetch some for me?",logDesc="Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Orgrimmar.",rewards={{id=17727,qty=1}}} end
if not DB[6963] then DB[6963]={id=6963,zoneId=-22,name="Stolen Winter Veil Treats",level=-1,minLevel=30,giver="Kaymard Copperpinch",giverType="NPC",giverId=13418,ender="Strange Snowman",enderType="NPC",enderId=13636,rewardNextId=6983,poiX=1652,poiY=-4429,wowhead="https://www.wowhead.com/wotlk/quest=6963",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.$B$BWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains, and that's where our man went to look for it.$B$BSee if both are out there, safe and sound!",logDesc="Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains."} end
if not DB[6964] then DB[6964]={id=6964,zoneId=-22,name="The Reason for the Season",level=-1,minLevel=10,giver="Furmund",giverType="NPC",giverId=9550,ender="Sagorne Creststrider",enderType="NPC",enderId=13417,rewardNextId=7061,poiX=1663,poiY=-4394,wowhead="https://www.wowhead.com/wotlk/quest=6964",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Gifts, treats, presents... bah, I say!$B$BThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!$B$BIf you're interested in learning what the Feast is all about for yourself, ask Sagorne Creststrider.  I'm sure he'll be surprised that someone cares about history rather than getting presents.",logDesc="Speak with Sagorne Creststrider in the Valley of Wisdom of Orgrimmar about the Feast of Winter Veil."} end
if not DB[6981] then DB[6981]={id=6981,zoneId=718,name="The Glowing Shard",level=26,minLevel=15,ender="Falla Sagewind",enderType="NPC",enderId=8418,wowhead="https://www.wowhead.com/wotlk/quest=6981",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.$B$BMaybe you should see if anyone in Ratchet can tell you more about this strange shard.",logDesc="Travel to Ratchet to find someone that can tell you more about the glowing shard.$B$BThen, deliver the shard as you are directed."} end
if not DB[6982] then DB[6982]={id=6982,zoneId=2597,name="Coldtooth Supplies",level=-1,minLevel=51,giver="Stormpike Quartermaster",giverType="NPC",giverId=12096,ender="Stormpike Quartermaster",enderType="NPC",enderId=12096,wowhead="https://www.wowhead.com/wotlk/quest=6982",image="assets/images/quests/placeholder.png",money=62000,desc="The Coldtooth mine is a storage depot for the Horde.  I can't stomach the food they give their troops, and the state of their arms and armor is atrocious!  But... in times like these when supplies are so important, we can use what they have.$B$BEnter the Coldtooth mine and bring me back their supplies.  That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors.$B$BGood luck, $N.  The mine is to the distant south, deep in Horde territory.",logDesc="Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar."} end
if not DB[6983] then DB[6983]={id=6983,zoneId=-22,name="You're a Mean One...",level=-1,minLevel=30,giver="Strange Snowman",giverType="NPC",giverId=13636,ender="Kaymard Copperpinch",enderType="NPC",enderId=13418,rewardNextId=6984,poiX=147,poiY=-209,wowhead="https://www.wowhead.com/wotlk/quest=6983",image="assets/images/quests/placeholder.png",xpDiff=3,desc="A c-c-creature called \"The Abominable Greench\" is the one w-w-who stole our shipment of t-t-treats, $N.  Be c-c-careful though!  He is t-t-the one who turned me into this s-s-snowy mess!$B$BYou're g-g-gonna need some help in f-f-facing him.  I've seen him w-w-wander all around where the y-y-yeti are; he's s-s-surely here s-s-somewhere!  F-f-find the treats $N, take them b-b-back to Smokywood Pastures in Orgrimmar, and t-t-tell them I n-n-need to be unfrozen!",logDesc="Locate and return the Stolen Treats to Kaymard Copperpinch in Orgrimmar.  It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains."} end
if not DB[6984] then DB[6984]={id=6984,zoneId=-22,name="A Smokywood Pastures' Thank You!",level=-1,minLevel=30,giver="Kaymard Copperpinch",giverType="NPC",giverId=13418,ender="Great-father Winter",enderType="NPC",enderId=13445,poiX=1652,poiY=-4429,wowhead="https://www.wowhead.com/wotlk/quest=6984",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We at Smokywood Pastures appreciate the recovery of the stolen treats, $N.  For that, we'd like to offer you a special gift... presented by none other than Great-father Winter himself!$B$BPlease, speak with Great-father Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!",logDesc="Speak with Great-father Winter in Orgrimmar.",rewards={{id=17726,qty=1}}} end
if not DB[6985] then DB[6985]={id=6985,zoneId=2597,name="Irondeep Supplies",level=-1,minLevel=51,giver="Frostwolf Quartermaster",giverType="NPC",giverId=12097,ender="Frostwolf Quartermaster",enderType="NPC",enderId=12097,wowhead="https://www.wowhead.com/wotlk/quest=6985",image="assets/images/quests/placeholder.png",money=74000,desc="The Stormpike dwarves are using the Irondeep mine as a storage depot.  I want you to raid that mine and bring me its supplies.  This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment!$B$BBe wary, $N.  The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.",logDesc="Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep."} end
if not DB[7001] then DB[7001]={id=7001,zoneId=2597,name="Empty Stables",level=-1,minLevel=51,giver="Frostwolf Stable Master",giverType="NPC",giverId=13616,ender="Frostwolf Stable Master",enderType="NPC",enderId=13616,wowhead="https://www.wowhead.com/wotlk/quest=7001",image="assets/images/quests/placeholder.png",desc="The war in the valley has taken its toll on our soldiers. We must revitalize our forces!$B$BIf we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle.$B$BTake this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable.$B$BWhen we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.",logDesc="Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master. Speak with the Frostwolf Stable Master to earn credit for the capture."} end
if not DB[7002] then DB[7002]={id=7002,zoneId=2597,name="Ram Hide Harnesses",level=-1,minLevel=51,giver="Frostwolf Wolf Rider Commander",giverType="NPC",giverId=13441,ender="Frostwolf Wolf Rider Commander",enderType="NPC",enderId=13441,wowhead="https://www.wowhead.com/wotlk/quest=7002",image="assets/images/quests/placeholder.png"} end
if not DB[7003] then DB[7003]={id=7003,zoneId=357,name="Zapped Giants",level=48,minLevel=45,giver="Zorbin Fandazzle",giverType="NPC",giverId=14637,ender="Zorbin Fandazzle",enderType="NPC",enderId=14637,poiX=-4379,poiY=2327,wowhead="https://www.wowhead.com/wotlk/quest=7003",image="assets/images/quests/placeholder.png",xpDiff=5,money=7000,desc="I'm going to have to do something about the giants if I stay out here!  They're certainly not good for business, now are they?$B$BI've been working on a variant of a gnomish shrinking ray, but I'm using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I'd like for you to try it out on any of the giants in Feralas.  You should find miniaturization residue on them after you shrink them - bring me back some!",logDesc="Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form.  Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.",rewards={{id=19040,qty=1}}} end
if not DB[7021] then DB[7021]={id=7021,zoneId=-22,name="Great-father Winter is Here!",level=-1,minLevel=10,giver="Whulwert Copperpinch",giverType="NPC",giverId=13431,ender="Great-father Winter",enderType="NPC",enderId=13445,poiX=-1235,poiY=73,wowhead="https://www.wowhead.com/wotlk/quest=7021",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!$B$BAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",logDesc="Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar."} end
if not DB[7022] then DB[7022]={id=7022,zoneId=-22,name="Greatfather Winter is Here!",level=-1,minLevel=10,giver="Wulmort Jinglepocket",giverType="NPC",giverId=13433,ender="Greatfather Winter",enderType="NPC",enderId=13444,poiX=-4924,poiY=-980,wowhead="https://www.wowhead.com/wotlk/quest=7022",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!$B$BAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",logDesc="Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge."} end
if not DB[7023] then DB[7023]={id=7023,zoneId=-22,name="Greatfather Winter is Here!",level=-1,minLevel=10,giver="Khole Jinglepocket",giverType="NPC",giverId=13435,ender="Greatfather Winter",enderType="NPC",enderId=13444,poiX=-8810,poiY=642,wowhead="https://www.wowhead.com/wotlk/quest=7023",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who's currently in Ironforge!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!$B$BAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",logDesc="Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge."} end
if not DB[7024] then DB[7024]={id=7024,zoneId=-22,name="Great-father Winter is Here!",level=-1,minLevel=10,giver="Nardstrum Copperpinch",giverType="NPC",giverId=13429,ender="Great-father Winter",enderType="NPC",enderId=13445,poiX=1629,poiY=218,wowhead="https://www.wowhead.com/wotlk/quest=7024",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!$B$BAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",logDesc="Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar."} end
if not DB[7025] then DB[7025]={id=7025,zoneId=-22,name="Treats for Greatfather Winter",level=-1,minLevel=10,giver="Greatfather Winter",giverType="NPC",giverId=13444,ender="Greatfather Winter",enderType="NPC",enderId=13444,poiX=-4914,poiY=-976,wowhead="https://www.wowhead.com/wotlk/quest=7025",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hey, can you do Greatfather Winter a favor, um, little $g boy : girl;?$B$BNot to needlessly talk about myself in the third person, but Greatfather Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Greatfather and fetch some for me?",logDesc="Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge.",rewards={{id=17727,qty=1}}} end
if not DB[7026] then DB[7026]={id=7026,zoneId=2597,name="Ram Riding Harnesses",level=-1,minLevel=51,giver="Stormpike Ram Rider Commander",giverType="NPC",giverId=13577,ender="Stormpike Ram Rider Commander",enderType="NPC",enderId=13577,wowhead="https://www.wowhead.com/wotlk/quest=7026",image="assets/images/quests/placeholder.png"} end
if not DB[7027] then DB[7027]={id=7027,zoneId=2597,name="Empty Stables",level=-1,minLevel=51,giver="Stormpike Stable Master",giverType="NPC",giverId=13617,ender="Stormpike Stable Master",enderType="NPC",enderId=13617,wowhead="https://www.wowhead.com/wotlk/quest=7027",image="assets/images/quests/placeholder.png",desc="Just look at the stables, $N! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct.$B$BYou must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable.$B$BWhen we have enough rams, the ram rider commander will be notifed. With your help, the cavalry will be reborn!",logDesc="Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture.$B"} end
if not DB[7028] then DB[7028]={id=7028,zoneId=2100,name="Twisted Evils",level=47,minLevel=41,giver="Willow",giverType="NPC",giverId=13656,ender="Willow",enderType="NPC",enderId=13656,poiX=-736,poiY=1437,wowhead="https://www.wowhead.com/wotlk/quest=7028",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it, $c. Relics of the old gods lie hidden behind the giant doors.$B$BIf you are willing to brave the twisted evils found in Maraudon, I believe I can make it worth your time. Collect the theradric crystal carvings you find, and return them to me.$B$BOnce I get the carvings, I will be able to... study them. These powers have been too long at rest... ",logDesc="Collect 15 Theradric Crystal Carvings for Willow in Desolace.",choiceRewards={{id=17775,qty=1},{id=17776,qty=1},{id=17777,qty=1},{id=17779,qty=1}}} end
if not DB[7029] then DB[7029]={id=7029,zoneId=2100,name="Vyletongue Corruption",level=47,minLevel=41,giver="Vark Battlescar",giverType="NPC",giverId=11823,ender="Vark Battlescar",enderType="NPC",enderId=11823,poiX=-1656,poiY=3190,wowhead="https://www.wowhead.com/wotlk/quest=7029",image="assets/images/quests/placeholder.png",xpDiff=7,desc="A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.$B$BTake this vial, $N. Fill it at the orange crystal pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.$B$BFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...",logDesc="Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.$B$BUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.$B$BHeal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.",choiceRewards={{id=17768,qty=1},{id=17778,qty=1},{id=17770,qty=1}}} end
if not DB[7041] then DB[7041]={id=7041,zoneId=2100,name="Vyletongue Corruption",level=47,minLevel=41,giver="Talendria",giverType="NPC",giverId=11715,ender="Talendria",enderType="NPC",enderId=11715,poiX=186,poiY=1154,wowhead="https://www.wowhead.com/wotlk/quest=7041",image="assets/images/quests/placeholder.png",xpDiff=7,desc="A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.$B$BTake this vial, $N. Fill it at the corrupted orange pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.$B$BFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...",logDesc="Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.$B$BUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.$B$BHeal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.",choiceRewards={{id=17768,qty=1},{id=17778,qty=1},{id=17770,qty=1}}} end
if not DB[7042] then DB[7042]={id=7042,zoneId=-22,name="Stolen Winter Veil Treats",level=-1,minLevel=30,giver="Macey Jinglepocket",giverType="NPC",giverId=13434,ender="Strange Snowman",enderType="NPC",enderId=13636,rewardNextId=7043,poiX=-4926,poiY=-979,wowhead="https://www.wowhead.com/wotlk/quest=7042",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.$B$BWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains, and that's where our man went to look for it.$B$BSee if both are out there, safe and sound!",logDesc="Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains."} end
if not DB[7043] then DB[7043]={id=7043,zoneId=-22,name="You're a Mean One...",level=-1,minLevel=30,giver="Strange Snowman",giverType="NPC",giverId=13636,ender="Wulmort Jinglepocket",enderType="NPC",enderId=13433,rewardNextId=7045,poiX=147,poiY=-209,wowhead="https://www.wowhead.com/wotlk/quest=7043",image="assets/images/quests/placeholder.png",xpDiff=3,desc="A c-c-creature called \"The Abominable Greench\" is the one w-w-who stole our shipment of t-t-treats, $N.  Be c-c-careful though!  He is t-t-the one who turned me into this s-s-snowy mess!$B$BYou're g-g-gonna need some help in f-f-facing him.  I've seen him w-w-wander all around where the y-y-yeti are; he's s-s-surely here s-s-somewhere!  F-f-find the treats $N, take them b-b-back to Smokywood Pastures in Ironforge, and t-t-tell them I n-n-need to be unfrozen!",logDesc="Locate and return the Stolen Treats to Wulmort Jinglepocket in Ironforge.  It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.$B"} end
if not DB[7044] then DB[7044]={id=7044,zoneId=2100,name="Legends of Maraudon",level=49,minLevel=41,giver="Cavindra",giverType="NPC",giverId=13697,ender="Celebras the Redeemed",enderType="NPC",enderId=13716,poiX=-1465,poiY=2790,wowhead="https://www.wowhead.com/wotlk/quest=7044",image="assets/images/quests/placeholder.png",xpDiff=7,desc="A dark satyr called Lord Vyletongue spread his evil through these twisting caves, poisoning the minds of all inside. He still resides beyond the purple crystals.$B$BVyletongue also created a living symbol of his corruption called Noxxion that dwells beyond the orange crystals. Together, they have stolen the two parts of my brother's scepter. Celebras, my brother... he wanders blindly inside, cursed by corruption.$B$BYou must help him! Find the pieces, and speak to my brother... somehow.",logDesc="Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.$B$BFind a way to speak with Celebras."} end
if not DB[7045] then DB[7045]={id=7045,zoneId=-22,name="A Smokywood Pastures' Thank You!",level=-1,minLevel=30,giver="Wulmort Jinglepocket",giverType="NPC",giverId=13433,ender="Greatfather Winter",enderType="NPC",enderId=13444,poiX=-4924,poiY=-980,wowhead="https://www.wowhead.com/wotlk/quest=7045",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We at Smokywood Pastures appreciate the recovery of the stolen treats, $N.  For that, we'd like to offer you a special gift... presented by none other than Greatfather Winter himself!$B$BPlease, speak with Greatfather Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!",logDesc="Speak with Greatfather Winter in Ironforge.",rewards={{id=17726,qty=1}}} end
if not DB[7046] then DB[7046]={id=7046,zoneId=2100,name="The Scepter of Celebras",level=49,minLevel=41,giver="Celebras the Redeemed",giverType="NPC",giverId=13716,ender="Celebras the Redeemed",enderType="NPC",enderId=13716,wowhead="https://www.wowhead.com/wotlk/quest=7046",image="assets/images/quests/placeholder.png",xpDiff=6,desc="My scepter was once a source of hope for me. It once granted me power over these caverns. I had hoped to bring peace to the spirit of my uncle...$B$BFor the two parts to once again become one, I will need your assistance in performing the ritual. Please follow me, and listen to my instructions while I channel the energy required to reunite the rod with the diamond.$B$BTogether, we shall create the Scepter of Celebras once again!",logDesc="Assist Celebras the Redeemed while he creates the Scepter of Celebras.$B$BSpeak with him when the ritual is complete.",rewards={{id=17191,qty=1}}} end
if not DB[7061] then DB[7061]={id=7061,zoneId=-22,name="The Feast of Winter Veil",level=-1,minLevel=10,giver="Sagorne Creststrider",giverType="NPC",giverId=13417,ender="Cairne Bloodhoof",enderType="NPC",enderId=3057,poiX=1938,poiY=-4223,wowhead="https://www.wowhead.com/wotlk/quest=7061",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a student of legends to appreciate the collection of all information into a single source.$B$BWhen you're done, take the book to Cairne Bloodhoof in Thunder Bluff.  I know for a fact he'd be interested in hearing that others have taken an interest in the lore of our people.  ",logDesc="Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to Cairne Bloodhoof in Thunder Bluff."} end
if not DB[7062] then DB[7062]={id=7062,zoneId=-22,name="The Reason for the Season",level=-1,minLevel=10,giver="Goli Krumn",giverType="NPC",giverId=1365,ender="Historian Karnik",enderType="NPC",enderId=2916,rewardNextId=7063,poiX=-4935,poiY=-955,wowhead="https://www.wowhead.com/wotlk/quest=7062",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Gifts, treats, presents... bah, I say!$B$BThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!$B$BIf you're interested in learning what the Feast is all about for yourself, ask Historian Karnik at the Explorer's League.  I'm sure he'll be surprised that someone cares about history rather than getting presents.",logDesc="Speak with Historian Karnik at the Explorer's League in Ironforge about the Feast of Winter Veil."} end
if not DB[7063] then DB[7063]={id=7063,zoneId=-22,name="The Feast of Winter Veil",level=-1,minLevel=10,giver="Historian Karnik",giverType="NPC",giverId=2916,ender="King Magni Bronzebeard",enderType="NPC",enderId=2784,poiX=-4632,poiY=-1327,wowhead="https://www.wowhead.com/wotlk/quest=7063",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a scholar to appreciate the collection of all information into a single source.$B$BWhen you're done, take the book to King Magni Bronzebeard.  I know for a fact he'd be interested in hearing that others have taken an interest in the older legends.  ",logDesc="Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to King Magni Bronzebeard in Ironforge."} end
if not DB[7064] then DB[7064]={id=7064,zoneId=2100,name="Corruption of Earth and Seed",level=51,minLevel=45,giver="Selendra",giverType="NPC",giverId=13699,ender="Selendra",enderType="NPC",enderId=13699,poiX=-1876,poiY=3025,wowhead="https://www.wowhead.com/wotlk/quest=7064",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship. The offspring of their time together became known to the people of Kalimdor as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now hold Zaetar's remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.",logDesc="Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.",choiceRewards={{id=17705,qty=1},{id=17743,qty=1},{id=17753,qty=1}}} end
if not DB[7065] then DB[7065]={id=7065,zoneId=2100,name="Corruption of Earth and Seed",level=51,minLevel=45,giver="Keeper Marandis",giverType="NPC",giverId=13698,ender="Keeper Marandis",enderType="NPC",enderId=13698,poiX=132,poiY=1364,wowhead="https://www.wowhead.com/wotlk/quest=7065",image="assets/images/quests/placeholder.png",xpDiff=7,desc="In the depths of Maraudon lives a creature of chaos and evil, $N. Princess Theradras is an elemental force of earth related somehow to the Old Gods. Ages ago, she was sought out by Zaetar, first son of Cenarius. The offspring of their... relationship are the creatures known as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now Theradras keeps his remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.",logDesc="Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.",choiceRewards={{id=17705,qty=1},{id=17743,qty=1},{id=17753,qty=1}}} end
if not DB[7066] then DB[7066]={id=7066,zoneId=2100,name="Seed of Life",level=51,minLevel=39,giver="Zaetar's Spirit",giverType="NPC",giverId=12238,ender="Keeper Remulos",enderType="NPC",enderId=11832,wowhead="https://www.wowhead.com/wotlk/quest=7066",image="assets/images/quests/placeholder.png",xpDiff=7,money=15000,desc="The misbegotten centaur--my sons and daughters--have need of their father.$B$BLook around you--this place rings of hope and all that my father Cenarius preaches. It sprung from me! And I cannot take that away from them... not even for their crimes against me.$B$BBut there is one thing I would ask of you to ease my brother's mind. Take this... it is the first seed that fell from the life my remains nourished. Tell him my spirit remains here, and that I live on. I am sure he will understand.",logDesc="Seek out Remulos in Moonglade and give him the Seed of Life."} end
if not DB[7067] then DB[7067]={id=7067,zoneId=2100,name="The Pariah's Instructions",level=48,minLevel=39,giver="Centaur Pariah",giverType="NPC",giverId=13717,ender="Centaur Pariah",enderType="NPC",enderId=13717,poiX=-2146,poiY=1966,wowhead="https://www.wowhead.com/wotlk/quest=7067",image="assets/images/quests/placeholder.png",xpDiff=7,money=14000,desc="Though exiled as a heretic, my beliefs still ring true--that alone drives me onward. But for my destiny to be complete, I need the aid of an outsider... one not of any centaur tribe.$B$BThe task requires someone to enter the holy halls of Maraudon--a tomb my people protect, and only the most devout are ever allowed to enter.$B$BIf you agree to aid me, then you need only nod. I will pass you a parchment with my instructions on it. Read it over and consider my words.",logDesc="Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.",rewards={{id=17774,qty=1}}} end
if not DB[7068] then DB[7068]={id=7068,zoneId=2100,name="Shadowshard Fragments",level=42,minLevel=39,giver="Uthel'nay",giverType="NPC",giverId=7311,ender="Uthel'nay",enderType="NPC",enderId=7311,poiX=1467,poiY=-4230,wowhead="https://www.wowhead.com/wotlk/quest=7068",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Strong magics be found in the centaur holy place... the holy place of Maraudon. The Desolace tribes of centaur protect that place wit' their lives, but they canna stop us from takin' what we need.$B$BYou, you head to this Maraudon place and find the rock creatures made of shadowshard. You bring me the purple crystals, and Uthel'nay make you somethin' for your time.$B$BThe place be dangerous, so maybe you be bringing some friends.",logDesc="Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.",choiceRewards={{id=17772,qty=1},{id=17773,qty=1}}} end
if not DB[7069] then DB[7069]={id=7069,zoneId=0,name="<UNUSED>",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=7069",image="assets/images/quests/placeholder.png",xpDiff=6} end
if not DB[7070] then DB[7070]={id=7070,zoneId=2100,name="Shadowshard Fragments",level=42,minLevel=39,giver="Archmage Tervosh",giverType="NPC",giverId=4967,ender="Archmage Tervosh",enderType="NPC",enderId=4967,poiX=-3757,poiY=-4462,wowhead="https://www.wowhead.com/wotlk/quest=7070",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I've recently begun testing various crystals and their arcane properties. Lady Proudmoore has given me leave to ask travelers heading into Desolace to seek out a place called Maraudon. Within the ruined temple are great elementals composed of purplish stones I've named shadowshards.$B$BIf you decide to head that direction and find some of the crystals, I would be very thankful. I could even fashion you a trinket from them if you so desired.",logDesc="Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.",choiceRewards={{id=17772,qty=1},{id=17773,qty=1}}} end
if not DB[7081] then DB[7081]={id=7081,zoneId=2597,name="Alterac Valley Graveyards",level=-1,minLevel=51,giver="Sergeant Durgen Stormpike",giverType="NPC",giverId=13777,ender="Sergeant Durgen Stormpike",enderType="NPC",enderId=13777,poiX=59,poiY=-246,wowhead="https://www.wowhead.com/wotlk/quest=7081",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The graveyards in Alterac Valley are prized territories.  Both the Horde and the Alliance fight savagely for these sacred grounds.  Are you, $N, ready to join that fight?$B$BI want you to assault an enemy graveyard.  Find a graveyard with a Horde banner in its midst, and pull it from the ground!  Do that, and your task will be complete....$B$BBut if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.",logDesc="Assault a graveyard, then return to Sergeant Durgen Stormpike in the Alterac Mountains."} end
if not DB[7082] then DB[7082]={id=7082,zoneId=2597,name="The Graveyards of Alterac",level=-1,minLevel=51,giver="Corporal Teeka Bloodsnarl",giverType="NPC",giverId=13776,ender="Corporal Teeka Bloodsnarl",enderType="NPC",enderId=13776,poiX=471,poiY=-1052,wowhead="https://www.wowhead.com/wotlk/quest=7082",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="The battle lines of Alterac Valley are ever shifting.  Territories swing back and forth as we meet our opponents in deadly combat.  And graveyards, $N, are where battles rage most fierce.$B$BI want you to attack an Alliance held graveyard!  Find a graveyard with an Alliance banner in its midst and pull it from the ground.$B$BDo that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.",logDesc="Assault a graveyard, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains."} end
if not DB[7101] then DB[7101]={id=7101,zoneId=2597,name="Towers and Bunkers",level=-1,minLevel=51,giver="Corporal Teeka Bloodsnarl",giverType="NPC",giverId=13776,ender="Corporal Teeka Bloodsnarl",enderType="NPC",enderId=13776,poiX=471,poiY=-1052,wowhead="https://www.wowhead.com/wotlk/quest=7101",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Towers and bunkers are important positions, and we must capture and hold them all!  So to that end, I want you to attack a bunker that is controlled by the enemy.$B$BTo do that, enter one with an Alliance banner.  You will see another banner inside.  Pull out that banner, and a white Horde banner will appear in its place.  Well done!$B$BAt that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!",logDesc="Capture an enemy tower, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains."} end
if not DB[7102] then DB[7102]={id=7102,zoneId=2597,name="Towers and Bunkers",level=-1,minLevel=51,giver="Sergeant Durgen Stormpike",giverType="NPC",giverId=13777,ender="Sergeant Durgen Stormpike",enderType="NPC",enderId=13777,poiX=59,poiY=-246,wowhead="https://www.wowhead.com/wotlk/quest=7102",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Towers and bunkers are key defensive positions, and so we must hold as many as possible!  I want you to attack a tower or a bunker in Alterac Valley.$B$BTo do that, enter a tower with a Horde banner atop it.  You will see another enemy banner inside.  Pull out that banner, and a white Alliance banner will appear in its place.  Well done!$B$BAt that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!",logDesc="Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Alterac Mountains."} end
if not DB[7121] then DB[7121]={id=7121,zoneId=2597,name="The Quartermaster",level=-1,minLevel=51,giver="Mountaineer Boombellow",giverType="NPC",giverId=13797,ender="Stormpike Quartermaster",enderType="NPC",enderId=12096,wowhead="https://www.wowhead.com/wotlk/quest=7121",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N, our quartermaster charged me to direct new recruits to him.  He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them.$B$BFollow the road.  You'll find our quartermaster to the west.",logDesc="Speak with the Stormpike Quartermaster."} end
if not DB[7122] then DB[7122]={id=7122,zoneId=2597,name="Capture a Mine",level=-1,minLevel=51,giver="Sergeant Durgen Stormpike",giverType="NPC",giverId=13777,ender="Sergeant Durgen Stormpike",enderType="NPC",enderId=13777,poiX=59,poiY=-246,wowhead="https://www.wowhead.com/wotlk/quest=7122",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="The mines in Alterac Valley hold more than just minerals.  Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them!$B$BCapture a mine, then return to me.  To capture a mine, enter one that we do not control and kill its leader.  When you do that, the mine will be ours, and we'll send troops to protect it!",logDesc="Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains."} end
if not DB[7123] then DB[7123]={id=7123,zoneId=2597,name="Speak with our Quartermaster",level=-1,minLevel=51,giver="Jotek",giverType="NPC",giverId=13798,ender="Frostwolf Quartermaster",enderType="NPC",enderId=12097,wowhead="https://www.wowhead.com/wotlk/quest=7123",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley.  Speak with him; he will tell you more.$B$BFollow the road west into the bunker, then take the west exit and you'll find our quartermaster.",logDesc="Speak with the Frostwolf Quartermaster."} end
if not DB[7124] then DB[7124]={id=7124,zoneId=2597,name="Capture a Mine",level=-1,minLevel=51,giver="Corporal Teeka Bloodsnarl",giverType="NPC",giverId=13776,ender="Corporal Teeka Bloodsnarl",enderType="NPC",enderId=13776,poiX=471,poiY=-1052,wowhead="https://www.wowhead.com/wotlk/quest=7124",image="assets/images/quests/placeholder.png",xpDiff=5,money=148000,desc="As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines.  Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued!$B$BHelp our war effort, $N!  Capture one of the mines for the Horde!  To capture a mine, enter one that we do not control and kill its leader.  When that is done, the mine will be ours and we'll send troops to protect it!",logDesc="Capture a mine, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains."} end
if not DB[7141] then DB[7141]={id=7141,zoneId=2597,name="The Battle of Alterac",level=-1,minLevel=51,giver="Prospector Stonehewer",giverType="NPC",giverId=13816,ender="Prospector Stonehewer",enderType="NPC",enderId=13816,poiX=15,poiY=-355,wowhead="https://www.wowhead.com/wotlk/quest=7141",image="assets/images/quests/placeholder.png",xpDiff=7,money=99000,desc="The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.$B$BDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.",logDesc="Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Alterac Mountains."} end
if not DB[7142] then DB[7142]={id=7142,zoneId=2597,name="The Battle for Alterac",level=-1,minLevel=51,giver="Voggah Deathgrip",giverType="NPC",giverId=13817,ender="Voggah Deathgrip",enderType="NPC",enderId=13817,poiX=371,poiY=-1004,wowhead="https://www.wowhead.com/wotlk/quest=7142",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!$B$BYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.$B$BDestroy him, $N, and then return to me.",logDesc="Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike.  Then, return to Voggah Deathgrip in the Alterac Mountains."} end
if not DB[7161] then DB[7161]={id=7161,zoneId=2597,name="Proving Grounds",level=-1,minLevel=51,giver="Warmaster Laggrond",giverType="NPC",giverId=13840,ender="Warmaster Laggrond",enderType="NPC",enderId=13840,poiX=401,poiY=-960,wowhead="https://www.wowhead.com/wotlk/quest=7161",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hail, $c. It has been a long time since we have had the chance to answer the call of battle. The old feelings are slow to rise but once awakened, the blood does rush. The battle rage returns...$B$BAll newcomers to the Valley must first complete the rite of battle.$B$BDeep within the Wildpaw gnoll cave is a banner of the Frostwolf. Venture forth and recover the banner. Return it to me and I shall grant you the Frostwolf initiate's insignia.",logDesc="Travel to the Wildpaw cavern located southeast of the main base in Alterac Valley and find the Frostwolf Banner. Return the Frostwolf Banner to Warmaster Laggrond. ",rewards={{id=17690,qty=1},{id=19483,qty=1}}} end
if not DB[7162] then DB[7162]={id=7162,zoneId=2597,name="Proving Grounds",level=-1,minLevel=51,giver="Lieutenant Haggerdin",giverType="NPC",giverId=13841,ender="Lieutenant Haggerdin",enderType="NPC",enderId=13841,poiX=-16,poiY=-322,wowhead="https://www.wowhead.com/wotlk/quest=7162",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You've arrived just in time, $c. These Frostwolf savages just won't give up! We must show them the might of the Stormpike. They must bow to our superiority.$B$BBefore you make your way to the field of battle, you will want to join the rank of Stormpike.$B$BSouthwest of Dun Baldar, you will find the Icewing Caverns. Planted deep within the caverns is a Stormpike Banner. Venture forth and recover that banner. Return it to me, and you will have earned a Stormpike initiate's insignia.",logDesc="Travel to the Icewing Caverns located southwest of Dun Baldar in Alterac Valley and recover the Stormpike Banner. Return the Stormpike Banner to Lieutenant Haggerdin in the Alterac Mountains.",rewards={{id=17691,qty=1},{id=19484,qty=1}}} end
