if not DB[7181] then DB[7181]={id=7181,zoneId=2597,name="The Legend of Korrak",level=60,minLevel=51,giver="Warmaster Laggrond",giverType="NPC",giverId=13840,ender="Warmaster Laggrond",enderType="NPC",enderId=13840,poiX=401,poiY=-960,wowhead="https://www.wowhead.com/wotlk/quest=7181",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power.$B$BThey are lead by Korrak the Bloodrager - a cruel and cunning beast.$B$BA strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!",logDesc="According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.$B$BShould Korrak make himself known, destroy him and return to Warmaster Laggrond.",rewards={{id=18149,qty=1}},choiceRewards={{id=19107,qty=1},{id=19106,qty=1},{id=19108,qty=1}}} end
if not DB[7201] then DB[7201]={id=7201,zoneId=1584,name="The Last Element",level=54,minLevel=48,giver="Shadowmage Vivian Lagrave",giverType="NPC",giverId=9078,ender="Shadowmage Vivian Lagrave",enderType="NPC",enderId=9078,poiX=-6682,poiY=-2151,wowhead="https://www.wowhead.com/wotlk/quest=7201",image="assets/images/quests/placeholder.png",xpDiff=7,money=24500,desc="There is work to be had for those venturing into the depths, $N.$B$BThe Dark Irons have mastered creation of extremely powerful golems.$B$BInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.$B$BJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.",logDesc="Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.$B",rewards={{id=12038,qty=1}}} end
if not DB[7202] then DB[7202]={id=7202,zoneId=2597,name="Korrak the Bloodrager",level=60,minLevel=51,giver="Lieutenant Haggerdin",giverType="NPC",giverId=13841,ender="Lieutenant Haggerdin",enderType="NPC",enderId=13841,poiX=-16,poiY=-322,wowhead="https://www.wowhead.com/wotlk/quest=7202",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew.$B$BWe must show them our might!$B$BWe have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager, tends to remain hidden until given a reason to make his presence known.$B$BDeath to Korrak would mean death to Winterax Clan! Slay him and return.",logDesc="According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.$B$BShould Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Alterac Mountains.",rewards={{id=18150,qty=1}},choiceRewards={{id=19107,qty=1},{id=19106,qty=1},{id=19108,qty=1}}} end
if not DB[7221] then DB[7221]={id=7221,zoneId=2597,name="Speak with Prospector Stonehewer",level=60,minLevel=51,rewardNextId=7141,wowhead="https://www.wowhead.com/wotlk/quest=7221",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Ah, $N, reporting for duty are you?  Great, the Stormpikes can use everyone we can muster!$B$BSpeak with Prospector Stonehewer in Dun Baldar.  She's recruiting for a vital mission into enemy territory.  You'll find Stonehewer in the bottom of the Dun Baldar garrison.$B$BAnd keep an eye out as you go through Dun Baldar.  There's plenty to do for a hardworking $c who's not afraid to get $ghis:her; hands dirty.",logDesc="Speak with Prospector Stonehewer in the Dun Baldar garrison."} end
if not DB[7222] then DB[7222]={id=7222,zoneId=2597,name="Speak with Voggah Deathgrip",level=60,minLevel=51,rewardNextId=7142,wowhead="https://www.wowhead.com/wotlk/quest=7222",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A $c?  Good!  We are glad to see you in Alterac, $N.  Interloping dwarves and their allies invade our valley, and we welcome all in the Horde to join us in righteous slaughter!$B$BSpeak with Voggah Deathgrip.  He is looking for agents for an important mission into the Alliance's stronghold in Alterac Valley!$B$BYou will find Voggah in Frostwolf Keep.",logDesc="Speak with Voggah in Frostwolf Keep."} end
if not DB[7223] then DB[7223]={id=7223,zoneId=2597,name="Armor Scraps",level=-1,minLevel=51,giver="Murgot Deepforge",giverType="NPC",giverId=13257,ender="Murgot Deepforge",enderType="NPC",enderId=13257,wowhead="https://www.wowhead.com/wotlk/quest=7223",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops.$B$BIf you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!",logDesc="Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar."} end
if not DB[7224] then DB[7224]={id=7224,zoneId=2597,name="Enemy Booty",level=-1,minLevel=51,giver="Smith Regzar",giverType="NPC",giverId=13176,ender="Smith Regzar",enderType="NPC",enderId=13176,wowhead="https://www.wowhead.com/wotlk/quest=7224",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When you fight the enemy, gather the scraps of their armor and bring them to me.  I'll use those scraps to make armor for our own troops!",logDesc="Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village."} end
if not DB[7241] then DB[7241]={id=7241,zoneId=2597,name="In Defense of Frostwolf",level=-1,minLevel=51,giver="Frostwolf Ambassador Rokhstrom",giverType="NPC",giverId=13842,ender="Warmaster Laggrond",enderType="NPC",enderId=13840,poiX=1608,poiY=-4376,wowhead="https://www.wowhead.com/wotlk/quest=7241",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The drums of war sound off in a distant land, $c. The favored clan of your Warchief is under attack from the nefarious Stormpike Guard of Ironforge.$B$BBy the looks of you, I can discern that you are indeed battle hardy and prepared to take on the cause of the Frostwolf.$B$BIt is you who must now take the next step in your evolution.$B$BNorth of Tarren Mill, in Alterac,  you will find the entrance to Alterac Valley. It is there that you will find Warmaster Laggrond. Hurry $c, for the battle is upon us!",logDesc="Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains."} end
if not DB[7261] then DB[7261]={id=7261,zoneId=2597,name="The Sovereign Imperative",level=-1,minLevel=51,giver="Lieutenant Rotimer",giverType="NPC",giverId=13843,ender="Lieutenant Haggerdin",enderType="NPC",enderId=13841,poiX=-4903,poiY=-968,wowhead="https://www.wowhead.com/wotlk/quest=7261",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We are fighting a brutal battle in the valleys of Alterac. The savage Frostwolf Clan challenges the might of the Stormpike! They must be exterminated in the name of King Magni Bronzebeard! The taking, culling, and turning of that land is a sovereign and territorial imperative to the kingdom of Ironforge.$B$BAlas, soldiers do not grow on trees! Report to Lieutenant Haggerdin outside Alterac Valley to begin your tour of duty and honor amongst the Stormpike.",logDesc="Travel to Alterac Valley in the Hillsbrad Foothills. Outside of the entrance tunnel, find and speak with Lieutenant Haggerdin.$B$BFor the glory of Bronzebeard!"} end
if not DB[7281] then DB[7281]={id=7281,zoneId=2597,name="Brotherly Love",level=-1,minLevel=51,wowhead="https://www.wowhead.com/wotlk/quest=7281",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Tragic... My brother faces me on the field of battle: A commander for the Stormpike.$B$BOf the four Stormpike Commanders, he is undoubtedly the most dangerous. Perhaps if he is slain, the Banshee Queen could turn him as she did me - show him the error of his ways...$B$BDeep within enemy territory you will find my brother. Slay him and return to me. I trust that you are capable of completing this mission, soldier.$B$BAnd soldier, do not go alone.",logDesc="Travel into Stormpike territory and slay Commander Karl Philips. Return to Commander Louis Philips when the task is complete.$B"} end
if not DB[7282] then DB[7282]={id=7282,zoneId=2597,name="Brotherly Love",level=-1,minLevel=51,wowhead="https://www.wowhead.com/wotlk/quest=7282",image="assets/images/quests/placeholder.png",xpDiff=5,desc="He must be put out of his misery, soldier! He knows not what he does. He has become a mindless servant of the dreaded Banshee Queen.$B$BVenture forth, across the Field of Strife, to the depths of Frostwolf territory. Find my brother and destroy him. His torment must come to an end.",logDesc="Travel into Frostwolf territory and slay Commander Louis Philips. Return to Commander Karl Philips when the task is complete.$B"} end
if not DB[7301] then DB[7301]={id=7301,zoneId=2597,name="Fallen Sky Lords",level=-1,minLevel=51,wowhead="https://www.wowhead.com/wotlk/quest=7301",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We got them held prisoner, $r. I'm talking about their Wing Commanders. It was a furious battle in the skies but they finally fell! Unfortunately, our best pilots were shot down in a counterattack against Frostwolf Keep. You gotta find out what happened to them.$B$BSearch Tower Point West and Frostwolf Keep. These were their last known locations. Search these areas thoroughly.",logDesc="Travel to Frostwolf territory and search for Wing Commander Slidore, Wing Commander Vipore, and Wing Commander Ichman. Return to Commander Duffy should you complete your mission."} end
if not DB[7302] then DB[7302]={id=7302,zoneId=2597,name="Fallen Sky Lords",level=-1,minLevel=51,wowhead="https://www.wowhead.com/wotlk/quest=7302",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Our air support is in shambles, $N. The Wing Commanders were shot down over enemy territory. You must find out what became of them so that we can attempt a rescue!$B$BGuse was last seen flying over the Icewing Bunker. Jeztor's War Rider was spotted near the Stormpike lumber mill. Mulverick... that reckless fool was seen crashing near the Dun'Baldar North Bunker.$B$BThat's all the information I have. Move out! Search through the areas thoroughly.",logDesc="Find out what became of Wing Commander Guse, Wing Commander Jeztor, and Wing Commander Mulverick. Return to Commander Mulfort should you complete your mission."} end
if not DB[7321] then DB[7321]={id=7321,zoneId=-304,name="Soothing Turtle Bisque",level=31,minLevel=28,giver="Christoph Jeffcoat",giverType="NPC",giverId=2393,ender="Christoph Jeffcoat",enderType="NPC",enderId=2393,poiX=-6,poiY=-927,wowhead="https://www.wowhead.com/wotlk/quest=7321",image="assets/images/quests/placeholder.png",xpDiff=5,money=3000,desc="Who says that the undead don't know anything about cooking? Take my secret recipe for Turtle Bisque, for example. I've known folks that would come back from the dead just to enjoy a bowl! Heh, heh...$B$BSpeaking of which, I haven't been able to make any lately.  I used to head over to Lake Lordamere myself to hunt snapjaws, the nasty things, but I can't pull myself away from my work here.$B$BIf you bring me some Turtle Meat from the snapjaws, I'll show you how it's done!",logDesc="Bring 10 pieces of Turtle Meat to Christoph Jeffcoat in Tarren Mill.",rewards={{id=3737,qty=1},{id=3729,qty=3}}} end
if not DB[7341] then DB[7341]={id=7341,zoneId=1637,name="A Fair Trade",level=60,minLevel=52,giver="Bounty Hunter Kolark",giverType="NPC",giverId=14182,ender="Bounty Hunter Kolark",enderType="NPC",enderId=14182,poiX=2058,poiY=-4733,wowhead="https://www.wowhead.com/wotlk/quest=7341",image="assets/images/quests/placeholder.png",rewards={{id=18042,qty=200}}} end
if not DB[7342] then DB[7342]={id=7342,zoneId=1537,name="Arrows Are For Sissies",level=60,minLevel=52,giver="Artilleryman Sheldonore",giverType="NPC",giverId=14183,ender="Artilleryman Sheldonore",enderType="NPC",enderId=14183,poiX=-4842,poiY=-869,wowhead="https://www.wowhead.com/wotlk/quest=7342",image="assets/images/quests/placeholder.png",rewards={{id=18042,qty=200}}} end
if not DB[7361] then DB[7361]={id=7361,zoneId=2597,name="Favor Amongst the Darkspear",level=60,minLevel=200,giver="Najak Hexxen",giverType="NPC",giverId=14185,ender="Najak Hexxen",enderType="NPC",enderId=14185,wowhead="https://www.wowhead.com/wotlk/quest=7361",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="<Najak snarls.>$B$BBefore the night elves existed there was troll. It was from troll that the night elves came.$B$BTheir mutinous attacks against my people will not be tolerated. Staghelm seeks to wipe us out - to leave no trace of those that bore him and his ilk. It will not happen!$B$BFor every night elf that you slay and decapitate, Najak will grant you favor amongst the Darkspear. Word of your deeds will be spread across Kalimdor and the Eastern Kingdoms. Go now and serve the Darkspear!",logDesc="You have been tasked with slaying opposing night elf players in Alterac Valley.$B$BKill a night elf and return to Najak Hexxen at Frostwolf Keep with a Severed Night Elf Head."} end
if not DB[7362] then DB[7362]={id=7362,zoneId=2597,name="Ally of the Tauren",level=60,minLevel=200,giver="Ravak Grimtotem",giverType="NPC",giverId=14186,ender="Ravak Grimtotem",enderType="NPC",enderId=14186,wowhead="https://www.wowhead.com/wotlk/quest=7362",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="The Elder Crone has sent me to this warzone to research the other races. More specifically, I am to collect gnome samples. Magatha is primarily interested in their survivability. Aye, the gnomes - while pitifully weak and miniscule - exude great resilience both in and out of combat.$B$BFortunately for you, I am looking for ruffians to do Magatha's bidding. Return to me with tufts of gnome hair and you shall be known to the tauren as an ally.",logDesc="You have been tasked with slaying opposing gnome players in Alterac Valley.$B$BKill a gnome and return to Ravak Grimtotem at Frostwolf Keep with a Tuft of Gnome Hair."} end
if not DB[7363] then DB[7363]={id=7363,zoneId=2597,name="The Human Condition",level=60,minLevel=200,wowhead="https://www.wowhead.com/wotlk/quest=7363",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="Humans are so utterly detestable.$B$B<Commander Philips grimaces.>$B$BWhile it is true that I am a soldier of Frostwolf, I remain a servant of Sylvanas.$B$BDuring my tour of duty, I do extra work on the side for the Dark Apothecaries of the Undercity.$B$BI have been tasked with collecting human bone chips that are to be used in curing the human condition.$B$BI am authorized to pass that task on to my subordinates.$B$BFind them. Kill them. Return their bone chips to me.",logDesc="You have been tasked with slaying opposing human players in Alterac Valley.$B$BKill a human and return to Commander Louis Philips (who wanders between the front lines and Frostwolf keep) with a  Human Bone Chip.$B$BA cure for the human condition is close at hand!"} end
if not DB[7364] then DB[7364]={id=7364,zoneId=2597,name="Gnomeregan Bounty",level=60,minLevel=200,wowhead="https://www.wowhead.com/wotlk/quest=7364",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="The High Tinkerer himself has sent me to this field of battle to defend my gnomish brothers and sisters. We have received word that the tauren are singling out and slaying gnomes. Worst of all, they are removing tufts of glorious gnome hair from the corpses of the fallen. These atrocities must be stopped. We must reciprocate!$B$BI want them de-hoofed, $c. Bring me their hooves! Show yourself as an ally of the gnomes.",logDesc="You have been tasked with slaying opposing tauren players in Alterac Valley.$B$BKill a tauren and return to Dirk Swindle at Dun'Baldar with a  Tauren Hoof."} end
if not DB[7365] then DB[7365]={id=7365,zoneId=2597,name="Staghelm's Requiem",level=60,minLevel=200,wowhead="https://www.wowhead.com/wotlk/quest=7365",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="Staghelm has given the order. All trolls on the field of battle must be exterminated. Their preposterous claims of birthing night elves must be met with force and due prejudice.$B$BSlay them and return to me with their mojo. To reiterate: I want you to steal their mojo.",logDesc="You have been tasked with slaying opposing troll players in Alterac Valley.$B$BKill a troll and return to Athramanis at Dun'Baldar with Darkspear Troll Mojo."} end
if not DB[7366] then DB[7366]={id=7366,zoneId=2597,name="The Archbishop's Mercy",level=60,minLevel=200,wowhead="https://www.wowhead.com/wotlk/quest=7366",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="The Archbishop is as kind as he is wise. For a man to look mercifully on such a wretched lot...$B$B<Commander Philips shakes his head in disbelief.>$B$BToo kind... Just too kind.$B$BThe Archbishop asks that we take pity on the undead and grant them swift and permanent deaths. For this grand display of mercy, we merely require their black, disease ridden hearts.$B$BBring me the hearts of the Forsaken so that they may be ceremoniously incinerated at the Cathedral of Light. Make haste, $N!",logDesc="You have been tasked with slaying opposing Forsaken players in Alterac Valley.$B$BKill a Forsaken and return to Commander Karl Philips (who wanders between the lumber mill and the mine) with a Forsaken Heart."} end
if not DB[7367] then DB[7367]={id=7367,zoneId=2597,name="Defusing the Threat",level=-1,minLevel=51,giver="Stormpike Explosives Expert",giverType="NPC",giverId=13598,ender="Stormpike Explosives Expert",enderType="NPC",enderId=13598,wowhead="https://www.wowhead.com/wotlk/quest=7367",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Frostwolf have their front lines and bases booby trapped, $c. You have to watch your step when invading enemy territory.$B$BIf you want to make a solid strike against them, you must destroy their source of anti personnel munitions - I'm talking about their explosives expert. If you kill him, you are safe to disarm the mines. As long as he is kept down, the mines will also stay down.$B$BYou will probably find him in a tower near the Iceblood Garrison. Good luck!",logDesc="Find the Frostwolf Explosives Expert and kill him. Return to the Stormpike Explosives Expert when the task is complete."} end
if not DB[7368] then DB[7368]={id=7368,zoneId=2597,name="Defusing the Threat",level=-1,minLevel=51,giver="Frostwolf Explosives Expert",giverType="NPC",giverId=13597,ender="Frostwolf Explosives Expert",enderType="NPC",enderId=13597,wowhead="https://www.wowhead.com/wotlk/quest=7368",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I know all about landmines. I'm the one that lays all the mines on the front lines here, after all.$B$BIf you want to defuse the Stormpike mine fields, all you have to do is kill their explosives expert. That dwarven coward is no doubt hiding in the first tower on the Field of Strife. Take him out and those landmines won't come back after they've been disarmed.$B$BIf you do happen to kill him, come back here and let me know. No good deed should go unrewarded.",logDesc="Find the Stormpike Explosives Expert and kill him. Return to the Frostwolf Explosives Expert when the task is complete."} end
if not DB[7381] then DB[7381]={id=7381,zoneId=2597,name="The Return of Korrak",level=60,minLevel=51,giver="Warmaster Laggrond",giverType="NPC",giverId=13840,ender="Warmaster Laggrond",enderType="NPC",enderId=13840,poiX=401,poiY=-960,wowhead="https://www.wowhead.com/wotlk/quest=7381",image="assets/images/quests/placeholder.png",desc="While it is true that Korrak has been slain, one question remains: Will he remain dead? Trolls are notorious for their other-worldly tribal magics. I would not be surprised if the fallen leader was raised from the dead to once more rule over his clan.$B$BYou know what to do should this ever occur.$B$B<Warmaster Laggrond makes a cutting motion across his neck with his index finger.>$B$BAnd  this time, I want his skull. Just keep your eyes peeled, soldier.$B$BDismissed!",logDesc="Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him.$B$BReturn the Skull of Korrak to Warmaster Laggrond in the Hillsbrad Foothills.",rewards={{id=18149,qty=1}}} end
if not DB[7382] then DB[7382]={id=7382,zoneId=2597,name="Korrak the Everliving",level=60,minLevel=50,giver="Lieutenant Haggerdin",giverType="NPC",giverId=13841,ender="Lieutenant Haggerdin",enderType="NPC",enderId=13841,poiX=-16,poiY=-322,wowhead="https://www.wowhead.com/wotlk/quest=7382",image="assets/images/quests/placeholder.png",desc="There's something not quite right about all of this... Did anybody think to burn Korrak's corpse? Those trolls will stop at nothing to revive their fallen leader - as blue skinned pagan man-beasts often do.$B$BJust keep your eyes out, $N. Don't be alarmed if Korrak makes a surprise appearance; and if he does, I want him executed - his corpse burned to ashes.$B$BFor good measure, lop off his head and bring me his skull before you ignite the lifeless mass.",logDesc="Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him.$B$BReturn the Skull of Korrak to Lieutenant Haggerdin in the Hillsbrad Foothills.$B",rewards={{id=18150,qty=1}}} end
if not DB[7383] then DB[7383]={id=7383,zoneId=141,name="Crown of the Earth",level=11,minLevel=1,giver="Corithras Moonrage",giverType="NPC",giverId=3515,ender="Corithras Moonrage",enderType="NPC",enderId=3515,rewardNextId=935,poiX=9737,poiY=956,wowhead="https://www.wowhead.com/wotlk/quest=7383",image="assets/images/quests/placeholder.png",xpDiff=4,desc="All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed.$b$bHowever, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.",logDesc="Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar."} end
if not DB[7384] then DB[7384]={id=7384,zoneId=-182,name="<nyi> <txt> The Scale Crafters",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=7384",image="assets/images/quests/placeholder.png",desc="Give me some scales.",logDesc="Collect some scales for Karana in the Harborage in Swamp of Sorrows."} end
if not DB[7385] then DB[7385]={id=7385,zoneId=2597,name="A Gallon of Blood",level=-1,minLevel=51,giver="Primalist Thurloga",giverType="NPC",giverId=13236,ender="Primalist Thurloga",enderType="NPC",enderId=13236,wowhead="https://www.wowhead.com/wotlk/quest=7385",image="assets/images/quests/placeholder.png"} end
if not DB[7386] then DB[7386]={id=7386,zoneId=2597,name="Crystal Cluster",level=-1,minLevel=51,giver="Arch Druid Renferal",giverType="NPC",giverId=13442,ender="Arch Druid Renferal",enderType="NPC",enderId=13442,wowhead="https://www.wowhead.com/wotlk/quest=7386",image="assets/images/quests/placeholder.png"} end
if not DB[7401] then DB[7401]={id=7401,zoneId=2597,name="Wanted: DWARVES!",level=60,minLevel=200,ender="Sergeant Yazra Bloodsnarl",enderType="NPC",enderId=13448,wowhead="https://www.wowhead.com/wotlk/quest=7401",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="By order of Sergeant Yazra Bloodsnarl, all dwarves on the field of battle are to be killed on sight.$B$BShould you slay a dwarf in combat, rip out their spine, leaving a spineless heap of stink and rot to serve as a warning to any and all that dare oppose the might of the Frostwolf.$B$BReturn to Sergeant Yazra Bloodsnarl with proof of your heroics.",logDesc="You have been tasked with slaying opposing Dwarf players in Alterac Valley.$B$BKill a Dwarf and rip out their spine. Take the Dwarf Spine to Sergeant Yazra Bloodsnarl at Frostwolf Keep."} end
if not DB[7402] then DB[7402]={id=7402,zoneId=2597,name="Wanted: ORCS!",level=60,minLevel=200,wowhead="https://www.wowhead.com/wotlk/quest=7402",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="By order of Corporal Noreg Stormpike, all able bodied soldiers of Stormpike are required to slay any opposing orcs that they meet upon the field of battle.$B$BSoldiers are required to remove a tusk or tooth from the maw of the enemy and present said tooth as proof of their accomplishment.$B$BWear protective gloves.",logDesc="You have been tasked with slaying opposing Orc players in Alterac Valley.$B$BKill an Orc and take their Orc Tooth back to Corporal Noreg Stormpike at Dun Baldar."} end
if not DB[7421] then DB[7421]={id=7421,zoneId=2597,name="Darkspear Defense",level=60,minLevel=200,wowhead="https://www.wowhead.com/wotlk/quest=7421",image="assets/images/quests/placeholder.png"} end
