if not DB[7441] then DB[7441]={id=7441,zoneId=2557,name="Pusillin and the Elder Azj'Tordin",level=58,minLevel=54,giver="Azj'Tordin",giverType="NPC",giverId=14355,ender="Azj'Tordin",enderType="NPC",enderId=14355,poiX=-4097,poiY=96,wowhead="https://www.wowhead.com/wotlk/quest=7441",image="assets/images/quests/placeholder.png",xpDiff=7,money=17500,desc="I had let my guard down for only one moment, stranger. In my haste to escape the grip of the fallen Prince, I was robbed. A most foul demon, the imp Pusillin, pilfered my book of incantations and the key to the once great halls of Eldre'Thalas.$B$BI no longer hold interest in the key, as I have exchanged my immortality for freedom, but I desperately need my book of incantations.$B$BFind the imp, Pusillin, and recover my book.$B$BSearch the Warpwood Quarter of Dire Maul for Pusillin.",logDesc="Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.$B$BReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.",choiceRewards={{id=18411,qty=1},{id=18410,qty=1}}} end
if not DB[7461] then DB[7461]={id=7461,zoneId=2557,name="The Madness Within",level=60,minLevel=56,giver="Shen'dralar Ancient",giverType="NPC",giverId=14358,ender="Shen'dralar Ancient",enderType="NPC",enderId=14358,rewardNextId=7877,poiX=14,poiY=390,wowhead="https://www.wowhead.com/wotlk/quest=7461",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Have you heard enough? Are you a $g man:woman; of action?$B$BThis madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced, attack and end him. Lay the spirits of this city to rest, adventurer.",logDesc="You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.$B$BEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.$B$BReturn to the Shen'dralar Ancient in the courtyard should you complete this quest."} end
if not DB[7462] then DB[7462]={id=7462,zoneId=2557,name="The Treasure of the Shen'dralar",level=60,minLevel=56,giver="Shen'dralar Ancient",giverType="NPC",giverId=14358,poiX=14,poiY=390,wowhead="https://www.wowhead.com/wotlk/quest=7462",image="assets/images/quests/placeholder.png",xpDiff=1,money=27000,desc="In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.",logDesc="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!",choiceRewards={{id=18420,qty=1},{id=18421,qty=1},{id=18424,qty=1}}} end
if not DB[7463] then DB[7463]={id=7463,zoneId=2557,name="Arcane Refreshment",level=-1,minLevel=60,giver="Lorekeeper Lydros",giverType="NPC",giverId=14368,ender="Lorekeeper Lydros",enderType="NPC",enderId=14368,poiX=164,poiY=523,wowhead="https://www.wowhead.com/wotlk/quest=7463",image="assets/images/quests/placeholder.png",xpDiff=7,desc="A $r mage! How wonderous. I have not seen one of your kind for... oh what is it going on now? 500 years!$B$BI have something that will quench your thirst, but first you must do a task for me.$B$B<Lydros snickers.>$B$BThere is an anomaly in Eldre'Thalas. A water elemental has taken residence in the east wing. His presence must be catalogued!$B$BVenture to the Warpwood Quarter and extract a portion of the elemental essence of the Hydrospawn. Return it to me and I shall teach you a useful cantrip.",logDesc="Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence."} end
if not DB[7481] then DB[7481]={id=7481,zoneId=2557,name="Elven Legends",level=60,minLevel=54,giver="Sage Korolusk",giverType="NPC",giverId=14373,ender="Sage Korolusk",enderType="NPC",enderId=14373,poiX=-4394,poiY=212,wowhead="https://www.wowhead.com/wotlk/quest=7481",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.$B$BOur search for this lost master lead us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.$B$BWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).$B$BYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!",logDesc="Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find."} end
if not DB[7482] then DB[7482]={id=7482,zoneId=2557,name="Elven Legends",level=60,minLevel=54,giver="Scholar Runethorn",giverType="NPC",giverId=14374,ender="Scholar Runethorn",enderType="NPC",enderId=14374,poiX=-4402,poiY=3275,wowhead="https://www.wowhead.com/wotlk/quest=7482",image="assets/images/quests/placeholder.png",xpDiff=7,money=18000,desc="Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.$B$BOur search for this lost master lead us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.$B$BWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).$B$BYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!",logDesc="Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find."} end
if not DB[7483] then DB[7483]={id=7483,zoneId=2557,name="Libram of Rapidity",level=60,minLevel=54,giver="Lorekeeper Lydros",giverType="NPC",giverId=14368,ender="Lorekeeper Lydros",enderType="NPC",enderId=14368,poiX=164,poiY=523,wowhead="https://www.wowhead.com/wotlk/quest=7483",image="assets/images/quests/placeholder.png",desc="Master Winthalus lost the Libram of Rapidity in the east wing. The Libram will allow for a minor haste cantrip to be placed upon your equipment. Parlor tricks, really...$B$BRegardless, if you are interested, you will need to present the Libram along with some basic reagents.$B$BHrm... I believe it also requires blood of heroes, a pristine black diamond, and large brilliant shards. I could be wrong!$B$B<Lydros shrugs.>",logDesc="Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.",rewards={{id=18329,qty=1}}} end
if not DB[7484] then DB[7484]={id=7484,zoneId=2557,name="Libram of Focus",level=60,minLevel=54,giver="Lorekeeper Lydros",giverType="NPC",giverId=14368,ender="Lorekeeper Lydros",enderType="NPC",enderId=14368,poiX=164,poiY=523,wowhead="https://www.wowhead.com/wotlk/quest=7484",image="assets/images/quests/placeholder.png",desc="This libram almost aroused interest in one of the younger Lorekeeper's familiars. Poor thing, it was only a few weeks old.$B$BThose among you who are more magically inclined might find this item interesting.$B$BThe Libram of Focus was lost in this wing. I can only assume one of the Highborne spirits holds it in their possession.$B$BBring the Libram along with some large brilliant shards, skin of shadow, and a pristine black diamond and I shall conjure the Arcanum.",logDesc="Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.",rewards={{id=18330,qty=1}}} end
if not DB[7485] then DB[7485]={id=7485,zoneId=2557,name="Libram of Protection",level=60,minLevel=54,giver="Lorekeeper Lydros",giverType="NPC",giverId=14368,ender="Lorekeeper Lydros",enderType="NPC",enderId=14368,poiX=164,poiY=523,wowhead="https://www.wowhead.com/wotlk/quest=7485",image="assets/images/quests/placeholder.png",desc="He wept like an infant at the loss of this libram. Mind you, I myself have wept over texts - there is no greater loss than that of knowledge and history - but to cry over this nearly useless jumbling of incantations? Preposterous! It left me to believe that the Prince was doing him a favor in flaying the flesh from his bones.$B$BBring the Libram along with a pristine black diamond, large brilliant shards, and a frayed abomination stitching and I shall recreate the Arcanum.$B$BOh, and check the north wing.",logDesc="Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.",rewards={{id=18331,qty=1}}} end
if not DB[7486] then DB[7486]={id=7486,zoneId=16,name="A Hero's Reward",level=60,minLevel=55,giver="Duke Hydraxis",giverType="NPC",giverId=13278,poiX=2850,poiY=-7297,wowhead="https://www.wowhead.com/wotlk/quest=7486",image="assets/images/quests/placeholder.png",xpDiff=7,desc="$N, your services to the Warlords surpassed all we could expect from the denizens of this world.$B$BWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.$B$BUnder the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward.$B$BGo, $N.  Claim your reward.",logDesc="Claim your reward from Hydraxis' Coffer.",choiceRewards={{id=18399,qty=1},{id=18398,qty=1}}} end
if not DB[7487] then DB[7487]={id=7487,zoneId=2717,name="Attunement to the Core",level=60,minLevel=55,giver="Lothos Riftwaker",giverType="NPC",giverId=14387,ender="Lothos Riftwaker",enderType="NPC",enderId=14387,poiX=-7509,poiY=-1040,wowhead="https://www.wowhead.com/wotlk/quest=7487",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Rifts stir, tear, and collapse all around us, $r. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.$B$BSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.$B$BI assure you, the portal is there and access is possible.$B$BI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.",logDesc="Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment."} end
if not DB[7488] then DB[7488]={id=7488,zoneId=2557,name="Lethtendris's Web",level=57,minLevel=54,giver="Latronicus Moonspear",giverType="NPC",giverId=7877,ender="Latronicus Moonspear",enderType="NPC",enderId=7877,poiX=-4506,poiY=3330,wowhead="https://www.wowhead.com/wotlk/quest=7488",image="assets/images/quests/placeholder.png",xpDiff=7,money=17000,desc="The mage Lethtendris, a vicious blood elf whose brutality is matched only by her twisted addiction to magic, has fled into Dire Maul.  She has created a device, a web to ensnare the magical energies of that place and we fear that, if left unchecked, she will cause irreparable damage to our world!$B$BStop her, $N.  Find her and retrieve her web.  She is likely near the satyrs in Warpwood Quarter of Dire Maul.  Bring the web to me so that its power may be released safely back into the wilds...",logDesc="Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.",rewards={{id=18491,qty=1}}} end
if not DB[7489] then DB[7489]={id=7489,zoneId=2557,name="Lethtendris's Web",level=57,minLevel=54,giver="Talo Thornhoof",giverType="NPC",giverId=7776,ender="Talo Thornhoof",enderType="NPC",enderId=7776,poiX=-4398,poiY=147,wowhead="https://www.wowhead.com/wotlk/quest=7489",image="assets/images/quests/placeholder.png",xpDiff=7,money=17000,desc="The blood elf Lethtendris has overstepped her bounds.  So eager was she to gather magical power that she defied her brethren and created a device of insidious design, a web meant to siphon the tainted magical energies of Dire Maul.  Even now she gathers those energies and plans to release them against her enemies.$B$BLethtendris must be stopped.  Find her within the Warpwood Quarter of Dire Maul, defeat her and bring her web to me so that it might be returned to more clear-headed blood elves for study.",logDesc="Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.",rewards={{id=18491,qty=1}}} end
if not DB[7490] then DB[7490]={id=7490,zoneId=1637,name="Victory for the Horde",level=60,minLevel=60,rewardNextId=7491,wowhead="https://www.wowhead.com/wotlk/quest=7490",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to your Warchief.",logDesc="Take the Head of Onyxia to Thrall in Orgrimmar."} end
if not DB[7491] then DB[7491]={id=7491,zoneId=1637,name="For All To See",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=7491",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Overlord Runthak awaits your arrival in the Valley of Strength.$B$B<Thrall salutes you.>$B$BDo not keep your public waiting, hero.",logDesc="Seek out Overlord Runthak in the Valley of Strength.",choiceRewards={{id=18406,qty=1},{id=18403,qty=1},{id=18404,qty=1}}} end
if not DB[7492] then DB[7492]={id=7492,zoneId=2557,name="Camp Mojache",level=57,minLevel=54,giver="Harbinger Balthazad",giverType="NPC",giverId=10879,ender="Talo Thornhoof",enderType="NPC",enderId=7776,rewardNextId=7489,poiX=1570,poiY=215,wowhead="https://www.wowhead.com/wotlk/quest=7492",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Talo Thornhoof, a Tauren elder in Feralas, sends a request for aid.  He offered few details, but he did say that he needs agents for a matter both delicate... and dire.$B$BServe the Horde, $N.  Go to Camp Mojache in Feralas and speak with Talo.",logDesc="Speak with Talo Thornhoof at Camp Mojache in Feralas."} end
if not DB[7493] then DB[7493]={id=7493,zoneId=1637,name="The Journey Has Just Begun",level=60,minLevel=60,giver="Overlord Runthak",giverType="NPC",giverId=14392,ender="Overlord Runthak",enderType="NPC",enderId=14392,poiX=1568,poiY=-4406,wowhead="https://www.wowhead.com/wotlk/quest=7493",image="assets/images/quests/placeholder.png"} end
if not DB[7494] then DB[7494]={id=7494,zoneId=2557,name="Feathermoon Stronghold",level=57,minLevel=54,giver="Crier Goodman",giverType="NPC",giverId=2198,ender="Latronicus Moonspear",enderType="NPC",enderId=7877,rewardNextId=7488,poiX=-8854,poiY=743,wowhead="https://www.wowhead.com/wotlk/quest=7494",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N!  Your aid is needed in Feralas!$B$BAn outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre'thalas, now called Dire Maul.  It is believed she has an item of dangerous magical energy which must be recovered.$B$BLatronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris.$B$BServe the Alliance!  Seek out Latronicus at the Feathermoon Stronghold in Feralas.",logDesc="Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas."} end
if not DB[7495] then DB[7495]={id=7495,zoneId=1519,name="Victory for the Alliance",level=60,minLevel=60,rewardNextId=7496,wowhead="https://www.wowhead.com/wotlk/quest=7495",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the King Varian Wrynn.",logDesc="Take the Head of Onyxia to King Varian Wrynn in Stormwind."} end
