if not DB[7507] then DB[7507]={id=7507,zoneId=2557,name="Foror's Compendium",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=7507",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have uncovered something of great importance. This book is unlike any that you have seen.$B$BIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible.",logDesc="Return Foror's Compendium of Dragon Slaying to the Athenaeum."} end
if not DB[7508] then DB[7508]={id=7508,zoneId=2557,name="The Forging of Quel'Serrar",level=60,minLevel=60,rewardNextId=7509,wowhead="https://www.wowhead.com/wotlk/quest=7508",image="assets/images/quests/placeholder.png",desc="If you wish to take on this task, present Lydros with the dull blade.",logDesc="Give the Dull and Flat Elven Blade to Lorekeeper Lydros."} end
if not DB[7509] then DB[7509]={id=7509,zoneId=2159,name="The Forging of Quel'Serrar",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=7509",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Take the unfired ancient blade to the lair of Onyxia and engage her in battle.$B$BSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.$B$BPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.",logDesc="You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.$B$BThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.$B$BDo this and Quel'Serrar will be yours.",rewards={{id=18348,qty=1}}} end
if not DB[7521] then DB[7521]={id=7521,zoneId=-344,name="Thunderaan the Windseeker",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=7521",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I have told you all that I know, $N. It is you who must find elementium. It is you who must destroy the Firelord's corporeal form.$B$BDo this and gain the blessing of Thunderaan.",logDesc="To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Wind Seeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian. "} end
if not DB[7522] then DB[7522]={id=7522,zoneId=-344,name="Examine the Vessel",level=1,minLevel=1,rewardNextId=7521,wowhead="https://www.wowhead.com/wotlk/quest=7522",image="assets/images/quests/placeholder.png",desc="Examine the vessel of his rebirth, mortal. It is from this that the Windseeker shall be reborn!",logDesc="Examine the Vessel of Rebirth and return it to Highlord Demitrian."} end
if not DB[7541] then DB[7541]={id=7541,zoneId=15,name="Service to the Horde",level=40,minLevel=30,giver="Zor Lonetree",giverType="NPC",giverId=4047,ender="Zor Lonetree",enderType="NPC",enderId=4047,poiX=1915,poiY=-4227,wowhead="https://www.wowhead.com/wotlk/quest=7541",image="assets/images/quests/placeholder.png",xpDiff=3,money=15000,choiceRewards={{id=18585,qty=1},{id=18586,qty=1}}} end
if not DB[7561] then DB[7561]={id=7561,zoneId=-344,name="Rise,Thunderfury!",level=60,minLevel=100,wowhead="https://www.wowhead.com/wotlk/quest=7561",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have defeated the Wind Seeker. Take the dormant blade and force the lying wretch,Demitrian,to use the materials you provided for his betrayal to wake Thunderfury.",logDesc="Present the Dormant Wind Kissed Blade to Highlord Demitrian.",rewards={{id=17802,qty=1}}} end
if not DB[7562] then DB[7562]={id=7562,zoneId=-61,name="Mor'zul Bloodbringer",level=-1,minLevel=60,giver="Spackle Thornberry",giverType="NPC",giverId=5520,ender="Mor'zul Bloodbringer",enderType="NPC",enderId=14436,rewardNextId=7563,poiX=-8975,poiY=1036,wowhead="https://www.wowhead.com/wotlk/quest=7562",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N, your delvings into the dark arts are deep.  Your mastery over otherworldly denizens has grown so strong... perhaps you are ready to bind to you one of the infamous dreadsteeds.$B$BThe ritual to summon the beast from its home requires great power and resources, but if you desire to dominate that epic mount, then speak with Mor'zul Bloodbringer.  He is camped near the Altar of Storms in the Burning Steppes.$B$BGo, $N.  This quest will be perilous, but a Warlock of your stature does not shy from danger!",logDesc="Speak with Mor'zul Bloodbringer at the Altar of Storms in the Burning Steppes."} end
if not DB[7563] then DB[7563]={id=7563,zoneId=-61,name="Rage of Blood",level=-1,minLevel=60,giver="Mor'zul Bloodbringer",giverType="NPC",giverId=14436,ender="Mor'zul Bloodbringer",enderType="NPC",enderId=14436,rewardNextId=7564,poiX=-7649,poiY=-638,wowhead="https://www.wowhead.com/wotlk/quest=7563",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The dreadsteeds dwell on another world, on the fiery Plains of Xoroth, and to bind one of those famed beasts you must invoke powerful glyphs.  I can scribe the glyphs on a parchment for you, but first I will need a special ink.$B$BIn distant Winterspring there dwells a race of owl beasts.  Once pure creatures, they were turned mad by the demonic emanations of the Darkwhisper Gorge and now roam the snows in a frenzy.$B$BTheir blood is what I need to ink your parchment.  Bring it to me.",logDesc="Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes."} end
if not DB[7564] then DB[7564]={id=7564,zoneId=-61,name="Wildeyes",level=-1,minLevel=60,giver="Mor'zul Bloodbringer",giverType="NPC",giverId=14436,ender="Gorzeeki Wildeyes",enderType="NPC",enderId=14437,poiX=-7649,poiY=-638,wowhead="https://www.wowhead.com/wotlk/quest=7564",image="assets/images/quests/placeholder.png",xpDiff=3,desc="My servant, Gorzeeki, is an alchemist of some skill.  He can prepare the ink I will need for your parchment.  I gathered together the blood you acquired; take it to Gorzeeki so that he can begin his work.",logDesc="Bring the Case of Blood to Gorzeeki Wildeyes at the Altar of Storms in the Burning Steppes."} end
if not DB[7581] then DB[7581]={id=7581,zoneId=-61,name="The Prison's Bindings",level=-1,minLevel=60,giver="Daio the Decrepit",giverType="NPC",giverId=14463,ender="Daio the Decrepit",enderType="NPC",enderId=14463,poiX=-11686,poiY=-2385,wowhead="https://www.wowhead.com/wotlk/quest=7581",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You must retrieve bindings for the prison of the Doomguard from lesser demons.$B$BThe blood of the Wildspawn satyr that occupy Dire Maul should do nicely. The coagulated blood will bond the Hederine shards and power the crystal prison.",logDesc="Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done.$B"} end
if not DB[7582] then DB[7582]={id=7582,zoneId=-61,name="The Prison's Casing",level=-1,minLevel=60,giver="Daio the Decrepit",giverType="NPC",giverId=14463,ender="Daio the Decrepit",enderType="NPC",enderId=14463,poiX=-11686,poiY=-2385,wowhead="https://www.wowhead.com/wotlk/quest=7582",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Hederine demons that occupy the foothills of Mount Hyjal secrete powerful fel poisons, which if left to mature, harden into a dense anti-magic crystal. These crystals have come to be known as Tears of the Hederine.$B$BNot even the immense power of a Doomguard could break the walls of a prison constructed from this material.$B$BTravel to Darkwhisper Gorge in Winterspring and recover the Tears.",logDesc="Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task."} end
if not DB[7583] then DB[7583]={id=7583,zoneId=-61,name="Suppression",level=-1,minLevel=60,giver="Daio the Decrepit",giverType="NPC",giverId=14463,ender="Daio the Decrepit",enderType="NPC",enderId=14463,poiX=-11686,poiY=-2385,wowhead="https://www.wowhead.com/wotlk/quest=7583",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The prison is ready. Now for the most difficult portion of this task.$B$BYou must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison.$B$BBe warned! A Doomguard is a cunning and lethal adversary and will seek to destroy you as you begin the ritual of imprisonment. It will flail wildly in its attempts to escape imprisonment.$B$BIt will focus on nothing but you, $N. Because of this, I must recommend that you take companions capable of keeping you alive!",logDesc="Venture forth into the Tainted Scar and locate a Doomguard Commander.$B$BUse the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.$B$BShould you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar.",rewards={{id=18602,qty=1}}} end
if not DB[7601] then DB[7601]={id=7601,zoneId=-61,name="What Niby Commands",level=-1,minLevel=50,giver="Niby the Almighty",giverType="NPC",giverId=14469,ender="Impsy",enderType="NPC",enderId=14470,rewardNextId=7602,poiX=5414,poiY=-738,wowhead="https://www.wowhead.com/wotlk/quest=7601",image="assets/images/quests/placeholder.png",desc="If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.$B$BMy imp, Impsy, shall set you on your way.",logDesc="Speak with Impsy in Felwood."} end
if not DB[7602] then DB[7602]={id=7602,zoneId=-61,name="Flawless Fel Essence",level=-1,minLevel=50,giver="Impsy",giverType="NPC",giverId=14470,ender="Impsy",enderType="NPC",enderId=14470,rewardNextId=7603,poiX=5408,poiY=-737,wowhead="https://www.wowhead.com/wotlk/quest=7602",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If you're going to reanimate Kroshius, you're going to need Fel fire. I can make Fel fire but it's going to require some components.$B$BYou need to bring me flawless Fel essences from three distinct regions of the world.$B$BThe Legashi Satyrs of Azshara will have the first essence type; the Jaedenar legionnaires of Jaedenar the second type and the felguard sentries of the Blasted Lands the third.$B$BBring me back one of each essence type and I will create the Fel fire, allowing you to reanimate Kroshius.",logDesc="Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.$B$BThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.$B$BRecover the Flawless Fel Essences and return  to Impsy in Felwood."} end
if not DB[7603] then DB[7603]={id=7603,zoneId=-61,name="Kroshius' Infernal Core",level=-1,minLevel=50,giver="Impsy",giverType="NPC",giverId=14470,ender="Niby the Almighty",enderType="NPC",enderId=14469,poiX=5408,poiY=-737,wowhead="https://www.wowhead.com/wotlk/quest=7603",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal.$B$BAt this point, I fully expect him to kill you and your minion.$B$BIf by some miracle you happen to kill Kroshius, take his infernal core and return it to Niby.",logDesc="Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.$B$BReturn Kroshius' Infernal Core to Niby the Almighty in Felwood.",rewards={{id=18762,qty=1}}} end
if not DB[7604] then DB[7604]={id=7604,zoneId=1584,name="A Binding Contract",level=60,minLevel=60,ender="Lokhtos Darkbargainer",enderType="NPC",enderId=12944,wowhead="https://www.wowhead.com/wotlk/quest=7604",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The undersigned hereby declares that the Sulfuron ingot they are delivering to the Thorium Brotherhood (TB Ltd.) is genuine and not a facsimile thereof. The undersigned also acknowledges that any harm that should come to $g him:her; as a result of attempting to build, forge, find, create, sell, or eat Sulfuras, is not the responsibility or fault of TB Ltd.$B$BBy signing this contract, you are agreeing to all terms listed herein.$B$B_________________$B$BSignature",logDesc="Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.",rewards={{id=18592,qty=1}}} end
if not DB[7621] then DB[7621]={id=7621,zoneId=-262,name="A Warning",level=60,minLevel=60,giver="Eris Havenfire",giverType="NPC",giverId=14494,ender="Eris Havenfire",enderType="NPC",enderId=14494,poiX=3325,poiY=-2997,wowhead="https://www.wowhead.com/wotlk/quest=7621",image="assets/images/quests/placeholder.png"} end
if not DB[7622] then DB[7622]={id=7622,zoneId=-262,name="The Balance of Light and Shadow",level=60,minLevel=60,giver="Eris Havenfire",giverType="NPC",giverId=14494,ender="Eris Havenfire",enderType="NPC",enderId=14494,poiX=3325,poiY=-2997,wowhead="https://www.wowhead.com/wotlk/quest=7622",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.$B$BThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.$B$BEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, $N.",logDesc="Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.$B$BYou may view the Death Post to view how many Peasants have been slain.",rewards={{id=18659,qty=1}}} end
if not DB[7623] then DB[7623]={id=7623,zoneId=-61,name="Lord Banehollow",level=-1,minLevel=60,giver="Gorzeeki Wildeyes",giverType="NPC",giverId=14437,ender="Lord Banehollow",enderType="NPC",enderId=9516,rewardNextId=7624,poiX=-7649,poiY=-631,wowhead="https://www.wowhead.com/wotlk/quest=7623",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Mor'zul says that you want to open a portal to Xoroth.  To do that, you'll need Xorothian stardust.  That's not easy to find on Azeroth!$B$BThere is one being who might have some: Lord Banehollow in Jaedenar, the seat of the Shadow Council!  Speak with him and he might part with the stardust.$B$BBut if you're going to Jaedenar, then you'll need to cloak yourself in the Shadow Council's own flavor of evil.  That will require some of my shadowy potions, and that will cost you...",logDesc="Purchase Shadowy Potions from Gorzeeki Wildeyes at the Altar of Storms in the Burning Steppes.$B$BUse the potions to travel through Jaedenar in Felwood, and speak with Lord Banehollow inside the Shadow Hold."} end
if not DB[7624] then DB[7624]={id=7624,zoneId=-61,name="Ulathek the Traitor",level=-1,minLevel=60,giver="Lord Banehollow",giverType="NPC",giverId=9516,ender="Lord Banehollow",enderType="NPC",enderId=9516,rewardNextId=7625,poiX=5431,poiY=-424,wowhead="https://www.wowhead.com/wotlk/quest=7624",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You wish to enter my good graces?  Then kill for me.$B$BMy servant, Ulathek, is pathetic how he grovels before me, all the while plotting with Lord Hel'nurath on Xoroth.  Hel'nurath plans to usurp my power here, and Ulathek is his spy...$B$BProve that you serve me and not my rivals.  Confront Ulathek in his quarters, in the Shadow Hold to the west.  Tell him that I know his secret and watch as fear grips him.  Then, bring me the traitor's heart!",logDesc="Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar."} end
if not DB[7625] then DB[7625]={id=7625,zoneId=-61,name="Xorothian Stardust",level=-1,minLevel=60,giver="Lord Banehollow",giverType="NPC",giverId=9516,ender="Gorzeeki Wildeyes",enderType="NPC",enderId=14437,rewardNextId=7629,poiX=5431,poiY=-424,wowhead="https://www.wowhead.com/wotlk/quest=7625",image="assets/images/quests/placeholder.png",xpDiff=5,desc="So you come to me seeking Xorothian stardust?  You wish to open a portal to Xoroth, the domain of Hel'nurath my rival?  Perhaps you plan to steal from him one of his precious dreadsteeds?$B$BVery well.  My servant Ur'dan has a supply of Xorothian stardust.  You may obtain it from him... if you can pay the price.",logDesc="Purchase Xorothian Stardust from Ur'dan inside the Shadow Hold at Jaedenar in Felwood.  Bring it to Gorzeeki Wildeyes in the Burning Steppes."} end
if not DB[7626] then DB[7626]={id=7626,zoneId=-61,name="Bell of Dethmoora",level=-1,minLevel=60,giver="Mor'zul Bloodbringer",giverType="NPC",giverId=14436,ender="Gorzeeki Wildeyes",enderType="NPC",enderId=14437,poiX=-7649,poiY=-638,wowhead="https://www.wowhead.com/wotlk/quest=7626",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A Bell of Dethmoora, named after the late warlock Dethmoora Darkeyes, is one of the three tools needed to create a Circle of Greater Summoning.  When properly atuned with the Wheel and the Candle, these items conduct vast stores of arcane power.$B$BMy servant Gorzeeki can construct such a bell, but to do so he will need a large supply of elixirs of shadow power.  Procure the elixirs from an alchemist and bring them to Gorzeeki.",logDesc="Bring 2 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes."} end
if not DB[7627] then DB[7627]={id=7627,zoneId=-61,name="Wheel of the Black March",level=-1,minLevel=60,giver="Mor'zul Bloodbringer",giverType="NPC",giverId=14436,ender="Gorzeeki Wildeyes",enderType="NPC",enderId=14437,poiX=-7649,poiY=-638,wowhead="https://www.wowhead.com/wotlk/quest=7627",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A Wheel of the Black March contains and directs the violent energies required for the Circle of Greater Summoning.  For Gozeeki to construct a wheel, he will need both large brilliant shards from an enchanter, and dark iron ore from a master miner.$B$BAcquire these and bring them to my servant.",logDesc="Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes."} end
if not DB[7628] then DB[7628]={id=7628,zoneId=-61,name="Doomsday Candle",level=-1,minLevel=60,giver="Mor'zul Bloodbringer",giverType="NPC",giverId=14436,ender="Gorzeeki Wildeyes",enderType="NPC",enderId=14437,poiX=-7649,poiY=-638,wowhead="https://www.wowhead.com/wotlk/quest=7628",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A Doomsday Candle stores fire and directs it at those who would disrupt your ritual.  When creating your Circle of Greater Summoning, if your candle is lit then any wayward demons will be burned by its flames!$B$BContaining that fire is not easy, and requires the essence within the scales of a black dragon.  Acquire those scales from a skinner and bring them to Gorzeeki Wildeyes.",logDesc="Bring 3 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes."} end
if not DB[7629] then DB[7629]={id=7629,zoneId=-61,name="Imp Delivery",level=-1,minLevel=60,giver="Gorzeeki Wildeyes",giverType="NPC",giverId=14437,ender="Gorzeeki Wildeyes",enderType="NPC",enderId=14437,poiX=-7649,poiY=-631,wowhead="https://www.wowhead.com/wotlk/quest=7629",image="assets/images/quests/placeholder.png",xpDiff=7,desc="There is one more process required for Mor'zul's parchment; I need paper infused with Xorothian stardust.  And... I'm afraid I can't do that here.  I don't have the equipment!$B$BThere is an alchemy lab, however, with everything needed.  It's in the Scholomance, on the isle of Caer Darrow in the Plaguelands.$B$BI can't make the trip, but here - take this jar.  There's an imp inside who is quite clever.  Let him out at the alchemy lab and he'll infuse the parchment.",logDesc="Bring the Imp in a Jar to the alchemy lab in the Scholomance.  After the parchment is created, return the jar to Gorzeeki Wildeyes."} end
if not DB[7630] then DB[7630]={id=7630,zoneId=-61,name="Arcanite",level=-1,minLevel=60,giver="Gorzeeki Wildeyes",giverType="NPC",giverId=14437,ender="Gorzeeki Wildeyes",enderType="NPC",enderId=14437,poiX=-7649,poiY=-631,wowhead="https://www.wowhead.com/wotlk/quest=7630",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now that the Bell, Wheel and Candle are made, I should make a black lodestone.  During your ritual, you'll need that lodestone to maintain the other ritual objects if they should fail.$B$BTo make the lodestone, I require arcanite.  Do you have any?  If not, then... you'll have to get the arcanite from an alchemist.$B$BReturn to me when you have the arcanite, and then I'll make the black lodestone.",logDesc="Bring 1 Arcanite Bar to Gorzeeki in the Burning Steppes."} end
if not DB[7631] then DB[7631]={id=7631,zoneId=-61,name="Dreadsteed of Xoroth",level=-1,minLevel=60,giver="Mor'zul Bloodbringer",giverType="NPC",giverId=14436,ender="Dreadsteed Spirit",enderType="NPC",enderId=14504,poiX=-7649,poiY=-638,wowhead="https://www.wowhead.com/wotlk/quest=7631",image="assets/images/quests/placeholder.png",xpDiff=7,desc="All the preparations are made.  Now, you must perform the ritual to create a Circle of Greater Summoning, then use the parchment infused with Xorothian stardust... to open a portal to Xoroth.$B$BI have written the instructions for the ritual onto a scroll.  Study it closely, for you must perform each step exactly if you wish to succeed.$B$BFortune to you, $N.  And may the souls of your enemies swiftly find their way into your shard pouch.",logDesc="Read Mor'zul's Instructions.  Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you."} end
if not DB[7632] then DB[7632]={id=7632,zoneId=-261,name="The Ancient Leaf",level=60,minLevel=60,ender="Vartrus the Ancient",enderType="NPC",enderId=14524,wowhead="https://www.wowhead.com/wotlk/quest=7632",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The epidermis of the leaf glows a bright green. The surface is extremely rugose, exposing several veins and wrinkles.$B$BIf you had to take a guess, you would say this leaf came from something ancient and powerful.$B$BMaybe you should find the original owner of this leaf?",logDesc="Find the owner of the Ancient Petrified Leaf. Good luck, $N; It's a big world."} end
if not DB[7633] then DB[7633]={id=7633,zoneId=-261,name="An Introduction",level=60,minLevel=60,giver="Vartrus the Ancient",giverType="NPC",giverId=14524,ender="Vartrus the Ancient",enderType="NPC",enderId=14524,wowhead="https://www.wowhead.com/wotlk/quest=7633",image="assets/images/quests/placeholder.png"} end
if not DB[7634] then DB[7634]={id=7634,zoneId=-261,name="Ancient Sinew Wrapped Lamina",level=60,minLevel=60,giver="Hastat the Ancient",giverType="NPC",giverId=14526,ender="Hastat the Ancient",enderType="NPC",enderId=14526,wowhead="https://www.wowhead.com/wotlk/quest=7634",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Greetings, $c. I am Hastat, Ancient of Lore. I hold knowledge lost eons ago.$B$BWith the proper binding, one of my leaves can serve as a quiver the likes of which has not been seen in 10,000 years. A quiver that when accompanied by a bow of Ancients, could grant untold powers.$B$BReturn here with sinew from an adult blue dragon and this quiver shall be yours.",logDesc="Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood.",rewards={{id=18714,qty=1}}} end
if not DB[7635] then DB[7635]={id=7635,zoneId=-261,name="A Proper String",level=60,minLevel=60,giver="Stoma the Ancient",giverType="NPC",giverId=14525,ender="Stoma the Ancient",enderType="NPC",enderId=14525,wowhead="https://www.wowhead.com/wotlk/quest=7635",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Vartrus may offer you the stave to create a bow of Ancients but only I can enchant the string required to complete the bow.$B$BIt is a simple task, puny one. Slay a mature black dragon and remove the sinew from its bones. Return that sinew to me and I shall enchant the material into an almost indestructible bow string.",logDesc="Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood.",rewards={{id=18724,qty=1}}} end
if not DB[7636] then DB[7636]={id=7636,zoneId=-261,name="Stave of the Ancients",level=60,minLevel=60,giver="Vartrus the Ancient",giverType="NPC",giverId=14524,ender="Vartrus the Ancient",enderType="NPC",enderId=14524,wowhead="https://www.wowhead.com/wotlk/quest=7636",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Agents of the Burning Legion are still active in our world, $c. These agents corrupt all that they touch. Nature wilts and weeps in their presence.$B$BYou must track down these demonic corrupters and destroy them, $N. Be warned, you must engage them by yourself or they will flee. As long as you are alone, they will try and destroy you. You must strike at them, turning their arrogance into misery.$B$BI grant you a piece of my bark, the inscriptions shall lead you to your targets. Retrieve their heads.",logDesc="You must find and destroy these four demonic corrupters:$B$BSimone the Seductress.$B$BKlinfran the Crazed.$B$BSolenor the Slayer.$B$BArtorius the Doombringer.$B$BDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.$B$BRefer to the Petrified Bark in your inventory for clues as to their whereabouts.$B$BYou MUST complete this task by yourself.",rewards={{id=18707,qty=1}}} end
if not DB[7637] then DB[7637]={id=7637,zoneId=-141,name="Emphasis on Sacrifice",level=-1,minLevel=60,giver="Lord Grayson Shadowbreaker",giverType="NPC",giverId=928,ender="High Priest Rohan",enderType="NPC",enderId=11406,rewardNextId=7639,poiX=-8577,poiY=882,wowhead="https://www.wowhead.com/wotlk/quest=7637",image="assets/images/quests/placeholder.png",xpDiff=1,desc="In order to prepare yourself for this task, you must first show due sacrifice and judgment... with an emphasis on sacrifice.$B$BYou must acquire High Priest Rohan's exorcism censer for your task.  Even though its use will be for good and just reasons, due compensation must be given for it.$B$BProceed to Ironforge and speak with the High Priest.  By bringing ample coin with you to help offset the loss of his censer, it will show your due sacrifice.$B$BGo now $N, time is of the essence.",logDesc="Travel to Ironforge and get High Priest Rohan's Exorcism Censer.  You will need to make a donation of 150 gold in order to secure it."} end
if not DB[7638] then DB[7638]={id=7638,zoneId=-141,name="Lord Grayson Shadowbreaker",level=-1,minLevel=60,giver="Duthorian Rall",giverType="NPC",giverId=6171,ender="Lord Grayson Shadowbreaker",enderType="NPC",enderId=928,poiX=-8546,poiY=846,wowhead="https://www.wowhead.com/wotlk/quest=7638",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The time has come, $N, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.$B$BSpeak with Lord Grayson Shadowbreaker here in Stormwind's Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin's most trusted mount, but the tasks before you to acquire one of your own.$B$BI wish you the best in this trial.  For the Light, noble $G brother : sister;!",logDesc="Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."} end
if not DB[7639] then DB[7639]={id=7639,zoneId=-141,name="To Show Due Judgment",level=-1,minLevel=60,giver="High Priest Rohan",giverType="NPC",giverId=11406,ender="Lord Grayson Shadowbreaker",enderType="NPC",enderId=928,rewardNextId=7640,poiX=-4607,poiY=-897,wowhead="https://www.wowhead.com/wotlk/quest=7639",image="assets/images/quests/placeholder.png",xpDiff=1,desc="With my blessings, take the censer.  I myself have used it in several exorcisms, and it should serve you well for the arduous tasks that lie ahead.$B$BReturn now to Lord Grayson Shadowbreaker in Stormwind, $N.  Your quest continues with him.",logDesc="Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."} end
if not DB[7640] then DB[7640]={id=7640,zoneId=-141,name="Exorcising Terrordale",level=-1,minLevel=60,giver="Lord Grayson Shadowbreaker",giverType="NPC",giverId=928,ender="Lord Grayson Shadowbreaker",enderType="NPC",enderId=928,poiX=-8577,poiY=882,wowhead="https://www.wowhead.com/wotlk/quest=7640",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I have added a pinch of dirt from the tainted ground of Terrordale in the Eastern Plaguelands to the censer.  You will now use this censer to find areas there that show signs of spiritual turmoil and disturbance.  Look for green auras that permeate the ground as the physical world buckles under the torment of the spirit realm and use the censer to drive out the evil spirits.$B$BWhen you have passed sufficient judgment on the spirits there, you will be ready to proceed.",logDesc="Use the Exorcism Censer to drive out the spirits that torment Terrordale.  When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."} end
if not DB[7641] then DB[7641]={id=7641,zoneId=-141,name="The Work of Grimand Elmore",level=-1,minLevel=60,giver="Lord Grayson Shadowbreaker",giverType="NPC",giverId=928,ender="Grimand Elmore",enderType="NPC",enderId=1416,rewardNextId=7642,poiX=-8577,poiY=882,wowhead="https://www.wowhead.com/wotlk/quest=7641",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A paladin's charger is nothing more than a pack animal without proper barding for it.  The barding used by your charger not only needs to be of the finest materials possible, but because of the circumstances involved it must also be sufficiently attuned to the spirit realm.$B$BFirst things first, $N - let's get your barding made.  In Stormwind's Dwarven District is one of the finest craftsmen living today, Grimand Elmore.  His work will not be cheap, but his quality is what we seek.  Speak with him.",logDesc="Speak with Grimand Elmore in Stormwind's Dwarven District."} end
if not DB[7642] then DB[7642]={id=7642,zoneId=-141,name="Collection of Goods",level=-1,minLevel=60,giver="Grimand Elmore",giverType="NPC",giverId=1416,ender="Grimand Elmore",enderType="NPC",enderId=1416,poiX=-8387,poiY=685,wowhead="https://www.wowhead.com/wotlk/quest=7642",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You'll need four things for the barding - runecloth for the lining, arcanite bars for the plating, Arthas' Tears for the spiritual attunement, and Stratholme holy water for the spiritual imbuement.  Actually, you need five things... gold for my fee.  That fee includes all labor as well as a handcrafted saddle and stirrups.$B$BOnce you've got all that, I'll be able to finish your barding.  Until then, there are some things I can get started on for you while you assemble your collection of goods.",logDesc="Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."} end
if not DB[7643] then DB[7643]={id=7643,zoneId=-141,name="Ancient Equine Spirit",level=-1,minLevel=60,giver="Lord Grayson Shadowbreaker",giverType="NPC",giverId=928,ender="Ancient Equine Spirit",enderType="NPC",enderId=14566,rewardNextId=7644,poiX=-8577,poiY=882,wowhead="https://www.wowhead.com/wotlk/quest=7643",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Your barding needs a special form of blessing, one from an appropriate spirit.  In Dire Maul is such a spirit, the Ancient Equine Spirit.  It is currently held by a corrupt treant, Tendris Warpwood.  Pass judgment upon this foul beast, $N.$B$BKnow this - freedom alone is not enough.  You must soothe the spirit before receiving its blessing.  For that, special horse feed is needed.  Travel to Southshore first and speak with Merideth Carlson on this... and prepare for more sacrifice.",logDesc="Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.$B$BTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it."} end
if not DB[7644] then DB[7644]={id=7644,zoneId=-141,name="Blessed Arcanite Barding",level=-1,minLevel=60,giver="Ancient Equine Spirit",giverType="NPC",giverId=14566,ender="Lord Grayson Shadowbreaker",enderType="NPC",enderId=928,rewardNextId=7646,poiX=18,poiY=381,wowhead="https://www.wowhead.com/wotlk/quest=7644",image="assets/images/quests/placeholder.png",xpDiff=6,desc="As the barding rests on the back of the Ancient Equine Spirit, it glows ever so slightly.  The air is thick with power for a brief moment, and then the barding disappears from the back of the horse and is now secure in your backpack.$B$BIt would seem that the barding has been blessed.  As per Lord Shadowbreaker's instructions, you should now return with it to him in Stormwind.",logDesc="Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."} end
if not DB[7645] then DB[7645]={id=7645,zoneId=-141,name="Manna-Enriched Horse Feed",level=-1,minLevel=60,giver="Merideth Carlson",giverType="NPC",giverId=2357,ender="Merideth Carlson",enderType="NPC",enderId=2357,poiX=-784,poiY=-603,wowhead="https://www.wowhead.com/wotlk/quest=7645",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Silver Hand thought me MAD when I told them that I could make a special horse feed that could nourish spiritual horses.  EVERYONE thought I was mad!  Well, now it's payback time!$B$BI'll make what you need, PALADIN... so-called CHAMPION... but it will cost you.  I need special biscuits - Enriched Manna Biscuits sold only by the Argent Dawn - for this blend.  I also demand, yes DEMAND gold as compensation for the misery I have endured!$B$BShow me the sacrifice you tout so much, PALADIN.",logDesc="Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills.  The Argent Dawn is known as the sole purveyor of the biscuits.$B$BYou also need to give her 50 gold to soothe her ruffled sensibilities.",rewards={{id=18775,qty=1}}} end
if not DB[7646] then DB[7646]={id=7646,zoneId=-141,name="The Divination Scryer",level=-1,minLevel=60,giver="Lord Grayson Shadowbreaker",giverType="NPC",giverId=928,ender="Lord Grayson Shadowbreaker",enderType="NPC",enderId=928,rewardNextId=7647,poiX=-8577,poiY=882,wowhead="https://www.wowhead.com/wotlk/quest=7646",image="assets/images/quests/placeholder.png",xpDiff=3,desc="We now must assemble a Divination Scryer - this will begin the trial that will allow you to redeem the fallen charger.  Your scryer, actually, is almost done.  The exorcism censer used in Terrordale is the catalyst for it, and I will fashion a suitable housing for the device.$B$BThe last components needed, though, are two diamonds.  They must be as juxtaposed in brilliance as they are in purpose - an Azerothian and a Pristine Black.  These two will be the beacon by which the scryer will pierce the shadows!",logDesc="Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."} end
if not DB[7647] then DB[7647]={id=7647,zoneId=-141,name="Judgment and Redemption",level=-1,minLevel=60,giver="Lord Grayson Shadowbreaker",giverType="NPC",giverId=928,ender="Darkreaver's Fallen Charger",enderType="NPC",enderId=14568,poiX=-8577,poiY=882,wowhead="https://www.wowhead.com/wotlk/quest=7647",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Take this satchel - in it are the items you will need for your task.$B$BUse the divination scryer in the heart of the Great Ossuary's basement to bring forth accursed spirits that must be judged.  Use your judgments wisely during this trial - they will prove more potent than you realize.  After the spirits, the death knight will appear; defeat him and reclaim the lost soul of the charger.  Only then $N, will you be able to redeem it and place your barding upon your new steed!$B$BGood luck!",logDesc="Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.$B$BGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."} end
if not DB[7648] then DB[7648]={id=7648,zoneId=-141,name="Grimand's Finest Work",level=-1,minLevel=60,giver="Grimand Elmore",giverType="NPC",giverId=1416,ender="Lord Grayson Shadowbreaker",enderType="NPC",enderId=928,poiX=-8387,poiY=685,wowhead="https://www.wowhead.com/wotlk/quest=7648",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Grimand wipes sweat from his brow, beaming with a sense of pride.>$B$BThere you are, my friend.  This is some of my finest work - as good as the barding I personally made for Lord Shadowbreaker when he went for his own charger.  I thank you for your trust in me to provide for you the best.$B$BNo doubt Grayson will want to see the work for himself as well.  Take your barding to him, and give him my thanks for his honorable business.",logDesc="Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection."} end
if not DB[7649] then DB[7649]={id=7649,zoneId=-121,name="Enchanted Thorium Platemail: Volume I",level=60,minLevel=50,ender="Lorekeeper Lydros",enderType="NPC",enderId=14368,wowhead="https://www.wowhead.com/wotlk/quest=7649",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The tome carries the mark of the Athenaeum.",logDesc="Return the book to its rightful owners.",rewards={{id=12727,qty=1}}} end
