if not DB[7666] then DB[7666]={id=7666,zoneId=-141,name="Again Into the Great Ossuary",level=-1,minLevel=60,giver="Lord Grayson Shadowbreaker",giverType="NPC",giverId=928,ender="Lord Grayson Shadowbreaker",enderType="NPC",enderId=928,poiX=-8577,poiY=882,wowhead="https://www.wowhead.com/wotlk/quest=7666",image="assets/images/quests/placeholder.png",rewards={{id=18746,qty=1}}} end
if not DB[7667] then DB[7667]={id=7667,zoneId=-82,name="Material Assistance",level=60,minLevel=58,giver="Sagorne Creststrider",giverType="NPC",giverId=13417,ender="Sagorne Creststrider",enderType="NPC",enderId=13417,rewardNextId=8258,poiX=1938,poiY=-4223,wowhead="https://www.wowhead.com/wotlk/quest=7667",image="assets/images/quests/placeholder.png",xpDiff=4,desc="$N, there is a pressing matter I hope you can help with... both materially and spiritually.  Allow me to explain.$B$BWithin the depths of the Scholomance in Lordaeron is a chamber called the Great Ossuary.  I need to complete a device that would pierce the shadows of this horrid room.  To finish what I have started, I need two diamonds: an Azerothian and a Pristine Black.  These are not trivial items, I know - I just don't have the resources myself.$B$BCould you provide me with one of each?",logDesc="If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond."} end
if not DB[7668] then DB[7668]={id=7668,zoneId=-82,name="The Darkreaver Menace",level=60,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=7668",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Death Knight Darkreaver lords over the Great Ossuary in the Scholomance.  He threatens to twist the spirit realm to do his own bidding, and he must be stopped!  This is where the scryer you helped make comes into play.$B$BUse the divination scryer in the heart of the Great Ossuary's basement to call forth Darkreaver's spirit minions.  Defeat the spirits and the death knight himself will appear.  $N, bring me his head!  Only his demise will reverse the damage dome to the spirit realm!",logDesc="Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth spirits you must fight.  Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.$B$BBring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.",rewards={{id=18807,qty=1}}} end
if not DB[7669] then DB[7669]={id=7669,zoneId=-82,name="Again Into the Great Ossuary",level=60,minLevel=58,giver="Lord Grayson Shadowbreaker",giverType="NPC",giverId=928,ender="Lord Grayson Shadowbreaker",enderType="NPC",enderId=928,poiX=-8577,poiY=882,wowhead="https://www.wowhead.com/wotlk/quest=7669",image="assets/images/quests/placeholder.png",rewards={{id=18746,qty=1}}} end
if not DB[7670] then DB[7670]={id=7670,zoneId=-141,name="Lord Grayson Shadowbreaker",level=-1,minLevel=60,giver="Brandur Ironhammer",giverType="NPC",giverId=5149,ender="Lord Grayson Shadowbreaker",enderType="NPC",enderId=928,poiX=-4602,poiY=-896,wowhead="https://www.wowhead.com/wotlk/quest=7670",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The time has come, $N, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.$B$BSpeak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin's most trusted mount, but the tasks before you to acquire one of your own.$B$BI wish you the best in this trial.  For the Light, noble $G brother : sister;!",logDesc="Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."} end
