if not DB[7761] then DB[7761]={id=7761,zoneId=1583,name="Blackhand's Command",level=60,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=7761",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Imbecile,$B$BI hold very little faith in your ability to prevent outsiders from accessing the master's lair. In the very likely event of your death, this orb has its own failsafe built in to prevent outsiders from teleporting directly into Blackwing.$B$BOnly those with the Mark of Drakkisath branded upon their hand may make use of this orb. Thankfully, Drakkisath is not nearly as incompetent as you, Quartermaster. He guards the brand himself!$B$B-Warchief Rend Blackhand$B$BP.S. Destroy this letter, idiot.",logDesc="That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.$B$BThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate."} end
if not DB[7781] then DB[7781]={id=7781,zoneId=1519,name="The Lord of Blackrock",level=60,minLevel=60,ender="3",enderType="NPC",enderId=29611,rewardNextId=7782,wowhead="https://www.wowhead.com/wotlk/quest=7781",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian. Return it to King Varian Wrynn, champion.",logDesc="Return the Head of Nefarian to King Varian Wrynn in Stormwind."} end
