if not DB[7785] then DB[7785]={id=7785,zoneId=-344,name="Examine the Vessel",level=60,minLevel=60,ender="Highlord Demitrian",enderType="NPC",enderId=14347,rewardNextId=7786,wowhead="https://www.wowhead.com/wotlk/quest=7785",image="assets/images/quests/placeholder.png",desc="Examine the vessel of his rebirth, mortal. It is from this that the Windseeker shall be reborn!",logDesc="Examine the Vessel of Rebirth and return it to Highlord Demitrian."} end
if not DB[7786] then DB[7786]={id=7786,zoneId=-344,name="Thunderaan the Windseeker",level=60,minLevel=60,giver="Highlord Demitrian",giverType="NPC",giverId=14347,ender="Highlord Demitrian",enderType="NPC",enderId=14347,poiX=-6158,poiY=1781,wowhead="https://www.wowhead.com/wotlk/quest=7786",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I have told you all that I know, $N. It is you who must find elementium. It is you who must destroy the Firelord's corporeal form.$B$BDo this and gain the blessing of Thunderaan.",logDesc="To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus."} end
if not DB[7787] then DB[7787]={id=7787,zoneId=-344,name="Rise, Thunderfury!",level=60,minLevel=60,ender="Highlord Demitrian",enderType="NPC",enderId=14347,wowhead="https://www.wowhead.com/wotlk/quest=7787",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have defeated the Wind Seeker. Take the dormant blade and force the lying wretch, Demitrian, to use the materials you provided for his betrayal to wake Thunderfury.",logDesc="Present the Dormant Wind Kissed Blade to Highlord Demitrian.",rewards={{id=19019,qty=1}}} end
if not DB[7788] then DB[7788]={id=7788,zoneId=3277,name="Vanquish the Invaders!",level=25,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=7788",image="assets/images/quests/placeholder.png",xpDiff=5,money=5500,desc="Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.$B$BEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!$B$BDo this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.",logDesc="Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove."} end
if not DB[7789] then DB[7789]={id=7789,zoneId=3277,name="Quell the Silverwing Usurpers",level=25,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=7789",image="assets/images/quests/placeholder.png",xpDiff=5,money=5500,desc="The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!$B$BLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded.$B",logDesc="Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp."} end
