if not DB[7815] then DB[7815]={id=7815,zoneId=47,name="Snapjaws, Mon!",level=50,minLevel=44,giver="Katoom the Angler",giverType="NPC",giverId=14740,ender="Katoom the Angler",enderType="NPC",enderId=14740,poiX=-626,poiY=-4668,wowhead="https://www.wowhead.com/wotlk/quest=7815",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="Don't let their big eyes fool you, mon! Those saltwater snapjaws be a menace. I can't fish for five minutes without getting a broken line from one of those oversized fish vacuums stealing my bait.$B$BDo me and the people of Revantusk Village a service and kill em, mon.$B$BKill the whole lot of em!",logDesc="Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 10 Saltwater Snapjaw turtles. Return to him when you have completed this task.",rewards={{id=19022,qty=1}}} end
if not DB[7816] then DB[7816]={id=7816,zoneId=47,name="Gammerita, Mon!",level=48,minLevel=44,giver="Katoom the Angler",giverType="NPC",giverId=14740,ender="Katoom the Angler",enderType="NPC",enderId=14740,poiX=-626,poiY=-4668,wowhead="https://www.wowhead.com/wotlk/quest=7816",image="assets/images/quests/placeholder.png",xpDiff=5,money=14000,desc="Yo! There be a turtle out there not like the others. She be the Gammerita, leader of the saltwater snapjaws - a downright dirty thievin' reptile.$B$BMon, she stole my best lure. Snapped it right off my line! Since then, the fish just aren't biting the same.$B$BFind Gammerita and get my lure out of her stomach.",logDesc="Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.$B$BKatoom mentioned that Gammerita hangs out on the coast with the other turtles."} end
