if not DB[7838] then DB[7838]={id=7838,zoneId=0,name="Arena Grandmaster",level=55,minLevel=0,giver="Short John Mithril",giverType="NPC",giverId=14508,ender="Short John Mithril",enderType="NPC",enderId=14508,poiX=-13184,poiY=333,wowhead="https://www.wowhead.com/wotlk/quest=7838",image="assets/images/quests/placeholder.png",rewards={{id=19024,qty=1}}} end
if not DB[7839] then DB[7839]={id=7839,zoneId=47,name="Vilebranch Hooligans",level=48,minLevel=44,giver="Smith Slagtree",giverType="NPC",giverId=14737,ender="Smith Slagtree",enderType="NPC",enderId=14737,poiX=-590,poiY=-4548,wowhead="https://www.wowhead.com/wotlk/quest=7839",image="assets/images/quests/placeholder.png",xpDiff=5,money=14000,desc="Vilebranch scum invaded our village and stole my tools! I have backup tools but the set they stole was a gift given to me by a kind hearted gnome that saved my life when I was a young orc.$B$BI want those tools back, $N - they mean the world to me.$B$BMarkhor reported that the tools were spotted near the Agol'watha and Shaol'watha temples.$B$BThose temples are in the northeastern region of the Hinterlands.$B$BRecover my tools!",logDesc="Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete.$B$BYou recall Smith Slagtree mentioning that the tools might be at one of the Vilebranch temples in the northeastern region of the Hinterlands. You should also check Skulk Rock."} end
if not DB[7840] then DB[7840]={id=7840,zoneId=47,name="Lard Lost His Lunch",level=49,minLevel=44,giver="Lard",giverType="NPC",giverId=14731,ender="Lard",enderType="NPC",enderId=14731,poiX=-622,poiY=-4583,wowhead="https://www.wowhead.com/wotlk/quest=7840",image="assets/images/quests/placeholder.png",xpDiff=5,money=14000,desc="Lard was at secret special spot having picnic when ugly mean Vilebranch hit Lard wit da big stick. Lard run back to Revantusk but forget Lard lunch. Lard hungry. Maybe you go back to secret special spot and get Lard lunch? Lard scared. Go nort! Island der to da nort is da secret special spot.",logDesc="Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.$B$BLard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls.",rewards={{id=19035,qty=1}}} end
if not DB[7841] then DB[7841]={id=7841,zoneId=47,name="Message to the Wildhammer",level=48,minLevel=44,giver="Otho Moji'ko",giverType="NPC",giverId=14738,ender="Otho Moji'ko",enderType="NPC",enderId=14738,rewardNextId=7842,poiX=-563,poiY=-4631,wowhead="https://www.wowhead.com/wotlk/quest=7841",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Wildhammer be striking up deals with our enemies, forgin' new alliances. This time, they be workin' with the high elves, mon.$B$B<Otho spits.>$B$BWe be needin' to send those Wildhammer dwarves a message - a message in the blood of our enemies. Slaughter every Highvale high elf that you come across, leave their bodies as a warnin'.$B$BNever mess with trolls!",logDesc="Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 8 Highvale Scouts, 5 Highvale Outrunners, 5 Highvale Rangers and 2 Highvale Marksman. Return to him when this task is complete.$B$BYou can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands."} end
if not DB[7842] then DB[7842]={id=7842,zoneId=47,name="Another Message to the Wildhammer",level=48,minLevel=44,giver="Otho Moji'ko",giverType="NPC",giverId=14738,ender="Otho Moji'ko",enderType="NPC",enderId=14738,rewardNextId=7843,poiX=-563,poiY=-4631,wowhead="https://www.wowhead.com/wotlk/quest=7842",image="assets/images/quests/placeholder.png",xpDiff=6,desc="They say the Wildhammer and gryphon are as close to each other as troll and mate. Disgusting, but we be able to use this to our advantage, mon. We send them another message.$B$BKill all the gryphons you see in the Hinterlands and collect a long elegant feather! From this we make the final message.",logDesc="Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 1 Long Elegant Feather from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.$B$BGryphons are known to inhabit every region of the Hinterlands."} end
if not DB[7843] then DB[7843]={id=7843,zoneId=47,name="The Final Message to the Wildhammer",level=50,minLevel=44,giver="Otho Moji'ko",giverType="NPC",giverId=14738,ender="Otho Moji'ko",enderType="NPC",enderId=14738,poiX=-563,poiY=-4631,wowhead="https://www.wowhead.com/wotlk/quest=7843",image="assets/images/quests/placeholder.png",xpDiff=6,money=22000,desc="<Otho hands you a long, blood drenched spear, wrapped in several gryphon feathers.>$B$BYou take this, mon. You take this to Aerie Peak, dead center of town by the well. You plant it! Drive it right into the ground! Show those dwarves that troll mean business! Come back when you do this. Hopefully you come back alive.",logDesc="Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.$B$BBeware of angry Wildhammer dwarves and unruly members of the Alliance.",rewards={{id=19119,qty=1}}} end
if not DB[7844] then DB[7844]={id=7844,zoneId=47,name="Cannibalistic Cousins",level=48,minLevel=44,giver="Mystic Yayo'jin",giverType="NPC",giverId=14739,ender="Mystic Yayo'jin",enderType="NPC",enderId=14739,poiX=-542,poiY=-4609,wowhead="https://www.wowhead.com/wotlk/quest=7844",image="assets/images/quests/placeholder.png",xpDiff=5,money=14000,desc="Three different tribes of trolls inhabit the Hinterlands, $N. That is about as far as the similarities between the tribes extends: We are all trolls and we live in the Hinterlands.$B$BThe Vilebranch - aptly named - are a depraved lot; feeding on other trolls and humanoids.$B$BIf Zul'jin were here, he would have destroyed the whole lot of them with a flick of his wrist - alas, Zul'jin has not yet returned and we are left to our own devices.$B$BIt is up to you to destroy the filth of the region!",logDesc="Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 6 Vilebranch Scalpers and 2 Vilebranch Soothsayers. Return to her when this task is complete.$B$BYayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands."} end
if not DB[7845] then DB[7845]={id=7845,zoneId=47,name="Kidnapped Elder Torntusk!",level=51,minLevel=46,giver="Primal Torntusk",giverType="NPC",giverId=14736,ender="Elder Torntusk",enderType="NPC",enderId=14757,rewardNextId=7846,poiX=-617,poiY=-4586,wowhead="https://www.wowhead.com/wotlk/quest=7845",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My mate was taken by Vilebranch savages in a bold midnight raid on our village. Our spies have told me that he is still alive and being held prisoner atop Jintha'alor. The Vile Priestess Hexx is said to be preparing him for a sacrifice to the faceless blood God, Hakkar.$B$BYou must save him, $N! Our village could not stand a loss this great.",logDesc="Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.$B$BYou have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands."} end
if not DB[7846] then DB[7846]={id=7846,zoneId=47,name="Recover the Key!",level=51,minLevel=46,giver="Elder Torntusk",giverType="NPC",giverId=14757,ender="Elder Torntusk",enderType="NPC",enderId=14757,rewardNextId=7847,poiX=-531,poiY=-3873,wowhead="https://www.wowhead.com/wotlk/quest=7846",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The key to my bindings is held by Hitah'ya the Keeper. She is in the nearby cave. Be careful, $c, for she is guarded well.$B$BKill her and bring the key back to loosen my shackles. Only then will I be free to return home.",logDesc="Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key."} end
if not DB[7847] then DB[7847]={id=7847,zoneId=47,name="Return to Primal Torntusk",level=51,minLevel=46,giver="Elder Torntusk",giverType="NPC",giverId=14757,ender="Primal Torntusk",enderType="NPC",enderId=14736,poiX=-531,poiY=-3873,wowhead="https://www.wowhead.com/wotlk/quest=7847",image="assets/images/quests/placeholder.png",xpDiff=5,money=22500,desc="Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you.",logDesc="Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue.",choiceRewards={{id=19114,qty=1},{id=19115,qty=1}}} end
if not DB[7848] then DB[7848]={id=7848,zoneId=2717,name="Attunement to the Core",level=60,minLevel=55,giver="Lothos Riftwaker",giverType="NPC",giverId=14387,ender="Lothos Riftwaker",enderType="NPC",enderId=14387,poiX=-7509,poiY=-1040,wowhead="https://www.wowhead.com/wotlk/quest=7848",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Rifts stir, tear, and collapse all around us, $r. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.$B$BSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.$B$BI assure you, the portal is there and access is possible.$B$BI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.",logDesc="Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment."} end
if not DB[7849] then DB[7849]={id=7849,zoneId=47,name="Separation Anxiety",level=50,minLevel=46,giver="Huntsman Markhor",giverType="NPC",giverId=14741,ender="Huntsman Markhor",enderType="NPC",enderId=14741,poiX=-575,poiY=-4623,wowhead="https://www.wowhead.com/wotlk/quest=7849",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch.$B$BSadly, he was not fated to live and was given a swift, brutal execution; his remains fed to the oozes and wolves of the Vilebranch.$B$BIt is too late to save his life but not too late to save his soul. Recover his remains, $N.",logDesc="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.$B$BMarkhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.",choiceRewards={{id=19117,qty=1},{id=19116,qty=1}}} end
if not DB[7850] then DB[7850]={id=7850,zoneId=47,name="Dark Vessels",level=50,minLevel=46,giver="Primal Torntusk",giverType="NPC",giverId=14736,ender="Primal Torntusk",enderType="NPC",enderId=14736,poiX=-617,poiY=-4586,wowhead="https://www.wowhead.com/wotlk/quest=7850",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx.$B$BThroughout Jintha'alor you will find dark vessels of tainted blood. The vessels radiate the foul magic of the faceless blood God, empowering the Vilebranch and also driving them to madness.$B$BSteal those vessels and return them to me so that I may remove the taint and ultimately loosen the grip of the blood God.",logDesc="Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 5 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.",rewards={{id=19118,qty=1}}} end
if not DB[7861] then DB[7861]={id=7861,zoneId=47,name="Wanted: Vile Priestess Hexx and Her Minions",level=51,minLevel=44,ender="Primal Torntusk",enderType="NPC",enderId=14736,wowhead="https://www.wowhead.com/wotlk/quest=7861",image="assets/images/quests/placeholder.png",xpDiff=6,money=22500,desc="By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice!$B$BA grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard.",logDesc="You have been ordered to slay Vile Priestess Hexx and 5 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.$B$BVile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.",choiceRewards={{id=19159,qty=1},{id=19121,qty=1}}} end
if not DB[7862] then DB[7862]={id=7862,zoneId=47,name="Job Opening: Guard Captain of Revantusk Village",level=51,minLevel=44,ender="Primal Torntusk",enderType="NPC",enderId=14736,wowhead="https://www.wowhead.com/wotlk/quest=7862",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open. If you are interested in becoming Captain of the Guard for Revantusk, complete the following tasks and submit your application to Primal Torntusk:$B$BExterminate Vilebranch Berserkers.$B$BExterminate Vilebranch Shadow Hunters.$B$BExterminate Vilebranch Blood Drinkers.$B$BExterminate Vilebranch Soul Eaters.",logDesc="You have been tasked with the decimation of 5 Vilebranch Berserkers, 3 Vilebranch Shadow Hunters, 3 Vilebranch Blood Drinkers, and 2 Vilebranch Soul Eaters.$B$BShould you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands.",rewards={{id=19120,qty=1}}} end
