if not DB[7937] then DB[7937]={id=7937,zoneId=-364,name="Your Fortune Awaits You...",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=7937",image="assets/images/quests/placeholder.png",desc="\"Your fortune awaits you in Eastvale.\"$B$BThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Eastvale Logging Camp in Elwynn Forest.  Focusing closer in on the image, you see a haystack that sits next to a stable.$B",logDesc="Travel to the Eastvale Logging Camp in Elwynn Forest and seek out your fortune.",rewards={{id=19425,qty=1}}} end
if not DB[7938] then DB[7938]={id=7938,zoneId=-364,name="Your Fortune Awaits You...",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=7938",image="assets/images/quests/placeholder.png",desc="\"Your fortune awaits you inside the Deadmines.\"$B$BThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Deadmines inside Westfall's ruined hamlet of Moonbrook.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the mines itself.  Stepping through it, a strange chest appears out from nowhere.",logDesc="Travel to the Deadmines in Westfall and seek out your fortune.",rewards={{id=19425,qty=1}}} end
