if not DB[8053] then DB[8053]={id=8053,zoneId=19,name="Paragons of Power: The Freethinker's Armguards",level=60,minLevel=58,giver="Jin'rokh the Breaker",giverType="NPC",giverId=14902,ender="Jin'rokh the Breaker",enderType="NPC",enderId=14902,poiX=-11783,poiY=1244,wowhead="https://www.wowhead.com/wotlk/quest=8053",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You are a heathen.  Heathens have a place in the tribe.  Heathens are freethinkers of Zandalar.  Freethinkers do not fear oppression.  Freethinkers die for what they believe in.  We know you would die for what you believe in.  This earns our acknowledgement.  This earns you a chance to prove yourself further.$B$BWe must have the Paragons of Power.  Go to Zul'Gurub.  Kill the minions of Hakkar.  Return when you have what I seek.  Claim the first battle gear of a Zandalar freethinker.$B$BGo.",logDesc="Bring Jin'rokh the Breaker Primal Hakkari Bindings.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.$B$BJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19827,qty=1}}} end
if not DB[8054] then DB[8054]={id=8054,zoneId=19,name="Paragons of Power: The Freethinker's Belt",level=60,minLevel=58,giver="Jin'rokh the Breaker",giverType="NPC",giverId=14902,ender="Jin'rokh the Breaker",enderType="NPC",enderId=14902,poiX=-11783,poiY=1244,wowhead="https://www.wowhead.com/wotlk/quest=8054",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Your beliefs are alien to us, heathen.  Ancient Zandalar were once branded as heretics.  This was when the Gurubashi Empire was strong.  Heathens dared to challenge the priest of Hakkar.  Heathens then were hunted and killed as vermin.  Those heathens never wavered in their fight against the Blood God.  We honor the price they paid.  They are the freethinkers.$B$BDestroy the minions of Hakkar in Zul'Gurub.  Bring me the Paragons of Power I seek.  Success will be greatly rewarded.$B$BGo.",logDesc="Bring Jin'rokh the Breaker a Primal Hakkari Shawl.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.$B$BJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19826,qty=1}}} end
if not DB[8055] then DB[8055]={id=8055,zoneId=19,name="Paragons of Power: The Freethinker's Breastplate",level=60,minLevel=58,giver="Jin'rokh the Breaker",giverType="NPC",giverId=14902,ender="Jin'rokh the Breaker",enderType="NPC",enderId=14902,poiX=-11783,poiY=1244,wowhead="https://www.wowhead.com/wotlk/quest=8055",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Battle gear gives you power in the tribe.  The freethinkers are honored in this way.  They are zealots.  They imbue their breastplates with powerful mojo.  If their beliefs falter in the face of the enemy, their breastplate will not.$B$BYou must be revered amongst us to possess such a breastplate.  Go to Zul'Gurub.  Take the Paragons of Power I need.  Take the Paragons most painfully from the fools inside.  Bring them to me.  Prove your worth as a freethinker once and for all.",logDesc="Bring Jin'rokh the Breaker a Primal Hakkari Tabard.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.$B$BJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19825,qty=1}}} end
if not DB[8056] then DB[8056]={id=8056,zoneId=19,name="Paragons of Power: The Augur's Bracers",level=60,minLevel=58,giver="Maywiki of Zuldazar",giverType="NPC",giverId=14904,ender="Maywiki of Zuldazar",enderType="NPC",enderId=14904,poiX=-11850,poiY=1245,wowhead="https://www.wowhead.com/wotlk/quest=8056",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The augurs of our tribe are revered for their gifts of the divine sight, ya mon.  They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people.  As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe.$B$BBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this for us, and I'll give ya some bracers that our augurs prize above all others!  ",logDesc="Bring Maywiki of Zuldazar a Primal Hakkari Armsplint.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.$B$BMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19830,qty=1}}} end
if not DB[8057] then DB[8057]={id=8057,zoneId=19,name="Paragons of Power: The Haruspex's Bracers",level=60,minLevel=58,giver="Maywiki of Zuldazar",giverType="NPC",giverId=14904,ender="Maywiki of Zuldazar",enderType="NPC",enderId=14904,poiX=-11850,poiY=1245,wowhead="https://www.wowhead.com/wotlk/quest=8057",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A haruspex is a key member of our tribe; you'll be wise to listen to their portents.  By communion with animals and givin' them up to the spirits when needed, they give us divine guidance.  In times past, the haruspex's insight and wisdom gave us an edge in the wars against the splintered tribes of the Gurubashi.$B$BBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this, and I'll give ya bracers that any haruspex of the Zandalar would want.",logDesc="Bring Maywiki of Zuldazar a Primal Hakkari Stanchion.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.$B$BMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19840,qty=1}}} end
if not DB[8058] then DB[8058]={id=8058,zoneId=19,name="Paragons of Power: The Vindicator's Armguards",level=60,minLevel=58,giver="Jin'rokh the Breaker",giverType="NPC",giverId=14902,ender="Jin'rokh the Breaker",enderType="NPC",enderId=14902,poiX=-11783,poiY=1244,wowhead="https://www.wowhead.com/wotlk/quest=8058",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Vengeance is power.  The Zandalar vindicator is such power.  The tribe has many enemies.  The vindicator exacts retribution on them.  No crime against us is unpunished.  The vindicator delivers this punishment.  Our enemies fear our vengeance.  They should.  They forever will.$B$BBecome one of our vindicators.  Seek the Paragons of Power inside Zul'Gurub.  Slay the minions of Hakkar and claim vengeance in the tribe's name.  You will be rewarded.",logDesc="Bring Jin'rokh the Breaker a Primal Hakkari Armsplint.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.$B$BJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19824,qty=1}}} end
if not DB[8059] then DB[8059]={id=8059,zoneId=19,name="Paragons of Power: The Demoniac's Wraps",level=60,minLevel=58,giver="Al'tabim the All-Seeing",giverType="NPC",giverId=14903,ender="Al'tabim the All-Seeing",enderType="NPC",enderId=14903,poiX=-11854,poiY=1242,wowhead="https://www.wowhead.com/wotlk/quest=8059",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Warlocks tread dangerous ground in dealing with demons, but our demoniacs take this one step further.  Through an ancient and arcane ritual, they allow a demon to enter their being.  Rather than let it possess them though, they enslave the demon from the inside, absorbing the power of the beast for their own command.  It is a feat few are ever able to master.$B$BFor you to learn of the power of the demoniac, I must have Paragons of Power from Zul'Gurub.  Go there and retrieve that which we seek.",logDesc="Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.$B$BAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19848,qty=1}}} end
if not DB[8060] then DB[8060]={id=8060,zoneId=19,name="Paragons of Power: The Illusionist's Wraps",level=60,minLevel=58,giver="Al'tabim the All-Seeing",giverType="NPC",giverId=14903,ender="Al'tabim the All-Seeing",enderType="NPC",enderId=14903,poiX=-11854,poiY=1242,wowhead="https://www.wowhead.com/wotlk/quest=8060",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Mages in our tribe are known as illusionists.  They employ powerful mojo in their incantations, often befuddling and confusing the tribe's enemies!$B$B<Al'tabim laughs wickedly.>$B$BIt is quite the sight to see a powerful illusionist at work, bringing our enemies to their knees from their own madness!$B$BFor you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power.  For this, I will give you arm wraps our illusionists use to weave their spells.",logDesc="Bring Al'tabim the All-Seeing Primal Hakkari Bindings.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.$B$BAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19846,qty=1}}} end
if not DB[8061] then DB[8061]={id=8061,zoneId=19,name="Paragons of Power: The Confessor's Wraps",level=60,minLevel=58,giver="Al'tabim the All-Seeing",giverType="NPC",giverId=14903,ender="Al'tabim the All-Seeing",enderType="NPC",enderId=14903,poiX=-11854,poiY=1242,wowhead="https://www.wowhead.com/wotlk/quest=8061",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We Zandalar invest power in those who speak with the authority of divinity.  Our priests are more than just healers - they are our confessors.  Evil comes both from outside threats - such as Hakkar - and from within the tribe.  Our confessors act as the judges amongst us, preserving us from the same evil that devoured the Gurubashi from inside itself.$B$BGo to Zul'Gurub and bring back the Paragons of Power from the Gurubashi.  Learn what it means to be the confessor, and preserve us from evil.",logDesc="Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.$B$BAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19843,qty=1}}} end
if not DB[8062] then DB[8062]={id=8062,zoneId=19,name="Paragons of Power: The Predator's Bracers",level=60,minLevel=58,giver="Falthir the Sightless",giverType="NPC",giverId=14905,ender="Falthir the Sightless",enderType="NPC",enderId=14905,poiX=-11752,poiY=1322,wowhead="https://www.wowhead.com/wotlk/quest=8062",image="assets/images/quests/placeholder.png",xpDiff=5,desc="In the dark times after the fall of the Gurubashi Empire, Zandalar predators used their prowess to provide sustenance for the tribe.  Hunters claim to be much like our tribe's predators - to seek the hunt is to embody the essence of the predator, yes.  Your hunt in Zul'Gurub, however, will show us how you truly rate amongst our finest predators.$B$BBring to me a sampling of the Paragons of Power from within Zul'Gurub.  Do so, and you'll take first steps in becoming the penultimate predator.",logDesc="Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Bindings.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.$B$BFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19833,qty=1}}} end
if not DB[8063] then DB[8063]={id=8063,zoneId=19,name="Paragons of Power: The Madcap's Bracers",level=60,minLevel=58,giver="Falthir the Sightless",giverType="NPC",giverId=14905,ender="Falthir the Sightless",enderType="NPC",enderId=14905,poiX=-11752,poiY=1322,wowhead="https://www.wowhead.com/wotlk/quest=8063",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The madcaps of Zandalar are similar to rogues, but above all else they embrace madness... chaos... the unpredictability of existence.  A terror to behold on the battlefield, they sowed the seeds of confusion and mayhem amongst our enemies in the savage times after the tribes splintered.  We would not be here today without them.$B$BBring to me the Paragons of Power from Zul'Gurub that I seek, and I will grant you the first of the madcap's prized armors.  Embrace the madness!",logDesc="Bring Falthir the Sightless a Primal Hakkari Armsplint.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.$B$BFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19836,qty=1}}} end
if not DB[8064] then DB[8064]={id=8064,zoneId=19,name="Paragons of Power: The Haruspex's Belt",level=60,minLevel=58,giver="Maywiki of Zuldazar",giverType="NPC",giverId=14904,ender="Maywiki of Zuldazar",enderType="NPC",enderId=14904,poiX=-11850,poiY=1245,wowhead="https://www.wowhead.com/wotlk/quest=8064",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We Zandalar know not of druidic ways; nature is to be shaped by our need, not the other way around.  Still, a haruspex is the one of us most in tune with nature, and rightly so.  To give up the ghost of a beastie is to know what it is to be one of them.  That is the real power of nature.$B$BBring me an offerin' of the Paragons of Power from inside Zul'Gurub, proving yourself to us.  Do this, and I'll give ya a powerful item - a belt used by many of the Zandalar's haruspices.$B$BStrong mojo, ya mon!",logDesc="Bring Maywiki of Zuldazar a Primal Hakkari Sash.  Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale. You must also be Honored with Zandalar.",rewards={{id=19839,qty=1}}} end
if not DB[8065] then DB[8065]={id=8065,zoneId=19,name="Paragons of Power: The Haruspex's Tunic",level=60,minLevel=58,giver="Maywiki of Zuldazar",giverType="NPC",giverId=14904,ender="Maywiki of Zuldazar",enderType="NPC",enderId=14904,poiX=-11850,poiY=1245,wowhead="https://www.wowhead.com/wotlk/quest=8065",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The ultimate symbol of a haruspex's power is what they wear, $N.  Of these, the tunic symbolizes the connection between themselves and the divine wisdom they seek.  It often weaves parts of the beasties they sacrifice into the tunic; this reminds them of the connection they have to their gifts.$B$BBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this, and a tunic seeping with the true power of a haruspex is yours.",logDesc="Bring Maywiki of Zuldazar a Primal Hakkari Tabard.  Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale. You must also be Revered with Zandalar.",rewards={{id=19838,qty=1}}} end
if not DB[8066] then DB[8066]={id=8066,zoneId=19,name="Paragons of Power: The Predator's Belt",level=60,minLevel=58,giver="Falthir the Sightless",giverType="NPC",giverId=14905,ender="Falthir the Sightless",enderType="NPC",enderId=14905,poiX=-11752,poiY=1322,wowhead="https://www.wowhead.com/wotlk/quest=8066",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A predator knows how to stalk their prey, but a successful one knows how to strike at it once they have closed ranks.  You must master both to have any chance of success in Zul'Gurub... and any chance of being like the Zandalar predators.$B$BBring me choice parts of the Paragons of Power from within Zul'Gurub.  My reward will be the power that the trinkets yield, while yours will be the Zandalar predator's belt - equipment well worth the trade.",logDesc="Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Shawl.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.$B$BFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19832,qty=1}}} end
if not DB[8067] then DB[8067]={id=8067,zoneId=19,name="Paragons of Power: The Predator's Mantle",level=60,minLevel=58,giver="Falthir the Sightless",giverType="NPC",giverId=14905,ender="Falthir the Sightless",enderType="NPC",enderId=14905,poiX=-11752,poiY=1322,wowhead="https://www.wowhead.com/wotlk/quest=8067",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We Zandalar prize what we wear as a symbol of accomplishment.  You don't need to be able to see what one wears to be able to sense what emanates from it - power transcends sight.  The garments of the Zandalar predator are like this, and most cherished by them is the mantle they wear.  It helps to obfuscate them from view... and to make their presence known when they wish it.$B$BThe Paragons of Power await your retrieval in Zul'Gurub.  Bring me what I seek, and the predator's mantle shall be yours.",logDesc="Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Aegis.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.$B$BFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19831,qty=1}}} end
if not DB[8068] then DB[8068]={id=8068,zoneId=19,name="Paragons of Power: The Illusionist's Mantle",level=60,minLevel=58,giver="Al'tabim the All-Seeing",giverType="NPC",giverId=14903,ender="Al'tabim the All-Seeing",enderType="NPC",enderId=14903,poiX=-11854,poiY=1242,wowhead="https://www.wowhead.com/wotlk/quest=8068",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Magic is a raw, primal force to be shaped by those strong enough to do it.  Mojo is our extension of this power; one such potent manipulation of it is in the form of illusion.  How can one truly hope to win against a foe that is not even really there?  We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe.$B$BTake the needed Paragons of Power from Zul'Gurub - for this, honor from the tribe and a powerful mantle used by our best illusionists will be yours!",logDesc="Bring Al'tabim the All-Seeing a Primal Hakkari Shawl.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.$B$BAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19845,qty=1}}} end
if not DB[8069] then DB[8069]={id=8069,zoneId=19,name="Paragons of Power: The Illusionist's Robes",level=60,minLevel=58,giver="Al'tabim the All-Seeing",giverType="NPC",giverId=14903,ender="Al'tabim the All-Seeing",enderType="NPC",enderId=14903,poiX=-11854,poiY=1242,wowhead="https://www.wowhead.com/wotlk/quest=8069",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The tribe acknowledges station and power through what we wear.  Our vestments are made from the finest of materials, and interwoven with the mojo we use to make us powerful.  Illusionists are no exception; their robes are said to embody the essence of illusion in their look.  Legend states that their ancient robes never looked the same twice.$B$BI will give you an illusionist's robe, $N... but earn your place of reverence among the tribe first!  Bring me the Paragons of Power from Zul'Gurub!",logDesc="Bring Al'tabim the All-Seeing a Primal Hakkari Kossack.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.$B$BAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=20034,qty=1}}} end
if not DB[8070] then DB[8070]={id=8070,zoneId=19,name="Paragons of Power: The Confessor's Bindings",level=60,minLevel=58,giver="Al'tabim the All-Seeing",giverType="NPC",giverId=14903,ender="Al'tabim the All-Seeing",enderType="NPC",enderId=14903,poiX=-11854,poiY=1242,wowhead="https://www.wowhead.com/wotlk/quest=8070",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Shortly after the fall of the Gurubashi, we Zandalar almost succumbed to a final defeat from evil within our own tribe.  It was then that the confessors amongst us arose, preserving the tribe by banishing out those who would destroy their own kind.  They not only keep us in tune with the spirits, but they also preserve the flesh.$B$BGo forth into Zul'Gurub and witness first hand the depravity of Hakkar and the Gurubashi.  Wrest the Paragons of Power that we seek from them; success will be rewarded!",logDesc="Bring Al'tabim the All-Seeing a Primal Hakkari Sash.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.$B$BAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19842,qty=1}}} end
if not DB[8071] then DB[8071]={id=8071,zoneId=19,name="Paragons of Power: The Confessor's Mantle",level=60,minLevel=58,giver="Al'tabim the All-Seeing",giverType="NPC",giverId=14903,ender="Al'tabim the All-Seeing",enderType="NPC",enderId=14903,poiX=-11854,poiY=1242,wowhead="https://www.wowhead.com/wotlk/quest=8071",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The confessors of the Zandalar all wear a distinctive mantle, marking them as the preservers of the tribe.  These mantles are woven with powerful mojo that aids them in judging those who would threaten our tribe.  As a priest, you too must spend your time judging those worthy and not; such a mantle would definitely be a blessing to you.$B$BIn exchange for fighting Hakkar's minions in Zul'Gurub and bringing me the Paragons of Power I seek, I will give you a mantle worthy of our finest confessors.",logDesc="Bring Al'tabim the All-Seeing a Primal Hakkari Aegis.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.$B$BAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19841,qty=1}}} end
if not DB[8072] then DB[8072]={id=8072,zoneId=19,name="Paragons of Power: The Madcap's Mantle",level=60,minLevel=58,giver="Falthir the Sightless",giverType="NPC",giverId=14905,ender="Falthir the Sightless",enderType="NPC",enderId=14905,poiX=-11752,poiY=1322,wowhead="https://www.wowhead.com/wotlk/quest=8072",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One of Zandalar's legendary madcaps was Khar'vaxal the Cracked.  Legend states that when facing the enemies of the tribe for the first time, Kar'xavan used his mantle specifically woven with \"the weave of madness\".  His form was shrouded not only by the mantle, but also with the blinding speed of his twin daggers.  Madcaps today cherish their mantle as a sign of their place in the tribe.$B$BBring to me the Paragons of Power I seek, and such a mantle will be yours to weave madness unto your own enemies.",logDesc="Bring Falthir the Sightless a Primal Hakkari Girdle.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.$B$BFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19835,qty=1}}} end
if not DB[8073] then DB[8073]={id=8073,zoneId=19,name="Paragons of Power: The Madcap's Tunic",level=60,minLevel=58,giver="Falthir the Sightless",giverType="NPC",giverId=14905,ender="Falthir the Sightless",enderType="NPC",enderId=14905,poiX=-11752,poiY=1322,wowhead="https://www.wowhead.com/wotlk/quest=8073",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My eyes failed me long ago, but I do not miss them.  Even in a tribe such as ours - where one's vestments convey station and purpose - the most potent of garb exudes power that simple eyes cannot see.  The prized tunic of the Zandalar madcap is no exception, exuding the raw power of chaos and madness that they are able to channel.$B$BThe Paragons of Power I need lie in Zul'Gurub; bring me what I seek, and I will reward you with your own legendary tunic... one befitting a weaver of madness.",logDesc="Bring Falthir the Sightless a Primal Hakkari Aegis.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.$B$BFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19834,qty=1}}} end
if not DB[8074] then DB[8074]={id=8074,zoneId=19,name="Paragons of Power: The Augur's Belt",level=60,minLevel=58,giver="Maywiki of Zuldazar",giverType="NPC",giverId=14904,ender="Maywiki of Zuldazar",enderType="NPC",enderId=14904,poiX=-11850,poiY=1245,wowhead="https://www.wowhead.com/wotlk/quest=8074",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Augurs know the mojo of the elements, mon.  They use it as a means to guide the tribe to glory.  In the dark days after the Gurubashi Empire ripped itself up, our augurs led us to our safe haven in the South Seas.  They've also led us back here to the Vale, right back to the heart of evil brewin' in Zul'Gurub.$B$BBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!",logDesc="Bring Maywiki of Zuldazar a Primal Hakkari Girdle.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.$B$BMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19829,qty=1}}} end
if not DB[8075] then DB[8075]={id=8075,zoneId=19,name="Paragons of Power: The Augur's Hauberk",level=60,minLevel=58,giver="Maywiki of Zuldazar",giverType="NPC",giverId=14904,ender="Maywiki of Zuldazar",enderType="NPC",enderId=14904,poiX=-11850,poiY=1245,wowhead="https://www.wowhead.com/wotlk/quest=8075",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The augurs of the Zandalar all wear a distinctive chest piece called a hauberk.  It's fitted with the finest of silks and cloths, interwoven with strong chain.  It's a symbol of not only their divinity, but also of their authority, mon.  It's never wise to cross one whose life is devoted to speakin' with the spirits...$B$BBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do it and I'll give ya one of the finest hauberks our augurs would ever hope to wear!",logDesc="Bring Maywiki of Zuldazar a Primal Hakkari Tabard.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.$B$BMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19828,qty=1}}} end
if not DB[8076] then DB[8076]={id=8076,zoneId=19,name="Paragons of Power: The Demoniac's Mantle",level=60,minLevel=58,giver="Al'tabim the All-Seeing",giverType="NPC",giverId=14903,ender="Al'tabim the All-Seeing",enderType="NPC",enderId=14903,poiX=-11854,poiY=1242,wowhead="https://www.wowhead.com/wotlk/quest=8076",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The demoniac seeks to embody power outright, not just possess it.  More than one of our demoniacs has lost a fight with a demon; with our enemies threatening us - especially in Zul'Gurub - the power that a demoniac is able to unleash on our foes is worth the sacrifice.  Our survival depends on crushing those who would destroy us; the fall of the Gurubashi Empire taught us this.$B$BTravel to Zul'Gurub and gain the Paragons of Power we need.  Do this, and a valuable demoniac item shall be yours.",logDesc="Bring Al'tabim the All-Seeing a Primal Hakkari Sash.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.$B$BAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19849,qty=1}}} end
if not DB[8077] then DB[8077]={id=8077,zoneId=19,name="Paragons of Power: The Demoniac's Robes",level=60,minLevel=58,giver="Al'tabim the All-Seeing",giverType="NPC",giverId=14903,ender="Al'tabim the All-Seeing",enderType="NPC",enderId=14903,poiX=-11854,poiY=1242,wowhead="https://www.wowhead.com/wotlk/quest=8077",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The ultimate symbol of power amongst the tribe is the garb we wear in battle.  A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric.  The visage of the robe is said to instill fear into the minds of all who see it... especially the demons that the demoniac will eventually dominate.$B$BFrom Zul'Gurub, you must bring me a very specific set of the Paragons of Power.  It will be difficult... but your success will assure you of acquiring a robe for yourself.",logDesc="Bring Al'tabim the All-Seeing a Primal Hakkari Kossack.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.$B$BAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=20033,qty=1}}} end
if not DB[8078] then DB[8078]={id=8078,zoneId=19,name="Paragons of Power: The Vindicator's Belt",level=60,minLevel=58,giver="Jin'rokh the Breaker",giverType="NPC",giverId=14902,ender="Jin'rokh the Breaker",enderType="NPC",enderId=14902,poiX=-11783,poiY=1244,wowhead="https://www.wowhead.com/wotlk/quest=8078",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The ultimate vengeance waits within Zul'Gurub.  Hakkar must not rise again.  Hakkar destroyed the Gurubashi Empire from within.  No sacrifice was enough.  The trolls are a shadow of former glories.  I know this is because of Hakkar.$B$BBecome the vindicator you were meant to be.  Wreak havoc on the minions of evil.  Zul'Gurub must taste Zandalar vengeance.  Bring me proof in the Paragons of Power.  You will receive the vindicator's belt.  You will receive real power.$B$BGo.",logDesc="Bring Jin'rokh the Breaker a Primal Hakkari Girdle.  You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.$B$BJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19823,qty=1}}} end
if not DB[8079] then DB[8079]={id=8079,zoneId=19,name="Paragons of Power: The Vindicator's Breastplate",level=60,minLevel=58,giver="Jin'rokh the Breaker",giverType="NPC",giverId=14902,ender="Jin'rokh the Breaker",enderType="NPC",enderId=14902,poiX=-11783,poiY=1244,wowhead="https://www.wowhead.com/wotlk/quest=8079",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The vindicator's symbol of power is the breastplate.  It is forged with powerful mojo.  It is trusted only to those we revere.  It is the Zandalar symbol of vengeance.$B$BTo become a vindicator is to become vengeance.  Take the Paragons of Power we need from Zul'Gurub.  Bring them to us.  We will take the mojo stolen from us.  We will make the minions of Hakkar pay.  We will reward you with the vindicator's breastplate.$B$BGo.  Be our vengeance, $N.",logDesc="Bring Jin'rokh the Breaker a Primal Hakkari Kossack.  You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.$B$BJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",rewards={{id=19822,qty=1}}} end
if not DB[8080] then DB[8080]={id=8080,zoneId=3358,name="Arathi Basin Resources!",level=55,minLevel=50,giver="Sergeant Maclear",giverType="NPC",giverId=14984,ender="Sergeant Maclear",enderType="NPC",enderId=14984,poiX=-1220,poiY=-2518,wowhead="https://www.wowhead.com/wotlk/quest=8080",image="assets/images/quests/placeholder.png",xpDiff=5,money=25000,desc="War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!$B$BThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.$B$BThat is what I want from you, $N.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",logDesc="Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe."} end
