if not DB[8119] then DB[8119]={id=8119,zoneId=1977,name="The Unmarred Vision of Voodress",level=60,minLevel=58,giver="Maywiki of Zuldazar",giverType="NPC",giverId=14904,ender="Maywiki of Zuldazar",enderType="NPC",enderId=14904,poiX=-11850,poiY=1245,wowhead="https://www.wowhead.com/wotlk/quest=8119",image="assets/images/quests/placeholder.png",xpDiff=5,rewards={{id=19609,qty=1}}} end
if not DB[8120] then DB[8120]={id=8120,zoneId=3358,name="The Battle for Arathi Basin!",level=55,minLevel=50,giver="Deathmaster Dwire",giverType="NPC",giverId=15021,ender="Deathmaster Dwire",enderType="NPC",enderId=15021,poiX=-847,poiY=-3504,wowhead="https://www.wowhead.com/wotlk/quest=8120",image="assets/images/quests/placeholder.png",xpDiff=5,money=16500,desc="As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!$B$BGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.$B$BGo, $N.  Report back to me when this task is complete.",logDesc="Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall."} end
if not DB[8121] then DB[8121]={id=8121,zoneId=3358,name="Take Four Bases",level=60,minLevel=60,giver="Deathmaster Dwire",giverType="NPC",giverId=15021,ender="Deathmaster Dwire",enderType="NPC",enderId=15021,poiX=-847,poiY=-3504,wowhead="https://www.wowhead.com/wotlk/quest=8121",image="assets/images/quests/placeholder.png",xpDiff=7,money=27000,desc="$N, as the battles over Arathi Basin rage, news of your actions have reached many ears.  You are highly regarded among us, which gives me confidence that you will accomplish the mission I now have for you.$B$BIt is time to send a message to the League of Arathor.  We must show them that their holdings in Arathi Basin are tenuous and quickly lost.  We will show them this by holding, all at once, four strategic points in Arathi Basin.$B$BSucceed in this, $N, and earn great respect among the Defilers.",logDesc="Hold four bases at the same time in Arathi Basin, and then return to Deathmaster Dwire in Hammerfall."} end
if not DB[8122] then DB[8122]={id=8122,zoneId=3358,name="Take Five Bases",level=60,minLevel=60,giver="Deathmaster Dwire",giverType="NPC",giverId=15021,ender="Deathmaster Dwire",enderType="NPC",enderId=15021,poiX=-847,poiY=-3504,wowhead="https://www.wowhead.com/wotlk/quest=8122",image="assets/images/quests/placeholder.png",xpDiff=7,money=27000,desc="It is difficult to see, so deep we are in the conflict, but our spies report a weakening in the League of Arathor's resolve.  We must use this window and strike a brutal blow against them!  Return to Arathi Basin and throw yourself against our foes.  Curse them and kill them and control all five strategic bases!  Send their soldiers screaming and bleeding from the front lines, with stories of your cruelty on their mewling lips.$B$BDo this, and score a great victory for the Defilers.",logDesc="Hold five bases in Arathi Basin at the same time, then return to Deathmaster Dwire in Hammerfall.",rewards={{id=20131,qty=1}}} end
if not DB[8123] then DB[8123]={id=8123,zoneId=3358,name="Cut Arathor Supply Lines",level=55,minLevel=50,giver="Deathstalker Mortis",giverType="NPC",giverId=15022,ender="Deathstalker Mortis",enderType="NPC",enderId=15022,poiX=-848,poiY=-3511,wowhead="https://www.wowhead.com/wotlk/quest=8123",image="assets/images/quests/placeholder.png",xpDiff=5,money=25000,desc="The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.$B$BYou can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.",logDesc="Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall."} end
