if not DB[8149] then DB[8149]={id=8149,zoneId=-22,name="Honoring a Hero",level=-1,minLevel=30,giver="Wagner Hammerstrike",giverType="NPC",giverId=15011,ender="Wagner Hammerstrike",enderType="NPC",enderId=15011,poiX=-5060,poiY=-789,wowhead="https://www.wowhead.com/wotlk/quest=8149",image="assets/images/quests/placeholder.png",xpDiff=5,desc="During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf.  The Alliance acknowledges many heroes, but none weave a more tragic tale than that of Uther Lightbringer.$B$BHelp us honor Uther by taking this offering to his tomb in the Western Plaguelands.  Place it at his statue, and then return to me.  I'll only be here through the end of the festival, so waste no time in giving Uther his tribute.",logDesc="Travel to Uther's Tomb in Western Plaguelands and use Uther's Tribute at his statue, and then return to Wagner Hammerstrike outside Ironforge before the Harvest Festival is over.",rewards={{id=20009,qty=1}}} end
if not DB[8150] then DB[8150]={id=8150,zoneId=-22,name="Honoring a Hero",level=-1,minLevel=30,giver="Javnir Nashak",giverType="NPC",giverId=15012,ender="Javnir Nashak",enderType="NPC",enderId=15012,poiX=1323,poiY=-4400,wowhead="https://www.wowhead.com/wotlk/quest=8150",image="assets/images/quests/placeholder.png",xpDiff=5,desc="During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf.  The Horde acknowledges many heroes, but none exemplify strength and sacrifice more than Grom Hellscream.$B$BHelp us honor Grom by taking this offering to his monument in the Demon Fall Canyon of Ashenvale.  Place it at the base, and then return to me.  I'll only be here through the end of the festival, so waste no time in giving Grom his tribute.",logDesc="Travel to Grom's Monument in the Demon Fall Canyon of Ashenvale and use Grom's Tribute at the base of the monument.  Return to Javnir Nashak outside Orgrimmar before the Harvest Festival is over.",rewards={{id=20010,qty=1}}} end
if not DB[8151] then DB[8151]={id=8151,zoneId=-261,name="The Hunter's Charm",level=52,minLevel=50,giver="Holt Thunderhorn",giverType="NPC",giverId=3039,ender="Ogtinc",enderType="NPC",enderId=8405,rewardNextId=8153,poiX=-1475,poiY=-81,wowhead="https://www.wowhead.com/wotlk/quest=8151",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Ogtinc of Azshara has sent out a call for seasoned hunters such as yourself.  He is a furbolg hunter who has left his tribe to aid the Cenarion Circle.  His teachings are meant to enrich the wisdom of others who share his craft, and guide them toward maintaining a balance.  You would do well to speak with him.$b$bOgtinc resides atop the cliffs of Azshara, northeast from the Ruins of Eldarath.",logDesc="Speak to Ogtinc in Azshara."} end
if not DB[8152] then DB[8152]={id=8152,zoneId=-261,name="REUSE",level=52,minLevel=50,rewardNextId=8151,wowhead="https://www.wowhead.com/wotlk/quest=8152",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N,when you feel you are ready,there is a wisened furbolg hunter by the name of Ogtinc who resides in Azshara.  He may be able to enhance your teaching,and provide you with guidance.$b$bOgtinc is atop the cliffs northeast the Ruins of Eldarath in Azshara.",logDesc="Speak with Ogtinc in Azshara."} end
if not DB[8153] then DB[8153]={id=8153,zoneId=-261,name="Courser Antlers",level=52,minLevel=50,giver="Ogtinc",giverType="NPC",giverId=8405,ender="Ogtinc",enderType="NPC",enderId=8405,rewardNextId=8231,poiX=3901,poiY=-5427,wowhead="https://www.wowhead.com/wotlk/quest=8153",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The courser wears the mightiest antlers in the known lands.  Such antlers are used to defend the courser, goring an attacker and often damaging the points.  Perfect, natural antlers are the sign of an animal spirit with supreme confidence.$b$bTo hold such antlers will bestow the same confidence in you.$b$bHunt the mosshoof courser, find the perfect antlers and bring them to me.",logDesc="Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath."} end
if not DB[8154] then DB[8154]={id=8154,zoneId=3358,name="Arathi Basin Resources!",level=45,minLevel=40,giver="Sergeant Maclear",giverType="NPC",giverId=14984,ender="Sergeant Maclear",enderType="NPC",enderId=14984,poiX=-1220,poiY=-2518,wowhead="https://www.wowhead.com/wotlk/quest=8154",image="assets/images/quests/placeholder.png",xpDiff=5,money=19500,desc="War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!$B$BThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.$B$BThat is what I want from you, $N.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",logDesc="Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe."} end
