if not DB[8160] then DB[8160]={id=8160,zoneId=3358,name="Cut Arathor Supply Lines",level=45,minLevel=40,giver="Deathstalker Mortis",giverType="NPC",giverId=15022,ender="Deathstalker Mortis",enderType="NPC",enderId=15022,poiX=-848,poiY=-3511,wowhead="https://www.wowhead.com/wotlk/quest=8160",image="assets/images/quests/placeholder.png",xpDiff=5,money=19500,desc="The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.$B$BYou can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.",logDesc="Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall."} end
if not DB[8161] then DB[8161]={id=8161,zoneId=3358,name="Cut Arathor Supply Lines",level=35,minLevel=30,giver="Deathstalker Mortis",giverType="NPC",giverId=15022,ender="Deathstalker Mortis",enderType="NPC",enderId=15022,poiX=-848,poiY=-3511,wowhead="https://www.wowhead.com/wotlk/quest=8161",image="assets/images/quests/placeholder.png",xpDiff=5,money=11000,desc="The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.$B$BYou can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.",logDesc="Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall."} end
