if not DB[8166] then DB[8166]={id=8166,zoneId=3358,name="The Battle for Arathi Basin!",level=45,minLevel=40,giver="Field Marshal Oslight",giverType="NPC",giverId=14983,ender="Field Marshal Oslight",enderType="NPC",enderId=14983,poiX=-1224,poiY=-2516,wowhead="https://www.wowhead.com/wotlk/quest=8166",image="assets/images/quests/placeholder.png",xpDiff=5,money=13000,desc="$N, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.$B$BAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!$B$BWhen you have done this to all four points, return to me.",logDesc="Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe."} end
if not DB[8167] then DB[8167]={id=8167,zoneId=3358,name="The Battle for Arathi Basin!",level=35,minLevel=30,giver="Field Marshal Oslight",giverType="NPC",giverId=14983,ender="Field Marshal Oslight",enderType="NPC",enderId=14983,poiX=-1224,poiY=-2516,wowhead="https://www.wowhead.com/wotlk/quest=8167",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="$N, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.$B$BAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!$B$BWhen you have done this to all four points, return to me.",logDesc="Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe."} end
if not DB[8168] then DB[8168]={id=8168,zoneId=3358,name="The Battle for Arathi Basin!",level=25,minLevel=20,giver="Field Marshal Oslight",giverType="NPC",giverId=14983,ender="Field Marshal Oslight",enderType="NPC",enderId=14983,poiX=-1224,poiY=-2516,wowhead="https://www.wowhead.com/wotlk/quest=8168",image="assets/images/quests/placeholder.png",xpDiff=5,money=3500,desc="$N, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.$B$BAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!$B$BWhen you have done this to all four points, return to me.",logDesc="Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe."} end
if not DB[8169] then DB[8169]={id=8169,zoneId=3358,name="The Battle for Arathi Basin!",level=45,minLevel=40,giver="Deathmaster Dwire",giverType="NPC",giverId=15021,ender="Deathmaster Dwire",enderType="NPC",enderId=15021,poiX=-847,poiY=-3504,wowhead="https://www.wowhead.com/wotlk/quest=8169",image="assets/images/quests/placeholder.png",xpDiff=5,money=13000,desc="As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!$B$BGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.$B$BGo, $N.  Report back to me when this task is complete.",logDesc="Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall."} end
if not DB[8170] then DB[8170]={id=8170,zoneId=3358,name="The Battle for Arathi Basin!",level=35,minLevel=30,giver="Deathmaster Dwire",giverType="NPC",giverId=15021,ender="Deathmaster Dwire",enderType="NPC",enderId=15021,poiX=-847,poiY=-3504,wowhead="https://www.wowhead.com/wotlk/quest=8170",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!$B$BGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.$B$BGo, $N.  Report back to me when this task is complete.",logDesc="Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall."} end
if not DB[8171] then DB[8171]={id=8171,zoneId=3358,name="The Battle for Arathi Basin!",level=25,minLevel=20,giver="Deathmaster Dwire",giverType="NPC",giverId=15021,ender="Deathmaster Dwire",enderType="NPC",enderId=15021,poiX=-847,poiY=-3504,wowhead="https://www.wowhead.com/wotlk/quest=8171",image="assets/images/quests/placeholder.png",xpDiff=5,money=3500,desc="As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!$B$BGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.$B$BGo, $N.  Report back to me when this task is complete.",logDesc="Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall."} end
if not DB[8181] then DB[8181]={id=8181,zoneId=19,name="Confront Yeh'kinya",level=58,minLevel=40,giver="Prospector Ironboot",giverType="NPC",giverId=10460,ender="Yeh'kinya",enderType="NPC",enderId=8579,poiX=-6980,poiY=-4834,wowhead="https://www.wowhead.com/wotlk/quest=8181",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My delvings into the Mosh'aru Tablets bear grim news, $N.  Hakkar's true form, the god himself, can be born again through the very egg into which you captured him.  Yeh'kinya told you it was to contain his evil, but it is to recreate it!  The troll has led you astray!$B$BGo to Yeh'kinya and demand the egg from him.  Pray that it is not too late to stop Hakkar's return!",logDesc="Speak with Yeh'kinya.",choiceRewards={{id=20218,qty=1},{id=20219,qty=1}}} end
if not DB[8182] then DB[8182]={id=8182,zoneId=440,name="The Hand of Rastakhan",level=58,minLevel=40,giver="Prospector Ironboot",giverType="NPC",giverId=10460,ender="Molthor",enderType="NPC",enderId=14875,poiX=-6980,poiY=-4834,wowhead="https://www.wowhead.com/wotlk/quest=8182",image="assets/images/quests/placeholder.png",xpDiff=7,desc="$N, our worst fears have come.  Legend speaks of the Soulflayer ruling the ancient troll world through evil and terror, and his power was absolute.  If he cannot be stopped now, then his new reign may spread across all of Azeroth!$B$BThere is a contingent of Zandalarian trolls who may help us stem this tide of darkness.  They have camped on Yojamba Isle, off the coast of Stranglethorn, west of the ruins of Zul'Kunda.  Speak with their leader, Molthor, and pray he knows how to defeat Hakkar.",logDesc="Speak with Molthor in Stranglethorn."} end
if not DB[8183] then DB[8183]={id=8183,zoneId=19,name="The Heart of Hakkar",level=60,minLevel=58,giver="Heart of Hakkar",giverType="NPC",giverId=15069,ender="Molthor",enderType="NPC",enderId=14875,wowhead="https://www.wowhead.com/wotlk/quest=8183",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The Heart of Hakkar burns from within.  Although the Soulflayer is defeated, the kernel of his power yet remains in this cursed organ.",logDesc="Bring the Heart of Hakkar to Molthor on Yojamba Isle.",choiceRewards={{id=19948,qty=1},{id=19950,qty=1},{id=19949,qty=1}}} end
