if not DB[8227] then DB[8227]={id=8227,zoneId=19,name="Nat's Measuring Tape",level=60,minLevel=58,ender="Nat Pagle",enderType="NPC",enderId=12919,wowhead="https://www.wowhead.com/wotlk/quest=8227",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Amongst the shattered fishing lures and tackle is a rolled, silken measuring tape.  Attached to the tape is a label that reads:$B$B\"Nat Pagle, Dustwallow Marsh.\"",logDesc="Return Nat's Measuring Tape to Nat Pagle in Dustwallow Marsh."} end
