if not DB[8231] then DB[8231]={id=8231,zoneId=-261,name="Wavethrashing",level=52,minLevel=50,giver="Ogtinc",giverType="NPC",giverId=8405,ender="Ogtinc",enderType="NPC",enderId=8405,rewardNextId=8232,poiX=3901,poiY=-5427,wowhead="https://www.wowhead.com/wotlk/quest=8231",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The wavethrasher is an amphibious beast living only here in Azshara.  They are powerful and resilient.$b$bThe tough, reflective scales from a wavethrasher mirror the strength of the hunter.$b$bTrack and hunt wavethrashers along the coast of Azshara, and bring me their scales.",logDesc="Bring 6 Wavethrasher Scales to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."} end
if not DB[8232] then DB[8232]={id=8232,zoneId=-261,name="The Green Drake",level=52,minLevel=50,giver="Ogtinc",giverType="NPC",giverId=8405,ender="Ogtinc",enderType="NPC",enderId=8405,poiX=3901,poiY=-5427,wowhead="https://www.wowhead.com/wotlk/quest=8232",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Now I set you on a dangerous hunt to slay the green drake, Morphaz, and bring his tooth to me.  Morphaz dwells deep in Temple of Atal'Hakkar, the entrance to which lies in Swamp of Sorrows.$b$bIf you wish to defeat him, you must not go alone.  This drake is an enemy of many -- seek others who wish to destroy him.$b$bThe drake's tooth represents the power a hunter will find in the company of others.  Bring it to me and you will have learned much.",logDesc="Bring the Tooth of Morphaz to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",choiceRewards={{id=20083,qty=1},{id=19991,qty=1},{id=19992,qty=1}}} end
if not DB[8233] then DB[8233]={id=8233,zoneId=-162,name="A Simple Request",level=52,minLevel=50,giver="Osborne the Night Man",giverType="NPC",giverId=918,ender="Lord Jorach Ravenholdt",enderType="NPC",enderId=6768,rewardNextId=8234,poiX=-8752,poiY=378,wowhead="https://www.wowhead.com/wotlk/quest=8233",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Lord Jorach Ravenholdt has requested your presence.  The matter is secret, and I cannot say any more.$b$bRavenholdt Manor is located in the Hillsbrad Foothills -- look for a path in the mountains northwest of Durnhold Keep.",logDesc="Speak with Lord Jorach Ravenholdt in Ravenholdt Manor."} end
if not DB[8234] then DB[8234]={id=8234,zoneId=-162,name="Sealed Azure Bag",level=52,minLevel=50,giver="Lord Jorach Ravenholdt",giverType="NPC",giverId=6768,ender="Archmage Xylem",enderType="NPC",enderId=8379,rewardNextId=8235,poiX=28,poiY=-1625,wowhead="https://www.wowhead.com/wotlk/quest=8234",image="assets/images/quests/placeholder.png",xpDiff=5,money=6000,desc="First things first.  What I've lost is a small blue bag, the contents of which are a private matter.$b$bDon't bother going after the thieves, because they are already dead.  What we do know is the fools couldn't get the bag open. so they sold it to some timbermaw shaman in Azshara as a holy relic.  Clever.$b$bI need you to travel to Azshara and retrieve it from the shaman through subtlety... or force.  Better luck with the first method, I'd wager.  Once acquired, take it to Archmage Xylem.",logDesc="Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara.  Then take the bag to Archmage Xylem, also found in Azshara."} end
if not DB[8235] then DB[8235]={id=8235,zoneId=-162,name="Encoded Fragments",level=52,minLevel=50,giver="Archmage Xylem",giverType="NPC",giverId=8379,ender="Archmage Xylem",enderType="NPC",enderId=8379,rewardNextId=8236,poiX=3982,poiY=-4760,wowhead="https://www.wowhead.com/wotlk/quest=8235",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="Lord Ravenholdt has asked a favor of us both.  He wishes to remove the enchantment from this bag.$b$bUnfortunately, some of my books on the subject of dispelling were taken recently, only to be destroyed by savages.  The remains of my books are still valuable to me.$b$bIf you can bring me enough of the encoded fragments, I can piece them back together.  Your best chance is to kill the beasts of Azshara, since they have a tendency to pick up just about anything.",logDesc="Bring 10 Encoded Fragments to Archmage Xylem in Azshara."} end
if not DB[8236] then DB[8236]={id=8236,zoneId=-162,name="The Azure Key",level=52,minLevel=50,giver="Archmage Xylem",giverType="NPC",giverId=8379,ender="Lord Jorach Ravenholdt",enderType="NPC",enderId=6768,poiX=3982,poiY=-4760,wowhead="https://www.wowhead.com/wotlk/quest=8236",image="assets/images/quests/placeholder.png",xpDiff=7,money=7500,desc="It will take some time to decipher the fragments and remove the enchantment.  When I am complete, I'll deliver the bag to Lord Ravenholdt personally.$b$bThere is still the matter of the key, said to be held by a green drake known as Morphaz.  The drake has made its home deep in the Temple of Atal'Hakkar, the entrance to which lies in the Swamp of Sorrows.$b$bGather your friends and venture to his lair.  Lord Ravenholdt will await your return with the key.",logDesc="Return the Azure Key to Lord Jorach Ravenholdt.",choiceRewards={{id=19984,qty=1},{id=20255,qty=1},{id=19982,qty=1}}} end
