if not DB[8249] then DB[8249]={id=8249,zoneId=-162,name="Junkboxes Needed",level=60,minLevel=50,giver="Fahrad",giverType="NPC",giverId=6707,ender="Fahrad",enderType="NPC",enderId=6707,poiX=1,poiY=-1581,wowhead="https://www.wowhead.com/wotlk/quest=8249",image="assets/images/quests/placeholder.png",rewards={{id=25878,qty=1}}} end
if not DB[8250] then DB[8250]={id=8250,zoneId=-161,name="Magecraft",level=52,minLevel=50,giver="Archmage Shymm",giverType="NPC",giverId=3047,ender="Sanath Lim-yo",enderType="NPC",enderId=8395,poiX=-951,poiY=279,wowhead="https://www.wowhead.com/wotlk/quest=8250",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Archmage Xylem has been asking around lately... for someone of your experience.$b$bIf you wish to seek him out, you can find him in Azshara.  His tower is built high atop the cliffs, and the only way up is a teleport spell invoked by his arrogant servant, Sanath Lim-yo.$b$bSanath makes camp below his master's tower.  To find him, travel to where Azshara's main road forks at the entrance to the Ruins of Eldarath.  From that spot, head directly north until you reach the cliffs.",logDesc="Seek out Sanath Lim-yo and gain passage to see Archmage Xylem."} end
if not DB[8251] then DB[8251]={id=8251,zoneId=-161,name="Magic Dust",level=52,minLevel=50,giver="Archmage Xylem",giverType="NPC",giverId=8379,ender="Archmage Xylem",enderType="NPC",enderId=8379,rewardNextId=8252,poiX=3982,poiY=-4760,wowhead="https://www.wowhead.com/wotlk/quest=8251",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The blood elves in Azshara have developed a method for pulverizing the magical items they acquire.  This glittering dust they produce differs from the components normally acquired by a disenchantment spell.$b$bWhen I sent my apprentice to trade for the dust, he was killed without hesitation.  For that, they must pay.$b$bThe time for talk is over, $N.  Find the blood elves along the cliffs of Azshara and use more \"persuasive\" methods to acquire their glittering dust.",logDesc="Bring 10 Glittering Dust to Archmage Xylem."} end
if not DB[8252] then DB[8252]={id=8252,zoneId=-161,name="The Siren's Coral",level=52,minLevel=50,giver="Archmage Xylem",giverType="NPC",giverId=8379,ender="Archmage Xylem",enderType="NPC",enderId=8379,rewardNextId=8253,poiX=3982,poiY=-4760,wowhead="https://www.wowhead.com/wotlk/quest=8252",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="Take a look around you.  The ruins and beaches are overrun with spitelash.  Recently, the wretched creatures have learned to recognize the rare components indigenous to Azshara.$b$bSpecifically, I speak of enchanted coral -- they are drawn to it by reasons unknown to me.  Now there is little coral left in the bay, and it is vital to my research.  I need you to separate some enchanted coral from the spitelash sirens and bring it to me.",logDesc="Collect 6 Enchanted Coral and return them to Archmage Xylem."} end
if not DB[8253] then DB[8253]={id=8253,zoneId=-161,name="Destroy Morphaz",level=52,minLevel=50,giver="Archmage Xylem",giverType="NPC",giverId=8379,ender="Archmage Xylem",enderType="NPC",enderId=8379,poiX=3982,poiY=-4760,wowhead="https://www.wowhead.com/wotlk/quest=8253",image="assets/images/quests/placeholder.png",xpDiff=7,money=15500,desc="There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz.$b$bYears ago, he overwhelmed me in a bold ambush and consumed my apprentice whole.  While the loss of an apprentice is not unknown to me, this particular one carried an arcane shard of unsurpassed size and quality.$b$bYou must gather powerful allies and delve into the temple.  Destroy Morphaz and recover the arcane shard from his ageless stomach.",logDesc="Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.",choiceRewards={{id=20035,qty=1},{id=20037,qty=1},{id=20036,qty=1}}} end
if not DB[8254] then DB[8254]={id=8254,zoneId=-262,name="Cenarion Aid",level=52,minLevel=50,giver="High Priestess Laurena",giverType="NPC",giverId=376,ender="Ogtinc",enderType="NPC",enderId=8405,rewardNextId=8255,poiX=-8512,poiY=862,wowhead="https://www.wowhead.com/wotlk/quest=8254",image="assets/images/quests/placeholder.png",xpDiff=1,desc="It is the way of the divine to help those in need.  The how is insignificant -- only the why matters.$b$bThe Cenarion Circle has such a need.  Speak with Ogtinc to lend aid to their plight.  He resides atop the cliffs to the northeast of the Ruins of Eldarath in Azshara.",logDesc="Seek out Ogtinc in Azshara."} end
if not DB[8255] then DB[8255]={id=8255,zoneId=-262,name="Of Coursers We Know",level=52,minLevel=50,giver="Ogtinc",giverType="NPC",giverId=8405,ender="Ogtinc",enderType="NPC",enderId=8405,rewardNextId=8256,poiX=3901,poiY=-5427,wowhead="https://www.wowhead.com/wotlk/quest=8255",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The mosshoof coursers of Azshara are magnificent animals who once lived in Felwood.  They naturally resist disease and poison, and were unaffected by the corruption there.  In their ancestral wisdom, they simply chose to leave that sickened place.$b$bIt saddens my heart, but I must ask you to hunt these mighty beasts for me.  Gather four courser glands as the first ingredient for a restorative salve -- a salve we will use to heal Felwood.",logDesc="Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."} end
if not DB[8256] then DB[8256]={id=8256,zoneId=-262,name="The Ichor of Undeath",level=52,minLevel=50,giver="Ogtinc",giverType="NPC",giverId=8405,ender="Ogtinc",enderType="NPC",enderId=8405,rewardNextId=8257,poiX=3901,poiY=-5427,wowhead="https://www.wowhead.com/wotlk/quest=8256",image="assets/images/quests/placeholder.png",xpDiff=5,desc="For this restorative salve, you must use a simple formula: one part poison, two parts cure.  You have acquired one cure, now you must gather the poison.$b$bPowerful undead, such as the lingering highborne who wander the Ruins of Eldarath, are sometimes so infused with evil that it coalesces into a sickly greenish goo.  To the living, this substance is known as ichor of undeath.$b$bDue to the potency of this vile element, I require only a single ichor.",logDesc="Acquire an Ichor of Undeath for Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."} end
if not DB[8257] then DB[8257]={id=8257,zoneId=-262,name="Blood of Morphaz",level=52,minLevel=50,giver="Ogtinc",giverType="NPC",giverId=8405,ender="Greta Mosshoof",enderType="NPC",enderId=10922,poiX=3901,poiY=-5427,wowhead="https://www.wowhead.com/wotlk/quest=8257",image="assets/images/quests/placeholder.png",xpDiff=7,money=15500,desc="Now the last part, the second cure.$b$bThe green drake Morphaz is known to be immune to all forms of poison and disease -- many druids died to bring us this information.  There is no doubt his blood is potent for our needs.$b$bA courier from the Cenarion Circle will take the parts you have already collected while you gather the last.  Summon your allies and seek out the drake's lair in the sunken temple of Atal'Hakkar.  Bring his blood to Greta Mosshoof in Felwood.",logDesc="Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood.  The entrance to the sunken temple can be found in the Swamp of Sorrows.",choiceRewards={{id=19990,qty=1},{id=20082,qty=1},{id=20006,qty=1}}} end
if not DB[8258] then DB[8258]={id=8258,zoneId=-82,name="The Darkreaver Menace",level=60,minLevel=58,giver="Sagorne Creststrider",giverType="NPC",giverId=13417,ender="Sagorne Creststrider",enderType="NPC",enderId=13417,poiX=1938,poiY=-4223,wowhead="https://www.wowhead.com/wotlk/quest=8258",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Death Knight Darkreaver lords over the Great Ossuary in the Scholomance.  He threatens to twist the spirit realm to do his own bidding, and he must be stopped!  This is where the scryer you helped make comes into play.$B$BUse the divination scryer in the heart of the Great Ossuary's basement to call forth Darkreaver's spirit minions.  Defeat the spirits and the death knight himself will appear.  $N, bring me his head!  Only his demise will reverse the damage done to the spirit realm!",logDesc="Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth spirits you must fight.  Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.$B$BBring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.",rewards={{id=20134,qty=1}}} end
if not DB[8259] then DB[8259]={id=8259,zoneId=-82,name="A More Fitting Reward",level=60,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=8259",image="assets/images/quests/placeholder.png",rewards={{id=20134,qty=1}}} end
