if not DB[8399] then DB[8399]={id=8399,zoneId=3277,name="Fight for Warsong Gulch",level=29,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=8399",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.$B$BThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.$B$BDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",logDesc="Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds."} end
if not DB[8400] then DB[8400]={id=8400,zoneId=3277,name="Fight for Warsong Gulch",level=39,minLevel=30,wowhead="https://www.wowhead.com/wotlk/quest=8400",image="assets/images/quests/placeholder.png",xpDiff=5,money=4500,desc="The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.$B$BThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.$B$BDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",logDesc="Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds."} end
if not DB[8401] then DB[8401]={id=8401,zoneId=3277,name="Fight for Warsong Gulch",level=49,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=8401",image="assets/images/quests/placeholder.png",xpDiff=5,money=7000,desc="The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than the preservationist philosophy the Silverwings espouse.$B$BThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.  Do your part in fighting the Warsong Outriders!  For the Alliance!",logDesc="Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds."} end
