if not DB[8409] then DB[8409]={id=8409,zoneId=-22,name="Ruined Kegs",level=-1,minLevel=30,ender="Darkcaller Yanka",enderType="NPC",enderId=15197,wowhead="https://www.wowhead.com/wotlk/quest=8409",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The rotten eggs have been successfully placed inside the keg.  Future batches of ale from the Southshore Inn are sure to be ruined!$B$BYou should now report back to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade and report your success.",logDesc="Return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.",rewards={{id=20557,qty=15}}} end
if not DB[8410] then DB[8410]={id=8410,zoneId=-82,name="Elemental Mastery",level=52,minLevel=50,giver="Haromm",giverType="NPC",giverId=986,ender="Bath'rah the Windwatcher",enderType="NPC",enderId=6176,rewardNextId=8412,poiX=-10507,poiY=-3328,wowhead="https://www.wowhead.com/wotlk/quest=8410",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Bath'rah the Windwatcher has sent out a summons for a shaman of your wisdom.  He requests you bring a sample of each of the elements to show you are ready.$b$bTo find Bath'rah, go to the river east of Tarren Mill.  Follow the river north until you come across the ruins where Bath'rah resides.",logDesc="Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher."} end
if not DB[8411] then DB[8411]={id=8411,zoneId=-82,name="Mastering the Elements",level=52,minLevel=50,rewardNextId=8412,wowhead="https://www.wowhead.com/wotlk/quest=8411",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Welcome, $c.  You bring me the elements and then we do the talkin'.$b$bThe fire, the air, the water, and the earth I be needin' before I trust ya, mon.  I gots to know you be knowledgeable.",logDesc="Bring the elements earth, air, fire and water to Bath'rah the Windwatcher."} end
if not DB[8412] then DB[8412]={id=8412,zoneId=-82,name="Spirit Totem",level=52,minLevel=50,giver="Bath'rah the Windwatcher",giverType="NPC",giverId=6176,ender="Bath'rah the Windwatcher",enderType="NPC",enderId=6176,poiX=251,poiY=-1471,wowhead="https://www.wowhead.com/wotlk/quest=8412",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The elemental spirits of this place don't be likin' me any more.$b$bYou know about the totems more than any, and I be needin' a spirit totem to protect me.  We already got the elements, now we need somethin' more with more nature.  More primal.$b$bIn the Western Plaguelands you can kill bears for claws and spiders for their eyes.  The carrion birds eat everything, so they might have either one.",logDesc="Bring the pieces for the spirit totem to Bath'rah the Windwatcher."} end
if not DB[8413] then DB[8413]={id=8413,zoneId=-82,name="Da Voodoo",level=52,minLevel=50,giver="Bath'rah the Windwatcher",giverType="NPC",giverId=6176,ender="Bath'rah the Windwatcher",enderType="NPC",enderId=6176,poiX=251,poiY=-1471,wowhead="https://www.wowhead.com/wotlk/quest=8413",image="assets/images/quests/placeholder.png",xpDiff=7,money=15500,desc="The spirit totem just isn't enough.  We be needin' some voodoo magic to make it work jus' right.$b$bThe trolls in the sunken temple have feathers strong with voodoo magics.  Go there and kill Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Then we have magic enough for a real spirit totem.",logDesc="Bring the voodoo feathers to Bath'rah the Windwatcher.",choiceRewards={{id=20369,qty=1},{id=20503,qty=1},{id=20556,qty=1}}} end
if not DB[8414] then DB[8414]={id=8414,zoneId=-141,name="Dispelling Evil",level=52,minLevel=50,giver="Commander Ashlam Valorfist",giverType="NPC",giverId=10838,ender="High Priest Thel'danis",enderType="NPC",enderId=1854,poiX=958,poiY=-1419,wowhead="https://www.wowhead.com/wotlk/quest=8414",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Greetings, $c.  Crusaders like you are a welcome sight in these desolate reaches.$b$bYour holy strength is needed to help fight the endless undead here.  We need you to collect a large number of scourgestones and bring them to High Priest Thel'danis.  The high priest can be found guarding Uther's Tomb in Sorrow Hill, not far from here.$b$bOnly one with an Argent Dawn Commission can hope to find scourgestones, so speak to Officer Pureheart if you haven't already.",logDesc="Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands."} end
if not DB[8415] then DB[8415]={id=8415,zoneId=-141,name="Chillwind Camp",level=52,minLevel=50,giver="Lord Grayson Shadowbreaker",giverType="NPC",giverId=928,ender="Commander Ashlam Valorfist",enderType="NPC",enderId=10838,rewardNextId=8414,poiX=-8577,poiY=882,wowhead="https://www.wowhead.com/wotlk/quest=8415",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Commander Ashlam Valorfist has sent out a call for a paladin of your purity and valor, $n.  You can find him at Chillwind Camp in the southern part of the Western Plaguelands.  Seek him and aid in his cause for the Light!",logDesc="Speak to Commander Ashlam Valorfist at Chillwind Camp."} end
if not DB[8416] then DB[8416]={id=8416,zoneId=-141,name="Inert Scourgestones",level=52,minLevel=50,giver="High Priest Thel'danis",giverType="NPC",giverId=1854,ender="Commander Ashlam Valorfist",enderType="NPC",enderId=10838,rewardNextId=8418,poiX=980,poiY=-1822,wowhead="https://www.wowhead.com/wotlk/quest=8416",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The evil has been purged from the stones, $n.$b$bI am aware of Commander Ashlam's plans, and he will require only a single inert stone.  Bring it to him so we may bathe the Scourge in righteous fire.",logDesc="Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point."} end
if not DB[8417] then DB[8417]={id=8417,zoneId=-81,name="A Troubled Spirit",level=52,minLevel=50,giver="Torm Ragetotem",giverType="NPC",giverId=3041,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,rewardNextId=8423,poiX=-1458,poiY=-81,wowhead="https://www.wowhead.com/wotlk/quest=8417",image="assets/images/quests/placeholder.png",xpDiff=1,desc="In the Blasted Lands, there is a troubled spirit who was once a great hero of the horde.  A warrior's honor does not die with the body, and it would serve you well to speak with him.",logDesc="Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands."} end
if not DB[8418] then DB[8418]={id=8418,zoneId=-141,name="Forging the Mightstone",level=52,minLevel=50,giver="Commander Ashlam Valorfist",giverType="NPC",giverId=10838,ender="Commander Ashlam Valorfist",enderType="NPC",enderId=10838,poiX=958,poiY=-1419,wowhead="https://www.wowhead.com/wotlk/quest=8418",image="assets/images/quests/placeholder.png",xpDiff=7,money=15500,desc="Now we must combine the inert scourgestones and create a weapon to shatter the ranks of undead.  This is no trivial task, $n.  Only the trolls of the sunken temple carry the kind of rare magic able to turn the evil of something against itself.$b$bIn the temple, the trolls are known as Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Do not feel remorse for their corrupt souls... they are not without evil.",logDesc="Collect Amber, Blue, and Green Voodoo Feathers from the trolls of Sunken Temple.",rewards={{id=20620,qty=1}},choiceRewards={{id=20504,qty=1},{id=20512,qty=1},{id=20505,qty=1}}} end
if not DB[8419] then DB[8419]={id=8419,zoneId=-61,name="An Imp's Request",level=52,minLevel=50,giver="Demisette Cloyce",giverType="NPC",giverId=461,ender="Impsy",enderType="NPC",enderId=14470,rewardNextId=8421,poiX=-8980,poiY=1041,wowhead="https://www.wowhead.com/wotlk/quest=8419",image="assets/images/quests/placeholder.png",xpDiff=4,desc="$n, an imp in Felwood by the name of Impsy has requested your presence.  It is somewhat strange, as he has asked that you bring a piece of felcloth as a sign of good faith.  Considering the power you already wield as a warlock, I can only assume you know the satyrs of Felwood carry this felcloth.$b$bYou can find Impsy just north of the Bloodvenom Falls, which I've heard is quite lovely this time of year.",logDesc="Bring a piece of felcloth to Impsy in Felwood."} end
if not DB[8420] then DB[8420]={id=8420,zoneId=-61,name="Hot and Itchy",level=52,minLevel=50,giver="Impsy",giverType="NPC",giverId=14470,ender="Impsy",enderType="NPC",enderId=14470,rewardNextId=8421,poiX=5408,poiY=-737,wowhead="https://www.wowhead.com/wotlk/quest=8420",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Maybe this sounds strange coming from an imp, but I'd like a pet of my own.  I really would.  It's just not fair that Niby gets me and I get nothing!$b$bIn fact, it doesn't even need to be a living pet.  I'd need something to start making it with, like some felcloth.  The satyrs here in Felwood sometimes have felcloth, so you'd just have to kill enough of them until you find some.  That doesn't sound so bad, does it?",logDesc="Bring a piece of felcloth to Impsy in Felwood."} end
if not DB[8421] then DB[8421]={id=8421,zoneId=-61,name="The Wrong Stuff",level=52,minLevel=50,giver="Impsy",giverType="NPC",giverId=14470,ender="Impsy",enderType="NPC",enderId=14470,rewardNextId=8422,poiX=5408,poiY=-737,wowhead="https://www.wowhead.com/wotlk/quest=8421",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now that I have my felcloth, I can really begin making *my* pet.$b$bIt's going to need some eyes though.  Perhaps you could rip some rotting wood from the irontree folk for me, so I can carve out some lovely eyes.  They're up north in the Irontree Woods.$b$bI'll also need some bloodvenom essence to give it that new demon smell.  The tainted oozes carry the essence, and they hang out right here near Niby and me.",logDesc="Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood."} end
if not DB[8422] then DB[8422]={id=8422,zoneId=-61,name="Trolls of a Feather",level=52,minLevel=50,giver="Impsy",giverType="NPC",giverId=14470,ender="Impsy",enderType="NPC",enderId=14470,poiX=5408,poiY=-737,wowhead="https://www.wowhead.com/wotlk/quest=8422",image="assets/images/quests/placeholder.png",xpDiff=7,money=15500,desc="My pet is almost done.  Now I just need something to stuff it with.$b$bOnly the voodoo feathers from the trolls in the sunken temple will do.  They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Kill them.  Kill them all.$b$bThis is no trivial task $n, so I'll make it worth your while by giving you something of Niby's -- he probably doesn't need it anyhow.",logDesc="Bring a total of 6 Voodoo Feathers from the trolls in sunken temple.",choiceRewards={{id=20536,qty=1},{id=20534,qty=1},{id=20530,qty=1}}} end
if not DB[8423] then DB[8423]={id=8423,zoneId=-81,name="Warrior Kinship",level=52,minLevel=50,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,rewardNextId=8424,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=8423",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<The Hero looks you over.>$b$bYou are a $c, no doubt.  I would ask an honorable task of you, but I must test your strength.$b$bIt is said that Rexxar would measure the sharpness of his blades by killing a helboar with a single, swift strike.  Now I will measure your strength by killing them.",logDesc="Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde."} end
if not DB[8424] then DB[8424]={id=8424,zoneId=-81,name="War on the Shadowsworn",level=52,minLevel=50,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,rewardNextId=8425,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=8424",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The continued presence of the shadowsworn in the Blasted Lands bring great pain to me.  Their dark rituals and spells cause agony unlike any I felt while alive.$b$bThrough you I can deliver my own message of pain.  Go forth and deliver my wrath.",logDesc="Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde."} end
if not DB[8425] then DB[8425]={id=8425,zoneId=-81,name="Voodoo Feathers",level=52,minLevel=50,giver="Fallen Hero of the Horde",giverType="NPC",giverId=7572,ender="Fallen Hero of the Horde",enderType="NPC",enderId=7572,poiX=-10632,poiY=-3009,wowhead="https://www.wowhead.com/wotlk/quest=8425",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Your honor has brought some peace to me.  It is only right that I offer you something in return.$b$bMy weapons and armor were splendid in life, and yet they are of no use to me now.  They would be better served in your possession.$b$bTravel to the sunken temple and destroy the troll guardians Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  They carry magic feathers that can reform my physical body long enough to grant you a reward.",logDesc="Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde.",choiceRewards={{id=20521,qty=1},{id=20130,qty=1},{id=20517,qty=1}}} end
if not DB[8426] then DB[8426]={id=8426,zoneId=3277,name="Battle of Warsong Gulch",level=29,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=8426",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.$B$BDo not let this happen, $N!  Come back to me with proof of serving the Horde in a worthy manner!",logDesc="Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds."} end
