if not DB[8446] then DB[8446]={id=8446,zoneId=-1,name="Shrouded in Nightmare",level=60,minLevel=60,ender="Keeper Remulos",enderType="NPC",enderId=11832,rewardNextId=8447,wowhead="https://www.wowhead.com/wotlk/quest=8446",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Corruption seeps from this object.$B$BThere may be a link between this object and the dragons coming forth from the Dream. You must find someone that can decipher the meaning of this item. Perhaps the druids of the Moonglade or Cenarion Hold could assist you further.",logDesc="Find someone capable of deciphering the meaning behind the Nightmare Engulfed Object.$B$BPerhaps a druid of great power could assist you."} end
if not DB[8447] then DB[8447]={id=8447,zoneId=-1,name="Waking Legends",level=60,minLevel=60,giver="Keeper Remulos",giverType="NPC",giverId=11832,ender="Keeper Remulos",enderType="NPC",enderId=11832,poiX=7848,poiY=-2216,wowhead="https://www.wowhead.com/wotlk/quest=8447",image="assets/images/quests/placeholder.png",desc="The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing, $N.",logDesc="Wait for Keeper Remulos at the Moonglade to cleanse the Nightmare Engulfed Object.",rewards={{id=20600,qty=1}}} end
