if not DB[8458] then DB[8458]={id=8458,zoneId=405,name="<UNUSED>",level=33,minLevel=25,rewardNextId=1482,wowhead="https://www.wowhead.com/wotlk/quest=8458",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I believe I can find this demon lord given the proper reagents.$B$BIf he is indeed as powerful as I suspect,I will need items gathered from deadly creatures. But you act in the Warchief's name,so I am sure you will accept my task.$B$BFirst,I will have to break any wards he has against scrying. For this,I will need the scalp from a satyr--but not any satyr. The scalp must come from a Hatefury shadowstalker.$B$BSearch for them among the ancient ruins in the northeast of Desolace.",logDesc="Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace."} end
if not DB[8459] then DB[8459]={id=8459,zoneId=0,name="<UNUSED>",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=8459",image="assets/images/quests/placeholder.png",desc="Description",logDesc="Log"} end
if not DB[8460] then DB[8460]={id=8460,zoneId=361,name="Timbermaw Ally",level=48,minLevel=45,giver="Grazle",giverType="NPC",giverId=11554,ender="Grazle",enderType="NPC",enderId=11554,poiX=3875,poiY=-1287,wowhead="https://www.wowhead.com/wotlk/quest=8460",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe. For this reason, the Timbermaw furbolg trust very few.$B$BAre you interested in proving yourself? Drive back the corrupted Deadwood tribe of Felwood and we may one day consider you an ally. You'll find the first Deadwood tribe - warriors, pathfinders and gardeners - to my west.",logDesc="Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners.  Return to him in southern Felwood near the Emerald Sanctuary when you are done.",choiceRewards={{id=21311,qty=1},{id=21312,qty=1}}} end
if not DB[8461] then DB[8461]={id=8461,zoneId=1769,name="Deadwood of the North",level=55,minLevel=45,giver="Nafien",giverType="NPC",giverId=15395,ender="Nafien",enderType="NPC",enderId=15395,poiX=6822,poiY=-2083,wowhead="https://www.wowhead.com/wotlk/quest=8461",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.$B$BThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  It saddens me that we must fight our own brethren.$B$BPlease, $N - I ask you to do what must be done.  Simply spare me the details; such troublesome images upset me far too much.",logDesc="Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans.  Return to him in northern Felwood near the entrance to Timbermaw Hold.",choiceRewards={{id=21316,qty=1},{id=21317,qty=1}}} end
if not DB[8462] then DB[8462]={id=8462,zoneId=361,name="Speak to Nafien",level=55,minLevel=45,giver="Grazle",giverType="NPC",giverId=11554,ender="Nafien",enderType="NPC",enderId=15395,poiX=3875,poiY=-1287,wowhead="https://www.wowhead.com/wotlk/quest=8462",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Perhaps you are capable of handling a larger threat that we Timbermaw face.  You certainly have shown yourself capable here...$B$BAnother of my kind stands guard outside the entrance to Timbermaw Hold, along this road far to the north.  His name is Nafien; while he may appear to be a feral and unsavory beast, fear him not.  He only seeks aid against the malign forces that threaten our home.",logDesc="Travel north along the main road in Felwood and speak with the furbolg named Nafien.  He stands guard outside the entrance to Timbermaw Hold."} end
if not DB[8463] then DB[8463]={id=8463,zoneId=3430,name="Unstable Mana Crystals",level=5,minLevel=4,giver="Aeldon Sunbrand",giverType="NPC",giverId=15403,ender="Aeldon Sunbrand",enderType="NPC",enderId=15403,rewardNextId=9352,poiX=9531,poiY=-6860,wowhead="https://www.wowhead.com/wotlk/quest=8463",image="assets/images/quests/placeholder.png",xpDiff=5,money=100,desc="A group of Wretched recently raided a supply of unstable mana crystals from one of our arcane sanctums.  If not handled properly, the crystals could explode with enough force to blow a hole into the city walls.$B$BNow, $N, I don't quite care if they blow themselves up while tapping unstable arcane sources, but the whole incident would make my men look bad.$B$BBring me back any remaining stolen crystals you find; they might still be inside their original crates.",logDesc="Bring back 6 Unstable Mana Crystals to Aeldon Sunbrand at Falconwing Square."} end
if not DB[8464] then DB[8464]={id=8464,zoneId=1769,name="Winterfall Activity",level=58,minLevel=45,giver="Salfa",giverType="NPC",giverId=11556,ender="Salfa",enderType="NPC",enderId=11556,poiX=6900,poiY=-2286,wowhead="https://www.wowhead.com/wotlk/quest=8464",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Timbermaw tend to stay to themselves, $N.  While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible.$B$BThe Winterfall tribe as of late has become increasingly hostile towards us.  They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.$B$BI must ask you to thin their numbers as to lessen the threat against us.  Seek them out in Winterfall Village, far to the east of here.",logDesc="Salfa wants you to kill 8 Winterfall Shaman, 8 Winterfall Den Watchers, and 8 Winterfall Ursa.  Salfa is located just outside the entrance to Timbermaw Hold in Winterspring.$B",choiceRewards={{id=21318,qty=1},{id=21319,qty=1},{id=21320,qty=1},{id=21322,qty=1}}} end
if not DB[8465] then DB[8465]={id=8465,zoneId=361,name="Speak to Salfa",level=55,minLevel=45,giver="Nafien",giverType="NPC",giverId=15395,ender="Salfa",enderType="NPC",enderId=11556,poiX=6822,poiY=-2083,wowhead="https://www.wowhead.com/wotlk/quest=8465",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The threat of corruption comes not only from the Deadwood furbolgs to the south, but also from the east and the Winterfall furbolgs of Winterspring.  If you wish to further aid us, speak with Salfa on the other side of the Hold, by the Winterspring entrance.  Follow the path to the left to reach it.$B$BBe warned - if my kind inside considers you hostile or hated, they will attack.  Travel as quick as you can, avoiding conflict.  To kill a Timbermaw - even in self defense - will only alienate you further.",logDesc="Travel through Timbermaw Hold and exit into Winterspring.  Speak with Salfa, who stands guard outside the entrance to Timbermaw Hold."} end
if not DB[8466] then DB[8466]={id=8466,zoneId=361,name="Feathers for Grazle",level=55,minLevel=45,giver="Grazle",giverType="NPC",giverId=11554,ender="Grazle",enderType="NPC",enderId=11554,poiX=3875,poiY=-1287,wowhead="https://www.wowhead.com/wotlk/quest=8466",image="assets/images/quests/placeholder.png"} end
if not DB[8467] then DB[8467]={id=8467,zoneId=361,name="Feathers for Nafien",level=55,minLevel=45,giver="Nafien",giverType="NPC",giverId=15395,ender="Nafien",enderType="NPC",enderId=15395,poiX=6822,poiY=-2083,wowhead="https://www.wowhead.com/wotlk/quest=8467",image="assets/images/quests/placeholder.png"} end
if not DB[8468] then DB[8468]={id=8468,zoneId=3430,name="Wanted: Thaelis the Hungerer",level=6,minLevel=4,ender="Sergeant Kan'ren",enderType="NPC",enderId=16924,wowhead="https://www.wowhead.com/wotlk/quest=8468",image="assets/images/quests/placeholder.png",xpDiff=5,money=250,desc="The city of Silvermoon hereby issues a reward for the head of Thaelis the Hungerer, notorious Wretched ringleader.  He is wanted for repeated crimes against the general populace of Silvermoon City, including the murder of two city guards.$B$BReport to Sergeant Kan'ren to collect the reward.",logDesc="Bring Thaelis's Head to Sergeant Kan'ren at Falconwing Square in Eversong Woods."} end
if not DB[8469] then DB[8469]={id=8469,zoneId=361,name="Beads for Salfa",level=56,minLevel=50,giver="Salfa",giverType="NPC",giverId=11556,ender="Salfa",enderType="NPC",enderId=11556,poiX=6900,poiY=-2286,wowhead="https://www.wowhead.com/wotlk/quest=8469",image="assets/images/quests/placeholder.png"} end
if not DB[8470] then DB[8470]={id=8470,zoneId=361,name="Deadwood Ritual Totem",level=55,minLevel=45,ender="Kernda",enderType="NPC",enderId=11558,wowhead="https://www.wowhead.com/wotlk/quest=8470",image="assets/images/quests/placeholder.png",xpDiff=5,money=8500,desc="You have found one of the Deadwood furbolg's ritual totems.  The totem itself is of non-descript construction, but a palpable sense of despair emanates from it.  If there were any object that might best exemplify the corruption that the Deadwood furbolg suffer under, this item would clearly be it.$B$BOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.$B",logDesc="Take the Deadwood Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item.  The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them.",rewards={{id=13446,qty=2},{id=13444,qty=2}}} end
if not DB[8471] then DB[8471]={id=8471,zoneId=618,name="Winterfall Ritual Totem",level=56,minLevel=50,ender="Kernda",enderType="NPC",enderId=11558,wowhead="https://www.wowhead.com/wotlk/quest=8471",image="assets/images/quests/placeholder.png",xpDiff=5,money=17000,desc="You have found one of the Winterfall furbolg's ritual totems.  The totem itself is of non-descript construction, but it seems to emanate an almost tangible sense of dread and despair.  If many of the Winterfall furbolgs do indeed carry these, it certainly would go a long way in explaining their current condition.$B$BOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.",logDesc="Take the Winterfall Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item.  The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them.",rewards={{id=13446,qty=3},{id=13444,qty=3}}} end
if not DB[8472] then DB[8472]={id=8472,zoneId=3430,name="Major Malfunction",level=5,minLevel=4,giver="Magister Jaronis",giverType="NPC",giverId=15418,ender="Magister Jaronis",enderType="NPC",enderId=15418,rewardNextId=8895,poiX=9521,poiY=-6815,wowhead="https://www.wowhead.com/wotlk/quest=8472",image="assets/images/quests/placeholder.png",xpDiff=5,money=100,desc="The arcane patrollers crafted by our forefathers to protect the city have fallen into a dangerous state of disrepair.  They fail to recognize us as their masters and will attack us on sight!$B$BEven though they were created many years ago, the arcane cores that power them are still quite useful and valuable to us.  I want you to gather these cores and bring them to me so I can put them to good use again.  You will find the patrollers in the ruined section of Silvermoon, to the northwest.",logDesc="Collect 6 Arcane Cores from the Arcane Patrollers that roam the ruins of Silvermoon City and bring them to Magister Jaronis at Falconwing Square in Eversong Woods.",choiceRewards={{id=24241,qty=1},{id=23367,qty=1},{id=27552,qty=1}}} end
if not DB[8473] then DB[8473]={id=8473,zoneId=3430,name="A Somber Task",level=9,minLevel=6,giver="Larianna Riverwind",giverType="NPC",giverId=15398,ender="Larianna Riverwind",enderType="NPC",enderId=15398,poiX=8414,poiY=-6165,wowhead="https://www.wowhead.com/wotlk/quest=8473",image="assets/images/quests/placeholder.png",xpDiff=5,money=300,desc="These are difficult times for us, $N.  It was a very hard decision to burn the woods bordering the Ghostlands to prevent the Scourge's expansion.$B$BThe treants, who have been our friends for years, are now trying to foster the regrowth of the forest along the Scorched Grove.$B$BThis is a painful thing to ask of you, $c, but we've failed to convince our former allies to cease their endeavors.  I need you to stop them by the only means that remain to us: force.",logDesc="Slay 10 Withered Green Keepers at the Scorched Grove.  Then report back to Larianna Riverwind inside the tower just to the northwest of the Scorched Grove in Eversong Woods."} end
if not DB[8474] then DB[8474]={id=8474,zoneId=3430,name="Old Whitebark's Pendant",level=10,minLevel=7,ender="Larianna Riverwind",enderType="NPC",enderId=15398,rewardNextId=10166,wowhead="https://www.wowhead.com/wotlk/quest=8474",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="The pendant has the initials L.R. etched on to it.  Perhaps these letters will lead to the pendant's maker.",logDesc="Find the person who might have made Old Whitebark's Pendant.  They might provide some insight on the item."} end
if not DB[8475] then DB[8475]={id=8475,zoneId=3430,name="The Dead Scar",level=6,minLevel=4,giver="Ranger Jaela",giverType="NPC",giverId=15416,ender="Ranger Jaela",enderType="NPC",enderId=15416,poiX=9375,poiY=-6967,wowhead="https://www.wowhead.com/wotlk/quest=8475",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The black swath of soil that cuts through Eversong Woods is a permanent reminder of the day Arthas led the Scourge into our beloved city.$B$BThis blemish is more than an eyesore as even today it brings Scourge from the Ghostlands to Silvermoon.$B$BGo, $N, and give my men a hand in killing the mindless undead that walk down the Dead Scar.",logDesc="Slay 8 Plaguebone Pillagers and report back to Ranger Jaela on the Dead Scar in Eversong Woods.",choiceRewards={{id=23375,qty=1},{id=23376,qty=1},{id=23377,qty=1}}} end
if not DB[8476] then DB[8476]={id=8476,zoneId=3430,name="Amani Encroachment",level=10,minLevel=7,giver="Lieutenant Dawnrunner",giverType="NPC",giverId=15399,ender="Lieutenant Dawnrunner",enderType="NPC",enderId=15399,poiX=8981,poiY=-7458,wowhead="https://www.wowhead.com/wotlk/quest=8476",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="Ours are not the vast kingdoms of the humans and orcs.  All we have left of our lands in Azeroth lies mostly before your eyes, $N.$B$BUntil we can reach Outland, we must defend what little land we have at any cost.$B$BOur uncivilized neighbors to the southeast, the Amani trolls, certainly have a different opinion regarding the ownership of these lands.  Their daily raids are something we can't tolerate anymore.  Go to their settlements, Zeb'Watha and Tor'Watha, and teach them a lesson.",logDesc="Lieutenant Dawnrunner at the Farstrider Retreat in Eversong Woods wants you to kill 5 Amani Berserkers and 5 Amani Axe Throwers."} end
if not DB[8477] then DB[8477]={id=8477,zoneId=3430,name="The Spearcrafter's Hammer",level=10,minLevel=7,giver="Arathel Sunforge",giverType="NPC",giverId=15400,ender="Arathel Sunforge",enderType="NPC",enderId=15400,poiX=8986,poiY=-7419,wowhead="https://www.wowhead.com/wotlk/quest=8477",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="The Amani and the sin'dorei have a long history of mutual dislike and open hostility.  That doesn't prevent me from appreciating a fellow craftsman's work, $N.$B$BI've come across pieces of Amani weaponry and I must admit I'm impressed by the quality of their work.  It is rumored that Spearcrafter Otembe wields a magical hammer that is so light and well-balanced it allows him to work with great dexterity and efficiency.$B$BIf you bring me this tool I'll use it to craft you a weapon.",logDesc="Search Tor'Watha to the southeast of the Farstrider Retreat for Spearcrafter Otembe and bring Otembe's Hammer to Arathel Sunforge at the Farstrider Retreat in Eversong Woods.",choiceRewards={{id=22958,qty=1},{id=22959,qty=1},{id=22963,qty=1}}} end
if not DB[8478] then DB[8478]={id=8478,zoneId=3430,name="Choose Your Weapon",level=9,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=8478",image="assets/images/quests/placeholder.png",xpDiff=3,money=150} end
if not DB[8479] then DB[8479]={id=8479,zoneId=3430,name="Zul'Marosh",level=11,minLevel=8,giver="Ven'jashi",giverType="NPC",giverId=15406,ender="Ven'jashi",enderType="NPC",enderId=15406,poiX=8667,poiY=-7961,wowhead="https://www.wowhead.com/wotlk/quest=8479",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Come closer, mon.  Don't be 'fraid, Ven'jashi not gonna hurt you.$B$BUs Darkspears be mortal enemies of the Amani just like you.  Their boss Zul'Marosh is evil troll.  He give me the bad poison and leave me in this cage to die.$B$BI not scared of dyin', mon.  I seen death in the eye an' I laugh at her.$B$BI cannot die in peace yet, mon.  Not 'til Zul'Marosh be dead too.  You find him 'cross the lake in Zeb'Watha.  I hold this poison off 'til you bring me his big ugly head, mon.  Only then I die peacefully.",logDesc="Ven'jashi, the troll prisoner at Tor'Watha, wants you to bring him Chieftain Zul'Marosh's Head.  Chieftain Zul'Marosh can be found in Zeb'Watha, across Lake Elrendar.",choiceRewards={{id=22969,qty=1},{id=22971,qty=1}}} end
if not DB[8480] then DB[8480]={id=8480,zoneId=3430,name="Lost Armaments",level=7,minLevel=5,giver="Velendris Whitemorn",giverType="NPC",giverId=15404,ender="Velendris Whitemorn",enderType="NPC",enderId=15404,rewardNextId=9076,poiX=8849,poiY=-6278,wowhead="https://www.wowhead.com/wotlk/quest=8480",image="assets/images/quests/placeholder.png",xpDiff=5,money=175,desc="The Wretched grow bolder every day, $N.  They've achieved enough coordination to launch an attack on Sunsail Anchorage.$B$BAs if that weren't embarrassing enough, most of our weapons were left behind when they attacked.  Bring me back our armaments so that we may show those ruffians who's boss.",logDesc="Bring 8 Sin'dorei Armaments to Velendris Whitemorn in Eversong Woods.",choiceRewards={{id=22957,qty=1},{id=22956,qty=1}}} end
if not DB[8481] then DB[8481]={id=8481,zoneId=1769,name="The Root of All Evil",level=60,minLevel=45,giver="Gorn One Eye",giverType="NPC",giverId=11555,ender="Gorn One Eye",enderType="NPC",enderId=11555,poiX=7031,poiY=-2106,wowhead="https://www.wowhead.com/wotlk/quest=8481",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N, thanks to you we have devised a way to summon forth the root of all evil for the Winterfall tribe - the corrupting demon that dominates them!$B$BTake this torch to the mouth of High Chief Winterfall's personal cave and plant it there.  Doing so will force the demon to reveal itself and investigate.  This is when you and your allies must strike it down!  Only the essence of the fallen demon will begin the lengthy healing process of the Winterfall tribe... and the salvation of Timbermaw Hold.",logDesc="Plant the Demon Summoning Torch in the mouth of High Chief Winterfall's cave in the Winterfall furbolg village.  Defeat the demon and retrieve the Essence of Xandivious for Gorn One Eye in Timbermaw Hold.",rewards={{id=21326,qty=1}}} end
if not DB[8482] then DB[8482]={id=8482,zoneId=3430,name="Incriminating Documents",level=6,minLevel=4,ender="Aeldon Sunbrand",enderType="NPC",enderId=15403,rewardNextId=8483,wowhead="https://www.wowhead.com/wotlk/quest=8482",image="assets/images/quests/placeholder.png",xpDiff=6,money=250,desc="The documents contain detailed maps of different strategic buildings in Eversong Woods.  A diagram of an arcane sanctum is also sketched in good detail.  There seem to be numerous notes in a language you don't recognize.$B$BAs these were carried by a Darnassian spy, it might be a good idea to bring them to the Captain of the Guard - Aeldon Sunbrand.",logDesc="Bring the Incriminating Documents to Aeldon Sunbrand at Falconwing Square in Eversong Woods."} end
if not DB[8483] then DB[8483]={id=8483,zoneId=3430,name="The Dwarven Spy",level=7,minLevel=4,giver="Aeldon Sunbrand",giverType="NPC",giverId=15403,ender="Aeldon Sunbrand",enderType="NPC",enderId=15403,poiX=9531,poiY=-6860,wowhead="https://www.wowhead.com/wotlk/quest=8483",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Listen, $N.  This is a very delicate situation; even though we've identified the spy, we cannot kill him out in the open.  We cannot try to capture him either as the risk of him escaping is too great.$B$BI want you to go find Prospector Anvilward at the North Sanctum and kill him.  Do this in a quiet manner, we don't want word to spread that we allowed a spy into our city.$B$BBring me his head as proof.  Ironforge will learn not to meddle with the sin'dorei.",logDesc="Bring Prospector Anvilward's Head to Aeldon Sunbrand at Falconwing Square in Eversong Woods.",choiceRewards={{id=23372,qty=1},{id=23373,qty=1}}} end
if not DB[8484] then DB[8484]={id=8484,zoneId=1769,name="The Brokering of Peace",level=60,minLevel=45,giver="Gorn One Eye",giverType="NPC",giverId=11555,ender="King Magni Bronzebeard",enderType="NPC",enderId=2784,poiX=7031,poiY=-2106,wowhead="https://www.wowhead.com/wotlk/quest=8484",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Your deeds go beyond the tale of a simple hero, $N.  If you are a representative of your people, then your people are ones we would work to make peace with.$B$BPlease - take this offering to the dwarven king that resides in a mountain of iron; I believe you call this city Ironforge.  In times past, he had tried to make contact with us on behalf of his Alliance.  It is now only fitting to acknowledge you as the key in your Alliance's efforts in brokering peace.",logDesc="Bring the Timbermaw Offering of Peace to King Magni Bronzebeard in Ironforge."} end
if not DB[8485] then DB[8485]={id=8485,zoneId=1769,name="The Brokering of Peace",level=60,minLevel=45,giver="Gorn One Eye",giverType="NPC",giverId=11555,ender="Thrall",enderType="NPC",enderId=4949,poiX=7031,poiY=-2106,wowhead="https://www.wowhead.com/wotlk/quest=8485",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Your deeds go beyond the tale of a simple hero, $N.  If you are a representative of your people, then your people are ones we would work to make peace with.$B$BPlease - take this offering to the orcish warchief that resides in the lands of Durotar; I believe you call this city Orgrimmar.  In times past, he had tried to make contact with us on behalf of his Horde.  It is now only fitting to acknowledge you as the key in your Horde's efforts in brokering peace.",logDesc="Bring the Timbermaw Offering of Peace to Thrall in Orgrimmar."} end
if not DB[8486] then DB[8486]={id=8486,zoneId=3430,name="Arcane Instability",level=6,minLevel=4,giver="Ley-Keeper Velania",giverType="NPC",giverId=15401,ender="Ley-Keeper Velania",enderType="NPC",enderId=15401,poiX=9156,poiY=-6295,wowhead="https://www.wowhead.com/wotlk/quest=8486",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It's about time that dimwit, Caidanis, sent someone this way.$B$BI warned of the dangers of increasing the load on the West Sanctum!  Now one of our energy converters is destroyed and arcane wraiths are pouring out of the sanctum!$B$BI'm going to need you to take care of these creatures before we send anyone in for repairs.  Make haste!",logDesc="Ley-Keeper Velania wants you to kill 5 Manawraiths and 5 Mana Stalkers.",choiceRewards={{id=23370,qty=1},{id=23371,qty=1}}} end
if not DB[8487] then DB[8487]={id=8487,zoneId=3430,name="Corrupted Soil",level=9,minLevel=7,giver="Apprentice Mirveda",giverType="NPC",giverId=15402,ender="Apprentice Mirveda",enderType="NPC",enderId=15402,poiX=8711,poiY=-7161,wowhead="https://www.wowhead.com/wotlk/quest=8487",image="assets/images/quests/placeholder.png",xpDiff=5,money=300,desc="This was a fully functional arcane sanctum before Arthas and his army of Scourge decided to plow through it on their way to Silvermoon.$B$BNow it's as useful to us as any part of the Dead Scar.  The soil is tainted, undead are drawn to it and the energy in the ley lines is completely disrupted.$B$BWhat I want to know, $N, is whether this taint is reversible or not.  I want you to collect soil samples from this area so I can study them.  Perhaps with time we can set things back to normal.",logDesc="Apprentice Mirveda at the East Sanctum in Eversong Woods wants you to collect 8 Tainted Soil Samples."} end
if not DB[8488] then DB[8488]={id=8488,zoneId=3430,name="Unexpected Results",level=9,minLevel=7,giver="Apprentice Mirveda",giverType="NPC",giverId=15402,ender="Apprentice Mirveda",enderType="NPC",enderId=15402,rewardNextId=9255,poiX=8711,poiY=-7161,wowhead="https://www.wowhead.com/wotlk/quest=8488",image="assets/images/quests/placeholder.png",xpDiff=5,money=300,desc="Something's wrong, $N.  I sense the presence of Scourge.  Be ready to fight them!",logDesc="Protect Apprentice Mirveda from the Scourge ambush."} end
if not DB[8489] then DB[8489]={id=8489,zoneId=3430,name="An Intact Converter",level=6,minLevel=4,wowhead="https://www.wowhead.com/wotlk/quest=8489",image="assets/images/quests/placeholder.png",xpDiff=5,money=125,desc="This object appears to be one of the arcane converters Ley-Keeper Velania mentioned.  It hasn't been damaged by the fire, perhaps she could find a use for it.",logDesc="Bring the Intact Arcane Converter to Ley-Keeper Velania."} end
if not DB[8490] then DB[8490]={id=8490,zoneId=3430,name="Powering our Defenses",level=10,minLevel=8,giver="Runewarden Deryan",giverType="NPC",giverId=16362,ender="Runewarden Deryan",enderType="NPC",enderId=16362,poiX=8236,poiY=-6664,wowhead="https://www.wowhead.com/wotlk/quest=8490",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="Ancient runestones once powered a protective barrier across the Eversong border.  Many were destroyed during Arthas' attack; others were stolen.$B$BOf the three that remain, only this one has retained its powers.  The runestone to the east might be salvageable, though.$B$BTake this crystal and instill its energy on the Eastern Runestone.  The process should take but a minute.  Beware though, nearby Scourge will be drawn to it and will seek to destroy it.  Do not let them! ",logDesc="Place the Infused Crystal at the Eastern Runestone and protect it from the Scourge for 1 minute.  Return the Infused Crystal to Runewarden Deryan in Eversong Woods for a reward."} end
if not DB[8491] then DB[8491]={id=8491,zoneId=3430,name="Pelt Collection",level=7,minLevel=4,giver="Velan Brightoak",giverType="NPC",giverId=15417,ender="Velan Brightoak",enderType="NPC",enderId=15417,poiX=8756,poiY=-6690,wowhead="https://www.wowhead.com/wotlk/quest=8491",image="assets/images/quests/placeholder.png",xpDiff=5,money=175,desc="The springpaw that inhabit this region are known for their high quality pelts.  We've even seen night elf scum travel to these lands just to poach them.$B$BOur skirmishes with the Amani have put a bit of a strain on our supply of gear and our rangers don't have much time to hunt for pelts anymore.  If you'd be willing to lend a hand by collecting springpaw pelts, I'd be happy to reward you with a hand-crafted piece of armor.  You'll find springpaw stalkers all around the woods north of here.",logDesc="Velan Brightoak at Fairbreeze Village in Eversong Woods wants you to bring him 6 Springpaw Pelts.",choiceRewards={{id=22951,qty=1},{id=22953,qty=1},{id=22952,qty=1}}} end
if not DB[8492] then DB[8492]={id=8492,zoneId=-365,name="The Alliance Needs Copper Bars!",level=60,minLevel=1,giver="Sergeant Stonebrow",giverType="NPC",giverId=15383,ender="Sergeant Stonebrow",enderType="NPC",enderId=15383,wowhead="https://www.wowhead.com/wotlk/quest=8492",image="assets/images/quests/placeholder.png",desc="Hey there, $c, you look fit enough to contribute to the war effort! We need all of the help that we can get here to put together the materiel needed for the Ahn'Qiraj War and it's your lucky day.$B$BI'm collecting copper bars in stacks of twenty. It's for a worthy cause, what do you say? Do you think you could help out the Alliance?",logDesc="Bring 20 Copper Bars to Sergeant Stonebrow at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21509,qty=1}}} end
if not DB[8493] then DB[8493]={id=8493,zoneId=-365,name="The Alliance Needs More Copper Bars!",level=60,minLevel=1,giver="Sergeant Stonebrow",giverType="NPC",giverId=15383,ender="Sergeant Stonebrow",enderType="NPC",enderId=15383,wowhead="https://www.wowhead.com/wotlk/quest=8493",image="assets/images/quests/placeholder.png",desc="Back again $c? Outstanding! We still need more stacks of copper bars if you can procure them for the Ahn'Qiraj war effort.  Will you help us out?",logDesc="Bring 20 copper bars to Sergeant Stonebrow at the airfield in Dun Morogh.",rewards={{id=21436,qty=1},{id=21509,qty=1}}} end
if not DB[8494] then DB[8494]={id=8494,zoneId=-365,name="The Alliance Needs Iron Bars!",level=60,minLevel=1,giver="Corporal Carnes",giverType="NPC",giverId=15431,ender="Corporal Carnes",enderType="NPC",enderId=15431,wowhead="https://www.wowhead.com/wotlk/quest=8494",image="assets/images/quests/placeholder.png",desc="Well hello there, $g Mr. : Ms.; Fancypants, aren't you a sight for sore eyes. In case you hadn't heard while you were out there \"adventuring\", the Alliance has been gearing up for a war in Ahn'Qiraj and is in need of iron bars... a whole mess of 'em. Bring them to me in stacks of twenty. We can count on you, right, $c?",logDesc="Bring 20 Iron Bars to Corporal Carnes at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21511,qty=1}}} end
if not DB[8495] then DB[8495]={id=8495,zoneId=-365,name="The Alliance Needs More Iron Bars!",level=60,minLevel=1,giver="Corporal Carnes",giverType="NPC",giverId=15431,ender="Corporal Carnes",enderType="NPC",enderId=15431,wowhead="https://www.wowhead.com/wotlk/quest=8495",image="assets/images/quests/placeholder.png",desc="Back so soon? Stop making me re-evaluate my low opinion of you $c, you're making me feel all gooey inside. So, as you can tell we still don't have enough iron bars for all of the weapons, armor, steam tanks and whatnot that need building for the bug hunt. Think you have it in you to bring back another stack of twenty iron bars in between all of those trips to Zul'Gurub, or wherever it is that you kids hang out these days?",logDesc="Bring 20 iron bars to Corporal Carnes at the airfield in Dun Morogh.",rewards={{id=21436,qty=5},{id=21511,qty=1}}} end
if not DB[8496] then DB[8496]={id=8496,zoneId=1377,name="Bandages for the Field",level=60,minLevel=60,ender="Windcaller Proudhorn",enderType="NPC",enderId=15191,wowhead="https://www.wowhead.com/wotlk/quest=8496",image="assets/images/quests/placeholder.png",desc="Our supply of bandages in the battlefield is running dangerously low after the recent casualties we have incurred.  Obtain a batch of first-aid supplies and deliver them to Windcaller Proudhorn in Cenarion Hold.",logDesc="Bring 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages and 30 Heavy Mageweave Bandages to Windcaller Proudhorn at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing X in order to complete this quest.",rewards={{id=20800,qty=1},{id=20805,qty=1}}} end
if not DB[8497] then DB[8497]={id=8497,zoneId=1377,name="Desert Survival Kits",level=60,minLevel=60,ender="Calandrath",enderType="NPC",enderId=15174,wowhead="https://www.wowhead.com/wotlk/quest=8497",image="assets/images/quests/placeholder.png",desc="With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.",logDesc="Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Smoked Desert Dumplings to Calandrath at the inn in Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing I in order to complete this quest.",rewards={{id=20800,qty=1},{id=21132,qty=1}}} end
if not DB[8498] then DB[8498]={id=8498,zoneId=1377,name="Twilight Battle Orders",level=60,minLevel=60,ender="Commander Mar'alith",enderType="NPC",enderId=15181,wowhead="https://www.wowhead.com/wotlk/quest=8498",image="assets/images/quests/placeholder.png",desc="Our scouts have reported new battle orders being issued by the Twilight's Hammer leaders.  The orders are being distributed by Twilight Prophets under heavy escort.  Intercept the orders and bring them to Commander Mar'alith.",logDesc="Obtain the Twilight Battle Orders and bring them Commander Mar'alith at Cenarion Hold in Silithus.  You must also bring Tactical Task Briefing X in order to complete this quest.",rewards={{id=20801,qty=1},{id=20809,qty=1}}} end
if not DB[8499] then DB[8499]={id=8499,zoneId=-365,name="The Alliance Needs Thorium Bars!",level=60,minLevel=1,giver="Dame Twinbraid",giverType="NPC",giverId=15432,ender="Dame Twinbraid",enderType="NPC",enderId=15432,wowhead="https://www.wowhead.com/wotlk/quest=8499",image="assets/images/quests/placeholder.png",desc="It is very kind of you to inquire about the needs that the Alliance has. In addition to all of the other collection efforts underway, we are in need of a great quantity of thorium bars, which is the task that I am in charge of. The thorium will be used in the creation of many different things for the war, foremost of which is the construction of a battalion of steam tanks to be airlifted into Silithus as soon as they are completed. Can you aid us in this endeavor, $c?",logDesc="Bring 20 Thorium Bars to Dame Twinbraid at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21513,qty=1}}} end
if not DB[8500] then DB[8500]={id=8500,zoneId=-365,name="The Alliance Needs More Thorium Bars!",level=60,minLevel=1,giver="Dame Twinbraid",giverType="NPC",giverId=15432,ender="Dame Twinbraid",enderType="NPC",enderId=15432,wowhead="https://www.wowhead.com/wotlk/quest=8500",image="assets/images/quests/placeholder.png",desc="It is so good to see you again $N. I hope that you've been doing well. It's true that we are still in need of thorium bars. If you have them to spare I am collecting them for the Ahn'Qiraj war effort.",logDesc="Bring 20 thorium bars to Dame Twinbraid at the airfield in Dun Morogh.",rewards={{id=21436,qty=10},{id=21513,qty=1}}} end
if not DB[8501] then DB[8501]={id=8501,zoneId=1377,name="Target: Hive'Ashi Stingers",level=60,minLevel=60,ender="Commander Mar'alith",enderType="NPC",enderId=15181,wowhead="https://www.wowhead.com/wotlk/quest=8501",image="assets/images/quests/placeholder.png",desc="As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of the airborne Hive'Ashi stingers.$B$BReport back to Commander Mar'alith after your task is completed.",logDesc="Kill 30 Hive'Ashi Stingers and report back to Commander Mar'alith at Cenarion Hold in Silithus.  You must also bring Combat Task Briefing XII in order to complete this quest.$B",rewards={{id=20802,qty=1}}} end
if not DB[8502] then DB[8502]={id=8502,zoneId=1377,name="Target: Hive'Ashi Workers",level=60,minLevel=60,ender="Commander Mar'alith",enderType="NPC",enderId=15181,wowhead="https://www.wowhead.com/wotlk/quest=8502",image="assets/images/quests/placeholder.png",desc="As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of Hive'Ashi workers.$B$BReport back to Commander Mar'alith after your task is completed.",logDesc="Slay 30 Hive'Ashi Workers and report back to Commander Mar'alith at Cenarion Hold in Silithus.  You must also bring Combat Task Briefing III in order to complete this quest.",rewards={{id=20802,qty=1}}} end
if not DB[8503] then DB[8503]={id=8503,zoneId=-365,name="The Alliance Needs Stranglekelp!",level=60,minLevel=1,giver="Private Draxlegauge",giverType="NPC",giverId=15434,ender="Private Draxlegauge",enderType="NPC",enderId=15434,wowhead="https://www.wowhead.com/wotlk/quest=8503",image="assets/images/quests/placeholder.png",desc="So, $c, did I already tell you about all of the fabulous uses stranglekelp has? I did? Oh well... in any case we need a lot of it, and when I say a lot, I mean A LOT! Do you think that you could help us out? I know that it means going without all of those wonderful things that you can make with it, but it's for a good cause!",logDesc="Bring 20 Stranglekelp to Private Draxlegauge at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21510,qty=1}}} end
if not DB[8504] then DB[8504]={id=8504,zoneId=-365,name="The Alliance Needs More Stranglekelp!",level=60,minLevel=1,giver="Private Draxlegauge",giverType="NPC",giverId=15434,ender="Private Draxlegauge",enderType="NPC",enderId=15434,wowhead="https://www.wowhead.com/wotlk/quest=8504",image="assets/images/quests/placeholder.png",desc="Well hello again there... what was it? Ah yes, $N! Come to see if I still need more stranglekelp have you? Well, it's your lucky day, because the answer to that very important question is a very affirmative YES! Think you could gather up twenty more?",logDesc="Bring 20 stranglekelp to Private Draxlegauge at the airfield in Dun Morogh.",rewards={{id=21436,qty=3},{id=21510,qty=1}}} end
if not DB[8505] then DB[8505]={id=8505,zoneId=-365,name="The Alliance Needs Purple Lotus!",level=60,minLevel=1,giver="Master Nightsong",giverType="NPC",giverId=15437,ender="Master Nightsong",enderType="NPC",enderId=15437,wowhead="https://www.wowhead.com/wotlk/quest=8505",image="assets/images/quests/placeholder.png",desc="$C, the purple lotus is a flower with a plentitude of uses. I am here at the request of the Alliance as an authority on those applications, to preserve the herbs collected and to ensure that their war effort acquires enough purple lotus to sustain whatever function they plan for it.$B$BI would like for you to travel out into the world and return to me with some of these flowers. Is that something that you can do?",logDesc="Bring 20 Purple Lotus to Master Nightsong at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21512,qty=1}}} end
if not DB[8506] then DB[8506]={id=8506,zoneId=-365,name="The Alliance Needs More Purple Lotus!",level=60,minLevel=1,giver="Master Nightsong",giverType="NPC",giverId=15437,ender="Master Nightsong",enderType="NPC",enderId=15437,wowhead="https://www.wowhead.com/wotlk/quest=8506",image="assets/images/quests/placeholder.png",desc="Welcome back $c. Our collection grows, but even now we have a need for additional purple lotus. If it is still within your power to gather more of the herb, I entreat you to do so and return them to me here.",logDesc="Bring 20 purple lotus to Master Nightsong at the airfield in Dun Morogh.",rewards={{id=21436,qty=7},{id=21512,qty=1}}} end
if not DB[8507] then DB[8507]={id=8507,zoneId=1377,name="Field Duty",level=60,minLevel=60,giver="Windcaller Kaldon",giverType="NPC",giverId=15540,ender="Windcaller Kaldon",enderType="NPC",enderId=15540,poiX=-6803,poiY=796,wowhead="https://www.wowhead.com/wotlk/quest=8507",image="assets/images/quests/placeholder.png",desc="Greetings, $N.  Before I assign you to more involved tasks in the war, you'll need to do your share of field duty.  $B$BYou will find Captain Blackanvil's Ironforge Brigade outside Hive'Zora.$B$BReport to him or his lieutenant, Janela Stouthammer and come back to me.  I shall have a more advanced assignment for you ready.$B$BOh and please do us a favor and stay away from the Orgrimmar Legion.  We've been forced to keep the two forces well apart from one another due to mutual animosity.",logDesc="Report for duty at the Ironforge Brigade post near Hive'Zora.  Prepare your Unsigned Field Duty Papers and obtain Signed Field Duty Papers from Captain Blackanvil and return to Windcaller Kaldon at Cenarion Hold in Silithus.$B$BNote: Healing or casting beneficial spells on a member of the Ironforge Brigade will flag you for PvP.",choiceRewards={{id=20808,qty=1},{id=21132,qty=1},{id=20809,qty=1}}} end
if not DB[8508] then DB[8508]={id=8508,zoneId=1377,name="Field Duty Papers",level=60,minLevel=60,giver="Captain Blackanvil",giverType="NPC",giverId=15440,ender="Captain Blackanvil",enderType="NPC",enderId=15440,wowhead="https://www.wowhead.com/wotlk/quest=8508",image="assets/images/quests/placeholder.png",rewards={{id=20810,qty=1}}} end
if not DB[8509] then DB[8509]={id=8509,zoneId=-365,name="The Alliance Needs Arthas' Tears!",level=60,minLevel=1,giver="Sergeant Major Germaine",giverType="NPC",giverId=15445,ender="Sergeant Major Germaine",enderType="NPC",enderId=15445,wowhead="https://www.wowhead.com/wotlk/quest=8509",image="assets/images/quests/placeholder.png",desc="I'll keep it simple and to the point, $c. The Alliance needs to collect a large quantity of Arthas' Tears for the Ahn'Qiraj war effort. Don't ask me what for; I'm just following orders. But I'd like you to gather up as many of the herbs as you can and bring them back to me here. Are you willing to do that?",logDesc="Bring 20 Arthas' Tears to Sergeant Major Germaine at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21513,qty=1}}} end
if not DB[8510] then DB[8510]={id=8510,zoneId=-365,name="The Alliance Needs More Arthas' Tears!",level=60,minLevel=1,giver="Sergeant Major Germaine",giverType="NPC",giverId=15445,ender="Sergeant Major Germaine",enderType="NPC",enderId=15445,wowhead="https://www.wowhead.com/wotlk/quest=8510",image="assets/images/quests/placeholder.png",desc="Ok, so it looks like I still need more Arthas' Tears. I would imagine that you will be able to find them in the general location that you gathered them up for me last time. The quicker we get these, the faster we can start up the offensive against the forces at Ahn'Qiraj.$B$BYou gonna help us out again $c?",logDesc="Bring 20 arthas' tears to Sergeant Major Germaine at the airfield in Dun Morogh.",rewards={{id=21436,qty=10},{id=21513,qty=1}}} end
if not DB[8511] then DB[8511]={id=8511,zoneId=-365,name="The Alliance Needs Light Leather!",level=60,minLevel=1,giver="Bonnie Stoneflayer",giverType="NPC",giverId=15446,ender="Bonnie Stoneflayer",enderType="NPC",enderId=15446,wowhead="https://www.wowhead.com/wotlk/quest=8511",image="assets/images/quests/placeholder.png",desc="We Stoneflayers have a long history of being skinners, $c. That's why the Alliance has asked my family to help out with the collection of light leather for the Ahn'Qiraj war effort. I'm here to see to it that the leather is tanned correctly for whatever they want to put it to use for. But we need your help.$B$BSince I have to be here doing that, I need you to go out and collect the skins, returning them to me here. What do you say, $g lad : lass;, will you give it a go?",logDesc="Bring 10 Light Leather to Bonnie Stoneflayer at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21509,qty=1}}} end
if not DB[8512] then DB[8512]={id=8512,zoneId=-365,name="The Alliance Needs More Light Leather!",level=60,minLevel=1,giver="Bonnie Stoneflayer",giverType="NPC",giverId=15446,ender="Bonnie Stoneflayer",enderType="NPC",enderId=15446,wowhead="https://www.wowhead.com/wotlk/quest=8512",image="assets/images/quests/placeholder.png",desc="Good to see you again $N. It does appear that we need more light leather for the creation of the various war materiel. If you could bring me a stack of ten that would be just perfect.",logDesc="Bring 10 light leather to Bonnie Stoneflayer at the airfield in Dun Morogh.",rewards={{id=21436,qty=1},{id=21509,qty=1}}} end
if not DB[8513] then DB[8513]={id=8513,zoneId=-365,name="The Alliance Needs Medium Leather!",level=60,minLevel=1,giver="Private Porter",giverType="NPC",giverId=15448,ender="Private Porter",enderType="NPC",enderId=15448,wowhead="https://www.wowhead.com/wotlk/quest=8513",image="assets/images/quests/placeholder.png",desc="Yes $g sir : ma'am;, I have been charged with collecting and tracking all of the medium leather gathered for the war effort. If you have the wherewithal to gather medium leather, from whatever source, then please bring them to me here. I sure would appreciate a hand with this if you can spare the time.",logDesc="Bring 10 Medium Leather to Private Porter at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21510,qty=1}}} end
if not DB[8514] then DB[8514]={id=8514,zoneId=-365,name="The Alliance Needs More Medium Leather!",level=60,minLevel=1,giver="Private Porter",giverType="NPC",giverId=15448,ender="Private Porter",enderType="NPC",enderId=15448,wowhead="https://www.wowhead.com/wotlk/quest=8514",image="assets/images/quests/placeholder.png",desc="Yes $g sir : ma'am;, looks like we've collected $2063w pieces of medium leather to date. I know it's a lot to ask, but if you're still willing, I could use your help in attempting to put a dent in the rest of my quota.",logDesc="Bring 10 medium leather to Private Porter at the airfield in Dun Morogh.",rewards={{id=21436,qty=3},{id=21510,qty=1}}} end
if not DB[8515] then DB[8515]={id=8515,zoneId=-365,name="The Alliance Needs Thick Leather!",level=60,minLevel=1,giver="Marta Finespindle",giverType="NPC",giverId=15450,ender="Marta Finespindle",enderType="NPC",enderId=15450,wowhead="https://www.wowhead.com/wotlk/quest=8515",image="assets/images/quests/placeholder.png",desc="Oh boy, this is going to be great! $C, the Ahn'Qiraj war effort is in full swing, and I've been put in charge of keeping track of all of the thick leather that comes in. We'll make tons of things with it, but first we need to get a ton of it. And I mean that literally! That's where you come in.$B$BSo, do you think you can go out there and bring me back a nice, fat stack of thick leather? Do yah, do yah?!",logDesc="Bring 10 Thick Leather to Marta Finespindle at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21512,qty=1}}} end
if not DB[8516] then DB[8516]={id=8516,zoneId=-365,name="The Alliance Needs More Thick Leather!",level=60,minLevel=1,giver="Marta Finespindle",giverType="NPC",giverId=15450,ender="Marta Finespindle",enderType="NPC",enderId=15450,wowhead="https://www.wowhead.com/wotlk/quest=8516",image="assets/images/quests/placeholder.png",desc="Yep, the stack's still not high enough. $N, we still haven't reached our goal of $2071w thick leather. Just think of all the things that we can make with all of that leather! All kinds of armor and weapons. Stuff for inside the steam tanks and rifle scopes! Engineering goggles, and I bet if it ends up that we collect too much we could give the rest to the Horde for their zeppelins!$B$BYou gonna bring me back some more thick leather?",logDesc="Bring 10 thick leather to Marta Finespindle at the airfield in Dun Morogh.",rewards={{id=21436,qty=7},{id=21512,qty=1}}} end
if not DB[8517] then DB[8517]={id=8517,zoneId=-365,name="The Alliance Needs Linen Bandages!",level=60,minLevel=1,giver="Sentinel Silversky",giverType="NPC",giverId=15451,ender="Sentinel Silversky",enderType="NPC",enderId=15451,wowhead="https://www.wowhead.com/wotlk/quest=8517",image="assets/images/quests/placeholder.png",desc="The war at Ahn'Qiraj is going to be long and bloody. It is a very wise thing that the Alliance is doing by enlisting the aid of you, and those like you, to build up the materiel necessary before plunging headlong into conflict.$B$BI have been asked to head up the collection of linen bandages for the war, and I am hoping that you are going to assist me in amassing as many as we need. It is no light matter, but at least the linen bandages are the least difficult to create. Are you with us, $c?",logDesc="Bring 20 Linen Bandages to Sentinel Silversky at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21509,qty=1}}} end
if not DB[8518] then DB[8518]={id=8518,zoneId=-365,name="The Alliance Needs More Linen Bandages!",level=60,minLevel=1,giver="Sentinel Silversky",giverType="NPC",giverId=15451,ender="Sentinel Silversky",enderType="NPC",enderId=15451,wowhead="https://www.wowhead.com/wotlk/quest=8518",image="assets/images/quests/placeholder.png",desc="Ever am I amazed by the selflessness exhibited when so many would instead turn to selfishness instead. $C, I am still in need of a number of linen bandages before my assignment here is fulfilled. Will you aid me once more in the collection of those bandages?",logDesc="Bring 20 linen bandages to Sentinel Silversky at the airfield in Dun Morogh.",rewards={{id=21436,qty=1},{id=21509,qty=1}}} end
if not DB[8519] then DB[8519]={id=8519,zoneId=1377,name="A Pawn on the Eternal Board",level=60,minLevel=60,ender="3",enderType="NPC",enderId=15192,rewardNextId=8555,wowhead="https://www.wowhead.com/wotlk/quest=8519",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As you regain your composure and focus your gaze, you notice that something stirs within the crystal. Upon closer inspection, you realize that you are looking into the past... a memory... long forgotten.",logDesc="Learn all that you can of the past, then speak with Anachronos at the Caverns of Time in Tanaris.$B"} end
if not DB[8520] then DB[8520]={id=8520,zoneId=-365,name="The Alliance Needs Silk Bandages!",level=60,minLevel=1,giver="Nurse Stonefield",giverType="NPC",giverId=15452,ender="Nurse Stonefield",enderType="NPC",enderId=15452,wowhead="https://www.wowhead.com/wotlk/quest=8520",image="assets/images/quests/placeholder.png",desc="With the Ahn'Qiraj War looming we need to do everything that we can to see to it that our soldiers have everything that they need. We're doing just that right here. For my part I've been placed in charge of seeing to it that we collect enough silk bandages.$B$BDo you think you can help me out, $c?",logDesc="Bring 20 Silk Bandages to Nurse Stonefield at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21511,qty=1}}} end
if not DB[8521] then DB[8521]={id=8521,zoneId=-365,name="The Alliance Needs More Silk Bandages!",level=60,minLevel=1,giver="Nurse Stonefield",giverType="NPC",giverId=15452,ender="Nurse Stonefield",enderType="NPC",enderId=15452,wowhead="https://www.wowhead.com/wotlk/quest=8521",image="assets/images/quests/placeholder.png",desc="It is very kind of you to offer to help me again $c. It looks like we've collected $2082w silk bandages, so we'll need more.",logDesc="Bring 20 silk bandages to Nurse Stonefield at the airfield in Dun Morogh.",rewards={{id=21436,qty=5},{id=21511,qty=1}}} end
if not DB[8522] then DB[8522]={id=8522,zoneId=-365,name="The Alliance Needs Runecloth Bandages!",level=60,minLevel=1,giver="Keeper Moonshade",giverType="NPC",giverId=15453,ender="Keeper Moonshade",enderType="NPC",enderId=15453,wowhead="https://www.wowhead.com/wotlk/quest=8522",image="assets/images/quests/placeholder.png",desc="Argue the merits of the war if you will, $c, but it has already been set in motion. Look around you at your family and friends, and then ask yourself what it is that you can do to see to it that if they are involved, they will have every advantage to survive the conflagration.$B$BTo that end, I am collecting runecloth bandages here from whatever source. Would you like to make a donation?",logDesc="Bring 20 Runecloth Bandages to Keeper Moonshade at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21513,qty=1}}} end
if not DB[8523] then DB[8523]={id=8523,zoneId=-365,name="The Alliance Needs More Runecloth Bandages!",level=60,minLevel=1,giver="Keeper Moonshade",giverType="NPC",giverId=15453,ender="Keeper Moonshade",enderType="NPC",enderId=15453,wowhead="https://www.wowhead.com/wotlk/quest=8523",image="assets/images/quests/placeholder.png",desc="So it is that we come to discuss pressing matters yet again $c. Once more I thank you for your previous efforts; it is not everyone who would give so selflessly. But there is still more work to do.$B$B$N, will you once more collect runecloth bandages and return them to me here?",logDesc="Bring 20 runecloth bandages to Keeper Moonshade at the airfield in Dun Morogh.",rewards={{id=21436,qty=10},{id=21513,qty=1}}} end
if not DB[8524] then DB[8524]={id=8524,zoneId=-365,name="The Alliance Needs Rainbow Fin Albacore!",level=60,minLevel=1,giver="Slicky Gastronome",giverType="NPC",giverId=15455,ender="Slicky Gastronome",enderType="NPC",enderId=15455,wowhead="https://www.wowhead.com/wotlk/quest=8524",image="assets/images/quests/placeholder.png",desc="Hey there, friend! If I were to say to you, 'Don't you think that soldiers should have food to eat like anyone else?', you would of course reply, 'yes'. I agree with you 110%! I'm glad we're in accord. All I need for you to do is to head out there, fish up a whole bunch of raw rainbow fin albacore, and then cook it all up and bring it back to me right here. Mmm, mmm, I can taste it already.",logDesc="Bring 20 Rainbow Fin Albacore to Slicky Gastronome at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21509,qty=1}}} end
if not DB[8525] then DB[8525]={id=8525,zoneId=-365,name="The Alliance Needs More Rainbow Fin Albacore!",level=60,minLevel=1,giver="Slicky Gastronome",giverType="NPC",giverId=15455,ender="Slicky Gastronome",enderType="NPC",enderId=15455,wowhead="https://www.wowhead.com/wotlk/quest=8525",image="assets/images/quests/placeholder.png",desc="What! You again? Well I'll be a monkey's uncle... except that I'm a gnome. Slicky Gastronome to be precise! So you're back to help out again eh? Well, I can't say as I blame you. Don't you just love the smell of all of that food? <drool>$B$BEnough loitering! Get out there and bring me back more rainbow fin albacore!",logDesc="Bring 20 rainbow fin albacore to Slicky Gastronome at the airfield in Dun Morogh.",rewards={{id=21436,qty=3},{id=21509,qty=1}}} end
if not DB[8526] then DB[8526]={id=8526,zoneId=-365,name="The Alliance Needs Roast Raptor!",level=60,minLevel=1,giver="Sarah Sadwhistle",giverType="NPC",giverId=15456,ender="Sarah Sadwhistle",enderType="NPC",enderId=15456,wowhead="https://www.wowhead.com/wotlk/quest=8526",image="assets/images/quests/placeholder.png",desc="Oh, how's it going, $c? I see that you're interested in maybe gathering up food for the coming war at Ahn'Qiraj? Somehow my dad thought that it would be a good learning experience for me if I were to volunteer to help out here. Big mistake. I don't even like to eat meat.$B$BAnyway, if you feel like it, you could bring me back a lot of roast raptor. Apparently that's what all of the soldiers are going to want.",logDesc="Bring 20 Roast Raptor to Sarah Sadwhistle at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21511,qty=1}}} end
if not DB[8527] then DB[8527]={id=8527,zoneId=-365,name="The Alliance Needs More Roast Raptor!",level=60,minLevel=1,giver="Sarah Sadwhistle",giverType="NPC",giverId=15456,ender="Sarah Sadwhistle",enderType="NPC",enderId=15456,wowhead="https://www.wowhead.com/wotlk/quest=8527",image="assets/images/quests/placeholder.png",desc="Hi again $c. I can tell you're very excited about all of this. So I suppose you want to bring me another twenty roast raptor. Great. Well you do that. I guess I'll see you when you get back.",logDesc="Bring 20 roast raptor to Sarah Sadwhistle at the airfield in Dun Morogh.",rewards={{id=21436,qty=5},{id=21511,qty=1}}} end
if not DB[8528] then DB[8528]={id=8528,zoneId=-365,name="The Alliance Needs Spotted Yellowtail!",level=60,minLevel=1,giver="Huntress Swiftriver",giverType="NPC",giverId=15457,ender="Huntress Swiftriver",enderType="NPC",enderId=15457,wowhead="https://www.wowhead.com/wotlk/quest=8528",image="assets/images/quests/placeholder.png",desc="It may not seem heroic to gather up cooked fish, but do not underestimate the value of preparation, young $c. Soldiers need to eat like anyone else, and we're here to do our part to make sure they have what they need once the war in Ahn'Qiraj commences.$B$BAccordingly, I am stockpiling spotted yellowtail, a versatile source of sustenance that stores well and can be used in many different dishes. It also doesn't have the odor of some other saltwater fish. Are you willing to aid me in this endeavor?",logDesc="Bring 20 Spotted Yellowtail to Huntress Swiftriver at the Military Ward in Ironforge.",rewards={{id=21436,qty=10},{id=21512,qty=1}}} end
if not DB[8529] then DB[8529]={id=8529,zoneId=-365,name="The Alliance Needs More Spotted Yellowtail!",level=60,minLevel=1,giver="Huntress Swiftriver",giverType="NPC",giverId=15457,ender="Huntress Swiftriver",enderType="NPC",enderId=15457,wowhead="https://www.wowhead.com/wotlk/quest=8529",image="assets/images/quests/placeholder.png",desc="If you're still willing I'd like to send you back out to bring in another haul of spotted yellowtail, $N. I'd imagine with the expertise you gained the first time out that this catch should be much faster and easier. Are you game?",logDesc="Bring 20 spotted yellowtail to Huntress Swiftriver at the airfield in Dun Morogh.",rewards={{id=21436,qty=7},{id=21512,qty=1}}} end
if not DB[8530] then DB[8530]={id=8530,zoneId=-365,name="The Alliance Needs Singed Corestones!",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=8530",image="assets/images/quests/placeholder.png",desc="$C, I need your help. In the Molten Core there are these stones, singed Corestones to be precise, that we need to harvest for the Ahn'Qiraj war effort. I'm told that our blacksmiths and engineers can put them to good use, so that's where you come in. I need you to go into the Molten Core and gather up as many of these corestones as you can. Of course, you'll want to talk thirty-nine of your closest friends along with you.",logDesc="Bring 50 singed corestones to Commander Stronghammer at the airfield in Dun Morogh."} end
if not DB[8531] then DB[8531]={id=8531,zoneId=-365,name="The Alliance Needs More Singed Corestones!",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=8531",image="assets/images/quests/placeholder.png",desc="Thank you for returning $N. If you and your friends still have it in you, I need you to return to the Molten Core and continue your singed corestone collection efforts. What do you say?",logDesc="Bring 50 singed corestones to Commander Stronghammer at the airfield in Dun Morogh."} end
if not DB[8532] then DB[8532]={id=8532,zoneId=-365,name="The Horde Needs Copper Bars!",level=60,minLevel=1,giver="Miner Cromwell",giverType="NPC",giverId=15459,ender="Miner Cromwell",enderType="NPC",enderId=15459,wowhead="https://www.wowhead.com/wotlk/quest=8532",image="assets/images/quests/placeholder.png",desc="So glad that you've decided to help out here. Not everyone would, so I need to make sure you understand what it is that I need. Copper bars, not copper ore. We don't have the time or people to do all of the smelting ourselves, so if you would be so kind as to take care of that, your efforts will be duly noted. Is that something that you can handle, $c?",logDesc="Bring 20 Copper Bars to Miner Cromwell at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21509,qty=1}}} end
if not DB[8533] then DB[8533]={id=8533,zoneId=-365,name="The Horde Needs More Copper Bars!",level=60,minLevel=1,giver="Miner Cromwell",giverType="NPC",giverId=15459,ender="Miner Cromwell",enderType="NPC",enderId=15459,wowhead="https://www.wowhead.com/wotlk/quest=8533",image="assets/images/quests/placeholder.png",desc="Back so soon? You'll be a real miner in no time $c. So, you already know the drill; I need you to go out, mine up a mess of copper ore, smelt it into bars and bring it back to me here. I know that's something you're capable of, the question is, are you willing?",logDesc="Bring 20 copper bars to Miner Cromwell in Durotar.",rewards={{id=21438,qty=1},{id=21509,qty=1}}} end
if not DB[8534] then DB[8534]={id=8534,zoneId=1377,name="Hive'Zora Scout Report",level=60,minLevel=60,ender="Windcaller Proudhorn",enderType="NPC",enderId=15191,wowhead="https://www.wowhead.com/wotlk/quest=8534",image="assets/images/quests/placeholder.png",desc="We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Azenel has been watching the silithid movements at Hive'Zora for several days now.  Find her and obtain a written report.  We need to be able to act on that information as soon as possible, $N.",logDesc="Contact Cenarion Scout Azenel inside Hive'Zora and return the Hive'Zora Scout Report to Windcaller Proudhorn at Cenarion Hold.  You must also bring Tactical Task Briefing VI in order to complete this quest.",rewards={{id=20801,qty=1},{id=21133,qty=1}}} end
if not DB[8535] then DB[8535]={id=8535,zoneId=1377,name="Hoary Templar",level=60,minLevel=60,ender="Bor Wildmane",enderType="NPC",enderId=15306,wowhead="https://www.wowhead.com/wotlk/quest=8535",image="assets/images/quests/placeholder.png",desc="The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.$B$BFind a way to summon and destroy a Hoary Templar and report to Bor Wildmane.$B",logDesc="Summon and slay a Hoary Templar and report back to Bor Wildmane in Cenarion Hold.  You must also bring Tactical Task Briefing IV in order to complete this quest.",rewards={{id=20801,qty=1},{id=20809,qty=1}}} end
if not DB[8536] then DB[8536]={id=8536,zoneId=1377,name="Earthen Templar",level=60,minLevel=60,ender="Bor Wildmane",enderType="NPC",enderId=15306,wowhead="https://www.wowhead.com/wotlk/quest=8536",image="assets/images/quests/placeholder.png",desc="The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.$B$BFind a way to summon and destroy an Earthen Templar and report to Bor Wildmane.",logDesc="Summon and slay an Earthen Templar and report back to Bor Wildmane in Cenarion Hold.  You must also bring Tactical Task Briefing III in order to complete this quest.",rewards={{id=20801,qty=1},{id=21133,qty=1}}} end
if not DB[8537] then DB[8537]={id=8537,zoneId=1377,name="Crimson Templar",level=60,minLevel=60,ender="Bor Wildmane",enderType="NPC",enderId=15306,wowhead="https://www.wowhead.com/wotlk/quest=8537",image="assets/images/quests/placeholder.png",desc="The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.$B$BFind a way to summon and destroy a Crimson Templar and report to Bor Wildmane.",logDesc="Summon and slay a Crimson Templar and report back to Bor Wildmane in Cenarion Hold.  You must also bring Tactical Task Briefing II in order to complete this quest.",rewards={{id=20801,qty=1},{id=20809,qty=1}}} end
if not DB[8538] then DB[8538]={id=8538,zoneId=1377,name="The Four Dukes",level=60,minLevel=60,ender="Commander Mar'alith",enderType="NPC",enderId=15181,wowhead="https://www.wowhead.com/wotlk/quest=8538",image="assets/images/quests/placeholder.png",desc="The links between the Twilight's Hammer and the Abyssal Council are proving to be more important than we had expected.$B$BWe believe the elemental nobles known as the Abyssal Dukes are one of the primary force organizing the Twilight's Hammer cultists.  Find a way to lure the four Abyssal Dukes into our plane of existence and destroy them!$B$BYour dedication and prowess in past assignments have led us to choose you for this particular assignment.  We are certain you will succeed in this endeavor.",logDesc="Find a way to summon and slay the Duke of Cynders, the Duke of Fathoms, the Duke of Zephyrs and the Duke of Shards and report back to Commander Mar'alith in Cenarion Hold.  You must also bring Tactical Task Briefing V in order to complete this quest.",rewards={{id=21508,qty=1}}} end
if not DB[8539] then DB[8539]={id=8539,zoneId=1377,name="Target: Hive'Zora Hive Sisters",level=60,minLevel=60,ender="Commander Mar'alith",enderType="NPC",enderId=15181,wowhead="https://www.wowhead.com/wotlk/quest=8539",image="assets/images/quests/placeholder.png",desc="Reinforcements have been called on to join the assault on Hive'Zora.  You have been selected to target Hive'Zora hive sisters.  Report back to Commander Mar'alith after completing your task.",logDesc="Slay 30 Hive'Zora Hive Sisters and report back to Commander Mar'alith at Cenarion Hold in Silithus.  You must also bring Combat Task Briefing V in order to complete this quest.",rewards={{id=20802,qty=1}}} end
if not DB[8540] then DB[8540]={id=8540,zoneId=1377,name="Boots for the Guard",level=60,minLevel=60,ender="Vish Kozus",enderType="NPC",enderId=15182,wowhead="https://www.wowhead.com/wotlk/quest=8540",image="assets/images/quests/placeholder.png",desc="The mounted division of the Cenarion Hold guard is in short supply of ornate mithril boots.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.",logDesc="Bring 3 Ornate Mithril Boots to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing II in order to complete this quest.",rewards={{id=20800,qty=1},{id=21132,qty=1}}} end
if not DB[8541] then DB[8541]={id=8541,zoneId=1377,name="Grinding Stones for the Guard",level=60,minLevel=60,ender="Vish Kozus",enderType="NPC",enderId=15182,wowhead="https://www.wowhead.com/wotlk/quest=8541",image="assets/images/quests/placeholder.png",desc="The Cenarion Hold guard is in short supply of grinding stones.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.",logDesc="Bring 10 Dense Grinding Stones, 10 Solid Grinding Stones and 10 Heavy Grinding Stones to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing III in order to complete this quest.",rewards={{id=20800,qty=1},{id=21132,qty=1}}} end
if not DB[8542] then DB[8542]={id=8542,zoneId=-365,name="The Horde Needs Tin Bars!",level=60,minLevel=1,giver="Grunt Maug",giverType="NPC",giverId=15460,ender="Grunt Maug",enderType="NPC",enderId=15460,wowhead="https://www.wowhead.com/wotlk/quest=8542",image="assets/images/quests/placeholder.png",desc="Lok'tar, $r, I'm sure you already know that we're going to war at Ahn'Qiraj with the insects. But first the Warchief has decided that we're going to do something called 'prepare'. Though I'd rather be sharpening weapons and hammering armor into shape, I'm proud to have been chosen to be in charge of tin bar collection here. But I cannot do that without your help.$B$BSo I need you to go out and make tin bars and bring them back to me here. I think I'm going to need more than I can count.$B",logDesc="Bring 20 Tin Bars to Grunt Maug at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21510,qty=1}}} end
if not DB[8543] then DB[8543]={id=8543,zoneId=-365,name="The Horde Needs More Tin Bars!",level=60,minLevel=1,giver="Grunt Maug",giverType="NPC",giverId=15460,ender="Grunt Maug",enderType="NPC",enderId=15460,wowhead="https://www.wowhead.com/wotlk/quest=8543",image="assets/images/quests/placeholder.png",desc="Very good, I see that you are serious about the war. I'm a little edgy waiting for it to start though, which means I'm going to get angry if you don't start bringing in the goods faster. Maybe I can just practice on you instead.$B$BHar! Maybe not, 'cuz then who would bring me back the tin bars?",logDesc="Bring 20 tin bars to Grunt Maug in Durotar.",rewards={{id=21438,qty=3},{id=21510,qty=1}}} end
if not DB[8544] then DB[8544]={id=8544,zoneId=3428,name="Conqueror's Spaulders",level=60,minLevel=60,giver="Andorgos",giverType="NPC",giverId=15502,ender="Andorgos",enderType="NPC",enderId=15502,poiX=-8496,poiY=1933,wowhead="https://www.wowhead.com/wotlk/quest=8544",image="assets/images/quests/placeholder.png",desc="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.$B$BBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!",logDesc="Bring the Qiraji Bindings of Command, 2 Idols of Night, 5 Stone Scarabs and 5 Clay Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21330,qty=1}}} end
if not DB[8545] then DB[8545]={id=8545,zoneId=-365,name="The Horde Needs Mithril Bars!",level=60,minLevel=1,giver="Senior Sergeant T'kelah",giverType="NPC",giverId=15469,ender="Senior Sergeant T'kelah",enderType="NPC",enderId=15469,wowhead="https://www.wowhead.com/wotlk/quest=8545",image="assets/images/quests/placeholder.png",desc="$C, the war it is comin' and the only thing we can do is prepare for it. That be where you and I can help each other, mon. Ya see, they put me in charge of collectin' all the mithril bars we be needin' ta build for all the things we gonna need. An I still be needin' more!$B$BSo, I be hopin' that you can get out there an mine us up some mithril, then smelt it into bars. Sound like something you can do for us?",logDesc="Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21512,qty=1}}} end
if not DB[8546] then DB[8546]={id=8546,zoneId=-365,name="The Horde Needs More Mithril Bars!",level=60,minLevel=1,giver="Senior Sergeant T'kelah",giverType="NPC",giverId=15469,ender="Senior Sergeant T'kelah",enderType="NPC",enderId=15469,wowhead="https://www.wowhead.com/wotlk/quest=8546",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=7},{id=21512,qty=1}}} end
if not DB[8547] then DB[8547]={id=8547,zoneId=3431,name="Welcome!",level=1,minLevel=1,ender="Marsilla Dawnstar",enderType="NPC",enderId=15493,wowhead="https://www.wowhead.com/wotlk/quest=8547",image="assets/images/quests/placeholder.png",desc="Welcome to the World of Warcraft!$B$BAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Marsilla Dawnstar in Falconwing Square.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.$B$BThanks again, and enjoy your stay in the World of Warcraft!",logDesc="Bring the Falconwing Square Gift Voucher to Marsilla Dawnstar in Falconwing Square.",choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}} end
if not DB[8548] then DB[8548]={id=8548,zoneId=1377,name="Volunteer's Battlegear",level=60,minLevel=60,giver="Vargus",giverType="NPC",giverId=15176,ender="Vargus",enderType="NPC",enderId=15176,poiX=-6861,poiY=753,wowhead="https://www.wowhead.com/wotlk/quest=8548",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, $N.$B$BYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.  ",logDesc="Bring 5 Cenarion Combat Badges, 3 Cenarion Logistics Badges and 7 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus.  You must also attain Friendly reputation with Cenarion Circle to be able to complete this quest.",choiceRewards={{id=21178,qty=1},{id=21179,qty=1},{id=21187,qty=1}}} end
if not DB[8549] then DB[8549]={id=8549,zoneId=-365,name="The Horde Needs Peacebloom!",level=60,minLevel=1,giver="Herbalist Proudfeather",giverType="NPC",giverId=15477,ender="Herbalist Proudfeather",enderType="NPC",enderId=15477,wowhead="https://www.wowhead.com/wotlk/quest=8549",image="assets/images/quests/placeholder.png",desc="It is said that every generation must face a defining trial. I fear the Ahn'Qiraj War will be the crucible in which our mettle is tested. So we prepare, and in so doing find what we are made of.$B$BI have volunteered to help the Horde by gathering as much peacebloom as possible, so that it can be made into potions for the war. I hope that you are here to lend me your aid. If so, then I need you to bring back to me a good quantity of the herb. Will you assist me, $c?",logDesc="Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21509,qty=1}}} end
if not DB[8550] then DB[8550]={id=8550,zoneId=-365,name="The Horde Needs More Peacebloom!",level=60,minLevel=1,giver="Herbalist Proudfeather",giverType="NPC",giverId=15477,ender="Herbalist Proudfeather",enderType="NPC",enderId=15477,wowhead="https://www.wowhead.com/wotlk/quest=8550",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=1},{id=21509,qty=1}}} end
if not DB[8551] then DB[8551]={id=8551,zoneId=33,name="The Captain's Chest",level=42,minLevel=35,ender="Captain Hecklebury Smotts",enderType="NPC",enderId=2500,wowhead="https://www.wowhead.com/wotlk/quest=8551",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.$B$BUntil...$B$BThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!$B$BI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.",logDesc="Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.",rewards={{id=11469,qty=1}}} end
if not DB[8552] then DB[8552]={id=8552,zoneId=33,name="The Monogrammed Sash",level=50,minLevel=35,ender="Captain Hecklebury Smotts",enderType="NPC",enderId=2500,rewardNextId=8553,wowhead="https://www.wowhead.com/wotlk/quest=8552",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This fine sash has the letters \"HS\" embroidered along its hem.",logDesc="Return the Monogrammed Sash to its owner."} end
if not DB[8553] then DB[8553]={id=8553,zoneId=33,name="The Captain's Cutlass",level=42,minLevel=35,giver="Captain Hecklebury Smotts",giverType="NPC",giverId=2500,ender="Sprogger",enderType="NPC",enderId=2594,rewardNextId=8554,poiX=-14300,poiY=517,wowhead="https://www.wowhead.com/wotlk/quest=8553",image="assets/images/quests/placeholder.png",xpDiff=1,desc="After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.$B$BThis time another of the giants, Negolash, stole my cutlass.$B$BFace Negolash and bring me my cutlass!$B$BSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant.",logDesc="Speak with Sprogger."} end
if not DB[8554] then DB[8554]={id=8554,zoneId=33,name="Facing Negolash",level=42,minLevel=35,giver="Sprogger",giverType="NPC",giverId=2594,ender="Captain Hecklebury Smotts",enderType="NPC",enderId=2500,poiX=-14302,poiY=520,wowhead="https://www.wowhead.com/wotlk/quest=8554",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Negolash is a hungry giant.$B$BWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!$B$BIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!",logDesc="Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.$B$BKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.",rewards={{id=4130,qty=1}}} end
if not DB[8555] then DB[8555]={id=8555,zoneId=440,name="The Charge of the Dragonflights",level=60,minLevel=60,giver="3",giverType="NPC",giverId=15192,ender="3",enderType="NPC",enderId=15192,poiX=-8240,poiY=-4649,wowhead="https://www.wowhead.com/wotlk/quest=8555",image="assets/images/quests/placeholder.png",xpDiff=1} end
if not DB[8556] then DB[8556]={id=8556,zoneId=3428,name="Signet of Unyielding Strength",level=60,minLevel=60,giver="Windcaller Yessendra",giverType="NPC",giverId=15498,ender="Windcaller Yessendra",enderType="NPC",enderId=15498,poiX=-6845,poiY=724,wowhead="https://www.wowhead.com/wotlk/quest=8556",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.$B$BThe gems that adorn Qiraji idols would work quite well, as their quality is superior.$B$BBring me the ring and idols and I'll create a powerful ring for you, $c.",logDesc="Bring 1 Qiraji Magisterial Ring, 2 Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus.  You must also attain Honored reputation with Cenarion Circle to complete this quest.",rewards={{id=21393,qty=1}}} end
if not DB[8557] then DB[8557]={id=8557,zoneId=3428,name="Drape of Unyielding Strength",level=60,minLevel=60,giver="Keyl Swiftclaw",giverType="NPC",giverId=15500,ender="Keyl Swiftclaw",enderType="NPC",enderId=15500,poiX=-6877,poiY=735,wowhead="https://www.wowhead.com/wotlk/quest=8557",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, $N.  I can make you a protective item that'll be of assistance in the fight against our enemy, $c.$B$BI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.$B$BI promise you won't be disappointed.",logDesc="Bring 1 Qiraji Martial Drape, 2 Onyx Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest.",rewards={{id=21394,qty=1}}} end
if not DB[8558] then DB[8558]={id=8558,zoneId=3428,name="Sickle of Unyielding Strength",level=60,minLevel=60,giver="Warden Haro",giverType="NPC",giverId=15499,ender="Warden Haro",enderType="NPC",enderId=15499,poiX=-6863,poiY=756,wowhead="https://www.wowhead.com/wotlk/quest=8558",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.$B$BJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, $N, and I will make you a powerful weapon from the finest Qiraji materials.",logDesc="Bring 1 Qiraji Spiked Hilt, 2  Alabaster Idols, 5 Crystal Scarabs and 5 Stone Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",rewards={{id=21392,qty=1}}} end
if not DB[8559] then DB[8559]={id=8559,zoneId=3428,name="Conqueror's Greaves",level=60,minLevel=60,giver="Kandrostrasz",giverType="NPC",giverId=15503,ender="Kandrostrasz",enderType="NPC",enderId=15503,poiX=-8500,poiY=1937,wowhead="https://www.wowhead.com/wotlk/quest=8559",image="assets/images/quests/placeholder.png",desc="Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.$B$BBring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you.$B$BYou will find them useful in the fight against the enemy.",logDesc="Bring the Qiraji Bindings of Command, 2 Idols of War, 5 Ivory Scarabs and 5 Gold Scarabs to Kandrostrasz in Ahn'Qiraj.  This quest also requires Neutral faction with the Brood of Nozdormu.",rewards={{id=21333,qty=1}}} end
if not DB[8560] then DB[8560]={id=8560,zoneId=3428,name="Conqueror's Legguards",level=60,minLevel=60,giver="Kandrostrasz",giverType="NPC",giverId=15503,ender="Kandrostrasz",enderType="NPC",enderId=15503,poiX=-8500,poiY=1937,wowhead="https://www.wowhead.com/wotlk/quest=8560",image="assets/images/quests/placeholder.png",desc="You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.$B$BThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.$B$BHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.$B$BBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.",logDesc="Bring Ouro's Intact Hide, 2 Idols of Death, 5 Bronze Scarabs and 5 Ivory Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21332,qty=1}}} end
if not DB[8561] then DB[8561]={id=8561,zoneId=3428,name="Conqueror's Crown",level=60,minLevel=60,giver="Andorgos",giverType="NPC",giverId=15502,ender="Andorgos",enderType="NPC",enderId=15502,poiX=-8496,poiY=1933,wowhead="https://www.wowhead.com/wotlk/quest=8561",image="assets/images/quests/placeholder.png",desc="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.$B$BIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.$B$BBring me the components I require, $N.  I will give you a headpiece of unmatched power.",logDesc="Bring Vek'nilash's Circlet, 2 Idols of the Sun, 5 Stone Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21329,qty=1}}} end
if not DB[8562] then DB[8562]={id=8562,zoneId=3428,name="Conqueror's Breastplate",level=60,minLevel=60,giver="Vethsera",giverType="NPC",giverId=15504,ender="Vethsera",enderType="NPC",enderId=15504,poiX=-8500,poiY=1934,wowhead="https://www.wowhead.com/wotlk/quest=8562",image="assets/images/quests/placeholder.png",desc="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.$B$BWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.$B$BDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!",logDesc="Bring the the Carapace of the Old God, 2 Idols of War, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn'Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21331,qty=1}}} end
if not DB[8563] then DB[8563]={id=8563,zoneId=-61,name="Warlock Training",level=1,minLevel=1,giver="Magistrix Erona",giverType="NPC",giverId=15278,ender="Summoner Teli'Larien",enderType="NPC",enderId=15283,poiX=10352,poiY=-6360,wowhead="https://www.wowhead.com/wotlk/quest=8563",image="assets/images/quests/placeholder.png",xpDiff=3,desc="As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young warlocks here on Sunstrider Isle, your trainer is Summoner Teli'Larien.  Speak with Summoner Teli'Larien and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.$B$BYour trainer - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.",logDesc="Speak with Summoner Teli'Larien - the Warlock class trainer - inside the Sunspire on Sunstrider Isle."} end
if not DB[8564] then DB[8564]={id=8564,zoneId=-262,name="Priest Training",level=1,minLevel=1,giver="Magistrix Erona",giverType="NPC",giverId=15278,ender="Matron Arena",enderType="NPC",enderId=15284,poiX=10352,poiY=-6360,wowhead="https://www.wowhead.com/wotlk/quest=8564",image="assets/images/quests/placeholder.png",xpDiff=3,desc="As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young priests here on Sunstrider Isle, your trainer is Matron Arena.  Speak with the matron and see what training she has available for you.  The things she will teach do have a cost, so bring some coin with you.$B$BMatron Arena - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.",logDesc="Speak with Matron Arena - the Priest class trainer - inside the Sunspire on Sunstrider Isle."} end
