if not DB[8572] then DB[8572]={id=8572,zoneId=1377,name="Veteran's Battlegear",level=60,minLevel=60,giver="Vargus",giverType="NPC",giverId=15176,ender="Vargus",enderType="NPC",enderId=15176,poiX=-6861,poiY=753,wowhead="https://www.wowhead.com/wotlk/quest=8572",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, $N.$B$BYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.",logDesc="Bring 7 Cenarion Combat Badges, 4 Cenarion Logistics Badges and 4 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus.  You must also attain Honored reputation with Cenarion Circle to be able to complete this quest.$B",choiceRewards={{id=21181,qty=1},{id=21182,qty=1},{id=21183,qty=1}}} end
if not DB[8573] then DB[8573]={id=8573,zoneId=1377,name="Champion's Battlegear",level=60,minLevel=60,giver="Vargus",giverType="NPC",giverId=15176,ender="Vargus",enderType="NPC",enderId=15176,poiX=-6861,poiY=753,wowhead="https://www.wowhead.com/wotlk/quest=8573",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, $N.$B$BYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.",logDesc="Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 20 Cenarion Tactical Badges and 1 Mark of Cenarius to Vargus at Cenarion Hold in Silithus.  You must also attain Exalted reputation with Cenarion Circle to be able to complete this quest.$B",choiceRewards={{id=21188,qty=1},{id=21190,qty=1},{id=21180,qty=1}}} end
if not DB[8574] then DB[8574]={id=8574,zoneId=1377,name="Stalwart's Battlegear",level=60,minLevel=60,giver="Vargus",giverType="NPC",giverId=15176,ender="Vargus",enderType="NPC",enderId=15176,poiX=-6861,poiY=753,wowhead="https://www.wowhead.com/wotlk/quest=8574",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show, $N.$B$BYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.",logDesc="Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 17 Cenarion Tactical Badges and 1 Mark of Remulos to Vargus at Cenarion Hold in Silithus.  You must also attain Revered reputation with Cenarion Circle to be able to complete this quest.",choiceRewards={{id=21184,qty=1},{id=21185,qty=1},{id=21186,qty=1},{id=21189,qty=1}}} end
if not DB[8575] then DB[8575]={id=8575,zoneId=16,name="Azuregos's Magical Ledger",level=60,minLevel=60,ender="Narain Soothfancy",enderType="NPC",enderId=11811,rewardNextId=8576,wowhead="https://www.wowhead.com/wotlk/quest=8575",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You cannot understand a single word on this ledger. You don't even know what language it is written in!",logDesc="Deliver Azuregos's Magical Ledger to Narain Soothfancy in Tanaris."} end
if not DB[8576] then DB[8576]={id=8576,zoneId=440,name="Translating the Ledger",level=60,minLevel=60,giver="Narain Soothfancy",giverType="NPC",giverId=11811,ender="Narain Soothfancy",enderType="NPC",enderId=11811,poiX=-6730,poiY=-4720,wowhead="https://www.wowhead.com/wotlk/quest=8576",image="assets/images/quests/placeholder.png",xpDiff=1} end
if not DB[8577] then DB[8577]={id=8577,zoneId=440,name="Stewvul, Ex-B.F.F.",level=60,minLevel=60,giver="Narain Soothfancy",giverType="NPC",giverId=11811,rewardNextId=8578,poiX=-6730,poiY=-4720,wowhead="https://www.wowhead.com/wotlk/quest=8577",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If I am to translate anything, I will need my scrying goggles. Unfortunately, those were stolen quite some time ago by my ex-best friend forever, Stewvul. He broke my heart in five places and then left me here to rot.$B$BWith the help of my trusty crystal ball, I've isolated his whereabouts to either the Greymane Wall in Silverpine or what appears to be a portal world in the Outland that is currently being overrun by the Burning Legion. You're going to have to track him down and get my goggles back, $N!",logDesc="Narain Soothfancy wants you to find his ex-best friend forever (BFF), Stewvul, and take back the scrying goggles that Stewvul stole from him."} end
if not DB[8578] then DB[8578]={id=8578,zoneId=2717,name="Scrying Goggles? No Problem!",level=60,minLevel=60,ender="Narain Soothfancy",enderType="NPC",enderId=11811,wowhead="https://www.wowhead.com/wotlk/quest=8578",image="assets/images/quests/placeholder.png",xpDiff=6,desc="<You hear a sigh of relief escape the crate.>$B$BYou just want his scrying goggles? Great! That will be no problem... Just give me a minute to... Hey! Where the... Dagnabbit!$B$BWell, there's some bad news and some worse news. The bad news is that I lost the goggles. The worse news is that I lost them when I was nosing around in the Molten Core last month. Yep, the Molten Core... I guess that concludes our business! Bye!",logDesc="Find Narain's Scrying Goggles and return them to Narain Soothfancy in Tanaris.",rewards={{id=18253,qty=3}}} end
if not DB[8579] then DB[8579]={id=8579,zoneId=3428,name="Mortal Champions",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=8579",image="assets/images/quests/placeholder.png",xpDiff=5} end
if not DB[8580] then DB[8580]={id=8580,zoneId=-365,name="The Horde Needs Firebloom!",level=60,minLevel=1,giver="Batrider Pele'keiki",giverType="NPC",giverId=15508,ender="Batrider Pele'keiki",enderType="NPC",enderId=15508,wowhead="https://www.wowhead.com/wotlk/quest=8580",image="assets/images/quests/placeholder.png",desc="Hey, $c. Ya you, mon! There be a whole mess of firebloom the Horde thinkin' they need for this Ahn'Qiraj war effort. Maybe they put it in nice things that go boom? Maybe they give it to the Alliance as fuel for their steam tanks? Who knows? Not Pele'keiki!$B$BPele'keiki know this though... he know you gonna help him out and bring back lots of the firebloom, right, mon?",logDesc="Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21511,qty=1}}} end
if not DB[8581] then DB[8581]={id=8581,zoneId=-365,name="The Horde Needs More Firebloom!",level=60,minLevel=1,giver="Batrider Pele'keiki",giverType="NPC",giverId=15508,ender="Batrider Pele'keiki",enderType="NPC",enderId=15508,wowhead="https://www.wowhead.com/wotlk/quest=8581",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=5},{id=21511,qty=1}}} end
if not DB[8582] then DB[8582]={id=8582,zoneId=-365,name="The Horde Needs Purple Lotus!",level=60,minLevel=1,giver="Apothecary Jezel",giverType="NPC",giverId=15512,ender="Apothecary Jezel",enderType="NPC",enderId=15512,wowhead="https://www.wowhead.com/wotlk/quest=8582",image="assets/images/quests/placeholder.png",desc="The purple lotus, $c, is a reagent in a great many potions, elixirs and oils, some of which will be of use to us at Ahn'Qiraj. We're going to need to create an immense number of those potions for the war effort. And I'm going to experiment to find more uses for the lotus as well. But to do all of that I'm going to need a great quantity of the flower.$B$BThat's where you come in. Go out into the field and collect up as many purple lotuses as you can. Is this something that you are willing to do for us?",logDesc="Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21512,qty=1}}} end
if not DB[8583] then DB[8583]={id=8583,zoneId=-365,name="The Horde Needs More Purple Lotus!",level=60,minLevel=1,giver="Apothecary Jezel",giverType="NPC",giverId=15512,ender="Apothecary Jezel",enderType="NPC",enderId=15512,wowhead="https://www.wowhead.com/wotlk/quest=8583",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=7},{id=21512,qty=1}}} end
if not DB[8584] then DB[8584]={id=8584,zoneId=440,name="Never Ask Me About My Business",level=60,minLevel=60,giver="Narain Soothfancy",giverType="NPC",giverId=11811,ender="Dirge Quikcleave",enderType="NPC",enderId=8125,rewardNextId=8585,poiX=-6730,poiY=-4720,wowhead="https://www.wowhead.com/wotlk/quest=8584",image="assets/images/quests/placeholder.png",xpDiff=1,desc="If there is one thing that you should know about me, it is this: NEVER ask me about my business! I work with things you simply cannot understand. Like for example: Do you know what a psychotronic muzzledorf is? Of course you don't! And that's why we leave the planning to me and the fetching to you.$B$BAs I said earlier, if this is going to work, we're going to need a 500 pound chicken.$B$BHead to Gadgetzan and speak with Dirge Quikcleave - he'll get you started on finding a suitable specimen.$B",logDesc="Narain Soothfancy in Tanaris wants you to speak with Dirge Quikcleave in Gadgetzan."} end
if not DB[8585] then DB[8585]={id=8585,zoneId=440,name="The Isle of Dread!",level=60,minLevel=60,giver="Dirge Quikcleave",giverType="NPC",giverId=8125,ender="Dirge Quikcleave",enderType="NPC",enderId=8125,rewardNextId=8586,poiX=-7168,poiY=-3850,wowhead="https://www.wowhead.com/wotlk/quest=8585",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Legend has it that the chimaerok of the Isle of Dread in Feralas have the most succulent and tender vittles in existence! Now these chimaerok also have a daddy who, with proper preparation, may or may not look like a 500 pound chicken.$B$BHead to the Isle of Dread and kill Lord Lakmaeran and bring me his fresh carcass. That should satisfy the gnome. To satisfy me, you'll need to get your hands on some chimaerok tenderloin.$B$BDo this and you'll have your 500 pound chicken and a little something extra.$B",logDesc="Recover Lakmaeran's Carcass and 20 Chimaerok Tenderloins for Dirge Quikcleave in Tanaris."} end
if not DB[8586] then DB[8586]={id=8586,zoneId=440,name="Dirge's Kickin' Chimaerok Chops",level=60,minLevel=60,giver="Dirge Quikcleave",giverType="NPC",giverId=8125,ender="Dirge Quikcleave",enderType="NPC",enderId=8125,rewardNextId=8587,poiX=-7168,poiY=-3850,wowhead="https://www.wowhead.com/wotlk/quest=8586",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="My recipe is complete! What I need from you now is some rocket fuel and deeprock salt. I'll handle the spices and the meat you brought me will cover the rest.$B$BAfter you bring me what I asked for, the chicken will be ready to take back to Narain.",logDesc="Dirge Quikcleave in Gadgetzan wants you to bring him 20 Goblin Rocket Fuel and 20 Deeprock Salt.",rewards={{id=21025,qty=1},{id=21023,qty=20}}} end
if not DB[8587] then DB[8587]={id=8587,zoneId=440,name="Return to Narain",level=60,minLevel=60,giver="Dirge Quikcleave",giverType="NPC",giverId=8125,ender="Narain Soothfancy",enderType="NPC",enderId=11811,poiX=-7168,poiY=-3850,wowhead="https://www.wowhead.com/wotlk/quest=8587",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'm a goblin of my word, kid. Here's your 500 pound chicken.$B$BWhat a gnome wants with a 500 pound chicken, I'll never know...$B$B<Dirge grumbles something unintelligible.>$B$BProbably to sleep in it... Dirty gnomes...",logDesc="Deliver the 500 Pound Chicken to Narain Soothfancy in Tanaris."} end
if not DB[8588] then DB[8588]={id=8588,zoneId=-365,name="The Horde Needs Heavy Leather!",level=60,minLevel=1,giver="Skinner Jamani",giverType="NPC",giverId=15515,ender="Skinner Jamani",enderType="NPC",enderId=15515,wowhead="https://www.wowhead.com/wotlk/quest=8588",image="assets/images/quests/placeholder.png",desc="Since we're preparing for war, it might be best if we get all of the goods we need first, don't you think, mon? One of the staples of the war materiel that we're producing is heavy leather. We'll use it for just about everything, from reinforcement to armor, and good old plain tarps too.$B$BBut first we need to get our hands on more of it. That's your job, $c. Sharpen your knife and bring me back a bundle. Then we'll talk further.",logDesc="Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21511,qty=1}}} end
if not DB[8589] then DB[8589]={id=8589,zoneId=-365,name="The Horde Needs More Heavy Leather!",level=60,minLevel=1,giver="Skinner Jamani",giverType="NPC",giverId=15515,ender="Skinner Jamani",enderType="NPC",enderId=15515,wowhead="https://www.wowhead.com/wotlk/quest=8589",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=5},{id=21511,qty=1}}} end
if not DB[8590] then DB[8590]={id=8590,zoneId=-365,name="The Horde Needs Thick Leather!",level=60,minLevel=1,giver="Sergeant Umala",giverType="NPC",giverId=15522,ender="Sergeant Umala",enderType="NPC",enderId=15522,wowhead="https://www.wowhead.com/wotlk/quest=8590",image="assets/images/quests/placeholder.png",desc="I'm glad that you decided to speak to me about this, $c. It looks like the Horde's preparations for the upcoming Ahn'Qiraj War are in full swing. But you and I still need to do our part.$B$BI've been asked to collect a great number of thick leather skins for use in all manner of war materiel, and I need you to help me by going out there and gathering them up. There's honor and the gratitude of the Horde in it for you should you decide to help. Will you?",logDesc="Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21512,qty=1}}} end
if not DB[8591] then DB[8591]={id=8591,zoneId=-365,name="The Horde Needs More Thick Leather!",level=60,minLevel=1,giver="Sergeant Umala",giverType="NPC",giverId=15522,ender="Sergeant Umala",enderType="NPC",enderId=15522,wowhead="https://www.wowhead.com/wotlk/quest=8591",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=7},{id=21512,qty=1}}} end
if not DB[8592] then DB[8592]={id=8592,zoneId=3428,name="Tiara of the Oracle",level=60,minLevel=60,giver="Andorgos",giverType="NPC",giverId=15502,ender="Andorgos",enderType="NPC",enderId=15502,poiX=-8496,poiY=1933,wowhead="https://www.wowhead.com/wotlk/quest=8592",image="assets/images/quests/placeholder.png",desc="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.$B$BIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.$B$BBring me the components I require, $N.  I will give you a headpiece of unmatched power.",logDesc="Bring Vek'nilash's Circlet, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21348,qty=1}}} end
if not DB[8593] then DB[8593]={id=8593,zoneId=3428,name="Trousers of the Oracle",level=60,minLevel=60,giver="Kandrostrasz",giverType="NPC",giverId=15503,ender="Kandrostrasz",enderType="NPC",enderId=15503,poiX=-8500,poiY=1937,wowhead="https://www.wowhead.com/wotlk/quest=8593",image="assets/images/quests/placeholder.png",desc="You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.$B$BThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.$B$BHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.$B$BBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.",logDesc="Bring Ouro's Intact Hide, 2 Idols of Life, 5 Gold Scarabs and 5 Clay Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21352,qty=1}}} end
if not DB[8594] then DB[8594]={id=8594,zoneId=3428,name="Mantle of the Oracle",level=60,minLevel=60,giver="Andorgos",giverType="NPC",giverId=15502,ender="Andorgos",enderType="NPC",enderId=15502,poiX=-8496,poiY=1933,wowhead="https://www.wowhead.com/wotlk/quest=8594",image="assets/images/quests/placeholder.png",desc="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.$B$BBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!",logDesc="Bring the Qiraji Bindings of Command, 2 Idols of Rebirth, 5 Silver Scarabs and 5 Ivory Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21350,qty=1}}} end
if not DB[8595] then DB[8595]={id=8595,zoneId=3428,name="Mortal Champions",level=60,minLevel=60,giver="Kandrostrasz",giverType="NPC",giverId=15503,ender="Kandrostrasz",enderType="NPC",enderId=15503,poiX=-8500,poiY=1937,wowhead="https://www.wowhead.com/wotlk/quest=8595",image="assets/images/quests/placeholder.png"} end
if not DB[8596] then DB[8596]={id=8596,zoneId=3428,name="Footwraps of the Oracle",level=60,minLevel=60,giver="Kandrostrasz",giverType="NPC",giverId=15503,ender="Kandrostrasz",enderType="NPC",enderId=15503,poiX=-8500,poiY=1937,wowhead="https://www.wowhead.com/wotlk/quest=8596",image="assets/images/quests/placeholder.png",desc="Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.$B$BBring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you.$B$BYou will find them useful in the fight against the enemy.",logDesc="Bring the Qiraji Bindings of Command, 2 Idols of Death, 5 Bronze Scarabs and 5 Gold Scarabs to Kandrostrasz in Ahn'Qiraj.  This quest also requires Neutral faction with the Brood of Nozdormu.",rewards={{id=21349,qty=1}}} end
if not DB[8597] then DB[8597]={id=8597,zoneId=440,name="Draconic for Dummies",level=60,minLevel=60,giver="Narain Soothfancy",giverType="NPC",giverId=11811,rewardNextId=8598,poiX=-6730,poiY=-4720,wowhead="https://www.wowhead.com/wotlk/quest=8597",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I knew that book would come in handy some day! Thankfully, I had the wit and foresight to stow it somewhere safe.$B$BDon't worry, it's in a place that nobody could ever hope to find it! I needed a gyrocopter just to get there the first time. Unfortunately I crashed it on the beach on my way back. It was through that accident that I gained these super-gnomish psychic powers!$B$BLook for my crashed gyrocopter somewhere on Land's End Beach and swim south from there! You'll know the spot when you see it!",logDesc="Find Narain Soothfancy's book, buried on an island in the South Seas."} end
if not DB[8598] then DB[8598]={id=8598,zoneId=440,name="rAnS0m",level=60,minLevel=60,ender="Narain Soothfancy",enderType="NPC",enderId=11811,rewardNextId=8606,wowhead="https://www.wowhead.com/wotlk/quest=8598",image="assets/images/quests/placeholder.png",xpDiff=3,desc="<The text on this note is made up of various typefaces glued onto the parchment's surface.>$B$BWe've got your precious book, gnome. If you ever want to see it again, you'll do exactly as we ask.$B$B<A detailed set of instructions is listed, spanning 3 pages.>$B$BBring the money and come alone!",logDesc="Return the Ransom Letter to Narain Soothfancy in Tanaris.$B"} end
if not DB[8599] then DB[8599]={id=8599,zoneId=440,name="Love Song for Narain",level=60,minLevel=60,giver="Meridith the Mermaiden",giverType="NPC",giverId=15526,ender="Narain Soothfancy",enderType="NPC",enderId=11811,poiX=-10293,poiY=-4319,wowhead="https://www.wowhead.com/wotlk/quest=8599",image="assets/images/quests/placeholder.png",xpDiff=3,desc="It isn't often that I get visitors. As a matter of fact, the last time I had a visitor was when I rescued that dear, sweet gnome from the wreckage of the crashed flying machine.$B$B<Meridith gazes into nothingness, lost in a memory.>$B$BDo you know him? Narain? Narain Soothfancy? Oh it would mean so much to me if somebody would deliver a message to him for me. I must tell him how I feel! I know it's love! I just know it!$B$BCould you possibly deliver a message to Narain? I would be forever indebted to you!",logDesc="Take Meridith's Love Letter to Narain Soothfancy in Tanaris."} end
if not DB[8600] then DB[8600]={id=8600,zoneId=-365,name="The Horde Needs Rugged Leather!",level=60,minLevel=1,giver="Doctor Serratus",giverType="NPC",giverId=15525,ender="Doctor Serratus",enderType="NPC",enderId=15525,wowhead="https://www.wowhead.com/wotlk/quest=8600",image="assets/images/quests/placeholder.png",desc="I find that the fit of the knife in your palm is more important than the edge on it. Even the dullest blade can be made to cut if pressure is being properly applied through it, wouldn't you agree, $c? But you and I don't have such problems as we maintain the sharpest of edges, yes? $B$BWell, no matter, I have a task for you. In service to the Horde, and to do your part for the Ahn'Qiraj war effort, I want you to return to me with a number of rugged leather skins. This is something that you will do, no?",logDesc="Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21513,qty=1}}} end
if not DB[8601] then DB[8601]={id=8601,zoneId=-365,name="The Horde Needs More Rugged Leather!",level=60,minLevel=1,giver="Doctor Serratus",giverType="NPC",giverId=15525,ender="Doctor Serratus",enderType="NPC",enderId=15525,wowhead="https://www.wowhead.com/wotlk/quest=8601",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=10},{id=21513,qty=1}}} end
if not DB[8602] then DB[8602]={id=8602,zoneId=3428,name="Stormcaller's Pauldrons",level=60,minLevel=60,giver="Andorgos",giverType="NPC",giverId=15502,ender="Andorgos",enderType="NPC",enderId=15502,poiX=-8496,poiY=1933,wowhead="https://www.wowhead.com/wotlk/quest=8602",image="assets/images/quests/placeholder.png",desc="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.$B$BBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!",logDesc="Bring the Qiraji Bindings of Dominance, 2 Idols of Life, 5 Gold Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21376,qty=1}}} end
if not DB[8603] then DB[8603]={id=8603,zoneId=3428,name="Vestments of the Oracle",level=60,minLevel=60,giver="Vethsera",giverType="NPC",giverId=15504,ender="Vethsera",enderType="NPC",enderId=15504,poiX=-8500,poiY=1934,wowhead="https://www.wowhead.com/wotlk/quest=8603",image="assets/images/quests/placeholder.png",desc="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.$B$BWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.$B$BDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!",logDesc="Bring the the Husk of the Old God, 2 Idols of Death, 5 Stone Scarabs and 5 Crystal Scarabs to Vethsera inside Ahn'Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21351,qty=1}}} end
if not DB[8604] then DB[8604]={id=8604,zoneId=-365,name="The Horde Needs Wool Bandages!",level=60,minLevel=1,giver="Healer Longrunner",giverType="NPC",giverId=15528,ender="Healer Longrunner",enderType="NPC",enderId=15528,wowhead="https://www.wowhead.com/wotlk/quest=8604",image="assets/images/quests/placeholder.png",desc="Greetings, $c. In preparation for the war at Ahn'Qiraj, I am here coordinating the Horde's efforts at gathering wool bandages. Unfortunately, out in the field, our soldiers cannot afford to rely upon the presence of a healer to keep them alive. Trust me, I know first hand. Thus, we're putting together all of these first aid kits for them.$B$BIf you have the time, I need many wool bandages. Return them to me here and I will see to it that you are properly rewarded.",logDesc="Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21510,qty=1}}} end
if not DB[8605] then DB[8605]={id=8605,zoneId=-365,name="The Horde Needs More Wool Bandages!",level=60,minLevel=1,giver="Healer Longrunner",giverType="NPC",giverId=15528,ender="Healer Longrunner",enderType="NPC",enderId=15528,wowhead="https://www.wowhead.com/wotlk/quest=8605",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=3},{id=21510,qty=1}}} end
if not DB[8606] then DB[8606]={id=8606,zoneId=440,name="Decoy!",level=60,minLevel=60,giver="Narain Soothfancy",giverType="NPC",giverId=11811,ender="Narain Soothfancy",enderType="NPC",enderId=11811,rewardNextId=8620,poiX=-6730,poiY=-4720,wowhead="https://www.wowhead.com/wotlk/quest=8606",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've got it! Here's what we're going to do. I'm going to fill a sack up with rocks and you're going to make the drop. I know it said that I should make the delivery and I'm going to - sort of.$B$B<Narain looks you up and down.>$B$BYes, you will do just fine. Take this turban, robe, and sack of rocks and head to the drop off point in Winterspring.$B$BI've included everything you need in this special kit. When they show up to pick up the goods, snuff them out! That will teach them to mess with Narain!$B",logDesc="Narain Soothfancy in Tanaris wants you to travel to Winterspring and place the Bag of Gold at the drop off point documented by the booknappers."} end
if not DB[8607] then DB[8607]={id=8607,zoneId=-365,name="The Horde Needs Mageweave Bandages!",level=60,minLevel=1,giver="Lady Callow",giverType="NPC",giverId=15529,ender="Lady Callow",enderType="NPC",enderId=15529,wowhead="https://www.wowhead.com/wotlk/quest=8607",image="assets/images/quests/placeholder.png",desc="I trust that you are speaking to me because you are going to help with the collection I have been entrusted to? Good! By whatever means, and I do mean whatever, I wish for you to gather up a good number of mageweave bandages. Fresh would be nice, but not absolutely necessary. Return them to me here, $c, and I will personally see to it that you are properly rewarded.",logDesc="Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21512,qty=1}}} end
if not DB[8608] then DB[8608]={id=8608,zoneId=-365,name="The Horde Needs More Mageweave Bandages!",level=60,minLevel=1,giver="Lady Callow",giverType="NPC",giverId=15529,ender="Lady Callow",enderType="NPC",enderId=15529,wowhead="https://www.wowhead.com/wotlk/quest=8608",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=7},{id=21512,qty=1}}} end
if not DB[8609] then DB[8609]={id=8609,zoneId=-365,name="The Horde Needs Runecloth Bandages!",level=60,minLevel=1,giver="Stoneguard Clayhoof",giverType="NPC",giverId=15532,ender="Stoneguard Clayhoof",enderType="NPC",enderId=15532,wowhead="https://www.wowhead.com/wotlk/quest=8609",image="assets/images/quests/placeholder.png",desc="It appears inevitable that the Horde and Alliance are on a collision course for war at Ahn'Qiraj. Surprisingly, it is not a war with each other, but rather with the silithid, and whatever force controls them. Also surprisingly, both sides are doing their part to gather the resources necessary to wage a successful war.$B$BI am collecting runecloth bandages to distribute to the soldiers, but I won't be successful without assistance, hopefully yours. Is this something that you can aid me with, $c?$B",logDesc="Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21513,qty=1}}} end
if not DB[8610] then DB[8610]={id=8610,zoneId=-365,name="The Horde Needs More Runecloth Bandages!",level=60,minLevel=1,giver="Stoneguard Clayhoof",giverType="NPC",giverId=15532,ender="Stoneguard Clayhoof",enderType="NPC",enderId=15532,wowhead="https://www.wowhead.com/wotlk/quest=8610",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=10},{id=21513,qty=1}}} end
if not DB[8611] then DB[8611]={id=8611,zoneId=-365,name="The Horde Needs Lean Wolf Steaks!",level=60,minLevel=1,giver="Bloodguard Rawtar",giverType="NPC",giverId=15533,ender="Bloodguard Rawtar",enderType="NPC",enderId=15533,wowhead="https://www.wowhead.com/wotlk/quest=8611",image="assets/images/quests/placeholder.png",desc="I'm not standing here just to get a nice tan, $c. There are war preparations to be made. If we're going to crush those bugs at Ahn'Qiraj then we need to be ready, and that includes food too!$B$BThey have me gathering and salting lean wolf steaks here for the upcoming war. But since I need to stay here to take care of all of this, I need you to go out, kill some wolves and then cook up the meat into lean wolf steaks and bring them back to me here. You got all that?",logDesc="Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21510,qty=1}}} end
if not DB[8612] then DB[8612]={id=8612,zoneId=-365,name="The Horde Needs More Lean Wolf Steaks!",level=60,minLevel=1,giver="Bloodguard Rawtar",giverType="NPC",giverId=15533,ender="Bloodguard Rawtar",enderType="NPC",enderId=15533,wowhead="https://www.wowhead.com/wotlk/quest=8612",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=1},{id=21510,qty=1}}} end
if not DB[8613] then DB[8613]={id=8613,zoneId=-365,name="The Horde Needs Spotted Yellowtail!",level=60,minLevel=1,giver="Fisherman Lin'do",giverType="NPC",giverId=15534,ender="Fisherman Lin'do",enderType="NPC",enderId=15534,wowhead="https://www.wowhead.com/wotlk/quest=8613",image="assets/images/quests/placeholder.png",desc="It be a nice day for fishin', don't'cha think mon? Good thing, cuz I be needin' a lot of fish it lookin' like. The Horde, they askin' me to be in charge of collectin' a ton of the spotted yellowtail for them. They say they needin' it for the war they getting' ready for at Ahn'Qiraj. I say to them I do the best I can. So I be needin' to get some help. You gonna be helpin' me, $c?",logDesc="Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21512,qty=1}}} end
if not DB[8614] then DB[8614]={id=8614,zoneId=-365,name="The Horde Needs More Spotted Yellowtail!",level=60,minLevel=1,giver="Fisherman Lin'do",giverType="NPC",giverId=15534,ender="Fisherman Lin'do",enderType="NPC",enderId=15534,wowhead="https://www.wowhead.com/wotlk/quest=8614",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=7},{id=21512,qty=1}}} end
if not DB[8615] then DB[8615]={id=8615,zoneId=-365,name="The Horde Needs Baked Salmon!",level=60,minLevel=1,giver="Chief Sharpclaw",giverType="NPC",giverId=15535,ender="Chief Sharpclaw",enderType="NPC",enderId=15535,wowhead="https://www.wowhead.com/wotlk/quest=8615",image="assets/images/quests/placeholder.png",desc="The Ahn'Qiraj war effort is an immense undertaking, $c. All of the materials being gathered here, whether it is metal for weapons, or food to eat, are all as important as the other. For, if you haven't eaten in days you will not have the strength to lift your axe when it matters.$B$BThus, we gather what food we can. I am collecting baked salmon, a dish that was chosen both for its sustenance and its ability to keep well. Can you aid me with this task, $c?",logDesc="Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.",rewards={{id=21438,qty=10},{id=21513,qty=1}}} end
if not DB[8616] then DB[8616]={id=8616,zoneId=-365,name="The Horde Needs More Baked Salmon!",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=8616",image="assets/images/quests/placeholder.png",rewards={{id=21438,qty=10},{id=21513,qty=1}}} end
if not DB[8617] then DB[8617]={id=8617,zoneId=-365,name="The Horde Needs Singed Corestones!",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=8617",image="assets/images/quests/placeholder.png",desc="The time has come for you to contribute to the Ahn'Qiraj war effort, $c. Gone are the halcyon days of whiling away your time in leisure. Now it is time to serve me and the Horde, and I assure you that I am not as forgiving as the Warchief.$B$BYou will gather your forces, a guild if you have one, and invade the Molten Core. Inside you will find that the denizens of the place have singed corestones. Bring these back to me in large quantities.",logDesc="Bring 50 singed corestones to General Zog in Durotar."} end
if not DB[8618] then DB[8618]={id=8618,zoneId=-365,name="The Horde Needs More Singed Corestones!",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=8618",image="assets/images/quests/placeholder.png"} end
if not DB[8619] then DB[8619]={id=8619,zoneId=-366,name="Morndeep the Elder",level=-1,minLevel=1,giver="Elder Morndeep",giverType="NPC",giverId=15549,ender="Elder Morndeep",enderType="NPC",enderId=15549,poiX=593,poiY=-190,wowhead="https://www.wowhead.com/wotlk/quest=8619",image="assets/images/quests/placeholder.png",rewards={{id=21100,qty=1}}} end
if not DB[8620] then DB[8620]={id=8620,zoneId=440,name="The Only Prescription",level=60,minLevel=60,giver="Narain Soothfancy",giverType="NPC",giverId=11811,ender="Narain Soothfancy",enderType="NPC",enderId=11811,poiX=-6730,poiY=-4720,wowhead="https://www.wowhead.com/wotlk/quest=8620",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book! How are you going to save the world now, hero?$B$BThe note I received stated that the only known copy of \"Draconic for Dummies: Volume II\" was ripped into 8 parts and scattered to the wind! If you somehow manage to find those missing chapters, use this magical binding to put them back together and return to me.",logDesc="Recover the 8 lost chapters of Draconic for Dummies and combine them with the Magical Book Binding and return the completed book of Draconic for Dummies: Volume II to Narain Soothfancy in Tanaris.",rewards={{id=21517,qty=1}}} end
if not DB[8621] then DB[8621]={id=8621,zoneId=3428,name="Stormcaller's Footguards",level=60,minLevel=60,giver="Kandrostrasz",giverType="NPC",giverId=15503,ender="Kandrostrasz",enderType="NPC",enderId=15503,poiX=-8500,poiY=1937,wowhead="https://www.wowhead.com/wotlk/quest=8621",image="assets/images/quests/placeholder.png",desc="Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.$B$BBring me the qiraji bindings of dominance and other minor components and I'll create a set of powerful boots for you.$B$BYou will find them useful in the fight against the enemy.",logDesc="Bring the Qiraji Bindings of Dominance, 2 Idols of the Sage, 5 Bronze Scarabs and 5 Clay Scarabs to Kandrostrasz in Ahn'Qiraj.  This quest also requires Neutral faction with the Brood of Nozdormu.",rewards={{id=21373,qty=1}}} end
if not DB[8622] then DB[8622]={id=8622,zoneId=3428,name="Stormcaller's Hauberk",level=60,minLevel=60,giver="Vethsera",giverType="NPC",giverId=15504,ender="Vethsera",enderType="NPC",enderId=15504,poiX=-8500,poiY=1934,wowhead="https://www.wowhead.com/wotlk/quest=8622",image="assets/images/quests/placeholder.png",desc="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.$B$BWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.$B$BDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!",logDesc="Bring the Carapace of the Old God, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn'Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21374,qty=1}}} end
if not DB[8623] then DB[8623]={id=8623,zoneId=3428,name="Stormcaller's Diadem",level=60,minLevel=60,giver="Andorgos",giverType="NPC",giverId=15502,ender="Andorgos",enderType="NPC",enderId=15502,poiX=-8496,poiY=1933,wowhead="https://www.wowhead.com/wotlk/quest=8623",image="assets/images/quests/placeholder.png",desc="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.$B$BIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.$B$BBring me the components I require, $N.  I will give you a headpiece of unmatched power.",logDesc="Bring Vek'lor's Diadem, 2 Idols of Rebirth, 5 Stone Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21372,qty=1}}} end
if not DB[8624] then DB[8624]={id=8624,zoneId=3428,name="Stormcaller's Leggings",level=60,minLevel=60,giver="Kandrostrasz",giverType="NPC",giverId=15503,ender="Kandrostrasz",enderType="NPC",enderId=15503,poiX=-8500,poiY=1937,wowhead="https://www.wowhead.com/wotlk/quest=8624",image="assets/images/quests/placeholder.png",desc="You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.$B$BThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.$B$BHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.$B$BBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.",logDesc="Bring the Skin of the Great Sandworm, 2 Idols of Strife, 5 Bronze Scarabs and 5 Ivory Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21375,qty=1}}} end
if not DB[8625] then DB[8625]={id=8625,zoneId=3428,name="Enigma Shoulderpads",level=60,minLevel=60,giver="Andorgos",giverType="NPC",giverId=15502,ender="Andorgos",enderType="NPC",enderId=15502,poiX=-8496,poiY=1933,wowhead="https://www.wowhead.com/wotlk/quest=8625",image="assets/images/quests/placeholder.png",desc="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.$B$BBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!",logDesc="Bring the Qiraji Bindings of Dominance, 2 Idols of Death, 5 Stone Scarabs and 5 Bronze Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.",rewards={{id=21345,qty=1}}} end
