if not DB[8728] then DB[8728]={id=8728,zoneId=440,name="The Good News and The Bad News",level=60,minLevel=60,giver="Narain Soothfancy",giverType="NPC",giverId=11811,ender="Narain Soothfancy",enderType="NPC",enderId=11811,rewardNextId=8729,poiX=-6730,poiY=-4720,wowhead="https://www.wowhead.com/wotlk/quest=8728",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Well that took a little longer than expected. Now let me see what this ledger says.$B$B<Narain silently reads the ledger, periodically mumbling under his breath.>$B$B The good news is that I am 99% certain that I am capable of creating an arcanite buoy that will function to your specifications. This is, of course, wholly dependant on the bad news.$B$BThe bad news is that I'm going to need a lot of arcanite, elementium ore, and rare gemstones.$B$BBring me what I need and I will craft the buoy.",logDesc="Narain Soothfancy in Tanaris wants you to bring him 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds, and 10 Blue Sapphires."} end
if not DB[8729] then DB[8729]={id=8729,zoneId=16,name="The Wrath of Neptulon",level=60,minLevel=60,giver="Narain Soothfancy",giverType="NPC",giverId=11811,ender="3",enderType="NPC",enderId=15192,poiX=-6730,poiY=-4720,wowhead="https://www.wowhead.com/wotlk/quest=8729",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit.$B$BAccording to my superior psycho-psionic clairvoyance, you'll find that the best spot to cast this buoy is off the coast of Azshara, in the Bay of Storms.$B$BLook for a swirling maelstrom, most likely cluttered with wreckage.$B$BBy the by, I hope you have friends.$B$BNow if you somehow miraculously succeed, take the scepter shard to Anachronos.",logDesc="Use the Arcanite Buoy at the Swirling Maelstrom at the Bay of Storms in Azshara.",choiceRewards={{id=21526,qty=1},{id=21527,qty=1}}} end
if not DB[8730] then DB[8730]={id=8730,zoneId=2677,name="Nefarius's Corruption",level=60,minLevel=60,giver="3",giverType="NPC",giverId=13020,ender="3",enderType="NPC",enderId=15192,poiX=-7484,poiY=-1016,wowhead="https://www.wowhead.com/wotlk/quest=8730",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it... But what would tragedy be without cruelty?$B$B<Vaelastrasz coughs weakly.>$B$BNe... Nefarius now holds the scepter shard.$B$BTime is of the essence. Nefarius plans to destroy the shard. You must hurry!",logDesc="Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.",choiceRewards={{id=21530,qty=1},{id=21529,qty=1}}} end
if not DB[8731] then DB[8731]={id=8731,zoneId=1377,name="Field Duty",level=60,minLevel=60,giver="Windcaller Kaldon",giverType="NPC",giverId=15540,ender="Windcaller Kaldon",enderType="NPC",enderId=15540,poiX=-6803,poiY=796,wowhead="https://www.wowhead.com/wotlk/quest=8731",image="assets/images/quests/placeholder.png",desc="Greetings, $N.  Before I assign you to more involved tasks in the war, you'll need to do your share of field duty.  $B$BYou will find Captain Skullsplit's Orgrimmar Legion outside Hive'Regal.$B$BReport to him and come back to me with proof of your field service.  I shall have a more advanced assignment ready for you.$B$BOh, please do your best to stay away from the Ironforge Brigade.  Tensions are high among our Alliance and Horde volunteers.",logDesc="Report to Krug Skullsplit at the Orgrimmar Legion post in front of Hive'Regal.  Prepare your Unsigned Field Duty Papers, obtain Signed Field Duty Papers and bring them to Windcaller Kaldon in Cenarion Hold.$B$BNote: Healing or casting beneficial spells on a member of the Orgrimmar Legion will flag you for PvP.",choiceRewards={{id=20808,qty=1},{id=21266,qty=1},{id=20809,qty=1}}} end
if not DB[8732] then DB[8732]={id=8732,zoneId=1377,name="Field Duty Papers",level=60,minLevel=60,giver="Krug Skullsplit",giverType="NPC",giverId=15612,ender="Krug Skullsplit",enderType="NPC",enderId=15612,poiX=-7548,poiY=719,wowhead="https://www.wowhead.com/wotlk/quest=8732",image="assets/images/quests/placeholder.png",rewards={{id=20810,qty=1}}} end
if not DB[8733] then DB[8733]={id=8733,zoneId=1417,name="Eranikus, Tyrant of the Dream",level=60,minLevel=60,giver="Malfurion Stormrage",giverType="NPC",giverId=15362,ender="Forest Wisp",enderType="NPC",enderId=15624,rewardNextId=8734,wowhead="https://www.wowhead.com/wotlk/quest=8733",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This is a journey of redemption, hero. Would it be that I was slain today, I would have died for a just and righteous cause. You must recover the green scepter shard. You must cleanse Eranikus of the taint placed upon him by the Old Gods.$B$BTravel to Darnassus. Just outside the city walls you will find one of my agents. This agent will set things in motion for us and inform Tyrande of our plans without alerting Staghelm.$B$B<Malfurion sighs.>$B$BA fall from grace a thousand years in the making...",logDesc="Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus.$B"} end
if not DB[8734] then DB[8734]={id=8734,zoneId=141,name="Tyrande and Remulos",level=60,minLevel=60,giver="Forest Wisp",giverType="NPC",giverId=15624,ender="Keeper Remulos",enderType="NPC",enderId=11832,rewardNextId=8735,poiX=10205,poiY=1903,wowhead="https://www.wowhead.com/wotlk/quest=8734",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Tyrande will be notifed, mortal. Shan'do Stormrage has prepared me for this contingency.$B$BNow you must venture to the Moonglade and speak with Remulos. He will have further instruction as to the summoning of Eranikus.$B$BWe all wish you great luck.",logDesc="Travel to the Moonglade and speak to Keeper Remulos. "} end
if not DB[8735] then DB[8735]={id=8735,zoneId=493,name="The Nightmare's Corruption",level=60,minLevel=60,giver="Keeper Remulos",giverType="NPC",giverId=11832,ender="Keeper Remulos",enderType="NPC",enderId=11832,rewardNextId=8736,poiX=7848,poiY=-2216,wowhead="https://www.wowhead.com/wotlk/quest=8735",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You must travel to the four dream portals of Azeroth. From each you must draw a fragment of the Nightmare's corruption. The dragonkin that inhabit these areas will hold such fragments. Return to me when you have gathered these fragments.",logDesc="Travel to the four Emerald Dream portals in Azeroth and collect a Fragment of the Nightmare's Corruption from each. Return to Keeper Remulos in the Moonglade when you have completed this task.$B"} end
if not DB[8736] then DB[8736]={id=8736,zoneId=493,name="The Nightmare Manifests",level=60,minLevel=60,giver="Keeper Remulos",giverType="NPC",giverId=11832,ender="Keeper Remulos",enderType="NPC",enderId=11832,rewardNextId=8741,poiX=7848,poiY=-2216,wowhead="https://www.wowhead.com/wotlk/quest=8736",image="assets/images/quests/placeholder.png",xpDiff=7,desc="We must use restraint against Eranikus. We are to redeem him not destroy him.$B$BTyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction.$B$BBe on guard! You and your allies are our only hope.$B",logDesc="Defend Nighthaven from Eranikus. Do not let Keeper Remulos perish. Do not slay Eranikus. Defend yourself. Await Tyrande.$B",choiceRewards={{id=21531,qty=1},{id=21532,qty=1}}} end
if not DB[8737] then DB[8737]={id=8737,zoneId=1377,name="Azure Templar",level=60,minLevel=60,ender="Bor Wildmane",enderType="NPC",enderId=15306,wowhead="https://www.wowhead.com/wotlk/quest=8737",image="assets/images/quests/placeholder.png",desc="The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.$B$BFind a way to summon and destroy an Azure Templar and report to Bor Wildmane.",logDesc="Summon and slay an Azure Templar and report back to Bor Wildmane in Cenarion Hold.  You must also bring Tactical Task Briefing I in order to complete this quest.",rewards={{id=20801,qty=1},{id=21133,qty=1}}} end
if not DB[8738] then DB[8738]={id=8738,zoneId=1377,name="Hive'Regal Scout Report",level=60,minLevel=60,ender="Windcaller Proudhorn",enderType="NPC",enderId=15191,wowhead="https://www.wowhead.com/wotlk/quest=8738",image="assets/images/quests/placeholder.png",desc="We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Landion has been watching the silithid movements at Hive'Regal for several days now.  Find him and obtain a written report.  We need to be able to act on that information as soon as possible, $N.",logDesc="Contact Cenarion Scout Landion inside Hive'Regal and return the Hive'Regal Scout Report to Windcaller Proudhorn at Cenarion Hold.  You must also bring Tactical Task Briefing VII in order to complete this quest.",rewards={{id=20801,qty=1},{id=21133,qty=1}}} end
if not DB[8739] then DB[8739]={id=8739,zoneId=1377,name="Hive'Ashi Scout Report",level=60,minLevel=60,ender="Windcaller Proudhorn",enderType="NPC",enderId=15191,wowhead="https://www.wowhead.com/wotlk/quest=8739",image="assets/images/quests/placeholder.png",desc="We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Jalia has been watching the silithid movements at Hive'Ashi for several days now.  Find her and obtain a written report.  We need to be able to act on that information as soon as possible, $N.",logDesc="Contact Cenarion Scout Jalia inside Hive'Ashi and return the Hive'Ashi Scout Report to Windcaller Proudhorn at Cenarion Hold.  You must also bring Tactical Task Briefing VIII in order to complete this quest.",rewards={{id=20801,qty=1},{id=20809,qty=1}}} end
if not DB[8740] then DB[8740]={id=8740,zoneId=1377,name="Twilight Marauders",level=60,minLevel=60,ender="Windcaller Proudhorn",enderType="NPC",enderId=15191,wowhead="https://www.wowhead.com/wotlk/quest=8740",image="assets/images/quests/placeholder.png",desc="Bands of mounted Twilight's Hammer cultists have been spotted riding outside the reach of our forces in Cenarion Hold, picking off our smaller patrols and caravans.$B$BFind and defeat the twilight marauders along with their leader, a terrible warrior by the name of Morna.  Report to Windcaller Proudhorn after completing the task.",logDesc="Slay Twilight Marauder Morna and 2 Twilight Marauders.  Report to Windcaller Proudhorn when your task is finished.  You must also bring Tactical Task Briefing IX in order to complete this quest.",rewards={{id=20801,qty=1},{id=21133,qty=1}}} end
if not DB[8741] then DB[8741]={id=8741,zoneId=493,name="The Champion Returns",level=60,minLevel=60,giver="Keeper Remulos",giverType="NPC",giverId=11832,ender="3",enderType="NPC",enderId=15192,poiX=7848,poiY=-2216,wowhead="https://www.wowhead.com/wotlk/quest=8741",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The keeper awaits your return, $N. Take the green scepter shard to Anachronos at the Caverns of Time.$B",logDesc="Take the Green Scepter Shard to Anachronos at the Caverns of Time in Tanaris.$B"} end
