if not DB[8778] then DB[8778]={id=8778,zoneId=1377,name="The Ironforge Brigade Needs Explosives!",level=60,minLevel=60,ender="Arcanist Nozzlespring",enderType="NPC",enderId=15444,wowhead="https://www.wowhead.com/wotlk/quest=8778",image="assets/images/quests/placeholder.png",desc="The Ironforge Brigade has put in an unusual request for highly... volatile... components.  Gather them and bring them to Mr. Nozzlespring from the Ironforge Brigade.",logDesc="Bring 6 Oils of Immolation, 5 Goblin Rocket Fuel and 10 Dense Blasting Powder to Arcanist Nozzlespring near Hive'Zora in Silithus.  You must also bring Logistics Task Briefing IV in order to complete this quest.",rewards={{id=20800,qty=1},{id=20805,qty=1}}} end
if not DB[8779] then DB[8779]={id=8779,zoneId=1377,name="Scrying Materials",level=60,minLevel=60,ender="Geologist Larksbane",enderType="NPC",enderId=15183,wowhead="https://www.wowhead.com/wotlk/quest=8779",image="assets/images/quests/placeholder.png",desc="Geologist Larksbane's studies have proven to be of tremendous value to our operations in Silithus.  She has recently requested scrying materials to be used in her research.$B$BPlease gather these materials and deliver them to her directly so that she may continue her research.",logDesc="Bring 1 Large Brilliant Shard, 1 Large Radiant Shard and 1 Huge Emerald to Geologist Larksbane at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing V in order to complete this quest.",rewards={{id=20800,qty=1},{id=20805,qty=1}}} end
if not DB[8780] then DB[8780]={id=8780,zoneId=1377,name="Armor Kits for the Field",level=60,minLevel=60,ender="Janela Stouthammer",enderType="NPC",enderId=15443,wowhead="https://www.wowhead.com/wotlk/quest=8780",image="assets/images/quests/placeholder.png",desc="The Ironforge Brigade's supply of armor kits in the battlefield is running dangerously low.  Obtain a batch and deliver them to Janela Stouthammer at the Ironforge Brigade's outpost outside Hive'Zora.",logDesc="Bring 8 Rugged Armor Kits and 8 Heavy Armor Kits to Janela Stouthammer at the Ironforge Brigade Outpost near Hive'Zora in Silithus.  You must also bring Logistics Task Briefing VII in order to complete this quest.",rewards={{id=20800,qty=1},{id=20805,qty=1}}} end
if not DB[8781] then DB[8781]={id=8781,zoneId=1377,name="Arms for the Field",level=60,minLevel=60,ender="Janela Stouthammer",enderType="NPC",enderId=15443,wowhead="https://www.wowhead.com/wotlk/quest=8781",image="assets/images/quests/placeholder.png",desc="The Ironforge Brigade has been a worthy ally in our fight in Silithus.  Unfortunately, many of their supplies were lost on their way here.  Procure a batch of weapons and deliver them to Janela Stouthammer near Hive'Zora.",logDesc="Bring 2 Moonsteel Broadswords to Janela Stouthammer at the Ironforge Brigade Outpost outside of Hive'Zora.  You must also bring Logistics Task Briefing VI in order to complete this quest.",rewards={{id=20800,qty=1},{id=20805,qty=1}}} end
if not DB[8782] then DB[8782]={id=8782,zoneId=1377,name="Uniform Supplies",level=60,minLevel=60,ender="Windcaller Proudhorn",enderType="NPC",enderId=15191,wowhead="https://www.wowhead.com/wotlk/quest=8782",image="assets/images/quests/placeholder.png",desc="The latest influx of volunteers has caused a shortage of uniforms.  Procure a batch of uniform materials and bring them to Windcaller Proudhorn.",logDesc="Bring 1 Mooncloth, 2 Bolts of Runecloth and 1 Ironweb Spider Silk to Windcaller Proudhorn at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing VIII in order to complete this quest.",rewards={{id=20800,qty=1},{id=21132,qty=1}}} end
if not DB[8783] then DB[8783]={id=8783,zoneId=1377,name="Extraordinary Materials",level=60,minLevel=60,ender="Vargus",enderType="NPC",enderId=15176,wowhead="https://www.wowhead.com/wotlk/quest=8783",image="assets/images/quests/placeholder.png",desc="Vargus, Cenarion Hold's blacksmith, has requested enchanted materials to be used in the crafting of powerful weapons for our forces.  Obtain these and bring them directly to Vargus so that Cenarion Hold's troops may continue to be well equipped.",logDesc="Bring 2 Enchanted Thorium Bars and 2 Enchanted Leather to Vargus at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing IX in order to complete this quest.",rewards={{id=20800,qty=1},{id=21132,qty=1}}} end
if not DB[8784] then DB[8784]={id=8784,zoneId=3428,name="Secrets of the Qiraji",level=60,minLevel=60,ender="Andorgos",enderType="NPC",enderId=15502,wowhead="https://www.wowhead.com/wotlk/quest=8784",image="assets/images/quests/placeholder.png",desc="You have discovered an ancient Qiraji artifact! Perhaps one of the dragons near the entrance of the temple would have a use for this relic.",logDesc="Take the Ancient Qiraji Artifact to the dragons hiding near the entrance of the temple.$B"} end
if not DB[8785] then DB[8785]={id=8785,zoneId=1377,name="The Orgrimmar Legion Needs Mojo!",level=60,minLevel=60,ender="Shadow Priestess Shai",enderType="NPC",enderId=15615,wowhead="https://www.wowhead.com/wotlk/quest=8785",image="assets/images/quests/placeholder.png",desc="The Orgrimmar Legion has put in a request for several unusual ingredients.  Given their current performance in Silithus, we'd like to comply with their request as soon as possible.  Gather the materials and bring them to the troll called Shai.",logDesc="Bring 6 Powerful Mojo, 6 Flasks of Big Mojo and 8 Oils of Immolation to Shadow Priestess Shai near Hive'Regal in Silithus.  You must also bring Logistics Task Briefing IV in order to complete this quest.",rewards={{id=20800,qty=1},{id=21386,qty=1}}} end
if not DB[8786] then DB[8786]={id=8786,zoneId=1377,name="Arms for the Field",level=60,minLevel=60,ender="Merok Longstride",enderType="NPC",enderId=15613,wowhead="https://www.wowhead.com/wotlk/quest=8786",image="assets/images/quests/placeholder.png",desc="The Orgrimmar Legion has put in a request for additional weapons that we haven't been able to provide at the moment.  Obtain the weapons they've requested and bring them to Merok Longstride outside of Hive'Regal.",logDesc="Bring 3 Massive Iron Axes to Merok Longstride at the Orgrimmar Legion camp outside of Hive'Regal.  You must also bring Logistics Task Briefing VI in order to complete this quest.",rewards={{id=20800,qty=1},{id=21386,qty=1}}} end
if not DB[8787] then DB[8787]={id=8787,zoneId=1377,name="Armor Kits for the Field",level=60,minLevel=60,ender="Merok Longstride",enderType="NPC",enderId=15613,wowhead="https://www.wowhead.com/wotlk/quest=8787",image="assets/images/quests/placeholder.png",desc="The brave volunteers of the Orgrimmar Legion have arrived to Silithus to aid us in our cause.  Their supplies of armor kits were somehow lost in the trip.  Obtain a batch of armor kits and deliver them to Merok Longstride at the location of the Orgrimmar Legion camp.",logDesc="Bring 8 Rugged Armor Kits and 8 Heavy Armor Kits to Merok Longstride near Hive'Regal.  You must also bring Logistics Task Briefing VII in order to complete this quest.",rewards={{id=20800,qty=1},{id=21386,qty=1}}} end
if not DB[8788] then DB[8788]={id=8788,zoneId=-22,name="A Gently Shaken Gift",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=8788",image="assets/images/quests/placeholder.png",rewards={{id=21271,qty=1}}} end
if not DB[8789] then DB[8789]={id=8789,zoneId=3428,name="Imperial Qiraji Armaments",level=60,minLevel=60,giver="Arygos",giverType="NPC",giverId=15380,ender="Arygos",enderType="NPC",enderId=15380,poiX=-8663,poiY=2030,wowhead="https://www.wowhead.com/wotlk/quest=8789",image="assets/images/quests/placeholder.png",desc="We have not sat idly by for a millennium, $N.$B$BWe have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world. And we have learned of their own internal treachery.$B$BWeaknesses exist and we know how to use those weaknesses to our advantage.$B$BFind and bring me their ceremonial armaments: Combined with the element created from the volatility of their own God, they will become a force of reckoning.",logDesc="Arygos in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring him Imperial Qiraji Armaments and 3 Elementium Ore.",choiceRewards={{id=21242,qty=1},{id=21272,qty=1},{id=21244,qty=1},{id=21269,qty=1}}} end
if not DB[8790] then DB[8790]={id=8790,zoneId=3428,name="Imperial Qiraji Regalia",level=60,minLevel=60,giver="Merithra of the Dream",giverType="NPC",giverId=15378,ender="Merithra of the Dream",enderType="NPC",enderId=15378,poiX=-8652,poiY=2021,wowhead="https://www.wowhead.com/wotlk/quest=8790",image="assets/images/quests/placeholder.png",desc="Arygos theorizes that the element which is born of conflicts between the Old Gods and their minions is also extremely deadly to them under the right conditions. I speak of Elementium, mortal.$B$BFind and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power.$B",logDesc="Merithra of the Dream in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring her Imperial Qiraji Regalia and 3 Elementium Ore.$B",choiceRewards={{id=21273,qty=1},{id=21275,qty=1},{id=21268,qty=1}}} end
if not DB[8791] then DB[8791]={id=8791,zoneId=3429,name="The Fall of Ossirian",level=60,minLevel=60,ender="Commander Mar'alith",enderType="NPC",enderId=15181,wowhead="https://www.wowhead.com/wotlk/quest=8791",image="assets/images/quests/placeholder.png",xpDiff=7,desc="A terrible menace has been laid to rest. The cruel Ossirian has been vanquished.$B$BThe denizens of Kalimdor would be relieved to know of this victory. Take Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.",logDesc="Deliver the Head of Ossirian the Unscarred to Commander Mar'alith at Cenarion Hold in Silithus.$B",choiceRewards={{id=21504,qty=1},{id=21507,qty=1},{id=21505,qty=1},{id=21506,qty=1}}} end
if not DB[8792] then DB[8792]={id=8792,zoneId=-365,name="The Horde Needs Your Help!",level=60,minLevel=1,giver="Senior Sergeant Taiga",giverType="NPC",giverId=15702,ender="Warlord Gorchuk",enderType="NPC",enderId=15700,wowhead="https://www.wowhead.com/wotlk/quest=8792",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, $N!$B$BYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, $c? Will you help out with the vital preparations?",logDesc="Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits."} end
