if not DB[8856] then DB[8856]={id=8856,zoneId=1377,name="Desert Survival Kits",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=8856",image="assets/images/quests/placeholder.png",xpDiff=1,desc="With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.",logDesc="Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Baked Salmon to Calandrath at the inn in Cenarion Hold in Silithus.",rewards={{id=20800,qty=1},{id=20805,qty=1}}} end
if not DB[8857] then DB[8857]={id=8857,zoneId=1377,name="Secrets of the Colossus - Ashi",level=60,minLevel=51,giver="Colossus Researcher Nestor",giverType="NPC",giverId=15798,ender="Oglethorpe Obnoticus",enderType="NPC",enderId=7406,wowhead="https://www.wowhead.com/wotlk/quest=8857",image="assets/images/quests/placeholder.png",xpDiff=7,money=27000,desc="I'm looking for battle hardened adventurers willing and able to get a fresh husk sample from the fallen Colossus of Ashi to Oglethorpe in Booty Bay. No, no, I wouldn't want you to go anywhere near that thing's corpse. Just take one of my samples and make it snappy. These things are no good to him rotten!",logDesc="Take the Colossus of Ashi's Husk to Oglethorpe Obnoticus in Booty Bay.$B",rewards={{id=21528,qty=1}}} end
if not DB[8858] then DB[8858]={id=8858,zoneId=1377,name="Secrets of the Colossus - Regal",level=60,minLevel=51,giver="Colossus Researcher Eazel",giverType="NPC",giverId=15799,ender="Overseer Oilfist",enderType="NPC",enderId=14625,wowhead="https://www.wowhead.com/wotlk/quest=8858",image="assets/images/quests/placeholder.png",xpDiff=7,money=27000,desc="There ain't nothin' I'd like more than to stuff this bug husk down Oilfist's fat face... Cept, I'm stuck here collectin' samples from that overgrown cockroach. I'll be here 'till the wee mornin' hours given the size o' that thing.$B$BTake this here sample to Oilfist fer me and do it fast, $c. He's payin' BIG!$B$BYar, Thorium Point - it be in the Searin' Gorge.",logDesc="Take the Colossus of Regal's Husk to Overseer Oilfist in Searing Gorge.$B",rewards={{id=21528,qty=1}}} end
if not DB[8859] then DB[8859]={id=8859,zoneId=1377,name="Secrets of the Colossus - Zora",level=60,minLevel=51,giver="Colossus Researcher Sophia",giverType="NPC",giverId=15797,ender="Lord Maxwell Tyrosus",enderType="NPC",enderId=11034,wowhead="https://www.wowhead.com/wotlk/quest=8859",image="assets/images/quests/placeholder.png",xpDiff=7,money=27000,desc="My servants were nearly killed in their efforts to recover this sample. You absolutely must hurry! Lord Maxwell Tyrosus eagerly awaits a fresh husk sample. He believes that the secrets of this Colossus could help us in the war against the Scourge!$B$BWhy are you still here!? To Light's Hope! Yes, you will be rewarded handsomely for your efforts...$B",logDesc="Take the Colossus of Zora's Husk to Lord Maxwell Tyrosus at Light's Hope Chapel in the Eastern Plaguelands.$B",rewards={{id=21528,qty=1}}} end
if not DB[8860] then DB[8860]={id=8860,zoneId=-22,name="New Year Celebrations!",level=-1,minLevel=1,ender="Innkeeper Allison",enderType="NPC",enderId=6740,wowhead="https://www.wowhead.com/wotlk/quest=8860",image="assets/images/quests/placeholder.png",money=7400,desc="Stormwind is holding a celebration for the new year!  All day long today you can get free booze, and at night they'll put on a firework show!  It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!$B$BWell anyway, Innkeeper Allison in Stormwind needs a supply of Smoky Wood Pasture fare to help feed all the party goers.  Can you do me a favor and deliver it!$B$BThanks, $N!  Innkeeper Allison is in the Gilded Rose, in the Trade District of Stormwind.",logDesc="Bring the Smokywood Supplies to Innkeeper Allison in Stormwind."} end
if not DB[8861] then DB[8861]={id=8861,zoneId=-22,name="New Year Celebrations!",level=-1,minLevel=1,ender="Innkeeper Pala",enderType="NPC",enderId=6746,wowhead="https://www.wowhead.com/wotlk/quest=8861",image="assets/images/quests/placeholder.png",money=7400,desc="Thunder Bluff is holding a celebration for the new year!  All day you'll find free booze there, and at night they'll put on a firework show!$B$BIt should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!$B$BWell anyway, Innkeeper Pala in Thunder Bluff needs a supply of Smoky Wood Pasture fare to help feed all the party goers.  Can you do me a favor and deliver it!$B$BThanks, $N!  Innkeeper Pala is in the inn near the bridge to Hunter's Rise.",logDesc="Bring the Smokywood Supplies to Innkeeper Pala in Thunder Bluff."} end
