if not DB[8867] then DB[8867]={id=8867,zoneId=-366,name="Lunar Fireworks",level=-1,minLevel=1,giver="Lunar Festival Harbinger",giverType="NPC",giverId=15895,ender="Lunar Festival Harbinger",enderType="NPC",enderId=15895,rewardNextId=8883,poiX=5825,poiY=657,wowhead="https://www.wowhead.com/wotlk/quest=8867",image="assets/images/quests/placeholder.png",desc="Every year the druids of Moonglade hold a celebration of our city's great triumph over an ancient evil.$B$BWe celebrate the wisdom of our elders, share in magnificent feasts and of course... shoot fireworks!$B$BFor a small donation you can purchase colorful rockets from our vendor.  Try using some of the launchers around here, $N.",logDesc="Launch 8 Lunar Fireworks and 2 Cluster Fireworks and return to a Lunar Festival Harbinger at any capital city.",rewards={{id=21711,qty=1}}} end
if not DB[8868] then DB[8868]={id=8868,zoneId=-22,name="Elune's Blessing",level=-1,minLevel=40,giver="Valadar Starsong",giverType="NPC",giverId=15864,ender="Valadar Starsong",enderType="NPC",enderId=15864,poiX=7949,poiY=-2620,wowhead="https://www.wowhead.com/wotlk/quest=8868",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The beast Omen was once a hero of this world.  A wolf of great strength and fortune, Omen fought beside the heroes of the War of the Ancients until he succumbed to demonic magics.  Turning against his allies, he raged across Azeroth and carried death and terror in his wake.$B$BFinally defeated here, in Moonglade, Omen now sleeps among the silt of Lake Elune'ara.  But each new year, during the festival, he stirs...$B$BGather cohorts, $N, and summon and defeat the beast Omen.  Earn the blessing of Elune!",logDesc="Summon Omen, defeat him and gain Elune's Blessing.  Return to Valadar Starsong in Nighthaven",rewards={{id=21540,qty=1},{id=21640,qty=1},{id=7912,qty=3}}} end
if not DB[8869] then DB[8869]={id=8869,zoneId=-121,name="Sweet Serenity",level=60,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=8869",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Within the confines of the Scarlet Bastion lies sweet Serenity. The Crimson Hammersmith guards the recipe with his life. Defeat him and bring me his apron. For that, I shall train you to become a hammersmith.$B$BUnderstand this: Once you have chosen the path of the hammersmith, the paths of the swordsmith and axesmith will no longer be available.$B",logDesc="Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith.$B",rewards={{id=12824,qty=1}}} end
if not DB[8870] then DB[8870]={id=8870,zoneId=-366,name="The Lunar Festival",level=-1,minLevel=1,giver="Lunar Festival Emissary",giverType="NPC",giverId=15892,ender="Lunar Festival Harbinger",enderType="NPC",enderId=15895,rewardNextId=8867,poiX=5826,poiY=643,wowhead="https://www.wowhead.com/wotlk/quest=8870",image="assets/images/quests/placeholder.png",desc="It's that time of the year, $N!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.",logDesc="Talk to the Lunar Festival Harbinger in the Mystic Ward of Ironforge.  You can also talk to Lunar Festival Harbingers in other capital cities."} end
if not DB[8871] then DB[8871]={id=8871,zoneId=-366,name="The Lunar Festival",level=-1,minLevel=1,giver="Lunar Festival Emissary",giverType="NPC",giverId=15892,ender="Lunar Festival Harbinger",enderType="NPC",enderId=15895,rewardNextId=8867,poiX=5826,poiY=643,wowhead="https://www.wowhead.com/wotlk/quest=8871",image="assets/images/quests/placeholder.png",desc="It's that time of the year, $N!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.",logDesc="Talk to the Lunar Festival Harbinger in the Park District in Stormwind.  You can also talk to Lunar Festival Harbingers in other capital cities."} end
if not DB[8872] then DB[8872]={id=8872,zoneId=-366,name="The Lunar Festival",level=-1,minLevel=1,giver="Lunar Festival Emissary",giverType="NPC",giverId=15892,ender="Lunar Festival Harbinger",enderType="NPC",enderId=15895,rewardNextId=8867,poiX=5826,poiY=643,wowhead="https://www.wowhead.com/wotlk/quest=8872",image="assets/images/quests/placeholder.png",desc="It's that time of the year, $N!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.",logDesc="Talk to the Lunar Festival Harbinger at the Cenarion Enclave in Darnassus.  You can also talk to Lunar Festival Harbingers in other capital cities."} end
if not DB[8873] then DB[8873]={id=8873,zoneId=-366,name="The Lunar Festival",level=-1,minLevel=1,giver="Lunar Festival Herald",giverType="NPC",giverId=15891,ender="Lunar Festival Harbinger",enderType="NPC",enderId=15895,rewardNextId=8867,poiX=1614,poiY=-4396,wowhead="https://www.wowhead.com/wotlk/quest=8873",image="assets/images/quests/placeholder.png",desc="It's that time of the year, $N!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.",logDesc="Talk to the Lunar Festival Harbinger in the Valley of Wisdom in Orgrimmar.  You can also talk to Lunar Festival Harbingers in other capital cities."} end
