if not DB[8913] then DB[8913]={id=8913,zoneId=1637,name="An Earnest Proposition",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Mokvar",enderType="NPC",enderId=16012,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=8913",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hail, $c!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.$B$BPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.$B$BI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.",logDesc="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Wildheart Bracers to Mokvar in Orgrimmar.",rewards={{id=22108,qty=1}}} end
