if not DB[8920] then DB[8920]={id=8920,zoneId=1637,name="An Earnest Proposition",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Mokvar",enderType="NPC",enderId=16012,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=8920",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hail, $c!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.$B$BPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.$B$BI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.",logDesc="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Bracers of Valor to Mokvar in Orgrimmar.$B",rewards={{id=21996,qty=1}}} end
if not DB[8921] then DB[8921]={id=8921,zoneId=440,name="The Ectoplasmic Distiller",level=60,minLevel=58,giver="Mux Manascrambler",giverType="NPC",giverId=16014,ender="Mux Manascrambler",enderType="NPC",enderId=16014,rewardNextId=8924,poiX=-7127,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=8921",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Ah, you're in need of my latest project... the extra-dimensional ghost revealer!  Unfortunately I've run out of funds and manpower.$B$BYou're willing to help?  Excellent!  Our first task is to build a device to harvest the very fabric of death!  Building an ectoplasmic distiller won't be an easy task, $N.$B$BI'll need you to bring me an arcanite converter, some greater eternal essences and stonescale oil. I'll also need some volcanic ash from the lava pools in the Burning Steppes to build a filter.",logDesc="Return to Mux Manascrambler in Gadgetzan with 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash and 40 gold.",rewards={{id=22320,qty=1}}} end
if not DB[8922] then DB[8922]={id=8922,zoneId=440,name="A Supernatural Device",level=60,minLevel=58,giver="Deliana",giverType="NPC",giverId=16013,ender="Mux Manascrambler",enderType="NPC",enderId=16014,rewardNextId=8921,poiX=-4847,poiY=-1058,wowhead="https://www.wowhead.com/wotlk/quest=8922",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I must find a way to speak with Anthion Harmon... or more specifically, his ghost!$B$BI know of an engineer with a queer interest in the supernatural.  He claims he can build a machine that allows him to speak with the dead!$B$BThe blood you collected was intended for him; travel to Gadgetzan and bring it to him as payment for his services! ",logDesc="Bring the Sealed Blood Container to Mux Manascrambler inside Gadgetzan in Tanaris."} end
if not DB[8923] then DB[8923]={id=8923,zoneId=440,name="A Supernatural Device",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Mux Manascrambler",enderType="NPC",enderId=16014,rewardNextId=8921,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=8923",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You must be quite brave to have stuck around after that.  That or I've piqued your interest with the piece of armor I gave you.  There is more from where that came from, if you're still interested in aiding me.$B$BThe venom samples you collected are for an acquaintance of mine, Mux Manascrambler, an engineer with an interest in the supernatural.  His latest project consists of a device that allows you to communicate with the dead!  My last hope is to contact Anthion and find out more about my situation.",logDesc="Take the Sealed Venom Container to Mux Manascrambler in Gadgetzan."} end
if not DB[8924] then DB[8924]={id=8924,zoneId=440,name="Hunting for Ectoplasm",level=60,minLevel=58,giver="Mux Manascrambler",giverType="NPC",giverId=16014,ender="Mux Manascrambler",enderType="NPC",enderId=16014,rewardNextId=8925,poiX=-7127,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=8924",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="A fine piece of engineering, if I do say so myself!  You will need to travel a bit, I'm afraid, in order to find the incorporeal undead we require.$B$BYou see, different climates lend different consistencies to the spectral fabric of the dead.  The tortured night elves of Silithus, the spirits of the highborne from Winterspring and the ghosts and banshees of the Eastern Plaguelands should give us the different types of ectoplasm we need.  Be sure to place the distiller nearby before you harvest them!",logDesc="Use the Ectoplasmic Distiller near incorporeal undead to collect 12 Scorched Ectoplasms in Silithus, 12 Frozen Ectoplasms in Winterspring and 12 Stable Ectoplasms in the Eastern Plaguelands.  Bring them along with the Ectoplasmic Distiller back to Mux Manascrambler in Gadgetzan."} end
if not DB[8925] then DB[8925]={id=8925,zoneId=440,name="A Portable Power Source",level=60,minLevel=58,giver="Mux Manascrambler",giverType="NPC",giverId=16014,ender="Mux Manascrambler",enderType="NPC",enderId=16014,rewardNextId=8928,poiX=-7127,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=8925",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="Next we shall need to find a stable and portable source of energy to keep the ectoplasm active.  I've heard rumors of a mighty elemental called Magma Lord Bokk, whose heart is a powerful magma core - an endless supply of heat!$B$BIt's said he can be found in the Burning Steppes, south of Blackrock Mountain.  Bring the magma core to me and we shall have enough juice to power the extra-dimensional ghost revealer!",logDesc="Find Magma Lord Bokk in the Burning Steppes, obtain his Magma Core and bring it to Mux Manascrambler in Gadgetzan."} end
if not DB[8926] then DB[8926]={id=8926,zoneId=1537,name="Just Compensation",level=60,minLevel=58,giver="Deliana",giverType="NPC",giverId=16013,ender="Deliana",enderType="NPC",enderId=16013,rewardNextId=8929,poiX=-4847,poiY=-1058,wowhead="https://www.wowhead.com/wotlk/quest=8926",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me the belt and set of gloves that you wish to upgrade.  I promise the ones I give you in return will be far superior.",logDesc="Bring a Wildheart Belt and a set of Wildheart Gloves Deliana in Ironforge.",rewards={{id=22106,qty=1},{id=22110,qty=1}}} end
if not DB[8927] then DB[8927]={id=8927,zoneId=1637,name="Just Compensation",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Mokvar",enderType="NPC",enderId=16012,rewardNextId=8930,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=8927",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You've proven to be a very reliable individual, $N.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.$B$BFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.",logDesc="Bring a Wildheart Belt and a set of Wildheart Gloves to Mokvar in Orgrimmar.",rewards={{id=22106,qty=1},{id=22110,qty=1}}} end
if not DB[8928] then DB[8928]={id=8928,zoneId=440,name="A Shifty Merchant",level=60,minLevel=58,giver="Mux Manascrambler",giverType="NPC",giverId=16014,ender="Mux Manascrambler",enderType="NPC",enderId=16014,poiX=-7127,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=8928",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The core will provide us with enough juice to power our device; now we just have to build a rod that can channel that energy without melting.$B$BI met an imp in Winterspring that sold all manner of exotic goods.  He had an elemental rod that would do perfectly.  I'm kicking myself in the head right now for not having bought it.$B$BHe lives inside a cave in the entrance to Darkwhisper Gorge.  Sneak in there and try to find him.$B$BMake sure he only charges you forty gold; that's the price he quoted me!",logDesc="Search for an imp inside a cave at the entrance of Darkwhisper Gorge in southern Winterspring, purchase a Fel Elemental Rod and return to Mux Manascrambler in Gadgetzan."} end
if not DB[8929] then DB[8929]={id=8929,zoneId=139,name="In Search of Anthion",level=60,minLevel=58,giver="Deliana",giverType="NPC",giverId=16013,ender="Anthion Harmon",enderType="NPC",enderId=16016,rewardNextId=8945,poiX=-4847,poiY=-1058,wowhead="https://www.wowhead.com/wotlk/quest=8929",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Well, nothing left for us to do but try out the goblin's invention.  Word has it that Anthion was mowed down by the undead legions of Stratholme as he tried to enter its gates.$B$BTry using the device there and find out whatever Anthion knew.",logDesc="Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon."} end
if not DB[8930] then DB[8930]={id=8930,zoneId=139,name="In Search of Anthion",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Anthion Harmon",enderType="NPC",enderId=16016,rewardNextId=8945,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=8930",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Very well, $N.  All that remains is to put the goblin's invention to the test.  Word has it that Anthion was slain by the undead legions of Stratholme as he tried to enter its gates.$B$BTry using the device there and see if, indeed, you can speak with the dead!",logDesc="Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon."} end
if not DB[8931] then DB[8931]={id=8931,zoneId=1537,name="Just Compensation",level=60,minLevel=58,giver="Deliana",giverType="NPC",giverId=16013,ender="Deliana",enderType="NPC",enderId=16013,rewardNextId=8929,poiX=-4847,poiY=-1058,wowhead="https://www.wowhead.com/wotlk/quest=8931",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me an ordinary belt and a set of gloves that you wish to upgrade.",logDesc="Bring a Beaststalker's Belt and a set of Beaststalker's Gloves to Deliana in Ironforge.",rewards={{id=22010,qty=1},{id=22015,qty=1}}} end
