if not DB[8938] then DB[8938]={id=8938,zoneId=1637,name="Just Compensation",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Mokvar",enderType="NPC",enderId=16012,rewardNextId=8930,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=8938",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You've proven to be a very reliable individual, $N.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.$B$BFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.",logDesc="Bring a Beaststalker's Belt and a set of Beaststalker's Gloves to Mokvar in Orgrimmar.",rewards={{id=22010,qty=1},{id=22015,qty=1}}} end
