if not DB[8945] then DB[8945]={id=8945,zoneId=2017,name="Dead Man's Plea",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Ysida Harmon",enderType="NPC",enderId=16031,rewardNextId=8946,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=8945",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I'll provide you the information you ask for, $N.  But more pressing matters are at hand.$B$BMy beloved wife has been taken prisoner by Rivendare's undead scum.$B$BI strongly objected to her joining the Argent Dawn's foolish crusade, yet that's not of importance anymore.  You must finish what I attempted to do, you must rescue Ysida from the clutches of the Baron!",logDesc="Go into Stratholme and rescue Ysida Harmon from Baron Rivendare.",rewards={{id=22137,qty=1}}} end
if not DB[8946] then DB[8946]={id=8946,zoneId=139,name="Proof of Life",level=60,minLevel=58,giver="Ysida Harmon",giverType="NPC",giverId=16031,ender="Anthion Harmon",enderType="NPC",enderId=16016,rewardNextId=8947,poiX=4045,poiY=-3334,wowhead="https://www.wowhead.com/wotlk/quest=8946",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is the cruelest of fates that my beloved has perished while trying to rescue me.  Yet, you claim to possess the ability to converse with him.$B$BBring him this locket as proof that I am well.  He must not linger in this world; my heart would not be able to bear it.$B$BFarewell, $N.  I shall be in your debt always.",logDesc="Bring Ysida's Locket to Anthion Harmon in Eastern Plaguelands."} end
if not DB[8947] then DB[8947]={id=8947,zoneId=139,name="Anthion's Strange Request",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Anthion Harmon",enderType="NPC",enderId=16016,rewardNextId=8948,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=8947",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We didn't realize the importance of Valthalak's medallion, so it was divided along with the rest of the spoils.  The first piece was taken by a dwarf named Theldren.  I tried to retrieve it from him and he beat me within an inch of my life.  You shall have to take the fragment by force.$B$BLast I heard of him, he'd become a gladiator for the Dark Iron dwarves.  Getting him to fight you is going to present a bit of a challenge, though.$B$BGather the following materials for me.  You're going to need them.",logDesc="Bring 3 Dark Iron Bars, 20 Enchanted Leather, 3 Mooncloth and 4 Cured Rugged Hides to Anthion Harmon in the Eastern Plaguelands."} end
if not DB[8948] then DB[8948]={id=8948,zoneId=2557,name="Anthion's Old Friend",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Falrin Treeshaper",enderType="NPC",enderId=16032,rewardNextId=8949,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=8948",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Theldren is not one to willingly participate in a fair fight.  I've shaped this banner to display his family colors.$B$BWith some additional sorcery, this banner shall provoke him in a way he won't be able to resist.$B$BAn old acquaintance of mine named Falrin knows the exact procedure required.  He has a particular way of... aggravating people.  You shall find him at the library in Dire Maul.",logDesc="Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul."} end
if not DB[8949] then DB[8949]={id=8949,zoneId=2557,name="Falrin's Vendetta",level=60,minLevel=58,giver="Falrin Treeshaper",giverType="NPC",giverId=16032,ender="Falrin Treeshaper",enderType="NPC",enderId=16032,rewardNextId=8950,poiX=117,poiY=458,wowhead="https://www.wowhead.com/wotlk/quest=8949",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Yes, it is true that I am familiar with this enchantment you require, $c.  Yet I'm not one to give out favors freely, even if you were sent here by an old friend.$B$BI hold nothing but hatred and contempt for our brutish ogre neighbors.  And not only them, I hate the followers of Omokk just as much as I hate those that follow King Gordok.$B$BI want you to kill them.  Kill lots of them!  Bring me the beads they carry around their neck as proof of your work.  Do this and we shall talk about your request.",logDesc="Collect 25 Ogre Warbeads from Ogres inside Dire Maul or Blackrock Spire and return to Falrin Treeshaper inside the Athenaeum in Dire Maul.",choiceRewards={{id=22150,qty=1},{id=22149,qty=1}}} end
if not DB[8950] then DB[8950]={id=8950,zoneId=2557,name="The Instigator's Enchantment",level=60,minLevel=58,giver="Falrin Treeshaper",giverType="NPC",giverId=16032,ender="Falrin Treeshaper",enderType="NPC",enderId=16032,poiX=117,poiY=458,wowhead="https://www.wowhead.com/wotlk/quest=8950",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I can place the enchantment you require on the banner quite easily, $N.  Unfortunately I don't have the materials I need as it is very rarely that someone asks for this sort of charm.$B$BI will require the essence of one of the Eldreth ghosts that haunt these halls, a handful of Scholomance dark runes and some large brilliant shards.  Bring me these reagents and I shall perform this task for you.",logDesc="Bring the following to Falrin Treeshaper inside Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes and 8 Large Brilliant Shards."} end
if not DB[8951] then DB[8951]={id=8951,zoneId=1537,name="Anthion's Parting Words",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Deliana",enderType="NPC",enderId=16013,rewardNextId=8960,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=8951",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!",logDesc="Return to Deliana in Ironforge with a set of Wildheart Boots, a Wildheart Kilt and Wildheart Spaulders.",rewards={{id=22107,qty=1},{id=22111,qty=1},{id=22112,qty=1}}} end
if not DB[8952] then DB[8952]={id=8952,zoneId=1537,name="Anthion's Parting Words",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Deliana",enderType="NPC",enderId=16013,rewardNextId=8960,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=8952",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!",logDesc="Return to Deliana in Ironforge with a set of Beaststalker's Boots, Beaststalker's Pants and Beaststalker's Mantle.",rewards={{id=22061,qty=1},{id=22017,qty=1},{id=22016,qty=1}}} end
