if not DB[8955] then DB[8955]={id=8955,zoneId=1537,name="Anthion's Parting Words",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Deliana",enderType="NPC",enderId=16013,rewardNextId=8960,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=8955",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!",logDesc="Return to Deliana in Ironforge with a set of Devout Sandals, Devout Skirt and Devout Mantle.",rewards={{id=22084,qty=1},{id=22085,qty=1},{id=22082,qty=1}}} end
