if not DB[8957] then DB[8957]={id=8957,zoneId=1637,name="Anthion's Parting Words",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Mokvar",enderType="NPC",enderId=16012,rewardNextId=9032,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=8957",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!",logDesc="Return to Mokvar in Orgimmar with a set of Boots of Elements, Kilt of Elements and Pauldrons of Elements.",rewards={{id=22096,qty=1},{id=22100,qty=1},{id=22101,qty=1}}} end
if not DB[8958] then DB[8958]={id=8958,zoneId=1537,name="Anthion's Parting Words",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Deliana",enderType="NPC",enderId=16013,rewardNextId=8960,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=8958",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!",logDesc="Return to Deliana in Ironforge with a set of Dreadmist Sandals, Dreadmist Leggings and Dreadmist Mantle.",rewards={{id=22076,qty=1},{id=22072,qty=1},{id=22073,qty=1}}} end
if not DB[8959] then DB[8959]={id=8959,zoneId=1537,name="Anthion's Parting Words",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Deliana",enderType="NPC",enderId=16013,rewardNextId=8960,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=8959",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!",logDesc="Return to Deliana in Ironforge with a set of Boots of Valor, Legplates of Valor and Spaulders of Valor.",rewards={{id=21995,qty=1},{id=22000,qty=1},{id=22001,qty=1}}} end
if not DB[8960] then DB[8960]={id=8960,zoneId=25,name="Bodley's Unfortunate Fate",level=60,minLevel=58,giver="Deliana",giverType="NPC",giverId=16013,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8961,poiX=-4847,poiY=-1058,wowhead="https://www.wowhead.com/wotlk/quest=8960",image="assets/images/quests/placeholder.png",xpDiff=2,desc="So we need to recover the rest of the medallion?  Finding Bodley's going to be a bit of a headache.  He went back to Blackrock Mountain to attempt to re-enter Blackrock Spire and never came back.$B$BI'd suggest taking the goblin's ghost revealing device with you, as I fear the worst might have happened.",logDesc="Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire."} end
if not DB[8961] then DB[8961]={id=8961,zoneId=25,name="Three Kings of Flame",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8961",image="assets/images/quests/placeholder.png",xpDiff=5,desc="In order to summon Lord Valthalak we're first going to need to gather the other two-thirds of the amulet. To do that we need to get a brazier and some special coals to burn in it.$B$BThere are three nobles of fire, Lord Incedius in Blackrock Depths, Pyroguard Emberseer in Blackrock Spire and The Duke of Cynders in Silithus, with what we need. Collect from each a piece of their remains, and then return to me with a Hallowed Brazier, which can be purchased from the Argent Dawn if you are honored by them.",logDesc="Gather the Incendicite of Incendius, the Ember of Emberseer and the Cinder of Cynders, along with a Hallowed Brazier, and return them to Bodley inside Blackrock Mountain."} end
if not DB[8962] then DB[8962]={id=8962,zoneId=25,name="Components of Importance",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8966,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8962",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$C, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.$B$BMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus.",logDesc="Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain."} end
if not DB[8963] then DB[8963]={id=8963,zoneId=25,name="Components of Importance",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8967,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8963",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$C, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.$B$BIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.",logDesc="Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain."} end
if not DB[8964] then DB[8964]={id=8964,zoneId=25,name="Components of Importance",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8968,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8964",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$C, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.$B$BThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.",logDesc="Retrieve a Brilliant Sword of Zealotry and return it to Bodley inside Blackrock Mountain."} end
if not DB[8965] then DB[8965]={id=8965,zoneId=25,name="Components of Importance",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8969,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8965",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$C, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.$B$BAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.",logDesc="Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain."} end
if not DB[8966] then DB[8966]={id=8966,zoneId=1583,name="The Left Piece of Lord Valthalak's Amulet",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8970,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8966",image="assets/images/quests/placeholder.png",xpDiff=6,desc="My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.$B$BLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front of Voone.",logDesc="Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning."} end
if not DB[8967] then DB[8967]={id=8967,zoneId=2557,name="The Left Piece of Lord Valthalak's Amulet",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8970,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8967",image="assets/images/quests/placeholder.png",xpDiff=6,desc="It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.$B$BShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces.",logDesc="Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning."} end
if not DB[8968] then DB[8968]={id=8968,zoneId=2017,name="The Left Piece of Lord Valthalak's Amulet",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8970,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8968",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the left piece of Lord Valthalak's amulet with them. Good riddance, I say, but we need that piece back.$B$BFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.$B$BIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.",logDesc="Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning."} end
if not DB[8969] then DB[8969]={id=8969,zoneId=2057,name="The Left Piece of Lord Valthalak's Amulet",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8970,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8969",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Now we have what we need, so it's time to discuss who it is that you'll be summoning.$B$BKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.$B$BBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.",logDesc="Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning."} end
if not DB[8970] then DB[8970]={id=8970,zoneId=2079,name="I See Alcaz Island In Your Future...",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8970",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As I was saying, $c, in my living years I flirted with becoming a diviner. But, there really wasn't as much profit in it as you might imagine, mostly because it's dangerous and the reagents are rare and expensive. However, I do know enough to be able to pinpoint the final piece of the amulet, and the spirit of my former comrade along with it.$B$BThis is where you come in, $N. I need you to go to Alcaz Island off the coast of Dustwallow Marsh and collect Bloodkelp from the Strashaz naga that live there.",logDesc="Gather 20 Bloodkelp from the Strashaz naga and then return to Bodley inside Blackrock Mountain."} end
