if not DB[8977] then DB[8977]={id=8977,zoneId=1537,name="Return to Deliana",level=60,minLevel=58,giver="Mux Manascrambler",giverType="NPC",giverId=16014,ender="Deliana",enderType="NPC",enderId=16013,poiX=-7127,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=8977",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It's been great working with you, $N.  Here is the finished product.$B$BI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!",logDesc="Bring the Extra-Dimensional Ghost Revealer  to Deliana in Ironforge."} end
if not DB[8978] then DB[8978]={id=8978,zoneId=1637,name="Return to Mokvar",level=60,minLevel=58,giver="Mux Manascrambler",giverType="NPC",giverId=16014,ender="Mokvar",enderType="NPC",enderId=16012,poiX=-7127,poiY=-3839,wowhead="https://www.wowhead.com/wotlk/quest=8978",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It's been great working with you, $N.  Here is the finished product.$B$BI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!",logDesc="Return to Mokvar in Orgrimmar with the Extra-Dimensional Ghost Revealer."} end
if not DB[8979] then DB[8979]={id=8979,zoneId=-22,name="Fenstad's Hunch",level=-1,minLevel=1,rewardNextId=8980,wowhead="https://www.wowhead.com/wotlk/quest=8979",image="assets/images/quests/placeholder.png",desc="I believe I know the cause of this recent behavior. Have you smelled the new fragrance on the wind, over the stink of the canals? The new colognes and perfumes that have come into fashion?$b$bOur thinking has been clouded by some foul alchemy.$b$bThere is only one way to be sure - bring a bottle of cologne and perfume to my friend, Apothecary Zinge. The Royal Apothecary Society will find the truth.$b$b I will reimburse you for their purchase when you return.",logDesc="Bring 1 Cologne Bottle and 1 Perfume Bottle to Apothecary Zinge in the Undercity's Apothecarium."} end
if not DB[8980] then DB[8980]={id=8980,zoneId=-22,name="Zinge's Assessment",level=-1,minLevel=1,ender="Fenstad Argyle",enderType="NPC",enderId=16108,rewardNextId=8982,wowhead="https://www.wowhead.com/wotlk/quest=8980",image="assets/images/quests/placeholder.png",desc="This is unexpected. It looks like Fenstad might be on to something after all. I found traces of substances used in mind control potions.$b$bIt isn't unheard of for perfumes to have some of this, but a few of the ingredients I detected... This is serious alchemy, along the abilities of a member of the Royal Apothecary Society.",logDesc="Return to Fenstad Argyle outside the bank in the Undercity.",rewards={{id=21812,qty=1},{id=22218,qty=1},{id=34258,qty=1}}} end
if not DB[8981] then DB[8981]={id=8981,zoneId=-22,name="Gift Giving",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=8981",image="assets/images/quests/placeholder.png",rewards={{id=21812,qty=1}},choiceRewards={{id=22218,qty=5},{id=22200,qty=5},{id=34258,qty=5}}} end
if not DB[8982] then DB[8982]={id=8982,zoneId=-22,name="Tracing the Source",level=-1,minLevel=1,giver="Fenstad Argyle",giverType="NPC",giverId=16108,ender="Innkeeper Norman",enderType="NPC",enderId=6741,rewardNextId=8983,wowhead="https://www.wowhead.com/wotlk/quest=8982",image="assets/images/quests/placeholder.png",desc="We must find who the supplier is. I noticed Apothecary Katrina with a bottle of the perfume tucked in her pack. She told me that she purchased it from Norman, the innkeeper.",logDesc="Speak with Innkeeper Norman in the Undercity."} end
if not DB[8983] then DB[8983]={id=8983,zoneId=-22,name="Tracing the Source",level=-1,minLevel=1,ender="Mara Rennick",enderType="NPC",enderId=16109,rewardNextId=8984,wowhead="https://www.wowhead.com/wotlk/quest=8983",image="assets/images/quests/placeholder.png",desc="Something's wrong with my product? Well, I've never seen so many people wanting something so badly.$b$bI bought my supply from a merchant named Mara Rennick. She's new in town.$b$bShe mentioned she had some goods she had to deliver to the tailor in the Magic Quarter.",logDesc="Speak with Mara Rennick at the tailor's shop in the Undercity's Magic Quarter."} end
if not DB[8984] then DB[8984]={id=8984,zoneId=-22,name="The Source Revealed",level=-1,minLevel=1,giver="Mara Rennick",giverType="NPC",giverId=16109,ender="Apothecary Staffron Lerent",enderType="NPC",enderId=16107,wowhead="https://www.wowhead.com/wotlk/quest=8984",image="assets/images/quests/placeholder.png",desc="Look, the actions of a rogue apothecary are not my concern. If he's undermining our efforts, then let me be the first to point you in the right direction.$b$bIf he's innocent, then he's got nothing to hide, right?$b$bI purchased the goods from Apothecary Staffron Lerent. He's working in a secluded area past Ravenholdt Manor in the hills over Hillsbrad. To be honest with you, I thought he was a little odd.",logDesc="Find Apothecary Staffron Lerent in the Hillsbrad Foothills past Ravenholdt Manor."} end
if not DB[8985] then DB[8985]={id=8985,zoneId=25,name="More Components of Importance",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8990,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8985",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$C, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.$B$BIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.",logDesc="Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain.",choiceRewards={{id=22192,qty=3},{id=22193,qty=3}}} end
if not DB[8986] then DB[8986]={id=8986,zoneId=25,name="More Components of Importance",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8989,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8986",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$C, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.$B$BMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus.",logDesc="Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.",choiceRewards={{id=22192,qty=3},{id=22193,qty=3}}} end
if not DB[8987] then DB[8987]={id=8987,zoneId=25,name="More Components of Importance",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8991,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8987",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$C, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.$B$BThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.$B",logDesc="Retrieve a Brilliant Sword of Zealotry and return it to Bodley inside Blackrock Mountain.",choiceRewards={{id=22192,qty=3},{id=22193,qty=3}}} end
if not DB[8988] then DB[8988]={id=8988,zoneId=25,name="More Components of Importance",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8992,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8988",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$C, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.$B$BAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.",logDesc="Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain.",choiceRewards={{id=22192,qty=3},{id=22193,qty=3}}} end
if not DB[8989] then DB[8989]={id=8989,zoneId=1583,name="The Right Piece of Lord Valthalak's Amulet",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8994,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8989",image="assets/images/quests/placeholder.png",xpDiff=6,desc="My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.$B$BLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front of Voone.",logDesc="Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning."} end
if not DB[8990] then DB[8990]={id=8990,zoneId=2557,name="The Right Piece of Lord Valthalak's Amulet",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8994,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8990",image="assets/images/quests/placeholder.png",xpDiff=6,desc="It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.$B$BShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces.",logDesc="Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning."} end
if not DB[8991] then DB[8991]={id=8991,zoneId=2017,name="The Right Piece of Lord Valthalak's Amulet",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8994,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8991",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the right piece of Lord Valthalak's amulet with them. Good riddance, I say, but we need that piece back.$B$BFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.$B$BIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.",logDesc="Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning."} end
if not DB[8992] then DB[8992]={id=8992,zoneId=2057,name="The Right Piece of Lord Valthalak's Amulet",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8994,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8992",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Now we have what we need, so it's time to discuss who it is that you'll be summoning next.$B$BKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.$B$BBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.",logDesc="Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning."} end
if not DB[8993] then DB[8993]={id=8993,zoneId=-22,name="Gift Giving",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=8993",image="assets/images/quests/placeholder.png",rewards={{id=21812,qty=1}},choiceRewards={{id=22218,qty=5},{id=22200,qty=5},{id=34258,qty=5}}} end
if not DB[8994] then DB[8994]={id=8994,zoneId=25,name="Final Preparations",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8995,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8994",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We're nearly there, $c. All that is left is to retrieve a few more components so that I can attune the brazier and enable it to beckon forth Lord Valthalak.$B$BTo begin I must ask you to journey forth into Blackrock Spire and slay the orcs therein. They wear bracers that contain trace metals that I will need, so I'll need more than a few to extract the right amount out of them. Then, to complete the imbuing process, you'll need to bring me a Flask of Supreme Power.$B$BGood luck, $N!",logDesc="Gather 40 Blackrock Bracers and acquire a Flask of Supreme Power. Return them to Bodley inside Blackrock Mountain."} end
if not DB[8995] then DB[8995]={id=8995,zoneId=1583,name="Mea Culpa, Lord Valthalak",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Spirit of Lord Valthalak",enderType="NPC",enderId=16073,rewardNextId=8996,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8995",image="assets/images/quests/placeholder.png",xpDiff=7,desc="All is now ready, $N.$B$BWhen alive, Lord Valthalak used to inhabit what is now The Beast's chamber. Go there and use the Brazier of Beckoning to summon forth Lord Valthalak. It will reincorporate him, so he'll have to be killed again. I'd take care of The Beast first, and be sure take enough friends along to survive the upper portion of Blackrock Spire.$B$BOnce you've dispatched Valthalak, use the amulet on his corpse. With his spirit reunified, he'll likely want his amulet back, as well.$B$BGood luck!",logDesc="Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak."} end
if not DB[8996] then DB[8996]={id=8996,zoneId=25,name="Return to Bodley",level=60,minLevel=58,giver="Spirit of Lord Valthalak",giverType="NPC",giverId=16073,ender="Bodley",enderType="NPC",enderId=16033,wowhead="https://www.wowhead.com/wotlk/quest=8996",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I will ignore your impertinence this time, $c, because you have done a noble thing today; returning the rest of my stolen spirit to me. Despite your obviously weak nature, $r, you have shown courage where those that stole from me did not, and probably never could!$B$BReturn to them, before I change my mind and slay you where you stand. Go back and tell them that they are safe... for now.",logDesc="Return to Bodley inside Blackrock Mountain and give him the Brazier of Beckoning.",rewards={{id=22057,qty=1},{id=22344,qty=1}}} end
if not DB[8997] then DB[8997]={id=8997,zoneId=1537,name="Back to the Beginning",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Deliana",enderType="NPC",enderId=16013,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8997",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.$B$BGo, before I start to cry. Go back to Deliana in Ironforge and tell her what's happened.",logDesc="Speak with Deliana at The High Seat in Ironforge."} end
if not DB[8998] then DB[8998]={id=8998,zoneId=1637,name="Back to the Beginning",level=60,minLevel=58,giver="Bodley",giverType="NPC",giverId=16033,ender="Mokvar",enderType="NPC",enderId=16012,poiX=-7535,poiY=-1213,wowhead="https://www.wowhead.com/wotlk/quest=8998",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.$B$BGo, before I start to cry. Go back to Mokvar in Orgrimmar and tell him what's happened.",logDesc="Speak with Mokvar at Grommash Hold in Orgrimmar's Valley of Wisdom."} end
if not DB[8999] then DB[8999]={id=8999,zoneId=1537,name="Saving the Best for Last",level=60,minLevel=58,giver="Deliana",giverType="NPC",giverId=16013,ender="Deliana",enderType="NPC",enderId=16013,poiX=-4847,poiY=-1058,wowhead="https://www.wowhead.com/wotlk/quest=8999",image="assets/images/quests/placeholder.png",xpDiff=2,desc="That's an amazing story, $N! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.$B$BAs to your reward, I believe I have a few things that you'll really enjoy.",logDesc="Give Deliana your Wildheart Cowl and Wildheart Vest.",rewards={{id=22109,qty=1},{id=22113,qty=1}}} end
