if not DB[9007] then DB[9007]={id=9007,zoneId=1637,name="Saving the Best for Last",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Mokvar",enderType="NPC",enderId=16012,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=9007",image="assets/images/quests/placeholder.png",xpDiff=2,desc="A truly amazing story, $N! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past.$B$BAs to your reward, I believe I have a few things that you have definitely earned and will truly enjoy.",logDesc="Give Mokvar your Wildheart Cowl and Wildheart Vest.",rewards={{id=22109,qty=1},{id=22113,qty=1}}} end
