if not DB[9015] then DB[9015]={id=9015,zoneId=1584,name="The Challenge",level=60,minLevel=58,giver="Falrin Treeshaper",giverType="NPC",giverId=16032,ender="Anthion Harmon",enderType="NPC",enderId=16016,poiX=117,poiY=458,wowhead="https://www.wowhead.com/wotlk/quest=9015",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Heed me well, $N.  For the banner to work in the desired way, you will need to step into the Ring of the Law in Blackrock Depths.  Allow yourself to be sentenced by High Justice Grimstone and place the banner firmly on the ground in a sign of defiance.$B$BYour victim will not be able to restrain himself and shall enter the fray filled with a desire to fight you.  Once you obtain that which you seek, go back to Anthion.",logDesc="Travel to the Ring of the Law in Blackrock Depths and place the Banner of Provocation in its center as you are sentenced by High Justice Grimstone.  Slay Theldren and his gladiators and return to Anthion Harmon in the Eastern Plaguelands with the first piece of Lord Valthalak's amulet."} end
if not DB[9016] then DB[9016]={id=9016,zoneId=1637,name="Anthion's Parting Words",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Mokvar",enderType="NPC",enderId=16012,rewardNextId=9032,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=9016",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!",logDesc="Return to Mokvar in Orgimmar with a set of Wildheart Boots, a Wildheart Kilt and Wildheart Spaulders.$B",rewards={{id=22107,qty=1},{id=22111,qty=1},{id=22112,qty=1}}} end
