if not DB[9023] then DB[9023]={id=9023,zoneId=1377,name="The Perfect Poison",level=60,minLevel=60,giver="Dirk Thunderwood",giverType="NPC",giverId=16091,ender="Dirk Thunderwood",enderType="NPC",enderId=16091,poiX=-6868,poiY=722,wowhead="https://www.wowhead.com/wotlk/quest=9023",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My brother and I run the poison operations out of the manor Ravenholdt.$B$BLord Ravenholdt tasked me to track down a new and extremely effective poison compound that can be crafted from the venom sacs of the inhabitants of Zul'Gurub and the Ruins of Ahn'Qiraj.$B$BThere are two particularly venomous beasts residing in those blasted ruins that possess what it is that we might be looking for, $c. Bring me a venom sac from the beasts Kurinnaxx and Venoxis and we would be eternally grateful.",logDesc="Dirk Thunderwood at Cenarion Hold wants you to bring him Venoxis's Venom Sac and Kurinnaxx's Venom Sac.",choiceRewards={{id=22378,qty=1},{id=22379,qty=1},{id=22377,qty=1},{id=22348,qty=1},{id=22347,qty=1},{id=22380,qty=1}}} end
if not DB[9024] then DB[9024]={id=9024,zoneId=-22,name="Aristan's Hunch",level=-1,minLevel=1,rewardNextId=9025,wowhead="https://www.wowhead.com/wotlk/quest=9024",image="assets/images/quests/placeholder.png",desc="I've got it! Have you smelled the new fragrance on the wind? The new colognes and perfumes that have come into fashion? Our guards wouldn't neglect their duties so easily.$b$bThat is, unless their thinking has been clouded by some foul alchemy.$b$bThere is only one way to be sure - bring a bottle of cologne and perfume to Morgan Pestle, and tell him my suspicions. I will reimburse you for their purchase when you return.",logDesc="Bring 1 Cologne Bottle and 1 Perfume Bottle to Morgan Pestle in the Trade District of Stormwind."} end
if not DB[9025] then DB[9025]={id=9025,zoneId=-22,name="Morgan's Discovery",level=-1,minLevel=1,rewardNextId=9026,wowhead="https://www.wowhead.com/wotlk/quest=9025",image="assets/images/quests/placeholder.png",desc="Well, I'll be. It looks like Aristan might be on to something after all. I found traces of substances used in love potions and insidious mind-altering draughts.$b$bIt isn't unheard of for perfumes to have some of them, but a few of the ingredients I detected... Smells funny.",logDesc="Return to Aristan Mottar outside the bank in Stormwind's Trade District.",rewards={{id=21812,qty=1},{id=22218,qty=1},{id=34258,qty=1}}} end
if not DB[9026] then DB[9026]={id=9026,zoneId=-22,name="Tracing the Source",level=-1,minLevel=1,giver="Aristan Mottar",giverType="NPC",giverId=16105,ender="Innkeeper Allison",enderType="NPC",enderId=6740,rewardNextId=9027,wowhead="https://www.wowhead.com/wotlk/quest=9026",image="assets/images/quests/placeholder.png",desc="We've got to find the source. I've seen a lot more people than usual - guards included - going in and out of The Gilded Rose. Talk to Allison. If she's selling them, she can tell you where they came from.",logDesc="Speak with Innkeeper Allison at The Gilded Rose in Stormwind's Trade District."} end
if not DB[9027] then DB[9027]={id=9027,zoneId=-22,name="Tracing the Source",level=-1,minLevel=1,ender="Evert Sorisam",enderType="NPC",enderId=16106,rewardNextId=9028,wowhead="https://www.wowhead.com/wotlk/quest=9027",image="assets/images/quests/placeholder.png",desc="Something funny about the cologne? It's possible. I've never seen so many people after one product like this.$b$bLook, if there's something wrong with it, I want to know, too. I bought my supply from a merchant named Evert Sorisam. He's new in town.$b$bHe mentioned he had some goods he was going to deliver to The Finest Thread.",logDesc="Speak with Evert Sorisam at The Finest Thread along Stormwind's Canals."} end
if not DB[9028] then DB[9028]={id=9028,zoneId=-22,name="The Source Revealed",level=-1,minLevel=1,giver="Evert Sorisam",giverType="NPC",giverId=16106,ender="Apothecary Staffron Lerent",enderType="NPC",enderId=16107,wowhead="https://www.wowhead.com/wotlk/quest=9028",image="assets/images/quests/placeholder.png",desc="What? Treason? No, no. I assure you, my intentions are completely harmless.$b$bIs it so wrong to help those who wish to ease the painful ritual of courtship? Come, that is no crime.$b$bAnd to prove that I mean no harm, I will even tell you my source.$b$bThey were shipped to me by a Staffron Lerent, an apothecary of some sort. I never spoke with him.$b$bOur goblin middle man said that he worked in the foothills over Hillsbrad past that mysterious Ravenholdt Manor. I wish you luck in finding him.",logDesc="Find Apothecary Staffron Lerent in the Hillsbrad Foothills behind Ravenholdt Manor."} end
if not DB[9029] then DB[9029]={id=9029,zoneId=0,name="A Bubbling Cauldron",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9029",image="assets/images/quests/placeholder.png",choiceRewards={{id=22281,qty=1},{id=22282,qty=1},{id=22277,qty=1},{id=22278,qty=1},{id=22280,qty=1},{id=22276,qty=1}}} end
if not DB[9030] then DB[9030]={id=9030,zoneId=2557,name="Anthion's Parting Words",level=60,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=9030",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.$B$BI, for once, shall rest in peace.  I wish you the best of luck, and you shall need it!",logDesc="Speak to Deliana in Ironforge."} end
if not DB[9031] then DB[9031]={id=9031,zoneId=139,name="<TXT>Anthion's Parting Words",level=60,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=9031",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.$B$BI, for once, shall rest in peace.  I wish you the best of luck, and you shall need it!",logDesc="Speak to Mokvar in Orgrimmar."} end
if not DB[9032] then DB[9032]={id=9032,zoneId=25,name="Bodley's Unfortunate Fate",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Bodley",enderType="NPC",enderId=16033,rewardNextId=8961,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=9032",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The medallion contained Valthalak's soul?  It's no surprise it was guarded by such a powerful curse.$B$BLocating Bodley presents a bit of a problem.  Last time I heard of him, he was preparing to venture back into Blackrock Spire.  He was never heard of again.$B$BSeek him out in Blackrock Mountain, though I'm afraid to say he's probably dead by now.  I suggest taking the goblin's device with you, friend.",logDesc="Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire."} end
if not DB[9033] then DB[9033]={id=9033,zoneId=3456,name="Echoes of War",level=60,minLevel=60,giver="Commander Eligor Dawnbringer",giverType="NPC",giverId=16115,ender="Commander Eligor Dawnbringer",enderType="NPC",enderId=16115,poiX=2299,poiY=-5342,wowhead="https://www.wowhead.com/wotlk/quest=9033",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Five years since the last war...$B$BTens of thousands of lives were lost and for what? The threat was never fully extinguished.$B$BAnd so the Lich King stirs once more... His yes-man, Kel'Thuzad, amassing for another attack upon our lands.$B$BWe will not allow it! Prove your dedication. Prove that you are willing to risk life and limb to stop this madness and the combined might of the Dawn and the Crusade will be at your beck and call.$B$BEnter Naxxramas and destroy the Scourge within...",logDesc="Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands wants you to slay 5 Living Monstrosities, 5 Stoneskin Gargoyles, 8 Deathknight Captains and 3 Venom Stalkers."} end
if not DB[9034] then DB[9034]={id=9034,zoneId=3456,name="Dreadnaught Breastplate",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=9034",image="assets/images/quests/placeholder.png",desc="During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.",logDesc="Korfax at Light's Hope Chapel in the Eastern Plaguelands will make a Dreadnaught Breastplate if you bring him the following items: 1 Desecrated Breastplate, 25 Wartorn Plate Scraps, 4 Arcanite Bars and 2 Nexus Crystals.$B",rewards={{id=22416,qty=1}}} end
if not DB[9035] then DB[9035]={id=9035,zoneId=3430,name="Roadside Ambush",level=6,minLevel=4,giver="Apprentice Ralen",giverType="NPC",giverId=15941,ender="Apprentice Meledor",enderType="NPC",enderId=15945,rewardNextId=9062,poiX=9189,poiY=-6713,wowhead="https://www.wowhead.com/wotlk/quest=9035",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You, there!  You must help me, please!$B$BA fellow apprentice and I were attacked by the Wretched!  In their mad hunger for magic, they took everything they could get their hands on: mana crystals, wands, spellbooks... everything!$B$BMeledor gave chase after them; I had to stay behind and look after what they didn't take.  Continue down the road and see if you can lend him a hand.",logDesc="Speak to Apprentice Meledor in Eversong Woods along the road heading south from Silvermoon City."} end
