if not DB[9043] then DB[9043]={id=9043,zoneId=3456,name="Redemption Tunic",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=9043",image="assets/images/quests/placeholder.png",desc="You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.",logDesc="Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make a Redemption Tunic if you bring him the following: 1 Desecrated Tunic, 25 Wartorn Plate Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides.",rewards={{id=22425,qty=1}}} end
