if not DB[9062] then DB[9062]={id=9062,zoneId=3430,name="Soaked Pages",level=6,minLevel=4,giver="Apprentice Meledor",giverType="NPC",giverId=15945,ender="Apprentice Meledor",enderType="NPC",enderId=15945,rewardNextId=9064,poiX=9038,poiY=-6698,wowhead="https://www.wowhead.com/wotlk/quest=9062",image="assets/images/quests/placeholder.png",xpDiff=3,money=250,desc="Those blasted Wretched sure can run fast at the sight of someone who'll stand up to them.  But let's not worry about that now.  I need to find my instructor's elemental grimoire.$B$BI'm certain I saw one of those cowards throw it into the river but I cannot seem to be able to locate it.  I could use another set of eyes.  I'll throw in a bit of coin if you spot it.",logDesc="Apprentice Meledor in Eversong Woods wants you to search the water beneath the bridge nearby and bring him Antheol's Elemental Grimoire."} end
if not DB[9063] then DB[9063]={id=9063,zoneId=-263,name="Torwa Pathfinder",level=52,minLevel=50,giver="Turak Runetotem",giverType="NPC",giverId=3033,ender="Torwa Pathfinder",enderType="NPC",enderId=9619,rewardNextId=9052,poiX=-1039,poiY=-282,wowhead="https://www.wowhead.com/wotlk/quest=9063",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A hunter by the name of Torwa Pathfinder has requested the help of a druid.  He said only we would possess the necessary skills and respect for nature to help him.$b$bThere is a road that connects the Un'Goro Crater and the desert of Tanaris.  As that road enters the crater, you will find Torwa close by.",logDesc="Speak with Torwa Pathfinder in Un'Goro Crater."} end
if not DB[9064] then DB[9064]={id=9064,zoneId=3430,name="Taking the Fall",level=6,minLevel=4,giver="Apprentice Meledor",giverType="NPC",giverId=15945,ender="Instructor Antheol",enderType="NPC",enderId=15970,rewardNextId=9066,poiX=9038,poiY=-6698,wowhead="https://www.wowhead.com/wotlk/quest=9064",image="assets/images/quests/placeholder.png",xpDiff=2,money=125,desc="Antheol is going to fly off his rocker when he finds out his book is ruined.  I've got a little proposal for you; don't worry, I'll make it worth your while.$B$BTake this book to him and tell him nothing of this incident.  If he asks, just tell him you dropped the book into a puddle.  He has no direct authority over you, so there's not much he can do.$B$BAntheol delivers his lectures at Stillwhisper Pond, southeast of Silvermoon.  You'll do this for us, right?  I'll reward you handsomely for this favor!",logDesc="Bring Antheol's Elemental Grimoire to Instructor Antheol at Stillwhisper Pond in Eversong Woods."} end
if not DB[9065] then DB[9065]={id=9065,zoneId=22,name="The Pattymac Special",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9065",image="assets/images/quests/placeholder.png",xpDiff=7,money=50,desc="Hey you, knock down that tower!",logDesc="Make sure you destroy that tower!",rewards={{id=159,qty=1},{id=118,qty=5}}} end
if not DB[9066] then DB[9066]={id=9066,zoneId=3430,name="Swift Discipline",level=6,minLevel=4,giver="Instructor Antheol",giverType="NPC",giverId=15970,ender="Instructor Antheol",enderType="NPC",enderId=15970,poiX=9252,poiY=-7231,wowhead="https://www.wowhead.com/wotlk/quest=9066",image="assets/images/quests/placeholder.png",xpDiff=5,money=125,desc="I hope you learn a valuable lesson today, $N.  Never trust someone else to lie for you.$B$BNow I want you to go back to my two dimwitted students and discipline them using this wand.  My magic tells me that you'll find them along the road to the west on the other side of the Dead Scar.$B$BCome back to me after you've done this.  I'll give you a small reward for your troubles.",logDesc="Use Antheol's Disciplinary Rod on his two students: Apprentice Ralen and Apprentice Meledor.  Return to Antheol at Stillwhisper Pond in Eversong Woods with the rod after this.",rewards={{id=22976,qty=1}}} end
if not DB[9067] then DB[9067]={id=9067,zoneId=3430,name="The Party Never Ends",level=9,minLevel=7,giver="Lord Saltheril",giverType="NPC",giverId=16144,ender="Lord Saltheril",enderType="NPC",enderId=16144,poiX=8627,poiY=-6366,wowhead="https://www.wowhead.com/wotlk/quest=9067",image="assets/images/quests/placeholder.png",xpDiff=5,money=900,desc="I like to throw parties... just a little something to celebrate the magnificence that is Quel'Thalas!$B$BBut, I'm in a bit of a bind.  I need you to gather up more party supplies.$B$BFrom Vinemaster Suntouched at the Silvermoon City inn, bring me a bottle of Suntouched Special Reserve.  From Zalene Firstlight at Farstrider Retreat acquire more of those delicious Springpaw Appetizers.  And you can pick up my delivery of fireworks from Halis Dawnstrider at Fairbreeze Village.$B$BBe quick about it!",logDesc="Acquire a bottle of Suntouched Special Reserve, Springpaw Appetizers and a Bundle of Fireworks, and return them to Lord Saltheril at Saltheril's Haven in Eversong Woods.",rewards={{id=23500,qty=1}}} end
if not DB[9068] then DB[9068]={id=9068,zoneId=3456,name="Earthshatter Tunic",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=9068",image="assets/images/quests/placeholder.png",desc="Would you honor me by returning the armor of those that fell in the defense of these lands?$B$BThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.$B$BBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.$B$BSearch Naxxramas.",logDesc="Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make an Earthshatter Tunic if you bring him the following: 1 Desecrated Tunic, 25 Wartorn Chain Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides.",rewards={{id=22464,qty=1}}} end
