if not DB[9076] then DB[9076]={id=9076,zoneId=3430,name="Wretched Ringleader",level=8,minLevel=5,giver="Velendris Whitemorn",giverType="NPC",giverId=15404,ender="Velendris Whitemorn",enderType="NPC",enderId=15404,poiX=8849,poiY=-6278,wowhead="https://www.wowhead.com/wotlk/quest=9076",image="assets/images/quests/placeholder.png",xpDiff=5,money=225,desc="The Wretched are so oblivious, gorging on foul magic, that they haven't realized we've recovered most of our weapons.  We can't expect them to remain in their stupor, though.  Now is the time for a decisive attack.  Let us make an example of their leader, Aldaron.  He was spotted on the top floor of the building by the anchorage.  Bring me his head; I'll reward you suitably.",logDesc="Bring Aldaron's Head to Velendris Whitemorn near Sunsail Anchorage in Eversong Woods.",choiceRewards={{id=22964,qty=1},{id=22965,qty=1},{id=22966,qty=1}}} end
if not DB[9077] then DB[9077]={id=9077,zoneId=3456,name="Bonescythe Breastplate",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=9077",image="assets/images/quests/placeholder.png",desc="If you want Bonescythe made, you're going to have to supply the materials.$B$BEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.",logDesc="Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands will make a Bonescythe Breastplate if you bring him the following: 1 Desecrated Breastplate, 25 Wartorn Leather Scraps, 2 Arcanite Bars and 6 Cured Rugged Hides.",rewards={{id=22476,qty=1}}} end
