if not DB[9119] then DB[9119]={id=9119,zoneId=3430,name="Malfunction at the West Sanctum",level=5,minLevel=4,giver="Ley-Keeper Caidanis",giverType="NPC",giverId=15405,ender="Ley-Keeper Velania",enderType="NPC",enderId=15401,rewardNextId=8486,poiX=9297,poiY=-6685,wowhead="https://www.wowhead.com/wotlk/quest=9119",image="assets/images/quests/placeholder.png",xpDiff=5,money=100,desc="Since you're here, $N, I've a favor to ask you.  Ley-Keeper Velania's apprentice dropped by earlier to ask for assistance.  Apparently there's some malfunction happening at the West Sanctum.  I've been a bit busy entertaining our... most pleasant... dwarven guest.  See if you can give her a hand.  You'll find the West Sanctum southwest of here.",logDesc="Speak to Ley-Keeper Velania at the West Sanctum in Eversong Woods."} end
if not DB[9120] then DB[9120]={id=9120,zoneId=3456,name="The Fall of Kel'Thuzad",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=9120",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The phylactery is all that remains of the master of Naxxramas. Your better judgment dictates that you destroy the phylactery, preventing the lich from ever reforming. Thankfully, you seldom listen to that internal voice of reason.$B$BSomeone at Light's Hope will pay you hugely for this artifact. Who cares if Kel'Thuzad regenerates to full power?",logDesc="Take the Phylactery of Kel'Thuzad to Light's Hope Chapel in the Eastern Plaguelands.",choiceRewards={{id=23206,qty=1},{id=23207,qty=1}}} end
if not DB[9121] then DB[9121]={id=9121,zoneId=139,name="The Dread Citadel - Naxxramas",level=60,minLevel=60,giver="Archmage Angela Dosantos",giverType="NPC",giverId=16116,ender="Archmage Angela Dosantos",enderType="NPC",enderId=16116,poiX=2296,poiY=-5341,wowhead="https://www.wowhead.com/wotlk/quest=9121",image="assets/images/quests/placeholder.png",desc="In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.$B$BWe have devised a way to gain entry via arcane cloaking - an old cantrip of the Kirin Tor with a few modifications of my own. Since your dedication to the cause of the Dawn is somewhat lacking, $N, the price will be high. You may decline and choose to return when you are revered or exalted for a discount.",logDesc="Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 5 Arcane Crystals, 2 Nexus Crystals, 1 Righteous Orb and 60 gold pieces. You must also be Honored with the Argent Dawn.$B"} end
if not DB[9122] then DB[9122]={id=9122,zoneId=139,name="The Dread Citadel - Naxxramas",level=60,minLevel=60,giver="Archmage Angela Dosantos",giverType="NPC",giverId=16116,ender="Archmage Angela Dosantos",enderType="NPC",enderId=16116,poiX=2296,poiY=-5341,wowhead="https://www.wowhead.com/wotlk/quest=9122",image="assets/images/quests/placeholder.png",desc="In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.$B$BWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly. Since your dedication to the cause of the Dawn is admirable, we are willing to incur some of those costs.",logDesc="Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 2 Arcane Crystals, 1 Nexus Crystal and 30 gold pieces. You must also be Revered with the Argent Dawn."} end
if not DB[9123] then DB[9123]={id=9123,zoneId=139,name="The Dread Citadel - Naxxramas",level=60,minLevel=60,giver="Archmage Angela Dosantos",giverType="NPC",giverId=16116,ender="Archmage Angela Dosantos",enderType="NPC",enderId=16116,poiX=2296,poiY=-5341,wowhead="https://www.wowhead.com/wotlk/quest=9123",image="assets/images/quests/placeholder.png",desc="In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.$B$BWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.",logDesc="Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn."} end
if not DB[9124] then DB[9124]={id=9124,zoneId=139,name="Cryptstalker Armor Doesn't Make Itself...",level=60,minLevel=55,giver="Huntsman Leopold",giverType="NPC",giverId=16132,ender="Huntsman Leopold",enderType="NPC",enderId=16132,poiX=2289,poiY=-5340,wowhead="https://www.wowhead.com/wotlk/quest=9124",image="assets/images/quests/placeholder.png",xpDiff=5,desc="How would you like to earn yourself one of these shiny coins?$B$B<Leopold holds up an insignia of the Crusade.>$B$BI've got a little problem that you might be able to help me with, $N. You see, I make Cryptstalker armor for those daft enough to venture into Naxxramas. While they supply me with the core material requirements for the armor, I always run out of the crypt fiend parts. Bring me back a bundle of parts and I'll pay you with an insignia - usable at the quartermaster.",logDesc="Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands wants 30 Crypt Fiend Parts.",rewards={{id=22524,qty=1}}} end
if not DB[9125] then DB[9125]={id=9125,zoneId=139,name="Crypt Fiend Parts",level=60,minLevel=55,giver="Huntsman Leopold",giverType="NPC",giverId=16132,ender="Huntsman Leopold",enderType="NPC",enderId=16132,poiX=2289,poiY=-5340,wowhead="https://www.wowhead.com/wotlk/quest=9125",image="assets/images/quests/placeholder.png",money=900,rewards={{id=22524,qty=1}}} end
if not DB[9126] then DB[9126]={id=9126,zoneId=139,name="Bonescythe Digs",level=60,minLevel=55,giver="Rohan the Assassin",giverType="NPC",giverId=16131,ender="Rohan the Assassin",enderType="NPC",enderId=16131,poiX=2290,poiY=-5337,wowhead="https://www.wowhead.com/wotlk/quest=9126",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Don Julio's Bonescythe armor pattern requires bone fragments - a lot of bone fragments. While those crazy enough to venture into Naxxramas provide me with enough of the core materials to make the armor, I'm always looking for more Scourge bone fragments.$B$BSo what do you think? Interested in getting your hands dirty and destroying some Scourge at the same time? It's a win-win situation.",logDesc="Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands wants 30 Bone Fragments.$B",rewards={{id=22524,qty=1}}} end
if not DB[9127] then DB[9127]={id=9127,zoneId=139,name="Bone Fragments",level=60,minLevel=55,giver="Rohan the Assassin",giverType="NPC",giverId=16131,ender="Rohan the Assassin",enderType="NPC",enderId=16131,poiX=2290,poiY=-5337,wowhead="https://www.wowhead.com/wotlk/quest=9127",image="assets/images/quests/placeholder.png",money=900,rewards={{id=22524,qty=1}}} end
if not DB[9128] then DB[9128]={id=9128,zoneId=139,name="The Elemental Equation",level=60,minLevel=55,giver="Archmage Angela Dosantos",giverType="NPC",giverId=16116,ender="Archmage Angela Dosantos",enderType="NPC",enderId=16116,poiX=2296,poiY=-5341,wowhead="https://www.wowhead.com/wotlk/quest=9128",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Greetings, adventurer! Are you interested in some work? I pay those under my employ with insignias. These insignias can be used at the Quartermaster to purchase items of power.$B$BAll I need you to do is bring me as many core of elements as you can carry. The more the better!$B$BYou'll find them on elementals of varying shapes and sizes that exist across our world.",logDesc="Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 30 Core of Elements.$B",rewards={{id=22523,qty=1}}} end
if not DB[9129] then DB[9129]={id=9129,zoneId=139,name="Core of Elements",level=60,minLevel=55,giver="Archmage Angela Dosantos",giverType="NPC",giverId=16116,ender="Archmage Angela Dosantos",enderType="NPC",enderId=16116,poiX=2296,poiY=-5341,wowhead="https://www.wowhead.com/wotlk/quest=9129",image="assets/images/quests/placeholder.png",money=900,rewards={{id=22523,qty=1}}} end
if not DB[9130] then DB[9130]={id=9130,zoneId=3433,name="Goods from Silvermoon City",level=10,minLevel=10,giver="Quartermaster Lymel",giverType="NPC",giverId=16187,ender="Skymaster Sunwing",enderType="NPC",enderId=16189,rewardNextId=9133,poiX=7623,poiY=-6846,wowhead="https://www.wowhead.com/wotlk/quest=9130",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Welcome volunteer!  We're running low on supplies here, but the blood elves have promised us materiel assistance.  That's where you come in.$B$BTake this bill of lading over to Skymaster Sunwing. He'll have further instructions for you on how best to get up to Silvermoon City.",logDesc="Deliver Quartermaster Lymel's Bill of Lading to Skymaster Sunwing in Tranquillien."} end
if not DB[9131] then DB[9131]={id=9131,zoneId=139,name="Binding the Dreadnaught",level=60,minLevel=55,giver="Korfax, Champion of the Light",giverType="NPC",giverId=16112,ender="Korfax, Champion of the Light",enderType="NPC",enderId=16112,poiX=2301,poiY=-5352,wowhead="https://www.wowhead.com/wotlk/quest=9131",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Have you ever seen Dreadnaught armor, $c? No, of course you haven't. You're still a $g boy:girl; - a tyke. Let me tell you, it is glorious.$B$BYou're probably asking yourself what any of this has to do with you, right? I'll tell you what, scrub; I need Dark Iron scraps and I'm willing to pay to get my hands on as many as possible.$B$BI need the scraps to put together sets of Dreadnaught for our champions. Bring me scraps and get paid.",logDesc="Korfax at Light's Hope Chapel in the Eastern Plaguelands wants 30 Dark Iron Scraps.",rewards={{id=22523,qty=1}}} end
if not DB[9132] then DB[9132]={id=9132,zoneId=139,name="Dark Iron Scraps",level=60,minLevel=55,giver="Korfax, Champion of the Light",giverType="NPC",giverId=16112,ender="Korfax, Champion of the Light",enderType="NPC",enderId=16112,poiX=2301,poiY=-5352,wowhead="https://www.wowhead.com/wotlk/quest=9132",image="assets/images/quests/placeholder.png",money=900,rewards={{id=22523,qty=1}}} end
if not DB[9133] then DB[9133]={id=9133,zoneId=3433,name="Fly to Silvermoon City",level=10,minLevel=10,giver="Skymaster Sunwing",giverType="NPC",giverId=16189,ender="Sathren Azuredawn",enderType="NPC",enderId=16191,rewardNextId=9134,poiX=7595,poiY=-6782,wowhead="https://www.wowhead.com/wotlk/quest=9133",image="assets/images/quests/placeholder.png",xpDiff=3,money=175,desc="$C, for a very modest amount of coin, I can send you swiftly flying through the air on one of these magnificent beasts.  And, it's safer than walking there, I can assure you!$B$BWhen you arrive in Silvermoon City, seek out Sathren Azuredawn in the Bazaar.$B$BSpeak with me once more when you've decided you're ready to brave the skies.",logDesc="Purchase a flight to Silvermoon City and deliver Quartermaster Lymel's Bill of Lading to Sathren Azuredawn in Silvermoon City."} end
if not DB[9134] then DB[9134]={id=9134,zoneId=3433,name="Skymistress Gloaming",level=10,minLevel=10,giver="Sathren Azuredawn",giverType="NPC",giverId=16191,ender="Skymistress Gloaming",enderType="NPC",enderId=16192,rewardNextId=9135,poiX=9581,poiY=-7054,wowhead="https://www.wowhead.com/wotlk/quest=9134",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It doesn't look as if you have a cart or a beast of burden with you, so I'd better send you back only with what you can carry.  If you've spoken with Skymaster Sunwing at Tranquillien, then you should get this to Quartermaster Lymel as soon as possible by flying back.$B$BTake these goods for final inspection to Skymistress Gloaming just outside Silvermoon City's Shepherd's Gate.",logDesc="Bring Quartermaster Lymel's Goods to Skymistress Gloaming just outside Silvermoon City's Shepherd's Gate."} end
if not DB[9135] then DB[9135]={id=9135,zoneId=3433,name="Return to Quartermaster Lymel",level=10,minLevel=10,giver="Skymistress Gloaming",giverType="NPC",giverId=16192,ender="Quartermaster Lymel",enderType="NPC",enderId=16187,poiX=9376,poiY=-7165,wowhead="https://www.wowhead.com/wotlk/quest=9135",image="assets/images/quests/placeholder.png",xpDiff=6,money=350,desc="It all checks out as far as I can tell.  Seems to me that the Forsaken have put their backs to the wall for us and we owe them, even if they are all ugly and rotting.$B$BSo, the question is, have you already spoken to Skymaster Sunwing in Tranquillien?  If so, then this can be as simple as you paying the small fare and quickly flying back.$B$BLet me know when you're ready.",logDesc="Purchase a flight back to Tranquillien in the Ghostlands and deliver Quartermaster Lymel's Goods to Quartermaster Lymel at Tranquillien in the Ghostlands."} end
if not DB[9136] then DB[9136]={id=9136,zoneId=139,name="Savage Flora",level=60,minLevel=55,giver="Rayne",giverType="NPC",giverId=16135,ender="Rayne",enderType="NPC",enderId=16135,poiX=2277,poiY=-5329,wowhead="https://www.wowhead.com/wotlk/quest=9136",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I make a special type of armor for the brave heroes that enter Naxxramas known as Dreamwalker. They are able to provide me with most of the materials I require but I am always looking for those able to retrieve savage fronds from the flora of our world.$B$BYou may think of this job as beneath you, but without the fronds, the armor could not be made.$B$BI am also in a unique position to pay you with an insignia of your choice as both the Dawn and the Crusade supply me with funds.$B",logDesc="Rayne at Light's Hope Chapel in the Eastern Plaguelands wants 30 Savage Fronds.",choiceRewards={{id=22524,qty=1},{id=22523,qty=1}}} end
if not DB[9137] then DB[9137]={id=9137,zoneId=139,name="Savage Fronds",level=60,minLevel=55,giver="Rayne",giverType="NPC",giverId=16135,ender="Rayne",enderType="NPC",enderId=16135,poiX=2277,poiY=-5329,wowhead="https://www.wowhead.com/wotlk/quest=9137",image="assets/images/quests/placeholder.png",money=900,choiceRewards={{id=22523,qty=1},{id=22524,qty=1}}} end
if not DB[9138] then DB[9138]={id=9138,zoneId=3433,name="Suncrown Village",level=10,minLevel=9,giver="Arcanist Vandril",giverType="NPC",giverId=16197,ender="Arcanist Vandril",enderType="NPC",enderId=16197,rewardNextId=9139,poiX=7642,poiY=-6819,wowhead="https://www.wowhead.com/wotlk/quest=9138",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="We're surrounded here, $c.  The outlying villages have all been overrun by the Scourge!$B$BYou must head northeast to Suncrown Village immediately and deal with the Nerubian Scourge menace.  You can't miss them - they're spider-like creatures.$B$BThere's no time to waste.... Quel'Thalas must be reclaimed!",logDesc="Slay 10 Nerubis Guards and then return to Arcanist Vandril at Tranquillien in the Ghostlands."} end
if not DB[9139] then DB[9139]={id=9139,zoneId=3433,name="Goldenmist Village",level=11,minLevel=9,giver="Arcanist Vandril",giverType="NPC",giverId=16197,ender="Arcanist Vandril",enderType="NPC",enderId=16197,rewardNextId=9140,poiX=7642,poiY=-6819,wowhead="https://www.wowhead.com/wotlk/quest=9139",image="assets/images/quests/placeholder.png",xpDiff=5,money=400,desc="We've had one success, but there are two more villages that must be reclaimed!$B$BGoldenmist Village is our next target. It lies to the northwest, and has been taken by the ghosts of the high elves that used to live there. Gruesome, I know, but these are apparently the sorts of tactics that the Scourge like to employ.$B$BGo and defeat these ghosts and wraiths, $c. Take the west road out of Tranquillien to get there.",logDesc="Defeat 6 Quel'dorei Ghosts and 4 Quel'dorei Wraiths at Goldenmist Village, and then return to Arcanist Vandril at Tranquillien in the Ghostlands.",rewards={{id=23444,qty=5},{id=28152,qty=1}}} end
if not DB[9140] then DB[9140]={id=9140,zoneId=3433,name="Windrunner Village",level=14,minLevel=9,giver="Arcanist Vandril",giverType="NPC",giverId=16197,ender="Arcanist Vandril",enderType="NPC",enderId=16197,poiX=7642,poiY=-6819,wowhead="https://www.wowhead.com/wotlk/quest=9140",image="assets/images/quests/placeholder.png",xpDiff=6,money=1300,desc="$N, the final battle against the Ghostlands villages is upon you. Windrunner Village to the southwest has been overrun by a large force of the more powerful Scourge shocktroopers; shades and gargoyles. You will be the spearpoint of our offensive by thinning out their numbers.$B$BThe magisters at the nearby Sanctum of the Sun have made a special request this time; they want the remains from these Scourge to study in hopes of finding creative ways of fighting them.$B$BGood hunting!",logDesc="Gather 6 Phantasmal Substance and 4 Gargoyle Fragments.  Return them to Arcanist Vandril at Tranquillien in the Ghostlands.",choiceRewards={{id=23402,qty=1},{id=23403,qty=1},{id=23404,qty=1},{id=28151,qty=1}}} end
if not DB[9141] then DB[9141]={id=9141,zoneId=139,name="They Call Me \"The Rooster\"",level=60,minLevel=55,giver="Dispatch Commander Metz",giverType="NPC",giverId=16212,ender="Dispatch Commander Metz",enderType="NPC",enderId=16212,poiX=2315,poiY=-5323,wowhead="https://www.wowhead.com/wotlk/quest=9141",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You want a writ? What? Do you expect me to hand you a highly sought after work order just for showing up? I think not, scrub. Crafters from around the world bid for jobs here at the front lines.$B$BIf you want a work order, you'll have to show me that you're willing to bleed for the cause. Bring me a valor token and we'll talk.$B$BAnd there's only one way to get your grubby little scrub mitts on those - get to killin'.",logDesc="Dispatch Commander Metz at Light's Hope Chapel in the Eastern Plaguelands wants an Argent Dawn Valor Token.$B",rewards={{id=22568,qty=1}}} end
if not DB[9142] then DB[9142]={id=9142,zoneId=139,name="Craftsman's Writ",level=60,minLevel=55,giver="Dispatch Commander Metz",giverType="NPC",giverId=16212,ender="Dispatch Commander Metz",enderType="NPC",enderId=16212,poiX=2315,poiY=-5323,wowhead="https://www.wowhead.com/wotlk/quest=9142",image="assets/images/quests/placeholder.png",rewards={{id=22568,qty=1}}} end
if not DB[9143] then DB[9143]={id=9143,zoneId=3433,name="Dealing with Zeb'Sora",level=12,minLevel=9,giver="Ranger Valanna",giverType="NPC",giverId=16219,ender="Ranger Valanna",enderType="NPC",enderId=16219,rewardNextId=9146,poiX=7933,poiY=-7574,wowhead="https://www.wowhead.com/wotlk/quest=9143",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The lieutenant here rushed us into battle with the trolls across the lake instead of scouting the situation first. We were decimated by his stupidity! You hear me Tomathren? You're an idiot!$B$BWill you help us, $c? Those trolls still need to be dealt with. I need to stay here and nursemaid him -- I think he's lost his mind.$B$BJust head east to the other side of the lake into Zeb'Sora. I want revenge... bring me their ears so that I can fashion a nice necklace!",logDesc="Collect 6 Zeb'Sora Troll Ears and return them to Ranger Valanna in the Ghostlands."} end
if not DB[9144] then DB[9144]={id=9144,zoneId=3433,name="Missing in the Ghostlands",level=10,minLevel=10,giver="Magistrix Landra Dawnstrider",giverType="NPC",giverId=16210,ender="Courier Dawnstrider",enderType="NPC",enderId=16183,poiX=8718,poiY=-6656,wowhead="https://www.wowhead.com/wotlk/quest=9144",image="assets/images/quests/placeholder.png",xpDiff=3,desc="My nephew was sent into the Ghostlands a few days ago.  He never mentioned anything about his task, except that it was of an extremely secret nature.$B$BHe never returned and I fear for the worst, $c.  A missing messenger might not mean much to the callous magisters of Silvermoon, but he's like a son to me.  Please, $N, will you look for him?",logDesc="Follow the road out of Fairbreeze Village towards the south and look for Courier Dawnstrider as you approach the Ghostlands."} end
if not DB[9145] then DB[9145]={id=9145,zoneId=3433,name="Help Ranger Valanna!",level=12,minLevel=9,giver="Ranger Lethvalin",giverType="NPC",giverId=16213,ender="Ranger Valanna",enderType="NPC",enderId=16219,rewardNextId=9143,poiX=7553,poiY=-6784,wowhead="https://www.wowhead.com/wotlk/quest=9145",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$C, I can't just sit here waiting for an audience with the high executor or Dame Auriferous! This cannot wait!$B$BWe were dealing with the Shadowpine trolls of Zeb'Sora to the northeast across Lake Elrendar. But the lieutenant mishandled the attack and we lost a lot of Farstriders. Then he just fell to pieces afterward.  Ranger Valanna sent me here, and Ranger Salissa to the Farstrider Enclave for help.$B$BPlease find them, $c. Valanna was badly injured and the lieutenant's useless.",logDesc="Find Ranger Valanna and Lieutenant Tomathren on the shore of Lake Elrendar in the Ghostlands near Suncrown Village."} end
if not DB[9146] then DB[9146]={id=9146,zoneId=3433,name="Report to Captain Helios",level=12,minLevel=9,giver="Ranger Valanna",giverType="NPC",giverId=16219,ender="Captain Helios",enderType="NPC",enderId=16220,poiX=7933,poiY=-7574,wowhead="https://www.wowhead.com/wotlk/quest=9146",image="assets/images/quests/placeholder.png",xpDiff=2,money=500,desc="I need one last favor of you, $c.  Just in case Ranger Salissa didn't make it back to Farstrider Enclave on the south edge of the lake, I need you to go there and get help.$B$BJust check in with Captain Helios and let him know what's happened here.  I'm sure he'll send help back as soon as he can.",logDesc="Speak with Captain Helios at the Farstrider Enclave on the southern shore of Lake Elrendar in the Ghostlands.",choiceRewards={{id=23405,qty=1},{id=28144,qty=1},{id=28153,qty=1}}} end
if not DB[9147] then DB[9147]={id=9147,zoneId=3433,name="The Fallen Courier",level=10,minLevel=9,giver="Apothecary Thedra",giverType="NPC",giverId=16196,ender="Apothecary Thedra",enderType="NPC",enderId=16196,poiX=8118,poiY=-6902,wowhead="https://www.wowhead.com/wotlk/quest=9147",image="assets/images/quests/placeholder.png",xpDiff=5,desc="What are you standing around for?  Can't you see this boy needs immediate attention?  By the looks of it, the plague is beginning to take over his body.  Within minutes not even a master apothecary like me will be able to save him.$B$BThe animals south of the river all carry the plague in their blood.  Go across the bridge and hunt the plagued beasts there.  Bring me enough plagued blood samples and I'll distill a serum capable of saving this blood elf.  Hurry!",logDesc="Apothecary Thedra in Eversong Woods wants you to bring her 4 Plagued Blood Samples from beasts in the Ghostlands."} end
if not DB[9148] then DB[9148]={id=9148,zoneId=3433,name="Delivery to Tranquillien",level=10,minLevel=9,giver="Courier Dawnstrider",giverType="NPC",giverId=16183,ender="Arcanist Vandril",enderType="NPC",enderId=16197,poiX=8120,poiY=-6900,wowhead="https://www.wowhead.com/wotlk/quest=9148",image="assets/images/quests/placeholder.png",xpDiff=3,money=175,desc="I... I'm too weak to continue.  I carry a dire warning from Regent Lord Theron, in the form of a letter.  You'll have to deliver it for me.$B$BTake it to Arcanist Vandril in Tranquillien.  You'll find the town further to the south along this road.  Go there and... find Vandril...",logDesc="Bring the Letter from Silvermoon to Arcanist Vandril at Tranquillien in the Ghostlands.",rewards={{id=22571,qty=1}},choiceRewards={{id=28146,qty=1},{id=28147,qty=1},{id=28148,qty=1}}} end
if not DB[9149] then DB[9149]={id=9149,zoneId=3433,name="The Plagued Coast",level=13,minLevel=10,giver="Apothecary Renzithen",giverType="NPC",giverId=16198,ender="Apothecary Renzithen",enderType="NPC",enderId=16198,poiX=7500,poiY=-6856,wowhead="https://www.wowhead.com/wotlk/quest=9149",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="To find a cure for the plague we need to understand how it affects different creatures, from the most complex life forms to the lowliest subspecies.$B$BI've come here to study the murlocs since, like us, they've retained free will in undeath.  What makes these lowly mongrels so special?  I need to find out, $N!$B$BTravel northwest and bring me their spines so that I may study the accumulation of plague in their marrow.  Who knows what secrets their little bones hold?",logDesc="Bring 6 Plagued Murloc Spines to Apothecary Renzithen in Tranquillien in the Ghostlands.",rewards={{id=6372,qty=2},{id=28150,qty=1}}} end
if not DB[9150] then DB[9150]={id=9150,zoneId=3433,name="Salvaging the Past",level=12,minLevel=9,giver="Magister Darenis",giverType="NPC",giverId=16199,ender="Magister Darenis",enderType="NPC",enderId=16199,poiX=7564,poiY=-6802,wowhead="https://www.wowhead.com/wotlk/quest=9150",image="assets/images/quests/placeholder.png",xpDiff=5,money=500,desc="Can you believe it?  We have an actual functioning arcane sanctum up and running southeast of here: the Sanctum of the Sun.  All manner of important magisters have come to take part in running it.$B$BOf course they've all forgotten about the Sanctum of the Moon.  Not much remains of it and its energies have given rise to bizarre creatures.$B$BI'm not one to let good resources go to waste, however.  Go to the Sanctum of the Moon and see if you can recover the crystallized essences from the creatures there.",logDesc="Magister Darenis wants you to travel to the Sanctum of the Moon to the west of Tranquillien and recover 8 Crystallized Mana Essences from the Arcane Devourers and Mana Shifters that inhabit the structure."} end
if not DB[9151] then DB[9151]={id=9151,zoneId=3433,name="The Sanctum of the Sun",level=20,minLevel=17,giver="Magister Darenis",giverType="NPC",giverId=16199,ender="Magister Idonis",enderType="NPC",enderId=16204,rewardNextId=9220,poiX=7564,poiY=-6802,wowhead="https://www.wowhead.com/wotlk/quest=9151",image="assets/images/quests/placeholder.png",xpDiff=3,money=600,desc="You've proven your loyalty to Tranquillien and have helped us defend it against the threat of the Scourge.  Some of our most powerful magisters have come from Silvermoon to help us take the fight to the enemy's doorstep.$B$BThey've rebuilt the arcane sanctum to the south and have driven the Scourge away from the surrounding area.  They plan to launch an offensive into Deatholme, Dar'Khan's stronghold.  You would do well to join them, $N.  I'm sure they can make use of a seasoned $c like yourself.",logDesc="Speak to Magister Idonis in the Sanctum of the Sun in the Ghostlands."} end
if not DB[9152] then DB[9152]={id=9152,zoneId=3433,name="Tomber's Supplies",level=11,minLevel=9,giver="Rathis Tomber",giverType="NPC",giverId=16224,ender="Rathis Tomber",enderType="NPC",enderId=16224,poiX=7638,poiY=-6842,wowhead="https://www.wowhead.com/wotlk/quest=9152",image="assets/images/quests/placeholder.png",xpDiff=5,money=400,desc="How am I supposed to supply the war effort when I cannot even safely get my supplies here? I was promised an escort that never came. And then, I had to leave one of my carts behind to the west when I was attacked by a band of ghouls!$B$BWant to help out, and get me open for business in the process? Go down the western road out of town and past the graveyard. On the other side of the Dead Scar is a fork in the road. The hill that my cart had to be left on lies just beyond.",logDesc="Retrieve Rathis Tomber's Supplies and return it to him at Tranquillien in the Ghostlands."} end
if not DB[9153] then DB[9153]={id=9153,zoneId=-368,name="Under the Shadow",level=-1,minLevel=50,giver="Commander Thomas Helleran",giverType="NPC",giverId=16361,ender="Commander Thomas Helleran",enderType="NPC",enderId=16361,wowhead="https://www.wowhead.com/wotlk/quest=9153",image="assets/images/quests/placeholder.png",desc="The floating necropolises of the Scourge plague the lands of Horde and Alliance alike. Tanaris, the Blasted Lands, Winterspring and the Burning Steppes are blanketed in the shadows of the flying fortresses.$b$bOnly through our combined efforts will they be repelled.$b$bEach necropolis is supported by nearby magical circles, and among each circle swarms a host of undead creartures. We have determined that destroying these mindless hordes will destroy the circle's defenses.",logDesc="Check your map to find an area under Scourge attack. Go there and damage a necropolis by defeating the Scourge around them. Return 10 of their Necrotic Runes to Commander Thomas Helleran at Light's Hope Chapel in the Eastern Plaguelands.",choiceRewards={{id=23123,qty=2},{id=23122,qty=2}}} end
if not DB[9154] then DB[9154]={id=9154,zoneId=-368,name="Light's Hope Chapel",level=-1,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=9154",image="assets/images/quests/placeholder.png",desc="The Scourge have returned in greater numbers than we have seen before.  This must be the doing of the Lich King!  The Argent Dawn is recruiting all willing and capable men and women to defend our lands.$b$bIf we share common cause, take this document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.",logDesc="Deliver the Call to Arms Announcement to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands."} end
if not DB[9155] then DB[9155]={id=9155,zoneId=3433,name="Down the Dead Scar",level=14,minLevel=10,giver="Deathstalker Rathiel",giverType="NPC",giverId=16200,ender="Deathstalker Rathiel",enderType="NPC",enderId=16200,poiX=7528,poiY=-6802,wowhead="https://www.wowhead.com/wotlk/quest=9155",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="If you've made it this far then you probably know about the Dead Scar and how to this day mindless Scourge follow the path of destruction that Arthas created on his way to Silvermoon City.$B$BMake yourself useful and thin down the Scourge's numbers in the Scar.  If you prove to be worth your salt I'll put in a good word for you.",logDesc="Slay 10 Risen Hungerers and 10 Gangled Cannibals on the Dead Scar.  Return to Deathstalker Rathiel in Tranquillien for a reward."} end
if not DB[9156] then DB[9156]={id=9156,zoneId=3433,name="Wanted: Knucklerot and Luzran",level=21,minLevel=9,ender="Deathstalker Rathiel",enderType="NPC",enderId=16200,wowhead="https://www.wowhead.com/wotlk/quest=9156",image="assets/images/quests/placeholder.png",xpDiff=7,money=4000,desc="A bounty is hereby declared for the abominations known as Knucklerot and Luzran.  These dreadful creations of Dar'Khan are extremely dangerous and have been sighted patrolling near the Howling and Bleeding Ziggurats.  Individuals seeking to claim the reward must present the abominations' heads to Deathstalker Rathiel as proof of the deed.",logDesc="Search the Ghostlands for Knucklerot and Luzran.  Bring their heads to Deathstalker Rathiel in Tranquillien for a reward.",choiceRewards={{id=28303,qty=1},{id=22979,qty=1}}} end
if not DB[9157] then DB[9157]={id=9157,zoneId=3433,name="Forgotten Rituals",level=12,minLevel=9,giver="Geranis Whitemorn",giverType="NPC",giverId=16201,ender="Geranis Whitemorn",enderType="NPC",enderId=16201,rewardNextId=9174,poiX=7847,poiY=-7669,wowhead="https://www.wowhead.com/wotlk/quest=9157",image="assets/images/quests/placeholder.png",xpDiff=5,money=500,desc="Every year we, the denizens of Suncrown Village, would take part in a ritual to keep the different aspects of nature under our control.  Dominion over the element of water was symbolized by the summoning and enslavement of an elemental named Aquantion.  Through a wicked perversion of our magic, the scoundrel broke his bonds and enslaved us instead!$B$BWe wore medallions shaped like waves during the ritual.  Seek them at the bottom of the lake; we'll need them to free my compatriots' spirits!",logDesc="Bring 8 Wavefront Medallions to Geranis Whitemorn in the Ghostlands."} end
if not DB[9158] then DB[9158]={id=9158,zoneId=3433,name="Bearers of the Plague",level=14,minLevel=11,giver="Farstrider Sedina",giverType="NPC",giverId=16202,ender="Farstrider Sedina",enderType="NPC",enderId=16202,poiX=7560,poiY=-7676,wowhead="https://www.wowhead.com/wotlk/quest=9158",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="You show courage coming to the Ghostlands, $N.  There is much work to be done here and not enough brave souls to do it.$B$BI've a thankless task to offer you, should you have the inclination to aid our cause.  The very wildlife in this land has been tainted by the plague and we must stop it from spreading.  Hunt the ghostclaw lynxes to the east and south of here and return when you've slain enough of them.",logDesc="Farstrider Sedina at the Farstrider Enclave in the Ghostlands wants you to slay 10 Ghostclaw Lynxes."} end
if not DB[9159] then DB[9159]={id=9159,zoneId=3433,name="Curbing the Plague",level=15,minLevel=11,giver="Farstrider Sedina",giverType="NPC",giverId=16202,ender="Farstrider Sedina",enderType="NPC",enderId=16202,poiX=7560,poiY=-7676,wowhead="https://www.wowhead.com/wotlk/quest=9159",image="assets/images/quests/placeholder.png",xpDiff=5,money=700,desc="You've proven your worth as an ally, $N.  I need you to continue your task and track down more plagued wildlife.  This time seek out some of the more dangerous beasts.  Hunt the spindleweb lurkers west of the Dead Scar and the vampiric mistbats just south of here.  Return to me when you're done.",logDesc="Farstrider Sedina at the Farstrider Enclave in the Ghostlands wants you to slay 8 Spindleweb Lurkers and 10 Vampiric Mistbats.",rewards={{id=23415,qty=1}},choiceRewards={{id=28141,qty=1},{id=28142,qty=1},{id=28143,qty=1}}} end
if not DB[9160] then DB[9160]={id=9160,zoneId=3433,name="Investigate An'daroth",level=11,minLevel=11,giver="Dame Auriferous",giverType="NPC",giverId=16231,ender="Dame Auriferous",enderType="NPC",enderId=16231,rewardNextId=9163,poiX=7552,poiY=-6764,wowhead="https://www.wowhead.com/wotlk/quest=9160",image="assets/images/quests/placeholder.png",xpDiff=5,money=400,desc="$C, we are having difficulty with a group of night elves that have recently taken over a nearby island. They've set up a small camp at the old high elf ley-line nexus, An'daroth, to the northwest. There is a dirt path that leads up to it just past the Dead Scar.$B$BI suggest that you lend us your aid by going there, investigating what they are up to, and slaying as many of the conceited night elves as you can.",logDesc="Investigate the area at An'daroth, kill 12 Sentinel Spies and then return to Dame Auriferous at Tranquillien in the Ghostlands.",rewards={{id=858,qty=2}}} end
if not DB[9161] then DB[9161]={id=9161,zoneId=3433,name="The Traitor's Shadow",level=16,minLevel=15,giver="Ranger Vynna",giverType="NPC",giverId=16203,rewardNextId=9162,poiX=7549,poiY=-7658,wowhead="https://www.wowhead.com/wotlk/quest=9161",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Dar'Khan Drathir is believed to have returned from the dead to rule over the armies of the Scourge in the Ghostlands.  Dar'Khan aligned himself with the Scourge long ago... yet he was once a living, breathing elf.  Much of his time was spent inside Dawnstar Spire, northeast of here.  He hid there for many nights, scheming against his own. $B$BSearch the tower for more information, $N.  Perhaps he had a journal or kept notes.  One never knows where useful information might present itself.",logDesc="Travel to Dawnstar Spire in the Ghostlands and search for any clues involving Dar'Khan's past."} end
if not DB[9162] then DB[9162]={id=9162,zoneId=3433,name="Hints of the Past",level=16,minLevel=15,ender="Ranger Vynna",enderType="NPC",enderId=16203,rewardNextId=9172,wowhead="https://www.wowhead.com/wotlk/quest=9162",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="As you skim through the pages in the journal you're overcome by an unnerving sense of being watched.$B$BThe contents are unsettling.  Dar'Khan's soul was one filled with hatred and contempt for his own people.  The extent of his machinations and plots are all documented in great detail.$B$BPerhaps there is something here that Vynna will find useful.",logDesc="Return to Ranger Vynna at the Farstrider Enclave with Dar'Khan's Journal."} end
if not DB[9163] then DB[9163]={id=9163,zoneId=3433,name="Into Occupied Territory",level=14,minLevel=11,giver="Dame Auriferous",giverType="NPC",giverId=16231,ender="Dame Auriferous",enderType="NPC",enderId=16231,rewardNextId=9166,poiX=7552,poiY=-6764,wowhead="https://www.wowhead.com/wotlk/quest=9163",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="Now, the more direct course of action that we are going to take, to figure out what these night elves are really up to, is to have you go to their island and steal any information that you can come by.$B$BI want you to head west down the road out of town to Shalandis Isle, just off the coast. Go there and recover any plans they might have on the island or on their ship.",logDesc="Steal the Night Elf Plans: An'daroth, Night Elf Plans: An'owyn and Night Elf Plans: Scrying on the Sin'dorei, and return them to Dame Auriferous at Tranquillien in the Ghostlands."} end
if not DB[9164] then DB[9164]={id=9164,zoneId=3433,name="Captives at Deatholme",level=20,minLevel=17,giver="Apothecary Renzithen",giverType="NPC",giverId=16198,ender="Arcanist Janeda",enderType="NPC",enderId=16240,poiX=7500,poiY=-6856,wowhead="https://www.wowhead.com/wotlk/quest=9164",image="assets/images/quests/placeholder.png",xpDiff=6,money=2500,desc="Ah, yes.  One of my finest creations.  This draught will break most forms of alchemically induced stupor.$B$BSide effects include confusion, nausea and - in rare cases - temporary blindness.  All much preferable to whatever the Scourge plans to do to those prisoners in Deatholme, if you ask me.$B$BBest of luck, brave $c.  You are going to need it.",logDesc="Take Renzithen's Restorative Draught to Deatholme and rescue Apprentice Varnis,  Apothecary Enith and Ranger Vedoran.  Return to Arcanist Janeda at the Sanctum of the Sun for a reward."} end
if not DB[9165] then DB[9165]={id=9165,zoneId=139,name="Writ of Safe Passage",level=60,minLevel=55,giver="Guard Didier",giverType="NPC",giverId=16226,ender="Dispatch Commander Metz",enderType="NPC",enderId=16212,poiX=2305,poiY=-5286,wowhead="https://www.wowhead.com/wotlk/quest=9165",image="assets/images/quests/placeholder.png",desc="Without the help of adventurers, my caravan would have never made it! Scourge were coming out of the woodwork to try and stop us from getting here.$B$B<Guard Didier wipes his brow.>$B$BNow we need to wait here for Field Marshal Chambers to arrive. He'll sign your writ of safe passage to take back to Dispatch Commander Metz at Light's Hope Chapel.$B$BAnd $N, watch what you say around Chambers. He's the 'bite off your head and spit down your wind pipe' type of guy - except that he'll actually do it...",logDesc="Deliver the signed Writ of Safe Passage to Dispatch Commander Metz at Light's Hope Chapel in the Eastern Plaguelands.",choiceRewards={{id=22523,qty=1},{id=22524,qty=1}}} end
if not DB[9166] then DB[9166]={id=9166,zoneId=3433,name="Deliver the Plans to An'telas",level=16,minLevel=11,giver="Dame Auriferous",giverType="NPC",giverId=16231,ender="Magister Sylastor",enderType="NPC",enderId=16237,poiX=7552,poiY=-6764,wowhead="https://www.wowhead.com/wotlk/quest=9166",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You must deliver the recovered night elf plans to An'telas for me. It is to the east, on the southern slopes of Sungraze Peak, just to the northeast of the Sanctum of the Sun.$B$BMagister Sylastor is there conducting ongoing studies into the ley-line nexus energy for potential use in our fight against the Scourge. Have him look at these plans to shed some light on what it is that these night elves are up to.",logDesc="Deliver the Night Elf Plans to Magister Sylastor at An'telas in the Ghostlands."} end
if not DB[9167] then DB[9167]={id=9167,zoneId=3433,name="The Traitor's Destruction",level=21,minLevel=15,giver="Magister Kaendris",giverType="NPC",giverId=16239,ender="Magister Kaendris",enderType="NPC",enderId=16239,poiX=7192,poiY=-7101,wowhead="https://www.wowhead.com/wotlk/quest=9167",image="assets/images/quests/placeholder.png",xpDiff=7,money=4000,desc="Everything we've done in the Ghostlands has been done with the goal of taking back what is rightfully ours.  The Scourge have maintained their chokehold on the region for far too long.$B$BThe time has come for payback, $N.  Thanks to your help and the help of our new allies, the Forsaken, vengeance will soon be ours.$B$BHe who sought to steal the power of the Sunwell must die.  Go to Deatholme, the Scourge stronghold south of the Dead Scar.  Bring me Dar'Khan's head and your deeds will go down in history!",logDesc="Slay Dar'Khan Drathir inside Deatholme and bring his head to Magister Kaendris at the Sanctum of the Sun in the Ghostlands.",choiceRewards={{id=22980,qty=1},{id=22982,qty=1},{id=22984,qty=1},{id=22995,qty=1}}} end
if not DB[9168] then DB[9168]={id=9168,zoneId=3433,name="Heart of Deatholme",level=20,minLevel=16,wowhead="https://www.wowhead.com/wotlk/quest=9168",image="assets/images/quests/placeholder.png",xpDiff=6,money=2500,desc="Deep inside Deatholme our enemies are striving to create stronger, deadlier spectral soldiers.  These abhorrent creatures are perfect killing machines, handcrafted by Dar'Khan himself and hardened by the dark magic of Deatholme.$B$BTravel to the Tower of the Damned inside Deatholme and destroy them, $N.  We cannot let our enemy's army grow in power while we struggle to maintain our foothold in the Ghostlands.",logDesc="Destroy 8 Eyes of Dar'Khan and report back to Magister Idonis at the Sanctum of the Sun in the Ghostlands."} end
if not DB[9169] then DB[9169]={id=9169,zoneId=3433,name="Deactivate An'owyn",level=16,minLevel=11,giver="Magister Sylastor",giverType="NPC",giverId=16237,ender="Magister Sylastor",enderType="NPC",enderId=16237,poiX=7484,poiY=-7274,wowhead="https://www.wowhead.com/wotlk/quest=9169",image="assets/images/quests/placeholder.png",xpDiff=6,money=1600,desc="Their moon crystals are scrying devices -- they're going to spy on us! I know that An'daroth can't provide enough power for that, but An'owyn, directly to the south, most definitely can!$B$BFrom the plans I now have a basic knowledge of how these moon crystals work; enough to shut them down. They're keyed so that they can be turned off. You must go to An'owyn, retrieve the controlling orb from one of the night elves and then use it on the moon crystal to stop them from enacting their plan!$B$BHurry, $c!",logDesc="Retrieve the Crystal Controlling Orb and then use it to deactivate the Night Elf Moon Crystal at An'owyn. Then return to Magister Sylastor at An'telas in the Ghostlands.",choiceRewards={{id=23400,qty=1},{id=23401,qty=1},{id=28160,qty=1}}} end
if not DB[9170] then DB[9170]={id=9170,zoneId=3433,name="Dar'Khan's Lieutenants",level=20,minLevel=17,giver="Magister Idonis",giverType="NPC",giverId=16204,ender="Magister Idonis",enderType="NPC",enderId=16204,poiX=7199,poiY=-7094,wowhead="https://www.wowhead.com/wotlk/quest=9170",image="assets/images/quests/placeholder.png",xpDiff=6,money=2500,desc="The odious traitor, Dar'Khan, has risen to great power among the ranks of the Scourge.  His lieutenants command vast armies of undead against our dwindling numbers.$B$BMasophet the Black, Jurion the Deceiver, Borgoth the Bloodletter, Mirdoran the Fallen.  Learn these names well for in the Ghostlands these Scourge leaders are second only to Dar'Khan himself.  Slay them and their mindless armies will be thrown into disarray.",logDesc="Magister Idonis wants you to venture into Deatholme to slay Masophet the Black, Jurion the Deceiver, Borgoth the Bloodletter and Mirdoran the Fallen.  Report back to him in the Sanctum of the Sun in the Ghostlands after you've completed this task.",choiceRewards={{id=22996,qty=1},{id=22997,qty=1},{id=22998,qty=1}}} end
if not DB[9171] then DB[9171]={id=9171,zoneId=3433,name="Culinary Crunch",level=15,minLevel=12,giver="Master Chef Mouldier",giverType="NPC",giverId=16253,ender="Master Chef Mouldier",enderType="NPC",enderId=16253,poiX=7586,poiY=-6881,wowhead="https://www.wowhead.com/wotlk/quest=9171",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This is intolerable!  I have nothing to work with here! Milady asks me to come from Silvermoon City; she deserves cuisine as befits her station.  No?  But I get here and there is no food.  You must go out, $c, and bring back fresh kills so that I have something to prepare.$B$BDame Auriferous prefers a crunchy texture to her food.  There are plenty of spindleweb lurkers to the southwest on the other side of the Dead Scar.  Disgusting, I know, but that's what we have to work with.",logDesc="Collect 5 Crunchy Spider Legs and return them to Master Chef Mouldier at Tranquillien in the Ghostlands.",rewards={{id=22645,qty=5},{id=22647,qty=1}}} end
if not DB[9172] then DB[9172]={id=9172,zoneId=3433,name="Report to Magister Kaendris",level=16,minLevel=15,giver="Ranger Vynna",giverType="NPC",giverId=16203,ender="Magister Kaendris",enderType="NPC",enderId=16239,rewardNextId=9176,poiX=7549,poiY=-7658,wowhead="https://www.wowhead.com/wotlk/quest=9172",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="The magisters at the Sanctum of the Sun have made great progress in analyzing the Scourge's weaknesses with the aid of the Forsaken.  Magister Kaendris will know what to do with this information.$B$BYou'll find the Sanctum of the Sun southwest of here.  You must hurry, $N.  Dar'Khan is a cunning enemy and watches our every move!",logDesc="Bring Dar'Khan's Journal to Magister Kaendris at the Sanctum of the Sun in the Ghostlands.",choiceRewards={{id=28154,qty=1},{id=28157,qty=1},{id=28161,qty=1}}} end
if not DB[9173] then DB[9173]={id=9173,zoneId=3433,name="Retaking Windrunner Spire",level=15,minLevel=15,giver="High Executor Mavren",giverType="NPC",giverId=16252,ender="High Executor Mavren",enderType="NPC",enderId=16252,poiX=7553,poiY=-6761,wowhead="https://www.wowhead.com/wotlk/quest=9173",image="assets/images/quests/placeholder.png",xpDiff=5,money=700,desc="$C, I want you to reclaim Windrunner Spire!$B$BIt's an honor, really. Windrunner Spire is the original home of Lady Sylvanas Windrunner, queen of the Forsaken and former ranger-general of the elves. But now it's been overrun by the mindless Scourge.$B$BTo get there take the road south until it branches. Take the right fork and after crossing the Dead Scar continue southwest. You can't miss it.",logDesc="Slay 8 Deatholme Acolytes and 10 Fallen Rangers, and return to High Executor Mavren at Tranquillien in the Ghostlands."} end
if not DB[9174] then DB[9174]={id=9174,zoneId=3433,name="Vanquishing Aquantion",level=13,minLevel=9,giver="Geranis Whitemorn",giverType="NPC",giverId=16201,ender="Geranis Whitemorn",enderType="NPC",enderId=16201,poiX=7847,poiY=-7669,wowhead="https://www.wowhead.com/wotlk/quest=9174",image="assets/images/quests/placeholder.png",xpDiff=6,money=1100,desc="That willful elemental ended many lives that fateful day when he revolted against us.  By calling to the lowly murloc to sabotage our rites he subverted our magic and turned it against us.$B$BShow him our thirst for vengeance has not waned!  Take these medallions and lay them at the Altar of Tidal Mastery at the bottom of the lake.  Aquantion shall immediately answer your summons!$B$BBeware, $r!  Without our magic controlling him, his wrath will be unrestrained.  Destroy Aquantion so we may rest!",logDesc="Geranis Whitemorn wants you to swim to the bottom of the lake east of Suncrown Village and use the Bundle of Medallions on the Altar of Tidal Mastery.  Summon and slay the elemental known as Aquantion and return to Geranis."} end
if not DB[9175] then DB[9175]={id=9175,zoneId=3433,name="The Lady's Necklace",level=15,minLevel=15,ender="High Executor Mavren",enderType="NPC",enderId=16252,wowhead="https://www.wowhead.com/wotlk/quest=9175",image="assets/images/quests/placeholder.png",xpDiff=5,money=1400,desc="The necklace shimmers, a remarkable piece of jewelry that doesn't seem to succumb to the gloom that permeates the Ghostlands. Given the inscription, and where you found it, it must be the lost property of Lady Sylvanas Windrunner herself!$B$BPerhaps it would be best to first take it to High Executor Mavren at Tranquillien? He seems to be the highest ranking Forsaken in the area and is sure to know what to do with it.",logDesc="Take The Lady's Necklace to High Executor Mavren at Tranquillien in the Ghostlands."} end
if not DB[9176] then DB[9176]={id=9176,zoneId=3433,name="The Twin Ziggurats",level=17,minLevel=15,giver="Magister Kaendris",giverType="NPC",giverId=16239,ender="Magister Kaendris",enderType="NPC",enderId=16239,rewardNextId=9167,poiX=7192,poiY=-7101,wowhead="https://www.wowhead.com/wotlk/quest=9176",image="assets/images/quests/placeholder.png",xpDiff=7,money=900,desc="According to this journal, Dar'Khan promised the Scourge two powerful elven artifacts: the stone of light and the stone of flame.  These were imbued with the magical energies of the Sunwell and attuned to have warding powers against the Scourge.$B$BThe crystals were to be transported to where the Howling Ziggurat and the Bleeding Ziggurat now stand, in the middle of the Dead Scar.  If they're still held there, we need to recover them.  Their power will be greatly useful in our struggle against the enemy.",logDesc="Travel to the Bleeding Ziggurat and the Howling Ziggurat and recover the Stone of Light and the Stone of Flame.  Return to Magister Kaendris at the Sanctum of the Sun after recovering the items.",choiceRewards={{id=22783,qty=1},{id=22784,qty=1}}} end
if not DB[9177] then DB[9177]={id=9177,zoneId=1497,name="Journey to Undercity",level=15,minLevel=15,wowhead="https://www.wowhead.com/wotlk/quest=9177",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This is quite extraordinary! It appears to be a gift to Lady Sylvanas Windrunner from her sister, Alleria!$B$BYou must take it to her in the Undercity at once! The lady holds court in the Royal Quarter.$B$BTo get there, use the orb of translocation in the Inner Sanctum of Sunfury Spire in Silvermoon City to cross over to the Undercity.  Once there, take the elevator ride down into the city proper. Use your maps if you need help finding the Royal Quarter.",logDesc="Take The Lady's Necklace to Lady Sylvanas Windrunner at the Royal Quarter in Undercity."} end
if not DB[9178] then DB[9178]={id=9178,zoneId=139,name="Craftsman's Writ - Dense Weightstone",level=60,minLevel=55,ender="Packmaster Stonebruiser",enderType="NPC",enderId=16283,wowhead="https://www.wowhead.com/wotlk/quest=9178",image="assets/images/quests/placeholder.png",desc="The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.$B$BWork Order BS-091:$B$B120 Dense Weightstones.$B$BAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.$B$BContract is null and void if tampered with or damaged.$B$B-Dispatch Commander Metz, The Argent Dawn",logDesc="Deliver 120 Dense Weightstones and the Craftsman's Writ - Dense Weightstone - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.",choiceRewards={{id=22524,qty=1},{id=22523,qty=1}}} end
if not DB[9179] then DB[9179]={id=9179,zoneId=139,name="Craftsman's Writ - Imperial Plate Chest",level=60,minLevel=55,ender="Packmaster Stonebruiser",enderType="NPC",enderId=16283,wowhead="https://www.wowhead.com/wotlk/quest=9179",image="assets/images/quests/placeholder.png",desc="The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.$B$BWork Order BS-428:$B$B3 Imperial Plate Chests.$B$BAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.$B$BContract is null and void if tampered with or damaged.$B$B-Dispatch Commander Metz, The Argent Dawn",logDesc="Deliver 3 Imperial Plate Chests and the Craftsman's Writ - Imperial Plate Chest - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.",choiceRewards={{id=22524,qty=1},{id=22523,qty=1}}} end
if not DB[9180] then DB[9180]={id=9180,zoneId=1497,name="Journey to Undercity",level=15,minLevel=15,giver="High Executor Mavren",giverType="NPC",giverId=16252,ender="3",enderType="NPC",enderId=10181,poiX=7553,poiY=-6761,wowhead="https://www.wowhead.com/wotlk/quest=9180",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This is quite extraordinary! It appears to be a gift to Lady Sylvanas Windrunner from her sister, Alleria!$B$BYou must take it to her in the Undercity at once! The lady holds court in the Royal Quarter.$B$BTo get there, use the orb of translocation in the Inner Sanctum of Sunfury Spire in Silvermoon City to cross over to the Undercity.  Once there, take the elevator ride down into the city proper. Use your maps if you need help finding the Royal Quarter.",logDesc="Take The Lady's Necklace to Lady Sylvanas Windrunner at the Royal Quarter in Undercity."} end
if not DB[9181] then DB[9181]={id=9181,zoneId=139,name="Craftsman's Writ - Volcanic Hammer",level=60,minLevel=55,ender="Packmaster Stonebruiser",enderType="NPC",enderId=16283,wowhead="https://www.wowhead.com/wotlk/quest=9181",image="assets/images/quests/placeholder.png",desc="The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.$B$BWork Order BS-697:$B$B3 Volcanic Hammers.$B$BAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.$B$BContract is null and void if tampered with or damaged.$B$B-Dispatch Commander Metz, The Argent Dawn",logDesc="Deliver 3 Volcanic Hammers and the Craftsman's Writ - Volcanic Hammer - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.",choiceRewards={{id=22524,qty=1},{id=22523,qty=1}}} end
