if not DB[9207] then DB[9207]={id=9207,zoneId=3433,name="Underlight Ore Samples",level=14,minLevel=11,giver="Apprentice Shatharia",giverType="NPC",giverId=16293,ender="Magister Quallestis",enderType="NPC",enderId=16291,poiX=7203,poiY=-6321,wowhead="https://www.wowhead.com/wotlk/quest=9207",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="I was sent here from the Sanctum of the Sun to collect some ore samples, but the gnolls have overrun the place! It's going to be my head on a platter if I don't get those samples to the magister soon. Maybe you could help, $c?$B$BYou can find the ore in the tin and copper veins here, and the gnolls are carrying it around, too. When you have enough, take it to Magister Quallestis at the Sanctum of the Sun directly to the east. Go across the Dead Scar and you'll find the sanctum just south of Sungraze Peak.",logDesc="Collect 6 Underlight Ore and deliver them to Magister Quallestis at the Sanctum of the Sun in the Ghostlands."} end
if not DB[9208] then DB[9208]={id=9208,zoneId=1977,name="The Savage Guard - Arcanum of Protection",level=60,minLevel=58,giver="Zanza the Restless",giverType="NPC",giverId=15042,ender="Zanza the Restless",enderType="NPC",enderId=15042,poiX=-12013,poiY=-1806,wowhead="https://www.wowhead.com/wotlk/quest=9208",image="assets/images/quests/placeholder.png",desc="Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.$B$BBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.$B",logDesc="Zanza the Restless in Zul'Gurub wants an Arcanum of Protection.",rewards={{id=22635,qty=1}}} end
if not DB[9209] then DB[9209]={id=9209,zoneId=1977,name="The Savage Guard - Arcanum of Rapidity",level=60,minLevel=58,giver="Zanza the Restless",giverType="NPC",giverId=15042,ender="Zanza the Restless",enderType="NPC",enderId=15042,poiX=-12013,poiY=-1806,wowhead="https://www.wowhead.com/wotlk/quest=9209",image="assets/images/quests/placeholder.png",desc="Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.$B$BBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.$B",logDesc="Zanza the Restless in Zul'Gurub wants an Arcanum of Rapidity.",rewards={{id=22635,qty=1}}} end
if not DB[9210] then DB[9210]={id=9210,zoneId=1977,name="The Savage Guard - Arcanum of Focus",level=60,minLevel=58,giver="Zanza the Restless",giverType="NPC",giverId=15042,ender="Zanza the Restless",enderType="NPC",enderId=15042,poiX=-12013,poiY=-1806,wowhead="https://www.wowhead.com/wotlk/quest=9210",image="assets/images/quests/placeholder.png",desc="Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.$B$BBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.$B",logDesc="Zanza the Restless in Zul'Gurub wants an Arcanum of Focus.",rewards={{id=22635,qty=1}}} end
if not DB[9211] then DB[9211]={id=9211,zoneId=139,name="The Ice Guard",level=60,minLevel=60,giver="Mataus the Wrathcaster",giverType="NPC",giverId=16133,ender="Mataus the Wrathcaster",enderType="NPC",enderId=16133,poiX=2297,poiY=-5336,wowhead="https://www.wowhead.com/wotlk/quest=9211",image="assets/images/quests/placeholder.png",desc="Ah, the Ice Guard. It is a thin sheen of protective magic that covers certain pieces of equipment. Those that do battle with creatures of frost and ice will gain increased protection from their attacks by using the Ice Guard.$B$BAs with all things the Wrathcaster creates, there is a price - a price that I will not lower, regardless of how much you whimper. Interested?",logDesc="Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.",rewards={{id=22636,qty=1}}} end
if not DB[9212] then DB[9212]={id=9212,zoneId=3433,name="Escape from the Catacombs",level=17,minLevel=14,giver="Ranger Lilatha",giverType="NPC",giverId=16295,ender="Captain Helios",enderType="NPC",enderId=16220,poiX=7545,poiY=-7360,wowhead="https://www.wowhead.com/wotlk/quest=9212",image="assets/images/quests/placeholder.png",xpDiff=5,money=900,desc="These trolls ambushed me and have been keeping me in this cage.  I think they're planning to sacrifice me!  Help me get out of here!$B$BThe lock on the cage isn't that complex... I just can't get to it from this side.  Please escort me back to the Farstrider Enclave.  I'm sure Captain Helios will reward you, and you'll have my undying gratitude!",logDesc="Escort Ranger Lilatha to Captain Helios at Farstrider Enclave in the Ghostlands.",choiceRewards={{id=23412,qty=1},{id=23413,qty=1},{id=23414,qty=1}}} end
if not DB[9213] then DB[9213]={id=9213,zoneId=139,name="The Shadow Guard",level=60,minLevel=60,giver="Mataus the Wrathcaster",giverType="NPC",giverId=16133,ender="Mataus the Wrathcaster",enderType="NPC",enderId=16133,poiX=2297,poiY=-5336,wowhead="https://www.wowhead.com/wotlk/quest=9213",image="assets/images/quests/placeholder.png",desc="A creation of genius! Much like the Ice Guard, the Shadow Guard employs a thin sheen of protective magic that covers certain pieces of equipment. And like the Ice Guard, the Shadow Guard is going to cost you a good amount of money.$B$B<Mataus holds his hand out and rubs his fingers together.>$B$BInterested?",logDesc="Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.",rewards={{id=22638,qty=1}}} end
if not DB[9214] then DB[9214]={id=9214,zoneId=3433,name="Shadowpine Weaponry",level=18,minLevel=15,giver="Captain Helios",giverType="NPC",giverId=16220,ender="Captain Helios",enderType="NPC",enderId=16220,poiX=7615,poiY=-7671,wowhead="https://www.wowhead.com/wotlk/quest=9214",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="$C, I want you to kill as many Shadowpine trolls as you can. We need their numbers greatly reduced before we can shift our attention toward Deatholme. And while you're at it, we might as well kill two birds with one stone, so bring me back a load of their weapons. Better that they not go to waste, and we can use them in the fight against the Scourge.$B$BHit their camps hard to the east and the south at Zeb'Tela and Zeb'Nowa.",logDesc="Collect 3 Headhunter Axes, 3 Shadowcaster Maces, 3 Catlord Claws and 3 Hexxer Staves. Return them to Captain Helios at Farstrider Enclave in the Ghostlands."} end
if not DB[9215] then DB[9215]={id=9215,zoneId=3433,name="Bring Me Kel'gash's Head!",level=20,minLevel=9,ender="Captain Helios",enderType="NPC",enderId=16220,wowhead="https://www.wowhead.com/wotlk/quest=9215",image="assets/images/quests/placeholder.png",xpDiff=6,money=2500,desc="WANTED: Bring the head of Kel'gash the Wicked, chieftain of the Shadowpine trolls, to Captain Helios. No questions asked. Kel'gash is known to dwell somewhere to the south in Zeb'Nowa.$B$B$B$BREWARD: Yes, but no advances!",logDesc="Return the Head of Kel'gash the Wicked to Captain Helios at the Farstrider Enclave in the Ghostlands.",choiceRewards={{id=23409,qty=1},{id=23410,qty=1},{id=23411,qty=1}}} end
if not DB[9216] then DB[9216]={id=9216,zoneId=3433,name="Rotting Hearts",level=16,minLevel=15,giver="Magistrix Aminel",giverType="NPC",giverId=16205,ender="Magistrix Aminel",enderType="NPC",enderId=16205,poiX=7578,poiY=-6898,wowhead="https://www.wowhead.com/wotlk/quest=9216",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I hear the Amani trolls eat their enemies' hearts to steal their strength.  They might just be on to something, $N.  With the proper treatment, the hearts of the unliving can produce potent elixirs.$B$BHunt down the zombies that roam the Dead Scar and bring me their hearts.  I'll show you the kind of enhancement we can perform to your physical prowess against the undead.",logDesc="Bring back 10 Rotting Hearts to Magistrix Aminel in Tranquillien.",rewards={{id=22779,qty=1}}} end
if not DB[9217] then DB[9217]={id=9217,zoneId=3433,name="More Rotting Hearts",level=16,minLevel=15,giver="Magistrix Aminel",giverType="NPC",giverId=16205,ender="Magistrix Aminel",enderType="NPC",enderId=16205,poiX=7578,poiY=-6898,wowhead="https://www.wowhead.com/wotlk/quest=9217",image="assets/images/quests/placeholder.png",rewards={{id=22779,qty=1}}} end
if not DB[9218] then DB[9218]={id=9218,zoneId=3433,name="Spinal Dust",level=18,minLevel=15,giver="Magistrix Aminel",giverType="NPC",giverId=16205,ender="Magistrix Aminel",enderType="NPC",enderId=16205,poiX=7578,poiY=-6898,wowhead="https://www.wowhead.com/wotlk/quest=9218",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The dark energy that flows through the bodies of reanimated skeletons tends to accumulate primarily in their spine.  I've discovered a method of instilling this energy into a potion that boosts our magical abilities against the undead.$B$BBring me some spinal dust and I'll be glad to provide you with a sample.  You'll find an ample number of skeletons wandering the Dead Scar, west of here.",logDesc="Bring back 10 Spinal Dusts to Magistrix Aminel in Tranquillien.",rewards={{id=22778,qty=1}}} end
if not DB[9219] then DB[9219]={id=9219,zoneId=3433,name="More Spinal Dust",level=18,minLevel=15,giver="Magistrix Aminel",giverType="NPC",giverId=16205,ender="Magistrix Aminel",enderType="NPC",enderId=16205,poiX=7578,poiY=-6898,wowhead="https://www.wowhead.com/wotlk/quest=9219",image="assets/images/quests/placeholder.png",rewards={{id=22778,qty=1}}} end
if not DB[9220] then DB[9220]={id=9220,zoneId=3433,name="War on Deatholme",level=20,minLevel=17,giver="Magister Idonis",giverType="NPC",giverId=16204,ender="Magister Idonis",enderType="NPC",enderId=16204,rewardNextId=9170,poiX=7199,poiY=-7094,wowhead="https://www.wowhead.com/wotlk/quest=9220",image="assets/images/quests/placeholder.png",xpDiff=6,money=2500,desc="If you seek to aid our cause there is no better place to start than here and no better time to do it than now.$B$BBy rebuilding the Sanctum of the Sun we've raised a banner of defiance in front of our enemy's seat of power: Deatholme.$B$BGo forth and fight the hordes of undead that inhabit the vile Scourge fortress.",logDesc="Slay 5 Eyes of Dar'khan, 6 Nerubis Centurions and 6 Wailers in Deatholme and return to Magister Idonis at the Sanctum of the Sun in the Ghostlands."} end
if not DB[9221] then DB[9221]={id=9221,zoneId=139,name="Superior Armaments of Battle - Friend of the Dawn",level=60,minLevel=55,giver="Quartermaster Miranda Breechlock",giverType="NPC",giverId=11536,ender="Quartermaster Miranda Breechlock",enderType="NPC",enderId=11536,poiX=2251,poiY=-5345,wowhead="https://www.wowhead.com/wotlk/quest=9221",image="assets/images/quests/placeholder.png",desc="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?$B$BI must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.",logDesc="For 30 Insignias of the Dawn and 30 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.$B",choiceRewards={{id=22681,qty=1},{id=22680,qty=1},{id=22688,qty=1},{id=22679,qty=1},{id=22690,qty=1},{id=22689,qty=1}}} end
