if not DB[9223] then DB[9223]={id=9223,zoneId=139,name="Superior Armaments of Battle - Honored Amongst the Dawn",level=60,minLevel=55,giver="Quartermaster Miranda Breechlock",giverType="NPC",giverId=11536,ender="Quartermaster Miranda Breechlock",enderType="NPC",enderId=11536,poiX=2251,poiY=-5345,wowhead="https://www.wowhead.com/wotlk/quest=9223",image="assets/images/quests/placeholder.png",desc="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?$B$BI must warn you; purchases made at honored reputation with the Dawn come with a fairly prohibitive surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.",logDesc="For 20 Insignias of the Dawn and 20 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.",choiceRewards={{id=22681,qty=1},{id=22680,qty=1},{id=22688,qty=1},{id=22679,qty=1},{id=22690,qty=1},{id=22689,qty=1}}} end
