if not DB[9225] then DB[9225]={id=9225,zoneId=139,name="Epic Armaments of Battle - Revered Amongst the Dawn",level=60,minLevel=55,giver="Quartermaster Miranda Breechlock",giverType="NPC",giverId=11536,ender="Quartermaster Miranda Breechlock",enderType="NPC",enderId=11536,poiX=2251,poiY=-5345,wowhead="https://www.wowhead.com/wotlk/quest=9225",image="assets/images/quests/placeholder.png",desc="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?$B$BI must warn you; epic purchases made at revered reputation with the Dawn are still quite expensive. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.",logDesc="For 45 Insignias of the Dawn and 45 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.",choiceRewards={{id=22657,qty=1},{id=22667,qty=1},{id=22668,qty=1},{id=22659,qty=1},{id=22678,qty=1},{id=22656,qty=1}}} end
