if not DB[9228] then DB[9228]={id=9228,zoneId=139,name="Epic Armaments of Battle - Exalted Amongst the Dawn",level=60,minLevel=55,giver="Quartermaster Miranda Breechlock",giverType="NPC",giverId=11536,ender="Quartermaster Miranda Breechlock",enderType="NPC",enderId=11536,poiX=2251,poiY=-5345,wowhead="https://www.wowhead.com/wotlk/quest=9228",image="assets/images/quests/placeholder.png",desc="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?$B$BThose exalted amongst the Dawn receive our greatest discounts! I encourage you to make a purchase.",logDesc="For 27 Insignias of the Dawn and 27 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.",choiceRewards={{id=22657,qty=1},{id=22667,qty=1},{id=22668,qty=1},{id=22659,qty=1},{id=22678,qty=1},{id=22656,qty=1}}} end
if not DB[9229] then DB[9229]={id=9229,zoneId=3456,name="The Fate of Ramaladni",level=60,minLevel=60,rewardNextId=9230,wowhead="https://www.wowhead.com/wotlk/quest=9229",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Ramaladni was a warrior of the Brotherhood - a pupil of Highlord Mograine before the Dawn even existed! When news of Mograine's death reached him, hatred and anger took over.$B$BUnderstand this, $N, when rage and retribution take the reins, a man ceases to be a man. The man personifies the emotions that control him instead. And so it would be that Ramaladni, the spirit of retribution, would enter Naxxramas to exact vengeance... and never return.$B$BEnter Naxxramas and find what became of Ramaladni.",logDesc="Enter Naxxramas and uncover the Fate of Ramaladni."} end
if not DB[9230] then DB[9230]={id=9230,zoneId=3456,name="Ramaladni's Icy Grasp",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=9230",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Fixing this band may prove to be quite challenging, $N. You see, it was made from the very runes that form inside Scourge structures - like Naxxramas. Additional materials are also required but your main concern should be getting those frozen runes. Bring me what I need and I will restore the ring to its former glory.",logDesc="Korfax at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 1 Frozen Rune, 1 Blue Sapphire and 1 Arcanite Bar.$B",rewards={{id=22707,qty=1}}} end
if not DB[9231] then DB[9231]={id=9231,zoneId=0,name="reuse",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9231",image="assets/images/quests/placeholder.png",rewards={{id=22486,qty=1}}} end
if not DB[9232] then DB[9232]={id=9232,zoneId=3456,name="The Only Song I Know...",level=60,minLevel=60,ender="Craftsman Wilhelm",enderType="NPC",enderId=16376,wowhead="https://www.wowhead.com/wotlk/quest=9232",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?$B$B<Wilhelm sighs.>$B$BBah, what choice do I got? You're the best I can do; I may as well help you.$B$BOmarion left me with one recipe. It's the only song I know... I can make a few variations of these pants; you just gotta supply the materials.",logDesc="Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires and 30 gold pieces.",choiceRewards={{id=22700,qty=1},{id=22699,qty=1},{id=22702,qty=1},{id=22701,qty=1}}} end
if not DB[9233] then DB[9233]={id=9233,zoneId=3456,name="Omarion's Handbook",level=60,minLevel=60,ender="Craftsman Wilhelm",enderType="NPC",enderId=16376,wowhead="https://www.wowhead.com/wotlk/quest=9233",image="assets/images/quests/placeholder.png",desc="Wilhelm,$B$BIf you are reading this, I have perished - finally. I want you to know that my dying thoughts revolved around you and your ineptitude when it comes to tradeskills. Unfortunately, the bearer of this handbook is in even worse shape than you in regards to crafting.$B$BAbout the book: These are the rest of my recipes. Make the bearer of this book whatever they request. I'm sure you will charge a hefty fee for your services because you are, after all, a crook.$B$BIn Disdain,$B$BOmarion",logDesc="Take Omarion's Handbook to Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands.$B"} end
if not DB[9234] then DB[9234]={id=9234,zoneId=3456,name="Icebane Gauntlets",level=60,minLevel=60,giver="Craftsman Wilhelm",giverType="NPC",giverId=16376,ender="Craftsman Wilhelm",enderType="NPC",enderId=16376,poiX=2261,poiY=-5321,wowhead="https://www.wowhead.com/wotlk/quest=9234",image="assets/images/quests/placeholder.png",desc="Thanks to you and Omarion, may he rest in peace, I am now able to create Icebane gauntlets. All you need to do is bring me the materials and pay a small crafting fee.",logDesc="Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essences of Water and 200 gold.",rewards={{id=22670,qty=1}}} end
if not DB[9235] then DB[9235]={id=9235,zoneId=3456,name="Icebane Bracers",level=60,minLevel=60,giver="Craftsman Wilhelm",giverType="NPC",giverId=16376,ender="Craftsman Wilhelm",enderType="NPC",enderId=16376,poiX=2261,poiY=-5321,wowhead="https://www.wowhead.com/wotlk/quest=9235",image="assets/images/quests/placeholder.png",desc="Thanks to you and Omarion (May he rest in peace), I am now able to create Icebane bracers. All you need to do is bring me the materials and pay a small crafting fee.",logDesc="Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 4 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essence of Water and 200 gold.",rewards={{id=22671,qty=1}}} end
if not DB[9236] then DB[9236]={id=9236,zoneId=3456,name="Icebane Breastplate",level=60,minLevel=60,giver="Craftsman Wilhelm",giverType="NPC",giverId=16376,ender="Craftsman Wilhelm",enderType="NPC",enderId=16376,poiX=2261,poiY=-5321,wowhead="https://www.wowhead.com/wotlk/quest=9236",image="assets/images/quests/placeholder.png",desc="Thanks to you and Omarion (May he rest in peace), I am now able to create an Icebane breastplate. All you need to do is bring me the materials and pay a small crafting fee.",logDesc="Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 16 Thorium Bars, 2 Arcanite Bars, 4 Essence of Water and 300 gold. You will also need to be of Exalted reputation with the Argent Dawn.$B",rewards={{id=22669,qty=1}}} end
