if not DB[9247] then DB[9247]={id=9247,zoneId=-368,name="The Keeper's Call",level=-1,minLevel=1,ender="Keeper of the Rolls",enderType="NPC",enderId=16281,wowhead="https://www.wowhead.com/wotlk/quest=9247",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N,$B$BIn times past you have served the interests of the Argent Dawn, always to the best of your abilities. Now, once again, we sound the clarion call in our time of greatest need.$B$B$N, please report to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands if you are willing to aid us once more.",logDesc="Take the Letter from the Keeper of the Rolls to him at Light's Hope Chapel in the Eastern Plaguelands.",choiceRewards={{id=23123,qty=1},{id=23122,qty=1}}} end
if not DB[9248] then DB[9248]={id=9248,zoneId=1377,name="A Humble Offering",level=60,minLevel=58,giver="Aurel Goldleaf",giverType="NPC",giverId=15282,ender="Aurel Goldleaf",enderType="NPC",enderId=15282,poiX=-6845,poiY=728,wowhead="https://www.wowhead.com/wotlk/quest=9248",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Ishnu-alah, $r. Show me proof of the demise of a Lord of the Abyssal Council and I shall reward you with an item that should aid you in your battles against the Qiraji.",logDesc="Aurel Goldleaf at Cenarion Hold in Silithus wants you to bring her 1 Abyssal Scepter. You must also be Honored with the Cenarion Circle.",rewards={{id=22725,qty=1}}} end
