if not DB[9250] then DB[9250]={id=9250,zoneId=-344,name="Frame of Atiesh",level=60,minLevel=60,ender="3",enderType="NPC",enderId=15192,rewardNextId=9251,wowhead="https://www.wowhead.com/wotlk/quest=9250",image="assets/images/quests/placeholder.png",xpDiff=5,desc="With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil.$B$BFind someone that can assist you in locating the remaining pieces and exorcising the evil from the staff.",logDesc="Find someone that will help you in recovering the last two pieces of the staff and ridding it of evil."} end
if not DB[9251] then DB[9251]={id=9251,zoneId=-344,name="Atiesh, the Befouled Greatstaff",level=60,minLevel=60,giver="3",giverType="NPC",giverId=15192,ender="3",enderType="NPC",enderId=15192,poiX=-8240,poiY=-4649,wowhead="https://www.wowhead.com/wotlk/quest=9251",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, $N. I only do as I must.$B$BKel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek.$B$BAs for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains.$B$BShould you succeed in recovering the pieces, return them to me.",logDesc="Anachronos at the Caverns of Time in Tanaris wants the Staff Head of Atiesh and the Base of Atiesh."} end
if not DB[9252] then DB[9252]={id=9252,zoneId=3430,name="Defending Fairbreeze Village",level=9,minLevel=7,giver="Ranger Sareyn",giverType="NPC",giverId=15942,ender="Ranger Sareyn",enderType="NPC",enderId=15942,poiX=8685,poiY=-6799,wowhead="https://www.wowhead.com/wotlk/quest=9252",image="assets/images/quests/placeholder.png",xpDiff=5,money=300,desc="We've experienced a marked increase in Scourge attacks, $N.  Our defenses are barely holding and there's no sign of reinforcements from Silvermoon City.  Lend us a hand in defending the village by thinning the numbers of the undead roaming the Dead Scar nearby.",logDesc="Slay 4 Rotlimb Marauders and 4 Darkwraiths and return to Ranger Sareyn at Fairbreeze Village in Eversong Woods."} end
if not DB[9253] then DB[9253]={id=9253,zoneId=3430,name="Runewarden Deryan",level=10,minLevel=8,giver="Ranger Sareyn",giverType="NPC",giverId=15942,ender="Runewarden Deryan",enderType="NPC",enderId=16362,rewardNextId=8490,poiX=8685,poiY=-6799,wowhead="https://www.wowhead.com/wotlk/quest=9253",image="assets/images/quests/placeholder.png",xpDiff=2,money=85,desc="This increase in Scourge attacks leads me to believe there might be a malfunction at one of the protective runestones at the border with the Ghostlands.$B$BWe used these ancient stones to protect us against the undead.  Most of them were destroyed or lost after the attack on the Sunwell. $B$BFollow the road south, towards the Ghostlands, and look to the west for a small path.  You will find Runewarden Deryan by the runestone nearby; he will know whether anything's wrong.",logDesc="Speak to Runewarden Deryan in Eversong Woods, near the border with the Ghostlands."} end
if not DB[9254] then DB[9254]={id=9254,zoneId=3430,name="The Wayward Apprentice",level=9,minLevel=7,giver="Magistrix Landra Dawnstrider",giverType="NPC",giverId=16210,ender="Apprentice Mirveda",enderType="NPC",enderId=15402,rewardNextId=8487,poiX=8718,poiY=-6656,wowhead="https://www.wowhead.com/wotlk/quest=9254",image="assets/images/quests/placeholder.png",xpDiff=3,money=70,desc="Thank you for your help, $N.  While I get things back in order here, I'd like to ask you for a favor.  One of my former apprentices embarked in a very dangerous line of research.  She journeyed to the East Sanctum, in the middle of the Dead Scar.$B$BI worry for her well-being.  See if you can find her and convince her to return to her senses.",logDesc="Speak to Apprentice Mirveda at the East Sanctum in Eversong Woods."} end
if not DB[9255] then DB[9255]={id=9255,zoneId=3430,name="Research Notes",level=9,minLevel=7,giver="Apprentice Mirveda",giverType="NPC",giverId=15402,ender="Magistrix Landra Dawnstrider",enderType="NPC",enderId=16210,poiX=8711,poiY=-7161,wowhead="https://www.wowhead.com/wotlk/quest=9255",image="assets/images/quests/placeholder.png",xpDiff=3,money=70,desc="As discouraging as my research results are, they still contain valuable data.  I must have a magister review my work before it is taken seriously.  Please, take these notes to Magistrix Landra Dawnstrider at Fairbreeze Village, west of here.",logDesc="Deliver the Research Notes to Magistrix Landra Dawnstrider at Fairbreeze Village in Eversong Woods."} end
if not DB[9256] then DB[9256]={id=9256,zoneId=3430,name="Fairbreeze Village",level=7,minLevel=6,giver="Aeldon Sunbrand",giverType="NPC",giverId=15403,ender="Ranger Degolien",enderType="NPC",enderId=15939,rewardNextId=8892,poiX=9531,poiY=-6860,wowhead="https://www.wowhead.com/wotlk/quest=9256",image="assets/images/quests/placeholder.png",xpDiff=3,money=85,desc="I have another task for you, $N.  Ranger Degolien was sent to Fairbreeze Village to find out more about a Wretched attack on a nearby shipyard.  He has requested reinforcements which we cannot yet provide.  Seek him out and grant him whatever aid you can.$B$BFairbreeze Village can be reached by following the road out of Falconwing Square all the way towards the south.  Good luck, $N.",logDesc="Speak to Ranger Degolien at Fairbreeze Village in Eversong Woods."} end
if not DB[9257] then DB[9257]={id=9257,zoneId=-344,name="Atiesh, Greatstaff of the Guardian",level=60,minLevel=60,giver="3",giverType="NPC",giverId=15192,ender="3",enderType="NPC",enderId=15192,poiX=-8240,poiY=-4649,wowhead="https://www.wowhead.com/wotlk/quest=9257",image="assets/images/quests/placeholder.png",xpDiff=7,desc="This final task will be the most difficult of all, $N. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.$B$BTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.",logDesc="Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.",rewards={{id=22631,qty=1}}} end
if not DB[9258] then DB[9258]={id=9258,zoneId=3430,name="The Scorched Grove",level=10,minLevel=8,giver="Ardeyn Riverwind",giverType="NPC",giverId=16397,ender="Larianna Riverwind",enderType="NPC",enderId=15398,rewardNextId=8473,poiX=8704,poiY=-6634,wowhead="https://www.wowhead.com/wotlk/quest=9258",image="assets/images/quests/placeholder.png",xpDiff=2,money=85,desc="A foul taint in the soil precedes the expansion of the Scourge into a new area.  The protective runestones along the border with the Ghostlands have warded the land against this taint in the past.$B$BThe westernmost runestone was destroyed during a Scourge attack, which forced us to burn the ground around it to prevent the taint from spreading.$B$BMy sister, Larianna Riverwind, watches over the Scorched Grove.  Go find her; she might have some work for you.",logDesc="Find Larianna Riverwind near the Scorched Grove in the southwest of Eversong Woods."} end
if not DB[9259] then DB[9259]={id=9259,zoneId=33,name="Traitor to the Bloodsail",level=-1,minLevel=30,giver="Bloodsail Traitor",giverType="NPC",giverId=16399,ender="Bloodsail Traitor",enderType="NPC",enderId=16399,poiX=-14184,poiY=193,wowhead="https://www.wowhead.com/wotlk/quest=9259",image="assets/images/quests/placeholder.png"} end
if not DB[9260] then DB[9260]={id=9260,zoneId=-368,name="Investigate the Scourge of Stormwind",level=6,minLevel=1,giver="Lieutenant Orrin",giverType="NPC",giverId=16478,ender="Lieutenant Orrin",enderType="NPC",enderId=16478,wowhead="https://www.wowhead.com/wotlk/quest=9260",image="assets/images/quests/placeholder.png",xpDiff=4,money=100,desc="The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Stormwind from these accursed invaders? $b $bThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!",logDesc="Collect three Dim Necrotic Stones from the Scourge outside Stormwind and investigate the glowing runic circles near their encampment."} end
if not DB[9261] then DB[9261]={id=9261,zoneId=-368,name="Investigate the Scourge of Ironforge",level=10,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9261",image="assets/images/quests/placeholder.png",xpDiff=4,money=250,desc="The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Ironforge from these accursed invaders? $b $bThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!",logDesc="Collect three Dim Necrotic Stones from the Scourge outside Ironforge and investigate the glowing runic circles near their encampment."} end
