if not DB[9269] then DB[9269]={id=9269,zoneId=-344,name="Atiesh, Greatstaff of the Guardian",level=60,minLevel=60,giver="3",giverType="NPC",giverId=15192,ender="3",enderType="NPC",enderId=15192,poiX=-8240,poiY=-4649,wowhead="https://www.wowhead.com/wotlk/quest=9269",image="assets/images/quests/placeholder.png",xpDiff=7,desc="This final task will be the most difficult of all, $N. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.$B$BTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.",logDesc="Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.",rewards={{id=22632,qty=1}}} end
if not DB[9270] then DB[9270]={id=9270,zoneId=-344,name="Atiesh, Greatstaff of the Guardian",level=60,minLevel=60,giver="3",giverType="NPC",giverId=15192,ender="3",enderType="NPC",enderId=15192,poiX=-8240,poiY=-4649,wowhead="https://www.wowhead.com/wotlk/quest=9270",image="assets/images/quests/placeholder.png",xpDiff=7,desc="This final task will be the most difficult of all, $N. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.$B$BTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.",logDesc="Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.",rewards={{id=22589,qty=1}}} end
if not DB[9271] then DB[9271]={id=9271,zoneId=-344,name="Atiesh, Greatstaff of the Guardian",level=60,minLevel=60,giver="3",giverType="NPC",giverId=15192,ender="3",enderType="NPC",enderId=15192,poiX=-8240,poiY=-4649,wowhead="https://www.wowhead.com/wotlk/quest=9271",image="assets/images/quests/placeholder.png",xpDiff=7,desc="This final task will be the most difficult of all, $N. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.$B$BTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.",logDesc="Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.",rewards={{id=22630,qty=1}}} end
