if not DB[9274] then DB[9274]={id=9274,zoneId=3433,name="Spirits of the Drowned",level=12,minLevel=9,giver="Ranger Krenn'an",giverType="NPC",giverId=16462,ender="Ranger Krenn'an",enderType="NPC",enderId=16462,poiX=7612,poiY=-7666,wowhead="https://www.wowhead.com/wotlk/quest=9274",image="assets/images/quests/placeholder.png",xpDiff=5,money=500,desc="The lake to the north has been haunted by the ghosts of my ancestors for as long as I can remember, $N.  The poor souls were victims of a tragic incident in which scores of them drowned at the bottom of the lake.$B$BThe details of the event are mostly forgotten, but their haunting cries serve as a constant reminder of their curse.$B$BIf you're up to the task, I want you to go to the lake and put an end to their suffering, $N.  You will have my gratitude as well as theirs... I'm sure.",logDesc="Ranger Krenn'an, at the Farstrider Enclave in the Ghostlands, wants you to kill 8 Vengeful Apparitions and 8 Ravening Apparitions in the nearby lake."} end
if not DB[9275] then DB[9275]={id=9275,zoneId=3433,name="A Little Dash of Seasoning",level=19,minLevel=16,giver="Apothecary Venustus",giverType="NPC",giverId=16464,ender="Apothecary Venustus",enderType="NPC",enderId=16464,poiX=7572,poiY=-7680,wowhead="https://www.wowhead.com/wotlk/quest=9275",image="assets/images/quests/placeholder.png",xpDiff=5,money=1100,desc="I'm on loan to the Farstriders in an attempt to help with their troll difficulties. I believe that I have a solution to their problem.$B$BAt my disposal are a number of potent poisons. The trolls, as you know, are living creatures and therefore must eat. If we combine my poison with their food... well, I'm sure that the results will be entertaining!$B$BCare to help rid us of the Shadowpine trolls at Zeb'Nowa to the south? The camp straddles both the north and south sides of the road to Zul'Aman.",logDesc="Poison the Troll foodstuff at the camps in Zeb'Nowa and then return to Apothecary Venustus at the Farstrider Enclave in the Ghostlands."} end
if not DB[9276] then DB[9276]={id=9276,zoneId=3433,name="Attack on Zeb'Tela",level=18,minLevel=15,giver="Farstrider Solanna",giverType="NPC",giverId=16463,ender="Farstrider Solanna",enderType="NPC",enderId=16463,rewardNextId=9277,poiX=7579,poiY=-7670,wowhead="https://www.wowhead.com/wotlk/quest=9276",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="Our resources are spread pretty thin here, $c, so your help is going to be invaluable.  The captain has tasked me with overseeing the harassment of the local Shadowpine troll camps. We have a policy of keeping them off balance until the day when we can launch a brutal offensive to wipe them out.$B$BUntil then, we need all of the volunteers that we can get so that those Shadowpine troll numbers are decreased.$B$BThink you could head east to Zeb'Tela and hurt them a little?",logDesc="Kill 8 Shadowpine Shadowcasters and 8 Shadowpine Headhunters, and return to Farstrider Solanna at Farstrider Enclave in the Ghostlands."} end
if not DB[9277] then DB[9277]={id=9277,zoneId=3433,name="Assault on Zeb'Nowa",level=19,minLevel=15,giver="Farstrider Solanna",giverType="NPC",giverId=16463,ender="Farstrider Solanna",enderType="NPC",enderId=16463,poiX=7579,poiY=-7670,wowhead="https://www.wowhead.com/wotlk/quest=9277",image="assets/images/quests/placeholder.png",xpDiff=5,money=1100,desc="Time for something a little more challenging. Zeb'Nowa, to the south, is where the more powerful Shadowpine trolls make their home. In our continuing effort to keep the troll numbers to a minimum I'm dispatching you to go down there and assail them by whatever means you have at your disposal.$B$BWhat do you say, $N? Ready to deal with some more trolls?",logDesc="Kill 10 Shadowpine Catlords and 10 Shadowpine Hexxers, and return to Farstrider Solanna at the Farstrider Enclave in the Ghostlands.",choiceRewards={{id=23406,qty=1},{id=23407,qty=1},{id=23408,qty=1}}} end
if not DB[9278] then DB[9278]={id=9278,zoneId=3526,name="Welcome!",level=1,minLevel=1,ender="Jaeleil",enderType="NPC",enderId=16476,wowhead="https://www.wowhead.com/wotlk/quest=9278",image="assets/images/quests/placeholder.png",desc="Welcome to the World of Warcraft!$B$BAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Jaeleil in Azure Watch.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.$B$BThanks again, and enjoy your stay in the World of Warcraft!$B",logDesc="Bring the Azure Watch Gift Voucher to Jaeleil in Azure Watch.",choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}} end
if not DB[9279] then DB[9279]={id=9279,zoneId=3526,name="You Survived!",level=1,minLevel=1,giver="Megelon",giverType="NPC",giverId=16475,ender="3",enderType="NPC",enderId=16477,rewardNextId=9280,poiX=-3962,poiY=-13927,wowhead="https://www.wowhead.com/wotlk/quest=9279",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Nevermind my injuries, $g brother : sister;. It's a miracle that any of us are alive!$b$bIt didn't look like you'd pull through; you've been in suspension for weeks.$B$BSomething happened and the Exodar crashed. Many have died.$B$BBut I'm relieved that you are alive, $N. With you leading our efforts, I'm sure we'll get to safety soon! Proenitus asked me to send you to him when you awoke. He's waiting for you at the bottom of the hill. Just follow the path southwest.",logDesc="Speak with Proenitus at the Crash Site in Ammen Vale."} end
if not DB[9280] then DB[9280]={id=9280,zoneId=3526,name="Replenishing the Healing Crystals",level=1,minLevel=1,giver="3",giverType="NPC",giverId=16477,ender="3",enderType="NPC",enderId=16477,rewardNextId=9409,poiX=-4039,poiY=-13774,wowhead="https://www.wowhead.com/wotlk/quest=9280",image="assets/images/quests/placeholder.png",xpDiff=5,money=15,desc="Our immediate concern is the depleted state of our healing crystals.  We must replenish them quickly!$B$BUnfortunately, the only way to do this at this point is to extract the blood from the local vale moths.  Their blood will make for a suitable substitute.$B$BThe moths can be found in many places around the vale, but they are mostly concentrated in the northwest.",logDesc="Acquire 8 Vials of Moth Blood from the nearby Vale Moths and give them to Proenitus at the Crash Site in Ammen Vale.",choiceRewards={{id=24129,qty=1},{id=24131,qty=1},{id=24130,qty=1}}} end
if not DB[9281] then DB[9281]={id=9281,zoneId=3433,name="Clearing the Way",level=18,minLevel=15,giver="Apprentice Vor'el",giverType="NPC",giverId=16480,ender="Apprentice Vor'el",enderType="NPC",enderId=16480,poiX=7025,poiY=-6815,wowhead="https://www.wowhead.com/wotlk/quest=9281",image="assets/images/quests/placeholder.png",xpDiff=5,money=2000,desc="Magister Kaendris sent me down here to clear the area of any hostile wildlife.  Once this area is secured, the magisters plan to turn it into some sort of advance outpost against the Scourge.$B$BNow if there's one thing I've learned as an apprentice it's to delegate responsibility - especially in matters that endanger one's life!$B$BIf you're interested, I'll pay you well to kill the greater spindlewebs and ghostclaw ravagers to the west and south of here.",logDesc="Apprentice Vor'el at Andilien Estate in the Ghostlands wants you to slay 10 Greater Spindlewebs and 10 Ghostclaw Ravagers."} end
if not DB[9282] then DB[9282]={id=9282,zoneId=3433,name="The Farstrider Enclave",level=16,minLevel=15,giver="Magister Kaendris",giverType="NPC",giverId=16239,ender="Ranger Vynna",enderType="NPC",enderId=16203,rewardNextId=9161,poiX=7192,poiY=-7101,wowhead="https://www.wowhead.com/wotlk/quest=9282",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Magisters and Farstriders may not see eye to eye all the time, $N.  When it comes to Dar'Khan, however, we're all in agreement that a way must be found to defeat him and his legions.$B$BRanger Vynna, at the Farstrider Enclave northeast of here, has come across important information regarding our enemy.  Speak to her and see if you can be of assistance.  ",logDesc="Magister Kaendris, at the Sanctum of the Sun, wants you to talk to Ranger Vynna at the Farstrider Enclave in the Ghostlands."} end
if not DB[9283] then DB[9283]={id=9283,zoneId=3526,name="Rescue the Survivors!",level=2,minLevel=1,giver="Zalduun",giverType="NPC",giverId=16502,ender="Zalduun",enderType="NPC",enderId=16502,poiX=-4121,poiY=-13762,wowhead="https://www.wowhead.com/wotlk/quest=9283",image="assets/images/quests/placeholder.png",xpDiff=6,money=65,desc="The healing crystals are replenished, but that is not the only way we can help the injured. All draenei can tap the gift of the Naaru to heal. You must use this ability to heal one of the crash survivors.$b$bYou'll find most of the survivors in the areas to the west and northwest, but the crash scattered us all over the vale.$b$bThe survivors have suffered from exposure to the irradiated power crystals, so you should be able to find them by the red glow that surround them.$B$BYou must save them, $N.",logDesc="Use your Gift of the Naaru ability on one of the Draenei Survivors spread throughout Ammen Vale, then return to Zalduun at the Crash Site in Ammen Vale.",rewards={{id=23389,qty=1}}} end
