if not DB[9292] then DB[9292]={id=9292,zoneId=-368,name="Cracked Necrotic Crystal",level=-1,minLevel=1,giver="3",giverType="NPC",giverId=16531,ender="Lieutenant Orrin",enderType="NPC",enderId=16478,wowhead="https://www.wowhead.com/wotlk/quest=9292",image="assets/images/quests/placeholder.png",desc="On the corpse of the fallen abomination, you discover a cracked crystal, slowly pulsing with necrotic energy.",logDesc="Bring the Cracked Necrotic Crystal to Lieutenant Orrin outside the gates of Stormwind.",choiceRewards={{id=23123,qty=1},{id=23122,qty=1}}} end
if not DB[9293] then DB[9293]={id=9293,zoneId=3526,name="What Must Be Done...",level=2,minLevel=1,giver="Botanist Taerix",giverType="NPC",giverId=16514,ender="Botanist Taerix",enderType="NPC",enderId=16514,rewardNextId=9294,poiX=-4057,poiY=-13722,wowhead="https://www.wowhead.com/wotlk/quest=9293",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="The nearby lake has been contaminated by one of the ship's power crystals.  Many of the plants and animals of Ammen Vale have been mutated because of this.$B$BI have a theory on how to heal the lake, but I must have samples from the mutated lashers for analysis.  They can be found to the west in the Ammen Fields.$B$BWill you help me, $c?",logDesc="Gather 10 Lasher Samples and return them to Botanist Taerix at the Crash Site in Ammen Vale."} end
if not DB[9294] then DB[9294]={id=9294,zoneId=3526,name="Healing the Lake",level=3,minLevel=1,giver="Botanist Taerix",giverType="NPC",giverId=16514,ender="Botanist Taerix",enderType="NPC",enderId=16514,poiX=-4057,poiY=-13722,wowhead="https://www.wowhead.com/wotlk/quest=9294",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Thank goodness, I think it'll work!  I have an agent for you to spread at Silverline Lake to the south.  It will neutralize the effects of the irradiated ship's power crystal that fell there.$B$BSwim out and scatter the neutralizing agent near it.  Don't worry, you won't be exposed long enough to become irradiated.",logDesc="Disperse the Neutralizing Agent at the Irradiated Power Crystal, then return to Botanist Taerix at the Crash Site in Ammen Vale."} end
if not DB[9295] then DB[9295]={id=9295,zoneId=-368,name="Letter from the Front",level=-1,minLevel=45,ender="Keeper of the Rolls",enderType="NPC",enderId=16281,wowhead="https://www.wowhead.com/wotlk/quest=9295",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...",logDesc="Take the Torn Letter to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands."} end
