if not DB[9303] then DB[9303]={id=9303,zoneId=3526,name="Inoculation",level=4,minLevel=2,giver="Vindicator Aldar",giverType="NPC",giverId=16535,ender="Vindicator Aldar",enderType="NPC",enderId=16535,rewardNextId=9309,poiX=-4195,poiY=-13736,wowhead="https://www.wowhead.com/wotlk/quest=9303",image="assets/images/quests/placeholder.png",xpDiff=6,money=150,desc="Zhanaa needs our help to salvage parts from the Exodar.  Taerix prepared an inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of the salvage.$B$BJust get close to the unaffected ones and use the crystal on them.  Unfortunately, you'll have to kill the others.  You'll find the owlkin at Nestlewood Thicket and Nestlewood Hills to the southeast.",logDesc="Use the Inoculating Crystal on 6 Nestlewood Owlkin. Then return to Vindicator Aldar at the Crash Site in Ammen Vale.",rewards={{id=118,qty=3}},choiceRewards={{id=5997,qty=3},{id=2454,qty=3}}} end
if not DB[9304] then DB[9304]={id=9304,zoneId=-368,name="Document from the Front",level=-1,minLevel=45,ender="Keeper of the Rolls",enderType="NPC",enderId=16281,wowhead="https://www.wowhead.com/wotlk/quest=9304",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...",logDesc="Take the Smudged Document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands."} end
if not DB[9305] then DB[9305]={id=9305,zoneId=3526,name="Spare Parts",level=4,minLevel=2,giver="Technician Zhanaa",giverType="NPC",giverId=17071,ender="Technician Zhanaa",enderType="NPC",enderId=17071,poiX=-4185,poiY=-13733,wowhead="https://www.wowhead.com/wotlk/quest=9305",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We managed to recover a damaged holographic emitter from the crash. If we repair it, we'll have a chance to find other survivors outside of Ammen Vale.$B$BThere were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. $B$B$N, you must go south to Nestlewood Thicket and Hills to find the spare parts.",logDesc="Collect 4 Emitter Spare Parts and then return to Technician Zhanaa at the Crash Site in Ammen Vale.",choiceRewards={{id=24423,qty=1},{id=24424,qty=1},{id=24425,qty=1}}} end
if not DB[9306] then DB[9306]={id=9306,zoneId=3526,name="<DEPRECATED>Speak with Vindicator Aldar",level=4,minLevel=1,rewardNextId=9307,wowhead="https://www.wowhead.com/wotlk/quest=9306",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N,Vindicator Aldar has been looking for someone to take care of a problem that we're having with the mutated owlkin at Nestlewood Thicket.  We must deal with an unfortunate side effect of our unintended arrival here.$B$BYou'll find him outside to the south in the crash site. Please,speak with him as soon as you can.",logDesc="Speak with Vindicator Aldar at the Crash Site in Ammen Vale."} end
if not DB[9307] then DB[9307]={id=9307,zoneId=3526,name="<DEPRECATED>Compassion",level=4,minLevel=2,wowhead="https://www.wowhead.com/wotlk/quest=9307",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Nearby Silverline Lake was contaminated by a piece of the ship that fell into it.  This in turn has caused the mutation of most of the creatures in the area,some of which have turned hostile.  The worst of these are the mutated owlkin.$B$BGo south into Nestlewood Thicket and put down as many of these pitiful creatures as you can.  It's a mercy killing,$c,so please make it quick and painless.",logDesc="Kill 14 Mutated Owlkin and then return to Vindicator Aldar at the Crash Site in Ammen Vale.",choiceRewards={{id=24135,qty=1},{id=24134,qty=1},{id=24133,qty=1}}} end
if not DB[9308] then DB[9308]={id=9308,zoneId=3526,name="<DEPRECATED>Blood Elf Remains?",level=4,minLevel=3,wowhead="https://www.wowhead.com/wotlk/quest=9308",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You believe that these are the remains of one of the sin'dorei -- a blood elf -- laying dead here on the ground.  By the look of it he fell victim to the savage claws of at least a few of the mutated owlkin in the thicket.$B$BSearching the body,you uncover an amulet on a chain around his neck.  Perhaps this would be of interest to Vindicator Aldar?",logDesc="Take the Blood Elf Amulet to Vindicator Aldar at the Crash Site in Ammen Vale."} end
if not DB[9309] then DB[9309]={id=9309,zoneId=3526,name="The Missing Scout",level=5,minLevel=2,giver="Vindicator Aldar",giverType="NPC",giverId=16535,ender="Tolaan",enderType="NPC",enderId=16546,rewardNextId=10303,poiX=-4195,poiY=-13736,wowhead="https://www.wowhead.com/wotlk/quest=9309",image="assets/images/quests/placeholder.png",xpDiff=2,desc="We now have several separate confirmations of unusual activity up on the Shadow Ridge.$B$BThis is disturbing; we thought that the scouting missions already undertaken had been thorough. One of my scouts hasn't reported back yet.$B$B$C, I need you to head southwest to the other side of Silverline Lake and find Tolaan, and see what has delayed him.",logDesc="Find and speak with Tolaan at Shadow Ridge in Ammen Vale."} end
if not DB[9310] then DB[9310]={id=9310,zoneId=-368,name="Faint Necrotic Crystal",level=-1,minLevel=1,giver="3",giverType="NPC",giverId=16531,ender="Lieutenant Rukag",enderType="NPC",enderId=16494,wowhead="https://www.wowhead.com/wotlk/quest=9310",image="assets/images/quests/placeholder.png",desc="On the corpse of the fallen wight, you find a crystal faintly radiating necrotic energy.",logDesc="Bring the Faint Necrotic Crystal to Lieutenant Rukag in the courtyard of the Undercity.",choiceRewards={{id=23123,qty=1},{id=23122,qty=1}}} end
if not DB[9311] then DB[9311]={id=9311,zoneId=3526,name="Blood Elf Spy",level=5,minLevel=2,giver="Tolaan",giverType="NPC",giverId=16546,ender="Vindicator Aldar",enderType="NPC",enderId=16535,poiX=-4446,poiY=-13431,wowhead="https://www.wowhead.com/wotlk/quest=9311",image="assets/images/quests/placeholder.png",xpDiff=7,money=300,desc="I have a plan. We must kill their leader. Without their master, perhaps they will retreat to regroup. We just need to buy time until the repairs are completed.$b$bThen Vindicator Aldar must know of this. Kill the surveyor, then return and tell him what we've found.",logDesc="Slay Surveyor Candress and then inform Vindicator Aldar at the Crash Site in Ammen Vale.",choiceRewards={{id=23390,qty=1},{id=23391,qty=1},{id=23392,qty=1},{id=23393,qty=1},{id=24441,qty=1},{id=25553,qty=1}}} end
if not DB[9312] then DB[9312]={id=9312,zoneId=3526,name="The Emitter",level=5,minLevel=3,giver="Vindicator Aldar",giverType="NPC",giverId=16535,ender="Technician Zhanaa",enderType="NPC",enderId=17071,poiX=-4195,poiY=-13736,wowhead="https://www.wowhead.com/wotlk/quest=9312",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, while you were out investigating the Shadow Ridge, Zhanaa here has been going on about the holographic emitter.  You might want to speak with her.",logDesc="Speak with Technician Zhanaa at the Crash Site in Ammen Vale."} end
if not DB[9313] then DB[9313]={id=9313,zoneId=3524,name="Travel to Azure Watch",level=5,minLevel=2,giver="Technician Zhanaa",giverType="NPC",giverId=17071,ender="Technician Dyvuun",enderType="NPC",enderId=16551,poiX=-4185,poiY=-13733,wowhead="https://www.wowhead.com/wotlk/quest=9313",image="assets/images/quests/placeholder.png",xpDiff=6,desc="By all that is good, $N, you must go at once to this Azure Watch and speak with Dyvuun!$B$BThere is a path that leads west off of this tiny isle.  Follow it and cross the Crystalbrook River to arrive on the larger part of the isle.  Continue to follow the path and you should find Azure Watch.$B$BSee if you can convince them to send us some aid and supplies.  The rest of us will follow when we can.$B$BThank you, we wouldn't have made it without you!",logDesc="Speak with Technician Dyvuun at Azure Watch on Azuremyst Isle."} end
if not DB[9314] then DB[9314]={id=9314,zoneId=3524,name="Word from Azure Watch",level=5,minLevel=1,giver="Aeun",giverType="NPC",giverId=16554,ender="Caregiver Chellan",enderType="NPC",enderId=16553,poiX=-4261,poiY=-13125,wowhead="https://www.wowhead.com/wotlk/quest=9314",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$C! A couple mutated beasts jumped me and my leg is injured.$B$BI was sent on a scouting mission from Azure Watch after we received word from Zhanaa. Please, could you go speak with Caregiver Chellan in my stead? She needs to know how many people to expect in Azure Watch. Just cross the Crystalbrook River here and continue following the road until you get to Azure Watch.$B$BBe sure to ask her for a place for yourself to stay in.",logDesc="Speak with Caregiver Chellan at Azure Watch on Azuremyst Isle.",choiceRewards={{id=6290,qty=5},{id=159,qty=5}}} end
if not DB[9315] then DB[9315]={id=9315,zoneId=3433,name="Anok'suten",level=11,minLevel=9,giver="Dying Blood Elf",giverType="NPC",giverId=16601,ender="Arcanist Vandril",enderType="NPC",enderId=16197,poiX=7938,poiY=-7182,wowhead="https://www.wowhead.com/wotlk/quest=9315",image="assets/images/quests/placeholder.png",xpDiff=5,money=400,desc="Come closer, I am ... dying.$B$BI was sent here ... to slay these Nerubians, but Vandril didn't ... know that they have a leader.$B$B<The dying blood elf coughs up a good amount of blood.>$B$BYou must find and ... slay Anok'suten.  Get help.  She wanders around ... Suncrown Village.",logDesc="Slay Anok'suten and return to Arcanist Vandril at Tranquillien in the Ghostlands.",choiceRewards={{id=24341,qty=1},{id=24339,qty=1},{id=24340,qty=1},{id=28149,qty=1}}} end
if not DB[9316] then DB[9316]={id=9316,zoneId=151,name="[TXT] Goblin Savages",level=50,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=9316",image="assets/images/quests/placeholder.png",xpDiff=5,money=7500,desc="<Brianna gives you a searching glance.>$B$BSo,you want to kill some goblins,eh? Well,if you're determined,you can start with the nearby savages. Bring me their teeth as proof of your deeds.",logDesc="Brianna Schneider on Designer Island wants 10 Goblin Teeth.",rewards={{id=13909,qty=1}}} end
if not DB[9317] then DB[9317]={id=9317,zoneId=0,name="Consecrated Sharpening Stones",level=-1,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=9317",image="assets/images/quests/placeholder.png",rewards={{id=23122,qty=1}}} end
if not DB[9318] then DB[9318]={id=9318,zoneId=0,name="Blessed Wizard Oil",level=-1,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=9318",image="assets/images/quests/placeholder.png",rewards={{id=23123,qty=1}}} end
if not DB[9319] then DB[9319]={id=9319,zoneId=-369,name="A Light in Dark Places",level=-1,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=9319",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We are not the only ones who celebrate this holiday, $n. All creatures, all cultures, are touched by the flame. Even in the darkest places, the fires are being lit.$b$bIf you wish to see them for yourself, travel into the depths. Seek out the bonfires burning within Stratholme, Scholomance, among the ogres of Dire Maul, and the halls of Blackrock Spire itself; I will await your return.",logDesc="Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then return to the Festival Flamekeeper.",rewards={{id=23083,qty=1},{id=23247,qty=10}}} end
if not DB[9320] then DB[9320]={id=9320,zoneId=0,name="Super Mana Potion",level=-1,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=9320",image="assets/images/quests/placeholder.png",rewards={{id=22832,qty=1}}} end
if not DB[9321] then DB[9321]={id=9321,zoneId=0,name="Super Healing Potion",level=-1,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=9321",image="assets/images/quests/placeholder.png",rewards={{id=22829,qty=1}}} end
if not DB[9322] then DB[9322]={id=9322,zoneId=-369,name="Wild Fires in Kalimdor",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9322",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The Midsummer Fire Festival is celebrated everywhere in Azeroth, and the diverse land of Kalimdor is no exception. You look fit to travel -- perhaps a journey is in order.$b$bMidsummer cannot be truly appreciated unless you've seen the blistering blue fires abroad. The celebrants have lit fires in chilly western Winterspring, northeastern Azshara, near Valor's Rest in the wastes of Silithus, and by the entrance to lush Un'Goro. Return once your journey is complete.",logDesc="Visit the Midsummer camps located in Azshara, Silithus, Un'Goro Crater, and Winterspring, then return to the Festival Flamekeeper.",rewards={{id=23379,qty=1},{id=23247,qty=10}}} end
if not DB[9323] then DB[9323]={id=9323,zoneId=-369,name="Wild Fires in the Eastern Kingdoms",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9323",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Our celebration of the flame is spread throughout the land, $c. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue. Seek them out.$b$bYou'll find one just north of Blackrock Spire. The others are located deep within the Eastern Plaguelands near a decrepit town, along the road to the cliffs within the mountainous Hinterlands, and on the way to the Dark Portal within the Blasted Lands.$b$b Return once your journey is done.",logDesc="Visit the Fire Festival camps located in Blasted Lands, Eastern Plaguelands, the Hinterlands and Searing Gorge, then speak with the Festival Flamekeeper.",rewards={{id=23324,qty=1},{id=23247,qty=10}}} end
if not DB[9324] then DB[9324]={id=9324,zoneId=-369,name="Stealing Orgrimmar's Flame",level=-1,minLevel=1,ender="Festival Loremaster",enderType="NPC",enderId=16817,wowhead="https://www.wowhead.com/wotlk/quest=9324",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="This flame, stolen from the heart of Orgrimmar itself, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...",logDesc="Return the Flame of Orgrimmar to the Festival Loremaster.",rewards={{id=23247,qty=25}},choiceRewards={{id=23435,qty=5},{id=23327,qty=5},{id=23326,qty=5},{id=23211,qty=5},{id=23246,qty=10},{id=34684,qty=10}}} end
if not DB[9325] then DB[9325]={id=9325,zoneId=-369,name="Stealing Thunder Bluff's Flame",level=-1,minLevel=1,ender="Festival Loremaster",enderType="NPC",enderId=16817,wowhead="https://www.wowhead.com/wotlk/quest=9325",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="This flame, stolen from the shaman of Thunder Bluff, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...",logDesc="Return the Flame of Thunder Bluff to the Festival Loremaster.",rewards={{id=23247,qty=25}},choiceRewards={{id=23435,qty=5},{id=23327,qty=5},{id=23326,qty=5},{id=23211,qty=5},{id=23246,qty=10},{id=34684,qty=10}}} end
if not DB[9326] then DB[9326]={id=9326,zoneId=-369,name="Stealing the Undercity's Flame",level=-1,minLevel=1,ender="Festival Loremaster",enderType="NPC",enderId=16817,wowhead="https://www.wowhead.com/wotlk/quest=9326",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="This flame, stolen from the ruins above the Undercity, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...",logDesc="Return the Flame of the Undercity to the Festival Loremaster.",rewards={{id=23247,qty=25}},choiceRewards={{id=23435,qty=5},{id=23327,qty=5},{id=23326,qty=5},{id=23211,qty=5},{id=23246,qty=10},{id=34684,qty=10}}} end
if not DB[9327] then DB[9327]={id=9327,zoneId=3433,name="The Forsaken",level=10,minLevel=9,giver="Arcanist Vandril",giverType="NPC",giverId=16197,ender="High Executor Mavren",enderType="NPC",enderId=16252,rewardNextId=9758,poiX=7642,poiY=-6819,wowhead="https://www.wowhead.com/wotlk/quest=9327",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I know it seems strange, but these Forsaken are here to help. You should speak with their leader, High Executor Mavren. He's in the tower on the west side of town.$B$BAnd, $c, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!",logDesc="Speak with High Executor Mavren at Tranquillien in the Ghostlands."} end
if not DB[9328] then DB[9328]={id=9328,zoneId=3433,name="Hero of the Sin'dorei",level=21,minLevel=15,giver="Magister Kaendris",giverType="NPC",giverId=16239,ender="3",enderType="NPC",enderId=16802,rewardNextId=9621,poiX=7192,poiY=-7101,wowhead="https://www.wowhead.com/wotlk/quest=9328",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This is the beginning of a new chapter in the history of our race, $N.  Our lands will be reclaimed and we shall cement our bond with Sylvanas and her allies.$B$BTake the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City.  He'll be eager to hear the news.",logDesc="Take Dar'Khan's Head to Lor'themar Theron in Silvermoon City."} end
if not DB[9329] then DB[9329]={id=9329,zoneId=3433,name="The Forsaken",level=10,minLevel=9,giver="Arcanist Vandril",giverType="NPC",giverId=16197,ender="High Executor Mavren",enderType="NPC",enderId=16252,rewardNextId=9758,poiX=7642,poiY=-6819,wowhead="https://www.wowhead.com/wotlk/quest=9329",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I know it seems strange, but the Forsaken are here to help. You should speak with their leader, High Executor Mavren.  He's in the tower on the west side of town.$B$BAnd, $c, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!",logDesc="Speak with High Executor Mavren at Tranquillien in the Ghostlands."} end
if not DB[9330] then DB[9330]={id=9330,zoneId=-369,name="Stealing Stormwind's Flame",level=-1,minLevel=1,ender="Festival Talespinner",enderType="NPC",enderId=16818,wowhead="https://www.wowhead.com/wotlk/quest=9330",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...",logDesc="Return the Flame of Stormwind to the Festival Talespinner.",rewards={{id=23247,qty=25}},choiceRewards={{id=23435,qty=5},{id=23327,qty=5},{id=23326,qty=5},{id=23211,qty=5},{id=23246,qty=10},{id=34684,qty=10}}} end
