if not DB[9340] then DB[9340]={id=9340,zoneId=3483,name="The Great Fissure",level=62,minLevel=60,giver="Ranger Captain Venn'ren",giverType="NPC",giverId=16789,ender="Ranger Captain Venn'ren",enderType="NPC",enderId=16789,rewardNextId=9391,poiX=-593,poiY=4068,wowhead="https://www.wowhead.com/wotlk/quest=9340",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We're dangerously close to becoming fenced in by Alliance forces.  With the influx of sin'dorei pilgrims from Azeroth, we must establish a route that's safe from our enemies' prying eyes.$B$BI've given it some thought and have arrived at a solution.  We're to establish a secret path through the Great Fissure.$B$BYes, even though the area is crawling with brutal rock flayers, they are merely beasts and can be taught to fear us.  I want you to go and kill a good number of them.  They shall learn fear.",logDesc="Ranger Captain Venn'ren at Falcon Watch wants you to slay 8 Stonescythe Whelps and 3 Stonescythe Alphas at the Great Fissure, east of Falcon Watch."} end
if not DB[9341] then DB[9341]={id=9341,zoneId=-368,name="Tabard of the Argent Dawn",level=-1,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=9341",image="assets/images/quests/placeholder.png",rewards={{id=22999,qty=1}}} end
if not DB[9342] then DB[9342]={id=9342,zoneId=3483,name="Marauding Crust Bursters",level=61,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=9342",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="As if the gan'arg that overran the mines aren't bad enough, now we've got gigantic worms encroaching on us from the other direction!$B$BWith Thrallmar's garrison pinned down defending against the Legion and tending to their wounded, it leaves me and the miners to deal with the problems.$B$B<The foreman gestures at the sleeping peons.>$B$BAnd you can see how useful they are...$B$BI'd gladly pay you their wages to clear out some of those worms.",logDesc="Foreman Razelcraz at the mines near Thrallmar wants you to kill 15 Marauding Crust Bursters. The worms have a tendency to attack suddenly from their tunnels below ground.",choiceRewards={{id=25785,qty=1},{id=25784,qty=1}}} end
if not DB[9343] then DB[9343]={id=9343,zoneId=-368,name="Tabard of the Argent Dawn",level=-1,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=9343",image="assets/images/quests/placeholder.png",rewards={{id=22999,qty=1}}} end
if not DB[9344] then DB[9344]={id=9344,zoneId=3483,name="A Hasty Departure",level=61,minLevel=255,giver="Far Seer Regulkut",giverType="NPC",giverId=16574,ender="Grelag",enderType="NPC",enderId=16858,rewardNextId=9345,poiX=176,poiY=2739,wowhead="https://www.wowhead.com/wotlk/quest=9344",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Greetings, $N. Outland is a perilous place, as many of our expedition quickly learned. I'm afraid young Grelag may have learned that lesson firsthand.$B$BGrelag is a promising student, but he lacks patience! He eagerly studies the history of his people, but he sometimes forgets the threats of the present day.$B$BHe departed for the Spinebreaker Post, ignorant of the Legion and fel orc presences. I fear something may have happened to him.",logDesc="Far Seer Regulkut wants you to track down her student Grelag.  "} end
if not DB[9345] then DB[9345]={id=9345,zoneId=3483,name="Preparing the Salve",level=61,minLevel=58,giver="Grelag",giverType="NPC",giverId=16858,ender="Grelag",enderType="NPC",enderId=16858,rewardNextId=10213,poiX=-1331,poiY=2393,wowhead="https://www.wowhead.com/wotlk/quest=9345",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Just as Zeth'Gor came into view, a Legion patrol caught sight of me. I ran, hoping to duck into one of the towers in the distance, but one of their felhounds caught up with me and nearly hamstrung me!$B$BI managed to escape, but my leg is in terrible shape. Stone Guard Ambelan found me and brought me here.$BNow, I have to find a way to tend to my leg. Spineleaf grows in and around the Valley of Bones to the north . A salve made from it will dull the pain enough for me to travel.",logDesc="Gather 12 Hellfire Spineleaf plants for a salve and return to Grelag at Spinebreaker Post.",rewards={{id=24338,qty=20}}} end
if not DB[9346] then DB[9346]={id=9346,zoneId=3483,name="When Helboars Fly",level=61,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=9346",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Have you ever seen a helboar fly? They don't even need wings!$B$B<Watch Commander Krunk laughs.>$B$BThe fight against the Legion camps to the north has depleted our supplies, including catapult ammunition. This is the perfect opportunity to try something new.$B$BInstead of using boulders, I want to try igniting the corpses of the starving helboars I've seen around the eastern ruins and use them to bombard the Legion's camps.$B$BAre you going to volunteer, or do I have to order you? ",logDesc="Watch Commander Krunk in Thrallmar wants you to bring him 10 Plump Helboar Carcasses from Starving Helboars."} end
if not DB[9347] then DB[9347]={id=9347,zoneId=3483,name="Voidwalkers Gone Wild",level=61,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=9347",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Examining the essence reveals violent swirls of energy sealed within a vessel made of unidentifiable material. As you consider it,you can feel it beginning to tug at your mind,inviting you to come closer and to look deeper.$B$BFeeling your will begin to slip away,you break your gaze immediately. Its presence remains at the edge of your consciousness as you determine what to do with it.",logDesc="Bring the Pulsating Voidwalker Essence to Mahuram Stouthoof in Thrallmar."} end
if not DB[9348] then DB[9348]={id=9348,zoneId=3483,name="Ravager Roundup",level=61,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=9348",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Outland is rife with fascinating creatures. Fascinating -- and extremely dangerous.$B$BThe area is rich with predators,which seems strange for such a barren land,but a closer look reveals something of a hierarchy.$B$BThe rock flayers seem to have domesticated another predator,the ravager,and breed them as hunting companions and guard animals. I need to know more about how they're training these ravagers. We must shut down and examine their breeding site to the southwest,near the Terokkar Forest.",logDesc="Slay 10 Captive Ravager Hatchlings and retrieve 12 Ravager Eggs for Mahuram Stouthoof in Thrallmar.",choiceRewards={{id=25980,qty=1},{id=25981,qty=1},{id=25979,qty=1}}} end
if not DB[9349] then DB[9349]={id=9349,zoneId=3483,name="Ravager Egg Roundup",level=61,minLevel=58,giver="Legassi",giverType="NPC",giverId=19344,ender="Legassi",enderType="NPC",enderId=19344,rewardNextId=9361,poiX=-1096,poiY=2996,wowhead="https://www.wowhead.com/wotlk/quest=9349",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'm starving!$B$BThere's irony in that, wouldn't you say?  A starving cook?$B$B<Legassi laughs half-heartedly and taps a folded piece of parchment he has in his pocket.>$B$BAccording to this tourist map we were following - before we were so rudely shot down - there's an area to the southwest, near Terokkar Forest.  It's called the Razorthorn Trail, and supposedly it's brimming with delicious ravager eggs!$B$BI could cook up quite a feast if only someone were brave enough to go down there and get me some!",logDesc="Retrieve 12 Ravager Eggs for Legassi at the Zeppelin Crash in Hellfire Peninsula.",rewards={{id=28501,qty=5}}} end
if not DB[9350] then DB[9350]={id=9350,zoneId=3483,name="A Peon's Work is Never Done",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=9350",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The Legion's constant assaults take a heavy toll on our defenses. If the palisade falls,so will Thrallmar. I've assigned peons to reinforce and repair the walls,but we're running out of materials.$B$BGrelag,one of the Far Seer's students,is well versed in the old ways and suggested returning to an ancient practice. Long ago,the clefthoof hunt supplied us with meat,hides,and bones. Taking up the hunt again,with the clefthoof to the southeast,would provide what's needed and honor the ancestors.",logDesc="Gather 8 Clefthoof Hides and 8 sets of Clefthoof Bones from the Raging Clefthoof. Return to Watch Commander Krunk in Thrallmar once you have all the materials.",choiceRewards={{id=25982,qty=1},{id=25983,qty=1},{id=25984,qty=1}}} end
if not DB[9351] then DB[9351]={id=9351,zoneId=3483,name="Voidwalkers Gone Wild",level=61,minLevel=58,giver="\"Screaming\" Screed Luckheed",giverType="NPC",giverId=19367,ender="\"Screaming\" Screed Luckheed",enderType="NPC",enderId=19367,poiX=-1097,poiY=3001,wowhead="https://www.wowhead.com/wotlk/quest=9351",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Even if I can get the zeppelin's frame repaired, I'll have to find something else to power the engine. I'm all out of fuel and there's no place to fill up around here!$B$BTo the south of us is an area of broken land called the Warp Fields. It's full of rogue and uncontrolled voidwalkers, but I like to think of them as walking batteries.$B$BIf you can bring me enough of their essence, I can convert the zeppelin's engine to run on it. Five gold says I'll even get better mileage out of it, too!",logDesc="Bring 10 Condensed Voidwalker Essences to \"Screaming\" Screed Luckheed at the Zeppelin Crash.",choiceRewards={{id=25786,qty=1},{id=25787,qty=1}}} end
if not DB[9352] then DB[9352]={id=9352,zoneId=3430,name="Darnassian Intrusions",level=6,minLevel=4,giver="Aeldon Sunbrand",giverType="NPC",giverId=15403,ender="Ley-Keeper Velania",enderType="NPC",enderId=15401,poiX=9531,poiY=-6860,wowhead="https://www.wowhead.com/wotlk/quest=9352",image="assets/images/quests/placeholder.png",xpDiff=5,money=125,desc="Besides the constant threat that the Wretched represent, I also have to deal with all kind of fictitious reports of night elf sightings.$B$BThough most reports are unfounded, one recent incident demands further investigation.  The West Sanctum, one of our primary energy sources, has suffered a terrible malfunction and rumors of Darnassian sabotage are rampant.$B$BTravel there and deal with anyone that looks suspicious.  Report back to Ley-Keeper Velania, who watches over the sanctum.",logDesc="Travel to the West Sanctum, southwest of Falconwing Square and defeat any intruders present there.  Report your findings to Ley-Keeper Velania."} end
if not DB[9353] then DB[9353]={id=9353,zoneId=0,name="Redeem iCoke Gift Box Voucher",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9353",image="assets/images/quests/placeholder.png",rewards={{id=23224,qty=1}}} end
if not DB[9354] then DB[9354]={id=9354,zoneId=3483,name="Searching for New Materials",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=9354",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="<The dwarf looks up from his work expectantly.>$B$BIf you're looking to commission a piece,get in line,$c. I've got my hands full maintaining the Sons' equipment and preparing us for the day when we'll take the battle to the enemy again.$B$BOur metal stocks are getting very low since crust borers invaded the mines. I've been experimenting with natural materials from the raging clefthoof that graze in the areas northeast of the Hold,and while they're no substitute for iron,I'm learning to make do.",logDesc="Gather 8 Clefthoof Hides and 8 Clefthoof Sinews from the Raging Clefthoof. When you have the materials,bring them to Humphry in Honor Hold.",choiceRewards={{id=25982,qty=1},{id=25983,qty=1},{id=25984,qty=1}}} end
if not DB[9355] then DB[9355]={id=9355,zoneId=3483,name="A Job for an Intelligent Man",level=61,minLevel=58,giver="Foreman Biggums",giverType="NPC",giverId=16837,ender="Foreman Biggums",enderType="NPC",enderId=16837,poiX=-673,poiY=2853,wowhead="https://www.wowhead.com/wotlk/quest=9355",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Well met, $c. Now that reinforcements are finally arriving, we can recapture some semblance of a normal life.$B$BOne of our first goals is to restore the flow of men and goods along the road to the southwest, but it must be reclaimed from the crust bursters that've overrun the area.$B$BIf you're willing to help us deal with this menace, you would have the gratitude of the Sons. Watch carefully for the disturbed ground they leave in their wake.",logDesc="Kill 15 Marauding Crust Bursters and return to Foreman Biggums at Honor Hold.",choiceRewards={{id=25785,qty=1},{id=25784,qty=1}}} end
if not DB[9356] then DB[9356]={id=9356,zoneId=3483,name="Smooth as Butter",level=61,minLevel=58,giver="Legassi",giverType="NPC",giverId=19344,ender="Legassi",enderType="NPC",enderId=19344,poiX=-1096,poiY=2996,wowhead="https://www.wowhead.com/wotlk/quest=9356",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Screed likes to say his flying is as \"smooth as butter.\" I think \"butterfingered\" is more like it!$B$BTake a look at the wreckage over there. He calls it a \"rough\" landing.$B$BSure, we got shot at, but I'd be willing to cut him a little more slack if he didn't brag about his piloting skills so often!$B$BI think I'm going to make him a batch of wings to drive the point home. To the east, in the Valley of Bones, you'll find bonestripper buzzards. Their wings are plump, juicy, and perfect for my needs.",logDesc="Bring 12 Plump Buzzard Wings to Legassi at the Zeppelin Crash.",rewards={{id=27651,qty=5},{id=27684,qty=1}}} end
if not DB[9357] then DB[9357]={id=9357,zoneId=3430,name="Report to Aeldon Sunbrand",level=5,minLevel=4,rewardNextId=8463,wowhead="https://www.wowhead.com/wotlk/quest=9357",image="assets/images/quests/placeholder.png",xpDiff=1,desc="If you're looking for work, you'll find Captain Sunbrand inside the Inner Elf Gate, through the doors behind me.$B$BNow leave me be, I must question this scoundrel.",logDesc="Report to Aeldon Sunbrand at the Inner Elf Gate in Eversong Woods."} end
if not DB[9358] then DB[9358]={id=9358,zoneId=3430,name="Ranger Sareyn",level=9,minLevel=8,giver="Marniel Amberlight",giverType="NPC",giverId=15397,ender="Ranger Sareyn",enderType="NPC",enderId=15942,poiX=8700,poiY=-6638,wowhead="https://www.wowhead.com/wotlk/quest=9358",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Don't take the safety of this village for granted.  We're under siege by the Scourge on the east and the Wretched to the west.$B$BRanger Sareyn keeps our borders safe from the undead that pour in from the Dead Scar.  Follow the road eastwards out of town and see if you can lend her a hand.",logDesc="Report to Ranger Sareyn outside Fairbreeze Village in Eversong Woods."} end
if not DB[9359] then DB[9359]={id=9359,zoneId=3430,name="Farstrider Retreat",level=10,minLevel=8,giver="Ranger Degolien",giverType="NPC",giverId=15939,ender="Lieutenant Dawnrunner",enderType="NPC",enderId=15399,rewardNextId=8476,poiX=8716,poiY=-6622,wowhead="https://www.wowhead.com/wotlk/quest=9359",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Your help in subduing the Wretched has been invaluable.  The Farstriders would surely have use for someone like you in their fight against the Amani trolls.$B$BLook for the Farstrider Retreat to the northeast of here, speak to Lieutenant Dawnrunner and see what assistance she might need.",logDesc="Report to Lieutenant Dawnrunner at the Farstrider Retreat in Eversong Woods."} end
if not DB[9360] then DB[9360]={id=9360,zoneId=3430,name="Amani Invasion",level=11,minLevel=8,ender="Lieutenant Dawnrunner",enderType="NPC",enderId=15399,rewardNextId=9363,wowhead="https://www.wowhead.com/wotlk/quest=9360",image="assets/images/quests/placeholder.png",xpDiff=5,money=400,desc="Though you don't understand the language in these battle plans, you clearly make out a map marking the positions of the Farstrider Retreat and Fairbreeze Village.$B$BYou'd best let Lieutenant Dawnrunner at the Farstrider Retreat know about this.",logDesc="Deliver the Amani Invasion Plans to Lieutenant Dawnrunner at Farstrider Retreat."} end
if not DB[9361] then DB[9361]={id=9361,zoneId=3483,name="Helboar, the Other White Meat",level=61,minLevel=58,giver="Legassi",giverType="NPC",giverId=19344,ender="Legassi",enderType="NPC",enderId=19344,rewardNextId=9356,poiX=-1096,poiY=2996,wowhead="https://www.wowhead.com/wotlk/quest=9361",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Those eggs are superb, but what do you say we kick it up another notch?$B$BA side of bacon would round out the meal perfectly and I know just where to get it.$B$BThis place is littered with helboars. Of course, there's no one here to inspect and tenderize the meat, but we're in luck!$B$B<Legassi rummages around in his pack and produces a flask.>$B$BThis wasn't made for use on pork, but cooking is as much about improvisation as anything else!",logDesc="Legassi at the Zeppelin Crash wants you to gather 8 Purified Helboar Meat. To purify the meat, use the Purification Mixture on the Tainted Helboar Meat you gather from Helboars.",rewards={{id=29292,qty=5}}} end
if not DB[9362] then DB[9362]={id=9362,zoneId=-161,name="Warlord Krellian",level=60,minLevel=60,giver="Archmage Xylem",giverType="NPC",giverId=8379,ender="Archmage Xylem",enderType="NPC",enderId=8379,rewardNextId=9364,poiX=3982,poiY=-4760,wowhead="https://www.wowhead.com/wotlk/quest=9362",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There isn't much time, $n!  My scrying spells have revealed a powerful source of magic.  I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact.$b$bThe pathetic little cretin is known as Warlord Krellian, hiding behind his guards in the Temple of Zin-Malor.  Burn him to ashes and take the prismatic shell he covets so dearly.",logDesc="Retrieve the Prismatic Shell for Archmage Xylem.  The Archmage resides in a tower atop the cliffs of Azshara."} end
if not DB[9363] then DB[9363]={id=9363,zoneId=3430,name="Warning Fairbreeze Village",level=11,minLevel=8,giver="Lieutenant Dawnrunner",giverType="NPC",giverId=15399,ender="Ranger Degolien",enderType="NPC",enderId=15939,poiX=8981,poiY=-7458,wowhead="https://www.wowhead.com/wotlk/quest=9363",image="assets/images/quests/placeholder.png",xpDiff=3,money=200,desc="Go to Fairbreeze Village and notify Ranger Degolien of the Amani plans.  Even with Zul'Marosh dead, Fairbreeze must prepare for a troll attack.  Tell Degolien I will send him reinforcements as soon as possible.",logDesc="Travel to Fairbreeze Village in Eversong Woods and speak to Ranger Degolien.",choiceRewards={{id=23265,qty=1},{id=23266,qty=1},{id=23267,qty=1}}} end
if not DB[9364] then DB[9364]={id=9364,zoneId=-161,name="Fragmented Magic",level=-1,minLevel=60,giver="Archmage Xylem",giverType="NPC",giverId=8379,ender="Archmage Xylem",enderType="NPC",enderId=8379,poiX=3982,poiY=-4760,wowhead="https://www.wowhead.com/wotlk/quest=9364",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My research has revealed a unique purpose for the prismatic shell.$b$bCarry the shell and cast your polymorph spell on the Spitelash in Azshara.  If you wait a few moments, the chaotic aura of the shell will cause them to split into several smaller clones for a few moments.  Kill these clones as quickly as possible, and the shell will collect their essence.$b$bWhen the shell is full, return it to me.",logDesc="Polymorph the Spitelash of Azshara and kill the clones that appear several seconds later.  When you have slain 50 Polymorph Clones, return to Archmage Xylem in Azshara."} end
if not DB[9365] then DB[9365]={id=9365,zoneId=-369,name="A Thief's Reward",level=-1,minLevel=1,ender="Festival Loremaster",enderType="NPC",enderId=16817,wowhead="https://www.wowhead.com/wotlk/quest=9365",image="assets/images/quests/placeholder.png",xpDiff=4,rewards={{id=23323,qty=1}}} end
if not DB[9366] then DB[9366]={id=9366,zoneId=3483,name="In Need of Felblood",level=62,minLevel=60,giver="Ryathen the Somber",giverType="NPC",giverId=16791,ender="Ryathen the Somber",enderType="NPC",enderId=16791,rewardNextId=9370,poiX=-569,poiY=4146,wowhead="https://www.wowhead.com/wotlk/quest=9366",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Northeast of here lie the Pools of Aggonar.  Once a sacred site to the draenei, their waters were corrupted after the blood from the demon Aggonar was spilled into them.$B$BThat blood, though old and diluted, still possesses tremendous power.  Terrorfiends now walk the area, empowered by the pure demonic energies of the original blood.  Slay them and retrieve as much felblood as you can.  I'll make it worth your while.",logDesc="Ryathen the Somber at Falcon Watch in Hellfire Peninsula wants you to bring him 6 Felblood Samples from the Terrorfiends that inhabit the Pools of Aggonar."} end
if not DB[9367] then DB[9367]={id=9367,zoneId=-369,name="The Festival of Fire",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9367",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Midsummer is upon us once again!$b$bEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.$b$bIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!",logDesc="Touch the bonfires within Stormwind, Ironforge, and Darnassus, then speak to a Festival Loremaster within the capital cities.",rewards={{id=23247,qty=10},{id=23246,qty=10}}} end
if not DB[9368] then DB[9368]={id=9368,zoneId=-369,name="The Festival of Fire",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9368",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Midsummer is upon us once again!$b$bEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.$b$bIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!",logDesc="Touch the bonfires within Orgrimmar, Thunder Bluff, and the Undercity, then speak to a Festival Talespinner within the capital cities.",rewards={{id=23247,qty=10},{id=23246,qty=10}}} end
if not DB[9369] then DB[9369]={id=9369,zoneId=3526,name="Replenishing the Healing Crystals",level=1,minLevel=1,giver="3",giverType="NPC",giverId=16477,ender="3",enderType="NPC",enderId=16477,rewardNextId=9409,poiX=-4039,poiY=-13774,wowhead="https://www.wowhead.com/wotlk/quest=9369",image="assets/images/quests/placeholder.png",xpDiff=5,money=15,desc="We are the draenei.  Our ship crashed and, since we have many wounded, our immediate concern is the depleted state of our healing crystals.  We must replenish them quickly!$B$BUnfortunately, the only way to do this at this point is to extract the blood from the local vale moths.  Their blood will make for a suitable substitute.$B$BThe moths can be found in many places around the vale, but mostly in the northwest.",logDesc="Acquire 8 Vials of Moth Blood from the nearby Vale Moths and bring them to Proenitus at the Crash Site in Ammen Vale.",choiceRewards={{id=24129,qty=1},{id=24131,qty=1},{id=24130,qty=1}}} end
if not DB[9370] then DB[9370]={id=9370,zoneId=3483,name="The Cleansing Must Be Stopped",level=62,minLevel=60,giver="Ryathen the Somber",giverType="NPC",giverId=16791,ender="Ryathen the Somber",enderType="NPC",enderId=16791,poiX=-569,poiY=4146,wowhead="https://www.wowhead.com/wotlk/quest=9370",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Our scouts captured a draenei paladin at the Pools of Aggonar.  He was to take part in a cleansing ritual to purify the pools.  We must stop the draenei from succeeding or we will lose our supply of felblood!$B$BHe was carrying this signaling gem, looking to mark a spot where a priest - or \"anchorite\" as they call themselves - could perform their rituals in safety.  Place the gem near the Altar of Aggonar and be ready to ambush any approaching draenei.$B$BI suggest that you take a friend or two along.",logDesc="Place the Signaling Gem near the Altar of Aggonar at the Pools of Aggonar and defeat any Draenei Anchorites that respond to your summons.  Return to Ryathen the Somber at Falcon Watch with the Signaling Gem after completing this task.",choiceRewards={{id=25500,qty=1},{id=25501,qty=1},{id=25499,qty=1}}} end
if not DB[9371] then DB[9371]={id=9371,zoneId=3526,name="Botanist Taerix",level=2,minLevel=1,giver="3",giverType="NPC",giverId=16477,ender="Botanist Taerix",enderType="NPC",enderId=16514,rewardNextId=10302,poiX=-4039,poiY=-13774,wowhead="https://www.wowhead.com/wotlk/quest=9371",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, Botanist Taerix is in need of your assistance. You'll find her with her apprentices to the west, outside the ship.",logDesc="Speak with Botanist Taerix at the Crash Site in Ammen Vale."} end
if not DB[9372] then DB[9372]={id=9372,zoneId=3483,name="Demonic Contamination",level=63,minLevel=61,giver="Thiah Redmane",giverType="NPC",giverId=16991,ender="Thiah Redmane",enderType="NPC",enderId=16991,rewardNextId=10255,poiX=-312,poiY=4729,wowhead="https://www.wowhead.com/wotlk/quest=9372",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Welcome to the Cenarion Post, $c. We don't often get company out here, but I'm grateful for the visit. My work with the creatures of this desolate land requires me to travel to many remote places.$B$BThe Cenarion Expedition has dispatched me to study some of the most dangerous wildlife in Outland, and I've made a startling discovery. While many creatures here have already undergone radical changes, they continue to mutate. I'm collecting blood samples to document the changes, and any help would be welcome.",logDesc="Thiah Redmane, at the Cenarion Post in Hellfire Peninsula, has asked you to gather 6 Helboar Blood Samples from Hulking Helboars."} end
if not DB[9373] then DB[9373]={id=9373,zoneId=3483,name="Missing Missive",level=61,minLevel=58,ender="Thiah Redmane",enderType="NPC",enderId=16991,wowhead="https://www.wowhead.com/wotlk/quest=9373",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Upon examining the battered leather case, it becomes apparent that the container's damage must've been caused by the caustic fluid of the worm's digestive tract. The leather appears to have been intricately tooled at one time, but the details of its adornment can no longer be made out.$B$BThe only recognizable feature of the case is a worn logo of the Cenarion Circle. Knowing nothing about the contents of the case, you decide the best course of action would be to deliver it to a Circle member.",logDesc="Return the Eroded Leather Case to Thiah Redmane, camped near the Ruins of Sha'naar in western Hellfire Peninsula."} end
if not DB[9374] then DB[9374]={id=9374,zoneId=3483,name="Arelion's Journal",level=62,minLevel=60,giver="Magistrix Carinda",giverType="NPC",giverId=16793,ender="Magistrix Carinda",enderType="NPC",enderId=16793,rewardNextId=10286,poiX=-596,poiY=4177,wowhead="https://www.wowhead.com/wotlk/quest=9374",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="My husband, Arelion, had been fascinated with the Pools of Aggonar ever since we arrived in Outland.  He spent much of his time studying slimes, of all things!$B$BHe went missing in there a few days ago.  They say he's dead and there's nothing I can do about it.$B$BOne thing I can do is try to ensure that his research doesn't die with him.  Go northeast to the pools and look for his journal.  He always carried it inside a brown knapsack.",logDesc="Magistrix Carinda at Falcon Watch in Hellfire Peninsula wants you to go to the Pools of Aggonar and retrieve Arelion's Journal."} end
if not DB[9375] then DB[9375]={id=9375,zoneId=3483,name="The Road to Falcon Watch",level=63,minLevel=61,giver="Wounded Blood Elf Pilgrim",giverType="NPC",giverId=16993,ender="Taleris Dawngazer",enderType="NPC",enderId=17015,rewardNextId=9376,poiX=-1138,poiY=4272,wowhead="https://www.wowhead.com/wotlk/quest=9375",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="<The battered blood elf's face displays relief at your presence.>$B$BPlease, $c, get me out of this cage! I foolishly set out from Thrallmar ahead of the main group, despite Martik Tor'seldori's warnings.$B$BI was set upon by horrible creatures that could only be the ravagers he talked about. I managed to drive them off, but that was only the beginning of my troubles.$B$BAs I bound my wounds, those bird men found me, dragged me back to this cave, and locked me in this cage! I must get to Falcon Watch!",logDesc="Protect the Wounded Blood Elf Pilgrim on her way to Falcon Watch, then speak with Taleris Dawngazer."} end
if not DB[9376] then DB[9376]={id=9376,zoneId=3483,name="A Pilgrim's Plight",level=63,minLevel=61,giver="Taleris Dawngazer",giverType="NPC",giverId=17015,ender="Taleris Dawngazer",enderType="NPC",enderId=17015,poiX=-647,poiY=4177,wowhead="https://www.wowhead.com/wotlk/quest=9376",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="That wounded pilgrim seems to be shouting something about a pack.$B$BWhen you encountered her, did you see a pack nearby? Hmm...$B$BShe must've left it when fleeing from her attackers. The quillfang ravagers, in their ravine to the south, are known to attack solitary travelers.$B$BIf she doesn't calm down, I won't be able to tend her wounds. Her stubbornness may just cost her her life.$B$BGo to Dustquill Ravine and see if you can find her campsite. I'm willing to bet she left it there.",logDesc="The Wounded Blood Elf Pilgrim was attacked by Quillfang Ravagers while camped in Dustquill Ravine. Find her camp and search it for the missing pack.",choiceRewards={{id=25783,qty=1},{id=25782,qty=1},{id=25781,qty=1}}} end
if not DB[9377] then DB[9377]={id=9377,zoneId=3483,name="Thirsting For Power",level=63,minLevel=61,wowhead="https://www.wowhead.com/wotlk/quest=9377",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Falcon Watch serves as a stop for pilgrims on their long journey into Outland. Although we are an early stop on the way,many of the pilgrims reach us exhausted and wracked by their addictions.$B$BIn a world such as this,many find it necessary to relearn mastery of their magical addiction. Food and drink help,$c,but magical energy is their greatest need. The remains of Outland's voidwalkers provide a potent source of energy,but they grow rare and can only be found in the Warp Fields to the southwest.",logDesc="Retrieve a Potent Voidwalker Essence from the Vengeful Voidwalkers and return to Taleris Dawngazer at Falcon Watch."} end
if not DB[9378] then DB[9378]={id=9378,zoneId=139,name="DND FLAG The Dread Citadel - Naxxramas",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=9378",image="assets/images/quests/placeholder.png",desc="In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.$B$BWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.",logDesc="Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn."} end
if not DB[9379] then DB[9379]={id=9379,zoneId=3483,name="Fortifying the Felhunter",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=9379",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Greetings,$c. Say hello to Jir'see here,too. Don't worry,he won't bite unless I tell him to.$B$B<Angela makes a cooing sound at the felhunter.>$B$BHe's so tiny in comparison to the warp hounds that live in Outland. But we're going to fix that right up,yes we are,aren't we,Jir'see?$B$BI think I've figured out a way to do it. I'll need plenty of blood from the warp hounds and that's where you come in. While you're hunting them in the southeast,I'll get ready for the experi... err,treatment.",logDesc="Gather 6 Warp Hound Blood and bring them to Angela \"The Claw\" Kestrel in Thrallmar."} end
if not DB[9380] then DB[9380]={id=9380,zoneId=3483,name="Hounded for More",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=9380",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="I swear, if I get one more letter from Ironforge...$B$BHave you ever tried to explain something to someone who just wouldn't listen, $c? I sent the boys in Ironforge the warp hound they asked for, and they had the gall to write back saying they wanted a \"pack\" of the things! A pack!$B$BSo, I tried to tell 'em that warp hounds are solitary creatures, but they'd have none of it. I've given up on setting 'em straight. Grab 6 of the best ones from the area east of the hold, and brimg 'em back here?",logDesc="Collect 6 Undamaged Warp Hound Corpses and bring them to Prospector Murantus in Honor Hold."} end
if not DB[9381] then DB[9381]={id=9381,zoneId=3483,name="Trueflight Arrows",level=63,minLevel=61,giver="Falconer Drenna Riverwind",giverType="NPC",giverId=16790,ender="Falconer Drenna Riverwind",enderType="NPC",enderId=16790,poiX=-596,poiY=4108,wowhead="https://www.wowhead.com/wotlk/quest=9381",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="With the influx of pilgrims and the encroachment of Alliance forces, things around Falcon Watch have gotten quite busy lately. In my spare time, I usually help prepare batches of arrows for the rangers, but I haven't had the chance to gather feathers for the fletching in a long time.$B$BI could offer you a bit of coin if you'd be willing to gather the tail feathers of the bonestripper vultures. In the past, I've found them circling the bones of large beasts to the north of Falcon Watch.",logDesc="Gather 8 Bonestripper Tail Feathers from Bonestripper Vultures and bring them to Falconer Drenna Riverwind at Falcon Watch."} end
if not DB[9382] then DB[9382]={id=9382,zoneId=3483,name="The Fate of the Clefthoof",level=63,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=9382",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Greetings, $c.$B$BI'm certain your travels in Outland have shown you something of the corruption in this world. It is so pervasive that it has transformed the very creatures who dwell here - the ones that survived, that is.$B$BThe clefthoof to the south and west were once docile grazers, but the corruption has created an unquenchable rage in them. They only find release from their torment in death, though it grieves us to spill their blood. Will you help me end the suffering of the bristlehide clefthoof?",logDesc="Kill 15 Bristlehide Clefthoof and return to Amaan the Wise at the Temple of Telhamat.",choiceRewards={{id=25787,qty=1},{id=25786,qty=1}}} end
if not DB[9383] then DB[9383]={id=9383,zoneId=3483,name="An Ambitious Plan",level=63,minLevel=61,giver="Elsaana",giverType="NPC",giverId=17006,ender="Elsaana",enderType="NPC",enderId=17006,poiX=219,poiY=4341,wowhead="https://www.wowhead.com/wotlk/quest=9383",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="The blood elves epitomize the irresponsible use of magic, $c. They do not control magical energy. Rather, they are slaves to it and will suffer nothing to stand between them and their addiction. They consume the energies of Outland's voidwalkers to power their demonic magics.$B$BI've prepared a crystal charged with a spell that will allow us to neutralize a voidwalker and sever its link to this world when destroyed. I've mostly seen the voidwalkers in the Warp Fields to the southeast of Hellfire Citadel.",logDesc="Use the Sanctified Crystal against a wounded Uncontrolled Voidwalker and return to Elsaana at the Temple of Telhamat."} end
if not DB[9384] then DB[9384]={id=9384,zoneId=3483,name="<NYI>Harnessing the Light",level=63,minLevel=61,wowhead="https://www.wowhead.com/wotlk/quest=9384",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Now,the time has come to destroy this demon. I counsel caution in this,$N,for there is much you do not yet know about the voidwalkers of Outland.$B$BTake this vessel to Rumatu,who will see to its destruction. Observe the process carefully and report to me when it is finished.",logDesc="Take the Glowing Sanctified Crystal to Rumatu at the Temple of Sha'naar,who will invoke the Light to smite the demon within."} end
if not DB[9385] then DB[9385]={id=9385,zoneId=3483,name="Rampaging Ravagers",level=63,minLevel=60,giver="Gremni Longbeard",giverType="NPC",giverId=16850,ender="Gremni Longbeard",enderType="NPC",enderId=16850,poiX=-1004,poiY=4306,wowhead="https://www.wowhead.com/wotlk/quest=9385",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="So Honor Hold sends us to deal with the arakkoa and we set up camp here thinking hey isn't this a great spot.  Little did we know how close we were to the quillfang ravagers.$B$BThey are relentless predators and have made any sort of work on our part impossible.  There's a bit of coin in it for you if you can deal with them for us.  Do you feel up to it?",logDesc="Kill 10 Quillfang Ravagers and return to Gremni Longbeard in Hellfire Peninsula."} end
if not DB[9386] then DB[9386]={id=9386,zoneId=-369,name="A Light in Dark Places",level=-1,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=9386",image="assets/images/quests/placeholder.png",desc="An eager one, aren't you? If you're willing to enter the depths once more, I'll gladly reward you.$b$bSeek out the bonfires burning within Stratholme, Scholomance, Dire Maul, and the halls of Blackrock Spire itself; I look forward to your return, $n.",logDesc="Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then speak with the Festival Flamekeeper.",rewards={{id=23247,qty=10}}} end
if not DB[9387] then DB[9387]={id=9387,zoneId=3483,name="Source of the Corruption",level=63,minLevel=60,giver="Apothecary Azethen",giverType="NPC",giverId=16794,ender="Apothecary Azethen",enderType="NPC",enderId=16794,poiX=-575,poiY=4156,wowhead="https://www.wowhead.com/wotlk/quest=9387",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Uncorrupted draenei, like this unlucky fellow here, are virtuous champions of the Light.  What corruption caused their great race to devolve into the Broken and Lost Ones?$B$BI've heard a theory that exposure to fel energies is what caused the mutation.  I would like to put that theory to the test.$B$BNorthwest of here lie the Ruins of Sha'naar.  There you will find lowly Broken commanded by Illidari taskmasters.  Bring me demonic essences from the taskmasters so that I can test them on this draenei.",logDesc="Travel to the Ruins of Sha'naar in Hellfire Peninsula and obtain 5 Demonic Essences from the Illidari Taskmasters.  Return to Apothecary Azethen at Falcon Watch after you've completed the task.",choiceRewards={{id=25914,qty=1},{id=25915,qty=1},{id=25913,qty=1}}} end
if not DB[9388] then DB[9388]={id=9388,zoneId=-369,name="Flickering Flames in Kalimdor",level=25,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9388",image="assets/images/quests/placeholder.png",xpDiff=4,desc="There are many flames burning throughout the world today, $n. The trickiest fires to tend are those that burn green; they do not stay lit long without supervision. Make certain the emerald fires still burn on Kalimdor for our Flamekeeper, eh?$b$bYou will find them near Ratchet in the Barrens, close to the Master's Glaive in Darkshore, in the forest of Ashenvale by the bridge near Silverwing Outpost, and near the road to Windshear Crag along the main road in Stonetalon Mountains.",logDesc="Visit the bonfires within Ashenvale, the Barrens, Darkshore, and Stonetalon Mountains, then speak with the Festival Flamekeeper.",choiceRewards={{id=23435,qty=5},{id=23327,qty=4},{id=23326,qty=5},{id=23211,qty=5}}} end
if not DB[9389] then DB[9389]={id=9389,zoneId=-369,name="Flickering Flames in the Eastern Kingdoms",level=25,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9389",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The Midsummer Fire Festival traditionally lights up the land with a myriad of flames. Some argue that the green fires are the finest, as they are the hardest to maintain and have such a distinctive hue.$b$bMake sure they still burn in the Eastern Kingdoms for our Flamekeeper. They sit near Dun Modr in the Wetlands, close to Pyrewood Village within Silverpine Forest, on the cliffs overlooking the lighthouse in Westfall, and by the ruined tower in Hillsbrad Foothills.",logDesc="Visit the bonfires within Hillsbrad Foothills, Silverpine Forest, Westfall, and the Wetlands, then speak with the Festival Flamekeeper.",choiceRewards={{id=23435,qty=5},{id=23327,qty=4},{id=23326,qty=5},{id=23211,qty=5}}} end
if not DB[9390] then DB[9390]={id=9390,zoneId=3483,name="In Search of Sedai",level=62,minLevel=60,giver="Anchorite Obadei",giverType="NPC",giverId=16834,ender="Sedai's Corpse",enderType="NPC",enderId=16852,rewardNextId=9423,poiX=91,poiY=4352,wowhead="https://www.wowhead.com/wotlk/quest=9390",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hear my plight, $c.  My brother, Sedai, left long ago to contact the orcs of Mag'har Post.  Ever the idealist, he thought the time was ripe to set our differences aside and negotiate a peace with them.$B$BHe's been missing for days and I fear for the worst.$B$BWould you set my mind to rest and look for him?  Sedai must be somewhere nearby to the east.",logDesc="Anchorite Obadei wants you to look for his brother, Sedai, nearby to the east in Hellfire Peninsula."} end
if not DB[9391] then DB[9391]={id=9391,zoneId=3483,name="Marking the Path",level=62,minLevel=60,giver="Ranger Captain Venn'ren",giverType="NPC",giverId=16789,ender="Ranger Captain Venn'ren",enderType="NPC",enderId=16789,poiX=-593,poiY=4068,wowhead="https://www.wowhead.com/wotlk/quest=9391",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="With the rock flayer population thinned, all that's left is to signal the safe path to our pilgrims.  Return to the Great Fissure with this torch and seek the three beacons that mark the path from the east.$B$BLight the three beacons and return to me.  Be warned that the beacons will attract any nearby rock flayers when you first light them.",logDesc="Ranger Captain Venn'ren at Falcon Watch wants you to go to the Great Fissure in Hellfire Peninsula and light the Southern Beacon, Western Beacon and Central Beacon.  Return to him with the Lit Torch after you've completed this task.",choiceRewards={{id=25503,qty=1},{id=25502,qty=1},{id=25504,qty=1}}} end
if not DB[9392] then DB[9392]={id=9392,zoneId=-162,name="Rogue Training",level=1,minLevel=1,giver="Magistrix Erona",giverType="NPC",giverId=15278,ender="Pathstalker Kariel",enderType="NPC",enderId=15285,poiX=10352,poiY=-6360,wowhead="https://www.wowhead.com/wotlk/quest=9392",image="assets/images/quests/placeholder.png",xpDiff=3,desc="As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young rogues here on Sunstrider Isle, your trainer is Pathstalker Kariel.  Speak with Kariel and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.$B$BKariel - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.",logDesc="Speak with Pathstalker Kariel - the Rogue class trainer - inside the Sunspire on Sunstrider Isle."} end
if not DB[9393] then DB[9393]={id=9393,zoneId=-261,name="Hunter Training",level=1,minLevel=1,giver="Magistrix Erona",giverType="NPC",giverId=15278,ender="Ranger Sallina",enderType="NPC",enderId=15513,poiX=10352,poiY=-6360,wowhead="https://www.wowhead.com/wotlk/quest=9393",image="assets/images/quests/placeholder.png",xpDiff=3,desc="As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young hunters here on Sunstrider Isle, your trainer is Ranger Sallina.  Speak with Sallina and see what training she has available for you.  The things she will teach do have a cost, so bring some coin with you.$B$BSallina - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.",logDesc="Speak with Ranger Sallina - the Hunter class trainer - inside the Sunspire on Sunstrider Isle."} end
if not DB[9394] then DB[9394]={id=9394,zoneId=3430,name="Where's Wyllithen?",level=10,minLevel=8,giver="Apprentice Loralthalis",giverType="NPC",giverId=15924,ender="Groundskeeper Wyllithen",enderType="NPC",enderId=15969,rewardNextId=8894,poiX=9186,poiY=-7827,wowhead="https://www.wowhead.com/wotlk/quest=9394",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Duskwither groundskeeper has gone missing! Someone must have forgotten to tell him to leave when the magister and everyone else did.  I know that he's still somewhere around here on the grounds, but I dare not go looking for him myself with all of these magical creatures roaming about.$B$BWill you find him for me, $c, and make sure that he's alright?",logDesc="Find Groundskeeper Wyllithen on the Duskwither Grounds in Eversong Woods."} end
if not DB[9395] then DB[9395]={id=9395,zoneId=3430,name="Saltheril's Haven",level=9,minLevel=8,giver="Magistrix Landra Dawnstrider",giverType="NPC",giverId=16210,ender="Lord Saltheril",enderType="NPC",enderId=16144,rewardNextId=9067,poiX=8718,poiY=-6656,wowhead="https://www.wowhead.com/wotlk/quest=9395",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I swear that I'm going to fireball someone if I get one more request from Lord Saltheril concerning supplies for his party!  Do I look like a party planner?!  Between you and me, that fool and his sycophants are living in denial that we're under attack here!$B$BSome of us are actually busy with, oh, I don't know, defending what's left of Quel'Thalas!  $C, would you please head over to Saltheril's Haven and see if you can shut him up?  It's just down the road to the west.",logDesc="Speak with Lord Saltheril at Saltheril's Haven in Eversong Woods."} end
if not DB[9396] then DB[9396]={id=9396,zoneId=3483,name="Magic of the Arakkoa",level=62,minLevel=60,giver="Arcanist Calesthris Dawnstar",giverType="NPC",giverId=16792,ender="Arcanist Calesthris Dawnstar",enderType="NPC",enderId=16792,poiX=-577,poiY=4143,wowhead="https://www.wowhead.com/wotlk/quest=9396",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Outland holds many secrets, $N.  It's only a matter of time before we uncover them all.$B$BThe half-bird, half-man species of the arakkoa possesses ancient arcane knowledge that would aid us greatly in our exploration of this world.  Travel to the Den of Haal'esh, south of here.  Obtain any magical scrolls that the Haal'eshi might be carrying on them and bring them to me.",logDesc="Bring 4 Haal'eshi Scrolls to Arcanist Calesthris Dawnstar at Falcon Watch in Hellfire Peninsula."} end
if not DB[9397] then DB[9397]={id=9397,zoneId=3483,name="Birds of a Feather",level=62,minLevel=60,giver="Falconer Drenna Riverwind",giverType="NPC",giverId=16790,ender="Falconer Drenna Riverwind",enderType="NPC",enderId=16790,poiX=-596,poiY=4108,wowhead="https://www.wowhead.com/wotlk/quest=9397",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="The Haal'eshi arakkoa have domesticated a beautiful bird species called the kaliri.$B$BI've managed to capture a young male and they appear to be trainable.  The females are much rarer, but if I had one I could attempt to breed them.  She has to be young, though... a hatchling.  An older wild bird wouldn't survive in captivity.$B$BTake this cage and travel south, to the Den of Haal'esh.  Search the nests for eggs that are ready to hatch.  If you bring me back a female hatchling, I'll reward you handsomely.",logDesc="Travel to the Den of Haal'esh in Hellfire Peninsula and search the Kaliri Nests for a Female Kaliri Hatchling.  Use the Empty Birdcage to capture it and bring it to Falconer Drenna Riverwind at Falcon Watch."} end
if not DB[9398] then DB[9398]={id=9398,zoneId=3483,name="Deadly Predators",level=62,minLevel=60,giver="Scout Vanura",giverType="NPC",giverId=16797,ender="Scout Vanura",enderType="NPC",enderId=16797,poiX=74,poiY=4333,wowhead="https://www.wowhead.com/wotlk/quest=9398",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="The Broken that live in Outland have endured endless violence.  It is of little surprise that as soon as the Dark Portal opened they flocked to it in droves with hopes of escaping this land.$B$BUnfortunately for our confused brothers and sisters coming from the south, the rock flayers that inhabit the Great Fissure see them as easy prey.  Go there and thin the rock flayer population, so that our kin might have a chance.",logDesc="Scout Vanura at the Temple of Telhamat in Hellfire Peninsula wants you to slay 8 Stonescythe Whelps and 4 Stonescythe Alpha."} end
if not DB[9399] then DB[9399]={id=9399,zoneId=3483,name="Cruel Taskmasters",level=63,minLevel=60,giver="Ikan",giverType="NPC",giverId=16799,ender="Ikan",enderType="NPC",enderId=16799,poiX=96,poiY=4347,wowhead="https://www.wowhead.com/wotlk/quest=9399",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="You probably think most Broken are evil, don't you?  In reality many just lack guidance.$B$BBefore I met the Omenai, I too was lost.$B$BOur minds suffered terrible pain from the orcs' demonic magic.  We are easily confused and taken advantage of.$B$BDemons allied with Illidan raid Hellfire daily and capture our kind as slaves.  With the Omenai we now have hope.  Travel to the Ruins of Sha'naar, southwest of here, and slay the Illidari taskmasters so my people may be free!",logDesc="Slay 4 Illidari Taskmasters at the Ruins of Sha'naar and return to Ikan at the Temple of Telhamat in Hellfire Peninsula."} end
if not DB[9400] then DB[9400]={id=9400,zoneId=3483,name="The Assassin",level=62,minLevel=60,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Fel Orc Corpse",enderType="NPC",enderId=17062,rewardNextId=9401,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=9400",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$n, we recently uncovered a plot to assassinate our envoy to Falcon Watch.  Hellfire Citadel learned of our plans to send an expedition there earlier this morning and set up an ambush.$B$BOur scouts have informed me that an assassin known as Krun Spinebreaker waits along the road north of the Citadel.  Go there and slay this assassin.  Show the fel orcs we're not to be trifled with!",logDesc="Nazgrel wants you to travel to the road north of Hellfire Citadel and look for an assassin named Krun Spinebreaker."} end
if not DB[9401] then DB[9401]={id=9401,zoneId=3483,name="A Strange Weapon",level=62,minLevel=60,giver="Fel Orc Corpse",giverType="NPC",giverId=17062,ender="Nazgrel",enderType="NPC",enderId=3230,rewardNextId=9405,poiX=-18,poiY=3803,wowhead="https://www.wowhead.com/wotlk/quest=9401",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="You pull the stone axe out of the body to examine it more closely.  There's something unusual about the craftsmanship of the weapon.$B$BIts origin appears orcish, though the materials aren't like anything you've seen before.  Nazgrel might be interested in seeing the weapon.",logDesc="Bring the Heavy Stone Axe to Nazgrel in Thrallmar in Hellfire Peninsula."} end
if not DB[9402] then DB[9402]={id=9402,zoneId=-161,name="Fetch!",level=10,minLevel=10,giver="Instructor Antheol",giverType="NPC",giverId=15970,ender="Instructor Antheol",enderType="NPC",enderId=15970,rewardNextId=9403,poiX=9252,poiY=-7231,wowhead="https://www.wowhead.com/wotlk/quest=9402",image="assets/images/quests/placeholder.png",xpDiff=2,desc="So... $n is it?  Don't be flattered I know your name, one of my students has been fawning over you and won't shut up.$b$bHmm... if you'd like to impress $gher:him;, why don't you do something for me?  There's an azure phial at the bottom of the pond behind me.  Dive in, retrieve it, and bring it here.",logDesc="Dive to the bottom of Stillwhisper Pond and retrieve the Azure Phial for Instructor Antheol."} end
if not DB[9403] then DB[9403]={id=9403,zoneId=-161,name="The Purest Water",level=10,minLevel=10,giver="Instructor Antheol",giverType="NPC",giverId=15970,ender="Instructor Antheol",enderType="NPC",enderId=15970,rewardNextId=9404,poiX=9252,poiY=-7231,wowhead="https://www.wowhead.com/wotlk/quest=9403",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now that you've learned a little lesson, I'll offer you something more substantial.  It concerns your ability to defend yourself in close combat.  Of course, you should only resort to melee in the most dire of circumstances, but that is no excuse to be unprepared.$b$bI can assist you in creating a staff befitting a mage of your learning.  Simply take the phial you retrieved for me and fill it at the base of Elrendar Falls.  Just follow the river southeast from here.",logDesc="Instructor Antheol wants you to fill the Azure Phial at Elrendar Falls."} end
if not DB[9404] then DB[9404]={id=9404,zoneId=-161,name="Recently Living",level=10,minLevel=10,giver="Instructor Antheol",giverType="NPC",giverId=15970,ender="Instructor Antheol",enderType="NPC",enderId=15970,poiX=9252,poiY=-7231,wowhead="https://www.wowhead.com/wotlk/quest=9404",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You may have noticed the walking trees near Elrendar Falls.  As the keepers of nature, they are infused with a primal magic we can reform to our own purposes using the pure water you have already brought to me.$b$bUnfortunately, the green keepers are gnarled and twisted creatures, so you may need to kill a few before you find a useable branch.",logDesc="Slay the Eversong Green Keepers until they yield a Living Branch for Instructor Antheol.",choiceRewards={{id=9513,qty=1},{id=7508,qty=1}}} end
if not DB[9405] then DB[9405]={id=9405,zoneId=3483,name="The Warchief's Mandate",level=62,minLevel=60,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Far Seer Regulkut",enderType="NPC",enderId=16574,rewardNextId=9410,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=9405",image="assets/images/quests/placeholder.png",xpDiff=3,desc="As you know, the warchief put his power behind this expedition for one reason.  This is the world we came from.  This is where our roots lie.$B$BThis journey means different things to orcs and blood elves.  To them it's a search for the promised land.  To us it's more like returning home.$B$BWhoever made this axe is familiar with the old ways and we must contact them.  This is too important for us to use ordinary tracking methods.  Show the weapon to Far Seer Regulkut; she will know what to do.",logDesc="Bring the Heavy Stone Axe to Far Seer Regulkut at Thrallmar in Hellfire Peninsula."} end
if not DB[9406] then DB[9406]={id=9406,zoneId=3483,name="The Mag'har",level=62,minLevel=60,giver="Gorkan Bloodfist",giverType="NPC",giverId=16845,ender="Nazgrel",enderType="NPC",enderId=3230,rewardNextId=9438,poiX=524,poiY=3887,wowhead="https://www.wowhead.com/wotlk/quest=9406",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This news you bring from beyond the Dark Portal...  you want us to believe the son of Durotan now rules over the lands beyond it... free from any demonic taint?  And that now his people have returned to this world?$B$BI hope for your sake that this isn't some manner of joke, $c.  What this means to my people... cannot be described.  I must send word to Nagrand at once!  Hellscream must hear about this.$B$BTake this letter back to your leader in Thrallmar.  Tell him the Mag'har welcome them!",logDesc="Deliver the Letter from the Mag'har to Nazgrel at Thrallmar in Hellfire Peninsula."} end
if not DB[9407] then DB[9407]={id=9407,zoneId=3483,name="Through the Dark Portal",level=61,minLevel=58,giver="Warlord Dar'toon",giverType="NPC",giverId=19254,ender="Lieutenant General Orion",enderType="NPC",enderId=19253,rewardNextId=10120,poiX=-11817,poiY=-3188,wowhead="https://www.wowhead.com/wotlk/quest=9407",image="assets/images/quests/placeholder.png",xpDiff=2,desc="For years the Dark Portal loomed silent... forgotten.  But it is silent no longer.$B$BAfter stopping the demonic assault here, our forces breached the portal and met the demons on their own ground!$B$BNow, we are locked in a savage war, and there are some who think we might not win.  So it is our duty, our grim pleasure, to battle the fiends of Outland and ensure our victory, $N.$B$BIf you would help us, then report to Lieutenant General Orion at once. He awaits you in the Outland...$B",logDesc="Travel through the Dark Portal and find Lieutenant General Orion. He awaits your arrival on the other side, in Outland.$B"} end
if not DB[9408] then DB[9408]={id=9408,zoneId=3483,name="Forgotten Heroes",level=60,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=9408",image="assets/images/quests/placeholder.png",xpDiff=1,desc="While it pains me to know that we have lost so many soldiers in our efforts to breach the portal, my heart swells with pride to know that the original expeditionary force is still alive.$B$BI can hardly believe it; but here they stand - a testament to the resolve of the Alliance.$B$BInside that keep stands one of our greatest heroes: Danath Trollbane! Seek him out, $c. He has already met and addressed all of our soldiers. He will surely want to meet you.",logDesc="Speak with Force Commander Danath Trollbane at Honor Hold."} end
if not DB[9409] then DB[9409]={id=9409,zoneId=3526,name="Urgent Delivery!",level=2,minLevel=1,giver="3",giverType="NPC",giverId=16477,ender="Zalduun",enderType="NPC",enderId=16502,rewardNextId=9283,poiX=-4039,poiY=-13774,wowhead="https://www.wowhead.com/wotlk/quest=9409",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Now that you've gathered all that we need to replenish our healing crystals, I need you to deliver the vials to Zalduun, our priest.  You'll find him tending to our wounded inside the central chamber of the ship.",logDesc="Deliver the Bundle of Vials to Zalduun at the Crash Site in Ammen Vale."} end
if not DB[9410] then DB[9410]={id=9410,zoneId=3483,name="A Spirit Guide",level=62,minLevel=60,giver="Far Seer Regulkut",giverType="NPC",giverId=16574,ender="Gorkan Bloodfist",enderType="NPC",enderId=16845,rewardNextId=9406,poiX=176,poiY=2739,wowhead="https://www.wowhead.com/wotlk/quest=9410",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Even our best tracking wolves' senses can fail them, $N.  The spirits have a way of seeing the world differently than ours.  The being you will call forth will find the person you seek, for they'll be drawn not to their scent but their essence.$B$BGo now, $c, take this totem with you and use it at the location you found the stone axe.",logDesc="Use the Wolf Totem at the location where you found Krun Spinebreaker's body and follow the Ancestral Spirit Wolf."} end
if not DB[9411] then DB[9411]={id=9411,zoneId=0,name="<UNUSED>Infused Bandages",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9411",image="assets/images/quests/placeholder.png",rewards={{id=23689,qty=1}}} end
if not DB[9412] then DB[9412]={id=9412,zoneId=0,name="<UNUSED>Crystal Flake Throat Lozenge",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9412",image="assets/images/quests/placeholder.png"} end
if not DB[9413] then DB[9413]={id=9413,zoneId=0,name="<UNUSED>Crystal Flake Throat Lozenge",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9413",image="assets/images/quests/placeholder.png"} end
if not DB[9414] then DB[9414]={id=9414,zoneId=0,name="<UNUSED>Infused Bandages",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9414",image="assets/images/quests/placeholder.png",rewards={{id=23689,qty=1}}} end
if not DB[9415] then DB[9415]={id=9415,zoneId=1377,name="Report to Marshal Bluewall",level=60,minLevel=55,giver="Rifleman Torrig",giverType="NPC",giverId=17082,ender="Marshal Bluewall",enderType="NPC",enderId=17080,rewardNextId=9419,poiX=-6765,poiY=772,wowhead="https://www.wowhead.com/wotlk/quest=9415",image="assets/images/quests/placeholder.png",desc="Are you Marshal Bluewall's new recruits? Of course you are.$b$bWhat are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them?$b$bNow, get going and don't dry out on the way.",logDesc="Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora."} end
if not DB[9416] then DB[9416]={id=9416,zoneId=1377,name="Report to General Kirika",level=60,minLevel=55,giver="Scout Bloodfist",giverType="NPC",giverId=17081,ender="General Kirika",enderType="NPC",enderId=17079,rewardNextId=9422,poiX=-6811,poiY=832,wowhead="https://www.wowhead.com/wotlk/quest=9416",image="assets/images/quests/placeholder.png",desc="You must be one of General Kirika's new recruits. It's about time you showed up. Bodies wear down quick in the desert.$b$bThe dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus.$b$bGet your instructions from the General. It's not my job to train you, just find you.",logDesc="Speak with General Kirika at the Horde encampment near Hive'Regal."} end
if not DB[9417] then DB[9417]={id=9417,zoneId=3483,name="The Arakkoa Threat",level=63,minLevel=60,giver="Gremni Longbeard",giverType="NPC",giverId=16850,ender="Gremni Longbeard",enderType="NPC",enderId=16850,poiX=-1004,poiY=4306,wowhead="https://www.wowhead.com/wotlk/quest=9417",image="assets/images/quests/placeholder.png",xpDiff=5,money=58000,desc="The arakkoa are smart creatures... smart as any gnome you ever met.  They have this way with magic and a violent temper, however. $B$BLately they've taken to attacking Honor Hold patrols, which is why we were sent here.  See, Mirren and I are world-famous marksmen, we are!  But fowl and game are what we specialize in... not these... lightning-invoking birdmen.$B$BSo what do you say you give us a hand in this one assignment?  You'll find the Den of Haal'esh to the southwest.",logDesc="Gremni Longbeard in Hellfire Peninsula wants you to slay 4 Haal'eshi Windwalkers and 6 Haal'eshi Talonguards."} end
if not DB[9418] then DB[9418]={id=9418,zoneId=3483,name="Avruu's Orb",level=63,minLevel=60,ender="Aeranas",enderType="NPC",enderId=17085,wowhead="https://www.wowhead.com/wotlk/quest=9418",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<As you hold the orb closer to you, you hear a voice address you.>$B$BI sense you're not of the arakkoa, so I will attempt to barter for my freedom.  My name is Aeranas. I once ruled over the eastern winds.  The Haal'eshi mage, Avruu, trapped me inside this orb.$B$BFind the altar the arakkoa used to enslave me.  It is hidden to the southeast of the arakkoa's den.  Approach it with the orb and give it to me once I'm free.  In exchange for my liberty I'll reward you with powerful treasure!",logDesc="Take Avruu's Orb to the Haal'eshi Altar southeast of the Den of Haal'esh in Hellfire Peninsula and give it to Aeranas once he's free.",choiceRewards={{id=25489,qty=1},{id=25488,qty=1},{id=25487,qty=1}}} end
if not DB[9419] then DB[9419]={id=9419,zoneId=1377,name="Scouring the Desert",level=60,minLevel=55,giver="Marshal Bluewall",giverType="NPC",giverId=17080,ender="Marshal Bluewall",enderType="NPC",enderId=17080,poiX=-7144,poiY=1378,wowhead="https://www.wowhead.com/wotlk/quest=9419",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We recently found out that the Horde has been scavenging the Silithus desert for resources, but paid them little mind. We thought it could not be worth it to station large numbers in this sweltering desert.$b$bHowever, it was discovered the importance of the resources, and now we are scrambling to catch up.$b$bIf I have your assistance, you must go into the desert and recover the silithyst and return it here.",logDesc="Find and deliver Silithyst to the Silithyst Extractor, then speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.",choiceRewards={{id=13446,qty=2},{id=13444,qty=2}}} end
if not DB[9420] then DB[9420]={id=9420,zoneId=3483,name="The Finest Down",level=62,minLevel=60,giver="Mirren Longbeard",giverType="NPC",giverId=16851,ender="Mirren Longbeard",enderType="NPC",enderId=16851,poiX=-1010,poiY=4301,wowhead="https://www.wowhead.com/wotlk/quest=9420",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="The arakkoa at the Den of Haal'esh, south of here, breed a magnificent species of birds called kaliri.  Their feathers would fetch a bundle at the trading posts back in Azeroth.  Just think of all the ale I could buy then!$B$BTell you what, you bring me a stack of kaliri feathers and I'll give you my very own hat.  What do you say?  You'll never find a hat like this one!  Do we have a deal?",logDesc="Mirren Longbeard in Hellfire Peninsula wants you to bring him 8 Kaliri Feathers from the various kaliri found in the Den of Haal'esh.",rewards={{id=23587,qty=1}}} end
if not DB[9421] then DB[9421]={id=9421,zoneId=-82,name="Shaman Training",level=2,minLevel=1,giver="Firmanvaar",giverType="NPC",giverId=17089,ender="Firmanvaar",enderType="NPC",enderId=17089,poiX=-4127,poiY=-13727,wowhead="https://www.wowhead.com/wotlk/quest=9421",image="assets/images/quests/placeholder.png",xpDiff=3} end
if not DB[9422] then DB[9422]={id=9422,zoneId=1377,name="Scouring the Desert",level=60,minLevel=55,giver="General Kirika",giverType="NPC",giverId=17079,ender="General Kirika",enderType="NPC",enderId=17079,poiX=-7574,poiY=770,wowhead="https://www.wowhead.com/wotlk/quest=9422",image="assets/images/quests/placeholder.png",xpDiff=5,desc="For some time now, we have been tapping the crystal resources of the Silithus desert. The only dangers we faced were from the creatures that made this place their home and the oppressive sand and dust and heat.$b$bBut now the Alliance seems to have caught on to what we have found here. It is now a race between us to capture the natural resources, and keep them from the other.$b$bI need every set of hands that is available. I hope I have yours.",logDesc="Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.",choiceRewards={{id=13446,qty=2},{id=13444,qty=2}}} end
if not DB[9423] then DB[9423]={id=9423,zoneId=3483,name="Return to Obadei",level=62,minLevel=60,giver="Sedai's Corpse",giverType="NPC",giverId=16852,ender="Anchorite Obadei",enderType="NPC",enderId=16834,poiX=192,poiY=4151,wowhead="https://www.wowhead.com/wotlk/quest=9423",image="assets/images/quests/placeholder.png",xpDiff=2,desc="With Sedai's death confirmed, you're left with the unpleasant task of returning to Obadei with the grim news.",logDesc="Return to Anchorite Obadei at the Temple of Telhamat in Hellfire Peninsula and inform him of Sedai's death."} end
if not DB[9424] then DB[9424]={id=9424,zoneId=3483,name="Makuru's Vengeance",level=63,minLevel=60,giver="Makuru",giverType="NPC",giverId=16833,ender="Makuru",enderType="NPC",enderId=16833,poiX=98,poiY=4345,wowhead="https://www.wowhead.com/wotlk/quest=9424",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Sedai was like a brother to Makuru.   We owe him our lives and more!  They call Makuru crazy but if the Omenai are not going to do anything about his death then they're the crazy ones!$B$BMakuru doesn't have much to call his own in this world, but he will give you his only possession if you avenge Sedai.  $B$BI've seen the brown orc Mag'har grunts before, up in the hills to the northeast.  They hate us!  They don't deserve our mercy!  Go, avenge Sedai!  Bring me their ancestral beads as proof!",logDesc="Makuru at the Temple of Telhamat in Hellfire Peninsula wants you to bring him 10 Mag'har Ancestral Beads.",choiceRewards={{id=25920,qty=1},{id=25919,qty=1},{id=25921,qty=1}}} end
if not DB[9425] then DB[9425]={id=9425,zoneId=267,name="Report to Tarren Mill",level=20,minLevel=18,giver="Ambassador Sunsorrow",giverType="NPC",giverId=16287,ender="Advisor Duskingdawn",enderType="NPC",enderId=17092,poiX=1298,poiY=319,wowhead="https://www.wowhead.com/wotlk/quest=9425",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ah, good to see you here, $c!  I've a task that you are perfectly suited to.$B$BAs new members of the Horde, we need to make sure that we support their efforts and help them with their problems.  That way they'll be more receptive to helping us with ours.$B$BTravel to the Forsaken town, Tarren Mill, in the Hillsbrad Foothills to the southeast.  Check in with Advisor Duskingdawn when you arrive.",logDesc="Travel to Tarren Mill in the Hillsbrad Foothills and speak with Advisor Duskingdawn."} end
if not DB[9426] then DB[9426]={id=9426,zoneId=3483,name="The Pools of Aggonar",level=62,minLevel=60,giver="Amaan the Wise",giverType="NPC",giverId=16796,ender="Amaan the Wise",enderType="NPC",enderId=16796,rewardNextId=9427,poiX=223,poiY=4330,wowhead="https://www.wowhead.com/wotlk/quest=9426",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Much has changed since the days when we called this land Draenor.  Parts of the land have been forever changed by the demons' taint.$B$BOne such place is known as the Pools of Aggonar.  It was once the location of our people's sacred springs.  The blood of the demon Aggonar fouled the very essence of the holy waters.  This fel blood has spawned foul beings that must be cleansed if we're ever to reclaim the pools.  Travel east of here and slay the Terrorfiends and slimes that wander the pools.",logDesc="Amaan the Wise wants you to go to the Pools of Aggonar and slay 6 Terrorfiends and 6 Blistering Rots."} end
if not DB[9427] then DB[9427]={id=9427,zoneId=3483,name="Cleansing the Waters",level=62,minLevel=60,giver="Amaan the Wise",giverType="NPC",giverId=16796,ender="Amaan the Wise",enderType="NPC",enderId=16796,poiX=223,poiY=4330,wowhead="https://www.wowhead.com/wotlk/quest=9427",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I must ask that you finish what we've set in motion.  Now that the demonic influence has weakened you must take this cleansing vial and pour it at the very source of the taint - Aggonar's own corpse.$B$BYou will find the demon's bones at the northern end of the pools.  Beware, I sense that Aggonar's essence has not quite left this world.",logDesc="Amaan the Wise wants you to travel to the Pools of Aggonar and use the Cleansing Vial at Aggonar's corpse.  Return to him when Aggonar's essence is cleansed from the water.",choiceRewards={{id=25484,qty=1},{id=25486,qty=1},{id=25485,qty=1}}} end
if not DB[9428] then DB[9428]={id=9428,zoneId=331,name="Report to Splintertree Post",level=20,minLevel=18,giver="Ambassador Dawnsinger",giverType="NPC",giverId=17098,ender="Advisor Sunsworn",enderType="NPC",enderId=17100,poiX=1915,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=9428",image="assets/images/quests/placeholder.png",xpDiff=3,desc="<The ambassador keeps her voice low as she leans in close.>$B$BYour reputation precedes you, $N.  I want you to travel to Splintertree Post in Ashenvale.  The easiest way to get there on foot is to travel west through Durotar and the Barrens, and then turn north at the fork in the road.$B$BWhen you arrive, speak with Advisor Sunsworn.  Travel carefully; Ashenvale can be a very dangerous place!",logDesc="Travel to Splintertree Post in Ashenvale and speak with Advisor Sunsworn."} end
if not DB[9429] then DB[9429]={id=9429,zoneId=10,name="Travel to Darkshire",level=20,minLevel=18,giver="Emissary Taluun",giverType="NPC",giverId=17103,ender="Anchorite Delan",enderType="NPC",enderId=17104,poiX=-8443,poiY=325,wowhead="https://www.wowhead.com/wotlk/quest=9429",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I am told that there is a thorn in the side of the kingdom of Stormwind.  It is known as Duskwood, and it is a place that is filled with evil and the vile stench of undeath.$B$BAs we're trying to help as much as we can, I would like for you to travel southeast to the main human settlement there, named Darkshire.  Anchorite Delan will be awaiting your arrival.",logDesc="Travel to Darkshire in Duskwood and speak with Anchorite Delan."} end
if not DB[9430] then DB[9430]={id=9430,zoneId=3483,name="Sha'naar Relics",level=63,minLevel=60,giver="Amaan the Wise",giverType="NPC",giverId=16796,ender="Amaan the Wise",enderType="NPC",enderId=16796,rewardNextId=9545,poiX=223,poiY=4330,wowhead="https://www.wowhead.com/wotlk/quest=9430",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As I've told you before, I do not require eyes to see what others cannot.  I will not pass judgment on what you did on Makuru's behalf, yet I think you need to see beyond what your eyes show you.$B$BTravel southwest to the Ruins of Sha'naar and salvage any relics you find.  If fate wills it you will find what we need.$B$BThe meaning of my request might not be immediately apparent.  Have faith though, $N.  Clarity comes to those with patience.",logDesc="Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula wants you to travel to the Ruins of Sha'naar and retrieve 10 Sha'naar Relics."} end
if not DB[9431] then DB[9431]={id=9431,zoneId=400,name="A Different Approach",level=28,minLevel=24,giver="Magistrix Elosai",giverType="NPC",giverId=17093,ender="Wizlo Bearingshiner",enderType="NPC",enderId=10941,rewardNextId=9433,poiX=-5445,poiY=-2467,wowhead="https://www.wowhead.com/wotlk/quest=9431",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="What's a sin'dorei doing standing on the top of a windswept butte in Thousand Needles instead of the halls of Silvermoon?$B$BIt's simple. My brethren will no longer have me. Every copy of my treatise on natural cures for our magical addiction was burned.$B$BI can safely pursue my research here, but I am without my reagents. If you'd be willing to gather purifying earth from the thundering boulderkin near the western end of the Needles and deliver it to my associate at Whitereach Post, I'd appreciate it.",logDesc="Gather 2 handfuls of Purifying Earth from Thundering Boulderkin and take them to Wizlo Bearingshiner at Whitereach Post."} end
if not DB[9432] then DB[9432]={id=9432,zoneId=331,name="Travel to Astranaar",level=20,minLevel=18,giver="Emissary Valustraa",giverType="NPC",giverId=17105,ender="Vindicator Palanaar",enderType="NPC",enderId=17106,poiX=9664,poiY=2529,wowhead="https://www.wowhead.com/wotlk/quest=9432",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I am glad that you are here to help.  In fact, there is something that you can do.$B$BAs part of our inclusion within the Alliance, I would like for you to travel to the night elf town, Astranaar.  It is located in Ashenvale, a large forest that is south of Darkshore on the continent of Kalimdor.$B$BPlease speak with Vindicator Palais when you arrive to see if there's anything that you can do to help the inhabitants.",logDesc="Travel to Astranaar in Ashenvale and speak with Vindicator Palais."} end
if not DB[9433] then DB[9433]={id=9433,zoneId=400,name="A Dip in the Moonwell",level=28,minLevel=24,giver="Wizlo Bearingshiner",giverType="NPC",giverId=10941,ender="Wizlo Bearingshiner",enderType="NPC",enderId=10941,rewardNextId=9434,poiX=-4922,poiY=-1376,wowhead="https://www.wowhead.com/wotlk/quest=9433",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Stop looking at me like that! I didn't say I was going to send you to Thalanaar's moonwell out in the open with dipper and a flask!$B$BI've been, err... tinkering with a product I was transporting for a client. In fact, I've already set up a portable control console for the Robotron out near Thalanaar. You'll need to bring this control unit with you and use it in the vicinity of my concealed console.$B$BIf my client ever heard that I so much as removed Robotron from its packaging, he'd hang me by my ears!",logDesc="Use the Robotron Control while standing near the Concealed Command Console hidden in a small cluster of bushes on the rim of the needle closest to Thalanaar to take command of a Robotron 3000. Pilot the robot to the western edge of Thousand Needles where the Alliance outpost of Thalanaar is located. Use the robot to collect a sample of the moonwell's water and return it to Wizlo Bearingshiner at Whitereach Post."} end
if not DB[9434] then DB[9434]={id=9434,zoneId=400,name="Testing the Tonic",level=28,minLevel=24,giver="Wizlo Bearingshiner",giverType="NPC",giverId=10941,ender="Magistrix Elosai",enderType="NPC",enderId=17093,poiX=-4922,poiY=-1376,wowhead="https://www.wowhead.com/wotlk/quest=9434",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="<Wizlo retrieves the water sample from the robot and places it in a crate with the boulderkin earth and several other items.>$B$BThere you go, that's everything on Magistrix Elosai's list. Tell her that it's been a pleasure working with her and that I wish her luck in her research.",logDesc="Deliver the Crate of Reagents to Magistrix Elosai at Freewind Post."} end
if not DB[9435] then DB[9435]={id=9435,zoneId=267,name="Missing Crystals",level=29,minLevel=25,giver="Huraan",giverType="NPC",giverId=17218,ender="Huraan",enderType="NPC",enderId=17218,poiX=-852,poiY=-565,wowhead="https://www.wowhead.com/wotlk/quest=9435",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="If there's one great truth about Hillsbrad, it's that this region is destined to live under the shadow of war. Even something as innocuous as a cartload of stone is a target.$B$BNormally the loss of building materials is no great setback, but the most recent shipment from the Azurelode mine contained a crate of rare crystals I was eager to study. Forsaken raiders intercepted the cart and drove it northeast to a tower they're attempting to rebuild. It's imperative that we retrieve those crystals, $c!",logDesc="Retrieve the Shipment of Rare Crystals from the Forsaken and return it to Huraan in Southshore."} end
if not DB[9436] then DB[9436]={id=9436,zoneId=33,name="Bloodscalp Insight",level=34,minLevel=30,giver="Nemeth Hawkeye",giverType="NPC",giverId=17094,ender="Nemeth Hawkeye",enderType="NPC",enderId=17094,rewardNextId=9457,poiX=-12386,poiY=181,wowhead="https://www.wowhead.com/wotlk/quest=9436",image="assets/images/quests/placeholder.png",xpDiff=5,money=3500,desc="Well met, $c. I've made a habit of studying the fighting techniques of the various troll tribes in my travels, and I've noticed a trend. The Bloodscalp trolls at the Tkashi Ruins and Bal'lal Ruins to the north use some of the same tactics as the Amani of the northern forests.$B$BTheir magic seems to have diverged in an interesting direction and they've used it to become the strongest tribe in the area. It could form the core of a powerful weapon against the Amani, but first I must find out more about it.",logDesc="Nemeth Hawkeye at Grom'gol Base Camp wants you to bring him a Bloodscalp Totem from a Bloodscalp Shaman."} end
if not DB[9437] then DB[9437]={id=9437,zoneId=15,name="Twilight of the Dawn Runner",level=37,minLevel=33,giver="Balandar Brightstar",giverType="NPC",giverId=17095,ender="Balandar Brightstar",enderType="NPC",enderId=17095,poiX=-3144,poiY=-2858,wowhead="https://www.wowhead.com/wotlk/quest=9437",image="assets/images/quests/placeholder.png",xpDiff=5,money=4000,desc="The ogres here are useful for little more than crude jokes, sour ale, and bouts of headbutting. When my ship, the Dawn Runner, ran aground, those curs from Theramore made off with my cargo and last surviving crewman. I made my way here searching for help, but those good-for-nothing ogres stared blankly at me when I told them my story.$B$BI could use the help of a reliable $r in recovering what remains of my cargo and freeing Ithania from North Point Tower, to the northeast, where they're being held.",logDesc="Balandar Brightstar in Brackenwall Village wants you to reclaim the Dawn Runner Cargo and rescue his first mate Ithania from forces of Theramore at North Point Tower.",choiceRewards={{id=33250,qty=1},{id=33269,qty=1},{id=33252,qty=1}}} end
if not DB[9438] then DB[9438]={id=9438,zoneId=3483,name="Messenger to Thrall",level=62,minLevel=60,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Thrall",enderType="NPC",enderId=4949,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=9438",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The warchief has been waiting for word of this ever since we set foot on Outland.  Now you get the honor of giving him the news of the Mag'har yourself.$B$BGo quickly, $N.  Take this letter with you; it bears my personal seal.  There is nothing that Thrall wants to hear more than the message you bear.",logDesc="Travel to Orgrimmar and give Thrall the Letter from Nazgrel."} end
if not DB[9439] then DB[9439]={id=9439,zoneId=3,name="Unclaimed Baggage",level=40,minLevel=36,giver="Advisor Sarophas",giverType="NPC",giverId=17097,ender="Advisor Sarophas",enderType="NPC",enderId=17097,poiX=-6687,poiY=-2228,wowhead="https://www.wowhead.com/wotlk/quest=9439",image="assets/images/quests/placeholder.png",xpDiff=5,money=5000,desc="This is Kargath? Oh, dear. I expected a, a... well, some kind of settlement, some sign of civilization here in the wilderness.$B$BThere must be a mistake; surely this hovel full of uncouth, unwashed, sniggering savages can't be the headquarters of the Expeditionary Force. The loutish barbarians had the gall to laugh at me when I told them about how the Dark Iron dwarves robbed me and then disappeared into the Angor Fortress. I can count on you to help me recover my possessions and my dignity, can't I?",logDesc="Retrieve the Advisor's Pack and Advisor's Rapier from their holding places in the Angor Fortress and return them to Advisor Sarophas at Kargath."} end
if not DB[9440] then DB[9440]={id=9440,zoneId=8,name="Little Morsels",level=38,minLevel=35,giver="Cersei Dusksinger",giverType="NPC",giverId=17109,ender="Cersei Dusksinger",enderType="NPC",enderId=17109,poiX=-10461,poiY=-3320,wowhead="https://www.wowhead.com/wotlk/quest=9440",image="assets/images/quests/placeholder.png",xpDiff=5,money=4500,desc="I'm perfecting a weapon to use against the draenei and you're going to help me!$B$BThe Lost Ones are the backward cousins of the draenei, and I've been experimenting on them.  I just need you to feed some fel-tainted morsels to their captured livestock.  In turn, when they slaughter and eat the animals, they'll be cursed!  That'll show that stuffy Anchorite Avuun at the Harborage!$B$BGo now, hurry!  You'll find the Lost Ones and their caged animals to the northeast at the Fallow Sanctuary.",logDesc="Feed the Fel-Tainted Morsels to the Lost Ones' captured animals.  Then return the leftovers to Cersei Dusksinger at Stonard in the Swamp of Sorrows."} end
if not DB[9441] then DB[9441]={id=9441,zoneId=3483,name="Envoy to the Mag'har",level=63,minLevel=60,giver="Thrall",giverType="NPC",giverId=4949,ender="Gorkan Bloodfist",enderType="NPC",enderId=16845,poiX=1920,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=9441",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'd leave for Outland this very minute after hearing the news you brought.  Important matters require my attention in Durotar, however.$B$BI will arrange for a fitting tribute to be sent to the Mag'har immediately.  I will send my most trusted diplomats as well.  This will all take time... I need someone to represent us there right now.$B$BI must place my trust on you, $N.  Go to the Mag'har Post in Hellfire and render whatever services you can to my kin.  Do not fail me, $N.  Too much depends on this.",logDesc="Thrall wants you to return to Gorkan Bloodfist at Mag'har Post in Hellfire Peninsula and offer him your services.",choiceRewards={{id=25510,qty=1},{id=25512,qty=1},{id=25511,qty=1},{id=25513,qty=1}}} end
if not DB[9442] then DB[9442]={id=9442,zoneId=3483,name="A Debilitating Sickness",level=63,minLevel=60,giver="Earthcaller Ryga",giverType="NPC",giverId=17123,ender="Earthcaller Ryga",enderType="NPC",enderId=17123,rewardNextId=9447,poiX=505,poiY=3882,wowhead="https://www.wowhead.com/wotlk/quest=9442",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is good that you've offered to aid us, $N.  Our grunts have fallen sick from drinking contaminated water and I'm missing an ingredient to produce a healing salve.  I'm in need of a rare mushroom called drycap.$B$BOur foremost orders are to keep our location secret and not risk being spotted while looking for it, or I would go myself.  The only place in Hellfire Peninsula where drycap grows is a cave at the Great Fissure, south of here.$B$BBe extremely careful if you choose to seek it.",logDesc="Earthcaller Ryga at Mag'har Post in Hellfire Peninsula wants you to bring her 1 Drycap Mushroom from a cave inside the Great Fissure."} end
if not DB[9443] then DB[9443]={id=9443,zoneId=28,name="The So-Called Mark of the Lightbringer",level=58,minLevel=55,giver="Mehlar Dawnblade",giverType="NPC",giverId=17099,ender="Mehlar Dawnblade",enderType="NPC",enderId=17099,poiX=1689,poiY=-727,wowhead="https://www.wowhead.com/wotlk/quest=9443",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="I was once a pupil of Uther Lightbringer, founder of the Knights of the Silver Hand. I saw how he mishandled Prince Arthas's training. It led to the destruction of my homeland, Quel'Thalas, and I blame Uther and his incompetence for all of it! And now he has a tomb in his honor - how lovely.$B$BMy sources tell me that the scarlet fools are keeping one of his 'holy' relics atop their guard tower near the gates of Hearthglen.$B$BGo to the Western Plaguelands and retrieve it for me.",logDesc="Obtain the Mark of the Lightbringer and return it to Mehlar Dawnblade at the Bulwark in the Western Plaguelands."} end
if not DB[9444] then DB[9444]={id=9444,zoneId=28,name="Defiling Uther's Tomb",level=58,minLevel=55,giver="Mehlar Dawnblade",giverType="NPC",giverId=17099,ender="Mehlar Dawnblade",enderType="NPC",enderId=17099,poiX=1689,poiY=-727,wowhead="https://www.wowhead.com/wotlk/quest=9444",image="assets/images/quests/placeholder.png",xpDiff=6,money=17500,desc="There, that's better.  I've added a little fel magic to it.$B$BNow, you must take it to his resting place in the Western Plaguelands.  Use the corrupted holy symbol in the presence of Uther's statue to defile his tomb!  You'll have to get close for it to work.$B$BTo find the tomb go southeast of the Ruins of Andorhal.  Return to me when the deed is done.$B$BBe quick about it, $c!",logDesc="Defile Uther's Tomb and return to Mehlar Dawnblade at the Bulwark in the Western Plaguelands."} end
if not DB[9445] then DB[9445]={id=9445,zoneId=28,name="<NYI><TXT>Placeholder: A Worthy Offering",level=58,minLevel=55,rewardNextId=9446,wowhead="https://www.wowhead.com/wotlk/quest=9445",image="assets/images/quests/placeholder.png",logDesc="Obtain Uther's Blessing from the top of the guard tower near the entrance to Hearthglen and return it to <NPC> at Chillwind Point."} end
if not DB[9446] then DB[9446]={id=9446,zoneId=28,name="Tomb of the Lightbringer",level=58,minLevel=55,giver="Anchorite Truuen",giverType="NPC",giverId=17238,ender="High Priestess MacDonnell",enderType="NPC",enderId=11053,poiX=944,poiY=-1428,wowhead="https://www.wowhead.com/wotlk/quest=9446",image="assets/images/quests/placeholder.png",xpDiff=6,money=17500,desc="Now that you've recovered the Mark of the Lightbringer, all that is left is to return it to Uther's Tomb.$B$BWould you be willing to accompany me there to do this?  It's not far and I would enjoy your company.  Afterward you can come back here and relate the experience to High Priestess MacDonnell.$B$BWhat say you, $N?",logDesc="Escort Anchorite Truuen to Uther's Tomb in the Western Plaguelands.  Afterward, speak with High Priestess MacDonnell at Chillwind Camp in the Western Plaguelands."} end
if not DB[9447] then DB[9447]={id=9447,zoneId=3483,name="Administering the Salve",level=63,minLevel=60,giver="Earthcaller Ryga",giverType="NPC",giverId=17123,ender="Earthcaller Ryga",enderType="NPC",enderId=17123,poiX=505,poiY=3882,wowhead="https://www.wowhead.com/wotlk/quest=9447",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="I've prepared a simple salve that should restore our grunts' strength with the herbs you brought me.  Take it and administer it to any debilitated grunts you see in the vicinity.  Return to me when you're done.",logDesc="Earthcaller Ryga wants you to administer the Healing Salve to 10 Debilitated Mag'har Grunts nearby Mag'har Post in Hellfire Peninsula.",choiceRewards={{id=25496,qty=1},{id=25492,qty=1},{id=25495,qty=1},{id=25494,qty=1},{id=29212,qty=1}}} end
if not DB[9448] then DB[9448]={id=9448,zoneId=8,name="Mercy for the Cursed",level=38,minLevel=35,giver="Anchorite Avuun",giverType="NPC",giverId=17127,ender="Anchorite Avuun",enderType="NPC",enderId=17127,poiX=-10107,poiY=-2814,wowhead="https://www.wowhead.com/wotlk/quest=9448",image="assets/images/quests/placeholder.png",xpDiff=5,money=4500,desc="That blood elf witch, Cersei Dusksinger, has been cursing the Lost Ones, I just know it!  I don't know why or how, but the results are tragic.  Several of the Lost Ones have now been further corrupted - cursed with even more fel energies!$B$B$C, can you find it in you to take pity on these poor creatures?  They should not have to live out the rest of their lives in such a horrible condition.$B$BYou'll find these cursed Lost Ones at the Fallow Sanctuary, east down the path.",logDesc="Slay 3 Cursed Lost Ones and then return to Anchorite Avuun at the Harborage in the Swamp of Sorrows."} end
if not DB[9449] then DB[9449]={id=9449,zoneId=-82,name="Call of Earth",level=-1,minLevel=4,giver="Firmanvaar",giverType="NPC",giverId=17089,ender="Spirit of the Vale",enderType="NPC",enderId=17087,rewardNextId=9450,poiX=-4127,poiY=-13727,wowhead="https://www.wowhead.com/wotlk/quest=9449",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The time has come, $N.  You have grown to the point where you are ready to commune directly with the elemental spirits of this world.$B$BBut be warned.  I can sense that the manner of our entry into this world, and its unfortunate side effects, have angered the earth spirits and caused an imbalance of the elements.$B$BIf you are to create your earth totem, you must first speak with the Spirit of the Vale.  You will find it in the Sacred Grove, nestled in the hills to the northwest.",logDesc="Speak with the Spirit of the Vale at the Sacred Grove in Ammen Vale."} end
if not DB[9450] then DB[9450]={id=9450,zoneId=-82,name="Call of Earth",level=-1,minLevel=4,giver="Spirit of the Vale",giverType="NPC",giverId=17087,ender="Spirit of the Vale",enderType="NPC",enderId=17087,rewardNextId=9451,poiX=-3855,poiY=-13403,wowhead="https://www.wowhead.com/wotlk/quest=9450",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The balance of the elements has been disrupted by the violent intrusion of the draenei to the Vale.  Your crash has caused the spirits of earth to be enraged and turn upon the other elements who have come to quell them.  You will learn that an understanding of the elements can only come when all are in harmony.$B$BThus, it falls to you to seek a balance.  Behind me in the grove you will find the restless spirits of earth warring upon the other three elements.  Help restore the balance.",logDesc="Slay 4 Restless Elements of Earth and then return to the Spirit of the Vale at the Sacred Grove in Ammen Vale."} end
if not DB[9451] then DB[9451]={id=9451,zoneId=-82,name="Call of Earth",level=-1,minLevel=4,giver="Spirit of the Vale",giverType="NPC",giverId=17087,ender="Firmanvaar",enderType="NPC",enderId=17089,poiX=-3855,poiY=-13403,wowhead="https://www.wowhead.com/wotlk/quest=9451",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I will now give you a piece of my physical being that you may create your earth totem.  Return it to he who sent you here.$B$BYou and I will be bound together for all time.  Throughout your life the forces of earth will be at your disposal.  The balance will come when your bones return to us at the end of your days.$B$BUse our power wisely.",logDesc="Deliver the Earth Crystal to Firmanvaar at the Crash Site in Ammen Vale.",rewards={{id=5175,qty=1}}} end
if not DB[9452] then DB[9452]={id=9452,zoneId=3524,name="Red Snapper - Very Tasty!",level=6,minLevel=4,giver="Diktynna",giverType="NPC",giverId=17101,ender="Diktynna",enderType="NPC",enderId=17101,rewardNextId=9453,poiX=-4266,poiY=-12985,wowhead="https://www.wowhead.com/wotlk/quest=9452",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've found that these waters are bustling with red snapper, a very tasty fish. With a fishing net, I can catch enough to feed dozens of draenei! Unfortunately, I was recently attacked by a creature known as a murloc while netting in the river and have suffered some injuries that prevent me from doing my job. I need help!$B$BUse this fishing net near schools of red snapper, found in the Crystalbrook river to the east to catch the fish.$B$BWhat do you say? Remember to return the net when you are finished.",logDesc="Use the Draenei Fishing Net to catch 10 Red Snappers. Return both the fish and the net to Diktynna on Azuremyst Isle when the task is complete.",rewards={{id=6256,qty=1},{id=6529,qty=1}}} end
if not DB[9453] then DB[9453]={id=9453,zoneId=3524,name="Find Acteon!",level=6,minLevel=4,giver="Diktynna",giverType="NPC",giverId=17101,ender="Acteon",enderType="NPC",enderId=17110,poiX=-4266,poiY=-12985,wowhead="https://www.wowhead.com/wotlk/quest=9453",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You did a wonderful job, $N. Our people will be thankful for this bounty. With that said, would you mind taking this haul of red snapper to Acteon at Azure Watch?$B$BHe shouldn't be hard to find as he is awaiting this catch.",logDesc="Deliver the Crate of Red Snapper to Acteon at Azure Watch."} end
if not DB[9454] then DB[9454]={id=9454,zoneId=3524,name="The Great Moongraze Hunt",level=6,minLevel=4,giver="Acteon",giverType="NPC",giverId=17110,ender="Acteon",enderType="NPC",enderId=17110,rewardNextId=10324,poiX=-4204,poiY=-12526,wowhead="https://www.wowhead.com/wotlk/quest=9454",image="assets/images/quests/placeholder.png",xpDiff=4,money=100,desc="You're starting to make a name for yourself, $N. How about trying your hand at hunting?$B$BBack on Draenor, our greatest hunters would hunt a beast that resembled the moongraze stag of this region known as a talbuk.$B$BIf you think yourself draenei enough, go out into the wilds and kill enough stags to fill your pack with meat.$B$BYou will find them grazing south of Azure Watch. Watch out for their horns!",logDesc="Bring 6 Moongraze Stag Tenderloins to Acteon at Azure Watch.",rewards={{id=24105,qty=5},{id=27686,qty=1}}} end
if not DB[9455] then DB[9455]={id=9455,zoneId=3524,name="Strange Findings",level=7,minLevel=5,ender="Exarch Menelaous",enderType="NPC",enderId=17116,rewardNextId=9456,wowhead="https://www.wowhead.com/wotlk/quest=9455",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The crystal you found on the nightstalker runt's body appears to be a piece of the Exodar. This may help explain the unusual appearance and demeanor of some of the animals in this region.$B$BTake the crystal back to Azure Watch. The exarch will surely want to know about this discovery.",logDesc="Deliver the Faintly Glowing Crystal to Exarch Menelaous at Azure Watch."} end
if not DB[9456] then DB[9456]={id=9456,zoneId=3524,name="Nightstalker Clean Up, Isle 2...",level=8,minLevel=5,giver="Exarch Menelaous",giverType="NPC",giverId=17116,ender="Exarch Menelaous",enderType="NPC",enderId=17116,poiX=-4167,poiY=-12418,wowhead="https://www.wowhead.com/wotlk/quest=9456",image="assets/images/quests/placeholder.png",xpDiff=5,money=225,desc="I'm not going to make any excuses for what you've found. This is clearly our fault. We had gotten reports of crushed crystal fragments showing up in the river to the east but chose to ignore the implications. Now we can either sit around on this island and cry about the tragedy that has befallen this land or we can do something about it and prevent it from spreading.$B$BIf you've got the stomach for it, I want you to go back into the wilds and kill as many of the infected nightstalkers as you can find.",logDesc="Exarch Menelaous at Azure Watch has asked that you slay 8 Infected Nightstalker Runts.",choiceRewards={{id=24436,qty=1},{id=24435,qty=1},{id=24437,qty=1}}} end
if not DB[9457] then DB[9457]={id=9457,zoneId=33,name="An Unusual Patron",level=36,minLevel=30,giver="Nemeth Hawkeye",giverType="NPC",giverId=17094,ender="Nemeth Hawkeye",enderType="NPC",enderId=17094,poiX=-12386,poiY=181,wowhead="https://www.wowhead.com/wotlk/quest=9457",image="assets/images/quests/placeholder.png",xpDiff=6,money=7500,desc="So this Naias is the mastermind behind the Bloodscalp and their exotic magic? I'll admit, this is the last place I expected my inquiry to lead, but no matter, our findings may still prove useful.$B$BOff the coast to the northwest is an island inhabited by lesser water elementals. There's a crude stone slab there that might serve as an altar for the likes of the trolls. Take the totem you found to that altar. Let's see if we can draw this Naias out and distill his power into a more agreeable form.",logDesc="Use the Gift of Naias near the Altar of Naias to summon the water elemental Naias. Defeat him and return to Nemeth Hawkeye at Grom'gol Base Camp with the Heart of Naias."} end
if not DB[9458] then DB[9458]={id=9458,zoneId=0,name="<UNUSED>Potion of Heightened Senses",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9458",image="assets/images/quests/placeholder.png",rewards={{id=23696,qty=1}}} end
if not DB[9459] then DB[9459]={id=9459,zoneId=0,name="<UNUSED>Anti-crit Potion",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9459",image="assets/images/quests/placeholder.png",rewards={{id=23696,qty=1}}} end
if not DB[9460] then DB[9460]={id=9460,zoneId=-162,name="Combining Forces",level=12,minLevel=10,giver="Keltus Darkleaf",giverType="NPC",giverId=17224,ender="Keltus Darkleaf",enderType="NPC",enderId=17224,rewardNextId=9618,poiX=8021,poiY=-6372,wowhead="https://www.wowhead.com/wotlk/quest=9460",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Keltus Darkleaf reporting for duty!$b$bOh... who are you, anyhow?  If you are here for my report, I insist you help me first.$b$bI am planning to attack the sentinel spies, but I intend to send in my faithful Whisper as a first strike.  She just needs a scent to hone in on them.$b$bSurely someone of your skill could sneak in and steal something from the sentinel leader?",logDesc="Keltus Darkleaf wants you to pickpocket the Lacy Handkerchief from the Sentinel Leader and bring it to him.",rewards={{id=23919,qty=1}}} end
if not DB[9461] then DB[9461]={id=9461,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Tuluun",giverType="NPC",giverId=17212,ender="3",enderType="NPC",enderId=17468,rewardNextId=9555,poiX=-4162,poiY=-12456,wowhead="https://www.wowhead.com/wotlk/quest=9461",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You should know that The Prophet has been asking for you, having heard of your success in your trial. The creation of your fire totem will have to wait until you have spoken with him.$b$bThis is a rare honor; you must hurry to the Exodar to see him at once!",logDesc="Seek out Prophet Velen at the Vault of Lights in the Exodar."} end
if not DB[9462] then DB[9462]={id=9462,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Sulaa",giverType="NPC",giverId=17219,ender="Tuluun",enderType="NPC",enderId=17212,rewardNextId=9464,poiX=-3778,poiY=-11407,wowhead="https://www.wowhead.com/wotlk/quest=9462",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N! It is time for you to receive further training in the ways of the spirits. You should seek out Tuluun, the shaman at Azure Watch. He can begin your introduction to understanding and harnessing the power of flame.",logDesc="Speak with Tuluun at Azure Watch on Azuremyst Isle."} end
if not DB[9463] then DB[9463]={id=9463,zoneId=3524,name="Medicinal Purpose",level=6,minLevel=4,giver="Anchorite Fateema",giverType="NPC",giverId=17214,ender="Anchorite Fateema",enderType="NPC",enderId=17214,poiX=-4199,poiY=-12470,wowhead="https://www.wowhead.com/wotlk/quest=9463",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I have found that lashers milling about on the island hold restorative medicinal properties in their vines. Through proper treatment, the vines can be broken down into a powerful healing ointment. Unfortunately, with so many injured draenei passing through Azure Watch, we are always in short supply.$B$BOur delicate guest was found injured and unconscious by the Crystalbrook only yesterday. If you bring me vines, we may be able to save her.$B$BYou will find root trappers both south and east of Azure Watch.",logDesc="Anchorite Fateema at Azure Watch wants you to bring her 8 Root Trapper Vines."} end
if not DB[9464] then DB[9464]={id=9464,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Tuluun",giverType="NPC",giverId=17212,ender="Temper",enderType="NPC",enderId=17205,rewardNextId=9465,poiX=-4162,poiY=-12456,wowhead="https://www.wowhead.com/wotlk/quest=9464",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Once again you are to be tested, and this time the chaotic element of fire must be understood if you're to create a totem to harness its energies.$B$BTo the northeast on the coast is a sacred place of fire known as Emberglade. Amidst its burned trees stands Temper, a fire elemental of great power, and the one that you must speak with.$B$BGo to him now and may the elemental spirits of Azeroth go with you.",logDesc="Speak with Temper at Emberglade on Azuremyst Isle."} end
if not DB[9465] then DB[9465]={id=9465,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Temper",giverType="NPC",giverId=17205,ender="Temper",enderType="NPC",enderId=17205,rewardNextId=9467,poiX=-3286,poiY=-12924,wowhead="https://www.wowhead.com/wotlk/quest=9465",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One of my brethren, Hauteur, has gone insane, no doubt because of the crash of your ship.  He's begun demanding that the local owlbeasts worship him.$B$BThis will not continue!  None of us would ever impersonate a god!  It falls to you to restore the balance.$B$BFirst, you must retrieve their ritual torch, which has been taken by the crazed wildkin inside Stillpine Hold to the west.$B$BReturn the torch to me.",logDesc="Retrieve the Ritual Torch and return it to Temper at Emberglade on Azuremyst Isle."} end
if not DB[9466] then DB[9466]={id=9466,zoneId=3483,name="Wanted: Blacktalon the Savage",level=63,minLevel=58,ender="Ranger Captain Venn'ren",enderType="NPC",enderId=16789,wowhead="https://www.wowhead.com/wotlk/quest=9466",image="assets/images/quests/placeholder.png",xpDiff=6,money=58000,desc="By order of the Ranger Captain, a reward is hereby offered for the slaying of the vicious rockflayer matriarch known as Blacktalon the Savage.$B$BBlacktalon was last sighted inside a cave in the Great Fissure.  Individuals seeking the reward are to present the creature's claws as proof of the deed.",logDesc="Bring Blacktalon's Claws to Ranger Captain Venn'ren at Falcon Watch in Hellfire Peninsula.",choiceRewards={{id=25483,qty=1},{id=25482,qty=1},{id=25481,qty=1}}} end
if not DB[9467] then DB[9467]={id=9467,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Temper",giverType="NPC",giverId=17205,ender="Temper",enderType="NPC",enderId=17205,poiX=-3286,poiY=-12924,wowhead="https://www.wowhead.com/wotlk/quest=9467",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The owlbeasts of Moonwing Den on Silvermyst Isle, far to the southwest, have been deluded into thinking that Hauteur is a god to be worshipped.  What he truly is, is a fallen elemental who needs to be put out of his misery.  That torch is the key to his downfall.$B$BHauteur regularly demands that these owlbeasts burn an effigy in his honor.  So, when you light it, he will come.  Slay him and bring me the ashes.  Then use the orb in the satchel that I will give you to return to me here.",logDesc="Retrieve Hauteur's Ashes and then return them and the Ritual Torch to Temper at Emberglade on Azuremyst Isle.  Remember that you can use the Orb of Returning to teleport back to Temper once you have the ashes."} end
if not DB[9468] then DB[9468]={id=9468,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="Temper",giverType="NPC",giverId=17205,ender="Tuluun",enderType="NPC",enderId=17212,rewardNextId=9461,poiX=-3286,poiY=-12924,wowhead="https://www.wowhead.com/wotlk/quest=9468",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You have done a great thing here today in your pursuit of understanding your relationship to the flame.  Remember to always treat it with the utmost respect lest you get burned.$B$BI saved a portion of Hauteur's ashes for you.  Use them in the creation of your fire totem and remember all that you have learned in their attainment.$B$BNow, return to Tuluun.",logDesc="Deliver Hauteur's Ashes to Tuluun at Azure Watch on Azuremyst Isle."} end
if not DB[9469] then DB[9469]={id=9469,zoneId=47,name="Featherbeard's Endorsement",level=46,minLevel=42,giver="Ambassador Rualeth",giverType="NPC",giverId=17223,rewardNextId=9476,poiX=255,poiY=-2157,wowhead="https://www.wowhead.com/wotlk/quest=9469",image="assets/images/quests/placeholder.png",xpDiff=4,desc="When I am finally granted an audience with Falstad Wildhammer, I hope to have our strongest advocate among the Wildhammer dwarves at my side, $N.$B$BFeatherbeard is revered among his people, both for his legendary gryphon training skills and for his wisdom. If anyone can sway Falstad Wildhammer, it is he.$B$BI would go to see him myself, except that I cannot leave the confines of Aerie Peak while awaiting my audience. Visit Featherbeard at his residence to the south and ask if he will speak with me.",logDesc="Go to Featherbeard's Hovel and visit the dwarf if he is at home. If he is not at home, search for evidence of where he can be found."} end
if not DB[9470] then DB[9470]={id=9470,zoneId=47,name="A Gesture of Goodwill",level=46,minLevel=42,giver="Ambassador Rualeth",giverType="NPC",giverId=17223,ender="Ambassador Rualeth",enderType="NPC",enderId=17223,poiX=255,poiY=-2157,wowhead="https://www.wowhead.com/wotlk/quest=9470",image="assets/images/quests/placeholder.png",xpDiff=5,money=6500,desc="The rugged terrain of the Hinterlands is not only home to the Wildhammer dwarves and their gryphons, but also to a number of forest troll tribes.$B$BThe trolls view the Wildhammers as squatters on their ancestral lands and spare no opportunity to accost the dwarves by attacking the gryphon aeries. One way to prove ourselves in the eyes of the Wildhammer is to help staunch these attacks by killing a Witherbark leader, Witch Doctor Mai'jin, who shelters in a cave at Bogen's Ledge, to the west of Shadra'Alor.",logDesc="Ambassador Rualeth at Aerie Peak wants you to slay Witch Doctor Mai'jin and his pet spider Tcha'kaz."} end
if not DB[9471] then DB[9471]={id=9471,zoneId=47,name="Preying on the Predators",level=44,minLevel=40,giver="Ambassador Rualeth",giverType="NPC",giverId=17223,ender="Ambassador Rualeth",enderType="NPC",enderId=17223,poiX=255,poiY=-2157,wowhead="https://www.wowhead.com/wotlk/quest=9471",image="assets/images/quests/placeholder.png",xpDiff=5,money=6500,desc="The Wildhammer dwarves act as companions, caretakers, and trainers to the gryphons. The gryphons have no shortage of enemies, especially among the forest troll tribes.$B$BSometimes, though, the threat comes from natural predators, such as wolves. A single animal is no match for a gryphon, but packs have taken to targeting gryphons more often because normal prey is scarce. Culling the wolves can help to reduce their impact on the gryphons and ingratiate us to the Wildhammer.",logDesc="Ambassador Rualeth at Aerie Peak wants you to kill 10 Mangy Silvermane and 5 Silvermane Wolves."} end
if not DB[9472] then DB[9472]={id=9472,zoneId=3483,name="Arelion's Mistress",level=62,minLevel=60,giver="Magistrix Carinda",giverType="NPC",giverId=16793,ender="Magistrix Carinda",enderType="NPC",enderId=16793,poiX=-596,poiY=4177,wowhead="https://www.wowhead.com/wotlk/quest=9472",image="assets/images/quests/placeholder.png",xpDiff=6,money=54000,desc="With all the important matters at hand Arelion still found time in his schedule to see a mistress!$B$BIt's all becoming perfectly clear.  Viera Sunwhisper, that filthy wench... we'll show her to never cross a magistrix again.$B$BTake this scroll and find Viera.  Find a way to lure her away from town and use the scroll on her.$B$BArelion mentioned she couldn't resist a particular wine harvested by the cenarion druids.  You might find some at Cenarion Refuge, just inside Zangarmarsh, west of here.",logDesc="Magistrix Carinda at Falcon Watch wants you to lure Viera Sunwhisper away from the settlement and then use Carinda's Scroll of Retribution on her.",rewards={{id=25505,qty=1}}} end
if not DB[9473] then DB[9473]={id=9473,zoneId=3524,name="An Alternative Alternative",level=8,minLevel=5,giver="Daedal",giverType="NPC",giverId=17215,ender="Daedal",enderType="NPC",enderId=17215,poiX=-4191,poiY=-12470,wowhead="https://www.wowhead.com/wotlk/quest=9473",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The girl is too far gone for mere ointments to be effective. There may be another way...$B$BThe forest of Azuremyst holds many secrets, one of those being a rare plant known as the azure snapdragon that some claim to be a panacea - a cure all.$B$BYou can identify the plant by its stark contrast to the other plants of Azuremyst and its need to grow at the base of the azure pine trees. Make haste!$B$BAnd $N, be wary of the root threshers of the region as they consume snapdragon for sustenance.",logDesc="Daedal at Azure Watch wants you to bring him 5 Azure Snapdragon Bulbs."} end
if not DB[9474] then DB[9474]={id=9474,zoneId=28,name="The Mark of the Lightbringer",level=58,minLevel=55,giver="Anchorite Truuen",giverType="NPC",giverId=17238,ender="Anchorite Truuen",enderType="NPC",enderId=17238,rewardNextId=9446,poiX=944,poiY=-1428,wowhead="https://www.wowhead.com/wotlk/quest=9474",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="In the short time that I have been on Azeroth I have studied many of its heroes.  Of them all, Uther Lightbringer stands above the rest.  A hero for the ages, in the end Uther was betrayed by his most promising pupil, Arthas.$B$BIn his honor, I would like to return something he lost to his nearby tomb.  It is rumored that the Scarlet Crusade is keeping one of his holy relics atop their guard tower near the gates of Hearthglen.$B$BPlease, $c, go and retrieve it.",logDesc="Obtain the Mark of the Lightbringer and return it to Anchorite Truuen at Chillwind Camp in the Western Plaguelands."} end
if not DB[9475] then DB[9475]={id=9475,zoneId=47,name="Reclaiming the Eggs",level=46,minLevel=42,ender="Ambassador Rualeth",enderType="NPC",enderId=17223,wowhead="https://www.wowhead.com/wotlk/quest=9475",image="assets/images/quests/placeholder.png",xpDiff=6,money=13000,desc="Looking over the remains, you surmise that this broken and battered skeleton must be all that is left of Featherbeard. Clutched in one skeletal hand is a torn and stained sheaf of paper. You gently remove and unroll it, revealing a hand-drawn map and a few hastily scrawled notes.$B$BThe map appears to be a rendering of Shadra'Alor and its three temples with 'x' marks in several places, presumably the locations of the stolen eggs. You place the map in your pack for inspection at a safer location.",logDesc="Gather 5 Gryphon Eggs and return them to Ambassador Rualeth at Aerie Peak."} end
if not DB[9476] then DB[9476]={id=9476,zoneId=47,name="In Pursuit of Featherbeard",level=46,minLevel=42,rewardNextId=9475,wowhead="https://www.wowhead.com/wotlk/quest=9476",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The journal's most recent entries detail Featherbeard's concern about a growing number of Witherbark troll raids on the Wildhammer gryphon aeries and a rash of egg thefts. A search of the smaller Witherbark settlements in the area appears to have yielded no information.$B$BThe last entry describes Featherbeard's suspicion that a Witherbark witch doctor named Mai'jin is behind the raids. The last, hastily written sentence states the dwarf's intention to travel to Shadra'Alor in search of the eggs.",logDesc="Travel to Shadra'Alor and search for traces of Featherbeard."} end
if not DB[9477] then DB[9477]={id=9477,zoneId=0,name="<UNUSED>Potion of Nature's Armor",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9477",image="assets/images/quests/placeholder.png",rewards={{id=23698,qty=1}}} end
