if not DB[9483] then DB[9483]={id=9483,zoneId=3483,name="Life's Finer Pleasures",level=62,minLevel=60,giver="Viera Sunwhisper",giverType="NPC",giverId=17226,ender="Viera Sunwhisper",enderType="NPC",enderId=17226,poiX=-658,poiY=4137,wowhead="https://www.wowhead.com/wotlk/quest=9483",image="assets/images/quests/placeholder.png"} end
if not DB[9484] then DB[9484]={id=9484,zoneId=-261,name="Taming the Beast",level=-1,minLevel=10,giver="Lieutenant Dawnrunner",giverType="NPC",giverId=15399,ender="Lieutenant Dawnrunner",enderType="NPC",enderId=15399,rewardNextId=9486,poiX=8981,poiY=-7458,wowhead="https://www.wowhead.com/wotlk/quest=9484",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have undoubtedly hunted and slain beasts for both your defense and sustenance, yet to befriend them and harness their strengths is only now within your grasp.  This I can teach you.$b$bTake this magical taming rod that allows a wild animal to temporarily bond and fight beside you.  Begin with the crazed dragonhawk, a nearly docile bird found just outside of Farstrider Retreat.  Return to me when this is done.",logDesc="Use the Taming Rod to tame a Crazed Dragonhawk, and then return to Lieutenant Dawnrunner."} end
if not DB[9485] then DB[9485]={id=9485,zoneId=-261,name="Taming the Beast",level=-1,minLevel=10,giver="Lieutenant Dawnrunner",giverType="NPC",giverId=15399,ender="Lieutenant Dawnrunner",enderType="NPC",enderId=15399,rewardNextId=9673,poiX=8981,poiY=-7458,wowhead="https://www.wowhead.com/wotlk/quest=9485",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have done well, $n.  Your understanding of the wild grows quickly.$b$bThe mistbat is a clever hunter, combining the swiftness of the dragonhawk and the ferocity of the springpaw.  Mistbats are found just across the Elrendar River to the south, preying on hapless travelers who wander into the Ghostlands.$b$bUse this final taming rod to befriend a mistbat and return to me when you have finished.",logDesc="Use the Taming Rod to tame a Mistbat, and then return to Lieutenant Dawnrunner."} end
if not DB[9486] then DB[9486]={id=9486,zoneId=-261,name="Taming the Beast",level=-1,minLevel=10,giver="Lieutenant Dawnrunner",giverType="NPC",giverId=15399,ender="Lieutenant Dawnrunner",enderType="NPC",enderId=15399,rewardNextId=9485,poiX=8981,poiY=-7458,wowhead="https://www.wowhead.com/wotlk/quest=9486",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The elder springpaw is an efficient and swift hunter.  In attempting to befriend one, it sees you as prey.  Do not be dissuaded.$b$bUse the taming rod to bring the great cat to your side and hunt beside it.  They are found throughout Eversong Woods, some very close to the lodge.  When you have learned enough, return to me.",logDesc="Use the Taming Rod to tame an Elder Springpaw, then return to Lieutenant Dawnrunner."} end
if not DB[9487] then DB[9487]={id=9487,zoneId=-161,name="Arcane Reavers",level=16,minLevel=15,giver="Arcanist Vandril",giverType="NPC",giverId=16197,ender="Arcanist Vandril",enderType="NPC",enderId=16197,rewardNextId=9488,poiX=7642,poiY=-6819,wowhead="https://www.wowhead.com/wotlk/quest=9487",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Arcane reavers are magical creations of brute strength.  They are heavily armored and deliver stunning blows.  You, however, can bypass their defenses and avoid their attacks.  Your spellcraft is not without many advantages, $n.$b$bTravel to Dawnstar Spire and blast apart the arcane reavers.  From their remains, collect the crystallized fragments of magical energy and return to me.  Dawnstar Spire is found to the east, across the lake.",logDesc="Arcanist Vandril wants you to collect 10 Arcane Fragments for him."} end
if not DB[9488] then DB[9488]={id=9488,zoneId=-161,name="A Simple Robe",level=16,minLevel=15,giver="Arcanist Vandril",giverType="NPC",giverId=16197,ender="Arcanist Vandril",enderType="NPC",enderId=16197,poiX=7642,poiY=-6819,wowhead="https://www.wowhead.com/wotlk/quest=9488",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The arcane fragments you collected will do nicely.$b$bNicely for what, you ask?  For making a splendid robe fit for a $c like yourself!$b$bAll we need now is some linen cloth and a spindleweb silk gland.  You can find the silk gland from any spindleweb spider, preferably after killing them.",logDesc="Arcanist Vandril wants you to bring him 15 Linen Cloth and a Spindleweb Silk Gland.",rewards={{id=7509,qty=1}}} end
if not DB[9489] then DB[9489]={id=9489,zoneId=-262,name="Cleansing the Scar",level=5,minLevel=5,giver="Ponaris",giverType="NPC",giverId=16276,ender="Ponaris",enderType="NPC",enderId=16276,poiX=9467,poiY=-6844,wowhead="https://www.wowhead.com/wotlk/quest=9489",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$N, it is good you are here.  The Scourge attack our city with such endless hate that I fear the morale of our guard is breaking.$b$bHurry to the Dead Scar just south of the city where Jaela and her rangers stand ready.  Fill them with the power of the Light through your blessings.",logDesc="Cast Power Word: Fortitude on 6 Eversong Rangers in the Dead Scar.",rewards={{id=23924,qty=1}}} end
if not DB[9490] then DB[9490]={id=9490,zoneId=3483,name="The Rock Flayer Matriarch",level=63,minLevel=60,giver="Ikan",giverType="NPC",giverId=16799,ender="Ikan",enderType="NPC",enderId=16799,poiX=96,poiY=4347,wowhead="https://www.wowhead.com/wotlk/quest=9490",image="assets/images/quests/placeholder.png",xpDiff=6,money=58000,desc="Rock flayers are mean, nasty, violent creatures.  But the plain ones are like tame beasts when compared to their matriarch, Blacktalon the Savage.$B$BMy cousin got eaten by her and it wasn't pretty.  I swore that one day Blacktalon would pay for that.  You bring back proof of that monster's death and I will give you my life's savings.  Deal?$B$BYou're going to need some friends to kill Blacktalon.  Big tough friends with sharp swords.  You'll find her inside a cave in the Great Fissure.  Good luck!",logDesc="Obtain Blacktalon's Claws from Blacktalon the Savage at the Great Fissure and bring it to Ikan at the Temple of Telhamat in Hellfire Peninsula.",choiceRewards={{id=25480,qty=1},{id=25479,qty=1},{id=25478,qty=1}}} end
if not DB[9491] then DB[9491]={id=9491,zoneId=-162,name="Greed",level=18,minLevel=16,giver="Eralan",giverType="NPC",giverId=16268,ender="Eralan",enderType="NPC",enderId=16268,rewardNextId=10548,poiX=7512,poiY=-6841,wowhead="https://www.wowhead.com/wotlk/quest=9491",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A rich, and I mean filthy rich, merchant came through here yesterday talking about some ring of \"immense archeological importance\" locked in one of the countless burial chests found in the Amani Catacombs.  When he wasn't talking about the ring, he was talking about how much he'd pay for it.$b$bTell you what, I'll front the thieves' tools, and if you manage to bring the ring back, I'll pay you enough to buy ten rings of your own!",logDesc="Eralan in Tranquillien wants you to retrieve the Pitted Gold Band from the Amani Catacombs.",rewards={{id=23921,qty=1}}} end
if not DB[9492] then DB[9492]={id=9492,zoneId=3535,name="Turning the Tide",level=70,minLevel=67,giver="Force Commander Danath Trollbane",giverType="NPC",giverId=16819,ender="Force Commander Danath Trollbane",enderType="NPC",enderId=16819,poiX=-816,poiY=2614,wowhead="https://www.wowhead.com/wotlk/quest=9492",image="assets/images/quests/placeholder.png",xpDiff=8,money=44000,desc="The permanence of the orcish threat is one of the sad truths of Outland. There was a time when we Sons of Lothar believed we'd purchased Honor Hold's safety with our blood, but there was to be no peace.$B$BThe Sons will yield to no orc - green, brown, and now red - we will overcome them or die trying. If we are to have any expectation of victory, we must take the fight to them in Hellfire Citadel. Bring me the weapon of their self-styled 'Warchief' Kargath Bladefist and you will be well rewarded.",logDesc="Bring Warchief Kargath's Fist to Force Commander Danath Trollbane in Honor Hold.",choiceRewards={{id=25806,qty=1},{id=25805,qty=1},{id=25804,qty=1},{id=25803,qty=1}}} end
if not DB[9493] then DB[9493]={id=9493,zoneId=3535,name="Pride of the Fel Horde",level=70,minLevel=66,giver="Field Commander Romus",giverType="NPC",giverId=16830,ender="Field Commander Romus",enderType="NPC",enderId=16830,poiX=-679,poiY=2604,wowhead="https://www.wowhead.com/wotlk/quest=9493",image="assets/images/quests/placeholder.png",xpDiff=8,money=44000,desc="We know precious little about the Fel Horde presence in Hellfire Citadel and our information has come at the cost of many lives.$B$BFel Horde troops under the command of Kargath Bladefist are a brutal, battle-hardened lot fortified by foul magics. The elite of this force, the Shattered Hand legionnaires, champions, and centurions are feared by the regulars and serve as an officer corps.$B$BTargeting and eliminating them is a necessary first step in any successful assault on the Fel Horde's leadership.",logDesc="Field Commander Romus at Honor Hold wants you to kill 8 Shattered Hand Legionnaires, 4 Shattered Hand Centurions, and 4 Shattered Hand Champions."} end
if not DB[9494] then DB[9494]={id=9494,zoneId=3535,name="Fel Embers",level=70,minLevel=67,giver="Magus Zabraxis",giverType="NPC",giverId=16829,ender="Magus Zabraxis",enderType="NPC",enderId=16829,poiX=-783,poiY=2758,wowhead="https://www.wowhead.com/wotlk/quest=9494",image="assets/images/quests/placeholder.png",xpDiff=8,money=44000,desc="The stuffy academics of Azeroth have cowered in their towers for too long and it's fallen to me to show them what cutting edge research is! They're afraid to play with fire and that's exactly what I intend to do, once I get my hands on the fire, that is.$B$BWithin Hellfire Citadel's Shattered Halls, Grand Warlock Nethekurse performs unrivaled magical feats augmented by the powers of a pair of strange braziers. Using the vessel he uses to contain these fel embers, capture one and bring it back to me, $N.",logDesc="Magus Zabraxis at Honor Hold wants you to bring her a Fel Ember.",choiceRewards={{id=25792,qty=1},{id=25789,qty=1},{id=25791,qty=1},{id=25790,qty=1},{id=25788,qty=1}}} end
if not DB[9495] then DB[9495]={id=9495,zoneId=3535,name="The Will of the Warchief",level=70,minLevel=67,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Nazgrel",enderType="NPC",enderId=3230,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=9495",image="assets/images/quests/placeholder.png",xpDiff=8,money=44000,desc="The struggle to free the orcish people from our tainted blood has not been easy, $N. Warchief Thrall has seen too many orcish heroes laid low by fate's hand. Now, it seems Kargath Bladefist numbers among them.$B$BIn the Shattered Halls of Hellfire Citadel, Kargath has claimed the title of 'Warchief' of the Fel Horde. With an army of crazed, bloodthirsty fel orcs at his back, he won't rest until Thrallmar is destroyed. Warchief Thrall has commanded us to defeat Kargath and his forces at all costs.",logDesc="Bring Warchief Kargath's Fist to Nazgrel in Thrallmar.",choiceRewards={{id=25808,qty=1},{id=25810,qty=1},{id=25811,qty=1},{id=25809,qty=1}}} end
if not DB[9496] then DB[9496]={id=9496,zoneId=3535,name="Pride of the Fel Horde",level=70,minLevel=66,giver="Shadow Hunter Ty'jin",giverType="NPC",giverId=16575,ender="Shadow Hunter Ty'jin",enderType="NPC",enderId=16575,poiX=230,poiY=2696,wowhead="https://www.wowhead.com/wotlk/quest=9496",image="assets/images/quests/placeholder.png",xpDiff=8,money=44000,desc="Overlord Maimfist's insults aside, $N, this Fel Horde is nothing to be trifled with.$B$BFrom what we know, Fel Horde troops under the command of Kargath Bladefist are a brutal, battle-hardened lot fortified by foul magics. The elite of this force, the Shattered Hand legionnaires, champions, and centurions are feared by the Fel Horde regulars and serve as an officer corps.$B$BTargeting and eliminating them is a necessary first step in any successful assault on the Fel Horde's leadership.$B",logDesc="Shadow Hunter Ty'jin at Thrallmar wants you to kill 8 Shattered Hand Legionnaires, 4 Shattered Hand Centurions, and 4 Shattered Hand Champions."} end
if not DB[9497] then DB[9497]={id=9497,zoneId=3535,name="Emblem of the Fel Horde",level=70,minLevel=67,wowhead="https://www.wowhead.com/wotlk/quest=9497",image="assets/images/quests/placeholder.png",xpDiff=8,money=44000,desc="When word of the so-called 'Fel Horde' reached the Warchief's ears,he was both furious and greatly saddened. Like Rend's pretenders before them,this false Horde too will fall,and its banner will adorn the wall of Grommash Hold as a testament to the Warchief's might.$B$BIt falls to you to carry out the Warchief's will in this matter,$N. It will not be an easy task,for the banner is guarded by a champion of this Fel Horde,known as Warbringer O'mrogg,and he will not yield his charge without a fight.",logDesc="Slay Warbringer O'mrogg and capture the Fel Horde Banner,then return it to Overlord Hun Maimfist at Thrallmar.",choiceRewards={{id=25793,qty=1},{id=25794,qty=1},{id=25795,qty=1},{id=25796,qty=1},{id=25797,qty=1}}} end
if not DB[9498] then DB[9498]={id=9498,zoneId=3483,name="Falcon Watch",level=62,minLevel=60,giver="Martik Tor'seldori",giverType="NPC",giverId=16577,ender="Ranger Captain Venn'ren",enderType="NPC",enderId=16789,rewardNextId=9340,poiX=134,poiY=2690,wowhead="https://www.wowhead.com/wotlk/quest=9498",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My people recently finished building Falcon Watch, a base of operations in the southwestern region of Hellfire Peninsula - beyond Hellfire Citadel.  You are welcome there as an ally, $N.$B$BIf you're looking for work, go there and tell Ranger Captain Venn'ren that I sent you.  He will see to it that you're given tasks worthy of someone of your caliber.",logDesc="Report to Ranger Captain Venn'ren at Falcon Watch in Hellfire Peninsula."} end
if not DB[9499] then DB[9499]={id=9499,zoneId=3483,name="Falcon Watch",level=62,minLevel=60,giver="Martik Tor'seldori",giverType="NPC",giverId=16577,ender="Ranger Captain Venn'ren",enderType="NPC",enderId=16789,rewardNextId=9340,poiX=134,poiY=2690,wowhead="https://www.wowhead.com/wotlk/quest=9499",image="assets/images/quests/placeholder.png",xpDiff=1,desc="What are you still doing here, $N?  Didn't you hear we built a proper sin'dorei outpost here in Hellfire Peninsula?$B$BSurely you'd rather be among fellow blood elves and away from all this... smell.  You'll find Falcon Watch in the southwest, beyond Hellfire Citadel.  Report to Ranger Captain Venn'ren; he will take care of you.$B$BThe road ahead is dangerous and heavily patrolled by Alliance scouts.  I would recommend travelling with companions.  Blood elves, preferably.",logDesc="Travel to Falcon Watch in the southwest of Hellfire Peninsula and report to Ranger Captain Venn'ren."} end
if not DB[9500] then DB[9500]={id=9500,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Sulaa",giverType="NPC",giverId=17219,ender="Farseer Nobundo",enderType="NPC",enderId=17204,rewardNextId=9501,poiX=-3778,poiY=-11407,wowhead="https://www.wowhead.com/wotlk/quest=9500",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It's been a while since last you were tested.  Farseer Nobundo has been asking for you.  You must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.$B$BYou remember where to find him at the Crystal Hall inside of the Exodar, right?",logDesc="Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle."} end
if not DB[9501] then DB[9501]={id=9501,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Farseer Nobundo",giverType="NPC",giverId=17204,ender="Aqueous",enderType="NPC",enderId=17275,rewardNextId=9503,poiX=-3804,poiY=-11397,wowhead="https://www.wowhead.com/wotlk/quest=9501",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A powerful water elemental named Aqueous has requested your presence.  It would seem that there is a great imbalance occurring in the water element on Bloodmyst Isle.  Not surprising given the unnatural predilections of the blood elves.$B$BYou will find Aqueous in a hidden reef under the waves off the northern shore of Bloodmyst Isle.$B$BTake this potion; it can help you to get to her once you get into the water near the reef.",logDesc="Speak with Aqueous in the Hidden Reef at Bloodmyst Isle."} end
if not DB[9502] then DB[9502]={id=9502,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Farseer Javad",giverType="NPC",giverId=23127,ender="Farseer Nobundo",enderType="NPC",enderId=17204,rewardNextId=9501,poiX=-4720,poiY=-1150,wowhead="https://www.wowhead.com/wotlk/quest=9502",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It's been a while since last you were tested.  Farseer Nobundo has been asking for you.  You must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.$B$BYou remember where to find him at the Crystal Hall inside of the Exodar, right?",logDesc="Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle."} end
if not DB[9503] then DB[9503]={id=9503,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Aqueous",giverType="NPC",giverId=17275,ender="Aqueous",enderType="NPC",enderId=17275,rewardNextId=9504,poiX=-1110,poiY=-11129,wowhead="https://www.wowhead.com/wotlk/quest=9503",image="assets/images/quests/placeholder.png",xpDiff=5,desc="In balance with the other elements, water is the source and sustenance of all living things.  It gives and nurtures life, and all rely upon it for their existence.  Yet, when polluted, it also brings life to an end.$B$BWe must determine the extent of the damage that has been done.  To the southwest is one such contaminated body of water that has come to be known as the Foul Pool.  Travel there and extract the foul essence from the water spirits that inhabit the pool.",logDesc="Collect 6 Foul Essences and return them to Aqueous in the Hidden Reef at Bloodmyst Isle."} end
if not DB[9504] then DB[9504]={id=9504,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Aqueous",giverType="NPC",giverId=17275,ender="Aqueous",enderType="NPC",enderId=17275,rewardNextId=9508,poiX=-1110,poiY=-11129,wowhead="https://www.wowhead.com/wotlk/quest=9504",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is worse than I feared. The corruption is very potent and if unchecked it could spread to the ocean currents and be carried throughout all of Azeroth!$B$BWe are going to need a sample of the purest water to counter this malignancy. There are ruins on the untainted portion of this island, to the southeast. Go there, where the Wrathscale naga reside, and take from their fountain.$B$BUse this bota bag to gather the sample. Hurry, $N!",logDesc="Fill the Empty Bota Bag and then return to Aqueous in the Hidden Reef at Bloodmyst Isle."} end
if not DB[9505] then DB[9505]={id=9505,zoneId=3524,name="The Prophecy of Velen",level=8,minLevel=5,giver="Daedal",giverType="NPC",giverId=17215,ender="Admiral Odesyus",enderType="NPC",enderId=17240,rewardNextId=9506,poiX=-4191,poiY=-12470,wowhead="https://www.wowhead.com/wotlk/quest=9505",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The Prophet spoke of this day: That on this island, in this new world, our allies would find us.$B$B\"We will be tested. They will ask that we pay for the sins of our fathers...\"$B$BAt the time, I did not understand the meaning behind his words, but seeing this creature and her reaction to us, it is now coming into focus. The corruption of our people has been felt even here.$B$BVenture south. It is there that we found this being. Find its kin and tell them of our people.",logDesc="Daedal wants you to travel south and seek out the people that the injured creature mentioned."} end
if not DB[9506] then DB[9506]={id=9506,zoneId=3524,name="A Small Start",level=7,minLevel=5,giver="Admiral Odesyus",giverType="NPC",giverId=17240,ender="Admiral Odesyus",enderType="NPC",enderId=17240,rewardNextId=9530,poiX=-4700,poiY=-12415,wowhead="https://www.wowhead.com/wotlk/quest=9506",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I am Admiral Odesyus of Alliance Naval Command. Our ship was forced to port on your island due to an infestation of sorts. It's embarrassing to even talk about, but goblins somehow managed to stow away in the holds of both of my ships.$B$BLast night, while most of the ship's crew was asleep below deck, they struck!$B$BStranger still, they took our navigation gear and jumped ship!$B$BThey disappeared into the thicket, east of here. Will you go in search of our gear? It will make for a strong gesture.",logDesc="Admiral Odesyus at Odesyus' Landing wants you to recover the Nautical Compass and Nautical Map stolen by the Venture Co."} end
if not DB[9507] then DB[9507]={id=9507,zoneId=3524,name="<DEPRECATED>From the Desk of Mogul Razdunk",level=8,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=9507",image="assets/images/quests/placeholder.png",xpDiff=5,desc="According to these plans,the goblins are here for the crystal wreckage of the Exodar. It would appear that the goblins are intent on strip-mining the island of the crystals and hijacking the two Alliance ships docked off-shore once their task is complete.$B$BYou should probably take these plans to Admiral Odesyus.",logDesc="Take the Top Secret Venture Co. Plans to Admiral Odesyus at Odesyus' Landing."} end
if not DB[9508] then DB[9508]={id=9508,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Aqueous",giverType="NPC",giverId=17275,ender="Aqueous",enderType="NPC",enderId=17275,rewardNextId=9509,poiX=-1110,poiY=-11129,wowhead="https://www.wowhead.com/wotlk/quest=9508",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I have determined where the corruption is coming from.  It is the by-product of some demented research and you're going to put an end to it!$B$BJust to the southwest of the Foul Pool is a small camp.  There you will find the 'research' of Tel'athion the Impure.  This is where he produces the filth that has been seeping into the island's water.$B$BUse the pure water you obtained from Ashenvale to destroy his cache of barrels.  That will be sure to bring him out.$B$BWe will have an end to this!",logDesc="Bring the Head of Tel'athion to Aqueous in the Hidden Reef at Bloodmyst Isle."} end
if not DB[9509] then DB[9509]={id=9509,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Aqueous",giverType="NPC",giverId=17275,ender="Farseer Nobundo",enderType="NPC",enderId=17204,poiX=-1110,poiY=-11129,wowhead="https://www.wowhead.com/wotlk/quest=9509",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I held back a little of the water from Ashenvale, not because I doubted your ability to deal with the situation.  Rather, I knew that you would succeed, and I wanted to make sure that you had something special to take back to Nobundo.$B$BHere, $N, take this flask of pure water.  It will ensure that you receive a very powerful water totem.$B$BFarseer Nobundo awaits your return at the Exodar.",logDesc="Take the Flask of Purest Water to Farseer Nobundo inside the Exodar on Azuremyst Isle.",rewards={{id=5177,qty=1}}} end
if not DB[9510] then DB[9510]={id=9510,zoneId=3483,name="Bristlehide Clefthoof Hides",level=62,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=9510",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="So you're looking to make yourself useful?  We're in very short supply of clefthoof hides, $N.$B$BIf you go southwest of here you'll find bristlehide clefthoof in abundance near a place called Falcon Watch.  Their hides are ideal for leatherworking.  Bring me a stack of them and I'll reward you appropriately.",logDesc="Provisioner Braknar at Mag'har Post in Hellfire Peninsula wants you to bring him 5 Bristlehide Clefthoof Hides."} end
if not DB[9511] then DB[9511]={id=9511,zoneId=3483,name="Kargath's Battle Plans",level=70,minLevel=67,wowhead="https://www.wowhead.com/wotlk/quest=9511",image="assets/images/quests/placeholder.png",desc="<TXT>The documents you found on Kargath's body detail plans on what appears to be a massive invasion on Honor Hold."} end
if not DB[9512] then DB[9512]={id=9512,zoneId=3524,name="Cookie's Jumbo Gumbo",level=7,minLevel=5,giver="\"Cookie\" McWeaksauce",giverType="NPC",giverId=17246,ender="\"Cookie\" McWeaksauce",enderType="NPC",enderId=17246,poiX=-4711,poiY=-12401,wowhead="https://www.wowhead.com/wotlk/quest=9512",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The Admiral be right, ye are a resourceful one. Mayhap ye could help Cookie out?$B$BIf I serve the crew chicken for dinner again, I'll be sent to the brig fer sure.$B$BI noticed that thar be crawlers all along the coastline - lots o' crawlers! Bring me crawler meats and I'll be forever indebted to ya.$B$BHelp a reformed pirate out?",logDesc="\"Cookie\" McWeaksauce at the Odesyus' Landing wants you to bring him 6 Skittering Crawler Meat.$B",rewards={{id=23756,qty=10}}} end
if not DB[9513] then DB[9513]={id=9513,zoneId=3524,name="Reclaiming the Ruins",level=8,minLevel=6,giver="Priestess Kyleen Il'dinare",giverType="NPC",giverId=17241,ender="Priestess Kyleen Il'dinare",enderType="NPC",enderId=17241,poiX=-4702,poiY=-12418,wowhead="https://www.wowhead.com/wotlk/quest=9513",image="assets/images/quests/placeholder.png",xpDiff=5,desc="While some may look at our current predicament as an unfortunate turn of events, I sense that we are here for a reason. The invisible hand of fate has pushed us in this direction. The reason why will become evident in time.$B$BTo the west lies an ancient night elf city, now in ruin and overrun with naga. It would be remiss of me to sit idly by as the naga tainted my ancestral lands.$B$BYou have shown yourself a capable $c. Honor my people and cleanse the ruins of their unwelcome inhabitants.",logDesc="Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle wants you to kill 5 Wrathscale Myrmidons, 5 Wrathscale Naga and 5 Wrathscale Sirens."} end
if not DB[9514] then DB[9514]={id=9514,zoneId=3524,name="Rune Covered Tablet",level=8,minLevel=6,ender="Priestess Kyleen Il'dinare",enderType="NPC",enderId=17241,wowhead="https://www.wowhead.com/wotlk/quest=9514",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You cannot make out any of the symbols on the tablet. Perhaps the priestess would be able to decipher the mysterious runes.",logDesc="Take the Rune Covered Tablet to Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle.$B"} end
if not DB[9515] then DB[9515]={id=9515,zoneId=3524,name="Warlord Sriss'tiz",level=10,minLevel=6,giver="Priestess Kyleen Il'dinare",giverType="NPC",giverId=17241,ender="Priestess Kyleen Il'dinare",enderType="NPC",enderId=17241,poiX=-4702,poiY=-12418,wowhead="https://www.wowhead.com/wotlk/quest=9515",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="A naga invasion would be disastrous, $N. I've seen what naga can do and I would not want to see such a catastrophe befall any being. If I were to guess, this Warlord Sriss'tiz will be hidden in a cave - probably along the coast to the west.$B$BFind Warlord Sriss'tiz and put an end to his reign.",logDesc="Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle wants you to kill Warlord Sriss'tiz.",choiceRewards={{id=24448,qty=1},{id=24447,qty=1}}} end
if not DB[9516] then DB[9516]={id=9516,zoneId=331,name="Destroy the Legion",level=30,minLevel=27,giver="Vindicator Vedaar",giverType="NPC",giverId=17303,ender="Vindicator Vedaar",enderType="NPC",enderId=17303,poiX=2995,poiY=-3286,wowhead="https://www.wowhead.com/wotlk/quest=9516",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="I will not tolerate their existence on this world!  The Burning Legion all but destroyed our race and we fell back to settle a new home on a new world.  Then they came again.  And we retreated, over and over.$B$BNo more!$B$BThere is a remnant of the Legion to the south in the regions known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge.  They are what is leftover from a force that once long ago invaded this world.$B$BGo and destroy as many as you can before it is too late!",logDesc="Slay 6 Mannoroc Lashers, 6 Felguards and 6 Searing Infernals, and then return to Vindicator Vedaar at Forest Song in Ashenvale."} end
if not DB[9517] then DB[9517]={id=9517,zoneId=331,name="A Shameful Waste",level=28,minLevel=24,giver="Architect Nemos",giverType="NPC",giverId=17291,ender="3",enderType="NPC",enderId=17310,poiX=2950,poiY=-3307,wowhead="https://www.wowhead.com/wotlk/quest=9517",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Welcome to Forest Song, $c. Where you see tents, there will one day be buildings, but such ambitions require a steady stream of building materials. I cannot bring myself to order our workers to fell any of the ancient trees of this grove, but our neighbors to the south and west have no such reverence for the forest.$B$BWe shall relieve the Warsong loggers of their excess, and reclaim some of the tainted wood from the satyr stronghold to the west. Bring the wood to Gnarl, who will purify it for our use.",logDesc="Bring 15 pieces of Warsong Lumber and 5 Satyrnaar Fel Wood to Gnarl at Forest Song."} end
if not DB[9518] then DB[9518]={id=9518,zoneId=331,name="Agents of Destruction",level=28,minLevel=24,giver="Sentinel Luciel Starwhisper",giverType="NPC",giverId=17287,ender="Sentinel Luciel Starwhisper",enderType="NPC",enderId=17287,poiX=2968,poiY=-3260,wowhead="https://www.wowhead.com/wotlk/quest=9518",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="The Warsong Lumber Camp is a blight upon an embattled landscape. Every time we make progress in halting their operations, Overseer Gorthak orders his loggers to redouble their efforts!$B$BNow, the orcs are cutting more wood than they can possibly use, leaving it to rot while their blades bite into fresh trees! This is an affront to all we stand for, $N, and we will show them that we'll not suffer further destruction of our lands!$B$BGo, and do not rest until Overseer Gorthak and his minions are dead!",logDesc="Sentinel Luciel Starwhisper at Forest Song wants you to kill Overseer Gorthak, 2 Warsong Shredders, 5 Horde Deforesters, and 10 Horde Scouts."} end
if not DB[9519] then DB[9519]={id=9519,zoneId=331,name="The Lost Chalice",level=27,minLevel=23,giver="Kayneth Stillwind",giverType="NPC",giverId=3848,ender="Kayneth Stillwind",enderType="NPC",enderId=3848,poiX=2954,poiY=-3215,wowhead="https://www.wowhead.com/wotlk/quest=9519",image="assets/images/quests/placeholder.png",xpDiff=5,money=2200,desc="The area to our west, now called Satyrnaar, was once a prominent shrine built by my people. It housed a priceless relic, the Chalice of Elune, entrusted to the shrine's keepers by the priests of Elune. Pilgrims once traveled to the shrine to experience the healing powers the chalice was rumored to hold.$B$BThese stories might be nothing but old wives' tales, but if there is any truth to them, the relic may hold the key to rejuvenating the wounded forest. I must know, $N.",logDesc="Bring the Chalice of Elune to Kayneth Stillwind at Forest Song."} end
if not DB[9520] then DB[9520]={id=9520,zoneId=331,name="Diabolical Plans",level=30,minLevel=27,ender="Vindicator Vedaar",enderType="NPC",enderId=17303,rewardNextId=9522,wowhead="https://www.wowhead.com/wotlk/quest=9520",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The demon dropped this parchment, which is amazingly written in the Common tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.$B$BThe plans detail preparations for a demonic attack on Forest Song to the north; the location where a new draenei settlement is being established.$B$BPerhaps Vindicator Vedaar at Forest Song would be interested in these?",logDesc="Deliver the Diabolical Plans to Vindicator Vedaar at Forest Song in Ashenvale."} end
if not DB[9521] then DB[9521]={id=9521,zoneId=331,name="Report from the Northern Front",level=25,minLevel=21,giver="Sentinel Luciel Starwhisper",giverType="NPC",giverId=17287,ender="Sentinel Farsong",enderType="NPC",enderId=14733,poiX=2968,poiY=-3260,wowhead="https://www.wowhead.com/wotlk/quest=9521",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The battle against the Warsong Lumber Camp isn't being waged from Forest Song alone, $N. There's a more substantial Silverwing Sentinel presence at Silverwing Grove to the southwest, near the border with the Barrens. From the grove, Sentinel Farsong directs our efforts against those who would destroy our lands.$B$BI'm a bit late in sending my latest report to Sentinel Farsong, but also hesitant to leave Forest Song unattended. If your travels take you near Silverwing Grove, would you deliver my report?",logDesc="Deliver Sentinel Luciel's report to Sentinel Farsong at Silverwing Grove."} end
if not DB[9522] then DB[9522]={id=9522,zoneId=331,name="Never Again!",level=32,minLevel=27,giver="Vindicator Vedaar",giverType="NPC",giverId=17303,ender="Vindicator Vedaar",enderType="NPC",enderId=17303,poiX=2995,poiY=-3286,wowhead="https://www.wowhead.com/wotlk/quest=9522",image="assets/images/quests/placeholder.png",xpDiff=6,money=6500,desc="$N, it falls to you to see that this attack by the Burning Legion never comes to pass.  You must go and slay their leaders.  Without them the rest of the demons are essentially mindless.$B$BYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.$B$BDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.  To find the ridge, look for a ramp up from Demon Fall Canyon near the Horde's monument to Grom Hellscream.",logDesc="Kill Gorgannon and Diathorus the Seeker, and then return to Vindicator Vedaar at Forest Song in Ashenvale.",choiceRewards={{id=24119,qty=1},{id=24120,qty=1},{id=24118,qty=1}}} end
if not DB[9523] then DB[9523]={id=9523,zoneId=3524,name="Precious and Fragile Things Need Special Handling",level=8,minLevel=6,giver="Archaeologist Adamant Ironheart",giverType="NPC",giverId=17242,ender="Archaeologist Adamant Ironheart",enderType="NPC",enderId=17242,poiX=-4694,poiY=-12423,wowhead="https://www.wowhead.com/wotlk/quest=9523",image="assets/images/quests/placeholder.png",xpDiff=5,money=225,desc="The priestess tells me that the ruins to the west are what's left of a night elf civilization. That got me thinking about what my pappy used to always say about night elf ruins, \"Sonny, whenever you see night elf ruins, night elf relics are sure to be close by.\"$B$BNow what kind of a dwarf would I be if I didn't hire the first person I saw to go digging up night elf relics for me? Now get going!",logDesc="Archaeologist Adamant Ironheart at Odesyus' Landing on Azuremyst Isle wants you to bring him 8 Ancient Relics."} end
if not DB[9524] then DB[9524]={id=9524,zoneId=3535,name="Imprisoned in the Citadel",level=70,minLevel=67,giver="Randy Whizzlesprocket",giverType="NPC",giverId=17288,ender="Captain Alina",enderType="NPC",enderId=17290,poiX=131,poiY=255,wowhead="https://www.wowhead.com/wotlk/quest=9524",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Alliance, here?!  Listen carefully, $c.$B$BKargath has captured several of our soldiers.  Captain Alina, an important officer is among them.  You must try to save her before she is executed.$B$BDon't worry about me, I'll find a way out as soon as I catch my breath.",logDesc="Rescue Captain Alina inside Hellfire Citadel before she is executed.$B$BThis quest must be completed in Heroic dungeon difficulty.",rewards={{id=29434,qty=2}}} end
if not DB[9525] then DB[9525]={id=9525,zoneId=3535,name="Imprisoned in the Citadel",level=70,minLevel=67,giver="Drisella",giverType="NPC",giverId=17294,ender="Captain Boneshatter",enderType="NPC",enderId=17296,wowhead="https://www.wowhead.com/wotlk/quest=9525",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="I was fortunate to escape Kargath's prison today, $N.  Several prisoners are scheduled to be executed, an important officer among them.$B$BIt would be a huge blow against our forces if Captain Boneshatter was slain.  You must do what you can to rescue him.  I'm too weak to go on...",logDesc="Rescue Captain Boneshatter inside Hellfire Citadel before he is executed.$B$BThis quest must be completed in Heroic dungeon difficulty.",rewards={{id=29434,qty=2}}} end
if not DB[9526] then DB[9526]={id=9526,zoneId=331,name="Reclaiming Felfire Hill",level=30,minLevel=27,giver="3",giverType="NPC",giverId=17310,ender="3",enderType="NPC",enderId=17310,poiX=2919,poiY=-3154,wowhead="https://www.wowhead.com/wotlk/quest=9526",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="Little one, to the south is an area of Nightsong Woods that has in recent times come to be called Felfire Hill.  It is very sad to see the demons crawling over it, spreading their corruption.$B$BWould you do something to help take back the land?$B$BI have a number of seeds that I have been saving for such a purpose.  Take them to Felfire Hill and plant them in the fertile dirt mounds.",logDesc="Plant 8 Tree Seedlings in the Fertile Dirt Mounds and then return to Gnarl at Forest Song in Ashenvale."} end
if not DB[9527] then DB[9527]={id=9527,zoneId=3524,name="All That Remains",level=10,minLevel=6,giver="Cowlen",giverType="NPC",giverId=17311,ender="Cowlen",enderType="NPC",enderId=17311,poiX=-5358,poiY=-11175,wowhead="https://www.wowhead.com/wotlk/quest=9527",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We had lived peacefully among the Owlbeasts of this island for many years. You can imagine my surprise when they stormed the beach and attacked us.$B$BI fought tooth and nail but was easily overpowered. As I blacked out from the vicious blows that I had been dealt, I prayed that my family not suffer.$B$BWhen I awoke, all was quiet. The sand was soaked red with blood - their blood. They were devoured whole.$B$BI care not for vengeance, $N. I only ask that their remains be returned to me for proper burial.",logDesc="Cowlen on Azuremyst Isle wants you to recover the Remains of Cowlen's Family."} end
if not DB[9528] then DB[9528]={id=9528,zoneId=3524,name="A Cry For Help",level=10,minLevel=6,giver="Magwin",giverType="NPC",giverId=17312,ender="Cowlen",enderType="NPC",enderId=17311,poiX=-4781,poiY=-11055,wowhead="https://www.wowhead.com/wotlk/quest=9528",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My family was attacked by the murlocs and owlkin of this island several weeks ago. I managed to escape but I think that both my mother and father have been slain. I don't know what I'm going to do now, but I must try and get back to my home - or what's left of it... Will you help me get through the forest?",logDesc="Escort Magwin through the island to her home.",rewards={{id=24113,qty=1}}} end
if not DB[9529] then DB[9529]={id=9529,zoneId=-61,name="The Stone",level=-1,minLevel=10,giver="Talionia",giverType="NPC",giverId=16647,rewardNextId=9619,poiX=9773,poiY=-7302,wowhead="https://www.wowhead.com/wotlk/quest=9529",image="assets/images/quests/placeholder.png",xpDiff=5,desc="While I'm certain your imp has proven a useful and sometimes entertaining servant, it is time you mastered a more powerful demon: the voidwalker.$b$bTravel down the Dead Scar until it is crossed by the Elrendar River.  Just south of the river, locate one of the blue glowing stones and take it.  Your path will be revealed there.",logDesc="Obtain a Voidstone from the Dead Scar."} end
if not DB[9530] then DB[9530]={id=9530,zoneId=3524,name="I've Got a Plant",level=9,minLevel=5,giver="Admiral Odesyus",giverType="NPC",giverId=17240,ender="Admiral Odesyus",enderType="NPC",enderId=17240,rewardNextId=9531,poiX=-4700,poiY=-12415,wowhead="https://www.wowhead.com/wotlk/quest=9530",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I've wondered about this for some time now, but this proves it to be true.$B$BThere is a traitor among us.$B$BThe plans left behind by the goblins document the conspiracy. Since I don't know who it could be, I'm going to need your help in finding the traitor. None of my crew can be trusted.$B$BIf this is going to work, I'm going to need a hollowed out tree and leaves. Search near the loggers north of us for the tree. You'll need to find the leaves by yourself. Check the forest.",logDesc="Admiral Odesyus at Odesyus' Landing on Azuremyst Isle wants you to bring him a Hollowed Out Tree and 5 Piles of Leaves."} end
if not DB[9531] then DB[9531]={id=9531,zoneId=3524,name="Tree's Company",level=9,minLevel=5,giver="Admiral Odesyus",giverType="NPC",giverId=17240,ender="Admiral Odesyus",enderType="NPC",enderId=17240,rewardNextId=9537,poiX=-4700,poiY=-12415,wowhead="https://www.wowhead.com/wotlk/quest=9531",image="assets/images/quests/placeholder.png",xpDiff=4,money=900,desc="According to the plans, the traitor and the leader of the goblins, Geezle, are to meet at a cove on the western island. I need you to be at that meeting, $N.$B$BRemember the tree and leaves? You're going to wear them! It's a perfect disguise.$B$BGo to the cove and look for a naga flag. If the flag is there, it means a meeting is planned. Use the disguise kit when you see the flag and wait. Eventually the traitor will show up. Let the meeting finish then return to me with the identity of the scoundrel.",logDesc="Admiral Odesyus at Odesyus' Landing on Azuremyst Isle wants you to observe the meeting that is to take place between Geezle and the traitor.$B$BReturn to him when you know the identity of the traitor."} end
if not DB[9532] then DB[9532]={id=9532,zoneId=-162,name="Find Keltus Darkleaf",level=10,minLevel=10,giver="Zelanis",giverType="NPC",giverId=16684,ender="Keltus Darkleaf",enderType="NPC",enderId=17224,rewardNextId=9460,poiX=9733,poiY=-7366,wowhead="https://www.wowhead.com/wotlk/quest=9532",image="assets/images/quests/placeholder.png",xpDiff=5,desc="$n, one of our scouts has taken too strong an interest in his duties.  He surveys our enemies relentlessly, but sends no reports of his findings.$b$bYou must find this spy, Keltus Darkleaf, convince him to hand over his report and return it to me as swiftly as possible.  He can be found far to the southwest, where the Elrendar River forks and flows around Goldenmist Village.  The night elves of An'daroth are his quarry, and he won't be far from them.",logDesc="Locate Keltus Darkleaf."} end
if not DB[9533] then DB[9533]={id=9533,zoneId=331,name="A Helping Hand",level=25,minLevel=22,giver="Vindicator Palanaar",giverType="NPC",giverId=17106,ender="Architect Nemos",enderType="NPC",enderId=17291,poiX=2762,poiY=-312,wowhead="https://www.wowhead.com/wotlk/quest=9533",image="assets/images/quests/placeholder.png",xpDiff=3,desc="My people have undertaken an important endeavor in the eastern part of Ashenvale, with support and cooperation from the kaldorei.$B$BUnder the supervision of Architect Nemos and Vindicator Vedaar, they are revitalizing an old night elf outpost. The task of building won't be easy, $N, for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested $g men:women; his way.",logDesc="Make your way to Forest Song and speak with Architect Nemos."} end
if not DB[9534] then DB[9534]={id=9534,zoneId=331,name="Destroy the Legion",level=30,minLevel=27,giver="Valusha",giverType="NPC",giverId=17355,ender="Valusha",enderType="NPC",enderId=17355,poiX=2352,poiY=-2523,wowhead="https://www.wowhead.com/wotlk/quest=9534",image="assets/images/quests/placeholder.png",xpDiff=5,money=2500,desc="The remains of the demonic Burning Legion have been making raids against our Warsong Lumber Camp!$B$BNo more!$B$BThe demons are attacking from the areas known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge to the east.$B$BGo and destroy as many as you can to bring glory to both yourself and the Horde!",logDesc="Slay 6 Mannoroc Lashers, 6 Felguards and 6 Searing Infernals, and then return to Valusha at Splintertree Post in Ashenvale."} end
if not DB[9535] then DB[9535]={id=9535,zoneId=331,name="Diabolical Plans",level=30,minLevel=27,ender="Valusha",enderType="NPC",enderId=17355,rewardNextId=9536,wowhead="https://www.wowhead.com/wotlk/quest=9535",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The demon dropped this parchment, which is amazingly written in the Orcish tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.$B$BThe plans detail preparations for a demonic attack on Splintertree Post to the northwest.$B$BYou're certain that Valusha at Splintertree Post would be interested in these.",logDesc="Deliver the Diabolical Plans to Valusha at Splintertree Post in Ashenvale."} end
if not DB[9536] then DB[9536]={id=9536,zoneId=331,name="Never Again!",level=32,minLevel=27,giver="Valusha",giverType="NPC",giverId=17355,ender="Valusha",enderType="NPC",enderId=17355,poiX=2352,poiY=-2523,wowhead="https://www.wowhead.com/wotlk/quest=9536",image="assets/images/quests/placeholder.png",xpDiff=6,money=6500,desc="$N, you will see to it that this attack by the Burning Legion never comes to pass!  Go and slay these dreadlords!  Without them the rest of the demons are essentially mindless.$B$BYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.$B$BDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.  To find the ridge, look for a ramp up from Demon Fall Canyon near the monument to Grom Hellscream.",logDesc="Kill Gorgannon and Diathorus the Seeker.",choiceRewards={{id=24119,qty=1},{id=24120,qty=1},{id=24118,qty=1}}} end
if not DB[9537] then DB[9537]={id=9537,zoneId=3524,name="Show Gnomercy",level=9,minLevel=5,giver="Admiral Odesyus",giverType="NPC",giverId=17240,ender="Admiral Odesyus",enderType="NPC",enderId=17240,rewardNextId=9602,poiX=-4700,poiY=-12415,wowhead="https://www.wowhead.com/wotlk/quest=9537",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Spark must be brought to justice!$B$BI need you to go down to the beach and find that deceitful gnome. Once you find him, get whatever information you can out of him!$B$BIf a high ranking official of the Alliance has committed treasonous acts, who knows how many others are corrupt?$B$BAnd $N, use force if you have to...$B",logDesc="Admiral Odesyus at Odesyus' Landing wants you to recover the Traitor's Communication from Engineer \"Spark\" Overgrind.",choiceRewards={{id=24433,qty=1},{id=24431,qty=1},{id=24430,qty=1},{id=24434,qty=1},{id=24432,qty=1}}} end
if not DB[9538] then DB[9538]={id=9538,zoneId=3524,name="Learning the Language",level=8,minLevel=8,giver="Cryptographer Aurren",giverType="NPC",giverId=17232,ender="Totem of Akida",enderType="NPC",enderId=17360,rewardNextId=9539,poiX=-4177,poiY=-12510,wowhead="https://www.wowhead.com/wotlk/quest=9538",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I think I've cracked it, $N!$B$B<Aurren points to the totem.>$B$BAll that we need to know about the Stillpine furbolg language is imprinted on their totems. With just a rudimentary understanding of how their symbols work, we can study the totems and learn to communicate with the furbolgs.$B$BI've written down the basics of the symbol matrix on this parchment. Study it and then examine the totem. It should lead you to the next language totem.$B$BSpeak to Arugoo when you return an educated $r!",logDesc="Read the Stillpine Furbolg Language Primer that Aurren gave you and interact with the Totem of Akida at Azure Watch."} end
if not DB[9539] then DB[9539]={id=9539,zoneId=3524,name="Totem of Coo",level=10,minLevel=8,giver="Totem of Akida",giverType="NPC",giverId=17360,ender="Totem of Coo",enderType="NPC",enderId=17361,rewardNextId=9540,poiX=-4178,poiY=-12512,wowhead="https://www.wowhead.com/wotlk/quest=9539",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You begin to read the totem, barely able to pronounce the awkward words and phrases. Slowly, words start to form in your head. You think that the totem is telling you to go up the nearby hill, to the northeast.",logDesc="Find the Totem of Coo using the clues provided to you."} end
if not DB[9540] then DB[9540]={id=9540,zoneId=3524,name="Totem of Tikti",level=10,minLevel=8,giver="Totem of Coo",giverType="NPC",giverId=17361,ender="Totem of Tikti",enderType="NPC",enderId=17362,rewardNextId=9541,poiX=-3924,poiY=-12748,wowhead="https://www.wowhead.com/wotlk/quest=9540",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You begin to read the totem, better able to pronounce the words and phrases. Words start to form in your head. You think that the totem is telling you to go across the Crystalbrook river to the east. Perhaps your destination is on the other side of the river.",logDesc="Find the Totem of Tikti using the clues provided to you."} end
if not DB[9541] then DB[9541]={id=9541,zoneId=3524,name="Totem of Yor",level=10,minLevel=8,giver="Totem of Tikti",giverType="NPC",giverId=17362,ender="Totem of Yor",enderType="NPC",enderId=17363,rewardNextId=9542,poiX=-3873,poiY=-13124,wowhead="https://www.wowhead.com/wotlk/quest=9541",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The symbols on this totem seem to translate much faster. The patterns and imagery all seem to blend into familiar words. You are fairly certain the totem is pointing you south, down the river. Something is at the bottom of the river itself.",logDesc="Find the Totem of Yor using the clues provided to you."} end
if not DB[9542] then DB[9542]={id=9542,zoneId=3524,name="Totem of Vark",level=10,minLevel=8,giver="Totem of Yor",giverType="NPC",giverId=17363,ender="Totem of Vark",enderType="NPC",enderId=17364,rewardNextId=9544,poiX=-4636,poiY=-13069,wowhead="https://www.wowhead.com/wotlk/quest=9542",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You no longer see unrecognizable symbology in the totems. The totem of Yor reads to you just as easily as your native tongue.$B$BThe markings identify another furbolg den, due west of here. You are able to expertly decipher the language on the totem and know that your destination is Bristlelimb Village. Yor will guide you but if you get lost, you know that you are able to take the ancient elven road in the forest leading west to reach your destination.",logDesc="Find the Totem of Vark using the clues provided to you."} end
if not DB[9543] then DB[9543]={id=9543,zoneId=3483,name="Atonement",level=63,minLevel=60,giver="Anchorite Obadei",giverType="NPC",giverId=16834,ender="Amaan the Wise",enderType="NPC",enderId=16796,rewardNextId=9430,poiX=91,poiY=4352,wowhead="https://www.wowhead.com/wotlk/quest=9543",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Our history with the orcs is one of constant conflict, $N.  We were once near driven to extinction due to their bloodlust and have since then avoided them even when not under demonic influence.$B$BYet, this retaliation... it's not what Sedai would've wanted.  Speak with our elder, Amaan the Wise.  He will help shed light on these events.",logDesc="Speak to Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula."} end
if not DB[9544] then DB[9544]={id=9544,zoneId=3524,name="The Prophecy of Akida",level=10,minLevel=8,giver="Totem of Vark",giverType="NPC",giverId=17364,ender="Arugoo of the Stillpine",enderType="NPC",enderId=17114,poiX=-4487,poiY=-11644,wowhead="https://www.wowhead.com/wotlk/quest=9544",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The images on this totem depict a war between the Stillpine and the Bristlelimb furbolg tribes. The etchings show that the Bristlelimb have done unconscionable things to the furbolgs of Stillpine.$B$BAmidst the chaos, a prophecy has begun to unfold: A hero will rise - not of furbolg blood - and save the Stillpine tribe.$B$BSlay Bristlelimb furbolgs at Bristlelimb Village for their keys. Use the keys to free the Stillpine captives. Return to Arugoo of the Stillpine when you have freed them all!$B",logDesc="Free 8 Stillpine Captives from cages found in Bristlelimb Village. Return to Arugoo of the Stillpine at Azure Watch when you have completed this task.",choiceRewards={{id=27399,qty=1},{id=27403,qty=1},{id=27401,qty=1}}} end
if not DB[9545] then DB[9545]={id=9545,zoneId=3483,name="The Seer's Relic",level=63,minLevel=60,giver="Amaan the Wise",giverType="NPC",giverId=16796,ender="Amaan the Wise",enderType="NPC",enderId=16796,poiX=223,poiY=4330,wowhead="https://www.wowhead.com/wotlk/quest=9545",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The stubborn close their mind and convince themselves of one truth.  The wise keep an open mind to the different possibilities leading to and stemming from the present.$B$BTake this relic with you to where you found Sedai.  See not with your eyes, $N, but with your mind.",logDesc="Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula wants you to return to Sedai's Corpse, northeast of the Temple of Telhamat, and use the Seer's Relic at that location.  Return to him after you've completed this task.",choiceRewards={{id=25508,qty=1},{id=25506,qty=1},{id=25507,qty=1}}} end
if not DB[9546] then DB[9546]={id=9546,zoneId=3524,name="Fulfilling a Promise",level=8,minLevel=7,rewardNextId=9559,wowhead="https://www.wowhead.com/wotlk/quest=9546",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The prophecy spoke of one that would rise and deliver us from the oppressive grasp of Bristlelimb -- that the spirits themselves would herald the arrival of this hero.$B$BAnd now,you have come.$B$BI humble myself before you,great one. I beg of you,save our younglings. They were taken by the Bristlelimb while our guard was down. You will find them in cages at Bristlelimb Village,to the southwest. The Bristlelimb furbolgs hold the keys to the cages. Strike them down and take their keys. Release my kin.",logDesc="Arugoo of the Stillpine has asked that you free 8 Stillpine Captives from cages found in Bristlelimb Village.",choiceRewards={{id=24442,qty=1},{id=24443,qty=1},{id=24444,qty=1}}} end
if not DB[9547] then DB[9547]={id=9547,zoneId=-82,name="Call of Air",level=-1,minLevel=30,giver="Farseer Javad",giverType="NPC",giverId=23127,ender="Farseer Nobundo",enderType="NPC",enderId=17204,rewardNextId=9552,poiX=-4720,poiY=-1150,wowhead="https://www.wowhead.com/wotlk/quest=9547",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!$B$BI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.",logDesc="Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle."} end
if not DB[9548] then DB[9548]={id=9548,zoneId=3525,name="Pilfered Equipment",level=17,minLevel=13,giver="Clopper Wizbang",giverType="NPC",giverId=17421,ender="Clopper Wizbang",enderType="NPC",enderId=17421,poiX=-1220,poiY=-11450,wowhead="https://www.wowhead.com/wotlk/quest=9548",image="assets/images/quests/placeholder.png",xpDiff=5,money=900,desc="Shh! Keep your voice down and don't call attention to me.$B$BIf the murlocs detect my presence, the experiment will be ruined! I've already come perilously close to contaminating my data.$B$BWhile I was foraging yesterday, one of them must've wandered too close and discovered my camp. I returned just in time to see two of them carrying off a crate with most of my equipment! It's bound to be in one of their settlements around here, but I can't risk revealing my presence. Are you willing to help?",logDesc="Bring Clopper's Equipment back to Clopper Wizbang, who is hiding in a beached turtle shell."} end
if not DB[9549] then DB[9549]={id=9549,zoneId=3525,name="Artifacts of the Blacksilt",level=17,minLevel=13,giver="Clopper Wizbang",giverType="NPC",giverId=17421,ender="Clopper Wizbang",enderType="NPC",enderId=17421,poiX=-1220,poiY=-11450,wowhead="https://www.wowhead.com/wotlk/quest=9549",image="assets/images/quests/placeholder.png",xpDiff=5,money=900,desc="My observations and writings about the Blacksilt murlocs are quite illuminating, $N, but they are just the beginning. I plan to return to Ironforge with items produced by the Blacksilts' rudimentary crafting skills.$B$BThe problem is that the Blacksilt carry these items with them at all times, and I can't have their blood on my conscience. If you're willing to help me gather the idols carried by Blacksilt seers and crude knives of the Blacksilt warriors and shorestrikers, I won't ask how you came by them.",logDesc="Bring 3 Crude Murloc Idols and 6 Crude Murloc Knives to Clopper Wizbang, who is hiding in a beached turtle shell.",rewards={{id=23837,qty=1}}} end
if not DB[9550] then DB[9550]={id=9550,zoneId=3525,name="A Map to Where?",level=16,minLevel=13,rewardNextId=9557,wowhead="https://www.wowhead.com/wotlk/quest=9550",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The crudely-drawn map reveals nothing of its maker, but it appears to have been drawn with an unsteady hand. Wavering lines and symbols depict a small pavilion with broken columns located to the west of a partially submerged tower. $B$BIf the map is to be believed, this cluster of ruins appears to be located on the eastern coast of the island. You have no idea what you'll find, but it was important enough for the map's creator to record.",logDesc="Locate the pavilion described by the map and search for what the map's maker was trying to record."} end
if not DB[9551] then DB[9551]={id=9551,zoneId=-82,name="Call of Air",level=-1,minLevel=30,giver="Sulaa",giverType="NPC",giverId=17219,ender="Farseer Nobundo",enderType="NPC",enderId=17204,rewardNextId=9552,poiX=-3778,poiY=-11407,wowhead="https://www.wowhead.com/wotlk/quest=9551",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!$B$BI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.",logDesc="Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle."} end
if not DB[9552] then DB[9552]={id=9552,zoneId=-82,name="Call of Air",level=-1,minLevel=30,giver="Farseer Nobundo",giverType="NPC",giverId=17204,ender="Velaada",enderType="NPC",enderId=17431,rewardNextId=9553,poiX=-3804,poiY=-11397,wowhead="https://www.wowhead.com/wotlk/quest=9552",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The great spirit of air calls out to you, $N, and it is time for you to take heed.$B$BI wish for you to travel up the Wildwind Path on the north facing of the mountain that the Exodar has crashed into.  At its peak you will find a cave and within will be one of my most accomplished pupils, Velaada.$B$BPlease, listen to her wisdom and do as she bids.  When you return you will have a greater understanding of the element of air.",logDesc="Speak with Velaada at Wildwind Peak on Azuremyst Isle."} end
if not DB[9553] then DB[9553]={id=9553,zoneId=-82,name="Call of Air",level=-1,minLevel=30,giver="Velaada",giverType="NPC",giverId=17431,ender="3",enderType="NPC",enderId=17435,rewardNextId=9554,poiX=-3769,poiY=-11514,wowhead="https://www.wowhead.com/wotlk/quest=9553",image="assets/images/quests/placeholder.png",xpDiff=2,desc="While air may seem ethereal, it is an all pervasive force, covering and permeating everything around us.$B$BThough you cannot see it, the rocks of this cave are composed mostly of air, the waters of the oceans are saturated in it and without it, fire cannot be sustained.  Just don't let those elements hear you repeat that!$B$BWho you really wish to speak with for such wisdom is nearby.  At the northern edge of the precipice, Susurrus awaits you.  It is from him that you will gain understanding.",logDesc="Speak with Susurrus at Wildwind Peak on Azuremyst Isle."} end
if not DB[9554] then DB[9554]={id=9554,zoneId=-82,name="Call of Air",level=-1,minLevel=30,giver="3",giverType="NPC",giverId=17435,ender="Farseer Nobundo",enderType="NPC",enderId=17204,poiX=-3677,poiY=-11408,wowhead="https://www.wowhead.com/wotlk/quest=9554",image="assets/images/quests/placeholder.png",xpDiff=6,desc="While my brothers and sisters of the other elements have demanded that you perform various tasks, I will not ask anything further of you.  I think that you have done enough to 'atone' for the accident of your ship falling to this place from my skies.  I can see that you have all the wisdom within you already to use the element of air wisely.$B$BTake this portion of my being back to Farseer Nobundo so that he might help you fashion your totem.  And when you're ready, I will fly you back down to the Exodar.",logDesc="Return to Farseer Nobundo at the Exodar on Azuremyst Isle with the Whorl of Air.",rewards={{id=5178,qty=1}}} end
if not DB[9555] then DB[9555]={id=9555,zoneId=-82,name="Call of Fire",level=-1,minLevel=10,giver="3",giverType="NPC",giverId=17468,ender="Farseer Nobundo",enderType="NPC",enderId=17204,poiX=-3994,poiY=-11414,wowhead="https://www.wowhead.com/wotlk/quest=9555",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I am thankful that you have chosen the difficult path of the shaman. Few enough do, but I foresee it as critical to our future that we learn shamanism from the Broken.$B$BThey are called that, but once they were draenei. Fel magics transformed them, and that is why they cannot call upon the power of the Light. Some disapprove of them and the shamanism they teach, but they are not evil.$B$BI wish you to speak with Farseer Nobundo. He is the wisest shaman I know and you will learn much with his guidance.",logDesc="Speak with Farseer Nobundo at the Crystal Hall in the Exodar.",rewards={{id=5176,qty=1}}} end
if not DB[9556] then DB[9556]={id=9556,zoneId=0,name="To The Victor...",level=60,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=9556",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You've no doubt been fighting long and hard among the towers, $r. We would like to give something back to you in return for your defense of these lands, but first, you must prove to us you understand the weight of the tragedies that took place here.$b$bWalk the streets of Stratholme and find a vial of the holy water. Once you have it, travel to the mage quarter of Stormwind or the Undercity... There, if you are victorious within these lands, you will find my colleague.",logDesc="Collect a bottle of Stratholme Holy Water from within the city of Stratholme and deliver it to the Lordaeron Mage within the Mage Quarter of Stormwind or the Undercity when your side is victorious in the Eastern Plaguelands."} end
if not DB[9557] then DB[9557]={id=9557,zoneId=3525,name="Deciphering the Book",level=16,minLevel=13,ender="Anchorite Paetheus",enderType="NPC",enderId=17424,wowhead="https://www.wowhead.com/wotlk/quest=9557",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Lacking the means to read the book's contents, you think about who might be able to help you separate the author's words from the mapmaker's scrawl.$B$BRemembering Anchorite Paetheus's collection of artifacts from countless cultures, you wonder if his experienced eye might be able to help you decipher the book's contents.",logDesc="Take the Ancient Journal to Anchorite Paetheus in Blood Watch."} end
if not DB[9558] then DB[9558]={id=9558,zoneId=3483,name="The Longbeards",level=62,minLevel=60,giver="Sid Limbardi",giverType="NPC",giverId=16826,ender="Gremni Longbeard",enderType="NPC",enderId=16850,rewardNextId=9417,poiX=-709,poiY=2739,wowhead="https://www.wowhead.com/wotlk/quest=9558",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We were having a problem with arakkoa bandits raiding many of our supply caravans, so I hired some dwarves to take care of them.$B$BThey were brothers; Gremni Longbeard was the oldest.$B$BI'm a little worried about them.  Those crazy dwarves packed more ale than food or ammunition!  Maybe you can go check up on them?$B$BThe arakkoa's hideout, the Den of Haal'esh, can be found to the far west of here - beyond the Great Fissure.  They set up camp northwest of there, south of Dustquill Ravine.",logDesc="Look for Gremni Longbeard northwest of the Den of Haal'esh, to the far west of Honor Hold in Hellfire Peninsula."} end
if not DB[9559] then DB[9559]={id=9559,zoneId=3524,name="Stillpine Hold",level=10,minLevel=7,giver="Arugoo of the Stillpine",giverType="NPC",giverId=17114,ender="High Chief Stillpine",enderType="NPC",enderId=17440,poiX=-4181,poiY=-12510,wowhead="https://www.wowhead.com/wotlk/quest=9559",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Promised one, you must travel north to the home of my people - Stillpine Hold. It is there that you will face your most daunting challenge.$B$BGo now, High Chief Stillpine awaits your arrival.",logDesc="Speak with High Chief Stillpine at Stillpine Hold."} end
if not DB[9560] then DB[9560]={id=9560,zoneId=3524,name="Beasts of the Apocalypse!",level=10,minLevel=7,giver="Moordo",giverType="NPC",giverId=17442,ender="Moordo",enderType="NPC",enderId=17442,poiX=-3443,poiY=-12322,wowhead="https://www.wowhead.com/wotlk/quest=9560",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My brother and I were hunting in the woods to the east when we were ambushed by strange, insect-like beasts. Such aberrations have never before been seen in Azuremyst! Could they be a sign of the coming apocalypse? The apocalypse that YOU are destined to prevent?$B$BIf you truly are the Promised One, you will strike the creatures of the apocalypse down... and bring me their hides. From their hides, I can fashion armor of great power!$B$BFind them to the east, beyond the road.",logDesc="Moordo at Stillpine Hold on Azuremyst Isle wants you to bring him 8 Ravager Hides. ",choiceRewards={{id=24108,qty=1},{id=24107,qty=1},{id=24109,qty=1}}} end
if not DB[9561] then DB[9561]={id=9561,zoneId=3525,name="Nolkai's Words",level=16,minLevel=13,giver="Anchorite Paetheus",giverType="NPC",giverId=17424,poiX=-1932,poiY=-11858,wowhead="https://www.wowhead.com/wotlk/quest=9561",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The translation is ready now, $N.$B$B<Anchorite Paetheus points out a block of text at the end of his translation.>$B$B'The enemy is nearly upon us. We've gathered up all the survivors and retreated to the temple to the east. It's the last ground we truly hold on the island, and there is a sense among the survivors that we will make our last stand here. I've taken care to bury my last few possessions on the grounds of the temple, with the hope that someone will find them and know what happened here.'",logDesc="Find the location described in Nolkai's journal and discover his long-buried possessions.",rewards={{id=23846,qty=1}}} end
if not DB[9562] then DB[9562]={id=9562,zoneId=3524,name="Murlocs... Why Here? Why Now?",level=10,minLevel=7,giver="Gurf",giverType="NPC",giverId=17441,ender="Gurf",enderType="NPC",enderId=17441,poiX=-3431,poiY=-12316,wowhead="https://www.wowhead.com/wotlk/quest=9562",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="These are dark days, Promised One. Even the murlocs are kicking our tails - literally. Unfortunately, more than just my ego has been bruised.$B$BWhile our relationship with the Siltfin murlocs had always been tenuous, never could we have imagined that they would have the gall to attack us and steal from our food stores! Travel west to the Silting Shore and recover our stolen food-stuffs!$B$BAnd if you see a dark-skinned murloc with a patch of white fur stuck in between his webbed toes... ",logDesc="Gurf at Stillpine Hold on Azuremyst Isle wants you to recover 5 sacks of Stillpine Grain."} end
if not DB[9563] then DB[9563]={id=9563,zoneId=3483,name="Gaining Mirren's Trust",level=62,minLevel=60,giver="Mirren Longbeard",giverType="NPC",giverId=16851,ender="Mirren Longbeard",enderType="NPC",enderId=16851,rewardNextId=9420,poiX=-1010,poiY=4301,wowhead="https://www.wowhead.com/wotlk/quest=9563",image="assets/images/quests/placeholder.png",xpDiff=5,desc="So you want to gain our trust?  I don't trust many people these days.$B$BWe lost one of our own not long ago to the arakkoa.  It's got me a bit on edge.$B$BTell you what, if you can prove your loyalty to Honor Hold and... bring me a mug of Nethergarde Bitter... yes, that sounds rather good about now... I'll have a deal to offer you then.$B$BBernie at Nethergarde Keep keeps the bitter in stock.",logDesc="Mirren Longbeard wants you to bring him 1 Nethergarde Bitter.  You must also attain Friendly reputation with Honor Hold to complete this quest."} end
if not DB[9564] then DB[9564]={id=9564,zoneId=3524,name="Gurf's Dignity",level=11,minLevel=7,ender="Gurf",enderType="NPC",enderId=17441,wowhead="https://www.wowhead.com/wotlk/quest=9564",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You recover the piece of fur that Gurf had \"lost\" in his struggle with the murlocs. Return the fur to Gurf and let him know that the fearsome Murgurgula has been slain.",logDesc="Return Gurf's Dignity to Gurf at Stillpine Hold on Azuremyst Isle.",choiceRewards={{id=24440,qty=1},{id=24439,qty=1},{id=24438,qty=1}}} end
if not DB[9565] then DB[9565]={id=9565,zoneId=3524,name="Search Stillpine Hold",level=10,minLevel=7,giver="High Chief Stillpine",giverType="NPC",giverId=17440,rewardNextId=9566,poiX=-3353,poiY=-12400,wowhead="https://www.wowhead.com/wotlk/quest=9565",image="assets/images/quests/placeholder.png",xpDiff=4,desc="As High Chief, my immediate concern is the root of the corruption in Stillpine Hold.$B$BWhy did the wildkin - once our allies - attack us? Why have they taken residence in Stillpine Hold?$B$BPerhaps something inside will hold the answer. Search Stillpine Hold for clues as to the source of corruption.",logDesc="Search Stillpine Hold for clues."} end
if not DB[9566] then DB[9566]={id=9566,zoneId=3524,name="Blood Crystals",level=10,minLevel=7,ender="High Chief Stillpine",enderType="NPC",enderId=17440,wowhead="https://www.wowhead.com/wotlk/quest=9566",image="assets/images/quests/placeholder.png",xpDiff=4,desc="On the surface, the crystal appears to be a piece of the Exodar. Something has gone terribly wrong with this crystal, however, as it is blood red and rapidly dissolving into the water supply of the cave.$B$BThis may explain the unusually aggressive behavior of the creatures in Azuremyst. Return to High Chief Stillpine with this information.$B",logDesc="Speak with High Chief Stillpine at Stillpine Hold."} end
if not DB[9567] then DB[9567]={id=9567,zoneId=3525,name="Know Thine Enemy",level=14,minLevel=13,giver="Vindicator Aalesia",giverType="NPC",giverId=17433,ender="Vindicator Aalesia",enderType="NPC",enderId=17433,poiX=-2020,poiY=-11872,wowhead="https://www.wowhead.com/wotlk/quest=9567",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="It's good to see another new face here in Blood Watch, $c. Although the blood elves are the most immediate threat, there are other sinister creatures that call Bloodmyst Isle home.$B$BThe Nazzivus satyr are of particular concern. They are foul, demonic creatures, commanding dark magics and feeding on the corruption created by the Exodar's crash.$B$BWe must hold them in check, but first we must learn more about them. Go southwest to Nazzivian and learn what you can from their grotesque monument.",logDesc="Find the Nazzivus Monument in Nazzivian and retrieve a Nazzivus Monument Glyph. Return to Vindicator Aalesia in Blood Watch when you have one of the glyphs."} end
if not DB[9568] then DB[9568]={id=9568,zoneId=3525,name="On the Offensive",level=15,minLevel=13,rewardNextId=9569,wowhead="https://www.wowhead.com/wotlk/quest=9568",image="assets/images/quests/placeholder.png",xpDiff=5,money=700,desc="It's worse than I had imagined, $N. We draenei know well what comes of selling one's soul to the Burning Legion in return for promises of power and immortality.$B$BThe satyr on this island, the Nazzivus, are descendents of that first, twisted creature who allied with the Legion. I fear that they will find a way to use the power of the Exodar's crystals against us.$B$BYou've seen what they've done to the land. Imagine what the satyr could do with them. Go southwest to Nazzivian and begin our offensive!",logDesc="Vindicator Aalesia at Blood Watch wants you to kill 10 Nazzivus Satyr, 5 Nazzivus Rogues, and 5 Nazzivus Felsworn."} end
if not DB[9569] then DB[9569]={id=9569,zoneId=3525,name="Containing the Threat",level=18,minLevel=13,giver="Vindicator Aalesia",giverType="NPC",giverId=17433,ender="Vindicator Aalesia",enderType="NPC",enderId=17433,poiX=-2020,poiY=-11872,wowhead="https://www.wowhead.com/wotlk/quest=9569",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="Now that we have made our presence known to the satyr, we must send a message that we will not tolerate the Burning Legion's hounds in these lands.$B$BToo long have the draenei fled in the wake of the Legion and its minions, $N. Wherever they have found us, they have shown no mercy.$B$BWe must not permit the satyr to exploit the Exodar's crash and use the corrupted crystals as weapons. Go north to where their leader resides in Axxarien, destroy him, and recover the corrupted crystals he has been gathering!",logDesc="Kill 5 Axxarien Shadowstalkers, 5 Axxarien Hellcallers, and Zevrax, then gather 5 Corrupted Crystals and return to Vindicator Aalesia in Blood Watch.",choiceRewards={{id=27402,qty=1},{id=27404,qty=1}}} end
if not DB[9570] then DB[9570]={id=9570,zoneId=3524,name="The Kurken is Lurkin'",level=12,minLevel=7,giver="Kurz the Revelator",giverType="NPC",giverId=17443,ender="Kurz the Revelator",enderType="NPC",enderId=17443,rewardNextId=9571,poiX=-3398,poiY=-12412,wowhead="https://www.wowhead.com/wotlk/quest=9570",image="assets/images/quests/placeholder.png",xpDiff=6,desc="After the crystal storm had subsided, a beast of myth appeared in our village. Brought here by the invading wildkin, this beast, the Kurken, laid waste to our village. Many Stillpine were slain in defense of our lands by this fiend and many have since lost their lives attempting to subdue the beast.$B$BIn my visions, I have seen one defeat the Kurken. The one must be you, $N. You are our only hope. Enter Stillpine Hold and slay the Kurken. Bring me his hide as proof of deed.$B",logDesc="Kurz the Revelator at Stillpine Hold on Azuremyst Isle wants you to kill the Kurken and bring back the Kurken's Hide."} end
if not DB[9571] then DB[9571]={id=9571,zoneId=3524,name="The Kurken's Hide",level=10,minLevel=7,giver="Kurz the Revelator",giverType="NPC",giverId=17443,ender="Moordo",enderType="NPC",enderId=17442,poiX=-3398,poiY=-12412,wowhead="https://www.wowhead.com/wotlk/quest=9571",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Take the Kurken's hide to Moordo, on the other side of the village. He will fashion the hide into an item of your choice.$B",logDesc="Deliver the Kurken's Hide to Moordo at Stillpine Hold.",choiceRewards={{id=24112,qty=1},{id=24111,qty=1}}} end
if not DB[9572] then DB[9572]={id=9572,zoneId=3535,name="Weaken the Ramparts",level=62,minLevel=59,giver="Stone Guard Stok'ton",giverType="NPC",giverId=17493,ender="Caza'rez",enderType="NPC",enderId=17558,rewardNextId=9608,poiX=241,poiY=2689,wowhead="https://www.wowhead.com/wotlk/quest=9572",image="assets/images/quests/placeholder.png",xpDiff=8,money=54000,desc="Quick, there isn't much time.  Thrallmar's existence balances on the razor's edge!$B$BWe're caught between Hellfire Citadel in the west and the Burning Legion to the east.  With the Legion's attention turned toward the Dark Portal we must take this opportunity to strike at the fel orcs of Hellfire Citadel.  The key to this is to first break through their ramparts!$B$BGo there, slay their leaders, and then bring back proof to Caza'rez across the room from me!",logDesc="Slay Watchkeeper Gargolmar, Omor the Unscarred and the drake, Nazan.  Return Gargolmar's Hand, Omor's Hoof and Nazan's Head to Caza'rez at Thrallmar in Hellfire Peninsula.",choiceRewards={{id=25716,qty=1},{id=25715,qty=1},{id=25718,qty=1},{id=25717,qty=1}}} end
if not DB[9573] then DB[9573]={id=9573,zoneId=3524,name="Chieftain Oomooroo",level=11,minLevel=7,giver="Stillpine the Younger",giverType="NPC",giverId=17445,ender="Stillpine the Younger",enderType="NPC",enderId=17445,poiX=-3368,poiY=-12409,wowhead="https://www.wowhead.com/wotlk/quest=9573",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I am Stillpine the Younger, heir to the Stillpine legacy. As you can see, my defenders have set up a death trap for the raving wildkin that attack from inside Stillpine Hold. While we are able to hold them off out here, none of my defenders have been able to infiltrate the hold. If you could get inside and slay their leader, it might give us an opportunity to strike!$B$BFind Chieftain Oomooroo and destroy him. Slay any crazed wildkin that you encounter inside as well.",logDesc="Stillpine the Younger at Stillpine Hold on Azuremyst Isle wants you to slay Chieftain Oomooroo and 9 Crazed Wildkin.$B",choiceRewards={{id=24446,qty=1},{id=24445,qty=1}}} end
if not DB[9574] then DB[9574]={id=9574,zoneId=3525,name="Victims of Corruption",level=14,minLevel=10,giver="Morae",giverType="NPC",giverId=17434,ender="Morae",enderType="NPC",enderId=17434,poiX=-2014,poiY=-11812,wowhead="https://www.wowhead.com/wotlk/quest=9574",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="Bloodmyst Isle was forever changed by our arrival. The Exodar's crash scattered debris all over the islands and I think it's beginning to have an adverse effect on the wildlife.$B$BBefore I can be certain of my conclusion, I'll need to get a closer look. The crystals seem to have affected the trees the fastest, so it seems that the treants would be the most likely to show symptoms. If you bring me samples of bark from corrupted treants, I can begin my in-depth studies.",logDesc="Bring 6 pieces of Crystallized Bark to Morae in Blood Watch."} end
if not DB[9575] then DB[9575]={id=9575,zoneId=3535,name="Weaken the Ramparts",level=62,minLevel=59,giver="Lieutenant Chadwick",giverType="NPC",giverId=17557,ender="Gunny",enderType="NPC",enderId=17479,rewardNextId=9607,poiX=-803,poiY=2610,wowhead="https://www.wowhead.com/wotlk/quest=9575",image="assets/images/quests/placeholder.png",xpDiff=8,money=54000,desc="Quick, $c, there isn't much time.  Honor Hold's existence balances on the razor's edge!$B$BWe're caught between Hellfire Citadel in the west and the forces of the Burning Legion to the east.  With the Legion's attention turned toward the Dark Portal we must take this opportunity to strike at the fel orcs of Hellfire Citadel.  The key to this is to first break through their ramparts!$B$BGo there, slay their leaders, and then bring back proof to Gunny across the hall here from me!",logDesc="Slay Watchkeeper Gargolmar, Omor the Unscarred and the drake, Nazan.  Return Gargolmar's Hand, Omor's Hoof and Nazan's Head to Gunny at Honor Hold in Hellfire Peninsula.",choiceRewards={{id=25716,qty=1},{id=25715,qty=1},{id=25718,qty=1},{id=25717,qty=1}}} end
if not DB[9576] then DB[9576]={id=9576,zoneId=3525,name="Cruelfin's Necklace",level=12,minLevel=9,ender="Morae",enderType="NPC",enderId=17434,wowhead="https://www.wowhead.com/wotlk/quest=9576",image="assets/images/quests/placeholder.png",xpDiff=5,money=500,desc="Examining the crudely constructed pendant, you notice the crystal pulsating softly. Though it emits little light, you can almost feel the crystal radiating a sense of wrongness.$B$BYou're not quite sure what might have possessed Cruelfin to create this pendant, but the find is too important to ignore. You should probably show it to someone at Blood Watch.",logDesc="Bring the Red Crystal Pendant to Morae at Blood Watch."} end
if not DB[9577] then DB[9577]={id=9577,zoneId=0,name="DAILY TEST QUEST (PVP)",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9577",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<NYI>Seek <QUESTGIVER> in <LOCATION>.  S/he wishes for you to aid them in a difficult task.",logDesc="Speak with <QUESTGIVER> in the <AREA>."} end
if not DB[9578] then DB[9578]={id=9578,zoneId=3525,name="Searching for Galaen",level=18,minLevel=15,giver="Morae",giverType="NPC",giverId=17434,ender="Galaen's Corpse",enderType="NPC",enderId=17508,rewardNextId=9579,poiX=-2014,poiY=-11812,wowhead="https://www.wowhead.com/wotlk/quest=9578",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Do you think often of your family, $N? There were a number of families aboard the Exodar, but I've heard of very few being reunited.$B$BI, myself, am looking for traces of my husband Galaen, who was a technician in the Cryo-Core. The wreckage of it is located to the west, and it's swarming with blood elves!$B$BI must find out what became of Galaen! Even news of his death is better than never knowing. My husband will be wearing a pendant identical to my own; they were a gift from my sister.",logDesc="Search for Morae's husband Galaen."} end
if not DB[9579] then DB[9579]={id=9579,zoneId=3525,name="Galaen's Fate",level=18,minLevel=15,giver="Galaen's Corpse",giverType="NPC",giverId=17508,ender="Morae",enderType="NPC",enderId=17434,poiX=-2090,poiY=-11298,wowhead="https://www.wowhead.com/wotlk/quest=9579",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="You have no means of identifying the corpse as Galaen with the information Morae gave you, but the clothing appears to have been torn in search of valuables.$B$BThe blood elves in the area would've claimed anything of value from the wreckage, including Galaen's jeweled amulet.$B$BAlthough her husband did not survive the crash, you believe that Morae would be grateful if you recovered her husband's amulet from the blood elves.",logDesc="Bring Galaen's Amulet to Morae at Blood Watch.",choiceRewards={{id=26011,qty=1},{id=26037,qty=1},{id=26025,qty=1}}} end
if not DB[9580] then DB[9580]={id=9580,zoneId=3525,name="The Bear Necessities",level=16,minLevel=14,giver="Tracker Lyceon",giverType="NPC",giverId=17642,ender="Tracker Lyceon",enderType="NPC",enderId=17642,poiX=-1998,poiY=-11897,wowhead="https://www.wowhead.com/wotlk/quest=9580",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="As I'm sure you've seen in your time on Bloodmyst Isle, very little remains unchanged by our arrival. My training and experience has taught me that even the products of an environment like this one can be put to use.$B$BWith so few resources, we must rely on our ingenuity to provide for us. I've been supplementing our stores with meat from the bears that wander this island. With the proper preparation, it can safely be eaten. If you're going to be out in the field, why not help replenish our stocks?",logDesc="Bring 8 Elder Brown Bear Flanks to Tracker Lyceon in Blood Watch."} end
if not DB[9581] then DB[9581]={id=9581,zoneId=3525,name="Learning from the Crystals",level=11,minLevel=10,giver="Harbinger Mikolaas",giverType="NPC",giverId=17423,ender="Harbinger Mikolaas",enderType="NPC",enderId=17423,rewardNextId=9620,poiX=-1916,poiY=-11791,wowhead="https://www.wowhead.com/wotlk/quest=9581",image="assets/images/quests/placeholder.png",xpDiff=5,money=400,desc="Welcome to Blood Watch, $c. Seeing to the defenses of the outpost is my primary concern, but I've also been tasked with a variety of other duties by our leaders at the Exodar.$B$BThe problem is that it's hardly safe to send out large amounts of researchers when the island is this dangerous. I need someone to gather a series of crystal samples from various sites on the island.$B$BThe first sample I need must come from the ravager infested ship debris south of the town and across the bridge.",logDesc="Get an Impact Site Crystal Sample using the Crystal Mining Pick on the Impact Site Crystal and bring it to Harbinger Mikolaas in Blood Watch.",choiceRewards={{id=26006,qty=1},{id=26032,qty=1},{id=26020,qty=1}}} end
if not DB[9582] then DB[9582]={id=9582,zoneId=-81,name="Strength of One",level=10,minLevel=10,giver="Ruada",giverType="NPC",giverId=17480,ender="Ruada",enderType="NPC",enderId=17480,rewardNextId=10350,poiX=-4165,poiY=-12536,wowhead="https://www.wowhead.com/wotlk/quest=9582",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When the ship crashed, our menagerie was scattered on the northeast beaches of this isle.  I have been handed a key that unlocks the cage holding one of the deadlier specimens, a death ravager.  The creature is little armored but resistant to most magic.  It must be killed by a simple blade.$b$bTake this key and release the creature from both its prison and its pain.  We cannot afford to have it escape and cause even more damage to the ecology than we already have.",logDesc="Unlock the Ravager Cage and kill the Death Ravager, then return to Ruada at Azure Watch in Azuremyst."} end
if not DB[9583] then DB[9583]={id=9583,zoneId=22,name="Omar's Test Quest",level=70,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=9583",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="An honorable person gives me cloth",logDesc="Get Omar some cloth",rewards={{id=29434,qty=2}},choiceRewards={{id=23425,qty=1},{id=23424,qty=1},{id=23426,qty=1}}} end
if not DB[9584] then DB[9584]={id=9584,zoneId=3525,name="The Second Sample",level=14,minLevel=10,giver="Harbinger Mikolaas",giverType="NPC",giverId=17423,ender="Harbinger Mikolaas",enderType="NPC",enderId=17423,rewardNextId=9585,poiX=-1916,poiY=-11791,wowhead="https://www.wowhead.com/wotlk/quest=9584",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="Now that we have the baseline crystal, we're going to need samples from more dangerous areas of the island to complete the set I'll be sending to the Exodar.$B$BThe next sample must come from the crystals controlled by the blood elves in the Bladewood area to the northwest of Blood Watch. I have heard reports that they alter and harvest the crystals for use in some magical apparatus. See if you can find one that has not yet been incorporated into one of their devices, and mine a sample from it.",logDesc="Get an Altered Crystal Sample using the Crystal Mining Pick on the Altered Bloodmyst Crystal and bring it to Harbinger Mikolaas in Blood Watch."} end
if not DB[9585] then DB[9585]={id=9585,zoneId=3525,name="The Final Sample",level=18,minLevel=10,giver="Harbinger Mikolaas",giverType="NPC",giverId=17423,ender="Harbinger Mikolaas",enderType="NPC",enderId=17423,poiX=-1916,poiY=-11791,wowhead="https://www.wowhead.com/wotlk/quest=9585",image="assets/images/quests/placeholder.png",xpDiff=5,money=1000,desc="There's just one sample remaining before I can send this set of crystals to the Exodar, $n. The final sample must come from the satyr stronghold of Axxarien to the northwest.$B$BI'm not certain what to expect from this crystal sample, but I'm sure there will be some signs of corruption. Take care to mine your shard from the crystal that looks like the ones you took your previous samples from, or else our researchers cannot make a valid comparison.",logDesc="Get an Axxarian Crystal Sample using the Crystal Mining Pick on the Axxarien Crystal and bring it to Harbinger Mikolaas in Blood Watch."} end
if not DB[9586] then DB[9586]={id=9586,zoneId=-262,name="Help Tavara",level=5,minLevel=5,giver="Guvan",giverType="NPC",giverId=17482,ender="Guvan",enderType="NPC",enderId=17482,poiX=-4132,poiY=-12479,wowhead="https://www.wowhead.com/wotlk/quest=9586",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Tavara, one of our herbalists, has been gone far too long in her search for herbs.  I fear she is hurt and in need of help, yet I cannot look for her myself.$b$bPlease find her and lend your healing if needed, fellow $c.  She was heading east towards some hot springs when she left Azure Watch.",logDesc="Guvan at Azure Watch wants you to find Tavara and heal her wounds.",rewards={{id=23931,qty=1}}} end
if not DB[9587] then DB[9587]={id=9587,zoneId=3483,name="Dark Tidings",level=62,minLevel=59,ender="Force Commander Danath Trollbane",enderType="NPC",enderId=16819,wowhead="https://www.wowhead.com/wotlk/quest=9587",image="assets/images/quests/placeholder.png",xpDiff=8,money=27000,desc="Giving the lifeless form of Vazruden the Herald the once-over, you discover a rolled letter, its seal yet unbroken.  An elaborate \"I\" is pressed within the blood-red ink.  Cracking the note open, the message that you read is most disturbing.$B$BForce Commander Danath Trollbane back at Honor Hold will definitely want to take a look at this!",logDesc="Take the Ominous Letter to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula."} end
if not DB[9588] then DB[9588]={id=9588,zoneId=3483,name="Dark Tidings",level=62,minLevel=59,ender="Nazgrel",enderType="NPC",enderId=3230,wowhead="https://www.wowhead.com/wotlk/quest=9588",image="assets/images/quests/placeholder.png",xpDiff=8,money=27000,desc="Giving the lifeless form of Vazruden the Herald the once-over, you discover a rolled letter, its seal yet unbroken.  An elaborate \"I\" is pressed within the blood-red ink.  Cracking the note open, the message that you read is most disturbing.$B$BNazgrel back in Thrallmar will definitely want to take a look at this!",logDesc="Take the Ominous Letter to Nazgrel at Thrallmar in Hellfire Peninsula."} end
if not DB[9589] then DB[9589]={id=9589,zoneId=3535,name="The Blood is Life",level=63,minLevel=59,giver="Gunny",giverType="NPC",giverId=17479,ender="Gunny",enderType="NPC",enderId=17479,poiX=-814,poiY=2627,wowhead="https://www.wowhead.com/wotlk/quest=9589",image="assets/images/quests/placeholder.png",xpDiff=8,money=58000,desc="That letter is going to get folks all riled up around here.  They'll think there's something we might do about all those new fel orcs being created if only we knew how it was being done.  It's bad enough that we have to fight the Burning Legion to the east.$B$BSo, it's your lucky day, sweetness!  You get to take a stroll into what they call the Blood Furnace inside Hellfire Citadel.  Sounds hot!$B$BGet in there, kill some fel orcs and bring back samples of their blood.$B$BYou think you can handle that?",logDesc="Collect 10 Fel Orc Blood Vials and return them to Gunny at Honor Hold in Hellfire Peninsula.",choiceRewards={{id=25701,qty=1},{id=25711,qty=1},{id=25710,qty=1},{id=25702,qty=1}}} end
if not DB[9590] then DB[9590]={id=9590,zoneId=3535,name="The Blood is Life",level=63,minLevel=59,giver="Caza'rez",giverType="NPC",giverId=17558,ender="Caza'rez",enderType="NPC",enderId=17558,poiX=241,poiY=2705,wowhead="https://www.wowhead.com/wotlk/quest=9590",image="assets/images/quests/placeholder.png",xpDiff=8,money=58000,desc="That letter is disturbing, and not just because it comes from the Betrayer.  We must know how they are creating these new fel orcs if we're to defeat them!  It's bad enough that we must fight the Burning Legion on our eastern flank, but now a new army of fel orcs to the west!$B$BYou must infiltrate this Blood Furnace inside Hellfire Citadel.  Bring back samples of blood from the fel orcs that you find in there.",logDesc="Collect 10 Fel Orc Blood Vials and return them to Centurion Caza'rez at Thrallmar in Hellfire Peninsula.",choiceRewards={{id=25701,qty=1},{id=25711,qty=1},{id=25710,qty=1},{id=25702,qty=1}}} end
if not DB[9591] then DB[9591]={id=9591,zoneId=-261,name="Taming the Beast",level=-1,minLevel=10,giver="Huntress Kella Nightbow",giverType="NPC",giverId=17614,ender="Huntress Kella Nightbow",enderType="NPC",enderId=17614,rewardNextId=9592,poiX=-4269,poiY=-11484,wowhead="https://www.wowhead.com/wotlk/quest=9591",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When the $c first begins $ghis:her; path, $ghe:she; learns only to kill.  Now it seems you are ready for more.$b$bThe Stillpine furbolgs have provided a means to master the skill of taming without months of study.  They are able to carve a totem into the likeness of an animal, which you can use to temporarily bond with a creature of that type.$b$bFor your first lesson, take this totem and use it on the barbed crawlers found along the western coast of the isle.",logDesc="Use the Taming Totem to befriend a Barbed Crawler and return to Huntress Kella Nightbow when you have succeeded."} end
if not DB[9592] then DB[9592]={id=9592,zoneId=-261,name="Taming the Beast",level=-1,minLevel=10,giver="Huntress Kella Nightbow",giverType="NPC",giverId=17614,ender="Huntress Kella Nightbow",enderType="NPC",enderId=17614,rewardNextId=9593,poiX=-4269,poiY=-11484,wowhead="https://www.wowhead.com/wotlk/quest=9592",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The crawler was undoubtedly mean, but the timberstrider will test your resolve.  More powerful allies require more tenacity from the hunter.$b$bTake this taming totem and befriend a greater timberstrider.  They are found in the northern reaches of Azuremyst Isle.",logDesc="Use the Taming Totem to befriend a Greater Timberstrider and return to Huntress Kella Nightbow."} end
if not DB[9593] then DB[9593]={id=9593,zoneId=-261,name="Taming the Beast",level=-1,minLevel=10,giver="Huntress Kella Nightbow",giverType="NPC",giverId=17614,ender="Huntress Kella Nightbow",enderType="NPC",enderId=17614,rewardNextId=9675,poiX=-4269,poiY=-11484,wowhead="https://www.wowhead.com/wotlk/quest=9593",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You probably noticed the big cats known as nightstalkers when you tamed the timberstrider.  They are efficient and deadly hunters... and allies.$b$bUse this taming totem to befriend a nightstalker.  Hunt with the vicious cat and keep it from harm.  When you are finished, return to me.",logDesc="Use the Taming Totem to befriend a Nightstalker and return to Huntress Kella Nightbow."} end
if not DB[9594] then DB[9594]={id=9594,zoneId=3525,name="Signs of the Legion",level=14,minLevel=10,ender="Vindicator Aalesia",enderType="NPC",enderId=17433,wowhead="https://www.wowhead.com/wotlk/quest=9594",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="The armor scrap is forged from a deep black metal that seems to absorb light. Although it doesn't appear to be enchanted, there is an unmistakable sense of wrongness about it.$B$BSuch armor is only used by one force - the Burning Legion. The Legion's presence here can only mean that they're intending to mobilize the island's satyr against the draenei.$B$BTake action against the local satyr, then return to Blood Watch and show this armor scrap to Vindicator Aalesia. ",logDesc="Kill 8 Nazzivus Satyr and 8 Nazzivus Felsworn, then bring Tzerak's Armor Plate to Vindicator Aalesia in Blood Watch."} end
if not DB[9595] then DB[9595]={id=9595,zoneId=-161,name="Control",level=11,minLevel=10,giver="Semid",giverType="NPC",giverId=17481,ender="Bati",enderType="NPC",enderId=17514,poiX=-4150,poiY=-12530,wowhead="https://www.wowhead.com/wotlk/quest=9595",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have chosen the path of the $c, and so you must learn control. Magic, when unchecked, can corrupt souls and destroy worlds.$b$bTo fully understand, you must face one who has been consumed by magic. Travel to the beaches on the northwest coast of Azuremyst Isle and use your spells to decimate the murlocs. The display of power will attract the attention of the evil force lurking there, a Quel'dorei magewraith. Defeat it.$b$bWhen you have finished, seek out Bati at the Vault of Lights in the Exodar.",logDesc="Kill Murlocs of the Silting Shore to summon a Quel'dorei Magewraith, then destroy it. Afterwards, speak with Bati at the Vault of Lights in the Exodar.",choiceRewards={{id=9513,qty=1},{id=7508,qty=1}}} end
if not DB[9596] then DB[9596]={id=9596,zoneId=-161,name="<DEPRECATED>Control",level=10,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=9596",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="<NYI>Do something else,$c!",logDesc="<NYI>Log description.",choiceRewards={{id=9513,qty=1},{id=7508,qty=1}}} end
if not DB[9597] then DB[9597]={id=9597,zoneId=-141,name="<UNUSED>",level=12,minLevel=12,wowhead="https://www.wowhead.com/wotlk/quest=9597",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<NYI>Hey little man,do something worthy and talk to Jonathan LeCraft.",logDesc="<NYI>Log description."} end
if not DB[9598] then DB[9598]={id=9598,zoneId=-141,name="Redemption",level=-1,minLevel=12,giver="Jol",giverType="NPC",giverId=17509,ender="Jol",enderType="NPC",enderId=17509,rewardNextId=9600,poiX=-4192,poiY=-11472,wowhead="https://www.wowhead.com/wotlk/quest=9598",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend our people from threats.$B$BThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a tome of divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.",logDesc="Study the Tome of Divinity and speak with Jol."} end
if not DB[9599] then DB[9599]={id=9599,zoneId=-141,name="<UNUSED>",level=12,minLevel=12,rewardNextId=9600,wowhead="https://www.wowhead.com/wotlk/quest=9599",image="assets/images/quests/placeholder.png",xpDiff=5,desc="In all things, paladins must reflect the Light, which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.$B$BAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the other citizens. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.$B$BKnow this well, and never forget it.",logDesc="Speak with Jol in the Exodar."} end
if not DB[9600] then DB[9600]={id=9600,zoneId=-141,name="Redemption",level=-1,minLevel=12,giver="Jol",giverType="NPC",giverId=17509,ender="Jol",enderType="NPC",enderId=17509,poiX=-4192,poiY=-11472,wowhead="https://www.wowhead.com/wotlk/quest=9600",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Your task then, $N, is to aid our new allies, the Stillpine furbolgs.$b$bSeveral of the younger Stillpine shaman stumbled across a Bristlelimb camp and were slaughtered to the last.  Take this Symbol of Life and resurrect one of the shaman.$b$bBristlelimb Enclave is located to the east of the road just after you cross the bridge spanning Azuremyst and Bloodmyst Isle.  Speak with me when you have done this.$B",logDesc="Jol wants you to resurrect a Young Furbolg Shaman with the Symbol of Life and return to her."} end
if not DB[9601] then DB[9601]={id=9601,zoneId=-141,name="To The Bulwark",level=52,minLevel=50,giver="Champion Bachi",giverType="NPC",giverId=16681,ender="Mehlar Dawnblade",enderType="NPC",enderId=17099,rewardNextId=10590,poiX=9851,poiY=-7518,wowhead="https://www.wowhead.com/wotlk/quest=9601",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The blood knight Mehlar Dawnblade has requested an audience with you, $n.  Mehlar can be found at the Bulwark, guarding the passage between Tirisfal Glades and the Western Plaguelands.$b$bHe is not known for his patience.  It would not be wise to keep him waiting.",logDesc="Speak with Mehlar Dawnblade at the Bulwark."} end
if not DB[9602] then DB[9602]={id=9602,zoneId=3524,name="Deliver Them From Evil...",level=9,minLevel=5,giver="Admiral Odesyus",giverType="NPC",giverId=17240,ender="Exarch Menelaous",enderType="NPC",enderId=17116,poiX=-4700,poiY=-12415,wowhead="https://www.wowhead.com/wotlk/quest=9602",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You must get this information to your people, $N. While your brave acts have certainly slowed down the plans of Kael'thas and his dark master, the attacks will undoubtedly continue.$B$BTake the traitor's communication to your leaders. They must see this for themselves. Perhaps they will be able to better understand some of what was written.",logDesc="Deliver the Traitor's Communication to Exarch Menelaous at Azure Watch."} end
if not DB[9603] then DB[9603]={id=9603,zoneId=3525,name="Beds, Bandages, and Beyond",level=10,minLevel=10,giver="Caregiver Topher Loaal",giverType="NPC",giverId=17553,ender="Laando",enderType="NPC",enderId=17554,rewardNextId=9604,poiX=-2059,poiY=-11897,wowhead="https://www.wowhead.com/wotlk/quest=9603",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Welcome to Blood Watch, $c. Please excuse the disorder you see around you. It's easy to take simple things for granted, like a fully furnished and stocked inn, until you're forced to build one from nothing.$B$BWe've managed to salvage this pod for a building, but without the proper furnishings and first aid supplies, the inn is little more than a glorified tent. Nurguni at the Exodar has offered to put together a package to help with our most immediate needs, but I need someone to deliver this list to him.",logDesc="Take Topher's List to Laando, the Hippogryph Master at Blood Watch."} end
if not DB[9604] then DB[9604]={id=9604,zoneId=3525,name="On the Wings of a Hippogryph",level=10,minLevel=10,giver="Laando",giverType="NPC",giverId=17554,ender="Nurguni",enderType="NPC",enderId=16768,rewardNextId=9605,poiX=-1930,poiY=-11957,wowhead="https://www.wowhead.com/wotlk/quest=9604",image="assets/images/quests/placeholder.png",xpDiff=3,desc="For a small fee, you can rent one of my hippogryphs to fly you to the Exodar.$B$BTaking the hippogryph is a faster, not to mention safer, alternative for someone carrying an important message. If you'd like to take a ride, speak to me again and I'll make the arrangements.",logDesc="Purchase a hippogryph ride to the Exodar from Laando. When you land, take Topher's List to Nurguni in the Seat of the Naaru at the Exodar."} end
if not DB[9605] then DB[9605]={id=9605,zoneId=3525,name="Hippogryph Master Stephanos",level=10,minLevel=10,giver="Nurguni",giverType="NPC",giverId=16768,ender="Stephanos",enderType="NPC",enderId=17555,rewardNextId=9606,poiX=-3963,poiY=-11669,wowhead="https://www.wowhead.com/wotlk/quest=9605",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Here's the box, $N. That should be enough for Topher to get the inn up and running. Let him know that he can keep sending in orders as the need arises. Blood Watch urgently needs a place to care for the wounded and put up any travelers they receive.$B$BWhen you're ready to return to Blood Watch, seek out Stephanos near the gates of the Exodar.",logDesc="Find Stephanos outside the Exodar and purchase a hippogryph ride back to Blood Watch."} end
if not DB[9606] then DB[9606]={id=9606,zoneId=3525,name="Return to Topher Loaal",level=10,minLevel=10,giver="Stephanos",giverType="NPC",giverId=17555,ender="Caregiver Topher Loaal",enderType="NPC",enderId=17553,poiX=-4057,poiY=-11789,wowhead="https://www.wowhead.com/wotlk/quest=9606",image="assets/images/quests/placeholder.png",xpDiff=5,money=700,desc="If I remember correctly, Blood Watch's hippogryph master is Laando.  If you've spoken to him before, then you can take one of my hippogryphs to him.$B$BThat's a good lesson to know: hippogryphs are always trained to fly to their capital city, but they'll only take you to a remote hippogryph master after you've already been there.$B$BSince you arrived on one of Laando's hippogryphs, you can also use that route to return to Blood Watch with the caregiver's supplies.",logDesc="Speak with Stephanos to purchase a hippogryph ride back to Blood Watch. Once you have arrived, deliver Nurguni's Supplies to Caregiver Topher Loaal."} end
if not DB[9607] then DB[9607]={id=9607,zoneId=3535,name="Heart of Rage",level=63,minLevel=59,giver="Gunny",giverType="NPC",giverId=17479,ender="Force Commander Danath Trollbane",enderType="NPC",enderId=16819,poiX=-814,poiY=2627,wowhead="https://www.wowhead.com/wotlk/quest=9607",image="assets/images/quests/placeholder.png",xpDiff=8,money=58000,desc="$C, put together a force to investigate the Blood Furnace inside Hellfire Citadel at once!  And that means today, princess!$B$BThe magic we have at our disposal indicates that something unnatural is occurring in there.  But something more powerful inside is blocking any detailed arcane investigations.  It figures!$B$BYou can expect heavy resistance - no other mission that we've sent in there has yet to return!$B$BScout it entirely and then report back to the force commander with what you witness.",logDesc="Fully investigate the Blood Furnace and then report to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.",choiceRewards={{id=25714,qty=1},{id=25713,qty=1},{id=25712,qty=1}}} end
if not DB[9608] then DB[9608]={id=9608,zoneId=3535,name="Heart of Rage",level=63,minLevel=59,giver="Caza'rez",giverType="NPC",giverId=17558,ender="Nazgrel",enderType="NPC",enderId=3230,poiX=241,poiY=2705,wowhead="https://www.wowhead.com/wotlk/quest=9608",image="assets/images/quests/placeholder.png",xpDiff=8,money=58000,desc="$C, you must gather a group to investigate the Blood Furnace inside Hellfire Citadel at once!$B$BThe magical scrying that we have at our disposal indicates that something unnatural is occurring in there.  But a powerful force inside is blocking any detailed arcane investigations, so it must be very important.$B$BYou should expect heavy resistance - no other mission that we've sent in there has ever returned!$B$BScout it entirely and then report back to Nazgrel, advisor to Thrall, with what you witness.",logDesc="Fully investigate the Blood Furnace and then report to Nazgrel at Thrallmar in Hellfire Peninsula.",choiceRewards={{id=25714,qty=1},{id=25713,qty=1},{id=25712,qty=1}}} end
if not DB[9609] then DB[9609]={id=9609,zoneId=8,name="Help Watcher Biggs",level=37,minLevel=30,giver="Anchorite Avuun",giverType="NPC",giverId=17127,ender="Watcher Biggs",enderType="NPC",enderId=5476,rewardNextId=1396,poiX=-10107,poiY=-2814,wowhead="https://www.wowhead.com/wotlk/quest=9609",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Magtoor has informed me that there's a stranded watcher nearby.  Apparently the caravan he was escorting from Darkshire was attacked by Lost Ones.  It sounds as if he's the sole survivor.$B$BHe's somewhere to the south.  Please, $c, lend him your aid.",logDesc="Find Watcher Biggs in the Swamp of Sorrows."} end
if not DB[9610] then DB[9610]={id=9610,zoneId=8,name="Pool of Tears",level=43,minLevel=38,giver="Holaaru",giverType="NPC",giverId=18221,ender="Holaaru",enderType="NPC",enderId=18221,poiX=-10117,poiY=-2816,wowhead="https://www.wowhead.com/wotlk/quest=9610",image="assets/images/quests/placeholder.png",xpDiff=6,money=12000,desc="I am interested in studying Azeroth's past and I'm wondering if you'd be willing to help?$B$BThere is a nearby place of historical significance within the swamp that I would like for you to venture to.  The Pool of Tears lies to the southeast.  It is said that upon its shores and within its depths are buried artifacts of the Atal'ai troll civilization.$B$BBut beware, it is guarded by Somnus, an ancient green dragon, and his dragonkin, as well as carnivorous fish in the pool itself!",logDesc="Obtain 5 Atal'ai Artifacts and return them to Holaaru at the Harborage in the Swamp of Sorrows."} end
if not DB[9611] then DB[9611]={id=9611,zoneId=3524,name="Azuremyst: aa - A - Quest Flag 000",level=8,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=9611",image="assets/images/quests/placeholder.png"} end
if not DB[9612] then DB[9612]={id=9612,zoneId=3524,name="A Hearty Thanks!",level=8,minLevel=5,giver="Draenei Youngling",giverType="NPC",giverId=17587,ender="Exarch Menelaous",enderType="NPC",enderId=17116,poiX=-4367,poiY=-12204,wowhead="https://www.wowhead.com/wotlk/quest=9612",image="assets/images/quests/placeholder.png",xpDiff=4,money=450,desc="You saved my life, $N! Thank you so much! That beast would have torn me to shreds if it weren't for you.$B$BIf you see the exarch at Azure Watch, tell him of what you did. I'm sure he'll be pleased to hear such news!",logDesc="Speak with Exarch Menelaous at Azure Watch."} end
if not DB[9613] then DB[9613]={id=9613,zoneId=2562,name="Deprecated: Keanna's Will",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=9613",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<As you touch the sword,you hear a female voice address you>$B$BOuch!  Don't do that!  Can't you see I'm in pieces?  It really hurts.$B$BI see that Karazahan hasn't trapped you.  You must know about Kadghar and the Violet Eye then.$B$BYou're going to need to find someone who can put me back together.  Koren... he was our agent once... he's nearby.  I hope you're on our good side.  If so,he can help!",logDesc="The Shattered Blade you found in Karazhan wants you to ask Koren to repair it.  You'll also need to attain Honored reputation with the Violet Eye to complete this quest."} end
if not DB[9614] then DB[9614]={id=9614,zoneId=2562,name="Deprecated: Reforge a Short Blade",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=9614",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This weapon has been broken into so many pieces... putting it back together won't be easy.$B$BI'm going to need khorium.  Lots of it.  I'll also need a void crystal and some primal fire.",logDesc="Bring 40 Khorium Bars,1 Void Crystal and 8 Primal Fires to Koren inside Karazhan.",rewards={{id=23905,qty=1}}} end
if not DB[9615] then DB[9615]={id=9615,zoneId=2562,name="Deprecated: Reforge a Long Blade",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=9615",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This weapon has been broken into so many pieces... putting it back together won't be easy.$B$BI'm going to need khorium.  Lots of it.  I'll also need a void crystal and some primal fire.",logDesc="Bring 40 Khorium Bars,1 Void Crystal and 8 Primal Fires to Koren inside Karazhan.",rewards={{id=23647,qty=1}}} end
if not DB[9616] then DB[9616]={id=9616,zoneId=3524,name="Bandits!",level=7,minLevel=5,ender="Exarch Menelaous",enderType="NPC",enderId=17116,wowhead="https://www.wowhead.com/wotlk/quest=9616",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This appears to be a bounty ledger. You cannot understand the blood elf language but you note that there is a picture depicting a dead draenei, a smiling blood elf standing over the corpse, and a symbol of what you think is some sort of blood elf currency.$B$BThey've put a hit out on draenei! You must inform the exarch.",logDesc="Take the Blood Elf Communication to Exarch Menelaous at Azure Watch.",choiceRewards={{id=24141,qty=1},{id=24142,qty=1},{id=24144,qty=1}}} end
if not DB[9617] then DB[9617]={id=9617,zoneId=-261,name="Seek the Farstriders",level=-1,minLevel=10,giver="Kary Thunderhorn",giverType="NPC",giverId=3038,ender="Lieutenant Dawnrunner",enderType="NPC",enderId=15399,rewardNextId=9484,poiX=-1465,poiY=-94,wowhead="https://www.wowhead.com/wotlk/quest=9617",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, $N.  She is a beacon of wisdom for those of our calling.$b$bFarstrider Retreat lies south of Silvermoon City.",logDesc="Speak with Lieutenant Dawnrunner at Farstrider Retreat."} end
if not DB[9618] then DB[9618]={id=9618,zoneId=-162,name="Return the Reports",level=10,minLevel=10,giver="Keltus Darkleaf",giverType="NPC",giverId=17224,ender="Zelanis",enderType="NPC",enderId=16684,poiX=8021,poiY=-6372,wowhead="https://www.wowhead.com/wotlk/quest=9618",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Your sleight of hand was most impressive.  There's no question that I can trust you to take these reports to Zelanis.",logDesc="Bring Keltus Darkleaf's Reports to Zelanis in Silvermoon City.",rewards={{id=7298,qty=1}}} end
if not DB[9619] then DB[9619]={id=9619,zoneId=-61,name="The Rune of Summoning",level=-1,minLevel=10,ender="Talionia",enderType="NPC",enderId=16647,wowhead="https://www.wowhead.com/wotlk/quest=9619",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The voidstone reveals a vision of a multi-story building haunted by ghostly figures.  As the scene sharpens and blurs, other buildings come into view, leading you to believe it is Goldenmist Village.$b$bRooftops and tree canopies suddenly flash by, revealing the way to Goldenmist by following the Elrendar River to the west.$b$bOnce there, use the voidstone near the rune of summoning atop the center building and defeat the summoned voidwalker.  Only then can you return to your teacher.",logDesc="Use the Voidstone to summon a Voidwalker in Goldenmist Village, defeat it, and return to Talionia in Silvermoon City."} end
if not DB[9620] then DB[9620]={id=9620,zoneId=3525,name="The Missing Survey Team",level=14,minLevel=10,giver="Harbinger Mikolaas",giverType="NPC",giverId=17423,ender="Draenei Cartographer",enderType="NPC",enderId=17600,rewardNextId=9628,poiX=-1916,poiY=-11791,wowhead="https://www.wowhead.com/wotlk/quest=9620",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As we've gotten ourselves established here at Blood Watch, I've been sending out survey teams to create more reliable maps of the island. In most cases, they returned unharmed with the data we need, but the team I sent east to the ruins hasn't reported back.$B$BI worry about what might have happened to them, but I can't spare the men to send another mission after them. Find them, $N, and lend them any assistance they require to return with their survey data.",logDesc="Harbinger Mikolaas wants you to find the Survey Team he sent to the Ruins of Loreth'Aran and assist them in any way you can."} end
if not DB[9621] then DB[9621]={id=9621,zoneId=1497,name="Envoy to the Horde",level=21,minLevel=15,giver="3",giverType="NPC",giverId=16802,ender="3",enderType="NPC",enderId=10181,rewardNextId=9626,poiX=9991,poiY=-7053,wowhead="https://www.wowhead.com/wotlk/quest=9621",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?$B$BThis changes everything.  No longer will our power be questioned.  We'll be able to join the Horde as equals.$B$BTake this letter to Sylvanas, ruler of the Forsaken.  She's already on our side but the news of Dar'Khan's death will be music to her ears.  Prepare for a long trip, $N.  If all goes well she will send you to Orgrimmar.",logDesc="Bring the Letter from Lor'themar Theron to Lady Sylvanas Windrunner in Undercity, the Forsaken capital in Tirisfal Glades."} end
if not DB[9622] then DB[9622]={id=9622,zoneId=3524,name="Warn Your People",level=11,minLevel=7,giver="High Chief Stillpine",giverType="NPC",giverId=17440,ender="Exarch Menelaous",enderType="NPC",enderId=17116,poiX=-3353,poiY=-12400,wowhead="https://www.wowhead.com/wotlk/quest=9622",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The Hold is saved and soon my people will make their way back to the ancestral home. The prophecy has come to pass and a new age of prosperity begins for the Stillpine.$B$BBut I fear that darkness looms ahead for your own people. There are questions left unanswered - visions of prophecy unseen.$B$BReturn to your leaders and tell them of what you have seen here.$B$BAnd Promised One, should you ever require the aid of Stillpine, you have merely to ask.",logDesc="Speak with Exarch Menelaous at Azure Watch."} end
if not DB[9623] then DB[9623]={id=9623,zoneId=3524,name="Coming of Age",level=11,minLevel=10,giver="Exarch Menelaous",giverType="NPC",giverId=17116,ender="Torallius the Pack Handler",enderType="NPC",enderId=17584,rewardNextId=9625,poiX=-4167,poiY=-12418,wowhead="https://www.wowhead.com/wotlk/quest=9623",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You have survived the wilds of our new home and shown yourself a cut above the others. I believe that you have come of age to assist those battling on the front lines of Bloodmyst. The Hand of Argus could use a $r like you. $B$BReport to Torallius the Pack Handler. You will find him outside the Exodar, tending to the elekk. Give him these orders so that he may direct you towards your new duties on Bloodmyst.",logDesc="Exarch Menelaous at Azure Watch has asked that you deliver the Exarch's Orders to Torallius the Pack Handler, standing outside of the Exodar."} end
if not DB[9624] then DB[9624]={id=9624,zoneId=3525,name="A Favorite Treat",level=12,minLevel=9,giver="Aonar",giverType="NPC",giverId=17599,ender="Aonar",enderType="NPC",enderId=17599,poiX=-2690,poiY=-12144,wowhead="https://www.wowhead.com/wotlk/quest=9624",image="assets/images/quests/placeholder.png",xpDiff=5,money=500,desc="I've made a wonderful discovery, $c. On the uncorrupted part of the island grows a remarkable fruit called the sand pear. They're found near the bottoms of the trees.$B$BI've been preparing pies from them, but if I'm not careful, the elekk will start to wander over and steal my fruit. I've taken to gathering enough to share with the animals, but my stores are gone and the craving for pie has returned. Would you be willing to help gather the fruit I need for another batch of pies? I promise I'll share!",logDesc="Aonar at Kessel's Crossing wants you to bring him 10 Sand Pears.",rewards={{id=24072,qty=20}},choiceRewards={{id=26018,qty=1},{id=26004,qty=1},{id=26031,qty=1}}} end
if not DB[9625] then DB[9625]={id=9625,zoneId=3524,name="Elekks Are Serious Business",level=11,minLevel=10,giver="Torallius the Pack Handler",giverType="NPC",giverId=17584,ender="Vorkhan the Elekk Herder",enderType="NPC",enderId=17586,poiX=-3972,poiY=-11927,wowhead="https://www.wowhead.com/wotlk/quest=9625",image="assets/images/quests/placeholder.png",xpDiff=2,money=100,desc="Is he crazy? Entrusting something like this to some no-named $r youngling!$B$BJust remember this kid: You'll never make it as a Hand of Argus! You don't have the guts!$B$BI guess I'll have to humor him this time. Speak with Vorkhan at Kessel's Crossing on Bloodmyst Isle. Just follow the road north from here, and when it forks, just keep on going north.",logDesc="Speak with Vorkhan the Elekk Herder on Bloodmyst Isle."} end
if not DB[9626] then DB[9626]={id=9626,zoneId=1637,name="Meeting the Warchief",level=21,minLevel=15,giver="3",giverType="NPC",giverId=10181,ender="Thrall",enderType="NPC",enderId=4949,rewardNextId=9627,poiX=1290,poiY=316,wowhead="https://www.wowhead.com/wotlk/quest=9626",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I haven't lost any love for my homeland or its people, as you know.  I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table.$B$BThis should silence any opposition. Take this letter to Thrall in Orgrimmar.  As leader of the Horde he will have the final say on accepting your race's pledge.$B$BI've added my own seal to the letter as a personal endorsement.  Go northwest of the city and board the zeppelin bound for Durotar at the tower.",logDesc="Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to Thrall in Orgrimmar, capital of Durotar."} end
if not DB[9627] then DB[9627]={id=9627,zoneId=3487,name="Allegiance to the Horde",level=21,minLevel=15,giver="Thrall",giverType="NPC",giverId=4949,ender="3",enderType="NPC",enderId=16802,poiX=1920,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=9627",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Your people suffered a great betrayal by the Alliance.  You've succeeded in fending off Darnassian attacks as well as spies from Ironforge.  Now you've defeated a powerful Scourge leader at the footsteps of your home.  Your worthiness is no longer in question.$B$BIt is now apparent that you need us and we need you.  Return to Lor'themar.  Tell him I received his message loud and clear.$B$B<The warchief crushes the letter inside his palm.>$B$BWelcome to the Horde, elf.",logDesc="Return to Silvermoon City and report back to Lor'themar Theron."} end
if not DB[9628] then DB[9628]={id=9628,zoneId=3525,name="Salvaging the Data",level=14,minLevel=10,giver="Draenei Cartographer",giverType="NPC",giverId=17600,ender="Harbinger Mikolaas",enderType="NPC",enderId=17423,rewardNextId=9584,poiX=-1819,poiY=-12071,wowhead="https://www.wowhead.com/wotlk/quest=9628",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="It's too late to assist the cartographers in completing their mission, but it appears they collected the data Harbinger Mikolaas was expecting. The crystal storing their survey information was not among their ransacked packs, so it must be in the hands of the Wrathscale naga.$B$BYou know that Harbinger Mikolaas will be saddened by the loss of the survey crew, but would want to salvage the survey data.",logDesc="Obtain the Survey Data Crystal from the Wrathscale near the dead cartographers and return it to Harbinger Mikolaas at Blood Watch.",rewards={{id=26016,qty=1}}} end
if not DB[9629] then DB[9629]={id=9629,zoneId=3525,name="Catch and Release",level=13,minLevel=10,giver="Morae",giverType="NPC",giverId=17434,ender="Morae",enderType="NPC",enderId=17434,rewardNextId=9574,poiX=-2014,poiY=-11812,wowhead="https://www.wowhead.com/wotlk/quest=9629",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="The Blacksilt murlocs on the southwestern coast are curious creatures. In some ways, they act barely sentient, yet in others, they show a remarkable degree of organization.$B$BI have a few theories about that, but no real way to test them until recently. I've devised a method that will allow me to track the murlocs I'm interested in without doing any lasting harm or interfering with their natural behavior. If you're willing to help with the marking, I'll gladly pay you for your assistance.",logDesc="Morae at Blood Watch wants you to 'mark' 6 Blacksilt Scouts using the Murloc Tagger. ",choiceRewards={{id=26034,qty=1},{id=26022,qty=1},{id=26008,qty=1}}} end
if not DB[9630] then DB[9630]={id=9630,zoneId=2562,name="Medivh's Journal",level=70,minLevel=70,giver="Archmage Alturus",giverType="NPC",giverId=17613,ender="Wravien",enderType="NPC",enderId=16813,rewardNextId=9638,poiX=-11120,poiY=-2015,wowhead="https://www.wowhead.com/wotlk/quest=9630",image="assets/images/quests/placeholder.png",desc="Your name is getting around, $N.  You've made your way into and out of Karazhan - more than most mortals can claim.$B$BI need to ask a special favor of you.  As part of our research, the Violet Eye has been trying to track down Medivh's own journal.$B$BUnfortunately, none of the agents we've sent inside have come out.  Wravien was the last to be sent; see if you can find him and see about any leads on the journal.",logDesc="Archmage Alturus at Deadwind Pass wants you to go into Karazhan and speak to Wravien."} end
if not DB[9631] then DB[9631]={id=9631,zoneId=3523,name="A Colleague's Aid",level=70,minLevel=70,giver="Archmage Alturus",giverType="NPC",giverId=17613,ender="Kalynna Lathred",enderType="NPC",enderId=17636,rewardNextId=9637,poiX=-11120,poiY=-2015,wowhead="https://www.wowhead.com/wotlk/quest=9631",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There is a small detail I've forgotten to take into account.  The residue of Medivh's essence contained in this bone fragment is completely devoid of life - just like Arcanagos.$B$BThere is a way, however.  And I know just the person to help us.$B$BTravel to Area 52 in Netherstorm and show the bone fragment to Kalynna Lathred.  She will know just what to do.",logDesc="Take the Charred Bone Fragment to Kalynna Lathred at Area 52 in Netherstorm."} end
if not DB[9632] then DB[9632]={id=9632,zoneId=3525,name="Newfound Allies",level=15,minLevel=15,giver="Anchorite Paetheus",giverType="NPC",giverId=17424,ender="Huntress Kella Nightbow",enderType="NPC",enderId=17614,rewardNextId=9633,poiX=-1932,poiY=-11858,wowhead="https://www.wowhead.com/wotlk/quest=9632",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Harbinger Mikolaas has done a commendable job of safeguarding Blood Watch, $c, but our enemies are many and our resources few.$B$BOur weakness is well known to our enemies, but your contact with the forces of the Alliance is something they haven't accounted for. I have prepared a letter of introduction to the people of Auberdine, the closest Alliance settlement, proposing cooperation in the fight against our foes. Take it with you and seek out Huntress Kella Nightbow near the docks west of the Exodar.",logDesc="Take the Letter of Introduction to Huntress Kella Nightbow in Azuremyst Isle."} end
if not DB[9633] then DB[9633]={id=9633,zoneId=3525,name="The Way to Auberdine",level=15,minLevel=15,giver="Huntress Kella Nightbow",giverType="NPC",giverId=17614,ender="Thundris Windweaver",enderType="NPC",enderId=3649,poiX=-4269,poiY=-11484,wowhead="https://www.wowhead.com/wotlk/quest=9633",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If you wait out on the dock, you'll see the boat arriving from the port of Auberdine in Darkshore. Once it has offloaded its passengers, you'll be able to board.$B$BAfter a short journey, the boat will put in at Auberdine and you'll be able to deliver your message.$B$BIt's probably best to take this to Thundris Windweaver, an old friend of mine and a well-respected citizen of the town. ",logDesc="Take the boat from the dock near Huntress Kella Nightbow to Auberdine. Once you have arrived in Auberdine, take the Letter of Introduction to Thundris Windweaver."} end
if not DB[9634] then DB[9634]={id=9634,zoneId=3525,name="Alien Predators",level=11,minLevel=8,giver="Vorkhan the Elekk Herder",giverType="NPC",giverId=17586,ender="Vorkhan the Elekk Herder",enderType="NPC",enderId=17586,poiX=-2670,poiY=-12131,wowhead="https://www.wowhead.com/wotlk/quest=9634",image="assets/images/quests/placeholder.png",xpDiff=5,money=400,desc="One thing we've learned in our travels is that extreme care must be taken when introducing wildlife from one world to another. When the Exodar crashed, it was carrying specimens of various Outland species, including an insectoid predator called the ravager.$B$BSome of the specimens were lost, but many others survived and took to the wild. If we don't keep them in check, they will upset the natural balance here on the islands.$b$bYou'll find these ravagers to the west of Kessel's Crossing, near the coast.",logDesc="Kill 10 Bloodmyst Hatchlings then return to Vorkhan the Elekk Herder at Kessel's Crossing on Bloodmyst Isle.",choiceRewards={{id=26051,qty=1},{id=26053,qty=1},{id=26049,qty=1},{id=27389,qty=1}}} end
if not DB[9635] then DB[9635]={id=9635,zoneId=-201,name="The Zapthrottle Mote Extractor!",level=60,minLevel=58,giver="Mack Diver",giverType="NPC",giverId=17637,ender="Mack Diver",enderType="NPC",enderId=17637,poiX=228,poiY=7764,wowhead="https://www.wowhead.com/wotlk/quest=9635",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The swamp gas is truly amazing, and can be very useful, mon!  But first, you gotta be able to suck it up, and that, my friend, requires a Zapthrottle Mote Extractor.$B$BNow, I could just give you the schematics, but I'll need something in return first.  How about some spare parts?  Last time I checked, there were plenty laying around near the broken steam pump at the Dead Mire, far to the northeast.$B$BI heard that the withered giants spread the pieces all over that dried-out lake bed.",logDesc="Bring 15 Steam Pump Parts to Mack Diver at Zabra'jin in Zangarmarsh.",rewards={{id=23888,qty=1}}} end
if not DB[9636] then DB[9636]={id=9636,zoneId=-201,name="The Zapthrottle Mote Extractor!",level=60,minLevel=58,giver="K. Lee Smallfry",giverType="NPC",giverId=17634,ender="K. Lee Smallfry",enderType="NPC",enderId=17634,poiX=252,poiY=6024,wowhead="https://www.wowhead.com/wotlk/quest=9636",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Have you seen the swamp gas?  Isn't it just shiny?$B$BIt takes a Zapthrottle Mote Extractor to suck 'em dry though.  I could give you the plans to make one, but I really need some spare parts to fix stuff 'round here.$B$BLast time I checked, there were plenty of parts laying around near the steam pump at the Dead Mire to the northeast.  I think the withered giants broke the pump out there.$B$BShall we help each other out?",logDesc="Bring 15 Steam Pump Parts to K. Lee Smallfry at Telredor in Zangarmarsh.",rewards={{id=23888,qty=1}}} end
if not DB[9637] then DB[9637]={id=9637,zoneId=2562,name="Kalynna's Request",level=70,minLevel=70,giver="Kalynna Lathred",giverType="NPC",giverId=17636,ender="Kalynna Lathred",enderType="NPC",enderId=17636,rewardNextId=9644,poiX=3093,poiY=3687,wowhead="https://www.wowhead.com/wotlk/quest=9637",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I left the Kirin Tor in pursuit of knowledge forbidden by those of my order; it is beyond ironic that I am now asked to assist them with that very same knowledge.$B$BIf I'm to perform this favor for you, you will have to do something for me first.  I want you to obtain two of the tomes I've been searching for.$B$BThe first one is called the Tome of Dusk and is owned by the orc warlock known as Nethekurse.  The second, known as the Book of Forgotten Names, belongs to the arakkoa known as Darkweaver Syth.",logDesc="Kalynna Lathred wants you to retrieve the Tome of Dusk from Grand Warlock Nethekurse in the Shattered Halls of Hellfire Citadel and the Book of Forgotten Names from Darkweaver Syth in the Sethekk Halls in Auchindoun.$B$BThis quest must be completed in Heroic difficulty."} end
if not DB[9638] then DB[9638]={id=9638,zoneId=2562,name="In Good Hands",level=70,minLevel=70,giver="Wravien",giverType="NPC",giverId=16813,ender="Gradav",enderType="NPC",enderId=16814,rewardNextId=9639,poiX=-11182,poiY=-1800,wowhead="https://www.wowhead.com/wotlk/quest=9638",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Was I supposed to be looking for this journal?  It can't be... I don't quite recall...$B$BOf course!  It is Gradav you're thinking of.  He was looking for the book when I got here.  Surely he must've found it by now; why don't you go ask him about it?$B$BI'd lend you a hand... but these books are just so... interesting!",logDesc="Speak to Gradav at the Guardian's Library in Karazhan."} end
if not DB[9639] then DB[9639]={id=9639,zoneId=2562,name="Kamsis",level=70,minLevel=70,giver="Gradav",giverType="NPC",giverId=16814,ender="Kamsis",enderType="NPC",enderId=16815,rewardNextId=9640,poiX=-11188,poiY=-1730,wowhead="https://www.wowhead.com/wotlk/quest=9639",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Journal, what journal?  You're thinking of Kamsis, surely.$B$BGo and ask her about it.  I can't leave my project right now or all my work will be wasted!",logDesc="Speak to Kamsis at the Guardian's Library in Karazhan."} end
if not DB[9640] then DB[9640]={id=9640,zoneId=2562,name="The Shade of Aran",level=70,minLevel=70,giver="Kamsis",giverType="NPC",giverId=16815,ender="Kamsis",enderType="NPC",enderId=16815,rewardNextId=9645,poiX=-11257,poiY=-1721,wowhead="https://www.wowhead.com/wotlk/quest=9640",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Let me think for a second.  The Violet Eye... Medivh's Journal...  Why yes, it's all coming back to me now.$B$BI believe I had the journal you're looking for before I started to read these scrolls...$B$BAran... yes, Aran asked me for the book.  So nicely too.  I just had to give it to him.  He's Medivh's father after all, did you know?",logDesc="Obtain Medivh's Journal and return to Kamsis at the Guardian's Library in Karazhan."} end
if not DB[9641] then DB[9641]={id=9641,zoneId=3525,name="Irradiated Crystal Shards",level=15,minLevel=13,giver="Vindicator Boros",giverType="NPC",giverId=17684,ender="Vindicator Boros",enderType="NPC",enderId=17684,poiX=-1960,poiY=-11883,wowhead="https://www.wowhead.com/wotlk/quest=9641",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Exodar's crash scattered pieces of fouled crystals all over Bloodmyst Isle, corrupting the water and the landscape.$B$BWe've even begun finding pieces of the crystals inside the flesh of animals taken for meat. I've uncovered a way to purify the shard and turn them into functional crystals, so if you bring me enough shards, I'll trade one of my completed crystals for them. So far I've found the shards in the bodies of bears, ravagers, flutterers, and treants inhabiting the corrupted part of the island.",logDesc="Vindicator Boros at Blood Watch wants you to bring him 10 Irradiated Crystal Shards.",choiceRewards={{id=23985,qty=1},{id=23986,qty=1},{id=23989,qty=1}}} end
if not DB[9642] then DB[9642]={id=9642,zoneId=3525,name="More Irradiated Crystal Shards",level=15,minLevel=13,giver="Vindicator Boros",giverType="NPC",giverId=17684,ender="Vindicator Boros",enderType="NPC",enderId=17684,poiX=-1960,poiY=-11883,wowhead="https://www.wowhead.com/wotlk/quest=9642",image="assets/images/quests/placeholder.png",choiceRewards={{id=23985,qty=1},{id=23986,qty=1},{id=23989,qty=1}}} end
if not DB[9643] then DB[9643]={id=9643,zoneId=3525,name="Constrictor Vines",level=15,minLevel=14,giver="Tracker Lyceon",giverType="NPC",giverId=17642,ender="Tracker Lyceon",enderType="NPC",enderId=17642,poiX=-1998,poiY=-11897,wowhead="https://www.wowhead.com/wotlk/quest=9643",image="assets/images/quests/placeholder.png",xpDiff=5,money=700,desc="A good woodsman makes use of every available resource, $c. Even the most bizarre creatures possess attributes we can use to our advantage.$B$BWith Blood Watch under constant assault from the Sunhawks, we're looking to a variety of natural defenses including traps. The lasher's thorny vines are perfectly suited to the construction of the traps I have in mind. The combination of sharp spines and deadly toxin will fell unwary attackers. Bring me the vines of mutated constrictors so that I can begin my work.",logDesc="Tracker Lyceon at Blood Watch wants you to bring him 6 Thorny Constrictor Vines."} end
if not DB[9644] then DB[9644]={id=9644,zoneId=2562,name="Nightbane",level=70,minLevel=70,giver="Kalynna Lathred",giverType="NPC",giverId=17636,ender="Archmage Alturus",enderType="NPC",enderId=17613,poiX=3093,poiY=3687,wowhead="https://www.wowhead.com/wotlk/quest=9644",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You fulfilled your end of the deal.  I will now bind your essence to that of the dead blue dragon.$B$BThere is an urn in the Master's Terrace, should you touch that urn, you'll now release its energy anl bring life back to the charred remains of Arcanagos.  Defeat the creature and retrieve its essence immediately!  You will need to take it to Alturus.$B$BShould you fail, the stars predict you will have let a great terror loose upon the skies.$B$BA terror known as Nightbane!",logDesc="Go to the Master's Terrace in Karazhan and touch the Blackened Urn to summon Nightbane.  Retrieve the Faint Arcane Essence from Nightbane's corpse and bring it to Archmage Alturus.",choiceRewards={{id=31118,qty=1},{id=31117,qty=1},{id=31116,qty=1}}} end
if not DB[9645] then DB[9645]={id=9645,zoneId=2562,name="The Master's Terrace",level=70,minLevel=70,giver="Kamsis",giverType="NPC",giverId=16815,ender="Archmage Alturus",enderType="NPC",enderId=17613,rewardNextId=9680,poiX=-11257,poiY=-1721,wowhead="https://www.wowhead.com/wotlk/quest=9645",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Journal?  What journal?$B$BOh, right.  That journal!  The Violet Eye sent me here for it.  It's all coming back now.$B$B<Kamsis points to a page in the journal.>$B$BThis is the page that Alturus is interested in.  Did you know that while other people's journals serve as a record of their memories, Medivh's is literally just that?$B$BTry it.  Go to the Master's Terrace and read the page; you'll see just what I mean.  Might as well report to Alturus while you're at it.  I'm afraid I'll be here for a while.",logDesc="Go to the Master's Terrace in Karazhan and read Medivh's Journal.  Return to Archmage Alturus with Medivh's Journal after completing this task."} end
if not DB[9646] then DB[9646]={id=9646,zoneId=3525,name="WANTED: Deathclaw",level=17,minLevel=9,ender="Harbinger Mikolaas",enderType="NPC",enderId=17423,wowhead="https://www.wowhead.com/wotlk/quest=9646",image="assets/images/quests/placeholder.png",xpDiff=5,money=1800,desc="By order of Harbinger Mikolaas: A bounty of 18 silver to be paid to the brave soul who returns with proof of the marauding bear Deathclaw's demise.$B$BDeathclaw should be considered extremely dangerous and is responsible for the killing of a survey team on the coast to the northwest of Blood Watch. Travelers are advised to avoid the area.",logDesc="Bring Deathclaw's Paw to Harbinger Mikolaas in Blood Watch.",choiceRewards={{id=27398,qty=1},{id=27400,qty=1}}} end
if not DB[9647] then DB[9647]={id=9647,zoneId=3525,name="Culling the Flutterers",level=16,minLevel=14,giver="Tracker Lyceon",giverType="NPC",giverId=17642,ender="Tracker Lyceon",enderType="NPC",enderId=17642,poiX=-1998,poiY=-11897,wowhead="https://www.wowhead.com/wotlk/quest=9647",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="When we first encountered flutterers, they showed few signs of mutation. As the corruption got progressively worse, the moths and other species began to show signs of contamination.$B$BIt has progressed to the point where they damage nearly everything they come in contact with. They're amplifying the damage being done by the crystal shards scattered by the Exodar's crash. We have no choice but to begin culling their population in the lands north of Blood Watch.",logDesc="Tracker Lyceon at Blood Watch wants you to kill 10 Royal Blue Flutterers.",choiceRewards={{id=26013,qty=1},{id=26026,qty=1},{id=26038,qty=1}}} end
if not DB[9648] then DB[9648]={id=9648,zoneId=3525,name="Mac'Aree Mushroom Menagerie",level=14,minLevel=10,giver="Jessera of Mac'Aree",giverType="NPC",giverId=17663,ender="Jessera of Mac'Aree",enderType="NPC",enderId=17663,poiX=-1994,poiY=-11916,wowhead="https://www.wowhead.com/wotlk/quest=9648",image="assets/images/quests/placeholder.png",xpDiff=5,money=1300,desc="Did you know mushroom hunting is far more dangerous than mushroom consumption? Mushroom hunters expose themselves to many unknowns - not including potential wildlife dangers!$B$BWhat would life be without a little danger? I am in need of mushrooms for my collection. Scattered throughout these unexplored wilds you will find four different types: An aquatic stinkhorn, a blood mushroom, a ruinous polyspore, and a fel cone fungus. They are each unique to various regions in Bloodmyst. Bring them to me.",logDesc="Jessera of Mac'Aree at Blood Watch wants 1 Aquatic Stinkhorn, 1 Blood Mushroom, 1 Ruinous Polyspore, and 1 Fel Cone Fungus.",choiceRewards={{id=26014,qty=1},{id=26028,qty=1},{id=26040,qty=1}}} end
if not DB[9649] then DB[9649]={id=9649,zoneId=3525,name="Ysera's Tears",level=18,minLevel=15,giver="Jessera of Mac'Aree",giverType="NPC",giverId=17663,ender="Jessera of Mac'Aree",enderType="NPC",enderId=17663,poiX=-1994,poiY=-11916,wowhead="https://www.wowhead.com/wotlk/quest=9649",image="assets/images/quests/placeholder.png",xpDiff=5,money=3000,desc="Good to see you again, $N! You were exceptionally efficient in completing the last task that I offered you. Perhaps you would be interested in another?$B$BTo the northeast lies Wyrmscar Island, home to a rare species of mushroom known as Ysera's tear - named after the green dragonlings that inhabit the island. I only require a small sampling of the mushroom, but I must warn you that the denizens of the island do not welcome visitors. Tread carefully.$B",logDesc="Jessera of Mac'Aree at Blood Watch wants 2 Ysera's Tears.",choiceRewards={{id=26005,qty=1},{id=26019,qty=1},{id=26030,qty=1}}} end
if not DB[9650] then DB[9650]={id=9650,zoneId=2562,name="Deprecated: Magical Augmentation",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=9650",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<TXT>Yes,let's enhance my magical properties.  That makes sense.  I was,after all,a wizard in life.$B$BJust because one's physical vessel is a weapon does not automatically make someone a brute.$B$BI will need you to collect some materials.",logDesc="<TXT>",choiceRewards={{id=23911,qty=1}}} end
if not DB[9651] then DB[9651]={id=9651,zoneId=2562,name="Deprecated: Magical Augmentation",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=9651",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<TXT>Yes,let's enhance my magical properties.  That makes sense.  I was,after all,a wizard in life.$B$BJust because one's physical vessel is a weapon does not automatically make someone a brute.$B$BI will need you to collect some materials.",logDesc="<TXT>",rewards={{id=23649,qty=1}}} end
if not DB[9652] then DB[9652]={id=9652,zoneId=2562,name="Deprecated: Physical Enhancement",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=9652",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I wouldn't mind that.  We might as well make the best of our situation... in my case,being a weapon.  Might as well become the best weapon I can be.$B$BYes,let's do that.  A sharper edge,a sturdier hilt... I like the sound of that.$B$BI'll need you to gather a few things for me.",rewards={{id=23916,qty=1}}} end
if not DB[9653] then DB[9653]={id=9653,zoneId=2562,name="Deprecated: Physical Enhancement",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=9653",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I wouldn't mind that.  We might as well make the best of our situation... in my case,being a weapon.  Might as well become the best weapon I can be.$B$BYes,let's do that.  A sharper edge,a sturdier hilt... I like the sound of that.$B$BI'll need you to gather a few things for me.",rewards={{id=23648,qty=1}}} end
if not DB[9654] then DB[9654]={id=9654,zoneId=2562,name="Deprecated: A Well Rounded Defense",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=9654",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Offensive magic was my area of expertise... that much I can remember.  I'll do my best to add my arcane channeling powers to yours.$B$BI'll need more raw power than I possess right now,however.  The arcane anomalies that roam the upper levels of the guardian's library would make excellent targets.  Gather their arcane residue,we'll need lots of it.",logDesc="The Facet of Keanna stored inside Keanna's Will wants you to gather 20 Arcane Residues from the Arcane Anomalies in Karazhan.",rewards={{id=23917,qty=1}}} end
if not DB[9655] then DB[9655]={id=9655,zoneId=2562,name="Deprecated: Healing Amplification",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=9655",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Offensive magic was my area of expertise... that much I can remember.  I'll do my best to add my arcane channeling powers to yours.$B$BI'll need more raw power than I possess right now,however.  The arcane anomalies that roam the upper levels of the guardian's library would make excellent targets.  Gather their arcane residue,we'll need lots of it.",logDesc="The Facet of Keanna stored inside Keanna's Will wants you to gather 20 Arcane Residues from the Arcane Anomalies in Karazhan.",rewards={{id=23914,qty=1}}} end
