if not DB[9662] then DB[9662]={id=9662,zoneId=2562,name="Deprecated: Keanna's Freedom",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=9662",image="assets/images/quests/placeholder.png",xpDiff=7,desc="My memories... I remember everything now!  My mind feels like a puzzle falling into place all of a sudden.$B$BI was one of the first sent to investigate Karazhan after it changed.  The demon Malchezaar discovered my intrusion.$B$BI quickly realized that I was no match for him.  I began to feel my soul become trapped by his magic.$B$BAt the last moment I hid a fraction of myself... of my memories inside the only place I could think of: my weapon.  Malchezaar has my soul.  You must help me recover it!",logDesc="Defeat Malchezar in Karazhan while equipped with Keanna's Will.  Facet of Keanna must survive."} end
if not DB[9663] then DB[9663]={id=9663,zoneId=3525,name="The Kessel Run",level=12,minLevel=10,giver="Kessel",giverType="NPC",giverId=17649,ender="Kessel",enderType="NPC",enderId=17649,rewardNextId=9666,poiX=-2662,poiY=-12130,wowhead="https://www.wowhead.com/wotlk/quest=9663",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You're just in time, $N. Blood elf activity in this area has doubled in the past week. Our agents have informed us that the blood elves that call themselves Sunhawks plan to launch an offensive upon Azuremyst soon. I need you to get a warning out to our allies and compatriots.$B$BWarn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing.$B$BTime is of the essence so I am lending you my elekk. Be sure to keep it out of water.",logDesc="Kessel at Kessel's Crossing wants you to warn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing of the imminent blood elf invasion. Return to Kessel when you complete this task. You have 15 minutes. (Be sure to keep it out of water.)"} end
if not DB[9664] then DB[9664]={id=9664,zoneId=139,name="Establishing New Outposts",level=60,minLevel=55,giver="Emissary Whitebeard",giverType="NPC",giverId=17069,ender="Emissary Whitebeard",enderType="NPC",enderId=17069,poiX=2268,poiY=-5333,wowhead="https://www.wowhead.com/wotlk/quest=9664",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="Welcome to the Plaguelands, $n. As you know, the Forsaken and their allies hold the lands to the west of here against our best efforts. The Alliance commanders have decided that here in the east, we will establish new fortifications to tighten the noose around our enemies.$b$bTowers long abandoned since the days of Lordaeron are to be seized and rebuilt for this purpose. These lands are dangerous, and we could use your help.",logDesc="Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Whitebeard at Light's Hope Chapel."} end
if not DB[9665] then DB[9665]={id=9665,zoneId=139,name="Bolstering Our Defenses",level=60,minLevel=55,giver="Emissary Gormok",giverType="NPC",giverId=17072,ender="Emissary Gormok",enderType="NPC",enderId=17072,poiX=2317,poiY=-5284,wowhead="https://www.wowhead.com/wotlk/quest=9665",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="Agents of the Forsaken uncovered an Alliance plot to establish new bases here in the Eastern Plaguelands, at abandoned towers throughout the area.$b$bIt is imperative that we not allow them to establish a significant presence on our eastern borders, and so we must stave off this Alliance incursion. Our current plans are to drive them out of any towers they may have already seized, and occupy those that we have under our control against further attacks.",logDesc="Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel."} end
if not DB[9666] then DB[9666]={id=9666,zoneId=3525,name="Declaration of Power",level=13,minLevel=10,giver="Kessel",giverType="NPC",giverId=17649,ender="Kessel",enderType="NPC",enderId=17649,rewardNextId=9668,poiX=-2662,poiY=-12130,wowhead="https://www.wowhead.com/wotlk/quest=9666",image="assets/images/quests/placeholder.png",xpDiff=5,money=600,desc="Have you seen the serpent men? The ones that call themselves naga?$B$B<Kessel spits.>$B$BThey dared make an advance upon this camp under cover of darkness only three nights ago. Can you believe the audacity of those primitive beasts?$B$BI need you to deliver a message to their leadership, $N. To the northeast is Wrathscale Lair, home to Lord Xiz. Find him, slay him where he stands and drive this banner through his corpse.$B$BLet them know fear whenever they should see our standard!",logDesc="Kessel at Kessel's Crossing on Bloodmyst Isle wants you to kill Lord Xiz at Wrathscale Lair and drive the Draenei Banner through his dead body.",choiceRewards={{id=26012,qty=1},{id=26027,qty=1},{id=26039,qty=1}}} end
if not DB[9667] then DB[9667]={id=9667,zoneId=3525,name="Saving Princess Stillpine",level=13,minLevel=10,giver="Princess Stillpine",giverType="NPC",giverId=17682,ender="Stillpine Ambassador Frasaboo",enderType="NPC",enderId=18803,poiX=-2520,poiY=-12302,wowhead="https://www.wowhead.com/wotlk/quest=9667",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Help me, $N! The Bristlelimb captured me and are planning to sacrifice me to their foul gods!$B$BHigh Chief Bristlelimb holds the key that opens the cage. To force him to appear, you must slaughter the evil Bristlelimb furbolgs that inhabit the enclave, just two camps to the west of this camp. If you kill enough of them, he will surely come for vengeance! When he shows up, kill him and get the key!$B$BMy father will richly reward you if you can save me!",logDesc="Release Princess Stillpine from her cage and then speak with Stillpine Ambassador Frasaboo at Blood Watch.$B$BYou must kill High Chief Bristlelimb for the key that opens the cage.",choiceRewards={{id=24342,qty=1},{id=24343,qty=1}}} end
if not DB[9668] then DB[9668]={id=9668,zoneId=3525,name="Report to Exarch Admetius",level=13,minLevel=10,giver="Kessel",giverType="NPC",giverId=17649,ender="Exarch Admetius",enderType="NPC",enderId=17658,poiX=-2662,poiY=-12130,wowhead="https://www.wowhead.com/wotlk/quest=9668",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A Hand of Argus soldier is many things: Obedient, brave, intelligent, and above all, honorable. You may yet exhibit some of these traits, $c.$B$BReport to Exarch Admetius at Blood Watch if you are still interested in joining the Hand. He and his subordinates will further train you in the ways of the draenei soldier.$B$BAnd remember this, $N: Honorable people do not always perform honorably. Sometimes they cannot.$B$BYou will find Blood Watch just up this road, to the north.",logDesc="Speak with Exarch Admetius at Blood Watch."} end
if not DB[9669] then DB[9669]={id=9669,zoneId=3525,name="The Missing Expedition",level=19,minLevel=16,giver="Achelus",giverType="NPC",giverId=17676,ender="Achelus",enderType="NPC",enderId=17676,poiX=-1999,poiY=-11812,wowhead="https://www.wowhead.com/wotlk/quest=9669",image="assets/images/quests/placeholder.png",xpDiff=5,money=3000,desc="About a week ago, my research team and I were out exploring the western wilds of Bloodmyst when we were attacked by bloodthirsty spiders. The effect of the crystal contamination was clearly evident as these spiders were massive and extremely aggressive.$B$BI managed to escape but my team wasn't so lucky. We must not let the same fate befall others. Go west to the Amberweb Pass and destroy the spiders and their matriarch, Zarakh.",logDesc="Kill 8 Myst Spinners, 8 Myst Leechers and their leader, Zarakh. Return to Achelus at Blood Watch when the task is complete."} end
if not DB[9670] then DB[9670]={id=9670,zoneId=3525,name="They're Alive! Maybe...",level=19,minLevel=16,giver="Researcher Cornelius",giverType="NPC",giverId=17686,ender="Researcher Cornelius",enderType="NPC",enderId=17686,poiX=-1505,poiY=-10887,wowhead="https://www.wowhead.com/wotlk/quest=9670",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It was a bloody mess, $N. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons.$B$BAfter we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD!$B$BI managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand?$B$BDestroy those cocoons! Hopefully some of our team is still alive!$B",logDesc="Researcher Cornelius has asked that you free 5 Expedition Researchers.",rewards={{id=26017,qty=1}}} end
if not DB[9671] then DB[9671]={id=9671,zoneId=3525,name="Urgent Delivery",level=18,minLevel=15,giver="Messenger Hermesius",giverType="NPC",giverId=17703,ender="Messenger Hermesius",enderType="NPC",enderId=17703,poiX=-1952,poiY=-11897,wowhead="https://www.wowhead.com/wotlk/quest=9671",image="assets/images/quests/placeholder.png"} end
if not DB[9672] then DB[9672]={id=9672,zoneId=3525,name="The Bloodcurse Legacy",level=18,minLevel=15,ender="Captain Edward Hanes",enderType="NPC",enderId=17712,rewardNextId=9674,wowhead="https://www.wowhead.com/wotlk/quest=9672",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Dear friend,$B$BMy hand trembles as I ink this letter. I pray that it reaches you in time.$B$BLast night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago.$B$BThis apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of your base?$B$BRegards,$B$BAdmiral Odesyus$B",logDesc="Admiral Odesyus has asked that you find and speak with Captain Edward Hanes."} end
if not DB[9673] then DB[9673]={id=9673,zoneId=-261,name="Beast Training",level=-1,minLevel=10,giver="Lieutenant Dawnrunner",giverType="NPC",giverId=15399,ender="Halthenis",enderType="NPC",enderId=16675,poiX=8981,poiY=-7458,wowhead="https://www.wowhead.com/wotlk/quest=9673",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Beyond bonding with your chosen pet, there remains the intricacies of caring and training it.  For this, Halthenis the beast trainer of Silvermoon City can show you the way.$b$bHe always shows the utmost respect for my students, if they do the same for him.  Do not disappoint me.",logDesc="Speak with Halthenis in Silvermoon City.",rewards={{id=24136,qty=1}}} end
if not DB[9674] then DB[9674]={id=9674,zoneId=3525,name="The Bloodcursed Naga",level=18,minLevel=15,giver="Captain Edward Hanes",giverType="NPC",giverId=17712,ender="Captain Edward Hanes",enderType="NPC",enderId=17712,rewardNextId=9682,poiX=-1251,poiY=-12657,wowhead="https://www.wowhead.com/wotlk/quest=9674",image="assets/images/quests/placeholder.png",xpDiff=5,desc="They say when the world was sundered, this land cried the loudest. It was here that thousands of night elves faded into oblivion and in their place rose terrible creatures of hate - the naga.$B$BObedient to their twisted queen, Azshara, they would destroy all that would dare pass through their sea. It would remain this way for thousands of years - until now.$B$BThe first order of business is to remove the bloodcursed naga from the reef.",logDesc="Captain Edward Hanes on Wyrmscar Island wants you to kill 10 Bloodcursed Naga.$B"} end
if not DB[9675] then DB[9675]={id=9675,zoneId=-261,name="Beast Training",level=-1,minLevel=10,giver="Huntress Kella Nightbow",giverType="NPC",giverId=17614,ender="Ganaar",enderType="NPC",enderId=16712,poiX=-4269,poiY=-11484,wowhead="https://www.wowhead.com/wotlk/quest=9675",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Oh, one more thing!  You'll want to speak with Ganaar at the Exodar.  He'll be able to teach you the last bits of knowledge necessary to care for your pet and train it.$b$bYou can find him in the southwest corner of the Traders Tier.",logDesc="Speak with Ganaar at the Traders Tier of the Exodar.",rewards={{id=24138,qty=1}}} end
if not DB[9676] then DB[9676]={id=9676,zoneId=-141,name="Paladin Training",level=1,minLevel=1,giver="Magistrix Erona",giverType="NPC",giverId=15278,ender="Jesthenis Sunstriker",enderType="NPC",enderId=15280,poiX=10352,poiY=-6360,wowhead="https://www.wowhead.com/wotlk/quest=9676",image="assets/images/quests/placeholder.png",xpDiff=3,desc="As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young paladins here on Sunstrider Isle, your trainer is Jesthenis Sunstriker. Speak with Jesthenis and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.$B$BYour trainer - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.",logDesc="Speak with Jesthenis Sunstriker - the Paladin class trainer - inside the Sunspire on Sunstrider Isle."} end
if not DB[9677] then DB[9677]={id=9677,zoneId=-141,name="Summons from Knight-Lord Bloodvalor",level=-1,minLevel=12,giver="Noellene",giverType="NPC",giverId=16275,ender="Knight-Lord Bloodvalor",enderType="NPC",enderId=17717,rewardNextId=9678,poiX=9516,poiY=-6871,wowhead="https://www.wowhead.com/wotlk/quest=9677",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N, you have excelled in your early training and distinguished yourself among those who would become Blood Knights. You are ready to undertake the next phase of your training and, to that end, Knight-Lord Bloodvalor himself has asked to speak with you.$B$BI have no doubt that Knight-Lord Bloodvalor wishes to set a trial for you to test your abilities and training. You will find him in the Blood Knight headquarters in Silvermoon City's Farstriders' Square. I wish you well, $N.",logDesc="Speak with Knight-Lord Bloodvalor in Farstriders' Square in Silvermoon City."} end
if not DB[9678] then DB[9678]={id=9678,zoneId=-141,name="The First Trial",level=-1,minLevel=12,giver="Knight-Lord Bloodvalor",giverType="NPC",giverId=17717,ender="Knight-Lord Bloodvalor",enderType="NPC",enderId=17717,rewardNextId=9681,poiX=9870,poiY=-7482,wowhead="https://www.wowhead.com/wotlk/quest=9678",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have learned much of combat and bloodshed, initiate, but there is much more to our order.$B$BMastery of the Light requires a focused mind and tremendous willpower. Without these, you are little better than a street thug.$B$BThere is an island in the northeastern reaches of the Ghostlands, called the Isle of Tribulations, that we use to hone these skills. You will find a brazier within a shallow cave there. Kneel before the brazier, light it, and focus on what you see before your eyes.",logDesc="Travel to the island Knight-Lord Bloodvalor described, find the cave, and light the brazier. When the First Trial is over, return to Knight-Lord Bloodvalor in Silvermoon City."} end
if not DB[9679] then DB[9679]={id=9679,zoneId=-141,name="<NYI>Return to Knight-Lord Bloodvalor",level=-1,minLevel=12,rewardNextId=9679,wowhead="https://www.wowhead.com/wotlk/quest=9679",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Your assailant has died,but his words make it seem as though his presence here is no accident. It can only be meant as part of the test Knight-Lord Bloodvalor spoke about.$B$BHaving survived your ordeal and done as the Knight-Lord asked,you should make your way back to Silvermoon City and report to him.",logDesc="Report to Knight-Lord Bloodvalor in Silvermoon City."} end
if not DB[9680] then DB[9680]={id=9680,zoneId=41,name="Digging Up the Past",level=70,minLevel=70,giver="Archmage Alturus",giverType="NPC",giverId=17613,ender="Archmage Alturus",enderType="NPC",enderId=17613,rewardNextId=9631,poiX=-11120,poiY=-2015,wowhead="https://www.wowhead.com/wotlk/quest=9680",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Kamsis was right!  This information is extremely important.$B$BIf Medivh weaved his own essence into the magic he used to defeat the dragon, it is quite possible we could retrieve even a faint residue of that essence from the dragon's remains.  What great insight may lie beneath the ashes of Deadwind Pass, awaiting discovery.$B$BGo to the mountains south of Karazhan and bring me back a bone fragment of seemingly draconic origin.",logDesc="Archmage Alturus wants you to go to the mountains south of Karazhan in Deadwind Pass and retrieve a Charred Bone Fragment."} end
if not DB[9681] then DB[9681]={id=9681,zoneId=-141,name="A Study in Power",level=-1,minLevel=12,giver="Knight-Lord Bloodvalor",giverType="NPC",giverId=17717,ender="Magister Astalor Bloodsworn",enderType="NPC",enderId=17718,rewardNextId=9684,poiX=9870,poiY=-7482,wowhead="https://www.wowhead.com/wotlk/quest=9681",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Do not think me unduly harsh, $N. Stillblade knew well what he was being sent to do. He understood and accepted his duty and is an example for all aspiring Blood Knights.$B$BMy words are no eulogy, $N. Stillblade's service to us is far from over and you will be the instrument of his resurrection.$B$BYour education in the order's ways has just begun. With the betrayal of Kael'thas and the loss of our power source, you must learn new methods of wielding the Light. Seek out Magister Astalor Bloodsworn.",logDesc="Speak with Magister Astalor Bloodsworn in the hidden chamber beneath Blood Knight headquarters."} end
if not DB[9682] then DB[9682]={id=9682,zoneId=3525,name="The Hopeless Ones...",level=18,minLevel=15,giver="Captain Edward Hanes",giverType="NPC",giverId=17712,ender="Captain Edward Hanes",enderType="NPC",enderId=17712,rewardNextId=9683,poiX=-1251,poiY=-12657,wowhead="https://www.wowhead.com/wotlk/quest=9682",image="assets/images/quests/placeholder.png",xpDiff=5,desc="On a ledge of the reef, deeper than where you found the bloodcursed naga, you will find the hopeless ones: The bloodcursed voyagers, ghosts of those taken by the bloodcurse.$B$BIt is regrettable, what I ask of you now... but they must be destroyed and their cursed shells brought back to me.$B$BTheir souls must be put to rest. Return to me when you have done as asked and I shall give you one final task.",logDesc="Captain Edward Hanes on Wyrmscar Island wants you to recover 4 Bloodcursed Souls."} end
if not DB[9683] then DB[9683]={id=9683,zoneId=3525,name="Ending the Bloodcurse",level=19,minLevel=15,giver="Captain Edward Hanes",giverType="NPC",giverId=17712,ender="Captain Edward Hanes",enderType="NPC",enderId=17712,poiX=-1251,poiY=-12657,wowhead="https://www.wowhead.com/wotlk/quest=9683",image="assets/images/quests/placeholder.png",xpDiff=5,desc="To the south you will find Bloodcurse Isle. Atop the island you will find a shrine dedicated to the beloved queen of the naga, Azshara. Destroy the statue - burn it in effigy! This will surely draw the ire of Atoph, the Bloodcursed leader.$B$BSlay Atoph and return to me!",logDesc="Captain Edward Hanes on Wyrmscar Island wants you to destroy the Statue of Queen Azshara and kill Atoph the Bloodcursed.",rewards={{id=24334,qty=1}}} end
if not DB[9684] then DB[9684]={id=9684,zoneId=-141,name="Claiming the Light",level=-1,minLevel=12,giver="Magister Astalor Bloodsworn",giverType="NPC",giverId=17718,ender="Knight-Lord Bloodvalor",enderType="NPC",enderId=17717,rewardNextId=9685,poiX=9861,poiY=-7516,wowhead="https://www.wowhead.com/wotlk/quest=9684",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Take this vessel, $N. The enchantment it bears will allow you to draw the last vestiges of the Light surrounding these magisters. They once tended the captive naaru and some of its energy yet remains within them.$B$BIt will be just enough to restore your comrade to life.$B$BDo not worry about the magisters, $N. I have seen to their care, and Lord Solanar assures me that Lady Liadrin seeks a new source of power even now.",logDesc="Use the Shimmering Vessel on the Blood Elf Magisters to fill it and return to Knight-Lord Bloodvalor in Silvermoon City."} end
if not DB[9685] then DB[9685]={id=9685,zoneId=-141,name="Redeeming the Dead",level=-1,minLevel=12,giver="Knight-Lord Bloodvalor",giverType="NPC",giverId=17717,ender="Knight-Lord Bloodvalor",enderType="NPC",enderId=17717,poiX=9870,poiY=-7482,wowhead="https://www.wowhead.com/wotlk/quest=9685",image="assets/images/quests/placeholder.png",xpDiff=6,desc="While you were preparing the vessel, I sent a group of initiates to retrieve Sangrias Stillblade. You will find him on the top level of Silvermoon's inn with an attendant. Make your way there with all haste and unleash the vessel's magic to restore him to life.$B$BTime is of the essence, $N. Once he has been dead for too long, not even the Light can bring him back to us. Return to me once you have resurrected Stillblade.",logDesc="Take the Filled Shimmering Vessel to Silvermoon City's inn and use its magic to resurrect Sangrias Stillblade."} end
if not DB[9686] then DB[9686]={id=9686,zoneId=-141,name="The Second Trial",level=-1,minLevel=20,giver="Master Kelerun Bloodmourn",giverType="NPC",giverId=17807,ender="Master Kelerun Bloodmourn",enderType="NPC",enderId=17807,rewardNextId=9691,poiX=10100,poiY=-6599,wowhead="https://www.wowhead.com/wotlk/quest=9686",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You stand on the verge of adept status in the order, $N. First, you must prove your worthiness by undertaking another trial.$B$BThe Second Trial differs from the first in that there will be no surprises this time. The challenge before you is simple; you must face and best four Blood Knight champions in combat.$B$BWhen you accept the challenge, a crystal will appear in the middle of the pavilion. Touch it to begin your trial and do not stray far from the building.$B$BAre you prepared?",logDesc="Complete the Second Trial by defeating Champion Bloodwrath, Champion Lightrend, Champion Swiftblade, and Champion Sunstriker in the pavilion near Master Kelerun Bloodmourn."} end
if not DB[9687] then DB[9687]={id=9687,zoneId=3525,name="Restoring Sanctity",level=18,minLevel=15,giver="Prince Toreth",giverType="NPC",giverId=17674,ender="Prince Toreth",enderType="NPC",enderId=17674,poiX=-1507,poiY=-12525,wowhead="https://www.wowhead.com/wotlk/quest=9687",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Not long ago, the once tranquil owlkin of the region appeared on the shores of this island. One by one they would come to steal the bones of the fallen dragons. I do not know what would cause these creatures such distress or why they would want the bones of the deceased, but the spirits of the brood have grown restless due to this sacrilege.$B$BTo the west, across the Crimson Reach, you will find Ragefeather Ridge. Venture to the owlkin encampments and recover the pilfered dragon bones.",logDesc="Prince Toreth on Wyrmscar Island wants you to recover 8 Dragon Bones."} end
if not DB[9688] then DB[9688]={id=9688,zoneId=3525,name="Into the Dream",level=19,minLevel=16,giver="Prince Toreth",giverType="NPC",giverId=17674,ender="Prince Toreth",enderType="NPC",enderId=17674,poiX=-1507,poiY=-12525,wowhead="https://www.wowhead.com/wotlk/quest=9688",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The whelps that you see on this island are the agitated spirits of the green dragonflight. Like me, they are bound to the land, unable to ascend to their final resting place in the Dream.$B$BRecovering the bones of the fallen has settled them somewhat but you must take further action.$B$BDestroy their ethereal manifestations. I cannot leave this place until it is done. They must be released!",logDesc="Prince Toreth at Wyrmscar Island has asked that you slay 5 Viridian Whelps and 5 Viridian Broodlings."} end
if not DB[9689] then DB[9689]={id=9689,zoneId=3525,name="Razormaw",level=21,minLevel=19,giver="Prince Toreth",giverType="NPC",giverId=17674,ender="Prince Toreth",enderType="NPC",enderId=17674,poiX=-1507,poiY=-12525,wowhead="https://www.wowhead.com/wotlk/quest=9689",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Many of the black dragonflight were slain during the attacks. One of them, a lieutenant of Deathwing himself, still haunts this place. If you look to the heavens, you can see his spectral countenance circling the skies. His hatred is so great that he remains even in death.$B$BTake the bones that you gathered for me earlier to the top of the mountain on this island and place them in the ever-burning pyre. This act should signal Razormaw to descend. When he does, slay his undead form.",logDesc="Prince Toreth at Wyrmscar Island has asked that you slay Razormaw.",choiceRewards={{id=24346,qty=1},{id=24348,qty=1},{id=24347,qty=1}}} end
if not DB[9690] then DB[9690]={id=9690,zoneId=-141,name="The Second Trial",level=-1,minLevel=20,giver="Knight-Lord Bloodvalor",giverType="NPC",giverId=17717,ender="Master Kelerun Bloodmourn",enderType="NPC",enderId=17807,rewardNextId=9686,poiX=9870,poiY=-7482,wowhead="https://www.wowhead.com/wotlk/quest=9690",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Initiate $N, you have worked hard to master the powers of the Light won by our magisters. You have learned the source of our abilities and of the duties of a Blood Knight.$B$BThe time has come for you to undergo the Second Trial, and contest for status as an adept among the Blood Knights. The trial will be administered by Master Kelerun Bloodmourn at a location north of the city. Travel north through the Ruins of Silvermoon and take the east path immediately before the bridge to Sunstrider Isle.",logDesc="Report to Master Kelerun Bloodmourn."} end
if not DB[9691] then DB[9691]={id=9691,zoneId=-141,name="Return to Silvermoon",level=-1,minLevel=20,giver="Master Kelerun Bloodmourn",giverType="NPC",giverId=17807,ender="Knight-Lord Bloodvalor",enderType="NPC",enderId=17717,rewardNextId=9692,poiX=10100,poiY=-6599,wowhead="https://www.wowhead.com/wotlk/quest=9691",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Return to Silvermoon City and report to Knight-Lord Bloodvalor promptly. Your arrival will tell him all he needs to know about the outcome of the trial.$B$BHe will tell you of your remaining tasks on the road to becoming an adept. Hold your head high, $N. Many undertake this trial, but very few return to tell of their success.",logDesc="Return to Knight-Lord Bloodvalor in Silvermoon City."} end
if not DB[9692] then DB[9692]={id=9692,zoneId=-141,name="The Path of the Adept",level=23,minLevel=20,giver="Knight-Lord Bloodvalor",giverType="NPC",giverId=17717,ender="Knight-Lord Bloodvalor",enderType="NPC",enderId=17717,rewardNextId=9707,poiX=9870,poiY=-7482,wowhead="https://www.wowhead.com/wotlk/quest=9692",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Before a newly-minted adept can be accepted into the ranks of the Blood Knights, $g he:she; must procure the resources  to create our order's distinctive weapon, the blood-tempered ranseur.$B$BYou must also earn the right to wear our order's insignia. When the order was founded, a set number were forged and distributed, so each new adept inherits $g his:hers; from a veteran. Your insignia will come from a fallen knight who bravely led an assault on Deatholme.$B$BI have prepared a set of notes to guide you.",logDesc="Bring a Corrupted Kor Gem, a Crate of Bloodforged Ingots, a quantity of Blood of the Wrathful, and a Blood Knight Insignia to Knight-Lord Bloodvalor in Silvermoon City."} end
if not DB[9693] then DB[9693]={id=9693,zoneId=3525,name="What Argus Means to Me",level=15,minLevel=10,giver="Exarch Admetius",giverType="NPC",giverId=17658,ender="Vindicator Boros",enderType="NPC",enderId=17684,rewardNextId=9694,poiX=-1916,poiY=-11794,wowhead="https://www.wowhead.com/wotlk/quest=9693",image="assets/images/quests/placeholder.png",xpDiff=1,desc="What does Argus mean to you, $N? Many draenei probably do not know or remember our home planet. It is there that we split from the man'ari: the twisted demonic reflections of ourselves that were 'gifted' by Sargeras. Or as they call themselves, eredar.$B$BEredar... this word once held meaning.$B$B<Admetius smacks his lips as if to taste the word.>$B$BDisgusting.$B$BLet us not waste anymore time. Find Vindicator Boros to begin your training.",logDesc="Exarch Admetius at Blood Watch has told you to speak with Vindicator Boros."} end
if not DB[9694] then DB[9694]={id=9694,zoneId=3525,name="Blood Watch",level=15,minLevel=10,giver="Vindicator Boros",giverType="NPC",giverId=17684,ender="Vindicator Boros",enderType="NPC",enderId=17684,poiX=-1960,poiY=-11883,wowhead="https://www.wowhead.com/wotlk/quest=9694",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Blood Watch is one of two forward bases operated by the Hand of Argus. You have already been to the other base, Azure Watch; things are completely different in Bloodmyst. When we first got here, the land was as beautiful as Azuremyst. We even called it Silvergale but now sickness is spreading across the land, worse yet, the blood elves that we were battling on the Exodar survived the crash. This brings me to your assignment: Venture northwest into Bladewood and terminate any blood elves that you find.",logDesc="Vindicator Boros at Blood Watch wants you to slay 10 Sunhawk Spies.",choiceRewards={{id=26050,qty=1},{id=26054,qty=1},{id=27640,qty=1}}} end
if not DB[9695] then DB[9695]={id=9695,zoneId=3525,name="The Sun King's Command",level=16,minLevel=14,rewardNextId=9696,wowhead="https://www.wowhead.com/wotlk/quest=9695",image="assets/images/quests/placeholder.png",xpDiff=4,desc="This document looks to be important. Unfortunately,it is written in Thalassian,a language that you cannot understand.$B$BPerhaps Vindicator Boros will know what to do with the letter.",logDesc="Take the Sun King's Command to Vindicator Boros at Blood Watch.\n"} end
if not DB[9696] then DB[9696]={id=9696,zoneId=3525,name="Translations...",level=16,minLevel=14,giver="Vindicator Boros",giverType="NPC",giverId=17684,ender="Interrogator Elysia",enderType="NPC",enderId=17825,rewardNextId=9698,poiX=-1960,poiY=-11883,wowhead="https://www.wowhead.com/wotlk/quest=9696",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Our chief interrogator, Elysia, is fluent in Thalassian. Take the document to her and see what she has to say.",logDesc="Take the Sunhawk Missive to Interrogator Elysia at Blood Watch."} end
if not DB[9697] then DB[9697]={id=9697,zoneId=3521,name="Watcher Leesa'oh",level=63,minLevel=61,giver="Lethyn Moonfire",giverType="NPC",giverId=17834,ender="Watcher Leesa'oh",enderType="NPC",enderId=17831,rewardNextId=9701,poiX=-181,poiY=5527,wowhead="https://www.wowhead.com/wotlk/quest=9697",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There's important research to be conducted into the ecology of the local creatures, especially the sporelings and bog lords of the marsh.  And trust me, once you get out into the field, you'll find the work to be challenging.$B$BSeek out Watcher Leesa'oh at the Cenarion Watchpost in the western region of the marsh toward the south.  Follow the path west and you will eventually find her.  She can be a bit -- studious -- but don't let that get to you.$B$BOh, and watch out for her cat.",logDesc="Speak with Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh."} end
if not DB[9698] then DB[9698]={id=9698,zoneId=3525,name="Audience with the Prophet",level=16,minLevel=14,giver="Interrogator Elysia",giverType="NPC",giverId=17825,ender="3",enderType="NPC",enderId=17468,rewardNextId=9699,poiX=-1943,poiY=-11851,wowhead="https://www.wowhead.com/wotlk/quest=9698",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I need you to deliver the translated documents to Velen personally, $N. I don't trust that deranged messenger.$B$BExplain to the Prophet that the blood elves are receiving reinforcements from the Outland and that they have a spy amongst the draenei at the Exodar. Velen resides in the Vault of Lights inside the Exodar.$B$BMake haste!$B",logDesc="Take the Translated Sunhawk Missive to Prophet Velen at the Exodar."} end
if not DB[9699] then DB[9699]={id=9699,zoneId=3525,name="Truth or Fiction",level=16,minLevel=14,giver="3",giverType="NPC",giverId=17468,ender="Vindicator Boros",enderType="NPC",enderId=17684,rewardNextId=9700,poiX=-3994,poiY=-11414,wowhead="https://www.wowhead.com/wotlk/quest=9699",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I thank you for the timely delivery, $N. You are turning out to be one of the Hand's better agents.$B$BIf only we knew who they reported to in Bloodmyst and more importantly, where this sun portal was... They seem to have it tightly guarded - wherever it may be.$B$BWould you be interested in some reconnaissance work?$B$BIf so, take these orders back to Vindicator Boros. He will give you your next mission.",logDesc="Take Velen's Orders to Vindicator Boros at Blood Watch."} end
if not DB[9700] then DB[9700]={id=9700,zoneId=3525,name="I Shoot Magic Into the Darkness",level=16,minLevel=14,giver="Vindicator Boros",giverType="NPC",giverId=17684,ender="Vindicator Boros",enderType="NPC",enderId=17684,poiX=-1960,poiY=-11883,wowhead="https://www.wowhead.com/wotlk/quest=9700",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Velen states that if the blood elves have been opening rifts between this island and the Outland, there will be residue or anomalies left in the areas where the portals have been opened. You must search the island for locations that exhibit or display these anomalies.$B$BBe warned, $N; some of these anomalies will be creatures from the void itself. Should you find void anomalies, slay them! Report back to me with any new information that you may find. Begin your search to the north, near the Warp Piston.$B",logDesc="Vindicator Boros at Blood Watch wants you to locate the Sun Portal Site and slay 5 Void Anomalies.",choiceRewards={{id=26010,qty=1},{id=26024,qty=1},{id=26036,qty=1}}} end
if not DB[9701] then DB[9701]={id=9701,zoneId=3521,name="Observing the Sporelings",level=63,minLevel=61,giver="Watcher Leesa'oh",giverType="NPC",giverId=17831,ender="Watcher Leesa'oh",enderType="NPC",enderId=17831,rewardNextId=9702,poiX=-284,poiY=8303,wowhead="https://www.wowhead.com/wotlk/quest=9701",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="We need to learn all that we can of the sporelings at Sporeggar and their relationship to the creatures around them.  One way to do that is what I'm doing; passive observation while making a note of their interactions.$B$BI need you to head over to the Spawning Glen to the west.  Investigate the whole area and then return to tell me what you saw.",logDesc="Investigate the Spawning Glen in Zangarmarsh, and then report back to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh with your findings."} end
if not DB[9702] then DB[9702]={id=9702,zoneId=3521,name="A Question of Gluttony",level=64,minLevel=61,giver="Watcher Leesa'oh",giverType="NPC",giverId=17831,ender="Watcher Leesa'oh",enderType="NPC",enderId=17831,rewardNextId=9708,poiX=-284,poiY=8303,wowhead="https://www.wowhead.com/wotlk/quest=9702",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="I was wondering why the bog lords were crossing the road to go to the Spawning Glen - they must be starving for some reason.  This just will not do!$B$BI mean, normally I wouldn't get involved, but if they continue to eat all of the sporeling pods they'll wipe them out!$B$BHere's what we'll do: I'll stay here and you head to the Quagg Ridge to the east and look for dietary clues as to why they're raiding the sporelings.",logDesc="Collect 10 pieces of Discarded Nutriment and then return to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh."} end
if not DB[9703] then DB[9703]={id=9703,zoneId=3525,name="The Cryo-Core",level=17,minLevel=15,giver="Vindicator Kuros",giverType="NPC",giverId=17843,ender="Vindicator Kuros",enderType="NPC",enderId=17843,poiX=-1959,poiY=-11890,wowhead="https://www.wowhead.com/wotlk/quest=9703",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We have others pursuing leads on the sun portals, $N. I need you to focus on the task at hand.$B$BBoros has received new reports of another crash site. What we've since discovered is that the crash site is actually the Exodar's cryo-core. This is a pod holding area that houses pods exactly like the ones we draenei crawled out of in Ammen Vale.$B$BThis area also holds medical supplies. Head to the Cryo-Core, directly west of Blood Watch. Search for supplies and search for survivors.$B",logDesc="Vindicator Kuros at Blood Watch wants you to recover 12 boxes of Medical Supplies.",choiceRewards={{id=26052,qty=1},{id=27641,qty=1},{id=27390,qty=1}}} end
if not DB[9704] then DB[9704]={id=9704,zoneId=3431,name="Slain by the Wretched",level=5,minLevel=4,giver="Outrunner Alarion",giverType="NPC",giverId=15301,ender="Slain Outrunner",enderType="NPC",enderId=17849,rewardNextId=9705,poiX=9984,poiY=-6478,wowhead="https://www.wowhead.com/wotlk/quest=9704",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It's hard work being an outrunner between Sunstrider Isle and Falconwing Square.  Tight deadlines, long hours and worst of all... the Wretched!$B$BThe road south goes through the ruins of Silvermoon... the place is crawling with Wretched ready to kill you for a few mana crystals.  Unfortunately, I think that's what happened to the last outrunner we sent with one of Erona's packages.$B$BI see you're eager to prove yourself.  Venture into Dawning Lane and see if you can find any traces of our outrunner.",logDesc="Go south into the ruins of Silvermoon and look for the Slain Outrunner in Dawning Lane."} end
if not DB[9705] then DB[9705]={id=9705,zoneId=3431,name="Package Recovery",level=5,minLevel=4,giver="Slain Outrunner",giverType="NPC",giverId=17849,ender="Outrunner Alarion",enderType="NPC",enderId=15301,rewardNextId=8350,poiX=9871,poiY=-6557,wowhead="https://www.wowhead.com/wotlk/quest=9705",image="assets/images/quests/placeholder.png",xpDiff=3,money=50,desc="You take the package and confirm that indeed it comes from Magistrix Erona.  Alarion would probably want you to bring it to her.",logDesc="Return to Outrunner Alarion with Erona's Package."} end
if not DB[9706] then DB[9706]={id=9706,zoneId=3525,name="Galaen's Journal - The Fate of Vindicator Saruan",level=18,minLevel=15,ender="Vindicator Kuros",enderType="NPC",enderId=17843,wowhead="https://www.wowhead.com/wotlk/quest=9706",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Your hands tremble as you pick up the book. Kuros must be told about this tragedy. Return the book to him.",logDesc="Take Galaen's Journal to Vindicator Kuros at Blood Watch.$B"} end
if not DB[9707] then DB[9707]={id=9707,zoneId=-141,name="Forging the Weapon",level=23,minLevel=20,giver="Knight-Lord Bloodvalor",giverType="NPC",giverId=17717,ender="Bemarrin",enderType="NPC",enderId=16669,rewardNextId=9710,poiX=9870,poiY=-7482,wowhead="https://www.wowhead.com/wotlk/quest=9707",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Once again, you have proven yourself worthy before the order and your peers. It is with great pleasure that I bestow upon you the rank of adept, $N. Prince Kael'thas himself would be proud of you.$B$BAny of us would be honored to fight by your side on the field of battle. Continue to serve as an example for those who aspire to join us. Show neither mercy nor weakness, defend your people and your brothers tirelessly, and hone your mastery of the Light.$B$BNow, claim the weapon befitting your new rank.",logDesc="Take the Crate of Materials to Bemarrin in Silvermoon City."} end
if not DB[9708] then DB[9708]={id=9708,zoneId=3521,name="Familiar Fungi",level=63,minLevel=61,giver="Watcher Leesa'oh",giverType="NPC",giverId=17831,ender="Watcher Leesa'oh",enderType="NPC",enderId=17831,rewardNextId=9709,poiX=-284,poiY=8303,wowhead="https://www.wowhead.com/wotlk/quest=9708",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Yes, that's it, I knew I had seen this particular phylum of mushroom elsewhere in the marsh!$B$BTo the north is a place known as the Hewn Bog.  Odd name for the place if you ask me, but I've never been there.  I'll need samples of those mushrooms to confirm my hypothesis.$B$BJust be careful, $c.  I'd heard that ogres have moved in to the area, so you'll have to get the samples from them.  Could that be why the bog lords are no longer going there for their food?",logDesc="Collect 15 Mushroom Samples and return them to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh."} end
if not DB[9709] then DB[9709]={id=9709,zoneId=3521,name="Stealing Back the Mushrooms",level=64,minLevel=61,giver="Watcher Leesa'oh",giverType="NPC",giverId=17831,ender="Watcher Leesa'oh",enderType="NPC",enderId=17831,poiX=-284,poiY=8303,wowhead="https://www.wowhead.com/wotlk/quest=9709",image="assets/images/quests/placeholder.png",xpDiff=6,money=62000,desc="$C, I've got an idea.   I want you to head north again, this time into the heart of ogre territory!$B$BNorthwest of the Hewn Bog there is a place named Ango'rosh Stronghold, which sits on a floating island across a large mushroom bridge.$B$BThe ogres must be storing the harvested mushrooms there.  I bet you'll find them all over the place, and probably on the ogres themselves, too!$B$BBring me a sufficient number and I will try to do something about providing the bog lords with a new source of nourishment.",logDesc="Collect 10 Boxes of Mushrooms and return them to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.",choiceRewards={{id=25525,qty=1},{id=25534,qty=1},{id=25530,qty=1},{id=31661,qty=1}}} end
if not DB[9710] then DB[9710]={id=9710,zoneId=-141,name="The Blood-Tempered Ranseur",level=23,minLevel=20,giver="Bemarrin",giverType="NPC",giverId=16669,ender="Bemarrin",enderType="NPC",enderId=16669,poiX=9842,poiY=-7362,wowhead="https://www.wowhead.com/wotlk/quest=9710",image="assets/images/quests/placeholder.png",desc="I've got everything prepared, $N. Very soon you will have a weapon befitting your new status.",logDesc="Wait while Bemarrin forges your weapon.",rewards={{id=25464,qty=1}}} end
if not DB[9711] then DB[9711]={id=9711,zoneId=3525,name="Matis the Cruel",level=18,minLevel=15,giver="Vindicator Kuros",giverType="NPC",giverId=17843,ender="Vindicator Kuros",enderType="NPC",enderId=17843,poiX=-1959,poiY=-11890,wowhead="https://www.wowhead.com/wotlk/quest=9711",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Matis will be brought to justice, $N; and I want you to be the one to find him and bring him back to the Triumvirate.$B$BScour the island for this killer. Should you find him, use this flare gun. When my trackers see the flare, they'll come and assist in capturing Matis. Return to me after he's been captured.",logDesc="Vindicator Kuros at Blood Watch wants you to capture Matis the Cruel.",choiceRewards={{id=26007,qty=1},{id=26021,qty=1},{id=26033,qty=1}}} end
if not DB[9712] then DB[9712]={id=9712,zoneId=-141,name="The Thalassian Warhorse",level=-1,minLevel=40,wowhead="https://www.wowhead.com/wotlk/quest=9712",image="assets/images/quests/placeholder.png",desc="You have distinguished yourself in the service of the order, $N. Your skill in wielding the Light energies granted by Magister Astalor and his fellows has proven you worthy to receive a new kind of knowledge.$B$BWith the Light at your command, it is possible to summon a fearsome warhorse that will serve as your faithful mount.$B$BContinue to serve with dedication and honor, $N, and even greater boons await you.",logDesc="Talk to Knight-Lord Bloodvalor to learn how to summon your Thalassian Warhorse."} end
if not DB[9713] then DB[9713]={id=9713,zoneId=0,name="Glowcap Harvesting Enabling Flag",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=9713",image="assets/images/quests/placeholder.png"} end
if not DB[9714] then DB[9714]={id=9714,zoneId=3716,name="Bring Me Another Shrubbery!",level=65,minLevel=63,giver="Gzhun'tt",giverType="NPC",giverId=17856,ender="Gzhun'tt",enderType="NPC",enderId=17856,poiX=258,poiY=8493,wowhead="https://www.wowhead.com/wotlk/quest=9714",image="assets/images/quests/placeholder.png"} end
if not DB[9715] then DB[9715]={id=9715,zoneId=3716,name="Bring Me A Shrubbery!",level=65,minLevel=63,giver="Gzhun'tt",giverType="NPC",giverId=17856,ender="Gzhun'tt",enderType="NPC",enderId=17856,poiX=258,poiY=8493,wowhead="https://www.wowhead.com/wotlk/quest=9715",image="assets/images/quests/placeholder.png",xpDiff=8,desc="We must replenish our supply of sanguine hibiscus, which we use for a number of purposes.  They used to grow thick as shrubs, but the lowering of the marsh's water levels means that they can only be found now in the Underbog at Coilfang Reservoir, under Serpent Lake.$B$BIt is said that the shamblers, bog giants, and underbats there consider them a delicacy.  So, if you are to help us, you must retrieve the flowers from them.",logDesc="Collect 5 Sanguine Hibiscus and return them to Gzhun'tt at Sporeggar in Zangarmarsh."} end
if not DB[9716] then DB[9716]={id=9716,zoneId=3521,name="Disturbance at Umbrafen Lake",level=63,minLevel=61,giver="Ysiel Windsinger",giverType="NPC",giverId=17841,ender="Ysiel Windsinger",enderType="NPC",enderId=17841,rewardNextId=9718,poiX=-143,poiY=5534,wowhead="https://www.wowhead.com/wotlk/quest=9716",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="We came to Outland expecting to find small pockets of life.  What we discovered in Zangarmarsh was a lush environment with a thriving ecosystem.$B$BOur initial assessment of the area was deceiving, however.  The water levels at the lakes and marshes have consistently been going down since we started taking measurements.$B$BThe impact this could have on the local animal and plant life is disastrous.  Go to Umbrafen Lake, southwest of here, and look for clues related to this water depletion.",logDesc="Investigate the cause of the water depletion at Umbrafen Lake.  Then return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh."} end
if not DB[9717] then DB[9717]={id=9717,zoneId=3716,name="Oh, It's On!",level=65,minLevel=63,giver="T'shu",giverType="NPC",giverId=17857,ender="T'shu",enderType="NPC",enderId=17857,poiX=267,poiY=8501,wowhead="https://www.wowhead.com/wotlk/quest=9717",image="assets/images/quests/placeholder.png",xpDiff=8,desc="While we are a peaceful people, we are at war with the spore giants, whether we like it or not.  And there is a saying amongst us that all is fair in mushrooms and war!$B$BOne of the leaders of the spore giants, Hungerfen, has been tending a very special plant, known as the Underspore, to perfection for millennia.  It would break his spirit if something were to happen to that plant.$B$BTravel to the Underbog in Coilfang Reservoir and steal a frond off of it for us.  Trust me, he'll notice.",logDesc="Gather an Underspore Frond and return it to T'shu at Sporeggar in Zangarmarsh.",rewards={{id=28111,qty=1}}} end
if not DB[9718] then DB[9718]={id=9718,zoneId=3521,name="As the Crow Flies",level=63,minLevel=61,giver="Ysiel Windsinger",giverType="NPC",giverId=17841,ender="Ysiel Windsinger",enderType="NPC",enderId=17841,rewardNextId=9720,poiX=-143,poiY=5534,wowhead="https://www.wowhead.com/wotlk/quest=9718",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We must determine how widespread the naga's activity truly is and react accordingly.$B$BExploring each body of water in Zangarmarsh could be a lengthy undertaking.  If you allow me to, I will use my magic to mold your shape to one more suited to scouting the marsh.$B$BHold this amulet above the balcony near me when you're ready to begin.  I will guide your way back to safety after we're done.",logDesc="Ysiel Windsinger wants you to use the Stormcrow Amulet to explore the major lakes in Zangarmarsh."} end
if not DB[9719] then DB[9719]={id=9719,zoneId=3716,name="Stalk the Stalker",level=65,minLevel=63,giver="Khn'nix",giverType="NPC",giverId=17866,ender="Khn'nix",enderType="NPC",enderId=17866,poiX=270,poiY=8487,wowhead="https://www.wowhead.com/wotlk/quest=9719",image="assets/images/quests/placeholder.png",xpDiff=8,desc="Historically the greatest danger to my people has been from the marsh walkers.  With the new problems we are facing from spore giants, we cannot afford another attack from our ancient enemies.$B$BYou have proven yourself to be capable, $c.  Do you think that you'd be able to journey to the Underbog in Coilfang Reservoir and eliminate the great mother of the marsh walkers, known as The Black Stalker?!$B$BBring me her brain as proof.",logDesc="Bring the Brain of the Black Stalker to Khn'nix at Sporeggar in Zangarmarsh.",choiceRewards={{id=28109,qty=1},{id=28108,qty=1}}} end
if not DB[9720] then DB[9720]={id=9720,zoneId=3521,name="Balance Must Be Preserved",level=64,minLevel=61,giver="Ysiel Windsinger",giverType="NPC",giverId=17841,ender="Ysiel Windsinger",enderType="NPC",enderId=17841,poiX=-143,poiY=5534,wowhead="https://www.wowhead.com/wotlk/quest=9720",image="assets/images/quests/placeholder.png",xpDiff=6,money=31000,desc="I cannot begin to comprehend why the naga would drain the water out of their own habitat.  What I do understand is a need to put a stop to their operations.$B$BThese seeds carry with them the rage of the earth.  Take them to the steam pumps operated by the naga and use them on their controls.$B$BThe vines that grow from the seeds will be as thick as your arm and as strong as iron.  Go, $N.  Restore the balance that the naga have upset.",logDesc="Ysiel Windsinger wants you to use the Ironvine Seeds on the Steam Pump Controls at Serpent Lake, Umbrafen Lake, Marshlight Lake and the Lagoon.  Then return to her at the Cenarion Refuge in Zangarmarsh with any leftover seeds you have."} end
if not DB[9721] then DB[9721]={id=9721,zoneId=-141,name="A Summons from Lord Solanar",level=-1,minLevel=60,giver="Knight-Lord Bloodvalor",giverType="NPC",giverId=17717,ender="Lord Solanar Bloodwrath",enderType="NPC",enderId=25223,rewardNextId=9722,poiX=9870,poiY=-7482,wowhead="https://www.wowhead.com/wotlk/quest=9721",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Your dedication to our order and advancement through the ranks has not gone unnoticed. In fact, Lord Solanar Bloodwrath, Lady Liadrin's right hand and a hero in his own right, has asked to speak with you.$B$BThis is a rare honor, $N. Normally, Lord Solanar leaves the management of the order's rank-and-file to me, but he has taken a personal interest in you. Do not tarry, $N.",logDesc="Speak with Lord Solanar Bloodwrath in Silvermoon City."} end
if not DB[9722] then DB[9722]={id=9722,zoneId=-141,name="The Master's Path",level=-1,minLevel=60,giver="Lord Solanar Bloodwrath",giverType="NPC",giverId=25223,ender="Lord Solanar Bloodwrath",enderType="NPC",enderId=25223,rewardNextId=9723,poiX=9841,poiY=-7516,wowhead="https://www.wowhead.com/wotlk/quest=9722",image="assets/images/quests/placeholder.png",desc="Within the ranks of our order, there exists an inner circle of elite knights. Members of the circle represent the most dedicated, skilled, and trustworthy of all Blood Knights and are handpicked by the leadership. Most simply know the masters by their thalassian charger mounts.$B$BEach candidate for membership must have a sponsor within the circle and must demonstrate their dedication to the order's central tenets.$B$BI have chosen to sponsor you for standing as a Blood Knight master, if this is your wish.",logDesc="Speak with Lord Solanar Bloodwrath again to accept his offer of sponsorship."} end
if not DB[9723] then DB[9723]={id=9723,zoneId=-141,name="A Gesture of Commitment",level=-1,minLevel=60,giver="Lord Solanar Bloodwrath",giverType="NPC",giverId=25223,ender="Lord Solanar Bloodwrath",enderType="NPC",enderId=25223,rewardNextId=9725,poiX=9841,poiY=-7516,wowhead="https://www.wowhead.com/wotlk/quest=9723",image="assets/images/quests/placeholder.png",xpDiff=3,desc="A Blood Knight's loyalty does not stop at the end of $g his:her; blade, $N. The order asks more of its members than mere drilling and combat. A true knight contributes to all of the order's activities, even the ones that may not seem glorious on the surface.$B$BThis first task is neither combat intensive, nor glorious, but without such contributions, the order would fall apart. I will give you a list of items Magister Astalor Bloodsworn's men require to keep us supplied with Light energy for our magics.",logDesc="Bring 40 Runecloth, 6 Arcanite Bars, 10 Sungrass, 5 Dark Runes, and 150 Gold to Lord Solanar Bloodwrath in Silvermoon City."} end
if not DB[9724] then DB[9724]={id=9724,zoneId=3521,name="Warning the Cenarion Circle",level=64,minLevel=61,giver="Ysiel Windsinger",giverType="NPC",giverId=17841,ender="Amythiel Mistwalker",enderType="NPC",enderId=16885,rewardNextId=9732,poiX=-143,poiY=5534,wowhead="https://www.wowhead.com/wotlk/quest=9724",image="assets/images/quests/placeholder.png",xpDiff=3,money=16000,desc="The Cenarion Expedition has become a large organization with a good degree of autonomy.  These events are important enough that we need to warn the Cenarion Circle.$B$BDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.",logDesc="Speak to Amythiel Mistwalker at Cenarion Post in Hellfire Peninsula."} end
if not DB[9725] then DB[9725]={id=9725,zoneId=-141,name="A Demonstration of Loyalty",level=-1,minLevel=60,giver="Lord Solanar Bloodwrath",giverType="NPC",giverId=25223,ender="Lord Solanar Bloodwrath",enderType="NPC",enderId=25223,rewardNextId=9735,poiX=9841,poiY=-7516,wowhead="https://www.wowhead.com/wotlk/quest=9725",image="assets/images/quests/placeholder.png",xpDiff=6,desc="We Blood Knights are bound to defend Quel'Thalas, $N. This is a central part of your training. Our enemies are fierce and unrelenting. Silvermoon and its people remain free by our efforts and the support of our allies.$B$BI have received some disturbing reports of a renewed Scourge presence to the southeast of our border with the Eastern Plaguelands. A company of Scourge siege engineers and their equipment appear to be staging for an attack on the Ghostlands. They must not be permitted to succeed.",logDesc="Lord Solanar Bloodwrath in Silvermoon City wants you to destroy 3 Scourge Meat Wagons and kill 15 Scourge Siege Engineers."} end
if not DB[9726] then DB[9726]={id=9726,zoneId=3521,name="Now That We're Friends...",level=64,minLevel=62,giver="Gzhun'tt",giverType="NPC",giverId=17856,ender="Gzhun'tt",enderType="NPC",enderId=17856,rewardNextId=9727,poiX=258,poiY=8493,wowhead="https://www.wowhead.com/wotlk/quest=9726",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The naga of the Bloodscale Enclave to the northeast have begun to kill our people.  We cannot allow this to continue, $c!$B$BWe suggest that you teach them a lesson as proof of our friendship.",logDesc="Kill 12 Bloodscale Slavedrivers and 6 Bloodscale Enchantresses, and then return to Gzhun'tt at Sporeggar in Zangarmarsh.",choiceRewards={{id=27749,qty=1},{id=27751,qty=1},{id=27750,qty=1},{id=27752,qty=1}}} end
if not DB[9727] then DB[9727]={id=9727,zoneId=3521,name="Now That We're Still Friends...",level=64,minLevel=62,giver="Gzhun'tt",giverType="NPC",giverId=17856,ender="Gzhun'tt",enderType="NPC",enderId=17856,poiX=258,poiY=8493,wowhead="https://www.wowhead.com/wotlk/quest=9727",image="assets/images/quests/placeholder.png",desc="Reports have come in that the naga of the Bloodscale Enclave to the northeast continue to kill our people.  We thought that you had dealt with this, $c!$B$BI suggest that you to teach them a lesson as proof of our continued friendship.",logDesc="Kill 12 Bloodscale Slavedrivers and 6 Bloodscale Enchantresses, and then return to Gzhun'tt at Sporeggar in Zangarmarsh."} end
if not DB[9728] then DB[9728]={id=9728,zoneId=3521,name="A Warm Welcome",level=64,minLevel=61,giver="Warden Hamoot",giverType="NPC",giverId=17858,ender="Warden Hamoot",enderType="NPC",enderId=17858,poiX=-252,poiY=5499,wowhead="https://www.wowhead.com/wotlk/quest=9728",image="assets/images/quests/placeholder.png",xpDiff=6,money=31000,desc="While the druids from the expedition have made themselves busy studying plants and researching the lakes, I've made it my business to deal with the hostiles in the area.$B$BEver since we set foot in Zangarmarsh, the naga have launched lethal attacks against us without warning.  We've done our best to keep them at bay, but our resources are limited.$B$BI want you to go to the various naga strongholds in Zangarmarsh and show them that we're not to be crossed.  Bring me their claws as proof of your victories.",logDesc="Warden Hamoot at the Cenarion Refuge wants you to bring him 30 Naga Claws.",rewards={{id=28100,qty=5}}} end
if not DB[9729] then DB[9729]={id=9729,zoneId=3521,name="Fhwoor Smash!",level=65,minLevel=63,giver="Fhwoor",giverType="NPC",giverId=17877,ender="Gzhun'tt",enderType="NPC",enderId=17856,poiX=231,poiY=8480,wowhead="https://www.wowhead.com/wotlk/quest=9729",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Little naga make Fhwoor angry!  Sporelings good friend to Fhwoor, so Fhwoor get naga ark.$B$BWe go into nearby naga village.  You help?  Bring friends!",logDesc="Escort Fhwoor into the area of the Marshlight steam pump to retrieve the Ark of Ssslith.  Bring Fhwoor and the ark back safely and then report back to Gzhun'tt at Sporeggar in Zangarmarsh.",choiceRewards={{id=25537,qty=1},{id=25538,qty=1},{id=25536,qty=1}}} end
if not DB[9730] then DB[9730]={id=9730,zoneId=3521,name="Leader of the Darkcrest",level=64,minLevel=58,ender="Warden Hamoot",enderType="NPC",enderId=17858,wowhead="https://www.wowhead.com/wotlk/quest=9730",image="assets/images/quests/placeholder.png",xpDiff=6,money=62000,desc="A bounty is hereby declared by the Cenarion Expedition on Rajah Haghazed, leader of the Darkcrest naga.  Haghazed was last sighted by Cenarion scouts at the Lagoon, in the central southern region of Zangarmarsh.$B$BThe Darkcrest have been linked to numerous attacks against the Cenarion Expedition and their leader is considered extremely dangerous.$B$BThose seeking to claim the bounty are advised to report to Warden Hamoot.",logDesc="Slay Rajah Haghazed at the Lagoon and return to Warden Hamoot at the Cenarion Expedition in Zangarmarsh for a reward.",choiceRewards={{id=27728,qty=1},{id=27725,qty=1},{id=27727,qty=1},{id=27726,qty=1}}} end
if not DB[9731] then DB[9731]={id=9731,zoneId=3521,name="Drain Schematics",level=63,minLevel=59,ender="Ysiel Windsinger",enderType="NPC",enderId=17841,wowhead="https://www.wowhead.com/wotlk/quest=9731",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="The schematics you've obtained show an underground system of drains and pumps that connect the lakes in the region to Serpent Lake.$B$BIf the schematics are correct, there is a giant drain in the center of Serpent Lake.  Confirm this and bring the news to Cenarion Refuge.",logDesc="Search Serpent Lake for signs of a drain.  Return to Ysiel Windsinger at the Cenarion Refuge with news of your discovery.",choiceRewards={{id=27734,qty=1},{id=27735,qty=1},{id=27733,qty=1},{id=27730,qty=1}}} end
if not DB[9732] then DB[9732]={id=9732,zoneId=3521,name="Return to the Marsh",level=63,minLevel=60,giver="Amythiel Mistwalker",giverType="NPC",giverId=16885,ender="Ysiel Windsinger",enderType="NPC",enderId=17841,poiX=-315,poiY=4711,wowhead="https://www.wowhead.com/wotlk/quest=9732",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Return to Ysiel and let her know that help will be extended to her as soon as it is possible.$B$BAffairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.  ",logDesc="Return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.",choiceRewards={{id=25524,qty=1},{id=25523,qty=1},{id=25522,qty=1}}} end
if not DB[9733] then DB[9733]={id=9733,zoneId=3521,name="Warning the Cenarion Circle",level=64,minLevel=61,rewardNextId=9734,wowhead="https://www.wowhead.com/wotlk/quest=9733",image="assets/images/quests/placeholder.png",xpDiff=3,money=16000,desc="The Cenarion Expedition has become a large organization with a good degree of autonomy.  These events are important enough that we need to warn the Cenarion Circle.$B$BDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.",logDesc="Speak to Mahuram Stouthoof at Thrallmar in Hellfire Peninsula."} end
if not DB[9734] then DB[9734]={id=9734,zoneId=3521,name="Return to the Marsh",level=63,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=9734",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Return to Ysiel and let her know that help will be extended to her as soon as it is possible.$B$BAffairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.  ",logDesc="Return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.",choiceRewards={{id=25524,qty=1},{id=25523,qty=1},{id=25522,qty=1}}} end
if not DB[9735] then DB[9735]={id=9735,zoneId=-141,name="True Masters of the Light",level=-1,minLevel=60,giver="Lord Solanar Bloodwrath",giverType="NPC",giverId=25223,ender="Lord Solanar Bloodwrath",enderType="NPC",enderId=25223,rewardNextId=9736,poiX=9841,poiY=-7516,wowhead="https://www.wowhead.com/wotlk/quest=9735",image="assets/images/quests/placeholder.png",xpDiff=6,desc="A Blood Knight master possesses incredible skill at wielding and weaving the Light in a way that other so-called 'paladins' can never comprehend. It doesn't stop them from despising us for unleashing the Light's true potential.$B$BWe must send them a message and show them that we are not to be trifled with. What I have in mind will be neither brief nor easy, but if you are committed, the first step will be to infiltrate the library wing of the Tyr's Hand Abbey and procure a vial of Tyr's Hand holy water.",logDesc="Lord Solanar Bloodwrath in Silvermoon City wants you to bring him a vial of Tyr's Hand Holy Water."} end
if not DB[9736] then DB[9736]={id=9736,zoneId=-141,name="True Masters of the Light",level=-1,minLevel=60,giver="Lord Solanar Bloodwrath",giverType="NPC",giverId=25223,ender="Lord Solanar Bloodwrath",enderType="NPC",enderId=25223,rewardNextId=9737,poiX=9841,poiY=-7516,wowhead="https://www.wowhead.com/wotlk/quest=9736",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Now that we have the water, we're going to need a number of reagents in precise quantities. Some of these substances are rare and expensive, $N, but I have located sources for two.$B$BYou should be able to purchase some arcane catalyst from Zalle, the reagent vendor in one of the shops on the plaza near the Dead Scar. Darlia, the poison merchant near the rogue trainers on Murder Row, stocks crepuscular powder.$B$BTo complete my mixture, I'll also need an azerothian diamond and a pristine black diamond.",logDesc="Lord Solanar Bloodwrath in Silvermoon City wants you to bring him 1 Arcane Catalyst, 1 Crepuscular Powder, 1 Azerothian Diamond, and 1 Pristine Black Diamond."} end
if not DB[9737] then DB[9737]={id=9737,zoneId=-141,name="True Masters of the Light",level=-1,minLevel=60,giver="Lord Solanar Bloodwrath",giverType="NPC",giverId=25223,ender="Lord Solanar Bloodwrath",enderType="NPC",enderId=25223,poiX=9841,poiY=-7516,wowhead="https://www.wowhead.com/wotlk/quest=9737",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Ours is the true way of utilizing the Light, $N. To show others that would call themselves 'paladins' the folly of their ways, I intend to send an unmistakable message.$B$BThe Alonsus Chapel, where the Order of the Silver Hand was founded, seems immune to the destruction of Stratholme. The chapel's eternal flame affords it the Light's protection, but when you use this mixture to extinguish the flame, that protection will be no more. It will burn, and our dominion over the Light will be proven to the world.",logDesc="Use the Extinguishing Mixture near the eternal flame in the Alonsus Chapel to remove the Light's protection. Be prepared to fight anyone who may attempt to defend the chapel.",rewards={{id=25549,qty=1}}} end
if not DB[9738] then DB[9738]={id=9738,zoneId=3905,name="Lost in Action",level=65,minLevel=62,giver="Watcher Jhang",giverType="NPC",giverId=17884,ender="Watcher Jhang",enderType="NPC",enderId=17884,poiX=729,poiY=6846,wowhead="https://www.wowhead.com/wotlk/quest=9738",image="assets/images/quests/placeholder.png",xpDiff=8,desc="You have to help me!  We were sent here by Ysiel to investigate the mystery of the steam pumps and why they're being used to drain the water from the marsh.  But my friends split up and went on recklessly without me.$B$BThose four can be such jerks sometimes, but I love them anyway.$B$BThat is why I need you to discover what became of them, though I fear the worst.  Seek them in both the Slave Pens and the Underbog.$B$BThank you, $c.",logDesc="Discover what happened to Earthbinder Rayge, Naturalist Bite, Weeder Greenthumb, and Windcaller Claw.  Then, return to Watcher Jhang at Coilfang Reservoir in Zangarmarsh.",choiceRewards={{id=25541,qty=1},{id=28029,qty=1},{id=25540,qty=1}}} end
if not DB[9739] then DB[9739]={id=9739,zoneId=3521,name="The Sporelings' Plight",level=63,minLevel=61,giver="Fahssn",giverType="NPC",giverId=17923,ender="Fahssn",enderType="NPC",enderId=17923,poiX=-205,poiY=8517,wowhead="https://www.wowhead.com/wotlk/quest=9739",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You there!  You must help us!$B$BThe fungal giants are devouring all of our spore sacs!  You must do something, or we'll lose our young!$B$BThe spore sacs start out large and become smaller as the air inside them is depleted.  Look for the small, mature spore sacs and save as many of them as you can!",logDesc="Fahssn at the Spawning Glen wants you to collect 10 Mature Spore Sacs."} end
if not DB[9740] then DB[9740]={id=9740,zoneId=3525,name="The Sun Gate",level=18,minLevel=16,giver="Vindicator Aesom",giverType="NPC",giverId=17844,ender="Vindicator Aesom",enderType="NPC",enderId=17844,poiX=-1963,poiY=-11887,wowhead="https://www.wowhead.com/wotlk/quest=9740",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Thanks to you and the work you did, my scouts were able to find the sun gate. The elves keep the portal location mobile so that they can move it at a moment's notice. That's why the site you investigated was empty.$B$BThe strength of such a system is also its greatest weakness. The sun gate is stabilized by portal controllers. If we can take down the controllers, the portal will be ours to destroy. The current sun gate location can be found west of here, south of the Vector Coil. Find it and destroy it!",logDesc="Vindicator Aesom at Blood Watch wants you to destroy the Sun Gate."} end
if not DB[9741] then DB[9741]={id=9741,zoneId=3525,name="Critters of the Void",level=18,minLevel=16,giver="Scout Loryi",giverType="NPC",giverId=17926,ender="Vindicator Aesom",enderType="NPC",enderId=17844,poiX=-1756,poiY=-11061,wowhead="https://www.wowhead.com/wotlk/quest=9741",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Aesom sent my squad out on a reconnaissance mission to search for the sun gate a few days ago. Needless to say, we found it...$B$B<Loryi points at Jorli.>$B$BWhatever those fool elves are transporting through that portal is causing void energy to be released. The area is teaming with void critters. $B$BWe must destroy them before they have a chance to grow into void anomalies. You'll find the source of the creatures southwest of here, near the sun gate. Kill them and report back to Aesom when you're done.",logDesc="Kill 12 Void Critters and report to Vindicator Aesom at Blood Watch.$B"} end
if not DB[9742] then DB[9742]={id=9742,zoneId=3521,name="More Spore Sacs",level=63,minLevel=61,giver="Fahssn",giverType="NPC",giverId=17923,ender="Fahssn",enderType="NPC",enderId=17923,poiX=-205,poiY=8517,wowhead="https://www.wowhead.com/wotlk/quest=9742",image="assets/images/quests/placeholder.png"} end
if not DB[9743] then DB[9743]={id=9743,zoneId=3521,name="Natural Enemies",level=64,minLevel=61,giver="Fahssn",giverType="NPC",giverId=17923,ender="Fahssn",enderType="NPC",enderId=17923,poiX=-205,poiY=8517,wowhead="https://www.wowhead.com/wotlk/quest=9743",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Us sporelings and the bog lords have never gotten along well.  In the past, we've managed to keep them at bay with spears and stones.  Lately they seem to have become more aggressive... or more desperate.  They do not fear us or our weapons.$B$BYou are much scarier and better armed than us.  If you were to fight the boglords for us, we'd be forever in your debt!  Bring me their tendrils so I know how many you've killed.",logDesc="Fahssn at the Spawning Glen in Zangarmarsh wants you to bring him 6 Bog Lord Tendrils."} end
if not DB[9744] then DB[9744]={id=9744,zoneId=3521,name="More Tendrils!",level=64,minLevel=61,giver="Fahssn",giverType="NPC",giverId=17923,ender="Fahssn",enderType="NPC",enderId=17923,poiX=-205,poiY=8517,wowhead="https://www.wowhead.com/wotlk/quest=9744",image="assets/images/quests/placeholder.png"} end
if not DB[9745] then DB[9745]={id=9745,zoneId=-141,name="<DEPRECATED>Suppressing the Flame",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=9745",image="assets/images/quests/placeholder.png",rewards={{id=24287,qty=1}}} end
if not DB[9746] then DB[9746]={id=9746,zoneId=3525,name="Limits of Physical Exhaustion",level=18,minLevel=16,giver="Vindicator Aesom",giverType="NPC",giverId=17844,ender="Vindicator Aesom",enderType="NPC",enderId=17844,rewardNextId=9740,poiX=-1963,poiY=-11887,wowhead="https://www.wowhead.com/wotlk/quest=9746",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Victory is close at hand, $N. With the discovery of the sun gate, it won't be long until their supply lines are completely closed off. Now is the time to strike at their numbers.$B$BTo the west you will find numerous Sunhawk camps. The Sunhawk pyromancers and defenders occupy the vast majority of the area. Find them, kill them and return to me.",logDesc="Vindicator Aesom at Blood Watch wants you to slay 10 Sunhawk Pyromancers and 10 Sunhawk Defenders.$B"} end
if not DB[9747] then DB[9747]={id=9747,zoneId=3521,name="The Umbrafen Tribe",level=62,minLevel=60,giver="Ikeyen",giverType="NPC",giverId=17956,ender="Ikeyen",enderType="NPC",enderId=17956,rewardNextId=9788,poiX=-215,poiY=5433,wowhead="https://www.wowhead.com/wotlk/quest=9747",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="The naga are terrible, yes.  But even more terrible are the traitor tribes of Broken and Lost Ones that helped them!$B$BThe worst of all are the Lost Ones of the Umbrafen tribe; they use dark magic to trap and enslave others. They're especially cruel to escaped slaves and would slit my throat if I left the refuge even for a day.$B$BTravel to Umbrafen Village south of here and kill them and their leader, Kataru.  Until then I will fear for my life every single day.",logDesc="Ikeyen at the Cenarion Refuge wants you to travel to Umbrafen Village and slay Kataru, 8 Umbrafen Seers, 6 Umbrafen Witchdoctors and 6 Umbrafen Oracles."} end
if not DB[9748] then DB[9748]={id=9748,zoneId=3525,name="Don't Drink the Water",level=18,minLevel=16,giver="Vindicator Aesom",giverType="NPC",giverId=17844,ender="Vindicator Aesom",enderType="NPC",enderId=17844,rewardNextId=9746,poiX=-1963,poiY=-11887,wowhead="https://www.wowhead.com/wotlk/quest=9748",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Our shaman claim that the elements of water have become greatly agitated by the pollution of the water source. We know that the Exodar's power core is lodged into the mountain to the west. It must be leaking volatile fluids into the water supply! I need you to get me more information.$B$B<Aesom points to a flask and nods.>$B$BYou are to take this flask and follow the beach north until you reach the area where the rivers of Bloodmyst drain into the ocean. Take a sample from that location and return to me.",logDesc="Vindicator Aesom at Blood Watch wants you to use the Water Sample Flask to get a Bloodmyst Water Sample."} end
if not DB[9749] then DB[9749]={id=9749,zoneId=3525,name="They're Alive! Maybe...",level=19,minLevel=16,wowhead="https://www.wowhead.com/wotlk/quest=9749",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It was a bloody mess, $N. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons.$B$BAfter we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD!$B$BI managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand?$B$BDestroy those cocoons! Hopefully some of our team is still alive!$B",logDesc="Researcher Cornelius has asked that you free 5 Expedition Researchers."} end
if not DB[9750] then DB[9750]={id=9750,zoneId=3525,name="UNUSED Urgent Delivery",level=18,minLevel=15,wowhead="https://www.wowhead.com/wotlk/quest=9750",image="assets/images/quests/placeholder.png"} end
if not DB[9751] then DB[9751]={id=9751,zoneId=3525,name="The Bloodcurse Legacy",level=18,minLevel=15,giver="Admiral Odesyus",giverType="NPC",giverId=17240,ender="Captain Edward Hanes",enderType="NPC",enderId=17712,rewardNextId=9674,poiX=-4700,poiY=-12415,wowhead="https://www.wowhead.com/wotlk/quest=9751",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Last night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago.$B$BThis apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of Blood Watch?$B",logDesc="Admiral Odesyus has asked that you find and speak with Captain Edward Hanes."} end
if not DB[9752] then DB[9752]={id=9752,zoneId=3521,name="Escape from Umbrafen",level=63,minLevel=60,giver="Kayra Longmane",giverType="NPC",giverId=17969,ender="Ysiel Windsinger",enderType="NPC",enderId=17841,poiX=-932,poiY=5284,wowhead="https://www.wowhead.com/wotlk/quest=9752",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="You must help me get out of here!$B$BI was gathering herbs nearby when a handful of these little savages abducted me.  I tried to fight them off, but there were too many of them.$B$BHelp me return to the Cenarion Refuge and away from these cruel wretches and their vile magic!",logDesc="Escort Kayra Longmane to the Cenarion Refuge in Zangarmarsh.  Report to Ysiel Windsinger when you've completed this task.",choiceRewards={{id=25518,qty=1},{id=25517,qty=1},{id=25519,qty=1}}} end
if not DB[9753] then DB[9753]={id=9753,zoneId=3525,name="What We Know...",level=20,minLevel=18,giver="Vindicator Aesom",giverType="NPC",giverId=17844,ender="Exarch Admetius",enderType="NPC",enderId=17658,rewardNextId=9756,poiX=-1963,poiY=-11887,wowhead="https://www.wowhead.com/wotlk/quest=9753",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We've learned much of our enemies in recent days. The blood elves are led by a being known as Sironas and plot to destroy us. Ultimately, they seek to enslave O'ros and regain control of the Exodar.$B$BLight be praised, we have stopped their supply line by destroying the sun gate. Unfortunately, they continue to use the contaminant of the Vector Coil to poison the land, using the mutagenic properties of the fallout to their advantage.$B$BWith this knowledge, Admetius has devised a plan. Seek him out.",logDesc="Speak to Exarch Admetius at Blood Watch."} end
if not DB[9756] then DB[9756]={id=9756,zoneId=3525,name="What We Don't Know...",level=20,minLevel=18,giver="Exarch Admetius",giverType="NPC",giverId=17658,ender="Exarch Admetius",enderType="NPC",enderId=17658,rewardNextId=9760,poiX=-1916,poiY=-11794,wowhead="https://www.wowhead.com/wotlk/quest=9756",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Our attempts at interrogation have failed miserably, $N. Torture is - of course - out of the question. What we need is a draenei on the inside.$B$BI can cast a spell upon you that would make you appear blood elf and adjust your language. Through subterfuge, we may be able to get the information we need out of the captured agent.$B$BUnder this guise, I want you to get whatever information you can out of the prisoner.$B$BAnd $N, do not leave Blood Watch while disguised as the spell will fail.",logDesc="Speak to a Captured Sunhawk Agent at Blood Watch and recover Sunhawk Information. Return to Exarch Admetius when the task is complete."} end
if not DB[9757] then DB[9757]={id=9757,zoneId=-261,name="Seek Huntress Kella Nightbow",level=-1,minLevel=10,giver="Thorgas Grimson",giverType="NPC",giverId=895,ender="Huntress Kella Nightbow",enderType="NPC",enderId=17614,rewardNextId=9591,poiX=-6092,poiY=365,wowhead="https://www.wowhead.com/wotlk/quest=9757",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Huntress Kella Nightbow seeks the audience of all eligible hunters.  She is the one to teach you the skill of taming wild beasts, a lesson you should learn above all else at this point in your training.$b$bKella can be found near Valaar's Berth, the docks west of the Exodar.",logDesc="Speak with Huntress Kella Nightbow near Valaar's Berth."} end
if not DB[9758] then DB[9758]={id=9758,zoneId=3433,name="Return to Arcanist Vandril",level=10,minLevel=9,giver="High Executor Mavren",giverType="NPC",giverId=16252,ender="Arcanist Vandril",enderType="NPC",enderId=16197,rewardNextId=9138,poiX=7553,poiY=-6761,wowhead="https://www.wowhead.com/wotlk/quest=9758",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Now my friend, if you would be so kind as to return to Arcanist Vandril, I know that he is very anxious to send you out on your first mission here in the Ghostlands.$B$BWe're counting on you, $N.  Don't let us down.",logDesc="Return to Arcanist Vandril at Tranquillien in the Ghostlands."} end
if not DB[9759] then DB[9759]={id=9759,zoneId=3525,name="Ending Their World",level=20,minLevel=18,giver="Demolitionist Legoso",giverType="NPC",giverId=17982,ender="Exarch Admetius",enderType="NPC",enderId=17658,poiX=-1773,poiY=-11081,wowhead="https://www.wowhead.com/wotlk/quest=9759",image="assets/images/quests/placeholder.png",xpDiff=7,money=3500,desc="Don't accept this assignment if you value your life. You see that gigantic power core jutting out of the mountain side over yonder? Whoever takes on this burden will need to fight their way through that mountain, battling an army of Sunhawks while protecting me as I rig the core up for demolition. Sironas the eredar is somewhere up there as well.$B$BI won't think less of you if you just walk away, $N.$B$BBut maybe you're the one - the one to destroy the Vector Coil and take down Sironas. Well, are you?",logDesc="Follow and protect Demolitionist Legoso as he attempts to destroy the Vector Coil and slay Sironas. Return to Exarch Admetius at Blood Watch should you complete the mission.",choiceRewards={{id=24352,qty=1},{id=24353,qty=1},{id=24351,qty=1},{id=24354,qty=1}}} end
if not DB[9760] then DB[9760]={id=9760,zoneId=3525,name="Vindicator's Rest",level=20,minLevel=18,giver="Exarch Admetius",giverType="NPC",giverId=17658,ender="Vindicator Corin",enderType="NPC",enderId=17986,rewardNextId=9761,poiX=-1916,poiY=-11794,wowhead="https://www.wowhead.com/wotlk/quest=9760",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I would not ask you to single-handedly bear the burden of destroying the Vector Coil and slaying Sironas, $N; however, I believe that you can be of some help in clearing the way for others that might take on such a dangerous assignment.$B$BTake the road going north out of Blood Watch and follow it until you get to the fork. Once there, take the left road and follow it until you see Vindicator's Rest - it will be slightly west of the road itself. Corin will be waiting for you.",logDesc="Speak with Vindicator Corin at Vindicator's Rest on Bloodmyst Isle.$B"} end
if not DB[9761] then DB[9761]={id=9761,zoneId=3525,name="Clearing the Way",level=20,minLevel=18,giver="Vindicator Corin",giverType="NPC",giverId=17986,ender="Vindicator Corin",enderType="NPC",enderId=17986,poiX=-1777,poiY=-11078,wowhead="https://www.wowhead.com/wotlk/quest=9761",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Only the most battle hardened, noble and positively fearless of draenei will submit to Legoso's mission. The exarch will not order any agent of the Hand to take on the task of destroying the Vector Coil and dispatching Sironas. He refuses to send any draenei to their death - which is what the mission is: suicide...$B$B<Corin sighs.>$B$BMy job is to soften up the Sunhawk defenses. You are to slay Sunhawks near the Vector Coil and keep the path clear for our champion - whoever that may be.",logDesc="Vindicator Corin at Vindicator's Rest wants you to slay 8 Sunhawk Saboteurs and 8 Sunhawk Agents.$B",choiceRewards={{id=26009,qty=1},{id=26023,qty=1},{id=26035,qty=1}}} end
if not DB[9762] then DB[9762]={id=9762,zoneId=3525,name="The Unwritten Prophecy",level=20,minLevel=18,giver="3",giverType="NPC",giverId=17468,ender="3",enderType="NPC",enderId=17468,poiX=-3994,poiY=-11414,wowhead="https://www.wowhead.com/wotlk/quest=9762",image="assets/images/quests/placeholder.png",rewards={{id=24344,qty=1}},choiceRewards={{id=24349,qty=1},{id=24350,qty=1}}} end
if not DB[9763] then DB[9763]={id=9763,zoneId=3715,name="The Warlord's Hideout",level=70,minLevel=67,giver="Watcher Jhang",giverType="NPC",giverId=17884,ender="Watcher Jhang",enderType="NPC",enderId=17884,poiX=729,poiY=6846,wowhead="https://www.wowhead.com/wotlk/quest=9763",image="assets/images/quests/placeholder.png",xpDiff=8,money=132000,desc="There are benefits to hiding very, very quietly at the entrance of your enemy's hideout.$B$BJust hours ago I saw a group of naga go through the stone archway on the second tunnel from the left.  I'm not well versed in their language, yet I clearly understood one word: Kalithresh.$B$BThat must be the entrance to the steam vaults, where Warlord Kalithresh has been commanding his troops from.  You must find him and stop him.  I am too weak to be of any assistance.",logDesc="Watcher Jhang wants you to find and slay Warlord Kalithresh inside Coilfang Reservoir.",choiceRewards={{id=28183,qty=1},{id=28182,qty=1},{id=28181,qty=1},{id=28180,qty=1}}} end
if not DB[9764] then DB[9764]={id=9764,zoneId=3715,name="Orders from Lady Vashj",level=70,minLevel=67,ender="Ysiel Windsinger",enderType="NPC",enderId=17841,rewardNextId=9765,wowhead="https://www.wowhead.com/wotlk/quest=9764",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This letter contains detailed orders to the Coilfang naga operating the steam vaults.  It warns of the arrival of Cenarion druids into the region and orders them to be slain on sight.  The rate of water redirection from other lakes into Coilfang Reservoir is to be doubled.  The orders bear the seal of the infamous Lady Vashj.$B$BThis letter would be of great interest to the druids of the Cenarion Expedition.  Take it to their leader, Ysiel Windsinger.",logDesc="Deliver the Orders from Lady Vashj to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh."} end
if not DB[9765] then DB[9765]={id=9765,zoneId=3715,name="Preparing for War",level=70,minLevel=67,giver="Ysiel Windsinger",giverType="NPC",giverId=17841,ender="Ysiel Windsinger",enderType="NPC",enderId=17841,poiX=-143,poiY=5534,wowhead="https://www.wowhead.com/wotlk/quest=9765",image="assets/images/quests/placeholder.png",xpDiff=8,desc="The Cenarion Expedition began as a peaceful venture, yet we now face the prospect of all out war with the naga.$B$BWe have many among us who are willing to fight but are ill equipped.  Bring me the naga's own weapons so that we may reforge them into glaives and arrowheads.$B$BOnly the best armaments will have materials useful to us, $N.  You will have to seek out the naga of Coilfang Reservoir.",logDesc="Obtain Coilfang Armaments from naga at Coilfang Reservoir and return them to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh."} end
if not DB[9766] then DB[9766]={id=9766,zoneId=3607,name="Coilfang Armaments",level=70,minLevel=67,giver="Ysiel Windsinger",giverType="NPC",giverId=17841,ender="Ysiel Windsinger",enderType="NPC",enderId=17841,poiX=-143,poiY=5534,wowhead="https://www.wowhead.com/wotlk/quest=9766",image="assets/images/quests/placeholder.png"} end
if not DB[9767] then DB[9767]={id=9767,zoneId=3607,name="Know Your Enemy",level=70,minLevel=67,wowhead="https://www.wowhead.com/wotlk/quest=9767",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Defeating an enemy requires more than superior power or numbers.  Victory often hinges on knowledge of an opponent's weaknesses, the anticipation of their plans or the recognition of a behavior pattern.$B$BWe know much about the naga, yet much of their magical practices remain foreign to us.$B$BI seek to learn of the Hydromancy used by the naga of Coilfang Reservoir.  Bring me one of their spellbooks so I may learn more about it.",logDesc="Obtain a Coilfang Spellbook from the naga inside of Coilfang Reservoir and bring it to Ashyen at the Cenarion Refuge in Zangarmarsh."} end
if not DB[9768] then DB[9768]={id=9768,zoneId=3607,name="Coilfang Spellbooks",level=70,minLevel=67,wowhead="https://www.wowhead.com/wotlk/quest=9768",image="assets/images/quests/placeholder.png"} end
if not DB[9769] then DB[9769]={id=9769,zoneId=3521,name="There's No Explanation for Fashion",level=62,minLevel=60,giver="Magasha",giverType="NPC",giverId=18016,ender="Magasha",enderType="NPC",enderId=18016,poiX=114,poiY=5234,wowhead="https://www.wowhead.com/wotlk/quest=9769",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="<Magasha chuckles softly to herself.>$B$BI bet if they knew they were wearing bug parts, the fashion trend would end very quickly.$B$BWe first started killing the bugs 'round here 'cause they were getting in the way of our construction. Some enterprising merchant stops here, spends the night, and next thing you know he's buyin' up all the bug wings we have!$B$BSays he makes clothes out of 'em. I be stickin' to my armor, thanks. But if you gather the wings of any of the fireflies, I'll gladly buy 'em.",logDesc="Bring 8 Diaphanous Wings from any species of Zangarmarsh fireflies to Magasha in Swamprat Post."} end
if not DB[9770] then DB[9770]={id=9770,zoneId=3521,name="Menacing Marshfangs",level=62,minLevel=60,giver="Reavij",giverType="NPC",giverId=18012,ender="Reavij",enderType="NPC",enderId=18012,rewardNextId=9898,poiX=124,poiY=5204,wowhead="https://www.wowhead.com/wotlk/quest=9770",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Sometimes I wish Denjai had sent a shaman with us, or at least given us a totem to keep the marshfang rippers at bay.$B$BThe whole place is crawling with the pests! It's just not right. Shouldn't something be eating these despicable things?$B$BWe've all been taking turns playing exterminator. You showed up at just the right time, $N. Congratulations! Now get out there and mop up some marshfangs!",logDesc="Reavij at Swamprat Post wants you to kill 10 Marshfang Rippers."} end
if not DB[9771] then DB[9771]={id=9771,zoneId=3521,name="Searching for Scout Jyoba",level=62,minLevel=59,giver="Zurai",giverType="NPC",giverId=18011,ender="Scout Jyoba",enderType="NPC",enderId=18035,rewardNextId=9772,poiX=100,poiY=5188,wowhead="https://www.wowhead.com/wotlk/quest=9771",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now that you're familiar with the terrain, I'd like to ask your help with something else. The Dead Mire, we've taken to calling the area to the northwest, is an eerie place. No one has ever reported seeing anything alive there, but they didn't stay for very long, either.$B$BScout Jyoba volunteered to investigate the area and report on his findings. He left the post three days ago and hasn't returned. It's not like him to be gone that long without sending some kind of report. Will you search for him, $N?",logDesc="Search for Scout Jyoba at the Dead Mire in Zangarmarsh."} end
if not DB[9772] then DB[9772]={id=9772,zoneId=3521,name="Jyoba's Report",level=62,minLevel=60,giver="Scout Jyoba",giverType="NPC",giverId=18035,ender="Zurai",enderType="NPC",enderId=18011,poiX=719,poiY=5416,wowhead="https://www.wowhead.com/wotlk/quest=9772",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Flecks of withered fungus dot the body of Scout Jyoba. Whatever killed him must've been made of the same dying fungus as the giant wilting mushrooms of the Dead Mire. Perhaps one of the withered giants caught him by surprise as he sat writing his report.$B$BWithout the text of the report, it's nearly impossible to tell what the scout discovered. If the report can be found, it should be returned to Zurai.",logDesc="Retrieve Scout Jyoba's Report from the Withered Giants and return it to Zurai at Swamprat Post.",choiceRewards={{id=25600,qty=1},{id=25601,qty=1},{id=25602,qty=1},{id=31768,qty=1}}} end
if not DB[9773] then DB[9773]={id=9773,zoneId=3521,name="No More Mushrooms!",level=61,minLevel=58,giver="Magasha",giverType="NPC",giverId=18016,ender="Magasha",enderType="NPC",enderId=18016,poiX=114,poiY=5234,wowhead="https://www.wowhead.com/wotlk/quest=9773",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Mushroom soup, mushroom stew, mushroom sauce!$B$BMushroom, mushroom, mushroom! It's all there is to eat around here. If you say you're hungry, the cook hands you an axe and tells you to go chop down your dinner!$B$BWell, I'm tired of mushrooms. I've seen fish in the lakes around here. Sure, they look like a nasty piece of work, but they've got to be better than mushrooms!$B$BHow much will it cost me to hire you to bring me my first decent meal in weeks?",logDesc="Gather 8 Eel Filets from Umbrafen Eels and bring them to Magasha at Swamprat Post."} end
if not DB[9774] then DB[9774]={id=9774,zoneId=3521,name="Thick Hydra Scales",level=62,minLevel=59,giver="Zurai",giverType="NPC",giverId=18011,ender="Zurai",enderType="NPC",enderId=18011,rewardNextId=9771,poiX=100,poiY=5188,wowhead="https://www.wowhead.com/wotlk/quest=9774",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Reavij was wise to bring leather armor. This swamp will render my mail useless before long.$B$BI've been replacing the scales bit by bit as I'm able. The hydra in the marsh have thick, protective scales that stand up well to the dampness of their home.$B$BFinding suitable ones is a tedious process, though. All too often, the best scales are torn or worn too thin for use in armor. Bring me any good ones that you might get from the hydra in the larger lakes.",logDesc="Zurai at Swamprat Post wants you to bring him 12 Thick Hydra Scales."} end
if not DB[9775] then DB[9775]={id=9775,zoneId=3521,name="Report to Shadow Hunter Denjai",level=62,minLevel=62,giver="Zurai",giverType="NPC",giverId=18011,ender="Shadow Hunter Denjai",enderType="NPC",enderId=18013,poiX=100,poiY=5188,wowhead="https://www.wowhead.com/wotlk/quest=9775",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Shadow Hunter Denjai will no doubt expect to receive a report about my progress in establishing our outpost. I've prepared a short summary of what we've accomplished here already, but with the loss of Scout Jyoba, I can't spare a runner to take the report to Denjai's base of Zabra'jin to the west.$B$BIf you're headed that way, would you mind bringing this to him? Shadow Hunter Denjai can be a little intimidating at first, but once you get used to him, he's not so bad.",logDesc="Bring Zurai's Report to Shadow Hunter Denjai at Zabra'jin in Zangarmarsh."} end
if not DB[9776] then DB[9776]={id=9776,zoneId=3521,name="The Orebor Harborage",level=64,minLevel=62,giver="Anchorite Ahuurn",giverType="NPC",giverId=18003,ender="Ikuti",enderType="NPC",enderId=18008,poiX=280,poiY=6047,wowhead="https://www.wowhead.com/wotlk/quest=9776",image="assets/images/quests/placeholder.png",xpDiff=2,desc="As you know, many of Telredor's inhabitants are refugees from the war that decimated the draenei. It is my goal to maintain Telredor as a safe haven for all of our allies in this struggle. There are some who desire to join us, but feel they are not yet ready.$B$BWe owe them whatever help we can provide, $N. A group of Broken under the leadership of Ikuti have taken shelter in the ruins of an old temple to the northwest of Serpent Lake. Seek them out and extend your hand in friendship to them.",logDesc="Speak to Ikuti at the Orebor Harborage in Zangarmarsh."} end
if not DB[9777] then DB[9777]={id=9777,zoneId=3521,name="Fulgor Spores",level=62,minLevel=60,giver="Ruam",giverType="NPC",giverId=18007,ender="Ruam",enderType="NPC",enderId=18007,poiX=302,poiY=6025,wowhead="https://www.wowhead.com/wotlk/quest=9777",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="There is little in this swamp that will burn, $r, so we must resort to other means for lighting Telredor. Many of the creatures and plants in the marsh emit a soft glow.$B$BIt's difficult and cruel to confine the glowing creatures, so we've turned to a species of mushroom for our light source.$B$BWe pick and cultivate the fulgor mushroom here, but our needs require us to gather new crops occasionally. The small green mushrooms often grow at the base of larger ones near Telredor.",logDesc="Bring 6 Fulgor Spores to Ruam at Telredor."} end
if not DB[9778] then DB[9778]={id=9778,zoneId=3521,name="Warden Hamoot",level=64,minLevel=61,giver="Ysiel Windsinger",giverType="NPC",giverId=17841,ender="Warden Hamoot",enderType="NPC",enderId=17858,rewardNextId=9728,poiX=-143,poiY=5534,wowhead="https://www.wowhead.com/wotlk/quest=9778",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Before you leave Cenarion Refuge, make sure you speak with Warden Hamoot.  He's in charge of the expedition's security.$B$BHe would never forgive me if I didn't send a seasoned adventurer like you his way.",logDesc="Report to Warden Hamoot at the Cenarion Refuge in Zangarmarsh."} end
if not DB[9779] then DB[9779]={id=9779,zoneId=3525,name="Intercepting the Message",level=16,minLevel=14,giver="Vindicator Boros",giverType="NPC",giverId=17684,ender="Vindicator Boros",enderType="NPC",enderId=17684,rewardNextId=9696,poiX=-1960,poiY=-11883,wowhead="https://www.wowhead.com/wotlk/quest=9779",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is good to see you again, $N. I have a quandary that you might be able to solve.$B$BOur agents situated behind Sunhawk lines have reported seeing Sunhawk soldiers parsing an unusual document.$B$BUnfortunately, we have been unsuccessful in acquiring a copy of the document for ourselves. I need you to go out in the field and try to recover the document. I am certain that if you apply enough pressure, a Sunhawk agent will turn over the information we seek. I leave the use of force to your discretion.",logDesc="Kill Sunhawk elves until you find the Sunhawk Missive, then return it to Vindicator Boros at Blood Watch."} end
if not DB[9780] then DB[9780]={id=9780,zoneId=3521,name="Umbrafen Eel Filets",level=62,minLevel=60,giver="Noraani",giverType="NPC",giverId=18006,ender="Noraani",enderType="NPC",enderId=18006,poiX=331,poiY=6075,wowhead="https://www.wowhead.com/wotlk/quest=9780",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="It's good to see another fresh face here. When Haalrun and I first came to Telredor, we were the only outsiders, but that seems like a lifetime ago.$B$BStill, we try to welcome newcomers and ensure that there's always enough food and supplies. We can never fully repay the kindness of the Telredor anchorites, but we can follow their example and extend it to others.$B$BIf you would like to help, the nearby lakes are populated with a fish called the Umbrafen eel, whose meat is a staple of our diet.",logDesc="Noraani at Telredor wants you to bring her 8 Eel Filets."} end
if not DB[9781] then DB[9781]={id=9781,zoneId=3521,name="Too Many Mouths to Feed",level=62,minLevel=60,giver="Haalrun",giverType="NPC",giverId=18005,ender="Haalrun",enderType="NPC",enderId=18005,rewardNextId=9790,poiX=329,poiY=6066,wowhead="https://www.wowhead.com/wotlk/quest=9781",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="On my last hunting trip, I caught sight of a new outpost being built by a group of trolls. No doubt they've begun hunting these lands, too.$B$BIf they establish a permanent presence out here, the competition for food will be fierce. We cannot take direct action against them without provocation, but we can remove some of the natural competition for food.$B$BFor each mire hydra you kill, that's three fewer mouths to feed!",logDesc="Kill 10 Mire Hydra and return to Haalrun at Telredor."} end
if not DB[9782] then DB[9782]={id=9782,zoneId=3521,name="The Dead Mire",level=62,minLevel=60,giver="Vindicator Idaar",giverType="NPC",giverId=18004,ender="Vindicator Idaar",enderType="NPC",enderId=18004,rewardNextId=9783,poiX=257,poiY=6040,wowhead="https://www.wowhead.com/wotlk/quest=9782",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="I have lived among the anchorites of Telredor for some time, $N, and in that time I've come to know the marsh quite well. Recently, I've started to notice a disturbing change in the land to the northeast.$B$BVirtually all life there has begun to wither and die, seemingly without explanation. I have a few ideas as to what might be happening, but they are little more than speculation. If you were to bring me a sample of the soil in that area, I may be able to get to the bottom of this mystery.",logDesc="Bring a Dead Mire Soil Sample to Vindicator Idaar at Telredor."} end
if not DB[9783] then DB[9783]={id=9783,zoneId=3521,name="An Unnatural Drought",level=62,minLevel=60,giver="Vindicator Idaar",giverType="NPC",giverId=18004,ender="Vindicator Idaar",enderType="NPC",enderId=18004,poiX=257,poiY=6040,wowhead="https://www.wowhead.com/wotlk/quest=9783",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="The soil sample you brought me is nearly devoid of moisture, $N. If the soil itself is losing moisture, then the creatures that live in the Dead Mire must be suffering terribly.$B$BI've seen what happens when the region's fungal giants begin to wither and die. The pain drives them mad, causing them to attack anything in their path.$B$BThese creatures have no idea what's happening to them. They're beyond our ability to save, so the best we can do is to end their suffering.",logDesc="Vindicator Idaar at Telredor wants you to kill 12 Withered Giants.",choiceRewards={{id=25599,qty=1},{id=25598,qty=1},{id=25597,qty=1},{id=31659,qty=1}}} end
if not DB[9784] then DB[9784]={id=9784,zoneId=3521,name="Identify Plant Parts",level=64,minLevel=60,giver="Lauranna Thar'well",giverType="NPC",giverId=17909,ender="Lauranna Thar'well",enderType="NPC",enderId=17909,poiX=-216,poiY=5437,wowhead="https://www.wowhead.com/wotlk/quest=9784",image="assets/images/quests/placeholder.png",rewards={{id=24402,qty=1}}} end
if not DB[9785] then DB[9785]={id=9785,zoneId=3521,name="Blessings of the Ancients",level=64,minLevel=59,giver="Windcaller Blackhoof",giverType="NPC",giverId=18070,ender="Windcaller Blackhoof",enderType="NPC",enderId=18070,poiX=-234,poiY=5435,wowhead="https://www.wowhead.com/wotlk/quest=9785",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You've earned the trust of the Cenarion Expedition, $N.  It is time you spoke to the ancients allied with our cause, Ashyen and Keleth, and asked for their blessing.$B$BCarrying the mark of an ancient will fill you with great power.  These boons will become more powerful as your renown among us increases.$B$BGo, $N, and ask the ancients for their blessing. ",logDesc="Windcaller Blackhoof wants you to speak to the ancients Ashyen and Keleth at Cenarion Refuge and obtain their blessings."} end
if not DB[9786] then DB[9786]={id=9786,zoneId=3521,name="The Boha'mu Ruins",level=62,minLevel=60,giver="Anchorite Ahuurn",giverType="NPC",giverId=18003,ender="Anchorite Ahuurn",enderType="NPC",enderId=18003,rewardNextId=9787,poiX=280,poiY=6047,wowhead="https://www.wowhead.com/wotlk/quest=9786",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Before my people were decimated by the orcs, Telredor served as a retreat for draenei anchorites and spiritualists. A small order of anchorites and vindicators maintained a number of shrines in this region.$B$BDuring the war, we lost contact with the anchorites assigned to the shrines, particularly the Boha'mu temple to the southwest. I've heard reports that a tribe of Lost Ones has settled in the area and may even be using the ruins. Visit the Boha'mu Ruins and tell me of what you find there.",logDesc="Anchorite Ahuurn at Telredor wants you to explore the Boha'mu Ruins."} end
if not DB[9787] then DB[9787]={id=9787,zoneId=3521,name="Idols of the Feralfen",level=62,minLevel=60,giver="Anchorite Ahuurn",giverType="NPC",giverId=18003,ender="Anchorite Ahuurn",enderType="NPC",enderId=18003,rewardNextId=9801,poiX=280,poiY=6047,wowhead="https://www.wowhead.com/wotlk/quest=9787",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="From what you've told me about your observations at the Boha'mu Ruins, it seems this tribe of Lost Ones has reverted to the worship of animal spirits. Before we can approach them, we must know more of their beliefs.$B$BReturn to Feralfen Village and discreetly gather some of their idols so that I may study them. Try to avoid angering them, $N, as it may hurt our chances of making contact with them.",logDesc="Gather 6 Feralfen Idols and return them to Anchorite Ahuurn at Telredor."} end
if not DB[9788] then DB[9788]={id=9788,zoneId=3521,name="A Damp, Dark Place",level=62,minLevel=60,giver="Ikeyen",giverType="NPC",giverId=17956,ender="Ikeyen",enderType="NPC",enderId=17956,poiX=-215,poiY=5433,wowhead="https://www.wowhead.com/wotlk/quest=9788",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Soon after I escaped the Umbrafen tribe, I holed up in a cave south of their village.  Little did I know that the cave was being fought over by marsh beasts and spore men!$B$BI had to leave in a hurry and left behind a box containing my only worldly possessions.$B$BAfter managing to sneak out of Umbrafen with my belongings it was terrible irony that I would lose them so soon after.  If you're willing to bring them back to me I'll give you one of my very own personal items.  What do you say, $N?",logDesc="Look for Ikeyen's Belongings inside a cave south of Umbrafen.  Return them to Ikeyen at Cenarion Refuge in Zangarmarsh.",choiceRewards={{id=25516,qty=1},{id=25515,qty=1},{id=25514,qty=1},{id=27716,qty=1}}} end
if not DB[9789] then DB[9789]={id=9789,zoneId=3518,name="Clefthoof Mastery",level=66,minLevel=64,giver="Hemet Nesingwary",giverType="NPC",giverId=18180,ender="Hemet Nesingwary",enderType="NPC",enderId=18180,rewardNextId=9850,poiX=-1462,poiY=6344,wowhead="https://www.wowhead.com/wotlk/quest=9789",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="You want to earn a place in this safari?  You'll have to prove yourself.$B$BI don't care what you've hunted before, you haven't hunted until you hunt what we hunt here.  Start with the clefthoof if you're $g man : tough; enough.$B$BI know that I've seen them in the immediate area around the safari and also close by to the south.",logDesc="Hunt down 12 Clefthoof and return to Hemet Nesingwary at Nesingwary's Safari in Nagrand to prove yourself."} end
if not DB[9790] then DB[9790]={id=9790,zoneId=3521,name="Diaphanous Wings",level=62,minLevel=60,giver="Haalrun",giverType="NPC",giverId=18005,ender="Haalrun",enderType="NPC",enderId=18005,poiX=329,poiY=6066,wowhead="https://www.wowhead.com/wotlk/quest=9790",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Living in such a remote location has taught us to make use of everything available. Of course, you have to learn to stop thinking about where some of these materials come from first.$B$BI've found that the wings of the umbraglow stingers are very helpful for waterproofing. They're strong, thin, and flexible.$B$B<Haalrun chuckles.>$B$BI see the look on your face. Like I said, it takes time to get used to the idea. If you're going to be out and about, would you mind bringing me some of the wings?",logDesc="Haalrun at Telredor wants you to bring him 8 Diaphanous Wings from any of the firefly species in Zangarmarsh."} end
if not DB[9791] then DB[9791]={id=9791,zoneId=3521,name="Menacing Marshfangs",level=62,minLevel=60,giver="Noraani",giverType="NPC",giverId=18006,ender="Noraani",enderType="NPC",enderId=18006,rewardNextId=9780,poiX=331,poiY=6075,wowhead="https://www.wowhead.com/wotlk/quest=9791",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="During the orcs' war against my people, gatherers rarely left Telredor for fear of being attacked or captured. Now, we venture out more often, but the marsh is no less perilous.$B$BIt seems that the nether rays have grown bolder in recent months. I don't know if it has something to do with more competition for their normal prey, but they've been attacking our foraging parties on a regular basis. If we can thin their ranks in the area around Telredor, perhaps they would learn to leave us alone.",logDesc="Kill 10 Marshfang Rippers and return to Noraani at Telredor."} end
if not DB[9792] then DB[9792]={id=9792,zoneId=3521,name="A Message to Telaar",level=64,minLevel=64,giver="Ikuti",giverType="NPC",giverId=18008,ender="Nahuud",enderType="NPC",enderId=18097,poiX=1024,poiY=7366,wowhead="https://www.wowhead.com/wotlk/quest=9792",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You've been honorable in our dealings, $N, at a time when trust is hard to win among my people.$B$BA large group of my brethren have made their home in the old draenei city of Telaar in Nagrand, to the south. To reach Telaar, take the road south into Nagrand, then continue southeast until you find yourself in the cliffs east of Oshu'gun.$B$BAnyone who has aided us, as you have, would be welcome among the people of Telaar.$B$BSeek out Nahuud and tell him you have earned my trust.",logDesc="Speak with Nahuud at Telaar in Nagrand."} end
if not DB[9793] then DB[9793]={id=9793,zoneId=3521,name="The Fate of Tuurem",level=62,minLevel=62,giver="Vindicator Idaar",giverType="NPC",giverId=18004,ender="Andarl",enderType="NPC",enderId=18252,poiX=257,poiY=6040,wowhead="https://www.wowhead.com/wotlk/quest=9793",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Prophet Velen's search for allies has emboldened those draenei remaining in Outland to begin a search of their own. The Legion's war on my people drove us from our cities and temples, but they have not destroyed the traces of our civilization.$B$BTuurem, my former home in the Terokkar Forest, was one of the first cities overrun by the orcs. It's been too long since I've received news of its status. Take this letter to Andarl in the Allerian Stronghold within Terokkar and see what you can find out.",logDesc="Take Vindicator Idaar's Letter to Andarl at the Allerian Stronghold in Terokkar Forest."} end
if not DB[9794] then DB[9794]={id=9794,zoneId=3522,name="No Time for Curiosity",level=65,minLevel=64,giver="Timothy Daniels",giverType="NPC",giverId=18019,ender="Kialon Nightblade",enderType="NPC",enderId=18098,poiX=974,poiY=7403,wowhead="https://www.wowhead.com/wotlk/quest=9794",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, I have a favor to ask of you. Normally, I would do this myself, but my hands are already beyond full.$B$BI have an associate named Kialon at Sylvanaar in the Blade's Edge Mountains to the north. He's expecting to hear from me in the near future, although I suspect he won't like what I have to say.$B$BIf you would deliver my response to him, you would have my gratitude. I must insist, and this is very important, that you not attempt to read the letter. It is for Kialon's eyes alone.",logDesc="Deliver Timothy's Letter to Kialon at Sylvanaar in the Blade's Edge Mountains."} end
if not DB[9795] then DB[9795]={id=9795,zoneId=3522,name="The Ogre Threat",level=65,minLevel=64,giver="Shadow Hunter Denjai",giverType="NPC",giverId=18013,ender="Nekthar",enderType="NPC",enderId=18248,poiX=230,poiY=7930,wowhead="https://www.wowhead.com/wotlk/quest=9795",image="assets/images/quests/placeholder.png",xpDiff=2,desc="As if the naga and their allies weren't enough, the ogres are extending their reach in the marsh. They've already conquered most of the area to the northwest and there isn't much of a buffer left.$B$BFor each one we kill, several more take their place. I'm not sure how long we'll be able to hold Zabra'jin once they decide to attack. Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Nekthar know of our plight. Any help he can spare would be most welcome.",logDesc="Travel to Thunderlord Stronghold in the Blade's Edge Mountains and speak with Nekthar."} end
if not DB[9796] then DB[9796]={id=9796,zoneId=3521,name="News from Zangarmarsh",level=62,minLevel=62,giver="Zurai",giverType="NPC",giverId=18011,ender="Mokasa",enderType="NPC",enderId=18249,poiX=100,poiY=5188,wowhead="https://www.wowhead.com/wotlk/quest=9796",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Shadow Hunter Denjai isn't the only one expecting a report from me. Mokasa at Stonebreaker Hold in Terokkar is eager to hear of our progress, especially since most of her messengers travel through here.$B$BShe asked me to send word once Swamprat Post was completed. If you wouldn't mind delivering the news, I'd be very grateful. We may be up and running, but there is still much to be done.$B$BTo get to Stonebreaker Hold, follow the road south out of Zangarmarsh, into Terokkar Forest and beyond Tuurem.",logDesc="Speak with Mokasa at Stonebreaker Hold in Terokkar Forest."} end
if not DB[9797] then DB[9797]={id=9797,zoneId=3521,name="Reinforcements for Garadar",level=64,minLevel=64,giver="Messenger Gazgrigg",giverType="NPC",giverId=18091,ender="Captain Kroghan",enderType="NPC",enderId=18090,poiX=245,poiY=7866,wowhead="https://www.wowhead.com/wotlk/quest=9797",image="assets/images/quests/placeholder.png",xpDiff=2,desc="<Still catching his breath, the messenger gestures for you to sit.>$B$BThey may not survive, $r! Get to Garadar as quickly as your legs will carry you.$B$B<In response to your blank stare, the messenger elaborates.>$B$BThe home of the Mag'har, lies to the south, in Nagrand. Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake.$B$BFind our commander, Captain Kroghan, there and offer him what assistance you can. Garadar must not fall!",logDesc="Speak with Captain Kroghan at Garadar in Nagrand."} end
if not DB[9798] then DB[9798]={id=9798,zoneId=3526,name="Blood Elf Plans",level=5,minLevel=2,ender="Vindicator Aldar",enderType="NPC",enderId=16535,wowhead="https://www.wowhead.com/wotlk/quest=9798",image="assets/images/quests/placeholder.png",xpDiff=5,money=100,desc="These plans seem important.  You should take them to Vindicator Aldar at the crash site.",logDesc="Take the Blood Elf Plans to Vindicator Aldar at the Crash Site in Ammen Vale."} end
if not DB[9799] then DB[9799]={id=9799,zoneId=3526,name="Botanical Legwork",level=3,minLevel=1,giver="Apprentice Vishael",giverType="NPC",giverId=20233,ender="Apprentice Vishael",enderType="NPC",enderId=20233,poiX=-4059,poiY=-13719,wowhead="https://www.wowhead.com/wotlk/quest=9799",image="assets/images/quests/placeholder.png",xpDiff=5,money=50,desc="The Ammen Fields to the west are the primary breeding ground of the local lasher population. With the corruption of the water table from the nearby lake, Botanist Taerix is worried that the lashers will not be able to repopulate themselves once we've cleansed the lake.$B$BGo to the Ammen Fields and pick some of the corrupted flowers for me so that I might take a look at them and see what can be done. You should be able to identify them by their uncharacteristic red petals.",logDesc="Gather 3 Corrupted Flowers and return them to Apprentice Vishael at the Crash Site in Ammen Vale."} end
if not DB[9800] then DB[9800]={id=9800,zoneId=3518,name="A Rare Bean",level=65,minLevel=64,giver="Elementalist Lo'ap",giverType="NPC",giverId=18073,ender="Elementalist Lo'ap",enderType="NPC",enderId=18073,rewardNextId=9804,poiX=-783,poiY=6937,wowhead="https://www.wowhead.com/wotlk/quest=9800",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You are ill-equipped to face the restless elements of Nagrand. Before you can help the Earthen Ring, you must help yourself.$B$BTo the west you will find dung heaps left behind by the wildlife of Nagrand. You must search the dung for the digested remnants of the Nagrand caracoli. From this bean I am able to make a tablet that will aid you in your battle against the restless forces of nature.$B$BReturn to me when you have collected no less than two fists worth of caracoli... Ogre sized fists.",logDesc="Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to bring him 8 Digested Caracoli.",rewards={{id=24421,qty=5}}} end
if not DB[9801] then DB[9801]={id=9801,zoneId=3521,name="Gathering the Reagents",level=62,minLevel=60,giver="Anchorite Ahuurn",giverType="NPC",giverId=18003,ender="Anchorite Ahuurn",enderType="NPC",enderId=18003,rewardNextId=9803,poiX=280,poiY=6047,wowhead="https://www.wowhead.com/wotlk/quest=9801",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="I have a feeling that these Lost Ones may not respond well to a draenei, but would welcome an arakkoa. I can create a potion that will allow you to take on the form of an arakkoa for a short time. It requires a couple of reagents which cannot be stored and must be used within hours of being gathered.$B$BYou will need to bring me a handful of sporebat eyes and some fen strider tentacles. Both species dwell in the wilderness surrounding Telredor.",logDesc="Anchorite Ahuurn at Telredor wants you to bring him 4 Sporebat Eyes and 4 Fen Strider Tentacles."} end
if not DB[9802] then DB[9802]={id=9802,zoneId=3521,name="Plants of Zangarmarsh",level=63,minLevel=60,giver="Lauranna Thar'well",giverType="NPC",giverId=17909,ender="Lauranna Thar'well",enderType="NPC",enderId=17909,poiX=-216,poiY=5437,wowhead="https://www.wowhead.com/wotlk/quest=9802",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The lakes of Zangarmarsh are slowly being drained of their water.  We don't quite know why, but we do know that many plants species are in danger of becoming extinct.$B$BAs the expedition's cataloguer, it is my job to track and identify these plants so we can better understand what's happening to them.$B$BIf you'd like to help, bring me unidentified plant parts.  They can be picked right from the ground if you're an herbalist, and the indigenous creatures of the swamp may also carry plant parts on them.",logDesc="Bring 10 Unidentified Plant Parts to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh.",rewards={{id=24402,qty=1}}} end
if not DB[9803] then DB[9803]={id=9803,zoneId=3521,name="Messenger to the Feralfen",level=62,minLevel=60,giver="Anchorite Ahuurn",giverType="NPC",giverId=18003,ender="Anchorite Ahuurn",enderType="NPC",enderId=18003,poiX=280,poiY=6047,wowhead="https://www.wowhead.com/wotlk/quest=9803",image="assets/images/quests/placeholder.png",xpDiff=6,money=27000,desc="The time has come for us to embrace the Feralfen and teach them that the Light has not forsaken them. Take the potion I've prepared and carry it with you to the Boha'mu Ruins.$B$BOnce you arrive at the ruins, drink the potion to assume the form of one of their bird spirits. Speak with Elder Kuruti and let him know the draenei are ready to welcome his people as our long lost brothers.",logDesc="Drink Ahuurn's Elixir while standing in the Boha'mu Ruins. Speak to Elder Kuruti while you are in the form of an arakkoa.",choiceRewards={{id=25613,qty=1},{id=25614,qty=1},{id=25615,qty=1},{id=31660,qty=1}}} end
if not DB[9804] then DB[9804]={id=9804,zoneId=3518,name="Agitated Spirits of Skysong",level=65,minLevel=64,giver="Elementalist Lo'ap",giverType="NPC",giverId=18073,ender="Elementalist Lo'ap",enderType="NPC",enderId=18073,rewardNextId=9805,poiX=-783,poiY=6937,wowhead="https://www.wowhead.com/wotlk/quest=9804",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The disturbance in the ebb and flow of the waters of Nagrand has greatly agitated the water spirits of Skysong Lake. They have in turn begun sowing destruction throughout the waterways of the area.$B$BWatoosun of the Water has come to us in a vision and granted us permission to remedy the problem - so long as the source of the disturbance is also dealt with...$B$BWe will get to the source, but first you must deal with the problems immediate to the Throne. Destroy the agitated lake spirits and return to me.",logDesc="Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to destroy 8 Lake Spirits."} end
if not DB[9805] then DB[9805]={id=9805,zoneId=3518,name="Blessing of Incineratus",level=65,minLevel=64,giver="Elementalist Lo'ap",giverType="NPC",giverId=18073,ender="Elementalist Lo'ap",enderType="NPC",enderId=18073,rewardNextId=9810,poiX=-783,poiY=6937,wowhead="https://www.wowhead.com/wotlk/quest=9805",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The wretched Lost Ones, heretofore banished to the swamps of Zangarmarsh, are seeking to spread their filth to other parts of our world.$B$BI have sought the wisdom of the furies and gained their blessing. To stop the source, we must unleash the elements upon them!$B$BI give you living fire, plucked from the fiery essence of Incineratus himself. Travel to Windyreed Village, southeast of here, and unleash the living fire upon their huts! Let them see the fury of the elements!",logDesc="Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to destroy the Large Hut, the Western Hut, the Southern Hut and the Eastern Hut at Windyreed Village.$B$BReturn the Living Fire to Elementalist Lo'ap when the task is complete."} end
if not DB[9806] then DB[9806]={id=9806,zoneId=3521,name="Fertile Spores",level=64,minLevel=62,giver="Gshaff",giverType="NPC",giverId=17925,ender="Gshaff",enderType="NPC",enderId=17925,poiX=280,poiY=8513,wowhead="https://www.wowhead.com/wotlk/quest=9806",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Spore bats and marsh walkers accumulate fertile spores on their appendages from wandering around the tallstalk mushrooms in the marsh.$B$BAs you can see, we're a short people so our options for gathering these spores are limited.  Seek out the spore bats and marsh walkers and gather the fertile spores.  All of Sporeggar will be in your debt.",logDesc="Gshaff wants you to gather 6 Fertile Spores from the various Zangarmarsh Spore Bats and Marsh Walkers.  Return to Ghsaff at Sporeggar when you've completed this task.",rewards={{id=24245,qty=1}}} end
if not DB[9807] then DB[9807]={id=9807,zoneId=3521,name="More Fertile Spores",level=64,minLevel=62,giver="Gshaff",giverType="NPC",giverId=17925,ender="Gshaff",enderType="NPC",enderId=17925,poiX=280,poiY=8513,wowhead="https://www.wowhead.com/wotlk/quest=9807",image="assets/images/quests/placeholder.png",rewards={{id=24245,qty=1}}} end
if not DB[9808] then DB[9808]={id=9808,zoneId=3521,name="Glowcap Mushrooms",level=64,minLevel=62,giver="Msshi'fn",giverType="NPC",giverId=17924,ender="Msshi'fn",enderType="NPC",enderId=17924,poiX=190,poiY=8486,wowhead="https://www.wowhead.com/wotlk/quest=9808",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've seen your kind use shiny round pieces of metal to trade for things that you need.  We're not so different from you.  We use shiny round mushrooms as our currency.$B$BGlowcap mushrooms grow everywhere in the marsh, you just have to know how to pick them from the ground without wrecking them.  I'll teach you how to do it, if you promise to bring us some for our reserves.  What do you say, $N?",logDesc="Bring 10 Glowcaps to Msshi'fn at Sporeggar in Zangarmarsh."} end
if not DB[9809] then DB[9809]={id=9809,zoneId=3521,name="More Glowcaps",level=64,minLevel=62,giver="Msshi'fn",giverType="NPC",giverId=17924,ender="Msshi'fn",enderType="NPC",enderId=17924,poiX=190,poiY=8486,wowhead="https://www.wowhead.com/wotlk/quest=9809",image="assets/images/quests/placeholder.png"} end
if not DB[9810] then DB[9810]={id=9810,zoneId=3518,name="The Spirit Polluted",level=66,minLevel=64,giver="Elementalist Lo'ap",giverType="NPC",giverId=18073,ender="Elementalist Lo'ap",enderType="NPC",enderId=18073,poiX=-783,poiY=6937,wowhead="https://www.wowhead.com/wotlk/quest=9810",image="assets/images/quests/placeholder.png",xpDiff=5,money=70000,desc="Watoosun was able to shed the stink of corruption; but in doing so, created a twisted spirit essence. A spirit essence composed of the vilest corruption found amongst the elements!$B$BYou will find this polluted spirit of the swamp southwest of here, hidden in the depths of Lake Sunspring.$B$BFind and destroy the polluted essence of Watoosun and any corrupt offspring that it may have created.",logDesc="Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to destroy Watoosun's Polluted Essence and 8 Lake Surgers.",choiceRewards={{id=25558,qty=1},{id=25557,qty=1},{id=25556,qty=1}}} end
if not DB[9811] then DB[9811]={id=9811,zoneId=3433,name="Friend of the Sin'dorei",level=21,minLevel=15,giver="Magister Kaendris",giverType="NPC",giverId=16239,ender="3",enderType="NPC",enderId=16802,rewardNextId=9812,poiX=7192,poiY=-7101,wowhead="https://www.wowhead.com/wotlk/quest=9811",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This is the beginning of a new chapter in blood elf history, $N.  You've helped cement the bond between my race and yours, $r.$B$BTake the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City.  He'll be eager to hear the news.",logDesc="Take Dar'Khan's Head to Lor'themar Theron in Silvermoon City."} end
if not DB[9812] then DB[9812]={id=9812,zoneId=1497,name="Envoy to the Horde",level=21,minLevel=15,giver="3",giverType="NPC",giverId=16802,ender="3",enderType="NPC",enderId=10181,rewardNextId=9813,poiX=9991,poiY=-7053,wowhead="https://www.wowhead.com/wotlk/quest=9812",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?$B$BThis changes everything.  No longer will our power be questioned.  We'll be able to join the Horde as equals.$B$BTake this letter to Sylvanas, ruler of the Forsaken.  She's already on our side but the news of Dar'Khan's death will be music to her ears.  Prepare for a long trip, $N.  If all goes well she will send you to Orgrimmar.",logDesc="Bring the Letter from Lor'themar Theron to Lady Sylvanas Windrunner in Undercity, the Forsaken capital in Tirisfal Glades."} end
if not DB[9813] then DB[9813]={id=9813,zoneId=1637,name="Meeting the Warchief",level=21,minLevel=15,giver="3",giverType="NPC",giverId=10181,ender="Thrall",enderType="NPC",enderId=4949,poiX=1290,poiY=316,wowhead="https://www.wowhead.com/wotlk/quest=9813",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I haven't lost any love for my homeland or its people, as you know.  I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table.$B$BThis should silence any opposition. Take this letter to Thrall in Orgrimmar.  As leader of the Horde he will have the final say on accepting the sin'dorei's pledge.$B$BI've added my own seal to the letter as a personal endorsement.  Go northwest of the city and board the zeppelin bound for Durotar at the tower.",logDesc="Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to Thrall in Orgrimmar, capital of Durotar."} end
if not DB[9814] then DB[9814]={id=9814,zoneId=3521,name="Burstcap Mushrooms, Mon!",level=64,minLevel=62,giver="Witch Doctor Tor'gash",giverType="NPC",giverId=18014,ender="Witch Doctor Tor'gash",enderType="NPC",enderId=18014,rewardNextId=9816,poiX=297,poiY=7822,wowhead="https://www.wowhead.com/wotlk/quest=9814",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="You like mushrooms, mon? There be a powerful one here in Zangarmarsh, growin' real close to Zabra'jin.$B$BYou gotta be careful, though, mon. They be callin' it the burstcap for a reason. If you be gettin' too close without takin' the proper precautions, it'll blow right up on you! Poof! Right into a cloud o' toxic spores.$B$BI been usin' them for readin' the omens, but they be almost gone now.",logDesc="Bring Witch Doctor Tor'gash 6 Burstcap Mushrooms."} end
if not DB[9815] then DB[9815]={id=9815,zoneId=3518,name="Muck Diving",level=66,minLevel=64,giver="Elementalist Lo'ap",giverType="NPC",giverId=18073,ender="Elementalist Lo'ap",enderType="NPC",enderId=18073,poiX=-783,poiY=6937,wowhead="https://www.wowhead.com/wotlk/quest=9815",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The most affected elements of water can be found in the Halaani Basin, southwest of here, beneath the abandoned city of Halaa. While some distressed elements can be destroyed without any impact upon the environment, spawns of muck must be physically removed from the world once destroyed.$B$BYou see, muck spawns leave behind globules of tainted debris that if left untouched will spread and further contaminate the environment.$B$BDestroy these muck spawns and bring back their muck-ridden cores.",logDesc="Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to retrieve 5 Muck-ridden Cores.",choiceRewards={{id=25560,qty=1},{id=25561,qty=1},{id=25559,qty=1}}} end
if not DB[9816] then DB[9816]={id=9816,zoneId=3521,name="Have You Ever Seen One of These?",level=64,minLevel=62,giver="Witch Doctor Tor'gash",giverType="NPC",giverId=18014,ender="Witch Doctor Tor'gash",enderType="NPC",enderId=18014,poiX=297,poiY=7822,wowhead="https://www.wowhead.com/wotlk/quest=9816",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="This marsh be missin' one thing, mon! There be no murlocs here.$B$BDon't worry, mon, I got a plan to fix the problem. See Gargle 'n' Gurgle over there? I plan to give the gift o' murlocs to the Lost Ones!$B$BTake this cage with you to Daggerfen Village an' release 'em in the northeastern cluster of huts. Now you know I can't be riskin' Gargle 'n' Gurgle with you, but I'll give you a cage full o' colorful young murlocs. Just set it on the flat rock you be findin' up there and open the door!",logDesc="Take the Murloc Cage and place it on the flat rock near Daggerfen Village.",choiceRewards={{id=25611,qty=1},{id=25612,qty=1},{id=25610,qty=1}}} end
if not DB[9817] then DB[9817]={id=9817,zoneId=3521,name="Leader of the Bloodscale",level=63,minLevel=58,ender="Warden Hamoot",enderType="NPC",enderId=17858,wowhead="https://www.wowhead.com/wotlk/quest=9817",image="assets/images/quests/placeholder.png",xpDiff=6,money=58000,desc="A bounty is hereby declared by the Cenarion Expedition on Rajis Fyashe, leader of the Bloodscale naga.  The naga sorceress was last sighted at Serpent Lake, in the northern region of Zangarmarsh.$B$BThe Bloodscale are to be considered extremely dangerous and their leader is to be approached with extreme caution.$B$BThose seeking to claim the bounty are advised to report to Warden Hamoot at Cenarion Refuge.",logDesc="Slay Rajis Fyashe at Serpent Lake and return to Warden Hamoot at the Cenarion Refuge in Zangarmarsh for a reward.",choiceRewards={{id=27724,qty=1},{id=27722,qty=1},{id=27723,qty=1},{id=27721,qty=1}}} end
if not DB[9818] then DB[9818]={id=9818,zoneId=3518,name="The Underneath",level=65,minLevel=64,giver="Elementalist Untrag",giverType="NPC",giverId=18071,ender="3",enderType="NPC",enderId=18099,rewardNextId=9819,poiX=-793,poiY=6945,wowhead="https://www.wowhead.com/wotlk/quest=9818",image="assets/images/quests/placeholder.png",desc="Something rails the underneath. It beats the ground as if to punish.$B$B*Thud*$B$B<Untrag beats his chest with his fist.>$B$BIt makes this sound a hundred-thousand times. Endlessly it beats. The earth reels. It is calling out to us now.$B$BGordawg speaks to me. Gordawg knows that something forces the elements out. Something from the underneath.$B$BGo now and speak to Gordawg. No, listen to Gordawg, do not speak. Hear Gordawg...",logDesc="Communicate with Gordawg."} end
if not DB[9819] then DB[9819]={id=9819,zoneId=3518,name="The Tortured Earth",level=65,minLevel=64,giver="3",giverType="NPC",giverId=18099,ender="3",enderType="NPC",enderId=18099,rewardNextId=9821,poiX=-873,poiY=6908,wowhead="https://www.wowhead.com/wotlk/quest=9819",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Bring up the usurper. You will find him. Follow earthen path. First you put to rest tortured earth spirits. Must sleep once more.$B$B<Gordawg smashes his fist into the ground and brings up very foul smelling soil.>$B$BMust sleep!$B$B<Gordawg points southeast.>$B$BFind spirits near mountains. Near hills. Near rocks. Near earth.$B$BPut to sleep.$B$BTelaari Basin... Southeast.$B",logDesc="Gordawg at the Throne of the Elements in Nagrand has asked that you destroy 10 Tortured Earth Spirits."} end
if not DB[9820] then DB[9820]={id=9820,zoneId=3521,name="WANTED: Boss Grog'ak",level=64,minLevel=58,ender="Shadow Hunter Denjai",enderType="NPC",enderId=18013,rewardNextId=9822,wowhead="https://www.wowhead.com/wotlk/quest=9820",image="assets/images/quests/placeholder.png",xpDiff=6,money=31000,desc="Wanted - Dead or Alive: Boss Grog'ak, overseer of the Ango'rosh mushroom-cutting operation.$B$BThis brute and his axe-wielding cronies are responsible for chopping down the mushrooms to the north of town. Unless he is stopped, he and his band will cut a path to the walls of Zabra'jin.$B$B$g He:She; who presents the head of Boss Grog'ak to Shadow Hunter Denjai shall be well-rewarded.",logDesc="Bring Boss Grog'ak's Head to Shadow Hunter Denjai in Zabra'jin."} end
if not DB[9821] then DB[9821]={id=9821,zoneId=3518,name="Eating Damnation",level=66,minLevel=64,giver="3",giverType="NPC",giverId=18099,ender="3",enderType="NPC",enderId=18099,rewardNextId=9849,poiX=-873,poiY=6908,wowhead="https://www.wowhead.com/wotlk/quest=9821",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Gordawg picks up a rock and begins to chew on it.>$B$BGordawg tastes. Gordawg knows where this earth has been.$B$B<Gordawg raises one of his massive legs and stomps the ground.>$B$BLook. See Nagrand.$B$B<Gordawg directs you to the imprint of his foot. Within the imprint you see what appears to be a perfect geological map of Nagrand, marked with the locations of where you can find the elementals Gordawg wants you to destroy.>$B$BBREAK THEM! Bring Gordawg the pieces to eat.$B$BTake the map.",logDesc="Gordawg at the Throne of the Elements in Nagrand has asked that you bring him 10 Enraged Crusher Cores. "} end
if not DB[9822] then DB[9822]={id=9822,zoneId=3521,name="Impending Attack",level=64,minLevel=62,giver="Shadow Hunter Denjai",giverType="NPC",giverId=18013,ender="Shadow Hunter Denjai",enderType="NPC",enderId=18013,rewardNextId=9823,poiX=230,poiY=7930,wowhead="https://www.wowhead.com/wotlk/quest=9822",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="The position of the ogres' mushroom-cutting operation can't be an accident. I can't escape the suspicion that they're preparing for an attack on Zabra'jin.$B$BI must know for certain, $N. The ogres have another outpost to the northwest, the Ango'rosh Grounds. If they're staging for an attack, there will be evidence of their plans there. Go there, $N and search the camp for signs of their intentions. Return to me with anything that might be suspicious.",logDesc="Bring the Ango'rosh Attack Plans to Shadow Hunter Denjai in Zabra'jin."} end
if not DB[9823] then DB[9823]={id=9823,zoneId=3521,name="Us or Them",level=64,minLevel=62,giver="Shadow Hunter Denjai",giverType="NPC",giverId=18013,ender="Shadow Hunter Denjai",enderType="NPC",enderId=18013,poiX=230,poiY=7930,wowhead="https://www.wowhead.com/wotlk/quest=9823",image="assets/images/quests/placeholder.png",xpDiff=6,money=62000,desc="In order to end the Ango'rosh threat, we must kill their leader, Overlord Gorefist. We'll do better than that, though. We'll make an example of the overlord and his followers.$B$BGo to the Ango'rosh Stronghold and deal with our foes. The stronghold is located in a cave on a small island to the northwest of Zabra'jin. You'll see a bridge made from a fallen mushroom beyond the Ango'rosh Camp.$B$BShow no mercy, $N. They certainly wouldn't spare any of us.",logDesc="Kill Overlord Gorefist, 10 Ango'rosh Maulers, and 10 Ango'rosh Souleaters and report back to Shadow Hunter Denjai in Zabra'jin.",rewards={{id=25617,qty=1},{id=27553,qty=5}}} end
if not DB[9824] then DB[9824]={id=9824,zoneId=2562,name="Arcane Disturbances",level=70,minLevel=68,giver="Archmage Alturus",giverType="NPC",giverId=17613,ender="Archmage Alturus",enderType="NPC",enderId=17613,poiX=-11120,poiY=-2015,wowhead="https://www.wowhead.com/wotlk/quest=9824",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="I'm trying to obtain an imprint of Karazhan's energy... for a personal project, of course.  Unfortunately, I'm not getting anything up here.  If I could get near an underground water source, my crystal would pick up the signals much more clearly.$B$BI've heard of an underground pond as well as a well in a cellar below us.  This whole place is crawling with ghosts however, and venturing there would be hazardous for someone my age.  What do you say; will you help an old man and perform the scrying for me?",logDesc="Use the Violet Scrying Crystal near underground sources of water in the Master's Cellar and return to Archmage Alturus outside of Karazhan."} end
if not DB[9825] then DB[9825]={id=9825,zoneId=2562,name="Restless Activity",level=70,minLevel=68,giver="Archmage Alturus",giverType="NPC",giverId=17613,ender="Archmage Alturus",enderType="NPC",enderId=17613,poiX=-11120,poiY=-2015,wowhead="https://www.wowhead.com/wotlk/quest=9825",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="As you may have noticed, the outside of Karazhan is crawling with ghostly beings. The reason for their existence is unknown and unknowns bother me!$B$BBring me their ghostly essence so that I may study their nature.  Karazhan has many secrets, $N.  I'm determined to uncover all of them.",logDesc="Bring 10 Ghostly Essences to Archmage Alturus outside of Karazhan."} end
if not DB[9826] then DB[9826]={id=9826,zoneId=279,name="Contact from Dalaran",level=70,minLevel=68,giver="Archmage Alturus",giverType="NPC",giverId=17613,ender="Archmage Cedric",enderType="NPC",enderId=18165,rewardNextId=9829,poiX=-11120,poiY=-2015,wowhead="https://www.wowhead.com/wotlk/quest=9826",image="assets/images/quests/placeholder.png",xpDiff=3,desc="These signs do not bode well for us, $N.  I've never been one for secrecy so I will tell you a bit about my organization, the Violet Eye.$B$BWe are agents of the Kirin Tor, the Magus Senate of Dalaran.  We were assigned to keep an eye on Karazhan and Medivh, in case things got out of hand.$B$BWhich they did... very quickly, after Medivh disappeared.$B$BThis report details my findings.  Take it to Archmage Cedric, also from the Violet Eye; you will find him in the outskirts of Dalaran Crater.",logDesc="Bring Alturus's Report to Archmage Cedric in the outskirts of Dalaran Crater."} end
if not DB[9827] then DB[9827]={id=9827,zoneId=3521,name="Withered Basidium",level=62,minLevel=60,ender="Ruam",enderType="NPC",enderId=18007,rewardNextId=10355,wowhead="https://www.wowhead.com/wotlk/quest=9827",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="A close inspection of the basidium reveals a number of indentations that might have once held something. The alien mass of fungus presents something of a puzzle. It's far from healthy, but you have little clue as to what function it might normally perform.$B$BPerhaps someone more familiar with the denizens of Zangarmarsh would be able to tell you more about the basidium.",logDesc="Take the Withered Basidium to Ruam in Telredor in Zangarmarsh."} end
if not DB[9828] then DB[9828]={id=9828,zoneId=3521,name="Withered Basidium",level=62,minLevel=60,ender="Reavij",enderType="NPC",enderId=18012,wowhead="https://www.wowhead.com/wotlk/quest=9828",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="A close inspection of the basidium reveals a number of indentations that might have once held something. The alien mass of fungus presents something of a puzzle. It's far from healthy, but you have little clue as to what function it might normally perform.$B$BPerhaps someone more familiar with the denizens of Zangarmarsh would be able to tell you more about the basidium.",logDesc="Bring the Withered Basidium to Reavij at Swamprat Post in Zangarmarsh."} end
if not DB[9829] then DB[9829]={id=9829,zoneId=3703,name="Khadgar",level=70,minLevel=68,giver="Archmage Cedric",giverType="NPC",giverId=18165,ender="Khadgar",enderType="NPC",enderId=18166,rewardNextId=9831,poiX=481,poiY=346,wowhead="https://www.wowhead.com/wotlk/quest=9829",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Alturus's report is unsettling.  We thought it was bad when Karazhan sealed itself off to the outside world.  We had agents inside; we never heard from any of them again.  Now this... demonic emanation.  We must investigate it.$B$BThe only people who can reopen Karazhan were presumed dead: Khadgar and Medivh.$B$BWhile we hope that the latter is indeed gone, we recently learned that his apprentice, Khadgar, is alive and well in a place called Shattrath City.  Find him and give him Alturus's report.",logDesc="Deliver Alturus's Report to Khadgar in Shattrath City in Terokkar Forest."} end
if not DB[9830] then DB[9830]={id=9830,zoneId=3521,name="Stinger Venom",level=64,minLevel=62,giver="Puluu",giverType="NPC",giverId=18009,ender="Puluu",enderType="NPC",enderId=18009,poiX=975,poiY=7422,wowhead="https://www.wowhead.com/wotlk/quest=9830",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="When I speak to draenei, I often get the sense that they consider themselves removed from their environment. Many seem to pity my brethren, the Broken, who they say have lost something.$B$BWe Broken may have lost our inclination toward the Light, but our experiences have brought us closer to the land.$B$BMy people see opportunities where few draenei do. Take, for example, the venom of the marshlight bleeders that live to the south and west. It has a wide variety of uses from hunting to healing.",logDesc="Bring 6 Marshlight Bleeder Venom to Puluu at the Orebor Harborage."} end
if not DB[9831] then DB[9831]={id=9831,zoneId=3789,name="Entry Into Karazhan",level=70,minLevel=68,giver="Khadgar",giverType="NPC",giverId=18166,ender="Khadgar",enderType="NPC",enderId=18166,rewardNextId=9832,poiX=-1860,poiY=5420,wowhead="https://www.wowhead.com/wotlk/quest=9831",image="assets/images/quests/placeholder.png",xpDiff=8,desc="I am deeply troubled by the news in this report, $N.  Gaining entry into Karazhan will be difficult, however.$B$BYou see, when it became apparent that I was stranded here I split the key into three fragments.$B$BI placed the keys inside enchanted containers, and in turn placed those in places that were safe at the time.$B$BWith the dark changes Outland has endured this no longer is the case.  The first fragment is in a section of Auchindoun taken over by the Shadow Council.  Return this fragment to me.",logDesc="Khadgar wants you to enter the Shadow Labyrinth at Auchindoun and retrieve the First Key Fragment from an Arcane Container hidden there."} end
if not DB[9832] then DB[9832]={id=9832,zoneId=3703,name="The Second and Third Fragments",level=70,minLevel=68,giver="Khadgar",giverType="NPC",giverId=18166,ender="Khadgar",enderType="NPC",enderId=18166,poiX=-1860,poiY=5420,wowhead="https://www.wowhead.com/wotlk/quest=9832",image="assets/images/quests/placeholder.png",xpDiff=8,desc="I hid the second fragment at the bottom of Serpent Lake, long before it was called that.  The giant drain installed there after the naga took over has likely pulled the container into the depths of Coilfang Reservoir.$B$BThe third fragment will prove the most trying, as I left it inside Tempest Keep back when it was controlled by the naaru.  Kael'thas now rules it and the chamber where I left it has become a prison.$B$BBring me these remaining fragments, $N.  Much depends on your success.",logDesc="Obtain the Second Key Fragment from an Arcane Container inside Coilfang Reservoir and the Third Key Fragment from an Arcane Container inside Tempest Keep.  Return to Khadgar in Shattrath City after you've completed this task."} end
if not DB[9833] then DB[9833]={id=9833,zoneId=3521,name="Lines of Communication",level=64,minLevel=62,giver="Puluu",giverType="NPC",giverId=18009,ender="Puluu",enderType="NPC",enderId=18009,poiX=975,poiY=7422,wowhead="https://www.wowhead.com/wotlk/quest=9833",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="One of the reasons Ikuti led us to Zangarmarsh was to help open the lines of communication between the draenei and the Kurenai home city of Telaar in Nagrand. In order for messengers to pass swiftly between Telaar and Telredor, the roads must be secured.$B$BOn our way here, we were attacked repeatedly by marshfang slicers. We were able to fight them off, but they would pose a formidable threat to a solitary messenger. Reducing their numbers will help ensure the safety of our messengers.",logDesc="Puluu at the Orebor Harborage wants you to kill 12 Marshfang Slicers.",choiceRewards={{id=27753,qty=1},{id=27754,qty=1},{id=27756,qty=1}}} end
if not DB[9834] then DB[9834]={id=9834,zoneId=3521,name="Natural Armor",level=64,minLevel=62,giver="Maktu",giverType="NPC",giverId=18010,ender="Maktu",enderType="NPC",enderId=18010,rewardNextId=9905,poiX=1021,poiY=7383,wowhead="https://www.wowhead.com/wotlk/quest=9834",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Maktu can always see a draenei approaching in his shiny armor from a mile away, even in this murky swamp!$B$BMaktu wants to laugh at them, but then he remembers that they have been kind to the Kurenai and he wants to teach them about how Kurenai make armor.$B$BThe dark, scaly hides of the fenclaw thrashers make some of the best armor Maktu has ever worn. If $N can bring Maktu some of these hides from the fenclaw thrashers deep in Serpent Lake, he'll be happy to share some of his armor.",logDesc="Bring 8 Fenclaw Hides to Maktu at the Orebor Harborage."} end
if not DB[9835] then DB[9835]={id=9835,zoneId=3521,name="Ango'rosh Encroachment",level=64,minLevel=62,giver="Ikuti",giverType="NPC",giverId=18008,ender="Ikuti",enderType="NPC",enderId=18008,rewardNextId=9839,poiX=1024,poiY=7366,wowhead="https://www.wowhead.com/wotlk/quest=9835",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="The small band of Broken you see here is a mission from a larger settlement in Nagrand. The Kurenai, as we call ourselves, are Broken who desire to reunite with our draenei brothers.$B$BMy group has come here to strengthen Kurenai ties to the draenei of Telredor.$B$BIf the Ango'rosh ogres have their way, this temple will not stand much longer. They have cleared the Hewn Bog of its towering mushrooms and draw ever closer to our refuge. If you would call yourself our friend, aid us in fighting this enemy.",logDesc="Kill 10 Ango'rosh Ogres and 5 Ango'rosh Shaman and return to Ikuti at the Orebor Harborage."} end
if not DB[9836] then DB[9836]={id=9836,zoneId=1941,name="The Master's Touch",level=70,minLevel=68,giver="Khadgar",giverType="NPC",giverId=18166,ender="3",enderType="NPC",enderId=15608,rewardNextId=9837,poiX=-1860,poiY=5420,wowhead="https://www.wowhead.com/wotlk/quest=9836",image="assets/images/quests/placeholder.png",xpDiff=8,desc="I've put together the very key I used as an apprentice.  It looks completely functional as far as keys go.  In regards to opening Karazhan, however, this might as well be a piece of scrap metal.$B$BWithout Medivh's consent, the key is worthless.  Yes, of course I know Medivh is dead.  This merely makes things difficult, not impossible.$B$BThere is a place in Azeroth called the Caverns of Time, guarded by the bronze dragonflight.  Find a way inside, travel back in time and get Medivh to enable the key.",logDesc="Go into the Caverns of Time and convince Medivh to enable your Restored Apprentice's Key."} end
if not DB[9837] then DB[9837]={id=9837,zoneId=3703,name="Return to Khadgar",level=70,minLevel=68,giver="3",giverType="NPC",giverId=15608,ender="Khadgar",enderType="NPC",enderId=18166,rewardNextId=9838,poiX=-2025,poiY=7120,wowhead="https://www.wowhead.com/wotlk/quest=9837",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I seem to have memories about future events surrounding you and this key.$B$B<Medivh looks at you like he's just seen a ghost.>$B$BYou have trying times ahead of you, $N.  Let us hope your strength does not fail you.$B$BRegarding the key, I am to hand it to Khadgar when he's sent to me.  I couldn't hope for a better apprentice.$B$BI suppose you will need a key of your own.$B$B<Medivh reaches into his robe and hands you his own key.>$B$BGo on then.  And best of luck, $c.",logDesc="Return to Khadgar in Shattrath City and show him the Master's Key.",rewards={{id=24490,qty=1}}} end
if not DB[9838] then DB[9838]={id=9838,zoneId=2562,name="The Violet Eye",level=70,minLevel=68,giver="Khadgar",giverType="NPC",giverId=18166,ender="Archmage Alturus",enderType="NPC",enderId=17613,rewardNextId=9840,poiX=-1860,poiY=5420,wowhead="https://www.wowhead.com/wotlk/quest=9838",image="assets/images/quests/placeholder.png",xpDiff=3,desc="A great responsibility has been bestowed upon you, $N.  If the signs that the Violet Eye has observed are to be trusted, then you must help them.$B$BFor all my disagreements with Cedric, the work that men like Alturus do is still important.  Beware that they do not use you, however.  Remember it is you who the key is bound to, not them.  But if the danger in Karazhan is real, then it is they who are best prepared to guide you in dealing with it.  Go back to Alturus and help him in any way that you can.",logDesc="Speak to Archmage Alturus outside Karazhan."} end
if not DB[9839] then DB[9839]={id=9839,zoneId=3521,name="Overlord Gorefist",level=64,minLevel=62,giver="Ikuti",giverType="NPC",giverId=18008,ender="Ikuti",enderType="NPC",enderId=18008,poiX=1024,poiY=7366,wowhead="https://www.wowhead.com/wotlk/quest=9839",image="assets/images/quests/placeholder.png",xpDiff=6,money=31000,desc="The centerpiece of any ogre tribe is its leader. Without leadership, the Ango'rosh's organization will disappear and they'll resort to infighting to determine who will lead next.$B$BAlthough we've seen the ogres out and about in this area, their true strength is concentrated in their Ango'rosh Stronghold to the northwest. It's located in a cave on a small island connected to the marsh by a fallen mushroom.$B$BGo there and defeat Overlord Gorefist. That should provide us with a well-deserved respite.",logDesc="Ikuti wants you to kill Overlord Gorefist and 10 Ango'rosh Maulers. Return to the Orebor Harborage once you have completed the task.",choiceRewards={{id=25619,qty=1},{id=25618,qty=1},{id=31770,qty=1}}} end
if not DB[9840] then DB[9840]={id=9840,zoneId=2562,name="Assessing the Situation",level=70,minLevel=68,giver="Archmage Alturus",giverType="NPC",giverId=17613,ender="Koren",enderType="NPC",enderId=16388,rewardNextId=9843,poiX=-11120,poiY=-2015,wowhead="https://www.wowhead.com/wotlk/quest=9840",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now that we've found a way back into Medivh's Tower - or rather you have - the first thing we need to do is try to get a sense of what the situation inside is.$B$BOne of our agents who had managed to infiltrate Karazhan kept an encoded log of her observations.  Unfortunately her death was confirmed shortly before Karazhan was shut down.  Koren, Karazhan's blacksmith, was under our pay.  Though not a member of the Violet Eye, he should be able to help us find Keanna's log.  Look for him inside.",logDesc="Find Koren inside Karazhan."} end
if not DB[9841] then DB[9841]={id=9841,zoneId=3521,name="Stinging the Stingers",level=64,minLevel=62,giver="Gambarinka",giverType="NPC",giverId=18015,ender="Gambarinka",enderType="NPC",enderId=18015,rewardNextId=9842,poiX=286,poiY=7885,wowhead="https://www.wowhead.com/wotlk/quest=9841",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="It's impossible to work with all this infernal buzzing! Do you hear it?$B$BI can't get it out of my head! I know exactly what's making the noise, too. It's those damnable marshlight bleeders! The noise always comes from the south and west of the village.$B$BThey're too big to swat, crush underfoot, or wave away. The only way to stop that unholy droning is to kill them. I don't care how you do it, $N, just quiet them!",logDesc="Kill 8 Marshlight Bleeders and return to Gambarinka at Zabra'jin."} end
if not DB[9842] then DB[9842]={id=9842,zoneId=3521,name="The Sharpest Blades",level=64,minLevel=62,giver="Gambarinka",giverType="NPC",giverId=18015,ender="Gambarinka",enderType="NPC",enderId=18015,poiX=286,poiY=7885,wowhead="https://www.wowhead.com/wotlk/quest=9842",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="The damp atmosphere of the marsh has taken a toll on my metal tools. It's made woodworking a lot more difficult than it ought to be, so I've given up on metal blades.$B$BIt turns out that the marshfang slicers living to the south and west of town grow blades that are sharper than any steel I've ever owned. They're also resistant to rust and wear. It's just a little tricky to attach them to a handle, but I think I've got it figured out. I'd appreciate any blades you could bring me.",logDesc="Bring 10 Marshfang Slicer Blades to Gambarinka at Zabra'jin.",choiceRewards={{id=27756,qty=1},{id=27753,qty=1},{id=27754,qty=1}}} end
if not DB[9843] then DB[9843]={id=9843,zoneId=2562,name="Keanna's Log",level=70,minLevel=68,giver="Koren",giverType="NPC",giverId=16388,ender="Archmage Alturus",enderType="NPC",enderId=17613,rewardNextId=9844,poiX=-11090,poiY=-1908,wowhead="https://www.wowhead.com/wotlk/quest=9843",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Who did you say you were looking for again?  Keanna?$B$BI once met someone with that name.  She was staying up at the guest chambers.  I was supposed to keep that a secret now, wasn't I?$B$BDid you say you were with the Violet Eye?  No, I've never heard of them.$B$BI need to return to my work now, if you don't mind.$B$B<Koren seems to have forgotten about you already.>",logDesc="Search the Guest Chambers inside Karazhan for Keanna's Log and bring it to Archmage Alturus outside Karazhan."} end
if not DB[9844] then DB[9844]={id=9844,zoneId=2562,name="A Demonic Presence",level=70,minLevel=68,giver="Archmage Alturus",giverType="NPC",giverId=17613,ender="Archmage Alturus",enderType="NPC",enderId=17613,rewardNextId=9860,poiX=-11120,poiY=-2015,wowhead="https://www.wowhead.com/wotlk/quest=9844",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Keanna's last few entries confirm our suspicions of a demonic presence inside Karazhan.$B$BShe detected the arrival of a Burning Legion agent whose location she describes as coming from the top of the tower.$B$BHer entries stop there.$B$BKarazhan is a very important place, $c.  It is a portal into the nether, a beacon shining into other worlds.  The possible repercussions of it falling into the wrong hands are unthinkable.  This demonic intrusion must be stopped.  And you, $N, are the only one with a key.",logDesc="Archmage Alturus wants you to destroy the Demonic Presence at the top of Karazhan."} end
if not DB[9845] then DB[9845]={id=9845,zoneId=3521,name="Angling to Beat the Competition",level=64,minLevel=62,giver="Zurjaya",giverType="NPC",giverId=18018,ender="Zurjaya",enderType="NPC",enderId=18018,rewardNextId=9903,poiX=273,poiY=7854,wowhead="https://www.wowhead.com/wotlk/quest=9845",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="It's a relief to be in someplace with water after trekking through the wasteland of Hellfire Peninsula. I was worried there might not be any respectable fishing holes in Outland.$B$BNow I'm glad I lugged my fishing supplies along. For the most part, the fishing's been good, except for those no good fenclaw thrashers in Serpent Lake.$B$BNot only do they scare the fish away, but they're bold enough to snap the bait right off my hook. I spend more time re-baiting the hook than I do catching anything!",logDesc="Kill 10 Fenclaw Thrashers and return to Zurjaya at Zabra'jin."} end
if not DB[9846] then DB[9846]={id=9846,zoneId=3521,name="Spirits of the Feralfen",level=62,minLevel=60,giver="Seer Janidi",giverType="NPC",giverId=18017,ender="Seer Janidi",enderType="NPC",enderId=18017,rewardNextId=9847,poiX=194,poiY=7847,wowhead="https://www.wowhead.com/wotlk/quest=9846",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="The most powerful tribe of Lost Ones in the marsh, the Feralfen, are said to possess powerful medicine. There may be no truth to such rumors, but anything that might help me channel the spirits of this world cannot be ignored.$B$BFind the Feralfen mystics, hunters and druids, $N, and capture their totems. Everything I need to know should be apparent from the carvings.",logDesc="Bring 10 Feralfen Protection Totems to Seer Janidi at Zabra'jin."} end
if not DB[9847] then DB[9847]={id=9847,zoneId=3521,name="A Spirit Ally?",level=64,minLevel=60,giver="Seer Janidi",giverType="NPC",giverId=18017,ender="Seer Janidi",enderType="NPC",enderId=18017,poiX=194,poiY=7847,wowhead="https://www.wowhead.com/wotlk/quest=9847",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="We must find out how much power this Feralfen snake spirit possesses and whether it can be bent to our will. Imagine what I could do with the powers of an Outland spirit at my command!$B$BTake this totem with you and make your way to the foot of the stairs leading to the Boha'mu Ruins. Plant the totem in the ground and it should do the rest. The spirit should not be able to tell who has used the totem until it has manifested.",logDesc="Take the Feralfen Totem to the foot of the stairs at the Boha'mu Ruins and plant it in the ground. Report your findings to Seer Janidi at Zabra'jin.",choiceRewards={{id=25620,qty=1},{id=25621,qty=1},{id=31770,qty=1}}} end
if not DB[9848] then DB[9848]={id=9848,zoneId=3521,name="Secrets of the Daggerfen",level=64,minLevel=62,giver="Timothy Daniels",giverType="NPC",giverId=18019,ender="Timothy Daniels",enderType="NPC",enderId=18019,poiX=974,poiY=7403,wowhead="https://www.wowhead.com/wotlk/quest=9848",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Bugs, bugs, bugs! The marsh is full of them and my companions here seem obsessed with them.$B$BWell, I've had it with the bugs! Something far more intriguing has captured my interest. To the west, there is a village of Lost Ones who call themselves the Daggerfen.$B$BThe whole tribe consists of highly specialized assassins. I've noticed them mixing and using a particularly potent kind of poison. I'm dying to know more about the poison, but that's going to require a copy of the recipe and a sample vial.",logDesc="Bring the Daggerfen Poison Manual and a Daggerfen Poison Vial to Timothy Daniels at the Orebor Harborage.",rewards={{id=25616,qty=1},{id=27553,qty=5}}} end
if not DB[9849] then DB[9849]={id=9849,zoneId=3518,name="Shattering the Veil",level=67,minLevel=64,giver="3",giverType="NPC",giverId=18099,ender="3",enderType="NPC",enderId=18099,rewardNextId=9853,poiX=-873,poiY=6908,wowhead="https://www.wowhead.com/wotlk/quest=9849",image="assets/images/quests/placeholder.png",xpDiff=7,desc="<Gordawg breaks off a piece of ebon rock from his back.>$B$BYou are granted a piece of the fury of the earth. Take the boulder of Gordawg and hurl it at the poison rock. Shatter their shells to discover the truth. Destroy the minions of the usurper and return to Gordawg with the name.$B$BYou find the shattered elements at the edge of the world. Southwest.",logDesc="Gordawg at the Throne of the Elements in Nagrand has asked that you slay 30 Minions of Gurok."} end
if not DB[9850] then DB[9850]={id=9850,zoneId=3518,name="Clefthoof Mastery",level=67,minLevel=64,giver="Hemet Nesingwary",giverType="NPC",giverId=18180,ender="Hemet Nesingwary",enderType="NPC",enderId=18180,rewardNextId=9851,poiX=-1462,poiY=6344,wowhead="https://www.wowhead.com/wotlk/quest=9850",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="You've proved to me that you can find and take down a regular clefthoof, but far more dangerous are the clefthoof bulls.$B$BBag yourself twelve of those.  Then you can talk to me of your hunting prowess.$B$BLook for them all along the middle region of Nagrand to the west and south.",logDesc="Kill 12 Clefthoof Bulls and then speak to Hemet Nesingwary at Nesingwary's Safari in Nagrand about your prowess."} end
if not DB[9851] then DB[9851]={id=9851,zoneId=3518,name="Clefthoof Mastery",level=67,minLevel=64,giver="Hemet Nesingwary",giverType="NPC",giverId=18180,ender="Hemet Nesingwary",enderType="NPC",enderId=18180,poiX=-1462,poiY=6344,wowhead="https://www.wowhead.com/wotlk/quest=9851",image="assets/images/quests/placeholder.png",xpDiff=6,money=74000,desc="Banthar is the fiercest and most elusive of all the clefthoof in Outland.  She's also the hairiest.$B$BIt is said that she roams with her clefthoof herd in the Field of Spirits near Oshu'gun.$B$BYou want to truly prove your hunting mastery?  Bring me her horn!",logDesc="Acquire the Horn of Banthar and return it to Hemet Nesingwary at the Nesingwary Safari in Nagrand.",choiceRewards={{id=25591,qty=1},{id=25592,qty=1},{id=25589,qty=1}}} end
if not DB[9852] then DB[9852]={id=9852,zoneId=3518,name="The Ultimate Bloodsport",level=68,minLevel=64,giver="Hemet Nesingwary",giverType="NPC",giverId=18180,ender="Hemet Nesingwary",enderType="NPC",enderId=18180,poiX=-1462,poiY=6344,wowhead="https://www.wowhead.com/wotlk/quest=9852",image="assets/images/quests/placeholder.png",xpDiff=7,money=117000,desc="The queen of all that dwell in Nagrand is known as Tusker.  She's a giant elekk the likes of which you won't see anywhere else!$B$BYou're right to be fearful of that name.  Bach'lor, Gutripper, and Banthar are nothing when compared to her.  It is said that she can be found on a huge bluff far to the southwest overlooking Oshu'gun.  Bring me her massive heart if you dare.$B$BDo you want to leave a letter with me so that I can have it delivered to your next of kin in the likely event that you don't return?",logDesc="Bring the Heart of Tusker to Hemet Nesingwary at Nesingwary's Safari in Nagrand.",choiceRewards={{id=25640,qty=1},{id=29211,qty=1},{id=25639,qty=1},{id=25643,qty=1},{id=25644,qty=1},{id=25645,qty=1}}} end
if not DB[9853] then DB[9853]={id=9853,zoneId=3518,name="Gurok the Usurper",level=67,minLevel=64,giver="3",giverType="NPC",giverId=18099,ender="3",enderType="NPC",enderId=18099,poiX=-873,poiY=6908,wowhead="https://www.wowhead.com/wotlk/quest=9853",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Gurok must be summoned. You summon Gurok and you destroy.$B$BYou must go to Warmaul Hill to the northwest and find where ogre worships Gurok. You put ogre skull from Warmaul ogres on Gurok's earthen brand. Only then will Gurok come. Seven skulls.$B$BIf you live, bring Gordawg back Gurok earthen head. Gordawg crushes head.$B$B<Gordawg bites down hard, shaking the earth beneath your feet.>",logDesc="Gordawg at the Throne of the Elements in Nagrand has asked that you destroy Gurok the Usurper and bring back Gurok's Earthen Head.",choiceRewards={{id=25563,qty=1},{id=25564,qty=1},{id=25562,qty=1}}} end
if not DB[9854] then DB[9854]={id=9854,zoneId=3518,name="Windroc Mastery",level=65,minLevel=64,giver="Shado 'Fitz' Farstrider",giverType="NPC",giverId=18200,ender="Shado 'Fitz' Farstrider",enderType="NPC",enderId=18200,rewardNextId=9855,poiX=-1451,poiY=6341,wowhead="https://www.wowhead.com/wotlk/quest=9854",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="Do you live for the hunt as I do, $c?  Do you seek the quietude that comes as you stalk your prey?  Would you know what it is to honor the last heartbeats of your fallen quarry?  I will help you to achieve this.$B$BNagrand is a lush land, full of life in the midst of this broken world.  Bring down a handful of the windrocs and then we will speak more.$B$BYou can find them in many places nearby in all directions around our camp.",logDesc="Kill 12 Windrocs and then return to Fitz at the Nesingwary Safari in Nagrand."} end
if not DB[9855] then DB[9855]={id=9855,zoneId=3518,name="Windroc Mastery",level=67,minLevel=64,giver="Shado 'Fitz' Farstrider",giverType="NPC",giverId=18200,ender="Shado 'Fitz' Farstrider",enderType="NPC",enderId=18200,rewardNextId=9856,poiX=-1451,poiY=6341,wowhead="https://www.wowhead.com/wotlk/quest=9855",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="You must always push yourself if you are to one day stalk the mightiest of prey!  While you are not yet ready, I will point you in the right direction.$B$BThere is another breed of windroc even deadlier.  Seek out the ravenous windroc to test your mettle against.  You will find them in the heart of Nagrand to the west and southwest.",logDesc="Hunt down 12 Ravenous Windrocs and then return to Fitz at the Nesingwary Safari in Nagrand."} end
if not DB[9856] then DB[9856]={id=9856,zoneId=3518,name="Windroc Mastery",level=67,minLevel=64,giver="Shado 'Fitz' Farstrider",giverType="NPC",giverId=18200,ender="Shado 'Fitz' Farstrider",enderType="NPC",enderId=18200,poiX=-1451,poiY=6341,wowhead="https://www.wowhead.com/wotlk/quest=9856",image="assets/images/quests/placeholder.png",xpDiff=6,money=74000,desc="You are ready, $c.  Ready to face the mother of all windrocs, Gutripper!  Honor demands that after hunting so many of her children that you give her the chance to defeat you!  Seek her out amongst the greater windroc far to the west.$B$BShould you survive, bring her eye to me.",logDesc="Bring the Eye of Gutripper to Fitz at the Nesingwary Safari in Nagrand.",choiceRewards={{id=25595,qty=1},{id=25594,qty=1},{id=25593,qty=1}}} end
if not DB[9857] then DB[9857]={id=9857,zoneId=3518,name="Talbuk Mastery",level=65,minLevel=64,giver="Harold Lane",giverType="NPC",giverId=18218,ender="Harold Lane",enderType="NPC",enderId=18218,rewardNextId=9858,poiX=-1455,poiY=6352,wowhead="https://www.wowhead.com/wotlk/quest=9857",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="I don't think that I'm up to the hunt today.  Do you think that you might take my place?$B$BI told Hemet that I was going to see about bagging us some of those talbuk that seem to be all over the place.  The stags are especially nice to hunt.  You can find them congregated around the nearby trees.$B$BThink that you could take care of that for me?",logDesc="Kill 12 Talbuk Stags and then return to Harold Lane at the Nesingwary Safari in Nagrand."} end
if not DB[9858] then DB[9858]={id=9858,zoneId=3518,name="Talbuk Mastery",level=66,minLevel=64,giver="Harold Lane",giverType="NPC",giverId=18218,ender="Harold Lane",enderType="NPC",enderId=18218,rewardNextId=9859,poiX=-1455,poiY=6352,wowhead="https://www.wowhead.com/wotlk/quest=9858",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="This darned scratch is getting the worst of me it would seem.  So, are you up to filling...<cough>... in for me again?$B$BThis time you're going to bag yourself some thorngrazers.  They're tougher and wilier than the stags, so keep your wits about you.  Look for them... <cough>... sheltered under the trees in the middle of Nagrand to the west and south.$B$BGo on, get out there and...<cough>... show Hemet what you're made of.  I'll be fine.",logDesc="Hunt down 12 Talbuk Thorngrazers and then return to Harold Lane at the Nesingwary Safari in Nagrand."} end
if not DB[9859] then DB[9859]={id=9859,zoneId=3518,name="Talbuk Mastery",level=66,minLevel=64,giver="Harold Lane",giverType="NPC",giverId=18218,ender="Harold Lane",enderType="NPC",enderId=18218,poiX=-1455,poiY=6352,wowhead="https://www.wowhead.com/wotlk/quest=9859",image="assets/images/quests/placeholder.png",xpDiff=6,money=70000,desc="<Wracking cough.>$B$BDon't worry about...<cough>... me.  I'll be fine.  It's just a...<cough>... scratch.$B$BJust the same, I think you'll... <cough>... have to fill in for me one more... <cough>... time.$B$BYou must seek out the great Bach'lor, king of...<cough>... the stags.  It's ok if you... <cough>... take friends along.$B$BBring me one of his hooves...<cough>, <cough>... as confirmation.$B$BLook for him...<cough>... leading his herd in the far west of Nagrand.",logDesc="Obtain the Hoof of Bach'lor and return it to Harold Lane at the Nesingwary Safari in Nagrand.",choiceRewards={{id=25543,qty=1},{id=25636,qty=1},{id=25545,qty=1}}} end
if not DB[9860] then DB[9860]={id=9860,zoneId=279,name="The New Directive",level=70,minLevel=68,giver="Archmage Alturus",giverType="NPC",giverId=17613,ender="Archmage Cedric",enderType="NPC",enderId=18165,poiX=-11120,poiY=-2015,wowhead="https://www.wowhead.com/wotlk/quest=9860",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Return to Cedric at once, $N.  The aid you've given the Violet Eye will not go unrewarded.$B$BThink what you want of us and our organization, $c, but gaining the favor of the archmages of Dalaran will not be something you regret.",logDesc="Speak to Archmage Cedric in the outskirts of Dalaran Crater.",rewards={{id=31113,qty=1}}} end
if not DB[9861] then DB[9861]={id=9861,zoneId=3518,name="The Howling Wind",level=67,minLevel=64,ender="Elementalist Morgh",enderType="NPC",enderId=18074,rewardNextId=9862,wowhead="https://www.wowhead.com/wotlk/quest=9861",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This amorphous mass of elemental air is speaking to you in a language that you cannot understand. You believe the language to be the tongue of the elements: Kalimag. Perhaps someone at the Throne of the Elements could shed some insight on this unusual find.",logDesc="Find someone at the Throne of the Elements that knows how to speak Kalimag and show them the Howling Wind."} end
if not DB[9862] then DB[9862]={id=9862,zoneId=3518,name="Murkblood Corrupters",level=67,minLevel=64,giver="Elementalist Morgh",giverType="NPC",giverId=18074,ender="Elementalist Morgh",enderType="NPC",enderId=18074,poiX=-782,poiY=6953,wowhead="https://www.wowhead.com/wotlk/quest=9862",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Murkblood are capturing and torturing the spirits of air! Murkblood are my kin: A tribe of the Broken who serve the vile Musel'ek, beast lord of Coilfang.$B$BThe air spirit states that the Murkblood putrifiers are capturing other spirits of air and using them to sow chaos into the ranks of the elements. It would seem that the Murkblood have recently sacked an orc village to the southwest known as Sunspring and are using powerful elemental magic to disturb the lake. Find the putrifiers and destroy them.",logDesc="Elementalist Morgh at the Throne of the Elements in Nagrand wants you to slay 5 Murkblood Putrifiers.",choiceRewards={{id=25566,qty=1},{id=25565,qty=1},{id=25567,qty=1}}} end
if not DB[9863] then DB[9863]={id=9863,zoneId=3518,name="Vile Idolatry",level=66,minLevel=64,giver="Farseer Kurkush",giverType="NPC",giverId=18066,ender="Farseer Kurkush",enderType="NPC",enderId=18066,poiX=-1410,poiY=7269,wowhead="https://www.wowhead.com/wotlk/quest=9863",image="assets/images/quests/placeholder.png",xpDiff=5,desc="With our leadership in ruin, we are left open to attacks from all sides. The foul Murkblood tribe could not have picked a better time to attack us!$B$BIn recent days, we have been subject to no less than 5 assaults from the Broken. They have even taken over our only other territorial holding in the area: Sunspring Post.$B$BWe must strike and show them that we are not powerless! Strike down the vile idolaters and bring me their twisted idols of worship so that they may ride the lightning.",logDesc="Farseer Kurkush at Garadar in Nagrand wants you to bring him 10 Murkblood Idols.",choiceRewards={{id=25570,qty=1},{id=25568,qty=1},{id=25569,qty=1}}} end
if not DB[9864] then DB[9864]={id=9864,zoneId=3518,name="The Missing War Party",level=67,minLevel=64,giver="Farseer Corhuk",giverType="NPC",giverId=18067,ender="Saurfang the Younger",enderType="NPC",enderId=18229,rewardNextId=9865,poiX=-1427,poiY=7268,wowhead="https://www.wowhead.com/wotlk/quest=9864",image="assets/images/quests/placeholder.png",xpDiff=2,desc="After the last Murkblood raid, a group of younglings decided to act. We tried to stop them but the rage had taken hold. It has now been one week since we last saw our beloved younglings.$B$BPlease, $r, you must find them! They have just barely reached adolescence. How can they expect to defeat such savages?$B$BThey took the road leading west out of town. Follow that road around and look for signs of our younglings.$B$BAnd $N, avoid Halaa if you value your life. It is a war-zone.",logDesc="Try and find the missing Garadar war party."} end
if not DB[9865] then DB[9865]={id=9865,zoneId=3518,name="Once Were Warriors",level=67,minLevel=64,giver="Saurfang the Younger",giverType="NPC",giverId=18229,ender="Saurfang the Younger",enderType="NPC",enderId=18229,rewardNextId=9866,poiX=-1285,poiY=8504,wowhead="https://www.wowhead.com/wotlk/quest=9865",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I do not know you, stranger, but I ask for your help. I feel shame for this, but I am only one orc.$B$BEmotions have surfaced that I have never felt. I... I seek vengeance. Blood for blood. Do your people ever feel this? I wish to pick up my axe and split my enemies in two. To swing the weapon until my arms fall lifelessly at my sides, exhausted.$B$BSunspring Post is directly south of this procession. It is there that you will find our enemies... Kill them... Kill them all...",logDesc="Kill 20 Murkblood Scavengers and 10 Murkblood Raiders."} end
if not DB[9866] then DB[9866]={id=9866,zoneId=3518,name="He Will Walk The Earth...",level=67,minLevel=64,giver="Saurfang the Younger",giverType="NPC",giverId=18229,ender="Farseer Corhuk",enderType="NPC",enderId=18067,poiX=-1285,poiY=8504,wowhead="https://www.wowhead.com/wotlk/quest=9866",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Will you do me one last honor, $N? I do not wish to return to Garadar. I believe that my destiny lies elsewhere - that I will serve a greater purpose someday.$B$BPlease, return to Farseer Corhuk and tell him that I will not be returning. That I cannot return. I must walk the earth... He will understand.",logDesc="Deliver the news to Farseer Corhuk at Garadar.",choiceRewards={{id=25574,qty=1},{id=25575,qty=1},{id=25576,qty=1}}} end
if not DB[9867] then DB[9867]={id=9867,zoneId=3518,name="Murkblood Leaders...",level=67,minLevel=64,giver="Farseer Margadesh",giverType="NPC",giverId=18068,ender="Farseer Margadesh",enderType="NPC",enderId=18068,poiX=-1430,poiY=7283,wowhead="https://www.wowhead.com/wotlk/quest=9867",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We have lost many friends in recent weeks.$B$BFor decades we have dealt with the ogres of Nagrand but now a new threat has arisen. The Broken tribe of Murkblood attacked our fishing village to the southwest, Sunspring Post, and managed to kill or evict all of the orcs that inhabited the town.$B$BWhile the others feel that the best course of action is to kill indiscriminately, I know that we must destroy their leadership. I do not know who their leader is but I suspect that you will know when you find him.",logDesc="Farseer Margadesh at Garadar in Nagrand wants you to bring him the Head of Ortor of Murkblood. ",choiceRewards={{id=25583,qty=1},{id=25585,qty=1},{id=25584,qty=1}}} end
if not DB[9868] then DB[9868]={id=9868,zoneId=3518,name="The Totem of Kar'dash",level=67,minLevel=64,giver="Mag'har Captive",giverType="NPC",giverId=18210,ender="Garrosh",enderType="NPC",enderId=18063,poiX=-1584,poiY=8565,wowhead="https://www.wowhead.com/wotlk/quest=9868",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Thank you, stranger. They would have surely killed me had it not been for you.$B$BI was kidnapped by these Murkbloods 3 nights ago during a nighttime raid on Garadar. What I have since uncovered may very well shake the foundation of the Outland: these savages seek to recover the totem of Kar'dash! We cannot allow the totem to fall into the hands of the Murkbloods!$B$BYou must help me escape. And stranger, if I do not make it back to Garadar, you must tell Garrosh what happened here... ",logDesc="Escort the Mag'har Captive out of Sunspring Post. Speak to Garrosh at Garadar if you succeed."} end
if not DB[9869] then DB[9869]={id=9869,zoneId=3518,name="The Throne of the Elements",level=66,minLevel=64,giver="Elementalist Ioki",giverType="NPC",giverId=18233,ender="Elementalist Sharvak",enderType="NPC",enderId=18072,poiX=-2492,poiY=7229,wowhead="https://www.wowhead.com/wotlk/quest=9869",image="assets/images/quests/placeholder.png",xpDiff=2,money=35000,desc="Greetings, $r. I am Ioki, elementalist of the Earthen Ring. I have come to Telaar to inform the Kurenai of the state of the elements.$B$BCould I ask a favor of you? Would you travel to the Throne of the Elements in the northern hills of Nagrand, beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Telaar safely? She will surely reward you for this small deed.",logDesc="Elementalist Ioki wants you to travel to the Throne of the Elements and speak with Elementalist Sharvak."} end
if not DB[9870] then DB[9870]={id=9870,zoneId=3518,name="The Throne of the Elements",level=66,minLevel=64,giver="Elementalist Yal'hah",giverType="NPC",giverId=18234,ender="Elementalist Sharvak",enderType="NPC",enderId=18072,poiX=-1357,poiY=7233,wowhead="https://www.wowhead.com/wotlk/quest=9870",image="assets/images/quests/placeholder.png",xpDiff=2,money=35000,desc="Greetings, $r. I am Yal'hah, elementalist of the Earthen Ring. I have come to Garadar to inform the Mag'har of the state of the elements.$B$BCould I ask a favor of you? Would you travel to the Throne of the Elements in the northern hills of Nagrand, beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Garadar safely? She will surely reward you for this small deed.",logDesc="Elementalist Yal'hah wants you to travel to the Throne of the Elements and speak with Elementalist Sharvak."} end
if not DB[9871] then DB[9871]={id=9871,zoneId=3518,name="Murkblood Invaders",level=67,minLevel=64,ender="Arechron",enderType="NPC",enderId=18183,rewardNextId=9873,wowhead="https://www.wowhead.com/wotlk/quest=9871",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The parchment holds a crudely painted map of Nagrand. There is a big red 'X' where Telaar would be on the map. It would seem that these savages are planning an attack on the city. Take the Murkblood invasion plans to Arechron in Telaar.$B",logDesc="Take the Murkblood Invasion Plans to Arechron at Telaar in Nagrand."} end
if not DB[9872] then DB[9872]={id=9872,zoneId=3518,name="Murkblood Invaders",level=67,minLevel=64,ender="Garrosh",enderType="NPC",enderId=18063,wowhead="https://www.wowhead.com/wotlk/quest=9872",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The parchment holds a crudely painted map of Nagrand. There is a big red 'X' where Garadar would be on the map. It would seem that these savages are planning an attack on the city. Take the Murkblood invasion plans to Garrosh in Garadar.",logDesc="Take the Murkblood Invasion Plans to Garrosh."} end
if not DB[9873] then DB[9873]={id=9873,zoneId=3518,name="Ortor My Old Friend...",level=67,minLevel=64,giver="Arechron",giverType="NPC",giverId=18183,ender="Arechron",enderType="NPC",enderId=18183,poiX=-2489,poiY=7231,wowhead="https://www.wowhead.com/wotlk/quest=9873",image="assets/images/quests/placeholder.png",xpDiff=5,desc="These invasion plans were written by someone I once knew. Ortor of Murkblood, once a noble Broken, versed in the way of the elements, now a muck addled yes-man of Musel'ek the bog lord.$B$BThe plans state that they have taken over an orc village northwest of here known as Sunspring.$B$BTravel to Sunspring Post and rid the world of Ortor of Murkblood. What you do, you do for the good of us all...",logDesc="Arechron at Telaar in Nagrand wants you to kill Ortor of Murkblood.",choiceRewards={{id=25583,qty=1},{id=25584,qty=1},{id=25585,qty=1}}} end
if not DB[9874] then DB[9874]={id=9874,zoneId=3518,name="Stopping the Spread",level=67,minLevel=64,giver="Otonbu the Sage",giverType="NPC",giverId=18222,ender="Otonbu the Sage",enderType="NPC",enderId=18222,poiX=-2613,poiY=7286,wowhead="https://www.wowhead.com/wotlk/quest=9874",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I have just gotten word of a catastrophe of epic proportions, $N. The foul Murkblood have sacked the orc village of Sunspring Post, northwest of here, and murdered its residents. To make matters worse, they have begun dumping the bodies into Sunspring Lake. Should those bodies rot, our primary source of water in the region will be compromised.$B$BIt's a gruesome task that I give you next but it must be done. Take this enchanted torch and return to Sunspring. Burn all of the rotting orc corpses...",logDesc="Otonbu the Sage at Telaar in Nagrand wants you to use the Torch of Liquid Fire to destroy 10 Sunspring Villager corpses. Return the Torch of Liquid Fire when the task is complete.$B",choiceRewards={{id=25570,qty=1},{id=25568,qty=1},{id=25569,qty=1}}} end
if not DB[9875] then DB[9875]={id=9875,zoneId=3521,name="Uncatalogued Species",level=63,minLevel=60,ender="Lauranna Thar'well",enderType="NPC",enderId=17909,wowhead="https://www.wowhead.com/wotlk/quest=9875",image="assets/images/quests/placeholder.png",desc="Lauranna must've missed this particular plant.  You're certain you've discovered a species not yet catalogued by Lauranna's work.  You'd best show it to her to see what she makes of it.",logDesc="Bring the Uncatalogued Species to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh."} end
if not DB[9876] then DB[9876]={id=9876,zoneId=3905,name="Failed Incursion",level=65,minLevel=62,giver="Ysiel Windsinger",giverType="NPC",giverId=17841,ender="Watcher Jhang",enderType="NPC",enderId=17884,poiX=-143,poiY=5534,wowhead="https://www.wowhead.com/wotlk/quest=9876",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I sent a small group of our druids to investigate the drain you discovered inside of Serpent Lake.  They were expected to return shortly after.  Needless to say, they did not.$B$BYou are amongst our most capable allies; I ask you to seek them and find out what became of them.",logDesc="Ysiel Windsinger wants you to look for signs of Cenarion Expedition Druids near the entrance to Coilfang Reservoir in Zangarmarsh."} end
if not DB[9877] then DB[9877]={id=9877,zoneId=3433,name="A Restorative Draught",level=20,minLevel=17,giver="Arcanist Janeda",giverType="NPC",giverId=16240,ender="Apothecary Renzithen",enderType="NPC",enderId=16198,rewardNextId=9164,poiX=7203,poiY=-7093,wowhead="https://www.wowhead.com/wotlk/quest=9877",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The battle against the Scourge is not one without casualties.  Many are slain every day yet many more meet a worse fate.$B$BIt is not uncommon for the Scourge to take prisoners.  Death would be preferable to what awaits them in Deatholme.  They're interrogated and tortured while under the effects of horrible will-breaking poisons.$B$BApothecary Renzithen in Tranquillien has developed a remedy; go to him and retrieve this restorative draught.",logDesc="Speak to Apothecary Renzithen in Tranquillien."} end
if not DB[9878] then DB[9878]={id=9878,zoneId=3518,name="Solving the Problem",level=67,minLevel=64,giver="Poli'lukluk the Wiser",giverType="NPC",giverId=18224,ender="Poli'lukluk the Wiser",enderType="NPC",enderId=18224,poiX=-2622,poiY=7287,wowhead="https://www.wowhead.com/wotlk/quest=9878",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The appearance of the Murkblood in Nagrand has had a profound negative impact on our environment. The elementals are all in flux which has, in turn, greatly disturbed the wildlife. Worse yet, the razing of Sunspring Post has reignited the hatred that the orcs held for our people.$B$BWhile the Kurenai are a different tribe than the Murkblood, all an orc sees is Broken.$B$BWe must make an effort to solve this dilemma. Travel to Sunspring Post, northwest of here, and resolve the Murkblood problem.",logDesc="Poli'lukluk the Wiser at Telaar in Nagrand wants you to kill 10 Murkblood Scavengers and 5 Murkblood Raiders.",choiceRewards={{id=25577,qty=1},{id=25578,qty=1},{id=25579,qty=1}}} end
if not DB[9879] then DB[9879]={id=9879,zoneId=3518,name="The Totem of Kar'dash",level=67,minLevel=64,giver="Kurenai Captive",giverType="NPC",giverId=18209,ender="Arechron",enderType="NPC",enderId=18183,poiX=-1517,poiY=8462,wowhead="https://www.wowhead.com/wotlk/quest=9879",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I would have been killed had you not come along, stranger. They have already murdered so many Kurenai in their search for a lost relic.$B$BWhat they seek is the totem of Kar'dash. Why they think that we would know anything about this totem, I cannot understand. Is a totem not an orcish implement by nature?$B$BThis information must be taken back to Arechron. Perhaps he knows why Murkblood are kidnapping Kurenai and torturing them for information regarding an orcish device.$B$BLet's go before more come.",logDesc="Escort the Kurenai Captive out of Sunspring Post. Speak to Arechron at Telaar if you succeed."} end
if not DB[9880] then DB[9880]={id=9880,zoneId=3483,name="Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin Cap",level=60,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=9880",image="assets/images/quests/placeholder.png",xpDiff=5,rewards={{id=24520,qty=2}}} end
if not DB[9881] then DB[9881]={id=9881,zoneId=3483,name="Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap",level=60,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=9881",image="assets/images/quests/placeholder.png",xpDiff=5,rewards={{id=24522,qty=2}}} end
if not DB[9882] then DB[9882]={id=9882,zoneId=3518,name="Stealing from Thieves",level=66,minLevel=64,giver="Gezhe",giverType="NPC",giverId=18265,ender="Gezhe",enderType="NPC",enderId=18265,poiX=-2087,poiY=8563,wowhead="https://www.wowhead.com/wotlk/quest=9882",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="Nexus Prince Haramad has ordered us to not begin work inside of Oshu'gun as it might anger a certain powerful naaru.  Sort of puts a damper on our operation.$B$BI think I might've found a loophole, however.$B$BYou see, we're not the only ethereals drawn to this colossal diamond.  A thief called Gava'xi has led a band of rogue ethereals into Oshu'gun and they've begun to dislodge large fragments from it.$B$BYour job, $r, is to go there and retrieve what is rightfully ours.",logDesc="Obtain 10 Oshu'gun Crystal Fragments and bring them to Gezhe at Aeris Landing in Nagrand."} end
if not DB[9883] then DB[9883]={id=9883,zoneId=3518,name="More Crystal Fragments",level=66,minLevel=64,giver="Gezhe",giverType="NPC",giverId=18265,ender="Gezhe",enderType="NPC",enderId=18265,poiX=-2087,poiY=8563,wowhead="https://www.wowhead.com/wotlk/quest=9883",image="assets/images/quests/placeholder.png"} end
if not DB[9884] then DB[9884]={id=9884,zoneId=3518,name="Membership Benefits",level=70,minLevel=63,giver="Gezhe",giverType="NPC",giverId=18265,ender="Gezhe",enderType="NPC",enderId=18265,poiX=-2087,poiY=8563,wowhead="https://www.wowhead.com/wotlk/quest=9884",image="assets/images/quests/placeholder.png",rewards={{id=25419,qty=1}}} end
if not DB[9885] then DB[9885]={id=9885,zoneId=3518,name="Membership Benefits",level=70,minLevel=63,giver="Gezhe",giverType="NPC",giverId=18265,ender="Gezhe",enderType="NPC",enderId=18265,poiX=-2087,poiY=8563,wowhead="https://www.wowhead.com/wotlk/quest=9885",image="assets/images/quests/placeholder.png",rewards={{id=25422,qty=1}}} end
if not DB[9886] then DB[9886]={id=9886,zoneId=3518,name="Membership Benefits",level=70,minLevel=63,giver="Gezhe",giverType="NPC",giverId=18265,ender="Gezhe",enderType="NPC",enderId=18265,poiX=-2087,poiY=8563,wowhead="https://www.wowhead.com/wotlk/quest=9886",image="assets/images/quests/placeholder.png",rewards={{id=25424,qty=1}}} end
if not DB[9887] then DB[9887]={id=9887,zoneId=3518,name="Membership Benefits",level=70,minLevel=63,giver="Gezhe",giverType="NPC",giverId=18265,ender="Gezhe",enderType="NPC",enderId=18265,poiX=-2087,poiY=8563,wowhead="https://www.wowhead.com/wotlk/quest=9887",image="assets/images/quests/placeholder.png",rewards={{id=25423,qty=1}}} end
if not DB[9888] then DB[9888]={id=9888,zoneId=3519,name="The Impotent Leader",level=65,minLevel=64,giver="Jorin Deadeye",giverType="NPC",giverId=18106,ender="Kilrath",enderType="NPC",enderId=18273,rewardNextId=9889,poiX=-1344,poiY=7226,wowhead="https://www.wowhead.com/wotlk/quest=9888",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I have escaped certain death, surviving a cowardly nighttime attack by Boulderfist ogres upon my village.$B$BBut I ask you, stranger: For what?$B$B<Jorin points to Garrosh.>$B$BHe has refused to give us assistance. Ogres are rampaging through my town and he sits here, weeping into a fire. What has become of us? What will become of us?$B$BI've sent a scout, Kilrath, to the village, now the Bleeding Hollow Ruins. Will you find him and give him your assistance? He hides on the border of Nagrand and Terokkar.",logDesc="Jorin Deadeye has asked that you find and speak with Kilrath."} end
if not DB[9889] then DB[9889]={id=9889,zoneId=3519,name="Don't Kill the Fat One",level=65,minLevel=64,giver="Kilrath",giverType="NPC",giverId=18273,ender="Unkor the Ruthless",enderType="NPC",enderId=18262,rewardNextId=9890,poiX=-3191,poiY=6016,wowhead="https://www.wowhead.com/wotlk/quest=9889",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I have been watching these beasts for days. The fat one says that he is waiting for something. What he is waiting for, however, is a mystery.$B$BI have a plan but it is going to involve some violence on your part. You will need to kill several of his subordinates and then beat him within an inch of his life. Do this and I am certain he will tell us everything that we need to know.",logDesc="Kilrath in Terokkar Forest has asked that you kill 10 Boulderfist Invaders and beat Unkor the Ruthless until he talks."} end
if not DB[9890] then DB[9890]={id=9890,zoneId=3519,name="Success!",level=65,minLevel=64,giver="Unkor the Ruthless",giverType="NPC",giverId=18262,ender="Kilrath",enderType="NPC",enderId=18273,rewardNextId=9891,poiX=-3277,poiY=6000,wowhead="https://www.wowhead.com/wotlk/quest=9890",image="assets/images/quests/placeholder.png",xpDiff=1,desc="For many years, Boulderfist ruled all ogres in the Outland. The ogres were united under Krol and content with the lands that they were given. In the past few months, we have lost many ogres to a new clan known as Warmaul. Warmaul has taken most of our land in Nagrand and killed many of our people.$B$BWe had no choice but to take this town. We are being exterminated...$B$BKrol has gone missing and Boulderfist is in turmoil. Lantresor of the Blade rules in his absence.$B",logDesc="Take the information that you beat out of Unkor back to Kilrath in Terokkar Forest."} end
if not DB[9891] then DB[9891]={id=9891,zoneId=3518,name="Because Kilrath is a Coward",level=65,minLevel=64,giver="Kilrath",giverType="NPC",giverId=18273,ender="Jorin Deadeye",enderType="NPC",enderId=18106,rewardNextId=9906,poiX=-3191,poiY=6016,wowhead="https://www.wowhead.com/wotlk/quest=9891",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Take what you have learned and tell Jorin at Garadar. I can assure you that he won't be happy to know that our village was destroyed and many of our people killed because the ogres needed more space.$B$BMay the ancestors watch over you... I will be hiding in the bushes if you need me for anything else.",logDesc="Take the information that you beat out of Unkor to Jorin Deadeye at Garadar in Nagrand."} end
if not DB[9892] then DB[9892]={id=9892,zoneId=3518,name="More Obsidian Warbeads",level=67,minLevel=64,giver="Gezhe",giverType="NPC",giverId=18265,ender="Gezhe",enderType="NPC",enderId=18265,poiX=-2087,poiY=8563,wowhead="https://www.wowhead.com/wotlk/quest=9892",image="assets/images/quests/placeholder.png",money=3800} end
if not DB[9893] then DB[9893]={id=9893,zoneId=3518,name="Obsidian Warbeads",level=67,minLevel=64,giver="Gezhe",giverType="NPC",giverId=18265,ender="Gezhe",enderType="NPC",enderId=18265,poiX=-2087,poiY=8563,wowhead="https://www.wowhead.com/wotlk/quest=9893",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="All this waiting around for Oshu'gun to be ready for digging is eating into our profits, $N.$B$BFortunately, I've devised an alternate source of income.  The ogres of Nagrand wear warbeads made of obsidian, a mineral that commands a hefty price in many other worlds.$B$BZerid already has had to take care a few of the brutes as a matter of security.  Think of the warbeads as an added bonus.  Or better yet, don't think about it too much and just bring them to me.",logDesc="Bring 10 Obsidian Warbeads to Gezhe at Aeris Landing in Nagrand."} end
if not DB[9894] then DB[9894]={id=9894,zoneId=3521,name="Safeguarding the Watchers",level=62,minLevel=60,giver="Windcaller Blackhoof",giverType="NPC",giverId=18070,ender="Windcaller Blackhoof",enderType="NPC",enderId=18070,poiX=-234,poiY=5435,wowhead="https://www.wowhead.com/wotlk/quest=9894",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="In your travels, you might have encountered some of the expedition's watchers. They do the majority of the field work: documenting the unique inhabitants of the marsh, collecting samples, and making contact with sentient species.$B$BThe safety of the watchers is paramount, $c. We've had to recall the watchers we sent to explore Funggor Cavern to the south, because of marshbeast attacks. Warden Hamoot believes that killing their leader, Lord Klaq, will bring a swift end to the attacks. ",logDesc="Kill Lord Klaq and return to Windcaller Blackhoof at the Cenarion Refuge."} end
if not DB[9895] then DB[9895]={id=9895,zoneId=3521,name="The Dying Balance",level=62,minLevel=60,giver="Lethyn Moonfire",giverType="NPC",giverId=17834,ender="Lethyn Moonfire",enderType="NPC",enderId=17834,poiX=-181,poiY=5527,wowhead="https://www.wowhead.com/wotlk/quest=9895",image="assets/images/quests/placeholder.png",xpDiff=6,money=27000,desc="Have you observed your surroundings closely, $N? This is an ailing landscape, struggling to keep itself in balance and losing the fight.$B$BIf you know where to look, you can see the symptoms. Members of some species rapidly outgrow their peers and become more aggressive.$B$BA good example of this uncontrolled growth is the marshtrekker Boglash. If you wish to see it for yourself, look no further than the waterways south of the refuge.$B$BBe prepared to defend yourself. The creature knows no mercy.",logDesc="Locate and deal with Boglash, then return to Lethyn Moonfire at Cenarion Refuge."} end
if not DB[9896] then DB[9896]={id=9896,zoneId=3521,name="Blacksting's Bane",level=62,minLevel=60,giver="Prospector Conall",giverType="NPC",giverId=18295,ender="Prospector Conall",enderType="NPC",enderId=18295,poiX=281,poiY=6029,wowhead="https://www.wowhead.com/wotlk/quest=9896",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="By Khaz'goroth's flaming navel, it's hot here! I can't blame the first party for leaving, but everyone knows 'twasn't the heat that drove them away. No, it was Blacksting, although they won't admit it.$B$BThey were camped just to the south of the glowing draenei towers to the west, just north of the Feralfen Village, when the giant wasp appears out of nowhere and attacks! I can't wait to see the looks on their faces when I bring the creature's stinger back to Ironforge and show it to them!",logDesc="Bring Blacksting's Stinger to Prospector Conall at Telredor.",choiceRewards={{id=31786,qty=1},{id=31787,qty=1},{id=31788,qty=1},{id=31789,qty=1}}} end
if not DB[9897] then DB[9897]={id=9897,zoneId=3518,name="I'm Saved!",level=65,minLevel=64,giver="Kristen Dipswitch",giverType="NPC",giverId=18294,ender="Harold Lane",enderType="NPC",enderId=18218,poiX=-1249,poiY=6236,wowhead="https://www.wowhead.com/wotlk/quest=9897",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="I don't mind sharing.  I'm just glad to be saved from that creep, Gankly!  And I collected tons of skins from Zangarmarsh, so it's no problem at all!",logDesc="Give the Bundle of Skins to Harold Lane at the Nesingwary Safari in Nagrand."} end
if not DB[9898] then DB[9898]={id=9898,zoneId=3521,name="Nothin' Says Lovin' Like a Big Stinger",level=62,minLevel=60,giver="Reavij",giverType="NPC",giverId=18012,ender="Reavij",enderType="NPC",enderId=18012,poiX=124,poiY=5204,wowhead="https://www.wowhead.com/wotlk/quest=9898",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="She will be mine. Oh yes - she will be mine.$B$BIsn't Magasha the most beautiful troll you've ever seen? I have to find a way to win her heart. Sure, she has her eye on Zurai, but that is about to change. My foolproof plan will see to that.$B$BAll I need is a way to demonstrate my superior hunting skills, and that's where you come in my friend. There's a gigantic bog wasp known as Blacksting that roams the area south of the glowing draenei towers to the west. Bring me its stinger and I'll work my magic.",logDesc="Bring Blacksting's Stinger to Reavij at Swamprat Post.",choiceRewards={{id=31786,qty=1},{id=31787,qty=1},{id=31788,qty=1},{id=31789,qty=1}}} end
if not DB[9899] then DB[9899]={id=9899,zoneId=3521,name="A Job Undone",level=62,minLevel=60,giver="Magasha",giverType="NPC",giverId=18016,ender="Magasha",enderType="NPC",enderId=18016,poiX=114,poiY=5234,wowhead="https://www.wowhead.com/wotlk/quest=9899",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Someone needs to find a way to make Reavij come to his senses! He's ignoring his duty and instead, he's devoting all his energy to getting my attention. I've tried ignoring him and telling him to stop. Nothing seems to work.$B$BUntil he gets over this, I'm left cleaning up after him. He was supposed to have dealt with Sporewing, but I'll bet the monster is alive and well. If you have time, would you mind going to the western part of the Dead Mire and killing the bat? I'll deal with Reavij in the meantime.",logDesc="Magasha at Swamprat Post wants you to kill Sporewing.",choiceRewards={{id=33457,qty=5},{id=33458,qty=5},{id=33459,qty=5},{id=33460,qty=5},{id=33461,qty=5},{id=33462,qty=5}}} end
if not DB[9900] then DB[9900]={id=9900,zoneId=3518,name="Gava'xi",level=67,minLevel=65,giver="Zerid",giverType="NPC",giverId=18276,ender="Zerid",enderType="NPC",enderId=18276,poiX=-2100,poiY=8595,wowhead="https://www.wowhead.com/wotlk/quest=9900",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="The presence of rogue ethereals in this area might amuse Gezhe, who sees nothing but opportunity wherever we go, but it's a true threat to the security of our operations.$B$BTheir leader, Gava'xi, is a dangerous criminal and I've made it my top priority to see to it that he is neutralized.$B$BIf you're looking to make yourself useful, go and take care of Gava'xi.  I will see to it that you're rewarded properly.",logDesc="Slay Gava'xi near Oshu'gun and return to Zerid at Aeris Landing in Nagrand.",choiceRewards={{id=25637,qty=1},{id=25634,qty=1},{id=25544,qty=1}}} end
if not DB[9901] then DB[9901]={id=9901,zoneId=3521,name="Unfinished Business",level=62,minLevel=60,giver="Prospector Conall",giverType="NPC",giverId=18295,ender="Prospector Conall",enderType="NPC",enderId=18295,poiX=281,poiY=6029,wowhead="https://www.wowhead.com/wotlk/quest=9901",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="The first expedition the league sent reported encountering a gigantic spore bat they'd taken to calling Sporewing. They had to leave in a hurry, so they didn't have the chance to kill him while they were here, so I figured I'd finish the job for them.$B$BWhat's left of their report suggests that the creature can be found in the southwestern parts of the Dead Mire. I think Vindicator Idaar mentioned that it's to the northeast of Telredor.",logDesc="Prospector Conall at Telredor wants you to kill Sporewing.",choiceRewards={{id=27503,qty=5},{id=27501,qty=5},{id=27502,qty=5},{id=27499,qty=5},{id=27498,qty=5},{id=27500,qty=5}}} end
if not DB[9902] then DB[9902]={id=9902,zoneId=3521,name="The Terror of Marshlight Lake",level=64,minLevel=62,giver="Puluu",giverType="NPC",giverId=18009,ender="Puluu",enderType="NPC",enderId=18009,poiX=975,poiY=7422,wowhead="https://www.wowhead.com/wotlk/quest=9902",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Traveling through naga-infested lands has shown me the cruel truth about how my less fortunate brethren are treated. At Marshlight Lake, to the southwest, I observed a particularly malicious taskmaster playing a deadly game. He orders his slaves out to the islands in Marshlight Lake when he knows that Terrorclaw, a giant bogstrok, is ready to feed.$B$BI needn't describe what results. We are too few to take on the naga directly, but we can deprive them of their amusement by killing their pet.",logDesc="Slay Terrorclaw and return to Puluu at the Orebor Harborage.",choiceRewards={{id=25924,qty=1},{id=25923,qty=1},{id=25922,qty=1},{id=25925,qty=1}}} end
if not DB[9903] then DB[9903]={id=9903,zoneId=3521,name="The Biggest of Them All",level=64,minLevel=62,giver="Zurjaya",giverType="NPC",giverId=18018,ender="Zurjaya",enderType="NPC",enderId=18018,poiX=273,poiY=7854,wowhead="https://www.wowhead.com/wotlk/quest=9903",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="You've dealt with most of the little hydra, but I doubt Mragesh was impressed by your display. He's a cunning, ferocious beast and he's dogged many an angler in his time.$B$BI intend to be the last one he'll ever bother. He's bound to be hiding deep in the waters of Serpent Lake, to the northeast. He's a has-been; he just doesn't know it yet.",logDesc="Slay Mragesh and return to Zurjaya in Zabra'jin.",choiceRewards={{id=28103,qty=5},{id=28102,qty=5}}} end
if not DB[9904] then DB[9904]={id=9904,zoneId=3521,name="Pursuing Terrorclaw",level=64,minLevel=62,giver="Zurjaya",giverType="NPC",giverId=18018,ender="Zurjaya",enderType="NPC",enderId=18018,poiX=273,poiY=7854,wowhead="https://www.wowhead.com/wotlk/quest=9904",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="I've caught every kind of fish that lives in the marsh, but there's one that eludes me. Sure, I've caught eels and mudfin frenzies. But the last time I was out on one of the islands in Marshlight Lake, I hooked a gigantic bogstrok that snapped my line and got away.$B$BTerrorclaw, he's called, and I won't rest until he's dead. He's too big for any fisherman to catch, so I suppose we'll just have to kill him the old-fashioned way.",logDesc="Kill Terrorclaw and return to Zurjaya at Zabra'jin.",choiceRewards={{id=25924,qty=1},{id=25923,qty=1},{id=25922,qty=1},{id=25925,qty=1}}} end
if not DB[9905] then DB[9905]={id=9905,zoneId=3521,name="Maktu's Revenge",level=64,minLevel=62,giver="Maktu",giverType="NPC",giverId=18010,ender="Maktu",enderType="NPC",enderId=18010,poiX=1021,poiY=7383,wowhead="https://www.wowhead.com/wotlk/quest=9905",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Last time Maktu was out hunting hydras for hides at Serpent Lake, he was attacked by the biggest hydra he's ever seen. Maktu reached for his spear, but it was too late. He had just enough time to escape becoming hydra food.$B$BWho knows? Maybe next time, Maktu not be so lucky. Maktu wants to be there so there won't be a next time. Will you help Maktu get his revenge on Mragesh?",logDesc="Locate and kill Mragesh, then return to Maktu at the Orebor Harborage.",choiceRewards={{id=28103,qty=5},{id=28102,qty=5}}} end
if not DB[9906] then DB[9906]={id=9906,zoneId=3518,name="Message in a Battle",level=65,minLevel=64,giver="Jorin Deadeye",giverType="NPC",giverId=18106,ender="Jorin Deadeye",enderType="NPC",enderId=18106,rewardNextId=9907,poiX=-1344,poiY=7226,wowhead="https://www.wowhead.com/wotlk/quest=9906",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Ogres are moved by one thing: Might. If we expose ourselves to them as being weak, they will take advantage of that weakness and wipe us out.$B$BGarrosh might be ready to lie down and let the ogre dogs take our lands but I am not! I need you to deliver a message to the Boulderfist, $N. The only type of message that they are capable of understanding: Brutality.$B$BTravel to the Burning Blade Ruins, southeast of here and show them the might of the Mag'har.$B$BAnd $N, check in with the others before leaving.",logDesc="Jorin Deadeye at Garadar in Nagrand has asked that you slay 8 Boulderfist Crushers and 8 Boulderfist Mystics."} end
if not DB[9907] then DB[9907]={id=9907,zoneId=3518,name="An Audacious Advance",level=66,minLevel=64,giver="Jorin Deadeye",giverType="NPC",giverId=18106,ender="Jorin Deadeye",enderType="NPC",enderId=18106,rewardNextId=10107,poiX=-1344,poiY=7226,wowhead="https://www.wowhead.com/wotlk/quest=9907",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Directly west of here you will find the Halaani Basin. Within the basin are the twin clefts of Nagrand: Northwind and Southwind. Boulderfist shock troops use the clefts to hide their ogre mounds.$B$BI need you to track down those troops and kill all that you encounter in the name of Mag'har.",logDesc="Jorin Deadeye at Garadar in Nagrand has asked that you slay 10 Boulderfist Warriors and 10 Boulderfist Mages.",choiceRewards={{id=25622,qty=1},{id=25623,qty=1},{id=25624,qty=1}}} end
if not DB[9908] then DB[9908]={id=9908,zoneId=3483,name="Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin",level=60,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=9908",image="assets/images/quests/placeholder.png",rewards={{id=24520,qty=2}}} end
if not DB[9909] then DB[9909]={id=9909,zoneId=3483,name="Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin",level=60,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=9909",image="assets/images/quests/placeholder.png",rewards={{id=24522,qty=2}}} end
if not DB[9910] then DB[9910]={id=9910,zoneId=3518,name="Standards and Practices",level=65,minLevel=64,giver="Elkay'gan the Mystic",giverType="NPC",giverId=18300,ender="Elkay'gan the Mystic",enderType="NPC",enderId=18300,rewardNextId=9916,poiX=-1341,poiY=7222,wowhead="https://www.wowhead.com/wotlk/quest=9910",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If you're venturing into the Burning Blade Ruins, I have a task for you. Take these Mag'har battle standards and place them at three distinct locations in the ogre compound. An area of high visibility is recommended. Look for the gigantic flaming pyres on the upper levels. Place a standard near the first, second, and third Burning Blade pyres.$B$BThe standard will leave a lasting impression upon any ogres who may have missed the battle.",logDesc="Elkay'gan the Mystic at Garadar in Nagrand wants you to use the Mag'har Battle Standard at the First Burning Blade Pyre, Second Burning Blade Pyre, and Third Burning Blade Pyre. Return the left-over Mag'har Battle Standards to him when you are finished."} end
if not DB[9911] then DB[9911]={id=9911,zoneId=3521,name="The Count of the Marshes",level=64,minLevel=62,ender="Watcher Leesa'oh",enderType="NPC",enderId=17831,wowhead="https://www.wowhead.com/wotlk/quest=9911",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="This bloody mandible comes from an unbelievably large creature. The nether ray that it belonged to has to be the largest ever seen in Zangarmarsh. Judging from the condition of the mandible, the count must've abandoned a diet of carrion in favor of living flesh.$B$BSurely the Cenarion Expedition would be interested in such a specimen. Watcher Leesa'oh has a small camp to the west of Quagg Ridge.",logDesc="Bring \"Count\" Ungula's Mandible to Watcher Leesa'oh at the Cenarion Outpost in Zangarmarsh."} end
if not DB[9912] then DB[9912]={id=9912,zoneId=3521,name="The Cenarion Expedition",level=62,minLevel=61,giver="Amythiel Mistwalker",giverType="NPC",giverId=16885,ender="Ysiel Windsinger",enderType="NPC",enderId=17841,poiX=-315,poiY=4711,wowhead="https://www.wowhead.com/wotlk/quest=9912",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body.$B$BThe expedition's leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.",logDesc="Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh."} end
if not DB[9913] then DB[9913]={id=9913,zoneId=3518,name="The Consortium Needs You!",level=66,minLevel=64,giver="Consortium Recruiter",giverType="NPC",giverId=18335,ender="Gezhe",enderType="NPC",enderId=18265,poiX=-2528,poiY=7472,wowhead="https://www.wowhead.com/wotlk/quest=9913",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My organization, the Consortium, is looking for a few resourceful individuals just like yourself.  You'll be hard pressed to find ethereals more honest, hard-working or pleasant to be around than us.$B$BAll we require is loyalty, dedication and a reasonable amount of moral flexibility.  If you're interested, speak to Gezhe, our ground operations leader.  You will find him at Aeris Landing, north of Oshu'gun.",logDesc="Report to Gezhe at Aeris Landing in Nagrand."} end
if not DB[9914] then DB[9914]={id=9914,zoneId=3518,name="A Head Full of Ivory",level=66,minLevel=64,giver="Shadrek",giverType="NPC",giverId=18333,ender="Shadrek",enderType="NPC",enderId=18333,poiX=-2050,poiY=8540,wowhead="https://www.wowhead.com/wotlk/quest=9914",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="Ivory is a much sought after prize.  I have many customers lined up in far off places to purchase it.$B$BI could be convinced to let you in on a cut of the profits.$B$BThe wild elekk roaming Nagrand have the high quality of tusks that I'm after.  Steer clear of the bull elekk; their ivory isn't in the condition that I desire.$B$BOh and don't worry, it's not poaching; I have an understanding with both the orcs and the draenei.$B$BDo you and I have an understanding?",logDesc="Collect 3 Pair of Ivory Tusks and return them to Shadrek at Aeris Landing in Nagrand."} end
if not DB[9915] then DB[9915]={id=9915,zoneId=3518,name="More Heads Full of Ivory",level=66,minLevel=64,giver="Shadrek",giverType="NPC",giverId=18333,ender="Shadrek",enderType="NPC",enderId=18333,poiX=-2050,poiY=8540,wowhead="https://www.wowhead.com/wotlk/quest=9915",image="assets/images/quests/placeholder.png"} end
if not DB[9916] then DB[9916]={id=9916,zoneId=3518,name="Bleeding Hollow Supply Crates",level=66,minLevel=64,giver="Elkay'gan the Mystic",giverType="NPC",giverId=18300,ender="Elkay'gan the Mystic",enderType="NPC",enderId=18300,poiX=-1341,poiY=7222,wowhead="https://www.wowhead.com/wotlk/quest=9916",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Boulderfist have moved the supplies they stole from our village to the twin clefts of Nagrand, found west of here in the Halaani Basin.$B$BWhile you are in the area, keep your eye out for the supply crates. If we can get those back, it would ease much of the burden that has fallen upon the matrons of Garadar.",logDesc="Elkay'gan the Mystic at Garadar in Nagrand wants you to recover 10 Bleeding Hollow Supply Crates.",choiceRewards={{id=25630,qty=1},{id=25629,qty=1},{id=25628,qty=1}}} end
if not DB[9917] then DB[9917]={id=9917,zoneId=3518,name="Do My Eyes Deceive Me",level=65,minLevel=64,giver="Huntress Bintook",giverType="NPC",giverId=18353,ender="Huntress Bintook",enderType="NPC",enderId=18353,rewardNextId=9918,poiX=-2556,poiY=7254,wowhead="https://www.wowhead.com/wotlk/quest=9917",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Do my eyes deceive me or is there an ogre hunting party over yonder? What could ogres be doing this far from their mound? I don't like this one bit, stranger. First Murkbloods and now ogres. We just don't have the manpower to handle all of these threats to our land.$B$BCould you investigate the ogre presence to the east for us? Their forward camp is about 200 paces east of here. You'll know you're at the right place if you see the Boulderfist hunters. Kill them to find the plans!",logDesc="Huntress Bintook at Telaar in Nagrand wants you to recover Boulderfist Plans."} end
if not DB[9918] then DB[9918]={id=9918,zoneId=3518,name="Not On My Watch!",level=65,minLevel=64,giver="Huntress Bintook",giverType="NPC",giverId=18353,ender="Huntress Bintook",enderType="NPC",enderId=18353,rewardNextId=9920,poiX=-2556,poiY=7254,wowhead="https://www.wowhead.com/wotlk/quest=9918",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The battle plans were written up by an ogre lieutenant. His name is either Dump or Lump.$B$B<Bintook turns the parchment sideways and cocks her head.>$B$BIt could also be Billy.$B$BAnyhow, I think you should go back out there and have a word with Billy or Lump or Dumpy or whatever! Try to approach him diplomatically. If that doesn't work, try using some muscle.",logDesc="Huntress Bintook at Telaar in Nagrand wants you to speak to Lump. Return to Huntress Bintook when you have gathered the information that she requested."} end
if not DB[9919] then DB[9919]={id=9919,zoneId=3521,name="Sporeggar",level=64,minLevel=60,giver="Fahssn",giverType="NPC",giverId=17923,ender="Msshi'fn",enderType="NPC",enderId=17924,poiX=-205,poiY=8517,wowhead="https://www.wowhead.com/wotlk/quest=9919",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You're a kind $r, $N.  Not like some of the others I've met.$B$BYou should meet the rest of my people; they'll be very grateful for your help.  Take these spore sacs to my leader, Msshi'fn.  You will find him in Sporeggar, north of here.",logDesc="Go to Sporeggar in Zangarmarsh, north of the Spawning Glen, and deliver the Salvaged Spore Sacs to Msshi'fn."} end
if not DB[9920] then DB[9920]={id=9920,zoneId=3518,name="Mo'mor the Breaker",level=65,minLevel=64,giver="Huntress Bintook",giverType="NPC",giverId=18353,ender="Mo'mor the Breaker",enderType="NPC",enderId=18223,rewardNextId=9921,poiX=-2556,poiY=7254,wowhead="https://www.wowhead.com/wotlk/quest=9920",image="assets/images/quests/placeholder.png",desc="You must seek out Mo'mor immediately! You will find him in the center of Telaar, by the fountain. Tell him exactly what the ogre told you.",logDesc="Huntress Bintook at Telaar in Nagrand wants you to speak to Mo'mor the Breaker."} end
if not DB[9921] then DB[9921]={id=9921,zoneId=3518,name="The Ruins of Burning Blade",level=65,minLevel=64,giver="Mo'mor the Breaker",giverType="NPC",giverId=18223,ender="Mo'mor the Breaker",enderType="NPC",enderId=18223,rewardNextId=9922,poiX=-2618,poiY=7278,wowhead="https://www.wowhead.com/wotlk/quest=9921",image="assets/images/quests/placeholder.png",xpDiff=5,desc="These ogre hunting parties are a precursor to invasion. We must strike at them before they have a chance to amass an army big enough to take over our town.$B$BYou're going to need to get your hands dirty, $r.$B$BThe largest collection of Boulderfist in this region can be found at the Burning Blade Ruins, almost directly east of Telaar, near the border of Terokkar. Go there and show the Boulderfist that Telaar will not bend to their will!",logDesc="Mo'mor the Breaker at Telaar in Nagrand wants you to kill 8 Boulderfist Crushers and 8 Boulderfist Mystics."} end
if not DB[9922] then DB[9922]={id=9922,zoneId=3518,name="The Twin Clefts of Nagrand",level=66,minLevel=64,giver="Mo'mor the Breaker",giverType="NPC",giverId=18223,ender="Mo'mor the Breaker",enderType="NPC",enderId=18223,rewardNextId=10108,poiX=-2618,poiY=7278,wowhead="https://www.wowhead.com/wotlk/quest=9922",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You made a strong showing, $N. Are you ready for more?$B$BI have received reports of a large contingent of Boulderfist ogres hidden in the twin clefts of Nagrand, northwest of here in the Halaani Basin.$B$BVenture forth to the clefts and deal with the remaining Boulderfist ogres.",logDesc="Mo'mor the Breaker at Telaar in Nagrand has asked that you slay 10 Boulderfist Warriors and 10 Boulderfist Mages.",choiceRewards={{id=25623,qty=1},{id=25624,qty=1},{id=25622,qty=1}}} end
if not DB[9923] then DB[9923]={id=9923,zoneId=3518,name="HELP!",level=65,minLevel=64,giver="Corki",giverType="NPC",giverId=18369,ender="Arechron",enderType="NPC",enderId=18183,rewardNextId=9924,poiX=-2564,poiY=6288,wowhead="https://www.wowhead.com/wotlk/quest=9923",image="assets/images/quests/placeholder.png",xpDiff=5,money=99000,desc="HELP! They're gonna eat me! I just know it!$B$BFind the key, I know it has to be on one of these ogres.$B$BIf you get me out of here, my father will reward you handsomely! He's the leader of Telaar, Arechron.$B",logDesc="Find the Boulderfist Key and Free Corki. Speak with Arechron in Telaar should you succeed.$B"} end
if not DB[9924] then DB[9924]={id=9924,zoneId=3518,name="Corki's Gone Missing Again!",level=66,minLevel=64,giver="Arechron",giverType="NPC",giverId=18183,ender="Arechron",enderType="NPC",enderId=18183,poiX=-2489,poiY=7231,wowhead="https://www.wowhead.com/wotlk/quest=9924",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Arechron sighs.>$B$BThis is so embarrassing. Do you remember my boy, Corki? You rescued him from the Burning Blade Ruins recently. Well, his curiosity has gotten the best of him once more. He told me that he was going to investigate the Boulderfist menace for 'uncle' Mo'mor and ran off to the ogre mounds in the Halaani Basin, north of here.$B$BDo you think you could track him down? I would be eternally grateful.$B",logDesc="Arechron at Telaar has asked that you find and free Corki.",choiceRewards={{id=25631,qty=1},{id=25632,qty=1},{id=25633,qty=1}}} end
if not DB[9925] then DB[9925]={id=9925,zoneId=3518,name="Matters of Security",level=66,minLevel=64,giver="Zerid",giverType="NPC",giverId=18276,ender="Zerid",enderType="NPC",enderId=18276,poiX=-2100,poiY=8595,wowhead="https://www.wowhead.com/wotlk/quest=9925",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="Gezhe chose to base our operations as close to Oshu'gun as possible, without any regard for the safety of our crew.  Why?  Because he projected a ten percent increase in productivity by setting up shop here instead of in the mountains to the south.$B$BNever mind the crazed voidspawn wandering all of ten feet away from us.  That would be the security officer's problem, not Gezhe's.$B$BKill some voidspawn for me and I'll pay you a tenth of our security budget.  Don't get excited, it's not much of a budget.",logDesc="Zerid at Aeris Landing in Nagrand wants you to kill 8 Voidspawn near Oshu'gun."} end
if not DB[9926] then DB[9926]={id=9926,zoneId=3518,name="FLAG Shadow Council/Warmaul Questline",level=66,minLevel=64,wowhead="https://www.wowhead.com/wotlk/quest=9926",image="assets/images/quests/placeholder.png"} end
if not DB[9927] then DB[9927]={id=9927,zoneId=3518,name="Ruthless Cunning",level=66,minLevel=64,giver="Lantresor of the Blade",giverType="NPC",giverId=18261,ender="Lantresor of the Blade",enderType="NPC",enderId=18261,poiX=-2264,poiY=6218,wowhead="https://www.wowhead.com/wotlk/quest=9927",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="<Lantresor hands you a pack full of banners.>$B$BThese are Warmaul ogre banners that I recently acquired.$B$BI want you to travel to Kil'sorrow Fortress, directly south of here, and kill as many of the Kil'sorrow filth as you can find. Drive a Warmaul ogre banner through the heart of each fallen Kil'sorrow soldier. Return to me when you have completed this task and the other that this plan requires.",logDesc="Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to drive 10 Warmaul Ogre Banners through the bodies of Kil'sorrow members at Kil'sorrow Fortress.$B$BReturn any unused Warmaul Ogre Banners."} end
if not DB[9928] then DB[9928]={id=9928,zoneId=3518,name="Armaments for Deception",level=66,minLevel=64,giver="Lantresor of the Blade",giverType="NPC",giverId=18261,ender="Lantresor of the Blade",enderType="NPC",enderId=18261,poiX=-2264,poiY=6218,wowhead="https://www.wowhead.com/wotlk/quest=9928",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="You will need to steal Kil'sorrow armaments from Kil'sorrow Fortress if my plan is to work.$B$BSearch the fortress for crates of Kil'sorrow armaments. Bring whatever you can find to me.$B$BKil'sorrow Fortress is located directly south and a little to the west of the Burning Blade Ruins.",logDesc="Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to collect 10 Kil'sorrow Armaments."} end
if not DB[9929] then DB[9929]={id=9929,zoneId=3519,name="The Missing Merchant",level=63,minLevel=255,rewardNextId=9942,wowhead="https://www.wowhead.com/wotlk/quest=9929",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="I don't suppose you've been here long enough to know Dugar, have you? He's a merchant with contacts among the various factions in Shattrath.$B$BDon't ask me how he does it, but he manages to trade with them for some of the goods our quartermasters can't provide.$B$BHe set out for Shattrath three days ago and hasn't returned. He's normally able to make the entire trip in less than that. If you're going to be traveling in the forest, would you keep an eye out for him?",logDesc="Travel northwest along the road toward Shattrath and search for evidence of what happened to Dugar."} end
if not DB[9930] then DB[9930]={id=9930,zoneId=3519,name="The Missing Merchant",level=63,minLevel=255,rewardNextId=9941,wowhead="https://www.wowhead.com/wotlk/quest=9930",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="I don't suppose you've been here long enough to know Deirom, have you? He's a merchant with contacts among the various factions in Shattrath.$B$BDon't ask me how he does it, but he manages to trade with them for some of the goods our quartermasters can't provide.$B$BHe set out for Shattrath three days ago and hasn't returned. He's normally able to make the entire trip in less than that. Keep an eye out for him and report anything you find to the mercenary captain, Thander.",logDesc="Travel northwest along the road toward Shattrath and search for evidence of what happened to Deirom."} end
if not DB[9931] then DB[9931]={id=9931,zoneId=3518,name="Returning the Favor",level=66,minLevel=64,giver="Lantresor of the Blade",giverType="NPC",giverId=18261,ender="Lantresor of the Blade",enderType="NPC",enderId=18261,poiX=-2264,poiY=6218,wowhead="https://www.wowhead.com/wotlk/quest=9931",image="assets/images/quests/placeholder.png",xpDiff=5,money=70000,desc="Now you must plant the seed of war in the fat, useless heads of the Warmaul. To the northwest, near the mountains, you will find the Laughing Skull Ruins.$B$B<Lantresor points into the crate of armaments you brought him.>$B$BDo you recognize those banners? They are Kil'sorrow banners. I want you to take a stack of Kil'sorrow banners and plant them on the corpses of Warmaul ogres. Remember, northwest is where you will find the ogres.",logDesc="Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to drive 10 Kil'sorrow Banners through the bodies of Warmaul ogres at the Laughing Skull Ruins.$B$BReturn any unused Kil'sorrow Banners."} end
if not DB[9932] then DB[9932]={id=9932,zoneId=3518,name="Body of Evidence",level=66,minLevel=64,giver="Lantresor of the Blade",giverType="NPC",giverId=18261,ender="Lantresor of the Blade",enderType="NPC",enderId=18261,poiX=-2264,poiY=6218,wowhead="https://www.wowhead.com/wotlk/quest=9932",image="assets/images/quests/placeholder.png",xpDiff=5,money=70000,desc="Your rampage through Kil'sorrow Fortress has provided us with a special opportunity. We have enough bodies to make it appear as if a great battle has taken place.$B$BTravel to the Laughing Skull Ruins and find the Laughing Skull Courtyard. There should be a blazing pyre in the courtyard. Make sure the area is secure and then use this blanket to send up smoke signals. When my ogres see the smoke, they will sneak in and plant the bodies of slain Kil'sorrow soldiers.$B$BThat should be the final straw!",logDesc="Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to use the Damp Woolen Blanket at the Blazing Warmaul Pyre in the Laughing Skull Courtyard to signal his ogres."} end
if not DB[9933] then DB[9933]={id=9933,zoneId=3518,name="Message to Telaar",level=66,minLevel=64,giver="Lantresor of the Blade",giverType="NPC",giverId=18261,ender="Arechron",enderType="NPC",enderId=18183,poiX=-2264,poiY=6218,wowhead="https://www.wowhead.com/wotlk/quest=9933",image="assets/images/quests/placeholder.png",xpDiff=6,money=105000,desc="<Lantresor points to an unmarked crate.>$B$BTake it. It is my offering to your people. You have single-handedly saved my clan from extermination.$B$BYou may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace.$B$B<Lantresor bows.>$B",logDesc="Take the Burning Blade Peace Offering to Arechron at Telaar in Nagrand.",choiceRewards={{id=25606,qty=1},{id=25603,qty=1},{id=25605,qty=1}}} end
if not DB[9934] then DB[9934]={id=9934,zoneId=3518,name="Message to Garadar",level=66,minLevel=64,giver="Lantresor of the Blade",giverType="NPC",giverId=18261,ender="Garrosh",enderType="NPC",enderId=18063,poiX=-2264,poiY=6218,wowhead="https://www.wowhead.com/wotlk/quest=9934",image="assets/images/quests/placeholder.png",xpDiff=6,money=105000,desc="<Lantresor points to an unmarked crate.>$B$BTake it. It is my offering to your people. You have single-handedly saved my clan from extermination.$B$BYou may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace.$B$B<Lantresor bows.>",logDesc="Take the Burning Blade Peace Offering to Garrosh at Garadar.",choiceRewards={{id=25607,qty=1},{id=25608,qty=1},{id=25609,qty=1}}} end
if not DB[9935] then DB[9935]={id=9935,zoneId=3518,name="Wanted: Giselda the Crone",level=66,minLevel=64,ender="Warden Bullrok",enderType="NPC",enderId=18407,wowhead="https://www.wowhead.com/wotlk/quest=9935",image="assets/images/quests/placeholder.png",xpDiff=5,money=105000,desc="Wanted: Dead or Alive$B$BGiselda the Crone of Kil'sorrow and her lackeys for murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary.$B$BKnown to congregate at Kil'sorrow Fortress in southeastern Nagrand, near the border of Terokkar.$B$BLarge gold reward to be dispensed by Warden Bullrok at Garadar to anyone able to bring Giselda to justice.",logDesc="Slay Giselda the Crone and any combination of 10 Kil'sorrow Agents. Return to Warden Bullrok at Garadar should you complete this task."} end
if not DB[9936] then DB[9936]={id=9936,zoneId=3518,name="Wanted: Giselda the Crone",level=66,minLevel=64,ender="Warden Moi'bff Jill",enderType="NPC",enderId=18408,wowhead="https://www.wowhead.com/wotlk/quest=9936",image="assets/images/quests/placeholder.png",xpDiff=5,money=105000,desc="Wanted: Dead or Alive$B$BGiselda the Crone of Kil'sorrow and her lackeys for murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary.$B$BKnown to congregate at Kil'sorrow Fortress in southeastern Nagrand, near the border of Terokkar.$B$BLarge gold reward to be dispensed by Warden Moi'bff Jill at Telaar to anyone able to bring Giselda to justice.",logDesc="Slay Giselda the Crone and any combination of 10 Kil'sorrow Agents. Return to Warden Moi'bff Jill at Telaar should you complete this task."} end
if not DB[9937] then DB[9937]={id=9937,zoneId=3518,name="Wanted: Durn the Hungerer",level=67,minLevel=66,giver="Warden Bullrok",giverType="NPC",giverId=18407,ender="Warden Bullrok",enderType="NPC",enderId=18407,poiX=-1356,poiY=7213,wowhead="https://www.wowhead.com/wotlk/quest=9937",image="assets/images/quests/placeholder.png",xpDiff=7,money=111000,desc="You have destroyed two of the biggest threats in Nagrand, $N. Are you ready to take on the scourge of the Spirit Fields?$B$BDurn the Hungerer lords over the area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Gather your allies and venture to the Spirit Fields, far southwest of here, near Oshu'gun, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.$B",logDesc="Slay Durn the Hungerer. Return to Warden Bullrok if you manage to complete this task.",choiceRewards={{id=25774,qty=1},{id=25773,qty=1},{id=25772,qty=1}}} end
if not DB[9938] then DB[9938]={id=9938,zoneId=3518,name="Wanted: Durn the Hungerer",level=67,minLevel=66,giver="Warden Moi'bff Jill",giverType="NPC",giverId=18408,ender="Warden Moi'bff Jill",enderType="NPC",enderId=18408,poiX=-2569,poiY=7272,wowhead="https://www.wowhead.com/wotlk/quest=9938",image="assets/images/quests/placeholder.png",xpDiff=7,money=111000,desc="You have destroyed two of the biggest threats in Nagrand, $N. Are you ready to take on the scourge of the Spirit Fields?$B$BDurn the Hungerer lords over the area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Gather your allies and venture to the Spirit Fields, west of here, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.",logDesc="Slay Durn the Hungerer. Return to Warden Moi'bff Jill if you manage to complete this task.",choiceRewards={{id=25774,qty=1},{id=25773,qty=1},{id=25772,qty=1}}} end
if not DB[9939] then DB[9939]={id=9939,zoneId=3518,name="Wanted: Zorbo the Advisor",level=66,minLevel=64,ender="Warden Bullrok",enderType="NPC",enderId=18407,wowhead="https://www.wowhead.com/wotlk/quest=9939",image="assets/images/quests/placeholder.png",xpDiff=5,money=70000,desc="Wanted: Dead or Alive$B$BZorbo the Advisor, wanted for numerous planned attacks on Garadar. Along with his reavers and shaman, Zorbo has slain countless orcs. Consider Zorbo as armed, dangerous, and merciless.$B$BZorbo makes his home in the Laughing Skull Ruins in the northern mountains of Nagrand.$B$BReward for Zorbo the Advisor's death or capture to be dispensed by Warden Bullrok at Garadar. ",logDesc="Slay Zorbo the Advisor, 5 Warmaul Shaman and 5 Warmaul Reavers. Return to Warden Bullrok if you manage to complete this task."} end
if not DB[9940] then DB[9940]={id=9940,zoneId=3518,name="Wanted: Zorbo the Advisor",level=66,minLevel=64,ender="Warden Moi'bff Jill",enderType="NPC",enderId=18408,wowhead="https://www.wowhead.com/wotlk/quest=9940",image="assets/images/quests/placeholder.png",xpDiff=5,money=70000,desc="Wanted: Dead or Alive$B$BZorbo the Advisor, wanted for numerous planned attacks on Telaar. Along with his reavers and shaman, Zorbo has slain countless Broken. Consider Zorbo as armed, dangerous, and merciless.$B$BZorbo makes his home in the Laughing Skull Ruins in the northern mountains of Nagrand.$B$BReward for Zorbo the Advisor's death or capture to be dispensed by Warden Moi'bff Jill at Telaar.",logDesc="Slay Zorbo the Advisor, 5 Warmaul Shaman and 5 Warmaul Reavers. Return to Warden Moi'bff Jill if you manage to complete this task."} end
if not DB[9941] then DB[9941]={id=9941,zoneId=3519,name="Tracking Down the Culprits",level=63,minLevel=255,rewardNextId=9943,wowhead="https://www.wowhead.com/wotlk/quest=9941",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="The arakkoa tracks, accompanied by a pair of shallow ruts, lead north across the road. It seems the arakkoa dragged something away from the site of the battle, perhaps toward a nearby settlement.$B$BWhile the broken cart shows signs of a struggle, there's little information about Deirom's fate. Follow the arakkoa tracks north and continue your search for the merchant. If he was captured alive, there may still be a chance to rescue him. ",logDesc="Continue your search for signs of Deirom in the Arakkoa settlement north of the broken cart."} end
if not DB[9942] then DB[9942]={id=9942,zoneId=3519,name="Tracking Down the Culprits",level=63,minLevel=255,rewardNextId=9947,wowhead="https://www.wowhead.com/wotlk/quest=9942",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="The arakkoa tracks, accompanied by a pair of shallow ruts, lead north across the road. It seems the arakkoa dragged something away from the site of the battle, perhaps toward a nearby settlement.$B$BWhile the broken cart shows signs of a struggle, there's little information about Dugar's fate. Follow the arakkoa tracks north and continue your search for the merchant. If he was captured alive, there may still be a chance to rescue him. ",logDesc="Continue your search for signs of Dugar in the Arakkoa settlement north of the broken cart."} end
if not DB[9943] then DB[9943]={id=9943,zoneId=3519,name="Return to Thander",level=64,minLevel=255,rewardNextId=9949,wowhead="https://www.wowhead.com/wotlk/quest=9943",image="assets/images/quests/placeholder.png",xpDiff=2,money=8000,desc="Deirom's cargo doesn't seem to have been harmed or even opened. The cargo clearly seemed of interest to them, but it seems their prisoner was more important. What the arakkoa hoped to gain from attacking and kidnapping Deirom remains unclear, but the merchant is certainly not being held here. $B$BWithout any further clues as to how to continue your search, you decide it might be a good time to report your findings to Thander.",logDesc="Return to Thander at the Allerian Stronghold with news of your findings.",choiceRewards={{id=25958,qty=1},{id=25959,qty=1},{id=25961,qty=1},{id=25960,qty=1}}} end
if not DB[9944] then DB[9944]={id=9944,zoneId=3518,name="Missing Mag'hari Procession",level=67,minLevel=65,giver="Matron Drakia",giverType="NPC",giverId=18302,ender="Elder Yorley",enderType="NPC",enderId=18414,rewardNextId=9945,poiX=-1214,poiY=7159,wowhead="https://www.wowhead.com/wotlk/quest=9944",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Greatmother says that we must press on and serve our people. She says that we must serve as an example for Garrosh - to show that life goes on.$B$BI have so many matters to attend to here, especially with Greatmother having taken ill. Would you honor the Mag'har by helping one of their matrons?$B$BSeveral days ago we sent a funeral procession to the Ancestral Grounds and they have yet to return. Will you go search for them? They took the western road out of Garadar. Follow it around and avoid Halaa.",logDesc="Search for the missing Mag'hari procession."} end
if not DB[9945] then DB[9945]={id=9945,zoneId=3518,name="War on the Warmaul",level=67,minLevel=65,giver="Elder Yorley",giverType="NPC",giverId=18414,ender="Elder Yorley",enderType="NPC",enderId=18414,rewardNextId=9946,poiX=-1290,poiY=8511,wowhead="https://www.wowhead.com/wotlk/quest=9945",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="We were en route to the Ancestral Grounds when we were ambushed by Warmaul. They came from all sides, killing several of the procession guards and many of the others. They even desecrated the remains of the elder in the wagon.$B$BAnd for what? So they could humiliate us and display their power. Not even Boulderfist would have sunk so low.$B$BI am a spiritual orc, $N, but even I have limitations. Find the attackers at Warmaul Hill to the northwest and destroy them!",logDesc="Elder Yorley at the Mag'hari Procession in Nagrand has asked that you slay 8 Warmaul Brutes and 8 Warmaul Warlocks."} end
if not DB[9946] then DB[9946]={id=9946,zoneId=3518,name="Cho'war the Pillager",level=67,minLevel=65,giver="Elder Yorley",giverType="NPC",giverId=18414,ender="Elder Yorley",enderType="NPC",enderId=18414,poiX=-1290,poiY=8511,wowhead="https://www.wowhead.com/wotlk/quest=9946",image="assets/images/quests/placeholder.png",xpDiff=6,money=74000,desc="Have you ever seen an ogre king, $r? Few have and lived to tell the tale. Unfortunately, that is exactly what we are dealing with here.$B$BThe leader of these barbarians is an ogre named Cho'war. Rumor has it that Cho'war was the ogre responsible for forcing the gronn out of the cave. Cho'war then declared himself king and dissolved the ogre clans that served under the gronn. Thus, Warmaul was born.$B$BFind Cho'war deep in the caves of Warmaul Hill. Slay him and bring me his head.",logDesc="Elder Yorley at the Mag'hari Procession in Nagrand has asked that you slay Cho'war the Pillager and retrieve the Head of Cho'war.",choiceRewards={{id=25777,qty=1},{id=25776,qty=1},{id=25775,qty=1}}} end
if not DB[9947] then DB[9947]={id=9947,zoneId=3519,name="Return to Rokag",level=64,minLevel=255,rewardNextId=9950,wowhead="https://www.wowhead.com/wotlk/quest=9947",image="assets/images/quests/placeholder.png",xpDiff=2,money=8000,desc="Dugar's cargo doesn't seem to have been harmed or even opened. The cargo clearly seemed of interest to them, but it seems their prisoner was more important. What the arakkoa hoped to gain from attacking and kidnapping Dugar remains unclear, but the merchant is certainly not being held here. $B$BWithout any further clues as to how to continue your search, you decide it might be a good time to report your findings to Rokag.",logDesc="Return to Rokag at Stonebreaker Hold with news of your findings.",choiceRewards={{id=25958,qty=1},{id=25959,qty=1},{id=25961,qty=1},{id=25960,qty=1}}} end
if not DB[9948] then DB[9948]={id=9948,zoneId=3518,name="Finding the Survivors",level=67,minLevel=65,giver="Elder Ungriz",giverType="NPC",giverId=18415,ender="Elder Ungriz",enderType="NPC",enderId=18415,poiX=-1292,poiY=8508,wowhead="https://www.wowhead.com/wotlk/quest=9948",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="If I know anything about ogres, it's that they like their food fresh. This means that the Mag'har that they captured are more than likely being kept alive until they are ready to serve. It's a sickening thought, I know, but one that we must use to our advantage.$B$BVenture to Warmaul Hill and search for Mag'har prisoners. If you find prisoners, then you will find keys to their cages on the nearby Warmaul ogres.$B$BKill ogres for their keys and release the prisoners.",logDesc="Elder Ungriz at the Mag'hari Procession in Nagrand has asked that you free 5 Mag'har Prisoners.",choiceRewards={{id=25778,qty=1},{id=25779,qty=1},{id=25780,qty=1}}} end
if not DB[9949] then DB[9949]={id=9949,zoneId=3519,name="A Bird's-Eye View",level=64,minLevel=255,rewardNextId=10048,wowhead="https://www.wowhead.com/wotlk/quest=9949",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="With no further information to go on, we're in a difficult situation. I'm not going to give up on finding and rescuing Deirom. His abduction isn't an accident, $N.$B$BThe arakkoa are up to something, but what is it they're planning?$B$BAndarl, over in the mage tower, knows something of their peculiar magic. With the right tools, he can scare up some new information for us. He'll need the \"eye\" crystals from each of the arakkoa towns north of the Bone Wastes - Veil Skith, Veil Reskk, and Veil Shienor.",logDesc="Bring the Eye of Veil Skith, the Eye of Veil Shienor, and the Eye of Veil Reskk to Andarl at the Allerian Stronghold."} end
if not DB[9950] then DB[9950]={id=9950,zoneId=3519,name="A Bird's-Eye View",level=64,minLevel=255,rewardNextId=10049,wowhead="https://www.wowhead.com/wotlk/quest=9950",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="With no further information to go on, we're in a difficult situation. I'm not going to give up on finding and rescuing Dugar. His abduction isn't an accident, $N.$B$BThe arakkoa are up to something, but what is it they're planning?$B$BKurgatok the warlock knows something of their peculiar magic. With the right tools, he can scare up some new information for us. He'll need the \"eye\" crystals from each of the arakkoa towns north of the Bone Wastes - Veil Skith, Veil Reskk, and Veil Shienor.",logDesc="Bring the Eye of Veil Skith, the Eye of Veil Shienor, and the Eye of Veil Reskk to Kurgatok at Stonebreaker Hold."} end
if not DB[9951] then DB[9951]={id=9951,zoneId=3519,name="It's Watching You!",level=64,minLevel=62,giver="Warden Treelos",giverType="NPC",giverId=18424,ender="Warden Treelos",enderType="NPC",enderId=18424,poiX=-1804,poiY=4647,wowhead="https://www.wowhead.com/wotlk/quest=9951",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Quick, hide!  The eyes of Naphthal'ar are upon you... upon us all!$B$BI dare not go to the top of the tower to speak with it, but you... you look as if you might know the right words to say.  Just be careful, it doesn't like jokes and will not suffer fools easily.$B$BIf you can, convince it to come down for tea.  But, by all means, get it to stop staring at me!",logDesc="Kill Naphthal'ar and then return to Warden Treelos at the Cenarion Thicket in Terokkar Forest.",choiceRewards={{id=25542,qty=1},{id=28028,qty=1},{id=28026,qty=1},{id=28027,qty=1},{id=31723,qty=1}}} end
if not DB[9952] then DB[9952]={id=9952,zoneId=3519,name="Prospector Balmoral",level=65,minLevel=255,rewardNextId=9958,wowhead="https://www.wowhead.com/wotlk/quest=9952",image="assets/images/quests/placeholder.png",xpDiff=2,desc="So Andarl is certain Deirom is being held in Veil Shalas? That's the largest of the arakkoa settlements that we know of.$B$BVeil Shalas is in the far south of the forest, close to the eastern rim of the Bone Wastes. Unfortunately, I don't have much information on it, but there is an Explorers' League member camped down there who may be able to help you. Prospector Balmoral's camp is perched on the very edge of the land to the southwest of Veil Shalas. Consult him before making any move against the arakkoa.",logDesc="Locate and speak with Prospector Balmoral."} end
if not DB[9953] then DB[9953]={id=9953,zoneId=3519,name="Lookout Nodak",level=65,minLevel=255,rewardNextId=9959,wowhead="https://www.wowhead.com/wotlk/quest=9953",image="assets/images/quests/placeholder.png",xpDiff=2,desc="So Kurgatok is certain Dugar is being held in Veil Shalas? That's the largest of the arakkoa settlements that we know of.$B$BVeil Shalas is in the far south of the forest, close to the eastern rim of the Bone Wastes. Unfortunately, I don't have much information on it, but we have a scout camped down there who may be able to help you. Lookout Nodak's camp is perched on the very edge of the land to the southwest of Veil Shalas. Consult him before making any move against the arakkoa.",logDesc="Locate and speak with Lookout Nodak."} end
if not DB[9954] then DB[9954]={id=9954,zoneId=3518,name="Corki's Ransom",level=67,minLevel=65,giver="Arechron",giverType="NPC",giverId=18183,ender="Corki",enderType="NPC",enderId=18445,rewardNextId=9955,poiX=-2489,poiY=7231,wowhead="https://www.wowhead.com/wotlk/quest=9954",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Arechron shows you a grime covered letter.>$B$BI just received this letter. It's from a clan of ogres known as Warmaul that rule the northwestern lands of Nagrand. It says that they have Corki and if we don't cooperate, they're going to eat him. Admittedly, Corki is a moron, but he's still my blood. Will you rescue him, $N?$B$BI presume that he's locked up in a cage somewhere on Warmaul Hill. That should be your first stop.",logDesc="Arechron wants you to find Corki at Warmaul Hill."} end
if not DB[9955] then DB[9955]={id=9955,zoneId=3518,name="Cho'war the Pillager",level=67,minLevel=65,giver="Corki",giverType="NPC",giverId=18445,ender="Arechron",enderType="NPC",enderId=18183,poiX=-918,poiY=8664,wowhead="https://www.wowhead.com/wotlk/quest=9955",image="assets/images/quests/placeholder.png",xpDiff=6,money=74000,desc="They call him Cho'war the pillager, $N. He's the ogre that forced out the gronn that used to rule over these ogres. You better believe he's powerful!$B$BThe chef said that Cho'war lives in the big cave - wherever that may be... Get that key and get me out of here! If we live through this, my father will no doubt give you the big reward! As soon as I'm free, seek him out.",logDesc="Corki wants you to get Cho'war's Key so that you can free him from his cage. Return to Arechron at Telaar should you manage this task.",choiceRewards={{id=25777,qty=1},{id=25776,qty=1},{id=25775,qty=1}}} end
if not DB[9956] then DB[9956]={id=9956,zoneId=3518,name="The Ravaged Caravan",level=67,minLevel=65,giver="Huntress Kima",giverType="NPC",giverId=18416,ender="Huntress Kima",enderType="NPC",enderId=18416,poiX=-2542,poiY=7323,wowhead="https://www.wowhead.com/wotlk/quest=9956",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="I was part of a caravan taking supplies to the Orebor Harborage in Zangarmarsh. As we were nearing the border of the marsh, we were jumped by a vicious squad of Warmaul ogres. They killed the others and took me prisoner, along with all of our supplies.$B$BThankfully, they neglected to place a backing on my cage. When they fell asleep, I made my escape.$B$BIt's too late for my comrades but we could really use the supplies they stole. Warmaul Hill is in the northwestern mountains of Nagrand.",logDesc="Huntress Kima at Telaar in Nagrand wants you to recover 10 Telaar Supply Crates.",choiceRewards={{id=25778,qty=1},{id=25779,qty=1},{id=25780,qty=1}}} end
if not DB[9957] then DB[9957]={id=9957,zoneId=3519,name="What's Wrong at Cenarion Thicket?",level=63,minLevel=62,giver="Lethyn Moonfire",giverType="NPC",giverId=17834,ender="Earthbinder Tavgren",enderType="NPC",enderId=18446,poiX=-181,poiY=5527,wowhead="https://www.wowhead.com/wotlk/quest=9957",image="assets/images/quests/placeholder.png",xpDiff=2,desc="We haven't heard from the druids at the Cenarion Thicket of Terokkar Forest in quite some time.$B$B$N, I'd like for you to go down there and check in with them to see what's happening.  There are several ways to get there, but the fastest is to head south along the path, and then take the road that branches east from Shattrath City once you're in the forest.",logDesc="Speak with one of the druids at the Cenarion Thicket in Terokkar Forest."} end
if not DB[9958] then DB[9958]={id=9958,zoneId=3519,name="Scouting the Defenses",level=65,minLevel=255,rewardNextId=9963,wowhead="https://www.wowhead.com/wotlk/quest=9958",image="assets/images/quests/placeholder.png",xpDiff=4,desc="In my time out here, I've had a few interactions with the arakkoa, none of them friendly. They seem very territorial, but I suppose we're the same way, aren't we?$B$BThe arakkoa wield a kind of primal magic unknown to us on Azeroth and have used it to weave defenses for Veil Shalas. Before moving against them, it would be prudent to scout out their defenses so we know what we're up against.",logDesc="Approach Veil Shalas and observe the town's defenses."} end
if not DB[9959] then DB[9959]={id=9959,zoneId=3519,name="Scouting the Defenses",level=65,minLevel=255,rewardNextId=9964,wowhead="https://www.wowhead.com/wotlk/quest=9959",image="assets/images/quests/placeholder.png",xpDiff=4,desc="In my time out here, I've had a few interactions with the arakkoa, none of them friendly. They seem very territorial, but I suppose we're the same way, aren't we? Not even the ancestors recorded any encounters with the bird-men.$B$BThe arakkoa wield a kind of primal magic unknown to our seers and have used it to weave defenses for Veil Shalas. Before moving against them, it would be wise to scout out their defenses so we know what we're up against.",logDesc="Approach Veil Shalas and learn about the magic defending the settlement."} end
if not DB[9960] then DB[9960]={id=9960,zoneId=3519,name="What's Wrong at Cenarion Thicket?",level=63,minLevel=62,giver="Tooki",giverType="NPC",giverId=18447,ender="Earthbinder Tavgren",enderType="NPC",enderId=18446,poiX=-2654,poiY=4381,wowhead="https://www.wowhead.com/wotlk/quest=9960",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hey there, $c.  We haven't heard from the druids of the Cenarion Thicket in quite some time.$B$BI want you to go over there and check to see what's happening.  You can find it by heading northwest through the forest.",logDesc="Speak with one of the druids at the Cenarion Thicket in Terokkar Forest."} end
if not DB[9961] then DB[9961]={id=9961,zoneId=3519,name="What's Wrong at Cenarion Thicket?",level=63,minLevel=62,giver="Jenai Starwhisper",giverType="NPC",giverId=18459,ender="Earthbinder Tavgren",enderType="NPC",enderId=18446,poiX=-2926,poiY=4005,wowhead="https://www.wowhead.com/wotlk/quest=9961",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$C, I have urgent business for you.  We haven't heard from the druids of the Cenarion Thicket in quite some time.  This is unusual as we usually hear from them at least once every few days.$B$BI want you to go up there and make sure that they're alright.  You can find the thicket by heading northwest through the forest.",logDesc="Speak with one of the druids at the Cenarion Thicket in Terokkar Forest."} end
if not DB[9962] then DB[9962]={id=9962,zoneId=3518,name="The Ring of Blood: Brokentoe",level=67,minLevel=65,giver="Gurgthock",giverType="NPC",giverId=18471,ender="Wodin the Troll-Servant",enderType="NPC",enderId=22893,poiX=-722,poiY=7932,wowhead="https://www.wowhead.com/wotlk/quest=9962",image="assets/images/quests/placeholder.png",xpDiff=7,money=111000,desc="So are you ready for your first battle? If you are, let me know and I'll get things started. All you have to do is go wait in the Ring of Blood for your opponent to arrive.$B$BThis fight is against Brokentoe, a ferocious clefthoof.$B$BGood luck! I hope you brought friends.$B$BAnd remember, the fight's over when either you or your opponent are lying face down on the arena floor.$B",logDesc="Defeat Brokentoe. Should you win, speak with Wodin the Troll-Servant to collect your reward."} end
if not DB[9963] then DB[9963]={id=9963,zoneId=3519,name="Seeking Help from the Source",level=65,minLevel=255,rewardNextId=9965,wowhead="https://www.wowhead.com/wotlk/quest=9963",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The wards you encountered are powerful magic, indeed. The techniques employed by the arakkoa are so far beyond our understanding that we can only hope to find a counter with their help.$B$BI know what's going through your mind. Why would an enemy help us to overcome their defenses? The answer is that they wouldn't, of course. Have you heard the tales of a crazy old arakkoa sage named Kokorek? They say he's hiding in Veil Lithic on the western edge of the Bone Wastes, waiting for the return of a lost age.",logDesc="Find Kokorek in Veil Lithic and speak with him."} end
if not DB[9964] then DB[9964]={id=9964,zoneId=3519,name="Seeking Help from the Source",level=65,minLevel=255,rewardNextId=9966,wowhead="https://www.wowhead.com/wotlk/quest=9964",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The wards you encountered are powerful magic, indeed. The techniques employed by the arakkoa are so far beyond our understanding that we can only hope to find a counter with their help.$B$BI know what's going through your mind. Why would an enemy help us to overcome their defenses? The answer is that they wouldn't, of course. Have you heard the tales of a crazy old arakkoa sage named Kokorek? They say he's hiding in Veil Lithic on the western edge of the Bone Wastes, waiting for the return of a lost age.",logDesc="Find Kokorek in Veil Lithic and speak with him."} end
if not DB[9965] then DB[9965]={id=9965,zoneId=3519,name="A Show of Good Faith",level=65,minLevel=255,rewardNextId=9969,wowhead="https://www.wowhead.com/wotlk/quest=9965",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'd like to propose something of a trade: demonstrate your good intentions by helping me resolve a little problem, and I'll help you rescue your comrade.$B$BThe ogres are an ancient enemy of my people, and lately they have begun to filter back into our forest from the grasslands of Nagrand.$B$BOne particular ogre, Mug'gok, is quite an adventurous fellow, but none too bright. He goes back and forth between causing trouble for his friends at the Bleeding Hollow Ruins and trying to provoke us.",logDesc="Bring Mug'gok's Head to Kokorek in Veil Lithic."} end
if not DB[9966] then DB[9966]={id=9966,zoneId=3519,name="A Show of Good Faith",level=65,minLevel=255,rewardNextId=9974,wowhead="https://www.wowhead.com/wotlk/quest=9966",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'd like to propose something of a trade: demonstrate your good intentions by helping me resolve a little problem, and I'll help you rescue your comrade.$B$BThe ogres are an ancient enemy of my people, and lately they have begun to filter back into our forest from the grasslands of Nagrand.$B$BOne particular ogre, Mug'gok, is quite an adventurous fellow, but none too bright. He goes back and forth between causing trouble for his friends at the Bleeding Hollow Ruins and trying to provoke us.",logDesc="Bring Mug'gok's Head to Kokorek in Veil Lithic."} end
if not DB[9967] then DB[9967]={id=9967,zoneId=3518,name="The Ring of Blood: The Blue Brothers",level=67,minLevel=65,giver="Gurgthock",giverType="NPC",giverId=18471,ender="Wodin the Troll-Servant",enderType="NPC",enderId=22893,poiX=-722,poiY=7932,wowhead="https://www.wowhead.com/wotlk/quest=9967",image="assets/images/quests/placeholder.png",xpDiff=7,money=111000,desc="This next battle involves a duo - twin brothers to be precise. They call themselves the \"Blue Brothers.\"$B$BIt's not too late to chicken out, $N. I'd certainly understand.$B$BBut if you're ready for some action, step in the Ring of Blood and wait for the Murkblood twins to arrive.$B$BLast one standing is the winner!",logDesc="Defeat the Murkblood Twins that call themselves the Blue Brothers. Should you win, speak with Wodin the Troll-Servant to collect your reward."} end
if not DB[9968] then DB[9968]={id=9968,zoneId=3519,name="Strange Energy",level=63,minLevel=62,giver="Earthbinder Tavgren",giverType="NPC",giverId=18446,ender="Earthbinder Tavgren",enderType="NPC",enderId=18446,poiX=-1947,poiY=4690,wowhead="https://www.wowhead.com/wotlk/quest=9968",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Something strange has changed the teromoths of the thicket.$B$BWhere once there was a diversity of life in there, now only the teromoths remain.  And while before they were at peace, now they are agitated and will not hesitate to attack you should you get close.$B$BI need to compare the vicious ones to the normal.  Collect for me a number of samples from both.  You'll find the unaffected teromoths both to the south and the north.$B$BI'm certain this is related to whatever killed all of the druids.",logDesc="Collect 4 Teromoth Samples and 4 Vicious Teromoth Samples.  Then return to Earthbinder Tavgren just outside of the Cenarion Thicket in Terokkar Forest."} end
if not DB[9969] then DB[9969]={id=9969,zoneId=3519,name="The Final Reagents",level=65,minLevel=255,rewardNextId=9975,wowhead="https://www.wowhead.com/wotlk/quest=9969",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I can create an item that will neutralize the ward spells protecting Veil Shalas, but be warned, $N. The magic will only work as long as your friend is held captive. I will not give you a means to attack my people at will.$B$BI have most of the materials I require to create the charm, but there are a couple that I'm going to need you to gather before I can finish the work. I'll need some warp hunter essence and a handful of Terokkar chokeberries. Both can be found in the area around the veil.",logDesc="Bring 5 Warp Hunter Essences and 30 Terokkar Chokeberries to Kokorek in Veil Lithic.",choiceRewards={{id=25966,qty=1},{id=25965,qty=1},{id=25963,qty=1}}} end
if not DB[9970] then DB[9970]={id=9970,zoneId=3518,name="The Ring of Blood: Rokdar the Sundered Lord",level=67,minLevel=65,giver="Gurgthock",giverType="NPC",giverId=18471,ender="Wodin the Troll-Servant",enderType="NPC",enderId=22893,poiX=-722,poiY=7932,wowhead="https://www.wowhead.com/wotlk/quest=9970",image="assets/images/quests/placeholder.png",xpDiff=7,money=111000,desc="This fight is gonna be painful, $N. Do you have any friends that are brave enough to help you out? The ogres managed to get a giant from Blade's Edge named Rokdar! Trust me, you're gonna need friends, he seems unbeatable! He's hard as a rock - literally!$B$BIf you still want to fight him, step into the Ring of Blood and he will come.",logDesc="Defeat Rokdar the Sundered Lord. Should you win, speak with Wodin the Troll-Servant to collect your reward.",rewards={{id=22829,qty=5},{id=22832,qty=5}}} end
if not DB[9971] then DB[9971]={id=9971,zoneId=3519,name="Clues in the Thicket",level=63,minLevel=62,giver="Earthbinder Tavgren",giverType="NPC",giverId=18446,ender="Earthbinder Tavgren",enderType="NPC",enderId=18446,poiX=-1947,poiY=4690,wowhead="https://www.wowhead.com/wotlk/quest=9971",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="I have no idea what killed all of the druids here.  I've been away for a couple of days on a survey of the Bone Wastes to the south.$B$BPlease, you must help me to uncover what's behind this horrible tragedy.  Go into the thicket and look for a clue that might reveal something to us.  When I was in there briefly, I could have sworn I saw a dead Broken and a strange object next to him.$B$B And don't worry about Treelos - he might have been driven insane by what happened, but I think he's mostly harmless.",logDesc="Investigate the Strange Object next to the Broken Corpse to determine what might have befallen the Cenarion Thicket.  Then return to Earthbinder Tavgren just outside the thicket in Terokkar Forest."} end
if not DB[9972] then DB[9972]={id=9972,zoneId=3518,name="The Ring of Blood: Skra'gath",level=67,minLevel=65,giver="Gurgthock",giverType="NPC",giverId=18471,ender="Wodin the Troll-Servant",enderType="NPC",enderId=22893,poiX=-722,poiY=7932,wowhead="https://www.wowhead.com/wotlk/quest=9972",image="assets/images/quests/placeholder.png",xpDiff=7,money=111000,desc="You're murderin' 'em out there, kid! They got a ringer for the next match. They say he's a void lord or something... No way do they want you up against their champion. Did you here that palooka, Mogor, yapping at you? The bets are through the roof!$B$BGet in that ring and take this one out fast!",logDesc="Defeat Skra'gath. Should you win, speak with Wodin the Troll-Servant to collect your reward.",rewards={{id=22829,qty=5},{id=22832,qty=5},{id=21991,qty=20}}} end
if not DB[9973] then DB[9973]={id=9973,zoneId=3518,name="The Ring of Blood: The Warmaul Champion",level=67,minLevel=65,giver="Gurgthock",giverType="NPC",giverId=18471,ender="Wodin the Troll-Servant",enderType="NPC",enderId=22893,poiX=-722,poiY=7932,wowhead="https://www.wowhead.com/wotlk/quest=9973",image="assets/images/quests/placeholder.png",xpDiff=7,money=111000,desc="They had to ship the champion in from the Blade's Edge gladiator pits. He was training on mountain giants - three at a time.$B$BIf you win this one, you become the new champion. What do you think your odds are, kid? Do you have a shot? Just give me the word and I'll bet the house on you.$B$BNow get in there and win!",logDesc="Defeat the Warmaul Champion. Should you win, speak with Wodin the Troll-Servant to collect your reward."} end
if not DB[9974] then DB[9974]={id=9974,zoneId=3519,name="The Final Reagents",level=65,minLevel=255,rewardNextId=9976,wowhead="https://www.wowhead.com/wotlk/quest=9974",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I can create an item that will neutralize the ward spells protecting Veil Shalas, but be warned, $N. The magic will only work as long as your friend is held captive. I will not give you a means to attack my people at will.$B$BI have most of the materials I require to create the charm, but there are a couple that I'm going to need you to gather before I can finish the work. I'll need some warp hunter essence and a handful of Terokkar chokeberries. Both can be found in the area around the veil.",logDesc="Bring 5 Warp Hunter Essences and 30 Terokkar Chokeberries to Kokorek at Veil Lithic.",choiceRewards={{id=25966,qty=1},{id=25965,qty=1},{id=25963,qty=1}}} end
if not DB[9975] then DB[9975]={id=9975,zoneId=3519,name="Primal Magic",level=65,minLevel=255,rewardNextId=9980,wowhead="https://www.wowhead.com/wotlk/quest=9975",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've stored the spell inside this talisman. Unleash it while standing near the totems that guard the approach to Veil Shalas. It should be sufficient to unravel the wards.$B$B<You mention that the figure in the talisman doesn't especially resemble an arakkoa.>$B$BMy people weren't always as they appear now. We were once magnificent creatures, but we... we made many ill-advised choices and failed in our sacred task. It cost us our beauty, our power, and very nearly our lives. Do not repeat our mistakes, $N.",logDesc="Use Kokorek's Talisman near the totems that guard the path to Veil Shalas, then speak with Prospector Balmoral."} end
if not DB[9976] then DB[9976]={id=9976,zoneId=3519,name="Primal Magic",level=65,minLevel=255,rewardNextId=9981,wowhead="https://www.wowhead.com/wotlk/quest=9976",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I've stored the spell inside this talisman. Unleash it while standing near the totems that guard the approach to Veil Shalas. It should be sufficient to unravel the wards.$B$B<You mention that the figure in the talisman doesn't especially resemble an arakkoa.>$B$BMy people weren't always as they appear now. We were once magnificent creatures, but we... we made many ill-advised choices and failed in our sacred task. It cost us our beauty, our power, and very nearly our lives. Do not repeat our mistakes, $N.",logDesc="Use Kokorek's Talisman near the totems that guard the path to Veil Shalas, then speak with Lookout Nodak."} end
if not DB[9977] then DB[9977]={id=9977,zoneId=3518,name="The Ring of Blood: The Final Challenge",level=68,minLevel=65,giver="Gurgthock",giverType="NPC",giverId=18471,ender="Wodin the Troll-Servant",enderType="NPC",enderId=22893,poiX=-722,poiY=7932,wowhead="https://www.wowhead.com/wotlk/quest=9977",image="assets/images/quests/placeholder.png",xpDiff=7,money=117000,desc="<Gurgthock is counting his massive pile of gold.>$B$BYou've made me a lot of money, kid. If you can defeat Mogor, I promise to make it worth your while. All that pain you suffered in the Ring of Blood is gonna end up paying off.$B$BNow get in there and show these ogres what you're made of!",logDesc="Defeat Mogor, Hero of the Warmaul. Should you win, speak with Wodin the Troll-Servant to collect your reward.",choiceRewards={{id=25762,qty=1},{id=25760,qty=1},{id=25763,qty=1},{id=25761,qty=1},{id=25764,qty=1},{id=25759,qty=1}}} end
if not DB[9978] then DB[9978]={id=9978,zoneId=3519,name="By Any Means Necessary",level=63,minLevel=62,giver="Earthbinder Tavgren",giverType="NPC",giverId=18446,ender="Empoor",enderType="NPC",enderId=18482,rewardNextId=9979,poiX=-1947,poiY=4690,wowhead="https://www.wowhead.com/wotlk/quest=9978",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I don't know what to make of all of this, but I do know how we can find more clues.$B$BEmpoor is a Broken merchant that traffics in all sorts of goods and information.  If you were to persuade him to talk, I'm sure he might have something interesting to say.$B$BHe travels the road here between Tuurem and Shattrath.  Watch out, though -- he travels with a bodyguard.",logDesc="Find Empoor on the road between Tuurem and Shattrath City in Terokkar Forest. Convince him to tell you what he knows."} end
if not DB[9979] then DB[9979]={id=9979,zoneId=3703,name="Wind Trader Lathrai",level=63,minLevel=62,giver="Empoor",giverType="NPC",giverId=18482,ender="Wind Trader Lathrai",enderType="NPC",enderId=18484,rewardNextId=10112,poiX=-1955,poiY=4752,wowhead="https://www.wowhead.com/wotlk/quest=9979",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I was asked to pick up and deliver some boxes of goods from an ethereal in Shattrath City.$B$BLast I saw him, he was standing outside of the World's End Tavern in Lower City.  His name is Wind Trader Lathrai, and that's all that I know!$B$BWant more answers, go talk with him!",logDesc="Speak with Wind Trader Lathrai near the World's End Tavern in the Lower City section of Shattrath City."} end
if not DB[9980] then DB[9980]={id=9980,zoneId=3519,name="Rescue Deirom!",level=65,minLevel=62,wowhead="https://www.wowhead.com/wotlk/quest=9980",image="assets/images/quests/placeholder.png",xpDiff=7,money=66000,desc="Make your way to Veil Shalas with all haste, $N! Time is of the essence here. If the arakkoa discover what you've done to their defenses, they may attempt to move Deirom, or even kill him.$B$BIf you can, bring a friend or two with you. It's likely to be rough there. The bird-men have gone to great lengths to secure their prisoner and they're not likely to give him up easily. After you've found Deirom and dealt with his captor, return to the Allerian Stronghold and notify Thander.",logDesc="Venture into Veil Shalas, kill Luanga, and free Deirom. Report to Lady Dena Kennedy at the Allerian Stronghold when you have completed your mission.",choiceRewards={{id=25967,qty=1},{id=25969,qty=1},{id=25970,qty=1},{id=25968,qty=1}}} end
if not DB[9981] then DB[9981]={id=9981,zoneId=3519,name="Rescue Dugar!",level=65,minLevel=62,wowhead="https://www.wowhead.com/wotlk/quest=9981",image="assets/images/quests/placeholder.png",xpDiff=7,money=66000,desc="Make your way to Veil Shalas with all haste, $N! Time is of the essence here. If the arakkoa discover what you've done to their defenses, they may attempt to move Dugar, or even kill him.$B$BIf you can, bring a friend or two with you. It's likely to be rough there. The bird-men have gone to great lengths to secure their prisoner and they're not likely to give him up easily. After you've found Dugar and dealt with his captor, return to Stonebreaker Hold and notify Rokag.",logDesc="Venture into Veil Shalas, kill Luanga, and free Dugar. Report to Rokag at Stonebreaker Hold when you have completed your mission.",choiceRewards={{id=25967,qty=1},{id=25969,qty=1},{id=25970,qty=1},{id=25968,qty=1}}} end
if not DB[9982] then DB[9982]={id=9982,zoneId=3518,name="He Called Himself Altruis...",level=68,minLevel=66,giver="Huntress Kima",giverType="NPC",giverId=18416,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,poiX=-2542,poiY=7323,wowhead="https://www.wowhead.com/wotlk/quest=9982",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A being riding atop a nether drake arrived in town late last week. He introduced himself as Altruis and then proceeded to ask us several questions about Nagrand.$B$BHe claimed that he was hunting Legion. That such insanity was actually his job. Can you imagine? A person that would willingly hunt demons?$B$BBefore he left, he asked that we let the would-be heroes in town know that he will be staying in western Nagrand for awhile and that should they seek a purpose, to find him.",logDesc="If you are looking to fight the Burning Legion, find Altruis the Sufferer in western Nagrand."} end
if not DB[9983] then DB[9983]={id=9983,zoneId=3518,name="He Called Himself Altruis...",level=68,minLevel=66,giver="Matron Celestine",giverType="NPC",giverId=18301,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,poiX=-1288,poiY=7246,wowhead="https://www.wowhead.com/wotlk/quest=9983",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A being riding atop a nether drake arrived in town late last week. He introduced himself as Altruis and then proceeded to ask us several questions about Nagrand.$B$BHe claimed that he was hunting Legion. That such insanity was actually his job. Can you imagine? A person that would willingly hunt demons?$B$BBefore he left, he asked that we let the would-be heroes in town know that he will be staying in western Nagrand for awhile and that should they seek a purpose, to find him.",logDesc="If you are looking to fight the Burning Legion, find Altruis the Sufferer in western Nagrand."} end
if not DB[9984] then DB[9984]={id=9984,zoneId=3519,name="Host of the Hidden City",level=65,minLevel=62,ender="Andarl",enderType="NPC",enderId=18252,wowhead="https://www.wowhead.com/wotlk/quest=9984",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="Although you cannot read the strange script on the scroll, the ornate seal at the bottom of the document implies that it was drafted by an arakkoa of high standing. Luanga may have masterminded the capture and interrogation of Deirom, but it seems he was taking orders from someone else.$B$BYou remember Thander mentioning that Andarl has studied the arakkoa. Perhaps he can decipher the scroll's contents.",logDesc="Take Luanga's Orders to Andarl at the Allerian Stronghold in Terokkar Forest."} end
if not DB[9985] then DB[9985]={id=9985,zoneId=3519,name="Host of the Hidden City",level=65,minLevel=62,ender="Kurgatok",enderType="NPC",enderId=18383,wowhead="https://www.wowhead.com/wotlk/quest=9985",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="Although you cannot read the strange script on the scroll, the ornate seal at the bottom of the document implies that it was drafted by an arakkoa of high standing. Luanga may have masterminded the capture and interrogation of Dugar, but it seems he was taking orders from someone else.$B$BYou remember Rokag mentioning that Kurgatok has studied the arakkoa. Perhaps he can decipher the scroll's contents.",logDesc="Bring Luanga's Orders to Kurgatok at Stonebreaker Hold in Terokkar Forest."} end
if not DB[9986] then DB[9986]={id=9986,zoneId=3519,name="Stymying the Arakkoa",level=64,minLevel=62,giver="Thander",giverType="NPC",giverId=18389,ender="Thander",enderType="NPC",enderId=18389,poiX=-2953,poiY=3961,wowhead="https://www.wowhead.com/wotlk/quest=9986",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="We need to show the arakkoa that they cannot attack our people with impunity. If we don't stop them here, the roads will no longer be safe for our merchants, couriers, or soldiers.$B$BMy scouts have identified the leaders of each of the major arakkoa settlements in the area. Seek out Ashkaz, Ayit, and Urdak, in Veil Reskk, Veil Shienor, and Veil Skith and kill them. ",logDesc="Kill Ashkaz in Veil Reskk, Ayit in Veil Shienor, and Urdak in Veil Skith and return to Thander at the Allerian Stronghold.",choiceRewards={{id=22829,qty=5},{id=22832,qty=5}}} end
if not DB[9987] then DB[9987]={id=9987,zoneId=3519,name="Stymying the Arakkoa",level=64,minLevel=62,giver="Rokag",giverType="NPC",giverId=18386,ender="Rokag",enderType="NPC",enderId=18386,poiX=-2607,poiY=4439,wowhead="https://www.wowhead.com/wotlk/quest=9987",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="We need to show the arakkoa that they cannot attack our people with impunity. If we don't stop them here, the roads will no longer be safe for our merchants, couriers, or soldiers.$B$BMy scouts have identified the leaders of each of the major arakkoa settlements in the area. Seek out Ashkaz, Ayit, and Urdak, in Veil Reskk, Veil Shienor, and Veil Skith and kill them. ",logDesc="Kill Ashkaz in Veil Reskk, Ayit in Veil Shienor, and Urdak in Veil Skith and return to Rokag at Stonebreaker Hold.",choiceRewards={{id=22829,qty=5},{id=22832,qty=5}}} end
if not DB[9988] then DB[9988]={id=9988,zoneId=3519,name="A Dandy's Best Friend",level=65,minLevel=62,wowhead="https://www.wowhead.com/wotlk/quest=9988",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="Don't let Thander and company fool you. They may look like a band of fearsome warriors, but underneath all that steel, they're nothing more than a troop of dandies!$B$BAnd they won't be seen in public without their hats. They're extravagant affairs made from felt and fur, complete with the gaudiest feathers you've ever seen.$B$BThe most desirable feathers come from any of the arakkoa, of course, and my supply is running low. I'll gladly pay you if you'll collect them for me.",logDesc="Bring 30 Arakkoa Feathers to Ros'eleth in the Allerian Stronghold.",rewards={{id=28499,qty=1}}} end
if not DB[9989] then DB[9989]={id=9989,zoneId=3519,name="Alien Spirits",level=65,minLevel=62,wowhead="https://www.wowhead.com/wotlk/quest=9989",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="When I first came to Outland, and opened my ears to the voices of its spirits, I was amazed at what I heard. In time, I also came to notice which spirits I couldn't hear.$B$BFor all my attempts, I have never been able to make contact with the spirit of an arakkoa ancestor. Their magic is fundamentally different from ours, but I'm not convinced that their spirits are beyond my reach.$B$BBring me feathers from many arakkoa; perhaps having some token from them will provide the link I need.",logDesc="Bring 30 Arakkoa Feathers to Malukaz at Stonebreaker Hold.",rewards={{id=28499,qty=1}}} end
if not DB[9990] then DB[9990]={id=9990,zoneId=3519,name="Investigate Tuurem",level=64,minLevel=62,giver="Wind Trader Lathrai",giverType="NPC",giverId=18484,ender="Earthbinder Tavgren",enderType="NPC",enderId=18446,poiX=-1742,poiY=5192,wowhead="https://www.wowhead.com/wotlk/quest=9990",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="You know, come to think of it, I do recall selling several boxes of strange and exotic engineering parts to Empoor about a month ago.  I'm not sure what they'd be used for, but I know that they were delivered to Tuurem.$B$BPerhaps one or more of those boxes is still there?",logDesc="Find the Sealed Box and then deliver it to Earthbinder Tavgren just outside of the Cenarion Thicket in Terokkar Forest."} end
if not DB[9991] then DB[9991]={id=9991,zoneId=3518,name="Survey the Land",level=68,minLevel=66,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,rewardNextId=9999,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=9991",image="assets/images/quests/placeholder.png",xpDiff=2,desc="To be my eyes will require some diligence on your part. Nethrandamus will take you through the Legion camps, but you must catalog everything that you see. Even the smallest detail that you may think to be inconsequential could be useful for our purposes.$B$BPrimarily, I want you to note what structures are in the camps and what comprises the camps' defenses.$B$BNethrandamus is ready when you are, $N. Do not be afraid, he will keep you safe from harm.$B",logDesc="Sit back and enjoy the ride. Speak to Altruis when the survey is complete."} end
if not DB[9992] then DB[9992]={id=9992,zoneId=3519,name="Olemba Seeds",level=63,minLevel=62,giver="Ros'eleth",giverType="NPC",giverId=18390,ender="Ros'eleth",enderType="NPC",enderId=18390,rewardNextId=10028,poiX=-2996,poiY=3983,wowhead="https://www.wowhead.com/wotlk/quest=9992",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Aren't the trees in the forest beautiful? I've often wondered if they would survive on Azeroth.$B$BI'm hesitant to send back seedlings, though. It's a rough trip and they're much harder to transport than something like a sack of seeds. The seeds are stored in tough cones that fall from the tree's branches once they've reached maturity.$B$BIf you come upon some of those cones in your travels, would you mind bringing some of the seeds back to me?",logDesc="Gather 30 Olemba Seeds and return them to Ros'eleth in the Allerian Stronghold."} end
if not DB[9993] then DB[9993]={id=9993,zoneId=3519,name="Olemba Seed Oil",level=63,minLevel=62,giver="Rakoria",giverType="NPC",giverId=18385,ender="Rakoria",enderType="NPC",enderId=18385,rewardNextId=10201,poiX=-2616,poiY=4376,wowhead="https://www.wowhead.com/wotlk/quest=9993",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="The oily seeds from the forest's olemba trees could prove very valuable. I'd like to gather a larger quantity of them, press them for their oil, and then see what I can do with it.$B$BJust think, there's a whole forest full of trees out there, producing a lot of seeds that go to waste. I don't care if it turns out to be cooking oil, lamp oil, or weapon oil, I won't let it go to waste!$B$BBring me any of the seeds that you happen to gather from the olemba cones. They're all over the place.",logDesc="Bring 30 Olemba Seeds to Rakoria in Stonebreaker Hold."} end
if not DB[9994] then DB[9994]={id=9994,zoneId=3519,name="What Are These Things?",level=64,minLevel=62,giver="Earthbinder Tavgren",giverType="NPC",giverId=18446,ender="Jenai Starwhisper",enderType="NPC",enderId=18459,rewardNextId=10444,poiX=-1947,poiY=4690,wowhead="https://www.wowhead.com/wotlk/quest=9994",image="assets/images/quests/placeholder.png",xpDiff=3,money=16000,desc="I don't know about you, but I have no idea what all of those things are.  I do know one thing though - they look dangerous!$B$B$N, I think you should take this box of parts to Jenai Starwhisper at the Allerian Stronghold to the southeast.  She may have some idea of what these are.",logDesc="Deliver the Box of Parts to Jenai Starwhisper at the Allerian Stronghold in Terokkar Forest."} end
if not DB[9995] then DB[9995]={id=9995,zoneId=3519,name="What Are These Things?",level=64,minLevel=62,giver="Earthbinder Tavgren",giverType="NPC",giverId=18446,ender="Tooki",enderType="NPC",enderId=18447,rewardNextId=10448,poiX=-1947,poiY=4690,wowhead="https://www.wowhead.com/wotlk/quest=9995",image="assets/images/quests/placeholder.png",xpDiff=3,money=16000,desc="I don't know about you, but I have no idea what all of those things are.  I do know one thing though - they look dangerous!$B$B$N, I think you should take this box of parts to Tooki at Stonebreaker Hold to the southeast.  He may have some idea of what these are.",logDesc="Deliver the Box of Parts to Tooki at Stonebreaker Hold in Terokkar Forest."} end
if not DB[9996] then DB[9996]={id=9996,zoneId=3519,name="Attack on Firewing Point",level=64,minLevel=62,giver="Lieutenant Meridian",giverType="NPC",giverId=21006,ender="Lieutenant Meridian",enderType="NPC",enderId=21006,rewardNextId=10446,poiX=-2588,poiY=3320,wowhead="https://www.wowhead.com/wotlk/quest=9996",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="We know that the blood elves of Firewing Point are working for Kael'thas and Illidan.  And from what you've told me, clearly they are using the Broken of Tuurem as smuggling go-betweens for the creation of some horrible weapon.$B$BWhatever they're up to out there, the most efficient thing that we can do right now is to thin out their numbers.$B$BThe Firewing blood elves need to be taken out!  Head up to Firewing Point to the north and see to it.",logDesc="Kill 10 Firewing Defenders, 10 Firewing Bloodwarders, and 10 Firewing Warlocks.  Then report back to Lieutenant Meridian at the Allerian Post in Terokkar Forest."} end
if not DB[9997] then DB[9997]={id=9997,zoneId=3519,name="Attack on Firewing Point",level=64,minLevel=62,giver="Sergeant Chawni",giverType="NPC",giverId=21007,ender="Sergeant Chawni",enderType="NPC",enderId=21007,rewardNextId=10447,poiX=-2526,poiY=3666,wowhead="https://www.wowhead.com/wotlk/quest=9997",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="We know that the blood elves of Firewing Point are working for Kael'thas and Illidan.  And from what you've told me, clearly they are using the Broken of Tuurem as smuggling go-betweens for the creation of some horrible weapon.$B$BWhatever they're up to out there, the most efficient thing that we can do right now is to thin out their numbers.$B$BThe Firewing blood elves need to be taken out!  Head over to Firewing Point to the northeast and see to it.",logDesc="Kill 10 Firewing Defenders, 10 Firewing Bloodwarders, and 10 Firewing Warlocks.  Then report back to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest."} end
if not DB[9998] then DB[9998]={id=9998,zoneId=3519,name="Unruly Neighbors",level=63,minLevel=62,giver="Bertelm",giverType="NPC",giverId=18387,ender="Theloria Shadecloak",enderType="NPC",enderId=18565,poiX=-2971,poiY=3935,wowhead="https://www.wowhead.com/wotlk/quest=9998",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="The recent arrival of the fel orcs at the ruins to the east both puzzles and troubles Thander. They wasted no time in starting to construct fortifications and repair the buildings.$B$BThe construction goes on day and night, $N. I've dispatched one of my most reliable agents to keep watch, but we can ill afford to delay action. Move against their workers, then seek out Theloria Shadecloak at the Allerian Post to the north of the Bonechewer Ruins. She'll give you further instructions.",logDesc="Kill 12 Warped Peons and then report to Theloria Shadecloak at the Allerian Post."} end
if not DB[9999] then DB[9999]={id=9999,zoneId=3518,name="Buying Time",level=68,minLevel=66,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,rewardNextId=10001,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=9999",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As long as the transporters stand, nothing we do to the forge camps will have any permanence. We must find a way to destroy the Legion structures.$B$BI need time to devise a plan of attack. If you can keep their engineers and tinkerers busy, it would greatly slow down their progress, buying me the time I need.$B$BStay as far away as possible from the overseers, $N. They are extremely dangerous beings.",logDesc="Altruis the Sufferer in western Nagrand has asked that you kill 2 Felguard Legionnaires, 3 Mo'arg Engineers and 8 Gan'arg Tinkerers."} end
if not DB[10000] then DB[10000]={id=10000,zoneId=3519,name="An Unwelcome Presence",level=63,minLevel=62,giver="Kurgatok",giverType="NPC",giverId=18383,ender="Shadowstalker Kaide",enderType="NPC",enderId=18566,poiX=-2645,poiY=4450,wowhead="https://www.wowhead.com/wotlk/quest=10000",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Our forces at Thrallmar thought they had the fel orcs contained in the Hellfire Citadel area, but the recent arrivals at the ruins to the east say otherwise.$B$BWe can't permit them to gain a foothold here. Rokag has dispatched Shadowstalker Kaide to the ruins to keep an eye on them, but we have to do something to keep them from digging in.$B$BGo to the ruins, decimate their peons, and then look for Kaide in the trees to the north. He'll tell you where to go from there.",logDesc="Kill 12 Warped Peons and then report to Shadowstalker Kaide."} end
if not DB[10001] then DB[10001]={id=10001,zoneId=3518,name="The Master Planner",level=68,minLevel=66,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,rewardNextId=10004,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=10001",image="assets/images/quests/placeholder.png",xpDiff=5,desc="All forge camps have a master planner. The master planner dictates what types of structures are present at a forge camp and how each structure is situated. Moreover, this information is kept on a set of blueprints that the planner carries around on their person.$B$BWe need the master planner's blueprints. Armed with such exacting information, we could persuade an acquaintance of mine to lend some assistance.$B$BFind the mo'arg master planner and take his blueprints. He will be stationed behind the forges.",logDesc="Altruis the Sufferer in western Nagrand has asked that you recover the Master Planner's Blueprints."} end
if not DB[10002] then DB[10002]={id=10002,zoneId=3519,name="The Firewing Liaison",level=64,minLevel=62,giver="Theloria Shadecloak",giverType="NPC",giverId=18565,ender="Theloria Shadecloak",enderType="NPC",enderId=18565,poiX=-2592,poiY=3317,wowhead="https://www.wowhead.com/wotlk/quest=10002",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying?$B$BMy curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost.$B$BKill her before she leaves the fel orc camp again.$B",logDesc="Locate and slay Lisaile Fireweaver, then return to Theloria Shadecloak."} end
if not DB[10003] then DB[10003]={id=10003,zoneId=3519,name="The Firewing Liaison",level=64,minLevel=62,giver="Shadowstalker Kaide",giverType="NPC",giverId=18566,ender="Shadowstalker Kaide",enderType="NPC",enderId=18566,poiX=-2538,poiY=3661,wowhead="https://www.wowhead.com/wotlk/quest=10003",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying?$B$BMy curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost.$B$BKill her before she leaves the fel orc camp again.",logDesc="Locate and slay Lisaile Fireweaver, then return to Shadowstalker Kaide."} end
if not DB[10004] then DB[10004]={id=10004,zoneId=3518,name="Patience and Understanding",level=68,minLevel=66,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Sal'salabim",enderType="NPC",enderId=18584,rewardNextId=10009,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=10004",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Take the blueprints and travel to Shattrath City in the Terokkar forest. Once at Shattrath, go to the Lower City and look for a mo'arg by the name Sal'salabim. He'll probably be at the bar, drinking away his sorrows.$B$BBy the way, you may need to convince him to lend his assistance. Try to approach him with patience and understanding. If that does not work, use your fists.",logDesc="Altruis the Sufferer in western Nagrand wants you to take the Master Planner's Blueprints to Sal'salabim in Shattrath City and convince him to help you.$B"} end
if not DB[10005] then DB[10005]={id=10005,zoneId=3519,name="Letting Earthbinder Tavgren Know",level=63,minLevel=62,giver="Jenai Starwhisper",giverType="NPC",giverId=18459,ender="Earthbinder Tavgren",enderType="NPC",enderId=18446,poiX=-2926,poiY=4005,wowhead="https://www.wowhead.com/wotlk/quest=10005",image="assets/images/quests/placeholder.png",xpDiff=7,money=87000,desc="$N, after you're done celebrating here, I think that you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.$B$BI'm certain that he'll want to know what really happened out there.",logDesc="Speak with Earthbinder Tavgren just outside the Cenarion Thicket in Terokkar Forest.",choiceRewards={{id=25931,qty=1},{id=25930,qty=1},{id=25932,qty=1},{id=25929,qty=1}}} end
if not DB[10006] then DB[10006]={id=10006,zoneId=3519,name="Letting Earthbinder Tavgren Know",level=63,minLevel=62,giver="Tooki",giverType="NPC",giverId=18447,ender="Earthbinder Tavgren",enderType="NPC",enderId=18446,poiX=-2654,poiY=4381,wowhead="https://www.wowhead.com/wotlk/quest=10006",image="assets/images/quests/placeholder.png",xpDiff=7,money=87000,desc="$N, I think that after you're done celebrating here, you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.$B$BI'm certain that he'll want to know what really happened out there.",logDesc="Speak with Earthbinder Tavgren just outside the Cenarion Thicket in Terokkar Forest.",choiceRewards={{id=25931,qty=1},{id=25930,qty=1},{id=25932,qty=1},{id=25929,qty=1}}} end
if not DB[10007] then DB[10007]={id=10007,zoneId=3519,name="Thinning the Ranks",level=64,minLevel=62,giver="Theloria Shadecloak",giverType="NPC",giverId=18565,ender="Theloria Shadecloak",enderType="NPC",enderId=18565,poiX=-2592,poiY=3317,wowhead="https://www.wowhead.com/wotlk/quest=10007",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Knowing Thander and Bertelm, they won't tolerate such a large buildup of hostile forces on our doorstep. Asking them to dispatch members of the garrison to participate in an attack on the camp isn't an option either. It would just leave us too vulnerable to attack.$B$BIt falls to us to do what we can to diminish the threat the fel orc buildup poses. Kill what you can of their forces and I will look for ways to stall any reinforcements.",logDesc="Kill 10 Bonechewer Devastators and 6 Bonechewer Backbreakers and return to Theloria Shadecloak.",choiceRewards={{id=25972,qty=1},{id=25971,qty=1},{id=25973,qty=1}}} end
if not DB[10008] then DB[10008]={id=10008,zoneId=3519,name="What Happens in Terokkar Stays in Terokkar",level=64,minLevel=62,giver="Shadowstalker Kaide",giverType="NPC",giverId=18566,ender="Shadowstalker Kaide",enderType="NPC",enderId=18566,poiX=-2538,poiY=3661,wowhead="https://www.wowhead.com/wotlk/quest=10008",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="If word reaches Thrallmar that they've failed to contain the fel orcs, we're going to be receiving a lot of company down here. Frankly, I'm not sure I want all that attention, so we're going to keep this little problem under wraps, got it?$B$BIf we can inflict enough casualties on the fel orcs, chances are their presence will never come to the attention of anyone outside Stonebreaker. So, let's end it now.$B$BWade in there, swing your weapon, wave your hands, or whatever it is you do - just kill fel orcs.",logDesc="Shadowstalker Kaide wants you to kill 10 Bonechewer Devastators and 6 Bonechewer Backbreakers.",choiceRewards={{id=25973,qty=1},{id=25972,qty=1},{id=25971,qty=1}}} end
if not DB[10009] then DB[10009]={id=10009,zoneId=3519,name="Crackin' Some Skulls",level=68,minLevel=66,giver="Sal'salabim",giverType="NPC",giverId=18584,ender="Sal'salabim",enderType="NPC",enderId=18584,rewardNextId=10010,poiX=-1777,poiY=5126,wowhead="https://www.wowhead.com/wotlk/quest=10009",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="<Sal'salabim laughs.>$B$BThis Sal'salabim design.$B$B<Sal'salabim points to the architecture and formations on the blueprints.>$B$BLook at towers. Demon hunter no can see, yes? Poor, poor Altruis. He cry if he had eyes, yes?$B$BYes, Sal'salabim help but first you help Sal'salabim.$B$B<Sal'salabim gives you a ledger.>$B$BThese creatures owe Sal'salabim golds. Many golds. Go collect for Sal'salabim and come back. They no give you Sal'salabim gold easy. Have to fight, but you strong. You defeat Sal'salabim!",logDesc="Sal'salabim at Shattrath City wants you to recover Raliq's Debt, Coosh'coosh's Debt and Floon's Debt."} end
if not DB[10010] then DB[10010]={id=10010,zoneId=3519,name="It's Just That Easy?",level=68,minLevel=66,giver="Sal'salabim",giverType="NPC",giverId=18584,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,rewardNextId=10011,poiX=-1777,poiY=5126,wowhead="https://www.wowhead.com/wotlk/quest=10010",image="assets/images/quests/placeholder.png",xpDiff=3,desc="<Sal'salabim points to the blueprint.>$B$BYou see where fel cannons are?$B$B<Sal'salabim draws an arrow denoting a change of direction.>$B$BYou turn fel cannon around and use on structures.$B$BWait! Don't be mad! One thing you not know. Overseers have key to turn cannons. You need key first! One from each overseer!$B$BNot so easy, eh?$B$BTake information back to Altruis.$B",logDesc="Sal'salabim at Shattrath City wants you to return to Altruis the Sufferer in western Nagrand."} end
if not DB[10011] then DB[10011]={id=10011,zoneId=3518,name="Forge Camp: Annihilated",level=68,minLevel=66,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=10011",image="assets/images/quests/placeholder.png",xpDiff=7,money=117000,desc="Gather your allies, $N. You will need them if you are to face an overseer.$B$BOnce you have a suitable group, find and kill the overseers at each camp. Take their keys and use them to turn and fire the fel cannons upon the camps. Return to me once the camps are destroyed.",logDesc="Altruis the Sufferer in western Nagrand has asked that you Destroy Forge Camp: Hate and Destroy Forge Camp: Fear.",choiceRewards={{id=25822,qty=1},{id=25821,qty=1},{id=25820,qty=1},{id=25819,qty=1}}} end
if not DB[10012] then DB[10012]={id=10012,zoneId=3519,name="Fel Orc Plans",level=64,minLevel=62,ender="Bertelm",enderType="NPC",enderId=18387,wowhead="https://www.wowhead.com/wotlk/quest=10012",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point.$B$BWhy would the two forces be working together? Bertelm might have some insight into this odd alliance. You decide to make your way back to the Allerian Stronghold and show him the map.",logDesc="Bring the Fel Orc Plans to Bertelm at the Allerian Stronghold in Terokkar Forest."} end
if not DB[10013] then DB[10013]={id=10013,zoneId=3519,name="An Unseen Hand",level=64,minLevel=62,ender="Rokag",enderType="NPC",enderId=18386,wowhead="https://www.wowhead.com/wotlk/quest=10013",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point.$B$BWhy would the two forces be working together? Rokag might have some insight into this odd alliance. You decide to make your way back to Stonebreaker Hold and show him the map.",logDesc="Bring the Fel Orc Plans to Rokag at Stonebreaker Hold in Terokkar Forest."} end
if not DB[10014] then DB[10014]={id=10014,zoneId=3519,name="The Firewing Point Project",level=64,minLevel=62,rewardNextId=10446,wowhead="https://www.wowhead.com/wotlk/quest=10014",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="As I was saying, we've just received some further intel and there's a much larger problem at hand.$B$BThe blood elves are hard at work on the construction of a second bomb at Firewing Point.  I cannot stress strongly enough the implications of them completing and using such a device on the Allerian Stronghold!$B$BMy scouts tell me that they are guarding the codes to the device in the four smaller buildings ringing the central courtyard.  Get in there and retrieve those codes before it's too late!",logDesc="Steal the four Mana Bomb Code Sheets and deliver them to Lieutenant Meridian at the Allerian Post in Terokkar Forest."} end
if not DB[10015] then DB[10015]={id=10015,zoneId=3519,name="The Firewing Point Project",level=64,minLevel=62,rewardNextId=10447,wowhead="https://www.wowhead.com/wotlk/quest=10015",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="As I was saying, we've just received some further intel and there's a much larger problem at hand.$B$BThe blood elves are hard at work on the construction of a second bomb at Firewing Point.  I cannot stress strongly enough the implications of them completing and using such a device on Stonebreaker Hold!$B$BMy scouts tell me that they are guarding the codes to the device in the four smaller buildings ringing the central courtyard.  Get in there and retrieve those codes before it's too late!",logDesc="Steal the four Mana Bomb Code Sheets and deliver them to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest."} end
if not DB[10016] then DB[10016]={id=10016,zoneId=3519,name="Timber Worg Tails",level=64,minLevel=62,giver="Bertelm",giverType="NPC",giverId=18387,ender="Bertelm",enderType="NPC",enderId=18387,rewardNextId=10022,poiX=-2971,poiY=3935,wowhead="https://www.wowhead.com/wotlk/quest=10016",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Have you come across the timber worgs in your travels? I've had the opportunity to observe them while mapping some of the northern reaches of the forest. I wouldn't recommend getting close to them unless you're prepared for combat.$B$BThey have no fear of us and won't hesitate to defend their territory.$B$BIt's fitting that such a creature would have a magnificent tail. I've been trying to collect enough of them to trim a new cloak, but the worgs have a habit of evading my snares. Will you help?",logDesc="Bertelm at the Allerian Stronghold wants you to bring him 12 Timber Worg Tails. The tails can come from either Timber Worgs or Timber Worg Alphas."} end
if not DB[10017] then DB[10017]={id=10017,zoneId=3703,name="Strained Supplies",level=64,minLevel=62,giver="Sha'nir",giverType="NPC",giverId=18597,ender="Sha'nir",enderType="NPC",enderId=18597,poiX=-1606,poiY=5292,wowhead="https://www.wowhead.com/wotlk/quest=10017",image="assets/images/quests/placeholder.png",xpDiff=5,desc="More and more refugees come through the gates of Shattrath City each day.  Some have sustained such injuries, it's a real wonder they made it here.$B$BI can deal with most of the conventional injuries; my training as an Aldor healer has prepared me for that.  Poison wounds are more problematic as my anti-venom supplies have begun to run low.$B$BBring me venom sacs from the local dreadfang spiders so I can produce more antidotes.  You'll find a pocket of the spiders in the southeastern region of Terokkar.",logDesc="Bring 8 Dreadfang Venom Sacs to Sha'nir in Shattrath City.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10018] then DB[10018]={id=10018,zoneId=3519,name="Vestments of the Wolf Spirit",level=64,minLevel=62,giver="Malukaz",giverType="NPC",giverId=18384,ender="Malukaz",enderType="NPC",enderId=18384,rewardNextId=10023,poiX=-2672,poiY=4374,wowhead="https://www.wowhead.com/wotlk/quest=10018",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Generations ago, when orc clans still called Terokkar Forest home, the wolf spirit played an important role in their lives. When the orcs departed, they had no longer had any need for the spirit and they left it behind.$B$BIn time, the spirit grew lonely and it too left the forest.$B$BI believe I can bring the wolf spirit back to his ancestral home, just as we orcs have returned. The ritual will require me to create vestments from the pelts of the wolves of the forest to guide the spirit back to its home.",logDesc="Bring 12 Timber Worg Pelts to Malukaz at Stonebreaker Hold. "} end
if not DB[10019] then DB[10019]={id=10019,zoneId=3703,name="More Venom Sacs",level=64,minLevel=62,giver="Sha'nir",giverType="NPC",giverId=18597,ender="Sha'nir",enderType="NPC",enderId=18597,poiX=-1606,poiY=5292,wowhead="https://www.wowhead.com/wotlk/quest=10019",image="assets/images/quests/placeholder.png"} end
if not DB[10020] then DB[10020]={id=10020,zoneId=3703,name="A Cure for Zahlia",level=64,minLevel=62,giver="Sha'nir",giverType="NPC",giverId=18597,ender="Sha'nir",enderType="NPC",enderId=18597,poiX=-1606,poiY=5292,wowhead="https://www.wowhead.com/wotlk/quest=10020",image="assets/images/quests/placeholder.png",xpDiff=6,money=62000,desc="The woman to my right suffered a severe injury to the head.  She survived, but lost her eyesight.$B$BA traditional cure used among my people requires the blood of a very old basilisk.$B$BUnfortunately, due to poaching from various groups, Terokkar basilisks don't tend to live very long.$B$BThere is one basilisk whose name I've known since I was a youngling.  It is known only as \"Stonegazer\" and it's rumored to live east of here, near the land's edge.$B$BBring me its blood so that Zahlia may see once again.",logDesc="Bring Stonegazer's Blood to Sha'nir in Shattrath City.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10021] then DB[10021]={id=10021,zoneId=3703,name="Restoring the Light",level=64,minLevel=62,giver="Ishanah",giverType="NPC",giverId=18538,ender="Ishanah",enderType="NPC",enderId=18538,poiX=-1733,poiY=5822,wowhead="https://www.wowhead.com/wotlk/quest=10021",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Much of this region was inhabited by draenei long ago.  We Aldor were charged with the safeguarding of our holy sites and altars.  Many of them have since been destroyed or taken over by our enemies.$B$BTo the east of here there is an arakkoa outpost.  It was purposefully built on the location of three of our sacred altars. The arakkoa use their foul magic to warp and defile the innate power of our shrines.$B$BTake this to the arakkoa outpost and use it to cleanse the three altars.",logDesc="Ishanah wants you to go to the Arakkoa outpost east of Shattrath City and use the Blessed Vial to cleanse the Eastern Altar, the Western Altar and the Northern Altar.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10022] then DB[10022]={id=10022,zoneId=3519,name="The Elusive Ironjaw",level=64,minLevel=62,giver="Bertelm",giverType="NPC",giverId=18387,ender="Bertelm",enderType="NPC",enderId=18387,poiX=-2971,poiY=3935,wowhead="https://www.wowhead.com/wotlk/quest=10022",image="assets/images/quests/placeholder.png",xpDiff=6,money=31000,desc="Now that I have the fur I'll need for the trim, I've been thinking that the pelt of a particular wolf would make a good hood for my cloak. Imagine seeing your enemy clad in the pelt of the most cunning predator in the forest!$B$BI've tried trapping old Ironjaw without success. I've tried cornering him, outsmarting him, and baiting him. None of it has worked.$B$BHe stalks the northeastern reaches of the forest, and I'd gladly reward you if you could succeed where I have failed.",logDesc="Bring Ironjaw's Pelt to Bertelm at the Allerian Stronghold.",choiceRewards={{id=25974,qty=1},{id=25976,qty=1},{id=25977,qty=1},{id=25975,qty=1}}} end
if not DB[10023] then DB[10023]={id=10023,zoneId=3519,name="Patriarch Ironjaw",level=64,minLevel=62,giver="Malukaz",giverType="NPC",giverId=18384,ender="Malukaz",enderType="NPC",enderId=18384,rewardNextId=10791,poiX=-2672,poiY=4374,wowhead="https://www.wowhead.com/wotlk/quest=10023",image="assets/images/quests/placeholder.png",xpDiff=6,money=31000,desc="You've done well in gathering the first pelts.$B$BThe final piece of the vestments requires a pelt unlike any other. There is one particular wolf, an old and cunning one, that has earned his place as the patriarch of the forest wolves. He is known among them as Ironjaw, the mighty hunter.$B$BIn my visions, I have seen him wandering the northeastern region of the forest. Including his pelt in the vestments will surely light the wolf spirit's path.$B$BDo not mourn Ironjaw. He will be well honored.",logDesc="Bring Ironjaw's Pelt to Malukaz at Stonebreaker Hold."} end
if not DB[10024] then DB[10024]={id=10024,zoneId=3703,name="Voren'thal's Visions",level=65,minLevel=62,giver="Arcanist Adyria",giverType="NPC",giverId=18596,ender="Arcanist Adyria",enderType="NPC",enderId=18596,poiX=-1670,poiY=5417,wowhead="https://www.wowhead.com/wotlk/quest=10024",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Our leader, Voren'thal the Seer, was once a close advisor to Kael'thas.  His prophetic visions warned him that Kael's path would lead to the destruction of our race.$B$BThe visions are usually vague and unfocused, but our alchemists have devised an elixir to help him focus his clairvoyance.  Unfortunately, this elixir calls for a rare ingredient: basilisk eyes.  My usual source, this pathetic ethereal, has failed me.$B$BSeek the dampscale basilisks in the rocky regions of Terokkar and bring me their eyes.",logDesc="Bring 8 Dampscale Basilisk Eyes to Arcanist Adyria in Shattrath City.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10025] then DB[10025]={id=10025,zoneId=3703,name="More Basilisk Eyes",level=65,minLevel=62,giver="Arcanist Adyria",giverType="NPC",giverId=18596,ender="Arcanist Adyria",enderType="NPC",enderId=18596,poiX=-1670,poiY=5417,wowhead="https://www.wowhead.com/wotlk/quest=10025",image="assets/images/quests/placeholder.png"} end
if not DB[10026] then DB[10026]={id=10026,zoneId=3519,name="Magical Disturbances",level=64,minLevel=62,giver="Andarl",giverType="NPC",giverId=18252,ender="Andarl",enderType="NPC",enderId=18252,poiX=-2928,poiY=3923,wowhead="https://www.wowhead.com/wotlk/quest=10026",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="It's embarrassing to admit this, but something has happened to me here in Terokkar Forest that hasn't occurred since my apprentice days.$B$BOccasionally, my spells will fizzle when I know I've done everything correctly. I almost drove myself crazy the first time it happened.$B$BI think I've found the cause. The forest is full of creatures called warp stalkers, demonic creatures with an affinity for magic and a habit of disturbing magical flows. The best way to deal with them is simply to kill them.",logDesc="Andarl at the Allerian Stronghold wants you to kill 10 Warp Stalkers."} end
if not DB[10027] then DB[10027]={id=10027,zoneId=3519,name="Magical Disturbances",level=64,minLevel=62,giver="Kurgatok",giverType="NPC",giverId=18383,ender="Kurgatok",enderType="NPC",enderId=18383,poiX=-2645,poiY=4450,wowhead="https://www.wowhead.com/wotlk/quest=10027",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="There's nothing more annoying than preparing to cast a spell, only to have it interrupted by some unseen force. After the fourth time, I knew it couldn't be coincidence and I sent Keb'ezil out to investigate.$B$BI guarantee you'll never encounter an imp that talks back more than Keb.$B$BAnyway, he managed to find the source of the problem, a pesky creature known as a warp stalker. They have a habit of disturbing the magical energy wherever they blink into existence. I've had enough of their interference.",logDesc="Kill 10 Warp Stalkers and return to Kurgatok at Stonebreaker Hold."} end
if not DB[10028] then DB[10028]={id=10028,zoneId=3519,name="Vessels of Power",level=63,minLevel=62,giver="Ros'eleth",giverType="NPC",giverId=18390,ender="Ros'eleth",enderType="NPC",enderId=18390,poiX=-2996,poiY=3983,wowhead="https://www.wowhead.com/wotlk/quest=10028",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Amid the ruins of Tuurem are a number of vessels containing raw, magical energy. We are fortunate that the Broken who have overrun the city are ignorant to the resource in their midst, but we cannot assume they will remain so forever.$B$BWith those vessels and their power in hand, the scattered survivors of my people can resist the lure of demonic magic. Every quel'dorei we can save from our prince's folly is one more that can help us regain our lost glory. Bring me these vessels, $c.",logDesc="Bring 8 Draenei Vessels to Ros'eleth at the Allerian Stronghold."} end
if not DB[10029] then DB[10029]={id=10029,zoneId=3519,name="The Spirits Are Calling",level=65,minLevel=63,wowhead="https://www.wowhead.com/wotlk/quest=10029",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The spirits of the dead in the Bone Wastes have been calling out to me and they are in pain!$B$B$C, you must journey to the Bone Wastes to the south and find my assistant, Soolaveen with the Refugee Caravan.  He must be feeling it too, and will need your assistance to help put the spirits there to rest.$B$BIf you hurry, you may catch them.  I know that they were going to stop for a while in the northern portion of the Bone Wastes before continuing south to Auchindoun.",logDesc="Anchorite Lyteera wants you to locate her assistant, Soolaveen at the Refugee Caravan in the Bone Wastes of Terokkar Forest.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease.$B"} end
if not DB[10030] then DB[10030]={id=10030,zoneId=3519,name="Recover the Bones",level=65,minLevel=63,giver="Soolaveen",giverType="NPC",giverId=18675,ender="Ramdor the Mad",enderType="NPC",enderId=19417,rewardNextId=10031,poiX=-2783,poiY=5082,wowhead="https://www.wowhead.com/wotlk/quest=10030",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="The bones of the dead draenei litter the Bone Wastes from the explosion of Auchindoun.  Their spirits are restless, and cannot move on to the next life.$B$B$C, you must help me to recover their bones and take them to their final resting place!  Only then will they be at peace; only then will they know comfort.$B$BGather up the restless bones with care and deliver them to Ramdor the Mad at Auchindoun in the center of the Bone Wastes.  Despite his name, he will know how to care for them.",logDesc="Collect 10 Restless Bones.  Deliver them to Ramdor the Mad, just off the western side of the Ring of Observance in Auchindoun, which is in the middle of the Bone Wastes of Terokkar Forest.$B"} end
if not DB[10031] then DB[10031]={id=10031,zoneId=3519,name="Helping the Lost Find Their Way",level=65,minLevel=63,giver="Ramdor the Mad",giverType="NPC",giverId=19417,ender="Soolaveen",enderType="NPC",enderId=18675,poiX=-3385,poiY=5185,wowhead="https://www.wowhead.com/wotlk/quest=10031",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="Many spirits of the draenei were corrupted by the explosion of Auchindoun.  Now they wander the wastes in torment.$B$B$N, I beseech you to put them to rest.  Destroy the lost spirits and broken skeletons that haunt the Bone Wastes beyond Auchindoun's walls.$B$BWhat?  You think leaving them to wander in blind agony would be better?$B$BAfterward, return to Soolaveen at the Refugee Caravan and tell him of that which you have done.",logDesc="Destroy 10 Lost Spirits and 10 Broken Skeletons, and then speak with Soolaveen at the Refugee Caravan in the Bone Wastes of Terokkar Forest.$B",choiceRewards={{id=25948,qty=1},{id=25949,qty=1},{id=25951,qty=1},{id=31725,qty=1}}} end
if not DB[10032] then DB[10032]={id=10032,zoneId=3519,name="Artifacts from Tuurem",level=63,minLevel=62,wowhead="https://www.wowhead.com/wotlk/quest=10032",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="Have you ever noticed the behavior of the Lost Ones in Tuurem? They wander the ruins,searching for surviving scraps of anything made by the draenei.$B$BTheir Broken masters know better. They've left their former lives and identities behind and become something completely different.$B$BI believe we can use the Lost Ones' compulsion to our benefit and gather old draenei relics from them. Why risk life and limb battling the Broken,when we can profit from picking our targets wisely?",logDesc="Gather 6 Tuurem Artifacts from Tuurem Scavengers and Tuurem Hunters and bring them to Rakoria at Stonebreaker Hold."} end
if not DB[10033] then DB[10033]={id=10033,zoneId=3519,name="Wanted: Bonelashers Dead!",level=65,minLevel=62,ender="Taela Everstride",enderType="NPC",enderId=18704,rewardNextId=10035,wowhead="https://www.wowhead.com/wotlk/quest=10033",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="A bounty is declared on the bonelashers of the Bone Wastes.  As known carriers of the plague, they are to be destroyed forthwith!$B$BWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.$B$BReport to Taela Everstride afterward to collect your reward.",logDesc="Kill 20 Bonelashers and then report to Taela Everstride at the Allerian Stronghold in Terokkar Forest."} end
if not DB[10034] then DB[10034]={id=10034,zoneId=3519,name="Wanted: Bonelashers Dead!",level=65,minLevel=62,ender="Mawg Grimshot",enderType="NPC",enderId=18705,rewardNextId=10036,wowhead="https://www.wowhead.com/wotlk/quest=10034",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="The bonelashers of the Bone Wastes bit Mawg and made him sick.  Now he wants all of them destroyed!$B$BWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.$B$BReturn to Mawg Grimshot after you've done the deed and he'll give you a good reward.",logDesc="Kill 20 Bonelashers and then report to Mawg Grimshot at Stonebreaker Hold in Terokkar Forest."} end
if not DB[10035] then DB[10035]={id=10035,zoneId=3519,name="Torgos!",level=65,minLevel=63,giver="Taela Everstride",giverType="NPC",giverId=18704,ender="Taela Everstride",enderType="NPC",enderId=18704,poiX=-2923,poiY=3946,wowhead="https://www.wowhead.com/wotlk/quest=10035",image="assets/images/quests/placeholder.png",xpDiff=6,money=66000,desc="There's a creature in the Bone Wastes so fearsome that only the dauntless dare to stalk him.$B$BI speak of Torgos, king of the bonelashers, who circles over Veil Rhaze on the western edge of the wastes.$B$BToo bad that there's an arakkoan scarecrow there, known as Torgos's Bane, which keeps him at bay.  I'd bet if you laid his mate Trachela's carcass at the foot of that scarecrow he'd come down anyway.  She can be found at Carrion Hill in the northern wastes.$B$BBring me one of Torgos's tail feathers.",logDesc="Call down Torgos with Trachela's Carcass.  Acquire a Tail Feather of Torgos and return it to Taela Everstride at the Allerian Stronghold in Terokkar Forest.",choiceRewards={{id=25937,qty=1},{id=25936,qty=1}}} end
if not DB[10036] then DB[10036]={id=10036,zoneId=3519,name="Torgos!",level=65,minLevel=63,giver="Mawg Grimshot",giverType="NPC",giverId=18705,ender="Mawg Grimshot",enderType="NPC",enderId=18705,poiX=-2652,poiY=4424,wowhead="https://www.wowhead.com/wotlk/quest=10036",image="assets/images/quests/placeholder.png",xpDiff=6,money=66000,desc="I want Torgos, king of the bonelashers, dead!$B$BNot long ago, while I was out hunting at Veil Rhaze on the western edge of the wastes, he fell upon me.$B$B<Mawg taps his eyepatch.>$B$BHe took my eye, and now I would have his life!  Bring me one of his tail feathers as proof and I'll give you a worthy reward.$B$BYou'll need his mate Trachela's carcass though to call him down as he's deathly afraid of the old arakkoan scarecrow known as Torgos's Bane.$B$BFind her at Carrion Hill in the northern wastes.",logDesc="Call down Torgos with Trachela's Carcass.  Acquire a Tail Feather of Torgos and return it to Mawg Grimshot at Stonebreaker Hold in Terokkar Forest.",choiceRewards={{id=25937,qty=1},{id=25936,qty=1}}} end
if not DB[10037] then DB[10037]={id=10037,zoneId=3519,name="Rather Be Fishin'",level=64,minLevel=62,giver="Seth",giverType="NPC",giverId=18653,ender="Seth",enderType="NPC",enderId=18653,poiX=-1613,poiY=5315,wowhead="https://www.wowhead.com/wotlk/quest=10037",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Speaking of lakes, there's a lake with real good fishin' up to the northeast. I used to go up there with my friends, but my mom won't let me go anymore.$B$BShe says it's too dangerous, but I haven't seen anything up there but a few little spiders. Like spiders can do anything to you...$B$BMy favorites were always the eels that live up there. If you're going to be up by the lake, would you think about bringing back some of the eels? They're feisty but once you subdue 'em, you can bring 'em back no problem.",logDesc="Bring 8 Pristine Shimmerscale Eels to Seth in Shattrath City.",rewards={{id=25978,qty=1}}} end
if not DB[10038] then DB[10038]={id=10038,zoneId=3519,name="Speak with Private Weeks",level=64,minLevel=62,giver="Lieutenant Gravelhammer",giverType="NPC",giverId=18713,ender="Private Weeks",enderType="NPC",enderId=18715,rewardNextId=10040,poiX=-3008,poiY=3978,wowhead="https://www.wowhead.com/wotlk/quest=10038",image="assets/images/quests/placeholder.png",xpDiff=2,desc="A report's just come in from one of our scouts near Grangol'var Village.  He says that a shadowy band has moved into the ruins there.$B$B$N, I want you to speak with Private Weeks and see how you can assist him to figure out what this unknown group is up to.  Just head west past Stonebreaker Hold.  His last report puts his position near the north entrance to the village.",logDesc="Speak with Private Weeks near the north entrance to Grangol'var Village in Terokkar Forest."} end
if not DB[10039] then DB[10039]={id=10039,zoneId=3519,name="Speak with Scout Neftis",level=64,minLevel=62,giver="Advisor Faila",giverType="NPC",giverId=18712,ender="Scout Neftis",enderType="NPC",enderId=18714,rewardNextId=10041,poiX=-2605,poiY=4441,wowhead="https://www.wowhead.com/wotlk/quest=10039",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I am informed that one of our scouts near Grangol'var Village is currently observing a shadowy band that has recently moved in there.$B$B$N, I want you to speak with Scout Neftis and see how you can assist her in figuring out what this unknown group is up to.$B$BJust head south out of here, and then due west, skirting the north of the Bone Wastes.  Her last report puts her position near the southern entrance to the village.",logDesc="Speak with Scout Neftis near the south entrance to Grangol'var Village in Terokkar Forest."} end
if not DB[10040] then DB[10040]={id=10040,zoneId=3519,name="Who Are They?",level=65,minLevel=62,giver="Private Weeks",giverType="NPC",giverId=18715,ender="Private Weeks",enderType="NPC",enderId=18715,rewardNextId=10042,poiX=-2302,poiY=4898,wowhead="https://www.wowhead.com/wotlk/quest=10040",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="I don't know who they are, but I know they're hostile!$B$BI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.$B$BJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.",logDesc="While in disguise, speak with the Shadowy Initiate, the Shadowy Laborer and the Shadowy Advisor.  Then return to Private Weeks at Grangol'var Village in Terokkar Forest."} end
if not DB[10041] then DB[10041]={id=10041,zoneId=3519,name="Who Are They?",level=65,minLevel=62,giver="Scout Neftis",giverType="NPC",giverId=18714,ender="Scout Neftis",enderType="NPC",enderId=18714,rewardNextId=10043,poiX=-2575,poiY=4976,wowhead="https://www.wowhead.com/wotlk/quest=10041",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="I don't know who they are, but I know they're hostile!$B$BI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.$B$BJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.",logDesc="While in disguise, speak with the Shadowy Initiate, the Shadowy Laborer and the Shadowy Advisor.  Then return to Scout Neftis at Grangol'var Village in Terokkar Forest."} end
if not DB[10042] then DB[10042]={id=10042,zoneId=3519,name="Kill the Shadow Council!",level=65,minLevel=62,giver="Private Weeks",giverType="NPC",giverId=18715,ender="Lieutenant Gravelhammer",enderType="NPC",enderId=18713,poiX=-2302,poiY=4898,wowhead="https://www.wowhead.com/wotlk/quest=10042",image="assets/images/quests/placeholder.png",xpDiff=6,money=66000,desc="What!  Those guys are Shadow Council?!$B$B$N, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.$B$BAfter you're done with that, report back to Lieutenant Gravelhammer at the Allerian Stronghold.$B$BGood luck, $c!",logDesc="Kill 10 Shadowy Executioners, 10 Shadowy Summoners and Shadowmaster Grieve, and then return to Lieutenant Gravelhammer at the Allerian Stronghold in Terokkar Forest.",choiceRewards={{id=25933,qty=1},{id=25935,qty=1},{id=25934,qty=1}}} end
if not DB[10043] then DB[10043]={id=10043,zoneId=3519,name="Kill the Shadow Council!",level=65,minLevel=62,giver="Scout Neftis",giverType="NPC",giverId=18714,ender="Advisor Faila",enderType="NPC",enderId=18712,poiX=-2575,poiY=4976,wowhead="https://www.wowhead.com/wotlk/quest=10043",image="assets/images/quests/placeholder.png",xpDiff=6,money=66000,desc="What!  Those guys are Shadow Council?!$B$B$N, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.$B$BAfter you're done with that, report back to Advisor Faila at Stonebreaker Hold.$B$BGood luck, $c!",logDesc="Kill 10 Shadowy Executioners, 10 Shadowy Summoners and Shadowmaster Grieve, and then return to Advisor Faila at Stonebreaker Hold in Terokkar Forest.",choiceRewards={{id=25933,qty=1},{id=25935,qty=1},{id=25934,qty=1}}} end
if not DB[10044] then DB[10044]={id=10044,zoneId=3518,name="A Visit With the Greatmother",level=68,minLevel=66,giver="Garrosh",giverType="NPC",giverId=18063,ender="Greatmother Geyah",enderType="NPC",enderId=18141,rewardNextId=10045,poiX=-1345,poiY=7233,wowhead="https://www.wowhead.com/wotlk/quest=10044",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Greatmother has asked that I seek you out and deliver a message. She wishes to speak with you at once.$B$BMy will has been sapped but make no mistake, $N, if you anger the Greatmother, I will come down upon you with all the force that I can muster. She is in the main hall.$B$B<Garrosh points at the large building to the north.>$B$BListen to what she has to say and do as she tells you.",logDesc="Speak to Greatmother Geyah and listen to what she has to tell you.$B"} end
if not DB[10045] then DB[10045]={id=10045,zoneId=3518,name="Material Components",level=68,minLevel=66,giver="Greatmother Geyah",giverType="NPC",giverId=18141,ender="Greatmother Geyah",enderType="NPC",enderId=18141,rewardNextId=10081,poiX=-1222,poiY=7163,wowhead="https://www.wowhead.com/wotlk/quest=10045",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Mother Kashur wishes to speak with you, $N. Before this becomes possible, you must collect the herbs required to create a potion that will expand your mind, allowing you to commune with the spirits.$B$BYou must gather Olemba root from Terokkar, marshberries from Zangarmarsh, Telaari fronds from Nagrand and dragonspine from the Blade's Edge mountains. I have written down instructions on this parchment as to the cultivation of these herbs. Return to me when you have gathered the materials.",logDesc="Greatmother Geyah at Garadar in Nagrand has asked that you collect 1 Olemba Root, 1 Marshberry, 1 Telaari Frond and 1 Dragonspine.$B"} end
if not DB[10046] then DB[10046]={id=10046,zoneId=3483,name="Through the Dark Portal",level=60,minLevel=54,wowhead="https://www.wowhead.com/wotlk/quest=10046",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Two weeks ago, our scouts reported a heavily armed Alliance force under the command of Field Commander Romus departing Nethergarde Keep. With so many soldiers and supplies, along with such a distinguished commander, they can only have one goal: Outland.$B$BThe warchief sent an advance force through the portal, but if the Alliance believes there is a need for that many troops, perhaps we'd be wise to send our own reinforcements.$B$BJourney through the Dark Portal and report to Nazgrel at Thrallmar.",logDesc="Travel through the Dark Portal and speak with Nazgrel at Thrallmar."} end
if not DB[10047] then DB[10047]={id=10047,zoneId=3483,name="The Path of Glory",level=61,minLevel=58,giver="Warp-Scryer Kryv",giverType="NPC",giverId=16839,ender="Warp-Scryer Kryv",enderType="NPC",enderId=16839,rewardNextId=10093,poiX=-809,poiY=2612,wowhead="https://www.wowhead.com/wotlk/quest=10047",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The 'Path of Glory,' they called it. A road leading from the heart of their gruesome fortress to the Dark Portal, paved with the bones of my people.$B$BIt wasn't enough for them to hunt us down like animals, destroy our cities, and torture those who survived. No, they had to use our bones as paving stones, denying my brethren a proper burial under the Light.$B$BThose tortured souls still wander these lands, crying out for release. I ask you, $N, help me in this undertaking.",logDesc="Cleanse 8 Trampled Skeletons on the Path of Glory with Draenei Holy Water, then return to Warp-Scryer Kryv at Honor Hold."} end
if not DB[10048] then DB[10048]={id=10048,zoneId=3519,name="A Handful of Magic Dust",level=64,minLevel=62,wowhead="https://www.wowhead.com/wotlk/quest=10048",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="I'm going to need dust, but not just any dust.$B$BThe royal teromoths that inhabit the forest nearby have a magical dust upon their wings, which they use to pacify those that hunt them.  I can make use of that property of the dust to assuage the resistance that I am feeling from the arakkoa eyes you retrieved.  This, in turn, will allow me to use them to find Deirom.$B$BI won't need much, perhaps half a dozen handfuls, or so.",logDesc="Collect 7 handfuls of Pacifying Dust for Andarl at the Allerian Stronghold."} end
if not DB[10049] then DB[10049]={id=10049,zoneId=3519,name="A Handful of Magic Dust",level=64,minLevel=62,wowhead="https://www.wowhead.com/wotlk/quest=10049",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="I'm going to need dust, but not just any dust.$B$BThe royal teromoths that inhabit the forest nearby have a magical dust upon their wings, which they use to pacify those that hunt them.  I can make use of that property of the dust to assuage the resistance that I am feeling from the arakkoa eyes you retrieved.  This, in turn, will allow me to use them to find Dugar.$B$BI won't need much, perhaps half a dozen handfuls, or so.",logDesc="Collect 7 handfuls of Pacifying Dust for Kurgatok at Stonebreaker Hold."} end
if not DB[10050] then DB[10050]={id=10050,zoneId=3483,name="Unyielding Souls",level=61,minLevel=58,giver="Honor Guard Wesilow",giverType="NPC",giverId=16827,ender="Honor Guard Wesilow",enderType="NPC",enderId=16827,rewardNextId=10057,poiX=-597,poiY=2912,wowhead="https://www.wowhead.com/wotlk/quest=10050",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Near the end of our invasion, the Armory to the south fell under attack by the Horde's insidious Death Knights. Those vile shades cursed the Armory's defenders - and trapped their souls between the realms of the living and the dead.$B$BThose noble souls must be set free! I beg you, $N, end my comrades' torment, for I have not the heart to slay them myself.",logDesc="Honor Guard Wesilow wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south."} end
if not DB[10051] then DB[10051]={id=10051,zoneId=3519,name="Escape from Firewing Point!",level=64,minLevel=62,giver="Isla Starmane",giverType="NPC",giverId=18760,ender="Captain Auric Sunchaser",enderType="NPC",enderId=18745,poiX=-2265,poiY=3091,wowhead="https://www.wowhead.com/wotlk/quest=10051",image="assets/images/quests/placeholder.png",xpDiff=6,money=62000,desc="Thank goodness for you!$B$B$C, I need you to help me escape.  I have information vital to the security of the Allerian Stronghold and probably all of Outland!$B$BI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!$B$BWe won't be able to do this on our own - you do have a group with you, right?",logDesc="Escort Isla Starmane to safety and then report to Captain Auric Sunchaser at the Allerian Stronghold in Terokkar Forest.",choiceRewards={{id=25918,qty=1},{id=25917,qty=1},{id=25916,qty=1}}} end
if not DB[10052] then DB[10052]={id=10052,zoneId=3519,name="Escape from Firewing Point!",level=64,minLevel=62,giver="Isla Starmane",giverType="NPC",giverId=18760,ender="Advisor Faila",enderType="NPC",enderId=18712,poiX=-2265,poiY=3091,wowhead="https://www.wowhead.com/wotlk/quest=10052",image="assets/images/quests/placeholder.png",xpDiff=6,money=62000,desc="Thank goodness for you!$B$B$C, I need you to help me escape.  I have information vital to the security of Stonebreaker Hold and probably all of Outland!$B$BI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!$B$BWe won't be able to do this on our own - you do have a group with you, right?",logDesc="Escort Isla Starmane to safety and then report to Advisor Faila at Stonebreaker Hold in Terokkar Forest.",choiceRewards={{id=25918,qty=1},{id=25917,qty=1},{id=25916,qty=1}}} end
if not DB[10053] then DB[10053]={id=10053,zoneId=3483,name="Dealing with Zeth'Gor",level=61,minLevel=58,rewardNextId=10054,wowhead="https://www.wowhead.com/wotlk/quest=10053",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="It is imperative that we follow up on the momentum created by your defeat of Warboss Nekrogg, $N. If we're lucky, the leadership at Zeth'Gor won't have heard about Nekrogg.$B$BThe Bonechewers at Zeth'Gor to the southeast are usually led into battle by Grillok \"Darkeye\". Seek him out in his lair, a cave cut beneath the fel orc settlement, and kill him. Once he is dead, search the cave for the fel orc battle plans. We must not be taken by surprise.",logDesc="Defeat Grillok \"Darkeye\" and search his lair for the Bleeding Hollow Attack Plans."} end
if not DB[10054] then DB[10054]={id=10054,zoneId=3483,name="Impending Doom",level=61,minLevel=58,rewardNextId=10138,wowhead="https://www.wowhead.com/wotlk/quest=10054",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="A quick examination of the plans reveals Zeth'Gor's leader, Warlord Morkh, as the mastermind behind the attacks led by Bone Magus Warlor. There's more to the map than just Morkh's forces.$B$BThe plans indicate that the Bonechewer force is armed and marshalling for an all out attack on Honor Hold in concert with forces from Hellfire Citadel.$B$BThere's no time to bring word to Lieutenant Amadi. You must stop the Bonechewer forces before they can launch their attack!",logDesc="Slay 15 Bleeding Hollow Grunts, 10 Bleeding Hollow Necrolytes, 5 Bleeding Hollow Peons, and Warlord Morkh, then make your report to Lieutenant Amadi at Honor Hold's western tower."} end
if not DB[10055] then DB[10055]={id=10055,zoneId=3483,name="Waste Not, Want Not",level=61,minLevel=58,giver="Dumphry",giverType="NPC",giverId=21209,ender="Dumphry",enderType="NPC",enderId=21209,rewardNextId=10078,poiX=-595,poiY=2899,wowhead="https://www.wowhead.com/wotlk/quest=10055",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Reinforcements are great, but I don't see 'em haulin' any wagons loaded with ingots or timber.$B$BTake a look around, friend. Trees are in short supply, and the mines are overrun with Legion scum.$B$BI'm in a bad way fer supplies, and I'm makin' what substitutions I can, but it's time to start reusing what we can.$B$BThe southern edge of the Path o' Glory is strewn with the ruins of siege machinery. Some pieces of 'em are still usable. Feeling up to a bit o' a salvage operation?",logDesc="Bring 8 pieces of Salvaged Metal and 8 pieces of Salvaged Wood to Dumphry at Honor Hold.",choiceRewards={{id=29931,qty=1},{id=29938,qty=1},{id=29943,qty=1},{id=29945,qty=1}}} end
if not DB[10056] then DB[10056]={id=10056,zoneId=3483,name="Bleeding Hollow Supplies",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10056",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The orcish ruins of Zeth'Gor to the southeast serve as a base for an ever-growing tide of orcs emerging from Hellfire Citadel.$B$BThe Sons of Lothar have been fighting them for some time, and the stories they tell would be nigh unbelievable if I hadn't seen these 'fel' orcs with my own eyes.$B$BSomething has changed them, augmented them in a way we've never seen before. We have to do anything we can to keep them from strengthening. Go to Zeth'Gor and destroy any supplies you find there.",logDesc="Destroy 6 piles of Bleeding Hollow Supplies and report to Lieutenant Amadi at Honor Hold."} end
if not DB[10057] then DB[10057]={id=10057,zoneId=3483,name="Looking to the Leadership",level=61,minLevel=58,giver="Honor Guard Wesilow",giverType="NPC",giverId=16827,ender="Honor Guard Wesilow",enderType="NPC",enderId=16827,poiX=-597,poiY=2912,wowhead="https://www.wowhead.com/wotlk/quest=10057",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The disturbances at Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.$B$BPerhaps we've been approaching this the wrong way. I've always assumed that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?$B$BArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.",logDesc="Overcome the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos and return to Honor Guard Wesilow in the tower northwest of Honor Hold.",choiceRewards={{id=25989,qty=1},{id=25992,qty=1},{id=25993,qty=1}}} end
if not DB[10058] then DB[10058]={id=10058,zoneId=3483,name="An Old Gift",level=61,minLevel=58,giver="Father Malgor Devidicus",giverType="NPC",giverId=16825,ender="Father Malgor Devidicus",enderType="NPC",enderId=16825,poiX=-708,poiY=2736,wowhead="https://www.wowhead.com/wotlk/quest=10058",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="<The priest's gaze slowly moves from his mug to you.>$B$BDon't you know better than to bother a man in his cups?$B$BOh, what's the use? I suppose newcomers are a good sign. What would Turalyon think?$B$BI remember the eve of our departure, when I gave Mysteries of the Light to him. During the campaign and the ensuing years, he never forgot to read his daily passage to the men.$B$BWhen he left us again, he gave the book back to me. Like a fool, I believed it safe in my quarters to the south of the armory.",logDesc="Retrieve Mysteries of the Light and return it to Father Malgor Devidicus at Honor Hold."} end
if not DB[10059] then DB[10059]={id=10059,zoneId=3483,name="Dealing With Zeth'Gor",level=61,minLevel=58,rewardNextId=10060,wowhead="https://www.wowhead.com/wotlk/quest=10059",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="It is imperative that we follow up on the momentum created by your defeat of Warboss Nekrogg, $N. If we're lucky, the leadership at Zeth'Gor won't have heard about Nekrogg.$B$BThe Bonechewers at Zeth'Gor are usually led into battle by Grillok \"Darkeye\". Seek him out in his lair, a cave cut into the rock beneath the outpost, and kill him. Once he is dead, search the cave for the fel orc battle plans. Thrallmar must not be taken by surprise.",logDesc="Slay Grillok \"Darkeye\" and search his lair for the Bleeding Hollow Attack Plans."} end
if not DB[10060] then DB[10060]={id=10060,zoneId=3483,name="Impending Doom",level=61,minLevel=58,rewardNextId=10156,wowhead="https://www.wowhead.com/wotlk/quest=10060",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="A quick examination of the plans reveals Zeth'Gor's leader, Warlord Morkh, as the mastermind behind the attacks led by Bone Magus Warlor. There's more to the map than just Morkh's forces.$B$BThe plans indicate that the Bonechewer force is armed and marshalling for an all out attack on Thrallmar in concert with forces from Hellfire Citadel.$B$BThere's no time to bring word back to Thrallmar. You must stop the Bonechewer forces before they can launch their attack!",logDesc="Slay 15 Bleeding Hollow Grunts, 10 Bleeding Hollow Necrolytes, 5 Bleeding Hollow Peons, and Warlord Morkh. Then report to Stone Guard Ambelan at Spinebreaker Ridge."} end
if not DB[10061] then DB[10061]={id=10061,zoneId=3483,name="The Unyielding",level=61,minLevel=58,rewardNextId=10062,wowhead="https://www.wowhead.com/wotlk/quest=10061",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="When the Bonechewer fel orcs attacked the Expedition Armory, the garrison there fell quickly.  The battle was bloody and fierce, and there were no survivors.$B$BAlthough the dead were buried, their spirits continue to haunt those ruins.  Of late, I have been receiving visions that these spirits may soon become a threat to Thrallmar.$B$BThere is only one course of action to take.  We must grant these spirits rest.  You must overcome them in battle.",logDesc="Grelag wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south of Honor Hold."} end
if not DB[10062] then DB[10062]={id=10062,zoneId=3483,name="Looking to the Leadership",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10062",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The disturbances at the Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.$B$BWe may be approaching this the wrong way. My visions suggested that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?$B$BArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.",logDesc="Overcome the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos and return to Grelag at Spinebreaker Ridge.",choiceRewards={{id=25993,qty=1},{id=25992,qty=1},{id=25989,qty=1}}} end
if not DB[10063] then DB[10063]={id=10063,zoneId=3525,name="Explorers' League, Is That Something for Gnomes?",level=17,minLevel=13,giver="Prospector Nachlan",giverType="NPC",giverId=18804,ender="Clopper Wizbang",enderType="NPC",enderId=17421,poiX=-1938,poiY=-11912,wowhead="https://www.wowhead.com/wotlk/quest=10063",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Babysitting! Would you believe it?$B$BThey pulled me out of a promising dig and sent me along with Captain Odesyus' expedition to babysit that little gnome!$B$BI'd never heard o' a gnome wanting to become a prospector before, so I asked.$B$BSeems we are takin' gnomes now, and this particular one has a fascination with murlocs!$B$BWell, he's gone off and set up shop in an old turtle shell on the northern shore of the island. Go and have a look if you don't believe me!",logDesc="Find Clopper Wizbang camped in an old turtle shell on the shore north of Blood Watch."} end
if not DB[10064] then DB[10064]={id=10064,zoneId=3525,name="Talk to the Hand",level=18,minLevel=16,giver="Harbinger Mikolaas",giverType="NPC",giverId=17423,ender="Scout Jorli",enderType="NPC",enderId=17927,poiX=-1916,poiY=-11791,wowhead="https://www.wowhead.com/wotlk/quest=10064",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Hand of Argus has established a forward base at Vindicator's Rest, but they are sorely outnumbered by both the blood elves and mutated wildlife. Without backup, their outpost is in danger of falling, and we'd have no way to keep an eye on events near the Vector Coil.$B$BReport to Scout Jorli at Vindicator's Rest to the northwest and offer her your assistance, $N.",logDesc="Report to Scout Jorli at Vindicator's Rest."} end
if not DB[10065] then DB[10065]={id=10065,zoneId=3525,name="Cutting a Path",level=17,minLevel=16,giver="Scout Jorli",giverType="NPC",giverId=17927,ender="Scout Jorli",enderType="NPC",enderId=17927,poiX=-1757,poiY=-11062,wowhead="https://www.wowhead.com/wotlk/quest=10065",image="assets/images/quests/placeholder.png",xpDiff=5,desc="During our mission to reconnoiter the Sunhawks and their portal, I sustained a serious wound. Scout Loryi has managed to staunch the bleeding and she's trying to figure out a way to evacuate me to Blood Watch.$B$BThe problem is that we'd have to abandon our position here in order to guarantee a safe return.$B$BAs soon as we leave this consecrated ground, we'll be set upon by ravagers. If you can clear some of the enraged ravagers, it might allow us to make the trip back safely.",logDesc="Kill 10 Enraged Ravagers and return to Scout Jorli at Vindicator's Rest."} end
if not DB[10066] then DB[10066]={id=10066,zoneId=3525,name="Oh, the Tangled Webs They Weave",level=18,minLevel=16,giver="Vindicator Corin",giverType="NPC",giverId=17986,ender="Vindicator Corin",enderType="NPC",enderId=17986,poiX=-1777,poiY=-11078,wowhead="https://www.wowhead.com/wotlk/quest=10066",image="assets/images/quests/placeholder.png",xpDiff=6,money=1000,desc="We don't dare abandon our post, or wander too far from Vindicator's Rest, $r. The mutated creatures closest to the Vector Coil have been changed profoundly by energy leaking from the crystals.$B$BThe mutated tanglers appear to have gained a certain degree of sentience. They've learned to create, set, and conceal vicious traps that can ensnare even the most careful warrior.$B$BWe'll never be able to move against the Sunhawks if we're constantly forced to look underfoot. Attack the problem at its source, $N.",logDesc="Kill 8 Mutated Tanglers and report to Vindicator Corin at Vindicator's Rest."} end
if not DB[10067] then DB[10067]={id=10067,zoneId=3525,name="Fouled Water Spirits",level=19,minLevel=16,giver="Vindicator Corin",giverType="NPC",giverId=17986,ender="Vindicator Corin",enderType="NPC",enderId=17986,poiX=-1777,poiY=-11078,wowhead="https://www.wowhead.com/wotlk/quest=10067",image="assets/images/quests/placeholder.png",xpDiff=5,money=1100,desc="Most of the creatures touched by the crystals' energy have been corrupted in the same ways: strange marks on their flesh, increased aggression, and small crystal shards in their bodies. However, the fouled water spirits north of here appear to be turning entirely to crystal.$B$BI've never seen anything react to the crystals this way before, when we explored the foul pool, they were particularly dangerous. We must get rid of them before the Sunhawks can exploit them as a new source of energy.",logDesc="Kill 6 Fouled Water Spirits and return to Vindicator Corin at Vindicator's Rest."} end
if not DB[10068] then DB[10068]={id=10068,zoneId=3431,name="Well Watcher Solanian",level=2,minLevel=2,giver="Julia Sunstriker",giverType="NPC",giverId=15279,ender="Well Watcher Solanian",enderType="NPC",enderId=15295,poiX=10337,poiY=-6419,wowhead="https://www.wowhead.com/wotlk/quest=10068",image="assets/images/quests/placeholder.png",xpDiff=1,desc="And now, I need for you to do something.$B$BWell Watcher Solanian is in need of your services.  You would do well to ingratiate yourself with him.$B$BHe awaits you on the exterior platform that the ramp in this chamber leads up to.",logDesc="Speak with Well Watcher Solanian at the Sunspire on Sunstrider Isle."} end
