if not DB[10074] then DB[10074]={id=10074,zoneId=3518,name="Oshu'gun Crystal Powder",level=67,minLevel=64,giver="Chief Researcher Amereldine",giverType="NPC",giverId=18816,ender="Chief Researcher Amereldine",enderType="NPC",enderId=18816,wowhead="https://www.wowhead.com/wotlk/quest=10074",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="This base was the primary draenei research facility for the study of naaru crystals.$B$BWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.",logDesc="Chief Researcher Amereldine at Halaa wants 10 Oshu'gun Crystal Powder Samples.",rewards={{id=26044,qty=1}}} end
if not DB[10075] then DB[10075]={id=10075,zoneId=3518,name="Oshu'gun Crystal Powder",level=67,minLevel=64,giver="Chief Researcher Amereldine",giverType="NPC",giverId=18816,ender="Chief Researcher Amereldine",enderType="NPC",enderId=18816,wowhead="https://www.wowhead.com/wotlk/quest=10075",image="assets/images/quests/placeholder.png",xpDiff=4,money=29000,rewards={{id=26044,qty=1}}} end
if not DB[10076] then DB[10076]={id=10076,zoneId=3518,name="Oshu'gun Crystal Powder",level=67,minLevel=64,giver="Chief Researcher Kartos",giverType="NPC",giverId=18817,ender="Chief Researcher Kartos",enderType="NPC",enderId=18817,wowhead="https://www.wowhead.com/wotlk/quest=10076",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="This base was the primary draenei research facility for the study of naaru crystals.$B$BWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.",logDesc="Chief Researcher Kartos at Halaa wants 10 Oshu'gun Crystal Powder Samples.",rewards={{id=26044,qty=1}}} end
if not DB[10077] then DB[10077]={id=10077,zoneId=3518,name="Oshu'gun Crystal Powder",level=67,minLevel=64,giver="Chief Researcher Kartos",giverType="NPC",giverId=18817,ender="Chief Researcher Kartos",enderType="NPC",enderId=18817,wowhead="https://www.wowhead.com/wotlk/quest=10077",image="assets/images/quests/placeholder.png",xpDiff=4,money=29000,rewards={{id=26044,qty=1}}} end
if not DB[10078] then DB[10078]={id=10078,zoneId=3483,name="Laying Waste to the Unwanted",level=61,minLevel=58,giver="Dumphry",giverType="NPC",giverId=21209,ender="Dumphry",enderType="NPC",enderId=21209,poiX=-595,poiY=2899,wowhead="https://www.wowhead.com/wotlk/quest=10078",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Now that we've gotten our salvage operation off the ground, it's time to begin the second phase of the plan.$B$BAcross the Path of Glory, the Horde still has their old blade throwers trained on us. Don't let their age fool you, $N, they're still very dangerous. Much as we're working to reclaim what we can, we can't assume the Horde is going to dismantle their weaponry.$B$BTake this torch and burn the remaining siege equipment. I'll take no chances with Honor Hold's safety.",logDesc="Use the Flaming Torch to burn the Horde Blade Throwers overlooking the Path of Glory.  Then, bring the Flaming Torch to Dumphry in Honor Hold.",choiceRewards={{id=29928,qty=1},{id=29930,qty=1},{id=29934,qty=1},{id=29941,qty=1}}} end
if not DB[10079] then DB[10079]={id=10079,zoneId=3483,name="When This Mine's a-Rockin'",level=61,minLevel=58,giver="Foreman Biggums",giverType="NPC",giverId=16837,ender="Foreman Biggums",enderType="NPC",enderId=16837,rewardNextId=10099,poiX=-673,poiY=2853,wowhead="https://www.wowhead.com/wotlk/quest=10079",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The mine's been overrun by a plague of gan'arg misfits!$B$BNot only did they run all my workers out of the tunnels, but they're pounding away in there night and day! To make things worse, now I've got Danath on me back! He says he's going to take away me ale ration if I don't get this taken care of soon!$B$BNone of the miners'll go in there, and the guards are busy drinking themselves silly.$B$BI'm begging you, $N, help me here. Danath can take me dignity, but he'll never take me ale!",logDesc="Kill 12 Gan'arg Sappers and return to Foreman Biggums."} end
if not DB[10080] then DB[10080]={id=10080,zoneId=3483,name="Forge Camps of the Legion",level=61,minLevel=255,rewardNextId=10083,wowhead="https://www.wowhead.com/wotlk/quest=10080",image="assets/images/quests/placeholder.png",xpDiff=6,desc="If you've spoken to Humphry,he's undoubtedly told you that he finds the infestation in the mines a minor annoyance,but I know it for what it is: a symptom of a larger evil.$B$BTo the northeast of the Horde outpost of Thrallmar,the Legion's minions labor night and day on something,but what is it?$B$BNone of the scouts I've dispatched to the camps have ever returned. The time for subtlety has passed,$N. Fight your way into Forge Camp: Rage and find out just what the Legion is up to.",logDesc="Kill 10 Gan'arg Servants,5 Forge Camp Legionnaires,and 5 Sisters of Grief,then search Forge Camp: Rage for evidence of the Legion's intentions."} end
if not DB[10081] then DB[10081]={id=10081,zoneId=3518,name="To Meet Mother Kashur",level=68,minLevel=66,giver="Greatmother Geyah",giverType="NPC",giverId=18141,ender="Mother Kashur",enderType="NPC",enderId=18687,rewardNextId=10082,poiX=-1222,poiY=7163,wowhead="https://www.wowhead.com/wotlk/quest=10081",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Do not be alarmed by what you might see once the effect has taken hold! These spirits are all around us - always. The potion allows your mind to be able to understand and ultimately see the spirits. You will need to be under its influence if you are to speak with Mother Kashur.$B$BYou will find her a great ways to the southwest, at the Ancestral Grounds.$B",logDesc="Greatmother Geyah wants you to speak with Mother Kashur."} end
if not DB[10082] then DB[10082]={id=10082,zoneId=3518,name="The Agitated Ancestors",level=68,minLevel=66,giver="Mother Kashur",giverType="NPC",giverId=18687,ender="Mother Kashur",enderType="NPC",enderId=18687,rewardNextId=10085,poiX=-2210,poiY=8820,wowhead="https://www.wowhead.com/wotlk/quest=10082",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Do you see them walking around us? The Ancestral Grounds are normally quiet and undisturbed.$B$BAs of late, the ancestral spirits have risen and are extremely agitated. Something is causing a great disturbance to the spirits. We must discover what that something could be, but first, we must put the immediate threat to rest.$B$BThese ghosts that you see walking about are not truly the ancestors but a representation of their state of being. You must destroy the agitated orc spirits. Do this and return to me.",logDesc="Mother Kashur has asked that you put to rest 8 Agitated Orc Spirits.$B"} end
if not DB[10083] then DB[10083]={id=10083,zoneId=3483,name="The Legion's Plans",level=61,minLevel=255,rewardNextId=10084,wowhead="https://www.wowhead.com/wotlk/quest=10083",image="assets/images/quests/placeholder.png",xpDiff=6,money=40000,desc="You make a copy of the glowing glyphs etched into the ground, but without the second half, the diagram doesn't make sense.$B$BField Marshall Rohamus mentioned another camp to the west, Forge Camp: Spite. Could that be where the Legion is keeping the other half of the plans?$B$BIf the Legion has undertaken a massive production campaign, assembling at multiple sites would make sense.",logDesc="Retrieve the Forge Camp: Spite Plans and return them to Field Marshal Rohamus at Expedition Point."} end
if not DB[10084] then DB[10084]={id=10084,zoneId=3483,name="Assault on Mageddon",level=61,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10084",image="assets/images/quests/placeholder.png",xpDiff=7,money=60000,desc="With the skills of the mo'arg engineers and an endless supply of their gan'arg minions, they'll begin churning out fel reavers before we can get word to Nethergarde.$B$BWe have no choice but to move against them as soon as possible. We cannot strip Honor Hold's defenses to support you in this offensive, for to do so would be suicide. The fel orcs and the Horde will pounce on us at the first sign of weakness.$B$BHonor Hold has stood for 20 years, and we don't intend to lose it now.",logDesc="Kill Nightlord Malphas at Forge Base: Mageddon, and report to Force Commander Danath Trollbane at Honor Hold.",choiceRewards={{id=25995,qty=1},{id=25996,qty=1},{id=25994,qty=1}}} end
if not DB[10085] then DB[10085]={id=10085,zoneId=3518,name="A Visit With The Ancestors",level=68,minLevel=66,giver="Mother Kashur",giverType="NPC",giverId=18687,ender="Mother Kashur",enderType="NPC",enderId=18687,rewardNextId=10101,poiX=-2210,poiY=8820,wowhead="https://www.wowhead.com/wotlk/quest=10085",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I need for you to journey to the villages of the ancestors, $N. Seek each one out and see if the ancestors remain.$B$BVisit Sunspring Post to the north, visit the Laughing Skull Ruins far to the north against the mountains, visit Garadar to the northeast, and finally, visit the Bleeding Hollow Ruins on the borders of Nagrand and the Terokkar Forest, to the east.$B$BReturn to me once you have observed the ancestors in their homes.",logDesc="Mother Kashur at the Ancestral Grounds in Nagrand has asked that you Visit Sunspring Post, Visit Laughing Skull Ruins, Visit Garadar and Visit Bleeding Hollow Ruins."} end
if not DB[10086] then DB[10086]={id=10086,zoneId=3483,name="I Work... For the Horde!",level=61,minLevel=58,giver="Megzeg Nukklebust",giverType="NPC",giverId=21283,ender="Megzeg Nukklebust",enderType="NPC",enderId=21283,rewardNextId=10087,poiX=145,poiY=2690,wowhead="https://www.wowhead.com/wotlk/quest=10086",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Would you believe it?  These orcs hired me to help them shore up damaged fortifications and build explosives.  What a dream job!  It's too bad we're so short on materials, but a clever goblin like myself learns how to make do!$B$BCan you help me?  I need salvaged wood and metal from the ruined battlements along the Path of Glory.  Go down there and salvage, and watch out for those red-skinned orcs!$B$BWhen you're done, come back for big rewards!",logDesc="Bring 8 pieces of Salvaged Metal and 8 pieces of Salvaged Wood to Megzeg Nukklebust in Thrallmar.",choiceRewards={{id=29931,qty=1},{id=29938,qty=1},{id=29943,qty=1},{id=29945,qty=1}}} end
if not DB[10087] then DB[10087]={id=10087,zoneId=3483,name="Burn It Up... For the Horde!",level=61,minLevel=58,giver="Megzeg Nukklebust",giverType="NPC",giverId=21283,ender="Megzeg Nukklebust",enderType="NPC",enderId=21283,poiX=145,poiY=2690,wowhead="https://www.wowhead.com/wotlk/quest=10087",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="I'm a lucky, lucky goblin.  I get to make explosives and killing machines, knowing they'll be used immediately on important missions!$B$BSpeaking of missions, I just got one from Thrallmar command: burn the Alliance cannons on the far side of the Path of Glory... the ones pointing dangerously close to Horde fortifications.  Take this torch and make your way to each cannon.  Fire the torch and watch the sparks fly!",logDesc="Use the Flaming Torch to burn the Eastern Alliance Cannon and the Western Alliance Cannon, and then return to Megzeg Nukklebust in Thrallmar.",choiceRewards={{id=29928,qty=1},{id=29930,qty=1},{id=29934,qty=1},{id=29941,qty=1}}} end
if not DB[10088] then DB[10088]={id=10088,zoneId=3483,name="When This Mine's a-Rockin'",level=61,minLevel=255,rewardNextId=10100,wowhead="https://www.wowhead.com/wotlk/quest=10088",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The mine's been overrun by a plague of gan'arg misfits, and on top of that, the peons have decided that this is a fine time for a nap! I don't know how they can sleep through all the disturbances coming from the mine, but that's the least of my problems.$B$BIf we don't get rid of those gan'arg pests soon, Thrallmar's supply of ore and other minerals will be cut off. I've already asked Watch Commander Krunk for help, but he says he can't spare the men with the town under constant attack. Will you help?",logDesc="Kill 12 Gan'arg Sappers and return to Foreman Razelcraz."} end
if not DB[10089] then DB[10089]={id=10089,zoneId=3483,name="Forge Camps of the Legion",level=61,minLevel=255,rewardNextId=10090,wowhead="https://www.wowhead.com/wotlk/quest=10089",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Thrallmar has been subjected to bombardment from the Legion Camps since its establishment. We've managed to hold out so far, but the situation is getting more desperate with every day.$B$BShadow Hunter Ty'jin has made several attempts to learn more about the camps, but none of his scouts ever returned.$B$BThe time for subtlety has passed, $N. Fight your way into Forge Camp: Rage and find out just what the Legion is up to.",logDesc="Kill 10 Gan'arg Servants, 5 Forge Camp Legionnaires, and 5 Sisters of Grief, then search Forge Camp: Rage for evidence of the Legion's intentions."} end
if not DB[10090] then DB[10090]={id=10090,zoneId=3483,name="The Legion's Plans",level=61,minLevel=255,rewardNextId=10092,wowhead="https://www.wowhead.com/wotlk/quest=10090",image="assets/images/quests/placeholder.png",xpDiff=6,money=40000,desc="You make a copy of the glowing glyphs etched into the ground, but without the second half, the diagram doesn't make sense.$B$BThe glyphs indicate that another camp to the west, Forge Camp: Spite, is also involved in the project. Could that be where the Legion is keeping the other half of the plans?$B$BIf the Legion was forging something truly monstrous, assembling it at multiple sites would make sense.",logDesc="Retrieve the Forge Camp: Spite Plans and return them to Overlord Hun Maimfist at Reaver's Fall."} end
if not DB[10091] then DB[10091]={id=10091,zoneId=3688,name="The Soul Devices",level=70,minLevel=68,giver="Spy To'gun",giverType="NPC",giverId=18891,ender="Spymistress Mehlisah Highcrown",enderType="NPC",enderId=18893,poiX=-61,poiY=41,wowhead="https://www.wowhead.com/wotlk/quest=10091",image="assets/images/quests/placeholder.png",xpDiff=8,money=88000,desc="Gah!  They've been torturing me, trying to get me to tell them everything that I know.$B$BI failed - they fed the others to Hellmaw, and I was to be next.  But I told them nothing!$B$BThey're crazy!  They're hell-bent on summoning demonic forces that they have no way of controlling!$B$BThey're using special devices to make their soul shards, and their summoning, more powerful.  You must steal these devices!$B$BI would join you, but I must return to Shattrath City to report to the Lower City's spymistress.",logDesc="Steal 5 Soul Devices and deliver them to Spymistress Mehlisah Highcrown at the Terrace of the Light in Shattrath City.",choiceRewards={{id=28174,qty=1},{id=28171,qty=1},{id=28170,qty=1},{id=28167,qty=1}}} end
if not DB[10092] then DB[10092]={id=10092,zoneId=3483,name="Assault on Mageddon",level=61,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10092",image="assets/images/quests/placeholder.png",xpDiff=7,money=60000,desc="With the skills of the mo'arg engineers and an endless supply of their gan'arg minions, they'll have churned out a fleet of fel reavers before we can get word to Orgrimmar.$B$BWe have no choice but to move against them as soon as possible. I cannot use Thrallmar's garrison to support you, since it would leave us too vulnerable.$B$BThere are any number of opportunists, the Alliance notwithstanding, who would eagerly pounce on our unprotected outpost. Do not fail, $N. Too much depends on you.",logDesc="Kill Nightlord Malphas at Forge Base: Mageddon, and return to Overlord Hun Maimfist at Reaver's Fall.",choiceRewards={{id=25995,qty=1},{id=25994,qty=1},{id=25996,qty=1}}} end
if not DB[10093] then DB[10093]={id=10093,zoneId=3483,name="The Temple of Telhamat",level=63,minLevel=58,giver="Warp-Scryer Kryv",giverType="NPC",giverId=16839,ender="Amaan the Wise",enderType="NPC",enderId=16796,poiX=-809,poiY=2612,wowhead="https://www.wowhead.com/wotlk/quest=10093",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Fortunately, the Path of Glory is not the only trace of my people in these lands. To the west, a few of our holy sites survive, although some have been overrun.$B$BWhile Velen prepared for the journey that would lead him to Azeroth, those of us who would remain behind sought to reestablish a presence at our holy places.$B$BIn the western part of the Hellfire Peninsula, you will find a small group of draenei at the Temple of Telhamat, led by Amaan the Wise. I am certain he'd be interested in meeting you.",logDesc="Speak with Amaan the Wise at the Temple of Telhamat in western Hellfire Peninsula."} end
if not DB[10094] then DB[10094]={id=10094,zoneId=3688,name="The Codex of Blood",level=70,minLevel=68,giver="Field Commander Mahfuun",giverType="NPC",giverId=19542,rewardNextId=10095,poiX=-3598,poiY=4921,wowhead="https://www.wowhead.com/wotlk/quest=10094",image="assets/images/quests/placeholder.png",xpDiff=8,desc="It has been two years since the Shadow Council summoning that resulted in the explosion of this once-great mausoleum, and the formation of the Bone Wastes.$B$BNow they are at war with an unbelievably powerful force on the inside.$B$B$N, you must make your way into the Shadow Labyrinth to determine what they are up against, and to see if it poses a threat to us.  Our spies speak of their use of a forbidden book of unholy summoning, known only as the Codex of Blood.$B$BSeek your answers within its pages.",logDesc="Read from the Codex of Blood in the Shadow Labyrinth of Auchindoun."} end
if not DB[10095] then DB[10095]={id=10095,zoneId=3688,name="Into the Heart of the Labyrinth",level=70,minLevel=68,ender="Spymistress Mehlisah Highcrown",enderType="NPC",enderId=18893,wowhead="https://www.wowhead.com/wotlk/quest=10095",image="assets/images/quests/placeholder.png",xpDiff=8,money=132000,desc="The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago!  It is what caused the explosion of Auchindoun, and the creation of the Bone Wastes beyond.$B$BKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!$B$BWith the grandmaster, and the rest of their leadership dead, you are Outland's last hope against this monstrosity!$B$B$N, you know at the core of your being that you and your companions dare not fail!",logDesc="Destroy Murmur and inform Spymistress Mehlisah Highcrown at the Terrace of Light in Shattrath City of the events that have transpired inside the Shadow Labyrinth.",choiceRewards={{id=28179,qty=1},{id=28178,qty=1},{id=28177,qty=1},{id=28176,qty=1}}} end
if not DB[10096] then DB[10096]={id=10096,zoneId=3521,name="Saving the Sporeloks",level=62,minLevel=60,giver="Lauranna Thar'well",giverType="NPC",giverId=17909,ender="Lauranna Thar'well",enderType="NPC",enderId=17909,poiX=-216,poiY=5437,wowhead="https://www.wowhead.com/wotlk/quest=10096",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Ikeyen's been telling me stories about what happened to him down in those caves and I think it's just awful!$B$BYou know, maybe we should do something to help out those poor sporeloks.  Ikeyen says that they live there in the Funggor Cavern, but that the marsh beasts have recently invaded.$B$BWhy don't you go down there and see if you can clear some of those marsh beasts out?  It's just to the southwest.",logDesc="Slay 10 Marsh Dredgers and 10 Marsh Lurkers, and then return to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh.",choiceRewards={{id=27717,qty=1},{id=31657,qty=1},{id=27715,qty=1},{id=31658,qty=1}}} end
if not DB[10097] then DB[10097]={id=10097,zoneId=3688,name="Brother Against Brother",level=69,minLevel=65,giver="Isfar",giverType="NPC",giverId=18933,ender="Isfar",enderType="NPC",enderId=18933,poiX=-3339,poiY=4704,wowhead="https://www.wowhead.com/wotlk/quest=10097",image="assets/images/quests/placeholder.png",xpDiff=8,money=82000,desc="The Sethekk departed Skettis with great fanfare when Auchindoun exploded. Surely it must've been an omen of our master's arrival.$B$BMy brother, Syth, was one of their leaders and told us we were obligated to go into the temple ruins and face our god.$B$BAfter we took up residence in the ruins, calling them the Sethekk Halls, I began to doubt my brother and his ally, Ikiss.$B$BIn time, Syth had me cast out of the Halls, but he refused to let me take our sister Lakka with me. Will you help me rescue her?",logDesc="Kill Darkweaver Syth in the Sethekk halls, then free Lakka from captivity. Return to Isfar outside the Sethekk Halls when you've completed the rescue.",choiceRewards={{id=29333,qty=1},{id=29334,qty=1},{id=29335,qty=1},{id=29336,qty=1}}} end
if not DB[10098] then DB[10098]={id=10098,zoneId=3688,name="Terokk's Legacy",level=69,minLevel=65,giver="Isfar",giverType="NPC",giverId=18933,ender="Isfar",enderType="NPC",enderId=18933,poiX=-3339,poiY=4704,wowhead="https://www.wowhead.com/wotlk/quest=10098",image="assets/images/quests/placeholder.png",xpDiff=8,money=82000,desc="My people honor an ancient hero named Terokk. Arakkoa hatchlings are regaled with stories of his deeds and descriptions of his beautiful plumage.$B$BHe dwelt among my people for hundreds of years, but mysteriously vanished one day, leaving only his mask, spear, and writings behind.$B$BThe relics are cherished by the arakkoa, but they were heartbroken when the Sethekk bore the objects away from Skettis at their departure.$B$BI have written down what little I know about their location within the halls.",logDesc="Bring Terokk's Mask, Terokk's Quill, and the Saga of Terokk to Isfar outside the Sethekk Halls.",choiceRewards={{id=29330,qty=1},{id=29332,qty=1},{id=29329,qty=1}}} end
if not DB[10099] then DB[10099]={id=10099,zoneId=3483,name="The Mastermind",level=61,minLevel=58,giver="Foreman Biggums",giverType="NPC",giverId=16837,ender="Foreman Biggums",enderType="NPC",enderId=16837,poiX=-673,poiY=2853,wowhead="https://www.wowhead.com/wotlk/quest=10099",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Those infernal gan'arg keep scurrying into the mine! For each one you kill, two or three more seem to take its place!$B$BThere's got to be someone down there in the deepest reaches of the mine directing the incursion. You seemed to do well against them last time, and Light knows you're the only one brave enough to venture back into the mine. Find out who's responsible for this disturbance and make him pay!",logDesc="Locate and kill Z'kral in the mines beneath Honor Hold, then report back to Foreman Biggums.",choiceRewards={{id=25984,qty=1},{id=25982,qty=1},{id=25983,qty=1}}} end
if not DB[10100] then DB[10100]={id=10100,zoneId=3483,name="The Mastermind",level=61,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10100",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Don't get me wrong, $N, I'm glad that you agreed to help with the mines, but for every sapper you killed, I swear two more appeared.$B$BI've been giving Watch Commander Krunk an earful, but he's still refusing to send me any help. He keeps muttering something under his breath about helboars. If I wasn't so sure he'd hit me, I'd tell him this is no time to be thinking about ribs!$B$BAnyway, it looks like there's someone down there deep in the mines directing this whole thing. Find him and kill him!",logDesc="Locate and kill Urga'zz within the mines beneath Thrallmar, then return to Foreman Razelcraz.",choiceRewards={{id=25983,qty=1},{id=25982,qty=1},{id=25984,qty=1}}} end
if not DB[10101] then DB[10101]={id=10101,zoneId=3518,name="When Spirits Speak",level=68,minLevel=66,giver="Mother Kashur",giverType="NPC",giverId=18687,ender="K'ure",enderType="NPC",enderId=17545,rewardNextId=10102,poiX=-2210,poiY=8820,wowhead="https://www.wowhead.com/wotlk/quest=10101",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Oshu'gun - the diamond mountain - was once sacred to my people. It was there that the clans would gather every year to celebrate the springtime festival. It was there that our shaman communed with the honored ancestors. It was the center of our culture - until the shadows overtook us. When the clans became a horde, the spirits of Oshu'gun fell silent. The ancestors turned their backs on us.$B$BYet something now draws them from their rest. Venture to Oshu'gun and discover what could trouble the spirits so.",logDesc="Mother Kashur at the Ancestral Grounds in Nagrand has asked that you seek out the vision you had. Find K'ure in Oshu'gun."} end
if not DB[10102] then DB[10102]={id=10102,zoneId=3518,name="A Secret Revealed",level=68,minLevel=66,giver="K'ure",giverType="NPC",giverId=17545,ender="A'dal",enderType="NPC",enderId=18481,rewardNextId=10167,poiX=-2825,poiY=8336,wowhead="https://www.wowhead.com/wotlk/quest=10102",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As my energies bled away over the centuries, a void slowly grew in my place - devouring the souls of those nearby. Helplessly, I watched as generations of orc souls were drawn into the vortex. Recently, my enemies harnessed the vortex and used it to draw countless void minions into their Burning Legion.$B$BNow, the key to ending this cycle and freeing the orc spirits lies with another naaru - A'dal. I have sensed his essence within the ancient city of Shattrath in the Terokkar Forest.",logDesc="Speak with A'dal in Shattrath City."} end
if not DB[10103] then DB[10103]={id=10103,zoneId=3483,name="Report to Zurai",level=61,minLevel=61,giver="Ranger Captain Venn'ren",giverType="NPC",giverId=16789,ender="Zurai",enderType="NPC",enderId=18011,poiX=-593,poiY=4068,wowhead="https://www.wowhead.com/wotlk/quest=10103",image="assets/images/quests/placeholder.png",xpDiff=2,desc="With the arrival of Field Commander Romus and his forces, the Alliance and their draenei friends have grown bold. They're militarizing every old draenei ruin from here to Shattrath.$B$BIn response, the trolls have established a new outpost in the eastern part of Zangarmarsh, just south of the Dead Mire. Swamprat Post, they're calling it. I'm glad they have a sense of humor about living in a place like that, because I wouldn't relish it.$B$BThe post's commander has asked me to send anyone I can spare.",logDesc="Report to Zurai at Swamprat Post in Zangarmarsh."} end
if not DB[10104] then DB[10104]={id=10104,zoneId=3521,name="Concerns About Tuurem",level=62,minLevel=62,giver="Ikuti",giverType="NPC",giverId=18008,ender="Andarl",enderType="NPC",enderId=18252,poiX=1024,poiY=7366,wowhead="https://www.wowhead.com/wotlk/quest=10104",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The rumors from Tuurem are unsettling. Some say the town's ruins are overrun with crazed Broken and Lost Ones, while opportunistic artifact hunters steal draenei relics.$B$BIt's hard to know which are true and which aren't, but we have a responsibility to safeguard the ruins as best we can. Find Andarl at the Allerian Stronghold in Terokkar Forest. He is something of a student of magical relics. More than anyone else, he's likely to know what's going on there.",logDesc="Speak with Andarl at the Allerian Stronghold in Terokkar Forest."} end
if not DB[10105] then DB[10105]={id=10105,zoneId=3521,name="News for Rakoria",level=62,minLevel=62,giver="Shadow Hunter Denjai",giverType="NPC",giverId=18013,ender="Rakoria",enderType="NPC",enderId=18385,poiX=230,poiY=7930,wowhead="https://www.wowhead.com/wotlk/quest=10105",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Now that Swamprat Post is complete, our control of the roads in and out of the marsh is much less tenuous. Our presence in Terokkar Forest is much less secure. Even so, at Stonebreaker Hold, Rakoria awaits word of our progress.$B$BShe's sharp and capable, $N, but be careful around her. She's got a lot of goods she's eager to move along the roads, but don't assume she's got our best interests at heart. Rakoria goes where she believes there's profit to be found.",logDesc="Speak with Rakoria at Stonebreaker Hold in Terokkar Forest."} end
if not DB[10106] then DB[10106]={id=10106,zoneId=3483,name="Hellfire Fortifications",level=60,minLevel=55,giver="Warrant Officer Tracy Proudwell",giverType="NPC",giverId=18266,ender="Warrant Officer Tracy Proudwell",enderType="NPC",enderId=18266,poiX=-683,poiY=2630,wowhead="https://www.wowhead.com/wotlk/quest=10106",image="assets/images/quests/placeholder.png",xpDiff=4,money=7000,desc="The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.$B$BOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.$B$BMay fortune shine upon you in the conflicts ahead, $N, for you will no doubt clash with Horde forces eager to gain these same fortifications.",logDesc="Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.",rewards={{id=24579,qty=3}}} end
if not DB[10107] then DB[10107]={id=10107,zoneId=3518,name="Diplomatic Measures",level=66,minLevel=64,giver="Jorin Deadeye",giverType="NPC",giverId=18106,ender="Lantresor of the Blade",enderType="NPC",enderId=18261,poiX=-1344,poiY=7226,wowhead="https://www.wowhead.com/wotlk/quest=10107",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Kilrath sends news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the southeast near the border of Terokkar. Good luck, $N!$B$BBe warned, he is a blademaster...",logDesc="Jorin Deadeye at Garadar in Nagrand has asked that you find and speak with Lantresor of the Blade in the Burning Blade Ruins."} end
if not DB[10108] then DB[10108]={id=10108,zoneId=3518,name="Diplomatic Measures",level=66,minLevel=64,giver="Mo'mor the Breaker",giverType="NPC",giverId=18223,ender="Lantresor of the Blade",enderType="NPC",enderId=18261,poiX=-2618,poiY=7278,wowhead="https://www.wowhead.com/wotlk/quest=10108",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The huntress's agents send news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the east. Good luck, $N!$B$BBe warned, he is a blademaster...",logDesc="Mo'mor the Breaker at Telaar in Nagrand has asked that you find and speak with Lantresor of the Blade in the Burning Blade Ruins."} end
if not DB[10109] then DB[10109]={id=10109,zoneId=3518,name="I Must Have Them!",level=66,minLevel=64,giver="Wazat",giverType="NPC",giverId=19035,ender="Wazat",enderType="NPC",enderId=19035,rewardNextId=10111,poiX=-2428,poiY=6886,wowhead="https://www.wowhead.com/wotlk/quest=10109",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="Do you see them?? By Gazlowe's horrific halitosis, I will have those eggs! Say, you look like you might be of some use.$B$BI'll tell you what, $r; if you gather a few items for me to make my Jump-a-tron 4000 functional, I'll give you a key that will let you operate the machine as well! What can you do with a Jump-a-tron 4000 you say? What can't you do is more like it...$B$BI'll need air elemental gas from the air elementals of Nagrand. They're all over the place so don't ask me where to find 'em!",logDesc="Wazat across from Clan Watch in southern Nagrand wants you to bring him 3 Air Elemental Gases.",rewards={{id=27808,qty=1}}} end
if not DB[10110] then DB[10110]={id=10110,zoneId=3483,name="Hellfire Fortifications",level=60,minLevel=55,giver="Battlecryer Blackeye",giverType="NPC",giverId=18267,ender="Battlecryer Blackeye",enderType="NPC",enderId=18267,poiX=131,poiY=2650,wowhead="https://www.wowhead.com/wotlk/quest=10110",image="assets/images/quests/placeholder.png",xpDiff=4,money=7000,desc="The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.$B$BOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!$B$BWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.$B$BFor the Horde!",logDesc="Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.",rewards={{id=24581,qty=3}}} end
if not DB[10111] then DB[10111]={id=10111,zoneId=3518,name="Bring Me The Egg!",level=66,minLevel=64,giver="Wazat",giverType="NPC",giverId=19035,ender="Wazat",enderType="NPC",enderId=19035,poiX=-2428,poiY=6886,wowhead="https://www.wowhead.com/wotlk/quest=10111",image="assets/images/quests/placeholder.png",xpDiff=6,money=70000,desc="Now that you've been initiated, I want you to get me that egg! Use the Jump-a-tron and try to hit the nest dead center. But be careful! Bodily injury or serious permanent damage may occur from a bad jump.",logDesc="Wazat in Nagrand wants you to use the Jump-a-tron 4000 to get to the nest in the nearby tree and steal the Mysterious Egg.",choiceRewards={{id=28030,qty=1},{id=28032,qty=1},{id=28031,qty=1}}} end
if not DB[10112] then DB[10112]={id=10112,zoneId=3519,name="A Personal Favor",level=64,minLevel=62,giver="Wind Trader Lathrai",giverType="NPC",giverId=18484,ender="Wind Trader Lathrai",enderType="NPC",enderId=18484,rewardNextId=9990,poiX=-1742,poiY=5192,wowhead="https://www.wowhead.com/wotlk/quest=10112",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Hmmm?  A box you say?  Or was it several?  Do you know what material the box was constructed from?$B$BAnd what was the name of this merchant?  Empoor?  Are you certain that he's one of the Broken?  I don't do much business with their kind.$B$BPerhaps my memory would be jogged if you were to do me a favor?$B$BThe Skithian arakkoa - primitive casters that they are - recently stole a huge shipment of my more exotic goods.  I want it all back!$B$BYou can find Veil Skith just to the south of Shattrath City.",logDesc="Retrieve 5 of Lathrai's Stolen Goods.  Return them to Wind Trader Lathrai near the World's End Tavern in the Lower City section of Shattrath City.",choiceRewards={{id=25927,qty=1},{id=25926,qty=1},{id=25928,qty=1},{id=31724,qty=1}}} end
if not DB[10113] then DB[10113]={id=10113,zoneId=3518,name="The Nesingwary Safari",level=65,minLevel=64,giver="\"Shotgun\" Jones",giverType="NPC",giverId=19137,ender="Hemet Nesingwary",enderType="NPC",enderId=18180,poiX=-2551,poiY=7257,wowhead="https://www.wowhead.com/wotlk/quest=10113",image="assets/images/quests/placeholder.png",xpDiff=1,desc="\"Go out and find us some supplies,\" he said. I was nearly killed about 15 times before I found this place! These Broken might not be the most hospitable bunch but at least they're not trying to tear my skin from my bones.$B$BAnyway, I'm not going back. My days of huntin' big game are over. If you end up heading northeast towards Zangarmarsh and run into the Nesingwary Safari, let them know that \"Shotgun\" quit. $B$BHey, maybe you can take my place! Good luck, stranger.$B",logDesc="\"Shotgun\" Jones wants you to speak with Hemet Nesingwary at the Nesingwary Safari on the outskirts of northeast Nagrand.$B"} end
if not DB[10114] then DB[10114]={id=10114,zoneId=3518,name="The Nesingwary Safari",level=65,minLevel=64,giver="Ohlorn Farstrider",giverType="NPC",giverId=19133,ender="Shado 'Fitz' Farstrider",enderType="NPC",enderId=18200,poiX=-1333,poiY=7234,wowhead="https://www.wowhead.com/wotlk/quest=10114",image="assets/images/quests/placeholder.png",xpDiff=1,desc="These orcs have never seen a tauren before - if you can believe such a thing. If it weren't for Captain Kroghan, they would have probably been serving me for their next meal right about now.$B$BBut where are my manners? I am Ohlorn Farstrider, hunter extraordinaire! I am part of the Nesingwary expedition that came up here from Azeroth in search of big game. If you are interested in the hunt, perhaps you should visit my crew at the Nesingwary Safari, due east of here near the border of Zangarmarsh.$B",logDesc="Ohlorn Farstrider wants you to speak with Shado 'Fitz' Farstrider at the Nesingwary Safari in Nagrand."} end
if not DB[10115] then DB[10115]={id=10115,zoneId=3521,name="Daggerfen Deviance",level=64,minLevel=62,giver="Ikuti",giverType="NPC",giverId=18008,ender="Ikuti",enderType="NPC",enderId=18008,poiX=1024,poiY=7366,wowhead="https://www.wowhead.com/wotlk/quest=10115",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="The Kurenai and the draenei don't always see eye to eye, particularly on the issue of the Lost Ones. We are content to help the Lost Ones who seek us out, but we won't pursue them. Some draenei are intent on 'redeeming' them all.$B$BHowever, there are times when even the Lost Ones go too far, such as the Daggerfen. In their village to the west, they dabble in poisons and deceit, arts that come unnaturally to us.$B$BWe must put an end to this before the vile Daggerfen can extend their influence.",logDesc="Slay 3 Daggerfen Assassins and 15 Daggerfen Muckdwellers."} end
if not DB[10116] then DB[10116]={id=10116,zoneId=3521,name="Wanted: Chieftain Mummaki",level=64,minLevel=58,ender="Ikuti",enderType="NPC",enderId=18008,wowhead="https://www.wowhead.com/wotlk/quest=10116",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against the Orebor Harborage.$B$BThe chieftain and his band of assassins are responsible for the deaths of numerous Kurenai and draenei and should only be approached by seasoned combatants.$B$BTravelers are advised to avoid the Daggerfen Village area to the west of the Orebor Harborage.$B$BTo claim the bounty, present proof of the chietain's demise to Ikuti.",logDesc="Bring Chieftain Mummaki's Totem to Ikuti at the Orebor Harborage."} end
if not DB[10117] then DB[10117]={id=10117,zoneId=3521,name="Wanted: Chieftain Mummaki",level=64,minLevel=58,ender="Shadow Hunter Denjai",enderType="NPC",enderId=18013,wowhead="https://www.wowhead.com/wotlk/quest=10117",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against Zabra'jin and its inhabitants.$B$BThe chieftain and his band of assassins are responsible for the deaths of numerous scouts and messengers and should only be approached by seasoned combatants.$B$BTravelers are advised to avoid the Daggerfen Village area to the northwest of Zabra'jin.$B$BTo claim the bounty, present proof of the chietain's demise to Shadow Hunter Denjai.",logDesc="Bring Chieftain Mummaki's Totem to Shadow Hunter Denjai."} end
if not DB[10118] then DB[10118]={id=10118,zoneId=3521,name="Message to the Daggerfen",level=64,minLevel=62,giver="Shadow Hunter Denjai",giverType="NPC",giverId=18013,ender="Shadow Hunter Denjai",enderType="NPC",enderId=18013,poiX=230,poiY=7930,wowhead="https://www.wowhead.com/wotlk/quest=10118",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Of all the Lost One tribes in Zangarmarsh, the Daggerfen are the most cunning and most aggressive. They are highly organized and make no secret of the fact that they desire control over the other Lost Ones in the marsh.$B$BTheir attacks have already taken quite a toll on my scouts and messengers. I cannot afford to lose any more men.$B$BIf we don't act soon, they'll have complete control over the roads and Zabra'jin will effectively be surrounded.",logDesc="Slay 3 Daggerfen Assassins and 15 Daggerfen Muckdwellers and return to Shadow Hunter Denjai at Zabra'jin."} end
if not DB[10119] then DB[10119]={id=10119,zoneId=3483,name="Through the Dark Portal",level=61,minLevel=58,giver="Watch Commander Relthorn Netherwane",giverType="NPC",giverId=16841,ender="Commander Duron",enderType="NPC",enderId=19229,rewardNextId=10288,poiX=-11815,poiY=-3196,wowhead="https://www.wowhead.com/wotlk/quest=10119",image="assets/images/quests/placeholder.png",xpDiff=2,desc="For 20 years the Dark Portal has remained a silent monument - a eulogy to a time long since forgotten.$B$B<Relthorn looks around.>$B$BI never thought to see this day, yet here we stand, looking into the abyss.$B$BOn the other side of this gate we are locked in a savage war - a war that we cannot win without support. You must go through the Dark Portal and help our troops, $c.$B$BReport to Commander Duron at once. He awaits you in Outland...",logDesc="Travel through the Dark Portal and find Commander Duron. He awaits your arrival on the other side - in the Outland.$B"} end
if not DB[10120] then DB[10120]={id=10120,zoneId=3483,name="Arrival in Outland",level=61,minLevel=58,giver="Lieutenant General Orion",giverType="NPC",giverId=19253,ender="Vlagga Freyfeather",enderType="NPC",enderId=18930,rewardNextId=10289,poiX=-233,poiY=1028,wowhead="https://www.wowhead.com/wotlk/quest=10120",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Aided by the Alliance, my forces will hold the line here, but I need you to deliver my report to General Krakork in Thrallmar. With his help, we'll be able to drive these demons back into the abyss that spawned them! Speak to Vlagga Freyfeather who stands on the platform behind us. She'll speed you on your way.",logDesc="Lieutenant General Orion at the Dark Portal in Hellfire Peninsula wants you to bring Orion's Report to Vlagga Freyfeather."} end
if not DB[10121] then DB[10121]={id=10121,zoneId=3483,name="Eradicate the Burning Legion",level=61,minLevel=58,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Sergeant Shatterskull",enderType="NPC",enderId=19256,rewardNextId=10123,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=10121",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Though this land is full of strange new enemies, the Burning Legion is still the greatest threat to our Expedition. One of my most trusted warriors, Sergeant Shatterskull, has been studying the Legion's tactics - trying to discern the demons' true purpose in this land. Seek him out at the supply caravan just outside the southern wall.$B$BAnd $n - be wary of the Legion. Their evil cannot be underestimated.",logDesc="Speak with Sergeant Shatterskull at the Supply Caravan just outside of Thrallmar, to the east."} end
if not DB[10122] then DB[10122]={id=10122,zoneId=3483,name="The Citadel's Reach",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10122",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.$B$BI dispatched one of my most capable scouts, Private Imarion, to track their movements, preparations and numbers, but he hasn't returned to report his findings.$B$BImarion was to focus his efforts on the northernmost camp along the Southern Rampart, near where it joined the Citadel. Find him, $N. Without his information, we're sitting ducks.",logDesc="Search the northernmost camp along the Southern Rampart for any trace of Private Imarion."} end
if not DB[10123] then DB[10123]={id=10123,zoneId=3483,name="Felspark Ravine",level=61,minLevel=58,giver="Sergeant Shatterskull",giverType="NPC",giverId=19256,ender="Sergeant Shatterskull",enderType="NPC",enderId=19256,rewardNextId=10124,poiX=60,poiY=2537,wowhead="https://www.wowhead.com/wotlk/quest=10123",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.$B$BThey have stationed dreadlords in Felspark Ravine, east of here. They are responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.",logDesc="Sergeant Shatterskull at the Supply Caravan east of Thrallmar in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.",choiceRewards={{id=29908,qty=1},{id=29909,qty=1},{id=29910,qty=1},{id=29911,qty=1},{id=29913,qty=1}}} end
if not DB[10124] then DB[10124]={id=10124,zoneId=3483,name="Forward Base: Reaver's Fall",level=61,minLevel=58,giver="Sergeant Shatterskull",giverType="NPC",giverId=19256,ender="Forward Commander To'arch",enderType="NPC",enderId=19273,rewardNextId=10208,poiX=60,poiY=2537,wowhead="https://www.wowhead.com/wotlk/quest=10124",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Your battle prowess has been noted by high command, $c. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...$B$BHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Foward Commander To'arch.$B$BNow move out!",logDesc="Report to Forward Commander To'arch at Reaver's Fall."} end
if not DB[10125] then DB[10125]={id=10125,zoneId=3483,name="Mission: Disrupt Communications",level=62,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10125",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Directly east of here is the Legion Front. The front acts as a mobile command station for the Burning Legion. Jutting out of the ground you'll see Legion antennas. The Legion uses these to communicate with their forge camps throughout Outland. They also serve as wards to scramble Legion transmissions, making magical surveillance impossible.$B$BI want you to take these explosives and use them to obliterate the antennas. Get all of them, $N. They run south to north on the border of the Legion Front.",logDesc="Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you use To'arch's Explosives and destroy Legion Antenna: Spite, Legion Antenna: Rage, Legion Antenna: Hate, Legion Antenna: Fear."} end
if not DB[10126] then DB[10126]={id=10126,zoneId=3483,name="Warboss Nekrogg's Orders",level=61,minLevel=58,rewardNextId=10128,wowhead="https://www.wowhead.com/wotlk/quest=10126",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their human prisoner south for interrogation.$B$BLieutenant Amadi mentioned that the Southern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Private Imarion.$B$BJudging by the note's mention of interrogation, it seems the private's fel orc captors see some value in keeping him alive. Pick up the trail before they decide to change their minds.",logDesc="Travel south along the west side of the South Rampart and search the next camp for signs of Private Imarion."} end
if not DB[10127] then DB[10127]={id=10127,zoneId=3483,name="Mission: Sever the Tie",level=62,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10127",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It would be a dereliction of duty if I did not order you to take out the demons that inhabit the Legion Front, just east of this base.$B$BBoth sides of the front are set up in the same manner: Fel handlers roam between Legion encampments, which are in turn guarded by wrathguards. A shivan subjugator oversees the entire operation. Kill 'em all and let Kazzak sort 'em out.$B$BAnd watch out for patrolling fel reavers. I know you're tough but those things will make short work of you.",logDesc="Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula wants you to kill 4 Fel Handlers, 8 Wrathguards, and Subjugator Shi'aziv."} end
if not DB[10128] then DB[10128]={id=10128,zoneId=3483,name="Saving Private Imarion",level=61,minLevel=58,rewardNextId=10131,wowhead="https://www.wowhead.com/wotlk/quest=10128",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The tracks lead south from Imarion's equipment, appearing to follow the Southern Rampart. The roughness of the shallow ruts suggests that Imarion's captors were in a hurry to move him to his next destination, but why?$B$BWas someone waiting there for him, perhaps the Warboss Nekrogg, the leader named in the orders you found further north?$B$BThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Private Imarion, you're likely to find Warboss Nekrogg too.",logDesc="Continue south along the Southern Rampart and search for where Warboss Nekrogg is holding Private Imarion."} end
if not DB[10129] then DB[10129]={id=10129,zoneId=3483,name="Mission: Gateways Murketh and Shaadraz",level=62,minLevel=58,giver="Forward Commander To'arch",giverType="NPC",giverId=19273,ender="Forward Commander To'arch",enderType="NPC",enderId=19273,rewardNextId=10162,poiX=-20,poiY=2137,wowhead="https://www.wowhead.com/wotlk/quest=10129",image="assets/images/quests/placeholder.png",xpDiff=6,desc="We've identified the two main transporters that the Burning Legion are using to bring in reinforcements: Gateway Murketh and Gateway Shaadraz.$B$BIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into oblivion!$B$BHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Brack -- he'll put you on a wyvern.",logDesc="Speak with Wing Commander Brack, bomb Gateway Murketh and Gateway Shaadraz and then return to Forward Commander To'arch at Reaver's Fall.",choiceRewards={{id=29942,qty=1},{id=29937,qty=1},{id=29929,qty=1},{id=29944,qty=1}}} end
if not DB[10130] then DB[10130]={id=10130,zoneId=3483,name="The Western Flank",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10130",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.$B$BAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Honor Hold.$B$BWith the hold's garrison concentrating on its eastern walls, an attack from the west would be devastating. Honor Hold can only hope to hold out if the western forces are kept out of the battle.",logDesc="Kill 10 Shattered Hand Guards, 10 Shattered Hand Berserkers, and 5 Shattered Hand Acolytes, then report to Lieutenant Amadi at Honor Hold's western guard tower."} end
if not DB[10131] then DB[10131]={id=10131,zoneId=3483,name="Planning the Escape",level=61,minLevel=58,rewardNextId=10137,wowhead="https://www.wowhead.com/wotlk/quest=10131",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Like I said, getting out of here won't be easy. Warboss Nekrogg may look like an overgrown brute, but he's no simpleton.$B$BHe won't let the cage key out of his sight and doesn't come down from his tower atop that chunk of wall until he's ready to question me or that orc he's managed to capture.$B$BIt's going to take something extraordinary to get him off that wall, but I have an idea. Find one of the grenadiers that patrol the ground along the Southern Rampart and bring me some of his explosives.",logDesc="Kill a Shattered Hand Grenadier and bring his Crude Explosives to Private Imarion at Gor'gaz Outpost."} end
if not DB[10132] then DB[10132]={id=10132,zoneId=3483,name="Colossal Menace",level=63,minLevel=61,giver="Tola'thion",giverType="NPC",giverId=19293,ender="Tola'thion",enderType="NPC",enderId=19293,poiX=-311,poiY=4733,wowhead="https://www.wowhead.com/wotlk/quest=10132",image="assets/images/quests/placeholder.png",xpDiff=6,money=58000,desc="You see that huge red crystal to the north?  It fell from the sky not long ago, causing a massive earthquake.$B$BWhen we came out here to investigate the disturbance, we found all of these colossi wandering about that weren't previously here.$B$BThere's definitely something strange about that crystal and the energies that it's emanating, but I don't have time for that.  Those mountain giants are my immediate concern.$B$BI want you to head up to Fallen Sky Ridge with some friends and deal with them.",logDesc="Slay 5 Raging Colossi and then return to Tola'thion at the Cenarion Post in Hellfire Peninsula.",choiceRewards={{id=28064,qty=1},{id=28062,qty=1},{id=28065,qty=1},{id=28066,qty=1},{id=28063,qty=1}}} end
if not DB[10133] then DB[10133]={id=10133,zoneId=3483,name="Mission: Kill the Messenger",level=62,minLevel=255,rewardNextId=10135,wowhead="https://www.wowhead.com/wotlk/quest=10133",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Your handiwork is already causing the Legion great discomfort, $N. My scouts have just informed me that the Legion has resorted to sending communication via courier. We have successfully managed to cut their troops off from the host!$B$BWhat I ask of you next is more than I would ask of an ordinary soldier.$B$BThe Legion courier travels from the Pools of Aggonar to Forge Base: Mageddon, north of here. You must intercept the courier at Mageddon, dispose of him, and return to me with the Legion missive.",logDesc="Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you find and slay Arix'malidash and recover the Legion Missive."} end
if not DB[10134] then DB[10134]={id=10134,zoneId=3483,name="Crimson Crystal Clue",level=63,minLevel=61,ender="Tola'thion",enderType="NPC",enderId=19293,rewardNextId=10349,wowhead="https://www.wowhead.com/wotlk/quest=10134",image="assets/images/quests/placeholder.png",xpDiff=3,money=15000,desc="As the colossus falls under the weight of your attacks, you notice for the first time that it was holding a red crystal fragment.$B$BWhile it was small and unnoticeable in the mountain giant's hand, it's a fairly hefty piece for you to carry around.  It also suspiciously looks like it's a piece of the giant crystal in the middle of the ridge.$B$BIt's most definitely a clue as to the strangeness that is occurring here, and you're sure that the druids at the Cenarion Post to the south will want to see it.",logDesc="Deliver the Crimson Crystal Shard to Tola'thion at the Cenarion Post in Hellfire Peninsula."} end
if not DB[10135] then DB[10135]={id=10135,zoneId=3483,name="Mission: Be the Messenger",level=62,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10135",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I am merely a field commander, $c. The authority to act on this kind of information falls squarely on the shoulders of our leader, Nazgrel. You must take this missive to him in Thrallmar. Ride with the wind at your back, soldier. Let nothing prevent you from reaching Nazgrel!",logDesc="Take the Legion Missive to Nazgrel at Thrallmar in Hellfire Peninsula."} end
if not DB[10136] then DB[10136]={id=10136,zoneId=3483,name="Cruel's Intentions",level=63,minLevel=58,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Nazgrel",enderType="NPC",enderId=3230,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=10136",image="assets/images/quests/placeholder.png",xpDiff=7,money=87000,desc="Magister Bloodhawk finally deciphered the Legion missive you found earlier. It turned out to be attack plans sent by one of Highlord Kazzak's lieutenants - Arazzius the Cruel. Apparently, Arazzius commands the Legion ground forces in Hellfire. The time has come to terminate his command, $N. Terminate with extreme prejudice. $B$BHead west to the Pools of Aggonar and put an end to this so-called 'Legion lord'. Today, the Horde reclaims Hellfire Peninsula. Let the Legion be damned. ",logDesc="Kill Arazzius the Cruel, then return to Nazgrel in Thrallmar.",choiceRewards={{id=28040,qty=1},{id=28041,qty=1},{id=28042,qty=1}}} end
if not DB[10137] then DB[10137]={id=10137,zoneId=3483,name="Provoking the Warboss",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10137",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The plan succeeds or fails on how well these explosives are made...$B$BAs much as I'd hate to rely on anything made by an orc, it's my only real chance to get out of here. Take this and throw it against the banner hanging from the tower up there.$B$BOnce it explodes, Warboss Nekrogg won't be able to resist the chance to make an example of the troublemaker. Kill him, take the key, and then open my cage. Good luck, $N.",logDesc="Use the Crude Explosives to create a disturbance and lure Warboss Nekrogg out of his tower. Kill him, obtain Nekrogg's Key, and use it to open Private Imarion's cage. Once you have freed Private Imarion, report to Lieutenant Amadi.",choiceRewards={{id=25991,qty=1},{id=25990,qty=1},{id=25988,qty=1}}} end
if not DB[10138] then DB[10138]={id=10138,zoneId=3483,name="Under Whose Orders?",level=61,minLevel=58,rewardNextId=10139,wowhead="https://www.wowhead.com/wotlk/quest=10138",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="One thing is clear, $N: we can't keep this up. The fel orcs have us surrounded and as quickly as we can kill them, several spring up to replace them. We can't hope to win this war huddled behind Honor Hold's shattered walls and counting the days until our deaths at the hands of the fel orcs or the Legion.$B$BYou've done a remarkable job of sparing us from the brunt of the fel orc attack, but now you must fight your way up the Path of Glory and learn who is orchestrating these attacks.",logDesc="Kill 20 Shattered Hand Grunts, 10 Shattered Hand Warlocks, and capture Drillmaster Zurok's Orders. Then, return to Lieutenant Amadi at Honor Hold's western guard tower."} end
if not DB[10139] then DB[10139]={id=10139,zoneId=3483,name="Dispatching the Commander",level=62,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=10139",image="assets/images/quests/placeholder.png",xpDiff=6,money=54000,desc="From what I can tell, Drillmaster Zurok served as the right hand of the fel orc leader in Hellfire Peninsula, Force-Commander Gorax.$B$BThis Gorax isn't your typical fel orc brute, though. I almost admire the way he managed to keep us on the defensive for so long.$B$BZurok's orders indicate that Gorax's command center is located at the end of the Path of Glory, near where the citadel's walls meet the Northern Rampart. There's no telling what to expect, $N, but it would be wise to travel with allies.",logDesc="Slay Force-Commander Gorax and report to Lieutenant Amadi at Honor Hold's western tower.",choiceRewards={{id=28051,qty=1},{id=28057,qty=1},{id=28050,qty=1},{id=28055,qty=1},{id=28052,qty=1},{id=28054,qty=1}}} end
if not DB[10140] then DB[10140]={id=10140,zoneId=3483,name="Journey to Honor Hold",level=61,minLevel=58,giver="Amish Wildhammer",giverType="NPC",giverId=18931,ender="Marshal Isildor",enderType="NPC",enderId=19308,rewardNextId=10254,poiX=-324,poiY=1028,wowhead="https://www.wowhead.com/wotlk/quest=10140",image="assets/images/quests/placeholder.png",xpDiff=2,desc="When you're ready, I'll arrange a flight straight to Honor Hold.$B$BFrom there, speak with Marshal Isildor and give him Duron's report.  He'll be happy to see another recruit from the homelands, and I'm sure the information in that report is important stuff!",logDesc="Take a flight to Honor Hold and deliver Duron's Report to Marshal Isildor."} end
if not DB[10141] then DB[10141]={id=10141,zoneId=3483,name="The Legion Reborn",level=61,minLevel=58,giver="Force Commander Danath Trollbane",giverType="NPC",giverId=16819,ender="Sergeant Altumus",enderType="NPC",enderId=19309,rewardNextId=10142,poiX=-816,poiY=2614,wowhead="https://www.wowhead.com/wotlk/quest=10141",image="assets/images/quests/placeholder.png",xpDiff=1,desc="While the Burning Legion invaded Azeroth, they were also at work here, in Outland.  We have tracked their movements over the years, but this latest activity, $c - well, this is beyond anything we've seen.$B$BSeek out Sergeant Altumus near the eastern supply caravan. She has been monitoring the invaders and may have insights into their purpose.$B$BBe swift - and take care, $n - the Burning Legion is not to be underestimated.",logDesc="Speak with Sergeant Altumus at the East Supply Caravan just outside of Honor Hold, to the east."} end
if not DB[10142] then DB[10142]={id=10142,zoneId=3483,name="The Path of Anguish",level=61,minLevel=58,giver="Sergeant Altumus",giverType="NPC",giverId=19309,ender="Sergeant Altumus",enderType="NPC",enderId=19309,rewardNextId=10143,poiX=-617,poiY=2353,wowhead="https://www.wowhead.com/wotlk/quest=10142",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.$B$BThey have stationed dreadlords at the Path of Anguish, east of here. They are the ones responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.",logDesc="Sergeant Altumus at the East Supply Caravan east of Honor Hold in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.",choiceRewards={{id=29908,qty=1},{id=29909,qty=1},{id=29910,qty=1},{id=29911,qty=1},{id=29913,qty=1}}} end
if not DB[10143] then DB[10143]={id=10143,zoneId=3483,name="Expedition Point",level=61,minLevel=58,giver="Sergeant Altumus",giverType="NPC",giverId=19309,ender="Forward Commander Kingston",enderType="NPC",enderId=19310,rewardNextId=10144,poiX=-617,poiY=2353,wowhead="https://www.wowhead.com/wotlk/quest=10143",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Your battle prowess has been noted by high command, $c. They want to send you to the front lines to meet up with Rohamus's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...$B$BHead east about 400 paces, across the Valley of Bones, until you run into a destroyed fel reaver. You'll see Expedition Point where a Legion base used to stand. Once there, you are to report to Forward Commander Kingston.$B$BNow move out!",logDesc="Report to Forward Commander Kingston at Expedition Point."} end
if not DB[10144] then DB[10144]={id=10144,zoneId=3483,name="Disrupt Their Reinforcements",level=62,minLevel=58,giver="Forward Commander Kingston",giverType="NPC",giverId=19310,ender="Forward Commander Kingston",enderType="NPC",enderId=19310,poiX=-680,poiY=1855,wowhead="https://www.wowhead.com/wotlk/quest=10144",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You'll find the Legion front to our northeast, and spaced along it are portals used to gather reinforcements from throughout Outland. We, $n, are going to destroy those portals!$B$BTake this primer.  Designed in Area 52, it uses the demons' own power as an explosive device!  Defeat Legion forces around Portals Grimh and Kaalez to gather demonic rune stones, use the primer to detonate the stones inside the portals... then watch the fireworks!!$B$BGo, $n, and return to me when your mission is complete.",logDesc="Defeat enemies around Portal Grimh and Portal Kaalez to gather Demonic Rune Stones.$B$BUse Kingston's Primer inside Portal Grimh and Portal Kaalez.$B$BReturn to Forward Commander Kingston with the remaining explosives.",choiceRewards={{id=29927,qty=1},{id=29939,qty=1},{id=29932,qty=1},{id=29946,qty=1},{id=29935,qty=1}}} end
if not DB[10145] then DB[10145]={id=10145,zoneId=3483,name="Mission: Sever the Tie UNUSED",level=62,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10145",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It would be a dereliction of duty if I did not order you to take out the demons that inhabit the Legion Front, just north of this base.$B$BBoth sides of the front are set up in the same manner: Fel handlers roam between Legion encampments, which are in turn guarded by wrathguards. A shivan subjugator oversees the entire operation. Kill 'em all and let Kazzak sort 'em out.$B$BAnd watch out for patrolling fel reavers. I know you're tough but those things will make short work of you.",logDesc="Forward Commander Kingston at Expedition Point in Hellfire Peninsula wants you to kill 4 Fel Handlers, 8 Wrathguards, and Subjugator Yalqiz."} end
if not DB[10146] then DB[10146]={id=10146,zoneId=3483,name="Mission: The Murketh and Shaadraz Gateways",level=62,minLevel=58,giver="Forward Commander Kingston",giverType="NPC",giverId=19310,ender="Forward Commander Kingston",enderType="NPC",enderId=19310,rewardNextId=10340,poiX=-680,poiY=1855,wowhead="https://www.wowhead.com/wotlk/quest=10146",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Just west of the Dark Portal are two huge transporters: Gateway Murketh and Gateway Shaadraz.$B$BIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into rubble!$B$BHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Dabir'ee -- he'll put you on a gryphon and send you on your way.",logDesc="Speak with Wing Commander Dabir'ee, bomb Gateway Murketh and Gateway Shaadraz and then return to Forward Commander Kingston at Expedition Point.",choiceRewards={{id=29942,qty=1},{id=29937,qty=1},{id=29929,qty=1},{id=29944,qty=1}}} end
if not DB[10147] then DB[10147]={id=10147,zoneId=3483,name="Mission: Kill the Messenger",level=62,minLevel=255,rewardNextId=10148,wowhead="https://www.wowhead.com/wotlk/quest=10147",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Your handiwork is already causing the Legion great discomfort, $N. My scouts have just informed me that the Legion has resorted to sending communication via courier. We have successfully managed to cut their troops off from the host!$B$BWhat I ask of you next is more than I would ask of an ordinary soldier.$B$BThe Legion courier travels from the Pools of Aggonar to Forge Base: Mageddon, far north of here. You must intercept the courier at Mageddon, dispose of him, and return to me with the Legion missive.",logDesc="Forward Commander Kingston at Expedition Point in Hellfire Peninsula has asked that you find and slay Arix'malidash and recover the Legion Missive."} end
if not DB[10148] then DB[10148]={id=10148,zoneId=3483,name="Mission: Be the Messenger",level=62,minLevel=255,rewardNextId=10149,wowhead="https://www.wowhead.com/wotlk/quest=10148",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I am merely a field commander, $c. The authority to act on this kind of information falls squarely on the shoulders of our leader, Force Commander Danath Trollbane. You must take this missive to him in Honor Hold. Ride with the wind at your back, soldier. Let nothing prevent you from reaching Danath!",logDesc="Take the Legion Missive to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula."} end
if not DB[10149] then DB[10149]={id=10149,zoneId=3483,name="Mission: End All, Be All",level=63,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10149",image="assets/images/quests/placeholder.png",xpDiff=7,money=87000,desc="Do you know what would have happened if you had not intercepted this missive, $N?$B$B<Danath nods.>$B$BThe entirety of the Legion army in Hellfire would have been knocking on our door. There is no way that we could have survived such an assault.$B$BThere is only one way to make sure that these orders never reach the Legion Front. You must travel to the Pools of Aggonar, far northwest of here, and slay this Arazzius creature.$B$BDo this and I will grant you a commendation.",logDesc="Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula has asked that you slay Arazzius the Cruel.$B",choiceRewards={{id=28040,qty=1},{id=28041,qty=1},{id=28042,qty=1}}} end
if not DB[10150] then DB[10150]={id=10150,zoneId=3483,name="The Citadel's Reach",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10150",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.$B$BI dispatched one of my most capable trackers, Scout Makha, to track their movements, preparations and numbers, but she hasn't returned to report her findings.$B$BMakha was to focus her efforts on the northernmost camp along the Northern Rampart, near where it ends in the rocks. Find her, $N. Without her information, we're sitting ducks.",logDesc="Search the northernmost camp along the Northern Rampart for any trace of Scout Makha."} end
if not DB[10151] then DB[10151]={id=10151,zoneId=3483,name="Warboss Nekrogg's Orders",level=61,minLevel=58,rewardNextId=10153,wowhead="https://www.wowhead.com/wotlk/quest=10151",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their orcish prisoner south for interrogation.$B$BShadow Hunter Ty'jin mentioned that the Northern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Scout Makha.$B$BJudging by the note's mention of interrogation, it seems the scout's fel orc captors see some value in keeping her alive. Pick up the trail before they decide to change their minds.",logDesc="Travel south along the west side of the Northern Rampart and search the next camp for signs of Scout Makha"} end
if not DB[10152] then DB[10152]={id=10152,zoneId=3483,name="The Western Flank",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10152",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.$B$BAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Thrallmar.$B$BWith the town's garrison concentrating on its eastern walls, an attack from the west would be devastating. Thrallmar can only hope to hold out if the western forces are kept out of the battle.",logDesc="Kill 10 Shattered Hand Guards, 10 Shattered Hand Berserkers, and 5 Shattered Hand Acolytes, then report to Stone Guard Ambelan at Spinebreaker Post near Zeth'Gor."} end
if not DB[10153] then DB[10153]={id=10153,zoneId=3483,name="Saving Scout Makha",level=61,minLevel=58,rewardNextId=10154,wowhead="https://www.wowhead.com/wotlk/quest=10153",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The tracks lead south from Makha's equipment, appearing to cross the Path of Glory. The roughness of the shallow ruts suggests that Makha's captors were in a hurry to move her to the next destination, but why?$B$BWas someone waiting there for her, perhaps Warboss Nekrogg, the leader named in the orders you found further north?$B$BThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Scout Makha, you're likely to find Warboss Nekrogg too.",logDesc="Continue south across the Path of Glory to the Southern Rampart and search for where Warboss Nekrogg is holding Scout Makha."} end
if not DB[10154] then DB[10154]={id=10154,zoneId=3483,name="Planning the Escape",level=61,minLevel=58,rewardNextId=10155,wowhead="https://www.wowhead.com/wotlk/quest=10154",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Like I said, getting out of here won't be easy. Warboss Nekrogg may look like an overgrown brute, but he's no simpleton.$B$BHe won't let the cage key out of his sight and doesn't come down from his tower atop that chunk of wall until he's ready to question me or that human he's managed to capture.$B$BIt's going to take something extraordinary to get him off that wall, but I have an idea. Find one of the grenadiers that patrol the ground along the Southern Rampart and bring me some of his explosives.",logDesc="Kill a Shattered Hand Grenadier and bring his Crude Explosives to Scout Makha at Gor'gaz Outpost."} end
if not DB[10155] then DB[10155]={id=10155,zoneId=3483,name="Provoking the Warboss",level=61,minLevel=58,rewardNextId=10059,wowhead="https://www.wowhead.com/wotlk/quest=10155",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The plan succeeds or fails on how well these explosives are made...$B$BAs much as I'd hate to rely on anything made by a fel orc, it's my only real chance to get out of here. Take this and throw it against the banner hanging from the tower up there.$B$BOnce it explodes, Warboss Nekrogg won't be able to resist the chance to make an example of the troublemaker. Kill him, take the key, and then open my cage. Good luck, $N.",logDesc="Use the Crude Explosives to create a disturbance and lure Warboss Nekrogg out of his tower. Kill him, obtain Nekrogg's Key, and use it to open Scout Makha's cage. Once you have freed Scout Makha, report to Stone Guard Ambelan at Spinebreaker Post near Zeth'Gor.",choiceRewards={{id=25991,qty=1},{id=25990,qty=1},{id=25988,qty=1}}} end
if not DB[10156] then DB[10156]={id=10156,zoneId=3483,name="Under Whose Orders?",level=61,minLevel=58,rewardNextId=10157,wowhead="https://www.wowhead.com/wotlk/quest=10156",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="One thing is clear, $N: we can't keep this up. The fel orcs have us pinned down and as quickly as we can kill them, several spring up to replace them. We can't hope to win this war with our forces divided and locked in constant combat with the fel orcs and the demons of the Legion.$B$BYou've done a remarkable job of blunting the fel orc attack, but now you must fight your way up the Path of Glory and learn who is orchestrating this offensive.",logDesc="Kill 20 Shattered Hand Grunts, 10 Shattered Hand Warlocks, and capture Drillmaster Zurok's Orders. Then, return to Stone Guard Ambelan at Spinebreaker Post."} end
if not DB[10157] then DB[10157]={id=10157,zoneId=3483,name="Dispatching the Commander",level=62,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=10157",image="assets/images/quests/placeholder.png",xpDiff=6,money=54000,desc="From what I can tell, Drillmaster Zurok served as the right hand of the fel orc leader in Hellfire Peninsula, Force-Commander Gorax.$B$BThis Gorax isn't your typical fel orc brute, though. I almost admire the way he managed to keep us on the defensive for so long.$B$BZurok's orders indicate that Gorax's command center is located at the end of the Path of Glory, near where the citadel's walls meet the Northern Rampart. There's no telling what to expect, $N, but it would be wise to travel with allies.",logDesc="Slay Force-Commander Gorax and report to Shadow Hunter Ty'jin at Thrallmar.",choiceRewards={{id=28051,qty=1},{id=28057,qty=1},{id=28050,qty=1},{id=28055,qty=1},{id=28052,qty=1},{id=28054,qty=1}}} end
if not DB[10158] then DB[10158]={id=10158,zoneId=3483,name="Bleeding Hollow Supplies",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10158",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The orcish ruins of Zeth'Gor to serve as a base for an ever-growing tide of orcs emerging from Hellfire Citadel.$B$BShadow Hunter Ty'jin sent me here to keep an eye on the outpost and its strange inhabitants.$B$BSomething has changed these orcs, augmented them in a way we've never seen before. We have to do anything we can to keep them from strengthening. Fight your way into Zeth'Gor and destroy any supplies you find there.",logDesc="Destroy 6 piles of Bleeding Hollow Supplies and report to Stone Guard Ambelan at Spinebreaker Post."} end
if not DB[10159] then DB[10159]={id=10159,zoneId=3483,name="Keep Thornfang Hill Clear!",level=63,minLevel=61,giver="Mahuram Stouthoof",giverType="NPC",giverId=16888,ender="Mahuram Stouthoof",enderType="NPC",enderId=16888,poiX=-315,poiY=4716,wowhead="https://www.wowhead.com/wotlk/quest=10159",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="We've been fighting an ongoing battle to keep the pass through Thornfang Hill to the west clear of ravagers.  It would be bad if we were to become completely cut off from the refuge in Zangarmarsh.$B$BWe don't want to displace the creatures, but there seems to be little choice as their attacks on travelers through the area have become more aggressive.$B$BClear some of the ravagers out of there if you can.",logDesc="Kill 8 Thornfang Ravagers and 8 Thornfang Venomspitters, and then return to Mahuram Stouthoof at the Cenarion Post in Hellfire Peninsula."} end
if not DB[10160] then DB[10160]={id=10160,zoneId=3483,name="Know your Enemy",level=61,minLevel=58,giver="Force Commander Danath Trollbane",giverType="NPC",giverId=16819,ender="Lieutenant Amadi",enderType="NPC",enderId=16820,rewardNextId=10482,poiX=-816,poiY=2614,wowhead="https://www.wowhead.com/wotlk/quest=10160",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Rumors have surfaced that some new breed of orc is on the rise. Larger, meaner - more cunning than the brutes we're familiar with.  If these rumors are true then our forces, already stretched, may be taxed beyond their limit.$B$BI have entrusted my lieutenant, Amadi, with investigating this matter. If you would help us in this dark hour, seek her out. She is stationed at the broken tower just west of the Hold.$B$BAnd $N - be careful out there. You're heading into a dangerous new world.",logDesc="Speak with Lieutenant Amadi at the old guard tower just west of Honor Hold."} end
if not DB[10161] then DB[10161]={id=10161,zoneId=3483,name="In Case of Emergency...",level=61,minLevel=58,giver="\"Screaming\" Screed Luckheed",giverType="NPC",giverId=19367,ender="\"Screaming\" Screed Luckheed",enderType="NPC",enderId=19367,rewardNextId=9351,poiX=-1097,poiY=3001,wowhead="https://www.wowhead.com/wotlk/quest=10161",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="In the event of an emergency, it's always the pilot's job to keep a level head, especially when the only orders your co-pilot follows come from his stomach.$B$BThe good news is that we won't need to wait days for replacement parts to be imported. The bad news is that the \"spare\" parts got scattered from here to the Valley of Bones to the east.$B$BThe other bad news? The spare parts aren't so spare. They, uh, fell off during our rapid descent. Could you help me collect enough to get us off the ground again?",logDesc="Collect 30 pieces of Zeppelin Debris and bring them to \"Screaming\" Screed Luckheed at the Zeppelin Crash.",choiceRewards={{id=25981,qty=1},{id=25980,qty=1},{id=25979,qty=1}}} end
if not DB[10162] then DB[10162]={id=10162,zoneId=3483,name="Mission: The Abyssal Shelf",level=62,minLevel=58,giver="Forward Commander To'arch",giverType="NPC",giverId=19273,ender="Forward Commander To'arch",enderType="NPC",enderId=19273,poiX=-20,poiY=2137,wowhead="https://www.wowhead.com/wotlk/quest=10162",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now that you've got your wings, perhaps you'd be interested in running another bombing mission?$B$BThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a wyvern and destroy the whole damned thing!$B$BHere are your bombs - now, talk to Wing Commander Brack when you're ready for takeoff.",logDesc="Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.",choiceRewards={{id=29926,qty=1},{id=29940,qty=1},{id=29933,qty=1},{id=29936,qty=1}}} end
if not DB[10163] then DB[10163]={id=10163,zoneId=3483,name="Mission: The Abyssal Shelf",level=62,minLevel=58,giver="Wing Commander Gryphongar",giverType="NPC",giverId=20232,ender="Wing Commander Gryphongar",enderType="NPC",enderId=20232,poiX=315,poiY=1442,wowhead="https://www.wowhead.com/wotlk/quest=10163",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now that you've got your wings, perhaps you'd be interested in running another bombing mission?$B$BThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a gryphon and destroy the whole damned thing!$B$BHere are your bombs - now, talk to Gryphoneer Windbellow when you're ready for takeoff.$B",logDesc="Wing Commander Gryphongar at Shatter Point in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.",choiceRewards={{id=29926,qty=1},{id=29940,qty=1},{id=29933,qty=1},{id=29936,qty=1}}} end
if not DB[10164] then DB[10164]={id=10164,zoneId=3790,name="Everything Will Be Alright",level=67,minLevel=64,giver="Greatfather Aldrimus",giverType="NPC",giverId=19698,ender="Greatfather Aldrimus",enderType="NPC",enderId=19698,poiX=-3345,poiY=5189,wowhead="https://www.wowhead.com/wotlk/quest=10164",image="assets/images/quests/placeholder.png",xpDiff=8,desc="You've had quite an adventure, $N. And before you've even set foot inside of the Auchenai Crypts.$B$BI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.$B$BWhat I ask is simple. Enter the Auchenai Crypts and destroy Exarch Maladaar so that the spirits trapped inside can finally rest in peace.",logDesc="Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and destroy Exarch Maladaar.",choiceRewards={{id=29341,qty=1},{id=29340,qty=1},{id=29339,qty=1},{id=29337,qty=1}}} end
if not DB[10165] then DB[10165]={id=10165,zoneId=3792,name="Undercutting the Competition",level=66,minLevel=64,giver="Nexus-Prince Haramad",giverType="NPC",giverId=19674,ender="Nexus-Prince Haramad",enderType="NPC",enderId=19674,poiX=-3105,poiY=4957,wowhead="https://www.wowhead.com/wotlk/quest=10165",image="assets/images/quests/placeholder.png",xpDiff=8,money=105000,desc="That Shaffar is a shrewd one - I'll give him that... He's managed to keep the Consortium out while he safely pillages this crypt for all it's worth. I have no faith in these imbeciles actually breaking through Shaffar's defenses so I'll make you a deal, $r.$B$BEnter the Mana-Tombs and kill Nexus-Prince Shaffar. Bring me back his body wrap as proof of this deed and I'll reward you handsomely.",logDesc="Nexus-Prince Haramad located outside of the Mana-Tombs wants you to kill Nexus-Prince Shaffar and bring Shaffar's Wrappings back to him.",choiceRewards={{id=29343,qty=1},{id=29342,qty=1},{id=29345,qty=1},{id=29344,qty=1}}} end
if not DB[10166] then DB[10166]={id=10166,zoneId=3430,name="Whitebark's Memory",level=10,minLevel=7,giver="Larianna Riverwind",giverType="NPC",giverId=15398,ender="Whitebark's Spirit",enderType="NPC",enderId=19456,poiX=8414,poiY=-6165,wowhead="https://www.wowhead.com/wotlk/quest=10166",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This pendant brings back memories of a different time.  A better time.$B$BUnfortunately, memories are the last thing I need right now.$B$BI want you to bury this by the runestone in the Scorched Grove.  It was there that I first met the treant elder.  Put my old friend's memory to rest.",logDesc="Larianna Riverwind wants you to place Old Whitebark's Pendant by the runestone at the Scorched Grove."} end
if not DB[10167] then DB[10167]={id=10167,zoneId=3790,name="Auchindoun...",level=68,minLevel=66,giver="A'dal",giverType="NPC",giverId=18481,ender="D'ore",enderType="NPC",enderId=19412,rewardNextId=10168,poiX=-1864,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=10167",image="assets/images/quests/placeholder.png",xpDiff=8,desc="Deep within the Auchenai Crypts is a tomb: A tomb unlike any that exists on this shattered realm. It was from this tomb, the first tomb, that the vast mausoleum of Auchindoun was born.$B$BYou must venture to the Auchenai Crypts of Auchindoun and find this tomb. Slay the guardian of the crypt to release the captive spirit within. The spirit holds the key... ",logDesc="Travel to the Auchenai Crypts in the Bone Wastes of Terokkar Forest and slay Exarch Maladaar to free the spirit of D'ore.$B"} end
if not DB[10168] then DB[10168]={id=10168,zoneId=3518,name="What the Soul Sees",level=68,minLevel=66,giver="D'ore",giverType="NPC",giverId=19412,ender="Mother Kashur",enderType="NPC",enderId=18687,rewardNextId=10170,wowhead="https://www.wowhead.com/wotlk/quest=10168",image="assets/images/quests/placeholder.png",xpDiff=6,desc="For several centuries, the spirits of Auchindoun coalesced into my darkened essence. Many of the catastrophes that befell this crypt were a direct result of my weakened state.$B$BRegrettably, there is nothing that can be done to stop this cycle. It is a facet of the naaru condition - without the void, the Light cannot exist.$B$BYour only recourse is to destroy the ancient spirits of Nagrand before they transform into creatures of the void. Use the soul mirrors found throughout this crypt to free them...",logDesc="Locate a Soul Mirror somewhere in the Auchenai Crypts and use it to call forth a Darkened Spirit from Ancient Orc Ancestors in Nagrand. Destroy 15 Darkened Spirits so that the ancestors may rest in peace.$B$BReturn to Mother Kashur at the Ancestral Grounds when this task is complete."} end
if not DB[10169] then DB[10169]={id=10169,zoneId=3703,name="Losing Gracefully",level=65,minLevel=62,wowhead="https://www.wowhead.com/wotlk/quest=10169",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The Aldor have gained the favor of the Sha'tar today.  As if that should come as any sort of surprise!$B$BWatch them showing off their fancy footwork a few feet away from A'dal.  Could they possibly put any more effort into sucking up to the naaru?$B$BHarbinger Haronem's marksman regiment is so dedicated, it even brings its own cooking pot to avoid taking long breaks for lunch.  This cannot go without retribution, $N.$B$BI want you to pour this vial into their meal.  The results should be... comical.",logDesc="Magister Falris in Shattrath wants you to take the Vial of Sedative Serum to the Terrace of Light and pour it into Haronem's Regiment Cooking Pot."} end
if not DB[10170] then DB[10170]={id=10170,zoneId=3518,name="Return to the Greatmother",level=68,minLevel=66,giver="Mother Kashur",giverType="NPC",giverId=18687,ender="Greatmother Geyah",enderType="NPC",enderId=18141,rewardNextId=10171,poiX=-2210,poiY=8820,wowhead="https://www.wowhead.com/wotlk/quest=10170",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Return to Greatmother Geyah at Garadar with news of your victory, $N. This will surely lift the spirits of the Mag'har. Perhaps even the young Hellscream will be lifted from his malaise.",logDesc="Return to Garadar and speak to Greatmother Geyah."} end
if not DB[10171] then DB[10171]={id=10171,zoneId=3518,name="The Inconsolable Chieftain",level=68,minLevel=66,giver="Greatmother Geyah",giverType="NPC",giverId=18141,ender="Garrosh",enderType="NPC",enderId=18063,rewardNextId=10172,poiX=-1222,poiY=7163,wowhead="https://www.wowhead.com/wotlk/quest=10171",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You have done so much for the Mag'har, $N. Your accomplishments are known to all, including Garrosh. Go to him now and tell him of your latest victory. Tell him that you do what you do for him and his people. Surely he will be lifted by your words.",logDesc="Greatmother Geyah at Garadar has asked that you speak with Garrosh."} end
if not DB[10172] then DB[10172]={id=10172,zoneId=3518,name="There Is No Hope",level=68,minLevel=66,giver="Garrosh",giverType="NPC",giverId=18063,ender="Greatmother Geyah",enderType="NPC",enderId=18141,rewardNextId=10175,poiX=-1345,poiY=7233,wowhead="https://www.wowhead.com/wotlk/quest=10172",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You are an honorable $r, $N. You have done much for the Mag'har. No one could ever deny your service to my people. Alas, the time of the Mag'har is at an end. You have shown me, more than anything, that I am unfit to lead these people. My cursed blood runs too deep. I will not... I cannot become the second Hellscream to damn the orcs.$B$BPlease, $N, return to the Greatmother and tell her what I have told you. I am too ashamed to see her... to look into her eyes.",logDesc="Speak to Greatmother Geyah and tell her what Garrosh told you.",rewards={{id=28168,qty=1}},choiceRewards={{id=28173,qty=1},{id=28169,qty=1},{id=28172,qty=1},{id=28175,qty=1}}} end
if not DB[10173] then DB[10173]={id=10173,zoneId=3523,name="The Archmage's Staff",level=68,minLevel=67,giver="Ravandwyr",giverType="NPC",giverId=19217,ender="Ravandwyr",enderType="NPC",enderId=19217,rewardNextId=10300,poiX=2998,poiY=3735,wowhead="https://www.wowhead.com/wotlk/quest=10173",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Allow me to introduce myself, $c.$B$BI am Ravandwyr, apprentice to the Archmage Vargoth.$B$BMy master is... indisposed, shall we say. I am here on a matter of great importance.$B$BThe Arklon Ruins southeast of the city are a hotbed of Burning Legion activity. Their purpose in the ruins concerns neither me nor my master, but their leader, Ekkorash, possesses the archmage's staff.$B$BThis conjuring powder will allow you to draw the demon out of hiding. Sprinkle it on the brazier at the center of the ruins.",logDesc="Retrieve Archmage Vargoth's Staff from Ekkorash the Inquisitor and bring it to Ravandwyr in Area 52. To bring Ekkorash out of hiding, sprinkle the Conjuring Powder on the brazier in the center of the ruins."} end
if not DB[10174] then DB[10174]={id=10174,zoneId=3523,name="Curse of the Violet Tower",level=68,minLevel=67,giver="Ravandwyr",giverType="NPC",giverId=19217,ender="Image of Archmage Vargoth",enderType="NPC",enderId=19644,rewardNextId=10188,poiX=2998,poiY=3735,wowhead="https://www.wowhead.com/wotlk/quest=10174",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Now, you will be able to use the archmage's staff to contact him.$B$BHe resides in the Violet Tower, on an 'island' to the southeast. The tower is both sanctuary and prison to him, cursed as it is. Kirin Tor can neither enter nor leave, keeping me apart from my master.$B$BThe staff's magic can penetrate the tower's defenses, but only if invoked by one outside the Kirin Tor.$B$BTake the archmage's staff and use it to conjure his image. Tell him what has happened and that I have not completely failed him.",logDesc="Use Archmage Vargoth's Staff to make contact with Archmage Vargoth.$B$BIf you lose Archmage Vargoth's Staff, speak to Ravandwyr at Area 52 to receive a replacement."} end
if not DB[10175] then DB[10175]={id=10175,zoneId=3518,name="Thrall, Son of Durotan",level=68,minLevel=66,giver="Greatmother Geyah",giverType="NPC",giverId=18141,ender="Thrall",enderType="NPC",enderId=4949,rewardNextId=10212,poiX=-1222,poiY=7163,wowhead="https://www.wowhead.com/wotlk/quest=10175",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Return to your world, $N. Go to my grandchild and tell him that his blood is here - on this shattered world.$B$BTell him that his father's legacy lives on.$B$BTell him everything...$B",logDesc="Venture to Orgrimmar and deliver Geyah's message to Thrall."} end
if not DB[10176] then DB[10176]={id=10176,zoneId=3523,name="Ar'kelos the Guardian",level=68,minLevel=67,giver="Image of Archmage Vargoth",giverType="NPC",giverId=19644,ender="Archmage Vargoth",enderType="NPC",enderId=19481,wowhead="https://www.wowhead.com/wotlk/quest=10176",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Now that you've gathered all the items I'll need to break Kael'thas's curse, one thing remains to be done. When Kael'thas sealed the tower, he placed an arcane golem, known as Ar'kelos, at the bottom of the tower.$B$BYou must defeat Ar'kelos in order allow me to work magic within the tower again.$B$BWhen you enter the Violet Tower, the curse will begin to affect you.$B$BOnce you have defeated Ar'kelos, ascend the tower and assist me in making preparations for the ritual.",logDesc="Enter the Violet Tower at the center of Kirin'Var Village and defeat Ar'kelos, then speak with Archmage Vargoth.",choiceRewards={{id=29775,qty=1},{id=29776,qty=1},{id=29777,qty=1},{id=29779,qty=1}}} end
if not DB[10177] then DB[10177]={id=10177,zoneId=3688,name="Trouble at Auchindoun",level=70,minLevel=68,giver="Spymistress Mehlisah Highcrown",giverType="NPC",giverId=18893,ender="Field Commander Mahfuun",enderType="NPC",enderId=19542,rewardNextId=10094,poiX=-1869,poiY=5479,wowhead="https://www.wowhead.com/wotlk/quest=10177",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I have spies within Auchindoun and they have been sending me disturbing reports.  That place has been nothing but trouble ever since it exploded a couple of years ago.$B$BSomething in there has gone horribly wrong - again - and the Shadow Council is now on a war footing.  Though the reports were lacking on details, their preparations appear to be directed inward.$B$BYou must make your way to the entrance of the Shadow Labyrinth.  My field commander, Mahfuun, will fill you in on what needs to be done.",logDesc="Report to Field Commander Mahfuun at the entrance to the Shadow Labyrinth at Auchindoun in Terokkar Forest."} end
if not DB[10178] then DB[10178]={id=10178,zoneId=3688,name="Find Spy To'gun",level=70,minLevel=68,giver="Spy Grik'tha",giverType="NPC",giverId=19496,ender="Spy To'gun",enderType="NPC",enderId=18891,rewardNextId=10091,poiX=-3602,poiY=4927,wowhead="https://www.wowhead.com/wotlk/quest=10178",image="assets/images/quests/placeholder.png",xpDiff=8,desc="To'gun, the fool!  We're barely holding off the attacks here, and he goes back in to get more information and try to save the other spies!$B$BI don't know whether to love him or kill him!$B$BThe Shadow Council must have used magic to ferret us out, because all of our spies had to get out of there in a hurry.  Most of us didn't make it.$B$BPlease, if you're brave enough to enter the Shadow Labyrinth, will you keep an eye peeled for To'gun?  It's been a while, and I fear the worst.",logDesc="Locate Spy To'gun in the Shadow Labyrinth of Auchindoun."} end
if not DB[10179] then DB[10179]={id=10179,zoneId=3523,name="The Custodian of Kirin'Var",level=68,minLevel=67,wowhead="https://www.wowhead.com/wotlk/quest=10179",image="assets/images/quests/placeholder.png",xpDiff=2,desc="When it became clear that our expedition was trapped in Outland with no way to return to Azeroth, the Kirin Tor contingent traveled to the Plains of Farahlon and built Kirin'Var village. I left the administration of the town in the hands of Custodian Dieworth, but when Kael'thas and his forces sealed me in the Violet Tower, I lost contact with the custodian.$B$BSearch for him in Kirin'Var Village and help him in any way you can, $N. I'm certain he's got his hands full in the aftermath of the attack.",logDesc="Speak with Custodian Dierworth at Kirin'Var Village in Netherstorm."} end
if not DB[10180] then DB[10180]={id=10180,zoneId=3519,name="Can't Stay Away",level=69,minLevel=65,giver="Oloraak",giverType="NPC",giverId=19045,ender="Isfar",enderType="NPC",enderId=18933,poiX=-1606,poiY=5378,wowhead="https://www.wowhead.com/wotlk/quest=10180",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I tried to persuade Isfar to remain here, in the safety of Shattrath, but he would have none of it. Instead, he's decided to venture out to Auchindoun again on his own.$B$BHe was lucky enough to escape the Sethekk Halls once, but if they discover him, there won't be a second time.$B$BI admire his desire to free his sister, but he's not going to be able to do it without help.$B$BFind Isfar and have a word with him, $N. If you can't persuade him to come back, perhaps you could help him rescue Lakka?",logDesc="Speak with Isfar, who can be found near the entrance to the Sethekk Halls in Auchindoun."} end
if not DB[10181] then DB[10181]={id=10181,zoneId=0,name="Collector's Edition: -pn - E - FLAG",level=1,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=10181",image="assets/images/quests/placeholder.png"} end
if not DB[10182] then DB[10182]={id=10182,zoneId=3523,name="Battle-Mage Dathric",level=68,minLevel=67,ender="Custodian Dieworth",enderType="NPC",enderId=19488,wowhead="https://www.wowhead.com/wotlk/quest=10182",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The sword is of exceptional quality, finely crafted and perfectly balanced for a battle-mage. The seal of the Kirin Tor and the name \"Dathric\" are engraved into the weapon's pommel.$B$BTurning the weapon over in your hands, you notice a sense of wrongness radiating from the metal, as if the item is torn between two worlds. Could this be the item anchoring Battle-Mage Dathric's spirit to this world?$B$BPerhaps returning it to its proper place can break the bond, freeing Dathric's spirit to rest at last.",logDesc="Locate Battle-Mage Dathric's quarters in Wizard's Row and return the blade to his weapon rack. Then, speak with Custodian Dieworth at Kirin'Var Village."} end
if not DB[10183] then DB[10183]={id=10183,zoneId=3523,name="Off To Area 52",level=68,minLevel=67,giver="Netherologist Coppernickels",giverType="NPC",giverId=19569,ender="Rocket-Chief Fuselage",enderType="NPC",enderId=19570,rewardNextId=10186,poiX=3389,poiY=4296,wowhead="https://www.wowhead.com/wotlk/quest=10183",image="assets/images/quests/placeholder.png",xpDiff=2,money=10000,desc="I'm out here studying the nether - the ethereal currents and all that.  This is an ideal spot away from the lights and hubbub of town.  Isn't this bridge great?  If I could just keep this junk working.$B$BHey, you know, if you're looking for work there's plenty at Area 52!  It's just up the path and take a right at the fork in the road.$B$BWhy don't you deliver my latest research notes to Rocket-Chief Fuselage?  I'm sure that he'd have plenty for you to do, what with the X-52 rocket ship, and all!",logDesc="Deliver the Netherologist's Notes to Rocket-Chief Fuselage at Area 52 in the Netherstorm."} end
if not DB[10184] then DB[10184]={id=10184,zoneId=3523,name="Malevolent Remnants",level=68,minLevel=67,giver="Custodian Dieworth",giverType="NPC",giverId=19488,ender="Custodian Dieworth",enderType="NPC",enderId=19488,rewardNextId=10312,poiX=2247,poiY=2277,wowhead="https://www.wowhead.com/wotlk/quest=10184",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Most of the spirits in the village are little more than pale remnants of Kirin Tor mages. They retain no knowledge of their former selves and wander the ruins in blind anger.$B$BIt wasn't always like this, though. In the immediate aftermath of the attack, the spirits were restless, but not spiteful. With the passage of time they have only grown more aggressive. I dare not venture into the southern part of the village, for they will not spare even me. Quiet them and let us hope it will purge their anger.",logDesc="Custodian Dieworth at Kirin'Var Village wants you to defeat 20 Severed Spirits in Kirin'Var's Town Square."} end
if not DB[10185] then DB[10185]={id=10185,zoneId=3523,name="A Fate Worse Than Death",level=68,minLevel=67,giver="Custodian Dieworth",giverType="NPC",giverId=19488,ender="Custodian Dieworth",enderType="NPC",enderId=19488,poiX=2247,poiY=2277,wowhead="https://www.wowhead.com/wotlk/quest=10185",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="After the blood elves leveled Kirin'Var Village, they started the construction of a large building to the northwest. Without the expertise of the archmage, we can't say for certain what's going on there.$B$BOne thing is clear, though. The blood elf activities have unleashed a tide of ravenous mana elementals on the village. They seem drawn to the ruins of Wizard Row, wreaking further destruction. We cannot permit this to continue.",logDesc="Kill 10 Mageslayers and 10 Mana Seekers and return to Custodian Dieworth at Kirin'Var Village.",choiceRewards={{id=29955,qty=1},{id=29954,qty=1},{id=30401,qty=1},{id=29959,qty=1}}} end
if not DB[10186] then DB[10186]={id=10186,zoneId=3523,name="You're Hired!",level=68,minLevel=67,giver="Rocket-Chief Fuselage",giverType="NPC",giverId=19570,ender="Rocket-Chief Fuselage",enderType="NPC",enderId=19570,poiX=3042,poiY=3659,wowhead="https://www.wowhead.com/wotlk/quest=10186",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Let me be the first to welcome you aboard, Junior Technician 3rd Grade $N!$B$BWe're building my masterpiece out here - the X-52 Nether-Rocket!$B$BBut first we need to get all of the parts and fuel for it.  That's where you come in.$B$BTo start, I need crystals - LOTS of crystals - for the rocket's Etherlithium Engine Matrix.  The draenei had crystals coming out of their ears!$B$BSo head north to the Ruins of Enkaat and get them for me!  Nevermind all of the draenei ghosts.",logDesc="Collect 10 Etherlithium Matrix Crystals and return them to Rocket-Chief Fuselage at Area 52 in the Netherstorm.",choiceRewards={{id=30225,qty=1},{id=30224,qty=1},{id=30218,qty=1},{id=30515,qty=1}}} end
if not DB[10187] then DB[10187]={id=10187,zoneId=3523,name="A Message for the Archmage",level=69,minLevel=67,wowhead="https://www.wowhead.com/wotlk/quest=10187",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Although things are grim here, it heartened us quite a bit to hear from you that the archmage has not forgotten the village's plight.$B$B<The custodian glances up at the tower.>$B$BIt's ridiculous, isn't it? Sometimes it seems all that separates us is a wall of mere stone. The wall of magic is easy enough to forget.$B$BIf you would be so kind, ascend the tower and let Archmage Vargoth know that we are making progress with the village and will soon have a plan to ward off the mana creatures.",logDesc="Speak to Archmage Vargoth at the top of the Violet Tower in Netherstorm."} end
if not DB[10188] then DB[10188]={id=10188,zoneId=3523,name="The Sigil of Krasus",level=69,minLevel=67,giver="Image of Archmage Vargoth",giverType="NPC",giverId=19644,ender="Image of Archmage Vargoth",enderType="NPC",enderId=19644,rewardNextId=10192,wowhead="https://www.wowhead.com/wotlk/quest=10188",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Before we departed Azeroth all those years ago, the Kirin Tor entrusted our expedition with a powerful artifact, the Sigil of Krasus. It was a great boon to us in our battle against the orcs and it could play a key role in helping me break the enchantment that imprisons me.$B$BHowever, when Kael'thas divested me of my possessions, he gave the sigil to Spellbinder Maryana, who remained behind with the garrison. If he truly realized what he had in his possession, he wouldn't have given it away so easily.",logDesc="Retrieve the Sigil of Krasus from Spellbinder Maryana at Manaforge Coruu, northwest of the Violet Tower.",choiceRewards={{id=29771,qty=1},{id=29772,qty=1},{id=29773,qty=1},{id=29774,qty=1}}} end
if not DB[10189] then DB[10189]={id=10189,zoneId=3523,name="Manaforge B'naar",level=68,minLevel=67,giver="Spymaster Thalodien",giverType="NPC",giverId=19468,ender="Spymaster Thalodien",enderType="NPC",enderId=19468,rewardNextId=10193,poiX=3075,poiY=3699,wowhead="https://www.wowhead.com/wotlk/quest=10189",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="You may have noticed one of Kael's manaforges on your way here.  You know, the large purple buildings sucking energy from the sky?$B$BWe were sent here by the Sha'tar to investigate them.  You can help our information gathering efforts by obtaining a personnel roster.  Giving us an idea of who's there and what they do will prove to be invaluable information.$B$BWe believe Captain Arathyn, leading a ballista team just outside of Manaforge B'naar, is in possession of one such roster.  Obtain it for us.",logDesc="Spymaster Thalodien at Area 52 wants you to go to the outskirts of Manaforge B'naar and retrieve the B'naar Personnel Roster from Captain Arathyn.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10190] then DB[10190]={id=10190,zoneId=3523,name="Recharging the Batteries",level=68,minLevel=67,giver="Bot-Specialist Alley",giverType="NPC",giverId=19578,ender="Bot-Specialist Alley",enderType="NPC",enderId=19578,poiX=3353,poiY=3726,wowhead="https://www.wowhead.com/wotlk/quest=10190",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="I have the very important task of collecting the machinery inside these ruins, but I'm having a problem keeping all of my bots charged up.$B$BThe phase hunters - those wyrm-looking things - have lots of energy!  You can find them all over the edges of this island, floating in from the nether.$B$BFill the battery on this recharging blaster by using it on a phase hunter when they're very weak, and then finish it off to soak up the last of its energy.",logDesc="Use the Battery Recharging Blaster on enough Phase Hunters to get the Battery Recharge Level to 10.  Then return it to Bot-Specialist Alley at the Ruins of Enkaat in the Netherstorm."} end
if not DB[10191] then DB[10191]={id=10191,zoneId=3523,name="Mark V is Alive!",level=68,minLevel=67,giver="Maxx A. Million Mk. V",giverType="NPC",giverId=19589,ender="Bot-Specialist Alley",enderType="NPC",enderId=19578,poiX=3351,poiY=3722,wowhead="https://www.wowhead.com/wotlk/quest=10191",image="assets/images/quests/placeholder.png",xpDiff=6,money=78000,desc="Greetings, $r.  I am charged up and fully functional.$B$BThere are fragile draenei machines in these ruins, which I must retrieve.  I am equipped with delicate servos in my wrist actuators, and the latest in combustion-pneumatic bump soakers.  Handling them with care will not be an issue.$B$BHowever, the ghosts that haunt these ruins will likely attack, so I will need you and your friends along for protection.",logDesc="Escort the Maxx A. Million Mk. V through the Ruins of Enkaat and back out to safety.  Then speak with Bot-Specialist Alley just outside the Ruins of Enkaat in the Netherstorm.",choiceRewards={{id=30226,qty=1},{id=30227,qty=1},{id=30252,qty=1}}} end
if not DB[10192] then DB[10192]={id=10192,zoneId=3523,name="Krasus's Compendium",level=69,minLevel=67,giver="Image of Archmage Vargoth",giverType="NPC",giverId=19644,ender="Image of Archmage Vargoth",enderType="NPC",enderId=19644,rewardNextId=10301,wowhead="https://www.wowhead.com/wotlk/quest=10192",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The Kirin Tor sent one other of Krasus's possessions with our expedition. It was his spellbook, called Krasus's Compendium. Containing all the spells he mastered, it lent us a much-needed advantage in the war.$B$BBefore Kael'thas and his forces laid siege to Kirin'Var, the compendium had been stolen from me by a rebellious apprentice intent on studying necromancy. The apprentice and his followers divided and studied the text in secret, locking themselves inside their houses in the southern part of town.",logDesc="Reclaim Krasus's Compendium - Chapter 1, Krasus's Compendium - Chapter 2, and Krasus's Compendium - Chapter 3 from Kirin'Var Village's Town Square. "} end
if not DB[10193] then DB[10193]={id=10193,zoneId=3523,name="High Value Targets",level=68,minLevel=67,giver="Spymaster Thalodien",giverType="NPC",giverId=19468,ender="Spymaster Thalodien",enderType="NPC",enderId=19468,rewardNextId=10329,poiX=3075,poiY=3699,wowhead="https://www.wowhead.com/wotlk/quest=10193",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Based on the roster information, we know that the brains of the manaforge operations are the warp-masters and warp-engineers.  It is they who oversee the retrieval of a so called \"warp-energy\" by the manaforge and its delivery to a remote destination via a system of underground pipes.$B$BThe only other specialists in the area are geologists.  Everyone else is either part of the military or a magister crony; both easily replaced.$B$BGet in there and kill Kael's specialists; that's what'll hurt him the most.",logDesc="Spymaster Thalodien at Area 52 wants you to go to Manaforge B'naar and slay 2 Sunfury Warp-Masters, 6 Sunfury Warp-Engineers and 8 Sunfury Geologists.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10194] then DB[10194]={id=10194,zoneId=3523,name="Stealth Flight",level=68,minLevel=67,giver="Spymaster Thalodien",giverType="NPC",giverId=19468,ender="Veronia",enderType="NPC",enderId=20162,rewardNextId=10652,poiX=3075,poiY=3699,wowhead="https://www.wowhead.com/wotlk/quest=10194",image="assets/images/quests/placeholder.png",xpDiff=1,desc="While you were gone, my men uncovered another one of these manaforges.  It is east of here and is known as Manaforge Coruu.$B$BTwo of my best spies have arranged a secret landing spot outside of the manaforge.  You are to help them infiltrate Kael's forces and obtain whatever information you can.$B$BSpeak to Veronia just outside the city walls; she's arranged for a windrider that will take you to Manaforge Coruu.  Once there, speak to Caledis Brightdawn; he will brief you on your mission.",logDesc="Speak to Veronia outside Area 52 and fly to Manaforge Coruu.$B$BCompleting quests for the Scryers will cause your Aldor reputation to decrease."} end
if not DB[10195] then DB[10195]={id=10195,zoneId=3519,name="Mercenary See, Mercenary Do",level=65,minLevel=62,wowhead="https://www.wowhead.com/wotlk/quest=10195",image="assets/images/quests/placeholder.png",desc="Ever since you brought that first batch of feathers and I completed Bertelm's hat, all the other mercenaries have been clamoring for their own, including Thander. It told them I'd get right on it, but I'm going to need a steady supply of arakkoa feathers for the project.$B$BI'll gladly accept any you happen to gather in your adventures in the forest.",logDesc="Bring 30 Arakkoa Feathers to Ros'eleth at the Allerian Stronghold.",rewards={{id=28499,qty=1}}} end
if not DB[10196] then DB[10196]={id=10196,zoneId=3519,name="More Arakkoa Feathers",level=65,minLevel=62,wowhead="https://www.wowhead.com/wotlk/quest=10196",image="assets/images/quests/placeholder.png",desc="I've had some success drawing the arakkoa spirits closer to me, but they are still very shy. Perhaps if I improve my disguise, they will be more willing to approach me in the trance.$B$BTo do that, though, I'll need more feathers like the ones you've already brought me. If you get any more of the feathers, I'd be very happy to take them off your hands.",logDesc="Bring 30 Arakkoa Feathers to Malukaz at Stonebreaker Hold.",rewards={{id=28499,qty=1}}} end
if not DB[10197] then DB[10197]={id=10197,zoneId=3523,name="A Convincing Disguise",level=68,minLevel=67,giver="Caledis Brightdawn",giverType="NPC",giverId=19840,ender="Caledis Brightdawn",enderType="NPC",enderId=19840,rewardNextId=10198,poiX=2238,poiY=2794,wowhead="https://www.wowhead.com/wotlk/quest=10197",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Infiltrating the ranks of Kael's army will not be an easy task.  With my knowledge of illusionary magic I could pass you off as one of Kael's followers, but there are certain details in their uniforms I could not replicate.$B$BBring me a set of their robes, a pair of their gloves and a Sunfury guardsman medallion.  This will make the results of my magic much more convincing.",logDesc="Obtain a set of Sunfury Arcanist Robes, one pair of Sunfury Researcher Gloves and a Sunfury Guardsman Medallion and bring them to Caledis Brightdawn at Manaforge Coruu in Netherstorm.$B$BCompleting quests for the Scryers will cause your Aldor reputation to decrease."} end
if not DB[10198] then DB[10198]={id=10198,zoneId=3523,name="Information Gathering",level=68,minLevel=67,giver="Caledis Brightdawn",giverType="NPC",giverId=19840,ender="Caledis Brightdawn",enderType="NPC",enderId=19840,rewardNextId=10330,poiX=2238,poiY=2794,wowhead="https://www.wowhead.com/wotlk/quest=10198",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I've prepared a uniform with the pieces you obtained.  It is magically enhanced to complete the illusion.$B$BWe spotted Commander Dawnforge going in to meet Arcanist Ardonis a few minutes ago.  He had a full retinue of guards with him, so whatever they're discussing is bound to be incredibly important; see if you can catch any of it.$B$BOh, I almost forgot.  You'll want to stay away from the arcane golems patrolling the manaforge.  They will see right through the illusion.",logDesc="Use the Sunfury Disguise, go into Manaforge Coruu and listen to the conversation between Commander Dawnforge and Arcanist Ardonis.  Report back to Caledis Brightdawn at Manaforge Coruu after completing this task.$B$BCompleting tasks for the Scryers will cause your Aldor reputation level to decrease.",choiceRewards={{id=30397,qty=1},{id=30383,qty=1},{id=30384,qty=1},{id=30386,qty=1}}} end
if not DB[10199] then DB[10199]={id=10199,zoneId=3523,name="That Little Extra Kick",level=68,minLevel=67,giver="Boots",giverType="NPC",giverId=19617,ender="Boots",enderType="NPC",enderId=19617,poiX=3081,poiY=3684,wowhead="https://www.wowhead.com/wotlk/quest=10199",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="So, I'm just missing the one ingredient that'll give my concoction that little extra kick that it needs.$B$BThe sting of the nether rays, roaming around near the shaleskin flayers, delivers quite a punch.  Bring me some of their stingers and I'll extract the venom right out of them!$B$BI'm certain the results will be explosive!",logDesc="Obtain 5 Nether Ray Stingers for Boots at Area 52 in the Netherstorm.",choiceRewards={{id=29999,qty=1},{id=30002,qty=1},{id=30001,qty=1},{id=30000,qty=1}}} end
if not DB[10200] then DB[10200]={id=10200,zoneId=3523,name="Return to Thalodien",level=68,minLevel=67,giver="Caledis Brightdawn",giverType="NPC",giverId=19840,ender="Spymaster Thalodien",enderType="NPC",enderId=19468,rewardNextId=10338,poiX=2238,poiY=2794,wowhead="https://www.wowhead.com/wotlk/quest=10200",image="assets/images/quests/placeholder.png",xpDiff=1,desc="It would be best if this information got back to Thalodien as soon as possible.  I'll stay here and cover our tracks.$B$BIt wouldn't do us much good to have Kael'thas find out what we were snooping around here.  Secret information is always better if your enemy doesn't know you have it.",logDesc="Return to Spymaster Thalodien at Area 52 in Netherstorm."} end
if not DB[10201] then DB[10201]={id=10201,zoneId=3519,name="And Now, the Moment of Truth",level=65,minLevel=62,giver="Rakoria",giverType="NPC",giverId=18385,ender="Rakoria",enderType="NPC",enderId=18385,poiX=-2616,poiY=4376,wowhead="https://www.wowhead.com/wotlk/quest=10201",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The oil is finally ready for its first test. It seems heavy enough to serve as a high quality weapon oil.$B$BThe only way to find out is to have a professional try it out. See Grek over there by the wanted posters? Sure, he's no poet, but the orc knows his way around a weapon!$B$BTake a sample of the oil to him and ask him to use it on his weapon. After he's had a chance to test it out, let me know what he thinks of it.",logDesc="Find Grek and ask him to try it on his weapon. Once he's tried out the oil, return to Rakoria with the results.",choiceRewards={{id=20748,qty=1},{id=20749,qty=1}}} end
if not DB[10202] then DB[10202]={id=10202,zoneId=3523,name="A Defector",level=70,minLevel=67,giver="Magistrix Larynna",giverType="NPC",giverId=19469,ender="Magister Theledorn",enderType="NPC",enderId=20920,rewardNextId=10432,poiX=3078,poiY=3696,wowhead="https://www.wowhead.com/wotlk/quest=10202",image="assets/images/quests/placeholder.png",xpDiff=3,desc="We've recently been contacted by a Sunfury magister who wishes to join our ranks and swears he has information we're in need of.  We've checked our informants to make sure he's not a double agent and he checks out.$B$BHe's stationed in Manaforge Ara which makes communication difficult.  Talk to him and see what he knows.  If he's half as useful as he claims to be, we'll be able to put him to good use.",logDesc="Go to Manaforge Ara and speak to Magister Theledorn.$B$BCompleting quests for the Scryers will cause your Aldor reputation to decrease."} end
if not DB[10203] then DB[10203]={id=10203,zoneId=3523,name="Invaluable Asset Zapping",level=69,minLevel=67,giver="Rocket-Chief Fuselage",giverType="NPC",giverId=19570,ender="Lead Sapper Blastfizzle",enderType="NPC",enderId=19634,poiX=3042,poiY=3659,wowhead="https://www.wowhead.com/wotlk/quest=10203",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="See the fissure running through Area 52?  We did that!  <grin>$B$BIt's yielding up all sorts of goodies for the X-52 Nether-Rocket, but we're running short on equipment.$B$BWe had an operation at the Arklon Ruins to the southeast until the Burning Legion moved in.  I need you to take this Ultra Deconsolodation Zapper to the ruins.  Use it to beam our gear back to Lead Sapper Blastfizzle down in the fissure.$B$BJunior Technician 3rd Grade $N, this is your chance for that promotion.  Don't blow it!",logDesc="Use the Ultra Deconsolodation Zapper to beam the Hyper Rotational Dig-A-Matic, Servo-Pneumatic Dredging Claw, Multi-Spectrum Terrain Analyzer, and the Big Wagon Full of Explosives back to Area 52.  Then report to Lead Sapper Blastfizzle at the eastern end of the fissure that runs through Area 52 in the Netherstorm."} end
if not DB[10204] then DB[10204]={id=10204,zoneId=3523,name="Bloodgem Crystals",level=68,minLevel=67,giver="Magistrix Larynna",giverType="NPC",giverId=19469,ender="Magistrix Larynna",enderType="NPC",enderId=19469,poiX=3078,poiY=3696,wowhead="https://www.wowhead.com/wotlk/quest=10204",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Kael's magisters have refined their usage of mana crystals to the point where they can siphon large amounts of energy in a matter of seconds.$B$BThey do this by attuning smaller bloodgem crystal shards to larger, fully charged ones.$B$BGo to Manaforge B'naar and obtain one of these shards from a Sunfury magister and use it to siphon energy from one of the larger crystals.$B$BReturn to me so that I may study the effects of the aura.  Do not worry; any side effects should be temporary.",logDesc="Magistrix Larynna wants you to go to Manaforge B'naar and obtain a Bloodgem Shard from a Sunfury Magister.  Use this shard near the larger Bloodgem crystals and return to her at Area 52.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10205] then DB[10205]={id=10205,zoneId=3523,name="Warp-Raider Nesaad",level=69,minLevel=67,giver="Nether-Stalker Khay'ji",giverType="NPC",giverId=19880,ender="Nether-Stalker Khay'ji",enderType="NPC",enderId=19880,rewardNextId=10266,poiX=3070,poiY=3675,wowhead="https://www.wowhead.com/wotlk/quest=10205",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Warp-Raider Nesaad must be dealt with!  I have no idea how he survived my attack, but he cannot be allowed to continue his operation out there.$B$BGo back and take out Nesaad.  He keeps a small ethereal camp near the southwestern corner of the Heap.$B$BDon't fail like I did, $c.",logDesc="Kill Warp-Raider Nesaad and then return to Nether-Stalker Khay'ji at Area 52 in the Netherstorm.",choiceRewards={{id=30266,qty=1},{id=30265,qty=1},{id=30267,qty=1}}} end
if not DB[10206] then DB[10206]={id=10206,zoneId=3523,name="Pick Your Part",level=68,minLevel=67,giver="Papa Wheeler",giverType="NPC",giverId=19645,ender="Papa Wheeler",enderType="NPC",enderId=19645,poiX=3053,poiY=3644,wowhead="https://www.wowhead.com/wotlk/quest=10206",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Those ethereal clowns are as opportunistic as us, I'll give them that.  But no one, and I mean NO ONE, moves in on a B.O.O.M. claim!$B$BThe Heap to the south is ours!$B$BIf we're to finish the X-52 Nether-Rocket, we're going to need all of the new tech that we can get our hands on.  And since the ethereals are stealing from us, I think it's only fair that we repay them in kind.$B$BWhy don't you head down there and see if you can acquire some of their technology out from under their noses!",logDesc="Collect 10 pieces of Ethereal Technology and return them to Papa Wheeler at Area 52 in the Netherstorm.",choiceRewards={{id=30275,qty=1},{id=30274,qty=1},{id=30276,qty=1}}} end
if not DB[10207] then DB[10207]={id=10207,zoneId=3483,name="Forward Base: Reaver's Fall REUSE",level=61,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=10207",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Your battle prowess has been noted by high command, $c. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...$B$BHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Foward Commander To'arch.$B$BNow move out!",logDesc="Report to Forward Commander To'arch at Reaver's Fall."} end
if not DB[10208] then DB[10208]={id=10208,zoneId=3483,name="Disrupt Their Reinforcements",level=62,minLevel=58,giver="Forward Commander To'arch",giverType="NPC",giverId=19273,ender="Forward Commander To'arch",enderType="NPC",enderId=19273,rewardNextId=10129,poiX=-20,poiY=2137,wowhead="https://www.wowhead.com/wotlk/quest=10208",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Directly east of here is the Legion Front.  Spaced across the front are infernal portals and gateways, used to bring reinforcements to Hellfire Peninsula and throughout Outland. We're going to destroy those portals!$B$BTake these primers.  Designed in Area 52, they use the demons' own power as an explosive!  Defeat Legion forces around Portals Xilus and Kruul to gather demonic rune stones, use the primer to detonate four stones inside the portals, and watch!  Return to me when your mission is complete.",logDesc="Defeat enemies around Portal Xilus and Portal Kruul to gather Demonic Rune Stones.$B$BUse To'arch's Primer within Portal Xilus and Portal Kruul.$B$BReturn to To'arch with To'arch's Primers at Reaver's Fall in Hellfire Peninsula.",choiceRewards={{id=29927,qty=1},{id=29939,qty=1},{id=29932,qty=1},{id=29946,qty=1},{id=29935,qty=1}}} end
if not DB[10209] then DB[10209]={id=10209,zoneId=3523,name="Summoner Kanthin's Prize",level=69,minLevel=67,giver="Image of Archmage Vargoth",giverType="NPC",giverId=19644,ender="Image of Archmage Vargoth",enderType="NPC",enderId=19644,rewardNextId=10176,wowhead="https://www.wowhead.com/wotlk/quest=10209",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The next thing we must do is reclaim my familiar, Glacius, from the blood elf summoner who holds it captive. Summoner Kanthin was one of the most senior magisters in the force Kael'thas sent to decimate Kirin'Var. It's only natural that he would claim my familiar as a kind of trophy.$B$BI'm certain that Kanthin, fool that he is, has tried to compel Glacius to serve him. My scrying has revealed that Kanthin is now stationed at 'Manaforge Duro,' if that terminology has any meaning for you.",logDesc="Defeat Summoner Kanthin at Manaforge Duro, on the island to the north of Sunfury Hold, and reclaim the Stone of Glacius from him."} end
if not DB[10210] then DB[10210]={id=10210,zoneId=3519,name="A'dal",level=65,minLevel=60,giver="Haggard War Veteran",giverType="NPC",giverId=19684,ender="A'dal",enderType="NPC",enderId=18481,poiX=-1560,poiY=5328,wowhead="https://www.wowhead.com/wotlk/quest=10210",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Welcome to Shattrath City, $c.  This might be the one place in all of Outland where you'll find any semblance of safety.$B$BA group of naaru known as the Sha'tar drove the demons away from here.$B$BIf you've never met a naaru, you ought to see A'dal inside the Terrace of Light.  The leader of the Sha'tar is an awe-inspiring sight if I ever saw one.  Sure is a change of pace from anything else in this bleak land.",logDesc="Speak to A'dal, the leader of the Sha'tar, in the center of the Terrace of Light."} end
if not DB[10211] then DB[10211]={id=10211,zoneId=3703,name="City of Light",level=65,minLevel=60,giver="Khadgar",giverType="NPC",giverId=18166,ender="Khadgar",enderType="NPC",enderId=18166,poiX=-1860,poiY=5420,wowhead="https://www.wowhead.com/wotlk/quest=10211",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Do not burden A'dal with petty inquisitions, $c.  That just might be the most powerful being you ever come face to face with.$B$BYou do not look familiar.  I suppose you want to learn about the city?$B$BYou'll have to excuse me if I don't give you a tour myself, but I'm a bit busy discussing strategy with A'dal.  Perhaps you'll find a summoned servant acceptable in my stead?  Excellent!",logDesc="Follow Khadgar's servant and listen to its story.  Return to Khadgar after completing this task."} end
if not DB[10212] then DB[10212]={id=10212,zoneId=3518,name="Hero of the Mag'har",level=68,minLevel=66,giver="Thrall",giverType="NPC",giverId=4949,ender="Greatmother Geyah",enderType="NPC",enderId=18141,poiX=1920,poiY=-4124,wowhead="https://www.wowhead.com/wotlk/quest=10212",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I must set things in order before I leave. Return to the Greatmother and tell her that her grandson comes. ",logDesc="Return to Greatmother Geyah at Garadar in Nagrand.$B",rewards={{id=28168,qty=1}},choiceRewards={{id=28173,qty=1},{id=28169,qty=1},{id=28172,qty=1},{id=28175,qty=1}}} end
if not DB[10213] then DB[10213]={id=10213,zoneId=3483,name="Investigate the Crash",level=61,minLevel=58,giver="Grelag",giverType="NPC",giverId=16858,ender="\"Screaming\" Screed Luckheed",enderType="NPC",enderId=19367,poiX=-1331,poiY=2393,wowhead="https://www.wowhead.com/wotlk/quest=10213",image="assets/images/quests/placeholder.png",xpDiff=2,desc="When I was wounded in the wastes I saw a goblin zeppelin crash.  It went down to the northwest, beyond the Expedition Armory. $B$BThe zeppelin was on fire.  Shrieking, burning goblins were falling like bombs from the sky.  Of course I was in a lot of pain and I had lost a lot of blood.  I may have imagined the whole thing.$B$BIf you can find any survivors, we can offer them sanctuary here at Spinebreaker Post.  ",logDesc="Search for crash survivors.  "} end
if not DB[10214] then DB[10214]={id=10214,zoneId=3483,name="When This Mine's a-Rockin'",level=61,minLevel=58,rewardNextId=10100,wowhead="https://www.wowhead.com/wotlk/quest=10214",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The mine's been overrun by a plague of gan'arg misfits, and on top of that, the peons have decided that this is a fine time for a nap! I don't know how they can sleep through all the disurbances coming from the mine, but that's the least of my problems.$B$BIf we don't get rid of those gan'arg pests soon, Thrallmar's supply of ore and other minerals will be cut off. I've already asked Watch Commander Krunk for help, but he says he can't spare the men with the town under constant attack. Will you help?",logDesc="Kill 15 Gan'arg Sappers and return to Foreman Razelcraz."} end
if not DB[10216] then DB[10216]={id=10216,zoneId=3792,name="Safety Is Job One",level=66,minLevel=64,giver="Artificer Morphalius",giverType="NPC",giverId=19670,poiX=-3106,poiY=4954,wowhead="https://www.wowhead.com/wotlk/quest=10216",image="assets/images/quests/placeholder.png",xpDiff=8,desc="Shaffar's ethereals have completely blocked us out of the Mana-Tombs. Thankfully, I've got a plan. While we can't go in through the front door, there are sure to be several transporters inside.$B$BI want you to clear the way for my crew first and then I want you to activate one of their transporters to teleport us inside.$B$BActivate the teleporter in the chamber right before Shaffar's chambers when the way has been cleared. Don't worry, I'll make it worth your while...",logDesc="Artificer Morphalius wants you to kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers and 5 Ethereal Spellbinders.$B$BOnce that's done, find the Ethereal Transporter in the chamber before Shaffar's and activate it."} end
if not DB[10217] then DB[10217]={id=10217,zoneId=0,name="Fossil Fuel",level=255,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10217",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My Shredder is out of fuel!",logDesc="Test"} end
if not DB[10218] then DB[10218]={id=10218,zoneId=3792,name="Someone Else's Hard Work Pays Off",level=66,minLevel=64,giver="Cryo-Engineer Sha'heen",giverType="NPC",giverId=19671,ender="Nexus-Prince Haramad",enderType="NPC",enderId=19674,wowhead="https://www.wowhead.com/wotlk/quest=10218",image="assets/images/quests/placeholder.png",xpDiff=8,money=105000,desc="Who were you expecting!? That idiot Morphalius was 'de-prioritized.' Now I'm here to clean up his mess. All I need from you is to watch my back as I go through Shaffar's ether gatherers and suck them dry of all that they have collected. If I successfully complete my mission, Haramad himself will reward you!$B$BWhat do you say? Escort me through the Mana-Tombs and then collect some incredible treasure? You already did most of the work anyway! Nothing's alive back behind us, right?",logDesc="Escort Cryo-Engineer Sha'heen safely through the Mana-Tombs so that he can gather the ether held inside Shaffar's ether collectors.$B$BReport to Nexus-Prince Haramad located outside the Mana-Tombs at the Consortium encampment should you succeed.",choiceRewards={{id=29328,qty=1},{id=29327,qty=1},{id=29326,qty=1},{id=29325,qty=1}}} end
if not DB[10219] then DB[10219]={id=10219,zoneId=0,name="Walk the Dog",level=255,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10219",image="assets/images/quests/placeholder.png"} end
if not DB[10220] then DB[10220]={id=10220,zoneId=3483,name="Make Them Listen",level=61,minLevel=58,giver="Emissary Mordiba",giverType="NPC",giverId=19682,ender="Emissary Mordiba",enderType="NPC",enderId=19682,poiX=-1333,poiY=2349,wowhead="https://www.wowhead.com/wotlk/quest=10220",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="I was sent here to make contact with the Unyielding spirits.  These once proud Alliance soldiers were defeated long ago, and now their cursed spirits haunt the ruins to the west.  $B$BIf they would only join us we would gain a powerful ally.  Imagine, a legion of undying warriors to use against our enemies.  But these undead are mad with hatred and will not listen to me.  $B$BPerhaps they can be forced to join us.  ",logDesc="Mordiba wants you to defeat 12 Unyielding Footmen, 8 Unyielding Knights, and 6 Unyielding Sorcerers at the Expedition Armory to the west of Spinebreaker Post."} end
if not DB[10221] then DB[10221]={id=10221,zoneId=3523,name="Dr. Boom!",level=68,minLevel=67,giver="Lead Sapper Blastfizzle",giverType="NPC",giverId=19634,ender="Lead Sapper Blastfizzle",enderType="NPC",enderId=19634,poiX=2923,poiY=3577,wowhead="https://www.wowhead.com/wotlk/quest=10221",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="$N, my former protege, Sparky Uberthruster, wouldn't wear his helmet while down here and one day transformed into the infamous Dr. Boom!$B$BAnd he stole off to the northeast with most of our sapping equipment!  He and his Boom Bots have been a menace to Area 52 ever since.$B$BI need you to go to his Camp of Boom just outside of town and put an end to him!  Use these Boom's Doom bombs to take him out.$B$BAnd make sure not to get too close to him or his Boom Bots!",logDesc="Kill Dr. Boom and return with the good news to Lead Sapper Blastfizzle at Area 52 in the Netherstorm.",choiceRewards={{id=29969,qty=1},{id=29968,qty=1},{id=29967,qty=1},{id=30514,qty=1}}} end
if not DB[10222] then DB[10222]={id=10222,zoneId=3523,name="The Sunfury Garrison",level=69,minLevel=67,giver="Custodian Dieworth",giverType="NPC",giverId=19488,ender="Custodian Dieworth",enderType="NPC",enderId=19488,rewardNextId=10223,poiX=2247,poiY=2277,wowhead="https://www.wowhead.com/wotlk/quest=10222",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="After Prince Kael'thas's forces destroyed the village and imprisoned the archmage in the Violet Tower, they withdrew to Sunfury Hold to the northeast. The very men who destroyed our village and slew our fellows toast their 'amazing victory' while we are helpless to avenge the fallen.$B$BWe must not allow these crimes to go unanswered! Be the instrument of our vengeance, $N. Go to Sunfury Hold and claim the lives of those responsible for this crime.",logDesc="Custodian Dieworth at Kirin'Var Village wants you to kill 10 Sunfury Archers."} end
if not DB[10223] then DB[10223]={id=10223,zoneId=3523,name="Down With Daellis",level=69,minLevel=67,giver="Custodian Dieworth",giverType="NPC",giverId=19488,ender="Custodian Dieworth",enderType="NPC",enderId=19488,poiX=2247,poiY=2277,wowhead="https://www.wowhead.com/wotlk/quest=10223",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="I'll never forget the blood elf who led the attack. He wore a tabard with a device I've never seen before, over top of crimson armor.$B$BHe was ferocious and merciless, leading from the front where most other blood elf officers would never be seen. He was responsible for the deaths of many Kirin Tor mages that day, but he didn't linger long at Sunfury Hold. Kael'thas has ordered him to Manaforge Duro to aid in their attempt to control the area. Find him, $N, and silence his bow for good.",logDesc="Custodian Dieworth at Kirin'Var Village wants you to kill Master Daellis Dawnstrike.",choiceRewards={{id=29792,qty=1},{id=29793,qty=1},{id=30399,qty=1},{id=29794,qty=1}}} end
if not DB[10224] then DB[10224]={id=10224,zoneId=3523,name="Essence for the Engines",level=68,minLevel=67,giver="Chief Engineer Trep",giverType="NPC",giverId=19709,ender="Chief Engineer Trep",enderType="NPC",enderId=19709,rewardNextId=10226,poiX=2974,poiY=3675,wowhead="https://www.wowhead.com/wotlk/quest=10224",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="As the X-52's chief of engineering, I have to see to it that the nether-rocket's main engines are in tip-top shape.$B$BUnfortunately, I haven't built them yet.$B$B$C, I'm in dire straits here!  I have almost all of the parts.  All that I'm missing is the engine core.$B$BLuckily for us, I think we can make use of the essence from the local mana wraiths to jump-start the engines.$B$BThey can be found near most of the glowing trenches in the northern part of the island.  Except for here in Area 52, of course.",logDesc="Collect 7 Mana Wraith Essences and return them to Chief Engineer Trep at Area 52 in the Netherstorm."} end
if not DB[10225] then DB[10225]={id=10225,zoneId=3523,name="Report to Engineering",level=68,minLevel=67,giver="Rocket-Chief Fuselage",giverType="NPC",giverId=19570,ender="Chief Engineer Trep",enderType="NPC",enderId=19709,rewardNextId=10224,poiX=3042,poiY=3659,wowhead="https://www.wowhead.com/wotlk/quest=10225",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N!  I need you to take all of these etherlithium crystals over to Chief Engineer Trep, my, uh, chief of engineering.$B$BHe should know what to do with them.  And if he doesn't, you see to it that he finds out!",logDesc="Deliver the Etherlithium Matrix Crystals to Chief Engineer Trep at Area 52 in the Netherstorm."} end
if not DB[10226] then DB[10226]={id=10226,zoneId=3523,name="Elemental Power Extraction",level=68,minLevel=67,giver="Chief Engineer Trep",giverType="NPC",giverId=19709,ender="Chief Engineer Trep",enderType="NPC",enderId=19709,poiX=2974,poiY=3675,wowhead="https://www.wowhead.com/wotlk/quest=10226",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Darn it, that didn't do it!$B$BOk, I've got another idea!  I had Xyrol whip up an elemental power extractor.  I'm not certain exactly what this power will do, but I know that I can use it.$B$BThe sundered rumblers and warp aberrations on the ledge of the Crumbling Wastes to the south have just what I need for the engines!$B$BThe extractor will change the form of their power into something solid that you'll be able to gather up after you've defeated them.",logDesc="Extract 5 Elemental Power for Chief Engineer Trep at Area 52 in the Netherstorm.",choiceRewards={{id=30264,qty=1},{id=30263,qty=1},{id=30262,qty=1},{id=30516,qty=1}}} end
if not DB[10227] then DB[10227]={id=10227,zoneId=3688,name="I See Dead Draenei",level=67,minLevel=64,giver="Ha'lei",giverType="NPC",giverId=19697,ender="Ramdor the Mad",enderType="NPC",enderId=19417,rewardNextId=10228,poiX=-3343,poiY=5188,wowhead="https://www.wowhead.com/wotlk/quest=10227",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I see dead draenei. They're all around us.$B$BBah, nobody believes me because I'm a child. Not even my own mommy believes me.$B$B<Ha'lei points to Ramdor.>$B$BHe believes me, though... He sees them too. Boy does he get angry about it!$B$BIt's kind of funny. I see ghosts and people just smile and pat me on the head, trying to placate me. Ramdor sees ghosts and people label him as crazy. I sure hope I never grow up!$B$BYou should probably talk to Ramdor before you go inside. He was once a death priest.",logDesc="Speak to Ramdor the Mad, standing on the bone pile outside of the Auchenai Crypts."} end
if not DB[10228] then DB[10228]={id=10228,zoneId=3688,name="Ezekiel",level=67,minLevel=64,giver="Ramdor the Mad",giverType="NPC",giverId=19417,ender="Ezekiel",enderType="NPC",enderId=19715,rewardNextId=10231,poiX=-3385,poiY=5185,wowhead="https://www.wowhead.com/wotlk/quest=10228",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I believe that the dead, which we have been caring for these last 500 odd years, should be left alone. Maladaar has other plans. He has retreated to the Crypt of Remembrance to start his experiments... Necromancy.$B$BI hope you weren't thinking about going in there... Not before helping me out so that these damned spirits will finally leave me alone. I know where they keep their treasures, $r. Got your attention, eh?$B$BBring me the book of the dead, held by the Aldor, Ezekiel of Shattrath.$B",logDesc="Find and speak with Ezekiel of Shattrath in Shattrath City."} end
if not DB[10229] then DB[10229]={id=10229,zoneId=3483,name="Decipher the Tome",level=61,minLevel=58,ender="Althen the Historian",enderType="NPC",enderId=19736,rewardNextId=10230,wowhead="https://www.wowhead.com/wotlk/quest=10229",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This tome appears to be some sort of history written in a secret Alliance cipher.  Althen, the historian in Spinebreaker Post, has studied the Unyielding for some time; he may be able to crack the Alliance code and decipher the book.  ",logDesc="Take the Mysterious Tome to Althen the Historian in Spinebreaker Post.  "} end
if not DB[10230] then DB[10230]={id=10230,zoneId=3483,name="The Battle Horn",level=61,minLevel=58,giver="Althen the Historian",giverType="NPC",giverId=19736,ender="Althen the Historian",enderType="NPC",enderId=19736,rewardNextId=10250,poiX=-1335,poiY=2351,wowhead="https://www.wowhead.com/wotlk/quest=10230",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Perhaps we have taken the wrong approach to the Unyielding? $B$BThe tome tells me the Expedition Armory was destroyed by orcs and death knights long ago.  The Unyielding remain here as vengeful spirits trapped in an eternal battle against the fel orc clans.  $B$BThey think only of revenge.  We must arrange for them to defeat their most hated enemies.  Enter the Expedition Armory once again and find Lieutenant Commander Thalvos.  He carries a battle horn that can summon the Unyielding.  Bring it to me.  ",logDesc="Take the Unyielding Battle Horn from Lieutenant Commander Thalvos and bring it to Althen the Historian in Spinebreaker Post."} end
if not DB[10231] then DB[10231]={id=10231,zoneId=3703,name="What Book? I Don't See Any Book.",level=67,minLevel=64,giver="Ezekiel",giverType="NPC",giverId=19715,ender="\"Dirty\" Larry",enderType="NPC",enderId=19720,rewardNextId=10251,poiX=-1787,poiY=5494,wowhead="https://www.wowhead.com/wotlk/quest=10231",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Ramdor? Hrm, let me think... Ramdor... Oh yes, the death priest. What does he want with the book? Well it doesn't matter. Yes I lied to you and no I don't have the book. Not anymore, anyway. It was stolen. Probably by one of those filthy refugees.$B$BBesides, Auchindoun is now defunct. We have no use for the book. If you find it, you can keep it.$B$BLike I said, I saw some of those ruffians snooping around the terrace last week. Start your search with them. They're probably playing dice in the slums.",logDesc="Ezekiel said the book has been stolen. Your best bet is to find the Ruffians and see if they have any information.$B"} end
if not DB[10232] then DB[10232]={id=10232,zoneId=3523,name="In A Scrap With The Legion",level=69,minLevel=67,giver="Papa Wheeler",giverType="NPC",giverId=19645,ender="Papa Wheeler",enderType="NPC",enderId=19645,poiX=3053,poiY=3644,wowhead="https://www.wowhead.com/wotlk/quest=10232",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The Burning Legion has moved in on our claim at the Scrap Field down the path and across the bridge to the east.$B$BThis could be a huge problem for us!  With the Legion at the Arklon Ruins, and now there, it's starting to look bad for us - and the rocket project - here at Area 52.$B$B$N, I need you to go out there and deal with those demons!  I'd do it, but I'm a lover, not a fighter.$B$BYep, this is going to be trouble, I can feel it!",logDesc="Kill 5 Mo'arg Doomsmiths and 15 Gan'arg Engineers.  Then return to Papa Wheeler at Area 52 in the Netherstorm."} end
if not DB[10233] then DB[10233]={id=10233,zoneId=3523,name="Torching Sunfury Hold",level=69,minLevel=67,giver="Lieutenant-Sorcerer Morran",giverType="NPC",giverId=19489,ender="Lieutenant-Sorcerer Morran",enderType="NPC",enderId=19489,poiX=2249,poiY=2273,wowhead="https://www.wowhead.com/wotlk/quest=10233",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Ridding Sunfury Hold of its garrison is not sufficient to keep the blood elves from reoccupying it. Kael'thas's followers are zealous and tenacious. Leaving them anything to use at Sunfury is effectively an invitation to return.$B$BNo, it must all be destroyed. See to it that their tents and artillery burn to ashes!$B$B<The ghost's fists clench.>$B$BSteal torches from the Sunfury flamekeepers to accomplish your task, $N.",logDesc="Using a Flaming Torch, destroy 4 Sunfury Ballistas and 4 Sunfury Tents and return to Lieutenant-Sorcerer Morran at Kirin'Var Village."} end
if not DB[10234] then DB[10234]={id=10234,zoneId=3523,name="One Demon's Trash...",level=69,minLevel=67,giver="Mama Wheeler",giverType="NPC",giverId=19728,ender="Mama Wheeler",enderType="NPC",enderId=19728,rewardNextId=10235,poiX=3355,poiY=2883,wowhead="https://www.wowhead.com/wotlk/quest=10234",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="You look like a capable young $g man: woman;!  I was wondering if you could lend me a hand?$B$BTo the east is the Scrap Field, which the Burning Legion has moved into.  It's full of huge fel reaver parts.  There're also a whole bunch of smaller parts in there that they don't seem to care about.$B$BI want you to get in there and get me a lot of those smaller fel reaver parts!",logDesc="Gather 10 Fel Reaver Parts and return them to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm."} end
if not DB[10235] then DB[10235]={id=10235,zoneId=3523,name="Declawing Doomclaw",level=69,minLevel=67,giver="Mama Wheeler",giverType="NPC",giverId=19728,ender="Mama Wheeler",enderType="NPC",enderId=19728,rewardNextId=10237,poiX=3355,poiY=2883,wowhead="https://www.wowhead.com/wotlk/quest=10235",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="You know what might just discourage them?  Take out their leader!$B$BIt seems to work everywhere else from what I've heard.  And when they see a $g grizzled : tough; $c, such as yourself take out their leader... why, I bet they'll tuck tail and run for the hills!$B$BGet back in there and take out the big one they call Doomclaw.  I hear he keeps himself in the eastern part of the Scrap Field underneath the pipe.$B$BBring me his claw, too!  Maybe we can make use of it.",logDesc="Obtain Doomclaw's Hand and deliver it to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.",choiceRewards={{id=30279,qty=1},{id=30278,qty=1},{id=30277,qty=1}}} end
if not DB[10236] then DB[10236]={id=10236,zoneId=3483,name="Outland Sucks!",level=61,minLevel=58,giver="Foreman Razelcraz",giverType="NPC",giverId=16915,ender="Foreman Razelcraz",enderType="NPC",enderId=16915,rewardNextId=10238,poiX=430,poiY=2887,wowhead="https://www.wowhead.com/wotlk/quest=10236",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="I can't believe I left Booty Bay to come to Outland.  My cousin Screed Luckheed promised me I would make a fortune, but instead he flew off in his zeppelin and left me here to try to scrape a living out of this mine.  $B$BHow am I suppose to make a living here with helboars and demons and fel orcs attacking all the time?  My shredder here was broken yesterday and the parts I need to fix it were stolen by fel orcs.  They took the parts into the fissure to the southwest and may have dropped them there.",logDesc="Find 6 Shredder Parts and return to Foreman Razelcraz by the mine northwest of Thrallmar.",rewards={{id=23424,qty=5}}} end
if not DB[10237] then DB[10237]={id=10237,zoneId=3523,name="Warn Area 52!",level=69,minLevel=67,giver="Mama Wheeler",giverType="NPC",giverId=19728,ender="Rocket-Chief Fuselage",enderType="NPC",enderId=19570,rewardNextId=10247,poiX=3355,poiY=2883,wowhead="https://www.wowhead.com/wotlk/quest=10237",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, you have to get word back to Area 52 immediately!  Hurry!$B$BTell the rocket-chief that the Burning Legion is after us now!",logDesc="Deliver the bad news to Rocket-Chief Fuselage at Area 52 in the Netherstorm."} end
if not DB[10238] then DB[10238]={id=10238,zoneId=3483,name="How to Serve Goblins",level=61,minLevel=58,giver="Foreman Razelcraz",giverType="NPC",giverId=16915,ender="Foreman Razelcraz",enderType="NPC",enderId=16915,rewardNextId=10629,poiX=430,poiY=2887,wowhead="https://www.wowhead.com/wotlk/quest=10238",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Why would fel orcs steal my shredder parts?  I hate them so much.  They just sneak into my camp here and take things all the time.  A couple of days ago they stole three of my peons!  Now the rest of my peons have run off because they are afraid they are going to be eaten by fel orcs.  $B$BI can't run a mine without peons.  If you could save the peons that I lost maybe the others would come back.  The fel orcs have their camps along the wall to the southwest.",logDesc="Rescue Manni, Moh and Jakk from the Fel Orc camps and return to Foreman Razelcraz by the mine northwest of Thrallmar.",rewards={{id=30858,qty=5}}} end
if not DB[10239] then DB[10239]={id=10239,zoneId=3523,name="Potential Energy Source",level=69,minLevel=67,giver="Lieutenant-Sorcerer Morran",giverType="NPC",giverId=19489,ender="Lieutenant-Sorcerer Morran",enderType="NPC",enderId=19489,rewardNextId=10240,poiX=2249,poiY=2273,wowhead="https://www.wowhead.com/wotlk/quest=10239",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="We are not the only ones battling the influx of the mana beings. The blood elves, too, are troubled by them, but I'm not sure why.$B$BWhatever they're involved in over there, they don't seem to be stopping. Instead, I've seen them employ a variety of methods to kill the creatures. The most effective involves magical defenses fueled by some sort of concentrated energy.$B$BCapture some of these energy sources and bring them to me. Don't hesitate to stymie the elves if an opportunity presents itself.",logDesc="Lieutenant-Sorcerer Morran at Kirin'Var Village wants you to capture 10 Energy Isolation Cubes from the blood elf operations at Manaforge Coruu."} end
if not DB[10240] then DB[10240]={id=10240,zoneId=3523,name="Building a Perimeter",level=69,minLevel=67,giver="Lieutenant-Sorcerer Morran",giverType="NPC",giverId=19489,ender="Lieutenant-Sorcerer Morran",enderType="NPC",enderId=19489,poiX=2249,poiY=2273,wowhead="https://www.wowhead.com/wotlk/quest=10240",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="We are prepared to try to construct a perimeter around the village using the energy source taken from the blood elves. I can't guarantee that it will work, but we have to attempt it.$B$BOtherwise, the mana creatures will surely continue devouring the spirits of the fallen Kirin Tor.$B$BUse this device at the small runes around the perimeter of town to release the energy there. If I've woven the field correctly, we should start noticing a difference once you've used the device at each point.",logDesc="Use the Rune Activation Device near the East Rune, Northeast Rune, and West Rune. The runes can be found around the perimeter of Kirin'Var Village's Wizard Row and Town Square districts. Return to Lieutenant-Sorcerer Morran once you've completed the task.",choiceRewards={{id=29785,qty=1},{id=29784,qty=1},{id=29786,qty=1},{id=30398,qty=1}}} end
if not DB[10241] then DB[10241]={id=10241,zoneId=3523,name="Distraction at Manaforge B'naar",level=68,minLevel=67,giver="Exarch Orelis",giverType="NPC",giverId=19466,ender="Exarch Orelis",enderType="NPC",enderId=19466,rewardNextId=10313,poiX=3071,poiY=3695,wowhead="https://www.wowhead.com/wotlk/quest=10241",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="We were sent here by the Sha'tar to investigate the manaforges that Kael'thas' army is operating here.  Unfortunately, the Scryers threaten to renege on their information-gathering duties unless we support them with military action.$B$BWe can't afford to compromise this mission over politics, so we've agreed to weaken the manaforge's defenses so that the Scryers can do their work.$B$BProve your loyalty to the Aldor and slay the Sunfury magisters and bloodwarders that guard Manaforge B'naar.",logDesc="Slay 8 Sunfury Magisters and 8 Sunfury Bloodwarders and return to Exarch Orelis at Area 52.$B$BCompleting quests for the Aldor will cause your Scryers reputation to decrease."} end
if not DB[10242] then DB[10242]={id=10242,zoneId=3483,name="Spinebreaker Post",level=60,minLevel=58,giver="Apothecary Zelana",giverType="NPC",giverId=21257,ender="Apothecary Albreck",enderType="NPC",enderId=21279,poiX=37,poiY=2122,wowhead="https://www.wowhead.com/wotlk/quest=10242",image="assets/images/quests/placeholder.png",xpDiff=2,money=2300,desc="$n, my equipment here is, unfortunately, not configured for all the tests I'd like to perform.  However, my colleague at Spinebreaker Post, Apothecary Albreck, possesses the required implements.$B$BI have acquired a sample of Bleeding Hollow blood -- gained from a past mission of Thrallmar's agents.  Take the sample to Albreck and allow him to study it.$B$BTo reach Spinebreaker Post, speak with Wing Commander Brack, near the wyverns to the south.",logDesc="Apothecary Zelana at Reaver's Fall wants you to speak with Wing Commander Brack to take a wyvern to Spinebreaker Post, and then bring the Bleeding Hollow Blood Sample to Apothecary Albreck at Spinebreaker Post.  "} end
if not DB[10243] then DB[10243]={id=10243,zoneId=3523,name="Naaru Technology",level=68,minLevel=67,giver="Anchorite Karja",giverType="NPC",giverId=19467,rewardNextId=10245,poiX=3071,poiY=3697,wowhead="https://www.wowhead.com/wotlk/quest=10243",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Scryers obtained a personnel roster for Manaforge B'naar and are now having a field day picking out assassination targets.$B$BThey've missed one small bit of information, scribbled on the side of the roster.  It appeared to be a password or code like those used to access naaru-made technology like the Exodar or Tempest Keep.$B$BGo inside the manaforge and look for a control panel.  Copy its readouts on this scroll as well as you can.  We must confirm our suspicions about the origin of the technology.",logDesc="Go inside Manaforge B'naar and find the B'naar Control Console.$B$BCompleting quests for the Aldor will cause your Scryers reputation to decrease."} end
if not DB[10244] then DB[10244]={id=10244,zoneId=3523,name="R.T.F.R.C.M.",level=69,minLevel=67,rewardNextId=10237,wowhead="https://www.wowhead.com/wotlk/quest=10244",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Cracking the seal on this rather large tome, you can't quite make out what the words say.  They appear to be written in the language of demons.$B$BHowever, you can make out the pictures, which tell their own story.$B$BThis is clearly a fel reaver construction manual, and you know for a fact that Mama Wheeler will want to take a look at it!",logDesc="Take the Fel Reaver Construction Manual to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm."} end
if not DB[10245] then DB[10245]={id=10245,zoneId=3523,name="B'naar Console Transcription",level=68,minLevel=67,ender="Anchorite Karja",enderType="NPC",enderId=19467,rewardNextId=10299,wowhead="https://www.wowhead.com/wotlk/quest=10245",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="You try to transcribe the shapes as you see them flash across your eyes.  The results are less than exact, but should serve as adequate evidence to prove or disprove the Aldor's suspicions.",logDesc="Deliver the B'naar Console Transcription to Anchorite Karja at Area 52 in Netherstorm.$B$BCompleting quests for the Aldor will cause your Scryers reputation to decrease."} end
if not DB[10246] then DB[10246]={id=10246,zoneId=3523,name="Attack on Manaforge Coruu",level=68,minLevel=67,giver="Exarch Orelis",giverType="NPC",giverId=19466,ender="Exarch Orelis",enderType="NPC",enderId=19466,poiX=3071,poiY=3695,wowhead="https://www.wowhead.com/wotlk/quest=10246",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Your success at Manaforge B'naar was quite noteworthy.  I'm sure that Anchorite Karja will ask you for a repeat performance at Manaforge Coruu next.$B$BWe've learned of a particularly important regiment of Sunfury arcanists and researchers being deployed there and I would like you to target them.  Succeed and you will deliver a crushing blow against our enemy's forces.",logDesc="Travel to Manaforge Coruu and slay 8 Sunfury Arcanists and 5 Sunfury Researchers.  Return to Exarch Orelis when you've completed this task.$B$BPerforming quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10247] then DB[10247]={id=10247,zoneId=3523,name="Doctor Vomisa, Ph.T.",level=69,minLevel=67,giver="Rocket-Chief Fuselage",giverType="NPC",giverId=19570,ender="Doctor Vomisa, Ph.T.",enderType="NPC",enderId=19832,rewardNextId=10248,poiX=3042,poiY=3659,wowhead="https://www.wowhead.com/wotlk/quest=10247",image="assets/images/quests/placeholder.png",xpDiff=1,desc="On the outskirts of town to the east are the Proving Grounds.  Our top experimentalist, Doctor Vomisa, has been toying with a combination of fel reaver, ethereal, and of course, goblin technologies there.$B$BThis is in no small part thanks to your gathering efforts Junior Technician 3rd Grade, $N!$B$BGo to him; I know that he'll have a solution for saving Area 52.$B$BAnd since he's likely to use you as a test subject, if I were you, I'd bring some friends along just in case.",logDesc="Speak with Doctor Vomisa, Ph.T. at the Proving Grounds in Netherstorm."} end
if not DB[10248] then DB[10248]={id=10248,zoneId=3523,name="You, Robot",level=69,minLevel=67,giver="Doctor Vomisa, Ph.T.",giverType="NPC",giverId=19832,ender="Doctor Vomisa, Ph.T.",enderType="NPC",enderId=19832,rewardNextId=10249,poiX=3087,poiY=3403,wowhead="https://www.wowhead.com/wotlk/quest=10248",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Doctor Vomisa, Ph.T. at your service.  Here, take this controller.  I want you to activate it and give my newly-invented Scrap Reaver X6000 a spin.$B$BJust stay nearby!  The controller is tied to my console here, and if you get too far away, the robot will cease to function.$B$BTry out everything... I'll be watching and calibrating its servos based upon your test run.",logDesc="Activate the Scrap Reaver X6000 Controller and test out its capabilities.  Then give your feedback to Doctor Vomisa, Ph.T at the Proving Grounds in the Netherstorm.  Deal with any problems that arise."} end
if not DB[10249] then DB[10249]={id=10249,zoneId=3523,name="Back to the Chief!",level=69,minLevel=67,giver="Doctor Vomisa, Ph.T.",giverType="NPC",giverId=19832,ender="Rocket-Chief Fuselage",enderType="NPC",enderId=19570,poiX=3087,poiY=3403,wowhead="https://www.wowhead.com/wotlk/quest=10249",image="assets/images/quests/placeholder.png",xpDiff=7,money=123000,desc="I'm certain that the rocket-chief is going to want to have a word or two with you!$B$BIf I were you, I wouldn't hesitate to get back to Area 52 and speak with him!",logDesc="Report to Rocket-Chief Fuselage at Area 52 in the Netherstorm immediately!",rewards={{id=30847,qty=1}},choiceRewards={{id=30019,qty=1},{id=30016,qty=1},{id=30014,qty=1}}} end
if not DB[10250] then DB[10250]={id=10250,zoneId=3483,name="Bloody Vengeance",level=61,minLevel=58,giver="Althen the Historian",giverType="NPC",giverId=19736,ender="Althen the Historian",enderType="NPC",enderId=19736,rewardNextId=10258,poiX=-1335,poiY=2351,wowhead="https://www.wowhead.com/wotlk/quest=10250",image="assets/images/quests/placeholder.png",xpDiff=5,desc="East of here is an old destroyed Alliance siege tower.  Now scavengers loot it for old nails and bits of scrap.  Long ago, many Alliance warriors lost their lives at this tower and their banner was captured by Urtrak, a foul orc commander.$B$BBlow the Unyielding battle horn near the Alliance banner.  This will get the attention of Urtrak.  It may also summon forth warriors who fell in battle long ago.",logDesc="Blow the Unyielding Battle Horn near the Alliance Banner.  Kill Urtrak and then return to Althen the Historian at Spinebreaker Post."} end
if not DB[10251] then DB[10251]={id=10251,zoneId=3518,name="The Master's Grand Design?",level=67,minLevel=64,giver="\"Dirty\" Larry",giverType="NPC",giverId=19720,ender="Nitrin the Learned",enderType="NPC",enderId=19844,rewardNextId=10252,poiX=-1733,poiY=5565,wowhead="https://www.wowhead.com/wotlk/quest=10251",image="assets/images/quests/placeholder.png",xpDiff=3,desc="A couple of draenei paid us a visit last night. They'd somehow learned that we had the book in our possession and made a very generous offer to \"take it off our hands.\"$B$BWe didn't ask them what they wanted with the book but the young one kept talking about \"the master's grand design,\" whatever that means.$B$BLook, I don't ask questions when money is in play. They gave us a lot of gold and we gave them the book.$B$BHe said that they lived in Nagrand - in the old Abandoned Armory, north of Telaar.",logDesc="Find Nitrin the Learned at the Abandoned Armory in Nagrand."} end
if not DB[10252] then DB[10252]={id=10252,zoneId=3518,name="Vision of the Dead",level=67,minLevel=64,giver="Nitrin the Learned",giverType="NPC",giverId=19844,ender="Nitrin the Learned",enderType="NPC",enderId=19844,rewardNextId=10253,poiX=-2052,poiY=7433,wowhead="https://www.wowhead.com/wotlk/quest=10252",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It has already begun. Levixus stands atop the ruins of Auchindoun and reads from the book of the dead. He calls the dead out by name and, through demonic ritual, binds the tortured souls to his will. He will raise all of Auchindoun if given the chance!$B$BBut... you must first prepare. You cannot do battle with that which you cannot see.$B$B<Nitrin hands you a parchment.>$B$BBring me the items I require to brew the tincture. It will open your mind and allow you to see into the spirit world.",logDesc="Nitrin at the Abandoned Armory in Nagrand wants you to bring him 1 Mountain Gronn Eyeball, 1 Flawless Greater Windroc Beak, and 1 Aged Clefthoof Blubber."} end
if not DB[10253] then DB[10253]={id=10253,zoneId=3688,name="Levixus the Soul Caller",level=67,minLevel=64,giver="Nitrin the Learned",giverType="NPC",giverId=19844,ender="Ramdor the Mad",enderType="NPC",enderId=19417,poiX=-2052,poiY=7433,wowhead="https://www.wowhead.com/wotlk/quest=10253",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Go now, $N. You will find Levixus on the uppermost ruins of Auchindoun. Enter there from the southern reaches of the Bone Wastes. He stands amidst a storm of souls...$B$BDestroy him and take the book of the dead. Once you have the cursed book in your possession, destroy it! Destroy it so that such an atrocity can never again be made possible.",logDesc="Destroy Levixus and take the Book of the Dead from his possession.$B$BDeliver the Book of the Dead to Ramdor the Mad standing outside the Auchenai Crypt entrance of Auchindoun.$B$BYou had a deal, remember?",choiceRewards={{id=29312,qty=1},{id=29313,qty=1},{id=29315,qty=1},{id=29314,qty=1}}} end
if not DB[10254] then DB[10254]={id=10254,zoneId=3483,name="Force Commander Danath",level=60,minLevel=55,giver="Marshal Isildor",giverType="NPC",giverId=19308,ender="Force Commander Danath Trollbane",enderType="NPC",enderId=16819,poiX=-681,poiY=2709,wowhead="https://www.wowhead.com/wotlk/quest=10254",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Marshal Isildor spits in the dust.>$B$BWell, time to earn your pay. Report at once to Force Commander Trollbane within the keep. He and his advisors will no doubt be heartened to see you.$B$B<Marshal Isildor salutes you stoically.>$B$BFor the Alliance!",logDesc="Marshal Isildor wants you to report to Force Commander Danath Trollbane in Honor Hold."} end
if not DB[10255] then DB[10255]={id=10255,zoneId=3483,name="Testing the Antidote",level=63,minLevel=61,giver="Thiah Redmane",giverType="NPC",giverId=16991,ender="Thiah Redmane",enderType="NPC",enderId=16991,poiX=-312,poiY=4729,wowhead="https://www.wowhead.com/wotlk/quest=10255",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="I think there's something we can use in the blood as the base of an antidote. Don't look at me like I've lost my mind!$B$BIt's a common theme in nature. Often, the cure for something can be derived from the toxin itself. That's just what I aim to do.$B$BRidding the boars of their demonic influence would probably eliminate their aggression and give us insight into how to best attempt to help other species.",logDesc="Use the Cenarion Antidote on a Hulking Helboar and observe the results. Once you have the results of the experiment, return to Thiah Redmane at the Cenarion Post in Hellfire Peninsula.",choiceRewards={{id=25986,qty=1},{id=25987,qty=1},{id=25985,qty=1}}} end
if not DB[10256] then DB[10256]={id=10256,zoneId=3523,name="Finding the Keymaster",level=69,minLevel=67,giver="Archmage Vargoth",giverType="NPC",giverId=19481,ender="Archmage Vargoth",enderType="NPC",enderId=19481,rewardNextId=10257,poiX=2245,poiY=2231,wowhead="https://www.wowhead.com/wotlk/quest=10256",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="In retrospect, I suppose I should've expected Kael'thas's magic to be this robust. He's always been a talented mage, but I've never seen anything like the power he wielded during the attack on the tower.$B$BThe ward keeps me from being able to scry out the force holding it in place, but it doesn't preclude you from scrying.$B$BYou'll require a focus, though. A crystal-bearing giant named Apex roams the plains to the west of Manaforge Duro. One of its crystals would make an excellent scrying focus.",logDesc="Locate Apex and obtain Apex's Crystal Focus from him. Return to the Violet Tower and use Apex's Crystal Focus near Archmage Vargoth's Orb to discover who holds the key to breaking the tower's curse."} end
if not DB[10257] then DB[10257]={id=10257,zoneId=3523,name="Capturing the Keystone",level=70,minLevel=67,giver="Archmage Vargoth",giverType="NPC",giverId=19481,ender="Archmage Vargoth",enderType="NPC",enderId=19481,poiX=2245,poiY=2231,wowhead="https://www.wowhead.com/wotlk/quest=10257",image="assets/images/quests/placeholder.png",xpDiff=8,money=132000,desc="It doesn't surprise me that Kael'thas has put the key to this ward in the hands of someone like Commander Sarannis. Prince Kael'thas is a great many things, but he is no simpleton.$B$BIn order to break this curse once and for all, you must enter Tempest Keep and claim the keystone.$B$BOnly once the keystone has been destroyed will I regain my freedom.",logDesc="Venture into Tempest Keep's Botanica and retrieve the Keystone from Commander Sarannis. Bring it to Archmage Vargoth at the Violet Tower."} end
if not DB[10258] then DB[10258]={id=10258,zoneId=3483,name="Honor the Fallen",level=61,minLevel=58,giver="Althen the Historian",giverType="NPC",giverId=19736,ender="Commander Hogarth",enderType="NPC",enderId=19937,poiX=-1335,poiY=2351,wowhead="https://www.wowhead.com/wotlk/quest=10258",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hogarth, the commander of the Armory, is in the eastern tower.  You must report your victory over Urtrak to him.  Perhaps he will be friendly?  Of course he may try to consume your soul.  One can never tell with spirits such as these. $B$BThe Unyielding are still against us and will no doubt kill you if they can.  Be careful $N.  ",logDesc="Report to Commander Hogarth in the Expedition Armory.  ",choiceRewards={{id=29108,qty=1},{id=29109,qty=1}}} end
if not DB[10259] then DB[10259]={id=10259,zoneId=4,name="Into the Breach",level=60,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=10259",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="Battle rages non-stop at the portal!  The Argent Dawn is fighting a desperate fight -- and if we lose, then there will be no end to the demon's fire.$B$BHelp us, $N.  Enter the breach and lend aid to our brothers and sisters.  Help stem this tide of darkness!  The Argent Dawn -- and the world -- needs you!",logDesc="Kill 6 Invading Felguards and then return to Argent Emissary Proudwell.",rewards={{id=28788,qty=1}}} end
if not DB[10260] then DB[10260]={id=10260,zoneId=3523,name="Netherologist Coppernickels",level=68,minLevel=67,rewardNextId=10183,wowhead="https://www.wowhead.com/wotlk/quest=10260",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You must have crossed the main bridge into Netherstorm from Blade's Edge.  Did you see Netherologist Coppernickels working with all of his crazy equipment there?$B$BStrange... I've been expecting a report from him and it's overdue.  He's probably forgotten.  You know those 'science' types.$B$BHead back out to the bridge and pin him down.  Don't accept any of his excuses, just get me that report.$B$BThanks!",logDesc="Speak with Netherologist Coppernickels at the bridge leading into the Netherstorm from Blade's Edge."} end
if not DB[10261] then DB[10261]={id=10261,zoneId=3523,name="Wanted: Annihilator Servo!",level=68,minLevel=67,ender="Papa Wheeler",enderType="NPC",enderId=19645,wowhead="https://www.wowhead.com/wotlk/quest=10261",image="assets/images/quests/placeholder.png",xpDiff=5,money=78000,desc="WANTED:  1 Annihilator Servo to replace the failing one in my Long Neck Spectrum Analyzer.$B$BYou and your friends might want to check with the blood elves at Manaforge B'naar to the west to see if they have any spares.  They seem to have a few arcane annihilators roaming about.$B$BPlease deliver the servo in pristine condition to Papa Wheeler at Area 52.",logDesc="Obtain an Annihilator Servo and deliver it to Papa Wheeler at Area 52 in the Netherstorm.",choiceRewards={{id=30295,qty=1},{id=30296,qty=1},{id=30294,qty=1}}} end
if not DB[10262] then DB[10262]={id=10262,zoneId=3523,name="A Heap of Ethereals",level=68,minLevel=67,giver="Nether-Stalker Khay'ji",giverType="NPC",giverId=19880,ender="Nether-Stalker Khay'ji",enderType="NPC",enderId=19880,poiX=3070,poiY=3675,wowhead="https://www.wowhead.com/wotlk/quest=10262",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="There is something else that I want your help with.$B$BA group of ethereals, known as the Zaxxis, have cut their relationship with the Consortium and gone into business for themselves.  They've even cut deals with the Sunfury blood elves.  This will not be tolerated!$B$BI infiltrated their group at the Heap to the south.  But after I took out their leader, I had to escape here to Area 52.$B$B$C, go down there and bring back their insignias.  Of course, not all wear them because they're cowards.",logDesc="Collect 10 Zaxxis Insignias and return them to Nether-Stalker Khay'ji at Area 52 in the Netherstorm."} end
if not DB[10263] then DB[10263]={id=10263,zoneId=3523,name="Assisting the Consortium",level=68,minLevel=67,giver="Anchorite Karja",giverType="NPC",giverId=19467,ender="Nether-Stalker Khay'ji",enderType="NPC",enderId=19880,rewardNextId=10265,poiX=3071,poiY=3697,wowhead="https://www.wowhead.com/wotlk/quest=10263",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The naaru of Shattrath City have been trying to find a means to bring the Consortium over to their way of seeing things.$B$BLuck would have it that the business relationship between the ethereals and the blood elves of the Netherstorm has recently soured.$B$BThere's a Consortium representative in town named Nether-Stalker Khay'ji who recently ran into trouble with a pack of renegade ethereals.  As a representative of the Aldor, I would like for you to help him in any way that you can.",logDesc="Speak with Nether-Stalker Khay'ji at Area 52 in the Netherstorm."} end
if not DB[10264] then DB[10264]={id=10264,zoneId=3523,name="Assisting the Consortium",level=68,minLevel=67,giver="Spymaster Thalodien",giverType="NPC",giverId=19468,ender="Nether-Stalker Khay'ji",enderType="NPC",enderId=19880,rewardNextId=10265,poiX=3075,poiY=3699,wowhead="https://www.wowhead.com/wotlk/quest=10264",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The naaru of Shattrath City have been trying to find a means to bring the Consortium over to their way of seeing things.$B$BLuck would have it that the business relationship between the ethereals and the blood elves of the Netherstorm has recently soured.$B$BThere's a Consortium representative in town named Nether-Stalker Khay'ji who recently ran into trouble with a pack of renegade ethereals.  As a representative of the Scryers, I would like for you to help him in any way that you can.",logDesc="Speak with Nether-Stalker Khay'ji at Area 52 in the Netherstorm."} end
if not DB[10265] then DB[10265]={id=10265,zoneId=3523,name="Consortium Crystal Collection",level=69,minLevel=67,giver="Nether-Stalker Khay'ji",giverType="NPC",giverId=19880,ender="Nether-Stalker Khay'ji",enderType="NPC",enderId=19880,rewardNextId=10262,poiX=3070,poiY=3675,wowhead="https://www.wowhead.com/wotlk/quest=10265",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Our leader, Nexus-Prince Haramad, has tasked me with the acquisition of a crystal artifact from the Arklon Ruins to the southeast.$B$BThey're old draenei ruins.  Unfortunately for both myself and the goblins here, the Burning Legion has decided to move in to perform their own excavation.$B$BIf you're willing to help me, go to the ruins and take the crystal artifact from the dreadlord named Pentatharon.",logDesc="Obtain an Arklon Crystal Artifact and return it to Nether-Stalker Khay'ji at Area 52 in the Netherstorm."} end
if not DB[10266] then DB[10266]={id=10266,zoneId=3523,name="Request for Assistance",level=69,minLevel=67,giver="Nether-Stalker Khay'ji",giverType="NPC",giverId=19880,ender="Gahruj",enderType="NPC",enderId=20066,rewardNextId=10267,poiX=3070,poiY=3675,wowhead="https://www.wowhead.com/wotlk/quest=10266",image="assets/images/quests/placeholder.png",xpDiff=2,desc="While you were at the Arklon Ruins, I received a request for assistance from one of our representatives out in the field.  It would appear that the Consortium is having some 'difficulties' in trying to recover property from the blood elves, which they refuse to pay for.$B$BPlease head east out of Area 52 and cross the bridge to the next island over.  You'll find my associate, Gahruj, at the Midrealm Post, just inside of Eco-Dome Midrealm.",logDesc="Seek out and offer your services to Gahruj.  He is located at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm."} end
if not DB[10267] then DB[10267]={id=10267,zoneId=3523,name="Rightful Repossession",level=69,minLevel=67,giver="Gahruj",giverType="NPC",giverId=20066,ender="Gahruj",enderType="NPC",enderId=20066,rewardNextId=10268,poiX=3340,poiY=2882,wowhead="https://www.wowhead.com/wotlk/quest=10267",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Our business relations with the blood elves appear to be at an end.  A few weeks ago a large shipment of surveying equipment was delivered to them at Manaforge Duro.  They have refused to pay for it.$B$B$N, I would ask that you pay the blood elves of Manaforge Duro to the east a visit.  They appear to be having some trouble with an infestation of mana creatures there, so take advantage of their preoccupation.$B$BI care not what happens to them, but I would very much like to see the return of our property.",logDesc="Collect 10 Boxes of Surveying Equipment and return them to Gahruj at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.",choiceRewards={{id=30273,qty=1},{id=30272,qty=1},{id=30271,qty=1}}} end
if not DB[10268] then DB[10268]={id=10268,zoneId=3523,name="An Audience with the Prince",level=69,minLevel=67,giver="Gahruj",giverType="NPC",giverId=20066,ender="Image of Nexus-Prince Haramad",enderType="NPC",enderId=20084,rewardNextId=10269,poiX=3340,poiY=2882,wowhead="https://www.wowhead.com/wotlk/quest=10268",image="assets/images/quests/placeholder.png",xpDiff=3,money=21000,desc="Nexus-Prince Haramad has conveyed to me that he is interested in the immediate return of this property to him personally.  I would greatly appreciate if you would deliver it in my stead.$B$BIt is a great honor to gain an audience with the nexus-prince, and I am sure that he would be keenly interested in hearing the tales of your adventures here in the Netherstorm.$B$BSeek out his chamber atop the Stormspire to the north.  He is often present as a holographic image, which you may address.",logDesc="Deliver the Surveying Equipment to the Image of Nexus-Prince Haramad at the Stormspire in the Netherstorm."} end
if not DB[10269] then DB[10269]={id=10269,zoneId=3523,name="Triangulation Point One",level=69,minLevel=67,giver="Image of Nexus-Prince Haramad",giverType="NPC",giverId=20084,ender="Dealer Hazzin",enderType="NPC",enderId=20092,rewardNextId=10275,poiX=4120,poiY=2926,wowhead="https://www.wowhead.com/wotlk/quest=10269",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="There is another reason for the retrieval of the surveying equipment.  There is a crystal from draenei legend of great importance to me.$B$BIt is said that the crystal bestows god-like powers to its bearer!  But it is in danger of being unearthed by others - namely the Burning Legion.$B$B$N, take the equipment and use it to find the first triangulation point.  We know it to be somewhere to the east near Manaforge Ultris.$B$BAfterward, check-in with my agent, Dealer Hazzin, on the Manaforge Ultris island.",logDesc="Use the Triangulation Device to point your way toward the first triangulation point.  Once you have found it, report the location to Dealer Hazzin at the Protectorate Watchpost on the Manaforge Ultris island in the Netherstorm."} end
if not DB[10270] then DB[10270]={id=10270,zoneId=3523,name="A Not-So-Modest Proposal",level=70,minLevel=68,giver="Wind Trader Marid",giverType="NPC",giverId=20071,ender="Image of Wind Trader Marid",enderType="NPC",enderId=20518,rewardNextId=10271,poiX=4280,poiY=2232,wowhead="https://www.wowhead.com/wotlk/quest=10270",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="From the look on your face, I can tell you're a $r who appreciates a good profit.$B$BI've built a reputation as a dealer in exotic goods, and I'm about to launch a new venture.$B$BI need a reliable subcontractor to procure the goods from the Celestial Ridge.$B$BFirst, you'll need to re-energize a teleport pad. There is a spare power pack in Access Shaft Zeon, which is on the south side of Manaforge UItris. The Protectorate is operating in there, so you may be able to follow their tracers to your goal.",logDesc="Retrieve the Teleporter Power Pack and bring it to the Ethereal Teleport Pad on the Celestial Ridge to the east of Manaforge Ultris. Activate the pad and give the Teleporter Power Pack to the Image of Wind Trader Marid so he can install it."} end
if not DB[10271] then DB[10271]={id=10271,zoneId=3523,name="Getting Down to Business",level=70,minLevel=68,giver="Image of Wind Trader Marid",giverType="NPC",giverId=20518,ender="Shrouded Figure",enderType="NPC",enderId=20154,rewardNextId=10281,wowhead="https://www.wowhead.com/wotlk/quest=10271",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="As you've no doubt seen, the area is teeming with nether dragons in various stages of growth. All nether dragons, young and old, contain an essence that's highly desired by K -- err, by a client of mine.$B$BMost people aren't willing to risk their lives to gather it, so we've got the place to ourselves. You can start by gathering the essence from any of the creatures out here, but it's imperative that we start building a supply right away. Return to me once you have the first batch.",logDesc="Gather 8 Nether Dragon Essence, then return to the Ethereal Teleport Pad area. Nether Dragon Essence may be obtained from Nether Drakes or Nether Dragons."} end
if not DB[10272] then DB[10272]={id=10272,zoneId=3523,name="A Promising Start",level=70,minLevel=68,giver="Tyri",giverType="NPC",giverId=20110,ender="Tyri",enderType="NPC",enderId=20110,rewardNextId=10273,poiX=4151,poiY=1513,wowhead="https://www.wowhead.com/wotlk/quest=10272",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="We've come here to investigate rumors of a strange breed of dragons, perhaps even descendents of Deathwing himself. These are clearly not ordinary black dragons, though.$B$BWe'll know more once we've had a chance to examine their eggs. Their hatred for my flight runs deep, so I can't get close enough to gather the eggs. Will you agree to help?",logDesc="Gather 15 Nether Dragonkin Eggs, then return to Tyri and Jorad on the Celestial Ridge."} end
if not DB[10273] then DB[10273]={id=10273,zoneId=3523,name="Troublesome Distractions",level=70,minLevel=68,giver="Tyri",giverType="NPC",giverId=20110,ender="Tyri",enderType="NPC",enderId=20110,rewardNextId=10274,poiX=4151,poiY=1513,wowhead="https://www.wowhead.com/wotlk/quest=10273",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Your former employer, Wind Trader Marid, must've gotten wind that you're helping us now. Through my projection, I've seen his nether-stalkers entering the area, hoping to track us down.$B$BWe've been able to evade them so far, but Marid must be dealt with before the problem grows more severe.$B$BIf your impressions of Marid are correct, he'll do just about anything to secure the supply of his product. Return to him and tell him you're prepared to offer a deal. Lure him away and slay him.",logDesc="Speak with Wind Trader Marid and lure him away from his trading post. Deal with him and then return to Tyri and Jorad on the Celestial Ridge."} end
if not DB[10274] then DB[10274]={id=10274,zoneId=3523,name="Securing the Celestial Ridge",level=70,minLevel=68,giver="Tyri",giverType="NPC",giverId=20110,ender="Tyri",enderType="NPC",enderId=20110,poiX=4151,poiY=1513,wowhead="https://www.wowhead.com/wotlk/quest=10274",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="The nether dragons have the same ferocious temperament as their black dragon forbears, but there is something entirely alien about them. They hatch and mature rapidly, harnessing the strange energies that forged their kind in the destruction of Draenor.$B$BThere is so much more I need to know about them, but I believe the powers may be of use to my own flight. If we can displace the leader of these drakes, Veraku, with a show of dominance, we can cow the rest of them into submission.",logDesc="Use the Challenge of the Blue Flight to provoke Veraku on the southern edge of the Celestial Ridge. Defeat him and return to Tyri and Jorad on the Celestial Ridge.",choiceRewards={{id=29808,qty=1},{id=29810,qty=1},{id=29811,qty=1},{id=29812,qty=1}}} end
if not DB[10275] then DB[10275]={id=10275,zoneId=3523,name="Triangulation Point Two",level=70,minLevel=67,giver="Dealer Hazzin",giverType="NPC",giverId=20092,ender="Wind Trader Tuluman",enderType="NPC",enderId=20112,rewardNextId=10276,poiX=4294,poiY=2230,wowhead="https://www.wowhead.com/wotlk/quest=10275",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="I've recalibrated the triangulation device with the information that you provided from the first point.  You'll use it in exactly the same manner to discover the second.$B$BAll that I can tell you is that the second point is somewhere far to the west.$B$BOnce you've located it, speak with Wind Trader Tuluman; another of the nexus-prince's agents.  He's posing as a weapon merchant at a small trading post next to the bridge, which leads to the island that Manaforge Ara is on.",logDesc="Use the Triangulation Device to point your way toward the second triangulation point.  Once you have found it, report the location to Wind Trader Tuluman at Tuluman's Landing, just on the other side of the bridge from the Manaforge Ara island in the Netherstorm."} end
if not DB[10276] then DB[10276]={id=10276,zoneId=3523,name="Full Triangle",level=70,minLevel=67,giver="Wind Trader Tuluman",giverType="NPC",giverId=20112,ender="Image of Nexus-Prince Haramad",enderType="NPC",enderId=20084,poiX=4046,poiY=3553,wowhead="https://www.wowhead.com/wotlk/quest=10276",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="With the data from both the first and second points, I'm now certain that the crystal is at the top of the Ruins of Farahlon to the northeast.$B$BUnfortunately, the data indicates that the crystal is moving, which means that it has already been discovered, probably by the Burning Legion!$B$BJust in case, I recommend that you take some friends along.$B$BSlay the demon that has the crystal and return it to Nexus-Prince Haramad.",logDesc="Recover the Ata'mal Crystal and deliver it to the Image of Nexus-Prince Haramad at the Stormspire in the Netherstorm."} end
if not DB[10277] then DB[10277]={id=10277,zoneId=1941,name="The Caverns of Time",level=68,minLevel=66,giver="Andormu",giverType="NPC",giverId=20130,ender="Andormu",enderType="NPC",enderId=20130,poiX=-8372,poiY=-4250,wowhead="https://www.wowhead.com/wotlk/quest=10277",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Greetings, $N. Please follow the custodian. She will make things a bit more... clear.",logDesc="Andormu at the Caverns of Time has asked that you follow the Custodian of Time around the cavern."} end
if not DB[10278] then DB[10278]={id=10278,zoneId=3483,name="The Warp Rifts",level=61,minLevel=58,giver="Ogath the Mad",giverType="NPC",giverId=19683,ender="Ogath the Mad",enderType="NPC",enderId=19683,rewardNextId=10294,poiX=-1326,poiY=2344,wowhead="https://www.wowhead.com/wotlk/quest=10278",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Long have I wandered through Outland, searching for the truth of the void.  Now I am old and weak.  Perhaps you will help me? $B$BI must learn the secrets of the voidwalkers.  You must find the Warp Fields to the west.  West of the Expedition Armory there is a dark place on the edge of the abyss where time and space are weak.  Use my unstable warp rift generator in the Warp Fields to create a warp rift.  You must gather warp nether from the creatures that come through.  ",logDesc="Use the Unstable Warp Rift Generator in the Warp Fields.  Gather 3 Warp Nethers from Unstable Voidwalkers and return them to Ogath the Mad in Spinebreaker Post.  "} end
if not DB[10279] then DB[10279]={id=10279,zoneId=1941,name="To The Master's Lair",level=66,minLevel=66,giver="3",giverType="NPC",giverId=20142,ender="Andormu",enderType="NPC",enderId=20130,rewardNextId=10277,poiX=-8161,poiY=-4774,wowhead="https://www.wowhead.com/wotlk/quest=10279",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Ah, $N. We have been expecting you. Please, allow one of my brothers to fly you down to the master. He awaits you below...",logDesc="Speak to Andormu at the Caverns of Time."} end
if not DB[10280] then DB[10280]={id=10280,zoneId=3703,name="Special Delivery to Shattrath City",level=70,minLevel=67,giver="Image of Nexus-Prince Haramad",giverType="NPC",giverId=20084,ender="A'dal",enderType="NPC",enderId=18481,rewardNextId=10704,poiX=4120,poiY=2926,wowhead="https://www.wowhead.com/wotlk/quest=10280",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="I am an ethereal of my word, $N.  You have truly inspired me.$B$BI am now going to give you the ata'mal crystal to hand over to the naaru.  As it was your heroics that made this possible, I wish for you to deliver it.$B$BYou may use my personal teleporter to go directly to Shattrath City.  Simply step through it and you will be transported there.$B$BGive the crystal to the naaru known as A'dal on the Terrace of Light.  May the trade winds be at your back.",logDesc="Deliver the Ata'mal Crystal to A'dal on the Terrace of Light in Shattrath City.",choiceRewards={{id=30258,qty=1},{id=30256,qty=1},{id=30257,qty=1}}} end
if not DB[10281] then DB[10281]={id=10281,zoneId=3523,name="Formal Introductions",level=70,minLevel=68,giver="Shrouded Figure",giverType="NPC",giverId=20154,ender="Tyri",enderType="NPC",enderId=20110,rewardNextId=10272,poiX=4014,poiY=1529,wowhead="https://www.wowhead.com/wotlk/quest=10281",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Greetings, $N. Do not be alarmed. This is merely a projection of my current form. It's the only way my companion and I could keep watch without revealing ourselves.$B$BThe ethereal who approached you, Marid, is little better than a swindler in the guise of a legitimate merchant. I'd like you to consider working with me instead. My purpose out here is to find out more about the unusual dragonkin on this ridge. Meet me at the north end of the ridge and we will discuss this further.",logDesc="Find Tyri at the north end of the Celestial Ridge and speak with her."} end
if not DB[10282] then DB[10282]={id=10282,zoneId=1941,name="Old Hillsbrad",level=68,minLevel=66,giver="Andormu",giverType="NPC",giverId=20130,ender="Erozion",enderType="NPC",enderId=18723,rewardNextId=10283,poiX=-8372,poiY=-4250,wowhead="https://www.wowhead.com/wotlk/quest=10282",image="assets/images/quests/placeholder.png",xpDiff=1,desc="To the west is the timeway to Hillsbrad of the past - 7 years to be exact.$B$BForces are working against the Horde warchief, Thrall, attempting to prevent him from ever escaping Durnholde Keep.$B$BIf Thrall never escapes, this world - as you know it - will cease to exist.$B$BGather a group of adventurers and take the timeway to old Hillsbrad. Two of our agents await you inside.$B$BSpeak with Erozion on the other side.",logDesc="Andormu at the Caverns of Time has asked that you venture to Old Hillsbrad and speak with Erozion."} end
if not DB[10283] then DB[10283]={id=10283,zoneId=1941,name="Taretha's Diversion",level=68,minLevel=66,giver="Erozion",giverType="NPC",giverId=18723,ender="3",enderType="NPC",enderId=17876,rewardNextId=10284,poiX=2375,poiY=1175,wowhead="https://www.wowhead.com/wotlk/quest=10283",image="assets/images/quests/placeholder.png",xpDiff=8,desc="Taretha was integral in Thrall's survival and upbringing and instrumental in shaping Thrall's life.$B$BIt was Taretha who created the original diversion at Durnholde, allowing Thrall to escape.$B$BNow the Infinite have captured Taretha and hold her at Tarren Mill. The diversion will not happen without our involvement. You must use the incendiary devices that I give you and burn down the internment lodges in Durnholde. When you have done this, speak with young Thrall in the basement prison of Durnholde.",logDesc="Travel to Durnholde Keep and set 5 incendiary charges at the barrels located inside each of the internment lodges using the Pack of Incendiary Bombs given to you by Erozion.$B$BSpeak to Thrall in the basement prison of Durnholde Keep when you have the Internment Lodges Set Ablaze."} end
if not DB[10284] then DB[10284]={id=10284,zoneId=1941,name="Escape from Durnholde",level=68,minLevel=66,giver="3",giverType="NPC",giverId=17876,ender="Erozion",enderType="NPC",enderId=18723,rewardNextId=10285,poiX=2232,poiY=120,wowhead="https://www.wowhead.com/wotlk/quest=10284",image="assets/images/quests/placeholder.png",xpDiff=8,desc="You look upon me now and see only a boy, but in my heart and soul I hide my dreams. I have plans for my people, stranger. One day, they shall overthrow their oppressors and rise as one. They will break free from the bonds that hold them and from that uprising shall be born the orcish Horde.$B$BI promise you, stranger, should we make it out of here alive, when I have the means to reward this selfless deed, I will seek you out... I will find you.$B$B<Thrall nods.>$B$BWe will leave when you are ready.",logDesc="When you are ready to proceed, let Thrall know. Follow Thrall out of Durnholde Keep and help him free Taretha and fulfill his destiny.$B$BSpeak with Erozion in Old Hillsbrad should you complete this task."} end
if not DB[10285] then DB[10285]={id=10285,zoneId=1941,name="Return to Andormu",level=68,minLevel=66,giver="Erozion",giverType="NPC",giverId=18723,ender="Andormu",enderType="NPC",enderId=20130,poiX=2375,poiY=1175,wowhead="https://www.wowhead.com/wotlk/quest=10285",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This timeline has been restored and the assault of the Infinite Dragonflight upon Hillsbrad has been quashed.$B$BReturn to Andormu at once. He awaits your arrival in the master's lair.",logDesc="Return to the child Andormu at the Caverns of Time in the Tanaris desert.",choiceRewards={{id=29317,qty=1},{id=29318,qty=1},{id=29319,qty=1},{id=29316,qty=1}}} end
if not DB[10286] then DB[10286]={id=10286,zoneId=3483,name="Arelion's Secret",level=62,minLevel=60,giver="Magistrix Carinda",giverType="NPC",giverId=16793,ender="Magister Aledis",enderType="NPC",enderId=20159,rewardNextId=10287,poiX=-596,poiY=4177,wowhead="https://www.wowhead.com/wotlk/quest=10286",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Arelion's journal does not deal with any sort of scholarly studies.  It details his escapades with a young female blood elf!  How could I've been such a fool?$B$BUnfortunately, the floozy's identity is not revealed in this journal.  Aledis, a colleague of Arelion's, was his best friend and confidant.  Go question him and find out who he was having this affair with.$B$BI saw Aledis leave Falcon Watch for Zangarmarsh.  Follow the road headed north from town; it'll eventually lead west, toward Zangarmarsh.",logDesc="Magistrix Carinda wants you to interrogate Magister Aledis, last seen traveling from Falcon Watch to Zangarmarsh."} end
if not DB[10287] then DB[10287]={id=10287,zoneId=3483,name="The Mistress Revealed",level=62,minLevel=60,giver="Magister Aledis",giverType="NPC",giverId=20159,ender="Magistrix Carinda",enderType="NPC",enderId=16793,rewardNextId=9472,poiX=-690,poiY=4168,wowhead="https://www.wowhead.com/wotlk/quest=10287",image="assets/images/quests/placeholder.png",xpDiff=3,money=14000,desc="I'm Arelion's friend, but I'm not going to take the beating of my life for him.  His mistress is Viera Sunwhisper.$B$BGo tell that harpy of a wife of his.  What's she going to do anyway?",logDesc="Return to Magistrix Carinda at Falcon Watch in Hellfire Peninsula."} end
if not DB[10288] then DB[10288]={id=10288,zoneId=3483,name="Arrival in Outland",level=61,minLevel=58,giver="Commander Duron",giverType="NPC",giverId=19229,ender="Amish Wildhammer",enderType="NPC",enderId=18931,rewardNextId=10140,poiX=-266,poiY=1029,wowhead="https://www.wowhead.com/wotlk/quest=10288",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I want you to speak with Amish Wildhammer, standing about 30 paces south of us, and catch the first flight to Honor Hold. When you arrive at Honor Hold, you'll be greeted by Marshal Isildor. I have prepared a report detailing our situation here.  Give him the report, and tell him you're ready for duty.$B$BYou have your orders, soldier, now move out!  And though your blood must be burning to help us against the fiends below, waste no time here.  Honor Hold needs you even more.",logDesc="Commander Duron at the Dark Portal in Hellfire Peninsula wants you to bring Duron's Report to Amish Wildhammer."} end
if not DB[10289] then DB[10289]={id=10289,zoneId=3483,name="Journey to Thrallmar",level=61,minLevel=58,giver="Vlagga Freyfeather",giverType="NPC",giverId=18930,ender="General Krakork",enderType="NPC",enderId=19255,rewardNextId=10291,poiX=-176,poiY=1029,wowhead="https://www.wowhead.com/wotlk/quest=10289",image="assets/images/quests/placeholder.png",xpDiff=2,desc="When you're ready, I'll summon a wyvern to fly you to Thrallmar. Once you arrive, deliver Orion's report to General Krakork.$B$BLok'tar ogar, $n - good luck.",logDesc="Take Vlagga Freyfeather's Wind Rider to Thrallmar.  Bring Orion's Report to General Krakork."} end
if not DB[10290] then DB[10290]={id=10290,zoneId=3523,name="In Search of Farahlite",level=70,minLevel=68,giver="Zuben Elgenubi",giverType="NPC",giverId=20067,ender="Zuben Elgenubi",enderType="NPC",enderId=20067,rewardNextId=10293,poiX=4116,poiY=3026,wowhead="https://www.wowhead.com/wotlk/quest=10290",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="To the northeast is an area called the Netherstone, a landmark not seen when this was a lush, green land. Newly-exposed crystal formations have shown us a mineral we've called farahlite in honor of this land's former identity.$B$BThe tiny amount of farahlite we've mined has already proven popular with our clients. The highest grade of the mineral comes not from static deposits, but from the giants around the Netherstone. I can offer you a cut of the profits if you'll help supply the higher grade farahlite.",logDesc="Gather 4 pieces of Raw Farahlite and return to Zuben Elgenubi at the Stormspire."} end
if not DB[10291] then DB[10291]={id=10291,zoneId=3483,name="Report to Nazgrel",level=60,minLevel=55,giver="General Krakork",giverType="NPC",giverId=19255,ender="Nazgrel",enderType="NPC",enderId=3230,rewardNextId=10121,poiX=219,poiY=2654,wowhead="https://www.wowhead.com/wotlk/quest=10291",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Though our warriors are without peer, our hold on this wasteland is still tenuous. Report to Nazgrel inside the barracks - he has need of agents... such as you. If we can't protect our holdings here, we'll be of no use to anyone. Now go!",logDesc="General Krakork in Thrallmar wants you to speak with Nazgrel."} end
if not DB[10292] then DB[10292]={id=10292,zoneId=3523,name="More Power!",level=69,minLevel=67,rewardNextId=10293,wowhead="https://www.wowhead.com/wotlk/quest=10292",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Gathering a precious commodity in small batches has a quaint, cottage-industry feel to it, but it's just not competitive in today's market.$B$BNo, what we need is a method of mass producing farahlite! Then, the quantity on the market will be completely within our control.$B$BI have an idea, but it's going to require a powerful, focused energy source. There's only one possible place to find an energy source powerful enough. Go to the Legion's camps to our north and 'procure' some of their cannon.",logDesc="Zuben Elgenubi wants you to capture 8 Legion Cannon and bring them back to the Stormspire."} end
if not DB[10293] then DB[10293]={id=10293,zoneId=3523,name="Hitting the Motherlode",level=69,minLevel=67,giver="Zuben Elgenubi",giverType="NPC",giverId=20067,ender="Zuben Elgenubi",enderType="NPC",enderId=20067,poiX=4116,poiY=3026,wowhead="https://www.wowhead.com/wotlk/quest=10293",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Now that we've got a good baseline product, we're going to need something of higher quality. Certainly the farahlite we've gathered so far is nice, but I know there's better out there.$B$BWe'll have to get a sample directly from Cragskaar, the patriarch of the Farahlon giants! You should be able to find it among the other giants in the Netherstone area. It's got huge pieces of farahlite jutting from its back and that's exactly what we need. Fell the giant and collect a farahlite core from it.",logDesc="Zuben Elgenubi at the Stormspire wants you to obtain a Farahlite Core.",choiceRewards={{id=29813,qty=1},{id=29814,qty=1},{id=29815,qty=1}}} end
if not DB[10294] then DB[10294]={id=10294,zoneId=3483,name="Void Ridge",level=61,minLevel=58,giver="Ogath the Mad",giverType="NPC",giverId=19683,ender="Ogath the Mad",enderType="NPC",enderId=19683,rewardNextId=10295,poiX=-1326,poiY=2344,wowhead="https://www.wowhead.com/wotlk/quest=10294",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="We have to improve my warp rift generator.  You must take it to Void Ridge.  Head east of here.  You must avoid the foul fort of Zeth'Gor.  To the east beyond Zeth'Gor is a small pass through the mountains.  Through this pass you will find Void Ridge, a terrible place on the edge of the abyss.$B$BYou must kill the walkers that you find there, and bring me shards of their souls.  With their power we will improve upon the warp rift generator and open a portal to the beyond that cannot be closed.  ",logDesc="Go to Void Ridge and kill the creatures you find.  Collect 40 Void Ridge Soul Shards and return them to Ogath the Mad in Spinebreaker Post."} end
if not DB[10295] then DB[10295]={id=10295,zoneId=3483,name="From the Abyss",level=63,minLevel=58,giver="Ogath the Mad",giverType="NPC",giverId=19683,ender="Ogath the Mad",enderType="NPC",enderId=19683,poiX=-1326,poiY=2344,wowhead="https://www.wowhead.com/wotlk/quest=10295",image="assets/images/quests/placeholder.png",xpDiff=5,money=29000,desc="My warp rift generator is complete. You can now use it to summon a true prince of the void, a creature whose soul shard will tell us much of what lies beyond.  $B$BGo south in Void Ridge and use my warp rift generator near the void stones.  Look for a cluster of crystals near the edge of the abyss.  A huge warp rift will form and Void Baron Galaxis will surely appear.  $B$BDestroy this creature and bring me his soul shard.  ",logDesc="Kill Void Baron Galaxis and collect his soul shard.  Take the shard to Ogath the Mad in Spinebreaker Post.",choiceRewards={{id=29399,qty=1},{id=29398,qty=1},{id=29400,qty=1}}} end
if not DB[10296] then DB[10296]={id=10296,zoneId=1941,name="The Black Morass",level=70,minLevel=66,giver="Andormu",giverType="NPC",giverId=20130,ender="Sa'at",enderType="NPC",enderId=20201,rewardNextId=10297,poiX=-8372,poiY=-4250,wowhead="https://www.wowhead.com/wotlk/quest=10296",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.$B$BYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.",logDesc="Travel through the Caverns of Time to the Black Morass during the opening of the Dark Portal and speak with Sa'at."} end
if not DB[10297] then DB[10297]={id=10297,zoneId=1941,name="The Opening of the Dark Portal",level=70,minLevel=66,giver="Sa'at",giverType="NPC",giverId=20201,ender="Sa'at",enderType="NPC",enderId=20201,rewardNextId=10298,poiX=-1543,poiY=7115,wowhead="https://www.wowhead.com/wotlk/quest=10297",image="assets/images/quests/placeholder.png",xpDiff=8,desc="Beyond this timeway, in the heart of the Black Morass, the Guardian, Medivh, feverishly works to open the Dark Portal, heralding in the age of orcs upon Azeroth.$B$BThe Infinite have sent their rift lords to stop this from happening.$B$BScattered across the morass, rifts will materialize. Infinite will pour out of the rifts and attempt to destroy Medivh's shields and, ultimately, Medivh.$B$BKill their rift lords and leaders! Do this until Medivh succeeds. Use this chrono-beacon should you require aid.",logDesc="Sa'at inside the Black Morass of the Caverns of Time has tasked you with defending Medivh until he succeeds in opening the Dark Portal.$B$BReturn to Sa'at should you succeed in your task."} end
if not DB[10298] then DB[10298]={id=10298,zoneId=1941,name="Hero of the Brood",level=70,minLevel=66,giver="Sa'at",giverType="NPC",giverId=20201,ender="Andormu",enderType="NPC",enderId=20130,poiX=-1543,poiY=7115,wowhead="https://www.wowhead.com/wotlk/quest=10298",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Return to the child, Andormu, $N. He awaits you outside this pocket of time, in the master's lair.$B$BI hear flutterings. The Scale of Sands has shown interest in your abilities. Perhaps they too would like to speak with you.",logDesc="Return to the child, Andormu, at the Caverns of Time in the Tanaris desert.",choiceRewards={{id=29320,qty=1},{id=29322,qty=1},{id=29321,qty=1},{id=29323,qty=1}}} end
if not DB[10299] then DB[10299]={id=10299,zoneId=3523,name="Shutting Down Manaforge B'naar",level=68,minLevel=67,giver="Anchorite Karja",giverType="NPC",giverId=19467,ender="Anchorite Karja",enderType="NPC",enderId=19467,rewardNextId=10321,poiX=3071,poiY=3697,wowhead="https://www.wowhead.com/wotlk/quest=10299",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="We cannot shut down the manaforges by force as we'd risk causing an explosion that would shake Outland to the core.$B$BAccording to your transcription, there is an emergency shutdown that permanently disables the technology - a safety mechanism common in naaru constructs.$B$BTo perform this procedure you will have to obtain a crystal that will allow you to communicate with the console.  This access crystal is in the possession of an overseer called Theredis according to our information.",logDesc="Return to Manaforge B'naar and obtain the B'naar Access Crystal from Overseer Theredis.  Use it at the Manaforge B'naar console to shut it down and report back to Anchorite Karja.$B$BPerforming quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10300] then DB[10300]={id=10300,zoneId=3523,name="Rebuilding the Staff",level=69,minLevel=67,giver="Ravandwyr",giverType="NPC",giverId=19217,ender="Ravandwyr",enderType="NPC",enderId=19217,rewardNextId=10174,poiX=2998,poiY=3735,wowhead="https://www.wowhead.com/wotlk/quest=10300",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="<Ravandwyr inspects the staff, noting that part of the headpiece seems to be missing.>$B$BSimply barbaric! Ekkorash must've taken the staff's crystalline headpiece for use in some other trinket, not realizing that it works in concert with the rest of the staff.$B$BAs long as it remains broken, the staff's power is greatly diminished. With a suitable draenei crystal, I should be able to repair it. I've heard the goblins remarking about the crystals carried by the ghosts at the Enkaat Ruins to the north.",logDesc="Obtain 4 Flawless Crystal Shards from the ghosts at the Enkaat Ruins and return them to Ravandwyr at Area 52."} end
if not DB[10301] then DB[10301]={id=10301,zoneId=3523,name="Unlocking the Compendium",level=69,minLevel=67,giver="Image of Archmage Vargoth",giverType="NPC",giverId=19644,ender="Image of Archmage Vargoth",enderType="NPC",enderId=19644,rewardNextId=10209,wowhead="https://www.wowhead.com/wotlk/quest=10301",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="While I'm glad to have most of Krasus's Compendium back, it's useless without the heliotrope oculus. You see, Krasus was well aware of the sheer power of the spells recorded in the book and took steps to safeguard them from prying eyes.$B$BOnly a knowledgeable mage can use the oculus to unlock the compendium's secrets.$B$BDuring Kael'thas's attack, one of his lieutenants, Spellreaver Marathelle, looted it and took it to Sunfury Hold northeast of the tower. No doubt she thought it a pretty little bauble.",logDesc="Obtain the Heliotrope Oculus from Spellreaver Marathelle at Sunfury Hold. "} end
if not DB[10302] then DB[10302]={id=10302,zoneId=3526,name="Volatile Mutations",level=2,minLevel=1,giver="Botanist Taerix",giverType="NPC",giverId=16514,ender="Botanist Taerix",enderType="NPC",enderId=16514,rewardNextId=9293,poiX=-4057,poiY=-13722,wowhead="https://www.wowhead.com/wotlk/quest=10302",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="The irradiated power cores from the Exodar have been wreaking havoc on the environment here. The most obvious effect has been the appearance of the strange creatures that seem to have sprung up near them.$b$bThere may be something we can do to help them, but now, their sheer numbers are becoming too much for us to handle.$b$bI'd like you to go out and cull their numbers somewhat, and perhaps I'll have another idea after giving it some thought.",logDesc="Kill 8 Volatile Mutations, then return to Botanist Taerix at the Crash Site in Ammen Vale."} end
if not DB[10303] then DB[10303]={id=10303,zoneId=3526,name="The Blood Elves",level=4,minLevel=1,giver="Tolaan",giverType="NPC",giverId=16546,ender="Tolaan",enderType="NPC",enderId=16546,rewardNextId=9311,poiX=-4446,poiY=-13431,wowhead="https://www.wowhead.com/wotlk/quest=10303",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You must eliminate... the blood elf... threat.  Find out... what they're... up to!$B$BThey're on the... ridge behind me.",logDesc="Kill 10 Blood Elf Scouts then return to Tolaan in the Shadow Ridge of Ammen Vale.",choiceRewards={{id=24135,qty=1},{id=24134,qty=1},{id=24133,qty=1}}} end
if not DB[10304] then DB[10304]={id=10304,zoneId=3526,name="Vindicator Aldar",level=4,minLevel=1,giver="Botanist Taerix",giverType="NPC",giverId=16514,ender="Vindicator Aldar",enderType="NPC",enderId=16535,rewardNextId=9303,poiX=-4057,poiY=-13722,wowhead="https://www.wowhead.com/wotlk/quest=10304",image="assets/images/quests/placeholder.png",xpDiff=3,desc="With your help, we were able to find a solution to our problems faster than I could have hoped.$b$bI don't have any other work for you to do. My apprentices and I can handle the rest.$b$bYou should go speak with Vindicator Aldar on the other side of the ship.",logDesc="Speak with Vindicator Aldar at the Crash Site in Ammen Vale."} end
if not DB[10305] then DB[10305]={id=10305,zoneId=3523,name="Abjurist Belmara",level=69,minLevel=67,ender="Custodian Dieworth",enderType="NPC",enderId=19488,wowhead="https://www.wowhead.com/wotlk/quest=10305",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This worn, sturdy tome is no spellbook, as you might expect a Kirin Tor mage to carry. The pages of the volume are covered with hand-copied stories, accompanied by colorful illustrations.$B$BThe tome seems to be far older than its former owner and may have even been a family heirloom. A powerful tie to the book may have been the last thread tying Belmara's spirit to the ruins of Kirin'Var. Returning it to its proper place on the bookshelf in her quarters might help appease her restless spirit.",logDesc="Locate Abjurist Belmara's quarters in Wizard Row and return the book to its Bookshelf. Then, speak with Custodian Dieworth at Kirin'Var Village."} end
if not DB[10306] then DB[10306]={id=10306,zoneId=3523,name="Conjurer Luminrath",level=69,minLevel=67,ender="Custodian Dieworth",enderType="NPC",enderId=19488,wowhead="https://www.wowhead.com/wotlk/quest=10306",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The cloak, undoubtedly of high elven craftsmanship, is richly tailored, even by the standards of the Kirin Tor. The symbols and characters sewn into the cloak's fabric hold no meaning for you, but clearly imbue the garment with magical properties.$B$BPerhaps this object binds the spirit of its former owner to this plane of existence. If so, returning it to the dresser in Conjurer Luminrath's quarters might break the spirit's link to this world, allowing it to rest.",logDesc="Locate Conjurer Luminrath's quarters in Wizard Row and return the mantle to his Dresser. Then, speak with Custodian Dieworth at Kirin'Var Village."} end
if not DB[10307] then DB[10307]={id=10307,zoneId=3523,name="Cohlien Frostweaver",level=69,minLevel=67,ender="Custodian Dieworth",enderType="NPC",enderId=19488,wowhead="https://www.wowhead.com/wotlk/quest=10307",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Looking at the hat, you find yourself asking if any Kirin Tor mage would own such headgear. Judging from the hat's wear, it seems the gnome wouldn't go anywhere without it.$B$BYou try on the hat momentarily, discovering no magical properties beyond a faint urge to dance.$B$BThe treasured possession might be the source of the dead mage's bond to the village. Placing the hat in the footlocker in Cohlien's quarters might free his spirit.",logDesc="Locate Cohlien Frostweaver's quarters in Wizard Row and return the hat to his Footlocker. Then, speak with Custodian Dieworth at Kirin'Var Village."} end
if not DB[10308] then DB[10308]={id=10308,zoneId=3523,name="Another Heap of Ethereals",level=68,minLevel=67,giver="Nether-Stalker Khay'ji",giverType="NPC",giverId=19880,ender="Nether-Stalker Khay'ji",enderType="NPC",enderId=19880,poiX=3070,poiY=3675,wowhead="https://www.wowhead.com/wotlk/quest=10308",image="assets/images/quests/placeholder.png"} end
if not DB[10309] then DB[10309]={id=10309,zoneId=3523,name="It's a Fel Reaver, But with Heart",level=68,minLevel=67,giver="N. D. Meancamp",giverType="NPC",giverId=19690,ender="N. D. Meancamp",enderType="NPC",enderId=19690,poiX=2595,poiY=3988,wowhead="https://www.wowhead.com/wotlk/quest=10309",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="You see that scrapped fel reaver over there to the south?  Isn't it a thing of beauty?$B$BI want its heart!$B$BWhat?  Yes, of course it has a heart... what doesn't?$B$B<N. D. looks indignant for a moment.>$B$BGo on over there, pry it open, bring back what I want and I'll give you a nice finder's fee in return.$B$BOh, and I'd take a friend or two along if I were you.  These Zaxxis ethereals are a pretty mean bunch!$B$BTake this fel zapper to jumpstart its heart when you're ready to begin.",logDesc="Recover the Heart of the Fel Reaver and deliver it to N. D. Meancamp at The Heap in the Netherstorm.",choiceRewards={{id=30268,qty=1},{id=30270,qty=1},{id=30269,qty=1}}} end
if not DB[10310] then DB[10310]={id=10310,zoneId=3523,name="Sabotage the Warp-Gate!",level=70,minLevel=68,giver="Drijya",giverType="NPC",giverId=20281,ender="Gahruj",enderType="NPC",enderId=20066,poiX=3096,poiY=2801,wowhead="https://www.wowhead.com/wotlk/quest=10310",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="With the Burning Legion nearby at the fel reaver scrap field, we must do what we can to stop the flow of demons into the area.$B$BThey have a warp-gate to the south in an area that they've cleverly named Invasion Point: Destroyer.$B$BI need you to go with me to the site and keep me safe while I sabotage it.$B$BAfterward, go to the Midrealm Post to the north inside Eco-Dome Midrealm and apprise Gahruj of our success.$B$BWe're going to need a friend or two of yours along to help with this.",logDesc="Escort Drijya to the warp-gate at Invasion Point: Destroyer, and see to it that he is kept safe while he attempts to sabotage it.  Then speak to Gahruj at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.",choiceRewards={{id=29978,qty=1},{id=29980,qty=1},{id=29979,qty=1}}} end
if not DB[10311] then DB[10311]={id=10311,zoneId=3523,name="Drijya Needs Your Help",level=70,minLevel=68,giver="Gahruj",giverType="NPC",giverId=20066,ender="Drijya",enderType="NPC",enderId=20281,rewardNextId=10310,poiX=3340,poiY=2882,wowhead="https://www.wowhead.com/wotlk/quest=10311",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$C, it is good to see a helpful face around here.$B$BThe Burning Legion at the nearby fel reaver heap has become more bold, and I am beginning to fear for our safety here.  The demons are constantly receiving reinforcements from Invasion Point: Destroyer to the south.$B$BMy compatriot, Drijya, has gone down there to scout and see if he can do something about the Burning Legion's warp-gate.$B$BPlease find and assist him in any way that you can.",logDesc="Speak with Drijya near Invasion Point: Destroyer in the Netherstorm."} end
if not DB[10312] then DB[10312]={id=10312,zoneId=3523,name="The Annals of Kirin'Var",level=69,minLevel=67,giver="Custodian Dieworth",giverType="NPC",giverId=19488,ender="Custodian Dieworth",enderType="NPC",enderId=19488,rewardNextId=10316,poiX=2247,poiY=2277,wowhead="https://www.wowhead.com/wotlk/quest=10312",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Silencing the spirits has not bled them of their aggression as we had hoped it would. The malevolent spirits you subdued have reemerged in the streets of the town.$B$BWe must uncover what is causing this to happen. The destruction of Kirin'Var was just the beginning, or else the spirits would have been quieted by now.$B$BThe town hall in the southern section of Kirin'Var maintained a logbook of all the residents. Last I heard, it was in the keeping of Battle-Mage Dathric. Perhaps his spirit still has it.",logDesc="Retrieve the Annals of Kirin'Var from the town hall of Kirin'Var Village and return it to Custodian Dieworth."} end
if not DB[10313] then DB[10313]={id=10313,zoneId=3523,name="Measuring Warp Energies",level=68,minLevel=67,giver="Exarch Orelis",giverType="NPC",giverId=19466,ender="Exarch Orelis",enderType="NPC",enderId=19466,poiX=3071,poiY=3695,wowhead="https://www.wowhead.com/wotlk/quest=10313",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If our instincts are right and these manaforges have been made using technology from Tempest Keep, then all of Outland could be in grave danger.$B$BTempest Keep's energy-recharging mechanisms were never supposed to be used this close to the land.  The warp energies are capable of destroying this very land, even when contained within Kael's pipelines.$B$BTake this orb to Manaforge B'naar; it is attuned to measure warp energies.  Use it at the pipelines' ends, where they go into the earth.",logDesc="Exarch Orelis in Area 52 wants you to take the Warp-Attuned Orb to Manaforge B'naar and use it at the end of its four pipelines.$B$BPerforming quests for the Aldor will cause your Scryers reputation level to decrease.",choiceRewards={{id=30362,qty=1},{id=30363,qty=1},{id=30364,qty=1},{id=30521,qty=1}}} end
if not DB[10314] then DB[10314]={id=10314,zoneId=3523,name="A Lingering Suspicion",level=69,minLevel=67,ender="Custodian Dieworth",enderType="NPC",enderId=19488,rewardNextId=10319,wowhead="https://www.wowhead.com/wotlk/quest=10314",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The strange magical device resembles nothing you've ever seen before. It's certainly not of blood elf manufacture.$B$BAs you sense spirits moving closer to the building, the orb glows with a greater intensity, which fades as the spirits leave. There's no question that it plays a role in the corruption of the ghosts.$B$BHow it works remains a mystery. Perhaps Custodian Dieworth will have some insight if you can provide the remains of some of the spirits along with your observations.",logDesc="Collect 10 Loathsome Remnants from the twisted spirits in Kirin'Var Village's Chapel Yard and bring them to Custodian Dieworth."} end
if not DB[10315] then DB[10315]={id=10315,zoneId=3523,name="Neutralizing the Nethermancers",level=70,minLevel=68,giver="Nether-Stalker Oazul",giverType="NPC",giverId=20341,ender="Nether-Stalker Oazul",enderType="NPC",enderId=20341,poiX=4051,poiY=3560,wowhead="https://www.wowhead.com/wotlk/quest=10315",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="The blood elves are fools!  I'm glad that our trade relations with them have fallen apart.  In all of my travels throughout the cosmos, I have never encountered beings so selfish.$B$BThey continue to destroy the land around us with their manaforges, so let's see if we can put a dent in their operations across the bridge at Manaforge Ara.$B$BTheir nethermancers channel energy to and from the blood gems to stabilize the flow of power.  Go over there and wipe them out!",logDesc="Kill 15 Sunfury Nethermancers and return to Nether-Stalker Oazul at Tuluman's Landing in the Netherstorm."} end
if not DB[10316] then DB[10316]={id=10316,zoneId=3523,name="Searching for Evidence",level=69,minLevel=67,giver="Custodian Dieworth",giverType="NPC",giverId=19488,rewardNextId=10314,poiX=2247,poiY=2277,wowhead="https://www.wowhead.com/wotlk/quest=10316",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Whoever is behind the transformation of the spirits has been very deliberate in their actions, taking care to target the most powerful mages first, but why? The kind of magic required to influence the spirits of slain Kirin Tor mages must be very powerful.$B$BWhy would a powerful mage go to all this trouble? I'm inclined to say this is another plot of Kael'thas's, designed to cause more misery here. If there are blood elves here, they're likely to be hiding in the houses across the covered bridge.",logDesc="Search Kirin'Var Village's Chapel Yard for clues about who is behind the manipulation of the spirits."} end
if not DB[10317] then DB[10317]={id=10317,zoneId=3523,name="Dealing with the Foreman",level=70,minLevel=68,giver="Wind Trader Tuluman",giverType="NPC",giverId=20112,ender="Foreman Sundown",enderType="NPC",enderId=20393,rewardNextId=10318,poiX=4046,poiY=3553,wowhead="https://www.wowhead.com/wotlk/quest=10317",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The blood elves call the mine underneath Manaforge Ara the Trelleum Mine.  Ever since they lost the one underneath Manaforge Ultris, this is where their sole supply of material for running the forges is coming from.$B$BNeedless to say, it would be a boon for us to cripple their mining operation.  Perhaps we'd even be able to move in and take it over for ourselves?$B$BWhatever the case, I want you to go in there and deal with Foreman Sundown.  The mine is around the back of the island to the left.",logDesc="Deal with Foreman Sundown inside the Trelleum Mine, which is underneath Manaforge Ara in the Netherstorm."} end
if not DB[10318] then DB[10318]={id=10318,zoneId=3523,name="Dealing with the Overmaster",level=70,minLevel=68,giver="Foreman Sundown",giverType="NPC",giverId=20393,ender="Wind Trader Tuluman",enderType="NPC",enderId=20112,poiX=3885,poiY=4013,wowhead="https://www.wowhead.com/wotlk/quest=10318",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="I used to be the foreman here.  But now that I've been demoted, I've come to realize our pilgrimage from Quel'Thalas to Outland was all a lie.$B$BA lie perpetrated by Kael'thas to strengthen his forces here in the Netherstorm.$B$BI've tried to convince my brethren that we should leave, especially with the Burning Legion here, but they are all too stubborn.$B$BDo me a favor?  Kill Overmaster Grindgarr.  Then return to your ethereal and tell him that I am no longer his enemy.",logDesc="Slay Overmaster Grindgarr.  Then return to Wind Trader Tuluman at Tuluman's Landing in the Netherstorm.",choiceRewards={{id=30003,qty=1},{id=30004,qty=1},{id=30005,qty=1},{id=30006,qty=1}}} end
if not DB[10319] then DB[10319]={id=10319,zoneId=3523,name="Capturing the Phylactery",level=69,minLevel=67,giver="Custodian Dieworth",giverType="NPC",giverId=19488,ender="Custodian Dieworth",enderType="NPC",enderId=19488,rewardNextId=10320,poiX=2247,poiY=2277,wowhead="https://www.wowhead.com/wotlk/quest=10319",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="I suppose an explanation is in order. You've met one of the archmage's apprentices, Ravandwyr, but there was also another named Naberius.$B$BHe was an ardent student, but was drawn to necromancy. When Kael'thas appeared with his forces, Naberius seized the opportunity to betray the archmage, handing over the secrets to the tower's defense.$B$BNow, it seems, he has become a lich. If we are to stop him, we must capture his phylactery. Knowing him, he would've buried it somewhere out of sight in his domain.",logDesc="Recover Naberius's Phylactery from Kirin'Var Village's Chapel Yard district and bring it to Custodian Dieworth."} end
if not DB[10320] then DB[10320]={id=10320,zoneId=3523,name="Destroy Naberius!",level=69,minLevel=67,giver="Custodian Dieworth",giverType="NPC",giverId=19488,ender="Custodian Dieworth",enderType="NPC",enderId=19488,poiX=2247,poiY=2277,wowhead="https://www.wowhead.com/wotlk/quest=10320",image="assets/images/quests/placeholder.png",xpDiff=6,money=41000,desc="Archmage Vargoth saw the danger in Naberius's pursuit of necromancy, but I don't think he ever anticipated that his own apprentice would wreak this much destruction upon the Kirin Tor.$B$BYou must defeat him, $N, or else he will continue enslaving the spirits of our fallen brothers, robbing them of their rightful rest and destroying what little remains of Kirin'Var.$B$BWith his phylactery in hand, he can be confronted by two or three combatants, but who knows what his magic might do to more foes?",logDesc="Custodian Dieworth in Kirin'Var Village wants you to confront and defeat Naberius in the village's Chapel Yard.",choiceRewards={{id=29780,qty=1},{id=29781,qty=1},{id=29782,qty=1},{id=29783,qty=1}}} end
if not DB[10321] then DB[10321]={id=10321,zoneId=3523,name="Shutting Down Manaforge Coruu",level=69,minLevel=67,giver="Anchorite Karja",giverType="NPC",giverId=19467,ender="Anchorite Karja",enderType="NPC",enderId=19467,rewardNextId=10322,poiX=3071,poiY=3697,wowhead="https://www.wowhead.com/wotlk/quest=10321",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Your success at B'naar has given us a great deal of hope, $N.$B$BWe've shared our discoveries with the Scryers and in return they've given us more information on the remaining manaforges.$B$BThree other manaforges still stand, in full control of the Sunfury army.$B$BYou will find Manaforge Coruu to the east.  Overseer Seylanna holds the access crystal there.  Obtain it and use it on the manaforge's control console to begin the emergency shutdown.$B$BWe're all counting on you, $N.",logDesc="Travel to Manaforge Coruu, east of Area 52, and obtain the Coruu Access Crystal from Overseer Seylanna.  Use it at the Manaforge Coruu Console to shut it down and return to Anchorite Karja.$B$BPerforming quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10322] then DB[10322]={id=10322,zoneId=3523,name="Shutting Down Manaforge Duro",level=70,minLevel=67,giver="Anchorite Karja",giverType="NPC",giverId=19467,ender="Anchorite Karja",enderType="NPC",enderId=19467,rewardNextId=10323,poiX=3071,poiY=3697,wowhead="https://www.wowhead.com/wotlk/quest=10322",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We've received news from one of the two manaforges that remain operational.  The Sunfury army is losing control of Manaforge Duro.$B$BDroves of errant mana creatures have been attracted to it by its increased energy production - the manaforge is in chaos.$B$BAn explosion at Duro has the potential to cause a chain reaction that would endanger all of Outland.  Overseer Athanel is in possesion of the access crystal you need to safely disable the manaforge.",logDesc="Anchorite Karja wants you to go Manaforge Duro and obtain the Duro Access Crystal from Overseer Athanel.  Use it at the Manaforge Duro Console to shut it down.$B$BPerforming quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10323] then DB[10323]={id=10323,zoneId=3523,name="Shutting Down Manaforge Ara",level=70,minLevel=67,giver="Anchorite Karja",giverType="NPC",giverId=19467,ender="Anchorite Karja",enderType="NPC",enderId=19467,poiX=3071,poiY=3697,wowhead="https://www.wowhead.com/wotlk/quest=10323",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="One manaforge is all that keeps Tempest Keep functional.  After we bring Manaforge Ara down, Kael will have to resort to depleting whatever energy he's got stored up.$B$BTravel to Manaforge Ara, in the northwest, and deliver the final blow that we need by shutting it down.$B$BThe last access crystal is in the possession of Overseer Azarad.  Be warned that we expect heavy opposition in the last of Kael's functional manaforges.  You're likely to need the assistance of reliable friends.",logDesc="Travel to Manaforge Ara and obtain the Ara Access Crystal from Overseer Azarad.  Use it at the Manaforge Ara console to shut it down.$B$BPerforming quests for the Aldor will cause your Scryers reputation level to decrease.",choiceRewards={{id=30377,qty=1},{id=30365,qty=1}}} end
if not DB[10324] then DB[10324]={id=10324,zoneId=3524,name="The Great Moongraze Hunt",level=8,minLevel=4,giver="Acteon",giverType="NPC",giverId=17110,ender="Acteon",enderType="NPC",enderId=17110,poiX=-4204,poiY=-12526,wowhead="https://www.wowhead.com/wotlk/quest=10324",image="assets/images/quests/placeholder.png",xpDiff=4,money=175,desc="Well done, $n! Well done!$b$bNow that you've cut your teeth with the moongraze stag, it's time you graduated to more formidable prey. Do not allow the casual disinterest of the moongraze bucks to fool you: when provoked, they are a fearsome foe.$b$bYou'll find the bucks north of here. Good hunting.",logDesc="Bring 6 Moongraze Buck Hides to Acteon at Azure Watch.",choiceRewards={{id=24104,qty=1},{id=24103,qty=1}}} end
if not DB[10325] then DB[10325]={id=10325,zoneId=3703,name="Marks of Kil'jaeden",level=65,minLevel=62,giver="Adyen the Lightwarden",giverType="NPC",giverId=18537,ender="Adyen the Lightwarden",enderType="NPC",enderId=18537,poiX=-1775,poiY=5734,wowhead="https://www.wowhead.com/wotlk/quest=10325",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As you probably know, $N, the Aldor are keepers of the Light and servants of the naaru.$B$BDiametrically opposed to us are the agents of the Burning Legion - demons bent on the destruction of worlds and the corruption of the innocent.$B$BIf you wish to prove yourself to the Aldor, bring me the insignias of low-ranking Legion and their Shadow Council followers.  We know of a Shadow Council hideout in the Bone Wastes and there are many Legion outposts in Nagrand and the Blade's Edge Mountains.",logDesc="Bring 10 Marks of Kil'jaeden to Adyen the Lightwarden in Shattrath City.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10326] then DB[10326]={id=10326,zoneId=3703,name="More Marks of Kil'jaeden",level=65,minLevel=62,giver="Adyen the Lightwarden",giverType="NPC",giverId=18537,ender="Adyen the Lightwarden",enderType="NPC",enderId=18537,poiX=-1775,poiY=5734,wowhead="https://www.wowhead.com/wotlk/quest=10326",image="assets/images/quests/placeholder.png"} end
if not DB[10327] then DB[10327]={id=10327,zoneId=3703,name="Single Mark of Kil'jaeden",level=65,minLevel=62,giver="Adyen the Lightwarden",giverType="NPC",giverId=18537,ender="Adyen the Lightwarden",enderType="NPC",enderId=18537,poiX=-1775,poiY=5734,wowhead="https://www.wowhead.com/wotlk/quest=10327",image="assets/images/quests/placeholder.png"} end
if not DB[10328] then DB[10328]={id=10328,zoneId=3523,name="Sunfury Briefings",level=70,minLevel=67,giver="Exarch Orelis",giverType="NPC",giverId=19466,ender="Exarch Orelis",enderType="NPC",enderId=19466,rewardNextId=10431,poiX=3071,poiY=3695,wowhead="https://www.wowhead.com/wotlk/quest=10328",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Something about these manaforges has been bothering me, $N.  Naaru technology is incredibly advanced; it should've taken Kael'thas years to even begin to understand it.$B$BInformation-gathering on the subject has been difficult as Kael's army is well disciplined and destroys all evidence of written communication.$B$BWe've been informed Manaforge Duro is under attack by mana creatures.  It is possible that those defending it have not yet destroyed their briefings.  Obtain them and bring them to me.",logDesc="Go to Manaforge Duro and retrieve the Sunfury Military Briefing and the Sunfury Arcane Briefing from the Sunfury units stationed there.  Return to Exarch Orellis when you've completed this task.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10329] then DB[10329]={id=10329,zoneId=3523,name="Shutting Down Manaforge B'naar",level=68,minLevel=67,giver="Spymaster Thalodien",giverType="NPC",giverId=19468,ender="Spymaster Thalodien",enderType="NPC",enderId=19468,rewardNextId=10194,poiX=3075,poiY=3699,wowhead="https://www.wowhead.com/wotlk/quest=10329",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="I was having a friendly discussion with the Aldor while you were gone.  Manaforges sure look like modified naaru technology from Tempest Keep.  Apparently, most naaru constructs have certain safeguards that allow them to be permanently disabled in case of emergency.$B$BThe procedure is usually initiated at a control console via an access crystal.  Lo and behold, according to the roster you secured, such a crystal is in the possession of a fellow called Overseer Theredis.  Obtain it and see what you can do.",logDesc="Return to Manaforge B'naar and obtain the B'naar Access Crystal from Overseer Theredis.  Use it at the B'naar Control Console to shut it down, then report back to Spymaster Thalodien.$B$BPerforming quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10330] then DB[10330]={id=10330,zoneId=3523,name="Shutting Down Manaforge Coruu",level=69,minLevel=67,giver="Caledis Brightdawn",giverType="NPC",giverId=19840,ender="Caledis Brightdawn",enderType="NPC",enderId=19840,rewardNextId=10200,poiX=2238,poiY=2794,wowhead="https://www.wowhead.com/wotlk/quest=10330",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Thalodien told us of your success in disabling Manaforge B'naar.  He expects a repeat performance here and asked us to keep an eye out for anyone using a crystal to access the console inside.  Overseer Seylanna holds the access crystal, we're sure of it.$B$BGo back in there and finish the operation.  No need to be stealthy anymore; get the crystal, begin the shutdown, kill the technicians trying to stop you and get out.$B$BHurry, it won't be long before Kael's lapdogs sniff us out.",logDesc="Obtain the Coruu Access Crystal from Overseer Seylanna.  Use it at the Coruu Control Console to shut down the manaforge and return to Caledis Brightdawn.$B$BPerforming quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10331] then DB[10331]={id=10331,zoneId=3523,name="Indispensable Tools",level=69,minLevel=67,giver="Apprentice Andrethan",giverType="NPC",giverId=20463,ender="Apprentice Andrethan",enderType="NPC",enderId=20463,rewardNextId=10332,poiX=2290,poiY=2266,wowhead="https://www.wowhead.com/wotlk/quest=10331",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="You haven't seen a heavy smithing hammer lying around by chance, have you? I brought it out here with me to finish the shoes for some of old man Amorlin's horses, but I can't find it.$B$BI've searched the barn no less than a half dozen times and I just can't seem to find it. Maybe one of the other apprentices retrieved it and took it back to the smithy? Would you be willing to go down there and take a look? The workshop is to the southeast of the tower in the Town Square.",logDesc="Retrieve the Smithing Hammer from the Kirin'Var Apprentices and bring it back to Apprentice Andrethan in Kirin'Var Village."} end
if not DB[10332] then DB[10332]={id=10332,zoneId=3523,name="Master Smith Rhonsus",level=69,minLevel=67,giver="Apprentice Andrethan",giverType="NPC",giverId=20463,ender="Apprentice Andrethan",enderType="NPC",enderId=20463,poiX=2290,poiY=2266,wowhead="https://www.wowhead.com/wotlk/quest=10332",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="At last, my journeyman project is complete! I can't wait to formally present it to Master Rhonsus.$B$B<The apprentice looks at you as you describe your experiences retrieving the hammer.>$B$BThey attacked you? All of them? By the Light, they've gone mad!$B$BWhat are we to do, $N? It grieves me to say so, but it may be necessary to kill Master Rhonsus. It would leave me as the only smith in Kirin'Var, but I believe my training is sufficient to serve the town's needs.",logDesc="Apprentice Andrethan in Kirin'Var Village wants you to kill the ghost of Rhonsus, the town's master blacksmith.",choiceRewards={{id=29787,qty=1},{id=29788,qty=1},{id=29789,qty=1},{id=29791,qty=1}}} end
if not DB[10333] then DB[10333]={id=10333,zoneId=3523,name="Help Mama Wheeler",level=69,minLevel=67,giver="Papa Wheeler",giverType="NPC",giverId=19645,ender="Mama Wheeler",enderType="NPC",enderId=19728,rewardNextId=10234,poiX=3053,poiY=3644,wowhead="https://www.wowhead.com/wotlk/quest=10333",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Say, $N, I was wondering if you could do me another favor.$B$BMy partner out in the field could probably use a hand.  I was wondering if you could go check in on her.$B$BI'm sure that Mama Wheeler will appreciate the help.  Just don't mind her sharp tongue.$B$BShe's trying to look out for our interests to the east.  You'll find her just inside Eco-Dome Midrealm at the Midrealm Post.",logDesc="Speak with Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm."} end
if not DB[10334] then DB[10334]={id=10334,zoneId=3523,name="Needs More Cowbell",level=69,minLevel=67,giver="Thadell",giverType="NPC",giverId=20464,ender="Bessy",enderType="NPC",enderId=20415,poiX=2299,poiY=2265,wowhead="https://www.wowhead.com/wotlk/quest=10334",image="assets/images/quests/placeholder.png",xpDiff=4,money=41000,desc="Where, oh where has my Bessy gone? After the attack, I searched the fields and the Chapel Yard for her, but she was nowhere to be seen!$B$BAll I have left of her is this old cowbell. She usually comes running when she hears it, but these feeble old bones probably couldn't shake it hard enough.$B$BI'll loan you Bessy's bell if you're willing to go out to the fields and ring it as hard as you can. Perhaps all Bessy's waiting for is a little more cowbell.",logDesc="Find Bessy in the fields near Kirin'Var Village's Chapel Hill in Netherstorm."} end
if not DB[10335] then DB[10335]={id=10335,zoneId=3523,name="Surveying the Ruins",level=70,minLevel=68,giver="Zephyrion",giverType="NPC",giverId=20470,ender="Zephyrion",enderType="NPC",enderId=20470,poiX=4160,poiY=2990,wowhead="https://www.wowhead.com/wotlk/quest=10335",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="I have to get over to the Ruins of Farahlon to start my excavations!  The problem is that the place has been infested by demons!$B$BMaybe you could do some preliminary work for me?$B$BThere are three locations within the ruins to the northeast where I want you to place surveying markers.  Each is near a draenei banner.$B$BReturn to me when you've managed to place all three markers.",logDesc="Place the three Surveying Markers and then return to Zephyrion at the Stormspire in the Netherstorm.",choiceRewards={{id=30255,qty=1},{id=30253,qty=1},{id=30254,qty=1}}} end
if not DB[10336] then DB[10336]={id=10336,zoneId=3523,name="The Minions of Culuthas",level=70,minLevel=68,giver="Nether-Stalker Nauthis",giverType="NPC",giverId=20471,ender="Nether-Stalker Nauthis",enderType="NPC",enderId=20471,poiX=4158,poiY=2991,wowhead="https://www.wowhead.com/wotlk/quest=10336",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="A few weeks ago, the Burning Legion moved into the Ruins of Farahlon, thwarting our plans to excavate the site for its artifacts.$B$BThen earlier today, I learned that one of their dreadlords, Culuthas, somehow killed off all of the other Burning Legion.  He has since summoned in demons that serve him.$B$B$C, I want you to go up to those ruins to the northeast and rid them of their demon infestation.",logDesc="Slay 10 Hounds of Culuthas and 5 Eyes of Culuthas.  Then return to Nether-Stalker Nauthis at the Stormspire in the Netherstorm."} end
if not DB[10337] then DB[10337]={id=10337,zoneId=3523,name="When the Cows Come Home",level=69,minLevel=67,giver="Bessy",giverType="NPC",giverId=20415,ender="Thadell",enderType="NPC",enderId=20464,poiX=2528,poiY=2186,wowhead="https://www.wowhead.com/wotlk/quest=10337",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Realizing that Bessy is still staring at you, you gesture toward Thadell's location. You find yourself promising to protect the cow on her way home. Upon finishing your sentence, you realize there's no possible way the cow could understand anything you've said.$B$BShrugging your shoulders, you prepare to guard the bovine on her way back to Thadell.",logDesc="Escort Bessy safely back to her owner, Thadell.",choiceRewards={{id=29804,qty=1},{id=29806,qty=1},{id=29807,qty=1},{id=30400,qty=1},{id=30523,qty=1}}} end
if not DB[10338] then DB[10338]={id=10338,zoneId=3523,name="Shutting Down Manaforge Duro",level=70,minLevel=67,giver="Spymaster Thalodien",giverType="NPC",giverId=19468,ender="Spymaster Thalodien",enderType="NPC",enderId=19468,rewardNextId=10365,poiX=3075,poiY=3699,wowhead="https://www.wowhead.com/wotlk/quest=10338",image="assets/images/quests/placeholder.png",xpDiff=5,desc="So Manaforge Duro is under attack and Sunfury forces have lost control?  What a dilemma!  If Duro goes down, then Tempest Keep goes down.  Only drawback is... if Tempest Keep is destroyed, the explosion will probably take what little remains of this forsaken land with it.$B$BDead Kael'thas is good.  Dead everyone else is... not that great, I suppose.  It pains me to ask this of you, but go to Manaforge Duro and shut it down before it goes up in flames.  The access crystal is held by Overseer Athanel.",logDesc="Return to Manaforge Duro and obtain the Duro Access Crystal from Overseer Athanel.  Use it at the Duro Control Console to shut it down and report back to Spymaster Thalodien.$B$BPerforming quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10339] then DB[10339]={id=10339,zoneId=3523,name="The Ethereum",level=70,minLevel=70,giver="Commander Ameer",giverType="NPC",giverId=20448,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,rewardNextId=10384,poiX=4253,poiY=2166,wowhead="https://www.wowhead.com/wotlk/quest=10339",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Directly south of here you will find the Ethereum Staging Grounds. The Ethereum are there, preparing for something... Perhaps an assault on Ultris.$B$BWe can't take any chances, though, $c. Break through their perimeter defenses and take out their training facility.$B$BOnce you've destroyed their soldiers and Captain Zovax, locate Ethereum transponder Zeta and use it to establish contact with me to get your next set of orders.",logDesc="Commander Ameer wants you to kill 5 Ethereum Assassins, 5 Ethereum Shocktroopers, 2 Ethereum Researchers and Captain Zovax then activate Ethereum Transponder Zeta."} end
if not DB[10340] then DB[10340]={id=10340,zoneId=3483,name="Shatter Point",level=60,minLevel=58,giver="Forward Commander Kingston",giverType="NPC",giverId=19310,ender="Runetog Wildhammer",enderType="NPC",enderId=20234,rewardNextId=10344,poiX=-680,poiY=1855,wowhead="https://www.wowhead.com/wotlk/quest=10340",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$n, you've done a great job here at the front, and you showed a lot of talent with that armored gryphon... I think I have another mission in mind for you.$B$BThis new mission launches from Shatter Point -- an attack base the Wildhammers set up on a floating piece of land near the Portal.  It's a little unnerving there, but you have tough guts.  You'll be fine.$B$BTalk to Wing Commander Dabir'ee and have him send you to Shatter Point.  From there, report to the gryphon master Runetog Wildhammer.",logDesc="Forward Commander Kingston wants you to speak with Wing Commander Dabir'ee, ride a gryphon to Shatter Point, and then report to Runetog Wildhammer."} end
if not DB[10341] then DB[10341]={id=10341,zoneId=3523,name="Kick Them While They're Down",level=70,minLevel=67,giver="Magistrix Larynna",giverType="NPC",giverId=19469,ender="Magistrix Larynna",enderType="NPC",enderId=19469,rewardNextId=10202,poiX=3078,poiY=3696,wowhead="https://www.wowhead.com/wotlk/quest=10341",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The news you've discovered is fortunate, $N.  Not only do you get to waltz into Manaforge Duro unfettered, this also presents a great opportunity to deal a blow to Kael's army.$B$BUse the mana creature assault to your advantage and pick off any Sunfury stragglers you run into.$B$BI do not take particular glee in the senseless slaughter of my own kin the way that Thalodien does, but the tactical advantage here is too high to pass up.",logDesc="Slay 8 Sunfury Conjurers, 6 Sunfury Bowmen and 4 Sunfury Centurions.  Return to Magistrix Larynna at Area 52 after completing this task.$B$BCompleting tasks for the Scryers will cause your Aldor reputation to decrease.",choiceRewards={{id=30395,qty=1},{id=30394,qty=1},{id=30396,qty=1},{id=30522,qty=1}}} end
if not DB[10342] then DB[10342]={id=10342,zoneId=3523,name="Securing the Shaleskin Shale",level=68,minLevel=67,giver="Boots",giverType="NPC",giverId=19617,ender="Boots",enderType="NPC",enderId=19617,rewardNextId=10199,poiX=3081,poiY=3684,wowhead="https://www.wowhead.com/wotlk/quest=10342",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="I make a good living selling drinks to the boozehounds around here.  But I want something more!$B$BThe rocket-chief is always telling me how he can't perfect the rocket fuel needed to get the X-52 off of the ground.$B$BWe can solve that little problem for him.$B$BFor starters I need to extract the oil from the shale of the local shaleskin flayers!  It'll form a concentrated, if explosive, base for the mix that I have in mind.$B$BFind the flayers, and their shale, all over the place near the purple rocks.",logDesc="Collect 5 Shaleskin Shale and give them to Boots at Area 52 in the Netherstorm."} end
if not DB[10343] then DB[10343]={id=10343,zoneId=3523,name="The Unending Invasion",level=69,minLevel=67,giver="Lieutenant-Sorcerer Morran",giverType="NPC",giverId=19489,ender="Lieutenant-Sorcerer Morran",enderType="NPC",enderId=19489,rewardNextId=10239,poiX=2249,poiY=2273,wowhead="https://www.wowhead.com/wotlk/quest=10343",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Kael'thas's assault on Kirin'Var began with thundering noise and a bright flash of light in the officer quarters to the northwest. The destruction there was the most severe and after the withdrawal of the blood elves, a strange thing began to happen.$B$BBeings of pure mana began streaming into the village from all over the area. For now, we're containing them as we can, but with more information about the weapon Kael'thas used, I hope to cut off the flow of mana creatures entirely.",logDesc="Search the mana creature infested area of Kirin'Var Village for a Mana Bomb Fragment and bring it to Lieutenant-Sorcerer Morran."} end
if not DB[10344] then DB[10344]={id=10344,zoneId=3483,name="Wing Commander Gryphongar",level=60,minLevel=58,giver="Runetog Wildhammer",giverType="NPC",giverId=20234,ender="Wing Commander Gryphongar",enderType="NPC",enderId=20232,poiX=279,poiY=1490,wowhead="https://www.wowhead.com/wotlk/quest=10344",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Wing Commander Gryphongar runs this outfit of Wildhammers.  If this is your first time to Shatter Point, then you should report to him.$B$BYou'll find him inside what's left of that tower over yonder.",logDesc="Speak with Wing Commander Gryphongar in Shatter Point."} end
if not DB[10345] then DB[10345]={id=10345,zoneId=3523,name="The Flesh Lies...",level=70,minLevel=68,giver="Agent Araxes",giverType="NPC",giverId=20551,ender="Agent Araxes",enderType="NPC",enderId=20551,poiX=3782,poiY=2171,wowhead="https://www.wowhead.com/wotlk/quest=10345",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You see these corpses, $r? Arconus is responsible for this slaughter. He's sucked them dry, leaving nothing more than a fleshy husk. But don't let the bodies fool you! Inside those corpses lie flesh beasts, waiting to pounce on the unsuspecting fool that gets too close.$B$BI've got my orders. I must remain here until backup arrives. That doesn't mean that you can't take my igniter and destroy the withered corpses that litter the mines. One way or another, the mission must be completed.",logDesc="Use the Protectorate Igniter on 12 Withered Corpses. Return the Protectorate Igniter to Agent Araxes outside of Access Shaft Zeon when the task is complete.$B",choiceRewards={{id=30352,qty=1},{id=30341,qty=1},{id=30342,qty=1},{id=30519,qty=1}}} end
if not DB[10346] then DB[10346]={id=10346,zoneId=3483,name="Return to the Abyssal Shelf",level=62,minLevel=58,giver="Gryphoneer Windbellow",giverType="NPC",giverId=20235,ender="Gryphoneer Windbellow",enderType="NPC",enderId=20235,poiX=295,poiY=1498,wowhead="https://www.wowhead.com/wotlk/quest=10346",image="assets/images/quests/placeholder.png",desc="$n, you've proven yourself as a capable gryphon rider, and we could use you on more sorties over the Abyssal Shelf.  What say you, $c?  Do you want some more flight time?",logDesc="Gryphoneer Windbellow at Shatter Point in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons."} end
if not DB[10347] then DB[10347]={id=10347,zoneId=3483,name="Return to the Abyssal Shelf",level=62,minLevel=58,giver="Wing Commander Brack",giverType="NPC",giverId=19401,ender="Wing Commander Brack",enderType="NPC",enderId=19401,poiX=-24,poiY=2126,wowhead="https://www.wowhead.com/wotlk/quest=10347",image="assets/images/quests/placeholder.png",desc="$n, are you ready for another sortie over the Abyssal Shelf?  I fear that, if we do not maintain pressure on the Legion forces there and allow them to strengthen their hold, then we may suffer a large demon attack from the north.$B$BWhat say you, $c?  Do you want to take another windrider and hammer the Abyssal Shelf one more time?",logDesc="Wing Commander Brack at Reaver's Fall in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons."} end
if not DB[10348] then DB[10348]={id=10348,zoneId=3523,name="New Opportunities",level=69,minLevel=67,giver="Mehrdad",giverType="NPC",giverId=20810,ender="Mehrdad",enderType="NPC",enderId=20810,poiX=3360,poiY=2894,wowhead="https://www.wowhead.com/wotlk/quest=10348",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="I hear that a group of 'druids' from Azeroth has taken quite an interest in the effects of our eco-dome technology.$B$BThe Cenarion Expedition's representatives are eager to get access to the plants growing within the domes, particularly one called the ivory bell, known for its healing properties. They're found in clumps of brush around larger plants in Eco-Dome Midrealm.$B$BI'll share the profits with you if you're willing to gather the herbs for my first delivery.",logDesc="Gather 15 Ivory Bells and return to Mehrdad at Midrealm Post."} end
if not DB[10349] then DB[10349]={id=10349,zoneId=3483,name="The Earthbinder",level=63,minLevel=61,giver="Tola'thion",giverType="NPC",giverId=19293,ender="Earthbinder Galandria Nightbreeze",enderType="NPC",enderId=19294,poiX=-311,poiY=4733,wowhead="https://www.wowhead.com/wotlk/quest=10349",image="assets/images/quests/placeholder.png",xpDiff=1,money=3000,desc="You should take the crystal lump over to the earthbinder.  She's just like you... always needing to get to the bottom of a mystery and thinking all of the time.$B$BIf you ask me, she thinks a little too much.$B$BJust give it to her and I'm sure that she'll get you into a heap of trouble figuring out what is going on up there on the ridge.",logDesc="Take the Crimson Crystal Shard to Earthbinder Galandria Nightbreeze at the Cenarion Post in Hellfire Peninsula."} end
if not DB[10350] then DB[10350]={id=10350,zoneId=-81,name="Behomat",level=10,minLevel=10,giver="Ruada",giverType="NPC",giverId=17480,ender="Behomat",enderType="NPC",enderId=17120,poiX=-4165,poiY=-12536,wowhead="https://www.wowhead.com/wotlk/quest=10350",image="assets/images/quests/placeholder.png",xpDiff=3,desc="While you have learned many hard lessons from me during our time together, it is time that I entrusted you to wiser hands.$b$bBehomat, who trained me when I was as green as grass, will be your new teacher. I have told him that you will be seeking him out, and he is expecting you.$b$bYou will find him at the center of the Warriors' Terrace, at the highest point of the Traders Tier of the Exodar.",logDesc="Speak with Behomat at the Traders Tier of the Exodar.",choiceRewards={{id=23429,qty=1},{id=23423,qty=1},{id=23431,qty=1},{id=23430,qty=1}}} end
if not DB[10351] then DB[10351]={id=10351,zoneId=3483,name="Natural Remedies",level=63,minLevel=61,giver="Earthbinder Galandria Nightbreeze",giverType="NPC",giverId=19294,ender="Earthbinder Galandria Nightbreeze",enderType="NPC",enderId=19294,poiX=-295,poiY=4715,wowhead="https://www.wowhead.com/wotlk/quest=10351",image="assets/images/quests/placeholder.png",xpDiff=6,money=58000,desc="It must be that the evil emanations from that giant crystal are summoning the mountain giants and driving them insane.$B$BIt's too big to move, and beyond our ability to destroy, but I know a way to quell its power.$B$BI've summoned a circle at the northwest corner of the crystal on the ridge.  Take this seed to the circle and channel its powers to heal the land through the natural forces of rain, growth and insect repopulation.$B$BBeware, $N, I sense an external force at play here... this is not natural!",logDesc="Use the Seed of Revitalization at the Earthbinder's Circle to heal the land around the crystal.  Then, return to Earthbinder Galandria Nightbreeze at the Cenarion Post in Hellfire Peninsula with any information that you gain.",choiceRewards={{id=28074,qty=1},{id=28075,qty=1},{id=28069,qty=1},{id=28070,qty=1}}} end
if not DB[10352] then DB[10352]={id=10352,zoneId=1657,name="A Donation of Wool",level=60,minLevel=12,giver="Raedon Duskstriker",giverType="NPC",giverId=14725,ender="Raedon Duskstriker",enderType="NPC",enderId=14725,poiX=10076,poiY=2261,wowhead="https://www.wowhead.com/wotlk/quest=10352",image="assets/images/quests/placeholder.png",xpDiff=1} end
if not DB[10353] then DB[10353]={id=10353,zoneId=3523,name="Arconus the Insatiable",level=70,minLevel=68,giver="Agent Ya-six",giverType="NPC",giverId=20552,ender="Commander Ameer",enderType="NPC",enderId=20448,poiX=3914,poiY=2087,wowhead="https://www.wowhead.com/wotlk/quest=10353",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Araxes and I were deployed to Ultris 2 days ago. Our mission: Find and terminate the void lord Arconus. We tracked him to this mine and discovered that he'd been feeding off the energies of the creatures in the area.$B$BA fire-fight broke out which resulted in Araxes and I separating. Now I'm stuck here, badly injured. The mission is in shambles!$B$BIf you can take out Arconus, high command would be grateful. Should you accept this mission, I will assist by providing a reflection of myself as a guardian.",logDesc="Agent Ya-six at Access Shaft Zeon in Netherstorm has asked you to slay Arconus the Insatiable and return to Commander Ameer at the Protectorate Watch Post in Netherstorm.",choiceRewards={{id=30329,qty=1},{id=30328,qty=1},{id=30330,qty=1},{id=30517,qty=1}}} end
if not DB[10354] then DB[10354]={id=10354,zoneId=1657,name="A Donation of Silk",level=60,minLevel=26,giver="Raedon Duskstriker",giverType="NPC",giverId=14725,ender="Raedon Duskstriker",enderType="NPC",enderId=14725,poiX=10076,poiY=2261,wowhead="https://www.wowhead.com/wotlk/quest=10354",image="assets/images/quests/placeholder.png",xpDiff=2} end
if not DB[10355] then DB[10355]={id=10355,zoneId=3521,name="Withered Flesh",level=62,minLevel=60,giver="Ruam",giverType="NPC",giverId=18007,ender="Ruam",enderType="NPC",enderId=18007,poiX=302,poiY=6025,wowhead="https://www.wowhead.com/wotlk/quest=10355",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="We must determine how far the damage has spread. The basidium you brought me comes from a bog giant. Their larger, hardier cousins, the bog lords, should prove more resistant to the degeneration that's struck the giants.$B$BIt would be good to know how the changes in the Dead Mire have affected the other creatures out there, too.$B$BReturn to the Dead Mire and see if you can get samples from the bog lords and the hydra in the area.",logDesc="Gather 5 Parched Hydra Samples and 5 Withered Bog Lord Samples and bring them to Ruam at Telredor."} end
if not DB[10356] then DB[10356]={id=10356,zoneId=3557,name="A Donation of Mageweave",level=60,minLevel=40,giver="Dugiru",giverType="NPC",giverId=20604,ender="Dugiru",enderType="NPC",enderId=20604,poiX=-4087,poiY=-11737,wowhead="https://www.wowhead.com/wotlk/quest=10356",image="assets/images/quests/placeholder.png",xpDiff=3} end
