if not DB[10364] then DB[10364]={id=10364,zoneId=-262,name="Caedmos",level=10,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=10364",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You have come far in a short time, $n. Faster than I had expected or hoped. It is time that you continued your training under the tutelage of Caedmos.$b$bI have sent word to him at the Exodar to expect you. You'll find him in the Anchorites' Sanctum near the entrance of the Vault of Lights.",logDesc="Speak with Caedmos in the Vault of Lights of the Exodar."} end
if not DB[10365] then DB[10365]={id=10365,zoneId=3523,name="Shutting Down Manaforge Ara",level=70,minLevel=67,giver="Spymaster Thalodien",giverType="NPC",giverId=19468,ender="Spymaster Thalodien",enderType="NPC",enderId=19468,poiX=3075,poiY=3699,wowhead="https://www.wowhead.com/wotlk/quest=10365",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="You've done much better than any of us anticipated.  Manaforge Ara is the last of Kael's working manaforges.  You'll find it northwest of here, though you're likely to have to do some circumnavigating to get to it.  We want you to shut it down.$B$BThe last access crystal is in the possession of Overseer Azarad.  This is Kael's very last source of energy as far as we know, so expect heavy opposition.  I'd bring a couple of friends along if I were you.$B$BHmm... Azarad.  What an odd name for a sin'dorei.",logDesc="Travel to Manaforge Ara and obtain the Ara Access Crystal from Overseer Azarad.  Use it at the Manaforge Ara console to shut it down.$B$BPerforming quests for the Scryers will cause your Aldor reputation level to decrease.",choiceRewards={{id=30366,qty=1},{id=30378,qty=1}}} end
if not DB[10366] then DB[10366]={id=10366,zoneId=-141,name="Jol",level=-1,minLevel=12,giver="Tullas",giverType="NPC",giverId=17483,ender="Jol",enderType="NPC",enderId=17509,rewardNextId=9598,poiX=-4139,poiY=-12468,wowhead="https://www.wowhead.com/wotlk/quest=10366",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The path of the Light and purity is not an easy one to walk, $n. Even I, at times, struggle with following its course.$b$bYou should seek out my master, Jol, at the Exodar. She trained me when I was beginning my journey, and I believe she will find in you a new star pupil.$b$bYou will find Jol in the Vault of Lights of the Exodar at the Vindicators' Sanctum, a room surrounded by a vibrant glow of light.",logDesc="Speak with Jol in the Vindicators' Sanctum of the Exodar."} end
if not DB[10367] then DB[10367]={id=10367,zoneId=3483,name="A Traitor Among Us",level=62,minLevel=60,giver="Naladu",giverType="NPC",giverId=19361,ender="Naladu",enderType="NPC",enderId=19361,rewardNextId=10368,poiX=-760,poiY=4699,wowhead="https://www.wowhead.com/wotlk/quest=10367",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Anywhere you see a tribe of enslaved Broken you will also find a traitor.  A despicable being who sold his brothers for promises of power.$B$BThere is a hut at the top of the stairs in the center of the ruins.  That's the turncoat's hut.$B$BHe's not there right now, so you will be able to sneak in if you're patient.  Inside you will find a coffer with a key inside of it.  That key unlocks the chains that keep the Dreghood elders prisoner.  Bring it to me.$B$BBeware, Arzeth the Merciless wanders nearby.",logDesc="Naladu at the Ruins of Sha'naar wants you to obtain the Sha'naar Key from a nearby hut."} end
if not DB[10368] then DB[10368]={id=10368,zoneId=3483,name="The Dreghood Elders",level=62,minLevel=60,giver="Naladu",giverType="NPC",giverId=19361,ender="Naladu",enderType="NPC",enderId=19361,rewardNextId=10369,poiX=-760,poiY=4699,wowhead="https://www.wowhead.com/wotlk/quest=10368",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Dreghood spirit is broken because our elders are imprisoned.  Take this key and go downstairs to free them.$B$BThey are Morod the Windstirrer, Akoru the Firecaller and Aylaan the Waterwaker.  Once they are free, the spirits will return to the Dreghood tribe.",logDesc="Free Morod the Windstirrer, Akoru the Firecaller and Aylaan the Waterwaker at the Ruins of Sha'naar.  Return to Naladu after completing this task."} end
if not DB[10369] then DB[10369]={id=10369,zoneId=3483,name="Arzeth's Demise",level=62,minLevel=60,giver="Naladu",giverType="NPC",giverId=19361,ender="Naladu",enderType="NPC",enderId=19361,poiX=-760,poiY=4699,wowhead="https://www.wowhead.com/wotlk/quest=10369",image="assets/images/quests/placeholder.png",xpDiff=6,money=54000,desc="Yes, the elemental spirits have returned to us!  We are not as strong as we once were, but a little magic can go a long way in the right hands.$B$BArzeth has great powers bestowed upon him by his dark lord.  Take this staff.  It was once a great symbol of our tribe.  Use it against Arzeth and his powers will be temporarily removed from him.  Defeat him then, so that my people may finally be free!",logDesc="Use the Staff of Dreghood Elders on Arzeth the Merciless and slay him after he's lost his powers.  Return to Naladu at the Ruins of Sha'naar after completing this task."} end
if not DB[10370] then DB[10370]={id=10370,zoneId=3483,name="Nazgrel's Command <TXT>",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=10370",image="assets/images/quests/placeholder.png"} end
if not DB[10371] then DB[10371]={id=10371,zoneId=-81,name="Yorus Barleybrew",level=20,minLevel=20,giver="Ahonan",giverType="NPC",giverId=16771,ender="Yorus Barleybrew",enderType="NPC",enderId=6166,rewardNextId=1699,poiX=-4199,poiY=-11649,wowhead="https://www.wowhead.com/wotlk/quest=10371",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A dwarven warrior known as Yorus Barleybrew has issued a challenge to all skilled Alliance warriors.$B$BHe waits at the Lakeshire Inn, in a place known as the Redridge Mountains in the Eastern Kingdoms.  The journey will be long, but it'll be worth it for you to test yourself, $N.",logDesc="Speak with Yorus Barleybrew at the Lakeshire Inn in Redridge Mountains."} end
if not DB[10372] then DB[10372]={id=10372,zoneId=-162,name="A Discreet Inquiry",level=16,minLevel=16,giver="Zelanis",giverType="NPC",giverId=16684,ender="Eralan",enderType="NPC",enderId=16268,rewardNextId=9491,poiX=9733,poiY=-7366,wowhead="https://www.wowhead.com/wotlk/quest=10372",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Eralan, an associate of mine in Tranquillien, has made an inquiry about securing some help for an urgent job.$B$BNow, I don't know what she has in mind because I don't ask questions, but you've proven yourself more than capable. I want you to travel to Tranquillien in the Ghostlands and have a word with Eralan.$B$BShe may be a bit gruff, but she's trustworthy.",logDesc="Speak with Eralan in Tranquillien."} end
if not DB[10373] then DB[10373]={id=10373,zoneId=3557,name="A Call to Arms: The Plaguelands!",level=50,minLevel=50,giver="Herald Bran'daan",giverType="NPC",giverId=20722,ender="Commander Ashlam Valorfist",enderType="NPC",enderId=10838,rewardNextId=5092,poiX=-3943,poiY=-11652,wowhead="https://www.wowhead.com/wotlk/quest=10373",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hear ye, hear ye!  All heroes are called upon to heed these words!$B$BA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!$B$BHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!",logDesc="Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains."} end
if not DB[10374] then DB[10374]={id=10374,zoneId=28,name="A Call to Arms: The Plaguelands!",level=50,minLevel=50,giver="Herald Amorlin",giverType="NPC",giverId=20724,ender="High Executor Derrington",enderType="NPC",enderId=10837,rewardNextId=5096,poiX=9631,poiY=-7119,wowhead="https://www.wowhead.com/wotlk/quest=10374",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Heroes of the realm, hear me - the Horde calls upon you for swift action!$B$BA call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands!$B$BHeroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glade!",logDesc="Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity."} end
if not DB[10375] then DB[10375]={id=10375,zoneId=3518,name="Obsidian Warbeads",level=67,minLevel=65,wowhead="https://www.wowhead.com/wotlk/quest=10375",image="assets/images/quests/placeholder.png",desc="You've proven yourself to our people, $N.  Now is time for you to show us that you're willing to stand by us, even in the face of the strongest enemy.$B$BThe ogres of Outland are "} end
