if not DB[10377] then DB[10377]={id=10377,zoneId=-262,name="Nothing to Fear",level=20,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=10377",image="assets/images/quests/placeholder.png"} end
if not DB[10378] then DB[10378]={id=10378,zoneId=-262,name="Consume Magic",level=20,minLevel=20,wowhead="https://www.wowhead.com/wotlk/quest=10378",image="assets/images/quests/placeholder.png"} end
if not DB[10379] then DB[10379]={id=10379,zoneId=-262,name="Touch of Weakness",level=10,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=10379",image="assets/images/quests/placeholder.png"} end
if not DB[10380] then DB[10380]={id=10380,zoneId=3523,name="A Dark Pact",level=70,minLevel=67,giver="Kaylaan",giverType="NPC",giverId=20780,ender="Kaylaan",enderType="NPC",enderId=20780,rewardNextId=10381,poiX=4033,poiY=3543,wowhead="https://www.wowhead.com/wotlk/quest=10380",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We've been so blind, $N, that the alliance of two of our most dangerous enemies went completely unnoticed.$B$BI wouldn't be surprised if the Scryers had something to do with hiding this information from us, but we must now face the reality.  The Burning Legion and Kael'thas' Sunfury army serve under the same banner.$B$BThese demons are the only reason Kael'thas was ever able to utilize the technology in Tempest Keep.  Under Orelis's orders I must command you to destroy them.",logDesc="Kaylaan at Tuluman's Landing in Netherstorm wants you to slay 6 Gan'arg Warp-Tinkers, 3 Daughters of Destiny and 3 Mo'arg Warp-Masters.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10381] then DB[10381]={id=10381,zoneId=3523,name="Aldor No More",level=70,minLevel=67,giver="Kaylaan",giverType="NPC",giverId=20780,ender="Exarch Orelis",enderType="NPC",enderId=19466,poiX=4033,poiY=3543,wowhead="https://www.wowhead.com/wotlk/quest=10381",image="assets/images/quests/placeholder.png",xpDiff=4,desc="My mission here is finished.  I did what Orelis ordered me to - I've never failed to.$B$BNo more.  I foresee a great carnage - a crusade, they'll call it - following the news of this alliance between Kael'thas and the Burning Legion.$B$BFirst they give our holiest city away to our enemies and then they ask us to die fighting their enemies.  Go back to Orelis; tell him the naaru can fight their own fights from now on.",logDesc="Report back to Exarch Orelis at Area 52.$B$BPerforming quests for the Aldor will cause your Scryers reputation level to decrease.",choiceRewards={{id=30382,qty=1},{id=30379,qty=1},{id=30381,qty=1},{id=30380,qty=1}}} end
if not DB[10382] then DB[10382]={id=10382,zoneId=3483,name="Go to the Front",level=61,minLevel=58,giver="Wing Commander Gryphongar",giverType="NPC",giverId=20232,ender="Field Marshal Brock",enderType="NPC",enderId=20793,rewardNextId=10394,poiX=315,poiY=1442,wowhead="https://www.wowhead.com/wotlk/quest=10382",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Well, $N, I hope you're prepared for the next phase of our operation. The Legion never rests - and neither shall we! Take a gryphon and fly over to Honor Point - it's a small post near the Legion Front. $B$BSpeak with Field Marshal Brock. He'll have instructions for you when you arrive. Oh, and tell that pasty-faced shield-kisser I said 'hello'.  $B",logDesc="Take a gryphon to Honor Point and speak with Field Marshal Brock."} end
if not DB[10383] then DB[10383]={id=10383,zoneId=0,name="This is a Breadcrumb!",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=10383",image="assets/images/quests/placeholder.png",desc="Hello.  You should find out about those wabbits.",logDesc="Speak with Jonathan LeCraft about the wabbits."} end
if not DB[10384] then DB[10384]={id=10384,zoneId=3523,name="Ethereum Data",level=70,minLevel=68,giver="Image of Commander Ameer",giverType="NPC",giverId=20482,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,rewardNextId=10385,wowhead="https://www.wowhead.com/wotlk/quest=10384",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Look around you, fleshling. Very close to this transponder should be an Ethereum data cell. Locate that data cell, open it, and retrieve the contents.$B$BBring it back to this transponder at once!",logDesc="The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to recover the Ethereum Data Cell."} end
if not DB[10385] then DB[10385]={id=10385,zoneId=3523,name="Potential for Brain Damage = High",level=70,minLevel=68,giver="Image of Commander Ameer",giverType="NPC",giverId=20482,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,rewardNextId=10405,wowhead="https://www.wowhead.com/wotlk/quest=10385",image="assets/images/quests/placeholder.png",xpDiff=5,desc="They're using relays to transfer information around the staging grounds.$B$BThere is only one way for you to see these relays and extract the information they hold. Unfortunately, doing so may cause you irreparable brain damage.$B$BIf you're still interested, you'll need to slay Ethereum here at the staging grounds and take their essences. Once you have an essence, drink it down. It will temporarily allow you to see an Ethereum relay - giving you enough time to destroy a relay and extract its information.",logDesc="The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to recover 15 pieces of Ethereum Relay Data."} end
if not DB[10386] then DB[10386]={id=10386,zoneId=0,name="The Fel Reaver Slayer",level=61,minLevel=58,rewardNextId=10089,wowhead="https://www.wowhead.com/wotlk/quest=10386",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Overlord Hun Maimfist is always looking for volunteers for his suicide attacks against the Burning Legion.  You definitely have the courage for one of his \"missions.\"  $B$BSpeak with him if you've got the stomach for more carnage.  He is celebrating just over there by that fallen fel reaver.  He and his guards killed it just a few hours ago, we would all have died here but for his ferocity and skill in battle.",logDesc="Speak with Overlord Hun Maimist."} end
if not DB[10387] then DB[10387]={id=10387,zoneId=0,name="The Fel Reaver Slayer",level=61,minLevel=58,rewardNextId=10089,wowhead="https://www.wowhead.com/wotlk/quest=10387",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Overlord Hun Maimfist is always looking for volunteers for his suicide attacks against the Burning Legion.  You definitely have the courage for one of his \"missions.\"  $B$BSpeak with him if you've got the stomach for more carnage.  He is celebrating just over there by that fallen fel reaver.  He and his guards killed it just a few hours ago, we would all have died here but for his ferocity and skill in battle.",logDesc="Speak with Overlord Hun Maimist."} end
if not DB[10388] then DB[10388]={id=10388,zoneId=3483,name="Return to Thrallmar",level=61,minLevel=58,giver="Overlord Hun Maimfist",giverType="NPC",giverId=16576,ender="Nazgrel",enderType="NPC",enderId=3230,rewardNextId=10390,poiX=-43,poiY=2181,wowhead="https://www.wowhead.com/wotlk/quest=10388",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hope you enjoyed your flight, friend. A messenger arrived while you were away - seems Nazgrel's got a new use for you. You'd best head back to Thrallmar and check in with him. I have a feeling the Legion's just getting warmed up. $B",logDesc="Return to Thrallmar and speak with Nazgrel.$B"} end
if not DB[10389] then DB[10389]={id=10389,zoneId=3483,name="The Agony and the Darkness",level=61,minLevel=58,giver="Magister Bloodhawk",giverType="NPC",giverId=21175,ender="Magister Bloodhawk",enderType="NPC",enderId=21175,poiX=240,poiY=2693,wowhead="https://www.wowhead.com/wotlk/quest=10389",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Greetings, $N. I've deciphered the Legion missive and uncovered the demons' strategic plans for this Peninsula. Apparently, there is a large group of hellish terrorfiends gathering near the Pools of Aggonar in the west. We cannot allow such a force to go unchallenged. You must go there and decimate their cursed numbers. ",logDesc="Magister Bloodhawk wants you to kill 10 Terrorfiends in the Pools of Aggonar."} end
if not DB[10390] then DB[10390]={id=10390,zoneId=3483,name="Forge Camp: Mageddon",level=61,minLevel=58,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Nazgrel",enderType="NPC",enderId=3230,rewardNextId=10391,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=10390",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="$N, we have reason to believe that the easternmost forge camp is not yet complete. The Legion's gan'arg servants are working 'round the clock to get the facility up and running. We can't allow that to happen. $B$BHead east to Forge Camp: Mageddon and slay 10 gan'arg. Bring me the head of their master - Razorsaw - and the Legion's fel reaver production will grind to a halt!   $B$B",logDesc="Nazgrel in Thrallmar wants you to attack Forge Camp: Mageddon and kill 10 Gan'arg Servants and return with the head of Razorsaw."} end
if not DB[10391] then DB[10391]={id=10391,zoneId=3483,name="Cannons of Rage",level=61,minLevel=58,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Nazgrel",enderType="NPC",enderId=3230,rewardNextId=10392,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=10391",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="There is a second production facility, Forge Camp: Rage, that lies to the immediate northeast of Thrallmar. The demons have positioned a number of their fel cannons along the ridge - and they're aimed straight at us! You must enter the camp and destroy these fel cannons. $B$B$N, you must be sure to detonate them all - or nothing will stop the Legion from raining fiery hell down upon our heads!  $B",logDesc="Destroy 3 Fel Cannon MKIs in Forge Camp: Rage and return to Nazgrel in Thrallmar."} end
if not DB[10392] then DB[10392]={id=10392,zoneId=3483,name="Doorway to the Abyss",level=61,minLevel=58,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Nazgrel",enderType="NPC",enderId=3230,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=10392",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="You are an honor to us, $N. But now we must strike before the Legion recovers! To the north of Thrallmar lies Invasion Point: Annihilator. It houses a warp-portal through which the Legion draws its reinforcements. $B$BYou must overload that portal - and blast it back to the abyss it came from. The portal's activation key will be held by the Point's commander - Warbringer Arix'Amal. Slay him. Take the key. Use it on the portal and do what must be done. May the warchief's blessings be with you.   ",logDesc="Slay Arix'Amal to get the Burning Legion Gate Key.  Use the Burning Legion Gate Key on the Rune of Spite, then return to Nazgrel in Thrallmar."} end
if not DB[10393] then DB[10393]={id=10393,zoneId=3483,name="Vile Plans",level=61,minLevel=58,ender="Magister Bloodhawk",enderType="NPC",enderId=21175,wowhead="https://www.wowhead.com/wotlk/quest=10393",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The text on the note is written in some dark, indecipherable scrawl. The more you stare at them, the more the symbols seem to twist and burn before your eyes. There is only one in Thrallmar that can transcribe such vile script - the blood elf Magister Bloodhawk. $B$B",logDesc="Take the Burning Legion Missive to Magister Bloodhawk in Thrallmar. "} end
if not DB[10394] then DB[10394]={id=10394,zoneId=3483,name="Disruption - Forge Camp: Mageddon",level=61,minLevel=58,giver="Field Marshal Brock",giverType="NPC",giverId=20793,ender="Field Marshal Brock",enderType="NPC",enderId=20793,rewardNextId=10396,poiX=498,poiY=2013,wowhead="https://www.wowhead.com/wotlk/quest=10394",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Pay close attention, $N. We've been surveying the Legion camps that lie along the ridge ahead. We have reason to believe that these so-called 'Forge Camps' are where the demons are constructing those blasted Fel Reavers. $B$BYou can see the closest target, Forge Camp: Mageddon, to the west. Our intelligence suggests that it's still under construction. If you can slay the Gan'arg Servants and their master - Razorsaw - we can bring the Legion's Fel Reaver production to a grinding halt!   $B$B",logDesc="Kill 10 Gan'arg Servants and Razorsaw at Forge Camp Mageddon and return to Forward Commander Brock at Honor Point."} end
if not DB[10395] then DB[10395]={id=10395,zoneId=3483,name="The Dark Missive",level=61,minLevel=58,ender="Warp-Scryer Kryv",enderType="NPC",enderId=16839,rewardNextId=10399,wowhead="https://www.wowhead.com/wotlk/quest=10395",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The text on the note is written in some dark, indecipherable scrawl. The more you stare at them, the more the symbols seem to twist and burn before your eyes. There is only one at Honor Hold who can decipher such archaic script - the draenei mystic, Kryv. $B$BTake the Burning Legion Missive to Warp-Scryer Kryv who resides within the War-Room at Honor Hold.$B",logDesc="Take the Missive to Warp-Scryer Kryv in the main keep of Honor Hold."} end
if not DB[10396] then DB[10396]={id=10396,zoneId=3483,name="Enemy of my Enemy...",level=61,minLevel=58,giver="Field Marshal Brock",giverType="NPC",giverId=20793,ender="Field Marshal Brock",enderType="NPC",enderId=20793,rewardNextId=10397,poiX=498,poiY=2013,wowhead="https://www.wowhead.com/wotlk/quest=10396",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Now we focus on the second target - Forge Camp: Rage. It lies just west of Mageddon. Trouble is, the demons have a number of fel cannons aimed straight at the Horde's outpost of Thrallmar! Though I can scarcely believe it, we actually need the Horde to help us hold the line at the Dark Portal. We can't afford to let Thrallmar fall.  You've got to destroy these cannons before the Legion pulverizes our allies! ",logDesc="Destroy 3 Fel Cannon MKIs in Forge Camp: Rage and return to Field Marshal Brock at Honor Point."} end
if not DB[10397] then DB[10397]={id=10397,zoneId=3483,name="Invasion Point: Annihilator",level=61,minLevel=58,giver="Field Marshal Brock",giverType="NPC",giverId=20793,ender="Field Marshal Brock",enderType="NPC",enderId=20793,poiX=498,poiY=2013,wowhead="https://www.wowhead.com/wotlk/quest=10397",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Well, we've located the Legion's final base on the ridge - Invasion Point: Annihilator. It lies northwest of Forge Camp: Rage - and it houses a warp-portal through which the Legion has been drawing its reinforcements! $B$BYou've got to close that portal to prevent any more demons from coming through. The Point's overlord, Warbringer Arix'Amal, holds the portal's activation key. Take it from him and shut that blasted gateway down!  $B",logDesc="Slay Arix'Amal.  Take the Burning Legion Gate Key.  Use the Burning Legion Gate Key on the Rune of Spite."} end
if not DB[10398] then DB[10398]={id=10398,zoneId=3483,name="Return to Honor Hold",level=61,minLevel=255,rewardNextId=10400,wowhead="https://www.wowhead.com/wotlk/quest=10398",image="assets/images/quests/placeholder.png",xpDiff=5,desc="PH: Go to Honor Hold.",logDesc="PH:  Go to Honor Hold."} end
if not DB[10399] then DB[10399]={id=10399,zoneId=3483,name="The Heart of Darkness",level=61,minLevel=58,giver="Warp-Scryer Kryv",giverType="NPC",giverId=16839,ender="Warp-Scryer Kryv",enderType="NPC",enderId=16839,poiX=-809,poiY=2612,wowhead="https://www.wowhead.com/wotlk/quest=10399",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="It is just as I feared. Arix'Amal - the demon you killed earlier, was working for a secret Legionlord - Arazzius the Cruel. It appears this new villain has amassed a force of hellish terrorfiends near the Pools of Aggonar. $B$BYou must journey there and slay the terrorfiends before they strike against us. But be wary, friend - the Pools of Aggonar lie within a tortured, poisonous valley. You can find the cursed pools to the northwest of here, beyond Hellfire Citadel. $B$BLight be with you, $N.  $B",logDesc="Kill 10 Terrorfiends in the Pools of Aggonar and return to Warp-Scryer Kryv in the main keep of Honor Hold."} end
if not DB[10400] then DB[10400]={id=10400,zoneId=3483,name="Overlord",level=63,minLevel=58,giver="Force Commander Danath Trollbane",giverType="NPC",giverId=16819,ender="Force Commander Danath Trollbane",enderType="NPC",enderId=16819,poiX=-816,poiY=2614,wowhead="https://www.wowhead.com/wotlk/quest=10400",image="assets/images/quests/placeholder.png",xpDiff=7,money=87000,desc="The honorable Warp-Scryer has told me of your perils, $N - and of the new foe you've discovered. If Kryv is to be believed, this 'Arazzius the Cruel' is as powerful and evil as any foe the Sons of Lothar have ever faced. $B$BWill you stand for us now, $N? Will you face this Legionlord and deliver the Light's justice upon him? If so, you will find him at the Pools of Aggonar. If not, his evil will most certainly find you. $B",logDesc="Slay Arazzius the Cruel in the Pools of Aggonar and return to Force Commander Danath Trollbane in the keep of Honor Hold.$B",choiceRewards={{id=28040,qty=1},{id=28041,qty=1},{id=28042,qty=1}}} end
if not DB[10401] then DB[10401]={id=10401,zoneId=3483,name="Mission: End All, Be All",level=63,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10401",image="assets/images/quests/placeholder.png",xpDiff=7,money=87000,desc="Do you know what would have happened if you had not intercepted this missive, $N?$B$B<Nazgrel nods.>$B$BThe entirety of the Legion army in Hellfire would have been knocking on our door. There is no way that we could have survived such an assault.$B$BThere is only one way to make sure that these orders never reach the Legion Front. You must travel to the Pools of Aggonar, west of here, and slay this Arazzius creature.$B$BDo this and I will see to it that the Warchief grants you a commendation.",logDesc="Nazgrel at Thrallmar in Hellfire Peninsula has asked that you slay Arazzius the Cruel.$B",choiceRewards={{id=28040,qty=1},{id=28041,qty=1},{id=28042,qty=1}}} end
if not DB[10402] then DB[10402]={id=10402,zoneId=3523,name="<TXT>",level=70,minLevel=67,wowhead="https://www.wowhead.com/wotlk/quest=10402",image="assets/images/quests/placeholder.png"} end
if not DB[10403] then DB[10403]={id=10403,zoneId=3483,name="Naladu",level=62,minLevel=60,giver="Morod the Windstirrer",giverType="NPC",giverId=20677,ender="Naladu",enderType="NPC",enderId=19361,rewardNextId=10367,poiX=-621,poiY=4862,wowhead="https://www.wowhead.com/wotlk/quest=10403",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Perhaps not all hope is lost for the Dreghood.  I am one of four elders that guided this tribe before we were enslaved by the Illidari.  I thought the others were dead, but I've slowly learned that at least two others are alive - chained down and powerless just as I am.$B$BI've not yet been able to find Naladu and fear for the worst.  There are more huts in the ruins upstairs; perhaps you could look for him.  It would be a great boon for our tribe if all our elders were alive.",logDesc="Seek out Naladu inside the Ruins of Sha'naar."} end
if not DB[10404] then DB[10404]={id=10404,zoneId=3523,name="Against the Legion",level=70,minLevel=67,wowhead="https://www.wowhead.com/wotlk/quest=10404",image="assets/images/quests/placeholder.png",xpDiff=6,desc="We've established that the Burning Legion has been providing Kael'thas with technological assistance, magnifying his threat many times over.$B$BBased on the Legion's numbers in the region, the largest impact we can make on our enemy's alliance is through a head-on attack on the forge bases to the north.$B$BGo to Forge Base: Oblivion and Forge Base: Gehenna and destroy our enemies.  May the Light guide your blade, $N.",logDesc="Exarch Orelis at Area 52 wants you to go to Forge Base: Oblivion and Forge Base: Gehenna and slay 12 Gan'arg Forgehands, 6 Mo'arg Forgelords and 6 Wrathbringers.$B$BPerforming quests for the Aldor will cause your Scryers reputation to decrease."} end
if not DB[10405] then DB[10405]={id=10405,zoneId=3523,name="S-A-B-O-T-A-G-E",level=70,minLevel=68,giver="Image of Commander Ameer",giverType="NPC",giverId=20482,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,rewardNextId=10406,wowhead="https://www.wowhead.com/wotlk/quest=10405",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We must destroy the machinery that is making these nexus-stalker aberrations possible. To strike at their proto-accelerator would be futile as it is an ethereal creation. We must instead destroy the manaforge energy tube that they are using as a conduit.$B$BI have all that I need to create a device to overload the conduit save for one item. I need a wrapping from an archon or overlord that might be transforming soon in order to calibrate the device.",logDesc="The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to recover 1 Prepared Ethereum Wrapping."} end
if not DB[10406] then DB[10406]={id=10406,zoneId=3523,name="Delivering the Message",level=70,minLevel=68,giver="Image of Commander Ameer",giverType="NPC",giverId=20482,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,rewardNextId=10408,wowhead="https://www.wowhead.com/wotlk/quest=10406",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'm sending one of my demolitionists out to place the disruption device. Just make sure no harm comes to him as he's placing the disruptor.$B$BKeep him protected! He will not fight back if enemies attack him as he is only a holographic image but the image can be destroyed!$B$BReturn to me once the job is done.$B",logDesc="The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to escort the Protectorate Demolitionist to the Manaforge Ultris conduit and keep him protected while he works to sabotage the pipeline.",choiceRewards={{id=30335,qty=1},{id=30337,qty=1},{id=30336,qty=1},{id=30518,qty=1}}} end
if not DB[10407] then DB[10407]={id=10407,zoneId=3523,name="Socrethar's Shadow",level=70,minLevel=67,giver="Anchorite Karja",giverType="NPC",giverId=19467,ender="Anchorite Karja",enderType="NPC",enderId=19467,rewardNextId=10410,poiX=3071,poiY=3697,wowhead="https://www.wowhead.com/wotlk/quest=10407",image="assets/images/quests/placeholder.png",xpDiff=6,money=44000,desc="The infamous eredar, Socrethar, leads the Burning Legion in Netherstorm.  Mentioning his name is enough to make most draenei shudder.  He gives orders from an island in the northwest that only his most trusted lieutenants can access.$B$BTo get there you will need to obtain a teleportation stone, which won't be an easy task.  The first half of the stone is in the possession of Forgemaster Morug at Forge Base: Oblivion.  The second half is held by Silroth at Forge Base: Gehenna.",logDesc="Anchorite Karja at Area 52 wants you to obtain the First Half of Socrethar's Stone from Forgemaster Morug at Forge Base: Oblivion and the Second Half of Socrethar's Stone from Silroth at Forge Base: Gehenna.$B$BPerforming quests for the Aldor will cause your Scryers reputation to decrease."} end
if not DB[10408] then DB[10408]={id=10408,zoneId=3523,name="Nexus-King Salhadaar",level=70,minLevel=68,giver="Image of Commander Ameer",giverType="NPC",giverId=20482,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,wowhead="https://www.wowhead.com/wotlk/quest=10408",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="I have in my possession another disruptor, one capable of destroying the three conduits that surround Salhadaar. Once the conduits are destroyed, Salhadaar's protective force fields will be down. For this act, he will strike at you with a ferocity you have never before witnessed, $N.$B$BIf you are willing to rid the world of Salhadaar, I will give you the disruptor.",logDesc="The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to use the Protectorate Disruptor to bring down Salhadaar's force fields and then destroy Nexus-King Salhadaar.",choiceRewards={{id=30011,qty=1},{id=30012,qty=1},{id=30010,qty=1},{id=30013,qty=1},{id=30009,qty=1}}} end
if not DB[10409] then DB[10409]={id=10409,zoneId=3523,name="Deathblow to the Legion",level=70,minLevel=67,giver="Ishanah",giverType="NPC",giverId=18538,ender="Ishanah",enderType="NPC",enderId=18538,poiX=-1733,poiY=5822,wowhead="https://www.wowhead.com/wotlk/quest=10409",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="When facing eredar of great power, large armies are useless for the most part.  Their corruptive powers over mortal souls are such that only the strongest-willed can even stand face to face with them.$B$BTake this stone to the Invasion Point: Overlord, between Forge Base: Oblivion and Gehenna and bring your closest, strongest friends with you.  Orelis and Karja will meet you at Socrethar's Seat; I will send Adyen along with them.$B$BMay the Light prevail today, $N.  May Socrethar meet his end.",logDesc="High Priestess Ishanah wants you to go to the Legion Teleporter at the northwestern corner of Netherstorm and use it to teleport to Socrethar's Seat.  Once there, defeat Socrethar.$B$BPerforming quests for the Aldor will cause your Scryers reputation to decrease.",choiceRewards={{id=30368,qty=1},{id=30369,qty=1},{id=30370,qty=1},{id=30371,qty=1},{id=30860,qty=1}}} end
if not DB[10410] then DB[10410]={id=10410,zoneId=3523,name="Ishanah's Help",level=70,minLevel=67,giver="Anchorite Karja",giverType="NPC",giverId=19467,ender="Ishanah",enderType="NPC",enderId=18538,rewardNextId=10409,poiX=3071,poiY=3697,wowhead="https://www.wowhead.com/wotlk/quest=10410",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The time has come to face Socrethar, $N.  Confronting an eredar leader isn't something that's taken lightly among us.  A single mistake is likely to cost us our lives if we're ill-prepared.$B$BTake Socrethar's teleportation stone to High Priestess Ishanah at the Shrine of Unending Light in Shattrath City.  She will determine how we need to handle the situation.",logDesc="Take Socrethar's Teleportation Stone to High Priestess Ishanah at the Shrine of Unending Light on the Aldor Rise in Shattrath City.$B$BPerforming quests for the Aldor will cause your Scryers reputation to decrease."} end
if not DB[10411] then DB[10411]={id=10411,zoneId=3523,name="Electro-Shock Goodness!",level=70,minLevel=68,giver="Researcher Navuud",giverType="NPC",giverId=20449,ender="Researcher Navuud",enderType="NPC",enderId=20449,poiX=4245,poiY=2180,wowhead="https://www.wowhead.com/wotlk/quest=10411",image="assets/images/quests/placeholder.png",xpDiff=5,money=132000,desc="Around the ruined manaforge you will find the run-off of Dimensius's handy work. Seeping sludge occupies the pools that surround Ultris. Directly below those pools, where the Ethereum Staging Grounds now stand, you will find even more run-off in the form of void waste.$B$BThe best method of disposal is to use electro-shock to break slimes down to globules. Use this elixir to augment your attacks with electricity. The resultant discharge will break the slimes up into their raw form. Destroy the globules!",logDesc="Researcher Navuud at the Protectorate Watch Post in Netherstorm has asked that you destroy 30 Void Waste Globules and 30 Seeping Sludge Globules.$B"} end
if not DB[10412] then DB[10412]={id=10412,zoneId=3703,name="Firewing Signets",level=65,minLevel=62,giver="Magistrix Fyalenn",giverType="NPC",giverId=18531,ender="Magistrix Fyalenn",enderType="NPC",enderId=18531,poiX=-2183,poiY=5545,wowhead="https://www.wowhead.com/wotlk/quest=10412",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is no secret that Kael'thas Sunstrider perceives us as a great threat.  Let's face it - not many sin'dorei, fresh from Silvermoon, are willing to join the sort of company that Kael keeps.$B$BIt's also no secret that this is not just a war of words.  Scryers and the armies that serve Kael'thas attack each other on sight.  The only way to prove you're with us, $N, is to do your share of fighting.$B$BKael's lower ranking followers wear Firewing signets to indicate their rank.  Bring them to me.",logDesc="Magistrix Fyalenn in Shattrath City wants you to bring her 10 Firewing Signets.$B$BPerforming quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10413] then DB[10413]={id=10413,zoneId=3523,name="The Horrors of Pollution",level=70,minLevel=68,ender="Researcher Navuud",enderType="NPC",enderId=20449,wowhead="https://www.wowhead.com/wotlk/quest=10413",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="You carefully fill a vial with the fallen void horror's ooze.$B$BResearcher Navuud at the Protectorate Watch Post would be quite interested in such a find! Take it to him at once!",logDesc="Take the Vial of Void Horror Ooze to Researcher Navuud at the Protectorate Watch Post in Netherstorm.",choiceRewards={{id=30338,qty=1},{id=30339,qty=1},{id=30340,qty=1}}} end
if not DB[10414] then DB[10414]={id=10414,zoneId=3703,name="Single Firewing Signet",level=70,minLevel=64,giver="Magistrix Fyalenn",giverType="NPC",giverId=18531,ender="Magistrix Fyalenn",enderType="NPC",enderId=18531,poiX=-2183,poiY=5545,wowhead="https://www.wowhead.com/wotlk/quest=10414",image="assets/images/quests/placeholder.png"} end
if not DB[10415] then DB[10415]={id=10415,zoneId=3703,name="More Firewing Signets",level=70,minLevel=64,giver="Magistrix Fyalenn",giverType="NPC",giverId=18531,ender="Magistrix Fyalenn",enderType="NPC",enderId=18531,poiX=-2183,poiY=5545,wowhead="https://www.wowhead.com/wotlk/quest=10415",image="assets/images/quests/placeholder.png"} end
if not DB[10416] then DB[10416]={id=10416,zoneId=3703,name="Synthesis of Power",level=70,minLevel=64,giver="Voren'thal the Seer",giverType="NPC",giverId=18530,ender="Voren'thal the Seer",enderType="NPC",enderId=18530,poiX=-2273,poiY=5576,wowhead="https://www.wowhead.com/wotlk/quest=10416",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Arcane tomes are not ordinary books that happen to deal with arcane matters.  There is intrinsic power in them - a power I've learned to synthesize into a single arcane rune.$B$BShould you find an arcane tome in your travels I will give you one such rune.  Only the most powerful wielders of magic carry the books I need.  In Outland this usually means Kael's blood elves - but you'd be surprised by where such tomes often turn up.",logDesc="Voren'thal the Seer in Shattrath City wants you to obtain an Arcane Tome.$B$BPerforming quests for the Scryers will cause your Aldor reputation to decrease.",rewards={{id=29736,qty=1}}} end
if not DB[10417] then DB[10417]={id=10417,zoneId=3523,name="Run a Diagnostic!",level=68,minLevel=67,giver="Mehrdad",giverType="NPC",giverId=20810,ender="Mehrdad",enderType="NPC",enderId=20810,rewardNextId=10418,poiX=3360,poiY=2894,wowhead="https://www.wowhead.com/wotlk/quest=10417",image="assets/images/quests/placeholder.png",xpDiff=3,money=39000,desc="Wherever the Consortium establishes a presence, we bring our eco-dome technology. The fields allow us to work in a controlled and life-sustaining atmosphere since we often find ourselves in hostile environments.$B$BNetherstorm's volatile conditions and creatures have begun to destroy the equipment that sustains our domes, especially the generator east of here. I've started a diagnostic there in hopes of understanding what can be done to combat the damage. Would you collect the results and bring them to me?",logDesc="Retrieve the Diagnostic Results and return them to Mehrdad at Midrealm Post."} end
if not DB[10418] then DB[10418]={id=10418,zoneId=3523,name="Deal With the Saboteurs",level=68,minLevel=67,giver="Mehrdad",giverType="NPC",giverId=20810,ender="Mehrdad",enderType="NPC",enderId=20810,rewardNextId=10423,poiX=3360,poiY=2894,wowhead="https://www.wowhead.com/wotlk/quest=10418",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="In searching the area for clues about the damage to our equipment, I've seen pieces of the shield generators at the bottom of the small lake to the north. I'm not sure why the crocolisks have taken an interest in the equipment, but we have to put a stop to this problem.$B$BThe Consortium is quite clear on this matter. If it comes down to a choice between the equipment and crocolisks, the animals will have to go. I'll make it worth your while to deal with them.",logDesc="Mehrdad at Midrealm Post wants you to kill 8 Barbscale Crocolisks."} end
if not DB[10419] then DB[10419]={id=10419,zoneId=3703,name="Arcane Tomes",level=70,minLevel=64,giver="Voren'thal the Seer",giverType="NPC",giverId=18530,ender="Voren'thal the Seer",enderType="NPC",enderId=18530,poiX=-2273,poiY=5576,wowhead="https://www.wowhead.com/wotlk/quest=10419",image="assets/images/quests/placeholder.png",rewards={{id=29736,qty=1}}} end
if not DB[10420] then DB[10420]={id=10420,zoneId=3703,name="A Cleansing Light",level=70,minLevel=64,giver="Ishanah",giverType="NPC",giverId=18538,ender="Ishanah",enderType="NPC",enderId=18538,poiX=-1733,poiY=5822,wowhead="https://www.wowhead.com/wotlk/quest=10420",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This temple is one of the holiest places in all of Outland.  The power of the Light here is so strong, that even items with the strongest fel taint can be cleansed of a worldly item.$B$BShould you run into any fel armaments in your confrontations with demonic enemies, bring them to me and I will demonstrate the cleansing power of the Light.",logDesc="Bring a Fel Armament to Ishanah in Shattrath City.$B$BCompleting quests for the Aldor will cause your Scryers reputation to decrease.",rewards={{id=29735,qty=1}}} end
if not DB[10421] then DB[10421]={id=10421,zoneId=3703,name="Fel Armaments",level=70,minLevel=64,giver="Ishanah",giverType="NPC",giverId=18538,ender="Ishanah",enderType="NPC",enderId=18538,poiX=-1733,poiY=5822,wowhead="https://www.wowhead.com/wotlk/quest=10421",image="assets/images/quests/placeholder.png",rewards={{id=29735,qty=1}}} end
if not DB[10422] then DB[10422]={id=10422,zoneId=3523,name="Captain Tyralius",level=70,minLevel=68,giver="Flesh Handler Viridius",giverType="NPC",giverId=20450,ender="Flesh Handler Viridius",enderType="NPC",enderId=20450,poiX=4264,poiY=2180,wowhead="https://www.wowhead.com/wotlk/quest=10422",image="assets/images/quests/placeholder.png",xpDiff=5,money=132000,desc="Captain Tyralius took a platoon of soldiers south towards the Ethereum Staging Grounds 10 days ago. We haven't heard from him or his crew since.$B$BChances are good that they were ambushed and killed but I'm getting a curious reading from my instruments.$B$BI think it's a distress signal but these things have been wrong before. If Tyralius is still alive, they're keeping him in one of their prisons. You'll have to locate the prison and open it with a key, probably found on the warden.",logDesc="Flesh Handler Viridius at the Protectorate Watch Post in Netherstorm has asked that you find and free Captain Tyralius.$B"} end
if not DB[10423] then DB[10423]={id=10423,zoneId=3523,name="To the Stormspire",level=69,minLevel=67,giver="Mehrdad",giverType="NPC",giverId=20810,ender="Ghabar",enderType="NPC",enderId=20811,rewardNextId=10424,poiX=3360,poiY=2894,wowhead="https://www.wowhead.com/wotlk/quest=10423",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Master Engineer Ghabar will want to know about the results of the diagnostics. If anything, they caution us to keep a close eye on the workings of our dome generators. As the fields become more and more unstable, their effects will become harder to control. It could spell disaster for our expedition and anything else housed within the domes.$B$BYou'll find Ghabar at the Stormspire. Just follow the road north from this eco-dome and across the bridge. It'll lead you to the elevator at the base of the spire.",logDesc="Speak with Ghabar at the Stormspire in Netherstorm."} end
if not DB[10424] then DB[10424]={id=10424,zoneId=3523,name="Diagnosis: Critical",level=69,minLevel=67,giver="Ghabar",giverType="NPC",giverId=20811,ender="Ghabar",enderType="NPC",enderId=20811,rewardNextId=10430,poiX=4150,poiY=3056,wowhead="https://www.wowhead.com/wotlk/quest=10424",image="assets/images/quests/placeholder.png",xpDiff=4,money=21000,desc="If Mehrdad's results are correct -- and I have no reason to believe they're faulty -- then the rest of the domes could be in trouble.$B$BI do think Mehrdad has failed to identify the underlying cause of the failures. From time to time, creatures damage the generators, but never this severely.$B$BTo be on the safe side, I'd like for you to run a set of diagnostics at the Stormspire's main dome generator, located in Eco-Dome Sutheron at the very eastern edge of the dome.",logDesc="Use the Diagnostic Device while standing near the Eco-Dome Sutheron Generator and bring the Diagnostic Results back to Ghabar at the Stormspire."} end
if not DB[10425] then DB[10425]={id=10425,zoneId=3523,name="Escape from the Staging Grounds",level=70,minLevel=68,giver="Captured Protectorate Vanguard",giverType="NPC",giverId=20763,ender="Commander Ameer",enderType="NPC",enderId=20448,poiX=4055,poiY=2289,wowhead="https://www.wowhead.com/wotlk/quest=10425",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Thank K'aresh! He would have torn me apart!$B$BI'm a Protectorate soldier, fleshling. My platoon was sent on a recon mission about 10 days ago. As we were moving across the upper ledges of this island, a group of Ethereum jumped us. At least I think it was Ethereum. They had the same energy color but their wrappings looked void.$B$BOnly Tyralius was spared. I think they put him in a prison cell.$B$BI've got to get back to the Protectorate Watch Post! Can you escort me back?$B",logDesc="Escort the Captured Protectorate Vanguard back to Protectorate Watch Post in Netherstorm.",choiceRewards={{id=30331,qty=1},{id=30332,qty=1},{id=30333,qty=1},{id=30334,qty=1}}} end
if not DB[10426] then DB[10426]={id=10426,zoneId=3523,name="Flora of the Eco-Domes",level=69,minLevel=67,giver="Aurine Moonblaze",giverType="NPC",giverId=20871,ender="Aurine Moonblaze",enderType="NPC",enderId=20871,rewardNextId=10427,poiX=4246,poiY=3124,wowhead="https://www.wowhead.com/wotlk/quest=10426",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Just look around you, $c! Isn't it amazing? Of course, this incredible resurgence of life is a byproduct of the ethereal domes, but imagine what it could do in the hands of the expedition.$B$BI'm preparing to negotiate with the ethereals for access to their technology, but I'd like to get a better idea of its effects on plant-based life.$B$BI've built a device to concentrate the dome's energies on the lashers in this area. Would you be so kind as to test it for me and share the results?",logDesc="Use the Energy Field Modulator on Farahlon Lashers. Observe the results and report back to Aurine Moonblaze at the Stormspire when you have conducted 10 tests."} end
if not DB[10427] then DB[10427]={id=10427,zoneId=3523,name="Creatures of the Eco-Domes",level=69,minLevel=67,giver="Aurine Moonblaze",giverType="NPC",giverId=20871,ender="Aurine Moonblaze",enderType="NPC",enderId=20871,rewardNextId=10429,poiX=4246,poiY=3124,wowhead="https://www.wowhead.com/wotlk/quest=10427",image="assets/images/quests/placeholder.png",xpDiff=6,money=41000,desc="Your work with the lashers turned up some astounding information, but I wonder if it holds true for animals as well.$B$BGathering information on the talbuks that live underneath this dome is going to be trickier than studying the lashers, I'm afraid.$B$BUsing this tagging device, you can put a weakened talbuk to sleep and apply a tag that I'll use to track the animal as it matures. The tagging mechanism won't work unless the talbuk has expended most of its energy.",logDesc="Tag 12 Talbuks for Aurine Moonblaze at the Stormspire. You may tag either Talbuk Sires or Talbuk Does using the Talbuk Tagger."} end
if not DB[10428] then DB[10428]={id=10428,zoneId=3524,name="The Missing Fisherman",level=10,minLevel=8,giver="Dulvi",giverType="NPC",giverId=17488,ender="Cowlen",enderType="NPC",enderId=17311,rewardNextId=9527,poiX=-4180,poiY=-12493,wowhead="https://www.wowhead.com/wotlk/quest=10428",image="assets/images/quests/placeholder.png",xpDiff=3,desc="In the fevered dreams of our injured guest, she spoke of a fisherman, Cowlen, who was in some distress at Silvermyst Isle, to the southwest, off the coast of Azuremyst.$b$bWith all that has been happening, no one has had the opportunity to look into it, but I do feel a bit of worry. Perhaps there's something you can do, $n?",logDesc="Find Cowlen at the southeast docks of Silvermyst Isle off the coast of Azuremyst."} end
if not DB[10429] then DB[10429]={id=10429,zoneId=3523,name="When Nature Goes Too Far",level=69,minLevel=67,giver="Aurine Moonblaze",giverType="NPC",giverId=20871,ender="Aurine Moonblaze",enderType="NPC",enderId=20871,poiX=4246,poiY=3124,wowhead="https://www.wowhead.com/wotlk/quest=10429",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The dome technology possesses such power! Certainly, there are bounds beyond which we dare not go, $N.$B$BCreatures allowed to grow too large or too fast could be just as bad as a barren landscape.$B$BI have heard rumors of just such a creature in the pool to the east. I've heard the ethereal merchants conspiring to catch the overgrown hydra for sport, but I have another purpose in mind for the giant. Bring me the creature's heart so I may study it.",logDesc="Aurine Moonblaze at the Stormspire wants you to bring her a Hulking Hydra Heart."} end
if not DB[10430] then DB[10430]={id=10430,zoneId=3523,name="Testing the Prototype",level=69,minLevel=67,giver="Ghabar",giverType="NPC",giverId=20811,ender="Tashar",enderType="NPC",enderId=20913,rewardNextId=10436,poiX=4150,poiY=3056,wowhead="https://www.wowhead.com/wotlk/quest=10430",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I've been working on a portable generator repair kit for use in some of the harsher climates that the Consortium operates in. Granted, it wasn't designed for Netherstorm, but we shouldn't have any problems with it.$B$BI had already scheduled a test with one of my best techs up at Eco-Dome Farfield beyond the Netherstone to the northeast. Take this prototype to Tashar. He'll know what to do with it. If it works, we can use it to reinforce the shield generators at the larger domes.",logDesc="Bring the Repair Apparatus to Tashar at Eco-Dome Farfield in Netherstorm."} end
if not DB[10431] then DB[10431]={id=10431,zoneId=3523,name="Outside Assistance",level=70,minLevel=67,giver="Exarch Orelis",giverType="NPC",giverId=19466,ender="Kaylaan",enderType="NPC",enderId=20780,rewardNextId=10380,poiX=3071,poiY=3695,wowhead="https://www.wowhead.com/wotlk/quest=10431",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The Sunfury briefings support the theory that Kael'thas has been receiving outside help in constructing and running these manaforges.  Who this is remains a bit of a mystery, though we're likely to find out in Manaforge Ara.$B$BI've sent a group of my men to scout the surrounding area.  Go to Tuluman's Landing, north of here, and speak to Kaylaan.  See what he's discovered at Manaforge Ara.  Find out who is assisting the Sunfury army and take care of them. ",logDesc="Go to Tuluman's Landing, north of Area 52, and speak to Kaylaan.$B$BPerforming quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10432] then DB[10432]={id=10432,zoneId=3523,name="Damning Evidence",level=70,minLevel=67,giver="Magister Theledorn",giverType="NPC",giverId=20920,ender="Spymaster Thalodien",enderType="NPC",enderId=19468,rewardNextId=10508,poiX=3911,poiY=4023,wowhead="https://www.wowhead.com/wotlk/quest=10432",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As you may have noticed, there are servants of the Burning Legion all over Manaforge Ara.  Kael'thas has entered an alliance with the Burning Legion.  He must've caught wind of Illidan's descent into insanity and switched paymasters accordingly.$B$BIf the Scryers get definite proof of this, it will give them a considerable political advantage.  I know for a fact that the Legion forces at this manaforge have orders that bear Kael's seal.$B$BGet these orders and bring them to Thalodien.",logDesc="Obtain 8 Orders from Kael'thas from demons at Manaforge Ara and bring them to Spymaster Thalodien in Area 52.$B$BPerforming quests for the Scryers will cause your Aldor reputation to decrease."} end
if not DB[10433] then DB[10433]={id=10433,zoneId=3523,name="Keeping Up Appearances",level=69,minLevel=67,giver="Shauly Pore",giverType="NPC",giverId=20921,ender="Shauly Pore",enderType="NPC",enderId=20921,rewardNextId=10434,poiX=3374,poiY=2892,wowhead="https://www.wowhead.com/wotlk/quest=10433",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The ethereals are clever and very observant, so it's no accident that I'm here posing as a simple furrier. In fact, I've been sent from Area 52 to appraise the technology the ethereals use to generate their eco-domes.$B$BI'd like to enlist your help, $c. We've been asked to use non-goblin agents whenever possible.$B$BWhat I want you to do is bring me a number of ripfang lynx pelts in the guise of a hunter. You can find the lynxes all over Eco-Dome Midrealm.",logDesc="Bring 10 Ripfang Lynx Pelts to Shauly Pore at Midrealm Post."} end
if not DB[10434] then DB[10434]={id=10434,zoneId=3523,name="The Dynamic Duo",level=69,minLevel=67,giver="Shauly Pore",giverType="NPC",giverId=20921,ender="Audi the Needle",enderType="NPC",enderId=20205,rewardNextId=10435,poiX=3374,poiY=2892,wowhead="https://www.wowhead.com/wotlk/quest=10434",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excellent job.$B$B<Shauly winks at you.>$B$BI think they're buying it. Now, when I send you up to speak with my associates at the Stormspire, there won't be any suspicion at all.$B$BYou'll want to look for Action Jaxon and Audi the Needle up there. They'll tell you everything you need to know. Tell 'em Shauly sent you.",logDesc="Speak with Audi the Needle at the Stormspire in Netherstorm."} end
if not DB[10435] then DB[10435]={id=10435,zoneId=3523,name="Retrieving the Goods",level=69,minLevel=67,giver="Audi the Needle",giverType="NPC",giverId=20205,ender="Audi the Needle",enderType="NPC",enderId=20205,poiX=4090,poiY=2989,wowhead="https://www.wowhead.com/wotlk/quest=10435",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="<Audi looks around and then lowers her voice.>$B$BI'm sure Shauly told you a bit about our work here. When Jaxon and I are out in the field 'hunting,' we've been collecting pieces of the ethereal eco-dome generators and hiding them in the nests of our prey, the raptors in Eco-Dome Farfield.$B$BIt's a remote area to the northeast of the Stormspire, close to the Netherstone. I don't anticipate you'll run into many ethereals there, but would you be willing to help us collect the dome generator pieces?",logDesc="Audi the Needle at the Stormspire wants you to bring her 10 Dome Generator Segments.",choiceRewards={{id=30284,qty=1},{id=30402,qty=1},{id=30285,qty=1},{id=30286,qty=1}}} end
if not DB[10436] then DB[10436]={id=10436,zoneId=3523,name="All Clear!",level=69,minLevel=67,giver="Tashar",giverType="NPC",giverId=20913,ender="Tashar",enderType="NPC",enderId=20913,poiX=4915,poiY=2992,wowhead="https://www.wowhead.com/wotlk/quest=10436",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Before we can begin the test, we have to make certain the area is clear of anything that might interfere. In our case, that means these overgrown lizards.$B$B<Tashar gestures toward the scythetooth raptors.>$B$BThere's no telling what might happen if one those decides to take a nice bite out of the generator while it's charging. I've seen a lot of strange things in all my years as a technician, including more than a few abominations that had their beginnings as humble animals.",logDesc="Tashar, stationed at Eco-Dome Farfield, wants you to kill 12 Scythetooth Raptors."} end
if not DB[10437] then DB[10437]={id=10437,zoneId=3523,name="Recipe for Destruction",level=70,minLevel=68,giver="Professor Dabiri",giverType="NPC",giverId=20907,ender="Professor Dabiri",enderType="NPC",enderId=20907,rewardNextId=10438,poiX=4277,poiY=2132,wowhead="https://www.wowhead.com/wotlk/quest=10437",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Atop Manaforge Ultris lies the tear in the nether that the void lord, Dimensius, came through. That tear provides Dimensius with a link to the void, rendering him immune to physical harm. If we can get a lock on the conduit that Dimensius is using to keep himself phased out of this plane of existence, we can destroy it and then destroy Dimensius.$B$BTo do this, we're going to first need you to collect fragments of Dimensius from the void creatures that he sends out to do his dirty work.",logDesc="Professor Dabiri at the Protectorate Watch Post in Netherstorm wants you to recover 8 Fragments of Dimensius."} end
if not DB[10438] then DB[10438]={id=10438,zoneId=3523,name="On Nethery Wings",level=70,minLevel=68,giver="Professor Dabiri",giverType="NPC",giverId=20907,ender="Professor Dabiri",enderType="NPC",enderId=20907,rewardNextId=10439,poiX=4277,poiY=2132,wowhead="https://www.wowhead.com/wotlk/quest=10438",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Here it is, $N. Take this phase disruptor and mount up! The Protecotrate nether drake will fly you close enough to Ultris so that you can drop the disruptor on top of the void conduit.$B$BDrop as many disruptor charges as possible to ensure complete annihilation!$B$BWhen you are ready, speak with the nether drake and he'll take you up.$B$BIf you miss the mark you will have to get more bombs from me before you can go up again.",logDesc="Professor Dabiri at the Protectorate Watch Post in Netherstorm wants you to use your Phase Disruptor when you get in range of the Void Conduit that rests atop Ultris. Drop as many charges of the Phase Disruptor as you can to ensure total annihilation. The Phase Disruptor charges will automatically home in on the Void Conduit so long as you are close enough to use it.$B$BReturn to Professor Dabiri should you succeed!$B"} end
if not DB[10439] then DB[10439]={id=10439,zoneId=3523,name="Dimensius the All-Devouring",level=70,minLevel=68,giver="Professor Dabiri",giverType="NPC",giverId=20907,ender="Professor Dabiri",enderType="NPC",enderId=20907,poiX=4277,poiY=2132,wowhead="https://www.wowhead.com/wotlk/quest=10439",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Your brave actions have forced Ameer to react! He has deployed Captain Saeed and the Avengers!$B$BNow all that is left to do is destroy Dimensius.$B$BWhen you are ready, I will call for Saeed. If he is not currently fighting another battle, he will be awaiting orders from you - directly east of here.$B$BLet him know when you are ready to fight and he will put his troops in motion!$B$BI wish you luck, fleshling! We have hunted Dimensius for a thousand years!",logDesc="Professor Dabiri at the Protectorate Watch Post in Netherstorm wants you to speak with Captain Saeed and then follow his army to Manaforge Ultris and kill Dimensius the All-Devouring!",choiceRewards={{id=30297,qty=1},{id=30300,qty=1},{id=30299,qty=1},{id=30298,qty=1}}} end
if not DB[10440] then DB[10440]={id=10440,zoneId=3523,name="Success!",level=69,minLevel=67,giver="Tashar",giverType="NPC",giverId=20913,ender="Ghabar",enderType="NPC",enderId=20811,poiX=4915,poiY=2992,wowhead="https://www.wowhead.com/wotlk/quest=10440",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The test was a resounding success! We can certainly use this device to start repairing the domes.$B$BCarry word of the test results to the Stormspire and let Ghabar know that I've also found a pattern in the damage to the shield generators. Key pieces of generator units have gone missing from a number of sites. This is no accident, $N, no technological failure. We're being stolen from. ",logDesc="Return to Ghabar at the Stormspire in Netherstorm.",choiceRewards={{id=30293,qty=1},{id=30290,qty=1},{id=30291,qty=1},{id=30520,qty=1}}} end
if not DB[10441] then DB[10441]={id=10441,zoneId=3523,name="Peddling the Goods",level=69,minLevel=67,wowhead="https://www.wowhead.com/wotlk/quest=10441",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Audi lowers her voice again.>$B$BNow that we have the goods, I'll be sending most of the parts on to Area 52. There's enough here for more than one generator, presenting us with a perfect business opportunity.$B$BI've seen the Cenarion Expdedition's representative trying to negotiate. I want you to let her know that we can provide what she seeks at a very reasonable price. There's no reason for her to continue dealing with those two-timing ethereals.",logDesc="Speak with Aurine Moonblaze at the bottom of the Stormspire in Netherstorm."} end
if not DB[10442] then DB[10442]={id=10442,zoneId=3483,name="Helping the Cenarion Post",level=61,minLevel=61,giver="Falconer Drenna Riverwind",giverType="NPC",giverId=16790,ender="Thiah Redmane",enderType="NPC",enderId=16991,rewardNextId=9372,poiX=-596,poiY=4108,wowhead="https://www.wowhead.com/wotlk/quest=10442",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$C, there's some tauren by the name of Thiah Redmane that keeps pestering us for assistance.  She's with the Cenarion Expedition, and they've setup a little post just to the west on the south side of the the road leading to Zangarmarsh.$B$BIf you hit Thornfang Hill, you've gone too far.$B$BDo you think you might head over there and see what she needs?  I don't want to have to bother Ranger Captain Venn'ren with such trivialities.",logDesc="Falconer Drenna Riverwind wants you to offer your services to Thiah Redmane at the Cenarion Post in Hellfire Peninsula."} end
if not DB[10443] then DB[10443]={id=10443,zoneId=3483,name="Helping the Cenarion Post",level=61,minLevel=61,giver="Amaan the Wise",giverType="NPC",giverId=16796,ender="Thiah Redmane",enderType="NPC",enderId=16991,rewardNextId=9372,poiX=223,poiY=4330,wowhead="https://www.wowhead.com/wotlk/quest=10443",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Cenarion Circle has sent an expedition to Outland and, as I understand it, they are here to study what has happened and to help reverse any damage that they can.$B$BThey've setup a little post just to the west on the south side of the road leading to Zangarmarsh.$B$BIf you hit Thornfang Hill, you've gone too far.$B$BWould you please go and see how you might help them?  Speak with Thiah Redmane as she is the one that sent the request to us for assistance.",logDesc="Amaan the Wise would like for you to offer your services to Thiah Redmane at the Cenarion Post in Hellfire Peninsula."} end
if not DB[10444] then DB[10444]={id=10444,zoneId=3519,name="Report to the Allerian Post",level=64,minLevel=62,giver="Jenai Starwhisper",giverType="NPC",giverId=18459,ender="Lieutenant Meridian",enderType="NPC",enderId=21006,rewardNextId=9996,poiX=-2926,poiY=4005,wowhead="https://www.wowhead.com/wotlk/quest=10444",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This calls for immediate action!$B$BWe have someone out in the field closer to Firewing Point that I want you to speak with.  He'll have a better idea of what our next step should be.$B$BReport to Lieutenant Meridian out at the Allerian Post and apprise him of the situation.  You'll find the post to the northeast on the southern bank of the river just south of Firewing Point.$B$BGodspeed, $N.",logDesc="Jenai Starwhisper wants you to report to Lieutenant Meridian at the Allerian Post in Terokkar Forest."} end
if not DB[10445] then DB[10445]={id=10445,zoneId=1941,name="The Vials of Eternity",level=70,minLevel=70,ender="Soridormi",enderType="NPC",enderId=19935,wowhead="https://www.wowhead.com/wotlk/quest=10445",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.$B$BWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.",logDesc="Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep."} end
if not DB[10446] then DB[10446]={id=10446,zoneId=3519,name="The Final Code",level=65,minLevel=62,giver="Lieutenant Meridian",giverType="NPC",giverId=21006,ender="Jenai Starwhisper",enderType="NPC",enderId=18459,poiX=-2588,poiY=3320,wowhead="https://www.wowhead.com/wotlk/quest=10446",image="assets/images/quests/placeholder.png",xpDiff=6,money=66000,desc="They're building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.$B$B$N, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.$B$BTake the final code to the mana bomb that they're working on in the central courtyard and set it off.$B$BOnly then will we be certain that the Allerian Stronghold is safe.",logDesc="Lieutenant Meridian wants you to use The Final Code to set off the Mana Bomb.  Then report back to Jenai Starwhisper at the Allerian Stronghold in Terokkar Forest.",choiceRewards={{id=31785,qty=1},{id=31782,qty=1},{id=31784,qty=1},{id=31783,qty=1}}} end
if not DB[10447] then DB[10447]={id=10447,zoneId=3519,name="The Final Code",level=65,minLevel=62,giver="Sergeant Chawni",giverType="NPC",giverId=21007,ender="Tooki",enderType="NPC",enderId=18447,poiX=-2526,poiY=3666,wowhead="https://www.wowhead.com/wotlk/quest=10447",image="assets/images/quests/placeholder.png",xpDiff=6,money=66000,desc="They're building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.$B$B$N, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.$B$BTake the final code to the mana bomb that they're working on in the central courtyard and set it off.$B$BOnly then will we be certain that Stonebreaker Hold is safe.",logDesc="Sergeant Chawni wants you to use the Final Code Sheet to set off the Mana Bomb.  Then report back to Tooki at Stonebreaker Hold in Terokkar Forest.",choiceRewards={{id=31785,qty=1},{id=31782,qty=1},{id=31784,qty=1},{id=31783,qty=1}}} end
if not DB[10448] then DB[10448]={id=10448,zoneId=3519,name="Report to Stonebreaker Camp",level=64,minLevel=62,giver="Tooki",giverType="NPC",giverId=18447,ender="Sergeant Chawni",enderType="NPC",enderId=21007,rewardNextId=9997,poiX=-2654,poiY=4381,wowhead="https://www.wowhead.com/wotlk/quest=10448",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This calls for immediate action!$B$BWe have someone out in the field closer to Firewing Point that I want you to speak with.  She'll have a better idea of what our next step should be.$B$BReport to Sergeant Chawni out at Stonebreaker Camp and apprise her of the situation.$B$BTake the road north out of the hold.  From the middle of Tuurem, follow the road to the east.  You'll find the camp on the bank of the river that lies just southwest of Firewing Point.$B$BGood luck, $N.",logDesc="Tooki wants you to report to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest."} end
if not DB[10449] then DB[10449]={id=10449,zoneId=3483,name="Apothecary Zelana",level=60,minLevel=58,giver="Vurtok Axebreaker",giverType="NPC",giverId=21256,ender="Apothecary Zelana",enderType="NPC",enderId=21257,poiX=228,poiY=2692,wowhead="https://www.wowhead.com/wotlk/quest=10449",image="assets/images/quests/placeholder.png",xpDiff=2,money=2300,desc="Apethecary Zelana has been studying the beasts of Hellfire Peninsula in the field.  She wants a sample of the blood you gathered; with luck, she might discover what turned those Bonechewer freaks' skins red!$B$BZelana is at Reaver's Fall, southeast of Thrallmar.  Follow the road east and when you see a destroyed, green-glowing hunk of metal, you're there.  She has a camp set up behind the wyverns.",logDesc="Vertok Axebreaker in Thrallmar wants you to bring Bonechewer Blood Samples to Apothecary Zelana at Reaver's Fall."} end
if not DB[10450] then DB[10450]={id=10450,zoneId=3483,name="Bonechewer Blood",level=60,minLevel=58,giver="Vurtok Axebreaker",giverType="NPC",giverId=21256,ender="Vurtok Axebreaker",enderType="NPC",enderId=21256,rewardNextId=10449,poiX=228,poiY=2692,wowhead="https://www.wowhead.com/wotlk/quest=10450",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="Bonechewers!  They should all die!  The sight of their red skin and depravity makes my blood boil!$B$BI have a mission for you, $N.  Kill Bonechewer orcs and collect their vile blood.  There is an apothecary who needs the blood for her tests, so we can discover how these orcs fell to the demon taint, a taint from which we so recently freed ourselves.$B$BBonechewers scavenge near the ruined battlements along the Path of Glory, to the south.  Return to me when your mission is complete.",logDesc="Bring 12 Bonechewer Blood Vials to Vurtok Axebreaker in Thrallmar.",choiceRewards={{id=29915,qty=1},{id=29919,qty=1},{id=29917,qty=1},{id=29914,qty=1},{id=29916,qty=1}}} end
if not DB[10451] then DB[10451]={id=10451,zoneId=3520,name="Escape from Coilskar Cistern",level=70,minLevel=68,giver="Earthmender Wilda",giverType="NPC",giverId=21027,ender="Earthmender Torlok",enderType="NPC",enderId=21024,poiX=-2616,poiY=1372,wowhead="https://www.wowhead.com/wotlk/quest=10451",image="assets/images/quests/placeholder.png",xpDiff=6,money=132000,desc="Thank the Earthmother! I parted ways with the others several days ago. I was intent on discovering the source of the disturbance that the spirits of water were feeling. My search led me to Coilskar where I discovered that the naga were befouling the water supply of Shadowmoon Valley.$B$BUnfortunately, I was discovered and taken prisoner. There's no telling what ghastly things they had in store for me.$B$BWe must leave this place! Help me escape and then seek out Torlok at the Altar of Damnation.$B",logDesc="Escort Earthmender Wilda out of Coilskar Cistern and then seek out Earthmender Torlok at the Altar of Damnation, found at the western outskirts of the Hand of Gul'dan.",choiceRewards={{id=30927,qty=1},{id=30952,qty=1},{id=30937,qty=1},{id=30968,qty=1}}} end
if not DB[10452] then DB[10452]={id=10452,zoneId=3483,name="DON'T USE [PH] Fel Orc 1",level=58,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=10452",image="assets/images/quests/placeholder.png",desc="[PH Fel Orc 1.",logDesc="[PH Fel Orc 1."} end
