if not DB[10454] then DB[10454]={id=10454,zoneId=0,name="FLAG - OFF THE RAILS",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=10454",image="assets/images/quests/placeholder.png"} end
if not DB[10455] then DB[10455]={id=10455,zoneId=3522,name="The Encroaching Wilderness",level=66,minLevel=65,giver="Rina Moonspring",giverType="NPC",giverId=21066,ender="Rina Moonspring",enderType="NPC",enderId=21066,rewardNextId=10456,poiX=1981,poiY=6881,wowhead="https://www.wowhead.com/wotlk/quest=10455",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="We've been growing the Living Grove at an accelerated rate, but somehow the lynxes there have become lost to our control.$B$BWhere once their population was stable, the grovestalker lynxes are now beginning to encroach upon Sylvanaar, and there have been a number of unpleasant incidents of late.$B$BI suspect that the arakkoa of Veil Lashh are somehow behind it, but the immediate issue is with the lynxes themselves.$B$BI would be most grateful if you would help us to deal with this situation.",logDesc="Slay 12 Grovestalker Lynxes."} end
if not DB[10456] then DB[10456]={id=10456,zoneId=3522,name="Marauding Wolves",level=66,minLevel=65,giver="Rina Moonspring",giverType="NPC",giverId=21066,ender="Rina Moonspring",enderType="NPC",enderId=21066,rewardNextId=10457,poiX=1981,poiY=6881,wowhead="https://www.wowhead.com/wotlk/quest=10456",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="The filthy races of the Horde have taken over a settlement to the east.  They've brought with them a large pack of the dire wolves that they prefer to use as mounts and sentries.$B$BThese sentries have been marauding across the bridge that separates us.  They've been stalking our fey drakes, which are critical to the pollination of the Living Grove.$B$BUse the east exit to traverse the bridge over Bloodmaul Ravine that leads to the Jagged Ridge to the east, and bring me their tails as proof!",logDesc="Collect 4 Thunderlord Dire Wolf Tails."} end
if not DB[10457] then DB[10457]={id=10457,zoneId=3522,name="Protecting Our Own",level=66,minLevel=65,giver="Rina Moonspring",giverType="NPC",giverId=21066,ender="Rina Moonspring",enderType="NPC",enderId=21066,rewardNextId=10506,poiX=1981,poiY=6881,wowhead="https://www.wowhead.com/wotlk/quest=10457",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="Though you've done a great deal of good work in defense of our new home here, I still feel that the Living Grove needs more protection.$B$BPlease, take this small tree bough that I have imbued with the force of nature.  When used upon the seedlings that I have planted out in the grove, it will call down a storm to accelerate the growth of a treant defender.$B$BThese treants are critical to the defense of the grove, especially if you choose not to make Sylvanaar your home for long.",logDesc="Use Rina's Bough on 5 of the Grove Seedlings to summon forth defenses for the Living Grove.",choiceRewards={{id=31418,qty=1},{id=31419,qty=1},{id=31420,qty=1},{id=31421,qty=1}}} end
if not DB[10458] then DB[10458]={id=10458,zoneId=3520,name="Enraged Spirits of Fire and Earth",level=70,minLevel=68,giver="Earthmender Torlok",giverType="NPC",giverId=21024,ender="Earthmender Torlok",enderType="NPC",enderId=21024,rewardNextId=10480,poiX=-3600,poiY=1905,wowhead="https://www.wowhead.com/wotlk/quest=10458",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We must try and make amends. We must commune with the elements of this region and see if anything can be done!$B$BI grant you the totem of spirits, $r. If you slay an enraged elemental spirit in close proximity of the totem, it will consume the elemental's soul. You must use the totem to consume many souls before you may return to me.$B$BDo this for the spirits of fire and earth first. Return to me when the totem is full.",logDesc="Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 8 Earthen Souls and 8 Fiery Souls."} end
if not DB[10459] then DB[10459]={id=10459,zoneId=3905,name="Revered Among the Cenarion Expedition",level=70,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=10459",image="assets/images/quests/placeholder.png",xpDiff=5,money=88000,desc="We've taken notice of your accomplishments, $N.  What you've done for us goes beyond what we expect from our allies.$B$BI've a special request to ask of you, but I must test your dedication first.",logDesc="Ysiel Windsinger at the Cenarion Refuge wants you to become revered with the Cenarion Expedition."} end
