if not DB[10468] then DB[10468]={id=10468,zoneId=1941,name="Sage's Oath",level=70,minLevel=70,giver="Soridormi",giverType="NPC",giverId=19935,ender="Soridormi",enderType="NPC",enderId=19935,rewardNextId=10472,poiX=-8495,poiY=-4431,wowhead="https://www.wowhead.com/wotlk/quest=10468",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You've carried out the promise you made to us, $N.  And for that you've gained the recognition you deserve.$B$BAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.",logDesc="Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.",rewards={{id=29304,qty=1}}} end
