if not DB[10472] then DB[10472]={id=10472,zoneId=1941,name="Sage's Covenant",level=70,minLevel=70,giver="Soridormi",giverType="NPC",giverId=19935,ender="Soridormi",enderType="NPC",enderId=19935,poiX=-8495,poiY=-4431,wowhead="https://www.wowhead.com/wotlk/quest=10472",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Your accomplishments have gone beyond my greatest expectations, $N.$B$BYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.$B$BContinue to serve the Scale of the Sands and I will unleash your gift's full potential.",logDesc="Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.",rewards={{id=29305,qty=1}}} end
