if not DB[10476] then DB[10476]={id=10476,zoneId=3518,name="Fierce Enemies",level=67,minLevel=65,giver="Warden Moi'bff Jill",giverType="NPC",giverId=18408,ender="Warden Moi'bff Jill",enderType="NPC",enderId=18408,poiX=-2569,poiY=7272,wowhead="https://www.wowhead.com/wotlk/quest=10476",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If you seek to prove your loyalty to us, there is no better way than to fight against our enemies.$B$BOf these, there are none that can match the ogres in strength and fierceness.  Bring me the warbeads they wear around their necks as proof of their demise and I'll let the others know of your prowess.",logDesc="Warden Moi'bff Jill at Telaar wants you to obtain 10 Obsidian Warbeads from the various ogres that inhabit Nagrand."} end
