if not DB[10478] then DB[10478]={id=10478,zoneId=3518,name="More Warbeads!",level=68,minLevel=65,giver="Warden Bullrok",giverType="NPC",giverId=18407,ender="Warden Bullrok",enderType="NPC",enderId=18407,poiX=-1356,poiY=7213,wowhead="https://www.wowhead.com/wotlk/quest=10478",image="assets/images/quests/placeholder.png"} end
if not DB[10479] then DB[10479]={id=10479,zoneId=3518,name="Proving Your Strength",level=67,minLevel=65,giver="Warden Bullrok",giverType="NPC",giverId=18407,ender="Warden Bullrok",enderType="NPC",enderId=18407,poiX=-1356,poiY=7213,wowhead="https://www.wowhead.com/wotlk/quest=10479",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Though we seek a peaceful life, our enemies are many.  Of these, none match the ogres in sheer brute power.$B$BIf you seek to prove your prowess to us, bring me the warbeads they wear around their necks.  I will tell others of your accomplishments.",logDesc="Warden Bullrok at Garadar wants you to obtain 10 Obsidian Warbeads from the various ogres that inhabit Nagrand."} end
if not DB[10480] then DB[10480]={id=10480,zoneId=3520,name="Enraged Spirits of Water",level=70,minLevel=68,giver="Earthmender Torlok",giverType="NPC",giverId=21024,ender="Earthmender Torlok",enderType="NPC",enderId=21024,rewardNextId=10481,poiX=-3600,poiY=1905,wowhead="https://www.wowhead.com/wotlk/quest=10480",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Illidari naga of the region have taken control of the only clean water supply that exists in Shadowmoon Valley.$B$BDirectly north of here you will find the lair of the naga: Coilskar. Around Coilskar are pockets of agitated water that howl to the land in anguish. It is at those pockets that the enraged spirits of water now wander.$B$BTravel to Coilskar and use the totem of spirits to capture watery souls. You will find the largest concentration of these spirits near Coilskar Cistern.$B",logDesc="Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 5 Watery Souls.$B"} end
if not DB[10481] then DB[10481]={id=10481,zoneId=3520,name="Enraged Spirits of Air",level=70,minLevel=68,giver="Earthmender Torlok",giverType="NPC",giverId=21024,ender="Earthmender Torlok",enderType="NPC",enderId=21024,poiX=-3600,poiY=1905,wowhead="https://www.wowhead.com/wotlk/quest=10481",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Venture southeast, hero. When you see fields of gigantic blue crystals jutting out from the land, you will have reached your destination. It is there, at the Netherwing Fields, that you will find the enraged spirits of air. They roam the cliffs and mountain bases that surround the fields.$B$BDestroy their tortured forms and capture their souls with the totem of spirits. Return to me when this is done.",logDesc="Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 10 Airy Souls.",choiceRewards={{id=30953,qty=1},{id=30930,qty=1},{id=30942,qty=1},{id=30964,qty=1}}} end
if not DB[10482] then DB[10482]={id=10482,zoneId=3483,name="Fel Orc Scavengers",level=58,minLevel=58,giver="Lieutenant Amadi",giverType="NPC",giverId=16820,ender="Lieutenant Amadi",enderType="NPC",enderId=16820,rewardNextId=10483,poiX=-592,poiY=2910,wowhead="https://www.wowhead.com/wotlk/quest=10482",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="Scavengers, orcs of the Bonechewer clan, skulk about the ruined battlements overlooking the Path of Glory.  We must assume that these fel orcs are gathering war machine parts for their masters within Hellfire Citadel -- they must be stopped!$B$BFind Bonechewer orcs to the north, $n.  Find them and slay them!  But use caution, for although these orcs are the lesser of the fel orc clans, their strength is the match of any green-skinned orc we've faced thus far...",logDesc="Kill 20 Bonechewer Orcs and return to Amadi in Honor Hold.",choiceRewards={{id=29915,qty=1},{id=29919,qty=1},{id=29917,qty=1},{id=29914,qty=1},{id=29916,qty=1}}} end
if not DB[10483] then DB[10483]={id=10483,zoneId=3483,name="Ill Omens",level=58,minLevel=58,giver="Lieutenant Amadi",giverType="NPC",giverId=16820,ender="Corporal Ironridge",enderType="NPC",enderId=21133,poiX=-592,poiY=2910,wowhead="https://www.wowhead.com/wotlk/quest=10483",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$n, in our battles with the Bleeding Hollow clan of fel orcs, we have found upon them foreboding trinkets.  These orcs have collected the insignias of fallen Honor Hold soldiers and created cursed talismans from them.  We fear the dark magic of the Bleeding Hollow orcs have transformed our insignias into evil charms with powers against us!$B$BFind such a talisman from the Bleeding Hollow orcs of Zeth'Gor, to the east, and bring it to Corporal Ironridge at Expedition Point, northeast of Zeth'Gor.",logDesc="Lieutenant Amadi in Honor Hold wants you to bring 1 Cursed Talisman to Corporal Ironridge at Expedition Point."} end
if not DB[10484] then DB[10484]={id=10484,zoneId=3483,name="Cursed Talismans",level=58,minLevel=58,giver="Corporal Ironridge",giverType="NPC",giverId=21133,ender="Corporal Ironridge",enderType="NPC",enderId=21133,rewardNextId=10485,poiX=-701,poiY=1875,wowhead="https://www.wowhead.com/wotlk/quest=10484",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="$n, we cannot allow the Bleeding Hollow orcs to possess their cursed talismans!  You must acquire them for us so they may be disposed of, and so the soldiers who owned them may be honored for their sacrifices.$B$BGo to Zeth'Gor, the cursed abode of the Bleeding Hollow, and perform your grim task... return to me when you have collected the talismans.",logDesc="Bring 12 Cursed Talismans to Corporal Ironridge at Expedition Point."} end
if not DB[10485] then DB[10485]={id=10485,zoneId=3483,name="Warlord of the Bleeding Hollow",level=60,minLevel=58,giver="Corporal Ironridge",giverType="NPC",giverId=21133,ender="Corporal Ironridge",enderType="NPC",enderId=21133,rewardNextId=10903,poiX=-701,poiY=1875,wowhead="https://www.wowhead.com/wotlk/quest=10485",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="You have shown great strength and fortune, for you have delved into Zeth'Gor and lived!  Now, let us hope your fortune holds, for I have a dire task to ask of you...$B$BWarlord Morkh sits within the barracks of Zeth'Gor, commanding his fel troops against us.  His tactics are as clever as they are cruel, and I must admit that his successes against us have cut deep.  And so, $n, I ask you to remove Morkh from his seat.  Bring me his armor so that we might display it for our soldiers and bolster them.",logDesc="Bring Warlord Morkh's Shattered Armor to Corporal Ironridge in Expedition Point."} end
if not DB[10486] then DB[10486]={id=10486,zoneId=3522,name="The Encroaching Wilderness",level=66,minLevel=65,giver="Gor'drek",giverType="NPC",giverId=21117,ender="Gor'drek",enderType="NPC",enderId=21117,rewardNextId=10487,poiX=2313,poiY=6005,wowhead="https://www.wowhead.com/wotlk/quest=10486",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="The Thunderlord were once a proud orc clan before they were transformed into fel orcs through the blood of Mannoroth.$B$BRecently we recovered this orc stronghold from the ogres that infest the ravine below.  They had moved in when the Thunderlord clan abandoned it.$B$BWe will keep this place and I will have your help doing so.$B$BIn the Jagged Ridge to the south and the west, there are bloodletters that have become like a plague upon us.  They eat and breed incessantly.$B$BKill them and then return to me.",logDesc="Slay 12 Bladewing Bloodletters."} end
if not DB[10487] then DB[10487]={id=10487,zoneId=3522,name="Dust from the Drakes",level=66,minLevel=65,giver="Gor'drek",giverType="NPC",giverId=21117,ender="Gor'drek",enderType="NPC",enderId=21117,rewardNextId=10488,poiX=2313,poiY=6005,wowhead="https://www.wowhead.com/wotlk/quest=10487",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="The Alliance has recently moved in to the west, using their elven magics to grow a town and grove in a short matter of time.  We must keep their defenses weak so that they do not also grow a spine.$B$BI have a plan that will do that and more.  I want you to traverse the bridge to the southwest, which crosses over Bloodmaul Ravine and leads into the Living Grove.$B$BAttack their fey drake defenses in the Living Grove and bring back the magical dust that sometimes can be found upon their wings.",logDesc="Collect 4 Dusts of the Fey Drake."} end
if not DB[10488] then DB[10488]={id=10488,zoneId=3522,name="Protecting Our Own",level=66,minLevel=65,giver="Gor'drek",giverType="NPC",giverId=21117,ender="Gor'drek",enderType="NPC",enderId=21117,poiX=2313,poiY=6005,wowhead="https://www.wowhead.com/wotlk/quest=10488",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="With the magical dust you recovered, I have fashioned a magic ointment that will aid in our own defenses.$B$BOur dire wolves are the perfect combination of mount, sentry and friend, but the Alliance scum have been poaching them in the Jagged Ridge.$B$B$N, I want you to take this ointment and apply it to our dire wolf friends.  The Alliance will get a rude surprise the next time that they send one of their hunting parties.$B$BBe aware though that some of the wolves may not like this, and will turn on you.",logDesc="Use Gor'drek's Ointment on 5 of the Thunderlord Dire Wolves.",choiceRewards={{id=31481,qty=1},{id=31482,qty=1},{id=31483,qty=1},{id=31484,qty=1}}} end
if not DB[10489] then DB[10489]={id=10489,zoneId=3522,name="Felling an Ancient Tree",level=66,minLevel=65,ender="Tor'chunk Twoclaws",enderType="NPC",enderId=21147,wowhead="https://www.wowhead.com/wotlk/quest=10489",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="WANTED!$B$BStronglimb Deeproot, ancient of war and chief defender of the Living Grove south of Sylvanaar.$B$BFind him by heading west across the bridge that traverses the Bloodmaul Ravine.$B$BReturn his hewn trunk to Tor'chunk Twoclaws.",logDesc="Collect Stronglimb Deeproot's Trunk.",choiceRewards={{id=31486,qty=1},{id=31487,qty=1},{id=31488,qty=1},{id=31485,qty=1}}} end
if not DB[10490] then DB[10490]={id=10490,zoneId=-82,name="Call of Water",level=-1,minLevel=20,giver="Farseer Umbrua",giverType="NPC",giverId=20407,ender="Farseer Nobundo",enderType="NPC",enderId=17204,rewardNextId=9501,poiX=-9032,poiY=550,wowhead="https://www.wowhead.com/wotlk/quest=10490",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I'm sensing that it's been a while since last you were tested.  This is because Farseer Nobundo has been asking for you.$B$BYou must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.$B$BI trust that you remember how to take the boat from Auberdine in Darkshore on Kalimdor back to the Exodar?  And that you remember where to find the farseer at the Crystal Hall inside the Exodar, yes?",logDesc="Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle."} end
if not DB[10491] then DB[10491]={id=10491,zoneId=-82,name="Call of Air",level=-1,minLevel=30,giver="Farseer Umbrua",giverType="NPC",giverId=20407,ender="Farseer Nobundo",enderType="NPC",enderId=17204,rewardNextId=9552,poiX=-9032,poiY=550,wowhead="https://www.wowhead.com/wotlk/quest=10491",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, once again Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!$B$BI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.$B$BTake the boat from Auberdine in Darkshore on Kalimdor.  Cross the Veiled Sea and seek out the farseer inside the Crystal Hall of the Exodar on Azuremyst Isle.",logDesc="Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle."} end
if not DB[10492] then DB[10492]={id=10492,zoneId=1537,name="An Earnest Proposition",level=60,minLevel=58,giver="Deliana",giverType="NPC",giverId=16013,ender="Deliana",enderType="NPC",enderId=16013,poiX=-4847,poiY=-1058,wowhead="https://www.wowhead.com/wotlk/quest=10492",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Well met, $c.  I've something that might interest you.$B$BI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.$B$BThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.",logDesc="Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Bindings of Elements to Deliana in Ironforge.",rewards={{id=22095,qty=1}}} end
if not DB[10493] then DB[10493]={id=10493,zoneId=1637,name="An Earnest Proposition",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Mokvar",enderType="NPC",enderId=16012,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=10493",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hail, $c!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.$B$BPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.$B$BI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.",logDesc="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Lightforge Bracers to Mokvar in Orgrimmar.",rewards={{id=22088,qty=1}}} end
if not DB[10494] then DB[10494]={id=10494,zoneId=1537,name="Just Compensation",level=60,minLevel=58,giver="Deliana",giverType="NPC",giverId=16013,ender="Deliana",enderType="NPC",enderId=16013,rewardNextId=8929,poiX=-4847,poiY=-1058,wowhead="https://www.wowhead.com/wotlk/quest=10494",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me the belt and set of gloves that you wish to upgrade.  I promise the ones I give you in return will be far superior.",logDesc="Bring a Cord of Elements and a set of Gauntlets of Elements to Deliana in Ironforge.",rewards={{id=22098,qty=1},{id=22099,qty=1}}} end
if not DB[10495] then DB[10495]={id=10495,zoneId=1637,name="Just Compensation",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Mokvar",enderType="NPC",enderId=16012,rewardNextId=8930,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=10495",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You've proven to be a very reliable individual, $N.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.$B$BFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.",logDesc="Bring a Lightforge Belt and a set of Lightforge Gauntlets to Mokvar in Orgrimmar.",rewards={{id=22086,qty=1},{id=22090,qty=1}}} end
if not DB[10496] then DB[10496]={id=10496,zoneId=1537,name="Anthion's Parting Words",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Deliana",enderType="NPC",enderId=16013,rewardNextId=8960,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=10496",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!",logDesc="Return to Deliana in Ironforge with a set of Boots of Elements, a Kilt of Elements and Pauldrons of Elements.",rewards={{id=22096,qty=1},{id=22100,qty=1},{id=22101,qty=1}}} end
if not DB[10497] then DB[10497]={id=10497,zoneId=1637,name="Anthion's Parting Words",level=60,minLevel=58,giver="Anthion Harmon",giverType="NPC",giverId=16016,ender="Mokvar",enderType="NPC",enderId=16012,rewardNextId=9032,poiX=3368,poiY=-3380,wowhead="https://www.wowhead.com/wotlk/quest=10497",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!",logDesc="Return to Mokvar in Orgimmar with a set of Lightforge Boots, Lightforge Legplates and Lightforge Spaulders.$B",rewards={{id=22087,qty=1},{id=22092,qty=1},{id=22093,qty=1}}} end
if not DB[10498] then DB[10498]={id=10498,zoneId=1537,name="Saving the Best for Last",level=60,minLevel=58,giver="Deliana",giverType="NPC",giverId=16013,ender="Deliana",enderType="NPC",enderId=16013,poiX=-4847,poiY=-1058,wowhead="https://www.wowhead.com/wotlk/quest=10498",image="assets/images/quests/placeholder.png",xpDiff=2,desc="That's an amazing story, $N! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.$B$BAs to your reward, I believe I have a few things that you'll really enjoy.",logDesc="Give Deliana your Coif of Elements and Vest of Elements.",rewards={{id=22097,qty=1},{id=22102,qty=1}}} end
if not DB[10499] then DB[10499]={id=10499,zoneId=1637,name="Saving the Best for Last",level=60,minLevel=58,giver="Mokvar",giverType="NPC",giverId=16012,ender="Mokvar",enderType="NPC",enderId=16012,poiX=1916,poiY=-4171,wowhead="https://www.wowhead.com/wotlk/quest=10499",image="assets/images/quests/placeholder.png",xpDiff=2,desc="A truly amazing story, $N! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past.$B$BAs to your reward, I believe I have a few things that you have definitely earned and will truly enjoy.",logDesc="Give Mokvar your Lightforge Helm and Lightforge Breastplate.",rewards={{id=22091,qty=1},{id=22089,qty=1}}} end
if not DB[10500] then DB[10500]={id=10500,zoneId=-365,name="The Horde Needs Your Help!",level=60,minLevel=1,giver="Senior Sergeant Eveningshade",giverType="NPC",giverId=21155,ender="Warlord Gorchuk",enderType="NPC",enderId=15700,wowhead="https://www.wowhead.com/wotlk/quest=10500",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, $N!$B$BYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, $c? Will you help out with the vital preparations?",logDesc="Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits."} end
if not DB[10501] then DB[10501]={id=10501,zoneId=-365,name="The Alliance Needs Your Help!",level=60,minLevel=1,giver="Master Sergeant Thelaana",giverType="NPC",giverId=21156,wowhead="https://www.wowhead.com/wotlk/quest=10501",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, $N!$B$BYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, $c? Will you help out with the vital preparations?",logDesc="Speak with Field Marshal Snowfall in Ironforge's Military Ward."} end
if not DB[10502] then DB[10502]={id=10502,zoneId=3522,name="The Bloodmaul Ogres",level=66,minLevel=65,giver="Commander Skyshadow",giverType="NPC",giverId=21158,ender="Commander Skyshadow",enderType="NPC",enderId=21158,rewardNextId=10504,poiX=2015,poiY=6881,wowhead="https://www.wowhead.com/wotlk/quest=10502",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="There is a threat to Sylvanaar far deadlier than the Horde at Thunderlord Stronghold.$B$BI'm speaking of the native ogres of these mountains.  Just to the south and east, down in the ravine, lives the Bloodmaul clan.  While they aren't the only group of ogres that threaten us here, they are the closest.$B$BI would have you head south through the Living Grove, and then go down the path to the east, which leads to their outpost.  Slay as many of the Bloodmaul ogres at Bloodmaul Outpost as you can.",logDesc="Slay any 30 Bloodmaul Ogres at Bloodmaul Outpost."} end
if not DB[10503] then DB[10503]={id=10503,zoneId=3522,name="The Bladespire Threat",level=66,minLevel=65,giver="Tor'chunk Twoclaws",giverType="NPC",giverId=21147,ender="Tor'chunk Twoclaws",enderType="NPC",enderId=21147,rewardNextId=10505,poiX=2296,poiY=6028,wowhead="https://www.wowhead.com/wotlk/quest=10503",image="assets/images/quests/placeholder.png",xpDiff=6,money=70000,desc="There is a threat to Thunderlord Stronghold worse than the Alliance at Sylvanaar.$B$BI speak of the ogres of these mountains.  Just to the west, down in the ravine, lies the Bladespire clan.  While they aren't the only ogres, they are the closest and they're the ones that we defeated to take this place.$B$BHead north through the Jagged Ridge, and then down the path, which leads to their hold.  Slay as many of the Bladespire ogres and their raptors as you can at Bladespire Hold and the Bladespire Grounds.",logDesc="Slay any 30 Bladespire Ogres and 10 Bladespire Raptors at Bladespire Hold and the Bladespire Grounds."} end
if not DB[10504] then DB[10504]={id=10504,zoneId=3522,name="The Bladespire Ogres",level=66,minLevel=65,giver="Commander Skyshadow",giverType="NPC",giverId=21158,ender="Commander Skyshadow",enderType="NPC",enderId=21158,poiX=2015,poiY=6881,wowhead="https://www.wowhead.com/wotlk/quest=10504",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="To the north of the Bloodmaul clan lies a threat more grave:  Bladespire Hold.$B$BThe Bladespire ogres are the strongest clan in the mountains, having the favor of the gronn known as Gruul the Dragonkiller, and his seven sons.$B$BNow that we've dealt with winnowing the Bloodmaul, it is time to turn our eye upon their rivals.$B$BFrom Bloodmaul Hold head north through the ravine until you come to Bladespire Hold and the Bladespire Grounds.  Slay as many of the Bladespire ogres therein as you can.",logDesc="Slayl any 30 Bladespire Ogres in Bladespire Hold and the Bladespire Grounds.",choiceRewards={{id=31425,qty=1},{id=31426,qty=1},{id=31427,qty=1},{id=31428,qty=1}}} end
if not DB[10505] then DB[10505]={id=10505,zoneId=3522,name="The Bloodmaul Ogres",level=66,minLevel=65,giver="Tor'chunk Twoclaws",giverType="NPC",giverId=21147,ender="Tor'chunk Twoclaws",enderType="NPC",enderId=21147,poiX=2296,poiY=6028,wowhead="https://www.wowhead.com/wotlk/quest=10505",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="To the south of the Bladespire clan lies yet another threat:  Bloodmaul Outpost.$B$BWhile the Bloodmaul ogres are not the strongest clan in the mountains, not having the favor of the gronn known as Gruul the Dragonkiller, they run a close second.$B$BNow that we've dealt with winnowing the Bladespire, it is time to turn our eye upon their rivals.$B$BFrom Bladespire Hold head south through the ravine until you come to Bloodmaul Outpost.  Slay as many of the Bloodmaul ogres in the vicinity as you can.",logDesc="Slay any 30 Bloodmaul Ogres at Bloodmaul Outpost.",choiceRewards={{id=31477,qty=1},{id=31479,qty=1},{id=31478,qty=1},{id=31480,qty=1}}} end
if not DB[10506] then DB[10506]={id=10506,zoneId=3522,name="A Dire Situation",level=66,minLevel=65,giver="Rina Moonspring",giverType="NPC",giverId=21066,ender="Rina Moonspring",enderType="NPC",enderId=21066,poiX=1981,poiY=6881,wowhead="https://www.wowhead.com/wotlk/quest=10506",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="With their wolf pack reduced, the Horde is looking for replacements.  Unfortunately there's another source nearby.$B$BThe Bloodmaul ogres in the ravine below to the east keep a strong pack as their own sentries.  I hated sending you to kill the Thunderlord wolves, so why don't we do something different this time?$B$BI've derived a magic powder from the dust that naturally falls off the wings of our fey drakes.  Sprinkle it on the Bloodmaul dire wolves to make them undesirable to the Horde.",logDesc="Apply Rina's Diminution Powder to 5 of the Bloodmaul Dire Wolves at Bloodmaul Outpost and in Bloodmaul Ravine."} end
if not DB[10507] then DB[10507]={id=10507,zoneId=3523,name="Turning Point",level=70,minLevel=67,giver="Voren'thal the Seer",giverType="NPC",giverId=18530,ender="Voren'thal the Seer",enderType="NPC",enderId=18530,poiX=-2273,poiY=5576,wowhead="https://www.wowhead.com/wotlk/quest=10507",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="This is the chance we've been waiting for, $N.  Not only have we uncovered the evidence we need to show our people who Kael'thas is really working for, but we can prove our strength by defeating his new masters.$B$BMy frail health prevents me from aiding you in person with this endeavor, but I will offer you an object that will allow me to project my powers across the continent.  ",logDesc="Use Socrethar's Teleportation's Stone at Invasion Point: Overlord, north of Forge Base: Oblivion to transport your party to Socrethar's Landing.  Once there, use Voren'thal's Presence to defeat Socrethar.$B$BPerforming quests for the Scryers will cause your Aldor reputation to decrease.",choiceRewards={{id=30375,qty=1},{id=30372,qty=1},{id=30373,qty=1},{id=30374,qty=1},{id=30859,qty=1}}} end
if not DB[10508] then DB[10508]={id=10508,zoneId=3523,name="A Gift for Voren'thal",level=70,minLevel=67,giver="Spymaster Thalodien",giverType="NPC",giverId=19468,ender="Spymaster Thalodien",enderType="NPC",enderId=19468,rewardNextId=10509,poiX=3075,poiY=3699,wowhead="https://www.wowhead.com/wotlk/quest=10508",image="assets/images/quests/placeholder.png",xpDiff=6,money=44000,desc="I don't want to send you to Voren'thal empty-handed.  It's not in my style to be underwhelming.$B$BTo gain access to Socrethar's Seat in the north, we'll need to use his own teleporters - locked by Socrethar's teleportation stone.  The first half of the stone is in the possession of Forgemaster Morug at Forge Base Oblivion.  The second half is held by the demon Silroth at Forge Base: Gehenna.$B$BObtain these and Voren'thal will be impressed beyond words.",logDesc="Spymaster Thalodien at Area 52 wants you to obtain the First Half of Socrethar's Stone from Forgemaster Morug at Forge Base: Oblivion and the Second Half of Socrethar's Stone from Silroth at Forge Base: Gehenna.$B$BCompleting quests for the Scryers will cause your Aldor reputation to decrease."} end
if not DB[10509] then DB[10509]={id=10509,zoneId=3703,name="Bound for Glory",level=70,minLevel=67,giver="Spymaster Thalodien",giverType="NPC",giverId=19468,ender="Voren'thal the Seer",enderType="NPC",enderId=18530,rewardNextId=10507,poiX=3075,poiY=3699,wowhead="https://www.wowhead.com/wotlk/quest=10509",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Now I can properly send you back to Shattrath City.  You've uncovered evidence of Kael'thas making pacts with the Burning Legion and you've got the key to the overlord's back door.$B$BMake sure Voren'thal doesn't topple over with excitement from the news - the old man's getting a bit fragile, if you know what I mean.  You'll find him inside the Seer's Library at the Scryer's Tier.",logDesc="Bring Socrethar's Teleportation Stone to Voren'thal the Seer at the Scryer's Tier in Shattrath City.$B$BCompleting quests for the Scryers will cause your Aldor reputation to decrease."} end
if not DB[10510] then DB[10510]={id=10510,zoneId=3522,name="Into the Draenethyst Mine",level=66,minLevel=65,giver="Bronwyn Stouthammer",giverType="NPC",giverId=21197,ender="Bronwyn Stouthammer",enderType="NPC",enderId=21197,poiX=2056,poiY=6817,wowhead="https://www.wowhead.com/wotlk/quest=10510",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="Well it's good to see someone who's willing to help out around here!$B$BBorgrim and I are part of the Explorers' League, and we're here to learn what we can of these mountains.  We've heard all sorts of tales, and I can't wait to get settled in and started.$B$BOne thing in particular has caught my attention.  The night elves speak of a place down in the ravine to the east known as the Draenethyst Mine.  It's at the south end of Bloodmaul Outpost.  I'd like some of the crystals that grow naturally therein.",logDesc="Collect 5 Draenethyst Mine Crystals.",choiceRewards={{id=31429,qty=1},{id=31431,qty=1},{id=31430,qty=1},{id=31432,qty=1}}} end
if not DB[10511] then DB[10511]={id=10511,zoneId=3522,name="Strange Brew",level=66,minLevel=65,giver="Borgrim Stouthammer",giverType="NPC",giverId=21151,ender="Borgrim Stouthammer",enderType="NPC",enderId=21151,poiX=2070,poiY=6817,wowhead="https://www.wowhead.com/wotlk/quest=10511",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="If I'm going to start this vacation out right, then I'm going to need more brew.  Unfortunately, the elves know nothing of the fine art of fermentation.$B$BI overheard that the Bloodmaul ogres down in the ravine have plenty.  I'm willing to give it a try.$B$BDo me a favor?  Head south through the Living Grove and then down the ramp to the east into Bloodmaul Outpost and procure me some?  I hear they have big barrels of it laying around and that their brewmasters carry it around to all the other ogres.",logDesc="Collect 11 Bloodmaul Brutebane Brew."} end
if not DB[10512] then DB[10512]={id=10512,zoneId=3522,name="Getting the Bladespire Tanked",level=66,minLevel=65,giver="Borgrim Stouthammer",giverType="NPC",giverId=21151,ender="Borgrim Stouthammer",enderType="NPC",enderId=21151,poiX=2070,poiY=6817,wowhead="https://www.wowhead.com/wotlk/quest=10512",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="I'll not take another sip of that ill-smelling muck!  But it does give me an idea.$B$B<Borgrim gets a twinkle in his eye.>$B$BSo here's the plan.  We know that the Bloodmaul practically live off of this swill.  But I wonder what their enemies, the Bladespire ogres, think of it?$B$B$N, I want you to take the rest of this rubbish and see if you can get the Bladespire ogres tanked.  You can find them by heading north from Bloodmaul Outpost through the ravine.",logDesc="Use the Bloodmaul Brutebane Keg in an attempt to get 5 Bladespire Ogres drunk."} end
if not DB[10513] then DB[10513]={id=10513,zoneId=3520,name="Oronok Torn-heart",level=70,minLevel=68,giver="Earthmender Torlok",giverType="NPC",giverId=21024,ender="Oronok Torn-heart",enderType="NPC",enderId=21183,rewardNextId=10514,poiX=-3600,poiY=1905,wowhead="https://www.wowhead.com/wotlk/quest=10513",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I do not know how we can acquire the spell that the spirits mentioned, $N. Truth be told, I don't even know where we would start such a search.$B$B<Torlok stares off in the distance, lost in thought.>$B$BHrm... It is a long shot but it might be our only chance. There is an orc that I have seen visit this area before. I spoke to him briefly once. He is a hermit that claims to live above Coilskar Cistern to the northeast. Seek out this orc, Oronok Torn-heart.$B$BAs I said, it is a long shot.",logDesc="Seek out Oronok Torn-heart on the Shattered Shelf - north of Coilskar Cistern.$B"} end
if not DB[10514] then DB[10514]={id=10514,zoneId=3520,name="I Was A Lot Of Things...",level=70,minLevel=68,giver="Oronok Torn-heart",giverType="NPC",giverId=21183,ender="Oronok Torn-heart",enderType="NPC",enderId=21183,rewardNextId=10515,poiX=-2810,poiY=1258,wowhead="https://www.wowhead.com/wotlk/quest=10514",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've been a lot of things, stranger, but what I once was isn't what's important. What I am now is what matters and what I am now is a farmer.$B$BI use trained felboars to dig up tubers from the hardened earth of the Shattered Plains. Recently, though, flayers from a nest to the northeast have been attacking my animals, preventing me from gathering tubers.$B$BWould you go to the area north of here and gather tubers for me? Use this whistle while standing on a tuber mound and a boar will come dig one up!",logDesc="Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley wants you to recover 10 Shadowmoon Tubers from the Shattered Plains.$B$BHe also wants Oronok's Boar Whistle back when you're done.",choiceRewards={{id=30357,qty=20},{id=30358,qty=20},{id=30359,qty=20},{id=30361,qty=20}}} end
if not DB[10515] then DB[10515]={id=10515,zoneId=3520,name="A Lesson Learned",level=70,minLevel=68,giver="Oronok Torn-heart",giverType="NPC",giverId=21183,ender="Oronok Torn-heart",enderType="NPC",enderId=21183,rewardNextId=10519,poiX=-2810,poiY=1258,wowhead="https://www.wowhead.com/wotlk/quest=10515",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We need to show those flayers what happens when you mess with Oronok's business!$B$BI want you to go back to the Shattered Plains and destroy every flayer egg that you see. They'll be deep in flayer territory so keep your guard up.",logDesc="Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley wants you to destroy 10 Ravenous Flayer Eggs on the Shattered Plains."} end
if not DB[10516] then DB[10516]={id=10516,zoneId=3522,name="The Trappings of a Vindicator",level=66,minLevel=65,giver="Vindicator Vuuleen",giverType="NPC",giverId=21277,ender="Vindicator Vuuleen",enderType="NPC",enderId=21277,rewardNextId=10517,poiX=2534,poiY=6458,wowhead="https://www.wowhead.com/wotlk/quest=10516",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="I know it's strange, but I do want to stay in this cage.  It gives me the perfect opportunity to do what I came here for; to gather information on the Bladespire.$B$BI can leave at any time, but I would like to have my sword and shield back.$B$BTwo of their leaders have my trappings.  Droggam has my sword and Mugdorg has my shield.$B$BIf you have need, obtain and use the brew from Bloodmaul Outpost to the south to thin out their help and entice those two, but beware their sober guards who don't drink!",logDesc="Collect Vindicator Vuuleen's Blade and Vindicator Vuuleen's Shield."} end
if not DB[10517] then DB[10517]={id=10517,zoneId=3522,name="Gorr'Dim, Your Time Has Come...",level=67,minLevel=65,giver="Vindicator Vuuleen",giverType="NPC",giverId=21277,ender="Vindicator Vuuleen",enderType="NPC",enderId=21277,rewardNextId=10518,poiX=2534,poiY=6458,wowhead="https://www.wowhead.com/wotlk/quest=10517",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="The leader of Bladespire Hold is known as Gorr'Dim.  Trust me... the name is appropriate.$B$BStill, I wouldn't underestimate him.  He's crafty enough to have elevated his clan to be the favorite of Gruul the Dragonkiller and they now dominate these mountains.  And Gorr'Dim keeps an entourage about him at all times, including defenders who are sworn not to drink the Bloodmaul brew.$B$BFor the safety of Sylvanaar, I'm asking that you go back in there and deal with him.",logDesc="Slay Gorr'Dim, leader of the Bladespire Hold ogres."} end
if not DB[10518] then DB[10518]={id=10518,zoneId=3522,name="Planting the Banner",level=67,minLevel=65,giver="Vindicator Vuuleen",giverType="NPC",giverId=21277,ender="Commander Skyshadow",enderType="NPC",enderId=21158,poiX=2534,poiY=6458,wowhead="https://www.wowhead.com/wotlk/quest=10518",image="assets/images/quests/placeholder.png",xpDiff=6,money=74000,desc="I want you to steal the Bladespire banner from one of their champions and take it south to Bloodmaul Outpost.  Plant it atop their Northmaul Tower.$B$BThis will infuriate the Bloodmaul and they will attack you relentlessly.  But it will also keep their hatred focused on Bladespire Hold, and away from Sylvanaar.$B$BYou will know you have accomplished the deed when you have defeated Gurn Grubnosh and taken his helm.  Return it to Sylvanaar.$B$B$N, this isn't going to be easy.  Take a  friend or two with you.",logDesc="Use the Bladespire Banner atop the Northmaul Tower to lure Gurn Grubnosh.  Collect the Bladespire Clan Banner and the Helm of Gurn Grubnosh.",choiceRewards={{id=31433,qty=1},{id=31434,qty=1},{id=31435,qty=1},{id=31436,qty=1}}} end
if not DB[10519] then DB[10519]={id=10519,zoneId=3520,name="The Cipher of Damnation - Truth and History",level=70,minLevel=68,giver="Oronok Torn-heart",giverType="NPC",giverId=21183,ender="Oronok Torn-heart",enderType="NPC",enderId=21183,poiX=-2810,poiY=1258,wowhead="https://www.wowhead.com/wotlk/quest=10519",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Oronok adjusts his posture and stands to his full height.>$B$BI had to be sure, $N. And to be sure, I had to test you. Please excuse the little masquerade. I am as much a farmer as you are $g female:male;. Which is to say, not at all.$B$BIf you are to recover the Cipher of Damnation, you will need to listen to what I have to tell you. When you are ready, let me know and I will tell you the story.",logDesc="Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley wants you to listen to his story. Speak to Oronok to begin hearing his story."} end
if not DB[10520] then DB[10520]={id=10520,zoneId=3557,name="Assisting Arch Druid Staghelm",level=50,minLevel=47,giver="Caregiver Breel",giverType="NPC",giverId=16739,ender="Arch Druid Fandral Staghelm",enderType="NPC",enderId=3516,rewardNextId=3764,poiX=-3746,poiY=-11696,wowhead="https://www.wowhead.com/wotlk/quest=10520",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excuse me $c, but I'd like just a moment of your time if possible.$B$BThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.$B$BPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.",logDesc="Speak with Arch Druid Fandral Staghelm in Darnassus."} end
if not DB[10521] then DB[10521]={id=10521,zoneId=3520,name="Grom'tor, Son of Oronok",level=70,minLevel=68,giver="Oronok Torn-heart",giverType="NPC",giverId=21183,ender="Grom'tor, Son of Oronok",enderType="NPC",enderId=21291,rewardNextId=10522,poiX=-2810,poiY=1258,wowhead="https://www.wowhead.com/wotlk/quest=10521",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My first born, Grom'tor, left to search Coilskar Point - directly southwest of here.$B$BHe's the warrior in the family - ill-tempered and blood-thirsty... Traits he inherited from his mother. Search along the outskirts of Coilskar Point. If you see naga corpses, Grom'tor is sure to be close.$B$BWhen you find him, tell him this: \"We spill blood for just cause.\" It will let him know that you are a friend to Torn-heart and prevent your premature death.",logDesc="Find Grom'tor, Son of Oronok at Coilskar Point in Shadowmoon Valley."} end
if not DB[10522] then DB[10522]={id=10522,zoneId=3520,name="The Cipher of Damnation - Grom'tor's Charge",level=70,minLevel=68,giver="Grom'tor, Son of Oronok",giverType="NPC",giverId=21291,ender="Grom'tor, Son of Oronok",enderType="NPC",enderId=21291,rewardNextId=10523,poiX=-2815,poiY=1771,wowhead="https://www.wowhead.com/wotlk/quest=10522",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This naga filth is the sixth one I've interrogated today. He's got the fancy armor so I figured he knew something. Those other ones were useless.$B$B<Grom'tor points to the corpses of the naga around him.>$B$BI only had to beat him once and he told me everything.$B$BThe first part of the cipher is hidden in a naga chest at Coilskar Point or Coilskar Cistern, east of here. He says naga carry the keys. Kill 'em, take their keys and use them to open the Coilskar chests. Return to me when you find the cipher.",logDesc="Grom'tor, Son of Oronok at Coilskar Point in Shadowmoon Valley wants you to recover the First Fragment of the Cipher of Damnation."} end
if not DB[10523] then DB[10523]={id=10523,zoneId=3520,name="The Cipher of Damnation - The First Fragment Recovered",level=70,minLevel=68,giver="Grom'tor, Son of Oronok",giverType="NPC",giverId=21291,ender="Oronok Torn-heart",enderType="NPC",enderId=21183,poiX=-2815,poiY=1771,wowhead="https://www.wowhead.com/wotlk/quest=10523",image="assets/images/quests/placeholder.png",xpDiff=2,desc="<Grom'tor wraps the documents up and places them in a lockbox.>$B$BTake this box to father. He awaits your return at the farm, northeast of here.$B$BTell him that I will be home soon. As soon as I am done having my fun...",logDesc="Take Grom'tor's Lockbox to Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley.",choiceRewards={{id=30945,qty=1},{id=30923,qty=1},{id=30981,qty=1},{id=30956,qty=1}}} end
if not DB[10524] then DB[10524]={id=10524,zoneId=3522,name="Thunderlord Clan Artifacts",level=66,minLevel=65,ender="Rokgah Bloodgrip",enderType="NPC",enderId=21311,rewardNextId=10525,wowhead="https://www.wowhead.com/wotlk/quest=10524",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="The artifact bears markings that indicate its origins as being created by the Thunderlord clan orcs.  These orcs used to live at Thunderlord Stronghold before they were changed into fel orcs.$B$BFor a time the Bladespire ogres inhabited the stronghold until recently when the Horde pushed them out.$B$BYou've heard of other artifacts that were lost.  A drum, an arrow and a tablet come to mind as objects that you know are being sought after.$B$BFind them in Bladespire Hold and return them to Rokgar Bloodgrip.",logDesc="Collect the Thunderlord Clan Drum, Thunderlord Clan Arrow and the Thunderlord Clan Tablet."} end
if not DB[10525] then DB[10525]={id=10525,zoneId=3522,name="Vision Guide",level=66,minLevel=65,giver="Rokgah Bloodgrip",giverType="NPC",giverId=21311,ender="Rokgah Bloodgrip",enderType="NPC",enderId=21311,rewardNextId=10526,poiX=2276,poiY=5982,wowhead="https://www.wowhead.com/wotlk/quest=10525",image="assets/images/quests/placeholder.png",xpDiff=4,desc="$R fool.  You almost destroyed the drum!$B$BI've worked too hard to get here, and my hands have been empty up until now.  At least you were able to succeed where the others only met with failure, or worse.$B$BIt is time to evoke a vision that will lead you to the last relic that I have been seeking.$B$BTake this fiery fragment of my soul.  Use it to transform your body into flame and denature your spirit into a vision guide that will shoot forth to reveal the location of the final Thunderlord relic.",logDesc="Use the Fiery Soul Fragment to transform your spirit into a vision guide, which will reveal the location of the final Thunderlord artifact."} end
if not DB[10526] then DB[10526]={id=10526,zoneId=3522,name="The Thunderspike",level=67,minLevel=65,giver="Rokgah Bloodgrip",giverType="NPC",giverId=21311,ender="Rokgah Bloodgrip",enderType="NPC",enderId=21311,poiX=2276,poiY=5982,wowhead="https://www.wowhead.com/wotlk/quest=10526",image="assets/images/quests/placeholder.png",xpDiff=6,money=74000,desc="If the vision that I granted you is true, then you must travel down into the ravine and to the south end of Bloodmaul Ravine.  There you will find the Draenethyst Mine.$B$BJourney to the back of the mine, and retrieve the Thunderspike.  Ignore everything else!  I have no interest in the crystals of the mine, nor the ogres therein.$B$BAs soon as you have the spear return it to me here!$B$BAnd, $N, be very careful with it... I would hate to think what would happen to you should you break it.",logDesc="Collect the Thunderspike.",choiceRewards={{id=31475,qty=1},{id=31476,qty=1},{id=31474,qty=1}}} end
if not DB[10527] then DB[10527]={id=10527,zoneId=3520,name="Ar'tor, Son of Oronok",level=70,minLevel=68,giver="Oronok Torn-heart",giverType="NPC",giverId=21183,ender="Ar'tor, Son of Oronok",enderType="NPC",enderId=21292,rewardNextId=10528,poiX=-2810,poiY=1258,wowhead="https://www.wowhead.com/wotlk/quest=10527",image="assets/images/quests/placeholder.png",xpDiff=3,desc="My youngest son, Ar'tor, left to search Illidari Point - far to the southwest, nestled between Legion Hold and Wildhammer Stronghold.$B$BWhile Ar'tor is a hunter of remarkable skill and an expert tracker, I fear that he may be in over his head this time. Illidari Point is the proving grounds for Illidan's demons. These are demons that left the Burning Legion to join the Betrayer!$B$BTravel to Illidari Point and find Ar'tor, $N.",logDesc="Find Ar'tor, Son of Oronok at Illidari Point in Shadowmoon Valley."} end
if not DB[10528] then DB[10528]={id=10528,zoneId=3520,name="Demonic Crystal Prisons",level=70,minLevel=68,giver="Ar'tor, Son of Oronok",giverType="NPC",giverId=21292,ender="Ar'tor, Son of Oronok",enderType="NPC",enderId=21292,poiX=-3796,poiY=2595,wowhead="https://www.wowhead.com/wotlk/quest=10528",image="assets/images/quests/placeholder.png",xpDiff=4,desc="From assessing the scene, you note that Ar'tor is being held in place by energy beams emanating from the crystals hovering around the rune. Try as you might, Ar'tor is unmovable.$B$BYou note that the crystals have an empty slot at their base - perhaps for a key. It also seems as if succubi periodically perform some sort of ritual at the site.$B$BSearch Illidari Point for their leader. Perhaps she holds the key to releasing Ar'tor.",logDesc="Seek out and slay Painmistress Gabrissa at Illidari Point and return to the corpse of Ar'tor, Son of Oronok with the Crystalline Key."} end
if not DB[10529] then DB[10529]={id=10529,zoneId=-261,name="The Hunter's Path",level=-1,minLevel=10,rewardNextId=9484,wowhead="https://www.wowhead.com/wotlk/quest=10529",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, $N.  She is a beacon of wisdom for those of our calling.$b$bFarstrider Retreat lies south of Silvermoon City.",logDesc="Speak with Lieutenant Dawnrunner at Farstrider Retreat in Eversong Woods."} end
if not DB[10530] then DB[10530]={id=10530,zoneId=-261,name="The Hunter's Path",level=-1,minLevel=10,ender="Lieutenant Dawnrunner",enderType="NPC",enderId=15399,rewardNextId=9484,wowhead="https://www.wowhead.com/wotlk/quest=10530",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, $N.  She is a beacon of wisdom for those of our calling.$b$bFarstrider Retreat lies south of Silvermoon City.",logDesc="Speak with Lieutenant Dawnrunner at Farstrider Retreat in Eversong Woods."} end
if not DB[10531] then DB[10531]={id=10531,zoneId=3358,name="The Battle for Arathi Basin!",level=55,minLevel=50,wowhead="https://www.wowhead.com/wotlk/quest=10531",image="assets/images/quests/placeholder.png",xpDiff=5,money=16500,desc="$N, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.$B$BAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!$B$BWhen you have done this to all four points, return to me.",logDesc="Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe."} end
if not DB[10532] then DB[10532]={id=10532,zoneId=3358,name="Cut Arathor Supply Lines",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=10532",image="assets/images/quests/placeholder.png",xpDiff=5,money=132000,desc="The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.$B$BYou can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.",logDesc="Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall."} end
if not DB[10533] then DB[10533]={id=10533,zoneId=3358,name="More Resource Crates",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=10533",image="assets/images/quests/placeholder.png",xpDiff=3} end
if not DB[10534] then DB[10534]={id=10534,zoneId=-262,name="Returning Home",level=10,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=10534",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A $r $c...$b$bYes, there was a priest of your order here recently, $n.  He told me it was time you returned to the Exodar met with Caedmos.  There was a sense of urgency in his request, so I wouldn't take too long to see him.",logDesc="Caedmos at the Exodar has requested you come see him."} end
if not DB[10535] then DB[10535]={id=10535,zoneId=3358,name="Arathi Basin Resources!",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=10535",image="assets/images/quests/placeholder.png",xpDiff=5,money=132000,desc="War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!$B$BThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.$B$BThat is what I want from you, $N.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.",logDesc="Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe."} end
if not DB[10536] then DB[10536]={id=10536,zoneId=3358,name="More Resource Crates",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=10536",image="assets/images/quests/placeholder.png",xpDiff=3} end
if not DB[10537] then DB[10537]={id=10537,zoneId=3520,name="Lohn'goron, Bow of the Torn-heart",level=70,minLevel=68,giver="Spirit of Ar'tor",giverType="NPC",giverId=21318,ender="Spirit of Ar'tor",enderType="NPC",enderId=21318,rewardNextId=10540,poiX=-3800,poiY=2601,wowhead="https://www.wowhead.com/wotlk/quest=10537",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is a sign, $N. Even in death, I cannot be stopped. Recovering a part of the Cipher of Damnation is my destiny. With your help, that destiny will be fulfilled.$B$BBefore we embark on that journey, I must have my longbow, Lohn'goron. It is a family heirloom that has been handed down from Torn-heart to Torn-heart for generations.$B$BMy instinct tells me that a demon stole it from my corpse. Kill the demons here until you find my bow. ",logDesc="The Spirit of Ar'tor at Illidari Point in Shadowmoon Valley wants you to recover Lohn'goron, Bow of the Torn-heart from the demons of the area."} end
if not DB[10538] then DB[10538]={id=10538,zoneId=3483,name="Boiling Blood",level=60,minLevel=58,giver="Apothecary Albreck",giverType="NPC",giverId=21279,ender="Apothecary Albreck",enderType="NPC",enderId=21279,rewardNextId=10835,poiX=-1335,poiY=2382,wowhead="https://www.wowhead.com/wotlk/quest=10538",image="assets/images/quests/placeholder.png",xpDiff=5,money=9000,desc="That last experiment was not a complete loss -- I did save a small bit of the blood you brought me.  Now boiled down, it should be free of whatever curses the Bleeding Hollow witches placed on their people's blood.$B$BI need more for study.  Go gather Bleeding Hollow blood from the orcs in Zeth'Gor.  When you've gathered the blood, bring it to their cursed cauldron and boil it.  Bring me the boiled blood.",logDesc="Use Bleeding Hollow Blood at the Cursed Cauldron to make Boiled Blood.  Bring 12 Boiled Blood to Apothecary Albreck at Spinebreaker Post."} end
if not DB[10539] then DB[10539]={id=10539,zoneId=-262,name="Returning Home",level=10,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=10539",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A $r $c...$b$bYes, there was a priest of your order here recently, $n.  He told me it was time you returned to the Exodar met with Caedmos.  There was a sense of urgency in his request, so I wouldn't take too long to see him.",logDesc="Caedmos at the Exodar has requested you come see him."} end
if not DB[10540] then DB[10540]={id=10540,zoneId=3520,name="The Cipher of Damnation - Ar'tor's Charge",level=70,minLevel=68,giver="Spirit of Ar'tor",giverType="NPC",giverId=21318,ender="Spirit of Ar'tor",enderType="NPC",enderId=21318,rewardNextId=10541,poiX=-3800,poiY=2601,wowhead="https://www.wowhead.com/wotlk/quest=10540",image="assets/images/quests/placeholder.png",xpDiff=6,desc="At last, we are ready. I will bestow a piece of my spirit upon you, hero. It will guard you and help you in your battle against evil.$B$BYou must then travel south of here towards the back of Illidari Point. Hidden in the ether is a vile creature known as Veneratus the Many. My spirit hunter will call him out when he is near.$B$BDestroy Veneratus and take from his corpse the second part of the Cipher of Damnation.",logDesc="The Spirit of Ar'tor at Illidari Point in Shadowmoon Valley wants you to recover the Second Fragment of the Cipher of Damnation from Veneratus the Many.$B$BCreatures attacked or damaged by the Spirit Hunter will not yield loot or experience."} end
if not DB[10541] then DB[10541]={id=10541,zoneId=3520,name="The Cipher of Damnation - The Second Fragment Recovered",level=70,minLevel=68,giver="Spirit of Ar'tor",giverType="NPC",giverId=21318,ender="Oronok Torn-heart",enderType="NPC",enderId=21183,poiX=-3800,poiY=2601,wowhead="https://www.wowhead.com/wotlk/quest=10541",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I thank you, hero. For without you, my spirit would forever remain in this cursed place.$B$B<Ar'tor hands you a spectral lockbox.>$B$BTake it and deliver it to my father at the farm, far to the northeast, above Coilskar Cistern... Inside are Lohn'goron and the second part of the cipher.$B$BHe will be sad to hear news of my death. Promise me that you will assure him that I died a free soul. Tell him that I see the hunting grounds and they are glorious. Tell him that I wait for him there...",logDesc="Take Ar'tor's Lockbox to Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley.$B",choiceRewards={{id=30936,qty=1},{id=30931,qty=1},{id=30957,qty=1},{id=30971,qty=1},{id=30959,qty=1}}} end
if not DB[10542] then DB[10542]={id=10542,zoneId=3522,name="They Stole Me Hookah and Me Brews!",level=66,minLevel=65,giver="T'chali the Witch Doctor",giverType="NPC",giverId=21349,ender="T'chali the Witch Doctor",enderType="NPC",enderId=21349,rewardNextId=10545,poiX=1793,poiY=6406,wowhead="https://www.wowhead.com/wotlk/quest=10542",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="T'chali used to be a pretty friendly troll.  Me come down here to teach the Bloodmaul how to brew their beer.  But once me do that, the Bloodmaul bury T'chali and leave him here to rot!$B$BThe worst part of it was that they stole me hookah!$B$BSo, you want to help T'chali?  You bring me hookah back.  T'chali think the ogres that stole it headed southwest over by the mine.$B$BAnd while you're in there, pick up some brews, too!",logDesc="Collect T'chali's Hookah and 10 Bloodmaul Brutebane Brews."} end
if not DB[10543] then DB[10543]={id=10543,zoneId=3522,name="Grimnok and Korgaah, I Am For You!",level=67,minLevel=65,giver="T'chali the Witch Doctor",giverType="NPC",giverId=21349,ender="T'chali the Witch Doctor",enderType="NPC",enderId=21349,rewardNextId=10544,poiX=1793,poiY=6406,wowhead="https://www.wowhead.com/wotlk/quest=10543",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="T'chali has been waiting for his revenge!$B$BThe day they bury T'chali and leave him to die, it was Grimnok Battleborn that led them.  And the next day it was Korgaah that come south to raid and kick T'chali in the head.$B$BI want them dead!$B$BYou will find Grimnok atop the Southmaul Tower in Bloodmaul Outpost.  You will find Korgaah in the top of a building at the north end of Bladespire Hold.  Korgaah has sober defenders, so use the brew to distract him away from them, because they won't drink.",logDesc="Slay Grimnok Battleborn and Korgaah."} end
if not DB[10544] then DB[10544]={id=10544,zoneId=3522,name="A Curse Upon Both of Your Clans!",level=66,minLevel=65,giver="T'chali the Witch Doctor",giverType="NPC",giverId=21349,ender="T'chali the Witch Doctor",enderType="NPC",enderId=21349,poiX=1793,poiY=6406,wowhead="https://www.wowhead.com/wotlk/quest=10544",image="assets/images/quests/placeholder.png",xpDiff=6,money=70000,desc="T'chali wants revenge on all of the ogres!$B$BT'chali was a powerful witch doctor in life.  If you reach into me grave you will find a wicked strong fetish.$B$BInvoke the fetish's magic at the entrances to the buildings and towers of both Bladespire Hold and Bloodmaul Outpost.  The voodoo you work will summon an evil spirit that you must defeat.  This in turn will curse that building.$B$BBeware, if you attempt to curse a building that is already cursed, you will call down another cursed spirit!",logDesc="Use the Wicked Strong Fetish to curse 5 buildings or towers in Bladespire Hold and 2 in Bloodmaul Outpost.",choiceRewards={{id=31470,qty=1},{id=31471,qty=1},{id=31472,qty=1},{id=31473,qty=1}}} end
if not DB[10545] then DB[10545]={id=10545,zoneId=3522,name="Bladespire Kegger",level=66,minLevel=65,giver="T'chali the Witch Doctor",giverType="NPC",giverId=21349,ender="T'chali the Witch Doctor",enderType="NPC",enderId=21349,rewardNextId=10543,poiX=1793,poiY=6406,wowhead="https://www.wowhead.com/wotlk/quest=10545",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="As T'chali was saying, he helped out his Bloodmaul friends to make their brew.  But what T'chali did not say was why.$B$BThe Bloodmaul are in dire straits.  The Bladespire clan be crushing them, and they needed a new weapon to help out with their fight.$B$BThat's when T'chali came up with a great idea.  Why not make the perfect brew, one that strengthens you and weakens your enemy?  Only thing is, T'chali does not know if it works.$B$BSo, you gonna take this brew up to Bladespire Hold and see if it works!",logDesc="Use the Bloodmaul Brutebane Keg to get 5 Bladespire Ogres drunk."} end
if not DB[10546] then DB[10546]={id=10546,zoneId=3520,name="Borak, Son of Oronok",level=70,minLevel=68,giver="Oronok Torn-heart",giverType="NPC",giverId=21183,ender="Borak, Son of Oronok",enderType="NPC",enderId=21293,rewardNextId=10547,poiX=-2810,poiY=1258,wowhead="https://www.wowhead.com/wotlk/quest=10546",image="assets/images/quests/placeholder.png",xpDiff=2,desc="While Ar'tor was off hunting and Grom'tor was off fighting, Borak studied. Eventually he took up a vocation as a scholar and left for the wilds of Draenor. He returned home a few years ago a changed orc.$B$BHis heightened sense of awareness and mental acuity had forged a silent assassin.$B$BNow a confident and powerful orc, he has taken to recovering the most guarded piece of the cipher.$B$BFind Borak hiding near Eclipse Point, far to the south. He watches from the shadows of the bridge.",logDesc="Find Borak, Son of Oronok near Eclipse Point in Shadowmoon Valley."} end
if not DB[10547] then DB[10547]={id=10547,zoneId=3520,name="Of Thistleheads and Eggs...",level=70,minLevel=68,giver="Borak, Son of Oronok",giverType="NPC",giverId=21293,ender="Tobias the Filth Gorger",enderType="NPC",enderId=21411,poiX=-4044,poiY=1609,wowhead="https://www.wowhead.com/wotlk/quest=10547",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'd have given up had I not noticed... He's a Thistlehead. I couldn't place it at first but the signs are all there...$B$BNow if we could get our hands on some bloodthistle, we'd be in business.$B$BIn my travels, I met a shady Broken in Shattrath named Tobias.$B$BTobias made a business of trading bloodthistle to blood elves for rotten arakkoa eggs.$B$BDirectly west of here are arakkoa ruins. Search them for an egg and head to the lower city of Shattrath. That's where you'll find Tobias.",logDesc="Borak, Son of Oronok at the bridge north of Eclipse Point wants you to find a Rotten Arakkoa Egg and deliver it to Tobias the Filth Gorger in Shattrath City, located in northwest Terokkar Forest."} end
if not DB[10548] then DB[10548]={id=10548,zoneId=-162,name="The Sad Truth",level=18,minLevel=16,giver="Eralan",giverType="NPC",giverId=16268,ender="Eralan",enderType="NPC",enderId=16268,poiX=7512,poiY=-6841,wowhead="https://www.wowhead.com/wotlk/quest=10548",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Remember how I told you about the fat merchant who was looking for that ring?  As it turns out, he had his archeologist son looking for the thing and it didn't turn out so well.  By not so well I mean they killed him and shrunk his head.$b$bNow this might seem cold, calculating, and exceptionally callous, but he'd pay a lot to get his son's head back.  Sounds like the perfect job for you!$b$bGo east until you find the troll ruins of Zeb'Tela and Zeb'Nowa.  You're bound to find it one of the chests there.",logDesc="Eralan in Tranquillien wants you to retrieve the Archeologist's Shrunken Head from one of the chests in Zeb'Tela or Zeb'Nowa.",choiceRewards={{id=30504,qty=1},{id=30505,qty=1}}} end
if not DB[10549] then DB[10549]={id=10549,zoneId=-162,name="REUSE",level=18,minLevel=16,wowhead="https://www.wowhead.com/wotlk/quest=10549",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Remember how I told you about the fat merchant who was looking for that ring?  As it turns out,he had his archeologist son looking for the thing and it didn't turn out so well.  By not so well I mean they killed him and shrunk his head.$b$bNow this might seem cold,calculating,and exceptionally callous,but he'd pay a lot to get his son's head back.  Sounds like the perfect job for you!$b$bGo east until you find the troll ruins of Zeb'Tela and Zeb'Nowa.  You're bound to find it one of the chests there.",logDesc="Eralan in Tranquillien wants you to retrieve the Archeologist's Shrunken Head from one of the chests in Zeb'Tela or Zeb'Nowa.",choiceRewards={{id=30504,qty=1},{id=30505,qty=1}}} end
if not DB[10550] then DB[10550]={id=10550,zoneId=3520,name="The Bundle of Bloodthistle",level=70,minLevel=68,giver="Tobias the Filth Gorger",giverType="NPC",giverId=21411,ender="Borak, Son of Oronok",enderType="NPC",enderId=21293,rewardNextId=10570,poiX=-2084,poiY=5300,wowhead="https://www.wowhead.com/wotlk/quest=10550",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I wasn't lying. That egg was incredible. Where did you get it from?$B$BWell, if you ever need more bloodthistle, you know where I am and what I need.$B$BHere's a bundle of the stuff. Take it back to your benefactor.",logDesc="Take the Bundle of Bloodthistle back to Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley.$B"} end
if not DB[10551] then DB[10551]={id=10551,zoneId=3703,name="Allegiance to the Aldor",level=65,minLevel=60,giver="Khadgar",giverType="NPC",giverId=18166,ender="Khadgar",enderType="NPC",enderId=18166,poiX=-1860,poiY=5420,wowhead="https://www.wowhead.com/wotlk/quest=10551",image="assets/images/quests/placeholder.png"} end
if not DB[10552] then DB[10552]={id=10552,zoneId=3703,name="Allegiance to the Scryers",level=65,minLevel=60,giver="Khadgar",giverType="NPC",giverId=18166,ender="Khadgar",enderType="NPC",enderId=18166,poiX=-1860,poiY=5420,wowhead="https://www.wowhead.com/wotlk/quest=10552",image="assets/images/quests/placeholder.png"} end
if not DB[10553] then DB[10553]={id=10553,zoneId=3703,name="Voren'thal the Seer",level=65,minLevel=60,giver="Khadgar",giverType="NPC",giverId=18166,ender="Voren'thal the Seer",enderType="NPC",enderId=18530,poiX=-1860,poiY=5420,wowhead="https://www.wowhead.com/wotlk/quest=10553",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Now that you've chosen a side, $N, you should meet the Scryers' leader.$B$BYou will find Voren'thal the Seer inside the Seer's Library at the Scryer's Tier.$B$BSee if you can be of assistance to him.  He will be glad to hear you've decided to lend them a hand.",logDesc="Speak to Voren'thal the Seer inside the Seer's Library at the Scryer's Tier in Shattrath City.$B$BPerforming quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10554] then DB[10554]={id=10554,zoneId=3703,name="Ishanah",level=65,minLevel=60,giver="Khadgar",giverType="NPC",giverId=18166,ender="Ishanah",enderType="NPC",enderId=18538,poiX=-1860,poiY=5420,wowhead="https://www.wowhead.com/wotlk/quest=10554",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Now that you've decided to side with the Aldor, you'd do well to introduce yourself to their leader.  You will find High Priestess Ishanah inside the Shrine of Unending Light.",logDesc="Speak to Ishanah inside the Shrine of Unending Light at the Aldor Rise in Shattrath City.$B$BPerforming quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10555] then DB[10555]={id=10555,zoneId=3522,name="Malaise",level=66,minLevel=65,giver="Daranelle",giverType="NPC",giverId=21469,rewardNextId=10556,poiX=2035,poiY=6835,wowhead="https://www.wowhead.com/wotlk/quest=10555",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The magic practiced by the Lashh'an arakkoa is unnatural. They rip out handfuls-clawfuls?-of their own feathers as reagents!$b$bThat doesn't sound like good magic to me. I've come here to learn more about their spells. Unfortunately getting close is too much for me.$b$bYou could succeed: cast one of their spells on yourself, then return to me. You'll have to find one of their spellbooks, high up in the trees of Veil Lashh.$b$bAnd unless you've grown feathers I can't see, you'll need to get some of those.$B",logDesc="Collect 18 Plucked Lashh'an Feathers."} end
if not DB[10556] then DB[10556]={id=10556,zoneId=3522,name="Scratches",level=66,minLevel=65,ender="Daranelle",enderType="NPC",enderId=21469,wowhead="https://www.wowhead.com/wotlk/quest=10556",image="assets/images/quests/placeholder.png",xpDiff=4,money=35000,desc="The pictograms indicate using feathers to cast the spell at one of the circles of power in Veil Lashh.$b$bConfusing iconography seems to show an arakkoa being suffused with the spirit of a kaliri.",logDesc="Use the Fistful of Feathers on the Lashh'an Spell Circle."} end
if not DB[10557] then DB[10557]={id=10557,zoneId=3522,name="Test Flight: The Zephyrium Capacitorium",level=64,minLevel=62,giver="Tally Zapnabber",giverType="NPC",giverId=21460,ender="Tally Zapnabber",enderType="NPC",enderId=21460,rewardNextId=10710,poiX=1935,poiY=5576,wowhead="https://www.wowhead.com/wotlk/quest=10557",image="assets/images/quests/placeholder.png",xpDiff=2,money=8000,desc="I built an amazing device, the Zephyrium Capacitorium, and I'm sure it'll work perfectly, but... do you want to help me test it?$B$BThere's plenty of hazard pay!$B$BSpeak with my twin over there, Rally. Good luck, $N. Come back after your experiment.  Or... if that's not possible due to sustained injuries, your next of kin can report to collect your pay.",logDesc="Speak with Rally Zapnabber and use the Zephyrium Capacitorium."} end
if not DB[10558] then DB[10558]={id=10558,zoneId=3545,name="Revered Among Honor Hold",level=70,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=10558",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You've proven your worth to our cause, $N.  One such as yourself could one day become a great leader.$B$BContinue to fight our enemies in the Shattered Halls and gain renown among my men.  If you live up to my expectations I will have greater tasks to ask of you.",logDesc="Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula wants you to become revered with Honor Hold by fighting Fel Orcs inside the Shattered Halls of Hellfire Citadel."} end
if not DB[10559] then DB[10559]={id=10559,zoneId=3535,name="Revered Among Thrallmar",level=70,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=10559",image="assets/images/quests/placeholder.png",desc="You've proven yourself time and again, $c.  Yet more trials await you.$B$BContinue to fight the Fel Horde inside the Shattered Halls of Hellfire Citadel and your name will be known to all of Thrall's followers in this land.",logDesc="Nazgrel at Thrallmar in Hellfire Peninsula wants you to become revered with Thrallmar by fighting the Fel Orcs inside the Shattered Halls of Hellfire Citadel."} end
if not DB[10560] then DB[10560]={id=10560,zoneId=3842,name="Revered Among the Sha'tar",level=70,minLevel=68,giver="A'dal",giverType="NPC",giverId=18481,ender="A'dal",enderType="NPC",enderId=18481,poiX=-1864,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=10560",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<The calming melodic tones projected by A'dal become more hushed and somber.>$B$B<You are shown the large naaru structure known as Tempest Keep.  It is now inhabited by the forces of Kael'thas and its power used for nefarious ends.  A'dal promises you greater tasks once you've done your part to take back Tempest Keep.>",logDesc="A'dal in Shattrath City wants you to become revered with the Sha'tar by defeating the forces of Kael'thas inside Tempest Keep."} end
if not DB[10561] then DB[10561]={id=10561,zoneId=2300,name="Revered Among the Keepers of Time",level=70,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=10561",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You've proven yourself to us, $r.  The timeline is not yet safe, however.$B$BWe're in need of true champions and you may prove to be one.$B$BContinue to defend the events of the past from intruders and you'll get the renown you deserve.",logDesc="Andormu inside the Caverns of Time in Tanaris wants you to become revered with the Keepers of Time by continuing to defend the events of Old Hillsbrad and the Black Morass inside the Caverns of Time."} end
if not DB[10562] then DB[10562]={id=10562,zoneId=3520,name="Besieged!",level=69,minLevel=67,giver="Wing Commander Nuainn",giverType="NPC",giverId=21357,ender="Wing Commander Nuainn",enderType="NPC",enderId=21357,rewardNextId=10563,poiX=-3918,poiY=2052,wowhead="https://www.wowhead.com/wotlk/quest=10562",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Don't let your guard down, $r. We're under constant assault from the Burning Legion.$B$BFrom their base of Legion Hold to the northwest, the demons rain down a ceaseless stream of infernals. As quickly as we can kill them, the new meteors impact and begin a new wave of attacks.$B$BMy men are ragged and exhausted. I don't know how much longer they'll hold out. Please, $N, lend your help to our defenses. Take your place on the line and halt the advance of the infernals!",logDesc="Wing Commander Nuainn, outside of Wildhammer Stronghold, wants you to kill 10 Infernal Attackers."} end
if not DB[10563] then DB[10563]={id=10563,zoneId=3520,name="To Legion Hold",level=69,minLevel=67,giver="Wing Commander Nuainn",giverType="NPC",giverId=21357,ender="Wing Commander Nuainn",enderType="NPC",enderId=21357,rewardNextId=10572,poiX=-3918,poiY=2052,wowhead="https://www.wowhead.com/wotlk/quest=10563",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The fortress of Legion Hold is nigh impregnable, and to be completely honest, I can't spare the forces for an assault. Our hopes are riding on you, $N.$B$BWhat little information we've been able to gather indicates that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I'll give you, you must sneak into Legion Hold and learn about their plans. Your best hope is to intercept or overhear communication between their commanders. Good luck, $N.",logDesc="Make your way to Legion Hold and locate the Legion Communication Device. While standing near the communication device, use your disguise and learn about the Legion's plans. Return to Wing Commander Nuainn at Wildhammer Stronghold when you've completed your mission."} end
if not DB[10564] then DB[10564]={id=10564,zoneId=3520,name="Blast the Infernals!",level=69,minLevel=67,giver="Wing Commander Nuainn",giverType="NPC",giverId=21357,ender="Wing Commander Nuainn",enderType="NPC",enderId=21357,rewardNextId=10573,poiX=-3918,poiY=2052,wowhead="https://www.wowhead.com/wotlk/quest=10564",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The device we've assembled won't win any beauty contests, but it should be capable of destroying the infernals amassed at Legion Hold. Judging from what the fel reaver power core's energy did to the Fetid Pool, it holds a respectable amount of explosive power.$B$BIf you set the device off in the middle of the green glyph at the hold, it should be in range to hit all of the infernals.",logDesc="Use the Fel Bomb while standing on the green glyph in Legion Hold, then report to Wing Commander Nuainn at Wildhammer Stronghold.",choiceRewards={{id=30986,qty=1},{id=30947,qty=1},{id=30946,qty=1},{id=30929,qty=1}}} end
if not DB[10565] then DB[10565]={id=10565,zoneId=3522,name="The Stones of Vekh'nir",level=66,minLevel=61,giver="Dertrok",giverType="NPC",giverId=21496,ender="Dertrok",enderType="NPC",enderId=21496,poiX=2162,poiY=4770,wowhead="https://www.wowhead.com/wotlk/quest=10565",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The arakkoa of Vekh'nir have been a thorn in our sides for many years. Some strange religion guides them, a religion which has the arakkoa in a frenzy of activity. They carry these crystals with them now, which they have turned to some dark purpose.$b$bI know something of their rituals. They take the crystals to their spell circles to infuse them. We at the village would like to know more. Waylay a few of the arakkoa until you find a crystal, charge it, then return it to me.",logDesc="Collect and use a Vekh'nir Crystal at the Vekh'nir Spell Circle to create a Charged Vekh'nir Crystal."} end
if not DB[10566] then DB[10566]={id=10566,zoneId=3522,name="Trial and Error",level=66,minLevel=61,giver="Dertrok",giverType="NPC",giverId=21496,ender="Dertrok",enderType="NPC",enderId=21496,rewardNextId=10615,poiX=2162,poiY=4770,wowhead="https://www.wowhead.com/wotlk/quest=10566",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="I've fashioned four wands that I believe will enhance the power of the arakkoa's crystals. Take these wands to Trogma's Claim, and try them on the ogre slaves.$b$bYou'll need to find an infused crystal off of the arakkoa in the area.$b$bWhen you figure out which is best, come back to me.",logDesc="Try out each of Dertrok's wands on an Arakkoa Ogre Slave. Each wand will require an Infused Vekh'nir Crystal to use."} end
if not DB[10567] then DB[10567]={id=10567,zoneId=3522,name="Creating the Pendant",level=66,minLevel=66,giver="Timeon",giverType="NPC",giverId=21782,ender="Timeon",enderType="NPC",enderId=21782,rewardNextId=10607,poiX=2994,poiY=5474,wowhead="https://www.wowhead.com/wotlk/quest=10567",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The arakkoa of Ruaan Weald elevate from their flock the Harbingers of the Raven, the heralds of their god.$b$bThey believe that the Harbingers watch over them from the sky, where they receive the teachings of the Raven, and descend to pass this message along.$b$bThe Harbingers hold a powerful sway over the souls of the arakkoa. They use magical pendants, which we need.$b$bAttract one of the Harbingers by slaying its flock and taking their claws. Place the claws upon the altar to get his attention.",logDesc="Collect 6 Ruuan'ok Claws and use them at the Ruaan'ok Oracle Circle to summon a Harbinger of the Raven. Kill it to collect its Harbinger's Pendant."} end
if not DB[10568] then DB[10568]={id=10568,zoneId=3520,name="Tablets of Baa'ri",level=70,minLevel=68,giver="Anchorite Ceyla",giverType="NPC",giverId=21402,ender="Anchorite Ceyla",enderType="NPC",enderId=21402,rewardNextId=10571,poiX=-2988,poiY=783,wowhead="https://www.wowhead.com/wotlk/quest=10568",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Years ago, the dreaded warlock known as Gul'dan raised the volcano in the middle of Shadowmoon.  The draenei village of Baa'ri, to the southwest, was buried under the lava along with its inhabitants and artifacts of religious importance.$B$BThe treacherous tribe of Broken known as the Ashtongue has been ordered by Illidan to excavate the area.  We must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to hold the secrets of the Temple of Karabor, now known as the Black Temple.",logDesc="Anchorite Ceyla at the Altar of Sha'tar wants you to collect 12 Baa'ri Tablets from the ground and from Ashtongue Workers at the Ruins of Baa'ri.$B$BCompleting quests with the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10569] then DB[10569]={id=10569,zoneId=3520,name="The Sketh'lon Wreckage",level=69,minLevel=67,giver="Gryphonrider Kieran",giverType="NPC",giverId=22042,ender="Gryphonrider Kieran",enderType="NPC",enderId=22042,rewardNextId=10759,poiX=-3936,poiY=2092,wowhead="https://www.wowhead.com/wotlk/quest=10569",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Our scouts have brought back disturbing reports from the ruined arakkoa encampments in the area.$B$BThe ghosts of powerful arakkoa magicians wield powers we never thought they possessed. They seem to be organizing, as though preparing for something, but our knowledge is limited. We cannot afford to remain ignorant!$B$BTravel north to the Sketh'lon Wreckage, to the northwest of the Deathforge and search for signs of their motives.",logDesc="Recover the Skethlon Commander's Journal Page 1, Skethlon Commander's Journal Page 2, and Skethlon Commander's Journal Page 3 from the Dark Conclave arakkoa at the Sketh'lon Wreckage to Gryphonrider Kieran."} end
if not DB[10570] then DB[10570]={id=10570,zoneId=3520,name="To Catch A Thistlehead",level=70,minLevel=68,giver="Borak, Son of Oronok",giverType="NPC",giverId=21293,ender="Borak, Son of Oronok",enderType="NPC",enderId=21293,rewardNextId=10576,poiX=-4044,poiY=1609,wowhead="https://www.wowhead.com/wotlk/quest=10570",image="assets/images/quests/placeholder.png",xpDiff=4,desc="<Borak takes the bundle of bloodthistle from you and places it to his nose.>$B$BPungent...$B$BNow, take this bundle and place it at the other end of this bridge. When the envoy makes his daily rounds, he will be compelled to pick it up - without his bodyguard. You see, blood elves look down upon bloodthistle addicts. If any of his compatriots ever found out...$B$BAll you need to do is lie in wait for him to dismiss his bodyguard. When he is alone, make your strike! Kill him and take the missive.",logDesc="Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to recover the Stormrage Missive."} end
if not DB[10571] then DB[10571]={id=10571,zoneId=3520,name="Oronu the Elder",level=70,minLevel=68,giver="Anchorite Ceyla",giverType="NPC",giverId=21402,ender="Anchorite Ceyla",enderType="NPC",enderId=21402,rewardNextId=10574,poiX=-2988,poiY=783,wowhead="https://www.wowhead.com/wotlk/quest=10571",image="assets/images/quests/placeholder.png",xpDiff=5,desc="According to the tablets, an artifact known as a Medallion of Karabor was kept at Baa'ri.  Only the highest-ranking draenei priests were granted these, as they allowed unfettered access into the Temple of Karabor.$B$BWe must find out whether the Ashtongue have recovered the medallion that was kept at Baa'ri yet.  Its power would provide great aid in our fight against Illidan.$B$BAkama's lieutenant at Baa'ri, Oronu the Elder, receives written orders from him daily.  Obtain them and bring them to me.",logDesc="Anchorite Ceyla at the Altar of Sha'tar wants you to obtain the Orders from Akama from Oronu the Elder at the Ruins of Baa'ri.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10572] then DB[10572]={id=10572,zoneId=3520,name="Setting Up the Bomb",level=69,minLevel=67,giver="Wing Commander Nuainn",giverType="NPC",giverId=21357,ender="Wing Commander Nuainn",enderType="NPC",enderId=21357,rewardNextId=10564,poiX=-3918,poiY=2052,wowhead="https://www.wowhead.com/wotlk/quest=10572",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="We cannot permit the Legion to carry out its plan to destroy Wildhammer Stronghold on their march to the Black Temple.$B$BThere's only one way to stop them, $N. You must create an explosive large enough to destroy the Legion's entire stockpile of infernals at the hold.$B$BThe Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the base of your device. Search the other wreckage near the fel reaver for armor plating we might be able to make a casing from.",logDesc="Obtain a Fel Reaver Power Core and a Fel Reaver Armor Plate and bring them to Wing Commander Nuainn at Wildhammer Stronghold."} end
if not DB[10573] then DB[10573]={id=10573,zoneId=3520,name="The Deathforge",level=69,minLevel=67,giver="Wing Commander Nuainn",giverType="NPC",giverId=21357,ender="Stormer Ewan Wildwing",enderType="NPC",enderId=21471,rewardNextId=10582,poiX=-3918,poiY=2052,wowhead="https://www.wowhead.com/wotlk/quest=10573",image="assets/images/quests/placeholder.png",xpDiff=1,desc="From your findings at Legion Hold, we know that the Legion's Shadow Council allies are producing infernals in the Deathforge. I've dispatched a small scouting party to keep watch over the area, but they're not able to accomplish everything we need.$B$BIf the Deathforge is left alone to operate, they'll rebuild the infernal stockpile that you destroyed at Legion Hold.$B$BI want you to meet up with Stormer Ewan Wildwing, at the Deathforge Tower, to the northwest, overlooking the Deathforge itself.",logDesc="Report to Stormer Ewan Wildwing at the Deathforge Tower."} end
if not DB[10574] then DB[10574]={id=10574,zoneId=3520,name="The Ashtongue Corruptors",level=70,minLevel=68,giver="Anchorite Ceyla",giverType="NPC",giverId=21402,ender="Anchorite Ceyla",enderType="NPC",enderId=21402,rewardNextId=10575,poiX=-2988,poiY=783,wowhead="https://www.wowhead.com/wotlk/quest=10574",image="assets/images/quests/placeholder.png",xpDiff=5,desc="According to Akama's letter, four fragments of the medallion were unearthed and given to the Ashtongue Corruptors.  These dreaded Broken were once powerful shaman who now defile the very elements they revered.$B$BHaalum, Corruptor of Air, can be found at Netherwing Pass.  Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at the Fel Pits near the Hand of Gul'dan.  Lakaan, Corruptor of Water, is rumored to be near Coilskar Point.$B$BFind them and obtain the medallion fragments.",logDesc="Obtain the four medallion fragments from Haalum, Eykenen, Lakaan and Uylaru and return to Anchorite Ceyla at the Altar of Sha'tar in Shadowmoon Valley.$B$BPerforming quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10575] then DB[10575]={id=10575,zoneId=3520,name="The Warden's Cage",level=70,minLevel=68,giver="Anchorite Ceyla",giverType="NPC",giverId=21402,ender="Sanoru",enderType="NPC",enderId=21826,rewardNextId=10622,poiX=-2988,poiY=783,wowhead="https://www.wowhead.com/wotlk/quest=10575",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The fragments you obtained are only half of the medallion.  The Ashtongue leader, Akama, must have kept the other half.$B$BI dread to ask this of you, as Akama is both evil and cunning.$B$BHe and the Ashtongue Deathsworn - the vilest and most brutal of the tribe - are rumored to run a torture chamber inside the Warden's Cage.$B$BI want you to find that dreaded prison,  and find the whereabouts of Akama.  His second in command at the location is a Broken known as Sanoru - interrogate him if you have to.",logDesc="Anchorite Ceyla wants you to enter the Warden's Cage, south of the Ruins of Baa'ri and interrogate Sanoru on Akama's whereabouts.$B$BCompleting quests for the Aldor will cause your Scryers reputation to decrease."} end
if not DB[10576] then DB[10576]={id=10576,zoneId=3520,name="The Shadowmoon Shuffle",level=70,minLevel=68,giver="Borak, Son of Oronok",giverType="NPC",giverId=21293,ender="Borak, Son of Oronok",enderType="NPC",enderId=21293,rewardNextId=10577,poiX=-4044,poiY=1609,wowhead="https://www.wowhead.com/wotlk/quest=10576",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Borak looks you up and down.>$B$BThis is going to be tricky, but I think I can make it work.$B$BI can disguise you as one of these Illidari blood elves, $N. What I need first, though, are several pieces of their armor. It is imperative that the armor be clean. No blood stains! We want to avoid suspicion.$B$BBring me the gear and I'll take care of the rest of the disguise.$B$BOnce the disguise is assembled, you're going to deliver the message to the Grand Commander - in person.",logDesc="Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to recover 6 pieces of Eclipsion Armor.$B"} end
if not DB[10577] then DB[10577]={id=10577,zoneId=3520,name="What Illidan Wants, Illidan Gets...",level=70,minLevel=68,giver="Borak, Son of Oronok",giverType="NPC",giverId=21293,ender="Borak, Son of Oronok",enderType="NPC",enderId=21293,rewardNextId=10578,poiX=-4044,poiY=1609,wowhead="https://www.wowhead.com/wotlk/quest=10577",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Take this disguise and enter Eclipse Point. Once inside, use the disguise to cloak yourself. The Eclipsion blood elves will be unable to see through the disguise, thereby granting you safe passage to Grand Commander Ruusk.$B$BOnce you find Ruusk, tell him where next to move the cipher. You're going to have to act your heart out, $N. Play it off as if you are his superior, delivering a message from his lord. That should do it!$B$BOh - watch out for the dragonhawks as they see through the disguise.",logDesc="Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to Deliver Illidan's Message to Grand Commander Ruusk at Eclipse Point."} end
if not DB[10578] then DB[10578]={id=10578,zoneId=3520,name="The Cipher of Damnation - Borak's Charge",level=70,minLevel=68,giver="Borak, Son of Oronok",giverType="NPC",giverId=21293,ender="Borak, Son of Oronok",enderType="NPC",enderId=21293,rewardNextId=10579,poiX=-4044,poiY=1609,wowhead="https://www.wowhead.com/wotlk/quest=10578",image="assets/images/quests/placeholder.png",xpDiff=5,desc="That Cipher fragment will never reach Zuluhed. You're going to ambush Ruul the Darkener and his transport before it has a chance to make the delivery.$B$BThe Dragonmaw Fortress is directly east of here, across the Netherwing Fields. Somewhere between Dragonmaw Fortress and the Sanctum of the Stars is where you'll find Ruul. Strike hard and strike fast! And $N, from the sound of it, this Ruul is going to be tough. Keep your guard up.$B$BReturn the Cipher to me should you succeed.$B",logDesc="Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to recover the Third Part of the Cipher of Damnation from Ruul the Darkener.$B$BThis mission will require a group."} end
if not DB[10579] then DB[10579]={id=10579,zoneId=3520,name="The Cipher of Damnation - The Third Fragment Recovered",level=70,minLevel=68,giver="Borak, Son of Oronok",giverType="NPC",giverId=21293,ender="Oronok Torn-heart",enderType="NPC",enderId=21183,poiX=-4044,poiY=1609,wowhead="https://www.wowhead.com/wotlk/quest=10579",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Take this box to my father. He still resides at Oronok's Farm, far to the north, above Coilskar Cistern. When all three fragments are pieced together, the ancient words will be known once more.$B$BGood luck, $N. Tell my father that I will be home soon.",logDesc="Take Borak's Lockbox to Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley.",choiceRewards={{id=30951,qty=1},{id=30962,qty=1},{id=30939,qty=1},{id=30925,qty=1},{id=30967,qty=1},{id=30944,qty=1}}} end
if not DB[10580] then DB[10580]={id=10580,zoneId=3522,name="Where Did Those Darn Gnomes Go?",level=67,minLevel=65,giver="Commander Skyshadow",giverType="NPC",giverId=21158,ender="3",enderType="NPC",enderId=21690,rewardNextId=10581,poiX=2015,poiY=6881,wowhead="https://www.wowhead.com/wotlk/quest=10580",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Despite the good that we've done here, I feel bad about one thing: driving Toshley and his gnome friends away.$B$BWe had no choice; they were making a mess of our efforts in the grove with all of their technology and experimentation.$B$BI would appreciate it if you would find out what became of them.  Last we heard, they headed east across the bridge.  I'm certain that they must have turned south, away from Thunderlord Stronghold.$B$BLook for a clue as to their whereabouts in the southern Jagged Ridge.",logDesc="Search the southern area of the Jagged Ridge of the Blade's Edge Mountains for a clue as to the whereabouts of Toshley and the other gnomes."} end
if not DB[10581] then DB[10581]={id=10581,zoneId=3522,name="Follow the Breadcrumbs",level=67,minLevel=65,giver="3",giverType="NPC",giverId=21690,ender="Toshley",enderType="NPC",enderId=21691,poiX=1776,poiY=5856,wowhead="https://www.wowhead.com/wotlk/quest=10581",image="assets/images/quests/placeholder.png",xpDiff=2,desc="VERY WELL, I AM HEREBY WARNING YOU THAT YOU WILL FIND NOTHING UP ON THE RIDGE.$B$BDO NOT FOLLOW THE TRAIL OF SPARE PARTS THAT LEAD TO TOSHLEY'S STATION!  YOU WILL NOT FIND TOSHLEY, NOR ANY OTHER GNOME THERE.",logDesc="Follow the trail of spare parts up the ramp to the Razor Ridge. Speak with Toshley at Toshley's Station in the Blade's Edge Mountains."} end
if not DB[10582] then DB[10582]={id=10582,zoneId=3520,name="Minions of the Shadow Council",level=69,minLevel=67,giver="Stormer Ewan Wildwing",giverType="NPC",giverId=21471,ender="Stormer Ewan Wildwing",enderType="NPC",enderId=21471,poiX=-3462,poiY=2000,wowhead="https://www.wowhead.com/wotlk/quest=10582",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="<Ewan listens to you recount the events at Legion Hold, nodding.>$B$BThat puts our observations into perspective. We've caught glimpses of them launching infernals in the direction of the hold, but haven't been able to find much more than that.$B$BThe Shadow Council has the Deathforge sealed tighter than a new keg o' thunderbrew. The first thing you'll need to do is crack some skulls so you can get in there and poke around. Start eliminating the Shadow Council guarding the entrance to the Deathforge!",logDesc="Stormer Ewan Wildwing at the Deathforge Tower wants you to kill 10 Deathforge Guardians and 5 Deathforge Summoners."} end
if not DB[10583] then DB[10583]={id=10583,zoneId=3520,name="The Fate of Flanis",level=69,minLevel=67,giver="Stormer Ewan Wildwing",giverType="NPC",giverId=21471,ender="Stormer Ewan Wildwing",enderType="NPC",enderId=21471,poiX=-3462,poiY=2000,wowhead="https://www.wowhead.com/wotlk/quest=10583",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Wing Commander Nuainn originally sent three of us out here to keep watch over the Deathforge and to gather information. Flanis Swiftwing volunteered to try to infiltrate the Deathforge, but we haven't heard anything from him in days.$B$BI fear the worst, $N. Flanis is a skilled scout, but if he's gotten in over his head, we have no way of knowing. Search the Deathforge for him and recover any information or items he might have collected.",logDesc="Stormer Ewan Wildwing at Deathforge Tower wants you to search the Deathforge for Flanis Swiftwing and recover Flanis's Pack."} end
if not DB[10584] then DB[10584]={id=10584,zoneId=3522,name="Picking Up Some Power Converters",level=67,minLevel=65,giver="Toshley",giverType="NPC",giverId=21691,ender="Toshley",enderType="NPC",enderId=21691,rewardNextId=10657,poiX=1914,poiY=5562,wowhead="https://www.wowhead.com/wotlk/quest=10584",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="Those dumb ogres at the Bladespire Outpost to the north have been raiding our power converters!  And you're going to get them back for me, sort of.$B$BNo doubt, with their big, clumsy hands, the ogres have damaged the converters.  So, what I want you to do is release the energy from them and then use this protovoltaic magneto collector on the resultant electromental to encase it.$B$BIt'll likely be sore with you, so you'll need to 'kill' it while it's contained in the magneto sphere.",logDesc="Use the Protovoltaic Magneto Collector to collect 5 Electromentals."} end
if not DB[10585] then DB[10585]={id=10585,zoneId=3520,name="The Summoning Chamber",level=69,minLevel=67,giver="Stormer Ewan Wildwing",giverType="NPC",giverId=21471,ender="Stormer Ewan Wildwing",enderType="NPC",enderId=21471,poiX=-3462,poiY=2000,wowhead="https://www.wowhead.com/wotlk/quest=10585",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="In order for the Shadow Council to construct infernals as quickly as they're being used, they must have an area dedicated to summoning the corrupted elementals that serve as the souls of the creatures.$B$BThe summoning chamber is likely to be found below ground, near a pool of fouled water or lava. Locate the summoning chamber within the Deathforge and find a way to end their summoning ritual. The mo'arg involved in making the infernals may carry a tool that will help disrupt the summoner's magics.",logDesc="Obtain an Elemental Displacer from a Deathforge Smith or Deathforge Tinkerer and use it to disrupt the ritual in the summoning  chamber. Report to Stormer Ewan Wildwing at the Deathforge Tower when you've completed your task."} end
if not DB[10586] then DB[10586]={id=10586,zoneId=3520,name="Bring Down the Warbringer!",level=69,minLevel=67,giver="Stormer Ewan Wildwing",giverType="NPC",giverId=21471,ender="Wing Commander Nuainn",enderType="NPC",enderId=21357,rewardNextId=10589,poiX=-3462,poiY=2000,wowhead="https://www.wowhead.com/wotlk/quest=10586",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="We've made a lot of progress against the Shadow Council's operations at the Deathforge, but if we're to truly be triumphant, we'll need to defeat the Legion's overseer there.$B$BI found a key among the items in Flanis's pack. I'm certain it will prove useful in tracking down this Warbringer Razuun you observed at Legion Hold.$B$BAfter you've hunted down and dealt with Warbringer Razuun, report directly to Wing Commander Nuainn. He'll want to know immediately!",logDesc="Defeat Warbringer Razuun, recover Razuun's Orders, and report to Wing Commander Nuainn at Wildhammer Stronghold."} end
if not DB[10587] then DB[10587]={id=10587,zoneId=3520,name="Karabor Training Grounds",level=70,minLevel=68,giver="Exarch Onaala",giverType="NPC",giverId=21860,ender="Exarch Onaala",enderType="NPC",enderId=21860,rewardNextId=10637,poiX=-3020,poiY=859,wowhead="https://www.wowhead.com/wotlk/quest=10587",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Our scouts have reported a massive influx of Sunfury blood elf recruits heading to the Ruins of Karabor.  Normally this would represent a purely military threat, however we believe something else is amiss.$B$BDescriptions of their attire and fighting style are suspiciously close to that of Illidan himself.  I do not want to become alarmed without good reason, so I would like you to go there and bring me back their weapons.  We will then determine whether my fears are unfounded or not.",logDesc="Exarch Onaala at the Altar of Sha'tar wants you to obtain 8 Sunfury Glaives from Demon Hunter Supplicants and Demon Hunter Initiates at the Ruins of Karabor, southeast of the Altar of Sha'tar.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10588] then DB[10588]={id=10588,zoneId=3520,name="The Cipher of Damnation",level=70,minLevel=68,giver="Oronok Torn-heart",giverType="NPC",giverId=21183,ender="Earthmender Torlok",enderType="NPC",enderId=21024,poiX=-2810,poiY=1258,wowhead="https://www.wowhead.com/wotlk/quest=10588",image="assets/images/quests/placeholder.png",xpDiff=7,desc="How many times has this spell been used in the history of our worlds? Undoubtedly, its power for destruction is unparalleled.$B$BWhat you must do now is take the cipher, now made whole, and read from it at the Altar of Damnation - where the memory of Gul'dan stands.$B$BWhat you will see once the words are uttered are the memories left imprinted upon the land. Stand your ground and await the coming of Cyrukh.$B$BYou must be victorious, $N. This land cannot withstand another shattering.",logDesc="Use the Cipher of Damnation at the Altar of Damnation to summon Cyrukh the Firelord.$B$BDestroy Cyrukh the Firelord and then speak with Earthmender Torlok, also found at the Altar of Damnation.",rewards={{id=31074,qty=1}},choiceRewards={{id=31073,qty=1},{id=31071,qty=1},{id=31072,qty=1},{id=31036,qty=1},{id=31062,qty=1},{id=31038,qty=1}}} end
if not DB[10589] then DB[10589]={id=10589,zoneId=3520,name="Gaining Access",level=69,minLevel=67,giver="Wing Commander Nuainn",giverType="NPC",giverId=21357,ender="Wing Commander Nuainn",enderType="NPC",enderId=21357,rewardNextId=10766,poiX=-3918,poiY=2052,wowhead="https://www.wowhead.com/wotlk/quest=10589",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="According to Razuun's orders, the massive infernal staging area is called Invasion Point: Cataclysm and it's nestled in the northern mountains. The only way to reach it is by using a teleporter located at Legion Hold.$B$BCertain members of the Legion host carry devices allowing them to activate the teleporters. You must capture one of these devices to win access to the teleporter. Slaughter all of the demons if you must, but you can't afford to return empty-handed.",logDesc="Bring a Legion Teleporter Control to Wing Commander Nuainn at Wildhammer Stronghold. The Mo'arg Weaponsmiths at Legion Hold are known to carry the devices."} end
if not DB[10590] then DB[10590]={id=10590,zoneId=-141,name="Prove Your Hatred",level=52,minLevel=50,giver="Mehlar Dawnblade",giverType="NPC",giverId=17099,ender="Mehlar Dawnblade",enderType="NPC",enderId=17099,rewardNextId=10592,poiX=1689,poiY=-727,wowhead="https://www.wowhead.com/wotlk/quest=10590",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is time you remembered history that should not be forgotten... the slaughter of our people by Arthas and his Scourge army.$b$bVengeance on the Scourge is the only way to ease your pain.  It is unfortunate they are not susceptible to fear and pain.  Only their utter destruction will bring you even a shred of satisfaction.$b$bSpeak with Argent Officer Garush for knowledge of scourgestones and how to obtain them -- I will need to see many of them as proof of your commitment before we speak again.",logDesc="Mehlar Dawnblade at the Bulwark wants you to bring him 20 Minion's Scourgestones."} end
if not DB[10591] then DB[10591]={id=10591,zoneId=-141,name="DESTROY THIS QUEST!",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=10591",image="assets/images/quests/placeholder.png",xpDiff=6,rewards={{id=30696,qty=1}}} end
if not DB[10592] then DB[10592]={id=10592,zoneId=-141,name="Wisdom of the Banshee Queen",level=52,minLevel=50,giver="Mehlar Dawnblade",giverType="NPC",giverId=17099,ender="3",enderType="NPC",enderId=10181,rewardNextId=10593,poiX=1689,poiY=-727,wowhead="https://www.wowhead.com/wotlk/quest=10592",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The scourgestones are weak when separated from the skeletal grasp that once held them.  Simply holding them in my hands has caused them to fracture and break.$b$b<Mehlar crushes the scourgestones into a pile of rubble.>$b$bTake these fragments to the Banshee Queen, Lady Sylvanas Windrunner, at her throne in Undercity.  With her lies the knowledge to turn these remains into a weapon against the Scourge.",logDesc="Bring the Scourgestone Fragments to Lady Sylvanas Windrunner in Undercity."} end
if not DB[10593] then DB[10593]={id=10593,zoneId=-141,name="Ancient Evil",level=52,minLevel=50,giver="3",giverType="NPC",giverId=10181,ender="Mehlar Dawnblade",enderType="NPC",enderId=17099,poiX=1290,poiY=316,wowhead="https://www.wowhead.com/wotlk/quest=10593",image="assets/images/quests/placeholder.png",xpDiff=7,desc="If you wish to turn these stones into a weapon to fight the Scourge, you must acquire something equally vile to fortify them.$b$bAn ancient evil lies hidden at the bottom of the Temple of Atal'Hakkar in the Swamp of Sorrows.  Release the creature there and destroy him, taking only a small part of his body back to Mehlar Dawnblade.  My guards will deliver the scourgestone fragments to Mehlar.",logDesc="Unlock the secrets of the Temple of Atal'Hakkar to release Atal'alarion and recover the Putrid Vine from his flesh.  Return to Mehlar at the Bulwark when you have done this.",rewards={{id=30696,qty=1}}} end
if not DB[10594] then DB[10594]={id=10594,zoneId=3522,name="Gauging the Resonant Frequency",level=67,minLevel=65,giver="Nickwinkle the Metro-Gnome",giverType="NPC",giverId=21755,ender="Nickwinkle the Metro-Gnome",enderType="NPC",enderId=21755,poiX=1915,poiY=5579,wowhead="https://www.wowhead.com/wotlk/quest=10594",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="Take these scanners to the Singing Ridge.  By dropping them in a pattern on the ground, you will create overlapping fields that will read the amplitude of the crystals.  Stand amidst them in such a way that you're in five oscillation fields and I'll have the information that I need!$B$BYour scanners will even work with those that others drop.$B$BOh, and it's likely that a rift will be formed!  I have no idea what, if anything, will come out of it, but be prepared for the worst.",logDesc="Place the Oscillating Frequency Scanners in such a way that when you stand amongst them, you are hit by 5 overlapping Oscillation fields.",choiceRewards={{id=31444,qty=1},{id=31443,qty=1},{id=31445,qty=1},{id=31442,qty=1}}} end
if not DB[10595] then DB[10595]={id=10595,zoneId=3520,name="Besieged!",level=69,minLevel=67,giver="Blood Guard Gulmok",giverType="NPC",giverId=21359,ender="Blood Guard Gulmok",enderType="NPC",enderId=21359,rewardNextId=10596,poiX=-3136,poiY=2550,wowhead="https://www.wowhead.com/wotlk/quest=10595",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="<Gulmok looks to the sky.>$B$BOur scouts are putting up a good fight, but the infernals keep coming!$B$BFrom their base of Legion Hold to the southwest, the demons bombard us with impunity! Even the elite Kor'kron guard cannot hold them off forever.$B$BI'm drafting every able-bodied $r to do their part in defense of Shadowmoon Village. This is no game, $c. The survival of the village is at stake. Do your duty to the Horde, and join the fray!",logDesc="Blood Guard Gulmok outside of Shadowmoon Village, wants you to kill 10 Infernal Attackers."} end
if not DB[10596] then DB[10596]={id=10596,zoneId=3520,name="To Legion Hold",level=69,minLevel=67,giver="Blood Guard Gulmok",giverType="NPC",giverId=21359,ender="Blood Guard Gulmok",enderType="NPC",enderId=21359,rewardNextId=10597,poiX=-3136,poiY=2550,wowhead="https://www.wowhead.com/wotlk/quest=10596",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The fortress of Legion Hold is your target. You'll have no reinforcements, so a frontal attack is out of the question.$B$BWhat little information we have shows that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I'll give you, you must sneak into Legion Hold and discover their plans.$B$BYour best hope is to intercept or overhear communication between their commanders. ",logDesc="Make your way to Legion Hold, locate the Legion Communication Device, and learn about the Legion's plans while in disguise. Return to Blood Guard Gulmok at Shadowmoon Village when you've completed your mission."} end
if not DB[10597] then DB[10597]={id=10597,zoneId=3520,name="Setting Up the Bomb",level=69,minLevel=67,giver="Blood Guard Gulmok",giverType="NPC",giverId=21359,ender="Blood Guard Gulmok",enderType="NPC",enderId=21359,rewardNextId=10598,poiX=-3136,poiY=2550,wowhead="https://www.wowhead.com/wotlk/quest=10597",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="We can't allow the Legion to trample us on their march to Black Temple.$B$BFind a way to destroy the infernals they intend to use against us. That's not a request, $N; it's an order.$B$BThe Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the basis for a kind of fel bomb. Search the other wreckage near the fel reaver for a section of armor plating. You should be able to make a bomb powerful enough to take out those infernals and give the hold a nice shake!",logDesc="Obtain a Fel Reaver Power Core and a Fel Reaver Armor Plate, then bring them to Blood Guard Gulmok at Shadowmoon Village."} end
if not DB[10598] then DB[10598]={id=10598,zoneId=3520,name="Blast the Infernals!",level=69,minLevel=67,giver="Blood Guard Gulmok",giverType="NPC",giverId=21359,ender="Blood Guard Gulmok",enderType="NPC",enderId=21359,rewardNextId=10599,poiX=-3136,poiY=2550,wowhead="https://www.wowhead.com/wotlk/quest=10598",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The device we've assembled won't win any beauty contests, but it should be capable of destroying the infernals amassed at Legion Hold. Judging from what the fel reaver power core's energy did to the Fetid Pool, it holds a respectable amount of explosive power.$B$BIf you set the device off in the middle of the green glyph at the hold, it should be in range to hit all of the infernals.",logDesc="Use the Fel Bomb while standing on the green glyph in Legion Hold to destroy the infernals, then report to Blood Guard Gulmok at Shadowmoon Village.",choiceRewards={{id=30986,qty=1},{id=30947,qty=1},{id=30946,qty=1},{id=30929,qty=1}}} end
if not DB[10599] then DB[10599]={id=10599,zoneId=3520,name="The Deathforge",level=69,minLevel=67,giver="Blood Guard Gulmok",giverType="NPC",giverId=21359,ender="Scout Zagran",enderType="NPC",enderId=21475,rewardNextId=10600,poiX=-3136,poiY=2550,wowhead="https://www.wowhead.com/wotlk/quest=10599",image="assets/images/quests/placeholder.png",xpDiff=1,desc="While you were taking care of the infernals at Legion Hold, I've been going over your reports. We've got no reason to believe the Legion lied about what's going on at the Deathforge. They're really cranking out infernals down there, so I've dispatched a scouting party to keep watch over it.$B$BIf we don't shut down the Deathforge, they'll rebuild the infernal stockpile that you destroyed at Legion Hold.$B$BReport to Scout Zagran atop Slag Watch, to the southeast of here and overlooking the Deathforge.",logDesc="Report to Scout Zagran at Slag Watch."} end
if not DB[10600] then DB[10600]={id=10600,zoneId=3520,name="Minions of the Shadow Council",level=69,minLevel=67,giver="Scout Zagran",giverType="NPC",giverId=21475,ender="Scout Zagran",enderType="NPC",enderId=21475,poiX=-3348,poiY=2103,wowhead="https://www.wowhead.com/wotlk/quest=10600",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="<Zagran listens to you recount the events at Legion Hold, nodding.>$B$BThat fills in the gaps we've seen. We've caught glimpses of them launching infernals in the direction of the hold, but haven't been able to find much more than that.$B$BThe Shadow Council has the forge pretty much locked down. Looks like you're going to need to fight your way in. Start eliminating the Shadow Council guarding the entrance to the Deathforge!",logDesc="Scout Zagran at Slag Watch wants you to kill 10 Deathforge Guardians and 5 Deathforge Summoners."} end
if not DB[10601] then DB[10601]={id=10601,zoneId=3520,name="The Fate of Kagrosh",level=69,minLevel=67,giver="Scout Zagran",giverType="NPC",giverId=21475,ender="Scout Zagran",enderType="NPC",enderId=21475,poiX=-3348,poiY=2103,wowhead="https://www.wowhead.com/wotlk/quest=10601",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The scouting party originally had three members. Unfortunately, Kagrosh decided he wanted to be a hero.$B$BHe descended into the Deathforge and we haven't heard from him since.$B$BIn all likelihood, the fool's gone and gotten himself killed. The Shadow Council members aren't idiots and Kagrosh wasn't exactly strong in the subtlety department, if you know what I mean. Keep an eye out for him in the Deathforge and recover any information or items he might have collected.",logDesc="Scout Zagran at Slag Watch wants you to search the Deathforge for Kagrosh and recover Kagrosh's Pack."} end
if not DB[10602] then DB[10602]={id=10602,zoneId=3520,name="The Summoning Chamber",level=69,minLevel=67,giver="Scout Zagran",giverType="NPC",giverId=21475,ender="Scout Zagran",enderType="NPC",enderId=21475,poiX=-3348,poiY=2103,wowhead="https://www.wowhead.com/wotlk/quest=10602",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="In order to churn out infernals as quickly as the Deathforge seems to, they must have an area dedicated to summoning the elementals that form the core of the infernals.$B$BThe summoning chamber is likely to be found below ground, near a pool of fouled water or lava. Locate the summoning chamber within the Deathforge and find a way to end their summoning ritual. The mo'arg involved in making the infernals may carry a tool that will help disrupt the summoner's magics.",logDesc="Obtain an Elemental Displacer from a Deathforge Smith or Deathforge Tinkerer and use it to disrupt the ritual in the summoning chamber. Report to Scout Zagran at Slag Watch when you've completed your task."} end
if not DB[10603] then DB[10603]={id=10603,zoneId=3520,name="Bring Down the Warbringer!",level=69,minLevel=67,giver="Scout Zagran",giverType="NPC",giverId=21475,ender="Blood Guard Gulmok",enderType="NPC",enderId=21359,rewardNextId=10604,poiX=-3348,poiY=2103,wowhead="https://www.wowhead.com/wotlk/quest=10603",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="We've made a lot of progress against the Shadow Council here at the Deathforge, but now it's time to finish the job.$B$BI found a key among the items in Kagrosh's pack. At least he accomplished something before they got to him.$B$BThe key should help you to track down this Warbringer Razuun you observed at Legion Hold.$B$BAfter you've hunted down and dealt with Warbringer Razuun, report directly to Blood Guard Gulmok. We must not keep him waiting.",logDesc="Defeat Warbringer Razuun, recover Razuun's Orders, and report to Blood Guard Gulmok at Shadowmoon Village."} end
if not DB[10604] then DB[10604]={id=10604,zoneId=3520,name="Gaining Access",level=69,minLevel=67,giver="Blood Guard Gulmok",giverType="NPC",giverId=21359,ender="Blood Guard Gulmok",enderType="NPC",enderId=21359,rewardNextId=10767,poiX=-3136,poiY=2550,wowhead="https://www.wowhead.com/wotlk/quest=10604",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="According to Razuun's orders, the massive infernal staging area is called Invasion Point: Cataclysm and it's located in the mountains behind our village! The only way to reach it is by using a teleporter at Legion Hold.$B$BCertain Legion minions carry a device allowing them to use the teleporter. You must capture one of these devices to win access to the teleporter. Slaughter all of the demons if you must, but you can't afford to return empty-handed. Do not delay; the enemy is perilously close.",logDesc="Bring a Legion Teleporter Control to Blood Guard Gulmok at Shadowmoon Village. The Mo'arg Weaponsmiths at Legion Hold are known to carry the devices."} end
if not DB[10605] then DB[10605]={id=10605,zoneId=-61,name="Carendin Summons",level=-1,minLevel=20,giver="Alamma",giverType="NPC",giverId=16646,ender="Carendin Halgar",enderType="NPC",enderId=5675,rewardNextId=1472,poiX=9775,poiY=-7286,wowhead="https://www.wowhead.com/wotlk/quest=10605",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You have a hungry look about you, $n.  Perhaps it is time you advanced your training.$b$bTravel to Undercity and speak with Carendin Halgar, the old bag of bones knows a trick or two you might find useful.",logDesc="Speak with Carendin Halgar in Undercity."} end
if not DB[10606] then DB[10606]={id=10606,zoneId=3520,name="The Art of Fel Reaver Maintenance",level=69,minLevel=67,giver="Plexi",giverType="NPC",giverId=21790,ender="Plexi",enderType="NPC",enderId=21790,rewardNextId=10612,poiX=-2764,poiY=1981,wowhead="https://www.wowhead.com/wotlk/quest=10606",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The best way to destroy the rest of the Legion's supplies is to use their own weapons against them. I've been working on a rig that will let you take control of one of those Fel Reaver Sentinels below.$B$BThere are a couple things I need to work out, yet. For that, I'll need the manual that Doctor Gutrick keeps locked in a chest at the bottom of the ramp. He probably won't give up the key without a fight, so you'll need to capture it. Bring the fel reaver manual back to me and I'll do the rest!",logDesc="Kill Doctor Gutrick and obtain the Doctor's Key. Use the key to open the Doctor's Strongbox to retrieve The Art of Fel Reaver Maintenance and deliver the book to Plexi at Invasion Point: Cataclysm."} end
if not DB[10607] then DB[10607]={id=10607,zoneId=3522,name="Whispers of the Raven God",level=68,minLevel=66,giver="Timeon",giverType="NPC",giverId=21782,ender="Timeon",enderType="NPC",enderId=21782,poiX=2994,poiY=5474,wowhead="https://www.wowhead.com/wotlk/quest=10607",image="assets/images/quests/placeholder.png",xpDiff=5,desc="At Grishnath, totems left by the Oracles of the Raven enable the arakkoa to hear the Word of the Raven. Unfortunately, the language of the arakkoa is indecipherable to us.$b$bUsing the Harbinger's pendant, we can understand it. You will be able to take the souls of the arakkoa to understand their language. While you are suffused with the arakkoa's spirit, you can visit the totems and understand their message.$b$bDiscover this for us, $n.",logDesc="Kill Grishna arakkoa to gain Understanding Ravenspeech for 2 minutes. While under the effects of the spell, you can find and receive the prophecy from the four shrines.",choiceRewards={{id=31531,qty=1},{id=31532,qty=1},{id=31533,qty=1},{id=31534,qty=1}}} end
if not DB[10608] then DB[10608]={id=10608,zoneId=3522,name="Crystal Clear",level=67,minLevel=65,giver="Nickwinkle the Metro-Gnome",giverType="NPC",giverId=21755,ender="Nickwinkle the Metro-Gnome",enderType="NPC",enderId=21755,rewardNextId=10594,poiX=1915,poiY=5579,wowhead="https://www.wowhead.com/wotlk/quest=10608",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="The damned rock flayers are keeping me from my research down in the Singing Ridge!  By digging at the crystals there, with every scratch they are ruining my chances of studying the harmonics of the singing crystals.$B$BYou look like someone who can help me deal with this problem.  Head south and clear those crystal flayers out.",logDesc="Slay 10 Crystal Flayers."} end
if not DB[10609] then DB[10609]={id=10609,zoneId=3522,name="What Came First, the Drake or the Egg?",level=67,minLevel=65,giver="Fizit \"Doc\" Clocktock",giverType="NPC",giverId=21110,ender="Fizit \"Doc\" Clocktock",enderType="NPC",enderId=21110,poiX=1945,poiY=5538,wowhead="https://www.wowhead.com/wotlk/quest=10609",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="I'm researching the applications of drake essences to my work as a physician.  I think they could be a panacea for a host of maladies!$B$BI need someone to go south to the Singing Ridge and get me some.$B$BWilling to take my temporal phase modulator and use it on the nether whelps that hatch from the nether drake eggs?  Retrieve the essences from whatever they turn into.$B$BWhich, I might add, I'm not certain of what that will be as we're using some pretty dicey, time  and space modifying tech here.",logDesc="Collect 3 Proto-Nether Drake Essences, 3 Adolescent Drake Essences and 3 Mature Drake Essences.",rewards={{id=31437,qty=5}},choiceRewards={{id=31438,qty=1},{id=31439,qty=1},{id=31440,qty=1},{id=31441,qty=1}}} end
if not DB[10610] then DB[10610]={id=10610,zoneId=0,name="Prospecting Basics",level=5,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=10610",image="assets/images/quests/placeholder.png"} end
if not DB[10611] then DB[10611]={id=10611,zoneId=3520,name="The Art of Fel Reaver Maintenance",level=69,minLevel=67,giver="Nakansi",giverType="NPC",giverId=21789,ender="Nakansi",enderType="NPC",enderId=21789,rewardNextId=10613,poiX=-2726,poiY=2713,wowhead="https://www.wowhead.com/wotlk/quest=10611",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The best way to destroy the rest of the Legion's supplies is to use their own weapons against them. I've been working on a rig that will let you take control of one of those Fel Reaver Sentinels below.$B$BThere are a couple things I need to work out, yet. For that, I'll need the manual that Doctor Maleficus keeps locked in a chest near the bottom of the ramp. He probably won't give up the key without a fight, so you'll need to capture it. Bring the fel reaver manual back to me and I'll do the rest.",logDesc="Kill Doctor Maleficus and obtain the Doctor's Key. Use the key to open the Doctor's Strongbox to retrieve The Art of Fel Reaver Maintenance and deliver the book to Nakansi at Invasion Point Cataclysm."} end
if not DB[10612] then DB[10612]={id=10612,zoneId=3520,name="The Fel and the Furious",level=69,minLevel=67,giver="Plexi",giverType="NPC",giverId=21790,ender="Plexi",enderType="NPC",enderId=21790,rewardNextId=10744,poiX=-2764,poiY=1981,wowhead="https://www.wowhead.com/wotlk/quest=10612",image="assets/images/quests/placeholder.png",xpDiff=6,money=41000,desc="<Plexi leafs through the manual.>$B$BWell, this has everything we need, but there's just one problem. Fel Reavers aren't really built to respond to remote control.$B$BWe can modify one for you to use for a short time, but you'll have to work fast, or there's no telling what might happen! I wouldn't be surprised if your little stunt with the fel reaver catches the attention of the Legion's lackeys, either. Keep an eye out, and whatever you do, don't forget to destroy as much as you can!",logDesc="Use a Fel Reaver Control Console to take control of a Fel Reaver Sentinel. Destroy 60 Deathforged Infernals before your fel reaver fails. When your mission is complete, report to Plexi at Invasion Point: Cataclysm."} end
if not DB[10613] then DB[10613]={id=10613,zoneId=3520,name="The Fel and the Furious",level=69,minLevel=67,giver="Nakansi",giverType="NPC",giverId=21789,ender="Nakansi",enderType="NPC",enderId=21789,rewardNextId=10745,poiX=-2726,poiY=2713,wowhead="https://www.wowhead.com/wotlk/quest=10613",image="assets/images/quests/placeholder.png",xpDiff=6,money=41000,desc="<Nakansi leafs through the manual.>$B$BAll the information is here, but be warned. These things weren't built to be controlled remotely.$B$BWe can modify one for you to use for a short time, but you'll have to work fast, or there's no telling what might happen! I wouldn't be surprised if your little stunt with the fel reaver catches the attention of the Legion scum, either. Try to keep yourself safe, but remember, the mission and the safety of Shadowmoon Village come first!",logDesc="Use a Fel Reaver Control Console to take control of a Fel Reaver Sentinel. Destroy 60 Deathforged Infernals before your fel reaver fails. When your mission is complete, report to Nakansi at Invasion Point: Cataclysm."} end
if not DB[10614] then DB[10614]={id=10614,zoneId=3522,name="Whispers on the Wind",level=66,minLevel=65,giver="3",giverType="NPC",giverId=21984,ender="Leoroxx",enderType="NPC",enderId=22004,rewardNextId=10709,poiX=2298,poiY=6034,wowhead="https://www.wowhead.com/wotlk/quest=10614",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I have chased rumors of the Mok'Nathal across Outland with nothing to show for it. Finally, we may have found their home.$b$bBut now that the moment is here, I am filled with unease. Unease that has kept me awake deep into the nights during my search. Will they accept me?$b$bI... know their leader's name: Leoroxx. Seek him out. You must be my eyes in this.",logDesc="Speak with Leoroxx at the Mok'Nathal Village in the Blade's Edge Mountains."} end
if not DB[10615] then DB[10615]={id=10615,zoneId=3522,name="Ruuan Weald",level=64,minLevel=61,giver="Dertrok",giverType="NPC",giverId=21496,ender="Timeon",enderType="NPC",enderId=21782,poiX=2162,poiY=4770,wowhead="https://www.wowhead.com/wotlk/quest=10615",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The information you have helped me reveal about the nature of the arakkoa here will be of great interest to another.$b$bWe were visited by members of the Cenarion Expedition, who have also become concerned with the arakkoa's intentions here in the Blade's Edge Mountains.$b$bYou should seek him out. His name is Timeon, and you will find him at Evergrove in Ruuan Weald. Follow the road west from here, then north when it forks in Razor Ridge. Finally, follow the road west when it splits in the Bladed Gulch.",logDesc="Speak with Timeon at Evergrove, which is in the Ruuan Weald in the Blade's Edge Mountains."} end
if not DB[10616] then DB[10616]={id=10616,zoneId=0,name="<nyi>Breadcrumb",level=66,minLevel=61,wowhead="https://www.wowhead.com/wotlk/quest=10616",image="assets/images/quests/placeholder.png"} end
if not DB[10617] then DB[10617]={id=10617,zoneId=3522,name="Silkwing Cocoons",level=66,minLevel=61,giver="Taerek",giverType="NPC",giverId=21895,ender="Taerek",enderType="NPC",enderId=21895,poiX=2187,poiY=4730,wowhead="https://www.wowhead.com/wotlk/quest=10617",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="The silk from the cocoons of the silkwings are used for all manner of things in the village. We can never get enough, and we never have enough.$b$bIt is difficult to harvest the cocoons from the larva once they begin the process of metamorphosis.$b$bOur warriors are occupied with the assault on our village. If you could gather these for us, that would be helpful.",logDesc="Collect 8 Silkwing Cocoons from Silkwing Larva.$b$bKill the Larva quickly or they will turn into Silkwings, ruining their cocoons."} end
if not DB[10618] then DB[10618]={id=10618,zoneId=3522,name="The Softest Wings",level=65,minLevel=61,giver="Silmara",giverType="NPC",giverId=21896,ender="Silmara",enderType="NPC",enderId=21896,poiX=2183,poiY=4732,wowhead="https://www.wowhead.com/wotlk/quest=10618",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="Hunting silkwing larva is a difficult challenge for our young warriors, but luckily, even if they fail to harvest the cocoon from the larva, we can still use the wings of hatched silkwings.$b$bIn fact, we use the wings for much more than the cocoons, and we can never have too many.$b$bIf you'll be out there, it would be a great help if you could bring me some.",logDesc="Collect 12 Iridescent Wings."} end
if not DB[10619] then DB[10619]={id=10619,zoneId=3520,name="The Ashtongue Tribe",level=70,minLevel=68,giver="Vindicator Aluumen",giverType="NPC",giverId=21822,ender="Vindicator Aluumen",enderType="NPC",enderId=21822,rewardNextId=10816,poiX=-3017,poiY=861,wowhead="https://www.wowhead.com/wotlk/quest=10619",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Ashtongue tribe is feared among all Broken.  It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself.  They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, southwest of here.  Go there and put a dent in their numbers before they get a chance to mount an attack on us.",logDesc="Vindicator Aluumen wants you to go to the Ruins of Baa'ri and slay 3 Ashtongue Handlers, 4 Ashtongue Warriors and 6 Ashtongue Shaman.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10620] then DB[10620]={id=10620,zoneId=3522,name="Ridgespine Menace",level=67,minLevel=65,giver="Dizzy Dina",giverType="NPC",giverId=21824,ender="Dizzy Dina",enderType="NPC",enderId=21824,poiX=1922,poiY=5569,wowhead="https://www.wowhead.com/wotlk/quest=10620",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="We hired on to help Toshley when he decided to move to Outland, and we've been on the move ever since.$B$BNow it looks like we've finally put down some roots.  All of the crazy scientists have their projects going, and us Roughriders are here to protect them.$B$BWhat we need right now is for you to go north into Razor Ridge, or east to the Scalewing Shelf, and keep them clear by killing the stalkers.  They're stealthy spiders that live amongst the rock outcroppings, and jump unsuspecting passersby.",logDesc="Slay 10 Ridgespine Stalkers.",choiceRewards={{id=31449,qty=5},{id=31450,qty=5}}} end
if not DB[10621] then DB[10621]={id=10621,zoneId=3520,name="Illidari-Bane Shard",level=69,minLevel=67,ender="Ordinn Thunderfist",enderType="NPC",enderId=19370,rewardNextId=10626,wowhead="https://www.wowhead.com/wotlk/quest=10621",image="assets/images/quests/placeholder.png",xpDiff=4,money=41000,desc="The shard appears to be a piece of a larger weapon. Sharp-looking runes etched into the metal glow with a menacing light.$B$BThe weapon's intended purpose isn't clear to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths at Wildhammer Stronghold might be able to tell you more about it.",logDesc="Bring the Illidari-Bane Shard to Ordinn Thunderfist at Wildhammer Stronghold."} end
if not DB[10622] then DB[10622]={id=10622,zoneId=3520,name="Proof of Allegiance",level=70,minLevel=68,giver="Sanoru",giverType="NPC",giverId=21826,ender="Sanoru",enderType="NPC",enderId=21826,rewardNextId=10628,poiX=-3766,poiY=1072,wowhead="https://www.wowhead.com/wotlk/quest=10622",image="assets/images/quests/placeholder.png",desc="Akama has been tracking your progress quite closely, $N.$B$BThe Ashtongue you've slain at the Ruins of Baa'ri are amongst the most evil Broken known among us... carefully hand-picked by Akama himself to maintain the facade we need to present to Illidan.  The Deathsworn, however, know of Akama's true intentions.$B$BFirst things first.  We need to know that you are not with Illidan.  A Satyr known as Zandras watches over us from above the prison walls on his behalf.  Slay him as proof of your allegiance.",logDesc="Slay Zandras at the Warden's Cage in Shadowmoon Valley and return to Sanoru."} end
if not DB[10623] then DB[10623]={id=10623,zoneId=3520,name="Illidari-Bane Shard",level=69,minLevel=67,ender="Grokom Deatheye",enderType="NPC",enderId=19333,rewardNextId=10627,wowhead="https://www.wowhead.com/wotlk/quest=10623",image="assets/images/quests/placeholder.png",xpDiff=4,money=41000,desc="The shard appears to be a piece of a larger weapon. Sharp-looking runes etched into the metal glow with a menacing light.$B$BThe weapon's intended purpose isn't clear to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths at Shadowmoon Village might be able to tell you more about it.",logDesc="Bring the Illidari-Bane Shard to Grokom Deatheye at Shadowmoon Village."} end
if not DB[10624] then DB[10624]={id=10624,zoneId=3520,name="A Haunted History",level=69,minLevel=67,giver="Chief Apothecary Hildagard",giverType="NPC",giverId=21772,ender="Chief Apothecary Hildagard",enderType="NPC",enderId=21772,rewardNextId=10625,poiX=-2965,poiY=2577,wowhead="https://www.wowhead.com/wotlk/quest=10624",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Have you felt the cold chill? Perhaps what you thought was a hand on your shoulder? That was not your mind playing tricks on you, $r. The land is haunted. Ghosts litter the landscape, stuck here for all eternity.$B$BWould you like to see them? Are you sure about that? These types of things tend to change a person - and not for the better.$B$BVery well, I will need you to collect for me the ever-burning ash that is found near any of the fel lava pools of western Shadowmoon. Anywhere near green lava...$B",logDesc="Chief Apothecary Hildagard at Shadowmoon Village in Shadowmoon Valley wants you to bring her 15 Ever-burning Ash samples."} end
if not DB[10625] then DB[10625]={id=10625,zoneId=3520,name="Spectrecles",level=69,minLevel=67,giver="Chief Apothecary Hildagard",giverType="NPC",giverId=21772,ender="Chief Apothecary Hildagard",enderType="NPC",enderId=21772,rewardNextId=10633,poiX=-2965,poiY=2577,wowhead="https://www.wowhead.com/wotlk/quest=10625",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="I call them \"Spectrecles.\" Clever, no? When you equip these goggles, you will be able to see the spirits of Shadowmoon Valley.$B$BBefore I let you have them, though, you must promise me that you will help us clear out the ghosts at the village.$B$BTake the goggles and destroy any and all spirits that you see wandering about Shadowmoon Village. Hopefully, destroying these spirits will force any that remain to move elsewhere.",logDesc="Chief Apothecary Hildagard at Shadowmoon Village in Shadowmoon Valley wants you to slay 12 Shadowmoon Zealots."} end
if not DB[10626] then DB[10626]={id=10626,zoneId=3520,name="Capture the Weapons",level=69,minLevel=67,giver="Ordinn Thunderfist",giverType="NPC",giverId=19370,ender="Ordinn Thunderfist",enderType="NPC",enderId=19370,poiX=-3961,poiY=2200,wowhead="https://www.wowhead.com/wotlk/quest=10626",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="With a larger supply of this material, we might be able to forge a weapon for you to use.$B$BThe two pit lords at Legion Hold, Makazradon and Morgroron, have already been equipped with these anti-demon weapons. We have no way of knowing how many more the Legion intends to produce, but if we can capture these prototypes, there should be enough for our project.$B$B<Ordinn grins.>$B$BThere's a certain amount of satisfaction in using the Legion's own 'secret weapons' against them, don't you think?",logDesc="Ordinn Thunderfist at Wildhammer Stronghold wants you to bring him Mazakradon's Glaive and Morgroron's Glaive.",choiceRewards={{id=30926,qty=1},{id=30938,qty=1},{id=30950,qty=1},{id=30966,qty=1}}} end
if not DB[10627] then DB[10627]={id=10627,zoneId=3520,name="Capture the Weapons",level=69,minLevel=67,giver="Grokom Deatheye",giverType="NPC",giverId=19333,ender="Grokom Deatheye",enderType="NPC",enderId=19333,poiX=-3093,poiY=2586,wowhead="https://www.wowhead.com/wotlk/quest=10627",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="With a larger supply of this material, I can forge a weapon suitable for you.$B$BThe two pit lords at Legion Hold, Makazradon and Morgroron, have already been equipped with these anti-demon weapons. Capturing those two weapons should provide us with enough material to make your weapon, and then some.$B$BI can't wait to bring the battle to the enemy using these weapons. That'll teach the Legion to trifle with anti-demon magics.",logDesc="Grokom Deatheye at Shadowmoon Village wants you to bring him Mazakradon's Glaive and Morgroron's Glaive.",choiceRewards={{id=30926,qty=1},{id=30938,qty=1},{id=30950,qty=1},{id=30966,qty=1}}} end
if not DB[10628] then DB[10628]={id=10628,zoneId=3520,name="Akama",level=70,minLevel=68,giver="Sanoru",giverType="NPC",giverId=21826,ender="Akama",enderType="NPC",enderId=21700,poiX=-3766,poiY=1072,wowhead="https://www.wowhead.com/wotlk/quest=10628",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You've proven what side you're on.  I will reveal to you our leader's hideout.$B$BFollow the halls beyond; there will be an underground passage hidden by stagnant water on your right.$B$BI must warn you, $N.  You are not to speak to anyone of what you see there.",logDesc="Speak to Akama inside the hidden chamber in the Warden's Cage."} end
if not DB[10629] then DB[10629]={id=10629,zoneId=3483,name="Shizz Work",level=61,minLevel=58,giver="Foreman Razelcraz",giverType="NPC",giverId=16915,ender="Foreman Razelcraz",enderType="NPC",enderId=16915,rewardNextId=10630,poiX=430,poiY=2887,wowhead="https://www.wowhead.com/wotlk/quest=10629",image="assets/images/quests/placeholder.png",xpDiff=5,money=40000,desc="I finally got my shredder working but I seem to have lost the keys.  I keep a pack of felhounds to protect my camp.  They don't do a very good job and they like to bite me a lot.  They also like shiny things.  I think this one felhound I have may have eaten my shredder keys.  I'll pay you if you'll take my felhound on a walk.  Kill some helboars and let him eat.  He'll do his business.  When he's done, see if you can't find the keys in his \"leavings.\"",logDesc="Use the Felhound Whistle to summon a Fel Guard Hound.  Take the Fel Guard Hound for a walk and kill some Deranged Helboars.  Search for the Shredder Keys in the Fel Guard Hound's \"leavings.\"  Return the Shredder Keys to Foreman Razelcraz by the mine northwest of Thrallmar.",rewards={{id=18588,qty=5}}} end
if not DB[10630] then DB[10630]={id=10630,zoneId=3483,name="Beneath Thrallmar",level=61,minLevel=58,giver="Foreman Razelcraz",giverType="NPC",giverId=16915,ender="Foreman Razelcraz",enderType="NPC",enderId=16915,poiX=430,poiY=2887,wowhead="https://www.wowhead.com/wotlk/quest=10630",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="I'm almost back in business.  Problem is all these gan'arg are in my mine.  I can't send my peons in and even once I fix this shredder I wouldn't want to risk it in combat. Deep down in the mine the gan'arg have a leader.  If you kill him maybe the gan'arg will leave.  Then I could make some money and buy my way out of here. ",logDesc="Kill Urga'zz and return to Foreman Razelcraz by the mine northwest of Thrallmar.",choiceRewards={{id=30856,qty=1},{id=30855,qty=1},{id=30857,qty=1}}} end
if not DB[10631] then DB[10631]={id=10631,zoneId=3483,name="Back In Business",level=61,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10631",image="assets/images/quests/placeholder.png",desc="Take my shredder.  Go into the mine and get some ore.",logDesc="Get some ore."} end
if not DB[10632] then DB[10632]={id=10632,zoneId=3522,name="Cutting Your Teeth",level=67,minLevel=65,giver="Razak Ironsides",giverType="NPC",giverId=21118,ender="Razak Ironsides",enderType="NPC",enderId=21118,poiX=1898,poiY=5589,wowhead="https://www.wowhead.com/wotlk/quest=10632",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="It's nice that you've been helping out Toshley and his scientists.  I, however, do not have the luxury of indulging in my 'personal' interests.$B$BIf you want to make a difference around here, you'll do what I ask of you, and right now, I need weapons.$B$BOur guns are effective at range, but when the bugs get in close, we need to have powerful melee weapons as a backup.$B$BThe teeth of the daggermaw lashtails in the northern part of the Razor Ridge make for great vibro-weapon blades.  Scare me up some.",logDesc="Collect 5 Extra Sharp Daggermaw Teeth.",choiceRewards={{id=31446,qty=1},{id=31447,qty=1},{id=31448,qty=1}}} end
if not DB[10633] then DB[10633]={id=10633,zoneId=3520,name="Teron Gorefiend - Lore and Legend",level=70,minLevel=67,giver="Chief Apothecary Hildagard",giverType="NPC",giverId=21772,ender="Ancient Shadowmoon Spirit",enderType="NPC",enderId=21797,poiX=-2965,poiY=2577,wowhead="https://www.wowhead.com/wotlk/quest=10633",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Stories abound about the life of Teron Gorefiend, but most are just that - stories. We do not know what happened to Gorefiend after he returned to Draenor.$B$BThe only thing we are certain of is that he has already died once.$B$BI have heard the scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far to the southeast, across the Netherwing Fields and through Netherwing Pass. Take the Spectrecles and track this orc down. He will surely have more information on Gorefiend.",logDesc="Chief Apothecary Hildagard at Shadowmoon Village in Shadowmoon Valley wants you to find the Ancient Shadowmoon Spirit.$B$BIf you lose your Spectrecles, Chief Apothecary Hildagard can make you a new pair."} end
if not DB[10634] then DB[10634]={id=10634,zoneId=3520,name="Divination: Gorefiend's Armor",level=70,minLevel=67,giver="Ancient Shadowmoon Spirit",giverType="NPC",giverId=21797,ender="Ancient Shadowmoon Spirit",enderType="NPC",enderId=21797,poiX=-4544,poiY=1023,wowhead="https://www.wowhead.com/wotlk/quest=10634",image="assets/images/quests/placeholder.png",xpDiff=7,desc="In life, Gorefiend was a monster, but in death, Gorefiend was an unmitigated terror.$B$BTo the southeast you will find Netherwing Ledge. What was once part of the mainland of Shadowmoon is now a floating island in the sky.$B$BVhel'kur, spawn of Deathwing, once called it his home, but now knows it as his grave. He flies an endless circle above the island, seething at his defeat to Gorefiend.$B$BIf you are to recover the Gorefiend's armor, it is Vhel'kur that you must defeat.",logDesc="The Ancient Shadowmoon Spirit at the Altar of Shadows in southeast Shadowmoon Valley wants you to recover Gorefiend's Armor."} end
if not DB[10635] then DB[10635]={id=10635,zoneId=3520,name="Divination: Gorefiend's Cloak",level=70,minLevel=67,giver="Ancient Shadowmoon Spirit",giverType="NPC",giverId=21797,ender="Ancient Shadowmoon Spirit",enderType="NPC",enderId=21797,poiX=-4544,poiY=1023,wowhead="https://www.wowhead.com/wotlk/quest=10635",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Many a cruel act he committed but none so cold as the slaughter of the clerics of Karabor.$B$BAfter Gul'dan's Horde defeated the draenei of Karabor, the surviving clerics of Karabor were marched out, told that they were to be taken to Hellfire Citadel as prisoners of war.$B$BGorefiend, not yet a death knight, murdered each and every last one of them in cold blood. They now roam in front of the Black Temple with vengeance in their hearts.$B$BIt is the clerics of Karabor that hold the cloak of Gorefiend.",logDesc="The Ancient Shadowmoon Spirit at the Altar of Shadows in southeast Shadowmoon Valley wants you to recover Gorefiend's Cloak."} end
if not DB[10636] then DB[10636]={id=10636,zoneId=3520,name="Divination: Gorefiend's Truncheon",level=70,minLevel=67,giver="Ancient Shadowmoon Spirit",giverType="NPC",giverId=21797,ender="Ancient Shadowmoon Spirit",enderType="NPC",enderId=21797,poiX=-4544,poiY=1023,wowhead="https://www.wowhead.com/wotlk/quest=10636",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One by one they knelt before him, offering their lives as a show of allegiance. Gorefiend hoisted his sickle and cut clean their heads. Shortly after this slaughter, Gorefiend took his own life.$B$BBut this was no act of contrition! No, Gorefiend sought immortality! From the corpses of the fallen death knights rose the Ghostriders of Karabor.$B$BThey now ride the roads encircling the Hand of Guldan, awaiting the day that their master returns. It is they who hold the truncheon of Gorefiend. Retrieve it...",logDesc="The Ancient Shadowmoon Spirit at the Altar of Shadows in southeast Shadowmoon Valley wants you to recover Gorefiend's Truncheon."} end
if not DB[10637] then DB[10637]={id=10637,zoneId=3520,name="A Necessary Distraction",level=70,minLevel=68,giver="Exarch Onaala",giverType="NPC",giverId=21860,ender="Exarch Onaala",enderType="NPC",enderId=21860,rewardNextId=10640,poiX=-3020,poiY=859,wowhead="https://www.wowhead.com/wotlk/quest=10637",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The weapons are authentic, as we feared.  Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it.$B$BDo not be fooled by their name, $N, their power will be used against us as often as against any demon.$B$BTheir warlocks summon and subdue demons to be used as part of the initiates' training.  A pit lord named Azaloth has proven too strong to be used in training and is kept banished.  Find a way to let him loose on his captors.  That should buy us the time we need.",logDesc="Exarch Onaala wants you to return to the Ruins of Karabor and find a way to unleash Azaloth on his captors.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10638] then DB[10638]={id=10638,zoneId=-262,name="NOT A QUEST",level=10,minLevel=10,rewardNextId=10379,wowhead="https://www.wowhead.com/wotlk/quest=10638",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Seek your trainer in Silvermoon City.",logDesc="Seek <NAME> in the <DISTRICT> of Silvermoon City."} end
if not DB[10639] then DB[10639]={id=10639,zoneId=3520,name="Teron Gorefiend, I am...",level=70,minLevel=67,giver="Ancient Shadowmoon Spirit",giverType="NPC",giverId=21797,ender="Chief Apothecary Hildagard",enderType="NPC",enderId=21772,poiX=-4544,poiY=1023,wowhead="https://www.wowhead.com/wotlk/quest=10639",image="assets/images/quests/placeholder.png",xpDiff=7,desc="With Gorefiend's items restored, there is but one last piece to this puzzle: A host.$B$B<The ancient shadowmoon spirit's lips curl up  to form a wicked grin.>$B$BSurely you did not believe the fairy tale that I told you. The Altar of Shadows is my prison. Without your help, I would have been stuck here for all eternity. Now, I will take over your body and you will destroy my captors and break these bonds. Refuse and we will both be stuck here forever.$B$BTeron Gorefiend will be free!",logDesc="The Ancient Shadowmoon Spirit has used you as a pawn! Now that you have collected the items he required, he has revealed himself to be Teron Gorefiend. To break free of his possession, you must do his bidding and slay Karsius the Ancient Watcher.$B$BIf you succeed, return to Chief Apothecary Hildagard at Shadowmoon Village.",choiceRewards={{id=31104,qty=1},{id=31110,qty=1},{id=31109,qty=1},{id=31107,qty=1},{id=31106,qty=1},{id=31105,qty=1}}} end
if not DB[10640] then DB[10640]={id=10640,zoneId=3518,name="Altruis",level=70,minLevel=68,giver="Exarch Onaala",giverType="NPC",giverId=21860,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,poiX=-3020,poiY=859,wowhead="https://www.wowhead.com/wotlk/quest=10640",image="assets/images/quests/placeholder.png",xpDiff=3,desc="It is rare in this day and age to hear of those who follow the path of the demon hunter.  It is rarer still to find someone who does and has no allegiance to Illidan.$B$BThere are rumors of one such individual here in Outland.  One name is said to be feared in the Legion fields of Nagrand more than any army of Aldor vindicators.  That name is Altruis.$B$BGo to western Nagrand and find him.  He might be willing to shed some light on these new demon hunter training grounds.",logDesc="Travel to western Nagrand and find Altruis the Sufferer.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10641] then DB[10641]={id=10641,zoneId=3518,name="Against the Legion",level=70,minLevel=68,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=10641",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Burning Legion has proven its capacity to corrupt mortal souls time and again.  If I'm to entrust you with the knowledge you seek, I must have proof of your allegiance.$B$BA demoness known as Sathal has eluded me for a long time as she's gifted with an incorporeal form.$B$BShe watches over the wrath priestesses as they do her bidding at Forge Base: Gehenna.  Slay one of her minions and spill her blood on the ground.  This affront should cause Sathal to materialize temporarily.  Slay her while you can.",logDesc="Altruis the Sufferer wants you to obtain Freshly Drawn Blood from a Wrath Priestess at Forge Base: Gehenna in Netherstorm.  Spill it on the ground and slay the Avatar of Sathal.  Return to Altruis when you've completed this task."} end
if not DB[10642] then DB[10642]={id=10642,zoneId=3520,name="A Ghost in the Machine",level=69,minLevel=67,giver="Zorus the Judicator",giverType="NPC",giverId=21774,ender="Zorus the Judicator",enderType="NPC",enderId=21774,rewardNextId=10643,poiX=-3971,poiY=2191,wowhead="https://www.wowhead.com/wotlk/quest=10642",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="I fear that these dwarves do not understand what they have built upon. This area was once the ancestral grounds for the Shadowmoon orcs. I speak of spirits, $r.$B$BFor nearly twenty years they have laid dormant beneath the Wildhammer Stronghold, but recently, something has riled them up.$B$BVenture beyond the gates of Wildhammer and seek out the pools and rivers of fel lava found across this land. Near the lava will be ever-burning ash. Bring me this ash so that I may craft something that will help us.$B",logDesc="Zorus the Judicator at Wildhammer Stronghold in Shadowmoon Valley wants you to bring him 15 Ever-burning Ash samples."} end
if not DB[10643] then DB[10643]={id=10643,zoneId=3520,name="Harbingers of Shadowmoon",level=69,minLevel=67,giver="Zorus the Judicator",giverType="NPC",giverId=21774,ender="Zorus the Judicator",enderType="NPC",enderId=21774,rewardNextId=10644,poiX=-3971,poiY=2191,wowhead="https://www.wowhead.com/wotlk/quest=10643",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Let it be known that Zorus does have a sense of humor.$B$BEnough small talk. Don the Spectrecles so that you are able to see the Shadowmoon orc spirits that wander this stronghold. Do not be frightened as we are truly the invaders here. Alas, they must be destroyed, for their time has long since passed.$B$BDestroy the Shadowmoon harbingers infesting Wildhammer Stronghold and return to me.",logDesc="Zorus the Judicator at Wildhammer Stronghold in Shadowmoon Valley wants you to slay 12 Shadowmoon Harbingers."} end
if not DB[10644] then DB[10644]={id=10644,zoneId=3520,name="Teron Gorefiend - Lore and Legend",level=70,minLevel=67,giver="Zorus the Judicator",giverType="NPC",giverId=21774,ender="Ancient Shadowmoon Spirit",enderType="NPC",enderId=21797,poiX=-3971,poiY=2191,wowhead="https://www.wowhead.com/wotlk/quest=10644",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Stories abound about the life of Teron Gorefiend, but most are just that - stories. We do not know what happened to Gorefiend after he returned to Draenor.$B$BThe only thing we are certain of is that he has already died once.$B$BI have heard the scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far to the east, across the Netherwing Fields and through Netherwing Pass. Take the Spectrecles and track this orc down. He will surely have more information on Gorefiend.",logDesc="Zorus the Judicator at Wildhammer Stronghold in Shadowmoon Valley wants you to find the Ancient Shadowmoon Spirit.$B$BIf you lose your Spectrecles, Zorus the Judicator can make you a new pair.$B"} end
if not DB[10645] then DB[10645]={id=10645,zoneId=3520,name="Teron Gorefiend, I am...",level=70,minLevel=67,giver="Ancient Shadowmoon Spirit",giverType="NPC",giverId=21797,ender="Zorus the Judicator",enderType="NPC",enderId=21774,poiX=-4544,poiY=1023,wowhead="https://www.wowhead.com/wotlk/quest=10645",image="assets/images/quests/placeholder.png",xpDiff=7,desc="With Gorefiend's items restored, there is but one last piece to this puzzle: A host.$B$B<The ancient shadowmoon spirit's lips curl up  to form a wicked grin.>$B$BSurely you did not believe the fairy tale that I told you. The Altar of Shadows is my prison. Without your help, I would have been stuck here for all eternity. Now, I will take over your body and you will destroy my captors and break these bonds. Refuse and we will both be stuck here forever.$B$BTeron Gorefiend will be free!",logDesc="The Ancient Shadowmoon Spirit has used you as a pawn! Now that you have collected the items he required, he has revealed himself to be Teron Gorefiend. To break free of his possession, you must do his bidding and slay Karsius the Ancient Watcher.$B$BIf you succeed, return to Zorus the Judicator at Wildhammer Stronghold.",choiceRewards={{id=31104,qty=1},{id=31110,qty=1},{id=31109,qty=1},{id=31107,qty=1},{id=31106,qty=1},{id=31105,qty=1}}} end
if not DB[10646] then DB[10646]={id=10646,zoneId=3518,name="Illidan's Pupil",level=70,minLevel=68,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,rewardNextId=10649,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=10646",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You've proven your allegiance, $N.  You must forgive my caution, but in this world things are not what they appear.$B$BI will tell you about Varedis when you're ready.",logDesc="Listen to Altruis's story."} end
if not DB[10647] then DB[10647]={id=10647,zoneId=3520,name="Wanted: Uvuros, Scourge of Shadowmoon",level=70,minLevel=67,ender="Warcaller Sardon Truslice",enderType="NPC",enderId=21771,wowhead="https://www.wowhead.com/wotlk/quest=10647",image="assets/images/quests/placeholder.png",xpDiff=6,money=132000,desc="Wanted - DEAD:$B$BUvuros, scourge of Shadowmoon Valley.$B$BBy order of Overlord Or'barokh, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his carcass as proof of deed. Return the fiery mane of the beast to Warcaller Sardon Truslice should you succeed.$B$BUvuros was last seen at the Hand of Gul'dan, located in the heart of Shadowmoon Valley - east of Shadowmoon Village.",logDesc="Slay Uvuros and recover Uvuros's Fiery Mane. Return it to Warcaller Sardon Truslice at Shadowmoon Village in Shadowmoon Valley.",choiceRewards={{id=31112,qty=1},{id=31114,qty=1},{id=31111,qty=1},{id=31115,qty=1}}} end
if not DB[10648] then DB[10648]={id=10648,zoneId=3520,name="Wanted: Uvuros, Scourge of Shadowmoon",level=70,minLevel=67,ender="Warcaller Beersnout",enderType="NPC",enderId=21775,wowhead="https://www.wowhead.com/wotlk/quest=10648",image="assets/images/quests/placeholder.png",xpDiff=6,money=132000,desc="Wanted - DEAD:$B$BUvuros, scourge of Shadowmoon Valley.$B$BBy order of Thane Yoregar, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his carcass as proof of deed. Return the fiery mane of the beast to Warcaller Beersnout should you succeed.$B$BUvuros was last seen at the Hand of Gul'dan, located in the heart of Shadowmoon Valley - northeast of Wildhammer Stronghold.",logDesc="Slay Uvuros and recover Uvuros's Fiery Mane. Return it to Warcaller Beersnout at Wildhammer Stronghold in Shadowmoon Valley.",choiceRewards={{id=31112,qty=1},{id=31114,qty=1},{id=31111,qty=1},{id=31115,qty=1}}} end
if not DB[10649] then DB[10649]={id=10649,zoneId=3688,name="The Book of Fel Names",level=70,minLevel=68,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=10649",image="assets/images/quests/placeholder.png",xpDiff=8,desc="I sympathize with your intentions of stopping Varedis and his followers, but you won't stand a chance against him.  That is, unless you find the artifact that gave him his power.$B$BThe Book of Fel Names is rumored to be in the possession of Blackheart the Inciter inside the Shadow Labyrinth in Auchindoun.  Obtaining it will be your only hope against Varedis.",logDesc="Venture inside the Shadow Labyrinth in Auchindoun and obtain the Book of Fel Names from Blackheart the Inciter.  Return to Altruis in Nagrand once you've completed this task."} end
if not DB[10650] then DB[10650]={id=10650,zoneId=3520,name="Return to the Aldor",level=70,minLevel=68,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Exarch Onaala",enderType="NPC",enderId=21860,rewardNextId=10651,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=10650",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This book... I could use it to increase my power tenfold...  No!  It would end up corrupting my very soul, this I am sure of.  Return to those who sent you here, $N.$B$BYou now have the means to stop Varedis.  Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence.  That will be the only way you can deprive him of his power.",logDesc="Speak with Exarch Onaala at the Altar of Sha'tar in Shadowmoon Valley.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10651] then DB[10651]={id=10651,zoneId=3520,name="Varedis Must Be Stopped",level=70,minLevel=68,giver="Exarch Onaala",giverType="NPC",giverId=21860,ender="Exarch Onaala",enderType="NPC",enderId=21860,poiX=-3020,poiY=859,wowhead="https://www.wowhead.com/wotlk/quest=10651",image="assets/images/quests/placeholder.png",xpDiff=7,desc="We must dispose of this foul artifact, but not before we use it to dispose of Varedis's powers.$B$BWe need to permanently shut down the Ruins of Karabor training grounds, which will mean killing not only Varedis but also the three night elf masters that assist him: Alandien, Theras and Netharel.$B$BGather a suitable force and return to the Ruins of Karabor.  Follow Altruis's instructions for defeating Varedis.  For all of our sakes, I hope they work.",logDesc="Exarch Onaala wants you to go to the ruins of Karabor and slay Alandien, Theras, Netharel and Varedis.  Use the Book of Fel Names when Varedis uses Metamorphosis to weaken him.  Return to Exarch Onaala with the Book of Fel Names after you've completed this task.$B$BCompleting quests for the Aldor will cause your Scryers reputation to decrease.",choiceRewards={{id=31013,qty=1},{id=30933,qty=1},{id=31010,qty=1},{id=31002,qty=1},{id=30948,qty=1},{id=31009,qty=1}}} end
if not DB[10652] then DB[10652]={id=10652,zoneId=3523,name="Behind Enemy Lines",level=69,minLevel=67,giver="Veronia",giverType="NPC",giverId=20162,ender="Caledis Brightdawn",enderType="NPC",enderId=19840,rewardNextId=10197,poiX=3069,poiY=3598,wowhead="https://www.wowhead.com/wotlk/quest=10652",image="assets/images/quests/placeholder.png",xpDiff=1,desc="All arrangements have been made to take you to where our spies are hiding.  Just come see me when you're ready and we'll get you on your way.",logDesc="Speak to Veronia when you're ready to depart to Manaforge Coruu.  Once there, speak to Caledis Brightdawn.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10653] then DB[10653]={id=10653,zoneId=3703,name="Marks of Sargeras",level=70,minLevel=68,giver="Adyen the Lightwarden",giverType="NPC",giverId=18537,ender="Adyen the Lightwarden",enderType="NPC",enderId=18537,poiX=-1775,poiY=5734,wowhead="https://www.wowhead.com/wotlk/quest=10653",image="assets/images/quests/placeholder.png",xpDiff=5,desc="By now it should be clear to you why we oppose the Burning Legion and those who serve them.$B$BIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers.  The highest-ranking Legion can be found in Netherstorm and Shadowmoon Valley.",logDesc="Bring 10 Marks of Sargeras to Adyen the Lightwarden in Shattrath City.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10654] then DB[10654]={id=10654,zoneId=3703,name="More Marks of Sargeras",level=70,minLevel=68,giver="Adyen the Lightwarden",giverType="NPC",giverId=18537,ender="Adyen the Lightwarden",enderType="NPC",enderId=18537,poiX=-1775,poiY=5734,wowhead="https://www.wowhead.com/wotlk/quest=10654",image="assets/images/quests/placeholder.png"} end
if not DB[10655] then DB[10655]={id=10655,zoneId=3703,name="Single Mark of Sargeras",level=70,minLevel=68,giver="Adyen the Lightwarden",giverType="NPC",giverId=18537,ender="Adyen the Lightwarden",enderType="NPC",enderId=18537,poiX=-1775,poiY=5734,wowhead="https://www.wowhead.com/wotlk/quest=10655",image="assets/images/quests/placeholder.png"} end
if not DB[10656] then DB[10656]={id=10656,zoneId=3703,name="Sunfury Signets",level=70,minLevel=68,giver="Magistrix Fyalenn",giverType="NPC",giverId=18531,ender="Magistrix Fyalenn",enderType="NPC",enderId=18531,poiX=-2183,poiY=5545,wowhead="https://www.wowhead.com/wotlk/quest=10656",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As you might know, the Scryers and the armies of Kael'thas are at war.  Kael sees us as a threat to his influence over other blood elves and has tried to crush us time and again.$B$BIf you wish to aid us in our battle against Kael'thas, there are plenty of targets for you to go after.  Kael's highest ranking soldiers wear Sunfury signets to mark their ranks.  You will find them all over Netherstorm and Shadowmoon Valley.",logDesc="Magistrix Fyalenn in Shattrath City wants you to bring her 10 Sunfury Signets.$B$BPerforming quests for the Scryers will cause you Aldor reputation level to decrease."} end
if not DB[10657] then DB[10657]={id=10657,zoneId=3522,name="Ride the Lightning",level=67,minLevel=65,giver="Toshley",giverType="NPC",giverId=21691,ender="Toshley",enderType="NPC",enderId=21691,rewardNextId=10674,poiX=1914,poiY=5562,wowhead="https://www.wowhead.com/wotlk/quest=10657",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="We haven't kept the use of the Zephyrium Capacitorium under budget.  But, it occurs to me that the serpents of the Scalewing Shelf to the east have a lightning breath and glands that we can make use of.$B$BI've repolarized the magneto collector to absorb lightning strikes and I want you to head up there, activate it on yourself, and get us some cheap fuel from those serpents.",logDesc="Use the Repolarized Magneto Sphere to absorb 25 lightning strikes from the Scalewing Serpents.  Also, collect 5 Scalewing Lightning Glands.",rewards={{id=31451,qty=5}},choiceRewards={{id=31452,qty=1},{id=31453,qty=1},{id=31454,qty=1},{id=31455,qty=1}}} end
if not DB[10658] then DB[10658]={id=10658,zoneId=3703,name="More Sunfury Signets",level=70,minLevel=68,giver="Magistrix Fyalenn",giverType="NPC",giverId=18531,ender="Magistrix Fyalenn",enderType="NPC",enderId=18531,poiX=-2183,poiY=5545,wowhead="https://www.wowhead.com/wotlk/quest=10658",image="assets/images/quests/placeholder.png"} end
if not DB[10659] then DB[10659]={id=10659,zoneId=3703,name="Single Sunfury Signet",level=70,minLevel=68,giver="Magistrix Fyalenn",giverType="NPC",giverId=18531,ender="Magistrix Fyalenn",enderType="NPC",enderId=18531,poiX=-2183,poiY=5545,wowhead="https://www.wowhead.com/wotlk/quest=10659",image="assets/images/quests/placeholder.png"} end
if not DB[10660] then DB[10660]={id=10660,zoneId=3520,name="What Strange Creatures...",level=69,minLevel=67,giver="Researcher Tiorus",giverType="NPC",giverId=21770,ender="Researcher Tiorus",enderType="NPC",enderId=21770,rewardNextId=10672,poiX=-2984,poiY=2571,wowhead="https://www.wowhead.com/wotlk/quest=10660",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="I am interested in learning more about the strange reptiles that mill about the lava flows of Shadowmoon Valley. Never have I seen beasts able to withstand the searing heat of molten lava!$B$BOutside of Shadowmoon Village, where the ground has ruptured and lava flows through the cracks, you will find felfire diemetradons. Slay them and bring me their spleens. From their spleens I will be able to begin preliminary analysis of their resistance to heat.$B$BBegin your search to the southeast.$B",logDesc="Researcher Tiorus at Shadowmoon Village in Shadowmoon Valley wants you to recover 8 Felfire Spleens."} end
if not DB[10661] then DB[10661]={id=10661,zoneId=3520,name="Spleendid!",level=69,minLevel=67,giver="Gnomus",giverType="NPC",giverId=21777,ender="Gnomus",enderType="NPC",enderId=21777,rewardNextId=10677,poiX=-3973,poiY=2215,wowhead="https://www.wowhead.com/wotlk/quest=10661",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Have you ever heard of food that cooks itself and stays hot forever? Dare to dream, I say!$B$BBut maybe it's not a dream at all! Outside the fortress, near the lava pools and streams, you can find beasts that thrive in the sizzling heat. They're called felfire diemetradons.$B$BThe dwarves around here tell me that those diemetradons have the tastiest spleens ever and that the spleens practically come pre-cooked! Bring me those spleens and I'll give you some coin.$B$BStart your search directly east of here.",logDesc="Gnomus at Wildhammer Stronghold in Shadowmoon Valley wants you to recover 8 Felfire Spleens."} end
if not DB[10662] then DB[10662]={id=10662,zoneId=3520,name="The Hermit Smith",level=69,minLevel=67,giver="Ordinn Thunderfist",giverType="NPC",giverId=19370,ender="David Wayne",enderType="NPC",enderId=21465,rewardNextId=10664,poiX=-3961,poiY=2200,wowhead="https://www.wowhead.com/wotlk/quest=10662",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Ordinn examines the results from his attempt at smithing the metal and shakes his head.>$B$BThis is beyond my ability, but that's not to say the weapon can't be recreated for your use.$B$BThere was a talented smith who accompanied the Sons of Lothar to Draenor, David Wayne. He was a remarkable blacksmith, but chose to leave the expedition. These days, he lives in a small camp on a peninsula east of Firewing Point in Terokkar Forest. Take the ingots to him and see if he can help you with the weapon.",logDesc="Bring the Box of Ingots to David Wayne at Wayne's Refuge in Terokkar Forest."} end
if not DB[10663] then DB[10663]={id=10663,zoneId=3520,name="The Hermit Smith",level=69,minLevel=67,giver="Grokom Deatheye",giverType="NPC",giverId=19333,ender="David Wayne",enderType="NPC",enderId=21465,rewardNextId=10664,poiX=-3093,poiY=2586,wowhead="https://www.wowhead.com/wotlk/quest=10663",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<The orc shakes his head at his failure.>$B$BThis is beyond my ability, but that's not to say the weapon can't be recreated.$B$BIt pains me to suggest this, but your only hope may be a human smith by the name of David Wayne. It's true he was once a member of the Alliance's expedition, but that was a long time ago and he has since left the Sons of Lothar. These days, he lives in a small camp on a peninsula east of Firewing Point in Terokkar Forest. Take the ingots to him and see if he can help you.",logDesc="Bring the Box of Ingots to David Wayne at Wayne's Refuge in Terokkar Forest."} end
if not DB[10664] then DB[10664]={id=10664,zoneId=3520,name="Additional Materials",level=69,minLevel=67,giver="David Wayne",giverType="NPC",giverId=21465,ender="David Wayne",enderType="NPC",enderId=21465,poiX=-2389,poiY=2896,wowhead="https://www.wowhead.com/wotlk/quest=10664",image="assets/images/quests/placeholder.png",xpDiff=4,money=41000,desc="The ingots that you brought contain most of the metal I'll need to forge the sword's blade, but I'll need a variety of things to create other parts of the weapon.$B$BLet's see, among the things I don't have here are an adamantite frame, some heavy knothide leather, and a demon warding totem. Skilled crafters should be able to produce the first two, but the third is only sold by the reagent vendor in Shattrath's Lower City, Fantei. You'll find him with the other tradesmen.",logDesc="David Wayne at Wayne's Refuge wants you to bring him an Adamantite Frame, 4 Heavy Knothide Leather, and a Demon Warding Totem."} end
if not DB[10665] then DB[10665]={id=10665,zoneId=3520,name="Fresh from the Mechanar",level=69,minLevel=67,giver="David Wayne",giverType="NPC",giverId=21465,ender="David Wayne",enderType="NPC",enderId=21465,poiX=-2389,poiY=2896,wowhead="https://www.wowhead.com/wotlk/quest=10665",image="assets/images/quests/placeholder.png",xpDiff=8,desc="Working with the ingots you brought is going to require a lot of heat -- rather more than a conventional forge can supply.$B$BI'm going to need a supplemental heat source for the forge and there are very few things in Outland that can supply that kind of power.$B$BThe Mechanar area of Tempest Keep turns out manacells containing an incredible amount of power. Find one of the overcharged manacells from the stacks around Mechano-Lord Capacitus and bring it back here.",logDesc="David Wayne at Wayne's Retreat wants you to bring him an Overcharged Manacell."} end
if not DB[10666] then DB[10666]={id=10666,zoneId=3520,name="The Lexicon Demonica",level=69,minLevel=67,giver="David Wayne",giverType="NPC",giverId=21465,ender="David Wayne",enderType="NPC",enderId=21465,poiX=-2389,poiY=2896,wowhead="https://www.wowhead.com/wotlk/quest=10666",image="assets/images/quests/placeholder.png",xpDiff=8,money=41000,desc="Recreating the enchantments on the blade requires several spells to be spoken in demonic.$B$BIt's not something I was taught during my training as an apprentice, but there's no way around it. There's a book, called the Lexicon Demonica, that will provide most of the words I need, but it's in the hands of a powerful Shadow Council warlock.$B$BDeep in the halls of Auchindoun's Shadow Labyrinth, it is held by Grandmaster Vorpil. Do whatever you must to secure the book and bring it to me. ",logDesc="Obtain the Lexicon Demonica from Grandmaster Vorpil and bring it to David Wayne at Wayne's Refuge."} end
if not DB[10667] then DB[10667]={id=10667,zoneId=3520,name="Underworld Loam",level=70,minLevel=67,giver="David Wayne",giverType="NPC",giverId=21465,ender="David Wayne",enderType="NPC",enderId=21465,poiX=-2389,poiY=2896,wowhead="https://www.wowhead.com/wotlk/quest=10667",image="assets/images/quests/placeholder.png",xpDiff=8,money=44000,desc="The frame that you brought me earlier will not be sufficient to hold molten metal without reinforcement. A rare kind of earth can be used to cool and imbue the frame, giving the adamantite an unnatural strength.$B$BUnderwold loam, as the earth is known, is accorded great value among the naga. Few enough of them possess it, and in Outland, I know of only one naga who uses it -- Hydromancer Thespia, who resides in the Steamvault of Coilfang Reservoir.",logDesc="Get a Vial of Underworld Loam from Hydromancer Thespia and bring it to David Wayne at Wayne's Refuge."} end
if not DB[10668] then DB[10668]={id=10668,zoneId=3518,name="Against the Illidari",level=70,minLevel=68,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=10668",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I still have respect for Illidan.  Without him I would not have found my path.$B$BHe is not who he once was, however.  His soul has been corrupted by power, his mind has been twisted by defeat.  He has become what I am sworn to destroy and his pet servants, the Illidari, are as much of an abomination as any demon of the Burning Legion.$B$BHis grasp on Outland is slipping yet his reach is still vast.  Prove you're not with him by slaying his lieutenant Lothros at Illidari Point in Shadowmoon Valley.",logDesc="Altruis the Sufferer wants you to slay Lothros at Illidari Point in Shadowmoon Valley."} end
if not DB[10669] then DB[10669]={id=10669,zoneId=3518,name="Against All Odds",level=70,minLevel=68,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=10669",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Some demons pledge allegiance to no one but themselves.  A true enemy of demons finds and destroys his prey regardless of affiliation, however.$B$BThe demon Xeleth - a Legion defector - was once worshipped as a god by primitive swamp creatures in Zangarmarsh.  When Draenor was nearly destroyed, he retreated into a slumber deep beneath Marshlight Lake.  Find the portal at the lake and plant this spear into the ground.$B$BXeleth will awake - be ready to slay him and prove you're an enemy to all demons.",logDesc="Altruis the Sufferer wants you to take the Imbued Silver Spear and use it at Portal Clearing near Marshlight Lake in Zangarmarsh to awake Xeleth.  Return to Altruis after you've slain the demon."} end
if not DB[10670] then DB[10670]={id=10670,zoneId=3520,name="Tear of the Earthmother",level=70,minLevel=67,giver="David Wayne",giverType="NPC",giverId=21465,ender="David Wayne",enderType="NPC",enderId=21465,poiX=-2389,poiY=2896,wowhead="https://www.wowhead.com/wotlk/quest=10670",image="assets/images/quests/placeholder.png",xpDiff=8,money=44000,desc="The sword's enchantments must be contained within a powerful focus, such as a gem. I know of a gem that we can use for this purpose, for there are few that can play host to such powerful magics without shattering.$B$BThe gem we need is called the tear of the earthmother. It's a powerful artifact in the hands of the ogres who created it, and Warbringer O'mrogg, who currently holds the gem, has many powerful allies in Hellfire Citadel's Shattered Halls. Take care in retrieving the tear, $N.",logDesc="Recover the Tear of the Earthmother from Warbringer O'mrogg and return it to David Wayne at Wayne's Refuge."} end
if not DB[10671] then DB[10671]={id=10671,zoneId=3522,name="More than a Pound of Flesh",level=67,minLevel=65,giver="Dizzy Dina",giverType="NPC",giverId=21824,ender="Dizzy Dina",enderType="NPC",enderId=21824,poiX=1922,poiY=5569,wowhead="https://www.wowhead.com/wotlk/quest=10671",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="$N, I've got something else for you to do.  One of the eggheads wants to study the fiendling flesh beasts that can be found at Razaan's Landing, north of the Razor Ridge.$B$BMore to the point, they want to study the flesh of the flesh beasts that are there.$B$B<Dizzy makes a disgusted face.>$B$BBut, of course, they aren't willing to get their hands dirty, and they only want the ether-energized flesh, which it's not likely that all of them have.$B$BI say, beggars can't be choosers, but what can you do?",logDesc="Collect 5 Ether-Energized Flesh."} end
if not DB[10672] then DB[10672]={id=10672,zoneId=3520,name="Frankly, It Makes No Sense...",level=69,minLevel=67,giver="Researcher Tiorus",giverType="NPC",giverId=21770,ender="Researcher Tiorus",enderType="NPC",enderId=21770,rewardNextId=10673,poiX=-2984,poiY=2571,wowhead="https://www.wowhead.com/wotlk/quest=10672",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="We must study these creatures further.$B$BFar to the east - near the huge lava flow beneath the ruins of Baa'ri - you will find arcano control units. These controllers were crafted by a genius named Gnomus for the sole purpose of exploring lava via mechanical scorpion.$B$BHe has long since lost his mind and is now only interested in eating the hottest food known to gnome-kind.$B$B<Tiorus gives you a funny look.>$B$BI want you to use the control and tag the diemetradons of the lava flow for further study.$B",logDesc="Researcher Tiorus at Shadowmoon Village in Shadowmoon Valley wants you to travel to the lava flow near the Ruins of Baa'ri and use the Arcano Control Unit to control an Arcano-Scorp, swim in the lava with the Arcano-Scorp, and tag 8 Greater Felfire Diemetradons."} end
if not DB[10673] then DB[10673]={id=10673,zoneId=3520,name="Felspine the Greater",level=70,minLevel=67,giver="Researcher Tiorus",giverType="NPC",giverId=21770,ender="Researcher Tiorus",enderType="NPC",enderId=21770,poiX=-2984,poiY=2571,wowhead="https://www.wowhead.com/wotlk/quest=10673",image="assets/images/quests/placeholder.png",xpDiff=5,money=88000,desc="Gnomus knows about the massive diemetradon and plans to eat it! He must have been able to see what I could see through the eyes of his arcano-scorp. Look, there's no time to explain. He's crazy and that craziness is going to cost us the closest thing we've got to a fireproof jumpsuit.$B$BGet back to the lava flow near Baa'ri and track down Felspine the Greater. Once you find it, kill it and bring me back its hide.$B$BDon't try and reason with me, $N. I'm well past that point.",logDesc="Researcher Tiorus at Shadowmoon Village in Shadowmoon Valley wants you to kill Felspine the Greater and recover Felspine's Hide.$B"} end
if not DB[10674] then DB[10674]={id=10674,zoneId=3522,name="Trapping the Light Fantastic",level=67,minLevel=65,giver="Toshley",giverType="NPC",giverId=21691,ender="Toshley",enderType="NPC",enderId=21691,rewardNextId=10675,poiX=1914,poiY=5562,wowhead="https://www.wowhead.com/wotlk/quest=10674",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="The Razaani ethereals have been playing with some interesting technology at Razaan's Landing to the north.$B$BI'm sure they won't mind if you use this trap to take a few samples of their little pink floating light orbs?  They're probably only for decoration anyway.$B$BThe trap has a special property to it that when opened should attract one of the floating balls towards it.  Of course, it'll probably also alert the Razaani to your presence.",logDesc="Use the Light Trap to collect 15 Razaani Light Orbs."} end
if not DB[10675] then DB[10675]={id=10675,zoneId=3522,name="Show Them Gnome Mercy!",level=68,minLevel=65,giver="Toshley",giverType="NPC",giverId=21691,ender="Toshley",enderType="NPC",enderId=21691,poiX=1914,poiY=5562,wowhead="https://www.wowhead.com/wotlk/quest=10675",image="assets/images/quests/placeholder.png",xpDiff=6,money=78000,desc="<The blood drains out of Toshley's face.>$B$BThese orbs are made up of both nether energy and souls, some of them gnome souls!$B$BHow dare they!  Were they the ones killing our people that traveled north?!$B$B$N, you must put a stop to this, and the only way to do that is to finish off their leader, Nexus-Prince Razaan.$B$BYou'll have to coax him out of hiding though.  I'm guessing that you can do that by killing a lot of his Razaani ethereal.$B$BBring me the collection of souls that he no doubt has.",logDesc="Collect the Collection of Souls.",rewards={{id=30690,qty=1}},choiceRewards={{id=31456,qty=1},{id=31457,qty=1},{id=31458,qty=1},{id=31459,qty=1}}} end
if not DB[10676] then DB[10676]={id=10676,zoneId=3520,name="Bane of the Illidari",level=70,minLevel=67,giver="David Wayne",giverType="NPC",giverId=21465,ender="David Wayne",enderType="NPC",enderId=21465,rewardNextId=10679,poiX=-2389,poiY=2896,wowhead="https://www.wowhead.com/wotlk/quest=10676",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<David gathers his smithing supplies.>$B$BYou've done well in getting everything we'll need to reforge the anti-demon blade. Your hard work and dedication is about to be repaid.$B$BThe time has come to forge the sword.",logDesc="Wait for David Wayne to finish forging a sword for you."} end
if not DB[10677] then DB[10677]={id=10677,zoneId=3520,name="The Second Course...",level=69,minLevel=67,giver="Gnomus",giverType="NPC",giverId=21777,ender="Gnomus",enderType="NPC",enderId=21777,rewardNextId=10678,poiX=-3973,poiY=2215,wowhead="https://www.wowhead.com/wotlk/quest=10677",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="I remember seeing larger diemetradons east of the Hand of Gul'dan, near the lava flows around the Ruins of Baa'ri. What I want you to get for me now is one overdeveloped felfire gizzard from the beasts around that area. You might have to kill several to find a gizzard like the one I described. Keep at it! One of them is bound to have my next meal.",logDesc="Gnomus at Wildhammer Stronghold in Shadowmoon Valley wants you to recover 1 Overdeveloped Felfire Gizzard."} end
if not DB[10678] then DB[10678]={id=10678,zoneId=3520,name="The Main Course!",level=70,minLevel=67,giver="Gnomus",giverType="NPC",giverId=21777,ender="Gnomus",enderType="NPC",enderId=21777,poiX=-3973,poiY=2215,wowhead="https://www.wowhead.com/wotlk/quest=10678",image="assets/images/quests/placeholder.png",xpDiff=5,money=88000,desc="Long story short, I used to work with a blood elf named Tiorus. My partnership with Tiorus dissolved once I got into gourmet living. He decided to take it upon himself to continue our research using MY inventions. Anyhow, he had some of his Horde goons using my arcano-scorp probes at the Ruins of Baa'ri lava flow and discovered the mother of all diemetradons!$B$BI need you to get there before he does and kill the diemetradon, Felspine, and bring his hide back to me.$B$BHurry up!",logDesc="Gnomus at Wildhammer Stronghold in Shadowmoon Valley wants you to recover Felspine's Hide."} end
if not DB[10679] then DB[10679]={id=10679,zoneId=3520,name="Quenching the Blade",level=70,minLevel=67,giver="David Wayne",giverType="NPC",giverId=21465,ender="David Wayne",enderType="NPC",enderId=21465,poiX=-2389,poiY=2896,wowhead="https://www.wowhead.com/wotlk/quest=10679",image="assets/images/quests/placeholder.png",xpDiff=6,money=44000,desc="The blade is nearly finished!$B$BYou can almost feel the magic beginning to coalesce inside the steel, but one thing remains to be done.$B$BYou must take the forged blade to the Scalding Pools near the top of the Hand of Gul'dan in Shadowmoon Valley and plunge it into the lava pools to quench the sword. When you have quenched the sword, return.",logDesc="Travel to the Scalding Pools located near the top of the Hand of Gul'dan and use the Forged Illidari-Bane Blade to quench it in the lava pools. Once you have the Quenched Illidari-Bane Blade, return to David Wayne at Wayne's Refuge.",choiceRewards={{id=30788,qty=1},{id=30789,qty=1},{id=30787,qty=1},{id=31745,qty=1}}} end
if not DB[10680] then DB[10680]={id=10680,zoneId=3520,name="The Hand of Gul'dan",level=70,minLevel=68,giver="Earthmender Sophurus",giverType="NPC",giverId=21937,ender="Earthmender Torlok",enderType="NPC",enderId=21024,rewardNextId=10458,poiX=-4036,poiY=2225,wowhead="https://www.wowhead.com/wotlk/quest=10680",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The elements need your help, $r! Shadowmoon Valley has been subject to unspeakable evils. The spirits remain tortured to this day. Many are enraged and unwilling to commune with the Earthen Ring.$B$BHelp this world heal, friend.$B$BDirectly northeast of Wildhammer Stronghold you will find an area known as the Altar of Damnation. Make your way there and speak with Earthmender Torlok.",logDesc="Speak with Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley."} end
if not DB[10681] then DB[10681]={id=10681,zoneId=3520,name="The Hand of Gul'dan",level=70,minLevel=68,giver="Earthmender Splinthoof",giverType="NPC",giverId=21938,ender="Earthmender Torlok",enderType="NPC",enderId=21024,rewardNextId=10458,poiX=-2922,poiY=2658,wowhead="https://www.wowhead.com/wotlk/quest=10681",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The elements need your help, $r! Shadowmoon Valley has been subject to unspeakable evils. The spirits remain tortured to this day. Many are enraged and unwilling to commune with the Earthen Ring.$B$BHelp this world heal, friend.$B$BSoutheast of Shadowmoon Village - in the heart of Shadowmoon Valley - you will find an area known as the Altar of Damnation. Make your way there and speak with Earthmender Torlok.",logDesc="Speak with Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley."} end
if not DB[10682] then DB[10682]={id=10682,zoneId=3522,name="A Time for Negotiation...",level=67,minLevel=65,giver="Tree Warden Chawn",giverType="NPC",giverId=22007,ender="Tree Warden Chawn",enderType="NPC",enderId=22007,rewardNextId=10713,poiX=2981,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10682",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="When we arrived in the Ruuan Weald, the wyrm cultists were keeping themselves to Blackwing Coven, through the tunnel to the west.  But now, they are encroaching upon us here.$B$BI need you to find the wyrmcultists' overseer.  He's known to make a regular patrol between their various camps in the Ruuan Weald.$B$BNegotiate with him.  Let him know that there's room for compromise, but that we will not condone or allow the wholesale slaughter of the wildlife, nor the felling of all of the trees.",logDesc="Negotiate with Overseer Nuaar."} end
if not DB[10683] then DB[10683]={id=10683,zoneId=3520,name="Tablets of Baa'ri",level=70,minLevel=68,giver="Arcanist Thelis",giverType="NPC",giverId=21955,ender="Arcanist Thelis",enderType="NPC",enderId=21955,rewardNextId=10684,poiX=-4133,poiY=1131,wowhead="https://www.wowhead.com/wotlk/quest=10683",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Ashtongue Broken have been ordered by Illidan to excavate the Ruins of Baa'ri, to the far north.  They're in search of draenei artifacts, no doubt - Baa'ri was home to many Baa'ri relics before Gul'dan buried the town under a volcanic explosion.  We must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to hold the secrets of the Temple of Karabor... a place you might know as the Black Temple.",logDesc="Arcanist Thelis at the Sanctum of the Stars wants you to collect 12 Baa'ri Tablets from the ground and from Ashtongue Workers at the Ruins of Baa'ri.$B$BCompleting quests with the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10684] then DB[10684]={id=10684,zoneId=3520,name="Oronu the Elder",level=70,minLevel=68,giver="Arcanist Thelis",giverType="NPC",giverId=21955,ender="Arcanist Thelis",enderType="NPC",enderId=21955,rewardNextId=10685,poiX=-4133,poiY=1131,wowhead="https://www.wowhead.com/wotlk/quest=10684",image="assets/images/quests/placeholder.png",xpDiff=5,desc="According to the tablets, an artifact known as a Medallion of Karabor was kept at Baa'ri.  Only the highest-ranking draenei priests were granted these, as they allowed unfettered access into the Temple of Karabor.$B$BWe must find out whether the Ashtongue have recovered the medallion that was kept at Baa'ri yet.  Its power would provide great aid in our fight against Illidan.$B$BAkama's lieutenant at Baa'ri, Oronu the Elder, receives written orders from him daily.  Obtain them and bring them to me.",logDesc="Arcanist Thelis at the Sanctum of the Stars wants you to obtain the Orders from Akama from Oronu the Elder at the Ruins of Baa'ri.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10685] then DB[10685]={id=10685,zoneId=3520,name="The Ashtongue Corruptors",level=70,minLevel=68,giver="Arcanist Thelis",giverType="NPC",giverId=21955,ender="Arcanist Thelis",enderType="NPC",enderId=21955,rewardNextId=10686,poiX=-4133,poiY=1131,wowhead="https://www.wowhead.com/wotlk/quest=10685",image="assets/images/quests/placeholder.png",xpDiff=5,desc="According to Akama's letter, four fragments of the medallion were unearthed and given to the Ashtongue Corruptors.  These dreaded Broken were once powerful shaman who now defile the very elements they revered.$B$BHaalum, Corruptor of Air, can be found at Netherwing Pass.  Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at the Fel Pits near the Hand of Gul'dan.  Lakaan, Corruptor of Water, is rumored to be near Coilskar Point.$B$BFind them and obtain the medallion fragments.",logDesc="Obtain the four medallion fragments from Haalum, Eykenen, Lakaan and Uylaru and return to Arcanist Thelis at the Sanctum of the Stars in Shadowmoon Valley.$B$BPerforming quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10686] then DB[10686]={id=10686,zoneId=3520,name="The Warden's Cage",level=70,minLevel=68,giver="Arcanist Thelis",giverType="NPC",giverId=21955,ender="Sanoru",enderType="NPC",enderId=21826,rewardNextId=10622,poiX=-4133,poiY=1131,wowhead="https://www.wowhead.com/wotlk/quest=10686",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The fragments you obtained are only half of the medallion.  The Ashtongue leader, Akama, must have kept the other half.$B$BI dread to ask this of you, as Akama is both evil and cunning.$B$BHe and the Ashtongue Deathsworn - the vilest and most brutal of the tribe - are rumored to run a torture chamber inside the Warden's Cage.$B$BI want you to find that dreaded prison,  and find the whereabouts of Akama.  His second in command at the location is a Broken known as Sanoru - interrogate him if you have to.",logDesc="Arcanist Thelis wants you to enter the Warden's Cage, south of the Ruins of Baa'ri and interrogate Sanoru on Akama's whereabouts.$B$BCompleting quests for the Scryers will cause your Aldor reputation to decrease."} end
if not DB[10687] then DB[10687]={id=10687,zoneId=3520,name="Karabor Training Grounds",level=70,minLevel=68,giver="Larissa Sunstrike",giverType="NPC",giverId=21954,ender="Larissa Sunstrike",enderType="NPC",enderId=21954,rewardNextId=10688,poiX=-4081,poiY=1160,wowhead="https://www.wowhead.com/wotlk/quest=10687",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Our scouts have reported a massive influx of Sunfury blood elf recruits heading to the Ruins of Karabor.  Normally this would represent a purely military threat, however we believe something else is amiss.$B$BDescriptions of their attire and fighting style are suspiciously close to that of Illidan himself.  I do not want to become alarmed without good reason, so I would like you to go there and bring me back their weapons.  We will then determine whether my fears are unfounded or not.",logDesc="Larissa Sunstrike at the Sanctum of the Stars wants you to obtain 8 Sunfury Glaives from the Demon Hunter Supplicants and Demon Hunter Initiates at the Ruins of Karabor, northeast of the Sanctum of the Stars.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10688] then DB[10688]={id=10688,zoneId=3520,name="A Necessary Distraction",level=70,minLevel=68,giver="Larissa Sunstrike",giverType="NPC",giverId=21954,ender="Larissa Sunstrike",enderType="NPC",enderId=21954,rewardNextId=10689,poiX=-4081,poiY=1160,wowhead="https://www.wowhead.com/wotlk/quest=10688",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The weapons are authentic, as we feared.  Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it.$B$BDo not be fooled by their name, $N, their power will be used against us as often as against any demon.$B$BTheir warlocks summon and subdue demons to be used as part of the initiates' training.  A pit lord named Azaloth has proven too strong to be used in training and is kept banished.  Find a way to let him loose on his captors.  That should buy us the time we need.",logDesc="Larissa Sunstrike wants you to return to the Ruins of Karabor and find a way to unleash Azaloth on his captors.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10689] then DB[10689]={id=10689,zoneId=3518,name="Altruis",level=70,minLevel=68,giver="Larissa Sunstrike",giverType="NPC",giverId=21954,ender="Altruis the Sufferer",enderType="NPC",enderId=18417,poiX=-4081,poiY=1160,wowhead="https://www.wowhead.com/wotlk/quest=10689",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You don't see many demon hunters nowawdays.  They're viewed with suspicion by their own people and it's very rare to find one that doesn't have some sort of allegiance to Illidan.$B$BThere are rumors of one such demon hunter out in Nagrand.  His name is Altruis.  He hates all demons with a passion and will help us if you can convince him that you share his goals.$B$BGo to western Nagrand and find him.  He might be willing to shed some light on these new demon hunter training grounds.",logDesc="Travel to western Nagrand and find Altruis the Sufferer.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10690] then DB[10690]={id=10690,zoneId=3522,name="The Den Mother",level=66,minLevel=65,ender="Commander Skyshadow",enderType="NPC",enderId=21158,wowhead="https://www.wowhead.com/wotlk/quest=10690",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="WANTED!$B$BRema, the den mother and primary defender of the Jagged Ridge south of Thunderlord Stronghold.$B$BFind her by heading east out of town and across the bridge that traverses the Bloodmaul Ravine.  She keeps herself secluded in the tunnel at the southern edge of the ridge.$B$BReturn with news of her demise to Commander Skyshadow of Sylvanaar.",logDesc="Slay Rema.",choiceRewards={{id=31423,qty=1},{id=31422,qty=1},{id=31424,qty=1}}} end
if not DB[10691] then DB[10691]={id=10691,zoneId=3520,name="Return to the Scryers",level=70,minLevel=68,giver="Altruis the Sufferer",giverType="NPC",giverId=18417,ender="Larissa Sunstrike",enderType="NPC",enderId=21954,rewardNextId=10692,poiX=-1545,poiY=8785,wowhead="https://www.wowhead.com/wotlk/quest=10691",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This book... I could use it to increase my power tenfold...  No!  It would end up corrupting my very soul, this I am sure of.  Return to those who sent you here, $N.$B$BYou now have the means to stop Varedis.  Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence.  That will be the only way you can deprive him of his power.",logDesc="Speak with Larissa Sunstrike at the Sanctum of the Stars in Shadowmoon Valley.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10692] then DB[10692]={id=10692,zoneId=3520,name="Varedis Must Be Stopped",level=70,minLevel=68,giver="Larissa Sunstrike",giverType="NPC",giverId=21954,ender="Larissa Sunstrike",enderType="NPC",enderId=21954,poiX=-4081,poiY=1160,wowhead="https://www.wowhead.com/wotlk/quest=10692",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Of course we must destroy this book, but not before we use it to destroy Varedis.$B$BIf we're to shut down this academy of Illidan imitators, we'll have to deal not just with Varedis but also the three night elf masters that assist him: Alandien, Theras and Netharel.$B$BGather a suitable force and return to the Ruins of Karabor.  Follow Altruis's instructions for defeating Varedis.  Hopefully his plan will work - otherwise... it'll have been a pleasure working with you.",logDesc="Larissa Sunstrike wants you to go to the ruins of Karabor and slay Alandien, Theras, Netharel and Varedis.  Use the Book of Fel Names when Varedis uses Metamorphosis to weaken him.  Return to Larissa Sunstrike with the Book of Fel Names after completing this task.$B$BCompleting quests for the Scryers will cause your Aldor reputation to decrease.",choiceRewards={{id=31013,qty=1},{id=30933,qty=1},{id=31010,qty=1},{id=31002,qty=1},{id=30948,qty=1},{id=31009,qty=1}}} end
