if not DB[10700] then DB[10700]={id=10700,zoneId=-367,name="Ten Commendation Signets",level=60,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=10700",image="assets/images/quests/placeholder.png"} end
if not DB[10701] then DB[10701]={id=10701,zoneId=3523,name="Breaking Down Netherock",level=68,minLevel=67,ender="Rocket-Chief Fuselage",enderType="NPC",enderId=19570,wowhead="https://www.wowhead.com/wotlk/quest=10701",image="assets/images/quests/placeholder.png",xpDiff=5,money=78000,desc="To whomever cares about the timely construction of the X-52 Nether-Rocket --$B$BThe king of the local mountain giants, Netherock, has been terrorizing the Crumbling Wastes.  He's been interfering with operations all along the south ledge of the island!$B$BTake your friends and deal with him!  Then, return to me here in Area 52.$B$BRocket-Chief Fuselage",logDesc="Slay Netherock and then report in with Rocket-Chief Fuselage at Area 52 in the Netherstorm.",choiceRewards={{id=31314,qty=1},{id=31313,qty=1},{id=31315,qty=1},{id=31312,qty=1}}} end
if not DB[10702] then DB[10702]={id=10702,zoneId=3520,name="A Grunt's Work...",level=69,minLevel=67,giver="Overlord Or'barokh",giverType="NPC",giverId=21769,ender="Overlord Or'barokh",enderType="NPC",enderId=21769,poiX=-2921,poiY=2663,wowhead="https://www.wowhead.com/wotlk/quest=10702",image="assets/images/quests/placeholder.png",xpDiff=5,money=123000,desc="All Horde forces in this region have been dispatched to handle the attacks from the Burning Legion. This means that we are short-handed for grunt work.$B$BOur supply caravans are in constant danger from the wildlife of the region. We can't veer 15 feet off the road without running into a chimaera, felboar, or abnormally large scorpion.$B$BGet out there and clear Shadowmoon Valley of its sadistic wildlife! Just kill 'em all!",logDesc="Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley wants you to kill 20 Shadowmoon Valley Wildlife.$B$BThese creatures include Felboars, Vilewing Chimaera, and Scorchshell Pincer. Any combination will be sufficient."} end
if not DB[10703] then DB[10703]={id=10703,zoneId=3520,name="Put On Yer Kneepads...",level=69,minLevel=67,giver="Thane Yoregar",giverType="NPC",giverId=21773,ender="Thane Yoregar",enderType="NPC",enderId=21773,poiX=-4034,poiY=2233,wowhead="https://www.wowhead.com/wotlk/quest=10703",image="assets/images/quests/placeholder.png",xpDiff=5,money=123000,desc="It's time to get down in the muck and get dirty. What were you expectin'? You gotta learn to walk before you can crawl, right? Er, reverse that...$B$BAnyway, we got all hands on deck fer killin' the garbage being thrown at us by the Burning Legion. That leaves you with the honor of cleaning up the crazed wildlife of Shadowmoon Valley.$B$BGrab a sword, staff, whatever it is that makes you happy, and kill as much of the wildlife as you can see. That'll clear a way out for our supply caravans!",logDesc="Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley wants you to kill 20 Shadowmoon Valley Wildlife.$B$BThese creatures include Felboars, Vilewing Chimaeras, and Scorchshell Pincers. Any combination will be sufficient."} end
if not DB[10704] then DB[10704]={id=10704,zoneId=3845,name="How to Break Into the Arcatraz",level=70,minLevel=67,giver="A'dal",giverType="NPC",giverId=18481,ender="A'dal",enderType="NPC",enderId=18481,rewardNextId=10882,poiX=-1864,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=10704",image="assets/images/quests/placeholder.png",xpDiff=8,money=132000,desc="A message was embedded in the ata'mal crystal that you recovered.  Nexus-Prince Haramad has given us information vital to our campaign against Tempest Keep.$B$BHe tells us that there are two pieces, shards to a key, which, when combined, will unlock the keep's Arcatraz satellite.$B$BOne half is possessed by an ancient in the Botanica known as Warp Splinter.  The other is held by Pathaleon the Calculator inside the Mechanar.$B$BBring both shards to me and I will combine them into the Arcatraz key.",logDesc="A'dal has tasked you with the recovery of the Top and Bottom Shards of the Arcatraz Key.  Return them to him, and he will fashion them into the Key to the Arcatraz for you.",rewards={{id=31084,qty=1}},choiceRewards={{id=31465,qty=1},{id=31461,qty=1},{id=31464,qty=1},{id=31462,qty=1},{id=31460,qty=1}}} end
if not DB[10705] then DB[10705]={id=10705,zoneId=3845,name="Seer Udalo",level=70,minLevel=68,giver="Akama",giverType="NPC",giverId=21700,ender="Udalo",enderType="NPC",enderId=21962,rewardNextId=10706,poiX=-3715,poiY=1029,wowhead="https://www.wowhead.com/wotlk/quest=10705",image="assets/images/quests/placeholder.png",xpDiff=8,desc="I hope you're not shocked when I reveal to you that the pieces of the Medallion of Karabor you obtained from my minions are mere replicas.$B$B<Akama shows you an identical medallion in his open palm.>$B$BMy Deathsworn and I have kept the secret from Illidan for as long as possible.   We are however, still missing the final piece.$B$BUdalo came to me in dreams  to announce he had found it.  Unfortunately he is held by Kael'thas inside the Arcatraz in Tempest Keep.  Find him and see what he knows.",logDesc="Find Seer Udalo inside the Arcatraz in Tempest Keep."} end
if not DB[10706] then DB[10706]={id=10706,zoneId=3520,name="A Mysterious Portent",level=70,minLevel=68,giver="Udalo",giverType="NPC",giverId=21962,ender="Akama",enderType="NPC",enderId=21700,rewardNextId=10707,poiX=469,poiY=12,wowhead="https://www.wowhead.com/wotlk/quest=10706",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Before he died, Udalo appears to have written a single word on the floor beneath him.  The writing is barely legible but you recognize the word Atam'al.$B$BPerhaps Akama will understand the meaning of his brethren's message.",logDesc="Return to Akama at the Warden's Cage in Shadowmoon Valley."} end
if not DB[10707] then DB[10707]={id=10707,zoneId=3520,name="The Ata'mal Terrace",level=70,minLevel=68,giver="Akama",giverType="NPC",giverId=21700,ender="Akama",enderType="NPC",enderId=21700,poiX=-3715,poiY=1029,wowhead="https://www.wowhead.com/wotlk/quest=10707",image="assets/images/quests/placeholder.png",xpDiff=7,desc="It has been known to us that the fel orcs, under Illidan's command, have guarded an Ata'mal crystal known as the Heart of Fury at the Ata'mal Terrace.  They cloud its presence with dark magic, to keep it from the Sha'tar.$B$BFight your way to the Ata'mal Terrace outside the Black Temple and turn your eyes to the sky.  Shadowlord Deathwail will circle the terrace, beyond your reach.  You will have to slay him and his warlocks before you can obtain the crystal.$B$BIt won't be easy, $N.  I wish you luck.",logDesc="Go to the top of the Ata'mal Terrace in Shadowmoon Valley and obtain the Heart of Fury.  Return to Akama at the Warden's Cage in Shadowmoon Valley when you've completed this task."} end
if not DB[10708] then DB[10708]={id=10708,zoneId=3520,name="Akama's Promise",level=70,minLevel=68,giver="Akama",giverType="NPC",giverId=21700,ender="A'dal",enderType="NPC",enderId=18481,poiX=-3715,poiY=1029,wowhead="https://www.wowhead.com/wotlk/quest=10708",image="assets/images/quests/placeholder.png",xpDiff=7,desc="<Akama inserts the crystal into the medallion in his hand.>$B$BI am not as strong as I once was, $N.  Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.$B$BTake this as my promise to you that when the time comes and you face Illidan, I will be on your side.  Take it to the one being we know we can trust with its power.  Take the medallion to A'dal in Shattrath City.",logDesc="Bring the Medallion of Karabor to A'dal in Shattrath City.",choiceRewards={{id=30932,qty=1},{id=30999,qty=1},{id=31000,qty=1},{id=30943,qty=1},{id=30984,qty=1},{id=31417,qty=1}}} end
if not DB[10709] then DB[10709]={id=10709,zoneId=3522,name="Reunion",level=67,minLevel=65,giver="Leoroxx",giverType="NPC",giverId=22004,ender="3",enderType="NPC",enderId=21984,rewardNextId=10714,poiX=2207,poiY=4761,wowhead="https://www.wowhead.com/wotlk/quest=10709",image="assets/images/quests/placeholder.png",xpDiff=2,desc="So you come from the world beyond the Portal? And you know of Rexxar. Oh yes, I am quite familiar with him.$b$bYou see, he is my son.$b$bBut he made his choice a lifetime ago. He is not one of us, and he is not welcome here. We have enough troubles with the Bloodmaul ogres.$b$bKnow this: being born a half-breed does not make you Mok'Nathal.",logDesc="Speak with Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains."} end
if not DB[10710] then DB[10710]={id=10710,zoneId=3522,name="Test Flight: The Singing Ridge",level=64,minLevel=62,giver="Tally Zapnabber",giverType="NPC",giverId=21460,ender="Tally Zapnabber",enderType="NPC",enderId=21460,poiX=1935,poiY=5576,wowhead="https://www.wowhead.com/wotlk/quest=10710",image="assets/images/quests/placeholder.png",xpDiff=3,money=16000,desc="I've been fiddling with the Zephyrium Capicitorium and I'm ready to perform another test!  Do you want to help?$B$BThis next flight should be short, but fast!$B$BUm... and although I'm sure there's no danger... I have this, uh, waiver that I'd like  you to sign.  It's just a formality, I assure you!$B$BBest of luck!  Talk to Rally to launch yourself, and come back to me after the experiment is over!",logDesc="Sign Tally's Waiver, then speak with Rally Zapnabber to use the Zephyrium Capacitorium."} end
if not DB[10711] then DB[10711]={id=10711,zoneId=3522,name="Test Flight: Razaan's Landing",level=64,minLevel=62,giver="Tally Zapnabber",giverType="NPC",giverId=21460,ender="Tally Zapnabber",enderType="NPC",enderId=21460,poiX=1935,poiY=5576,wowhead="https://www.wowhead.com/wotlk/quest=10711",image="assets/images/quests/placeholder.png",xpDiff=3,money=24000,desc="$n, I raised the efficiency of the Zephyrium Capacitorium by 30 percent.  That will launch a test subject of your weight and wind drag ratio to new heights!  Want to test my theory?  This experiment ought to send you near Razaan's Landing.$B$BSpeak with Rally... he'll get you prepared for launch.",logDesc="Speak with Rally Zapnabber to use the Zephyrium Capacitorium."} end
if not DB[10712] then DB[10712]={id=10712,zoneId=3522,name="Test Flight: Ruuan Weald",level=64,minLevel=62,giver="Tally Zapnabber",giverType="NPC",giverId=21460,ender="O'Mally Zapnabber",enderType="NPC",enderId=22020,poiX=1935,poiY=5576,wowhead="https://www.wowhead.com/wotlk/quest=10712",image="assets/images/quests/placeholder.png",xpDiff=3,money=31000,desc="Hey, $N.  I'm glad I caught you!  I have a very important mission!$B$BHere is a nether-weather vane.  I need you to take some in flight readings for me and deliver them to my cousin in Ruuan Weald.$B$BSpeak with Rally and take a Zephyrium Capacitorium flight to Ruuan Weald.  While you're flying, spin the vane!$B$BAfter you land, bring the spinning vane to O'Mally Zabnabber.$B$BGood luck, $n.  And don't delay!",logDesc="Speak with Rally Zapnabber to use the Zephyrium Capacitorium.  While flying to Ruuan Weald, spin the Nether-weather Vane.  Deliver the Spinning Nether-weather Vane to O'Mally Zapnabber in Evergrove."} end
if not DB[10713] then DB[10713]={id=10713,zoneId=3522,name="...and a Time for Action",level=67,minLevel=65,giver="Tree Warden Chawn",giverType="NPC",giverId=22007,ender="Tree Warden Chawn",enderType="NPC",enderId=22007,poiX=2981,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10713",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="We will not stand idly by while they decimate the Ruuan Weald around us.  Our first priority must be to the trees.$B$B$C, I want you to go back out into the Weald and deliver a very different message for us.  I want you to slay every one of their hewers that you come into contact with!$B$BIf they will not listen to reason, perhaps they will listen to a more assertive method of persuasion!",logDesc="Slay 10 Wyrmcult Hewers.",choiceRewards={{id=31510,qty=1},{id=31512,qty=1},{id=31516,qty=1},{id=31521,qty=1}}} end
if not DB[10714] then DB[10714]={id=10714,zoneId=3522,name="On Spirit's Wings",level=67,minLevel=65,giver="3",giverType="NPC",giverId=21984,ender="3",enderType="NPC",enderId=21984,rewardNextId=10783,poiX=2298,poiY=6034,wowhead="https://www.wowhead.com/wotlk/quest=10714",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="If the Mok'Nathal are tormented by the Bloodmaul ogres, then I will stop them and their followers. Ogres are simple creatures, and there is little profit they could gain from harassing the Mok'Nathal.$b$bThere must be something more to this. $n, take Spirit, my hawk, and spy upon the conversations of the Bloodmaul's leaders. He may go undetected where we cannot.",logDesc="Find a Bloodmaul Taskmaster and a Bloodmaul Soothsayer engaged in conversation, then use Rexxar's Whistle to summon Spirit to spy on them."} end
if not DB[10715] then DB[10715]={id=10715,zoneId=3522,name="Into the Churning Gulch",level=67,minLevel=65,giver="Baron Sablemane",giverType="NPC",giverId=22103,ender="Baron Sablemane",enderType="NPC",enderId=22103,poiX=2919,poiY=5957,wowhead="https://www.wowhead.com/wotlk/quest=10715",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="So, your Rexxar would have me fashion a poison for him? I'll give him what he desires, but there will be a price. Even for friends, there must be a price. Free things destroy friendships.$B$BFirst, you must venture a short distance to the southwest to the Churning Gulch.$B$BTherein mill some of the most poisonous creatures in all of Outland, or anywhere. I speak of the crust bursters, and this poison will require gathering their glands for me.",logDesc="Collet 7 Crust Burster Venom Glands.",rewards={{id=31535,qty=5}}} end
if not DB[10716] then DB[10716]={id=10716,zoneId=3522,name="Test Flight: Raven's Wood <needs reward>",level=64,minLevel=62,giver="Tally Zapnabber",giverType="NPC",giverId=21460,poiX=1935,poiY=5576,wowhead="https://www.wowhead.com/wotlk/quest=10716",image="assets/images/quests/placeholder.png",xpDiff=6,money=8000,desc="The Zephyrium Capacitorium is ready for its longest launch yet!  What do you say, $N?  Do you want to fly one more time?$B$BI've been boosting the proplusion system but, until I get all the variables hammered out, the capicitorium will need added fuel to give it the necessary kick!  Speak with Rally before the flight -- he has the details.$B$BBest of luck, $N.  This flight will take you to distant Raven's Wood.  If you survive the flight -- and the wood's ogres and arakkoa -- come back and we'll celebrate!",logDesc="Speak with Rally Zapnabber to use the Zephyrium Capacitorium.  Return to Tally Zapnabber at Toshley's Station."} end
if not DB[10717] then DB[10717]={id=10717,zoneId=3522,name="Poaching from Poachers",level=67,minLevel=65,giver="Samia Inkling",giverType="NPC",giverId=21983,ender="Samia Inkling",enderType="NPC",enderId=21983,rewardNextId=10747,poiX=2981,poiY=5486,wowhead="https://www.wowhead.com/wotlk/quest=10717",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="Pardon me, but I couldn't help but overhear your conversation with Chawn.  I'd like to help.$B$BI'm studying the Blackwing Coven, and helping the druids in their dealings with them.$B$BI am very interested in acquiring a few of their dragon whelps; it would help us to gauge exactly what we're up against by understanding that which they revere.$B$BBut first, we're going to need to acquire some nets.  I noticed that the wyrmcult poachers out in the Ruuan Weald have an abundance of them.",logDesc="Collect 5 Wyrmcult Nets."} end
if not DB[10718] then DB[10718]={id=10718,zoneId=3522,name="The Spirits Have Voices",level=67,minLevel=65,giver="Garm Wolfbrother",giverType="NPC",giverId=21950,ender="3",enderType="NPC",enderId=21984,rewardNextId=10614,poiX=2273,poiY=5984,wowhead="https://www.wowhead.com/wotlk/quest=10718",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N, now that you can see me, there is something you must tell Rexxar. I know that he seeks his people, and I know where they are.$B$BThe Mok'Nathal, as they are known, have a village to the east beyond the Razor Ridge.$B$BGo, give Rexxar this news. His people are in danger, and I know that he will want to come to their aid.",logDesc="Speak with Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains."} end
if not DB[10719] then DB[10719]={id=10719,zoneId=3522,name="Did You Get The Note?",level=67,minLevel=65,ender="Tree Warden Chawn",enderType="NPC",enderId=22007,wowhead="https://www.wowhead.com/wotlk/quest=10719",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The cultist dropped this note, which apparently was to be delivered to Overseer Nuaar.  It is signed by someone named Kolphis Darkscale.$B$BIt is likely that Tree Warden Chawn will be interested in looking at this.",logDesc="Deliver the Meeting Note to Tree Warden Chawn at Evergrove in the Blade's Edge Mountains."} end
if not DB[10720] then DB[10720]={id=10720,zoneId=3522,name="The Smallest Creatures",level=67,minLevel=65,giver="3",giverType="NPC",giverId=21984,ender="3",enderType="NPC",enderId=21984,rewardNextId=10721,poiX=2298,poiY=6034,wowhead="https://www.wowhead.com/wotlk/quest=10720",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="The ogres, simple as they are, would notice you dispersing this poison throughout their camp. Thus, I will teach you how to enlist the help of one of nature's smallest creatures to do this task.$b$bBy playing a simple rhythm on this drum, you can coax a marmot to follow your commands.$b$bThere is a den of marmots near the Bloodmaul camp, to the north, down in the Daggermaw Canyon past the Circle of Blood.$B$BOnce you have a marmot's aid, use it to disperse the poison to the Bloodmaul's kegs.",logDesc="Use the Kodohide Drum at the Marmot Den. While controlling the Marmot, poison the three kegs in the Bloodmaul Camp."} end
if not DB[10721] then DB[10721]={id=10721,zoneId=3522,name="A Boaring Time for Grulloc",level=67,minLevel=65,giver="3",giverType="NPC",giverId=21984,ender="Baron Sablemane",enderType="NPC",enderId=22103,rewardNextId=10785,poiX=2298,poiY=6034,wowhead="https://www.wowhead.com/wotlk/quest=10721",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="$N, I have a pet boar named Huffer. He wants to help you to have some fun with one of the nearby sons of Gruul.$B$BGrulloc inhabits a place known as the Cursed Hollow. When you get there, let Huffer loose. The gronn will have a fine time chasing him around, and you will retrieve the bag that he guards and deliver it to Baron Sablemane.$B$BTo get to the Cursed Hollow, head down the northern ramp and east through Dragons' End. The hollow is on the eastern edge.",logDesc="Collect Grulloc's Sack."} end
if not DB[10722] then DB[10722]={id=10722,zoneId=3522,name="Meeting at the Blackwing Coven",level=68,minLevel=65,giver="Watcher Moonshade",giverType="NPC",giverId=22386,ender="Tree Warden Chawn",enderType="NPC",enderId=22007,rewardNextId=10748,poiX=3108,poiY=6132,wowhead="https://www.wowhead.com/wotlk/quest=10722",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="I know what must be done!  $N, you must pose as Overseer Nuaar and attend that meeting!$B$BThe wyrmcultists at the coven all have a standard outfit that they wear, so go collect scraps from them, and when you have enough, put together a disguise.$B$BPose as Overseer Nuuar and speak with Kolphis Darkscale to see what he has to say, and then return to Tree Warden Chawn.$B$BYou'll find the coven by heading through the Wyrmskull Tunnel and following the path past the Raven's Wood and Grishnath to its end.",logDesc="Collect enough Costume Scraps from wyrmcultists to create an Overseer Disguise.  Use the disguise to attend the meeting with Kolphis Darkscale."} end
if not DB[10723] then DB[10723]={id=10723,zoneId=3522,name="Gorgrom the Dragon-Eater",level=68,minLevel=65,giver="3",giverType="NPC",giverId=21984,ender="3",enderType="NPC",enderId=21984,rewardNextId=10724,poiX=2298,poiY=6034,wowhead="https://www.wowhead.com/wotlk/quest=10723",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The gronn we seek is Gorgrom the Dragon-Eater. With Sablemane's trap, you will make short work of the gronn. You will find him accepting sacrifices from the ogres of Boulder'mok.$b$bFollow the road north from the Circle of Blood, then west at Ruuan Weald. Go northwest through the tunnel.$b$bFirst, kill the ogres for their heads. We will send a message. Set the trap at his altar. When he is dead, plant the grisly totems near him - none can mistake that message.$b$bTake the bear.$b$b<Misha growls.>",logDesc="Collect 3 Grisly Totems from the Boulder'mok ogres. Then, use Sablemane's Trap at Gorgrom's Altar to set the trap and summon and kill Gorgrom the Dragon-Eater.$b$bWhen Gorgrom is dead, place the 3 Grisly Totems near his corpse.",choiceRewards={{id=31542,qty=1},{id=31541,qty=1},{id=31543,qty=1}}} end
if not DB[10724] then DB[10724]={id=10724,zoneId=3522,name="Prisoner of the Bladespire",level=67,minLevel=65,giver="3",giverType="NPC",giverId=21984,ender="3",enderType="NPC",enderId=21984,rewardNextId=10742,poiX=2298,poiY=6034,wowhead="https://www.wowhead.com/wotlk/quest=10724",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="Shortly after my arrival in the mountains, I came under attack by a group of Bladespire ogres.$b$bThough I fought free of them, and slew many, they took my wyvern, Leokk, captive. Spirit has found him, locked in a cage in the heart of the Bladespire encampment outside of Gruul's lair.$b$bOne of the ogres must carry his key. Find it and Spirit can use it to unlock Leokk's cage.$B$BYou will find the encampment at the north end of the Daggermaw Canyon down below.",logDesc="Slay Bladespire ogres to get the Wyvern Cage Key. Once you have it, go to the Wyvern Cage and use Spirit's Whistle to summon Spirit, who will unlock the cage to free Leokk."} end
if not DB[10725] then DB[10725]={id=10725,zoneId=2562,name="Eminence Among the Violet Eye",level=70,minLevel=70,giver="Archmage Leryda",giverType="NPC",giverId=18253,ender="Archmage Leryda",enderType="NPC",enderId=18253,poiX=-11116,poiY=-2014,wowhead="https://www.wowhead.com/wotlk/quest=10725",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Your services have gone above and beyond what is expected of you, $N.  You are but a step away from achieving the highest honor available to non-citizens of Dalaran.$B$BContinue to prove your loyalty to us and I will empower your signet to its full capacity.",logDesc="Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Exalted reputation with the Violet Eye.",rewards={{id=29287,qty=1}}} end
