if not DB[10733] then DB[10733]={id=10733,zoneId=2562,name="Down the Violet Path",level=70,minLevel=70,giver="Archmage Leryda",giverType="NPC",giverId=18253,ender="Archmage Leryda",enderType="NPC",enderId=18253,rewardNextId=10738,poiX=-11116,poiY=-2014,wowhead="https://www.wowhead.com/wotlk/quest=10733",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You've chosen your path, $c.  Now it is up to you to travel the path to wherever it may lead.$B$BYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.",logDesc="Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.",rewards={{id=29285,qty=1}}} end
