if not DB[10737] then DB[10737]={id=10737,zoneId=1941,name="The Master's Touch",level=70,minLevel=68,rewardNextId=9837,wowhead="https://www.wowhead.com/wotlk/quest=10737",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I've put together the very key I used as an apprentice.  It looks completely functional as far as keys go.  In regards to opening Karazhan, however, this might as well be a piece of scrap metal.$B$BWithout Medivh's consent, the key is worthless.  Yes, of course I know Medivh is dead.  This merely makes things difficult, not impossible$B$BThere is a place in Azeroth called the Caverns of Time, guarded by the bronze dragonflight.  Find a way inside, travel back in time and get Medivh to enable the key.",logDesc="Go into the Caverns of Time and convince Medivh to enable your Restored Apprentice's Key."} end
if not DB[10738] then DB[10738]={id=10738,zoneId=2562,name="Distinguished Service",level=70,minLevel=70,giver="Archmage Leryda",giverType="NPC",giverId=18253,ender="Archmage Leryda",enderType="NPC",enderId=18253,rewardNextId=10725,poiX=-11116,poiY=-2014,wowhead="https://www.wowhead.com/wotlk/quest=10738",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You have not disappointed us, $N.  We continue to have very high hopes for you, however.$B$BContinue to serve the Violet Eye and you will be appropriately rewarded.",logDesc="Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.",rewards={{id=29286,qty=1}}} end
