if not DB[10742] then DB[10742]={id=10742,zoneId=3522,name="Showdown",level=70,minLevel=65,giver="3",giverType="NPC",giverId=21984,ender="3",enderType="NPC",enderId=21984,poiX=2298,poiY=6034,wowhead="https://www.wowhead.com/wotlk/quest=10742",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Now it comes to this. We will bring Goc forth from his lair, and we will destroy him. With Goc dead, the Bladespire ogres will threaten the Mok'Nathal no longer. Go to Goc's altar outside Gruul's Lair, then blow my horn. I will come, and we will face the son of Gruul together.",logDesc="Use Rexxar's Battle Horn at the Altar of Goc, then kill Goc.",choiceRewards={{id=31546,qty=1},{id=31544,qty=1},{id=31545,qty=1},{id=31547,qty=1},{id=31549,qty=1},{id=31548,qty=1}}} end
if not DB[10743] then DB[10743]={id=10743,zoneId=3522,name="[DEPRECATED]<txt>Hero of the Mok'Nathal",level=67,minLevel=65,wowhead="https://www.wowhead.com/wotlk/quest=10743",image="assets/images/quests/placeholder.png"} end
if not DB[10744] then DB[10744]={id=10744,zoneId=3520,name="News of Victory",level=70,minLevel=67,giver="Plexi",giverType="NPC",giverId=21790,ender="Kurdran Wildhammer",enderType="NPC",enderId=21330,poiX=-2764,poiY=1981,wowhead="https://www.wowhead.com/wotlk/quest=10744",image="assets/images/quests/placeholder.png",xpDiff=6,money=44000,desc="You must bring word of our success to Kurdran Wildhammer immediately! His men, under Wing Commander Nuainn, have fought nonstop to keep Wildhammer Stronghold safe and your return will surely bolster their spirits. With the threat from the Legion out of the way, Kurdran can finally turn his attention to dealing with the forces of Illidan. Our place here is far from secure, but we've won a major victory this day.",logDesc="Return to Wildhammer Stronghold and speak with Kurdran Wildhammer.",choiceRewards={{id=30973,qty=1},{id=30924,qty=1},{id=31025,qty=1},{id=31033,qty=1},{id=31031,qty=1}}} end
if not DB[10745] then DB[10745]={id=10745,zoneId=3520,name="News of Victory",level=70,minLevel=67,giver="Nakansi",giverType="NPC",giverId=21789,ender="Overlord Or'barokh",enderType="NPC",enderId=21769,poiX=-2726,poiY=2713,wowhead="https://www.wowhead.com/wotlk/quest=10745",image="assets/images/quests/placeholder.png",xpDiff=6,money=44000,desc="You must bring word of our success to Overlord Or'barokh immediately! Now that we've crushed the Legion and obliterated their presence in Shadowmoon Valley, the overlord can turn his attention to our other foes.$B$BAlthough the Kor'kron guard will never admit it, they'll be glad we're no longer fighting on two fronts.",logDesc="Return to Shadowmoon Village and speak with Overlord Or'barokh.",choiceRewards={{id=30973,qty=1},{id=30924,qty=1},{id=31025,qty=1},{id=31033,qty=1},{id=31031,qty=1}}} end
if not DB[10746] then DB[10746]={id=10746,zoneId=1941,name="DEPRECATED Karazhan: LAB - E - Exalted Ring - Caster",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=10746",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Your accomplishments have gone beyond my greatest expectations,$N.$B$BYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.$B$BContinue to serve the Scale of the Sands and I will unleash your gift's full potential.",logDesc="Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.",rewards={{id=29305,qty=1}}} end
if not DB[10747] then DB[10747]={id=10747,zoneId=3522,name="Whelps of the Wyrmcult",level=68,minLevel=65,giver="Samia Inkling",giverType="NPC",giverId=21983,ender="Samia Inkling",enderType="NPC",enderId=21983,poiX=2981,poiY=5486,wowhead="https://www.wowhead.com/wotlk/quest=10747",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="I need to examine the whelps that they are raising at the Blackwing Coven.$B$BThere should be an abundance of them flying around inside their cavernous base, as well as a number of eggs, which if you get close to them will likely hatch.$B$BPlease, $N, take the net and capture a handful of them alive for me.$B$BFind them by heading west across the Wyrmskull Bridge and heading through the Wyrmskull Tunnel.  Follow the path to its end past Grishnath and the Raven's Wood.",logDesc="Use the Blackwhelp Net to capture 10 Wyrmcult Blackwhelps.",choiceRewards={{id=31509,qty=1},{id=31513,qty=1},{id=31515,qty=1},{id=31519,qty=1}}} end
if not DB[10748] then DB[10748]={id=10748,zoneId=3522,name="Maxnar Must Die!",level=68,minLevel=65,giver="Tree Warden Chawn",giverType="NPC",giverId=22007,ender="Tree Warden Chawn",enderType="NPC",enderId=22007,poiX=2981,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10748",image="assets/images/quests/placeholder.png",xpDiff=6,money=78000,desc="They've left us no choice, $N.  It's time to put an end to the threat from the Blackwing Coven by taking out their leader, Maxnar the Ashmaw.$B$BI don't know if you caught a glimpse of him while you were in there, but he's one of the dragonkin, half-man, half-dragon.  And he's tough, so don't underestimate him!$B$BFinish it quickly and with any luck you'll secure the safety of Evergrove and the Ruuan Weald.",logDesc="Slay Maxnar the Ashmaw.",choiceRewards={{id=31508,qty=1},{id=31511,qty=1},{id=31514,qty=1},{id=31520,qty=1}}} end
if not DB[10749] then DB[10749]={id=10749,zoneId=3522,name="Baron Sablemane's Poison",level=67,minLevel=65,giver="Baron Sablemane",giverType="NPC",giverId=22103,ender="3",enderType="NPC",enderId=21984,rewardNextId=10720,poiX=2919,poiY=5957,wowhead="https://www.wowhead.com/wotlk/quest=10749",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Here, take this to your master. I'm sure that whatever the reason, Rexxar will put it to good use.$B$BOh, and do be certain to remind him that he owes me.$B$BHe knows what I want, and I'm certain that however he intends to obtain it for me, I'll be seeing you again sooner than you think.$B$BNow, do be a good little $g boy : girl; and run this up to Rexxar.",logDesc="Deliver Baron Sablemane's Poison to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains."} end
if not DB[10750] then DB[10750]={id=10750,zoneId=3520,name="The Path of Conquest",level=70,minLevel=68,giver="Overlord Or'barokh",giverType="NPC",giverId=21769,ender="Kor'kron Wind Rider",enderType="NPC",enderId=21998,rewardNextId=10751,poiX=-2921,poiY=2663,wowhead="https://www.wowhead.com/wotlk/quest=10750",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Word has come from my wind riders, $N. The Eclipsion blood elves are planning something big. They have begun forming their armies at the Path of Conquest, far to the southeast - adjacent to Eclipse Point.$B$BI want you to travel to the Path of Conquest and assess the situation. Once you have done so, use this flare gun to signal a wind rider. One will swoop down from the sky to meet you. Inform them of what you have discovered and they will give you your next set of orders.",logDesc="Travel to the Path of Conquest in Shadowmoon Valley. "} end
if not DB[10751] then DB[10751]={id=10751,zoneId=3520,name="Breaching the Path",level=70,minLevel=68,giver="Kor'kron Wind Rider",giverType="NPC",giverId=21998,ender="Kor'kron Wind Rider",enderType="NPC",enderId=21998,rewardNextId=10765,wowhead="https://www.wowhead.com/wotlk/quest=10751",image="assets/images/quests/placeholder.png",xpDiff=6,desc="We're going to need more time, $r. I'm going to fly further ahead with some of the other wind riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!$B$BCall for a wind rider with the Kor'kron flare gun once you have thinned their numbers.",logDesc="Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 10 Eclipsion Spellbinders."} end
if not DB[10752] then DB[10752]={id=10752,zoneId=331,name="Onward to Ashenvale",level=20,minLevel=18,giver="Thundris Windweaver",giverType="NPC",giverId=3649,ender="Raene Wolfrunner",enderType="NPC",enderId=3691,poiX=6581,poiY=492,wowhead="https://www.wowhead.com/wotlk/quest=10752",image="assets/images/quests/placeholder.png",xpDiff=4,money=900,desc="Recently Raene Wolfrunner came through Auberdine from Darnassus and was heading to Ashenvale; she said something about the Furbolgs. I wasn't given an opportunity to ask more about her situation but perhaps you can seek her out and lend her your aid $C. Take the southern road out of Auberdine. Once you reach Ashenvale border continue your path down the road. There you will find Astranaar and Raene Wolfrunner.",logDesc="Speak with Raene Wolfrunner in Astranaar."} end
if not DB[10753] then DB[10753]={id=10753,zoneId=3522,name="Culling the Wild",level=67,minLevel=65,giver="Faradrella",giverType="NPC",giverId=22133,ender="Faradrella",enderType="NPC",enderId=22133,poiX=3025,poiY=5452,wowhead="https://www.wowhead.com/wotlk/quest=10753",image="assets/images/quests/placeholder.png",xpDiff=4,money=29000,desc="The number of atrocities committed by the Burning Legion is countless. Even as we speak, they send their legion forces against the creatures of this land. Helpless to defend against their power, they fall one by one. $N, help me stop these crimes of nature destroy all which they corrupt. $B$BOver the hill, east of here, you will see the corruption spreading across Bladed Gulch. Kill the ones causing the crime, the Fel Corrupters, and as many Felsworn as you can.",logDesc="Slay 4 Felsworn Scalewing, 4 Felsworn Daggermaw, and 2 Fel Corrupters."} end
if not DB[10754] then DB[10754]={id=10754,zoneId=3483,name="Entry Into the Citadel",level=70,minLevel=68,ender="Force Commander Danath Trollbane",enderType="NPC",enderId=16819,rewardNextId=10762,wowhead="https://www.wowhead.com/wotlk/quest=10754",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.$B$BMaybe this could prove to interest to Danath, the force commander at Honor Hold.",logDesc="Bring the Primed Key Mold to Force Commander Danath at Honor Hold in Hellfire Peninsula."} end
if not DB[10755] then DB[10755]={id=10755,zoneId=3483,name="Entry Into the Citadel",level=70,minLevel=68,ender="Nazgrel",enderType="NPC",enderId=3230,rewardNextId=10756,wowhead="https://www.wowhead.com/wotlk/quest=10755",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.$B$BMaybe this could prove to interest to Nazgrel, the leader of the Horde's forces in Thrallmar.",logDesc="Bring the Primed Key Mold to Nazgrel at Thrallmar in Hellfire Peninsula."} end
if not DB[10756] then DB[10756]={id=10756,zoneId=3483,name="Grand Master Rohok",level=70,minLevel=68,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Rohok",enderType="NPC",enderId=16583,rewardNextId=10757,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=10756",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it as the Shattered Hand's own.$B$BThere is a good chance this key will allow you to enter the Shattered Halls.$B$BSpeak to Rohok, our resident blacksmith.  If anyone can forge this key it is he.",logDesc="Bring the Primed Key Mold to Rohok at Thrallmar in Hellfire Peninsula."} end
if not DB[10757] then DB[10757]={id=10757,zoneId=3483,name="Rohok's Request",level=70,minLevel=68,giver="Rohok",giverType="NPC",giverId=16583,ender="Rohok",enderType="NPC",enderId=16583,rewardNextId=10758,poiX=167,poiY=2796,wowhead="https://www.wowhead.com/wotlk/quest=10757",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Fel orc blacksmiths may not be the most skilled in the world, but there is some craftsmanship to their trade.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.$B$BBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.",logDesc="Bring 4 Fel Iron Bars, 2 Arcane Dust and 4 Motes of Fire to Rohok at Thrallmar in Hellfire Peninsula."} end
if not DB[10758] then DB[10758]={id=10758,zoneId=3483,name="Hotter than Hell",level=70,minLevel=68,giver="Rohok",giverType="NPC",giverId=16583,ender="Rohok",enderType="NPC",enderId=16583,poiX=167,poiY=2796,wowhead="https://www.wowhead.com/wotlk/quest=10758",image="assets/images/quests/placeholder.png",xpDiff=6,desc="It's no good, $N!  No matter how many coals I put to the fire, it's just not enough heat.$B$BThere's only one thing I can think of that is hot enough to temper this key and it is the insides of the Legion's fel reavers.$B$BI've only ever seen one downed once.  I remember seeing its insides fuming, shooting fire and steam as it fell.  Take this mold and plunge it into a fallen fel reaver.  I recommend you get yourself some friends if you plan to take one down.",logDesc="Destroy a Fel Reaver in Hellfire Peninsula and plunge the Unfired Key Mold into its remains.  Bring the Charred Key Mold to Rohok in Thrallmar.",rewards={{id=28395,qty=1}}} end
if not DB[10759] then DB[10759]={id=10759,zoneId=3520,name="Find the Deserter",level=69,minLevel=67,giver="Gryphonrider Kieran",giverType="NPC",giverId=22042,ender="Parshah",enderType="NPC",enderId=22024,rewardNextId=10777,poiX=-3936,poiY=2092,wowhead="https://www.wowhead.com/wotlk/quest=10759",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I get the feeling that all the pieces are here, but I just can't put them together in a way that makes sense.$B$BI think our best lead is to attempt to locate this deserter. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.$B$BStart your search for him along the road in Magma Fields to the northwest. It seems a likely place for him to take refuge.",logDesc="Locate Parshah in the Magma Fields and speak to him."} end
if not DB[10760] then DB[10760]={id=10760,zoneId=3520,name="The Sketh'lon Wreckage",level=69,minLevel=67,giver="Sergeant Kargrul",giverType="NPC",giverId=22043,ender="Sergeant Kargrul",enderType="NPC",enderId=22043,rewardNextId=10761,poiX=-3039,poiY=2519,wowhead="https://www.wowhead.com/wotlk/quest=10760",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The Sketh'lon Wreckage, just to the east, is an eerie place. The peons are convinced that it's cursed.$B$BThere are few trees here, so the peons have no choice but to venture into the arakkoa ruins to chop wood. The arakkoa spirits prey on the work groups, draining their life and using it to fuel their foul magics.$B$BWe must find out what is driving the dark conclave and stop them before their influence expands. Search the Sketh'lon Wreckage for evidence of their plans.",logDesc="Recover the Skethlon Commander's Journal Page 1, Skethlon Commander's Journal Page 2, and Skethlon Commander's Journal Page 3 from the Dark Conclave arakkoa at the Sketh'lon Wreckage to Sergeant Kargrul at Shadowmoon Village."} end
if not DB[10761] then DB[10761]={id=10761,zoneId=3520,name="Find the Deserter",level=69,minLevel=67,giver="Sergeant Kargrul",giverType="NPC",giverId=22043,ender="Parshah",enderType="NPC",enderId=22024,rewardNextId=10777,poiX=-3039,poiY=2519,wowhead="https://www.wowhead.com/wotlk/quest=10761",image="assets/images/quests/placeholder.png",xpDiff=1,desc="There's nothing here that would explain why the spirits of these arakkoa have remained in this world or how they came into thirst for the blood of orcs.$B$BI think our best lead is to try to find the deserter mentioned in the journal. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.$B$BStart your search for him on the road through the Magma Fields to the southeast.",logDesc="Locate Parshah in the Magma Fields and speak to him."} end
if not DB[10762] then DB[10762]={id=10762,zoneId=3483,name="Grand Master Dumphry",level=70,minLevel=68,giver="Force Commander Danath Trollbane",giverType="NPC",giverId=16819,ender="Dumphry",enderType="NPC",enderId=21209,rewardNextId=10763,poiX=-816,poiY=2614,wowhead="https://www.wowhead.com/wotlk/quest=10762",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it at the Shattered Hand's own.$B$BThere is a good chance this key will allow you to enter the Shattered Halls.$B$BSpeak to Dumphry.  He is a master of his craft.  If he can't craft this key for you, no one can.",logDesc="Bring the Primed Key Mold to Dumphry in Honor Hold."} end
if not DB[10763] then DB[10763]={id=10763,zoneId=3483,name="Dumphry's Request",level=70,minLevel=68,giver="Dumphry",giverType="NPC",giverId=21209,ender="Dumphry",enderType="NPC",enderId=21209,rewardNextId=10764,poiX=-595,poiY=2899,wowhead="https://www.wowhead.com/wotlk/quest=10763",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Fel orcs might be complete barbarians but their smithing is not as primitive as you might think.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.$B$BBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.",logDesc="Bring 4 Fel Iron Bars, 2 Arcane Dust and 4 Motes of Fire to Dumphry at Honor Hold in Hellfire Peninsula."} end
if not DB[10764] then DB[10764]={id=10764,zoneId=3483,name="Hotter than Hell",level=70,minLevel=68,giver="Dumphry",giverType="NPC",giverId=21209,ender="Dumphry",enderType="NPC",enderId=21209,poiX=-595,poiY=2899,wowhead="https://www.wowhead.com/wotlk/quest=10764",image="assets/images/quests/placeholder.png",xpDiff=6,desc="It's not working, $g lad : lass;.  I cannot give it enough heat... the materials will not be properly tempered.$B$BYou know, the Fel Reavers used by the Burning Legion are powered by a scalding core of fel fire - it burns much hotter than normal fire.$B$BIf you could find enough people to take one down, you could heat the mold in the insides of the fallen reaver.  Beware, $c, those fel reavers pack quite a punch.",logDesc="Destroy a Fel Reaver in Hellfire Peninsula and plunge the Unfired Key Mold into its remains.  Bring the Charred Key Mold to Dumphry in Honor Hold.",rewards={{id=28395,qty=1}}} end
if not DB[10765] then DB[10765]={id=10765,zoneId=3520,name="When Worlds Collide...",level=70,minLevel=68,giver="Kor'kron Wind Rider",giverType="NPC",giverId=21998,ender="Kor'kron Wind Rider",enderType="NPC",enderId=21998,rewardNextId=10768,wowhead="https://www.wowhead.com/wotlk/quest=10765",image="assets/images/quests/placeholder.png",xpDiff=6,desc="At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. You've probably already noticed the smaller giants on the path as well. Something is just not right about all of this, grunt.$B$BI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.",logDesc="Slay Chancellor Bloodleaf and Corok the Mighty and recover Illidan's Command."} end
if not DB[10766] then DB[10766]={id=10766,zoneId=3520,name="Invasion Point: Cataclysm",level=69,minLevel=67,giver="Wing Commander Nuainn",giverType="NPC",giverId=21357,ender="Plexi",enderType="NPC",enderId=21790,rewardNextId=10606,poiX=-3918,poiY=2052,wowhead="https://www.wowhead.com/wotlk/quest=10766",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Wildhammer Stronghold won't be safe until the Legion's presence is erased from Shadowmoon Valley.$B$BI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Plexi will meet you at your destination.",logDesc="Report to Plexi at Invasion Point: Cataclysm."} end
if not DB[10767] then DB[10767]={id=10767,zoneId=3520,name="Invasion Point: Cataclysm",level=69,minLevel=67,giver="Blood Guard Gulmok",giverType="NPC",giverId=21359,ender="Nakansi",enderType="NPC",enderId=21789,rewardNextId=10611,poiX=-3136,poiY=2550,wowhead="https://www.wowhead.com/wotlk/quest=10767",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Shadowmoon Village won't be safe until the Legion's presence is erased from the valley.$B$BI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Nakansi will meet you at your destination.",logDesc="Report to Nakansi at Invasion Point: Cataclysm."} end
if not DB[10768] then DB[10768]={id=10768,zoneId=3520,name="Tabards of the Illidari",level=70,minLevel=68,giver="Kor'kron Wind Rider",giverType="NPC",giverId=21998,ender="Kor'kron Wind Rider",enderType="NPC",enderId=21998,rewardNextId=10769,wowhead="https://www.wowhead.com/wotlk/quest=10768",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The wind riders must return to Shadowmoon Village to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.$B$BWhen you have collected enough tabards, call for a wind rider using the Kor'kron flare gun. Prepare yourself for a bit of espionage, $r!",logDesc="Collect 10 Illidari Tabards."} end
if not DB[10769] then DB[10769]={id=10769,zoneId=3520,name="Dissension Amongst the Ranks...",level=70,minLevel=68,giver="Kor'kron Wind Rider",giverType="NPC",giverId=21998,ender="Overlord Or'barokh",enderType="NPC",enderId=21769,wowhead="https://www.wowhead.com/wotlk/quest=10769",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Researcher Tiorus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.$B$BTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!",logDesc="Slay 5 Crazed Colossus while in disguise as an Illidari blood elf and return to Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley. He will also want his Kor'kron Flare Gun returned.",choiceRewards={{id=31075,qty=1},{id=31077,qty=1},{id=31076,qty=1},{id=31078,qty=1}}} end
if not DB[10770] then DB[10770]={id=10770,zoneId=3522,name="Little Embers",level=67,minLevel=65,giver="Mosswood the Ancient",giverType="NPC",giverId=22053,ender="Mosswood the Ancient",enderType="NPC",enderId=22053,poiX=3018,poiY=5523,wowhead="https://www.wowhead.com/wotlk/quest=10770",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="Northeast of here, on the plateau above us lies the burnt ashes of my ancient home. A great wood flourished there before the Burning Legion sent their imps to burn us away. So many died that even centuries later my tired old heart hungers for revenge. There are too many of them for us to ever reclaim the land, but you could make them afraid.$B$BSurely you will help me?",logDesc="Mosswood the Ancient wants you to kill 8 Scorch Imps and then return to him in Ruuan Weald. "} end
if not DB[10771] then DB[10771]={id=10771,zoneId=3522,name="From the Ashes",level=67,minLevel=65,giver="Mosswood the Ancient",giverType="NPC",giverId=22053,ender="Mosswood the Ancient",enderType="NPC",enderId=22053,poiX=3018,poiY=5523,wowhead="https://www.wowhead.com/wotlk/quest=10771",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="If you follow the road east and up the side of the mountain, then turn north, you will come to my long lost home.$b$bOnce there was a wood there. Its name is forgotten. Long ago the Burning Legion summoned scorched imps and other creatures of flame. My home was destroyed and my people fled. Now only I remain. $B$BI have saved some ironroot seeds that could be planted in fertile volcanic soil. Their magic is strong. Do this for me and I will share with you the treasures of a forgotten age.",logDesc="Mosswood the Ancient wants you to journey to Skald and plant Ironroot Seeds in three different mounds of Fertile Volcanic Soil and then return to him in Ruuan Weald.",choiceRewards={{id=31414,qty=1},{id=31416,qty=1},{id=31415,qty=1}}} end
if not DB[10772] then DB[10772]={id=10772,zoneId=3520,name="The Path of Conquest",level=70,minLevel=68,giver="Thane Yoregar",giverType="NPC",giverId=21773,ender="Wildhammer Gryphon Rider",enderType="NPC",enderId=22059,rewardNextId=10773,poiX=-4034,poiY=2233,wowhead="https://www.wowhead.com/wotlk/quest=10772",image="assets/images/quests/placeholder.png",xpDiff=4,desc="My gryphon riders have come back with a bit of news! The Eclipsion blood elves are planning something big. They've begun forming their armies at the Path of Conquest, located east of here - adjacent to Eclipse Point.$B$BI want you to travel to the Path of Conquest and assess the situation. Once you've done so, use this flare gun to signal a gryphon rider. One will swoop down from the sky to meet you. Tell 'em what you've discovered and they'll give you the next set of orders.",logDesc="Travel to the Path of Conquest in Shadowmoon Valley."} end
if not DB[10773] then DB[10773]={id=10773,zoneId=3520,name="Breaching the Path",level=70,minLevel=68,giver="Wildhammer Gryphon Rider",giverType="NPC",giverId=22059,ender="Wildhammer Gryphon Rider",enderType="NPC",enderId=22059,rewardNextId=10774,wowhead="https://www.wowhead.com/wotlk/quest=10773",image="assets/images/quests/placeholder.png",xpDiff=6,desc="We're going to need more time, $r. I'm going to fly further ahead with some of the other gryphon riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!$B$BCall for a gryphon rider with the Wildhammer flare gun once you have thinned their numbers.",logDesc="Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 5 Sons of Corok."} end
if not DB[10774] then DB[10774]={id=10774,zoneId=3520,name="Blood Elf + Giant = ???",level=70,minLevel=68,giver="Wildhammer Gryphon Rider",giverType="NPC",giverId=22059,ender="Wildhammer Gryphon Rider",enderType="NPC",enderId=22059,rewardNextId=10775,wowhead="https://www.wowhead.com/wotlk/quest=10774",image="assets/images/quests/placeholder.png",xpDiff=6,desc="At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. What are giants even doing here? Something is just not right about all of this, grunt.$B$BI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.",logDesc="Slay Chancellor Bloodleaf and Corok the Mighty and recover Illidan's Command."} end
if not DB[10775] then DB[10775]={id=10775,zoneId=3520,name="Tabards of the Illidari",level=70,minLevel=68,giver="Wildhammer Gryphon Rider",giverType="NPC",giverId=22059,ender="Wildhammer Gryphon Rider",enderType="NPC",enderId=22059,rewardNextId=10776,wowhead="https://www.wowhead.com/wotlk/quest=10775",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The gryphon riders must return to Wildhammer Stronghold to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.$B$BWhen you have collected enough tabards, call for a gryphon rider using the Wildhammer flare gun. Prepare yourself for a bit of espionage, $r!",logDesc="Collect 10 Illidari Tabards.$B"} end
if not DB[10776] then DB[10776]={id=10776,zoneId=3520,name="Dissension Amongst the Ranks...",level=70,minLevel=68,giver="Wildhammer Gryphon Rider",giverType="NPC",giverId=22059,ender="Thane Yoregar",enderType="NPC",enderId=21773,wowhead="https://www.wowhead.com/wotlk/quest=10776",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Gnomus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.$B$BTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!",logDesc="Slay 5 Crazed Colossus while in disguise as an agent of Illidan and return to Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley. He will also want his Wildhammer Flare Gun returned.",choiceRewards={{id=31075,qty=1},{id=31077,qty=1},{id=31076,qty=1},{id=31078,qty=1}}} end
if not DB[10777] then DB[10777]={id=10777,zoneId=3520,name="Asghar's Totem",level=69,minLevel=67,giver="Parshah",giverType="NPC",giverId=22024,ender="Parshah",enderType="NPC",enderId=22024,rewardNextId=10778,poiX=-3478,poiY=2278,wowhead="https://www.wowhead.com/wotlk/quest=10777",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="What you read in the commander's journal is true. While the orcish Horde massed under Gul'dan, my people sought to defend ourselves from the threat by striking against him. Gul'dan learned of their intentions and cast a mighty spell that destroyed our camps and twisted the spirits of my brothers.$B$BThey must be stopped before they unleash a greater evil. In the Sketh'lon Wreckage to the north, seek out Asghar and bring me the totem he carries. With it, we can begin to thwart the dark conclave's plans.",logDesc="Bring the Sketh'lon War Totem to Parshah in the Magma Fields."} end
if not DB[10778] then DB[10778]={id=10778,zoneId=3520,name="The Rod of Lianthe",level=69,minLevel=67,giver="Parshah",giverType="NPC",giverId=22024,ender="Parshah",enderType="NPC",enderId=22024,rewardNextId=10780,poiX=-3478,poiY=2278,wowhead="https://www.wowhead.com/wotlk/quest=10778",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The totem alone is not strong enough to counteract the sinister magics of the dark conclave.$B$BWe can combine it with other objects of power, forming a staff to focus the energies. We cannot rescue my brethren from the depths of their depravity, but we can stop them.$B$BOne of the items I need for the staff is the Rod of Lianthe, held by the blood elves at Eclipse Point to the southeast. It is kept in a pavilion on the top tier of the ruins and will be heavily guarded. Use caution, $N.",logDesc="Obtain Lianthe's Key from any of the blood elves at Eclipse Point and use it to open Lianthe's Strongbox and claim the Rod of Lianthe. Return the rod to Parshah in the Magma Fields."} end
if not DB[10779] then DB[10779]={id=10779,zoneId=-261,name="The Hunter's Path",level=10,minLevel=10,rewardNextId=9591,wowhead="https://www.wowhead.com/wotlk/quest=10779",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Huntress Kella Nightbow at LOCATION. She can put you on the path to earning a pet of your own.",logDesc="Speak with Huntress Kella Nightbow at LOCATION."} end
if not DB[10780] then DB[10780]={id=10780,zoneId=3520,name="Sketh'lon Feathers",level=69,minLevel=67,giver="Parshah",giverType="NPC",giverId=22024,ender="Parshah",enderType="NPC",enderId=22024,rewardNextId=10782,poiX=-3478,poiY=2278,wowhead="https://www.wowhead.com/wotlk/quest=10780",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="There is one last element missing from the staff. We must direct the staff's power toward the Dark Conclave spirits.$B$BWe can do that by gathering feathers scattered on the ground at the Sketh'lon Base Camp and using them in the staff. The base camp is to the south, east of Wildhammer Stronghold.$B$BGul'dan's magic utterly destroyed my brethren, leaving only their spirits, but it did not stop there. The magic fed on the spell the arakkoa were preparing, forging a sinister force that engulfed the spirits.",logDesc="Gather 8 Sketh'lon Feathers and bring them to Parshah in the Magma Fields."} end
if not DB[10781] then DB[10781]={id=10781,zoneId=3520,name="Battle of the Crimson Watch",level=70,minLevel=68,ender="A'dal",enderType="NPC",enderId=18481,wowhead="https://www.wowhead.com/wotlk/quest=10781",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="They are probably searching for you on the Path of Conquest as we speak. You must make your escape, $r!$B$BLeave me, I'm done for... They... I think I hear them coming. It's now or never! Get out! If you choose to stay, you will have to fight!$B$BIf you fight and somehow manage to survive, take what you have learned here and deliver that knowledge to A'dal in Shattrath City.",logDesc="Battle the forces of Illidan at Crimson Watch and survive!$B$BReturn to A'dal at Shattrath City should you emerge the victor.",rewards={{id=31408,qty=1}},choiceRewards={{id=31380,qty=1},{id=31381,qty=1},{id=31382,qty=1},{id=31383,qty=1}}} end
if not DB[10782] then DB[10782]={id=10782,zoneId=3520,name="Imbuing the Headpiece",level=69,minLevel=67,giver="Parshah",giverType="NPC",giverId=22024,ender="Parshah",enderType="NPC",enderId=22024,rewardNextId=10808,poiX=-3478,poiY=2278,wowhead="https://www.wowhead.com/wotlk/quest=10782",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The staff is nearly finished!$B$BAll that remains is to imbue the headpiece with power flowing from the echoes of Gul'dan in this accursed place. To the east, near the Fel Pits and south of the Deathforge, is the Altar of Damnation.$B$BThere, fragments of Gul'dan's past are trapped. When you carry the unfinished headpiece of the staff into the area around the altar, don't be surprised if some of the entities react to it. You will be carrying a dangerous object with strong connections to the cataclysm.",logDesc="Equip the Unfinished Headpiece, travel to the Altar of Damnation, and use it while standing near Gul'dan. When the headpiece is energized, return to Parshah in the Magma Fields."} end
if not DB[10783] then DB[10783]={id=10783,zoneId=3522,name="Baron Sablemane",level=67,minLevel=62,giver="3",giverType="NPC",giverId=21984,ender="Baron Sablemane",enderType="NPC",enderId=22103,rewardNextId=10715,poiX=2298,poiY=6034,wowhead="https://www.wowhead.com/wotlk/quest=10783",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Here is my plan. We will poison the ogres and then destroy their gronn master.$b$bDuring my travels in these mountains, I met a man named Baron Sablemane. He is a master of the alchemical arts, and may be convinced to assist us.$b$bYou will find him at the Circle of Blood, down in the canyon to the north of here. Whatever price he requires, I will leave it to your discretion to accept.",logDesc="Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains."} end
if not DB[10784] then DB[10784]={id=10784,zoneId=3522,name="Crush the Bloodmaul Camp",level=67,minLevel=65,giver="Tor'chunk Twoclaws",giverType="NPC",giverId=21147,ender="Tor'chunk Twoclaws",enderType="NPC",enderId=21147,poiX=2296,poiY=6028,wowhead="https://www.wowhead.com/wotlk/quest=10784",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="<Tor'chunk leans in close to whisper.>$B$B$N, you've done us more than proud in the fight against the ogres so far.  And while I have every confidence in what Rexxar has planned, I would still ask that you crush the ogres at Bloodmaul Camp before returning.$B$BThat way we'll be doubly certain of the outcome.$B$BTo get there, head north down the ramp out of Thunderlord.  Then, at the base of the ramp, head west across Dragons' End and north through the Churning Gulch and Daggermaw Canyon.",logDesc="Slay 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks.",choiceRewards={{id=31537,qty=1},{id=31538,qty=1},{id=31539,qty=1},{id=31540,qty=1}}} end
if not DB[10785] then DB[10785]={id=10785,zoneId=3522,name="It's a Trap!",level=67,minLevel=65,giver="Baron Sablemane",giverType="NPC",giverId=22103,ender="3",enderType="NPC",enderId=21984,rewardNextId=10723,poiX=2919,poiY=5957,wowhead="https://www.wowhead.com/wotlk/quest=10785",image="assets/images/quests/placeholder.png",xpDiff=1,desc="There's is no cause of fury greater in this world than that of Gruul and his sons. They slaughtered my people - my children - and now I will have revenge.$B$BI have fashioned a trap from dragon fire, and if you're clever enough, you can use it to kill even a gronn.$B$BJust hurry, take the trap to Rexxar. My thirst for revenge must be quenched.",logDesc="Deliver the Dragonfire Trap to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains."} end
if not DB[10786] then DB[10786]={id=10786,zoneId=3522,name="Slaughter at Boulder'mok",level=68,minLevel=65,giver="Tor'chunk Twoclaws",giverType="NPC",giverId=21147,ender="Tor'chunk Twoclaws",enderType="NPC",enderId=21147,poiX=2296,poiY=6028,wowhead="https://www.wowhead.com/wotlk/quest=10786",image="assets/images/quests/placeholder.png",xpDiff=6,money=78000,desc="I know that Rexxar has plans for you to head to Boulder'mok.  I have something that I want you to do while you are there.$B$BWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!$B$BBoulder'mok lies far to the northwest.  Travel north to Ruuan Weald, and from there head west through the tunnel and past the Raven's Wood.$B$B$N, I want you to kill the Bladespire ogres of Boulder'mok.  Wipe them out!",logDesc="Slay 5 Boulder'mok Brutes and 3 Boulder'mok Shaman, and then return to Tor'chunk Twoclaws at Thunderlord Stronghold in the Blade's Edge Mountains."} end
if not DB[10787] then DB[10787]={id=10787,zoneId=3522,name="[DEPRECATED]<txt><nyi>The Dragons of Dragons' End",level=67,minLevel=65,wowhead="https://www.wowhead.com/wotlk/quest=10787",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We must do something that will infuriate Goc if we're to face him.$B$BAnd now that you've freed &&&,I think I know just what will do!$B$BWhen you are ready,let me know,and I will ask &&& to fly you out to one of the dragon corpses impaled upon the rocks at Dragons' End.$B$BRecover the corpse and bring it back to me here so that we can create something that is sure to bring Goc out of hiding!",logDesc="Rexxar has asked you to speak to him about riding &&& out to Dragons' End to recover a Black Dragon Corpse.  Return to him at Thunderlord Stronghold in the Blade's Edge Mountains when you have it."} end
if not DB[10788] then DB[10788]={id=10788,zoneId=-61,name="Return to Talionia",level=-1,minLevel=10,giver="Carendin Halgar",giverType="NPC",giverId=5675,ender="Talionia",enderType="NPC",enderId=16647,rewardNextId=9529,poiX=1712,poiY=57,wowhead="https://www.wowhead.com/wotlk/quest=10788",image="assets/images/quests/placeholder.png",xpDiff=1,desc="One of your masters, Talionia, in Silvermoon City has sent a summons for you, $n.  I'm certain it is time you learned to summon and control a more powerful demon, so I suggest you see her at once.  I understand Talionia is found in The Sanctum, a cozy little den of evil found along Murder Row.",logDesc="Speak with Talionia in Silvermoon City."} end
if not DB[10789] then DB[10789]={id=10789,zoneId=-61,name="Return to Carendin Halgar",level=-1,minLevel=10,giver="Gan'rul Bloodeye",giverType="NPC",giverId=5875,ender="Carendin Halgar",enderType="NPC",enderId=5675,rewardNextId=1473,poiX=1850,poiY=-4357,wowhead="https://www.wowhead.com/wotlk/quest=10789",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Ah, so there you are, $n.$b$bCarendin Halgar has sent out word for you to come see him in the Magic Quarter of Undercity.  He is not known for his patience, so I would not wait long.",logDesc="Speak with Carendin Halgar in Undercity."} end
if not DB[10790] then DB[10790]={id=10790,zoneId=-61,name="Return to Gan'rul Bloodeye",level=-1,minLevel=10,giver="Carendin Halgar",giverType="NPC",giverId=5675,ender="Gan'rul Bloodeye",enderType="NPC",enderId=5875,rewardNextId=1501,poiX=1712,poiY=57,wowhead="https://www.wowhead.com/wotlk/quest=10790",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You are a long way from home, $r.  Perhaps it is time you returned to learn from your master, Gan'rul Bloodeye.  His knowledge is known to all of our craft, even those of us here.$b$bGan'rul dwells in the Cleft of Shadow in Orgrimmar.",logDesc="Speak with Gan'rul Bloodeye in Orgrimmar."} end
if not DB[10791] then DB[10791]={id=10791,zoneId=3519,name="Welcoming the Wolf Spirit",level=64,minLevel=62,giver="Malukaz",giverType="NPC",giverId=18384,ender="Malukaz",enderType="NPC",enderId=18384,poiX=-2672,poiY=4374,wowhead="https://www.wowhead.com/wotlk/quest=10791",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I've nearly completed the vestments that I'll wear during the ceremony. As I add the finishing touches, I'd like you to set this incense by the candles near the runestone to my left.$B$BI believe it will help us to attract the wolf spirit's attention, since it was made in the days of the orcish clans. I can almost imagine my ancestors using it in a ceremony paying tribute to the wolf spirit after a successful hunt.$B$BOnce you've placed the incense, I'll begin the ceremony.",logDesc="Use the Ceremonial Incense near the candles in Malukaz's hut and observe the ceremony. When the ceremony is complete, speak with Malukaz again.",choiceRewards={{id=25974,qty=1},{id=25977,qty=1},{id=25976,qty=1},{id=25975,qty=1}}} end
if not DB[10792] then DB[10792]={id=10792,zoneId=3483,name="Zeth'Gor Must Burn!",level=61,minLevel=58,giver="Captain Darkhowl",giverType="NPC",giverId=22107,ender="Captain Darkhowl",enderType="NPC",enderId=22107,poiX=-1319,poiY=2378,wowhead="https://www.wowhead.com/wotlk/quest=10792",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="The Bleeding Hollow clan have betrayed their noble heritage!  We, the orcs who fought and died to save ourselves from the fel taint of Mannoroth, look upon our vile cousins and see only weakness and ignobility... and for that, they must burn!$B$BEnter Zeth'Gor, their bastion to the east, and burn their buildings.  Kill peons for their torches, ignite them at their forge, and hurl the burning torches at their hovels, their stable and their barracks.  Burn them all, and then return to me!$B$BFor the Horde!",logDesc="Kill Bleeding Hollow Peons for their torches, ignite them at Zeth'Gor's forge then throw the burning torches at Zeth'Gor Buildings.",choiceRewards={{id=27732,qty=1},{id=27731,qty=1}}} end
if not DB[10793] then DB[10793]={id=10793,zoneId=3520,name="The Journal of Val'zareq: Portends of War",level=70,minLevel=68,rewardNextId=10781,wowhead="https://www.wowhead.com/wotlk/quest=10793",image="assets/images/quests/placeholder.png",xpDiff=4,desc="This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.$B$BThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.",logDesc="Locate Marcus Auralion, High General of the Sha'tar, at Crimson Watch.$B$BLook for him inside a crystalline prison."} end
if not DB[10794] then DB[10794]={id=10794,zoneId=-162,name="Rogues of the Shattered Hand",level=24,minLevel=20,giver="Zelanis",giverType="NPC",giverId=16684,ender="Shenthul",enderType="NPC",enderId=3401,rewardNextId=2460,poiX=9733,poiY=-7366,wowhead="https://www.wowhead.com/wotlk/quest=10794",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N, there are secrets in the world that we do not yet possess.  The Shattered Hand in Orgrimmar can lead you to one of these secrets: the method for brewing deadly poisons.  Do as they ask and you will gain their trust.$b$bTo reach Orgrimmar, take the portal in Silvermoon City to Undercity.  Then, travel outside the city and find the nearby tower where the goblin Zepplins pick up their passengers.  From there, fly to the city of Orgrimmar where you can find Shenthul in the Cleft of Shadow.",logDesc="Speak with Shenthul in Orgrimmar."} end
if not DB[10795] then DB[10795]={id=10795,zoneId=3522,name="A Date with Dorgok",level=67,minLevel=65,giver="Commander Haephus Stonewall",giverType="NPC",giverId=22149,ender="Commander Haephus Stonewall",enderType="NPC",enderId=22149,poiX=3035,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10795",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="Good, I've seen you around and I've been meaning to speak to you about a matter of some importance.$B$BThere are reports coming in that for some reason the Bloodmaul ogres are planning an offensive against Sylvanaar and Ruuan Weald.  We don't know who or what is pushing them to do this, but I intend to nip their plan in the bud!$B$BBloodmaul Camp is where the attacks are to be staged from.  Head northwest down the ramp out of the Ruuan Weald and you will find it.  I want you to kill their leader, Dorgok!",logDesc="Slay Dorgok at Bloodmaul Camp."} end
if not DB[10796] then DB[10796]={id=10796,zoneId=3522,name="Crush the Bloodmaul Camp!",level=67,minLevel=65,giver="Lieutenant Fairweather",giverType="NPC",giverId=22150,ender="Lieutenant Fairweather",enderType="NPC",enderId=22150,poiX=3036,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10796",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="I've heard that you've done us more than proud in the fight against the ogres thus far.  Now, I would ask that you face them again.  I want you to crush the ogres at Bloodmaul Camp!$B$BTo get down there, head northwest down the ramp out of the Ruuan Weald.  You'll find them at the base of the ramp.$B$BGood luck, $c!",logDesc="Slay 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks.",choiceRewards={{id=31537,qty=1},{id=31538,qty=1},{id=31539,qty=1},{id=31540,qty=1}}} end
if not DB[10797] then DB[10797]={id=10797,zoneId=3522,name="Favor of the Gronn",level=67,minLevel=65,ender="Commander Haephus Stonewall",enderType="NPC",enderId=22149,rewardNextId=10798,wowhead="https://www.wowhead.com/wotlk/quest=10797",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A token in the form of a small statuette falls from Dorgok's dead clutch.  It bears a striking resemblance to one of the gronn.$B$BSurely, Commander Haephus Stonewall at Evergrove in the Ruuan Weald, up the ramp to the east, would be interested in this!",logDesc="Deliver Gorgrom's Favor to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains."} end
if not DB[10798] then DB[10798]={id=10798,zoneId=3522,name="Pay the Baron a Visit",level=67,minLevel=65,giver="Commander Haephus Stonewall",giverType="NPC",giverId=22149,ender="Baron Sablemane",enderType="NPC",enderId=22103,rewardNextId=10799,poiX=3035,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10798",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This is bad news.  Gorgrom the Dragon-Eater is behind the recent Bloodmaul plans against Sylvanaar!$B$BWhy he's manipulating them, and not just using the Bladespire, I don't know.  But if we're to deal with a gronn, we're going to need help.$B$BI know a man who is wise in the ways of all sorts of exotic magics.  Baron Sablemane is his name, and you can find him at the Circle of Blood, back down the ramp to the northwest, and then southwest through the canyon.$B$BAsk him to fashion us a trap for the gronn.",logDesc="Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains."} end
if not DB[10799] then DB[10799]={id=10799,zoneId=3522,name="Into the Churning Gulch",level=67,minLevel=65,giver="Baron Sablemane",giverType="NPC",giverId=22103,ender="Baron Sablemane",enderType="NPC",enderId=22103,rewardNextId=10800,poiX=2919,poiY=5957,wowhead="https://www.wowhead.com/wotlk/quest=10799",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="Very well, I'll create this trap, but first I want something in return.$B$BThere happens to be a nearby gronn that is in possession of an item that I want, but you can't face him, not yet anyway.$B$BSo, you and I are going to fashion a sleeping powder from the poison of the nearby crust bursters.$B$BYou'll find them in the Churning Gulch to the southwest.  Bring me a number of their glands, and be quick about it!",logDesc="Collect 7 Crust Burster Venom Glands.",rewards={{id=31535,qty=5}}} end
if not DB[10800] then DB[10800]={id=10800,zoneId=3522,name="Goodnight, Gronn",level=67,minLevel=65,giver="Baron Sablemane",giverType="NPC",giverId=22103,ender="Baron Sablemane",enderType="NPC",enderId=22103,rewardNextId=10801,poiX=2919,poiY=5957,wowhead="https://www.wowhead.com/wotlk/quest=10800",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="I've outdone myself again.  I've fashioned a sleeping powder for you to use on Grulloc, the gronn I spoke of who is guarding what I want.$B$BGrulloc keeps himself at the Cursed Hollow, an area at the eastern edge of Dragons' End on the other side of the Circle of Blood.$B$BIf I were you, I wouldn't tarry long once you have his sack.  The effects of the dust won't last long.",logDesc="Collect Grulloc's Sack."} end
if not DB[10801] then DB[10801]={id=10801,zoneId=3522,name="It's a Trap!",level=67,minLevel=65,giver="Baron Sablemane",giverType="NPC",giverId=22103,ender="Commander Haephus Stonewall",enderType="NPC",enderId=22149,rewardNextId=10802,poiX=2919,poiY=5957,wowhead="https://www.wowhead.com/wotlk/quest=10801",image="assets/images/quests/placeholder.png",xpDiff=1,desc="There's nothing more that I hate in this world than the sons of Gruul and their father!  They slaughtered my people, and my children, and now I will have a taste of revenge!$B$BI have fashioned a trap from some dragon fire, and if you're clever enough, you might just be able to use it to kill a gronn.$B$BI'm sure that you have a particular gronn in mind; it matters not to me which one you kill.  Just hurry, take the trap to your Commander Stonewall.$B$BMy thirst for revenge must be quenched!",logDesc="Deliver the Dragonfire Trap to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains."} end
if not DB[10802] then DB[10802]={id=10802,zoneId=3522,name="Gorgrom the Dragon-Eater",level=68,minLevel=65,giver="Commander Haephus Stonewall",giverType="NPC",giverId=22149,ender="Commander Haephus Stonewall",enderType="NPC",enderId=22149,rewardNextId=10818,poiX=3035,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10802",image="assets/images/quests/placeholder.png",xpDiff=6,money=78000,desc="We must show the ogres that we are not to be trifled with. We must send a message.$b$bTravel to Boulder'mok and kill the ogres there. Make sure you keep their heads.$b$bThen go to Gorgrom's altar and place the trap there for him. Gorgrom will appear, and you must lure him into the trap. When he is dead, mount your grisly totems near his corpse, so that the ogres may look at their fallen master and their fallen brothers, and know the price for seeking to destroy us.",logDesc="Collect 3 Grisly Totems from Boulder'mok ogres. Then, use Sablemane's Trap at Gorgrom's Altar to summon and kill Gorgrom the Dragon-Eater.$b$bWhen Gorgrom is dead, place the 3 Grisly Totems near his corpse.",choiceRewards={{id=31542,qty=1},{id=31541,qty=1},{id=31543,qty=1}}} end
if not DB[10803] then DB[10803]={id=10803,zoneId=3522,name="Slaughter at Boulder'mok",level=68,minLevel=65,giver="Lieutenant Fairweather",giverType="NPC",giverId=22150,ender="Lieutenant Fairweather",enderType="NPC",enderId=22150,poiX=3036,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10803",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="I know that we have plans for you to head to Boulder'mok. I have something that I want you to do while you are there.$B$BWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!$B$BBoulder'mok lies to the west. Travel southwest, cross the bridge and head through the tunnel. On the west side of the Raven's Wood you will find them.$B$B$N, I want you to wipe out the Bladespire ogres of Boulder'mok.",logDesc="Slaughter 5 Boulder'mok Brutes and 3 Boulder'mok Shaman."} end
if not DB[10804] then DB[10804]={id=10804,zoneId=3520,name="Kindness",level=70,minLevel=70,giver="Mordenai",giverType="NPC",giverId=22113,ender="Mordenai",enderType="NPC",enderId=22113,rewardNextId=10811,poiX=-4129,poiY=762,wowhead="https://www.wowhead.com/wotlk/quest=10804",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Something has them spooked, $r.$B$B<Mordenai points to the nether drakes flying overhead.>$B$BThey won't even come down to feed. I have seen several fall to the earth, dead from exhaustion before their bodies hit the ground.$B$BWe must save them! The Rocknail flayers that are found near the crystals are their natural prey. Kill flayers and take their carcasses. Place a carcass in the field and stand extremely still. As long as you do not make any aggressive motions, they will not attack you.",logDesc="Mordenai at Netherwing Fields in Shadowmoon Valley wants you to feed 8 Mature Netherwing Drakes."} end
if not DB[10805] then DB[10805]={id=10805,zoneId=3522,name="Massacre at Gruul's Lair",level=67,minLevel=65,giver="Baron Sablemane",giverType="NPC",giverId=22103,ender="Baron Sablemane",enderType="NPC",enderId=22103,rewardNextId=10806,poiX=2919,poiY=5957,wowhead="https://www.wowhead.com/wotlk/quest=10805",image="assets/images/quests/placeholder.png",xpDiff=6,money=74000,desc="You've proven yourself resourceful, and now I think I'm going to put you to personal use in my own fight against Gruul and his sons.$B$BThe Bladespire clan are the favored of the gronn, and while you may have thinned out their numbers elsewhere, you haven't yet dealt with their strongest.$B$BGruul protects the exterior of his lair with only the toughest of ogres, and it is those that you must kill.  Head north through the Daggermaw Canyon and you will find Gruul's Lair at the end.",logDesc="Slay 10 Bladespire Enforcers, 5 Bladespire Battlemages, 5 Bladespire Ravagers and their leader, Fingrom."} end
if not DB[10806] then DB[10806]={id=10806,zoneId=3522,name="Showdown",level=70,minLevel=65,giver="Baron Sablemane",giverType="NPC",giverId=22103,ender="Baron Sablemane",enderType="NPC",enderId=22103,poiX=2919,poiY=5957,wowhead="https://www.wowhead.com/wotlk/quest=10806",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="The time has come for us to face Goc, the master of the Bladespire ogres. It is also time that I take a hand in events, to see the last of the gronn's life.$b$bTake my signet ring. When you come to the Altar of Goc, use it, and I will come to join you.$b$bTogether we will destroy Goc.",logDesc="Use Sablemane's Signet at the Altar of Goc, then kill Goc.",choiceRewards={{id=31546,qty=1},{id=31544,qty=1},{id=31545,qty=1},{id=31547,qty=1},{id=31549,qty=1},{id=31548,qty=1}}} end
if not DB[10807] then DB[10807]={id=10807,zoneId=3520,name="The Ashtongue Broken",level=70,minLevel=68,giver="Varen the Reclaimer",giverType="NPC",giverId=21953,ender="Varen the Reclaimer",enderType="NPC",enderId=21953,rewardNextId=10817,poiX=-4082,poiY=1215,wowhead="https://www.wowhead.com/wotlk/quest=10807",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Ashtongue tribe is feared among all Broken.  It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself.  They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, to the north.  Go there and put a dent in their numbers before they get a chance to mount an attack on us.",logDesc="Varen the Reclaimer wants you to go to the Ruins of Baa'ri and slay 3 Ashtongue Handlers, 4 Ashtongue Warriors and 6 Ashtongue Shaman.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease."} end
if not DB[10808] then DB[10808]={id=10808,zoneId=3520,name="Thwart the Dark Conclave",level=69,minLevel=67,giver="Parshah",giverType="NPC",giverId=22024,ender="Parshah",enderType="NPC",enderId=22024,poiX=-3478,poiY=2278,wowhead="https://www.wowhead.com/wotlk/quest=10808",image="assets/images/quests/placeholder.png",xpDiff=6,money=41000,desc="The spirits of the dark conclave seek to summon an ancient and powerful evil through a ritual conducted at the lava pits to the south of the Sketh'lon Base Camp.$B$BGul'dan's magic mingled with their own, empowering them to aid this creature in manifesting in our world! We must not allow this to happen, $N. The death and destruction it would bring are unimaginable!$B$BCarry the staff with you to the site of the summoning and use its magics to stop the dark conclave once and for all!",logDesc="Slay the Dark Conclave Ritualists and use the Staff of Parshah to end the Dark Conclave's summoning ritual, then return to Parshah in the Magma Fields.",choiceRewards={{id=30941,qty=1},{id=30955,qty=1},{id=30960,qty=1},{id=30928,qty=1}}} end
if not DB[10809] then DB[10809]={id=10809,zoneId=3483,name="Wanted: Worg Master Kruush",level=60,minLevel=58,ender="Captain Darkhowl",enderType="NPC",enderId=22107,wowhead="https://www.wowhead.com/wotlk/quest=10809",image="assets/images/quests/placeholder.png",xpDiff=5,money=18000,desc="The poster reads:$B$B\"Worg Master Kruush leads the worg riders of the Bleeding Hollow clan.  A price has been placed on his head, for his riders exact heavy tolls on supply trains to Spinebreaker Post.\"$B$B\"Scouts report him within Zeth'Gor, and the hero able to bring the severed head of this villain to me will earn the thanks of the Horde, and a large bounty.\"$B$B\"-Captain Darkhowl\"",logDesc="Kill Worg Master Kruush and bring his head to Captain Darkhowl in Spinebreaker Post."} end
if not DB[10810] then DB[10810]={id=10810,zoneId=3522,name="Damaged Mask",level=68,minLevel=65,ender="O'Mally Zapnabber",enderType="NPC",enderId=22020,rewardNextId=10812,wowhead="https://www.wowhead.com/wotlk/quest=10810",image="assets/images/quests/placeholder.png",xpDiff=2,money=10000,desc="As you examine the damaged mask, you hear strange sounds coming from within. If the mask wasn't damaged you might be able to hear the sounds more clearly.$B$BO'Mally Zapnabber in Ruuan Weald might be able to fix the mask.",logDesc="Deliver the Damaged Mask to O'Mally Zapnabber at Evergrove in the Blade's Edge Mountains."} end
if not DB[10811] then DB[10811]={id=10811,zoneId=3520,name="Seek Out Neltharaku",level=70,minLevel=70,giver="Mordenai",giverType="NPC",giverId=22113,ender="3",enderType="NPC",enderId=21657,rewardNextId=10814,poiX=-4129,poiY=762,wowhead="https://www.wowhead.com/wotlk/quest=10811",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Their patron soars high above, $N. Perhaps the kindness that you showed his children has moved his heart. Seek Neltharaku out and enlist his aid. Together, you may be able to solve the plight of the Netherwing drakes.$B$B<Mordenai points to the sky.>$B$BFly high, friend...",logDesc="Seek out Neltharaku, patron of the Netherwing Dragonflight."} end
if not DB[10812] then DB[10812]={id=10812,zoneId=3522,name="Mystery Mask",level=68,minLevel=65,giver="O'Mally Zapnabber",giverType="NPC",giverId=22020,ender="Wildlord Antelarion",enderType="NPC",enderId=22127,rewardNextId=10819,poiX=2948,poiY=5447,wowhead="https://www.wowhead.com/wotlk/quest=10812",image="assets/images/quests/placeholder.png",xpDiff=2,money=10000,desc="Ok, it should work now. What is it, you ask? Why, it's a communication device - it allows those blockheads to communicate with each other. You know, the Burning Legion! I would suggest that you hand this mask to Wildlord Antelarion. He's over there pacing around. Always moving, he is.$B$BWell get moving, he's been trying to get his hands on one of these for sometime now.",logDesc="Deliver the Mystery Mask to Wildlord Antelarion at Evergrove in the Blade's Edge Mountains."} end
if not DB[10813] then DB[10813]={id=10813,zoneId=3483,name="The Eyes of Grillok",level=62,minLevel=58,giver="Zezzak",giverType="NPC",giverId=22231,ender="Zezzak",enderType="NPC",enderId=22231,rewardNextId=10834,poiX=-1338,poiY=2355,wowhead="https://www.wowhead.com/wotlk/quest=10813",image="assets/images/quests/placeholder.png",xpDiff=3,money=14000,desc="$n, you have braved the lair of the Bleeding Hollow orcs, dreaded Zeth'Gor, and survived!  Perhaps you have the strength to aid me, for I aim to gaze into the mind of its darkest witch, Grillok!$B$BTake this shard.  Use it to ensorcel an Eye of Grillok and bind it to yourself.  Return here and approach my cauldron... and it will pull the eye from you.$B$BGo, $N.  And use care -- An Eye of Grillok will betray you to our enemies if given the slightest opening!",logDesc="Use Zezzak's Shard to capture an Eye of Grillok, then approach Zezzak's cauldron to extract it.  After it is removed, return Zezzak's Shard to him."} end
if not DB[10814] then DB[10814]={id=10814,zoneId=3520,name="Neltharaku's Tale",level=70,minLevel=70,giver="3",giverType="NPC",giverId=21657,ender="3",enderType="NPC",enderId=21657,rewardNextId=10836,poiX=-4147,poiY=853,wowhead="https://www.wowhead.com/wotlk/quest=10814",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I have information that you may find useful. Please listen to what I have to tell you, $r.",logDesc="Speak with Neltharaku and listen to his story."} end
if not DB[10815] then DB[10815]={id=10815,zoneId=3520,name="The Journal of Val'zareq: Portends of War",level=70,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=10815",image="assets/images/quests/placeholder.png",xpDiff=4,desc="This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.$B$BThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.",logDesc="Locate Marcus Auralion, High General of the Sha'tar, at Crimson Watch."} end
if not DB[10816] then DB[10816]={id=10816,zoneId=3520,name="Reclaiming Holy Grounds",level=70,minLevel=68,giver="Vindicator Aluumen",giverType="NPC",giverId=21822,ender="Vindicator Aluumen",enderType="NPC",enderId=21822,poiX=-3017,poiY=861,wowhead="https://www.wowhead.com/wotlk/quest=10816",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="You did well against the Broken in Baa'ri, $N.  Let's see how well you do against Illidan's most feared army.$B$BThe fel orcs of the Shadowmoon Clan occupy the Ata'mal Terrace, once a very holy site where ata'mal crystals were used in spiritual ceremonies.$B$BWe had reason to believe they were hiding an actual ata'mal crystal in the vicinity, but our scrying has revealed nothing.  Nevertheless, the fel orcs are on draenei holy ground and their presence must be dealt with.",logDesc="Vindicator Aluumen wants you to slay 8 Shadowmoon Slayers, 8 Shadowmoon Chosen and 4 Shadowmoon Darkweavers.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease.",choiceRewards={{id=30940,qty=1},{id=30961,qty=1},{id=30922,qty=1},{id=30958,qty=1}}} end
if not DB[10817] then DB[10817]={id=10817,zoneId=3520,name="The Great Retribution",level=70,minLevel=68,giver="Varen the Reclaimer",giverType="NPC",giverId=21953,ender="Varen the Reclaimer",enderType="NPC",enderId=21953,poiX=-4082,poiY=1215,wowhead="https://www.wowhead.com/wotlk/quest=10817",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="You did well against the Ashtongue Broken, $N.  I have another challenge for you, should you be up to it.$B$BNot too long ago, the Sanctum of the Stars suffered a tremendous attack by Illidan's fel orcs.$B$BWe've determined it was perpetrated by the Shadowmoon orcs who occupy the Ata'mal Terrace.$B$BShow them that the Scryers are not to be trifled with.",logDesc="Varen the Reclaimer wants you to slay 8 Shadowmoon Slayers, 8 Shadowmoon Chosen and 4 Shadowmoon Darkweavers.$B$BCompleting quests for the Scryers will cause your Aldor reputation level to decrease.",choiceRewards={{id=30940,qty=1},{id=30961,qty=1},{id=30922,qty=1},{id=30958,qty=1}}} end
if not DB[10818] then DB[10818]={id=10818,zoneId=3522,name="Baron Sablemane Has Requested Your Presence",level=67,minLevel=65,giver="Commander Haephus Stonewall",giverType="NPC",giverId=22149,ender="Baron Sablemane",enderType="NPC",enderId=22103,rewardNextId=10805,poiX=3035,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10818",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$N, while you were out being one hell of a $c, Baron Sablemane sent his pet dragon up here with a message.$B$BHe's asked for you personally.  From what I understand, he wants you to head up his own fight against the gronn.$B$BI guess you're the most qualified person in all of Outland to help him, but if I were you, I'd get in contact with a couple of friends first and ask them to join you at the Circle of Blood.",logDesc="Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains."} end
if not DB[10819] then DB[10819]={id=10819,zoneId=3522,name="Felsworn Gas Mask",level=68,minLevel=65,giver="Wildlord Antelarion",giverType="NPC",giverId=22127,rewardNextId=10820,poiX=2960,poiY=5465,wowhead="https://www.wowhead.com/wotlk/quest=10819",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I have a very special mission for you, $N. I need you to infiltrate Forge Camp: Anger east of here. When you enter the camp you will need to wear the Felsworn gas mask and locate the Legion communicator. Once you have located the communication device speak with whomever is on the other side of the device.$B$BIf all works out you can trick the demon into something devious! Try telling the demon that Camp Anger has revolted.$B$BGood luck to you $C.",logDesc="Wear the Felsworn Gas Mask and use the Legion Communicator at Forge Camp: Anger in the Blade's Edge Mountains."} end
if not DB[10820] then DB[10820]={id=10820,zoneId=3522,name="Deceive thy Enemy",level=68,minLevel=65,rewardNextId=10821,wowhead="https://www.wowhead.com/wotlk/quest=10820",image="assets/images/quests/placeholder.png",xpDiff=4,desc="For every moment I hear silence, you draw closer to your death! SPEAK!$B$BWhat? The camp has revolted? This cannot possibly be true! My minions would not dare undermine my authority.$B$BWell then, every last one of them will pay for this treachery, they will pay dearly. Silence them all and be done with it! Report back to me once you have carried out my order or you shall be dealt with.",logDesc="Slay 4 Doomforge Attendants and 4 Doomforge Engineers."} end
if not DB[10821] then DB[10821]={id=10821,zoneId=3522,name="You're Fired!",level=68,minLevel=65,ender="Wildlord Antelarion",enderType="NPC",enderId=22127,rewardNextId=10910,wowhead="https://www.wowhead.com/wotlk/quest=10821",image="assets/images/quests/placeholder.png",xpDiff=5,money=78000,desc="Doomcryer did nothing to stop the revolt? How dare she! She has been trying to undermine my authority for some time. However, this time will be her last. You must summon her and deal with her personally.$B$BHer anger guards hold the keys that summon her to Forge Camp: Anger. Retrieve the five keys and activate the five Legion obelisks. The obelisks have a short duration, so make sure they are all activated at the same time. Remember, the anger guards carry more keys.",logDesc="Slay Doomcryer.",choiceRewards={{id=31793,qty=1},{id=31792,qty=1},{id=31790,qty=1},{id=31791,qty=1}}} end
if not DB[10822] then DB[10822]={id=10822,zoneId=3703,name="Single Sunfury Signet",level=70,minLevel=68,giver="Battlemage Vyara",giverType="NPC",giverId=22211,ender="Battlemage Vyara",enderType="NPC",enderId=22211,poiX=-4104,poiY=1129,wowhead="https://www.wowhead.com/wotlk/quest=10822",image="assets/images/quests/placeholder.png"} end
if not DB[10823] then DB[10823]={id=10823,zoneId=3520,name="More Sunfury Signets",level=70,minLevel=68,giver="Battlemage Vyara",giverType="NPC",giverId=22211,ender="Battlemage Vyara",enderType="NPC",enderId=22211,poiX=-4104,poiY=1129,wowhead="https://www.wowhead.com/wotlk/quest=10823",image="assets/images/quests/placeholder.png"} end
if not DB[10824] then DB[10824]={id=10824,zoneId=3520,name="Sunfury Signets",level=70,minLevel=68,giver="Battlemage Vyara",giverType="NPC",giverId=22211,ender="Battlemage Vyara",enderType="NPC",enderId=22211,poiX=-4104,poiY=1129,wowhead="https://www.wowhead.com/wotlk/quest=10824",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The survival of the Scryers hinges on outrecruiting Kael'thas.  Every pilgrim from Quel'Thalas that joins his side brings him closer to victory.  The opposite is true for us.$B$BSoon, however, we will run out of recruits and it will come down to what side can kill the other quicker.  Prove your worth to the Scryers by bringing me Sunfury signets worn by  high-ranking blood elves allied with Kael'thas and Illidan.  You'll find them at Eclipse Point to the west and the Ruins of Karabor, to the northeast.",logDesc="Battlemage Vyara at the Sanctum of the Stars wants you to bring her 10 Sunfury Signets.$B$BPerforming quests for the Scryers will cause you Aldor reputation level to decrease."} end
if not DB[10825] then DB[10825]={id=10825,zoneId=3522,name="The Truth Unorbed",level=68,minLevel=65,ender="Tree Warden Chawn",enderType="NPC",enderId=22007,wowhead="https://www.wowhead.com/wotlk/quest=10825",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This strange, magical orb drops from beneath the contour feathers of the arakkoa.$B$BSuffused with an eerie, purple glow, the orb pulses to an unheard beat.  Holding it makes you mildly uncomfortable, and so you quickly place it within your pack.$B$BPerhaps Tree Warden Chawn at Ruuan Weald to the west, through the tunnel and across the Wyrmskull Bridge, would be interested in examining it?",logDesc="Deliver the Orb of the Grishna to Tree Warden Chawn at Evergrove in the Blade's Edge Mountains."} end
if not DB[10826] then DB[10826]={id=10826,zoneId=3703,name="Marks of Sargeras",level=70,minLevel=68,giver="Harbinger Saronen",giverType="NPC",giverId=22214,ender="Harbinger Saronen",enderType="NPC",enderId=22214,poiX=-3040,poiY=800,wowhead="https://www.wowhead.com/wotlk/quest=10826",image="assets/images/quests/placeholder.png",xpDiff=5,desc="By now it should be clear to you why we oppose the Burning Legion and those who serve them.$B$BIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers.  Here in Shadowmoon you will find a strong Legion presence to the far west in Legion Hold and the Deathforge.",logDesc="Bring 10 Marks of Sargeras to Harbinger Saronen in Shadowmoon Valley.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease."} end
if not DB[10827] then DB[10827]={id=10827,zoneId=3703,name="More Marks of Sargeras",level=70,minLevel=68,giver="Harbinger Saronen",giverType="NPC",giverId=22214,ender="Harbinger Saronen",enderType="NPC",enderId=22214,poiX=-3040,poiY=800,wowhead="https://www.wowhead.com/wotlk/quest=10827",image="assets/images/quests/placeholder.png"} end
if not DB[10828] then DB[10828]={id=10828,zoneId=3703,name="Single Mark of Sargeras",level=70,minLevel=68,giver="Harbinger Saronen",giverType="NPC",giverId=22214,ender="Harbinger Saronen",enderType="NPC",enderId=22214,poiX=-3040,poiY=800,wowhead="https://www.wowhead.com/wotlk/quest=10828",image="assets/images/quests/placeholder.png"} end
if not DB[10829] then DB[10829]={id=10829,zoneId=3522,name="Treebole Must Know",level=68,minLevel=65,giver="Tree Warden Chawn",giverType="NPC",giverId=22007,ender="Treebole",enderType="NPC",enderId=22215,rewardNextId=10830,poiX=2981,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10829",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This is troubling!  The arakkoa are causing the ancients and protectors to become possessed by evil spirits!$B$BBut, there is one ancient that could not possibly have been affected.  His name is Treebole, and you must go to him at once if we're to save the trees of the Raven's Wood!$B$BGo back to the Raven's Wood.  You will find him at the fork in the path just past Grishnath.",logDesc="Speak with Treebole, an ancient of lore who lives in the Raven's Wood of the Blade's Edge Mountains."} end
if not DB[10830] then DB[10830]={id=10830,zoneId=3522,name="Exorcising the Trees",level=68,minLevel=65,giver="Treebole",giverType="NPC",giverId=22215,ender="Treebole",enderType="NPC",enderId=22215,poiX=3609,poiY=6830,wowhead="https://www.wowhead.com/wotlk/quest=10830",image="assets/images/quests/placeholder.png",xpDiff=6,money=78000,desc="The Grishna have caused the leafbeards and stonebarks to be inhabited by evil koi-koi spirits.$B$BWe must save the trees or soon all of the Raven's Wood will be lost forever!$B$BCombine the magic of a Grishnath orb, found throughout Grishnath, with a dire pinfeather from a dire raven.$B$BUse the resultant exorcism feather to draw out and slay the koi-koi spirit as quickly as possible.  The stonebarks are too powerful for this ritual, but if enough leafbeards are saved, they will be freed as well.",logDesc="Collect 5 Grishnath Orbs and 5 Dire Pinfeathers and then combine them into Exorcism Feathers.  Use these feathers to exorcise and slay 5 Koi-Koi Spirits from the Raven's Wood Leafbeards.",choiceRewards={{id=31526,qty=1},{id=31527,qty=1},{id=31523,qty=1},{id=31528,qty=1}}} end
if not DB[10831] then DB[10831]={id=10831,zoneId=-264,name="Becoming a Mooncloth Tailor",level=70,minLevel=60,giver="Nasmara Moonsong",giverType="NPC",giverId=22208,ender="Nasmara Moonsong",enderType="NPC",enderId=22208,poiX=-2078,poiY=5266,wowhead="https://www.wowhead.com/wotlk/quest=10831",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I can teach you the ways of mooncloth tailoring, if you are interested.. By specializing in mooncloth tailoring, creating primal mooncloth will yield twice the normal amount and you will have access to several exclusive patterns. All that is required is that you pass a simple test.$B$BAs to the test, your task is to create a small sample of primal mooncloth in the moonwell at Cenarion Refuge. I will provide all the materials you'll need. When you've created the sample, bring it back to me for examination.",logDesc="Use the Square of Imbued Netherweave while standing in Cenarion Refuge's moonwell to create a Sample of Primal Mooncloth. Bring the completed sample back to Nasmara Moonsong in Shattrath's Lower City.$B$B*WARNING!* You can only select one tailoring specialization."} end
if not DB[10832] then DB[10832]={id=10832,zoneId=-264,name="Becoming a Spellfire Tailor",level=70,minLevel=60,giver="Gidge Spellweaver",giverType="NPC",giverId=22213,ender="Gidge Spellweaver",enderType="NPC",enderId=22213,poiX=-2073,poiY=5262,wowhead="https://www.wowhead.com/wotlk/quest=10832",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I can teach you the ways of spellfire tailoring if you wish, but be warned, it's a dangerous pursuit.$B$BCreating spellcloth in Netherstorm attracts powerful nether-wraiths. I'm searching for a way to lessen backlash, but I need more nether-wraith essence for my research.$B$BTake this beacon with you to Netherstorm and use it to summon a nether-wraith. Bring back its essence and I'll agree to teach you. As a spellfire tailor, you'll receive twice as much cloth and have access to exclusive patterns.",logDesc="Bring a sample of Nether-wraith Essence to Gidge Spellweaver in Shattrath's Lower City.$B$B*WARNING!* You can only select one tailoring specialization."} end
if not DB[10833] then DB[10833]={id=10833,zoneId=-264,name="Becoming a Shadoweave Tailor",level=70,minLevel=60,giver="Andrion Darkspinner",giverType="NPC",giverId=22212,ender="Andrion Darkspinner",enderType="NPC",enderId=22212,poiX=-2067,poiY=5263,wowhead="https://www.wowhead.com/wotlk/quest=10833",image="assets/images/quests/placeholder.png",xpDiff=4,desc="If you become a shadoweave specialist, you will make twice as much shadowcloth as an average tailor and have access to several exclusive patterns.$B$BOf course, any tailor can use the Altar of Shadows, but a shadoweave tailor possesses a deeper attunement to the altar, unlocking powers that few can fathom.$B$BTake this crystal to eastern Shadowmoon Valley, and find Netherwing Pass leading south from the Netherwing Fields. Near the world's edge, you will find the Altar of Shadows. Use the crystal there.",logDesc="Use the Crystal of Deep Shadows near the Altar of Shadows to deepen your attunement to the altar, then return to Andrion Darkspinner in Shattrath's Lower City.$B$B*WARNING!* You can only select one tailoring specialization."} end
if not DB[10834] then DB[10834]={id=10834,zoneId=3483,name="Grillok \"Darkeye\"",level=62,minLevel=58,giver="Zezzak",giverType="NPC",giverId=22231,ender="Zezzak",enderType="NPC",enderId=22231,poiX=-1338,poiY=2355,wowhead="https://www.wowhead.com/wotlk/quest=10834",image="assets/images/quests/placeholder.png",xpDiff=6,money=54000,desc="Grillok Darkeye has wagered a piece of himself to dark powers, and gained great magic for it.  His lost eye burns deep in some hellish pit, now a demon's trinket... and the patch that covers his betrayal holds its own dark secrets.$B$BBring me Grillok's eyepatch, $N, and I will reward you greatly for your service...",logDesc="Kill Grillok Darkeye and bring Grillok's Eyepatch to Zezzak in Spinebreaker Post.",choiceRewards={{id=28057,qty=1},{id=28052,qty=1},{id=28050,qty=1},{id=28055,qty=1},{id=28051,qty=1}}} end
if not DB[10835] then DB[10835]={id=10835,zoneId=3483,name="Apothecary Antonivich",level=61,minLevel=58,giver="Apothecary Albreck",giverType="NPC",giverId=21279,ender="Apothecary Antonivich",enderType="NPC",enderId=16588,rewardNextId=10864,poiX=-1335,poiY=2382,wowhead="https://www.wowhead.com/wotlk/quest=10835",image="assets/images/quests/placeholder.png",xpDiff=2,money=5200,desc="$n, I have prepared a preliminary report of my findings regarding the Bleeding Hollow orcs.  My colleague in Thrallmar, Apothecary Antonivich, will be happy to receive them.  He too studies the phenomenon of fel orcs... in hopes of preventing such a tragedy from again befalling our orcish allies.$B$BTake him this report, and I will continue my study of the blood you brought me.  If fortune is with us, we will isolate the cause of the fel orc affliction.",logDesc="Bring Albreck's Findings to Apothecary Antonivich at Thrallmar in Hellfire Peninsula."} end
if not DB[10836] then DB[10836]={id=10836,zoneId=3520,name="Infiltrating Dragonmaw Fortress",level=70,minLevel=70,giver="3",giverType="NPC",giverId=21657,ender="3",enderType="NPC",enderId=21657,rewardNextId=10837,poiX=-4147,poiY=853,wowhead="https://www.wowhead.com/wotlk/quest=10836",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I require time so that I may devise a plan to save my children and mate. You will buy me this time, mortal.$B$BVenture into Dragonmaw Fortress, located on the eastern edge of the Netherwing Fields, and lay waste to all Dragonmaw orcs that you find. The ensuing chaos and confusion should have a considerable impact on their plans.$B$BBe warned, some of my kin are too far gone - their minds corrupted by the Dragonmaw. For them, the only resolution is death. You have my permission to end their lives as well.",logDesc="Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to slay 15 Dragonmaw Orcs.$B$BAny Dragonmaw Orc in Dragonmaw Fortress will suffice."} end
if not DB[10837] then DB[10837]={id=10837,zoneId=3520,name="To Netherwing Ledge!",level=70,minLevel=70,giver="3",giverType="NPC",giverId=21657,ender="3",enderType="NPC",enderId=21657,rewardNextId=10854,poiX=-4147,poiY=853,wowhead="https://www.wowhead.com/wotlk/quest=10837",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I believe that I can imbue nethervine crystals with my own essence. The power contained within these imbued crystals should be sufficient to free enslaved drakes of their masters' grasps.$B$BTravel to Netherwing Ledge, an island located off the broken shelf of Shadowmoon Valley, to the southeast. It is on Netherwing Ledge that you will find nethervine crystals. Return to me when you have collected enough crystals to fill your packs.$B$BAnd $N, Beware the Dragonmaw that now inhabit the island.",logDesc="Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to collect 12 Nethervine Crystals from Netherwing Ledge.$B"} end
if not DB[10838] then DB[10838]={id=10838,zoneId=3483,name="The Demoniac Scryer",level=61,minLevel=58,giver="Apothecary Antonivich",giverType="NPC",giverId=16588,ender="Apothecary Antonivich",enderType="NPC",enderId=16588,rewardNextId=10875,poiX=226,poiY=2839,wowhead="https://www.wowhead.com/wotlk/quest=10838",image="assets/images/quests/placeholder.png",xpDiff=6,money=40000,desc="The Demoniac Scryer is now ready.  Take it behind Hellfire Citadel, to Hellfire Basin, and summon it upon the ground.  It will then begin to attune itself to Hellfire Citadel.  After its attunement, speak to the Scryer and transcribe what it tells you.  Bring that transcription to me...$B$BGo, $n, but only when you are ready.  There is no doubt that Hellfire Citadel will detect the Scryer and send wardens to destroy it!",logDesc="Use the Demoniac Scryer in Hellfire Basin, wait for it to attune, and then take a reading.$B$BReturn the Demoniac Scryer and the Demoniac Scryer Reading to Apothecary Antonivich in Thrallmar.",rewards={{id=31715,qty=1}}} end
if not DB[10839] then DB[10839]={id=10839,zoneId=3519,name="Veil Skith: Darkstone of Terokk",level=64,minLevel=62,giver="Kirrik the Awakened",giverType="NPC",giverId=22272,ender="Kirrik the Awakened",enderType="NPC",enderId=22272,rewardNextId=10848,poiX=-2855,poiY=5054,wowhead="https://www.wowhead.com/wotlk/quest=10839",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Veil Skith lies to the northwest of the caravan and to the south of Shattrath in a secluded grove of the forest. It is rumored that the colony of Skettis has constructed a maligned altar of worship. This Darkstone of Terokk must be purified if the arakkoa of Skith are ever to be redeemed.$b$bTake this Rod of Purification and cast it upon the Darkstone. Blessed by A'dal, the rod's purity might be enough to bring clarity to the Darkstone. Go now and may the light shine upon thee.",logDesc="Use the Rod of Purification on the Darkstone of Terokk in Veil Skith and return to Kirrik the Awakened at the Refugee Caravan in the Bone Wastes."} end
if not DB[10840] then DB[10840]={id=10840,zoneId=3519,name="The Tomb of Lights",level=65,minLevel=63,giver="High Priest Orglum",giverType="NPC",giverId=22278,ender="High Priest Orglum",enderType="NPC",enderId=22278,poiX=-2827,poiY=5061,wowhead="https://www.wowhead.com/wotlk/quest=10840",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="To the east, buried under the charred sand, is the Tomb of Lights, a lost resting place of the dead.  Before our caravan was ambushed I was going to journey to the tomb and cleanse it of evil spirits.  $B$BLittle did I know it was already infested with another kind of evil.  Even now the ethereals plunder the bodies of the fallen for trinkets and keepsakes that were given to the dead centuries ago.  $B$BThere is little I can do while our caravan struggles to survive.  ",logDesc="High Priest Orglum wants you to journey to the Tomb of Lights and kill 10 Ethereal Nethermancers and 10 Ethereal Plunderers and then return to him at the Refugee Caravan."} end
if not DB[10841] then DB[10841]={id=10841,zoneId=3519,name="The Vengeful Harbinger",level=255,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10841",image="assets/images/quests/placeholder.png",desc="[PH]  Go into the Tomb of Light and activate the thingy.",logDesc="[PH]  Activate the thingy."} end
if not DB[10842] then DB[10842]={id=10842,zoneId=3519,name="Vengeful Souls",level=65,minLevel=63,giver="High Priest Orglum",giverType="NPC",giverId=22278,ender="High Priest Orglum",enderType="NPC",enderId=22278,poiX=-2827,poiY=5061,wowhead="https://www.wowhead.com/wotlk/quest=10842",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Tomb of Lights has become corrupted by the Shadow Council and the draenei dead have become cursed spirits, angry and confused with a burning hatred for the living.$b$bEnter the tomb and seek out these tragic victims. Give them the rest that they deserve.",logDesc="High Priest Orglum wants you to journey into the Tomb of Lights and defeat 5 Vengeful Draenei.",choiceRewards={{id=31617,qty=1},{id=31615,qty=1}}} end
if not DB[10843] then DB[10843]={id=10843,zoneId=3522,name="Since Time Forgotten...",level=68,minLevel=65,giver="Leoroxx",giverType="NPC",giverId=22004,ender="Leoroxx",enderType="NPC",enderId=22004,rewardNextId=10845,poiX=2207,poiY=4761,wowhead="https://www.wowhead.com/wotlk/quest=10843",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Since time forgotten we have fought with the Bladespire ogres.$B$BWe have managed to push them back so that now they only hold a tenuous grip at Bladespire Outpost.  It's back the way that you came, on the southwestern edge of the Razor Ridge.$B$BProve your worth to me by killing their leader, Gnosh Brognat.$B$BLet us see what stuff you are made of when fighting the ogres.",logDesc="Slay Gnosh Brognat, leader of the ogres at the Bladespire Outpost."} end
if not DB[10844] then DB[10844]={id=10844,zoneId=3522,name="Forge Camp: Anger",level=68,minLevel=65,wowhead="https://www.wowhead.com/wotlk/quest=10844",image="assets/images/quests/placeholder.png",xpDiff=5,money=78000} end
if not DB[10845] then DB[10845]={id=10845,zoneId=3522,name="Slay the Brood Mother",level=68,minLevel=65,giver="Leoroxx",giverType="NPC",giverId=22004,ender="Leoroxx",enderType="NPC",enderId=22004,poiX=2207,poiY=4761,wowhead="https://www.wowhead.com/wotlk/quest=10845",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="My hunters have just returned from a scouting mission to the Singing Ridge.  It seems that the nether drakes, which infest the crystals there, have increased greatly in number, and threaten to spill out into our laps.$B$BSince you have proven yourself a competent slayer, let us see if your $c skills are the match of an adult drake.$B$BFind the Singing Ridge by heading south through the Scalewing Shelf.  Enter and slay their brood mother, Dreadwing.",logDesc="Slay Dreadwing.",choiceRewards={{id=31683,qty=1},{id=31685,qty=1},{id=31684,qty=1},{id=31686,qty=1}}} end
if not DB[10846] then DB[10846]={id=10846,zoneId=3522,name="Understanding the Mok'Nathal",level=67,minLevel=65,giver="Leoroxx",giverType="NPC",giverId=22004,ender="Leoroxx",enderType="NPC",enderId=22004,rewardNextId=10843,poiX=2207,poiY=4761,wowhead="https://www.wowhead.com/wotlk/quest=10846",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="<Leoroxx looks you in the eye with the kind of stare that chills your soul.>$B$BYou come to the Mok'Nathal, but you do not understand us.  You do not understand our struggle to survive.$B$BIf you would understand us, then you will have to endure a taste of that struggle.$B$BTo the south are the Vekh'nir arakkoa.  They have enslaved a group of ogres in the caverns known as Trogma's Claim and their leader, Vekh is in there.$B$BSlay him!",logDesc="Slay Vekh, leader of the Vekh'nir arakkoa."} end
if not DB[10847] then DB[10847]={id=10847,zoneId=3519,name="The Eyes of Skettis",level=62,minLevel=62,giver="Rilak the Redeemed",giverType="NPC",giverId=22292,ender="Rilak the Redeemed",enderType="NPC",enderId=22292,rewardNextId=10849,poiX=-1657,poiY=5449,wowhead="https://www.wowhead.com/wotlk/quest=10847",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="Doom harkens from the cliffs of Skettis.$b$bMy people, the arakkoa, face a fate shrouded in unspeakable evil. Too often have we abused dark magic for wrongdoing. Through A'dal I have learned of the Light and of redemption.$b$bTerokk watches his colonies from Skettis through orbs enchanted by the black art. Steal these Eyes from Veil Reskk and Veil Shienor in northern Terokkar. Let me see what Terokk sees. Let me look through the eyes of Skettis.",logDesc="Bring the Eye of Reskk and the Eye of Shienor to Rilak the Redeemed in the Lower City section of Shattrath City.",choiceRewards={{id=22829,qty=1},{id=22832,qty=1}}} end
if not DB[10848] then DB[10848]={id=10848,zoneId=3519,name="Veil Rhaze: Unliving Evil",level=64,minLevel=62,giver="Kirrik the Awakened",giverType="NPC",giverId=22272,ender="Kirrik the Awakened",enderType="NPC",enderId=22272,rewardNextId=10861,poiX=-2855,poiY=5054,wowhead="https://www.wowhead.com/wotlk/quest=10848",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="Veil Rhaze was a particularly wicked colony of Skettis.$b$bDespite the village's eradication by the Auchindoun disaster, Terokk's influence remained in the maligned spirits there. Travel west to Veil Rhaze and slay those murderous wretches. You'll find them to the west of the Shadow Tomb, on the border of Bone Wastes and Terokkar Forest.$b$bThis will be our first blow against Terokk and the guardians of Skettis.",logDesc="Kill 4 Deathtalon Spirits, 4 Screeching Spirits and 2 Spirit Ravens and return to Kirrik the Awakened at the Refugee Caravan.",choiceRewards={{id=31761,qty=1},{id=31762,qty=1}}} end
if not DB[10849] then DB[10849]={id=10849,zoneId=3519,name="Seek Out Kirrik",level=63,minLevel=62,giver="Rilak the Redeemed",giverType="NPC",giverId=22292,ender="Kirrik the Awakened",enderType="NPC",enderId=22272,rewardNextId=10839,poiX=-1657,poiY=5449,wowhead="https://www.wowhead.com/wotlk/quest=10849",image="assets/images/quests/placeholder.png",xpDiff=2,money=7400,desc="Other arakkoa took part in the betrayal of Terokk.$b$bKirrik recognized Terokk as a charlatan, not a prophet. The only prophecy Terokk envisioned was the doom borne of his own bidding.$b$bIt was Kirrik who led us bravely from Skettis. After our pilgrimage to Shattrath, Kirrik traveled to the colonies in search of others.$b$bThis missive tells of what the Eyes have seen. Kirrik must be told! Follow the road south out of Shattrath to the Bone Wastes and look for the caravan.",logDesc="Take Rilak's Missive to Kirrik the Awakened at the Refugee Caravan in the Bone Wastes."} end
if not DB[10850] then DB[10850]={id=10850,zoneId=3523,name="Nether Gas In a Fel Fire Engine",level=70,minLevel=67,giver="3",giverType="NPC",giverId=22293,ender="3",enderType="NPC",enderId=22293,poiX=4384,poiY=3484,wowhead="https://www.wowhead.com/wotlk/quest=10850",image="assets/images/quests/placeholder.png"} end
if not DB[10851] then DB[10851]={id=10851,zoneId=3522,name="The Totems of My Enemy",level=67,minLevel=65,giver="Spiritcaller Dohgar",giverType="NPC",giverId=22312,ender="Spiritcaller Dohgar",enderType="NPC",enderId=22312,rewardNextId=10853,poiX=2221,poiY=4782,wowhead="https://www.wowhead.com/wotlk/quest=10851",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="There is the right way to honor one's ancestors, and there is the wrong way.$B$BThe Bladespire ogres carry totems with them, but they do not use them to show their respect.  Instead, they seek to use them to manipulate and control.$B$BWe should steal their totems because they are unworthy!  We will then put them to better use.$B$BGo to the Bladespire Outpost to the west, just southwest of the Razor Ridge.  Slay the Bladespire mystics and crushers, and take their totems from them!",logDesc="Collect 5 Bladespire Totems."} end
if not DB[10852] then DB[10852]={id=10852,zoneId=3519,name="Missing Friends",level=64,minLevel=62,giver="Ethan",giverType="NPC",giverId=22365,ender="Ethan",enderType="NPC",enderId=22365,poiX=-2848,poiY=5046,wowhead="https://www.wowhead.com/wotlk/quest=10852",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We broke down here because some guys came in the night and made a lot of noise.  It was scary.  I don't know when we are going to get moving again.  $B$BSome of my friends are missing though.  I don't know where they are.  I think those scary bird men took them away to the northwest.  They probably are all locked up in cages and stuff.  If you find them that would be great.  I'm kind of worried about them.",logDesc="Ethan wants you to find 12 of his missing friends in Veil Skith and then return to him at the Refugee Caravan.",rewards={{id=31666,qty=1}}} end
if not DB[10853] then DB[10853]={id=10853,zoneId=3522,name="Spirit Calling",level=67,minLevel=65,giver="Spiritcaller Dohgar",giverType="NPC",giverId=22312,ender="Spiritcaller Dohgar",enderType="NPC",enderId=22312,rewardNextId=10859,poiX=2221,poiY=4782,wowhead="https://www.wowhead.com/wotlk/quest=10853",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="The spirits of the nether drakes in the Singing Ridge are in need of liberation.$B$BThe nether drakes were not always nether drakes.  They used to be black drakes.$B$BBut then, with the destruction of this world, a wave of nether energy washed over everything and had the side-effect of changing the drakeling eggs.$B$BNow they are all twisted versions of their former selves.  We must help them to find peace.$B$BDo this by slaying a drake near to the spirit calling totem, and then take its spirit from it.",logDesc="Use the Spirit Calling Totems to collect 8 Lesser Nether Drake Spirits.",rewards={{id=31437,qty=5}},choiceRewards={{id=31711,qty=1},{id=31713,qty=1},{id=31712,qty=1},{id=31714,qty=1}}} end
if not DB[10854] then DB[10854]={id=10854,zoneId=3520,name="The Force of Neltharaku",level=70,minLevel=70,giver="3",giverType="NPC",giverId=21657,ender="3",enderType="NPC",enderId=21657,rewardNextId=10858,poiX=-4147,poiY=853,wowhead="https://www.wowhead.com/wotlk/quest=10854",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Take this enchanted nethervine crystal and make your way back to Dragonmaw Fortress. Once there, seek out the enslaved drakes and invoke the magic of the nethervine crystal. My own energies will pour forth, causing the drakes to break free from the bond of their captors. When you see that the drake has broken free, help it defeat its captor! It will most assuredly be weak from the imprisonment.$B$BRelease all that you can find and return to me, $N.",logDesc="Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to free 5 Enslaved Netherwing Drakes."} end
if not DB[10855] then DB[10855]={id=10855,zoneId=3523,name="Fel Reavers, No Thanks!",level=69,minLevel=67,giver="Nether-Stalker Nauthis",giverType="NPC",giverId=20471,ender="Nether-Stalker Nauthis",enderType="NPC",enderId=20471,rewardNextId=10856,poiX=4158,poiY=2991,wowhead="https://www.wowhead.com/wotlk/quest=10855",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="Ah, yes - the fel reaver!  Certainly the Legion's most terrible mechanical creation.  There are no less than three of these abominations aimed at the Stormspire.$B$BFortunately for us, they are not active yet.  This affords us the possibility of dealing with them through sabotage instead of brute force.$B$BObtain condensed nether gas from the gan'arg at Forge Base: Oblivion and fill a nearby fel reaver's fuel tank with it.  I've a feeling its engine won't handle it too well.",logDesc="Obtain 5 Condensed Nether Gas from Gan'arg Mekgineers at Forge Base: Oblivion, northwest of the Stormspire, and load them into a nearby Inactive Fel Reaver.  Return to Nether-Stalker Nauthis after you've completed this task."} end
if not DB[10856] then DB[10856]={id=10856,zoneId=3523,name="The Best Defense",level=69,minLevel=67,giver="Nether-Stalker Nauthis",giverType="NPC",giverId=20471,ender="Nether-Stalker Nauthis",enderType="NPC",enderId=20471,rewardNextId=10857,poiX=4158,poiY=2991,wowhead="https://www.wowhead.com/wotlk/quest=10856",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Brave acts of industrial sabotage will only get us so far, $N.  Just as Forge Base: Oblivion serves as an assembly site for Fel Reavers, Forge Base: Gehenna serves as a staging ground for their army as it is where the majority of the Legion's teleportation devices are located.$B$BI want you to go in there and put a dent in their numbers.  They must have a full regiment of wrathbringers by now and we just can't allow that.",logDesc="Nether-Stalker Nauthis wants you to slay 12 Wrathbringers at Forge Base: Gehenna, north of the Stormspire."} end
if not DB[10857] then DB[10857]={id=10857,zoneId=3523,name="Teleport This!",level=69,minLevel=67,giver="Nether-Stalker Nauthis",giverType="NPC",giverId=20471,ender="Nether-Stalker Nauthis",enderType="NPC",enderId=20471,poiX=4158,poiY=2991,wowhead="https://www.wowhead.com/wotlk/quest=10857",image="assets/images/quests/placeholder.png",xpDiff=6,desc="As fun as killing demons might be, it does us little good when the Legion can keep using its teleporters to replace anything we kill.$B$BUnfortunately, I don't have any high-powered explosives handy... but the mo'arg that maintain the teleporters do.$B$BTake this rod... I've tuned its powers to interfere with mo'arg brain frequencies.  Return to Forge Base: Gehenna and use it on any mo'arg you see.  You won't have long, but you'll be able to use their demolition charges on the nearby teleporters.",logDesc="Nether-Stalker Nauthis wants you to use the Mental Interference Rod on the Mo'arg at Forge Base: Gehenna and use their Detonate Teleporter ability on the three teleporters in the forge camp.",choiceRewards={{id=31701,qty=1},{id=31700,qty=1},{id=31703,qty=1},{id=31699,qty=1}}} end
if not DB[10858] then DB[10858]={id=10858,zoneId=3520,name="Karynaku",level=70,minLevel=70,giver="3",giverType="NPC",giverId=21657,ender="3",enderType="NPC",enderId=22112,poiX=-4147,poiY=853,wowhead="https://www.wowhead.com/wotlk/quest=10858",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It shames me to ask for your assistance once more, $N, but you are my flight's only hope. Without my mate, the netherwing brood may die out completely.$B$BMake your way to the top of Dragonmaw Fortress and find Karynaku.$B$BWe will be flying overhead. Should a break appear in their defenses, the might of the netherwing will swoop down to assist you.$B",logDesc="Seek out Karynaku at Dragonmaw Fortress."} end
if not DB[10859] then DB[10859]={id=10859,zoneId=3522,name="Gather the Orbs",level=67,minLevel=65,giver="Spiritcaller Dohgar",giverType="NPC",giverId=22312,ender="Spiritcaller Dohgar",enderType="NPC",enderId=22312,rewardNextId=10865,poiX=2221,poiY=4782,wowhead="https://www.wowhead.com/wotlk/quest=10859",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="The Razaani ethereals have strange devices that emit small, pink floating light orbs.  They remind me of souls.$B$BThey are not to be confused with the large yellow balls that break free of the ethereal when they die, these are something else entirely.$B$BI'd like for you to head north to Razaan's Landing and drop some totems, which will attact the pink light orbs.$B$BBring them back to me so that I might determine exactly what they are.",logDesc="Use the Orb Collecting Totem to collect 15 Razaani Light Orbs."} end
if not DB[10860] then DB[10860]={id=10860,zoneId=3522,name="Mok'Nathal Treats",level=67,minLevel=65,giver="Matron Varah",giverType="NPC",giverId=21088,ender="Matron Varah",enderType="NPC",enderId=21088,poiX=2227,poiY=4718,wowhead="https://www.wowhead.com/wotlk/quest=10860",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="Hungry, $r?  The Great Spirit helps those that help themselves.  If you want to earn a meal, I suggest that you listen up, because Braagor there isn't going to give you anything for free, nor as tasty!$B$BThe raptors and scalewings of Razor Ridge and the Scalewing Shelf have everything that's needed for two of the most delicious dishes you'll ever taste.  Bring me their raptor ribs and serpent flesh, and I'll make some of each for you.$B$BI may even teach you how to cook them up for yourself, if you hurry.",logDesc="Collect 3 Raptor Ribs and 3 Serpent Flesh.",rewards={{id=31672,qty=3},{id=31673,qty=3},{id=31675,qty=1},{id=31674,qty=1}}} end
if not DB[10861] then DB[10861]={id=10861,zoneId=3519,name="Veil Lithic: Preemptive Strike",level=64,minLevel=62,giver="Kirrik the Awakened",giverType="NPC",giverId=22272,ender="Kirrik the Awakened",enderType="NPC",enderId=22272,rewardNextId=10874,poiX=-2855,poiY=5054,wowhead="https://www.wowhead.com/wotlk/quest=10861",image="assets/images/quests/placeholder.png",xpDiff=5,money=31000,desc="In the wretched colony to the southwest known as Veil Lithic, Terokk's minions are attempting to befoul their avian brethren before they hatch. The dark sorcerers of Lithic encase eggs in a shadowy curse. When the hatchlings emerge, they mindlessly serve Terrok.$b$bTravel to Veil Lithic and prematurely break the eggs before the curse has time to seep in. Even if you are too late, you can put down the tainted ones.$b$bRemember, the Light shines brightest in the darkness.",logDesc="Break the cursed eggs in Veil Lithic. Redeem 3 Hatchlings and slay 3 Malevolent Hatchlings before returning to Kirrik the Awakened at the Refugee Caravan.",choiceRewards={{id=25959,qty=1},{id=25961,qty=1},{id=25958,qty=1},{id=25960,qty=1}}} end
if not DB[10862] then DB[10862]={id=10862,zoneId=3519,name="Surrender to the Horde",level=63,minLevel=62,giver="Rokag",giverType="NPC",giverId=18386,ender="Rilak the Redeemed",enderType="NPC",enderId=22292,rewardNextId=10847,poiX=-2607,poiY=4439,wowhead="https://www.wowhead.com/wotlk/quest=10862",image="assets/images/quests/placeholder.png",xpDiff=5,money=23000,desc="The cowardly arakkoa attack us daily.  They ambush our hunters and sometimes even raid inside our walls.  We kill them when we can, but their magic is strong and they often escape our warbands.  $B$BI have learned that some arakkoa claim to be friendly with the Horde.  They live in Shattrath City to the northwest.  Rilak the Redeemed is their leader.  Search for him in the Lower City, and when you find him, demand his surrender.",logDesc="Rokag wants you to seek out Rilak the Redeemed in the Lower City section of Shattrath City and demand that he and his people surrender to the Horde."} end
if not DB[10863] then DB[10863]={id=10863,zoneId=3519,name="Secrets of the Arakkoa",level=63,minLevel=62,giver="Lady Dena Kennedy",giverType="NPC",giverId=15991,ender="Rilak the Redeemed",enderType="NPC",enderId=22292,rewardNextId=10847,poiX=-3017,poiY=3963,wowhead="https://www.wowhead.com/wotlk/quest=10863",image="assets/images/quests/placeholder.png",xpDiff=5,money=23000,desc="Out here on the frontier we have to deal with the arakkoa every day.  They strike at us when they please, raiding our supply lines and killing our scouts.  $B$BYet we know very little about these enigmatic creatures.  I have received news that northwest of here in Shattrath City there are arakkoa who are not hostile.  They might be willing to share the secrets of their race.  $B$BRilak the Redeemed is their leader.  He resides in the northern part of the Lower City.",logDesc="Lady Dena Kennedy wants you to seek out Rilak the Redeemed in the Lower City section of Shattrath City and find out what secrets he will share of the Arakkoa."} end
if not DB[10864] then DB[10864]={id=10864,zoneId=3483,name="A Burden of Souls",level=61,minLevel=58,giver="Apothecary Antonivich",giverType="NPC",giverId=16588,ender="Apothecary Antonivich",enderType="NPC",enderId=16588,rewardNextId=10838,poiX=226,poiY=2839,wowhead="https://www.wowhead.com/wotlk/quest=10864",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="I have a device, the Demoniac Scryer, that can analyze fel magic.  I would have you use the Scryer, but first... you must appease it.  The Scryer, you see, has trapped within it a creature of vast intelligence and its needs are, shall we say, quite eccentric.$B$BTo appease the Scryer, you must kill orcs.  Specifically, they must be Shattered Hand orcs -- the Scryer demands their souls.$B$BReturn to me when the souls are reaped.  You will find the orcs north, and south, and surrounding... Hellfire Citadel.",logDesc="Kill 20 Shattered Hand orcs, then return to Apothecary Antonivich in Thrallmar."} end
if not DB[10865] then DB[10865]={id=10865,zoneId=3522,name="Inform Leoroxx!",level=68,minLevel=65,giver="Spiritcaller Dohgar",giverType="NPC",giverId=22312,ender="Leoroxx",enderType="NPC",enderId=22004,poiX=2221,poiY=4782,wowhead="https://www.wowhead.com/wotlk/quest=10865",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Quickly, you must inform Leoroxx of what is transpiring up at Razaan's Landing!$B$BThose orbs were comprised of souls, some of them Mok'Nathal!",logDesc="Speak with Leoroxx about what the Razaani ethereal are up to.  He can be found at Mok'Nathal Village in the Blade's Edge Mountains."} end
if not DB[10866] then DB[10866]={id=10866,zoneId=3520,name="Zuluhed the Whacked",level=70,minLevel=70,giver="3",giverType="NPC",giverId=22112,ender="3",enderType="NPC",enderId=22112,rewardNextId=10870,poiX=-4201,poiY=382,wowhead="https://www.wowhead.com/wotlk/quest=10866",image="assets/images/quests/placeholder.png",xpDiff=7,desc="He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.$B$BAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!$B$BKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?",logDesc="Kill Zuluhed the Whacked and recover Zuluhed's Key. Use Zuluhed's Key on Zuluhed's Chains to free Karynaku."} end
if not DB[10867] then DB[10867]={id=10867,zoneId=3522,name="There Can Be Only One Response",level=68,minLevel=65,giver="Leoroxx",giverType="NPC",giverId=22004,ender="Spiritcaller Dohgar",enderType="NPC",enderId=22312,poiX=2207,poiY=4761,wowhead="https://www.wowhead.com/wotlk/quest=10867",image="assets/images/quests/placeholder.png",xpDiff=6,money=78000,desc="There can be only one response to this... this, DEFILEMENT of the souls of our ancestors!$B$B$N, if you would aid us to restore the souls of our honored dead to their rightful place, go back to Razaan's Landing.$B$BGo back up there and kill the razaani until their leader, Nexus-Prince Razaan shows his cowardly face.  Kill him and get those souls back, and then give them over to Spiritcaller Dohgar!",logDesc="Collect the Collection of Souls.",choiceRewards={{id=31687,qty=1},{id=31688,qty=1},{id=31689,qty=1},{id=31690,qty=1}}} end
if not DB[10868] then DB[10868]={id=10868,zoneId=3519,name="Arakkoa War Path",level=62,minLevel=60,giver="Advisor Faila",giverType="NPC",giverId=18712,ender="Advisor Faila",enderType="NPC",enderId=18712,poiX=-2605,poiY=4441,wowhead="https://www.wowhead.com/wotlk/quest=10868",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could charge out to meet them in numbers.  They use their summoning circles to rescue their warriors from certain death but they cannot run from us if we attack their homes.  Veil Reskk and Veil Shienor lie to the north and northeast.  $B$BFind these arakkoa nests and kill as many as you can.",logDesc="Advisor Faila asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to her in Stonebreaker Hold."} end
if not DB[10869] then DB[10869]={id=10869,zoneId=3519,name="Thin the Flock",level=62,minLevel=60,giver="Lieutenant Gravelhammer",giverType="NPC",giverId=18713,ender="Lieutenant Gravelhammer",enderType="NPC",enderId=18713,poiX=-3008,poiY=3978,wowhead="https://www.wowhead.com/wotlk/quest=10869",image="assets/images/quests/placeholder.png",xpDiff=5,money=27000,desc="The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could marshal our soldiers.  $B$BVeil Reskk and Veil Shienor lie to the north and northwest.  Find these arakkoa nests and kill as many as you can.  They may not fear us, but at least we can thin their numbers.",logDesc="Lieutenant Gravelhammer asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to him in Allerian Stronghold."} end
if not DB[10870] then DB[10870]={id=10870,zoneId=3520,name="Ally of the Netherwing",level=70,minLevel=70,giver="3",giverType="NPC",giverId=22112,ender="Mordenai",enderType="NPC",enderId=22113,poiX=-4201,poiY=382,wowhead="https://www.wowhead.com/wotlk/quest=10870",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Allow me to return you to Mordenai. I am certain that he wishes to see you once more.",logDesc="Let Karynaku return you to Mordenai in the Netherwing Fields.",choiceRewards={{id=31492,qty=1},{id=31491,qty=1},{id=31490,qty=1},{id=31494,qty=1},{id=31493,qty=1}}} end
if not DB[10871] then DB[10871]={id=10871,zoneId=3520,name="Ally of the Netherwing",level=70,minLevel=70,giver="3",giverType="NPC",giverId=22112,poiX=-4201,poiY=382,wowhead="https://www.wowhead.com/wotlk/quest=10871",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Allow me to return you to Mordenai. I am certain that he wishes to see you once more.",logDesc="Let Karynaku return you to Mordenai in the Netherwing Fields."} end
if not DB[10872] then DB[10872]={id=10872,zoneId=3520,name="Zuluhed the Whacked",level=70,minLevel=70,rewardNextId=10871,wowhead="https://www.wowhead.com/wotlk/quest=10872",image="assets/images/quests/placeholder.png",xpDiff=7,desc="He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.$B$BAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!$B$BKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?",logDesc="Kill Zuluhed the Whacked and recover Zuluhed's Key. Use Zuluhed's Key on Zuluhed's Chains to free Karynaku."} end
if not DB[10873] then DB[10873]={id=10873,zoneId=3519,name="Taken in the Night",level=65,minLevel=63,giver="Scout Navrin",giverType="NPC",giverId=22364,ender="Scout Navrin",enderType="NPC",enderId=22364,poiX=-3724,poiY=5386,wowhead="https://www.wowhead.com/wotlk/quest=10873",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="Our small outpost is under constant attack. Several nights ago, we were raided by the spiders of Netherweb Ridge, on the southeastern edge of the Bone Wastes. They poisoned many of our people, wrapped them in webs and carried them away. Some of our warriors took up arms and with little preparation pursued the spiders.$B$BWe have not seen the captives or our hunting parties since. We hope that some may still be alive, perhaps imprisoned by the spiders.  Our numbers are few. Will you search for our people?$B",logDesc="Scout Navrin wants you to travel to the Netherweb Ridge and free 6 Webbed Sha'tar Warriors and then return to him at Sha'tari Base Camp."} end
if not DB[10874] then DB[10874]={id=10874,zoneId=3519,name="Veil Shalas: Signal Fires",level=65,minLevel=62,giver="Kirrik the Awakened",giverType="NPC",giverId=22272,ender="Kirrik the Awakened",enderType="NPC",enderId=22272,rewardNextId=10889,poiX=-2855,poiY=5054,wowhead="https://www.wowhead.com/wotlk/quest=10874",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="Terokk's perch, Skettis, looms above the Bone Wastes to the east. At the base of Skettis lies Veil Shalas, the most formidable of Terokk's colonies. It is through the stronghold of Veil Shalas that Terokk's forward sages wage war against the Light.$b$bThe evil-doers of Shalas communicate with their master using a complex system of magical signal fires. Travel to the east, $r, and extinguish the fires. Once Veil Shalas is silenced, we can begin to plot the fall of Skettis.$b$bBut I get ahead of myself.",logDesc="Kirrik the Awakened at the Refugee Caravan wants you to extinguish the four signal fires of Veil Shalas.",choiceRewards={{id=25966,qty=1},{id=25965,qty=1},{id=25963,qty=1}}} end
if not DB[10875] then DB[10875]={id=10875,zoneId=3483,name="Report to Nazgrel",level=61,minLevel=58,giver="Apothecary Antonivich",giverType="NPC",giverId=16588,ender="Nazgrel",enderType="NPC",enderId=3230,rewardNextId=10876,poiX=226,poiY=2839,wowhead="https://www.wowhead.com/wotlk/quest=10875",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$n, during your foray with the Demoniac Scryer, I sent word of your exploits against the fel orcs.  Nazgrel, our illustrious leader in Thrallmar, wishes to speak with you.  I believe he has a bloody mission in mind...",logDesc="Speak with Nazgrel at Thrallmar in Hellfire Peninsula."} end
if not DB[10876] then DB[10876]={id=10876,zoneId=3483,name="The Foot of the Citadel",level=63,minLevel=58,giver="Nazgrel",giverType="NPC",giverId=3230,ender="Nazgrel",enderType="NPC",enderId=3230,poiX=243,poiY=2698,wowhead="https://www.wowhead.com/wotlk/quest=10876",image="assets/images/quests/placeholder.png",xpDiff=6,money=58000,desc="Force Commander Gorax is training Shattered Hand captains at the base of Hellfire Citadel, honing them to a bloody razor's edge.  You must kill him, $N, for his loss would be a mighty blow to the fel orcs.$B$BHowever, that is not all you must do.$B$BTake this banner.  Place it atop Gorax's corpse.  Gorax's commander, the Hand of Kargath, must answer your challenge if he has even a drop of true orc blood within him!$B$BHis head, the head of the hand of Kargath, is what I seek.",logDesc="Kill Force Commander Gorax, place the Challenge From the Horde upon his corpse, kill The Hand of Kargath, and then bring the Head of the Hand of Kargath to Nazgrel in Thrallmar.",choiceRewards={{id=31719,qty=1},{id=31717,qty=1},{id=31718,qty=1},{id=31720,qty=1}}} end
if not DB[10877] then DB[10877]={id=10877,zoneId=3519,name="The Dread Relic",level=66,minLevel=63,giver="Oakun",giverType="NPC",giverId=22456,ender="Oakun",enderType="NPC",enderId=22456,rewardNextId=10923,poiX=-3755,poiY=5406,wowhead="https://www.wowhead.com/wotlk/quest=10877",image="assets/images/quests/placeholder.png",xpDiff=5,money=35000,desc="Long ago a caravan went to Auchindoun with a mission to take a Dread Relic from the ancient tombs beneath the necropolis. They fled, but the relic was their undoing.  The relic is evil and it summons evil when touched.   Their caravan was destroyed somewhere to the east. $B$BThis dark artifact is the key to a terrible plan to defeat Teribus the Cursed, a creature that flies over the Bone Wastes.  Help me if you wish, but your life and even your soul will be at risk.",logDesc="Oakun wants you to travel east to the Derelict Caravan to recover the Dread Relic.  Return to Oakun when the task is complete."} end
if not DB[10878] then DB[10878]={id=10878,zoneId=3519,name="Before Darkness Falls",level=63,minLevel=62,giver="Mekeda",giverType="NPC",giverId=22370,ender="Mekeda",enderType="NPC",enderId=22370,poiX=-2866,poiY=5040,wowhead="https://www.wowhead.com/wotlk/quest=10878",image="assets/images/quests/placeholder.png",xpDiff=5,desc="After our caravan fell prey to an attack by Shadow Council cabal cultists, scouts were sent to Shattrath to call for help.  The guards think we're safe for now, but they underestimate these madmen.$B$BI, for one, am not looking forward to having my throat slit by some cabal initiate in the middle of the night.  Do us all a favor and take the fight to them, before they come to us.$B$BYou will find our attackers south of here, at Auchindoun's northern entrance.",logDesc="Mekeda at the Refugee Caravan wants you to kill 8 Cabal Skirmishers, 4 Cabal Spell-Weavers and 2 Cabal Initiates."} end
if not DB[10879] then DB[10879]={id=10879,zoneId=3519,name="The Skettis Offensive",level=65,minLevel=62,giver="Defender Grashna",giverType="NPC",giverId=22373,ender="Rilak the Redeemed",enderType="NPC",enderId=22292,poiX=-1655,poiY=5459,wowhead="https://www.wowhead.com/wotlk/quest=10879",image="assets/images/quests/placeholder.png",xpDiff=7,money=99000,desc="Skettis has waged war on us! Have you gathered enough to help with Shattrath's defense?$b$bHold off the attackers!",logDesc="Hold off the attackers and speak with Rilak the Redeemed.",choiceRewards={{id=31727,qty=1},{id=31726,qty=1}}} end
if not DB[10880] then DB[10880]={id=10880,zoneId=3519,name="Cabal Orders",level=64,minLevel=62,ender="Mekeda",enderType="NPC",enderId=22370,rewardNextId=10881,wowhead="https://www.wowhead.com/wotlk/quest=10880",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This message bears a dark seal and though the language seems somewhat familiar, it appears to be encoded.$B$BPerhaps someone at the Refugee Caravan will know something about it.",logDesc="Bring the Cabal Orders to Mekeda at the Refugee Caravan in the Bone Wastes."} end
if not DB[10881] then DB[10881]={id=10881,zoneId=3519,name="The Shadow Tomb",level=64,minLevel=62,giver="Mekeda",giverType="NPC",giverId=22370,ender="Mekeda",enderType="NPC",enderId=22370,poiX=-2866,poiY=5040,wowhead="https://www.wowhead.com/wotlk/quest=10881",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Many believe it was the Shadow Council that caused the explosion that tore Auchindoun apart.  It is rumored they awoke a great evil inside.$B$BIf that is true, then that evil must have turned against them.  According to these orders, part of the Shadow Council is fleeing Auchindoun.  They are using the Shadow Tomb to store powerful artifacts from Auchindoun.$B$BThree of these are sacred, for they belonged to the powerful patriarchs Arunen, K'alen and Atalor.  I must ask you to retrieve them.",logDesc="Go into the Shadow Tomb, west of the Refugee Caravan and retrieve the Drape of Arunen, the Gavel of K'alen and the Scroll of Atalor.  Return to Mekeda at the Refugee Caravan after you've completed this task.",choiceRewards={{id=31728,qty=1},{id=31729,qty=1}}} end
if not DB[10882] then DB[10882]={id=10882,zoneId=3845,name="Harbinger of Doom",level=70,minLevel=67,giver="A'dal",giverType="NPC",giverId=18481,ender="A'dal",enderType="NPC",enderId=18481,poiX=-1864,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=10882",image="assets/images/quests/placeholder.png",xpDiff=8,money=132000,desc="<A discordant note can be detected in A'dal's 'voice'.>$B$BPrince Kael'thas has chosen his warden poorly, and now the entities that we kept locked up within the Arcatraz are breaking free.$B$BOne in particular, a servant of the Old Gods known as Harbinger Skyriss, seeks to usher in his masters' vision of conquering all of the worlds in the universe.$B$B$N, you must not allow him to escape.  Return to Tempest Keep, enter the Arcatraz, and slay Harbinger Skyriss before it is too late!",logDesc="You have been tasked to go to Tempest Keep's Arcatraz satellite and slay Harbinger Skyriss.  Return to A'dal at the Terrace of Light in Shattrath City after you have done so.",choiceRewards={{id=31747,qty=1},{id=31749,qty=1},{id=31748,qty=1}}} end
if not DB[10883] then DB[10883]={id=10883,zoneId=3703,name="The Tempest Key",level=70,minLevel=70,giver="Khadgar",giverType="NPC",giverId=18166,ender="A'dal",enderType="NPC",enderId=18481,poiX=-1860,poiY=5420,wowhead="https://www.wowhead.com/wotlk/quest=10883",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You have proven yourself capable of great feats, $N. Your discovery of the Cipher of Damnation and Kael'Thas' involvement is most important to our cause. Should Kael use the cipher, what little is left of this world may collapse.$B$BA'dal is convinced that Kael must be stopped and now seeks adventurers willing to undergo trials. Those that prove their strength will be granted favor by the naaru.$B$B<Khadgar nods.>$B$BA'dal awaits...$B",logDesc="Speak with A'dal in Shattrath City.$B"} end
if not DB[10884] then DB[10884]={id=10884,zoneId=3703,name="Trial of the Naaru: Mercy",level=70,minLevel=70,giver="A'dal",giverType="NPC",giverId=18481,ender="A'dal",enderType="NPC",enderId=18481,poiX=-1864,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=10884",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Four trials you must pass before you are deemed worthy by the naaru.$B$BWithin the Shattered Halls of Hellfire Citadel are three of your people. They are held there by the merciless one, Kargath Bladefist. He seeks to execute them as a sign of his virility and power. You must save these prisoners before such an atrocity can come to pass. As proof of deed, bring me the unused axe of the executioner. It must not have a drop of blood on its blade!$B",logDesc="A'dal in Shattrath City wants you to recover the Unused Axe of the Executioner from the Shattered Halls of Hellfire Citadel.$B$BThis quest must be completed in Heroic dungeon difficulty."} end
if not DB[10885] then DB[10885]={id=10885,zoneId=3703,name="Trial of the Naaru: Strength",level=70,minLevel=70,giver="A'dal",giverType="NPC",giverId=18481,ender="A'dal",enderType="NPC",enderId=18481,poiX=-1864,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=10885",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Four trials you must pass before you are deemed worthy by the naaru.$B$BThe trial of strength is divided in two. You must destroy the leader of the Coilfang Steamvaults, Warlord Kalithresh, and bring me his trident. Slay the extra-planar being known as Murmur, in the Shadow Labyrinth of Auchindoun, and bring me his essence.$B$BDo this and you will have passed the trial of strength.",logDesc="A'dal in Shattrath City wants you to recover Kalithresh's Trident and Murmur's Essence.$B$BThis quest must be completed in Heroic dungeon difficulty."} end
if not DB[10886] then DB[10886]={id=10886,zoneId=3703,name="Trial of the Naaru: Tenacity",level=70,minLevel=70,giver="A'dal",giverType="NPC",giverId=18481,ender="A'dal",enderType="NPC",enderId=18481,poiX=-1864,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=10886",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Four trials you must pass before you are deemed worthy by the naaru.$B$BIn our travels we have encountered many dangerous beings. Some of these beings we incarcerated and placed in what is now known as the Arcatraz of Tempest Keep.$B$BThere is one prisoner, however, that is a victim of circumstance. A stowaway who was in the wrong naaru vessel at the wrong time.$B$BVenture to the Arcatraz and rescue the gnome, Millhouse Manastorm. Ensure his survival.",logDesc="A'dal in Shattrath City wants you to rescue Millhouse Manastorm from the Arcatraz of Tempest Keep.$B$BThis quest must be completed in Heroic dungeon difficulty."} end
if not DB[10887] then DB[10887]={id=10887,zoneId=3519,name="Escaping the Tomb",level=64,minLevel=62,giver="Akuno",giverType="NPC",giverId=22377,ender="Mekeda",enderType="NPC",enderId=22370,poiX=-2766,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=10887",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I appreciate your help, $N.  I was certain I was going to be killed.$B$BLet's get out of here with a hurry.  It won't be long before more cultists come after us.",logDesc="Help Akuno find his way to the Refugee Caravan.  Speak to Mekeda after you've completed this quest.",choiceRewards={{id=31733,qty=1},{id=31734,qty=1},{id=31731,qty=1},{id=31732,qty=1}}} end
if not DB[10888] then DB[10888]={id=10888,zoneId=3836,name="Trial of the Naaru: Magtheridon",level=70,minLevel=70,ender="A'dal",enderType="NPC",enderId=18481,wowhead="https://www.wowhead.com/wotlk/quest=10888",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Four trials you must pass before you are deemed worthy by the naaru.$B$BOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!",logDesc="A'dal in Shattrath City wants you to slay Magtheridon.",rewards={{id=31746,qty=1}}} end
if not DB[10889] then DB[10889]={id=10889,zoneId=3519,name="Return to Shattrath",level=65,minLevel=62,giver="Kirrik the Awakened",giverType="NPC",giverId=22272,ender="Rilak the Redeemed",enderType="NPC",enderId=22292,poiX=-2855,poiY=5054,wowhead="https://www.wowhead.com/wotlk/quest=10889",image="assets/images/quests/placeholder.png",xpDiff=4,money=26000,desc="Your actions, while brave, will surely rouse a vindictive response from Terokk.$b$bHurry to Shattrath. Send word to Rilak!",logDesc="Travel to Shattrath City and speak with Rilak the Redeemed in the Lower City."} end
if not DB[10890] then DB[10890]={id=10890,zoneId=0,name="[UNUSED] <NYI> ",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=10890",image="assets/images/quests/placeholder.png"} end
if not DB[10891] then DB[10891]={id=10891,zoneId=-121,name="Imperial Plate Armor",level=50,minLevel=50,giver="Myolor Sunderfury",giverType="NPC",giverId=11145,ender="Derotain Mudsipper",enderType="NPC",enderId=14567,poiX=-4788,poiY=-1122,wowhead="https://www.wowhead.com/wotlk/quest=10891",image="assets/images/quests/placeholder.png",xpDiff=4,desc="There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?",logDesc="Speak with Derotain Mudsipper at Gadgetzan in Tanaris.$B"} end
if not DB[10892] then DB[10892]={id=10892,zoneId=-121,name="Imperial Plate Armor",level=50,minLevel=50,giver="Krathok Moltenfist",giverType="NPC",giverId=11176,ender="Derotain Mudsipper",enderType="NPC",enderId=14567,poiX=2056,poiY=-4802,wowhead="https://www.wowhead.com/wotlk/quest=10892",image="assets/images/quests/placeholder.png",xpDiff=4,desc="There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?",logDesc="Speak with Derotain Mudsipper at Gadgetzan in Tanaris.$B"} end
if not DB[10893] then DB[10893]={id=10893,zoneId=3522,name="Longtail is the Lynchpin",level=67,minLevel=65,giver="Watcher Moonshade",giverType="NPC",giverId=22386,ender="Watcher Moonshade",enderType="NPC",enderId=22386,rewardNextId=10722,poiX=3108,poiY=6132,wowhead="https://www.wowhead.com/wotlk/quest=10893",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="With the Blackwing wyrmcultists massing in the tunnel, we're hard pressed to deal with the situation.  Quite frankly, they have the numbers.$B$BAnd while we've been able to take care of any of their people that get too close, the fact remains that if they attack in earnest, we're going to be overrun.$B$BThe situation calls for someone to get through to the other end of the tunnel, and take out their leader, Draaca Longtail.  Up for some fun?",logDesc="Slay Draaca Longtail, the leader of the wyrmcultists in the Wyrmskull Tunnel."} end
if not DB[10894] then DB[10894]={id=10894,zoneId=3522,name="Wyrmskull Watcher",level=67,minLevel=65,giver="Tree Warden Chawn",giverType="NPC",giverId=22007,ender="Watcher Moonshade",enderType="NPC",enderId=22386,rewardNextId=10893,poiX=2981,poiY=5483,wowhead="https://www.wowhead.com/wotlk/quest=10894",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hmm, I'm not certain what we should do.  I'm not much of a military planner.$B$BWatcher Moonshade will know what to do.  He's heading up our defensive efforts at the Wyrmskull Tunnel to the west at the end of Wyrmskull Bridge.  We have a force out there just in case the cultists try anything funny.$B$BPlease, take the note to him with all due haste.",logDesc="Deliver the Meeting Note to Watcher Moonshade at the entrance of the Wyrmskull Tunnel in the Blade's Edge Mountains."} end
if not DB[10895] then DB[10895]={id=10895,zoneId=3483,name="Zeth'Gor Must Burn!",level=60,minLevel=58,giver="Wing Commander Dabir'ee",giverType="NPC",giverId=19409,ender="Wing Commander Dabir'ee",enderType="NPC",enderId=19409,poiX=-670,poiY=1852,wowhead="https://www.wowhead.com/wotlk/quest=10895",image="assets/images/quests/placeholder.png",xpDiff=6,money=18000,desc="It's time to strike Zeth'Gor from the air!  Our gryphon riders are ready for a sortie, $n.  But they need someone on the ground to direct their fire.  Are you ready for a covert mission?$B$BTake these smoke beacons into Zeth'Gor, the Bleeding Hollow stronghold to the west.  They have four guard towers: one near their northern wall, one near their southern wall, one near their forge and another nestled in their foothills.  Place a beacon underneath each of the towers and we'll fly in and bomb them!",logDesc="Use the smoke beacon at each of Zeth'Gor's towers, and then return to Wing Commander Dabir'ee at Expedition Point.",choiceRewards={{id=28057,qty=1},{id=28052,qty=1},{id=28050,qty=1},{id=28055,qty=1},{id=28051,qty=1}}} end
if not DB[10896] then DB[10896]={id=10896,zoneId=3519,name="The Infested Protectors",level=65,minLevel=62,giver="Lakotae",giverType="NPC",giverId=22420,ender="Lakotae",enderType="NPC",enderId=22420,poiX=-2861,poiY=5039,wowhead="https://www.wowhead.com/wotlk/quest=10896",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="The trees of this land are ravaged by the power that was unleashed from Auchindoun.  The foul magic that was unleashed blasted the land into the wastes you see all around.  The trees that survived are now infested with wretched wood mites that crawl under their bark and gnaw at their flesh.  $B$BRotting forest-rages and infested root-walkers are breeding grounds for the mites.  They are found along the edge of the wood to the east.  Destroy these creatures and then kill the mites that flee their husks.",logDesc="Lakotae wants you to kill 25 Wood Mites and then return to him at the Refugee Caravan.  The mites can be found living inside the bodies of Rotting Forest-Ragers and Infested Root-Walkers.  "} end
if not DB[10897] then DB[10897]={id=10897,zoneId=-181,name="Master of Potions",level=70,minLevel=68,giver="Lauranna Thar'well",giverType="NPC",giverId=17909,ender="Lauranna Thar'well",enderType="NPC",enderId=17909,poiX=-216,poiY=5437,wowhead="https://www.wowhead.com/wotlk/quest=10897",image="assets/images/quests/placeholder.png",xpDiff=8,desc="As you know, plants have properties that allow alchemists to re-energize and reinvigorate others through potions.$B$BMy familiarity with the plants of Outland allows me to teach alchemists how to make the most out of them.  If you're interested in expanding your knowledge of potions, I have but one task to ask of you.$B$BHigh Botanist Freywinn in Tempest Keep is rumored to have written a comprehensive botany guide.  Bring it to me along with samples of your work and I'll teach you the knowledge you seek.",logDesc="Lauranna Thar'well wants you to go to the Botanica in Tempest Keep and retrieve the Botanist's Field Guide from High Botanist Freywinn.  In addition she also wants you to bring her 5 Super Healing Potions, 5 Super Mana Potions and 5 Major Dreamless Sleep Potions.$B$B*WARNING!* You can only select one alchemy specialization."} end
if not DB[10898] then DB[10898]={id=10898,zoneId=3519,name="Skywing",level=65,minLevel=63,giver="Skywing",giverType="NPC",giverId=22424,ender="Rilak the Redeemed",enderType="NPC",enderId=22292,poiX=-3606,poiY=4176,wowhead="https://www.wowhead.com/wotlk/quest=10898",image="assets/images/quests/placeholder.png",xpDiff=6,money=66000,desc="Skywing flutters around you.$b$bYou get the feeling he wants you to follow him.",logDesc="Escort Skywing and report to Rilak the Redeemed in Shattrath City.",rewards={{id=31760,qty=1}},choiceRewards={{id=31766,qty=1},{id=31765,qty=1},{id=31764,qty=1}}} end
if not DB[10899] then DB[10899]={id=10899,zoneId=-181,name="Master of Transmutation",level=70,minLevel=68,giver="Zarevhi",giverType="NPC",giverId=22427,ender="Zarevhi",enderType="NPC",enderId=22427,poiX=4095,poiY=3024,wowhead="https://www.wowhead.com/wotlk/quest=10899",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Any alchemist will tell you that matter is malleable, any substance can be transformed into another - but nothing is really created or destroyed.$B$BA true master of transmutation can learn to overcome this limitation - and I can teach you how to obtain this mastery!$B$BAs a prospective transmuter you're undoubtedly familiar with primal might - the combination of the material representation of all primal forces.  Show me proof of your transmuting prowess and I will share my knowledge with you.",logDesc="Zarevhi at the Stormspire in Netherstorm wants you to bring him 4 Primal Mights.$B$B*WARNING!* You can only select one alchemy specialization."} end
if not DB[10900] then DB[10900]={id=10900,zoneId=3717,name="The Mark of Vashj",level=70,minLevel=70,giver="Skar'this the Heretic",giverType="NPC",giverId=22421,ender="Skar'this the Heretic",enderType="NPC",enderId=22421,poiX=-296,poiY=-459,wowhead="https://www.wowhead.com/wotlk/quest=10900",image="assets/images/quests/placeholder.png"} end
if not DB[10901] then DB[10901]={id=10901,zoneId=3717,name="The Cudgel of Kar'desh",level=70,minLevel=70,ender="Skar'this the Heretic",enderType="NPC",enderId=22421,wowhead="https://www.wowhead.com/wotlk/quest=10901",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Bring me the elemental signets that the cudgel requires!$B$BThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.$B$BThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.$B$BMake haste!$B",logDesc="Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet."} end
if not DB[10902] then DB[10902]={id=10902,zoneId=-181,name="Master of Elixirs",level=70,minLevel=68,giver="Lorokeem",giverType="NPC",giverId=19052,ender="Lorokeem",enderType="NPC",enderId=19052,poiX=-1661,poiY=5540,wowhead="https://www.wowhead.com/wotlk/quest=10902",image="assets/images/quests/placeholder.png",xpDiff=8,desc="I've devoted my life to perfecting my elixirs.  Despite my success, I haven't been able to create an elixir of eternal life.$B$BI think I know the reagent I'm missing.  I've heard of a place called the Caverns of Time in Azeroth where intruders known as rift lords and rift keepers phase in and out of the timeline.$B$BThis intrusive time-shifting creates tears in time itself, twisting it infinitely into crystallized essences.  Bring these to me along with samples of your work and I'll teach you all I know.",logDesc="Go to the Black Morass in the Caverns of Time and obtain 10 Essences of Infinity from Rift Lords and Rift Keepers.  Bring these along with  5 Elixirs of Major Defense, 5 Elixirs of Mastery and 5 Elixirs of Major Agility to Lorokeem in Shattrath's Lower City.$B$B*WARNING!* You can only select one alchemy specialization."} end
if not DB[10903] then DB[10903]={id=10903,zoneId=3483,name="Return to Honor Hold",level=61,minLevel=58,giver="Corporal Ironridge",giverType="NPC",giverId=21133,ender="Assistant Klatu",enderType="NPC",enderId=22430,poiX=-701,poiY=1875,wowhead="https://www.wowhead.com/wotlk/quest=10903",image="assets/images/quests/placeholder.png",xpDiff=3,desc="$n, while you were on your mission in Zeth'Gor, I received news of my commanding officer, Colonel Jules.  He was stricken with a demonic corruption while fighting near the Gor'gaz Outpost, and his situation has grown very bad.$B$BYou have made such great gains for us against the fel orcs.  Your strength in battle is without question... is your spirit just as strong?$B$BPlease, return to Honor Hold and speak with Klatu, in an upper room at the Honor Hold inn.",logDesc="Speak with Assistant Klatu, at Honor Hold's inn."} end
if not DB[10904] then DB[10904]={id=10904,zoneId=3522,name="Harvesting the Fel Ammunition",level=68,minLevel=65,giver="Evergrove Druid",giverType="NPC",giverId=22423,ender="Evergrove Druid",enderType="NPC",enderId=22423,rewardNextId=10911,poiX=2148,poiY=5416,wowhead="https://www.wowhead.com/wotlk/quest=10904",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="We must shut down the Burning Legion's access to Death's Door, but first you're going to destroy their two warp-gates!$B$BThe problem is, we can't even scratch one of those things, so you're going to need to use their own weapons against them.$B$BThe death's might, death's watch, deathforge over-smiths and deathforge technicians carry the ammunition for the fel cannons.$B$BNormally it wouldn't affect any of them, but if you bring the cannonballs to me, I will imbue them with Nature's unbridled wrath!",logDesc="Collect 5 Fel Cannonballs."} end
if not DB[10905] then DB[10905]={id=10905,zoneId=-181,name="Master of Potions",level=70,minLevel=68,giver="Apothecary Antonivich",giverType="NPC",giverId=16588,ender="Lauranna Thar'well",enderType="NPC",enderId=17909,rewardNextId=10897,poiX=226,poiY=2839,wowhead="https://www.wowhead.com/wotlk/quest=10905",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.$B$BIf you wish to specialize in potion creation, I would recommend that you seek the help of Lauranna Thar'well of the Cenarion Expedition.$B$BHer knowledge of plants will allow you to make the most of your raw materials.  Look for her in Zangarmarsh and tell her I sent you to her.",logDesc="Speak to Lauranna Thar'well at Cenarion Refuge in Zangarmarsh.$B$B*WARNING!* You can only select one alchemy specialization."} end
if not DB[10906] then DB[10906]={id=10906,zoneId=-181,name="Master of Elixirs",level=70,minLevel=68,giver="Apothecary Antonivich",giverType="NPC",giverId=16588,ender="Lorokeem",enderType="NPC",enderId=19052,rewardNextId=10902,poiX=226,poiY=2839,wowhead="https://www.wowhead.com/wotlk/quest=10906",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.$B$BIf you wish to specialize in elixir creation, I would recommend that you seek the help of the arakkoa known as Lorokeem.$B$BHis knowledge of elixirs is unmatched, yet he  squanders his skill pursuing an elixir of eternal life.  Find him and see what he can teach you.",logDesc="Speak to Lorokeem in Shattrath's Lower City.$B$B*WARNING!* You can only select one alchemy specialization."} end
if not DB[10907] then DB[10907]={id=10907,zoneId=-181,name="Master of Transmutation",level=70,minLevel=68,giver="Apothecary Antonivich",giverType="NPC",giverId=16588,ender="Zarevhi",enderType="NPC",enderId=22427,rewardNextId=10899,poiX=226,poiY=2839,wowhead="https://www.wowhead.com/wotlk/quest=10907",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.$B$BIf you wish to specialize in transmutation, I would recommend that you seek the help of the ethereal known as Zarevhi.  He resides in the Stormspire in Netherstorm.$B$BHis mastery of transmutation is... well, outlandish!  See what you can learn from him, but beware - ethereals drive a hard bargain.",logDesc="Speak to Zarevhi at the Stormspire in Netherstorm.$B$B*WARNING!* You can only select one alchemy specialization."} end
if not DB[10908] then DB[10908]={id=10908,zoneId=3519,name="Speak with Rilak the Redeemed",level=63,minLevel=62,giver="Kirrik the Awakened",giverType="NPC",giverId=22272,ender="Rilak the Redeemed",enderType="NPC",enderId=22292,rewardNextId=10847,poiX=-2855,poiY=5054,wowhead="https://www.wowhead.com/wotlk/quest=10908",image="assets/images/quests/placeholder.png",xpDiff=1,money=3000,desc="You look surprised to be talking to me. I do not blame you. My people, the arakkoa, deserve to be feared.$b$bSpeak with Rilak the Redeemed in Shattrath City if you wish to know more. He can be found in the northern part of the Lower City, with the other outcasts of Skettis.$b$bAnd, $n, we will speak again.",logDesc="Kirrik the Awakened wants you to speak with Rilak the Redeemed in the Lower City section of Shattrath City."} end
if not DB[10909] then DB[10909]={id=10909,zoneId=3483,name="Fel Spirits",level=61,minLevel=58,giver="Assistant Klatu",giverType="NPC",giverId=22430,ender="Assistant Klatu",enderType="NPC",enderId=22430,poiX=-711,poiY=2734,wowhead="https://www.wowhead.com/wotlk/quest=10909",image="assets/images/quests/placeholder.png",xpDiff=5,money=20000,desc="Colonel Jules was cursed in a battle near the Gor'gaz Outpost, a haunt for Shattered Hand fel orcs.  My master, Barada, works feverishly to cure the poor human, but he needs help.  The Colonel's tormented spirit seeks peace, and his path to peace is, I fear, a path of vengeance.$B$BTake this anchorite relic to Gor'gaz Outpost.  Place it upon the ground near Shattered Hand orcs and defeat them.  This will release their fel spirits -- you must slay those fel spirits for Jules' own spirit's recovery.",logDesc="Klatu in Honor Hold wants you to use the Anchorite Relic at Gor'gaz Outpost southwest of Honor Hold, slay Shattered Hand Berserkers near the relic, and then slay 10 released Fel Spirits to avenge Colonel Jules."} end
if not DB[10910] then DB[10910]={id=10910,zoneId=3522,name="Death's Door",level=68,minLevel=65,giver="Wildlord Antelarion",giverType="NPC",giverId=22127,ender="Evergrove Druid",enderType="NPC",enderId=22423,rewardNextId=10904,poiX=2960,poiY=5465,wowhead="https://www.wowhead.com/wotlk/quest=10910",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Now there is an even greater threat from the Burning Legion.  To the south is a portal known as Death's Door, which opens upon the horrific world where the Legion breeds its deadly hounds.$B$BTo get there, exit Evergrove by heading east up the ramp.  Follow the path south, through the Bladed Gulch, Razaan's Landing, Razor Ridge and the Scalewing Shelf.  Then, take the ramp down into the Vekhaar Stand and enter Death's Door through the tunnel, south of Mok'Nathal.$B$BOnce there, use this druid signal.",logDesc="Use the Druid Signal at Death's Door to call down and speak with an Evergrove Druid."} end
if not DB[10911] then DB[10911]={id=10911,zoneId=3522,name="Fire At Will!",level=68,minLevel=65,giver="Evergrove Druid",giverType="NPC",giverId=22423,ender="Evergrove Druid",enderType="NPC",enderId=22423,rewardNextId=10912,poiX=2148,poiY=5416,wowhead="https://www.wowhead.com/wotlk/quest=10911",image="assets/images/quests/placeholder.png",xpDiff=5,money=39000,desc="Now that the ammunition can affect the Burning Legion, it's time for you to use it.$B$BThere are two warp-gates, which are used for teleportation and enhancement of the void terrors.  One is in the south and the other in the north, and each is within range of a fel cannon.$B$BUse the naturalized ammunition to take control of each fel cannon and destroy the warp-gates.$B$BAttack the gate with artillery to begin, and be prepared to kill its defenders to keep the cannon alive if necessary.",logDesc="Use the Naturalized Ammunition to take control of the Death's Door Fel Cannons.  Use the cannons to destroy both the South Warp-Gate and the North Warp-Gate."} end
if not DB[10912] then DB[10912]={id=10912,zoneId=3522,name="The Hound-Master",level=68,minLevel=65,giver="Evergrove Druid",giverType="NPC",giverId=22423,ender="Wildlord Antelarion",enderType="NPC",enderId=22127,poiX=2148,poiY=5416,wowhead="https://www.wowhead.com/wotlk/quest=10912",image="assets/images/quests/placeholder.png",xpDiff=7,money=117000,desc="Baelmon the Hound-Master must die!  He maintains the ritual that keeps the portal functioning.$B$BThe Death's Door portal is located at the north end of the canyon.  When you find it, you will find Baelmon.$B$BYou're going to need help on this one, so take this wand.  When you battle the Hound-Master, use it and a couple of my friends will come to your aid.$B$BAfter you have defeated Baelmon, return to Wildlord Antelarion.$B$BAnd, $N, thank you for all that you've gone through for us here.",logDesc="Slay Baelmon the Hound-Master.",choiceRewards={{id=31693,qty=1},{id=31696,qty=1},{id=31695,qty=1},{id=31692,qty=1},{id=31691,qty=1},{id=31694,qty=1}}} end
if not DB[10913] then DB[10913]={id=10913,zoneId=3519,name="An Improper Burial",level=65,minLevel=63,giver="Commander Ra'vaj",giverType="NPC",giverId=22446,ender="Commander Ra'vaj",enderType="NPC",enderId=22446,rewardNextId=10914,poiX=-3740,poiY=5409,wowhead="https://www.wowhead.com/wotlk/quest=10913",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Is there nothing that can be done to stem the tide of corruption? My soldiers have been battling the Auchenai for days now with no end in sight. Each casualty, whether Auchenai or Sha'tar, is snatched from the battlefield - their souls lifted and taken to parts unknown.$B$BI will not have it! A proper burial is out of the question but those fiends will not have their souls! Take this torch and travel to the field of battle, directly east of here. Burn every corpse you see! We will not fuel their rituals.",logDesc="Commander Ra'vaj at the Sha'tari Outpost in the Bone Wastes of Terokkar Forest wants you to burn 8 Slain Auchenai Warriors and 8 Slain Sha'tar Vindicators."} end
if not DB[10914] then DB[10914]={id=10914,zoneId=3519,name="A Hero Is Needed",level=65,minLevel=63,giver="Commander Ra'vaj",giverType="NPC",giverId=22446,ender="Commander Ra'vaj",enderType="NPC",enderId=22446,rewardNextId=10915,poiX=-3740,poiY=5409,wowhead="https://www.wowhead.com/wotlk/quest=10914",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is not enough. A hero is needed. Our forces are overwhelmed as the Auchenai continue to grow in number.$B$B<Commander Ra'vaj looks at you.>$B$BWill you be the hero? Return to the field of battle and strike at their soldiers. Keep them occupied so that my scouts can get behind their lines and see what they are creating.",logDesc="Commander Ra'vaj at the Sha'tari Outpost in the Bone Wastes of Terokkar Forest wants you to slay 12 Auchenai Initiates and 5 Auchenai Doomsayers."} end
if not DB[10915] then DB[10915]={id=10915,zoneId=3519,name="The Fallen Exarch",level=65,minLevel=63,giver="Commander Ra'vaj",giverType="NPC",giverId=22446,ender="Commander Ra'vaj",enderType="NPC",enderId=22446,poiX=-3740,poiY=5409,wowhead="https://www.wowhead.com/wotlk/quest=10915",image="assets/images/quests/placeholder.png",xpDiff=5,desc="They are feeding the souls they steal to a coffin that they have dragged out from the Auchenai Crypts. My scouts believe the contents of the coffin to contain the first exarch of the crypts. They seek to resurrect the ancient one!$B$BYou must battle your way to the western side of Auchindoun and disturb the contents of that coffin before they feed it enough souls. Should you lose your way, follow the walking souls.$B$BDestroy whatever is inside that coffin!",logDesc="Commander Ra'vaj at the Sha'tari Outpost in the Bone Wastes of Terokkar Forest wants you to destroy the contents of the Auchenai Coffin.",choiceRewards={{id=31798,qty=1},{id=31797,qty=1},{id=31796,qty=1},{id=31794,qty=1}}} end
if not DB[10916] then DB[10916]={id=10916,zoneId=3483,name="Digging for Prayer Beads",level=61,minLevel=58,giver="Assistant Klatu",giverType="NPC",giverId=22430,ender="Assistant Klatu",enderType="NPC",enderId=22430,poiX=-711,poiY=2734,wowhead="https://www.wowhead.com/wotlk/quest=10916",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Anchorite Barada plans to exorcise the corruption from Colonel Jules, and will require an assistant for the task.  Such an assistant must be prepared...$B$BI am ashamed to admit that my prayer beads were lost in Honor Hold's courtyard.  I believe the dog Fei Fei stole them and buried them, but I do not know where.  If you speak with his master, Warrant Officer Tracy Proudwell, perhaps she will know where Fei Fei hides his stolen treasures.",logDesc="Recover the Draenei Prayer Beads and bring them to Assistant Klatu in Honor Hold."} end
if not DB[10917] then DB[10917]={id=10917,zoneId=3519,name="The Outcast's Plight",level=65,minLevel=62,giver="Vekax",giverType="NPC",giverId=22429,ender="Vekax",enderType="NPC",enderId=22429,poiX=-1669,poiY=5532,wowhead="https://www.wowhead.com/wotlk/quest=10917",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="As an outcast, I am marked by death by arakkoa loyal to the city of Skettis.  I cannot leave these walls for fear of my life, but that doesn't mean I cannot strike at them in retaliation.$B$BI have a small cache of treasure that I'm willing to part with, should you help me strike back at my would-be assassins.  Bring me feathers from the denizens of the various Veils of Terokkar as proof of their demise.",logDesc="Bring 30 Arakkoa Feathers to Vekax in Shattrath's Lower City.",rewards={{id=31800,qty=1}}} end
if not DB[10918] then DB[10918]={id=10918,zoneId=3519,name="More Feathers",level=65,minLevel=62,giver="Vekax",giverType="NPC",giverId=22429,ender="Vekax",enderType="NPC",enderId=22429,poiX=-1669,poiY=5532,wowhead="https://www.wowhead.com/wotlk/quest=10918",image="assets/images/quests/placeholder.png",rewards={{id=31800,qty=1}}} end
if not DB[10919] then DB[10919]={id=10919,zoneId=3483,name="Fei Fei's Treat",level=61,minLevel=1,giver="Fei Fei",giverType="NPC",giverId=20206,ender="Fei Fei",enderType="NPC",enderId=20206,poiX=-685,poiY=2626,wowhead="https://www.wowhead.com/wotlk/quest=10919",image="assets/images/quests/placeholder.png"} end
if not DB[10920] then DB[10920]={id=10920,zoneId=3519,name="For the Fallen",level=65,minLevel=63,giver="Vindicator Haylen",giverType="NPC",giverId=22462,ender="Vindicator Haylen",enderType="NPC",enderId=22462,rewardNextId=10921,poiX=-3743,poiY=4399,wowhead="https://www.wowhead.com/wotlk/quest=10920",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When the dreadfang widows attacked our outpost we heard the voice of the naaru calling us to battle.  We pursued the creatures into the night.  Some of our people we found dead in the dark, others we could hear struggling against their captors. $B$BBy morning we had come to this place and we fought a fierce battle but we were beaten.  Dreadfang poison will soon take my companions and I cannot last long.  Before I die I must know that the dreadfang widows were beaten.",logDesc="Vindicator Haylen wants you to slay 20 Dreadfang Widows and then return to him just west of Netherweb Ridge."} end
if not DB[10921] then DB[10921]={id=10921,zoneId=3519,name="Terokkarantula",level=65,minLevel=63,giver="Vindicator Haylen",giverType="NPC",giverId=22462,ender="Vindicator Haylen",enderType="NPC",enderId=22462,rewardNextId=10926,poiX=-3743,poiY=4399,wowhead="https://www.wowhead.com/wotlk/quest=10921",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have slain many of the dreadfang widows but they will continue to spawn and soon they will strike at us again.  Deep within Netherweb Ridge is the lair of the Terokkarantula, the brood-mother of these gruesome creatures.  If we are to be safe, she must die.  ",logDesc="Vindicator Haylen wants you to kill the Terokkarantula and then return to him west of Netherweb Ridge.",choiceRewards={{id=31821,qty=1},{id=31820,qty=1},{id=31819,qty=1},{id=31823,qty=1}}} end
if not DB[10922] then DB[10922]={id=10922,zoneId=3519,name="Digging Through Bones",level=65,minLevel=63,giver="Chief Archaeologist Letoll",giverType="NPC",giverId=22458,ender="Dwarfowitz",enderType="NPC",enderId=22481,rewardNextId=10929,poiX=-3741,poiY=5404,wowhead="https://www.wowhead.com/wotlk/quest=10922",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Oy! You look like you can take care of yerself, $r. Me and the crew here are looking for a bodyguard to watch over us while we hit a dig site to the north. The pay is pretty good and all you gotta do is make sure no nasty creatures kill me or any of my employees.$B$BIf you successfully make it back without any casualties, Dwarfowitz over there will pay ya.",logDesc="Escort Letoll and his crew and protect them while they make their dig. Return to Dwarfowitz at the Sha'tari Outpost if you succeed.$B"} end
if not DB[10923] then DB[10923]={id=10923,zoneId=3519,name="Evil Draws Near",level=65,minLevel=63,giver="Oakun",giverType="NPC",giverId=22456,ender="Oakun",enderType="NPC",enderId=22456,poiX=-3755,poiY=5406,wowhead="https://www.wowhead.com/wotlk/quest=10923",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now you must use the Dread Relic in a foul necromantic ritual if you wish to challenge Teribus the Cursed.  To the northeast, beyond Auchindoun, is the Writhing Mound, a place where necromancers gather.  $B$BThe auchenai death-speakers and doomsayers carry doom skulls that are laced with powerful necro-enchantments.  If you collect enough skulls you can use their power along with the power of the Dread Relic to command Teribus to face you.",logDesc="Oakun wants you to take the Dread Relic to the Writhing Mound.  Once there, kill Auchenai Death-Speakers and Auchenai Doomsayers to collect 20 Doom Skulls.  Then find the Writhing Mound Summoning Circle and use the Dread Relic to summon and destroy Teribus the Cursed.  Return to Oakun when the deed is done.",choiceRewards={{id=31816,qty=1},{id=31817,qty=1},{id=31818,qty=1}}} end
if not DB[10924] then DB[10924]={id=10924,zoneId=3523,name="Bloody Imp-ossible!",level=69,minLevel=67,giver="Sab'aoth",giverType="NPC",giverId=22479,ender="Sab'aoth",enderType="NPC",enderId=22479,poiX=2955,poiY=1782,wowhead="https://www.wowhead.com/wotlk/quest=10924",image="assets/images/quests/placeholder.png",xpDiff=5,money=41000,desc="The blood of the warp chasers in this area is a powerful and rare reagent. It's one of my biggest sellers.$B$BNormally, I take my imp, Zeppit, out to help me gather it. Warp chaser blood is simply too caustic to be handled safely by you or I, but it doesn't bother Zeppit.$B$BThings are getting busier here at the shop, so if I send Zeppit with you, will you help gather the blood? Zeppit's attention tends to wander, so you'll need to be close to the chaser when it dies for Zeppit to do his work.",logDesc="Bring 8 vials of Warp Chaser Blood to Sab'aoth at Cosmowrench."} end
if not DB[10925] then DB[10925]={id=10925,zoneId=3519,name="Evil Draws Near",level=255,minLevel=255,wowhead="https://www.wowhead.com/wotlk/quest=10925",image="assets/images/quests/placeholder.png"} end
if not DB[10926] then DB[10926]={id=10926,zoneId=3519,name="Return to Sha'tari Base Camp",level=65,minLevel=63,giver="Vindicator Haylen",giverType="NPC",giverId=22462,ender="Scout Navrin",enderType="NPC",enderId=22364,poiX=-3743,poiY=4399,wowhead="https://www.wowhead.com/wotlk/quest=10926",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We will not make it back on our own.  The dreadfang poison is too strong. You must return to Sha'tari Base Camp for us.  Scout Navrin will send a rescue party out to find us.",logDesc="Vindicator Haylen wants you to return to the Sha'tari Base Camp in the Bone Wastes and speak with Scout Navrin."} end
if not DB[10927] then DB[10927]={id=10927,zoneId=3522,name="Killing the Crawlers",level=65,minLevel=65,giver="Sentinel Moonwhisper",giverType="NPC",giverId=22488,ender="Commander Skyshadow",enderType="NPC",enderId=21158,poiX=1113,poiY=7099,wowhead="https://www.wowhead.com/wotlk/quest=10927",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="Commander Skyshadow wants this tunnel cleared out so we can expedite trade with the Harborage. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Commander Skyshadow at once!$B",logDesc="Slay 6 Cavern Crawlers."} end
if not DB[10928] then DB[10928]={id=10928,zoneId=3522,name="Killing the Crawlers",level=65,minLevel=65,giver="Grunt Grahk",giverType="NPC",giverId=22489,ender="Tor'chunk Twoclaws",enderType="NPC",enderId=21147,poiX=929,poiY=5973,wowhead="https://www.wowhead.com/wotlk/quest=10928",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="Tor'chunk Twoclaws wants this tunnel cleared out so we can expedite trade with Swamp Rat. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Tor'chunk Twoclaws at once!$B",logDesc="Slay 6 Cavern Crawlers."} end
if not DB[10929] then DB[10929]={id=10929,zoneId=3519,name="Fumping",level=65,minLevel=63,giver="Dwarfowitz",giverType="NPC",giverId=22481,ender="Dwarfowitz",enderType="NPC",enderId=22481,rewardNextId=10930,poiX=-3743,poiY=5410,wowhead="https://www.wowhead.com/wotlk/quest=10929",image="assets/images/quests/placeholder.png",xpDiff=5,desc="How would you like to do a little more work for the Explorers' League? These bone worms have us all quite intrigued.$B$BI've got a drum right here that you can use out in the Bone Wastes. Just bang on the damned thing and see what you get. If it's a worm, kill it and bring back the carcass for us to study. We'll need a good lot of carcasses to get a valid testing sample.",logDesc="Dwarfowitz at the Sha'tari Base Camp in the Bone Wastes wants you to bring him 8 Mature Bone Sifter Carcasses."} end
if not DB[10930] then DB[10930]={id=10930,zoneId=3519,name="The Big Bone Worm",level=65,minLevel=63,giver="Dwarfowitz",giverType="NPC",giverId=22481,ender="Dwarfowitz",enderType="NPC",enderId=22481,poiX=-3743,poiY=5410,wowhead="https://www.wowhead.com/wotlk/quest=10930",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I was right! These carcasses you brought me belong to the baby bone worms. Do you know what that means? It means that somewhere out there is a big one! I think we can get it to come out if we can provide the right kind of food. Let's see... something big! Yes!$B$BI remember seeing clefthooves east of here on the other side of the Bone Wastes. Get out there and kill a clefthoof. Once it's dead, use the drums. Hopefully the big one will come up to feed. If you manage to kill it, bring me its organs!",logDesc="Dwarfowitz at the Sha'tari Base Camp in the Bone Wastes wants you to recover Enormous Bone Worm Organs.$B$BHe wants his Fumper back too.$B",choiceRewards={{id=31756,qty=1},{id=31758,qty=1},{id=31759,qty=1}}} end
if not DB[10931] then DB[10931]={id=10931,zoneId=-262,name="Return to the Exodar",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=10931",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Your master Caedmos of the Exodar has requested to see you.  It concerns your training, but I don't really know anything beyond that.",logDesc="Speak with Caedmos at the Exodar."} end
