if not DB[10933] then DB[10933]={id=10933,zoneId=-262,name="Return to Silvermoon",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=10933",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Your master Aldrae in Silvermoon City has requested to see you.  It concerns your training, but I don't really know anything beyond that.",logDesc="Speak with Aldrae in Silvermoon City."} end
if not DB[10934] then DB[10934]={id=10934,zoneId=-262,name="Return to Silvermoon",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=10934",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Your master Aldrae in Silvermoon City has requested to see you.  It concerns your training, but I don't really know anything beyond that.",logDesc="Speak with Aldrae in Silvermoon City."} end
if not DB[10935] then DB[10935]={id=10935,zoneId=3483,name="The Exorcism of Colonel Jules",level=61,minLevel=58,giver="Assistant Klatu",giverType="NPC",giverId=22430,ender="Assistant Klatu",enderType="NPC",enderId=22430,rewardNextId=10936,poiX=-711,poiY=2734,wowhead="https://www.wowhead.com/wotlk/quest=10935",image="assets/images/quests/placeholder.png",xpDiff=6,money=40000,desc="$n, it is time to save Colonel Jules.  His condition has worsened and Barada fears that, if we do not cleanse him of his corruption,  he will be lost to us.$B$BTake the prayer beads you found and speak with Anchorite Barada to begin the ritual.  Let no disruptions stop the ritual... and if all goes well, Colonel Jules will be saved.  Speak with Jules when he is saved, then return to me.",logDesc="Speak with Anchorite Barada.  Use the prayer beads to help with the ritual, and then speak with Colonel Jules when he is saved.  Finally, return to Assistant Klatu."} end
if not DB[10936] then DB[10936]={id=10936,zoneId=3483,name="Trollbane is Looking for You",level=61,minLevel=58,giver="Assistant Klatu",giverType="NPC",giverId=22430,ender="Force Commander Danath Trollbane",enderType="NPC",enderId=16819,rewardNextId=10937,poiX=-711,poiY=2734,wowhead="https://www.wowhead.com/wotlk/quest=10936",image="assets/images/quests/placeholder.png",xpDiff=1,desc="While we were busy, a messenger was waiting out in the hall.  I suppose he grew tired, or perhaps he simply ran away at the sight of Jules floating around the room.$B$BEither way, Force Commander Danath is looking for you.  I suggest that you seek an audience with him inside the barracks as quickly as possible!",logDesc="Assistant Klatu has informed you that Force Commander Danath Trollbane has been seeking you.  Speak to him in the barracks at Honor Hold in Hellfire Peninsula."} end
if not DB[10937] then DB[10937]={id=10937,zoneId=3483,name="Drill the Drillmaster",level=62,minLevel=58,giver="Force Commander Danath Trollbane",giverType="NPC",giverId=16819,ender="Force Commander Danath Trollbane",enderType="NPC",enderId=16819,poiX=-816,poiY=2614,wowhead="https://www.wowhead.com/wotlk/quest=10937",image="assets/images/quests/placeholder.png",xpDiff=6,money=54000,desc="I'm receiving reports that the Shattered Hand fel orcs, out in front of Hellfire Citadel, are organizing for what looks like an all-out assault.  No doubt, they're not happy about your successes against all of the clans.$B$BGet to the base of the citadel, where the Path of Glory ends.  You'll find the fel orcs busy with their preparations, but you're going to catch them with their pants down.$B$BEliminate the one that's in charge of that force.  Kill Drillmaster Zurok!",logDesc="Force Commander Danath Trollbane has ordered you to kill Drillmaster Zurok with all due haste.  Return to the force commander at Honor Hold in the Hellfire Peninsula once the drillmaster is dead.",choiceRewards={{id=31719,qty=1},{id=31718,qty=1},{id=31717,qty=1},{id=31720,qty=1}}} end
if not DB[10938] then DB[10938]={id=10938,zoneId=-364,name="Darkmoon Blessings Deck",level=70,minLevel=1,ender="Professor Thaddeus Paleo",enderType="NPC",enderId=14847,wowhead="https://www.wowhead.com/wotlk/quest=10938",image="assets/images/quests/placeholder.png",desc="Now that you have gathered all of the Blessings cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.",logDesc="Return the Blessings Deck to the Darkmoon Faire when it comes to town.",rewards={{id=31856,qty=1}}} end
if not DB[10939] then DB[10939]={id=10939,zoneId=-364,name="Darkmoon Storms Deck",level=70,minLevel=1,ender="Professor Thaddeus Paleo",enderType="NPC",enderId=14847,wowhead="https://www.wowhead.com/wotlk/quest=10939",image="assets/images/quests/placeholder.png",desc="Now that you have gathered all of the Storms cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.",logDesc="Return the Storms Deck to the Darkmoon Faire when it comes to town.",rewards={{id=31857,qty=1}}} end
if not DB[10940] then DB[10940]={id=10940,zoneId=-364,name="Darkmoon Furies Deck",level=70,minLevel=1,ender="Professor Thaddeus Paleo",enderType="NPC",enderId=14847,wowhead="https://www.wowhead.com/wotlk/quest=10940",image="assets/images/quests/placeholder.png",desc="Now that you have gathered all of the Furies cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.",logDesc="Return the Furies Deck to the Darkmoon Faire when it comes to town.",rewards={{id=31858,qty=1}}} end
if not DB[10941] then DB[10941]={id=10941,zoneId=-364,name="Darkmoon Lunacy Deck",level=70,minLevel=1,ender="Professor Thaddeus Paleo",enderType="NPC",enderId=14847,wowhead="https://www.wowhead.com/wotlk/quest=10941",image="assets/images/quests/placeholder.png",desc="Now that you have gathered all of the Lunacy cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.",logDesc="Return the Lunacy Deck to the Darkmoon Faire when it comes to town.",rewards={{id=31859,qty=1}}} end
if not DB[10942] then DB[10942]={id=10942,zoneId=-284,name="Children's Week",level=-1,minLevel=60,ender="Blood Elf Orphan",enderType="NPC",enderId=22817,wowhead="https://www.wowhead.com/wotlk/quest=10942",image="assets/images/quests/placeholder.png",desc="One special little girl is going to be very happy to have you as a friend, even if it is for a short while.$B$BTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.$B$BPlease, $N, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!",logDesc="Use the Blood Elf Orphan Whistle to call for the ward that you will be looking after during Children's Week."} end
if not DB[10943] then DB[10943]={id=10943,zoneId=-284,name="Children's Week",level=-1,minLevel=60,ender="Draenei Orphan",enderType="NPC",enderId=22818,wowhead="https://www.wowhead.com/wotlk/quest=10943",image="assets/images/quests/placeholder.png",desc="One special little girl is going to be very happy to have you as a friend, even if it is for a short while.$B$BTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.$B$BPlease, $N, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!",logDesc="Use the Draenei Orphan Whistle to call for the ward that you will be looking after during Children's Week."} end
if not DB[10944] then DB[10944]={id=10944,zoneId=3520,name="The Secret Compromised",level=70,minLevel=70,giver="Seer Olum",giverType="NPC",giverId=22820,ender="Akama",enderType="NPC",enderId=21700,poiX=451,poiY=-545,wowhead="https://www.wowhead.com/wotlk/quest=10944",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="Thanks again, $N.  I recognize your name.  Akama has entrusted you with his plans and so I will trust you as well.$B$BThe naga discovered I was working against Illidan and tried to get me to speak by torturing me.  I did not tell them a thing - Akama himself taught me to master pain through meditation.$B$BIllidan asked the naga to bring me to him.  He would have seen right through my flesh and into my soul's deepest secrets.$B$BAkama must be warned.  Our plans are in jeopardy!",logDesc="Travel to the Warden's Cage in Shadowmoon Valley and speak to Akama."} end
if not DB[10945] then DB[10945]={id=10945,zoneId=-284,name="Hch'uu and the Mushroom People",level=-1,minLevel=60,ender="Hch'uu",enderType="NPC",enderId=22823,wowhead="https://www.wowhead.com/wotlk/quest=10945",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I had a friend named Hch'uu.  She told me that she ended up in the orphanage because she had to run away from an evil fungal giant and got lost.$B$BWe had great fun until her people came and took her away last year.  I think she said she was going to live at a place called Sporeggar.$B$BI'd like to go to see her and have a look at her mushroom village.  The orphan matron told me that it is on the west side of Zangarmarsh, between the Sporewind and Marshlight lakes.$B$BCan we go?  Can we go?  Please?!",logDesc="Take your orphan, Salandria, to Sporeggar in Zangarmarsh.  Make sure to call for her if she is not present when you arrive.  Then, speak with Hch'uu."} end
if not DB[10946] then DB[10946]={id=10946,zoneId=3845,name="Ruse of the Ashtongue",level=70,minLevel=70,giver="Akama",giverType="NPC",giverId=21700,ender="Akama",enderType="NPC",enderId=21700,rewardNextId=10947,poiX=-3715,poiY=1029,wowhead="https://www.wowhead.com/wotlk/quest=10946",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Olum's sacrifice was tremendous.  I would never have asked him to give up his life myself.  But it is done.$B$BIf we're to lure Illidan back into a false sense of security, we need to do his bidding - at least for now.$B$BI command a vast army of Ashtongue, but - aside from the Deathsworn - none can be trusted.$B$BYou are to perform the deed that Illidan demands.  Take this cowl; it is magical in nature.  You will appear to be one of my men to any who see you slaying Kael's phoenix, Al'ar.",logDesc="Travel into Tempest Keep and slay Al'ar while wearing the Ashtongue Cowl.  Return to Akama in Shadowmoon Valley once you've completed this task."} end
if not DB[10947] then DB[10947]={id=10947,zoneId=3606,name="An Artifact From the Past",level=70,minLevel=70,giver="Akama",giverType="NPC",giverId=21700,ender="Akama",enderType="NPC",enderId=21700,rewardNextId=10948,poiX=-3715,poiY=1029,wowhead="https://www.wowhead.com/wotlk/quest=10947",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Illidan's attention is now on Kael'thas, thanks to you.  The time has come to make our move.$B$BI've had a vision of an artifact that will aid us in our final struggle - the phylactery of a lich known as Winterchill.  Unfortunately its power was lost forever after his defeat in the Battle of Mount Hyjal.$B$BThere might be a way to retrieve this artifact, however.  Legend speaks of a place in Azeroth guarded by bronze dragons...  a place where past and present meet.  It is there you will find what we seek.",logDesc="Go to the Caverns of Time in Tanaris and gain access to the Battle of Mount Hyjal.  Once inside, defeat Rage Winterchill and bring the Time-Phased Phylactery to Akama in Shadowmoon Valley."} end
if not DB[10948] then DB[10948]={id=10948,zoneId=3703,name="The Hostage Soul",level=70,minLevel=70,giver="Akama",giverType="NPC",giverId=21700,ender="A'dal",enderType="NPC",enderId=18481,rewardNextId=10949,poiX=-3715,poiY=1029,wowhead="https://www.wowhead.com/wotlk/quest=10948",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You might wonder why I go to such lengths to hide my intentions.  Why not throw my lot in openly with the naaru?$B$BMy very essence - my soul - is held prisoner inside the Black Temple.  Illidan could destroy me any moment... until now!  This phylactery will allow me to regain control of my soul.$B$BThe time has come, $N.  I'll lead Maiev and my Deathsworn to Illidan's doorstep.$B$BSpeak to A'dal and and tell him of our plan.  If we strike together we'll break through Illidan's defenses.",logDesc="Travel to Shattrath City to tell A'dal about Akama's request."} end
if not DB[10949] then DB[10949]={id=10949,zoneId=3520,name="Entry Into the Black Temple",level=70,minLevel=70,giver="A'dal",giverType="NPC",giverId=18481,ender="3",enderType="NPC",enderId=18528,rewardNextId=13429,poiX=-1864,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=10949",image="assets/images/quests/placeholder.png",xpDiff=4,money=44000,desc="<A'dal shows you an image of a naaru outside of the Black Temple, fighting alongside draenei vindicators and blood elf magisters.  You immediately understand that this is the distraction Akama is waiting for.>",logDesc="Travel to the entrance to the Black Temple in Shadowmoon Valley and speak to Xi'ri."} end
if not DB[10950] then DB[10950]={id=10950,zoneId=-284,name="Auchindoun and the Ring of Observance",level=-1,minLevel=60,ender="Draenei Orphan",enderType="NPC",enderId=22818,wowhead="https://www.wowhead.com/wotlk/quest=10950",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One of the priests that comes to visit told a story about a place nearby.  It's called Auchindoun, and it's supposed to be very important to the draenei.$B$BHe said it used to be the place where the bodies of the draenei were taken when they died.  But some time ago, something bad blew it up.$B$BI'd like to see its Ring of Observance.  The orphan matron told me that it is in the middle of the Bone Wastes, on the south side of the Terokkar Forest.$B$BPlease, $G Mr. : Miss; $N, can we go?",logDesc="Take your orphan, Dornaa, to the Meeting Stone at the Ring of Observance in the middle of Auchindoun.  Auchindoun, in turn, is in the middle of Terokkar Forest's Bone Wastes.  Make sure to call for her if she is not present when you arrive."} end
if not DB[10951] then DB[10951]={id=10951,zoneId=-284,name="A Trip to the Dark Portal",level=-1,minLevel=60,ender="Blood Elf Orphan",enderType="NPC",enderId=22817,wowhead="https://www.wowhead.com/wotlk/quest=10951",image="assets/images/quests/placeholder.png",xpDiff=5,desc="How can we look at all of these interesting places and not see the Dark Portal?!$B$BThe grown-ups are always trying to tell us scary stories about it and how it's so dangerous, with lots of demons, and stuff.$B$B<Salandria rolls her eyes.>$B$BBut you're here, so it can't be too bad, right?$B$BI want to see for myself.  You remember where it is on the east edge of Hellfire Peninsula?",logDesc="Take your orphan, Salandria, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula.  Make sure to call for her if she is not present when you arrive."} end
if not DB[10952] then DB[10952]={id=10952,zoneId=-284,name="A Trip to the Dark Portal",level=-1,minLevel=60,ender="Draenei Orphan",enderType="NPC",enderId=22818,wowhead="https://www.wowhead.com/wotlk/quest=10952",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There's one place that if we don't go anywhere else, we have to go to: the Dark Portal!$B$BThe orphan matrons are always trying to scare us with stories about how dangerous it is, with lots of demons, and people like you coming through it.$B$B<Dornaa rolls her eyes.>$B$BBut you're here, and nice, so it can't be too bad, right?$B$BI want to see it for myself.  You remember where it is on the eastern edge of Hellfire Peninsula?",logDesc="Take your orphan, Dornaa, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula.  Make sure to call for her if she is not present when you arrive."} end
if not DB[10953] then DB[10953]={id=10953,zoneId=-284,name="Visit the Throne of the Elements",level=-1,minLevel=60,ender="Elementalist Sharvak",enderType="NPC",enderId=18072,wowhead="https://www.wowhead.com/wotlk/quest=10953",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Have you heard of the Throne of the Elements?  It's supposed to be this place in Nagrand where there are these powerful elementals.$B$BOne day soon, I'm going to be a powerful mage, or maybe a warlock.  I'm gonna have to learn about some of the elemental forces!$B$BDo you think maybe that we could go there?$B$B<Salandria looks at you slyly.>$B$BYa know, it would be educational to go there.  It's supposedly just north of Garadar, on the other side of Skysong Lake.",logDesc="Take your orphan, Salandria, to the Throne of the Elements in Nagrand.  Make sure to call for her if she is not present when you arrive.  Then, speak with Elementalist Sharvak."} end
if not DB[10954] then DB[10954]={id=10954,zoneId=-284,name="Jheel is at Aeris Landing!",level=-1,minLevel=60,ender="Jheel",enderType="NPC",enderId=22836,wowhead="https://www.wowhead.com/wotlk/quest=10954",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I miss my brother, Jheel.  He's a couple of years older than me, so they let him start an apprenticeship with the ethereal in Nagrand.$B$BIt sure would be nice to go visit him.  He loves geology and stuff, so I bet he's having a great time.$B$BThe orphan matron told me that he's training at a place called Aeris Landing in Nagrand.  It's supposed to be along the road, far to the west of Telaar, and northwest of the great mountain, Oshu'gun.",logDesc="Take your orphan, Dornaa, to Aeris Landing in Nagrand.  Make sure to call for her if she is not present when you arrive.  Then, speak with Jheel."} end
if not DB[10955] then DB[10955]={id=10955,zoneId=-263,name="Morthis Whisperwing",level=-1,minLevel=70,giver="Loganaar",giverType="NPC",giverId=12042,ender="Morthis Whisperwing",enderType="NPC",enderId=22832,rewardNextId=10961,poiX=7867,poiY=-2594,wowhead="https://www.wowhead.com/wotlk/quest=10955",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Before all of the druidic orders coalesced into the Cenarion Circle, the Druids of the Talon were responsible for teaching promising young druids the mysteries of flight. With the dissolution of the order, former members teach the skill sparingly.$B$BEven now, Morthis Whisperwing continues his search for a suitable apprentice. Few druids have truly mastered all the forms available to them, but you show the promise Morthis requires of his students. Seek him out at the Cenarion Refuge in Zangarmarsh.",logDesc="Seek out Morthis Whisperwing at the Cenarion Refuge in Zangarmarsh."} end
if not DB[10956] then DB[10956]={id=10956,zoneId=-284,name="The Seat of the Naaru",level=-1,minLevel=60,ender="O'ros",enderType="NPC",enderId=17538,rewardNextId=10968,wowhead="https://www.wowhead.com/wotlk/quest=10956",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Do you know anything about the naaru?  They're these angelic beings that have been helping the draenei for a really long time.  I've seen a bunch around Shattrath.$B$BThey say that one naaru, O'ros, was with the Exodar when it traveled to your homeworld.  I should like to see for myself.$B$BCan you take me there?  I bet we could get there fast by using one of the portals inside the Terrace of Light at Shattrath City!  When we get there, if you get lost, we could always just look at your map.",logDesc="Take your orphan, Dornaa, to stand before O'ros at the bottom of the Seat of the Naaru inside of the Exodar, which is on Azuremyst Isle.  Make sure to call for her if she is not present when you arrive.$B$BRemember that you can use your map inside the city."} end
if not DB[10957] then DB[10957]={id=10957,zoneId=3840,name="Redemption of the Ashtongue",level=70,minLevel=70,giver="Seer Kanai",giverType="NPC",giverId=23158,ender="Seer Kanai",enderType="NPC",enderId=23158,rewardNextId=10959,poiX=703,poiY=190,wowhead="https://www.wowhead.com/wotlk/quest=10957",image="assets/images/quests/placeholder.png",xpDiff=7,desc="When Illidan obtained the Broken's allegiance, Akama was our wisest.  He knew that openly opposing the Betrayer would lead to the extinction of our race.$B$BInstead he has plotted and schemed for this very moment under utmost secrecy.  Failure would be catastrophic... not just for Akama, not just for the Broken, but for all of Outland.  No one this close to Illidan has ever been able to deliver such a terrible blow to him.$B$BHelp Akama free his soul and he will grant you access to Illidan's sanctum.",logDesc="Help Akama wrest control back of his soul by defeating the Shade of Akama inside the Black Temple.  Return to Seer Kanai when you've completed this task."} end
if not DB[10958] then DB[10958]={id=10958,zoneId=3840,name="Seek Out the Ashtongue",level=70,minLevel=70,giver="3",giverType="NPC",giverId=18528,ender="Seer Kanai",enderType="NPC",enderId=23158,rewardNextId=10957,poiX=-3560,poiY=638,wowhead="https://www.wowhead.com/wotlk/quest=10958",image="assets/images/quests/placeholder.png",xpDiff=6,desc="<As you look up at Xi'ri, your mind becomes focused and your will determined.  Your work here is not done; you must go inside the Black Temple and find Akama's followers.>$B$B<Much depends on Akama's success.>",logDesc="Find Akama's Deathsworn inside the Black Temple."} end
if not DB[10959] then DB[10959]={id=10959,zoneId=3840,name="The Fall of the Betrayer",level=70,minLevel=70,giver="Seer Kanai",giverType="NPC",giverId=23158,ender="Seer Kanai",enderType="NPC",enderId=23158,poiX=703,poiY=190,wowhead="https://www.wowhead.com/wotlk/quest=10959",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="With Illidan's lieutenants defeated, Akama will be able to force open the doors to Illidan's sanctum.  Be ready to bring your force inside as soon as Akama does.$B$BWe still do not know what has become of Maiev, but we must make our move without her.$B$BI hope your force is up to the task.  Illidan will not be pleased to see Akama.",logDesc="Seer Kanai wants you to defeat Illidan inside the Black Temple.",rewards={{id=32757,qty=1}}} end
if not DB[10960] then DB[10960]={id=10960,zoneId=-284,name="When I Grow Up...",level=-1,minLevel=60,ender="3",enderType="NPC",enderId=17076,wowhead="https://www.wowhead.com/wotlk/quest=10960",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When you were my age did you know that you wanted to be a $c when you grew up?$B$BI'm not sure what I want to be.  Maybe a mage or a warlock, like I said before?  Or maybe a paladin Blood Knight?  Yeah, definitely a Blood Knight!$B$BThey say that the true ones are trained in Silvermoon City on your world.  Could you take me there?  The stories that I've heard say that the paladin trainers reside in the Farstriders' Square in that city.$B$BPlease take me there.  Please!",logDesc="Take your orphan, Salandria, to the paladin trainers in Silvermoon City's Farstriders' Square.  Make sure to call for her if she is not present when you arrive.  Then, speak with Lady Liadrin, the Blood Knight Matriarch.$B$BRemember that you can use your map inside the city, and speak to the guards to find the paladin trainers."} end
if not DB[10961] then DB[10961]={id=10961,zoneId=-263,name="The Ward of Wakening",level=-1,minLevel=70,giver="Morthis Whisperwing",giverType="NPC",giverId=22832,ender="Morthis Whisperwing",enderType="NPC",enderId=22832,poiX=-249,poiY=5444,wowhead="https://www.wowhead.com/wotlk/quest=10961",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Long ago, the relics used to teach the ways of the stormcrow were entrusted to an ancient druid.$B$BYour training requires these relics, so we must wake their guardian from his slumber.$B$BI will prepare a potion you can use to ease the process. The mixture requires common herbs, as well as bogblossom, which usually grows atop the tallest mushrooms in the marsh. Fly up there and pursue them but take care, as they're quite fragile and may explode violently if mishandled.",logDesc="Bring 10 Bogblossoms, 10 Ancient Lichen, and 10 Dreaming Glory to Morthis Whisperwing at the Cenarion Refuge."} end
if not DB[10962] then DB[10962]={id=10962,zoneId=-284,name="Time to Visit the Caverns",level=-1,minLevel=60,ender="Draenei Orphan",enderType="NPC",enderId=22818,wowhead="https://www.wowhead.com/wotlk/quest=10962",image="assets/images/quests/placeholder.png",xpDiff=5,desc="In the orphanage, the old priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.$B$BI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!$B$BDo you think that we could go there?  He said that the entrance was on the eastern edge of a great desert named Tanaris.$B$BMaybe you could buy me a souvenir while we're there?",logDesc="Take your orphan, Dornaa, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time.  Make sure to call for her if she is not present when you arrive.$B$BThen, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel."} end
if not DB[10963] then DB[10963]={id=10963,zoneId=-284,name="Time to Visit the Caverns",level=-1,minLevel=60,ender="Blood Elf Orphan",enderType="NPC",enderId=22817,wowhead="https://www.wowhead.com/wotlk/quest=10963",image="assets/images/quests/placeholder.png",xpDiff=5,desc="In the orphanage, the old stinky priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.$B$BI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!$B$BI think we should go there.  He said that the entrance was on the eastern edge of a great desert named Tanaris.$B$BYou could buy me a souvenir while we're there!",logDesc="Take your orphan, Salandria, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time.  Make sure to call for her if she is not present when you arrive.$B$BThen, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel."} end
if not DB[10964] then DB[10964]={id=10964,zoneId=-263,name="Waking the Sleeper",level=-1,minLevel=70,giver="Morthis Whisperwing",giverType="NPC",giverId=22832,ender="Clintar Dreamwalker",enderType="NPC",enderId=22834,poiX=-249,poiY=5444,wowhead="https://www.wowhead.com/wotlk/quest=10964",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Take the ward with you and travel to Moonglade, to the Stormrage Barrow Dens. Within the southernmost of the Stormrage Barrow Dens, watched over by the dreamwardens, you will find Clintar Dreamwalker.$B$BAdminister the potion and watch over him while he wakes. He'll be extremely vulnerable as his spirit reunites with his body and he certainly won't recognize you. Declare yourself to him as soon as he comes around, $N. He will need your help to gather the relics for the ceremony.",logDesc="Use the Ward of Waking to help Clintar Dreamwalker emerge from the Emerald Dream. When he is conscious, speak to him."} end
if not DB[10965] then DB[10965]={id=10965,zoneId=-263,name="No Mere Dream",level=-1,minLevel=70,giver="Clintar Dreamwalker",giverType="NPC",giverId=22834,ender="Dreamwarden Lurosa",enderType="NPC",enderId=22837,rewardNextId=10978,poiX=7459,poiY=-3123,wowhead="https://www.wowhead.com/wotlk/quest=10965",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="<Clintar listens as you relay Morthis' instructions, nodding, but clearly fearful.>$B$BI cannot extricate myself fully from the Emerald Dream to help you, but a fragment of my spirit will guide you in your search for the relics. Guard it well, $r, for it is a fragile thing.$B$BThe Emerald Dream itself has become an alien, dangerous place. Its grasp on me is strong, and I will not be whole until the Emerald Dream returns to normalcy. What you see around you is but an echo of the reality inside the dream!",logDesc="Protect Clintar Dreamwalker's Spirit while it gathers the relics of Aviana, then speak to Dreamwarden Lurosa."} end
if not DB[10966] then DB[10966]={id=10966,zoneId=-284,name="Back to the Orphanage",level=-1,minLevel=60,ender="Orphan Matron Mercy",enderType="NPC",enderId=22819,wowhead="https://www.wowhead.com/wotlk/quest=10966",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.$B$BI've had such a great time.  You're the best person in all of the worlds, $N!  You're my big $g brother : sister; now!$B$B<Dornaa's eyes begin to well up with tears.>$B$BI'm going to miss you so much!  When I grow up, I'm going to be just like you!!!",logDesc="Return your ward to the Shattrath City orphanage by handing in the Draenei Orphan Whistle to Orphan Matron Mercy in the Lower City.",choiceRewards={{id=32622,qty=1},{id=32616,qty=1},{id=32617,qty=1}}} end
if not DB[10967] then DB[10967]={id=10967,zoneId=-284,name="Back to the Orphanage",level=-1,minLevel=60,ender="Orphan Matron Mercy",enderType="NPC",enderId=22819,wowhead="https://www.wowhead.com/wotlk/quest=10967",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.$B$BI've had such a great time.  You're the best person in all of the worlds, $N!  You're my big $g brother : sister; now!$B$B<Salandria's eyes begin to well up with tears.>$B$BI'm going to miss you so much!!!",logDesc="Return your ward to the Shattrath City orphanage by handing in the Blood Elf Orphan Whistle to Orphan Matron Mercy in the Lower City.",choiceRewards={{id=32616,qty=1},{id=32622,qty=1},{id=32617,qty=1}}} end
if not DB[10968] then DB[10968]={id=10968,zoneId=-284,name="Call on the Farseer",level=-1,minLevel=60,ender="Farseer Nobundo",enderType="NPC",enderId=17204,wowhead="https://www.wowhead.com/wotlk/quest=10968",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I am sensing something very special about this child indeed.$B$BYou should take her to visit Farseer Nobundo, here in the Exodar.  I believe that he has been expecting the two of you.$B$BLook for Nobundo upon the highest terrace in the Crystal Hall.",logDesc="Take your orphan, Dornaa, to visit Farseer Nobundo at the Crystal Hall inside of the Exodar, which is on Azuremyst Isle.  Make sure to call for her if she is not present when you arrive.$B$BRemember that you can use your map inside the city."} end
if not DB[10969] then DB[10969]={id=10969,zoneId=3523,name="Seek Out Ameer",level=70,minLevel=70,giver="Protectorate Advisor Rahim",giverType="NPC",giverId=22899,ender="Commander Ameer",enderType="NPC",enderId=20448,rewardNextId=10970,poiX=4107,poiY=2930,wowhead="https://www.wowhead.com/wotlk/quest=10969",image="assets/images/quests/placeholder.png",xpDiff=1,money=4400,desc="It would seem that an outside force has taken an interest in the business practices of the Consortium. Five Consortium dealers have gone missing in the past two days. We have reason to believe the Ethereum are involved. If you are interested in assisting, seek out Commander Ameer at the Protectorate Watch Post.$B$BYou will find the Protectorate Watch Post directly east of here on the next island. $B",logDesc="Seek out Commander Ameer at the Protectorate Watch Post."} end
if not DB[10970] then DB[10970]={id=10970,zoneId=3523,name="A Mission of Mercy",level=70,minLevel=70,giver="Commander Ameer",giverType="NPC",giverId=20448,ender="Commander Ameer",enderType="NPC",enderId=20448,poiX=4253,poiY=2166,wowhead="https://www.wowhead.com/wotlk/quest=10970",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="We salvaged this prison orb on our last scouting mission into Ethereum territory. We'd have never found it had it not been for the distress signal that it was faintly emitting.$B$BWe think one of our own might be locked up in there but we have no way of opening the orb up without harming whatever is inside.$B$BWhat we know about the Ethereum is that any of their members could - at any given time - be carrying a key to unlock an orb. Retrieve one and return so that we may uncover the mysteries of this orb.",logDesc="Recover the Salvaged Ethereum Prison Key for Commander Ameer at the Protectorate Watch Post in Netherstorm."} end
if not DB[10971] then DB[10971]={id=10971,zoneId=3523,name="Ethereum Secrets",level=70,minLevel=70,giver="Commander Ameer",giverType="NPC",giverId=20448,ender="Commander Ameer",enderType="NPC",enderId=20448,poiX=4253,poiY=2166,wowhead="https://www.wowhead.com/wotlk/quest=10971",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="<Ameer holds up a tag.>$B$BI found this prisoner I.D. tag with the remains of the fallen vanguard. I can only assume that all of their prisoners are tagged in the same manner.$B$BI'm going to start cataloguing the tags in hopes of making sense of their penal system. If in your adventures you find more Ethereum prison keys, you can use them to open the Ethereum prisons at the Ethereum Staging Grounds - directly south of here. Bring me back any and all I.D. tags that you find.",logDesc="Commander Ameer at the Protectorate Watch Post in Netherstorm wants you to bring him an Ethereum Prisoner I.D. Tag."} end
if not DB[10972] then DB[10972]={id=10972,zoneId=3523,name="Ethereum Prisoner I.D. Catalogue",level=70,minLevel=70,giver="Commander Ameer",giverType="NPC",giverId=20448,ender="Commander Ameer",enderType="NPC",enderId=20448,poiX=4253,poiY=2166,wowhead="https://www.wowhead.com/wotlk/quest=10972",image="assets/images/quests/placeholder.png",desc="I am in need of more I.D tags, $N. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!$B$BOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received."} end
if not DB[10973] then DB[10973]={id=10973,zoneId=3523,name="A Thousand Worlds",level=70,minLevel=70,giver="Commander Ameer",giverType="NPC",giverId=20448,ender="Commander Ameer",enderType="NPC",enderId=20448,rewardNextId=10974,poiX=4253,poiY=2166,wowhead="https://www.wowhead.com/wotlk/quest=10973",image="assets/images/quests/placeholder.png",xpDiff=5,money=132000,desc="I have cracked the code! Each tag is broken up into several segments. The front side of the tag is always the same and states: \"A Thousand Worlds...\" I am unsure as to the meaning of this phrase but it sounds insidious.$B$BOn the back side of the tag are the vital statistics. The first set of runes indicates location and the second indicates prisoner type. Furthermore, it would seem that the keys can be combined to form a special key that accesses another prison type. Now I just need more keys...",logDesc="Commander Ameer at the Protectorate Watch Post in Netherstorm wants you to bring him 5 Ethereum Prison Keys."} end
if not DB[10974] then DB[10974]={id=10974,zoneId=3522,name="Stasis Chambers of Bash'ir",level=70,minLevel=70,giver="Commander Ameer",giverType="NPC",giverId=20448,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,poiX=4253,poiY=2166,wowhead="https://www.wowhead.com/wotlk/quest=10974",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The Ethereum have a settlement on the northernmost shelf of Blade's Edge Mountains known as Bash'ir's Landing. According to the key tablet, much larger versions of the prisons are kept at Bash'ir's. It should also be noted that the Ethereum refer to those prisons as stasis chambers.$B$BThe key tablet grants access to a very specific stasis chamber at the landing known as Stasis Chamber Alpha. Take the key and investigate.$B$BMy image will be awaiting your return at Bash'ir's Landing. Speak to me there.",logDesc="Use the Ethereum Key Tablet - Alpha to open Stasis Chamber Alpha at Bash'ir's Landing in Blade's Edge Mountains.$B$BReturn Evidence from Alpha to the Image of Commander Ameer at Bash'ir's Landing.",rewards={{id=32064,qty=1}}} end
if not DB[10975] then DB[10975]={id=10975,zoneId=3522,name="Purging the Chambers of Bash'ir",level=70,minLevel=70,giver="Image of Commander Ameer",giverType="NPC",giverId=20482,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,wowhead="https://www.wowhead.com/wotlk/quest=10975",image="assets/images/quests/placeholder.png",money=44000,rewards={{id=29750,qty=1}}} end
if not DB[10976] then DB[10976]={id=10976,zoneId=3522,name="The Mark of the Nexus-King",level=70,minLevel=70,giver="Image of Commander Ameer",giverType="NPC",giverId=20482,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,rewardNextId=10977,wowhead="https://www.wowhead.com/wotlk/quest=10976",image="assets/images/quests/placeholder.png",xpDiff=7,money=44000,desc="What I must now know is what the Ethereum have held inside the Mana-Tombs of Auchindoun.$B$BIn your battles against the beasts of the stasis chambers of Bash'ir you may run across an item known as the Mark of the Nexus-King. Should you find such an item, return it to me immediately! It is the final piece in crafting a key that will allow access to the stasis chamber inside the Mana-Tombs.",logDesc="The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to bring him a Mark of the Nexus-King."} end
if not DB[10977] then DB[10977]={id=10977,zoneId=3792,name="Stasis Chambers of the Mana-Tombs",level=70,minLevel=70,giver="Image of Commander Ameer",giverType="NPC",giverId=20482,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,wowhead="https://www.wowhead.com/wotlk/quest=10977",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="The Mark of the Nexus-King that you recovered has allowed me to forge a new key for the stasis chambers found inside the Mana-Tombs.$B$BAccording to the glyphs on the mark, two exist: one near the front and one near Nexus-Prince Shaffar. This key that I am about to give you will open the stasis chamber near the front.$B$BI want you to go to the Mana-Tombs of Auchindoun and open the Mana-Tombs Stasis Chamber.",logDesc="The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to use the Mana-Tombs Stasis Chamber Key on the Stasis Chamber inside the Mana-Tombs of Auchindoun.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=29434,qty=5}}} end
if not DB[10978] then DB[10978]={id=10978,zoneId=-263,name="Return to Morthis Whisperwing",level=-1,minLevel=70,giver="Dreamwarden Lurosa",giverType="NPC",giverId=22837,ender="Morthis Whisperwing",enderType="NPC",enderId=22832,rewardNextId=10979,poiX=7518,poiY=-3054,wowhead="https://www.wowhead.com/wotlk/quest=10978",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Now that the relics have been recovered, you must leave this place with all haste. Clintar risked his safety and that of the dreamwardens to help you, $N, but now he must fully devote his attention to fighting the force that has invaded the Emerald Dream.$B$BTake the relics back to Morthis Whisperwing, along with word of what you've seen here. He may be able to help us identify just what Clintar is struggling against.",logDesc="Bring the Relics of Aviana to Morthis Whisperwing at Cenarion Refuge in Zangarmarsh."} end
if not DB[10979] then DB[10979]={id=10979,zoneId=-263,name="To the Evergrove",level=-1,minLevel=70,giver="Morthis Whisperwing",giverType="NPC",giverId=22832,ender="Arthorn Windsong",enderType="NPC",enderId=22924,rewardNextId=10980,poiX=-249,poiY=5444,wowhead="https://www.wowhead.com/wotlk/quest=10979",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Are you certain you saw a raven in the barrow den?$B$BThis is a troubling development. There's little we can do to help Clintar and the dreamwardens directly, but if we can learn more about what's threatening the Emerald Dream, we may be able to stop it.$B$BWe've been learning about the resurgence in an ancient arakkoa cult in Blade's Edge -- one that venerates a raven god. Go to the Evergrove and find Arthorn Windsong. There may be a connection between what's happening there and in the Emerald Dream!",logDesc="Speak with Arthorn Windsong at the Evergrove in Blade's Edge Mountains."} end
if not DB[10980] then DB[10980]={id=10980,zoneId=-263,name="The Book of the Raven",level=-1,minLevel=70,giver="Arthorn Windsong",giverType="NPC",giverId=22924,ender="Arthorn Windsong",enderType="NPC",enderId=22924,rewardNextId=10986,poiX=3024,poiY=5511,wowhead="https://www.wowhead.com/wotlk/quest=10980",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="From what you've told me, Morthis's suspicions seem plausible, but we need confirmation.$B$BIn his research, Timeon has uncovered clues that a \"book of the raven\" served as an ancient scripture to the cult.$B$BThe arakkoa spirits will not reveal themselves to your eyes. Take this stone with you to the high peaks in the western part of Blade's Edge, to the south of Raven's Wood, obtain an aether ray eye, and combine them to augment your sight. Search for the ghost Timeon identified as Sai'kkal the Elder.",logDesc="Use an Aether Ray Eye with your Seer's Stone to reveal the raven cult ghosts. Search the Vortex Pinnacle for the spirit of Sai'kkal the Elder and question him about the book of the raven, then return to Arthorn Windsong."} end
if not DB[10981] then DB[10981]={id=10981,zoneId=3792,name="Nexus-Prince Shaffar's Personal Chamber",level=70,minLevel=70,giver="Image of Commander Ameer",giverType="NPC",giverId=20482,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,wowhead="https://www.wowhead.com/wotlk/quest=10981",image="assets/images/quests/placeholder.png",rewards={{id=32079,qty=1}}} end
if not DB[10982] then DB[10982]={id=10982,zoneId=3522,name="The Eye of Haramad",level=70,minLevel=70,giver="Image of Commander Ameer",giverType="NPC",giverId=20482,ender="Image of Commander Ameer",enderType="NPC",enderId=20482,wowhead="https://www.wowhead.com/wotlk/quest=10982",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,rewards={{id=32092,qty=1}}} end
if not DB[10983] then DB[10983]={id=10983,zoneId=3522,name="Mog'dorg the Wizened",level=70,minLevel=70,giver="Grok",giverType="NPC",giverId=22940,ender="Mog'dorg the Wizened",enderType="NPC",enderId=22941,poiX=-2067,poiY=5287,wowhead="https://www.wowhead.com/wotlk/quest=10983",image="assets/images/quests/placeholder.png",xpDiff=2,money=4400,desc="Mog'dorg wise!  Him send Grok to city, look for help.  Bloodmaul clan need help.$B$BMog'dorg say, send powerful little ones to him at Blade's Edge Mountains.  Him stand on tower at Circle of Blood.  Mog'dorg wise!",logDesc="Visit Mog'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade's Edge Mountains."} end
if not DB[10984] then DB[10984]={id=10984,zoneId=3703,name="Speak with the Ogre",level=70,minLevel=70,giver="V'eru",giverType="NPC",giverId=22497,ender="Grok",enderType="NPC",enderId=22940,rewardNextId=10983,poiX=-1901,poiY=5398,wowhead="https://www.wowhead.com/wotlk/quest=10984",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<V'eru's voice fills your mind with crystalline tone and clarity.>$B$BThere is an ogre down in the Lower City, pleading for the assistance of passersby.  They have all turned a deaf ear upon his plight.$B$BDo you think you might aid him?$B$BHis name is Grok, and he is sitting near the merchants to the southeast.$B$BThank you, $N.",logDesc="Speak with the Ogre, Grok, in the Lower City section of Shattrath City."} end
if not DB[10985] then DB[10985]={id=10985,zoneId=3520,name="A Distraction for Akama",level=70,minLevel=70,giver="3",giverType="NPC",giverId=18528,ender="3",enderType="NPC",enderId=18528,rewardNextId=10958,poiX=-3560,poiY=638,wowhead="https://www.wowhead.com/wotlk/quest=10985",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>",logDesc="Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.",rewards={{id=32649,qty=1}}} end
if not DB[10986] then DB[10986]={id=10986,zoneId=-263,name="Eyes in the Sky",level=-1,minLevel=70,giver="Arthorn Windsong",giverType="NPC",giverId=22924,ender="Watcher Elaira",enderType="NPC",enderId=22981,rewardNextId=10987,poiX=3024,poiY=5511,wowhead="https://www.wowhead.com/wotlk/quest=10986",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Locating the pieces of the Book of the Raven, if they survive at all, is going to be difficult. Our best hope is to use a keener pair of eyes than your own.$B$BDown in western Nagrand, on the eastern lip of the Twilight Ridge, Watcher Elaira studies the various bird species that make their home there. Visit her and see if she can help you harness avian sight to gather the pieces of the Book of the Raven.",logDesc="Speak with Watcher Elaira at the Twilight Ridge in Nagrand."} end
if not DB[10987] then DB[10987]={id=10987,zoneId=-263,name="To Catch A Sparrowhawk",level=-1,minLevel=70,giver="Watcher Elaira",giverType="NPC",giverId=22981,ender="Watcher Elaira",enderType="NPC",enderId=22981,poiX=-1274,poiY=9159,wowhead="https://www.wowhead.com/wotlk/quest=10987",image="assets/images/quests/placeholder.png",desc="The wild sparrowhawks of Nagrand have the keenest sight of all the predatory birds here. But, because of their size, they've been pushed out of most areas by the larger windrocs.$B$BMost of the sparrowhawks nest here, on the Twilight Ridge. If you can catch one, I'll train it to spot the pieces of your buried tablet.$B$BIt's going to be difficult, though. The sparrowhawks are very skittish and will flee at your approach. I'd suggest cornering one or prowling to get close enough to cast your net.",logDesc="Use the Sparrowhawk Net to capture a Wild Sparrowhawk and bring it to Watcher Elaira on the Twilight Ridge."} end
if not DB[10988] then DB[10988]={id=10988,zoneId=-263,name="The Raven Stones",level=-1,minLevel=70,giver="Watcher Elaira",giverType="NPC",giverId=22981,ender="Arthorn Windsong",enderType="NPC",enderId=22924,poiX=-1274,poiY=9159,wowhead="https://www.wowhead.com/wotlk/quest=10988",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I've trained your sparrowhawk to respond to a specific whistle. When it hears the sound, the bird will fly to you and guide you to the location of the nearest tablet fragment. Arthorn sent word that the fragments you're looking for are buried in the Skettis area of southeastern Terokkar Forest, so the bird will wait for you there.$B$BWhen you've gathered all the stones, return the whistle to Arthorn and she will see to the animal's care and release.$B$BConvey my greetings to Arthorn when you see her.",logDesc="Gather 8 Raven Stones from Skettis and bring them to Arthorn Windsong at Evergrove in Blade's Edge Mountains."} end
if not DB[10989] then DB[10989]={id=10989,zoneId=3522,name="Mog'dorg the Wizened",level=70,minLevel=70,giver="Chort",giverType="NPC",giverId=22995,ender="Mog'dorg the Wizened",enderType="NPC",enderId=22941,poiX=2773,poiY=5839,wowhead="https://www.wowhead.com/wotlk/quest=10989",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Mog'dorg the Wizened waits for you at top of da tower.  He tells me to look for a $r $c just like you.  You go speak with him about smart things.$B$BGo now, but don't tell no one.  It's a secret!",logDesc="Speak with Mog'dorg the Wizened atop the tower where Chort is standing, just outside the Circle of Blood in the Blade's Edge Mountains."} end
if not DB[10990] then DB[10990]={id=10990,zoneId=-263,name="The Eagle's Essence",level=-1,minLevel=70,giver="Arthorn Windsong",giverType="NPC",giverId=22924,ender="Arthorn's Sparrowhawk",enderType="NPC",enderId=23338,rewardNextId=10991,poiX=3024,poiY=5511,wowhead="https://www.wowhead.com/wotlk/quest=10990",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Book of the Raven tells us the raven's followers captured and bound the spirits of his rivals within stone shrines. A guardian was set to watch over each, lest the raven's enemies attempt to free them.$B$BThe first of the shrines is the eagle's, found in the hills to the south of Lake Jorune and west of Stonebreaker Hold in Terokkar Forest.$B$BThe tablet says that the eagle fought valiantly, but was overcome by a swarm of enemies. The armor and endurance of your bear form is well-suited to this fight.",logDesc="Defeat the Guardian of the Eagle and obtain the Essence of the Eagle. Use Arthorn's Sparrowhawk Whistle to call Arthorn's Sparrowhawk to relay news of your success.$B$BIf you lose Arthorn's Sparrowhawk Whistle, return to Arthorn Windsong at the Evergrove for a replacement."} end
if not DB[10991] then DB[10991]={id=10991,zoneId=-263,name="The Falcon's Essence",level=-1,minLevel=70,giver="Arthorn's Sparrowhawk",giverType="NPC",giverId=23338,ender="Arthorn's Sparrowhawk",enderType="NPC",enderId=23338,rewardNextId=10992,wowhead="https://www.wowhead.com/wotlk/quest=10991",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="<The bird speaks with Arthorn's voice.>$B$BThe second spirit bound by the raven's followers was the falcon.$B$BIt was subdued and imprisoned close to Skettis as a reminder to the raven-priests when they held power.$B$BOn the shores of Lake Ere'Noru, to the northwest of Skettis, you'll find the falcon's shrine.$B$BTo overcome the falcon's guardian, you'll need to use the falcon's strengths to your advantage. Use the speed and grace of your cat form to defeat the guardian before it reaches full strength!",logDesc="Defeat the Guardian of the Falcon, obtain the Essence of the Falcon. Use Arthorn's Sparrowhawk Whistle to call Arthorn's Sparrowhawk to relay news of your success.$B$BIf you lose Arthorn's Sparrowhawk Whistle, return to Arthorn Windsong at the Evergrove for a replacement."} end
if not DB[10992] then DB[10992]={id=10992,zoneId=-263,name="The Hawk's Essence",level=-1,minLevel=70,giver="Arthorn's Sparrowhawk",giverType="NPC",giverId=23338,ender="Arthorn Windsong",enderType="NPC",enderId=22924,rewardNextId=10993,wowhead="https://www.wowhead.com/wotlk/quest=10992",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="<Arthorn's voice addresses you.>$B$BThe last, and strongest, of the spirits spoken of in the Book of the Raven is that of the hawk. It was imprisoned far from Skettis, in a shrine on a remote island southeast of Auchindoun.$B$BI believe this description best matches the island we know as Sorrow Wing Point.$B$BThe tablet describes the hawk's guardian as nearly invulnerable to the bird's claws. Forsake physical attacks and call down the fury of the stars to defeat this foe. Do not repeat the hawk's mistake.",logDesc="Defeat the Guardian of the Hawk and bring the Essence of the Hawk to Arthorn Windsong at the Evergrove.",rewards={{id=32481,qty=1}}} end
if not DB[10993] then DB[10993]={id=10993,zoneId=-263,name="Return to Cenarion Refuge",level=-1,minLevel=70,giver="Arthorn Windsong",giverType="NPC",giverId=22924,ender="Morthis Whisperwing",enderType="NPC",enderId=22832,rewardNextId=10994,poiX=3024,poiY=5511,wowhead="https://www.wowhead.com/wotlk/quest=10993",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Bring the essences to Morthis Whisperwing, along with word of our findings about the raven god.$B$BMorthis will know best how to use the essences and information in drawing Anzu out into the open. Make your way to him quickly, for there's no telling how long Clintar and the dreamwardens can withstand the raven's assault!$B$B<Arthorn grabs your arm before you turn to leave>.$B$BPlease, $N, tell Morthis how much of a help I've been to you. I fear he will not see my hand in this work!",logDesc="Bring Arthorn's Package to Morthis Whisperwing at Cenarion Refuge."} end
if not DB[10994] then DB[10994]={id=10994,zoneId=-263,name="Chasing the Moonstone",level=-1,minLevel=70,giver="Morthis Whisperwing",giverType="NPC",giverId=22832,ender="Morthis Whisperwing",enderType="NPC",enderId=22832,rewardNextId=11001,poiX=-249,poiY=5444,wowhead="https://www.wowhead.com/wotlk/quest=10994",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If the essences are combined within a rare gemstone such as a Southfury moonstone, you'll be able to release them when you're prepared to challenge Anzu.$B$BThe only problem is that Southfury moonstones are only found on the Azshara side of the river, on the cliffs near the river's source.$B$BTragedy befell the last night elf party that sought the stone. Their boat is still anchored in the river near where they sighted the moonstone. Keep your eyes open and approach the site by land from the Azshara side.",logDesc="Bring a Southfury Moonstone to Morthis Whisperwing at the Cenarion Refuge."} end
if not DB[10995] then DB[10995]={id=10995,zoneId=3522,name="Grulloc Has Two Skulls",level=70,minLevel=70,giver="Mog'dorg the Wizened",giverType="NPC",giverId=22941,ender="Mog'dorg the Wizened",enderType="NPC",enderId=22941,poiX=2786,poiY=5836,wowhead="https://www.wowhead.com/wotlk/quest=10995",image="assets/images/quests/placeholder.png",xpDiff=7,money=88000,desc="To the east, at the terminus of Dragons' End, is the Cursed Hollow.  Therein, Grulloc, son of Gruul, plots his dimwitted schemes.$B$BI heard that one of his possessions was stolen from him through trickery.  Was that you?  Unfortunate that he was not slain in the process.$B$BIf we are to regain our freedom, I would have you take his most prized possession, a dragon skull from when he rejoiced in his father's slaying of the black dragonflight.  The only way you'll get the skull is to vanquish him.",logDesc="Collect Grulloc's Dragon Skull."} end
if not DB[10996] then DB[10996]={id=10996,zoneId=3522,name="Maggoc's Treasure Chest",level=70,minLevel=70,giver="Mog'dorg the Wizened",giverType="NPC",giverId=22941,ender="Mog'dorg the Wizened",enderType="NPC",enderId=22941,poiX=2786,poiY=5836,wowhead="https://www.wowhead.com/wotlk/quest=10996",image="assets/images/quests/placeholder.png",xpDiff=7,money=88000,desc="On the Razor Ridge, above and to the southeast, Maggoc patrols.  His father assigned him as the warden of the eastern mountain range, and he revels in terrorizing any creature that gets in his way.$B$BAs a son of Gruul, he must be done away with if my clan is to survive.  That's where you come in.$B$BMaggoc carries a treasure chest with him at all times.  Prove to me that he has been slain by bringing me his precious chest.  Feel free to keep whatever you find within it.",logDesc="Collect Maggoc's Treasure Chest."} end
if not DB[10997] then DB[10997]={id=10997,zoneId=3696,name="Even Gronn Have Standards",level=70,minLevel=70,giver="Mog'dorg the Wizened",giverType="NPC",giverId=22941,ender="Mog'dorg the Wizened",enderType="NPC",enderId=22941,poiX=2786,poiY=5836,wowhead="https://www.wowhead.com/wotlk/quest=10997",image="assets/images/quests/placeholder.png",xpDiff=7,money=88000,desc="Are you familiar with Shattrath City, $c?  Above it to the northwest is a place called the Barrier Hills, which you can only get to upon a flying mount.$B$BOne of Gruul's sons, Slaag, exiled himself and took control of the Gordunni ogres that reside there.  Even at such a distance, we cannot afford to leave him in peace, lest he return when the rest of his brothers have been slain.$B$B$N, you must travel there, and bring back his standard as proof that he has been dealt with.",logDesc="Collect Slaag's Standard."} end
if not DB[10998] then DB[10998]={id=10998,zoneId=3522,name="Grim(oire) Business",level=70,minLevel=70,giver="Mog'dorg the Wizened",giverType="NPC",giverId=22941,ender="Mog'dorg the Wizened",enderType="NPC",enderId=22941,rewardNextId=11000,poiX=2786,poiY=5836,wowhead="https://www.wowhead.com/wotlk/quest=10998",image="assets/images/quests/placeholder.png",xpDiff=7,money=88000,desc="There is one more gronn to be slain: Skulloc Soulgrinder. He keeps himself hidden away, but there is a way to coax him forth.$B$BHe was trained by an ogre warlock known as Vim'gol the Vile, whose grimoire you must retrieve!$B$BVim'gol must be summoned by standing within a fire ring at his circle. Find Vim'gol's Circle in the mountains, to the northeast, near the Broken Wilds.$B$B$N, if you hear Vim'gol talk about growing bigger, get people back into each of the five fire rings to interrupt his casting!",logDesc="Collect Vim'gol's Vile Grimoire."} end
if not DB[10999] then DB[10999]={id=10999,zoneId=151,name="One Shot,One Kill",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=10999",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Bring me 8 trogg stone teeth.",logDesc="Bring me 8 trogg stone teeth."} end
if not DB[11000] then DB[11000]={id=11000,zoneId=3522,name="Into the Soulgrinder",level=70,minLevel=70,giver="Mog'dorg the Wizened",giverType="NPC",giverId=22941,ender="Mog'dorg the Wizened",enderType="NPC",enderId=22941,poiX=2786,poiY=5836,wowhead="https://www.wowhead.com/wotlk/quest=11000",image="assets/images/quests/placeholder.png",xpDiff=8,money=132000,desc="The grimoire is the key to Skulloc's downfall.$B$BRead aloud from the book at Soulgrinder's Barrow to initiate the ritual.  An object known as the Soulgrinder will appear, as well as Skulloc's ghostly victims, who will try to destroy it.  You must keep them from doing so long enough to force Skulloc fully into the world.$B$BFind the barrow by heading north through the Daggermaw Canyon on the other side of the Circle of Blood.  It is on the right side before Gruul's Lair.$B$BBring back Skulloc's soul.",logDesc="Collect Skulloc's Soul."} end
if not DB[11001] then DB[11001]={id=11001,zoneId=-263,name="Vanquish the Raven God",level=-1,minLevel=70,giver="Morthis Whisperwing",giverType="NPC",giverId=22832,ender="Morthis Whisperwing",enderType="NPC",enderId=22832,poiX=-249,poiY=5444,wowhead="https://www.wowhead.com/wotlk/quest=11001",image="assets/images/quests/placeholder.png",xpDiff=7,desc="We must waste no time in dealing with the raven god. You must take the essence-infused moonstone to a place of great power in order to lure the god from the relative safety of the Emerald Dream.$B$BDescend into the Sethekk Halls and set the moonstone in the clutches of the raven's claw. You'll find it in the chamber before the talon king's hall.$B$BAnzu must be made believe that his followers have gathered to welcome him back into the world. Once he has manifested, show him no mercy!",logDesc="Slay the Raven God and return to Morthis Whisperwing at Cenarion Refuge.$B$BThis quest must be completed in Heroic dungeon difficulty.",rewards={{id=32387,qty=1}}} end
if not DB[11002] then DB[11002]={id=11002,zoneId=3483,name="The Fall of Magtheridon",level=70,minLevel=70,ender="Force Commander Danath Trollbane",enderType="NPC",enderId=16819,wowhead="https://www.wowhead.com/wotlk/quest=11002",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Alliance.$B$BReturn Magtheridon's head to Danath Trollbane at Honor Hold.$B",logDesc="Return Magtheridon's Head to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.",choiceRewards={{id=28792,qty=1},{id=28793,qty=1},{id=28790,qty=1},{id=28791,qty=1}}} end
if not DB[11003] then DB[11003]={id=11003,zoneId=3483,name="The Fall of Magtheridon",level=70,minLevel=70,ender="Nazgrel",enderType="NPC",enderId=3230,wowhead="https://www.wowhead.com/wotlk/quest=11003",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Horde.$B$BReturn Magtheridon's head to Nazgrel at Thrallmar.$B",logDesc="Return Magtheridon's Head to Nazgrel at Thrallmar in Hellfire Peninsula.",choiceRewards={{id=28792,qty=1},{id=28793,qty=1},{id=28790,qty=1},{id=28791,qty=1}}} end
if not DB[11004] then DB[11004]={id=11004,zoneId=3679,name="World of Shadows",level=70,minLevel=70,giver="Severin",giverType="NPC",giverId=23042,ender="Severin",enderType="NPC",enderId=23042,poiX=-3408,poiY=3625,wowhead="https://www.wowhead.com/wotlk/quest=11004",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Sky Commander Adaris was seriously injured during a Skettis incursion.  He's been in and out of consciousness since.$B$BI fear he has succumbed to a feverish delirium.  During brief lucid moments he demands that I prepare an elixir made from shadow dust carried by the arakkoa.  He seems to believe it will allow him to see into a \"world of shadows\" where the arakkoa's true leaders dwell.$B$BI do not believe this nonsense for a second, but I fear he won't rest until I obtain such an elixir.  Will you help?",logDesc="Severin wants you to venture into Skettis and retrieve 6 Shadow Dusts from the arakkoa that dwell there.",rewards={{id=32446,qty=1}}} end
if not DB[11005] then DB[11005]={id=11005,zoneId=3679,name="Secrets of the Talonpriests",level=70,minLevel=70,giver="Sky Commander Adaris",giverType="NPC",giverId=23038,ender="Sky Commander Adaris",enderType="NPC",enderId=23038,poiX=-3408,poiY=3623,wowhead="https://www.wowhead.com/wotlk/quest=11005",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Thank you for paying heed to my fevered rants.  All along we had been trying to identify and destroy the Skettis chain of command; we had learned of three clerics known as the talonpriests, but we'd never seen them with our own two eyes.  Now we know why.$B$BTalk to Severin to obtain more of the elixir he discovered.  Use the elixir to find and kill the three talonpriests: Ishaal, Skizzik and Zellek.  They're rumored to dwell in Veil Ala'rak, near the eastern shore of Blackwind Lake.",logDesc="Obtain an Elixir of Shadows from Severin and use it to find and slay Talonpriest Ishaal, Talonpriest Skizzik and Talonpriest Zellek in Skettis.  Return to Commander Adaris after completing this task."} end
if not DB[11006] then DB[11006]={id=11006,zoneId=3679,name="More Shadow Dust",level=70,minLevel=70,giver="Severin",giverType="NPC",giverId=23042,ender="Severin",enderType="NPC",enderId=23042,poiX=-3408,poiY=3625,wowhead="https://www.wowhead.com/wotlk/quest=11006",image="assets/images/quests/placeholder.png",rewards={{id=32446,qty=1}}} end
if not DB[11007] then DB[11007]={id=11007,zoneId=3845,name="Kael'thas and the Verdant Sphere",level=70,minLevel=70,ender="A'dal",enderType="NPC",enderId=18481,wowhead="https://www.wowhead.com/wotlk/quest=11007",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The air around you hums - a gentle hum. The naaru are aware of your victory. Perhaps they are the reason you were compelled to pick up this sphere from the still-twitching remains of Kael'thas Sunstrider. What secrets could it hold?$B$BPerhaps A'dal in Shattrath City could make sense of the item.",logDesc="Take the Verdant Sphere to A'dal in Shattrath City.",choiceRewards={{id=30018,qty=1},{id=30017,qty=1},{id=30007,qty=1},{id=30015,qty=1}}} end
if not DB[11008] then DB[11008]={id=11008,zoneId=3679,name="Fires Over Skettis",level=70,minLevel=70,giver="Sky Sergeant Doryn",giverType="NPC",giverId=23048,ender="Sky Sergeant Doryn",enderType="NPC",enderId=23048,poiX=-3401,poiY=3598,wowhead="https://www.wowhead.com/wotlk/quest=11008",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="You think you have what it takes to be part of the Skyguard?  We'll have to see how you handle yerself in the air.$B$BThe arakkoa are breeding a gargantuan variety of their attack pets and are using it against our scouts.  I want you to take these blasting charges and use them to destroy hatcheries above the arakkoa's dwellings.  Avoid the monstrous kaliri guarding the hatcheries.  They'll knock you off your mount before you know what hit you.",logDesc="Seek out Monstrous Kaliri Eggs on the tops of Skettis dwellings and use the Skyguard Blasting Charges on them.  Return to Sky Sergeant Doryn."} end
if not DB[11009] then DB[11009]={id=11009,zoneId=3522,name="Ogre Heaven",level=70,minLevel=70,giver="Mog'dorg the Wizened",giverType="NPC",giverId=22941,ender="Chu'a'lor",enderType="NPC",enderId=23233,poiX=2786,poiY=5836,wowhead="https://www.wowhead.com/wotlk/quest=11009",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Now that you have delivered us from bondage, we can begin the process of reunifying the clans.  This will take some time; old grudges are difficult to overcome.$B$BBut more pressing, you must go to Ogri'la in the heavens above to the west.  You must defend it, and us, from those forces above that the gronn used to protect us from: ethereals, demons, and worst of all, the black dragonflight.$B$BWhen you find ogre heaven, seek out the wisdom of Chu'a'lor on how best to proceed.",logDesc="Speak with Chu'a'lor at Ogri'la in the Blade's Edge Mountains."} end
if not DB[11010] then DB[11010]={id=11010,zoneId=3522,name="Bombing Run",level=70,minLevel=70,giver="Sky Sergeant Vanderlip",giverType="NPC",giverId=23120,ender="Sky Sergeant Vanderlip",enderType="NPC",enderId=23120,rewardNextId=11023,poiX=2494,poiY=7350,wowhead="https://www.wowhead.com/wotlk/quest=11010",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="You have a flying mount... so what!  You think you have what it takes to use it properly?$B$BForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.$B$BYou want to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!",logDesc="Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks."} end
if not DB[11011] then DB[11011]={id=11011,zoneId=-263,name="Eternal Vigilance",level=70,minLevel=70,giver="Morthis Whisperwing",giverType="NPC",giverId=22832,ender="Morthis Whisperwing",enderType="NPC",enderId=22832,poiX=-249,poiY=5444,wowhead="https://www.wowhead.com/wotlk/quest=11011",image="assets/images/quests/placeholder.png",desc="Your defeat of Anzu, the raven god, is truly a remarkable accomplishment. He may not abandon his quest to return to Outland, I fear.$B$BAs long as he has followers here, he will attempt to rise again. Keep the essence-infused moonstone with you in case we have not heard the last of Anzu.",logDesc="Speak with Morthis Whisperwing to receive an Essence-Infused Moonstone.",rewards={{id=32449,qty=1}}} end
if not DB[11012] then DB[11012]={id=11012,zoneId=3520,name="Blood Oath of the Netherwing",level=70,minLevel=70,giver="Mordenai",giverType="NPC",giverId=22113,ender="Mordenai",enderType="NPC",enderId=22113,poiX=-4129,poiY=762,wowhead="https://www.wowhead.com/wotlk/quest=11012",image="assets/images/quests/placeholder.png"} end
if not DB[11013] then DB[11013]={id=11013,zoneId=3520,name="In Service of the Illidari",level=70,minLevel=70,giver="Mordenai",giverType="NPC",giverId=22113,ender="Overlord Mor'ghor",enderType="NPC",enderId=23139,rewardNextId=11014,poiX=-4129,poiY=762,wowhead="https://www.wowhead.com/wotlk/quest=11013",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Netherwing Ledge... What was once a bastion of sanctuary for the Netherwing is now home to the Dragonmaw. While the orcs may have control of our territory, our magic there is still strong. Strong enough to cloak your true identity and allow you to infiltrate the ranks of Dragonmaw.$B$BI have prepared this letter for you to present to their leader, Overlord Mor'ghor. Fly headlong into the maw of our enemy and seek out Dragonmaw Base Camp to start your new life as a fel orc of Illidan Stormrage.",logDesc="Travel to Netherwing Ledge and deliver the Illidari Service Papers to Overlord Mor'ghor at Dragonmaw Base Camp.$B"} end
if not DB[11014] then DB[11014]={id=11014,zoneId=3520,name="Enter the Taskmaster",level=70,minLevel=70,giver="Overlord Mor'ghor",giverType="NPC",giverId=23139,ender="Taskmaster Varkule Dragonbreath",enderType="NPC",enderId=23140,poiX=-5085,poiY=579,wowhead="https://www.wowhead.com/wotlk/quest=11014",image="assets/images/quests/placeholder.png",desc="<Mor'ghor crumples up the service letter and tosses it aside.>$B$BAlright grunt, first things first. If you're gonna join my beloved Dragonmaw army, you'll need to work. Everyone works up here on the ledge. Get a job and don't screw it up and I'll see if there might be something more interesting for you to do later.$B$BGo talk to Taskmaster Varkule Dragonbreath. He's standin' in the middle of town. He'll assess your skills and assign work as he sees fit.$B$BNow get out of my face!",logDesc="Speak with Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp."} end
if not DB[11015] then DB[11015]={id=11015,zoneId=3520,name="Netherwing Crystals",level=70,minLevel=70,giver="Taskmaster Varkule Dragonbreath",giverType="NPC",giverId=23140,ender="Taskmaster Varkule Dragonbreath",enderType="NPC",enderId=23140,poiX=-5114,poiY=588,wowhead="https://www.wowhead.com/wotlk/quest=11015",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="No good at nothin'? That's fine. Even lunkheads like you can be used around here. Just find creatures on the ledge and kill 'em. Sometimes they'll have nether crystals on their carcasses. Gather those and bring 'em back to me and I'll consider your work order for the day complete.$B",logDesc="Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 30 Netherwing Crystals."} end
if not DB[11016] then DB[11016]={id=11016,zoneId=3520,name="Nethermine Flayer Hide",level=70,minLevel=70,giver="Taskmaster Varkule Dragonbreath",giverType="NPC",giverId=23140,ender="Taskmaster Varkule Dragonbreath",enderType="NPC",enderId=23140,poiX=-5114,poiY=588,wowhead="https://www.wowhead.com/wotlk/quest=11016",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="A skinner, eh? Well you'll find plenty to skin here! You gotta search for flayers around crystal formations. Take 'em down and take their hides. Sometimes they'll have a hide worth keepin'. Bring those to me.",logDesc="Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 35 Nethermine Flayer Hides."} end
if not DB[11017] then DB[11017]={id=11017,zoneId=3520,name="Netherdust Pollen",level=70,minLevel=70,giver="Taskmaster Varkule Dragonbreath",giverType="NPC",giverId=23140,ender="Taskmaster Varkule Dragonbreath",enderType="NPC",enderId=23140,poiX=-5114,poiY=588,wowhead="https://www.wowhead.com/wotlk/quest=11017",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="A flower picker?! Hilarious... Unfortunately, our mages and shaman need your services. The netherdust bushes that grow on this ledge have special pollen that is apparently very useful in their magical dealings. Bring me that stuff and I'll consider your work order complete.",logDesc="Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 40 Netherdust Pollen."} end
if not DB[11018] then DB[11018]={id=11018,zoneId=3520,name="Nethercite Ore",level=70,minLevel=70,giver="Taskmaster Varkule Dragonbreath",giverType="NPC",giverId=23140,ender="Taskmaster Varkule Dragonbreath",enderType="NPC",enderId=23140,poiX=-5114,poiY=588,wowhead="https://www.wowhead.com/wotlk/quest=11018",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="A miner!$B$B<Varkule salutes.>$B$BAn orc after my own heart! That's how Varkule got his start - minin'! There ain't nothin' better than getting down and dirty in the mines, is there?$B$BNow get out there and find those nethercite deposits. Strip 'em for all their worth and bring me back the ore.",logDesc="Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 40 Nethercite Ore."} end
if not DB[11019] then DB[11019]={id=11019,zoneId=3520,name="Your Friend On The Inside",level=70,minLevel=70,giver="Yarzill the Merc",giverType="NPC",giverId=23141,ender="Yarzill the Merc",enderType="NPC",enderId=23141,poiX=-5118,poiY=594,wowhead="https://www.wowhead.com/wotlk/quest=11019",image="assets/images/quests/placeholder.png"} end
if not DB[11020] then DB[11020]={id=11020,zoneId=3520,name="A Slow Death",level=70,minLevel=70,giver="Yarzill the Merc",giverType="NPC",giverId=23141,ender="Yarzill the Merc",enderType="NPC",enderId=23141,poiX=-5118,poiY=594,wowhead="https://www.wowhead.com/wotlk/quest=11020",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="The Dragonmaw have peons stationed at nearly every crystal formation up here. While the outright slaying of them would draw far too much unwanted attention to you, there is a way that we can thin their numbers and remain below the suspicious eyes of Mor'ghor.$B$BVenture into the wilds of Shadowmoon Valley and slay the tainted wildlife. Take from them their corrupt fel glands. Use those fel glands with this mutton that I'll give you near the peons. They'll take one bite and fall deathly ill!",logDesc="Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to use Yarzill's Mutton in conjunction with Fel Glands to poison 12 Dragonmaw Peon Camps.$B"} end
if not DB[11021] then DB[11021]={id=11021,zoneId=3679,name="Ishaal's Almanac",level=70,minLevel=70,ender="Sky Commander Adaris",enderType="NPC",enderId=23038,rewardNextId=11024,wowhead="https://www.wowhead.com/wotlk/quest=11021",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This mysterious tome was on Talonpriest Ishaal's body.  It contains arcane symbols and charts of celestial bodies beyond your comprehension.$B$BAll writing is in a language you don't understand; likely an ancient version of the arakkoa written tongue.  Perhaps you should bring this to Sky Commander Adaris.",logDesc="Bring Ishaal's Almanac to Sky Commander Adaris north of Skettis."} end
if not DB[11022] then DB[11022]={id=11022,zoneId=3522,name="Speak with Mog'dorg",level=70,minLevel=70,giver="Bladespire Supplicant",giverType="NPC",giverId=23053,ender="Mog'dorg the Wizened",enderType="NPC",enderId=22941,rewardNextId=11009,wowhead="https://www.wowhead.com/wotlk/quest=11022",image="assets/images/quests/placeholder.png",desc="$G King : Queen; $N!  You speak with Mog'dorg the Wizened before you leave and go to Ogri'la!",logDesc="Speak with Mog'dorg the Wizened.  He stands atop the tower on the east side of the Circle of Blood in the Blade's Edge Mountains."} end
if not DB[11023] then DB[11023]={id=11023,zoneId=3522,name="Bomb Them Again!",level=70,minLevel=70,giver="Sky Sergeant Vanderlip",giverType="NPC",giverId=23120,ender="Sky Sergeant Vanderlip",enderType="NPC",enderId=23120,poiX=2494,poiY=7350,wowhead="https://www.wowhead.com/wotlk/quest=11023",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="We're still having problems with those flak cannons, $N.$B$BDon't get me wrong -- I think that you did an outstanding job the last time out -- but, that doesn't change the fact that those damned demons seem to be replenishing their ammo supplies faster than we can knock them out.  And that means we're having a hell of a time getting our people through there, not to mention the risk those demons pose to Ogri'la.$B$BWhat do you say?  Want to take another shot at it?",logDesc="Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.",rewards={{id=32569,qty=15}}} end
if not DB[11024] then DB[11024]={id=11024,zoneId=3703,name="An Ally in Lower City",level=70,minLevel=70,giver="Sky Commander Adaris",giverType="NPC",giverId=23038,ender="Rilak the Redeemed",enderType="NPC",enderId=22292,rewardNextId=11028,poiX=-3408,poiY=3623,wowhead="https://www.wowhead.com/wotlk/quest=11024",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There is an arakkoa in Lower City by the name of Rilak...  He can be trusted.  Take the book... to him.$B$B<Adaris drifts into unconsciousness as he returns the book to you.>",logDesc="Bring Ishaal's Almanac to Rilak the Redeemed in the Lower City section of Shattrath City."} end
if not DB[11025] then DB[11025]={id=11025,zoneId=3522,name="The Crystals",level=70,minLevel=70,giver="Chu'a'lor",giverType="NPC",giverId=23233,ender="Chu'a'lor",enderType="NPC",enderId=23233,rewardNextId=11058,poiX=2335,poiY=7285,wowhead="https://www.wowhead.com/wotlk/quest=11025",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="When prepared correctly, the crystals of the mountains exhibit strange powers, such as the clarity of mind that we have found here in Ogri'la.$B$BAll of the creatures atop the mountains covet the crystal shards and use them to further their own goals.  An economy has even sprung up around them.$B$BTo assist us, you must first learn about the Apexis shards.  Bring me some.  In addition to the creatures here having them, they can sometimes be found where the flayers dig at the larger crystals.",logDesc="Collect 5 Apexis Shards."} end
if not DB[11026] then DB[11026]={id=11026,zoneId=3522,name="Banish the Demons",level=70,minLevel=70,giver="Kronk",giverType="NPC",giverId=23253,ender="Kronk",enderType="NPC",enderId=23253,poiX=2314,poiY=7278,wowhead="https://www.wowhead.com/wotlk/quest=11026",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="You've arrived at the perfect time, friend!  We are in need of assistance.  In return, you will receive something very rare, which will help us both in the end.$B$BWe're not a violent ogre any longer, but the demons nearby threaten to overrun us and the Skyguard.  The problem with demons is that, once killed, they come right back in new bodies!$B$BBut, if you use this crystal to summon a banishing portal, when they die near it, their essences will be drawn in and banished back from whence they came!",logDesc="Use the Banishing Crystal to banish 15 demons at Forge Camp: Wrath or Forge Camp: Terror.",rewards={{id=32643,qty=1}}} end
if not DB[11027] then DB[11027]={id=11027,zoneId=3522,name="Yous Have Da Darkrune?",level=70,minLevel=70,giver="Gahk",giverType="NPC",giverId=23300,ender="Gahk",enderType="NPC",enderId=23300,poiX=2308,poiY=7300,wowhead="https://www.wowhead.com/wotlk/quest=11027",image="assets/images/quests/placeholder.png",xpDiff=1,money=4400,rewards={{id=32602,qty=1}}} end
if not DB[11028] then DB[11028]={id=11028,zoneId=3679,name="Countdown to Doom",level=70,minLevel=70,giver="Rilak the Redeemed",giverType="NPC",giverId=22292,ender="Sky Commander Adaris",enderType="NPC",enderId=23038,poiX=-1657,poiY=5449,wowhead="https://www.wowhead.com/wotlk/quest=11028",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This almanac presages the return of Terokk, the most powerful and terrible Skettis king in arakkoa history.$B$BI always believed this to be the mere legend, $N.  The return of the talonpriests and your recovery of this tome indicate otherwise.$B$BWith each day, Terokk comes closer to returning to full strength.  Your only chance is to bring him to our world prematurely.  Return to Skettis and speak to Adaris about this.  Let us hope he has the wisdom to do the right thing.",logDesc="Return to Sky Commander Adaris at Blackwind Landing in Terokkar Forest with the news about Terokk's return."} end
if not DB[11029] then DB[11029]={id=11029,zoneId=3679,name="A Shabby Disguise",level=70,minLevel=70,giver="Hazzik",giverType="NPC",giverId=23306,ender="Hazzik",enderType="NPC",enderId=23306,rewardNextId=11885,poiX=-3411,poiY=3615,wowhead="https://www.wowhead.com/wotlk/quest=11029",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Open the package, $N.  It is a disguise.  It doesn't look very convincing, does it?$B$BI craft them for ethereal smugglers in search of rare books.  There is an arakkoa scribe who dwells in the central island in Skettis, Terokk's Rest; his name is Sahaak.  He is old and nearly blind.$B$BUse the disguise to speak with him and obtain the book known as the Adversarial Bloodlines.  Be careful, $N.  The disguise won't fool the other arakkoa.",logDesc="Use the Shabby Arakkoa Disguise to obtain the Adversarial Bloodlines from Sahaak and return to Hazzik."} end
if not DB[11030] then DB[11030]={id=11030,zoneId=3522,name="Our Boy Wants To Be A Skyguard Ranger",level=70,minLevel=70,giver="Torkus",giverType="NPC",giverId=23316,ender="Torkus",enderType="NPC",enderId=23316,rewardNextId=11061,poiX=2323,poiY=7307,wowhead="https://www.wowhead.com/wotlk/quest=11030",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="$C, we've got a problem -- we have lots of sons.  And ever since the Skyguard moved in nearby, all our sons ever talk about is joining their ranks.$B$BAs a proud father, we want them to have every advantage for when they apply.  So, would you go to the fel crystalforge at either forge camp to the north or south, and procure a magic flask for our sons?  You can't miss their green smoke.$B$BWe think that they take ten apexis shards to make.  We'd give you the shards, but we don't have any at the moment.",logDesc="Collect an Unstable Flask of the Beast."} end
if not DB[11031] then DB[11031]={id=11031,zoneId=2562,name="Archmage No More",level=70,minLevel=70,giver="Archmage Leryda",giverType="NPC",giverId=18253,ender="Archmage Leryda",enderType="NPC",enderId=18253,poiX=-11116,poiY=-2014,wowhead="https://www.wowhead.com/wotlk/quest=11031",image="assets/images/quests/placeholder.png",choiceRewards={{id=29290,qty=1},{id=29279,qty=1},{id=29283,qty=1}}} end
if not DB[11032] then DB[11032]={id=11032,zoneId=2562,name="Protector No More",level=70,minLevel=70,giver="Archmage Leryda",giverType="NPC",giverId=18253,ender="Archmage Leryda",enderType="NPC",enderId=18253,poiX=-11116,poiY=-2014,wowhead="https://www.wowhead.com/wotlk/quest=11032",image="assets/images/quests/placeholder.png",choiceRewards={{id=29290,qty=1},{id=29287,qty=1},{id=29283,qty=1}}} end
if not DB[11033] then DB[11033]={id=11033,zoneId=2562,name="Assassin No More",level=70,minLevel=70,giver="Archmage Leryda",giverType="NPC",giverId=18253,ender="Archmage Leryda",enderType="NPC",enderId=18253,poiX=-11116,poiY=-2014,wowhead="https://www.wowhead.com/wotlk/quest=11033",image="assets/images/quests/placeholder.png",choiceRewards={{id=29290,qty=1},{id=29279,qty=1},{id=29287,qty=1}}} end
if not DB[11034] then DB[11034]={id=11034,zoneId=2562,name="Restorer No More",level=70,minLevel=70,giver="Archmage Leryda",giverType="NPC",giverId=18253,ender="Archmage Leryda",enderType="NPC",enderId=18253,poiX=-11116,poiY=-2014,wowhead="https://www.wowhead.com/wotlk/quest=11034",image="assets/images/quests/placeholder.png",choiceRewards={{id=29283,qty=1},{id=29279,qty=1},{id=29287,qty=1}}} end
if not DB[11035] then DB[11035]={id=11035,zoneId=3520,name="The Not-So-Friendly Skies...",level=70,minLevel=70,giver="Yarzill the Merc",giverType="NPC",giverId=23141,ender="Yarzill the Merc",enderType="NPC",enderId=23141,poiX=-5118,poiY=594,wowhead="https://www.wowhead.com/wotlk/quest=11035",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="On the northeast edge of this island exists a dock used for the packaging and transport of Netherwing crystals and relics. Dragonmaw Transporters transport the goods from the dock to Dragonmaw Fortress while Dragonmaw Ascendants guard the ground from any would-be attackers.$B$BThis leaves one opening for you to make a strike at the Dragonmaw: The Dragonmaw Skyway.$B$BFly to the shattered islands of the Dragonmaw Skyway and ambush the transporters that use the route. Recover our stolen relics!",logDesc="Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to recover 10 Netherwing Relics."} end
if not DB[11036] then DB[11036]={id=11036,zoneId=3522,name="Out of This World Produce!",level=67,minLevel=67,giver="Old Orok",giverType="NPC",giverId=19471,ender="Rocket-Chief Fuselage",enderType="NPC",enderId=19570,rewardNextId=10186,poiX=2438,poiY=5960,wowhead="https://www.wowhead.com/wotlk/quest=11036",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I'll be the first to admit I'm not quite sure what this order is for, but Rocket-Chief Fuselage's instructions were very specific -- only the very best fruit, preserved to survive a long voyage and sealed against the elements.$B$BThere were other specifications, zero-gravity this and low pressure that. I don't pretend to understand it, but the price is right, so he'll get his superfood. Bring this crate to him up at Area 52. After crossing into Netherstorm, keep following the road until you see the town.",logDesc="Bring the Preserved Fruit to Rocket-Chief Fuselage at Area 52 in the Netherstorm."} end
if not DB[11037] then DB[11037]={id=11037,zoneId=3518,name="A Strange Vision",level=67,minLevel=67,giver="Seer Nakha",giverType="NPC",giverId=23265,ender="Rocket-Chief Fuselage",enderType="NPC",enderId=19570,rewardNextId=10186,poiX=-1334,poiY=7222,wowhead="https://www.wowhead.com/wotlk/quest=11037",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I've had a most unusual vision, $N, and I don't know quite what to make of it. I've seen an arrow, an immense arrow, riding into the sky on a trail of fire. Such a feat is trivial for a skilled mage, but somehow I know the arrow I saw is not the product of magic.$B$BIt will be unlike anything the people of Azeroth have ever achieved. You must seek out the people working on this, $N. Lend them your help, for without it, their efforts may yet fail.",logDesc="Speak with Rocket-Chief Fuselage at Area 52."} end
if not DB[11038] then DB[11038]={id=11038,zoneId=3703,name="Assist Exarch Orelis",level=67,minLevel=67,giver="Vindicator Aeus",giverType="NPC",giverId=23270,ender="Exarch Orelis",enderType="NPC",enderId=19466,rewardNextId=10241,poiX=-1701,poiY=5519,wowhead="https://www.wowhead.com/wotlk/quest=11038",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Not long ago, High Priestess Ishanah sent a small group of anchorites to Netherstorm, under the command of Exarch Orelis. They were to investigate the activities of Kael'thas and his minions, but we haven't received any reports of their findings yet.$B$BI worry that our presence in the area might not be strong enough to carry out the mission. I'm certain that the exarch could benefit from your knowledge and experience. Are you willing to travel to Area 52 and assist him?",logDesc="Speak with Exarch Orelis at Area 52."} end
if not DB[11039] then DB[11039]={id=11039,zoneId=3703,name="Report to Spymaster Thalodien",level=67,minLevel=67,giver="Arcanist Savan",giverType="NPC",giverId=23272,ender="Spymaster Thalodien",enderType="NPC",enderId=19468,rewardNextId=10189,poiX=-2139,poiY=5553,wowhead="https://www.wowhead.com/wotlk/quest=11039",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Some time ago, Voren'thal dispatched a small team to Netherstorm to investigate the activities of Kael'thas. Our leader has the utmost confidence in Spymaster Thalodien and his compatriots, and has decided to honor his request for reinforcements.$B$BThalodien's report was brief, but clear that he's encountered something of great importance. Report to him at Area 52 and assist him in any way possible, $N.",logDesc="Report to Spymaster Thalodien at Area 52."} end
if not DB[11040] then DB[11040]={id=11040,zoneId=3522,name="Parts for the Rocket-Chief",level=67,minLevel=67,giver="Bossi Pentapiston",giverType="NPC",giverId=21112,ender="Rocket-Chief Fuselage",enderType="NPC",enderId=19570,rewardNextId=10186,poiX=1910,poiY=5548,wowhead="https://www.wowhead.com/wotlk/quest=11040",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You can count on one hand the number of times I've collaborated with a goblin. We're far more likely to be in competition with them, but when I received Rocket-Chief Fuselage's request, I just couldn't refuse him.$B$BThis crate is full of parts I'm not using here, but that the rocket-chief might be able to put to use on his project. Would you be kind enough to deliver them if you're on your way to Area 52?$B$BWho knows, maybe some fine gnomish parts could keep his creation from exploding!",logDesc="Bring Bossi's Spare Parts to Rocket-Chief Fuselage at Area 52 in the Netherstorm."} end
if not DB[11041] then DB[11041]={id=11041,zoneId=3520,name="A Job Unfinished...",level=70,minLevel=70,ender="Overlord Mor'ghor",enderType="NPC",enderId=23139,wowhead="https://www.wowhead.com/wotlk/quest=11041",image="assets/images/quests/placeholder.png",xpDiff=5,money=132000,desc="In the name of our great master... For the glory of Illidan!$B$BBy order of Overlord Mor'ghor, the great plateau of Netherwing Ledge is to be secured. With all Netherwing drakes captured or forced off of the land, rock flayers are running rampant and threatening crystal harvesting operations.$B$BDestroy them all, their den mother and her consort, Arvoar.$B$BMor'ghor commands it!$B$B<It would appear that this orc failed to take the plateau. It is time to prove your worth to Mor'ghor!>",logDesc="Slay 10 Overmine Flayers and Barash the Den Mother. Return to Overlord Mor'ghor at the Dragonmaw Base Camp should you succeed.",choiceRewards={{id=32866,qty=1},{id=32867,qty=1},{id=32865,qty=1},{id=32868,qty=1}}} end
if not DB[11042] then DB[11042]={id=11042,zoneId=3518,name="A Mystifying Vision",level=67,minLevel=67,giver="Seer Jovar",giverType="NPC",giverId=23268,ender="Rocket-Chief Fuselage",enderType="NPC",enderId=19570,rewardNextId=10186,poiX=-2488,poiY=7234,wowhead="https://www.wowhead.com/wotlk/quest=11042",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A strange vision haunts me, $N. I see a continuous cloud of smoke ascending toward the sky, left in the wake of a giant fire moving ever faster away. It is not a natural phenomenon, nor a creation of evil; that much I know.$B$BI have no knowledge of what it looks like, save that it is the product of the labor of many. Yet, without more hands, it may never come to be.$B$BTravel to Netherstorm, $c. Locate those responsible for this creation and offer them your aid.",logDesc="Speak with Rocket-Chief Fuselage at Area 52."} end
if not DB[11043] then DB[11043]={id=11043,zoneId=3522,name="Building a Better Gryphon",level=67,minLevel=67,giver="Rip Pedalslam",giverType="NPC",giverId=21107,ender="Brunn Flamebeard",enderType="NPC",enderId=20510,poiX=1861,poiY=5528,wowhead="https://www.wowhead.com/wotlk/quest=11043",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I've heard that the Wildhammer dwarves maintain a gryphon roost at their fortress down in southern Shadowmoon Valley. If you're going down there, would you speak to them on my behalf? I have some ideas on how to improve their gryphons!$B$BWhy stop at armoring them when you could attach an altimeter, a rear view mirror, and rocket? Imagine how fast you could go with one of those babies strapped to your gryphon's back! I'll call it the TurboGryphon 8000!",logDesc="Speak with Brunn Flamebeard at Wildhammer Stronghold in Shadowmoon Valley."} end
if not DB[11044] then DB[11044]={id=11044,zoneId=3518,name="Visions of Destruction",level=67,minLevel=67,giver="Seer Jovar",giverType="NPC",giverId=23268,ender="Wing Commander Nuainn",enderType="NPC",enderId=21357,rewardNextId=10562,poiX=-2488,poiY=7234,wowhead="https://www.wowhead.com/wotlk/quest=11044",image="assets/images/quests/placeholder.png",xpDiff=1,desc="A vision of cataclysm often disturbs my rest -- a rain of green fire falling to the earth, felling the valiant defenders of a mighty fortress. It has haunted me for weeks now, although I have only recently come to understand its meaning.$B$BTo the far east, in Shadowmoon Valley, the Wildhammer dwarves endure constant attacks from the Burning Legion and numerous other foes. They fight bravely, but without relief, their enemies will triumph. Go to their side, $N. Help them in their fight.",logDesc="Speak with Wing Commander Nuainn at Wildhammer Stronghold."} end
if not DB[11045] then DB[11045]={id=11045,zoneId=3703,name="Zorus the Judicator",level=67,minLevel=67,giver="Fantei",giverType="NPC",giverId=19678,ender="Zorus the Judicator",enderType="NPC",enderId=21774,rewardNextId=10642,poiX=-2090,poiY=5290,wowhead="https://www.wowhead.com/wotlk/quest=11045",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The history of Shadowmoon Valley is a long and troubled one. Few delve into it for fear of breathing new life into the unspeakable atrocities that took place there.$B$BNot all are so timid, though. Zorus the Judicator searches for the truth about the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which he would welcome help, I'm sure.$B$BIf you should venture into the valley, look for Zorus at Wildhammer Stronghold, in the central portion of the valley's southern region.",logDesc="Speak with Zorus the Judicator at Wildhammer Stronghold."} end
if not DB[11046] then DB[11046]={id=11046,zoneId=3703,name="Chief Apothecary Hildagard",level=67,minLevel=67,giver="Fantei",giverType="NPC",giverId=19678,ender="Chief Apothecary Hildagard",enderType="NPC",enderId=21772,rewardNextId=10624,poiX=-2090,poiY=5290,wowhead="https://www.wowhead.com/wotlk/quest=11046",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The history of Shadowmoon Valley is a long and troubled one. Few study it for fear of breathing new life into the unspeakable atrocities that took place there.$B$BNot all are so timid, though. Chief Apothecary Hildagard's research delves into the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which she would welcome help, I'm sure.$B$BIf your travels bring you there, seek Hildagard at Shadowmoon Village, in the northwestern reaches of the valley.",logDesc="Speak with Chief Apothecary Hildagard at Shadowmoon Village."} end
if not DB[11047] then DB[11047]={id=11047,zoneId=3522,name="The Apprentice's Request",level=67,minLevel=67,giver="Agadai",giverType="NPC",giverId=23280,ender="Dama Wildmane",enderType="NPC",enderId=20494,poiX=2441,poiY=6028,wowhead="https://www.wowhead.com/wotlk/quest=11047",image="assets/images/quests/placeholder.png",xpDiff=1,desc="As an apprentice wind rider master, one of my tasks is to care for the beasts when they're not flying. The problem is that we have so few here, there's very little downtime for any of them.$B$BI'm afraid we'll work them all to death if we don't receive any replacements. There's a large stable down in Shadowmoon Village, in western Shadowmoon Valley. Dama Wildmane oversees the wind rider care and training there.$B$BWould you speak with her on our behalf and let her know about our situation?",logDesc="Speak with Dama Wildmane at Shadowmoon Village in Shadowmoon Valley."} end
if not DB[11048] then DB[11048]={id=11048,zoneId=3518,name="Kroghan's Report",level=67,minLevel=67,giver="Captain Kroghan",giverType="NPC",giverId=18090,ender="Blood Guard Gulmok",enderType="NPC",enderId=21359,rewardNextId=10595,poiX=-1338,poiY=7237,wowhead="https://www.wowhead.com/wotlk/quest=11048",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My original orders were to remain in Garadar for a short time, then continue on and report to Blood Guard Gulmok at Shadowmoon Village. What I've seen in my time here is that Garadar could benefit from a long term Horde liaison.$B$BI know that Blood Guard Gulmok needs all the troops he can get, but I know he'll understand that my mission here isn't yet complete. Travel to Shadowmoon Village, in northwestern Shadowmoon Valley, and inform Blood Guard Gulmok of my delayed arrival.",logDesc="Speak with Blood Guard Gulmok at Shadowmoon Village."} end
if not DB[11049] then DB[11049]={id=11049,zoneId=3520,name="The Great Netherwing Egg Hunt",level=70,minLevel=70,giver="Yarzill the Merc",giverType="NPC",giverId=23141,ender="Yarzill the Merc",enderType="NPC",enderId=23141,poiX=-5118,poiY=594,wowhead="https://www.wowhead.com/wotlk/quest=11049",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="Should you discover any Netherwing eggs while exploring, bring them to me.$B$BBe warned, a Netherwing egg is a rare discovery. Do not become frustrated if you cannot locate one. These Dragonmaw have been very thorough in collecting most of them and shipping them off to parts unknown.$B$BEggs might be found on creatures of the island, near crystal formations, in the mines, or even inside a nethercite node or netherdust bush.$B$BKeep a low profile. We don't need Mor'ghor catching wind of your actions.",logDesc="Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to recover a Netherwing Egg."} end
if not DB[11050] then DB[11050]={id=11050,zoneId=3520,name="Accepting All Eggs",level=70,minLevel=70,giver="Yarzill the Merc",giverType="NPC",giverId=23141,ender="Yarzill the Merc",enderType="NPC",enderId=23141,poiX=-5118,poiY=594,wowhead="https://www.wowhead.com/wotlk/quest=11050",image="assets/images/quests/placeholder.png"} end
if not DB[11051] then DB[11051]={id=11051,zoneId=3522,name="Banish More Demons",level=70,minLevel=70,giver="Kronk",giverType="NPC",giverId=23253,ender="Kronk",enderType="NPC",enderId=23253,poiX=2314,poiY=7278,wowhead="https://www.wowhead.com/wotlk/quest=11051",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="If we know the demons, and we do because we've studied them extensively, they're fast at work repairing any damage that has been done to their precious transporter.$B$BSo, if you want a chance at another darkrune, take our banishing crystal back out there and eliminate more demons.  Besides, you want to help us to lessen the threat that the demons pose, yes?$B$BWe said \"chance\" because the process we use yields mixed results.  You might get a darkrune, or you might get something else entirely.",logDesc="Use the Banishing Crystal to banish 15 demons at Forge Camp: Wrath or Forge Camp: Terror.",rewards={{id=32777,qty=1},{id=32569,qty=15}}} end
if not DB[11052] then DB[11052]={id=11052,zoneId=3520,name="Akama's Promise",level=70,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=11052",image="assets/images/quests/placeholder.png",xpDiff=7,desc="<Akama inserts the crystal into the medallion in his hand.>$B$BI am not as strong as I once was, $N.  Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.$B$BTake this as my promise to you that when the time comes and you face Illidan, I will be on your side.  Take it to the one being we know we can trust with its power.  Take the medallion to A'dal in Shattrath City.",logDesc="Bring the Medallion of Karabor to A'dal in Shattrath City.",choiceRewards={{id=30932,qty=1},{id=30999,qty=1},{id=31000,qty=1},{id=30943,qty=1},{id=30984,qty=1},{id=31417,qty=1}}} end
if not DB[11053] then DB[11053]={id=11053,zoneId=3520,name="Rise, Overseer!",level=70,minLevel=70,giver="Taskmaster Varkule Dragonbreath",giverType="NPC",giverId=23140,ender="Overlord Mor'ghor",enderType="NPC",enderId=23139,poiX=-5114,poiY=588,wowhead="https://www.wowhead.com/wotlk/quest=11053",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Rare it is that a peon survives for as long as you have. Rarer still is when a peon rises from the dregs to attain a new rank.$B$B<Varkule claps.>$B$BThe Overlord has called for you, grunt. A new rank awaits, no doubt.",logDesc="Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.",rewards={{id=32694,qty=1}}} end
if not DB[11054] then DB[11054]={id=11054,zoneId=3520,name="Overseeing and You: Making the Right Choices",level=70,minLevel=70,giver="Chief Overseer Mudlump",giverType="NPC",giverId=23291,ender="Chief Overseer Mudlump",enderType="NPC",enderId=23291,rewardNextId=11055,poiX=-5105,poiY=549,wowhead="https://www.wowhead.com/wotlk/quest=11054",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="So you're the new overseer, eh? Well there's one thing any good overseer needs and that's the proper disciplinary weapon. Before you can go out there and knock some sense into these peons you need to have your \"piece.\" Each overseer has to gather the materials required to make their own \"piece\" and you'll be no different.$B$BI'll need knothide leather and the hardened hide of Tyrantus. You'll find Tyrantus in Eco-Dome Farfield, located in the northern reaches of Netherstorm.",logDesc="Chief Overseer Mudlump at the Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 10 pieces of Knothide Leather and 1 Hardened Hide of Tyrantus.$B"} end
if not DB[11055] then DB[11055]={id=11055,zoneId=3520,name="The Booterang: A Cure For The Common Worthless Peon",level=70,minLevel=70,giver="Chief Overseer Mudlump",giverType="NPC",giverId=23291,ender="Chief Overseer Mudlump",enderType="NPC",enderId=23291,poiX=-5105,poiY=549,wowhead="https://www.wowhead.com/wotlk/quest=11055",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="This is your booterang. There are many like it but this one is yours.$B$BAs an overseer you will use this booterang to sow terror into the hearts of defiant peons. Proper use of the booterang will instill obedience and ensure subservience.$B$BVenture forth to the crystal fields and discipline any peons that you see slacking off. Show them the might of the booterang!$B",logDesc="Chief Overseer Mudlump at the Dragonmaw Base Camp in Shadowmoon Valley wants you to discipline 20 lazy Dragonmaw Peons. You will also need to return your Booterang."} end
if not DB[11056] then DB[11056]={id=11056,zoneId=3679,name="Hazzik's Bargain",level=70,minLevel=70,giver="Hazzik",giverType="NPC",giverId=23306,ender="Hazzik",enderType="NPC",enderId=23306,rewardNextId=11029,poiX=-3411,poiY=3615,wowhead="https://www.wowhead.com/wotlk/quest=11056",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Do not draw attention to our conversation.  Adaris would not approve.$B$BI belong to the lowest caste of arakkoa, $N.  During Terokk's rule I would've been sacrificed to the dark powers worshipped by his talonpriests.  If what you say is true and the talonpriests are seeking Terokk's return, then you must prevent them from succeeding - regardless of what your leader says!$B$BI've something to offer you that you'll find useful.  There is a package at my old dwelling in Upper Veil Shil'ak.  Bring it to me!",logDesc="Obtain Hazzik's Package at his dwelling in eastern Skettis and return to him with it."} end
if not DB[11057] then DB[11057]={id=11057,zoneId=3522,name="The Trouble Below",level=70,minLevel=70,giver="Chu'a'lor",giverType="NPC",giverId=23233,ender="Mog'dorg the Wizened",enderType="NPC",enderId=22941,poiX=2335,poiY=7285,wowhead="https://www.wowhead.com/wotlk/quest=11057",image="assets/images/quests/placeholder.png",desc="We commend your zeal in wanting to help out here in Ogri'la, $c.  However, we have a favor to ask of you before we can accept your assistance.$B$BDown below our brethren are enslaved to the Sons of Gruul.  Please, speak with Mog'dorg the Wizened, who is leading an ogre resistance against their gronn masters.$B$BSeek him out atop the tower on the eastern side of the Circle of Blood arena.",logDesc="Speak with Mog'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade's Edge Mountains.$B"} end
if not DB[11058] then DB[11058]={id=11058,zoneId=3522,name="An Apexis Relic",level=70,minLevel=70,giver="Chu'a'lor",giverType="NPC",giverId=23233,ender="Chu'a'lor",enderType="NPC",enderId=23233,rewardNextId=11080,poiX=2335,poiY=7285,wowhead="https://www.wowhead.com/wotlk/quest=11058",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Long ago a now-extinct sect of the arakkoa known as the Apexis lived here.  Remnants of their civilization are still present.  We call them apexis relics.$B$BWhat we know about them is that, when properly used, they grant a boon.  Each relic presents a colored sequence which, when the crystals are pressed in the correct order, leads through a series of levels, each harder than the last.$B$BAn apexis shard is needed to power the relic.  Return when you have attained the insight of the apexis vibration.",logDesc="Gain Apexis Vibrations from an Apexis Relic."} end
if not DB[11059] then DB[11059]={id=11059,zoneId=3522,name="Guardian of the Monument",level=70,minLevel=70,giver="Chu'a'lor",giverType="NPC",giverId=23233,ender="Chu'a'lor",enderType="NPC",enderId=23233,poiX=2335,poiY=7285,wowhead="https://www.wowhead.com/wotlk/quest=11059",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="You've figured out how to use the single-person relics, but as you may have seen, there are bigger ones, which they surround.$B$BThese larger apexis monuments function in much the same way, but they take many more apexis shards to activate and require four persons to operate.$B$BOf greater concern to us are the guardians that are summoned through their use.  These crystal constructs turned on their arakkoan masters long ago, and now endanger Ogri'la.$B$BWe would ask that you destroy one and bring us proof.",logDesc="Collect an Apexis Guardian's Head."} end
if not DB[11060] then DB[11060]={id=11060,zoneId=3522,name="A Crystalforged Darkrune",level=70,minLevel=70,giver="Gahk",giverType="NPC",giverId=23300,ender="Gahk",enderType="NPC",enderId=23300,poiX=2308,poiY=7300,wowhead="https://www.wowhead.com/wotlk/quest=11060",image="assets/images/quests/placeholder.png",xpDiff=1,money=4400,rewards={{id=32602,qty=1}}} end
if not DB[11061] then DB[11061]={id=11061,zoneId=3522,name="A Father's Duty",level=70,minLevel=70,giver="Torkus",giverType="NPC",giverId=23316,ender="Torkus",enderType="NPC",enderId=23316,poiX=2323,poiY=7307,wowhead="https://www.wowhead.com/wotlk/quest=11061",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="As to that other magical flask, it can only be obtained from one spot: Bash'ir Landing.  It's an ethereal base, and they aren't too friendly with outsiders, so it might be a little dangerous to obtain.$B$BWhere's Bash'ir Landing, you ask?  Well, if you get on your flying steed and head north by northeast, well past Forge Camp: Wrath, you'll eventually spot it.  The Bash'ir crystalforge itself is at the northeast corner of the landing.$B$BThank you for doing this, $N.  It'll mean the world to our sons!",logDesc="Collect an Unstable Flask of the Sorcerer for him."} end
if not DB[11062] then DB[11062]={id=11062,zoneId=3522,name="The Skyguard Outpost",level=70,minLevel=70,giver="Chu'a'lor",giverType="NPC",giverId=23233,ender="Sky Commander Keller",enderType="NPC",enderId=23334,poiX=2335,poiY=7285,wowhead="https://www.wowhead.com/wotlk/quest=11062",image="assets/images/quests/placeholder.png",xpDiff=1,money=4400,desc="$N, we were wondering if you might be willing to visit our friends just to the north at the Skyguard Outpost?$B$BSky Commander Keller and his Skyguard are here running missions for our mutual protection, and he's asked us to send along anyone that we feel would excel at helping out.$B$BThat would be you!$B$BHead up there as soon as you can, and please, give him our regards.",logDesc="Speak with Sky Commander Keller at the Skyguard Outpost in the Blade's Edge Mountains."} end
if not DB[11063] then DB[11063]={id=11063,zoneId=3520,name="Earning Your Wings...",level=70,minLevel=70,giver="Ja'y Nosliw",giverType="NPC",giverId=22433,ender="Ja'y Nosliw",enderType="NPC",enderId=22433,poiX=-5144,poiY=601,wowhead="https://www.wowhead.com/wotlk/quest=11063",image="assets/images/quests/placeholder.png"} end
if not DB[11064] then DB[11064]={id=11064,zoneId=3520,name="Dragonmaw Race: The Ballad of Oldie McOld",level=70,minLevel=70,giver="3",giverType="NPC",giverId=23340,ender="Ja'y Nosliw",enderType="NPC",enderId=22433,poiX=-5089,poiY=641,wowhead="https://www.wowhead.com/wotlk/quest=11064",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Don't let the gray hair fool you, grunt. I'm still ten times the rider that you are! And don't go thinking that this old dog doesn't have any tricks up his sleeve.$B$BNow all you gotta do is follow me and try not to get knocked down off your mount. If you can do that, Oldie will admit defeat.$B$BWe'll lift off as soon as you're ready.$B",logDesc="Follow Murg \"Oldie\" Muckjaw while attempting to stay on your flying mount. Should you defeat Murg \"Oldie\" Muckjaw, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley."} end
if not DB[11065] then DB[11065]={id=11065,zoneId=3522,name="Wrangle Some Aether Rays!",level=70,minLevel=70,giver="Skyguard Khatie",giverType="NPC",giverId=23335,ender="Skyguard Khatie",enderType="NPC",enderId=23335,rewardNextId=11066,poiX=2547,poiY=7331,wowhead="https://www.wowhead.com/wotlk/quest=11065",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Wanna help the Skyguard and Ogri'la?$B$BJust hear me out before you walk away, $g hot stuff : girly;.  We're in need of remounts!  The bombing runs and missions to Bash'ir Landing have taken a toll on our mounts.$B$BThe aether rays that fly around Vortex Pinnacle, and the Crystal Spine to the northeast, look like they'd do just fine.  You don't even have to bring them back here, though that would be nice.  Just break and rope them, and we'll track them down later.$B$BThink you can wrangle me up some?",logDesc="Use the Wrangling Rope to capture 5 Aether Rays."} end
if not DB[11066] then DB[11066]={id=11066,zoneId=3522,name="Wrangle More Aether Rays!",level=70,minLevel=70,giver="Skyguard Khatie",giverType="NPC",giverId=23335,ender="Skyguard Khatie",enderType="NPC",enderId=23335,poiX=2547,poiY=7331,wowhead="https://www.wowhead.com/wotlk/quest=11066",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="So, I hope that you're up to helping us wrangle up even more aether rays!  From what I can see, you're a natural with the rope!  And it's for a good cause, because not only do we get fresh mounts, but it helps us to protect Ogri'la, which the ogres appreciate.$B$BRemember, the aether rays fly around Vortex Pinnacle, and the Crystal Spine to the northeast.$B$BThink you can wrangle me up some more?",logDesc="Use the Wrangling Rope to capture 5 Aether Rays.",rewards={{id=32569,qty=15}}} end
if not DB[11067] then DB[11067]={id=11067,zoneId=3520,name="Dragonmaw Race: Trope the Filth-Belcher",level=70,minLevel=70,giver="3",giverType="NPC",giverId=23342,ender="Ja'y Nosliw",enderType="NPC",enderId=22433,poiX=-5082,poiY=641,wowhead="https://www.wowhead.com/wotlk/quest=11067",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Dragonmaw treat you right, $N. Even a worn out cursed being like me is given a chance. Now if you want to prove your worth to the Skybreakers, you will have to defeat me.$B$BI'm going to shake you off my tail like a bad case of fleas...$B$BWe'll lift off when you are ready.",logDesc="Follow Trope the Filth-Belcher while attempting to stay on your flying mount. Should you defeat Trope the Filth-Belcher, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley."} end
if not DB[11068] then DB[11068]={id=11068,zoneId=3520,name="Dragonmaw Race: Corlok the Vet",level=70,minLevel=70,giver="3",giverType="NPC",giverId=23344,ender="Ja'y Nosliw",enderType="NPC",enderId=22433,poiX=-5073,poiY=640,wowhead="https://www.wowhead.com/wotlk/quest=11068",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="You are challenging ME? Don't make me laugh!$B$BYou're serious? Very well then! All you need to do is not die. You can manage to not die, right?? Even if I'm hurling skulls at you and flying circles around your pathetic riding skills?$B$BJust let me know when you're ready and we'll lift off.",logDesc="Follow Corlok the Vet while attempting to stay on your flying mount. Should you defeat Corlok the Vet, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley."} end
if not DB[11069] then DB[11069]={id=11069,zoneId=3520,name="Dragonmaw Race: Wing Commander Ichman",level=70,minLevel=70,giver="3",giverType="NPC",giverId=23345,ender="Ja'y Nosliw",enderType="NPC",enderId=22433,poiX=-5066,poiY=640,wowhead="https://www.wowhead.com/wotlk/quest=11069",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="Three years I spent in that hell hole. Three years a prisoner of war to the damnable Frostwolf Clan. Made to sit in their tower and listen to them endlessly whine about the bridge to Dun Baldar. About how it's \"unfair\" that blah, blah, blah, blah... War isn't fair! To hell with 'em all!$B$BThe minute I was freed I left that place forever and came here to start a new life. Now Mulv and I are vying for the top orc spot. If you want it, you're gonna have to go through me, scrub.$B$BWe go when you're ready.$B",logDesc="Follow Wing Commander Ichman while attempting to stay on your flying mount. Should you defeat Wing Commander Ichman, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley."} end
if not DB[11070] then DB[11070]={id=11070,zoneId=3520,name="Dragonmaw Race: Wing Commander Mulverick",level=70,minLevel=70,giver="3",giverType="NPC",giverId=23346,ender="Ja'y Nosliw",enderType="NPC",enderId=22433,poiX=-5060,poiY=640,wowhead="https://www.wowhead.com/wotlk/quest=11070",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="Three years of blood, sweat and tears. Mostly tears... The amount of crying that a hardened soldier does when it comes down to all-out war is amazing!$B$B\"They're jumping into our tower with their horses!\" \"Why is their base so well defended?\" \"They're taking our relief hut, I'm going A.W.O.L.!\"$B$BWimps...$B$BI took the first train out of \"cry-town\" the minute the Dark Portal opened. Now I'm a top gun for the Dragonmaw. If you want to be top orc, you'll have to defeat me.$B$BWe go when you are ready.$B",logDesc="Follow Wing Commander Mulverick while attempting to stay on your flying mount. Should you defeat Wing Commander Mulverick, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.$B"} end
if not DB[11071] then DB[11071]={id=11071,zoneId=3520,name="Dragonmaw Race: Captain Skyshatter",level=70,minLevel=70,giver="3",giverType="NPC",giverId=23348,ender="Ja'y Nosliw",enderType="NPC",enderId=22433,poiX=-5075,poiY=625,wowhead="https://www.wowhead.com/wotlk/quest=11071",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="You dare challenge Skyshatter? The world around you will fall into darkness as the heavens are torn asunder by my meteors.$B$BYou stand no chance, soldier. Yet it is your desire to die...$B$BI will entertain this morbid obsession if only to prove a point to any that might foolishly dream of making the same mistake.$B$BWe ride when you are ready!",logDesc="Follow Captain Skyshatter while attempting to stay on your flying mount. Should you defeat Captain Skyshatter, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.",rewards={{id=32863,qty=1}}} end
if not DB[11072] then DB[11072]={id=11072,zoneId=3679,name="Adversarial Blood",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=11072",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.$B$BYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.",logDesc="Find the Skull Piles in the middle of the summoning circles of Skettis. Summon and defeat each of the descendants by using 10 Time-Lost Scrolls at the Skull Pile.  Return to Hazzik at Blackwind Landing with a token from each.",rewards={{id=32720,qty=1}}} end
if not DB[11073] then DB[11073]={id=11073,zoneId=3679,name="Terokk's Downfall",level=70,minLevel=70,giver="Sky Commander Adaris",giverType="NPC",giverId=23038,ender="Sky Commander Adaris",enderType="NPC",enderId=23038,poiX=-3408,poiY=3623,wowhead="https://www.wowhead.com/wotlk/quest=11073",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="I... I've turned a blind eye to your dealings with the arakkoa prisoner, $N.  It looks like your instincts to cooperate with him were right.$B$BYou must understand... I would've faced a mutiny in my current state if I endorsed your efforts to bring Terokk to this world.$B$BTake the items that Hazzik prepared for you and go ahead with your plan.  I will command my men to back you up when the time comes.  I recommend that you bring a force of your own as well.  I fear you'll only get one chance at this.",logDesc="Take the Time-Lost Offering prepared by Hazzik to the Skull Pile at the center of Skettis and summon and defeat Terokk.  Return to Sky Commander Adaris when you've completed this task.",choiceRewards={{id=32831,qty=1},{id=32832,qty=1},{id=32830,qty=1},{id=32829,qty=1}}} end
if not DB[11074] then DB[11074]={id=11074,zoneId=3519,name="Tokens of the Descendants",level=70,minLevel=70,giver="Hazzik",giverType="NPC",giverId=23306,ender="Hazzik",enderType="NPC",enderId=23306,poiX=-3411,poiY=3615,wowhead="https://www.wowhead.com/wotlk/quest=11074",image="assets/images/quests/placeholder.png",desc="The descendants held prisoner by the Skettis talonpriests are listed in this book.  Gezzarak the Huntress, Garokk the Crystal Giant, the heretic known as Darkscreecher Akkarai and Vekkaz the Windrager.  They will all need to be slain before Terokk returns to this world.$B$BYou will need the scrolls carried by the time-lost arakkoa and burn them at the summoning circles all over Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.",logDesc="Collect Time-Lost Scrolls from the time-lost arakkoa in Skettis and bring them to a Skull Pile inside a summoning circle in Skettis.  Summon and defeat the descendants of Terokk's adversaries and return to Hakkiz with Akkarai's Talon, Garokk's Spine, Vekkaz's Scale and Gezzarak's Claw.",rewards={{id=32720,qty=1}}} end
if not DB[11075] then DB[11075]={id=11075,zoneId=3520,name="The Netherwing Mines",level=70,minLevel=70,giver="Taskmaster Varkule Dragonbreath",giverType="NPC",giverId=23140,ender="Mistress of the Mines",enderType="NPC",enderId=23149,rewardNextId=11076,poiX=-5114,poiY=588,wowhead="https://www.wowhead.com/wotlk/quest=11075",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Your help is required at the Netherwing Mines, overseer $N.$B$BTwo days ago our mining operations came to a grinding halt when we made a grim discovery. A miner was working in the depths of the mine and struck his pick upon an unusual crystal formation. Unfortunately, this crystal formation was attached to a very angry nether dragon. The beast woke from its slumber and annihilated all of our workers.$B$BReport to the Mistress of the Mines. They await you at the mouth of the mines, southwest of here.",logDesc="Seek out the Mistress of the Mines on Netherwing Ledge."} end
if not DB[11076] then DB[11076]={id=11076,zoneId=3520,name="Picking Up The Pieces...",level=70,minLevel=70,giver="Mistress of the Mines",giverType="NPC",giverId=23149,ender="Mistress of the Mines",enderType="NPC",enderId=23149,poiX=-5165,poiY=757,wowhead="https://www.wowhead.com/wotlk/quest=11076",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="Much of our hard work lies scattered about in these mines. Carts full of cargo are littered across every inch of this mine! We just can't get to any of it with the current infestation.$B$BThat's where you come in, $N. Your daily duty here at this mine is to collect the cargo left behind by the miners and deep mine workers.$B$BGather the nethermine cargo and return it to me or my sister.",logDesc="The Mistress of the Mines at the Netherwing Mines in Shadowmoon Valley wants you to recover 15 Nethermine Cargo crates."} end
if not DB[11077] then DB[11077]={id=11077,zoneId=3520,name="Dragons are the Least of Our Problems",level=70,minLevel=70,giver="Dragonmaw Foreman",giverType="NPC",giverId=23376,ender="Dragonmaw Foreman",enderType="NPC",enderId=23376,poiX=-5129,poiY=681,wowhead="https://www.wowhead.com/wotlk/quest=11077",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="That dragon waking up riled up a host of other nasty creatures in these mines. Two types are proving to be a thorn in the side of the Dragonmaw: Nethermine flayers and Nethermine ravagers. You must help us by killing them off. All I ask is your involvement once per day.$B$BGet in there and kill as many as you can!",logDesc="The Dragonmaw Foreman at the Netherwing Mines in Shadowmoon Valley wants you to kill 15 Nethermine Flayers and 5 Nethermine Ravagers."} end
if not DB[11078] then DB[11078]={id=11078,zoneId=3522,name="To Rule The Skies",level=70,minLevel=70,giver="Sky Commander Keller",giverType="NPC",giverId=23334,ender="Sky Commander Keller",enderType="NPC",enderId=23334,poiX=2503,poiY=7360,wowhead="https://www.wowhead.com/wotlk/quest=11078",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="As ye've flown around, ye must have noticed the dragons above.  I trust ye haven't fallen victim ta their rage.  Help us put an end ta it, $N!$B$BRivendark and Obsidia lord over this terrace, while Insidion and Furywing rule the skies over yon terrace ta the northeast.  Each has a perch on their respective domains.  I be wondering if ye and yer friends will go ta one, $g lad : lass;, break open an egg and attract the dragon down.$B$BBring me some teeth as proof.  Ta rule the skies, it's either them or us.",logDesc="Collect Dragon Teeth."} end
if not DB[11079] then DB[11079]={id=11079,zoneId=3522,name="A Fel Whip For Gahk",level=70,minLevel=70,giver="Gahk",giverType="NPC",giverId=23300,ender="Gahk",enderType="NPC",enderId=23300,poiX=2308,poiY=7300,wowhead="https://www.wowhead.com/wotlk/quest=11079",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Gahk think being smart is dumb sometimes.  Gahk not want to think.  Me want little $r to smash big demons!$B$BDey have some chiefs, and da chiefs all have whips to hurt da little demons.  You bring Gahk a whip!$B$BYou challenge demon chief in forge camps at burning, green, fel crystal prism.  Use many apexis shards to get dem to come.  Dey called Galvanoth, Braxxus, Zarcsin and da Mo'arg Incinerator.",logDesc="Collect a Fel Whip."} end
if not DB[11080] then DB[11080]={id=11080,zoneId=3522,name="The Relic's Emanation",level=70,minLevel=70,giver="Chu'a'lor",giverType="NPC",giverId=23233,ender="Chu'a'lor",enderType="NPC",enderId=23233,poiX=2335,poiY=7285,wowhead="https://www.wowhead.com/wotlk/quest=11080",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="Now that you have felt the enlightening vibrations of the apexis relics, it is time for you to further your understanding of their workings.  We are very eager to benefit from your observations!$B$BAs you progress in your ability to attune to the relics, you will gain a higher level of knowledge.  This recognition will come in the form of an emanation from the relic.$B$BReturn to us when you have attained such an emanation.",logDesc="Gain Apexis Emanations from an Apexis Relic.",rewards={{id=32569,qty=15}}} end
if not DB[11081] then DB[11081]={id=11081,zoneId=3520,name="The Great Murkblood Revolt",level=70,minLevel=70,ender="Mistress of the Mines",enderType="NPC",enderId=23149,rewardNextId=11082,wowhead="https://www.wowhead.com/wotlk/quest=11081",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This document outlines a revolt planned by the Murkblood broken. It seems that the dragon was to be used as a diversion to draw attention away from their escape. Looking at all of the corpses littering the mine, it would be safe to assume that their plans failed.$B$BReturn the escape plans to the Mistress of the Mines.",logDesc="Take the Murkblood Escape Plans to the Mistress of the Mines."} end
if not DB[11082] then DB[11082]={id=11082,zoneId=3520,name="Seeker of Truth",level=70,minLevel=70,giver="Mistress of the Mines",giverType="NPC",giverId=23149,ender="Mistress of the Mines",enderType="NPC",enderId=23149,poiX=-5165,poiY=757,wowhead="https://www.wowhead.com/wotlk/quest=11082",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="These miners are far too stupid to concoct any type of escape plan. We must find and punish the source. Venture into the depths of the mine and seek out the Murkblood overseers. If they have not been overcome by the denizens of the mine, they will undoubtedly be hiding.$B$BOnce you locate one, interrogate him until he reveals the true mastermind behind the escape. Return to me with the identity of this traitor and the hand of the overseer.",logDesc="Find a Murkblood Overseer and interrogate him. Return to the Mistress of the Mines with the Murkblood information and the Hand of the Overseer."} end
if not DB[11083] then DB[11083]={id=11083,zoneId=3520,name="Crazed and Confused",level=70,minLevel=70,giver="Ronag the Slave Driver",giverType="NPC",giverId=23166,ender="Ronag the Slave Driver",enderType="NPC",enderId=23166,poiX=-5161,poiY=288,wowhead="https://www.wowhead.com/wotlk/quest=11083",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Don't worry about this dragon, $N. We've got plans for it...$B$BDeeper in this mine is a band of crazed Murkblood. After the dragon broke out, they were cut off from the exit. Somehow, after a mere 2 days of isolation, they've lost all sense of decency.$B$BThey've resorted to cannibalism and the promotion of mayhem. We don't need that kind of madness in this place. Find 'em and kill 'em. All of 'em.",logDesc="Ronag the Slave Driver in the Netherwing Mines of Shadowmoon Valley wants you to slay the Crazed Murkblood Foreman and 5 Crazed Murkblood Miners."} end
if not DB[11084] then DB[11084]={id=11084,zoneId=3520,name="Stand Tall, Captain!",level=70,minLevel=70,giver="Taskmaster Varkule Dragonbreath",giverType="NPC",giverId=23140,ender="Overlord Mor'ghor",enderType="NPC",enderId=23139,poiX=-5114,poiY=588,wowhead="https://www.wowhead.com/wotlk/quest=11084",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Well, well, well... still alive I see. That's good, because Mor'ghor has requested your presence in his tower at once. Get a move on!",logDesc="Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.",rewards={{id=32695,qty=1}}} end
if not DB[11085] then DB[11085]={id=11085,zoneId=3679,name="Escape from Skettis",level=70,minLevel=70,giver="Skyguard Prisoner",giverType="NPC",giverId=23383,ender="Sky Sergeant Doryn",enderType="NPC",enderId=23048,poiX=-3665,poiY=3390,wowhead="https://www.wowhead.com/wotlk/quest=11085",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="Hail, $N.  I thank you for coming to my aid.$B$BThe arakkoa's monstrous birds knocked me from my nether ray while on a scouting mission.$B$BLet's get out of here, while we can.",logDesc="Escort the Skyguard Prisoner to safety and report to Sky Sergeant Doryn."} end
if not DB[11086] then DB[11086]={id=11086,zoneId=3520,name="Disrupting the Twilight Portal",level=70,minLevel=70,giver="Overlord Mor'ghor",giverType="NPC",giverId=23139,ender="Overlord Mor'ghor",enderType="NPC",enderId=23139,poiX=-5085,poiY=579,wowhead="https://www.wowhead.com/wotlk/quest=11086",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="One of your responsibilities as a captain of Dragonmaw is to snuff out Burning Legion activity in Outland. It is your duty to silence those that defy Lord Illidan!$B$BThe demons foolishly attempt to stabilize the portal found on the Twilight Ridge of western Nagrand. They must pay for their treachery, and you will be the orc that collects on their debt.$B$BTravel to the Twilight Ridge and lay waste to its inhabitants. You will be responsible for making at least one attack per day on their fortifications.",logDesc="Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley wants you to kill 20 Deathshadow Agents."} end
if not DB[11087] then DB[11087]={id=11087,zoneId=1941,name="HYJAL FLAG",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=11087",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.$B$BWith the opening of the Dark Portal,we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal,recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.",logDesc="Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep."} end
if not DB[11088] then DB[11088]={id=11088,zoneId=-264,name="<DEPRECATED>Unravelling Your Training",level=70,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=11088",image="assets/images/quests/placeholder.png",desc="Bring me a lot of Spellfire cloth,and then you can forget everything.",logDesc="Bring Jonathan LeCraft 10 pieces of Spellfire cloth."} end
if not DB[11089] then DB[11089]={id=11089,zoneId=3520,name="The Soul Cannon of Reth'hedron",level=70,minLevel=70,giver="Illidari Lord Balthas",giverType="NPC",giverId=23427,ender="Illidari Lord Balthas",enderType="NPC",enderId=23427,rewardNextId=11090,poiX=-5092,poiY=582,wowhead="https://www.wowhead.com/wotlk/quest=11089",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Reth'hedron now lords over the Twilight Ridge of Nagrand. An eredar of such power being loosed upon this world does not bode well for the Illidari. Alas, we do not have the resources required to slay Reth'hedron. Not with the war the Sha'tar have brought to the Black Temple. No... I have a better plan.$B$BYou will subdue Reth'hedron, banishing him back through the Twilight Portal. For this a soul cannon must be fashioned.$B$BReturn to me with the materials on this list.",logDesc="Illidari Lord Balthas at the Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 2 Felsteel Bars, 1 Adamantite Frame, 1 Khorium Power Core and 1 Flawless Arcane Essence."} end
if not DB[11090] then DB[11090]={id=11090,zoneId=3520,name="Subdue the Subduer",level=70,minLevel=70,giver="Illidari Lord Balthas",giverType="NPC",giverId=23427,ender="Illidari Lord Balthas",enderType="NPC",enderId=23427,poiX=-5092,poiY=582,wowhead="https://www.wowhead.com/wotlk/quest=11090",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="<Balthas holds up an alien looking device.>$B$BThis is a soul cannon. Its effects are devastating when attuned. This one is attuned to my blood. The same blood flowing through the veins of Reth'hedron - my brother. Aye, his misplaced allegiance will be the end of him.$B$BTake the cannon and fly to the Twilight Ridge in western Nagrand. Locate Reth'hedron and fire! You must stay on your mount and within range for the effects to take hold. Stand your ground against him and he will have no choice but to flee!",logDesc="Illidari Lord Balthas at Dragonmaw Base Camp in Shadowmoon Valley has tasked you with using the Soul Cannon on Reth'hedron the Subduer in Nagrand.$B$BYou must also return the Soul Cannon.",choiceRewards={{id=32871,qty=1},{id=32869,qty=1},{id=32872,qty=1},{id=32870,qty=1}}} end
if not DB[11091] then DB[11091]={id=11091,zoneId=3522,name="A Special Thank You",level=70,minLevel=70,giver="Chu'a'lor",giverType="NPC",giverId=23233,ender="Jho'nass",enderType="NPC",enderId=23428,poiX=2335,poiY=7285,wowhead="https://www.wowhead.com/wotlk/quest=11091",image="assets/images/quests/placeholder.png",xpDiff=1,money=4400,desc="You honor us with your efforts on our behalf.  And now there is someone that we would like for you to meet.$B$BJho'nass is our most trusted quartermaster.  He maintains a stock of goods that we provide for sale to only the most dedicated of friends to Ogri'la.$B$BYou are one such friend, $N.$B$BWhen you find the time, go and speak with him.  As we understand it, he has prepared a little something for you as a token of our appreciation.",logDesc="Speak with Jho'nass at Ogri'la in the Blade's Edge Mountains.",rewards={{id=32835,qty=1}}} end
if not DB[11092] then DB[11092]={id=11092,zoneId=3520,name="Hail, Commander!",level=70,minLevel=70,giver="Taskmaster Varkule Dragonbreath",giverType="NPC",giverId=23140,ender="Overlord Mor'ghor",enderType="NPC",enderId=23139,poiX=-5114,poiY=588,wowhead="https://www.wowhead.com/wotlk/quest=11092",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Captain $N!$B$B<Taskmaster Varkule salutes you.>$B$BOverlord Mor'ghor has asked to see you in his chambers at once!",logDesc="Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.",rewards={{id=32864,qty=1}}} end
if not DB[11093] then DB[11093]={id=11093,zoneId=3679,name="Hungry Nether Rays",level=70,minLevel=70,giver="Skyguard Handler Deesak",giverType="NPC",giverId=23415,ender="Skyguard Handler Deesak",enderType="NPC",enderId=23415,poiX=-3369,poiY=3655,wowhead="https://www.wowhead.com/wotlk/quest=11093",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Nether rays are surprisingly loyal and obedient once properly trained.  Unfortunately the war on Skettis is taking a toll on them.$B$BWe have dozens of sorties a day - the poor fellows rarely get a break.  And with recent shortages on feed, if those blasted birdmen don't kill them on a mission then starvation will.$B$BIf you can lend a hand, take one of our rays to the woods in the south.  They don't mind warp chaser meat as long as it's a fresh kill.",logDesc="Use the Nether Ray Cage in the woods south of Blackwind Landing and slay Blackwind Warp Chasers near the Hungry Nether Ray.  Return to Skyguard Handler Deesak when you've completed your task.",choiceRewards={{id=22831,qty=2},{id=28103,qty=2}}} end
if not DB[11094] then DB[11094]={id=11094,zoneId=3520,name="Kill Them All!",level=70,minLevel=70,giver="Overlord Mor'ghor",giverType="NPC",giverId=23139,ender="Arcanist Thelis",enderType="NPC",enderId=21955,rewardNextId=11095,poiX=-5085,poiY=579,wowhead="https://www.wowhead.com/wotlk/quest=11094",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Commander $N, stand at attention! You are to take a battalion of Skybreakers and sack the Scryers' outpost located at the foot of the Netherwing Fields. With the Sanctum of the Stars destroyed, our lines of communication to our posts at Eclipse Point and Illidari Point will once more be open.$B$BGo now! Use this flare gun to signal the Skybreakers for the attack!",logDesc="Deliver news of your mission along with the Dragonmaw Flare Gun to Arcanist Thelis at the Sanctum of the Stars in Shadowmoon Valley."} end
if not DB[11095] then DB[11095]={id=11095,zoneId=3520,name="Commander Hobb",level=70,minLevel=70,giver="Arcanist Thelis",giverType="NPC",giverId=21955,ender="Commander Hobb",enderType="NPC",enderId=23434,poiX=-4133,poiY=1131,wowhead="https://www.wowhead.com/wotlk/quest=11095",image="assets/images/quests/placeholder.png",desc="The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.$B$BI want you to let them come, $N.$B$B<Thelis nods.>$B$BYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Hobb. He is standing guard right outside this building.",logDesc="Give the Dragonmaw Flare to Commander Hobb at the Sanctum of the Stars in Shadowmoon Valley."} end
if not DB[11096] then DB[11096]={id=11096,zoneId=3703,name="Threat from Above",level=70,minLevel=70,giver="Yuula",giverType="NPC",giverId=23449,ender="Yuula",enderType="NPC",enderId=23449,rewardNextId=11098,poiX=-1843,poiY=5295,wowhead="https://www.wowhead.com/wotlk/quest=11096",image="assets/images/quests/placeholder.png",xpDiff=5,desc="So you want to join the Skyguard?  Well, I know you can fly... but can you fight?$B$BThe Skyguard is sworn to protect Shattrath from the dangers that loom above us, both near and far.  The Gordunni ogres who dwell in the Barrier Hills to the north are an immediate threat to us.$B$BReaching the ogres has been problematic for Shattrath's ground units.  That's where we come in.  See what you can do to help contain them.",logDesc="Slay any 20 Gordunni Ogres in the Barrier Hills and return to Yuula in Shattrath City."} end
if not DB[11097] then DB[11097]={id=11097,zoneId=3520,name="The Deadliest Trap Ever Laid",level=70,minLevel=70,giver="Commander Hobb",giverType="NPC",giverId=23434,ender="Overlord Mor'ghor",enderType="NPC",enderId=23139,poiX=-4098,poiY=1118,wowhead="https://www.wowhead.com/wotlk/quest=11097",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="Take these Scryer medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Scryer soldiers.$B$BNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.",logDesc="Assist Commander Hobb and the Scryers in defending the Sanctum of the Stars. Once all of the Dragonmaw forces have been defeated, return to Overlord Mor'ghor at Dragonmaw Base Camp with the Scryer Medals.$B"} end
if not DB[11098] then DB[11098]={id=11098,zoneId=3679,name="To Skettis!",level=70,minLevel=70,giver="Yuula",giverType="NPC",giverId=23449,ender="Sky Sergeant Doryn",enderType="NPC",enderId=23048,poiX=-1843,poiY=5295,wowhead="https://www.wowhead.com/wotlk/quest=11098",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Barrier Hills are only one of the fronts where we've been deployed.  A less immediate but far more dangerous threat looms from beyond the Skethyl Mountains, from within the arakkoa city of Skettis.$B$BA few months ago our scouts detected a huge increase in arakkoa activity there.  Several attacks against Shattrath followed.  We've stationed forces outside of their city since.$B$BTake these explosives to Sergeant Doryn at Blackwind Landing, just outside Skettis.  Tell him you're a new recruit.",logDesc="Take the Explosives Package to Sky Sergeant Doryn at Blackwind Landing outside Skettis."} end
if not DB[11099] then DB[11099]={id=11099,zoneId=3520,name="Kill Them All!",level=70,minLevel=70,giver="Overlord Mor'ghor",giverType="NPC",giverId=23139,ender="Anchorite Ceyla",enderType="NPC",enderId=21402,rewardNextId=11100,poiX=-5085,poiY=579,wowhead="https://www.wowhead.com/wotlk/quest=11099",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Commander $N, stand at attention! You are to take a battalion of Skybreakers and sack the Aldor outpost located northwest of our beloved Black Temple. With the Altar of Sha'tar destroyed, our lines of communication to our posts at Coilskar will once more be open.$B$BGo now! Use this flare gun to signal the Skybreakers for the attack!",logDesc="Deliver news of your mission and the Dragonmaw Flare Gun to Anchorite Ceyla at the Altar of Sha'tar."} end
if not DB[11100] then DB[11100]={id=11100,zoneId=3520,name="Commander Arcus",level=70,minLevel=70,giver="Anchorite Ceyla",giverType="NPC",giverId=21402,ender="Commander Arcus",enderType="NPC",enderId=23452,poiX=-2988,poiY=783,wowhead="https://www.wowhead.com/wotlk/quest=11100",image="assets/images/quests/placeholder.png",desc="The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.$B$BI want you to let them come, $N.$B$B<Ceyla nods.>$B$BYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus. He is standing guard right outside this building.$B",logDesc="Give the Dragonmaw Flare to Commander Arcus at the Altar of Sha'tar in Shadowmoon Valley."} end
if not DB[11101] then DB[11101]={id=11101,zoneId=3520,name="The Deadliest Trap Ever Laid",level=70,minLevel=70,giver="Commander Arcus",giverType="NPC",giverId=23452,ender="Overlord Mor'ghor",enderType="NPC",enderId=23139,poiX=-3023,poiY=794,wowhead="https://www.wowhead.com/wotlk/quest=11101",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="Take these Aldor medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Aldor soldiers.$B$BNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.",logDesc="Assist Commander Arcus and the Aldor in defending the Altar of Sha'tar. Once all of the Dragonmaw forces have been defeated, return to Overlord Mor'ghor at Dragonmaw Base Camp with the Aldor Medals."} end
if not DB[11102] then DB[11102]={id=11102,zoneId=3522,name="Bombing Run",level=70,minLevel=70,giver="Sky Sergeant Vanderlip",giverType="NPC",giverId=23120,ender="Sky Sergeant Vanderlip",enderType="NPC",enderId=23120,rewardNextId=11023,poiX=2494,poiY=7350,wowhead="https://www.wowhead.com/wotlk/quest=11102",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="You can fly around as a crow... so what!  Ever annihilate something on the ground while you were flying?  Want to?$B$BForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.$B$BWant to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!",logDesc="Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks."} end
