if not DB[11107] then DB[11107]={id=11107,zoneId=3520,name="Bow to the Highlord",level=70,minLevel=70,giver="Taskmaster Varkule Dragonbreath",giverType="NPC",giverId=23140,ender="Overlord Mor'ghor",enderType="NPC",enderId=23139,rewardNextId=11108,poiX=-5114,poiY=588,wowhead="https://www.wowhead.com/wotlk/quest=11107",image="assets/images/quests/placeholder.png",desc="I am unworthy to even carry a message directed at you, sir. Please forgive me for this indulgence. Overlord Mor'ghor has requested your presence in his chambers at once!",logDesc="Speak to Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.$B"} end
if not DB[11108] then DB[11108]={id=11108,zoneId=3520,name="Lord Illidan Stormrage",level=70,minLevel=70,giver="Overlord Mor'ghor",giverType="NPC",giverId=23139,ender="Barthamus",enderType="NPC",enderId=23433,poiX=-5085,poiY=579,wowhead="https://www.wowhead.com/wotlk/quest=11108",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Come, highlord $N. Illidan himself awaits us!",logDesc="Meet Illidan Stormrage. Seek out Barthamus in the Lower City of Shattrath should you survive."} end
