if not DB[11402] then DB[11402]={id=11402,zoneId=151,name="Clayton's Quest: Extreme!",level=68,minLevel=61,wowhead="https://www.wowhead.com/wotlk/quest=11402",image="assets/images/quests/placeholder.png",xpDiff=2,money=10000,desc="Clayton wants you to find and slay twenty Evil Squirrels. ",logDesc="Seriously, go slay those Evil Squirrels!"} end
if not DB[11403] then DB[11403]={id=11403,zoneId=-22,name="Free at Last!",level=-1,minLevel=60,giver="Sir Thomas",giverType="NPC",giverId=23904,ender="Masked Orphan Matron",enderType="NPC",enderId=23973,wowhead="https://www.wowhead.com/wotlk/quest=11403",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Rage was my prison, $N, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.$B$BThank you for leading me back to the Light.  May I never again lose my way.$B$BTake this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.",logDesc="Take the Tome of Thomas Thomson to a Masked Orphan Matron in Durotar, Brill or Falconwing Square.",rewards={{id=20557,qty=5}}} end
if not DB[11404] then DB[11404]={id=11404,zoneId=-22,name="Call the Headless Horseman",level=-1,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=11404",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Many dreary candles adorn this pumpkin shrine, which grins, taunting...",logDesc="Take a Dreary Candle to the Loosely Turned Soil."} end
if not DB[11405] then DB[11405]={id=11405,zoneId=-22,name="Call the Headless Horseman",level=-1,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=11405",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Many dreary candles adorn this pumpkin shrine, which grins, taunting...",logDesc="Take a Dreary Candle to the Loosely Turned Soil."} end
if not DB[11406] then DB[11406]={id=11406,zoneId=495,name="Everything Must Be Ready",level=70,minLevel=68,giver="Quartermaster Brevin",giverType="NPC",giverId=24494,ender="Gil Grisert",enderType="NPC",enderId=24139,poiX=1392,poiY=-3250,wowhead="https://www.wowhead.com/wotlk/quest=11406",image="assets/images/quests/placeholder.png",xpDiff=1,money=4400,desc="When the expeditionary force moves north, Captain Adams expects everything to be ready at Fort Wildervar. The scouts and craftsmen there have been tasked with preparing the gear and rations for our men for the climb into the hills.$B$BThe captain's famous for his temper, so I want to send someone ahead to check on the preparations. Fort Wildervar is far to the northeast, beyond Skorn, up in the snow-covered areas near the border with Grizzly Hills. Find Gil Grisert there and make sure he is prepared.",logDesc="Speak with Gil Grisert at Fort Wildervar."} end
if not DB[11407] then DB[11407]={id=11407,zoneId=-370,name="Bark for Drohn's Distillery!",level=-1,minLevel=1,giver="Cort Gorestein",giverType="NPC",giverId=24498,ender="Cort Gorestein",enderType="NPC",enderId=24498,poiX=1177,poiY=-4309,wowhead="https://www.wowhead.com/wotlk/quest=11407",image="assets/images/quests/placeholder.png",desc="So, do you want to help bring strength and honor to Brewfest?  We need you to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.$b$bWe'll lend you a racing ram for 4 minutes and also give you these racing reins.$b$bBe careful though, the cheap goblins didn't put any apple crates along the way.",logDesc="Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.",rewards={{id=37829,qty=15}}} end
if not DB[11408] then DB[11408]={id=11408,zoneId=-370,name="Bark for T'chali's Voodoo Brewery!",level=-1,minLevel=1,giver="Ja'ron",giverType="NPC",giverId=24499,ender="Ja'ron",enderType="NPC",enderId=24499,poiX=1189,poiY=-4268,wowhead="https://www.wowhead.com/wotlk/quest=11408",image="assets/images/quests/placeholder.png",desc="We need to spread the word about the trolls at Brewfest.  Ya need to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.$b$bBut I'll make it easy for ya, I'll lend you a racing ram for 4 minutes.  I'll also give you these racing reins.$b$bBe careful though, the goblins didn't put any apple crates along the way.  They are cheap like that.",logDesc="Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.",rewards={{id=37829,qty=15}}} end
if not DB[11409] then DB[11409]={id=11409,zoneId=-370,name="Now This is Ram Racing... Almost.",level=-1,minLevel=1,giver="3",giverType="NPC",giverId=24497,ender="3",enderType="NPC",enderId=24497,poiX=1280,poiY=-4411,wowhead="https://www.wowhead.com/wotlk/quest=11409",image="assets/images/quests/placeholder.png",desc="So you want to check out the racing rams?  The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?$b$bNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.$b$bSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.$b$bKeep the ram at a trot, canter and gallop for 8 seconds each.",logDesc="You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds."} end
if not DB[11410] then DB[11410]={id=11410,zoneId=495,name="The One That Got Away",level=71,minLevel=68,giver="Christopher Sloan",giverType="NPC",giverId=24056,ender="Christopher Sloan",enderType="NPC",enderId=24056,poiX=2363,poiY=-5042,wowhead="https://www.wowhead.com/wotlk/quest=11410",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="The barbfish you brought should work well as bait for most fish, but I fear it'll attract a monster!$B$BWhen I first arrived, I put some of Nat Pagle's favorite bait on my hook and cast it into the water. A huge monster latched on, with giant teeth and icicles hanging from its fins!$B$BWould've pulled me into those icy waters if I hadn't cut the line! I can't use the new bait until ol' Frostfin's been dealt with. Use this bait near the sunken boat in the middle of the lake. He won't be able to resist!",logDesc="Christopher Sloan at Fort Wildervar wants you to defeat Frostfin."} end
if not DB[11411] then DB[11411]={id=11411,zoneId=495,name="Camp Winterhoof",level=70,minLevel=68,giver="Cormath the Courier",giverType="NPC",giverId=24125,ender="Chieftain Ashtotem",enderType="NPC",enderId=24129,poiX=456,poiY=-4604,wowhead="https://www.wowhead.com/wotlk/quest=11411",image="assets/images/quests/placeholder.png",xpDiff=1,desc="In my travels as a courier, I've seen a number of strange denizens of the Howling Fjord, but one group stands out. From a distance, they look like tauren, but upon closer inspection, they're quite different -- sturdier and shaggier.$B$BI found one of their settlements far to the north, beyond Halgrind, Skorn, and the northern forests. Camp Winterhoof, it's called, and it sits in the foothills of Gjalerhorn near the border with Grizzly Hills. Make contact with them, and see if they might be of use to us.",logDesc="Speak to Chieftain Ashtotem at Camp Winterhoof."} end
if not DB[11412] then DB[11412]={id=11412,zoneId=-370,name="There and Back Again",level=-1,minLevel=1,giver="3",giverType="NPC",giverId=24497,ender="3",enderType="NPC",enderId=24497,poiX=1280,poiY=-4411,wowhead="https://www.wowhead.com/wotlk/quest=11412",image="assets/images/quests/placeholder.png",desc="Am I glad you're here.  We are in big trouble!  The goblin that was supposed to be bringing us more brew had an accident on his way from Razor Hill.  You gotta get us that brew!$b$bI'll put you on one of my racing rams and you follow the road to Razor Hill.$b$bOnce you get near him he'll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant.  For now, all we want are 3 kegs.  Do a good job and maybe we'll have another job for you.",logDesc="Get a keg from the Goblin stranded on the road to Razor Hill and return it to Ram Master Ray's assistant.  Do this 3 times before your ram goes away.",rewards={{id=37829,qty=10}}} end
if not DB[11413] then DB[11413]={id=11413,zoneId=-370,name="Did Someone Say \"Souvenir?\"",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=11413",image="assets/images/quests/placeholder.png",desc="Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.$b$bTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.",logDesc="Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.",rewards={{id=32912,qty=1}}} end
if not DB[11414] then DB[11414]={id=11414,zoneId=495,name="Brother Betrayers",level=71,minLevel=69,giver="Ulfang",giverType="NPC",giverId=24261,ender="Ulfang",enderType="NPC",enderId=24261,rewardNextId=11416,poiX=2888,poiY=-3193,wowhead="https://www.wowhead.com/wotlk/quest=11414",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Watcher Moonleaf is from my dreams! If you are her friend, you are mine.$B$BI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha worg. There is something unnatural about him.$B$BTo help, you must first kill those who betrayed me.$B$BBjomolf hunts to the northwest of a place called Steel Gate. And look for Varg to the southeast, near the West Spear Tower.$B$BThey will not be fooled by your form.",logDesc="Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.$B$BIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement."} end
if not DB[11415] then DB[11415]={id=11415,zoneId=495,name="Brother Betrayers",level=71,minLevel=69,giver="Ulfang",giverType="NPC",giverId=24261,ender="Ulfang",enderType="NPC",enderId=24261,rewardNextId=11417,poiX=2888,poiY=-3193,wowhead="https://www.wowhead.com/wotlk/quest=11415",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Mistwalker is from my dreams! If you are his friend, you are mine.$B$BI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha. There is something unnatural about him.$B$BTo help, you must first kill those who betrayed me.$B$BBjomolf hunts to the northwest of a place the two-legs call Steel Gate. And look for Varg to the southeast, near the West Spear Tower.$B$BThey will not be fooled by your form.",logDesc="Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.$B$BIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement."} end
if not DB[11416] then DB[11416]={id=11416,zoneId=495,name="Eyes of the Eagle",level=71,minLevel=69,giver="Ulfang",giverType="NPC",giverId=24261,ender="Ulfang",enderType="NPC",enderId=24261,rewardNextId=11326,poiX=2888,poiY=-3193,wowhead="https://www.wowhead.com/wotlk/quest=11416",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.$B$BMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.$B$BTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.$B$BGet her eyes.",logDesc="Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.$B$BIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement."} end
if not DB[11417] then DB[11417]={id=11417,zoneId=495,name="Eyes of the Eagle",level=71,minLevel=69,giver="Ulfang",giverType="NPC",giverId=24261,ender="Ulfang",enderType="NPC",enderId=24261,rewardNextId=11324,poiX=2888,poiY=-3193,wowhead="https://www.wowhead.com/wotlk/quest=11417",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.$B$BMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.$B$BTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.$B$BGet her eyes.",logDesc="Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.$B$BIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement."} end
if not DB[11418] then DB[11418]={id=11418,zoneId=495,name="We Call Him Steelfeather",level=70,minLevel=68,giver="Gil Grisert",giverType="NPC",giverId=24139,ender="Gil Grisert",enderType="NPC",enderId=24139,poiX=2439,poiY=-5182,wowhead="https://www.wowhead.com/wotlk/quest=11418",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="We see one brave hippogryph circling over the fort, then swooping down and taking prey. Jethan over there has taken a couple of shots at the creature, but his arrows bounced right off!$B$BWe've taken to calling this remarkable creature Steelfeather, but we can't see why he prefers the area around Fort Wildervar. Most hippogryphs are wary of people.$B$BResearcher Aderan has helped us fashion a charm from one of the creature's feathers. He claims it will allow the user to see through Steelfeather's eyes.",logDesc="Locate Steelfeather circling Fort Wildervar and use the Feathered Charm to discover his secret. Report your findings to Gil Grisert."} end
if not DB[11419] then DB[11419]={id=11419,zoneId=-370,name="Brewfest Riding Rams",level=-1,minLevel=40,ender="3",enderType="NPC",enderId=24510,wowhead="https://www.wowhead.com/wotlk/quest=11419",image="assets/images/quests/placeholder.png",desc="If you show this hand stamp to Driz Tumblequick, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.",logDesc="Bring the \"Honorary Brewer\" Hand Stamp to Driz Tumblequick near the entrance to the Brewfest Grounds in Durotar."} end
if not DB[11420] then DB[11420]={id=11420,zoneId=495,name="The Path to Payback",level=71,minLevel=68,giver="Guard Captain Zorek",giverType="NPC",giverId=23728,ender="Guard Captain Zorek",enderType="NPC",enderId=23728,rewardNextId=11426,poiX=600,poiY=-5032,wowhead="https://www.wowhead.com/wotlk/quest=11420",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Two weeks ago our chief engineer got his hands on a vrykul harpoon gun - the same type of gun that the vrykul use to take down our ships. By studying that gun he managed to put together a comprehensive operation manual.$B$BUnfortunately he was abducted and taken north of here to Wyrmskull Village. We eventually did find him, but near death and without the manual. His dying words indicated that the manual was lost in the Utgarde Catacombs, located at the northwest end of Wyrmskull. Get me that manual!",logDesc="Guard Captain Zorek at Valgarde in Howling Fjord wants you to recover the Harpoon Operation Manual."} end
if not DB[11421] then DB[11421]={id=11421,zoneId=495,name="It Goes to 11...",level=71,minLevel=68,giver="Lieutenant Icehammer",giverType="NPC",giverId=24634,ender="Lieutenant Icehammer",enderType="NPC",enderId=24634,rewardNextId=11436,poiX=1224,poiY=-5293,wowhead="https://www.wowhead.com/wotlk/quest=11421",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="We must strike while the vrykul forces are in disarray! Take the harpoon control mechanism to Nifflevar and locate the northernmost harpoon building on the bluff side of the village.$B$BOnce there, commandeer one of the vrykul harpoon guns that are stationed on the building's deck. Use the harpoon gun to rain hell upon Wyrmskull Village! Destroy the longhouse, dockhouse, storage facility and any defenders that the vrykul may send at you!$B$BDo this and Daggercap Bay will become a much safer port!",logDesc="Lieutenant Icehammer in the Howling Fjord wants you to destroy the Dragonflayer Longhouse, Dragonflayer Dockhouse, Dragonflayer Storage Facility and 8 Dragonflayer Defenders.$B$BReturn the Harpoon Control Mechanism to him once the task is complete.",choiceRewards={{id=35841,qty=1},{id=35842,qty=1},{id=35843,qty=1},{id=35839,qty=1}}} end
if not DB[11422] then DB[11422]={id=11422,zoneId=495,name="Trident of the Son",level=71,minLevel=69,giver="Old Icefin",giverType="NPC",giverId=24544,ender="Old Icefin",enderType="NPC",enderId=24544,poiX=2221,poiY=-2594,wowhead="https://www.wowhead.com/wotlk/quest=11422",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="<From the scratches he makes in the rock, you see several symbols: a trident, a mur'ghoul, the sun, a wrecked ship, and a rough stick-figure of yourself.>$B$B<Puzzling out what the murloc is conveying takes a while. Obviously he wants you to get a trident from the Chillmere Coast, but the image of the sun is puzzling. That is until you realize he means his son.>$B$B<His son was changed into a mur'ghoul! He wants you to find him to the south near the wrecked ship and return with his trident.>",logDesc="Old Icefin wants you to obtain Rotgill's Trident. Return it to him on the small island on the Chillmere Coast."} end
if not DB[11423] then DB[11423]={id=11423,zoneId=495,name="The Enemy's Legacy",level=71,minLevel=70,giver="Scribe Seguine",giverType="NPC",giverId=24548,ender="Scribe Seguine",enderType="NPC",enderId=24548,poiX=685,poiY=-5470,wowhead="https://www.wowhead.com/wotlk/quest=11423",image="assets/images/quests/placeholder.png",xpDiff=5,desc="As our armies march through Northrend, our enemies will not suffer mere defeat.  Their houses will burn, their corpses will be devoured by our plagues, all trace of their existence will be lost.$B$BThis worries me as a seeker of knowledge.  The eastern town of Nifflevar will soon be razed by our forces in Vengeance Landing.  The vrykul bard, Helgus, lived there and wrote three sagas: the Saga of the Twins, the Saga of the Winter Curse and the Saga of the Val'kyr.  Obtain them before Nifflevar is destroyed.",logDesc="Go into Nifflevar, north of Ghostblade Post and look for the Saga of the Winter Curse, the Saga of the Val'kyr and the Saga of the Twins."} end
if not DB[11424] then DB[11424]={id=11424,zoneId=495,name="Shield Hill",level=71,minLevel=68,giver="\"Hacksaw\" Jenny",giverType="NPC",giverId=24252,ender="\"Hacksaw\" Jenny",enderType="NPC",enderId=24252,poiX=488,poiY=-4644,wowhead="https://www.wowhead.com/wotlk/quest=11424",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="My work should be extremely easy in a time of war.  There ought to be usable body parts everywhere.$B$BIt's not that simple, though.  With these eggheads making all sorts of killer plagues and sending them to enemy towns, most of the material gets contaminated.$B$BThere is a place, though, where usable samples exist.  Shield Hill, south of here, is an ancient vrykul burial ground where the dead walk but are not afflicted with any plague - ours or the Lich King's.  Get me some bones, I'll pay ya well.",logDesc="\"Hacksaw\" Jenny wants you to bring her 5 Ancient Vrykul Bones from the reanimated Vrykul in Shield Hill, south of New Agamand.",choiceRewards={{id=35893,qty=1},{id=35892,qty=1},{id=35894,qty=1},{id=35895,qty=1}}} end
if not DB[11425] then DB[11425]={id=11425,zoneId=151,name="Test Quest - Craig",level=1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=11425",image="assets/images/quests/placeholder.png",money=50,desc="Go on a quest!",logDesc="Vermin, gotta hate 'em."} end
if not DB[11426] then DB[11426]={id=11426,zoneId=495,name="Locating the Mechanism",level=71,minLevel=68,giver="Guard Captain Zorek",giverType="NPC",giverId=23728,ender="Guard Captain Zorek",enderType="NPC",enderId=23728,rewardNextId=11427,poiX=600,poiY=-5032,wowhead="https://www.wowhead.com/wotlk/quest=11426",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Don't worry, $N; this is all going to lead to something big! HUGE! You're just going to have to trust me for now and do as I ask of you.$B$BWe need to get the mechanism mentioned in the manual for the next step of the plan. I have a strong suspicion that you'll find one on one of those vrykul that operate the harpoon guns in Wyrmskull Village. You'll find them on the east side of the village, on the docks by the longhouses.",logDesc="Guard Captain Zorek at Valgarde in Howling Fjord wants you to bring him a Harpoon Control Mechanism."} end
if not DB[11427] then DB[11427]={id=11427,zoneId=495,name="Meet Lieutenant Icehammer...",level=71,minLevel=68,giver="Guard Captain Zorek",giverType="NPC",giverId=23728,ender="Lieutenant Icehammer",enderType="NPC",enderId=24634,rewardNextId=11429,poiX=600,poiY=-5032,wowhead="https://www.wowhead.com/wotlk/quest=11427",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Do you see those vrykul buildings on the bluffs to the northeast? The vrykul call that place Nifflevar. It's where most of their harpoon attacks on our frigates originate.$B$BWell guess what? The time for payback has come, $N. I need you to take this harpoon control mechanism and meet up with Lieutenant Icehammer, who is hiding out in a vrykul building northwest of Nifflevar.$B$BWhen you're ready I'll place you on the back of one of our gryphons and zip you right to him! $B",logDesc="Guard Captain Zorek wants you to take the Harpoon Control Mechanism to Lieutenant Icehammer stationed outside of Nifflevar."} end
if not DB[11428] then DB[11428]={id=11428,zoneId=495,name="Keeper Witherleaf",level=71,minLevel=69,giver="Lurielle",giverType="NPC",giverId=24117,ender="Lurielle",enderType="NPC",enderId=24117,poiX=2195,poiY=-5115,wowhead="https://www.wowhead.com/wotlk/quest=11428",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="You have been a great friend and ally to us, $N. There is one more thing I must ask of you.$B$BYou have seen the corruption of the Twisted Glade and the beasts that dwell there. The blacksouled keepers will continue raising these abominations from the waters and soil of our glade unless we act against them.$B$BThe most powerful of the blacksouled keepers is known as Keeper Witherleaf. Slay him, $N, and open the way for the redemption of the glade as you once redeemed my sisters.",logDesc="Lurielle at the Frozen Glade wants you to kill Keeper Witherleaf."} end
if not DB[11429] then DB[11429]={id=11429,zoneId=495,name="Drop It then Rock It!",level=71,minLevel=68,giver="Lieutenant Icehammer",giverType="NPC",giverId=24634,ender="Lieutenant Icehammer",enderType="NPC",enderId=24634,rewardNextId=11430,poiX=1224,poiY=-5293,wowhead="https://www.wowhead.com/wotlk/quest=11429",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I'm not about to put the fate of this mission into the hands of some untested scrub.$B$BNow, if you want to prove to me that you've got what it takes to carry out this mission, you'll need to do what I tell you.$B$BTake this battle standard and head over to Baleheim, directly north of here. Once you're at Baleheim, find the center of town and drop our flag. Fight off any vrykul dirt bags that attempt to take down our beloved flag and return to me once you've established Alliance dominance!",logDesc="Lieutenant Icehammer in the Howling Fjord wants you to place the Alliance Banner in Baleheim and then defend the banner against attackers.$B$BReturn to Lieutenant Icehammer with the Alliance Banner should you survive."} end
if not DB[11430] then DB[11430]={id=11430,zoneId=495,name="Harpoon Master Yavus",level=71,minLevel=68,giver="Lieutenant Icehammer",giverType="NPC",giverId=24634,ender="Lieutenant Icehammer",enderType="NPC",enderId=24634,rewardNextId=11421,poiX=1224,poiY=-5293,wowhead="https://www.wowhead.com/wotlk/quest=11430",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="That was a fairly strong showing at Baleheim, $N. Before you go off patting yourself on the back there's work to be done at Nifflevar.$B$BWe've located the vrykul responsible for the majority of the harpoon attacks on our frigates - goes by the name of Yavus. You'll find him in the main harpoon structure on the bluffs of Nifflevar, southeast of here.$B$BTrack him down and execute him for crimes against the Alliance!$B$BDo me proud, $N!$B",logDesc="Lieutenant Icehammer in the Howling Fjord wants you to slay Harpoon Master Yavus at Nifflevar."} end
if not DB[11431] then DB[11431]={id=11431,zoneId=-370,name="Catch the Wild Wolpertinger!",level=-1,minLevel=1,giver="Glodrak Huntsniper",giverType="NPC",giverId=24657,ender="Glodrak Huntsniper",enderType="NPC",enderId=24657,poiX=1195,poiY=-4343,wowhead="https://www.wowhead.com/wotlk/quest=11431",image="assets/images/quests/placeholder.png",desc="Hey there! I'm a crazy dwarf! We dwarves believe when you get enough brew together, invisible creatures show up. In fact they are probably wandering around the Brewfest grounds right now! But you can only see them if you are really drunk.$b$bWe dwarves will come up with any excuse to drink.$b$bI bet you want a reason to drink too... So here it is, bring me 5 of those wolpertingers with this net I got from a really drunk dwarf.$b$bIf you can't see them, get some Synthebrew Goggles from me - almost as good!",logDesc="The \"dwarf,\" Glodrak Huntsniper, has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be intoxicated or wearing Synthebrew Goggles to see them.",rewards={{id=32233,qty=1}}} end
if not DB[11432] then DB[11432]={id=11432,zoneId=495,name="Sleeping Giants",level=71,minLevel=68,giver="Mage-Lieutenant Malister",giverType="NPC",giverId=23888,ender="Mage-Lieutenant Malister",enderType="NPC",enderId=23888,poiX=1335,poiY=-3148,wowhead="https://www.wowhead.com/wotlk/quest=11432",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I've overheard what you've had to say with Father Levariol. Allow me to suggest that he's not having you go far enough.$B$BYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!$B$BI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.$B$BSurely such a disruption will prove fatal to the vrykul.",logDesc="Mage-Lieutenant Malister has tasked you with slaying 5 Dormant Vrykul. Return to him at Westguard Keep when you have done so."} end
if not DB[11433] then DB[11433]={id=11433,zoneId=495,name="Sleeping Giants",level=71,minLevel=68,giver="Ahota Whitefrost",giverType="NPC",giverId=24127,ender="Ahota Whitefrost",enderType="NPC",enderId=24127,poiX=2672,poiY=-4323,wowhead="https://www.wowhead.com/wotlk/quest=11433",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I've overheard what you've had to say with Greatmother Ankha. With all due respect, she's not having you go far enough.$B$BYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!$B$BI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.$B$BSurely such a disruption will prove fatal to the vrykul.",logDesc="Ahota Whitefrost has tasked you with slaying 5 Dormant Vrykul. Return to him at Camp Winterhoof when you have done so."} end
if not DB[11434] then DB[11434]={id=11434,zoneId=495,name="Forgotten Treasure",level=71,minLevel=69,giver="Handsome Terry",giverType="NPC",giverId=24537,ender="Handsome Terry",enderType="NPC",enderId=24537,rewardNextId=11455,poiX=-117,poiY=-3550,wowhead="https://www.wowhead.com/wotlk/quest=11434",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've made my fortune by specializing in treasure that regular pirates don't appreciate: art, antiquities, collector's pieces.$B$BBlack Conrad's fleet sank south of here years ago.  All the gold and jewelry was picked clean by divers, but two ancient relics remain there.  One is a museum-quality Amani vase, the other is an eagle figurine.$B$BGo and retrieve them for me and I'll vouch for you with the other pirates.  I'll even throw in something to make your underwater adventure a bit more manageable.",logDesc="Handsome Terry at Scalawag Point wants you to bring him 1 Amani Vase and 1 Eagle Figurine from the shipwreck to the south."} end
if not DB[11435] then DB[11435]={id=11435,zoneId=-22,name="Gathered Pumpkins NYI",level=70,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=11435",image="assets/images/quests/placeholder.png",desc="Hi,$N!  Thanks for driving away the Horseman!  Now that he's gone,the matron said we can roam the village!$B$BI found some pumpkins that the Horseman dropped.  They look scary... will you take them and show  them to the matron?",logDesc="Take the bunch of jack-o'-lanterns to the Costumed Orphan Matron.",rewards={{id=34068,qty=5}}} end
if not DB[11436] then DB[11436]={id=11436,zoneId=495,name="Let's Go Surfing Now",level=71,minLevel=68,giver="Lieutenant Icehammer",giverType="NPC",giverId=24634,ender="Guard Captain Zorek",enderType="NPC",enderId=23728,poiX=1224,poiY=-5293,wowhead="https://www.wowhead.com/wotlk/quest=11436",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Navigating the steep bluffs of Howling Fjord can be nerve-racking! I've come up with a solution to ease that burden by utilizing vrykul technology and dwarven ingenuity. With just a few adjustments and some fine tuning I've created Icehammer's harpoon controller! Of course it hasn't been tested, but that's what you're here for!$B$BTake the controller to the big gun in Nifflevar and use it to launch yourself into Valgarde. Report your victory to Zorek. Oh yea, you can keep the controller.",logDesc="Use the large Vrykul Harpoon Gun in Nifflevar to launch yourself into Valgarde. Report your victory over the Vrykul to Guard Captain Zorek."} end
if not DB[11437] then DB[11437]={id=11437,zoneId=-370,name="[PH] Beer Garden A",level=70,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=11437",image="assets/images/quests/placeholder.png",desc="[PH] Speak to a Brewfest Barker in any Beer Garden outside of Darnassus,the Exodar,Shattrath City,or Stormwind City and receive a free pretzel.",logDesc="[PH] Speak to a Brewfest Barker in any Beer Garden and receive a free pretzel.",rewards={{id=33043,qty=1}}} end
if not DB[11438] then DB[11438]={id=11438,zoneId=-370,name="[PH] Beer Garden B",level=70,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=11438",image="assets/images/quests/placeholder.png",desc="[PH] Speak to a Brewfest Barker in any Beer Garden outside of Darnassus,the Exodar,Shattrath City,or Stormwind City and receive a free pretzel.",logDesc="[PH] Speak to a Brewfest Barker in any Beer Garden and receive a free pretzel.",rewards={{id=33043,qty=1}}} end
if not DB[11439] then DB[11439]={id=11439,zoneId=-22,name="Fire Brigade Practice",level=-1,minLevel=1,giver="Costumed Orphan Matron",giverType="NPC",giverId=24519,ender="Costumed Orphan Matron",enderType="NPC",enderId=24519,poiX=-9430,poiY=56,wowhead="https://www.wowhead.com/wotlk/quest=11439",image="assets/images/quests/placeholder.png",desc="The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help?$B$BSouth of here, the mountaineers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.$B$BGood bye, $N.  When you're done with fire brigade practice, please visit us again!",logDesc="Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.",rewards={{id=20557,qty=1}}} end
if not DB[11440] then DB[11440]={id=11440,zoneId=-22,name="Fire Brigade Practice",level=-1,minLevel=1,giver="Costumed Orphan Matron",giverType="NPC",giverId=24519,ender="Costumed Orphan Matron",enderType="NPC",enderId=24519,poiX=-9430,poiY=56,wowhead="https://www.wowhead.com/wotlk/quest=11440",image="assets/images/quests/placeholder.png",desc="With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help?$B$BWest of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.$B$BGood bye, $N.  When you're done with fire brigade practice, please visit us again!",logDesc="Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.",rewards={{id=20557,qty=1}}} end
if not DB[11441] then DB[11441]={id=11441,zoneId=-370,name="Brewfest!",level=-1,minLevel=1,ender="Ipfelkofer Ironkeg",enderType="NPC",enderId=24710,wowhead="https://www.wowhead.com/wotlk/quest=11441",image="assets/images/quests/placeholder.png",desc="Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.",logDesc="Speak to the Brewfest Organizer.",choiceRewards={{id=33030,qty=1},{id=33031,qty=1},{id=33034,qty=1}}} end
if not DB[11442] then DB[11442]={id=11442,zoneId=-370,name="Welcome to Brewfest!",level=-1,minLevel=1,giver="Ipfelkofer Ironkeg",giverType="NPC",giverId=24710,ender="Ipfelkofer Ironkeg",enderType="NPC",enderId=24710,poiX=-5185,poiY=-562,wowhead="https://www.wowhead.com/wotlk/quest=11442",image="assets/images/quests/placeholder.png",desc="[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.",logDesc="[PH] Speak to the Brewfest Organizer and receive a free beer.",choiceRewards={{id=33030,qty=1},{id=33031,qty=1},{id=33034,qty=1}}} end
if not DB[11443] then DB[11443]={id=11443,zoneId=495,name="Daggercap Divin'",level=71,minLevel=68,giver="Harold Lagras",giverType="NPC",giverId=23730,ender="Harold Lagras",enderType="NPC",enderId=23730,poiX=733,poiY=-5199,wowhead="https://www.wowhead.com/wotlk/quest=11443",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Hey... Uh... What's up? What are you doing down here?$B$BMe? Oh... Well, you see... I'm... Um... I'm trying to clean this place up! Orders from Keller himself! He says to me, \"Harry, I want you to put on a divin' bell and search the shipwrecks of Daggercap for OUR stuff...\"$B$BSay, maybe you could lend me a hand while you're down here. Throughout the bay here are all kinds of goodies, err, I mean supplies. Go out and bring me back whatever you find. Use this diving helm so you don't run out of air and die.",logDesc="Harold Lagras at the bottom of Daggercap Bay wants you to recover 10 Valgarde Supply Crates."} end
if not DB[11444] then DB[11444]={id=11444,zoneId=-370,name="[PH] Beer Garden A",level=70,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=11444",image="assets/images/quests/placeholder.png",desc="[PH] Speak to a Brewfest Barker in any Beer Garden outside of Darnassus,the Exodar,Shattrath City,or Stormwind City and receive a free pretzel.",logDesc="[PH] Speak to a Brewfest Barker in any Beer Garden and receive a free pretzel.",rewards={{id=33043,qty=1}}} end
