if not DB[11448] then DB[11448]={id=11448,zoneId=495,name="The Explorers' League Outpost",level=71,minLevel=68,giver="Beltrand McSorf",giverType="NPC",giverId=23548,ender="Stanwad",enderType="NPC",enderId=24717,rewardNextId=11474,poiX=656,poiY=-5036,wowhead="https://www.wowhead.com/wotlk/quest=11448",image="assets/images/quests/placeholder.png",xpDiff=1,desc="It's all a bunch of cryptic nonsense! Even with this cipher I can't make heads or tails of these tablets. Admittedly, cryptography is not my strong point.$B$BYou'll need to take the cipher and tablets to our cryptographer, Stanwad. Unfortunately, I haven't heard from Stanwad in two weeks. He took a team of twenty scientists to the dig sites on the southeastern bluffs of the fjord and hasn't been heard from since. The best I can do is have McGoyver over there give you a lift with his flying machine.",logDesc="Deliver McSorf's Bundle to Stanwad at the Explorers' League Outpost in Howling Fjord."} end
if not DB[11449] then DB[11449]={id=11449,zoneId=-22,name="Fire Training",level=-1,minLevel=1,giver="Masked Orphan Matron",giverType="NPC",giverId=23973,ender="Masked Orphan Matron",enderType="NPC",enderId=23973,poiX=9516,poiY=-6815,wowhead="https://www.wowhead.com/wotlk/quest=11449",image="assets/images/quests/placeholder.png",desc="The deathstalkers have set up a fire training area outside the town.  We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter.$B$BHead west past the graveyard, following the road. You'll find the training area there.",logDesc="Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Brill.",rewards={{id=20557,qty=1}}} end
if not DB[11450] then DB[11450]={id=11450,zoneId=-22,name="Fire Training",level=-1,minLevel=1,giver="Masked Orphan Matron",giverType="NPC",giverId=23973,ender="Masked Orphan Matron",enderType="NPC",enderId=23973,poiX=9516,poiY=-6815,wowhead="https://www.wowhead.com/wotlk/quest=11450",image="assets/images/quests/placeholder.png",desc="The guards have set up a fire training area outside the town.  We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter.$B$BHead south through the gate to the crossroads. You'll find the training area there.",logDesc="Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Falconwing Square.",rewards={{id=20557,qty=1}}} end
if not DB[11451] then DB[11451]={id=11451,zoneId=3703,name="Alicia's Poem",level=70,minLevel=60,giver="Alicia",giverType="NPC",giverId=24729,ender="Caylee Dak",enderType="NPC",enderId=24727,poiX=-8409,poiY=490,wowhead="https://www.wowhead.com/wotlk/quest=11451",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Hi, I wrote a poem for my friend Caylee.  She likes to hang out with the Aldor in Shattrath City.  You know, in Outland?$b$bCould you take my poem to her?  My mommy says I'm too young to go to Shattrath City!",logDesc="You have been asked to deliver Alicia's Poem to Caylee Dak in Shattrath City in Outland."} end
if not DB[11452] then DB[11452]={id=11452,zoneId=495,name="The Slumbering King",level=72,minLevel=68,ender="Captain Adams",enderType="NPC",enderId=23749,wowhead="https://www.wowhead.com/wotlk/quest=11452",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.$B$BHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.$B$BIf you hurry, you may be able to stop her before it is too late.",logDesc="Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Westguard Keep and report your success to Captain Adams."} end
if not DB[11453] then DB[11453]={id=11453,zoneId=495,name="The Slumbering King",level=72,minLevel=68,ender="Chieftain Ashtotem",enderType="NPC",enderId=24129,wowhead="https://www.wowhead.com/wotlk/quest=11453",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.$B$BHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.$B$BIf you hurry, you may be able to stop her before it is too late.",logDesc="Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Camp Winterhoof and report your success to Chieftain Ashtotem."} end
if not DB[11454] then DB[11454]={id=11454,zoneId=-370,name="Seek the Saboteurs",level=52,minLevel=48,ender="Coren Direbrew",enderType="NPC",enderId=23872,wowhead="https://www.wowhead.com/wotlk/quest=11454",image="assets/images/quests/placeholder.png",money=6000,desc="This scrap of paper seems to have been left behind accidentally by the Dark Iron invaders.$B$BWhile the plans are complicated and written in some form of coded Dwarvish, the signature at the end - \"Coren Direbrew\" - is clear enough, as is mention of the Grim Guzzler deep within Blackrock Depths. You should seek out the instigator and put an end to these raids.",logDesc="Find Coren Direbrew in the Grim Guzzler within Blackrock Depths.",rewards={{id=11325,qty=5}}} end
if not DB[11455] then DB[11455]={id=11455,zoneId=495,name="The Fragrance of Money",level=71,minLevel=69,giver="Handsome Terry",giverType="NPC",giverId=24537,ender="Handsome Terry",enderType="NPC",enderId=24537,rewardNextId=11473,poiX=-117,poiY=-3550,wowhead="https://www.wowhead.com/wotlk/quest=11455",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Us pirates are known for many things, but hygiene isn't one of them.  Most pirate ships be carrying five or six times as many rats as people.$B$BIt's no wonder all the bears on this island caught the rabies soon after we moved in.  Long story short, the boss wants 'em all dead.$B$BIt just so happens I know a recipe for a bear musk fragrance popular among Stormwind nobles.  We kill the bears and sell the musk.  I see a fine business opportunity for us here.  What say ye?",logDesc="Handsome Terry at Scalawag Point in Howling Fjord wants you to obtain 4 Bear Musk from the Rabid Brown Bears in the surrounding area."} end
if not DB[11456] then DB[11456]={id=11456,zoneId=495,name="Feeding the Survivors",level=71,minLevel=69,giver="Elder Atuik",giverType="NPC",giverId=24755,ender="Elder Atuik",enderType="NPC",enderId=24755,poiX=820,poiY=-2910,wowhead="https://www.wowhead.com/wotlk/quest=11456",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="We tuskarr rely mostly on our fish catch for sustenance.  In times of great need, however, we will on occasion hunt land animals.$B$BThe nearby village of Iskaal was recently attacked by pirates and the survivors just keep pouring in.$B$BOur catch has been modest this week, but there are many shoveltusk on the island and their meat is plentiful.$B$BAid my people by hunting these great beasts and obtaining their meat.",logDesc="Elder Atuik at Kamagua in Howling Fjord wants you to obtain 6 pieces of Island Shoveltusk Meat from Island Shoveltusk in the Isle of Spears."} end
if not DB[11457] then DB[11457]={id=11457,zoneId=495,name="Arming Kamagua",level=71,minLevel=69,giver="Elder Atuik",giverType="NPC",giverId=24755,ender="Elder Atuik",enderType="NPC",enderId=24755,rewardNextId=11458,poiX=820,poiY=-2910,wowhead="https://www.wowhead.com/wotlk/quest=11457",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Issliruk, the spirit of war, is depicted as a silver eagle by my people.  Our stories tell of how Issliruk fought against a hundred worgs to save his young.$B$BIt is time for us, too, to fight against our foes to save our brethren.  We will need to craft new weapons.  The horns of the frostwing chimaera that make their home in the snowy parts of the island are sharp and are easily crafted into spear tips.  Bring me the best of these horns that you can find.",logDesc="Elder Atuik wants you to obain 3 Chimaera Horns."} end
if not DB[11458] then DB[11458]={id=11458,zoneId=495,name="Avenge Iskaal",level=71,minLevel=69,giver="Elder Atuik",giverType="NPC",giverId=24755,ender="Elder Atuik",enderType="NPC",enderId=24755,poiX=820,poiY=-2910,wowhead="https://www.wowhead.com/wotlk/quest=11458",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The totem of Issliruk is ready, $N, and for that I thank you.  We must cast our peaceful ways for the time being and strike at those who've attacked our land and our kin.$B$BThe pirate slavers that raided Iskaal have lost their minds and slaughtered all their captives.  Go to Iskaal, to the east of here and do what must must be done.  Take this horn and call on my brethren should you need assistance.",logDesc="Elder Atuik wants you to go to Iskaal and slay 8 Northsea Slavers.  Use the Horn of Kamagua should you need assistance."} end
if not DB[11459] then DB[11459]={id=11459,zoneId=495,name="Zeh'gehn Sez",level=71,minLevel=69,giver="Zeh'gehn",giverType="NPC",giverId=24525,ender="Handsome Terry",enderType="NPC",enderId=24537,rewardNextId=11476,poiX=-134,poiY=-3548,wowhead="https://www.wowhead.com/wotlk/quest=11459",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Is like dis, mon.  Ye be wantin' me 'elp spotting some craven bag-o-wire been cardin' da crew?$B$BYe gotta bring me a croaker, matey.  Aft I an' I show ye who da blaggard be, mon.  Nah, nah, croaker show ye.  Ye'll ku fer yerself with yer own deadlights, yahso.$B$BBring us a carver yahso too, 'atsteppa.  Galang, bucko.",logDesc="Return to Handsome Terry to decipher what Zeh'gehn asked of you."} end
if not DB[11460] then DB[11460]={id=11460,zoneId=495,name="Trust is Earned",level=71,minLevel=68,giver="Hidalgo the Master Falconer",giverType="NPC",giverId=24750,ender="Hidalgo the Master Falconer",enderType="NPC",enderId=24750,rewardNextId=11465,poiX=498,poiY=-5948,wowhead="https://www.wowhead.com/wotlk/quest=11460",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The first and most important factor in falconry is the bond between the falconer and $g his:her; bird. Trust must be earned by the master!$B$B<Hidalgo points to the falcons in the cage at his feet.>$B$BIf you are to earn their trust you will first need to fill their bellies.$B$BThe fjord rock falcon, as these birds are known, primarily eat grubs. Throughout the fjord you will find loose rocks that serve as breeding grounds for these grubs. Find a grub and return here to feed the falcons in the cage.",logDesc="Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to find a Fjord Grub and feed it to one of the falcons in the cage by his feet."} end
if not DB[11461] then DB[11461]={id=11461,zoneId=495,name="DEPRECATED",level=71,minLevel=69,wowhead="https://www.wowhead.com/wotlk/quest=11461",image="assets/images/quests/placeholder.png"} end
if not DB[11462] then DB[11462]={id=11462,zoneId=495,name="Handsome Terry",level=71,minLevel=70,rewardNextId=11434,wowhead="https://www.wowhead.com/wotlk/quest=11462",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Your people paid me good money to infiltrate the Northsea Freebooters and get your foot in the door.$B$BI talked you up to a fellow in Scalawag Point called Handsome Terry.  I told him you come highly recommended.$B$BPut your disguise on and go see him.  Here comes someone to take you there.$B$BYou're going to have to prove yourself a bit before they introduce you to their higher ups.  But that's all up to you.  Remember, $N, once you're inside you're on your own!",logDesc="Don the Pirate Disguise and speak to Handsome Terry inside Scalawag point."} end
if not DB[11463] then DB[11463]={id=11463,zoneId=495,name="Pirates of the North Seas",level=71,minLevel=69,rewardNextId=11462,wowhead="https://www.wowhead.com/wotlk/quest=11463",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The past few weeks have seen an increase in pirate attacks against our supply ships.  We've hired a goblin spy to pave the way for one of our agents to infiltrate the suspected pirates.$B$BThis group of Northsea Freebooters operates out of Scalawag Point, on Garvan's Reef.  We don't know much about them, but we do know that Sylvanas wants their leader's head.$B$BYou come very highly recommended, $N.  If you take on this task, we can keep our military focused against Arthas' forces.  Are you up to it?",logDesc="Find Grezzix Spindlesnap on the northern end of Garvan's Reef off of the Southwestern coast of Howling Fjord."} end
if not DB[11464] then DB[11464]={id=11464,zoneId=495,name="Gambling Debt",level=71,minLevel=69,giver="Taruk",giverType="NPC",giverId=24541,ender="Taruk",enderType="NPC",enderId=24541,rewardNextId=11466,poiX=-128,poiY=-3594,wowhead="https://www.wowhead.com/wotlk/quest=11464",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I heard you did a little work for Terry.  I was hoping someone reliable would show up around these parts.$B$BSee, pirates love to gamble.  They, however, do not love to pay their gambling debt.$B$BIf you're interested in collecting some coin on my behalf, I'd be willing to give you a cut.$B$BLet's start you out with an easy one.  \"Silvermoon\" Harry's a bit of an eccentric, keeps all sorts of expensive blood elf knickknacks inside his tent - yet when I see him he always pretends to be broke.  Get my gold.",logDesc="Taruk at Scalawag Point wants you to collect \"Silvermoon\" Harry's Debt."} end
if not DB[11465] then DB[11465]={id=11465,zoneId=495,name="The Ransacked Caravan",level=71,minLevel=68,giver="Hidalgo the Master Falconer",giverType="NPC",giverId=24750,ender="Hidalgo the Master Falconer",enderType="NPC",enderId=24750,rewardNextId=11468,poiX=498,poiY=-5948,wowhead="https://www.wowhead.com/wotlk/quest=11465",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I was leading a caravan here from Valgarde that was attacked by Dragonflayers. I was the only survivor of that ambush. Unfortunately, I couldn't make it back here with the cargo of fjord turkeys. This is the perfect opportunity for you to get your feet wet with your rock falcon.$B$B<Hidalgo hands you a cage.>$B$BTake this falcon cage and head west down the road leading out of this camp. Use the falcon to capture the loose turkeys and return here when you've gathered enough.$B$BRemember to feed the falcon!",logDesc="Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use the Trained Rock Falcon to recover 5 Fjord Turkeys.$B$BReturn to Hidalgo with the cage once you have completed this task."} end
if not DB[11466] then DB[11466]={id=11466,zoneId=495,name="Jack Likes His Drink",level=71,minLevel=69,giver="Taruk",giverType="NPC",giverId=24541,ender="Taruk",enderType="NPC",enderId=24541,rewardNextId=11467,poiX=-128,poiY=-3594,wowhead="https://www.wowhead.com/wotlk/quest=11466",image="assets/images/quests/placeholder.png",xpDiff=4,money=94000,desc="Our next customer,  Jack Adams, won't be the pushover that Harry was.  He spends all day drinking with his friends, tough pirates all of them.  Let's not use force this time, could get ugly.$B$BSee if you can use his drinking habit to your advantage.  There's only so much alcohol someone can handle before passing out.$B$BMaybe one of the bar wenches will be of assistance.  Once he's out, see if you can slip your hand into his pocket and get what's mine.",logDesc="Taruk at Scalawag Point in Howling Fjord wants you to collect Jack Adams' Debt."} end
if not DB[11467] then DB[11467]={id=11467,zoneId=495,name="Dead Man's Debt",level=71,minLevel=69,giver="Taruk",giverType="NPC",giverId=24541,ender="Taruk",enderType="NPC",enderId=24541,poiX=-128,poiY=-3594,wowhead="https://www.wowhead.com/wotlk/quest=11467",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You might've heard of Black Conrad, he's a famous pirate around these parts.$B$BWell, he had a thing for gambling on my fights.  He had a thing for not paying, too.$B$BI'd love to collect, but trouble is... he's dead.$B$BI was about ready to write the whole thing off, when I came across this...$B$B<Taruk unfolds a map of the Isle of Spears with an X on a northeastern plateau.>$B$BHe hid his treasure on tuskarr land.  I want you to get it.  I'll be damned if I let that bilge sucker get away without paying.",logDesc="Taruk at Scalawag Point wants you to search for Black Conrad's Treasure on the plateau in the northeastern end of the Isle of Spears, just north of Iskaal.",rewards={{id=34119,qty=1}}} end
if not DB[11468] then DB[11468]={id=11468,zoneId=495,name="Falcon Versus Hawk",level=71,minLevel=68,giver="Hidalgo the Master Falconer",giverType="NPC",giverId=24750,ender="Hidalgo the Master Falconer",enderType="NPC",enderId=24750,rewardNextId=11470,poiX=498,poiY=-5948,wowhead="https://www.wowhead.com/wotlk/quest=11468",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Do you feel the closeness, $N? Surely you feel a true bond forming between you and your falcon. Would you believe me if I told you that when the time is right you'll be able to see through the eyes of your bird? Aye, it is the ultimate level of falconry.$B$BBut first you must hunt more! The bird must hone and quicken its reflexes. Send it against a more formidable opponent! The fjord hawks of the region make the tops of the trees around us their homes. They shall be your next target!  ",logDesc="Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 10 Fjord Hawks.$B$BReturn to Hidalgo with the cage when you have completed this task.$B"} end
if not DB[11469] then DB[11469]={id=11469,zoneId=495,name="Swabbin' Soap",level=71,minLevel=69,giver="Scuttle Frostprow",giverType="NPC",giverId=24784,ender="Scuttle Frostprow",enderType="NPC",enderId=24784,poiX=-91,poiY=-3680,wowhead="https://www.wowhead.com/wotlk/quest=11469",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Yeah, I got to get the deck swabbed spotless afore Mad Jonah comes 'round. An' I ain't gonna do it on my hands and knees neither!$B$BProblem is, we're all outa soap. That's more your problem than mine though, mate. Being the newbie 'round here, I gots a special trip for ya to make.$B$BUp on the northwest coast of this island, there's a whole mess o' sea lions. Amongst the nearby ice floes you'll find the alpha bull, Big Roy. Bring me back his blubber and I'll magic-up the best soap ya ever seen!",logDesc="Scuttle Frostprow wants you to obtain Big Roy's Blubber as the main ingredient for her magic swabbin' soap. Return to her on the eastern pirate ship at Scalawag Point when you have it."} end
if not DB[11470] then DB[11470]={id=11470,zoneId=495,name="There Exists No Honor Among Birds",level=71,minLevel=68,giver="Hidalgo the Master Falconer",giverType="NPC",giverId=24750,ender="Hidalgo the Master Falconer",enderType="NPC",enderId=24750,poiX=498,poiY=-5948,wowhead="https://www.wowhead.com/wotlk/quest=11470",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="You are most definitely ready for the next step in falconry, $N.$B$BTake your trained falcon east of here, to the vrykul hawk roost near the Stonewall Lift. From the roost you will send out your falcon to steal the eggs of the hawks. Their nests will be located in remote areas of the cliff walls surrounding the roost. Locate those nests and use your falcon to scavenge for the eggs!$B$BBeware the fjord hawk matriarchs, $N. Should you come under attack, use your falcon's escape and soar abilities to flee!",logDesc="Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 8 Fjord Hawk Eggs.$B$BReturn to Hidalgo with the cage when you have completed this task.",choiceRewards={{id=35860,qty=1},{id=35859,qty=1},{id=35861,qty=1},{id=35862,qty=1}}} end
if not DB[11471] then DB[11471]={id=11471,zoneId=495,name="The Jig is Up",level=71,minLevel=69,giver="Annie Bonn",giverType="NPC",giverId=24741,ender="Annie Bonn",enderType="NPC",enderId=24741,poiX=-85,poiY=-3539,wowhead="https://www.wowhead.com/wotlk/quest=11471",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I know why you're here, $N.  You've been sent to kill our leader, Jonah Sterling.$B$BI'd like to offer my help.  Jonah's leadership threatens our operation.$B$BAttacking the Horde and the Alliance fleets simultaneously?  Suicidal.  Trying to sell the tuskarr as slaves when they die days after leaving this climate?  Disastrous.$B$BJonah's hideout is located inside a cave west of here.  Bring me his spyglass as proof of the deed  and my first action as lead will be to end all attacks against your allies.",logDesc="Annie Bonn at Scalawag Point wants you to bring her Jonah Sterling's Spyglass.",choiceRewards={{id=38258,qty=1},{id=38259,qty=1},{id=38257,qty=1}}} end
if not DB[11472] then DB[11472]={id=11472,zoneId=495,name="The Way to His Heart...",level=-1,minLevel=69,giver="Anuniaq",giverType="NPC",giverId=24810,ender="Anuniaq",enderType="NPC",enderId=24810,poiX=744,poiY=-2885,wowhead="https://www.wowhead.com/wotlk/quest=11472",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The Northsea Pirates slaughtered the isles' alpha sea lion bull, Big Roy. They made soap from him to clean the decks of their ships!$B$B<Anuniaq sighs.>$B$BNow the sea lions won't mate. Help me to repopulate their numbers.$B$BThe reef bulls can be found at the Twin Shores to the southeast. They crave the tasty reef fish that can be found on the east and west sides of the isles.$B$BTake this net and gather enough fish, at least a dozen -- maybe more, to lure a bull across the strait to a reef cow.",logDesc="Toss Tasty Reef Fish at a Reef Bull to lead it to a Reef Cow. Once you have helped the two to find true love, return to Anuniaq at Kamagua."} end
if not DB[11473] then DB[11473]={id=11473,zoneId=495,name="A Traitor Among Us",level=71,minLevel=69,giver="Handsome Terry",giverType="NPC",giverId=24537,ender="Zeh'gehn",enderType="NPC",enderId=24525,rewardNextId=11459,poiX=-117,poiY=-3550,wowhead="https://www.wowhead.com/wotlk/quest=11473",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Our second in command, Annie Bonn, has been acting rather paranoid as of late.  She seems sure we have an infiltrator in our ranks, can ye believe it?$B$BAnyhow, we have a foolproof way of uncovering rats around these parts.  See, good ole' Zeh'gehn over here happens to be an authentic witch doctor.  His family hails all the way from Zul... something or other.$B$BGo let him know that we're in need of his divination skills.  I must warn ye, $N, only one or two of us can understand anything Zeh'gehn says.",logDesc="Speak to Zeh'gehn at Scalawag Post."} end
if not DB[11474] then DB[11474]={id=11474,zoneId=495,name="Problems on the High Bluff",level=71,minLevel=68,giver="Stanwad",giverType="NPC",giverId=24717,ender="Walt",enderType="NPC",enderId=24807,rewardNextId=11475,poiX=480,poiY=-5929,wowhead="https://www.wowhead.com/wotlk/quest=11474",image="assets/images/quests/placeholder.png",xpDiff=1,desc="As usual, the real work is left up to me and my crew. Thankfully McSorf's team didn't die for nothin'. The cipher they recovered will help us crack the stuff we've found up here - that is if we can ever get back to it! Damned iron dwarves have sprung up like leaks all over the place and are now attemptin' to bury the sites! Can you believe it? Bastards want to bury our finds!$B$BAnyhow, talk to Walt over yonder. He'll get you started.",logDesc="Speak with Walt."} end
if not DB[11475] then DB[11475]={id=11475,zoneId=495,name="Tools to Get the Job Done",level=71,minLevel=68,giver="Walt",giverType="NPC",giverId=24807,ender="Walt",enderType="NPC",enderId=24807,poiX=476,poiY=-5935,wowhead="https://www.wowhead.com/wotlk/quest=11475",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've been studying this deactivated construct for days, $N. I think I can create a reasonable facsimile of the golem that would have room inside to fit one passenger. The idea being that it would fool those iron dwarves and allow us to get inside Baelgun's.$B$BNow I'm not gonna be able to make anything with a hammer and poker. I need my tools! Unfortunately I left those behind at Ivald's Ruin when the iron dwarves first attacked. Get me my tools!$B$BIvald's Ruin is located far to the northeast.",logDesc="Walt at the Explorers' League Outpost in the Howling Fjord wants you to recover his Building Tools."} end
if not DB[11476] then DB[11476]={id=11476,zoneId=495,name="A Carver and a Croaker",level=71,minLevel=69,giver="Handsome Terry",giverType="NPC",giverId=24537,ender="Zeh'gehn",enderType="NPC",enderId=24525,poiX=-117,poiY=-3550,wowhead="https://www.wowhead.com/wotlk/quest=11476",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Some of the pirates around here... we have our own special way of talking.  Zeh'gehn has... many different special ways of talking... all mixed together.$B$BFrom what I can tell he wants a frog and a knife.$B$B\"Silvermoon\" Harry might have a knife on the cheap.  There's frogs all over town, just grab one and bring it to him along with the knife.$B$BI'd hate to be in the poor critter's shoes, if you know what I mean.",logDesc="Get a Shiny Knife from \"Silvermoon\" Harry and capture a Scalawag Frog.  Bring these to Zeh'Gehn at Scalawag Point."} end
if not DB[11477] then DB[11477]={id=11477,zoneId=495,name="Out of My Element?",level=70,minLevel=68,giver="Donny",giverType="NPC",giverId=24811,ender="Donny",enderType="NPC",enderId=24811,poiX=1147,poiY=-6162,wowhead="https://www.wowhead.com/wotlk/quest=11477",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Keep it down, $r. These iron dwarves are quick on the trigger. Now don't let the activities down in the dig fool you. Those steel-skinned abominations aren't digging anything up! No sir - on the contrary - they're burying the site! For whatever whacked out reason, they don't want anyone finding this place.$B$BWhat kind of dwarf buries ancient relics and dig sites? I'll tell you what kind: the kind you kill with reckless abandon! Get in there and take 'em out!",logDesc="Donny at Ivald's Ruin in the Howling Fjord wants you to kill 10 Iron Rune Destroyers, 5 Iron Rune Laborers and 2 Iron Rune Sages."} end
if not DB[11478] then DB[11478]={id=11478,zoneId=495,name="Outpost Over Yonder...",level=71,minLevel=68,giver="Donny",giverType="NPC",giverId=24811,ender="Stanwad",enderType="NPC",enderId=24717,poiX=1147,poiY=-6162,wowhead="https://www.wowhead.com/wotlk/quest=11478",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I see that you haven't visited my brothers at the Explorers' League Outpost south of here. Why don't you do Donny a favor and deliver this message to Stanwad. He'll be interested to hear about the activities of the iron dwarves up here.$B$BLike I said, mount up and start heading south. You'll see the outpost right before you get to Baelgun's.",logDesc="Deliver Donny's Letter to Stanwad at the Explorers' League Outpost."} end
if not DB[11479] then DB[11479]={id=11479,zoneId=495,name="\"Crowleg\" Dan",level=71,minLevel=69,giver="Zeh'gehn",giverType="NPC",giverId=24525,ender="Handsome Terry",enderType="NPC",enderId=24537,rewardNextId=11480,poiX=-134,poiY=-3548,wowhead="https://www.wowhead.com/wotlk/quest=11479",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Croaker's spoken, matey. \"Crowleg\" Dan's on da ship yonder.$B$BBest go trace that blaggard, mon.  Show'im dis set's not fe be crossed.  Gaan back fe Terry when ye keelhaul 'is behind.",logDesc="Confront \"Crowleg\" Dan, who is in one of the ships at Scalawag Point. Speak to Handsome Terry when you've completed this task."} end
if not DB[11480] then DB[11480]={id=11480,zoneId=495,name="Meet Number Two",level=71,minLevel=69,giver="Handsome Terry",giverType="NPC",giverId=24537,ender="Annie Bonn",enderType="NPC",enderId=24741,rewardNextId=11471,poiX=-117,poiY=-3550,wowhead="https://www.wowhead.com/wotlk/quest=11480",image="assets/images/quests/placeholder.png",xpDiff=2,desc="All the good work you've done for us hasn't gone unnoticed, $N.  Our second in command, the delightful Annie Bonn, is incredibly impressed with what you've done so far and wants to meet you.  ",logDesc="Speak to Annie Bonn at Scalawag Point."} end
if not DB[11481] then DB[11481]={id=11481,zoneId=4080,name="Crisis at the Sunwell",level=70,minLevel=70,giver="Adyen the Lightwarden",giverType="NPC",giverId=18537,ender="Exarch Larethor",enderType="NPC",enderId=24813,rewardNextId=11488,poiX=-1775,poiY=5734,wowhead="https://www.wowhead.com/wotlk/quest=11481",image="assets/images/quests/placeholder.png",xpDiff=1,money=4400,desc="By the naaru, I thank you, $r, for your efforts.$b$bOur work is far from finished, however, and I must request that you undertake a critical mission - one as important as any I've issued.$b$bOur forces are spread thinly. To compound the strain, we've had to dispatch a contingent to Azeroth to investigate developments at the Sunwell Plateau.$b$bYou are needed there, $n. Report to Larethor. Tell him that I wish we could spare more men.",logDesc="Adyen the Lightwarden on the Aldor Rise in Shattrath City has requested that you travel to Sunwell Plateau and speak with Larethor."} end
if not DB[11482] then DB[11482]={id=11482,zoneId=4080,name="Duty Calls",level=70,minLevel=70,giver="Dathris Sunstriker",giverType="NPC",giverId=18594,ender="Exarch Larethor",enderType="NPC",enderId=24813,rewardNextId=11488,poiX=-2177,poiY=5422,wowhead="https://www.wowhead.com/wotlk/quest=11482",image="assets/images/quests/placeholder.png",xpDiff=1,money=4400,desc="Hear me, $r.$b$bDuty requires that you return to Azeroth. Every able person is to report to the Sunwell Plateau immediately.$b$bI'm afraid I have no more information to share, except this:$b$bYou'll be joining forces with the Aldor for this mission. Speak with a draenei by the name of Larethor when you arrive.$b$bApparently, the situation calls for us to set our differences aside and join forces.$b$bPrepare yourself, friend. This sounds serious.",logDesc="Dathris Sunstriker on Scryer's Tier in Shattrath City has insisted that you travel to Azeroth at once and report to Larethor at the Sunwell."} end
if not DB[11483] then DB[11483]={id=11483,zoneId=495,name="We Can Rebuild It",level=71,minLevel=68,giver="Walt",giverType="NPC",giverId=24807,ender="Walt",enderType="NPC",enderId=24807,poiX=476,poiY=-5935,wowhead="https://www.wowhead.com/wotlk/quest=11483",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Tools? Check. Materials? Negative.$B$BIf we're going to build this thing, you're going to have to get me the materials.$B$BFirst things first, $N. For the skeletal structure I'm going to need a large barrel from Nifflevar, some dark iron ingots from Valgarde, and industrial strength rope from Baleheim.$B$BNifflevar and Baleheim are vrykul towns northwest of here. Valgarde is located in Daggercap Bay, also to the northwest. Speak with McGoyver to get the ingots. He'll fly you back here once you're all done.",logDesc="Walt at the Explorers' League Outpost in the Howling Fjord wants you to bring him a Large Barrel, Industrial Strength Rope and Dark Iron Ingots."} end
if not DB[11484] then DB[11484]={id=11484,zoneId=495,name="We Have the Technology",level=71,minLevel=68,giver="Walt",giverType="NPC",giverId=24807,ender="Walt",enderType="NPC",enderId=24807,poiX=476,poiY=-5935,wowhead="https://www.wowhead.com/wotlk/quest=11484",image="assets/images/quests/placeholder.png",xpDiff=5,desc="While the infrastructure for a piece of machinery like this is important, we can't underestimate the appearance of the construct. If we're to fool the iron dwarves the clone must be exact!$B$BI can make this happen.$B$BBring me a pristine shoveltusk hide from the shoveltusk of this region and steel ribbing from vrykul in Nifflevar or Baleheim to the northwest.",logDesc="Walt at the Explorers' League Outpost in the Howling Fjord wants you to bring him a Pristine Shoveltusk Hide and Steel Ribbing."} end
if not DB[11485] then DB[11485]={id=11485,zoneId=495,name="Iron Rune Constructs and You: Rocket Jumping",level=71,minLevel=68,giver="Walt",giverType="NPC",giverId=24807,ender="Walt",enderType="NPC",enderId=24807,rewardNextId=11489,poiX=476,poiY=-5935,wowhead="https://www.wowhead.com/wotlk/quest=11485",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Alright, $N; the time has come for you to climb inside this thing and learn how to use its basic abilities. When you're ready, get on the work bench and I'll get you situated inside the construct.$B$BYour first lesson is going to be using the construct's transportation system. You'll notice that the iron dwarves have set up special rune carvings around the dig site. Their constructs use those rune carvings to power up and fly from point to point. Try it with the rune carving I built here.$B",logDesc="Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Rocket Jump ability at Walt's Iron Rune Carving.$B$BDismiss your construct by dismissing it from the pet window once you have completed the quest."} end
if not DB[11486] then DB[11486]={id=11486,zoneId=-370,name="The Best of Brews",level=-1,minLevel=1,giver="Coren Direbrew",giverType="NPC",giverId=23872,ender="Ipfelkofer Ironkeg",enderType="NPC",enderId=24710,poiX=892,poiY=-129,wowhead="https://www.wowhead.com/wotlk/quest=11486",image="assets/images/quests/placeholder.png",desc="I know a bright $Glad:lass; like ya wants to stop the hostilities on the surface, eh? Ya want yer nice and merry Brewfest to go off without a hitch. I'll make ya a deal.$b$bTake this keg of our finest brew to the Brewfest Organizer outside Ironforge, so that we Dark Iron dwarves can be rightly represented! The best brew in all of Azeroth comes from right here in this mountain, and don't ya ferget it!",logDesc="Take the Dark Iron Ale Keg to Ipfelkofer Ironkeg in Dun Morogh.",rewards={{id=34140,qty=1}}} end
if not DB[11487] then DB[11487]={id=11487,zoneId=-370,name="The Best of Brews",level=-1,minLevel=1,giver="Coren Direbrew",giverType="NPC",giverId=23872,ender="Tapper Swindlekeg",enderType="NPC",enderId=24711,poiX=892,poiY=-129,wowhead="https://www.wowhead.com/wotlk/quest=11487",image="assets/images/quests/placeholder.png",desc="I know a bright $Glad:lass; like ya wants to stop the hostilities on the surface, eh? Ya want yer nice and merry Brewfest to go off without a hitch. I'll make ya a deal.$b$bTake this keg of our finest brew to the Brewfest Organizer outside Orgrimmar, so that we Dark Iron dwarves can be rightly represented! The best brew in all of Azeroth comes from right here in this mountain, and don't ya ferget it!",logDesc="Take the Dark Iron Ale Keg to Tapper Swindlekeg in Durotar.",rewards={{id=34140,qty=1}}} end
if not DB[11488] then DB[11488]={id=11488,zoneId=4131,name="Magisters' Terrace",level=70,minLevel=70,giver="Exarch Larethor",giverType="NPC",giverId=24813,ender="Tyrith",enderType="NPC",enderId=24822,rewardNextId=11490,poiX=12887,poiY=-6879,wowhead="https://www.wowhead.com/wotlk/quest=11488",image="assets/images/quests/placeholder.png",xpDiff=8,desc="Welcome to the Sunwell, $c. Get yourself settled in and contribute however you can - there's much to do!$b$bMe? Yes, I have a little something that needs doing, but I'm not sure you're up to the task.$b$bWe've had a contact embedded in Magisters' Terrace gathering intelligence for us. He's recently failed to report and I'm growing concerned.$b$bThe terrace is just up the rise to the east. The information he was collecting is vital to our mission.$b$bThink you can handle it, $r?",logDesc="Exarch Larethor at the Shattered Sun Staging Area wants you to search Magisters' Terrace and find Tyrith, a blood elf spy."} end
if not DB[11489] then DB[11489]={id=11489,zoneId=495,name="Iron Rune Constructs and You: Collecting Data",level=71,minLevel=68,giver="Walt",giverType="NPC",giverId=24807,ender="Walt",enderType="NPC",enderId=24807,rewardNextId=11491,poiX=476,poiY=-5935,wowhead="https://www.wowhead.com/wotlk/quest=11489",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The most important part of your job while controlling the construct is the collection of data. I've placed an iron dwarf relic in the cart over yonder. It's the floating, lightning infused crystal.$B$BGet on the work bench and I'll put you back in the construct. Once you're back in the driver's seat, use the construct's data collection ability to pick up the test data.",logDesc="Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Collect Data ability while standing near the Iron Dwarf Relic.$B$BDismiss your construct by dismissing it from the pet window once you have completed the quest."} end
if not DB[11490] then DB[11490]={id=11490,zoneId=4131,name="The Scryer's Scryer",level=70,minLevel=70,giver="Tyrith",giverType="NPC",giverId=24822,ender="Kalecgos",enderType="NPC",enderId=24848,rewardNextId=11492,poiX=241,poiY=-97,wowhead="https://www.wowhead.com/wotlk/quest=11490",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="<Tyrith winces in pain as he speaks.>$b$bGo to the terrace... use the orb.$b$b...They're...feeding the sunwell....$b$b <Tyrith gasps for breath.>$b$bHurry... They must be stopped... before they can....$b$b<Tyrith dies.>",logDesc="Tyrith wants you to use the orb on the balcony in Magisters' Terrace."} end
if not DB[11491] then DB[11491]={id=11491,zoneId=495,name="Iron Rune Constructs and You: The Bluff",level=71,minLevel=68,giver="Walt",giverType="NPC",giverId=24807,ender="Walt",enderType="NPC",enderId=24807,poiX=476,poiY=-5935,wowhead="https://www.wowhead.com/wotlk/quest=11491",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You always gotta have a contingency plan in case your main plan backfires! That's why I've built in some anti-intelligence systems into the construct.$B$BYour shiny new ride might rouse some suspicion while you're at Baelgun's excavation site. That's what your bluff ability is for! Just use that any time you're confronted and you'll be safe from harm.$B$BTest it out on Lebronski by walking on his rug. Once he starts huffin' and puffin', use the bluff!$B$BGet on the work bench when you're ready to begin.",logDesc="Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Bluff ability on Lebronski after you've walked on his rug.$B$BDismiss your construct by dismissing it from the pet window once you have completed the quest.$B"} end
if not DB[11492] then DB[11492]={id=11492,zoneId=4131,name="Hard to Kill",level=70,minLevel=70,giver="Kalecgos",giverType="NPC",giverId=24848,ender="Exarch Larethor",enderType="NPC",enderId=24813,wowhead="https://www.wowhead.com/wotlk/quest=11492",image="assets/images/quests/placeholder.png",xpDiff=8,money=44000,desc="Welcome to the Sunwell, mortals. Your arrival is indeed timely.$b$bAs you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.$b$bKael'thas has risen from the ashes of defeat and once more leads them in their efforts. Find him, mortals. He must again be stopped.$b$bOther, equally urgent matters require my immediate attention. I shall leave Kael's fate to you. Do not fail.$b$bWith luck, we shall speak again.",logDesc="Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace. You are to take Kael's head and report back to Larethor at the Shattered Sun Staging Area.",choiceRewards={{id=35487,qty=1},{id=35488,qty=1},{id=35489,qty=1}}} end
if not DB[11493] then DB[11493]={id=11493,zoneId=0,name="UNUSED",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=11493",image="assets/images/quests/placeholder.png"} end
if not DB[11494] then DB[11494]={id=11494,zoneId=495,name="Lightning Infused Relics",level=71,minLevel=68,giver="Walt",giverType="NPC",giverId=24807,ender="Walt",enderType="NPC",enderId=24807,poiX=476,poiY=-5935,wowhead="https://www.wowhead.com/wotlk/quest=11494",image="assets/images/quests/placeholder.png",xpDiff=6,money=141000,desc="Your construct is ready to go. All abilities have been given a once over and I've programmed the machine to both comprehend and speak the language of the titans.$B$BTake the construct to Baelgun's Excavation Site, due south of here, and collect data from the lightning infused relics that litter the site. Remember to bluff any iron dwarves that suspect your construct to be a fake. And don't forget about rocket jumping from rune to rune to get around in there!$B$BGet on the table when you're ready!",logDesc="Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Collect Data ability to collect 15 sets of Iron Rune Data.$B$BDismiss your construct by dismissing it from the pet window once you have completed the quest.",choiceRewards={{id=35845,qty=1},{id=35844,qty=1},{id=35846,qty=1},{id=35848,qty=1}}} end
if not DB[11495] then DB[11495]={id=11495,zoneId=495,name="The Delicate Sound of Thunder",level=71,minLevel=68,giver="Walt",giverType="NPC",giverId=24807,ender="Walt",enderType="NPC",enderId=24807,poiX=476,poiY=-5935,wowhead="https://www.wowhead.com/wotlk/quest=11495",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="The cavern that we opened at Baelgun's was the one place that most steered clear of... Can't say I blame 'em. The sound of thunder shot out of that cave, $N! Loud, booming thunder!$B$BI think near the end, it was abandoned by all. Bad, bad things happened to any that went in to explore - most never coming back.$B$BI want you to check that cave out while you're at Baelgun's. Explore around the titan statue inside and report back with your findings.",logDesc="Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct to explore the thundering cave at Baelgun's Excavation Site.$B$BDismiss your construct by dismissing it from the pet window once you have completed the quest.",choiceRewards={{id=35851,qty=1},{id=35849,qty=1},{id=35852,qty=1},{id=35856,qty=1}}} end
if not DB[11496] then DB[11496]={id=11496,zoneId=4080,name="The Sanctum Wards",level=70,minLevel=70,ender="Captain Theris Dawnhearth",enderType="NPC",enderId=24967,wowhead="https://www.wowhead.com/wotlk/quest=11496",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="Our first priority is to capture the Sun's Reach Sanctum.  Once we've secured it, we'll be able to use its energy to open a portal from Shattrath.$B$BThe sanctum is overrun with the Wretched - former blood elves who've devolved into mindless husks of their former selves.  Its defenses would've normally prevented this intrusion, but the Wretched have stolen the power sources from the protective wards.$B$BHunt down the Wretched and get the mana remnants they carry.  Use them to energize the sanctum wards.",logDesc="Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the Sun's Reach Sanctum to the east."} end
if not DB[11497] then DB[11497]={id=11497,zoneId=3520,name="Learning to Fly",level=70,minLevel=70,giver="Nutral",giverType="NPC",giverId=18940,ender="Ilsa Blusterbrew",enderType="NPC",enderId=20511,poiX=-1832,poiY=5298,wowhead="https://www.wowhead.com/wotlk/quest=11497",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Though it may end up hurting my business in the long run, you look the sort that dreams of flying $g his : her; own mount through the skies, rather than being flown from place to place.$B$BI understand the feeling completely.$B$BYou, my friend, need to head to Wildhammer Stronghold in the southwest corner of Shadowmoon Valley. When you get there, speak with Ilsa Blusterbrew about some flight instruction. Mind you, her training's not cheap. But, I think that you'll find it worth your while.",logDesc="Speak with Ilsa Blusterbrew at Wildhammer Stronghold in Shadowmoon Valley."} end
if not DB[11498] then DB[11498]={id=11498,zoneId=3520,name="Learning to Fly",level=70,minLevel=70,giver="Nutral",giverType="NPC",giverId=18940,ender="Olrokk",enderType="NPC",enderId=20500,poiX=-1832,poiY=5298,wowhead="https://www.wowhead.com/wotlk/quest=11498",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Though it may end up hurting my business in the long run, you look the sort that dreams of flying $g his : her; own mount through the skies, rather than being flown from place to place.$B$BI understand the feeling completely.$B$BYou, my friend, need to head to Shadowmoon Village in the northwest corner of Shadowmoon Valley. When you get there, speak with Olrokk about some flight instruction. Mind you, his training's not cheap. But, I think that you'll find it worth your while.",logDesc="Speak with Olrokk at Shadowmoon Village in Shadowmoon Valley."} end
if not DB[11499] then DB[11499]={id=11499,zoneId=4131,name="Wanted: The Signet Ring of Prince Kael'thas",level=70,minLevel=70,giver="Wind Trader Zhareem",giverType="NPC",giverId=24369,ender="Wind Trader Zhareem",enderType="NPC",enderId=24369,poiX=-1792,poiY=5152,wowhead="https://www.wowhead.com/wotlk/quest=11499",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="$C, today I ask the impossible. Today, you must obtain the signet ring of Kael'thas Sunstrider, lord of the blood elves!$B$BIt's true, the rumors of his death within Tempest Keep were ill-founded. He has appeared once more, this time at the Magisters' Terrace on the Isle of Quel'Danas. What he is doing there is a tale for someone else to tell you. What I know is that I have innumerable collectors interested in his princely ring, and I mean to acquire it for them.$B$BOr rather, I mean for you to do so.",logDesc="Wind Trader Zhareem has asked you to obtain The Signet Ring of Prince Kael'thas. Deliver it to him in Shattrath's Lower City to collect the reward.$B$BThis quest may only be completed at the Magisters' Terrace on Heroic difficulty.",rewards={{id=29434,qty=2}}} end
if not DB[11500] then DB[11500]={id=11500,zoneId=4131,name="Wanted: Sisters of Torment",level=70,minLevel=70,giver="Nether-Stalker Mah'duun",giverType="NPC",giverId=24370,ender="Nether-Stalker Mah'duun",enderType="NPC",enderId=24370,poiX=-1797,poiY=5149,wowhead="https://www.wowhead.com/wotlk/quest=11500",image="assets/images/quests/placeholder.png",xpDiff=5,money=88000,desc="It has been whispered to Mah'duun that the sisters of torment are to be sent back to the hells from which they sprang.$B$BMah'duun knows that these demons can be found at the Magisters' Terrace on the Isle of Quel'Danas.$B$BYou will do this thing to earn the bounty, or you will not.",logDesc="Nether-Stalker Mah'duun wants you to slay 4 Sisters of Torment. Return to him in Shattrath's Lower City once you have done so in order to collect the bounty.",rewards={{id=29460,qty=1}}} end
if not DB[11501] then DB[11501]={id=11501,zoneId=495,name="News From the East",level=71,minLevel=68,giver="Walt",giverType="NPC",giverId=24807,ender="Captain Adams",enderType="NPC",enderId=23749,poiX=476,poiY=-5935,wowhead="https://www.wowhead.com/wotlk/quest=11501",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Westguard needs to know what's going on here, $N. I want you to personally deliver the news to Captain Adams.$B$BWhenever you're ready, let me know and I'll put you back in the construct for one final flight. It'll take you to Westguard Keep, but more than likely blow up in the process.$B$BIt's been a pleasure...",logDesc="Speak with Captain Adams at Westguard Keep.",choiceRewards={{id=35857,qty=1},{id=35858,qty=1}}} end
if not DB[11502] then DB[11502]={id=11502,zoneId=3518,name="In Defense of Halaa",level=70,minLevel=64,giver="Lakoor",giverType="NPC",giverId=24866,ender="Lakoor",enderType="NPC",enderId=24866,poiX=-2673,poiY=7204,wowhead="https://www.wowhead.com/wotlk/quest=11502",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="We are not a warlike race, $r.  However when war comes to our lands, we do not run away from it.$B$BThe Alliance and the Horde wage war in the city of Halaa, to the northwest. We do not know what the blood elves are scheming, but any victory for the Horde would be disastrous.  The history between our people and the orcs is one of bloodshed and betrayal.$B$BGo and slay the enemy in Halaa and you will be rewarded in coin, honor and renown.",logDesc="Defeat 10 enemy players in Halaa and return to Lakoor in Telaar."} end
if not DB[11503] then DB[11503]={id=11503,zoneId=3518,name="Enemies, Old and New",level=70,minLevel=64,giver="Karrtog",giverType="NPC",giverId=24881,ender="Karrtog",enderType="NPC",enderId=24881,poiX=-1286,poiY=7378,wowhead="https://www.wowhead.com/wotlk/quest=11503",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Our ancient enemy, the draenei, have returned with powerful allies.  They wage war in Halaa, southwest of here.$B$BWe cannot allow them a victory there as Garadar would be next without a doubt.$B$BGo and slay those who would aid our ancient enemy.",logDesc="Defeat 10 enemy players in Halaa and return to Karrtog in Garadar."} end
if not DB[11504] then DB[11504]={id=11504,zoneId=495,name="The Dead Rise!",level=71,minLevel=68,giver="Orfus of Kamagua",giverType="NPC",giverId=23804,ender="Orfus of Kamagua",enderType="NPC",enderId=23804,rewardNextId=11507,poiX=688,poiY=-3834,wowhead="https://www.wowhead.com/wotlk/quest=11504",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The path east of us is a primary hunting trail of the tuskarr. At least that's what it used to be...$B$BMore recently our hunters have been returning to Kamagua claiming that the dead have risen and are out for blood! That is what has brought my son and me here. Elder Atuik asks that we find resolution in the bluffs.$B$BWill you assist us in our time of need? I seek heroes willing to brave the perils of Shield Hill, southeast of here. Search the desecrated graves for clues and return your findings to me.",logDesc="Orfus of Kamagua at the Ancient Lift in the Howling Fjord wants you to find Fengir's Clue, Rodin's Clue, Isuldof's Clue and Windan's Clue."} end
if not DB[11505] then DB[11505]={id=11505,zoneId=3519,name="Spirits of Auchindoun",level=-1,minLevel=62,giver="Exorcist Sullivan",giverType="NPC",giverId=24885,ender="Exorcist Sullivan",enderType="NPC",enderId=24885,poiX=-2907,poiY=4028,wowhead="https://www.wowhead.com/wotlk/quest=11505",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Auchindoun's spirits have no stake in the conflict between the Alliance and the Horde, but incurring their favor will give our side an edge in the region.$B$BAncient custom directs the living to pay their respects at spirit towers in the Bone Wastes - though only at specific times of the day.  If you can help secure a tower during these times, you will have helped bring the spirits to our side.$B$BShould we succeed in gaining the spirits' favor, they will grant us a boon that will aid us in our endeavors.",logDesc="Help the Alliance secure a tower in the Bone Wastes."} end
if not DB[11506] then DB[11506]={id=11506,zoneId=3519,name="Spirits of Auchindoun",level=-1,minLevel=62,giver="Exorcist Vaisha",giverType="NPC",giverId=24886,ender="Exorcist Vaisha",enderType="NPC",enderId=24886,poiX=-2675,poiY=4396,wowhead="https://www.wowhead.com/wotlk/quest=11506",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The draenei might be our enemies, but the spirits of their ancestors in Auchindoun are restless and have no allegiance.$B$BThe draenei's custom required them to pay their respects at spirit towers at various times during the day.  If you can help secure a tower during these times, you will help the spirits return to peace in Auchindoun.$B$BThe Alliance will try to capture the towers in order to secure the dead's favor.   We must ensure that our side succeeds instead.",logDesc="Help the Horde secure a Spirit Tower in the Bone Wastes."} end
if not DB[11507] then DB[11507]={id=11507,zoneId=495,name="Elder Atuik and Kamagua",level=71,minLevel=68,giver="Orfus of Kamagua",giverType="NPC",giverId=23804,ender="Elder Atuik",enderType="NPC",enderId=24755,rewardNextId=11508,poiX=688,poiY=-3834,wowhead="https://www.wowhead.com/wotlk/quest=11507",image="assets/images/quests/placeholder.png",xpDiff=3,desc="<Orfus bundles up the clues you brought him.>$B$BMy people are bitterly entrenched in a war with the Northsea Freebooters. If any tuskarr could help us in our quest to right the wrongs of the pirates, it will be Elder Atuik of Kamagua. You must take these clues to him at once.$B$BTo get to Kamagua you must take the Ancient Lift, behind me. Take the lift directly to Kamagua and find Elder Atuik.",logDesc="Orfus of Kamagua in the Howling Fjord wants you to deliver Orfus's Bundle to Elder Atuik at Kamagua."} end
if not DB[11508] then DB[11508]={id=11508,zoneId=495,name="Grezzix Spindlesnap",level=71,minLevel=68,giver="Elder Atuik",giverType="NPC",giverId=24755,ender="Grezzix Spindlesnap",enderType="NPC",enderId=24643,rewardNextId=11509,poiX=820,poiY=-2910,wowhead="https://www.wowhead.com/wotlk/quest=11508",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The pirate thieves have set up port at Scalawag Point, far to the south. Unfortunately, they have fortified their camp with many deadly defenses.$B$BThere is someone that might be able to assist us in infiltrating Scalawag.$B$BA pirate mercenary by the name of Grezzix Spindlesnap recently came to our village in search of food and shelter. In exchange he gives us information about our enemies and feeds them misinformation about our attack plans. Seek him out at his ship just off the coast here - southwest.",logDesc="Speak with Grezzix Spindlesnap."} end
if not DB[11509] then DB[11509]={id=11509,zoneId=495,name="Street \"Cred\"",level=71,minLevel=68,giver="Grezzix Spindlesnap",giverType="NPC",giverId=24643,ender="\"Silvermoon\" Harry",enderType="NPC",enderId=24539,rewardNextId=11510,poiX=591,poiY=-2793,wowhead="https://www.wowhead.com/wotlk/quest=11509",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The Northsea Freebooters all fear and respect Grezzix. I'm thinking they recognize my special talents and envy my amazing ship. All you need to do is tag along with my cabin boy, Lou, and you'll be in like... In like tin. Pirates love tin.$B$BJust talk to Lou when you're ready to go and he'll take you to Scalawag.$B$BOh yea, you'll want to talk to \"Silvermoon\" Harry first. He'll have more information on the stuff they pilfered. Just watch what you say around him. He's a freak... crazy for blood elves.",logDesc="Speak with \"Silvermoon\" Harry at Scalawag Point about the missing Vrykul artifacts."} end
if not DB[11510] then DB[11510]={id=11510,zoneId=495,name="\"Scoodles\"",level=71,minLevel=68,giver="\"Silvermoon\" Harry",giverType="NPC",giverId=24539,ender="\"Silvermoon\" Harry",enderType="NPC",enderId=24539,poiX=-146,poiY=-3520,wowhead="https://www.wowhead.com/wotlk/quest=11510",image="assets/images/quests/placeholder.png",xpDiff=5,desc="One of the first things Jonah Sterling did after he went crazy was to take my prized sin'dorei scrying crystal and feed it to the bane of my existence, \"Scoodles\" the orca.$B$BNo I didn't name the damned thing. I just know that she swims out past the ships directly southeast of Scalawag. Kill that overinflated goldfish and rip out my beautiful sin'dorei crystal from its stomach.$B$BDo this and we can get down to business.",logDesc="\"Silvermoon\" Harry at Scalawag Point wants you to recover his Sin'dorei Scrying Crystal from the orca, \"Scoodles.\""} end
if not DB[11511] then DB[11511]={id=11511,zoneId=495,name="The Staff of Storm's Fury",level=71,minLevel=68,giver="\"Silvermoon\" Harry",giverType="NPC",giverId=24539,ender="Orfus of Kamagua",enderType="NPC",enderId=23804,poiX=-146,poiY=-3520,wowhead="https://www.wowhead.com/wotlk/quest=11511",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Those artifacts are cursed and you'd be crazy to go looking for them, $r. I know for certain that anyone that's come into direct contact with any of those items has either gone mad or been killed.$B$BTake that staff, for example. Last I heard the ship that held it was abandoned and left to rot on the coast of the Isle of Spears, north of here.$B$BIf you want that thing, check the ship's hold.$B$BWhatever you do, don't bring that staff back here! And steer clear of Abdul! He'll tear your heart out.",logDesc="Recover the Staff of Storm's Fury and deliver it to Orfus of Kamagua in the Howling Fjord.$B"} end
if not DB[11512] then DB[11512]={id=11512,zoneId=495,name="The Frozen Heart of Isuldof",level=71,minLevel=68,giver="\"Silvermoon\" Harry",giverType="NPC",giverId=24539,ender="Orfus of Kamagua",enderType="NPC",enderId=23804,poiX=-146,poiY=-3520,wowhead="https://www.wowhead.com/wotlk/quest=11512",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Some say Jonah was never quite right in the head, but I know the truth. It was the heart. That damned frozen heart! I saw the change in him the second he pulled it from the grave. I could see the blood freeze in his veins... It was then that the madness truly took over.$B$BHe left us to hole up in his cave on the north side of this island. Last I heard he had thrown the heart in the back of his bear den. Too little, too late...$B$BI'll kill you myself if you even think about bringing that heart back here!",logDesc="Recover the Frozen Heart of Isuldof and deliver it to Orfus of Kamagua in the Howling Fjord."} end
if not DB[11513] then DB[11513]={id=11513,zoneId=3522,name="Intercepting the Mana Cells",level=70,minLevel=70,ender="Exarch Nasuun",enderType="NPC",enderId=24932,wowhead="https://www.wowhead.com/wotlk/quest=11513",image="assets/images/quests/placeholder.png",xpDiff=4,money=44000,desc="I have devised a plan to acquire a power source strong enough for the creation of our portal.$B$BThe ethereal forces at Bash'ir Landing, atop the northwestern Blade's Edge Mountains, have been smuggling mana cells out of Tempest Keep and transporting them to the Sunwell for Kael'thas.$B$BThey have hidden the cells, but there is a way for you to find them; the ethereal carry phase devices that you can use to see the smuggled goods.$B$BJust beware the mana cells' phase wyrm guardians.",logDesc="Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.",rewards={{id=35232,qty=1}}} end
if not DB[11514] then DB[11514]={id=11514,zoneId=3522,name="Maintaining the Sunwell Portal",level=70,minLevel=70,giver="Exarch Nasuun",giverType="NPC",giverId=24932,ender="Exarch Nasuun",enderType="NPC",enderId=24932,poiX=-1844,poiY=5494,wowhead="https://www.wowhead.com/wotlk/quest=11514",image="assets/images/quests/placeholder.png",xpDiff=4,money=44000,desc="We must maintain the energy to our portal or it will collapse. The mana cells that the ethereals at Bash'ir Landing have hidden will continue to serve our purposes. The landing sits atop the northwestern corner of the Blade's Edge Mountains, far to the north.$B$BRemember, acquire a phase device from one of the ethereals and then use it to locate the smuggled goods.$B$BJust be cautious of the phase wyrms that they use to guard the mana cells.",logDesc="Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.",rewards={{id=35232,qty=1}}} end
if not DB[11515] then DB[11515]={id=11515,zoneId=3483,name="Blood for Blood",level=70,minLevel=70,giver="Magistrix Seyla",giverType="NPC",giverId=24937,ender="Magistrix Seyla",enderType="NPC",enderId=24937,poiX=876,poiY=2535,wowhead="https://www.wowhead.com/wotlk/quest=11515",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="When Kael's forces retreated through that portal, his most loyal lackeys were rewarded with an abominable gift.  They  stayed behind and gorged themselves on the blood of demons for days.$B$BThe blood has changed them, given them new powers.  It will also prove their undoing.$B$BObtain blood samples from other demons.  Use them to power this fel siphon and deprive these arrogant fools of their new powers.  Slay them in their weakened state and return to me.",logDesc="Magistrix Seyla at the Throne of Kil'jaeden wants you to kill 4 Emaciated Felbloods by using the Fel Siphon on them.  You will need Demonic Blood from nearby Wrath Heralds to power the Fel Siphon.",choiceRewards={{id=30809,qty=5},{id=30810,qty=5}}} end
if not DB[11516] then DB[11516]={id=11516,zoneId=3483,name="Blast the Gateway",level=70,minLevel=70,giver="Magistrix Seyla",giverType="NPC",giverId=24937,ender="Magistrix Seyla",enderType="NPC",enderId=24937,poiX=876,poiY=2535,wowhead="https://www.wowhead.com/wotlk/quest=11516",image="assets/images/quests/placeholder.png",xpDiff=4,money=44000,desc="We have to shut down this gateway to stop Legion reinforcements to the Isle of Quel'Danas.$B$BTake these embers, they contain one of my creations: a living flare.  It is designed to act as a powerful destructive force - as long as it has been provided enough energy.$B$BFind the fel sparks that wander the area and slay them near the living flare.  The flare will grow in power each time, until it becomes unstable.$B$BOnce you've achieved this bring the flare to the gateway.  It will know what to do.",logDesc="Magistrix Seyla at the Throne of Kil'jaeden wants you to use the Sizzling Embers to summon a Living Flare and slay Incandescent Fel Sparks near it until it becomes an Unstable Living Flare.  Return to the Legion Gateway with the Unstable Living Flare to destroy it.",rewards={{id=35232,qty=1}}} end
if not DB[11517] then DB[11517]={id=11517,zoneId=3703,name="Report to Nasuun",level=70,minLevel=70,ender="Exarch Nasuun",enderType="NPC",enderId=24932,wowhead="https://www.wowhead.com/wotlk/quest=11517",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I am most glad that you are here, $c! Now that we have taken this sanctum, we must hurry to create a magical portal that will lead to here from Shattrath City in the Outland.$B$BMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to do just that. He asked me to send along any promising candidates who have what it takes to help with the portal's creation.$B$BPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.",logDesc="Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City."} end
if not DB[11518] then DB[11518]={id=11518,zoneId=0,name="Sunwell Daily Portal Flag",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=11518",image="assets/images/quests/placeholder.png"} end
if not DB[11519] then DB[11519]={id=11519,zoneId=495,name="The Lost Shield of the Aesirites",level=71,minLevel=68,giver="\"Silvermoon\" Harry",giverType="NPC",giverId=24539,ender="3",enderType="NPC",enderId=24910,rewardNextId=11527,poiX=-146,poiY=-3520,wowhead="https://www.wowhead.com/wotlk/quest=11519",image="assets/images/quests/placeholder.png",xpDiff=4,desc="If you listen real close you can hear cannon fire coming from the northeast. That's Captain Ellis's ship, Sister Mercy. Thing is, Ellis and his entire crew were killed 'bout a month ago.$B$B<Harry nods.>$B$BGhost ship...$B$BIf it's info you be wantin' 'bout the shield, Ellis is the man to ask.$B$BSister Mercy docks on the small island between here and Sorlof's Strand to pick up more souls for the ship's crew 'bout once every five minutes. There be no shortage of souls 'round these parts...",logDesc="Speak with Captain Ellis aboard the Sister Mercy."} end
if not DB[11520] then DB[11520]={id=11520,zoneId=3519,name="Discovering Your Roots",level=70,minLevel=70,ender="Mar'nah",enderType="NPC",enderId=24975,wowhead="https://www.wowhead.com/wotlk/quest=11520",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="Greetings, $r.$b$bI'm afraid I have little to offer here until my reagents are stocked.$b$bOf the supplies I require, there is a special reagent, razorthorn root, that is particularly difficult to harvest.$b$bFortunately, I know a secret....$b$bUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.$b$bTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.",logDesc="Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.",rewards={{id=35232,qty=1}}} end
if not DB[11521] then DB[11521]={id=11521,zoneId=3519,name="Rediscovering Your Roots",level=70,minLevel=70,giver="Mar'nah",giverType="NPC",giverId=24975,ender="Mar'nah",enderType="NPC",enderId=24975,poiX=12848,poiY=-7015,wowhead="https://www.wowhead.com/wotlk/quest=11521",image="assets/images/quests/placeholder.png",xpDiff=6,money=44000,desc="My stocks are presently sufficient, but I'll need plenty of razorthorn roots to keep up with the demand.$b$bCollecting the roots is difficult, but I know a special method of extraction.$b$bUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.$b$bTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.$b$bReturn to me, $n, once you have collected five of the roots.",logDesc="Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.",rewards={{id=35232,qty=1}}} end
if not DB[11523] then DB[11523]={id=11523,zoneId=4080,name="Arm the Wards!",level=70,minLevel=70,giver="Captain Theris Dawnhearth",giverType="NPC",giverId=24967,ender="Captain Theris Dawnhearth",enderType="NPC",enderId=24967,poiX=12891,poiY=-6881,wowhead="https://www.wowhead.com/wotlk/quest=11523",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="We've succeeded in reactivating the crystal wards around the sanctum, but why stop there?  We'll build defenses around the other structures, but the Wretched are stubborn and continue to steal power from the crystal wards.$B$BHunt them down and get the mana remnants they carry.  Use the remnants to energize the sanctum wards; the safety of our operation depends on it.",logDesc="Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the structures in Sun's Reach."} end
if not DB[11524] then DB[11524]={id=11524,zoneId=4080,name="Erratic Behavior",level=70,minLevel=70,ender="Vindicator Xayann",enderType="NPC",enderId=24965,wowhead="https://www.wowhead.com/wotlk/quest=11524",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="We lack the numbers to capture the Sanctum at Sun's Reach, but I've a plan that will tip the scales in our favor.$B$BThe loose energy from the Sunwell has caused the sentries that patrol this island to malfunction.  The crystal cores that control their behavior are damaged beyond repair.$B$BI've crafted new crystals that will bring them under our control; place them inside of the hulls of defeated sentries.  We will need all the help we can get.",logDesc="Vindicator Xayanna at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units."} end
if not DB[11525] then DB[11525]={id=11525,zoneId=4080,name="Further Conversions",level=70,minLevel=70,giver="Vindicator Xayann",giverType="NPC",giverId=24965,ender="Vindicator Xayann",enderType="NPC",enderId=24965,poiX=12887,poiY=-6870,wowhead="https://www.wowhead.com/wotlk/quest=11525",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="My plan to replace the damaged crystals on the erratic sentries has been a success.  We've managed to take the Sun's Reach Sanctum with their help.$B$BI've crafted new crystals that will bring more of them under our control; place them inside the hulls of defeated sentries.  We'll deploy them to other locations once they're converted.",logDesc="Vindicator Xayann at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units."} end
if not DB[11526] then DB[11526]={id=11526,zoneId=4080,name="The Missing Magistrix",level=70,minLevel=70,giver="Captain Theris Dawnhearth",giverType="NPC",giverId=24967,ender="Magistrix Seyla",enderType="NPC",enderId=24937,poiX=12891,poiY=-6881,wowhead="https://www.wowhead.com/wotlk/quest=11526",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="We sent one of our operatives to investigate the fel portal in the middle of Dawning Square, south of here.  She never returned.$B$BTake this scroll we found on one of the enemy corpses.  We believe it will grant you access through the portal.  Once through, find Magistrix Seyla and aid her in any way you can.",logDesc="Use the Captured Legion Scroll near the portal at Dawning Square.  Once you've gone through the portal, find Magistrix Seyla."} end
if not DB[11527] then DB[11527]={id=11527,zoneId=495,name="Mutiny on the Mercy",level=71,minLevel=68,giver="3",giverType="NPC",giverId=24910,ender="3",enderType="NPC",enderId=24910,rewardNextId=11529,poiX=35,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=11527",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Aye, we got problems, matey. Me gunners have mutinied! M'n'the crew up top be tryin' to kick Sorlof's keester while dealin' with the mutinous gunners down'blo.$B$BYe're gonna have to go down'blo and deal with those mutinous sea dogs and take their blastin' powder for the big'un o'er on the poop deck.$B$BWith ye mannin' the big'un, Sorlof is sure to die and give up the booty!",logDesc="Captain Ellis aboard the Sister Mercy in the Howling Fjord has asked that you recover 5 Barrels of Blasting Powder from the ship's hold.$B"} end
if not DB[11528] then DB[11528]={id=11528,zoneId=-22,name="A Winter Veil Gift",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=11528",image="assets/images/quests/placeholder.png",rewards={{id=34426,qty=1}}} end
if not DB[11529] then DB[11529]={id=11529,zoneId=495,name="Sorlof's Booty",level=71,minLevel=68,giver="3",giverType="NPC",giverId=24910,ender="3",enderType="NPC",enderId=24910,rewardNextId=11530,poiX=35,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=11529",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Me crew is gonna get the big'un all primed an'ready for ya, matey. She's restin' snuggly on the bow, o'er on the other side of the ship. Go'n man it and be ready to fire when Sorlof is in our sights!$B$BOnce we take that landlubber down, ye'll have to recover the booty for us, seein' as how we can't leave the damned ship! Bring that booty back to me and ye'll get your cut - the shield...",logDesc="Slay Sorlof using the Big Gun and recover Sorlof's Booty. Return Sorlof's Booty to Captain Ellis aboard the Sister Mercy."} end
if not DB[11530] then DB[11530]={id=11530,zoneId=495,name="The Shield of the Aesirites",level=71,minLevel=68,giver="3",giverType="NPC",giverId=24910,ender="Orfus of Kamagua",enderType="NPC",enderId=23804,poiX=35,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=11530",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Here's yer shield. Me hopes it doesn't curse ye like it did me'n'me crew. Ye don't have to go home, but ye can't stay here... I be certain that thar be some that would be interested in getting' it back.$B$BNow get that thing off me ship!",logDesc="Return the Shield of the Aesirites to Orfus of Kamagua at the Ancient Lift in the Howling Fjord."} end
if not DB[11531] then DB[11531]={id=11531,zoneId=-101,name="Strange Engine Part",level=70,minLevel=55,ender="K. Lee Smallfry",enderType="NPC",enderId=17634,wowhead="https://www.wowhead.com/wotlk/quest=11531",image="assets/images/quests/placeholder.png",xpDiff=5,money=22000,desc="This strange engine part doesn't look like it fits in a steam pump, much less anything else you've seen.  Perhaps K. Lee Smallfry might know something about it.",logDesc="Take the Strange Engine Part to K. Lee Smallfry in Telredor."} end
if not DB[11532] then DB[11532]={id=11532,zoneId=4080,name="Distraction at the Dead Scar",level=70,minLevel=70,ender="Battlemage Arynna",enderType="NPC",enderId=25057,wowhead="https://www.wowhead.com/wotlk/quest=11532",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="The Legion will move against us as soon as their forces to the south are freed up.  The Scourge at the Dead Scar are keeping their forces occupied at the moment.  It won't last long, however.$B$BI want you to fly a dragonhawk over to the scar and put a dent in the demons' numbers with these arcane charges.$B$BIf all goes well, they won't even notice us taking the armory from Kael's lackeys.  Talk to Ayren, the dragonhawk master in the west part of the harbor, when you're ready to fly there.",logDesc="Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar.  Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers."} end
if not DB[11533] then DB[11533]={id=11533,zoneId=4080,name="The Air Strikes Must Continue",level=70,minLevel=70,giver="Battlemage Arynna",giverType="NPC",giverId=25057,ender="Battlemage Arynna",enderType="NPC",enderId=25057,poiX=12791,poiY=-6883,wowhead="https://www.wowhead.com/wotlk/quest=11533",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="We've taken the armory from the enemy thanks to our aerial attacks against the Legion's forces in the Dead Scar.$B$BAs a matter of fact, it's gone so well that we're going to continue our air strikes against them.  Take these arcane charges and use them against their forces.$B$BTalk to Ayren Cloudbreaker at the Sun's Reach Harbor when you're ready for flight.",logDesc="Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar.  Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers."} end
if not DB[11534] then DB[11534]={id=11534,zoneId=3703,name="Report to Nasuun",level=70,minLevel=70,giver="Tradesman Portanuus",giverType="NPC",giverId=25034,ender="Exarch Nasuun",enderType="NPC",enderId=24932,poiX=12791,poiY=-6875,wowhead="https://www.wowhead.com/wotlk/quest=11534",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I am most glad that you are here, $c! When we took this sanctum from the wretched, we hurried to create a magical portal that leads here from Shattrath City in the Outland.$B$BMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to maintain that portal. He asked me to send along any promising candidates who have what it takes to help with acquiring more energy to fuel it.$B$BPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.",logDesc="Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City."} end
if not DB[11535] then DB[11535]={id=11535,zoneId=4080,name="Making Ready",level=70,minLevel=70,ender="Smith Hauthaa",enderType="NPC",enderId=25046,wowhead="https://www.wowhead.com/wotlk/quest=11535",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Supplies are inbound, or so I'm told.$b$bRegardless, we can ill afford to wait around hoping that help arrives before our offensive stalls. We must make the best of what we have.$b$bAs for me, I need ore to fashion an anvil so I can begin to upgrade our armor and weapons.$b$bThere are a group of naga on the coast to the east of here collecting ore and placing it in chests for shipment to the Legion.$b$bRelieving them of their ore will help our efforts in more ways than one....",logDesc="Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests."} end
if not DB[11536] then DB[11536]={id=11536,zoneId=4080,name="Don't Stop Now....",level=70,minLevel=70,giver="Smith Hauthaa",giverType="NPC",giverId=25046,ender="Smith Hauthaa",enderType="NPC",enderId=25046,poiX=12664,poiY=-6985,wowhead="https://www.wowhead.com/wotlk/quest=11536",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Now that we have an anvil, I can really get to work.$b$bNo matter how many supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. We'll need a constant supply of weapons and armor if we're to be successful here.$b$bThere are a group of naga on the coast to the east of here. They're collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....",logDesc="Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests."} end
if not DB[11537] then DB[11537]={id=11537,zoneId=4080,name="The Battle Must Go On",level=70,minLevel=70,giver="Harbinger Inuuro",giverType="NPC",giverId=25061,ender="Harbinger Inuuro",enderType="NPC",enderId=25061,poiX=12791,poiY=-6887,wowhead="https://www.wowhead.com/wotlk/quest=11537",image="assets/images/quests/placeholder.png",xpDiff=4,money=44000,desc="We must continue to defeat and demoralize the armies of the Legion.$B$BThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.$B$BToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.",logDesc="Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square.  Use the Shattered Sun Banner to impale the Emissary of Hate's corpse."} end
if not DB[11538] then DB[11538]={id=11538,zoneId=4080,name="The Battle for the Sun's Reach Armory",level=70,minLevel=70,ender="Harbinger Inuuro",enderType="NPC",enderId=25061,wowhead="https://www.wowhead.com/wotlk/quest=11538",image="assets/images/quests/placeholder.png",xpDiff=4,money=44000,desc="The Burning Legion holds the Sun's Reach Armory, which is of tactical importance to our operation.  As long as their morale remains high we will not wrest the building from their control.$B$BThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.$B$BToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.",logDesc="Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square or the Sun's Reach Armory.  Use the Shattered Sun Banner to impale the Emissary of Hate's corpse."} end
if not DB[11539] then DB[11539]={id=11539,zoneId=4080,name="Taking the Harbor",level=70,minLevel=70,ender="Magister Ilastar",enderType="NPC",enderId=25069,wowhead="https://www.wowhead.com/wotlk/quest=11539",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="One of Kael's most elite forces, the Dawnblade army, has been stationed at the Sun's Reach Harbor and Dawnstar Village.$B$BThe harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help.  Kael'thas will rue the day that he turned his back on his people and sided with the Burning Legion.",logDesc="Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen."} end
if not DB[11540] then DB[11540]={id=11540,zoneId=4080,name="Crush the Dawnblade",level=70,minLevel=70,giver="Magister Ilastar",giverType="NPC",giverId=25069,ender="Magister Ilastar",enderType="NPC",enderId=25069,poiX=12673,poiY=-6943,wowhead="https://www.wowhead.com/wotlk/quest=11540",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="We've driven the Dawnblade army out of the Sun's Reach Harbor.  Sun's Reach is ours in its entirety.  Yet somehow... I'm not entirely satisfied.$B$BI want you to go to Dawnstar Village, west of here, and slay any surviving Dawnblade combatants.  They sealed their fate when they followed Kael to this place.",logDesc="Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen."} end
if not DB[11541] then DB[11541]={id=11541,zoneId=4080,name="Disrupt the Greengill Coast",level=70,minLevel=70,giver="Captain Valindria",giverType="NPC",giverId=25088,ender="Captain Valindria",enderType="NPC",enderId=25088,poiX=12809,poiY=-7091,wowhead="https://www.wowhead.com/wotlk/quest=11541",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="The naga have taken the Greengill Coast to the southeast. Their females, the Darkspine sirens, are using magic to enslave the indigenous murlocs.$B$BIt's my responsibility to see to it that whatever the naga are up to over there is disrupted. That's where you come in.$B$B$C, I want you to get the controlling orbs from the female naga and throw them near the Greengill slaves, breaking the orb and setting the murlocs free.$B$BMy guess is that the murlocs will be incensed and turn on their masters.",logDesc="Captain Valindria wants you to free 10 Greengill Slaves. Return to her onboard the Silvermoon's Pride at Sun's Reach Harbor once you have done so."} end
if not DB[11542] then DB[11542]={id=11542,zoneId=4080,name="Intercept the Reinforcements",level=70,minLevel=70,ender="Vindicator Kaalan",enderType="NPC",enderId=25108,wowhead="https://www.wowhead.com/wotlk/quest=11542",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We're making a push to solidify our control of Sun's Reach by capturing the harbor next.  Unfortunately a fleet of Dawnblade reservists is on its way to reinforce Kael's forces there.$B$BTake this oil and secure a dragonhawk from Ayren Cloudbreaker.    You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.$B$BLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.",logDesc="Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet.  Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists."} end
if not DB[11543] then DB[11543]={id=11543,zoneId=4080,name="Keeping the Enemy at Bay",level=70,minLevel=70,giver="Vindicator Kaalan",giverType="NPC",giverId=25108,ender="Vindicator Kaalan",enderType="NPC",enderId=25108,poiX=12704,poiY=-6985,wowhead="https://www.wowhead.com/wotlk/quest=11543",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We've managed to capture Sun's Reach in its entirety.  Unfortunately a fleet of Dawnblade reservists is on its way to take back the harbor.$B$BTake this oil and secure a dragonhawk from Ayren Cloudbreaker.  You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.$B$BLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.",logDesc="Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet.  Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists."} end
if not DB[11544] then DB[11544]={id=11544,zoneId=3520,name="Ata'mal Armaments",level=70,minLevel=70,giver="Smith Hauthaa",giverType="NPC",giverId=25046,ender="Smith Hauthaa",enderType="NPC",enderId=25046,poiX=12664,poiY=-6985,wowhead="https://www.wowhead.com/wotlk/quest=11544",image="assets/images/quests/placeholder.png",xpDiff=6,money=88000,desc="The Ata'mal Terrace in eastern Shadowmoon Valley is holy to the draenei, but is now overrun by fel orcs. They have dug up the special ore from that place and created corrupted weapons and armor.$B$BI need the armaments to form an alloy with the naga ore. Our anchorites have blessed my anvil with the ability to cleanse them.$B$BRetrieve the armaments from the Shadowmoon chosen, slayers and darkweavers. Return them here, breaking down and purifying them upon my anvil, and then hand me the cleansed results.",logDesc="Smith Hauthaa needs you to produce 5 Cleansed Ata'mal Metal. Do so by breaking down Ata'mal Armaments on her anvil at the Sun's Reach Armory on the Isle of Quel'Danas.",choiceRewards={{id=34538,qty=1},{id=34539,qty=1}}} end
if not DB[11545] then DB[11545]={id=11545,zoneId=4080,name="A Charitable Donation",level=70,minLevel=70,ender="Anchorite Ayuri",enderType="NPC",enderId=25112,wowhead="https://www.wowhead.com/wotlk/quest=11545",image="assets/images/quests/placeholder.png",desc="We've taken Sun's Reach from the enemy and our final victory is at hand.  The cost was high and many brave combatants gave their lives so we could achieve this.$B$BIt is my goal to ensure that those who perished in combat are not forgotten.  I ask that you take a moment to consider making a donation towards a memorial fund.  Any leftover gold will go to the widows and orphans of the fallen.",logDesc="Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold."} end
if not DB[11546] then DB[11546]={id=11546,zoneId=4080,name="Open for Business",level=70,minLevel=70,giver="Mar'nah",giverType="NPC",giverId=24975,ender="Mar'nah",enderType="NPC",enderId=24975,poiX=12848,poiY=-7015,wowhead="https://www.wowhead.com/wotlk/quest=11546",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Welcome, $n.$b$bThere are a number of ways I can assist you in your efforts here.$b$bFor example, I've recently discovered a recipe for a unique elixir.$b$bThe bloodberry grows wild in many regions of Azeroth and has long been considered nothing more than a nuisance. I've learned though, that when exposed to the Sunwell's power this plant takes on special properties that can be distilled and imbibed to magnify one's abilites.$b$bBring me a sample from the nearby bushes and I'll show you what I mean.",logDesc="Mar'nah at the Sun's Reach Harbor wants you to gather 5 Bloodberries from the bushes found on Quel'Danas.",rewards={{id=34537,qty=1}}} end
if not DB[11547] then DB[11547]={id=11547,zoneId=4080,name="Know Your Ley Lines",level=70,minLevel=70,giver="Astromancer Darnarian",giverType="NPC",giverId=25133,ender="Astromancer Darnarian",enderType="NPC",enderId=25133,poiX=12784,poiY=-6882,wowhead="https://www.wowhead.com/wotlk/quest=11547",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Freeloaders!$b$bYou all want instant gratification - never giving thought to the effort required to create even the simplest of portals.$b$bPerhaps a little education will instill a bit of gratitude for my ceaseless efforts.$b$bTake this crystal. Attune it to the Bloodcrystal to the west, at the Dawning Square portal just south of here, and at the naga shrine at Greengill Coast to the southeast.$b$bPerhaps then you'll appreciate your precious translocations....",logDesc="Astromancer Darnarian in the Sun's Reach Sanctum wants you to use the Astromancer's Crystal at the Bloodcrystal, the Dawning Square portal, and the naga shrine at Greengill Coast.",rewards={{id=35230,qty=1}}} end
if not DB[11548] then DB[11548]={id=11548,zoneId=4080,name="Your Continued Support",level=70,minLevel=70,giver="Anchorite Ayuri",giverType="NPC",giverId=25112,ender="Anchorite Ayuri",enderType="NPC",enderId=25112,poiX=12732,poiY=-6910,wowhead="https://www.wowhead.com/wotlk/quest=11548",image="assets/images/quests/placeholder.png",desc="We've built a memorial to honor those slain in battle.  It's but a small consolation to the families that lost their loved ones.$B$BI am taking up a collection to aid the orphans and spouses of our war heroes.  If you can spare a small donation it would go a long way.",logDesc="Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold."} end
if not DB[11549] then DB[11549]={id=11549,zoneId=4080,name="A Magnanimous Benefactor",level=70,minLevel=70,giver="Anchorite Kairthos",giverType="NPC",giverId=25163,ender="Anchorite Kairthos",enderType="NPC",enderId=25163,poiX=12834,poiY=-7005,wowhead="https://www.wowhead.com/wotlk/quest=11549",image="assets/images/quests/placeholder.png",desc="You've done so much for us, $N.  We greatly appreciate your assistance.$B$BYou might have noticed Anchorite Ayuri's efforts outside.  She has a big heart and is very convincing, but the donations do not quite add up to what she had expected.$B$BIf you were to make a large contribution to her cause, I will make sure that word of your deeds in this war spreads far and wide.  What do you say?",logDesc="Anchorite Kairthos wants you to donate 1000 gold to aid in Anchorite Ayuri's efforts.  You will be known as $N of the Shattered Sun if you complete this quest."} end
if not DB[11550] then DB[11550]={id=11550,zoneId=4080,name="Enter, the Deceiver...",level=70,minLevel=70,giver="General Tiras'alan",giverType="NPC",giverId=25167,ender="Archmage Ne'thul",enderType="NPC",enderId=25169,poiX=-1854,poiY=5435,wowhead="https://www.wowhead.com/wotlk/quest=11550",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Despite our best efforts, Kael'thas's sinister plans have been carried out. The Sunwell has been re-ignited in preparation for the Deceiver's arrival.$B$BThe object that stands before me and below A'dal is a representation of the current status of the Sunwell's defenses. Mighty barriers have been raised, stymieing our attacks against the inner chambers. If ever there were a time that our world needed assistance, it would be now.$B$BReport to Archmage Ne'thul at the Isle of Quel'Danas, north of Quel'Thalas.",logDesc="Report to Archmage Ne'thul on the Isle of Quel'Danas, north of Quel'Thalas.$B$BFlight masters in Ironforge and Silvermoon City will get you to your destination."} end
if not DB[11551] then DB[11551]={id=11551,zoneId=4080,name="Agamath, the First Gate",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=11551",image="assets/images/quests/placeholder.png",xpDiff=1,rewards={{id=34548,qty=1}}} end
if not DB[11552] then DB[11552]={id=11552,zoneId=4080,name="Rohendor, the Second Gate",level=70,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=11552",image="assets/images/quests/placeholder.png",xpDiff=1,rewards={{id=34548,qty=1}}} end
