if not DB[11554] then DB[11554]={id=11554,zoneId=4080,name="A Friend in the Frontlines",level=70,minLevel=70,giver="Eldara Dawnrunner",giverType="NPC",giverId=25032,ender="Eldara Dawnrunner",enderType="NPC",enderId=25032,poiX=12886,poiY=-6874,wowhead="https://www.wowhead.com/wotlk/quest=11554",image="assets/images/quests/placeholder.png",choiceRewards={{id=34583,qty=1},{id=34584,qty=1}}} end
if not DB[11555] then DB[11555]={id=11555,zoneId=4080,name="Honored by Your Allies",level=70,minLevel=70,giver="Eldara Dawnrunner",giverType="NPC",giverId=25032,ender="Eldara Dawnrunner",enderType="NPC",enderId=25032,poiX=12886,poiY=-6874,wowhead="https://www.wowhead.com/wotlk/quest=11555",image="assets/images/quests/placeholder.png",choiceRewards={{id=34587,qty=1},{id=34585,qty=1}}} end
if not DB[11556] then DB[11556]={id=11556,zoneId=4080,name="Revered in the Field of Battle",level=70,minLevel=70,giver="Eldara Dawnrunner",giverType="NPC",giverId=25032,ender="Eldara Dawnrunner",enderType="NPC",enderId=25032,poiX=12886,poiY=-6874,wowhead="https://www.wowhead.com/wotlk/quest=11556",image="assets/images/quests/placeholder.png",choiceRewards={{id=34592,qty=1},{id=34593,qty=1}}} end
if not DB[11557] then DB[11557]={id=11557,zoneId=4080,name="Exalted Among All Combatants",level=70,minLevel=70,giver="Eldara Dawnrunner",giverType="NPC",giverId=25032,ender="Eldara Dawnrunner",enderType="NPC",enderId=25032,poiX=12886,poiY=-6874,wowhead="https://www.wowhead.com/wotlk/quest=11557",image="assets/images/quests/placeholder.png",choiceRewards={{id=34595,qty=1},{id=34594,qty=1}}} end
if not DB[11558] then DB[11558]={id=11558,zoneId=-22,name="Dangerous Love",level=-1,minLevel=1,rewardNextId=8979,wowhead="https://www.wowhead.com/wotlk/quest=11558",image="assets/images/quests/placeholder.png",desc="There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.$b$bIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.$b$bFind one of our guardians and see if they've been caught up in this foolishness.",logDesc="Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity."} end
if not DB[11559] then DB[11559]={id=11559,zoneId=3537,name="Winterfin Commerce",level=71,minLevel=69,giver="King Mrgl-Mrgl",giverType="NPC",giverId=25197,ender="Ahlurglgr",enderType="NPC",enderId=25206,poiX=4361,poiY=6063,wowhead="https://www.wowhead.com/wotlk/quest=11559",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Now that you can speak with the Winterfin, it is time for you to let them get to know you. One of the best ways to do that is to conduct business with them.$B$BThe murlocs prize clams over any other object and their only surviving merchant is Ahlurglgr. If I were you, I'd collect a handful of Winterfin clams and give them to him as a gift.$B$BThe clams can be found all over down in the trench, as well as across it in the Winterfin village and their caverns.",logDesc="Collect 5 Winterfin Clams and deliver them to Ahlurglgr at Winterfin Retreat."} end
if not DB[11560] then DB[11560]={id=11560,zoneId=3537,name="Oh Noes, the Tadpoles!",level=71,minLevel=69,giver="King Mrgl-Mrgl",giverType="NPC",giverId=25197,ender="King Mrgl-Mrgl",enderType="NPC",enderId=25197,rewardNextId=11562,poiX=4361,poiY=6063,wowhead="https://www.wowhead.com/wotlk/quest=11560",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Oh good, you're back!$B$BWhen the landslide at the village across the water exposed the caverns, a malevolent lobstrok, known as Claximus, came out of the caves and stole the Winterfin tadpoles away.$B$BSomething happened to all of the murlocs that followed him in there, and when they re-emerged, they were under his control.$B$B$C, you must swim across the waters and rescue the Winterfin tadpoles in the village and caverns.$B$BThe future of the Winterfin tribe depends upon you!",logDesc="King Mrgl-Mrgl has asked you to rescue 20 Winterfin Tadpoles. Return to him at Winterfin Retreat once you have done so.",choiceRewards={{id=37034,qty=1},{id=37558,qty=1},{id=37508,qty=1},{id=37527,qty=1}}} end
if not DB[11561] then DB[11561]={id=11561,zoneId=3537,name="Them!",level=71,minLevel=69,giver="Brglmurgl",giverType="NPC",giverId=25199,ender="Brglmurgl",enderType="NPC",enderId=25199,poiX=4373,poiY=6102,wowhead="https://www.wowhead.com/wotlk/quest=11561",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Our brothers and sisters across the water are now our mortal enemies. They have kidnapped our tadpoles, driven us out of our village, and killed more of us than I can count.$B$BProve yourself, $r! Swim across the rift and slay them!$B$BDespite the favor that the new king has shown you, only then will we consider accepting you here. Fail to do so, and you might as well leave now and never return!",logDesc="Brglmurgl at Winterfin Retreat has asked you to kill 15 Winterfin murlocs. Any combination of warriors, oracles, and shorestrikers will do."} end
if not DB[11562] then DB[11562]={id=11562,zoneId=3537,name="I'm Being Blackmailed By My Cleaner",level=71,minLevel=69,giver="King Mrgl-Mrgl",giverType="NPC",giverId=25197,ender="Mrmrglmr",enderType="NPC",enderId=25205,rewardNextId=11563,poiX=4361,poiY=6063,wowhead="https://www.wowhead.com/wotlk/quest=11562",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I have something embarrassing to admit: I'm being blackmailed!$B$BMrmrglmr agreed to clean some of my things, and got hold of my spare murloc costume. He's threatening to reveal my true nature to the other murlocs.$B$BI need not explain to you what a disaster that would be! Besides, I have a plan that's going to require that we get that costume back.$B$BPlease, $N, go to Mrmrglmr at the other end of the Retreat to the north and do whatever he asks of you.",logDesc="King Mrgl-Mrgl has asked you to speak with Mrmrglmr at the northwest end of Winterfin Retreat."} end
if not DB[11563] then DB[11563]={id=11563,zoneId=3537,name="Grmmurggll Mrllggrl Glrggl!!!",level=71,minLevel=69,giver="Mrmrglmr",giverType="NPC",giverId=25205,ender="Mrmrglmr",enderType="NPC",enderId=25205,rewardNextId=11565,poiX=4407,poiY=6150,wowhead="https://www.wowhead.com/wotlk/quest=11563",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="If your pathetic little eyes were any good, you'd see that we're being slaughtered by the orcas to the north in the bay!$B$BAssuming your precious night elf king wants his spare costume back, I think you'll do me a favor and bring back the head of the king of the orcas, Glrggl: he who swims against the tides of fate -- eradicating the hope of life for all those who hear the siren song of death upon the waves!$B$BBe quick about it, $r, Winterfin murlocs are losing their lives even as we waste time talking!",logDesc="Mrmrglmr wants you to return to him at Winterfin Retreat with Glrggl's Head."} end
if not DB[11564] then DB[11564]={id=11564,zoneId=3537,name="Succulent Orca Stew",level=71,minLevel=69,giver="Cleaver Bmurglbrm",giverType="NPC",giverId=25211,ender="Cleaver Bmurglbrm",enderType="NPC",enderId=25211,poiX=4392,poiY=6148,wowhead="https://www.wowhead.com/wotlk/quest=11564",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Word is, strange $r, that you might be going after the king of the orcas, Glrggl.$B$BThat's all fine and good, but if you want to taste the stew that makes life worth living, then you'll bring me back the succulent blubber of the orcas that swim in Glimmer Bay.$B$BHurry... I have quite a bit of cutting to do on this carcass if you want to reap the benefits of your efforts.",logDesc="Cleaver Bmurglbrm has tasked you with acquiring 7 Succulent Orca Blubber. Return with them to him at Winterfin Retreat.",rewards={{id=39691,qty=20}}} end
if not DB[11565] then DB[11565]={id=11565,zoneId=3537,name="The Spare Suit",level=71,minLevel=69,giver="Mrmrglmr",giverType="NPC",giverId=25205,ender="King Mrgl-Mrgl",enderType="NPC",enderId=25197,rewardNextId=11566,poiX=4407,poiY=6150,wowhead="https://www.wowhead.com/wotlk/quest=11565",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Very well, your king's secret is safe with me as long as he continues to help us against our enemies.$B$BHere, take this to him. I cleaned it up nicely, though I have no idea why he needs a second disguise.$B$BMaybe he has something in mind for you?",logDesc="Return King Mrgl-Mrgl's Spare Suit to him at Winterfin Retreat."} end
if not DB[11566] then DB[11566]={id=11566,zoneId=3537,name="Surrender... Not!",level=72,minLevel=69,giver="King Mrgl-Mrgl",giverType="NPC",giverId=25197,ender="King Mrgl-Mrgl",enderType="NPC",enderId=25197,poiX=4361,poiY=6063,wowhead="https://www.wowhead.com/wotlk/quest=11566",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="The time has come to put an end to this unnatural situation, $N. For the Winterfin murlocs to have a chance at a future, Claximus must die!$B$BI want you to take my spare murloc suit and enter the Winterfin Caverns under the pretext of surrender. With the white flag in hand, the murlocs won't attack you.$B$BYou'll find him in the southwestern most corner of the caverns. Once you get close enough, deal with Claximus. Bring me one of his claws as proof that the grisly deed has been done.",logDesc="King Mrgl-Mrgl at Winterfin Retreat has asked you to bring him a Claw of Claximus.",choiceRewards={{id=37215,qty=1},{id=37392,qty=1},{id=37426,qty=1},{id=37506,qty=1}}} end
if not DB[11567] then DB[11567]={id=11567,zoneId=495,name="The Ancient Armor of the Kvaldir",level=71,minLevel=68,giver="\"Silvermoon\" Harry",giverType="NPC",giverId=24539,ender="Orfus of Kamagua",enderType="NPC",enderId=23804,poiX=-146,poiY=-3520,wowhead="https://www.wowhead.com/wotlk/quest=11567",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I was on the vessel that was bringing in the armor. We'd just boarded the ship and were headin' back here when we were attacked by a Forsaken destroyer.$B$BThey boarded our ship, took all the booty for themselves, and then sunk her.$B$BThat was the last I'd seen of that armor. If you want, you can take my bomber from Scalawag to the dreaded isle that the destroyer be docked. Talk to my woman, Alanya, outside. She'll get you on the bomber.$B$BIf you manage to find the stuff, don't you dare bring it back!",logDesc="Recover the Ancient Armor of the Kvaldir and deliver it to Orfus of Kamagua in the Howling Fjord."} end
if not DB[11568] then DB[11568]={id=11568,zoneId=495,name="A Return to Resting",level=71,minLevel=68,giver="Orfus of Kamagua",giverType="NPC",giverId=23804,ender="Orfus of Kamagua",enderType="NPC",enderId=23804,rewardNextId=11572,poiX=688,poiY=-3834,wowhead="https://www.wowhead.com/wotlk/quest=11568",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Orfus hands you a satchel.>$B$BWithin this satchel are the artifacts that you recovered. Locate the burial mounds of Shield Hill, far to the southeast, where the items were originally stolen from and return the artifacts. It is my hope that this gesture will quell the spirits that now haunt our hunting grounds.$B$BBe strong, $N...",logDesc="Use the Bundle of Vrykul Artifacts at the ransacked burial mounds of Shield Hill to return the Frozen Heart of Isuldof, the Shield of the Aesirites, the Staff of Storm's Fury and the Ancient Armor of the Kvaldir.$B$BReturn to Orfus of Kamagua at the Ancient Lift should you succeed."} end
if not DB[11569] then DB[11569]={id=11569,zoneId=3537,name="Keymaster Urmgrgl",level=71,minLevel=69,giver="Glrglrglr",giverType="NPC",giverId=28375,ender="Glrglrglr",enderType="NPC",enderId=28375,poiX=4005,poiY=6389,wowhead="https://www.wowhead.com/wotlk/quest=11569",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I have to get out of these caverns! There's magic stuff seeping in from Coldarra, above, and affecting everyone's minds.$B$BI don't intend to be controlled like these others!$B$BKeymaster Urmgrgl is in the cave below and to the south. He holds the key to my cage. Get it from him and bring it back so that I can unlock my cage and get out of here.$B$BHurry!",logDesc="Glrglrglr inside the Winterfin Caverns has asked you to retrieve Urmgrgl's Key."} end
if not DB[11570] then DB[11570]={id=11570,zoneId=3537,name="Escape from the Winterfin Caverns",level=71,minLevel=69,giver="Lurgglbr",giverType="NPC",giverId=25208,ender="King Mrgl-Mrgl",enderType="NPC",enderId=25197,poiX=4013,poiY=6396,wowhead="https://www.wowhead.com/wotlk/quest=11570",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="The lock on my cage doesn't look too solid, but I'm not foolish enough to try to leave without assistance.$B$BWill you help me safely get out of these caverns? There's no time to waste, $r.$B$BWhen you get back to the retreat, please let the king know that I'm okay. He's sure to give you a reward.",logDesc="Escort Lurgglbr to safety and then report to King Mrgl-Mrgl at Winterfin Retreat with the good news.",choiceRewards={{id=37046,qty=1},{id=37044,qty=1},{id=37041,qty=1},{id=37036,qty=1},{id=37039,qty=1},{id=37042,qty=1}}} end
if not DB[11571] then DB[11571]={id=11571,zoneId=3537,name="Learning to Communicate",level=71,minLevel=69,giver="King Mrgl-Mrgl",giverType="NPC",giverId=25197,ender="King Mrgl-Mrgl",enderType="NPC",enderId=25197,rewardNextId=11559,poiX=4361,poiY=6063,wowhead="https://www.wowhead.com/wotlk/quest=11571",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="To help, you must learn how to speak the Winterfin dialect. We'll work with the forces of nature and magic to do that.$B$BTake this empty conch shell. At the bottom of the watery trench below exists Scalder, an elemental of air and watery fury.$B$BOnce she is defeated, use the conch upon her remains to capture her magical steam. Return the full conch to me, and I'll imbue my knowledge of the Winterfin tongue into you.$B$BLuckily, a friend taught me a water breathing spell, which I will cast upon you.",logDesc="King Mrgl-Mrgl has given you a conch to use upon Scalder's remains. Return The King's Filled Conch to him at Winterfin Retreat."} end
if not DB[11572] then DB[11572]={id=11572,zoneId=495,name="Return to Atuik",level=71,minLevel=68,giver="Orfus of Kamagua",giverType="NPC",giverId=23804,ender="Elder Atuik",enderType="NPC",enderId=24755,poiX=688,poiY=-3834,wowhead="https://www.wowhead.com/wotlk/quest=11572",image="assets/images/quests/placeholder.png",xpDiff=7,money=141000,desc="Return to Elder Atuik at Kamagua. He and the rest of my people must be warned of this impending doom that approaches from the sea.$B$B<Orfus shivers.>$B$BUse the Ancient Lift to reach him. Please hurry!",logDesc="Deliver the bad news to Elder Atuik at Kamagua.",choiceRewards={{id=36874,qty=1},{id=36872,qty=1},{id=36871,qty=1}}} end
if not DB[11573] then DB[11573]={id=11573,zoneId=495,name="Orfus of Kamagua",level=71,minLevel=68,giver="Lunk-tusk",giverType="NPC",giverId=25233,ender="Orfus of Kamagua",enderType="NPC",enderId=23804,rewardNextId=11504,poiX=1231,poiY=-3349,wowhead="https://www.wowhead.com/wotlk/quest=11573",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hail, traveler. I am Lunk-tusk of the Kalu'ak. We are known as tuskarr to your people. My partner and I were recently sent up to investigate strange happenings along one of our hunting trails. It was when we approached the graveyard known as Shield Hill that we were attacked by the undead. I was lucky to make it to this camp, but I am uncertain as to what became of Orfus.$B$BWe parted ways at the Ancient Lift, southeast of here along the cliff edge. Will you go see if he is ok?",logDesc="Find Orfus of Kamagua at the Ancient Lift in Howling Fjord."} end
if not DB[11574] then DB[11574]={id=11574,zoneId=3537,name="Too Close For Comfort",level=71,minLevel=69,giver="Endorah",giverType="NPC",giverId=25247,ender="Librarian Donathan",enderType="NPC",enderId=25262,rewardNextId=11587,poiX=2794,poiY=6165,wowhead="https://www.wowhead.com/wotlk/quest=11574",image="assets/images/quests/placeholder.png",xpDiff=3,money=24000,desc="I told them all that I remember. Why don't they believe me?$b$bI was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts - I was surrounded!$b$bA magical box appeared above me, opened up and pulled me inside. Just as it began to close around me, my rescuers swooped in on the backs of red drakes. It was breathtaking!$b$bI never thanked them for saving me. Please, $c, find them, and pass on my gratitude.",logDesc="Endorah wants you to go to Amber Ledge north of Warsong Hold and thank those there for rescuing her."} end
if not DB[11575] then DB[11575]={id=11575,zoneId=3537,name="Nick of Time",level=71,minLevel=69,giver="Midge",giverType="NPC",giverId=25249,ender="Librarian Donathan",enderType="NPC",enderId=25262,rewardNextId=11587,poiX=2292,poiY=5204,wowhead="https://www.wowhead.com/wotlk/quest=11575",image="assets/images/quests/placeholder.png",xpDiff=3,money=24000,desc="I told them all that I remember. Why don't they believe me?$b$bI was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts. I was surrounded!$b$bA huge magical cube appeared above me. It opened up and pulled me inside. I swear it's true!$b$bJust as it began to close around me, my rescuers swooped in on the backs of drakes - It was amazing! My captors scattered and I was able to escape.$b$bI never thanked them for saving me. Please, $c, if you see them, pass on my gratitude.",logDesc="Midge in Valiance Keep wants you to go to Amber Ledge to the north and thank those there for rescuing her."} end
if not DB[11576] then DB[11576]={id=11576,zoneId=3537,name="Monitoring the Rift: Cleftcliff Anomaly",level=71,minLevel=69,giver="Librarian Garren",giverType="NPC",giverId=25291,ender="Librarian Garren",enderType="NPC",enderId=25291,rewardNextId=11582,poiX=3615,poiY=5978,wowhead="https://www.wowhead.com/wotlk/quest=11576",image="assets/images/quests/placeholder.png",xpDiff=4,money=37000,desc="Greetings, $r. I am Garren of Dalaran.$b$bNot long ago, the rift was a peaceful place - geothermally speaking at least.$b$bRecently though, earthquakes have occurred with alarming frequency and scars in the earth have appeared, exposing unique energy fields of chaotic power.$b$bMy mission here is to chart and monitor these anomalies. My instruments indicate that another has appeared on the cliff face to the southwest.$b$bTake this device with you and use it when you locate the new disruption.",logDesc="Garren on Amber Ledge wants you to use the Arcanometer at the Cleftcliff Anomaly."} end
if not DB[11577] then DB[11577]={id=11577,zoneId=0,name="WoW Collector's Edition: - DEM - E - FLAG",level=1,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=11577",image="assets/images/quests/placeholder.png"} end
