if not DB[11582] then DB[11582]={id=11582,zoneId=3537,name="Monitoring the Rift: Sundered Chasm",level=71,minLevel=69,giver="Librarian Garren",giverType="NPC",giverId=25291,ender="Librarian Garren",enderType="NPC",enderId=25291,rewardNextId=12728,poiX=3615,poiY=5978,wowhead="https://www.wowhead.com/wotlk/quest=11582",image="assets/images/quests/placeholder.png",xpDiff=4,money=37000,desc="Did you feel that?! That was just an aftershock... you should've been here a few minutes ago!$b$bI'm afraid I must call upon your services again. My instruments indicate that there is an immense disruption just west of here, far beneath the water's surface.$b$bJust as before, I need you to take the arcanometer and capture the anomaly's data.$b$bI'll cast a spell that will enable you to breathe underwater. If it wears off before you find it, come let me know and I'll renew its effects.",logDesc="Garren at Amber Ledge wants you to use the Arcanometer at the Sundered Chasm anomaly and return to him with the readings."} end
if not DB[11583] then DB[11583]={id=11583,zoneId=-22,name="Honor the Flame",level=-1,minLevel=1,ender="Westfall Flame Warden",enderType="NPC",enderId=25910,wowhead="https://www.wowhead.com/wotlk/quest=11583",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,rewards={{id=23247,qty=5}}} end
if not DB[11584] then DB[11584]={id=11584,zoneId=-22,name="Honor the Flame",level=-1,minLevel=1,ender="Silverpine Forest Flame Keeper",enderType="NPC",enderId=25939,wowhead="https://www.wowhead.com/wotlk/quest=11584",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,rewards={{id=23247,qty=5}}} end
if not DB[11585] then DB[11585]={id=11585,zoneId=3537,name="Hellscream's Vigil",level=71,minLevel=68,giver="Warsong Recruitment Officer",giverType="NPC",giverId=25273,ender="Garrosh Hellscream",enderType="NPC",enderId=25237,poiX=2759,poiY=6092,wowhead="https://www.wowhead.com/wotlk/quest=11585",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Throm-Ka, $r! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty!$B$BThis impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed!$B$BGarrosh awaits your arrival below.$B$BLok'tar ogar!",logDesc="Speak with Garrosh Hellscream in Warsong Hold."} end
if not DB[11586] then DB[11586]={id=11586,zoneId=3537,name="Hellscream's Vigil",level=71,minLevel=68,giver="Warsong Recruitment Officer",giverType="NPC",giverId=25273,ender="Garrosh Hellscream",enderType="NPC",enderId=25237,poiX=2759,poiY=6092,wowhead="https://www.wowhead.com/wotlk/quest=11586",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Throm-Ka, $r! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty!$B$BThis impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed!$B$BGarrosh awaits your arrival below.$B$BLok'tar ogar!",logDesc="Speak with Garrosh Hellscream in Warsong Hold."} end
if not DB[11587] then DB[11587]={id=11587,zoneId=3537,name="Prison Break",level=71,minLevel=69,giver="Librarian Donathan",giverType="NPC",giverId=25262,ender="Librarian Donathan",enderType="NPC",enderId=25262,rewardNextId=11590,poiX=3616,poiY=5961,wowhead="https://www.wowhead.com/wotlk/quest=11587",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Greetings, $c. I am Donathan, a loyal representative of Dalaran.$b$bForgive my abruptness, but we find ourselves in the midst of a crisis. Mages all across Azeroth are being abducted and I have been authorized to conscript anyone able to assist in the unraveling of this mystery.$b$bThe camp just south of ours is where our investigation begins. I call upon you to rescue one of the imprisoned mages held there. You must obtain a key from one of the mage hunters and use it to open an arcane prison.",logDesc="Librarian Donathan on Amber Ledge wants you to collect the Beryl Prison Key from one of the Beryl Mage Hunters at Beryl Point and use it to release a trapped mage from an arcane prison."} end
if not DB[11588] then DB[11588]={id=11588,zoneId=0,name="REUSE",level=70,minLevel=65,wowhead="https://www.wowhead.com/wotlk/quest=11588",image="assets/images/quests/placeholder.png",desc="Stop Ahune from coming to Azeroth and inciting an elemental war!",logDesc="Destroy the elemental Ahune within Blackfathom Deeps."} end
if not DB[11589] then DB[11589]={id=11589,zoneId=0,name="REUSE",level=70,minLevel=65,wowhead="https://www.wowhead.com/wotlk/quest=11589",image="assets/images/quests/placeholder.png",desc="Stop Ahune from coming to Azeroth and inciting an elemental war!",logDesc="Destroy the elemental Ahune within Blackfathom Deeps."} end
if not DB[11590] then DB[11590]={id=11590,zoneId=3537,name="Abduction",level=71,minLevel=69,giver="Librarian Donathan",giverType="NPC",giverId=25262,ender="Librarian Donathan",enderType="NPC",enderId=25262,rewardNextId=11646,poiX=3616,poiY=5961,wowhead="https://www.wowhead.com/wotlk/quest=11590",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="$n, we have a situation.$b$bI've just learned that one of our archmages en route from Dalaran has gone missing. Naturally, we suspect the mage hunters are behind her disappearance.$b$bTime is clearly of the essence. We must know what has become of Lady Evanor at once if we are to have any hope of rescuing her.$b$bTake this device. Return to Beryl Point and use it on a Beryl sorcerer when he is near death. It should bind him long enough for you to bring him here for questioning.",logDesc="Donathan wants you to use the Arcane Binder on a wounded Beryl Sorcerer at Beryl Point and return to Amber Ledge with him."} end
if not DB[11591] then DB[11591]={id=11591,zoneId=3537,name="Report to Steeljaw's Caravan",level=71,minLevel=68,giver="Overlord Bor'gorok",giverType="NPC",giverId=25326,ender="Grunt Ragefist",enderType="NPC",enderId=25336,poiX=4491,poiY=5710,wowhead="https://www.wowhead.com/wotlk/quest=11591",image="assets/images/quests/placeholder.png",xpDiff=1,desc="That dimwitted cur, Steeljaw, tried to take our caravan of supplies on a shortcut through a taunka graveyard!$B$BWe just struck up relations with them!$B$BNow the caravan lies in ruins, overrun by the taunka spirits that rose out of their graves as he was trampling them.$B$BHead south and see if you can salvage the situation, $c. I sent Grunt Ragefist and a few others down there with him to help out.$B$BWhy don't you see if you can lend a hand.",logDesc="Speak with Grunt Ragefist at Steeljaw's Caravan."} end
if not DB[11592] then DB[11592]={id=11592,zoneId=3537,name="We Strike!",level=72,minLevel=68,giver="Longrunner Proudhoof",giverType="NPC",giverId=25335,ender="Overlord Bor'gorok",enderType="NPC",enderId=25326,poiX=4138,poiY=5785,wowhead="https://www.wowhead.com/wotlk/quest=11592",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="One of your orcs named Steeljaw tried to save some time by taking a shortcut through our burial grounds. This had better not be how your Horde normally acts, $r, or you will find the taunka to be the end of you!$B$BBut, you look as if you want to help fix this situation. Good!$B$BSteeljaw's cursed spirit now haunts this place and disturbs the remains of my ancestors. We must put an end to him!$B$BIf we live through this, tell your Overlord Bor'gorok at the outpost to the north.$B$BAre you with me?",logDesc="Help Longrunner Proudhoof and his Warsong raiders to survive the assault upon Steeljaw's Caravan and finish off the spirit of Force-Commander Steeljaw.$B$BIf successful, report to Overlord Bor'gorok at Bor'gorok Outpost.",choiceRewards={{id=37271,qty=1},{id=37393,qty=1},{id=37425,qty=1},{id=37557,qty=1}}} end
if not DB[11593] then DB[11593]={id=11593,zoneId=3537,name="The Honored Dead",level=71,minLevel=68,giver="Grunt Ragefist",giverType="NPC",giverId=25336,ender="Grunt Ragefist",enderType="NPC",enderId=25336,poiX=4139,poiY=5780,wowhead="https://www.wowhead.com/wotlk/quest=11593",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Our fallen deserve a hero's funeral, but we cannot bury them here on sacred taunka ground.$B$BI'll not ask you to drag their bodies back here, but take this and head further into the cemetary.  When you come across our dead caravan guards and workers, put them to the torch.$B$BHonor our dead, $c!",logDesc="Grunt Ragefist at Steeljaw's Caravan has asked you to use Ragefist's Torch to burn any combination of 10 Dead Carvan Guards and Workers."} end
if not DB[11594] then DB[11594]={id=11594,zoneId=3537,name="Put Them to Rest",level=71,minLevel=68,giver="Grunt Ragefist",giverType="NPC",giverId=25336,ender="Grunt Ragefist",enderType="NPC",enderId=25336,poiX=4139,poiY=5780,wowhead="https://www.wowhead.com/wotlk/quest=11594",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Force-Commander Steeljaw's idiocy caused this mess. What was he thinking taking a caravan through a taunka burial mound?$B$BStill, what's done is done. Now it is up to us to deal with the consequences.$B$BOverlord Bor'gorok asked me to help Longrunner Proudhoof in any way that I can. The longrunner has asked that we lay to rest the spirits of his ancestors.$B$BWhat do you say, $c? Are you $g man : strong; enough to handle such a simple task?",logDesc="Put 20 taunka spirits, either Ghostly Sages or Risen Longrunners, to rest and then report back to Grunt Ragefist at Steeljaw's Caravan."} end
if not DB[11595] then DB[11595]={id=11595,zoneId=3537,name="The Defense of Warsong Hold",level=71,minLevel=68,giver="High Overlord Saurfang",giverType="NPC",giverId=25256,ender="Overlord Razgor",enderType="NPC",enderId=25279,rewardNextId=11598,poiX=2835,poiY=6182,wowhead="https://www.wowhead.com/wotlk/quest=11595",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hellscream has the weight of the Horde upon his shoulders. Do not be dissuaded from your duties because of his temperament, $N.$B$B<Saurfang nods.>$B$BDid you think that I would forget the name of a hero of Orgrimmar? It is not every day that I have the pleasure of putting the head of Nefarian on a pike!$B$BThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.",logDesc="Report to Overlord Razgor at the hut on the south side of Warsong Hold."} end
if not DB[11596] then DB[11596]={id=11596,zoneId=3537,name="The Defense of Warsong Hold",level=71,minLevel=68,giver="High Overlord Saurfang",giverType="NPC",giverId=25256,ender="Overlord Razgor",enderType="NPC",enderId=25279,rewardNextId=11598,poiX=2835,poiY=6182,wowhead="https://www.wowhead.com/wotlk/quest=11596",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Do not let Hellscream dissuade you from your duties as a soldier of the Horde, $r. He bears a terrible burden in these frozen wastes, with the outcome of his charge resulting in victory over the Scourge or the extinction of all life on Azeroth. It is for this reason that we require your strength and wisdom.$B$BThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.",logDesc="Report to Overlord Razgor at the hut on the south side of Warsong Hold."} end
if not DB[11597] then DB[11597]={id=11597,zoneId=3537,name="The Defense of Warsong Hold",level=71,minLevel=68,giver="High Overlord Saurfang",giverType="NPC",giverId=25256,ender="Overlord Razgor",enderType="NPC",enderId=25279,rewardNextId=11598,poiX=2835,poiY=6182,wowhead="https://www.wowhead.com/wotlk/quest=11597",image="assets/images/quests/placeholder.png",xpDiff=1,desc="It seems that we always meet in the direst of circumstances, Scarab Lord. Were you not saving the world from certain destruction the last time we met?$B$B<Saurfang chuckles.>$B$BYour assistance is most welcome in Northrend, despite what the young chieftain might say.$B$BIf we had even a dozen more soldiers with your power, we would be sitting in Orgrimmar right now, hunched over a warm fire.$B$BReport to Overlord Razgor, right outside the main entry to Warsong Hold, to the south.",logDesc="Report to Overlord Razgor at the hut on the south side of Warsong Hold."} end
if not DB[11598] then DB[11598]={id=11598,zoneId=3537,name="Taking Back Mightstone Quarry",level=71,minLevel=68,giver="Overlord Razgor",giverType="NPC",giverId=25279,ender="Overlord Razgor",enderType="NPC",enderId=25279,rewardNextId=11602,poiX=2785,poiY=6081,wowhead="https://www.wowhead.com/wotlk/quest=11598",image="assets/images/quests/placeholder.png",xpDiff=5,desc="While Warsong is protected by 10 feet of steel and stone on all sides, this quarry is soft and primed for attacks by the Nerubians.$B$B<Razgor points west.>$B$BBeyond this quarry stand thousands of Scourge, awaiting orders to attack. Should the Nerubians take down our inner defenses, we will be overrun by the undead legions of Arthas.$B$BWe can't let that happen - which is why you're going on the offensive and slaughtering the Nerubians in the quarry.$B$BBlood and thunder, soldier! Take 'em both with you.",logDesc="Overlord Razgor at Warsong Hold wants you to kill 15 Nerub'ar Nerubians."} end
if not DB[11599] then DB[11599]={id=11599,zoneId=3537,name="Thassarian, My Brother",level=71,minLevel=68,giver="Leryssa",giverType="NPC",giverId=25251,ender="William Allerton",enderType="NPC",enderId=25385,rewardNextId=11600,poiX=2271,poiY=5184,wowhead="https://www.wowhead.com/wotlk/quest=11599",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I recently received word from William Allerton, a family friend, that my brother enlisted here in Valiance Keep on the same day he did.  Thing is... my brother's been dead for years.$B$BI sold everything I owned to come looking for Thassarian, only to be stonewalled by the local bureaucracy.  I've even been threatened with arrest if I keep snooping around.$B$BI need someone in the good graces of the higher-ups... someone like you.  If you can help me, I heard that William's stationed at the Farshire mine.",logDesc="Look for William Allerton inside the Farshire mine."} end
if not DB[11600] then DB[11600]={id=11600,zoneId=3537,name="The Late William Allerton",level=71,minLevel=68,giver="William Allerton",giverType="NPC",giverId=25385,ender="Leryssa",enderType="NPC",enderId=25251,rewardNextId=11601,poiX=2768,poiY=5340,wowhead="https://www.wowhead.com/wotlk/quest=11600",image="assets/images/quests/placeholder.png",xpDiff=4,desc="William's neck has been cut by a sharp object.$B$BFurther inspection reveals a single clue to bring to Leryssa - an enlistment card bearing the name of William Allerton.",logDesc="Bring the Enlistment Card to Leryssa at Valiance Keep in Borean Tundra.",choiceRewards={{id=37207,qty=1},{id=37418,qty=1},{id=37556,qty=1},{id=37483,qty=1}}} end
if not DB[11601] then DB[11601]={id=11601,zoneId=3537,name="Lost and Found",level=71,minLevel=68,giver="Leryssa",giverType="NPC",giverId=25251,ender="James Deacon",enderType="NPC",enderId=25245,rewardNextId=11603,poiX=2271,poiY=5184,wowhead="https://www.wowhead.com/wotlk/quest=11601",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Poor Mr. Allerton might yet help us find my brother.$B$B<Leryssa unveils a voluminous book, not unlike an army recruitment ledger.>$B$BI borrowed it, ok?  Let's see, does that enlistment card have a date?$B$BWilliam saw Thassarian at the enlistment line.  Their entries must be near each other... here it is!$B$BHe was assigned to... Unit S?  All the other military units are named after Alliance towns.$B$BWho's in the unit?  Where are they deployed?  We need rumors.  See if the innkeeper's heard anything.",logDesc="Speak to James Deacon at the inn in Valiance Keep."} end
if not DB[11602] then DB[11602]={id=11602,zoneId=3537,name="Cutting Off the Source",level=71,minLevel=68,giver="Overlord Razgor",giverType="NPC",giverId=25279,ender="Overlord Razgor",enderType="NPC",enderId=25279,rewardNextId=11634,poiX=2785,poiY=6081,wowhead="https://www.wowhead.com/wotlk/quest=11602",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Aerial reconnaissance of the quarry reports that the Nerubians are storing their eggs on the scaffolding surrounding the base. Smart beasts these are... They're keeping the eggs high and dry, away from the epicenter of conflict.$B$BYou're going to have to go back out there and track down their eggs. Find 'em, smash 'em, and trash 'em.$B$BEach egg destroyed means twenty less Nerubians feeding on our corpses.$B",logDesc="Overlord Razgor at Warsong Hold wants you to destroy 10 Nerub'ar Egg Sacs.",choiceRewards={{id=36883,qty=1},{id=36882,qty=1},{id=36878,qty=1},{id=36881,qty=1},{id=36879,qty=1},{id=36880,qty=1}}} end
if not DB[11603] then DB[11603]={id=11603,zoneId=3537,name="In Wine, Truth",level=71,minLevel=68,giver="James Deacon",giverType="NPC",giverId=25245,ender="Old Man Colburn",enderType="NPC",enderId=25302,rewardNextId=11604,poiX=2282,poiY=5211,wowhead="https://www.wowhead.com/wotlk/quest=11603",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The military was all that old man Colburn had.  After he retired, he still clung to it like a lifeline.$B$BHe knows the name of every general, unit, brigade, detachment... you name it.  He's the man you need.$B$BProblem is, his mind is scarred.  He won't talk to anyone unless he gets his Kul Tiras wine.  Takes him back to the times he was a marine.$B$BI haven't received a shipment in months.  The last merchant ship out of Kul Tiras sunk northeast of here.  See if you can salvage a bottle to bring Colburn.",logDesc="Salvage a bottle of Kul Tiras Wine from the underwater shipwreck northeast of Valiance Keep and bring it to Old Man Colburn in the Valiance Keep inn.",rewards={{id=40042,qty=5}}} end
if not DB[11604] then DB[11604]={id=11604,zoneId=3537,name="A Deserter",level=71,minLevel=68,giver="Old Man Colburn",giverType="NPC",giverId=25302,ender="Private Brau",enderType="NPC",enderId=25395,rewardNextId=11932,poiX=2281,poiY=5197,wowhead="https://www.wowhead.com/wotlk/quest=11604",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Unit S... Unit S.... hmmmpph.... don't make any sense... it oughta be named after a town...$B$BDarkshire was sent to Dragonblight.  The Goldshire boys were sent to the Fjord.   Where did I hear...$B$BOh, yes... the deserter!  There's a turn-tail in the barracks prison.  Got thrown in not too long ago.  Kept saying that \"S\" stood for suicide.$B$BLook for the deserter.  He might have some information for you.",logDesc="Find the prison inside Inner Hold in Valiance Keep and speak to the deserter."} end
if not DB[11605] then DB[11605]={id=11605,zoneId=3537,name="The Honored Ancestors",level=72,minLevel=68,rewardNextId=11607,wowhead="https://www.wowhead.com/wotlk/quest=11605",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="<A distant voice echoes in your head as you regard the stone statue.>$B$BDo not be startled, stranger. I am Elder Atkanok, an ancient ancestor of the tuskarr people, a skilled craftsman in my own time and the guardian of this quarry for centuries.$B$BThe quarry has been overrun, leaving many statues unfinished while the ancestors' spirits wander the world. Will you aid me in righting this wrong?$B$BFirst, I must know the names of these wandering ancestors. Look for the markers near their statues.",logDesc="Elder Atkanok outside Coldrock Quarry wants you to identify the statues of Elder Kesuk, Elder Sagani, and Elder Takret."} end
if not DB[11606] then DB[11606]={id=11606,zoneId=3537,name="Patience is a Virtue that We Don't Need",level=71,minLevel=68,giver="Quartermaster Holgoth",giverType="NPC",giverId=25327,ender="Quartermaster Holgoth",enderType="NPC",enderId=25327,rewardNextId=11608,poiX=2770,poiY=6073,wowhead="https://www.wowhead.com/wotlk/quest=11606",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We can kill all the Nerubians that we see and destroy all the eggs that we find, but those things won't stop coming until we blow their tunnels and passageways up. Of course, we can't do that without some heavy grade munitions. Unfortunately, most of our stockpile is being used up by the goblins and blacksmiths for our siege tanks and weaponry.$B$BWe do happen to have a pretty good supply of the stuff out in Mightstone Quarry - underneath all the Nerubian crap. You'll just have to go out and get it for me.",logDesc="Quartermaster Holgoth at Warsong Hold wants you to recover 15 crates of Warsong Munitions."} end
if not DB[11607] then DB[11607]={id=11607,zoneId=3537,name="The Lost Spirits",level=72,minLevel=68,rewardNextId=11609,wowhead="https://www.wowhead.com/wotlk/quest=11607",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="In the attack on the quarry, the shaman and craftsmen working here were slain. The violence threw the spirit world into utter chaos and we'll be unable to guide the ancestors home unless we find a way to soothe the spirits of the murdered.$B$BThe aggressors themselves pay no heed to the spirits, but their companions, the beryl hounds, sense the spirits and hold them in thrall.$B$BKill the beryl hounds, and using the raw energy left behind, break the imprisonment of the spirits of the innocent.",logDesc="Elder Atkanok, on the outskirts of Coldrock Quarry, wants you to free the spirits of 3 Kaskala Craftsmen and 3 Kaskala Shaman."} end
if not DB[11608] then DB[11608]={id=11608,zoneId=3537,name="Bury Those Cockroaches!",level=71,minLevel=68,giver="Quartermaster Holgoth",giverType="NPC",giverId=25327,ender="Quartermaster Holgoth",enderType="NPC",enderId=25327,poiX=2770,poiY=6073,wowhead="https://www.wowhead.com/wotlk/quest=11608",image="assets/images/quests/placeholder.png",xpDiff=5,desc="North, south, east and west. Those are the locations that you should be concerned about. Surrounding this fortress, within Mightstone Quarry, are four perfectly situated Nerub'ar sinkholes.$B$B<Holgoth hands you a bundle.>$B$BBe very careful with that package, $N. Mishandle it and you'll be dog meat.$B$BInside the bundle are seaforium depth charges. Get to each of those Nerub'ar sinkholes and plant a depth charge at their center point. If all goes well, the tunnels will collapse.$B$BGet a move on!",logDesc="Quartermaster Holgoth at Warsong Hold wants you to use the Seaforium Depth Charge Bundle to destroy the Nerub'ar sinkholes to the south, east, west and north of Warsong Hold.",choiceRewards={{id=36888,qty=1},{id=36937,qty=1},{id=36938,qty=1},{id=37555,qty=1}}} end
if not DB[11609] then DB[11609]={id=11609,zoneId=3537,name="Picking Up the Pieces",level=72,minLevel=68,rewardNextId=11610,wowhead="https://www.wowhead.com/wotlk/quest=11609",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="With the spirits of the murdered craftsmen and shaman at rest, the way is clear for us to complete the ceremonies interrupted by the attack. You must perform a role traditionally reserved for a tuskarr shaman, and you must possess all the necessary ritual items.$B$BThere is no time to craft new ones, so you will need to scour the quarry for those left by the victims of the attack. Handle these objects with care, $N, for some are centuries old. You may need to wrest them from the hands of the invaders.",logDesc="Bring 6 Tuskarr Ritual Objects to Elder Atkanok, who stands outside Coldrock Quarry."} end
if not DB[11610] then DB[11610]={id=11610,zoneId=3537,name="Leading the Ancestors Home",level=72,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=11610",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="With your help, the ancestor spirits can now be guided to their rightful homes, the statues lovingly prepared by Kaskala's craftsmen and shaman.$B$BThe ceremonies for these ancestors were interrupted during the attack on the quarry, and you will need to complete them. Take with you the objects that you recovered from the quarry, stand in front of the statues with the name markers, and recite this chant.$B$B<Words in a strange language flood your head, but you have no difficulty recalling them.>",logDesc="Elder Atkanok wants you to guide the spirits of Elder Kesuk, Elder Sagani, and Elder Takret to their stone monuments.",choiceRewards={{id=37227,qty=1},{id=37548,qty=1},{id=37380,qty=1},{id=37514,qty=1}}} end
if not DB[11611] then DB[11611]={id=11611,zoneId=3537,name="Taken by the Scourge",level=71,minLevel=68,giver="Foreman Mortuus",giverType="NPC",giverId=25280,ender="Foreman Mortuus",enderType="NPC",enderId=25280,poiX=2739,poiY=6141,wowhead="https://www.wowhead.com/wotlk/quest=11611",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Mortuus sighs.>$B$BPeons... We may as well post up a sign offering the Nerub'ar a free meal.$B$BSee, the problem with a peon is that: (1) they're dumber than dirt; and (2) they're weaker than a leper gnome. Of course they're the first to be taken by the Scourge!$B$BThis puts me in a bit of a predicament, you see. Without peons, manual labor comes to a halt. No peons, no construction.$B$BFind and release my peons, $r. If they're alive, you'll find 'em spun up in webbing throughout Mightstone Quarry.$B",logDesc="Foreman Mortuus at Warsong Hold wants you to free 5 Warsong Peons.",choiceRewards={{id=37206,qty=1},{id=37403,qty=1},{id=37417,qty=1},{id=37482,qty=1}}} end
if not DB[11612] then DB[11612]={id=11612,zoneId=3537,name="Reclaiming the Quarry",level=72,minLevel=68,giver="Etaruk",giverType="NPC",giverId=25292,ender="Etaruk",enderType="NPC",enderId=25292,rewardNextId=11617,poiX=3511,poiY=5441,wowhead="https://www.wowhead.com/wotlk/quest=11612",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="You're a welcome sight, $c. My name is Etaruk, and I used to be a craftsman here at the Coldrock Quarry.$B$BMy companions and I were preparing a new set of statues for their last set of rites when we saw those mysterious blue platforms come flying over the plateau.$B$BWhen they landed, the mages they carried swarmed the quarry, murdering my fellows and plundering the quarry. If we don't stop them, they'll destroy our statues and make off with our artifacts. Will you help me defeat the invaders?",logDesc="Etaruk, camped near the entrance to the Coldrock Quarry, wants you to kill 12 Beryl Treasure Hunters."} end
if not DB[11613] then DB[11613]={id=11613,zoneId=3537,name="Karuk's Oath",level=71,minLevel=68,giver="Karuk",giverType="NPC",giverId=25435,ender="Karuk",enderType="NPC",enderId=25435,rewardNextId=11619,poiX=1996,poiY=5854,wowhead="https://www.wowhead.com/wotlk/quest=11613",image="assets/images/quests/placeholder.png",xpDiff=6,desc="They call themselves the Kvaldir.  My people have legends about them; we call them the tuk-hariq - walkers of the fog.$B$BMy village was destroyed by these giant mist-men.  Everyone I knew was slain, including my father Ariut.$B$BBy tuskarr law I must seek retribution against those who shed my kin's blood.$B$BI am but a fisherman and I've not yet passed the test of manhood... I cannot stand toe-to-toe with the vile Kvaldir.$B$BIf you were to carry out my blood duty for me, I will be in great debt to you.",logDesc="Karuk wants you to slay 6 Skadir Raiders and 5 Skadir Longboatsmen.",choiceRewards={{id=37025,qty=1},{id=37023,qty=1},{id=37024,qty=1},{id=37022,qty=1},{id=37021,qty=1},{id=37026,qty=1}}} end
if not DB[11614] then DB[11614]={id=11614,zoneId=3537,name="Untold Truths",level=71,minLevel=68,giver="Shadowstalker Barthus",giverType="NPC",giverId=25394,ender="Shadowstalker Luther",enderType="NPC",enderId=25328,rewardNextId=11615,poiX=2782,poiY=6081,wowhead="https://www.wowhead.com/wotlk/quest=11614",image="assets/images/quests/placeholder.png",xpDiff=2,desc="We are here by order of Varimathras! The mission of the Shadowstalkers is a simple one: spy. Well, spy with a little assassination on the side.$B$BOne of my best field agents has gone missing. I haven't heard from him in days, which has left me fearing the worst. No, not death! Death would be ideal. I fear he may have gone rogue... turned traitor even.$B$BHis last known location was northern Mightstone Quarry. He was gathering intelligence on the Nerubians. Find him.$B$BHe better be dead...",logDesc="Find Shadowstalker Luther in Mightstone Quarry."} end
if not DB[11615] then DB[11615]={id=11615,zoneId=3537,name="Nerub'ar Secrets",level=71,minLevel=68,giver="Shadowstalker Luther",giverType="NPC",giverId=25328,ender="Shadowstalker Barthus",enderType="NPC",enderId=25394,rewardNextId=11616,poiX=2896,poiY=6264,wowhead="https://www.wowhead.com/wotlk/quest=11615",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You skim through the pages of the book, looking for anything of importance. On the last page you discover what appears to be frantic scribbling:$B$BNecrolords. At least a dozen by my count.$B$BFarms to west being used as some sort of horrible spawning glade for Scourge.$B$BRow upon row of victims.$B$BI think they're on to me. Made a dash for the hold. I won't be captured alive.$B$BDreadvenom hemotoxin. If they decide to bite into me, they'll be in for a surprise.$B$BTake this information back to Barthus.",logDesc="Take Luther's Journal to Shadowstalker Barthus at Warsong Hold."} end
if not DB[11616] then DB[11616]={id=11616,zoneId=3537,name="Message to Hellscream",level=71,minLevel=68,giver="Shadowstalker Barthus",giverType="NPC",giverId=25394,ender="Garrosh Hellscream",enderType="NPC",enderId=25237,rewardNextId=11618,poiX=2782,poiY=6081,wowhead="https://www.wowhead.com/wotlk/quest=11616",image="assets/images/quests/placeholder.png",xpDiff=2,desc="<Barthus tears out the last page and rolls it up.>$B$BTake this to Hellscream at once! In the meantime, I'm going to send a team to scout out the farms.$B$BBe sure to tell Hellscream that we're going to need reinforcements. ",logDesc="Take Barthus's Note to Garrosh Hellscream at Warsong Hold."} end
if not DB[11617] then DB[11617]={id=11617,zoneId=3537,name="Hampering Their Escape",level=72,minLevel=68,giver="Etaruk",giverType="NPC",giverId=25292,ender="Etaruk",enderType="NPC",enderId=25292,rewardNextId=11623,poiX=3511,poiY=5441,wowhead="https://www.wowhead.com/wotlk/quest=11617",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I'm sure you've seen those blue and white platforms hovering over the quarry. They're the transportation the mage hunters used to land their forces here, and now they're loading them up with our artifacts and fragments of our statues.$B$BWe must stop them before they leave the quarry.$B$BThe small creatures digging in the quarry carry explosives. Take them and use them to destroy the three floating platforms. The leader keeps watch from a fourth, grounded platform, but we'll deal with him afterward.",logDesc="Etaruk, outside the Coldrock Quarry, wants you to destroy the North Platform, the East Platform, and the West Platform."} end
if not DB[11618] then DB[11618]={id=11618,zoneId=3537,name="Reinforcements Incoming...",level=71,minLevel=68,giver="Garrosh Hellscream",giverType="NPC",giverId=25237,ender="Shadowstalker Ickoris",enderType="NPC",enderId=25437,rewardNextId=11686,poiX=2838,poiY=6187,wowhead="https://www.wowhead.com/wotlk/quest=11618",image="assets/images/quests/placeholder.png",xpDiff=2,desc="<Hellscream shakes his head.>$B$BYou may not have noticed that we're trying to win a war here, $r. I need all available soldiers at the primary points of conflict. This means that we don't have any real soldiers to spare for these minor incursions.$B$B<Hellscream pauses to think.>$B$BIf Barthus wants reinforcements at the farm...$B$B<Hellscream claps his hands together.>$B$B...he shall have them! Report to Barthus's assassins at the farms, west of here. Let them know that reinforcements have arrived.",logDesc="Seek out Shadowstalker Ickoris at the Warsong Farms Outpost west of Warsong Hold."} end
if not DB[11619] then DB[11619]={id=11619,zoneId=3537,name="Gamel the Cruel",level=71,minLevel=68,giver="Karuk",giverType="NPC",giverId=25435,ender="Karuk",enderType="NPC",enderId=25435,poiX=1996,poiY=5854,wowhead="https://www.wowhead.com/wotlk/quest=11619",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="My own father was slain by the leader of this raiding party, Gamel the Cruel.  He has made his abode inside a cave on the beach.$B$BYou've dealt with his men already.  Finish what you've started, $N.  Avenge my father and I will share with you what little I still have.",logDesc="Karuk wants you to defeat Gamel the Cruel at Riplash Strand.",choiceRewards={{id=37209,qty=1},{id=37419,qty=1},{id=37523,qty=1},{id=37541,qty=1}}} end
if not DB[11620] then DB[11620]={id=11620,zoneId=3537,name="A Father's Words",level=71,minLevel=68,giver="Karuk",giverType="NPC",giverId=25435,ender="Veehja",enderType="NPC",enderId=25450,rewardNextId=11625,poiX=1996,poiY=5854,wowhead="https://www.wowhead.com/wotlk/quest=11620",image="assets/images/quests/placeholder.png",xpDiff=4,desc="There is someone who might shed light on this mystery, $r.  It is rumored that the Kvaldir have kept a naga priestess alive at the temple on the west side of the shore.$B$BShe will no doubt have great reason to resent her uninvited Kvaldir guests.  Perhaps my father is expecting her to cooperate with you in some way.",logDesc="Look for Veehja at the Shrine of Scales on Riplash Strand."} end
if not DB[11621] then DB[11621]={id=11621,zoneId=3537,name="The Tablet of Leviroth",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=11621",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You scour through the tablet's etchings, looking for any text you can understand.  You finally find the following fragment:$B$B\"The sons of the fog will claim a thousand souls for the one who dwells in darkest waters.  His emissary will then awake.\"$B$BKaruk might be interested in this information.",logDesc="Return to Karuk with the information you found on the tablet."} end
if not DB[11622] then DB[11622]={id=11622,zoneId=3537,name="Secrets of Riplash",level=71,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=11622",image="assets/images/quests/placeholder.png",xpDiff=4,desc="There is someone who might shed light on this mystery, $r.  It is rumored that the kvaldir have kept a handful of naga priestesses alive inside the temple.$B$BThe high priestess, Veehja, will no doubt have great reason to resent her uninvited kvaldir guests.  Perhaps she can tell you more about what the writing on the tablet means.",logDesc="Find Veehja at the ruins of Riplash in Borean Tundra."} end
if not DB[11623] then DB[11623]={id=11623,zoneId=3537,name="A Visit to the Curator",level=72,minLevel=68,giver="Etaruk",giverType="NPC",giverId=25292,ender="Etaruk",enderType="NPC",enderId=25292,poiX=3511,poiY=5441,wowhead="https://www.wowhead.com/wotlk/quest=11623",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The leader of the mage hunter forces is a fearsome creature called Curator Insivius. My people have hunted the beasts of the seas and land for countless generations, but I've never seen anything like this curator before.$B$BHe's landed one of those flying disks on the upper rim of the quarry and oversees the operation from there. $N, I can only believe the ancestors themselves sent you to my rescue and I hope you will help me drive the mage hunters from this quarry once and for all.",logDesc="Etaruk, on the outskirts of the Coldrock Quarry, wants you to kill Curator Insivius.",choiceRewards={{id=37378,qty=1},{id=37436,qty=1},{id=37521,qty=1},{id=37515,qty=1}}} end
if not DB[11624] then DB[11624]={id=11624,zoneId=3537,name="The Sky Will Know",level=71,minLevel=69,giver="Spirit Talker Snarlfang",giverType="NPC",giverId=25339,ender="Imperean",enderType="NPC",enderId=25376,rewardNextId=11627,poiX=4524,poiY=5672,wowhead="https://www.wowhead.com/wotlk/quest=11624",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I must find out what happened to my master, Farseer Grimwalker!$B$BEarlier, he was observing the magnataur at nearby Magmoth. But one of his grunts just returned, saying that the group had been crushed, and that the farseer was dragged into the depths of the place.$B$BBefore I send you on a suicide mission, I wish to consult with the spirits to learn more.$B$BThere is an air elemental known as Imperean in the ruins of Eldra'nath to the west. She is wise and may give you the information we seek.",logDesc="Speak with Imperean at the Ruins of Eldra'nath."} end
if not DB[11625] then DB[11625]={id=11625,zoneId=3537,name="The Trident of Naz'jan",level=71,minLevel=68,giver="Veehja",giverType="NPC",giverId=25450,ender="Veehja",enderType="NPC",enderId=25450,rewardNextId=11626,poiX=1803,poiY=6057,wowhead="https://www.wowhead.com/wotlk/quest=11625",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Five hundred years ago, Azshara imprisoned a being named Leviroth in the waters below.  Now these barbarians seek to undo our queen's work!$B$BThey took over our city and began to sacrifice my brethren to awaken him!  When they ran out of naga, they began to take tuskarr.  Their spirits will know no peace!$B$BI will help you, for it will go a long way towards quelling my vengeance.  Their captain, Ragnar, dwells deep inside northeastern Riplash.  He has in his possession a golden trident.  Bring it to me!",logDesc="Veehja in Riplash wants you to go to the far northeastern end of the Riplash Ruins.  Once there slay Ragnar Drakkarlund and obtain the Trident of Naz'jan from him."} end
if not DB[11626] then DB[11626]={id=11626,zoneId=3537,name="The Emissary",level=71,minLevel=68,giver="Veehja",giverType="NPC",giverId=25450,ender="Karuk",enderType="NPC",enderId=25435,poiX=1803,poiY=6057,wowhead="https://www.wowhead.com/wotlk/quest=11626",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Raj Naz'jan was the emperor of Riplash when Leviroth was imprisoned.  Azshara herself blessed his trident so it would slay the beast should it ever escape.$B$BNow you wield it, $r.  As much as it disgusts me, I will have my revenge on these barbaric giant-men.$B$BTake the trident to the depths beneath Riplash.  You will find Leviroth below an iceberg closest to northern Riplash.$B$BDrive the trident into his flesh and slay him!  Return to whomever sent you when you're done; I wish to see no more of you.",logDesc="Find Leviroth in the waters below the iceberg floating among the northern edge of Riplash Ruins.  Use the Trident of Naz'jan to slay him and return to Karuk to the north of Riplash Strand.",choiceRewards={{id=37213,qty=1},{id=37396,qty=1},{id=37423,qty=1},{id=37487,qty=1}}} end
if not DB[11627] then DB[11627]={id=11627,zoneId=3537,name="Boiling Point",level=72,minLevel=69,giver="Imperean",giverType="NPC",giverId=25376,ender="Imperean",enderType="NPC",enderId=25376,rewardNextId=11649,poiX=4538,poiY=5886,wowhead="https://www.wowhead.com/wotlk/quest=11627",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Ah, it is information that you crave: the whereabouts and condition of your 'farseer'. He did not see so far as to avoid the trouble which befell him.$B$BNevertheless, I will give you the means to acquire the knowledge. But first, you will do some things for me.$B$BNo doubt you have seen the war between fire and water to the south. Simmer keeps boiling Churn's pool, and the two have been battling for ages.$B$BGo to the Charred Rise and Blistering Pool, and convince each of them to stop their bickering.",logDesc="Imperean wants you to beat Simmer and Churn into submission.  Return to her at the Ruins of Eldra'nath when they have submitted."} end
if not DB[11628] then DB[11628]={id=11628,zoneId=3537,name="Shrouds of the Scourge",level=72,minLevel=68,giver="Chieftain Wintergale",giverType="NPC",giverId=24703,ender="Chieftain Wintergale",enderType="NPC",enderId=24703,rewardNextId=11630,poiX=3466,poiY=4196,wowhead="https://www.wowhead.com/wotlk/quest=11628",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="To the northeast looms the Temple City of En'kilah, the Scourge's seat in Borean Tundra. From behind its walls, the Scourge commander has sent his Nerubians to surround us.$B$BRemaining on the defensive would doom my people, but my advisors differ in their strategies. Durm would charge in blindly, while Sage Aeire favors stealth.$B$BThe Temple City has blighted the nearby lands and the native creatures. Aeire believes the pelts of the scourged mammoths can serve as a cloak that may hide an infiltrator.",logDesc="Chieftain Wintergale at Taunka'le Village wants you to bring him 5 Scourged Mammoth Pelts."} end
if not DB[11629] then DB[11629]={id=11629,zoneId=3537,name="Return to the Spirit Talker",level=71,minLevel=69,giver="Imperean",giverType="NPC",giverId=25376,ender="Spirit Talker Snarlfang",enderType="NPC",enderId=25339,rewardNextId=11631,poiX=4538,poiY=5886,wowhead="https://www.wowhead.com/wotlk/quest=11629",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You have done what was asked, and now I give you that which you desire.$B$BDeliver this primal to the spirit talker back at your Bor'gorok Outpost. If she is wise, she will know a ritual to gain you the information which you seek.",logDesc="Deliver Imperean's Primal to Spirit Talker Snarlfang at Bor'gorok Outpost."} end
if not DB[11630] then DB[11630]={id=11630,zoneId=3537,name="The Bad Earth",level=72,minLevel=68,giver="Chieftain Wintergale",giverType="NPC",giverId=24703,ender="Chieftain Wintergale",enderType="NPC",enderId=24703,rewardNextId=11633,poiX=3466,poiY=4196,wowhead="https://www.wowhead.com/wotlk/quest=11630",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="By curing the hides with the blighted earth outside the Temple City, Sage Aeire believes she can create a cloak which will cause most of the Scourge minions to ignore your presence. You should blend right in, she says.$B$BShe'd best be correct. It's our only chance to gather information and plan our counterattack.$B$BYou should be able to find the earth she needs poking in the areas to the south and west of the fortress. Bring it to me when you've finished gathering it.",logDesc="Bring 8 clods of Scourged Earth to Chieftain Wintergale at Taunka'le Village."} end
if not DB[11631] then DB[11631]={id=11631,zoneId=3537,name="Vision of Air",level=71,minLevel=69,giver="Spirit Talker Snarlfang",giverType="NPC",giverId=25339,ender="Spirit Talker Snarlfang",enderType="NPC",enderId=25339,poiX=4524,poiY=5672,wowhead="https://www.wowhead.com/wotlk/quest=11631",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Here, $N, I've attuned the primal to you.$B$BOpen your soul to it in the presence of my totem of air and concentrate upon the fate of Farseer Grimwalker.$B$BThe spirit of the wind touches all; with any luck you will be granted a vision.",logDesc="Use Imperean's Primal to perform a ritual at Snarlfang's Totem at Bor'gorok Outpost to gain information concerning Farseer Grimwalker.$B$BAfterward, speak with Spirit Talker Snarlfang.",choiceRewards={{id=37274,qty=1},{id=37352,qty=1},{id=37442,qty=1},{id=37530,qty=1}}} end
if not DB[11632] then DB[11632]={id=11632,zoneId=3537,name="What the Cold Wind Brings...",level=71,minLevel=68,ender="High Overlord Saurfang",enderType="NPC",enderId=25256,wowhead="https://www.wowhead.com/wotlk/quest=11632",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You hold the carapace fragment of Ith'rix the Harvester and realize that this is only the beginning. Even now you sense that victory is fleeting. Surely the Lich King has a thousand more beasts like Ith'rix, waiting to be unleashed upon the Horde.$B$BTake your trophy and present it to High Overlord Saurfang, inside Warsong Hold. He should be notified of your victory over a powerful Scourge agent.",logDesc="Take Ith'rix's Hardened Carapace to High Overlord Saurfang at Warsong Hold.",choiceRewards={{id=37214,qty=1},{id=37394,qty=1},{id=37424,qty=1},{id=37505,qty=1}}} end
if not DB[11633] then DB[11633]={id=11633,zoneId=3537,name="Blending In",level=72,minLevel=68,giver="Chieftain Wintergale",giverType="NPC",giverId=24703,ender="Chieftain Wintergale",enderType="NPC",enderId=24703,rewardNextId=11640,poiX=3466,poiY=4196,wowhead="https://www.wowhead.com/wotlk/quest=11633",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Sage Aeire has finished the shroud. Take it with you and travel to the Temple City of En'kilah. Don the cloak within the city's bounds to hide yourself from most of the Scourge there. This will be our best opportunity to gather information about the enemy's fortifications and leaders.$B$BWhile wearing the cloak, scout the three large spires on the grounds of the city. While the shroud will shield you from most of the Scourge, the En'kilah abominations will be able to find you if you get too close.",logDesc="Chieftain Wintergale at Taunka'le Village wants you to wear the Imbued Scourge Shroud in the Temple City of En'kilah and scout the Spire of Blood, the Spire of Pain, and the Spire of Decay."} end
if not DB[11634] then DB[11634]={id=11634,zoneId=3537,name="Wind Master To'bor",level=71,minLevel=68,giver="Overlord Razgor",giverType="NPC",giverId=25279,ender="3",enderType="NPC",enderId=25289,rewardNextId=11636,poiX=2785,poiY=6081,wowhead="https://www.wowhead.com/wotlk/quest=11634",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You're a tough mother, $N. I think your talents are better suited elsewhere - like the root of the whole damn problem!$B$B<Razgor points to the west.>$B$BA thousand Scourge, at least four full sized floating death machines and who knows what else.$B$BBut you're gonna find out and then you're gonna handle it... That's right, you're gonna beat the hell out of the Scourge army that's currently beating down our door.$B$BGet to the top of Warsong Hold and report to Wind Master To'bor. He'll be expecting you.",logDesc="Report to Wind Master To'bor at Warsong Hold."} end
if not DB[11635] then DB[11635]={id=11635,zoneId=3537,name="Farseer Grimwalker's Spirit",level=71,minLevel=69,giver="Spirit Talker Snarlfang",giverType="NPC",giverId=25339,ender="Farseer Grimwalker's Spirit",enderType="NPC",enderId=25425,rewardNextId=11637,poiX=4524,poiY=5672,wowhead="https://www.wowhead.com/wotlk/quest=11635",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="You must go to Magmoth to the east.$B$BYou must descend into the depths of their caverns.$B$BYou must speak with Farseer Grimwalker's spirit!",logDesc="Speak with Farseer Grimwalker's Spirit inside of Magmoth."} end
if not DB[11636] then DB[11636]={id=11636,zoneId=3537,name="Magic Carpet Ride",level=71,minLevel=68,giver="3",giverType="NPC",giverId=25289,ender="Gorge the Corpsegrinder",enderType="NPC",enderId=25329,rewardNextId=11642,poiX=2803,poiY=6148,wowhead="https://www.wowhead.com/wotlk/quest=11636",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Tanks, mon. I be talkin' bout siege machines! We got heavy tanks stationed at Garrosh's Landing on da west coast. We gonna get you to da tank and you gonna use da tank to lay down some Horde justice on da Scourge!$B$BDa only tricky part be getting' you der. No way we be sendin' you on our wind riders. Too risky.$B$BYou see dat pixie o'er der? Dat blondie elf? Yanni be his name, mon. He can get you to da coast, safely. Once der, talk to Gorge da Corpsegrinder!",logDesc="Talk to Yanni at Warsong Hold to arrange safe travel to the coast. Speak to Gorge the Corpsegrinder once you arrive at Garrosh's Landing."} end
if not DB[11637] then DB[11637]={id=11637,zoneId=3537,name="Kaganishu",level=72,minLevel=69,giver="Farseer Grimwalker's Spirit",giverType="NPC",giverId=25425,ender="Farseer Grimwalker's Spirit",enderType="NPC",enderId=25425,rewardNextId=11638,poiX=4548,poiY=5333,wowhead="https://www.wowhead.com/wotlk/quest=11637",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="After my small force of grunts were killed, I was dragged down here and ritually murdered. The snobold who did this is known as Kaganishu.$B$BThough you have vanquished his shaman helpers, my spirit is still tethered to this place. After he slew me, he created a fetish from my body, which anchors me here. Kaganishu is using it to learn all that I know of shamanism.$B$BYou must retrieve the fetish from him and use it upon my spirit. Kaganishu is nearby in the caves.$B$BOnly then will I truly be free.",logDesc="Retrieve Kaganishu's Fetish and use it upon Farseer Grimwalker's Remains.$B$BYou will need to give the fetish to Farseer Grimwalker's Spirit inside of Magmoth."} end
if not DB[11638] then DB[11638]={id=11638,zoneId=3537,name="Return My Remains",level=71,minLevel=69,giver="Farseer Grimwalker's Spirit",giverType="NPC",giverId=25425,ender="Spirit Talker Snarlfang",enderType="NPC",enderId=25339,poiX=4548,poiY=5333,wowhead="https://www.wowhead.com/wotlk/quest=11638",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="$N, now that my spirit has been freed would you do me the honor of returning my remains to Spirit Talker Snarlfang? They lay upon the ground beneath me.$B$BI sense that the spirit talker is still at Bor'gorok Outpost to the west where last I saw her.",logDesc="Deliver Farseer Grimwalker's Remains, which are resting below his spirit, to Spirit Talker Snarlfang at Bor'gorok Outpost.",choiceRewards={{id=37049,qty=1},{id=37528,qty=1},{id=37573,qty=1},{id=37574,qty=1},{id=37575,qty=1},{id=37047,qty=1}}} end
if not DB[11639] then DB[11639]={id=11639,zoneId=3537,name="Revenge Upon Magmoth",level=71,minLevel=69,giver="Ortrosh",giverType="NPC",giverId=25374,ender="Ortrosh",enderType="NPC",enderId=25374,poiX=4514,poiY=5714,wowhead="https://www.wowhead.com/wotlk/quest=11639",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="The overlord refuses to allow the shaman to heal my wounds. He says that it will be a good lesson for me and give me time to reflect upon my failure.$B$BBut you could get revenge for me and the others who fell at Magmoth!$B$BI know that the spirit talker wants you to go in there to save the farseer.$B$BIt's just to the east. Go, $c... go slay the magnataur and their snobold servants. Regain the outpost's honor!",logDesc="Kill 10 Magmoth Shaman, 5 Magmoth Foragers, 3 Magmoth Crushers, and 3 Mates of Magmothregar. Then, return to Ortrosh at Bor'gorok Outpost.",choiceRewards={{id=37270,qty=1},{id=37353,qty=1},{id=37441,qty=1},{id=37479,qty=1}}} end
if not DB[11640] then DB[11640]={id=11640,zoneId=3537,name="Words of Power",level=72,minLevel=68,giver="Chieftain Wintergale",giverType="NPC",giverId=24703,ender="Chieftain Wintergale",enderType="NPC",enderId=24703,poiX=3466,poiY=4196,wowhead="https://www.wowhead.com/wotlk/quest=11640",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Within the spires you described dwell the main lieutenants of the Scourge leader, the high priests. Not only do they command the Scourge forces, but they hold the key to the necropolis above, and their master.$B$BAn endless stream of Scourge minions will overrun us if we can't find and defeat their leader. I cannot leave my people defenseless, however much Durm might want to bring the fight to the enemy. It falls to you, $N, to slay the high priests and take the scrolls they hold.",logDesc="Bring High Priest Naferset's Scroll, High Priest Talet-Kha's Scroll, and High Priest Andorath's Scroll to Chieftain Wintergale at Taunka'le Village."} end
if not DB[11641] then DB[11641]={id=11641,zoneId=3537,name="A Courageous Strike",level=72,minLevel=68,giver="Durm Icehide",giverType="NPC",giverId=24706,ender="Durm Icehide",enderType="NPC",enderId=24706,poiX=3469,poiY=4192,wowhead="https://www.wowhead.com/wotlk/quest=11641",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="From the beginning, I've counseled that Chieftain Wintergale should assemble our mighty warriors and attack our enemy at their base. My advice has fallen on deaf ears and he has proven that he'd rather tip-toe around according to Sage Aeire's plans.$B$BI'll wait no longer. If Chieftain Wintergale is too cowardly to send our warriors into battle, perhaps you'd be willing to show him that a direct attack can succeed. Storm the Temple City of En'kilah and slay all in your path, $N.",logDesc="Slay 15 En'kilah Ghouls and 5 En'kilah Necromancers and report back to Durm Icehide at Taunka'le Village."} end
if not DB[11642] then DB[11642]={id=11642,zoneId=3537,name="Tank Ain't Gonna Fix Itself",level=71,minLevel=68,giver="Gorge the Corpsegrinder",giverType="NPC",giverId=25329,ender="Mobu",enderType="NPC",enderId=25475,poiX=2820,poiY=6712,wowhead="https://www.wowhead.com/wotlk/quest=11642",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We need to get these tanks back up and runnin'! They ain't gonna fix themselves. Mobu's gonna be the one to handle that stuff. Talk to him and see what he needs. Maybe you can shut him up before he finally drives me into a berserker frenzy and I cleave his little gnome-sized frame in two!$B$BI hate gnomes...",logDesc="Speak with Mobu at Garrosh's Landing."} end
if not DB[11643] then DB[11643]={id=11643,zoneId=3537,name="Mobu's Pneumatic Tank Transjigamarig",level=71,minLevel=68,giver="Mobu",giverType="NPC",giverId=25475,ender="Mobu",enderType="NPC",enderId=25475,poiX=2814,poiY=6720,wowhead="https://www.wowhead.com/wotlk/quest=11643",image="assets/images/quests/placeholder.png",xpDiff=5,desc="These wrenches are useless, buddy. I need my pneumatic tank transjigamarig to get these things up and running! Unfortunately, I left it at my old digs, on the other side of this landing. It's the beat down hut next to the stables. You're gonna have to go and get it for me, because I sure as hellfire am not going to go anywhere near the mist.$B$BOh yea, buddy, watch out for the mist. The mist is what tore up these shores.$B",logDesc="Mobu at the Coast of Echoes in the Borean Tundra wants you to recover his Pneumatic Tank Transjigamarig.$B"} end
if not DB[11644] then DB[11644]={id=11644,zoneId=3537,name="Super Strong Metal Plates!",level=71,minLevel=68,giver="Mobu",giverType="NPC",giverId=25475,ender="Mobu",enderType="NPC",enderId=25475,poiX=2814,poiY=6720,wowhead="https://www.wowhead.com/wotlk/quest=11644",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I need metal to patch these tanks up! Super strong metal plates can be found scattered about all across Garrosh's Landing and at the bottom of the bay.$B$BJust be careful when you're out there searching for plates. The mist is... um... AGGRESSIVE! The mist is what took out the landing and the adjoining tuskarr town. Poor little tuskarr...",logDesc="Mobu at the Coast of Echoes in the Borean Tundra wants you to collect 10 Super Strong Metal Plates."} end
if not DB[11645] then DB[11645]={id=11645,zoneId=3537,name="Dirty, Stinkin' Snobolds!",level=71,minLevel=69,giver="Crafty Wobblesprocket",giverType="NPC",giverId=25477,ender="Crafty Wobblesprocket",enderType="NPC",enderId=25477,rewardNextId=11650,poiX=4173,poiY=5255,wowhead="https://www.wowhead.com/wotlk/quest=11645",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Those dirty, stinkin' snobolds... they stole all of my supplies!$B$BWhat's a snobold you ask? It's like a kobold, 'cept they serve the magnataur; kinda take care of them. I know, weird!$B$BAnywho, wanna help me out? I know the little creeps stole off with all of my stuff. Stupid me thinkin' that it'd be nice and safe, packed up on the north side of the airstrip.$B$BWhy don'tcha do me a favor and head north to their stupid Magmoth. There's a cash reward if you bring all my stuff back quick!",logDesc="Retrieve 10 boxes of Crafty's Stuff and return them to Crafty Wobblesprocket at Fizzcrank Airstrip."} end
if not DB[11646] then DB[11646]={id=11646,zoneId=3537,name="The Borean Inquisition",level=71,minLevel=69,giver="Librarian Donathan",giverType="NPC",giverId=25262,ender="Librarian Normantis",enderType="NPC",enderId=25480,rewardNextId=11648,poiX=3616,poiY=5961,wowhead="https://www.wowhead.com/wotlk/quest=11646",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Listen closely, $n, for there is not a moment to spare.$b$bYour prisoner is being prepared for interrogation here in our tower. In the event that he is less than forthcoming, your assistance may be required.$b$bMake your way up to where he is being detained and tell Librarian Normantis that I've sent you to assist him.",logDesc="Donathan ordered you to offer your assistance to Librarian Normantis in the mage tower on Amber Ledge."} end
if not DB[11647] then DB[11647]={id=11647,zoneId=3537,name="Neutralizing the Cauldrons",level=72,minLevel=68,giver="Sage Aeire",giverType="NPC",giverId=24709,ender="Sage Aeire",enderType="NPC",enderId=24709,poiX=3462,poiY=4192,wowhead="https://www.wowhead.com/wotlk/quest=11647",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The presence of plague cauldrons within the Temple City of En'kilah worries me greatly, $N. It's clear that Chieftain Wintergale trusts your judgment and your knowledge of our enemy. Would you help me deal with the cauldrons as you help the chieftain carry out his plans in the Temple City?$B$BI've prepared a totem which will attack and neutralize the contents of the cauldrons. All you must do is locate the cauldrons and use the totem near each. Each Scourge weapon we destroy brings us closer to victory.",logDesc="Sage Aeire at Taunka'le Village wants you to use her totem to neutralize the East Cauldron, the Central Cauldron, and the West Cauldron in the Temple City of En'kilah.",choiceRewards={{id=37234,qty=1},{id=37356,qty=1},{id=37439,qty=1},{id=37517,qty=1}}} end
if not DB[11648] then DB[11648]={id=11648,zoneId=3537,name="The Art of Persuasion",level=71,minLevel=69,giver="Librarian Normantis",giverType="NPC",giverId=25480,ender="Librarian Normantis",enderType="NPC",enderId=25480,rewardNextId=11663,poiX=3635,poiY=5900,wowhead="https://www.wowhead.com/wotlk/quest=11648",image="assets/images/quests/placeholder.png",xpDiff=4,money=37000,desc="It is fortunate you're here, $r.$b$bYou see, the Kirin Tor code of conduct frowns upon our taking certain 'extreme' measures - even in desperate times such as these.$b$bYou, however, as an outsider, are not bound by such restrictions and could take any steps necessary in the retrieval of information.$b$bDo what you must. We need to know where Lady Evanor is being held at once!$b$bI'll just busy myself organizing these shelves here. Oh, and here, perhaps you'll find this old thing useful....",logDesc="Librarian Normantis on Amber Ledge wants you to use the Neural Needler on the Imprisoned Beryl Sorcerer until he reveals the location of Lady Evanor."} end
if not DB[11649] then DB[11649]={id=11649,zoneId=3537,name="Motes of the Enraged",level=71,minLevel=69,giver="Imperean",giverType="NPC",giverId=25376,ender="Imperean",enderType="NPC",enderId=25376,rewardNextId=11629,poiX=4538,poiY=5886,wowhead="https://www.wowhead.com/wotlk/quest=11649",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Now that their little squabble is dealt with, there is still the matter of helping you and your spirit talker.$B$BAs you can see, my vassals have been enraged by the ongoing war between fire and water. This will not change anytime soon, but it will serve to your advantage.$B$BIn order to assist you, what we need are their motes. Head further into the ruins and retrieve them from the tempests.",logDesc="Obtain 5 Tempest Motes and deliver them to Imperean at the Ruins of Eldra'nath."} end
if not DB[11650] then DB[11650]={id=11650,zoneId=3537,name="Just a Few More Things...",level=71,minLevel=69,giver="Crafty Wobblesprocket",giverType="NPC",giverId=25477,ender="Crafty Wobblesprocket",enderType="NPC",enderId=25477,poiX=4173,poiY=5255,wowhead="https://www.wowhead.com/wotlk/quest=11650",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="As you may have noticed, we created the airstrip on the southern border of a magnataur den!$B$B<Crafty says something uncharitable about Fizzcrank under her breath.>$B$BThe old man has put me in charge of finding a... ahem... creative solution to this situation: if we don't deal with them soon, they'll come down here and tear us limb from limb!$B$BThat's where you come in. I want you to get me everything on this shopping list. Please.",logDesc="Collect Crafty's Tools, an Overcharged Capacitor, and a Handful of Rocknar's Grit. Deliver them to Crafty Wobblesprocket at Fizzcrank Airstrip."} end
if not DB[11651] then DB[11651]={id=11651,zoneId=3537,name="Tanks a lot...",level=71,minLevel=68,giver="Mobu",giverType="NPC",giverId=25475,ender="Gorge the Corpsegrinder",enderType="NPC",enderId=25329,rewardNextId=11652,poiX=2814,poiY=6720,wowhead="https://www.wowhead.com/wotlk/quest=11651",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Thanks for all your help, buddy. You can let Gorge know the tanks are ready for action. Hopefully you can clean up this place once and for all!$B",logDesc="Speak to Gorge the Corpsegrinder at the Coast of Echoes."} end
if not DB[11652] then DB[11652]={id=11652,zoneId=3537,name="The Plains of Nasam",level=71,minLevel=68,giver="Gorge the Corpsegrinder",giverType="NPC",giverId=25329,ender="Garrosh Hellscream",enderType="NPC",enderId=25237,poiX=2820,poiY=6712,wowhead="https://www.wowhead.com/wotlk/quest=11652",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Once you're ready, jump into one of the tanks and drive it out to the Plains of Nasam, southeast of here.$B$BUse the tank's weapon arsenal to take down the Scourge army. If you get in a jam, the \"Meatpounder\" will tear 'em up and the land mines will finish 'em off! If you find any of our soldiers, grab 'em! One last thing, fuel tanks can be found all over the field.$B$BTry to get close enough to that structure in the center and see what's going on.$B$BIf you do all of this and live, go to Hellscream!",logDesc="Use the Horde Siege Tank to destroy 100 Scourge Soldiers and rescue 3 Injured Warsong Soldiers on the Plains of Nasam. You must also discover the identity of the leader of the Scourge assault.$B$BReport to Garrosh Hellscream at Warsong Hold should you succeed.",choiceRewards={{id=37276,qty=1},{id=37325,qty=1},{id=37446,qty=1},{id=37476,qty=1}}} end
if not DB[11653] then DB[11653]={id=11653,zoneId=3537,name="Hah... You're Not So Big Now!",level=71,minLevel=69,giver="Crafty Wobblesprocket",giverType="NPC",giverId=25477,ender="Crafty Wobblesprocket",enderType="NPC",enderId=25477,rewardNextId=11658,poiX=4173,poiY=5255,wowhead="https://www.wowhead.com/wotlk/quest=11653",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="That'll do her, chief! So, here's what I want ya to do....$B$BTake my blaster and head north to Magmoth. If we're gonna have a chance at all against those monsters, we need to cut them down to size... so to speak.$B$BIn order to gauge its effectiveness, I need you to slay the magnataur while the blaster's effects are still on it. Any of the crushers or mates will do, but don't bother with the offspring... they're too small to worry about.",logDesc="Test out Crafty's Ultra-Advanced Proto-Typical Shortening Blaster on 5 Magmoth Crushers or Mates of Magmothregar. After you have done so, return to her at Fizzcrank Airstrip.",choiceRewards={{id=37272,qty=1},{id=37388,qty=1},{id=37428,qty=1},{id=37526,qty=1}}} end
if not DB[11654] then DB[11654]={id=11654,zoneId=3537,name="The Spire of Blood",level=72,minLevel=68,ender="Snow Tracker Grumm",enderType="NPC",enderId=25516,rewardNextId=11659,wowhead="https://www.wowhead.com/wotlk/quest=11654",image="assets/images/quests/placeholder.png",xpDiff=4,money=39000,desc="As you inspect the captured blood vial, you realize its contents are still warm. The victim must have just been bled and may still be alive.$B$BWhat use would the Scourge have for blood? They've never shown an interest in live prisoners in the past. Perhaps if you can locate the source of the blood, you'll be able to discover what the Scourge is planning.",logDesc="Search the Spire of Blood for more information about the Vial of Fresh Blood."} end
if not DB[11655] then DB[11655]={id=11655,zoneId=3537,name="Into the Mist",level=71,minLevel=68,giver="Waltor of Pal'ea",giverType="NPC",giverId=25476,ender="Waltor of Pal'ea",enderType="NPC",enderId=25476,rewardNextId=11656,poiX=2812,poiY=6706,wowhead="https://www.wowhead.com/wotlk/quest=11655",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Across the mist to the north you will find Garrosh's Landing. To the south are the ruins of my old home, Pal'ea. Both have been ransacked by an ancient force known as the Kvaldir.$B$BThese fearsome savages slew all of my people without mercy and drove your people inland.$B$BAll that remains of the tuskarr of Pal'ea are our personal effects, taken as relics by the Kvaldir. While we are not a vengeful race, justice must be served. The tuskarr relics must be returned to me. Enter the mist and find them...",logDesc="Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to kill Kvaldir and recover 8 Tuskarr Relics."} end
if not DB[11656] then DB[11656]={id=11656,zoneId=3537,name="Burn in Effigy",level=71,minLevel=68,giver="Waltor of Pal'ea",giverType="NPC",giverId=25476,ender="Waltor of Pal'ea",enderType="NPC",enderId=25476,poiX=2812,poiY=6706,wowhead="https://www.wowhead.com/wotlk/quest=11656",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Tuskarr magic is similar to what your people call shamanism. While we serve the elements differently than you, the power that we are able to call forth is formidable.$B$B<Waltor waves a torch-like baton in front of you.>$B$BWith this tuskarr torch I want you to return to the mist and strike at the Kvaldir vessels. You will find three of their vessels docked behind the mist at Garrosh's Landing, north of here, and one docked off the shores of Pal'ea, to the south. Burn their ships in effigy! For all to see!",logDesc="Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to use the Tuskarr Torch to burn the Kvaldir ships at Pal'ea and Garrosh's Landing. You must destroy the following ships: The Serpent's Maw, The Kur Drakkar, Bor's Hammer and Bor's Anvil.$B",choiceRewards={{id=37207,qty=1},{id=37418,qty=1},{id=37556,qty=1},{id=37483,qty=1}}} end
if not DB[11657] then DB[11657]={id=11657,zoneId=-369,name="Torch Catching",level=-1,minLevel=1,ender="Master Fire Eater",enderType="NPC",enderId=25975,wowhead="https://www.wowhead.com/wotlk/quest=11657",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Now that you can throw a torch, let's see if you can catch one!$B$BTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four in a row, then come back to me.$B$BCareful! They're dangerous if they hit the ground!  And don't miss any catches!  If you do then you'll have to go back to the bonfire and start over.  Good luck!",logDesc="Catch 4 torches in a row, then speak with the Master Fire Eater.",rewards={{id=34599,qty=5},{id=23247,qty=5}}} end
if not DB[11658] then DB[11658]={id=11658,zoneId=3537,name="Plan B",level=71,minLevel=69,giver="Crafty Wobblesprocket",giverType="NPC",giverId=25477,ender="Crafty Wobblesprocket",enderType="NPC",enderId=25477,poiX=4173,poiY=5255,wowhead="https://www.wowhead.com/wotlk/quest=11658",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Okay, don't panic! The blaster might not've worked, but we still have options.$B$B<Crafty snaps her fingers.>$B$BWe're going to divert attention away from the airstrip! To make this work, we'll need a few things first.$B$B<Wobblesprocket looks you up and down appraisingly.>$B$BSteeljaw's caravan, just to the west, stupidly took a shortcut through a taunka graveyard and was destroyed by their risen spirits.$B$BHead over there and get some outfits off of the dead orcs. Pick up one of their banners, too!",logDesc="Collect 10 Warsong Outfits and a Warsong Banner. Bring them back to Crafty Wobblesprocket at Fizzcrank Airstrip."} end
if not DB[11659] then DB[11659]={id=11659,zoneId=3537,name="Shatter the Orbs!",level=72,minLevel=68,giver="Snow Tracker Grumm",giverType="NPC",giverId=25516,ender="Snow Tracker Junek",enderType="NPC",enderId=24733,poiX=4131,poiY=3523,wowhead="https://www.wowhead.com/wotlk/quest=11659",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="They're... bleeding the prisoners... putting the blood... in those globes.$B$B<Grumm's eyes close momentarily and he leans his head back.>$B$BThe blood... taken up to necropolis... to feed blood prince...$B$B<Grumm gasps for breath.>$B$BP-promise... you'll... destroy blood... globes... bring word... to Junek.$B$B<The snow tracker collapses into unconsciousness.>",logDesc="Destroy 5 Blood Globes and report to Snow Tracker Junek at Taunka'le Village."} end
if not DB[11660] then DB[11660]={id=11660,zoneId=3537,name="Horn of the Ancient Mariner",level=71,minLevel=68,giver="Waltor of Pal'ea",giverType="NPC",giverId=25476,ender="Waltor of Pal'ea",enderType="NPC",enderId=25476,rewardNextId=11661,poiX=2812,poiY=6706,wowhead="https://www.wowhead.com/wotlk/quest=11660",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A Kvaldir lieutenant known as Orabus directed the initial incursion against my people at Pal'ea, He oversaw the destruction of both villages and then disappeared into the mist.$B$BIn those early days there was talk of a horn that Orabus gifted to the Kvaldir mistweavers. This horn could be used to summon him should the need arise.$B$BWe need to get that horn from the Kvaldir mistweavers and call forth Orabus. If he is destroyed, these savages might retreat.$B$BSeek out mistweavers at Pal'ea, to the south.",logDesc="Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to bring him the Horn of the Ancient Mariner."} end
if not DB[11661] then DB[11661]={id=11661,zoneId=3537,name="Orabus the Helmsman",level=71,minLevel=68,giver="Waltor of Pal'ea",giverType="NPC",giverId=25476,ender="Waltor of Pal'ea",enderType="NPC",enderId=25476,poiX=2812,poiY=6706,wowhead="https://www.wowhead.com/wotlk/quest=11661",image="assets/images/quests/placeholder.png",xpDiff=5,money=141000,desc="Take the horn and travel west to the Warsong Jetty. Make your way to the end of the jetty and blow into the horn. The sound should rouse Orabus.$B$BSlay the foul beast and return to me!",logDesc="Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to use the Horn of the Ancient Mariner to summon Orabus the Helmsman. Once summoned, slay Orabus the Helmsman.",choiceRewards={{id=37208,qty=1},{id=37402,qty=1},{id=37543,qty=1},{id=37484,qty=1}}} end
if not DB[11662] then DB[11662]={id=11662,zoneId=3537,name="Seek Out Karuk!",level=71,minLevel=68,giver="Waltor of Pal'ea",giverType="NPC",giverId=25476,ender="Karuk",enderType="NPC",enderId=25435,poiX=2812,poiY=6706,wowhead="https://www.wowhead.com/wotlk/quest=11662",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A fellow survivor of Pal'ea known as Karuk has made his way to the main base of the Kvaldir in the Borean Tundra - far to the south where the snow was once bountiful. Karuk hides along the bluffs overlooking Riplash Strand.$B$BSeek out Karuk and let him know what you did for my people here at the Coast of Echoes.$B$BThe safest route to Karuk is through your fortress. From Warsong Hold, take the road south and follow it around until you reach Riplash Strand.",logDesc="Seek out Karuk at Riplash Strand."} end
if not DB[11663] then DB[11663]={id=11663,zoneId=3537,name="Sharing Intelligence",level=71,minLevel=69,giver="Librarian Normantis",giverType="NPC",giverId=25480,ender="Librarian Donathan",enderType="NPC",enderId=25262,rewardNextId=11671,poiX=3635,poiY=5900,wowhead="https://www.wowhead.com/wotlk/quest=11663",image="assets/images/quests/placeholder.png",xpDiff=1,money=4800,desc="Thank you, $c! The information you've extracted is of vital importance to the Kirin Tor.$b$bReturn at once to Donathan as we make plans for the rescue of Lady Evanor.",logDesc="Normantis has asked you to report to Librarian Donathan on Amber Ledge."} end
if not DB[11664] then DB[11664]={id=11664,zoneId=3537,name="Escaping the Mist",level=71,minLevel=68,giver="Mootoo the Younger",giverType="NPC",giverId=25504,ender="Elder Mootoo",enderType="NPC",enderId=25503,poiX=2887,poiY=6733,wowhead="https://www.wowhead.com/wotlk/quest=11664",image="assets/images/quests/placeholder.png",xpDiff=6,desc="I can hear the mist creatures outside. Their yells are driving me mad, but I dare not try to escape. And where would I even go? How long would it be until they caught up with me and executed me like the others?$B$BI wonder, how far has the mist crept, stranger? Has it overtaken this whole continent?$B$BWould you be willing to help me try and escape the mist? I think I can lead us back toward my father. I still sense his life spirit. He is close.",logDesc="Follow Mootoo the Younger out of the mist. Speak to Elder Mootoo should you successfully save Mootoo the Younger.",choiceRewards={{id=37212,qty=1},{id=37399,qty=1},{id=37422,qty=1},{id=37028,qty=1}}} end
if not DB[11665] then DB[11665]={id=11665,zoneId=-101,name="Crocolisks in the City",level=70,minLevel=70,giver="Old Man Barlo",giverType="NPC",giverId=25580,ender="Old Man Barlo",enderType="NPC",enderId=25580,poiX=-1409,poiY=5046,wowhead="https://www.wowhead.com/wotlk/quest=11665",image="assets/images/quests/placeholder.png",desc="Hello $glad:lass;.  I'm glad you've stopped by to talk to this old man--there's trouble back home.$b$bA traveling merchant recently sold a batch of baby crocolisks to some gullible children.  Crocolisks are wild beasts, and many have escaped and now lurk in city waterways.$b$bGrab your strongest fishing pole and drop a line in Stormwind or Orgrimmar and bring one of the little devils back to me.  I'm anxious to see one.",logDesc="Bring a Baby Crocolisk to Old Man Barlo.  You can find him fishing northeast of Shattrath City by Silmyr Lake.",rewards={{id=35348,qty=1}}} end
if not DB[11666] then DB[11666]={id=11666,zoneId=-101,name="Bait Bandits",level=70,minLevel=70,giver="Old Man Barlo",giverType="NPC",giverId=25580,ender="Old Man Barlo",enderType="NPC",enderId=25580,poiX=-1409,poiY=5046,wowhead="https://www.wowhead.com/wotlk/quest=11666",image="assets/images/quests/placeholder.png",desc="You probably know all about the golden darter--they're fairly common in the rivers of Terokkar Forest and a delicacy for priests.  But here's one you haven't heard of: the blackfin darter.$b$bThe fish is notoriously crafty and difficult to catch.  You have to pull your line at the last possible second, because they nibble at the bait before they take it.$b$bDrop your line in the rivers of Terokkar and bring me a blackfin darter.  Avoid the lakes, as the blackfin only thrive in moving water.",logDesc="Bring a Blackfin Darter to Old Man Barlo.  You can find him fishing northeast of Shattrath City by Silmyr Lake.",rewards={{id=34863,qty=1}}} end
if not DB[11667] then DB[11667]={id=11667,zoneId=-101,name="The One That Got Away",level=70,minLevel=70,giver="Old Man Barlo",giverType="NPC",giverId=25580,ender="Old Man Barlo",enderType="NPC",enderId=25580,poiX=-1409,poiY=5046,wowhead="https://www.wowhead.com/wotlk/quest=11667",image="assets/images/quests/placeholder.png",desc="Figluster's mudfish is a surprisingly quick bottom feeder found in the waters of Nagrand.  They grow their entire lives and are well known as fighters.$b$bYears ago, I caught what I'm certain was the world's biggest mudfish... until it snapped my line and escaped.$b$bA fisherman of your caliber doesn't need to be told what to do--your destiny awaits in the lakes of Nagrand.",logDesc="Catch the World's Largest Mudfish and bring it to Old Man Barlo.  You can find him fishing northeast of Shattrath City by Silmyr Lake.",rewards={{id=34863,qty=1}}} end
if not DB[11668] then DB[11668]={id=11668,zoneId=-101,name="Shrimpin' Ain't Easy",level=70,minLevel=70,giver="Old Man Barlo",giverType="NPC",giverId=25580,ender="Old Man Barlo",enderType="NPC",enderId=25580,poiX=-1409,poiY=5046,wowhead="https://www.wowhead.com/wotlk/quest=11668",image="assets/images/quests/placeholder.png",desc="There's a lot of big fish in the Zangarmarsh lakes.  Ever wonder what they eat?$b$bShrimp.  Giant freshwater shrimp.  The Rokk tells me the dishes you can make with shrimp are nearly endless.$b$bBut shrimp are too small to catch with a fishing line.  So here's the trick: cut open the bloated barbed gill trout and you'll find a shrimp or two if you're lucky.",logDesc="Bring 10 Giant Freshwater Shrimp to Old Man Barlo.  You can find him fishing northeast of Shattrath City by Silmyr Lake.",rewards={{id=34863,qty=1}}} end
if not DB[11669] then DB[11669]={id=11669,zoneId=-101,name="Felblood Fillet",level=70,minLevel=70,giver="Old Man Barlo",giverType="NPC",giverId=25580,ender="Old Man Barlo",enderType="NPC",enderId=25580,poiX=-1409,poiY=5046,wowhead="https://www.wowhead.com/wotlk/quest=11669",image="assets/images/quests/placeholder.png",desc="This old man is going hunting soon.  I'm gonna take down a mammoth shark off the coast of Azshara.$b$bThe thing is, I need a toxin that'll stay on a spear tip while it's underwater.  To make that kind of stuff, I need the glands from a poisonous fish: the felblood snapper.$b$bSuch a vile fish only thrives in the waters of Hellfire Peninsula and Shadowmoon Valley.  Bring me back a whopper and I'll be a happy old man.",logDesc="Bring a Monstrous Felblood Snapper to Old Man Barlo.  You can find him fishing northeast of Shattrath City by Silmyr Lake.",rewards={{id=34863,qty=1}}} end
if not DB[11670] then DB[11670]={id=11670,zoneId=3537,name="It Was The Orcs, Honest!",level=72,minLevel=69,giver="Crafty Wobblesprocket",giverType="NPC",giverId=25477,ender="Crafty Wobblesprocket",enderType="NPC",enderId=25477,poiX=4173,poiY=5255,wowhead="https://www.wowhead.com/wotlk/quest=11670",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="With all of those outfits you, er, recovered, I fashioned a Warsong orc disguise. I had the genius idea of combining it with some old stuff that I had left hanging around from last Hallows' End, so it should be foolproof!$B$BHere, in this sack is the disguise and the banner you recovered. Head down into the bowels of Magmoth and slay the magnataur chieftain, Magmothregar.$B$BIf you're going to convince them to turn their attention on the Warsong orcs, you'll need to plant the banner while disguised.",logDesc="While disguised as a Warsong orc, plant the Warsong Banner in the corpse of Magmothregar. Then, return with the disguise to Crafty Wobblesprocket at Fizzcrank Airstrip.",choiceRewards={{id=37054,qty=1},{id=37073,qty=1},{id=37357,qty=1},{id=37072,qty=1},{id=37231,qty=1}}} end
if not DB[11671] then DB[11671]={id=11671,zoneId=3537,name="A Race Against Time",level=71,minLevel=69,giver="Librarian Donathan",giverType="NPC",giverId=25262,ender="Librarian Donathan",enderType="NPC",enderId=25262,rewardNextId=11679,poiX=3616,poiY=5961,wowhead="https://www.wowhead.com/wotlk/quest=11671",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="So it's true. They have her.$b$bIt's clear what must be done, $r. She WILL be saved.$b$bI must remain here and aid in the rescue preparations. I call upon you again; this time to collect the prison key. All we know of this Salrand figure is that she cannot be harmed so long as her shield is intact.$b$bWe've customized a special explosive that should strip her of this protection, allowing you to perform your duty. Return to me when you've collected the key.$b$bHurry, $n. Lady Evanor is suffering!",logDesc="Donathan on Amber Ledge has tasked you with using the Beryl Shield Detonator to bring down the shield at Beryl Point. You are then to defeat Salrand and collect the key she holds."} end
if not DB[11672] then DB[11672]={id=11672,zoneId=3537,name="Enlistment Day",level=71,minLevel=68,giver="Recruitment Officer Blythe",giverType="NPC",giverId=25307,ender="General Arlos",enderType="NPC",enderId=25250,poiX=2300,poiY=5236,wowhead="https://www.wowhead.com/wotlk/quest=11672",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You've come to enlist, right?  Normally you'd have to stand in line like the other recruits.  Normally you'd be out of luck because the recruitment ledger's gone missing and I can't process anyone until the new books get here.$B$BFortunately for you, $N, I've heard about you and what you did in Outland.  To be honest, you're a cut above these poor saps.  Lines aren't for you.$B$BGo to the barracks and speak to General Arlos.  He'll be more than happy to meet with someone of your caliber.",logDesc="Meet with General Arlos inside the barracks in Valiance Keep."} end
if not DB[11673] then DB[11673]={id=11673,zoneId=3537,name="Get Me Outa Here!",level=72,minLevel=69,giver="Bonker Togglevolt",giverType="NPC",giverId=25589,ender="Fizzcrank Fullthrottle",enderType="NPC",enderId=25590,poiX=4414,poiY=5367,wowhead="https://www.wowhead.com/wotlk/quest=11673",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="I knew they'd send someone for me sooner or later... turned out to be later, of course.$B$BI came in here to parlay with the snobolds, but their main shaman, Kaganishu, decided instead that I'd make a tasty snack for Magmothregar.$B$BWait... what?! They didn't send you?!$B$BDID THEY FORGET ABOUT ME?!$B$BOkay, you're here now and that's all that matters.$B$BAs soon as you break this chain we'll make our way back to the airstrip. Then you can tell Fizzcrank I'm safely back.$B$BIf he remembers me, that is.",logDesc="Escort Bonker Togglevolt to safety and then report in with Fizzcrank Fullthrottle at Fizzcrank Airstrip.",choiceRewards={{id=37049,qty=1},{id=37528,qty=1},{id=37573,qty=1},{id=37574,qty=1},{id=37575,qty=1},{id=37047,qty=1}}} end
if not DB[11674] then DB[11674]={id=11674,zoneId=3537,name="Sage Highmesa is Missing",level=71,minLevel=68,giver="Greatmother Taiga",giverType="NPC",giverId=25602,ender="Sage Highmesa",enderType="NPC",enderId=25604,rewardNextId=11675,poiX=3481,poiY=4115,wowhead="https://www.wowhead.com/wotlk/quest=11674",image="assets/images/quests/placeholder.png",xpDiff=1,desc="There are many new mysteries walking the lands now. One of our sages, Highmesa, has foolishly gone north with only one longrunner to investigate something strange near the Dens of Dying.$B$BWhat are the dens, you ask? They are a sacred place to the magnataur, where they go in their old age to die. She saw something fall from the sky near them a few days ago.$B$BIf you would be friend to the taunka, I would have you find and help her. She is not so stubborn that she will not accept your aid.",logDesc="Find Sage Highmesa near the Dens of Dying."} end
if not DB[11675] then DB[11675]={id=11675,zoneId=3537,name="A Proper Death",level=71,minLevel=68,giver="Sage Highmesa",giverType="NPC",giverId=25604,ender="Sage Highmesa",enderType="NPC",enderId=25604,rewardNextId=11677,poiX=3988,poiY=4267,wowhead="https://www.wowhead.com/wotlk/quest=11675",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="The magnataur at the Dens of Dying have contracted a plague. We must find the cause, but first we must put them out of their misery.$B$B$R, you must go north onto the slopes in front of us and destroy as many of the poor creatures as you can.",logDesc="Destroy 10 Plagued Magnataur and then return to Sage Highmesa south of The Dens of Dying."} end
if not DB[11676] then DB[11676]={id=11676,zoneId=3537,name="Merciful Freedom",level=71,minLevel=68,giver="Shadowstalker Canarius",giverType="NPC",giverId=25438,ender="Shadowstalker Canarius",enderType="NPC",enderId=25438,poiX=2877,poiY=6385,wowhead="https://www.wowhead.com/wotlk/quest=11676",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The soldiers that they didn't kill are being held in cages scattered across this farmland. Through some thievery we've managed to find a few keys, but we're unable to get close enough to any prisoners without being attacked.$B$BWe need your \"talents\" in securing those keys and freeing the prisoners. Bash in the brains of the necrolords and aberrations and take their keys. Use those keys to free Scourge prisoners.",logDesc="Shadowstalker Canarius at Warsong Farms Outpost wants you to free 5 Scourge Prisoners."} end
if not DB[11677] then DB[11677]={id=11677,zoneId=3537,name="Stop the Plague",level=71,minLevel=68,giver="Sage Highmesa",giverType="NPC",giverId=25604,ender="Sage Highmesa",enderType="NPC",enderId=25604,poiX=3988,poiY=4267,wowhead="https://www.wowhead.com/wotlk/quest=11677",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I'm convinced that the plague is being caused by something in the caves up there.$B$B$C, I want you to take these seeds. I normally use them as a ward against the Scourge, though perhaps they can be used to disrupt whatever foulness is happening in the dens.$B$BFind the source of the plague and throw them into it.",logDesc="Sage Highmesa, standing just south of The Dens of Dying, has asked you to use Highmesa's Cleansing Seeds at a Den of Dying Plague Cauldron to neutralize it.",choiceRewards={{id=37223,qty=1},{id=37391,qty=1},{id=37427,qty=1},{id=37507,qty=1}}} end
if not DB[11678] then DB[11678]={id=11678,zoneId=3537,name="Find Bristlehorn",level=71,minLevel=68,giver="Sage Highmesa",giverType="NPC",giverId=25604,ender="Longrunner Bristlehorn",enderType="NPC",enderId=25658,rewardNextId=11687,poiX=3988,poiY=4267,wowhead="https://www.wowhead.com/wotlk/quest=11678",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Bristlehorn should have returned by now.$B$BThe other reason why we came up here was to investigate that Scourge structure to the west, which fell from the sky. He's impetuous and has likely gotten himself into trouble.$B$B$N, go to that place and find him, please.",logDesc="Find Longrunner Bristlehorn at Talramas."} end
if not DB[11679] then DB[11679]={id=11679,zoneId=3537,name="Reforging the Key",level=71,minLevel=69,giver="Librarian Donathan",giverType="NPC",giverId=25262,ender="3",enderType="NPC",enderId=24795,poiX=3616,poiY=5961,wowhead="https://www.wowhead.com/wotlk/quest=11679",image="assets/images/quests/placeholder.png",desc="Delays, delays... the one thing we cannot afford right now!$b$bAs much as I hate to disturb Lord Surristrasz, he's our only hope of saving our beloved Evanor.$b$bBring him the key fragments and hope that his mood is favorable.$b$bHurry, $c, our assault team is waiting.",logDesc="Donathan wants you to speak to Surristrasz on Amber Ledge."} end
if not DB[11680] then DB[11680]={id=11680,zoneId=3537,name="Taking Wing",level=71,minLevel=69,giver="3",giverType="NPC",giverId=24795,ender="3",enderType="NPC",enderId=25356,rewardNextId=11681,poiX=3571,poiY=5958,wowhead="https://www.wowhead.com/wotlk/quest=11680",image="assets/images/quests/placeholder.png",xpDiff=1,money=4800,desc="The key is forged anew.$b$bNow heed my counsel, $r. Succeed in your endeavor or die trying, for if a single scale falls from one of my drakes I shall hold you personally accountable.$b$bNow, off with you.",logDesc="Give Salrand's Key to Warmage Anzim when you are ready to free Evanor."} end
if not DB[11681] then DB[11681]={id=11681,zoneId=3537,name="Rescuing Evanor",level=71,minLevel=69,giver="3",giverType="NPC",giverId=25356,ender="Archmage Evanor",enderType="NPC",enderId=25785,rewardNextId=11682,poiX=3464,poiY=5897,wowhead="https://www.wowhead.com/wotlk/quest=11681",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="At last, we attack!$b$bOnce we've cleared the platform I'll use the key.$b$bYou are to ensure that Lady Evanor remains safe after her release.$b$bHurry now, let us be off!",logDesc="Anzim on Amber Ledge wants you to fly with his war mages to free Lady Evanor at Beryl Point. You are then to report to her in the mage tower on Amber Ledge.",choiceRewards={{id=37224,qty=1},{id=37387,qty=1},{id=37429,qty=1},{id=37509,qty=1}}} end
if not DB[11682] then DB[11682]={id=11682,zoneId=3537,name="Dragonspeak",level=71,minLevel=69,giver="Archmage Evanor",giverType="NPC",giverId=25784,ender="3",enderType="NPC",enderId=24795,rewardNextId=11733,wowhead="https://www.wowhead.com/wotlk/quest=11682",image="assets/images/quests/placeholder.png",xpDiff=3,money=24000,desc="I am aware of your recent deeds here, $n, and again I thank you.$b$bAs for this local menace, we've learned all we need to know from them. They'll be dealt with in short order. On now to more important issues....$b$bAzeroth needs you. The region just west of here is the center of an urgent crisis.$b$bI'll leave the details to Lord Surristrasz. You must speak with him at once.$b$bGood luck, friend of Dalaran.",logDesc="Lady Evanor has sent you to speak with Surristrasz on Amber Ledge."} end
if not DB[11683] then DB[11683]={id=11683,zoneId=3537,name="Fallen Necropolis",level=71,minLevel=68,giver="Sage Highmesa",giverType="NPC",giverId=25604,ender="Sage Highmesa",enderType="NPC",enderId=25604,poiX=3988,poiY=4267,wowhead="https://www.wowhead.com/wotlk/quest=11683",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="The fallen necropolis to the west can only be assumed to still be filled with Scourge.$B$BWhile you are at Talramas, $c, I would ask that you dispatch all of the Lich King's servants that you find within and in the surrounding pools where it fell.",logDesc="Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Sage Highmesa just to the south of The Dens of the Dying.",choiceRewards={{id=37239,qty=1},{id=37560,qty=1},{id=37355,qty=1},{id=37518,qty=1}}} end
if not DB[11684] then DB[11684]={id=11684,zoneId=3537,name="Scouting the Sinkholes",level=71,minLevel=68,giver="Greatfather Mahan",giverType="NPC",giverId=24702,ender="Greatfather Mahan",enderType="NPC",enderId=24702,rewardNextId=11685,poiX=3444,poiY=4128,wowhead="https://www.wowhead.com/wotlk/quest=11684",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Can you feel the tremors in the earth?$B$BThe Scourge's nerubians are on the move deep beneath the ground. They've emerged to the southwest in the Geyser Fields, and are harassing the patrols Chieftain Wintergale sent out.$B$B<The taunka elder offers you a worn map.>$B$BPerhaps a single person can succeed where the patrols have failed. Take this with you to the Geyser Fields and map out the locations of the Nerubian sinkholes.",logDesc="Greatfather Mahan at Taunka'le Village wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole."} end
if not DB[11685] then DB[11685]={id=11685,zoneId=3537,name="The Heart of the Elements",level=71,minLevel=68,giver="Greatfather Mahan",giverType="NPC",giverId=24702,ender="Wind Tamer Barah",enderType="NPC",enderId=24730,rewardNextId=11695,poiX=3444,poiY=4128,wowhead="https://www.wowhead.com/wotlk/quest=11685",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Now that we know the exact locations of the nerubian sinkholes, we can collapse them to halt the Scourge offensive and cripple their force. Wind Tamer Barah knows a way to harness elementals to destroy the tunnels the Nerubians are using, but she will require your help.$B$BSoutheast of the village, near the coast beyond the Frozen Reach, you'll find an area dominated by frozen earth elementals. The hearts of these elements are exactly what Wind Tamer Barah will need.",logDesc="Bring 5 Elemental Hearts to Wind Tamer Barah at Taunka'le Village."} end
if not DB[11686] then DB[11686]={id=11686,zoneId=3537,name="The Warsong Farms",level=71,minLevel=68,giver="Shadowstalker Ickoris",giverType="NPC",giverId=25437,ender="Shadowstalker Ickoris",enderType="NPC",enderId=25437,rewardNextId=11703,poiX=2875,poiY=6376,wowhead="https://www.wowhead.com/wotlk/quest=11686",image="assets/images/quests/placeholder.png",xpDiff=5,desc="According to Luther's notes the Scourge is now using this place as a breeding ground for those monsters you see lumbering across the field.$B$B<Ickoris shudders.>$B$BThose monsters were once orcs... tauren...$B$BWe need more information before a plan can be devised. I want you to investigate three sites that are heavily trafficked by Scourge: the Warsong Granary, southwest of us, Torp's Farm, directly west of us, and the old Warsong Slaughterhouse, north of us.$B$BReturn to me once you've scouted 'em out.",logDesc="Shadowstalker Ickoris at Warsong Farms Outpost wants you to scout Warsong Granary, Torp's Farm, and Warsong Slaughterhouse."} end
if not DB[11687] then DB[11687]={id=11687,zoneId=3537,name="The Doctor and the Lich-Lord",level=72,minLevel=68,giver="Longrunner Bristlehorn",giverType="NPC",giverId=25658,ender="Sage Highmesa",enderType="NPC",enderId=25604,rewardNextId=11689,poiX=4417,poiY=4549,wowhead="https://www.wowhead.com/wotlk/quest=11687",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="There are two... that must... be killed.$B$BThe doctor and... the lich-lord... are above. Find them... destroy them... before....$B$B...it is too... late....",logDesc="Destroy Doctor Razorgrin and Lich-Lord Chillwinter. Then, return to Sage Highmesa just to the south of The Dens of Dying."} end
if not DB[11688] then DB[11688]={id=11688,zoneId=3537,name="Damned Filthy Swine",level=71,minLevel=68,giver="Farmer Torp",giverType="NPC",giverId=25607,ender="Farmer Torp",enderType="NPC",enderId=25607,rewardNextId=11690,poiX=2886,poiY=6386,wowhead="https://www.wowhead.com/wotlk/quest=11688",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Just look at 'em! My beautiful kodos are helpless to defend themselves against those filthy swine! I need you to buy me some time, $r. I think I can cure the kodo of the sickness, but you need to keep the unliving swine off 'em, else there'll be nothin' left to cure!$B$BGet out there and send those swine to their graves - permanently!",logDesc="Farmer Torp at Warsong Farms Outpost wants you to kill 10 Unliving Swine."} end
if not DB[11689] then DB[11689]={id=11689,zoneId=3537,name="Return with the Bad News",level=71,minLevel=68,giver="Sage Highmesa",giverType="NPC",giverId=25604,ender="Greatmother Taiga",enderType="NPC",enderId=25602,poiX=3988,poiY=4267,wowhead="https://www.wowhead.com/wotlk/quest=11689",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="The greatmother will need to know, $N.$B$BWill you please return to Taunka'le? Tell her that I will be following shortly.",logDesc="Speak with Greatmother Taiga at Taunka'le Village.",choiceRewards={{id=37529,qty=1},{id=37354,qty=1},{id=37440,qty=1},{id=37519,qty=1},{id=37074,qty=1}}} end
if not DB[11690] then DB[11690]={id=11690,zoneId=3537,name="Bring 'Em Back Alive",level=71,minLevel=68,giver="Farmer Torp",giverType="NPC",giverId=25607,ender="Farmer Torp",enderType="NPC",enderId=25607,poiX=2886,poiY=6386,wowhead="https://www.wowhead.com/wotlk/quest=11690",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Take this riding snaffle, $N. You'll notice that I've placed a tiny medicine dispenser in the mouthpiece. That thing will cure the infection as soon as a kodo bites down. Once you've cured the sick out of 'em, you'll need to ride 'em home. They'll be weak so you'll need to gently direct 'em here.$B$BBring my babies back, $N!$B$BOne last thing, you've got ten minutes! That's how long the antidote will remain effective inside that snaffle.",logDesc="Farmer Torp at Warsong Farms Outpost wants you to rescue 8 Infected Kodo Beasts.",choiceRewards={{id=36884,qty=1},{id=36885,qty=1},{id=36886,qty=1},{id=36887,qty=1}}} end
if not DB[11691] then DB[11691]={id=11691,zoneId=-369,name="Summon Ahune",level=80,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=11691",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I and my Shamans have gathered our powers for the coming battle with the Lord of Frost.  $N, you will be the fist of the Earthmother.$B$BTake this magma totem.  Use it against the Ice Stone, to the northeast.  Ahune is channeling his power through this stone; it is our hope that the totem will disrupt him and cut off his link to the elemental planes.$B$BIf fortune is with us, then, perhaps, we can defeat him.$B$BPrepare yourself, $n.  If Ahune comes to face us, then his fury will be great.",logDesc="Bring the Earthen Ring Magma Totem to the Ice Stone."} end
if not DB[11692] then DB[11692]={id=11692,zoneId=3537,name="Check in With Bixie",level=71,minLevel=68,giver="Mordle Cogspinner",giverType="NPC",giverId=25702,ender="Bixie Wrenchshanker",enderType="NPC",enderId=25705,rewardNextId=11693,poiX=4183,poiY=5255,wowhead="https://www.wowhead.com/wotlk/quest=11692",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You're a proven $g hero : heroine;. I have another problem!$B$BMy boss, Tinky, went east with Bixie Wrenchshanker and I CAN'T get the outgoing on this thing to work! Tinky's the only one that can fix it and we really need it working one-hundred percent.$B$BYou think you could find them? Bixie said something about following some old magnataur to a place called The Dens of Dying.$B$BI'm guessing that's where you'll find them.$B$BYou can catch a ride out there by talking with Kara Thricestar at the runway.",logDesc="Mordle Cogspinner has asked you to find Bixie Wrenchshanker to the south of The Dens of Dying."} end
if not DB[11693] then DB[11693]={id=11693,zoneId=3537,name="Oh Great... Plagued Magnataur!",level=71,minLevel=68,giver="Bixie Wrenchshanker",giverType="NPC",giverId=25705,ender="Bixie Wrenchshanker",enderType="NPC",enderId=25705,rewardNextId=11694,poiX=4183,poiY=4336,wowhead="https://www.wowhead.com/wotlk/quest=11693",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Tinky and I came out here stalking some old magnataur. Apparently those caves up there are where they go to die.$B$BOf course, we had no idea that they were going to get plagued when they went in there. We can't have plagued things just roaming about; it's not healthy.$B$BSay, why don't you put down a number of those things while I figure out what our next step should be?",logDesc="Kill 10 Plagued Magnataur and then return to Bixie Wrenchshanker to the south of The Dens of Dying."} end
if not DB[11694] then DB[11694]={id=11694,zoneId=3537,name="There's Something Going On In Those Caves",level=71,minLevel=68,giver="Bixie Wrenchshanker",giverType="NPC",giverId=25705,ender="Bixie Wrenchshanker",enderType="NPC",enderId=25705,poiX=4183,poiY=4336,wowhead="https://www.wowhead.com/wotlk/quest=11694",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="So, while you were out taking care of those plagued beasts, I took a peek inside the caves up there.$B$BThere are cultists in there plaguing them!$B$BThey have some sort of noxious concoction brewing in a cauldron. I have a powder that I normally use as an anti-poison, and I mixed it up with some other stuff. I think it'll neutralize their brew!$B$BTake it up to one of those caves and see if it works.",logDesc="Bixie Wrenchshanker, skulking just to the south of The Dens of Dying, has asked you to use Bixie's Inhibiting Powder at a Den of Dying Plague Cauldron to neutralize it.",choiceRewards={{id=37223,qty=1},{id=37391,qty=1},{id=37427,qty=1},{id=37507,qty=1}}} end
if not DB[11695] then DB[11695]={id=11695,zoneId=3537,name="The Horn of Elemental Fury",level=71,minLevel=68,giver="Wind Tamer Barah",giverType="NPC",giverId=24730,ender="Wind Tamer Barah",enderType="NPC",enderId=24730,rewardNextId=11706,poiX=3523,poiY=4214,wowhead="https://www.wowhead.com/wotlk/quest=11695",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I can fashion the likeness of an elemental from these pieces of inanimate stone, but breathing life into it is different. For that, we'll need help and a bit of luck.$B$BLegend tells of an ancient artifact called the Horn of Elemental Fury, sought after by a great hero. I'll lend you a scroll with a copy of the tale. I don't know if the legend is true, but it's our best bet. If the legend is right, the parts of the horn may be in the Flood Plains surrounding the village to the north and southwest.",logDesc="Reclaim the Lower Horn Half and Upper Horn Half from Chieftain Burblegoggle and Chieftain Gurgleboggle and bring them to Wind Tamer Barah at Taunka'le Village."} end
if not DB[11696] then DB[11696]={id=11696,zoneId=-22,name="Ahune is Here!",level=80,minLevel=75,ender="Luma Skymother",enderType="NPC",enderId=25697,rewardNextId=11691,wowhead="https://www.wowhead.com/wotlk/quest=11696",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="$n, your presence is a blessing.  Ahune lies within these caverns, gathering strength for his assault.  Earthen Ring forces were sent ahead, but they alone cannot defeat him.$B$BExplore, $n.  Find our Earthen Ring Shamans and speak with their leader, Luma Skymother.  Perhaps, with your added strength, we can beat Ahune before it's too late.",logDesc="Find Luma Skymother in the Slave Pens."} end
if not DB[11697] then DB[11697]={id=11697,zoneId=3537,name="Rats, Tinky Went into the Necropolis!",level=71,minLevel=68,giver="Bixie Wrenchshanker",giverType="NPC",giverId=25705,ender="Tinky Wickwhistle",enderType="NPC",enderId=25714,rewardNextId=11699,poiX=4183,poiY=4336,wowhead="https://www.wowhead.com/wotlk/quest=11697",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I told Tinky not to go off on her own, but she just HAD to check out that crashed necropolis to the west.$B$BI'm 100% certain that those cultists came from inside that thing, which means I'm now 100% certain that Tinky's in trouble!$B$BShe's the airstrip's number one engineer. Without her we're doomed!$B$BI'd find her myself, but one of those things got in a swipe on my leg before I could vanish again. $N, if anyone can get her out, it's you!",logDesc="Find Tinky Wickwhistle inside Talramas."} end
if not DB[11698] then DB[11698]={id=11698,zoneId=3537,name="Might As Well Wipe Out the Scourge",level=71,minLevel=68,giver="Bixie Wrenchshanker",giverType="NPC",giverId=25705,ender="Bixie Wrenchshanker",enderType="NPC",enderId=25705,poiX=4183,poiY=4336,wowhead="https://www.wowhead.com/wotlk/quest=11698",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="If the cultists up in those caves survived the crash, then that fallen necropolis to the west can only be assumed to still be filled with Scourge. There're probably lots of them out in front of it in the pools, too!$B$BWhile you're at Talramas, $c, do you think you could dispatch all of the Lich King's flunkies that you find there?",logDesc="Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Bixie Wrenchshanker just to the south of The Dens of the Dying.",choiceRewards={{id=37239,qty=1},{id=37560,qty=1},{id=37355,qty=1},{id=37518,qty=1}}} end
if not DB[11699] then DB[11699]={id=11699,zoneId=3537,name="I'm Stuck in this Damned Cage... But Not For Long!",level=72,minLevel=68,giver="Tinky Wickwhistle",giverType="NPC",giverId=25714,ender="Tinky Wickwhistle",enderType="NPC",enderId=25714,poiX=4330,poiY=4540,wowhead="https://www.wowhead.com/wotlk/quest=11699",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The cultists magicked me into this cage and there's no door to it. Little did they know that I'm the chief transmatter engineer for the airstrip!$B$BWith your help, and a little elbow-grease, I won't be in here for long.$B$BI'm going to need an engine-core crystal from one of the ghouls in here, a magical gyroscope from their doctor, and a piloting scourgestone from the lich-lord up top.$B$BWith all of that stuff, I should be able to make a port device to get back to Fizzcrank's and escape the gnome way!",logDesc="Collect an Engine-Core Crystal, a Magical Gyroscope, and a Piloting Scourgestone. Deliver them to Tinky Wickwhistle at Talramas."} end
if not DB[11700] then DB[11700]={id=11700,zoneId=3537,name="Let Bixie Know",level=71,minLevel=68,giver="Tinky Wickwhistle",giverType="NPC",giverId=25714,ender="Bixie Wrenchshanker",enderType="NPC",enderId=25705,poiX=4330,poiY=4540,wowhead="https://www.wowhead.com/wotlk/quest=11700",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My evil twin's out there somewhere now.$B$BI'm pretty sure that she's not back at the airstrip. In fact, wherever she ended up, it's colder there than here. But I could only 'feel' her for a moment.$B$BOh well, I'll reconfigure this thing and port myself back to the airstrip soon enough. In the meantime, do you think you could go east and let Bixie know that I'll meet her back there?$B$BThanks, $N!",logDesc="Speak with Bixie Wrenchshanker just south of The Dens of Dying."} end
if not DB[11701] then DB[11701]={id=11701,zoneId=3537,name="Back to the Airstrip",level=71,minLevel=68,giver="Bixie Wrenchshanker",giverType="NPC",giverId=25705,ender="Fizzcrank Fullthrottle",enderType="NPC",enderId=25590,poiX=4183,poiY=4336,wowhead="https://www.wowhead.com/wotlk/quest=11701",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="Okay, I think I'm going to start making my way back to the airstrip, too. Of course, I'm moving a little slower with this leg injury.$B$BSay, do you think you could get there ahead of me and pass on the good news to Ol' Fizzcrank? I bet anything that there'll be a reward in it for you.$B$BThanks, $N!",logDesc="Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip in Borean Tundra.",choiceRewards={{id=37529,qty=1},{id=37354,qty=1},{id=37440,qty=1},{id=37519,qty=1},{id=38214,qty=1}}} end
if not DB[11702] then DB[11702]={id=11702,zoneId=3537,name="King Mrgl-Mrgl",level=71,minLevel=69,giver="Supply Master Taz'ishi",giverType="NPC",giverId=25736,ender="King Mrgl-Mrgl",enderType="NPC",enderId=25197,rewardNextId=11571,poiX=4503,poiY=5749,wowhead="https://www.wowhead.com/wotlk/quest=11702",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Dis is gonna sound weird, $c, but dere be a murloc askin' for our help!$B$BHe goes by da name of King Mrgl-Mrgl, leader of da Winterfin murlocs. Him and his people been run outa dere village and wantin' you to come save dem.$B$BYou find him by headin' west and go down da cliffs. He hangin' out on da south side of da Winterfin Retreat.",logDesc="Speak with King Mrgl-Mrgl at Winterfin Retreat."} end
if not DB[11703] then DB[11703]={id=11703,zoneId=3537,name="Get to Getry",level=71,minLevel=68,giver="Shadowstalker Ickoris",giverType="NPC",giverId=25437,ender="Shadowstalker Getry",enderType="NPC",enderId=25729,poiX=2875,poiY=6376,wowhead="https://www.wowhead.com/wotlk/quest=11703",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Scourge agent that's overseeing the abduction and transformation of Horde soldiers into undead monsters is using the northwest farm as a spawning glade. Shadowstalker Getry has been staking out that monster for the past week and has gathered some vital information that might allow us to end this menace.$B$BGet to Getry and see if you can help him put a stop to this Scourge assembly line. You'll find Getry at the abandoned tower on the northwest border of these farms.",logDesc="Find Shadowstalker Getry at Warsong Farms."} end
if not DB[11704] then DB[11704]={id=11704,zoneId=3537,name="King Mrgl-Mrgl",level=71,minLevel=69,giver="Mordle Cogspinner",giverType="NPC",giverId=25702,ender="King Mrgl-Mrgl",enderType="NPC",enderId=25197,rewardNextId=11571,poiX=4183,poiY=5255,wowhead="https://www.wowhead.com/wotlk/quest=11704",image="assets/images/quests/placeholder.png",xpDiff=1,desc="This is the weirdest thing, $c, but there's a murloc asking for our help!$B$BHe goes by the name of King Mrgl-Mrgl, leader of the Winterfin murlocs. It would seem that he and his people have been run out of their village and they want someone to come save them.$B$BThat someone is you!$B$BYou'll find Winterfin Retreat, and the king, by heading west down the road until you come to the cliffs. Head down to the water line near the Blistering Pool.",logDesc="Speak with King Mrgl-Mrgl at Winterfin Retreat."} end
if not DB[11705] then DB[11705]={id=11705,zoneId=3537,name="Foolish Endeavors",level=71,minLevel=68,giver="Shadowstalker Getry",giverType="NPC",giverId=25729,ender="Garrosh Hellscream",enderType="NPC",enderId=25237,rewardNextId=11709,poiX=3113,poiY=6577,wowhead="https://www.wowhead.com/wotlk/quest=11705",image="assets/images/quests/placeholder.png",xpDiff=7,desc="This is madness. How do they expect us to take on a Scourge necrolord and an unknown number of his minions?$B$B<Getry sighs.>$B$BIf Ickoris sent you he must think that you are capable of great feats. Perhaps you will call down a miracle today, eh?$B$BWhen you're ready we will descend and face Varidus.$B$BIf we make it out of this mess in one piece, report back to Hellscream in Warsong Hold.",logDesc="Help Getry defeat Varidus the Flenser at Warsong Farms.$B$BReport to Garrosh Hellscream should you succeed.$B",choiceRewards={{id=37447,qty=1},{id=37545,qty=1},{id=37475,qty=1},{id=37277,qty=1}}} end
if not DB[11706] then DB[11706]={id=11706,zoneId=3537,name="The Collapse",level=71,minLevel=68,giver="Wind Tamer Barah",giverType="NPC",giverId=24730,ender="Wind Tamer Barah",enderType="NPC",enderId=24730,poiX=3523,poiY=4214,wowhead="https://www.wowhead.com/wotlk/quest=11706",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="I have created and bound Alluvius using the Horn of Elemental Fury. He will respond to the horn's call when you stand near the southernmost sinkhole in the Geyser Fields.$B$BThe quake Alluvius will unleash should collapse the Nerubian tunnels and put an end to their flanking attack. I wouldn't be surprised if the Nerubian commander showed himself after the quake. If the collapse of the tunnels doesn't break the back of their assault, the defeat of their leader surely will.",logDesc="Wind Tamer Barah at Taunka'le Village wants you to collapse the Nerubian sinkholes using the Horn of Elemental Fury and defeat Lord Kryxix.",choiceRewards={{id=37228,qty=1},{id=37375,qty=1},{id=37437,qty=1},{id=37516,qty=1}}} end
if not DB[11707] then DB[11707]={id=11707,zoneId=3537,name="Distress Call",level=71,minLevel=68,giver="Airman Skyhopper",giverType="NPC",giverId=25737,ender="Fizzcrank Fullthrottle",enderType="NPC",enderId=25590,rewardNextId=11708,poiX=2256,poiY=5179,wowhead="https://www.wowhead.com/wotlk/quest=11707",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Oh good, you're $N, right?$B$BWe need your help up north at Fizzcrank Airstrip, like yesterday! The magnataur, and the Scourge... and the pumping station!$B$BIt's madness I tell you, madness!$B$BYou've got to head up there and talk to old man Fullthrottle a.s.a.p.!",logDesc="Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip."} end
if not DB[11708] then DB[11708]={id=11708,zoneId=3537,name="The Mechagnomes",level=71,minLevel=68,giver="Fizzcrank Fullthrottle",giverType="NPC",giverId=25590,ender="Jinky Wingnut",enderType="NPC",enderId=25747,rewardNextId=11712,poiX=4179,poiY=5286,wowhead="https://www.wowhead.com/wotlk/quest=11708",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Now that you're here, it's time for me to tell you the full story of what's going on.$B$BAfter you've heard my tale, go outside and find my second-in-command, Jinky Wingnut. She'll handle everything from here on out.",logDesc="Listen to Fizzcrank Fullthrottle's tale and then find Jinky Wingnut at Fizzcrank Airstrip."} end
if not DB[11709] then DB[11709]={id=11709,zoneId=3537,name="Nork Bloodfrenzy's Charge",level=71,minLevel=68,giver="Garrosh Hellscream",giverType="NPC",giverId=25237,ender="Warden Nork Bloodfrenzy",enderType="NPC",enderId=25379,rewardNextId=11711,poiX=2838,poiY=6187,wowhead="https://www.wowhead.com/wotlk/quest=11709",image="assets/images/quests/placeholder.png",xpDiff=1,desc="While you have done much to secure our foothold in these frozen wastes, other dangers still lurk in the shadows. I want you to assist Warden Nork Bloodfrenzy, stationed at the internment camp just outside and immediately southeast of Warsong Hold. Seek him out and offer your assistance for prisoner transport and exchange.$B$BYou are dismissed, $N. ",logDesc="Speak to Warden Nork Bloodfrenzy at Warsong Hold in Borean Tundra."} end
if not DB[11710] then DB[11710]={id=11710,zoneId=3537,name="What's the Matter with the Transmatter?",level=71,minLevel=68,giver="Mordle Cogspinner",giverType="NPC",giverId=25702,ender="Mordle Cogspinner",enderType="NPC",enderId=25702,rewardNextId=11692,poiX=4183,poiY=5255,wowhead="https://www.wowhead.com/wotlk/quest=11710",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="There're spare parts strewn all over to the east in the Scalding Pools, the Geyser Fields... heck, probably even up on the pumping station still, too. Bring back a whole bunch. Maybe then I'll be able to get outgoing teleport on this thing working, not to mention getting the incoming transmatter ports aligned.$B$BI'd hate to see another accident....",logDesc="Collect 15 Fizzcrank Spare Parts and deliver them to Mordle Cogspinner at Fizzcrank Airstrip."} end
if not DB[11711] then DB[11711]={id=11711,zoneId=3537,name="Coward Delivery... Under 30 Minutes or it's Free",level=71,minLevel=68,giver="Warden Nork Bloodfrenzy",giverType="NPC",giverId=25379,ender="Scout Tungok",enderType="NPC",enderId=25440,rewardNextId=11714,poiX=2806,poiY=6051,wowhead="https://www.wowhead.com/wotlk/quest=11711",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We're seeing more deserters show up at our gates with each passing day. We simply do not have enough room to keep all of these maggots caged up. Especially not if we want to keep the pigs happy.$B$B<Nork snorts as he laughs.>$B$BI want you to escort one of these cowards to the crossroads east of here and fire this flare gun. One of their captains will show up when they see the flare and take the coward off your hands.$B$BReport to Scout Tungok on the east road once the delivery has been made.$B",logDesc="Take the Alliance Deserter to the crossroads east of Warsong Hold and fire your Warsong Flare Gun to signal the Alliance.$B$BReport to Scout Tungok once you have successfully delivered the Alliance Deserter to their destination."} end
if not DB[11712] then DB[11712]={id=11712,zoneId=3537,name="Re-Cursive",level=71,minLevel=68,giver="Jinky Wingnut",giverType="NPC",giverId=25747,ender="Jinky Wingnut",enderType="NPC",enderId=25747,rewardNextId=11788,poiX=4178,poiY=5260,wowhead="https://www.wowhead.com/wotlk/quest=11712",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="If you listened to the old man, then you know that we have gnomes out there that were changed. Gearmaster Mechazod infected them with something that reversed the \"Curse of the Flesh\", and now they're robots!$B$BWe think we have a way to re-curse them back to normal. We want you to take this re-cursive transmatter injection and use it on the corpses of any mechagnomes you come across.$B$BWe're hoping that this stuff will cure them and allow us to lock onto them to port 'em out of there.$B$BWhaddya say, $N?",logDesc="Jinky Wingnut at Fizzcrank Airstrip has asked you to use the Re-Cursive Transmatter Injection on 6 Fizzcrank Mechagnomes.",choiceRewards={{id=37234,qty=1},{id=37356,qty=1},{id=37439,qty=1},{id=37517,qty=1}}} end
if not DB[11713] then DB[11713]={id=11713,zoneId=3537,name="Scouting the Sinkholes",level=71,minLevel=68,giver="Abner Fizzletorque",giverType="NPC",giverId=25780,ender="Abner Fizzletorque",enderType="NPC",enderId=25780,rewardNextId=11715,poiX=4125,poiY=5282,wowhead="https://www.wowhead.com/wotlk/quest=11713",image="assets/images/quests/placeholder.png",xpDiff=5,money=94000,desc="Fizzcrank sent out an aerial surveillance team to map the Nerubian sinkholes in the southern part of the Geyser Fields, but they haven't yet returned. I can't afford to wait any longer for their information, so I'm going to need someone to check out the sinkholes on foot.$B$BI understand the dangers involved, and I'll compensate you accordingly. Take this map with you and record the vital information about each of the sinkholes you encounter out there.",logDesc="Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole."} end
if not DB[11714] then DB[11714]={id=11714,zoneId=3537,name="Vermin Extermination",level=71,minLevel=68,giver="Scout Tungok",giverType="NPC",giverId=25440,ender="Scout Tungok",enderType="NPC",enderId=25440,poiX=2904,poiY=5498,wowhead="https://www.wowhead.com/wotlk/quest=11714",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Perhaps you'd be interested in helping me clean up these fields? They're littered with dirty little rat men! Kobolds, snobolds, whatever you wanna call 'em, they're all over the damned place. The stink alone is making my life hell!$B$BTake care of the vermin for me and I'll make it worth your while, $N.$B",logDesc="Scout Tungok at the Bloodspore Plains in the Borean Tundra wants you to kill 8 Bloodspore Harvesters, 5 Bloodspore Firestarters and 2 Bloodspore Roasters.",choiceRewards={{id=37205,qty=1},{id=37404,qty=1},{id=37524,qty=1},{id=37481,qty=1}}} end
if not DB[11715] then DB[11715]={id=11715,zoneId=3537,name="Fueling the Project",level=71,minLevel=68,giver="Abner Fizzletorque",giverType="NPC",giverId=25780,ender="Abner Fizzletorque",enderType="NPC",enderId=25780,rewardNextId=11718,poiX=4125,poiY=5282,wowhead="https://www.wowhead.com/wotlk/quest=11715",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I plan to build a machine that will collapse the tunnels the Scourge is using to deploy their Nerubians, but with the main drilling rig out of order, we'll have to collect the fuel for the device some other way.$B$BOut in the Geyser Fields to the southeast, small pools of oil bubble up away from the main rig. If you can collect enough of the oil from those pools, I can make a crude fuel to power the machine.$B$BSimply deploy the collector near the rig, and it will pump and store the oil in its tank.",logDesc="Abner Fizzletorque at Fizzcrank Airstrip wants you to collect 8 Barrels of Oil using the Portable Oil Collector."} end
if not DB[11716] then DB[11716]={id=11716,zoneId=3537,name="The Wondrous Bloodspore",level=71,minLevel=68,giver="Bloodmage Laurith",giverType="NPC",giverId=25381,ender="Bloodmage Laurith",enderType="NPC",enderId=25381,rewardNextId=11717,poiX=2880,poiY=5570,wowhead="https://www.wowhead.com/wotlk/quest=11716",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We are witnessing something amazing here, $r. A whole undiscovered ecology lives and breathes not more than a few paces from us! I surmise it is the bloodspore plant that sets this environment abuzz.$B$BI have collected some pollen from the nearby male species of bloodspore plant but still lack female receptors for pollination. Fetch me a bushel of the bloodspore carpels. You'll find them near the larger plants surrounding us.$B$BBe wary of their guardians! The kobolds won't give them up easily!",logDesc="Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 10 Bloodspore Carpels."} end
if not DB[11717] then DB[11717]={id=11717,zoneId=3537,name="Pollen from the Source",level=71,minLevel=68,giver="Bloodmage Laurith",giverType="NPC",giverId=25381,ender="Bloodmage Laurith",enderType="NPC",enderId=25381,rewardNextId=11719,poiX=2880,poiY=5570,wowhead="https://www.wowhead.com/wotlk/quest=11717",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It's obvious! The bloodspore moths are the entities responsible for pollination on these plains. It must be something that happens within the moth's internal system that acts as a catalyst for this pollen to work. It's all starting to make sense now, $N. That's why the kobolds don't kill the moths and instead go to great lengths to protect them! Those stupid little rats have it all figured out!$B$BWell we'll just have to get our own moth pollen! What do you say? Fetch me some in the name of science?",logDesc="Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 5 Bloodspore Moth Pollen.$B"} end
if not DB[11718] then DB[11718]={id=11718,zoneId=3537,name="A Bot in Mammoth's Clothing",level=71,minLevel=68,giver="Abner Fizzletorque",giverType="NPC",giverId=25780,ender="Abner Fizzletorque",enderType="NPC",enderId=25780,rewardNextId=11723,poiX=4125,poiY=5282,wowhead="https://www.wowhead.com/wotlk/quest=11718",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I've reconfigured the skeleton of an old bot to create an earthquake large enough to collapse the tunnels, but the machinery is delicate and sensitive to Northrend's biting cold.$B$BI've devised a means of insulating it using the thickest hides of the native mammoths. They roam the plains south of the airstrip and adjacent to the Geyser Fields. Bring back enough of the hides for me to finish the machine and then we'll be able to unleash it on the Nerubians!",logDesc="Abner Fizzletorque at Fizzcrank Airstrip wants you to bring him 6 Thick Mammoth Hides."} end
if not DB[11719] then DB[11719]={id=11719,zoneId=3537,name="A Suitable Test Subject",level=71,minLevel=68,giver="Bloodmage Laurith",giverType="NPC",giverId=25381,ender="Bloodmage Laurith",enderType="NPC",enderId=25381,rewardNextId=11720,poiX=2880,poiY=5570,wowhead="https://www.wowhead.com/wotlk/quest=11719",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Laurith looks you over as if to size you up.>$B$BSo we've got this pollinated bloodspore flower and nobody to test its effects on. Say, would you perhaps be interested in rubbing this on your skin and letting me observe? What's the worst that could happen anyway?$B$BDon't you worry, $N! Just take this sample and rub it all over your face. ",logDesc="Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra has asked that you use the Pollinated Bloodspore Flower and allow her to observe the results."} end
if not DB[11720] then DB[11720]={id=11720,zoneId=3537,name="The Invasion of Gammoth",level=71,minLevel=68,giver="Bloodmage Laurith",giverType="NPC",giverId=25381,ender="Primal Mighthorn",enderType="NPC",enderId=25380,rewardNextId=11721,poiX=2880,poiY=5570,wowhead="https://www.wowhead.com/wotlk/quest=11720",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hellscream assigned Mighthorn and I with the daunting task of magnataur extermination on the southern front of Warsong Hold. With us came an entire platoon of seasoned Horde soldiers. Our initial foray into the nearby magnataur dens proved quite unsuccessful as our entire squad was wiped out by the lair defenders. We're the only ones left...$B$BWe aren't scientists or researchers. We're soldiers of the Horde, just like you. Soldiers on a mission that cannot fail...$B$BSpeak to Primal Mighthorn now.",logDesc="Speak to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.$B"} end
if not DB[11721] then DB[11721]={id=11721,zoneId=3537,name="Gammothra the Tormentor",level=71,minLevel=68,giver="Primal Mighthorn",giverType="NPC",giverId=25380,ender="Primal Mighthorn",enderType="NPC",enderId=25380,rewardNextId=11722,poiX=2868,poiY=5563,wowhead="https://www.wowhead.com/wotlk/quest=11721",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Magnataur live in prides, much like lions: one or two dominant males and several females along with their offspring. In the case of Gammoth, the magnataur den west of here, Gammothra is the leader. It is Gammothra that controls this magnataur population and therefore it is Gammothra that must be slain to prevent any type of magnataur uprising.$B$BTake this pouch of crushed bloodspore flower to Gammoth. Use the powder from the pouch to weaken Gammothra and then slay him! Return his head to me as proof.",logDesc="Slay Gammothra and return the Head of Gammothra to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra."} end
if not DB[11722] then DB[11722]={id=11722,zoneId=3537,name="Trophies of Gammoth",level=71,minLevel=68,giver="Primal Mighthorn",giverType="NPC",giverId=25380,ender="Garrosh Hellscream",enderType="NPC",enderId=25237,poiX=2868,poiY=5563,wowhead="https://www.wowhead.com/wotlk/quest=11722",image="assets/images/quests/placeholder.png",xpDiff=4,desc="We cannot take all of the credit for this Horde victory, $N. It was you who risked your life to test the bloodspore and it was you who ultimately put an end to Gammothra.$B$BHonor us by returning to Warsong Hold and presenting the head of Gammothra to Lord Hellscream.",logDesc="Take the Head of Gammothra to Garrosh Hellscream in Warsong Hold.",choiceRewards={{id=37204,qty=1},{id=37405,qty=1},{id=37415,qty=1},{id=37480,qty=1}}} end
if not DB[11723] then DB[11723]={id=11723,zoneId=3537,name="Deploy the Shake-n-Quake!",level=71,minLevel=68,giver="Abner Fizzletorque",giverType="NPC",giverId=25780,ender="Abner Fizzletorque",enderType="NPC",enderId=25780,poiX=4125,poiY=5282,wowhead="https://www.wowhead.com/wotlk/quest=11723",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="Behold, the machine that will save us from the Nerubian threat!$B$B<Abner beams with pride as he presents the finished bot.>$B$BTake this remote control with you, and go out to the southernmost of the Nerubian sinkholes in the Geyser Fields. Use the remote to activate the Shake-n-Quake 5000. It will do the rest on its own.$B$BDon't be surprised if the quake it creates attracts the attention of a Nerubian leader. In fact, it would be a great opportunity to finish off the Nerubian offensive.",logDesc="Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Shake-n-Quake 5000 to collapse the Nerubian tunnels and defeat Lord Kryxix.",choiceRewards={{id=37228,qty=1},{id=37375,qty=1},{id=37437,qty=1},{id=37516,qty=1}}} end
if not DB[11724] then DB[11724]={id=11724,zoneId=3537,name="Massive Moth Omelet?",level=71,minLevel=68,ender="Bloodmage Laurith",enderType="NPC",enderId=25381,wowhead="https://www.wowhead.com/wotlk/quest=11724",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This egg was obviously important to somebody, as the corpse nearby can attest. As you look the egg over you notice that it has already been tagged for shipment to the Bloodspore Plains, care of Bloodmage Laurith. That's just east of here!$B$BCollect the egg and take it to the expectant Bloodmage.",logDesc="Take the Massive Glowing Egg to Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra."} end
if not DB[11725] then DB[11725]={id=11725,zoneId=3537,name="Finding Pilot Tailspin",level=71,minLevel=68,giver="Fizzcrank Fullthrottle",giverType="NPC",giverId=25590,ender="Iggy \"Tailspin\" Cogtoggle",enderType="NPC",enderId=25807,poiX=4179,poiY=5286,wowhead="https://www.wowhead.com/wotlk/quest=11725",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I should've flown the mission myself. It's not that I don't trust Tailspin. Far from it. Heck, he was the best wingman I ever flew with.$B$BNo, it's just that it's my responsibility to lead a mission of such import.$B$BI sent Tailspin out with our fastest recon squadron to gather information about the Nerubian infestation in the middle of the Geyser Fields.$B$BThe last report we received placed his squadron in the pools to the far south and just west of the Nerubian sinkholes.$B$BFind Tailspin, $N.",logDesc="Locate Iggy \"Tailspin\" Cogtoggle in the Geyser Fields."} end
if not DB[11726] then DB[11726]={id=11726,zoneId=3537,name="A Little Bit of Spice",level=71,minLevel=68,giver="Iggy \"Tailspin\" Cogtoggle",giverType="NPC",giverId=25807,ender="Iggy \"Tailspin\" Cogtoggle",enderType="NPC",enderId=25807,rewardNextId=11728,poiX=3522,poiY=5016,wowhead="https://www.wowhead.com/wotlk/quest=11726",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="The wolves have been pawing through the wreckage ever since the crash and I'm afraid they consumed the microfilm from our mission in the process.$B$BI have a plan to recover that microfilm, but I need your help to make it work.$B$BTo the south and east, in the Flood Plains, live creatures called gorlocs. They prepare their foods with noxious spices, which would sicken any other creature. If you can gather enough of the spice pouches from gorloc steam belchers or gorloc waddlers, I can make the wolf bait.",logDesc="Iggy \"Tailspin\" Cogtoggle in the Scalding Pools wants you to gather 4 Gorloc Spice Pouches."} end
if not DB[11727] then DB[11727]={id=11727,zoneId=3537,name="A Time for Heroes",level=71,minLevel=68,giver="General Arlos",giverType="NPC",giverId=25250,ender="Sergeant Hammerhill",enderType="NPC",enderId=25816,rewardNextId=11797,poiX=2106,poiY=5304,wowhead="https://www.wowhead.com/wotlk/quest=11727",image="assets/images/quests/placeholder.png",xpDiff=1,desc="It's good to have you among us, $N.  We've all heard of your past deeds.$B$BAs you know, King Wrynn is moving great armies into Northrend to meet those of Arthas.  But armies are nothing without true heroes to inspire and lead them.$B$BI want you to be that hero for my men.  Fight alongside them against the Scourge that lays siege to our stronghold.$B$BReport to Sergeant Hammerhill outside the inner hold.  Valiance Keep cannot fall.  The future of our campaign depends on it.",logDesc="Report to Sergeant Hammerhill at Valiance Keep."} end
if not DB[11728] then DB[11728]={id=11728,zoneId=3537,name="Lupus Pupus",level=71,minLevel=68,giver="Iggy \"Tailspin\" Cogtoggle",giverType="NPC",giverId=25807,ender="Iggy \"Tailspin\" Cogtoggle",enderType="NPC",enderId=25807,rewardNextId=11795,poiX=3522,poiY=5016,wowhead="https://www.wowhead.com/wotlk/quest=11728",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Whatever you do, don't eat this bait yourself. Just set it down in the vicinity of an oil-soaked wolf. If they're desperate enough to eat the microfilm, they'll come running when they smell the bait.$B$BSimply wait for nature to take its course and then all you need to do is search the, uh... byproduct for the film.$B$BI'd offer you my special lupus pupus scupus for the job, but I left it back at the airstrip. I'm afraid you'll have to conduct the... err... search the old-fashioned way.",logDesc="Iggy \"Tailspin\" Cogtoggle in the Scalding Pools wants you to bring him 8 pieces of Microfilm."} end
if not DB[11729] then DB[11729]={id=11729,zoneId=3537,name="The Ultrasonic Screwdriver",level=71,minLevel=68,ender="Crafty Wobblesprocket",enderType="NPC",enderId=25477,rewardNextId=11730,wowhead="https://www.wowhead.com/wotlk/quest=11729",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The unit you just dismantled had this inside of its mechanical innards.$B$BIt looks pretty complicated... certainly someone back at the airstrip would want to take a look at it. Maybe Crafty Wobblesprocket?",logDesc="Deliver the Ultrasonic Screwdriver to Crafty Wobblesprocket at Fizzcrank Airstrip."} end
if not DB[11730] then DB[11730]={id=11730,zoneId=3537,name="Master and Servant",level=71,minLevel=68,giver="Crafty Wobblesprocket",giverType="NPC",giverId=25477,ender="Crafty Wobblesprocket",enderType="NPC",enderId=25477,poiX=4173,poiY=5255,wowhead="https://www.wowhead.com/wotlk/quest=11730",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="The Ultrasonic Screwdriver is the ultimate tool. It can do anything to mechanical stuff!$B$BHead back into the pools and dismantle a number of Mechazod's robots. Then all you have to do is use the screwdriver on their remains, and I'm betting that they'll turn to our side, for a short time anyway.$B$BI'm pretty sure it won't work on the mechagnomes, so don't even bother with them.$B$BOh, and if you want to take anything from the robot's insides, you'll want to do so before using the screwdriver!",logDesc="Use the Ultrasonic Screwdriver to reprogram 15 robots and then return to Crafty Wobblesprocket at Fizzcrank Airstrip.$B$BMake sure to loot the dead robot before you reprogram it.",choiceRewards={{id=37270,qty=1},{id=37353,qty=1},{id=37441,qty=1},{id=37479,qty=1}}} end
if not DB[11731] then DB[11731]={id=11731,zoneId=-369,name="Torch Tossing",level=-1,minLevel=1,ender="Master Fire Eater",enderType="NPC",enderId=25975,rewardNextId=11657,wowhead="https://www.wowhead.com/wotlk/quest=11731",image="assets/images/quests/placeholder.png",xpDiff=5,money=1300,desc="So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!$B$BTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!$B$BHit enough marked braziers before the time limit, then come back here... for your next lession.",logDesc="Win the torch tossing game, then speak with the Master Fire Eater.",rewards={{id=23247,qty=5}}} end
if not DB[11732] then DB[11732]={id=11732,zoneId=-22,name="Desecrate this Fire!",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=11732",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,rewards={{id=23247,qty=10}}} end
if not DB[11733] then DB[11733]={id=11733,zoneId=3537,name="Traversing the Rift",level=71,minLevel=69,giver="3",giverType="NPC",giverId=24795,ender="Archmage Berinand",enderType="NPC",enderId=25314,poiX=3571,poiY=5958,wowhead="https://www.wowhead.com/wotlk/quest=11733",image="assets/images/quests/placeholder.png",xpDiff=4,money=37000,desc="I've been mindful of your efforts, mortal. Do not feign surprise. Surely you've felt my eye upon you.$b$bThe time has come to peel back a layer of darkness from your mind. There are stark truths that you have grown ready to accept.$b$bBefore hearing the tale, you shall be shown firsthand what we face.$b$bPut your affairs in order, $c....",logDesc="Surristrasz wants you to travel to Coldarra. Once there, you are to speak with Archmage Berinand."} end
