if not DB[11788] then DB[11788]={id=11788,zoneId=3537,name="Lefty Loosey, Righty Tighty",level=71,minLevel=68,giver="Jinky Wingnut",giverType="NPC",giverId=25747,ender="Jinky Wingnut",enderType="NPC",enderId=25747,rewardNextId=11798,poiX=4178,poiY=5260,wowhead="https://www.wowhead.com/wotlk/quest=11788",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="Okay, I think we're ready for the penultimate assault... before you can bring down Mechazod, you're going to have to dismantle his lieutenants first!$B$BYou'll find Twonky, ED-210, Max Blasto, and The Grinder at the West Point, North Point, Mid Point and South Point stations, respectively.$B$BTo get them to show up, just turn the valves at the stations to mess up whatever they're trying to do out there. You can't miss the places, they all have spinning lights.",logDesc="Dismantle Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Jinky Wingnut at Fizzcrank Airstrip."} end
if not DB[11789] then DB[11789]={id=11789,zoneId=3537,name="A Soldier in Need",level=71,minLevel=68,giver="Medic Hawthorn",giverType="NPC",giverId=25825,ender="Medic Hawthorn",enderType="NPC",enderId=25825,poiX=2249,poiY=5400,wowhead="https://www.wowhead.com/wotlk/quest=11789",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You there!  Please, I need your help.  This soldier will succumb to the cryptfiends' venom unless we act immediately.$B$BI've managed to slow down the poison, but without a suitable supply of antidote I cannot counteract it.$B$BI was promised a new shipment of anti-venom in the Stormbreaker's most recent trip from the south.  Go inside its hold and search for a chest of first aid supplies.$B$BHurry, $c!  We can't afford to lose any more men unnecessarily.",logDesc="Medic Hawthorn, outside of Valiance Keep, wants you to go inside the Stormbreaker's hold and retrieve Hawthorn's Anti-Venom from a crate of First Aid Supplies.",rewards={{id=22850,qty=2}}} end
if not DB[11790] then DB[11790]={id=11790,zoneId=3537,name="Cultists Among Us",level=71,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=11790",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship.$B$BPerhaps he is to be found above deck.",logDesc="Speak to Captain \"Lefty\" Lugsail above the Stormbreaker in Valiance Keep."} end
if not DB[11791] then DB[11791]={id=11791,zoneId=3537,name="Notify Arlos",level=71,minLevel=68,giver="Admiral Cantlebree",giverType="NPC",giverId=25299,ender="General Arlos",enderType="NPC",enderId=25250,poiX=2238,poiY=5239,wowhead="https://www.wowhead.com/wotlk/quest=11791",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We must notify General Arlos at once.  I've known the captain for a long time and, believe me, he is one of the more careful ones.$B$BWho knows how many cultists have been smuggled into our settlements in Northrend in other ships?  This could be disastrous.",logDesc="Speak to General Arlos inside the Inner Hold at Valiance Keep."} end
if not DB[11792] then DB[11792]={id=11792,zoneId=3537,name="Enemies of the Light",level=71,minLevel=68,giver="Harbinger Vurenn",giverType="NPC",giverId=25285,ender="Harbinger Vurenn",enderType="NPC",enderId=25285,rewardNextId=11793,poiX=2113,poiY=5308,wowhead="https://www.wowhead.com/wotlk/quest=11792",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Not so fast there.  I don't know about you, $c, but I was hardly convinced by the general's words.  They rung unsure... as if they were not his own.$B$BSomething's amiss here.  All of our efforts to collaborate have been blocked and delayed.  It is time we took a more independent approach.$B$BIf we're to learn more about the cultists inside the keep... perhaps we should investigate those outside.$B$BIntelligence reports a small group of them aiding the Scourge north of here.  See if they carry any clues.",logDesc="Harbinger Vurenn wants you to fight the Cultist Necrolytes near Farshire to the north of Valiance Keep and retrieve the Cultist Communique from them.",choiceRewards={{id=36888,qty=1},{id=36937,qty=1},{id=36938,qty=1},{id=38213,qty=1}}} end
if not DB[11793] then DB[11793]={id=11793,zoneId=3537,name="Further Investigation",level=71,minLevel=68,giver="Harbinger Vurenn",giverType="NPC",giverId=25285,ender="Vindicator Yaala",enderType="NPC",enderId=25826,rewardNextId=11794,poiX=2113,poiY=5308,wowhead="https://www.wowhead.com/wotlk/quest=11793",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I'm afraid this is a matter I must delegate to one of my operatives... someone who can work in secret.  Keep the evidence with you and take it to Vindicator Yaala inside the inn.$B$BTell her I sent you and speak of this matter to no one else.  We do not know who might be working for the cult.",logDesc="Bring the Cultist Communique to Vindicator Yaala inside the inn in Valiance Keep."} end
if not DB[11794] then DB[11794]={id=11794,zoneId=3537,name="The Hunt is On",level=71,minLevel=68,giver="Vindicator Yaala",giverType="NPC",giverId=25826,ender="Vindicator Yaala",enderType="NPC",enderId=25826,poiX=2311,poiY=5196,wowhead="https://www.wowhead.com/wotlk/quest=11794",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've made it my business to learn as much as possible about the vile death cult, including their secret language.$B$BVurenn was right.  The cultists mention disguised operatives in various locations in Valiance Keep: the lower docks, the jail inside the inner hold and in the inn's kitchen.$B$BTake this oculus.  Use it at those three locations - anyone that has recently used the cult's necromancy will be enshrouded by a dark aura.  Take care of the cultists before something nefarious happens.",logDesc="Vindicator Yaala wants you to use the Oculus of the Exorcist in three different locations in Valiance Keep to uncover and defeat Cult of the Damned members.",choiceRewards={{id=37204,qty=1},{id=37405,qty=1},{id=37415,qty=1},{id=37480,qty=1}}} end
if not DB[11795] then DB[11795]={id=11795,zoneId=3537,name="Emergency Protocol: Section 8.2, Paragraph C",level=71,minLevel=68,giver="Iggy \"Tailspin\" Cogtoggle",giverType="NPC",giverId=25807,ender="Iggy \"Tailspin\" Cogtoggle",enderType="NPC",enderId=25807,rewardNextId=11796,poiX=3522,poiY=5016,wowhead="https://www.wowhead.com/wotlk/quest=11795",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Injured or not, as squadron commander, I'm responsible for locating and returning the insignia of all fallen pilots under my command. In all the years I've flown with Fizzcrank, we've never failed to return the signet of a pilot.$B$BMy injuries make it dangerous for me to stray far from the safety of the wreckage, but perhaps you would be willing to help me recover the insignia? In the meantime, I'll make preparations to carry out my final duty as squadron commander.",logDesc="Recover 6 Fizzcrank Pilot Insignia from the bodies of Fizzcrank Recon Pilots and return them to Iggy \"Tailspin\" Cogtoggle in the Scalding Pools."} end
if not DB[11796] then DB[11796]={id=11796,zoneId=3537,name="Emergency Protocol: Section 8.2, Paragraph D",level=71,minLevel=68,giver="Iggy \"Tailspin\" Cogtoggle",giverType="NPC",giverId=25807,ender="Iggy \"Tailspin\" Cogtoggle",enderType="NPC",enderId=25807,rewardNextId=11873,poiX=3522,poiY=5016,wowhead="https://www.wowhead.com/wotlk/quest=11796",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="There's only one more thing left to do before I can finally return to the airstrip and make my report. Section 8.2, paragraph D of the emergency protocol requires me to scuttle as much of the wreckage as possible, in order to prevent our technology from falling into enemy hands.$B$BI'll give you my torch if you agree to help me complete this last duty. I don't want to think about what the Horde's goblin allies will do if these machines fall into their hands.",logDesc="Iggy \"Tailspin\" Cogtoggle wants you to scuttle the Eastern Wreck, a Southern Wreck, and a Northwestern Wreck."} end
if not DB[11797] then DB[11797]={id=11797,zoneId=3537,name="The Siege",level=71,minLevel=68,giver="Sergeant Hammerhill",giverType="NPC",giverId=25816,ender="Sergeant Hammerhill",enderType="NPC",enderId=25816,rewardNextId=11889,poiX=2223,poiY=5322,wowhead="https://www.wowhead.com/wotlk/quest=11797",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Well, well, well.  It's good to see Arlos bring out the big guns.$B$BDon't get me wrong - our lads are doing the best they can, but someone of your renown fighting alongside them could really turn the tides for us.  I'm not sure how much longer we can hold out against these undead Nerubians.$B$BWhat do you say you get out there and kill me some creepers?  Show these boys how it's done.",logDesc="Sergeant Hammerhill wants you to kill 6 Crypt Crawlers in the Sands of Nasam outside of Valiance Keep.",choiceRewards={{id=36883,qty=1},{id=38208,qty=1},{id=36878,qty=1},{id=36881,qty=1},{id=36879,qty=1},{id=36880,qty=1}}} end
if not DB[11798] then DB[11798]={id=11798,zoneId=3537,name="The Gearmaster",level=72,minLevel=68,giver="Jinky Wingnut",giverType="NPC",giverId=25747,ender="Fizzcrank Fullthrottle",enderType="NPC",enderId=25590,poiX=4178,poiY=5260,wowhead="https://www.wowhead.com/wotlk/quest=11798",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="Gearmaster Mechazod is insane! He says that he offers us immortality by removing this so-called 'Curse of the Flesh', but what he's really making are robotic slaves!$B$B$N, we're pretty certain that he's still at the pumping station out in the middle of the pools to the east.$B$BThe last we saw of him, he was in the command hut up top. Go up there and research his stuff.$B$BYou must confront Mechazod if gnomes everywhere,... no, everyone everywhere, are to stay alive!",logDesc="Research the Gearmaster's Manual and return Mechazod's Head to Fizzcrank Fullthrottle.",choiceRewards={{id=37274,qty=1},{id=37352,qty=1},{id=37442,qty=1},{id=37530,qty=1}}} end
