if not DB[11864] then DB[11864]={id=11864,zoneId=3537,name="A Mission Statement",level=72,minLevel=70,giver="Arch Druid Lathorius",giverType="NPC",giverId=25809,ender="Arch Druid Lathorius",enderType="NPC",enderId=25809,poiX=3194,poiY=5282,wowhead="https://www.wowhead.com/wotlk/quest=11864",image="assets/images/quests/placeholder.png",xpDiff=1} end
if not DB[11865] then DB[11865]={id=11865,zoneId=3537,name="Unfit for Death",level=72,minLevel=70,giver="Zaza",giverType="NPC",giverId=25811,ender="Zaza",enderType="NPC",enderId=25811,rewardNextId=11868,poiX=3205,poiY=5297,wowhead="https://www.wowhead.com/wotlk/quest=11865",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Just south of us the caribou used to roam freely, peacefully. Then Nesingwary showed up and everything changed. Now the caribou are in a perpetual state of frenzy, always in a panic. They are stalked by the hunters and trappers hidden in the field.$B$BNesingwary's executioners are unfit for death. They must feel the torture that they put the caribou through!$B$BTake this pile of fake furs and lay it upon their caribou traps to the south. Watch as the hunters are caught in their own deadly traps!",logDesc="Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the Pile of Fake Furs to trap 8 Nesingwary Trappers.$B"} end
if not DB[11866] then DB[11866]={id=11866,zoneId=3537,name="Ears of Our Enemies",level=72,minLevel=70,giver="Arch Druid Lathorius",giverType="NPC",giverId=25809,ender="Arch Druid Lathorius",enderType="NPC",enderId=25809,poiX=3194,poiY=5282,wowhead="https://www.wowhead.com/wotlk/quest=11866",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.$B$BShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.$B",logDesc="Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears."} end
if not DB[11867] then DB[11867]={id=11867,zoneId=3537,name="Can't Get Ear-nough...",level=72,minLevel=70,giver="Arch Druid Lathorius",giverType="NPC",giverId=25809,ender="Arch Druid Lathorius",enderType="NPC",enderId=25809,poiX=3194,poiY=5282,wowhead="https://www.wowhead.com/wotlk/quest=11867",image="assets/images/quests/placeholder.png",desc="Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nessingwary and does dare strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A. Should you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.$B",logDesc="Arch Druid Lathorius at the D.E.H.T.A. Outpost in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears."} end
if not DB[11868] then DB[11868]={id=11868,zoneId=3537,name="The Culler Cometh",level=72,minLevel=70,giver="Zaza",giverType="NPC",giverId=25811,ender="Zaza",enderType="NPC",enderId=25811,poiX=3205,poiY=5297,wowhead="https://www.wowhead.com/wotlk/quest=11868",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Near the southern end of this bluff is where you will find the treacherous leader of the caribou trappers. She is a savage like no other, making a mockery out of the carcasses of the slain animals: drinking from their blood and howling to the moons!$B$BFind this murderer, Karen, and end her worthless existence.$B$BPrepare yourself properly, $N. Karen the Culler has indulged in the riches that Nesingwary has lavished upon her! She will be well armed and guarded by lackeys.",logDesc="Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Karen the Culler.",choiceRewards={{id=36939,qty=1},{id=37002,qty=1},{id=36998,qty=1},{id=37004,qty=1}}} end
if not DB[11869] then DB[11869]={id=11869,zoneId=3537,name="Happy as a Clam",level=72,minLevel=70,giver="Hierophant Cenius",giverType="NPC",giverId=25810,ender="Hierophant Cenius",enderType="NPC",enderId=25810,rewardNextId=11870,poiX=3203,poiY=5266,wowhead="https://www.wowhead.com/wotlk/quest=11869",image="assets/images/quests/placeholder.png",xpDiff=5,desc="To the west of us you will find Lake Kum'uya. It is, as far as we know, the only freshwater giant clam habitat in the world.$B$BOf course Nesingwary's lackeys are now using the lake as a giant pearl farm. They must be stopped! A lesson must be taught to those that would think to endanger an entire species.$B$BGo to Lake Kum'uya and locate the loot crazed divers. Slay them until the water runs red! Return to me when a proper example has been made!",logDesc="Hierophant Cenius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill 10 Loot Crazed Divers."} end
if not DB[11870] then DB[11870]={id=11870,zoneId=3537,name="The Abandoned Reach",level=72,minLevel=70,giver="Hierophant Cenius",giverType="NPC",giverId=25810,ender="Hierophant Liandra",enderType="NPC",enderId=25838,rewardNextId=11871,poiX=3203,poiY=5266,wowhead="https://www.wowhead.com/wotlk/quest=11870",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We have just gotten word from Liandra that mercenaries hired by Nesingwary are moving goods off the beach and onto the main Nesingwary shipping vessel. No doubt they plan on making a fortune from their murderous trade!$B$BShe has asked that we send assistance to the Abandoned Reach, directly south of here on the beachfront of the Borean Tundra.$B$BMake haste, Liandra awaits you there!$B",logDesc="Seek out Hierophant Liandra at the Abandoned Reach."} end
if not DB[11871] then DB[11871]={id=11871,zoneId=3537,name="Not On Our Watch",level=72,minLevel=70,giver="Hierophant Liandra",giverType="NPC",giverId=25838,ender="Hierophant Liandra",enderType="NPC",enderId=25838,rewardNextId=11872,poiX=2780,poiY=5239,wowhead="https://www.wowhead.com/wotlk/quest=11871",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Strewn across this beach, amidst the flotsam and jetsam, are crates and sacks of animal parts. It would seem that Nesingwary is in cahoots with the Northsea Freebooters. Those dirty pirates are transporting the goods that Nesingwary's murderous lackeys gather offshore. No doubt they will end up in the homes and on the backs of wealthy, unscrupulous individuals across Azeroth.$B$BThis won't happen. Not on our watch. Bring me all shipments that you find upon this beach. They'll never have them!",logDesc="Hierophant Liandra at the Abandoned Reach in the Borean Tundra wants you to recover 12 Shipments of Animal Parts."} end
if not DB[11872] then DB[11872]={id=11872,zoneId=3537,name="The Nefarious Clam Master...",level=72,minLevel=70,giver="Hierophant Liandra",giverType="NPC",giverId=25838,ender="Hierophant Cenius",enderType="NPC",enderId=25810,poiX=2780,poiY=5239,wowhead="https://www.wowhead.com/wotlk/quest=11872",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It's despicable, really, to anoint one's self as the \"Clam Master,\" as if they hold mastery over the creatures of the sea. None may make such claims!$B$BThis \"Clam Master\" must be found and slain. He was last seen at the wreckage just off the coast of the Abandoned Reach. Find him and kill him.$B$BOnce this is done, return to Hierophant Cenius at the D.E.H.T.A. Encampment, north of here, and let her know that the mission was a success.",logDesc="Slay Clam Master K and return to Hierophant Cenius at the D.E.H.T.A. Encampment.$B",choiceRewards={{id=37017,qty=1},{id=37014,qty=1},{id=37018,qty=1},{id=37019,qty=1},{id=37016,qty=1},{id=37015,qty=1}}} end
if not DB[11873] then DB[11873]={id=11873,zoneId=3537,name="Give Fizzcrank the News",level=71,minLevel=68,giver="Iggy \"Tailspin\" Cogtoggle",giverType="NPC",giverId=25807,ender="Fizzcrank Fullthrottle",enderType="NPC",enderId=25590,poiX=3522,poiY=5016,wowhead="https://www.wowhead.com/wotlk/quest=11873",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="Would you be willing to head back to the airstrip and let Fizzcrank know that I'll be along shortly to give my formal report? I've got to deal with the wreckage of my flying machine, and then I'll be on my way.$B$BI'll be certain that Fizzcrank knows that he has you to thank for my survival and the recovery effort.$B$BI only wonder what the old man would've done himself if he'd been flying with us. I miss those days.",logDesc="Make your way back to Fizzcrank Airstrip and speak with Fizzcrank Fullthrottle.",choiceRewards={{id=37275,qty=1},{id=37351,qty=1},{id=37443,qty=1},{id=37478,qty=1}}} end
if not DB[11874] then DB[11874]={id=11874,zoneId=0,name="Upper Deck Promo - Rocket Mount",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=11874",image="assets/images/quests/placeholder.png"} end
if not DB[11875] then DB[11875]={id=11875,zoneId=3703,name="Gaining the Advantage",level=70,minLevel=70,giver="Emissary Mordin",giverType="NPC",giverId=19202,ender="Emissary Mordin",enderType="NPC",enderId=19202,poiX=-1784,poiY=5315,wowhead="https://www.wowhead.com/wotlk/quest=11875",image="assets/images/quests/placeholder.png",xpDiff=5,money=88000,desc="The troops of the Shattered Sun Offensive will need every advantage they can get to beat back the allies of Kil'Jaeden. My colleagues in Stormwind have created oils which will strengthen the blades and armor of our troops.$B$BThe key ingredient, nether residue, pervades Outland  -- if you know where to look. Any master herbalist, skinner, or miner who knows the signs can gather it while plying $g his:her; trade. Those herbs, ores, and beasts native to Outland may all bear the residue.",logDesc="Bring 8 Nether Residue to Emissary Mordin in Shattrath City.",rewards={{id=18253,qty=1}}} end
if not DB[11876] then DB[11876]={id=11876,zoneId=3537,name="Help Those That Cannot Help Themselves",level=72,minLevel=70,giver="Arch Druid Lathorius",giverType="NPC",giverId=25809,ender="Arch Druid Lathorius",enderType="NPC",enderId=25809,rewardNextId=11878,poiX=3194,poiY=5282,wowhead="https://www.wowhead.com/wotlk/quest=11876",image="assets/images/quests/placeholder.png",xpDiff=5,desc="They're majestic beasts, aren't they?$B$B<Lathorius points towards the mammoths of the northern tundra.>$B$BWith each passing day their numbers diminish. Demons that call themselves hunters slay the beasts for sport and riches.$B$B<Lathorius' face contorts with anger.>$B$BIt's the whimpers that drive me to madness, $N. You can hear them, carried by the wind. The mammoth calves, trapped in the hunters' vile traps, call out to us.$B$BTake this hammer and smash those traps. Free the calves!",logDesc="Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the D.E.H.T.A. Trap Smasher to free 8 Mammoth Calves."} end
if not DB[11877] then DB[11877]={id=11877,zoneId=3523,name="Sunfury Attack Plans",level=70,minLevel=70,giver="Lord Torvos",giverType="NPC",giverId=25140,ender="Lord Torvos",enderType="NPC",enderId=25140,poiX=-1787,poiY=5315,wowhead="https://www.wowhead.com/wotlk/quest=11877",image="assets/images/quests/placeholder.png",xpDiff=4,money=44000,desc="As we press the offensive on Quel'Danas, we've discovered that Kael'thas' minions are planning a counterattack. By ordering the Sunfury blood elves, based in Netherstorm, to attack our operations in Outland, he hopes to draw troops and attention away from the Sunwell.$B$BWe must not allow this to happen, $N. Each and every blade is needed on the front lines.$B$BGo to Netherstorm and capture their attack plans. Any of the Sunfury blood elves up there could be in possession of the plans. Good luck, $N.",logDesc="Lord Torvos in Shattrath wants you to capture the Sunfury Attack Plans.",rewards={{id=35232,qty=1}}} end
if not DB[11878] then DB[11878]={id=11878,zoneId=3537,name="Khu'nok Will Know",level=72,minLevel=70,giver="Arch Druid Lathorius",giverType="NPC",giverId=25809,ender="Khu'nok the Behemoth",enderType="NPC",enderId=25862,rewardNextId=11879,poiX=3194,poiY=5282,wowhead="https://www.wowhead.com/wotlk/quest=11878",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Although you have acted valiantly in freeing the trapped calves, many of them will still die. You see, without a caretaker, these calves must fend for themselves in the wild.$B$BBut there is a way! Hope yet remains!$B$BNorth of here in the mammoth fields, bordering the Scalding Pools, you will find Khu'nok the Behemoth: a mammoth as wise as he is ancient. Take this mammoth orphan and present it to Khu'nok. He will know what to do.",logDesc="Take the Orphaned Mammoth Calf to Khu'nok the Behemoth in the Borean Tundra."} end
if not DB[11879] then DB[11879]={id=11879,zoneId=3537,name="Kaw the Mammoth Destroyer",level=72,minLevel=70,giver="Khu'nok the Behemoth",giverType="NPC",giverId=25862,ender="Arch Druid Lathorius",enderType="NPC",enderId=25809,poiX=3731,poiY=5143,wowhead="https://www.wowhead.com/wotlk/quest=11879",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You cannot defeat the being responsible for the slaughter of my kind by yourself. The mammoths of the tundra will help you!$B$BVenture forth to the plains and find a mammoth bull. He will allow you to mount him and control his movements and actions. Ride upon his back and find Kaw, north of here at Kaw's Roost. Together, you will be the instrument of Kaw's demise.$B$BDestroy Kaw's armies and take from Kaw his coveted war halberd. Return to Lathorius at the D.E.H.T.A. Encampment should you succeed.",logDesc="Kill Kaw the Mammoth Destroyer and recover Kaw's War Halberd. Deliver Kaw's War Halberd to Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra.",choiceRewards={{id=37005,qty=1},{id=37007,qty=1},{id=37008,qty=1},{id=37009,qty=1}}} end
if not DB[11880] then DB[11880]={id=11880,zoneId=3518,name="The Multiphase Survey",level=70,minLevel=70,giver="Harbinger Haronem",giverType="NPC",giverId=19475,ender="Harbinger Haronem",enderType="NPC",enderId=19475,poiX=-1928,poiY=5330,wowhead="https://www.wowhead.com/wotlk/quest=11880",image="assets/images/quests/placeholder.png",xpDiff=4,money=34000,desc="I'm sure that 'gnomish inventor' is a crackpot. He was babbling about some dark distortions that have begun to appear in the Spirit Fields around Oshu'gun in Nagrand.$B$BAccording to him, these, uh, multiphase... um, spectro-goggles will allow the wearer to see the distortions and take readings from them. He insisted that recording this data was fundamental to our campaign at the Sunwell. I think he's nuts, but I'm under orders to investigate anything that might help. Would you mind taking some readings?",logDesc="Harbinger Haronem in Shattrath City wants you to use the Multiphase Spectrographic Goggles to take 6 Multiphase Readings."} end
if not DB[11881] then DB[11881]={id=11881,zoneId=3537,name="Load'er Up!",level=71,minLevel=68,giver="Fezzix Geartwist",giverType="NPC",giverId=25849,ender="Fezzix Geartwist",enderType="NPC",enderId=25849,poiX=3477,poiY=4104,wowhead="https://www.wowhead.com/wotlk/quest=11881",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Have you seen the flying machines buzzing around? That's gnomish innovation at its finest.$B$BI've long waited to get my hands on some of their technology and a perfect opportunity has presented itself. One of their recon wings crashed in the Scalding Pools, in the southwest part of the Geyser Fields.$B$BBlow this whistle near one of the crashed machines and my trusty mule, Jenny will answer. She'll follow you and carry the salvage, but you must keep her safe. She'll begin to drop the cargo if attacked.",logDesc="Help Jenny make her way from the crash site to Fezzix Geartwist at Taunka'le Village without losing all her cargo."} end
if not DB[11882] then DB[11882]={id=11882,zoneId=-369,name="Playing with Fire",level=-1,minLevel=1,giver="Fire Eater",giverType="NPC",giverId=25962,ender="Master Fire Eater",enderType="NPC",enderId=25975,poiX=-2987,poiY=4131,wowhead="https://www.wowhead.com/wotlk/quest=11882",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Are you interested in learning some hot new skills?$b$bI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Fire Eater at any Alliance capital. They should be able to help you.",logDesc="Speak to a Master Fire Eater in any Alliance capital."} end
if not DB[11883] then DB[11883]={id=11883,zoneId=-369,name="Fire Dancing?",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=11883",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You wish the learn the art of fire dancing?$b$bWell, then. Speak to a Master Fire Dancer at any Horde capital. They should be able to help you.$B",logDesc="Speak to a Master Fire Dancer in any Horde capital."} end
if not DB[11884] then DB[11884]={id=11884,zoneId=3537,name="Ned, Lord of Rhinos...",level=72,minLevel=70,giver="Killinger the Den Watcher",giverType="NPC",giverId=25812,ender="Killinger the Den Watcher",enderType="NPC",enderId=25812,poiX=3204,poiY=5294,wowhead="https://www.wowhead.com/wotlk/quest=11884",image="assets/images/quests/placeholder.png",xpDiff=6,desc="West of here, on the high bluffs above Lake Kum'uya, roams a despicable being known as Nedar. The self proclaimed \"Lord of Rhinos\" hunts the wastes for the injured or young - rhinos unable to defend themselves against Ned's cowardly attacks. To add insult to injury, Ned has raised a rhino of his own to become his mount and bodyguard.$B$BIt is a rare thing that D.E.H.T.A. would ever call for the death of an animal, but Ned's tainted rhino must be disposed of... Kill them both and return to me. ",logDesc="Killinger the Den Watcher at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Nedar, Lord of Rhinos and his companion, \"Lunchbox.\"",choiceRewards={{id=37203,qty=1},{id=37406,qty=1},{id=37414,qty=1},{id=37520,qty=1}}} end
if not DB[11885] then DB[11885]={id=11885,zoneId=3679,name="Adversarial Blood",level=70,minLevel=70,giver="Hazzik",giverType="NPC",giverId=23306,ender="Hazzik",enderType="NPC",enderId=23306,poiX=-3411,poiY=3615,wowhead="https://www.wowhead.com/wotlk/quest=11885",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.$B$BYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  These are powerful beings you will be facing; you would do well to bring friends.",logDesc="Find the Skull Piles in the middle of the summoning circles of Skettis. Summon and defeat each of the descendants by using 10 Time-Lost Scrolls at the Skull Pile.  Return to Hazzik at Blackwind Landing.",rewards={{id=32720,qty=1}}} end
if not DB[11886] then DB[11886]={id=11886,zoneId=-369,name="Unusual Activity",level=-1,minLevel=16,ender="Earthen Ring Guide",enderType="NPC",enderId=25324,rewardNextId=11891,wowhead="https://www.wowhead.com/wotlk/quest=11886",image="assets/images/quests/placeholder.png",xpDiff=5,desc="While celebration has its place, $c, some of us must look to graver matters.$b$bWhen the festival began, we received reports from Zoram Strand about a sharp increase in Twilight Cult activity. The origins of this holiday are steeped in the very powers those madmen revere; this cannot be coincidence. Go to the camp just south of the Blackfathom Deeps entrance, in the ruins, and see if the cultists will part with information - forcefully if need be. Use this beacon to summon a guide when you find it.",logDesc="Go to the new Twilight Camp south of the Blackfathom Deeps entrance on the Zoram Strand of Ashenvale and retrieve Twilight Correspondence from the cultists, then call upon the Earthen Ring Guide using the Totemic Beacon.",rewards={{id=23247,qty=5}}} end
if not DB[11887] then DB[11887]={id=11887,zoneId=3537,name="Emergency Supplies",level=71,minLevel=68,giver="Crashed Recon Pilot",giverType="NPC",giverId=25984,ender="Fezzix Geartwist",enderType="NPC",enderId=25849,poiX=3522,poiY=4877,wowhead="https://www.wowhead.com/wotlk/quest=11887",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Rifling through the dead gnome's possessions, you come across a small packet filled with rations, tools, and a handy roll of gnomish duct tape. The contents of these kits might prove helpful to Fezzix Geartwist when it comes time for him to reassemble the wreckage of the gnomish flying machines.$B$BBringing a few of these kits to Fezzix might just be worth a nice bonus.",logDesc="Collect 7 Gnomish Emergency Toolkits from the bodies of crashed Fizzcrank Recon Pilots and bring them to Fezzix Geartwist at Taunka'le Village."} end
if not DB[11888] then DB[11888]={id=11888,zoneId=3537,name="Ride to Taunka'le Village",level=71,minLevel=68,giver="Ambassador Talonga",giverType="NPC",giverId=25978,ender="Sage Earth and Sky",enderType="NPC",enderId=25982,rewardNextId=11890,poiX=2800,poiY=6167,wowhead="https://www.wowhead.com/wotlk/quest=11888",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$R, the chieftain is making me wait... time that Taunka'le does not have!$B$BThere has been talk of your prowess. Rather than wait for Garrosh to send help, I ask you to go and help my people.$B$BTaunka'le village lies far to the northeast. Follow the road east out of the hold, turning north at the intersection. Not long after, you will come to another intersection. Follow the path east, passing south and then east of the great pools along the flood plains.$B$BSpeak with Sage Earth and Sky when you arrive.",logDesc="Speak with Sage Earth and Sky at Taunka'le Village."} end
if not DB[11889] then DB[11889]={id=11889,zoneId=3537,name="Death From Above",level=71,minLevel=68,giver="Sergeant Hammerhill",giverType="NPC",giverId=25816,ender="Sergeant Hammerhill",enderType="NPC",enderId=25816,rewardNextId=11897,poiX=2223,poiY=5322,wowhead="https://www.wowhead.com/wotlk/quest=11889",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="We're doing a good job of holding the front lines against these bugs.  Some of these cheeky fiends, however, can fly over the aforementioned front lines and are really beating down on our inner defenses.$B$BI've requisitioned reinforced fishing nets from our civilian ships.  If you've got a good enough throwing arm, they'll help you knock the enemy out of the sky.  Thin their numbers so that our defenses can hold the keep.",logDesc="Sergeant Hammerhill wants you to use the Reinforced Net to help you slay 6 Scourged Flamespitters outside of Valiance Keep."} end
if not DB[11890] then DB[11890]={id=11890,zoneId=3537,name="What Are They Up To?",level=71,minLevel=68,giver="Sage Earth and Sky",giverType="NPC",giverId=25982,ender="Sage Earth and Sky",enderType="NPC",enderId=25982,rewardNextId=11895,poiX=3419,poiY=4118,wowhead="https://www.wowhead.com/wotlk/quest=11890",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="The gnomes have run into some trouble in the pools to the west. It serves them right as they have been fouling up the land with their so-called inventions.$B$BI want you to go out to their pumping station and observe what has befallen them. Return to me after.",logDesc="Investigate the area surrounding the Fizzcrank Pumping Station. Then, return to Sage Earth and Sky at Taunka'le Village."} end
if not DB[11891] then DB[11891]={id=11891,zoneId=-369,name="An Innocent Disguise",level=-1,minLevel=16,ender="Earthen Ring Guide",enderType="NPC",enderId=25324,rewardNextId=12012,wowhead="https://www.wowhead.com/wotlk/quest=11891",image="assets/images/quests/placeholder.png",xpDiff=5,desc="According to this, it seems there is another encampment of the cultists to the northwest of the large gathering on the Zoram Strand, and they are speaking with... guests?$b$bMuch could be learned from listening to these proceedings, $r. Take this orb; it will allow you to appear as one of the native crawlers on the beach. Spy on the conversation with these \"guests\" of the cultists at the northwestern camp and report back to me when you are successful.",logDesc="Use the Orb of the Crawler to spy upon the new Twilight camp to the west of the Blackfathom Deeps entrance on the Zoram Strand in Ashenvale, then summon the Earthen Ring Guide using the Totemic Beacon.",rewards={{id=23247,qty=5}}} end
if not DB[11892] then DB[11892]={id=11892,zoneId=3537,name="The Assassination of Harold Lane",level=72,minLevel=70,giver="Arch Druid Lathorius",giverType="NPC",giverId=25809,ender="Arch Druid Lathorius",enderType="NPC",enderId=25809,poiX=3194,poiY=5282,wowhead="https://www.wowhead.com/wotlk/quest=11892",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have done much for the animals of the Borean Tundra, $N. Nesingwary's lackeys have been beaten back and taught a lesson that they will not soon forget.$B$BHarold Lane, the primary agent responsible for the mass slaughters in Nagrand, has been identified as the man in charge of Nesingwary operations in the tundra. He is stationed at Lake Kum'uya, west of here.$B$B<Lathorius hands you an intricately carved oak horn.>$B$BFind Lane and kill him. Use this horn should you require our aid.$B",logDesc="Arch Druid Lathorius at the D.E.H.T.A. Outpost in the Borean Tundra wants you to kill Harold Lane.",choiceRewards={{id=38252,qty=1},{id=38251,qty=1},{id=38250,qty=1}}} end
if not DB[11893] then DB[11893]={id=11893,zoneId=3537,name="The Power of the Elements",level=71,minLevel=68,giver="Dorain Frosthoof",giverType="NPC",giverId=25983,ender="Dorain Frosthoof",enderType="NPC",enderId=25983,poiX=3478,poiY=4096,wowhead="https://www.wowhead.com/wotlk/quest=11893",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I kept trying to tell that silly goblin his machines are unreliable.$B$BBut the power of the elements; that is deep and abiding. When my apprenticeship is over, I will wield their full power. What I know now should be sufficient to help out our friend Fezzix, though.$B$BTake this windsoul totem and plant it near any of the steam ragers to the west of the village. The totem will gather up the energies of slain elementals. Return the fully charged totem to me and I'll do the rest.",logDesc="Dorain Frosthoof at Taunka'le Village wants you to use the Windsoul Totem to gather the energy of 10 Steam Ragers."} end
if not DB[11894] then DB[11894]={id=11894,zoneId=3537,name="Patching Up",level=71,minLevel=68,giver="Fezzix Geartwist",giverType="NPC",giverId=25849,ender="Fezzix Geartwist",enderType="NPC",enderId=25849,poiX=3477,poiY=4104,wowhead="https://www.wowhead.com/wotlk/quest=11894",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="Remember all that gnomish duct tape you brought me?$B$BWell, I've found a use for it. The body of this flying machine is so banged up in places, that I'm going to need to reinforce it if I ever hope to fly.$B$BDorain over there has been telling me that the taunka use steam cured caribou leather for making watertight containers. Marsh caribou live all around the village and in the Flood Plains to the south. Get the best hides you can find and cure them over the steam vents in the Geyser Fields.",logDesc="Fezzix Geartwist at Taunka'le Village wants you to bring him 5 Steam Cured Hides.",choiceRewards={{id=37272,qty=1},{id=37388,qty=1},{id=37428,qty=1},{id=37526,qty=1}}} end
if not DB[11895] then DB[11895]={id=11895,zoneId=3537,name="Master the Storm",level=71,minLevel=68,giver="Sage Earth and Sky",giverType="NPC",giverId=25982,ender="Sage Earth and Sky",enderType="NPC",enderId=25982,rewardNextId=11896,poiX=3419,poiY=4118,wowhead="https://www.wowhead.com/wotlk/quest=11895",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="From what you describe, the creatures of metal should be easy to deal with. But first, you must master the storm.$B$BBehind me in the lodge is a totem. When you are ready, focus your will upon it and the storm will come. You must defeat the storm and in so doing take its essence into yourself.$B$BIf others are there, it is enough that you all work together to defeat it. Return to me after, $c.",logDesc="Defeat the Storm Tempest and then return to Sage Earth and Sky at Taunka'le Village."} end
if not DB[11896] then DB[11896]={id=11896,zoneId=3537,name="Weakness to Lightning",level=71,minLevel=68,giver="Sage Earth and Sky",giverType="NPC",giverId=25982,ender="Sage Earth and Sky",enderType="NPC",enderId=25982,rewardNextId=11907,poiX=3419,poiY=4118,wowhead="https://www.wowhead.com/wotlk/quest=11896",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="You now have the power of the storm within you. I will give you the means to focus that power and weaken the robots in the pools.$B$BTake this lightning rod. Use it against the robotic creations of the mechagnomes you find within the greater pools area to the west. Do not worry about using it against the mechagnomes themselves; Greatmother Taiga has other plans for them.$B$BOnce the robots are weakened by the power of the storm, dismantle them utterly!",logDesc="While weakened by the Power of the Storm, destroy any 15 of the robotic units, except the mechagnomes, in the greater pools area surrounding the Fizzcrank Pumping Station.$B$BAfterward, return to Sage Earth and Sky at Taunka'le Village."} end
if not DB[11897] then DB[11897]={id=11897,zoneId=3537,name="Plug the Sinkholes",level=71,minLevel=68,giver="Sergeant Hammerhill",giverType="NPC",giverId=25816,ender="Sergeant Hammerhill",enderType="NPC",enderId=25816,poiX=2223,poiY=5322,wowhead="https://www.wowhead.com/wotlk/quest=11897",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Scourge are showing no sign of letting up, $N.  It's those blasted sinkholes; they connect to tunnels all the way to Icecrown for all we know.  Giant undead worms burrow under the ground to create them.$B$BIf there's something years of mining has taught me it's that without support beams, tunnels will cave in easily after an explosion.$B$BTake these explosives and place them at the entrance to the sinkholes up on the ridge beyond the beach to the west.  Come back after you've collapsed them.",logDesc="Sergeant Hammerhill wants you to use the Incendiary Explosives to collapse the sinkholes southwest and northwest of Valiance Keep.",choiceRewards={{id=36884,qty=1},{id=36885,qty=1},{id=36886,qty=1},{id=36887,qty=1}}} end
if not DB[11898] then DB[11898]={id=11898,zoneId=3537,name="Breaking Through",level=71,minLevel=68,giver="Chieftain Wintergale",giverType="NPC",giverId=24703,ender="Chieftain Wintergale",enderType="NPC",enderId=24703,poiX=3466,poiY=4196,wowhead="https://www.wowhead.com/wotlk/quest=11898",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="On the lowest tier of the Temple City, there is a gray altar bathed in light. Step into it to gain entry to the dread necropolis Naxxanar.$B$BBe cautious, $N. Prince Valanar will certainly be defended by his personal retainers, who will give their lives to keep you from ascending to the top level of the necropolis.$B$BYou must find your way through the necropolis to the prince's seat. If you fail to defeat him, $N, I fear my people will never know the safety Icemist offers.",logDesc="Defeat Prince Valanar and his lieutenants, Vanthryn the Merciless and Luthion the Vile, then report to Chieftain Wintergale at Taunka'le Village.",choiceRewards={{id=38232,qty=1},{id=38230,qty=1},{id=38231,qty=1}}} end
if not DB[11899] then DB[11899]={id=11899,zoneId=3537,name="Souls of the Decursed",level=71,minLevel=68,giver="Greatmother Taiga",giverType="NPC",giverId=25602,ender="Greatmother Taiga",enderType="NPC",enderId=25602,poiX=3481,poiY=4115,wowhead="https://www.wowhead.com/wotlk/quest=11899",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="The mechagnomes in the pools to the west are a great mystery to us. They appeared not long after the gnomes disappeared from their pumping station and its environs.$B$BThey are an unnatural danger and must be dealt with.$B$BTake this soulcatcher and use it on the remains of the mechagnomes to capture their souls. When you return, we will set them free so that we might find out what happened.",logDesc="Use The Greatmother's Soulcatcher to capture the souls of 10 Fizzcrank mechagnomes. Then, return to Greatmother Taiga at Taunka'le Village once you have done so."} end
if not DB[11900] then DB[11900]={id=11900,zoneId=4024,name="Reading the Meters",level=71,minLevel=69,giver="Archmage Berinand",giverType="NPC",giverId=25314,ender="Archmage Berinand",enderType="NPC",enderId=25314,rewardNextId=11905,poiX=3576,poiY=6672,wowhead="https://www.wowhead.com/wotlk/quest=11900",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I had hoped that the Nexus' impact was limited to this region. Recently though, reports have flooded in from all over Azeroth suggesting that geologic instability is growing exponentially!$b$bI need the Nexus monitored regularly as I work to develop a solution.$b$bI've placed sensitive instruments around Coldarra, disguised as Malygos' scrying orbs. One lies in the trench near the Nexus, and three are hidden in the structures around the valley's perimeter. Visit each and return to me with their readings.",logDesc="Archmage Berinand at the Transitus Shield has asked you to collect the readings from his instruments in Coldarra."} end
if not DB[11901] then DB[11901]={id=11901,zoneId=3537,name="Military?  What Military?",level=71,minLevel=68,giver="Gerald Green",giverType="NPC",giverId=26083,rewardNextId=11902,poiX=2483,poiY=5215,wowhead="https://www.wowhead.com/wotlk/quest=11901",image="assets/images/quests/placeholder.png",xpDiff=4,desc="There's Scourge everywhere, $c.  We've organized the farmers and miners into a militia, but this just won't cut it.$B$BThe one detachment of troops that Valiance Keep sent is defending the mine.  We haven't heard from them in days!$B$BIf you really wish to help us, why don't you go to the mine and see what's going on?  Maybe we can get them to send us some reinforcements.",logDesc="Gerald Green in Farshire wants you to go into the mine to the north and find out what happened to the military detachment that was sent there."} end
if not DB[11902] then DB[11902]={id=11902,zoneId=3537,name="Pernicious Evidence",level=71,minLevel=68,ender="Gerald Green",enderType="NPC",enderId=26083,rewardNextId=11903,wowhead="https://www.wowhead.com/wotlk/quest=11902",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The sacks of grain emanate the foul stench you've come to associate with the Plague.  This probably explains what happened to the footmen defending the mine.$B$BYou'd best bring word back to Gerald Green.",logDesc="Return to Gerald Green in Farshire."} end
if not DB[11903] then DB[11903]={id=11903,zoneId=3537,name="It's Time for Action",level=71,minLevel=68,giver="Gerald Green",giverType="NPC",giverId=26083,ender="Gerald Green",enderType="NPC",enderId=26083,rewardNextId=11904,poiX=2483,poiY=5215,wowhead="https://www.wowhead.com/wotlk/quest=11903",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Well, $N.  With the last of our military in Farshire dead or worse, we can do but one thing: fight these Scourge ourselves.$B$BWe have deployed militia in what remains of Farshire.  Without your help, they've but little hope of winning.  Go and lend them a hand.  Me and the lads will watch this path.  We can't let the Scourge break through!",logDesc="Gerald Green in Farshire wants you to kill 14 Plagued Scavengers.",choiceRewards={{id=37208,qty=1},{id=37402,qty=1},{id=37543,qty=1},{id=37484,qty=1}}} end
if not DB[11904] then DB[11904]={id=11904,zoneId=3537,name="Fruits of Our Labor",level=71,minLevel=68,giver="Gerald Green",giverType="NPC",giverId=26083,ender="Gerald Green",enderType="NPC",enderId=26083,rewardNextId=11962,poiX=2483,poiY=5215,wowhead="https://www.wowhead.com/wotlk/quest=11904",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Scourge just keeps coming... but we can't give up!  Listen, $N.  Inside that mine there's a cart with the last of the ore the Alliance is going to see on this side of the continent for a long time.$B$BThe problem is the cart release is locked.  When the military went in there, Captain Jacobs commandeered all the important equipment, including the cart release key.$B$BThe plague that affected the soldiers in the mine must also have affected Jacobs.  Get the key from him and salvage the ore.",logDesc="Go to the mine in Farshire, obtain the Cart Release Key from Captain Jacobs and use it to release the ore cart.  Return to Gerald Green in Farshire when you've completed this task."} end
if not DB[11905] then DB[11905]={id=11905,zoneId=4265,name="Postponing the Inevitable",level=71,minLevel=69,giver="Archmage Berinand",giverType="NPC",giverId=25314,ender="Archmage Berinand",enderType="NPC",enderId=25314,poiX=3576,poiY=6672,wowhead="https://www.wowhead.com/wotlk/quest=11905",image="assets/images/quests/placeholder.png",xpDiff=8,money=188000,desc="I've determined the cause of the instability!$b$bAzeroth's ley lines are being redirected to the Nexus. It's fascinating! If only I could spend the remainder of my days studying this anomaly....$b$bSadly, I must focus on the immediate crisis. The influx of arcane energies is tearing a rift between dimensions.$b$bDeep inside the Nexus, the fabric of our universe is being weakened. I cannot stop it, but I've discovered a way to slow it down.$b$bTake this into the Nexus and activate it near the forming rift.",logDesc="Archmage Berinand in the Transitus Shield wants you to use the Interdimensional Refabricator near the rift in the Nexus.",choiceRewards={{id=42758,qty=1},{id=42761,qty=1},{id=42763,qty=1},{id=42765,qty=1}}} end
if not DB[11906] then DB[11906]={id=11906,zoneId=3537,name="Cleaning Up the Pools",level=71,minLevel=68,giver="Iron Eyes",giverType="NPC",giverId=26104,ender="Iron Eyes",enderType="NPC",enderId=26104,poiX=3452,poiY=4137,wowhead="https://www.wowhead.com/wotlk/quest=11906",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="<A single tear rolls down the face of Iron Eyes.>$B$BI have heard that you are heading back into the pools to the west. I have something for you to do while you are out there, $r.$B$BThe gnomes, who care nothing for the land, have polluted it with their machinery. I want you to pick up any spare parts that you come across.$B$BReturn them to me here. I will see to it that they are properly disposed of before we leave this place for good.",logDesc="Collect 15 Fizzcrank Spare Parts and deliver them to Iron Eyes at Taunka'le Village.",choiceRewards={{id=37275,qty=1},{id=37351,qty=1},{id=37443,qty=1},{id=37478,qty=1}}} end
if not DB[11907] then DB[11907]={id=11907,zoneId=3537,name="The Sub-Chieftains",level=71,minLevel=68,giver="Sage Earth and Sky",giverType="NPC",giverId=25982,ender="Sage Earth and Sky",enderType="NPC",enderId=25982,poiX=3419,poiY=4118,wowhead="https://www.wowhead.com/wotlk/quest=11907",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="It is known that Gearmaster Mechazod has four sub-chieftains that manage the robots in the pools.$B$BWe must put an end to them!$B$BOur longrunners and snow trackers say that if you were to turn the valves at the west point, north point, mid point and south point stations, each of his sub-chieftains would come quickly to prevent you from fouling their operations.$B$BThe stations are centered on the spinning lights in the pools surrounding the pumping station.$B$BHurry, $N!",logDesc="Defeat Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Sage Earth and Sky at Taunka'le Village.",choiceRewards={{id=37054,qty=1},{id=37231,qty=1},{id=37073,qty=1},{id=37072,qty=1},{id=37357,qty=1}}} end
if not DB[11908] then DB[11908]={id=11908,zoneId=3537,name="Reference Material",level=71,minLevel=68,giver="Jeremiah Hawning",giverType="NPC",giverId=26084,ender="Jeremiah Hawning",enderType="NPC",enderId=26084,rewardNextId=12035,poiX=2476,poiY=5216,wowhead="https://www.wowhead.com/wotlk/quest=11908",image="assets/images/quests/placeholder.png",xpDiff=4,money=47000,desc="I was in charge of the harvest golems - an important job until the Scourge destroyed most of our farmlands.  I've an idea that would make the golems useful again, however.$B$BI think I can rewire the harvest collectors so they'll give us a hand fighting the Scourge.$B$BI'm not an expert at this just yet, so I'm going to need my manual.  The problem is, I left it at the workshop... which happens to be that burning building next to the mine.  Think you could go salvage it?",logDesc="Jeremiah Hawning wants you to retrieve the book \"Fields, Factories and Workshops\" from the burning building next to the mine in Farshire."} end
if not DB[11909] then DB[11909]={id=11909,zoneId=3537,name="Defeat the Gearmaster",level=72,minLevel=68,giver="Greatmother Taiga",giverType="NPC",giverId=25602,ender="Greatmother Taiga",enderType="NPC",enderId=25602,poiX=3481,poiY=4115,wowhead="https://www.wowhead.com/wotlk/quest=11909",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="Clearly this Gearmaster Mechazod creature is not in his right mind. If his offer of a cure and immortality means all of us becoming robotic slaves then he must be stopped!$B$BThe winds that guide me whisper that he's atop the pumping station out in the middle of the pools to the west.$B$BMost likely, he'll be found in the command hut on top of the structure. Go inside and research his works.$B$B$N, you must confront Mechazod if we are to survive!",logDesc="Research the Gearmaster's Manual and return Mechazod's Head to Greatmother Taiga at Taunka'le Village.",choiceRewards={{id=37122,qty=1},{id=37537,qty=1},{id=37522,qty=1},{id=37547,qty=1},{id=37535,qty=1}}} end
if not DB[11910] then DB[11910]={id=11910,zoneId=4024,name="Secrets of the Ancients",level=71,minLevel=69,giver="Archmage Berinand",giverType="NPC",giverId=25314,ender="Archmage Berinand",enderType="NPC",enderId=25314,rewardNextId=11911,poiX=3576,poiY=6672,wowhead="https://www.wowhead.com/wotlk/quest=11910",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="It's become clear that the instability in the region has had an effect on its indigenous creatures.$b$bI've taken a particular interest in the Glacial Ancients and their recent adaptations. I suspect that their transformation into these 'Magic-bound' Ancients may hold clues to our predicament here.$b$bFor my studies, I'll need samples from both. Do hurry....",logDesc="Archmage Berinand in the Transitus Shield wants you to collect 3 Glacial Splinters and 3 Magic-Bound Splinters from the Ancients in Coldarra."} end
if not DB[11911] then DB[11911]={id=11911,zoneId=4265,name="Quickening",level=71,minLevel=69,giver="Archmage Berinand",giverType="NPC",giverId=25314,ender="Archmage Berinand",enderType="NPC",enderId=25314,poiX=3576,poiY=6672,wowhead="https://www.wowhead.com/wotlk/quest=11911",image="assets/images/quests/placeholder.png",xpDiff=8,money=188000,desc="Though we may be witnessing the end of our existence, I can't help but marvel. I've learned more in my short time here than in decades of studies.$b$bThese Ancients are being exposed to incredible levels of arcane energy. It's literally transforming them into something... different.$b$bI'm confident that there's another stage in their metamorphosis. I'll need you to actually enter the Nexus, $n, and find me some evidence of their final state.$b$bDo be careful....",logDesc="Archmage Berinand in the Transitus Shield wants you to enter the Nexus and collect 5 Arcane Splinters from Crystalline Protectors.",choiceRewards={{id=42760,qty=1},{id=42762,qty=1},{id=42766,qty=1},{id=42767,qty=1},{id=42768,qty=1}}} end
if not DB[11912] then DB[11912]={id=11912,zoneId=4024,name="Nuts for Berries",level=71,minLevel=69,giver="Librarian Serrah",giverType="NPC",giverId=26110,ender="Librarian Serrah",enderType="NPC",enderId=26110,rewardNextId=11914,poiX=3576,poiY=6640,wowhead="https://www.wowhead.com/wotlk/quest=11912",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Oh! What a relief it is to see a fresh face. I was beginning to feel we had been forsaken.$b$bOur supply lines were cut off days ago, and things have been looking - well, bleak. To be honest, this was a suicide mission to begin with if you ask me.$b$bMaybe I'm simply not cut out for all of this violence - to say nothing of the bitter cold! I'd much rather be back in Dalaran studying ancient texts.$b$bTo the point, our food supply is nearly spent. Please, gather what you can and bring it to me.",logDesc="Librarian Serrah in the Transitus Shield wants you to gather 10 Frostberries from the Frostberry Bushes in Coldarra."} end
if not DB[11913] then DB[11913]={id=11913,zoneId=3537,name="Take No Chances",level=71,minLevel=68,giver="Wendy Darren",giverType="NPC",giverId=26085,ender="Wendy Darren",enderType="NPC",enderId=26085,poiX=2485,poiY=5211,wowhead="https://www.wowhead.com/wotlk/quest=11913",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I heard what you told Gerald and I don't like it one bit.  If cultists managed to poison the grain in the mines with their foul plague, they could've easily done the same with the grain outside.$B$BWe don't have time to sort the good grain from the bad.  We must act quickly and burn it all.$B$BTake this torch and set fire to any sacks of grain you find out here.  It would be a tragedy if we survived this attack only to succumb to the plague afterwards.",logDesc="Wendy Darren wants you to use Wendy's Torch to burn 8 sacks of Farshire Grain.",choiceRewards={{id=37205,qty=1},{id=37404,qty=1},{id=37524,qty=1},{id=37481,qty=1}}} end
if not DB[11914] then DB[11914]={id=11914,zoneId=4024,name="Keep the Secret Safe",level=71,minLevel=69,giver="Librarian Serrah",giverType="NPC",giverId=26110,ender="Librarian Serrah",enderType="NPC",enderId=26110,poiX=3576,poiY=6640,wowhead="https://www.wowhead.com/wotlk/quest=11914",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Our existence here depends entirely upon staying hidden. Should the shield fail, even for a moment, Malygos' minions would have us.$b$bOne of my responsibilities is to rejuvenate the warmages' mana levels so their focus doesn't falter. With our supply lines lost, I've been forced to improvise.$b$bI could use your help, $n.$b$bVery near the Nexus, Arcane Serpents feast on the abundant magical energies. Once defeated, they will yield a mana essence that I can make use of.",logDesc="Librarian Serrah in the Transitus Shield needs you to kill Arcane Serpents near the Nexus and collect 5 Nexus Mana Essences from them.",choiceRewards={{id=37434,qty=1},{id=37383,qty=1},{id=37512,qty=1},{id=37559,qty=1}}} end
if not DB[11915] then DB[11915]={id=11915,zoneId=-369,name="Playing with Fire",level=-1,minLevel=1,giver="Flame Eater",giverType="NPC",giverId=25994,ender="Master Flame Eater",enderType="NPC",enderId=26113,poiX=-3051,poiY=2391,wowhead="https://www.wowhead.com/wotlk/quest=11915",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Are you interested in learning some hot new skills?$b$bI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Flame Eater at any Horde capital. They should be able to help you.",logDesc="Speak to a Master Flame Eater in any Horde capital."} end
if not DB[11916] then DB[11916]={id=11916,zoneId=3537,name="Hellscream's Champion",level=71,minLevel=68,giver="Garrosh Hellscream",giverType="NPC",giverId=25237,ender="Chieftain Wintergale",enderType="NPC",enderId=24703,poiX=2838,poiY=6187,wowhead="https://www.wowhead.com/wotlk/quest=11916",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You have faced all challenges that have been set before you and squashed them beneath your boot heel. It is because of you, $N, that the Horde is now firmly entrenched in Northrend.$B$BBut our work has only just begun. We must march to Icecrown and we must tear down its walls!$B$BYour next assignment begins to the east, at Taunka'le Village. Our taunka allies are in dire straits and require aid. Secure transport from the stable master, Durkot Wolfbrother, and seek out Chieftain Wintergale at Taunka'le.",logDesc="Seek out Chieftain Wintergale at Taunka'le Village.",choiceRewards={{id=38238,qty=1},{id=38237,qty=1},{id=38240,qty=1},{id=38241,qty=1},{id=38242,qty=1},{id=38239,qty=1}}} end
if not DB[11917] then DB[11917]={id=11917,zoneId=-369,name="Striking Back",level=22,minLevel=16,ender="Earthen Ring Elder",enderType="NPC",enderId=26221,wowhead="https://www.wowhead.com/wotlk/quest=11917",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="We must act to preserve the balance! Time is against us.$b$bReturn to the camp on the Zoram Strand with the large ice stones. They use them to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...",logDesc="Slay the Frostwave Lieutenant summoned from the Ice Stone located on Zoram Strand in Ashenvale, then return to the Earthen Ring Elder in a capital city.",rewards={{id=23247,qty=10}}} end
if not DB[11918] then DB[11918]={id=11918,zoneId=4024,name="Basic Training",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26117,ender="3",enderType="NPC",enderId=26117,rewardNextId=11936,poiX=3570,poiY=6650,wowhead="https://www.wowhead.com/wotlk/quest=11918",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="This is war, mortal, and we are the tip of the spear.$b$bYour little spats over land or currency pale in comparison to this conflict. We face the aspect Malygos and his entire blue dragonflight. All you need to know is that if he is victorious, this world shall be no more.$b$bWe are but few here, and we fly against many. Our deaths are all but a certainty, and our ultimate success lies in merely delaying our enemy.$b$bGo now. Busy yourself while I decide what to do with you.",logDesc="Raelorasz at the Transitus Shield wants you to slay 10 Coldarra Spellweavers."} end
if not DB[11919] then DB[11919]={id=11919,zoneId=4024,name="Drake Hunt",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26117,ender="3",enderType="NPC",enderId=26117,rewardNextId=11931,poiX=3570,poiY=6650,wowhead="https://www.wowhead.com/wotlk/quest=11919",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="The blues have begun to cover their drakes in mysterious runes. I must discover their significance.$b$b<Raelorasz pokes his hand with a spear and coats the tip with his blood.>$b$bTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.$b$bTheir hatchlings feed around the northwest edge of the valley.",logDesc="Raelorasz wants you to use Raelorasz's Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield.",choiceRewards={{id=37226,qty=1},{id=37382,qty=1},{id=37435,qty=1},{id=37513,qty=1}}} end
if not DB[11920] then DB[11920]={id=11920,zoneId=3537,name="Cultists Among Us",level=71,minLevel=68,ender="Captain \"Lefty\" Lugsail",enderType="NPC",enderId=25298,wowhead="https://www.wowhead.com/wotlk/quest=11920",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship.$B$BPerhaps he is to be found above deck.",logDesc="Speak to Captain \"Lefty\" Lugsail above the Stormbreaker in Valiance Keep."} end
if not DB[11921] then DB[11921]={id=11921,zoneId=-369,name="More Torch Tossing",level=-1,minLevel=1,ender="Master Fire Eater",enderType="NPC",enderId=25975,wowhead="https://www.wowhead.com/wotlk/quest=11921",image="assets/images/quests/placeholder.png",xpDiff=5,money=1500,desc="Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...$B$BYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.$B$BReady?",logDesc="Win the torch tossing game, then speak with the Master Fire Eater.",rewards={{id=23247,qty=5}}} end
if not DB[11922] then DB[11922]={id=11922,zoneId=-369,name="Torch Tossing",level=-1,minLevel=1,ender="Master Flame Eater",enderType="NPC",enderId=26113,rewardNextId=11923,wowhead="https://www.wowhead.com/wotlk/quest=11922",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!$B$BTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!$B$BHit enough marked braziers before the time limit, then come back here... for your next lession.",logDesc="Win the torch tossing game, then speak with the Master Flame Eater.",rewards={{id=23247,qty=5}}} end
if not DB[11923] then DB[11923]={id=11923,zoneId=-369,name="Torch Catching",level=-1,minLevel=1,ender="Master Flame Eater",enderType="NPC",enderId=26113,wowhead="https://www.wowhead.com/wotlk/quest=11923",image="assets/images/quests/placeholder.png",xpDiff=5,money=350,desc="Now that you can throw a torch, let's see if you can catch one!$B$BTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four in a row, then come back to me.$B$BCareful! They're dangerous if they hit the ground!  And don't miss any catches!  If you do then you'll have to go back to the bonfire and start over.  Good luck!",logDesc="Catch 4 torches in a row, then speak with the Master Flame Eater.",rewards={{id=34599,qty=5},{id=23247,qty=5}}} end
if not DB[11924] then DB[11924]={id=11924,zoneId=-369,name="More Torch Catching",level=-1,minLevel=1,ender="Master Fire Eater",enderType="NPC",enderId=25975,wowhead="https://www.wowhead.com/wotlk/quest=11924",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?$B$BLet's see...",logDesc="Catch 10 torches in a row, then speak with the Master Fire Eater.",rewards={{id=23247,qty=5}}} end
if not DB[11925] then DB[11925]={id=11925,zoneId=-369,name="More Torch Catching",level=-1,minLevel=1,ender="Master Flame Eater",enderType="NPC",enderId=26113,wowhead="https://www.wowhead.com/wotlk/quest=11925",image="assets/images/quests/placeholder.png",xpDiff=5,money=400,desc="Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?$B$BLet's see...",logDesc="Catch 10 torches in a row, then speak with the Master Flame Eater.",rewards={{id=23247,qty=5}}} end
if not DB[11926] then DB[11926]={id=11926,zoneId=-369,name="More Torch Tossing",level=-1,minLevel=1,ender="Master Flame Eater",enderType="NPC",enderId=26113,wowhead="https://www.wowhead.com/wotlk/quest=11926",image="assets/images/quests/placeholder.png",xpDiff=5,money=400,desc="Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...$B$BYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.$B$BReady?",logDesc="Win the torch tossing game, then speak with the Master Flame Eater.",rewards={{id=23247,qty=5}}} end
if not DB[11927] then DB[11927]={id=11927,zoneId=3537,name="Word on the Street",level=71,minLevel=68,giver="Mark Hanes",giverType="NPC",giverId=26155,ender="Leryssa",enderType="NPC",enderId=25251,rewardNextId=11599,poiX=2226,poiY=5298,wowhead="https://www.wowhead.com/wotlk/quest=11927",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hey, $N.  There's a girl in the inn that's asking about you.  Her name's Leryssa.$B$BI don't think she knows you, but she said she needed your help.  She sounded really desperate.",logDesc="Find Leryssa at the inn in Valiance Keep"} end
if not DB[11928] then DB[11928]={id=11928,zoneId=3537,name="Farshire",level=71,minLevel=68,giver="Sergeant Hammerhill",giverType="NPC",giverId=25816,ender="Gerald Green",enderType="NPC",enderId=26083,rewardNextId=11901,poiX=2223,poiY=5322,wowhead="https://www.wowhead.com/wotlk/quest=11928",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My lads should be able to take it from here, $N.  Valiance Keep is built to take a beating far worse than this.  I worry about our farmlands and mine in Farshire, however.$B$BWe sent a full detachment to protect our mining operations right before the invasion - they should be able to defend the civilians.$B$BGerald Green's in charge of the villagers there. There's a passage out of the northern wall out of Valiance Keep; it'll take you straight to him.  See what you can do to help them.",logDesc="Travel to Farshire in Borean Tundra and speak to Gerald Green."} end
if not DB[11929] then DB[11929]={id=11929,zoneId=3537,name="The Fall of Taunka'le Village",level=72,minLevel=71,giver="Chieftain Wintergale",giverType="NPC",giverId=24703,ender="Mother Tauranook",enderType="NPC",enderId=26158,rewardNextId=11930,poiX=3466,poiY=4196,wowhead="https://www.wowhead.com/wotlk/quest=11929",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We are lost, $N. This place has been our home for many generations, but it is no longer safe. There remains only death... Death and a memory of what used to be.$B$BI have called for the evacuation of Taunka'le. All remaining taunka must leave at once and make their way to our capital city, Icemist, located in the Dragonblight.$B$B<Wintergale points east.>$B$BYou must help get my people to safety, $N. Mother Tauranook awaits you at the village gates. Hurry! The Scourge closes in from all sides!",logDesc="Speak to Mother Tauranook outside the gates of Taunka'le Village."} end
if not DB[11930] then DB[11930]={id=11930,zoneId=3537,name="Across Transborea",level=72,minLevel=71,giver="Mother Tauranook",giverType="NPC",giverId=26158,ender="Wartook Iceborn",enderType="NPC",enderId=26156,rewardNextId=11977,poiX=3437,poiY=4056,wowhead="https://www.wowhead.com/wotlk/quest=11930",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The path across Transborea, to the east, is the only way to reach the Dragonblight. Many perils await you as you make your journey across the tundra. Beware the Scourge and its influence upon the beasts of the land. Rumors have started to spread about our very own taunka brothers and sisters rising from the dead and attacking caravans on their way to the Dragonblight! Defend your caravan and get the evacuees to safety!$B$BWartook Iceborn waits for you across the bridge leading into the Dragonblight.",logDesc="Escort the Taunka'le Evacuees across Transborea to Wartook Iceborn on the border of the Dragonblight.$B"} end
if not DB[11931] then DB[11931]={id=11931,zoneId=4024,name="Cracking the Code",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26117,ender="3",enderType="NPC",enderId=26117,poiX=3570,poiY=6650,wowhead="https://www.wowhead.com/wotlk/quest=11931",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I sense a distinct peculiarity in the drakes here but the meaning of the runes that cover their bodies still eludes me.$b$bWithout a codex, it will take more time than we can afford for me to interpret them.$b$bNot far from here is a Kirin Tor traitor, Caleras, who is likely to have a copy of the tome I require. His underlings hold the runes I will need for my translation.$b$bHurry, mortal. Malygos gains strength with every passing moment.",logDesc="Raelorasz at the Transitus Shield wants you to get the Azure Codex from Inquisitor Caleras and collect 3 Shimmering Runes from his Coldarra Spellbinders."} end
if not DB[11932] then DB[11932]={id=11932,zoneId=3537,name="Cowards and Fools",level=71,minLevel=68,giver="Private Brau",giverType="NPC",giverId=25395,ender="Ataika",enderType="NPC",enderId=26169,rewardNextId=12086,poiX=2152,poiY=5303,wowhead="https://www.wowhead.com/wotlk/quest=11932",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Listen, $N.  No offense, but the operation they put Thassarian in charge of was pure suicide.$B$BA handful of our men were to launch an attack on the biggest Scourge presence in the area.  Call me crazy, but storming a Scourge ziggurat outside a plagued Nerubian city with a dozen men ain't my idea of fun.$B$BIf you're still interested in finding Thassarian, we were supposed to arrange for passage east with a tuskarr by the name of Ataika in Kaskala to the northeast.  Good luck with your fool's errand.",logDesc="Speak to Ataika in Kaskala, northeast of Valiance Keep."} end
if not DB[11933] then DB[11933]={id=11933,zoneId=-369,name="Stealing the Exodar's Flame",level=-1,minLevel=1,ender="Festival Talespinner",enderType="NPC",enderId=16818,wowhead="https://www.wowhead.com/wotlk/quest=11933",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="This flame, stolen from the heart of the Exodar itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...",logDesc="Return the Flame of the Exodar to the Festival Talespinner.",rewards={{id=23247,qty=25}},choiceRewards={{id=23435,qty=5},{id=23327,qty=5},{id=23326,qty=5},{id=23211,qty=5},{id=23246,qty=10},{id=34684,qty=10}}} end
if not DB[11934] then DB[11934]={id=11934,zoneId=-371,name="Unlocking Your Potential [PH]",level=15,minLevel=15,wowhead="https://www.wowhead.com/wotlk/quest=11934",image="assets/images/quests/placeholder.png",xpDiff=5,money=700,desc="Today you unlock a page in your spellbook, one you may not have realized it was there.  Bring me something, and I'll open it up for you.",logDesc="Bring this dude some stuff."} end
if not DB[11935] then DB[11935]={id=11935,zoneId=-369,name="Stealing Silvermoon's Flame",level=-1,minLevel=1,ender="Festival Loremaster",enderType="NPC",enderId=16817,wowhead="https://www.wowhead.com/wotlk/quest=11935",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="This flame, stolen from Silvermoon, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...",logDesc="Return the Flame of Silvermoon to the Festival Loremaster.",rewards={{id=23247,qty=25}},choiceRewards={{id=23435,qty=5},{id=23327,qty=5},{id=23326,qty=5},{id=23211,qty=5},{id=23246,qty=10},{id=34684,qty=10}}} end
if not DB[11936] then DB[11936]={id=11936,zoneId=4024,name="Hatching a Plan",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26117,ender="3",enderType="NPC",enderId=26117,rewardNextId=11919,poiX=3570,poiY=6650,wowhead="https://www.wowhead.com/wotlk/quest=11936",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Our goals here are simple. We are to remain hidden from Malygos, observe his brood, and thwart his efforts wherever possible. To that end, I have a task for you.$b$bThe blues are laying their eggs at the base of the Nexus. Exposure to so much arcane energy will surely make them hatch sooner, and there's no telling what effect it will have on their spawn.$b$bI don't intend to find out. Slay the local wyrmkin and use their frozen axes to break the eggs.",logDesc="Raelorasz at the Transitus Shield wants you to kill Coldarra Wyrmkin and use their frozen axes to break 5 blue dragon eggs."} end
if not DB[11937] then DB[11937]={id=11937,zoneId=-22,name="FLAG - all torch return quests are complete",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=11937",image="assets/images/quests/placeholder.png"} end
if not DB[11938] then DB[11938]={id=11938,zoneId=3537,name="Buying Some Time",level=72,minLevel=68,giver="Thassarian",giverType="NPC",giverId=26170,ender="Thassarian",enderType="NPC",enderId=26170,rewardNextId=11942,poiX=3296,poiY=3683,wowhead="https://www.wowhead.com/wotlk/quest=11938",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now that we have this phylactery, I shouldn't have any problems getting the information I need.  It won't take long for the Scourge in the Temple City to notice something's up, however.$B$BI won't be able to fend off a full scale attack here.  Or maybe I would... but I'd rather not find out.$B$BI want you to head down there and inflict some casualties.  Hopefully they'll be distracted long enough for these two to spill their guts... figuratively, of course.  Take Lurid with you, he might be of aid.",logDesc="Thassarian at the Wailing Ziggurat in Borean Tundra wants you to inflict 20 casualties against the Scourge inside the Temple City of En'kilah.  Use Lurid's Bones if you need assistance.",choiceRewards={{id=37271,qty=1},{id=37393,qty=1},{id=37425,qty=1},{id=38212,qty=1}}} end
if not DB[11939] then DB[11939]={id=11939,zoneId=4024,name="?????",level=71,minLevel=69,wowhead="https://www.wowhead.com/wotlk/quest=11939",image="assets/images/quests/placeholder.png",desc="[PH]Quest to close this questline - summon and kill a mature drake (Elite?) - Fight a drake in the dungeon?"} end
if not DB[11940] then DB[11940]={id=11940,zoneId=4024,name="Drake Hunt",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26117,ender="3",enderType="NPC",enderId=26117,poiX=3570,poiY=6650,wowhead="https://www.wowhead.com/wotlk/quest=11940",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="I need more drake hatchlings to continue researching the runes covering their bodies.$b$bThey can be found around the northwest edge of the valley....$b$b<Raelorasz pokes his hand with a spear and coats the tip with his blood.>$b$bTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.",logDesc="Raelorasz wants you to use the Blood-tipped Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield."} end
if not DB[11941] then DB[11941]={id=11941,zoneId=4024,name="Puzzling...",level=71,minLevel=69,ender="3",enderType="NPC",enderId=26117,rewardNextId=11943,wowhead="https://www.wowhead.com/wotlk/quest=11941",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Something about this scrap of metal prevents you from casting it aside.$b$bPerhaps Raelorasz might be able to shed some light on its purpose.",logDesc="Bring the Scintillating Fragment to Raelorasz at the Transitus Shield."} end
if not DB[11942] then DB[11942]={id=11942,zoneId=3537,name="Words of Power",level=72,minLevel=68,giver="Thassarian",giverType="NPC",giverId=26170,ender="Thassarian",enderType="NPC",enderId=26170,rewardNextId=12019,poiX=3296,poiY=3683,wowhead="https://www.wowhead.com/wotlk/quest=11942",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The lich has spoken, $N.  The high priests of En'kilah hold the secret to entering Naxxanar.$B$BGo to the Spire of Blood, the Spire of Pain and the Spire of Decay and slay each of the priests.$B$BReturn once you've obtained the three scrolls.",logDesc="Thassarian at the Wailing Ziggurat wants you to go to the Temple City of En'kilah and retrieve High Priest Talet-Kha's Scroll from the Spire of Pain, High Priest Naferset's Scroll from the Spire of Decay and High Priest Andorath's Scroll at the Spire of Blood."} end
if not DB[11943] then DB[11943]={id=11943,zoneId=4024,name="The Cell",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26117,ender="3",enderType="NPC",enderId=26117,poiX=3570,poiY=6650,wowhead="https://www.wowhead.com/wotlk/quest=11943",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="You've discovered a fragment of a special prison, $n.$b$bMalygos' minions use similar prisons to hold their captured mages and other arcane entities, but this prison was constructed to hold something... stronger.$b$bIn hopes that the enemy of our enemy will prove to be a friend, you must search for the prison's remaining fragments.$b$bThey are likely to be in the possession of Malygos' most trusted underlings.",logDesc="Raelorasz at the Transitus Shield wants you to obtain the Prison Casing from General Cerulean and the Energy Core from Warbringer Goredrak.",rewards={{id=35671,qty=1}}} end
if not DB[11944] then DB[11944]={id=11944,zoneId=3537,name="Surrounded!",level=72,minLevel=68,giver="Corporal Venn",giverType="NPC",giverId=26187,ender="Corporal Venn",enderType="NPC",enderId=26187,rewardNextId=12088,poiX=3114,poiY=3843,wowhead="https://www.wowhead.com/wotlk/quest=11944",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Our situation is nearly hopeless.  We were ordered to take the Wailing Ziggurat with a handful of men.$B$BWe'll be lucky if we can hold this position against the Scourge.  We're outnumbered, injured and have no escape route.$B$BIf you can take some of the pressure off of us, we might be able to solidify our position.  Kill some of the undead circling the structure - we'll hold off their advance.",logDesc="Corporal Venn at Death's Stand wants you to slay 7 Ziggurat Defenders.",choiceRewards={{id=37214,qty=1},{id=37394,qty=1},{id=37424,qty=1},{id=37505,qty=1}}} end
if not DB[11945] then DB[11945]={id=11945,zoneId=3537,name="Preparing for the Worst",level=72,minLevel=68,giver="Utaik",giverType="NPC",giverId=26213,ender="Utaik",enderType="NPC",enderId=26213,poiX=3141,poiY=4884,wowhead="https://www.wowhead.com/wotlk/quest=11945",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Dark times are upon us.  Karkut's spirit walks the earth and gathers the spirits of dead tuskarr.$B$BThe sons of the mist have taken many of our brethren.  Soon dear Kaskala will be reduced to ashes.$B$BThere is hope yet.  Not for us perhaps, but we've sent our families to Unu'pe.  We fight here so there may be a future for them.$B$BThey will need supplies or they will starve.  There's not enough food in Unu'pe.  Salvage any supplies before it's too late for our families.",logDesc="Utaik wants you to gather 8 Kaskala Supplies in Kaskala."} end
if not DB[11946] then DB[11946]={id=11946,zoneId=4024,name="Keristrasza",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26206,ender="3",enderType="NPC",enderId=26206,rewardNextId=11951,poiX=3580,poiY=6653,wowhead="https://www.wowhead.com/wotlk/quest=11946",image="assets/images/quests/placeholder.png",xpDiff=1,money=4800,desc="I am... free?$b$bI was destined to spend an eternity roaming an empty abyss, and now am saved? You cannot fathom my gratitude, mortal.$b$bWhen I refused to bend to his will Malygos bound me to that prison, then shattered it and scattered the pieces. Should I live one hundred of your lifetimes, I shall not forget this kindness.$b$bPerhaps, in time, I will find ways to repay you. For now, though, we must focus our attention on Malygos. I am weak, and there is much to be done.$b$bI need your help, $n.",logDesc="Keristrasza wants you to speak to her when you are ready to prepare for a confrontation with Malygos.$b$bIf you lose your Augmented Arcane Prison, speak to Raelorasz at the Transitus Shield."} end
if not DB[11947] then DB[11947]={id=11947,zoneId=-369,name="Striking Back",level=32,minLevel=29,ender="Earthen Ring Elder",enderType="NPC",enderId=26221,wowhead="https://www.wowhead.com/wotlk/quest=11947",image="assets/images/quests/placeholder.png",xpDiff=5,money=800,desc="We must act to preserve the balance! Time is against us.$b$bThere is a camp located in the shadow of Ethel Rethor within northwestern Desolace. There, they use ice stones to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...",logDesc="Slay the Hailstone Lieutenant summoned from the Ice Stone located at Ethel Rethor in Desolace, then return to the Earthen Ring Elder in a capital city.",rewards={{id=23247,qty=10}}} end
if not DB[11948] then DB[11948]={id=11948,zoneId=-369,name="Striking Back",level=43,minLevel=39,ender="Earthen Ring Elder",enderType="NPC",enderId=26221,wowhead="https://www.wowhead.com/wotlk/quest=11948",image="assets/images/quests/placeholder.png",xpDiff=5,money=1500,desc="We must act to preserve the balance! Time is against us.$b$bNeptulon has long had a base of operations on an island in western Stranglethorn. There, the Twilight Cult has set up ice stones to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...",logDesc="Slay the Chillwind Lieutenant summoned from the Ice Stone located on the water elemental's island in western Stranglethorn Vale, then return to the Earthen Ring Elder in a capital city.",rewards={{id=23247,qty=10}}} end
if not DB[11949] then DB[11949]={id=11949,zoneId=3537,name="Not Without a Fight!",level=72,minLevel=68,giver="Ataika",giverType="NPC",giverId=26169,ender="Ataika",enderType="NPC",enderId=26169,rewardNextId=11950,poiX=3125,poiY=4893,wowhead="https://www.wowhead.com/wotlk/quest=11949",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Kaskala is a sacred place for us, $r.  Our ancestors were guided here by the spirit of Tayutka herself.$B$BNow these foul creatures attack us from the mists without any provocation.$B$BWe will show them that our spears are not merely for whaling.  Fight alongside us, friend.  Perhaps my people might repay you some time in the future.",logDesc="Ataika wants you to slay 12 Kvaldir Raiders in Kaskala.",choiceRewards={{id=37211,qty=1},{id=37421,qty=1},{id=37486,qty=1},{id=37525,qty=1}}} end
if not DB[11950] then DB[11950]={id=11950,zoneId=3537,name="Muahit's Wisdom",level=72,minLevel=68,giver="Ataika",giverType="NPC",giverId=26169,ender="Elder Muahit",enderType="NPC",enderId=26218,rewardNextId=11961,poiX=3125,poiY=4893,wowhead="https://www.wowhead.com/wotlk/quest=11950",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Listen, $N.  Warriors like me are replaceable.  If I fall, my brothers and cousins will pick up my spear and fight.$B$BMy people cannot survive without wise elders.  Stubborn Muahit, our most venerable shaman, refuses to leave the altar to Tayutka in the central island.  We would suffer a significant loss if he was slain by these monsters.$B$BYou are an outsider, maybe he'll listen to you.  Show him reason... ask him to flee to the safety of Unu'pe before it's too late.",logDesc="Find Elder Muahit in Kaskala."} end
if not DB[11951] then DB[11951]={id=11951,zoneId=4024,name="Bait and Switch",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26206,ender="3",enderType="NPC",enderId=26206,rewardNextId=11957,poiX=3580,poiY=6653,wowhead="https://www.wowhead.com/wotlk/quest=11951",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="During my captivity I was able to learn much about Malygos. Fate now allows us to use this knowledge against him.$b$bThere is a great blue dragon, Saragosa, who circles high above the Nexus. She serves both as the aspect's guardian and as his consort. If any serious threats arise, she alerts her master of the danger.$b$bI suffered greatly at the hand of Saragosa during my captivity, and now her time to die has come. First, however, we must fashion the perfect bait....",logDesc="Keristrasza has asked you to collect 10 Crystalized Mana Shards from around Coldarra.$b$bIf you lose your Augmented Arcane Prison, speak to Raelorasz at the Transitus Shield."} end
if not DB[11952] then DB[11952]={id=11952,zoneId=-369,name="Striking Back",level=51,minLevel=49,ender="Earthen Ring Elder",enderType="NPC",enderId=26221,wowhead="https://www.wowhead.com/wotlk/quest=11952",image="assets/images/quests/placeholder.png",xpDiff=5,money=1900,desc="We must act to preserve the balance! Time is against us.$b$bFirewatch Ridge in Searing Gorge is an established bastion of Twilight Cult activity. Recently, they have been using ice stones in the cave to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...",logDesc="Slay the Frigid Lieutenant summoned from the Ice Stone located in the cave underneath Firewatch Ridge in the northwest of Searing Gorge, then return to the Earthen Ring Elder in a capital city.",rewards={{id=23247,qty=10}}} end
if not DB[11953] then DB[11953]={id=11953,zoneId=-369,name="Striking Back",level=60,minLevel=56,ender="Earthen Ring Elder",enderType="NPC",enderId=26221,wowhead="https://www.wowhead.com/wotlk/quest=11953",image="assets/images/quests/placeholder.png",xpDiff=5,money=2300,desc="We must act to preserve the balance! Time is against us.$b$bSilithus is the Azerothian base of the Twilight Cult. In the north, they have been using new ice stones to communicate with the Tidehunter's realm. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...",logDesc="Slay the Glacial Lieutenant summoned from the Ice Stone located at Twilight's Run in northern Silithus, then return to the Earthen Ring Elder in a capital city.",rewards={{id=23247,qty=10}}} end
if not DB[11954] then DB[11954]={id=11954,zoneId=-369,name="Striking Back",level=67,minLevel=64,ender="Earthen Ring Elder",enderType="NPC",enderId=26221,wowhead="https://www.wowhead.com/wotlk/quest=11954",image="assets/images/quests/placeholder.png",xpDiff=5,money=9400,desc="We must act to preserve the balance! Time is against us.$b$bIn order to ensure Ahune's success, the cult has established a base near the Dark Portal itself in Draenor. They use ice stones to coordinate the frost lord's arrival. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's templar protectors and destroy it. Perhaps this forestalling action will be enough...",logDesc="Slay the Glacial Templar summoned from the Ice Stone located near the Dark Portal in Hellfire Peninsula, then return to the Earthen Ring Elder in a capital city.",rewards={{id=23247,qty=10}}} end
if not DB[11955] then DB[11955]={id=11955,zoneId=-369,name="Ahune, the Frost Lord",level=80,minLevel=75,ender="Numa Cloudsister",enderType="NPC",enderId=25710,wowhead="https://www.wowhead.com/wotlk/quest=11955",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I believe you are strong enough for the ultimate task set before us.$b$bWe cannot allow the plot between the Twilight Cult and the naga heretics of Neptulon to come to fruition. For the sake of Azeroth and all life upon it, we must act. Our path is clear. You must journey to the Slave Pens deep within Coilfang Reservoir and meet with our shaman there. Go, and quickly!",logDesc="Travel to the Slave Pens in Coilfang Reservoir within Zangarmarsh and speak with Numa Cloudsister."} end
if not DB[11956] then DB[11956]={id=11956,zoneId=3537,name="Finding the Phylactery",level=71,minLevel=68,giver="Thassarian",giverType="NPC",giverId=26170,ender="Thassarian",enderType="NPC",enderId=26170,rewardNextId=11938,poiX=3296,poiY=3683,wowhead="https://www.wowhead.com/wotlk/quest=11956",image="assets/images/quests/placeholder.png",xpDiff=5,desc="No time for small talk, $N.  I was sent on what was to be a suicide mission to take this ziggurat.  I've accomplished my duty as a soldier, now is the time to get some answers.$B$BThis lich has knowledge I seek, yet I cannot inflict pain to his physical body to obtain that knowledge.$B$BThe lich stored his soul in a phylactery, and while it remains hidden, I won't be able to pry the information from him.$B$BReturn to the camp and take my horse, Dusk, she will lead you to the phylactery.  Bring it to me.",logDesc="Go to Death's Stand and ride Dusk to the location of Tanathal's Phylactery.  Obtain it and bring it back to Thassarian inside the Wailing Ziggurat."} end
if not DB[11957] then DB[11957]={id=11957,zoneId=4024,name="Saragosa's End",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26206,ender="3",enderType="NPC",enderId=26206,rewardNextId=11967,poiX=3580,poiY=6653,wowhead="https://www.wowhead.com/wotlk/quest=11957",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="Using the mana crystals you provided, I have created this Power Focus.$b$bSaragosa is a glutton. She will be unable to resist its lure. Inside it lie magics that will greatly diminish her power. Let us hope she does not see through my ruse....$b$bPrepare yourself, $n, and speak to me again when you are ready to face Saragosa.$B",logDesc="Keristrasza wants you to use the Power Focus to lure Saragosa, and then defeat her.",choiceRewards={{id=37280,qty=1},{id=37322,qty=1},{id=37456,qty=1},{id=37562,qty=1}}} end
if not DB[11958] then DB[11958]={id=11958,zoneId=65,name="Let Nothing Go To Waste",level=72,minLevel=71,giver="Elder Ko'nani",giverType="NPC",giverId=26194,ender="Elder Ko'nani",enderType="NPC",enderId=26194,rewardNextId=11959,poiX=2775,poiY=935,wowhead="https://www.wowhead.com/wotlk/quest=11958",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The wolvar have always been our natural enemies. But the incursion of your peoples into the Great Dragonblight has forced them into a small space upon the glade to the north.$B$BCombined with the land's upheaval this morning, they have become even more aggressive than ever before. They have made several raids upon our goods... things that we'll need if we are to survive the trek from our home here.$B$BAs a sign of good faith and friendship, retrieve our goods from the Snowfall Glade wolvar.",logDesc="Retrieve 6 Stolen Moa'ki Goods from the wolvar. Return them to Elder Ko'nani at Moa'ki Harbor."} end
if not DB[11959] then DB[11959]={id=11959,zoneId=65,name="Slay Loguhn",level=73,minLevel=71,giver="Elder Ko'nani",giverType="NPC",giverId=26194,ender="Elder Ko'nani",enderType="NPC",enderId=26194,poiX=2775,poiY=935,wowhead="https://www.wowhead.com/wotlk/quest=11959",image="assets/images/quests/placeholder.png",xpDiff=6,money=106000,desc="Already it goes from bad to worse. There is only one course to take... regrettably, Loguhn must die!$B$BHe's the alpha male of the Snowfall Glade tribe and one mean wolvar. But it's the only way to get a short break from their attacks and stealing forays.$B$BYou will find the \"Render of Flesh\" in front of his hovel upon the northern rise of the glade. It's larger than the others and hard to miss. Kill him and smear his blood upon yourself, both to show your dominance and respect.",logDesc="Smear the Blood of Loguhn upon yourself and then return to Elder Ko'nani at Moa'ki Harbor.",choiceRewards={{id=38026,qty=1},{id=37982,qty=1},{id=38087,qty=1},{id=37939,qty=1}}} end
if not DB[11960] then DB[11960]={id=11960,zoneId=65,name="Planning for the Future",level=72,minLevel=71,giver="Trapper Mau'i",giverType="NPC",giverId=26228,ender="Trapper Mau'i",enderType="NPC",enderId=26228,poiX=2795,poiY=921,wowhead="https://www.wowhead.com/wotlk/quest=11960",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="We must move decisively against the wolvar if we're to have a chance of survival. However, I worry that in our zeal, too many of them will be slain.$B$BThe Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance.$B$BIf Elder Ko'nani hasn't asked you already, he will ask you to deal with them.  While you're upon the glade to the north, I'd like you to bag up their pups and bring them back to me.",logDesc="Collect 12 Snowfall Glade Pups. Deliver them to Trapper Mau'i at Moa'ki Harbor."} end
if not DB[11961] then DB[11961]={id=11961,zoneId=3537,name="Spirits Watch Over Us",level=72,minLevel=68,giver="Elder Muahit",giverType="NPC",giverId=26218,ender="Elder Muahit",enderType="NPC",enderId=26218,rewardNextId=11968,poiX=2792,poiY=4696,wowhead="https://www.wowhead.com/wotlk/quest=11961",image="assets/images/quests/placeholder.png",xpDiff=4,money=39000,desc="Powerful spirits watch over my tribe -- Kaskala will not be lost.$B$BIssliruk will give us courage, Tayutka will make sure our survivors always have food and shelter and Karkut will watch over the fallen so they do not lose their way.$B$BIssliruk's guidance is the one we need the most right now.  I asked my nephew, Iruk, to bring me Issliruk's totem, but the Kvaldir's spears struck him down and his body fell into the waters to the north.  Bring me the totem, $N.  Don't let my nephew's death be in vain.",logDesc="Elder Muahit at Njord's Breath Bay wants you to find Iruk's corpse in the water and retrieve Issliruk's totem."} end
if not DB[11962] then DB[11962]={id=11962,zoneId=3537,name="One Last Delivery",level=71,minLevel=68,giver="Gerald Green",giverType="NPC",giverId=26083,ender="Hilda Stoneforge",enderType="NPC",enderId=25235,rewardNextId=11963,poiX=2483,poiY=5215,wowhead="https://www.wowhead.com/wotlk/quest=11962",image="assets/images/quests/placeholder.png",xpDiff=2,desc="That's it then.  With the last of the ore you salvaged we now have enough to send to Valiance Keep.$B$BIf Farshire is wiped off the face of Azeroth, then at least let us be remembered as the first ones to defend our land and the last ones to give up.$B$BTake this ore to Hilda Stoneforge - she is a good friend of mine.  Tell her to make some good weapons with this ore.  We'll need plenty of them in the days to come.",logDesc="Deliver the Crate of Farshire Ore to Hilda Stoneforge in Valiance Keep."} end
if not DB[11963] then DB[11963]={id=11963,zoneId=3537,name="Weapons for Farshire",level=71,minLevel=68,giver="Hilda Stoneforge",giverType="NPC",giverId=25235,ender="Gerald Green",enderType="NPC",enderId=26083,rewardNextId=11965,poiX=2336,poiY=5266,wowhead="https://www.wowhead.com/wotlk/quest=11963",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Farshire is overrun and all that Gerald can think of is to get me my ore shipment?  I swear that man has as much heart as any of our soldiers on the frontlines.$B$BWe cannot let the civilians lose their lands if they're willing to fight for them.  We might not have the troops to spare, but we can send them weapons.$B$BThese were earmarked for new recruits, but I'll be able to cover those with the ore you've brought me.  Send word to Gerald that weapons are on the way.",logDesc="Return to Gerald Green in Farshire."} end
if not DB[11964] then DB[11964]={id=11964,zoneId=-369,name="Incense for the Summer Scorchlings",level=-1,minLevel=1,ender="Summer Scorchling",enderType="NPC",enderId=26401,wowhead="https://www.wowhead.com/wotlk/quest=11964",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Did you know that our festival fires burn in every land with an Alliance settlement? Flame Wardens tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.$b$bWith each Flame Warden is a summer scorchling -- an emissary to the elemental spirits of fire.$B$BWould you like to honor a scorchling, $N?  Take this summer incense and bring it to any summer scorchling.  Appease the little fire spirit, and it may reward you.",logDesc="The Festival Loremaster wants you to take Summer Incense to a Summer Scorchling outside any Alliance settlement.",rewards={{id=23247,qty=1}}} end
if not DB[11965] then DB[11965]={id=11965,zoneId=3537,name="Call to Arms!",level=71,minLevel=68,giver="Gerald Green",giverType="NPC",giverId=26083,ender="Gerald Green",enderType="NPC",enderId=26083,poiX=2483,poiY=5215,wowhead="https://www.wowhead.com/wotlk/quest=11965",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Farshire has a fighting chance now, $N.  That's all we could've asked for and you've made it possible.$B$BAll we need now is a rallying point.  I'll have my men deliver the weapons to our town hall.  Go and ring the town hall bell so any survivors know to rally there.$B$BIt's time to show the Scourge what we're made of.",logDesc="Go to the town hall building in Farshire and ring the bell inside of it.",choiceRewards={{id=38227,qty=1},{id=38226,qty=1},{id=38228,qty=1}}} end
if not DB[11966] then DB[11966]={id=11966,zoneId=-369,name="Incense for the Festival Scorchlings",level=-1,minLevel=1,ender="Festival Scorchling",enderType="NPC",enderId=26520,wowhead="https://www.wowhead.com/wotlk/quest=11966",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Did you know that our festival fires burn in every land with a Horde settlement? Flame Keepers tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.$b$bWith each Flame Keeper is a festival scorchling -- an emissary to the elemental spirits of fire.$B$BWould you like to honor a scorchling, $N?  Take this summer incense and bring it to any festival scorchling.  Appease the little fire spirit, and it may reward you.",logDesc="The Festival Talespinner wants you to take Summer Incense to a Festival Scorchling outside any Horde settlement.",rewards={{id=23247,qty=1}}} end
if not DB[11967] then DB[11967]={id=11967,zoneId=4024,name="Mustering the Reds",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26206,ender="3",enderType="NPC",enderId=26117,rewardNextId=11969,poiX=3580,poiY=6653,wowhead="https://www.wowhead.com/wotlk/quest=11967",image="assets/images/quests/placeholder.png",xpDiff=3,money=24000,desc="Malygos is certainly aware that something is amiss.$b$bI know him. His focus is fragmented. I am confident that I can lure him from the safety of his realm when he learns what has become of his precious Saragosa.$b$bTake me to Raelorasz at once, $n. He must rouse every dragon he commands to face Malygos.",logDesc="Keristrasza has asked you to bring her to Raelorasz at the Transitus Shield."} end
if not DB[11968] then DB[11968]={id=11968,zoneId=3537,name="The Tides Turn",level=71,minLevel=68,giver="Elder Muahit",giverType="NPC",giverId=26218,ender="Elder Muahit",enderType="NPC",enderId=26218,poiX=2792,poiY=4696,wowhead="https://www.wowhead.com/wotlk/quest=11968",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The spirits have heard our cry for help, $N.  It's a sign that Kaskala might yet be saved.$B$BTake advantage of the confusion the weather has created and slay the Kvaldir leader.  Your actions will sway the battle in our favor, I am sure of it.",logDesc="Elder Muahit wants you to kill Heigarr the Horrible in Njord's Breath Bay.",choiceRewards={{id=37030,qty=1},{id=37031,qty=1},{id=37029,qty=1},{id=37032,qty=1},{id=37033,qty=1}}} end
if not DB[11969] then DB[11969]={id=11969,zoneId=4024,name="Springing the Trap",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26117,ender="3",enderType="NPC",enderId=26117,rewardNextId=11973,poiX=3570,poiY=6650,wowhead="https://www.wowhead.com/wotlk/quest=11969",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="We owe this opportunity in great part to your efforts, $n.$b$bIt is only fitting that you initiate the attack on Malygos.$b$bTake this spark and use it to light the signal fire northwest of the Nexus. Keristrasza will direct you from there.",logDesc="Raelorasz wants you to use Raelorasz' Spark at the signal fire in Coldarra.",choiceRewards={{id=37080,qty=1},{id=37075,qty=1},{id=37076,qty=1},{id=37078,qty=1},{id=37077,qty=1},{id=37564,qty=1}}} end
if not DB[11970] then DB[11970]={id=11970,zoneId=-369,name="The Master of Summer Lore",level=-1,minLevel=1,ender="Festival Loremaster",enderType="NPC",enderId=16817,wowhead="https://www.wowhead.com/wotlk/quest=11970",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The festival is a time for fun and laughter, there's no mistake. It's important, however, that you understand the origins of this holiday. Education should be sought out and savored.$b$bThe Festival Loremaster in the Alliance capitals can guide your way. Go now and learn.",logDesc="Speak to the Festival Loremaster in any Alliance capital.",rewards={{id=23247,qty=1}}} end
if not DB[11971] then DB[11971]={id=11971,zoneId=-369,name="The Spinner of Summer Tales",level=-1,minLevel=1,ender="Festival Talespinner",enderType="NPC",enderId=16818,wowhead="https://www.wowhead.com/wotlk/quest=11971",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The festival is a time for fun and laughter, there's no mistake. It's important, however, that you understand the origins of this holiday. Education should be sought out and savored.$b$bThe Festival Talespinner in the Horde capitals can guide your way. Go now and learn.",logDesc="Speak to the Festival Talespinner in any Horde capital.",rewards={{id=23247,qty=1}}} end
if not DB[11972] then DB[11972]={id=11972,zoneId=-369,name="Shards of Ahune",level=-1,minLevel=75,ender="Luma Skymother",enderType="NPC",enderId=25697,wowhead="https://www.wowhead.com/wotlk/quest=11972",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="These shards pulse with foreboding.  Do they hold the last essence of the Frost Lord?",logDesc="Bring the Ice Shards to Luma Skymother.",rewards={{id=23247,qty=20}},choiceRewards={{id=35279,qty=1},{id=35280,qty=1}}} end
if not DB[11973] then DB[11973]={id=11973,zoneId=4265,name="Prisoner of War",level=71,minLevel=69,giver="3",giverType="NPC",giverId=26117,ender="3",enderType="NPC",enderId=26117,poiX=3570,poiY=6650,wowhead="https://www.wowhead.com/wotlk/quest=11973",image="assets/images/quests/placeholder.png",xpDiff=8,money=47000,desc="Malygos has taken Keristrasza to serve as his consort!? Unthinkable!$b$bShe'll never cooperate willingly, but Malygos is a powerful aspect, and will eventually bend her will.$b$bThis cannot come to pass, $n. I refuse to allow her to suffer this indignity.$b$bYou must enter the Nexus and do whatever is required to spare her this fate.",logDesc="Raelorasz at the Transitus Shield wants you to enter the Nexus and release Keristrasza.",choiceRewards={{id=38223,qty=1},{id=38222,qty=1},{id=38221,qty=1}}} end
if not DB[11974] then DB[11974]={id=11974,zoneId=-284,name="[ph] Now, When I Grow Up...",level=-1,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=11974",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When you were my age did you know that you wanted to be a $c when you grew up?$B$BI'm not sure what I want to be.  I used to want to be a Blood Knight, but not anymore.  Now I want to be a Rock Star!  Like the blood elf in L70 ETC!$B$BWhen they aren't touring, they hang out in Silvermoon City! Could you take me there? They hang out in the Walk of Elder's on a balcony... Probably to keep the fans away  But that shouldn't stop us from trying, right?$B$BPlease take me there.  Please!",logDesc="Take your orphan, Salandria, to see L70ETC in Silvermoon City's Walk of Elder's.  Make sure to call for her if she is not present when you arrive."} end
if not DB[11975] then DB[11975]={id=11975,zoneId=-284,name="Now, When I Grow Up...",level=-1,minLevel=60,ender="Blood Elf Orphan",enderType="NPC",enderId=22817,wowhead="https://www.wowhead.com/wotlk/quest=11975",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Maybe I already asked you this, but when you were my age did you know that you wanted to be a $c when you grew up?$B$BI'm not sure what I want to be.  Maybe a mage or a warlock or a Blood Knight, like I said before?  Or maybe... A rock star!!  Like Sig Nicious, the blood elf, in the Elite Tauren Chieftain!$B$BI heard that when they aren't touring, they hang out in Silvermoon City!  They just sit on a balcony in the Walk of Elders waiting for people to stop by.$B$BPlease take me there.  Please!",logDesc="Take your orphan, Salandria, to see the Elite Tauren Chieftain in Silvermoon City's Walk of Elders.  Make sure to call for her if she is not present when you arrive. "} end
if not DB[11976] then DB[11976]={id=11976,zoneId=-22,name="Ice Shards",level=-1,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=11976",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="These shards pulse with foreboding.  Do they hold the last essence of the Frost Lord?",logDesc="Bring the Ice Shards to Luma Skymother.",rewards={{id=35279,qty=1},{id=23247,qty=20}}} end
if not DB[11977] then DB[11977]={id=11977,zoneId=65,name="A Tauren Among Taunka",level=72,minLevel=71,giver="Wartook Iceborn",giverType="NPC",giverId=26156,ender="Emissary Brighthoof",enderType="NPC",enderId=26181,rewardNextId=11978,poiX=3641,poiY=2912,wowhead="https://www.wowhead.com/wotlk/quest=11977",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Wartook points northeast.>$B$BShe is quite kind, you know. If it were not for your emissary, the surviving refugees may have given up hope. While she may not be taunka by birthright, the tribe has taken to her as a village elder for the time being.$B$BIf you are who I think you are, please go and pay Emissary Brighthoof a visit inside the refugee camp. She has been waiting for you.",logDesc="Seek out Emissary Brighthoof at the Westwind Refugee Camp."} end
if not DB[11978] then DB[11978]={id=11978,zoneId=65,name="Into the Fold",level=72,minLevel=71,giver="Emissary Brighthoof",giverType="NPC",giverId=26181,ender="Emissary Brighthoof",enderType="NPC",enderId=26181,rewardNextId=11983,poiX=3753,poiY=2865,wowhead="https://www.wowhead.com/wotlk/quest=11978",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Before we can officially bring these taunka into the Horde we must recover our armaments from the Anub'ar Nerubians that infest the nearby woods. The armaments were lost when a caravan from Agmar's Hammer was ambushed by the Scourge late last night.$B$BVenture out into the woods to the east of Westwind Refugee Camp and recover those armaments, $r.",logDesc="Emissary Brighthoof at the Westwind Refugee Camp in the Dragonblight wants you to recover 10 Horde Armaments."} end
if not DB[11979] then DB[11979]={id=11979,zoneId=65,name="The Taunka and the Tauren",level=72,minLevel=71,giver="Senior Sergeant Juktok",giverType="NPC",giverId=26415,ender="Emissary Brighthoof",enderType="NPC",enderId=26181,rewardNextId=11978,poiX=3833,poiY=1574,wowhead="https://www.wowhead.com/wotlk/quest=11979",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Scourge have seized control of the capital city of the taunka, Icemist Village! All living taunka that escaped the massacre are being held in protective custody at the Westwind Refugee Camp on the western border of Dragonblight.$B$BLord Hellscream believes that the taunka must join the Horde if they are to survive and has sent a tauren emissary to Westwind to bolster our relationship with the winter tauren. Travel to Westwind Refugee Camp and seek out Emissary Brighthoof. You will assist her.",logDesc="Seek out Emissary Brighthoof at the Westwind Refugee Camp.$B"} end
if not DB[11980] then DB[11980]={id=11980,zoneId=65,name="Pride of the Horde",level=72,minLevel=71,giver="Blood Guard Roh'kill",giverType="NPC",giverId=26180,ender="Blood Guard Roh'kill",enderType="NPC",enderId=26180,poiX=3712,poiY=2830,wowhead="https://www.wowhead.com/wotlk/quest=11980",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I was one of the guards chosen to escort the caravan carrying the armament shipment to this camp. The attack came fast and without warning. We fought and killed dozens of the beasts, but in the end there were simply too many. Tor'zin and I barely made it out alive...$B$BIf not for our injuries we would be out in the woods hunting down those fiends ourselves. Will you help us regain our lost pride? Search the woods east of here for Anub'ar Nerubians and kill them! For the Horde!",logDesc="Blood Guard Roh'kill at the Westwind Refugee Camp in the Dragonblight wants you to slay 15 Anub'ar Ambushers.$B",choiceRewards={{id=37964,qty=1},{id=38006,qty=1},{id=38048,qty=1},{id=38081,qty=1},{id=38110,qty=1}}} end
if not DB[11981] then DB[11981]={id=11981,zoneId=394,name="Find Kurun!",level=75,minLevel=72,giver="Fallen Earthen Warrior",giverType="NPC",giverId=26335,ender="3",enderType="NPC",enderId=26260,rewardNextId=11982,poiX=4707,poiY=-4454,wowhead="https://www.wowhead.com/wotlk/quest=11981",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Earthen warrior's stone surface is covered with cracks and gouges. Although it is incapable of bleeding, you can sense that the warrior is near death.$B$BA low, hoarse voice escapes from the dying warrior's mouth.$B$B\"Find... Kurun... you must find... Kurun.\"$B$BIt looks at you helplessly as you ask for any clues as to who or what Kurun might be.$B$B\"Our... leader... he stands on the... hill overlooking Thor Modan... commands us. Please... tell him... we cannot take... the city... \"",logDesc="Speak with Kurun on the hill overlooking Thor Modan."} end
if not DB[11982] then DB[11982]={id=11982,zoneId=394,name="Raining Down Destruction",level=75,minLevel=72,giver="3",giverType="NPC",giverId=26260,ender="3",enderType="NPC",enderId=26260,rewardNextId=12070,poiX=4894,poiY=-4563,wowhead="https://www.wowhead.com/wotlk/quest=11982",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Beneath us is iron's ancient bastion, Thor Modan. Thousands of years ago, the stone giants tore the land asunder, collapsing part of the city and exposing much of the rest.$B$BEven now, the iron dwarves attempt to reclaim their old capital, but we will not permit it. My giants fill the trench with boulders and debris, hoping to seal it off and kill the servants of iron as they work. Take up the boulders you see near the trench to the northeast, and help us put an end to their efforts.",logDesc="Kurun on the hill overlooking Thor Modan wants you to disrupt the iron dwarves' work by throwing boulders into the exposed area of Thor Modan."} end
if not DB[11983] then DB[11983]={id=11983,zoneId=65,name="Blood Oath of the Horde",level=72,minLevel=71,giver="Emissary Brighthoof",giverType="NPC",giverId=26181,ender="Emissary Brighthoof",enderType="NPC",enderId=26181,rewardNextId=12008,poiX=3753,poiY=2865,wowhead="https://www.wowhead.com/wotlk/quest=11983",image="assets/images/quests/placeholder.png",xpDiff=4,desc="They are ready, $N. These taunka will all willingly join the Horde and give all that they have to see the Scourge driven from this world.$B$B<Brighthoof hands you a scroll bearing the insignia of the Horde.>$B$BWithin this scroll you will find the blood oath of the Horde. Tradition dictates that our new taunka brothers and sisters utter the sacred words herein.$B$BTake the scroll and swear the taunka into the Horde, commander. Return the scroll to me when you have completed your duty.",logDesc="Speak to the taunka at Westwind Refugee Camp and make 5 of them pledge their allegiance to the Horde.$B$BReturn the Blood Oath of the Horde to Emissary Brighthoof once you have completed this task."} end
if not DB[11984] then DB[11984]={id=11984,zoneId=394,name="Filling the Cages",level=74,minLevel=73,giver="Samir",giverType="NPC",giverId=26424,ender="Samir",enderType="NPC",enderId=26424,rewardNextId=11989,poiX=3850,poiY=-1960,wowhead="https://www.wowhead.com/wotlk/quest=11984",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="'Ol Budd's seen better days.$b$bEver since our stay in Ghostlands he's been useless to us. We've had to find ways to make it on our own, and today that means sellin' trolls to the highest bidder.$b$bFortunately, we've recently found a use for Budd. Something about his condition allows him to mingle with the local trolls, so we taught him a little game that's turned us a tidy profit.$b$bSee for yourself. Talk to Budd, take him southwest to Drak' Zin Ruins and use this cage as soon as he tags a troll.",logDesc="Samir at Granite Springs wants you to use the Bounty Hunter's Cage on a drakkari troll that's been stunned by Budd.",choiceRewards={{id=39116,qty=1},{id=39131,qty=1},{id=39142,qty=1},{id=39129,qty=1},{id=39128,qty=1},{id=39132,qty=1}}} end
if not DB[11985] then DB[11985]={id=11985,zoneId=394,name="Into the Breach",level=75,minLevel=72,giver="3",giverType="NPC",giverId=26260,ender="3",enderType="NPC",enderId=26260,rewardNextId=12081,poiX=4894,poiY=-4563,wowhead="https://www.wowhead.com/wotlk/quest=11985",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="If we can't overcome the defenders inside Thor Modan, the iron dwarves can hold out forever. The Earthen are bravely taking on the constructs built by the sons of iron, but they cannot break into the city.$B$BThe tunnels narrow too quickly for my fellow giants to be of use, so our options are few. Would you be willing to venture into the city and kill the dwarf commanding the resistance?",logDesc="Kurun on the hill overlooking Thor Modan wants you to kill Iron Thane Argrum.",choiceRewards={{id=38715,qty=1},{id=39019,qty=1},{id=39048,qty=1},{id=39080,qty=1}}} end
if not DB[11986] then DB[11986]={id=11986,zoneId=394,name="The Damaged Journal",level=75,minLevel=73,ender="Torthen Deepdig",enderType="NPC",enderId=26361,wowhead="https://www.wowhead.com/wotlk/quest=11986",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps.$B$BThe author's handwriting seems vaguely familiar, but you're unable to place it until you discover an entry signed with the name of Brann Bronzebeard.$B$BThe back half of the book, containing the most recent entries, has been torn away. Pages litter the battlefield, and it will be impossible to know what Brann discovered here until the book is whole again.",logDesc="Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Torthen Deepdig at the Westfall Brigade Encampment."} end
if not DB[11987] then DB[11987]={id=11987,zoneId=-284,name="zzOLDFortune Card: Silver",level=1,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=11987",image="assets/images/quests/placeholder.png",choiceRewards={{id=35745,qty=1},{id=35745,qty=1},{id=35745,qty=1}}} end
if not DB[11988] then DB[11988]={id=11988,zoneId=394,name="The Runic Keystone",level=75,minLevel=73,giver="Torthen Deepdig",giverType="NPC",giverId=26361,ender="Torthen Deepdig",enderType="NPC",enderId=26361,poiX=4556,poiY=-4248,wowhead="https://www.wowhead.com/wotlk/quest=11988",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Brann's journal mentions that he used a runic keystone to illuminate the important runes on the plate he discovered. Without the keystone, the plate's contents would be little better than gibberish.$B$BAt the end of Brann's last entry, he describes the iron dwarf defenders seizing the keystone from him, shattering it, and dividing it among themselves. Before we can decipher the runed plate, we must hunt down the fragments. Any of the dwarves within Thor Modan or the buildings around it may carry fragments.",logDesc="Bring 5 Runic Keystone Fragments to Torthen Deepdig at the Westfall Brigade Encampment."} end
if not DB[11989] then DB[11989]={id=11989,zoneId=394,name="Truce?",level=73,minLevel=73,giver="Drakuru",giverType="NPC",giverId=26423,ender="Drakuru",enderType="NPC",enderId=26423,rewardNextId=11990,poiX=3845,poiY=-1973,wowhead="https://www.wowhead.com/wotlk/quest=11989",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Watch yerself, mon.$b$bDrakuru shrunk more $r heads than I can remember - and even if I could remember, I couldn't count that high. Lucky for you I be stuck in dis cage or I'd be addin' one more to da list.$b$bBut things bein' what they are, mebbe we be puttin' our differences aside fer a time, eh?$b$bDrakuru know things, mon. Things that will aid you in your struggle here.$b$b<Drakuru cuts the palm of his hand on one of his tusks and extends it through the cage.>$b$bSo, what you say, mon... truce?",logDesc="Drakuru at Granite Springs wants you to use the Dull Carving Knife near his cage and then speak to him."} end
if not DB[11990] then DB[11990]={id=11990,zoneId=394,name="Vial of Visions",level=74,minLevel=73,giver="Drakuru",giverType="NPC",giverId=26423,ender="Drakuru",enderType="NPC",enderId=26423,rewardNextId=11991,poiX=3845,poiY=-1973,wowhead="https://www.wowhead.com/wotlk/quest=11990",image="assets/images/quests/placeholder.png",xpDiff=5,desc="First things first, mon. There be some preparatory work that need doin'.$b$bNo tellin' how long dey gunna keep me here. Ya be needin' a powerful elixir so we can be keepin' in touch.$b$bLucky for you, I know just the thing! And the ingredients all be close by.$b$bI need a vial from the pretty little troll over there, some waterweed from the lake just north of here, and a few haze leaves found around the camp here.$b$bHurry now, mon, before dey be haulin' me away.",logDesc="Drakuru at Granite Springs wants you to bring him an Imbued Vial, a Waterweed Frond, and 3 Haze Leaves."} end
if not DB[11991] then DB[11991]={id=11991,zoneId=394,name="Subject to Interpretation",level=74,minLevel=73,giver="Drakuru",giverType="NPC",giverId=26423,ender="Image of Drakuru",enderType="NPC",enderId=26500,rewardNextId=12007,poiX=3845,poiY=-1973,wowhead="https://www.wowhead.com/wotlk/quest=11991",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="A legendary set of artifacts, lost for thousands of years, were created to make Drak'Tharon Keep impervious.$b$bMost think they be myth, but Drakuru knows better, mon!$b$bI nearly discovered where one be, but got captured while interpreting hieroglyphs. Ya gotta summon my soul back dere so I can finish readin' em!$b$bUse my elixir at da brazier on Drak'Zin Ruins, southwest of here. You'll hafta mix in da frozen mojo my bruddas be holdin'. I hate ta see my bruddas fall, but it be for the greater good.$B",logDesc="Drakuru wants you to get 5 Frozen Mojo from the Drakkari Trolls at the Ruins of Drak'Zin and then use the elixir at Drakuru's Brazier there.",choiceRewards={{id=38716,qty=1},{id=39020,qty=1},{id=39049,qty=1},{id=39081,qty=1}}} end
if not DB[11992] then DB[11992]={id=11992,zoneId=3537,name="Navigation Charts (Deprecated)",level=71,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=11992",image="assets/images/quests/placeholder.png",xpDiff=5,money=47000,desc="You've uncovered the first part of a navigation chart drawn on flayed dragonskin.  If you could complete it you'd be able to find the kvaldir's future plans of attack.$B$BOther mariners in Riplash might have the missing charts on them.  Karuk would be interested in the information they contain.",logDesc="Obtain the missing parts of the Skadir Navigational Chart and bring it to Karuk in Riplash Stand."} end
if not DB[11993] then DB[11993]={id=11993,zoneId=394,name="The Runic Prophecies",level=75,minLevel=73,giver="Torthen Deepdig",giverType="NPC",giverId=26361,ender="Torthen Deepdig",enderType="NPC",enderId=26361,poiX=4556,poiY=-4248,wowhead="https://www.wowhead.com/wotlk/quest=11993",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="We've no time to lose! Now that we've reassembled the runic keystone -- well, most of it -- we can decipher the contents of those very same runic plates Brann was working on before he fled.$B$BWe have no way of knowing if he managed to read the contents of all three plates, but we'll have to assume he got enough information to determine his next destination.$B$BStand before each of the plates and use the keystone to determine the contents of each. Brann may be counting on us!",logDesc="Torthen Deepdig at the Westfall Brigade Encampment wants you to decipher the three Rune Plates.",choiceRewards={{id=38710,qty=1},{id=39013,qty=1},{id=39043,qty=1},{id=39075,qty=1}}} end
if not DB[11994] then DB[11994]={id=11994,zoneId=0,name="Juno's Flag Tester",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=11994",image="assets/images/quests/placeholder.png"} end
if not DB[11995] then DB[11995]={id=11995,zoneId=65,name="Your Presence is Required at Stars' Rest",level=72,minLevel=71,giver="Emissary Skyhaven",giverType="NPC",giverId=26440,ender="Image of Archmage Modera",enderType="NPC",enderId=26673,rewardNextId=12000,poiX=2772,poiY=932,wowhead="https://www.wowhead.com/wotlk/quest=11995",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$C, I know these tuskarr will ask you to do many favors for them, but you must get to Stars' Rest with all due haste!$B$BThe upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives.$B$BStars' Rest is westward past the intersection of the road leading north out of the harbor. There is an archmage there named Modera. She will be expecting you.",logDesc="Speak with the Image of Archmage Modera at Stars' Rest."} end
if not DB[11996] then DB[11996]={id=11996,zoneId=65,name="Your Presence is Required at Agmar's Hammer",level=72,minLevel=71,giver="Envoy Ripfang",giverType="NPC",giverId=26441,ender="Image of Archmage Aethas Sunreaver",enderType="NPC",enderId=26471,rewardNextId=11999,poiX=2779,poiY=936,wowhead="https://www.wowhead.com/wotlk/quest=11996",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$C, I know these tuskarr will ask you to do many favors for them, but you must get to Agmar's Hammer with all due haste!$B$BThe upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives.$B$BThe Hammer is westward past the intersection of the road leading north out of the harbor. Archmage Aethas Sunreaver himself will be expecting you!",logDesc="Speak with the Image of Archmage Aethas Sunreaver at Agmar's Hammer."} end
if not DB[11997] then DB[11997]={id=11997,zoneId=394,name="REUSE",level=75,minLevel=73,wowhead="https://www.wowhead.com/wotlk/quest=11997",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Westfall Brigade has been dispatched to the northeastern part of Grizzly Hills to secure passage for our troops. They have established a base camp to the northeast of Grizzlemaw, and to the southwest of Thor Modan.$B$BYou might recognize the brigade's leader, Captain Gryan Stoutmantle as an honored veteran of the war against the Scourge in Lordaeron. But the people of Westfall know him best for his decision to leave the battlefield and return home to take on the Defias.",logDesc="Speak with Captain Gryan Stoutmantle at the Westfall Brigade Encampment."} end
if not DB[11998] then DB[11998]={id=11998,zoneId=394,name="Softening the Blow",level=75,minLevel=73,giver="Captain Gryan Stoutmantle",giverType="NPC",giverId=26212,ender="Brugar Stoneshear",enderType="NPC",enderId=26226,rewardNextId=12002,poiX=4607,poiY=-4230,wowhead="https://www.wowhead.com/wotlk/quest=11998",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Our best bet for moving our forces quickly to Icecrown Glacier lies with the network of tunnels beneath the ancient iron dwarf city of Thor Modan.$B$BBrugar Stoneshear and his Explorers' League boys aren't going to be happy, but orders are orders.$B$BThe news might go over better if you brought him a cask of that moonshine sold by that trapper, Hugh Glass, down at Redwood Trading Post, southeast of here along the tree line.$B$BMan's not right in the head, but you won't find better moonshine out here.",logDesc="Bring Brugar Stoneshear at the Westfall Brigade Encampment a cask of Howlin' Good Moonshine."} end
if not DB[11999] then DB[11999]={id=11999,zoneId=65,name="Rifle the Bodies",level=72,minLevel=71,giver="Image of Archmage Aethas Sunreaver",giverType="NPC",giverId=26471,ender="Image of Archmage Aethas Sunreaver",enderType="NPC",enderId=26471,rewardNextId=12005,poiX=3847,poiY=1493,wowhead="https://www.wowhead.com/wotlk/quest=11999",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The Moonrest Gardens to the southwest were the final resting place of a group of Highborne elves. It was also a ley line nexus.$B$BThe blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will.$B$BI want more information and you are going to get it for me!$B$BAfter the land was destroyed at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters there. Go rifle their corpses for clues.",logDesc="Find the Moonrest Gardens Plans and return them to the Image of Archmage Aethas Sunreaver at Agmar's Hammer."} end
if not DB[12000] then DB[12000]={id=12000,zoneId=65,name="Rifle the Bodies",level=72,minLevel=71,giver="Image of Archmage Modera",giverType="NPC",giverId=26673,ender="Image of Archmage Modera",enderType="NPC",enderId=26673,rewardNextId=12004,poiX=3501,poiY=2001,wowhead="https://www.wowhead.com/wotlk/quest=12000",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The Moonrest Gardens to the southwest were the final resting place of a noble group of Highborne elves. It was also a powerful ley line nexus.$B$BThe blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will.$B$BI need more information and I hope that you will get it for me.$B$BAfter the upheaval at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters present. Go rifle their corpses for clues.",logDesc="Find the Moonrest Gardens Plans and return them to the Image of Archmage Modera at Stars' Rest."} end
if not DB[12001] then DB[12001]={id=12001,zoneId=-284,name="zzOLDHunting Tarot: Lesser Beasts",level=5,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=12001",image="assets/images/quests/placeholder.png",xpDiff=5,money=100,desc="Staring into the card, the image blurs until you see yourself standing covered in the furs from many wolves and bears.  You can only assume this is your destiny should you invoke the tarot's power.",logDesc="Collect 12 Torn Hides and then summon the Huntsman with the Hunting Tarot.  The Torn Hides can only be gathered from beasts of level 5 or higher."} end
if not DB[12002] then DB[12002]={id=12002,zoneId=394,name="Brothers in Battle",level=75,minLevel=73,giver="Brugar Stoneshear",giverType="NPC",giverId=26226,ender="Brugar Stoneshear",enderType="NPC",enderId=26226,rewardNextId=12003,poiX=4552,poiY=-4250,wowhead="https://www.wowhead.com/wotlk/quest=12002",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="I hope Gryan knows I withdrew my men from Thor Modan when the battle began. There's no way we can excavate anything until that place settles down.$B$BYou seem like a brave sort, though, and you have Stoutmantle's trust.$B$BThor Modan is just to the northeast of us and the battle still rages between our Earthen brothers and the creations of those accursed iron dwarves. Help our brethren to even the odds and I'll start figuring out how we're going to accomplish this survey of Thor Modan.",logDesc="Kill 10 Runic Battle Golems and return to Brugar Stoneshear at the Westfall Brigade Encampment."} end
if not DB[12003] then DB[12003]={id=12003,zoneId=394,name="Uncovering the Tunnels",level=75,minLevel=73,giver="Brugar Stoneshear",giverType="NPC",giverId=26226,ender="Brugar Stoneshear",enderType="NPC",enderId=26226,rewardNextId=12010,poiX=4552,poiY=-4250,wowhead="https://www.wowhead.com/wotlk/quest=12003",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="The first place we'll search for entrances to the Thor Modan tunnel system will be the outlying buildings.$B$BAs I left the site with my men, it looked like the iron dwarf defenders were taking refuge inside the buildings. Be careful as you explore them.$B$BAny tunnel entrances are likely to be toward the back of the buildings. I'm not sure what Stoutmantle thinks we're going to find down there, but I doubt the iron dwarves will make the search easy.",logDesc="Brugar Stoneshear at the Westfall Brigade Encampment wants you to explore the North Building, the East Building, and the South Building of Thor Modan."} end
if not DB[12004] then DB[12004]={id=12004,zoneId=65,name="Prevent the Accord",level=73,minLevel=71,giver="Image of Archmage Modera",giverType="NPC",giverId=26673,ender="Image of Archmage Modera",enderType="NPC",enderId=26673,poiX=3501,poiY=2001,wowhead="https://www.wowhead.com/wotlk/quest=12004",image="assets/images/quests/placeholder.png",xpDiff=6,money=106000,desc="We need to kill two birds with one stone here, $c. You're the stone.$B$BOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit.$B$BI require proof of their demise, if you would be so kind.",logDesc="Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Modera at Stars' Rest.",choiceRewards={{id=37943,qty=1},{id=37987,qty=1},{id=38031,qty=1},{id=38094,qty=1}}} end
if not DB[12005] then DB[12005]={id=12005,zoneId=65,name="Prevent the Accord",level=73,minLevel=71,giver="Image of Archmage Aethas Sunreaver",giverType="NPC",giverId=26471,ender="Image of Archmage Aethas Sunreaver",enderType="NPC",enderId=26471,poiX=3847,poiY=1493,wowhead="https://www.wowhead.com/wotlk/quest=12005",image="assets/images/quests/placeholder.png",xpDiff=6,money=106000,desc="We need to kill two birds with one stone here, $c. You're the stone.$B$BOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit.$B$BI require proof of their demise, if you would be so kind.",logDesc="Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.",choiceRewards={{id=37943,qty=1},{id=37987,qty=1},{id=38031,qty=1},{id=38094,qty=1}}} end
if not DB[12006] then DB[12006]={id=12006,zoneId=65,name="Avenge this Atrocity!",level=72,minLevel=71,giver="Ethenial Moonshadow",giverType="NPC",giverId=26501,ender="Ethenial Moonshadow",enderType="NPC",enderId=26501,rewardNextId=12013,poiX=3328,poiY=2270,wowhead="https://www.wowhead.com/wotlk/quest=12006",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="These so-called mage hunters came here and destroyed our resting place.$B$BAvenge us, or I will see to it that your base of operations is overrun with the spirits of the dead!",logDesc="Kill any combination of 15 Dragonblight Mage Hunters, Moonrest Stalkers, Surge Needle Sorcerers, and Focus Wizards. After you have done that, return to Ethenial Moonshadow at Moonrest Gardens."} end
if not DB[12007] then DB[12007]={id=12007,zoneId=394,name="Sacrifices Must be Made",level=74,minLevel=73,giver="Image of Drakuru",giverType="NPC",giverId=26500,ender="Image of Drakuru",enderType="NPC",enderId=26543,rewardNextId=12042,poiX=3386,poiY=-1805,wowhead="https://www.wowhead.com/wotlk/quest=12007",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="I've got it, mon!$b$bTo da north, on da Ziggurat at Zeb'Halak be a stone head with ruby eyes. One o' dem be da Eye of the Prophets! Bring it to the brazier there and drink my elixir.$b$bAgain, ya be needing some mojo for my elixir to work - dis time from da warlord, Zim'bo. He be hidin' in one of da huts in Zeb'Halak.$b$bIt be a shame to kill Zim'bo, mon, but he swore da blood oath to defend Drak'Tharon and he done failed. Now at least his mojo be helpin' us to reclaim Drak'Tharon.",logDesc="Drakuru wants you to bring the Eye of the Prophets to him at Drakuru's Brazier in Zeb'Halak.$b$bYou will need to collect Zim'bo's Mojo to use Drakuru's Elixir there."} end
if not DB[12008] then DB[12008]={id=12008,zoneId=65,name="Agmar's Hammer",level=72,minLevel=71,giver="Emissary Brighthoof",giverType="NPC",giverId=26181,ender="Overlord Agmar",enderType="NPC",enderId=26379,poiX=3753,poiY=2865,wowhead="https://www.wowhead.com/wotlk/quest=12008",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Directly east of this refugee camp stands Agmar's Hammer - testament to the Hordes' power in the Dragonblight.$B$BWhile I have no doubt that our Horde brothers and sisters are already seeing the result of your efforts to bring the taunka into the Horde, I want you to deliver news of your success to Overlord Agmar in person.$B$BGo now, $N! Race the winds! East to Agmar's Hammer!$B",logDesc="Travel to Agmar's Hammer in the Dragonblight and speak to Overlord Agmar.$B"} end
if not DB[12009] then DB[12009]={id=12009,zoneId=65,name="Tua'kea's Crab Traps",level=72,minLevel=71,giver="Tua'kea",giverType="NPC",giverId=26245,ender="Tua'kea",enderType="NPC",enderId=26245,poiX=2729,poiY=936,wowhead="https://www.wowhead.com/wotlk/quest=12009",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="With all of the troubles, I've lost my assistants. I was wondering if maybe you could help me?$B$BI have many crab traps under the waves of the harbor. Will you retrieve them for me? I'm too old for that sort of thing and the waters can be very dangerous.$B$BPlease, take this bladder. It will help you to breathe while you're down there.",logDesc="Collect 8 of Tua'kea's Crab Traps and return them to him at Moa'ki Harbor."} end
if not DB[12010] then DB[12010]={id=12010,zoneId=394,name="The Fate of Orlond",level=75,minLevel=73,giver="Brugar Stoneshear",giverType="NPC",giverId=26226,ender="Surveyor Orlond",enderType="NPC",enderId=26514,rewardNextId=12014,poiX=4552,poiY=-4250,wowhead="https://www.wowhead.com/wotlk/quest=12010",image="assets/images/quests/placeholder.png",xpDiff=4,desc="When we began excavating the city, I sent Surveyor Orlond to check the stability of the tunnels in Thor Modan. I didn't see him escape when we withdrew at the beginning of the battle, and I worry he may still be trapped inside the city.$B$BIf we're going to get an army through Thor Modan, we'll need the information he was collecting. Stoutmantle and his superiors would have my hide if the tunnels collapsed on one of their brigades!",logDesc="Locate Surveyor Orlond within Thor Modan."} end
if not DB[12011] then DB[12011]={id=12011,zoneId=65,name="Signs of Big Watery Trouble",level=72,minLevel=71,ender="Tua'kea",enderType="NPC",enderId=26245,rewardNextId=12016,wowhead="https://www.wowhead.com/wotlk/quest=12011",image="assets/images/quests/placeholder.png",xpDiff=1,money=5000,desc="This crab trap appears to have been destroyed by something much larger than the nearby circling sharks.$B$BPerhaps Tua'kea, the fisherman at Moa'ki Harbor, should be told about this?",logDesc="Inform Tua'kea at Moa'ki Harbor about the wrecked crab trap."} end
if not DB[12012] then DB[12012]={id=12012,zoneId=-369,name="Inform the Elder",level=-1,minLevel=16,ender="Earthen Ring Elder",enderType="NPC",enderId=26221,wowhead="https://www.wowhead.com/wotlk/quest=12012",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!",logDesc="Travel to a capital city and speak to the Earthen Ring Elder."} end
if not DB[12013] then DB[12013]={id=12013,zoneId=65,name="End Arcanimus",level=73,minLevel=71,giver="Ethenial Moonshadow",giverType="NPC",giverId=26501,ender="Ethenial Moonshadow",enderType="NPC",enderId=26501,poiX=3328,poiY=2270,wowhead="https://www.wowhead.com/wotlk/quest=12013",image="assets/images/quests/placeholder.png",xpDiff=6,money=106000,desc="There is one last thing that I would have you do, $N the $r. I would have you destroy Arcanimus!$B$BThe sorcerers to the west used that giant device in the sky to bore a massive pit into our resting place. When they did that, they unleashed a monstrosity!$B$BI would not care if it were only a concern for mortals, but Arcanimus feeds upon the spirits of the dead.$B$BYou will put an end to it now!",logDesc="Destroy Arcanimus and then return to Ethenial Moonshadow at Moonrest Gardens.",choiceRewards={{id=37941,qty=1},{id=38028,qty=1},{id=37984,qty=1},{id=38092,qty=1}}} end
if not DB[12014] then DB[12014]={id=12014,zoneId=394,name="Steady as a Rock?",level=75,minLevel=73,giver="Surveyor Orlond",giverType="NPC",giverId=26514,ender="Brugar Stoneshear",enderType="NPC",enderId=26226,poiX=4982,poiY=-4654,wowhead="https://www.wowhead.com/wotlk/quest=12014",image="assets/images/quests/placeholder.png",xpDiff=6,money=46000,desc="Orlond's notes indicate that he brought a piece of equipment called a portable seismograph with him, but the device is nowhere to be seen.$B$BThe survey log shows that Orlond completed all his readings in the Thor Modan tunnel, save one labeled the 'east end of the exposed tunnel.'$B$BThe last entry in the log indicates Orlond tried to take refuge in the water and was attacked by subterranean threshers. They might've taken his equipment.You'll need to recover it before you can take the last reading.",logDesc="Retreive the Portable Seismograph and use it to take stability readings in Thor Modan, then return to Brugar Stoneshear at the Westfall Brigade Encampment.",choiceRewards={{id=38717,qty=1},{id=39021,qty=1},{id=39050,qty=1},{id=39082,qty=1}}} end
if not DB[12015] then DB[12015]={id=12015,zoneId=65,name="Test Quest for Craig",level=62,minLevel=58,wowhead="https://www.wowhead.com/wotlk/quest=12015",image="assets/images/quests/placeholder.png",xpDiff=5,desc="klajsdklajlsd",logDesc="Craig Amai at wherever wants you to bring him 5 whatevers."} end
if not DB[12016] then DB[12016]={id=12016,zoneId=65,name="The Bait",level=72,minLevel=71,giver="Tua'kea",giverType="NPC",giverId=26245,ender="Tua'kea",enderType="NPC",enderId=26245,rewardNextId=12017,poiX=2729,poiY=936,wowhead="https://www.wowhead.com/wotlk/quest=12016",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I'm sure of it... our ancient aquatic nemesis, Tu'u'gwar, \"He Who Plays With Food\", has returned. We must lay a trap for him, you and I.$B$BIf Tu'u'gwar has one weakness it's his stomach. There's one meat for certain that he'd never be able to pass up.$B$B\"Two Huge Pincers\", the mother of all crabs, Kili'ua, paces upon her island out in the waters to the southwest. You must pay her a visit and return with her meat.",logDesc="Obtain The Flesh of \"Two Huge Pincers\" and deliver it to Tua'kea at Moa'ki Harbor."} end
if not DB[12017] then DB[12017]={id=12017,zoneId=65,name="Meat on the Hook",level=73,minLevel=71,giver="Tua'kea",giverType="NPC",giverId=26245,ender="Tua'kea",enderType="NPC",enderId=26245,poiX=2729,poiY=936,wowhead="https://www.wowhead.com/wotlk/quest=12017",image="assets/images/quests/placeholder.png",xpDiff=6,money=106000,desc="The time has come my friend: Tu'u'gwar must be dealt with!$B$BI've prepped the meat so that the beast is sure to come once you bait the hook I have out in the water. Just follow the fishing line here down to it.$B$BWhatever you do, don't let Tu'u'gwar swallow you whole, $N!",logDesc="Slay Tu'u'gwar and then return to Tua'kea at Moa'ki Harbor.",choiceRewards={{id=37936,qty=1},{id=37980,qty=1},{id=38023,qty=1},{id=38084,qty=1}}} end
if not DB[12018] then DB[12018]={id=12018,zoneId=65,name="Sweet Revenge",level=73,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=12018",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="You there... you look the fighting type.  I want some sweet Revenge on the Scourge that killed my family.  Go get me 2 Stone Hunks O' Gargoyle so that I can throw them on the ground and stomp on them violently until they are mashed into itty bitty pebbly bits. $b$bYes. Go. Kill.",logDesc="Obtain 2 Stone Hunks O' Gargoyle from Carrion Gargoyles in the Eastern Carrion Fields.  Return to Lord Bevis when the task is complete."} end
if not DB[12019] then DB[12019]={id=12019,zoneId=3537,name="Last Rites",level=72,minLevel=68,giver="Thassarian",giverType="NPC",giverId=26170,ender="Thassarian",enderType="NPC",enderId=26170,poiX=3296,poiY=3683,wowhead="https://www.wowhead.com/wotlk/quest=12019",image="assets/images/quests/placeholder.png",xpDiff=7,money=150000,desc="I served Arthas in death, because I had no choice.  He had control over my will and my body.  The Cult of the Damned serves Arthas in life... willingly.$B$BNow that we know the words of power to enter Naxxanar we can put an end to the cultist blight.  Go to En'kilah and look for the teleportation orb beneath the floating citadel.$B$BWork your way up and meet me at the top.  Arm yourself with what courage you can, we might not make it out of this alive.",logDesc="Go to the Temple City of En'kilah and find the teleportation orb beneath the floating Scourge citadel of Naxxanar.  Use it to reach the top and help Thassarian there.",choiceRewards={{id=38238,qty=1},{id=38237,qty=1},{id=38240,qty=1},{id=38241,qty=1},{id=38242,qty=1},{id=38239,qty=1}}} end
if not DB[12020] then DB[12020]={id=12020,zoneId=-370,name="This One Time, When I Was Drunk...",level=-1,minLevel=1,ender="Boxey Boltspinner",enderType="NPC",enderId=27215,wowhead="https://www.wowhead.com/wotlk/quest=12020",image="assets/images/quests/placeholder.png",desc="The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.$b$bHead over to Boxey and explain your heroic triumph over the Dark Iron dwarves.",logDesc="Talk to Boxey Boltspinner in the Brewfest camp.",rewards={{id=37829,qty=10}}} end
if not DB[12021] then DB[12021]={id=12021,zoneId=65,name="A Letter Home",level=73,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=12021",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="This letter appears to be addressed to a resident of Stormwind from one of the late Villagers in the Carrion Fields.  Perhaps one of the surviving residents in the Eastern camp would be interested in forwarding it to its intended recipient.",logDesc="Bring the letter home to Lady Alustra in the Eastern Carrion Fields."} end
if not DB[12022] then DB[12022]={id=12022,zoneId=-370,name="Chug and Chuck!",level=-1,minLevel=1,giver="Boxey Boltspinner",giverType="NPC",giverId=27215,ender="Boxey Boltspinner",enderType="NPC",enderId=27215,poiX=-5185,poiY=-539,wowhead="https://www.wowhead.com/wotlk/quest=12022",image="assets/images/quests/placeholder.png",desc="Hey there!  You look like you can handle your brew.  But can you handle your brew mug? $b$bThe Dark Irons have come back with a vengeance to ruin our celebration.  Tossing mugs at them is the best way to stop them, but first, let's see if you can toss one at old S.T.O.U.T. here.$b$bIt's easy, pick up a complimentary sampler and take a drink.  Just make sure you're facing S.T.O.U.T.  Talk to me after you've hit him 5 times.",logDesc="Use the Complimentary Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Boxey Boltspinner.",rewards={{id=37829,qty=10}}} end
if not DB[12023] then DB[12023]={id=12023,zoneId=65,name="Sweeter Revenge",level=73,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=12023",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="Satisfyingly crunchy.  Now... you... $R thing... there's an Abomination wandering the hillside to the south.  Go kill it.  Kill it good.",logDesc="Kill the Abomination on the hillside in Eastern Carrion Fields.  Return to Lord Bevis once the slaughter is complete."} end
if not DB[12024] then DB[12024]={id=12024,zoneId=65,name="Recording the Fallen",level=73,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=12024",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="Thank you for coming $N.  We haven't recieved any word from Wintergarde Keep.  I'm sure they're still battling the Scourge, but I can believe they left us alone to this slaughter.  $b$bWe need to gather the names of the dead so that we can notify their families.  When the Alliance Military brought us here, we all filled out Settlement Documentation and were required to keep it on our persons.  $b$bGo sift through the corpses and bring me any Documents that you find so that I can start a list of the names.",logDesc="Search the skeletons in the Carrion Fields for Alliance Settlement Documents."} end
if not DB[12025] then DB[12025]={id=12025,zoneId=65,name="A Scarlet Among Us",level=73,minLevel=70,wowhead="https://www.wowhead.com/wotlk/quest=12025",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="It's good to see that you were not ravaged by the Scourge as well.  Perhaps you'd be willing to lend a hand.  $b$bThe Scarlet Crusade has taken up a post to the north with the obvious intent of battling the Scourge.  The thing that bothers me is that they were building before we were attacked - they must have known something.  $b$bI need to know if one of our Villagers was involved.  Search for evidence on those of us that were brought back as ghouls.  If you find anything, bring it to me.",logDesc="Search for evidence of the Scarlet Crusade on the freshly risen Carrion Ghouls in the Eastern Carrion Fields.  Return to Lady Alustra with anything you find."} end
if not DB[12026] then DB[12026]={id=12026,zoneId=394,name="The Damaged Journal",level=75,minLevel=73,ender="Sage Paluna",enderType="NPC",enderId=26584,rewardNextId=12054,wowhead="https://www.wowhead.com/wotlk/quest=12026",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps in the dwarven language.$B$BThe only text you're able to decipher is the name of Brann Bronzebeard scrawled at the end of one of the entries.$B$BThe back half of the book, containing the most recent entries, has been torn away. Someone thought the notes important enough to attempt to destroy them. Perhaps gathering the missing pages from the battlefield will yield some clues.",logDesc="Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Sage Paluna at Camp Oneqwah."} end
if not DB[12027] then DB[12027]={id=12027,zoneId=394,name="Mr. Floppy's Perilous Adventure",level=74,minLevel=73,giver="Emily",giverType="NPC",giverId=26588,ender="Squire Walter",enderType="NPC",enderId=26371,poiX=4323,poiY=-3694,wowhead="https://www.wowhead.com/wotlk/quest=12027",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Excuse me, $g Mister: Ma'am;, do you know the way back to the soldiers' camp?$B$BMr. Floppy and I decided to go for a walk in the woods, and my brother Walter was gonna come with us, but then he had squire things to do.$B$BSo Mr. Floppy and I went by ourselves, but we got lost, and there were a whole bunch of hungry wolves, but we found this tower.$B$BThe wolves went away, but we're still lost.$B$BI asked Mr. Floppy, and he doesn't know the way back. Would you help us? Please?",logDesc="Help Emily and Mr. Floppy get back to the Westfall Brigade Encampment, then speak to Squire Walter.",choiceRewards={{id=38714,qty=1},{id=39018,qty=1},{id=39047,qty=1},{id=39079,qty=1}}} end
if not DB[12028] then DB[12028]={id=12028,zoneId=65,name="Spiritual Insight",level=72,minLevel=71,giver="Toalu'u the Mystic",giverType="NPC",giverId=26595,ender="Toalu'u the Mystic",enderType="NPC",enderId=26595,rewardNextId=12030,poiX=2746,poiY=871,wowhead="https://www.wowhead.com/wotlk/quest=12028",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="$R, we have not heard from our people at Indu'le Village since the ground shook and was torn apart!$B$BHave you ever been upon a vision quest? You've bested Loguhn, so you must be capable.$B$BI will give you a special incense to sprinkle into my brazier. Breathe deep from its vapors and your spirit will be sent aloft to view what has transpired at Indu'le.$B$BAs your spirit soars, I will be able to look through your eyes.",logDesc="Speak with Toalu'u the Mystic at Moa'ki Harbor after you have attained your spiritual insight."} end
if not DB[12029] then DB[12029]={id=12029,zoneId=394,name="Seared Scourge",level=74,minLevel=73,giver="Mack Fearsen",giverType="NPC",giverId=26604,ender="Mack Fearsen",enderType="NPC",enderId=26604,rewardNextId=12037,poiX=3827,poiY=-1986,wowhead="https://www.wowhead.com/wotlk/quest=12029",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="<Hic>... gotta burn these corpshes 'fore they shtart walkin' around again.$b$bPoppa always said, only thing worshe than havin' to kill a troll is havin' ta kill a troll twice.$b$bSay,<hic>... shpeakin' of Scourge, we can't get into tha' troll keep up north 'til we get them trolls thinned out a bit.$b$bHow 'bout ya take shome o my grog here and put them bashtards outta their misery?",logDesc="Mack at Granite Springs wants you to use his grog to burn 20 Famished Scourge Trolls at Drak'Tharon."} end
if not DB[12030] then DB[12030]={id=12030,zoneId=65,name="Elder Mana'loa",level=72,minLevel=71,giver="Toalu'u the Mystic",giverType="NPC",giverId=26595,rewardNextId=12031,poiX=2746,poiY=871,wowhead="https://www.wowhead.com/wotlk/quest=12030",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="My people....$B$B<The mystic is on the verge of breaking down.>$B$BWhile your spirit was flying through the village, I sensed that Elder Mana'loa took notice of you. $N, he wishes to speak with you. The stone elders are revered by us as fonts of ancient wisdom.$B$BThe elder must want to help. Seek him in the northwest corner of the village.",logDesc="Speak with the statue, Elder Mana'loa, at Indu'le Village."} end
if not DB[12031] then DB[12031]={id=12031,zoneId=65,name="Freedom for the Lingering",level=72,minLevel=71,rewardNextId=12032,wowhead="https://www.wowhead.com/wotlk/quest=12031",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The sacred ground of the elves to the west has been torn asunder. Now their magic is moving through the land causing ruin where it flows.$B$BThe souls of the Kalu'ak are in danger as the blue dragons forces attempt to control the magic.$B$BThe power came up through the lake, instantly slaying most in the village. Those that survived were driven insane.$B$B$N, you must release these spirits so that they may move on. Leave the deranged living alone; they may yet regain their sanity in time.",logDesc="Put to rest any combination of 15 Indu'le Fishermen, Mystics and Warriors, then return to Elder Mana'loa at Indu'le Village."} end
if not DB[12032] then DB[12032]={id=12032,zoneId=65,name="Conversing With the Depths",level=72,minLevel=71,ender="Toalu'u the Mystic",enderType="NPC",enderId=26595,wowhead="https://www.wowhead.com/wotlk/quest=12032",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="The watery goddess, Oacha'noa, must be consulted; only she will know what the destiny of the Kalu'ak is to be. And only The Pearl of the Depths can call her forth from the murky nether.$B$BOff the coast to the southwest rises The Briny Pinnacle. Atop it sits the altar upon which the pearl rests.$B$BCommune at the altar and Oacha'noa is certain to hear your call. Do as she says lest you incur her wrath and bring ruin upon all of the tuskarr.$B$BShould you survive, return to the mystic.",logDesc="Commune with The Pearl of the Depths and do as the sea-goddess Oacha'noa instructs.$B$BShould you survive the ordeal, return to Toalu'u the Mystic at Moa'ki Harbor.",choiceRewards={{id=38148,qty=1},{id=38150,qty=1},{id=38128,qty=1},{id=38127,qty=1},{id=38146,qty=1},{id=38126,qty=1}}} end
if not DB[12033] then DB[12033]={id=12033,zoneId=65,name="Message from the West",level=72,minLevel=71,giver="Messenger Torvus",giverType="NPC",giverId=26649,ender="Messenger Torvus",enderType="NPC",enderId=26649,poiX=3825,poiY=1534,wowhead="https://www.wowhead.com/wotlk/quest=12033",image="assets/images/quests/placeholder.png",xpDiff=4,desc="<Torvus shakes your hand, giving you a letter in the process.>$B$B<Torvus speaks under his breath.>$B$BJust play along, $N.$B$BIt is good to see you here, soldier! Lord Hellscream has undoubtedly sent his strongest warriors to Lord Agmar!$B$B<Torvus speaks under his breath.>$B$BRead it and then destroy it in the fire pot next to me.",logDesc="Read the Letter from Saurfang and then destroy it.$B$BSpeak to Messenger Torvus once you have completed this task."} end
if not DB[12034] then DB[12034]={id=12034,zoneId=65,name="Victory Nears...",level=72,minLevel=71,giver="Overlord Agmar",giverType="NPC",giverId=26379,ender="Senior Sergeant Juktok",enderType="NPC",enderId=26415,rewardNextId=12036,poiX=3842,poiY=1487,wowhead="https://www.wowhead.com/wotlk/quest=12034",image="assets/images/quests/placeholder.png",xpDiff=1,desc="There remain only two primary threats that stand in our way. One is the dread citadel of Naxxramas, far to the east, above the Alliance fortress of Wintergarde and the other is the Pit of Narjun, exit point for the undead armies of Azjol'Nerub. It is from the Pit of Narjun that the Anub'ar Nerubians assaulted and ultimately razed the taunka village of Icemist.$B$BWe will destroy the Anub'ar and close off the Pit of Narjun.$B$BReport to Senior Sergeant Juktok for your mission orders.",logDesc="Speak to Senior Sergeant Juktok at Agmar's Hammer."} end
if not DB[12035] then DB[12035]={id=12035,zoneId=3537,name="Repurposed Technology",level=71,minLevel=68,giver="Jeremiah Hawning",giverType="NPC",giverId=26084,ender="Jeremiah Hawning",enderType="NPC",enderId=26084,poiX=2476,poiY=5216,wowhead="https://www.wowhead.com/wotlk/quest=12035",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Ok, I've got it!  The rewiring is a little complicated, but nothing a clever $c like you can't handle.$B$BTake my tools and put some of the harvest collectors out of commission.  Once they're down use the tools to plug all the red wires into the blue sockets.  That'll make them go into self-defense mode.  Hurry, $N.  Before long there won't be anything left to save.",logDesc="Jeremiah Hawning at Farshire wants you to destroy 5 Harvest Collectors and then use Jeremiah's Tools to rewire them.",choiceRewards={{id=37206,qty=1},{id=37403,qty=1},{id=37417,qty=1},{id=37482,qty=1}}} end
if not DB[12036] then DB[12036]={id=12036,zoneId=65,name="From the Depths of Azjol-Nerub",level=72,minLevel=71,giver="Senior Sergeant Juktok",giverType="NPC",giverId=26415,ender="Senior Sergeant Juktok",enderType="NPC",enderId=26415,rewardNextId=12053,poiX=3833,poiY=1574,wowhead="https://www.wowhead.com/wotlk/quest=12036",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The undead Nerubians that attacked Icemist Village came from a gigantic sinkhole known as the Pit of Narjun. If left alone, those fiends will no doubt flank our forces at the Wrathgate and end our march to victory.$B$BI need eyes on the ground, $N. You are to head west and investigate the Pit of Narjun. We need to locate their primary exit point and seal it off! Find me that location.$B",logDesc="Explore the Pit of Narjun and return with your findings to Senior Sergeant Juktok at Agmar's Hammer."} end
if not DB[12037] then DB[12037]={id=12037,zoneId=4196,name="Search and Rescue",level=74,minLevel=72,giver="Mack Fearsen",giverType="NPC",giverId=26604,ender="Kurzel",enderType="NPC",enderId=26664,rewardNextId=13129,poiX=3827,poiY=-1986,wowhead="https://www.wowhead.com/wotlk/quest=12037",image="assets/images/quests/placeholder.png",xpDiff=8,money=224000,desc="Orc women... they just don't lissen - hic. Know what I mean, $r?$b$bKurzel's been with us fer years. You'd think she'd get a feel fer how we do things by now. Lure the fools in fer the dangerous work, then reap the rewards when it's safe. What's so hard to understand?$b$bNot her though... impatient green-skin goes off and takes matters into her own hands. Probably dead by now, but I'd feel horrible if we didn't follow after her, and I'm in no shape to do it myself - hic.$b$bSo whatdya say, pal?",logDesc="Mack at Granite Springs wants you to go into Drak'Tharon and find out what became of Kurzel.",choiceRewards={{id=39649,qty=1},{id=39648,qty=1},{id=39650,qty=1}}} end
if not DB[12038] then DB[12038]={id=12038,zoneId=394,name="Seared Scourge",level=72,minLevel=70,giver="Mack Fearsen",giverType="NPC",giverId=26604,ender="Mack Fearsen",enderType="NPC",enderId=26604,poiX=3827,poiY=-1986,wowhead="https://www.wowhead.com/wotlk/quest=12038",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Whatcha waitin' fer, $c? Them shcourged trolls ain't gunna kill themselves!$b$bYou know the drill. Git up ta Drak'Tharon up north... Take some o thish here grog and hurl it at 'em from a distance...<hic>.  Then jusht sit back an' watch 'em burn.",logDesc="Mack at Granite Springs wants you to use his grog to burn 30 Famished Scourge Trolls."} end
if not DB[12039] then DB[12039]={id=12039,zoneId=65,name="Black Blood of Yogg-Saron",level=72,minLevel=71,giver="Borus Ironbender",giverType="NPC",giverId=26564,ender="Borus Ironbender",enderType="NPC",enderId=26564,rewardNextId=12048,poiX=3810,poiY=1574,wowhead="https://www.wowhead.com/wotlk/quest=12039",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Angrathar, the Wrathgate... I watched as the metal holding the gate together pulsed and undulated as if it were alive! In 50 years I've never seen metal \"breathe.\"$B$BOnly ones who knew anything about it were the tuskarr. They called it the \"Black Blood of Yogg-Saron\" and told me to keep my distance.$B$BThere's a sinkhole outside Icemist Village to the west called the Pit of Narjun. I've heard of these sinkholes being rich with this strange ore. If you head that way, could you try and get me some samples?",logDesc="Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to recover 10 Black Blood of Yogg-Saron Samples."} end
if not DB[12040] then DB[12040]={id=12040,zoneId=65,name="An Enemy in Arthas",level=72,minLevel=71,giver="Kilix the Unraveler",giverType="NPC",giverId=26653,ender="Kilix the Unraveler",enderType="NPC",enderId=26653,rewardNextId=12041,poiX=3676,poiY=2159,wowhead="https://www.wowhead.com/wotlk/quest=12040",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We are in the midst of a civil war. At the heart of this world the last living members of my species defend themselves against total annihilation. The Lich King seeks to rule the kingdom of Azjol-Nerub at any cost. Those that do not acquiesce are branded enemies of the Scourge and marked for death.$B$BIn Arthas we both have an enemy...$B$BJoin our cause and rid this place of the taint of Anub'ar! Let Anub'arak himself hear the anguish of their death cries!",logDesc="Kilix the Unraveler at the Pit of Narjun in the Dragonblight has asked that you slay 6 Anub'ar Underlords.$B"} end
if not DB[12041] then DB[12041]={id=12041,zoneId=65,name="The Lost Empire",level=72,minLevel=71,giver="Kilix the Unraveler",giverType="NPC",giverId=26653,ender="Overlord Agmar",enderType="NPC",enderId=26379,poiX=3676,poiY=2159,wowhead="https://www.wowhead.com/wotlk/quest=12041",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You have proven that you are willing to assist the Azjol Empire in its time of need and as such the Azjol Empire will assist the Horde.$B$BTake this scroll back to your leader. It documents the strengths and weaknesses of the Nerubians attacking Icemist Village. Consider it a gesture of good faith - a willingness to help your people. Use the knowledge on those pages to crush the Anub'ar and you will have done a service for us all.$B$BFarewell, $r.$B",logDesc="Deliver Kilix's Battle Plan to Overlord Agmar at Agmar's Hammer to the east.",choiceRewards={{id=37954,qty=1},{id=37996,qty=1},{id=38040,qty=1},{id=38101,qty=1}}} end
if not DB[12042] then DB[12042]={id=12042,zoneId=394,name="Heart of the Ancients",level=74,minLevel=73,giver="Image of Drakuru",giverType="NPC",giverId=26543,rewardNextId=12802,poiX=4244,poiY=-2025,wowhead="https://www.wowhead.com/wotlk/quest=12042",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Secrets of da ages, be revealed to me now!$b$b<Drakuru peers through the Eye of the Prophets.>$b$bAhh, great be mah destiny, $n. You be lucky ta know me....$b$bThere! I be seein' it, mon. The Heart of the Ancients. Dis be too easy!$b$bYou gunna find da heart lyin' near da corpse of a goblin east of here. He be up in a chamber, near a river of broken trees.$b$bHurry, mon, before someone else be findin' it!",logDesc="Drakuru wants you to go to the uppermost chamber at Blue Sky Logging Ground and find the Heart of the Ancients.",rewards={{id=36739,qty=1}}} end
if not DB[12043] then DB[12043]={id=12043,zoneId=65,name="Nozzlerust Defense",level=74,minLevel=72,giver="Narf",giverType="NPC",giverId=26647,ender="Narf",enderType="NPC",enderId=26647,poiX=4691,poiY=572,wowhead="https://www.wowhead.com/wotlk/quest=12043",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="You, $c!  These undead south of us are being a constant nuisance to our work.  Go clear them out, will ya?",logDesc="Kill 12 Wastes Diggers and 1 Wastes Taskmaster at the digs surrounding Galakrond's Rest.  Return to Narf at Nozzlerust Post when the task is complete."} end
if not DB[12044] then DB[12044]={id=12044,zoneId=65,name="Stocking Up",level=74,minLevel=72,giver="Xink",giverType="NPC",giverId=26660,ender="Xink",enderType="NPC",enderId=26660,poiX=4699,poiY=541,wowhead="https://www.wowhead.com/wotlk/quest=12044",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Hello hello!  The Scourge to the south are digging up some ancient dragon thing.  I could care less why they're doing it, but they're pulling cartloads of composite ore in the process.$b$bGo lift me a bunch of that ore.  That stuff should yield a pretty penny for all the weapons the Horde are crafting.$B",logDesc="Gather 8 bundles of Composite Ore from the digs surrounding Galakrond's Rest and bring them to Xink at Nozzlerust Post."} end
if not DB[12045] then DB[12045]={id=12045,zoneId=65,name="Shaved Ice",level=74,minLevel=72,giver="Zivlix",giverType="NPC",giverId=26661,ender="Zivlix",enderType="NPC",enderId=26661,rewardNextId=12046,poiX=4706,poiY=559,wowhead="https://www.wowhead.com/wotlk/quest=12045",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="I've never seen you before... are you new to the Vice?  Glad to have you.  I could always use some more hands.$b$bYou get the materials, I'll finish my machine, then we can sell it to those commander types and all go home rich.$b$bI actually have most of the primary components, so I just need some of the materials for the weapon itself.  Narf said that jagged ice shards from those elementals to the north would make perfect shrapnel for my bombs - go nab some, will ya?$B",logDesc="Collect 4 Ice Shard Clusters from Ice Elementals in the north and bring them to Zivlix at Nozzlerust Post."} end
if not DB[12046] then DB[12046]={id=12046,zoneId=65,name="Soft Packaging",level=74,minLevel=72,giver="Zivlix",giverType="NPC",giverId=26661,ender="Zivlix",enderType="NPC",enderId=26661,rewardNextId=12047,poiX=4706,poiY=559,wowhead="https://www.wowhead.com/wotlk/quest=12046",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="I need some new packaging for the shrapnel bombs.  All the stuff I have is too hard and the shrapnel doesn't spread when it bursts.  $b$bWhat we need is some really thin animal hide.  Those jormungar tunnelers to the west might work... or perhaps the condors sifting through the dragon bones.  Go get me whatever you can find.$B",logDesc="Collect 12 Thin Animal Hides from the Jormungar Tunnelers or the Dragonbone Condors near Nozzlerust Post.  Once you've located the hides, return them to Zivlix."} end
if not DB[12047] then DB[12047]={id=12047,zoneId=65,name="Something That Doesn't Melt",level=74,minLevel=72,giver="Zivlix",giverType="NPC",giverId=26661,ender="Zivlix",enderType="NPC",enderId=26661,poiX=4706,poiY=559,wowhead="https://www.wowhead.com/wotlk/quest=12047",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="No no no! Those ice shards didn't work at all! They'll melt before they even do any damage. That's the last time I'll trust Narf's word on materials. This means we need something else entirely for the shrapnel.$b$bI know! I'm brilliant. Bone splinters.$b$bThere are some bones all around here that the jormungar have been gnawing on pretty thoroughly. Go check them out and see if you can find me some splintered bone that I can use.",logDesc="Search the dragon bones east of Nozzlerust Post for 12 Splintered Bone Chunks.",choiceRewards={{id=37948,qty=1},{id=37991,qty=1},{id=38035,qty=1},{id=38080,qty=1},{id=38072,qty=1}}} end
if not DB[12048] then DB[12048]={id=12048,zoneId=65,name="Scourge Armaments",level=72,minLevel=71,giver="Borus Ironbender",giverType="NPC",giverId=26564,ender="Borus Ironbender",enderType="NPC",enderId=26564,poiX=3810,poiY=1574,wowhead="https://www.wowhead.com/wotlk/quest=12048",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I can't make a damned thing out of this ore. It simply will not hold together! Despite my best efforts the Scourge metal will not bend!$B$BPerhaps if I had some samples of some forged Scourge armaments I might be able to reverse engineer the process by which the items are created.$B$BIcemist Village is crawling with armored Scourge Nerubians. Go there and get me some Scourge armaments! With your help I might actually succeed in creating something from this ore.$B$BYou'll find Icemist to the west.",logDesc="Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to bring him 8 Scourge Armaments.",choiceRewards={{id=37961,qty=1},{id=38003,qty=1},{id=38045,qty=1},{id=38107,qty=1}}} end
if not DB[12049] then DB[12049]={id=12049,zoneId=65,name="Hard to Swallow",level=74,minLevel=72,giver="Xink",giverType="NPC",giverId=26660,ender="Xink",enderType="NPC",enderId=26660,poiX=4699,poiY=541,wowhead="https://www.wowhead.com/wotlk/quest=12049",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Those troops are sure to be needin' a hefty supply of food in their bellies.$B$BI'll let you in on a little secret that a squeamish $r like you would never know... those jormungar worms taste just like chicken.$b$bGo provoke one of those giant hulking jormungar to the east.  You're not likely to be able to kill one straight out, so just toss this down its throat when it opens its mouth wide.  Bring me back as many of the slabs of meat as you can tote.",logDesc="Battle a Hulking Jormungar east of Nozzlerust Post until it opens its mouth, then throw a Potent Explosive Charge into its throat. After it explodes, collect 6 slabs of Seared Jormungar Meat off of the ground and bring them back to Xink."} end
if not DB[12050] then DB[12050]={id=12050,zoneId=65,name="Lumber Hack",level=74,minLevel=72,giver="Xink",giverType="NPC",giverId=26660,ender="Xink",enderType="NPC",enderId=26660,poiX=4699,poiY=541,wowhead="https://www.wowhead.com/wotlk/quest=12050",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Next up, we need to haul in some lumber for all the towers the Alliance are building.  There are some thin trees to the south, but the trees the Harpies are nesting in to the north look much more fit for structures.$b$bTake this.  When you get to the Harpy nesting area, use the control and one of my Shredders should come to you.  Gather as much lumber as it can carry.  The Harpies are sure to disagree with you chopping down their homes - just deal with them as necessary.$b$bHop to it!",logDesc="Use Xink's Shredder Control Device to call a Shredder once you reach the Harpy Nesting Grounds in the North.  Gather 50 Bundles of Lumber from the trees in the area, and then return to Xink at Nozzlerust Post.$B$BShould you lose Xink's Shredder Control Device, speak to Xink at Nozzlerust Post to obtain a new one.",choiceRewards={{id=38197,qty=1},{id=38141,qty=1},{id=38143,qty=1},{id=38191,qty=1},{id=38187,qty=1},{id=38142,qty=1}}} end
if not DB[12051] then DB[12051]={id=12051,zoneId=65,name="Rustling Some Feathers",level=74,minLevel=72,wowhead="https://www.wowhead.com/wotlk/quest=12051",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Those harpies have slowed our profits long enough!  Kill them all.",logDesc="Kill 20 Harpies Northwest of Nozzlerust Post for Narf at Nozzlerust Post."} end
if not DB[12052] then DB[12052]={id=12052,zoneId=65,name="Harp on This!",level=74,minLevel=72,giver="Narf",giverType="NPC",giverId=26647,ender="Narf",enderType="NPC",enderId=26647,poiX=4691,poiY=572,wowhead="https://www.wowhead.com/wotlk/quest=12052",image="assets/images/quests/placeholder.png",xpDiff=6,money=112000,desc="$C, did you see that? That's the harpy that's been leading the attack on our shipments to the gate! I've seen her in the back of Coldwind Heights before.$B$B Those harpies have slowed our profits long enough! Kill them all.",logDesc="Kill the Mistress of the Coldwind and 15 Coldwind harpies in the mountains northwest of Nozzlerust Post. Return to Narf once the task is complete.$B$BShould you be in need of Xink's Shredder Control Device, speak to Xink at Nozzlerust Post.",choiceRewards={{id=37947,qty=1},{id=37990,qty=1},{id=38034,qty=1},{id=38097,qty=1}}} end
if not DB[12053] then DB[12053]={id=12053,zoneId=65,name="The Might of the Horde",level=72,minLevel=71,giver="Senior Sergeant Juktok",giverType="NPC",giverId=26415,ender="Senior Sergeant Juktok",enderType="NPC",enderId=26415,rewardNextId=12071,poiX=3833,poiY=1574,wowhead="https://www.wowhead.com/wotlk/quest=12053",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The taunka are now our brothers in arms. We must show our solidarity and retake Icemist Village.$B$BYou will find Icemist Village west of Agmar's Hammer, sitting at the foot of the mountains. Travel there and challenge the Anub'ar Nerubians! Plant our beloved Horde banner at Icemist Village and destroy all that dare come to tear it down!$B$BLet the Anub'ar feel the true might of the Horde! Let our battle standard be the last thing that they see before death!",logDesc="Senior Sergeant Juktok at Agmar's Hammer in the Dragonblight wants you to use the Warsong Battle Standard at Icemist Village and defend it against attackers.$B$BReturn the Warsong Battle Standard when you are finished.",choiceRewards={{id=37956,qty=1},{id=37998,qty=1},{id=38041,qty=1},{id=38102,qty=1}}} end
if not DB[12054] then DB[12054]={id=12054,zoneId=394,name="Deciphering the Journal",level=75,minLevel=73,giver="Sage Paluna",giverType="NPC",giverId=26584,ender="Sage Paluna",enderType="NPC",enderId=26584,poiX=3845,poiY=-4533,wowhead="https://www.wowhead.com/wotlk/quest=12054",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Vor'takh is right -- we cannot allow this opportunity to slip through our fingers.$B$BFortunately, I think I know of a way to translate the journal of this Brann.$B$BThe shamans of the Redfang furbolgs, who congregate at the Heart's Blood Shrine south of the camp, grow an herb known as spiritsbreath. An experienced mystic can use incense made from it to seek wisdom from the spirits of the ancestors.$B$BSeek out the shaman known as Grumbald One-Eye. He should carry the herb for his devotions to Ursoc.",logDesc="Bring a sprig of Spiritsbreath to Sage Paluna at Camp Oneqwah."} end
if not DB[12055] then DB[12055]={id=12055,zoneId=65,name="A Strange Device",level=72,minLevel=71,ender="Image of Archmage Modera",enderType="NPC",enderId=26673,rewardNextId=12060,wowhead="https://www.wowhead.com/wotlk/quest=12055",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Picking up this strange device, you are certain that it is magical in nature. Unfortunately, it doesn't seem to connote any other kind of use.$B$BPerhaps the archmage back at Stars' Rest to the east of the Moonrest Gardens would be able to tell what it's used for?",logDesc="Deliver Goramosh's Strange Device to the Image of Archmage Modera at Stars' Rest."} end
if not DB[12056] then DB[12056]={id=12056,zoneId=65,name="Marked for Death: High Cultist Zangus",level=72,minLevel=71,giver="Captain Gort",giverType="NPC",giverId=26618,ender="Captain Gort",enderType="NPC",enderId=26618,poiX=3765,poiY=1619,wowhead="https://www.wowhead.com/wotlk/quest=12056",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I witnessed his treachery with my own eyes! The traitor led an Anub'ar assault on this stronghold, taking out some of my best soldiers.$B$B<Gort shakes his head.>$B$BHe'd been working with the Scourge the whole time and we didn't have a clue! How many more like Zangus are there? We'll find 'em all and when we do...$B$B<Gort makes a cutting motion across his neck.>$B$BFirst on the list is Zangus. Our scouts report that he is hiding in The Pit of Narjun, west of here. Find him, kill him, bring me his head.$B",logDesc="Kill High Cultist Zangus and return High Cultist Zangus's Head to Captain Gort at Agmar's Hammer in the Dragonblight."} end
if not DB[12057] then DB[12057]={id=12057,zoneId=65,name="The Flesh-Bound Tome",level=72,minLevel=71,ender="Captain Gort",enderType="NPC",enderId=26618,rewardNextId=12115,wowhead="https://www.wowhead.com/wotlk/quest=12057",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The tome is bound in flesh and appears to be bleeding. Upon examination you discover page after page filled with strange symbols that appear to be written in blood.$B$BWhatever knowledge is held within the pages of this tome could be important. Return it to Captain Gort at Agmar's Hammer, east of Icemist Village.",logDesc="Return the Flesh-bound Tome to Captain Gort at Agmar's Hammer."} end
if not DB[12058] then DB[12058]={id=12058,zoneId=394,name="The Runic Prophecies",level=75,minLevel=73,giver="Sage Paluna",giverType="NPC",giverId=26584,ender="Sage Paluna",enderType="NPC",enderId=26584,rewardNextId=12204,poiX=3845,poiY=-4533,wowhead="https://www.wowhead.com/wotlk/quest=12058",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Brann's journal also contained a guide to iron dwarf symbols. I've inscribed these on a keystone which will help you to understand the words inscribed on the rune plates.$B$BFrom the journal entries, it seems Brann may be chasing after clues to the origins of his people. Keep your eyes open for any clues as to his destination.$B$BReturn to Thor Modan, northeast of here, stand before each of the plates, and use the stone to determine the contents of each. We can't allow the Alliance to find him first.",logDesc="Sage Paluna at Camp Oneqwah wants you to decipher the three Rune Plates.",choiceRewards={{id=38710,qty=1},{id=39013,qty=1},{id=39043,qty=1},{id=39075,qty=1}}} end
if not DB[12059] then DB[12059]={id=12059,zoneId=65,name="A Strange Device",level=72,minLevel=71,ender="Image of Archmage Aethas Sunreaver",enderType="NPC",enderId=26471,rewardNextId=12061,wowhead="https://www.wowhead.com/wotlk/quest=12059",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Picking up this strange device, you are certain that it is magical in nature. Unfortunately, it doesn't seem to connote any other kind of use.$B$BPerhaps the archmage back at Agmar's Hammer to the northeast of the Moonrest Gardens would be able to tell what it's used for?",logDesc="Deliver Goramosh's Strange Device to the Image of Archmage Aethas Sunreaver at Agmar's Hammer."} end
if not DB[12060] then DB[12060]={id=12060,zoneId=65,name="Projections and Plans",level=72,minLevel=71,giver="Image of Archmage Modera",giverType="NPC",giverId=26673,ender="Image of Archmage Modera",enderType="NPC",enderId=26673,rewardNextId=12065,poiX=3501,poiY=2001,wowhead="https://www.wowhead.com/wotlk/quest=12060",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="This is a teleportation device. If I had to guess, I'd say that it leads to the surge needle platform floating above the Moonrest Gardens to the west.$B$BI need you to use it to investigate what's up there. It appears that the device works both ways so you shouldn't have to jump off.$B$BI expect that once you teleport to the top of the surge needle, there will be some sort of apparatus on it to observe.$B$BYou should be able to use the teleporter from anywhere within the gardens.",logDesc="Get close to and observe the projection atop the Surge Needle floating above Moonrest Gardens.$B$BAfterward, return to the Image of Archmage Modera at Stars' Rest with the information."} end
if not DB[12061] then DB[12061]={id=12061,zoneId=65,name="Projections and Plans",level=72,minLevel=71,giver="Image of Archmage Aethas Sunreaver",giverType="NPC",giverId=26471,ender="Image of Archmage Aethas Sunreaver",enderType="NPC",enderId=26471,rewardNextId=12066,poiX=3847,poiY=1493,wowhead="https://www.wowhead.com/wotlk/quest=12061",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="This is a teleportation device. If I had to guess, I'd say that it leads to the surge needle platform floating above the Moonrest Gardens to the southwest.$B$B$N, I need you to use it to investigate what's up there. It appears that the device works both ways so you shouldn't have to jump off.$B$BI expect that once you teleport up to the top of the surge needle, there will be some sort of apparatus on it to observe.$B$BYou should be able to use the teleporter from anywhere within the gardens.",logDesc="Get close to and observe the projection atop the Surge Needle floating above Moonrest Gardens.$B$BAfterward, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer with the information."} end
if not DB[12062] then DB[12062]={id=12062,zoneId=-370,name="Insult Coren Direbrew",level=80,minLevel=75,giver="Brewfest Spy",giverType="NPC",giverId=26719,ender="Coren Direbrew",enderType="NPC",enderId=23872,wowhead="https://www.wowhead.com/wotlk/quest=12062",image="assets/images/quests/placeholder.png",desc="Coren Direbrew is in the next room, riling up Dark Iron dwarves for another attack on Brewfest.  Defeat him!$B$BGo to Coren and pick a fight.  Tell him his beer isn't fit for pigs.$B$BWhen you do that, be ready for a fight.  The last person who insulted his brew... was fed to dire boars.",logDesc="Speak with Coren Direbrew."} end
if not DB[12063] then DB[12063]={id=12063,zoneId=65,name="Strength of Icemist",level=72,minLevel=71,giver="Greatmother Icemist",giverType="NPC",giverId=26652,ender="Banthok Icemist",enderType="NPC",enderId=26733,rewardNextId=12064,poiX=3820,poiY=1619,wowhead="https://www.wowhead.com/wotlk/quest=12063",image="assets/images/quests/placeholder.png",xpDiff=4,desc="<Greatmother Icemist bows.>$B$BIt is an honor to meet you, hero. It is because of your actions that many of us are here now, alive and ready for battle against the Scourge.$B$BYou have done so much for us that it shames me to ask you for your assistance once more. Despite my pleas, my only son, Banthok, left here to go in search of his father, High Chief Icemist. He was last seen heading west, towards Icemist Village. Please find Banthok. I do not know what I would do if I lost my son.",logDesc="Find Banthok Icemist at Icemist Village."} end
if not DB[12064] then DB[12064]={id=12064,zoneId=65,name="Chains of the Anub'ar",level=72,minLevel=71,giver="Banthok Icemist",giverType="NPC",giverId=26733,ender="Banthok Icemist",enderType="NPC",enderId=26733,rewardNextId=12069,poiX=4015,poiY=2360,wowhead="https://www.wowhead.com/wotlk/quest=12064",image="assets/images/quests/placeholder.png",xpDiff=5,desc="They have my father bound by magical chains in the middle of Icemist Village. From what I have been able to gather, the prison is controlled by three powerful Anub'ar magi - each holding a piece of the key.$B$BScour Icemist and locate the magi. Kill them and take their key fragments. With all three pieces we might be able to free my father. Once he is free...$B$BRetribution will come swiftly.",logDesc="Banthok Icemist at Icemist Village in the Dragonblight has asked that you bring him Anok'ra's Key Fragment, Tivax's Key Fragment and Sinok's Key Fragment.$B",choiceRewards={{id=37959,qty=1},{id=38001,qty=1},{id=38044,qty=1},{id=38105,qty=1}}} end
if not DB[12065] then DB[12065]={id=12065,zoneId=65,name="The Focus on the Beach",level=72,minLevel=71,giver="Image of Archmage Modera",giverType="NPC",giverId=26673,ender="Image of Archmage Modera",enderType="NPC",enderId=26673,rewardNextId=12083,poiX=3501,poiY=2001,wowhead="https://www.wowhead.com/wotlk/quest=12065",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The mage hunter forces are active on the Glittering Strand to the south of Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and a captain who is in charge of it.$B$BNo doubt the captain will have some sort of controlling device on their person. Get the controller and use it on the focus.$B$BWith any luck, we'll be able to get some more information about what they're really up to out there.",logDesc="Obtain the Ley Line Focus Control Ring and use it to gain information from the Ley Line Focus on the Glittering Strand.$B$BThen, return to the Image of Archmage Modera at Stars' Rest."} end
if not DB[12066] then DB[12066]={id=12066,zoneId=65,name="The Focus on the Beach",level=72,minLevel=71,giver="Image of Archmage Aethas Sunreaver",giverType="NPC",giverId=26471,ender="Image of Archmage Aethas Sunreaver",enderType="NPC",enderId=26471,rewardNextId=12084,poiX=3847,poiY=1493,wowhead="https://www.wowhead.com/wotlk/quest=12066",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The mage hunter forces are active on the Glittering Strand to the south of Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and a captain who is in charge of it.$B$BNo doubt the captain of the force down there will have some sort of controlling device on their person. Get the controller and use it on the focus.$B$BWith any skill on your part, we'll be able to get some more information about what they're really up to out there.",logDesc="Obtain the Ley Line Focus Control Ring and use it to gain information from the Ley Line Focus on the Glittering Strand.$B$BThen, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer."} end
if not DB[12067] then DB[12067]={id=12067,zoneId=65,name="A Letter for Home",level=72,minLevel=71,ender="Commander Saia Azuresteel",enderType="NPC",enderId=26459,wowhead="https://www.wowhead.com/wotlk/quest=12067",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="You find a letter secreted in the lining of her robes. It reads:$B$B\"Father,$B$BI'm sorry for disappearing on you. If you're reading this letter, then I'm dead.$B$BI've been forced to work for Malygos's armies under threat that our family would be killed if I didn't. I feel so ashamed.$B$BIf there's anything that you can do to fight them, don't worry about me. I have them fooled and I'm sabotaging them from the inside.$B$BI love you, Daddy!$B$BEm\"$B$BCommander Saia Azuresteel will want to see this!",logDesc="Deliver Captain Malin's Letter to Commander Saia Azuresteel at Stars' Rest."} end
if not DB[12068] then DB[12068]={id=12068,zoneId=394,name="Voices From the Dust",level=75,minLevel=73,giver="Image of Drakuru",giverType="NPC",giverId=26701,ender="Image of Drakuru",enderType="NPC",enderId=26787,rewardNextId=12238,poiX=4524,poiY=-3473,wowhead="https://www.wowhead.com/wotlk/quest=12068",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="<Drakuru places the Eye of the Prophets on his brow and the Heart of the Ancients on his chest.>$b$bWe be close, mon, very close!$b$bThe Drakkari Tablets be all dat remain ta be found. Nobody be knowin' how old dey be or what dey be sayin', but with the eye and the heart Drakuru can be readin' dem. Dey lie deep inside the crypt at Drakil'jin, due east of here.$b$bOnce ya got the tablets, get sacred mojo from the oracles and protectors so ya can summon me there. They'd be proud to be dyin' for such a cause.",logDesc="Drakuru wants you to collect the Drakkari Tablets from the Ruins of Drakil'jin and 5 Sacred Mojo from Drakkari Oracles and Protectors there. You are then to use Drakuru's Elixir at Drakuru's Brazier at the ruins to summon his image.",choiceRewards={{id=38718,qty=1},{id=39022,qty=1},{id=39051,qty=1},{id=39089,qty=1},{id=38751,qty=1}}} end
if not DB[12069] then DB[12069]={id=12069,zoneId=65,name="Return of the High Chief",level=73,minLevel=71,giver="Banthok Icemist",giverType="NPC",giverId=26733,ender="Overlord Agmar",enderType="NPC",enderId=26379,rewardNextId=12140,poiX=4015,poiY=2360,wowhead="https://www.wowhead.com/wotlk/quest=12069",image="assets/images/quests/placeholder.png",xpDiff=7,desc="<Banthok hands you the prison key.>$B$BYou must hurry, $N. Take the key and use it to unchain my father from the Anub'ar prison. Once he is freed, assist him in destroying the Anub'ar leader, Under-king Anub'et'kan. When the Under-king is defeated, take from his chitinous carapace a fragment as a trophy to present to the Horde at Agmar's Hammer. Let Agmar see the might of the High Chief!",logDesc="Free High Chief Icemist using the Anub'ar Prison Key and assist him in defeating Under-king Anub'et'kan.$B$BRecover a Fragment of Anub'et'kan's Husk and return it to Overlord Agmar at Agmar's Hammer in the Dragonblight."} end
if not DB[12070] then DB[12070]={id=12070,zoneId=394,name="Rallying the Troops",level=75,minLevel=72,giver="3",giverType="NPC",giverId=26260,ender="3",enderType="NPC",enderId=26260,rewardNextId=11985,poiX=4894,poiY=-4563,wowhead="https://www.wowhead.com/wotlk/quest=12070",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="The sons of iron have used their runes to enthrall many of my brothers and are using them to break the siege on Thor Modan. I wish we did not have to fight them, but we have no choice.$B$BMy giants will not hold out long against them.$B$BI have imbued this earthen shard with a blessing that will aid our allies. Take it with you to the battle in the Boulder Hills to the north, and use it to reassure and fortify my brethren.$B$BKill any iron dwarves who would stand in your way.",logDesc="Use the Shard of the Earth to rally the Grizzly Hills Giants fighting in the Boulder Hills, kill any iron dwarves who oppose you, then report to Kurun on the hill overlooking Thor Modan."} end
if not DB[12071] then DB[12071]={id=12071,zoneId=65,name="Attack by Air! ",level=72,minLevel=71,giver="Senior Sergeant Juktok",giverType="NPC",giverId=26415,ender="Valnok Windrager",enderType="NPC",enderId=26574,rewardNextId=12072,poiX=3833,poiY=1574,wowhead="https://www.wowhead.com/wotlk/quest=12071",image="assets/images/quests/placeholder.png",xpDiff=1,desc="They have seen the might of the Horde by land, now they must feel it from the air! I want you to report to Valnok Windrager at once! You will find him here, in Agmar's Hammer.$B$BValnok has already been briefed on your mission and is expecting you.$B",logDesc="Speak with Valnok Windrager at Agmar's Hammer."} end
if not DB[12072] then DB[12072]={id=12072,zoneId=65,name="Blightbeasts be Damned!",level=72,minLevel=71,giver="Valnok Windrager",giverType="NPC",giverId=26574,ender="Valnok Windrager",enderType="NPC",enderId=26574,poiX=3866,poiY=1540,wowhead="https://www.wowhead.com/wotlk/quest=12072",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You've no doubt seen the army of Anub'ar blightbeasts that are being constructed at Icemist Village. The Anub'ar have plans to send those monsters against our soldiers at the Wrathgate. This cannot happen!$B$BVenture west to Icemist Village with this flare gun and use it to call down one of my war riders. Climb on its back and command it to destroy the blightbeasts that are out of reach from the ground!$B$BOnce you have decimated their aerial forces, return to me for your reward!",logDesc="Use Valnok's Flare Gun to call down a Kor'kron War Rider at Icemist Village. Mount the Kor'kron War Rider and then use it to kill 25 Anub'ar Blightbeasts!$B$BReturn to Valnok Windrager at Agmar's Hammer should you complete this mission.",choiceRewards={{id=37957,qty=1},{id=37999,qty=1},{id=38042,qty=1},{id=38103,qty=1}}} end
if not DB[12073] then DB[12073]={id=12073,zoneId=394,name="Pounding the Iron",level=75,minLevel=73,giver="Scout Vor'takh",giverType="NPC",giverId=26666,ender="Scout Vor'takh",enderType="NPC",enderId=26666,rewardNextId=12204,poiX=3848,poiY=-4532,wowhead="https://www.wowhead.com/wotlk/quest=12073",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="The Alliance isn't the only force opposing us in Grizzly Hills. The iron dwarves have firm control of the eastern coast, although Thor Modan, to the northeast, is besieged by stone giants.$B$BA skilled warrior uses an enemy's weakness against him and we would be fools to ignore the vulnerability of the iron dwarves at Thor Modan. Show the iron dwarves no mercy. Slay any and all who would stand in your way.$B$BThe 'sons of iron' will learn to fear the Horde.",logDesc="Kill any 10 Iron Dwarves defending Thor Modan and report back to Scout Vor'takh at Camp Oneqwah."} end
if not DB[12074] then DB[12074]={id=12074,zoneId=394,name="An Expedient Ally",level=75,minLevel=73,giver="Scout Vor'takh",giverType="NPC",giverId=26666,ender="3",enderType="NPC",enderId=26260,rewardNextId=11982,poiX=3848,poiY=-4532,wowhead="https://www.wowhead.com/wotlk/quest=12074",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The old iron dwarf capital of Thor Modan, far to the northeast, is under siege by a mysterious band of stone giants and earthen.$B$BWhy the creations of the titans would war against each other is beyond my understanding and the Horde's interest, but there is an opportunity here to weaken a mutual enemy.$B$BTravel to Thor Modan and seek out this 'Kurun' who commands the giants and earthen. Make common cause with him and use his forces to crush the iron dwarves.",logDesc="Speak with Kurun on the hill overlooking Thor Modan."} end
if not DB[12075] then DB[12075]={id=12075,zoneId=65,name="Slim Pickings",level=74,minLevel=72,giver="Zort",giverType="NPC",giverId=26659,ender="Zort",enderType="NPC",enderId=26659,rewardNextId=12076,poiX=4895,poiY=296,wowhead="https://www.wowhead.com/wotlk/quest=12075",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Cold out here, isn't it, $r?$B$BKo'char has refused to meet with me. It seems he has more pressing things on his mind - namely, the jormungar that have been attacking them from the cavern below. Maybe you can help me convince Ko'char that I'm one of the good guys.$b$bI saw a giant being eaten by some of the worms at the entrance to the cavern north of here... I'm still puzzled as to how the worms are killing them so easily. Bring me a sample from one of his wounds.",logDesc="Collect a sample of Rockflesh from the Ice Giant corpse at the cavern entrance in the Crystal Vice, north of Zort's location. After this task is complete, return to Zort near the center of the canyon."} end
if not DB[12076] then DB[12076]={id=12076,zoneId=65,name="Messy Business",level=74,minLevel=72,giver="Zort",giverType="NPC",giverId=26659,ender="Zort",enderType="NPC",enderId=26659,rewardNextId=12077,poiX=4895,poiY=296,wowhead="https://www.wowhead.com/wotlk/quest=12076",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Even at first glance, the sample you brought me shows obvious signs of some kind of corrosive spit. It would be a natural assumption that the same substance these worms use to burrow through the ground has allowed them a formidable weapon against the Ice Giants.$b$bTake this scraper and pick a fight with some of the worms. When they spit on you, use the scraper to remove it and bring it back to me.$B$BGet me a couple samples - I'm going to have to use it as the base for an elixir.",logDesc="Collect 2 Vials of Corrosive Spit from the Jormungar by using the scraper on yourself.  Bring the vials back to Zort in the Crystal Vice when your task is complete."} end
if not DB[12077] then DB[12077]={id=12077,zoneId=65,name="Apply This Twice A Day",level=74,minLevel=72,giver="Zort",giverType="NPC",giverId=26659,ender="Ko'char the Unbreakable",enderType="NPC",enderId=26473,poiX=4895,poiY=296,wowhead="https://www.wowhead.com/wotlk/quest=12077",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="This elixir should protect against their spit. Offer it to Ko'char for me, will you? Tell him there's plenty more where that came from if he'll return the favor.",logDesc="Offer the elixir that Zort has prepared to Ko'char the Unbreakable.",rewards={{id=36770,qty=1}}} end
if not DB[12078] then DB[12078]={id=12078,zoneId=65,name="Worm Wrangler",level=74,minLevel=72,giver="Zort",giverType="NPC",giverId=26659,ender="Zort",enderType="NPC",enderId=26659,poiX=4895,poiY=296,wowhead="https://www.wowhead.com/wotlk/quest=12078",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="So be it. If the giants will not come to our aid, perhaps we can make use of these worms. There are sure to be some spawn with their brood mother in the cavern below. Take this box and capture 3 of their spawn and bring them to me.$b$bWhere diplomacy fails, enslaving is a perfectly viable alternative.",logDesc="Enter the caverns in Crystal Vice and trap 3 Jormungar Spawn inside sturdy crates.  Be sure to pick the crates up after the Jormungar Spawn are trapped inside!$B$BBring the captured Jormungar Spawn back to Zort in the Crystal Vice."} end
if not DB[12079] then DB[12079]={id=12079,zoneId=65,name="Stomping Grounds",level=74,minLevel=72,giver="Ko'char the Unbreakable",giverType="NPC",giverId=26473,ender="Ko'char the Unbreakable",enderType="NPC",enderId=26473,poiX=4910,poiY=319,wowhead="https://www.wowhead.com/wotlk/quest=12079",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Greetings little one.  I know not what madness has brought you to the Crystal Vice, but you are welcome in my presence.  $b$bThese ice worms... these jormungar have taken a taste to eating my brothers.  I doubt you will find my kind friendly by any terms during this time of battle, but if you are here to help with the worms, then you have my ear.$b$bIf we are to take the cavern back, we must first clear the canyon of these jormungar feeders.  Join us in battle, $r!",logDesc="Delve into the cavern at the north end of the Crystal Vice and kill 8 Ice Heart Jormungar Feeders for Ko'char the Unbreakable."} end
if not DB[12080] then DB[12080]={id=12080,zoneId=65,name="Really Big Worm",level=74,minLevel=72,giver="Ko'char the Unbreakable",giverType="NPC",giverId=26473,ender="Ko'char the Unbreakable",enderType="NPC",enderId=26473,poiX=4910,poiY=319,wowhead="https://www.wowhead.com/wotlk/quest=12080",image="assets/images/quests/placeholder.png",xpDiff=7,money=168000,desc="The jormungar have a spawnmother in the caverns below. We call her Rattlebore - a name that was gifted to her by an adventurer from the Plaguelands. I saw her only briefly as I was fighting off their initial onslaught - she is large enough to make even my icy bones shiver. This cavern will not be ours until she is removed from it.$b$bGather your friends and end this.",logDesc="Enter the Ice Heart Cavern and slay Rattlebore.  If it is still in your possession, be sure to use Zort's Protective Elixir to protect you from the Jormungar's corrosive spit.$B$BReturn to Ko'char the Unbreakable in the Crystal Vice when the task is complete.",choiceRewards={{id=37945,qty=1},{id=37989,qty=1},{id=38033,qty=1},{id=38096,qty=1}}} end
if not DB[12081] then DB[12081]={id=12081,zoneId=394,name="Gavrock",level=75,minLevel=72,giver="3",giverType="NPC",giverId=26260,ender="3",enderType="NPC",enderId=26420,rewardNextId=12093,poiX=4894,poiY=-4563,wowhead="https://www.wowhead.com/wotlk/quest=12081",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Without your help, we wouldn't have been able to turn the tide of the battle for Thor Modan. This ancient city has long been a battlefield between the forces of earth and stone. I can only hope we have silenced it for the last time.$B$BThe iron dwarves can still use their magic to capture and enslave my brothers. Gavrock is searching for a way to free the runed giants. Look for him on a small cluster of islands, called the Ruins of Tethys, off the central part of the Eastwind Shore to the south.",logDesc="Speak with Gavrock at the Ruins of Tethys."} end
if not DB[12082] then DB[12082]={id=12082,zoneId=394,name="Dun-da-Dun-tah!",level=75,minLevel=73,giver="Harrison Jones",giverType="NPC",giverId=26814,ender="Harkor",enderType="NPC",enderId=26884,poiX=4905,poiY=-4759,wowhead="https://www.wowhead.com/wotlk/quest=12082",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Listen, kid. This is no place for you to be playin' around.$b$bI'm about to make a break for it. Stick with me and I'll get you outta here.",logDesc="Escort Harrison from Drakil'jin Ruins, then speak with Harkor at Harkor's Camp.",choiceRewards={{id=38729,qty=1},{id=39028,qty=1},{id=39056,qty=1},{id=39094,qty=1}}} end
if not DB[12083] then DB[12083]={id=12083,zoneId=65,name="Atop the Woodlands",level=72,minLevel=71,giver="Image of Archmage Modera",giverType="NPC",giverId=26673,ender="Image of Archmage Modera",enderType="NPC",enderId=26673,rewardNextId=12098,poiX=3501,poiY=2001,wowhead="https://www.wowhead.com/wotlk/quest=12083",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I'm convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don't know precisely what they're doing with all of that power, though.$B$BMy guess is that you'll find another one atop the Lothalor Woodlands to the southeast. Once again you'll need to find the person in charge and take whatever controlling device they have in their possession as I'm sure that each focus has its own.$B$BBe careful, $N, those woods are very dangerous.",logDesc="Obtain the Ley Line Focus Control Amulet and use it to gain information from the Ley Line Focus in the Lothalor Woodlands.$B$BThen, return to the Image of Archmage Modera at Stars' Rest.",choiceRewards={{id=37942,qty=1},{id=37985,qty=1},{id=38029,qty=1},{id=38093,qty=1}}} end
if not DB[12084] then DB[12084]={id=12084,zoneId=65,name="Atop the Woodlands",level=72,minLevel=71,giver="Image of Archmage Aethas Sunreaver",giverType="NPC",giverId=26471,ender="Image of Archmage Aethas Sunreaver",enderType="NPC",enderId=26471,rewardNextId=12106,poiX=3847,poiY=1493,wowhead="https://www.wowhead.com/wotlk/quest=12084",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I'm convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don't know precisely what they're doing with all of that power, though.$B$BMy guess is that you'll find another one atop the Lothalor Woodlands to the south. Once again you'll need to find the person in charge and take whatever controlling device they have in their possession as I'm sure that each focus has its own.$B$BBe quick about your business, $c. I feel that time may be running out.",logDesc="Obtain the Ley Line Focus Control Amulet and use it to gain information from the Ley Line Focus in the Lothalor Woodlands.$B$BThen, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.",choiceRewards={{id=37942,qty=1},{id=37985,qty=1},{id=38029,qty=1},{id=38093,qty=1}}} end
if not DB[12085] then DB[12085]={id=12085,zoneId=65,name="A Letter for Home",level=72,minLevel=71,ender="Overlord Agmar",enderType="NPC",enderId=26379,wowhead="https://www.wowhead.com/wotlk/quest=12085",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="You find a letter secreted in the lining of his robes. It reads:$B$B\"Deino,$B$BTa'zinni sorry for disappearing on ya. If you're reading this letter, then I be dead.$B$BI been forced to work for Malygos's armies under threat that the family would be killed if I didn't. Ta'zinni wasn't gonna let that happen!$B$BDon't worry about me, just keep your kids safe. I have them fooled and I'm sabotaging them from the inside.$B$BI love you, sistah!$B$BTa'zinni\"$B$BOverlord Agmar is sure to want to see this!",logDesc="Deliver Lieutenant Ta'zinni's Letter to Overlord Agmar at Agmar's Hammer."} end
if not DB[12086] then DB[12086]={id=12086,zoneId=3537,name="The Son of Karkut",level=72,minLevel=68,giver="Ataika",giverType="NPC",giverId=26169,ender="Corporal Venn",enderType="NPC",enderId=26187,rewardNextId=11944,poiX=3125,poiY=4893,wowhead="https://www.wowhead.com/wotlk/quest=12086",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The man you seek went far to the east, to a place near the coast called Death's Stand, beyond Unu'pe.$B$BBe careful if you go in search of him, $N.  He bore the mark of Karkut... he who watches over the dead.",logDesc="Go east to Death's Stand, just beyond Unu'pe."} end
if not DB[12087] then DB[12087]={id=12087,zoneId=3537,name="A Little Help Here? DEPRECATED",level=72,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=12087",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="We were sent here to take over the Howling Ziggurat, due north.  We weren't expecting to make it back alive.... hell, we already lost half our crew.$B$BTassarian was on point and the higher ups... well, they didn't like something about him.$B$BHe took off this morning... he might've gone to the ziggurat on his own.  But right now we have more pressing matters to worry about.  The Scourge keeps getting closer and closer to the camp, we need to take care of them -- now!",logDesc="Corporal Venn at Death's Stand wants you to kill 8 Ziggurat Defenders."} end
if not DB[12088] then DB[12088]={id=12088,zoneId=3537,name="Thassarian, the Death Knight",level=72,minLevel=68,giver="Corporal Venn",giverType="NPC",giverId=26187,ender="Thassarian",enderType="NPC",enderId=26170,poiX=3114,poiY=3843,wowhead="https://www.wowhead.com/wotlk/quest=12088",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Well, $N, you helped us out... so I figure it's only fair that we help you out as well.$B$BYou're looking for Thassarian?  He disappeared this morning.  We think he went off north to the Wailing Ziggurat.  If we hadn't fought side by side by him we'd even think he was a traitor.$B$BSee, he's a Death Knight... and I know they're on our side and all... but it wasn't too long ago they were servants of Arthas.$B$BBut not Thassarian, he's a good guy.  Go to the Wailing Ziggurat, see if he's doing okay.",logDesc="Look for Thassarian inside the Wailing Ziggurat, north of Death's Stand."} end
if not DB[12089] then DB[12089]={id=12089,zoneId=65,name="Wanted: Magister Keldonus",level=74,minLevel=71,ender="Captain Gort",enderType="NPC",enderId=26618,wowhead="https://www.wowhead.com/wotlk/quest=12089",image="assets/images/quests/placeholder.png",xpDiff=6,money=112000,desc="By decree of Overlord Agmar:$B$BTarget: Magister Keldonus$B$BCrime: Treason$B$BStatus: Alive$B$BMagister Keldonus, once mage commander of Agmar's Hammer, is to be killed on sight in the name of the Horde.$B$BKeldonus was last seen traveling southwest towards Moonrest Gardens to join the Blue Dragonflight in their campaign against magic.$B$BApproach with caution as Keldonus is a powerful magus. Do not engage solo!$B$BAll bounties are paid out by Captain Gort at Agmar's Hammer.",logDesc="Slay Magister Keldonus and return to Captain Gort at Agmar's Hammer in the Dragonblight.",choiceRewards={{id=38195,qty=1},{id=38194,qty=1},{id=38137,qty=1},{id=38189,qty=1},{id=38196,qty=1},{id=38138,qty=1}}} end
if not DB[12090] then DB[12090]={id=12090,zoneId=65,name="Wanted: Gigantaur",level=74,minLevel=71,ender="Captain Gort",enderType="NPC",enderId=26618,wowhead="https://www.wowhead.com/wotlk/quest=12090",image="assets/images/quests/placeholder.png",xpDiff=6,money=112000,desc="By decree of Overlord Agmar:$B$BTarget: Gigantaur$B$BCrime: Attacks upon the Horde; \"Bein' ugly\"$B$BStatus: Alive$B$BThe magnataur lord, Gigantaur, is wanted in relation to a number of attacks against Horde soldiers and installations in the Dragonblight.$B$BGigantaur was last seen wandering the woods and roads south by southeast of Agmar's Hammer.$B$BGigantaur should be considered armed and extremely dangerous. Do not engage solo!$B$BAll bounties are paid out by Captain Gort at Agmar's Hammer.",logDesc="Slay Gigantaur and return to Captain Gort at Agmar's Hammer in the Dragonblight.$B",choiceRewards={{id=37969,qty=1},{id=38012,qty=1},{id=38055,qty=1},{id=38116,qty=1}}} end
if not DB[12091] then DB[12091]={id=12091,zoneId=65,name="Wanted: Dreadtalon",level=74,minLevel=71,ender="Captain Gort",enderType="NPC",enderId=26618,wowhead="https://www.wowhead.com/wotlk/quest=12091",image="assets/images/quests/placeholder.png",xpDiff=6,money=112000,desc="By decree of Overlord Agmar:$B$BTarget: Dreadtalon$B$BCrime: Attacks upon the Horde$B$BStatus: Alive$B$BDreadtalon is wanted for numerous attacks upon Horde caravans traveling to and from Venomspite.$B$BDreadtalon makes his home on a bluff overlooking the Ruby Dragonshrine, east of Agmar's Hammer. He should be approached with extreme caution. Do not engage solo!$B$BAll bounties are paid out by Captain Gort at Agmar's Hammer.",logDesc="Slay Dreadtalon and return to Captain Gort at Agmar's Hammer in the Dragonblight.",choiceRewards={{id=37970,qty=1},{id=38013,qty=1},{id=38056,qty=1},{id=38117,qty=1}}} end
if not DB[12092] then DB[12092]={id=12092,zoneId=65,name="Strengthen the Ancients",level=72,minLevel=71,giver="Sarendryana",giverType="NPC",giverId=26837,ender="Sarendryana",enderType="NPC",enderId=26837,poiX=3439,poiY=2016,wowhead="https://www.wowhead.com/wotlk/quest=12092",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="It's not only the $r race that has been impacted by what the blue dragonflight forces have done. The ancients of the Lothalor Woods to the southeast have been affected as well.$B$BSome have been corrupted-- avoid them at all costs--but most can still be saved. However, the treants of the woods seem to be immune to the magic seeping through the land and the arcane wyrms that have come with it.$B$BAsk the treants for their bark and feed it to the ancients. Hopefully that will be enough to save them.",logDesc="Use the Bark of the Walkers to strengthen 3 Lothalor Ancients and then return to Sarendryana at Stars' Rest.",choiceRewards={{id=37966,qty=1},{id=38008,qty=1},{id=38051,qty=1},{id=38112,qty=1}}} end
if not DB[12093] then DB[12093]={id=12093,zoneId=394,name="Runes of Compulsion",level=75,minLevel=72,giver="3",giverType="NPC",giverId=26420,ender="3",enderType="NPC",enderId=26420,rewardNextId=12094,poiX=4341,poiY=-5298,wowhead="https://www.wowhead.com/wotlk/quest=12093",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Even as Kurun attacks Thor Modan, the iron dwarves work their magics against our brothers. Summoning our brothers from the earth, then binding them with runes, the sons of iron force them to war against the children of stone.$B$BAlong the Eastwind Shore, they use runes of compulsion to send enslaved giants to the battlefields of the north.$B$BFind the four runes of compulsion and force their overseers to appear by defeating the rune-weavers who man each rune. Without the overseers, the runes are useless.",logDesc="Gavrock, at the Ruins of Tethys, wants you to neutralize the four Runes of Compulsion by defeating Overseer Durval, Overseer Korgan, Overseer Lochli, and Overseer Brunon."} end
if not DB[12094] then DB[12094]={id=12094,zoneId=394,name="Latent Power",level=75,minLevel=72,giver="3",giverType="NPC",giverId=26420,ender="3",enderType="NPC",enderId=26420,rewardNextId=12099,poiX=4341,poiY=-5298,wowhead="https://www.wowhead.com/wotlk/quest=12094",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="While the runes of compulsion are dormant, there is a chance we can release the runed giants.$B$BI will give you a piece of stone that has been part of me since my creation. If properly imbued, it can be used to free the bound giants.$B$BTwo ancient stone markers sit atop places of power between the Path of Iron and the forest's edge -- locations your people would call the intersections of ley lines. The other is on an island at the southern end of these ruins. Charge the shard at each stone and return.",logDesc="Charge the Shard of Gavrock at the First Ancient Stone, the Second Ancient Stone, and the Third Ancient Stone, then return to Gavrock at the Ruins of Tethys."} end
if not DB[12095] then DB[12095]={id=12095,zoneId=65,name="To Dragon's Fall",level=75,minLevel=71,giver="Captain Gort",giverType="NPC",giverId=26618,ender="Rokhan",enderType="NPC",enderId=26859,rewardNextId=12097,poiX=3765,poiY=1619,wowhead="https://www.wowhead.com/wotlk/quest=12095",image="assets/images/quests/placeholder.png",xpDiff=1,desc="East of here, in the heart of the Dragonblight, is a field full of nothing but dragon bones and snow. The Scourge have set up multiple camps in the central tundra and are raising frostwyrms to send against our forces at the Wrathgate. While most of these frostwyrms are easily dealt with by Rokhan and his dragon hunters, one of them is proving to be a bit problematic.$B$BGo northeast and seek out Rokhan at Dragon's Fall. Help him and his men put down Sarathstra and you'll be rewarded handsomely!",logDesc="Speak with Rokhan at Dragon's Fall in the Dragonblight."} end
if not DB[12096] then DB[12096]={id=12096,zoneId=65,name="Strengthen the Ancients",level=72,minLevel=71,giver="Earthwarden Grife",giverType="NPC",giverId=26854,ender="Earthwarden Grife",enderType="NPC",enderId=26854,poiX=3785,poiY=1579,wowhead="https://www.wowhead.com/wotlk/quest=12096",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The ancients of the Lothalor Woods to the south are being corrupted by arcane wyrms... wyrms which have risen out of the ground!$B$BThose that are already corrupted are deadly and of no use to us, but most can still be saved. Luckily, the treants of the woods seem to be immune to everything happening up there.$B$BAsk the treants for their bark and when you get some, feed it to the ancients. This should strengthen them.$B$BNow leave me to my business! I have to keep an eye on these apothecaries.",logDesc="Use the Bark of the Walkers to strengthen 3 Lothalor Ancients and then return to Earthwarden Grife at Agmar's Hammer.",choiceRewards={{id=37966,qty=1},{id=38008,qty=1},{id=38051,qty=1},{id=38112,qty=1}}} end
if not DB[12097] then DB[12097]={id=12097,zoneId=65,name="Sarathstra, Scourge of the North",level=75,minLevel=71,giver="Rokhan",giverType="NPC",giverId=26859,ender="Captain Gort",enderType="NPC",enderId=26618,poiX=4340,poiY=980,wowhead="https://www.wowhead.com/wotlk/quest=12097",image="assets/images/quests/placeholder.png",xpDiff=7,money=177000,desc="Me hunters be dead or frozen, $N. Just you and whatever allies you bring wit ya is all da help you get. You still want to do dis? Just say da word and me call for da dragon once more.$B$BIf ya kill it, take da beast's frozen heart back to Agmar's Hammer and present it to Gort. He sure to reward you good, mon.",logDesc="Speak with Rokhan to call down the frostwyrm, Sarathstra.$B$BKill Sarathstra and deliver Sarathstra's Frozen Heart to Captain Gort at Agmar's Hammer.",choiceRewards={{id=38530,qty=1},{id=38532,qty=1},{id=38531,qty=1},{id=38533,qty=1}}} end
if not DB[12098] then DB[12098]={id=12098,zoneId=65,name="Search Indu'le Village",level=72,minLevel=71,giver="Image of Archmage Modera",giverType="NPC",giverId=26673,ender="Mage-Commander Evenstar",enderType="NPC",enderId=26873,rewardNextId=12107,poiX=3501,poiY=2001,wowhead="https://www.wowhead.com/wotlk/quest=12098",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I'm certain that you'll find the next ley line focus somewhere in the remains of Indu'le Village to the southeast. The problem is, we've had absolutely no reports of there being one there.$B$BIf you would, please investigate the village for any signs of the focus or the mage hunters and their commander in the area.$B$BDon't forget to search in the lake if you have to.",logDesc="Search for the commander of the mage hunter forces at Indu'le Village and Lake Indu'le."} end
if not DB[12099] then DB[12099]={id=12099,zoneId=394,name="Free at Last",level=75,minLevel=72,giver="3",giverType="NPC",giverId=26420,ender="3",enderType="NPC",enderId=26420,poiX=4341,poiY=-5298,wowhead="https://www.wowhead.com/wotlk/quest=12099",image="assets/images/quests/placeholder.png",xpDiff=6,money=118000,desc="The rock shard you imbued should be powerful enough to break the runic magic binding my brothers.$B$BTake it with you and find the runed giants walking north along the Eastwind Shore. Unleash the power stored in the stone and observe the results.$B$BIf it works, the runed giants should return to their senses and stop obeying the iron dwarves. If the stone fails to work, the giants may attack in a weakened state. But, what choice do we have? If we do not try, they will remain enslaved without hope.",logDesc="Use Gavrock's Runebreaker to free 4 Runed Giants, then return to Gavrock at the Ruins of Tethys.",choiceRewards={{id=39117,qty=1},{id=39109,qty=1},{id=39120,qty=1},{id=39119,qty=1},{id=39112,qty=1}}} end
if not DB[12100] then DB[12100]={id=12100,zoneId=65,name="Containing the Rot",level=72,minLevel=71,giver="Soar Hawkfury",giverType="NPC",giverId=26504,ender="Soar Hawkfury",enderType="NPC",enderId=26504,rewardNextId=12101,poiX=3759,poiY=1548,wowhead="https://www.wowhead.com/wotlk/quest=12100",image="assets/images/quests/placeholder.png",xpDiff=5,desc="With Scourge comes death and disease. We often overlook that the wildlife of a Scourge infested area is ravaged and ultimately destroyed by rot and contagion.$B$BFor most of the indigenous beasts of the Dragonblight it is too late. The festering disease that the Scourge brings has already infected the beasts and they are now rabid and rotting.$B$BYou must venture west, towards the Pit of Narjun, and cull the infected wildlife. Check their corpses for a preserved organ as we need one to devise a vaccine.",logDesc="Soar Hawkfury at Agmar's Hammer in the Dragonblight wants you to kill 15 Infected Wildlife and recover a Rot Resistant Organ."} end
if not DB[12101] then DB[12101]={id=12101,zoneId=65,name="The Good Doctor...",level=72,minLevel=71,giver="Soar Hawkfury",giverType="NPC",giverId=26504,ender="Doctor Sintar Malefious",enderType="NPC",enderId=26505,rewardNextId=12102,poiX=3759,poiY=1548,wowhead="https://www.wowhead.com/wotlk/quest=12101",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Our Forsaken allies have sent their apothecary core here to assist us in destroying the Scourge at the Wrathgate. One among them, Doctor Sintar Malefious, is well versed in the Scourge rot and methods of containing the spread. I had previously worked out a deal with him in regards to devising a vaccine for wildlife. He's since been waiting on the organ.$B$BDeliver this rot resistant organ to Dr. Malefious and let him know it's from me. He'll direct you on your next task.",logDesc="Deliver the Rot Resistant Organ to Doctor Sintar Malefious at Agmar's Hammer.$B"} end
if not DB[12102] then DB[12102]={id=12102,zoneId=65,name="In Search of the Ruby Lilac",level=73,minLevel=71,giver="Doctor Sintar Malefious",giverType="NPC",giverId=26505,ender="Doctor Sintar Malefious",enderType="NPC",enderId=26505,rewardNextId=12104,poiX=3747,poiY=1603,wowhead="https://www.wowhead.com/wotlk/quest=12102",image="assets/images/quests/placeholder.png",xpDiff=5,desc="How fortuitous it is that the Ruby Dragonshrine lays just to the east. It is there that you will find a flower called the ruby lilac. This lifegiving plant is all that I need to concoct a vaccine for the untainted beasts of this region.$B$BTravel east and search the Ruby Dragonshrine for the lilac.$B$BJust one thing: The dragonshrine, like all the dragonshrines in this blasted wasteland, is beset by the Scourge. Watch your step. We wouldn't want you to be devoured by an emberwyrm.$B$B<Sintar laughs.>",logDesc="Doctor Sintar Malefious at Agmar's Hammer in the Dragonblight wants you to collect 1 Ruby Lilac."} end
if not DB[12103] then DB[12103]={id=12103,zoneId=3537,name="DEPRECATED",level=74,minLevel=72,wowhead="https://www.wowhead.com/wotlk/quest=12103",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I've heard enough, $N.  We must make sure whatever's happening at Silverbrook doesn't spread to the rest of the continent.$B$BI don't care if it's the water, the altitude or an ancient troll curse that's driven these villagers murderously insane... return to Silverbrook and put an end to them.",logDesc="Captain Derrick at Amberpine Lodge wants you to slay 8 Silverbrook Villagers and 8 Silverbrook Trappers."} end
if not DB[12104] then DB[12104]={id=12104,zoneId=65,name="Return to Soar",level=73,minLevel=71,giver="Doctor Sintar Malefious",giverType="NPC",giverId=26505,ender="Soar Hawkfury",enderType="NPC",enderId=26504,rewardNextId=12111,poiX=3747,poiY=1603,wowhead="https://www.wowhead.com/wotlk/quest=12104",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Doctor Malefious hands you a vial full of murky liquid.>$B$BHere you are then, $r. Take this back to the cow and let him know that all debts have been paid. We are officially \"square.\"$B$BNow leave me before I set Jennings upon you.",logDesc="Deliver Sintar's Vaccine to Soar Hawkfury at Agmar's Hammer."} end
if not DB[12105] then DB[12105]={id=12105,zoneId=394,name="Descent into Darkness",level=74,minLevel=73,ender="Lieutenant Dumont",enderType="NPC",enderId=26875,rewardNextId=12109,wowhead="https://www.wowhead.com/wotlk/quest=12105",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The journal was written by a denizen of Silverbrook named Mikhail.  It details the arrival of a shadow-worshipping group called the \"wolfcult.\"$B$BThe villagers were reluctant to embrace the cult at first, but sympathizers sprung up gradually among town residents.$B$BUnsettled by this, Mikhail sent his daughter Sasha away from Silverbrook while he attempted to reason with the other villagers.$B$BMikhail's last entry mentions a meeting of local town leaders to discuss unspecified events in Hollowstone Mine.",logDesc="Bring Mikhail's Journal to Lieutenant Dumont in Amberpine Lodge.",choiceRewards={{id=38734,qty=1},{id=39033,qty=1},{id=39060,qty=1},{id=39098,qty=1}}} end
if not DB[12106] then DB[12106]={id=12106,zoneId=65,name="Search Indu'le Village",level=72,minLevel=71,giver="Image of Archmage Aethas Sunreaver",giverType="NPC",giverId=26471,ender="Mage-Commander Evenstar",enderType="NPC",enderId=26873,rewardNextId=12110,poiX=3847,poiY=1493,wowhead="https://www.wowhead.com/wotlk/quest=12106",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I'm certain that you'll find the next ley line focus somewhere in the remains of Indu'le Village to the southeast. The problem is, I've had absolutely no reports of there being one there.$B$BI need you to go investigate the village for any signs of the focus or the mage hunters and their commander in the area.$B$BSearch in the lake if you have to!",logDesc="Search for the commander of the mage hunter forces at Indu'le Village and Lake Indu'le."} end
if not DB[12107] then DB[12107]={id=12107,zoneId=65,name="The End of the Line",level=72,minLevel=71,giver="Mage-Commander Evenstar",giverType="NPC",giverId=26873,ender="Image of Archmage Modera",enderType="NPC",enderId=26673,rewardNextId=12119,poiX=3074,poiY=1370,wowhead="https://www.wowhead.com/wotlk/quest=12107",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="Within his robes you find two things of interest.$B$BOne is a talisman, which is clearly a focus controlling device. The other is a set of orders from someone named Sidragos, which were ultimately intended for the leader back at the Moonrest Gardens.$B$BThe water-soaked parchment informs Goramosh that he is to move all mage hunter forces east to the Azure Dragonshrine.$B$BPerhaps you should get what information you can from the focus and head east to observe the dragonshrine from its western ledge.",logDesc="Use the Ley Line Focus Control Talisman to gain information from the Ley Line Focus under Lake Indu'le. Then, head east to the Azure Dragonshrine near south central Dragonblight and observe what is occurring there from the western ledge.$B$BAfterward, return to the Image of Archmage Modera at Stars' Rest.",choiceRewards={{id=38151,qty=1},{id=38152,qty=1},{id=38129,qty=1},{id=38153,qty=1},{id=38217,qty=1}}} end
if not DB[12108] then DB[12108]={id=12108,zoneId=3537,name="DEPRECATED",level=74,minLevel=72,wowhead="https://www.wowhead.com/wotlk/quest=12108",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The dirt mound is, indeed, a hastily dug grave.  The body beneath is unrecognizable but you find a note that identifies that man as Mikhail.$B$BThe note mentions Hollowstone Mine once again.  Perhaps someone back at Amberpine Lodge might be familiar with the area.",logDesc="Bring Mikhail's Note to Cartographer Tobias at Amberpine Lodge."} end
if not DB[12109] then DB[12109]={id=12109,zoneId=394,name="Report to Gryan Stoutmantle... Again",level=74,minLevel=73,giver="Lieutenant Dumont",giverType="NPC",giverId=26875,ender="Captain Gryan Stoutmantle",enderType="NPC",enderId=26212,rewardNextId=12158,poiX=3411,poiY=-2782,wowhead="https://www.wowhead.com/wotlk/quest=12109",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The Westfall boys were sent east to look for a path into the northern territories.  Their secondary objective is to secure strategic resource points, so I'm sure they wouldn't mind investigating a mine.$B$BLook for the Westfall Brigade encampment far to the northeast and seek out Gryan Stoutmantle.  You might remember him if you ever spent any time in Westfall.  Make sure to tell him I sent you.$B$BHe'll be more than happy to let you claim a functioning mine for the king.",logDesc="Speak to Captain Gryan Stoutmantle at the Westfall Brigade Encampment."} end
if not DB[12110] then DB[12110]={id=12110,zoneId=65,name="The End of the Line",level=72,minLevel=71,giver="Mage-Commander Evenstar",giverType="NPC",giverId=26873,ender="Image of Archmage Aethas Sunreaver",enderType="NPC",enderId=26471,rewardNextId=12122,poiX=3074,poiY=1370,wowhead="https://www.wowhead.com/wotlk/quest=12110",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="Within his robes you find two things of interest.$B$BOne is a talisman, which is clearly a focus controlling device. The other is a set of orders from someone named Sidragos, which were ultimately intended for the leader back at the Moonrest Gardens.$B$BThe fragile water-soaked parchment informs Goramosh that he is to move all mage hunter forces east to the Azure Dragonshrine.$B$BPerhaps you should get what information you can from the focus and head east to observe the dragonshrine from its western ledge.",logDesc="Use the Ley Line Focus Control Talisman to gain information from the Ley Line Focus under Lake Indu'le. Then, head east to the Azure Dragonshrine near south central Dragonblight and observe what is occurring there from the western ledge$B$BAfterward, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.",choiceRewards={{id=38151,qty=1},{id=38152,qty=1},{id=38129,qty=1},{id=38153,qty=1},{id=38217,qty=1}}} end
if not DB[12111] then DB[12111]={id=12111,zoneId=65,name="Where the Wild Things Roam",level=73,minLevel=71,giver="Soar Hawkfury",giverType="NPC",giverId=26504,ender="Soar Hawkfury",enderType="NPC",enderId=26504,poiX=3759,poiY=1548,wowhead="https://www.wowhead.com/wotlk/quest=12111",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="Inside this pack are several vials containing the vaccine that Sintar created. I now want you to search the nearby woods for Snowfall elk and arctic grizzlies. When you locate the animals, find a safe distance and throw a vial in their general direction. The vial will shatter and release a fine gas that will act as the inoculating agent. The beasts merely have to step inside the gas and they will be vaccinated - ultimately saved.$B$BInoculate as many of the beasts as you can and return to me.$B",logDesc="Soar Hawkfury at Agmar's Hammer in the Dragonblight wants you to use the Pack of Vaccine to vaccinate 5 Snowfall Elk and 5 Arctic Grizzlies.",choiceRewards={{id=38171,qty=1},{id=38172,qty=1},{id=38132,qty=1},{id=38169,qty=1},{id=38170,qty=1},{id=38131,qty=1}}} end
if not DB[12112] then DB[12112]={id=12112,zoneId=65,name="Stiff Negotiations",level=74,minLevel=72,giver="Narf",giverType="NPC",giverId=26647,ender="Zort",enderType="NPC",enderId=26659,rewardNextId=12075,poiX=4691,poiY=572,wowhead="https://www.wowhead.com/wotlk/quest=12112",image="assets/images/quests/placeholder.png",xpDiff=4,money=44000,desc="Well it seems you were of a bit of use after all. It's not been my experience to meet many a $r that are.$b$bWe don't have any more use for you here. Head into the Vice and see if my brother Zort could use a hand. He went to see if he could con the giants into laying down their lives so that we don't have to. He certainly wasn't known for having the brains in the family.  ",logDesc="Locate Zort in the center of the Crystal Vice, northeast of Nozzlerust Post."} end
if not DB[12113] then DB[12113]={id=12113,zoneId=394,name="Nice to Meat You",level=75,minLevel=73,giver="Harkor",giverType="NPC",giverId=26884,ender="Harkor",enderType="NPC",enderId=26884,poiX=4326,poiY=-4983,wowhead="https://www.wowhead.com/wotlk/quest=12113",image="assets/images/quests/placeholder.png",xpDiff=4,money=59000,desc="G'day to ya, $c! Have yerself a seat by me fire, eh?$b$bI'd offer to share a nice hot meal, only I ain't got one. I'm stuck here waitin' on an associate, or I'd be out tryin' to remedy that situation meself.$b$bSay, you seem to have nuthin' but time on yer hands and there be plenty o' meat in these parts. What say ya lend a hand and round up some grub? ",logDesc="Harkor at Harkor's Camp wants you to collect 10 pieces of Fibrous Worg Meat from Duskhowl Prowlers and 10 Shovelhorn Steaks from Longhoof Grazers."} end
if not DB[12114] then DB[12114]={id=12114,zoneId=394,name="Therapy",level=75,minLevel=73,giver="Harkor",giverType="NPC",giverId=26884,ender="Harkor",enderType="NPC",enderId=26884,poiX=4326,poiY=-4983,wowhead="https://www.wowhead.com/wotlk/quest=12114",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Trolls... me hates 'em all! <Harkor spits.>$b$bI once got meself captured by a band o' tha beasts... came this close ta gettin' me head shrunk!$b$bMe friends tell me to just move on and put it all behind me, but that just ain't sittin' right.$b$bWanna know what would make me feel better, $r? Seein' a pile of their corpses so high it blots out the sun! I've got good gold to spend if ya can make that happen.",logDesc="Harkor at Harkor's Camp wants you to kill 10 Drakkari Protectors and 10 Drakkari Oracles outside Drakil'jin Ruins.",choiceRewards={{id=38728,qty=1},{id=39027,qty=1},{id=39055,qty=1},{id=39093,qty=1},{id=38758,qty=1}}} end
if not DB[12115] then DB[12115]={id=12115,zoneId=65,name="Koltira and the Language of Death",level=72,minLevel=71,giver="Captain Gort",giverType="NPC",giverId=26618,ender="Koltira Deathweaver",enderType="NPC",enderId=26581,poiX=3765,poiY=1619,wowhead="https://www.wowhead.com/wotlk/quest=12115",image="assets/images/quests/placeholder.png",xpDiff=1,desc="There is one who recently joined our cause that might be able to decipher this tome. An unbound death knight known as Koltira Deathweaver has temporarily taken residence here at Agmar's Hammer. As he was once a death knight of Arthas and member of the Scourge, he might be able to translate the language of the dead.$B$BTake the flesh-bound tome to Koltira and ask him to translate the pages.$B",logDesc="Take the Flesh-Bound Tome to Koltira Deathweaver."} end
if not DB[12116] then DB[12116]={id=12116,zoneId=394,name="It Takes Guts....",level=75,minLevel=73,giver="Kraz",giverType="NPC",giverId=26886,ender="Kraz",enderType="NPC",enderId=26886,rewardNextId=12120,poiX=4322,poiY=-4991,wowhead="https://www.wowhead.com/wotlk/quest=12116",image="assets/images/quests/placeholder.png",xpDiff=6,money=118000,desc="Greetings, $c. It is kind of you to stop and listen to Kraz's tale.$b$bFor many years Kraz has strained to hear the spirits and do their bidding.$b$bRecently,  many voices have been crying to Kraz from these ruins. They seek for a peace they cannot find on their own.$b$bIf you would help the spirits of those who have come before, enter this crypt and collect something that once belonged to those tormented souls.",logDesc="Kraz at Harkor's Camp wants you to enter Drakil'jin Ruins and collect 5 Drakkari Canopic Jars."} end
if not DB[12117] then DB[12117]={id=12117,zoneId=65,name="Travel to Moa'ki Harbor",level=72,minLevel=68,giver="Hotawa",giverType="NPC",giverId=28382,ender="Elder Ko'nani",enderType="NPC",enderId=26194,poiX=2792,poiY=4694,wowhead="https://www.wowhead.com/wotlk/quest=12117",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$R, word just arrived from Moa'ki Harbor. Something very bad happened over there this morning!$B$BYou've been very helpful to us here. Would you consider using the boat from Unu'pe to travel to the great Dragonblight?$B$BBy the sound of things, Elder Ko'nani could certainly use your assistance.",logDesc="Travel to Moa'ki Harbor in the Dragonblight and speak with Elder Ko'nani.",choiceRewards={{id=37283,qty=1},{id=37566,qty=1},{id=37546,qty=1},{id=37319,qty=1}}} end
if not DB[12118] then DB[12118]={id=12118,zoneId=65,name="Travel to Moa'ki Harbor",level=72,minLevel=68,giver="Anuniaq",giverType="NPC",giverId=24810,ender="Elder Ko'nani",enderType="NPC",enderId=26194,poiX=744,poiY=-2885,wowhead="https://www.wowhead.com/wotlk/quest=12118",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$R, word just came in off the boat from Moa'ki Harbor. Something very bad happened over there this morning!$B$BYou've been very helpful to us here. Would you consider using the boat to travel to the great Dragonblight?$B$BBy the sound of things, Elder Ko'nani could certainly use your assistance.",logDesc="Travel to Moa'ki Harbor in the Dragonblight and speak with Elder Ko'nani.",choiceRewards={{id=37283,qty=1},{id=37566,qty=1},{id=37546,qty=1},{id=37319,qty=1}}} end
if not DB[12119] then DB[12119]={id=12119,zoneId=65,name="Gaining an Audience",level=72,minLevel=71,giver="Image of Archmage Modera",giverType="NPC",giverId=26673,ender="Tariolstrasz",enderType="NPC",enderId=26443,rewardNextId=12766,poiX=3501,poiY=2001,wowhead="https://www.wowhead.com/wotlk/quest=12119",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, you must travel as swiftly as you can to Wyrmrest Temple and present this letter to the steward, Tariolstrasz.$B$BThe temple sits in the center of the Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to get to it.$B$BI'm sure that when the steward reads your introduction, he'll see to it that you gain an audience with Queen Alexstrasza. We can only hope that we're not too late.$B$BThank you for all that you have done on our behalf. Safe journeys!",logDesc="Deliver your Letter of Introduction to Wyrmrest Temple to Tariolstrasz at Wyrmrest Temple."} end
if not DB[12120] then DB[12120]={id=12120,zoneId=394,name="Drak'aguul's Mallet",level=75,minLevel=73,giver="Kraz",giverType="NPC",giverId=26886,ender="Kraz",enderType="NPC",enderId=26886,rewardNextId=12121,poiX=4322,poiY=-4991,wowhead="https://www.wowhead.com/wotlk/quest=12120",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Corruption....$b$bEven before you delivered these jars, Kraz could sense it. This corruption fills the ancient Drakkari spirits with great angst and prevents them from entering the rest they seek.$b$bKraz will not lie, $c. Cleansing this place will require great sacrifice, but we shall speak of that at another time.$b$bThere is one among the living here who holds the key to its cleansing. Seek out Drak'aguul and return to Kraz with the mallet he carries.",logDesc="Kraz at Harkor's Camp wants you to slay Drak'aguul outside Drakil'jin Ruins and return with the Drakil'jin Mallet.",choiceRewards={{id=38730,qty=1},{id=39029,qty=1},{id=39057,qty=1},{id=39095,qty=1}}} end
if not DB[12121] then DB[12121]={id=12121,zoneId=394,name="See You on the Other Side",level=75,minLevel=73,giver="Kraz",giverType="NPC",giverId=26886,ender="Gan'jo",enderType="NPC",enderId=26924,rewardNextId=12137,poiX=4322,poiY=-4991,wowhead="https://www.wowhead.com/wotlk/quest=12121",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="These Drakkari have met you with nothing but savage hostility. You owe them nothing. Few indeed would carry out the task that Kraz asks of you today.$b$bTo cleanse this place and send the spirits to their eternal rest, you must join them in death.$b$bThere is one inside the crypt who awaits you - on the other side. He holds the knowledge we seek, $n.$b$bUse the mallet on the gongs. The spirit of he who corrupts this place will surely deliver you to the spirit world.$b$bKraz awaits your return.",logDesc="Kraz at Harkor's Camp wants you to use the Drakil'jin Mallet on the gongs outside Drakil'jin Ruins. Once you have been slain, you are to enter the ruins and speak with the spirit of Gan'jo while you are dead."} end
if not DB[12122] then DB[12122]={id=12122,zoneId=65,name="Gaining an Audience",level=72,minLevel=71,giver="Image of Archmage Aethas Sunreaver",giverType="NPC",giverId=26471,ender="Tariolstrasz",enderType="NPC",enderId=26443,rewardNextId=12767,poiX=3847,poiY=1493,wowhead="https://www.wowhead.com/wotlk/quest=12122",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$N, you must travel as swiftly as you can to Wyrmrest Temple and present this letter to the steward, Tariolstrasz.$B$BThe temple sits in the center of the Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to get to it.$B$BI'm sure that when the steward reads your introduction, he'll see to it that you gain an audience with Queen Alexstrasza. We can only hope that we're not too late.$B$BThank you for all that you have done on our behalf. Safe journeys!",logDesc="Deliver your Letter of Introduction to Wyrmrest Temple to Tariolstrasz at Wyrmrest Temple."} end
if not DB[12123] then DB[12123]={id=12123,zoneId=65,name="Informing the Queen",level=75,minLevel=71,giver="Tariolstrasz",giverType="NPC",giverId=26443,ender="3",enderType="NPC",enderId=26917,rewardNextId=12435,poiX=3549,poiY=379,wowhead="https://www.wowhead.com/wotlk/quest=12123",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<The dragon steward pulls your letter of introduction out of his sleeve.>$B$BYes... yes, I think that you are ready to see the queen now.$B$BWhen you are ready, speak to me again and I will see to it that one of these drakes delivers you safely to the top of the temple. You will need to present your letter in person to Queen Alexstrasza.",logDesc="Deliver your Letter of Introduction to Wyrmrest Temple to Alexstrasza the Life-Binder at Wyrmrest Temple."} end
if not DB[12124] then DB[12124]={id=12124,zoneId=65,name="Informing the Queen",level=75,minLevel=71,giver="Tariolstrasz",giverType="NPC",giverId=26443,ender="3",enderType="NPC",enderId=26917,rewardNextId=12435,poiX=3549,poiY=379,wowhead="https://www.wowhead.com/wotlk/quest=12124",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<The dragon steward pulls your letter of introduction out of his sleeve.>$B$BYes... yes, I think that you are ready to see the queen now.$B$BWhen you are ready, speak to me again and I will see to it that one of these drakes delivers you safely to the top of the temple. You will need to present your letter in person to Queen Alexstrasza.",logDesc="Deliver your Letter of Introduction to Wyrmrest Temple to Alexstrasza the Life-Binder at Wyrmrest Temple."} end
if not DB[12125] then DB[12125]={id=12125,zoneId=65,name="In Service of Blood",level=73,minLevel=71,giver="Koltira Deathweaver",giverType="NPC",giverId=26581,ender="Koltira Deathweaver",enderType="NPC",enderId=26581,poiX=3798,poiY=1601,wowhead="https://www.wowhead.com/wotlk/quest=12125",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The blood of innocents was once used to sate the thirst of the blade. Alas, such options are no longer available to me.$B$B<Koltira pauses to think.>$B$BWe must improvise. South of here, upon the high bluffs, is the tuskarr village of Indu'le. Having been recently overrun by the Blue Dragonflight's chaotic magic, the resident tuskarr of Indu'le have gone mad.$B$BTake this blood gem and use it on a deranged villager. If I cannot take the blood of innocents, I shall have the blood of the meek!",logDesc="Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Blood Gem on a Deranged Indu'le Villager and return to him with a Filled Blood Gem."} end
if not DB[12126] then DB[12126]={id=12126,zoneId=65,name="In Service of the Unholy",level=73,minLevel=71,giver="Koltira Deathweaver",giverType="NPC",giverId=26581,ender="Koltira Deathweaver",enderType="NPC",enderId=26581,poiX=3798,poiY=1601,wowhead="https://www.wowhead.com/wotlk/quest=12126",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The power of the unholy is coveted among my kind. It makes up the very fiber of our existence, granting death to those that dare make a mockery of it! Thankfully there is a font from which I may draw from in my time of need.$B$BTake this unholy gem and make your way to the Ruby Dragonshrine, east of here. It is there that you will find Duke Vallenhal, death knight of Arthas. Weaken his resolve in battle and unleash the power of the gem upon him. It will finish him off and steal his unholy energy!$B",logDesc="Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Unholy Gem on Duke Vallenhal and return to him with a Filled Unholy Gem."} end
if not DB[12127] then DB[12127]={id=12127,zoneId=65,name="In Service of Frost",level=73,minLevel=71,giver="Koltira Deathweaver",giverType="NPC",giverId=26581,ender="Koltira Deathweaver",enderType="NPC",enderId=26581,poiX=3798,poiY=1601,wowhead="https://www.wowhead.com/wotlk/quest=12127",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The biting cold protects the death knight while repelling his enemies. He that commands the power of frost can incite chaos and destruction!$B$BTake this frost gem and travel far across the open tundra of the Dragonblight until you come upon the Mirror of Dawn, east of Wyrmrest Temple. It is there that you are to battle the legions of ice revenants that dwell upon the lakes surface and take from them the essence of frost. Utilize the power of the gem when they are weak, $N!",logDesc="Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Frost Gem on Ice Revenants and return to him with a Filled Frost Gem."} end
if not DB[12128] then DB[12128]={id=12128,zoneId=394,name="Check Up on Raegar",level=75,minLevel=73,giver="Brugar Stoneshear",giverType="NPC",giverId=26226,ender="Raegar Breakbrow",enderType="NPC",enderId=26883,rewardNextId=12129,poiX=4552,poiY=-4250,wowhead="https://www.wowhead.com/wotlk/quest=12128",image="assets/images/quests/placeholder.png",xpDiff=1,desc="With all the excitement about the army trying to move through Thor Modan, I'd almost forgotten about Raegar's crew down at Prospector's Point.$B$BI sent Raegar and his assistants, along with a mountaineer friend, down to establish a small post near Dun Argol, at the southern end of the Eastwind Shore.$B$BThey were to investigate the iron dwarf presence in the southern hills, but I haven't received any reports yet. Could you check up on them if you're going down that way?",logDesc="Speak with Raegar Breakbrow at Prospector's Point."} end
if not DB[12129] then DB[12129]={id=12129,zoneId=394,name="The Perfect Plan",level=75,minLevel=73,giver="Raegar Breakbrow",giverType="NPC",giverId=26883,ender="Raegar Breakbrow",enderType="NPC",enderId=26883,rewardNextId=12130,poiX=3814,poiY=-5157,wowhead="https://www.wowhead.com/wotlk/quest=12129",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="The iron dwarves are making no secret of the fact that they're preparing for war. With their giants, golems, and lightning elementals, they'd have a technological advantage against the Westfall Brigade. If they don't find passage north in time, the irons could take them by surprise.$B$BWe've got to tie them up here, and I've got just the way to do it. Dun Argol is full of rune-smiths churning out war golems. They carry plans for specific pieces, so you'll need to find and assemble all the parts.",logDesc="Bring the completed War Golem Blueprint to Raegar Breakbrow at Prospector's Point."} end
if not DB[12130] then DB[12130]={id=12130,zoneId=394,name="Why Fabricate When You Can Appropriate?",level=75,minLevel=73,giver="Raegar Breakbrow",giverType="NPC",giverId=26883,ender="Raegar Breakbrow",enderType="NPC",enderId=26883,rewardNextId=12131,poiX=3814,poiY=-5157,wowhead="https://www.wowhead.com/wotlk/quest=12130",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="We've got the blueprints, but we can't do anything with them without parts! We don't have access to a foundry, much less materials, but there's a whole load of parts up in Dun Argol.$B$BYour job?$B$BGive them a new home.$B$BThey're likely to be scattered around any of the buildings where the iron rune-smiths are working, and I wouldn't blame the irons for being cranky when you try to filch their handiwork. The more parts you can bring, the better we can make this golem.",logDesc="Bring 8 War Golem Parts to Raegar Breakbrow at Prospector's Point."} end
if not DB[12131] then DB[12131]={id=12131,zoneId=394,name="We Have the Power",level=75,minLevel=73,giver="Raegar Breakbrow",giverType="NPC",giverId=26883,ender="Raegar Breakbrow",enderType="NPC",enderId=26883,rewardNextId=12138,poiX=3814,poiY=-5157,wowhead="https://www.wowhead.com/wotlk/quest=12131",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="We're almost there, but the war golem won't run without power cells. From the information I was able to collect in Dun Argol before we were discovered, both Rune-Smith Durar and Rune-Smith Kathorn each create one power cell.$B$BWe'll need one power cell from each of the rune-smiths before our golem will work.$B$BYou should be able to find each rune-smith in his workshop on the central level of Dun Argol.",logDesc="Bring Durar's Power Cell and Kathorn's Power Cell to Raegar Breakbrow at Prospector's Point."} end
if not DB[12132] then DB[12132]={id=12132,zoneId=65,name="The Power to Destroy",level=73,minLevel=71,giver="Koltira Deathweaver",giverType="NPC",giverId=26581,ender="Koltira Deathweaver",enderType="NPC",enderId=26581,rewardNextId=12136,poiX=3798,poiY=1601,wowhead="https://www.wowhead.com/wotlk/quest=12132",image="assets/images/quests/placeholder.png",xpDiff=5,desc="While you have done much for me, one task remains.$B$BBeside the world you know exists another world. It is from that world, the world of shadows, that my tormentors assault me. While I am powerless to face my own demons, you could end their reign of terror. You have the strength, I have seen it with my own eyes.$B$BEnter the world of shadows and face the demons that torment me!$B$BDo this and I will translate the tome, as promised.",logDesc="Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to enter the world of shadows and defeat 6 Shadowy Tormentors.$B$BSpeak to Koltira Deathweaver should you need to re-enter the world of shadows."} end
if not DB[12133] then DB[12133]={id=12133,zoneId=-22,name="Smash the Pumpkin",level=-1,minLevel=1,ender="Costumed Orphan Matron",enderType="NPC",enderId=24519,wowhead="https://www.wowhead.com/wotlk/quest=12133",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.$B$BSmashing the pumpking reveals an old, scorched holy symbol.",logDesc="Give the Scorched Holy Symbol to the Costumed Orphan Matron.",rewards={{id=34077,qty=1}}} end
if not DB[12134] then DB[12134]={id=12134,zoneId=394,name="Sasha's Hunt",level=75,minLevel=73,giver="Sasha",giverType="NPC",giverId=26935,ender="Sasha",enderType="NPC",enderId=26935,poiX=4073,poiY=-4130,wowhead="https://www.wowhead.com/wotlk/quest=12134",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="This thing... this curse... that's affecting Silverbrook and Solstice Village... it makes beasts out of people.$B$BMy father tried to warn them, but they all listened to the wolfcult instead.$B$BThey're too far gone now, it's time to put them down... for their own sake.",logDesc="Sasha wants you to kill 12 Solstice Hunters in Solstice Village.",choiceRewards={{id=39011,qty=1},{id=39010,qty=1},{id=38755,qty=1},{id=39110,qty=1}}} end
if not DB[12135] then DB[12135]={id=12135,zoneId=-22,name="\"Let the Fires Come!\"",level=-1,minLevel=1,giver="Costumed Orphan Matron",giverType="NPC",giverId=24519,ender="Costumed Orphan Matron",enderType="NPC",enderId=24519,poiX=-9430,poiY=56,wowhead="https://www.wowhead.com/wotlk/quest=12135",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You must help us!  The Headless Horseman will attack the village at any moment!  Fires will be everywhere!  The children aren't safe!$B$BPlease, $n, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!",logDesc="The Costumed Orphan Matron wants you to help put out all the village fires after the Headless Horseman lights them.  When they are out, speak again to the Costumed Orphan Matron.",rewards={{id=20557,qty=3},{id=34068,qty=1}}} end
if not DB[12136] then DB[12136]={id=12136,zoneId=65,name="The Translated Tome",level=73,minLevel=71,giver="Koltira Deathweaver",giverType="NPC",giverId=26581,ender="Captain Gort",enderType="NPC",enderId=26618,poiX=3798,poiY=1601,wowhead="https://www.wowhead.com/wotlk/quest=12136",image="assets/images/quests/placeholder.png",xpDiff=7,money=159000,desc="Here it is, $N. I have translated everything printed upon the pages of the tome. Inside it you will find a list of the names of Cult of the Damned members spanning the entire continent.$B$BTheir network of spies and operatives is impressive, to say the least.$B$BFarewell, friend. May the book serve you and your people well.",logDesc="Deliver the Translated Flesh-bound Tome to Captain Gort at Agmar's Hammer.",choiceRewards={{id=37958,qty=1},{id=38000,qty=1},{id=38043,qty=1},{id=38104,qty=1}}} end
if not DB[12137] then DB[12137]={id=12137,zoneId=394,name="Chill Out, Mon",level=75,minLevel=73,giver="Gan'jo",giverType="NPC",giverId=26924,ender="Kraz",enderType="NPC",enderId=26886,rewardNextId=12152,poiX=4835,poiY=-4754,wowhead="https://www.wowhead.com/wotlk/quest=12137",image="assets/images/quests/placeholder.png",xpDiff=6,desc="It be as the prophecies said, mon. A $r $c be comin' to set our spirits to rest. We been waitin' for a long time now!$b$bThe Drakkari have become a lost people, fierce and savage.$b$bBut here we suffer by no fault of our own, mon. This place need cleansin' and only the living can do it.$b$bSpeak to me when ya be ready to rejoin your body. Then take the snow from the chest near me here and put my bruddas to sleep.$b$bTake their remnants to your spirit guide. He be knowin' what to do next.",logDesc="Gan'jo wants you to collect the Snow of Eternal Slumber from his chest in the Drakil'jin Ruins.$b$bYou are to use the Snow on the Ancient Drakkari Spirits there and take their Drakkari Spirit Particles back to Kraz at Harkor's Camp."} end
if not DB[12138] then DB[12138]={id=12138,zoneId=394,name="... Or Maybe We Don't",level=75,minLevel=73,giver="Raegar Breakbrow",giverType="NPC",giverId=26883,ender="Raegar Breakbrow",enderType="NPC",enderId=26883,poiX=3814,poiY=-5157,wowhead="https://www.wowhead.com/wotlk/quest=12138",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="You'd think the guys making the power cells would've thought to power them up, but no, they've got to make it difficult for us.$B$BFine, we'll charge those cells the hard way. There's enough power in them to run the golem for a short time, but don't expect it to be any good in combat.$B$BYou see the lightning sentries that the irons have posted around the perimeter of Dun Argol? Bring the golem with you, take it close to them, and use the golem to absorb the power as the sentries die.",logDesc="Charge your War Golem with the energy from 10 Lightning Sentries and return to Raegar Breakbrow at Prospector's Point."} end
if not DB[12139] then DB[12139]={id=12139,zoneId=-22,name="\"Let the Fires Come!\"",level=-1,minLevel=1,giver="Masked Orphan Matron",giverType="NPC",giverId=23973,ender="Masked Orphan Matron",enderType="NPC",enderId=23973,poiX=9516,poiY=-6815,wowhead="https://www.wowhead.com/wotlk/quest=12139",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Headless Horseman will attack the village at any moment!  Fires will be everywhere!$B$B$n, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!",logDesc="The Masked Orphan Matron wants you to help put out all the village fires.  When they are out, speak again to the Masked Orphan Matron in town.",rewards={{id=20557,qty=3},{id=34068,qty=1}}} end
if not DB[12140] then DB[12140]={id=12140,zoneId=65,name="All Hail Roanauk!",level=73,minLevel=71,giver="Overlord Agmar",giverType="NPC",giverId=26379,ender="Overlord Agmar",enderType="NPC",enderId=26379,poiX=3842,poiY=1487,wowhead="https://www.wowhead.com/wotlk/quest=12140",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Like the tauren, Forsaken, trolls and blood elves, so too do the taunka need a leader born of their own blood. The one you saved from Icemist, Roanauk, will be this leader.$B$B<Overlord Agmar hands you a parchment.>$B$BI give to you something familiar - the blood oath of the Horde.$B$BTake the oath to Roanauk Icemist and initiate him into the Horde as leader of the taunka.$B$BLet us not keep him waiting.$B$B<Agmar nods.>$B",logDesc="Seek out Roanauk Icemist at Agmar's Hammer and initiate him as a member and leader of the Horde forces.$B$BReturn to Overlord Agmar with the Blood Oath of the Horde when you complete this task.$B",choiceRewards={{id=38293,qty=1},{id=38002,qty=1},{id=38106,qty=1},{id=37960,qty=1}}} end
if not DB[12141] then DB[12141]={id=12141,zoneId=3537,name="A Diplomatic Mission",level=71,minLevel=68,giver="Counselor Talbot",giverType="NPC",giverId=25301,ender="Karuk",enderType="NPC",enderId=25435,rewardNextId=11613,poiX=2107,poiY=5302,wowhead="https://www.wowhead.com/wotlk/quest=12141",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I see that you are very eager to help, $N.  You didn't come all the way to Northrend to stay holed up in a city!  I've just the task for you... something that'll take you far away from here.$B$BWe've long sought to gain the favor of the tuskarr native to Northrend.  Recently a young tuskarr came to us seeking help, something we couldn't offer at the time.$B$BNow that you're around, maybe you can lend him a hand.  Look for Karuk near the Riplash Strand, southwest of here, and see what you can do to help.  ",logDesc="Speak to Karuk at Riplash Strand, southwest of Valiance Keep."} end
if not DB[12142] then DB[12142]={id=12142,zoneId=65,name="Pest Control",level=73,minLevel=72,giver="Duane",giverType="NPC",giverId=26978,ender="Duane",enderType="NPC",enderId=26978,rewardNextId=12143,poiX=4568,poiY=14,wowhead="https://www.wowhead.com/wotlk/quest=12142",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="Ugh! One of those little snobold runts trashed our camp while we were busy with that last dragon. They've been plaguing us whenever we turn our backs... I've had enough!$B$BTo the south you'll find the snobolds hiding under the skirts of some of the local magnataur. Go slaughter them.$B$BIf the magnataur interfere on behalf of their slaves, kill them as well.",logDesc="Duane at the 7th Legion Front wants you to kill 10 Snowplain Snobolds and 3 Dragonblight Magnataur at the magnataur camps surrounding Wyrmrest."} end
if not DB[12143] then DB[12143]={id=12143,zoneId=65,name="Canyon Chase",level=73,minLevel=72,giver="Duane",giverType="NPC",giverId=26978,ender="Duane",enderType="NPC",enderId=26978,poiX=4568,poiY=14,wowhead="https://www.wowhead.com/wotlk/quest=12143",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="I can't believe this! Another band of those vermin just tried to take off with more of our supplies. They're scurrying off towards that north canyon, get after them and deal with whoever they're going to!",logDesc="Duane wants you to chase the snobolds down the canyon northeast of 7th Legion Front and deal with their leader.",choiceRewards={{id=37965,qty=1},{id=38007,qty=1},{id=38049,qty=1},{id=38111,qty=1}}} end
if not DB[12144] then DB[12144]={id=12144,zoneId=65,name="Pest Control",level=73,minLevel=72,giver="Kontokanis",giverType="NPC",giverId=26979,ender="Kontokanis",enderType="NPC",enderId=26979,rewardNextId=12145,poiX=4322,poiY=1009,wowhead="https://www.wowhead.com/wotlk/quest=12144",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="Oi, mon! One of dose little snobold runts trashed our camp during da last dragon attack. Dey've been houndin us wheneva we turn our backs and I've had enough. $b$bTo da east you'll find da snobolds hiding under da skirts of some of da local magnataur. Go slaughter dem. If da magnataur interfere on behalf of deir slaves, kill dem as well.",logDesc="Kontokanis at Dragon's Fall wants you to kill 10 Snowplain Snobolds and 3 Dragonblight Magnataur at the magnataur camps surrounding Wyrmrest."} end
if not DB[12145] then DB[12145]={id=12145,zoneId=65,name="Canyon Chase",level=73,minLevel=72,giver="Kontokanis",giverType="NPC",giverId=26979,ender="Kontokanis",enderType="NPC",enderId=26979,poiX=4322,poiY=1009,wowhead="https://www.wowhead.com/wotlk/quest=12145",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="I can't believe dis! Another band of dose vermin just tried ta take off with more of our supplies. Dey're scurrying down da canyon now, get after dem and deal with whoever dey're going to!",logDesc="Kontokanis wants you to chase the snobolds down the canyon south of Dragon's Fall and deal with their leader.",choiceRewards={{id=37965,qty=1},{id=38007,qty=1},{id=38049,qty=1},{id=38111,qty=1}}} end
if not DB[12146] then DB[12146]={id=12146,zoneId=65,name="Disturbing Implications",level=73,minLevel=72,ender="Aurastrasza",enderType="NPC",enderId=26983,rewardNextId=12148,wowhead="https://www.wowhead.com/wotlk/quest=12146",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur.$b$bTake the horn south down the Path of the Titans to Wyrmrest and seek out someone who might be interested in these threatening implications.",logDesc="Bring the Emblazoned Battle Horn to Wyrmrest and seek out someone who might be interested in assessing the potential threat."} end
if not DB[12147] then DB[12147]={id=12147,zoneId=65,name="Disturbing Implications",level=73,minLevel=72,ender="Aurastrasza",enderType="NPC",enderId=26983,rewardNextId=12148,wowhead="https://www.wowhead.com/wotlk/quest=12147",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur. $b$bTake the horn east across the Dragon Wastes to Wyrmrest and seek out someone who might be interested in these threatening implications.",logDesc="Bring the Emblazoned Battle Horn to Wyrmrest and seek out someone who might be interested in assessing the potential threat."} end
if not DB[12148] then DB[12148]={id=12148,zoneId=65,name="One of a Kind",level=73,minLevel=72,giver="Aurastrasza",giverType="NPC",giverId=26983,ender="Aurastrasza",enderType="NPC",enderId=26983,rewardNextId=12149,poiX=3511,poiY=261,wowhead="https://www.wowhead.com/wotlk/quest=12148",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="Such a strange seal to see among magnataur... it suggests an unusual amount of organization.$B$BMagnataur rarely put aside their aggressive natures to cooperate with each other.  I suspect they have their eyes set on raiding a large settlement.$b$bI very much doubt that this horn is unique, I need you to prove me wrong. In the canyon northwest of the Azure Dragonshrine you will find Bonesunder. Go challenge him and bring me back any evidence you find that might confirm my concerns.",logDesc="Find and kill Bonesunder in or near the canyon northwest of the Azure Dragonshrine. Bring any evidence you find back to Aurastrasza at Wyrmrest Temple."} end
if not DB[12149] then DB[12149]={id=12149,zoneId=65,name="Mighty Magnataur",level=73,minLevel=72,giver="Aurastrasza",giverType="NPC",giverId=26983,ender="Aurastrasza",enderType="NPC",enderId=26983,rewardNextId=12150,poiX=3511,poiY=261,wowhead="https://www.wowhead.com/wotlk/quest=12149",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="Magnataur are hideously violent creatures... this is the main reason we rarely see them come together in any real numbers without killing each other. A powerful leader has stepped up somewhere among them and we need to hunt him down if we are to stop this threat. $B$BI will start asking around. I need you to disrupt them as much as possible in the meantime.$B$BEast of here there are 3 torches erected. Near them, there are 3 dominant Magnataur - put them down to buy us some time to hunt down this leader.",logDesc="Hunt down and kill Bloodfeast, Iceshatter, and Drakegore east of Wyrmrest$B$BBloodfeast resides in the southeastern corner of the Dragon Wastes, just north of the Emerald Dragonshrine. Iceshatter patrols the northern edge of the Mirror of Dawn. Drakegore wanders at the bottom of the cliffs west of the Bronze Dragonshrine.$B$BReturn to Aurastrasza at Wyrmrest once the magnataur have been slain."} end
if not DB[12150] then DB[12150]={id=12150,zoneId=65,name="Reclusive Runemaster",level=74,minLevel=72,giver="Aurastrasza",giverType="NPC",giverId=26983,ender="Aurastrasza",enderType="NPC",enderId=26983,rewardNextId=12151,poiX=3511,poiY=261,wowhead="https://www.wowhead.com/wotlk/quest=12150",image="assets/images/quests/placeholder.png",xpDiff=6,money=112000,desc="Dregmar Runebrand is a magnataur runemaster... a rare breed. He's generally solitary, but has been known to associate with the more powerful and influential magnataur in Dragonblight for quite some time. He will know who this new leader is. $b$bIt is unlikely we will gain any aid with the increasing concerns with the Scourge and the blue flight, so I need you to procure the information from Dregmar by any means necessary.$B$BI was told he can be found amongst the cliffs overlooking the Mirror of the Dawn.",logDesc="Locate Dregmar Runebrand near his cave on the path to the cliffs overlooking the Mirror of the Dawn. Challenge him and uncover the name of the magnataur leader by any means necessary. Return to Aurastrasza at Wyrmrest once the information is obtained."} end
if not DB[12151] then DB[12151]={id=12151,zoneId=65,name="Wanton Warlord",level=74,minLevel=72,giver="Aurastrasza",giverType="NPC",giverId=26983,ender="Aurastrasza",enderType="NPC",enderId=26983,poiX=3511,poiY=261,wowhead="https://www.wowhead.com/wotlk/quest=12151",image="assets/images/quests/placeholder.png",xpDiff=7,money=168000,desc="There's no reason to suspect Dregmar's words are anything but true. Whether Grom'thar defeats you or is defeated by you, he can wash his hands of this.$b$bFollow his instructions... take the horn that you brought me earlier, travel to the ring of torches south of the Azure Dragonshrine, and blow it to announce your challenge.$B$BWhen Grom'thar the Thunderbringer arrives, kill him and bring me his head.",logDesc="Travel to the ring of torches south of the Azure Dragonshrine and blow the Emblazoned Battle Horn. Defeat Grom'thar the Thunderbringer and bring his head back to Aurastrasza at Wyrmrest.",choiceRewards={{id=38156,qty=1},{id=38157,qty=1},{id=38155,qty=1},{id=38154,qty=1},{id=38130,qty=1},{id=38224,qty=1}}} end
if not DB[12152] then DB[12152]={id=12152,zoneId=394,name="Jin'arrak's End",level=75,minLevel=73,giver="Kraz",giverType="NPC",giverId=26886,ender="Kraz",enderType="NPC",enderId=26886,poiX=4322,poiY=-4991,wowhead="https://www.wowhead.com/wotlk/quest=12152",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="It is good to see you back among the living. Many who travel the path of the dead do not return to speak of it.$b$bWhile you were away, a vision appeared to Kraz revealing what remains to be done.$b$bA sacred offering lies somewhere inside the crypt. Take this spirit dust fashioned from the remnants you collected and use it on the offering.$b$bThe infused offering will bring an end to the corrupted warlord and will release the many tormented souls.$b$bMay the spirits guide your actions, $n.",logDesc="Kraz at Harkor's Camp wants you to collect the Sacred Drakkari Offering from the Drakil'jin Ruins and use the Drakkari Spirit Dust on it. You must use the Infused Drakkari Offering at the gongs outside of Drakil'jin Ruins.",choiceRewards={{id=39114,qty=1},{id=39125,qty=1},{id=39127,qty=1},{id=39124,qty=1},{id=39113,qty=1},{id=39118,qty=1}}} end
if not DB[12153] then DB[12153]={id=12153,zoneId=394,name="The Iron Thane and His Anvil",level=75,minLevel=73,giver="Raegar Breakbrow",giverType="NPC",giverId=26883,ender="Raegar Breakbrow",enderType="NPC",enderId=26883,poiX=3814,poiY=-5157,wowhead="https://www.wowhead.com/wotlk/quest=12153",image="assets/images/quests/placeholder.png",xpDiff=6,money=118000,desc="Now that you've charged up your war golem, we're going to put all that energy to good use. Activate the golem inside Dun Argol to take control of it.$B$BOur  information about Dun Argol's leader, Iron Thane Furyhammer, suggests his bodyguard protects him from all harm.$B$BThat bodyguard is the construct he travels with, called The Anvil. Disable the construct, and his protection will disappear.$B$BThe thane stays in the building at the top of Dun Argol and supervises production from the bottom level.",logDesc="Using the abilities of your War Golem, defeat Iron Thane Furyhammer, then return to Raegar Breakbrow at Prospector's Point.",choiceRewards={{id=38711,qty=1},{id=39015,qty=1},{id=39044,qty=1},{id=39076,qty=1}}} end
if not DB[12154] then DB[12154]={id=12154,zoneId=394,name="Blackout",level=75,minLevel=73,giver="Raegar Breakbrow",giverType="NPC",giverId=26883,ender="Raegar Breakbrow",enderType="NPC",enderId=26883,poiX=3814,poiY=-5157,wowhead="https://www.wowhead.com/wotlk/quest=12154",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="The large hall at the top of Dun Argol houses the power source for the entire area. If you can destroy the power core, it will cripple Dun Argol for some time.$B$BNo power means no golems, no sentries, and no more lightning armaments.$B$BWhen we were sent up here, they told us these explosives were for excavation, but thanks to Iron Thane Furyhammer, the research has been scrapped. We may as well get some use out of them, though. They're the only thing we have on hand capable of destroying the power core.",logDesc="Use Raegar's Explosives to destroy the Runic Power Core at Dun Argol, then report to Raegar Breakbrow at Prospector's Point."} end
if not DB[12155] then DB[12155]={id=12155,zoneId=-22,name="Smash the Pumpkin",level=-1,minLevel=1,ender="Masked Orphan Matron",enderType="NPC",enderId=23973,wowhead="https://www.wowhead.com/wotlk/quest=12155",image="assets/images/quests/placeholder.png",xpDiff=5,desc="This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.$B$BSmashing the pumpking reveals an old, scorched holy symbol.",logDesc="Give the Scorched Holy Symbol to the Masked Orphan Matron.",rewards={{id=34077,qty=1}}} end
if not DB[12156] then DB[12156]={id=12156,zoneId=3537,name="DEPRECAED",level=74,minLevel=72,wowhead="https://www.wowhead.com/wotlk/quest=12156",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I was meant to set off for Silverbrook, northwest of here, about an hour ago.  My military escort appears to be running late.$B$BI'll be damned if this diplomatic mission gets sidetracked because some new recruit overslept.$B$BWe're negotiating a deal with the locals and timeliness is essential.  What do you say?  If you come with me, you'll be well compensated for your troubles.",logDesc="Escort the Alliance Envoy to the town of Silverbrook.  Report to Lieutenant Dumont at the Amberpine Lodge when you've completed this task."} end
if not DB[12157] then DB[12157]={id=12157,zoneId=65,name="The Lost Courier",level=72,minLevel=71,giver="Private Casey",giverType="NPC",giverId=26186,ender="Courier Lanson",enderType="NPC",enderId=27060,rewardNextId=12171,poiX=3114,poiY=3834,wowhead="https://www.wowhead.com/wotlk/quest=12157",image="assets/images/quests/placeholder.png",xpDiff=2,desc="We're lucky we made it this far, $N.  We were ambushed by Scourge as soon as we landed.$B$BOne of our men turned out to be a spy for the Cult of the Damned.  Thassarian appears to have more evidence of cultist infiltration.  Apparently it goes all the way to the top.$B$BI've sent one of my best couriers to our outpost in western Dragonblight, but he has not yet returned. I fear he may have fallen to the Scourge. Will you go to Dragonblight and search for him? Courier Lanson is his name.$B",logDesc="Speak to Courier Lanson at Star's Rest in Dragonblight."} end
if not DB[12158] then DB[12158]={id=12158,zoneId=394,name="Hollowstone Mine",level=75,minLevel=73,giver="Captain Gryan Stoutmantle",giverType="NPC",giverId=26212,ender="Petrov",enderType="NPC",enderId=26932,rewardNextId=12159,poiX=4607,poiY=-4230,wowhead="https://www.wowhead.com/wotlk/quest=12158",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I've been meaning to send some of our lads to check out Hollowstone Mine.  Haven't had a chance to yet -- we've had our hands full between the Horde on the west and the iron dwarves to the east.$B$BIf Dumont sent you, though, the least I can do is point you in the right direction.$B$BYou'll find the mine entrance to the northwest, not far from here.  See if you think operations there can be salvaged.  We sure could use the additional resources until our mine in Farshire is operational again. ",logDesc="Look for clues inside Hollowstone Mine northwest of the Westfall Brigade Encampment."} end
if not DB[12159] then DB[12159]={id=12159,zoneId=394,name="Souls at Unrest",level=75,minLevel=73,giver="Petrov",giverType="NPC",giverId=26932,ender="Petrov",enderType="NPC",enderId=26932,rewardNextId=12160,poiX=4698,poiY=-4005,wowhead="https://www.wowhead.com/wotlk/quest=12159",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="<Petrov looks deeply disturbed, breathing heavily and shifting his gaze nervously around the mine.>$B$BMy comrades... we must put their souls to rest!  I kill them and kill them but.. they just come back!$B$BI've had an idea for a while but I just don't have the heart to do it myself.$B$BMaybe you can do this for me?  Take this lantern and use its oil to burn their remains so they never get up again.$B$BI'll answer your questions later.  Help my friends first!",logDesc="Petrov at Hollowstone Mine wants you to use the Miner's Lantern to burn the corpses of 8 Hollowstone Miners.",choiceRewards={{id=38735,qty=1},{id=39034,qty=1},{id=39064,qty=1},{id=39099,qty=1}}} end
if not DB[12160] then DB[12160]={id=12160,zoneId=394,name="A Name from the Past",level=75,minLevel=73,giver="Petrov",giverType="NPC",giverId=26932,ender="Captain Gryan Stoutmantle",enderType="NPC",enderId=26212,poiX=4698,poiY=-4005,wowhead="https://www.wowhead.com/wotlk/quest=12160",image="assets/images/quests/placeholder.png",xpDiff=2,desc="It worked!  It worked!  My comrades can finally enjoy their well-earned rest...$B$BI'll stay here and finish the job.  We Hollowstone miners always finish the job -- we never give up!$B$BThat's why Arugal made an example of us.  We wouldn't fall in line, you see?  We wouldn't join his wolfcult!",logDesc="Return to Captain Gryan Stoutmantle at the Westfall Brigade Encampment."} end
if not DB[12161] then DB[12161]={id=12161,zoneId=394,name="Ruuna the Blind",level=75,minLevel=73,giver="Private Arun",giverType="NPC",giverId=27582,ender="Ruuna the Blind",enderType="NPC",enderId=27581,rewardNextId=12328,poiX=4601,poiY=-4218,wowhead="https://www.wowhead.com/wotlk/quest=12161",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Hey there.  I overheard what you were saying to the captain and I just want you to know...  things aren't that simple in Northrend.$B$BJust because someone's dead it doesn't mean they're out of the picture.$B$BSouthwest of here, near Vordrassil Pass, lives a blind woman who goes by the name Ruuna the Blind.  They say she speaks to the dead and has visions of the past and future.$B$BI haven't heard your whole story but it sounds like she'd be right up your alley.",logDesc="Speak to Ruuna the Blind at Ruuna's Camp near Vordrassil Pass."} end
if not DB[12162] then DB[12162]={id=12162,zoneId=394,name="Solstice Village",level=75,minLevel=72,wowhead="https://www.wowhead.com/wotlk/quest=12162",image="assets/images/quests/placeholder.png"} end
if not DB[12163] then DB[12163]={id=12163,zoneId=394,name="The Evil Below",level=75,minLevel=72,wowhead="https://www.wowhead.com/wotlk/quest=12163",image="assets/images/quests/placeholder.png"} end
if not DB[12164] then DB[12164]={id=12164,zoneId=394,name="Hour of the Worg",level=75,minLevel=73,giver="Sasha",giverType="NPC",giverId=26935,ender="Sasha",enderType="NPC",enderId=26935,poiX=4073,poiY=-4130,wowhead="https://www.wowhead.com/wotlk/quest=12164",image="assets/images/quests/placeholder.png",xpDiff=7,money=177000,desc="It is time, then, $N.  Arugal must be defeated.$B$BGet a couple of people you can trust and head for Bloodmoon Isle.  It's just off the coast, east of here.$B$BWe'll hit them fast.  Take out Arugal's lieutenants -- I'll catch up with you when it's time to take out the monster himself.",logDesc="Sasha at the White Pine Trading Post wants you to go to  Bloodmoon Isle and slay Selas, Varlam, Goremaw and the Shade of Arugal.",choiceRewards={{id=39170,qty=1},{id=39171,qty=1},{id=39169,qty=1},{id=39168,qty=1},{id=39172,qty=1}}} end
if not DB[12165] then DB[12165]={id=12165,zoneId=394,name="An Intriguing Plan",level=75,minLevel=73,giver="Tormak the Scarred",giverType="NPC",giverId=27221,ender="Prospector Rokar",enderType="NPC",enderId=27227,rewardNextId=12196,poiX=3854,poiY=-4537,wowhead="https://www.wowhead.com/wotlk/quest=12165",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Prospector Rokar has decided to help us. He's concocted a plan to use the iron dwarves' strength against them.$B$BI must admit, our new 'friend' is more insightful than I'd given him credit for. He's correct in that our numbers are too few for a direct attack.$B$BTravel to Dun Argol, in the snowy regions to the southeast, and capture all the parts of their war golem blueprints from the iron rune-smiths there. Bring the assembled blueprint to Rokar and we'll see if his plan has any merit.",logDesc="Bring the completed War Golem Blueprints to Prospector Rokar at Camp Oneqwah."} end
if not DB[12166] then DB[12166]={id=12166,zoneId=65,name="The Liquid Fire of Elune",level=72,minLevel=71,giver="Warden Jodi Moonsong",giverType="NPC",giverId=26973,ender="Warden Jodi Moonsong",enderType="NPC",enderId=26973,rewardNextId=12167,poiX=3494,poiY=1991,wowhead="https://www.wowhead.com/wotlk/quest=12166",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="$R will you assist me?$B$BThe Scourge have moved into Icemist to the north. Wherever they go, they spread their taint, and the creatures of the land suffer.$B$BTake this vial, which is filled with the liquid fire of Elune from the moonwell. Please, use the liquid to cleanse the corpses of the blighted wildlife that you find.",logDesc="Warden Jodi Moonsong at Stars' Rest has asked you to use the Liquid Fire of Elune to cleanse the corpses of 6 Blighted Elk and 6 Rabid Grizzlies."} end
if not DB[12167] then DB[12167]={id=12167,zoneId=65,name="Kill the Cultists",level=72,minLevel=71,giver="Warden Jodi Moonsong",giverType="NPC",giverId=26973,ender="Warden Jodi Moonsong",enderType="NPC",enderId=26973,poiX=3494,poiY=1991,wowhead="https://www.wowhead.com/wotlk/quest=12167",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="The Anub'ar cultists are indirectly responsible for the plaguing of the beasts, and we must put an end to it!$B$BThe fumes that emit from the cultists' suits seep into everything they come near, poisoning and corrupting their surroundings.$B$BYou must go north to Icemist Village and slay them. Bring back any of their suits that survive your assault and I will see to it that they are properly disposed of.",logDesc="Collect 5 Functional Cultist Suits for Warden Jodi Moonsong at Stars' Rest."} end
if not DB[12168] then DB[12168]={id=12168,zoneId=65,name="The Favor of Zangus",level=72,minLevel=71,ender="Warden Jodi Moonsong",enderType="NPC",enderId=26973,rewardNextId=12169,wowhead="https://www.wowhead.com/wotlk/quest=12168",image="assets/images/quests/placeholder.png",xpDiff=1,desc="An inscription on the back of the favor reads,$B$B\"To my favorite pupil,$B$BIf you continue to show promise, I will teach you wonders beyond your imaginings.$B$BIf you do not, I will have you destroyed!$B$BAs ever,$B$BHigh Cultist Zangus\"$B$BNo doubt the warden at Stars' Rest will want to see this.",logDesc="Deliver the Favor of Zangus to Warden Jodi Moonsong at Stars' Rest."} end
if not DB[12169] then DB[12169]={id=12169,zoneId=65,name="The High Cultist",level=72,minLevel=71,giver="Warden Jodi Moonsong",giverType="NPC",giverId=26973,ender="Warden Jodi Moonsong",enderType="NPC",enderId=26973,poiX=3494,poiY=1991,wowhead="https://www.wowhead.com/wotlk/quest=12169",image="assets/images/quests/placeholder.png",xpDiff=6,money=100000,desc="I have dreamed of Zangus before but without the context that you have discovered, I knew not what it meant. You have brought clarity to the vision that the goddess has bestowed upon me, and now I know that he can be found within the Pit of Narjun to the north.$B$BYou know your target, $N. If there's to be an end to the suffering of the land, the high cultist must die!",logDesc="Warden Jodi Moonsong at Stars' Rest has asked you to slay High Cultist Zangus.",choiceRewards={{id=37961,qty=1},{id=38003,qty=1},{id=38045,qty=1},{id=38107,qty=1}}} end
if not DB[12170] then DB[12170]={id=12170,zoneId=394,name="Blackriver Brawl",level=74,minLevel=73,giver="Raider Captain Kronn",giverType="NPC",giverId=27120,ender="Raider Captain Kronn",enderType="NPC",enderId=27120,poiX=3215,poiY=-2499,wowhead="https://www.wowhead.com/wotlk/quest=12170",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="The Venture Company abandoned operations shortly after we showed up.  Clearly they were afraid of what we were going to do to their greedy little hides.$B$BWith them gone, their logging camps are up for grabs.  Our war machine is a hungry beast... without renewing our supplies we won't make it to Icecrown.$B$BUnfortunately the Alliance seems to have the same idea and we must make sure we're the ones that prevail.  Head into the logging camp and help us fight the Alliance scum.",logDesc="Raider Captain Kronn wants you to slay 10 Alliance units or players at the Blackriver Logging Camp.",rewards={{id=37836,qty=10}}} end
if not DB[12171] then DB[12171]={id=12171,zoneId=65,name="Of Traitors and Treason",level=72,minLevel=71,giver="Courier Lanson",giverType="NPC",giverId=27060,ender="Palena Silvercloud",enderType="NPC",enderId=26881,rewardNextId=12174,poiX=3474,poiY=2010,wowhead="https://www.wowhead.com/wotlk/quest=12171",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of Dragonblight.$B$BIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.$B$BHurry, $N. Show the document to Palena Silvercloud here at Stars' Rest and explain the nature of your mission. She will put you on her fastest hippogryph to Wintergarde!",logDesc="Show the Alliance Missive to Palena Silvercloud at Stars' Rest."} end
if not DB[12172] then DB[12172]={id=12172,zoneId=-161,name="Attunement to Dalaran",level=73,minLevel=71,giver="Image of Archmage Modera",giverType="NPC",giverId=26673,ender="Image of Archmage Modera",enderType="NPC",enderId=26673,poiX=3501,poiY=2001,wowhead="https://www.wowhead.com/wotlk/quest=12172",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="Welcome, mage.$B$BBy now you must be wondering where Dalaran is and how to get there. I will help you.$B$BBut before I can teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you risk destroying yourself in the process.$B$BTake this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the west. Then you will be ready to learn the spell.",logDesc="The Image of Archmage Modera at Stars' Rest has asked you to become Attuned to the Ley Lines of Northrend."} end
if not DB[12173] then DB[12173]={id=12173,zoneId=-161,name="Attunement to Dalaran",level=73,minLevel=71,giver="Image of Archmage Aethas Sunreaver",giverType="NPC",giverId=26471,ender="Image of Archmage Aethas Sunreaver",enderType="NPC",enderId=26471,poiX=3847,poiY=1493,wowhead="https://www.wowhead.com/wotlk/quest=12173",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="Hello, mage.$B$BBy now you must be wondering where Dalaran is and how to get there. I can help you with this if you can survive a simple test.$B$BBefore I teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you will destroy yourself in the process!$B$BTake this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the southwest. Then you will be ready to learn what I have to teach.",logDesc="The Image of Archmage Aethas Sunreaver at Agmar's Hammer has asked you to become Attuned to the Ley Lines of Northrend."} end
if not DB[12174] then DB[12174]={id=12174,zoneId=65,name="High Commander Halford Wyrmbane",level=72,minLevel=71,giver="Palena Silvercloud",giverType="NPC",giverId=26881,ender="High Commander Halford Wyrmbane",enderType="NPC",enderId=27136,rewardNextId=12235,poiX=3506,poiY=1990,wowhead="https://www.wowhead.com/wotlk/quest=12174",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Palena hands the missive back to you.>$B$BSnowstorm will take you to Wintergarde, $N. I guarantee you that it will be the fastest flight you've ever taken. Go now!$B",logDesc="Deliver the Alliance Missive to High Commander Halford Wyrmbane at Wintergarde Keep in eastern Dragonblight. $B"} end
if not DB[12175] then DB[12175]={id=12175,zoneId=394,name="Gray Worg Hides",level=74,minLevel=73,giver="Hidetrader Jun'ik",giverType="NPC",giverId=27037,ender="Hidetrader Jun'ik",enderType="NPC",enderId=27037,rewardNextId=12176,poiX=3238,poiY=-2268,wowhead="https://www.wowhead.com/wotlk/quest=12175",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Let me tell you something, mon.  When you get put in charge of outfittin' the armies of the Horde, you go through a lot of hides!$B$BConqueror Krenna, the she-wolf runnin' this place, she gave me a tight deadline.  If I don't outfit her whole regiment by week's end she's gonna have me wrestling bears in the pit.$B$BHelp me out and I'll pay you top price.  I'll be needin' hides from graymist hunters.$B$BYou'll find them all around in pockets to the north, hunting stag.  Remember, mon.  Top price!",logDesc="Hidetrader Jun'ik in Conquest Hold wants you to get 3 Gray Worg Hides from Graymist Hunters in the woods to the north.",choiceRewards={{id=38734,qty=1},{id=39033,qty=1},{id=39060,qty=1},{id=39098,qty=1}}} end
if not DB[12176] then DB[12176]={id=12176,zoneId=394,name="A Minor Substitution",level=74,minLevel=73,giver="Hidetrader Jun'ik",giverType="NPC",giverId=27037,ender="Hidetrader Jun'ik",enderType="NPC",enderId=27037,rewardNextId=12177,poiX=3238,poiY=-2268,wowhead="https://www.wowhead.com/wotlk/quest=12176",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Krenna, she be wantin' worg hides for all the outfits.  There's not gonna be enough worg hides for her army, though.  Not now, not ever.$B$BThose worgs -- they be skinny, mon!  Here's what we're gonna do... if you can keep a secret that is.$B$BEast of Voldrune there be grizzly bears as fat as an ogre.  Those large hides -- those we can use!$B$BHurry, $g brother:sister;.  Krenna's not known for her patience.",logDesc="Hidetrader Jun'ik wants you to bring him 6 Grizzly Hides.",choiceRewards={{id=38735,qty=1},{id=39034,qty=1},{id=39064,qty=1},{id=39099,qty=1}}} end
if not DB[12177] then DB[12177]={id=12177,zoneId=394,name="Jun'ik's Coverup",level=74,minLevel=73,giver="Hidetrader Jun'ik",giverType="NPC",giverId=27037,ender="Hidetrader Jun'ik",enderType="NPC",enderId=27037,rewardNextId=12178,poiX=3238,poiY=-2268,wowhead="https://www.wowhead.com/wotlk/quest=12177",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ah, we have a small problem.  Grizzly hides... they be brown, mon!$B$BThink... think!$B$BI got it, mon!  Is like this: gray is black an' white all mixed up.  You get me some coal an' some flour, I'll grind it all up and dust the hides with it.  No one will know the better!$B$BBlacksmiths sell coal for smeltin' an' you can get flour from the provisioner. ",logDesc="Bring 1 piece of Coal and 5 Simple Flour to Hidetrader Jun'ik at Conquest Hold in Grizzly Hills."} end
if not DB[12178] then DB[12178]={id=12178,zoneId=394,name="Delivery to Krenna",level=74,minLevel=73,giver="Hidetrader Jun'ik",giverType="NPC",giverId=27037,ender="Conqueror Krenna",enderType="NPC",enderId=26860,rewardNextId=12427,poiX=3238,poiY=-2268,wowhead="https://www.wowhead.com/wotlk/quest=12178",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This is it, mon.  Let's take these hides to Krenna and see if they pass the test.$B$BLet's hope for both our sakes Krenna doesn't notice anything.",logDesc="Take the Bundle of Hides to Krenna in Conquest Hold."} end
if not DB[12179] then DB[12179]={id=12179,zoneId=-264,name="Specialization 1 [PH]",level=65,minLevel=61,wowhead="https://www.wowhead.com/wotlk/quest=12179",image="assets/images/quests/placeholder.png",xpDiff=5,money=33000,desc="DESCRIPTION: Complete this quest for Specialization 1.",logDesc="LOG: Complete this quest for Specialization 1."} end
if not DB[12180] then DB[12180]={id=12180,zoneId=394,name="The Captive Prospectors",level=75,minLevel=73,giver="Mountaineer Kilian",giverType="NPC",giverId=26885,ender="Mountaineer Kilian",enderType="NPC",enderId=26885,poiX=3821,poiY=-5152,wowhead="https://www.wowhead.com/wotlk/quest=12180",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Raegar sent a team of prospectors into Dun Argol to search for artifacts and information about the history of the settlement. Raegar's team never expected Dun Argol to be this heavily populated.$B$BThey're being held captive while the iron dwarves prepare for war. We haven't the men to charge in after them, and Raegar's too busy fantasizing about defeating the irons to be of much help.$B$BIt falls to you, $N. Any of the irons or their servants could be carrying the keys to the cages holding our men.",logDesc="Free Prospector Gann, Prospector Torgan, and Prospector Varana, then return to Mountaineer Kilian at Prospector's Point."} end
if not DB[12181] then DB[12181]={id=12181,zoneId=495,name="Give it a Name",level=72,minLevel=71,giver="Chief Plaguebringer Harris",giverType="NPC",giverId=24251,ender="Tobias Sarkhoff",enderType="NPC",enderId=24155,rewardNextId=12182,poiX=442,poiY=-4638,wowhead="https://www.wowhead.com/wotlk/quest=12181",image="assets/images/quests/placeholder.png",xpDiff=1,desc="My, my, how long has it been? How long have we been working on this damned plague? Finally, after an eternity of failure, we are blessed with perfection. This... It doesn't even have a proper name yet! This blight... That's it, BLIGHT! This blight will tear down the very fabric of life!$B$B<Harris hands you a vial.>$B$BNow, find the bat handler, Tobias, and show him the specimen. He'll get you on your way to Venomspite.$B",logDesc="Show the Blight Specimen to Tobias Sarkhoff at New Agamand.$B"} end
if not DB[12182] then DB[12182]={id=12182,zoneId=65,name="To Venomspite!",level=72,minLevel=71,giver="Tobias Sarkhoff",giverType="NPC",giverId=24155,ender="Chief Plaguebringer Middleton",enderType="NPC",enderId=27172,rewardNextId=12188,poiX=400,poiY=-4542,wowhead="https://www.wowhead.com/wotlk/quest=12182",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I got a special bat all lined up for you, buddy. Fastest and smoothest ride I've got. He'll take you right to Venomspite - in style.$B$BJust hand that vial over to Chief Plaguebringer Middleton once you land. ",logDesc="Deliver the Blight Specimen to Chief Plaguebringer Middleton at Venomspite in eastern Dragonblight."} end
if not DB[12183] then DB[12183]={id=12183,zoneId=394,name="Looking the Part",level=75,minLevel=73,giver="Mountaineer Kilian",giverType="NPC",giverId=26885,ender="Mountaineer Kilian",enderType="NPC",enderId=26885,rewardNextId=12184,poiX=3821,poiY=-5152,wowhead="https://www.wowhead.com/wotlk/quest=12183",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="If, as Prospector Varana said, only certain irons are permitted to communicate with this Loken, it'll probably be the overseers who have the privilege.$B$BWe have to get you in there to see what all this is about, but it won't be easy. The first step will be to get a proper uniform for you.$B$BThen, we'll worry about doing your makeup.$B$BFind one of the overseers at Dun Argol, kill him, and bring back his uniform. If you get blood on it, you'll have only yourself to blame.",logDesc="Bring an Overseer's Uniform to Mountaineer Kilian at Prospector's Point."} end
if not DB[12184] then DB[12184]={id=12184,zoneId=394,name="Cultivating an Image",level=75,minLevel=73,giver="Mountaineer Kilian",giverType="NPC",giverId=26885,ender="Mountaineer Kilian",enderType="NPC",enderId=26885,rewardNextId=12185,poiX=3821,poiY=-5152,wowhead="https://www.wowhead.com/wotlk/quest=12184",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Now that we've got the uniform, we've got to get enough information to complete your camouflage.$B$BRaegar brought along this camera to document the team's finds, but I have a different use in mind. I want you to take it with you to Dun Argol and use it to capture the images of iron dwarves.$B$BOf course, your models aren't going to be a cooperative lot, so you may have to, err... subdue them first. Bring back the camera and the images when you're done.",logDesc="Use Kilian's Camera to record the images of 8 Iron Dwarves in Dun Argol, then return to Mountaineer Kilian at Prospector's Point."} end
if not DB[12185] then DB[12185]={id=12185,zoneId=394,name="Put on Your Best Face for Loken",level=75,minLevel=73,giver="Mountaineer Kilian",giverType="NPC",giverId=26885,ender="Mountaineer Kilian",enderType="NPC",enderId=26885,poiX=3821,poiY=-5152,wowhead="https://www.wowhead.com/wotlk/quest=12185",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Using the images you've captured, I've created everything you need for your overseer disguise kit. You'll make a fine iron dwarf, if I do say so myself.$B$BTake the kit with you to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city.$B$BThere, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.",logDesc="Disguise yourself as an Iron Rune Overseer, intercept the message from Loken, then report to Mountaineer Kilian at Prospector's Point.",choiceRewards={{id=38713,qty=1},{id=39017,qty=1},{id=39046,qty=1},{id=39078,qty=1}}} end
if not DB[12186] then DB[12186]={id=12186,zoneId=0,name="FLAG: Winner",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=12186",image="assets/images/quests/placeholder.png"} end
if not DB[12187] then DB[12187]={id=12187,zoneId=0,name="FLAG: Participant",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=12187",image="assets/images/quests/placeholder.png"} end
if not DB[12188] then DB[12188]={id=12188,zoneId=65,name="The Forsaken Blight and You: How Not to Die",level=72,minLevel=71,giver="Chief Plaguebringer Middleton",giverType="NPC",giverId=27172,ender="Chief Plaguebringer Middleton",enderType="NPC",enderId=27172,rewardNextId=12200,poiX=3227,poiY=-729,wowhead="https://www.wowhead.com/wotlk/quest=12188",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The details behind the functionality of the blight are hardly important. All you need to know is that it does the job it was designed to do. I have managed to synthesize a strain of the blight that is inert.$B$B<Middleton uncorks a vial and inhales.>$B$BSee, my body is still, mostly, intact. Now mix this with a reactive agent and we'd all be turned to shapeless piles of goo.$B$BOn the beach south of here you will find pathetic specters of Alliance soldiers past. Slay them and bring me ectoplasmic residue.",logDesc="Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to bring him 10 Ectoplasmic Residue.",choiceRewards={{id=37963,qty=1},{id=38005,qty=1},{id=38047,qty=1},{id=38109,qty=1}}} end
if not DB[12189] then DB[12189]={id=12189,zoneId=65,name="Imbeciles Abound!",level=72,minLevel=71,giver="Doctor Sintar Malefious",giverType="NPC",giverId=26505,ender="Chief Plaguebringer Middleton",enderType="NPC",enderId=27172,rewardNextId=12188,poiX=3747,poiY=1603,wowhead="https://www.wowhead.com/wotlk/quest=12189",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The shipment from New Agamand was to arrive at Venomspite last week and then be delivered to me after some simple field tests. It is a Horde imperative - the last piece of the \"victory puzzle.\"$B$B<Sintar sighs.>$B$BIt is quite disheartening to know that you are surrounded by imbeciles and incompetent boobs!$B$BYou must travel to Venomspite, near the eastern border of Dragonblight. Find that buffoon, Middleton, and let him know that I am waiting on the package.",logDesc="Travel to Venomspite in Dragonblight and speak with Chief Plaguebringer Middleton.$B"} end
if not DB[12190] then DB[12190]={id=12190,zoneId=394,name="Say Hello to My Little Friend",level=74,minLevel=73,giver="Prigmon",giverType="NPC",giverId=26519,ender="Harkor",enderType="NPC",enderId=26884,poiX=3882,poiY=-1936,wowhead="https://www.wowhead.com/wotlk/quest=12190",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Harkor's gunna drop a gold brick when he sees these choice ingredients. All that be left is gettin' them to him.$b$bHe's camped out on the eastern coast near dem haunted ruins - Drakil'jin, dey be called.$b$bYou'll likely be makin' it there before I can finish up with these corpses... unless, ya think you'd rather try your hand at embalming?",logDesc="Prigmon wants you to bring Harkor's Ingredients to Harkor at Harkor's Camp."} end
if not DB[12191] then DB[12191]={id=12191,zoneId=-370,name="Chug and Chuck!",level=-1,minLevel=1,giver="Bizzle Quicklift",giverType="NPC",giverId=27216,ender="Bizzle Quicklift",enderType="NPC",enderId=27216,poiX=1197,poiY=-4355,wowhead="https://www.wowhead.com/wotlk/quest=12191",image="assets/images/quests/placeholder.png",desc="Those pesky Dark Irons are back!  We need to make sure that you can defend yourself if needed.  More importantly, we need to know that you can defend our property!$b$bS.T.O.U.T. here is ready for action, are you?  Drink from the Complimentary Brewfest Samplers then throw the mug at S.T.O.U.T.!  Hit the target 5 times then talk to me.",logDesc="Use the Complimentary Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Bizzle Quicklift.",rewards={{id=37829,qty=10}}} end
if not DB[12192] then DB[12192]={id=12192,zoneId=-370,name="This One Time, When I Was Drunk...",level=-1,minLevel=1,ender="Bizzle Quicklift",enderType="NPC",enderId=27216,wowhead="https://www.wowhead.com/wotlk/quest=12192",image="assets/images/quests/placeholder.png",desc="The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.$b$bHead over to Bizzle and explain your heroic triumph over the Dark Iron dwarves.",logDesc="Talk to Bizzle Quicklift in the Brewfest camp.",rewards={{id=37829,qty=10}}} end
if not DB[12193] then DB[12193]={id=12193,zoneId=-370,name="Say, There Wouldn't Happen to be a Souvenir This Year, Would There?",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=12193",image="assets/images/quests/placeholder.png",desc="Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.$b$bIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.",logDesc="Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.",rewards={{id=33016,qty=1}}} end
if not DB[12194] then DB[12194]={id=12194,zoneId=-370,name="Say, There Wouldn't Happen to be a Souvenir This Year, Would There?",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=12194",image="assets/images/quests/placeholder.png",desc="Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.$b$bTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.",logDesc="Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.",rewards={{id=33016,qty=1}}} end
if not DB[12195] then DB[12195]={id=12195,zoneId=394,name="The Unexpected 'Guest'",level=75,minLevel=73,giver="Tormak the Scarred",giverType="NPC",giverId=27221,ender="Tormak the Scarred",enderType="NPC",enderId=27221,rewardNextId=12165,poiX=3854,poiY=-4537,wowhead="https://www.wowhead.com/wotlk/quest=12195",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="A recent hunting expedition brought back more than just game.$B$BThey encountered a wounded dwarf fleeing the iron dwarf stronghold of Dun Argol. He may have information we can use to strike at our ancient enemy, but before he's of any use to us, we must bring down his fever.$B$BThe horns of the silvercoat stags, who roam the nearby forest, have long been used to make healing poultices. If you can bring enough of the horns to me, we'll see if the poultice can bring our 'guest' around.",logDesc="Bring 5 Mature Stag Horns to Tormak the Scarred at Camp Oneqwah."} end
if not DB[12196] then DB[12196]={id=12196,zoneId=394,name="From the Ground Up",level=75,minLevel=73,giver="Prospector Rokar",giverType="NPC",giverId=27227,ender="Prospector Rokar",enderType="NPC",enderId=27227,rewardNextId=12197,poiX=3863,poiY=-4528,wowhead="https://www.wowhead.com/wotlk/quest=12196",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="We don't have enough time for me to forge the parts myself, but the foundries over at Dun Argol, to the southeast, are working day and night to churn out golem parts.$B$BI think you should go back there and pick up enough of them for me to make a golem from this blueprint.$B$BThey're probably scattered around any of the buildings where the iron rune-smiths are working.$B$BPlease hurry, $N. That Tormak looks like he's just waiting for an excuse to carry out his threat!",logDesc="Bring 8 War Golem Parts to Prospector Rokar at Camp Oneqwah."} end
if not DB[12197] then DB[12197]={id=12197,zoneId=394,name="We Have the Power",level=75,minLevel=73,giver="Prospector Rokar",giverType="NPC",giverId=27227,ender="Prospector Rokar",enderType="NPC",enderId=27227,rewardNextId=12198,poiX=3863,poiY=-4528,wowhead="https://www.wowhead.com/wotlk/quest=12197",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Well, we've got the shell of a golem, but that's not good enough for Tormak. He doesn't realize that these things don't just come together and miraculously start working! We're going to need power cells to animate it.$B$BWhen I was in Dun Argol, I noticed that Rune-Smith Durar and Rune-Smith Kathorn were the ones who manufactured the cells. We'll need one from each to power our golem.$B$BYou should be able to find each rune-smith in his workshop on the central level of Dun Argol.",logDesc="Bring Durar's Power Cell and Kathorn's Power Cell to Prospector Rokar at Camp Oneqwah."} end
if not DB[12198] then DB[12198]={id=12198,zoneId=394,name="... Or Maybe We Don't",level=75,minLevel=73,giver="Prospector Rokar",giverType="NPC",giverId=27227,ender="Prospector Rokar",enderType="NPC",enderId=27227,rewardNextId=12199,poiX=3863,poiY=-4528,wowhead="https://www.wowhead.com/wotlk/quest=12198",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="The golem's cells have just enough power to run it at the lowest levels, but it can't power any of its combat systems.$B$BThe good news is that the perimeter of Dun Argol is patrolled by lightning sentries. We should be able to use their power to charge up the golem's weapon systems.$B$BBring the golem with you, take it close to them, it will absorb the power as the sentries die.",logDesc="Charge your War Golem with the energy from 10 Lightning Sentries and return to Prospector Rokar at Camp Oneqwah."} end
if not DB[12199] then DB[12199]={id=12199,zoneId=394,name="Bringing Down the Iron Thane",level=75,minLevel=73,giver="Prospector Rokar",giverType="NPC",giverId=27227,ender="Tormak the Scarred",enderType="NPC",enderId=27221,poiX=3863,poiY=-4528,wowhead="https://www.wowhead.com/wotlk/quest=12199",image="assets/images/quests/placeholder.png",xpDiff=6,money=118000,desc="Now that the golem is fully charged, it can be used against the leader at Dun Argol.$B$BWhen I observed Iron Thane Furyhammer, he was always guarded by a personal golem that shielded him from all harm.$B$BThat construct called The Anvil, can be disrupted, causing him to drop the shield. Use your golem's EMP ability to do just that. You'll be able to activate and take control of your golem inside Dun Argol.$B$BThe thane is in the main plant at the top and supervises production from the bottom level.",logDesc="Using the abilities of your War Golem, defeat Iron Thane Furyhammer, then return to Tormak the Scarred at Camp Oneqwah.",choiceRewards={{id=38711,qty=1},{id=39015,qty=1},{id=39044,qty=1},{id=39076,qty=1}}} end
if not DB[12200] then DB[12200]={id=12200,zoneId=65,name="Emerald Dragon Tears",level=72,minLevel=71,giver="Chief Plaguebringer Middleton",giverType="NPC",giverId=27172,ender="Chief Plaguebringer Middleton",enderType="NPC",enderId=27172,rewardNextId=12218,poiX=3227,poiY=-729,wowhead="https://www.wowhead.com/wotlk/quest=12200",image="assets/images/quests/placeholder.png",xpDiff=5,desc="With an inert specimen of the blight compound complete and the activating agent in hand there only remains a need for a suitable shell to house the components.$B$BSouthwest of here, on the shores of central Dragonblight, is where you will find the Emerald Dragonshrine. Within the shrine you will find the hardened remnants of a green dragon's tear drop. I don't know the whole story, but apparently they cry a lot right before they die. Go figure.$B$BGo to the Emerald Dragonshrine and gather tears.",logDesc="Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to collect 8 Emerald Dragon Tears."} end
if not DB[12201] then DB[12201]={id=12201,zoneId=394,name="The Overseer's Shadow",level=75,minLevel=73,giver="Scout Vor'takh",giverType="NPC",giverId=26666,ender="Scout Vor'takh",enderType="NPC",enderId=26666,rewardNextId=12202,poiX=3848,poiY=-4532,wowhead="https://www.wowhead.com/wotlk/quest=12201",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="It sounds like this Loken is the mastermind behind the sudden preparations for war on the part of the iron dwarves.$B$BOnly the highest ranking irons are likely to have access to him, so we'll have to make you into an overseer to find out what's going on in there.$B$BI have a plan, for that, but we'll need some supplies.$B$BFind one of the iron rune overseers at Dun Argol, to the southeast, kill him, and bring back his uniform. ",logDesc="Bring an Overseer's Uniform to Scout Vor'takh at Camp Oneqwah."} end
if not DB[12202] then DB[12202]={id=12202,zoneId=394,name="Cultivating an Image",level=75,minLevel=73,giver="Scout Vor'takh",giverType="NPC",giverId=26666,ender="Scout Vor'takh",enderType="NPC",enderId=26666,rewardNextId=12203,poiX=3848,poiY=-4532,wowhead="https://www.wowhead.com/wotlk/quest=12202",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Now we have to finish the job of making you as repulsive as those iron dwarves.$B$BThe best way to do that is to base your disguise on the ugly mugs of real iron dwarves.$B$BWhen Tormak's hunting party discovered that wayward prospector, they took the camera he carried. Now, I suppose, we'll get the chance to use it.$B$BTake it with you to Dun Argol, kill some iron dwarves, and record their likenesses in this device. Bring it back once you have enough examples.",logDesc="Use Rokar's Camera to record the images of 8 Iron Dwarves in Dun Argol, then return to Scout Vor'takh at Camp Oneqwah."} end
if not DB[12203] then DB[12203]={id=12203,zoneId=394,name="Loken's Orders",level=75,minLevel=73,giver="Scout Vor'takh",giverType="NPC",giverId=26666,ender="Scout Vor'takh",enderType="NPC",enderId=26666,poiX=3848,poiY=-4532,wowhead="https://www.wowhead.com/wotlk/quest=12203",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="I've created everything else you'll need for your overseer disguise kit. Try not to retch when you put it on. I took pains to make it as true to reality as possible.$B$BTake the kit with you southeast to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city.$B$BThere, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.",logDesc="Disguise yourself as an Iron Rune Overseer, intercept the message from Loken, then report to Scout Vor'takh at Camp Oneqwah."} end
if not DB[12204] then DB[12204]={id=12204,zoneId=394,name="In the Name of Loken",level=75,minLevel=73,giver="Scout Vor'takh",giverType="NPC",giverId=26666,ender="Scout Vor'takh",enderType="NPC",enderId=26666,rewardNextId=12201,poiX=3848,poiY=-4532,wowhead="https://www.wowhead.com/wotlk/quest=12204",image="assets/images/quests/placeholder.png",xpDiff=4,money=46000,desc="The iron dwarves stand as one of the fiercest and most coordinated foes in Northrend. Wherever we have traveled, they have battled us with the name of Loken on their lips.$B$BWe must learn who this Loken is and what he seeks. The locals may be of help.$B$BTo the northeast, at the Redwood Trading Post, a human named Hugh Glass peddles his wares. Further east, at the Ruins of Tethys, you'll find a stone giant named Gavrock. Ask them about this Loken. They've got to know something of use.",logDesc="Speak with Hugh Glass and Gavrock about Loken, then report your findings to Scout Vor'takh at Camp Oneqeah."} end
if not DB[12205] then DB[12205]={id=12205,zoneId=65,name="Wanted: The Scarlet Onslaught",level=72,minLevel=71,ender="High Executor Wroth",enderType="NPC",enderId=27243,wowhead="https://www.wowhead.com/wotlk/quest=12205",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="By order of High Executor Wroth all members of the illegal organization known as the Scarlet Onslaught are to be put to death immediately.$B$BNo quarter is to be offered, and those proceeding to action upon this decree should be aware that any who are captured by the humans will be left to die, or worse!$B$BIn the High Executor's words, \"Paint the snow red with their blood!\"",logDesc="Kill 20 members of the Scarlet Onslaught and report to High Executor Wroth at Venomspite."} end
if not DB[12206] then DB[12206]={id=12206,zoneId=65,name="Blighted Last Rites",level=72,minLevel=71,giver="Apothecary Vicky Levine",giverType="NPC",giverId=27248,ender="Apothecary Vicky Levine",enderType="NPC",enderId=27248,rewardNextId=12211,poiX=3222,poiY=-691,wowhead="https://www.wowhead.com/wotlk/quest=12206",image="assets/images/quests/placeholder.png",xpDiff=1,money=5000,desc="Have you read the wanted poster? What is the high executor thinking?!$B$B<Vicky looks around and continues in hushed tones.>$B$BWe can't very well have those Scarlet Onslaught idiots being raised by their priests, or worse, rising as the Scourge, now can we?$B$BNo, I'm in total agreement with you, we have to do something about the corpses.$B$BI have just the thing. Take this blight that we just created and test it on the prisoner in the cage right here.$B$BNo muss, no fuss, no returning enemies.",logDesc="Apothecary Vicky Levine at Venomspite has asked you to test the Flask of Blight upon the Scarlet Onslaught Prisoner."} end
if not DB[12207] then DB[12207]={id=12207,zoneId=394,name="Vordrassil's Fall",level=74,minLevel=72,giver="Windseer Grayhorn",giverType="NPC",giverId=27262,ender="Windseer Grayhorn",enderType="NPC",enderId=27262,poiX=3317,poiY=-2292,wowhead="https://www.wowhead.com/wotlk/quest=12207",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Long ago, powerful druids planted a tree to the northeast of here.$B$BIt was called Vordrassil and it was to be a world tree.  It is not known why, but after the tree was fully grown, the druids decided it needed to be destroyed.$B$BEver since we arrived here, the earth has spoken to me, $N.  Its cries of pain come from the places where Vordrassil's remains fell on the ground.$B$BCorrupting ooze roams those places.  Bring me samples of it so we may begin to heal the land.",logDesc="Windseer Grayhorn in Conquest Hold wants you to go to Vordrassil's Limb, Vordrassil's Heart or Vordrassil's Tears and obtain 6 Slime Samples from the Entropic Oozes.",choiceRewards={{id=38719,qty=1},{id=39023,qty=1},{id=39052,qty=1},{id=39090,qty=1}}} end
if not DB[12208] then DB[12208]={id=12208,zoneId=394,name="Good Troll Hunting",level=74,minLevel=73,giver="Sergeant Thurkin",giverType="NPC",giverId=27266,ender="Samir",enderType="NPC",enderId=26424,rewardNextId=11984,poiX=3251,poiY=-2276,wowhead="https://www.wowhead.com/wotlk/quest=12208",image="assets/images/quests/placeholder.png",xpDiff=2,money=14400,desc="Good for nothing wretches!$b$bThey could have had it easy. We extended our hand in peace. All they had to do was give us passage through Drak'Tharon and we'd have let them be.$b$bBut no, the prideful little ice trolls decided that they wanted it rough. Now they'll be destroyed and we'll pass through their precious keep to Zul'Drak anyway.$b$bWe've contracted a gang to deliver us captured trolls. Talk to Samir if you want in on the action. You can find him to the northwest of here, due south of Zeb'Halek.",logDesc="Sergeant Thurkin told you to speak to Samir at Granite Springs."} end
if not DB[12209] then DB[12209]={id=12209,zoneId=65,name="Materiel Plunder",level=72,minLevel=71,giver="Quartermaster Bartlett",giverType="NPC",giverId=27267,ender="Quartermaster Bartlett",enderType="NPC",enderId=27267,poiX=3209,poiY=-634,wowhead="https://www.wowhead.com/wotlk/quest=12209",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Ah good, new meat. Do you wish to prove yourself, new meat?$B$BThe Scarlet Onslaught, the most zealous and racist of the Scarlet Crusade, are in our backyard to the south. If we're going to fight them, we'll need more armor and weapons than I can make in such a short time.$B$BWhy don't we take theirs?$B$BMore to the point, why don't YOU take theirs?",logDesc="Quartermaster Bartlett at Venomspite has asked you to steal 8 Scarlet Onslaught Armor and 8 Scarlet Onslaught Weapons."} end
if not DB[12210] then DB[12210]={id=12210,zoneId=394,name="Troll Season!",level=73,minLevel=73,giver="Lieutenant Dumont",giverType="NPC",giverId=26875,ender="Samir",enderType="NPC",enderId=26424,rewardNextId=11984,poiX=3411,poiY=-2782,wowhead="https://www.wowhead.com/wotlk/quest=12210",image="assets/images/quests/placeholder.png",xpDiff=4,money=41000,desc="You, $r! No sense standing around here when there's work to be done!$b$bDrak'Theron Keep is the most direct route to Zul'Drak. We MUST capture it to ensure safe passage for the Alliance. But until we get the numbers to make an assault, we'll have to content ourselves in thinning out the ice trolls and collecting intel.$b$bTo that end, we've conscripted a gang of thugs to capture and deliver live trolls for interrogation. Travel northwest and speak with Samir at Granite Springs. He'll direct you further.",logDesc="Lieutenant Dumont at Amberpine Lodge wants you to speak to Samir at Granite Springs."} end
if not DB[12211] then DB[12211]={id=12211,zoneId=65,name="Let Them Not Rise!",level=72,minLevel=71,giver="Apothecary Vicky Levine",giverType="NPC",giverId=27248,ender="Apothecary Vicky Levine",enderType="NPC",enderId=27248,poiX=3222,poiY=-691,wowhead="https://www.wowhead.com/wotlk/quest=12211",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I don't understand it. The blight should have worked!$B$BNo sense worrying about it now.$B$B<The apothecary seems relieved for some reason.>$B$BThough it doesn't work on the Onslaught for some strange reason, we still need to keep their priests from raising them.$B$BI have another idea, one that their corpses shouldn't have any protection from.$B$B$N, take a container of my rats and unleash them upon any Onslaught corpses you come across at New Hearthglen. I starve the vermin, so they should be voracious!",logDesc="Apothecary Vicky Levine at Venomspite has asked you to use her Container of Rats to pick clean the corpses of 15 Scarlet Onslaught members at New Hearthglen.",choiceRewards={{id=37971,qty=1},{id=38014,qty=1},{id=38057,qty=1},{id=38118,qty=1}}} end
if not DB[12212] then DB[12212]={id=12212,zoneId=394,name="Replenishing the Storehouse",level=74,minLevel=73,giver="Master Woodsman Anderhol",giverType="NPC",giverId=27277,ender="Master Woodsman Anderhol",enderType="NPC",enderId=27277,rewardNextId=12216,poiX=3418,poiY=-2796,wowhead="https://www.wowhead.com/wotlk/quest=12212",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="G'day, $c.$b$bThe good lieutenant here says that there's been a Horde raid on our storehouse that's left our food supply dangerously low.$b$bNo doubt we'll make those cretins pay, but first we need to focus our attention on restocking. My men are doing all they can, but we're going to need every able body to contribute if we're to avert a crisis.$b$bYou should have no trouble harvesting venison from the local stag in these parts. Happy hunting!",logDesc="Master Woodsman Anderhol at Amberpine Lodge wants you to kill Tallhorn Stag and collect 8 Succulent Venison."} end
if not DB[12213] then DB[12213]={id=12213,zoneId=394,name="The Darkness Beneath",level=74,minLevel=72,giver="Windseer Grayhorn",giverType="NPC",giverId=27262,ender="Windseer Grayhorn",enderType="NPC",enderId=27262,poiX=3317,poiY=-2292,wowhead="https://www.wowhead.com/wotlk/quest=12213",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Something... dark... happened to the tree Vordrassil.  After the druids decided to destroy it, its hollow remains grew roots deep into the ground.$B$BI want you to go to the three locations to the northeast where the tree's trunk shattered and go as far beneath the ground as you can.$B$BUse this orb once you get there to get an imprint of the energy surrounding the area.  This might shed some light on what happened to Vordrassil and why it failed to become a world tree.",logDesc="Windseer Grayhorn in Conquest Hold wants you to go to Vordrassil's Heart, Vordrassil's Tears and Vordrassil's Limb and use the Geomancer's Orb in the depths beneath the surface."} end
if not DB[12214] then DB[12214]={id=12214,zoneId=65,name="Fresh Remounts",level=72,minLevel=71,giver="Hansel Bauer",giverType="NPC",giverId=27028,ender="Hansel Bauer",enderType="NPC",enderId=27028,poiX=3261,poiY=-631,wowhead="https://www.wowhead.com/wotlk/quest=12214",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Hello. I am Hansel. Pleased to meet you, $g sir : ma'am;.$B$BThe high executor came to me and said, 'Hansel, I want you to get us new mounts.'$B$BWhere does he think dreadsteeds come from? The ground?$B$B<whispering> Actually, they do if you can find a horse graveyard.$B$BBut we don't have one of those, so what we need you to do is go south to New Hearthglen, kill the knights, take their riding crops, and steal their warhorses.$B$BRide the horse back to me here and hand over the reins, if you would.",logDesc="Hansel Bauer at Venomspite has asked you to steal 3 Onslaught Warhorses and deliver them to him, handing over the reins when you do so."} end
if not DB[12215] then DB[12215]={id=12215,zoneId=394,name="Them or Us!",level=74,minLevel=73,giver="Master Woodsman Anderhol",giverType="NPC",giverId=27277,ender="Master Woodsman Anderhol",enderType="NPC",enderId=27277,rewardNextId=12217,poiX=3418,poiY=-2796,wowhead="https://www.wowhead.com/wotlk/quest=12215",image="assets/images/quests/placeholder.png",xpDiff=4,money=44000,desc="As if we didn't have enough to concern ourselves with....$b$bWith the present food crisis, we find ourselves competing for food with the local worgs. The situation is becoming more dire, and I fear that if we don't address the issue immediately we'll soon find ourselves with nothing to hunt.$b$bScour the forest, $r. Kill any graymist you find. Recent reports have sighted a concentration of them on the other side of the river west of here.",logDesc="Anderhol at Amberpine Lodge wants you to find and kill 6 Graymist Hunters in Grizzly Hills."} end
if not DB[12216] then DB[12216]={id=12216,zoneId=394,name="Take Their Rear!",level=74,minLevel=73,giver="Master Woodsman Anderhol",giverType="NPC",giverId=27277,ender="Master Woodsman Anderhol",enderType="NPC",enderId=27277,poiX=3418,poiY=-2796,wowhead="https://www.wowhead.com/wotlk/quest=12216",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="We've all been working hard and it's beginning to pay off, but we're still far from our goal. We need much more meat than we have and it's growing clear that the local stag population won't be enough by itself.$b$bI'm afraid we need you to turn your attention to more dangerous prey - the grizzlies that give this region its name. They're plentiful, and they're well fed from the abundant fish that swim in these streams.$b$bBe safe, $c!",logDesc="Anderhol at Amberpine Lodge wants you to collect 8 Grizzly Flanks from the Grizzly Bears in Grizzly Hills."} end
if not DB[12217] then DB[12217]={id=12217,zoneId=394,name="Eagle Eyes",level=74,minLevel=73,giver="Master Woodsman Anderhol",giverType="NPC",giverId=27277,ender="Master Woodsman Anderhol",enderType="NPC",enderId=27277,poiX=3418,poiY=-2796,wowhead="https://www.wowhead.com/wotlk/quest=12217",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Well, $n, we've determined how the Horde was able to locate our hidden stores of food.$b$bIt turns out that they were binding their sight to the unsuspecting eagles that soar above the trees here. Using eagle vision, they were able to effectively spy on our every action.$b$bBy order of the lieutenant, we've got to hunt down these majestic birds in order to thwart our enemy.",logDesc="Anderhol in Amberpine Lodge wants you to kill 5 Imperial Eagles and then report back to him."} end
if not DB[12218] then DB[12218]={id=12218,zoneId=65,name="Spread the Good Word",level=72,minLevel=71,giver="Chief Plaguebringer Middleton",giverType="NPC",giverId=27172,ender="Chief Plaguebringer Middleton",enderType="NPC",enderId=27172,rewardNextId=12221,poiX=3227,poiY=-729,wowhead="https://www.wowhead.com/wotlk/quest=12218",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Before I can ship you off to Doctor Malefious with the good news, you will have to run a simple field test of the blight with the modifications I have made.$B$BThe hungering dead stream out from what remains of Old Wintergarde. Commandeer a vehicle from the east gate and drive it northeast through Vengeance Pass until you reach the twin towers at the southeastern edge of Wintergarde. Drop the blight bomb on the undead that cover the area. Report back to me with the results!",logDesc="Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to use the Forsaken Blight Spreader's Blight Bomb to destroy 30 Hungering Dead on the outskirts of the Carrion Fields."} end
if not DB[12219] then DB[12219]={id=12219,zoneId=394,name="The Failed World Tree",level=74,minLevel=73,giver="Hierophant Thayreen",giverType="NPC",giverId=27295,ender="Hierophant Thayreen",enderType="NPC",enderId=27295,poiX=3435,poiY=-2746,wowhead="https://www.wowhead.com/wotlk/quest=12219",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My ancestors once planted a tree in the middle of the Grizzly Hills.$B$BIt was called Vordrassil and it was to become a world tree.$B$BFor reasons long forgotten, after the tree was fully grown, they decided it needed to be destroyed.  Its giant trunk splintered at three locations in the area to the north.$B$BWhere the tree touched the ground, foul ooze began to crawl the earth.  Bring me slime samples so I can begin my work and the earth can be healed.",logDesc="Hierophant Thayreen at Amberpine Lodge wants you to go to Vordrassil's Limb, Vordrassil's Heart or Vordrassil's Tears and obtain 6 Slime Samples from the Entropic Oozes.",choiceRewards={{id=38719,qty=1},{id=39023,qty=1},{id=39052,qty=1},{id=39090,qty=1}}} end
if not DB[12220] then DB[12220]={id=12220,zoneId=394,name="A Dark Influence",level=74,minLevel=73,giver="Hierophant Thayreen",giverType="NPC",giverId=27295,ender="Hierophant Thayreen",enderType="NPC",enderId=27295,poiX=3435,poiY=-2746,wowhead="https://www.wowhead.com/wotlk/quest=12220",image="assets/images/quests/placeholder.png",xpDiff=5,desc="When the tree Vordrassil fell, its hollow remains grew roots deep into the ground.$B$BI want you to go north of here to the three locations where the trunk shattered and go as far beneath the ground as you can.  You'll find them west of Grizzlemaw.$B$BUse this orb once you get there to get an imprint of the energy surrounding the area.  If we're to heal the land, we must first find out what caused Vordrassil to fail as a world tree all those years ago.",logDesc="Hierophant Thayreen at Amberpine Lodge wants you to go to Vordrassil's Heart, Vordrassil's Tears and Vordrassil's Limb and use the Geomancer's Orb in the depths beneath the surface."} end
if not DB[12221] then DB[12221]={id=12221,zoneId=65,name="The Forsaken Blight",level=72,minLevel=71,giver="Chief Plaguebringer Middleton",giverType="NPC",giverId=27172,ender="Doctor Sintar Malefious",enderType="NPC",enderId=26505,poiX=3227,poiY=-729,wowhead="https://www.wowhead.com/wotlk/quest=12221",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I have prepared a package that must be delivered to Doctor Sintar Malefious at Agmar's Hammer. The contents of the package include the final blight specimen along with instructions on preparation and samples of the reactive agent.$B$BYou will find Agmar's Hammer in western Dragonblight. Just look for the black, jagged metal orc buildings - that will be Agmar's Hammer.$B",logDesc="Deliver The Forsaken Blight to Doctor Sintar Malefious at Agmar's Hammer.",choiceRewards={{id=38178,qty=1},{id=38177,qty=1},{id=38135,qty=1},{id=38295,qty=1},{id=38176,qty=1},{id=38134,qty=1}}} end
if not DB[12222] then DB[12222]={id=12222,zoneId=394,name="Secrets of the Flamebinders",level=74,minLevel=73,giver="Woodsman Drake",giverType="NPC",giverId=27391,ender="Woodsman Drake",enderType="NPC",enderId=27391,rewardNextId=12255,poiX=3419,poiY=-2812,wowhead="https://www.wowhead.com/wotlk/quest=12222",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Even as we attempt to fight off the Horde, the Dragonflayer tribe musters in their village of Voldrune, near the coast to the south.$B$BThe most powerful warriors in the village are granted flame-imbued talismans that give them the ability to control powerful, savage proto-drakes. If we can gain control of one of these drakes, perhaps we can use it to neutralize the threat posed by Voldrune.$B$BThe Dragonflayer flamebinders create the talismans and imbue them with power. Kill them and take the talismans.",logDesc="Bring 3 Flame-Imbued Talismans to Woodsman Drake at Amberpine Lodge."} end
if not DB[12223] then DB[12223]={id=12223,zoneId=394,name="Thinning the Ranks",level=74,minLevel=73,giver="Woodsman Drake",giverType="NPC",giverId=27391,ender="Woodsman Drake",enderType="NPC",enderId=27391,rewardNextId=12255,poiX=3419,poiY=-2812,wowhead="https://www.wowhead.com/wotlk/quest=12223",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="There's a flurry of activity down in Voldrune village to the south. Thane Torvald Eriksson and his huscarls are preparing for war. With most of our men in the field dealing with the Horde's treachery, Amberpine will be vulnerable.$B$BTravel to Voldrune, which is near the southern coast, and show those Dragonflayers we're no soft target.$B$BSlay as many of the huscarls as you can find. Make them think twice about taking advantage of our conflict with the Horde.",logDesc="Kill 12 Dragonflayer Huscarls and return to Woodsman Drake at Amberpine Lodge."} end
if not DB[12224] then DB[12224]={id=12224,zoneId=65,name="The Kor'kron Vanguard!",level=73,minLevel=71,giver="Overlord Agmar",giverType="NPC",giverId=26379,ender="Saurfang the Younger",enderType="NPC",enderId=25257,rewardNextId=12496,poiX=3842,poiY=1487,wowhead="https://www.wowhead.com/wotlk/quest=12224",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You have done well, $g brother:sister;. All that you have faced, you have done as a champion of the Horde. The Scourged Anub'ar of Azjol-Nerub, crushed under your foot! The taunka, brave and powerful new members of the Horde, because of you! Our super-weapon against the Scourge, tested and perfected by you!$B$BThe time has come, the moment is now - our elite soldiers at the Wrathgate need you. The son of Saurfang awaits your arrival at the Kor'kron Vanguard. Go now, northeast to the Wrathgate.",logDesc="Report to Saurfang the Younger at the Kor'kron Vanguard.",choiceRewards={{id=38541,qty=1},{id=38543,qty=1},{id=38540,qty=1},{id=38542,qty=1}}} end
if not DB[12225] then DB[12225]={id=12225,zoneId=394,name="Mmm... Amberseeds!",level=73,minLevel=73,ender="Master Woodsman Anderhol",enderType="NPC",enderId=27277,rewardNextId=12226,wowhead="https://www.wowhead.com/wotlk/quest=12225",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Your stomach growls as the pungent smell of hearty nuts draws your attention to the the bucket of seeds.$b$bSome thoughtful soul has obviously left these complimentary morsels here to rejuvenate weary visitors. Grateful, you take the remaining few and devour them.$b$bThe seeds do not disappoint. Finding yourself hungry for more, you set out to discover their origins....",logDesc="Speak with Master Woodsman Anderhol in Amberpine Lodge."} end
if not DB[12226] then DB[12226]={id=12226,zoneId=394,name="Just Passing Through",level=73,minLevel=73,giver="Master Woodsman Anderhol",giverType="NPC",giverId=27277,ender="Master Woodsman Anderhol",enderType="NPC",enderId=27277,rewardNextId=12227,poiX=3418,poiY=-2796,wowhead="https://www.wowhead.com/wotlk/quest=12226",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="We must act quickly, $r! We can't risk letting those precious seeds become fully digested. They need to come out, NOW.$b$bForage up some blackroot from the riverbank just west of here and I'll make you a purgative that should get things moving.$b$bHurry now! And remember, you brought this upon yourself....",logDesc="Anderhol at Amberpine Lodge wants you to bring him 5 Blackroot Stalks."} end
if not DB[12227] then DB[12227]={id=12227,zoneId=394,name="Doing Your Duty",level=73,minLevel=73,giver="Master Woodsman Anderhol",giverType="NPC",giverId=27277,ender="Master Woodsman Anderhol",enderType="NPC",enderId=27277,poiX=3418,poiY=-2796,wowhead="https://www.wowhead.com/wotlk/quest=12227",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Alright, $r. Here's the juice.$b$bIt works immediately, so don't use it until you're safely inside the outhouse.$b$bNow go get me those seeds!",logDesc="Anderhol in Amberpine Lodge wants you to take the Anderhol's Slider Cider and use the nearby outhouse to retrieve the Partially Processed Amberseeds.",choiceRewards={{id=38746,qty=1},{id=38745,qty=1},{id=38747,qty=1}}} end
if not DB[12228] then DB[12228]={id=12228,zoneId=-161,name="Reacquiring the Magic [PH]",level=60,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=12228",image="assets/images/quests/placeholder.png"} end
if not DB[12229] then DB[12229]={id=12229,zoneId=394,name="A Possible Link",level=74,minLevel=72,giver="Windseer Grayhorn",giverType="NPC",giverId=27262,ender="Windseer Grayhorn",enderType="NPC",enderId=27262,poiX=3317,poiY=-2292,wowhead="https://www.wowhead.com/wotlk/quest=12229",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Not long ago we sent an expedition to the east, where it was attacked by crazed furbolgs.  One of the survivors described slaying one of them and its body expelling a dark slimy substance.$B$BFor thousands of years, the furbolgs in this region have been peaceful.  It is possible that there is a link to the furbolgs' behavior and the dark energy we were able to detect earlier.$B$BBring me samples of the furbolgs' blood.  You will find them to the east in the Rage Fang Shrine and the Heart's Blood Shrine.",logDesc="Windseer Grayhorn in Conquest Hold wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart's Blood Shrine and Rage Fang Shrine.",choiceRewards={{id=38726,qty=1},{id=39025,qty=1},{id=39053,qty=1},{id=39091,qty=1}}} end
if not DB[12230] then DB[12230]={id=12230,zoneId=65,name="Stealing from the Siegesmiths",level=72,minLevel=71,giver="Deathguard Molder",giverType="NPC",giverId=27320,ender="Deathguard Molder",enderType="NPC",enderId=27320,rewardNextId=12232,poiX=3242,poiY=-683,wowhead="https://www.wowhead.com/wotlk/quest=12230",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I'm tasked with the destruction of the Scarlet Onslaught's ballistae. Unfortunately, the apothecaries and I are at odds on the use of our resources, so I've nothing to destroy them with!$B$BTo the northeast are the Carrion Fields. The Scourge siegesmiths there at their forge and meat wagons are demolition masters.$B$BLuckily for us, they also leave their bombs lying about. $B$BI want you to retrieve them for me, off of the ground or the siegesmiths, I don't care which.",logDesc="Deathguard Molder at Venomspite has asked you to retrieve 6 Siegesmith Bombs."} end
if not DB[12231] then DB[12231]={id=12231,zoneId=394,name="The Bear God's Offspring",level=75,minLevel=72,giver="Windseer Grayhorn",giverType="NPC",giverId=27262,ender="Windseer Grayhorn",enderType="NPC",enderId=27262,poiX=3317,poiY=-2292,wowhead="https://www.wowhead.com/wotlk/quest=12231",image="assets/images/quests/placeholder.png",xpDiff=4,desc="It is possible that the furbolg of Grizzly Hills have the same taint that plagued Vordrassil.  They've been involved in a deadly tribal war recently after years of peaceful coexistence.$B$BThe shrines that they guard to the east are home to Ursoc's offspring.$B$BIf the corruption has affected the furbolg, it is possible that because of their lineage, Kodian and Orsonn have remained unharmed.$B$BIf that's the case, find them and listen to what they have to say.",logDesc="Windseer Grayhorn in Conquest Hold wants you to speak to Orsonn at the Ragefang Shrine and Kodian at the Heart's Blood Shrine."} end
if not DB[12232] then DB[12232]={id=12232,zoneId=65,name="Bombard the Ballistae",level=72,minLevel=71,giver="Deathguard Molder",giverType="NPC",giverId=27320,ender="Deathguard Molder",enderType="NPC",enderId=27320,poiX=3242,poiY=-683,wowhead="https://www.wowhead.com/wotlk/quest=12232",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="At last, our chance to strike at their siege engines! Don't flub it.$B$BI kid.$B$BA little.$B$B$C, bombard New Hearthglen's ballistae with these bombs.$B$BWe'll show the Royal Apothecary Society how it's done old style. No concoctions required!",logDesc="Deathguard Molder at Venomspite has asked you to use the Siegesmith Bombs to bombard 5 New Hearthglen Ballistae.",choiceRewards={{id=37992,qty=1},{id=37949,qty=1},{id=38284,qty=1}}} end
if not DB[12233] then DB[12233]={id=12233,zoneId=394,name="[Depricated]Sewing Your Seed",level=73,minLevel=73,wowhead="https://www.wowhead.com/wotlk/quest=12233",image="assets/images/quests/placeholder.png",desc="No, no... You hold on to these.$b$bYou didn't actually expect me to handle them after all of that did you?$b$bhere's what you're going to do...."} end
if not DB[12234] then DB[12234]={id=12234,zoneId=65,name="Need to Know",level=72,minLevel=71,giver="Spy Mistress Repine",giverType="NPC",giverId=27337,ender="Spy Mistress Repine",enderType="NPC",enderId=27337,rewardNextId=12239,poiX=3218,poiY=-676,wowhead="https://www.wowhead.com/wotlk/quest=12234",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I need to know what New Hearthglen is up to.$B$BI want you to steal their orders of the day so that I can find that out.$B$BHead south and in their abbey, in their barracks, and on their beach, find those daily plans!$B$BJust in case you're confused, the barracks is the large building right next to the smithy.",logDesc="Spy Mistress Repine at Venomspite has asked you to steal the Scarlet Onslaught Daily Orders: Abbey, Scarlet Onslaught Daily Orders: Barracks, and Scarlet Onslaught Daily Orders: Beach."} end
if not DB[12235] then DB[12235]={id=12235,zoneId=65,name="Naxxramas and the Fall of Wintergarde",level=72,minLevel=71,giver="High Commander Halford Wyrmbane",giverType="NPC",giverId=27136,ender="Gryphon Commander Urik",enderType="NPC",enderId=27317,rewardNextId=12237,poiX=3768,poiY=-775,wowhead="https://www.wowhead.com/wotlk/quest=12235",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Lord Fordragon has led a crushing assault against Arthas at the Wrathgate. In response to this affront, Arthas has sent Naxxramas down upon us. While Kel'Thuzad hides in the floating citadel, his ground commander, Thel'zan, lays siege to Wintergarde Keep. The lower village is already lost and any chance of extracting survivors from the ruins diminishes by the minute.$B$BWe must act quickly! Report to Gryphon Commander Urik at the gryphon station at once! He'll get you up to speed.$B$BLeave me!$B",logDesc="Speak with Gryphon Commander Urik at the gryphon station in Wintergarde Keep."} end
if not DB[12236] then DB[12236]={id=12236,zoneId=394,name="Ursoc, the Bear God",level=75,minLevel=72,giver="Windseer Grayhorn",giverType="NPC",giverId=27262,ender="Windseer Grayhorn",enderType="NPC",enderId=27262,poiX=3317,poiY=-2292,wowhead="https://www.wowhead.com/wotlk/quest=12236",image="assets/images/quests/placeholder.png",xpDiff=7,money=177000,desc="The time has come, $N.  Now we will learn whether our efforts will accomplish what we need or nothing at all.$B$BTake these ashes and seek the furbolg that Kodian told you about, Tur Ragepaw, near Ursoc's Den.  You will find the den to the north of Grizzlemaw.$B$BConvince Tur to aid you, for you will need all the help you can get.$B$BOnce you've defeated the bear god, use these ashes over his body.$B$BEven if his worldly form is destroyed, his spirit must be saved.",logDesc="Windseer Grayhorn in Conquest Hold wants you to find Tur Ragepaw near Ursoc's Den and defeat Ursoc with his help.  Use the Purified Ashes of Vordrassil on Ursoc's Corpse when you've accomplished this.",rewards={{id=39173,qty=1}},choiceRewards={{id=39176,qty=1},{id=39177,qty=1},{id=39178,qty=1},{id=39174,qty=1},{id=39175,qty=1}}} end
if not DB[12237] then DB[12237]={id=12237,zoneId=65,name="Flight of the Wintergarde Defender",level=72,minLevel=71,giver="Gryphon Commander Urik",giverType="NPC",giverId=27317,ender="Gryphon Commander Urik",enderType="NPC",enderId=27317,rewardNextId=12251,poiX=3701,poiY=-697,wowhead="https://www.wowhead.com/wotlk/quest=12237",image="assets/images/quests/placeholder.png",xpDiff=5,desc="With this whistle you can call down a Wintergarde gryphon. Mount the creature and head towards the ruins of Wintergarde Village, now known as the Carrion Fields, southeast of here. Once at the fields, keep your eyes peeled for helpless Wintergarde villagers. When you spot one, fly low and use the gryphon to pick them up. Return the rescued villager here, to the gryphon station.$B$BThere are Scourge all over the place so you'll need to keep your wits about you, hero. Good luck!",logDesc="Rescue 10 Helpless Wintergarde Villagers and return to Gryphon Commander Urik at Wintergarde Keep."} end
if not DB[12238] then DB[12238]={id=12238,zoneId=4196,name="Cleansing Drak'Tharon",level=75,minLevel=73,giver="Image of Drakuru",giverType="NPC",giverId=26787,ender="Drakuru",enderType="NPC",enderId=28016,poiX=4600,poiY=-4877,wowhead="https://www.wowhead.com/wotlk/quest=12238",image="assets/images/quests/placeholder.png",xpDiff=7,money=177000,desc="The time be here at last, good friend.$b$bDrak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. My soul will be havin' peace, and in return for your help, the keep's most valuable treasures be yours, mon!$b$bDa keep rises up into a sacred ziggurat. Once ya be reachin' its top, ya must summon me a final time, and I'll perform the ritual.$b$bAlas, mon, my summonin' will again be comin' at a cost. Ya must collect the mojo from the survivors in the keep,",logDesc="Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo.",choiceRewards={{id=40758,qty=1},{id=40755,qty=1},{id=40757,qty=1},{id=40756,qty=1}}} end
if not DB[12239] then DB[12239]={id=12239,zoneId=65,name="The Spy in New Hearthglen",level=72,minLevel=71,giver="Spy Mistress Repine",giverType="NPC",giverId=27337,ender="Agent Skully",enderType="NPC",enderId=27350,rewardNextId=12254,poiX=3218,poiY=-676,wowhead="https://www.wowhead.com/wotlk/quest=12239",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I have a spy within the ranks of the Scarlet Onslaught. I need you to deliver these daily orders to her so that she can plan the next phase of our assault.$B$BShe goes by the name of Agent Skully and she's under a magical guise to appear as the Onslaught's cemetery caretaker.$B$BHere, take these orders to her, and then do as she asks. You'll find the graveyard on the side of the abbey.",logDesc="Deliver the Scarlet Onslaught Daily Orders to Agent Skully at New Hearthglen."} end
if not DB[12240] then DB[12240]={id=12240,zoneId=65,name="A Means to an End",level=72,minLevel=71,giver="Apothecary Vicky Levine",giverType="NPC",giverId=27248,ender="Apothecary Vicky Levine",enderType="NPC",enderId=27248,rewardNextId=12243,poiX=3222,poiY=-691,wowhead="https://www.wowhead.com/wotlk/quest=12240",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I received a few barrels of termites from my sister at the Bulwark back home in the last shipment. I think they're going to come in handy for something I have in mind for you.$B$BThe lumbermill operations at New Hearthglen are problematic for us, but so far we haven't been able to get anyone in there to take out their foreman.$B$BI think that if you were to unleash these termites on his precious woodworks, he'd be sure to come running.$B$BReady to take him out, $c?",logDesc="Apothecary Vicky Levine at Venomspite has asked you to use the Levine Family Termites to lure Foreman Kaleiki out and kill him."} end
if not DB[12241] then DB[12241]={id=12241,zoneId=394,name="Destroy the Sapling",level=75,minLevel=72,giver="Windseer Grayhorn",giverType="NPC",giverId=27262,ender="Windseer Grayhorn",enderType="NPC",enderId=27262,rewardNextId=12236,poiX=3317,poiY=-2292,wowhead="https://www.wowhead.com/wotlk/quest=12241",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The furbolgs' work must be undone, $N.  The best of intentions do not count for much when the result is tainted by such strong a corruption.$B$BThe sapling must be destroyed, for it is the source of this dark influence.  Take this torch and use it to set fire to the corrupted sapling and bring me its ashes.$B$BOnce cleansed, by fire, I will use what power I can to remove the taint from them.  You will need the ashes to purify Ursoc from the evil power that holds sway over him.",logDesc="Windseer Grayhorn in Conquest Hold wants you to take the Verdant Torch and use it to burn Vordrassil's Sapling.  Bring Vordrassil's Ashes back to Windseer Grayhorn."} end
if not DB[12242] then DB[12242]={id=12242,zoneId=394,name="Vordrassil's Seeds",level=74,minLevel=73,giver="Windseer Grayhorn",giverType="NPC",giverId=27262,ender="Windseer Grayhorn",enderType="NPC",enderId=27262,rewardNextId=12236,poiX=3317,poiY=-2292,wowhead="https://www.wowhead.com/wotlk/quest=12242",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We must make sure that Vordrassil is never regrown.  The furbolg must have harvested its seed.$B$BGo to Grizzlemaw, in central Grizzly Hills, and obtain all the seeds that you can find.  I will make sure they're properly destroyed.",logDesc="Windseer Grayhorn in Conquest Hold wants you to go to Grizzlemaw and obtain 8 of Vordrassil's Seeds.",choiceRewards={{id=38753,qty=1},{id=38743,qty=1},{id=38757,qty=1}}} end
if not DB[12243] then DB[12243]={id=12243,zoneId=65,name="Fire Upon the Waters",level=72,minLevel=71,giver="Apothecary Vicky Levine",giverType="NPC",giverId=27248,ender="Apothecary Vicky Levine",enderType="NPC",enderId=27248,poiX=3222,poiY=-691,wowhead="https://www.wowhead.com/wotlk/quest=12243",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="I have another mission for you.$B$BI was able to repurpose some of the blight to concoct my world-famous burning water. I want you to take it and set the sails of the Sinner's Folly ablaze!$B$BUse it from the dock. Once the sails are on fire, the deckhands will be busy putting them out, and you'll slip belowdecks to 'retrieve' the captain's rutters.$B$BYou'll find the ship on Crusader's Landing, below and south of New Hearthglen. Look for the captain's quarters on the first lower deck, behind the stairs.",logDesc="Apothecary Vicky Levine at Venomspite has asked you to use her Apothecary's Burning Water to set the sails of the Sinner's Folly afire.$B$BWhile the deckhands are busy attempting to put the fires out, head belowdecks and retrieve Captain Shely's Rutters from the captain.",choiceRewards={{id=37950,qty=1},{id=37993,qty=1},{id=38037,qty=1},{id=38068,qty=1}}} end
if not DB[12244] then DB[12244]={id=12244,zoneId=394,name="Shredder Repair",level=74,minLevel=73,giver="Synipus",giverType="NPC",giverId=27371,ender="Synipus",enderType="NPC",enderId=27371,poiX=3992,poiY=-3186,wowhead="https://www.wowhead.com/wotlk/quest=12244",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Listen, pal. Why don't ya roll up your sleeves and grab a wrench? There's work to be done! They need these shredders refurbished and sent down to Venture Bay, and they need it done yesterday....$b$bNo wrench? Well what good are ya then? May as well go down with the rest of the lugheads and play with the Horde!$b$bWhile you're there, see if you can drive some of those broken-down shredders up here for repairs. Be careful! They're in pretty bad shape.",logDesc="Synipus at Blue Sky Logging Grounds wants you to bring 3 Broken-down Shredders back to him.",rewards={{id=37500,qty=1}}} end
if not DB[12245] then DB[12245]={id=12245,zoneId=65,name="No Mercy for the Captured",level=72,minLevel=71,giver="Spy Mistress Repine",giverType="NPC",giverId=27337,ender="High Executor Wroth",enderType="NPC",enderId=27243,rewardNextId=12252,poiX=3218,poiY=-676,wowhead="https://www.wowhead.com/wotlk/quest=12245",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="We have more fools for you to kill.$B$BMy agents tell me that several of our good citizens have seen fit to fall into the hands of the Scarlet Onslaught.$B$BThis will not do.$B$BGo back to New Hearthglen and eliminate Deathguard Schneider, Senior Scrivener Barriga, Engineer Burke and Chancellor Amai.$B$BFrom what I hear, they're spread out throughout the area. No doubt they are being kept in cages awaiting torture.$B$BSpeak with them and then kill them!",logDesc="Spy Mistress Repine has asked you to slay Deathguard Schneider, Senior Scrivener Barriga, Engineer Burke, and Chancellor Amai.$B$BWhen you've accomplished this task, report your success to High Executor Wroth at Venomspite."} end
if not DB[12246] then DB[12246]={id=12246,zoneId=394,name="A Possible Link",level=74,minLevel=73,giver="Hierophant Thayreen",giverType="NPC",giverId=27295,ender="Hierophant Thayreen",enderType="NPC",enderId=27295,poiX=3435,poiY=-2746,wowhead="https://www.wowhead.com/wotlk/quest=12246",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The furbolgs that live east of here are more aggressive and bestial than the ones we're used to.  Our forces have squared off with them more than once, and the survivors always speak of a dark, slimy substance dripping from their corpses.$B$BTheir condition could be linked with the contaminants we found on Vordrassil's remains.$B$BBring me samples of the furbolgs' blood.  You will find them in the Rage Fang Shrine and the Heart's Blood Shrine, far to the east.",logDesc="Hierophant Thayreen at Amberpine Lodge wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart's Blood Shrine and Rage Fang Shrine.",choiceRewards={{id=38726,qty=1},{id=39025,qty=1},{id=39053,qty=1},{id=39091,qty=1}}} end
if not DB[12247] then DB[12247]={id=12247,zoneId=394,name="Children of Ursoc",level=75,minLevel=73,giver="Hierophant Thayreen",giverType="NPC",giverId=27295,ender="Hierophant Thayreen",enderType="NPC",enderId=27295,poiX=3435,poiY=-2746,wowhead="https://www.wowhead.com/wotlk/quest=12247",image="assets/images/quests/placeholder.png",xpDiff=4,desc="The furbolgs of Grizzly Hills carry with them a corruption of some kind, that is for sure.  Tribal war has broken out amongst them after years of peaceful coexistence.$B$BWhat remains to be seen is whether the bears they worship as gods have also been tainted.$B$BUrsoc's two children, Orsonn and Kodian, dwell in the Heart's Blood Shrine and the Rage Fang Shrine, south and southeast of Grizzlemaw.$B$BSee if they will speak to you regarding what has happened here.",logDesc="Hierophant Thayreen at Amberpine Lodge wants you to speak to Orsonn at the Rage Fang Shrine and Kodian at the Heart's Blood Shrine."} end
if not DB[12248] then DB[12248]={id=12248,zoneId=394,name="Vordrassil's Sapling",level=75,minLevel=73,giver="Hierophant Thayreen",giverType="NPC",giverId=27295,ender="Hierophant Thayreen",enderType="NPC",enderId=27295,rewardNextId=12249,poiX=3435,poiY=-2746,wowhead="https://www.wowhead.com/wotlk/quest=12248",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The druids of old seem to have had good reasons for destroying Vordrassil.  We cannot let the furbolgs regrow it.$B$BOn the other hand, saving Ursoc's spirit hinges on the magic contained by the sapling.$B$BTake this torch and use it to burn the tree.  You will find it in the middle of Grizzlemaw, inside Vordrassil's old trunk.$B$BBring me Vordrassil's ashes.  It is my hope that once purified by fire, we may use its magic to cleanse Ursoc's spirit of its dark taint.",logDesc="Hierophant Thayreen in Amberpine Lodge wants you to take the Verdant Torch and use it to burn Vordrassil's Sapling.  Bring Vordrassil's Ashes back to Hierophant Thayreen."} end
if not DB[12249] then DB[12249]={id=12249,zoneId=394,name="Ursoc, the Bear God",level=75,minLevel=73,giver="Hierophant Thayreen",giverType="NPC",giverId=27295,ender="Hierophant Thayreen",enderType="NPC",enderId=27295,rewardNextId=12070,poiX=3435,poiY=-2746,wowhead="https://www.wowhead.com/wotlk/quest=12249",image="assets/images/quests/placeholder.png",xpDiff=7,money=177000,desc="It is time, $N.  Take these ashes and look for the furbolg that Kodian spoke of.  If he went to seek Ursoc, he will be near his den, north of Grizzlemaw.$B$BYou will need his help.  You won't be able to defeat Ursoc alone.$B$BOnce you've defeated Ursoc, use these ashes to purify his spirit.  Only then will we know whether our efforts have been in vain or not.",logDesc="Hierophant Thayreen at Amberpine Lodge wants you to find Tur Ragepaw near Ursoc's Den and defeat Ursoc with his help.  Use the Purified Ashes of Vordrassil on Ursoc's Corpse when you've accomplished this.",rewards={{id=39173,qty=1}},choiceRewards={{id=39176,qty=1},{id=39177,qty=1},{id=39178,qty=1},{id=39174,qty=1},{id=39175,qty=1}}} end
if not DB[12250] then DB[12250]={id=12250,zoneId=394,name="Vordrassil's Seeds",level=75,minLevel=73,giver="Hierophant Thayreen",giverType="NPC",giverId=27295,ender="Hierophant Thayreen",enderType="NPC",enderId=27295,rewardNextId=12249,poiX=3435,poiY=-2746,wowhead="https://www.wowhead.com/wotlk/quest=12250",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We cannot allow Vordrassil to grow again.  If the furbolg regrew it once, they can do it again.$B$BGo to Grizzlemaw, in central Grizzly Hills, and obtain Vordrassil's seeds.  I will make sure they're properly disposed of.",logDesc="Hierophant Thayreen at Amberpine Lodge wants you to go to Grizzlemaw and obtain 8 of Vordrassil's Seeds.",choiceRewards={{id=38753,qty=1},{id=38743,qty=1},{id=38757,qty=1}}} end
if not DB[12251] then DB[12251]={id=12251,zoneId=65,name="Return to the High Commander",level=72,minLevel=71,giver="Gryphon Commander Urik",giverType="NPC",giverId=27317,ender="High Commander Halford Wyrmbane",enderType="NPC",enderId=27136,rewardNextId=12253,poiX=3701,poiY=-697,wowhead="https://www.wowhead.com/wotlk/quest=12251",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Return to High Commander Halford Wyrmbane at once, $N. Let him know that your mission was a success and that the few remaining villagers that were rescued are back to work.",logDesc="Speak with High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.",choiceRewards={{id=37956,qty=1},{id=37998,qty=1},{id=38041,qty=1},{id=38102,qty=1}}} end
if not DB[12252] then DB[12252]={id=12252,zoneId=65,name="Torture the Torturer",level=72,minLevel=71,giver="High Executor Wroth",giverType="NPC",giverId=27243,ender="High Executor Wroth",enderType="NPC",enderId=27243,poiX=3209,poiY=-679,wowhead="https://www.wowhead.com/wotlk/quest=12252",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="Enough! I want you to put an end to the torture of my people!$B$BThe Onslaught's torturer, LeCraft, has been bleeding information out of everyone that gets caught by those fiends! I need to know what they know.$B$BMy sources tell me that he has set up shop in the basement of their barracks, which is right next to the smithy.$B$BI'll loan you my personal branding iron to see to it that the job is done right.$B$BFind him and get that information.",logDesc="High Executor Wroth at Venomspite wants you to use the branding iron 5 times on Torturer LeCraft to get the information out of him. After that, kill him.",choiceRewards={{id=37953,qty=1},{id=37995,qty=1},{id=38039,qty=1},{id=38100,qty=1}}} end
if not DB[12253] then DB[12253]={id=12253,zoneId=65,name="Rescue from Town Square",level=72,minLevel=71,giver="High Commander Halford Wyrmbane",giverType="NPC",giverId=27136,ender="High Commander Halford Wyrmbane",enderType="NPC",enderId=27136,rewardNextId=12309,poiX=3768,poiY=-775,wowhead="https://www.wowhead.com/wotlk/quest=12253",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Just down this path here is Wintergarde's town square. Once a hive of activity for the citizens of Wintergarde, now a warzone, filled with murderous geists hell-bent on vengeance towards the living.$B$BIn the buildings surrounding the town square are trapped villagers that must be rescued! I ask much of you, now, $N, but you are the only soldier I can spare. Free our people. Take this path down into town square and enter those houses. Kill anything that gets in your way! Return to me should you survive.",logDesc="High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight wants you to rescue 6 Trapped Wintergarde Villagers."} end
if not DB[12254] then DB[12254]={id=12254,zoneId=65,name="Without a Prayer",level=72,minLevel=71,giver="Agent Skully",giverType="NPC",giverId=27350,ender="Agent Skully",enderType="NPC",enderId=27350,rewardNextId=12260,poiX=2825,poiY=-500,wowhead="https://www.wowhead.com/wotlk/quest=12254",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="These plans indicate something imminent is being planned.$B$BBut first, there's the matter of this strange protection that the Onslaught forces have. If Venomspite is to deal with them once and for all, we must find out who's behind it and eliminate them.$B$BI've noticed that the bishop in the chapel on the far side of New Hearthglen, across from the lumbermill, has stepped up his blessing of the troops. Kill him and steal his prayer book.$B$BMaybe it will give us a clue.",logDesc="Agent Skully at New Hearthglen has asked you to acquire Bishop Street's Prayer Book."} end
if not DB[12255] then DB[12255]={id=12255,zoneId=394,name="The Thane of Voldrune",level=74,minLevel=73,giver="Woodsman Drake",giverType="NPC",giverId=27391,ender="Woodsman Drake",enderType="NPC",enderId=27391,poiX=3419,poiY=-2812,wowhead="https://www.wowhead.com/wotlk/quest=12255",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Now that you've captured the flame-imbued talismans and weakened Voldrune's defenses, we can strike at its leader, Thane Torvald Eriksson.$B$BThe thane's favorite mount is an unruly proto-drake he calls Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the talismans, you should be able to control it long enough to use it against the thane.$B$BOnce you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and show him no mercy.",logDesc="Use Flamebringer to defeat Thane Torvald Eriksson and report to Woodsman Drake at Amberpine Lodge.",choiceRewards={{id=38712,qty=1},{id=39016,qty=1},{id=39045,qty=1},{id=39077,qty=1},{id=38749,qty=1}}} end
if not DB[12256] then DB[12256]={id=12256,zoneId=394,name="The Flamebinders' Secrets",level=74,minLevel=73,giver="Sergeant Nazgrim",giverType="NPC",giverId=27388,ender="Sergeant Nazgrim",enderType="NPC",enderId=27388,rewardNextId=12259,poiX=3275,poiY=-2213,wowhead="https://www.wowhead.com/wotlk/quest=12256",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Even as the Alliance cowards attack our positions, the Dragonflayer vrykul outpost of Voldrune, to the southeast, prepares for war. The vrykul are far from the strongest enemy we face here, but we must eliminate them before they can truly threaten us.$B$BTheir most powerful warriors are permitted to ride half-trained proto-drakes into battle. To control the beasts, their flamebinders create powerful talismans. You'll need to slay them and take the talismans if our plan is to work.",logDesc="Bring 3 Flame-Imbued Talismans to Sergeant Nazgrim at Conquest Hold."} end
if not DB[12257] then DB[12257]={id=12257,zoneId=394,name="A Show of Strength",level=74,minLevel=73,giver="Sergeant Nazgrim",giverType="NPC",giverId=27388,ender="Sergeant Nazgrim",enderType="NPC",enderId=27388,rewardNextId=12259,poiX=3275,poiY=-2213,wowhead="https://www.wowhead.com/wotlk/quest=12257",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Preparations for war are underway in the vrykul village of Voldrune to the southeast. Voldrune's thane cannot field a large army, but with our forces spread thin, we are still at risk.$B$BWe cannot risk giving the thane and his men an opportunity to attack, so we must take the battle to them. If you are truly a $c of the Horde, you will relish the chance to demonstrate our strength.$B$BCut down the huscarls and prove to this Dragonflayer clan that the Horde is not to be trifled with!",logDesc="Kill 12 Dragonflayer Huscarls and return to Sergeant Nazgrim at Conquest Hold."} end
if not DB[12258] then DB[12258]={id=12258,zoneId=65,name="The Fate of the Dead",level=72,minLevel=71,giver="Commander Lynore Windstryke",giverType="NPC",giverId=27155,ender="Commander Lynore Windstryke",enderType="NPC",enderId=27155,poiX=3773,poiY=-784,wowhead="https://www.wowhead.com/wotlk/quest=12258",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The town square, down this path, is overrun with the undead citizens of Wintergarde! Our own crypt provides a seemingly endless supply of soldiers for the Scourge to throw at us. Take no pity on them, though, $N. While they were once mortal, capable of compassion and thought, they are now ravaging undead with only one purpose: our destruction.$B$BVenture forth to the town square and deliver the vengeful geists to their maker. Give them peace.",logDesc="Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 15 Vengeful Geists.$B",choiceRewards={{id=37954,qty=1},{id=37996,qty=1},{id=38040,qty=1},{id=38101,qty=1}}} end
if not DB[12259] then DB[12259]={id=12259,zoneId=394,name="The Thane of Voldrune",level=74,minLevel=73,giver="Sergeant Nazgrim",giverType="NPC",giverId=27388,ender="Sergeant Nazgrim",enderType="NPC",enderId=27388,rewardNextId=12412,poiX=3275,poiY=-2213,wowhead="https://www.wowhead.com/wotlk/quest=12259",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="With the flame-imbued talismans, we can finally challenge the thane.$B$BHis favorite mount is a ferocious proto-drake called Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the power of the talismans, you should be able to bend it to your will and use it against the thane.$B$BOnce you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and use Flamebringer to destroy him.",logDesc="Use Flamebringer to defeat Thane Torvald Eriksson and report to Sergeant Nazgrim at Conquest Hold.",choiceRewards={{id=38712,qty=1},{id=39016,qty=1},{id=39045,qty=1},{id=39077,qty=1},{id=38749,qty=1}}} end
if not DB[12260] then DB[12260]={id=12260,zoneId=65,name="The Perfect Dissemblance",level=72,minLevel=71,giver="Agent Skully",giverType="NPC",giverId=27350,ender="Agent Skully",enderType="NPC",enderId=27350,rewardNextId=12274,poiX=2825,poiY=-500,wowhead="https://www.wowhead.com/wotlk/quest=12260",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="You may wonder how I can maintain this guise; I use a magic mirror that was loaned to me by the spy mistress.$B$BIt only has so much power in it, but I think there's enough for the both of us. Here, take it. I want you to use it to impersonate one of the Onslaught raven priests.$B$BBe quick about it... I have no idea how long my glamour will last while you have the mirror.$B$BRealize that you won't immediately be perfectly disguised, so don't count on it being foolproof until I've had a chance to help you.",logDesc="Agent Skully at New Hearthglen has asked you steal the image of a Onslaught Raven Priest. Return the Banshee's Magic Mirror to her when you have done so."} end
if not DB[12261] then DB[12261]={id=12261,zoneId=65,name="No Place to Run",level=74,minLevel=72,giver="Serinar",giverType="NPC",giverId=26593,ender="Serinar",enderType="NPC",enderId=26593,rewardNextId=12263,poiX=4451,poiY=1652,wowhead="https://www.wowhead.com/wotlk/quest=12261",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="They're drawing power from the bones of my dead brothers...$B$BI have no love for the cult, but I'm baffled by their audacity. There will be no mercy shown for them... not that I ever would have anyway.$B$BEnsure that they have no place to flee when the slaughter starts. Place a destructive ward at the end of the path leading out of the shrine... where the road starts to give way to snow. Defend it until it is fully charged.",logDesc="Place a Destructive Ward at the end of the path leading out of Obsidian Dragonshrine, where the road starts to give way to snow. Protect the ward until it is fully charged, then return to Serinar."} end
if not DB[12262] then DB[12262]={id=12262,zoneId=65,name="No One to Save You",level=74,minLevel=72,giver="Serinar",giverType="NPC",giverId=26593,ender="Serinar",enderType="NPC",enderId=26593,poiX=4451,poiY=1652,wowhead="https://www.wowhead.com/wotlk/quest=12262",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="We will spare no one. $B$BOutside, lowly necrolytes and their skeletal servants shame my land with their presence. Slaughter them all.",logDesc="Kill 6 Burning Depths Necrolytes and 10 Smoldering Skeletons outside of the Obsidian Dragonshrine. Return to Serinar once the task is complete."} end
if not DB[12263] then DB[12263]={id=12263,zoneId=65,name="The Best of Intentions",level=74,minLevel=72,giver="Serinar",giverType="NPC",giverId=26593,ender="Serinar",enderType="NPC",enderId=26593,poiX=4451,poiY=1652,wowhead="https://www.wowhead.com/wotlk/quest=12263",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="The Cult of the Damned has not come just to extract power from dead dragons. I suspect I know what they are up to, but I need you to prove me correct.$B$BI will grant you the guise of this dead necrolyte. Proceed to the back of the cave and confirm their intentions for being in this sacred place. I will watch through your eyes. $B$BBe cautious $N, any damage done to you is likely to break the fragile illusion.",logDesc="Wait for Serinar to administer the disguise of a Burning Depths Necrolyte, then proceed to the back of the Maw of Neltharion to uncover what the Cult of the Damned is doing there. Return to Serinar with details regarding their purpose."} end
if not DB[12264] then DB[12264]={id=12264,zoneId=65,name="Culling the Damned",level=74,minLevel=72,giver="Serinar",giverType="NPC",giverId=26593,ender="Serinar",enderType="NPC",enderId=26593,poiX=4451,poiY=1652,wowhead="https://www.wowhead.com/wotlk/quest=12264",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="The cave beyond was swarming with Cult atrocities. There is only one way to deal with such creatures... you know what to do.",logDesc="Kill 3 Burning Depths Necromancers, 6 Smoldering Constructs, and 6 Smoldering Geist in the Maw of Neltharion, and then return to Serinar."} end
if not DB[12265] then DB[12265]={id=12265,zoneId=65,name="Defiling the Defilers",level=74,minLevel=72,giver="Serinar",giverType="NPC",giverId=26593,ender="Serinar",enderType="NPC",enderId=26593,rewardNextId=12267,poiX=4451,poiY=1652,wowhead="https://www.wowhead.com/wotlk/quest=12265",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="I sensed a large accumulation of magic in the runes that we witnessed when you were scouting the cave. I will not have you toy with extracting the magic... often the most straight forward solution is the most effective one.$B$BDestroy the runes... stamp them out and ensure that the Cult will not have access to whatever power that they've accumulated there.",logDesc="Locate and stamp out 8 Necromantic Runes that have been drawn on the floor inside the Maw of Neltharion. Return to Serinar once the task is complete."} end
if not DB[12266] then DB[12266]={id=12266,zoneId=65,name="Tales of Destruction",level=74,minLevel=72,giver="Serinar",giverType="NPC",giverId=26593,ender="Nalice",enderType="NPC",enderId=27765,poiX=4451,poiY=1652,wowhead="https://www.wowhead.com/wotlk/quest=12266",image="assets/images/quests/placeholder.png",xpDiff=1,money=5600,desc="You can leave now, $r.$B$BGo tell Nalice she missed out on a good slaughter.",logDesc="Travel back to Wyrmrest and let Nalice know that Serinar's task is complete."} end
if not DB[12267] then DB[12267]={id=12267,zoneId=65,name="Neltharion's Flame",level=75,minLevel=72,giver="Serinar",giverType="NPC",giverId=26593,ender="Serinar",enderType="NPC",enderId=26593,rewardNextId=12266,poiX=4451,poiY=1652,wowhead="https://www.wowhead.com/wotlk/quest=12267",image="assets/images/quests/placeholder.png",xpDiff=6,money=118000,desc="With the cult's ranks thinned and some of their power stripped, it's time to strike at the source of the corruption.$B$BRothin the Decaying is resurrecting black dragons as magmawyrms in the back of the cave. Go to the summoning chamber and cleanse the remaining bones in the only way that will ensure that they will never be toyed with again... with flame.$B$BBurning the bones will surely gain Rothin's attention, see to it that he is destroyed as well.$B$BThe magic in this vial should see the task done.",logDesc="Use Neltharion's Flame to douse the summoning area in the back of the Maw of Neltharion. Once you get the attention of Rothin the Decaying, kill him, then return to Serinar at the front of the cave.",choiceRewards={{id=37944,qty=1},{id=38032,qty=1},{id=38095,qty=1},{id=37988,qty=1}}} end
if not DB[12268] then DB[12268]={id=12268,zoneId=394,name="Pieces Parts",level=74,minLevel=73,giver="Pipthwack",giverType="NPC",giverId=27416,ender="Pipthwack",enderType="NPC",enderId=27416,poiX=3999,poiY=-3191,wowhead="https://www.wowhead.com/wotlk/quest=12268",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Ack! This thing's a mess!$b$bGoblin engineering leaves a great deal to be desired, believe you me. Just look at this! It's a wonder it ever worked to begin with.$b$bGive me a hand, will ya? To get this even close to operable specifications I'll need to replace a few cogs, sprockets, and springs. You should have no trouble finding them down around the sawmill.",logDesc="Pipthwack in Blue Sky Logging Grounds wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs."} end
if not DB[12269] then DB[12269]={id=12269,zoneId=65,name="Not In Our Mine",level=72,minLevel=71,giver="Highlord Leoric Von Zeldig",giverType="NPC",giverId=27156,ender="Highlord Leoric Von Zeldig",enderType="NPC",enderId=27156,poiX=3693,poiY=-736,wowhead="https://www.wowhead.com/wotlk/quest=12269",image="assets/images/quests/placeholder.png",xpDiff=5,desc="That blasted necropolis blindsided us! In the wake of its destruction Wintergarde Mine was lost. Worse yet, Kel'Thuzad's acolytes have raised the slain miners as Scourge and are using them to supply their siegesmiths with materials from our mine!$B$BThe supply line must be halted and our lost brothers must be put to rest.$B$BTravel to Wintergarde Mine, northeast of here in the Carrion Fields, and destroy the risen miners. Return to me with their miner cards so that I may put their passing in our registry.",logDesc="Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight wants you to recover 10 Wintergarde Miner's Cards."} end
if not DB[12270] then DB[12270]={id=12270,zoneId=394,name="Shred the Alliance",level=74,minLevel=73,giver="Grekk",giverType="NPC",giverId=27423,ender="Grekk",enderType="NPC",enderId=27423,poiX=4379,poiY=-2922,wowhead="https://www.wowhead.com/wotlk/quest=12270",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Read my lips, $c - I need those shredders! Just as important - I need to keep them out of the hands of the Alliance!$b$bThey've been refurbishing the shredders and using them against our brothers in Venture Bay. Now we're going to give them a taste of their own medicine!$b$bYou see a shredder out there, grab it! You see one of the Alliance scum on one, kill 'em and then grab it! Once you have one, drive it back here to me and we'll get to work on it.$b$bDismissed!",logDesc="Grekk at Blue Sky Logging Grounds wants you to acquire 3 shredders and return to him with them.",rewards={{id=37500,qty=1}}} end
if not DB[12271] then DB[12271]={id=12271,zoneId=65,name="The Rod of Compulsion",level=72,minLevel=71,ender="High Executor Wroth",enderType="NPC",enderId=27243,rewardNextId=12273,wowhead="https://www.wowhead.com/wotlk/quest=12271",image="assets/images/quests/placeholder.png",xpDiff=3,money=25000,desc="A rod drops from LeCraft's dead hand. There are pulsing magical runes along its length.$B$BCould this be how he was getting his confessions?$B$BBetter let the high executor have a look at it.",logDesc="Deliver the Torturer's Rod to High Executor Wroth at Venomspite."} end
if not DB[12272] then DB[12272]={id=12272,zoneId=65,name="The Bleeding Ore",level=72,minLevel=71,giver="Siege Engineer Quarterflash",giverType="NPC",giverId=27159,ender="Siege Engineer Quarterflash",enderType="NPC",enderId=27159,poiX=3694,poiY=-739,wowhead="https://www.wowhead.com/wotlk/quest=12272",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hours before the Naxxramas invasion, one of the miners stumbled upon a dark ore that was oozing a viscous fluid. In the chaos that occurred during the evacuation of the mine, we lost the samples taken from the alien node. Now the Scourge prospects the ore for use in their machines of death.$B$BYou must get back to Wintergarde Mine, due northeast of here in the Carrion Fields, and recover the strange ore. It is imperative to our mission's success!",logDesc="Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight wants you to recover 10 samples of Strange Ore from Wintergarde Mine."} end
if not DB[12273] then DB[12273]={id=12273,zoneId=65,name="The Denouncement",level=73,minLevel=71,giver="High Executor Wroth",giverType="NPC",giverId=27243,ender="High Executor Wroth",enderType="NPC",enderId=27243,poiX=3209,poiY=-679,wowhead="https://www.wowhead.com/wotlk/quest=12273",image="assets/images/quests/placeholder.png",xpDiff=6,money=106000,desc="It's time for us to utterly demoralize the Onslaught forces!$B$BI want you to take the rod and use it on four of their leaders: Commander Jordan upstairs at the barracks, Lead Cannoneer Zierhut down the southeast ramp overlooking the beach, Blacksmith Goodman at the smithy, and Stable Master Mercer at the stables.$B$BPlace them under the rod's compulsion, concentrate on making them denounce the Onslaught, and then kill them!",logDesc="High Executor Wroth at Venomspite has tasked you with using the Rod of Compulsion on Commander Jordan, Lead Cannoneer Zierhut, Blacksmith Goodman, and Stable Master Mercer.$B$BOnce the rod has been used on them, kill each to exact a denouncement of the Scarlet Onslaught as their final words.",choiceRewards={{id=37968,qty=1},{id=38011,qty=1},{id=38054,qty=1},{id=38115,qty=1}}} end
if not DB[12274] then DB[12274]={id=12274,zoneId=65,name="A Fall From Grace",level=73,minLevel=71,giver="Agent Skully",giverType="NPC",giverId=27350,ender="Agent Skully",enderType="NPC",enderId=27350,rewardNextId=12283,poiX=2825,poiY=-500,wowhead="https://www.wowhead.com/wotlk/quest=12274",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="We need more information from the high abbot, and now that we have the visage of one of the raven priests, I think we can get you close to talk with him.$B$BUnfortunately, we need to separate him from his bodyguards or you'll never get any information out of him.$B$B<The agent leans on her shovel and thinks a moment.>$B$BI think I've got it! While in disguise, go to the top of the abbey and ring the bell. That should bring the abbot's bodyguards running and you can then head down to speak with him.",logDesc="Agent Skully at New Hearthglen has asked you to ring the bell in the abbey and then go speak with the high abbot and get information out of him."} end
if not DB[12275] then DB[12275]={id=12275,zoneId=65,name="The Demo-gnome",level=72,minLevel=71,giver="High Commander Halford Wyrmbane",giverType="NPC",giverId=27136,ender="Siege Engineer Quarterflash",enderType="NPC",enderId=27159,rewardNextId=12276,poiX=3768,poiY=-775,wowhead="https://www.wowhead.com/wotlk/quest=12275",image="assets/images/quests/placeholder.png",desc="Quarterflash recently requisitioned my group for a specialist that he could send on a reconnaissance mission to the Wintergarde Mine. To that end, I sent him Slinkin, my demolitionist. I foolishly thought that he could close off that pit of damnation after his mission for Quarterflash was complete, securing another victory for us against the Scourge.$B$BAn entire day has now passed and Slinkin has not returned. I want answers! Speak with Siege Engineer Quarterflash and track down my missing agent!",logDesc="Speak with Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight."} end
if not DB[12276] then DB[12276]={id=12276,zoneId=65,name="The Search for Slinkin",level=72,minLevel=71,giver="Siege Engineer Quarterflash",giverType="NPC",giverId=27159,ender="Slinkin the Demo-gnome",enderType="NPC",enderId=27412,rewardNextId=12277,poiX=3694,poiY=-739,wowhead="https://www.wowhead.com/wotlk/quest=12276",image="assets/images/quests/placeholder.png",xpDiff=5,desc="While I have not heard from Slinkin or know what fate has befallen him, perhaps I can assist in finding him.$B$B<Quarterflash holds up a tiny mechanical toy.>$B$BThis is not a toy, newfound compatriot. It is, in fact, my latest mechanical creation. The machine was created with the sole purpose of finding that which has been lost. These are unfortunate circumstances, but the machine is your best chance at finding Slinkin.$B$BWhen you are ready to begin your search, place the bot on the ground next to me.",logDesc="Find Slinkin the Demo-gnome in Wintergarde Mine. Use Quarterflash's Homing Bot if you need help finding the mine."} end
if not DB[12277] then DB[12277]={id=12277,zoneId=65,name="Leave Nothing to Chance",level=72,minLevel=71,giver="Slinkin the Demo-gnome",giverType="NPC",giverId=27412,ender="Siege Engineer Quarterflash",enderType="NPC",enderId=27159,poiX=3997,poiY=-945,wowhead="https://www.wowhead.com/wotlk/quest=12277",image="assets/images/quests/placeholder.png",xpDiff=6,desc="If there is good in your heart and your conscience is clear, read on.$B$BIn this mine, near the foreman's scaffold, rests a hefty cargo of dynamite. Go there and pick up several bundles of the explosive and make your way towards the entrance of the mine. Once there, set the dynamite and blow up the entrance. Remember to do this for the upper and lower entry points of Wintergarde Mine.$B$BYou must leave nothing to chance. The evil that exists here must never be allowed out. Light guide you.",logDesc="Retrieve a Wintergarde Mine Bomb and use it to blow up the Upper Wintergarde Mine Shaft and the Lower Wintergarde Mine Shaft. Report back to Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight when you have completed this task.",choiceRewards={{id=38293,qty=1},{id=38002,qty=1},{id=38106,qty=1},{id=37960,qty=1}}} end
if not DB[12278] then DB[12278]={id=12278,zoneId=-370,name="Brew of the Month Club",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=12278",image="assets/images/quests/placeholder.png",desc="Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.$b$bBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.",logDesc="Bring the \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge."} end
if not DB[12279] then DB[12279]={id=12279,zoneId=394,name="A Bear of an Appetite",level=75,minLevel=72,giver="Hugh Glass",giverType="NPC",giverId=26484,ender="Hugh Glass",enderType="NPC",enderId=26484,poiX=4113,poiY=-4738,wowhead="https://www.wowhead.com/wotlk/quest=12279",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Thank goodness you're back, Limpy! I worried that Griselda and I were going to be all alone.$B$BI'm cooking up some food here for us, but Griselda'll have none of it.$B$BShe's fond of the fish that live off the coast of the Eastwind Shore, to the east. Can't stand them myself, but she's always been a picky eater. Six good-sized fish ought to keep her happy for a while.$B$BNow, run... err... limp along, Joe. Wouldn't want to keep the girl waiting, would ya?",logDesc="Bring 6 Northern Salmon to Hugh Glass at the Redwood Trading Post."} end
if not DB[12280] then DB[12280]={id=12280,zoneId=394,name="Making Repairs",level=74,minLevel=73,giver="Lurz",giverType="NPC",giverId=27422,ender="Lurz",enderType="NPC",enderId=27422,poiX=4376,poiY=-2914,wowhead="https://www.wowhead.com/wotlk/quest=12280",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Twenty shredders by noon tomorrow!$b$bWho makes these schedules, anyway? No one who ever put one of these garbage cans back together, that's who....$b$bIf I'm going to hit my quota, I'll need a hand. Help me out and I'll share my commission with you - fair enough?$b$bI need cogs, sprockets and springs. They're littered across the ground down by the shredders.",logDesc="Lurz at Blue Sky Logging Grounds wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs."} end
if not DB[12281] then DB[12281]={id=12281,zoneId=65,name="Understanding the Scourge War Machine",level=72,minLevel=71,giver="Siege Engineer Quarterflash",giverType="NPC",giverId=27159,ender="High Commander Halford Wyrmbane",enderType="NPC",enderId=27136,poiX=3694,poiY=-739,wowhead="https://www.wowhead.com/wotlk/quest=12281",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We must take solace in the fact that Slinkin's death, while tragic, was for the greater good. His discovery coupled with your heroics in the mine and the samples you returned brings us one step closer to understanding the Scourge war machine.$B$BTake this package to High Commander Halford Wyrmbane. It holds a sample of the strange ore and my analysis.",logDesc="Deliver Quarterflash's Package to High Commander Halford Wyrmbane at Wintergarde Keep."} end
if not DB[12282] then DB[12282]={id=12282,zoneId=65,name="Imprints on the Past",level=72,minLevel=71,giver="Zelig the Visionary",giverType="NPC",giverId=27314,ender="Zelig the Visionary",enderType="NPC",enderId=27314,rewardNextId=12287,poiX=3811,poiY=-812,wowhead="https://www.wowhead.com/wotlk/quest=12282",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The memories of the past haunt this land, $N. I hear the cries of the fallen echo across Northrend - calling to me.$B$BArthas left a terrible imprint on everything he touched. Only wither and decay remains in his wake. It is important, then, for us to study the past so that we may better know our enemy. Perhaps untold truths shall surface that could help in our campaign.$B$BFirst, you must recover my scrying orb from the town hall, $N. Exit this tower and turn left down the path to reach the town square.",logDesc="Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to recover his Scrying Orb.",choiceRewards={{id=37938,qty=1},{id=38025,qty=1},{id=38070,qty=1},{id=38086,qty=1}}} end
if not DB[12283] then DB[12283]={id=12283,zoneId=65,name="The Truth Will Out",level=72,minLevel=71,giver="Agent Skully",giverType="NPC",giverId=27350,ender="High Executor Wroth",enderType="NPC",enderId=27243,rewardNextId=12285,poiX=2825,poiY=-500,wowhead="https://www.wowhead.com/wotlk/quest=12283",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="We have to figure out what's going on here. We need the general's diary!$B$BI'm pretty sure that you'll find it on her nightstand upstairs at her house. It's the one next to church, across from the stables and the lumbermill.$B$BOnce you acquire the diary, take it to the high executor back at Venomspite.$B$BYou'll have to do this the old-fashioned way; the power of the mirror is low and there's only enough left for me.$B$B<The agent smirks.>",logDesc="Agent Skully has asked you to acquire The Diary of High General Abbendis and to deliver it to High Executor Wroth at Venomspite."} end
if not DB[12284] then DB[12284]={id=12284,zoneId=394,name="Keep 'Em on Their Heels",level=74,minLevel=73,giver="Commander Bargok",giverType="NPC",giverId=27451,ender="Commander Bargok",enderType="NPC",enderId=27451,poiX=4362,poiY=-2921,wowhead="https://www.wowhead.com/wotlk/quest=12284",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="We've suffered heavy casualties here, $r.$b$bThe only good news is that we've given as much as we've taken. I've requested more troops, but the bulk of our forces are bogged down in Venture Bay. It looks like we're on our own for now.$b$bNo matter how bad it gets, we MUST stand our ground! The precious resources of this region are essential to the Horde's long-term success in Northrend.$b$bWe've got to keep the Alliance on their heels until help arrives. Get out there and give 'em something to think about.",logDesc="Commander Bargok wants you to kill 15 Alliance units or players in Blue Sky Logging Ground."} end
if not DB[12285] then DB[12285]={id=12285,zoneId=65,name="Do Unto Others",level=73,minLevel=71,giver="High Executor Wroth",giverType="NPC",giverId=27243,ender="High Executor Wroth",enderType="NPC",enderId=27243,poiX=3209,poiY=-679,wowhead="https://www.wowhead.com/wotlk/quest=12285",image="assets/images/quests/placeholder.png",xpDiff=6,money=106000,desc="Their attack is imminent, $c. I need you to get in there and sever the head of the Scarlet Onslaught, literally!$B$BIt's not going to be easy... Abbendis is sure to be surrounded by a great many of her men. I suggest that you take at least a couple of friends along.$B$BBring back her head and I'll see to it that you're properly rewarded for saving Venomspite.$B$BFail and don't even bother to return!",logDesc="High Executor Wroth at Venomspite has ordered you to return with The Head of the High General.",choiceRewards={{id=38536,qty=1},{id=38537,qty=1},{id=38535,qty=1},{id=38534,qty=1}}} end
if not DB[12286] then DB[12286]={id=12286,zoneId=-22,name="Candy Bucket",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=12286",image="assets/images/quests/placeholder.png",xpDiff=3,rewards={{id=37586,qty=1}}} end
if not DB[12287] then DB[12287]={id=12287,zoneId=65,name="Orik Trueheart and the Forgotten Shore",level=72,minLevel=71,giver="Zelig the Visionary",giverType="NPC",giverId=27314,ender="Orik Trueheart",enderType="NPC",enderId=27347,rewardNextId=12290,poiX=3811,poiY=-812,wowhead="https://www.wowhead.com/wotlk/quest=12287",image="assets/images/quests/placeholder.png",xpDiff=2,desc="I have gazed upon the orb and seen the path that you must walk, $N.$B$BMany years ago an atrocity was committed upon the shores of Dragonblight. The act itself remains shrouded in darkness, but I am certain that your destiny lies south, amidst the ruins of the Forgotten Shore.$B$BTake the road southeast through the ravaged town square. Follow the trail until you arrive at Dawn's Reach. You will meet an old friend of mine there known as Orik Trueheart. He will be expecting you.",logDesc="Seek out the assistance of Orik Trueheart at Dawn's Reach in Dragonblight."} end
if not DB[12288] then DB[12288]={id=12288,zoneId=394,name="Overwhelmed!",level=74,minLevel=73,giver="Aumana",giverType="NPC",giverId=27464,ender="Aumana",enderType="NPC",enderId=27464,poiX=4371,poiY=-2887,wowhead="https://www.wowhead.com/wotlk/quest=12288",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="You there, $c! Help me!$b$bWe're losing valuable lives! There are simply too many wounded for me to tend to alone. If we can't get our soldiers healed we could be run out of Grizzly Hills altogether!$b$bTake this tourniquet and use it on the wounded down on the battlefield.$b$bHurry, $n! They're dyyying!!",logDesc="Aumana at Blue Sky Logging Grounds wants you to use the Renewing Tourniquet on 10 Wounded Skirmishers."} end
if not DB[12289] then DB[12289]={id=12289,zoneId=394,name="Kick 'Em While They're Down",level=74,minLevel=73,giver="Sergeant Hartsman",giverType="NPC",giverId=27468,ender="Sergeant Hartsman",enderType="NPC",enderId=27468,poiX=3981,poiY=-3177,wowhead="https://www.wowhead.com/wotlk/quest=12289",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="It is a dark day for the Alliance. Many good men lay dead or dying here. Our only consolation is that they fought well and brought down many of the enemy with them.$b$bWith the bulk of our forces committed to Venture Bay we stand alone to weather this storm. The resources in this region are vital to the Alliance and may well make the difference in our struggle against the Horde. We must not fail!$b$bGo, $n. Strike at them while they lick their wounds. Avenge your fallen brothers and keep our hopes alive!",logDesc="Sergeant Hartsman wants you to defeat 15 Horde units or players in Blue Sky Logging Grounds."} end
if not DB[12290] then DB[12290]={id=12290,zoneId=65,name="The Murkweed Elixir",level=72,minLevel=71,giver="Orik Trueheart",giverType="NPC",giverId=27347,ender="Orik Trueheart",enderType="NPC",enderId=27347,rewardNextId=12291,poiX=3425,poiY=-1262,wowhead="https://www.wowhead.com/wotlk/quest=12290",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The spirits of the damned haunt the coast. In life they were brave and noble soldiers of the Alliance, but in death they are cursed - bound to this world until the end of days. We must discover the source of their anguish if we are to free them!$B$BTo the southeast, on the Eldritch Heights, you will find a rare herb known as murkweed. It is murkweed that I will use to concoct an elixir that will allow you temporary entry into the world of the forgotten. Go now and gather the weed.",logDesc="Orik Trueheart at Dawn's Reach in Dragonblight wants you to recover 5 Murkweed from the Eldritch Heights."} end
if not DB[12291] then DB[12291]={id=12291,zoneId=65,name="The Forgotten Tale",level=72,minLevel=71,giver="Orik Trueheart",giverType="NPC",giverId=27347,ender="Orik Trueheart",enderType="NPC",enderId=27347,rewardNextId=12301,poiX=3425,poiY=-1262,wowhead="https://www.wowhead.com/wotlk/quest=12291",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The toxins in the murkweed elixir will render you unconscious. So powerful is the effect of the murkweed that even your spirit will be fooled, allowing you to temporarily enter the world of the dead.$B$BOnce a spirit, you must speak to the ghostly denizens of the Forgotten Shore. Seek out the cause of their anguish and return to me.$B$BRemember, $N, these spirits were once Alliance soldiers. Treat them with respect, honor and dignity.$B$BNow, with elixir in hand, venture south to the Forgotten Shore.",logDesc="Orik Trueheart at Dawn's Reach in Dragonblight wants you to hear the tales of a Forgotten Peasant, Forgotten Rifleman, Forgotten Knight and Forgotten Footman."} end
if not DB[12292] then DB[12292]={id=12292,zoneId=394,name="Local Support",level=74,minLevel=73,giver="Lieutenant Dumont",giverType="NPC",giverId=26875,ender="Lieutenant Dumont",enderType="NPC",enderId=26875,rewardNextId=12293,poiX=3411,poiY=-2782,wowhead="https://www.wowhead.com/wotlk/quest=12292",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We've reached a deadlock with the Horde in Grizzly Hills.  Our forces are just about evenly matched and all signs so far have pointed to a stalemate.$B$BUntil this morning, that is.  The local trappers have requested our help.  Apparently the Horde took something that belongs to them... a relic of some sort.$B$BWe get this back for them and they'll give us the edge we need.  Head to the Evergreen Trading Post, west of Conquest Hold and look for a cedar chest.",logDesc="Lieutenant Dumont at Amberpine Lodge wants you to go to Evergreen Trading Post and obtain the Cedar Chest.",choiceRewards={{id=38732,qty=1},{id=39030,qty=1},{id=39058,qty=1},{id=39096,qty=1},{id=38759,qty=1}}} end
if not DB[12293] then DB[12293]={id=12293,zoneId=394,name="Close the Deal",level=74,minLevel=73,giver="Lieutenant Dumont",giverType="NPC",giverId=26875,ender="Ivan",enderType="NPC",enderId=27469,rewardNextId=12294,poiX=3411,poiY=-2782,wowhead="https://www.wowhead.com/wotlk/quest=12293",image="assets/images/quests/placeholder.png",xpDiff=2,desc="We have what the trappers want.  Now it's up to us to sign them up with our side.$B$BTake the chest to a trapper named Ivan at the Aspen Grove Post, just north of here.$B$BIf all goes well, we'll have local woodsmen serving as scouts for the king's army in no time.",logDesc="Bring the Cedar Chest to Ivan at Aspen Grove Post."} end
if not DB[12294] then DB[12294]={id=12294,zoneId=394,name="A Tentative Pact",level=74,minLevel=73,giver="Ivan",giverType="NPC",giverId=27469,ender="Lieutenant Dumont",enderType="NPC",enderId=26875,rewardNextId=12295,poiX=3570,poiY=-2936,wowhead="https://www.wowhead.com/wotlk/quest=12294",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Very well, $N.  Your people kept their end of the bargain.$B$BTell Dumont that we'll honor the deal.",logDesc="Return to Lieutenant Dumont in Amberpine Lodge."} end
if not DB[12295] then DB[12295]={id=12295,zoneId=394,name="An Exercise in Diplomacy",level=74,minLevel=73,giver="Lieutenant Dumont",giverType="NPC",giverId=26875,ender="Envoy Ducal",enderType="NPC",enderId=26821,poiX=3411,poiY=-2782,wowhead="https://www.wowhead.com/wotlk/quest=12295",image="assets/images/quests/placeholder.png",xpDiff=3,desc="We'd been trying to negotiate with the trappers for weeks, but we'd gotten nowhere until you found that blasted chest of theirs.$B$BThis should be good news to our envoy in Silverbrook.  We sent Ducal there about a week ago and his last letter indicated he'd been making little progress.$B$BGo to Silverbrook and aid him in his diplomatic efforts.  Take the roads heading northwest of here and you should find it after crossing a couple of bridges. ",logDesc="Speak to Envoy Ducal in Silverbrook."} end
if not DB[12296] then DB[12296]={id=12296,zoneId=394,name="Life or Death",level=74,minLevel=73,giver="Rheanna",giverType="NPC",giverId=27484,ender="Rheanna",enderType="NPC",enderId=27484,poiX=4024,poiY=-3235,wowhead="https://www.wowhead.com/wotlk/quest=12296",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Oh, the carnage....$b$bI've been through many battles, $c, and this one was more brutal than any I've seen. Our fight with the Horde has become more intense than ever. It's them or us here in Northrend - life or death.$b$bIf we are to survive here another day we'll need to mend our wounded. There are too many for me to rescue alone.$b$bI've prepared special bandages that will enable you to assist me. Take one and tend to those who have not yet succumbed to their wounds.",logDesc="Rheanna at Blue Sky Logging Grounds wants you to use the Renewing Bandage on 10 Wounded Westfall Infantry units."} end
if not DB[12297] then DB[12297]={id=12297,zoneId=65,name="Of Traitors and Treason",level=72,minLevel=71,giver="Captain Adams",giverType="NPC",giverId=23749,ender="Greer Orehammer",enderType="NPC",enderId=23859,rewardNextId=12298,poiX=1333,poiY=-3143,wowhead="https://www.wowhead.com/wotlk/quest=12297",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of the Great Dragonblight.$B$BIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.$B$BHurry, $N. Show the document to Greer Orehammer here at Westguard Keep and explain the nature of your mission. He'll put you on his fastest gryphon to Wintergarde!",logDesc="Captain Adams has asked you to show the Alliance Missive to Greer Orehammer at Westguard Keep."} end
if not DB[12298] then DB[12298]={id=12298,zoneId=65,name="High Commander Halford Wyrmbane",level=72,minLevel=71,giver="Greer Orehammer",giverType="NPC",giverId=23859,ender="High Commander Halford Wyrmbane",enderType="NPC",enderId=27136,rewardNextId=12235,poiX=1344,poiY=-3288,wowhead="https://www.wowhead.com/wotlk/quest=12298",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Greer hands the missive back to you.>$B$BSkysong will take you to Wintergarde, $N. I guarantee you that it will be the fastest flight you've ever taken. Go now!$B",logDesc="Deliver the Alliance Missive to High Commander Halford Wyrmbane at Wintergarde Keep in eastern Dragonblight. $B"} end
if not DB[12299] then DB[12299]={id=12299,zoneId=394,name="Northern Hospitality",level=74,minLevel=73,giver="Sergei",giverType="NPC",giverId=27486,ender="Sergei",enderType="NPC",enderId=27486,poiX=4265,poiY=-2500,wowhead="https://www.wowhead.com/wotlk/quest=12299",image="assets/images/quests/placeholder.png",xpDiff=5,money=112000,desc="It's good to meet you.  Let us celebrate our pact by partaking in some good old fashioned Horde-killing.$B$BYou'll find marauders from Conquest Hold just outside our town, west of here.  Why don't you head out there and hunt them like the filthy animals they are?$B$BLet's see if our new allies can back all their talk with some action.",logDesc="Sergei at Silverbrook wants you to slay 8 Conquest Hold Marauders.",choiceRewards={{id=38762,qty=1},{id=38760,qty=1},{id=38761,qty=1}}} end
if not DB[12300] then DB[12300]={id=12300,zoneId=394,name="Test of Mettle",level=74,minLevel=73,giver="Sergei",giverType="NPC",giverId=27486,ender="Captured Trapper",enderType="NPC",enderId=27497,rewardNextId=12302,poiX=4265,poiY=-2500,wowhead="https://www.wowhead.com/wotlk/quest=12300",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Alright, friend.  You've done us a favor or two, but that's not the true test of a person's courage.$B$BAround these parts, you're not a real hunter unless you wear your prey's skin.$B$B<Sergei unsheathes his skinning knife and hands it to you.>$B$BThe leader of those motherless orcs attacking our town is called Bonesnap; you'll find him at a camp further northwest.$B$BThat's right.  You're going to skin the monster.",logDesc="Find Sergeant Bonesnap northwest of Silverbrook and pass the Test of Mettle."} end
if not DB[12301] then DB[12301]={id=12301,zoneId=65,name="The Truth Shall Set Us Free",level=72,minLevel=71,giver="Orik Trueheart",giverType="NPC",giverId=27347,ender="Orik Trueheart",enderType="NPC",enderId=27347,rewardNextId=12305,poiX=3425,poiY=-1262,wowhead="https://www.wowhead.com/wotlk/quest=12301",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Zelig gave this crystal ball to me years ago with specific instruction on its use. For five years - whenever I would feel anger, anxiety, or sorrow over the events that transpired here - I was to focus my thoughts upon the orb.$B$BI now understand why Zelig gave this crystal to me.$B$BTake my crystalline orb to the Forgotten Shore. Find the ruins of my old base on the upper reaches of the beach and place the orb in the center of town. Let the forgotten see the world through my heart and soul.",logDesc="Orik Trueheart at Dawn's Reach in Dragonblight wants you to use Orik's Crystalline Orb in the ruins located at the Forgotten Shore to redeem the Forgotten."} end
if not DB[12302] then DB[12302]={id=12302,zoneId=394,name="Words of Warning",level=74,minLevel=73,giver="Captured Trapper",giverType="NPC",giverId=27497,ender="Caged Prisoner",enderType="NPC",enderId=27499,poiX=4469,poiY=-2262,wowhead="https://www.wowhead.com/wotlk/quest=12302",image="assets/images/quests/placeholder.png",xpDiff=4,desc="Thanks for helping me, $N.  My name's Sasha.  Listen, I have to get the hell out of here.$B$BThe people that sent you here... my people... they've changed.  They're not good people anymore... and they want to turn you into one of... one of them.$B$BThis... 'test' they sent you on is just the beginning.$B$BHead to the northwestern end of Silverbrook.  You'll find something of interest to you.$B$BGood luck... and trust no one.",logDesc="Go to the northwestern end of Silverbrook."} end
if not DB[12303] then DB[12303]={id=12303,zoneId=65,name="Funding the War Effort",level=72,minLevel=71,giver="Quartermaster Bartlett",giverType="NPC",giverId=27267,ender="Quartermaster Bartlett",enderType="NPC",enderId=27267,poiX=3209,poiY=-634,wowhead="https://www.wowhead.com/wotlk/quest=12303",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="<The quartermaster lowers his voice and whispers to you.>$B$B$C, I need your help; our coffers are empty. The Kor'kron Vanguard at the Wrath Gate has taken all of our coin for the fight there.$B$BBut, I've heard whispers that there's treasure to be had amongst the wrecks on the Forgotten Shore to the southeast.$B$BWe have to do something soon, or we won't be able to continue the fight against the Scarlet Onslaught. War isn't cheap, you know!",logDesc="Quartermaster Bartlett at Venomspite has asked you to recover 6 Forgotten Treasure.",choiceRewards={{id=38181,qty=1},{id=38071,qty=1},{id=37986,qty=1},{id=38030,qty=1},{id=38036,qty=1}}} end
if not DB[12304] then DB[12304]={id=12304,zoneId=65,name="Beachfront Property",level=72,minLevel=71,giver="Surveyor Hansen",giverType="NPC",giverId=32599,ender="Surveyor Hansen",enderType="NPC",enderId=32599,poiX=3142,poiY=-823,wowhead="https://www.wowhead.com/wotlk/quest=12304",image="assets/images/quests/placeholder.png",xpDiff=5,money=50000,desc="It's time for Venomspite to expand!$B$BWe'll take care of the Onslaught in due time, but I want you to spearhead our efforts on the Forgotten Shore. The property value has outstanding potential and just look at that view!$B$BUnfortunately, there's an infestation of human ghosts, shipwrecked crews and the like who haven't quite realized that they're dead.$B$BClear the beach and the waters off the shore, and maybe you and I will talk about building a cozy, new mausoleum down there soon.",logDesc="Surveyor Hansen, just north of the Forgotten Shore, has asked you to slay 20 Forgotten ghosts."} end
if not DB[12305] then DB[12305]={id=12305,zoneId=65,name="Parting Thoughts",level=72,minLevel=71,giver="Orik Trueheart",giverType="NPC",giverId=27347,ender="Zelig the Visionary",enderType="NPC",enderId=27314,rewardNextId=12475,poiX=3425,poiY=-1262,wowhead="https://www.wowhead.com/wotlk/quest=12305",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You have honored me and honored the memory of hundreds of Alliance veterans, $N. Zelig was wise in sending you here. Please return to him and give him my thanks. He will be happy to hear of the events that transpired at the Forgotten Shore.$B$BI do not have the gift of foresight like Zelig, but I am certain that great things await you, friend.$B$BFarewell. $B",logDesc="Return to Zelig the Visionary at Wintergarde Keep in Dragonblight.",choiceRewards={{id=38181,qty=1},{id=38071,qty=1},{id=37986,qty=1},{id=38030,qty=1},{id=38036,qty=1}}} end
if not DB[12306] then DB[12306]={id=12306,zoneId=-370,name="Brew of the Month Club",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=12306",image="assets/images/quests/placeholder.png",desc="There is strength in numbers, $n.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.$b$bBring your \"Brew of the Month\" club membership form to Ray'ma in the Darkbriar Lodge in Orgrimmar's Valley of Spirits.",logDesc="Bring the \"Brew of the Month\" club membership form to Ray'ma in the Darkbriar Lodge in Orgrimmar's Valley of Spirits."} end
if not DB[12307] then DB[12307]={id=12307,zoneId=394,name="Wolfsbane Root",level=74,minLevel=73,giver="Katja",giverType="NPC",giverId=27545,ender="Katja",enderType="NPC",enderId=27545,poiX=4351,poiY=-2455,wowhead="https://www.wowhead.com/wotlk/quest=12307",image="assets/images/quests/placeholder.png",xpDiff=5,money=44000,desc="Have you heard of the wolfsbane plant?  It is a horrible weed... it destroys our farmable crops.$B$BWe spent all of last week cutting them down, but the roots are beginning to sprout again.$B$BIt might not seem like an urgent matter, but a resurgence of the plant could be a real... disaster.  Do you think you could help us by uprooting them where you find them near the village?",logDesc="Katja in Silverbrook wants you to uproot 8 Wolfsbane Roots.",choiceRewards={{id=39062,qty=1},{id=39105,qty=1},{id=38754,qty=1},{id=38756,qty=1}}} end
if not DB[12308] then DB[12308]={id=12308,zoneId=394,name="Escape from Silverbrook",level=74,minLevel=73,giver="Caged Prisoner",giverType="NPC",giverId=27499,ender="Lieutenant Dumont",enderType="NPC",enderId=26875,rewardNextId=12310,poiX=4406,poiY=-2499,wowhead="https://www.wowhead.com/wotlk/quest=12308",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You... you're not one of them?  Quick!  Let me out!$B$BWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!",logDesc="Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook.  Report to Lieutenant Dumont when you reach Amberpine Lodge.",choiceRewards={{id=38733,qty=1},{id=39031,qty=1},{id=39059,qty=1},{id=39097,qty=1},{id=38750,qty=1}}} end
if not DB[12309] then DB[12309]={id=12309,zoneId=65,name="Find Durkon!",level=72,minLevel=71,giver="High Commander Halford Wyrmbane",giverType="NPC",giverId=27136,ender="Cavalier Durkon",enderType="NPC",enderId=27318,rewardNextId=12311,poiX=3768,poiY=-775,wowhead="https://www.wowhead.com/wotlk/quest=12309",image="assets/images/quests/placeholder.png",xpDiff=1,desc="After the Scourge breached the south wall, I ordered Cavalier Durkon to investigate the town crypt. Moments ago I was handed his report.$B$BThe undead that plague us are coming from two sources: the ruins of Wintergarde, now a breeding ground for Scourge, and our very own town crypt! Amidst the chaos and confusion the Scourge managed to get a necrolord inside the crypt.$B$BIn his message, Durkon requested assistance. You will find him and help him, $N. The crypt is on the western border of the town square.",logDesc="Seek out Cavalier Durkon at the Wintergarde Crypt in Dragonblight.$B"} end
if not DB[12310] then DB[12310]={id=12310,zoneId=394,name="A Swift Response",level=74,minLevel=73,giver="Lieutenant Dumont",giverType="NPC",giverId=26875,ender="Lieutenant Dumont",enderType="NPC",enderId=26875,poiX=3411,poiY=-2782,wowhead="https://www.wowhead.com/wotlk/quest=12310",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Our response must be immediate.  Decisive.  We must teach these savages not to cross us.$B$BOur scouts have located what's left of the Silverbrook trappers... you know, the ones you didn't get to douse in flames.  Apparently they're blockading the road to the southeast... perhaps they're trying to box us in.$B$BHead to the Forest's Edge post and take care of them.  Their leader's reported to be a man named Vladek... make sure he's dealt with.",logDesc="Lieutenant Dumont wants you to go to Forest's Edge Post and slay Vladek and 7 Silverbrook Hunters."} end
if not DB[12311] then DB[12311]={id=12311,zoneId=65,name="The Noble's Crypt",level=72,minLevel=71,giver="Cavalier Durkon",giverType="NPC",giverId=27318,ender="Cavalier Durkon",enderType="NPC",enderId=27318,poiX=3585,poiY=-807,wowhead="https://www.wowhead.com/wotlk/quest=12311",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Held within the cold stone walls of this crypt are the remains of the nobles and dignitaries that died in Northrend. At its very core now sits a necrolord who raises the corpses as servants of the Scourge.$B$BYou must make your way to the bottom of the Wintergarde Crypt and kill Necrolord Amarion. Only then will the assault from within cease!$B$BAnd $N, be on the lookout for any information that might be laying about inside the room where Amarion resides. $B",logDesc="Cavalier Durkon at Wintergarde Keep wants you to slay Necrolord Amarion.",choiceRewards={{id=37953,qty=1},{id=37995,qty=1},{id=38039,qty=1},{id=38100,qty=1}}} end
if not DB[12312] then DB[12312]={id=12312,zoneId=65,name="Secrets of the Scourge",level=73,minLevel=71,ender="Cavalier Durkon",enderType="NPC",enderId=27318,rewardNextId=12319,wowhead="https://www.wowhead.com/wotlk/quest=12312",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Scrawled across the flesh-bound chapters of this tome are strange symbols and shapes that seem to have been scraped into the pages with a blade. You have no idea what is written, but you are certain that whatever it is, it must be important.$B$BDeliver the tome to Cavalier Durkon standing guard topside at Wintergarde Crypt.",logDesc="Deliver the Flesh-bound Tome to Cavalier Durkon at Wintergarde Keep in Dragonblight."} end
if not DB[12313] then DB[12313]={id=12313,zoneId=-22,name="UNUSED Save Brewfest!",level=-1,minLevel=65,rewardNextId=12062,wowhead="https://www.wowhead.com/wotlk/quest=12313",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Save Brewfest!  Talk to the Brewfest spy in the Grim Guzzler of Blackrock Depths.",logDesc="Talk to the Brewfest spy in the Grim Guzzler of Blackrock Depths.$B"} end
if not DB[12314] then DB[12314]={id=12314,zoneId=394,name="Down With Captain Zorna!",level=74,minLevel=73,giver="Baron Freeman",giverType="NPC",giverId=27520,ender="Baron Freeman",enderType="NPC",enderId=27520,poiX=2674,poiY=-2275,wowhead="https://www.wowhead.com/wotlk/quest=12314",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="The Horde's forces are poised to break through our lines and complete their conquest of Venture Bay if we do not act. The Horde's forces in the port are commanded by Captain Zorna, near the ship on the far side of the bay.$B$BIf you can defeat her, the Horde's offensive will falter and we can seize the chance to capture the port. Beware, $N, for Zorna is a fierce fighter. It may take several people to defeat her, or if you have access to a repaired shredder, you might try using it to your advantage.",logDesc="Slay Captain Zorna and report to Baron Freeman at Venture Bay.",rewards={{id=37836,qty=10}}} end
if not DB[12315] then DB[12315]={id=12315,zoneId=394,name="Crush Captain Brightwater!",level=74,minLevel=73,giver="General Khazgar",giverType="NPC",giverId=27532,ender="General Khazgar",enderType="NPC",enderId=27532,poiX=2814,poiY=-1638,wowhead="https://www.wowhead.com/wotlk/quest=12315",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="With every advance, our men are met by fresh Alliance reinforcements. It's almost as though their commander anticipates my every move!$B$BThe time has come for good Captain Brightwater to meet his end. He commands his troops from aboard an Alliance destroyer at the far end of the bay.$B$BThis will be no easy fight, $N. Take along a couple of trusted friends, or if you have a key to one of those repaired shredders, use it to disembowel Brightwater! Either way, he must fall!",logDesc="Slay Captain Brightwater and report to General Khazgar at Venture Bay.",rewards={{id=37836,qty=10}}} end
if not DB[12316] then DB[12316]={id=12316,zoneId=394,name="Keep Them at Bay!",level=74,minLevel=73,giver="Lieutenant Stuart",giverType="NPC",giverId=27562,ender="Lieutenant Stuart",enderType="NPC",enderId=27562,poiX=2673,poiY=-2272,wowhead="https://www.wowhead.com/wotlk/quest=12316",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="We cannot permit the Horde to control Venture Bay. The port is essential to our operations in Grizzly Hills and beyond.$B$BCaptain Stoutmantle has taken the rest of the Westfall Brigade east in search of a passage through the mountains, so we'll have no reinforcements.$B$BGo into the field, $N, and kill the Conquest Hold berserkers the Horde has sent against us. Cut them down until none remain standing. The Alliance must have this port!",logDesc="Defeat 10 Horde units or players in Venture Bay and return to Lieutenant Stuart.",rewards={{id=37836,qty=10}}} end
if not DB[12317] then DB[12317]={id=12317,zoneId=394,name="Keep Them at Bay",level=74,minLevel=73,giver="Centurion Kaggrum",giverType="NPC",giverId=27563,ender="Centurion Kaggrum",enderType="NPC",enderId=27563,poiX=2810,poiY=-1642,wowhead="https://www.wowhead.com/wotlk/quest=12317",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="This wretched Westfall Brigade is proving a tougher opponent than we'd thought. Though few in number, they fight well and bravely, but we cannot afford to wait them out.$B$BConqueror Krenna's orders were to capture the port quickly. You must break the stalemate, $N. Find the enemy's marines and slaughter them until the resistance ceases. Only then will we be able to claim ownership of the port.$B$BGo quickly. We don't want to keep Conqueror Krenna waiting.",logDesc="Defeat 10 Alliance units or players in Venture Bay and return to Centurion Kaggrum.",rewards={{id=37836,qty=10}}} end
if not DB[12318] then DB[12318]={id=12318,zoneId=-370,name="Save Brewfest!",level=-1,minLevel=75,rewardNextId=12062,wowhead="https://www.wowhead.com/wotlk/quest=12318",image="assets/images/quests/placeholder.png",xpDiff=1,desc="$n, our spies have discovered a fiendish plot!  The Dark Iron dwarves want our beloved Brewfest destroyed!$B$BCoren Direbrew, head of a renegade family of brewers, has marshaled the dwarves of Blackrock Depths.  Their vile mole machines attack us constantly.$B$BOur spy is in the Grim Guzzler, a tavern in the bowels of Blackrock Depths.  He'll know more of Direbrew's plot.$B$BFind our spy.  Save Brewfest!",logDesc="Speak with the Brewfest Spy in the Grim Guzzler of Blackrock Depths.$B"} end
if not DB[12319] then DB[12319]={id=12319,zoneId=65,name="Mystery of the Tome",level=73,minLevel=71,giver="Cavalier Durkon",giverType="NPC",giverId=27318,ender="High Commander Halford Wyrmbane",enderType="NPC",enderId=27136,rewardNextId=12320,poiX=3585,poiY=-807,wowhead="https://www.wowhead.com/wotlk/quest=12319",image="assets/images/quests/placeholder.png",xpDiff=1,desc="What can it be, $N? That was certainly no ordinary curse that the blasted lich put on you!$B$B<Durkon flips through the grisly pages of the tome.>$B$BI don't even know if I'm looking at it the right way. We must find out what information is held within this tome!$B$B<Durkon hands the book back to you.>$B$BThe High Commander will know what to do. Take the flesh-bound tome to him and tell him exactly what happened here.",logDesc="Take the Flesh-bound Tome to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight."} end
if not DB[12320] then DB[12320]={id=12320,zoneId=65,name="Understanding the Language of Death",level=73,minLevel=71,giver="High Commander Halford Wyrmbane",giverType="NPC",giverId=27136,ender="Inquisitor Hallard",enderType="NPC",enderId=27316,poiX=3768,poiY=-775,wowhead="https://www.wowhead.com/wotlk/quest=12320",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Take the book and follow the path leading up to the barracks. Once inside the barracks take the staircase down to the prison. At the prison you will find Inquisitor Hallard and our mayor, Godfrey. I believe Godfrey might be the missing piece of this puzzle and Hallard the man to put it all together.$B$BGo now!",logDesc="Take the Flesh-bound Tome to Inquisitor Hallard at the Wintergarde Keep prison."} end
if not DB[12321] then DB[12321]={id=12321,zoneId=65,name="A Righteous Sermon",level=73,minLevel=71,giver="Inquisitor Hallard",giverType="NPC",giverId=27316,ender="High Commander Halford Wyrmbane",enderType="NPC",enderId=27136,poiX=3798,poiY=-677,wowhead="https://www.wowhead.com/wotlk/quest=12321",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Godfrey Goodard, once a righteous man and mayor of Wintergarde, is now an agent of the Scourge. His transformation from man to undying ghoul has taken place slowly, over time. He hears the call of the Lich King now and lives only to serve his master.$B$BBut as with all Scourge, Godfrey knows the language of death and with proper motivation, will tell us what we need to know about the tome.$B$BOnce you hear what you need to hear, return to the High Commander at the front lines. I'll clean up here as needed.",logDesc="Wait for Inquisitor Hallard to finish his Righteous Sermon and return to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight with the information you uncover.",choiceRewards={{id=37950,qty=1},{id=37993,qty=1},{id=38037,qty=1},{id=38068,qty=1}}} end
if not DB[12323] then DB[12323]={id=12323,zoneId=394,name="Smoke 'Em Out",level=74,minLevel=73,giver="Sergeant Downey",giverType="NPC",giverId=27602,ender="Sergeant Downey",enderType="NPC",enderId=27602,poiX=2691,poiY=-2265,wowhead="https://www.wowhead.com/wotlk/quest=12323",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="There are still pockets of cowardly Venture Company men holed up in some of the buildings at the center of Venture Bay. I need every man I can spare out there fighting against the Horde, but we can't allow those Venture Company stragglers to camp out in those buildings, either.$B$BMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; they probably bite.",logDesc="Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Sergeant Downey.",rewards={{id=37836,qty=10}}} end
if not DB[12324] then DB[12324]={id=12324,zoneId=394,name="Smoke 'Em Out",level=74,minLevel=73,giver="Stone Guard Ragetotem",giverType="NPC",giverId=27606,ender="Stone Guard Ragetotem",enderType="NPC",enderId=27606,poiX=2831,poiY=-1708,wowhead="https://www.wowhead.com/wotlk/quest=12324",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Not only is this port infested with sniveling Alliance cowards, but to make matters worse, there are still Venture Company employees holed up in some of the buildings. They're not worth the time it takes to kill and I can't spare the warriors anyway.$B$BMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; there's no telling what diseases they're carrying.",logDesc="Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Stone Guard Ragetotem.",rewards={{id=37836,qty=10}}} end
if not DB[12325] then DB[12325]={id=12325,zoneId=65,name="Into Hostile Territory",level=73,minLevel=71,giver="High Commander Halford Wyrmbane",giverType="NPC",giverId=27136,ender="Duke August Foehammer",enderType="NPC",enderId=27157,rewardNextId=12326,poiX=3768,poiY=-775,wowhead="https://www.wowhead.com/wotlk/quest=12325",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You have done much to advance our efforts against the Scourge, $N. In fact, the morale of all those who have come into contact with you soars! Such is your influence over the soldiers and citizenry of Wintergarde, ally.$B$BAnd because of you we are now prepared to go on the offensive! You are to report to Duke August Foehammer, across the Carrion Fields at Thorson's Post, east of here. Gryphon Commander Urik at the gryphon station has prepared a special gryphon to drop you behind enemy lines. Go now!",logDesc="Speak with Gryphon Commander Urik to secure a ride to Thorson's Post. Report to Duke August Foehammer when you arrive at Thorson's Post in Dragonblight.$B"} end
if not DB[12326] then DB[12326]={id=12326,zoneId=65,name="Steamtank Surprise",level=73,minLevel=71,giver="Duke August Foehammer",giverType="NPC",giverId=27157,ender="Ambo Cash",enderType="NPC",enderId=1293,rewardNextId=12455,poiX=3841,poiY=-1402,wowhead="https://www.wowhead.com/wotlk/quest=12326",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This is a seek and destroy mission. You'll be driving a tank into the Carrion Fields to dismantle Scourge plague wagons. With the tank comes a crew of three 7th Legion soldiers. All must survive if this mission is to succeed!$B$BYou'll need to get in close to a plague wagon to unleash your engineer. Let them do their deed and move on to the next one. When the field is clear of plague wagons, head to the mausoleum in front of the ruined keep and drop off the rest of your crew. Meet with Ambo Cash inside.",logDesc="Use an Alliance Steam Tank to destroy 6 Plague Wagons and deliver the 7th Legion Elites to Wintergarde Mausoleum. Speak with Ambo Cash inside the Wintergarde Mausoleum in Dragonblight should you succeed.",choiceRewards={{id=37992,qty=1},{id=37949,qty=1},{id=38284,qty=1}}} end
if not DB[12327] then DB[12327]={id=12327,zoneId=394,name="Out of Body Experience",level=75,minLevel=73,giver="Ruuna the Blind",giverType="NPC",giverId=27581,ender="Ruuna the Blind",enderType="NPC",enderId=27581,rewardNextId=12329,poiX=3837,poiY=-3422,wowhead="https://www.wowhead.com/wotlk/quest=12327",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Ah, you seek a vision of the past.  You're a wise $r.$B$BEvery time someone drops by for a reading, they seem to always ask about the future.  When you get to be my age, you learn that scrying the past, more often than not, is more useful.$B$BDrink this potion and peer into my crystal ball.  Let us see what knowledge we can obtain.",logDesc="Drink the Gossamer Potion near Ruuna's Crystal Ball and witness the Vision from the Past."} end
if not DB[12328] then DB[12328]={id=12328,zoneId=394,name="Ruuna's Request",level=75,minLevel=73,giver="Ruuna the Blind",giverType="NPC",giverId=27581,ender="Ruuna the Blind",enderType="NPC",enderId=27581,rewardNextId=12327,poiX=3837,poiY=-3422,wowhead="https://www.wowhead.com/wotlk/quest=12328",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I will not charge you gold for my services, for I can foresee that your actions are necessary and much hinges on what you learn today.$B$BI will, however, ask you to collect a reagent for me.  Obtain gossamer dust from the fern feeder moths northeast of here.  Do this and I will prepare a potion that will take you to the time and place where the events took place that you need to witness.",logDesc="Ruuna the Blind wants you to obtain 4 handfuls of Gossamer Dust.",choiceRewards={{id=38727,qty=1},{id=39026,qty=1},{id=39054,qty=1},{id=39092,qty=1}}} end
if not DB[12329] then DB[12329]={id=12329,zoneId=394,name="Fate and Coincidence",level=75,minLevel=73,giver="Ruuna the Blind",giverType="NPC",giverId=27581,ender="Sasha",enderType="NPC",enderId=26935,poiX=3837,poiY=-3422,wowhead="https://www.wowhead.com/wotlk/quest=12329",image="assets/images/quests/placeholder.png",xpDiff=2,desc="There are two types of people in this world, $N.  Those who believe in coincidence and those who don't.$B$BOn the day I lost my eyesight I was given the gift of clairvoyance.  I suppose you can guess what sort of person I am.$B$BEarlier today, a young woman named Sasha was granted the same vision you were.  You will want to talk to her.$B$BYou'll find her directly east of here at the White Pine Trading Post, on the way to Solstice Village.",logDesc="Speak to Sasha at the White Pine Trading Post."} end
if not DB[12330] then DB[12330]={id=12330,zoneId=394,name="Anatoly Will Talk",level=75,minLevel=73,giver="Sasha",giverType="NPC",giverId=26935,ender="Sasha",enderType="NPC",enderId=26935,poiX=4073,poiY=-4130,wowhead="https://www.wowhead.com/wotlk/quest=12330",image="assets/images/quests/placeholder.png",xpDiff=4,desc="My sister is here somewhere, and I can't seem to get this monster to talk.$B$BHe doesn't seem to care about his own well-being, but I've an idea.  I knew Anatoly's wife, Tatjana, from before the wolfcult arrived -- she was a horse-handler.$B$BTake this tranquillizer dart.  Bring her back alive, we're going to need her if we're to have any leverage with Anatoly.$B$BI will help you find the person behind all this once we save my sister.",logDesc="Sasha at the White Pine Trading Post wants you to take the Tranquilizer Dart and use it on Tatjana in Solstice Village.  Bring Tatjana back to the White Pine Trading Post.",choiceRewards={{id=38744,qty=1},{id=38752,qty=1},{id=38748,qty=1}}} end
if not DB[12331] then DB[12331]={id=12331,zoneId=-22,name="Candy Bucket",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=12331",image="assets/images/quests/placeholder.png",xpDiff=3,rewards={{id=37586,qty=1}}} end
