if not DB[12372] then DB[12372]={id=12372,zoneId=65,name="Defending Wyrmrest Temple",level=74,minLevel=71,giver="Lord Afrasastrasz",giverType="NPC",giverId=27575,ender="Lord Afrasastrasz",enderType="NPC",enderId=27575,poiX=3544,poiY=305,wowhead="https://www.wowhead.com/wotlk/quest=12372",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Emboldened by the overabundance of magic now flowing through the Azure Dragonshrine, the blue dragonflight has dared to attack Wyrmrest Temple itself!$B$BI ask that you ride one of our defenders into battle to slay their dragons and drakes, and to attack the eruption of ley line energies at the dragonshrine itself in order to destabilize it.$B$BOutside on the east and west terraces are wyrmrest defenders. Speak with one to ride it into battle.$B$BWithout your help, $N, we will surely lose.",logDesc="Afrasastrasz at Wyrmrest Temple has asked you to slay 3 Azure Dragons, slay 5 Azure Drakes, and to destabilize the Azure Dragonshrine while riding a Wyrmrest Defender into battle."} end
