if not DB[12411] then DB[12411]={id=12411,zoneId=394,name="A Sister's Pledge",level=75,minLevel=73,giver="Sasha",giverType="NPC",giverId=26935,ender="Anya",enderType="NPC",enderId=27646,poiX=4073,poiY=-4130,wowhead="https://www.wowhead.com/wotlk/quest=12411",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Please, $N.  I know it is Arugal you're after.  I swear on my father's memory I will help you take him down.$B$BBut I must beg you... Anya is completely innocent, we cannot leave her with these savages.$B$BHelp me rescue my sister and you'll have me at your side when you face Arugal.$B$BI know the den Anatoly spoke of.  We'll find it on the other side of this hill.  Let's go, my sister's in danger.",logDesc="Look for Anya in the Duskhowl Den near Solstice Village."} end
if not DB[12412] then DB[12412]={id=12412,zoneId=394,name="My Enemy's Friend",level=75,minLevel=73,giver="Conqueror Krenna",giverType="NPC",giverId=26860,ender="Conqueror Krenna",enderType="NPC",enderId=26860,rewardNextId=12413,poiX=3271,poiY=-2197,wowhead="https://www.wowhead.com/wotlk/quest=12412",image="assets/images/quests/placeholder.png",xpDiff=5,desc="If there is one thing I can get through your head, let it be this: the Alliance will be crushed in the Grizzly Hills.$B$BThere is far too much lumber, ore, game and strategic territory for us to give up on any single battlefront here.$B$BSo far we've been successful... but there's something that could tip the scales in our enemy's favor.$B$BFar to the east  of here, at the Forest Edge's Post, local trappers seek to join the Alliance.  Slaughter them before they have the chance to do so.",logDesc="Conqueror Krenna in Conquest Hold wants you to slay 8 Silverbrook Hunters and their leader, Vladek, at the Forest's Edge Post.",choiceRewards={{id=38732,qty=1},{id=39030,qty=1},{id=39058,qty=1},{id=39096,qty=1},{id=38759,qty=1}}} end
if not DB[12413] then DB[12413]={id=12413,zoneId=394,name="Attack on Silverbrook",level=74,minLevel=73,giver="Conqueror Krenna",giverType="NPC",giverId=26860,ender="Conqueror Krenna",enderType="NPC",enderId=26860,rewardNextId=12427,poiX=3271,poiY=-2197,wowhead="https://www.wowhead.com/wotlk/quest=12413",image="assets/images/quests/placeholder.png",xpDiff=5,desc="A few hours ago, the trappers were nothing but peasants threatening to add their number to the Alliance's.$B$BNow they've become something else... an uncertainty.  I do not like uncertainties.  Go to the hills outside their main town in northern Grizzly Hills, Silverbrook, and help my men crush them.",logDesc="Conqueror Krenna at Conquest Hold wants you to slay 8 Silverbrook Defenders in the Silverbrook Hills.",choiceRewards={{id=38733,qty=1},{id=39031,qty=1},{id=39059,qty=1},{id=39097,qty=1},{id=38750,qty=1}}} end
if not DB[12414] then DB[12414]={id=12414,zoneId=394,name="Mounting Up",level=75,minLevel=73,giver="Squire Percy",giverType="NPC",giverId=26377,ender="Squire Percy",enderType="NPC",enderId=26377,poiX=4585,poiY=-4212,wowhead="https://www.wowhead.com/wotlk/quest=12414",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Cap'n Stoutmantle left most of our calvary... cavlary... uh, horsemen at the fight for Venture Bay.$B$BWe chose a good place to put the camp 'cause there are tons of highland mustangs running around near here and in the Boulder Hills to the northeast. The Cap'n put me in charge of capturing some of 'em.$B$BWill you help? I've got a stick and some string, and there are loads of wild carrots growing near the camp. Pick the carrots and use them with the stick to lure in the mustang, then ride it back here.",logDesc="Ride 5 Highland Mustangs back to Squire Percy at the Westfall Brigade Encampment."} end
if not DB[12415] then DB[12415]={id=12415,zoneId=394,name="The Horse Hollerer",level=75,minLevel=73,giver="Soulok Stormfury",giverType="NPC",giverId=26944,ender="Soulok Stormfury",enderType="NPC",enderId=26944,poiX=3841,poiY=-4523,wowhead="https://www.wowhead.com/wotlk/quest=12415",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="The Alliance's 'Westfall Brigade' is camped far to the north, near Thor Modan. They have foolishly divided their forces to contest our control of Venture Bay, and they have been left without cavalry.$B$BThey're now trying to capture and tame the wild highland mustangs that roam the area around the Westfall Brigade Encampment and Boulder Hills. We must stop them before they're able to replace their lost mounts. Take this and throw it near the horses to drive them away.",logDesc="Scare 15 Highland Mustangs and return to Soulok Stormfury at Camp Oneqwah."} end
if not DB[12416] then DB[12416]={id=12416,zoneId=65,name="Heated Battle",level=74,minLevel=71,giver="Ceristrasz",giverType="NPC",giverId=27506,ender="Ceristrasz",enderType="NPC",enderId=27506,rewardNextId=12417,poiX=3704,poiY=699,wowhead="https://www.wowhead.com/wotlk/quest=12416",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, $r.$B$BCaptain Iskandar leads a group of your kind in stemming the flow of the Scourge out of the shrine.$B$BGo to his aid... but please stay behind his men. The flow of Scourge is endless and I don't want to lose you in one of those scarred canyons.",logDesc="Aid Captain Iskandar in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker.$B$BReturn to Ceristrasz once you have finished this task."} end
if not DB[12417] then DB[12417]={id=12417,zoneId=65,name="Return to the Earth",level=74,minLevel=71,giver="Ceristrasz",giverType="NPC",giverId=27506,ender="Ceristrasz",enderType="NPC",enderId=27506,rewardNextId=12418,poiX=3704,poiY=699,wowhead="https://www.wowhead.com/wotlk/quest=12417",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks.$B$BGet into the shrine through one of the other passes to the south or north... the Scourge presence should be lighter there.$B$BSearch the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.",logDesc="Enter the Ruby Dragonshrine through one of the northern or southern passes and search for Ruby Acorns.  Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth.  Return to Ceristrasz once the task is complete."} end
if not DB[12418] then DB[12418]={id=12418,zoneId=65,name="Through Fields of Flame",level=75,minLevel=71,giver="Ceristrasz",giverType="NPC",giverId=27506,ender="Ceristrasz",enderType="NPC",enderId=27506,rewardNextId=12768,poiX=3704,poiY=699,wowhead="https://www.wowhead.com/wotlk/quest=12418",image="assets/images/quests/placeholder.png",xpDiff=6,money=118000,desc="I have one final task for you, $r... one that should turn the tide of this fight.$B$BReturn to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine.$B$BI also need you to find the source of the corruption under the shrine and put an end to it.$B$BI know I have asked a lot of you, but if you do this for me, we will win this battle.",logDesc="Enter the Ruby Dragonshrine through one of the northern or southern passes, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Ceristrasz once the task is complete.",choiceRewards={{id=37962,qty=1},{id=38004,qty=1},{id=38046,qty=1},{id=38108,qty=1}}} end
if not DB[12419] then DB[12419]={id=12419,zoneId=65,name="The Fate of the Ruby Dragonshrine",level=75,minLevel=71,ender="Krasus",enderType="NPC",enderId=27990,wowhead="https://www.wowhead.com/wotlk/quest=12419",image="assets/images/quests/placeholder.png",xpDiff=2,money=15000,desc="As you pick up the brooch, its faint glow brightens slightly.$B$BKrasus will want to know of Dahlia's fate. Take the brooch to him at Wyrmrest.",logDesc="Bring Dahlia Suntouch's Ruby Brooch to Krasus in the Ruling Council Chamber at Wyrmrest and inform him of Dahlia's fate."} end
if not DB[12420] then DB[12420]={id=12420,zoneId=-370,name="Brew of the Month Club",level=-1,minLevel=1,ender="Larkin Thunderbrew",enderType="NPC",enderId=27478,wowhead="https://www.wowhead.com/wotlk/quest=12420",image="assets/images/quests/placeholder.png",desc="Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.$b$bBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.",logDesc="Bring the \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge."} end
if not DB[12421] then DB[12421]={id=12421,zoneId=-370,name="Brew of the Month Club",level=-1,minLevel=1,ender="Ray'ma",enderType="NPC",enderId=27489,wowhead="https://www.wowhead.com/wotlk/quest=12421",image="assets/images/quests/placeholder.png",desc="There is strength in numbers, $n.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.$b$bBring your \"Brew of the Month\" club membership form to Ray'ma in the Darkbriar Lodge in Orgrimmar's Valley of Spirits.",logDesc="Bring the \"Brew of the Month\" club membership form to Ray'ma in the Darkbriar Lodge in Orgrimmar's Valley of Spirits."} end
if not DB[12422] then DB[12422]={id=12422,zoneId=394,name="Tactical Clemency",level=74,minLevel=73,giver="Gorgonna",giverType="NPC",giverId=27102,ender="Captured Trapper",enderType="NPC",enderId=27497,rewardNextId=12427,poiX=3271,poiY=-2197,wowhead="https://www.wowhead.com/wotlk/quest=12422",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Listen, $N.  I need you to act with discretion and speed.$B$BOne of Krenna's top sergeants has captured a trapper outcast outside of Silverbrook.  Now, if things turn out the way they usually do, the prisoner is going to be executed before the day is over.$B$BWe can't let that happen.  You see, the prisoner matches the description of Mikhail's older daughter in his diary.$B$BIf we set her loose and follow her closely, she'll lead us to whoever's controlling the trappers.  Take this letter to her.",logDesc="Deliver the Letter of Amnesty to the Captured Trapper in Silverbrook Hills."} end
if not DB[12423] then DB[12423]={id=12423,zoneId=394,name="Mikhail's Journal",level=74,minLevel=73,ender="Conqueror Krenna",enderType="NPC",enderId=26860,rewardNextId=12424,wowhead="https://www.wowhead.com/wotlk/quest=12423",image="assets/images/quests/placeholder.png",xpDiff=3,desc="From what you can gather, this journal was written by a denizen of Silverbrook named Mikhail.$B$BIt is written in some variant of the common human tongue.  Perhaps you should bring this back to Conqueror Krenna.",logDesc="Bring Mikhail's Journal to Conqueror Krenna in Conquest Hold."} end
if not DB[12424] then DB[12424]={id=12424,zoneId=394,name="Gorgonna",level=74,minLevel=73,giver="Conqueror Krenna",giverType="NPC",giverId=26860,ender="Gorgonna",enderType="NPC",enderId=27102,rewardNextId=12422,poiX=3271,poiY=-2197,wowhead="https://www.wowhead.com/wotlk/quest=12424",image="assets/images/quests/placeholder.png",xpDiff=3,desc="This book is written in the pig-tongue the humans use.  It needs to be burned immediately.$B$BHand it to my sister Gorgonna and do not waste my time.",logDesc="Bring Mikhail's Journal to Gorgonna in Conquest Hold."} end
if not DB[12425] then DB[12425]={id=12425,zoneId=394,name="Ruuna the Blind",level=75,minLevel=73,giver="Gorgonna",giverType="NPC",giverId=27102,ender="Ruuna the Blind",enderType="NPC",enderId=27581,rewardNextId=12328,poiX=3271,poiY=-2197,wowhead="https://www.wowhead.com/wotlk/quest=12425",image="assets/images/quests/placeholder.png",xpDiff=2,desc="This trapper business has the potential to be more important than we've accounted for.$B$BIf they're not with the Alliance, there's a good chance they're with the Scourge, which could mean trouble.$B$BOur previous efforts might've paid off, though.  We spotted our former captive meeting with a fortune teller of some sort before we lost track of her.$B$BI'm almost certain now that she will take us to their leader if we can find her again.  Find Ruuna the Blind and see what you can find out.",logDesc="Speak to Ruuna the Blind at Ruuna's Camp near Vordrassil Pass."} end
if not DB[12426] then DB[12426]={id=12426,zoneId=394,name="DEPRECATED",level=75,minLevel=72,wowhead="https://www.wowhead.com/wotlk/quest=12426",image="assets/images/quests/placeholder.png",xpDiff=2} end
if not DB[12427] then DB[12427]={id=12427,zoneId=394,name="The Conquest Pit: Bear Wrestling!",level=74,minLevel=73,giver="Grennix Shivwiggle",giverType="NPC",giverId=27719,ender="Bookie Vel'jen",enderType="NPC",enderId=27720,rewardNextId=12428,poiX=3281,poiY=-2289,wowhead="https://www.wowhead.com/wotlk/quest=12427",image="assets/images/quests/placeholder.png",xpDiff=6,money=112000,desc="So you're interested in the fights, eh?  Well, Krenna has outlawed pit-fighting for all enlisted combatants.  But you, my friend, are technically a free agent and are not included in this prohibition.$B$BNice loophole, eh?$B$BAnyway, if you're interested I can start you off with something easy, a measly bear.  I'll even let you bring friends along!",logDesc="Defeat Ironhide inside the Conquest Pit and speak to Bookie Vel'jen for a reward."} end
if not DB[12428] then DB[12428]={id=12428,zoneId=394,name="The Conquest Pit: Mad Furbolg Fighting",level=74,minLevel=73,giver="Grennix Shivwiggle",giverType="NPC",giverId=27719,ender="Bookie Vel'jen",enderType="NPC",enderId=27720,poiX=3281,poiY=-2289,wowhead="https://www.wowhead.com/wotlk/quest=12428",image="assets/images/quests/placeholder.png",xpDiff=6,money=168000,desc="You're not bad.  Not bad at all.$B$BThink you can take a furbolg?  What about one of those extra-large crazed Northrend furbolgs?$B$BGood, good.  Get your crew together, and head to the ring.  Let's give these folks a show... maybe we can earn some more coin while we're at it.",logDesc="Defeat Torgg Thundertotem inside the Conquest Pit and speak to Bookie Vel'jen for a reward.$B"} end
if not DB[12429] then DB[12429]={id=12429,zoneId=394,name="The Conquest Pit: Blood and Metal",level=74,minLevel=73,giver="Grennix Shivwiggle",giverType="NPC",giverId=27719,ender="Bookie Vel'jen",enderType="NPC",enderId=27720,poiX=3281,poiY=-2289,wowhead="https://www.wowhead.com/wotlk/quest=12429",image="assets/images/quests/placeholder.png",xpDiff=6,money=168000,desc="It's nice to have a real fighter around these parts... we'd only had prisoners and caged beasts for the past few weeks.  The people get bored, ya know?$B$BAnyhow, your next challenge is a genuine iron golem stolen from the depths of Thor Modan... think you can swing it?",logDesc="Defeat Rustblood inside the Conquest Pit and speak to Bookie Vel'jen for a reward.$B"} end
if not DB[12430] then DB[12430]={id=12430,zoneId=394,name="The Conquest Pit: Death Is Likely",level=75,minLevel=73,giver="Grennix Shivwiggle",giverType="NPC",giverId=27719,ender="Bookie Vel'jen",enderType="NPC",enderId=27720,poiX=3281,poiY=-2289,wowhead="https://www.wowhead.com/wotlk/quest=12430",image="assets/images/quests/placeholder.png",xpDiff=7,money=177000,desc="I'm gonna shoot straight with ya, kid.  This next contender's a murderer.$B$BLiterally.$B$BHe was to be executed last week, but he strangled the hangman with his left hand, so Krenna's guards sort of let me have him.$B$BFeel free to pass on this one.  I wouldn't blame ya.",logDesc="Defeat Horgrenn Hellcleave inside the Conquest Pit and speak to Bookie Vel'jen for a reward.$B"} end
if not DB[12431] then DB[12431]={id=12431,zoneId=394,name="The Conquest Pit: Final Showdown",level=75,minLevel=73,giver="Grennix Shivwiggle",giverType="NPC",giverId=27719,ender="Gorgonna",enderType="NPC",enderId=27102,poiX=3281,poiY=-2289,wowhead="https://www.wowhead.com/wotlk/quest=12431",image="assets/images/quests/placeholder.png",xpDiff=7,money=177000,desc="You must've really upset Krenna.  She and Gorgonna have had a spat and you're wanted in the pit immediately.$B$BThere are some wild rumors that it's a fight to the death!  That would be bad news for you, but great news for our business venture!$B$BAt any rate, you can't run away from fate... best get in there on the quick and get it over with.",logDesc="Defeat Krenna in the Conquest Pit and speak to Gorgonna for a reward.",choiceRewards={{id=39181,qty=1},{id=39183,qty=1},{id=39182,qty=1},{id=39179,qty=1},{id=39180,qty=1}}} end
if not DB[12432] then DB[12432]={id=12432,zoneId=394,name="Riding the Red Rocket",level=74,minLevel=73,giver="General Gorlok",giverType="NPC",giverId=27708,ender="General Gorlok",enderType="NPC",enderId=27708,poiX=2488,poiY=-1889,wowhead="https://www.wowhead.com/wotlk/quest=12432",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="You there, $r! Get your lousy carcass over here!$b$bThe Alliance have a shipment of lumber all ready for transport just northeast of here. Since getting our hands on that wood is out of the question, there's only one thing to do - destroy it!$b$bThe goblin at the end of the dock here has some torpedoes all ready to go. He's got all the fuel for them on the docked goblin ship to the north.$b$bGet some fuel, then commandeer one of the torpedoes and ride it into their ship.$b$bDismissed!",logDesc="General Gorlok at the lighthouse in Venture Bay wants you to destroy the Alliance Lumber Boat.$b$bGeneral Gorlok will only be present at the lighthouse when the Horde has it in their possession.",rewards={{id=37836,qty=10}}} end
if not DB[12433] then DB[12433]={id=12433,zoneId=394,name="Seeking Solvent",level=74,minLevel=73,giver="Gurtor",giverType="NPC",giverId=27565,ender="Gurtor",enderType="NPC",enderId=27565,poiX=2835,poiY=-1697,wowhead="https://www.wowhead.com/wotlk/quest=12433",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Gah! Not again. Another blown gasket....$b$bEvery time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean.$b$bTell ya what, $r. There's some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent.$b$bGet me one of those and I'll make it worth your trouble.",logDesc="Gurtor at the Venture Bay Horde base wants you to bring him a canister of Element 115.",rewards={{id=37836,qty=4}}} end
if not DB[12434] then DB[12434]={id=12434,zoneId=394,name="Always Seeking Solvent",level=74,minLevel=73,wowhead="https://www.wowhead.com/wotlk/quest=12434",image="assets/images/quests/placeholder.png",rewards={{id=37836,qty=2}}} end
if not DB[12435] then DB[12435]={id=12435,zoneId=65,name="Report to Lord Afrasastrasz",level=74,minLevel=71,giver="3",giverType="NPC",giverId=26917,ender="Lord Afrasastrasz",enderType="NPC",enderId=27575,rewardNextId=12372,poiX=3531,poiY=271,wowhead="https://www.wowhead.com/wotlk/quest=12435",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I abhor the loss of life... any life. But I will not stand idly by and allow Malygos to kill us and defile the temple!$B$BI have appointed Lord Afrasastrasz as the commander of Wyrmrest's defenses.$B$BSpeak with Torastrasza to ride a drake down to him.$B$BPlease lend him your aid, $N. Your involvement with the defense of Wyrmrest will be critical to us prevailing against the blue dragonflight.",logDesc="Speak with Lord Afrasastrasz at Wyrmrest Temple."} end
if not DB[12436] then DB[12436]={id=12436,zoneId=394,name="Supplemental Income",level=74,minLevel=73,giver="Provisioner Lorkran",giverType="NPC",giverId=26868,ender="Provisioner Lorkran",enderType="NPC",enderId=26868,poiX=3201,poiY=-2301,wowhead="https://www.wowhead.com/wotlk/quest=12436",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hail, $c.  You'll find that here at Conquest Hold, we buy and sell what Krenna wants us to buy and sell... at the price that Krenna wants us to buy and sell.$B$BAll this is stifling business.  I'm hoping to make a little bit of coin on the side and feed our grunts at the same time.  Why don't you go hunt down some stag and bring me the venison?$B$BThey're numerous in the area, so bring me only the best meat.",logDesc="Provisioner Lorkran at Conquest Hold wants you to obtain 5 Succulent Venison from  the nearby Tallhorn Stag."} end
if not DB[12437] then DB[12437]={id=12437,zoneId=394,name="Riding the Red Rocket",level=74,minLevel=73,giver="Commander Howser",giverType="NPC",giverId=27759,ender="Commander Howser",enderType="NPC",enderId=27759,poiX=2485,poiY=-1889,wowhead="https://www.wowhead.com/wotlk/quest=12437",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Listen, $n. This battle is as much over resources as tactical supremacy.$b$bI have a mission that could turn the tide in our struggle against the Horde here.$b$bThere are torpedoes at the end of the dock that we can use to take down the Horde's lumber ship to the northwest.$b$bYou'll need to get some of the fuel that's stored on the docked goblin ship just north of here, then ride one of the torpedoes into their transport!",logDesc="Commander Howser at the lighthouse in Venture Bay wants you to destroy the Horde lumber shipment.$b$bCommander Howser will only be present at the lighthouse when the Alliance has it in their possession.",rewards={{id=37836,qty=10}}} end
if not DB[12438] then DB[12438]={id=12438,zoneId=65,name="Wanted: Kreug Oathbreaker",level=74,minLevel=71,ender="Highlord Leoric Von Zeldig",enderType="NPC",enderId=27156,wowhead="https://www.wowhead.com/wotlk/quest=12438",image="assets/images/quests/placeholder.png",xpDiff=6,money=112000,desc="Posted by: Illusia Lune$B$BThe Scourge flesh giant known as Kreug Oathbreaker was responsible for the deaths of my husband, children and my dear friends, the Whisperveils. Those brave enough to take on this bounty will find Kreug in the southeastern reaches of the Carrion Fields.$B$BI demand justice! Kill Kreug Oathbreaker!$B$BIn the event that Kreug is slain, I have pooled money and items together and given them to Highlord Leoric Von Zeldig to give out as a reward.$B$BPlease vindicate us!",logDesc="Kill Kreug Oathbreaker and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.",choiceRewards={{id=37957,qty=1},{id=37999,qty=1},{id=38042,qty=1},{id=38103,qty=1}}} end
if not DB[12439] then DB[12439]={id=12439,zoneId=65,name="A Disturbance In The West",level=72,minLevel=71,giver="Vas the Unstable",giverType="NPC",giverId=27158,ender="Rodney Wells",enderType="NPC",enderId=26878,rewardNextId=12440,poiX=3880,poiY=-798,wowhead="https://www.wowhead.com/wotlk/quest=12439",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Another force threatens to destroy all that we have worked for, $N. You must head westward to Stars' Rest. Archmage Modera has sensed a great disturbance in the magical ley lines of our world that must be dealt with immediately!$B$BGo now, $N! Speak to Rodney Wells at the gryphon station here in Wintergarde and let him know the nature of your mission. He will place you on his fastest gryphon to deliver you to Stars' Rest. Speak with Archmage Modera when you arrive.",logDesc="Speak to Rodney Wells at Wintergarde Keep to secure a ride to Stars' Rest in western Dragonblight."} end
if not DB[12440] then DB[12440]={id=12440,zoneId=65,name="To Stars' Rest!",level=72,minLevel=71,giver="Rodney Wells",giverType="NPC",giverId=26878,ender="Image of Archmage Modera",enderType="NPC",enderId=26673,rewardNextId=12000,poiX=3712,poiY=-695,wowhead="https://www.wowhead.com/wotlk/quest=12440",image="assets/images/quests/placeholder.png",xpDiff=1,desc="When you are ready I will place you on my fastest gryphon to Stars' Rest. Once you get there, find and speak with Archmage Modera.$B$BGood luck, ally!",logDesc="Speak with the Image of Archmage Modera at Stars' Rest in western Dragonblight.$B"} end
if not DB[12441] then DB[12441]={id=12441,zoneId=65,name="Wanted: High Shaman Bloodpaw",level=74,minLevel=71,ender="Highlord Leoric Von Zeldig",enderType="NPC",enderId=27156,wowhead="https://www.wowhead.com/wotlk/quest=12441",image="assets/images/quests/placeholder.png",xpDiff=6,money=112000,desc="Posted by: Drolfy$B$BWhile out in the Eldritch Heights with my cousins, Skrotee and Brote, a vicious band of wolvar from the Bloodpaw tribe attacked us. We attempted to flee, but I fear they got Skrotee and Brote.$B$BI demand retribution! Is there someone brave enough to venture to the southeastern reaches of Dragonblight, to the Eldritch Heights, and kill High Shaman Bloodpaw and his cronies?$B$BI have given a hefty sum of gold to Highlord Leoric Von Zeldig to disperse to anyone that claims this bounty!",logDesc="Kill High Shaman Bloodpaw and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.",choiceRewards={{id=38171,qty=1},{id=38172,qty=1},{id=38132,qty=1},{id=38169,qty=1},{id=38170,qty=1},{id=38131,qty=1}}} end
if not DB[12442] then DB[12442]={id=12442,zoneId=65,name="Wanted: Onslaught Commander Iustus",level=74,minLevel=71,ender="Highlord Leoric Von Zeldig",enderType="NPC",enderId=27156,wowhead="https://www.wowhead.com/wotlk/quest=12442",image="assets/images/quests/placeholder.png",xpDiff=6,money=112000,desc="Posted by: Highlord Leoric Von Zeldig$B$BUpon the northeastern path from Wintergarde a battalion of 7th Legion were ambushed and slain by Onslaught Commander Iustus and an army of mindless Scarlet Onslaught zealots. Such cold and calculated actions must be met with force!$B$BWintergarde demands justice! Seek out Onslaught Commander Iustus at Onslaught Base Camp to the northeast and end his miserable existence.$B$BI will hand out the reward for this bounty to any who would dare take up the task!$B",logDesc="Kill Onslaught Commander Iustus and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.$B",choiceRewards={{id=38115,qty=1},{id=38054,qty=1},{id=38529,qty=1},{id=38528,qty=1}}} end
if not DB[12443] then DB[12443]={id=12443,zoneId=394,name="Seeking Solvent",level=74,minLevel=73,giver="Barblefink",giverType="NPC",giverId=27495,ender="Barblefink",enderType="NPC",enderId=27495,poiX=2711,poiY=-2319,wowhead="https://www.wowhead.com/wotlk/quest=12443",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Gah! Not again. Another blown gasket....$b$bEvery time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean.$b$bTell ya what, $r. There's some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent.$b$bGet me one of those and I'll make it worth your trouble.",logDesc="Barblefink at the Alliance base in Venture Bay wants you to bring him a canister of Element 115.",rewards={{id=37836,qty=4}}} end
if not DB[12444] then DB[12444]={id=12444,zoneId=394,name="Blackriver Skirmish",level=74,minLevel=73,giver="Scout Captain Carter",giverType="NPC",giverId=27783,ender="Scout Captain Carter",enderType="NPC",enderId=27783,poiX=3424,poiY=-2681,wowhead="https://www.wowhead.com/wotlk/quest=12444",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="The Venture Company's on its way out of Grizzly Hills.  They used to run logging operations here, but things got a little too dangerous for them.$B$BTheir abandoned sites are up for grabs and we sure as hell can't let the Horde get their hands on them.$B$BThe Blackriver Logging Camp is the smallest of the three logging sites in this zone, but we still need it.  Do your part and fend off the Horde forces.  Any lumber they get here will be made into weapons to be used against us elsewhere.",logDesc="Scout Captain Carter wants you to kill 10 Horde units or players in the Blackriver Logging Camp.",rewards={{id=37836,qty=10}}} end
if not DB[12446] then DB[12446]={id=12446,zoneId=394,name="Always Seeking Solvent",level=74,minLevel=73,wowhead="https://www.wowhead.com/wotlk/quest=12446",image="assets/images/quests/placeholder.png",rewards={{id=37836,qty=2}}} end
if not DB[12447] then DB[12447]={id=12447,zoneId=65,name="The Obsidian Dragonshrine",level=74,minLevel=72,giver="Nalice",giverType="NPC",giverId=27765,ender="Serinar",enderType="NPC",enderId=26593,poiX=3548,poiY=258,wowhead="https://www.wowhead.com/wotlk/quest=12447",image="assets/images/quests/placeholder.png",xpDiff=1,money=5600,desc="The Scourge come. Korialstrasz calls upon his allies in a futile attempt to save their Ruby Dragonshrine, but it seems the good graces of the red flight don't extend to saving the shrines of the other flights.$B$BSurprised? I'm not.$B$BThere is another of my brood who has left to clear our Obsidian Dragonshrine of the undead vermin that now infest it. All it would take to prove yourself more noble and righteous than Alexstrasza herself is a quick jaunt over there and a few swings of a blade.$B$BI'm amused.",logDesc="Travel to the Obsidian Dragonshrine Northwest of Wymrest and just West of the Wrath Gate. Locate Serinar inside of the shrine and offer him your aid."} end
if not DB[12448] then DB[12448]={id=12448,zoneId=65,name="Heated Battle",level=74,minLevel=71,giver="Vargastrasz",giverType="NPC",giverId=27763,ender="Vargastrasz",enderType="NPC",enderId=27763,rewardNextId=12449,poiX=3672,poiY=1217,wowhead="https://www.wowhead.com/wotlk/quest=12448",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, $r.$B$BCaptain Drayzen leads a group of your kind in stemming the flow of the Scourge out of the shrine.$B$BGo to his aid... but please stay behind his men. The flow of Scourge is endless and I don't want to lose you in one of those scarred canyons.",logDesc="Aid Captain Drayzen in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker.$B$BReturn to Vargastrasz once you have finished this task."} end
if not DB[12449] then DB[12449]={id=12449,zoneId=65,name="Return to the Earth",level=74,minLevel=71,giver="Vargastrasz",giverType="NPC",giverId=27763,ender="Vargastrasz",enderType="NPC",enderId=27763,rewardNextId=12450,poiX=3672,poiY=1217,wowhead="https://www.wowhead.com/wotlk/quest=12449",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks.$B$BGet into the shrine through the pass in the south... the Scourge presence should be lighter there.$B$BSearch the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.",logDesc="Enter the Ruby Dragonshrine through the southern pass and search for Ruby Acorns.  Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth.  Return to Vargastrasz once the task is complete."} end
if not DB[12450] then DB[12450]={id=12450,zoneId=65,name="Through Fields of Flame",level=75,minLevel=71,giver="Vargastrasz",giverType="NPC",giverId=27763,ender="Vargastrasz",enderType="NPC",enderId=27763,rewardNextId=12769,poiX=3672,poiY=1217,wowhead="https://www.wowhead.com/wotlk/quest=12450",image="assets/images/quests/placeholder.png",xpDiff=6,money=118000,desc="I have one final task for you, $r... one that should turn the tide of this fight.$B$BReturn to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine.$B$BI also need you to find the source of the corruption under the shrine and put an end to it.$B$BI know I have asked a lot of you, but if you do this for me, we will win this battle.",logDesc="Enter the Ruby Dragonshrine through the southern pass, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Vargastrasz once the task is complete.",choiceRewards={{id=37962,qty=1},{id=38004,qty=1},{id=38046,qty=1},{id=38108,qty=1}}} end
if not DB[12451] then DB[12451]={id=12451,zoneId=394,name="Onward to Camp Oneqwah",level=74,minLevel=73,giver="Sergeant Nazgrim",giverType="NPC",giverId=27388,ender="Scout Vor'takh",enderType="NPC",enderId=26666,poiX=3275,poiY=-2213,wowhead="https://www.wowhead.com/wotlk/quest=12451",image="assets/images/quests/placeholder.png",xpDiff=2,desc="While we build Conquest Hold, I sent Scout Vor'takh to make contact with our taunka allies in the east. They're based in Camp Oneqwah, which is in the easternmost part of Grizzly Hills, beyond Grizzlemaw.$B$BMake the journey there, hear Vor'takh's report and offer your assistance with anything he and the local chieftain may need. Your contributions to Conquest Hold have been exemplary and I know Vor'takh will be grateful for the assistance.",logDesc="Speak with Scout Vor'takh at Camp Oneqwah."} end
if not DB[12452] then DB[12452]={id=12452,zoneId=65,name="zzOLD The Fate of the Ruby Dragonshrine",level=74,minLevel=72,wowhead="https://www.wowhead.com/wotlk/quest=12452",image="assets/images/quests/placeholder.png",logDesc="Bring Dahlia's Ruby Broach to Ceristrasz and inform him of her fate."} end
if not DB[12453] then DB[12453]={id=12453,zoneId=394,name="Eyes Above",level=74,minLevel=73,giver="Windseer Grayhorn",giverType="NPC",giverId=27262,ender="Windseer Grayhorn",enderType="NPC",enderId=27262,poiX=3317,poiY=-2292,wowhead="https://www.wowhead.com/wotlk/quest=12453",image="assets/images/quests/placeholder.png",xpDiff=4,money=44000,desc="I've been asked to lend my support to our efforts against the Alliance.  At the moment our military forces are about evenly matched and we're looking for ways to find an edge.$B$BThe imperial eagles that fly over the mountains and trees in this area would make excellent scouts for us.  Take this silver feather and use it to bind my sight to that of them.$B$BBeing able to see our enemy's movements will grant us the strategic advantage we need.  You'll find abundant eagles in the mountains to the east.",logDesc="Windseer Grayhorn wants you to use the Silver Feather on 6 Imperial Eagles in Grizzly Hills.",choiceRewards={{id=38762,qty=1},{id=38760,qty=1},{id=38761,qty=1}}} end
if not DB[12454] then DB[12454]={id=12454,zoneId=65,name="Cycle of Life",level=74,minLevel=72,giver="3",giverType="NPC",giverId=27255,ender="3",enderType="NPC",enderId=27255,rewardNextId=12456,poiX=2828,poiY=-20,wowhead="https://www.wowhead.com/wotlk/quest=12454",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="Ysera sleeps in the Emerald Dream, watching over both the Dream and Azeroth. But a horrible nightmare has taken hold in the Dream, and now I fear that Ysera is being affected by it.$B$BRecently, I asked her to aid in the fight against the Scourge that are raising frostwyrms at the other dragonshrines. She misunderstood.$B$BInstead, she told our dragonshrine's defenders to treat those not of the green dragonflight as enemies.$B$BI need you to slay some of the skytalons. The shrine must regain its balance.",logDesc="Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to slay 5 Emerald Skytalons."} end
if not DB[12455] then DB[12455]={id=12455,zoneId=65,name="Scattered To The Wind",level=73,minLevel=71,giver="Ambo Cash",giverType="NPC",giverId=1293,ender="Ambo Cash",enderType="NPC",enderId=1293,rewardNextId=12457,poiX=3673,poiY=-1193,wowhead="https://www.wowhead.com/wotlk/quest=12455",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The munitions drop went badly, friend. The shipment of ammo from Westguard Keep was intercepted by the frostwyrms circling overhead. The flying machines were torn apart in a matter of seconds and their cargo was scattered to the wind. Most of it is still topside - on the Carrion Fields.$B$BI'm gonna need you to go back up and recover the munitions crates that are scattered all over this damned place.$B$BHurry it up! We can't start this offensive without guns and ammo, $g buddy:missy;!",logDesc="Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to recover 8 Wintergarde Munitions."} end
if not DB[12456] then DB[12456]={id=12456,zoneId=65,name="The Plume of Alystros",level=74,minLevel=72,giver="3",giverType="NPC",giverId=27255,ender="3",enderType="NPC",enderId=27255,poiX=2828,poiY=-20,wowhead="https://www.wowhead.com/wotlk/quest=12456",image="assets/images/quests/placeholder.png",xpDiff=6,money=112000,desc="I can feel that the shrine is not completely back in balance. The verdant keeper has been angered by our actions, and I sense that he will not listen to reason.$B$BAlystros is an immense skytalon who perches at the south end of the Emerald Dragonshrine. It is he who is in charge of the dragonshrine's aerial defenses. I fear that we will have to deal with him.$B$BTake these skytalon molts and place them on the ground where he can see them. He will come. Bring me his plume.",logDesc="Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to acquire The Plume of Alystros.",choiceRewards={{id=37937,qty=1},{id=37981,qty=1},{id=38024,qty=1},{id=38085,qty=1}}} end
if not DB[12457] then DB[12457]={id=12457,zoneId=65,name="The Chain Gun And You",level=73,minLevel=71,giver="Ambo Cash",giverType="NPC",giverId=1293,ender="Ambo Cash",enderType="NPC",enderId=1293,rewardNextId=12463,poiX=3673,poiY=-1193,wowhead="https://www.wowhead.com/wotlk/quest=12457",image="assets/images/quests/placeholder.png",xpDiff=6,desc="We've set up chain guns and barricades directly to the east and to the west. Our injured soldiers are hiding in both rooms - trying their best to not alert the mindless ghouls to their presence.$B$BNow that we have ammo, I need you to man one of the chain guns and use it to blast a path clear for our soldiers! Once you're on board, call a soldier out from hiding and then lay down heavy fire to keep the Scourge off him!$B$BGet a move on!",logDesc="Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to save 8 Injured 7th Legion Soldiers."} end
if not DB[12458] then DB[12458]={id=12458,zoneId=65,name="Seeds of the Lashers",level=74,minLevel=72,giver="Lord Itharius",giverType="NPC",giverId=27785,ender="Lord Itharius",enderType="NPC",enderId=27785,rewardNextId=12459,poiX=3540,poiY=286,wowhead="https://www.wowhead.com/wotlk/quest=12458",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="We need more weapons in the fight against the Scourge. The natural properties of the Emerald Dragonshrine to the southeast may be the answer.$B$BAny unliving creature, save those that Sylvanas has redeemed, that steps foot in the dragonshrine falls to dust.$B$BI want to test a theory, and I want you to be my instrument in doing so, young $r. Go to the Emerald Dragonshrine and take the seeds from the emerald lashers therein.",logDesc="Lord Itharius at the top of Wyrmrest Temple has asked you to return with 3 Lasher Seeds."} end
if not DB[12459] then DB[12459]={id=12459,zoneId=65,name="That Which Creates Can Also Destroy",level=74,minLevel=72,giver="Lord Itharius",giverType="NPC",giverId=27785,ender="Lord Itharius",enderType="NPC",enderId=27785,poiX=3540,poiY=286,wowhead="https://www.wowhead.com/wotlk/quest=12459",image="assets/images/quests/placeholder.png",xpDiff=7,money=168000,desc="Since we only have three seeds, we must put them to the best possible use.$B$BYour targets are one of the reanimated frost wyrms circling to the north near Galakrond's Rest, Turgid the Vile in the ruined barracks at the Carrion Fields to the east, and Overseer Deathgaze at Jintha'kalar far to the northeast.$B$BWhile the seeds would outright destroy one of the lesser Scourge, they will greatly weaken these three. Enough so, in fact, that you should be able to handle them on your own.",logDesc="Lord Itharius at the top of Wyrmrest Temple has asked you to destroy a Weakened Reanimated Frost Wyrm, Weakened Turgid the Vile, and Weakened Overseer Deathgaze.",choiceRewards={{id=37940,qty=1},{id=37983,qty=1},{id=38027,qty=1},{id=38088,qty=1}}} end
if not DB[12460] then DB[12460]={id=12460,zoneId=65,name="Report to the Ruby Dragonshrine",level=74,minLevel=71,giver="Lauriel Trueblade",giverType="NPC",giverId=27803,ender="Ceristrasz",enderType="NPC",enderId=27506,rewardNextId=12416,poiX=3515,poiY=262,wowhead="https://www.wowhead.com/wotlk/quest=12460",image="assets/images/quests/placeholder.png",xpDiff=1,money=5600,desc="We need you at the Ruby Dragonshrine.$B$BThe dragons are beset on all sides by the blue flight and the scourge... they're in no better a state than we are. The situation seems dire, but this affords us a rare opportunity to establish a valuable alliance.$B$BI secured a regiment to aid the red dragonflight against the Scourge at the Ruby Dragonshrine. If you have a fight in you, please go find Ceristrasz on the ridge east of the shrine and help him in any way that you can.",logDesc="Report to Ceristrasz on the ridge east of the Ruby Dragonshrine, west of Wyrmrest."} end
if not DB[12461] then DB[12461]={id=12461,zoneId=65,name="Report to the Ruby Dragonshrine",level=74,minLevel=71,giver="Golluck Rockfist",giverType="NPC",giverId=27804,ender="Vargastrasz",enderType="NPC",enderId=27763,rewardNextId=12448,poiX=3499,poiY=368,wowhead="https://www.wowhead.com/wotlk/quest=12461",image="assets/images/quests/placeholder.png",xpDiff=1,money=5600,desc="You are leaving to the Ruby Dragonshrine. This is not a request.$B$BThe dragons are beset on all sides by the blue flight and the scourge... they're in no better a state than we are. It is not often we are afforded the opportunity to redeem ourselves for the transgressions of our ancestors.$B$BI have secured a regiment to aid the red dragonflight against the Scourge at the Ruby Dragonshrine. Join them and crush the Scourge beneath your boots!$B$BFor the Horde!",logDesc="Report to Vargastrasz on a ridge outside of the Ruby Dragonshrine, just east of Agmar's Hammer."} end
if not DB[12462] then DB[12462]={id=12462,zoneId=65,name="Breaking Off A Piece",level=73,minLevel=71,giver="Yord \"Calamity\" Icebeard",giverType="NPC",giverId=27319,ender="Yord \"Calamity\" Icebeard",enderType="NPC",enderId=27319,poiX=3667,poiY=-1188,wowhead="https://www.wowhead.com/wotlk/quest=12462",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Just down the steps lies the gateway to damnation: Scourge as far as the eye can see and getting thicker with each passing moment. What little intelligence we've been able to gather indicates that two Scourge necrolords are furiously working at emptying the first two crypts down below. Before we can breach the inner chamber to Thel'zan, we'll need to take care of those two clowns and their Naxxramas cronies.$B$BGo down into the mausoleum and take out the necrolords and the Naxxramas dreadguards and shades.",logDesc="Yord \"Calamity\" Icebeard at the Wintergarde Mausoleum in Dragonblight wants you to kill Necrolord X'avius, Necrolord Horus, and 15 Naxxramas Scourge.$B",choiceRewards={{id=37959,qty=1},{id=38001,qty=1},{id=38044,qty=1},{id=38105,qty=1}}} end
if not DB[12463] then DB[12463]={id=12463,zoneId=65,name="Plunderbeard Must Be Found!",level=73,minLevel=71,giver="Ambo Cash",giverType="NPC",giverId=1293,ender="Plunderbeard",enderType="NPC",enderId=27828,rewardNextId=12465,poiX=3673,poiY=-1193,wowhead="https://www.wowhead.com/wotlk/quest=12463",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There's been talk of a tunnel dug by Scourge that connects the embalming chambers of the mausoleum with the large crypts, now unearthed by Thel'zan and his minions. I recently sent my best rogue, Plunderbeard, in search of answers, but have yet to hear back from him. If I were a betting man I'd wager that he's a goner.$B$BI want you to go down those steps and head straight through the embalming chamber and look for Plunderbeard. Dead or alive, he'll have answers.$B",logDesc="Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to find Plunderbeard."} end
if not DB[12464] then DB[12464]={id=12464,zoneId=65,name="My Old Enemy",level=73,minLevel=71,giver="Commander Eligor Dawnbringer",giverType="NPC",giverId=27784,ender="Commander Eligor Dawnbringer",enderType="NPC",enderId=27784,poiX=3798,poiY=-681,wowhead="https://www.wowhead.com/wotlk/quest=12464",image="assets/images/quests/placeholder.png",xpDiff=6,money=106000,desc="My old enemy, High General Abbendis, has come to Northrend.$B$BSomehow she survived the attacks upon Tyr's Hand and brought a small force north. They've established New Hearthglen to the south.$B$BWhile they could prove useful in fighting the Scourge, Abbendis herself is far too shrewd an opponent to let live. Trust me, if we let them stand, she will be at our throats before the dust settles.$B$BSo, we'll deprive them of their leadership and go about our business. Bring me her head as proof.",logDesc="Deliver The High General's Head to Commander Eligor Dawnbringer at Wintergarde Keep.",choiceRewards={{id=38178,qty=1},{id=38177,qty=1},{id=38135,qty=1},{id=38176,qty=1},{id=38134,qty=1},{id=38295,qty=1}}} end
if not DB[12465] then DB[12465]={id=12465,zoneId=65,name="Plunderbeard's Journal",level=73,minLevel=71,giver="Plunderbeard",giverType="NPC",giverId=27828,ender="Ambo Cash",enderType="NPC",enderId=1293,rewardNextId=12466,poiX=3530,poiY=-1093,wowhead="https://www.wowhead.com/wotlk/quest=12465",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Whatever was written on the remaining pages of Plunderbeard's journal must be recovered. Search the chambers located on the other side of this tunnel for Plunderbeard's assailants. They must be the ones who tore the journal apart!$B$BShould you recover the missing pages, return them to Ambo Cash at the entrance of the Wintergarde Mausoleum.",logDesc="Recover Page 4 of Plunderbeard's Journal, Page 5 of Plunderbeard's Journal, Page 6 of Plunderbeard's Journal, and Page 7 of Plunderbeard's Journal and return them to Ambo Cash at the Wintergarde Mausoleum in Dragonblight."} end
if not DB[12466] then DB[12466]={id=12466,zoneId=65,name="Chasing Icestorm: The 7th Legion Front",level=73,minLevel=71,giver="Ambo Cash",giverType="NPC",giverId=1293,ender="Legion Commander Tyralion",enderType="NPC",enderId=27844,rewardNextId=12467,poiX=3673,poiY=-1193,wowhead="https://www.wowhead.com/wotlk/quest=12466",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You need to get to the 7th Legion Front in northern Dragonblight. Return to Wintergarde Keep and take the north gate out of town. Keep north until you hit a road. Take a left on that road and follow it until you reach the snowline. Once at the snowline keep heading west until you hit the Path of the Titans. Follow that north and it'll lead you right into the 7th Legion Front.$B$BOnce there, speak with Legion Commander Tyralion. He'll be expecting you.$B$BAnd $N - it has been a pleasure. Farewell.",logDesc="Report to Legion Commander Tyralion at the 7th Legion Front in central Dragonblight."} end
if not DB[12467] then DB[12467]={id=12467,zoneId=65,name="Chasing Icestorm: Thel'zan's Phylactery",level=73,minLevel=71,giver="Legion Commander Tyralion",giverType="NPC",giverId=27844,ender="High Commander Halford Wyrmbane",enderType="NPC",enderId=27136,rewardNextId=12472,poiX=4531,poiY=-4,wowhead="https://www.wowhead.com/wotlk/quest=12467",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Your frostwyrm is out there.$B$B<Tyralion points west.>$B$BAnd it's a big one!$B$BWhen you're ready to fight, go speak with \"Wyrmbait.\" He'll \"fetch\" her. Once Icestorm is close enough we'll chain her to the ground and finish her off! Hopefully, with your help, we'll be able to take her down and get you that phylactery.$B$BOnce you've got the phylactery, return to Wintergarde Keep and report to High Commander Halford Wyrmbane. He's been making preparations for the final showdown with Thel'zan.",logDesc="Recover Thel'zan's Phylactery from Icestorm and return it to High Commander Halford Wyrmbane at Wintergarde Keep.$B",choiceRewards={{id=37958,qty=1},{id=38000,qty=1},{id=38043,qty=1},{id=38104,qty=1}}} end
if not DB[12468] then DB[12468]={id=12468,zoneId=394,name="The Conqueror's Task",level=74,minLevel=73,giver="Conqueror Krenna",giverType="NPC",giverId=26860,ender="Sergeant Nazgrim",enderType="NPC",enderId=27388,rewardNextId=12257,poiX=3271,poiY=-2197,wowhead="https://www.wowhead.com/wotlk/quest=12468",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The Horde is a magnificent war machine and you are nothing but a cog.$B$BI am in charge of securing fuel for this machine.  If I fail, the machine fails.$B$BLumber, ore, water... it's all here and we want it.  And so does the Alliance.$B$BBefore we can move against the human scum, we need to solidify our control over the western region.$B$BSpeak to Sergeant Nazgrim about eradicating the vrykul in Voldrune and then maybe - if you turn out to not be a complete failure - we'll send you on further tasks.",logDesc="Speak to Sergeant Nazgrim in Conquest Hold."} end
if not DB[12469] then DB[12469]={id=12469,zoneId=65,name="Return to Sender",level=74,minLevel=72,giver="Nozzlerust Supply Runner",giverType="NPC",giverId=26896,ender="Xink",enderType="NPC",enderId=26660,rewardNextId=12044,poiX=4673,poiY=909,wowhead="https://www.wowhead.com/wotlk/quest=12469",image="assets/images/quests/placeholder.png",xpDiff=1,money=5600,desc="Upon closer examination, the goblin appears to have been running a pack full of explosives across the wastes for delivery. The harpy feathers half-buried in the snow nearby suggest how he met his ill fate.$B$BIt appears that the goblin was bringing the explosives towards the Wrath Gate from somewhere to the east. It seems most prudent to follow the ridge back to the east and inform the sender of their runner's fate.",logDesc="Follow the ridge to the east and deliver the pack of explosives to Xink at Nozzlerust Post in northern Dragonblight."} end
if not DB[12470] then DB[12470]={id=12470,zoneId=65,name="Mystery of the Infinite",level=75,minLevel=72,giver="Chromie",giverType="NPC",giverId=27856,ender="Chromie",enderType="NPC",enderId=27856,poiX=3537,poiY=262,wowhead="https://www.wowhead.com/wotlk/quest=12470",image="assets/images/quests/placeholder.png",xpDiff=6,money=118000,desc="A time storm at the Bronze Dragonshrine to the northeast is keeping immortals from entering.$B$BThe Infinite Dragonflight are in a fight inside with the defenders to wrest control of the dragonshrine. We must take this opportunity to gain information.$B$BYou are not immortal. You can cross into the dragonshrine and use the Hourglass of Eternity. Protect the hourglass for long enough and the leader of the Infinite Dragonflight should be revealed.$B$BBe warned, the Infinite Dragonflight will try to stop you!",logDesc="Chromie, at the top of Wyrmrest Temple, has asked you to travel to the Bronze Dragonshrine. Once inside, place the Hourglass of Eternity on the ground.$B$BProtect the hourglass for as long as it lasts and then return to her with whatever information you gain.",choiceRewards={{id=38173,qty=1},{id=38174,qty=1},{id=38133,qty=1},{id=38202,qty=1}}} end
if not DB[12471] then DB[12471]={id=12471,zoneId=3537,name="Cruelty of the Kvaldir",level=71,minLevel=68,giver="Captured Tuskarr Prisoner",giverType="NPC",giverId=25636,ender="Karuk",enderType="NPC",enderId=25435,poiX=1906,poiY=6023,wowhead="https://www.wowhead.com/wotlk/quest=12471",image="assets/images/quests/placeholder.png",xpDiff=4,desc="I thank you for saving me, $N.  The kvaldir are animals!$B$BThey made us fight the other prisoners.  It would've been more merciful to just kill us all.$B$BThe youngling Karuk is still alive -- I noticed him arrive here.  Tell him his father fought until the end.",logDesc="Speak to Karuk about the Captured Tuskarr Prisoner."} end
if not DB[12472] then DB[12472]={id=12472,zoneId=65,name="Finality",level=73,minLevel=71,giver="High Commander Halford Wyrmbane",giverType="NPC",giverId=27136,ender="Legion Commander Yorik",enderType="NPC",enderId=27857,poiX=3768,poiY=-775,wowhead="https://www.wowhead.com/wotlk/quest=12472",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Thanks to your heroics, Lord Fordragon has given the command to launch a full assault against Thel'zan. 7th Legion have made their way into the summoning chamber of the mausoleum and located what appears to be a gateway to hell. The only piece that's missing now is you.$B$BTake the phylactery and report to Legion Commander Yorik inside the Wintergarde Mausoleum.$B$BThere is a tunnel that the Scourge dug out just outside the keep that you can take to get to Yorik quickly. Go now, $N! Lead us to victory!",logDesc="Take Thel'zan's Phylactery to Legion Commander Yorik inside the Wintergarde Mausoleum in Dragonblight."} end
if not DB[12473] then DB[12473]={id=12473,zoneId=65,name="An End And A Beginning",level=73,minLevel=71,giver="Legion Commander Yorik",giverType="NPC",giverId=27857,ender="High Commander Halford Wyrmbane",enderType="NPC",enderId=27136,rewardNextId=12474,poiX=3681,poiY=-925,wowhead="https://www.wowhead.com/wotlk/quest=12473",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Every good story has a beginning and an ending, $N. While your story is far from over, I'll be damned if it's not already turning out to be the stuff of legend! No matter what happens to us when this is all over, what you've done at Wintergarde will be a tale told for years to come.$B$BNow, ally, when you are ready I will use the phylactery to coax Thel'zan out of hiding.$B$BShould we somehow succeed, report the victory to High Commander Halford Wyrmbane at Wintergarde Keep.",logDesc="Defeat Thel'zan the Duskbringer and report to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight."} end
if not DB[12474] then DB[12474]={id=12474,zoneId=65,name="To Fordragon Hold!",level=73,minLevel=71,giver="High Commander Halford Wyrmbane",giverType="NPC",giverId=27136,ender="Highlord Bolvar Fordragon",enderType="NPC",enderId=27872,rewardNextId=12495,poiX=3768,poiY=-775,wowhead="https://www.wowhead.com/wotlk/quest=12474",image="assets/images/quests/placeholder.png",xpDiff=7,desc="With the Naxxramas war machine stopped dead in its tracks the time has come for you to help our forces at Angrathar, the Wrathgate. Nestled against the mountain in northern Dragonblight is our base of operations, Fordragon Hold. It is there that Lord Fordragon awaits your arrival! Go now, $N!$B$BTake the north gate out of town and travel north by northwest until you arrive at your destination.$B$BLight protect you!",logDesc="Venture to Fordragon Hold in Dragonblight and speak with Highlord Bolvar Fordragon.$B",choiceRewards={{id=38541,qty=1},{id=38543,qty=1},{id=38540,qty=1},{id=38542,qty=1}}} end
if not DB[12475] then DB[12475]={id=12475,zoneId=65,name="What Secrets Men Hide",level=73,minLevel=71,giver="Zelig the Visionary",giverType="NPC",giverId=27314,ender="Zelig the Visionary",enderType="NPC",enderId=27314,rewardNextId=12478,poiX=3811,poiY=-812,wowhead="https://www.wowhead.com/wotlk/quest=12475",image="assets/images/quests/placeholder.png",xpDiff=5,desc="After the betrayal at the Forgotten Shore, Prince Arthas - with Muradin in tow - began his quest for Frostmourne. Could the location of the cavern where Frostmourne was found be near? What secrets could it hold? While the orb has no answers for these questions, it does show me something.$B$BTo the northeast of Wintergarde Keep is an outpost built by the Scarlet Onslaught. Somewhere within that outpost is a map. The orb tells me that this map will be of great use to us.$B$BRetrieve it!",logDesc="Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to find the Onslaught Map and return it to him."} end
if not DB[12476] then DB[12476]={id=12476,zoneId=65,name="The Return of the Crusade?",level=73,minLevel=71,giver="Commander Lynore Windstryke",giverType="NPC",giverId=27155,ender="Commander Lynore Windstryke",enderType="NPC",enderId=27155,poiX=3773,poiY=-784,wowhead="https://www.wowhead.com/wotlk/quest=12476",image="assets/images/quests/placeholder.png",xpDiff=5,money=53000,desc="To the northeast of Wintergarde Keep is a newly built encampment, set up by the Scarlet Crusade - or rather - the Scarlet Onslaught as they now call themselves. While we are unsure as to why they are in Northrend, they are certainly no less dangerous than they were before. As of last night the Scarlet Onslaught has killed twelve of our soldiers. They must be taught a lesson, $N.$B$BGo to Onslaught Base Camp and thin them out. $B",logDesc="Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 20 Scarlet Onslaught at the Onslaught Base Camp.",rewards={{id=33447,qty=5}}} end
if not DB[12477] then DB[12477]={id=12477,zoneId=65,name="The Path of Redemption",level=73,minLevel=71,giver="High Commander Halford Wyrmbane",giverType="NPC",giverId=27136,ender="High Commander Halford Wyrmbane",enderType="NPC",enderId=27136,poiX=3768,poiY=-775,wowhead="https://www.wowhead.com/wotlk/quest=12477",image="assets/images/quests/placeholder.png",xpDiff=5,desc="\"The Path of Redemption,\" ever heard of it? It is allegedly a journal that holds the prophetic ramblings of High General Abbendis of the Scarlet Onslaught. Within that book can be found the motivations and goals of the Scarlet zealots - not to mention a whole lot of insanity.$B$BVenture to Onslaught Base Camp, northeast of Wintergarde Keep, and recover a copy of \"The Path of Redemption\" from one of the Onslaught soldiers.",logDesc="Return \"The Path of Redemption\" to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight."} end
if not DB[12478] then DB[12478]={id=12478,zoneId=65,name="Frostmourne Cavern",level=73,minLevel=71,giver="Zelig the Visionary",giverType="NPC",giverId=27314,ender="Zelig the Visionary",enderType="NPC",enderId=27314,poiX=3811,poiY=-812,wowhead="https://www.wowhead.com/wotlk/quest=12478",image="assets/images/quests/placeholder.png",xpDiff=6,desc="They have labeled the cave as Frostmourne Cavern. Why the Scarlet Onslaught is interested in such things is unknown, but by the look of things, the area surrounding the cave is heavily guarded. Nonetheless, we must proceed!$B$BTake this scrying orb and travel north out of town and then northwest towards Scarlet Point. Make your way into the cave and battle your way to the bottom. Once there, use the orb. Return here with what you discover.",logDesc="Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to use Zelig's Scrying Orb at the bottom of Frostmourne Cavern. Unlock the secrets of the past!",choiceRewards={{id=38530,qty=1},{id=38532,qty=1},{id=38531,qty=1},{id=38533,qty=1}}} end
if not DB[12479] then DB[12479]={id=12479,zoneId=3703,name="Onwards to Northrend!",level=70,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=12479",image="assets/images/quests/placeholder.png",desc="Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend.$B$BYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.",logDesc="Speak to the Alliance Recruiter inside Valiance Keep in Borean Tundra or the one at Vengeance Landing in Howling Fjord."} end
if not DB[12480] then DB[12480]={id=12480,zoneId=3703,name="Onwards to Northrend!",level=70,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=12480",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend.$B$BYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.",logDesc="Speak to the Horde Recruiter inside Warsong Hold in Borean Tundra or Vengeance Landing in Howling Fjord."} end
if not DB[12481] then DB[12481]={id=12481,zoneId=495,name="Adding Injury to Insult",level=71,minLevel=68,giver="Lydell",giverType="NPC",giverId=24458,ender="Lydell",enderType="NPC",enderId=24458,poiX=1634,poiY=-5380,wowhead="https://www.wowhead.com/wotlk/quest=12481",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="The vrykul are being clever about this.  Fortunately I've a trick up my sleeve.$B$BThis leader of theirs, Bjorn, is a real hothead.  We've pieced together enough of their language to fashion what we think is a good insult.  Something involving his mother and large barnyard animals... we're not quite sure.$B$BTake this piece of paper and read it to him.  Once he starts chasing you, lure him back here.  We'll make sure he doesn't make it out alive.",logDesc="Read the Vrykul Insult to Bjorn Halgurdsson in Baleheim, then lead him back to Lydell's Ambush and help slay him.",choiceRewards={{id=35889,qty=1},{id=35888,qty=1},{id=35890,qty=1},{id=35891,qty=1}}} end
if not DB[12482] then DB[12482]={id=12482,zoneId=495,name="Against Nifflevar",level=71,minLevel=68,giver="Ranger Captain Areiel",giverType="NPC",giverId=27922,ender="Ranger Captain Areiel",enderType="NPC",enderId=27922,poiX=675,poiY=-5476,wowhead="https://www.wowhead.com/wotlk/quest=12482",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We await reinforcements from Vengeance Landing to move against Nifflevar.  If we were to capture it earlier, though, it would provide us with a great advantage over the Alliance.$B$BHead into town and see if you can put a dent in their numbers.",logDesc="Ranger Captain Areiel wants you to go to Nifflevar and slay 5 Dragonflayer Warriors, 4 Dragonflayer Rune-Seers and 4 Dragonflayer Hunting Hounds."} end
if not DB[12483] then DB[12483]={id=12483,zoneId=394,name="Shimmercap Stew",level=75,minLevel=73,giver="Prigmon",giverType="NPC",giverId=26519,ender="Prigmon",enderType="NPC",enderId=26519,rewardNextId=12190,poiX=3882,poiY=-1936,wowhead="https://www.wowhead.com/wotlk/quest=12483",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Say, while yer here, how bout ya help ol' Prigmon with a little chore? I got a friend who can make a mean stew - one like ya never tasted before!$b$bThere be a few ingredients found in these parts that he be needin'. They be in ruins to the southwest and the camp just north o' here.$b$bWhatd'ya say, mon?",logDesc="Prigmon in Granite Springs wants you to collect 5 Shimmering Snowcaps and 5 Ice Serpent Eyes from Drak'Zin Ruins and 5 Sweetroot from Zeb'Halak."} end
if not DB[12484] then DB[12484]={id=12484,zoneId=394,name="Scourgekabob",level=74,minLevel=73,giver="Prigmon",giverType="NPC",giverId=26519,ender="Mack Fearsen",enderType="NPC",enderId=26604,poiX=3882,poiY=-1936,wowhead="https://www.wowhead.com/wotlk/quest=12484",image="assets/images/quests/placeholder.png",xpDiff=2,money=14400,desc="Ugh.$b$bWrappin' up these unfortunate trolls be makin' my heart ache, but not so much as my back!$b$bHelp ol' Prigmon out and haul one of these carcasses over to Mack.$b$bIf we don't burn 'em they be walkin' again in no time.",logDesc="Prigmon at Granite Springs wants you to bring a Mummified Troll Carcass to Mack Fearsen and place it in the fire."} end
if not DB[12485] then DB[12485]={id=12485,zoneId=495,name="Howling Fjord: aa - A - LK FLAG",level=70,minLevel=60,wowhead="https://www.wowhead.com/wotlk/quest=12485",image="assets/images/quests/placeholder.png"} end
if not DB[12486] then DB[12486]={id=12486,zoneId=3537,name="To Bor'gorok Outpost, Quickly!",level=71,minLevel=69,giver="Sauranok the Mystic",giverType="NPC",giverId=25272,ender="Spirit Talker Snarlfang",enderType="NPC",enderId=25339,rewardNextId=11624,poiX=2851,poiY=6177,wowhead="https://www.wowhead.com/wotlk/quest=12486",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Did you feel it?$B$B<Sauranok momentarily clutches his chest in confusion. His hand comes away trailing red-hot steam.>$B$BSomething terrible has happened to my old friend, Farseer Grimwalker. I just sensed it.$B$BHe had a pupil that he took with him when he went north. They were going to help the overlord establish an outpost on the edge of Sholazar Basin.$B$BHer name is Snarlfang. She is a spirit talker.$B$BPerhaps she will know what happened. Or, at least, she can help you to find out.",logDesc="Speak with Spirit Talker Snarlfang at Bor'gorok Outpost."} end
if not DB[12487] then DB[12487]={id=12487,zoneId=394,name="To Conquest Hold, But Be Careful!",level=74,minLevel=73,giver="High Executor Wroth",giverType="NPC",giverId=27243,ender="Conqueror Krenna",enderType="NPC",enderId=26860,rewardNextId=12468,poiX=3209,poiY=-679,wowhead="https://www.wowhead.com/wotlk/quest=12487",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I've received a request for help from our base in the Grizzly Hills. I'm sending you to see Conqueror Krenna.$B$B<The high executor waves a sheaf of parchment in the air as if he could care less what is written on it.>$B$BShe's attempting to secure all of the natural resources or somesuch. Just watch your back around her. The word is that she's aggressive even for an orc.$B$BFollow the road east and then southeast. Cross the bridge at the Dragonspine Tributary and go east from the Evergreen Trading Post.",logDesc="Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills."} end
if not DB[12488] then DB[12488]={id=12488,zoneId=65,name="The High Executor Needs You",level=74,minLevel=73,giver="Senior Sergeant Juktok",giverType="NPC",giverId=26415,ender="High Executor Wroth",enderType="NPC",enderId=27243,rewardNextId=12487,poiX=3833,poiY=1574,wowhead="https://www.wowhead.com/wotlk/quest=12488",image="assets/images/quests/placeholder.png",xpDiff=1,desc="It's a good thing that I intercepted this request from High Executor Wroth before it got to Overlord Agmar. What is Wroth thinking?$B$B<The sergeant rips up the letter that he's holding.>$B$B$C, go see what it is that the high executor wants.$B$BFollow the road east and pass through The Dragon Wastes. You'll find a path leading up out of the wastes on the southeast side, and the Forsaken town, Venomspite, will stand before you on the south side of the mountain.",logDesc="Speak with High Executor Wroth at Venomspite in Dragonblight."} end
if not DB[12489] then DB[12489]={id=12489,zoneId=3711,name="Welcome to Sholazar Basin",level=76,minLevel=76,giver="Monte Muzzleshot",giverType="NPC",giverId=27987,ender="Hemet Nesingwary",enderType="NPC",enderId=27986,poiX=5584,poiY=5200,wowhead="https://www.wowhead.com/wotlk/quest=12489",image="assets/images/quests/placeholder.png",xpDiff=3,money=31000,desc="So, where did you come from? I don't suppose that fool of an archmage sent you, too?$B$BYou're lucky to be in one piece, $g laddie:lass;! They nearly blew you up!$B$BThe jungle here's a darned dangerous place, 'specially with the Venture Company about.$B$B Git you! Go see the boss... he'll sort you out. The camp's at the end of that path to the northwest.$B$BNow, git!",logDesc="Follow the path to the northwest to reach the camp that Monte mentioned."} end
if not DB[12490] then DB[12490]={id=12490,zoneId=3537,name="Veehja's Revenge",level=71,minLevel=68,wowhead="https://www.wowhead.com/wotlk/quest=12490",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="We share a common enemy today, $r!  My people have been wiped out by these Kvaldir... my city has been all but destroyed.  It is time for exacting revenge!$B$BIn return for my help, I'd like you to slay the barbaric monsters that defile Riplash.  You will be well rewarded, $c.",logDesc="Veehja at the Shrine of Scales wants you to slay 6 Skadir Mariners, 3 Skadir Mistweavers and 2 Skadir Runecasters."} end
if not DB[12491] then DB[12491]={id=12491,zoneId=-370,name="Direbrew's Dire Brew",level=-1,minLevel=75,ender="Ipfelkofer Ironkeg",enderType="NPC",enderId=24710,wowhead="https://www.wowhead.com/wotlk/quest=12491",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Coren Direbrew's corpse clutched this small cask tightly to its gut.  This must be his infamous Dire Brew!",logDesc="Give Direbrew's Dire Brew to Ipfelkofer Ironkeg at the Brewfest camp near Ironforge.",rewards={{id=37829,qty=40}}} end
if not DB[12492] then DB[12492]={id=12492,zoneId=-370,name="Direbrew's Dire Brew",level=-1,minLevel=75,ender="Tapper Swindlekeg",enderType="NPC",enderId=24711,wowhead="https://www.wowhead.com/wotlk/quest=12492",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Coren Direbrew's corpse clutched this small cask tightly to its gut.  This must be his infamous Dire Brew!",logDesc="Give Direbrew's Dire Brew to Tapper Swindlekeg at the Brewfest camp near Orgrimmar.",rewards={{id=37829,qty=40}}} end
if not DB[12493] then DB[12493]={id=12493,zoneId=3711,name="PvP Test",level=-1,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=12493",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Kill me some guys from the other side!  Those guys suck!  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.",logDesc="Kill 10 opponents."} end
if not DB[12494] then DB[12494]={id=12494,zoneId=0,name="FLAG: Riding Trainer Advertisement (20)",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=12494",image="assets/images/quests/placeholder.png"} end
if not DB[12495] then DB[12495]={id=12495,zoneId=65,name="Audience With The Dragon Queen",level=74,minLevel=71,giver="Highlord Bolvar Fordragon",giverType="NPC",giverId=27872,ender="3",enderType="NPC",enderId=26917,rewardNextId=12497,poiX=4700,poiY=1507,wowhead="https://www.wowhead.com/wotlk/quest=12495",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Our assault against Angrathar has staggered the Scourge, but they remain unrelenting. From overhead they send their frost wyrms to strafe the field of battle, making an advance upon the gate itself impossible. The frost wyrm attacks must be stopped, but before we defile the bones of ancient dragons, we must gain permission from their queen.$B$BTravel southeast to Wyrmrest Temple and seek out Queen Alexstrasza. Tell her what we must do and ask her for guidance.$B$BGo now, $N!",logDesc="Seek out Alexstrasza the Life-Binder at Wyrmrest Temple in Dragonblight."} end
if not DB[12496] then DB[12496]={id=12496,zoneId=65,name="Audience With The Dragon Queen",level=74,minLevel=71,giver="Saurfang the Younger",giverType="NPC",giverId=25257,ender="3",enderType="NPC",enderId=26917,rewardNextId=12497,poiX=4900,poiY=1344,wowhead="https://www.wowhead.com/wotlk/quest=12496",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Though I know you hunger to destroy the Scourge that stand before us at the Wrath Gate, we must first deal with the threat that looms overhead. Until the strafing assaults of the frost wyrms are halted, we cannot move forward.$B$BBut before we assault the dying grounds of dragons, we must first be granted permission. Venture now to the hallowed halls of dragonkind: Wyrmrest Temple. Once there, seek out Queen Alexstrasza.$B$BRide now, $N! Southeast, to Wyrmrest!",logDesc="Seek out Alexstrasza the Life-Binder at Wyrmrest Temple in Dragonblight."} end
if not DB[12497] then DB[12497]={id=12497,zoneId=65,name="Galakrond and the Scourge",level=74,minLevel=71,giver="3",giverType="NPC",giverId=26917,ender="Torastrasza",enderType="NPC",enderId=26949,rewardNextId=12498,poiX=3531,poiY=271,wowhead="https://www.wowhead.com/wotlk/quest=12497",image="assets/images/quests/placeholder.png",desc="Atop the Wicked Coil, the Grand Necrolord of the Scourge, Antiok, sits upon the shoulders of the reconstructed storm giant lord, Thiassi. From there he commands the armies of undead to work day and night to unearth Galakrond's massive bones. Should they succeed in raising Galakrond, all of your efforts will have been for naught.$B$BWhile I cannot call down the full fury of the Red Dragonflight to assist you in your journey, I will grant you my blessing. Go now and speak with my majordomo, Torastrasza. ",logDesc="Speak with Torastrasza at Wyrmrest Temple in Dragonblight."} end
if not DB[12498] then DB[12498]={id=12498,zoneId=65,name="On Ruby Wings",level=74,minLevel=71,giver="Torastrasza",giverType="NPC",giverId=26949,ender="3",enderType="NPC",enderId=26917,poiX=3581,poiY=290,wowhead="https://www.wowhead.com/wotlk/quest=12498",image="assets/images/quests/placeholder.png",xpDiff=6,desc="Use this beacon to signal a Wyrmrest vanquisher. Climb upon its back and fly north to Galakrond's Rest. Once there, command the dragon to destroy the Scourge scavengers that work to unearth Galakrond. Once the area has been cleansed, fly to the Wicked Coil, overlooking Galakrond's Rest, to destroy Grand Necrolord Antiok and recover the scythe that he uses to control the wyrms.$B$BDo this and return to Queen Alexstrasza for a hero's reward!$B$B$N, beware the rotting storm giants that wander the area!",logDesc="Destroy 30 Wastes Scavengers and recover the Scythe of Antiok. Return to Alexstrasza the Life-Binder at Wyrmrest Temple should you complete this task.",choiceRewards={{id=38010,qty=1},{id=38053,qty=1},{id=38114,qty=1},{id=38073,qty=1}}} end
if not DB[12499] then DB[12499]={id=12499,zoneId=65,name="Return To Angrathar",level=74,minLevel=71,giver="3",giverType="NPC",giverId=26917,ender="Highlord Bolvar Fordragon",enderType="NPC",enderId=27872,poiX=3531,poiY=271,wowhead="https://www.wowhead.com/wotlk/quest=12499",image="assets/images/quests/placeholder.png",xpDiff=7,desc="With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth.$B$BThe time to make your final stand is now, $N. Return to Fordragon Hold and notify Highlord Fordragon.$B",logDesc="Speak with Highlord Bolvar Fordragon at Fordragon Hold and tell him of your victory over the Scourge.$B"} end
if not DB[12500] then DB[12500]={id=12500,zoneId=65,name="Return To Angrathar",level=74,minLevel=71,giver="3",giverType="NPC",giverId=26917,ender="Saurfang the Younger",enderType="NPC",enderId=25257,poiX=3531,poiY=271,wowhead="https://www.wowhead.com/wotlk/quest=12500",image="assets/images/quests/placeholder.png",xpDiff=7,desc="With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth.$B$BThe time to make your final stand is now, $N. Return to the Kor'kron Vanguard and notify Saurfang the Younger.",logDesc="Speak with Saurfang the Younger at the Kor'kron Vangaurd and tell him of your victory over the Scourge."} end
if not DB[12501] then DB[12501]={id=12501,zoneId=66,name="Troll Patrol",level=76,minLevel=74,giver="Commander Kunz",giverType="NPC",giverId=28039,ender="Commander Kunz",enderType="NPC",enderId=28039,poiX=5451,poiY=-2611,wowhead="https://www.wowhead.com/wotlk/quest=12501",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Unsheathe that weapon, $r. It's time to go on patrol!$b$bI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.$b$bYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.$b$bReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!$b$bDismissed!",logDesc="Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.$b$bCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'Valok."} end
if not DB[12502] then DB[12502]={id=12502,zoneId=66,name="Troll Patrol: High Standards",level=76,minLevel=74,giver="Captain Brandon",giverType="NPC",giverId=28042,ender="Captain Brandon",enderType="NPC",enderId=28042,poiX=5042,poiY=-3037,wowhead="https://www.wowhead.com/wotlk/quest=12502",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Listen, $c. This is the Argent Crusade. Our men will fight to the end and never complain no matter what the conditions.$b$bThat said, we've taken some heavy casualties in this campaign and we've been hitting it hard with little or no sleep for months. That all takes a toll on morale, whether we admit it or not.$b$bIt may not seem like much, but seeing our standard raised over the battlefield is of considerable comfort to a soldier. Take these banners and raise them at the pedestals in Drak'Sotra.",logDesc="Captain Brandon wants you to place the Argent Crusade Banner in the Drakkari Pedestals at Drak'Sotra."} end
if not DB[12503] then DB[12503]={id=12503,zoneId=66,name="Defend the Stand",level=76,minLevel=74,giver="Commander Falstaav",giverType="NPC",giverId=28059,ender="Commander Falstaav",enderType="NPC",enderId=28059,rewardNextId=12596,poiX=5440,poiY=-2569,wowhead="https://www.wowhead.com/wotlk/quest=12503",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Despite our substantial successes in the lower third of Zul'Drak, we must still face the onslaught of the Scourge. Such is the way in this frigid hell.$B$BThe attacks are unrelenting, yet my men need rest. If you are willing, we could use your aid in reinforcing them.$B$BBelow in the courtyard you'll find no end to the fighting. Dispatch the Scourge there with all the zeal you can muster, $c.",logDesc="Commander Falstaav has tasked you with the destruction of any 10 Scourge in the courtyard at The Argent Stand."} end
if not DB[12504] then DB[12504]={id=12504,zoneId=66,name="Argent Crusade, We Are Leaving!",level=76,minLevel=74,giver="Sergeant Stackhammer",giverType="NPC",giverId=28056,ender="Sergeant Stackhammer",enderType="NPC",enderId=28056,poiX=6064,poiY=-2618,wowhead="https://www.wowhead.com/wotlk/quest=12504",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="<The sergeant quickly reads through the orders you've handed him, a frown coming over his face.>$B$BLook, $g lad : lass;, I'd love to just up and leave, but take a look out there. All of my people are fighting.$B$BTell you what, you've come this far, you think you're up to doing me a small favor? Head out there and round up my soldiers?$B$BTell 'em that the sergeant orders them to report back immediately. Lend them a hand if you will.",logDesc="Sergeant Stackhammer at the Altar of Sseratus wants you to speak with 10 of his Argent Soldiers and tell them to report back to him.",choiceRewards={{id=39771,qty=1},{id=39834,qty=1},{id=39780,qty=1},{id=39782,qty=1}}} end
if not DB[12505] then DB[12505]={id=12505,zoneId=66,name="New Orders for Sergeant Stackhammer",level=76,minLevel=74,giver="Commander Kunz",giverType="NPC",giverId=28039,ender="Sergeant Stackhammer",enderType="NPC",enderId=28056,rewardNextId=12504,poiX=5451,poiY=-2611,wowhead="https://www.wowhead.com/wotlk/quest=12505",image="assets/images/quests/placeholder.png",xpDiff=1,money=6200,desc="$C, you're here to help, right? I've got new orders for our forces that are currently deployed at the Drakkari altar to the north.$B$BYou can't miss it. Just head straight up the avenue. Sergeant Stackhammer shouldn't be hard to find.",logDesc="Commander Kunz has asked you to deliver the New Deployment Orders to Sergeant Stackhammer at the Altar of Sseratus."} end
if not DB[12506] then DB[12506]={id=12506,zoneId=66,name="Trouble at the Altar of Sseratus",level=76,minLevel=74,giver="Hexxer Ubungo",giverType="NPC",giverId=28062,ender="Hexxer Ubungo",enderType="NPC",enderId=28062,poiX=5485,poiY=-2624,wowhead="https://www.wowhead.com/wotlk/quest=12506",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="There's trouble at the altar of the snake god.$B$BThe presence of the Scourge has weakened the land, $r. This in turn has weakened the wild gods.$B$BWe know that the Drakkari are taking advantage of this to do evil things to the gods.$B$BI need you to be my eyes and ears. The Altar of Sseratus is at the end of the avenue to the north. Sneak around the back and get a look inside of the main altar building.$B$BWhatever you do, avoid the prophet at all costs!",logDesc="Hexxer Ubungo at The Argent Stand has asked you to investigate the main altar building at the Altar of Sseratus."} end
if not DB[12507] then DB[12507]={id=12507,zoneId=66,name="Strange Mojo",level=76,minLevel=74,ender="Hexxer Ubungo",enderType="NPC",enderId=28062,rewardNextId=12510,wowhead="https://www.wowhead.com/wotlk/quest=12507",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="This bottle of strange mojo may be the key to what is truly going on here.$B$BThe Zandalari troll Hexxer Ubungo, back at The Argent Stand, may want to take a look at it.",logDesc="Deliver the Strange Mojo to Hexxer Ubungo at The Argent Stand."} end
if not DB[12508] then DB[12508]={id=12508,zoneId=66,name="Mopping Up",level=76,minLevel=74,giver="Corporal Maga",giverType="NPC",giverId=28099,ender="Corporal Maga",enderType="NPC",enderId=28099,poiX=6064,poiY=-2616,wowhead="https://www.wowhead.com/wotlk/quest=12508",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="I couldn't help but overhear what you were talking to the sergeant about. That doesn't change the fact that we still have a job to do here.$B$BWhile you're out there, do you think you could help us to put some of those followers of Sseratus out of their misery?",logDesc="Corporal Maga at the Altar of Sseratus wants you to kill any combination of 10 Champions of Sseratus, Priests of Sseratus, or Drakkari Snake Handlers."} end
if not DB[12509] then DB[12509]={id=12509,zoneId=66,name="Troll Patrol: Intestinal Fortitude",level=76,minLevel=74,giver="Captain Rupert",giverType="NPC",giverId=28044,ender="Captain Rupert",enderType="NPC",enderId=28044,poiX=5258,poiY=-3500,wowhead="https://www.wowhead.com/wotlk/quest=12509",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Finally, the patrol arrives!$b$bHere's the situation, $r. We've lost many of our finest soldiers in this campaign and have had to call upon our recruits to fill in the gaps.$b$bWe've just fought one of our fiercest battles and many of the recruits were simply not prepared to face this enemy. There are more fights ahead, and I need them ready to follow orders.$b$bIf there's one thing I can't stomach, it's cowardice. Perhaps you can help them find the courage to continue. ",logDesc="Captain Rupert in Drak'Sotra wants you to restore courage to the cowering Crusade Recruits."} end
if not DB[12510] then DB[12510]={id=12510,zoneId=66,name="Precious Elemental Fluids",level=76,minLevel=74,giver="Hexxer Ubungo",giverType="NPC",giverId=28062,ender="Hexxer Ubungo",enderType="NPC",enderId=28062,rewardNextId=12514,poiX=5485,poiY=-2624,wowhead="https://www.wowhead.com/wotlk/quest=12510",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="<The hexxer examines the decanter of mojo.>$B$BI have an idea for how to deal with the prophet of Sseratus. But first, we're going to need some things.$B$BThe Drak'Sotra Fields are directly to the south. Because of the stresses on the land from the Scourge and the deaths of gods, the wall between worlds has weakened and the elementals are flooding in.$B$BWe need the precious fluids of their lords. If you combine three links from the elementals a tether will be made, and one of their lords can be summoned.",logDesc="Hexxer Ubungo at The Argent Stand wants you to acquire 3 Precious Elemental Fluids.",choiceRewards={{id=39781,qty=1},{id=39842,qty=1},{id=39803,qty=1},{id=39805,qty=1}}} end
if not DB[12511] then DB[12511]={id=12511,zoneId=394,name="The Hills Have Us",level=73,minLevel=73,giver="Gryphon Commander Urik",giverType="NPC",giverId=27317,ender="Lieutenant Dumont",enderType="NPC",enderId=26875,poiX=3701,poiY=-697,wowhead="https://www.wowhead.com/wotlk/quest=12511",image="assets/images/quests/placeholder.png",xpDiff=2,desc="While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills. All in hopes of finding an alternate route into Icecrown.$B$BLieutenant Dumont, stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?",logDesc="Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills.$B"} end
if not DB[12512] then DB[12512]={id=12512,zoneId=66,name="Leave No One Behind",level=76,minLevel=74,giver="Dr. Rogers",giverType="NPC",giverId=28125,ender="Dr. Rogers",enderType="NPC",enderId=28125,poiX=5255,poiY=-3530,wowhead="https://www.wowhead.com/wotlk/quest=12512",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Ahh, good. They sent someone.$b$bListen, $r. We need a hand here. Our forces were pushed back and we've lost Drak'Sotra to the Scourge. Where they came from is anyone's guess....$b$bThe point is, we need every man we can get here, and some of our best have yet to return from battle.$b$bI need you to enter the ruins now that the fighting has died down and find our wounded, patch them up, and bring them here to me.$b$bScour Drak'Sotra! They couldn't have gone far.",logDesc="Dr. Rogers at Drak'Sotra wants you to find Crusader Lamoof, Crusader Jonathan, and Crusader Josephine. Use the Crusader's Bandage on them, and escort them safely back to him.",choiceRewards={{id=39807,qty=1},{id=39868,qty=1},{id=39857,qty=1},{id=39860,qty=1}}} end
if not DB[12513] then DB[12513]={id=12513,zoneId=1941,name="Nice Hat...",level=68,minLevel=66,giver="Don Carlos",giverType="NPC",giverId=28126,ender="Don Carlos",enderType="NPC",enderId=28126,poiX=-7202,poiY=-3934,wowhead="https://www.wowhead.com/wotlk/quest=12513",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My hat? Yes, it's an unusual style, I know, from far away... few tailors here know how to make them.$B$BWhen I was young and hot-blooded, I wore it as a standing challenge. Many came seeking to defeat me and win it for themselves... but no one ever did.$B$BAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no longer duel.",logDesc="Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos' Hat to him in Tanaris as proof.",rewards={{id=38276,qty=1}}} end
if not DB[12514] then DB[12514]={id=12514,zoneId=66,name="Mushroom Mixer",level=76,minLevel=74,giver="Hexxer Ubungo",giverType="NPC",giverId=28062,ender="Hexxer Ubungo",enderType="NPC",enderId=28062,poiX=5485,poiY=-2624,wowhead="https://www.wowhead.com/wotlk/quest=12514",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Now what we need is something to spike the mojo with. Something that'll make it so that when the prophet drinks it, he'll become less powerful.$B$BDrak'Agal lies to the east. There's a mushroom there that the natives call muddlecap fungus. I think it's exactly what we need.$B$BBring back lots of them. When we mix them into the mojo, the mind of anyone who drinks it will become muddled.",logDesc="Collect 10 Muddlecap Fungus and deliver them to Hexxer Ubungo at The Argent Stand."} end
if not DB[12515] then DB[12515]={id=12515,zoneId=1941,name="Nice Hat...",level=68,minLevel=66,wowhead="https://www.wowhead.com/wotlk/quest=12515",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My hat? Yes, it's an unusual style, I know, from far away... few tailors here know how to make them.$B$BWhen I was young and hot-blooded, I wore it as a standing challenge. Many came seeking to defeat me and win it for themselves... but no one ever did.$B$BAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no longer duel.",logDesc="Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos' Hat to him in Tanaris as proof.",rewards={{id=38276,qty=1}}} end
if not DB[12516] then DB[12516]={id=12516,zoneId=66,name="Too Much of a Good Thing",level=76,minLevel=74,giver="Hexxer Ubungo",giverType="NPC",giverId=28062,ender="Hexxer Ubungo",enderType="NPC",enderId=28062,rewardNextId=12623,poiX=5485,poiY=-2624,wowhead="https://www.wowhead.com/wotlk/quest=12516",image="assets/images/quests/placeholder.png",xpDiff=6,money=124000,desc="There. I've modified the mojo. Now when the prophet drinks it, not only will he lose some of his power, his mind will also be addled by the effects of the fungus.$B$BAt least that's the theory.$B$BAs for how to get him to drink it, might I suggest you simply throw it at him? No doubt he'll catch and drink it given the arrogance that he's displayed at the altar.$B$BUnless you can kill him, $c, your Argent Crusade is about to come to a terrible end.",logDesc="Slay the Muddled Prophet of Sseratus and then return to Hexxer Ubungo at The Argent Stand.",choiceRewards={{id=39785,qty=1},{id=39843,qty=1},{id=39815,qty=1},{id=39817,qty=1}}} end
if not DB[12517] then DB[12517]={id=12517,zoneId=0,name="Rogues Deck",level=15,minLevel=10,ender="Darkmoon Fortune Teller",enderType="NPC",enderId=30481,wowhead="https://www.wowhead.com/wotlk/quest=12517",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Now that you have gathered all of the Rogue cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.$b$bYou feel the card could be used to communicate with someone or something.",logDesc="Use the Rogues Deck to summon a Darkmoon Fortune Teller and give the deck to them.",choiceRewards={{id=38318,qty=1},{id=39509,qty=1},{id=39507,qty=1}}} end
if not DB[12518] then DB[12518]={id=12518,zoneId=0,name="Mages Deck",level=35,minLevel=30,ender="Darkmoon Fortune Teller",enderType="NPC",enderId=30481,wowhead="https://www.wowhead.com/wotlk/quest=12518",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Now that you have gathered all of the Mage cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.$b$bYou feel the card could be used to communicate with someone or something.",logDesc="Use the Mages Deck to summon a Darkmoon Fortune Teller and give the deck to them.",choiceRewards={{id=44215,qty=1},{id=44213,qty=1}}} end
if not DB[12519] then DB[12519]={id=12519,zoneId=66,name="Troll Patrol: Whatdya Want, a Medal?",level=76,minLevel=74,giver="Captain Grondel",giverType="NPC",giverId=28043,ender="Captain Grondel",enderType="NPC",enderId=28043,poiX=5542,poiY=-3004,wowhead="https://www.wowhead.com/wotlk/quest=12519",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Look at me, $r. Do I look like I have time fer fillin' out reports?$b$bIt be all I can do to keep this post free o' the bloody Scourge, and they want me to mess with paperwork!$b$b<sigh> No sense in complainin'. I need to get the commander some kinda kill count from the last skirmish.$b$bYou wanna be helpful? Go and get me all the medals you can find from the dead trolls around here. That'll hafta be close enough.",logDesc="Captain Grondel outside the Coliseum wants you to gather 7 Drakkari Medallions from the nearby Drakkari Corpses."} end
if not DB[12520] then DB[12520]={id=12520,zoneId=3711,name="Rhino Mastery: The Test",level=76,minLevel=76,giver="Hemet Nesingwary",giverType="NPC",giverId=27986,ender="Hemet Nesingwary",enderType="NPC",enderId=27986,rewardNextId=12526,poiX=5584,poiY=5749,wowhead="https://www.wowhead.com/wotlk/quest=12520",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="No rough landing is going to stop ol' Hemet from mastering the largest game Sholazar has to offer. In the wilds northwest of the camp, the jungles are ruled by the mighty shardhorn rhino. You can prove your worth to the expedition, $g lad:lass;, by showing me that you're tough enough to face down those powerful beasts.",logDesc="Kill 15 Shardhorn Rhinos and return to Hemet Nesingwary at the Nesingwary Base Camp."} end
if not DB[12521] then DB[12521]={id=12521,zoneId=3711,name="Where in the World is Hemet Nesingwary?",level=76,minLevel=76,giver="3",giverType="NPC",giverId=28160,ender="Monte Muzzleshot",enderType="NPC",enderId=27987,rewardNextId=12489,poiX=5834,poiY=484,wowhead="https://www.wowhead.com/wotlk/quest=12521",image="assets/images/quests/placeholder.png",xpDiff=1,desc="When I heard that the legendary Hemet Nesingwary was setting sail for the Sholazar Basin, I offered to help fund his expedition. We know little of Sholazar,  but it's said to be a lush paradise in the midst of this frozen continent.$B$BHemet has agreed to send back samples of exotic plants, reagents, and crystals. There hasn't been any word from him. Monte Muzzleshot was supposed to be bringing them supplies, but he hasn't returned, either. If you'll look into it, I'll send you in my flying machine.",logDesc="Talk to Archmage Pentarus when you're ready to leave for Sholazar Basin. When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin."} end
if not DB[12522] then DB[12522]={id=12522,zoneId=3711,name="Need an Engine, Take an Engine",level=76,minLevel=76,giver="Weslex Quickwrench",giverType="NPC",giverId=28033,ender="Weslex Quickwrench",enderType="NPC",enderId=28033,rewardNextId=12523,poiX=5589,poiY=5825,wowhead="https://www.wowhead.com/wotlk/quest=12522",image="assets/images/quests/placeholder.png",xpDiff=4,money=48000,desc="She's ruined... ruined! I told that captain to be careful with such a precious cargo, but would she listen to me? No!$B$BWhen the ship ran aground, it damaged my flying machine, the Spirit of Gnomeregan. Now, we're left without any means to send our reports!$B$BThere is a chance, though, that the Venture Company's antics may work in our favor. They shot down another flying machine right about where Monte parachuted into the swamp to the east. Go there and retrieve the engine. It may be our only hope.",logDesc="Weslex Quickwrench at the Nesingwary Base Camp wants you to bring him a Flying Machine Engine."} end
if not DB[12523] then DB[12523]={id=12523,zoneId=3711,name="Have a Part, Give a Part",level=76,minLevel=76,giver="Weslex Quickwrench",giverType="NPC",giverId=28033,ender="Weslex Quickwrench",enderType="NPC",enderId=28033,poiX=5589,poiY=5825,wowhead="https://www.wowhead.com/wotlk/quest=12523",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Great, now that we've got an engine, we're going to need an assortment of other parts to get her back in flying condition. Don't worry, I know what I'm doing.$B$BA good mechanic can hold his creations together with anything, but we're better off if it doesn't come to that.$B$BAnyway, those Venture Company dullards have plenty of spare parts for their mining equipment all over Swindlegrin's Dig on the far side of that yellow crystal pillar to the northeast. Scoop up a few and bring them back here.",logDesc="Bring 7 Venture Co. Spare Parts to Weslex Quickwrench at the Nesingwary Base Camp."} end
if not DB[12524] then DB[12524]={id=12524,zoneId=3711,name="Venture Co. Misadventure",level=76,minLevel=76,giver="Debaar",giverType="NPC",giverId=28032,ender="Debaar",enderType="NPC",enderId=28032,rewardNextId=12525,poiX=5548,poiY=5742,wowhead="https://www.wowhead.com/wotlk/quest=12524",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Ever since we arrived, the Venture Company has hampered our efforts to secure our campsite and survey the area. Normally, we wouldn't care what they were up to, but they've started antagonizing our scouts and shooting down supply flights.$B$BWe can't allow this insult to stand. Hemet Nesingwary's expedition came here to hunt, and hunt it shall.$B$BGo to Swindlegrin's Dig, on the far side of the crystal pillar to the northeast, and kill any Venture Company employee you see!",logDesc="Debaar at the Nesingwary Base Camp wants you to kill 15 Venture Company members. You may kill either Venture Co. Ruffians or Venture Co. Excavators."} end
if not DB[12525] then DB[12525]={id=12525,zoneId=3711,name="Wipe That Grin Off His Face",level=76,minLevel=76,giver="Debaar",giverType="NPC",giverId=28032,ender="Debaar",enderType="NPC",enderId=28032,poiX=5548,poiY=5742,wowhead="https://www.wowhead.com/wotlk/quest=12525",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="We must send Foreman Swindlegrin packing if we're going to shut down his mine permanently, but be careful. His bodyguard, Meatpie, is a large, mean ogre, and  isn't likely to let you see the foreman without a fight.$B$BThe two probably occupy a platform that would let them look out over the entire Venture Company operation at Swindlegrin's Dig.$B$BRemember, the dig is on the far side of the Suntouched Pillar to the northeast. Good luck, $N.",logDesc="Kill Foreman Swindlegrin and Meatpie and return to Debaar at the Nesingwary Base Camp.",choiceRewards={{id=39332,qty=1},{id=39376,qty=1},{id=39430,qty=1},{id=39452,qty=1}}} end
if not DB[12526] then DB[12526]={id=12526,zoneId=3711,name="Rhino Mastery: The Chase",level=76,minLevel=76,giver="Hemet Nesingwary",giverType="NPC",giverId=27986,ender="Oracle Soo-rahm",enderType="NPC",enderId=28191,rewardNextId=12543,poiX=5584,poiY=5749,wowhead="https://www.wowhead.com/wotlk/quest=12526",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Well, that's settled then. We'll seek out this native sage and have a word with him. He's not likely to volunteer his services, though.$B$BI'm told he keeps a small lean-to near the Bones of Nozronn, just across the river to the south. Seek him out, introduce yourself, and ask what he requires to help us track down this patriarch of the rhinos.",logDesc="Speak to Oracle Soo-rahm at the Bones of Nozronn."} end
if not DB[12527] then DB[12527]={id=12527,zoneId=66,name="Gluttonous Lurkers",level=76,minLevel=74,giver="Apprentice Pestlepot",giverType="NPC",giverId=28204,ender="Alchemist Finklestein",enderType="NPC",enderId=28205,poiX=5501,poiY=-2664,wowhead="https://www.wowhead.com/wotlk/quest=12527",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="My master, Finklestein, is in the shrine at Heb'Valok to the northwest preparing a truth serum, and he needs basilisk crystals. Heb'Valok is on the west side of the road leading north before the Altar of Sseratus.$B$BThere are basilisks to the east at Drak'Agal.$B$BIf you grab the Zul'Drak rats and throw them at the basilisk, they will become gorged and docile after eating five. Then you'll be able to take their crystals.$B$BKilling the basilisk won't do you any good. That'd just break its crystals!",logDesc="Deliver 5 Basilisk Crystals to Alchemist Finklestein in the shrine at Heb'Valok."} end
if not DB[12528] then DB[12528]={id=12528,zoneId=3711,name="Playing Along",level=77,minLevel=76,giver="Tracker Gekgek",giverType="NPC",giverId=28095,ender="High-Shaman Rakjak",enderType="NPC",enderId=28082,rewardNextId=12529,poiX=5063,poiY=4728,wowhead="https://www.wowhead.com/wotlk/quest=12528",image="assets/images/quests/placeholder.png",xpDiff=2,money=16600,desc="My kill! You take my kill!$B$B<Gekgek taunts you with his spear.>$B$BYou dumb, $r. Now you owe Gekgek! You be Frenzyheart slave. You slay many more beasts for Frenzyheart.$B$BYou go Frenzyheart Hill to northeast - you tell High-Shaman Rakjak you the new slave.$B$BGo, $r! Go or I taunt you a second time!$B$B<Gekgek waves his spear around menacingly.>",logDesc="Report to High-Shaman Rakjak at Frenzyheart Hill as the new \"slave.\""} end
if not DB[12529] then DB[12529]={id=12529,zoneId=3711,name="The Ape Hunter's Slave",level=77,minLevel=76,giver="High-Shaman Rakjak",giverType="NPC",giverId=28082,ender="High-Shaman Rakjak",enderType="NPC",enderId=28082,poiX=5281,poiY=4534,wowhead="https://www.wowhead.com/wotlk/quest=12529",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="You think you so great hunter, eh? You no Frenzyheart, you not know of hunt.$B$BGoregek is great ape hunter. He slay so many ape you can't count on claws.$B$BYou go with Goregek and hunt hardknuckles to east. You the slave, $r. You do what Goregek tell you.",logDesc="Kill 8 Hardknuckle Foragers and 6 Hardknuckle Chargers for High-Shaman Rakjak at Frenzyheart Hill.$B$BIf you lose Goregek's Shackles, speak to Elder Harkek in Frenzyheart Hill."} end
if not DB[12530] then DB[12530]={id=12530,zoneId=3711,name="Tormenting the Softknuckles",level=77,minLevel=76,giver="Goregek the Gorilla Hunter",giverType="NPC",giverId=28214,ender="High-Shaman Rakjak",enderType="NPC",enderId=28082,wowhead="https://www.wowhead.com/wotlk/quest=12530",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Slave thing!$B$BRakjak want me to babysit you while I kill hardknuckles. I feeling generous today, so I let you kill some too, but don't get in Goregek's way!$B$BRakjak not know yet, but Goregek has eye on big bad hardknuckle mama. We go to Hardknuckle Clearing to east and poke softknuckles with poker and she sure to come yelling!$B$B<Goregek rubs his hands together gleefully.>",logDesc="Goregek has given you a Softknuckle Poker for use on Softknuckles to draw the Hardknuckle Matriarch out of hiding. Slay the Hardknuckle Matriarch and report her death to High-Shaman Rajak at Frenzyheart Hill.$B$BIf you lose Goregek's Shackles, speak to Elder Harkek in Frenzyheart Hill."} end
if not DB[12531] then DB[12531]={id=12531,zoneId=3711,name="The Underground Menace",level=77,minLevel=76,giver="Elder Harkek",giverType="NPC",giverId=28138,ender="High-Shaman Rakjak",enderType="NPC",enderId=28082,poiX=5264,poiY=4511,wowhead="https://www.wowhead.com/wotlk/quest=12531",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Lion killer, chicken chaser, new Frenzyheart slave...$B$BI know you no want to stay slave, so I tell you what to do. Show you better than the other Frenzyheart hunters and then Rakjak respect you.$B$BUnder sands of south river there a beast that kills wasp, apes, and even wolvar. He called Serfex. You bring claw of Serfex to Rakjak and maybe he release you from slaveness.$B$BHope Dajik teaching you good so Serfex be easy stuff.",logDesc="Locate Serfex under the sands of the southern river, slay him, and bring his claw to High-Shaman Rakjak at Frenzyheart Hill.$B$BIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill."} end
if not DB[12532] then DB[12532]={id=12532,zoneId=3711,name="Flown the Coop!",level=77,minLevel=76,giver="Elder Harkek",giverType="NPC",giverId=28138,ender="Elder Harkek",enderType="NPC",enderId=28138,rewardNextId=12531,poiX=5264,poiY=4511,wowhead="https://www.wowhead.com/wotlk/quest=12532",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Dumb Goregek stumble into chicken house and let all the chickens go!$B$BThey all around hill - go get chickens back!$B$B<Elder Harkek shoos you away.>",logDesc="Capture 12 Chicken Escapees for Elder Harkek.$B$BIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.",choiceRewards={{id=39337,qty=1},{id=39383,qty=1},{id=39435,qty=1},{id=39455,qty=1}}} end
if not DB[12533] then DB[12533]={id=12533,zoneId=3711,name="The Wasp Hunter's Apprentice",level=77,minLevel=76,giver="High-Shaman Rakjak",giverType="NPC",giverId=28082,ender="High-Shaman Rakjak",enderType="NPC",enderId=28082,poiX=5281,poiY=4534,wowhead="https://www.wowhead.com/wotlk/quest=12533",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Rakjak not dumb. Maybe you good at killing things. Maybe Frenzyheart can make you into real hunter.$B$BDajik hunts giant wasp things better than all wolvar. Go with Dajik to Sapphire Hive to southeast or to river in south and learn the hunt.",logDesc="Kill 6 Sapphire Hive Wasps and 9 Sapphire Hive Drones for High-Shaman Rakjak in Frenzyheart Hill.$B$BIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill."} end
if not DB[12534] then DB[12534]={id=12534,zoneId=3711,name="The Sapphire Queen",level=77,minLevel=76,giver="Elder Harkek",giverType="NPC",giverId=28138,ender="High-Shaman Rakjak",enderType="NPC",enderId=28082,poiX=5264,poiY=4511,wowhead="https://www.wowhead.com/wotlk/quest=12534",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Bristlepine can be dangerous, but most stay far away from wolvar. Wasps on other hand not fear the Frenzyheart... they even kill some of our hunters.$B$BI know Rakjak want wasp queen dead, but no wolvar want to go into her hive. You go kill wasp queen in Sapphire Hive to southeast and get stinger for Rakjak. Me bet Rakjak like that. ",logDesc="Bring the Stinger of the Sapphire Queen to High-Shaman Rakjak at Frenzyheart Hill.$B$BIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.",choiceRewards={{id=39346,qty=1},{id=39387,qty=1},{id=39436,qty=1},{id=39450,qty=1}}} end
if not DB[12535] then DB[12535]={id=12535,zoneId=3711,name="Mischief in the Making",level=77,minLevel=76,giver="High-Shaman Rakjak",giverType="NPC",giverId=28082,ender="High-Shaman Rakjak",enderType="NPC",enderId=28082,poiX=5281,poiY=4534,wowhead="https://www.wowhead.com/wotlk/quest=12535",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="You good hunter, but Frenzyheart can make you stronger. Harkek think maybe you ready for something more important.$B$BBefore Rakjak send you on important mission, you need gather things for Rakjak. All along river to south are blue crystals. Rakjak need lots of blue crystals.$B$BYou go get crystals now.",logDesc="High-Shaman Rakjak at Frenzyheart Hill wants 8 Skyreach Crystal Clusters."} end
if not DB[12536] then DB[12536]={id=12536,zoneId=3711,name="A Rough Ride",level=77,minLevel=76,giver="High-Shaman Rakjak",giverType="NPC",giverId=28082,ender="Zepik the Gorloc Hunter",enderType="NPC",enderId=28216,poiX=5281,poiY=4534,wowhead="https://www.wowhead.com/wotlk/quest=12536",image="assets/images/quests/placeholder.png",xpDiff=2,money=16600,desc="Zepik is best hunter of the Frenzyheart. Zepik hunts big-tongues... ugly things near swamps that try to steal all stuff they can find.$B$BZepik going on long trek to break big-tongue shrine and try to scare them away. We no want big-tongues in this land anymore.$B$BThere a crocolisk chained on northeast side of hill, next to tree - go with Zepik and do what Zepik tell you.",logDesc="Ride the captive crocolisk to Mistwhisper Refuge and then speak to Zepik for further instructions.$B$BIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill."} end
if not DB[12537] then DB[12537]={id=12537,zoneId=3711,name="Lightning Definitely Strikes Twice",level=77,minLevel=76,giver="Zepik the Gorloc Hunter",giverType="NPC",giverId=28216,ender="Zepik the Gorloc Hunter",enderType="NPC",enderId=28216,wowhead="https://www.wowhead.com/wotlk/quest=12537",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Okay, the crystal things...$B$BThe big-tongues use the crystals to power their rain shrines. Zepik not know quite how it works, but Zepik does know that if they use wrong crystals, the clouds and the rain go crazy!$B$BZepik tried to sneak in at one of their other rain shrines, but it not go so well. It sure to go much better with two!$B$BTake crystals, place at big stone pillar shrine thing, then smash them to release power. Zepik not sure what will happen, so might want to step back after.",logDesc="Zepik wants you to smash the Skyreach Crystal Clusters in front of the Mistwhisper weather shrine.$B$BIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.",choiceRewards={{id=39347,qty=1},{id=39400,qty=1},{id=39437,qty=1},{id=39457,qty=1}}} end
if not DB[12538] then DB[12538]={id=12538,zoneId=3711,name="The Mist Isn't Listening",level=77,minLevel=76,giver="Zepik the Gorloc Hunter",giverType="NPC",giverId=28216,ender="Zepik the Gorloc Hunter",enderType="NPC",enderId=28216,wowhead="https://www.wowhead.com/wotlk/quest=12538",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Gorillas and wasps are boring! Big-tongues the only thing fun to hunt.$B$BWhile we mess up rain shrine, we kill lots of mist big-tongues. That sure to make them not want to come back to village thing.$B$B<Zepik nods to himself confidently.>",logDesc="Zepik wants you to kill 12 Mistwhisper Gorlocs.$B$BIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill."} end
if not DB[12539] then DB[12539]={id=12539,zoneId=3711,name="Hoofing It",level=77,minLevel=76,giver="Zepik the Gorloc Hunter",giverType="NPC",giverId=28216,ender="High-Shaman Rakjak",enderType="NPC",enderId=28082,rewardNextId=12540,wowhead="https://www.wowhead.com/wotlk/quest=12539",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Okay, we done! Time to go back. No crocolisk to ride this time though.$B$BIf we go east and stay near ridge, it should lead all the way back near hill.$B$BNeed to be careful not to go far below ridge though or we might go right into big-tongue tree village thing. Zepik not think they like us right now.",logDesc="Find your way back to Frenzyheart Hill and speak to High-Shaman Rakjak."} end
if not DB[12540] then DB[12540]={id=12540,zoneId=3711,name="Just Following Orders",level=77,minLevel=76,giver="High-Shaman Rakjak",giverType="NPC",giverId=28082,ender="Injured Rainspeaker Oracle",enderType="NPC",enderId=28217,poiX=5281,poiY=4534,wowhead="https://www.wowhead.com/wotlk/quest=12540",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Okay $g guy:lady;, Rakjak have very important job. You go capture injured big-tongue that tracker spotted at river to north.$B$BNot bring hunter this time because they maybe want to just kill it. I want to hide it so that I can poke it and make it tell me things.$B$BGo you and bring me big-tongue prize thing.",logDesc="Locate an Injured Rainspeaker Oracle for High-Shaman Rakjak at Frenzyheart Hill.$B"} end
if not DB[12541] then DB[12541]={id=12541,zoneId=66,name="Troll Patrol: The Alchemist's Apprentice",level=76,minLevel=74,giver="Alchemist Finklestein",giverType="NPC",giverId=28205,ender="Alchemist Finklestein",enderType="NPC",enderId=28205,poiX=5934,poiY=-2349,wowhead="https://www.wowhead.com/wotlk/quest=12541",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.$b$bWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.$b$bCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.$b$bLet me know when you're ready, $r. And remember, timing is everything!$B",logDesc="Alchemist Finklestein at Heb'Valok wants you to assist him in the creation of a truth serum.$b$bWhen you are ready to begin, you are to speak to him and follow his instructions."} end
if not DB[12542] then DB[12542]={id=12542,zoneId=65,name="The Call Of The Crusade",level=74,minLevel=74,giver="Tilda Darathan",giverType="NPC",giverId=27348,ender="Crusader Valus",enderType="NPC",enderId=28228,rewardNextId=12545,poiX=3429,poiY=-1266,wowhead="https://www.wowhead.com/wotlk/quest=12542",image="assets/images/quests/placeholder.png",xpDiff=2,desc="$C! The Argent Crusade is looking for able bodied soldiers that are willing to set aside their differences and join forces to battle the forces of the Lich King. Will you take up our cause?$B$BShould you be interested, venture north to Light's Trust and speak with Crusader Valus.$B$BYou will find Light's Trust amidst the ruins of the sacked troll city of Jintha'kalar - bordering Zul'Drak.$B$BFarewell. ",logDesc="Report to Crusader Valus at Light's Trust in Dragonblight.$B"} end
if not DB[12543] then DB[12543]={id=12543,zoneId=3711,name="An Offering for Soo-rahm",level=76,minLevel=76,giver="Oracle Soo-rahm",giverType="NPC",giverId=28191,ender="Oracle Soo-rahm",enderType="NPC",enderId=28191,rewardNextId=12544,poiX=5355,poiY=5814,wowhead="https://www.wowhead.com/wotlk/quest=12543",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="We not know you, stranger, but we know you want something.$B$BWe will talk to Bones of Nozronn for you, but you must bring us offerings. We need powerful emperor cobra fangs to complete our oracle's necklace.$B$BGo to the Wildgrowth Mangal, northeast of our hut, find cobras and bring back best fangs. Then we make bones speak to you.",logDesc="Bring 5 Intact Cobra Fangs to Oracle Soo-rahm, near the Bones of Nozronn."} end
if not DB[12544] then DB[12544]={id=12544,zoneId=3711,name="The Bones of Nozronn",level=76,minLevel=76,giver="Oracle Soo-rahm",giverType="NPC",giverId=28191,ender="Hemet Nesingwary",enderType="NPC",enderId=27986,poiX=5355,poiY=5814,wowhead="https://www.wowhead.com/wotlk/quest=12544",image="assets/images/quests/placeholder.png",xpDiff=4,money=48000,desc="Bones of Nozronn, Oracle Soo-rahm sends $N to you!$B$BWe have prepared incense for you. Light it and place it near Nozronn's head and you will hear his voice.$B$B<Confused, you tell Soo-rahm that you haven't even told him your question.>$B$BTrue, we not know, but mighty Nozronn does. Do not doubt. Nozronn will answer your heart's question.$B$BGo. Nozronn not wait long.",logDesc="Use Soo-rahm's Incense near the Bones of Nozronn, then return to Hemet Nesingwary at Nesingwary's Base Camp with the information you learned."} end
if not DB[12545] then DB[12545]={id=12545,zoneId=65,name="The Cleansing Of Jintha'kalar",level=74,minLevel=74,giver="Crusader Valus",giverType="NPC",giverId=28228,ender="Crusader Valus",enderType="NPC",enderId=28228,poiX=4599,poiY=-1083,wowhead="https://www.wowhead.com/wotlk/quest=12545",image="assets/images/quests/placeholder.png",xpDiff=5,money=56000,desc="We wrested this ancient Drakkari temple from a swarm of invading Scourge. Not more than one-hundred paces from where we stand is the ruined city of Jintha'kalar. Scourge necromancers run amok, turning the living Drakkari trolls that remain into servants of the Lich King.$B$BAll are now lost to the Light. All must be purged.$B$B<Valus looks upon you sternly.>$B$BAll.",logDesc="Crusader Valus at Light's Trust in Dragonblight has asked you to slay 15 Jintha'kalar Scourge.",choiceRewards={{id=38190,qty=1},{id=38188,qty=1},{id=38198,qty=1},{id=38207,qty=1},{id=38206,qty=1}}} end
if not DB[12546] then DB[12546]={id=12546,zoneId=3711,name="Reclamation",level=78,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="3",enderType="NPC",enderId=27801,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12546",image="assets/images/quests/placeholder.png",xpDiff=7,money=204000,desc="It is time, $N.  The Etymidian is one of the most destructive forces ever created by the titans and I am loathe to unleash him in my lands.$B$BThere is little choice, however.  Our enemies have forced my hand and the fury of the titans will cleanse all.",logDesc="Go to the Avalanche in Sholazar Basin and use the Omega Rune to deploy Etymidian.  Use him to slay 200 Scourge Minions, Bythius the Flesh-Shaper, Urgreth of the Thousand Tombs and Hailscorn.$B$BSpeak to the Avatar of Freya in Sholazar Basin when you've completed this task.",choiceRewards={{id=40290,qty=1},{id=40291,qty=1},{id=40292,qty=1},{id=40293,qty=1},{id=40295,qty=1}}} end
if not DB[12547] then DB[12547]={id=12547,zoneId=490,name="The Activation Rune",level=78,minLevel=77,giver="The Etymidian",giverType="NPC",giverId=28092,ender="The Etymidian",enderType="NPC",enderId=28092,rewardNextId=12797,poiX=-6194,poiY=-1220,wowhead="https://www.wowhead.com/wotlk/quest=12547",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="This colossal being appears to be inactive.  You notice an empty rune-shaped slot on its chest.$B$BPerhaps you might be able to find the missing rune inside the nearby overlook.",logDesc="Obtain the Omega Rune inside the Shaper's Terrace and bring it to The Etymidian.",choiceRewards={{id=39366,qty=1},{id=39411,qty=1},{id=39442,qty=1},{id=39465,qty=1}}} end
if not DB[12548] then DB[12548]={id=12548,zoneId=3711,name="The Etymidian",level=78,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="The Etymidian",enderType="NPC",enderId=28092,rewardNextId=12547,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12548",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It is time, $N.  The Waygate has been activated for the first time in seven centuries.  Use it to travel to where our final hope lies.$B$BLet us put an end to those who would seek to bring the taint of undeath to this pristine land.  Let us unleash the Etymidian.",logDesc="Go through the Waygate in the southern end of Sholazar Basin and look for the weapon known as the Etymidian on the other side."} end
if not DB[12549] then DB[12549]={id=12549,zoneId=3711,name="Dreadsaber Mastery: Becoming a Predator",level=76,minLevel=76,giver="Buck Cantwell",giverType="NPC",giverId=28031,ender="Buck Cantwell",enderType="NPC",enderId=28031,rewardNextId=12550,poiX=5573,poiY=5768,wowhead="https://www.wowhead.com/wotlk/quest=12549",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="If you've hunted with Hemet before, you know that he's tested his skill against many large cats, but the dreadsabers here in Sholazar are different. They're able to bring down larger game than I've ever seen a cat hunt. To overcome and kill such a predator is the mark of a true hunter.$B$BIf you seek to prove you're up to the challenge, test yourself against the dreadsabers. They live in the wilderness surrounding the camp and south of the river.",logDesc="Kill 15 Dreadsabers and return to Buck Cantwell at the Nesingwary Base Camp."} end
if not DB[12550] then DB[12550]={id=12550,zoneId=3711,name="Dreadsaber Mastery: Stalking the Prey",level=76,minLevel=76,giver="Buck Cantwell",giverType="NPC",giverId=28031,ender="Buck Cantwell",enderType="NPC",enderId=28031,rewardNextId=12558,poiX=5573,poiY=5768,wowhead="https://www.wowhead.com/wotlk/quest=12550",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="I have heard that the natives tell stories of a large dreadsaber they call Shango. I haven't seen any evidence of this Shango's existence, but my injuries have kept me from venturing outside the camp.$B$BIf you fancy yourself something of a tracker, you might be able to find out the truth about Shango. Debaar said she saw some large tracks on her last outing. Go north from the camp toward Bittertide Lake, and search its southern shore for the prints.",logDesc="Buck Cantwell at the Nesingwary Base Camp wants you to identify 3 Shango Tracks from the Dreadsaber Tracks near Bittertide Lake."} end
if not DB[12551] then DB[12551]={id=12551,zoneId=3711,name="Crocolisk Mastery: The Trial",level=76,minLevel=76,giver="Debaar",giverType="NPC",giverId=28032,ender="Debaar",enderType="NPC",enderId=28032,rewardNextId=12560,poiX=5548,poiY=5742,wowhead="https://www.wowhead.com/wotlk/quest=12551",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="I warn you, stranger -- do not make any comments about crashing the ship. I already get enough of it from the rest of the expedition.$B$BIf you're looking to try your hand at hunting, though, you should test your skills against the wily mangal crocolisks. They live all along the river to the south, and in the Wildgrowth Mangal to the east. Prove you can hold your own against them and we'll talk again, hunter.",logDesc="Kill 15 Mangal Crocolisks and return to Debaar at the Nesingwary Encampment."} end
if not DB[12552] then DB[12552]={id=12552,zoneId=66,name="Death to the Necromagi",level=76,minLevel=74,giver="Sergeant Moonshard",giverType="NPC",giverId=28283,ender="Sergeant Moonshard",enderType="NPC",enderId=28283,rewardNextId=12554,poiX=5270,poiY=-3499,wowhead="https://www.wowhead.com/wotlk/quest=12552",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="When the trolls brought down Kolramas, it crashed next to us to the southeast. Unfortunately the crash did not destroy all of the Scourge within.$B$BNow they're raising our men from the dead and using them against us!$B$BThis will not be allowed to continue. You will see to it that their necromagi are slaughtered! Do we understand each other?",logDesc="Sergeant Moonshard at Drak'Sotra has asked you to destroy 8 Hath'ar Necromagi."} end
if not DB[12553] then DB[12553]={id=12553,zoneId=66,name="Skimmer Spinnerets",level=76,minLevel=74,giver="Specialist Cogwheel",giverType="NPC",giverId=28284,ender="Specialist Cogwheel",enderType="NPC",enderId=28284,rewardNextId=12555,poiX=5270,poiY=-3509,wowhead="https://www.wowhead.com/wotlk/quest=12553",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Why do I always get the tough tasks to tackle?$B$BThe Scourge at Kolramas have plague sprayers that are getting dangerously close. You don't want to know what's going to happen if they start heading this way!$B$BI've got an idea for how we might bring them down, but first we're going to need something... something from their own creatures.$B$BThe Hath'ar skimmers can spin a very strong web that we can put to good use. Bring back some of their spinnerets.",logDesc="Specialist Cogwheel at Drak'Sotra has asked you to collect 5 Intact Skimmer Spinnerets."} end
if not DB[12554] then DB[12554]={id=12554,zoneId=66,name="Malas the Corrupter",level=76,minLevel=74,giver="Sergeant Moonshard",giverType="NPC",giverId=28283,ender="Sergeant Moonshard",enderType="NPC",enderId=28283,poiX=5270,poiY=-3499,wowhead="https://www.wowhead.com/wotlk/quest=12554",image="assets/images/quests/placeholder.png",xpDiff=6,money=124000,desc="$N, gather at least one other person and head back down there!$B$BYou'll find the leader of Kolramas, Malas the Corrupter, gloating from atop the crashed necropolis.$B$BKill him and bring me his head!",logDesc="Sergeant Moonshard at Drak'Sotra insists that you return with the Head of the Corrupter.",choiceRewards={{id=43160,qty=1},{id=43161,qty=1},{id=43162,qty=1},{id=43163,qty=1}}} end
if not DB[12555] then DB[12555]={id=12555,zoneId=66,name="A Tangled Skein",level=76,minLevel=74,giver="Specialist Cogwheel",giverType="NPC",giverId=28284,ender="Specialist Cogwheel",enderType="NPC",enderId=28284,poiX=5270,poiY=-3509,wowhead="https://www.wowhead.com/wotlk/quest=12555",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="There! One tangled skein thrower ready and waiting for you to take those plague sprayers down.$B$BYou just aim and let loose. The webbing should foul up their hover spells long enough to cause them to crash to the ground just like Kolramas.$B$BKind of poetic. I like that!",logDesc="Specialist Cogwheel at Drak'Sotra has asked you to use the Tangled Skein Thrower in order to cause the destruction of 5 Plague Sprayers.",choiceRewards={{id=39806,qty=1},{id=39822,qty=1},{id=39824,qty=1},{id=39784,qty=1},{id=39823,qty=1},{id=39808,qty=1}}} end
if not DB[12556] then DB[12556]={id=12556,zoneId=3711,name="Rhino Mastery: The Kill",level=76,minLevel=76,giver="Hemet Nesingwary",giverType="NPC",giverId=27986,ender="Hemet Nesingwary",enderType="NPC",enderId=27986,poiX=5584,poiY=5749,wowhead="https://www.wowhead.com/wotlk/quest=12556",image="assets/images/quests/placeholder.png",xpDiff=6,money=124000,desc="Now that we know where to find Farunn, all that remains is the battle against the great beast. Are you ready to take on this rhino, $N? For all the spirit's blustering, I'm certain it was telling the truth about the beast's strength.$B$BWhen you're ready to face him, head north past the Suntouched Pillar and look for Farunn on the northeast shore of the Bittertide Lake. It may even venture near the Glimmering Pillar. Bring back its horn to commemorate your kill.",logDesc="Bring Farunn's Horn to Hemet Nesingwary at the Nesingwary Base Camp.",choiceRewards={{id=39333,qty=1},{id=39377,qty=1},{id=39431,qty=1},{id=39453,qty=1}}} end
if not DB[12557] then DB[12557]={id=12557,zoneId=66,name="Lab Work",level=76,minLevel=74,giver="Alchemist Finklestein",giverType="NPC",giverId=28205,ender="Alchemist Finklestein",enderType="NPC",enderId=28205,poiX=5934,poiY=-2349,wowhead="https://www.wowhead.com/wotlk/quest=12557",image="assets/images/quests/placeholder.png",xpDiff=1,money=6200,desc="I assume by your interruption that you wish to be numbered among those I am considering for apprenticeship.$b$bA worthy aspiration...$b$bShould I someday choose to accept your petition, I must be confident that you can find your way around my laboratory. I have many ingredients here; some plentiful, and others in short supply.$b$bTake your time, $c. Find a muddy mire maggot, a withered batwing, an amberseed, and some chilled serpent mucus.$b$bSucceed, and I'll know to take your request seriously.",logDesc="Alchemist Finklestein at Heb'Valok wants you to find a Muddy Mire Maggot, a Withered Batwing, an Amberseed, and some Chilled Serpent Mucus from within his laboratory."} end
if not DB[12558] then DB[12558]={id=12558,zoneId=3711,name="Dreadsaber Mastery: Ready to Pounce",level=76,minLevel=76,giver="Buck Cantwell",giverType="NPC",giverId=28031,ender="Buck Cantwell",enderType="NPC",enderId=28031,poiX=5573,poiY=5768,wowhead="https://www.wowhead.com/wotlk/quest=12558",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Shango awaits, $N. If you have succeeded in your tracking, he will not know that you stalk him, and you will need the advantage.$B$BHe is supposed to be bigger, stronger, and more ferocious than the other dreadsabers of the basin. Travel north, to the western shore of Bittertide Lake and near the falls that feed it, do battle with Shango. If you succeed, return with his pelt.",logDesc="Bring Shango's Pelt to Buck Cantwell at the Nesingwary Base Camp.",choiceRewards={{id=39323,qty=1},{id=39375,qty=1},{id=39429,qty=1},{id=39451,qty=1},{id=39503,qty=1}}} end
if not DB[12559] then DB[12559]={id=12559,zoneId=3711,name="Powering the Waygate - The Maker's Perch",level=77,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="3",enderType="NPC",enderId=27801,rewardNextId=12613,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12559",image="assets/images/quests/placeholder.png",xpDiff=4,money=51000,desc="It is time then.  Let us activate the waygate.$B$BYou will find the first switch inside the Maker's Perch in the western edge of the basin.$B$BBeware, $N.  The titans used the perch to watch over their creations.  Many of their stone servants still guard the place.",logDesc="The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Maker's Perch and use the Activation Switch Gamma."} end
if not DB[12560] then DB[12560]={id=12560,zoneId=3711,name="Crocolisk Mastery: The Plan",level=76,minLevel=76,giver="Debaar",giverType="NPC",giverId=28032,ender="Debaar",enderType="NPC",enderId=28032,rewardNextId=12569,poiX=5548,poiY=5742,wowhead="https://www.wowhead.com/wotlk/quest=12560",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="The mangal crocolisk is a master of the ambush, and I intend to beat the best at his game. To do that, we'll need to construct a convincing camouflage for you. We'll use plants that grow in the sandy soil of the riverbanks and lake beaches.$B$BThe sandfern is best for this purpose. It grows in the sandy areas near the shores of the Seabreach Flow, just to the south, Bittertide Lake and Bittertide Falls, to the north, and the edges of River's Heart, the large lake beyond the mangal to the east.",logDesc="Bring 5 Sandfern fronds to Debaar at the Nesingwary Base Camp."} end
if not DB[12561] then DB[12561]={id=12561,zoneId=3711,name="An Issue of Trust",level=77,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="3",enderType="NPC",enderId=27801,rewardNextId=12611,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12561",image="assets/images/quests/placeholder.png",xpDiff=6,money=130000,desc="This should never have happened.  The forces of undeath storm the very cradle of life!$B$BIf you're not here to destroy the minions of the Lich King, then leave at once.  Do not incur my wrath by distracting me from my duties.",logDesc="Obtain Freya's trust by destroying 6 Blighted Corpses and 10 Bonescythe Ravagers in the Lost Lands.",choiceRewards={{id=39363,qty=1},{id=39406,qty=1},{id=39439,qty=1},{id=39459,qty=1}}} end
if not DB[12562] then DB[12562]={id=12562,zoneId=66,name="The Drakkari Do Not Need Water Elementals!",level=76,minLevel=74,giver="Sub-Lieutenant Jax",giverType="NPC",giverId=28309,ender="Sub-Lieutenant Jax",enderType="NPC",enderId=28309,poiX=5374,poiY=-2607,wowhead="https://www.wowhead.com/wotlk/quest=12562",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Intelligence reports that ever since those water elementals appeared in the Drak'Sotra Fields, a number of Drakkari shaman have come down from the upper tiers of Zul'Drak to take control of them.$B$BI cannot stress enough, $g sir : ma'am;, how dangerous that could prove. We do not want them to have water elementals at their disposal.$B$BThe commander has ordered that these Drakkari water binders are to be put to the sword. Head south when you're ready.",logDesc="Sub-Lieutenant Jax at The Argent Stand has asked you to kill 10 Drakkari Water Binders."} end
if not DB[12563] then DB[12563]={id=12563,zoneId=66,name="Troll Patrol",level=76,minLevel=74,giver="Commander Kunz",giverType="NPC",giverId=28039,ender="Commander Kunz",enderType="NPC",enderId=28039,poiX=5451,poiY=-2611,wowhead="https://www.wowhead.com/wotlk/quest=12563",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Unsheathe that weapon, $r. It's time to go on patrol!$b$bI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.$b$bYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.$b$bReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!$b$bDismissed!",logDesc="Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.$b$bCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'Valok."} end
if not DB[12564] then DB[12564]={id=12564,zoneId=66,name="Troll Patrol: Something for the Pain",level=76,minLevel=74,giver="Captain Brandon",giverType="NPC",giverId=28042,ender="Captain Brandon",enderType="NPC",enderId=28042,poiX=5042,poiY=-3037,wowhead="https://www.wowhead.com/wotlk/quest=12564",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Gritty as my men are, they're still mortal.$b$bWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.$b$bThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.$b$bThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.",logDesc="Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields."} end
if not DB[12565] then DB[12565]={id=12565,zoneId=66,name="The Blessing of Zim'Abwa",level=76,minLevel=74,giver="Hexxer Ubungo",giverType="NPC",giverId=28062,poiX=5485,poiY=-2624,wowhead="https://www.wowhead.com/wotlk/quest=12565",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I am heartened to see the zeal with which your Argent Crusade is dealing with the Scourge, $r. I would like to help with your efforts.$B$BThe Drakkari trolls of this once-great city used to make regular offerings to their gods, but now neglect them, or worse.$B$BIf you were to make offerings to the gods, they would show their appreciation in return.$B$BZim'Abwa's statue is just to the southwest. Zim'Abwa would gladly accept your offerings of Drakkari artifacts as a sign that you are protecting Zul'Drak.",logDesc="Hexxer Ubungo at The Argent Stand wants you to present 10 Drakkari Offerings to the statue of Zim'Abwa."} end
if not DB[12566] then DB[12566]={id=12566,zoneId=495,name="Help for Camp Winterhoof",level=71,minLevel=68,giver="Longrunner Nanik",giverType="NPC",giverId=28314,ender="Chieftain Ashtotem",enderType="NPC",enderId=24129,poiX=1536,poiY=-5719,wowhead="https://www.wowhead.com/wotlk/quest=12566",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I am Longrunner Nanik of the Taunka, sent by the chieftain of Camp Winterhoof to seek out allies in the fight against the vrykul. They mass to the west and south of our village, and though we slay 10 of them for every one of our dead, we cannot hold.$B$BApothecary Scyllis has promised to send brave $cs northwest to our aid. Will you help my people fend off the vrykul assaults?$B$BFollow the road far to the northwest, across the river, and into the foothills of the mountains to reach Camp Winterhoof.",logDesc="Speak with Chieftain Ashtotem at Camp Winterhoof."} end
if not DB[12567] then DB[12567]={id=12567,zoneId=66,name="Blessing of Zim'Abwa",level=76,minLevel=74,wowhead="https://www.wowhead.com/wotlk/quest=12567",image="assets/images/quests/placeholder.png"} end
if not DB[12568] then DB[12568]={id=12568,zoneId=66,name="Troll Patrol: Done to Death",level=76,minLevel=74,giver="Captain Rupert",giverType="NPC",giverId=28044,ender="Captain Rupert",enderType="NPC",enderId=28044,poiX=5258,poiY=-3500,wowhead="https://www.wowhead.com/wotlk/quest=12568",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Trust me, $r. I know....$b$bThe smell of burnt flesh has become sickening to even me, a Forsaken. Nevertheless, it is our solemn duty to ensure that our brethren never walk with the Scourge.$b$bPour this oil on the corpses of our fallen to ensure that we never face them on the battlefield as enemies.",logDesc="Captain Rupert wants you to use the Incinerating Oil on 5 Defeated Argent Footmen in Drak'Sotra."} end
if not DB[12569] then DB[12569]={id=12569,zoneId=3711,name="Crocolisk Mastery: The Ambush",level=76,minLevel=76,giver="Debaar",giverType="NPC",giverId=28032,ender="Debaar",enderType="NPC",enderId=28032,poiX=5548,poiY=5742,wowhead="https://www.wowhead.com/wotlk/quest=12569",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="The largest crocolisk in the basin, known around here as \"Bushwhacker\" for his ambush prowess, likes to sun himself in the shallow waters of River's Heart. It's the large lake at the basin's center, and is to the east of our camp.$B$BI want you to take the camouflage I've prepared and hide on the western beach of River's Heart and ambush Bushwhacker when he shows himself. Bring back his mighty jaws if you are able to overcome him.",logDesc="Bring Bushwhacker's Jaw to Debaar at the Nesingwary Base Camp.",choiceRewards={{id=39331,qty=1},{id=39374,qty=1},{id=39461,qty=1},{id=39480,qty=1}}} end
if not DB[12570] then DB[12570]={id=12570,zoneId=3711,name="Fortunate Misunderstandings",level=77,minLevel=76,giver="Injured Rainspeaker Oracle",giverType="NPC",giverId=28217,ender="High-Oracle Soo-say",enderType="NPC",enderId=28027,rewardNextId=12571,poiX=5473,poiY=4381,wowhead="https://www.wowhead.com/wotlk/quest=12570",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="I sorry! I not mean to get you in trouble!$B$B<The injured oracle stares at you blankly for a long while.>$B$BYou save me! We thank you. We going to go back to village now. You come too... you can stay with us! Puppy-men kind of mean anyway.$B$BLet me know when you ready to go, okay?",logDesc="Escort the Injured Rainspeaker Oracle to Rainspaker Canopy and speak to High-Oracle Soo-say.",choiceRewards={{id=39335,qty=1},{id=39378,qty=1},{id=39432,qty=1},{id=39482,qty=1}}} end
if not DB[12571] then DB[12571]={id=12571,zoneId=3711,name="Make the Bad Snake Go Away",level=77,minLevel=76,giver="High-Oracle Soo-say",giverType="NPC",giverId=28027,ender="High-Oracle Soo-say",enderType="NPC",enderId=28027,rewardNextId=12573,poiX=5651,poiY=4551,wowhead="https://www.wowhead.com/wotlk/quest=12571",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="We were here long before the puppy-men came. This is very sacred place - we will not leave.$B$BYou seem like maybe you good, but we have Lafoo stay with you just in case. You understand we think.$B$BThere snakes thing that keeps trying to eat our hatchlings. Go with Lafoo and make them stop, okay? Especially big one near waterfall to northeast.",logDesc="High-Oracle Soo-say in Rainspeaker Canopy wants you to kill Venomtip and 10 Emperor Cobras.$B$BIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy."} end
if not DB[12572] then DB[12572]={id=12572,zoneId=3711,name="Gods like Shiny Things",level=77,minLevel=76,giver="Lafoo",giverType="NPC",giverId=28120,ender="High-Oracle Soo-say",enderType="NPC",enderId=28027,wowhead="https://www.wowhead.com/wotlk/quest=12572",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Soo-say said we go with you. You be nice, okay?$B$BOoh, ooh! We know! We can make Soo-say happy if we bring back more offerings for shrine! We not need to go far, there's always stuffs to dig up around village... just look for sparkles in dirt!$B$BLet's go! Let's go! More offerings for shrine!",logDesc="Collect 6 of the treasures that Lafoo digs up and bring them to High-Oracle Soo-say in Rainspeaker Canopy.$B$BIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy."} end
if not DB[12573] then DB[12573]={id=12573,zoneId=3711,name="Making Peace",level=77,minLevel=76,giver="High-Oracle Soo-say",giverType="NPC",giverId=28027,ender="High-Oracle Soo-say",enderType="NPC",enderId=28027,poiX=5651,poiY=4551,wowhead="https://www.wowhead.com/wotlk/quest=12573",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="We have great idea. You were friends with puppy-men, they maybe listen to you.$B$BWe want you to go give offering to Shaman Vekjik. He southwest where river turns into waterfall.  Tell puppy-man we no want fight. Tell him we play nice.$B$BYou good $r. We trust you do this right.",logDesc="High-Oracle Soo-say at Rainspeaker Canopy wants you to give a peace offering to Shaman Vekjik and then return with his response.$B$BIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.",choiceRewards={{id=39672,qty=1},{id=39674,qty=1},{id=39673,qty=1},{id=39675,qty=1}}} end
if not DB[12574] then DB[12574]={id=12574,zoneId=3711,name="Back So Soon?",level=77,minLevel=76,giver="High-Oracle Soo-say",giverType="NPC",giverId=28027,ender="Mistcaller Soo-gan",enderType="NPC",enderId=28114,poiX=5651,poiY=4551,wowhead="https://www.wowhead.com/wotlk/quest=12574",image="assets/images/quests/placeholder.png",xpDiff=3,money=33000,desc="<High-Oracle Soo-say stares at your forehead for a while before speaking.>$B$BSoo-gan ask for help. We think they might have been attacked by puppy-men again.$B$BWe sending you and Jaloot to help... follow west river up to Mistwhisper Refuge. Do what Soo-gan says... hit the puppy-men on the nose if they being mean, they don't like that.$B$B<High-Oracle Soo-say goes back to staring at your forehead as you leave.>",logDesc="Travel to Mistwhisper Refuge and speak to Mistcaller Soo-gan.$B$BIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy."} end
if not DB[12575] then DB[12575]={id=12575,zoneId=3711,name="The Lost Mistwhisper Treasure",level=77,minLevel=76,giver="Mistcaller Soo-gan",giverType="NPC",giverId=28114,ender="Mistcaller Soo-gan",enderType="NPC",enderId=28114,poiX=6165,poiY=5093,wowhead="https://www.wowhead.com/wotlk/quest=12575",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="So some puppy-men come and smash blue crystals at Great Mist Stone! Lots of rain and lightning and badness... blue is wrong crystal for Great Mist Stone! Dumb puppy-men.$B$BAfter lightning, puppy-men stole big treasure we found in the sea-lake. We need treasure back to give to Great Mist Stone! Mist Stone is angry after what the puppy-men did!$B$BOne who took it named Tarter... no, Tiktak... no, no... Tartek. That it, Tartek! He went to the camp thing to north. Go get treasure back!",logDesc="Kill Warlord Tartek and retrieve the Mistwhisper Treasure for Mistcaller Soo-gan at Mistwhisper Refuge.$B$BIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.",choiceRewards={{id=39336,qty=1},{id=39380,qty=1},{id=39433,qty=1},{id=39454,qty=1}}} end
if not DB[12576] then DB[12576]={id=12576,zoneId=3711,name="Forced Hand",level=77,minLevel=76,giver="Mistcaller Soo-gan",giverType="NPC",giverId=28114,ender="Mistcaller Soo-gan",enderType="NPC",enderId=28114,poiX=6165,poiY=5093,wowhead="https://www.wowhead.com/wotlk/quest=12576",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="We try to be nice to puppy-men ever since they came, but they nothing but mean.$B$BWe okay with them being dumb - they not do much harm. Now they mess with sacred shrines though. Sacred shrines not for messing with. The Great Stones are here from all the way back when the Great Ones made us.$B$BWe wouldn't know what to do if the Great Mist Stone were hurt. Go to their camp to north... make puppy-men stop and not come back!",logDesc="Kill 8 Frenzyheart Spearbearers and 6 Frenzyheart Scavengers for Mistcaller Soo-gan at Mistwhisper Refuge.$B$BIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy."} end
if not DB[12577] then DB[12577]={id=12577,zoneId=3711,name="Home Time!",level=77,minLevel=76,giver="Mistcaller Soo-gan",giverType="NPC",giverId=28114,ender="High-Oracle Soo-say",enderType="NPC",enderId=28027,rewardNextId=12578,poiX=6165,poiY=5093,wowhead="https://www.wowhead.com/wotlk/quest=12577",image="assets/images/quests/placeholder.png",xpDiff=3,money=33000,desc="You're a good dryskin. Mistwhisper safe, treasure safe, and puppy-men sure to leave us alone now.$B$BYou go back to Rainspeaker Canopy and tell Soo-say you done good.",logDesc="Return to Rainspeaker Canopy."} end
if not DB[12578] then DB[12578]={id=12578,zoneId=3711,name="The Angry Gorloc",level=77,minLevel=76,giver="High-Oracle Soo-say",giverType="NPC",giverId=28027,ender="Moodle",enderType="NPC",enderId=28122,poiX=5651,poiY=4551,wowhead="https://www.wowhead.com/wotlk/quest=12578",image="assets/images/quests/placeholder.png",xpDiff=3,money=33000,desc="I not think you be back in time to go out again, but I wrong. I sending Moodle to nearby Mosswalker friends to bop silly Mosswalkers for not coming see shrine. Their village is east, up ridge, northeast of broken pillar.$B$BYou go with Moodle! He extra smart Rainspeaker... you listen to him good-like.",logDesc="Travel to Mosswalker Village and speak to Moodle once you've arrived.$B$BIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy."} end
if not DB[12579] then DB[12579]={id=12579,zoneId=3711,name="Lifeblood of the Mosswalker Shrine",level=77,minLevel=76,giver="Moodle",giverType="NPC",giverId=28122,ender="Moodle",enderType="NPC",enderId=28122,wowhead="https://www.wowhead.com/wotlk/quest=12579",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="I've always suspected that the pillars have been the main reason for our weather and seclusion from the undead... this confirms it a bit.$B$BNot terribly long ago, there was a sound of a great explosion when the Lifeblood Pillar fell. The weather changed for the mosswalkers almost immediately... it began to snow, something we never see.$B$BThey were able to stop the snow by bringing more lifeblood crystals to the Great Moss Stone. Perhaps if we can do the same, it will help ward off the undead as well.",logDesc="Moodle wants you to collect 10 Lifeblood Shards, but stay away from the cave inside of the pillar itself.$B$BIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy."} end
if not DB[12580] then DB[12580]={id=12580,zoneId=3711,name="The Mosswalker Savior",level=77,minLevel=76,giver="Moodle",giverType="NPC",giverId=28122,ender="Moodle",enderType="NPC",enderId=28122,wowhead="https://www.wowhead.com/wotlk/quest=12580",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="There's some small chance that the Mosswalkers are not all dead yet... and at the very least, they deserve to not be butchered like this.$B$BLet's find some revenge for this slaughter and see if there are any to be saved in the process.",logDesc="Moodle wants you to rescue 6 of the Mosswalker Victims in Mosswalker Village, though some of them may no longer be alive to save.$B$BIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy."} end
if not DB[12581] then DB[12581]={id=12581,zoneId=3711,name="A Hero's Burden",level=77,minLevel=76,giver="Moodle",giverType="NPC",giverId=28122,wowhead="https://www.wowhead.com/wotlk/quest=12581",image="assets/images/quests/placeholder.png",xpDiff=7,money=195000,desc="Perhaps the crystals will ward off the undead gradually, but there is one more thing that must be done.$B$BWe need to find the leader of these undead and kill him to ensure there's no one to push the wretches back upon us. If my suspicions are correct, he will be somewhere inside the fallen pillar... the Sundered Shard.$B$BThe corpses being dragged there would suggest as much anyway.$B$BI'll place the shards and bring the news to Soo-say... you will need to find other help in the meantime.",logDesc="Kill Artruis the Heartless.$B$BWhile securing the aid of friends is highly recommended, Moodle will not be able to accompany you on this task.",choiceRewards={{id=39483,qty=1},{id=39485,qty=1},{id=39475,qty=1},{id=39484,qty=1}}} end
if not DB[12582] then DB[12582]={id=12582,zoneId=3711,name="Frenzyheart Champion",level=77,minLevel=76,giver="Zepik the Gorloc Hunter",giverType="NPC",giverId=28668,ender="Zepik the Gorloc Hunter",enderType="NPC",enderId=28668,poiX=5632,poiY=3794,wowhead="https://www.wowhead.com/wotlk/quest=12582",image="assets/images/quests/placeholder.png",xpDiff=3,money=33000} end
if not DB[12583] then DB[12583]={id=12583,zoneId=66,name="Crashed Sprayer",level=76,minLevel=74,giver="Specialist Cogwheel",giverType="NPC",giverId=28284,ender="Specialist Cogwheel",enderType="NPC",enderId=28284,rewardNextId=12555,poiX=5270,poiY=-3509,wowhead="https://www.wowhead.com/wotlk/quest=12583",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="I know that one of those plague sprayers crashed somewhere within Drak'Sotra to the west of us.$B$BWhy don't you see if you can find it. I can use the parts from the sprayer to create the device that's going to bring those things down!",logDesc="Specialist Cogwheel at Drak'Sotra has asked you to collect Plague Sprayer Parts."} end
if not DB[12584] then DB[12584]={id=12584,zoneId=66,name="Pure Evil",level=76,minLevel=74,giver="Captain Rupert",giverType="NPC",giverId=28044,ender="Eitrigg",enderType="NPC",enderId=28244,poiX=5258,poiY=-3500,wowhead="https://www.wowhead.com/wotlk/quest=12584",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="We know that Kolramas, the crashed necropolis to the southeast, was carrying a large amount of an ore known as saronite when the trolls shot it down.$B$BMy scouts tell me that much of the saronite is strewn about within the innards of that thing.$B$BEitrigg and his friends back at The Argent Stand want a bunch of the stuff so that they can study it.$B$BI want you to head in there and see if you can collect enough for them.",logDesc="Captain Rupert has asked you to collect 10 Chunks of Saronite and deliver them to Eitrigg at The Argent Stand.",choiceRewards={{id=39773,qty=1},{id=39837,qty=1},{id=39795,qty=1},{id=39792,qty=1}}} end
if not DB[12585] then DB[12585]={id=12585,zoneId=66,name="Troll Patrol: Creature Comforts",level=76,minLevel=74,giver="Captain Grondel",giverType="NPC",giverId=28043,ender="Captain Grondel",enderType="NPC",enderId=28043,poiX=5542,poiY=-3004,wowhead="https://www.wowhead.com/wotlk/quest=12585",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Well, it ain't glamorous, but it needs doin'.$b$bMy troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya.$b$bWhat they need is a nice fire to dry 'em out and lighten their spirits.$b$bThis part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture.$b$bRound us up some fuel for burnin' and we'll be mighty grateful.",logDesc="Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood."} end
if not DB[12586] then DB[12586]={id=12586,zoneId=3711,name="In Search of Bigger Game",level=77,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=12586",image="assets/images/quests/placeholder.png",desc="Well, $N, you've been an enormous asset to the expedition so far. Debaar, Buck, and I couldn't have have assembled such an amazing collection of trophies without you.$B$BBut, I hear there are even fiercer monsters in other parts of the basin. I've sent a search party up north to get an idea of what other beasts await us.$B$BI'd like you to meet up with them and see what they've found. Head north, beyond Bittertide Lake and search for the encampment.",logDesc="Talk to <x> at <x>."} end
if not DB[12587] then DB[12587]={id=12587,zoneId=66,name="Troll Patrol",level=76,minLevel=74,giver="Commander Kunz",giverType="NPC",giverId=28039,ender="Commander Kunz",enderType="NPC",enderId=28039,poiX=5451,poiY=-2611,wowhead="https://www.wowhead.com/wotlk/quest=12587",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Unsheathe that weapon, $r. It's time to go on patrol!$b$bI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.$b$bYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.$b$bReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!$b$bDismissed!",logDesc="Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.$b$bCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'valok."} end
if not DB[12588] then DB[12588]={id=12588,zoneId=66,name="Troll Patrol: Can You Dig It?",level=76,minLevel=74,giver="Captain Brandon",giverType="NPC",giverId=28042,ender="Captain Brandon",enderType="NPC",enderId=28042,poiX=5042,poiY=-3037,wowhead="https://www.wowhead.com/wotlk/quest=12588",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="One of our troops came across an old treasure map during our last offensive. If what it shows is true, then there are priceless troll artifacts nearby.$b$bMy soldiers have their hands full, pressed between the Drakkari and the Scourge. I need you to follow up on this intelligence.$b$bTake this shovel and use it at the loose dirt mounds to the southwest. Return to me after a diligent search has been conducted.",logDesc="Captain Brandon in Drak'Sotra wants you to use the Steel Spade on the nearby Ancient Dirt Mounds to recover the Ancient Drakkari Relic."} end
if not DB[12589] then DB[12589]={id=12589,zoneId=3711,name="Kick, What Kick?",level=76,minLevel=76,giver="Drostan",giverType="NPC",giverId=28328,ender="Drostan",enderType="NPC",enderId=28328,rewardNextId=12592,poiX=5548,poiY=5750,wowhead="https://www.wowhead.com/wotlk/quest=12589",image="assets/images/quests/placeholder.png",xpDiff=1,desc="So you think you can shoot?$B$BWell, let's give it a try. Here, we'll start you out with something nice and gentle. Don't worry, it's got no kick to it at all. Remember, don't point that gun at anything you don't intend to fire at.$B$BNow, when you're ready, just take aim at that apple on top o' old Lucky Wilhelm's head and let 'er fly!",logDesc="Using the RJR Rifle, shoot the apple on top of Lucky Wilhelm's head, then speak with Drostan."} end
if not DB[12590] then DB[12590]={id=12590,zoneId=66,name="Blahblah[PH]",level=76,minLevel=74,wowhead="https://www.wowhead.com/wotlk/quest=12590",image="assets/images/quests/placeholder.png"} end
if not DB[12591] then DB[12591]={id=12591,zoneId=66,name="Troll Patrol: Throwing Down",level=76,minLevel=74,giver="Captain Rupert",giverType="NPC",giverId=28044,ender="Captain Rupert",enderType="NPC",enderId=28044,poiX=5258,poiY=-3500,wowhead="https://www.wowhead.com/wotlk/quest=12591",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Clever...$b$bJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!$b$bNow we're caught between two nethurbian armies and our predicament is worsening by the minute.$b$bAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.$b$bTake these grenades and throw them down their craters to the northwest.",logDesc="Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nethurbian Craters."} end
if not DB[12592] then DB[12592]={id=12592,zoneId=3711,name="The Great Hunter's Challenge",level=76,minLevel=76,giver="Drostan",giverType="NPC",giverId=28328,ender="Drostan",enderType="NPC",enderId=28328,poiX=5548,poiY=5750,wowhead="https://www.wowhead.com/wotlk/quest=12592",image="assets/images/quests/placeholder.png",xpDiff=6,money=124000,desc="So y'have something of a hunter's instinct. You're not a bad shot, and Hemet hasn't driven you out, so he must be planning on including you in the hunt.$B$BHow'd you like to have a bit of a competition, just me and you?$B$BHemet and the others will ask you to help in their hunting. Along the way, you and I will count up the kills we contribute to their goals. Now, this isn't something you can win in the blink of an eye, and you'll find yourself killing many different kinds of creatures. Good luck!",logDesc="Kill 60 Game Animals while you aid Hemet and his companions in their hunting. When you've killed your 60, return to Drostan at the Nesingwary Base Camp to compare numbers.",choiceRewards={{id=39330,qty=1},{id=39373,qty=1},{id=39428,qty=1},{id=39448,qty=1}}} end
if not DB[12593] then DB[12593]={id=12593,zoneId=-372,name="In Service Of The Lich King",level=55,minLevel=55,giver="3",giverType="NPC",giverId=25462,ender="3",enderType="NPC",enderId=28357,rewardNextId=12619,poiX=2345,poiY=-5672,wowhead="https://www.wowhead.com/wotlk/quest=12593",image="assets/images/quests/placeholder.png",xpDiff=1,desc="All that I am: anger, cruelty, vengeance - I bestow upon you, my chosen knight. I have granted you immortality so that you may herald in a new, dark age for the Scourge.$B$BGaze now upon the lands below us. The Scarlet Crusade scurries to undo my work, while Light's Hope stands defiantly against us - a blemish upon these Plaguelands. They must all be shown the price of their defiance.$B$BYou will become my force of retribution. Where you tread, doom will follow. Go now and claim your destiny, death knight.",logDesc="Report to Instructor Razuvious in the Heart of Acherus.$B"} end
if not DB[12594] then DB[12594]={id=12594,zoneId=66,name="Troll Patrol: Couldn't Care Less",level=76,minLevel=74,giver="Captain Grondel",giverType="NPC",giverId=28043,ender="Captain Grondel",enderType="NPC",enderId=28043,poiX=5542,poiY=-3004,wowhead="https://www.wowhead.com/wotlk/quest=12594",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Of all the posts, they throw me in this one.$b$bThe place is flooded with putrid, stagnant water and now it's host to sewage elementals!$b$bI don't really know what they are or why they're here, and frankly I couldn't care less. What I do know is they're making a mess of my sector! How am I supposed to conduct any dignified military operations with those foul things roaming around?$b$bGet out there, $c, and don't come back 'til you've cleared your share of 'em off of my battlefield!",logDesc="Captain Grondel wants you to kill 7 Mossy Rampagers in Drak'Agal."} end
if not DB[12595] then DB[12595]={id=12595,zoneId=3711,name="In Search of Bigger Game",level=77,minLevel=76,giver="Hemet Nesingwary",giverType="NPC",giverId=27986,ender="Dorian Drakestalker",enderType="NPC",enderId=28376,poiX=5584,poiY=5749,wowhead="https://www.wowhead.com/wotlk/quest=12595",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Well, $N, you've certainly proven your mettle as a hunter of all kinds of game animals -- rhinos, cats, and crocolisks. For some members of the expedition, these creatures are sufficient to test their hunting skills, but others, like myself, crave larger challenges.$B$BDorian Drakestalker went north, across Bittertide Lake and established a camp there. He's heard rumors of gigantic primordial drakes. Just imagine what a quarry they would be! Go check up on Dorian and see if he's had any luck.",logDesc="Speak with Dorian Drakestalker at Dorian's Outpost in Sholazar Basin."} end
if not DB[12596] then DB[12596]={id=12596,zoneId=66,name="Pa'Troll",level=76,minLevel=74,giver="Commander Kunz",giverType="NPC",giverId=28039,ender="Commander Kunz",enderType="NPC",enderId=28039,poiX=5451,poiY=-2611,wowhead="https://www.wowhead.com/wotlk/quest=12596",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Welcome to The Argent Stand, scrub. I am Commander Kunz, but you - you can call me... Commander.$b$bDon't think you're going to just cruise through my region, picking which missions you're going to participate in, answering to no one.$b$bHere, you report to me and you follow my orders to the letter. Understood?!$b$bFirst, you're going to get familiar with my men and the region we're charged with clearing.$b$bReport to each of them and do as they ask. Return to me when your patrol is done.",logDesc="Commander Kunz at The Argent Stand wants you to visit the four Argent Crusade posts, follow their leaders' orders, and then return and report to him.$b$bCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Southeast of here.$b$bCaptain Grondel is posted in Drak'Agal, due east.$b$bAlchemist Finklestein is posted in Heb'Valok, to the north.",choiceRewards={{id=39800,qty=1},{id=39864,qty=1},{id=39850,qty=1},{id=39851,qty=1},{id=39827,qty=1}}} end
if not DB[12597] then DB[12597]={id=12597,zoneId=66,name="Something for the Pain",level=76,minLevel=74,giver="Captain Brandon",giverType="NPC",giverId=28042,ender="Captain Brandon",enderType="NPC",enderId=28042,poiX=5042,poiY=-3037,wowhead="https://www.wowhead.com/wotlk/quest=12597",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Gritty as my men are, they're still mortal.$b$bWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.$b$bThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.$b$bThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.",logDesc="Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields."} end
if not DB[12598] then DB[12598]={id=12598,zoneId=66,name="Throwing Down",level=76,minLevel=74,giver="Captain Rupert",giverType="NPC",giverId=28044,ender="Captain Rupert",enderType="NPC",enderId=28044,rewardNextId=12555,poiX=5258,poiY=-3500,wowhead="https://www.wowhead.com/wotlk/quest=12598",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Clever...$b$bJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!$b$bNow we're caught between two Nerubian armies and our predicament is worsening by the minute.$b$bAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.$b$bTake these grenades and throw them down their craters to the northwest.",logDesc="Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nerubian Craters."} end
if not DB[12599] then DB[12599]={id=12599,zoneId=66,name="Creature Comforts",level=76,minLevel=74,giver="Captain Grondel",giverType="NPC",giverId=28043,ender="Captain Grondel",enderType="NPC",enderId=28043,poiX=5542,poiY=-3004,wowhead="https://www.wowhead.com/wotlk/quest=12599",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Well, it ain't glamorous, but it needs doin'.$b$bMy troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya.$b$bWhat they need is a nice fire to dry 'em out and lighten their spirits.$b$bThis part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture.$b$bRound us up some fuel for burnin' and we'll be mighty grateful.",logDesc="Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood."} end
if not DB[12600] then DB[12600]={id=12600,zoneId=0,name="Upper Deck Promo - Bear Mount",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=12600",image="assets/images/quests/placeholder.png"} end
if not DB[12601] then DB[12601]={id=12601,zoneId=66,name="The Alchemist's Apprentice",level=76,minLevel=74,wowhead="https://www.wowhead.com/wotlk/quest=12601",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.$b$bWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.$b$bCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.$b$bLet me know when you're ready, $r. And remember, timing is everything!",logDesc="Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum.$b$bWhen you are ready to begin, you are to speak to him and follow his instructions."} end
if not DB[12602] then DB[12602]={id=12602,zoneId=66,name="The Alchemist's Apprentice",level=76,minLevel=74,wowhead="https://www.wowhead.com/wotlk/quest=12602",image="assets/images/quests/placeholder.png",xpDiff=2,money=15800,desc="Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.$b$bWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.$b$bCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.$b$bLet me know when you're ready, $r. And remember, timing is everything!",logDesc="Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum.$b$bWhen you are ready to begin, you are to speak to him and follow his instructions."} end
if not DB[12603] then DB[12603]={id=12603,zoneId=3711,name="Sharpening Your Talons",level=77,minLevel=76,giver="Dorian Drakestalker",giverType="NPC",giverId=28376,ender="Dorian Drakestalker",enderType="NPC",enderId=28376,poiX=6454,poiY=5085,wowhead="https://www.wowhead.com/wotlk/quest=12603",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="The primordial drakes occupy most of the area to the north and east, and I can feel the heat of their breath even at this distance. Before we can challenge the mightiest among the drakes, we must test our skills against the lesser creatures.$B$BStill, don't let your guard down; any one of these beasts can devour a man whole. Once you've familiarized yourself with the combat tactics of these drakes, return and I will tell you our next step.",logDesc="Kill 6 Primordial Drakes and then speak with Dorian Drakestalker at Dorian's Outpost."} end
if not DB[12604] then DB[12604]={id=12604,zoneId=66,name="Congratulations!",level=76,minLevel=74,giver="Commander Kunz",giverType="NPC",giverId=28039,ender="Commander Kunz",enderType="NPC",enderId=28039,poiX=5451,poiY=-2611,wowhead="https://www.wowhead.com/wotlk/quest=12604",image="assets/images/quests/placeholder.png",xpDiff=7,money=186000,rewards={{id=43556,qty=1}}} end
if not DB[12605] then DB[12605]={id=12605,zoneId=3711,name="Securing the Bait",level=77,minLevel=76,giver="Dorian Drakestalker",giverType="NPC",giverId=28376,ender="Dorian Drakestalker",enderType="NPC",enderId=28376,poiX=6454,poiY=5085,wowhead="https://www.wowhead.com/wotlk/quest=12605",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="We're not likely to get Broodmother Slivina's attention waving our arms around like fools, but if we're smart, we can bait her into fighting us. We'll also secure more, uh, fodder for my little project.$B$B<Dorian glances over at Zootfizzle.>$B$BBut don't worry about that for now. Just look for the primordial drake eggs in the area east and northeast of the camp. Burst them open and scoop up the hatchlings that come out. When the broodmother realizes what we've done, she'll have no choice but to face us.",logDesc="Bring 6 Primordial Hatchlings to Dorian Drakestalker at Dorian's Outpost."} end
if not DB[12606] then DB[12606]={id=12606,zoneId=66,name="Cocooned!",level=76,minLevel=74,giver="Captain Rupert",giverType="NPC",giverId=28044,ender="Captain Rupert",enderType="NPC",enderId=28044,poiX=5258,poiY=-3500,wowhead="https://www.wowhead.com/wotlk/quest=12606",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Now that the tunnels have been sealed, our next concern is recovering those who have fallen to the enemy.$b$bWith any luck, several of our soldiers are still alive and relatively well inside the nerubian cocoons.$b$bFree them, $c, while you still can!",logDesc="Captain Rupert wants you to open the Nerubian Cocoons in Drak'Sotra and return to him once you have freed 3 Captive Footmen."} end
if not DB[12607] then DB[12607]={id=12607,zoneId=3711,name="A Mammoth Undertaking",level=77,minLevel=76,giver="Zootfizzle",giverType="NPC",giverId=28374,ender="Zootfizzle",enderType="NPC",enderId=28374,poiX=6448,poiY=5095,wowhead="https://www.wowhead.com/wotlk/quest=12607",image="assets/images/quests/placeholder.png",xpDiff=4,money=51000,desc="Before you go off challenging Broodmother Slivina, Dorian thought it might be a good idea for you and Hemet to coordinate your efforts by riding into battle on the back of a mammoth.$B$BThe area around the camp is full of them. Just take this bridle and skip it over the head of a shattertusk mammoth. Be careful of the bulls, though. They won't tolerate the harness at all. Bring the mammoth back here when you've found a suitable one.",logDesc="Bring a Shattertusk Mammoth to Zootfizzle at Dorian's Outpost."} end
if not DB[12608] then DB[12608]={id=12608,zoneId=3711,name="Cultist Incursion",level=78,minLevel=77,giver="Cultist Corpse",giverType="NPC",giverId=28464,ender="3",enderType="NPC",enderId=27801,poiX=5536,poiY=4094,wowhead="https://www.wowhead.com/wotlk/quest=12608",image="assets/images/quests/placeholder.png",xpDiff=4,money=68000,desc="<It appears the Avatar of Freya was right.  The undead were not able to enter Sholazar Basin before the Lifeblood Pillar was brought down -- they used their living agents from the Cult of the Damned instead.>$B$B<You'd best warn her about the Lich King's living agents within Sholazar Basin.>",logDesc="Speak to the Avatar of Freya at the Rainspeaker Rapids."} end
if not DB[12609] then DB[12609]={id=12609,zoneId=66,name="Stocking the Shelves",level=76,minLevel=74,giver="Captain Arnath",giverType="NPC",giverId=28045,ender="Captain Arnath",enderType="NPC",enderId=28045,poiX=5930,poiY=-2379,wowhead="https://www.wowhead.com/wotlk/quest=12609",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Listen, $c. I realize that it's a lot to ask....$b$bFresh spider ichor is somewhat hard to come by, even in these heavily infested regions. But Finklestein said he'd settle for no less than a vat of it, and that he needs it soon.$b$bI'll keep my men out in the field collecting reagents, but if the alchemist's order is going to be filled in time, they'll require some assistance.$b$bAs you roam the fields of Zul'Drak, keep your eyes peeled for trapdoor crawlers and bring me all of the ichor you can find.",logDesc="Captain Arnath in Heb'Valok asked you to collect 7 units of Fresh Spider Ichor from the Trapdoor Crawlers in Zul'Drak.",choiceRewards={{id=39865,qty=1},{id=39852,qty=1},{id=39853,qty=1},{id=39802,qty=1},{id=39829,qty=1}}} end
if not DB[12610] then DB[12610]={id=12610,zoneId=66,name="Clipping Their Wings",level=76,minLevel=74,giver="Captain Arnath",giverType="NPC",giverId=28045,ender="Captain Arnath",enderType="NPC",enderId=28045,poiX=5930,poiY=-2379,wowhead="https://www.wowhead.com/wotlk/quest=12610",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Ever since Finklestein's arrival, I've been relegated to collecting various ingredients for his experiments and recipes.$b$bI'll follow my orders as I've vowed to do, but I'm a seasoned veteran. I've taken part in dozens of conflicts. I'd much rather be on the front lines, having a more direct impact on the Crusade's outcome here.$b$bHelp me, $r. Collect some bat wings for me so that I might get back to the real action sooner.",logDesc="Captain Arnath in Heb'Valok has asked you to collect 7 Unblemished Bat Wings from Zul'Drak Bats.",choiceRewards={{id=39804,qty=1},{id=39867,qty=1},{id=39854,qty=1},{id=39855,qty=1}}} end
if not DB[12611] then DB[12611]={id=12611,zoneId=3711,name="Returned Sevenfold",level=77,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="3",enderType="NPC",enderId=27801,rewardNextId=12612,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12611",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="The agents of the Lich King have foolishly trespassed upon these lands where the power of life rules supreme.  All harm they inflict will be returned to them sevenfold.$B$BThe monster directly responsible for corrupting the land is known as Thalgran Blightbringer; you will find him just to the north of here.  Take this ward and use it to reflect the power of death upon him.  Show the Scourge that the power of life prevails above all.",logDesc="The Avatar of Freya wants you defeat Thalgran Blightbringer by using Freya's Ward to reflect his Deathbolts back to him sevenfold.",rewards={{id=39481,qty=1}},choiceRewards={{id=39367,qty=1},{id=39412,qty=1},{id=39444,qty=1},{id=39464,qty=1}}} end
if not DB[12612] then DB[12612]={id=12612,zoneId=3711,name="The Fallen Pillar",level=77,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="Cultist Corpse",enderType="NPC",enderId=28464,rewardNextId=12608,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12612",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The titans shaped entire life forms here, fostering their unfettered growth.$B$BThe five crystal pillars that surround the basin emanate pure lifeforce.  The Scourge should've never been able to penetrate the basin, but one of the pillars was destroyed.$B$BGo to the Lifeblood Pillar and see if you can find out what happened.  No undead would've been able to approach the pillar, so keep your eyes out for living intruders.  You'll find what remains of the pillar directly south of here.",logDesc="Travel to the Lifeblood Pillar and look for clues to its destruction."} end
if not DB[12613] then DB[12613]={id=12613,zoneId=3711,name="Powering the Waygate - The Maker's Overlook",level=77,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="3",enderType="NPC",enderId=27801,rewardNextId=12548,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12613",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We cannot stop now, $r.  You've triggered the first switch, but one remains.$B$BThe titans constructed a second vantage point where they oversaw their creations.  You'll find it to the east, high in the mountains.$B$BPull the activation switch theta inside the overlook and the waygate will open.",logDesc="The Avatar of Freya wants you to head to the Maker's Overlook in eastern Sholazar Basin and use the Activation Switch Theta."} end
if not DB[12614] then DB[12614]={id=12614,zoneId=3711,name="Post-partum Aggression",level=77,minLevel=76,giver="Dorian Drakestalker",giverType="NPC",giverId=28376,ender="Dorian Drakestalker",enderType="NPC",enderId=28376,poiX=6454,poiY=5085,wowhead="https://www.wowhead.com/wotlk/quest=12614",image="assets/images/quests/placeholder.png",xpDiff=6,money=130000,desc="Broodmother Slivina's likely to be a snarling ball of teeth, spikes, and talons. You've gone and stolen her children away and no mother takes kindly to that.$B$B'Tis true they hatched from eggs, but she loves the little beasts no less than your mother loves you.$B$BShe'll be desperate and fierce in equal measures, everything Hemet loves in a target. You and he, along with that mammoth, should be a match for her.$B$BShe's on her perch at the northern edge of the Savage Thicket and hungers for revenge.",logDesc="Kill Broodmother Slivina and return to Dorian Drakestalker at Dorian's Outpost.",choiceRewards={{id=39487,qty=1},{id=39486,qty=1},{id=39490,qty=1},{id=39488,qty=1},{id=39478,qty=1},{id=40353,qty=1}}} end
if not DB[12615] then DB[12615]={id=12615,zoneId=66,name="The Blessing of Zim'Torga",level=77,minLevel=74,giver="Witch Doctor Khufu",giverType="NPC",giverId=28479,poiX=5736,poiY=-3571,wowhead="https://www.wowhead.com/wotlk/quest=12615",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Hexxer Ubungo probably told you about making offerings to the gods of Zul'Drak. Zim'Abwa is not the only god that stands forgotten by the Drakkari.$B$BWe have taken refuge within the presence of Zim'Torga, the Mother of Prosperity. As with Zim'Abwa, if you were to give offerings of the Drakkari to her, she is sure to give you her blessing.",logDesc="Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Torga."} end
if not DB[12616] then DB[12616]={id=12616,zoneId=2562,name="Chamber of Secrets",level=70,minLevel=70,giver="Argent Emissary",giverType="NPC",giverId=16285,ender="Argent Emissary",enderType="NPC",enderId=16285,wowhead="https://www.wowhead.com/wotlk/quest=12616",image="assets/images/quests/placeholder.png",desc="Excellent, an experienced adventurer. Precisely what we need.$b$bThere has been talk from the Kirin Tor guarding Medivh's tower that something is amiss with Karazhan. There is a new power lurking within, one that answers neither to the Guardian's magic nor the Legion. From what they've scouted, it appears it is an elven prince called Tenris Mirkblood, and there is reason to believe he serves the Scourge.$b$bGo, my friend, investigate Mirkblood's chamber, and return with any information you might find.",logDesc="The Argent Dawn Emissary wants you to search the chamber of Tenris Mirkblood within the Servant's Quarters of Karazhan.",rewards={{id=40354,qty=1}}} end
if not DB[12617] then DB[12617]={id=12617,zoneId=3711,name="Exterminate the Intruders",level=77,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="3",enderType="NPC",enderId=27801,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12617",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="I am an embodiment of but one aspect of Freya, daughter of the titans.  I am the Lifewarden -- I was left here to protect this land against the threat of the Scourge.$B$BI never anticipated the Lich King would send willing living servants to do his work.$B$BI could easily crush these cultists myself, but I am all that stands between the undead armies and the rest of the basin.  Go, $N.  Deliver my wrath to these insolent trespassers.",logDesc="The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Death's Hand Encampment to the northwest and slay 8 Cultist Infiltrators.",choiceRewards={{id=39365,qty=1},{id=39385,qty=1},{id=39441,qty=1},{id=39449,qty=1}}} end
if not DB[12618] then DB[12618]={id=12618,zoneId=66,name="Blessing of Zim'Torga",level=77,minLevel=74,wowhead="https://www.wowhead.com/wotlk/quest=12618",image="assets/images/quests/placeholder.png"} end
if not DB[12619] then DB[12619]={id=12619,zoneId=-372,name="The Emblazoned Runeblade",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28357,ender="3",enderType="NPC",enderId=28357,rewardNextId=12842,poiX=2498,poiY=-5593,wowhead="https://www.wowhead.com/wotlk/quest=12619",image="assets/images/quests/placeholder.png",xpDiff=8,desc="The single most important piece of equipment to a death knight is the runeblade. It is through the runeblade that a death knight commands the powers of frost, blood and the unholy. The runeblade also acts as a vessel to store the death knight's runic power.$B$BThe time has come to create your first runeblade. Search the weapon racks on this floor and locate a battle-worn sword. Once found, take the sword to a nearby runeforge and use it to create a runeblade.",logDesc="Search the weapon racks in Ebon Hold for a Battle-worn Sword and then use it on a runeforge to craft a Runebladed Sword.$B$BReturn the Runebladed Sword to Instructor Razuvious in Ebon Hold.",rewards={{id=38707,qty=1}}} end
if not DB[12620] then DB[12620]={id=12620,zoneId=3711,name="The Lifewarden's Wrath",level=77,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="3",enderType="NPC",enderId=27801,rewardNextId=12621,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12620",image="assets/images/quests/placeholder.png",xpDiff=4,money=51000,desc="We were not quick enough, $N.  The cultist scum have arrived at the Glimmering Pillar and are making preparations to destroy it, I can sense them.$B$BWe don't have much time.  Blow upon this horn atop the Glimmering Pillar to channel my power through the crystal.$B$BWe shall show this scum to not trifle with the titans' creations.",logDesc="The Avatar of Freya at the Rainspeaker Rapids wants you to use Freya's Horn atop of the Glimmering Pillar."} end
if not DB[12621] then DB[12621]={id=12621,zoneId=3711,name="Freya's Pact",level=77,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="3",enderType="NPC",enderId=27801,rewardNextId=12559,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12621",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The cultists have been taken care of, but the Scourge's invasion has not slowed down.  The situation is becoming desperate, $N.$B$BThere exists a last resort.  Before I reveal any more, however, I must be sure I have your absolute trust.",logDesc="Listen to what the Avatar of Freya has to say."} end
if not DB[12622] then DB[12622]={id=12622,zoneId=66,name="The Leaders at Jin'Alai",level=77,minLevel=74,giver="Scalper Ahunae",giverType="NPC",giverId=28484,ender="Scalper Ahunae",enderType="NPC",enderId=28484,rewardNextId=12640,poiX=5798,poiY=-3554,wowhead="https://www.wowhead.com/wotlk/quest=12622",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="You thinkin' what Ahunae thinkin', mon?$B$BSome of the Drakkari trolls have gathered at the Pools of Jin'Alai to the southwest. We be needin' to draw out their leaders, and Ahunae knows just how you be doin' it, too!$B$BGo in there and kill those trolls. When you kill enough, their leaders show up.$B$BWhen they show up next to their totems, you make sure to be gettin' the treasure of Kutube'sa, Gawanil, and Chulo the Mad, mon.",logDesc="Scalper Ahunae at Zim'Torga has asked you to retrieve the Treasure of Kutube'sa, the Treasure of Gawanil, and the Treasure of Chulo the Mad.",rewards={{id=20390,qty=5}},choiceRewards={{id=39775,qty=1},{id=39838,qty=1},{id=39796,qty=1},{id=39798,qty=1}}} end
if not DB[12623] then DB[12623]={id=12623,zoneId=66,name="To the Witch Doctor",level=77,minLevel=74,giver="Hexxer Ubungo",giverType="NPC",giverId=28062,ender="Witch Doctor Khufu",enderType="NPC",enderId=28479,rewardNextId=12627,poiX=5485,poiY=-2624,wowhead="https://www.wowhead.com/wotlk/quest=12623",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We Zandalari could use your help, $N. We must put an end to what the Drakkari are doing to their gods!$B$BTo the northeast, up the great steps that lead to the next tier of Zul'Drak, lies Zim'Torga. It is the home to another of the god statues and a refuge that my people are desparately attempting to defend.$B$BI would like for you to travel there and speak to Witch Doctor Khufu. Be warned though, the place is under constant attack from the Drakkari.",logDesc="Speak with Witch Doctor Khufu at Zim'Torga."} end
if not DB[12624] then DB[12624]={id=12624,zoneId=3711,name="It Could Be Anywhere!",level=76,minLevel=76,giver="Chad",giverType="NPC",giverId=28497,ender="Chad",enderType="NPC",enderId=28497,poiX=5576,poiY=5759,wowhead="https://www.wowhead.com/wotlk/quest=12624",image="assets/images/quests/placeholder.png",xpDiff=7,money=186000,desc="When I found out that Miss Boulian was helping Nesingwary with his expedition, I signed up as a deckhand immediately.  You see, I'd been meaning to marry her for months!$B$BI had it all planned out.  I was going to propose the very night of the shipwreck... but now the ring is gone.  I've searched everywhere!$B$BI know it might sound crazy, but I know the engagement ring is in the Basin.  If some Venture Company didn't steal it, maybe a wild creature ate it.  But it's here somewhere... I just know it!",logDesc="Look for a Golden Engagement Ring on the various creatures in Sholazar Basin.",choiceRewards={{id=39479,qty=1},{id=39446,qty=1},{id=39466,qty=1},{id=39474,qty=1}}} end
if not DB[12625] then DB[12625]={id=12625,zoneId=-372,name="Dominion Over Acherus",level=55,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=12625",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold.$B$BThough your thoughts may still be hazy, we haven't a moment to spare. You must claim dominion over Acherus and your mind! The horns of war surge!$B$BTake the stairs on this floor - located north, south, east and west - to the garrison floor above us. Seek out Master Siegesmith Corvus and acquire his status report. It must be delivered to Thalanor.",logDesc="Report to Master Siegesmith Corvus on the garrison floor of Ebon Hold."} end
if not DB[12626] then DB[12626]={id=12626,zoneId=-372,name="Company of the Damned",level=55,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=12626",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<Corvus salutes.>$B$BOur stockpiles of weapons, armor and munitions are nearly at maximum capacity. We are ready for war!$B$B<Corvus rolls up a fleshy piece of vellum.>$B$BOn the other side of this garrison floor, southwest of here, you will find the officers' quarters. Take this status report there and deliver it to Scourge Commander Thalanor, battalion commander of the Company of the Damned.",logDesc="Deliver Corvus' Report to Scourge Commander Thalanor at the garrison floor of Ebon Hold."} end
if not DB[12627] then DB[12627]={id=12627,zoneId=66,name="Breaking Through Jin'Alai",level=77,minLevel=74,giver="Witch Doctor Khufu",giverType="NPC",giverId=28479,ender="Witch Doctor Khufu",enderType="NPC",enderId=28479,poiX=5736,poiY=-3571,wowhead="https://www.wowhead.com/wotlk/quest=12627",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I have been trying to commune with the gods. However, the medicine men at the Pools of Jin'Alai are performing rituals that are interfering with my attempts.$B$BIt is imperative that we break through their obtrusion. If you were to head southwest into the pools area, I am certain that you would come across the cauldrons they are using for their magic.$B$BDisturb each of the cauldrons to bring down their ritual that is blocking me.",logDesc="Witch Doctor Khufu at Zim'Torga has asked you to disturb the Blue Cauldron, Green Cauldron, Purple Cauldron, and Red Cauldron."} end
if not DB[12628] then DB[12628]={id=12628,zoneId=66,name="To Speak With Har'koa",level=77,minLevel=74,giver="Witch Doctor Khufu",giverType="NPC",giverId=28479,ender="3",enderType="NPC",enderId=28401,rewardNextId=12632,poiX=5736,poiY=-3571,wowhead="https://www.wowhead.com/wotlk/quest=12628",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The gods have spoken, $N. We now know what you must do.$B$BYou must now go to the Altar of Har'koa to the southeast and speak with the leopard goddess.",logDesc="Speak with Har'koa at the Altar of Har'koa."} end
if not DB[12629] then DB[12629]={id=12629,zoneId=66,name="You Can Run, But You Can't Hide",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12648,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12629",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Once the Scourge have a target in their sights, they'll stop at nothing to acquire it.$b$bYou're doomed to a mindless existence as a walking corpse....$b$b<Stefan's face twists into a cruel grin.>$b$b... unless we can use their desires against them.$b$bI'll explain later. I have complex magic to prepare which requires certain material components.$b$bTravel due east of here to the Reliquary of Agony. Slay abominations and gather the ghoul drool you'll find there then return to me with their remnants.",logDesc="Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools."} end
if not DB[12630] then DB[12630]={id=12630,zoneId=66,name="Kickin' Nass and Takin' Manes",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12630",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Before you meet Nass, there's something you should know.$b$bHe got a toxic dose of blight back in the day, and now he's deaf, blind, and mostly numb.$b$bIt's not all bad, though. He's virtually immune to the stuff now, which makes him perfect for certain tasks - like the one I'm about to give you.$b$bThere are many freshly scourged trolls nearby and we need to study the blight's effect on them. Take Nass, and this boot. When you've slain a troll, give him a good kick and he'll know to take a hair sample.",logDesc="Stefan in Ebon Watch wants you to use Nass to collect 10 hair samples from Withered Trolls.$b$bIf you lose Nass, return to Stefan to recover him."} end
if not DB[12631] then DB[12631]={id=12631,zoneId=66,name="An Invitation, of Sorts...",level=75,minLevel=74,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12637,wowhead="https://www.wowhead.com/wotlk/quest=12631",image="assets/images/quests/placeholder.png",xpDiff=4,money=46000,desc="Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.$b$bGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.$b$bIf anyone can explain this, a death knight can....",logDesc="Take the Unliving Choker to Stefan at Ebon Watch."} end
if not DB[12632] then DB[12632]={id=12632,zoneId=66,name="But First My Offspring",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="3",enderType="NPC",enderId=28401,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=12632",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I am the last of the gods to be subdued, so we must first attempt to free the others. Bound by the magics of my subduers, I am unable to discern their fates.$B$BBut first, I would ask that you do me a kindness. Already the Drakkari turn my magic against me. They have transformed my offspring into monstrosities.$B$BTake one of my whiskers. Slay my tortured children and use the magic of it to release them from their nightmare, and bring them back to life.",logDesc="Har'koa has asked you to use her whisker on the corpses of her children to free and resurrect them. Return to her at the Altar of Har'koa when you are done.",choiceRewards={{id=39787,qty=1},{id=39856,qty=1},{id=39821,qty=1},{id=39891,qty=1}}} end
if not DB[12633] then DB[12633]={id=12633,zoneId=66,name="Darkness Calling",level=75,minLevel=74,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12638,wowhead="https://www.wowhead.com/wotlk/quest=12633",image="assets/images/quests/placeholder.png",xpDiff=4,money=46000,desc="Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.$b$bGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.$b$bIf anyone can explain this, a death knight can....",logDesc="Take the Writhing Choker to Stefan in Ebon Watch."} end
if not DB[12634] then DB[12634]={id=12634,zoneId=3711,name="Some Make Lemonade, Some Make Liquor",level=76,minLevel=76,giver="Grimbooze Thunderbrew",giverType="NPC",giverId=29157,ender="Grimbooze Thunderbrew",enderType="NPC",enderId=29157,rewardNextId=12644,poiX=5543,poiY=5763,wowhead="https://www.wowhead.com/wotlk/quest=12634",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Life's tossed me a cartload of lemons this time! When the ship ran aground, the kegs carrying my best brew burst! All we have now are a few bottles of rum, and it won't sustain a thirsty expedition!$B$BWe need to get some booze cooking, and fast!!$B$BThe trees in the Wildgrowth Mangal, to the east, seem laden with fruit, but it's too high for me to reach. Look for good, strong vines, see if you can use it to shake some of that fruit out of the trees. Bring me whatever you can find.",logDesc="Bring 1 Orange, 2 Banana Bunches, and 1 Papaya to Grimbooze Thunderbrew at the Nesingwary Base Camp."} end
if not DB[12635] then DB[12635]={id=12635,zoneId=66,name="Relics of the Snow Leopard Goddess",level=77,minLevel=74,giver="Chronicler To'kini",giverType="NPC",giverId=28527,ender="Chronicler To'kini",enderType="NPC",enderId=28527,poiX=5740,poiY=-3595,wowhead="https://www.wowhead.com/wotlk/quest=12635",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I overheard that you are going to see to the well-being of Har'koa. Good luck to you.$B$BI am wondering if while you are in the vicinity of the altar, you would be willing to recover their relics? I do not require many, and it is only a short trip to the southeast.$B$BWhat do you say?",logDesc="Chronicler To'kini at Zim'Torga wants you to recover 10 Har'koan Relics."} end
if not DB[12636] then DB[12636]={id=12636,zoneId=-372,name="The Eye Of Acherus",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28357,ender="3",enderType="NPC",enderId=25462,rewardNextId=12641,poiX=2498,poiY=-5593,wowhead="https://www.wowhead.com/wotlk/quest=12636",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold. Looming above the face of the necropolis is the all-seeing eye of Acherus. From it the master is able to see great distances into the territories held by our enemies. What the eye sees, the Lich King sees, and now the time has come for you to peer through the eye! The Lich King has called for you, $N.$B$BGo now! Suffer well, $g brother:sister;...$B",logDesc="Report to the Lich King in Ebon Hold."} end
if not DB[12637] then DB[12637]={id=12637,zoneId=66,name="Near Miss",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12629,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12637",image="assets/images/quests/placeholder.png",xpDiff=3,money=30000,desc="It was either wisdom or luck that prevented you from wearing this choker, $r.$b$bEither way, your acquiring it was no random occurance. You've been targeted by someone, or something....$b$bTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.",logDesc="Stefan at Ebon Watch wants you to take the Unliving Choker to Bloodrose Datura."} end
if not DB[12638] then DB[12638]={id=12638,zoneId=66,name="Close Call",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12643,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12638",image="assets/images/quests/placeholder.png",xpDiff=3,money=30000,desc="It was either wisdom or luck that prevented you from wearing this choker, $r.$b$bEither way, your acquiring it was no random occurence. You've been targeted by someone, or something....$b$bTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.",logDesc="Stefan at Ebon Watch wants you to take the Writhing Choker to Bloodrose Datura."} end
if not DB[12639] then DB[12639]={id=12639,zoneId=66,name="The Frozen Earth",level=77,minLevel=74,giver="Element-Tamer Dagoda",giverType="NPC",giverId=28480,ender="Element-Tamer Dagoda",enderType="NPC",enderId=28480,poiX=5791,poiY=-3566,wowhead="https://www.wowhead.com/wotlk/quest=12639",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="We captured these elementals from nearby, and I have plenty of defenders now. But, it takes a great deal of power to make them strong enough to stand up to our enemies.$B$BThe frozen earth at Drak'Mabwa to the northwest have what I need to maintain our defenses. I'll need more of their essence if I'm to keep this up.",logDesc="Element-Tamer Dagoda at Zim'Torga wants you to collect 7 Essence of the Frozen Earth.",choiceRewards={{id=39772,qty=1},{id=39835,qty=1},{id=39783,qty=1},{id=39786,qty=1}}} end
if not DB[12640] then DB[12640]={id=12640,zoneId=66,name="Sealing the Rifts",level=77,minLevel=74,giver="Scalper Ahunae",giverType="NPC",giverId=28484,ender="Scalper Ahunae",enderType="NPC",enderId=28484,rewardNextId=12659,poiX=5798,poiY=-3554,wowhead="https://www.wowhead.com/wotlk/quest=12640",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Dagoda gonna be sendin' you northwest to Drak'Mabwa to get her more stuff for her defenders if she didn't already.$B$BWhile you up there, Ahunae be wantin' you to destroy the rifts those elementals pourin' out of. The last thing we needin' is for them to attack us!$B$BJust watch out, more of those frozen earth'll show up when you try to seal the rifts.",logDesc="Scalper Ahunae at Zim'Torga has asked you to seal 7 Elemental Rifts."} end
if not DB[12641] then DB[12641]={id=12641,zoneId=-372,name="Death Comes From On High",level=55,minLevel=55,giver="3",giverType="NPC",giverId=25462,ender="3",enderType="NPC",enderId=25462,rewardNextId=12657,poiX=2345,poiY=-5672,wowhead="https://www.wowhead.com/wotlk/quest=12641",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Towering above this platform is the eye of Acherus. From it you will call forth a probe that you will then use to analyze Scarlet Crusade fortifications at New Avalon. The eye has a host of powers that should make the acquisition of this data simple.$B$BUse the eye's siphon to analyze the forge, town hall, hold, and chapel. The eye's control mechanisms are located on either side of this platform. Waste no more time, $N.$B$BThe Scourge will have this place. The Lich King commands it!",logDesc="The Lich King commands you to use the Eye of Acherus to analyze the Scarlet Hold, New Avalon Forge, New Avalon Town Hall and the Chapel of the Crimson Flame.$B$BControl the Eye of Acherus by using the Eye of Acherus Control Mechanism."} end
if not DB[12642] then DB[12642]={id=12642,zoneId=66,name="Spirit of Rhunok",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="3",enderType="NPC",enderId=28561,rewardNextId=12646,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=12642",image="assets/images/quests/placeholder.png",xpDiff=3,desc="My feelings tell me that Rhunok doesn't have much time.$B$BI can tell that the arctic bear god's spirit has already separated from his weakened body. It is his spirit with which you must commune.$B$BHis altar lies to the northwest beyond Drak'Mabwa.",logDesc="Speak with the Spirit of Rhunok at the Altar of Rhunok."} end
if not DB[12643] then DB[12643]={id=12643,zoneId=66,name="Silver Lining",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12649,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12643",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Once the Scourge have a target in their sights, they'll stop at nothing to acquire it.$b$bYou're doomed to a mindless existence as a walking corpse....$b$b<Stefan's face twists into a cruel grin.>$b$b... unless we can use their desires against them.$b$bI'll explain later. I have complex magic to prepare which requires certain material components.$b$bTravel due east of here to the land beneath the Reliquary of Agony. Slay the ghouls and abominations you'll find there and return to me with their remnants.",logDesc="Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools."} end
if not DB[12644] then DB[12644]={id=12644,zoneId=3711,name="Still At It",level=76,minLevel=76,giver="Grimbooze Thunderbrew",giverType="NPC",giverId=29157,ender="Grimbooze Thunderbrew",enderType="NPC",enderId=29157,rewardNextId=12645,poiX=5543,poiY=5763,wowhead="https://www.wowhead.com/wotlk/quest=12644",image="assets/images/quests/placeholder.png",xpDiff=4,money=48000,desc="Now that we've got the raw materials, I've had my assistant ready the still. He'll oversee the process, but I want you to help keep everything under control. You might be tempted to think that we just throw everything into the still and let it sit, but you're wrong.$B$BIngredients and heat need to be added at certain times, and the pressure regulated at others. You'll have no more than 10 seconds to react to a situation. Speak with \"Tipsy\" McManus when you're ready to start distilling.",logDesc="Successfully complete the distillation process and bring the completed Thunderbrew's Jungle Punch to Grimbooze Thunderbrew at the Nesingwary Base Camp."} end
if not DB[12645] then DB[12645]={id=12645,zoneId=3711,name="The Taste Test",level=76,minLevel=76,giver="Grimbooze Thunderbrew",giverType="NPC",giverId=29157,ender="Grimbooze Thunderbrew",enderType="NPC",enderId=29157,poiX=5543,poiY=5763,wowhead="https://www.wowhead.com/wotlk/quest=12645",image="assets/images/quests/placeholder.png",xpDiff=6,money=124000,desc="And now for the moment of truth!$B$B<Grimbooze chuckles.>$B$BI've always wanted to say that. Normally, I'd debut a new drink at a banquet, but we can't have one in the middle of the jungle.$B$BInstead, just take samples to a few trusted friends and return with their comments. Let's see, we'll definitely want Hemet Nesingwary's opinion, and Hadrius Harlowe's, too. They're here in camp. You'll want to head over to Lakeside Landing, near the center of the Basin and offer Tamara Wobblesprocket a taste.",logDesc="Offer a sample of Thunderbrew's Jungle Punch to Hemet Nesingwary, Hadrius Harlowe, and Tamara Wobblesprocket, then return to Grimbooze Thunderbrew at the Nesingwary Base Camp.",rewards={{id=39520,qty=20}}} end
if not DB[12646] then DB[12646]={id=12646,zoneId=66,name="My Prophet, My Enemy",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28561,ender="3",enderType="NPC",enderId=28561,rewardNextId=12647,poiX=6370,poiY=-3266,wowhead="https://www.wowhead.com/wotlk/quest=12646",image="assets/images/quests/placeholder.png",xpDiff=5,desc="My prophet absorbed too much of my power too quickly, and subsequently killed himself. You can see the results at the water-filled crater to the south in Drak'Mabwa.$B$BMy former priests have already resurrected him so that he can finish the job. They're channeling my power back into him, and it will not be long now before he reawakens.$B$BYou must put an end to him and return with my mojo before it is too late.",logDesc="The Spirit of Rhunok at the Altar of Rhunok has asked you to acquire his Arctic Bear God Mojo."} end
if not DB[12647] then DB[12647]={id=12647,zoneId=66,name="An End to the Suffering",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28561,ender="3",enderType="NPC",enderId=28561,rewardNextId=12653,poiX=6370,poiY=-3266,wowhead="https://www.wowhead.com/wotlk/quest=12647",image="assets/images/quests/placeholder.png",xpDiff=6,desc="My body is too far gone now, $N. It is only a matter of time before a new prophet is elevated and finishes what the other began.$B$BI am going to imbue you with the last of my power. The tormentor inside the altar building carries incense, which will awaken my body and make it vulnerable.$B$BUse the incense and do me the kindness of putting an end to my suffering.$B$BI apologize if I fight back. Even for me, the will to survive is strong.",logDesc="The Spirit of Rhunok has asked you to use the Tormentor's Incense to awaken his body. You are then to slay Rhunok using the power that his spirit has imbued you with.$B$BIf for some reason you lose the Mojo of Rhunok aura, you can return to the Spirit of Rhunok to have it reapplied.",choiceRewards={{id=39789,qty=1},{id=39858,qty=1},{id=39825,qty=1},{id=39893,qty=1}}} end
if not DB[12648] then DB[12648]={id=12648,zoneId=66,name="Dressing Down",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12661,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12648",image="assets/images/quests/placeholder.png",xpDiff=4,money=46000,desc="There... I've created a disguise that should make you indistinguishable from the Scourge.$b$bYou'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!$b$bAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.$b$bLet's test it out. Use the choker and visit the Scourge merchant just east of here. Return to me with a bottle of bitter plasma.",logDesc="Stefan at Ebon Watch wants you to use the Ensorceled Choker to apply the Scourge disguise.$b$bWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.$b$bIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another."} end
if not DB[12649] then DB[12649]={id=12649,zoneId=66,name="Suit Up!",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12661,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12649",image="assets/images/quests/placeholder.png",xpDiff=4,money=46000,desc="There... I've created a disguise that should make you indistinguishable from the Scourge.$b$bYou'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!$b$bAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.$b$bLet's test it out. Use the choker and visit the Scourge vendor just east of here. Return to me with a bottle of bitter plasma.",logDesc="Stefan at Ebon Watch wants you to use the Ensorcelled Choker to apply the Scourge disguise.$b$bWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.$b$bIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another."} end
if not DB[12650] then DB[12650]={id=12650,zoneId=66,name="Plundering Their Own",level=77,minLevel=74,giver="Chronicler To'kini",giverType="NPC",giverId=28527,ender="Chronicler To'kini",enderType="NPC",enderId=28527,poiX=5740,poiY=-3595,wowhead="https://www.wowhead.com/wotlk/quest=12650",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There is another altar nearby where there are artifacts to be saved.$B$BIt is said that the Drakkari at the Altar of Rhunok to the northwest, beyond the broken tundra of Drak'Mabwa, have already plundered their own holy site.$B$B$C, I would be appreciative if you could rescue those artifacts from their undeserving hands.",logDesc="Chronicler To'kini at Zim'Torga wants you to recover 7 Rhunokian Artifacts."} end
if not DB[12651] then DB[12651]={id=12651,zoneId=3711,name="Lakeside Landing",level=77,minLevel=76,giver="Hemet Nesingwary",giverType="NPC",giverId=27986,ender="Tamara Wobblesprocket",enderType="NPC",enderId=28568,poiX=5584,poiY=5749,wowhead="https://www.wowhead.com/wotlk/quest=12651",image="assets/images/quests/placeholder.png",xpDiff=1,money=6600,desc="When the trouble with the Venture Company started, I asked Marvin Wobblesprocket and his wife, Tamara, to take their flying machines east to River's Heart. I asked them to setup a small camp there so that we could use them as a relay to fly in supplies and survey the area.$B$BThey should have arrived by now and started setting up. River's Heart is near the center of the basin where the rivers converge. Search for Lakeshore Landing on the northeast shore. Marvin mentioned it would be the best spot.",logDesc="Speak with Tamara Wobblesprocket at Lakeside Landing."} end
if not DB[12652] then DB[12652]={id=12652,zoneId=66,name="Feedin' Da Goolz",level=75,minLevel=74,giver="Gristlegut",giverType="NPC",giverId=28589,ender="Gristlegut",enderType="NPC",enderId=28589,poiX=5157,poiY=-1592,wowhead="https://www.wowhead.com/wotlk/quest=12652",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Git o'er heer, gool! Yeh, I talkin' to yoo.$b$bIt feedin' time now. Gotta git da grub ta all da gools!$b$bSpeshal grub dis time! Bowels an' brainz bowl... num, num, num.$b$bJus drop da bowl nexta da gool. Gud way ta make frenz.$b$bYoo got goolfrenz? Ha, ha, hah!",logDesc="Gristlegut at the Reliquary of Agony wants you to use Bowels and Brains Bowl next to 10 Decaying Ghouls.",choiceRewards={{id=39812,qty=1},{id=39876,qty=1},{id=39880,qty=1},{id=39882,qty=1},{id=39831,qty=1}}} end
if not DB[12653] then DB[12653]={id=12653,zoneId=66,name="Back to Har'koa",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28561,ender="3",enderType="NPC",enderId=28401,rewardNextId=12665,poiX=6370,poiY=-3266,wowhead="https://www.wowhead.com/wotlk/quest=12653",image="assets/images/quests/placeholder.png",xpDiff=3,desc="And now it is time for you to return to the leopard goddess. Somehow I sense that she has other plans for you.$B$BTell her that no matter what, we are eternal.",logDesc="Speak with Har'koa at the Altar of Har'koa."} end
if not DB[12654] then DB[12654]={id=12654,zoneId=3711,name="The Part-time Hunter",level=76,minLevel=76,giver="Tamara Wobblesprocket",giverType="NPC",giverId=28568,ender="Tamara Wobblesprocket",enderType="NPC",enderId=28568,poiX=5483,poiY=4730,wowhead="https://www.wowhead.com/wotlk/quest=12654",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="When Hemet asked me to accompany Marvin out here, I hoped that I might have the opportunity to work on my own hunting skills in between repairing the flying machines and setting up the camp.$B$BI wanted to take down a ferocious lion named Pitch. He's said to make his home south of here, near where the Wildgrowth Mangal meets the northern face of the Skyreach Pillar. If you can find the beast, would you bring back his remains? If the rumors are true, they'd make a trophy even Hemet will respect!",logDesc="Bring Pitch's Remains to Tamara Wobblesprocket at Lakeside Landing."} end
if not DB[12655] then DB[12655]={id=12655,zoneId=66,name="The Blessing of Zim'Rhuk",level=77,minLevel=74,giver="Witch Doctor Khufu",giverType="NPC",giverId=28479,poiX=5736,poiY=-3571,wowhead="https://www.wowhead.com/wotlk/quest=12655",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There is another god of Zul'Drak that is being neglected.$B$BZim'Rhuk's statue lies directly to the north. Known as \"The Wise One\", Zim'Rhuk is also known to be very protective of his domain. He maintains guardians that deal harshly with anyone that does not have the wits to slip past them.$B$BAvoid the guardians and give the Drakkari offerings to Zim'Rhuk so that you will benefit from his blessing.",logDesc="Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Rhuk."} end
if not DB[12656] then DB[12656]={id=12656,zoneId=66,name="Blessing of Zim'Rhuk",level=77,minLevel=74,wowhead="https://www.wowhead.com/wotlk/quest=12656",image="assets/images/quests/placeholder.png"} end
if not DB[12657] then DB[12657]={id=12657,zoneId=-372,name="The Might Of The Scourge",level=55,minLevel=55,giver="3",giverType="NPC",giverId=25462,ender="3",enderType="NPC",enderId=28444,rewardNextId=12850,poiX=2345,poiY=-5672,wowhead="https://www.wowhead.com/wotlk/quest=12657",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Listen well, death knight, for I give to you the words that will start a war. My final judgment has been passed: Death. To. All. None shall stand so boldly against the might of the Scourge without reprisal!$B$BAs you have served me well in your first task, so too shall you serve me in your next task. Take my judgment to Highlord Mograine at the command post of Acherus, found on the first floor. Tell him to begin the assault.$B$BAnd when the Crusade has been dealt with, we will finish off the Argent Dawn.$B",logDesc="The Lich King commands you to carry his orders to Highlord Darion Mograine at Ebon Hold.$B$BUse the glowing transporter behind the Lich King to reach Highlord Darion Mograine in the Hall of Command.",rewards={{id=38662,qty=1}}} end
if not DB[12658] then DB[12658]={id=12658,zoneId=3711,name="My Pet Roc",level=77,minLevel=76,giver="Zootfizzle",giverType="NPC",giverId=28374,ender="Zootfizzle",enderType="NPC",enderId=28374,poiX=6448,poiY=5095,wowhead="https://www.wowhead.com/wotlk/quest=12658",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Dorian's had me training and feeding the baby drakes he captures, and it has gotten me thinking. I want a pet of my own!$B$BNo, not a juvenile drake. I don't want a pet capable of biting my hand off!$B$BHowever, in the Bonefields to the northeast of the camp, beyond the area dominated by the drakes, there's a large population of goretalon rocs. The grown ones are beyond hope of domesticating, but if you bring me the eggs from their nests, I can raise them from the time they hatch.",logDesc="Bring 7 Roc Eggs to Zootfizzle at Dorian's Outpost."} end
if not DB[12659] then DB[12659]={id=12659,zoneId=66,name="Scalps!",level=77,minLevel=74,giver="Scalper Ahunae",giverType="NPC",giverId=28484,ender="Scalper Ahunae",enderType="NPC",enderId=28484,poiX=5798,poiY=-3554,wowhead="https://www.wowhead.com/wotlk/quest=12659",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="I thinkin' it be time to do some scalpin', mon!$B$BThe trolls at Heb'Drakkar to the northeast should do nicely. With their fancy bats and attackin' us, they got it comin'!$B$BAhunae even give you his own knife so that you do the job right.",logDesc="Scalper Ahunae at Zim'Torga wants you to use Ahunae's Knife to scalp 10 Heb'Drakkar trolls.$B$BThe scalper reminds you that you should loot them first."} end
if not DB[12660] then DB[12660]={id=12660,zoneId=3711,name="Weapons of Destruction",level=77,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="3",enderType="NPC",enderId=27801,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12660",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="The Lich King's lackeys have dared to bring weapons of destruction into my domain.  I will not stand for this.$B$BGo to their outpost to the north and destroy the weapons they would use against the land.  We cannot let the Scourge taint another inch of these sacred lands.",logDesc="The Avatar of Freya wants you to go to the Death's Hand Encampment to the northwest and destroy 4 Unstable Explosives."} end
if not DB[12661] then DB[12661]={id=12661,zoneId=66,name="Infiltrating Voltarus",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12669,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12661",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="By now you've probably guessed the details of my plan.$b$bWe're using the Scourge's interest in you against them. You're going undercover. I know it's likely a death sentence, but if we do nothing your death is a certainty.$b$bTravel northeast to Reliquary of Pain and stand on the platform while wearing your disguise. Once inside Voltarus, you must earn the trust of the Scourge commander.$b$bWhen you've completed your mission, blow this horn and I'll fly to your location to receive your report.",logDesc="Stefan wants you to use your Ensorcelled Choker to get into Voltarus and do whatever the Scourge leader there asks of you.$b$bIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.",choiceRewards={{id=39809,qty=1},{id=39869,qty=1},{id=39866,qty=1},{id=39870,qty=1},{id=39830,qty=1}}} end
if not DB[12662] then DB[12662]={id=12662,zoneId=66,name="Bringing Down Heb'Jin",level=77,minLevel=74,giver="Element-Tamer Dagoda",giverType="NPC",giverId=28480,ender="Element-Tamer Dagoda",enderType="NPC",enderId=28480,poiX=5791,poiY=-3566,wowhead="https://www.wowhead.com/wotlk/quest=12662",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="<Dagoda looks at Ahunae and sighs.>$B$BYou want to really deal with Heb'Drakkar? Collecting scalps isn't going to get the job done. You have to take out their leader, Heb'Jin.$B$BThe problem is, he's up on the bat rookery goading his forces on.$B$BBang his drum and I guarantee that he'll fly down. That's when you kill him.$B$BYou can take this net we got from one of his headhunters. Use it to trap his bat when he lands. That way you won't have to fight both of them.$B",logDesc="Element-Tamer Dagoda at Zim'Torga wants you to kill Heb'Jin.",choiceRewards={{id=39777,qty=1},{id=39836,qty=1},{id=39788,qty=1},{id=39790,qty=1}}} end
if not DB[12663] then DB[12663]={id=12663,zoneId=66,name="Reunited",level=75,minLevel=74,giver="Overlord Drakuru",giverType="NPC",giverId=28503,ender="Overlord Drakuru",enderType="NPC",enderId=28503,poiX=6132,poiY=-1952,wowhead="https://www.wowhead.com/wotlk/quest=12663",image="assets/images/quests/placeholder.png",desc="$n!$b$bYa musta received mah gift! Turn around, mon, lemme get a good look at ya... Ahh, ya make me proud.$b$bWe come such a long way, you and I, and now we be servin' da Lich King together.$b$bStick with me and big things be comin, mon. Big things... but first, we need to be gettin' ya caught up. So much been happenin' since I saw ya last.$b$bGo speak ta Gorebag for a tour of Zul'Drak. Listen for me and I'll tell ya all ya be needin' ta know. ",logDesc="Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak."} end
if not DB[12664] then DB[12664]={id=12664,zoneId=66,name="Dark Horizon",level=75,minLevel=74,giver="Overlord Drakuru",giverType="NPC",giverId=28503,ender="Overlord Drakuru",enderType="NPC",enderId=28503,poiX=6132,poiY=-1952,wowhead="https://www.wowhead.com/wotlk/quest=12664",image="assets/images/quests/placeholder.png",desc="Ahh, another supplicant answerin' da Lich King's call.$b$b<Drakuru sniffs you.>$b$bFreshly scourged, eh? Ya still be reekin' of da living!$b$bLong be da line of dem who seek da Lich King's blessings. Ya must rise above da masses and prove yerself worthy of wieldin' true power.$b$bLookin' down over Zul'Drak, I sensed potential in ya. I ordered your - invitation.$b$bDa rest be up ta you....$b$bGo an' speak ta Gorebag for a tour of Zul'Drak. Dere be much ta do if you're to be of any worth to me.",logDesc="Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak."} end
if not DB[12665] then DB[12665]={id=12665,zoneId=66,name="I Sense a Disturbance",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="3",enderType="NPC",enderId=28401,rewardNextId=12666,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=12665",image="assets/images/quests/placeholder.png",xpDiff=5,desc="There's something wrong with Quetz'lun, the wind serpent goddess. What it is exactly I cannot sense, but I do know that her altar has been overrun with powerful creatures.$B$BI'm going to send you there on the back of one of my children, which you saved. The two of you will move swiftly and with great stealth to uncover what has become of Quetz'lun.$B$BMy child will see you safely back to me. Just keep your eyes open.$B$BWhen you are ready, ask and I will call one of my kittens for you.",logDesc="Har'koa has asked you to determine what has happened to Quetz'lun. Speak to her to be able to ride one of her children stealthily into the Altar of Quetz'lun.$B$BReturn to her at the Altar of Har'koa once you have done so."} end
if not DB[12666] then DB[12666]={id=12666,zoneId=66,name="Preparations for the Underworld",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="3",enderType="NPC",enderId=28401,rewardNextId=12667,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=12666",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Quetz'lun may be dead, but I can still feel her spirit lingering in the underworld at the altar. We have to find a way to get you to her.$B$BLuckily for us, I just happen to have a supply of former supplicants at hand who are no longer in need of their sacred adornments. Both my subduers and claws are likely to still be wearing them.$B$BBring the adornments to me and I'll draw upon their energy to enable you to cross over into Quetz'lun's underworld nightmare.",logDesc="Har'koa wants you to collect 8 Sacred Adornments. Deliver them to her at the Altar of Har'koa."} end
if not DB[12667] then DB[12667]={id=12667,zoneId=66,name="Seek the Wind Serpent Goddess",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="3",enderType="NPC",enderId=28030,rewardNextId=12672,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=12667",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You are prepared, but I'm not certain that you're ready for what is to come.$B$BWhen you cross back over into Quetz'lun's altar area, you will enter the realm of the dead. From what I can feel of it, it's not going to be pleasant.$B$BTry not to be distracted by what you see in there. Simply head for the altar building and seek out Quetz'lun's Spirit.",logDesc="Seek Quetz'lun's Spirit at the Altar of Quetz'lun."} end
if not DB[12668] then DB[12668]={id=12668,zoneId=66,name="Foundation for Revenge",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28030,ender="3",enderType="NPC",enderId=28030,rewardNextId=12674,poiX=5717,poiY=-4365,wowhead="https://www.wowhead.com/wotlk/quest=12668",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I have something special planned for my favorite high priests. But first you get to prove yourself in laying the foundation for my revenge.$B$BYou do still want to live, yes?$B$BAs you have seen, my devotees are enjoying their stay here, but now it's time for them to make final restitution.$B$BDo me the smallest of favors if you would, $N. Lure them near my soul fonts and then put an end to their existences.$B$BThey taste so delicious, and their sacrifice will not go in vain, I can assure you.",logDesc="Quetz'lun's Spirit has tasked you with the destruction of 12 trolls, either Quetz'lun Worshippers or Serpent-Touched Berserkers, near her Soul Fonts.$B$BOnly after you have accomplished this should you return to her at the Altar of Quetz'lun."} end
if not DB[12669] then DB[12669]={id=12669,zoneId=66,name="So Far, So Bad",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12677,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12669",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Everything you've reported is consistent with what we know. Learning of Drakuru and earning his trust will lay the groundwork for your future missions.$b$bReturn to him and do as he says. Do whatever you must to appear sincere, $n. A great deal is riding upon your performance.$b$bThis time I'm adding an additional assignment: While you're in the field, pour this additive into their blight cauldrons. It should neutralize the scourging agent and render the batch useless.",logDesc="Stefan at Ebon Watch wants you to return to Drakuru and complete any tasks he has for you.$b$bWhile at the Reliquary of Pain, you are to use the Diluting Additive on 5 Blight Cauldrons.$b$bIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.",choiceRewards={{id=39810,qty=1},{id=39871,qty=1},{id=39872,qty=1},{id=39874,qty=1}}} end
if not DB[12670] then DB[12670]={id=12670,zoneId=-372,name="The Scarlet Harvest",level=55,minLevel=55,giver="Scourge Commander Thalanor",giverType="NPC",giverId=28510,ender="3",enderType="NPC",enderId=28377,rewardNextId=12678,poiX=2370,poiY=-5675,wowhead="https://www.wowhead.com/wotlk/quest=12670",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Below Acherus stands Death's Breach, the staging point for our assault upon the Scarlet Crusade. You are to ride one of my Scourge gryphons, located on either side of this platform, and report to Prince Valanar. Do as he says and you may live to see these lands fall before us.",logDesc="Report to Prince Valanar at Death's Breach."} end
if not DB[12671] then DB[12671]={id=12671,zoneId=3711,name="Reconnaissance Flight",level=77,minLevel=77,giver="Pilot Vic",giverType="NPC",giverId=28746,ender="Pilot Vic",enderType="NPC",enderId=28746,poiX=5501,poiY=4753,wowhead="https://www.wowhead.com/wotlk/quest=12671",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="It's about time we had planes up and running in this place.  The professor's been asking me to check out a strange weather pattern coming from the northeast.$B$BThing is, I'm going to need a co-pilot if we're going into uncharted territory.  No way in hell I'm heading out there alone.$B$BWhat do you say, $g tough-guy : hotshot;?  You might learn a thing or two.  And once you learn to deal with the northern winds... you can pretty much fly anywhere.",logDesc="Help Pilot Vic complete the Reconnaissance Flight."} end
if not DB[12672] then DB[12672]={id=12672,zoneId=66,name="Setting the Stage",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28030,ender="3",enderType="NPC",enderId=28030,rewardNextId=12668,poiX=5717,poiY=-4365,wowhead="https://www.wowhead.com/wotlk/quest=12672",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I will give you a chance at continued existence.$B$BThere are fragments of the power that fueled my curse scattered about the altar grounds. It is my desire that you collect some of them for me. Not so many that the curse will be lifted, but enough that I will be able to eventually make use of them to exact revenge upon my prophet.$B$BGo, insect. Run and do my bidding before I change my mind about letting you live.",logDesc="Quetz'lun's Spirit has demanded that you collect 10 Underworld Power Fragments. Return to her at the Altar of Quetz'lun only when you have done so."} end
if not DB[12673] then DB[12673]={id=12673,zoneId=66,name="It Rolls Downhill",level=75,minLevel=74,giver="Overlord Drakuru",giverType="NPC",giverId=28503,ender="Overlord Drakuru",enderType="NPC",enderId=28503,poiX=6132,poiY=-1952,wowhead="https://www.wowhead.com/wotlk/quest=12673",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="If ya ever gonna be worthy of da Lich King's gifts, ya must learn ta be a great leader - one who be commandin' respect!$b$bI got a task dat gonna refine your command skills, mon....$b$bSumma my minions be trained ta harvest blight crystals from da land below, but dey be lazy and slow. You gonna be in charge o' dem, mon.$b$bTake dis scepter and teach 'em how to get da job done. When dey be under your control, make 'em harvest dem crystals!",logDesc="Overlord Drakuru in Voltarus wants you to use the Scepter of Suggestion on the Blight Geists and then order them to harvest 7 Blight Crystals."} end
if not DB[12674] then DB[12674]={id=12674,zoneId=66,name="Hell Hath a Fury",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28030,ender="3",enderType="NPC",enderId=28030,rewardNextId=12675,poiX=5717,poiY=-4365,wowhead="https://www.wowhead.com/wotlk/quest=12674",image="assets/images/quests/placeholder.png",xpDiff=6,desc="It is now time for you to punish my three high priests: Mu'funu, Tua-Tua, and Hawinni. You'll find them spread around the altar grounds.$B$BTake this hexxing stick. I've empowered it with my rage and indignation. I'm sure that it will prove potent.$B$BJust use it and proceed to destroy them. The hex will take care of the rest.$B$B<Quetz'lun displays a toothy grin.>$B$BSucceed and I may let you go. Fail and die.",logDesc="Quetz'lun's Spirit at the Altar of Quetz'lun wants you to use Quetz'lun's Hexxing Stick upon High Priest Mu'funu, High Priestess Tua-Tua, and High Priest Hawinni. Once you have done this, slay them.",choiceRewards={{id=39791,qty=1},{id=39859,qty=1},{id=39839,qty=1},{id=39841,qty=1}}} end
if not DB[12675] then DB[12675]={id=12675,zoneId=66,name="One Last Thing",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28030,ender="3",enderType="NPC",enderId=28401,rewardNextId=12684,poiX=5717,poiY=-4365,wowhead="https://www.wowhead.com/wotlk/quest=12675",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There is one last thing that is needed to enact the final revenge against my prophet. The power fragments you collected must be imbued with a portion of a living gods' spirit. You're going to need to beseech Har'koa for some of hers.$B$BOnce you've done that, when you return here, you will not come to the underworld. Instead, you will return to the physical world of my altar. My children and guardians will no longer attack you, and you'll be able to get to my prophet without having to worry about them.",logDesc="Deliver the Underworld Power Fragments to Har'koa and beseech her for a portion of her spirit. You will still find her at the Altar of Har'koa."} end
if not DB[12676] then DB[12676]={id=12676,zoneId=66,name="Sabotage",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12713,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12676",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="While we're working to discover the purpose of these crystals, we need you back in Voltarus doing Drakuru's bidding.$b$bEvery task you perform successfully gets you closer to him, and brings us that much nearer to knowing his mind.$b$bWhile you're there, I have another mission for you. Drakuru's Scourgewagons pose a significant threat. We need them destroyed. $b$bMake your way to the wagons and activate these charges. Once they're set, get clear! The explosion will expose you if you're too close.",logDesc="Stefan at Ebon Watch wants you to perform another task for Drakuru.$b$bAdditionally, you are to use the Explosive Charges on 5 Scourgewagons at the  Reliquary of Pain.$b$bIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.",choiceRewards={{id=39811,qty=1},{id=39873,qty=1},{id=39875,qty=1},{id=39877,qty=1}}} end
if not DB[12677] then DB[12677]={id=12677,zoneId=66,name="Hazardous Materials",level=75,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12676,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12677",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Blight crystals?! What could this scumbag Drakuru be up to? Clearly, he's working on something significant.$b$bContinue to do his bidding and perhaps once he's more familiar with you he'll reveal his plans. In the meantime, we need to have a look at these crystals.$b$bWhile you're in Voltarus, try to get some samples of the harvested crystals when no one's looking.$b$bBe alert! Handling those crystals can trigger your disguise to fail.",logDesc="Stefan at Ebon Watch wants you to go to Voltarus and complete any tasks Drakuru has for you. While there, you are to steal 5 Harvested Blight Crystals.$b$bIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another."} end
if not DB[12678] then DB[12678]={id=12678,zoneId=-372,name="If Chaos Drives, Let Suffering Hold The Reins",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28377,ender="3",enderType="NPC",enderId=28377,poiX=2371,poiY=-5701,wowhead="https://www.wowhead.com/wotlk/quest=12678",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="They make their stand now, outside of Death's Breach, futilely attempting to push us back in hopes of saving their horses, mines, lumber and citizens.$B$BThis will be your first lesson in Scourge warfare: TERROR!$B$BGo to the front lines, south of here, and destroy Scarlet Crusaders. Leave their corpses so that we may utilize them for the death march.$B$BBut most importantly: kill the fleeing villagers. Soldiers dying are an affordance, but villagers? That is what strikes fear into the hearts of man.",logDesc="Prince Valanar at Death's Breach commands you to slay 10 Scarlet Crusaders or Scarlet Peasants and 10 Citizens of Havenshire.",rewards={{id=38671,qty=1}}} end
if not DB[12679] then DB[12679]={id=12679,zoneId=-372,name="Tonight We Dine In Havenshire",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28647,ender="3",enderType="NPC",enderId=28647,poiX=2322,poiY=-5748,wowhead="https://www.wowhead.com/wotlk/quest=12679",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="The Sky Darkeners are mindless constructs with one purpose: KILL! Specifically, they are aiming to kill any man or woman that they see fleeing Havenshire for the safety of New Avalon. We certainly can't allow those cowards to make it to safety and then take up arms against us!$B$BThere is one slight problem. They use saronite arrows for maximum range and damage. Saronite, however, is a metal only found in Northrend, so supplies are limited! Retrieve those arrows for me and I will reward you handsomely.",logDesc="Orithos the Sky Darkener at Death's Breach wants you to recover 15 Saronite Arrows.",choiceRewards={{id=39320,qty=1},{id=38664,qty=1},{id=39322,qty=1}}} end
if not DB[12680] then DB[12680]={id=12680,zoneId=-372,name="Grand Theft Palomino",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28653,ender="3",enderType="NPC",enderId=28653,rewardNextId=12687,poiX=2351,poiY=-5701,wowhead="https://www.wowhead.com/wotlk/quest=12680",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="How fortuitous it is that the Crusade has a stable full of horses a mere stone's throw from this post. Though they guard it tenaciously, an enterprising young death knight could break through their defenses and take what is rightfully $g his:hers;!$B$BOnce you acquire a horse from the Havenshire Stables, return it to me and I will see what can be done about transforming it into a proper deathcharger.$B$BRemember, $N, it's only stealing if you're caught. Watch out for that deranged stable master, Kitrik!",logDesc="Salanar the Horseman asks that you steal a horse from the Havenshire Stables and return it to him at Death's Breach."} end
if not DB[12681] then DB[12681]={id=12681,zoneId=3711,name="Reagent Agent",level=77,minLevel=76,giver="Colvin Norrington",giverType="NPC",giverId=28771,ender="Colvin Norrington",enderType="NPC",enderId=28771,poiX=6455,poiY=5097,wowhead="https://www.wowhead.com/wotlk/quest=12681",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="That Archmage Pentarus, back in Dalaran, will be expecting us to return with all kinds of reagents and talismans. It seems the locals are fond of animal parts. Twisted claws from the goretalon rocs are among their favorite.$B$BIt's not my place to say whether the rumors are true or not, but I've a feeling there's something here.$B$BThe rocs live in the Bonefields off to the northeast, where they feed on the corpses of old mammoths. Will you help me gather talons for the archmage's research?",logDesc="Bring 5 Twisted Roc Claws to Colvin Norrington at Dorian's Outpost.",choiceRewards={{id=39368,qty=1},{id=39413,qty=1},{id=39445,qty=1},{id=39463,qty=1}}} end
if not DB[12682] then DB[12682]={id=12682,zoneId=3711,name="Uncharted Territory (DEPRECATED)",level=76,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=12682",image="assets/images/quests/placeholder.png",xpDiff=4,money=48000,desc="Not all of us in this expedition are here to hunt the biggest and rarest game.  Some of us actually have serious work to do.$B$BThe mere existence of this place boggles the mind -- a tropical paradise in the middle of Northrend.  I wouldn't be a scholar worthy of the name if I didn't put some effort into trying to understand this place.$B$BTake these "} end
if not DB[12683] then DB[12683]={id=12683,zoneId=3711,name="Burning to Help",level=77,minLevel=76,giver="Colvin Norrington",giverType="NPC",giverId=28771,ender="Colvin Norrington",enderType="NPC",enderId=28771,poiX=6455,poiY=5097,wowhead="https://www.wowhead.com/wotlk/quest=12683",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="There's no more caustic material in all of the basin than bittertide hydra sputum. I've got special containers to collect just such a thing for Archmage Pentarus' studies. Now all I need is a brave, um... collector.$B$BYou look like a hardy, adventurous $c. How'd you like to make a bit of money and aid Dalaran's cause at the same time?$B$BAll you need to do is take this container with you to Bittertide Lake, to the southwest. Engage the hydra and use the container to sample the sputum they shower you with.",logDesc="Colvin Norrington at Dorian's Outpost wants you to take 5 Hydra Sputum Samples and kill 5 Bittertide Hydra."} end
if not DB[12684] then DB[12684]={id=12684,zoneId=66,name="Blood of a Dead God",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="3",enderType="NPC",enderId=28401,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=12684",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Mam'toth, the god of the mammoths, destroyed himself, and took much of his temple with him, rather than allowing his trolls to gain his power.$B$BIf I'm to sacrifice a portion of my spirit, I will need something with which to bolster myself.$B$BMam'toth left behind an enormous crater to the northeast, just north of the Altar of Quetz'lun. Within the crater his blood yet lives.$B$BBring it to me.",logDesc="Har'koa has asked you to collect 7 Blood of Mam'toth. Return them to her at the Altar of Har'koa."} end
if not DB[12685] then DB[12685]={id=12685,zoneId=66,name="You Reap What You Sow",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="Witch Doctor Khufu",enderType="NPC",enderId=28479,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=12685",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This is what it has come down to... revenge.$B$B<Har'koa sighs.>$B$BTake this ritual kit and enact it near Quetz'lun's corpse upon her altar. If everything works properly, her spirit should be drawn into the material world where she will be able to reclaim her power from the prophet.$B$BThe rest will be up to you, $N. You must slay the prophet in his drained state.",logDesc="Slay the Drained Prophet of Quetz'lun and then inform Witch Doctor Khufu at Zim'Torga.",choiceRewards={{id=39844,qty=1},{id=39861,qty=1},{id=39793,qty=1},{id=39845,qty=1},{id=39826,qty=1}}} end
if not DB[12686] then DB[12686]={id=12686,zoneId=66,name="Zero Tolerance",level=75,minLevel=74,giver="Overlord Drakuru",giverType="NPC",giverId=28503,ender="Overlord Drakuru",enderType="NPC",enderId=28503,poiX=6132,poiY=-1952,wowhead="https://www.wowhead.com/wotlk/quest=12686",image="assets/images/quests/placeholder.png",xpDiff=3,money=30000,desc="Ignorance! Dis be intolerable, mon! My entire batch of blight be useless!$b$bDat mongrel, Darmuk! He be responsible for watchin over da blight. He failed me, mon!$b$bDis be a good lesson for ya, $n. Failure be like a disease dat spreads. Ya gotta catch it and kill it early, before it be killin' you!$b$bTake dis scepter. It make my scourged trolls stronger. Use dem ta kill Darmuk. He be lurkin' down below just to da south.$b$bLet dat be an example to all, mon. Don't be failin' Drakuru!",logDesc="Drakuru in Voltarus wants you to go to the Reliquary of Pain and use the Scepter of Empowerment on a Servant of Drakuru. You are then to use its abilities to defeat Darmuk."} end
if not DB[12687] then DB[12687]={id=12687,zoneId=-372,name="Into the Realm of Shadows",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28653,ender="3",enderType="NPC",enderId=28653,poiX=2351,poiY=-5701,wowhead="https://www.wowhead.com/wotlk/quest=12687",image="assets/images/quests/placeholder.png",xpDiff=8,money=8500,desc="The horse you stole has been taken to the Realm of Shadows. It is there that my dark rider will slay the beast and raise it as a deathcharger. Do you think yourself brave enough to enter the Realm of Shadows in pursuit of the deathcharger?$B$BIf you accept, I will transport you to the shadow world. Once there, seek out a dark rider in the open fields south of us. To emerge victorious you must slay him, overtake his deathcharger and return it to Death's Breach. Issue the Horseman's Call should you succeed.",logDesc="Salanar the Horseman at Death's Breach has challenged you to slay the Dark Rider of Acherus and take his Acherus Deathcharger.$B$BShould you succeed, return the Acherus Deathcharger to Death's Breach and use the Horseman's Call to summon Salanar.",rewards={{id=39208,qty=1}}} end
if not DB[12688] then DB[12688]={id=12688,zoneId=3711,name="Engineering a Disaster",level=76,minLevel=76,giver="Engineer Helice",giverType="NPC",giverId=28787,ender="Hemet Nesingwary",enderType="NPC",enderId=27986,poiX=5910,poiY=5380,wowhead="https://www.wowhead.com/wotlk/quest=12688",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="These goblin goons and their minions have decided that they own this pillar and its crystals. I came here to explore the crystals and take samples, but they overpowered me and won't let me return to the camp.$B$BIf you'll help me fight our way out of here, we can teach these thugs a lesson they'll never forget!",logDesc="Help Engineer Helice escape from Swindlegrin's Dig, then speak with Hemet Nesingwary at the Nesingwary Base Camp."} end
if not DB[12689] then DB[12689]={id=12689,zoneId=3711,name="Hand of the Oracles",level=77,minLevel=76,giver="Jaloot",giverType="NPC",giverId=28667,ender="Jaloot",enderType="NPC",enderId=28121,poiX=5617,poiY=3773,wowhead="https://www.wowhead.com/wotlk/quest=12689",image="assets/images/quests/placeholder.png",xpDiff=3,money=33000} end
if not DB[12690] then DB[12690]={id=12690,zoneId=66,name="Fuel for the Fire",level=75,minLevel=74,giver="Overlord Drakuru",giverType="NPC",giverId=28503,ender="Overlord Drakuru",enderType="NPC",enderId=28503,rewardNextId=12710,poiX=6132,poiY=-1952,wowhead="https://www.wowhead.com/wotlk/quest=12690",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="It be time we start our march to Gundrak, mon. It be time for me ta turn ya loose on dem trolls!$b$bDey breached our wall and put a whole army just north of us.$b$bHahaha!$b$bDey be fuel for da fire, mon! We gunna take da chieftiains an' kill da rest! It all be part of my master plan....$b$bYou take dis scepter and go command my abominations. Bring 'em to da Drakkari army and kill em all! When da chieftains come, my pet Shalewing gunna snatch 'em up and bring 'em here to me.",logDesc="Drakuru in Voltarus wants you to use the Scepter of Command on Bloated Abominations and then use their abilities at the Frigid Breach to kill 60 Drakkari Skullcrushers and lure out 3 Drakkari Chieftains.$b$bChieftains will appear when enough Skullcrushers have been slain."} end
if not DB[12691] then DB[12691]={id=12691,zoneId=3711,name="A Timeworn Coffer",level=78,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=12691",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="The stone coffer appears to be locked.  It appears that a key fits inside a large stone keyhole.$B$BPerhaps one of the guardians in the vicinity has this key in its possession.",logDesc="Obtain a Huge Stone Key from the nearby Sholazar Guardians and bring it to the Timeworn Coffer at the Maker's Overlook.",choiceRewards={{id=39348,qty=1},{id=39402,qty=1},{id=39438,qty=1},{id=39508,qty=1}}} end
if not DB[12692] then DB[12692]={id=12692,zoneId=3711,name="Return of the Lich Hunter",level=77,minLevel=76,giver="Zepik the Gorloc Hunter",giverType="NPC",giverId=28668,ender="Elder Harkek",enderType="NPC",enderId=28138,poiX=5632,poiY=3794,wowhead="https://www.wowhead.com/wotlk/quest=12692",image="assets/images/quests/placeholder.png",xpDiff=3,money=33000,desc="Okay, I going back to Frenzyheart Hill to make sure all Frenzyheart know what you done for wolvar and for Zepik. You great hunter and they dumb to think you not.$B$BGo back to hill and talk to Elder Harkek... I make sure he knows you not traitor before any other Frenzyheart.$B$BThank you, Lich Hunter.",logDesc="Return to Frenzyheart Hill and speak to Elder Harkek."} end
if not DB[12693] then DB[12693]={id=12693,zoneId=0,name="Wolvar Faction Choice Tracker",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=12693",image="assets/images/quests/placeholder.png"} end
if not DB[12694] then DB[12694]={id=12694,zoneId=0,name="Oracle Faction Choice Tracker",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=12694",image="assets/images/quests/placeholder.png"} end
if not DB[12695] then DB[12695]={id=12695,zoneId=3711,name="Return of the Friendly Dryskin",level=77,minLevel=76,giver="Jaloot",giverType="NPC",giverId=28667,ender="High-Oracle Soo-say",enderType="NPC",enderId=28027,poiX=5617,poiY=3773,wowhead="https://www.wowhead.com/wotlk/quest=12695",image="assets/images/quests/placeholder.png",xpDiff=3,money=33000,desc="Yay! Soo-say probably worrying about us! Maybe you go back to town and tell him everything okay? Yeah, go tell Soo-say.$B$BI going grab shiny ball thing from dead lich guy - I meet you there! Go go! I meet you there!",logDesc="Return to Rainspeaker Canopy and speak to High-Oracle Soo-say."} end
if not DB[12696] then DB[12696]={id=12696,zoneId=3711,name="Aerial Surveillance",level=77,minLevel=77,giver="Professor Calvert",giverType="NPC",giverId=28266,ender="Pilot Vic",enderType="NPC",enderId=28746,poiX=5590,poiY=5822,wowhead="https://www.wowhead.com/wotlk/quest=12696",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You did a good job helping Wes with getting that flying machine back up and running.$B$BIf you'd like to help us further, there is an unusual weather pattern coming in from the northeast.  I have a pilot ready to work for me, but I'm afraid he needs a copilot.$B$BIf you think you're up to it, you can take the flight to Lakeside Landing.  Tell Vic I sent you.",logDesc="Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there."} end
if not DB[12697] then DB[12697]={id=12697,zoneId=-372,name="Gothik the Harvester",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28377,ender="3",enderType="NPC",enderId=28658,rewardNextId=12698,poiX=2371,poiY=-5701,wowhead="https://www.wowhead.com/wotlk/quest=12697",image="assets/images/quests/placeholder.png",xpDiff=1,desc="CHAOS, $N! The Crusade is in a frenzy. They have diverted all forces outside of New Avalon to set up a blockade at Light's Point, east of here. They are desperately trying to strip the Havenshire Mine of all resources and load the cargo aboard the frigates they have docked on the coast.$B$BLet's stir things up a bit, shall we? Gothik the Harvester, grand necromancer of the Lich King, has graced us with his presence. He has a gift he'd like to bestow upon the Scarlet Crusade. Seek him out.",logDesc="Speak with Gothik the Harvester at Death's Breach."} end
if not DB[12698] then DB[12698]={id=12698,zoneId=-372,name="The Gift That Keeps On Giving",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28658,ender="3",enderType="NPC",enderId=28658,rewardNextId=12700,poiX=2349,poiY=-5758,wowhead="https://www.wowhead.com/wotlk/quest=12698",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="I have come from the frozen heart of Naxxramas to feast on souls and deliver a vicious thrashing upon our sworn enemies - and I'm all out of souls.$B$BThis device I am about to give to you is a portable plague spreader. Take it east, to the Havenshire Mines, and unleash it near the Scarlet miners working inside. Use it to turn the miners into ghouls and return to me when you have a small army at your side. I have saved a special place for them in the vacuum cleaner of souls!",logDesc="Gothik the Harvester at Death's Breach has given you the Gift of the Harvester to use on Scarlet Miners. Create 5 Scarlet Ghouls with the device and return the ghouls to Gothik.",rewards={{id=38674,qty=1}}} end
if not DB[12699] then DB[12699]={id=12699,zoneId=3711,name="An Embarassing Incident",level=77,minLevel=77,giver="Pilot Vic",giverType="NPC",giverId=28746,ender="Pilot Vic",enderType="NPC",enderId=28746,rewardNextId=12671,poiX=5501,poiY=4753,wowhead="https://www.wowhead.com/wotlk/quest=12699",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="There's one little problem we have to solve before we head out.  You see, I can't seem to find the keys to my flying machine.$B$BI've looked pretty much everywhere for them... maybe you can give me a hand.  Only place I haven't looked yet is inside the lake.$B$BI'll even give you my very own air tank.  It's almost empty, but it's got a couple of hits left.",logDesc="Look for Vic's Keys inside the lake at River's Heart."} end
if not DB[12700] then DB[12700]={id=12700,zoneId=-372,name="An Attack Of Opportunity",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28658,ender="3",enderType="NPC",enderId=28377,rewardNextId=12701,poiX=2349,poiY=-5758,wowhead="https://www.wowhead.com/wotlk/quest=12700",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Only the Scarlet forces at New Avalon and Light's Point challenge us! The time to attack the Scarlet fleet at Light's Point has come.$B$BThe diversion at the mine has caused chaos amidst their ranks. They are frantically working to clear the area and return to their ships.$B$BThe time is ripe! Prince Valanar is seizing this opportunity to finish off the Scarlet fleet. Report to him at once!",logDesc="Speak with Prince Valanar at Death's Breach."} end
if not DB[12701] then DB[12701]={id=12701,zoneId=-372,name="Massacre At Light's Point",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28377,ender="3",enderType="NPC",enderId=28377,rewardNextId=12706,poiX=2371,poiY=-5701,wowhead="https://www.wowhead.com/wotlk/quest=12701",image="assets/images/quests/placeholder.png",xpDiff=8,money=25000,desc="In their haste the Crusade will make one fatal error: forgetting to check the mine cars.$B$BYou are to return to Havenshire Mine, east of here, and locate the mine car that my minions have planted near the outhouse. Climb inside the mine car and a Scarlet miner will unwittingly see to it that you are placed safely behind enemy lines.$B$BOnce aboard one of their ships, use the cannons against them! SLAUGHTER THEM ALL!$B$BCall the Scourge gryphon from the cannon when you are ready to return.",logDesc="Prince Valanar at Death's Breach has commanded you to slaughter 100 Scarlet Defenders.",rewards={{id=38666,qty=1}}} end
if not DB[12702] then DB[12702]={id=12702,zoneId=3711,name="Chicken Party!",level=77,minLevel=76,giver="Elder Harkek",giverType="NPC",giverId=28138,ender="Elder Harkek",enderType="NPC",enderId=28138,poiX=5264,poiY=4511,wowhead="https://www.wowhead.com/wotlk/quest=12702",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="I bet you not guess what happen again.$B$BNope, not Goregek or chickens.$B$BOkay, I lie. Goregek let chickens out again. Dumb Goregek and rumbly belly.$B$BLet me know if you need help from any of the hunters... they around here somewhere.",logDesc="Capture 12 Chicken Escapees for Elder Harkek at Frenzyheart Hill."} end
if not DB[12703] then DB[12703]={id=12703,zoneId=3711,name="Kartak's Rampage",level=78,minLevel=76,giver="Vekgar",giverType="NPC",giverId=29146,ender="Shaman Jakjek",enderType="NPC",enderId=28106,poiX=5293,poiY=4510,wowhead="https://www.wowhead.com/wotlk/quest=12703",image="assets/images/quests/placeholder.png",xpDiff=6,money=136000,desc="You the great Lich Hunter, eh? Good to have such strong Frenzyheart ally for battle. Maybe you strong enough to call Kartak even.$B$BBig battle at Kartak's Hold to southwest.  Go kill spark big-tongues until you get good bit of Oracle Blood. Bring blood to altar in Kartak's Hold to call Kartak for delicious feast of big-tongue.$B$BKartak take your body if you worthy... with Kartak's powers, you slaughter more big-tongues than even best dreams.$B$BGo kill lots, hunter!",logDesc="Bring a pure sample of Oracle Blood to the Altar of Kartak to summon Kartak. With the aid of Kartak's shared powers, slaughter 50 of the nearby Sparktouched Gorlocs for Shaman Jakjek in Kartak's Hold."} end
if not DB[12704] then DB[12704]={id=12704,zoneId=3711,name="Appeasing the Great Rain Stone",level=77,minLevel=76,giver="High-Oracle Soo-say",giverType="NPC",giverId=28027,ender="High-Oracle Soo-say",enderType="NPC",enderId=28027,poiX=5651,poiY=4551,wowhead="https://www.wowhead.com/wotlk/quest=12704",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Since mosswalker been attacked I worried maybe we not good to Great Rain Stone... we maybe too greedy. We need more treasures to offer!$B$BYou good at finding shinies last time... maybe you go look more around village for shinies? You maybe need one of good Rainspeakers for help. Just tell us who.",logDesc="High-Oracle Soo-say in Rainspeaker Canopy wants you to take a companion to dig up and collect 6 Shiny Treasures.$B$BBe sure to speak to High-Oracle Soo-say in Rainspeaker Canopy about securing the aid of one of your previous companions."} end
if not DB[12705] then DB[12705]={id=12705,zoneId=3711,name="Will of the Titans",level=78,minLevel=76,giver="Oracle Soo-dow",giverType="NPC",giverId=29149,ender="Lightningcaller Soo-met",enderType="NPC",enderId=28107,poiX=5726,poiY=4570,wowhead="https://www.wowhead.com/wotlk/quest=12705",image="assets/images/quests/placeholder.png",xpDiff=6,money=136000,desc="Puppy-men been attacking Sparktouched... we need fight or they just attack other Oracles too.$B$BYou been good friend to us, so maybe we allow you special honor. Great Ones left protector long time ago for shrines... it here still, but it not know something wrong til shrines messed with.$B$BPuppy-men down there have bad crystals for making trouble... bring a bad crystal to Lightning Shrine so Soo-holu know to help.$B$BDon't be scared if Soo-holu take your body... he very powerful, so he keep you safe.",logDesc="Obtain a Tainted Crystal from the wolvar near Sparktouched Haven and bring it to the Great Lightning Stone to call Soo-holu. With the aid of Soo-holu's shared powers, kill 50 of the nearby Frenzyheart wolvar, then return to Lightningcaller Soo-met near the Great Lightning Stone."} end
if not DB[12706] then DB[12706]={id=12706,zoneId=-372,name="Victory At Death's Breach!",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28377,ender="3",enderType="NPC",enderId=28444,rewardNextId=12714,poiX=2371,poiY=-5701,wowhead="https://www.wowhead.com/wotlk/quest=12706",image="assets/images/quests/placeholder.png",xpDiff=8,money=8500,desc="<Prince Valanar hands you a sealed scroll.>$B$BThis is the full report of our victory at Death's Breach. You are to deliver this to Highlord Mograine - inside Acherus. I have made sure to include your heroics in the report. Mograine will undoubtedly reward you greatly for this victory, $N.$B$BGo now!",logDesc="Deliver Prince Valanar's Report to Highlord Darion Mograine in Acherus: The Ebon Hold.",rewards={{id=38669,qty=1}}} end
if not DB[12707] then DB[12707]={id=12707,zoneId=66,name="Wooly Justice",level=77,minLevel=74,giver="Scalper Ahunae",giverType="NPC",giverId=28484,ender="Scalper Ahunae",enderType="NPC",enderId=28484,poiX=5798,poiY=-3554,wowhead="https://www.wowhead.com/wotlk/quest=12707",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Ahunae hear about your trip to Mam'toth Crater, mon. The children of Mam'toth are enraged and cry out for justice!$B$BFollow the avenue northeast up the steps to the next tier of Zul'Drak. On your right you will find what's left of the Altar of Mam'toth.$B$BWhen you get there, flash this Medallion of Mam'toth in front of the eyes of one of the enraged mammoths. It'll calm down for a little while, letting you hop on its back.$B$BRide it around, trampling all of the Mam'toth disciples that you can find!",logDesc="Scalper Ahunae at Zim'Torga wants you to use the Medallion of Mam'toth to calm and ride an Enraged Mammoth. You are then to trample 12 Mam'toth Disciples to death.",choiceRewards={{id=39770,qty=1},{id=39833,qty=1},{id=39776,qty=1},{id=39778,qty=1},{id=39818,qty=1}}} end
if not DB[12708] then DB[12708]={id=12708,zoneId=66,name="Enchanted Tiki Warriors",level=77,minLevel=74,giver="Element-Tamer Dagoda",giverType="NPC",giverId=28480,ender="Element-Tamer Dagoda",enderType="NPC",enderId=28480,poiX=5791,poiY=-3566,wowhead="https://www.wowhead.com/wotlk/quest=12708",image="assets/images/quests/placeholder.png",xpDiff=5,desc="I know that you're headed up to the Zol'Maz Stronghold to the northeast, $c. While you're there, I need you to deal with the warlord's special guardians.$B$BThe enchanted tiki warriors, as they're called, represent a very real threat. If the Drakkari were to mass produce them, we'd quickly be overrun.$B$BLet's you and I demonstrate that they're not worth the effort to create, shall we?",logDesc="Element-Tamer Dagoda at Zim'Torga has asked you to destroy 12 Enchanted Tiki Warriors."} end
if not DB[12709] then DB[12709]={id=12709,zoneId=66,name="Hexed Caches",level=77,minLevel=74,giver="Chronicler To'kini",giverType="NPC",giverId=28527,ender="Chronicler To'kini",enderType="NPC",enderId=28527,poiX=5740,poiY=-3595,wowhead="https://www.wowhead.com/wotlk/quest=12709",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Pardon me, $N. I'm given to understand that you might be heading northeast up to the Zol'Maz Stronghold. Such a trip presents a great opportunity for us to conclude our Drakkari goods gathering.$B$BAs I have come to know, the Drakkari warlord is extremely paranoid. He's had all of his caches at the stronghold hexed with dire magic. Rumor has it that his tiki warriors carry the cure, but who can say?$B$BIf you could find the time to acquire some of those goods, I would be most appreciative.",logDesc="Chronicler To'kini at Zim'Torga has asked you to acquire 12 Zol'Maz Stronghold Caches.",choiceRewards={{id=39797,qty=1},{id=39863,qty=1},{id=39848,qty=1},{id=39849,qty=1}}} end
if not DB[12710] then DB[12710]={id=12710,zoneId=66,name="Disclosure",level=75,minLevel=74,giver="Overlord Drakuru",giverType="NPC",giverId=28503,ender="Overlord Drakuru",enderType="NPC",enderId=28503,poiX=6132,poiY=-1952,wowhead="https://www.wowhead.com/wotlk/quest=12710",image="assets/images/quests/placeholder.png",xpDiff=3,money=30000,desc="Ya doin' well, $n.$b$bYou be provin' dat I got an eye for talent! Now ya see why da Lich King gave me his blessing....$b$bDa time has come for me to reveal my master plan to ya, mon.$b$bNow you be seein' how we gunna sweep through da swarms of Drakkari trolls to take our rightful place in da great palace of Gundrak.$b$bTake dis scepter, mon. It be a token of my trust in ya. With it, you be able ta access my upper chamber and witness for yourself our secret weapons.",logDesc="Drakuru in Voltarus wants you to take the teleporter to his upper chamber."} end
if not DB[12711] then DB[12711]={id=12711,zoneId=-372,name="Abandoned Mail",level=55,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=12711",image="assets/images/quests/placeholder.png",xpDiff=1} end
if not DB[12712] then DB[12712]={id=12712,zoneId=66,name="The Key of Warlord Zol'Maz",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="3",enderType="NPC",enderId=28401,rewardNextId=12721,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=12712",image="assets/images/quests/placeholder.png",xpDiff=6,desc="$N, we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter.$B$BThe Drakkari warlord, Zol'Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast.$B$BThe warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home's gate.",logDesc="Har'koa at Zim'Torga has asked you to acquire the Key of Warlord Zol'Maz."} end
if not DB[12713] then DB[12713]={id=12713,zoneId=66,name="Betrayal",level=76,minLevel=74,giver="Stefan Vadu",giverType="NPC",giverId=28518,ender="Stefan Vadu",enderType="NPC",enderId=28518,poiX=5212,poiY=-1302,wowhead="https://www.wowhead.com/wotlk/quest=12713",image="assets/images/quests/placeholder.png",xpDiff=7,money=186000,desc="The time has come to end this charade, $n.$b$bAs valuable as your information has been, we must bring Drakuru down and bring his project to an end before his freaks are unleashed.$b$bWe've modified your scepter for the job. When the time is right, you will be able to use it on Drakuru's Blightbloods and turn them against him. It's your only hope of defeating him.$b$bFight well.",logDesc="Stefan in Ebon Watch wants you to defeat Drakuru.$b$bIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.",choiceRewards={{id=39655,qty=1},{id=39653,qty=1},{id=39652,qty=1}}} end
if not DB[12714] then DB[12714]={id=12714,zoneId=-372,name="The Will Of The Lich King",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28444,ender="3",enderType="NPC",enderId=28907,rewardNextId=12715,poiX=2461,poiY=-5593,wowhead="https://www.wowhead.com/wotlk/quest=12714",image="assets/images/quests/placeholder.png",xpDiff=1,desc="It is the will of the Lich King that drives us onward, $N. None are more aware of this than death knights. Our very existence is intrinsically tied to his consciousness. Surely you have heard him speak to you - invading your thoughts...$B$BCan you hear him now? Perhaps it is too early for you.$B$B<Mograine closes his eyes and nods to an unseen host.>$B$BYes, my lord. It will be done.$B$B$N, you are to return to Death's Breach and report to Prince Valanar. The Lich King commands it!",logDesc="Return to Death's Breach and report to Prince Valanar."} end
if not DB[12715] then DB[12715]={id=12715,zoneId=-372,name="The Crypt of Remembrance",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28907,ender="3",enderType="NPC",enderId=28911,rewardNextId=12719,poiX=2317,poiY=-5739,wowhead="https://www.wowhead.com/wotlk/quest=12715",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The attacks upon the gates of the last Scarlet bastion have begun. Our ghouls are wearing the Crusade's front lines down while we labor to fortify our new forward base, the Crypt of Remembrance.$B$BVenture south to the crypt, which borders New Avalon, and report to my dear brother, Prince Keleseth.$B$BHe will be expecting you.$B$BPrepare yourself, $N, for you are about to witness the next stage of Scourge warfare: DOMINATION!$B$BRide now, death knight!",logDesc="Report to Prince Keleseth at the Crypt of Remembrance."} end
if not DB[12716] then DB[12716]={id=12716,zoneId=-372,name="The Plaguebringer's Request",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28919,ender="3",enderType="NPC",enderId=28919,rewardNextId=12717,poiX=1983,poiY=-5816,wowhead="https://www.wowhead.com/wotlk/quest=12716",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="Look at this pumpkin patch! Notice anything missing? Of course you don't, because you're a moron! Your brain was probably the first thing to die.$B$B<Noth sighs.>$B$BI have been commanded to put together a plague cauldron. You will help me.$B$BDirectly inside the gate of New Avalon is the inn. Enter the inn and steal an empty cauldron. Then go to the forge, also near the gate, and steal some iron chains. Bring those back to me along with 10 Crusader skulls. Do I need to tell you where to get those too?",logDesc="Noth the Plaguebringer has requested that you bring him 1 Empty Cauldron, 1 Iron Chain and 10 Crusader Skulls.",rewards={{id=38668,qty=1}}} end
if not DB[12717] then DB[12717]={id=12717,zoneId=-372,name="Noth's Special Brew",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28919,poiX=1983,poiY=-5816,wowhead="https://www.wowhead.com/wotlk/quest=12717",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The cauldron is ready to begin spewing its foul corruption across the land!$B$BNow, death knight, a brief lesson in plague cauldrons. The gas that the cauldron emits is deadly to the living, but empowers Scourge. As with all Scourge creations, it feeds off of death and grows stronger the longer it feeds.$B$BTake these Crusader skulls and drop them in the cauldron. You will be quite happy with the results.",logDesc="Place the Pile of Crusader Skulls inside the Plague Cauldron.",rewards={{id=39327,qty=5}}} end
if not DB[12718] then DB[12718]={id=12718,zoneId=-372,name="More Skulls For Brew",level=55,minLevel=55,wowhead="https://www.wowhead.com/wotlk/quest=12718",image="assets/images/quests/placeholder.png",rewards={{id=39327,qty=5}}} end
if not DB[12719] then DB[12719]={id=12719,zoneId=-372,name="Nowhere To Run And Nowhere To Hide",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28911,ender="3",enderType="NPC",enderId=28911,rewardNextId=12720,poiX=1879,poiY=-5765,wowhead="https://www.wowhead.com/wotlk/quest=12719",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="Nothing less than total annihilation will suffice, $N. To that end, a few hundred mindless ghouls assaulting the front gate of New Avalon will not do. We must infiltrate the inner sanctum and dispose of their officials. They must be shown that no one can escape the Scourge's grasp!$B$BMake your way to the New Avalon Town Hall, southwest of here, and assassinate the mayor. Search the building for the New Avalon registry and bring it to me.",logDesc="Prince Keleseth at the Crypt of Remembrance has ordered you to kill Mayor Quimby and recover the New Avalon Registry. "} end
if not DB[12720] then DB[12720]={id=12720,zoneId=-372,name="How To Win Friends And Influence Enemies",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28911,ender="3",enderType="NPC",enderId=28911,poiX=1879,poiY=-5765,wowhead="https://www.wowhead.com/wotlk/quest=12720",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="In my travels across this world I have made several interesting discoveries. For instance, did you know that with the proper amount of encouragement one can extract all the truths that a man dares hide? As luck would have it, I happen to have some encouragement on hand.$B$B<Keleseth pulls something out of an ornately jeweled box.>$B$BThese are my \"persuaders.\" Equip them and take to the field, death knight. Apply the pointy ends to the soldiers of New Avalon. Discover the truth about this \"Crimson Dawn.\"",logDesc="Prince Keleseth at the Crypt of Remembrance has ordered you to discover the truth about the \"Crimson Dawn.\"$B$BRemove Keleseth's Persuaders from the Ornately Jeweled Box and use them to \"persuade\" the Scarlet Crusade into talking.",rewards={{id=38672,qty=1}}} end
if not DB[12721] then DB[12721]={id=12721,zoneId=66,name="Rampage",level=77,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="Witch Doctor Khufu",enderType="NPC",enderId=28479,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=12721",image="assets/images/quests/placeholder.png",xpDiff=6,desc="$N, there is no time left. You must take the key and use it to unlock Akali.$B$BHe is being held in the courtyard in front of Gundrak, the capital of Zul'Drak. Akali's chains are secured by four anchor points. You must unlock each of them to set the rhino god free.$B$BGundrak is teeming with ice trolls. However, I believe that if you're careful, you should be able to slip in without too much danger.$B$BOnce you're done, please inform the witch doctor.",logDesc="Har'koa at Zim'Torga has asked you to free Akali and then to inform Witch Doctor Khufu at Zim'Torga.",choiceRewards={{id=39794,qty=1},{id=39862,qty=1},{id=39846,qty=1},{id=39847,qty=1}}} end
if not DB[12722] then DB[12722]={id=12722,zoneId=-372,name="Lambs To The Slaughter",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28910,ender="3",enderType="NPC",enderId=28910,poiX=1876,poiY=-5777,wowhead="https://www.wowhead.com/wotlk/quest=12722",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="Most humans would have fled the moment a Scourge necropolis took up residence in their air space. Not the Scarlet Crusade!$B$BI must confess - I rather enjoy our exchanges with the Crusade. Through the years, Scourge battles against them have resulted in several of the most tragic events in human history. Yet here we stand - AGAIN - locked in battle!$B$BWe shan't deny them the pleasures of eternal servitude to the Lich King! Enter New Avalon and fulfill their death wish. Leave no survivors.",logDesc="Baron Rivendare at the Crypt of Remembrance has commanded you to slay 10 Scarlet Crusade Soldiers and 15 Citizens of New Avalon.",rewards={{id=38670,qty=1}}} end
if not DB[12723] then DB[12723]={id=12723,zoneId=-372,name="Behind Scarlet Lines",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28911,ender="Orbaz Bloodbane",enderType="NPC",enderId=28914,rewardNextId=12724,poiX=1879,poiY=-5765,wowhead="https://www.wowhead.com/wotlk/quest=12723",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I have sent Orbaz, Thassarian and Koltira behind enemy lines to search for the courier. They have set up a base of operations at the Scarlet Tavern, located at the southern end of New Avalon. The tavern is tucked away behind the two orchards, adjacent to the Chapel of the Crimson Flame. You are to make your way to the tavern and report to Orbaz Bloodbane. He will update you on their situation.$B",logDesc="Report to Orbaz Bloodbane at the Scarlet Tavern in New Avalon."} end
if not DB[12724] then DB[12724]={id=12724,zoneId=-372,name="The Path Of The Righteous Crusader",level=55,minLevel=55,giver="Orbaz Bloodbane",giverType="NPC",giverId=28914,ender="Orbaz Bloodbane",enderType="NPC",enderId=28914,poiX=1404,poiY=-5827,wowhead="https://www.wowhead.com/wotlk/quest=12724",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="We haven't got a damned clue about when or where this courier is supposed to show up. None of these humans had an answer either.$B$B<Orbaz points to the Scarlet corpses strewn across the floor.>$B$BI did manage to beat something useful out of the last one. Inside Scarlet Hold they keep a schedule of all patrol routes. I want you to break into the hold and steal the schedule.$B$BThe hold is the largest building in New Avalon - northeast of here. ",logDesc="Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to steal the New Avalon Patrol Schedule from the Scarlet Hold.",rewards={{id=38667,qty=1}}} end
if not DB[12725] then DB[12725]={id=12725,zoneId=-372,name="Brothers In Death",level=55,minLevel=55,giver="Thassarian",giverType="NPC",giverId=28913,ender="Koltira Deathweaver",enderType="NPC",enderId=28912,rewardNextId=12727,poiX=1398,poiY=-5827,wowhead="https://www.wowhead.com/wotlk/quest=12725",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Breaking through the Scarlet lines was no easy task. We suffered many casualties during the assault and lost one of our best death knights, Koltira Deathweaver. I don't know whether he's dead or alive, but I'll be damned if we don't search for him.$B$BI last saw him being bound in irons and dragged away to the Scarlet Hold, northeast of here. Tear that keep asunder, death knight. Find Koltira!",logDesc="Search for Koltira Deathweaver in the Scarlet Hold."} end
if not DB[12726] then DB[12726]={id=12726,zoneId=3711,name="Song of Wind and Water",level=80,minLevel=77,giver="Oracle Soo-nee",giverType="NPC",giverId=29006,ender="Oracle Soo-nee",enderType="NPC",enderId=29006,poiX=5649,poiY=4606,wowhead="https://www.wowhead.com/wotlk/quest=12726",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Listen to storm, yes?  The Stormwright's Shelf echoes with ancient song.... the Song of Wind and Water.$B$BThe great tempest devours the sons of typhoons and storms.  Take this drum and play his song... play Haiphoon's song.$B$BHelp him feed on wind and water so tempest can continue. ",logDesc="Soo-nee wants you to use the Tempest Drums at the Stormwright's Shelf and help Haiphoon devour 3 Storm Revenants and 3 Aqueous Spirits."} end
if not DB[12727] then DB[12727]={id=12727,zoneId=-372,name="Bloody Breakout",level=55,minLevel=55,giver="Koltira Deathweaver",giverType="NPC",giverId=28912,ender="Thassarian",enderType="NPC",enderId=28913,rewardNextId=12738,poiX=1656,poiY=-6039,wowhead="https://www.wowhead.com/wotlk/quest=12727",image="assets/images/quests/placeholder.png",xpDiff=8,money=16500,desc="The alarms have been sounded. The High Inquisitor and his acolytes will be here soon. I'm too badly injured to be of much use, but I'll do what little I can to help.$B$BSlay the High Inquisitor and his cronies. Tear off his head and return with it to Thassarian. Vengeance will soothe his savage soul.$B$BOne more thing, $N. If you do manage to survive and make it back to Thassarian, tell him that they're executing prisoners at the chapel. Perhaps he'll send you there to play the hero once more.",logDesc="Slay High Inquisitor Valroth and take Valroth's Head to Thassarian at the Scarlet Tavern in New Avalon.",rewards={{id=38665,qty=1}}} end
if not DB[12728] then DB[12728]={id=12728,zoneId=3537,name="Monitoring the Rift: Winterfin Cavern",level=71,minLevel=69,giver="Librarian Garren",giverType="NPC",giverId=25291,ender="Librarian Garren",enderType="NPC",enderId=25291,poiX=3615,poiY=5978,wowhead="https://www.wowhead.com/wotlk/quest=12728",image="assets/images/quests/placeholder.png",xpDiff=6,money=94000,desc="I need to compile my notes and prepare a presentation for my colleagues in Dalaran.$b$bWhile I do, I must ask that you visit the Winterfin Cavern to the north. You must use the Arcanometer while standing in the mouth of the cavern.$b$bReturn to me at once when you have the data. My documentation will be incomplete without it.",logDesc="Librarian Garren at Amber Ledge wants you to use the Arcanometer at Winterfin Caverns.",choiceRewards={{id=37282,qty=1},{id=37320,qty=1},{id=37458,qty=1},{id=37471,qty=1}}} end
if not DB[12729] then DB[12729]={id=12729,zoneId=66,name="The Gods Have Spoken",level=77,minLevel=74,giver="Witch Doctor Khufu",giverType="NPC",giverId=28479,ender="3",enderType="NPC",enderId=28401,rewardNextId=12730,poiX=5736,poiY=-3571,wowhead="https://www.wowhead.com/wotlk/quest=12729",image="assets/images/quests/placeholder.png",xpDiff=6,desc="The gods have spoken and we must heed their wisdom.$B$BGather friends to your side, $N. Take them north to Zim'Rhuk to destroy guardians there until they yield the unblemished heart. Take them east to the Altar of Quetz'lun and disrupt the altar wardens until you recover their gusty essence.$B$BDeliver both to Har'koa and she will combine them into that which will compel late Akali's prophet to appear.",logDesc="Deliver the Unblemished Heart of the Guardian and the Gusty Essence of the Warden to Har'koa at Zim'Torga."} end
if not DB[12730] then DB[12730]={id=12730,zoneId=66,name="Convocation at Zol'Heb",level=78,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="3",enderType="NPC",enderId=28401,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=12730",image="assets/images/quests/placeholder.png",xpDiff=7,money=204000,desc="You and your friends must take this instrument of convocation - of summoning - to Zol'Heb just south of Gundrak.$B$BTherein you will find a circle of power. Use the convocation to force the prophet of Akali to appear.$B$BMy heart goes out to you, $N. We have been through much together, and you have done all that you can to not only save my life, but those of the other gods the Drakkari have destroyed.$B$BBut I fear this time we may not see each other again until the afterlife.",logDesc="Har'koa at Zim'Torga has asked you to slay the Prophet of Akali.",choiceRewards={{id=41890,qty=1},{id=41891,qty=1},{id=41905,qty=1},{id=41932,qty=1}}} end
if not DB[12732] then DB[12732]={id=12732,zoneId=3711,name="The Heartblood's Strength",level=80,minLevel=77,giver="Rejek",giverType="NPC",giverId=29043,ender="Rejek",enderType="NPC",enderId=29043,poiX=5270,poiY=4502,wowhead="https://www.wowhead.com/wotlk/quest=12732",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="One day, Rejek will be mighty warrior. Blood and skyfire will make Rejek strong. You see soon.$B$BRejek give you vial, you take to very top of Suntouched Pillar, far to west. Put waters there in vial.$B$BThen go to north edge of basin, to ledge north of Bonefields. You find and kill goretalon matriarch. Take heartblood.$B$BYou combine heartblood and water, bring to Rejek. Rejek drink, make strong.",logDesc="Bring a vial of Suntouched Heartblood to Rejek at Frenzyheart Hill."} end
if not DB[12733] then DB[12733]={id=12733,zoneId=-372,name="Death's Challenge",level=55,minLevel=55,giver="Olrun the Battlecaller",giverType="NPC",giverId=29047,ender="Olrun the Battlecaller",enderType="NPC",enderId=29047,poiX=2378,poiY=-5792,wowhead="https://www.wowhead.com/wotlk/quest=12733",image="assets/images/quests/placeholder.png",xpDiff=7,money=25000,desc="Born of the Lich King's victory over Illidan Stormrage in the heart of the frozen wastes, Death's Challenge is a rite of passage that all death knights must undergo.$B$BSeek out other death knights of Acherus and challenge them to a duel. They must accept and fight until a victor emerges!$B$BGo now, $N! Victory for the Scourge! Glory to the Lich King!$B",logDesc="Olrun the Battlecaller has ordered you to win 5 duels against other death knights.$B$BYou may choose to battle death knight initiates or players.",rewards={{id=40483,qty=1}}} end
if not DB[12734] then DB[12734]={id=12734,zoneId=3711,name="Rejek: First Blood",level=80,minLevel=77,giver="Rejek",giverType="NPC",giverId=29043,ender="Rejek",enderType="NPC",enderId=29043,poiX=5270,poiY=4502,wowhead="https://www.wowhead.com/wotlk/quest=12734",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Rejek just became youngest warrior in all of Frenzyheart tribe. Father gave Rejek a mighty sword to defeat Frenzyheart enemies, but old tradition say sword need to be blooded first. Older warrior usually do that. You do this honor for Rejek?$B$BTake blade, put in corpses of all Frenzyheart foes: wasps and hardknuckles to southwest, and the big-tongues. Maybe blood blade on Mistwhispers, far to northwest near Bittertide Lake.",logDesc="Blood Rejek's Blade on the corpses of a Sapphire Hive Wasp, a Hardknuckle Charger, and 3 members of the Mistwhisper Tribe. You may blood the sword on either Mistwhisper Oracles or Mistwhisper Warriors. Return to Rejek at Frenzyheart Hill when your task is complete."} end
if not DB[12735] then DB[12735]={id=12735,zoneId=3711,name="A Cleansing Song",level=80,minLevel=77,giver="Oracle Soo-nee",giverType="NPC",giverId=29006,ender="Oracle Soo-nee",enderType="NPC",enderId=29006,poiX=5649,poiY=4606,wowhead="https://www.wowhead.com/wotlk/quest=12735",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Earth in Sholazar is pure.  The pillars have protected the land for centuries.$B$BWater, not as pure, it comes from outside Sholazar.... from oceans, from lakes, from rivers.  Water sometimes bring bad spirits - need to be cleansed.$B$BYou take this chime and play at Bittertide Lake, Wintergrasp River and River's Heart.  It make bad spirit angry... and then you must kill it.",logDesc="Soo-nee, at the Rainspeaker Canopy, wants you to play the Cleansing Chime at Bittertide Lake, Wintergrasp River and River's Heart and slay the evil spirits that plague the waters there."} end
if not DB[12736] then DB[12736]={id=12736,zoneId=3711,name="Song of Reflection",level=80,minLevel=77,giver="Oracle Soo-nee",giverType="NPC",giverId=29006,ender="Oracle Soo-nee",enderType="NPC",enderId=29006,poiX=5649,poiY=4606,wowhead="https://www.wowhead.com/wotlk/quest=12736",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Of course you not as smart as gorloc!  You just simple $r.$B$BYou not without hope, though!  You show you can learn.  Maybe crystals make you smart like crystals make us smart!$B$BI teach you to play song to clear your mind.  You play song by crystals then crystals make your mind better... not as good as gorloc's but better than you have now.  Lifeblood Pillar is broken, but other pillars still good!",logDesc="Soo-nee at Rainspeaker Canopy wants you to use the Didgeridoo of Contemplation at the top of the Glimmering Pillar, the Suntouched Pillar, the Mosslight Pillar and the Skyreach Pillar."} end
if not DB[12737] then DB[12737]={id=12737,zoneId=3711,name="Song of Fecundity",level=80,minLevel=77,giver="Oracle Soo-nee",giverType="NPC",giverId=29006,ender="Oracle Soo-nee",enderType="NPC",enderId=29006,poiX=5649,poiY=4606,wowhead="https://www.wowhead.com/wotlk/quest=12737",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The storm is a destructive force.  Storm burns trees.  Storm floods houses.$B$BBut storm can also be life force if you know right song.  In Stormwright Shelf, above Maker's Perch, you can find small dirt mounds.  They very fertile -- they carry inside a strong seed.  All they wait for is the right song.$B$BYou take this horn and play song for them.",logDesc="Soo-nee at Rainspeaker Canopy wants you to go to the Stormwright's Shelf, northwest of the Maker's Perch, and play the Horn of Fecundity near 8 piles Soaked Fertile Dirt."} end
if not DB[12738] then DB[12738]={id=12738,zoneId=-372,name="A Cry For Vengeance!",level=55,minLevel=55,giver="Thassarian",giverType="NPC",giverId=28913,ender="Knight Commander Plaguefist",enderType="NPC",enderId=29053,poiX=1398,poiY=-5827,wowhead="https://www.wowhead.com/wotlk/quest=12738",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The cry for vengeance must be heard, $N. Commander Plaguefist and a company of death knights are on their way to raze the Chapel of the Crimson Flame. If there are any death knights imprisoned at the chapel, Plaguefist will get them out.$B$BYou can still catch up to them if you hurry. The chapel is due west of here. ",logDesc="Report to Knight Commander Plaguefist at the Chapel of the Crimson Flame."} end
if not DB[12739] then DB[12739]={id=12739,zoneId=-372,name="A Special Surprise",level=55,minLevel=55,giver="Knight Commander Plaguefist",giverType="NPC",giverId=29053,ender="Knight Commander Plaguefist",enderType="NPC",enderId=29053,rewardNextId=12751,poiX=1372,poiY=-5720,wowhead="https://www.wowhead.com/wotlk/quest=12739",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, $N. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty tauren in there that I think you'll take great pleasure in executing.",logDesc="Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Malar Bravehorn, an Argent Dawn prisoner inside the nearby prison house."} end
if not DB[12740] then DB[12740]={id=12740,zoneId=66,name="Parachutes for the Argent Crusade",level=76,minLevel=74,giver="Commander Falstaav",giverType="NPC",giverId=28059,ender="Commander Falstaav",enderType="NPC",enderId=28059,rewardNextId=12596,poiX=5440,poiY=-2569,wowhead="https://www.wowhead.com/wotlk/quest=12740",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Those sky terrors are destroying my men and women! Dying from falling is a horrible way to go.$B$B$C, you have to get these parachutes out to them! At least then they'll have a fighting chance to survive.",logDesc="Commander Falstaav at The Argent Stand has asked you to equip 10 Argent Crusaders or Argent Shieldmen out in the courtyard with parachutes.",choiceRewards={{id=39779,qty=1},{id=39840,qty=1},{id=39799,qty=1},{id=39801,qty=1},{id=39820,qty=1}}} end
if not DB[12741] then DB[12741]={id=12741,zoneId=3711,name="Strength of the Tempest",level=80,minLevel=77,giver="Rejek",giverType="NPC",giverId=29043,ender="Rejek",enderType="NPC",enderId=29043,poiX=5270,poiY=4502,wowhead="https://www.wowhead.com/wotlk/quest=12741",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Silly big-tongues think singing to the clouds give them power. Rejek show big-tongues how to get power by taking it!$B$BFar to northwest, there is large, flat area the big-tongues call 'Stormwright's Shelf.' Rejek is sure you can only get there by flying like bird.$B$BOn this shelf, Rejek has heard of mighty forces of wind and water. Kill them for their badness, then take it to the big-tongue 'Shrine of the Tempest' at shelf's western side. Rejek will await your return with ultimate power.",logDesc="Gather 3 Essences of the Monsoon and 3 Essences of the Storm and take them to the Shrine of the Tempest. Return to Rejek at Frenzyheart Hill with the True Power of the Tempest."} end
if not DB[12742] then DB[12742]={id=12742,zoneId=-372,name="A Special Surprise",level=55,minLevel=55,giver="Knight Commander Plaguefist",giverType="NPC",giverId=29053,ender="Knight Commander Plaguefist",enderType="NPC",enderId=29053,rewardNextId=12751,poiX=1372,poiY=-5720,wowhead="https://www.wowhead.com/wotlk/quest=12742",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, $N. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty human in there that I think you'll take great pleasure in executing.",logDesc="Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Ellen Stanbridge, an Argent Dawn prisoner inside the nearby prison house."} end
if not DB[12743] then DB[12743]={id=12743,zoneId=-372,name="A Special Surprise",level=55,minLevel=55,giver="Knight Commander Plaguefist",giverType="NPC",giverId=29053,ender="Knight Commander Plaguefist",enderType="NPC",enderId=29053,rewardNextId=12751,poiX=1372,poiY=-5720,wowhead="https://www.wowhead.com/wotlk/quest=12743",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, $N. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty night elf in there that I think you'll take great pleasure in executing.",logDesc="Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Yazmina Oakenthorn, an Argent Dawn prisoner inside the nearby prison house."} end
