if not DB[12748] then DB[12748]={id=12748,zoneId=-372,name="A Special Surprise",level=55,minLevel=55,giver="Knight Commander Plaguefist",giverType="NPC",giverId=29053,ender="Knight Commander Plaguefist",enderType="NPC",enderId=29053,rewardNextId=12751,poiX=1372,poiY=-5720,wowhead="https://www.wowhead.com/wotlk/quest=12748",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, $N. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty orc in there that I think you'll take great pleasure in executing.",logDesc="Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Kug Ironjaw, an Argent Dawn prisoner inside the nearby prison house."} end
if not DB[12749] then DB[12749]={id=12749,zoneId=-372,name="A Special Surprise",level=55,minLevel=55,giver="Knight Commander Plaguefist",giverType="NPC",giverId=29053,ender="Knight Commander Plaguefist",enderType="NPC",enderId=29053,rewardNextId=12751,poiX=1372,poiY=-5720,wowhead="https://www.wowhead.com/wotlk/quest=12749",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, $N. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty troll in there that I think you'll take great pleasure in executing.",logDesc="Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Iggy Darktusk, an Argent Dawn prisoner inside the nearby prison house."} end
if not DB[12750] then DB[12750]={id=12750,zoneId=-372,name="A Special Surprise",level=55,minLevel=55,giver="Knight Commander Plaguefist",giverType="NPC",giverId=29053,ender="Knight Commander Plaguefist",enderType="NPC",enderId=29053,rewardNextId=12751,poiX=1372,poiY=-5720,wowhead="https://www.wowhead.com/wotlk/quest=12750",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, $N. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty Forsaken in there that I think you'll take great pleasure in executing.",logDesc="Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Antoine Brack, an Argent Dawn prisoner inside the nearby prison house."} end
if not DB[12751] then DB[12751]={id=12751,zoneId=-372,name="A Sort Of Homecoming",level=55,minLevel=55,giver="Knight Commander Plaguefist",giverType="NPC",giverId=29053,ender="Thassarian",enderType="NPC",enderId=28913,poiX=1372,poiY=-5720,wowhead="https://www.wowhead.com/wotlk/quest=12751",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="Return to Thassarian at the Scarlet Tavern and let him know that Koltira's cry for vengeance has been answered. The Chapel of the Crimson Flame will be a pile of ashes in a matter of hours.$B$BYou're one cold-blooded monster, $N. I salute you, $g brother:sister;.",logDesc="Return to Thassarian at the Scarlet Tavern in New Avalon with news of your victory.",rewards={{id=38675,qty=1}}} end
if not DB[12752] then DB[12752]={id=12752,zoneId=-284,name="Desperate Research",level=-1,minLevel=65,ender="Grand Apothecary Putress",enderType="NPC",enderId=28318,rewardNextId=12787,wowhead="https://www.wowhead.com/wotlk/quest=12752",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="$n, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.$B$BTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.$B$BBe swift, $n.  Each moment passed is another innocent life lost.",logDesc="Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath."} end
if not DB[12753] then DB[12753]={id=12753,zoneId=-284,name="A Desperate Alliance",level=-1,minLevel=65,rewardNextId=12771,wowhead="https://www.wowhead.com/wotlk/quest=12753",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Good $n, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.$B$BIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.$B$BLight speed, $n.",logDesc="Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath."} end
if not DB[12754] then DB[12754]={id=12754,zoneId=-372,name="Ambush At The Overlook",level=55,minLevel=55,giver="Orbaz Bloodbane",giverType="NPC",giverId=28914,ender="Orbaz Bloodbane",enderType="NPC",enderId=28914,rewardNextId=12755,poiX=1404,poiY=-5827,wowhead="https://www.wowhead.com/wotlk/quest=12754",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="While you were out burning churches and murdering vermin, I've been busy formulating a plan.$B$BThe Scarlet courier is scheduled to pass by the Scarlet Overlook within the hour. The roads by the overlook are wide open and swarming with Crusaders. Use this makeshift cover to hide at the overlook and wait for the Scarlet Courier to pass. When he's close enough, strike with all your fury! Cut him down and take his belongings - including his clothes!$B$BThe overlook is 200 paces east of here.",logDesc="Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to kill the Scarlet Courier and retrieve the Scarlet Courier's Belongings and the Scarlet Courier's Message."} end
if not DB[12755] then DB[12755]={id=12755,zoneId=-372,name="A Meeting With Fate",level=55,minLevel=55,giver="Orbaz Bloodbane",giverType="NPC",giverId=28914,ender="3",enderType="NPC",enderId=29077,rewardNextId=12756,poiX=1404,poiY=-5827,wowhead="https://www.wowhead.com/wotlk/quest=12755",image="assets/images/quests/placeholder.png",xpDiff=7,desc="This message must reach Abbendis. We do not want to draw their suspicion. They must continue under the assumption that everything is going as they planned.$B$BYou will don the Scarlet courier's clothes and with the help of some dark magic, take on the form of the courier.$B$BAbbendis is at King's Harbor, southeast of the Scarlet Overlook. Drop off the message and get as much information out of her as you can. She will tell us what we need to know about the \"Crimson Dawn.\"",logDesc="Orbaz Bloodbane has commanded you to deliver the Scarlet Courier's Message to High General Abbendis at King's Harbor."} end
if not DB[12756] then DB[12756]={id=12756,zoneId=-372,name="The Scarlet Onslaught Emerges",level=55,minLevel=55,giver="3",giverType="NPC",giverId=29077,ender="Orbaz Bloodbane",enderType="NPC",enderId=28914,rewardNextId=12757,poiX=1320,poiY=-6124,wowhead="https://www.wowhead.com/wotlk/quest=12756",image="assets/images/quests/placeholder.png",xpDiff=7,money=8500,desc="Listen well, courier. The Scarlet lands are lost. New Avalon and Havenshire are overrun by Scourge. The specter of death looms overhead and threatens to overtake us at any moment.$B$BReturn to Galvar with this message:$B$B\"Turn your armies around and prepare your ships for travel to the frozen wastes. When next we meet it will be in Northrend.\"$B$BGive this to Galvar.$B$B<Abbendis hands you a journal.>$B$BIt will explain everything.$B$BThe Scarlet Crusade is no more. Long live the Scarlet Onslaught!",logDesc="Deliver The Path of Redemption to Orbaz Bloodbane at the Scarlet Tavern in New Avalon."} end
if not DB[12757] then DB[12757]={id=12757,zoneId=-372,name="Scarlet Armies Approach...",level=55,minLevel=55,giver="Orbaz Bloodbane",giverType="NPC",giverId=28914,ender="3",enderType="NPC",enderId=28444,poiX=1404,poiY=-5827,wowhead="https://www.wowhead.com/wotlk/quest=12757",image="assets/images/quests/placeholder.png",xpDiff=8,money=25000,desc="We must prepare for the encroaching armies, $N. You will take what you have discovered to Highlord Mograine at once! I will open a portal directly to Acherus. Step inside and it will transport you.$B$BGive Highlord Mograine Abbendis' journal as well. Perhaps he'll find it useful.$B",logDesc="Deliver The Path of Redemption to Highlord Darion Mograine at Acherus: The Ebon Hold. ",rewards={{id=38663,qty=1}}} end
if not DB[12758] then DB[12758]={id=12758,zoneId=3711,name="A Hero's Headgear",level=80,minLevel=77,giver="Rejek",giverType="NPC",giverId=29043,ender="Rejek",enderType="NPC",enderId=29043,poiX=5270,poiY=4502,wowhead="https://www.wowhead.com/wotlk/quest=12758",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Rejek hears tales of giant metal men on faraway Stormwright's Shelf. Far to northwest, outside basin's lip, you will find it.$B$BImagine Rejek using heads of giant metal men as helmet. Make Rejek unstoppable! Make Rejek mighty!$B$BYou get for Rejek, but metal head might not come off metal body easy. Maybe steal bombs from little green men and their friends at Swindlegrin's Dig near Suntouched Pillar? Use bombs to get head off metal body, then bring to Rejek.",logDesc="Get Venture Co. Explosives from any of the Venture Company units at Swindlegrin's Dig and use them to obtain a Stormwatcher's Head. Bring the Stomwatcher's Head to Rejek at Frenzyheart Hill."} end
if not DB[12759] then DB[12759]={id=12759,zoneId=3711,name="Tools of War",level=78,minLevel=76,giver="Vekgar",giverType="NPC",giverId=29146,ender="Shaman Jakjek",enderType="NPC",enderId=28106,poiX=5293,poiY=4510,wowhead="https://www.wowhead.com/wotlk/quest=12759",image="assets/images/quests/placeholder.png",xpDiff=6,money=136000,desc="Zepik tell me that you maybe the best gorloc hunter he met... other than Zepik. Still big battle to southwest - you go help.$B$BZepik keeps some of biggest, baddest traps in his stash at Kartak's Hold... told Vekgar to use them for battle, so you use them too. Go pick out any traps you want and kill lots of big-tongues.$B$BLots and lots!",logDesc="Retrieve some of Zepik's traps from his stash in Kartak's Hold.  Using the traps, slaughter 50 of the nearby Sparktouched Gorlocs, and then return to Shaman Jakjek in Kartak's Hold."} end
if not DB[12760] then DB[12760]={id=12760,zoneId=3711,name="Secret Strength of the Frenzyheart",level=78,minLevel=76,giver="Vekgar",giverType="NPC",giverId=29146,ender="Shaman Jakjek",enderType="NPC",enderId=28106,poiX=5293,poiY=4510,wowhead="https://www.wowhead.com/wotlk/quest=12760",image="assets/images/quests/placeholder.png",xpDiff=6,money=136000,desc="Battle still going at Kartak hold... I think it time for you to learn big secret of Frenzyheart.$B$BWe have berries we keep from other lands we came from... they not so special on their own, but mix them with drunk drinks and they make Frenzyheart super strong. You a Frenzyheart now... it time you get to be strong too.$B$BI give some drink, then you be super strong and you go smash all the spark big-tongues.",logDesc="Using the secret Frenzyheart drink, slaughter 30 of the Sparktouched Gorlocs around Kartak's Hold."} end
if not DB[12761] then DB[12761]={id=12761,zoneId=3711,name="Mastery of the Crystals",level=78,minLevel=76,giver="Oracle Soo-dow",giverType="NPC",giverId=29149,ender="Lightningcaller Soo-met",enderType="NPC",enderId=28107,poiX=5726,poiY=4570,wowhead="https://www.wowhead.com/wotlk/quest=12761",image="assets/images/quests/placeholder.png",xpDiff=6,money=136000,desc="Sparktouched are still being attacked by puppy-men... we think they maybe not stop if we not make them stop. We have secret weapon though... we sent it out to Soo-met so he can use to protect all Oracles.$B$BSecret weapon is from Great Ones themselves... extra shiny crystals found inside sacred Great One temples. Be very careful... no break them.$B$BCrystals are in chest near shrine at Sparktouched Haven, in far southwest. You go use crystals to help Soo-met beat the puppy-men.",logDesc="Retrieve the crystal defenses at Sparktouched Haven and use them to kill 50 of the nearby Frenzyheart wolvar. When these tasks are complete, return to Lightningcaller Soo-met in Sparktouched Haven."} end
if not DB[12762] then DB[12762]={id=12762,zoneId=3711,name="Power of the Great Ones",level=78,minLevel=76,giver="Oracle Soo-dow",giverType="NPC",giverId=29149,ender="Lightningcaller Soo-met",enderType="NPC",enderId=28107,poiX=5726,poiY=4570,wowhead="https://www.wowhead.com/wotlk/quest=12762",image="assets/images/quests/placeholder.png",xpDiff=6,money=136000,desc="We need to do something to stop puppy-men attacking Sparktouched Haven. Jaloot brought me very special crystal that he found in River's Heart... we seen only one like it before.$B$BThe crystal not have power now, but the opened up lifeblood pillar should have energy to recharge it if you just bring it close. Once the crystal is charged, go to Sparktouched Haven in far southwest and let the crystal's energy make you big and strong.$B$BThen it time to kick some puppy-men butt.",logDesc="Charge the Dormant Polished Crystal at the exposed Lifeblood Pillar. Travel to Sparktouched Haven and use the power the crystal bestows to slaughter 30 of the nearby Frenzyheart wolvar, and then speak to Lightningcaller Soo-met in Sparktouched Haven."} end
if not DB[12763] then DB[12763]={id=12763,zoneId=394,name="Shifting Priorities",level=75,minLevel=74,giver="Scout Vor'takh",giverType="NPC",giverId=26666,ender="Sergeant Riannah",enderType="NPC",enderId=29137,poiX=3848,poiY=-4532,wowhead="https://www.wowhead.com/wotlk/quest=12763",image="assets/images/quests/placeholder.png",xpDiff=1,money=6000,desc="As pressing as our needs are here, there's news from the lands to the north that cannot be ignored.$b$bI've just received a message from the Argent Crusade. It seems that scourge forces are gathering there and are threatening to overrun Zul'drak.$b$bNeedless to say, $n, if that were to happen our struggle here would be meaningless. You must go there and aid the Crusaders in beating back the Lich King's armies.$b$bSpeak to Makki when you are ready to travel.",logDesc="Scout Vor'takh wants you to travel to Zul'Drak and report to Sergeant Riannah at Light's Breach.$b$bMakki Wintergale in Camp Onequah will provide you transportation."} end
if not DB[12764] then DB[12764]={id=12764,zoneId=3711,name="The Secret to Kungaloosh (DEPRECATED)",level=76,minLevel=76,wowhead="https://www.wowhead.com/wotlk/quest=12764",image="assets/images/quests/placeholder.png"} end
if not DB[12765] then DB[12765]={id=12765,zoneId=3711,name="Kungaloosh (DEPRECATED)",level=76,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=12765",image="assets/images/quests/placeholder.png"} end
if not DB[12766] then DB[12766]={id=12766,zoneId=65,name="Speak with your Ambassador",level=72,minLevel=71,giver="Tariolstrasz",giverType="NPC",giverId=26443,ender="Lauriel Trueblade",enderType="NPC",enderId=27803,rewardNextId=12460,poiX=3549,poiY=379,wowhead="https://www.wowhead.com/wotlk/quest=12766",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<The dragon in elf form takes your letter of introduction, perusing it for a moment and then stashing it away within his sleeve.>$B$BEverything seems to be in order. However, if you don't mind, I would ask that you speak with your ambassador here at the temple.$B$BShe has something of great import for you that needs taking care of before we send you up to the queen.$B$B<He pats at the letter under his sleeve.>$B$BI'll keep this safe for you until your return.",logDesc="Speak with Lauriel Trueblade at Wyrmrest Temple."} end
if not DB[12767] then DB[12767]={id=12767,zoneId=65,name="Speak with your Ambassador",level=72,minLevel=71,giver="Tariolstrasz",giverType="NPC",giverId=26443,ender="Golluck Rockfist",enderType="NPC",enderId=27804,rewardNextId=12461,poiX=3549,poiY=379,wowhead="https://www.wowhead.com/wotlk/quest=12767",image="assets/images/quests/placeholder.png",xpDiff=1,desc="<The dragon in elf form takes your letter of introduction, perusing it for a moment and then stashing it away within his sleeve.>$B$BEverything seems to be in order. However, if you don't mind, I would ask that you speak with your ambassador here at the temple.$B$BHe has something of great import for you that needs taking care of before we send you up to the queen.$B$B<He pats at the letter under his sleeve.>$B$BI'll keep this safe for you until your return.",logDesc="Speak with Golluck Rockfist at Wyrmrest Temple."} end
if not DB[12768] then DB[12768]={id=12768,zoneId=65,name="The Steward of Wyrmrest Temple",level=75,minLevel=71,giver="Ceristrasz",giverType="NPC",giverId=27506,ender="Tariolstrasz",enderType="NPC",enderId=26443,rewardNextId=12123,poiX=3704,poiY=699,wowhead="https://www.wowhead.com/wotlk/quest=12768",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You've proved that you're to be trusted and more.$B$BYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, $N.",logDesc="Speak with Tariolstrasz at Wyrmrest Temple."} end
if not DB[12769] then DB[12769]={id=12769,zoneId=65,name="The Steward of Wyrmrest Temple",level=75,minLevel=71,giver="Vargastrasz",giverType="NPC",giverId=27763,ender="Tariolstrasz",enderType="NPC",enderId=26443,rewardNextId=12124,poiX=3672,poiY=1217,wowhead="https://www.wowhead.com/wotlk/quest=12769",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You've proved that you're to be trusted and more.$B$BYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, $N.",logDesc="Speak with Tariolstrasz at Wyrmrest Temple."} end
if not DB[12770] then DB[12770]={id=12770,zoneId=394,name="Reallocating Resources",level=75,minLevel=74,giver="Captain Gryan Stoutmantle",giverType="NPC",giverId=26212,ender="Sergeant Riannah",enderType="NPC",enderId=29137,poiX=4607,poiY=-4230,wowhead="https://www.wowhead.com/wotlk/quest=12770",image="assets/images/quests/placeholder.png",xpDiff=1,money=6000,desc="Listen up, $c!$b$bYour days here are numbered. As much as we need capable $cs in our ranks, there's trouble up north that makes our problems look like a mid-summer Stormwind parade.$b$bTurns out the Scourge are concentrating their efforts - making a big push to take over Zul'Drak. If that happens, we may as well pack it in.$b$bYou're free to finish any business here, but then it's off to Light's Breach with you. Speak to Samuel if you need transportation.$b$bDismissed.",logDesc="Gryan Stoutmantle wants you to report to Sergeant Riannah at Light's Breach in Zul'Drak.$b$bYou may speak to Samuel Clearbook for transportation to Light's Breach."} end
if not DB[12771] then DB[12771]={id=12771,zoneId=-284,name="Ironforge",level=-1,minLevel=65,giver="Bishop Lazaril",giverType="NPC",giverId=29087,ender="King Magni Bronzebeard",enderType="NPC",enderId=2784,wowhead="https://www.wowhead.com/wotlk/quest=12771",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.$B$BTake this, $n.  Guard it close, and secure its passage to Ironforge.  Magni Bronzebeard is eager to take the fight to Northrend, and this will bring him closer to his goal.",logDesc="Bishop Lazaril wants you to bring the Light-infused Artifact to King Magni Bronzebeard in Ironforge."} end
if not DB[12772] then DB[12772]={id=12772,zoneId=-284,name="A Desperate Alliance",level=-1,minLevel=65,rewardNextId=12773,wowhead="https://www.wowhead.com/wotlk/quest=12772",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Good $n, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.$B$BIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.$B$BLight speed, $n.",logDesc="Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath."} end
if not DB[12773] then DB[12773]={id=12773,zoneId=-284,name="Darnassus",level=-1,minLevel=65,giver="Bishop Lazaril",giverType="NPC",giverId=29087,ender="3",enderType="NPC",enderId=7999,wowhead="https://www.wowhead.com/wotlk/quest=12773",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.$B$BTake this, $n.  Guard it close, and secure its passage to Darnassus.  Deliver it to Tyrande Whisperwind -- her priests will find it a vital source of power in their fight against the unholy forces from the North.",logDesc="Bishop Lazaril wants you to bring the Light-infused Artifact to Tyrande Whisperwind in Darnassus."} end
if not DB[12774] then DB[12774]={id=12774,zoneId=-284,name="Stormwind",level=-1,minLevel=65,giver="Bishop Lazaril",giverType="NPC",giverId=29087,ender="3",enderType="NPC",enderId=29611,wowhead="https://www.wowhead.com/wotlk/quest=12774",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.$B$BTake this, $n.  Guard it close, and secure its passage to Stormwind.  The King of Stormwind has recently returned; I'm sure he will welcome this tool.",logDesc="Bishop Lazaril wants you to bring the Light-infused Artifact to King Varian Wrynn in Stormwind."} end
if not DB[12775] then DB[12775]={id=12775,zoneId=-284,name="A Desperate Alliance",level=-1,minLevel=65,rewardNextId=12774,wowhead="https://www.wowhead.com/wotlk/quest=12775",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Good $n, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.$B$BIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.$B$BLight speed, $n.",logDesc="Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath."} end
if not DB[12776] then DB[12776]={id=12776,zoneId=-284,name="The Exodar",level=-1,minLevel=65,giver="Bishop Lazaril",giverType="NPC",giverId=29087,ender="3",enderType="NPC",enderId=17468,wowhead="https://www.wowhead.com/wotlk/quest=12776",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.$B$BTake this, $n.  Guard it close, and secure its passage to the Exodar.  Deliver it to Prophet Velen in the Vault of Lights so that he may use its powers against the unholy forces from the North.",logDesc="Bishop Lazaril wants you to deliver the Light-infused Artifact to Velen in the Exodar."} end
if not DB[12777] then DB[12777]={id=12777,zoneId=-284,name="A Desperate Alliance",level=-1,minLevel=65,rewardNextId=12776,wowhead="https://www.wowhead.com/wotlk/quest=12777",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Good $n, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.$B$BIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.$B$BLight speed, $n.",logDesc="Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath."} end
if not DB[12778] then DB[12778]={id=12778,zoneId=-372,name="The Scarlet Apocalypse",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28444,ender="3",enderType="NPC",enderId=29110,rewardNextId=12779,poiX=2461,poiY=-5593,wowhead="https://www.wowhead.com/wotlk/quest=12778",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The trap has been sprung, death knight. The armies of Hearthglen and Tirisfal have arrived, just in time to see their enclave in flames! If they turn back now, they fight us with their backs turned.$B$B<Mograine shakes his head.>$B$BNo, they have only one option, which has only one outcome: APOCALYPSE!$B$BAs we speak, they prepare to make one final stand.$B$BThe Lich King awaits your return, champion. He stands watch below us, at Death's Breach.",logDesc="Seek out the Lich King at Death's Breach."} end
if not DB[12779] then DB[12779]={id=12779,zoneId=-372,name="An End To All Things...",level=55,minLevel=55,giver="3",giverType="NPC",giverId=29110,ender="3",enderType="NPC",enderId=29110,rewardNextId=12800,poiX=2310,poiY=-5742,wowhead="https://www.wowhead.com/wotlk/quest=12779",image="assets/images/quests/placeholder.png",xpDiff=8,money=25000,desc="You have slaughtered legions beyond number and still your dark heart craves more. Your hunger knows no end, $N.$B$B<The Lich King pauses.>$B$BThere must come an end to all things, death knight. The Scarlet armies make their final stand against us. For them, there is no escape... no choice. And for this reason they will fight with a ferocity that you have yet to witness.$B$BUse this horn to call forth one of my wyrms. Climb upon its back and command it into battle. With it you will end the Scarlet Crusade.",logDesc="The Lich King has commanded you to eradicate the Scarlet Crusade.$B$BUse the Horn of the Frostbrood to call forth a Frostbrood Vanquisher and with it slay 150 Scarlet Soldiers and destroy 10 Scarlet Ballistas. Avoid incoming projectiles by moving out of their line of fire!",rewards={{id=38661,qty=1}}} end
if not DB[12780] then DB[12780]={id=12780,zoneId=66,name="DEPRICATED>>Enemy of Our Enemy",level=75,minLevel=74,wowhead="https://www.wowhead.com/wotlk/quest=12780",image="assets/images/quests/placeholder.png",xpDiff=1,money=6000,desc="As much as we find working with death knights distasteful, we cannot afford to be picky about our allies here.$b$bWe're pinched between the Scourge and the savage Drakkari, who want nothing more than to destroy us so that they can get at one another.$b$bTravel west to Ebon Watch. Speak with Stefan and see if you can be of service to him.",logDesc="Sergeant Riannah in Light's Breach wants you to speak with Stefan in Ebon Watch and offer your assistance."} end
if not DB[12781] then DB[12781]={id=12781,zoneId=4342,name="Welcome!",level=1,minLevel=1,ender="Siouxsie the Banshee",enderType="NPC",enderId=27928,wowhead="https://www.wowhead.com/wotlk/quest=12781",image="assets/images/quests/placeholder.png",desc="Welcome to the World of Warcraft!$B$BAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Siouxsie the Banshee in Ebon Hold.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.$B$BThanks again, and enjoy your stay in the World of Warcraft!$B",logDesc="Bring the Ebon Hold Gift Voucher to Siouxsie the Banshee in Ebon Hold.",choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}} end
if not DB[12782] then DB[12782]={id=12782,zoneId=-284,name="Desperate Research",level=-1,minLevel=65,ender="Grand Apothecary Putress",enderType="NPC",enderId=28318,rewardNextId=12788,wowhead="https://www.wowhead.com/wotlk/quest=12782",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="$n, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.$B$BTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.$B$BBe swift, $n.  Each moment passed is another innocent life lost.",logDesc="Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath."} end
if not DB[12783] then DB[12783]={id=12783,zoneId=-284,name="Desperate Research",level=-1,minLevel=65,ender="Grand Apothecary Putress",enderType="NPC",enderId=28318,rewardNextId=12785,wowhead="https://www.wowhead.com/wotlk/quest=12783",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="$n, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.$B$BTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.$B$BBe swift, $n.  Each moment passed is another innocent life lost.",logDesc="Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath."} end
if not DB[12784] then DB[12784]={id=12784,zoneId=-284,name="Desperate Research",level=-1,minLevel=65,ender="Grand Apothecary Putress",enderType="NPC",enderId=28318,rewardNextId=12786,wowhead="https://www.wowhead.com/wotlk/quest=12784",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="$n, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.$B$BTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.$B$BBe swift, $n.  Each moment passed is another innocent life lost.",logDesc="Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath."} end
if not DB[12785] then DB[12785]={id=12785,zoneId=-284,name="Orgrimmar",level=-1,minLevel=65,giver="Grand Apothecary Putress",giverType="NPC",giverId=28318,ender="Apothecary Karlov",enderType="NPC",enderId=29346,wowhead="https://www.wowhead.com/wotlk/quest=12785",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="We have a breakthrough!  Our zombie specimens have given us new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...$B$BTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.$B$BBring the box to my assistant, Apothecary Karlov.  He attends Warchief Thrall in Orgrimmar.",logDesc="Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Karlov in Orgrimmar."} end
if not DB[12786] then DB[12786]={id=12786,zoneId=-284,name="Thunder Bluff",level=-1,minLevel=65,giver="Grand Apothecary Putress",giverType="NPC",giverId=28318,ender="Apothecary Chaney",enderType="NPC",enderId=29348,wowhead="https://www.wowhead.com/wotlk/quest=12786",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...$B$BTake this box to Thunder Bluff.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.$B$BBring the box to my assistant, Apothecary Chaney.  He attends Magatha Grimtotem in Thunder Bluff.",logDesc="Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Chaney in Thunder Bluff."} end
if not DB[12787] then DB[12787]={id=12787,zoneId=-284,name="The Undercity",level=-1,minLevel=65,giver="Grand Apothecary Putress",giverType="NPC",giverId=28318,ender="Master Apothecary Faranell",enderType="NPC",enderId=2055,wowhead="https://www.wowhead.com/wotlk/quest=12787",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="The zombie plague was a blessing in disguise.  In our search for a cure, we have learned so much of the Scourge and their contagion.  Our research has given us weapons against them.  Weapons, and tools...$B$BTake this -- it is a zombie's head and has been partially cured of its plague by injecting it with a compound derived from our recent discoveries.  Deliver the head to Master Apothecary Faranell; I have a list of experiments I would like him to perform on it.",logDesc="Grand Apothecary Putress wants you to give the Dual-plagued Brain to Master Apothecary Faranell in the Undercity."} end
if not DB[12788] then DB[12788]={id=12788,zoneId=-284,name="Silvermoon",level=-1,minLevel=65,giver="Grand Apothecary Putress",giverType="NPC",giverId=28318,ender="Apothecary Tepesh",enderType="NPC",enderId=29339,wowhead="https://www.wowhead.com/wotlk/quest=12788",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...$B$BTake this box to Silvermoon City.  Inside is a head that is infected with the zombie plague, and something else... an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.$B$BBring the box to my assistant, Apothecary Tepesh.  She attends Lor'themar Theron in Silvermoon City.",logDesc="Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Tepesh in Silvermoon City."} end
if not DB[12789] then DB[12789]={id=12789,zoneId=66,name="Into the Breach!",level=75,minLevel=74,giver="Crusader Valus",giverType="NPC",giverId=28228,ender="Sergeant Riannah",enderType="NPC",enderId=29137,poiX=4599,poiY=-1083,wowhead="https://www.wowhead.com/wotlk/quest=12789",image="assets/images/quests/placeholder.png",xpDiff=1,money=6000,desc="Ready yourself, $c. I'm dispatching you to Light's Breach, northeast of here.$b$bI've received word that the Scourge are making a push to take over Zul'Drak.$b$b<Valus stares you dead in the eyes.>$b$bThis will not come to pass.$b$bSee to it that you assist in the destruction of the Scourge there. The light demands it.$b$bDismissed.",logDesc="Crusader Valus at Light's Trust wants you to report to Sergeant Riannah at Light's Breach in Zul'Drak."} end
if not DB[12790] then DB[12790]={id=12790,zoneId=4395,name="Learning to Leave and Return: the Magical Way",level=74,minLevel=68,giver="Archmage Celindra",giverType="NPC",giverId=29156,ender="Archmage Celindra",enderType="NPC",enderId=29156,poiX=5808,poiY=585,wowhead="https://www.wowhead.com/wotlk/quest=12790",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Just in case you don't already know, you can use the crystal on the platform behind me to teleport to the Violet Stand in Crystalsong Forest beneath Dalaran.$B$BCorrespondingly, you can use the crystal at the stand below to return to the chamber above me.$B$BI would like for you to do this now.",logDesc="Archmage Celindra at The Violet Gate in Dalaran wants you to use the Teleport to Violet Stand Crystal and the Teleport to Dalaran Crystal."} end
if not DB[12791] then DB[12791]={id=12791,zoneId=4395,name="The Magical Kingdom of Dalaran",level=74,minLevel=74,giver="Image of Archmage Aethas Sunreaver",giverType="NPC",giverId=26471,ender="Archmage Celindra",enderType="NPC",enderId=29156,rewardNextId=12790,poiX=3847,poiY=1493,wowhead="https://www.wowhead.com/wotlk/quest=12791",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, $N. You may or may not be aware that we Kirin Tor moved our city here to Northrend.$B$BNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.$B$BWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.$B$BWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.",logDesc="Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran."} end
if not DB[12792] then DB[12792]={id=12792,zoneId=66,name="First Things First",level=75,minLevel=74,giver="Commander Kunz",giverType="NPC",giverId=28039,ender="Sergeant Riannah",enderType="NPC",enderId=29137,poiX=5451,poiY=-2611,wowhead="https://www.wowhead.com/wotlk/quest=12792",image="assets/images/quests/placeholder.png",xpDiff=1,money=6000,desc="Listen up, $r!$b$bThis entire region is full of crises. Everywhere you look you'll find those who could use your assistance.$b$b<Kunz looks you squarely in the eye.>$b$bNo one needs your help right now more than Riannah. The scourge have forced their way between us, leaving her and those she commands isolated.$b$bLight's Breach, where her forces are holding out, lies just southwest of here.",logDesc="Commander Kunz at Argent Stand wants you to report to Sergeant Riannah at Light's Breach."} end
if not DB[12793] then DB[12793]={id=12793,zoneId=66,name="Smoke on the Horizon",level=75,minLevel=74,giver="Witch Doctor Khufu",giverType="NPC",giverId=28479,ender="Sergeant Riannah",enderType="NPC",enderId=29137,poiX=5736,poiY=-3571,wowhead="https://www.wowhead.com/wotlk/quest=12793",image="assets/images/quests/placeholder.png",xpDiff=1,money=6000,desc="You hear that, $r?$b$bThe clamor of battle far to the west reaches us here, even over the din of our own struggle.$b$bThe Scourge are threatening to break through the lines of those calling themselves the Argent Crusade. Preventing this is as urgent as anything in the region.$b$bTravel to Light's Breach and join in their struggle. Speak to Maaka and he will provide you safe passage.",logDesc="Khufu in Zim'Torga wants you to travel to Light's Breach and report to Sergeant Riannah there.$b$bMaaka will provide you with transportation there."} end
if not DB[12794] then DB[12794]={id=12794,zoneId=4395,name="The Magical Kingdom of Dalaran",level=74,minLevel=74,giver="Baron Ulrik von Stromhearth",giverType="NPC",giverId=23729,ender="Archmage Celindra",enderType="NPC",enderId=29156,rewardNextId=12790,poiX=587,poiY=-4951,wowhead="https://www.wowhead.com/wotlk/quest=12794",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, $N. You may or may not be aware that we Kirin Tor moved our city here to Northrend.$B$BNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.$B$BWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.$B$BWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.",logDesc="Deliver the Kirin Tor Signet to Archmage Celindra at the Violet Gate in Dalaran."} end
if not DB[12795] then DB[12795]={id=12795,zoneId=66,name="Taking a Stand",level=75,minLevel=74,giver="Bloodrose Datura",giverType="NPC",giverId=28532,ender="Commander Falstaav",enderType="NPC",enderId=28059,rewardNextId=12503,poiX=5204,poiY=-1313,wowhead="https://www.wowhead.com/wotlk/quest=12795",image="assets/images/quests/placeholder.png",xpDiff=1,money=6000,desc="A few moments ago I spotted a signal flare over the treeline to the east.$b$bThat can only mean that things are not going smoothly for the Crusaders at Argent Stand.$b$bI cannot leave our post here, $r, but you can. When time permits, make your way up to Commander Falstaav and see if there's anything you can do to lighten their burden.",logDesc="Bloodrose Datura at Ebon Watch wants you to speak with Commander Falstaav at The Argent Stand."} end
if not DB[12796] then DB[12796]={id=12796,zoneId=4395,name="The Magical Kingdom of Dalaran",level=74,minLevel=74,giver="Magister Teronus III",giverType="NPC",giverId=29169,ender="Archmage Celindra",enderType="NPC",enderId=29156,rewardNextId=12790,poiX=5442,poiY=-2629,wowhead="https://www.wowhead.com/wotlk/quest=12796",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Hello, $N. You may or may not be aware that we Kirin Tor moved our city here to Northrend.$B$BNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.$B$BWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.$B$BWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.",logDesc="Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran."} end
if not DB[12797] then DB[12797]={id=12797,zoneId=3711,name="Back Through the Waygate",level=78,minLevel=77,giver="The Etymidian",giverType="NPC",giverId=28092,ender="3",enderType="NPC",enderId=27801,rewardNextId=12546,poiX=-6194,poiY=-1220,wowhead="https://www.wowhead.com/wotlk/quest=12797",image="assets/images/quests/placeholder.png",xpDiff=4,money=53000,desc="You speak the truth, $r.  I can sense the very essence of Sholazar Basin begin to fray by the blight of undeath even as we speak.$B$BI've bound my being into the rune, $r.  Deliver it to she who sent you here -- for only her power can grant me passage to her lands.",logDesc="Bring the Omega Rune to the Avatar of Freya at the Rainspeaker Rapids in Sholazar Basin."} end
if not DB[12798] then DB[12798]={id=12798,zoneId=0,name="Swords Deck",level=25,minLevel=20,ender="Darkmoon Fortune Teller",enderType="NPC",enderId=30481,wowhead="https://www.wowhead.com/wotlk/quest=12798",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Now that you have gathered all of the Swords cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.$b$bYou feel the card could be used to communicate with someone.",logDesc="Use the Swords Deck to summon a Darkmoon Fortune Teller and give the deck to them.",choiceRewards={{id=39897,qty=1},{id=39895,qty=1},{id=39894,qty=1}}} end
if not DB[12799] then DB[12799]={id=12799,zoneId=66,name="Siphoning the Spirits",level=75,minLevel=74,giver="Captain Arnath",giverType="NPC",giverId=28045,ender="Captain Arnath",enderType="NPC",enderId=28045,poiX=5930,poiY=-2379,wowhead="https://www.wowhead.com/wotlk/quest=12799",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="You should be happy he's coming, they said. You'll enjoy his company, they said....$b$bWell it's not as if I had a choice in the matter. Finklestein is the Crusade's best alchemist. I suppose I should be honored that he's chosen my post to set up shop. But ever since he's arrived, I've been relegated to collecting various alchemical ingredients.$b$bSay, $r, how about you give me a hand? Just south of here are some pools that are haunted by spirits of ancient trolls. Collect their ectoplasm for me.",logDesc="Captain Arnath at Heb'Valok wants you to collect 5 Ancient Ectoplasms from the Lost Drakkari Spirits at the Pools of Zha'Jin."} end
if not DB[12800] then DB[12800]={id=12800,zoneId=-372,name="The Lich King's Command",level=55,minLevel=55,giver="3",giverType="NPC",giverId=29110,ender="Scourge Commander Thalanor",enderType="NPC",enderId=31082,poiX=2310,poiY=-5742,wowhead="https://www.wowhead.com/wotlk/quest=12800",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Scarlet Enclave is no more. What remains of the Crusade will be dealt with in Northrend.$B$BWe now turn all of our efforts to Light's Hope Chapel. No longer will this affront to your master be allowed to exist!$B$BI have issued my final command. Scourge Commander Thalanor awaits your arrival at the edge of Browman Mill. Go northwest, through the cave, into the Noxious Glade and take the path leading out of the glade to the mill.$B$BDo not fail me, $N.",logDesc="Report to Scourge Commander Thalanor at Browman Mill."} end
if not DB[12801] then DB[12801]={id=12801,zoneId=-372,name="The Light of Dawn",level=55,minLevel=55,giver="Scourge Commander Thalanor",giverType="NPC",giverId=31082,ender="3",enderType="NPC",enderId=29173,rewardNextId=13165,poiX=2448,poiY=-5125,wowhead="https://www.wowhead.com/wotlk/quest=12801",image="assets/images/quests/placeholder.png",xpDiff=8,money=33300,desc="The Argent Dawn stands defiantly against us at Light's Hope Chapel. They dare oppose the Scourge and for that reason alone they must be destroyed!$B$BThe mighty armies of the Lich King stand at the ready as the final battle for the Plaguelands approaches. Today we ascend into the immortal realm of Scourge heroes!$B$BWhen you are ready for battle, report to Highlord Darion Mograine. It is the highlord who will issue the final march orders and command our armies at Light's Hope Chapel.",logDesc="Defeat the forces of the Argent Dawn and uncover the Light of Dawn.$B$BReport to Highlord Darion Mograine should you survive.",choiceRewards={{id=38633,qty=1},{id=38632,qty=1}}} end
if not DB[12802] then DB[12802]={id=12802,zoneId=394,name="My Heart is in Your Hands",level=74,minLevel=73,ender="Image of Drakuru",enderType="NPC",enderId=26701,rewardNextId=12068,wowhead="https://www.wowhead.com/wotlk/quest=12802",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Drakuru's voice fills your mind.>$b$bHey, mon! Dis eye of da prophets be great! I been usin' it to watch ya and I see ya got da heart now! Not bad....$b$bNow ya just gotta bring it to my brazier at Drak'atal Passage, a short walk east of ya.$b$bYa must drink my elixir at da pedestal to summon me there. This time, ya need ta mix in some desperate mojo from the defenders there for it ta be workin'.",logDesc="Drakuru wants you to bring the Heart of the Ancients to him at Drak'atal Passage.$b$bYou will need to collect 5 Desperate Mojo to use the elixir there."} end
if not DB[12803] then DB[12803]={id=12803,zoneId=3711,name="Force of Nature",level=78,minLevel=77,giver="Pilot Vic",giverType="NPC",giverId=28746,ender="3",enderType="NPC",enderId=27801,rewardNextId=12561,poiX=5501,poiY=4753,wowhead="https://www.wowhead.com/wotlk/quest=12803",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I'm not sure about what I saw while flying to the northeast, but to me it looked like a gigantic woman kicking some Scourge butt.$B$BI'd heard the professor talk about a certain \"lifewarden\"  appointed by the titans to look over Sholazar.  I might not be a titan historian, but it sounds like she fits the bill.$B$BI also know that if the Scourge cross the border between the Lost Lands and the rest of Sholazar, our expedition's as good as dead.  What do you say you go look for her and lend a hand?",logDesc="Travel to the Blight Line, between Rainspeaker Rapids and the Lost Lands in Sholazar Basin and seek the Avatar of Freya."} end
if not DB[12804] then DB[12804]={id=12804,zoneId=3711,name="A Steak Fit for a Hunter",level=76,minLevel=76,giver="Korg the Cleaver",giverType="NPC",giverId=28046,ender="Korg the Cleaver",enderType="NPC",enderId=28046,poiX=5559,poiY=5765,wowhead="https://www.wowhead.com/wotlk/quest=12804",image="assets/images/quests/placeholder.png",xpDiff=5,money=62000,desc="Sometimes, there's nothing worse than a camp full of hunters. They're all so busy taking down prey animals that the only meat I get is tough and stringy. That's hardly the kind of thing you want to come home to after a long day on the hunt.$B$BLucky for us, though, there is a source of tender, succulent meat nearby. To the south of the river and the camp live longneck grazers. They're a perfect source of meat for our hungry hunters. Bring me back the best cuts of meat and we'll properly toast our comrades.",logDesc="Bring 5 Longneck Grazer Steaks to Korg the Cleaver at the Nesingwary Base Camp."} end
if not DB[12805] then DB[12805]={id=12805,zoneId=3711,name="Salvaging Life's Strength",level=77,minLevel=77,giver="3",giverType="NPC",giverId=27801,ender="3",enderType="NPC",enderId=27801,poiX=5876,poiY=4117,wowhead="https://www.wowhead.com/wotlk/quest=12805",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="The Lifeblood Pillar was toppled over with great force, sending the very earth into an upheaval.$B$BThe elementals that wander the sundered shard carry with them the very life essence that gave the pillar its strength.  I cannot allow this energy to be wasted, for only four pillars remain.$B$BHead to the sundered shard, to the southeast, and seek the lifeblood elementals.$B$BUse this gem on their remains to recover their rampant energy.  We'll need the energy to heal the land when all this is over.",logDesc="The Avatar of Freya wants you to go to the Sundered Shard to the southeast and use the Lifeforce Gem on 8 destroyed Lifeblood Elementals."} end
if not DB[12806] then DB[12806]={id=12806,zoneId=210,name="To the Rise with all Due Haste!",level=80,minLevel=77,giver="Baron Sliver",giverType="NPC",giverId=29343,ender="Lord-Commander Arete",enderType="NPC",enderId=29344,rewardNextId=12807,poiX=8385,poiY=2757,wowhead="https://www.wowhead.com/wotlk/quest=12806",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Some would say that our most critical mission lies not with the Lich King, but with the utter destruction of the Scarlet Onslaught. I would say that is foolish, but who am I to judge?$B$BDeath's Rise is far to the southwest, overlooking the sea along the cliff wall. There you will find Lord-Commander Arete personally overseeing the Onslaught's destruction himself.$B$B<The baron clears his throat.>$B$BDo see to it that you report to him with all due haste. He asked for you personally.",logDesc="Report to Lord-Commander Arete at Death's Rise in Icecrown."} end
if not DB[12807] then DB[12807]={id=12807,zoneId=210,name="The Story Thus Far...",level=80,minLevel=77,giver="Lord-Commander Arete",giverType="NPC",giverId=29344,ender="Lord-Commander Arete",enderType="NPC",enderId=29344,rewardNextId=12810,poiX=7414,poiY=4218,wowhead="https://www.wowhead.com/wotlk/quest=12807",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We have much to do, but first I believe a short refresher is in order.$B$BWe death knights have a colorful past with our Scarlet friends who idiotically rest comfortably in the harbor below us to the northwest.$B$BWhen you are ready for an earful, speak with me again and I shall provide enlightenment.",logDesc="Listen to Lord-Commander Arete's tale at Death's Rise."} end
if not DB[12808] then DB[12808]={id=12808,zoneId=-284,name="A Desperate Alliance",level=-1,minLevel=65,rewardNextId=12809,wowhead="https://www.wowhead.com/wotlk/quest=12808",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Good $n, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.$B$BIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.$B$BLight speed, $n.",logDesc="Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath."} end
if not DB[12809] then DB[12809]={id=12809,zoneId=-284,name="Ironforge",level=-1,minLevel=65,giver="Bishop Lazaril",giverType="NPC",giverId=29087,ender="High Tinker Mekkatorque",enderType="NPC",enderId=7937,wowhead="https://www.wowhead.com/wotlk/quest=12809",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.$B$BTake this, $n.  Guard it close, and secure its passage to Ironforge.  High Tinker Mekkatorque in Tinkertown will be eager to make use of the artifact's power.",logDesc="Bishop Lazaril wants you to bring the Light-infused Artifact to High Tinker Mekkatorque in Ironforge."} end
if not DB[12810] then DB[12810]={id=12810,zoneId=210,name="Blood in the Water",level=80,minLevel=77,giver="Lord-Commander Arete",giverType="NPC",giverId=29344,ender="Lord-Commander Arete",enderType="NPC",enderId=29344,rewardNextId=12814,poiX=7414,poiY=4218,wowhead="https://www.wowhead.com/wotlk/quest=12810",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The forces at Onslaught Harbor are heavily reinforced by gryphon riders. You need a mount that will enable you to put them down. But first, we need the components for the ritual that is going to make it all happen.$B$BA great deal of blood is necessary for the ritual to be undertaken.$B$B<The lord-commander points down and to the northwest.>$B$BThere is a readily available supply down there in the harbor... sharks. Do not return to me until you've filled this bladder with their blood.",logDesc="Lord-Commander Arete at Death's Rise wants you to fill the Gore Bladder with the blood of 10 Ravenous Jaws."} end
if not DB[12811] then DB[12811]={id=12811,zoneId=-284,name="Desperate Research",level=-1,minLevel=65,ender="Grand Apothecary Putress",enderType="NPC",enderId=28318,rewardNextId=12812,wowhead="https://www.wowhead.com/wotlk/quest=12811",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="$n, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.$B$BTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.$B$BBe swift, $n.  Each moment passed is another innocent life lost.",logDesc="Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath."} end
if not DB[12812] then DB[12812]={id=12812,zoneId=-284,name="Orgrimmar",level=-1,minLevel=65,giver="Grand Apothecary Putress",giverType="NPC",giverId=28318,ender="Apothecary Karlov",enderType="NPC",enderId=29346,wowhead="https://www.wowhead.com/wotlk/quest=12812",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...$B$BTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.$B$BBring the box to my assistant, Apothecary Karlov.  He attends Thrall in Orgrimmar.",logDesc="Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Karlov in Orgrimmar."} end
if not DB[12813] then DB[12813]={id=12813,zoneId=210,name="From Their Corpses, Rise!",level=80,minLevel=77,giver="Setaal Darkmender",giverType="NPC",giverId=29396,ender="Setaal Darkmender",enderType="NPC",enderId=29396,poiX=7404,poiY=4210,wowhead="https://www.wowhead.com/wotlk/quest=12813",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="How kind... how generous our lord-commander is. Where he is flowers and sunshine, I am filled only with hatred.$B$BIt is not enough to end their miserable lives... I want them humiliated... debased!$B$BWhat could be more unspeakable than to be turned into that which you hate? To dedicate your existence to eradicating a thing, and then in the end to become it?$B$BHow sad.$B$BTake this tincture northwest to Onslaught Harbor. Apply it to their still corpses and watch what happens, but avoid the cathedral.",logDesc="Setaal Darkmender at Death's Rise has given you the Darkmender's Tincture. Apply it to the corpses of 10 of any of the Scarlet Onslaught units found at Onslaught Harbor."} end
if not DB[12814] then DB[12814]={id=12814,zoneId=210,name="You'll Need a Gryphon",level=80,minLevel=77,giver="Lord-Commander Arete",giverType="NPC",giverId=29344,ender="Uzo Deathcaller",enderType="NPC",enderId=29405,poiX=7414,poiY=4218,wowhead="https://www.wowhead.com/wotlk/quest=12814",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="What could be more fitting than to take one of their own gryphons to use against them? Go to Onslaught Harbor and take the reins to one of their gryphons from the dead clutches of its rider.$B$BReturn with the gryphon, delivering it to Uzo Deathcaller. He will see to its proper transformation and provide you with further instructions.",logDesc="Deliver an Onslaught Gryphon to Uzo Deathcaller at Death's Rise.",choiceRewards={{id=43879,qty=1},{id=43894,qty=1},{id=43933,qty=1},{id=43846,qty=1}}} end
if not DB[12815] then DB[12815]={id=12815,zoneId=210,name="No Fly Zone",level=80,minLevel=77,giver="Uzo Deathcaller",giverType="NPC",giverId=29405,ender="Uzo Deathcaller",enderType="NPC",enderId=29405,poiX=7429,poiY=4212,wowhead="https://www.wowhead.com/wotlk/quest=12815",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Now that you got your bone gryphon, I wantcha to take it back down there everyday and make a no fly zone over Onslaught Harbor.$B$BI gotta admit, mon, I don't really care if you use the bone gryphon to kill them gryphon riders or not. But I'm guessin' that if you do, you'll find it much easier to get to 'em.$B$BBesides, it's got lots of neat tricks you can use.",logDesc="Uzo Deathcaller at Death's Rise wants you to kill 10 Onslaught Gryphon Riders."} end
if not DB[12816] then DB[12816]={id=12816,zoneId=-368,name="Investigate the Scourge of Silvermoon",level=10,minLevel=1,giver="Lieutenant Julek",giverType="NPC",giverId=29441,ender="Lieutenant Julek",enderType="NPC",enderId=29441,wowhead="https://www.wowhead.com/wotlk/quest=12816",image="assets/images/quests/placeholder.png",xpDiff=4,money=250,desc="The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Silvermoon from these accursed invaders? $b $bThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!",logDesc="Collect three Dim Necrotic Stones from the Scourge outside Silvermoon and investigate the glowing runic circles near their encampment."} end
if not DB[12817] then DB[12817]={id=12817,zoneId=-368,name="Investigate the Scourge of Exodar",level=10,minLevel=1,giver="Lieutenant Kregor",giverType="NPC",giverId=29442,ender="Lieutenant Kregor",enderType="NPC",enderId=29442,wowhead="https://www.wowhead.com/wotlk/quest=12817",image="assets/images/quests/placeholder.png",xpDiff=4,money=250,desc="The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Exodar from these accursed invaders? $b $bThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!",logDesc="Collect three Dim Necrotic Stones from the Scourge outside the Exodar and investigate the glowing runic circles near their encampment.  Then return to Lieutenant Kregor."} end
if not DB[12818] then DB[12818]={id=12818,zoneId=67,name="Clean Up",level=78,minLevel=77,giver="Jeer Sparksocket",giverType="NPC",giverId=29431,ender="Jeer Sparksocket",enderType="NPC",enderId=29431,rewardNextId=12819,poiX=6099,poiY=-1076,wowhead="https://www.wowhead.com/wotlk/quest=12818",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="To the point... Ricket's asked me to put together some stronger land mines, but I'm running low on parts.$B$BJust west of town, you'll find the remains of our last rocket sled... Ricket got a little excited when she was fueling it, but I probably should have thought to not put the nozzle right over the exhaust. Live and learn, eh?$B$BThere should be a good stock of spare parts scattered around the destroyed sled... why don't you go ahead and chase off those scavengers and nab me some of that wreckage?",logDesc="Jeer Sparksocket at K3 would like 10 pieces of Charred Wreckage."} end
if not DB[12819] then DB[12819]={id=12819,zoneId=67,name="Just Around the Corner",level=78,minLevel=77,giver="Jeer Sparksocket",giverType="NPC",giverId=29431,ender="Jeer Sparksocket",enderType="NPC",enderId=29431,rewardNextId=12826,poiX=6099,poiY=-1076,wowhead="https://www.wowhead.com/wotlk/quest=12819",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Blast it! Where are my tools? I had them here just a moment ago.$B$BOh! I probably forgot them when I was setting up that minefield in the west. That's mildly inconvenient. I'd be quite appreciative if you could go get them for me. You'll need to watch your step though... you should be able to use the same path that I did to get out.$B$BOh, and don't try to fly in... I had the presence of mind to set up turrets to shoot down anything that might fly, and they aren't very discerning in who they target.",logDesc="Jeer Sparksocket at K3 would like Sparksocket's Tools retrieved from his minefield."} end
if not DB[12820] then DB[12820]={id=12820,zoneId=67,name="A Delicate Touch",level=78,minLevel=77,giver="Ricket",giverType="NPC",giverId=29428,ender="Ricket",enderType="NPC",enderId=29428,poiX=6153,poiY=-1069,wowhead="https://www.wowhead.com/wotlk/quest=12820",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="I've been waiting an eternity for these mines! Well, a few days at least. What took him so long?$B$BHere's the low down, compadre... there's this nasty bunch of magnataur--you know, big, hairy, and extremely ugly--and they seem pretty keen on taking K3 for themselves.$B$BNot going to happen.$B$BWe've got some defenses set up in their path, northeast of here. Sadly, our laser turrets have pretty limited power supplies... that's where these mines come in! Get over there and blow them up good!",logDesc="Ricket at K3 wants you to use Improved Land Mines at Garm's Bane to fend off 12 attackers from Garm. Both Garm Invaders and Snowblind Followers will count towards this goal.",choiceRewards={{id=42787,qty=1},{id=42800,qty=1},{id=42829,qty=1},{id=42812,qty=1}}} end
if not DB[12821] then DB[12821]={id=12821,zoneId=67,name="Opening the Backdoor",level=78,minLevel=77,giver="Ricket",giverType="NPC",giverId=29428,ender="Ricket",enderType="NPC",enderId=29428,rewardNextId=12822,poiX=6153,poiY=-1069,wowhead="https://www.wowhead.com/wotlk/quest=12821",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="The sapper squad is ready. That means it's fun time, my dear!$B$BThere's only one thing holding us up from our full-scale assault on Garm! I sent a runner to set a teleporter up behind Garm--successfully I might add--and he returned to get the power cell it needs to function. It isn't working yet... which means the power cell didn't get there.$B$BI need you to look just on the other side of Garm's Bane for the power cell. When you find it, bring it farther east to Garm's Rise and activate the teleporter.",logDesc="Ricket at K3 would like you to locate the Transporter Power Cell and use it to activate the Transportation Pad at Garm's Rise."} end
if not DB[12822] then DB[12822]={id=12822,zoneId=67,name="Know No Fear",level=78,minLevel=77,giver="Ricket",giverType="NPC",giverId=29428,ender="Ricket",enderType="NPC",enderId=29428,poiX=6153,poiY=-1069,wowhead="https://www.wowhead.com/wotlk/quest=12822",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Now that we have the teleporter open, my plan is quite complex... it has several facets and will take impeccable coordination. And there are supplies to be gathered! And troops to recruit! Likely, weeks of hard labor as well!$B$BHahah, I had you going there for a moment, didn't I? You've got this, kid. Hop through the teleporter and take the fight to them! Our sappers will back you up... they won't have anywhere to run.",logDesc="Ricket at K3 wants you to kill 6 Garm Watchers and 8 Snowblind Devotees."} end
if not DB[12823] then DB[12823]={id=12823,zoneId=67,name="A Flawless Plan",level=78,minLevel=77,giver="Gino",giverType="NPC",giverId=29432,ender="Gino",enderType="NPC",enderId=29432,rewardNextId=12824,poiX=6321,poiY=-1726,wowhead="https://www.wowhead.com/wotlk/quest=12823",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Hey there! Joining us for the assault I assume?$B$BI've got a special task for you... we're going to bring the whole cave down on their heads! Towards the back of their cave, you should find Frostgut's Altar.  Sneak up and plant this hardpacked explosive bundle somewhere close to it.$B$BOnce the charge is placed, stick around just long enough to make sure Frostgut bites it, then get out quickly! There's no knowing how long the cave will last once that thing goes off!",logDesc="Gino at Garm's Rise wants you to plant the Hardpacked Explosive Bundle near Frostgut's Altar, kill Tormar Frostgut, and then escape the cave before it collapses on you."} end
if not DB[12824] then DB[12824]={id=12824,zoneId=67,name="Demolitionist Extraordinaire",level=78,minLevel=77,giver="Gino",giverType="NPC",giverId=29432,ender="Ricket",enderType="NPC",enderId=29428,poiX=6321,poiY=-1726,wowhead="https://www.wowhead.com/wotlk/quest=12824",image="assets/images/quests/placeholder.png",xpDiff=1,money=6800,desc="You've got some swift feet on you sonny! Thanks for lending a hand with those explosives... I've been waiting to give that invention a good test run for a while!$B$BGo ahead and tell Ricket we should be covered on the magnataur front now... my sappers will clean up any of the remaining baddies.$B$BThanks again!",logDesc="Return to Ricket at K3.",choiceRewards={{id=42790,qty=1},{id=42803,qty=1},{id=42815,qty=1},{id=42826,qty=1},{id=42823,qty=1}}} end
if not DB[12825] then DB[12825]={id=12825,zoneId=67,name="Expressions of Gratitude",level=78,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=12825",image="assets/images/quests/placeholder.png",logDesc="[PLACEHOLDER] Use mini-plane to kamakazi on the gnoll leader."} end
if not DB[12826] then DB[12826]={id=12826,zoneId=67,name="Slightly Unstable",level=78,minLevel=77,giver="Jeer Sparksocket",giverType="NPC",giverId=29431,ender="Ricket",enderType="NPC",enderId=29428,rewardNextId=12820,poiX=6099,poiY=-1076,wowhead="https://www.wowhead.com/wotlk/quest=12826",image="assets/images/quests/placeholder.png",xpDiff=1,money=6800,desc="Looking good!$B$BNo, not you - my new mines. You're just a little full of yourself, aren't you? I, on the other hand, am absolutely brilliant! My intellect cannot be matched.$B$BWhat were we talking about? Oh yes, my new mines! New and improved... ready for whatever devious use Ricket has concocted.$B$BBe a $G good lad:doll; and go hand them off to Ricket, will you? She's right over there... it should be quite the epic journey, I'm sure. Be careful though, she's a little loopy.",logDesc="Deliver Jeer's Improved Land Mines to Ricket in K3."} end
if not DB[12827] then DB[12827]={id=12827,zoneId=67,name="Reclaimed Rations",level=78,minLevel=77,giver="Ricket",giverType="NPC",giverId=29428,ender="Ricket",enderType="NPC",enderId=29428,poiX=6153,poiY=-1069,wowhead="https://www.wowhead.com/wotlk/quest=12827",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Hey hey! You're a new face! Care to lend Ricket a hand?$B$BWe have a somewhat unexpected problem - food shortage. I know, I know... we should have seen that coming, but you don't get it. We tend to have somewhat of a quick turn-around here with our sapper squad and all, so usually we don't have to worry about long term eats. Good old K3's gotten popular though.$B$BConvenient solution? There are gnoll camps to the west and some gnolls scattered, scavenging as gnolls do. Care to go nab some of their rations?",logDesc="Ricket at K3 wants you to repossess 16 Dried Gnoll Rations from the nearby Savage Hill Gnolls."} end
if not DB[12828] then DB[12828]={id=12828,zoneId=67,name="Ample Inspiration",level=78,minLevel=77,giver="Ricket",giverType="NPC",giverId=29428,ender="Ricket",enderType="NPC",enderId=29428,poiX=6153,poiY=-1069,wowhead="https://www.wowhead.com/wotlk/quest=12828",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Wow! That stuff is nasty. Not to account for gnoll taste or anything, but I figured whatever they had would at least be... edible?$B$BLet's get more creative.$B$BTore's got an explosive dispenser north of town... not far from the big cavern entrance, can't miss it. I'm sure she intends them for mining purposes of some sort, but I've got a better idea.$B$BGrab one of those things and rush it to one of the nearby mammoths... most of them are to the west. Collect the meat, bring it back.",logDesc="Ricket at K3 wants you to retrieve a U.D.E.D, use it to blow up a mammoth, and retrieve 8 Hearty Mammoth Meat.",choiceRewards={{id=42785,qty=1},{id=42798,qty=1},{id=42810,qty=1},{id=42825,qty=1},{id=42822,qty=1}}} end
if not DB[12829] then DB[12829]={id=12829,zoneId=67,name="Moving In",level=78,minLevel=77,giver="Tore Rumblewrench",giverType="NPC",giverId=29430,ender="Tore Rumblewrench",enderType="NPC",enderId=29430,poiX=6404,poiY=-1122,wowhead="https://www.wowhead.com/wotlk/quest=12829",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Hiya! The name's Tore. I  head up the mining operation here at K3... or I will shortly anyway!$B$BThis here cave is full of creepy-crawlies. I think we could do with a few less spiders before we move in - what'd you think?",logDesc="Tore Rumblewrench outside of Crystalweb Cavern wants you to kill 12 Crystalweb Spiders."} end
if not DB[12830] then DB[12830]={id=12830,zoneId=67,name="Ore Repossession",level=78,minLevel=77,giver="Tore Rumblewrench",giverType="NPC",giverId=29430,ender="Tore Rumblewrench",enderType="NPC",enderId=29430,poiX=6404,poiY=-1122,wowhead="https://www.wowhead.com/wotlk/quest=12830",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="We're moving in!$B$BThere were some snobolds here when we arrived... their mining operation seems to have met some unfortunate happenings though. Doesn't much matter - we were taking over soon anyway.$B$BI sent some of our miners in there to get me some ore samples that I can use to calibrate our machines for processing, but they haven't come back.$B$BMind going in there and nabbing some samples for me in their stead? The snobolds probably have some on them, though I'd expect most of them are dead by now.",logDesc="Tore Rumblewrench outside of Crystalweb Cavern would like you to retrieve 5 samples of Impure Saronite Ore."} end
if not DB[12831] then DB[12831]={id=12831,zoneId=67,name="Only Partly Forgotten",level=78,minLevel=77,giver="Injured Goblin Miner",giverType="NPC",giverId=29434,ender="Injured Goblin Miner",enderType="NPC",enderId=29434,rewardNextId=12832,poiX=6647,poiY=-1111,wowhead="https://www.wowhead.com/wotlk/quest=12831",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Oi... it's like there's a propeller in my stomach.$B$BI think I can walk, but I got something nasty in my system when I got bit by something in the back of the cave. It was bigger than the other spiders... and brightly colored.$B$BRicket can probably make me an antidote, but she'd need the venom sac from whatever bit me. Would you mind finding it for me? I don't think Tore's coming.$B$BI'll just pretend I'm dead here and hopefully they'll leave me alone.",logDesc="An Injured Goblin Miner in Crystalweb Cavern wants you to bring back an Icetip Venom Sac from an Icetip Crawler."} end
if not DB[12832] then DB[12832]={id=12832,zoneId=67,name="Bitter Departure",level=78,minLevel=77,giver="Injured Goblin Miner",giverType="NPC",giverId=29434,ender="Ricket",enderType="NPC",enderId=29428,poiX=6647,poiY=-1111,wowhead="https://www.wowhead.com/wotlk/quest=12832",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Oi - thank you! I thought for sure I'd just be a spider snack. Perhaps I'm speaking a bit soon though - let's get the heck out of here!$B$BLet me know as soon as you're ready to go... make it quick.",logDesc="Escort the Injured Goblin Miner out of Crystalweb Cavern and then speak to Ricket at K3.",choiceRewards={{id=42799,qty=1},{id=42828,qty=1},{id=42786,qty=1},{id=42811,qty=1}}} end
if not DB[12833] then DB[12833]={id=12833,zoneId=67,name="Overstock",level=78,minLevel=77,giver="Ricket",giverType="NPC",giverId=29428,ender="Ricket",enderType="NPC",enderId=29428,poiX=6153,poiY=-1069,wowhead="https://www.wowhead.com/wotlk/quest=12833",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Hey there again! You didn't run off like all the other adventurers did? Well, you're just a peach, aren't ya? I was beginning to think I smelled funny or something!$B$BWe could still use a bit of a hand around here, and you have just the right experience.  Remember those magnataur? Well apparently the cave didn't completely collapse... there are still quite a few left. So much for Gino taking care of them, eh?$B$BFortunately, Jeer made way more than enough mines. You've got this!",logDesc="Ricket at K3 wants you to use Improved Land Mines at Garm's Bane to fend off the attackers from Garm. Both Garm Invaders and Snowblind Followers will count towards this goal."} end
if not DB[12834] then DB[12834]={id=12834,zoneId=67,name="Not Rain, Nor Snow, Nor Exploding Plane",level=78,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=12834",image="assets/images/quests/placeholder.png",logDesc="[PLACEHOLDER] Test cold-weather bomber on giant."} end
if not DB[12835] then DB[12835]={id=12835,zoneId=67,name="All Grown Up",level=78,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=12835",image="assets/images/quests/placeholder.png",logDesc="[PLACEHOLDER] Test Grown Up Jormungar on Giant"} end
if not DB[12836] then DB[12836]={id=12836,zoneId=67,name="Expression of Gratitude",level=78,minLevel=77,giver="Ricket",giverType="NPC",giverId=29428,ender="Ricket",enderType="NPC",enderId=29428,poiX=6153,poiY=-1069,wowhead="https://www.wowhead.com/wotlk/quest=12836",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="I know just the job for an eager newcomer! We've got a gnoll problem. You might even call it a gnoll infestation! Pesky things. They keep creeping up more and more, and now they're on our doorstep, stealing our parts! Inconceivable.$B$BIt all begins and ends with their uppity leader, Gnarlhide. I want you to see to that \"ends\" part. Go pay him a visit at his camp all the way to the west, in Snowblind Hills.$B$BAnd when I say \"pay him a visit,\" that's a euphemism for \"kill him painfully.\" Kay? Kay!",logDesc="Ricket at K3 wants you to kill Gnarlhide."} end
if not DB[12837] then DB[12837]={id=12837,zoneId=67,name="Tore's Got the Goods",level=78,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=12837",image="assets/images/quests/placeholder.png",logDesc="[PLACEHOLDER] Report to Tore"} end
if not DB[12838] then DB[12838]={id=12838,zoneId=210,name="Intelligence Gathering",level=80,minLevel=77,giver="Aurochs Grimbane",giverType="NPC",giverId=29456,ender="Aurochs Grimbane",enderType="NPC",enderId=29456,poiX=7436,poiY=4200,wowhead="https://www.wowhead.com/wotlk/quest=12838",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I need to know what the Scarlet Onslaught is planning today. You will be my instrument in this task.$B$BFly to Onslaught Harbor and rifle through their baggage trunks for documents. The trunks will be locked, so you'll have to take the keys from the Scarlet Onslaught members by whatever means.",logDesc="Aurochs Grimbane at Death's Rise wants you to collect 5 Onslaught Intel Documents."} end
if not DB[12839] then DB[12839]={id=12839,zoneId=210,name="The Grand (Admiral's) Plan",level=80,minLevel=77,ender="Lord-Commander Arete",enderType="NPC",enderId=29344,rewardNextId=12840,wowhead="https://www.wowhead.com/wotlk/quest=12839",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="At first this note looks like any of the other intel that you've been looking for. However, a quick perusal of its contents disabuses you of this notion.$B$BThe letter conveys that Grand Admiral Westwind is present somewhere on the island, but that he is keeping himself secluded for now. He speaks of a glorious day that is coming soon in which the Scarlet Onslaught will wash over first the Lich King and then the rest of world to finally bring order to Azeroth.$B$BThe lord-commander will want to see this!",logDesc="Deliver the Note from the Grand Admiral to Lord-Commander Arete at Death's Rise."} end
if not DB[12840] then DB[12840]={id=12840,zoneId=210,name="In Strict Confidence",level=80,minLevel=77,giver="Lord-Commander Arete",giverType="NPC",giverId=29344,ender="Lord-Commander Arete",enderType="NPC",enderId=29344,rewardNextId=12847,poiX=7414,poiY=4218,wowhead="https://www.wowhead.com/wotlk/quest=12840",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="If anyone knows where the admiral is, then surely it must be his captains on the ships in Onslaught Harbor.$B$B<The lord-commander rubs his hands together.>$B$BWelsington and Hartford are their names if memory serves. Go beat the information out of them and then end their miserable lives.$B$BI want to know where the grand admiral is hidden!",logDesc="Lord-Commander Arete at Death's Rise wants you to beat information out of Captains Welsington and Hartford.",choiceRewards={{id=43883,qty=1},{id=43920,qty=1},{id=43919,qty=1},{id=43890,qty=1},{id=43921,qty=1}}} end
if not DB[12841] then DB[12841]={id=12841,zoneId=67,name="The Crone's Bargain",level=79,minLevel=77,giver="Lok'lira the Crone",giverType="NPC",giverId=29481,ender="Lok'lira the Crone",enderType="NPC",enderId=29481,rewardNextId=12905,poiX=6931,poiY=-1203,wowhead="https://www.wowhead.com/wotlk/quest=12841",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Yes, it must be the green-skinned prisoner you're after...  We might be able to help each other.$B$BYou're not going to get the goblin out of here by force.  Not alive, anyway.$B$BAmong my people I am known as a Yrkvinn, a practitioner of illusions.  As you can see, the Hyldnir have made me their prisoner.$B$BIf I had my runes, I could make you go unnoticed among them.  Further inside, patrolling the mines, you'll find an overseer named Syra.  She has my runes.  Retrieve them and we'll talk some more.",logDesc="Lok'lira the Crone inside the Forlorn Mine wants you to retrieve the Runes of the Yrkvinn from Overseer Syra."} end
if not DB[12842] then DB[12842]={id=12842,zoneId=-372,name="Runeforging: Preparation For Battle",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28357,ender="3",enderType="NPC",enderId=28357,rewardNextId=12848,poiX=2498,poiY=-5593,wowhead="https://www.wowhead.com/wotlk/quest=12842",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The mark of war is etched indelibly upon your soul, death knight. You have learned the dark art of runeforging and with it you will engrave runes of power upon your weaponry.$B$BPreparations for battle must be made. Return to one of the runeforges, here in the Heart of Acherus, and use the power of runeforging to emblazon your weapon with a rune of power!$B$BReturn to me when your blade glows with dark energy!",logDesc="Instructor Razuvious in Ebon Hold has commanded you to use your Runeforging ability to engrave a rune [of your choosing] upon your Runed Soulblade.$B$BYou may freely replace the engraving upon your weapon at any time, so long as you are near a Runeforge."} end
if not DB[12843] then DB[12843]={id=12843,zoneId=67,name="They Took Our Men!",level=79,minLevel=77,giver="Gretchen Fizzlespark",giverType="NPC",giverId=29473,ender="Gretchen Fizzlespark",enderType="NPC",enderId=29473,rewardNextId=12846,poiX=6113,poiY=-1085,wowhead="https://www.wowhead.com/wotlk/quest=12843",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You have to help us!  We were in the middle of an expedition into the mountains to set up a transmission tower when we were attacked.$B$BThey looked like vrykul, except their skin was blue and layered with frost.... and they were all female!  They took all the men in the expedition and let us women go.  Please, $N!  We think they're being held in Sifreldar, the village overlooking K3.",logDesc="Gretchen Fizzlespark wants you to go to Sifreldar Village and rescue 5 Goblin Prisoners.",choiceRewards={{id=42842,qty=1},{id=42866,qty=1},{id=42888,qty=1},{id=42877,qty=1},{id=42864,qty=1}}} end
if not DB[12844] then DB[12844]={id=12844,zoneId=67,name="Equipment Recovery",level=79,minLevel=77,giver="Gretchen Fizzlespark",giverType="NPC",giverId=29473,ender="Gretchen Fizzlespark",enderType="NPC",enderId=29473,poiX=6113,poiY=-1085,wowhead="https://www.wowhead.com/wotlk/quest=12844",image="assets/images/quests/placeholder.png",xpDiff=5,money=71000,desc="Please, $N.  When the Hyldnir took our men, they also took all our equipment.  Of course, it's more important that we get our boys back, but if you run into any of our equipment, I'd really appreciate it if you brought it back to us.$B$BYou'll find their village just above us, to the north.",logDesc="Gretchen Fizzlespark wants you to obtain 8 pieces of K3 Equipment in Sifreldar Village north of K3."} end
if not DB[12845] then DB[12845]={id=12845,zoneId=0,name="Dalaran Teleport Crystal Flag",level=0,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=12845",image="assets/images/quests/placeholder.png"} end
if not DB[12846] then DB[12846]={id=12846,zoneId=67,name="Leave No Goblin Behind",level=78,minLevel=77,giver="Gretchen Fizzlespark",giverType="NPC",giverId=29473,ender="Lok'lira the Crone",enderType="NPC",enderId=29481,rewardNextId=12841,poiX=6113,poiY=-1085,wowhead="https://www.wowhead.com/wotlk/quest=12846",image="assets/images/quests/placeholder.png",xpDiff=3,desc="All of our boys are back... thanks to you, $N!  Well... all but one.$B$BMy brother Zeev is still up there according to the others.  Apparently they have some sort of mine where they make their prisoners work.  Go in there and see if you can find out anything.",logDesc="Find the entrance to the Forlorn Mine in northern Sifreldar Village and look for clues for Zeev Fizzlespark's whereabouts."} end
if not DB[12847] then DB[12847]={id=12847,zoneId=210,name="Second Chances",level=80,minLevel=77,giver="Lord-Commander Arete",giverType="NPC",giverId=29344,ender="Lord-Commander Arete",enderType="NPC",enderId=29560,rewardNextId=12852,poiX=7414,poiY=4218,wowhead="https://www.wowhead.com/wotlk/quest=12847",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="I'd heard they have an archbishop in their cathedral, but I had no idea that they'd resurrected and promoted Landgren! The Crimson Cathedral is heavily guarded with only one entrance, so you'll need help.$B$BWe still need to know where the grand admiral is, but this time we're not taking any chances!$B$BTake this device. It can be used to summon a gate for me to step through once you've killed the archbishop.$B$BI'll have my answers directly from his compelled soul! We will find Grand Admiral Westwind!",logDesc="Kill Archbishop Landgren and then summon Arete's Gate in the presence of his corpse. Speak with Lord-Commander Arete inside The Crimson Cathedral once he's completed his questioning of the archbishop's spirit."} end
if not DB[12848] then DB[12848]={id=12848,zoneId=-372,name="The Endless Hunger",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28357,ender="3",enderType="NPC",enderId=28357,rewardNextId=12636,poiX=2498,poiY=-5593,wowhead="https://www.wowhead.com/wotlk/quest=12848",image="assets/images/quests/placeholder.png",xpDiff=7,desc="The endless hunger will soon take hold of you, $c. When it does, you will feel pain immeasurable. There is only one remedy for the suffering: the hunger must be sated.$B$BI give you the key to your salvation.$B$BChained to the Heart of Acherus are those deemed unworthy of the dark brotherhood. Use the key to free an unworthy initiate. Allow them to equip their gear and battle you for their freedom. Kill and the pain will cease. Fail and suffer for eternity.$B$BLive or die - the choice is yours to make.",logDesc="Instructor Razuvious in Ebon Hold has commanded you to free an Unworthy Initiate and then kill the Unworthy Initiate in cold blood!$B$BIt's your life or theirs!"} end
if not DB[12849] then DB[12849]={id=12849,zoneId=-372,name="The Power Of Blood, Frost And Unholy",level=55,minLevel=55,giver="Lord Thorval",giverType="NPC",giverId=28472,ender="Lord Thorval",enderType="NPC",enderId=28472,poiX=2528,poiY=-5549,wowhead="https://www.wowhead.com/wotlk/quest=12849",image="assets/images/quests/placeholder.png",xpDiff=7} end
if not DB[12850] then DB[12850]={id=12850,zoneId=-372,name="Report To Scourge Commander Thalanor",level=55,minLevel=55,giver="3",giverType="NPC",giverId=28444,ender="Scourge Commander Thalanor",enderType="NPC",enderId=28510,rewardNextId=12670,poiX=2461,poiY=-5593,wowhead="https://www.wowhead.com/wotlk/quest=12850",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Scourge Commander Thalanor awaits your arrival at the overhang located directly southeast of our current position. Report to Thalanor and requisition a Scourge gryphon to deliver you to Death's Breach.$B$BPrince Valanar will be waiting for you down below.$B$BSuffer well, $g brother:sister;! ",logDesc="Report to Scourge Commander Thalanor at the balcony on the first floor of Ebon Hold."} end
if not DB[12851] then DB[12851]={id=12851,zoneId=67,name="Going Bearback",level=80,minLevel=77,giver="3",giverType="NPC",giverId=29592,ender="3",enderType="NPC",enderId=29592,rewardNextId=12856,poiX=7082,poiY=-1938,wowhead="https://www.wowhead.com/wotlk/quest=12851",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The test awaits, woman!$b$bDo you have the heart of a warrior queen? Or that of a sniveling seamstress?$b$bOne taste of war and you'll know the answer.$b$bYou might lie to your mother, your sisters, and even yourself, but the battlefield always exposes one's true nature.$b$bWhen you've made your preparations, mount Icefang and ride into battle. From her back, you must rain down a shower of death upon our enemy.",logDesc="Brijana at Brunnhildar Village wants you to mount Icefang and shoot 7 Frostworgs and 15 Frost Giants in the Valley of Ancient Winters."} end
if not DB[12852] then DB[12852]={id=12852,zoneId=210,name="The Admiral Revealed",level=80,minLevel=77,giver="Lord-Commander Arete",giverType="NPC",giverId=29560,ender="Lord-Commander Arete",enderType="NPC",enderId=29344,wowhead="https://www.wowhead.com/wotlk/quest=12852",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="When High General Abbendis was confronted at New Hearthglen, the grand admiral protected himself within an impenetrable sphere of magic before making his escape.$B$BI am particularly adept at nullifying magic.$B$BTake this to use against him inside The Hidden Hollow when he puts the sphere up. I wish that I could be there to see the look on his face when you do it.$B$BDeal with him.",logDesc="Lord-Commander Arete wants you to deal with Grand Admiral Westwind. Return to the lord-commander upon Death's Rise after you have done so.",choiceRewards={{id=44034,qty=1},{id=44033,qty=1},{id=44017,qty=1},{id=44035,qty=1}}} end
if not DB[12853] then DB[12853]={id=12853,zoneId=67,name="Luxurious Getaway!",level=78,minLevel=77,giver="Rin Duoctane",giverType="NPC",giverId=30490,ender="Jeer Sparksocket",enderType="NPC",enderId=29431,poiX=5789,poiY=740,wowhead="https://www.wowhead.com/wotlk/quest=12853",image="assets/images/quests/placeholder.png",xpDiff=1,money=6800,desc="Hey there, pal!$B$BDo you like excitement and explosions?! Who doesn't? I know just the place for you. Down at luxurious K3, they're always making innovative inventions and finding all-new ways to make things blow up! Sounds thrilling, doesn't it? If you want to be part of the fun, head on down today and speak to Jeer Sparksocket!$B$BMandatory disclaimer: manual labor may be required to partake in previously indicated \"excitement.\"",logDesc="Speak to Jeer Sparksocket at K3 in the Storm Peaks."} end
if not DB[12854] then DB[12854]={id=12854,zoneId=67,name="On Brann's Trail",level=80,minLevel=77,giver="Archaeologist Andorin",giverType="NPC",giverId=29650,ender="Archaeologist Andorin",enderType="NPC",enderId=29650,poiX=6685,poiY=-260,wowhead="https://www.wowhead.com/wotlk/quest=12854",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="After the discovery of Brann's journal in Grizzly Hills, we've only had one other communication from Brann. A mysterious note found its way to Explorers' League headquarters in Ironforge, with no indication of where it came from. All it said was that we're to meet Brann at his camp and help him with his search.$B$BFrom what I can tell, the camp should be located northeast of here, across the Bor's Breath River and at the foot of some ruins from the Path of the Titans.",logDesc="Retrieve the Burlap-Wrapped Note from Brann's camp and return it to Archaeologist Andorin at Frosthold."} end
if not DB[12855] then DB[12855]={id=12855,zoneId=67,name="Sniffing Out the Perpetrator",level=80,minLevel=77,giver="Archaeologist Andorin",giverType="NPC",giverId=29650,ender="Brann Bronzebeard",enderType="NPC",enderId=29579,rewardNextId=12858,poiX=6685,poiY=-260,wowhead="https://www.wowhead.com/wotlk/quest=12855",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The tone of Brann's note suggests he meant to bury something with the note, maybe a pack of some kind. You're sure this was all you found?$B$BOkay, I'm going to have you take one of these frosthounds with you. The frostborn use them for tracking. Bring it to the destroyed camp and let it get Brann's scent.$B$BIt should at least lead you to the location of those missing possessions, and if we're lucky, Brann himself. ",logDesc="Use the Frosthound Collar at the Abandoned Camp to track down whoever took Brann's possessions. When you recover them, use the communication device and speak to whoever you can contact."} end
if not DB[12856] then DB[12856]={id=12856,zoneId=67,name="Cold Hearted",level=80,minLevel=77,giver="3",giverType="NPC",giverId=29592,ender="3",enderType="NPC",enderId=29592,rewardNextId=13063,poiX=7082,poiY=-1938,wowhead="https://www.wowhead.com/wotlk/quest=12856",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="To be slain honorably on the field of battle brings us all glory. To be frozen in a block of ice and endlessly taunted does not....$b$bYou are to fly to the frost giant city of Dun Niffelem, just east of the Valley of Ancient Winters, and liberate a captive proto-drake. With her, you will be able to free our sisters from their frozen bonds and carry three of them safely home.$b$bBeware the giants' clubs, sister, lest you find yourself numbered among the captives.",logDesc="Brijana, just east of Brunnhildar Village, wants you to fly to Dun Niffelem, then free 3 Captured Proto-Drakes and rescue 9 Brunnhildar Prisoners."} end
if not DB[12857] then DB[12857]={id=12857,zoneId=66,name="Wanted: Ragemane's Flipper",level=75,minLevel=74,ender="Chief Rageclaw",enderType="NPC",enderId=29690,wowhead="https://www.wowhead.com/wotlk/quest=12857",image="assets/images/quests/placeholder.png",xpDiff=6,money=118000,desc="Posted by Chief Rageclaw:$B$BChief Rageclaw trusty lion seal, Ragemane, bite hand that feed him. Rageclaw say Ragemane no more good because of bad Drakuru trolls. Chief Rageclaw very sad to ask that Ragemane be killeded and Ragemane flipper be returned to chief as proof.$B$BYou find Ragemane to southeast, at Rageclaw Lake.$B$BChief Rageclaw sorry for bad writing. First time use one of these things; plus, Chief Rageclaw is wolvar, not person.$B",logDesc="Recover Ragemane's Flipper and return it to Chief Rageclaw at Light's Breach in Zul'Drak.",choiceRewards={{id=41987,qty=1},{id=44734,qty=1},{id=44735,qty=1},{id=44736,qty=1}}} end
if not DB[12858] then DB[12858]={id=12858,zoneId=67,name="Pieces to the Puzzle",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,ender="Brann Bronzebeard",enderType="NPC",enderId=29579,rewardNextId=12860,wowhead="https://www.wowhead.com/wotlk/quest=12858",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Thank the Light that someone got my message. Now that I'm safe from the iron dwarves, I need to ask your help with something. I've got a lead on Norgannon's keystone, which guards access to Ulduar's archives, but the Titans divided it into two pieces and secreted them away.$B$BOne of the pieces, the keystone's shell, is held within the Inventor's Library on the northern coast, south of Ulduar itself. The first thing you'll need to do is retrieve the fragments of an access disk from the library's guardians.",logDesc="Gather 6 Inventor's Disk Fragments and use them to assemble the Inventor's Disk."} end
if not DB[12859] then DB[12859]={id=12859,zoneId=66,name="This Just In: Fire Still Hot!",level=75,minLevel=74,giver="Elder Shaman Moky",giverType="NPC",giverId=29733,ender="Elder Shaman Moky",enderType="NPC",enderId=29733,poiX=5152,poiY=-2199,wowhead="https://www.wowhead.com/wotlk/quest=12859",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Trolls attack Rageclaw Den and kick Rageclaw out! It get worse. Trolls now burning village! This very bad. Chief make top Rageclaw shaman, Moky, do study on fire. Results very surprising! Fire still hot and can burn things.$B$BWill you help Rageclaw and put fire out? Moky has special Rageclaw fire extinguisher for you. Use special fire extinguisher to put out fire at Rageclaw Den to southeast. Sometimes take many sprays to douse fire, but extinguisher always have water! Rageclaw magic strong!",logDesc="Elder Shaman Moky at Light's Breach in Zul'Drak wants you to use the Rageclaw Fire Extinguisher to douse 15 hut fires at Rageclaw Den.$B",rewards={{id=41755,qty=1}}} end
if not DB[12860] then DB[12860]={id=12860,zoneId=67,name="Data Mining",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,ender="Brann Bronzebeard",enderType="NPC",enderId=29579,rewardNextId=13415,wowhead="https://www.wowhead.com/wotlk/quest=12860",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="That disk you assembled... it's blank! That crafty Mimir must've hidden the information somewhere else. Look around the Inventor's Library; do you see any databanks there?$B$BThat might be what you need to do with the disk. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.",logDesc="Use the Inventor's Disk to retrieve 7 pieces of Hidden Data from the Databanks."} end
if not DB[12861] then DB[12861]={id=12861,zoneId=66,name="Trolls Is Gone Crazy!",level=75,minLevel=74,giver="Chief Rageclaw",giverType="NPC",giverId=29690,ender="Chief Rageclaw",enderType="NPC",enderId=29690,poiX=5151,poiY=-2207,wowhead="https://www.wowhead.com/wotlk/quest=12861",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Drakuru... You know who this troll is? I think bad troll are controlled by the Drakuru troll. They call themself Drakuru trolls - that how I know. Now you see why I am chief of Rageclaw. Smartest of all wolvar!$B$BBut that not why I talk to you now. Bad troll come and kick Rageclaw out of den. Rageclaw that no run away held as prisoner in village. You go to Rageclaw Den, southeast, and free captured Rageclaw. Kill troll for lock opener. You maybe kill many troll for many lock opener.",logDesc="Chief Rageclaw at Light's Breach in Zul'Drak wants you to use the Drakuru \"Lock Openers\" found on various Drakuru trolls to free 8 Captured Rageclaw.",choiceRewards={{id=41760,qty=1},{id=41761,qty=1},{id=41762,qty=1},{id=41763,qty=1}}} end
if not DB[12862] then DB[12862]={id=12862,zoneId=67,name="When All Else Fails",level=78,minLevel=77,giver="Ricket",giverType="NPC",giverId=29428,ender="Rork Sharpchin",enderType="NPC",enderId=29744,poiX=6153,poiY=-1069,wowhead="https://www.wowhead.com/wotlk/quest=12862",image="assets/images/quests/placeholder.png",xpDiff=1,money=6800,desc="So...  so I don't think we're going to be getting a good foothold in those mountains.$B$BTrust me, I'm not one to give up easily... but between freezing engines, nasty vrykul women, territorial dragon want-to-bes and the half a dozen other nasties settled in the area, this just ain't happening.$B$BDon't let that dissuade you though! Just because we can't get a foothold doesn't mean we won't get you there... one-way trips are pretty simple when you get down to it.$B$B<Ricket nods at some nearby rockets.>",logDesc="Speak to Ricket to make use of Ricket's D16 Propelled Delivery Device to enter further into Storm Peaks."} end
if not DB[12863] then DB[12863]={id=12863,zoneId=67,name="Offering Thanks",level=78,minLevel=77,giver="Lagnus",giverType="NPC",giverId=29743,ender="Glorthal Stiffbeard",enderType="NPC",enderId=29727,rewardNextId=12864,poiX=6700,poiY=-249,wowhead="https://www.wowhead.com/wotlk/quest=12863",image="assets/images/quests/placeholder.png",xpDiff=1,money=6800,desc="Ah! Thanks for coming up here, $G lad:lass;.$B$BJudging by your wide eyes and shivering hands, I'd venture a guess that you're somewhat new. Sounds like it would be good for you to meet our gracious hosts then!$B$BWe've got some extra medical supplies... to be honest, we weren't expecting to have such a comfortable setup. Go ahead and give this crate to Glorthal over there, and lend them a hand if you would too. We don't want them to think we're ungrateful for how welcoming they've been.",logDesc="Bring the crate of medical supplies to Glorthal Stiffbeard in Frosthold."} end
if not DB[12864] then DB[12864]={id=12864,zoneId=67,name="Missing Scouts",level=78,minLevel=77,giver="Glorthal Stiffbeard",giverType="NPC",giverId=29727,ender="Glorthal Stiffbeard",enderType="NPC",enderId=29727,rewardNextId=12866,poiX=6646,poiY=-233,wowhead="https://www.wowhead.com/wotlk/quest=12864",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="There is something that I could use a hand with now that I have you.$B$BWe have a few scouts that are extremely late in returning. The peaks are harsh... but these boys know what they're doing.$B$BHead to the east... along the Bor's Breath valley and near Bor's Fall... they should be out that direction. If you find any sign of one of them, bring me back news immediately. We have a few enemies in the area - if any of them are getting a bit uppity, the more warning the better.",logDesc="Glorthal in Frosthold has requested a search of the Bor's Breath valley and Bor's Fall for any sign of the missing Frostborn Scouts."} end
if not DB[12865] then DB[12865]={id=12865,zoneId=67,name="Loyal Companions",level=78,minLevel=77,giver="Fjorlin Frostbrow",giverType="NPC",giverId=29732,ender="Fjorlin Frostbrow",enderType="NPC",enderId=29732,rewardNextId=12867,poiX=6607,poiY=-280,wowhead="https://www.wowhead.com/wotlk/quest=12865",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Fresh blood! Good to meet ya! I've got some work if you've got some time.$B$BOff to the east are the Foot Steppes... pretty hard land, but there's quite a group of rhino that graze there. Our birds have a taste for that rhino meat, but it's always a bit dangerous for them to go hunting with all of the proto-drakes that nest around there.$B$BIf you're keen, head over that way and get some rhino meat, bring it back to the peaks above here, and then use it to feed some of the eagles that nest there.",logDesc="Fjorlin Frostbrow at Frosthold wants you to obtain 8 slabs of Fresh Ice Rhino Meat and use them to feed the Stormcrest Eagles above town.",choiceRewards={{id=42789,qty=1},{id=42802,qty=1},{id=42814,qty=1},{id=42833,qty=1}}} end
if not DB[12866] then DB[12866]={id=12866,zoneId=67,name="Stemming the Aggressors",level=78,minLevel=77,giver="Glorthal Stiffbeard",giverType="NPC",giverId=29727,ender="Glorthal Stiffbeard",enderType="NPC",enderId=29727,rewardNextId=12868,poiX=6646,poiY=-233,wowhead="https://www.wowhead.com/wotlk/quest=12866",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Damn harpies. We've beat that bunch into submission more times than I can remember... and they stay quiet for a time after each bout. This time, I'd thought that maybe it sunk in.$B$BApparently not.$B$BTheir memory may be a bit short, but if their numbers are thinned enough, they'll keep to themselves. Head into the valleys in the north and east and clear out a fair chunk of them for me, will ya?",logDesc="Glorthal Stiffbeard at Frosthold wants you to kill 8 Frostfeather Screechers and 8 Frostfeather Witches."} end
if not DB[12867] then DB[12867]={id=12867,zoneId=67,name="Baby Stealers",level=78,minLevel=77,giver="Fjorlin Frostbrow",giverType="NPC",giverId=29732,ender="Fjorlin Frostbrow",enderType="NPC",enderId=29732,poiX=6607,poiY=-280,wowhead="https://www.wowhead.com/wotlk/quest=12867",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="A few weeks ago, if you looked up, you'd see dozens of those beautiful eagles soaring the skies. Now, only a few if any. They've taken to staying with their nests nearly all the time now because the harpies have been stealing their eggs.$B$BThe harpies have grown a taste for eagle flesh, it seems... the sick wretches are caring for the eggs long enough to feast on the hatchlings. Go into the valleys to the north or the east and find the eggs... bring them back here, and I'll take them back to the nests.",logDesc="Fjorlin Frostbrow at Frosthold would like you to bring back 15 Stormcrest Eagle Eggs."} end
if not DB[12868] then DB[12868]={id=12868,zoneId=67,name="Sirana Iceshriek",level=78,minLevel=77,giver="Glorthal Stiffbeard",giverType="NPC",giverId=29727,ender="Glorthal Stiffbeard",enderType="NPC",enderId=29727,poiX=6646,poiY=-233,wowhead="https://www.wowhead.com/wotlk/quest=12868",image="assets/images/quests/placeholder.png",xpDiff=6,money=136000,desc="This Sirana Iceshriek sounds like the one that's spurring the harpies to be more aggressive. If we kill her, I suspect their attacks won't last long afterwards.$B$BOne of our stormriders claims to have spotted her circling the peak directly northwest of here.  Go find the wench and put her down. Let's see this done.",logDesc="Glorthal Stiffbeard at Frosthold wants you to kill Sirana Iceshriek.",choiceRewards={{id=43185,qty=1},{id=43186,qty=1},{id=43188,qty=1},{id=43187,qty=1}}} end
if not DB[12869] then DB[12869]={id=12869,zoneId=67,name="Pushed Too Far",level=78,minLevel=77,giver="Fjorlin Frostbrow",giverType="NPC",giverId=29732,ender="Fjorlin Frostbrow",enderType="NPC",enderId=29732,poiX=6607,poiY=-280,wowhead="https://www.wowhead.com/wotlk/quest=12869",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="You were there with Loken, weren't you? The iron dwarves captured Veranus, the brood mother of the proto-drakes. The drakes don't seem even a little bit happy about the situation... they've gotten very aggressive.$B$BThey've pushed into stormcrest territory and the eagles have taken to an all out fight with them. It's time to return the favor. We're riding to the Foot Steppes and slaughtering them there.$B$BKing Stormheart left this hammer to me - make good use and see to it that I get it back.",logDesc="Fjorlin Frostbrow at Frosthold wants you to ride with a Stormcrest Eagle and kill 16 Stormpeak Wyrms in the Foot Steppes."} end
if not DB[12870] then DB[12870]={id=12870,zoneId=67,name="Ancient Relics",level=78,minLevel=77,giver="Rork Sharpchin",giverType="NPC",giverId=29744,ender="Rork Sharpchin",enderType="NPC",enderId=29744,poiX=6686,poiY=-209,wowhead="https://www.wowhead.com/wotlk/quest=12870",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Why hello thar!$B$BBefore you be headin' off to do your grand questin' and adventure, might I beg a wee favor of ya, $G lad:lass;?$B$BThese mountains be packed full'a precious relics and baubles... this place be a dream come true for tha league. I'd be much obliged if ya could bring any such treasures you stumble upon back ta me. You can even share in me ale for tha trouble! Trust me $G lad:lass;, that's a rich deal!",logDesc="Return 10 Relics of Ulduar to Rork Sharpchin in Frosthold.",choiceRewards={{id=43462,qty=1},{id=43470,qty=1},{id=43472,qty=2},{id=43473,qty=2}}} end
if not DB[12871] then DB[12871]={id=12871,zoneId=67,name="Aid from the Explorers' League",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,ender="Lagnus",enderType="NPC",enderId=29743,rewardNextId=12873,wowhead="https://www.wowhead.com/wotlk/quest=12871",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Interesting. I don't see any locking mechanisms on the shell. That suggests to me that it may take more than just finding the other piece to combine the keystone.$B$BTake the shell back to the expedition leader, Lagnus, at Frosthold. Once he gets over his awe, he should be able to glean what the core looks like based on the shell, and maybe they can get the Frost Dwarves to help find it.$B$BI'm going to see if I can find out how to combine the two pieces. We'll catch up once we've both made some progress.",logDesc="Take Norgannon's Shell to Lagnus at Frosthold."} end
if not DB[12872] then DB[12872]={id=12872,zoneId=67,name="Norgannon's Shell",level=80,minLevel=77,ender="Brann Bronzebeard",enderType="NPC",enderId=29579,wowhead="https://www.wowhead.com/wotlk/quest=12872",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Charging inventor's disk.$B$BDisk charging completed.$B$BPreparing emergency protocol gamma.$B$BEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.$B$BPlease have a pleasant millennium.",logDesc="Recover Norgannon's Shell from Archivist Mechaton.",choiceRewards={{id=42794,qty=1},{id=42824,qty=1},{id=42819,qty=1},{id=42807,qty=1},{id=42831,qty=1}}} end
if not DB[12873] then DB[12873]={id=12873,zoneId=67,name="The Frostborn King",level=80,minLevel=77,giver="Lagnus",giverType="NPC",giverId=29743,ender="Yorg Stormheart",enderType="NPC",enderId=29593,rewardNextId=12874,poiX=6700,poiY=-249,wowhead="https://www.wowhead.com/wotlk/quest=12873",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Definitely... I can see exactly what the core must look like. If any of the frostborn have seen it, they'll be sure to recognize the description.$B$BThere's no time to waste, let's get straight to business. Go talk to King Stormheart and request his aid... he's sure to know someone who can help us find the core. And be nice about it will you - he's very respected around here.",logDesc="Speak to Yorg Stormheart in Frosthold."} end
if not DB[12874] then DB[12874]={id=12874,zoneId=67,name="Fervor of the Frostborn",level=80,minLevel=77,giver="Yorg Stormheart",giverType="NPC",giverId=29593,ender="Yorg Stormheart",enderType="NPC",enderId=29593,rewardNextId=12875,poiX=6653,poiY=-311,wowhead="https://www.wowhead.com/wotlk/quest=12874",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I be more than willing ta lend my shelter and home ta travelers in need, but I'm nae too keen ta force my people inte yer affairs.$B$BI'll tell ye what... my people are warriors, straight and true. On the day a frostborn becomes a man, he has ta prove himself in battle. He has ta show us that he'll not let size hold'm back.$B$BShow me yer as strong and fierce as one of my men, and I'll have them lend ye an ear or a blade. Speak ta Fjorlin over by the cliff to the south there and he'll put ye ta the test.",logDesc="Yorg Stormheart at Frosthold has requested that you speak to Fjorlin Frostbrow to secure a ride and face your challenge.",choiceRewards={{id=42788,qty=1},{id=42801,qty=1},{id=42813,qty=1},{id=42832,qty=1}}} end
if not DB[12875] then DB[12875]={id=12875,zoneId=67,name="An Experienced Guide",level=80,minLevel=77,giver="Yorg Stormheart",giverType="NPC",giverId=29593,ender="Drom Frostgrip",enderType="NPC",enderId=29751,rewardNextId=12877,poiX=6653,poiY=-311,wowhead="https://www.wowhead.com/wotlk/quest=12875",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I don't know where this core is hiding, but ye knew that. I said I'd help though, and that I shall.$B$BThere's a hermit by the name of Drom Frostgrip who lives in a cave north of here... down in tha valley. We've strayed away from the titans a bit ourselves being that there are so few about, but Drom's loyal to the old ways... he keeps an eye on their most precious places and speaks te the keeper Creteus often.$B$BYer sure to find him in the back of his cave... tell'm I sent ye and he'll help ye.",logDesc="Locate Drom Frostgrip."} end
if not DB[12876] then DB[12876]={id=12876,zoneId=67,name="Unwelcome Guests",level=80,minLevel=77,giver="Fjorlin Frostbrow",giverType="NPC",giverId=29732,ender="Fjorlin Frostbrow",enderType="NPC",enderId=29732,poiX=6607,poiY=-280,wowhead="https://www.wowhead.com/wotlk/quest=12876",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Our scouts have spotted iron dwarves in the valley north of here. I overheard King Stormheart sending you to visit Drom and I'm admittedly a bit worried about'm.$B$BIf you find any iron dwarves when you head down there, put'm down hard and fast for me, eh? I dun think they know exactly where we are or how to get here just yet, and I'd prefer to keep it that way.",logDesc="Fjorlin Frostbrow at Frosthold wants you to kill 10 Stormforged Invaders."} end
if not DB[12877] then DB[12877]={id=12877,zoneId=67,name="The Lonesome Watcher",level=80,minLevel=77,giver="Drom Frostgrip",giverType="NPC",giverId=29751,ender="3",enderType="NPC",enderId=30052,rewardNextId=12986,poiX=6951,poiY=46,wowhead="https://www.wowhead.com/wotlk/quest=12877",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I never found the core... but I've often spoken to the keeper Creteus, and his omissions give him away. You'll find Creteus over the mountains to the east, in the Foot Steppes, keeping watch on the Engine of the Makers. The core might well be in there, but you'll need to win Creteus's favor.$B$BThe iron dwarves were here looking for something... it might well be the core. They took my ring. Find their leader, get the ring back, and show it to Creteus so that he knows I sent you.",logDesc="Recover Frostgrip's Signet Ring from an Iron Dwarf Monitor and then bring it to Creteus in the Foot Steppes."} end
if not DB[12878] then DB[12878]={id=12878,zoneId=67,name="The Hidden Relic",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30052,ender="The Guardian's Charge",enderType="NPC",enderId=30548,rewardNextId=12879,poiX=7364,poiY=-964,wowhead="https://www.wowhead.com/wotlk/quest=12878",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="During your absence, I was privileged enough to parley with the dwarf Brann Bronzebeard. This dwarf indicated his purpose for seeking the keystone, and I am satisfied that it is for satisfactory intent... I believe this dwarf may be the entity for which the keystone was created.$B$BNorgannon's Core is located in the Frigid Tomb to the southeast. Its guardians are ancient beings of ice, and they will not welcome your presence. Best these guardians and retrieve the keystone with my blessing, $r.",logDesc="Creteus in the Foot Steppes has provided you with the information to locate Norgannon's Core."} end
if not DB[12879] then DB[12879]={id=12879,zoneId=67,name="Fury of the Frostborn King",level=80,minLevel=77,giver="The Guardian's Charge",giverType="NPC",giverId=30548,ender="3",enderType="NPC",enderId=30082,rewardNextId=12880,poiX=7137,poiY=-1324,wowhead="https://www.wowhead.com/wotlk/quest=12879",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="<As you retrieve the core from the chest, you hear the thumping of heavy footsteps rushing towards you from the corridor. There is the faint sound of battle in the distance.>",logDesc="Bring Norgannon's Core back to Creteus in the Foot Steppes."} end
if not DB[12880] then DB[12880]={id=12880,zoneId=67,name="The Master Explorer",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30082,ender="Brann Bronzebeard",enderType="NPC",enderId=30382,poiX=7272,poiY=-879,wowhead="https://www.wowhead.com/wotlk/quest=12880",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Combining the keystone will require Norgannon's Binding - a device located in the Engine of the Makers, the large pit beside us. Brann should be down there with the other half of the keystone now. I have instructed him on the use of the device. He awaits your presence.$B$BI will do what I can to keep the iron dwarves occupied, but I do not have confidence that I will hold them for long. King Stormheart is returning to the defense of Frosthold with some of his men shortly. Please hurry, $r.",logDesc="Bring Norgannon's Core to Brann Bronzebeard in the Engine of the Makers."} end
if not DB[12881] then DB[12881]={id=12881,zoneId=67,name="The Brothers Bronzebeard",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=30405,wowhead="https://www.wowhead.com/wotlk/quest=12881",image="assets/images/quests/placeholder.png"} end
if not DB[12882] then DB[12882]={id=12882,zoneId=67,name="Ancient Relics",level=78,minLevel=77,giver="Olut Alegut",giverType="NPC",giverId=30472,ender="Olut Alegut",enderType="NPC",enderId=30472,poiX=7850,poiY=-788,wowhead="https://www.wowhead.com/wotlk/quest=12882",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="Welcome to the peaks.$B$BI have a simple request before you head off on whatever grand jaunt you have planned. There are relics and treasures of ancient Ulduar scattered through these mountains. Most are likely in possession of the various sentient races.$B$BReturn any that you find to me, and I will reward you in kind. Perhaps I'll even let you partake on my many potent ales.",logDesc="Return 10 Relics of Ulduar to Olut Alegut at the Grom'arsh Crash-site.",choiceRewards={{id=43462,qty=1},{id=43470,qty=1},{id=43472,qty=2},{id=43473,qty=2}}} end
if not DB[12883] then DB[12883]={id=12883,zoneId=66,name="Orders From Drakuru",level=75,minLevel=74,ender="Crusader Lord Lantinga",enderType="NPC",enderId=29687,rewardNextId=12884,wowhead="https://www.wowhead.com/wotlk/quest=12883",image="assets/images/quests/placeholder.png",xpDiff=5,money=118000,desc="Minions be hearin' da call of your masta! Da Lich King be givin' Drakuru full control of da armies of da Scourge in Zul'Drak. We be commanded ta kill everyting.$B$BEVERYTING MUST DIE!$B$BWe be processin' all da corpses in da Dead Fields and sendin' em up ta Prince Navarius' crew in  Zeramas for Scourgin'! Notin' goes ta waste on Drakuru's watch!$B$BSoon we be drinkin' da blood of da prophets ta become stronger dan eva before! Zul'Drak and Gundrak gonna fall to da Scourge!",logDesc="Return the Orders From Drakuru to Crusader Lord Lantinga at Light's Breach in Zul'Drak."} end
if not DB[12884] then DB[12884]={id=12884,zoneId=66,name="The Ebon Watch",level=75,minLevel=74,giver="Crusader Lord Lantinga",giverType="NPC",giverId=29687,ender="Stefan Vadu",enderType="NPC",enderId=28518,rewardNextId=12630,poiX=5147,poiY=-2205,wowhead="https://www.wowhead.com/wotlk/quest=12884",image="assets/images/quests/placeholder.png",xpDiff=2,desc="West of here, across the ruined roads and structures, is the death knight encampment of Ebon Watch.$B$B<Crusader Lord Lantinga rolls up Drakuru's orders.>$B$BTake these orders and deliver them to Stefan Vadu. He is the death knight in command at Ebon Watch. Let him know that the Argent Crusade will deal with Prince Navarius. They'll have to handle Drakuru.$B$BBe careful, $N. The way to Ebon Watch is teeming with Scourge.",logDesc="Deliver the Orders From Drakuru to Stefan Vadu at Ebon Watch in Zul'Drak."} end
if not DB[12885] then DB[12885]={id=12885,zoneId=67,name="The Exiles of Ulduar",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,wowhead="https://www.wowhead.com/wotlk/quest=12885",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="The Storm Peaks are an intriguing place, but there's far more here than titan ruins. The peoples who live here face a dire threat in Loken and his minions.$B$BHe sent his favorite servants, the iron dwarves, on a brutal campaign against all the creatures of stone. He expelled the earthen from Ulduar, forcing them to take shelter at Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren are beset by the iron dwarves there. Find and help them, $N.",logDesc="Speak with Bouldercrag the Rockshaper at Bouldercrag's Refuge."} end
if not DB[12886] then DB[12886]={id=12886,zoneId=67,name="The Drakkensryd",level=80,minLevel=77,giver="Gretta the Arbiter",giverType="NPC",giverId=29796,ender="3",enderType="NPC",enderId=29445,rewardNextId=13064,poiX=7088,poiY=-1777,wowhead="https://www.wowhead.com/wotlk/quest=12886",image="assets/images/quests/placeholder.png",xpDiff=6,desc="This is it.  You've passed all the tests of the Hyldsmeet... all but one.  You've risen among our sisters' best and fiercest.$B$BThe final test is at hand.  The Drakkensryd - the true test of a Hyldnir's worth and warrior spirit.  It'll be you, your riding drake, a chained harpoon and a score of your sisters vying for dominance.$B$BShow no quarter.  None will be expected.",logDesc="Use the Hyldnir Harpoon to defeat 10 Hyldsmeet Drakeriders at the Temple of Storms.  Use the Hyldnir Harpoon on a Column Ornament to exit the Drakkensryd and speak to Thorim when you've succeeded.",choiceRewards={{id=42841,qty=1},{id=42865,qty=1},{id=42887,qty=1},{id=42876,qty=1},{id=42863,qty=1}}} end
if not DB[12887] then DB[12887]={id=12887,zoneId=210,name="It's All Fun and Games",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Baron Sliver",enderType="NPC",enderId=29804,rewardNextId=12891,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=12887",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Knights of the Ebon Blade want to take the Scourge base known as The Shadow Vault to the northwest. I have a contact in their group who has asked for help.$B$BThe first step is to blind the Lich King. He's using a device known as The Ocular to watch the area, which floats above the vault's spires.$B$BOur dwarves have created something for you to use against it. After the 'eye' has been destroyed, find Baron Sliver on the vault grounds. He's pretending to still be under the Lich King's will.",logDesc="Destroy The Ocular and then report to Baron Sliver at The Shadow Vault."} end
if not DB[12888] then DB[12888]={id=12888,zoneId=67,name="SCRAP-E",level=80,minLevel=77,ender="SCRAP-E",enderType="NPC",enderId=29806,wowhead="https://www.wowhead.com/wotlk/quest=12888",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="This card allows the user to access the control panel of the scrapbot designated SCRAP-E, in order to perform maintenance and reprogram the bot's directives.$B$BSCRAP-E appears to be assigned to the interior of the building at The Inventor's Library. The card displays a list of the bot's broken components and failing systems. With the proper parts, the bot can be restored to working condition.",logDesc="Bring the SCRAP-E Access Card along with 4 Handfuls of Cobalt Bolts and 5 Overcharged Capacitors to SCRAP-E at The Inventor's Library."} end
if not DB[12889] then DB[12889]={id=12889,zoneId=67,name="The Prototype Console",level=80,minLevel=77,giver="SCRAP-E",giverType="NPC",giverId=29806,poiX=7989,poiY=-840,wowhead="https://www.wowhead.com/wotlk/quest=12889",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Designation SCRAP-E.$B$BDirective: Maintain consoles and databases of Inventor's Library in Keeper Mimir's absences.$B$BTime since last maintenance cycle: 489 days.$B$BStatus of schematic data: unknown.$B$BCurrent tasks: Repair prototype console.",logDesc="Interact with the Prototype Console in The Inventor's Library."} end
if not DB[12890] then DB[12890]={id=12890,zoneId=67,name="If Size Mattered...",level=79,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=12890",image="assets/images/quests/placeholder.png"} end
if not DB[12891] then DB[12891]={id=12891,zoneId=210,name="I Have an Idea, But First...",level=80,minLevel=77,giver="Baron Sliver",giverType="NPC",giverId=29804,ender="Baron Sliver",enderType="NPC",enderId=29804,rewardNextId=12893,poiX=8395,poiY=2675,wowhead="https://www.wowhead.com/wotlk/quest=12891",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="When I was in the - ahem - employ of the Lich King, we would often use a device known as a sovereign rod to keep some of the more intelligent Scourge in line.$B$BI require that you assist me in the construction of a new one.$B$BLuckily for you, all of the necessary components are at hand: a cultist rod, an abomination hook, a geist rope, and a handful of Scourge essences.$B$BThis should not be difficult, $c.",logDesc="Baron Sliver at The Shadow Vault has asked you to collect a Cultist Rod, an Abomination Hook, a Geist Rope, and 5 Scourge Essences."} end
if not DB[12892] then DB[12892]={id=12892,zoneId=210,name="It's All Fun and Games",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Baron Sliver",enderType="NPC",enderId=29804,rewardNextId=12891,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=12892",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Knights of the Ebon Blade want to take the Scourge base known as The Shadow Vault to the northwest. I have a contact in their group who has asked for help.$B$BThe first step is to blind the Lich King. He's using a device known as The Ocular to watch the area, which floats above the vault's spires.$B$BOur goblins have created something for you to use against it. After the 'eye' has been destroyed, find Baron Sliver on the vault grounds. He's pretending to still be under the Lich King's will.",logDesc="Destroy The Ocular and then report to Baron Sliver at The Shadow Vault."} end
if not DB[12893] then DB[12893]={id=12893,zoneId=210,name="Free Your Mind",level=80,minLevel=77,giver="Baron Sliver",giverType="NPC",giverId=29804,ender="Baron Sliver",enderType="NPC",enderId=29804,poiX=8395,poiY=2675,wowhead="https://www.wowhead.com/wotlk/quest=12893",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Vile, Lady Nightswood, and The Leaper would make excellent weapons in the fight against the Lich King if they can be broken from his will. That is what the Sovereign Rod is for.$B$BYou'll find them on the ledges to the east and west of the vault, as well as on the mid-tier of the vault above us. The rod is to be used upon the corpses of the three.$B$BFly now. We will have them as our own!",logDesc="Baron Sliver at the Shadow Vault wants you to use the Sovereign Rod on the corpses of Vile, Lady Nightswood, and The Leaper.",choiceRewards={{id=43874,qty=1},{id=43926,qty=1},{id=43925,qty=1},{id=43849,qty=1}}} end
if not DB[12894] then DB[12894]={id=12894,zoneId=66,name="Crusader Forward Camp",level=75,minLevel=74,giver="Crusader Lord Lantinga",giverType="NPC",giverId=29687,ender="Crusader MacKellar",enderType="NPC",enderId=29689,rewardNextId=12903,poiX=5147,poiY=-2205,wowhead="https://www.wowhead.com/wotlk/quest=12894",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Crusader Dargath, Crusader MacKellar, Engineer Reed and the twins, Gerk and Burr, were sent to the Dead Fields to establish a battle front days ago. As of my last correspondence with them, they had successfully established a camp on the border of the Dead Fields, northwest of here.$B$BIn light of this newfound information about Drakuru and Prince Navarius I think it would be prudent to send someone to the Crusader Forward Camp post-haste.$B$BPack up your belongings, $N. You must leave at once!",logDesc="Seek out Crusader MacKellar at the Crusader Forward Camp in Zul'Drak."} end
if not DB[12895] then DB[12895]={id=12895,zoneId=67,name="The Missing Bronzebeard",level=80,minLevel=77,giver="Boktar Bloodfury",giverType="NPC",giverId=29651,ender="Boktar Bloodfury",enderType="NPC",enderId=29651,rewardNextId=12909,poiX=7843,poiY=-812,wowhead="https://www.wowhead.com/wotlk/quest=12895",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Before we left, I received the file Scout Vor'takh compiled on this Brann Bronzebeard. There can be no doubt that Brann was headed for the Storm Peaks from his journal entries and findings in Grizzly Hills. Before we crashed, I caught sight of a campsite south of here, across the Foot Steppes, and overlooking the frozen Bor's Breath River.$B$BIf Brann isn't there, search the camp and its environs for any clues as to where that blasted dwarf might've gone. Bring back anything you find.",logDesc="Retrieve the Burlap-Wrapped Note from Brann's camp and return it to Boktar Bloodfury at the Grom'arsh Crash-Site."} end
if not DB[12896] then DB[12896]={id=12896,zoneId=210,name="If He Cannot Be Turned",level=80,minLevel=77,giver="Baron Sliver",giverType="NPC",giverId=29804,ender="Thassarian",enderType="NPC",enderId=29799,rewardNextId=12898,poiX=8395,poiY=2675,wowhead="https://www.wowhead.com/wotlk/quest=12896",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Death knights, such as General Lightsbane, are held on too tight of a leash to be able to be turned from the Lich King's will except under the most extraordinary circumstances.$B$BThe general keeps himself within the vault overseeing the creation of new weapons. Disturb one of his weapon racks at the northern forge and I assure you, he will come. I'll send Vile, Lady Nightswood, and The Leaper in to help you.$B$BIf we are to finally own The Shadow Vault, General Lightsbane must fall!",logDesc="Defeat General Lightsbane and then report your success back to Thassarian aboard the gunship, The Skybreaker."} end
if not DB[12897] then DB[12897]={id=12897,zoneId=210,name="If He Cannot Be Turned",level=80,minLevel=77,giver="Baron Sliver",giverType="NPC",giverId=29804,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,rewardNextId=12899,poiX=8395,poiY=2675,wowhead="https://www.wowhead.com/wotlk/quest=12897",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Death knights, such as General Lightsbane, are held on too tight of a leash to be able to be turned from the Lich King's will except under the most extraordinary circumstances.$B$BThe general keeps himself within the vault overseeing the creation of new weapons. Disturb one of his weapon racks at the northern forge and I assure you, he will come. I'll send Vile, Lady Nightswood, and The Leaper in to help you.$B$BIf we are to finally own The Shadow Vault, General Lightsbane must fall!",logDesc="Defeat General Lightsbane and then report your success back to Koltira Deathweaver aboard the gunship, Orgrim's Hammer."} end
if not DB[12898] then DB[12898]={id=12898,zoneId=210,name="The Shadow Vault",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Baron Sliver",enderType="NPC",enderId=29343,rewardNextId=12938,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=12898",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="It sounds like you did extremely well. And you secured three very important allies for the Knights of the Ebon Blade in the process.$B$B<Thassarian gazes out over the horizon.>$B$BYou should head back. By now, Baron Sliver and the other death knights will be fighting tooth and nail to hold The Shadow Vault against the might of the Scourge.$B$BI'm sure they'll need your help.",logDesc="Report back to Baron Sliver at The Shadow Vault.",choiceRewards={{id=43837,qty=1},{id=43838,qty=1},{id=43836,qty=1}}} end
if not DB[12899] then DB[12899]={id=12899,zoneId=210,name="The Shadow Vault",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Baron Sliver",enderType="NPC",enderId=29343,rewardNextId=12938,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=12899",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="It sounds like you did extremely well. And you secured three very important allies for the Knights of the Ebon Blade in the process.$B$B<Koltira gazes down at the map on the floor.>$B$BYou should head back. By now, Baron Sliver and the other death knights will be fighting tooth and nail to hold The Shadow Vault against the might of the Scourge.$B$BI'm sure they'll need your help.",logDesc="Report back to Baron Sliver at The Shadow Vault.",choiceRewards={{id=43837,qty=1},{id=43838,qty=1},{id=43836,qty=1}}} end
if not DB[12900] then DB[12900]={id=12900,zoneId=67,name="Making a Harness",level=80,minLevel=77,giver="Astrid Bjornrittar",giverType="NPC",giverId=29839,ender="Astrid Bjornrittar",enderType="NPC",enderId=29839,poiX=6793,poiY=-1696,wowhead="https://www.wowhead.com/wotlk/quest=12900",image="assets/images/quests/placeholder.png",xpDiff=5,desc="So you want to ride?  Well, if you've made it this far someone must think you've got a shot at the Hyldsmeet.$B$BFirst things first; we'll have to make you a harness.$B$BIn the cliffs to the south, you'll find scattered groups of yeti.  Their hides are tough and just the right thickness.  Bring me some and we'll get you started on the path of the bear-rider.",logDesc="Astrid Bjornrittar in Brunnhildar Village wants you to obtain 3 Icemane Yeti Hides.",choiceRewards={{id=42845,qty=1},{id=42869,qty=1},{id=42891,qty=1},{id=42880,qty=1}}} end
if not DB[12901] then DB[12901]={id=12901,zoneId=66,name="Making Something Out Of Nothing",level=76,minLevel=74,giver="Engineer Reed",giverType="NPC",giverId=29688,ender="Engineer Reed",enderType="NPC",enderId=29688,poiX=5542,poiY=-1860,wowhead="https://www.wowhead.com/wotlk/quest=12901",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Prince Navarius must be stopped. We can't let the Scourge continue to use this area as a zombie factory. If we can get the tank operational we might stand a chance. What I need right now are spare parts.$B$BNorthwest of here is an area called Thrym's End. The Scourge armies are using the area as a base of sorts. Spread out across the base is the wreckage from their arrival. Bits and pieces of Scourge scrap metal litter the landscape. Get that stuff to me and I'll try and put it to good use.",logDesc="Engineer Reed at Crusader Forward Camp in Zul'Drak has asked that you recover 10 pieces of Scourge Scrap Metal."} end
if not DB[12902] then DB[12902]={id=12902,zoneId=66,name="In Search Of Answers",level=75,minLevel=74,giver="Crusader Lord Lantinga",giverType="NPC",giverId=29687,rewardNextId=12883,poiX=5147,poiY=-2205,wowhead="https://www.wowhead.com/wotlk/quest=12902",image="assets/images/quests/placeholder.png",xpDiff=4,desc="These poor creatures are the only survivors.$B$BAccording to their chief, the Drakkari trolls and Rageclaw wolvar have been allies for thousands of years. They've been living here, alongside the trolls, for generations, completely unaware of the ever changing world around them. To the Rageclaw, a troll is a troll, so the troll attack upon their den took them by surprise.$B$BWe need some answers, $N. Scour their village - southeast of here - for clues as to who or what is in charge of these attacks.",logDesc="Search Rageclaw Den for a clue about who or what initiated the attacks against the Rageclaw Wolvar."} end
if not DB[12903] then DB[12903]={id=12903,zoneId=66,name="That's What Friends Are For...",level=76,minLevel=74,giver="Crusader MacKellar",giverType="NPC",giverId=29689,ender="Crusader MacKellar",enderType="NPC",enderId=29689,poiX=5539,poiY=-1862,wowhead="https://www.wowhead.com/wotlk/quest=12903",image="assets/images/quests/placeholder.png",xpDiff=5,desc="We were attacked by Prince Navarius and at least a dozen Scourge. I told Dargath and the twins to stay inside the tank, but they wouldn't listen. Dargath looked me in the eyes and said, \"If somebody doesn't get out of this tank, they'll kill us all.\" He then made Reed cut the engine and charged. Most heroic thing I've ever seen.$B$BI heard the Prince barking orders to the monsters. Sounded like he was taking them to Thrym's End, northwest of here. We have to rescue our friends. Will you go look for them?",logDesc="Crusader MacKellar at Crusader Forward Camp has asked that you find Crusader Dargath, Gerk and Burr.",choiceRewards={{id=39886,qty=1},{id=39816,qty=1},{id=39890,qty=1},{id=39889,qty=1}}} end
if not DB[12904] then DB[12904]={id=12904,zoneId=66,name="Light Won't Grant Me Vengeance",level=76,minLevel=74,giver="Gerk",giverType="NPC",giverId=29455,ender="Gerk",enderType="NPC",enderId=29455,poiX=5753,poiY=-1481,wowhead="https://www.wowhead.com/wotlk/quest=12904",image="assets/images/quests/placeholder.png",xpDiff=6,money=124000,desc="They... They killed my brother.$B$B<Gerk fights back tears.>$B$BSlaughtered him like he was some sort of animal. Now they got him laid out on one of their tables on the other side of the camp, ready for their grizzly experiments. Dargath's dead too. The paladin made a heroic stand at the ruins to the northeast, but the leader of the Vargul, Algar, was too strong.$B$BI'm all that's left and I'll be dead soon too. I... I'm turning.$B$BIf the Light won't grant me vengeance, maybe you will, $c. Kill them all.",logDesc="Gerk at Thrym's End in Zul'Drak wants you to kill 15 Vargul.$B"} end
if not DB[12905] then DB[12905]={id=12905,zoneId=67,name="Mildred the Cruel",level=79,minLevel=77,giver="Lok'lira the Crone",giverType="NPC",giverId=29481,ender="Mildred the Cruel",enderType="NPC",enderId=29885,rewardNextId=12906,poiX=6931,poiY=-1203,wowhead="https://www.wowhead.com/wotlk/quest=12905",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Our deal is made then, $N.  You help me get out of these chains and I'll help you find your little green friend.$B$BThe Hyldnir who runs this mine is known as Mildred the Cruel -- and with good reason.$B$BTell her you've been sent to lend a hand with the mines.  Do whatever she asks until she trusts you with the keys to my shackles.",logDesc="Speak to Mildred the Cruel inside the Forlorn Mine."} end
if not DB[12906] then DB[12906]={id=12906,zoneId=67,name="Discipline",level=79,minLevel=77,giver="Mildred the Cruel",giverType="NPC",giverId=29885,ender="Mildred the Cruel",enderType="NPC",enderId=29885,rewardNextId=12907,poiX=6929,poiY=-1316,wowhead="https://www.wowhead.com/wotlk/quest=12906",image="assets/images/quests/placeholder.png",xpDiff=3,money=36000,desc="Let's start you off with something straightforward.  The male vrykul that work the mines for us do so against their will... purely out of fear of our blades.$B$BOnce in a while, one of them will lose their motivation.  Find any uncooperative vrykul and put them in their place.$B$BTake this disciplining rod.  You'll want to inflict pain, not death.  Well, most of the time anyway.",logDesc="Mildred the Cruel at the Forlorn Mine wants you to use the Disciplining Rod on 6 Exhausted Vrykul.",choiceRewards={{id=42843,qty=1},{id=42867,qty=1},{id=42889,qty=1},{id=42878,qty=1}}} end
if not DB[12907] then DB[12907]={id=12907,zoneId=67,name="Examples to be Made",level=79,minLevel=77,giver="Mildred the Cruel",giverType="NPC",giverId=29885,ender="Mildred the Cruel",enderType="NPC",enderId=29885,rewardNextId=12908,poiX=6929,poiY=-1316,wowhead="https://www.wowhead.com/wotlk/quest=12907",image="assets/images/quests/placeholder.png",xpDiff=3,money=36000,desc="For every action there is an opposite reaction, sister.  In the case of us applying pressure on the males, this has meant newly spread rumors of insurrection.$B$BThe bearded pig behind this rabble-rousing is called Garhal.  Put an end to him... and make sure the other males see his demise.  They must learn that insubordination will not be tolerated.",logDesc="Mildred the Cruel at the Forlorn Mine wants you to slay Garhal."} end
if not DB[12908] then DB[12908]={id=12908,zoneId=67,name="A Certain Prisoner",level=79,minLevel=77,giver="Mildred the Cruel",giverType="NPC",giverId=29885,ender="Lok'lira the Crone",enderType="NPC",enderId=29481,rewardNextId=12921,poiX=6929,poiY=-1316,wowhead="https://www.wowhead.com/wotlk/quest=12908",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You are without mercy.  You will do well around these parts.$B$BI have another task to ask of you.  There is a female vrykul prisoner that's become more of a liability than I had anticipated.$B$BShe had the gall to claim the right to take part in the Hyldsmeet, our sacred competition of strength and fighting prowess.$B$BHere's the key to her shackles.  Make it as painless as possible.  She's a female after all, even if not one of us.",logDesc="Take Mildred's Key to Lok'lira the Crone in the Forlorn Mine."} end
if not DB[12909] then DB[12909]={id=12909,zoneId=67,name="The Nose Knows",level=80,minLevel=77,giver="Boktar Bloodfury",giverType="NPC",giverId=29651,ender="Khaliisi",enderType="NPC",enderId=29855,rewardNextId=12910,poiX=7843,poiY=-812,wowhead="https://www.wowhead.com/wotlk/quest=12909",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="In order to track down Brann, we're going to need a creature with a keen sense of smell and a good tracking ability. There weren't any hounds on the zeppelin, but I think I have a substitute.$B$BAfter the crash, I sent Khaliisi down the east face of the mountain to start hunting for food. Her cat, Frostbite, excels at tracking prey in the snow. Tell her that she'll have to part with her companion for a while, at least. She can hunt on her own, but we have no other way of catching up to Brann Bronzebeard.",logDesc="Speak with Khaliisi at the foot of the mountain east of the Grom'arsh Crash-Site."} end
if not DB[12910] then DB[12910]={id=12910,zoneId=67,name="Sniffing Out the Perpetrator",level=80,minLevel=77,giver="Khaliisi",giverType="NPC",giverId=29855,ender="Brann Bronzebeard",enderType="NPC",enderId=29579,rewardNextId=12913,poiX=7770,poiY=-1058,wowhead="https://www.wowhead.com/wotlk/quest=12910",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Boktar can have his way this time, but I'll expect him to make it up to me. Don't look at me like that. Boktar may be in command, but no one tells a hunter what to do.$B$B'Put that beast away,' he says. 'Make it stop growling.'$B$BAll of a sudden he changes his mind when it suits him. Next time he complains, Frostbite'll just nip him a bit. Don't worry, she'll do an admirable job tracking your prey. After she locates her target, you're on your own to deal with iron dwarves, or Brann, or whatever you find.",logDesc="Mount Frostbite and ride her to the source of the scent from Brann's note. Then, recover Brann's Communicator and use it to make contact with Brann Bronzebeard."} end
if not DB[12911] then DB[12911]={id=12911,zoneId=3896,name="Kill Credit Test",level=80,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=12911",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="/wave at me and I'll assign 'kill credit to player' to you.",logDesc="/wave at Kill Credit Test"} end
if not DB[12912] then DB[12912]={id=12912,zoneId=66,name="A Great Storm Approaches",level=76,minLevel=74,giver="3",giverType="NPC",giverId=29647,ender="Engineer Reed",enderType="NPC",enderId=29688,rewardNextId=12914,poiX=5796,poiY=-1594,wowhead="https://www.wowhead.com/wotlk/quest=12912",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You are not like the others, little one. You do not reek of the ancient death. Perhaps you can be trusted.$B$BI am Gymer, king of the storm giants. I was lured here by my brother, Thiassi, now an undead servant of the Lich King. By the time I realized that his cry for help was a trap, it was too late. I am now a prisoner of the Scourge and I fear that soon I will suffer the same fate as many of the other storm giants.$B$BFind a way to release me from this cage and I will aid you to the best of my ability.",logDesc="Gymer, King of Storm Giants, has asked you to find a way to release him from his cage. Speak with Engineer Reed at the Crusader Forward Camp."} end
if not DB[12913] then DB[12913]={id=12913,zoneId=67,name="Speak Orcish, Man!",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,ender="Moteha Windborn",enderType="NPC",enderId=29937,rewardNextId=12917,wowhead="https://www.wowhead.com/wotlk/quest=12913",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="<Brann begins gesticulating wildly and rambling in his native language.>$B$BRuk MogOth red a mogoth ta eft Thros-garE Haldir.$B$BKha gor ruk khaz ta ke ruk hrim eft thros-am-kha ruk kost-um havar go kost.$B$BA modoss hine ruk bergum eft thros-am-kha ga eft Haldir ke loch Thon we lo gefrunon ta mitta.$B$B Gar Ruk dagUm loch angor-magi ta har ruk!$B$B<After a few moments, you realize the conversation is going nowhere. Perhaps the shaman, Moteha Windborn, at the Grom'arsh Crash-Site will know what to do.>",logDesc="Speak with Moteha Windborn at the Grom'arsh Crash-Site."} end
if not DB[12914] then DB[12914]={id=12914,zoneId=66,name="Gymer's Salvation",level=76,minLevel=74,giver="Engineer Reed",giverType="NPC",giverId=29688,ender="Engineer Reed",enderType="NPC",enderId=29688,rewardNextId=12916,poiX=5542,poiY=-1860,wowhead="https://www.wowhead.com/wotlk/quest=12914",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Now you say that he's locked up in a 100 foot tall cage, eh?$B$BIf my calculations are correct, we should be able to at least weaken the hinges on the cage, giving the giant enough leeway to break out.$B$BIf this is going to work I'm going to need some plasticizers and stabilizers.$B$BBanshee essence should do nicely for the plasticizer. You can get that from the banshees in the Dead Fields, northeast of us. The stabilizer can be found on the earthragers to the southwest, near Ebon Watch.$B$BGet a move on!",logDesc="Engineer Reed at Crusader Forward Camp in Zul'Drak wants you to bring him 6 Banshee Essence and 6 Diatomaceous Earth."} end
if not DB[12915] then DB[12915]={id=12915,zoneId=67,name="Mending Fences",level=80,minLevel=77,giver="3",giverType="NPC",giverId=29445,ender="3",enderType="NPC",enderId=29445,poiX=7452,poiY=-535,wowhead="https://www.wowhead.com/wotlk/quest=12915",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="If I hope to wrest control of the Temple of the Makers from my brother, I must make amends with my old allies.$b$bPerhaps by eliminating a common enemy, we may at least take a step towards renewing my friendship with the frost giants.$b$bFjorn has besieged Dun Niffelem with giants of iron. You must defeat him at Fjorn's Anvil, far to the east of here, and weaken his forces sufficiently for the Sons of Hodir to emerge victorious.$b$bTake this charm, $n. Use it to summon my earthen to your aid.",logDesc="Thorim at the Temple of Storms wants you to Kill Fjorn and 5 Stormforged Iron Giants at Fjorn's Anvil, east of Dun Niffelem.$b$bUsing Thorim's Charm of Earth will summon his Earthen to fight by your side. The charm requires a Granite Boulder from nearby Fjorn's Anvil."} end
if not DB[12916] then DB[12916]={id=12916,zoneId=66,name="Our Only Hope",level=76,minLevel=74,giver="Engineer Reed",giverType="NPC",giverId=29688,ender="3",enderType="NPC",enderId=29647,rewardNextId=12919,poiX=5542,poiY=-1860,wowhead="https://www.wowhead.com/wotlk/quest=12916",image="assets/images/quests/placeholder.png",xpDiff=3,desc="What I'm about to give you is called seaforium. It is a highly volatile explosive with some unique properties. Due to its malleable nature, you will be able to fill in the hinges and cracks of the cage for maximum damage.$B$BReturn to your friend and use the jumbo seaforium charge to set him free.$B$BLet's hope he honors the bargain. He's our only hope.",logDesc="Speak to Gymer at Thrym's End in Zul'Drak once you have used the Jumbo Seaforium Charge to open the Scourge Enclosure that is holding him prisoner."} end
if not DB[12917] then DB[12917]={id=12917,zoneId=67,name="Speaking with the Wind's Voice",level=80,minLevel=77,giver="Moteha Windborn",giverType="NPC",giverId=29937,ender="Moteha Windborn",enderType="NPC",enderId=29937,poiX=7840,poiY=-811,wowhead="https://www.wowhead.com/wotlk/quest=12917",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I suppose we shouldn't have expected to find Brann so easily, not with our luck. If we can make sense of what Brann is saying, you can persuade him to give up his location.$B$BThe power of the wind is strong in these mountains, and it may prove a great boon to us. A knowledgeable shaman can hear the sound of all the world's tongues on the wind.$B$BTo the northwest, on the Snowdrift Plains, you will find beings made of wind, the stormriders. Capture their voices and bring them to me.",logDesc="Bring 5 Voices of the Wind to Moteha Windborn at the Grom'arsh Crash-Site."} end
if not DB[12918] then DB[12918]={id=12918,zoneId=-373,name="Gem Perfection",level=-1,minLevel=65,giver="Ounhulo",giverType="NPC",giverId=26915,ender="Ounhulo",enderType="NPC",enderId=26915,poiX=543,poiY=-5021,wowhead="https://www.wowhead.com/wotlk/quest=12918",image="assets/images/quests/placeholder.png",xpDiff=3,desc="It has the cold of the Icewyrm's breath up here does it not?   Not only do I lack customers for my crafting skills, but I also lack stock of gems to sell!   If you can bring me several uncut gems to replenish my stocks, I can teach you the skill of gem perfection.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.",logDesc="Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Ounhulo in Valgarde.",rewards={{id=41888,qty=1}}} end
if not DB[12919] then DB[12919]={id=12919,zoneId=66,name="The Storm King's Vengeance",level=76,minLevel=74,giver="3",giverType="NPC",giverId=29647,ender="Crusader MacKellar",enderType="NPC",enderId=29689,poiX=5796,poiY=-1594,wowhead="https://www.wowhead.com/wotlk/quest=12919",image="assets/images/quests/placeholder.png",xpDiff=7,money=186000,desc="My people have been decimated by the Lich King. The Scourge now use the corpses of storm giants to create mindless flesh giants, or worse, stitched together aberrations like Thrym.$B$BI will stop at nothing to see them all driven from this world. We will work together to destroy the Scourge that threaten Zul'Drak.$B$BWe will kill them all: Navarius, Algar and Thrym!$B$BWhen you are ready, let me know and we will begin our destructive journey.",logDesc="Speak with Gymer to begin.$B$BWhile riding Gymer, destroy 100 Scourge and kill Algar the Chosen, Thrym and Prince Navarius. Report to Crusader MacKellar at Crusader Forward Camp should you succeed.",choiceRewards={{id=41826,qty=1},{id=41829,qty=1},{id=41844,qty=1},{id=41845,qty=1},{id=41846,qty=1}}} end
if not DB[12920] then DB[12920]={id=12920,zoneId=67,name="Catching up with Brann",level=80,minLevel=77,giver="Boktar Bloodfury",giverType="NPC",giverId=29651,ender="Boktar Bloodfury",enderType="NPC",enderId=29651,rewardNextId=12926,poiX=7843,poiY=-812,wowhead="https://www.wowhead.com/wotlk/quest=12920",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="What are you waiting for? The language barrier has been broken, thanks to Moteha. Contact Brann Bronzebeard and find out anything you can about where he's hiding and what he's chasing after.$B$BMaybe we can still salvage something from this disaster.",logDesc="Use Brann's Communicator to contact Brann Bronzebeard and speak with him, then speak to Boktar Bloodfury at the Grom'arsh Crash-Site.$B$BIf you lose Brann's Communicator, speak with Moteha Windborn at the Grom'arsh Crash-Site."} end
if not DB[12921] then DB[12921]={id=12921,zoneId=67,name="A Change of Scenery",level=79,minLevel=77,giver="Lok'lira the Crone",giverType="NPC",giverId=29481,ender="Lok'lira the Crone",enderType="NPC",enderId=29975,rewardNextId=12969,poiX=6931,poiY=-1203,wowhead="https://www.wowhead.com/wotlk/quest=12921",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Excellent.  There's an exit in the eastern end of the mine that leads to Brunnhildar Village.  Follow it and I'll meet you there.$B$BWe must not be seen together so no one suspects you of aiding me.  I'll use my magic to disguise my appearance.  Do not worry, $r -- we'll find your friend in no time.",logDesc="Reconvene with Lok'lira the Crone in Brunnhildar Village."} end
if not DB[12922] then DB[12922]={id=12922,zoneId=67,name="The Refiner's Fire",level=80,minLevel=77,rewardNextId=12956,wowhead="https://www.wowhead.com/wotlk/quest=12922",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Beneath its porous exterior, this hunk of metal gleams with a mysterious quality.$b$bYou feel it would only be prudent to burn off the slag at Fjorn's Anvil.$b$bAs you ponder where in this frozen waste you might find something hot enough for the job, a fire revenant crosses your path...$B",logDesc="You must collect 10 Furious Sparks from the Seething Revenants at Frostfield Lake and then use the anvil at Fjorn's Anvil."} end
if not DB[12924] then DB[12924]={id=12924,zoneId=67,name="Forging an Alliance",level=80,minLevel=77,giver="3",giverType="NPC",giverId=29445,ender="3",enderType="NPC",enderId=30127,rewardNextId=13009,poiX=7452,poiY=-535,wowhead="https://www.wowhead.com/wotlk/quest=12924",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="<Thorim, for the first time since your meeting him, smiles.>$b$bThis is all beginning to have the smell of fate's hand, $r.$b$bYour discovery is what remains of my armor, long ago cast off in a fit of grief and left to the elements. Only the sons of Hodir are capable of its reforging, for they are its original creators.$b$bPerhaps you've done enough to soften their hatred of me. Seek out their king, Jokkum, if he still breathes.$b$bFind your way into his good graces and plead for his assistance.",logDesc="You are to go to Dun Niffelem and ask King Jokkum to allow Thorim's armor to be reforged. After completing Jokkum's task, you are to speak with Njormeld in Dun Niffelem.",choiceRewards={{id=42792,qty=1},{id=42805,qty=1},{id=42817,qty=1},{id=42830,qty=1}}} end
if not DB[12925] then DB[12925]={id=12925,zoneId=67,name="Aberrations",level=80,minLevel=77,giver="Thyra Kvinnshal",giverType="NPC",giverId=30041,ender="Thyra Kvinnshal",enderType="NPC",enderId=30041,poiX=6777,poiY=-1603,wowhead="https://www.wowhead.com/wotlk/quest=12925",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Lich King sent emissaries to us on three different occasions.  All three were promptly dismembered.$B$BOur sisters in Valkyrion were not as dedicated to our traditions and accepted the Scourge's advances.  Now instead of capturing their drakes from the wild, they raise them from the blight and filth that the Scourge wallow in.$B$BTake the frost oil that the Valkyrion Hyldnir carry on them and use it to freeze any blighted eggs you find.  Rumors speak of a fetid pool of blight where the eggs are kept.",logDesc="Thyra Kvinnshal in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants.  Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs."} end
if not DB[12926] then DB[12926]={id=12926,zoneId=67,name="Pieces of the Puzzle",level=80,minLevel=77,giver="Boktar Bloodfury",giverType="NPC",giverId=29651,ender="Brann Bronzebeard",enderType="NPC",enderId=29579,rewardNextId=12927,poiX=7843,poiY=-812,wowhead="https://www.wowhead.com/wotlk/quest=12926",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="We've seen the iron dwarves and their constructs making war on the creatures of stone that Brann calls the earthen, along with their giant allies. Contact him and aid him in any way you can, and remember that anything we can learn from his search may aid us in fighting against the iron dwarves and their master.",logDesc="Use Brann's Communicator to contact Brann Bronzebeard and find out what to do next."} end
if not DB[12927] then DB[12927]={id=12927,zoneId=67,name="Data Mining",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,ender="Brann Bronzebeard",enderType="NPC",enderId=29579,rewardNextId=13416,wowhead="https://www.wowhead.com/wotlk/quest=12927",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="That disk you assembled... it's blank! Keeper Mimir, the tinker who built this library, must've hidden the information elsewhere. Look around the Inventor's Library; do you see any databanks there?$B$BThat might be the disk's purpose. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.",logDesc="Use the Inventor's Disk to retrieve 7 pieces of Hidden Data from the Databanks. "} end
if not DB[12928] then DB[12928]={id=12928,zoneId=67,name="Norgannon's Shell",level=80,minLevel=77,ender="Brann Bronzebeard",enderType="NPC",enderId=29579,wowhead="https://www.wowhead.com/wotlk/quest=12928",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Charging inventor's disk.$B$BDisk charging completed.$B$BPreparing emergency protocol gamma.$B$BEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.$B$BPlease have a pleasant millennium.",logDesc="Recover Norgannon's Shell from Archivist Mechaton.",choiceRewards={{id=42794,qty=1},{id=42824,qty=1},{id=42819,qty=1},{id=42807,qty=1},{id=42831,qty=1}}} end
if not DB[12929] then DB[12929]={id=12929,zoneId=67,name="The Earthen of Ulduar",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,wowhead="https://www.wowhead.com/wotlk/quest=12929",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="The earthen who once inhabited, built, and maintained Ulduar were ousted from their home when Loken took over the city. Since then, his iron dwarf followers have relentlessly attacked the exiles.$B$BThey have taken refuge in an old titan building, which they now call Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren fight to keep the irons from overrunning their haven, but they cannot hold their ground long. Find and help them, $N.",logDesc="Speak with Bouldercrag the Rockshaper at Bouldercrag's Refuge."} end
if not DB[12930] then DB[12930]={id=12930,zoneId=67,name="Rare Earth",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,rewardNextId=12931,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=12930",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="It seems so long ago that these hammers pounded and hewed stone instead of iron. Our expulsion from Ulduar saw the weakest of us dead and the strongest of our craftsmen reborn as warriors.$B$BAs the irons beat us back, even the strongest find themselves failing.$B$BWe can do little for the wounded, save when we have a stock of enchanted earth. We used to mine it from the deposits on the sheer cliff face to the northwest, but the constant battle has prevented us from replenishing our stock. Would you help?",logDesc="Use the Earthen Mining Pick to mine 7 clumps of Enchanted Earth. Bring the earth and 5 Frostweave Cloth to Bouldercrag the Rockshaper at Bouldercrag's Refuge."} end
if not DB[12931] then DB[12931]={id=12931,zoneId=67,name="Fighting Back",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=12931",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The refuge's defenders have done their best to blunt the iron dwarves' attacks, but we keep losing ground inch by inch. My men are hardy, but not tireless. Without reinforcements, it's only a matter of time until we will be overrun.$B$BWould you lend your skills to the refuge's defense? It would greatly improve the morale of the defenders and give them -- and me -- hope of mounting a counterattack.$B$BKill any of the stormforged or their creations you encounter outside the refuge.",logDesc="Bouldercrag the Rockshaper wants you to slay 10 Stormforged Attackers and return to him at Bouldercrag's Refuge. You may kill either Stormforged Raiders or Stormforged Reavers."} end
if not DB[12932] then DB[12932]={id=12932,zoneId=66,name="The Amphitheater of Anguish: Yggdras!",level=77,minLevel=75,giver="Gurgthock",giverType="NPC",giverId=30007,ender="Wodin the Troll-Servant",enderType="NPC",enderId=30009,poiX=5792,poiY=-3018,wowhead="https://www.wowhead.com/wotlk/quest=12932",image="assets/images/quests/placeholder.png",xpDiff=7,money=195000,desc="I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand. These trolls are dirtier than ogres; but hey, I go where the gold's at! So welcome to Zul'Drak, pal.$B$BYou're new to this racket, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.$B$BIf you're ready and got a group of friends with you, we can start! What do you say?$B",logDesc="Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward."} end
if not DB[12933] then DB[12933]={id=12933,zoneId=66,name="The Amphitheater of Anguish: Magnataur!",level=77,minLevel=75,giver="Gurgthock",giverType="NPC",giverId=30007,ender="Wodin the Troll-Servant",enderType="NPC",enderId=30009,poiX=5792,poiY=-3018,wowhead="https://www.wowhead.com/wotlk/quest=12933",image="assets/images/quests/placeholder.png",xpDiff=7,money=195000,desc="This next match is a doozy, buddy! Apparently some magnataur from the Dragonblight wants a piece of the action. You ever fought one of those before? All I can tell you is to aim high!$B$BWe'll get this party started when you give me the word.",logDesc="Get in the arena at the Amphitheater of Anguish and defeat Stinkbeard! Return to Wodin the Troll-Servant to redeem your reward."} end
if not DB[12934] then DB[12934]={id=12934,zoneId=66,name="The Amphitheater of Anguish: From Beyond!",level=77,minLevel=75,giver="Gurgthock",giverType="NPC",giverId=30007,ender="Wodin the Troll-Servant",enderType="NPC",enderId=30009,poiX=5792,poiY=-3018,wowhead="https://www.wowhead.com/wotlk/quest=12934",image="assets/images/quests/placeholder.png",xpDiff=7,money=195000,desc="I'm not gonna lie to you, pal. You might be overmatched here. This next one is a being from the elemental planes! I don't even know what's gonna show up in that arena!$B$BIf you think you're up to it, get in there and give 'em hell!",logDesc="Get in the arena at the Amphitheater of Anguish and defeat one of the elemental lords! Return to Wodin the Troll-Servant to redeem your reward."} end
if not DB[12935] then DB[12935]={id=12935,zoneId=66,name="The Amphitheater of Anguish: Tuskarrmageddon!",level=77,minLevel=75,giver="Gurgthock",giverType="NPC",giverId=30007,ender="Wodin the Troll-Servant",enderType="NPC",enderId=30009,poiX=5792,poiY=-3018,wowhead="https://www.wowhead.com/wotlk/quest=12935",image="assets/images/quests/placeholder.png",xpDiff=7,money=195000,desc="This next one's fightin' from a dark place, kid. The kind of dark that can only happen when you've been on the flip-side. He's hungry and willing to do whatever it takes to win. Watch yourself! I've heard he wrestles yetis for exercise!$B$BWe'll start when you're ready.",logDesc="Get in the arena at the Amphitheater of Anguish and defeat Orinoko Tuskbreaker! Return to Wodin the Troll-Servant to redeem your reward.",rewards={{id=33447,qty=5},{id=33448,qty=5},{id=34722,qty=20}}} end
if not DB[12936] then DB[12936]={id=12936,zoneId=66,name="The Amphitheater of Anguish: Korrak the Bloodrager!",level=77,minLevel=75,giver="Gurgthock",giverType="NPC",giverId=30007,ender="Wodin the Troll-Servant",enderType="NPC",enderId=30009,poiX=5792,poiY=-3018,wowhead="https://www.wowhead.com/wotlk/quest=12936",image="assets/images/quests/placeholder.png",xpDiff=7,money=195000,desc="You're not gonna believe this, pal. Your next fight is against Korrak the Bloodrager! Looks like the Drakkari trolls are pulling a power play! And let me tell you, buddy, he's been sippin' the animal god juice. He's good and ready to pound you into the ground.$B$BAre you ready?",logDesc="Get in the arena at the Amphitheater of Anguish and defeat Korrak the Bloodrager! Return to Wodin the Troll-Servant to redeem your reward."} end
if not DB[12937] then DB[12937]={id=12937,zoneId=67,name="Relief for the Fallen",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=12937",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The refuge's defenders fight bravely, but they cannot keep up with the iron onslaught.$B$BWith the earth you collected, I can make bandages to help heal the wounds of some of the fallen. The more defenders we can patch up, the longer we'll last out there.$B$BTake these poultices and use them to heal the wounds of the fallen defenders outside the refuge. Get as many back into the battle as possible, $N. Every casualty is one too many.",logDesc="Use the Telluric Poultice to heal 8 Fallen Earthen Defenders, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge."} end
if not DB[12938] then DB[12938]={id=12938,zoneId=210,name="The Duke",level=80,minLevel=77,giver="Baron Sliver",giverType="NPC",giverId=29343,ender="Duke Lankral",enderType="NPC",enderId=30002,rewardNextId=12939,poiX=8385,poiY=2757,wowhead="https://www.wowhead.com/wotlk/quest=12938",image="assets/images/quests/placeholder.png",xpDiff=1,desc="We need you focused, $N. We're barely holding The Shadow Vault as it is. As you can see, we've greatly angered the Lich King.$B$B<The baron chuckles.>$B$BI need you to speak with Duke Lankral. He's in charge here now. You'll find him inside the vault building proper.$B$BWere I you, I would not keep him waiting.",logDesc="Speak with Duke Lankral at The Shadow Vault."} end
if not DB[12939] then DB[12939]={id=12939,zoneId=210,name="Honor Challenge",level=80,minLevel=77,giver="Duke Lankral",giverType="NPC",giverId=30002,ender="Duke Lankral",enderType="NPC",enderId=30002,rewardNextId=12943,poiX=8577,poiY=2643,wowhead="https://www.wowhead.com/wotlk/quest=12939",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The first step we're going to take is at a place in Jotunheim called the Savage Ledge. It's just over the mountains to the west.$B$BOn the ledge the vrykul warriors are always sparring, being instructed in the finer arts of battle by their thane's men.$B$BI want you to take this flag and issue a challenge to a number of them. Let's demoralize them with the 'mere' skills of a $r, shall we?$B$B<The duke grins, his rotting teeth flashing in the dim light of the vault.>",logDesc="Duke Lankral at The Shadow Vault has asked you to use the Challenge Flag to challenge and defeat 6 Mjordin Combatants."} end
if not DB[12940] then DB[12940]={id=12940,zoneId=-22,name="Candy Bucket",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=12940",image="assets/images/quests/placeholder.png",xpDiff=3,rewards={{id=37586,qty=1}}} end
