if not DB[12942] then DB[12942]={id=12942,zoneId=67,name="Off With Their Black Wings",level=80,minLevel=77,giver="Iva the Vengeful",giverType="NPC",giverId=29997,ender="Iva the Vengeful",enderType="NPC",enderId=29997,poiX=6778,poiY=-1595,wowhead="https://www.wowhead.com/wotlk/quest=12942",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Traitors.  We Hyldnir have little love for them.$B$BThe dwellers of Valkyrion have gone unpunished for far too long.  While we remained loyal to Thorim, they became the Lich King's lapdogs!$B$BThey call the ones who receive his gift val'kyr.  They fly on feathered wings, like the harpies they are.$B$BYou will find Valkyrion far to the northwest, beyond the Temple of Storms.  Slay these winged she-wolves, sister.  Slay them and I will reward you with one of my most prized possessions.",logDesc="Iva the Vengeful in Brunnhildar Village wants you to go to Valkyrion and slay 12 Nascent Val'kyr.",choiceRewards={{id=42849,qty=1},{id=42862,qty=1},{id=42883,qty=1},{id=42872,qty=1},{id=42892,qty=1}}} end
if not DB[12943] then DB[12943]={id=12943,zoneId=210,name="Shadow Vault Decree",level=80,minLevel=77,giver="Duke Lankral",giverType="NPC",giverId=30002,ender="Duke Lankral",enderType="NPC",enderId=30002,poiX=8577,poiY=2643,wowhead="https://www.wowhead.com/wotlk/quest=12943",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Thane Ufrang the Mighty sits within his hall overlooking the Savage Ledge. I've studied him. The thane is a patient vrykul, with a head for strategy and warfare. He's also shown a penchant for biding his time and not wanting to overplay his hand in the ongoing battle.$B$BI need him dead!$B$BI've written a decree. Stand before the thane and read it aloud.$B$B<The duke arches his eyebrow in amusement.>$B$BIt should... unnerve him at the least.",logDesc="Duke Lankral at The Shadow Vault has ordered you to read the Shadow Vault Decree in the presence of Thane Ufrang the Mighty, and then to slay him.",choiceRewards={{id=43857,qty=1},{id=43912,qty=1},{id=43980,qty=1},{id=43945,qty=1}}} end
