if not DB[12948] then DB[12948]={id=12948,zoneId=66,name="The Champion of Anguish",level=78,minLevel=75,giver="Gurgthock",giverType="NPC",giverId=30007,ender="Wodin the Troll-Servant",enderType="NPC",enderId=30009,poiX=5792,poiY=-3018,wowhead="https://www.wowhead.com/wotlk/quest=12948",image="assets/images/quests/placeholder.png",xpDiff=7,money=204000,desc="This is the end, my friend! Your last opponent is going to be your greatest challenge. He's a vrykul champion from the steppes of Icecrown and he's out for blood! Defeat him and you'll be crowned the champion of the Amphitheater of Anguish! This fight is going to make us both rich!$B$BLet me know when you're ready and we'll start.",logDesc="Get in the arena at the Amphitheater of Anguish and defeat Vladof the Butcher! Return to Wodin the Troll-Servant to redeem your reward.",choiceRewards={{id=41815,qty=1},{id=41821,qty=1},{id=41825,qty=1},{id=41816,qty=1},{id=41822,qty=1},{id=41824,qty=1}}} end
if not DB[12949] then DB[12949]={id=12949,zoneId=210,name="Get the Key",level=80,minLevel=77,giver="Vaelen the Flayed",giverType="NPC",giverId=30056,ender="Vaelen the Flayed",enderType="NPC",enderId=30056,rewardNextId=12951,poiX=8429,poiY=2870,wowhead="https://www.wowhead.com/wotlk/quest=12949",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="$C, the key to my shackles is hanging around the neck of Instructor Hroegar outside.$B$BPerhaps you could retrieve it by separating his head from his shoulders?",logDesc="Vaelen the Flayed at Ufrang's Hall has asked you to retrieve the Key to Vaelen's Chains."} end
