if not DB[12951] then DB[12951]={id=12951,zoneId=210,name="Let the Baron Know",level=80,minLevel=77,giver="Vaelen the Flayed",giverType="NPC",giverId=30056,ender="Baron Sliver",enderType="NPC",enderId=29343,poiX=8429,poiY=2870,wowhead="https://www.wowhead.com/wotlk/quest=12951",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="The most important thing that you can do right now is to return to The Shadow Vault and let Baron Sliver know that I've failed.$B$BYou see, I wasn't the only one captured by these vrykul devils. My entire contingent of death knights was also taken.$B$BI should have seen the trap before it was sprung, but there's no use crying over spilled milk now is there?$B$BGo on before you get captured, too! I'll see you back at the vault.",logDesc="Speak with Baron Sliver at The Shadow Vault."} end
if not DB[12952] then DB[12952]={id=12952,zoneId=-373,name="Gem Perfection",level=-1,minLevel=65,giver="Carter Tiffens",giverType="NPC",giverId=26960,ender="Carter Tiffens",enderType="NPC",enderId=26960,poiX=1956,poiY=-6196,wowhead="https://www.wowhead.com/wotlk/quest=12952",image="assets/images/quests/placeholder.png",xpDiff=3,desc="My skills are going to waste in this wretched place.   I spent many years learning to cut gems into their perfect form and have nothing to work on!   You look like the type who may be able to find me some gems and if you do I can teach you the skill of gem perfection.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.",logDesc="Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Carter Tiffens in Vengeance Landing.",rewards={{id=41888,qty=1}}} end
if not DB[12953] then DB[12953]={id=12953,zoneId=67,name="Valkyrion Must Burn",level=80,minLevel=77,ender="Iva the Vengeful",enderType="NPC",enderId=29997,wowhead="https://www.wowhead.com/wotlk/quest=12953",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="The crate is filled with incendiary harpoons.  You recall seeing harpoon guns and dry stacks of hay outside.$B$BPerhaps Iva will appreciate the extra effort and reward you appropriately.",logDesc="Use the Valkyrion Harpoon Guns to burn 6 Dry Haystacks.",choiceRewards={{id=42850,qty=1},{id=42884,qty=1},{id=42896,qty=1},{id=42874,qty=1}}} end
if not DB[12954] then DB[12954]={id=12954,zoneId=66,name="The Amphitheater of Anguish: Yggdras!",level=77,minLevel=75,giver="Gurgthock",giverType="NPC",giverId=30007,ender="Wodin the Troll-Servant",enderType="NPC",enderId=30009,poiX=5792,poiY=-3018,wowhead="https://www.wowhead.com/wotlk/quest=12954",image="assets/images/quests/placeholder.png",xpDiff=7,money=195000,desc="I was wondering when you'd show up, $N! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH!$B$BAnyway, this dump is Zul'Drak. All the ice trolls seem to use it as a toilet. I dunno, the whole place is off its rocker if you ask me! Who cares, though, right? We're here to make some gold!$B$BYou know the drill, $N. When you're ready let me know and we'll get this show on the road!$B",logDesc="Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward."} end
if not DB[12955] then DB[12955]={id=12955,zoneId=210,name="Eliminate the Competition",level=80,minLevel=77,giver="The Leaper",giverType="NPC",giverId=30074,ender="The Leaper",enderType="NPC",enderId=30074,rewardNextId=12999,poiX=8380,poiY=2718,wowhead="https://www.wowhead.com/wotlk/quest=12955",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Mrrfrmrfrrmrrr...$B$B<The Leaper clears his throat.>$B$BSorry about that. It can sometimes be hard to understand what I'm saying. You know how it is.$B$BI wanted to make sure that if you find yourself at the Savage Ledge, over the mountains to the west, that you make sure to eliminate the competition there.$B$BSpecifically, I'd like you to challenge to duels and humiliate Sigrid Iceborn, Efrem the Faithful, Onu'zun, and Tinky Wickwhistle in front of the vrykul.",logDesc="The Leaper at The Shadow Vault wants you to duel and defeat Sigrid Iceborn, Efrem the Faithful, Onu'zun and Tinky Wickwhistle.",choiceRewards={{id=43856,qty=1},{id=43913,qty=1},{id=43981,qty=1},{id=43946,qty=1},{id=43843,qty=1}}} end
if not DB[12956] then DB[12956]={id=12956,zoneId=67,name="A Spark of Hope",level=80,minLevel=77,ender="3",enderType="NPC",enderId=29445,wowhead="https://www.wowhead.com/wotlk/quest=12956",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Clearly, this is more than an ordinary hunk of metal.$b$bUnlike any ore you're familiar with, it is hard but not brittle, far lighter than it looks, and glows even when cool.$b$bLooking closer, you can make out one of Thorim's runes shining beneath the surface....",logDesc="You are to bring the Refined Gleaming Ore to Thorim in the Temple of Storms."} end
if not DB[12957] then DB[12957]={id=12957,zoneId=67,name="Slaves of the Stormforged",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=12957",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="To the southwest, on the western side of the Snowdrift Plains, the iron dwarves have dug a mine into the hillside. There, they use captive mechagnomes, servants of Keeper Mimir, to mine ore.$B$BI don't know where these mechagnomes came from, nor what they would do with their freedom, but perhaps we can win their help.$B$BGo to the Frozen Mine, $N, and set these creatures free from their bondage. Ask if they would fight alongside us against iron dwarf tyranny.",logDesc="Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to free 6 Captive Mechagnomes and kill 3 Stormforged Taskmasters."} end
if not DB[12958] then DB[12958]={id=12958,zoneId=-373,name="Shipment: Blood Jade Amulet ",level=-1,minLevel=65,giver="Timothy Jones",giverType="NPC",giverId=28701,ender="Timothy Jones",enderType="NPC",enderId=28701,poiX=5871,poiY=715,wowhead="https://www.wowhead.com/wotlk/quest=12958",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="A wealthy shipping concern has requested a collection of Blood Jade Amulets to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.$B",logDesc="Combine a Vrykul Amulet, a Dark Jade and a Bloodstone to make a Blood Jade Amulet and bring it to Timothy Jones in Dalaran.$B$BYou can find a Vrykul Amulet on any Northrend Vrykul.",rewards={{id=41596,qty=1}}} end
if not DB[12959] then DB[12959]={id=12959,zoneId=-373,name="Shipment: Glowing Ivory Figurine",level=-1,minLevel=65,giver="Timothy Jones",giverType="NPC",giverId=28701,ender="Timothy Jones",enderType="NPC",enderId=28701,poiX=5871,poiY=715,wowhead="https://www.wowhead.com/wotlk/quest=12959",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="A wealthy shipping concern has requested a collection of Glowing Ivory Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.$B",logDesc="Combine Northern Ivory, a Chalcedony and a Shadow Crystal to create a Glowing Ivory Figurine and bring it to Timothy Jones in Dalaran.$B$BYou can find a Northern Ivory on any Shoveltusk or Mammoth in Northrend.",rewards={{id=41596,qty=1}}} end
if not DB[12960] then DB[12960]={id=12960,zoneId=-373,name="Shipment: Wicked Sun Brooch",level=-1,minLevel=65,giver="Timothy Jones",giverType="NPC",giverId=28701,ender="Timothy Jones",enderType="NPC",enderId=28701,poiX=5871,poiY=715,wowhead="https://www.wowhead.com/wotlk/quest=12960",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="A wealthy shipping concern has requested a collection of Wicked Sun Brooches to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.$B",logDesc="Combine an Iron Dwarf Brooch, a Huge Citrine and a Sun Crystal to create a Wicked Sun Brooch and bring it to Timothy Jones in Dalaran.$B$BYou can find an Iron Dwarf Brooch on any Northrend Iron Dwarf.",rewards={{id=41596,qty=1}}} end
if not DB[12961] then DB[12961]={id=12961,zoneId=-373,name="Shipment: Intricate Bone Figurine",level=-1,minLevel=65,giver="Timothy Jones",giverType="NPC",giverId=28701,ender="Timothy Jones",enderType="NPC",enderId=28701,poiX=5871,poiY=715,wowhead="https://www.wowhead.com/wotlk/quest=12961",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="A wealthy shipping concern has requested a collection of Intricate Bone Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.$B",logDesc="Combine a Proto Dragon Bone, a Sun Crystal and a Dark Jade to craft an Intricate Bone Figurine and bring it to Timothy Jones in Dalaran.$B$BYou can find a Proto Dragon Bone on any Northrend Proto Dragon.",rewards={{id=41596,qty=1}}} end
if not DB[12962] then DB[12962]={id=12962,zoneId=-373,name="Shipment: Bright Armor Relic",level=-1,minLevel=65,giver="Timothy Jones",giverType="NPC",giverId=28701,ender="Timothy Jones",enderType="NPC",enderId=28701,poiX=5871,poiY=715,wowhead="https://www.wowhead.com/wotlk/quest=12962",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="A wealthy shipping concern has requested a collection of Bright Armor Relics to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.$B",logDesc="Combine an Elemental Armor Scrap, a Bloodstone and a Huge Citrine to craft a Bright Armor Relic and bring it to Timothy Jones in Dalaran.$B$BYou can find an Elemental Armor Scrap on any Northrend Revenant.",rewards={{id=41596,qty=1}}} end
if not DB[12963] then DB[12963]={id=12963,zoneId=-373,name="Shipment: Shifting Sun Curio ",level=-1,minLevel=65,giver="Timothy Jones",giverType="NPC",giverId=28701,ender="Timothy Jones",enderType="NPC",enderId=28701,poiX=5871,poiY=715,wowhead="https://www.wowhead.com/wotlk/quest=12963",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="A wealthy shipping concern has requested a collection of Shifting Sun Curios to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.$B",logDesc="Combine a Scourge Curio, a Sun Crystal and a Shadow Crystal to make a Shifting Sun Curio and bring it to Timothy Jones in Dalaran.$B$BYou can find a Scourge Curio on any Northrend Scourge.",rewards={{id=41596,qty=1}}} end
if not DB[12964] then DB[12964]={id=12964,zoneId=67,name="The Dark Ore",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=12964",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="At the Frozen Mine in the western part of the Snowdrift Plains, the stormforged iron dwarves have constructed a mine manned by slaves.$B$BIt's well behind the lines, so we haven't been able to find out much about what's going on there, but my scouts have reported seeing them remove cartloads of dark, sickly looking ore.",logDesc="Bring 5 Ore Samples to Bouldercrag the Rockshaper at Bouldercrag's Refuge."} end
if not DB[12965] then DB[12965]={id=12965,zoneId=67,name="The Gifts of Loken",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=12965",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The one who commands the stormforged iron dwarves is called Runeseer Valduran. Although I have never seen them, it is said that his master, Keeper Loken, who took over Ulduar, has given Valduran powerful titan artifacts.$B$BIt could explain the strength and ferocity my men see in the stormforged warriors.$B$BValduran's base, Nidavelir, lies to the southwest, across the Snowdrift Plains. Go there, $N, and neutralize his power. Destroy these gifts of Loken's and help us to sap the strength of his followers.",logDesc="Destroy Loken's Fury, Loken's Power, and Loken's Favor, and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.",choiceRewards={{id=42795,qty=1},{id=42820,qty=1},{id=42827,qty=1},{id=42808,qty=1}}} end
if not DB[12966] then DB[12966]={id=12966,zoneId=67,name="You Can't Miss Him",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30105,ender="3",enderType="NPC",enderId=30099,rewardNextId=12967,poiX=7346,poiY=-2813,wowhead="https://www.wowhead.com/wotlk/quest=12966",image="assets/images/quests/placeholder.png",money=7400,desc="<Jokkum listens patiently to your request, then ponders it carefully before responding.>$b$bSo it is you we have to thank for Fjorn's demise?$b$bWhile it's true that you have aided us in our time of need, there is still much that must be done to repair our relations with Thorim.$b$bFor now, I shall allow Njormeld to reforge the armor we gifted to the Stormlord so many ages ago. Consider it payment for your assistance against Fjorn.$b$bNjormeld was sent to recover Fjorn's anvil. You should find him there.",logDesc="King Jokkum in Dun Niffelem wants you to find Njormeld at Fjorn's Anvil."} end
if not DB[12967] then DB[12967]={id=12967,zoneId=67,name="Battling the Elements",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30099,ender="3",enderType="NPC",enderId=30099,poiX=7183,poiY=-3520,wowhead="https://www.wowhead.com/wotlk/quest=12967",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Snorri was once the pride of our nation. A mighty warrior, many an enemy fell to his club.$b$bWe honor him, though he's no longer what he once was. Age has taken its toll, dulling his senses and sapping his strength. Still, he remains as proud as ever, never missing an opportunity to join a battle.$b$bSpeaking of battle, we're cooling Fjorn's anvil so it can be taken home. The remaining fire revenants are putting up some resistance. Help Snorri relive his glory days, $r. Guide him against this enemy.",logDesc="Njormeld wants you to accompany Snorri to Fjorn's anvil and help him kill 10 Seething Revenants."} end
if not DB[12968] then DB[12968]={id=12968,zoneId=67,name="Yulda's Folly",level=80,minLevel=77,giver="Iva the Vengeful",giverType="NPC",giverId=29997,ender="Iva the Vengeful",enderType="NPC",enderId=29997,poiX=6778,poiY=-1595,wowhead="https://www.wowhead.com/wotlk/quest=12968",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="The witch that started it all, Yulda the Stormspeaker came to our very village.  She dared to insult our noble traditions and spouted the Lich King's venomous promises of power.$B$BShe ought to have left with a sword through her, but her magic was strong and she managed to escape.$B$BSeek her in Valkyrion inside the largest dwelling and show her that we are not to be trifled with.",logDesc="Iva the Vengeful at Brunnhildar Village wants you to slay Yulda the Stormspeaker in Valkyrion."} end
if not DB[12969] then DB[12969]={id=12969,zoneId=67,name="Is That Your Goblin?",level=80,minLevel=77,giver="Lok'lira the Crone",giverType="NPC",giverId=29975,ender="Lok'lira the Crone",enderType="NPC",enderId=29975,rewardNextId=12970,poiX=6922,poiY=-1535,wowhead="https://www.wowhead.com/wotlk/quest=12969",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I trust that's the green little one you've been looking for.  If I were you I'd step in before that Hyldnir splits him in half.$B$BYou've arrived in the middle of the Hyldsmeet, so all challenges must be accepted by participants.  There's nothing to stop you from taking your green friend's place.",logDesc="Challenge Agnetta Tyrsdottar in order to save Zeev Fizzlespark.  Return to Lok'lira the Crone in Brunnhildar Village after you've succeeded."} end
if not DB[12970] then DB[12970]={id=12970,zoneId=67,name="The Hyldsmeet",level=80,minLevel=77,giver="Lok'lira the Crone",giverType="NPC",giverId=29975,ender="Lok'lira the Crone",enderType="NPC",enderId=29975,rewardNextId=12971,poiX=6922,poiY=-1535,wowhead="https://www.wowhead.com/wotlk/quest=12970",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Whether you've noticed or not, by defeating your first Hyldnir in hand-to-hand combat, you've entered the Hyldsmeet -- the great competition of Hyldnir against Hyldnir to determine who will rule by Thorim's side.$B$BThe Hyldsmeet is the reason why I was imprisoned, for I sought to partake in the competition but was far too old and frail to be a match for the Hyldnir.$B$BIf you're willing to listen, I've a proposal for you.",logDesc="Listen to Lok'lira the Crone's proposal."} end
if not DB[12971] then DB[12971]={id=12971,zoneId=67,name="Taking on All Challengers",level=80,minLevel=77,giver="Lok'lira the Crone",giverType="NPC",giverId=29975,ender="Lok'lira the Crone",enderType="NPC",enderId=29975,rewardNextId=12972,poiX=6922,poiY=-1535,wowhead="https://www.wowhead.com/wotlk/quest=12971",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Let's get you started.  The good news is that by defeating Agnetta, you've earned yourself a spot in the next round of matches.$B$BThe bad news is that all your opponents will also have defeated someone in the first round.  Do not expect pushovers.",logDesc="Lok'lira the Crone in Brunnhildar Village wants you to defeat 6 Victorious Challengers.",choiceRewards={{id=43204,qty=1},{id=42890,qty=1},{id=42879,qty=1},{id=42868,qty=1}}} end
if not DB[12972] then DB[12972]={id=12972,zoneId=67,name="You'll Need a Bear",level=80,minLevel=77,giver="Lok'lira the Crone",giverType="NPC",giverId=29975,ender="3",enderType="NPC",enderId=29592,rewardNextId=12851,poiX=6922,poiY=-1535,wowhead="https://www.wowhead.com/wotlk/quest=12972",image="assets/images/quests/placeholder.png",xpDiff=3,desc="You've succeeded in the first rounds of the Hyldsmeet.  To advance further, you're going to need a warbear of your own.$B$BUnfortunately, the Hyldnir don't give them out to just anyone.  You'll have to emerge victorious from true battle, not just gladiatorial combat.$B$BThe Hyldnir of Brunnhildar are currently involved in a feud against the Sons of Hodir, Thorim's former allies.  Speak to Brijana just outside the village and see how you can help them and prove yourself in the process.",logDesc="Speak to Brijana outside Brunnhildar Village."} end
if not DB[12973] then DB[12973]={id=12973,zoneId=67,name="The Brothers Bronzebeard",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=30382,ender="Velog Icebellow",enderType="NPC",enderId=30401,poiX=7526,poiY=-972,wowhead="https://www.wowhead.com/wotlk/quest=12973",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.$B$BHop on my flying machine and help keep us covered from those iron dwarves on the way out!",logDesc="Accompany Brann Bronzebeard and his flying machine to Frosthold.",choiceRewards={{id=43192,qty=1},{id=43191,qty=1},{id=43189,qty=1},{id=43190,qty=1}}} end
if not DB[12974] then DB[12974]={id=12974,zoneId=66,name="The Champion's Call!",level=77,minLevel=75,giver="Shifty Vickers",giverType="NPC",giverId=30137,ender="Gurgthock",enderType="NPC",enderId=30007,rewardNextId=12932,poiX=5816,poiY=650,wowhead="https://www.wowhead.com/wotlk/quest=12974",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Pfft, what happens down here ain't fightin'. It's a couple of guys dancin' around a flag.$B$BYou lookin' for some real action, buddy? 'Cause if you are I got the hottest ticket in town.$B$BEver heard of Gurgthock and Wodin? Goblin and troll who ran the Ring of Blood back in Outland? Well they're here in Northrend and they've started up a whole new fight club over in Zul'Drak. If you're interested go to Zul'Drak, east of Crystalsong. They're at the big arena in the center. Tell 'em Shifty sent ya!",logDesc="Seek out Gurgthock at the Amphitheater of Anguish in Zul'Drak."} end
if not DB[12975] then DB[12975]={id=12975,zoneId=67,name="In Memoriam",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30105,ender="3",enderType="NPC",enderId=30105,rewardNextId=12976,poiX=7346,poiY=-2813,wowhead="https://www.wowhead.com/wotlk/quest=12975",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Surely Thorim has told you of the tragedy that divides us.$b$bIt was in Thunderfall, northeast of here, that these events unfolded. The frozen fossils there are a reminder of that dark day, as are the spirits that haunt that place.$b$bIf my people are to forgive Thorim, something must take the place of those images. A memorial must be constructed to bring our hearts peace.$b$bGo there, $r. Collect the fragments of Hodir's Horn that was shattered that day.",logDesc="King Jokkum in Dun Niffelem wants you to collect 8 Horn Fragments from Thunderfall."} end
if not DB[12976] then DB[12976]={id=12976,zoneId=67,name="A Monument to the Fallen",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30105,ender="3",enderType="NPC",enderId=30127,poiX=7346,poiY=-2813,wowhead="https://www.wowhead.com/wotlk/quest=12976",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Bring these fragments to Njormeld. He will use the pieces of that sacred relic in the construction of a mighty monument.$b$bMay it soothe the pains and heal the scars my people have borne these many years.$b$bMay its presence help to bring about a new age that sees us once again in glorious battle at Thorim's side.$b$bGo now, $c. Njormeld awaits you.",logDesc="King Jokkum wants you to bring Hodir's Horn Fragments to Njormeld in Dun Niffelem."} end
if not DB[12977] then DB[12977]={id=12977,zoneId=67,name="Blowing Hodir's Horn",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=12977",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You have done a great service to the giants of Dun Niffelem. Without your aid, this monument would not exist.$b$bAs you silently ponder its significance, feelings begin to flood your heart. The feelings fill your mind with thoughts and images... as well as a sense of urgency.$b$bThe sensations fade and leave you with a knowledge of what you must do. The restless spirits at Thunderfall must be put to rest.$b$bAs you set off, you find that your hands have been filled with an ethereal horn.",logDesc="You are to defeat 5 Niffelem Forefathers and 5 Restless Frostborn at Thunderfall. You are then to blow Hodir's Horn over their corpses, then return to Hodir's Horn in Dun Niffelem."} end
if not DB[12978] then DB[12978]={id=12978,zoneId=67,name="Facing the Storm",level=80,minLevel=77,giver="Bruor Ironbane",giverType="NPC",giverId=30152,ender="Bruor Ironbane",enderType="NPC",enderId=30152,poiX=8388,poiY=-383,wowhead="https://www.wowhead.com/wotlk/quest=12978",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Like Bouldercrag, I once served the keepers as a craftsman in Ulduar, but with Loken's betrayal, I turned my hammer toward our new foes.$B$BWhen we could spare the men, I led raids on Nidavelir to relieve the pressure on our defenders, but our lines are near collapse.$B$BYou've proven yourself a capable combatant and a staunch ally. Perhaps you'd be willing to take up our banner and take the fight to Nidavelir, the iron dwarf stronghold to the southwest, across the Snowdrift Plains.",logDesc="Bruor Ironbane at Bouldercrag's Refuge wants you to kill 10 Nidavelir Stormforged. You may kill Stormforged Champions, Stormforged Magi, or Stormforged War Golems."} end
if not DB[12979] then DB[12979]={id=12979,zoneId=67,name="Armor of Darkness",level=80,minLevel=77,ender="Bruor Ironbane",enderType="NPC",enderId=30152,rewardNextId=12980,wowhead="https://www.wowhead.com/wotlk/quest=12979",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="This armor plate is thick and oversized compared to the rest of the golem's defenses. A quick examination of the golem's corpse reveals that this heavier plate seems to have been bolted on as an afterthought or a crude upgrade.$B$BWhy would the iron dwarves have added this redundant and mismatched armor to their war golems?$B$BPerhaps Bruor Ironbane would know if he had the chance to examine several of these plates from stormforged war golems.",logDesc="Bring 4 Dark Armor Samples to Bruor Ironbane at Bouldercrag's Refuge."} end
if not DB[12980] then DB[12980]={id=12980,zoneId=67,name="The Armor's Secrets",level=80,minLevel=77,giver="Bruor Ironbane",giverType="NPC",giverId=30152,ender="Bruor Ironbane",enderType="NPC",enderId=30152,poiX=8388,poiY=-383,wowhead="https://www.wowhead.com/wotlk/quest=12980",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The presence of that armor plate is disorienting, but we need to find out all we can from it. It could be part of one of Valduran's schemes.$B$BHe's dedicated an extraordinary amount of effort to mining, refining, smithing, and testing this metal.$B$BTo the east, along the northern mountain face, is a building called Mimir's Workshop. It hasn't been used in quite some time, but if we're lucky, some of its attendants are still functional. Take your armor plate there and learn what you can from it.",logDesc="Take the Dark Armor Plate to Mimir's Workshop and ask Attendant Tock to examine it. When you're finished, return to Bruor Ironbane at Bouldercrag's Refuge."} end
if not DB[12981] then DB[12981]={id=12981,zoneId=67,name="Hot and Cold",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=12981",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="As you stare at the anvil you relive your recent accomplishments, particularly those which brought this artifact to rest here.$b$bIt suddenly occurs to you that more remains to be done. To the east, smoldering scraps clutter the landscape - shrapnel from the battle fought there.$b$bIf they could be cooled and gathered somehow, the frost giants would have an abundant supply of metal and the region would be cleared of these remnants of war.",logDesc="You are to go to Frostfield Lake, kill the Brittle Revenants there and use the Essence of Ice on the Smoldering Scraps at Fjorn's Anvil. You are then to collect 6 of the Frozen Iron scraps and return to Fjorn's Anvil in Dun Niffelem."} end
if not DB[12982] then DB[12982]={id=12982,zoneId=210,name="Ebon Blade Prisoners",level=80,minLevel=77,giver="Vaelen the Flayed",giverType="NPC",giverId=30218,ender="Vaelen the Flayed",enderType="NPC",enderId=30218,poiX=8546,poiY=2740,wowhead="https://www.wowhead.com/wotlk/quest=12982",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Now that I'm back, I'm certain that the baron will want me to recover my men. I can see that we're barely hanging on here. The Lich King's forces are about to break through and we won't be able to hold without my captured death knights.$B$BCan you assist me once more, $N?$B$BGo back to Jotunheim and let them out of those cages. Break the damn locks, I don't care what you have to do. The vrykul likely have the keys.$B$BJust get my men free!",logDesc="Vaelen the Flayed at The Shadow Vault wants you to free 8 Ebon Blade Prisoners. They can be found in the cages throughout the greater Jotunheim region.",choiceRewards={{id=43859,qty=1},{id=43910,qty=1},{id=43935,qty=1},{id=43844,qty=1}}} end
if not DB[12983] then DB[12983]={id=12983,zoneId=67,name="The Last of Her Kind",level=80,minLevel=77,giver="Astrid Bjornrittar",giverType="NPC",giverId=29839,ender="Astrid Bjornrittar",enderType="NPC",enderId=29839,rewardNextId=12996,poiX=6793,poiY=-1696,wowhead="https://www.wowhead.com/wotlk/quest=12983",image="assets/images/quests/placeholder.png",xpDiff=5,desc="For as long as I can remember, we've obtained our best bears from the Hibernal Cave to the east.$B$BThose times might finally be gone.  The cave has been overrun by ravenous jormungar and the wild bears are all but extinct.$B$BIf you were to find a surviving matriarch, however, I would guarantee you that she would fight better than any of these bears born in captivity.$B$BTake this harness to the Hibernal Cave and rescue a surviving matriarch.  Good luck finding one.",logDesc="Astrid Bjornrittar in Brunnhildar Village wants you to rescue an Icemaw Matriarch in the Hibernal Cavern."} end
if not DB[12984] then DB[12984]={id=12984,zoneId=67,name="Valduran the Stormborn",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,rewardNextId=12988,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=12984",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="We have no choice, $N. What you learned in Mimir's Workshop means that we must act before Valduran can complete and unleash his new weapon.$B$BEven now, the refuge's defenders fight to buy us time to deal with Valduran the Stormborn.$B$BYou must go to Nidavelir, across the Snowdrift Plains to the southwest, and then find and face Valduran. But you will not be alone. Bring this war horn with you and sound it as you prepare to face the leader of our enemies. Bruor and I will aid you in this battle.",logDesc="Use Bouldercrag's War Horn when you have found Valduran the Stormborn. Defeat Valduran the Stormborn and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.",choiceRewards={{id=42796,qty=1},{id=42809,qty=1},{id=42821,qty=1},{id=42836,qty=1}}} end
if not DB[12985] then DB[12985]={id=12985,zoneId=67,name="Forging a Head",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30127,ender="3",enderType="NPC",enderId=30127,rewardNextId=12987,poiX=7199,poiY=-2654,wowhead="https://www.wowhead.com/wotlk/quest=12985",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Greetings, $r.$b$bI have a task that King Jokkum felt you would be suited for, assuming you still strive to gain favor with our people.$b$bI have developed plans for another artifact, one that will grant Hodir's blessing of protection to our stronghold. I have nearly all that I require for its construction. All that remains to collect are the very eyes of our fallen enemies.$b$bTake this tool, and gather the eyes from the iron giant corpses that litter our fields.",logDesc="Njormeld in Dun Niffelem needs you to use the Diamond Tipped Pick on the Dead Iron Giants at Frostfield Lake and return to him when you have collected 8 Stormforged Eyes."} end
if not DB[12986] then DB[12986]={id=12986,zoneId=67,name="Fate of the Titans",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30052,ender="3",enderType="NPC",enderId=30052,rewardNextId=12878,poiX=7364,poiY=-964,wowhead="https://www.wowhead.com/wotlk/quest=12986",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Norgannon's Core is not at this location. I am not sure why you seek it, $r, and I am equally unsure if you truly know the purpose of that which you seek.$B$BI would like you to aid me before I consider extending my assistance.  I have recently encountered knowledge of the watcher, Thorim. His seat of power is contested, and his fate remains to be seen. This troubles me, for I do not know of the other watchers. Utilize this databank to examine their temples to the northeast and return the knowledge to me.",logDesc="Creteus in the Foot Steppes has requested that you travel to the Temple of Invention, the Temple of Winter, the Temple of Life, and the Temple of Order and utilize the databank to examine each area.",choiceRewards={{id=42791,qty=1},{id=42804,qty=1},{id=42816,qty=1},{id=42834,qty=1}}} end
if not DB[12987] then DB[12987]={id=12987,zoneId=67,name="Mounting Hodir's Helm",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30127,ender="3",enderType="NPC",enderId=30127,poiX=7199,poiY=-2654,wowhead="https://www.wowhead.com/wotlk/quest=12987",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="The helm is forged.$b$bYour efforts have not gone unnoticed, small one. Though there remains much to do, we sons of Hodir are grateful for your accomplishments.$b$bIn return, I offer you the opportunity to present Hodir's helm to our king and our brethren.$b$bFly to the sparkling tip of the small ice spike in front of me and read to our people from this tablet.$b$bEnjoy the privilege, $c. Never before has an outsider been given such an honor!",logDesc="Njormeld wants you to fly to the tip of the northern ice spike in Dun Niffelem and use the Tablets of Pronouncement."} end
if not DB[12988] then DB[12988]={id=12988,zoneId=67,name="Destroy the Forges!",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=12988",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="In my folly, I'd thought Valduran's project at Narvir's Cradle, a large construction area to the south, no more than a grotesque monument to \"Keeper\" Loken's cruelty.$B$BNow we know the truth, that it was meant to be used as a weapon against us and our allies. We must not allow this iron colossus to reach completion, $N, for it will mean the end of the refuge.$B$BGo to Narvir's Cradle, find the lightning forges the stormforged artisans use, and sabotage them.",logDesc="Destroy the North Lightning Forge, the Central Lightning Forge, and the South Lightning Forge with Bouldercrag's Bombs, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge."} end
if not DB[12989] then DB[12989]={id=12989,zoneId=67,name="The Slithering Darkness",level=80,minLevel=77,giver="Astrid Bjornrittar",giverType="NPC",giverId=29839,ender="Astrid Bjornrittar",enderType="NPC",enderId=29839,poiX=6793,poiY=-1696,wowhead="https://www.wowhead.com/wotlk/quest=12989",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The vile jormungar have taken over most of the Hibernal Cavern.  They are despicable beings... children of Loken, Thorim's scumsucker of a brother.$B$BAs Thorim's servants we owe it to ourselves to kill these scum where we find them.  You'll find the cavern just east of here, outside the village.",logDesc="Astrid Bjornrittar wants you to slay 8 Ravenous Jormungar in the Hibernal Cavern east of Brunnhildar Village.",choiceRewards={{id=42846,qty=1},{id=42870,qty=1},{id=42895,qty=1},{id=42881,qty=1},{id=42861,qty=1}}} end
if not DB[12990] then DB[12990]={id=12990,zoneId=-201,name="The Wormhole",level=-1,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=12990",image="assets/images/quests/placeholder.png",desc="Bring me materials and I'll teach you how to use your Wormhole Generator.",logDesc="Bring Jon LeCraft the materials he seeks to avoid a swift death, and to get a cool new spell."} end
if not DB[12991] then DB[12991]={id=12991,zoneId=67,name="Hit Them Where it Hurts",level=80,minLevel=77,giver="Bruor Ironbane",giverType="NPC",giverId=30152,ender="Bruor Ironbane",enderType="NPC",enderId=30152,poiX=8388,poiY=-383,wowhead="https://www.wowhead.com/wotlk/quest=12991",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Bouldercrag's got a good plan to stymie the efforts of the iron dwarves at Narvir's Cradle, and I've got an idea of my own. Work on the iron colossus will come to a halt without any artisans.$B$BNarvir's Cradle is on the south side of the hill sheltering Bouldercrag's Refuge. Go there and slay any stormforged artificers in your path. They may be no different from what we once were, but they build a weapon that threatens us all.",logDesc="Kill 10 Stormforged Artificers and return to Bruor Ironbane at Bouldercrag's Refuge."} end
if not DB[12992] then DB[12992]={id=12992,zoneId=210,name="Crush Dem Vrykuls!",level=80,minLevel=77,giver="Vile",giverType="NPC",giverId=30216,ender="Vile",enderType="NPC",enderId=30216,rewardNextId=13071,poiX=8374,poiY=2739,wowhead="https://www.wowhead.com/wotlk/quest=12992",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Dem vrykuls at the Jotunheim needs to be crushed!$B$B$N crush dems good!",logDesc="Vile at The Shadow Vault wants you to slay any 15 vrykul in the greater Jotunheim region.",choiceRewards={{id=43929,qty=1},{id=43858,qty=1},{id=43927,qty=1},{id=43911,qty=1},{id=43928,qty=1}}} end
if not DB[12993] then DB[12993]={id=12993,zoneId=67,name="A Colossal Threat",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,rewardNextId=12998,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=12993",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You've done an excellent job of delaying the work on the iron colossus, but I fear we've only made the stormforged more determined to complete the weapon.$B$BEven now, they're bringing in new laborers and the overseers push them to the limit. We may not be able to keep them from bringing the colossus online, after all. Return to Narvir's Cradle, to the south and find the documents detailing the colossus' offensive and defensive abilities. They should be near the tents and forges on the bottom level.",logDesc="Retrieve the Colossus Attack Specs and Colossus Defense Specs and bring them to Bouldercrag the Rockshaper at Bouldercrag's Refuge."} end
if not DB[12994] then DB[12994]={id=12994,zoneId=67,name="Spy Hunter",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30294,ender="3",enderType="NPC",enderId=30294,poiX=7366,poiY=-2674,wowhead="https://www.wowhead.com/wotlk/quest=12994",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The rapport you've developed with the inhabitants of Dun Niffelem has yielded some unexpected discoveries.$b$bFor example, you somehow find yourself able to understand the denmother's guttural growls and sharp quips - at least you think you do.$b$bIt would seem that she senses danger outside the stronghold and wants you to do something about it.$b$bWith her forepaw, she removes the chain from around her neck and lets it drop at your feet. As you pick it up you notice an aged fang attached to it....",logDesc="You must defeat 3 Stormforged Spies in the Valley of Ancient Winters.$b$bUsing the Ethereal Worg's Fang at the Corpse of the Fallen Worg will summon an Ethereal Frostworg, which will expose hidden enemies. You are to return to the Frostworg Denmother in Dun Niffelem when the valley has been cleansed of spies."} end
if not DB[12995] then DB[12995]={id=12995,zoneId=210,name="Leave Our Mark",level=80,minLevel=77,giver="Baron Sliver",giverType="NPC",giverId=29343,ender="Baron Sliver",enderType="NPC",enderId=29343,poiX=8385,poiY=2757,wowhead="https://www.wowhead.com/wotlk/quest=12995",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="We must attack the vrykul of Jotunheim on many levels. Brute force, of course, is good, but I prefer a more cerebral approach.$B$BI want you to demoralize them.$B$BMy men here have forged a number of banners for you. I would like for you to take and plant them near the corpses of fallen vrykul.$B$BLet the banners serve as a constant reminder to them that they face a more immediate threat than the wrath of the Lich King.",logDesc="Baron Sliver at The Shadow Vault wishes you to plant 15 Ebon Blade Banners near the corpses of vrykul found within the greater Jotunheim region."} end
if not DB[12996] then DB[12996]={id=12996,zoneId=67,name="The Warm-Up ",level=80,minLevel=77,giver="Astrid Bjornrittar",giverType="NPC",giverId=29839,ender="Astrid Bjornrittar",enderType="NPC",enderId=29839,rewardNextId=12997,poiX=6793,poiY=-1696,wowhead="https://www.wowhead.com/wotlk/quest=12996",image="assets/images/quests/placeholder.png",xpDiff=4,desc="You've been very fortunate, sister.  This is a matriarch the likes of which hasn't been seen in years.$B$BA good bear won't do you much good without the skill to ride it.$B$BI'm going to have you practice some moves on Kirgaraak.  He's the largest yeti we've ever managed to capture so be careful.  Don't be afraid to walk away if he gives you a beating... there's a reason why we keep him chained.",logDesc="Astrid Bjornrittar in Brunnhildar Village wants you to use the Reins of the Warbear Matriarch to defeat Kirgaraak."} end
if not DB[12997] then DB[12997]={id=12997,zoneId=67,name="Into the Pit",level=80,minLevel=77,giver="Astrid Bjornrittar",giverType="NPC",giverId=29839,ender="Astrid Bjornrittar",enderType="NPC",enderId=29839,rewardNextId=13061,poiX=6793,poiY=-1696,wowhead="https://www.wowhead.com/wotlk/quest=12997",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Besting a tethered opponent is one thing.  Fighting other bear riders on equal footing is another.$B$BHead into the Pit of the Fang and use what you've learned to defeat your opponents.  Good luck, sister.$B$BGlory awaits, should you succeed.",logDesc="Astrid Bjornrittar, in Brunnhildar Village, wants you to use the Reins of the Warbear Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears."} end
if not DB[12998] then DB[12998]={id=12998,zoneId=67,name="The Heart of the Storm",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,rewardNextId=13007,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=12998",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="According to the documents you captured at Narvir's Cradle, the iron colossus is complete except for one key component -- the Heart of the Storm.$B$BWithout it, the iron colossus' weapons would be much weaker than the design predicts. If we can deny Overseer Narvir the heart, we could defeat the colossus!$B$BNotes on the documents you found say that the heart is in Uldis, a titan facility far to the south. Its entrance is on the south side of a tall mountain overlooking the Bor's Breath River.",logDesc="Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to travel to Uldis and try to prevent Overseer Narvir from obtaining the Heart of the Storm."} end
if not DB[12999] then DB[12999]={id=12999,zoneId=210,name="The Bone Witch",level=80,minLevel=77,giver="The Leaper",giverType="NPC",giverId=30074,ender="The Bone Witch",enderType="NPC",enderId=30232,poiX=8380,poiY=2718,wowhead="https://www.wowhead.com/wotlk/quest=12999",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="You remember Lady Nightswood, don't you? She certainly remembers you. She's the forlorn and very angry banshee that you 'saved' when you also broke Vile and myself out from under the Lich King's dominion.$B$BThe lady has gone into Jotunheim and possessed their bone witch. She intends to wreak havoc upon the vrykul from within.$B$BShe has asked that you seek her out. You'll find her in the cave on the south side of Njorndar Village to the southwest within Jotunheim.",logDesc="Speak with The Bone Witch within the cave at Njorndar Village."} end
if not DB[13000] then DB[13000]={id=13000,zoneId=67,name="Emergency Measures",level=79,minLevel=77,giver="Bloodguard Lorga",giverType="NPC",giverId=30247,ender="Bloodguard Lorga",enderType="NPC",enderId=30247,poiX=7870,poiY=-750,wowhead="https://www.wowhead.com/wotlk/quest=13000",image="assets/images/quests/placeholder.png",xpDiff=5,money=71000,desc="The cold in these mountains is brutal.  We have a day or two before we burn up all the wood from the wreckage.$B$BWe spotted worgs inside a cave directly east of here.  I need you to find the cave and obtain some furs.  It might not sound like much, but it might be the difference between freezing to death and living another day.$B$BWorgs don't hunt alone, so I'm giving you a flare.  It should buy you some time if you find yourself outnumbered.",logDesc="Bloodguard Lorga wants you to go to the Gimorak's Den to the east and obtain 6 Worg Furs.",choiceRewards={{id=42788,qty=1},{id=42801,qty=1},{id=42813,qty=1},{id=42832,qty=1}}} end
if not DB[13001] then DB[13001]={id=13001,zoneId=67,name="Raising Hodir's Spear",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30252,ender="3",enderType="NPC",enderId=30252,poiX=7398,poiY=-2770,wowhead="https://www.wowhead.com/wotlk/quest=13001",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The time has come, little $c. The stars have foretold of this day.$b$bI have received a vision from mighty Hodir himself, revealing the secret to the creation of a great artifact.$b$bWe must obey! Were we to fail in receiving this gift, doom would surely follow.$b$bI call upon you to assist me in this sacred undertaking.$b$bGo across the valley, deep into the Hibernal Cavern and gather everfrost shards from the icy crater there, then collect hides from the mammoths outside the cavern.",logDesc="Lorekeeper Randvir in Dun Niffelem wants you to collect 3 Everfrost Shards from the depths of Hibernal Cavern and 3 Stoic Mammoth Hides from the Stoic Mammoths in the Valley of Ancient Winters."} end
if not DB[13002] then DB[13002]={id=13002,zoneId=-373,name="Gem Perfection",level=-1,minLevel=65,giver="Geba'li",giverType="NPC",giverId=26982,ender="Geba'li",enderType="NPC",enderId=26982,poiX=2848,poiY=6171,wowhead="https://www.wowhead.com/wotlk/quest=13002",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Welcome to de cold, mon.  Dis place may not be so good for keepin' me bones warm, but I have learned how to cut me de perfect gem.  All I be needin' is some gems to do me work on.$B$BBring me some gems and I be teachin' you the skill of gem perfection.  Dis will allow you to sometimes cut a perfect gem with increased bonuses when cuttin' an uncommon quality gem from Northrend.",logDesc="Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Geba'li in Warsong Hold.",rewards={{id=41888,qty=1}}} end
if not DB[13003] then DB[13003]={id=13003,zoneId=67,name="Thrusting Hodir's Spear",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13003",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Hodir's Spear is an icon of great prowess in battle.$b$bIts mere presence instills a deep hunger for glory in all who enter Dun Niffelem. In fact, simply being near it has compelled you to test your own abilities.$b$bScanning the horizon, your vision locks on a wild wyrm as it flies nearby.$b$bIt is decided. Of you and he, only one shall see the next sunrise....",logDesc="You are to use Hodir's Spear to challenge a Wild Wyrm in the Valley of Ancient Winters. Once in its grip, you are to fight to the death."} end
if not DB[13004] then DB[13004]={id=13004,zoneId=-373,name="Gem Perfection",level=-1,minLevel=65,giver="Alestos",giverType="NPC",giverId=26997,ender="Alestos",enderType="NPC",enderId=26997,poiX=2121,poiY=5260,wowhead="https://www.wowhead.com/wotlk/quest=13004",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There's a war going on and we each must do our part!  Mine is cutting gems and not only can I cut normal gems but I have the skill to cut perfect gems as well.   If you can bring me several uncut gems to contribute to the cause, I can teach you gem perfection as well.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.",logDesc="Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Alestros in Valiance Keep.",rewards={{id=41888,qty=1}}} end
if not DB[13005] then DB[13005]={id=13005,zoneId=67,name="The Earthen Oath",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30295,ender="3",enderType="NPC",enderId=30295,poiX=7762,poiY=-2160,wowhead="https://www.wowhead.com/wotlk/quest=13005",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="For years I neglected my duties, giving into defeat and self-pity.$B$BNot the brave earthen, however.  Their oath to protect these grounds with their lives has gone unbroken.$B$BEven now, they fight the corruption of iron with selflessness, waiting for the moment in which the tides turn.$B$BThat moment has arrived.  We must rally what remains of the earthen defenders and lead them into a glorious victory.  Sound the Horn of the Peaks to call them to your side and take back the Terrace of the Makers.",logDesc="Thorim, at the Terrace of the Makers, wants you to use the Horn of the Peaks and call on the Earthen to defeat 20 Iron Dwarves and 7 Iron Sentinels.",choiceRewards={{id=42847,qty=1},{id=42871,qty=1},{id=42893,qty=1},{id=42882,qty=1}}} end
if not DB[13006] then DB[13006]={id=13006,zoneId=67,name="Polishing the Helm",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13006",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="As you draw near the helm, you notice that the frigid environment is already taking its toll on the artifact's surface. What is now just a thin layer of ice will surely grow to envelop it entirely.$b$bNot about to let your hard efforts go to waste, you resolve to scour the region in search of a solution.$b$bJust as you set off, the eyes of the helm flash and an image of the nearby Hibernal Cavern enters your mind.",logDesc="You are to enter Hibernal Cavern west of Dun Niffelem and collect 5 units of Viscous Oil from the Viscous Oils there.$b$bYou are then to return to Dun Niffelem and apply the oil to Hodir's Helm."} end
if not DB[13007] then DB[13007]={id=13007,zoneId=67,name="The Iron Colossus",level=80,minLevel=77,giver="Bouldercrag the Rockshaper",giverType="NPC",giverId=29801,ender="Bouldercrag the Rockshaper",enderType="NPC",enderId=29801,poiX=8393,poiY=-393,wowhead="https://www.wowhead.com/wotlk/quest=13007",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="We have failed to prevent the completion of the iron colossus, $N, which means we have no choice but to face it in battle.$B$BBruor has devised a plan to exploit the colossus' only weakness.$B$BNo matter how tough the colossus' armor is, it is still vulnerable to a jormungar's acid. Take control of one using the orbs along the northern edge of the Snowdrift Plains, then use it to fight the Iron Colossus on the Snowdrift Plains. If you need help controlling the creature, speak to one of the nearby handlers.",logDesc="Use a Tamed Jormungar to defeat the Iron Colossus and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.",choiceRewards={{id=43200,qty=1},{id=43201,qty=1},{id=43202,qty=1},{id=43203,qty=1}}} end
if not DB[13008] then DB[13008]={id=13008,zoneId=210,name="Scourge Tactics",level=78,minLevel=77,giver="Crusade Commander Entari",giverType="NPC",giverId=30223,ender="Crusade Commander Entari",enderType="NPC",enderId=30223,poiX=6256,poiY=-18,wowhead="https://www.wowhead.com/wotlk/quest=13008",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="We had the element of surprise on our side! We blew a hole in the side of the mountain and charged into Scourgeholme. Scourge opposition was fierce and it wasn't long until we were overwhelmed. We fell back to the valley and began raining artillery down on the Scourge that followed. This held them back for awhile until... Those monsters began using crusaders as living shields. We had to stop shelling for fear of killing our own soldiers.$B$BFree our crusaders trapped on the field outside the base, $c!",logDesc="Crusade Commander Entari at the Argent Vanguard in Icecrown has asked that you free 8 Webbed Crusaders."} end
if not DB[13009] then DB[13009]={id=13009,zoneId=67,name="A New Beginning",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30127,ender="3",enderType="NPC",enderId=29445,rewardNextId=13050,poiX=7199,poiY=-2654,wowhead="https://www.wowhead.com/wotlk/quest=13009",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="It remains uncertain whether or not our people can ever rekindle the affection we once held for Thorim.$b$bMay this armor, if nothing else, remind him of the days when we stood together in honor, invincible.",logDesc="Njormeld wants you to take the Reforged Armor to Thorim at the Temple of Storms."} end
if not DB[13010] then DB[13010]={id=13010,zoneId=67,name="Krolmir, Hammer of Storms",level=80,minLevel=77,giver="3",giverType="NPC",giverId=29445,ender="3",enderType="NPC",enderId=30390,rewardNextId=13057,poiX=7452,poiY=-535,wowhead="https://www.wowhead.com/wotlk/quest=13010",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="One task remains before I can reclaim my home at the Terrace of the Makers.$b$bKrolmir must be found.$b$bOn that fateful day, I threw it to the earth with all the power and rage I possessed. A mighty explosion followed.$b$bI've thought it lost for these many years, but now I must be certain.$b$bReturn to King Jokkum and discover what, if anything, he knows of my hammer's fate.",logDesc="Thorim wants you to talk to King Jokkum in Dun Niffelem and discover what he knows of Krolmir.",choiceRewards={{id=42793,qty=1},{id=42806,qty=1},{id=42818,qty=1},{id=42835,qty=1}}} end
if not DB[13011] then DB[13011]={id=13011,zoneId=67,name="Jormuttar is Soo Fat...",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30105,ender="3",enderType="NPC",enderId=30105,poiX=7346,poiY=-2813,wowhead="https://www.wowhead.com/wotlk/quest=13011",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I have an opportunity that will help you to gain approval with my people, provided you prevail.$b$bThe jormungar are a nuisance best dealt with quickly. If given any quarter, they breed like hares and spread like fire.$b$bThey have appeared southwest of here, in the Hibernal Cavern. If their spawnmother is not slain soon, they will gain a foothold in our region.$b$bShe cannot refuse food. Take this knife and get the flank of a bear corpse from their cave. Place it near her crater and kill her as she feeds.",logDesc="King Jokkum in Dun Niffelem wants you to slay Jormuttar in Hibernal Cavern."} end
if not DB[13012] then DB[13012]={id=13012,zoneId=-366,name="Sardis the Elder",level=-1,minLevel=1,giver="Elder Sardis",giverType="NPC",giverId=30348,ender="Elder Sardis",enderType="NPC",enderId=30348,poiX=2377,poiY=5164,wowhead="https://www.wowhead.com/wotlk/quest=13012",image="assets/images/quests/placeholder.png",rewards={{id=21100,qty=1}}} end
