if not DB[13014] then DB[13014]={id=13014,zoneId=-366,name="Morthie the Elder",level=-1,minLevel=1,giver="Elder Morthie",giverType="NPC",giverId=30358,ender="Elder Morthie",enderType="NPC",enderId=30358,poiX=3485,poiY=1963,wowhead="https://www.wowhead.com/wotlk/quest=13014",image="assets/images/quests/placeholder.png",rewards={{id=21100,qty=1}}} end
