if not DB[13034] then DB[13034]={id=13034,zoneId=67,name="The Witness and the Hero",level=80,minLevel=77,giver="Xarantaur",giverType="NPC",giverId=30381,ender="Xarantaur",enderType="NPC",enderId=30381,poiX=7760,poiY=-2836,wowhead="https://www.wowhead.com/wotlk/quest=13034",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="When I began my travels in Northrend, I visited the Borean Tundra and met the taunka for the first time. There, Wind Tamer Barah told me the tale of Stormhoof and his battle against the North Wind, their people's ancient enemy.$B$BI set out for the Storm Peaks to learn more of this hero, but strangely, the people of Tunka'lo seem to know nothing of him.$B$BPerhaps the camp's own records will give us greater insight. Find and read the history scrolls kept throughout the camp, then tell me what you learned.",logDesc="Xarantaur, at Camp Tunka'lo, wants you to read the First History Scroll, the Second History Scroll, and the Third History Scroll."} end
if not DB[13035] then DB[13035]={id=13035,zoneId=67,name="Loken's Lackeys",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30295,ender="3",enderType="NPC",enderId=30295,poiX=7762,poiY=-2160,wowhead="https://www.wowhead.com/wotlk/quest=13035",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The attack on the Terrace of the Makers was not a half-hearted move on my brother's behalf.  He sent a legion of iron dwarves and some of his most powerful lieutenants.$B$BUse the Horn of the Peaks to call the earthen to your side and defeat Loken's servants.$B$BYou'll find the giant, Eisenfaust, inside the Hall of the Shaper to the north.  You'll find the others deeper inside the Terrace of the Makers, beyond the stairs to the northwest.",logDesc="Thorim wants you to slay Eisenfaust inside the Hall of the Shaper and Halefnir the Windborn and Duronn the Runeforged in the Terrace of the Makers."} end
if not DB[13036] then DB[13036]={id=13036,zoneId=210,name="Honor Above All Else",level=78,minLevel=77,giver="Highlord Tirion Fordring",giverType="NPC",giverId=28179,ender="Crusade Commander Entari",enderType="NPC",enderId=30223,rewardNextId=13008,poiX=6256,poiY=-41,wowhead="https://www.wowhead.com/wotlk/quest=13036",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Long has been the path to our salvation, young $c. We have fought across continents, worlds even, to reach this point. Now we face our greatest challenge: the destruction of the Lich King and his Scourge.$B$BAlas, we fight this battle divided. The Horde and Alliance are in the throes of war and will lend us no support. We must remain unyielding in our cause! For what choice have we to do otherwise?$B$BDo you join the cause? Lend us your strength, $c! My commander, Entari, awaits you at his post.",logDesc="Report to Crusade Commander Entari at the Argent Vanguard in Icecrown."} end
if not DB[13037] then DB[13037]={id=13037,zoneId=67,name="Memories of Stormhoof",level=80,minLevel=77,giver="Xarantaur",giverType="NPC",giverId=30381,ender="Xarantaur",enderType="NPC",enderId=30381,poiX=7760,poiY=-2836,wowhead="https://www.wowhead.com/wotlk/quest=13037",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="When the bronze dragonflight gifted me with immortality and set me on the path of the witness, Nozdormu entrusted me with the Lorehammer.$B$BThe hammer's reaction to your findings means that time has gone awry here and it is our duty to restore the true timeline.$B$BWe must find it. To the northwest is Frostfloe Deep, ancient burial cave of the warriors of Tunka'lo. Seek out the spirit of Chieftain Swiftspear, Stormhoof's brother. Ask him what he remembers of his brother's battle against the North Wind.",logDesc="Speak with Chieftain Swiftspear in Frostfloe Deep, then return to Xarantaur at Camp Tunka'lo."} end
if not DB[13038] then DB[13038]={id=13038,zoneId=67,name="Distortions in Time",level=80,minLevel=77,giver="Chieftain Swiftspear",giverType="NPC",giverId=30395,ender="Xarantaur",enderType="NPC",enderId=30381,poiX=8349,poiY=-2509,wowhead="https://www.wowhead.com/wotlk/quest=13038",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="This, the tomb of Tunka'lo's warriors, is supposed to be a serene place, free from the terror of the elements.$B$BFrostfloe Deep has been invaded by a strange force, one that disturbs the spirits of the fallen and blurs my memories of my own life.$B$BIt's as though our deeds and memories are being erased from history.$B$BIn life, this totem was a symbol of my authority. It is the last true link I have to this world. Take it, use it to restore calm to the tomb, and then return it to Camp Tunka'lo.",logDesc="Use the Chieftain's Totem to close 4 Frostfloe Rifts, then bring the totem to Xarantaur at Camp Tunka'lo."} end
if not DB[13039] then DB[13039]={id=13039,zoneId=210,name="Defending The Vanguard",level=78,minLevel=77,giver="Crusader Lord Dalfors",giverType="NPC",giverId=30224,ender="Crusader Lord Dalfors",enderType="NPC",enderId=30224,poiX=6259,poiY=47,wowhead="https://www.wowhead.com/wotlk/quest=13039",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="We can't keep this pace up, $g lad:lass;. Once the breach was blown, the floodgates opened up. The Scourge have been pourin' through ever since with no end in sight!$B$BWe need every able bodied man and woman to help keep the tide of evil at bay. Get out there and do yer share, friend. Kill as many of those monsters as ye can!",logDesc="Crusader Lord Dalfors at the Argent Vanguard in Icecrown has asked that you kill 15 Forgotten Depths Nerubians.",choiceRewards={{id=43828,qty=1},{id=43841,qty=1},{id=43829,qty=1},{id=43831,qty=1}}} end
if not DB[13040] then DB[13040]={id=13040,zoneId=210,name="Curing The Incurable",level=78,minLevel=77,giver="Father Gustav",giverType="NPC",giverId=30226,ender="Father Gustav",enderType="NPC",enderId=30226,poiX=6222,poiY=-3,wowhead="https://www.wowhead.com/wotlk/quest=13040",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="The number of injured soldiers rises with each passing day. They are being stricken by some type of toxin that we have never before seen. Whatever it is that these Nerubians hold within their venom glands is lethal and incurable! So far we've only been able to slow down the poison flowing through the victim's bodies. We must devise a cure!$B$BVenture northwest to the valley outside of the Vanguard and slay the Forgotten Depths Nerubians. Recover their venom glands and bring them to me.",logDesc="Father Gustav at the Argent Vanguard in Icecrown has asked that you bring him 10 Forgotten Depths Venom Sacs.",choiceRewards={{id=33447,qty=5},{id=33448,qty=5}}} end
if not DB[13041] then DB[13041]={id=13041,zoneId=-373,name="Finish the Shipment",level=-1,minLevel=65,giver="Timothy Jones",giverType="NPC",giverId=28701,ender="Timothy Jones",enderType="NPC",enderId=28701,poiX=5871,poiY=715,wowhead="https://www.wowhead.com/wotlk/quest=13041",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="I'm glad you showed up!   A shipment of Glowing Ivory Figurines needs to go out to Undermine right now, and I am still short a Chalcedony to complete an eye for the last one.$B$BBring me one and a Dalaran Jeweler's token will be yours.",logDesc="Bring a Chalcedony to Timothy Jones in Dalaran.",rewards={{id=41596,qty=1}}} end
if not DB[13042] then DB[13042]={id=13042,zoneId=210,name="Deep in the Bowels of The Underhalls",level=80,minLevel=77,giver="The Bone Witch",giverType="NPC",giverId=30232,ender="The Bone Witch",enderType="NPC",enderId=30232,poiX=7631,poiY=3405,wowhead="https://www.wowhead.com/wotlk/quest=13042",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Deep in the bowels of The Underhalls to the northeast, a mad scientist known as Dr. Terrible is up to something befitting his name.$B$BThe doctor has been given dispensation by the Lich King to perform experiments upon the vargul -- the vrykul who fall in battle and are found unworthy, and then turned into Scourge.$B$BWe must put an end to his work, but my auguries have been unable to find him. He does, however, have an assistant.$B$BBeat the information out of his apprentice, and then dispose of the body.",logDesc="The Bone Witch in Njorndar Village has asked you to beat information out of Apprentice Osterkilgr concerning what Dr. Terrible is truly up to.$B$BYou are then to slay the apprentice."} end
if not DB[13043] then DB[13043]={id=13043,zoneId=210,name="The Sum is Greater than the Parts",level=80,minLevel=77,ender="The Bone Witch",enderType="NPC",enderId=30232,rewardNextId=13091,wowhead="https://www.wowhead.com/wotlk/quest=13043",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Opening the tome, you notice all manner of disgusting illustrations concerning the construction of what the doctor refers to as \"the ultimate weapon\"!$B$BClearly the prototype, Nergeld, is the massive flesh giant standing still at the end of the nearby Hall of Horrors.$B$BIf an army of those things were to be constructed, then it would mean doom. The only way to ensure that doesn't happen is to slay Dr. Terrible!$B$BPerhaps if you were to take control of the construct, the doctor would reveal himself?",logDesc="Mount and take control of Nergeld. Defend it from the denizens of the Hall of Horrors until Dr. Terrible shows himself.$B$BUse Nergeld to slay the doctor, and then return to The Bone Witch in Njorndar Village.",choiceRewards={{id=43861,qty=1},{id=43909,qty=1},{id=43979,qty=1},{id=43944,qty=1}}} end
if not DB[13044] then DB[13044]={id=13044,zoneId=210,name="If There Are Survivors...",level=78,minLevel=77,giver="Crusade Commander Entari",giverType="NPC",giverId=30223,ender="Penumbrius",enderType="NPC",enderId=30227,rewardNextId=13045,poiX=6256,poiY=-18,wowhead="https://www.wowhead.com/wotlk/quest=13044",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Across the Valley of Echoes, west of here, and through the Breach, is the first Scourge encampment in Icecrown known as Scourgeholme. We fought a good fight at Scourgeholme and killed many Scourge, but in the end we were forced to retreat. Many soldiers were left behind - their fate unknown.$B$BIf there are survivors, we must attempt a rescue. Directly down this southeastern path is Penumbrius, ally of the bronze dragonflight and caretaker of the proto-brood. Seek him out and ask for his assistance.",logDesc="Speak with Penumbrius at the Argent Vanguard in Icecrown."} end
if not DB[13045] then DB[13045]={id=13045,zoneId=210,name="Into The Wild Green Yonder",level=78,minLevel=77,giver="Penumbrius",giverType="NPC",giverId=30227,ender="Highlord Tirion Fordring",enderType="NPC",enderId=28179,rewardNextId=13070,poiX=6123,poiY=-13,wowhead="https://www.wowhead.com/wotlk/quest=13045",image="assets/images/quests/placeholder.png",xpDiff=6,money=136000,desc="We will do all that we can to assist you, $N. The proto-brood have volunteered to fly you across the Breach and into Scourgeholme. Rescue any captured Argent Crusaders that you find. Return them immediately to the Vanguard Infirmary, located at the center of this base.$B$BChoose one of the Argent Skytalons in the pen behind me and go!$B$BScourgeholme is located northwest, across the Valley of Echoes, through the great Breach.",logDesc="Rescue 3 Captured Argent Crusaders from Scourgeholme and drop them off at the Vanguard Infirmary at the center of the Argent Vanguard. Report to Highlord Tirion Fordring should you succeed."} end
if not DB[13046] then DB[13046]={id=13046,zoneId=67,name="Feeding Arngrim",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13046",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Arngrim's hunger was legendary.$b$bEven in death, his expression is one of famished yearning. You find that just looking at him is making your stomach growl.$b$bIt is said that throughout his life he was never truly sated, and that there was absolutely nothing he wouldn't eat. You wonder to yourself if there might be a way to feed the old king.$b$bNo sooner does the thought enter your mind than one of the massive frozen teeth falls from Arngrim's head, bounces off of his beard and lands in your hand.",logDesc="You are to feed Arngrim 5 Disembodied Jormungar, then return to Arngrim's frozen image in Dun Niffelem.$b$bYou must go to the Valley of Ancient Winters and use Arngrim's Tooth on the Roaming Jormungar there. Once they have become disembodied, you must fight them until they are weakened."} end
if not DB[13047] then DB[13047]={id=13047,zoneId=67,name="The Reckoning",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30295,ender="3",enderType="NPC",enderId=30105,rewardNextId=13108,poiX=7762,poiY=-2160,wowhead="https://www.wowhead.com/wotlk/quest=13047",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="Loken killed my wife, turned my followers and me against each other.  He took away everything I had, but today... that changes.$B$BToday we reclaim our sacred grounds.  Today... Loken dies.$B$BMeet me on the bridge near the Temple of Wisdom, just southwest of Ulduar.  I will finish this one way or the other.$B$BI need you there as a witness.  You will not aid me -- this is personal.$B$BAfter it's done, send word to Jokkum, King of the Frost Giants.  He's a good friend and will know what to do.",logDesc="Meet Thorim near the Temple of Wisdom.  Report the outcome of the fight to King Jokkum in Dun Niffelem.",choiceRewards={{id=43210,qty=1},{id=43211,qty=1},{id=43212,qty=1},{id=43213,qty=1}}} end
if not DB[13048] then DB[13048]={id=13048,zoneId=67,name="Where Time Went Wrong",level=80,minLevel=77,giver="Xarantaur",giverType="NPC",giverId=30381,ender="Xarantaur",enderType="NPC",enderId=30381,poiX=7760,poiY=-2836,wowhead="https://www.wowhead.com/wotlk/quest=13048",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Lorehammer can help us correct the damage to the timeline, but only if we can discover where the history was originally corrupted.$B$BFrom Chieftain Swiftspear and your findings at Frostfloe Deep, we know that the change happened around the time of Stormhoof's death.$B$BNow, you must go to the Howling Hollow, north of the camp, and inspect the gravesites the North Wind's minions have already destroyed. The Lorehammer will react to artifacts from Stormhoof's era and attune itself to the proper time.",logDesc="Use the Lorehammer on Taunka Relics to attune it to the time of Stormhoof. Once it has been attuned to 6 relics from the time of Stormhoof, return to Xarantaur at Camp Tunka'lo."} end
if not DB[13049] then DB[13049]={id=13049,zoneId=67,name="The Hero's Arms",level=80,minLevel=77,giver="Xarantaur",giverType="NPC",giverId=30381,ender="Xarantaur",enderType="NPC",enderId=30381,poiX=7760,poiY=-2836,wowhead="https://www.wowhead.com/wotlk/quest=13049",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Not all of the camp's records have yet been corrupted. My staff has helped me to find those records which reflect the true timeline.$B$BThey agree that Stormhoof was given a burial of honor among the village elders on the bottom level of the Howling Hollow, to the north.$B$BMost of the graves there have already been destroyed, their contents taken as trophies by the North Wind's subjects. Go to the hollow and see if you can recover Stormhoof's spear and armor from the scions of storm who have claimed them.",logDesc="Recover Stormhoof's Spear and Stormhoof's Mail and return them to Xarantaur at Camp Tunka'lo."} end
if not DB[13050] then DB[13050]={id=13050,zoneId=67,name="Veranus",level=80,minLevel=77,giver="3",giverType="NPC",giverId=29445,ender="3",enderType="NPC",enderId=29445,rewardNextId=13051,poiX=7452,poiY=-535,wowhead="https://www.wowhead.com/wotlk/quest=13050",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="If I'm to launch an attack against my brother's army, I'm going to need some way to get around.$B$BI released my riding drake back into the wild years ago.  Veranus was magnificent.  The leader of her own brood -- to whom she has now returned.$B$BFinding her will be hard, but perhaps there's a way.  She keeps her old empty nest out of pure pride.  She's a broodmother in name only, for she is beyond the age of breeding.$B$BBring me small eggs from the other nests near Brunnhildar.  I think I've an idea.",logDesc="Thorim, at the Temple of Storms, wants you to obtain 5 Small Proto-Drake Eggs from the peaks near Brunnhildar Village."} end
if not DB[13051] then DB[13051]={id=13051,zoneId=67,name="Territorial Trespass",level=80,minLevel=77,giver="3",giverType="NPC",giverId=29445,ender="3",enderType="NPC",enderId=29445,rewardNextId=13010,poiX=7452,poiY=-535,wowhead="https://www.wowhead.com/wotlk/quest=13051",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Veranus is proud like no other beast I've known.  She still keeps her old nest and makes sure none of the younger proto-drakes takes it over.$B$BTake the eggs you've collected and place them on her nest.  You'll find it atop a small peak, directly southeast of here.$B$BI should be able to get control of her before she kills you in a fit of rage.  Hopefully.",logDesc="Place the Stolen Proto-Dragon Eggs on top of the Broodmother's Nest and return to Thorim at the Temple of Storms.",choiceRewards={{id=42859,qty=1},{id=42857,qty=1},{id=42858,qty=1},{id=42860,qty=1},{id=42848,qty=1}}} end
if not DB[13052] then DB[13052]={id=13052,zoneId=3711,name="Aerial Surveillance",level=77,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13052",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You did a good job helping Wes with getting that flying machine back up and running.$B$BIf you'd like to help us further, there is an unusual weather pattern coming in from the northwest.  I have a pilot ready to work for me, but I'm afraid he needs a copilot.$B$BIf you think you're up to it, you can take the flight to Lakeside Landing.  Tell Vic I sent you.",logDesc="Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there."} end
if not DB[13053] then DB[13053]={id=13053,zoneId=67,name="Looking for Survivors",level=77,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13053",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Gretchen Fizzlespark wants to use my flying machine to look for survivors from her expedition.  Apparently she thinks they're being held prisoner in the village to the north.$B$BThe only problem is I don't have a co-pilot.  If you're willing to take it on, I'd be more than happy to teach you a move or two.$B$BWhat do you say, $N?  Deal?",logDesc="Help Zak Wobblesprocket complete the Test Flight."} end
if not DB[13054] then DB[13054]={id=13054,zoneId=67,name="The Missing Tracker",level=80,minLevel=77,giver="Bloodguard Lorga",giverType="NPC",giverId=30247,ender="Tracker Val'zij",enderType="NPC",enderId=30469,rewardNextId=13055,poiX=7870,poiY=-750,wowhead="https://www.wowhead.com/wotlk/quest=13054",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="I can't in good conscience send you to the worg cave without warning you that the previous person we sent there hasn't returned.$B$BWe're prepared for the worst, but perhaps there's a chance that he's alive.  We'd appreciate it if you helped him return -- Tracker Val'zij is one of the only hunters we have.",logDesc="Look for Tracker Val'zij inside Gimorak's Den, southeast of the Grom'arsh Crash Site."} end
if not DB[13055] then DB[13055]={id=13055,zoneId=67,name="Cave Medicine",level=80,minLevel=77,giver="Tracker Val'zij",giverType="NPC",giverId=30469,ender="Tracker Val'zij",enderType="NPC",enderId=30469,rewardNextId=13056,poiX=7620,poiY=-1609,wowhead="https://www.wowhead.com/wotlk/quest=13055",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="It's good to see a friendly face.  Might be the last one I see.$B$BOne of those jormungar stung me with some sort of toxin before I managed to get away.  I can feel my whole body getting numb, mon.$B$BI'm going to need a toxin gland to make an antidote.  I will also need some of the cave mushrooms that grow here... they'll slow the toxin down.$B$BHurry, please.  I don't have much time.  ",logDesc="Tracker Val'zij, at Gimorak's Den, wants you to obtain 1 Jormungar Toxin Gland and 8 Cave Mushrooms."} end
if not DB[13056] then DB[13056]={id=13056,zoneId=67,name="There's Always Time for Revenge",level=80,minLevel=77,giver="Tracker Val'zij",giverType="NPC",giverId=30469,ender="Tracker Val'zij",enderType="NPC",enderId=30469,poiX=7620,poiY=-1609,wowhead="https://www.wowhead.com/wotlk/quest=13056",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I should manage for now, $N.  There is one favor I'd like to ask, though.$B$BI would never had fallen to one of these worms, but my wind serpent, Heesha, was killed by the meanest worg I've seen in some time.$B$BDon't worry about me now, I'll feel better when that worg is breathing no more.  You should find him deeper in the cave.",logDesc="Tracker Val'zij wants you to slay Gimorak inside Gimorak's Den.",choiceRewards={{id=42789,qty=1},{id=42802,qty=1},{id=42814,qty=1},{id=42833,qty=1}}} end
if not DB[13057] then DB[13057]={id=13057,zoneId=67,name="The Terrace of the Makers",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30390,ender="3",enderType="NPC",enderId=30295,wowhead="https://www.wowhead.com/wotlk/quest=13057",image="assets/images/quests/placeholder.png",xpDiff=3,desc="It is time, $N.  I am prepared to face Loken now.$B$BLet us make our way to the Terrace of the Makers and face my brother's forces.  The fool will regret ever crossing me.",logDesc="Find Thorim at the southeastern edge of the Terrace of the Makers, just northwest of Dun Niffelem."} end
if not DB[13058] then DB[13058]={id=13058,zoneId=67,name="Changing the Wind's Course",level=80,minLevel=77,giver="Xarantaur",giverType="NPC",giverId=30381,ender="Xarantaur",enderType="NPC",enderId=30381,poiX=7760,poiY=-2836,wowhead="https://www.wowhead.com/wotlk/quest=13058",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="At last, we have all that we need to right the wrongs of the North Wind and its followers. You have attuned the Lorehammer to Stormhoof's time and his persona.$B$BTake the hammer again, head to the Temple of Life in the plains to the northwest. Use the hammer to assume the role of Stormhoof. Face the North Wind as Stormhoof, but realize that for the timeline to be restored, Stormhoof must die as the North Wind weakens.$B$BThen, you must find and use the Horn of Elemental Fury to destroy the North Wind.",logDesc="Use the Lorehammer to travel back in time and face the North Wind as Stormhoof. When Stormhoof falls and drops the Horn of Elemental Fury, use it to finish off the North Wind, and then return to Xarantaur at Camp Tunka'lo.",choiceRewards={{id=43186,qty=1},{id=43188,qty=1},{id=43185,qty=1},{id=43187,qty=1}}} end
if not DB[13059] then DB[13059]={id=13059,zoneId=210,name="Revenge for the Vargul",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30406,ender="3",enderType="NPC",enderId=30406,poiX=8044,poiY=3179,wowhead="https://www.wowhead.com/wotlk/quest=13059",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="I've been praying to The Lady of the Sword for one to come and strike down my enemy. Thane Illskar must pay for what he did to me!$B$BI was the champion of Thane Ufrang the Mighty. During my fight for ascendance in Valhalas, Illskar sabotaged me with dark magic, causing me to lose and be reduced to this.$B$BThe thane and his champions can be found below in The Circle of Suffering. Challenge him on my behalf. Defeat him.$B$BMake him know the suffering that I know!",logDesc="Bethod Feigr in The Underhalls wants you to throw down his sword to challenge Thane Illskar and then kill him in The Circle of Suffering.",choiceRewards={{id=43862,qty=1},{id=43908,qty=1},{id=43978,qty=1},{id=43943,qty=1},{id=43924,qty=1}}} end
if not DB[13060] then DB[13060]={id=13060,zoneId=67,name="When All Else Fails",level=78,minLevel=77,giver="Ricket",giverType="NPC",giverId=29428,ender="Olut Alegut",enderType="NPC",enderId=30472,poiX=6153,poiY=-1069,wowhead="https://www.wowhead.com/wotlk/quest=13060",image="assets/images/quests/placeholder.png",xpDiff=1,money=6800,desc="So...  so I don't think we're going to be getting a good foothold in those mountains.$B$BTrust me, I'm not one to give up easily... but between freezing engines, nasty vrykul women, territorial dragon want-to-bes and the half a dozen other nasties settled in the area, this just ain't happening.$B$BDon't let that dissuade you though! Just because we can't get a foothold doesn't mean we won't get you there... one-way trips are pretty simple when you get down to it.$B$B<Ricket nods at some nearby rockets.>",logDesc="Speak to Ricket to make use of Ricket's D16 Propelled Delivery Device to enter further into Storm Peaks."} end
if not DB[13061] then DB[13061]={id=13061,zoneId=67,name="Prepare for Glory",level=79,minLevel=77,giver="Astrid Bjornrittar",giverType="NPC",giverId=29839,ender="Lok'lira the Crone",enderType="NPC",enderId=29975,rewardNextId=13062,poiX=6793,poiY=-1696,wowhead="https://www.wowhead.com/wotlk/quest=13061",image="assets/images/quests/placeholder.png",xpDiff=1,money=7200,desc="This is it then.  I'll take care of your bear now, you won't be needing her.  The great Drakkensryd will be your next challenge.$B$BSay goodbye to your friends and leave your affairs in order, for you will return victorious... or you won't return at all.",logDesc="Speak to Lok'lira the Crone in Brunnhildar Village."} end
if not DB[13062] then DB[13062]={id=13062,zoneId=67,name="Lok'lira's Parting Gift",level=80,minLevel=77,giver="Lok'lira the Crone",giverType="NPC",giverId=29975,ender="Gretta the Arbiter",enderType="NPC",enderId=29796,rewardNextId=12886,poiX=6922,poiY=-1535,wowhead="https://www.wowhead.com/wotlk/quest=13062",image="assets/images/quests/placeholder.png",xpDiff=2,desc="You've been a great ally, $N.  Now comes your true test.  You will need skill, courage and a little luck.$B$B<Lok'lira attaches a thin strand of hair to yours.>$B$BYou cannot fail now sister.  Speak to Gretta the Arbiter.  She'll see you on your way.",logDesc="Speak to Gretta the Arbiter in Brunnhildar Village."} end
if not DB[13063] then DB[13063]={id=13063,zoneId=67,name="Deemed Worthy",level=80,minLevel=77,giver="3",giverType="NPC",giverId=29592,ender="Astrid Bjornrittar",enderType="NPC",enderId=29839,rewardNextId=12900,poiX=7082,poiY=-1938,wowhead="https://www.wowhead.com/wotlk/quest=13063",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="You have succeeded where many have failed, sister. Whether it be by strength and courage or mere luck remains to be seen.$b$bGo back to the village and seek out Astrid Bjornrittar. Tell her of your accomplishments. But be warned. She is not easily impressed.",logDesc="Brijana wants you to go to Brunnhildar Village and speak with Astrid Bjornrittar."} end
if not DB[13064] then DB[13064]={id=13064,zoneId=67,name="Sibling Rivalry",level=80,minLevel=77,giver="3",giverType="NPC",giverId=29445,ender="3",enderType="NPC",enderId=29445,rewardNextId=12915,poiX=7452,poiY=-535,wowhead="https://www.wowhead.com/wotlk/quest=13064",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Sif? Is it truly you?$b$bNo? A $r? But for a moment....$b$bEnough of this! The visions of my Sif have tormented me for far too long. It is time for me to avenge her, and to bring honor to her memory.$b$bMy brother must pay!",logDesc="Thorim wants you to listen to his story."} end
if not DB[13065] then DB[13065]={id=13065,zoneId=-366,name="Ohanzee the Elder",level=-1,minLevel=1,giver="Elder Ohanzee",giverType="NPC",giverId=30537,ender="Elder Ohanzee",enderType="NPC",enderId=30537,poiX=1698,poiY=752,wowhead="https://www.wowhead.com/wotlk/quest=13065",image="assets/images/quests/placeholder.png",rewards={{id=21100,qty=1}}} end
if not DB[13066] then DB[13066]={id=13066,zoneId=-366,name="Yurauk the Elder",level=-1,minLevel=1,giver="Elder Yurauk",giverType="NPC",giverId=30535,ender="Elder Yurauk",enderType="NPC",enderId=30535,poiX=947,poiY=753,wowhead="https://www.wowhead.com/wotlk/quest=13066",image="assets/images/quests/placeholder.png",rewards={{id=21100,qty=1}}} end
if not DB[13067] then DB[13067]={id=13067,zoneId=-366,name="Chogan'gada the Elder",level=-1,minLevel=1,giver="Elder Chogan'gada",giverType="NPC",giverId=30538,ender="Elder Chogan'gada",enderType="NPC",enderId=30538,poiX=474,poiY=-523,wowhead="https://www.wowhead.com/wotlk/quest=13067",image="assets/images/quests/placeholder.png",rewards={{id=21100,qty=1}}} end
if not DB[13068] then DB[13068]={id=13068,zoneId=210,name="A Tale of Valor",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31044,ender="Crusader Bridenbrad",enderType="NPC",enderId=30562,rewardNextId=13072,poiX=6427,poiY=440,wowhead="https://www.wowhead.com/wotlk/quest=13068",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Perhaps you've heard the praises for our missing hero?$B$BCrusader Bridenbrad was in the Broken Front aiding the attack against the Scourge when the undead army came down upon them. The many men of that allied force scattered, but Bridenbrad alone returned and dragged more than a dozen men to safety, one by one through the carnage.$B$B$C, he has not returned since. He was spotted heading to the far northeast, towards the Silent Vigil. Bring him back to me that I might honor him for his valor.",logDesc="Highlord Tirion Fordring at Crusaders' Pinnacle has requested that you locate the hero, Crusader Bridenbrad at the Silent Vigil, in northeast Icecrown.  His fire pit will likely be the most obvious indication of his location from the air."} end
if not DB[13069] then DB[13069]={id=13069,zoneId=210,name="Shoot 'Em Up",level=80,minLevel=77,giver="The Leaper",giverType="NPC",giverId=30074,ender="The Leaper",enderType="NPC",enderId=30074,poiX=8380,poiY=2718,wowhead="https://www.wowhead.com/wotlk/quest=13069",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Jotunheim has aerial defenses, both in terms of proto-drake riders and harpoon guns. They've concentrated these on their northern and western facings where they are most vulnerable.$B$BLet's use their defenses against them!$B$B<The Leaper pierces you with his single eye and cackles maniacally.>$B$BTake control of a harpoon gun on the platforms that overhang the cliffs on either side of Valhalas to the southwest. Take out the proto-drakes and their riders. Shoot 'em up!",logDesc="The Leaper at The Shadow Vault wants you to use a Jotunheim Rapid-Fire Harpoon to shoot down 15 Jotunheim Proto-Drakes and their riders."} end
if not DB[13070] then DB[13070]={id=13070,zoneId=210,name="A Cold Front Approaches",level=78,minLevel=77,giver="Highlord Tirion Fordring",giverType="NPC",giverId=28179,ender="Siegemaster Fezzik",enderType="NPC",enderId=30657,rewardNextId=13086,poiX=6256,poiY=-41,wowhead="https://www.wowhead.com/wotlk/quest=13070",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The chill of death stirs in the west, threatening to freeze our hearts and souls to this wasteland and bind us to its dark master. We will stand and we will fight!$B$BThe preparations have begun. Report to Siegemaster Fezzik at the front gate for your assignment.",logDesc="Report to Siegemaster Fezzik at the Argent Vanguard in Icecrown."} end
if not DB[13071] then DB[13071]={id=13071,zoneId=210,name="Vile Like Fire!",level=80,minLevel=77,giver="Vile",giverType="NPC",giverId=30216,ender="Vile",enderType="NPC",enderId=30216,poiX=8374,poiY=2739,wowhead="https://www.wowhead.com/wotlk/quest=13071",image="assets/images/quests/placeholder.png",xpDiff=5,money=37000,desc="Vile like fire! Vile like proto-drakes!$B$B<The abomination claps its hands excitedly.>$B$BLittle $N go to Jotunheim and steal a pretty proto-drake in Njorndar Village. Make proto-drake make pretty fires on Jotunheim buildings!",logDesc="Vile at The Shadow Vault wants you to steal a Njorndar Proto-Drake and use it to set fire to 8 vrykul buildings in the greater Jotunheim region.$B$BBalargarde Fortress, due to its nature, cannot be set ablaze."} end
if not DB[13072] then DB[13072]={id=13072,zoneId=210,name="A Hero Remains",level=80,minLevel=77,giver="Crusader Bridenbrad",giverType="NPC",giverId=30562,ender="3",enderType="NPC",enderId=31044,rewardNextId=13073,poiX=8140,poiY=436,wowhead="https://www.wowhead.com/wotlk/quest=13072",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I know why you've come... they've sent you to bring me back, but that cannot happen. I carry the plague of undeath, $c, and I'll not share my fate with those near me. No, I shall stay here.$B$BMy only regret lies in what I may become when death grips me. I do not fear death itself, but I loathe to consider serving the traitor, Arthas.$B$BLeave me... and see to it that no one else comes looking. You would do me a great disservice if you were to expose anyone to the plague that I carry.",logDesc="Bring news of Crusader Bridenbrad's fate to Highlord Tirion Fordring at Crusaders' Pinnacle."} end
if not DB[13073] then DB[13073]={id=13073,zoneId=210,name="The Keeper's Favor",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31044,ender="Keeper Remulos",enderType="NPC",enderId=11832,rewardNextId=13074,poiX=6427,poiY=440,wowhead="https://www.wowhead.com/wotlk/quest=13073",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="There are those of this world that tap into power unrestricted by the bounds of our mortal frames - powers of restoration, powers of life, and powers of light.  And Bridenbrad, this is no ordinary man... his valor and devotion shine through. We can only hope that one of these beings will intervene and bring this hero back from a fate worse than death.$B$BGo now and speak to Arch Druid Lilliandra in the Argent Vanguard... request passage to Moonglade and seek the aid of Keeper Remulos.",logDesc="Highlord Tirion Fordring at Crusaders' Pinnacle has requested that you secure passage from Arch Druid Lilliandra and speak to Keeper Remulos in Moonglade."} end
if not DB[13074] then DB[13074]={id=13074,zoneId=210,name="Hope Within the Emerald Nightmare",level=80,minLevel=77,giver="Keeper Remulos",giverType="NPC",giverId=11832,ender="Keeper Remulos",enderType="NPC",enderId=11832,rewardNextId=13075,poiX=7848,poiY=-2216,wowhead="https://www.wowhead.com/wotlk/quest=13074",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="What we need exists only in the emerald dream... acorns that are infused with a powerful restorative magic. Many places in this sacred glade are closely tied with the dream, and my shrine is among them.$B$BI will send you into the dream to recover some of these acorns. Be prepared though $c, for this method of entering the dream is dangerous, and it is very likely you will be beset by nightmares.$B$BRecover a few acorns quickly, and then depart from my shrine or pinch yourself to return to our world.",logDesc="Keeper Remulos at Moonglade has instructed you to enter the emerald dream and recover 3 Emerald Acorns.$B$BLeave the vicinity of the Shrine of Remulos to return to Azeroth."} end
if not DB[13075] then DB[13075]={id=13075,zoneId=210,name="The Boon of Remulos",level=80,minLevel=77,giver="Keeper Remulos",giverType="NPC",giverId=11832,ender="Crusader Bridenbrad",enderType="NPC",enderId=30562,poiX=7848,poiY=-2216,wowhead="https://www.wowhead.com/wotlk/quest=13075",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I shall open a portal to take you back to the druid that brought you here. You and your crusader have my well wishes. I hope that this acorn is able to purify your crusader and save him from the wretched fate of the plague.$B$BFarewell, $r.",logDesc="Return to Crusader Bridenbrad at the Silent Vigil in Icecrown with the Emerald Acorn."} end
if not DB[13076] then DB[13076]={id=13076,zoneId=210,name="Time Yet Remains",level=80,minLevel=77,giver="Crusader Bridenbrad",giverType="NPC",giverId=30562,ender="3",enderType="NPC",enderId=31044,rewardNextId=13077,poiX=8140,poiY=436,wowhead="https://www.wowhead.com/wotlk/quest=13076",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="I feel refreshed... renewed... but the plague still grips me. Not to worry, I am still eternally grateful that you went to such lengths for me, a complete stranger. If nothing else, you've bought me a few more precious hours not plaguing the world as a hideous undead.$B$BThank you, $c. Please extend my thanks to Tirion as well, and let him know that it has been an honor to serve beside him.",logDesc="Return to Highlord Tirion Fordring at Crusaders' Pinnacle with news of Emerald Acorn's effects."} end
if not DB[13077] then DB[13077]={id=13077,zoneId=210,name="The Touch of an Aspect",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31044,ender="3",enderType="NPC",enderId=26917,rewardNextId=13078,poiX=6427,poiY=440,wowhead="https://www.wowhead.com/wotlk/quest=13077",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="The dragon-queen, Alexstrasza, possesses magics over all life. In the past, she has used great fire to incinerate undead and rebirth fresh new life in their place. Perhaps her powers might be able to save our Bridenbrad as well.$B$BAlexstrasza makes her home at Wyrmrest Temple in Dragonblight - please go to her and humbly request her aid on my behalf.",logDesc="Request the aid of Alexstrasza the Life-Binder at Wyrmrest Temple."} end
if not DB[13078] then DB[13078]={id=13078,zoneId=65,name="Dahlia's Tears",level=80,minLevel=77,giver="3",giverType="NPC",giverId=26917,ender="3",enderType="NPC",enderId=26917,rewardNextId=13079,poiX=3531,poiY=271,wowhead="https://www.wowhead.com/wotlk/quest=13078",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="In this dark time, I'll not be the one to abandon a champion of the Light.$B$BWe will need something sacred for this to have a hope of saving your Bridenbrad... a remnant of a devout being that fell victim to this very same plague.$B$BGo now to the sacred soil of the passages outside my Ruby Dragonshrine where the battle is joined. As my Ruby Keepers fly down and set flame to the ground beneath undead feet, you will witness new life grow forth. Among that life are Dahlia's Tears - bring them to me.",logDesc="Alexstrasza the Life-Binder at Wyrmrest Temple has requested that you recover Dahlia's Tears from soil freshly cleansed by a Ruby Keeper's flames."} end
if not DB[13079] then DB[13079]={id=13079,zoneId=210,name="The Boon of Alexstrasza",level=80,minLevel=77,giver="3",giverType="NPC",giverId=26917,ender="Crusader Bridenbrad",enderType="NPC",enderId=30562,poiX=3531,poiY=271,wowhead="https://www.wowhead.com/wotlk/quest=13079",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You must understand, young $r, that cleansing the body in favor of life anew is something well within my grasp... removing the plague of undeath without affecting the body, however, is beyond the scope of the powers that I control.$B$BIf this Bridenbrad is the beacon of light that you profess him to be, perhaps he will endure such a cleansing and thrive, but I cannot state with confidence that this is the salvation that you seek. Take it and go with all of my blessings.",logDesc="Bring the Breath of Alexstrasza to Crusader Bridenbrad at the Silent Vigil in Icecrown."} end
if not DB[13080] then DB[13080]={id=13080,zoneId=210,name="Hope Yet Remains",level=80,minLevel=77,giver="Crusader Bridenbrad",giverType="NPC",giverId=30562,ender="3",enderType="NPC",enderId=31044,rewardNextId=13081,poiX=8140,poiY=436,wowhead="https://www.wowhead.com/wotlk/quest=13080",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="<Bridenbrad raises a hand to you as he catches his breath.>$B$BIt was nearly as painful as it looked, but it was as if I could feel some of the corruption being burnt away from within my body. It seems the plague is not so readily bested though.$B$B$C, thank you for everything that you have done. Your selfless actions have renewed my hope that there is yet great good left within this world - I can depart without fear that darkness will prevail in my absence.$B$BGo now, go with no regrets.",logDesc="Return to Highlord Tirion Fordring at Crusaders' Pinnacle with news of the effects of the Breath of Alexstrasza."} end
if not DB[13081] then DB[13081]={id=13081,zoneId=210,name="The Will of the Naaru",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31044,ender="A'dal",enderType="NPC",enderId=18481,rewardNextId=13082,poiX=6427,poiY=440,wowhead="https://www.wowhead.com/wotlk/quest=13081",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="I appreciate everything that you have done for us, $n. I have one last errand for you... one last gleaming hope for a paladin who deserves any salvation that we can extend.$B$BGo now to Shattrath and speak to the naaru, A'dal. He has long been a beacon of light and powerful ally to devout paladins. Impart Bridenbrad's story and seek any aid that he might have to offer.$B$BI cannot impress how important it is that you move quickly - I fear our crusader does not have much more time in this world.",logDesc="Request the aid of A'dal at Shattrath City in Terokkar Forest."} end
if not DB[13082] then DB[13082]={id=13082,zoneId=210,name="The Boon of A'dal",level=80,minLevel=77,giver="A'dal",giverType="NPC",giverId=18481,ender="Crusader Bridenbrad",enderType="NPC",enderId=30562,poiX=-1864,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=13082",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I am pleased that you have come to me, $n. I know of Crusader Bridenbrad, and of your travels in hope of saving him. Bridenbrad's valor has sparked remarkable selflessness in you, and this is a miracle unto itself.$B$BThe Light will take care of its own. I will extend my blessing to Bridenbrad and he shall not endure the corruption of undeath. I shall return you to Dalaran, and you shall return to him. Know that I remain with you.",logDesc="Return to Crusader Bridenbrad at the Silent Vigil in Icecrown."} end
if not DB[13083] then DB[13083]={id=13083,zoneId=210,name="Light Within the Darkness",level=80,minLevel=77,ender="3",enderType="NPC",enderId=31044,wowhead="https://www.wowhead.com/wotlk/quest=13083",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="<Crusader Bridenbrad's tabard rests in the bottom of the chest, shifting slightly as the howling wind finds its way in.>$B$BTirion will desire this last remnant of the great crusader.",logDesc="Bring Crusader Bridenbrad's Tabard to Highlord Tirion Fordring at Crusaders' Pinnacle.",choiceRewards={{id=44018,qty=1},{id=44041,qty=1},{id=44042,qty=1},{id=44043,qty=1},{id=44039,qty=1}}} end
if not DB[13084] then DB[13084]={id=13084,zoneId=210,name="Vandalizing Jotunheim",level=80,minLevel=77,giver="Duke Lankral",giverType="NPC",giverId=30002,ender="Duke Lankral",enderType="NPC",enderId=30002,poiX=8577,poiY=2643,wowhead="https://www.wowhead.com/wotlk/quest=13084",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Let us see if we can further weaken the resolve of the vrykul, $N.$B$BEach day I wish you to travel to Jotunheim and put their banners to the torch. It may seem a trivial thing, but to see their ancestral home vandalized on a daily basis will demoralize them more than any physical punishment you can inflict.$B$BAt least... it can't hurt.",logDesc="Duke Lankral at The Shadow Vault wants you to burn 10 Vrykul Banners."} end
if not DB[13085] then DB[13085]={id=13085,zoneId=210,name="Vaelen Has Returned",level=80,minLevel=77,giver="Baron Sliver",giverType="NPC",giverId=29343,ender="Vaelen the Flayed",enderType="NPC",enderId=30218,rewardNextId=12982,poiX=8385,poiY=2757,wowhead="https://www.wowhead.com/wotlk/quest=13085",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I just saw that incompetent fool, Vaelen the Flayed, sneak into the vault building.$B$BGo see to it that he rectifies his mistake and returns my death knights to me!",logDesc="Speak with Vaelen the Flayed at The Shadow Vault."} end
if not DB[13086] then DB[13086]={id=13086,zoneId=210,name="The Last Line Of Defense",level=78,minLevel=77,giver="Siegemaster Fezzik",giverType="NPC",giverId=30657,ender="Siegemaster Fezzik",enderType="NPC",enderId=30657,poiX=6249,poiY=75,wowhead="https://www.wowhead.com/wotlk/quest=13086",image="assets/images/quests/placeholder.png",xpDiff=7,desc="I've triggered the base's defenses, $c! Atop each of the Vanguard's four towers is a retractable Argent Crusade cannon, blessed by Father Gustav himself. You'll need to fly up to one of those towers and man a cannon. Use it to destroy the Scourge onslaught that the Lich King has deployed.$B$BJust one warning, the Scourge will undoubtedly send their frost wyrms to lay siege to the towers. Shoot them out of the sky! If they destroy the walls and towers of this base, we're done for!",logDesc="Use an Argent Cannon to destroy 100 Scourge attackers. You must also kill 3 Frostbrood Destroyers.$B$BReturn to Siegemaster Fezzik should you succeed.",choiceRewards={{id=44015,qty=1},{id=44014,qty=1},{id=44013,qty=1}}} end
if not DB[13087] then DB[13087]={id=13087,zoneId=-304,name="Northern Cooking",level=-1,minLevel=65,giver="Brom Brewbaster",giverType="NPC",giverId=26905,ender="Brom Brewbaster",enderType="NPC",enderId=26905,poiX=615,poiY=-4917,wowhead="https://www.wowhead.com/wotlk/quest=13087",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="So what are ya doin' if you dinna have any stew for me.   I got me a HUNGER!   At least bring me some chilled meat so I kin cook me own stew!   If ya do, I kin give ya the recipe so you kin make it for yourself.   NOW GO GET ME SOME MEAT!",logDesc="Bring four chilled meat to Brom Brewbaster at Valgarde.   Chilled meat can be found on any Northrend beast."} end
if not DB[13088] then DB[13088]={id=13088,zoneId=-304,name="Northern Cooking",level=-1,minLevel=65,giver="Rollick MacKreel",giverType="NPC",giverId=26989,ender="Rollick MacKreel",enderType="NPC",enderId=26989,poiX=2148,poiY=5232,wowhead="https://www.wowhead.com/wotlk/quest=13088",image="assets/images/quests/placeholder.png",xpDiff=3,money=22000,desc="We got a lot of new recruits here and these lads are hungry!  If you could go out and get me some chilled meat for stew, I could teach you how to make it for yourself.",logDesc="Bring four chilled meat to Rollick Mackreel at Valiance Keep.   Chilled meat can be found on any Northrend beast."} end
if not DB[13089] then DB[13089]={id=13089,zoneId=-304,name="Northern Cooking",level=-1,minLevel=65,giver="Thomas Kolichio",giverType="NPC",giverId=26953,ender="Thomas Kolichio",enderType="NPC",enderId=26953,poiX=1928,poiY=-6150,wowhead="https://www.wowhead.com/wotlk/quest=13089",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Nothing like a stew made from the living to warm your bones.   Bring me some of the chilled meat that can be found on the wretched beasts of this place, and I shall teach you to make a warm stew.",logDesc="Bring four chilled meat to Thomas Kolichio at Vengeance Landing.   Chilled meat can be found on any Northrend beast."} end
if not DB[13090] then DB[13090]={id=13090,zoneId=-304,name="Northern Cooking",level=-1,minLevel=65,giver="Orn Tenderhoof",giverType="NPC",giverId=26972,ender="Orn Tenderhoof",enderType="NPC",enderId=26972,poiX=2818,poiY=6151,wowhead="https://www.wowhead.com/wotlk/quest=13090",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="The warriors of the Warsong Offensive need food in their bellies to keep their strength up.   If you could bring some chilled meats from the Rhinos or other beasts, I could make them some stew.   I would be willing to teach you the recipe if you were willing.",logDesc="Bring four chilled meat to Orn Tenderhoof at Warsong Hold.   Chilled meat can be found on any Northrend beast."} end
if not DB[13091] then DB[13091]={id=13091,zoneId=210,name="The Art of Being a Water Terror",level=80,minLevel=77,giver="The Bone Witch",giverType="NPC",giverId=30232,ender="The Bone Witch",enderType="NPC",enderId=30232,rewardNextId=13121,poiX=7631,poiY=3405,wowhead="https://www.wowhead.com/wotlk/quest=13091",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The water lock outside my cave is teeming with elementals that the vrykul magi have yet to tame. I am going to teach you a trick for possessing these creatures for a short time, and you will use them to wreak havoc upon Jotunheim!$B$B<The banshee-infested vrykul draws magic in the air and touches a large finger to your forehead.>$B$BGo now and open the gate to the lock. A water terror will rush out and you will possess it to destroy our enemies!",logDesc="The Bone Witch in Njorndar Village wants you to possess a Water Terror and use it to slay 10 vrykul in the greater Jotunheim region.$B$BQualifying vrykul are Jotunheim Sleep-Watchers, Jotunheim Warriors, Mjordin Water Magi, Njorndar Spear-Sisters, and Valhalas Vargul.",choiceRewards={{id=43863,qty=1},{id=43907,qty=1},{id=43977,qty=1},{id=43942,qty=1}}} end
if not DB[13092] then DB[13092]={id=13092,zoneId=210,name="Reading the Bones",level=80,minLevel=77,giver="The Bone Witch",giverType="NPC",giverId=30232,ender="The Bone Witch",enderType="NPC",enderId=30232,poiX=7631,poiY=3405,wowhead="https://www.wowhead.com/wotlk/quest=13092",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="One of the benefits of possessing this creature is that I have access to all of her powers. As a bone witch and rune reader, she has the power to throw the bones and determine one's fate.$B$B<The Bone Witch smirks.>$B$BLucky for you and I that I have it within my power to influence those readings.$B$BBring me the bones of the vrykul that you kill here in Jotunheim and I will toss them to allow you to determine your own fate.",logDesc="The Bone Witch in Njorndar Village has instructed you to collect 15 Vrykul Bones.",choiceRewards={{id=43090,qty=1},{id=43135,qty=1},{id=43094,qty=1},{id=43134,qty=1},{id=43141,qty=1}}} end
if not DB[13093] then DB[13093]={id=13093,zoneId=210,name="Reading the Bones",level=80,minLevel=77,giver="The Bone Witch",giverType="NPC",giverId=30232,ender="The Bone Witch",enderType="NPC",enderId=30232,poiX=7631,poiY=3405,wowhead="https://www.wowhead.com/wotlk/quest=13093",image="assets/images/quests/placeholder.png",choiceRewards={{id=43090,qty=1},{id=43135,qty=1},{id=43094,qty=1},{id=43134,qty=1},{id=43141,qty=1}}} end
if not DB[13094] then DB[13094]={id=13094,zoneId=4265,name="Have They No Shame?",level=71,minLevel=68,giver="Librarian Serrah",giverType="NPC",giverId=26110,ender="Librarian Serrah",enderType="NPC",enderId=26110,poiX=3576,poiY=6640,wowhead="https://www.wowhead.com/wotlk/quest=13094",image="assets/images/quests/placeholder.png",xpDiff=8,money=188000,desc="Archmage Berinand is the Kirin Tor's foremost authority on Malygos. He's spent his life studying the aspect and his behaviors.$b$bRecently, he loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble. I made the mistake of discussing it with a group of Horde adventurers while they were restocking their goods here - and now it's gone!$b$bIt must have been them, $c. Please, follow them into the nexus and recover the book before Berinand comes to recover it.",logDesc="Librarian Serrah wants you to enter the Nexus and recover Berinand's Research.",choiceRewards={{id=43181,qty=1},{id=43182,qty=1},{id=43183,qty=1},{id=43184,qty=1}}} end
if not DB[13095] then DB[13095]={id=13095,zoneId=4265,name="Have They No Shame?",level=71,minLevel=68,giver="Librarian Serrah",giverType="NPC",giverId=26110,ender="Librarian Serrah",enderType="NPC",enderId=26110,poiX=3576,poiY=6640,wowhead="https://www.wowhead.com/wotlk/quest=13095",image="assets/images/quests/placeholder.png",xpDiff=8,money=188000,desc="Archmage Berinand is the Kirin Tor's foremost authority on Malygos. He's spent his life studying the aspect and his behaviors.$b$bRecently, he loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble. I made the mistake of discussing it with a group of Alliance adventurers while they were restocking their goods here - and now it's gone!$b$bIt must have been them, $c. Please, follow them into the nexus and find the book before Berinand comes to recover it from me.",logDesc="Librarian Serrah wants you to enter the Nexus and recover Berinand's Research.",choiceRewards={{id=43181,qty=1},{id=43182,qty=1},{id=43183,qty=1},{id=43184,qty=1}}} end
if not DB[13096] then DB[13096]={id=13096,zoneId=4416,name="Gal'darah Must Pay",level=78,minLevel=74,giver="Tol'mar",giverType="NPC",giverId=30671,ender="Tol'mar",enderType="NPC",enderId=30671,poiX=6906,poiY=-4096,wowhead="https://www.wowhead.com/wotlk/quest=13096",image="assets/images/quests/placeholder.png",xpDiff=8,money=272000,desc="Did ya see it, mon?$b$bIt musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible...$b$bI done took an oath not ta be gettin' involved here. My job be to observe only. But dis cannot stand! Gal'darah must pay!$b$bGo into Gundrak and seek him out. Come back to me when Akali's death been avenged, mon.",logDesc="Tol'mar at Dubra'Jin wants you to slay Gal'darah in Gundrak.",choiceRewards={{id=43164,qty=1},{id=43165,qty=1},{id=43167,qty=1},{id=43168,qty=1}}} end
if not DB[13097] then DB[13097]={id=13097,zoneId=66,name="Unfinished Business",level=78,minLevel=74,giver="3",giverType="NPC",giverId=28401,ender="Tol'mar",enderType="NPC",enderId=30671,rewardNextId=13096,poiX=5747,poiY=-3609,wowhead="https://www.wowhead.com/wotlk/quest=13097",image="assets/images/quests/placeholder.png",xpDiff=3,desc="While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done.$b$bThe greater part of Akali's blood has empowered another, and it is in him that the true danger lies.$b$bQuickly, $n, make your way north of Gundrak to Dubra'Jin and speak with Tol'mar. He will be able to direct you further in this cause.",logDesc="Har'koa wants you to speak with Tol'mar at Dubra'jin."} end
if not DB[13098] then DB[13098]={id=13098,zoneId=4416,name="For Posterity",level=78,minLevel=74,giver="Chronicler Bah'Kini",giverType="NPC",giverId=30676,ender="Chronicler Bah'Kini",enderType="NPC",enderId=30676,poiX=6972,poiY=-4099,wowhead="https://www.wowhead.com/wotlk/quest=13098",image="assets/images/quests/placeholder.png",xpDiff=8,money=272000,desc="Gundrak be doomed, mon.$b$bHistory be repeatin' itself before our eyes. When trolls be turnin' on their own gods, the end be certain. It just be a matter of time.$b$bPerhaps if we can record the events clearly, we might prevent future generations from traveling down da same path.$b$bIf you be havin' the courage, enter Gundrak and search for clues to what brought the Drakkari Empire to such an end as dis.",logDesc="Chronicler Bah'Kini at Dubra'Jin wants you to enter Gundrak and collect 6 Drakkari History Tablets.",choiceRewards={{id=43180,qty=1},{id=43178,qty=1},{id=43179,qty=1},{id=43177,qty=1}}} end
if not DB[13099] then DB[13099]={id=13099,zoneId=66,name="Just Checkin'",level=78,minLevel=74,giver="Chronicler To'kini",giverType="NPC",giverId=28527,ender="Chronicler Bah'Kini",enderType="NPC",enderId=30676,rewardNextId=13098,poiX=5740,poiY=-3595,wowhead="https://www.wowhead.com/wotlk/quest=13099",image="assets/images/quests/placeholder.png",xpDiff=3,desc="There have been fearsome sounds echoing from Gundrak. They have been increasing in volume and frequency of late.$b$bMy long-time student is currently recording events from her post just west of Gundrak. Perhaps you could find the time to check in on her for me?",logDesc="To'kini wants you to speak to Bah'kini at Dubra'Jin."} end
if not DB[13100] then DB[13100]={id=13100,zoneId=-304,name="Infused Mushroom Meatloaf",level=-1,minLevel=65,giver="Katherine Lee",giverType="NPC",giverId=28705,ender="Orton Bennet",enderType="NPC",enderId=29527,poiX=5708,poiY=716,wowhead="https://www.wowhead.com/wotlk/quest=13100",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="We have an important order that needs to go out!  Orton Bennet in Curiosities & Moore needs a mushroom meatloaf.$B$BGet some infused mushrooms found in the Dalaran sewers, chilled meat, and cook them in this meatloaf pan.  When you're done, deliver the cooked meatloaf to Orton.",logDesc="Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.",rewards={{id=43016,qty=1},{id=44113,qty=1}}} end
if not DB[13101] then DB[13101]={id=13101,zoneId=-304,name="Convention at the Legerdemain",level=-1,minLevel=65,giver="Katherine Lee",giverType="NPC",giverId=28705,ender="Arille Azuregaze",enderType="NPC",enderId=29049,poiX=5708,poiY=716,wowhead="https://www.wowhead.com/wotlk/quest=13101",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Arille Azuregaze at the Legerdemain Lounge has a convention coming in and needs a feast pronto!$B$BYou need to provide some Northern Stew and a Jug of Wine from the cheese shop \"One More Glass\" in central Dalaran.  The owner of the cheese shop owes me the wine and you should find it somewhere around the shop.$B$BBring the wine and stews to Arille.",logDesc="Bring 4 Northern Stew that you use your cooking skill to make and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.",rewards={{id=43016,qty=1},{id=44113,qty=1}}} end
if not DB[13102] then DB[13102]={id=13102,zoneId=-304,name="Sewer Stew",level=-1,minLevel=65,giver="Katherine Lee",giverType="NPC",giverId=28705,ender="Ajay Green",enderType="NPC",enderId=29532,poiX=5708,poiY=716,wowhead="https://www.wowhead.com/wotlk/quest=13102",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Ajay Green the innkeeper in the Dalaran sewers needs a vegetable stew for his customers as they are running low on food down there.$B$BCollect 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat.$B$B You can get to the Crystalsong Forest from the portal chamber in the eastern corner of Runeweaver Square.$B$BOnce the vegetable stew is ready, bring it to Ajay.",logDesc="Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot.$B$BOnce it is ready bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.",rewards={{id=43016,qty=1},{id=44113,qty=1}}} end
if not DB[13103] then DB[13103]={id=13103,zoneId=-304,name="Cheese for Glowergold",level=-1,minLevel=65,giver="Katherine Lee",giverType="NPC",giverId=28705,ender="Ranid Glowergold",enderType="NPC",enderId=28718,poiX=5708,poiY=716,wowhead="https://www.wowhead.com/wotlk/quest=13103",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Ranid Glowergold in the Leatherworkers shop in Dalaran has had a sudden craving for wine and cheese.$B$BCollect cheese which is on the shelf at \"One More Glass\" in central Dalaran and half full wine glasses found on tables all over the city.  Pour the wine together into a bottle and serve it with the cheese to Ranid.$B$BWe don't think he will know the difference.",logDesc="Combine the empty cheese platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran.$B$BBring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.",rewards={{id=43016,qty=1},{id=44113,qty=1}}} end
if not DB[13104] then DB[13104]={id=13104,zoneId=210,name="Once More Unto The Breach, Hero",level=78,minLevel=77,giver="3",giverType="NPC",giverId=30677,ender="The Ebon Watcher",enderType="NPC",enderId=30596,poiX=6260,poiY=50,wowhead="https://www.wowhead.com/wotlk/quest=13104",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Vanguard is secure, ally. We have reclaimed the Valley of Echoes and taken down the web walls blocking entry to the Breach. Now is the time to strike at Scourgeholme and establish our presence inside Icecrown. The battlefront moves on!$B$BI have asked the Ebon Watcher for his assistance with our assault upon Scourgeholme. His intimate knowledge of the Scourge will be invaluable in our effort.$B$BGo now and report to him at the tent outside of the Breach, northwest of here.",logDesc="Report to the Ebon Watcher in the Valley of Echoes just outside the Breach."} end
if not DB[13105] then DB[13105]={id=13105,zoneId=210,name="Once More Unto The Breach, Hero",level=78,minLevel=77,giver="3",giverType="NPC",giverId=30677,ender="The Ebon Watcher",enderType="NPC",enderId=30596,poiX=6260,poiY=50,wowhead="https://www.wowhead.com/wotlk/quest=13105",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The Vanguard is secure, ally. We have reclaimed the Valley of Echoes and taken down the web walls blocking entry to the Breach. Now is the time to strike at Scourgeholme and establish our presence inside Icecrown. The battlefront moves on!$B$BI have asked the Ebon Watcher for his assistance with our assault upon Scourgeholme. His intimate knowledge of the Scourge will be invaluable in our effort.$B$BGo now and report to him at the tent outside of the Breach, northwest of here.",logDesc="Report to the Ebon Watcher in the Valley of Echoes just outside the Breach."} end
if not DB[13106] then DB[13106]={id=13106,zoneId=210,name="Blackwatch",level=80,minLevel=77,giver="Baron Sliver",giverType="NPC",giverId=29343,ender="Darkrider Arly",enderType="NPC",enderId=30631,poiX=8385,poiY=2757,wowhead="https://www.wowhead.com/wotlk/quest=13106",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="The Scourge has a large facility called the Fleshwerks, dedicated to producing abominations and flesh giants. If we can shut it down, we can deprive the Lich King of a large component of his armies.$B$BI've sent Darkrider Arly to the area. She has a small base, Blackwatch, on a ridge overlooking the Fleshwerks and to the west of Corp'rethar. I'm told the Argent Crusade is sending someone to coordinate their efforts there, but the darkrider will know what to do. Find and assist her.",logDesc="Speak to Darkrider Arly at Blackwatch in Icecrown."} end
if not DB[13107] then DB[13107]={id=13107,zoneId=-304,name="Mustard Dogs!",level=-1,minLevel=65,giver="Katherine Lee",giverType="NPC",giverId=28705,ender="3",enderType="NPC",enderId=28160,poiX=5708,poiY=716,wowhead="https://www.wowhead.com/wotlk/quest=13107",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Archmage Pentarus likes to watch the occasional game of battle ball and is preparing to go, but needs food for the trip.$B$BYou need to fill his picnic basket with 4 rhino dogs that you cook and then 4 wild mustard that are found in grassy areas of the city.$B$BBring him his picnic basket so he can be ready to go see the big game.",logDesc="Fill the Empty Picnic Basket with 4 Rhino Dogs that you cook with your cooking skill and 4 Wild Mustard that you find in the grassy areas of Dalaran.$B$BBring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran.",rewards={{id=43016,qty=2},{id=44113,qty=1}}} end
if not DB[13108] then DB[13108]={id=13108,zoneId=4272,name="Whatever it Takes!",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30105,ender="3",enderType="NPC",enderId=30105,poiX=7346,poiY=-2813,wowhead="https://www.wowhead.com/wotlk/quest=13108",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="One way or another, Loken shall fall.$b$bIf I have to rip him limb from limb myself, he soon shall pay for his wretched deeds.$b$bShould you meet with him before I do, the honor and glory of his defeat shall be yours.$b$bReturn to me with his lying tongue, and earn my blessing and gratitude.",logDesc="King Jokkum in Dun Niffelem wants you to enter the Halls of Lightning and defeat Loken. You are then to return to King Jokkum with Loken's Tongue.",choiceRewards={{id=42844,qty=1},{id=43207,qty=1},{id=43208,qty=1},{id=43209,qty=1}}} end
if not DB[13109] then DB[13109]={id=13109,zoneId=4272,name="Diametrically Opposed",level=80,minLevel=77,giver="3",giverType="NPC",giverId=30105,ender="3",enderType="NPC",enderId=30105,poiX=7346,poiY=-2813,wowhead="https://www.wowhead.com/wotlk/quest=13109",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="I shall speak plainly to you, little $r. My people have not been the same since our ties with Thorim were severed.$b$bAs their leader, I wish nothing more than for their hearts to be mended and our friendship with the Stormlord to be renewed. In your defeat of Fjorn, a step has been taken down that path. I would have you bring us a step further...$b$bIn the Halls of Lightning, one even greater than Fjorn sits in opposition to our existence. Volkhan will not rest until either he, or we, are no more.",logDesc="King Jokkum at Dun Niffelem wants you to enter the Halls of Lightning and defeat Volkhan.",choiceRewards={{id=43193,qty=1},{id=43194,qty=1},{id=43195,qty=1},{id=43197,qty=1},{id=43198,qty=1}}} end
if not DB[13110] then DB[13110]={id=13110,zoneId=210,name="The Restless Dead",level=78,minLevel=77,giver="Father Gustav",giverType="NPC",giverId=30683,ender="Father Gustav",enderType="NPC",enderId=30683,poiX=6384,poiY=247,wowhead="https://www.wowhead.com/wotlk/quest=13110",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Not all of our soldiers made it out of Scourgeholme. Many were slain and turned into twisted reflections of their former selves. Such is the way of the Scourge. For those damned souls, there is no eternal peace. We must provide their souls rest.$B$BTravel through the Breach into Scourgeholme and slay the skeletal reanimated crusaders. Sprinkle this holy water on their bones so that their spirits may be freed.",logDesc="Father Gustav at the Valley of Echoes in Icecrown wants you to use Holy Water on the corpses of Reanimated Crusaders to free 10 restless souls.",choiceRewards={{id=43833,qty=1},{id=43832,qty=1},{id=43835,qty=1},{id=43834,qty=1}}} end
if not DB[13111] then DB[13111]={id=13111,zoneId=4416,name="One of a Kind",level=78,minLevel=74,giver="Chronicler Bah'Kini",giverType="NPC",giverId=30676,ender="Chronicler Bah'Kini",enderType="NPC",enderId=30676,poiX=6972,poiY=-4099,wowhead="https://www.wowhead.com/wotlk/quest=13111",image="assets/images/quests/placeholder.png",xpDiff=8,money=272000,desc="Lissen, mon.$b$bAt first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'.$b$bWhile dis be true, dere be somethin' special about dese Drakkari. If what I learned be true, den inside Gundrak dere be a special golem - one like nuthin' created before!$b$bYa want adventure, mon? Go inside Gundrak and bring me back a piece from dat golem ta study.",logDesc="Chronicler Bah'Kini at Dubra'Jin wants you to enter Gundrak and recover a piece of the Drakkari Colossus.",choiceRewards={{id=43171,qty=1},{id=43172,qty=1},{id=43173,qty=1},{id=43176,qty=1},{id=43174,qty=1}}} end
if not DB[13112] then DB[13112]={id=13112,zoneId=-304,name="Infused Mushroom Meatloaf",level=-1,minLevel=65,giver="Awilo Lon'gomba",giverType="NPC",giverId=29631,ender="Orton Bennet",enderType="NPC",enderId=29527,poiX=5851,poiY=472,wowhead="https://www.wowhead.com/wotlk/quest=13112",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Orton Bennet in Curiosities & Moore be needin' a mushroom meatloaf.$B$BGet ya some infused mushrooms found in the Dalaran sewers, chilled meat, and cook 'em in the meatloaf pan.  When ye be done, bring that meatloaf to Orton.$B$BIf only de council would let me serve me gnome specialty, I would show dem a real treat!",logDesc="Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.",rewards={{id=43016,qty=1},{id=44113,qty=1}}} end
if not DB[13113] then DB[13113]={id=13113,zoneId=-304,name="Convention at the Legerdemain",level=-1,minLevel=65,giver="Awilo Lon'gomba",giverType="NPC",giverId=29631,ender="Arille Azuregaze",enderType="NPC",enderId=29049,poiX=5851,poiY=472,wowhead="https://www.wowhead.com/wotlk/quest=13113",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Can you believe da horde has outlawed cannibalism...it just ain't right I tell ya!  I guess I should keep me mind on me work when we gots an order to fill.$B$BArille Azuregaze at the Legerdemain Lounge has many a guest a'comin to his place, mon.  You gots to be providin' some Northern Stew and a Jug of Wine from the cheese shop in central Dalaran.$B$BBring the wine and stew to Arille.",logDesc="Bring 4 Northern Stews and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.",rewards={{id=43016,qty=1},{id=44113,qty=1}}} end
if not DB[13114] then DB[13114]={id=13114,zoneId=-304,name="Sewer Stew",level=-1,minLevel=65,giver="Awilo Lon'gomba",giverType="NPC",giverId=29631,ender="Ajay Green",enderType="NPC",enderId=29532,poiX=5851,poiY=472,wowhead="https://www.wowhead.com/wotlk/quest=13114",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="We be havin' another order to fill.  Da innkeeper in da Dalaran sewers needs a vegetable stew as his customers dey don't have so much to eat, mon.$B$BHe asked for a vegetable stew as he didn't appreciate da gnome that was in the last stew I sent.  Get 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat and bring it to Ajay.$B$BYou can be gettin' to da Forest from da portal chamber in da eastern corner of Runeweaver Square. ",logDesc="Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot.$B$BThen bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.",rewards={{id=43016,qty=1},{id=44113,qty=1}}} end
if not DB[13115] then DB[13115]={id=13115,zoneId=-304,name="Cheese for Glowergold",level=-1,minLevel=65,giver="Awilo Lon'gomba",giverType="NPC",giverId=29631,ender="Ranid Glowergold",enderType="NPC",enderId=28718,poiX=5851,poiY=472,wowhead="https://www.wowhead.com/wotlk/quest=13115",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Ranid Glowergold in da Leatherworkers shop be havin' a need for wine and cheese.  Why he don't want some tasty gnome is beyond me.$B$BCollect da cheese from da cheese shop in central Dalaran and da half full wine glasses found on tables around da city.  Bring da wine and serve it with the cheese to Ranid.$B$BYou can call da wine a Wine Medley, mon'.",logDesc="Combine the empty cheese platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran.$B$BBring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.",rewards={{id=43016,qty=1},{id=44113,qty=1}}} end
if not DB[13116] then DB[13116]={id=13116,zoneId=-304,name="Mustard Dogs!",level=-1,minLevel=65,giver="Awilo Lon'gomba",giverType="NPC",giverId=29631,ender="3",enderType="NPC",enderId=28160,poiX=5851,poiY=472,wowhead="https://www.wowhead.com/wotlk/quest=13116",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Da Archmage Pentarus likes to be watchin' his crazy battle ball game, but he be needin' some food for da game.$B$BYou be needin' to fill his picnic basket with 4 cooked rhino dogs and then 4 wild mustard that are found in da grassy corners of de city.$B$BFill up his basket with the mustard dog goodies, mon'.",logDesc="Fill the Empty Picnic Basket with 4 Rhino Dogs that you be cookin' with your skill and 4 Wild Mustard that you find in the grassy areas of Dalaran.$B$BBring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran.",rewards={{id=43016,qty=2},{id=44113,qty=1}}} end
if not DB[13117] then DB[13117]={id=13117,zoneId=210,name="Where Are They Coming From?",level=80,minLevel=77,giver="Darkrider Arly",giverType="NPC",giverId=30631,ender="Darkrider Arly",enderType="NPC",enderId=30631,poiX=6654,poiY=3225,wowhead="https://www.wowhead.com/wotlk/quest=13117",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="The Lich King's tireless minions labor away night and day to assemble scores of abominations and flesh giants down there in the Fleshwerks.$B$BYet, that is not enough. More and more skeletal constructors keep appearing to increase the pace of work.$B$BIf we do not discover where they're coming from and how they're able to work so quickly, we'll be overrun before we can act in force. Search to the southeast and see if you can find the source of these skeletons.",logDesc="Investigate a Summoning Altar in the eastern part of the Fleshwerks, then report back to Darkrider Arly at Blackwatch."} end
if not DB[13118] then DB[13118]={id=13118,zoneId=210,name="The Purging Of Scourgeholme",level=78,minLevel=77,giver="The Ebon Watcher",giverType="NPC",giverId=30596,ender="The Ebon Watcher",enderType="NPC",enderId=30596,poiX=6377,poiY=239,wowhead="https://www.wowhead.com/wotlk/quest=13118",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Scourge have sent their armies at the Argent Crusade and have been repelled. What they do now is called a 'slash and burn.' All prisoners that they hold at Scourgeholme will be executed and raised as servants of the Lich King.$B$BUndoubtedly the Argent Crusade will request that you give their soldiers a proper farewell. I'll ask no such thing of you. To succeed we must kill Scourge indiscriminately.$B$BVenture to Scourgeholme, northwest through the Breach, and lay waste to all that stand in your way.",logDesc="The Ebon Watcher at the Valley of Echoes in Icecrown wants you to kill 3 Forgotten Depths High Priests, 3 Forgotten Depths Underkings, and 8 Reanimated Crusaders."} end
if not DB[13119] then DB[13119]={id=13119,zoneId=210,name="Destroying the Altars",level=80,minLevel=77,giver="Darkrider Arly",giverType="NPC",giverId=30631,ender="Darkrider Arly",enderType="NPC",enderId=30631,poiX=6654,poiY=3225,wowhead="https://www.wowhead.com/wotlk/quest=13119",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="So they're summoning in their workers and warriors at those altars?$B$BThey'll need to be the first thing to go. The master summoner should have a staff which allows him to activate the portal. If you kill the master summoner and take the staff, you can use it to overload the summoning portal and destroy its altar.$B$BDo this at all four of the altars and return to me once they've been destroyed.",logDesc="Kill Master Summoner Zarod and use his Summoning Stave to destroy the First, Second, Third, and Fourth Summoning Altars. When you've completed this task, report to Darkrider Arly at Blackwatch."} end
if not DB[13120] then DB[13120]={id=13120,zoneId=210,name="Death's Gaze",level=80,minLevel=77,giver="Darkrider Arly",giverType="NPC",giverId=30631,ender="Darkrider Arly",enderType="NPC",enderId=30631,poiX=6654,poiY=3225,wowhead="https://www.wowhead.com/wotlk/quest=13120",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Fleshwerks is a vast operation, and it will be difficult to keep an eye on all that transpires there. Fortunately, I have a plan.$B$B<Arly produces an orb from the folds of her cloak and shows it to you.>$B$BThis is a death's gaze orb. With it, we can observe the Scourge's actions and decide how best to strike.$B$BPlace these orbs on the stands at three crucial areas -- the abomination lab and the flesh giant lab to the southwest, along with the area surrounding the green cauldron far to the west.",logDesc="Use the Death's Gaze Orb to place orbs on the Abomination Lab Orb Stand, the Flesh Giant Lab Orb Stand, and the Cauldron Area Orb Stand, then return to Darkrider Arly at Blackwatch."} end
if not DB[13121] then DB[13121]={id=13121,zoneId=210,name="Through the Eye",level=80,minLevel=77,giver="The Bone Witch",giverType="NPC",giverId=30232,ender="The Bone Witch",enderType="NPC",enderId=30232,rewardNextId=13133,poiX=7631,poiY=3405,wowhead="https://www.wowhead.com/wotlk/quest=13121",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="We must use the Lich King's tools against him if we are to decide our next step.$B$BOver the mountain to the southwest lies Kul'galar Keep. Within it reside the oracles of Jotunheim who receive orders from their master and scry upon others through the Eye of the Lich King.$B$BIt is the eye that you must fight your way to. While it cannot be used to pierce the veil within Icecrown Citadel, you should be able to use it to discern something of value so that we will know how best to proceed.",logDesc="The Bone Witch in Njorndar Village has tasked you with using the Eye of the Lich King to gain information."} end
if not DB[13122] then DB[13122]={id=13122,zoneId=210,name="The Scourgestone",level=78,minLevel=77,giver="The Ebon Watcher",giverType="NPC",giverId=30596,ender="The Ebon Watcher",enderType="NPC",enderId=30596,poiX=6377,poiY=239,wowhead="https://www.wowhead.com/wotlk/quest=13122",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="A Scourgestone is an item given to all Scourge upon birth or creation. It provides certain benefits to the holder, but more importantly it allows Scourge leaders visibility into the location and movement of all of their units.$B$BWith enough Scourgestones, I might be able to track the movement of other Scourge units across Icecrown.$B$BAs you slaughter Scourge in Scourgeholme, gather all of the Scourgestones that you find. Return to me when your bags are full.",logDesc="The Ebon Watcher at the Valley of Echoes in Icecrown wants you to bring him 15 Scourgestones."} end
if not DB[13123] then DB[13123]={id=13123,zoneId=0,name="WotLK Collector's Edition: - DEM - E - FLAG",level=1,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=13123",image="assets/images/quests/placeholder.png"} end
if not DB[13124] then DB[13124]={id=13124,zoneId=4228,name="The Struggle Persists",level=80,minLevel=77,giver="3",giverType="NPC",giverId=26117,ender="Belgaristrasz",enderType="NPC",enderId=27658,rewardNextId=13126,poiX=3570,poiY=6650,wowhead="https://www.wowhead.com/wotlk/quest=13124",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="The battle goes on, $n. Somehow we have managed to avoid detection and continue our attempts to frustrate Malygos' schemes. This, though, is where the good news ends and the bad begins.$b$bOur best efforts have had little or no effect. Malygos and his underlings grow stronger in power with each passing day. And now, our latest assault team has been captured and is being held in the Oculus.$b$bWe must attempt a rescue! Belgaristrasz and his companions are invaluable to our cause. Can we count on you, $n?",logDesc="Raelorasz wants you to enter the Oculus and rescue Belgaristrasz  and his companions.",choiceRewards={{id=44334,qty=1},{id=44336,qty=1},{id=44335,qty=1},{id=44337,qty=1}}} end
if not DB[13125] then DB[13125]={id=13125,zoneId=210,name="The Air Stands Still",level=79,minLevel=77,giver="The Ebon Watcher",giverType="NPC",giverId=30596,ender="The Ebon Watcher",enderType="NPC",enderId=30596,poiX=6377,poiY=239,wowhead="https://www.wowhead.com/wotlk/quest=13125",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You must defeat the lords of Scourgeholme if this place is to be free of the Scourge's grasp.$B$BSalranax the Flesh Render lords over the temple on the first tier of Scourgeholme. Nearby Salranax you'll find High Priest Yath'amon preaching at the spirit tower on the second tier. Underking Talonox holds court at the Pit of Fiends, up the high road.$B$BThese are formidable opponents and must be approached with caution. Use this war horn should you require aid. The death knights of Acherus will come.",logDesc="The Ebon Watcher at the Valley of Echoes in Icecrown wants you to kill Salranax the Flesh Render, Underking Talonox and High Priest Yath'amon.",choiceRewards={{id=43839,qty=1},{id=43840,qty=1},{id=43830,qty=1},{id=43842,qty=1}}} end
if not DB[13126] then DB[13126]={id=13126,zoneId=4228,name="A Unified Front",level=80,minLevel=77,giver="Belgaristrasz",giverType="NPC",giverId=27658,ender="Image of Belgaristrasz",enderType="NPC",enderId=28012,rewardNextId=13127,poiX=933,poiY=1042,wowhead="https://www.wowhead.com/wotlk/quest=13126",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="Please accept our gratitude, $r.$b$bYou and your friends have succeeded where we had failed - you have bested Drakos. From here, however, it will take our combined efforts to proceed.$b$bAbove us, Varos hides behind an impenetrable shield. To reach him, you must defeat the Centrifuge Constructs that power his shield. That is where my friends and I come in....$b$bWe each can provide you with drakes from our respective flights. Only with the help of these drakes will you be able to expose Varos.",logDesc="Belgaristrasz wants you to destroy 10 Centrifuge Constructs to bring down Varos' shield. You then must defeat Varos Cloudstrider."} end
if not DB[13127] then DB[13127]={id=13127,zoneId=4228,name="Mage-Lord Urom",level=80,minLevel=77,giver="Image of Belgaristrasz",giverType="NPC",giverId=28012,ender="Image of Belgaristrasz",enderType="NPC",enderId=28012,rewardNextId=13128,wowhead="https://www.wowhead.com/wotlk/quest=13127",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="Only one obstacle stands between us and our ultimate goal here, $c. His name is Urom.$b$bAbove us, guarding the third ring, he awaits us. Beware his powerful conjurings, friend. He is a frightful opponent, certain to challenge your prowess.$b$bBring him down. Make him pay for his treacherous allegiance to the enemy!",logDesc="Belgaristrasz wants you to defeat Mage-Lord Urom in the Oculus."} end
if not DB[13128] then DB[13128]={id=13128,zoneId=4228,name="A Wing and a Prayer",level=80,minLevel=77,giver="Image of Belgaristrasz",giverType="NPC",giverId=28012,ender="3",enderType="NPC",enderId=26117,wowhead="https://www.wowhead.com/wotlk/quest=13128",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="The time has come to face Eregos, friend.$b$bHe is cunning and strong. One of Malygos' most trusted minions, he draws strength from the energies he is charged with defending - sipping from the well of the great aspect himself.$b$bThis shall not be easy....$b$bHowever, defeating the Mage-Lord has allowed us to unlock the full power of our drakes. Their skills shall be at your command. Use them wisely and Eregos shall surely fall.$b$bShould you succeed, return to Raelorasz and inform him of our victory.",logDesc="Belgaristrasz wants you to kill Eregos in the Oculus and then report to Raelorasz at the Transitus Shield in Coldarra.",choiceRewards={{id=44338,qty=1},{id=44339,qty=1},{id=44340,qty=1},{id=44341,qty=1}}} end
if not DB[13129] then DB[13129]={id=13129,zoneId=4196,name="Head Games",level=74,minLevel=72,giver="Kurzel",giverType="NPC",giverId=26664,ender="Mack Fearsen",enderType="NPC",enderId=26604,wowhead="https://www.wowhead.com/wotlk/quest=13129",image="assets/images/quests/placeholder.png",xpDiff=8,money=224000,desc="Too lazy for their own good.... Wait! I know how to teach 'em!$b$b<Kurzel rips a long strip of material from her blouse and hands it to you.>$b$bHere, $r, take this. Dip it in the remains of that annoying lich over there and return it to Mack back at the camp.$b$bOnce the boys have stewed in their guilt for a while I'll show up and let them off the hook.$b$bThey'll learn not to let a lady wander off alone!",logDesc="Kurzel wants you to use Kurzel's Blouse Scrap at the corpse of Novos the Summoner, then take the Ichor-Stained Cloth to Mack.",choiceRewards={{id=44366,qty=1},{id=44367,qty=1},{id=44368,qty=1},{id=44369,qty=1}}} end
if not DB[13130] then DB[13130]={id=13130,zoneId=210,name="The Stone That Started A Revolution",level=79,minLevel=77,giver="Crusade Architect Silas",giverType="NPC",giverId=30686,ender="Crusade Architect Silas",enderType="NPC",enderId=30686,poiX=6372,poiY=238,wowhead="https://www.wowhead.com/wotlk/quest=13130",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You may look at Scourgeholme now and see a rancid pit of decay, but one day it will be a place of glory and honor. Highlord Fordring has deemed it \"Justice Keep.\"$B$BAlas, even an impregnable fortress like Icecrown Citadel began with but a single stone. So begins our search for the stone to start a revolution.$B$BTravel to Crystalsong, south of here, and seek out the Unbound Thicket in the east. Once there gather crystalline heartwood from the thicket floor and elven masonry from the Ruins of Shandaral.",logDesc="Crusade Architect Silas at the Valley of Echoes in Icecrown wants you to retrieve 10 Trunks of Crystalline Heartwood and 10 pieces of Ancient Elven Masonry.",choiceRewards={{id=43855,qty=1},{id=43914,qty=1},{id=43982,qty=1},{id=43947,qty=1}}} end
if not DB[13131] then DB[13131]={id=13131,zoneId=1196,name="Junk in My Trunk",level=80,minLevel=78,giver="Brigg Smallshanks",giverType="NPC",giverId=30871,ender="Brigg Smallshanks",enderType="NPC",enderId=30871,poiX=570,poiY=-324,wowhead="https://www.wowhead.com/wotlk/quest=13131",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="Just look at it! Me trunk never been so empty. Shoulda been filled ten times over by now!$b$bMe mates jumped at the sight o' all that booty, and now look at 'em! Rattlin' bones, they be!$b$bIt be like me mammy use 'ta tell me - only thing worse than no treasure be cursed treasure.$b$bSay, thar be plenty o' loot farther in, an' not the cursed kind I'll wager. These sots not be needin' it - it just be junk ta them.$b$bFetch it fer me an' I'll be rewardin' ya handsomely, matey.$B",logDesc="Brigg in Utgarde Pinnacle wants you to find 5 Untarnished Silver Bars, 3 Shiny Baubles, 2 Golden Goblets, and a Jade Statue.",choiceRewards={{id=44404,qty=1},{id=44405,qty=1},{id=44407,qty=1},{id=44406,qty=1}}} end
if not DB[13132] then DB[13132]={id=13132,zoneId=1196,name="Vengeance Be Mine!",level=80,minLevel=78,giver="Brigg Smallshanks",giverType="NPC",giverId=30871,ender="Brigg Smallshanks",enderType="NPC",enderId=30871,poiX=570,poiY=-324,wowhead="https://www.wowhead.com/wotlk/quest=13132",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="Och! They cannae be blamed, $g lad:lass;. Who'da done different?$b$bThey hurled themselves at them piles o' gold - thought they'd hit the mother lode, they did. Aye... But look at 'em now. Mindless servants unable to pick up a single doubloon.$b$bOnly luck spared me from the same fate. In the scurry I got knocked down - was a wee bit tipsy to begin with. Looked up ta see the first of 'em turn...$b$bBe a good $g lad:lass; and find the one in charge here and teach 'em not ta be cursin' me mates.",logDesc="Brigg in Utgarde Pinnacle wants you to kill King Ymiron.",choiceRewards={{id=44408,qty=1},{id=44409,qty=1},{id=44410,qty=1},{id=44412,qty=1},{id=44411,qty=1}}} end
if not DB[13133] then DB[13133]={id=13133,zoneId=210,name="Find the Ancient Hero",level=80,minLevel=77,giver="The Bone Witch",giverType="NPC",giverId=30232,ender="The Bone Witch",enderType="NPC",enderId=30232,rewardNextId=13137,poiX=7631,poiY=3405,wowhead="https://www.wowhead.com/wotlk/quest=13133",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Quickly, $N, head southwest to the Halls of the Ancestors!$B$BWithin you will find slumbering mjordin. Wake them until you find Iskalder. When you do, use this amulet upon him and bring him back to me.$B$BNow go. There is no time to waste!",logDesc="The Bone Witch at Njorndar Village wants you to return with Iskalder."} end
if not DB[13134] then DB[13134]={id=13134,zoneId=210,name="Spill Their Blood",level=80,minLevel=77,giver="Darkrider Arly",giverType="NPC",giverId=30631,ender="Darkrider Arly",enderType="NPC",enderId=30631,poiX=6654,poiY=3225,wowhead="https://www.wowhead.com/wotlk/quest=13134",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Scourge cannot create their flesh monsters without blood and embalming fluid to preserve the parts and keep them functioning. If we can deny them these materials, their army will fall apart and we can easily destroy their creations.$B$BThroughout the labs where the flesh giants and abominations are cobbled together, you will find vats of embalming fluid and large orbs filled with blood. Destroy these, and bring death to any who would stop you!",logDesc="Darkrider Arly at Blackwatch wants you to destroy 5 vats of Embalming Fluid and 5 Blood Orbs."} end
if not DB[13135] then DB[13135]={id=13135,zoneId=210,name="It Could Kill Us All",level=79,minLevel=77,giver="Crusade Engineer Spitzpatrick",giverType="NPC",giverId=30714,ender="Crusade Engineer Spitzpatrick",enderType="NPC",enderId=30714,poiX=6372,poiY=240,wowhead="https://www.wowhead.com/wotlk/quest=13135",image="assets/images/quests/placeholder.png",xpDiff=5,money=71000,desc="Southeast of here, at the eastern reaches of Crystalsong Forest, is an area known as the Unbound Thicket. Within that thicket creeps all manner of life. One thing all of the affected creatures of the thicket share in common is their affinity for magical energy. Each of them holds pure, crystallized energy. Enough to kill us all should it ever destabilize!$B$BTravel to the Unbound Thicket and kill its denizens for crystallized energy. We need fuel and they need to die. We call that a \"win-win.\"",logDesc="Crusade Engineer Spitzpatrick at the Valley of Echoes in Icecrown wants you to retrieve 8 pieces of Crystallized Energy."} end
if not DB[13136] then DB[13136]={id=13136,zoneId=210,name="Jagged Shards",level=80,minLevel=77,ender="Crusader Olakin Sainrith",enderType="NPC",enderId=30708,wowhead="https://www.wowhead.com/wotlk/quest=13136",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You pulled this jagged, dark brittle shard from the body of a ghoul. The metal blade lacks a smooth edge, suggesting it was forged by an unskilled hand, or was broken from a larger piece.$B$BYou recall seeing similar shards embedded in the bodies of all the ghouls you've encountered at the Fleshwerks, leading you to wonder why their creators bothered to include the metal at all. Perhaps Crusader Olakin Sainrith would have some insight if you brought him the shards from several ghouls.",logDesc="Bring 10 Jagged Shards to Crusader Olakin Sainrith at Blackwatch."} end
if not DB[13137] then DB[13137]={id=13137,zoneId=210,name="Not-So-Honorable Combat",level=80,minLevel=77,giver="The Bone Witch",giverType="NPC",giverId=30232,ender="The Bone Witch",enderType="NPC",enderId=30232,rewardNextId=13142,poiX=7631,poiY=3405,wowhead="https://www.wowhead.com/wotlk/quest=13137",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Atop the tallest peak to the southwest overlooking Jotunheim is Battlescar Spire. It is a place of reverence for the vrykul, second only to Valhalas in terms of where they prefer to do honorable combat.$B$BWe shall visit not-so-honorable combat upon it.$B$BGather your companions and fly to the spire. When you are ready, light the signal fire and I will appear within the body of Iskalder.$B$BWe will fight, you will win, and Vardmadra is sure to come to witness the battle!",logDesc="The Bone Witch in Njorndar Village wants you to defeat Iskalder upon Battlescar Spire.",choiceRewards={{id=44016,qty=1},{id=44036,qty=1},{id=44037,qty=1},{id=44038,qty=1}}} end
if not DB[13138] then DB[13138]={id=13138,zoneId=210,name="I'm Smelting... Smelting!",level=80,minLevel=77,giver="Crusader Olakin Sainrith",giverType="NPC",giverId=30708,ender="Crusader Olakin Sainrith",enderType="NPC",enderId=30708,poiX=6649,poiY=3218,wowhead="https://www.wowhead.com/wotlk/quest=13138",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="<Olakin turns one of the shards over in an armored fist.>$B$BThese could pierce armor with enough force. We have to find out what they're made of and what the Lich King intends to do with them.$B$BTo the east, nestled next to Icecrown Citadel itself, lies Malykriss. From the few reports we have, it's full of smelting and smithing equipment. Bring these shards there, and smelt them in one of the open furnaces on the bottom level of Malykriss. Once the metal has been reformed, we can identify it.",logDesc="Use the Bag of Jagged Shards near one of the bottom level Malykriss furnaces. Return to Crusader Olakin Sainrith at Blackwatch with the Smelted Metal Bar."} end
if not DB[13139] then DB[13139]={id=13139,zoneId=210,name="Into The Frozen Heart Of Northrend",level=79,minLevel=77,giver="Father Gustav",giverType="NPC",giverId=30683,ender="3",enderType="NPC",enderId=30677,rewardNextId=13141,poiX=6384,poiY=247,wowhead="https://www.wowhead.com/wotlk/quest=13139",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Silas and Spitzpatrick have signed off on the materials and fuel needed to begin construction of Justice Keep. Thanks to you and the Ebon Blade the Scourge presence within Scourgeholme has been decimated and their lieutenants have been defeated.$B$BI have chosen the site at which we will break ground, but first you must deliver my report to Highlord Tirion Fordring. We will begin our march into Icecrown on his command.$B",logDesc="Deliver Father Gustav's Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.$B"} end
if not DB[13140] then DB[13140]={id=13140,zoneId=210,name="The Runesmiths of Malykriss",level=80,minLevel=77,giver="Crusader Olakin Sainrith",giverType="NPC",giverId=30708,ender="Crusader Olakin Sainrith",enderType="NPC",enderId=30708,poiX=6649,poiY=3218,wowhead="https://www.wowhead.com/wotlk/quest=13140",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Those shards you recovered can only have come from one place, Malykriss. It's the seat of the Lich King's metalworking operations, to the east of Corp'rethar.$B$BWhat's puzzling is that metal isn't needed to stitch together abominations or flesh giants, or to summon skeletal servants. Find the skeletal runesmiths working on the bottom level of Malykriss and capture the plates they're working on. We need to find out why this metal is finding its way to the Fleshwerks.",logDesc="Bring 5 Runed Saronite Plates to Crusader Olakin Sainrith at Blackwatch."} end
if not DB[13141] then DB[13141]={id=13141,zoneId=210,name="The Battle For Crusaders' Pinnacle",level=79,minLevel=77,giver="3",giverType="NPC",giverId=30677,ender="Father Gustav",enderType="NPC",enderId=30683,rewardNextId=13157,poiX=6260,poiY=50,wowhead="https://www.wowhead.com/wotlk/quest=13141",image="assets/images/quests/placeholder.png",xpDiff=5,money=71000,desc="<Highlord Fordring holds a banner of the Argent Crusade.>$B$BThis banner is like no other, $N. It carries with it a powerful blessing, able to sanctify large tracts of blighted land.$B$BYou must take it northwest, through the Breach, to an area the Scourge have mockingly named Crusaders' Pinnacle. Plant the banner atop the skulls of our fallen brethren at Crusaders' Pinnacle and defend it against attack. Once the land is sanctified, return to Father Gustav.$B$BGo now, $N. Hold no fear in your heart.",logDesc="Venture to Crusaders' Pinnacle and use the Blessed Banner of the Crusade atop the Pile of Crusader Skulls. Defend the banner against Scourge attack until the land atop the pinnacle is sanctified and then return to Father Gustav at the Valley of Echoes in Icecrown."} end
if not DB[13142] then DB[13142]={id=13142,zoneId=210,name="Banshee's Revenge",level=80,minLevel=77,giver="The Bone Witch",giverType="NPC",giverId=30232,ender="The Bone Witch",enderType="NPC",enderId=30232,rewardNextId=13213,poiX=7631,poiY=3405,wowhead="https://www.wowhead.com/wotlk/quest=13142",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="The time has come, $N. You and your friends must challenge the lord of Balargarde Fortress, the master of Jotunheim, Overthane Balargarde.$B$BAtop the fortress, which is on the southwestern edge of Jotunheim, you will find a horn. Blow into it. Allow your challenge to resound throughout the steadfast.$B$BBalargarde will have no choice but to face you. And I... excuse me, Vardmadra will be there to adjudicate the challenge.$B$B<The banshee-possessed vrykul lets out a bellowing cackle.>",logDesc="The Bone Witch at Njorndar Village has asked you to exact her revenge by challenging and defeating Overthane Balargarde.",choiceRewards={{id=44028,qty=1},{id=44029,qty=1},{id=44022,qty=1},{id=44023,qty=1},{id=44032,qty=1}}} end
if not DB[13143] then DB[13143]={id=13143,zoneId=210,name="New Recruit",level=80,minLevel=77,giver="Vereth the Cunning",giverType="NPC",giverId=30944,ender="Vereth the Cunning",enderType="NPC",enderId=30944,rewardNextId=13145,poiX=6451,poiY=2048,wowhead="https://www.wowhead.com/wotlk/quest=13143",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="First things first. I saw some Lithe Stalkers on the ramparts just east of us. They used to serve us before we broke with Arthas, and they're about as perfect a scout as you can get... with a little prodding from an eye of dominion.$B$BFly up, find one of the stalkers, beat it down a bit, and then use this Sigil of the Ebon Blade to command its obedience. It will recognize the sigil, guaranteed. Lead it back to the top of the rocks northeast of here and it will find its way to me.",logDesc="Vereth the Cunning on the Rise of Suffering has requested that you bring a subdued Lithe Stalker to the top of the rocks northeast of the Rise of Suffering."} end
if not DB[13144] then DB[13144]={id=13144,zoneId=210,name="Killing Two Scourge With One Skeleton",level=80,minLevel=77,giver="Darkrider Arly",giverType="NPC",giverId=30631,ender="Darkrider Arly",enderType="NPC",enderId=30631,poiX=6654,poiY=3225,wowhead="https://www.wowhead.com/wotlk/quest=13144",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The workers in the Fleshwerks abomination lab have already completed a number of their creations. For now, the creatures are chained to the pillars around the edge of the lab, but if we do not act, they will march with the Lich King's armies.$B$BGrasping arms reach out of the bone piles spread throughout the Fleshwerks. These arms belong to skeletons enchanted with the power of fire. Find and free these skeletons, then take them near the completed abominations and watch the show!",logDesc="Darkrider Arly at Blackwatch wants you to destroy 3 Chained Abominations with Burning Skeletons.",choiceRewards={{id=38739,qty=1},{id=39038,qty=1},{id=39068,qty=1},{id=39104,qty=1}}} end
if not DB[13145] then DB[13145]={id=13145,zoneId=210,name="The Vile Hold",level=80,minLevel=77,giver="Vereth the Cunning",giverType="NPC",giverId=30944,ender="Vereth the Cunning",enderType="NPC",enderId=30944,poiX=6451,poiY=2048,wowhead="https://www.wowhead.com/wotlk/quest=13145",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="We need to know what we're up against.$B$BUse the eye of dominion to assume control of a lithe stalker and scout out the area. There are a few spots in particular I saw when flying in that I want you to get a closer look at: the overlook in the northeast, the work area in the southeast, the large forge near the center, and the ritual area in the southwest.$B$BThe stalker can leap far and won't be hurt by large falls - use that to your advantage to get up and down from those ramparts.",logDesc="Vereth the Cunning at the Rise of Suffering has requested that you use a Lithe Stalker to scout out Malykriss.",choiceRewards={{id=43866,qty=1},{id=43906,qty=1},{id=43934,qty=1},{id=43845,qty=1}}} end
if not DB[13146] then DB[13146]={id=13146,zoneId=210,name="Generosity Abounds",level=80,minLevel=77,giver="Vereth the Cunning",giverType="NPC",giverId=30944,ender="Vereth the Cunning",enderType="NPC",enderId=30944,poiX=6451,poiY=2048,wowhead="https://www.wowhead.com/wotlk/quest=13146",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="We need to cause some disruption... anything to bring those death knights away from their leaders. If we lay waste to their minions below, I suspect they'll have to devote more attention to keeping a close eye on operations.$B$BAbominations are easy prey - slow, predictable, and most importantly, stupid. Take advantage of their trust of the stalkers to drag them some of the Scourge bombs scattered throughout the construction area. You'll be able light the bombs far before they figure out what's going on.",logDesc="Vereth the Cunning wants you to use the Lithe Stalker's Iron Chain to drag Scourge Bombs to 4 Lumbering Atrocities inside Malykriss."} end
if not DB[13147] then DB[13147]={id=13147,zoneId=210,name="Matchmaker",level=80,minLevel=77,giver="Vereth the Cunning",giverType="NPC",giverId=30944,ender="Vereth the Cunning",enderType="NPC",enderId=30944,poiX=6451,poiY=2048,wowhead="https://www.wowhead.com/wotlk/quest=13147",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The major difference between vargul and lesser undead minions is that vargul still possess enough of their minds to despise being used for labor. Never will a vargul be pleased to be working aside skeletons or ghouls.$B$BLets take advantage of this inevitable animosity and start some fights between the umbral brutes and the other undead in Malykriss. That should serve to slow production and bring the death knights down to babysit.$B$BShould be simple - throw rocks at the brutes as they near lesser undead.",logDesc="Vereth the Cunning at the Rise of Suffering wants you to use a Lithe Stalker to throw rocks at Umbral Brutes as they near lesser undead in Malykriss. Return after you've started 5 fights."} end
if not DB[13148] then DB[13148]={id=13148,zoneId=-373,name="Necklace Repair",level=-1,minLevel=77,ender="Timothy Jones",enderType="NPC",enderId=28701,wowhead="https://www.wowhead.com/wotlk/quest=13148",image="assets/images/quests/placeholder.png",money=74000,desc="This damaged necklace has an invoice with it that reads \"Property of Timothy Jones - Cartier and Co Fine Jewelry - Magus Commerce Exhange - Dalaran\".$B$BPerhaps you should repair it and return it to him.$B",logDesc="Repair the necklace with a single Chalcedony and return it to Timothy Jones in at the Jewelcrafters Shop in the Magus Commerce Exchange in Dalaran.",rewards={{id=41596,qty=1}}} end
if not DB[13149] then DB[13149]={id=13149,zoneId=4100,name="Dispelling Illusions",level=80,minLevel=78,giver="Chromie",giverType="NPC",giverId=26527,ender="Chromie",enderType="NPC",enderId=27915,rewardNextId=13151,poiX=1550,poiY=574,wowhead="https://www.wowhead.com/wotlk/quest=13149",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="Always meddling...$b$bThe Infinite Dragonflight seek to disrupt history as we have come to know it by deceiving Prince Arthas.$b$bIf they can convince him that none of the grain here carries the plague, then he'll never have to make the fateful decision to cull Stratholme.$b$bThis must not come to pass.$b$bUse this Arcane Disruptor on any suspicious crates of grain you find to reveal them for what they are. Meet me near Stratholme's entrance, north of this place, when the work is done.",logDesc="Chromie wants you to use the Arcane Disruptor on the suspicious crates in Stratholme Past, then speak to her near the entrance to Stratholme."} end
if not DB[13150] then DB[13150]={id=13150,zoneId=-373,name="ZZOLDLost: Widget",level=77,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=13150",image="assets/images/quests/placeholder.png",desc="Attached to the bottom of the widget is an invoice that indicates the owner is \"Timothy Jones - Jewelershop Name, District Name\" in Dalaran.   Perhaps if you fixed it and returned it to him, he would have a reward for you.",logDesc="Repair the whatsit and return it to Timothy Jones at the Jewelcrafting shop in Dalaran."} end
if not DB[13151] then DB[13151]={id=13151,zoneId=4100,name="A Royal Escort",level=80,minLevel=78,giver="Chromie",giverType="NPC",giverId=27915,ender="Chromie",enderType="NPC",enderId=30997,poiX=1813,poiY=1284,wowhead="https://www.wowhead.com/wotlk/quest=13151",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="The Infinite Dragonflight are not likely to give up so easily. I cannot be certain of what they're up to, but something tells me we haven't seen the last of them today.$b$bIn just a moment, Arthas will face a desperate dilemma, and make a momentous decision.$b$bDon't lose focus now, $n. I needn't remind you how much is at stake. I must call upon you to accompany the prince in his culling of Stratholme.$b$bArthas must make it through Stratholme alive and you must see to it that he defeats Mal'Ganis!",logDesc="Chromie has asked you to accompany Arthas in the Culling of Stratholme. You are to speak with her again after Mal'Ganis is defeated.",choiceRewards={{id=44396,qty=1},{id=44397,qty=1},{id=44398,qty=1},{id=44399,qty=1}}} end
if not DB[13152] then DB[13152]={id=13152,zoneId=210,name="A Visit to the Doctor",level=80,minLevel=77,giver="Darkrider Arly",giverType="NPC",giverId=30631,ender="Darkrider Arly",enderType="NPC",enderId=30631,poiX=6654,poiY=3225,wowhead="https://www.wowhead.com/wotlk/quest=13152",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="So they've been embedding these ghouls with broken shards of saronite down in the Sanctum of Reanimation? We must put a stop to this, before these ghouls can be deployed against our troops.$B$BFind the entrance to the Sanctum of Reanimation in the flesh giant lab area of the Fleshwerks. There, the ghoul mastermind, Doctor Sabnok, keeps the most fearsome of his creations, Patches. Free Patches from his chains and help him take his revenge on the doctor. Let his own creation be his undoing.",logDesc="Darkrider Arly at Blackwatch wants you to destroy the Metal Stake imprisoning Patches in the Sanctum of Reanimation and help him get his revenge on Doctor Sabnok."} end
if not DB[13153] then DB[13153]={id=13153,zoneId=4197,name="Warding the Warriors",level=80,minLevel=78,giver="Sorceress Kaylana",giverType="NPC",giverId=31051,ender="Sorceress Kaylana",enderType="NPC",enderId=31051,poiX=5082,poiY=2174,wowhead="https://www.wowhead.com/wotlk/quest=13153",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="$n, good to see you. While the battle has subsided for now, we must hurry and replenish our stocks. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been seen collecting armor in the area.$B$BHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.$B$BIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.",logDesc="Sorceress Kaylana at Wintergrasp Fortress wants you to retrieve 10 sets of Imbued Horde Armor from Horde players at the Glacial Falls.",rewards={{id=43228,qty=10}}} end
if not DB[13154] then DB[13154]={id=13154,zoneId=4197,name="Bones and Arrows",level=80,minLevel=78,giver="Bowyer Randolph",giverType="NPC",giverId=31052,ender="Bowyer Randolph",enderType="NPC",enderId=31052,poiX=5100,poiY=2169,wowhead="https://www.wowhead.com/wotlk/quest=13154",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.$B$BHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.$B$BHead to the Forest of Shadows and bring back any bone splinters you can find!$B$BThe Horde have been seen collecting bone splinters in the area. Slay them!",logDesc="Bowyer Randolph at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.",rewards={{id=43228,qty=10}}} end
if not DB[13155] then DB[13155]={id=13155,zoneId=210,name="Vereth the Cunning",level=80,minLevel=77,giver="Keritose Bloodblade",giverType="NPC",giverId=30946,ender="Vereth the Cunning",enderType="NPC",enderId=30944,rewardNextId=13143,poiX=8401,poiY=2681,wowhead="https://www.wowhead.com/wotlk/quest=13155",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="I've already heard some rumors regarding Malykriss and Arthas's new death knight order, but I assumed it nothing more than filling the void. These numbers suggest he's trying to take it up a notch though.$B$BWe dispatched one of our best to Malykriss not long ago - Vereth the Cunning. You should be able to find him on the Rise of Suffering, just west of Malykriss, and inside the Court of Bones.$B$BTry not to draw too much attention on your way in.",logDesc="Report to Vereth the Cunning on the Rise of Suffering in Icecrown."} end
if not DB[13156] then DB[13156]={id=13156,zoneId=4197,name="A Rare Herb",level=80,minLevel=78,giver="Anchorite Tessa",giverType="NPC",giverId=31054,ender="Anchorite Tessa",enderType="NPC",enderId=31054,poiX=5089,poiY=2168,wowhead="https://www.wowhead.com/wotlk/quest=13156",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="My, it its quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.$B$BHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 of the Horde herb pouches you find. I will grind them into a medicine to help protect against the cold.$B$BThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!",logDesc="Anchorite Tessa in Wintergrasp Fortress wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.",rewards={{id=43228,qty=10}}} end
if not DB[13157] then DB[13157]={id=13157,zoneId=210,name="The Crusaders' Pinnacle",level=79,minLevel=77,giver="Father Gustav",giverType="NPC",giverId=30683,ender="3",enderType="NPC",enderId=31044,poiX=6384,poiY=247,wowhead="https://www.wowhead.com/wotlk/quest=13157",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Stand proud in knowing that it was you who helped establish the Argent Crusade inside the walls of Icecrown, $N. The Crusaders' Pinnacle now stands in direct defiance of the Lich King and his twisted minions.$B$BHighlord Fordring and the crusaders who survived await your arrival at Crusaders' Pinnacle. Travel once more through the Breach and seek out the highlord!",logDesc="Seek out Highlord Tirion Fordring at Crusaders' Pinnacle in Icecrown.",choiceRewards={{id=44019,qty=1},{id=44044,qty=1},{id=44045,qty=1},{id=44046,qty=1},{id=44040,qty=1}}} end
if not DB[13158] then DB[13158]={id=13158,zoneId=4415,name="Discretion is Key",level=77,minLevel=75,giver="5",giverType="NPC",giverId=16128,ender="Warden Alturas",enderType="NPC",enderId=31080,rewardNextId=13159,poiX=5798,poiY=798,wowhead="https://www.wowhead.com/wotlk/quest=13158",image="assets/images/quests/placeholder.png",xpDiff=1,money=6600,desc="Listen to me, $r.$b$bIt's just been brought to my attention that there's been an incident at the Violet Hold. It would appear that the blues are launching a full scale invasion of Dalaran!$b$bI need you to get to the prison and speak with Warden Alturas at once. He'll give you the details.$b$bThat is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear?$b$bVery well. Now, go!",logDesc="Rhonin wants you to go to the Violet Hold in Dalaran and speak with Warden Alturas."} end
if not DB[13159] then DB[13159]={id=13159,zoneId=4415,name="Containment",level=77,minLevel=75,giver="Warden Alturas",giverType="NPC",giverId=31080,ender="Warden Alturas",enderType="NPC",enderId=31080,poiX=5714,poiY=544,wowhead="https://www.wowhead.com/wotlk/quest=13159",image="assets/images/quests/placeholder.png",xpDiff=8,money=260000,desc="Here is the prison key.$b$bMy men and I will stay here as a last line of defense in the event that you are unable to overcome the assault.$b$bBe sure to speak with Lieutenant Sinclari. She'll provide you with access to the prison's defenses.$b$bHurry, $r. There is little time. The few I left inside won't last long without your help. Report back to me once the invasion forces have been successfully dealt with.",logDesc="Warden Alturas wants you to enter the Violet Hold and put and end to the blue dragon invasion force. You are to report back to him once Cyanigosa is slain.",choiceRewards={{id=44342,qty=1},{id=44343,qty=1},{id=44344,qty=1},{id=44345,qty=1}}} end
if not DB[13160] then DB[13160]={id=13160,zoneId=210,name="Stunning View",level=80,minLevel=77,giver="Vereth the Cunning",giverType="NPC",giverId=30944,ender="Vereth the Cunning",enderType="NPC",enderId=30944,poiX=6451,poiY=2048,wowhead="https://www.wowhead.com/wotlk/quest=13160",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Gargoyles make effective scouts and can be deadly if left to rain attacks from the air, but they have a very obvious weakness. Most of them have to go through long periods resting as stone to maintain the energy they need to carry their heavy bodies through the air.$B$BAs I peered through the eye you were using, I noticed dozens of iceskin sentries resting on the eastern and southern walls inside. Use the stalker to leap up to their ledges and devastate them while they sleep.",logDesc="Vereth the Cunning at the Rise of Suffering wants you to use a Lithe Stalker's heave ability to destroy 12 sleeping Iceskin Sentries."} end
if not DB[13161] then DB[13161]={id=13161,zoneId=210,name="The Rider of the Unholy",level=80,minLevel=77,giver="Vereth the Cunning",giverType="NPC",giverId=30944,ender="Vereth the Cunning",enderType="NPC",enderId=30944,poiX=6451,poiY=2048,wowhead="https://www.wowhead.com/wotlk/quest=13161",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="It's time that we start cutting off the heads of the beast.$B$BI served beside Rokir for quite some time. He knows the unholy arts better than most any other death knight I've met and he's equally as ruthless.$B$BRokir's strengths are most apparent when you are fighting him on his own ground. Sadly, we don't have much option in those regards, but stay on your feet to avoid his undead minions and you should come out victorious.$B$BBe nimble, $c, and do not take him lightly.",logDesc="Vereth the Cunning on the Rise of Suffering wants you to kill Rokir, the Rider of the Unholy.",choiceRewards={{id=43904,qty=1},{id=43948,qty=1},{id=43940,qty=1},{id=43873,qty=1}}} end
if not DB[13162] then DB[13162]={id=13162,zoneId=210,name="The Rider of Frost",level=80,minLevel=77,giver="Vereth the Cunning",giverType="NPC",giverId=30944,ender="Vereth the Cunning",enderType="NPC",enderId=30944,poiX=6451,poiY=2048,wowhead="https://www.wowhead.com/wotlk/quest=13162",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Sapph... Sapph's a death knight like no other. She'll shower you with sweet words and you'll swear that she has no evil within her heart, and then she'll run you through without even breaking her smile.$B$BI have no fear that you'll be able to best Sapph, but do not grow overconfident. Her strength lies in lulling her victims into a false ease, shortly before shattering them with a fierce barrage of frost attacks.$B$BDo not let your guard down, and do not underestimate her.",logDesc="Vereth the Cunning on the Rise of Suffering wants you to kill Sapph, the Rider of Frost.",choiceRewards={{id=43899,qty=1},{id=43897,qty=1},{id=43898,qty=1},{id=43875,qty=1}}} end
if not DB[13163] then DB[13163]={id=13163,zoneId=210,name="The Rider of Blood",level=80,minLevel=77,giver="Vereth the Cunning",giverType="NPC",giverId=30944,ender="Vereth the Cunning",enderType="NPC",enderId=30944,poiX=6451,poiY=2048,wowhead="https://www.wowhead.com/wotlk/quest=13163",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Baelok is one of the few vrykul that I've ever seen rise through the ranks, and that was mostly accomplished through sheer brutality. If your competition ends up dead, there's far less to compete against.$B$BWhen you join battle with him, spread out from your companions and keep your distance as much as you reasonably can. He will not hesitate to steal your life force for himself, so you will need to hinder his ability to do so as much as possible.$B$BYou have my confidence. See to it that he dies.",logDesc="Vereth the Cunning on the Rise of Suffering wants you to kill Baelok, the Rider of Blood.",choiceRewards={{id=43877,qty=1},{id=43896,qty=1},{id=43937,qty=1},{id=43939,qty=1}}} end
if not DB[13164] then DB[13164]={id=13164,zoneId=210,name="The Fate of Bloodbane",level=80,minLevel=77,giver="Vereth the Cunning",giverType="NPC",giverId=30944,ender="Vereth the Cunning",enderType="NPC",enderId=30944,poiX=6451,poiY=2048,wowhead="https://www.wowhead.com/wotlk/quest=13164",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="With the riders of the Host of Suffering dead, now is the time to put an end to their true leader: Orbaz Bloodbane.$B$BMograine caught up with me while you were off and told me that he found where Orbaz is hiding. Under Icecrown Citadel itself, there is an immense pit - you will find Orbaz just outside its lip.$B$BSome of the Ebon Blade's strongest agents have already been dispatched - gather aid and join the fight. It is time for Bloodbane to die.",logDesc="Vereth on the Rise of Suffering has dispatched you to kill Orbaz Bloodbane.",choiceRewards={{id=44027,qty=1},{id=44025,qty=1},{id=44020,qty=1},{id=44026,qty=1}}} end
if not DB[13165] then DB[13165]={id=13165,zoneId=-372,name="Taking Back Acherus",level=55,minLevel=55,giver="3",giverType="NPC",giverId=29173,ender="3",enderType="NPC",enderId=31084,rewardNextId=13166,poiX=2432,poiY=-5137,wowhead="https://www.wowhead.com/wotlk/quest=13165",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The haze has been lifted. I can see as clearly now as the day that I plunged the Ashbringer into my own heart to free my father's cursed soul: my last memory as a free man.$B$BWe must take back Acherus from the Scourge if our order is to survive in this new world. I have taught you how to call forth a death gate. The death gate will return you to Acherus when you call upon it, $N. Use it now and meet me at Acherus. The first battle of the Knights of the Ebon Blade is underway! Death to the Scourge!",logDesc="Use your Death Gate spell to return to Acherus: The Ebon Hold. Report to Highlord Darion Mograine once you arrive."} end
if not DB[13166] then DB[13166]={id=13166,zoneId=-372,name="The Battle For The Ebon Hold",level=55,minLevel=55,giver="3",giverType="NPC",giverId=31084,ender="3",enderType="NPC",enderId=31084,poiX=2375,poiY=-5651,wowhead="https://www.wowhead.com/wotlk/quest=13166",image="assets/images/quests/placeholder.png",xpDiff=7,money=25000,desc="The Hall of Command has been secured, but the Lich King has left us a little present in the Heart of Acherus. The stitched terror, Patchwerk, and a horde of abominations have taken over the second floor.$B$BUse the teleporter to get to the second floor and destroy the Scourge forces that remain. Do not engage Patchwerk alone! You must fight the monstrosity with other death knights of Acherus!$B$BGo, $N. You have my strength to carry you!",logDesc="Slay 10 Scourge and help kill Patchwerk. Return to Highlord Darion Mograine should you succeed."} end
if not DB[13167] then DB[13167]={id=13167,zoneId=4277,name="Death to the Traitor King",level=74,minLevel=72,giver="Kilix the Unraveler",giverType="NPC",giverId=26653,ender="Kilix the Unraveler",enderType="NPC",enderId=26653,poiX=3676,poiY=2159,wowhead="https://www.wowhead.com/wotlk/quest=13167",image="assets/images/quests/placeholder.png",xpDiff=8,money=224000,desc="Anub'arak, the traitor king, makes his home in the once proud underland of Azjol-Nerub.$b$bSince his betrayal, he has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who, like their leader, have pledged themselves to serving the Lich King.$b$bBring an end to the traitor king's reign, $c. You will be doing a great service to both of our peoples.$b$bIf you manage to succeed where all others have failed, bring me the husk of Anub'arak.",logDesc="Kilix the Unraveler in the Pit of Narjun has tasked you with defeating Anub'arak in Azjol-Nerub. You are to return to Kilix with Anub'arak's Broken Husk.",choiceRewards={{id=44358,qty=1},{id=44359,qty=1},{id=44360,qty=1},{id=44361,qty=1}}} end
if not DB[13168] then DB[13168]={id=13168,zoneId=210,name="Parting Gifts",level=80,minLevel=77,giver="Keritose Bloodblade",giverType="NPC",giverId=30946,ender="Keritose Bloodblade",enderType="NPC",enderId=30946,poiX=8401,poiY=2681,wowhead="https://www.wowhead.com/wotlk/quest=13168",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Look what we have here... eyes of dominion. The Cult normally goes to great lengths to keep these things safe, but I suppose their options for retreat are few when we're slaughtering them in their own home.$B$BThe eyes allow a being of any relative power to control an undead minion's actions precisely. As you can imagine, this can be extremely useful when it comes to your typical clumsy ghoul or skeleton.$B$BCare to try your hand at it? Use one of the eyes to control a captured shade.",logDesc="Keritose Bloodblade at the Shadow Vault wants you to use an Eye of Dominion to take control of a captured Eidolon Watcher."} end
if not DB[13169] then DB[13169]={id=13169,zoneId=210,name="An Undead's Best Friend",level=80,minLevel=77,giver="Keritose Bloodblade",giverType="NPC",giverId=30946,ender="Keritose Bloodblade",enderType="NPC",enderId=30946,poiX=8401,poiY=2681,wowhead="https://www.wowhead.com/wotlk/quest=13169",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="As is usual practice, the undead at the saronite quarry to the southwest starve plaguehounds to keep them extra aggressive. Use the shade to get up close and feed some of those hounds and I promise you they'll be content to leave you alone, if not side with the hand that fed them.$B$BDon't get too close to those things until you've fed them though. Their noses don't fall victim to your shade's elusiveness.",logDesc="Keritose Bloodblade at the Shadow Vault wants you to use the Eidolon Watcher to feed 18 Hungering Plaguehounds."} end
if not DB[13170] then DB[13170]={id=13170,zoneId=210,name="Honor is for the Weak",level=80,minLevel=77,giver="Keritose Bloodblade",giverType="NPC",giverId=30946,ender="Keritose Bloodblade",enderType="NPC",enderId=30946,poiX=8401,poiY=2681,wowhead="https://www.wowhead.com/wotlk/quest=13170",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Ghouls are fragile things when it comes down to it, and the lookouts at the saronite quarry down the path to the southwest are no exception. Using one of the shades, I have no doubt that you can sneak up and put down their lookouts without making a sound.$B$BClear out as many lookouts as you can reach in a reasonable amount of time... we'll want their ranks thinned for our assault to come.",logDesc="Keritose Bloodblade at the Shadow Vault would like you to assassinate 20 Restless Lookouts."} end
if not DB[13171] then DB[13171]={id=13171,zoneId=210,name="From Whence They Came",level=80,minLevel=77,giver="Keritose Bloodblade",giverType="NPC",giverId=30946,ender="Keritose Bloodblade",enderType="NPC",enderId=30946,poiX=8401,poiY=2681,wowhead="https://www.wowhead.com/wotlk/quest=13171",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="My main concern is the saronite quarry down the path to the southwest. They are pulling up immense amounts of ore from that quarry and I'd like to know what they're building with it. To that end, we'll start by weakening their defenses.$B$BI noticed a series of crystals scattered throughout the base and I assume they are defensive structures of some sort, not unlike ziggurats. Use the eidolon watcher to destroy any of those crystals that you find.",logDesc="Keritose Bloodblade at the Shadow Vault has sent you to banish 10 Scourge Containment Crystals."} end
if not DB[13172] then DB[13172]={id=13172,zoneId=210,name="Seeds of Chaos",level=80,minLevel=77,giver="Keritose Bloodblade",giverType="NPC",giverId=30946,ender="Keritose Bloodblade",enderType="NPC",enderId=30946,poiX=8401,poiY=2681,wowhead="https://www.wowhead.com/wotlk/quest=13172",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Effective tool, is it not? Excellent job weakening their defenses, $c. Now we can push the main assault.$B$BThe plan here is straight-foward - we're looking to destroy anything moving, and get in there and steal some information amidst the confusion.$B$BLet me know when you're ready and I'll set you up with a skeletal gryphon.",logDesc="Keritose Bloodblade at the Shadow Vault has dispatched you to slaughter 80 undead in the Weeping Quarry. Speak to him to secure a skeletal gryphon for the assault.",choiceRewards={{id=43872,qty=1},{id=43905,qty=1},{id=43976,qty=1},{id=43941,qty=1},{id=43923,qty=1}}} end
if not DB[13173] then DB[13173]={id=13173,zoneId=210,name="Amidst the Confusion",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13173",image="assets/images/quests/placeholder.png",desc="We got our hands on quite a few workers. They should do nicely.$B$BI want you to use an eye to bring one of these workers back into the quarry. With the entire camp in disarray, there's no way they'll be able to distinguish you from any of the other workers that were scattered by the assault.$B$BFind whoever is in charge of the operation and get to work. With any luck, we'll find out where that Saronite is being shipped off to pretty quickly. I'll watch over your shoulder through the eye."} end
if not DB[13174] then DB[13174]={id=13174,zoneId=210,name="Amidst the Confusion",level=80,minLevel=77,giver="Keritose Bloodblade",giverType="NPC",giverId=30946,ender="Keritose Bloodblade",enderType="NPC",enderId=30946,poiX=8401,poiY=2681,wowhead="https://www.wowhead.com/wotlk/quest=13174",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Shutting down their operation is just half of the plan. The other important goal here is to find out where all that saronite is being sent. We know of a few places it's been ending up, but the amount they're pulling out suggests to me that there's a bigger project in the works.$B$BOnce you're inside the quarry, get your hands on any of their documents that you can find. If you're assaulting the place with one of the gryphons, you can drop down from it as soon as the wetwork is done.",logDesc="Keritose Bloodblade at the Shadow Vault has requested a Weeping Quarry Document, a Weeping Quarry Ledger, a Weeping Quarry Map, and a Weeping Quarry Schedule."} end
if not DB[13175] then DB[13175]={id=13175,zoneId=210,name="Regaining Control",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13175",image="assets/images/quests/placeholder.png"} end
if not DB[13176] then DB[13176]={id=13176,zoneId=210,name="Preparing the Delivery",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13176",image="assets/images/quests/placeholder.png"} end
if not DB[13177] then DB[13177]={id=13177,zoneId=4197,name="No Mercy for the Merciless",level=80,minLevel=78,giver="Commander Zanneth",giverType="NPC",giverId=31036,ender="Commander Zanneth",enderType="NPC",enderId=31036,poiX=5078,poiY=2184,wowhead="https://www.wowhead.com/wotlk/quest=13177",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Welcome to the Wintergrasp Fortress, $n. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!",logDesc="Commander Zanneth in Wintergrasp Fortress wants you to slay 10 members of the Horde.",rewards={{id=43228,qty=10}}} end
if not DB[13178] then DB[13178]={id=13178,zoneId=4197,name="Slay them all!",level=80,minLevel=78,giver="Commander Dardosh",giverType="NPC",giverId=31091,ender="Commander Dardosh",enderType="NPC",enderId=31091,poiX=5360,poiY=2858,wowhead="https://www.wowhead.com/wotlk/quest=13178",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Welcome to the Wintergrasp Fortress, $n. Warlord Garrosh demands one thing: Slay them all!$B$BReturn to me when ten of the strongest members of the Alliance are dead.",logDesc="Commander Dardosh in Wintergrasp Fortress wants you to slay 10 members of the Alliance.",rewards={{id=43228,qty=10}}} end
