if not DB[13180] then DB[13180]={id=13180,zoneId=4197,name="Slay them all!",level=80,minLevel=78,giver="Commander Dardosh",giverType="NPC",giverId=31091,ender="Commander Dardosh",enderType="NPC",enderId=31091,poiX=5360,poiY=2858,wowhead="https://www.wowhead.com/wotlk/quest=13180",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Welcome to the Wintergrasp, $n. Warlord Garrosh demands one thing: Slay them all!$B$BReturn to me when ten of the strongest members of the Alliance are dead.",logDesc="Commander Dardosh in Wintergrasp wants you to slay 10 members of the Alliance.",rewards={{id=43228,qty=10}}} end
if not DB[13181] then DB[13181]={id=13181,zoneId=4197,name="Victory in Wintergrasp",level=80,minLevel=78,giver="Tactical Officer Ahbramis",giverType="NPC",giverId=31153,ender="Tactical Officer Ahbramis",enderType="NPC",enderId=31153,poiX=5088,poiY=2188,wowhead="https://www.wowhead.com/wotlk/quest=13181",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Commander Zanneth might be satisfied with a pile of Horde corpses at his feet, but controlling Wintergrasp is of the utmost importance to the Valiance Expedition. Make sure it remains in our control.$B$BHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.",logDesc="Win a Wintergrasp battleground match and return to Tactical Officer Abrahmis in Wintergrasp. You must have participated in the battle to be credited for the victory.",rewards={{id=43228,qty=10}}} end
if not DB[13182] then DB[13182]={id=13182,zoneId=4277,name="Don't Forget the Eggs!",level=74,minLevel=72,giver="Kilix the Unraveler",giverType="NPC",giverId=26653,ender="Kilix the Unraveler",enderType="NPC",enderId=26653,poiX=3676,poiY=2159,wowhead="https://www.wowhead.com/wotlk/quest=13182",image="assets/images/quests/placeholder.png",xpDiff=8,money=224000,desc="Throughout Azjol-Nerub, the scourged nerubians carefully nurture eggs that will soon hatch, providing them even greater numbers.$b$bIt would do little good for the caverns to be cleansed of the undead that stain them if these fouled eggs were left to hatch and take their place.$b$bAs you  explore the expanse that was once Azjol-Nerub, be sure to clear our ancient home of any scourge eggs you find.",logDesc="Kilix the Unraveler in the Pit of Narjun wants you to enter Azjol-Nerub and destroy 6 Nerubian Scourge Eggs.",choiceRewards={{id=44362,qty=1},{id=44363,qty=1},{id=44364,qty=1},{id=44365,qty=1}}} end
if not DB[13183] then DB[13183]={id=13183,zoneId=4197,name="Victory in Wintergrasp",level=80,minLevel=78,giver="Tactical Officer Kilrath",giverType="NPC",giverId=31151,ender="Tactical Officer Kilrath",enderType="NPC",enderId=31151,poiX=5363,poiY=2835,wowhead="https://www.wowhead.com/wotlk/quest=13183",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="While Dardosh might be content with slaying our foes, it is of the utmost importance that we control Wintergrasp Fortress. Do whatever it takes to ensure Wintergrasp is ours.$B$BHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.",logDesc="Win a Wintergrasp battleground match and return to Tactical Officer Kilrath in Wintergrasp. You must have participated in the battle to gain credit for the victory.",rewards={{id=43228,qty=10}}} end
if not DB[13184] then DB[13184]={id=13184,zoneId=210,name="Outliving Usefulness",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13184",image="assets/images/quests/placeholder.png"} end
if not DB[13185] then DB[13185]={id=13185,zoneId=4197,name="Stop the Siege",level=80,minLevel=78,giver="Lieutenant Murp",giverType="NPC",giverId=31107,ender="Lieutenant Murp",enderType="NPC",enderId=31107,poiX=5230,poiY=2877,wowhead="https://www.wowhead.com/wotlk/quest=13185",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I hears dem! The Alliance come soon. Destroy three Alliance siege devices and come back to Murp.",logDesc="Lieutenant Murp in Wintergrasp Fortress wants you to destroy 3 Alliance siege machines.",rewards={{id=43228,qty=10}}} end
if not DB[13186] then DB[13186]={id=13186,zoneId=4197,name="Stop the Siege",level=80,minLevel=78,giver="Senior Demolitionist Legoso",giverType="NPC",giverId=31109,ender="Senior Demolitionist Legoso",enderType="NPC",enderId=31109,poiX=5080,poiY=2199,wowhead="https://www.wowhead.com/wotlk/quest=13186",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="It is only a matter of time before this castle is besieged by the forces of the Horde. Destroy three of their siege devices and return to me.",logDesc="Senior Demolitionist Legoso in Wintergrasp Fortress wants you to destroy 3 Horde siege machines.",rewards={{id=43228,qty=10}}} end
if not DB[13187] then DB[13187]={id=13187,zoneId=4494,name="The Faceless Ones",level=76,minLevel=73,giver="Kilix the Unraveler",giverType="NPC",giverId=26653,ender="Kilix the Unraveler",enderType="NPC",enderId=26653,poiX=3676,poiY=2159,wowhead="https://www.wowhead.com/wotlk/quest=13187",image="assets/images/quests/placeholder.png",xpDiff=8,money=248000,desc="In my peoples' struggle against the forces of the undead, they dug deeper as they lost ground. In desperation, they dug too deep.$b$bWe inadvertently exposed a tendril of the old god's will, which was made manifest in the creatures known only as the Faceless.$b$bIn the end, we could not fight on two fronts against such powerful enemies. Our misfortune cost us the war against the undead, and ultimately, our home.$b$bEnter Ahn'kahet, $c, and cleanse our former home of these Faceless atrocities.",logDesc="Kilix the Unraveler in the Pit of Narjun wants you to kill Herald Volazj and the three Forgotten Ones that accompany him in Ahn'Kahet.",choiceRewards={{id=44350,qty=1},{id=44351,qty=1},{id=44352,qty=1},{id=44353,qty=1}}} end
if not DB[13188] then DB[13188]={id=13188,zoneId=-372,name="Where Kings Walk",level=55,minLevel=55,giver="3",giverType="NPC",giverId=31084,ender="3",enderType="NPC",enderId=29611,poiX=2375,poiY=-5651,wowhead="https://www.wowhead.com/wotlk/quest=13188",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You are now, and forever will be, a Knight of the Ebon Blade, $N, but know this: you were once a hero of the Alliance.$B$B<Darion stares at you.>$B$BThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Alliance.$B$BOn the platform, southeast of me, is a portal to Stormwind City. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to King Varian Wrynn. Use the portal.",logDesc="Deliver the letter to King Varian Wrynn of the Alliance at Stormwind Keep in Stormwind City."} end
if not DB[13189] then DB[13189]={id=13189,zoneId=-372,name="Warchief's Blessing",level=55,minLevel=55,giver="3",giverType="NPC",giverId=31084,ender="Thrall",enderType="NPC",enderId=4949,poiX=2375,poiY=-5651,wowhead="https://www.wowhead.com/wotlk/quest=13189",image="assets/images/quests/placeholder.png",xpDiff=7,desc="You are now, and forever will be, a Knight of the Ebon Blade, $N, but know this: you were once a hero of the Horde.$B$B<Darion stares at you.>$B$BThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Horde.$B$BOn the platform, southeast of me, is a portal to Orgrimmar. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to Thrall. Use the portal.",logDesc="Deliver the letter to Thrall, Warchief of the Horde at Orgrimmar."} end
if not DB[13190] then DB[13190]={id=13190,zoneId=4494,name="All Things in Good Time",level=80,minLevel=80,giver="Kilix the Unraveler",giverType="NPC",giverId=26653,ender="Kilix the Unraveler",enderType="NPC",enderId=26653,poiX=3676,poiY=2159,wowhead="https://www.wowhead.com/wotlk/quest=13190",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="Ahn'kahet, from whence we came...$b$bOne day, I dream, we shall overcome the death and darkness that hold our ancient home in their grip. To that end, I have a plan to weaken the resolve of our enemies.$b$bTheir precious Watchers must burn!$b$bTake their corpses and place them upon the brazier deep within the city. The scent of their burnt remains will linger in the air, reminding our enemy of their weakness.$b$bBe mindful, $c! Their undead corpses are most fragile and will deteriorate rapidly.",logDesc="Kilix the Unraveler in the Pit of Narjun wants you to obtain an Ahn'kahar Watcher's Corpse and place it upon the Ahn'kahet Brazier in Ahn'kahet.$b$bThis quest can only be completed on Heroic Difficulty."} end
if not DB[13191] then DB[13191]={id=13191,zoneId=4197,name="Fueling the Demolishers",level=80,minLevel=78,giver="Siegesmith Stronghoof",giverType="NPC",giverId=31106,ender="Commander Dardosh",enderType="NPC",enderId=31091,poiX=5296,poiY=2927,wowhead="https://www.wowhead.com/wotlk/quest=13191",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Lok'tar, $n! While the battle may be over, we must prepare for the Alliance's next assault! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.$B$BThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. $B$BWe've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!",logDesc="Siegesmith Stronghoof at Wintergrasp Fortress wants you to retrieve 10 Eternal Embers from Alliance players in the Cauldron of Flames.",rewards={{id=43228,qty=10}}} end
if not DB[13192] then DB[13192]={id=13192,zoneId=4197,name="Warding the Walls",level=80,minLevel=78,giver="Hoodoo Master Fu'jin",giverType="NPC",giverId=31101,ender="Hoodoo Master Fu'jin",enderType="NPC",enderId=31101,poiX=5297,poiY=2790,wowhead="https://www.wowhead.com/wotlk/quest=13192",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Hey 'mon. This place be givin' me dah heebie jeebies, don't cha know?$B$BWay too many spirits haunting dis place. I want ta be placing hoodoo wards up, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.$B$BThe Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, mebbe they be havin' the stuff we need.$B$BBring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.",logDesc="Hoodoo Master Fu'jin at Wintergrasp Fortress wants you to retrieve 10 Enchanted Alliance Breastplates at the Glacial Falls.",rewards={{id=43228,qty=10}}} end
if not DB[13193] then DB[13193]={id=13193,zoneId=4197,name="Bones and Arrows",level=80,minLevel=78,giver="Vieron Blazefeather",giverType="NPC",giverId=31102,ender="Vieron Blazefeather",enderType="NPC",enderId=31102,poiX=5297,poiY=2731,wowhead="https://www.wowhead.com/wotlk/quest=13193",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. $n, I am in need of dragon bone for our arrowheads.$B$BTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.$B$BIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.",logDesc="Lieutenant Vieron Blazefeather at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players in the Forest of Shadows.",rewards={{id=43228,qty=10}}} end
if not DB[13194] then DB[13194]={id=13194,zoneId=4197,name="Healing with Roses",level=80,minLevel=78,giver="Primalist Mulfort",giverType="NPC",giverId=31053,ender="Primalist Mulfort",enderType="NPC",enderId=31053,poiX=5380,poiY=3027,wowhead="https://www.wowhead.com/wotlk/quest=13194",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Between the battles, one might almost believe that there was hope for peace in this land. Sadly, that is not to be our fate.$B$BTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.$B$BSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.$B$BIf that fails, perhaps a lasher or two might have one.",logDesc="Primalist Mulfort wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.",rewards={{id=43228,qty=10}}} end
if not DB[13195] then DB[13195]={id=13195,zoneId=4197,name="A Rare Herb",level=80,minLevel=78,giver="Anchorite Tessa",giverType="NPC",giverId=31054,ender="Anchorite Tessa",enderType="NPC",enderId=31054,poiX=5089,poiY=2168,wowhead="https://www.wowhead.com/wotlk/quest=13195",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="My, it is quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.$B$BHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 Horde Herb Pouches. I will grind the herbs into a medicine to protect against the cold.$B$BThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!$B$BYou may also find one on a lasher in the area.",logDesc="Anchorite Tessa in Wintergrasp wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.",rewards={{id=43228,qty=10}}} end
if not DB[13196] then DB[13196]={id=13196,zoneId=4197,name="Bones and Arrows",level=80,minLevel=78,giver="Bowyer Randolph",giverType="NPC",giverId=31052,ender="Bowyer Randolph",enderType="NPC",enderId=31052,poiX=5100,poiY=2169,wowhead="https://www.wowhead.com/wotlk/quest=13196",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.$B$BHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.$B$BHead to the Forest of Shadows and bring back any bone splinters you can find!$B$BThe Horde have been seen collecting bone splinters in the area. Slay them!",logDesc="Bowyer Randolph in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.",rewards={{id=43228,qty=10}}} end
if not DB[13197] then DB[13197]={id=13197,zoneId=4197,name="Fueling the Demolishers",level=80,minLevel=78,giver="Siege Master Stouthandle",giverType="NPC",giverId=31108,ender="Commander Zanneth",enderType="NPC",enderId=31036,poiX=5096,poiY=2193,wowhead="https://www.wowhead.com/wotlk/quest=13197",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="$n! About time you showed up. While we may have lost the last battle, we should prepare for the next! Travel to the Cauldron of Flames in southeastern Wintergrasp and retrieve several eternal embers.$B$BThe embers are mixed in with coal to fuel the Demolisher and Siege Engines. $B$BOh, and if you happen to see some of the Horde in the Cauldron, don't hesitate to slay them and take their embers. We must prevent them from holding the keep!",logDesc="Siegesmith Stouthandle in Wintergrasp wants you to retrieve 10 Eternal Embers from Horde players at the Cauldron of Flames.",rewards={{id=43228,qty=10}}} end
if not DB[13198] then DB[13198]={id=13198,zoneId=4197,name="Warding the Warriors",level=80,minLevel=78,giver="Sorceress Kaylana",giverType="NPC",giverId=31051,ender="Sorceress Kaylana",enderType="NPC",enderId=31051,poiX=5082,poiY=2174,wowhead="https://www.wowhead.com/wotlk/quest=13198",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="$n, good to see you. We must prepare for our next assault on the fortress. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been collecting armor in the area.$B$BHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.$B$BIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.",logDesc="Sorceress Kaylana in Wintergrasp wants you to retrieve 10 sets of Imbued Horde Armor at the Glacial Falls.",rewards={{id=43228,qty=10}}} end
if not DB[13199] then DB[13199]={id=13199,zoneId=4197,name="Bones and Arrows",level=80,minLevel=78,giver="Vieron Blazefeather",giverType="NPC",giverId=31102,ender="Vieron Blazefeather",enderType="NPC",enderId=31102,poiX=5297,poiY=2731,wowhead="https://www.wowhead.com/wotlk/quest=13199",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. $n, I am in need of dragon bone for our arrowheads.$B$BTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.$B$BIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.",logDesc="Lieutenant Vieron Blazefeather in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players at the Forest of Shadows.",rewards={{id=43228,qty=10}}} end
if not DB[13200] then DB[13200]={id=13200,zoneId=4197,name="Fueling the Demolishers",level=80,minLevel=78,giver="Siegesmith Stronghoof",giverType="NPC",giverId=31106,ender="Commander Dardosh",enderType="NPC",enderId=31091,poiX=5296,poiY=2927,wowhead="https://www.wowhead.com/wotlk/quest=13200",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Lok'tar, $n! While the battle may have subsided, we must prepare to retake the fortress! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.$B$BThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. $B$BWe've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!",logDesc="Siegesmith Stronghoof in Wintergrasp wants you to retrieve 10 Eternal Embers from Alliance players at the Cauldron of Flames.",rewards={{id=43228,qty=10}}} end
if not DB[13201] then DB[13201]={id=13201,zoneId=4197,name="Healing with Roses",level=80,minLevel=78,giver="Primalist Mulfort",giverType="NPC",giverId=31053,ender="Primalist Mulfort",enderType="NPC",enderId=31053,poiX=5380,poiY=3027,wowhead="https://www.wowhead.com/wotlk/quest=13201",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="So many of our braves were lost during the battle, but even more shall die if left untreated. $B$BTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.$B$BSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.$B$BIf that fails, perhaps a lasher or two might be in bloom.",logDesc="Primalist Mulfort in Wintergrasp wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.",rewards={{id=43228,qty=10}}} end
if not DB[13202] then DB[13202]={id=13202,zoneId=4197,name="Jinxing the Walls",level=80,minLevel=78,giver="Hoodoo Master Fu'jin",giverType="NPC",giverId=31101,ender="Hoodoo Master Fu'jin",enderType="NPC",enderId=31101,poiX=5297,poiY=2790,wowhead="https://www.wowhead.com/wotlk/quest=13202",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Hey 'mon. See dem Alliance sitting comfy in their keep?$B$BI think they be a bit too comfy, ya? I want ta be jinxing the place, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.$B$BThe Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, they be havin' the stuff we need.$B$BBring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.",logDesc="Hoodoo Master Fu'jin in Wintergrasp wants you to retrieve 10 Enchanted Alliance Breastplates from Alliance players at the Glacial Falls.",rewards={{id=43228,qty=10}}} end
if not DB[13203] then DB[13203]={id=13203,zoneId=-22,name="A Winter Veil Gift",level=-1,minLevel=10,wowhead="https://www.wowhead.com/wotlk/quest=13203",image="assets/images/quests/placeholder.png",rewards={{id=43504,qty=1}}} end
if not DB[13204] then DB[13204]={id=13204,zoneId=4494,name="Funky Fungi",level=76,minLevel=73,ender="Kilix the Unraveler",enderType="NPC",enderId=26653,wowhead="https://www.wowhead.com/wotlk/quest=13204",image="assets/images/quests/placeholder.png",xpDiff=8,desc="A misshapen piece of mushroom-like fungus falls from a particularly smelly, ooze-covered patch of the cave beast's flesh. Examining it, you are violently repulsed by its overwhelming stench.$b$bYou wonder to yourself if this is the kind of thing that the nerubians might find appetizing. Placing the sticky organism in your pack, you determine to find out...",logDesc="You are to collect 6 Grotesque Fungus from Savage Cave Beasts in Ahn'kahet and deliver them to Kilix the Unraveler in The Pit of Narjun."} end
if not DB[13205] then DB[13205]={id=13205,zoneId=206,name="Disarmament",level=71,minLevel=68,giver="Defender Mordun",giverType="NPC",giverId=24111,ender="Defender Mordun",enderType="NPC",enderId=24111,poiX=1138,poiY=-4988,wowhead="https://www.wowhead.com/wotlk/quest=13205",image="assets/images/quests/placeholder.png",xpDiff=8,desc="Take it from me, $g lad:lass;, them vrykul weapons be downright nasty!$b$bI've felt their edge personally, and there be somethin' unnatural about 'em. Deceptively well-balanced, wickedly sharp - just plain deadly.$b$bGet into their stronghold and if nuthin' else, pilfer some o' them weapons! Mebbe we can learn us a thing 'er two about 'em, mebbe not.$b$bBottom line - the fewer axes they be swingin' around, the better.",logDesc="Defender Mordun wants you to enter Utgarde Keep and steal 5 Vrykul Weapons",choiceRewards={{id=44374,qty=1},{id=44375,qty=1},{id=44376,qty=1},{id=44377,qty=1}}} end
if not DB[13206] then DB[13206]={id=13206,zoneId=206,name="Disarmament",level=71,minLevel=68,giver="Dark Ranger Marrah",giverType="NPC",giverId=24137,ender="High Executor Anselm",enderType="NPC",enderId=23780,wowhead="https://www.wowhead.com/wotlk/quest=13206",image="assets/images/quests/placeholder.png",xpDiff=8,money=188000,desc="We must discover the secret to these savages' weapons!$b$bIf you'd have seen how easily they cut through my companions, you'd understand my sense of urgency. Just have a look at their forge if you doubt my words.$b$bScour the place. Gather all of their arms that you can carry and bring them to Anselm for his inspection.$b$bDo not fail us, $c. Every weapon you are able to bring out of this place is one less that we must face in the field.",logDesc="Dark Ranger Marrah wants you to steal 5 Vrykul Weapons from Utgarde Keep and bring them to High Executor Anselm in Vengeance Landing.",choiceRewards={{id=44400,qty=1},{id=44401,qty=1},{id=44403,qty=1},{id=44402,qty=1}}} end
if not DB[13207] then DB[13207]={id=13207,zoneId=4264,name="Halls of Stone",level=78,minLevel=76,giver="Brann Bronzebeard",giverType="NPC",giverId=28070,ender="Brann Bronzebeard",enderType="NPC",enderId=28070,poiX=1077,poiY=474,wowhead="https://www.wowhead.com/wotlk/quest=13207",image="assets/images/quests/placeholder.png",xpDiff=8,money=272000,desc="Well now, I'm surprised to see other adventurers in a place such as this! It so happens that I could use a bit o' company for what lies ahead.$b$bIf my research on these halls is accurate, there be monumental discoveries to be made here!$b$bAssumin' I can count on ya to watch my back, you're welcome to tag along. So, what'dya say, $c? Care ta join me?",logDesc="Brann Bronzebeard wants you to accompany him as he uncovers the secrets that lie in the Halls of Stone.",choiceRewards={{id=44370,qty=1},{id=44371,qty=1},{id=44372,qty=1},{id=44373,qty=1}}} end
if not DB[13210] then DB[13210]={id=13210,zoneId=0,name="Blizzard Account: - DEM - E - FLAG",level=1,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=13210",image="assets/images/quests/placeholder.png"} end
if not DB[13211] then DB[13211]={id=13211,zoneId=210,name="By Fire Be Purged",level=80,minLevel=77,giver="Crusader Olakin Sainrith",giverType="NPC",giverId=30708,ender="Crusader Olakin Sainrith",enderType="NPC",enderId=30708,poiX=6649,poiY=3218,wowhead="https://www.wowhead.com/wotlk/quest=13211",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Scourge uses our own fallen against us, by raising them as ghouls or skeletons, or by dismembering their corpses and using the parts to make abominations. This must stop!$B$BThe dead are heroes who fell in defense of all the living, and they cannot be confined to so grisly a fate. Moreover, we cannot afford to face them again on the field, used as weapons against us. Take this torch with you to the Fleshwerks, and burn any of the corpses you find in the Sanctum of Reanimation or the abomination lab.",logDesc="Crusader Olakin Sainrith at Blackwatch wants you to burn 7 Festering Corpses using Olakin's Torch.",choiceRewards={{id=43880,qty=1},{id=43893,qty=1},{id=43900,qty=1}}} end
if not DB[13212] then DB[13212]={id=13212,zoneId=210,name="He's Gone to Pieces",level=80,minLevel=77,giver="Darkrider Arly",giverType="NPC",giverId=30631,ender="Darkrider Arly",enderType="NPC",enderId=30631,rewardNextId=13220,poiX=6654,poiY=3225,wowhead="https://www.wowhead.com/wotlk/quest=13212",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="With the abduction of Crusader Olakin, the Argent Crusade's forces will have no commander in the final assault on the Fleshwerks. While one crusader is the same as any other to me, the argents won't see it that way.$B$BI hate to see us waste time chasing after this, but I have no choice. Our gallant crusader has likely been dismembered by now, and his remains used to construct abominations. Go down into the Fleshwerks, kill the corpulent horrors fighting our forces, and recover Olakin's body parts.",logDesc="Recover Olakin's Torso, Olakin's Legs, Olakin's Left Arm, and Olakin's Right Arm and bring them to Darkrider Arly at Blackwatch."} end
if not DB[13213] then DB[13213]={id=13213,zoneId=210,name="Battle at Valhalas",level=80,minLevel=77,giver="The Bone Witch",giverType="NPC",giverId=30232,ender="3",enderType="NPC",enderId=31135,poiX=7631,poiY=3405,wowhead="https://www.wowhead.com/wotlk/quest=13213",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I see and hear many things, $N, and something very important has happened since your defeat of Overthane Balargarde: you are wanted for battle in Valhalas!$B$BYou will find the battle pit to the north. Go now with your friends and speak with Geirrvif the val'kyr. The challengers that she will offer you within Valhalas are sure to require their help.$B$BGood luck.",logDesc="Speak with Geirrvif in Valhalas."} end
if not DB[13214] then DB[13214]={id=13214,zoneId=210,name="Battle at Valhalas: Fallen Heroes",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31135,ender="Gjonner the Merciless",enderType="NPC",enderId=31154,poiX=8216,poiY=3516,wowhead="https://www.wowhead.com/wotlk/quest=13214",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="If you believe yourself ready to begin then I have just the match for you to cut your teeth on.$B$BAnother group of outsiders thought themselves prepared for the rigors of Valhalas. They had much hubris, but in the end they fell like all of the others.$B$BIf you think yourselves so different -- if you think that you have the skill and experience to fight here amongst such storied warriors -- then please accept the challenge.",logDesc="Geirrvif at Valhalas has challenged you to, in a single combat, defeat all six of the fallen heroes: Eldreth, Geness Half-Soul, Jhadras, Masud, Rith, and Talla.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas."} end
if not DB[13215] then DB[13215]={id=13215,zoneId=210,name="Battle at Valhalas: Khit'rix the Dark Master",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31135,ender="Gjonner the Merciless",enderType="NPC",enderId=31154,poiX=8216,poiY=3516,wowhead="https://www.wowhead.com/wotlk/quest=13215",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="A variety of beings travel the world to prove themselves within Valhalas. Some even come from under the world.$B$BKhit'rix the Dark Master is one such.$B$BHailing from deep within the ground where insanity reigns, Khit'rix has asked for someone exotic to face in the ring. You will do.$B$BDare you face this Nerubian nightmare, $r?",logDesc="Geirrvif at Valhalas has challenged you to defeat Khit'rix the Dark Master.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas."} end
if not DB[13216] then DB[13216]={id=13216,zoneId=210,name="Battle at Valhalas: The Return of Sigrid Iceborn",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31135,ender="Gjonner the Merciless",enderType="NPC",enderId=31154,poiX=8216,poiY=3516,wowhead="https://www.wowhead.com/wotlk/quest=13216",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="An old foe of yours has returned: Sigrid Iceborn. Perhaps you remember besting her in a duel upon the Savage Ledge?$B$BNo matter, she certainly remembers you. She's insisting upon a chance to prove herself once more.$B$BPersonally, I think it's more a chance for revenge, but that too can be useful in this place.$B$BI leave it up to you, $N. Will you face Sigrid Iceborn once more?",logDesc="Geirrvif at Valhalas has challenged you to defeat Sigrid Iceborn.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.",choiceRewards={{id=33447,qty=5},{id=33448,qty=5}}} end
if not DB[13217] then DB[13217]={id=13217,zoneId=210,name="Battle at Valhalas: Carnage!",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31135,ender="Gjonner the Merciless",enderType="NPC",enderId=31154,poiX=8216,poiY=3516,wowhead="https://www.wowhead.com/wotlk/quest=13217",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="You've been successful up to this point, $N, but what you must face to continue to battle within Valhalas is a gigantic horror beyond imagining.$B$BI must warn you to turn away now. Carnage is a mountain of flesh constructed by the Lich King's most fiendish minds.$B$BI do not see how you and your friends will defeat it. However, the choice is yours.",logDesc="Geirrvif at Valhalas has challenged you to defeat Carnage.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas."} end
if not DB[13218] then DB[13218]={id=13218,zoneId=210,name="Battle at Valhalas: Thane Deathblow",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31135,ender="Gjonner the Merciless",enderType="NPC",enderId=31154,poiX=8216,poiY=3516,wowhead="https://www.wowhead.com/wotlk/quest=13218",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="Your skills have not gone unnoticed by the vrykul of Jotunheim, $N. Thane Banahogg has taken a personal interest in you and has insisted that he be your next match.$B$BIf you thought Carnage was bad, then you might want to go home now. Thane Banahogg's nickname is The Deathblow. I think you can guess how he earned it.$B$BDo you accept the thane's challenge?",logDesc="Geirrvif at Valhalas has challenged you to defeat Thane Banahogg, the Deathblow.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas."} end
if not DB[13219] then DB[13219]={id=13219,zoneId=210,name="Battle at Valhalas: Final Challenge",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31135,ender="Gjonner the Merciless",enderType="NPC",enderId=31154,poiX=8216,poiY=3516,wowhead="https://www.wowhead.com/wotlk/quest=13219",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="I'm afraid that your success is going to be your undoing, $N.$B$B<If the val'kyr could turn more white, she would.>$B$BWord of your success in Valhalas has reached deep into Icecrown Citadel, stirring one whom you have no desire to meet.$B$BPrince Sandoval himself is on his way at this very moment. Gjonner warned you that you should run and I cannot disagree.$B$BWhat will you do? He's on his way. Will you face the blood prince in final battle?",logDesc="Geirrvif at Valhalas has challenged you to defeat Prince Sandoval.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.",choiceRewards={{id=44382,qty=1},{id=44383,qty=1},{id=44384,qty=1},{id=44385,qty=1}}} end
if not DB[13220] then DB[13220]={id=13220,zoneId=210,name="Putting Olakin Back Together Again",level=80,minLevel=77,giver="Darkrider Arly",giverType="NPC",giverId=30631,ender="Darkrider Arly",enderType="NPC",enderId=30631,rewardNextId=13235,poiX=6654,poiY=3225,wowhead="https://www.wowhead.com/wotlk/quest=13220",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="We can't afford to waste any time putting Olakin back together. Fortunately, the Scourge has provided a perfect place for you to stitch him back together.$B$BNear the Fleshwerks' flesh giant lab is the Sanctum of Reanimation. Search the area for a spool of thread and the doctor's cleaver. Then, take Olakin's remains to the large slab in the middle of the sanctum and get to work.",logDesc="Obtain a Spool of Thread and the Doctor's Cleaver, then take them to the Sanctum of Reanimation Slab and use Olakin's remains to attempt to reanimate the crusader. Return to Darkrider Arly at Blackwatch when this task is complete."} end
if not DB[13221] then DB[13221]={id=13221,zoneId=210,name="I'm Not Dead Yet!",level=80,minLevel=77,giver="Father Kamaros",giverType="NPC",giverId=31279,ender="Absalan the Pious",enderType="NPC",enderId=31259,poiX=6718,poiY=3452,wowhead="https://www.wowhead.com/wotlk/quest=13221",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.$B$BI cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again.$B$BWill you help me make my escape before the Scourge's butchers come to finish me off?",logDesc="Escort Father Kamaros to safety and then report to Absalan the Pious aboard the Skybreaker."} end
if not DB[13222] then DB[13222]={id=13222,zoneId=4197,name="Defend the Siege",level=80,minLevel=78,giver="Senior Demolitionist Legoso",giverType="NPC",giverId=31109,ender="Senior Demolitionist Legoso",enderType="NPC",enderId=31109,poiX=5080,poiY=2199,wowhead="https://www.wowhead.com/wotlk/quest=13222",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Front and center, $n! We're beginning our assault on Wintergrasp Fortress. Those Horde animals think they can hide cowardly behind their walls? Well, I think not! We'll show them the power of Gnomish technology and smash their walls to bits!$B$BHowever, even the most powerful siege device is helpless without a crew. Pilot or protect one of our siege vehicles as it destroys three of the Horde structures.",logDesc="Senior Demolitionist Legoso in Wintergrasp wants you to pilot or protect a siege device as it destroys three structures.$B$BPlayers of private rank or higher can build siege devices at Goblin Workshops.",rewards={{id=43228,qty=10}}} end
if not DB[13223] then DB[13223]={id=13223,zoneId=4197,name="Defend the Siege",level=80,minLevel=78,giver="Lieutenant Murp",giverType="NPC",giverId=31107,ender="Lieutenant Murp",enderType="NPC",enderId=31107,poiX=5230,poiY=2877,wowhead="https://www.wowhead.com/wotlk/quest=13223",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Dem Alliance won't be long to hold that keep. Murp would smash walls, but Murp has to stay in camp. Murp wish he could smash Alliance who want to hurt Horde demolishers.$B$BYou, $n! You go in Murp's place. Protect 3 siege vehicles while they smash Alliance buildings. Alliance not expect you to defend demolisher. Show Alliance how smart Murp is! ",logDesc="Lieutenant Murp in Wintergrasp wants you to defend or pilot a siege vehicle while they destroy three Alliance structures.$B$BSiege devices can be built by ranked Horde players at the Goblin Workshops.",rewards={{id=43228,qty=10}}} end
if not DB[13224] then DB[13224]={id=13224,zoneId=210,name="Orgrim's Hammer",level=79,minLevel=77,giver="Warlord Hork Strongbrow",giverType="NPC",giverId=31240,ender="Sky-Reaver Korm Blackscar",enderType="NPC",enderId=30824,poiX=6387,poiY=462,wowhead="https://www.wowhead.com/wotlk/quest=13224",image="assets/images/quests/placeholder.png",xpDiff=2,desc="The Argent Crusade pulled my ravaged body from the Broken Front. What a glorious battle, $r. My axe sang as it cut down Alliance filth and Scourge alike.$B$BMy time is over. It will be a good death. Carry a message for me, soldier.$B$BOur base flies out of reach of Scourge - overhead between Mord'rethar and Aldur'thar. It is called \"Orgrim's Hammer.\"$B$B<Hork futilely attempts to salute.>$B$BFly high and avoid the Alliance juggernaut, Skybreaker. Tell Korm... tell him I died... fighting... For the Horde.",logDesc="Seek out Sky-Reaver Korm Blackscar aboard Orgrim's Hammer flying above Icecrown."} end
if not DB[13225] then DB[13225]={id=13225,zoneId=210,name="The Skybreaker",level=79,minLevel=77,giver="Marshal Ivalius",giverType="NPC",giverId=31241,ender="High Captain Justin Bartlett",enderType="NPC",enderId=30344,poiX=6380,poiY=465,wowhead="https://www.wowhead.com/wotlk/quest=13225",image="assets/images/quests/placeholder.png",xpDiff=2,desc="We were neck deep in Scourge and Horde. The screams of the dying covered that field. It was torturous... unrelenting!$B$BAt some point my body gave out. I fell, only to be awoken by the Argent Crusade. They pulled me out of the Broken Front and brought me here. I'm not going to make it. Grant a dying soldier one last wish, $r? Our base, the Skybreaker, flies high above Icecrown. It is there that you'll find my commanding officer, High Captain Bartlett. Tell him that I died a soldier of the Alliance.",logDesc="Seek out High Captain Justin Bartlett aboard the Skybreaker flying above Icecrown."} end
if not DB[13226] then DB[13226]={id=13226,zoneId=210,name="Judgment Day Comes!",level=78,minLevel=77,giver="Absalan the Pious",giverType="NPC",giverId=31259,ender="Highlord Tirion Fordring",enderType="NPC",enderId=28179,poiX=17,poiY=-18,wowhead="https://www.wowhead.com/wotlk/quest=13226",image="assets/images/quests/placeholder.png",xpDiff=2,desc="We cannot defeat the Lich King on our own. Divided we shall all fall!$B$BI implore you to answer the call, $g brother:sister;. The Argent Crusade accepts all who would volunteer to aid in the war effort. Highlord Tirion Fordring himself awaits you at the Argent Vanguard! Get upon your mount and fly to the southeastern reaches of Icecrown. It is there that you will find Lord Fordring and the soldiers of the Argent Crusade.$B$BGo now, $c, for judgment day comes!",logDesc="Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown."} end
if not DB[13227] then DB[13227]={id=13227,zoneId=210,name="Judgment Day Comes!",level=78,minLevel=77,giver="Brother Keltan",giverType="NPC",giverId=31261,ender="Highlord Tirion Fordring",enderType="NPC",enderId=28179,poiX=-24,poiY=-22,wowhead="https://www.wowhead.com/wotlk/quest=13227",image="assets/images/quests/placeholder.png",xpDiff=2,desc="We cannot defeat the Lich King on our own. Divided we shall all fall!$B$BI implore you answer the call, $g brother:sister;. The Argent Crusade accepts all that would volunteer to aid in the war effort. Highlord Tirion Fordring himself awaits you at the Argent Vanguard! Get upon your mount and fly to the southeastern reaches of Icecrown. It is there that you will find Lord Fordring and the soldiers of the Argent Crusade.$B$BGo now, $c, for judgment day comes!",logDesc="Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown."} end
if not DB[13228] then DB[13228]={id=13228,zoneId=210,name="The Broken Front",level=80,minLevel=77,giver="Sky-Reaver Korm Blackscar",giverType="NPC",giverId=30824,ender="Sky-Reaver Korm Blackscar",enderType="NPC",enderId=30824,poiX=56,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13228",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="What battle?! Those troops were on a recon mission!$b$bAnd what's this talk of Alliance - you're sure he said Alliance?$b$bListen to me, $n! I need to know what's going on and I need to know NOW!$b$bGet yourself down there and get me some answers! Scour the battlefield and look for survivors - clues - anything!",logDesc="Korm Blackscar on Orgrim's Hammer wants you to go to The Broken Front and question a Dying Berserker to discover what happened there."} end
if not DB[13229] then DB[13229]={id=13229,zoneId=210,name="I'm Not Dead Yet!",level=80,minLevel=77,giver="Father Kamaros",giverType="NPC",giverId=31279,ender="Brother Keltan",enderType="NPC",enderId=31261,poiX=6718,poiY=3452,wowhead="https://www.wowhead.com/wotlk/quest=13229",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.$B$BI cannot make it on my own, $c, but with your help, I may yet live to fight the Scourge again.$B$BWill you help me make my escape before the Scourge's butchers come to finish me off?",logDesc="Escort Father Kamaros to safety and then report to Brother Keltan aboard Orgrim's Hammer."} end
if not DB[13230] then DB[13230]={id=13230,zoneId=210,name="Avenge Me!",level=80,minLevel=77,giver="Dying Berserker",giverType="NPC",giverId=31273,ender="Sky-Reaver Korm Blackscar",enderType="NPC",enderId=30824,poiX=6824,poiY=1054,wowhead="https://www.wowhead.com/wotlk/quest=13230",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I hear them, $g brother:sister;....$b$bThe moans of the wounded Alliance... they taunt me...$b$bFinish what we have begun here, $c. Show no mercy... let none of them survive.$b$bFor... the Horde...",logDesc="A Dying Berserker has asked that you slay 5 Dying Soldiers at the Broken Front. Report to Sky-Reaver Korm Blackscar on Orgrim's Hammer when it is done."} end
if not DB[13231] then DB[13231]={id=13231,zoneId=210,name="The Broken Front",level=80,minLevel=77,giver="High Captain Justin Bartlett",giverType="NPC",giverId=30344,ender="High Captain Justin Bartlett",enderType="NPC",enderId=30344,poiX=44,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13231",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="What?! Noooo!$b$bWe went to such great pains to keep this attack secret. How could the Horde have known? The resources... the men... all lost? Inconceivable!$b$bOur plans here in Icecrown hinged upon our taking that gate before the Horde could. We must recover quickly and prepare to mount another offensive.$b$bVisit the battlefield and search for any survivors. See if there's anything to be learned from this tragedy.$b$bAnd prepare yourself, $n, for a war - on two fronts...",logDesc="High Captain Justin Bartlett aboard the Skybreaker wants you to go to the Broken Front and question a Dying Soldier, then report back to him."} end
if not DB[13232] then DB[13232]={id=13232,zoneId=210,name="Finish Me!",level=80,minLevel=77,giver="Dying Soldier",giverType="NPC",giverId=31304,ender="High Captain Justin Bartlett",enderType="NPC",enderId=30344,poiX=6804,poiY=952,wowhead="https://www.wowhead.com/wotlk/quest=13232",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="They taunt us - even as they lie dying here...$b$bPlease, $g brother:miss;... Don't allow their mocking to be the last sounds I hear...$b$bFinish me... deliver me from this torment... into... the Light.$b$bSeek out  my companions... offer them the same mercy.$b$bLeave nothing for the Scourge to raise!$b$bI beg you...",logDesc="A Dying Soldier in the Broken Front wants you to kill 5 Dying Soldiers and report to High Captain Justin Bartlett on the Skybreaker."} end
if not DB[13233] then DB[13233]={id=13233,zoneId=210,name="No Mercy!",level=80,minLevel=77,giver="High Captain Justin Bartlett",giverType="NPC",giverId=30344,ender="High Captain Justin Bartlett",enderType="NPC",enderId=30344,poiX=44,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13233",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="It is as I told you. They were not merely idle words spoken in a fit of anger.$b$bTime and again, the Horde have demonstrated their disdain for everything we hold dear and holy. They must pay with their lives for their transgressions against the light.$b$bAll of them.$b$bJust imagine a world free of their stain, $n. Envision the joy our children will know. Think of the reverence your descendants will have for your memory, knowing they owe their happiness to you.$b$bNow go, and make that vision a reality!",logDesc="High Captain Justin Bartlett aboard the Skybreaker wants you to kill 15 Horde Players in Icecrown."} end
if not DB[13234] then DB[13234]={id=13234,zoneId=210,name="Make Them Pay!",level=80,minLevel=77,giver="Sky-Reaver Korm Blackscar",giverType="NPC",giverId=30824,ender="Sky-Reaver Korm Blackscar",enderType="NPC",enderId=30824,poiX=56,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13234",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The time has come!$b$bToo long have we suffered the company of the self-righteous Alliance! Too long have we stayed our hand from cleansing our world of the weak and the desperate.$b$bNow, we bring an end to our humiliation! Now, we show them the true meaning of fear! Now, we bring honor to the Horde!$b$bHere, at Icecrown, we break the Alliance!$b$bGo, $c. Hunt them down. Break them. Take their will to live!",logDesc="Sky-Reaver Korm Blackscar wants you to kill 15 Alliance Players in Icecrown."} end
if not DB[13235] then DB[13235]={id=13235,zoneId=210,name="The Flesh Giant Champion",level=80,minLevel=77,giver="Darkrider Arly",giverType="NPC",giverId=30631,ender="Darkrider Arly",enderType="NPC",enderId=30631,poiX=6654,poiY=3225,wowhead="https://www.wowhead.com/wotlk/quest=13235",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="You've done well in destroying the Fleshwerks and slaughtering the Lich King's servants. Now, all that remains is to defeat the Fleshwerks' greatest accomplishment -- the flesh giant known as Morbidus.$B$BIt will not be an easy fight, but the Shadow Vault has dispatched Margrave Dhakar with some reinforcements. Meet up with him at the highest point at the western end of the Fleshwerks. Tell him when you're ready to begin the attack and he'll order his forces into battle.",logDesc="Speak with Margrave Dhakar at the western end of the Fleshworks to engage Morbidus. After you have defeated Morbidus, report to Darkrider Arly at Blackwatch.",choiceRewards={{id=44378,qty=1},{id=44379,qty=1},{id=44380,qty=1},{id=44381,qty=1}}} end
if not DB[13236] then DB[13236]={id=13236,zoneId=210,name="Army of the Damned",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32404,ender="Matthias Lehner",enderType="NPC",enderId=32404,rewardNextId=13348,poiX=7588,poiY=1398,wowhead="https://www.wowhead.com/wotlk/quest=13236",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.$B$BThat is nothing compared to the strength it took to create them.$B$BI saw the prince do it himself.  I can show you how it happened... if you'd like.",logDesc="Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions."} end
if not DB[13237] then DB[13237]={id=13237,zoneId=210,name="Poke and Prod",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13237",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="While your commander has his focus diluted by his loathing of your Alliance rivals, you can depend on me to direct my attention squarely on the real enemy here - the Lich King and his minions.$b$bIn order to hold any hope of conquering him at the citadel, your people must take and hold each gate.$b$bFor now, let us focus on the first. Return to the front and prod their defenses. Look for any sign of weakness that we might exploit.$b$bI'll await your report, $c.",logDesc="Koltira Deathweaver aboard Orgrim's Hammer wants you to go the Broken Front and defeat 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts.",choiceRewards={{id=43903,qty=1},{id=43889,qty=1},{id=43884,qty=1}}} end
if not DB[13238] then DB[13238]={id=13238,zoneId=210,name="Good For Something?",level=80,minLevel=77,giver="Sky-Reaver Korm Blackscar",giverType="NPC",giverId=30824,ender="Chief Engineer Copperclaw",enderType="NPC",enderId=30825,rewardNextId=13239,poiX=56,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13238",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Goblins! Hyper little busy-bodies...$b$bListen, $n. Copperclaw, our resident engineer, is insisting that he's got something useful to show me.$b$bI'm in no mood to endure his squeaky nagging. The last time I acknowledged him, he chirped on for an hour straight. It was all I could do to keep from drop-kicking him into Sindragosa's Fall!$b$bYou go in my place and humor him. Let me know if indeed he's on to anything.",logDesc="Sky-Reaver Korm Blackscar wants you to speak with Chief Engineer Copperclaw aboard Orgrim's Hammer."} end
if not DB[13239] then DB[13239]={id=13239,zoneId=210,name="Volatility",level=80,minLevel=77,giver="Chief Engineer Copperclaw",giverType="NPC",giverId=30825,ender="Chief Engineer Copperclaw",enderType="NPC",enderId=30825,poiX=38,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13239",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Where to begin... well, you must know that as chief engineer of this vessel I have access to all of the intelligence reports - yes, yes, it's true, and I've recently taken a particular interest in the frostwyrms you reported seeing to the south, and I do believe I've developed a plan that just might work against them... now it'll take a little legwork on your part, but essentially, you build a dummy out of armor and coat it with a splash of this solution, then run for cover!$b$b...You still here, $r?",logDesc="Chief Engineer Copperclaw wants you to use Copperclaw's Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.$b$bTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.",choiceRewards={{id=38736,qty=1},{id=39035,qty=1},{id=39065,qty=1},{id=39100,qty=1}}} end
if not DB[13240] then DB[13240]={id=13240,zoneId=4228,name="Timear Foresees Centrifuge Constructs in your Future!",level=80,minLevel=78,wowhead="https://www.wowhead.com/wotlk/quest=13240",image="assets/images/quests/placeholder.png",xpDiff=7,money=148000,desc="It is into the Oculus floating above Coldarra that you must travel, $N.$B$BI have foreseen a situation in which you must destroy the centrifuge constructs therein. I can assure you that if you do not first eliminate these magical creations, you and your friends will fail.$B$BThus I have seen, thus you must do.",logDesc="Archmage Timear in Dalaran has foreseen that you must destroy 10 Centrifuge Constructs.",rewards={{id=47241,qty=1}},choiceRewards={{id=43950,qty=1},{id=44711,qty=1},{id=44713,qty=1},{id=44710,qty=1},{id=49702,qty=1}}} end
if not DB[13241] then DB[13241]={id=13241,zoneId=1196,name="Timear Foresees Ymirjar Berserkers in your Future!",level=80,minLevel=78,wowhead="https://www.wowhead.com/wotlk/quest=13241",image="assets/images/quests/placeholder.png",xpDiff=7,money=148000,desc="King Ymiron's champions stand between you and victory in the not-too-distant future.$B$BYou will travel to the fortress known as Utgarde Pinnacle nestled deep within the woods of the Howling Fjord. I cannot stress how important it is that you and your traveling companions deal with the Ymirjar berserkers therein.$B$BFailure to do so may very well doom you, $N!",logDesc="Archmage Timear in Dalaran wants you to slay 7 Ymirjar Berserkers.",rewards={{id=47241,qty=1}},choiceRewards={{id=43950,qty=1},{id=44711,qty=1},{id=44713,qty=1},{id=44710,qty=1},{id=49702,qty=1}}} end
if not DB[13242] then DB[13242]={id=13242,zoneId=65,name="Darkness Stirs",level=74,minLevel=71,giver="3",giverType="NPC",giverId=31333,ender="High Overlord Saurfang",enderType="NPC",enderId=25256,rewardNextId=13257,poiX=4855,poiY=1472,wowhead="https://www.wowhead.com/wotlk/quest=13242",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Darkness stirs, $N. A tragic event has transpired that none but the Timeless One could have foreseen. Soon your people will be gripped by anger and hatred. War is on the horizon.$B$BThe red dragonflight has done all that it can. What happens next is in the hands of the mortal races of Azeroth.$B$BRegrettably, your journey begins with anguish. A father has lost a child today. You must bear the grim news. Gather the armaments of Saurfang and return them to the elder Saurfang. $B",logDesc="Gather Saurfang's Battle Armor from the field of battle and return it to High Overlord Saurfang at Warsong Hold in Borean Tundra."} end
if not DB[13243] then DB[13243]={id=13243,zoneId=4100,name="Timear Foresees Infinite Agents in your Future!",level=80,minLevel=78,wowhead="https://www.wowhead.com/wotlk/quest=13243",image="assets/images/quests/placeholder.png",xpDiff=7,money=148000,desc="The timeline is in danger from the Infinite dragonflight. Without your intervention, all of time will unravel!$B$BYou must travel to a point in time known as the Culling of Stratholme within the Caverns of Time.$B$BIt gives me a migraine just to attempt to see into all of the possible pasts, but I do know that it is crucial for you to kill the Infinite agents.$B$BOnly by slaying them will the true past be preserved and the present and future kept from being undone forever!",logDesc="Archmage Timear in Dalaran has foreseen that you must slay 4 Infinite Agents.",rewards={{id=47241,qty=1}},choiceRewards={{id=43950,qty=1},{id=44711,qty=1},{id=44713,qty=1},{id=44710,qty=1},{id=49702,qty=1}}} end
if not DB[13244] then DB[13244]={id=13244,zoneId=4272,name="Timear Foresees Titanium Vanguards in your Future!",level=80,minLevel=78,wowhead="https://www.wowhead.com/wotlk/quest=13244",image="assets/images/quests/placeholder.png",xpDiff=7,money=148000,desc="The entirety of Azeroth is in peril. The mad god Loken has it within his power to put an end to everything!$B$BWithin the Terrestrial Watchtower at the Halls of Lightning, the titanium vanguards stand poised to execute Loken's dread will upon countless unknowing victims.$B$BI have looked into the future, $N. You are the one to see that this does not come to pass!",logDesc="Archmage Timear in Dalaran has foreseen that you must slay 7 Titanium Vanguards.",rewards={{id=47241,qty=1}},choiceRewards={{id=43950,qty=1},{id=44711,qty=1},{id=44713,qty=1},{id=44710,qty=1},{id=49702,qty=1}}} end
if not DB[13245] then DB[13245]={id=13245,zoneId=206,name="Proof of Demise: Ingvar the Plunderer",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13245",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="I need you to assemble a group and lead them into Utgarde Keep. Therein, you are to find and slay Ingvar the Plunderer before he can lead his vrykul forces to sack the nearby Alliance and Horde towns.$B$BI require his axe as proof that he has been dealt with. It's not that I don't trust you. It's simply prudent to be certain that the deed has been done.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with the Axe of the Plunderer.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13246] then DB[13246]={id=13246,zoneId=4265,name="Proof of Demise: Keristrasza",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13246",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="Are you familiar with the story of Keristrasza?$B$BHow she was instrumental in the slaying of Saragosa, the mate of Malygos? How, in turn, he took Keristrasza as his consort, freezing her within a block of ice?$B$BWe have become aware that Malygos has been using his magic to break her will. This has driven her insane.$B$B$N, you must go into the Nexus in Coldarra and put an end to her before she can be fully turned.$B$BThough it saddens me, I must insist that you bring me her heart as proof.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with Keristrasza's Broken Heart.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13247] then DB[13247]={id=13247,zoneId=4228,name="Proof of Demise: Ley-Guardian Eregos",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13247",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="The Nexus War rages on and we must do something to turn the tide! Are you willing to fly into the heart of the battle, $N?$B$BLey-Guardian Eregos is the protector of the conduit through which Malygos is funneling the magical power of Azeroth's ley lines. If he can be slain it will be a great blow to the enemy.$B$BPlease bring me one of his ley line tuners so that we might study it.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with a Ley Line Tuner.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13248] then DB[13248]={id=13248,zoneId=1196,name="Proof of Demise: King Ymiron",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13248",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="King Ymiron of Utgarde Pinnacle is the favored vrykul of the Lich King. That alone is reason enough to put an end to him.$B$BBut should he blow the horns and call for all of the leaders of the ymirjar and mjordin alike, the vrykul will become a force more powerful than any other within the Scourge!$B$BIt is up to you, $N, to see to it that this does not come to pass. Bring me the locket from around his neck so that I will know that Ymiron no longer poses a threat.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with the Locket of the Deceased Queen.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13249] then DB[13249]={id=13249,zoneId=4196,name="Proof of Demise: The Prophet Tharon'ja",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13249",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="Drak'Tharon Keep once stood as a proud bastion of the Drakkari nation. Now it is nothing more than a stepping stone for the Lich King in his fight to put an end to Zul'Drak and steal the powers of the troll gods.$B$BBut if we were to eliminate their leader, the Prophet Tharon'ja, perhaps we could stop the flow of Scourge troll reinforcements. At the very least this would give the Argent Crusade in Zul'Drak one less thing to worry about.$B$BReturn to me with his tiki so I will know the prophet is slain.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with the Prophet's Enchanted Tiki.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13250] then DB[13250]={id=13250,zoneId=4416,name="Proof of Demise: Gal'darah",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13250",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="The Drakkari prophets of Zul'Drak have done the unthinkable: they've slain most of their gods to absorb their powers! The most dangerous of all is the High Prophet of Akali, Gal'darah.$B$BSequestered within the bowels of Gundrak, Gal'darah has absorbed almost all of the mojo from slain Akali and now stands poised to erupt with his followers from the city. If we do not kill him now, we will be awash in a sea of madness and unthinkable power!$B$BHurry, $N, bring me what's left of Akali's mojo.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with the Mojo Remnant of Akali.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13251] then DB[13251]={id=13251,zoneId=4100,name="Proof of Demise: Mal'Ganis",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13251",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="$N, a friend within the bronze dragonflight has given me information that we must exploit.$B$BThe mysterious beings of the Burning Legion called the dreadlords are also known racially as the Nathrezim. Little is known of their homeworld and even that is rumor.$B$BHowever, it is known that Mal'Ganis of the past has made a critical error: he left behind an artifact from his homeworld!$B$BThrough the Caverns of Time, you must travel back to the time known as the Culling of Stratholme. Recover the artifact.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with the Artifact from the Nathrezim Homeworld.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13252] then DB[13252]={id=13252,zoneId=4264,name="Proof of Demise: Sjonnir The Ironshaper",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13252",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="Little is understood about the condition known as the Curse of Flesh. However, there is information to be had within the Halls of Stone.$B$BSjonnir The Ironshaper seems to know a great deal with regard to the curse. We have it on good authority that he is carrying a Titan disc of information upon him that could answer all of our questions.$B$BRetrieve this disc for me, $N, so that we may learn.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with the Curse of Flesh Disc.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13253] then DB[13253]={id=13253,zoneId=4272,name="Proof of Demise: Loken",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13253",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="Within the Halls of Lightning, Loken is poised to put an end to our world. Need I say more, $N?$B$BHe sits there listening to the mad whisperings of the Old God trapped beneath Northrend. You and your friends must travel to the Storm Peaks immediately!$B$BConfront Loken within the Terrestrial Watchtower and stop him before it is too late! Bring me his ruby ring so that I will know we are safe once more.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with the Celestial Ruby Ring.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13254] then DB[13254]={id=13254,zoneId=4277,name="Proof of Demise: Anub'arak",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13254",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="The Scourged nerubians are a plague upon our forces.$B$BWhile we are safe from them here, floating above the world, when we set foot upon the land below, it is always with the thought that the undead nerubians could burrow up from the depths of Azjol-Nerub and attack.$B$BIt's in the best interests of everyone if they are thrown into a state of disarray. Kill their former king, and major-domo to the Lich King, the crypt lord, Anub'arak.$B$BPlease bring me his crown... not that he wears it any longer.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with the Idle Crown of Anub'arak.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13255] then DB[13255]={id=13255,zoneId=4494,name="Proof of Demise: Herald Volazj",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13255",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="The nerubians of Ahn'kahet dug too deep during their attempt to escape the invasion of the Scourge. They got too close to the Old God under Northrend.$B$BRousing its awareness, the Old God sent its insane creatures against them, and the nerubians were caught between the proverbial rock and a hard place.$B$BThe leader of the Old Gods' forces, Herald Volazj is one of the nightmarish beings known as The Faceless. Put an end to him and bring me his withered brain.$B$BJust please, try to keep your sanity.",logDesc="Archmage Lan'dalock in Dalaran wants you to return with the Faceless One's Withered Brain.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13256] then DB[13256]={id=13256,zoneId=4415,name="Proof of Demise: Cyanigosa",level=80,minLevel=80,wowhead="https://www.wowhead.com/wotlk/quest=13256",image="assets/images/quests/placeholder.png",xpDiff=8,money=222000,desc="We're being invaded! The blue dragonflight has teleported into the Violet Hold and they're planning on breaking out from there into the rest of Dalaran!$B$BThere have already been reports of prisoners inadvertently being freed by their actions. It wouldn't surprise me if they're purposefully letting some of them free.$B$B$N, can you assemble your team quickly and get in there? Cyanigosa is the leader of their invasion force. Bring me her head!",logDesc="Archmage Lan'dalock in Dalaran wants you to return with the Head of Cyanigosa.$B$BThis quest may only be completed on Heroic difficulty.",rewards={{id=47241,qty=2}}} end
if not DB[13257] then DB[13257]={id=13257,zoneId=3537,name="Herald of War",level=74,minLevel=71,giver="High Overlord Saurfang",giverType="NPC",giverId=25256,ender="Thrall",enderType="NPC",enderId=31412,rewardNextId=13266,poiX=2835,poiY=6182,wowhead="https://www.wowhead.com/wotlk/quest=13257",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Warchief needs you, champion. Orgrimmar is in a state of martial law. All merchants and services have been shut down as the Warchief prepares for an unavoidable conflict.$B$BI cannot tell you much more - not now. Not in this place.$B$BThe Warchief commands that our strongest champions report to his throne room. Go now, $N! Take the portal back to Orgrimmar and seek out Thrall.",logDesc="Report to Thrall at Grommash Hold in Orgrimmar."} end
if not DB[13258] then DB[13258]={id=13258,zoneId=210,name="Opportunity",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Sergeant Kregga",enderType="NPC",enderId=31440,rewardNextId=13259,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13258",image="assets/images/quests/placeholder.png",xpDiff=3,desc="We recently came upon schematics that indicate a weakness in Icecrown Citadel.  An opening in its defenses, both figuratively and literally.$B$BThe captured diagrams show an orifice leading several hundred feet into the ground.  We're unsure of its purpose, but our scouting has revealed it to be of high importance to the Scourge.$B$BSpeak to Sergeant Kregga below Icecrown Citadel, she's leading the attack on the site.",logDesc="Speak to Sergeant Kregga below Icecrown Citadel."} end
if not DB[13259] then DB[13259]={id=13259,zoneId=4522,name="Establishing Superiority",level=80,minLevel=77,giver="Sergeant Kregga",giverType="NPC",giverId=31440,ender="Sergeant Kregga",enderType="NPC",enderId=31440,rewardNextId=13262,poiX=5907,poiY=1999,wowhead="https://www.wowhead.com/wotlk/quest=13259",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="We've one shot at dealing some damage to this place -- let's make sure we get it right.$B$BWe've acquired potent, Scourge-made, saronite bombs.  But we must secure this area before we can set them off.$B$BWe're going to need to get the Scourge defenses under control quickly, before reinforcements arrive.$B$BHelp my men out and come back when you're ready for some fireworks.",logDesc="Sergeant Kregga at Icecrown Citadel wants you to slay 10 Hulking Horrors.",choiceRewards={{id=38737,qty=1},{id=39036,qty=1},{id=39070,qty=1},{id=39102,qty=1}}} end
if not DB[13260] then DB[13260]={id=13260,zoneId=210,name="Takes One to Know One",level=80,minLevel=77,giver="Sky-Reaver Korm Blackscar",giverType="NPC",giverId=30824,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,rewardNextId=13237,poiX=56,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13260",image="assets/images/quests/placeholder.png",xpDiff=1,desc="While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.$b$bWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.$b$bI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?$b$bAllow me to introduce Koltira Deathweaver.$B",logDesc="Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer."} end
if not DB[13261] then DB[13261]={id=13261,zoneId=210,name="Volatility",level=80,minLevel=77,giver="Chief Engineer Copperclaw",giverType="NPC",giverId=30825,ender="Chief Engineer Copperclaw",enderType="NPC",enderId=30825,poiX=38,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13261",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Wahooo! It works! Not that I had any doubts in my supernatural ingenuity, only that I wasn't quite sure what kind of explosion to expect - let's just say I'm glad to see that you didn't get your eyebrows singed off. So now I just need to show ol' Korm how ya thaw out one 'a them wyrms. He'll hafta promote me to... to... to whatever comes after Chief Engineer! Here, you take another batch of the stuff and head back out to the front and I'll go get Korm...$b$bWell? Move out!",logDesc="Chief Engineer Copperclaw wants you to use Copperclaw's Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.$b$bTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there."} end
if not DB[13262] then DB[13262]={id=13262,zoneId=210,name="Blow it Up!",level=80,minLevel=77,giver="Sergeant Kregga",giverType="NPC",giverId=31440,rewardNextId=13263,poiX=5907,poiY=1999,wowhead="https://www.wowhead.com/wotlk/quest=13262",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="This is probably as under-control as this situation is going to get.  Let's do this, $N.$B$BI need someone to light the fuse on those bombs and it looks like you're the one to do it.",logDesc="Go to the nearby Saronite Bomb Stack to light the fuse."} end
if not DB[13263] then DB[13263]={id=13263,zoneId=210,name="A Short Fuse",level=80,minLevel=77,rewardNextId=13271,wowhead="https://www.wowhead.com/wotlk/quest=13263",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.$B$BThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.",logDesc="Look for clues wherever the fall takes you."} end
if not DB[13264] then DB[13264]={id=13264,zoneId=210,name="That's Abominable!",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13264",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Abominations...$b$bThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.$b$bThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.$b$bFortunately for you, I know these secrets.$b$bThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.",logDesc="Koltira Deathweaver on Orgrim's Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.",choiceRewards={{id=39814,qty=1},{id=39881,qty=1},{id=39887,qty=1},{id=39888,qty=1}}} end
if not DB[13265] then DB[13265]={id=13265,zoneId=-264,name="Cloth Scavenging",level=-1,minLevel=0,giver="Darin Goodstitch",giverType="NPC",giverId=27001,ender="Darin Goodstitch",enderType="NPC",enderId=27001,poiX=2117,poiY=5261,wowhead="https://www.wowhead.com/wotlk/quest=13265",image="assets/images/quests/placeholder.png",xpDiff=1} end
if not DB[13266] then DB[13266]={id=13266,zoneId=1637,name="A Life Without Regret",level=74,minLevel=71,giver="Thrall",giverType="NPC",giverId=31412,ender="Vol'jin",enderType="NPC",enderId=31649,rewardNextId=13267,poiX=1914,poiY=-4128,wowhead="https://www.wowhead.com/wotlk/quest=13266",image="assets/images/quests/placeholder.png",xpDiff=1,desc="On the day of my death I wish to be able to say that I lived a life without regret. Those who mourn my passing will know that I was a Warchief who made decisions that best served his people.$B$BBut this betrayal by Varimathras and Putress... All that we have worked for is for nothing.$B$B<Thrall's chest heaves with a heavy sigh.>$B$BJustice must be served.$B$BPortals to Undercity will be active momentarily. Vol'jin will be waiting for you. I will meet you there soon. Together we will make it right, $N.",logDesc="Take the portal to Undercity located in Grommash Hold and report to Vol'jin."} end
if not DB[13267] then DB[13267]={id=13267,zoneId=1497,name="The Battle For The Undercity",level=74,minLevel=71,giver="Vol'jin",giverType="NPC",giverId=31649,ender="4",enderType="NPC",enderId=31650,poiX=1944,poiY=245,wowhead="https://www.wowhead.com/wotlk/quest=13267",image="assets/images/quests/placeholder.png",xpDiff=8,money=224000,desc="The entirety of the Undercity is controlled by Varimathras. Our soldiers stand ready, waiting for the Warchief to give the attack orders.$B$BHelp the Horde take back the Undercity and earn your place among our greatest champions! Should you survive the assault, report to Thrall.$B$BCheck in with the Warchief when you are ready to begin.",logDesc="Assist Thrall and Sylvanas in retaking the Undercity for the Horde.$B$BReport to Thrall should you succeed.",rewards={{id=44579,qty=1}},choiceRewards={{id=44346,qty=1},{id=44347,qty=1},{id=44348,qty=1},{id=44349,qty=1},{id=44590,qty=1},{id=44583,qty=1}}} end
