if not DB[13269] then DB[13269]={id=13269,zoneId=-264,name="Cloth Scavenging",level=-1,minLevel=0,giver="Alexandra McQueen",giverType="NPC",giverId=26964,ender="Alexandra McQueen",enderType="NPC",enderId=26964,poiX=1875,poiY=-6198,wowhead="https://www.wowhead.com/wotlk/quest=13269",image="assets/images/quests/placeholder.png",xpDiff=1} end
if not DB[13270] then DB[13270]={id=13270,zoneId=-264,name="Cloth Scavenging",level=-1,minLevel=0,giver="Raenah",giverType="NPC",giverId=26969,ender="Raenah",enderType="NPC",enderId=26969,poiX=2843,poiY=6171,wowhead="https://www.wowhead.com/wotlk/quest=13270",image="assets/images/quests/placeholder.png",xpDiff=1} end
if not DB[13271] then DB[13271]={id=13271,zoneId=210,name="A Voice in the Dark",level=80,minLevel=77,ender="Matthias Lehner",enderType="NPC",enderId=31237,rewardNextId=13275,wowhead="https://www.wowhead.com/wotlk/quest=13271",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The object is not a crystal at all, but some form of organ, encased in ice.$B$BAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.$B$BAs you collect your thoughts, you hear a young boy's voice nearby.$B$B\"You really shouldn't have done that.\"",logDesc="Investigate the nearby voice in Naz'anak, the Forgotten Depths."} end
if not DB[13272] then DB[13272]={id=13272,zoneId=-264,name="Cloth Scavenging",level=-1,minLevel=0,giver="Charles Worth",giverType="NPC",giverId=28699,ender="Charles Worth",enderType="NPC",enderId=28699,poiX=5881,poiY=753,wowhead="https://www.wowhead.com/wotlk/quest=13272",image="assets/images/quests/placeholder.png",xpDiff=1} end
if not DB[13273] then DB[13273]={id=13273,zoneId=67,name="Going After the Core",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,ender="Brann Bronzebeard",enderType="NPC",enderId=29579,rewardNextId=13274,wowhead="https://www.wowhead.com/wotlk/quest=13273",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="With Norgannon's Shell in hand, only half of the archive key remains to be found. Luckily, I've had the Explorers' League hard at work chasing down leads about the whereabouts of Norgannon's Core.$B$BFar to the southeast of the Inventor's Library, on the slopes to the north of Dun Niffelem, is a camp bearing my name. The Explorers' League representatives seeking the second half of the key are based there. Bring me the maps and the notes they've made and we should be able to track down the other key half.",logDesc="Find Prospector Khrona's Notes and Prospector Soren's Maps at Brann's Base-Camp."} end
if not DB[13274] then DB[13274]={id=13274,zoneId=67,name="The Core's Keeper",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,ender="Brann Bronzebeard",enderType="NPC",enderId=29579,rewardNextId=13285,wowhead="https://www.wowhead.com/wotlk/quest=13274",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Prospector Soren's notes say that Norgannon's Core is in the keeping of a sentinel named Athan, one of Mimir's creations.$B$BSoren says the vault where Athan resides is called \"Loken's Bargain\" these days.$B$BLoken, eh? The earthen have mentioned him.$B$BThe vault is said to be southwest of the ruined Explorers' League camp, with a round entrance on a mountainside overlooking the Valley of Ancient Winters.$B$BFind this Athan and get the core from him, but I wouldn't be surprised if you were in for a fight.",logDesc="Obtain Norgannon's Core."} end
if not DB[13275] then DB[13275]={id=13275,zoneId=210,name="Time to Hide",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=31237,ender="Matthias Lehner",enderType="NPC",enderId=31237,rewardNextId=13282,poiX=5793,poiY=2069,wowhead="https://www.wowhead.com/wotlk/quest=13275",image="assets/images/quests/placeholder.png",xpDiff=5,money=58000,desc="You shouldn't have touched it.  But now that you did, he's going to come looking for you.$B$BAnd he'll find you.  Unless you hide yourself from him.$B$BBring me blood from the faceless ones if you want to live!",logDesc="Matthias Lehner wants you to obtain 3 Faceless One's Blood.",choiceRewards={{id=43885,qty=1},{id=43918,qty=1},{id=43915,qty=1},{id=43916,qty=1},{id=43888,qty=1},{id=43917,qty=1}}} end
if not DB[13276] then DB[13276]={id=13276,zoneId=210,name="That's Abominable!",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13276",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You know what to do, $c.$b$bTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.$b$bYou would do well to refine this tactic for when we make our assault on the gate.",logDesc="Koltira Deathweaver on Orgrim's Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers."} end
if not DB[13277] then DB[13277]={id=13277,zoneId=210,name="Against the Giants",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,rewardNextId=13279,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13277",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.$b$bThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.$b$bMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.$b$bOh... and bring me their spines. If memory serves, there's a little trick I can share with you.",logDesc="Koltira Deathweaver on Orgrim's Hammer wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord'rethar."} end
if not DB[13278] then DB[13278]={id=13278,zoneId=210,name="Coprous the Defiled",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13278",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Reports of a powerful zombie at the death gate have reached my ears, $c.$b$bWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.$b$bGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.",logDesc="Koltira Deathweaver aboard Orgrim's Hammer wants you to kill Coprous the Defiled at Mord'rethar."} end
if not DB[13279] then DB[13279]={id=13279,zoneId=210,name="Basic Chemistry",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13279",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="<Koltira takes the pustulant spines and drains their fluid into a flask.>$b$bA little-known quality of the flesh giants...$b$bTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.$b$bPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.$b$bPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.",logDesc="Koltira Deathweaver aboard Orgrim's Hammer wants you to use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.",choiceRewards={{id=44386,qty=1},{id=44388,qty=1},{id=44387,qty=1}}} end
if not DB[13280] then DB[13280]={id=13280,zoneId=210,name="King of the Mountain",level=80,minLevel=77,giver="Frazzle Geargrinder",giverType="NPC",giverId=31776,ender="Frazzle Geargrinder",enderType="NPC",enderId=31776,poiX=6811,poiY=1870,wowhead="https://www.wowhead.com/wotlk/quest=13280",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You've just got to get my jumpbot to the tippy top of the mountain to the northwest here at Ymirheim pronto, $N!$B$BThat dastardly, no-good Blast Thunderbomb is working on his own bot, and I'm afraid he almost has it completed. We're in a race to see who's gonna be king of the mountain!$B$BOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Alliance, and my engineering skills, are the best!",logDesc="Frazzle Geargrinder in Ymirheim wants you to use her Geargrinder's Jumpbot to plant the Alliance Battle Standard in the skulls at the top of the mountain."} end
if not DB[13281] then DB[13281]={id=13281,zoneId=210,name="Neutralizing the Plague",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13281",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="You no longer need my assistance in neutralizing the enemy's plague cauldrons, $r.$b$bHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.$b$bYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.$b$bRemember, the giants and the plague cauldrons can be found on Mord'rethar.",logDesc="Koltira Deathweaver aboard Orgrim's Hammer wants you use Pustulant Spinal Fluid on a blight cauldron at Mord'rethar.$b$bYou can create Pustulant Spinal Fluid by using a Giant Spine collected from a Pustulant Horror."} end
if not DB[13282] then DB[13282]={id=13282,zoneId=210,name="Return to the Surface",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=31237,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,rewardNextId=13304,poiX=5793,poiY=2069,wowhead="https://www.wowhead.com/wotlk/quest=13282",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="You should leave now.  You'll find a portal behind me.  It'll take you to the surface.$B$BWe'll meet again.  He'll be looking for you.$B$BIt's only a matter of time until he finds you.",logDesc="Return to Koltira Deathweaver aboard Orgrim's Hammer."} end
if not DB[13283] then DB[13283]={id=13283,zoneId=210,name="King of the Mountain",level=80,minLevel=77,giver="Blast Thunderbomb",giverType="NPC",giverId=31781,ender="Blast Thunderbomb",enderType="NPC",enderId=31781,poiX=7019,poiY=2187,wowhead="https://www.wowhead.com/wotlk/quest=13283",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Yo, $N, I need you to get my jumpbot to the top of this mountain to the southeast, like yesterday!$B$BThat girly, self-righteous Frazzle Geargrinder thinks that her jumpbot's better than mine. Hah! We're in a race to see who's gonna be king of the mountain!$B$BOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Horde, and my mad engineering skills, are the best!",logDesc="Blast Thunderbomb in Ymirheim wants you to use his Thunderbomb's Jumpbot to plant the Horde Battle Standard in the skulls at the top of the mountain."} end
if not DB[13284] then DB[13284]={id=13284,zoneId=210,name="Assault by Ground",level=80,minLevel=77,giver="Skybreaker Squad Leader",giverType="NPC",giverId=31737,ender="Ground Commander Koup",enderType="NPC",enderId=31808,poiX=7269,poiY=1507,wowhead="https://www.wowhead.com/wotlk/quest=13284",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Greetings $c.$B$BOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.$B$BIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.",logDesc="Escort the Skybreaker troops to the gates of Ymirheim. Return to Ground Commander Koup at the edge of the glacier east of Ymirheim for compensation after the task is complete."} end
if not DB[13285] then DB[13285]={id=13285,zoneId=67,name="Forging the Keystone",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,ender="Boktar Bloodfury",enderType="NPC",enderId=29651,wowhead="https://www.wowhead.com/wotlk/quest=13285",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Aha! Here it is: the Temple of Invention, the seat of Keeper Mimir himself! Of course, that's where one would go to join the two parts of the key.$B$BAccording to the prospector's notes, the Temple of Invention is one of the highest points on the western side of the Terrace of the Makers. That means it should be roughly east of your Grom'arsh Crash Site.$B$BI'll meet you at the temple and we'll combine the parts together.",logDesc="Brann Bronzebeard wants you to meet him at the Temple of Invention and help him combine Norgannon's Shell and Norgannon's Core. Once you have helped Brann, report back to Boktar Bloodfury at the Grom'arsh Crash-Site.",choiceRewards={{id=43189,qty=1},{id=43190,qty=1},{id=43191,qty=1},{id=43192,qty=1}}} end
if not DB[13286] then DB[13286]={id=13286,zoneId=210,name="...All the Help We Can Get.",level=80,minLevel=77,giver="High Captain Justin Bartlett",giverType="NPC",giverId=30344,ender="Thassarian",enderType="NPC",enderId=29799,rewardNextId=13287,poiX=44,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13286",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Desperate times, $c...$b$bAs uncomfortable as it makes me, I'm prepared to accept assistance from anyone - including our resident death knight.$b$bGo to Thassarian and see if he can help us develop tactics against the Scourge that will ensure victory once we are able to mount another offensive.$b$bWe have come so far... we must not fail here!",logDesc="High Captain Justin Bartlett aboard the Skybreaker wants you to speak to Thassarian."} end
if not DB[13287] then DB[13287]={id=13287,zoneId=210,name="Poke and Prod",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13287",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="As someone of your experience must surely know, there's no better way to familiarize one's self with their enemy than by confronting them in combat.$b$bWhile you no doubt lust for the glory of taking Icecrown Citadel, that cannot happen without taking each of the Lich King's gates first. For now, you must focus your efforts on the first of these...$b$bReturn to the Broken Front. Engage the enemy in battle. Search for a weakness we might exploit and return to me with a detailed report.",logDesc="Thassarian on the Alliance gunship, Skybreaker, wants you to kill 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts at the Broken Front.",choiceRewards={{id=43903,qty=1},{id=43889,qty=1},{id=43884,qty=1}}} end
if not DB[13288] then DB[13288]={id=13288,zoneId=210,name="That's Abominable!",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13288",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Abominations...$b$bThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.$b$bThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.$b$bFortunately for you, I know these secrets.$b$bThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.",logDesc="Thassarian on the Skybreaker wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.",choiceRewards={{id=39814,qty=1},{id=39881,qty=1},{id=39887,qty=1},{id=39888,qty=1}}} end
if not DB[13289] then DB[13289]={id=13289,zoneId=210,name="That's Abominable!",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13289",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You know what to do, $c.$b$bTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.$b$bYou would do well to refine this tactic for when we make another assault on the gate.",logDesc="Thassarian on the Skybreaker wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers."} end
if not DB[13290] then DB[13290]={id=13290,zoneId=210,name="Your Attention, Please",level=80,minLevel=77,giver="High Captain Justin Bartlett",giverType="NPC",giverId=30344,ender="Chief Engineer Boltwrench",enderType="NPC",enderId=30345,rewardNextId=13291,poiX=44,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13290",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Chief Engineer Boltwrench has proven invaluable in his service aboard the Stormbreaker. Were it not for his ingenuity, we'd be sprinkled across half of the glacier several times over by now.$b$bThe thing is, he feels he must share his every miniscule invention or discovery - most of which I don't even understand.$b$bMy focus must be squarely on our enemies right now. I cannot afford any distractions.$b$bPlease visit him in my stead, $n. And if you can, assist him. You'll find him belowdecks.",logDesc="High Captain Bartlett wants you to speak with Chief Engineer Boltwrench in the Skybreaker."} end
if not DB[13291] then DB[13291]={id=13291,zoneId=210,name="Borrowed Technology",level=80,minLevel=77,giver="Chief Engineer Boltwrench",giverType="NPC",giverId=30345,ender="Chief Engineer Boltwrench",enderType="NPC",enderId=30345,poiX=-48,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13291",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I get it, I get it. Cappy's too busy to see this for himself. His loss!$b$bSee, I've managed to 'acquire' a certain shipment of solution from the enemy. And as much as I hate tinkerin' with inferior goblin technology, I'm inclined to make an exception here.$b$bTake this sample. I'll need you to run a few field tests, just to prove its usefulness, while I try to do a little reverse engineering to duplicate the creation process.$b$bGo to the front and gather the materials to make a decoy, then use the oil.",logDesc="Chief Engineer Boltwrench aboard the Skybreaker wants you to use the Smuggled Solution at the Broken Front.$b$bUsing the solution will require an Abandoned Helm, Abandoned Armor, and Pile of Bones, all found at the Broken Front.",choiceRewards={{id=38736,qty=1},{id=39035,qty=1},{id=39065,qty=1},{id=39100,qty=1}}} end
if not DB[13292] then DB[13292]={id=13292,zoneId=210,name="The Solution Solution",level=80,minLevel=77,giver="Chief Engineer Boltwrench",giverType="NPC",giverId=30345,ender="Chief Engineer Boltwrench",enderType="NPC",enderId=30345,poiX=-48,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13292",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Oh, yes, yes. Back again, are we? Never enough practice, I suppose.$b$bHere we are, the solution to that pesky frostwyrm problem.$b$bMake them scarce, $r. The more you take out now, the less we face when we are again ready to attempt our march on the citadel.$b$bBest of luck, now. And do bring back whatever you don't use.",logDesc="Chief Engineer Boltwrench aboard the Skybreaker wants you to use the Smuggled Solution at the Broken Front.$b$bUsing the solution will require an Abandoned Helm, Abandoned Armor, and Pile of Bones, all found at the Broken Front."} end
if not DB[13293] then DB[13293]={id=13293,zoneId=210,name="Get to Ymirheim!",level=80,minLevel=77,giver="Chief Engineer Copperclaw",giverType="NPC",giverId=30825,ender="Blast Thunderbomb",enderType="NPC",enderId=31781,rewardNextId=13283,poiX=38,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13293",image="assets/images/quests/placeholder.png",xpDiff=1,desc="You need to get down to Ymirheim, that big frost vrykul town in the middle of Icecrown.$B$BOur boy, Blast Thunderbomb, is down there on the west side of town representing the Warsong Offensive in a competition against the Alliance. It's his jumpbot versus theirs in a king of the mountain contest!$B$BDon't let us down, $N. Goblin engineering pride is on the line! Besides, all the boys here in the hold are counting on you.$B$BThat and we've got money riding on it that you can kick those cowards in the pants!",logDesc="Speak with Blast Thunderbomb in Ymirheim."} end
if not DB[13294] then DB[13294]={id=13294,zoneId=210,name="Against the Giants",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,rewardNextId=13295,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13294",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.$b$bThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.$b$bMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.$b$bOh... and bring me their spines. If memory serves, there's a little trick I can share with you.",logDesc="Thassarian on the Skybreaker wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord'rethar.$B"} end
if not DB[13295] then DB[13295]={id=13295,zoneId=210,name="Basic Chemistry",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13295",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="<Thassarian takes the pustulant spines and drains their fluid into a flask.>$b$bA little-known quality of the flesh giants...$b$bTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.$b$bPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.$b$bPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.",logDesc="Thassarian aboard the Skybreaker wants you to use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.",choiceRewards={{id=44386,qty=1},{id=44387,qty=1},{id=44388,qty=1}}} end
if not DB[13296] then DB[13296]={id=13296,zoneId=210,name="Get to Ymirheim!",level=80,minLevel=77,giver="Chief Engineer Boltwrench",giverType="NPC",giverId=30345,ender="Frazzle Geargrinder",enderType="NPC",enderId=31776,rewardNextId=13280,poiX=-48,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13296",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I need you down in Ymirheim, that big frost vrykul town in the middle of Icecrown.$B$BFrazzle Geargrinder is down there on the south side of town representing the Valiance Expedition in a competition against the Horde scum. It's her jumpbot versus theirs in a king of the mountain contest!$B$BDon't let us down, $N. Gnomish engineering pride is on the line! Besides, all the boys here in the hold are counting on you.$B$BThat and we've got money riding on it that you can kick those idiots in the pants!",logDesc="Speak with Frazzle Geargrinder in Ymriheim."} end
if not DB[13297] then DB[13297]={id=13297,zoneId=210,name="Neutralizing the Plague",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13297",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="You no longer need my assistance in neutralizing the enemy's plague cauldrons, $r.$b$bHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.$b$bYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.$b$bRemember, the giants and the plague cauldrons can be found on Mord'rethar.",logDesc="Thassarian aboard the Skybreaker wants you use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.$b$bYou can create Pustulant Spinal Fluid by using a Giant Spine collected from a Pustulant Horror."} end
if not DB[13298] then DB[13298]={id=13298,zoneId=210,name="Coprous the Defiled",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13298",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="Reports of a powerful zombie at the death gate have reached my ears, $c.$b$bWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.$b$bGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.",logDesc="Thassarian aboard the Skybreaker wants you to kill Coprous the Defiled at Mord'rethar."} end
if not DB[13299] then DB[13299]={id=13299,zoneId=-264,name="ZZOLDWisp Cloak",level=75,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=13299",image="assets/images/quests/placeholder.png"} end
if not DB[13300] then DB[13300]={id=13300,zoneId=210,name="Slaves to Saronite",level=80,minLevel=77,giver="Absalan the Pious",giverType="NPC",giverId=31259,ender="Absalan the Pious",enderType="NPC",enderId=31259,poiX=17,poiY=-18,wowhead="https://www.wowhead.com/wotlk/quest=13300",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.$B$BI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.$B$BUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Valiance Expedition. Will you please rescue them in my stead, $N?",logDesc="Absalan the Pious aboard the Skybreaker wants you to rescue 10 Saronite Mine Slaves."} end
if not DB[13301] then DB[13301]={id=13301,zoneId=210,name="Assault by Ground",level=80,minLevel=77,giver="Kor'kron Squad Leader",giverType="NPC",giverId=31833,ender="Ground Commander Xutjja",enderType="NPC",enderId=31834,poiX=7509,poiY=1795,wowhead="https://www.wowhead.com/wotlk/quest=13301",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Greetings $c.$B$BOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.$B$BIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.",logDesc="Escort the Kor'kron troops to the gates of Ymirheim. Return to Ground Commander Xutjja at the edge of the glacier north of Ymirheim for compensation after the task is complete."} end
if not DB[13302] then DB[13302]={id=13302,zoneId=210,name="Slaves to Saronite",level=80,minLevel=77,giver="Brother Keltan",giverType="NPC",giverId=31261,ender="Brother Keltan",enderType="NPC",enderId=31261,poiX=-24,poiY=-22,wowhead="https://www.wowhead.com/wotlk/quest=13302",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.$B$BI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.$B$BUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Warsong Offensive. Will you please rescue them in my stead, $N?",logDesc="Brother Keltan aboard Orgrim's Hammer wants you to rescue 10 Saronite Mine Slaves."} end
if not DB[13303] then DB[13303]={id=13303,zoneId=-264,name="Test Quest",level=75,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=13303",image="assets/images/quests/placeholder.png",rewards={{id=29364,qty=1}}} end
if not DB[13304] then DB[13304]={id=13304,zoneId=210,name="Field Repairs",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Wrecked Demolisher",enderType="NPC",enderId=31868,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13304",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Scourge is still reeling from our attack, $N.  Now is the time to capitalize on our momentum.$B$BThe strategically important valley below us is wide open.  We've located a disassembled demolisher vehicle in what we believe is working condition in the southeastern corner of the Valley of Lost Hope area.$B$BIf you can get the remaining parts from the Scourge scavengers, you should be able to get it running again.  A single working demolisher can wreak havoc on the enemy's ground units.",logDesc="Koltira Deathweaver aboard Orgrim's Hammer wants you to collect 5 Demolisher Parts from the Scavenging Geists in the Valley of Lost Hope and take them to the Wrecked Demolisher."} end
if not DB[13305] then DB[13305]={id=13305,zoneId=210,name="Do Your Worst",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32408,ender="Matthias Lehner",enderType="NPC",enderId=32404,rewardNextId=13236,poiX=7270,poiY=1178,wowhead="https://www.wowhead.com/wotlk/quest=13305",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You're going to use this machine against the Scourge?  You're not going to win against them like that.$B$BYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.$B$BWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.",logDesc="Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope.  Speak to Matthias Lehner at the First Legion Forward Camp when you've completed this task.",choiceRewards={{id=43881,qty=1},{id=43892,qty=1},{id=43932,qty=1},{id=43930,qty=1},{id=43847,qty=1}}} end
if not DB[13306] then DB[13306]={id=13306,zoneId=210,name="Raise the Barricades",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13306",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.$B$BWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.$B$BTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.",logDesc="Koltira Deathweaver, aboard Orgrim's Hammer, wants you to construct 8 Barricades using your Barricade Construction Kit."} end
if not DB[13307] then DB[13307]={id=13307,zoneId=210,name="Bloodspattered Banners",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13307",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.$B$BIt falls to you to rid us of this obstacle, and thin the resistance before the main body can advance.",logDesc="Koltira Deathweaver, aboard Orgrim's Hammer, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes."} end
if not DB[13308] then DB[13308]={id=13308,zoneId=210,name="Mind Tricks",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31892,ender="3",enderType="NPC",enderId=31892,poiX=6948,poiY=2027,wowhead="https://www.wowhead.com/wotlk/quest=13308",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="<The creature speaks directly into your mind, its thoughts painful and strange.>$B$B$R-thing, I am in need of your assistance. Like your enslaved friends, I am a victim of the Lich King's ymirjar and their avarice. When I rose from below to investigate the noises coming from this cavern they captured and chained me.$B$BWill you please help me? The foreman of these mines holds the key to my chains. Kill him!$B$B<You can feel a pushing against your mind as if the creature is trying to coerce you.>",logDesc="Darkspeaker R'khem in the Saronite Mines wants you to recover the Foreman's Key to his chains.",choiceRewards={{id=44021,qty=1},{id=44024,qty=1},{id=44030,qty=1},{id=44031,qty=1}}} end
if not DB[13309] then DB[13309]={id=13309,zoneId=210,name="Assault by Air",level=80,minLevel=77,giver="Ground Commander Koup",giverType="NPC",giverId=31808,ender="Ground Commander Koup",enderType="NPC",enderId=31808,poiX=7281,poiY=1521,wowhead="https://www.wowhead.com/wotlk/quest=13309",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I've got some boys suited and ready for their drops inside of Ymirheim. I could use you to see them there safely.$B$BInside the walls, the vrykul have set up some kind of automated spear guns that have been tearing up our transports. We had our engineers install a Suppression Turret to shut down those spear guns - just fire a round near any gun and the smoke should block its sight and clog its gears.$B$BHop on the turret and see to it that all my boys make it to their drops in one piece.",logDesc="Ground Commander Koup at the edge of the glacier east of Ymirheim has ordered you to use the Skybreaker Suppression Turret to keep the Skybreaker Troop Transport alive long enough to make all of its drops.$B"} end
if not DB[13310] then DB[13310]={id=13310,zoneId=210,name="Assault by Air",level=80,minLevel=77,giver="Ground Commander Xutjja",giverType="NPC",giverId=31834,ender="Ground Commander Xutjja",enderType="NPC",enderId=31834,poiX=7504,poiY=1786,wowhead="https://www.wowhead.com/wotlk/quest=13310",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Alright scrub, I've got something to keep you from being a complete waste.$B$BA unit of highly trained infiltrators is ready to be dropped inside of Ymirheim. The vrykul inside have automated spear guns that have been ripping our transports to shreds, so we had the engineers on Orgrim's Hammer whip us up a suppression turret.$B$BYou're the gunner. Launch rounds at their spear guns to obscure their vision and clog their gears. See to it that my men all make their drops and the transport stays in one piece.",logDesc="Ground Commander Xutjja at the edge of the glacier north of Ymirheim has ordered you to use the Kor'kron Suppression Turret to keep the Kor'kron Troop Transport alive long enough to make all of its drops."} end
if not DB[13311] then DB[13311]={id=13311,zoneId=0,name="Demons Deck",level=45,minLevel=40,ender="Darkmoon Fortune Teller",enderType="NPC",enderId=30481,wowhead="https://www.wowhead.com/wotlk/quest=13311",image="assets/images/quests/placeholder.png",xpDiff=2,desc="Now that you have gathered all of the Demon cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.$b$bYou feel the card could be used to communicate with someone or something.",logDesc="Use the Demons Deck to summon a Darkmoon Fortune Teller and give the deck to them.",choiceRewards={{id=44217,qty=1},{id=44218,qty=1},{id=44219,qty=1}}} end
if not DB[13312] then DB[13312]={id=13312,zoneId=210,name="The Ironwall Rampart",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13312",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.$B$BIf you can weaken Grimkor, our forces know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.",logDesc="Defeat Grimkor the Wicked and return to Koltira Deathweaver aboard Orgrim's Hammer."} end
if not DB[13313] then DB[13313]={id=13313,zoneId=210,name="Blinding the Eyes in the Sky",level=80,minLevel=77,giver="Sky-Reaver Korm Blackscar",giverType="NPC",giverId=30824,ender="Sky-Reaver Korm Blackscar",enderType="NPC",enderId=30824,poiX=56,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13313",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Alliance has somehow managed to field a squadron of recon vehicles over the Valley of Fallen Heroes and Icecrown Glacier, the broad areas west of Aldur'thar.$B$BThey cannot be permitted to take the lead in this fight. Chief Engineer Copperclaw has supplied me with the perfect weapon to deal with this threat -- he calls his new missile the SGM-3. I have his assurances that it will take out the Alliance flying machines in a single hit. Go and use this weapon to give us the upper hand.",logDesc="Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer."} end
if not DB[13314] then DB[13314]={id=13314,zoneId=210,name="Get the Message",level=80,minLevel=77,giver="High Captain Justin Bartlett",giverType="NPC",giverId=30344,ender="High Captain Justin Bartlett",enderType="NPC",enderId=30344,poiX=44,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13314",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Horde is up to something and I don't like it. After the stunt they pulled on the Broken Front, they're capable of anything, and it's up to us to stop it.$B$BThere's been a flurry of activity in the skies over the Icecrown Glacier, to the west of Aldur'thar and the Ironwall Rampart. Horde scouts and messengers streak in and out on dragonhawks, carrying reports and orders. Take this dart gun and use it to kill the Orgrim's Hammer Scouts. It'll probably work best if you're flying, too.",logDesc="Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker."} end
if not DB[13315] then DB[13315]={id=13315,zoneId=210,name="Sneak Preview",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13315",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from those Horde you insist on contending with...$b$bAt any rate, our next focus will be the gate of desolation. Fly down and become familiar with it and with the enemies posted there.$b$bWhen you return, I will have your missions prepared.",logDesc="Thassarian, aboard the Skybreaker, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate. "} end
if not DB[13316] then DB[13316]={id=13316,zoneId=210,name="The Guardians of Corp'rethar",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13316",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.$B$BWe must weaken its defenses, or our army's strength will break upon its walls.$B$BIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.",logDesc="Koltira Deathweaver, aboard Orgrim's Hammer, wants you to kill 5 Harbingers of Horror and 5 Corp'rethar Guardians."} end
if not DB[13317] then DB[13317]={id=13317,zoneId=210,name="----",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13317",image="assets/images/quests/placeholder.png"} end
if not DB[13318] then DB[13318]={id=13318,zoneId=210,name="Drag and Drop",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13318",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Cult of the Damned hold the gate of desolation, eh? No surprise there.$b$bTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.$b$bThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.$b$bKill the fools until you find one, $c, then use it on a subjugator.",logDesc="Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there."} end
if not DB[13319] then DB[13319]={id=13319,zoneId=210,name="Chain of Command",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13319",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.$b$bWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, $r, is a worthy enough goal for now.$b$bSeek out these overseers and return to me when they have been dispatched.",logDesc="Thassarian aboard the Skybreaker wants you to go to Aldur'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.",choiceRewards={{id=43882,qty=1},{id=43891,qty=1},{id=43931,qty=1},{id=39458,qty=1}}} end
if not DB[13320] then DB[13320]={id=13320,zoneId=210,name="Cannot Reproduce",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Chief Engineer Boltwrench",enderType="NPC",enderId=30345,rewardNextId=13321,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13320",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I smell their cauldrons from here, but that's not plague they're cooking.$b$bPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.$b$bSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...$b$bFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Boltwrench.",logDesc="Thassarian aboard the Skybreaker wants you to use the Partitioned Flask at each of the 3 Cultists' Cauldrons at Aldur'thar, then bring it to Chief Engineer Boltwrench."} end
if not DB[13321] then DB[13321]={id=13321,zoneId=210,name="Retest Now",level=80,minLevel=77,giver="Chief Engineer Boltwrench",giverType="NPC",giverId=30345,ender="Chief Engineer Boltwrench",enderType="NPC",enderId=30345,poiX=-48,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13321",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="This should do the trick!$b$bThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!$b$bTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence once you've defeated them.$b$bWhen you've collected a bunch of them, throw the writhing mass of twisted souls into any of their cauldrons.$b$bLet's see how they like a taste of their own medicine!",logDesc="Chief Engineer Boltwrench aboard the Skybreaker wants you to throw a Writhing Mass into a cauldron at Aldur'thar.",choiceRewards={{id=39134,qty=1},{id=39144,qty=1},{id=39143,qty=1},{id=39121,qty=1},{id=39138,qty=1}}} end
if not DB[13322] then DB[13322]={id=13322,zoneId=210,name="Retest Now",level=80,minLevel=77,giver="Chief Engineer Boltwrench",giverType="NPC",giverId=30345,ender="Chief Engineer Boltwrench",enderType="NPC",enderId=30345,poiX=-48,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13322",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!$b$bTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.$b$bOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.$b$bLet's see how they like a taste of their own medicine!",logDesc="Chief Engineer Boltwrench aboard the Skybreaker wants you to drink the Diluted Cult Tonic, kill any Cultists at Aldur'thar and take their Tainted Essences. You are then to combine 10 of the essences into a Writhing Mass and throw it into any of their cauldrons."} end
if not DB[13323] then DB[13323]={id=13323,zoneId=210,name="Drag and Drop",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13323",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Looks like those initiates are increasing in number again. You know what to do...$b$bAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.$b$bThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.$b$bSlay the fools until you find some, then use them on the subjugators there.",logDesc="Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there."} end
if not DB[13324] then DB[13324]={id=13324,zoneId=-364,name="Darkmoon Prisms Deck",level=80,minLevel=1,ender="Professor Thaddeus Paleo",enderType="NPC",enderId=14847,wowhead="https://www.wowhead.com/wotlk/quest=13324",image="assets/images/quests/placeholder.png",desc="Now that you have gathered all of the Prism cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.",logDesc="Return the Prisms Deck to the Darkmoon Faire when it comes to town.",rewards={{id=42988,qty=1}}} end
if not DB[13325] then DB[13325]={id=13325,zoneId=-364,name="Darkmoon Chaos Deck",level=80,minLevel=1,ender="Professor Thaddeus Paleo",enderType="NPC",enderId=14847,wowhead="https://www.wowhead.com/wotlk/quest=13325",image="assets/images/quests/placeholder.png",desc="Now that you have gathered all of the Chaos cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.",logDesc="Return the Chaos Deck to the Darkmoon Faire when it comes to town.",rewards={{id=42989,qty=1}}} end
if not DB[13326] then DB[13326]={id=13326,zoneId=-364,name="Darkmoon Nobles Deck",level=80,minLevel=1,ender="Professor Thaddeus Paleo",enderType="NPC",enderId=14847,wowhead="https://www.wowhead.com/wotlk/quest=13326",image="assets/images/quests/placeholder.png",desc="Now that you have gathered all of the Nobles cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.",logDesc="Return the Nobles Deck to the Darkmoon Faire when it comes to town.",choiceRewards={{id=42987,qty=1},{id=44254,qty=1},{id=44253,qty=1},{id=44255,qty=1}}} end
if not DB[13327] then DB[13327]={id=13327,zoneId=-364,name="Darkmoon Undeath Deck",level=80,minLevel=1,ender="Professor Thaddeus Paleo",enderType="NPC",enderId=14847,wowhead="https://www.wowhead.com/wotlk/quest=13327",image="assets/images/quests/placeholder.png",desc="Now that you have gathered all of the Undeath cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.",logDesc="Return the Undeath Deck to the Darkmoon Faire when it comes to town.",rewards={{id=42990,qty=1}}} end
if not DB[13328] then DB[13328]={id=13328,zoneId=210,name="Shatter the Shards",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13328",image="assets/images/quests/placeholder.png",xpDiff=6,money=74000,desc="Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.$B$BIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.$B$BFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!",logDesc="Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Koltira Deathweaver aboard Orgrim's Hammer."} end
if not DB[13329] then DB[13329]={id=13329,zoneId=210,name="Before the Gate of Horror",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13329",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.$B$BLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.$B$BI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.",logDesc="Koltira Deathweaver, aboard Orgrim's Hammer, wants you to use the Volatile Acid to dissolve the remains of 6 Skeletal Reavers."} end
if not DB[13330] then DB[13330]={id=13330,zoneId=210,name="Blood of the Chosen",level=80,minLevel=77,giver="Warbringer Davos Rioht",giverType="NPC",giverId=32301,ender="Warbringer Davos Rioht",enderType="NPC",enderId=32301,poiX=-3,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13330",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.$B$BGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.",logDesc="Warbringer Davos Rioht on Orgrim's Hammer has sent you to kill 20 vrykul in Ymirheim."} end
if not DB[13331] then DB[13331]={id=13331,zoneId=210,name="Keeping the Alliance Blind",level=80,minLevel=77,giver="Sky-Reaver Korm Blackscar",giverType="NPC",giverId=30824,ender="Sky-Reaver Korm Blackscar",enderType="NPC",enderId=30824,poiX=56,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13331",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Alliance is tenacious, I'll give them that, but it'll take more than that to stop us. Take this SGM-3 with you and shoot down the Skybreaker's recon fighters once again.$B$BI doubt the message will get through their thick skulls, but there are enough missiles to keep trying to get our point across. Go and find their fighters flying above the Valley of Fallen Heroes, west of Aldur'thar, and don't come back until you've made wreckage of them.",logDesc="Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer."} end
if not DB[13332] then DB[13332]={id=13332,zoneId=210,name="Raise the Barricades",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13332",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.$B$BWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.$B$BTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.",logDesc="Thassarian, aboard the Skybreaker, wants you to construct 8 Barricades using your Barricade Construction Kit."} end
if not DB[13333] then DB[13333]={id=13333,zoneId=210,name="Capture More Dispatches",level=80,minLevel=77,giver="High Captain Justin Bartlett",giverType="NPC",giverId=30344,ender="High Captain Justin Bartlett",enderType="NPC",enderId=30344,poiX=44,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13333",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Despite our efforts, the Horde continues to send scouts to the area of the Icecrown Glacier, to the west of the Ironwall Rampart and Aldur'thar.$B$BWe can't afford to let the Horde gain the upper hand with this scouting operation. Take the dart gun with you again and show the Orgrim's Hammer scouts no mercy! Bring the captured dispatches to me.$B$BThe Horde's wasted efforts will be our gain.",logDesc="Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker."} end
if not DB[13334] then DB[13334]={id=13334,zoneId=210,name="Bloodspattered Banners",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13334",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.$B$BIt falls to you to rid us of this obstacle, and test the resistance before the main body can advance.",logDesc="Thassarian, aboard the Skybreaker, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes."} end
if not DB[13335] then DB[13335]={id=13335,zoneId=210,name="Before the Gate of Horror",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13335",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.$B$BLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.$B$BI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.",logDesc="Thassarian, aboard the Skybreaker, wants you to use the Volatile Acid to dissolve the corpses of 6 Skeletal Reavers."} end
if not DB[13336] then DB[13336]={id=13336,zoneId=210,name="Blood of the Chosen",level=80,minLevel=77,giver="Knight-Captain Drosche",giverType="NPC",giverId=32302,ender="Knight-Captain Drosche",enderType="NPC",enderId=32302,poiX=55,poiY=-7,wowhead="https://www.wowhead.com/wotlk/quest=13336",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.$B$BGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.",logDesc="Knight-Captain Drosche on the Skybreaker has sent you to kill 20 vrykul in Ymirheim."} end
if not DB[13337] then DB[13337]={id=13337,zoneId=210,name="The Ironwall Rampart",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13337",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.$B$BIf you can weaken Grimkor, our forces will know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.",logDesc="Defeat Grimkor the Wicked and return to Thassarian aboard the Skybreaker."} end
if not DB[13338] then DB[13338]={id=13338,zoneId=210,name="The Guardians of Corp'rethar",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13338",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.$B$BWe must weaken its defenses, or our army's strength will break upon its walls.$B$BIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.",logDesc="Thassarian, aboard the Skybreaker, wants you to kill 5 Harbingers of Horror and 5 Corp'rethar Guardians."} end
if not DB[13339] then DB[13339]={id=13339,zoneId=210,name="Shatter the Shards",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13339",image="assets/images/quests/placeholder.png",xpDiff=6,money=74000,desc="Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.$B$BIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.$B$BFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!",logDesc="Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Thassarian, aboard the Skybreaker."} end
if not DB[13340] then DB[13340]={id=13340,zoneId=210,name="Joining the Assault",level=80,minLevel=77,giver="Warbringer Davos Rioht",giverType="NPC",giverId=32301,ender="Ground Commander Xutjja",enderType="NPC",enderId=31834,poiX=-3,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13340",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="We need more men to join the main assault on Ymirheim.$B$BAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown us no restraint in proving why the Lich King deemed them worthy.$B$BGround Commander Xutjja is overseeing the assault. The city itself is located in the center of Icecrown - Xutjja's troops are positioned near the edge of the glacier, north of the city.",logDesc="Report to Ground Commander Xutjja at the edge of the glacier north of Ymirheim."} end
if not DB[13341] then DB[13341]={id=13341,zoneId=210,name="Joining the Assault",level=80,minLevel=77,giver="Knight-Captain Drosche",giverType="NPC",giverId=32302,ender="Ground Commander Koup",enderType="NPC",enderId=31808,poiX=55,poiY=-7,wowhead="https://www.wowhead.com/wotlk/quest=13341",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="We need more men to join the main assault on Ymirheim.$B$BAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown no restraint in proving to us why the Lich King deemed them worthy.$B$BGround Commander Koup is overseeing the assault. The city itself is located in the center of Icecrown - Koup's troops are positioned near the edge of the glacier, east of the city.",logDesc="Report to Ground Commander Koup at the edge of the glacier east of Ymirheim."} end
if not DB[13342] then DB[13342]={id=13342,zoneId=210,name="Not a Bug",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13342",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Alright, $g friend:missy;, time to plant a bug.$b$bRelax, it's not a bug exactly, but it'll serve our purposes.$b$bIn the northern portion of Aldur'thar the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use their summoning crystal to bring our little spy into being.$b$bUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.",logDesc="Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.",choiceRewards={{id=39372,qty=1},{id=39414,qty=1},{id=39443,qty=1},{id=39462,qty=1},{id=39471,qty=1}}} end
if not DB[13343] then DB[13343]={id=13343,zoneId=65,name="Mystery of the Infinite, Redux",level=80,minLevel=80,giver="Chromie",giverType="NPC",giverId=27856,ender="Chromie",enderType="NPC",enderId=27856,poiX=3537,poiY=262,wowhead="https://www.wowhead.com/wotlk/quest=13343",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="There you are! Or, were we just talking?$B$B<Chromie muses over the temporal possibilities.>$B$BAnyway, the Infinites are after you! Well, not you per-se. Rather, they're after the past version of you that defended the Hourglass of Eternity. You remember, right?$B$BThat was you back then, except it's you now too. Wait, that's not important. What is important is that you head back to the Bronze Dragonshrine and defend yourself and the hourglass from their attacks before you get erased from history!",logDesc="Chromie, at the top of Wyrmrest Temple, has asked you to travel once more to the Bronze Dragonshrine.$B$BOnce inside, place the Hourglass of Eternity on the ground and help your Past Self to protect it from the forces of the Infinite Dragonflight.",choiceRewards={{id=38763,qty=1},{id=38764,qty=1},{id=38765,qty=1}}} end
if not DB[13344] then DB[13344]={id=13344,zoneId=210,name="Not a Bug",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13344",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The cultists have discovered the last messenger you summoned, $r.$b$bWhile it was quite informative, it's important that we continue to monitor their every move.$b$bUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.$b$bUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.",logDesc="Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar."} end
if not DB[13345] then DB[13345]={id=13345,zoneId=210,name="Need More Info",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,rewardNextId=13346,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13345",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....$b$bPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!$b$bI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.",logDesc="Thassarian, aboard the Skybreaker, wants you to collect the 3 pages of Cultists' Research from the Cult Researchers at Aldur'thar and use them to create the Cult of the Damned Thesis."} end
if not DB[13346] then DB[13346]={id=13346,zoneId=210,name="No Rest For The Wicked",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13346",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="These fools have actually stumbled upon something that could pose a serious threat to our plans!$b$bThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.$b$bIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.$b$bCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.$b$bHurry, $r! Destroy him before he becomes any more powerful!",logDesc="Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur'thar.",choiceRewards={{id=44394,qty=1},{id=44393,qty=1},{id=44395,qty=1}}} end
if not DB[13347] then DB[13347]={id=13347,zoneId=65,name="Reborn From The Ashes",level=74,minLevel=71,giver="3",giverType="NPC",giverId=31333,ender="3",enderType="NPC",enderId=29611,rewardNextId=13369,poiX=4855,poiY=1472,wowhead="https://www.wowhead.com/wotlk/quest=13347",image="assets/images/quests/placeholder.png",xpDiff=7,desc="Our fate is emblazoned upon our souls at birth. Bolvar's fall, while tragic, was unavoidable.$B$BAll that you can do now is honor your hero, $N. Collect Bolvar's shield from the field of battle and return it to your king. When you present the shield to Varian, tell him this: \"All is not lost. From the ashes of the fallen will rise a force that will unite nations and purge the evil from this world.\"$B$BHe mustn't lose faith. Go now, $N. Your people need a hero. They need you.",logDesc="Gather Fordragon's Shield from the field of battle at Angrathar the Wrath Gate and return it to King Varian Wrynn at Stormwind Keep in Stormwind City."} end
if not DB[13348] then DB[13348]={id=13348,zoneId=210,name="Futility",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32404,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,rewardNextId=13349,poiX=7588,poiY=1398,wowhead="https://www.wowhead.com/wotlk/quest=13348",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Do you see now?  Sending your men against the prince's armies just swells their numbers.$B$BI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.",logDesc="Return to Koltira Deathweaver aboard Orgrim's Hammer."} end
if not DB[13349] then DB[13349]={id=13349,zoneId=210,name="Cradle of the Frostbrood",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13349",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="We need to keep our momentum going.  Let's not give the Scourge forces any respite.$B$BSindragosa's Fall lies east just beyond the Valley of Lost Hope.  The Cult of the Damned operate there, under close supervision of the Lich King's undead vrykul lackeys.$B$BIt is a place of great power, possibly a blue dragonflight graveyard.  The feared frostbrood are raised there from the bones of blue dragons.$B$BAn attack there would have great impact on the enemy's access to frost wyrms.  Are you up to it, $N?",logDesc="Koltira Deathweaver aboard Orgrim's Hammer wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa's Fall.",choiceRewards={{id=39115,qty=1},{id=39135,qty=1},{id=39136,qty=1},{id=39130,qty=1},{id=39133,qty=1}}} end
if not DB[13350] then DB[13350]={id=13350,zoneId=210,name="No Rest For The Wicked",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13350",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.$b$bIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.$b$bReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.$b$bHurry, $r! Destroy him before he becomes any more powerful!",logDesc="Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur'thar."} end
if not DB[13351] then DB[13351]={id=13351,zoneId=210,name="Sneak Preview",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13351",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from the Alliance.$b$bOur next focus will be Aldur'thar, the gate of desolation. Fly down and become familiar with it and with the enemies posted there.$b$bWhen you return, I will have your missions prepared.",logDesc="Koltira, aboard Orgrim's Hammer, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate. "} end
if not DB[13352] then DB[13352]={id=13352,zoneId=210,name="Drag and Drop",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13352",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Cult of the Damned hold the gate of desolation, eh? No surprise there.$b$bTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.$b$bThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.$b$bKill the fools until you find one, $c, then use it on a subjugator.",logDesc="Koltira, aboard Orgrim's Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there."} end
if not DB[13353] then DB[13353]={id=13353,zoneId=210,name="Drag and Drop",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13353",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Looks like those initiates are increasing in number again. You know what to do...$b$bAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.$b$bThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.$b$bSlay the fools until you find some, then use them on the subjugators there.",logDesc="Koltira, aboard Orgrim's Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there."} end
if not DB[13354] then DB[13354]={id=13354,zoneId=210,name="Chain of Command",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13354",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.$b$bWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, $r, is a worthy enough goal for now.$b$bSeek out these overseers and return to me when they have been dispatched.",logDesc="Koltira aboard Orgrim's Hammer wants you to go to Aldur'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.",choiceRewards={{id=43882,qty=1},{id=43891,qty=1},{id=43931,qty=1},{id=39458,qty=1}}} end
if not DB[13355] then DB[13355]={id=13355,zoneId=210,name="Cannot Reproduce",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Chief Engineer Copperclaw",enderType="NPC",enderId=30825,rewardNextId=13356,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13355",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I smell their cauldrons from here, but that's not plague they're cooking.$b$bPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.$b$bSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...$b$bFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Copperclaw.",logDesc="Koltira aboard Orgrim's Hammer wants you to use the Partitioned Flask at each of the 3 Cultists' Cauldrons at Aldur'thar, then bring it to Chief Engineer Copperclaw."} end
if not DB[13356] then DB[13356]={id=13356,zoneId=210,name="Retest Now",level=80,minLevel=77,giver="Chief Engineer Copperclaw",giverType="NPC",giverId=30825,ender="Chief Engineer Copperclaw",enderType="NPC",enderId=30825,poiX=38,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13356",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="This should do the trick!$b$bThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!$b$bTake a swig of this - don't worry, I've diluted it plenty... Its only effect will be to detect any cultist's essence once you've defeated them.$b$bWhen you've collected a bunch of essences, throw the writhing mass of twisted souls into any of their cauldrons.$b$bLet's see how they like a taste of their own medicine!",logDesc="Chief Engineer Copperclaw aboard Orgrim's Hammer wants you to throw a Writhing Mass into a cauldron at Aldur'thar.",choiceRewards={{id=39134,qty=1},{id=39144,qty=1},{id=39143,qty=1},{id=39121,qty=1},{id=39138,qty=1}}} end
if not DB[13357] then DB[13357]={id=13357,zoneId=210,name="Retest Now",level=80,minLevel=77,giver="Chief Engineer Copperclaw",giverType="NPC",giverId=30825,ender="Chief Engineer Copperclaw",enderType="NPC",enderId=30825,poiX=38,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13357",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!$b$bTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.$b$bOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.$b$bLet's see how they like a taste of their own medicine!",logDesc="Chief Engineer Copperclaw aboard Orgrim's Hammer wants you to throw a Writhing Mass into a cauldron at Aldur'thar."} end
if not DB[13358] then DB[13358]={id=13358,zoneId=210,name="Not a Bug",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13358",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Alright, $g friend:missy;, time to plant a bug.$b$bRelax, it's not a bug exactly, but it'll serve our purposes.$b$bIn the northern portion of Aldur'thar, the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use the cultists' summoning crystal to bring our little spy into being.$b$bUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.",logDesc="Koltira, aboard Orgrim's Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.",choiceRewards={{id=39372,qty=1},{id=39414,qty=1},{id=39443,qty=1},{id=39462,qty=1},{id=39471,qty=1}}} end
if not DB[13359] then DB[13359]={id=13359,zoneId=210,name="Where Dragons Fell",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32423,ender="Matthias Lehner",enderType="NPC",enderId=32423,poiX=7854,poiY=957,wowhead="https://www.wowhead.com/wotlk/quest=13359",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.$B$BHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.",logDesc="Matthias Lehner at Sindragosa's Fall wants you to obtain 6 Whelp Bone Dusts."} end
if not DB[13360] then DB[13360]={id=13360,zoneId=210,name="Time for Answers",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32423,ender="Matthias Lehner",enderType="NPC",enderId=32497,rewardNextId=13361,poiX=7854,poiY=957,wowhead="https://www.wowhead.com/wotlk/quest=13360",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="You have a lot of questions, $N.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?$B$BYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!$B$BMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.",logDesc="Speak to Matthias Lehner at the Court of Bones."} end
if not DB[13361] then DB[13361]={id=13361,zoneId=210,name="The Hunter and the Prince",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32497,ender="Matthias Lehner",enderType="NPC",enderId=32497,rewardNextId=13362,poiX=6370,poiY=2361,wowhead="https://www.wowhead.com/wotlk/quest=13361",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Before the prince became a king, he fought many battles... but only one where he came close to dying.$B$BIt was fought right here.  After you let me show you what happened, you'll understand everything.$B$BFind a bloodstained stone and pick it up from the floor.  You'll see what happened.",logDesc="Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince's Destiny.",choiceRewards={{id=38741,qty=1},{id=39040,qty=1},{id=39066,qty=1},{id=39108,qty=1}}} end
if not DB[13362] then DB[13362]={id=13362,zoneId=210,name="Knowledge is a Terrible Burden",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32497,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=6370,poiY=2361,wowhead="https://www.wowhead.com/wotlk/quest=13362",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Now you know what you're up against, $N.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.$B$BThe heart was his weakness and now he knows you've found it.$B$BIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.",logDesc="Report back to Koltira aboard Orgrim's Hammer."} end
if not DB[13363] then DB[13363]={id=13363,zoneId=210,name="Argent Aid",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="3",enderType="NPC",enderId=31044,rewardNextId=13364,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13363",image="assets/images/quests/placeholder.png",xpDiff=4,desc="There were rumors about the events you speak of among the death knights.  I always expected the story to be more... symbolic.$B$BWe must warn others, but we must be discreet.  As soon as the Lich King knows we're making our move, he'll move the location of the heart -- we'll never get a chance like this again.$B$BThe Horde and the Alliance have been infiltrated by the Cult of the Damned before.  The Ebon Blade operates too close to the Scourge.$B$BWe have to speak to Tirion Fordring and his Argent Crusade.",logDesc="Speak to Highlord Tirion Fordring at the Crusader's Pinnacle."} end
if not DB[13364] then DB[13364]={id=13364,zoneId=210,name="Tirion's Gambit",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31044,ender="3",enderType="NPC",enderId=31044,poiX=6427,poiY=440,wowhead="https://www.wowhead.com/wotlk/quest=13364",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.$B$BAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.$B$BThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!$B$BMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.",logDesc="Tirion Fordring, at the Crusader's Pinnacle, wants you to obtain and wear a Cultist Acolyte's Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.",choiceRewards={{id=44745,qty=1},{id=44747,qty=1},{id=44746,qty=1},{id=44748,qty=1}}} end
if not DB[13365] then DB[13365]={id=13365,zoneId=210,name="Not a Bug",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13365",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The cultists have discovered the last messenger you summoned, $r.$b$bWhile it was quite informative, it's important that we continue to monitor the cult's every move.$b$bUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.$b$bUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.",logDesc="Koltira, aboard Orgrim's Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar."} end
if not DB[13366] then DB[13366]={id=13366,zoneId=210,name="Need More Info",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,rewardNextId=13367,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13366",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....$b$bPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!$b$bI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.",logDesc="Koltira, aboard Orgrim's Hammer, wants you to collect the 3 pages of Cultists' Research from the Cult Researchers at Aldur'thar and use them to create the Cult of the Damned Thesis."} end
if not DB[13367] then DB[13367]={id=13367,zoneId=210,name="No Rest For The Wicked",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13367",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="These fools have actually stumbled upon something that could pose a serious threat to our plans!$b$bThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.$b$bIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.$b$bCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.$b$bHurry, $r! Destroy him before he becomes any more powerful!",logDesc="Koltira, aboard Orgrim's Hammer, wants you to slay Alumeth the Ascended at Aldur'thar.",choiceRewards={{id=44393,qty=1},{id=44394,qty=1},{id=44395,qty=1}}} end
if not DB[13368] then DB[13368]={id=13368,zoneId=210,name="No Rest For The Wicked",level=80,minLevel=77,giver="Koltira Deathweaver",giverType="NPC",giverId=29795,ender="Koltira Deathweaver",enderType="NPC",enderId=29795,poiX=46,poiY=7,wowhead="https://www.wowhead.com/wotlk/quest=13368",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.$b$bIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.$b$bReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.$b$bHurry, $r! Destroy him while there's still time!",logDesc="Koltira, aboard Orgrim's Hammer, wants you to slay Alumeth the Ascended at Aldur'thar."} end
if not DB[13369] then DB[13369]={id=13369,zoneId=65,name="Fate, Up Against Your Will",level=74,minLevel=71,giver="3",giverType="NPC",giverId=29611,ender="Thrall",enderType="NPC",enderId=32363,rewardNextId=13370,poiX=-8441,poiY=333,wowhead="https://www.wowhead.com/wotlk/quest=13369",image="assets/images/quests/placeholder.png",xpDiff=5,desc="At the behest of Lady Proudmoore, I will allow a diplomatic mission to Orgrimmar to question the Horde's Warchief, Thrall. You will assist her in this journey and keep her safe from harm. Return to me with news from Orgrimmar.$B$BSpeak to Jaina when you are ready to leave.",logDesc="Assist Lady Jaina Proudmoore in Orgrimmar. Speak to the Warchief of the Horde, Thrall, at Orgrimmar on the continent of Kalimdor."} end
if not DB[13370] then DB[13370]={id=13370,zoneId=65,name="A Royal Coup",level=74,minLevel=71,giver="Thrall",giverType="NPC",giverId=32363,ender="3",enderType="NPC",enderId=29611,rewardNextId=13371,wowhead="https://www.wowhead.com/wotlk/quest=13370",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Your champion, Bolvar, died in defense of our world. The Horde is saddened by the loss of such a great hero, but the Horde was not responsible for the cowardly attacks made by Putress at the Wrath Gate. We have also lost mighty heroes because of this betrayal.$B$BTell your king that we will do everything in our power to bring the perpetrators of this cowardly act to justice. We will do all that we can to avoid conflict with the Alliance, but we will not hesitate to defend ourselves if provoked.",logDesc="Use the portal in Grommash Hold to return to Stormwind Keep and deliver Thrall's message to King Varian Wrynn."} end
if not DB[13371] then DB[13371]={id=13371,zoneId=65,name="The Killing Time",level=74,minLevel=71,giver="3",giverType="NPC",giverId=29611,ender="3",enderType="NPC",enderId=32376,rewardNextId=13377,poiX=-8441,poiY=333,wowhead="https://www.wowhead.com/wotlk/quest=13371",image="assets/images/quests/placeholder.png",xpDiff=1,desc="I sent Broll and Valeera to the Undercity before you left for Orgrimmar. In fact, they're now stationed outside the sewer entrance to the ruins, awaiting orders.$B$BLady Proudmoore will open a portal to our forces outside the Undercity. Go there and report to Broll. Jaina and I will be close behind.",logDesc="Use the Portal to the Undercity inside Stormwind Keep to teleport to the Undercity. Report to Broll Bearmantle when you arrive at your destination."} end
if not DB[13372] then DB[13372]={id=13372,zoneId=65,name="The Key to the Focusing Iris",level=80,minLevel=80,ender="3",enderType="NPC",enderId=26917,wowhead="https://www.wowhead.com/wotlk/quest=13372",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.$B$BSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.",logDesc="Deliver the Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.",rewards={{id=44582,qty=1}}} end
if not DB[13373] then DB[13373]={id=13373,zoneId=210,name="Fringe Science Benefits",level=80,minLevel=77,giver="Fringe Engineer Tezzla",giverType="NPC",giverId=32430,ender="Fringe Engineer Tezzla",enderType="NPC",enderId=32430,poiX=7885,poiY=2058,wowhead="https://www.wowhead.com/wotlk/quest=13373",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I installed our infra-green technology into commandeered bombers; it'll protect you on your first mission into enemy territory!  Speak with Rizzy Ratchwiggle to get a bomber, then fly into The Bombardment!$B$BYou'll have bombs and rockets and shields.  Keep the shields charged and use bombs on the ground Scourge at The Bombardment.  Come back after you hit your targets, and more work will await you.",logDesc="Fringe Engineer Tezzla wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers."} end
if not DB[13374] then DB[13374]={id=13374,zoneId=210,name="Amped for Revolt!",level=80,minLevel=77,giver="Fringe Engineer Tezzla",giverType="NPC",giverId=32430,ender="Fringe Engineer Tezzla",enderType="NPC",enderId=32430,rewardNextId=13376,poiX=7885,poiY=2058,wowhead="https://www.wowhead.com/wotlk/quest=13374",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="$N, only our best pilots are given a mission like this, one deep, deep into enemy territory with only the power of infra-green technology to protect you!$B$BRequest another bomber from Rizzle, and this time fly it through the Valley of Lost Hope.  You have both air and ground targets on this mission, so keep your eyes open and your shields at full!$B$BGood luck!",logDesc="Fringe Engineer Tezzla wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines.$B"} end
if not DB[13375] then DB[13375]={id=13375,zoneId=65,name="The Heroic Key to the Focusing Iris",level=80,minLevel=80,ender="3",enderType="NPC",enderId=26917,wowhead="https://www.wowhead.com/wotlk/quest=13375",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.$B$BSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.",logDesc="Deliver the Heroic Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.",rewards={{id=44581,qty=1}}} end
if not DB[13376] then DB[13376]={id=13376,zoneId=210,name="Total Ohmage: The Valley of Lost Hope!",level=80,minLevel=77,giver="Fringe Engineer Tezzla",giverType="NPC",giverId=32430,ender="Fringe Engineer Tezzla",enderType="NPC",enderId=32430,poiX=7885,poiY=2058,wowhead="https://www.wowhead.com/wotlk/quest=13376",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="$N, the struggle continues.  Lucky for us, we're stocked up on bombs and rockets!  Time for another bombing mission  --  this one's a long one, through the Bombardment and into the Valley of Lost Hope.  Head back out with an infra-green bomber and blow those Scourge into little scourge-lets!",logDesc="Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines."} end
if not DB[13377] then DB[13377]={id=13377,zoneId=65,name="The Battle For The Undercity",level=74,minLevel=71,giver="3",giverType="NPC",giverId=32376,ender="3",enderType="NPC",enderId=29611,wowhead="https://www.wowhead.com/wotlk/quest=13377",image="assets/images/quests/placeholder.png",xpDiff=8,money=224000,desc="Deep inside the bowels of the Undercity hides the assassin responsible for the deaths of Bolvar and our brave soldiers at the Wrath Gate.$B$BVarian has brought the full might of the Alliance with him to assist in the take down. Join him and Lady Proudmoore in the manhunt and earn your place among the greatest champions of the Alliance!$B$BSpeak to King Varian Wrynn when you are ready.",logDesc="Assist King Varian Wrynn and Lady Jaina Proudmoore in bringing Grand Apothecary Putress to justice! Report to King Varian Wrynn should you succeed.",rewards={{id=44597,qty=1}},choiceRewards={{id=44591,qty=1},{id=44592,qty=1},{id=44593,qty=1},{id=44594,qty=1},{id=44595,qty=1},{id=44596,qty=1}}} end
if not DB[13378] then DB[13378]={id=13378,zoneId=210,name="Chief Engineer Copperclaw",level=80,minLevel=77,rewardNextId=13373,wowhead="https://www.wowhead.com/wotlk/quest=13378",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Speak with Chief Engineer Copperclaw.",logDesc="Speak with Chief Engineer Copperclaw."} end
if not DB[13379] then DB[13379]={id=13379,zoneId=210,name="Green Technology",level=80,minLevel=77,giver="Chief Engineer Copperclaw",giverType="NPC",giverId=30825,ender="Fringe Engineer Tezzla",enderType="NPC",enderId=32430,rewardNextId=13373,poiX=38,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13379",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Tezzla is the one you want to meet, yes she is... she mastered a new wavelength, infra-green, and used it to hide herself near the Scourge!  Near enough to bomb them!$B$BI'll give you infra-green vision so you can find her hiding above Aldur'thar, the Desolation Gate.  Go, go... I know she has work for brave heroes eager to blow up!  I mean... eager to blow up the Scourge!$B$BAnd $N, the Alliance has stolen our technology and has their own hidden airport nearby.  Avoid the dome with the Alliance banners!",logDesc="Speak with Fringe Engineer Tezzla."} end
if not DB[13380] then DB[13380]={id=13380,zoneId=210,name="Leading the Charge",level=80,minLevel=77,giver="Kibli Killohertz",giverType="NPC",giverId=32444,ender="Kibli Killohertz",enderType="NPC",enderId=32444,poiX=7632,poiY=2060,wowhead="https://www.wowhead.com/wotlk/quest=13380",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Infra-green technology allows us to stay hidden here, right over the Scourge's nose!  What's more, we installed infra-green in specially constructed bombers... but not to hide them, no!  We use infra-green tech to shield them!$B$BSpeak with Karen No and request a bomber.  Fly it over the Bombardment... use its shields and turret to protect yourself, and use the bomb launcher to hit Scourge targets.  Practice well, then return to me and I'll have an even more vital mission for you!",logDesc="Kibli Killohertz wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers."} end
if not DB[13381] then DB[13381]={id=13381,zoneId=210,name="Watts My Target",level=80,minLevel=77,giver="Kibli Killohertz",giverType="NPC",giverId=32444,ender="Kibli Killohertz",enderType="NPC",enderId=32444,rewardNextId=13382,poiX=7632,poiY=2060,wowhead="https://www.wowhead.com/wotlk/quest=13381",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Put on your lucky socks, $n, and say your favorite prayers.  This next mission will test your wit and fortitude like a visit from the in-laws!$B$BRequest another bomber from Karen No.  Take it beyond The Bombardment and over the Valley of Lost Hope.  You have more targets this time, both on the land an in the air.  Keep your shields charged and your ammo loaded, $n!  I'll see you when it's over.",logDesc="Kibli Killohertz wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines."} end
if not DB[13382] then DB[13382]={id=13382,zoneId=210,name="Putting the Hertz: The Valley of Lost Hope",level=80,minLevel=77,giver="Kibli Killohertz",giverType="NPC",giverId=32444,ender="Kibli Killohertz",enderType="NPC",enderId=32444,poiX=7632,poiY=2060,wowhead="https://www.wowhead.com/wotlk/quest=13382",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="The fight goes on!  Your new orders arrived for a long-range bombing mission through the Bombardment and into the Valley of Lost Hope -- when you're ready, ask Karen for a bomber and pour those bombs and rockets onto the Scourge!  ",logDesc="Kibli Killohertz wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines."} end
if not DB[13383] then DB[13383]={id=13383,zoneId=210,name="Killohertz",level=80,minLevel=77,giver="Chief Engineer Boltwrench",giverType="NPC",giverId=30345,ender="Kibli Killohertz",enderType="NPC",enderId=32444,rewardNextId=13380,poiX=-48,poiY=0,wowhead="https://www.wowhead.com/wotlk/quest=13383",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="The goblins got lucky and found a new energy.  They call it infra-green, and I'll be a one-eyed ogre if those psychos didn't strike green gold.$B$BGo find Kibli Killohertz.  He's leading the reverse engineering efforts of infra-green, at a small, hidden Alliance airport above Aldur'thar, the Desolation Gate.  I'll give you infra-green vision to help you find it.  Go to the dome with our Alliance banners -- if you fly near the Horde airport then you'll be in a load of green trouble.",logDesc="Chief Engineer Boltwrench wants you to find Kibli Killohertz at the hidden Alliance airport above Aldur'thar, the Desolation Gate."} end
if not DB[13384] then DB[13384]={id=13384,zoneId=4500,name="Judgment at the Eye of Eternity",level=80,minLevel=80,giver="Krasus",giverType="NPC",giverId=27990,ender="Krasus",enderType="NPC",enderId=27990,poiX=3529,poiY=274,wowhead="https://www.wowhead.com/wotlk/quest=13384",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="Now that you have access to the focusing iris it's time to put that key to use.$B$BAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.$B$B<Krasus says this last with a great deal of trepidation.>$B$B$N, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.",logDesc="Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.$B$BThis quest is for the Normal mode, 10-person version of The Eye of Eternity.",choiceRewards={{id=44658,qty=1},{id=44657,qty=1},{id=44659,qty=1},{id=44660,qty=1}}} end
if not DB[13385] then DB[13385]={id=13385,zoneId=4500,name="Heroic Judgment at the Eye of Eternity",level=80,minLevel=80,giver="Krasus",giverType="NPC",giverId=27990,ender="Krasus",enderType="NPC",enderId=27990,poiX=3529,poiY=274,wowhead="https://www.wowhead.com/wotlk/quest=13385",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="Now that you have access to the focusing iris it's time to put that key to use.$B$BAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.$B$B<Krasus says this last with a great deal of trepidation.>$B$B$N, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.",logDesc="Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.$B$BThis quest is for the Heroic mode, 25-person version of The Eye of Eternity.",choiceRewards={{id=44661,qty=1},{id=44662,qty=1},{id=44664,qty=1},{id=44665,qty=1}}} end
if not DB[13386] then DB[13386]={id=13386,zoneId=210,name="Exploiting an Opening",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Captain Kendall",enderType="NPC",enderId=31444,rewardNextId=13387,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13386",image="assets/images/quests/placeholder.png",xpDiff=3,desc="I've got an interesting assignment for you, $N.  If you're up for a challenge, that is.$B$BWe've been tipped off about an opening below Icecrown Citadel.  Our engineers have studied the layout and have decided it's a structural weakness.$B$BWe've sent some men there along with some \"borrowed\" saronite bombs.  They're under Captain Kendall's command.$B$BWith a little help we could deal a huge blow to the forces of the Scourge.  What do you say, $N?",logDesc="Speak to Captain Kendall below Icecrown Citadel."} end
if not DB[13387] then DB[13387]={id=13387,zoneId=4522,name="Securing the Perimeter",level=80,minLevel=77,giver="Captain Kendall",giverType="NPC",giverId=31444,ender="Captain Kendall",enderType="NPC",enderId=31444,rewardNextId=13388,poiX=5802,poiY=2199,wowhead="https://www.wowhead.com/wotlk/quest=13387",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The saronite bombs are in place, $N.  We're only going to get one shot at this, however.  Let's make it count.$B$BWe need temporary control of the area for a safe detonation.  Let's try to put a dent in the Scourge's numbers.",logDesc="Captain Kendall at Icecrown Citadel wants you to slay 10 Hulking Horrors.",choiceRewards={{id=38737,qty=1},{id=39036,qty=1},{id=39070,qty=1},{id=39102,qty=1}}} end
if not DB[13388] then DB[13388]={id=13388,zoneId=210,name="Set it Off!",level=80,minLevel=77,giver="Captain Kendall",giverType="NPC",giverId=31444,rewardNextId=13389,poiX=5802,poiY=2199,wowhead="https://www.wowhead.com/wotlk/quest=13388",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="Things are looking good.  Let's do this.$B$BThe stack of bombs is right near the pit.  I'll start to evacuate the men.",logDesc="Captain Kendall, below Icecrown Citadel, wants you to go to the nearby Saronite Bomb Stack to light the fuse."} end
if not DB[13389] then DB[13389]={id=13389,zoneId=210,name="A Short Fuse",level=80,minLevel=77,rewardNextId=13390,wowhead="https://www.wowhead.com/wotlk/quest=13389",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.$B$BThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.",logDesc="Look for clues wherever the fall takes you."} end
if not DB[13390] then DB[13390]={id=13390,zoneId=210,name="A Voice in the Dark",level=80,minLevel=77,ender="Matthias Lehner",enderType="NPC",enderId=31237,rewardNextId=13391,wowhead="https://www.wowhead.com/wotlk/quest=13390",image="assets/images/quests/placeholder.png",xpDiff=1,desc="The object is not a crystal at all, but some form of organ, encased in ice.$B$BAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.$B$BAs you collect your thoughts, you hear a young boy's voice nearby.$B$B\"You really shouldn't have done that.\"",logDesc="Investigate the nearby voice in Naz'anak, the Forgotten Depths."} end
if not DB[13391] then DB[13391]={id=13391,zoneId=210,name="Time to Hide",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=31237,ender="Matthias Lehner",enderType="NPC",enderId=31237,rewardNextId=13392,poiX=5793,poiY=2069,wowhead="https://www.wowhead.com/wotlk/quest=13391",image="assets/images/quests/placeholder.png",xpDiff=5,money=58000,desc="You shouldn't have touched it.  But now that you did, he's going to come looking for you.$B$BAnd he'll find you.  Unless you hide yourself from him.$B$BBring me blood from the faceless ones if you want to live!",logDesc="Matthias Lehner wants you to obtain 3 Faceless One's Blood.",choiceRewards={{id=43885,qty=1},{id=43918,qty=1},{id=43915,qty=1},{id=43916,qty=1},{id=43888,qty=1},{id=43917,qty=1}}} end
if not DB[13392] then DB[13392]={id=13392,zoneId=210,name="Return to the Surface",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=31237,ender="Thassarian",enderType="NPC",enderId=29799,rewardNextId=13393,poiX=5793,poiY=2069,wowhead="https://www.wowhead.com/wotlk/quest=13392",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="You should leave now.  You'll find a portal behind me.  It'll take you to the surface.$B$BWe'll meet again.  He'll be looking for you.$B$BIt's only a matter of time until he finds you.",logDesc="Return to Thassarian aboard the Skybreaker."} end
if not DB[13393] then DB[13393]={id=13393,zoneId=210,name="Field Repairs",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Wrecked Demolisher",enderType="NPC",enderId=31868,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13393",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="All right.  Let's not celebrate just yet.  We need to capitalize on the momentum we've gathered with our little bombing mission.$B$BWe've spotted a workable Horde demolisher-class catapult in the field below.  The geist seem to be taking it apart.$B$BIf you can put it back together, we'll be able to do some serious damage to the Scourge's armies in the Valley.$B$BSure, you'll be a little outnumbered, but I've a lot of faith in you!",logDesc="Thassarian, aboard the Skybreaker, wants you to collect 5 Demolisher Parts from the Scavenging Geists and take them to the Wrecked Demolisher in the Valley of Lost Hope."} end
if not DB[13394] then DB[13394]={id=13394,zoneId=210,name="Do Your Worst",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32408,ender="Matthias Lehner",enderType="NPC",enderId=32404,rewardNextId=13395,poiX=7270,poiY=1178,wowhead="https://www.wowhead.com/wotlk/quest=13394",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You're going to use this machine against the Scourge?  You're not going to win against them like that.$B$BYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.$B$BWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.",logDesc="Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope.  Speak to Matthias Lehner at the First Legion Forward Camp when you've completed this task.",choiceRewards={{id=43881,qty=1},{id=43892,qty=1},{id=43932,qty=1},{id=43930,qty=1},{id=43847,qty=1}}} end
if not DB[13395] then DB[13395]={id=13395,zoneId=210,name="Army of the Damned",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32404,ender="Matthias Lehner",enderType="NPC",enderId=32404,rewardNextId=13396,poiX=7588,poiY=1398,wowhead="https://www.wowhead.com/wotlk/quest=13395",image="assets/images/quests/placeholder.png",xpDiff=6,desc="You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.$B$BThat is nothing compared to the strength it took to create them.$B$BI saw the prince do it himself.  I can show you how it happened... if you'd like.",logDesc="Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions."} end
if not DB[13396] then DB[13396]={id=13396,zoneId=210,name="Futility",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32404,ender="Thassarian",enderType="NPC",enderId=29799,rewardNextId=13397,poiX=7588,poiY=1398,wowhead="https://www.wowhead.com/wotlk/quest=13396",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Do you see now?  Sending your men against the prince's armies just swells their numbers.$B$BI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.",logDesc="Return to Thassarian aboard the Skybreaker."} end
if not DB[13397] then DB[13397]={id=13397,zoneId=210,name="Sindragosa's Fall",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="Thassarian",enderType="NPC",enderId=29799,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13397",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="You're a real star, $N.  See, when I give one of these other soldiers an assignment, the odds of them getting it done are about fifty-fifty.  The odds of them coming back... well, slightly worse.$B$BBut with you, it's always a guaranteed thing.  Like gnomish clockwork!$B$BAnyway, I have another one for you.  Sindragosa's Fall, east of the valley.  There is some serious cultist activity, including and not limited to, the raising of frost wyrms.  I need you to go kick their teeth in.$B$BI hate cultists.",logDesc="Thassarian aboard the Skybreaker wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa's Fall.",choiceRewards={{id=39115,qty=1},{id=39135,qty=1},{id=39136,qty=1},{id=39130,qty=1},{id=39133,qty=1}}} end
if not DB[13398] then DB[13398]={id=13398,zoneId=210,name="Where Dragons Fell",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32423,ender="Matthias Lehner",enderType="NPC",enderId=32423,rewardNextId=13399,poiX=7854,poiY=957,wowhead="https://www.wowhead.com/wotlk/quest=13398",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.$B$BHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.",logDesc="Matthias Lehner at Sindragosa's Fall wants you to obtain 6 Whelp Bone Dusts."} end
if not DB[13399] then DB[13399]={id=13399,zoneId=210,name="Time for Answers",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32423,ender="Matthias Lehner",enderType="NPC",enderId=32497,rewardNextId=13400,poiX=7854,poiY=957,wowhead="https://www.wowhead.com/wotlk/quest=13399",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="You have a lot of questions, $N.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?$B$BYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!$B$BMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.",logDesc="Speak to Matthias Lehner at the Court of Bones."} end
if not DB[13400] then DB[13400]={id=13400,zoneId=210,name="The Hunter and the Prince",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32497,ender="Matthias Lehner",enderType="NPC",enderId=32497,rewardNextId=13401,poiX=6370,poiY=2361,wowhead="https://www.wowhead.com/wotlk/quest=13400",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Before the prince became a king, he fought many battles... but only one where he came close to dying.$B$BIt was fought right here.  After you let me show you what happened, you'll understand everything.$B$BFind a bloodstained stone and pick it up from the floor.  You'll see what happened.",logDesc="Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince's Destiny.",choiceRewards={{id=38741,qty=1},{id=39040,qty=1},{id=39066,qty=1},{id=39108,qty=1}}} end
if not DB[13401] then DB[13401]={id=13401,zoneId=210,name="Knowledge is a Terrible Burden",level=80,minLevel=77,giver="Matthias Lehner",giverType="NPC",giverId=32497,ender="Thassarian",enderType="NPC",enderId=29799,rewardNextId=13402,poiX=6370,poiY=2361,wowhead="https://www.wowhead.com/wotlk/quest=13401",image="assets/images/quests/placeholder.png",xpDiff=3,desc="Now you know what you're up against, $N.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.$B$BThe heart was his weakness and now he knows you've found it.$B$BIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.",logDesc="Report back to Thassarian aboard the Skybreaker."} end
if not DB[13402] then DB[13402]={id=13402,zoneId=210,name="Tirion's Help",level=80,minLevel=77,giver="Thassarian",giverType="NPC",giverId=29799,ender="3",enderType="NPC",enderId=31044,rewardNextId=13403,poiX=35,poiY=-39,wowhead="https://www.wowhead.com/wotlk/quest=13402",image="assets/images/quests/placeholder.png",xpDiff=4,desc="It's not the first time I've heard that story about Arthas and his heart... always thought it was some made-up tale to impress the rank and file.$B$BWe must act on this information immediately.  Unfortunately, we must do so in secret.$B$BArthas's agents are everywhere and if he finds out, our plan is dead in the water.$B$BWe need to take this to the Argent Crusade.  Every single paladin in that order was hand-picked by Tirion himself.  If there's anyone free of cultist infiltration, it's those guys.",logDesc="Speak to Highlord Tirion Fordring at the Crusader's Pinnacle."} end
if not DB[13403] then DB[13403]={id=13403,zoneId=210,name="Tirion's Gambit",level=80,minLevel=77,giver="3",giverType="NPC",giverId=31044,ender="3",enderType="NPC",enderId=31044,poiX=6427,poiY=440,wowhead="https://www.wowhead.com/wotlk/quest=13403",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.$B$BAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.$B$BThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!$B$BMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.",logDesc="Tirion Fordring, at the Crusader's Pinnacle, wants you to obtain and wear a Cultist Acolyte's Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.",choiceRewards={{id=44745,qty=1},{id=44746,qty=1},{id=44747,qty=1},{id=44748,qty=1}}} end
if not DB[13404] then DB[13404]={id=13404,zoneId=210,name="Static Shock Troops: the Bombardment",level=80,minLevel=77,giver="Kibli Killohertz",giverType="NPC",giverId=32444,ender="Kibli Killohertz",enderType="NPC",enderId=32444,poiX=7632,poiY=2060,wowhead="https://www.wowhead.com/wotlk/quest=13404",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="This is a short-ranged mission, over The Bombardment.  A good warm up.  Ready?",logDesc="Kibli Killohertz wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers."} end
if not DB[13405] then DB[13405]={id=13405,zoneId=4384,name="Call to Arms: Strand of the Ancients",level=-1,minLevel=71,wowhead="https://www.wowhead.com/wotlk/quest=13405",image="assets/images/quests/placeholder.png",xpDiff=7,money=74000,desc="The fight in Northrend is not only against the armies of the Lich King, but also against those of the Horde.$B$BA powerful titan relic has been found in the Strand of the Ancients.  As you might know, we dwarves have been custodians of such artifacts for years and as such we're their rightful keepers.$B$BIn this case, the Horde has developed a keen interest in pilfering the relic from the titan ruins.  They're certain to use it as a weapon against us; we must do whatever we can to stop them.",logDesc="Win a Strand of the Ancients battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath."} end
if not DB[13406] then DB[13406]={id=13406,zoneId=210,name="Riding the Wavelength: The Bombardment",level=80,minLevel=77,giver="Fringe Engineer Tezzla",giverType="NPC",giverId=32430,ender="Fringe Engineer Tezzla",enderType="NPC",enderId=32430,poiX=7885,poiY=2058,wowhead="https://www.wowhead.com/wotlk/quest=13406",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Ready to warm up with a short bombing mission?  You have your orders, and we have our bombers stocked and ready.",logDesc="Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers."} end
if not DB[13407] then DB[13407]={id=13407,zoneId=4384,name="Call to Arms: Strand of the Ancients",level=-1,minLevel=71,wowhead="https://www.wowhead.com/wotlk/quest=13407",image="assets/images/quests/placeholder.png",xpDiff=7,money=74000,desc="Just because we march into Northrend to smash the Scourge, doesn't mean we get to take a break from crushing the Alliance.$B$BThose Explorers' League dwarves have found the location of a powerful titan relic and we'll be damned if we let the Alliance take control of it.$B$BGo, $N, and destroy our enemies.  Make them see that no matter where we meet, they remain our sworn enemies.",logDesc="Win a Strand of the Ancients battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath."} end
if not DB[13408] then DB[13408]={id=13408,zoneId=3483,name="Hellfire Fortifications",level=60,minLevel=55,giver="Warrant Officer Tracy Proudwell",giverType="NPC",giverId=18266,ender="Warrant Officer Tracy Proudwell",enderType="NPC",enderId=18266,poiX=-683,poiY=2630,wowhead="https://www.wowhead.com/wotlk/quest=13408",image="assets/images/quests/placeholder.png",xpDiff=4,money=7000,desc="The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.$B$BOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.$B$BMay fortune shine upon you in the conflicts ahead, $N, for you will no doubt clash with Horde forces eager to gain these same fortifications.",logDesc="Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.",rewards={{id=40476,qty=1},{id=24579,qty=3}}} end
if not DB[13409] then DB[13409]={id=13409,zoneId=3483,name="Hellfire Fortifications",level=60,minLevel=55,giver="Battlecryer Blackeye",giverType="NPC",giverId=18267,ender="Battlecryer Blackeye",enderType="NPC",enderId=18267,poiX=131,poiY=2650,wowhead="https://www.wowhead.com/wotlk/quest=13409",image="assets/images/quests/placeholder.png",xpDiff=4,money=7000,desc="The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.$B$BOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!$B$BWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.$B$BFor the Horde!",logDesc="Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.",rewards={{id=40477,qty=1},{id=24581,qty=3}}} end
if not DB[13410] then DB[13410]={id=13410,zoneId=3483,name="Hellfire Fortifications",level=60,minLevel=55,giver="Warrant Officer Tracy Proudwell",giverType="NPC",giverId=18266,ender="Warrant Officer Tracy Proudwell",enderType="NPC",enderId=18266,poiX=-683,poiY=2630,wowhead="https://www.wowhead.com/wotlk/quest=13410",image="assets/images/quests/placeholder.png",xpDiff=4,money=7000,desc="The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.$B$BOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.$B$BMay fortune shine upon you in the conflicts ahead, $N, for you will no doubt clash with Horde forces eager to gain these same fortifications.",logDesc="Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.",rewards={{id=24579,qty=3}}} end
if not DB[13411] then DB[13411]={id=13411,zoneId=3483,name="Hellfire Fortifications",level=60,minLevel=55,giver="Battlecryer Blackeye",giverType="NPC",giverId=18267,ender="Battlecryer Blackeye",enderType="NPC",enderId=18267,poiX=131,poiY=2650,wowhead="https://www.wowhead.com/wotlk/quest=13411",image="assets/images/quests/placeholder.png",xpDiff=4,money=7000,desc="The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.$B$BOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!$B$BWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.$B$BFor the Horde!",logDesc="Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.",rewards={{id=24581,qty=3}}} end
if not DB[13412] then DB[13412]={id=13412,zoneId=4024,name="Corastrasza",level=80,minLevel=80,giver="Librarian Serrah",giverType="NPC",giverId=26110,ender="3",enderType="NPC",enderId=32548,rewardNextId=13413,poiX=3576,poiY=6640,wowhead="https://www.wowhead.com/wotlk/quest=13412",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="Greetings, $c. Might I impose on you for a favor?$b$bCorastrasza is the sister of Raelorasz - the red dragon in charge of our outpost here. Against his will, she has ascended to one of the upper rings of the Nexus to observe some frighteningly powerful blue drakes.$b$bThough he will never say it, he worries about her, and would welcome any news of her well-being.$b$bPlease seek her out. Ask her to put her pride aside and send word to her brother.",logDesc="Librarian Serrah wants you to speak to Corastrasza in Coldarra."} end
if not DB[13413] then DB[13413]={id=13413,zoneId=4024,name="Aces High!",level=80,minLevel=80,giver="3",giverType="NPC",giverId=32548,ender="3",enderType="NPC",enderId=32548,poiX=3944,poiY=6871,wowhead="https://www.wowhead.com/wotlk/quest=13413",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="You possess the courage to draw so near to Malygos' lair, mortal? Or is it simply ignorance? Soon we shall know....$b$bI am a seasoned trainer of the graceful drakes of the red dragonflight. My business here is to study the enemy and teach my precious pets the tactics that will be most effective when we face the master of the blues.$b$bTo demonstrate your nerve and ability, I will allow you to ride one of my drakes against the enemy's minions.$b$bThe opportunity is yours for the asking...",logDesc="Corastrasza on the upper ring of the Nexus in Coldarra wants you to ride her drake and kill 5 Scalesworn Elites.",choiceRewards={{id=44354,qty=1},{id=44355,qty=1},{id=44356,qty=1},{id=44357,qty=1}}} end
if not DB[13414] then DB[13414]={id=13414,zoneId=4024,name="Aces High!",level=80,minLevel=80,giver="3",giverType="NPC",giverId=32548,ender="3",enderType="NPC",enderId=32548,poiX=3944,poiY=6871,wowhead="https://www.wowhead.com/wotlk/quest=13414",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Again we meet, $r. I confess, your presence is beginning to grow on me.$b$bAm I correct in assuming that you've come to hone your aerial combat skills?$b$bAs always, my pets stand ready to bring fiery destruction to the enemy.$b$bSpeak, and they shall be at your disposal.",logDesc="Corastrasza on the upper ring of the Nexus in Coldarra wants you to ride her drake and kill 5 Scalesworn Elites."} end
if not DB[13415] then DB[13415]={id=13415,zoneId=67,name="The Library Console",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,rewardNextId=12872,wowhead="https://www.wowhead.com/wotlk/quest=13415",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Norgannon's shell is within our reach, $N. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!$B$BAnyway, use the disk to recover the shell. Hopefully, Mimir hasn't decided to put any more obstacles in our way. ",logDesc="Take the Inventor's Disk to the Inventor's Library Console inside the Inventor's Library."} end
if not DB[13416] then DB[13416]={id=13416,zoneId=67,name="The Library Console",level=80,minLevel=77,giver="Brann Bronzebeard",giverType="NPC",giverId=29579,rewardNextId=12928,wowhead="https://www.wowhead.com/wotlk/quest=13416",image="assets/images/quests/placeholder.png",xpDiff=3,money=37000,desc="Norgannon's shell is within our reach, $N. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!$B$BAnyway, bring the disk to the console. Hopefully, Mimir hasn't decided to put any more obstacles in our way. ",logDesc="Take the Inventor's Disk to the Inventor's Library Console inside the Inventor's Library."} end
if not DB[13417] then DB[13417]={id=13417,zoneId=67,name="The Brothers Bronzebeard",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=13417",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.$B$BHop on my flying machine and help keep us covered from those iron dwarves on the way out!",logDesc="Accompany Brann Bronzebeard and his flying machine to Frosthold.",choiceRewards={{id=43192,qty=1},{id=43191,qty=1},{id=43189,qty=1},{id=43190,qty=1}}} end
if not DB[13418] then DB[13418]={id=13418,zoneId=210,name="Preparations for War",level=80,minLevel=77,giver="Officer Van Rossem",giverType="NPC",giverId=31081,ender="High Captain Justin Bartlett",enderType="NPC",enderId=30344,poiX=5805,poiY=490,wowhead="https://www.wowhead.com/wotlk/quest=13418",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="You there!$B$BYou look like you have some wits about you. We could use some more able bodies in Icecrown.$B$BYou may have heard rumors of our failure in assaulting the glacier from the ground, but let me set those concerns to rest. We're now mounting our assault from one of the most advanced pieces of engineering known to Azeroth, the Skybreaker. The Horde don't stand a chance, and neither does Arthas.$B$BSpeak to me when you're ready to depart.",logDesc="Speak to Officer Van Rossem to secure passage to the Skybreaker in Icecrown, and then report to High Captain Justin Bartlett."} end
if not DB[13419] then DB[13419]={id=13419,zoneId=210,name="Preparations for War",level=80,minLevel=77,giver="Sky-Reaver Klum",giverType="NPC",giverId=31085,ender="Sky-Reaver Korm Blackscar",enderType="NPC",enderId=30824,poiX=5842,poiY=477,wowhead="https://www.wowhead.com/wotlk/quest=13419",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="You there!$B$BYou look like you have some wits about you. We could use some more able bodies in Icecrown.$B$BThe Alliance scum rushed into Icecrown ahead of us, unprepared, and got just what they deserved for their impatience. We took our time, we made ready, and soon we will mount a true assault from one of the most advanced pieces of engineering known to Azeroth - Orgrim's Hammer. The Alliance don't stand a chance, and neither does Arthas.$B$BSpeak to me when you're ready to depart and lend a hand.",logDesc="Speak to Sky-Reaver Klum to secure passage to Orgrim's Hammer in Icecrown, and then report to Sky-Reaver Korm Blackscar."} end
if not DB[13420] then DB[13420]={id=13420,zoneId=67,name="Everfrost",level=77,minLevel=77,ender="3",enderType="NPC",enderId=32594,wowhead="https://www.wowhead.com/wotlk/quest=13420",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="This piece of ice has been submitted to immense pressures and exposed to natural magics from deep beneath the world's surface. In combination, these effects have yielded an ice that will never melt.$b$bKnowing little of these things, you resolve to bring the sample back to Dun Niffelem. Someone there is bound to be familiar with its properties.",logDesc="You are to return to Dun Niffelem and ask Calder about the piece of Everfrost."} end
if not DB[13421] then DB[13421]={id=13421,zoneId=67,name="Remember Everfrost!",level=77,minLevel=77,giver="3",giverType="NPC",giverId=32594,ender="3",enderType="NPC",enderId=32594,poiX=7307,poiY=-2931,wowhead="https://www.wowhead.com/wotlk/quest=13421",image="assets/images/quests/placeholder.png",money=65000} end
if not DB[13422] then DB[13422]={id=13422,zoneId=67,name="Maintaining Discipline",level=79,minLevel=77,giver="Gretta the Arbiter",giverType="NPC",giverId=29796,ender="Gretta the Arbiter",enderType="NPC",enderId=29796,poiX=7088,poiY=-1777,wowhead="https://www.wowhead.com/wotlk/quest=13422",image="assets/images/quests/placeholder.png",xpDiff=4,money=55000,desc="You've succeeded where others have failed.  Yet you cannot rest on your laurels.$B$BYou must show others what strength and commitment really mean.$B$BThe male insubordinates inside the Forlorn Mine need to be disciplined once again.  Show them sister... show them what it means to disobey us.",logDesc="Gretta the Arbiter in Brunnhildar Village wants you to use the Disciplining Rod on 6 Exhausted Vrykul inside the Forlorn Mine.",rewards={{id=44751,qty=1}}} end
if not DB[13423] then DB[13423]={id=13423,zoneId=67,name="Defending Your Title",level=80,minLevel=77,giver="Gretta the Arbiter",giverType="NPC",giverId=29796,ender="Gretta the Arbiter",enderType="NPC",enderId=29796,poiX=7088,poiY=-1777,wowhead="https://www.wowhead.com/wotlk/quest=13423",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Everyone's impressed by your performance, sister.  But do not let your guard down -- every new challenger with delusions of grandeur is going to come out swinging for your title of Hyldskvinnar.$B$BShow these upstarts what you're made of.",logDesc="Gretta the Arbiter in Brunnhildar Village wants you to defeat 6 Victorious Challengers.",rewards={{id=44751,qty=1}}} end
if not DB[13424] then DB[13424]={id=13424,zoneId=67,name="Back to the Pit",level=80,minLevel=77,giver="Gretta the Arbiter",giverType="NPC",giverId=29796,ender="Gretta the Arbiter",enderType="NPC",enderId=29796,poiX=7088,poiY=-1777,wowhead="https://www.wowhead.com/wotlk/quest=13424",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="To truly stay in your best riding shape you'll want to test yourself against the other Hyldnir every day.$B$BHead back into the Pit of the Fang and show them what you're capable of.  They'll appreciate suffering defeat to one as skilled as yourself.",logDesc="Gretta the Arbiter, in Brunnhildar Village, wants you to use the Reins of the Warbear Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.",rewards={{id=44751,qty=1}}} end
if not DB[13425] then DB[13425]={id=13425,zoneId=67,name="The Aberrations Must Die",level=80,minLevel=77,giver="Gretta the Arbiter",giverType="NPC",giverId=29796,ender="Gretta the Arbiter",enderType="NPC",enderId=29796,poiX=7088,poiY=-1777,wowhead="https://www.wowhead.com/wotlk/quest=13425",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="It is not enough to demonstrate your prowess among your peers.  You must also fight our enemies, dear sister.$B$BThe Valkyrion traitors continue to mock our noble drake-riding traditions by rearing plagued proto-drakes.$B$BSeize the frost oil they wield and use it to freeze their abominable plagued eggs.",logDesc="Gretta the Arbiter in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants.  Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs.",rewards={{id=44751,qty=1}}} end
if not DB[13426] then DB[13426]={id=13426,zoneId=67,name="Xarantaur, the Witness",level=80,minLevel=77,giver="Boktar Bloodfury",giverType="NPC",giverId=29651,ender="Xarantaur",enderType="NPC",enderId=30381,rewardNextId=13034,poiX=7843,poiY=-812,wowhead="https://www.wowhead.com/wotlk/quest=13426",image="assets/images/quests/placeholder.png",xpDiff=1,money=7400,desc="It seems we're not the only visitors to this area. A courier relayed a message from a tauren named Xarantaur, who said he was visiting a taunka village called Camp Tunka'lo. The note was somewhat cryptic, but it seems this Xarantaur has come to Storm Peaks to learn the history of a taunka legend.$B$BMeet up with him, $N. See if what he knows can help us in any way. From his description, Camp Tunka'lo is far to the east, beyond the Terrace of the Makers and north of Dun Niffelem.",logDesc="Speak with Xarantaur at Camp Tunka'lo."} end
if not DB[13427] then DB[13427]={id=13427,zoneId=2597,name="Call to Arms: Alterac Valley",level=-1,minLevel=61,wowhead="https://www.wowhead.com/wotlk/quest=13427",image="assets/images/quests/placeholder.png",xpDiff=7,money=74000,desc="The reality of fighting on multiple fronts, $g lad : lass;, is that we cannot spread our forces too thin or we risk losing it all!$B$BCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.$B$BGo now, $N, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!",logDesc="Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath.$B"} end
if not DB[13428] then DB[13428]={id=13428,zoneId=2597,name="Call to Arms: Alterac Valley",level=-1,minLevel=61,wowhead="https://www.wowhead.com/wotlk/quest=13428",image="assets/images/quests/placeholder.png",xpDiff=7,money=74000,desc="We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.$B$BA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.$B$BGo, $N.  Earn great honor by heeding the call of the brave Frostwolf warriors.",logDesc="Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath."} end
if not DB[13429] then DB[13429]={id=13429,zoneId=3520,name="A Distraction for Akama",level=70,minLevel=70,rewardNextId=10958,wowhead="https://www.wowhead.com/wotlk/quest=13429",image="assets/images/quests/placeholder.png",xpDiff=5,desc="<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>",logDesc="Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.",rewards={{id=32649,qty=1}}} end
if not DB[13430] then DB[13430]={id=13430,zoneId=3836,name="Trial of the Naaru: Magtheridon",level=70,minLevel=70,giver="A'dal",giverType="NPC",giverId=18481,ender="A'dal",enderType="NPC",enderId=18481,poiX=-1864,poiY=5430,wowhead="https://www.wowhead.com/wotlk/quest=13430",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Four trials you must pass before you are deemed worthy by the naaru.$B$BOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!",logDesc="A'dal in Shattrath City wants you to slay Magtheridon.",rewards={{id=31746,qty=1}}} end
if not DB[13431] then DB[13431]={id=13431,zoneId=3717,name="The Cudgel of Kar'desh",level=70,minLevel=70,giver="Skar'this the Heretic",giverType="NPC",giverId=22421,ender="Skar'this the Heretic",enderType="NPC",enderId=22421,poiX=-296,poiY=-459,wowhead="https://www.wowhead.com/wotlk/quest=13431",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Bring me the elemental signets that the cudgel requires!$B$BThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.$B$BThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.$B$BMake haste!$B",logDesc="Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet."} end
if not DB[13432] then DB[13432]={id=13432,zoneId=1941,name="The Vials of Eternity",level=70,minLevel=70,giver="Soridormi",giverType="NPC",giverId=19935,ender="Soridormi",enderType="NPC",enderId=19935,poiX=-8495,poiY=-4431,wowhead="https://www.wowhead.com/wotlk/quest=13432",image="assets/images/quests/placeholder.png",xpDiff=7,money=132000,desc="Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.$B$BWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.",logDesc="Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep."} end
