if not DB[13502] then DB[13502]={id=13502,zoneId=-374,name="A Tisket, a Tasket, a Noblegarden Basket",level=-1,minLevel=1,giver="Noblegarden Vendor",giverType="NPC",giverId=32836,ender="Noblegarden Vendor",enderType="NPC",enderId=32836,poiX=-5601,poiY=-513,wowhead="https://www.wowhead.com/wotlk/quest=13502",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you've found ten Noblegarden Chocolates.",logDesc="The Noblegarden Vendor wants you to collect 10 Noblegarden Chocolates and return them along with the Egg Basket.",rewards={{id=45067,qty=1}}} end
if not DB[13503] then DB[13503]={id=13503,zoneId=-374,name="A Tisket, a Tasket, a Noblegarden Basket",level=-1,minLevel=1,giver="Noblegarden Merchant",giverType="NPC",giverId=32837,ender="Noblegarden Merchant",enderType="NPC",enderId=32837,poiX=2245,poiY=262,wowhead="https://www.wowhead.com/wotlk/quest=13503",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you've found ten Noblegarden Chocolates.",logDesc="The Noblegarden Merchant wants you to collect 10 Noblegarden Chocolates and return them along with the Egg Basket.",rewards={{id=45067,qty=1}}} end
if not DB[13524] then DB[13524]={id=13524,zoneId=394,name="Escape from Silverbrook",level=74,minLevel=73,rewardNextId=12310,wowhead="https://www.wowhead.com/wotlk/quest=13524",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You... you're not one of them?  Quick!  Let me out!$B$BWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!",logDesc="Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook.  Report to Lieutenant Dumont when you reach Amberpine Lodge.",choiceRewards={{id=38733,qty=1},{id=39031,qty=1},{id=39059,qty=1},{id=39097,qty=1},{id=38750,qty=1}}} end
if not DB[13538] then DB[13538]={id=13538,zoneId=4197,name="Southern Sabotage",level=80,minLevel=78,giver="Tactical Officer Ahbramis",giverType="NPC",giverId=31153,ender="Tactical Officer Ahbramis",enderType="NPC",enderId=31153,poiX=5088,poiY=2188,wowhead="https://www.wowhead.com/wotlk/quest=13538",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The three towers south of the Wintergrasp river are draining power from the Fortress! $B$BDestroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower, then return to me. Remember, only siege vehicles can damage a tower, so make sure to protect them from the Horde!",logDesc="Destroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower and return to Tactical Officer Ahbramis in Wintergrasp.",rewards={{id=43228,qty=10}}} end
if not DB[13539] then DB[13539]={id=13539,zoneId=4197,name="Toppling the Towers",level=80,minLevel=78,giver="Tactical Officer Kilrath",giverType="NPC",giverId=31151,ender="Tactical Officer Kilrath",enderType="NPC",enderId=31151,poiX=5363,poiY=2835,wowhead="https://www.wowhead.com/wotlk/quest=13539",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="While the Alliance may be pounding on our doors, a true tactician looks beyond the obvious.$B$B\"Attack him where he is unprepared, appear where you are not expected.\"$B$B$n, I need you to travel across the Wintergrasp River and destroy one of the three towers to the south. Our Warlocks report that the towers are draining power we could use to bolster our own troops.$B$BReturn to me once you've destroyed a tower.",logDesc="Destroy Shadowsight Tower, Flamewatch Tower, or Winter's Edge Tower and return to Tactical Officer Kilrath in Wintergrasp.",rewards={{id=43228,qty=10}}} end
if not DB[13548] then DB[13548]={id=13548,zoneId=-22,name="Candy Bucket",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=13548",image="assets/images/quests/placeholder.png",xpDiff=3,rewards={{id=37586,qty=1}}} end
if not DB[13549] then DB[13549]={id=13549,zoneId=66,name="Tails Up",level=77,minLevel=74,giver="Chronicler To'kini",giverType="NPC",giverId=28527,ender="Chronicler To'kini",enderType="NPC",enderId=28527,poiX=5740,poiY=-3595,wowhead="https://www.wowhead.com/wotlk/quest=13549",image="assets/images/quests/placeholder.png",xpDiff=5,money=65000,desc="Along with the Drakkari artifacts, I'm interested in returning to Zandalar with some of the Zul'Drak wildlife. I have males of both the frost leopards and icepaw bears, but I need females!$B$BToo bad that my trapper was killed in a most unfortunate accident. Perhaps you would be willing to fill in for him?$B$BPut the leopards and bears to sleep with this blowgun then lift their tails and return with some females if you would be so kind. They can be found near the Altars of Rhunok, Quetz'lun, and Har'koa.",logDesc="Chronicler To'kini at Zim'Torga wants you to use To'kini's Blowgun on Frost Leopards and Icepaw Bears. Return to him with 3 females of each."} end
if not DB[13556] then DB[13556]={id=13556,zoneId=66,name="Eggs for Dubra'Jin",level=77,minLevel=74,giver="Ha'wana",giverType="NPC",giverId=33025,ender="Ha'wana",enderType="NPC",enderId=33025,poiX=6971,poiY=-4095,wowhead="https://www.wowhead.com/wotlk/quest=13556",image="assets/images/quests/placeholder.png",xpDiff=5,desc="How ya doin', mon? Thinkin' ya might be helpin' me out? Bah'Kini be needin' lots o' the raptor eggs to be sacrificin' to Dubra'Jin.$B$BHow ya thinkin' we not be overrun yet by the Drakkari? Dubra'Jin be lendin' us his aid!$B$BWe need ya to gather up the raptor eggs from around the trees outside here in Gundrak. Sometimes the raptors carry 'em to keep 'em warm, too.",logDesc="Ha'wana at Dubra'Jin needs you to collect 12 Gundrak Raptor Eggs."} end
