if not DB[13702] then DB[13702]={id=13702,zoneId=-241,name="A Champion Rises",level=80,minLevel=77,giver="Marshal Jacob Alerius",giverType="NPC",giverId=33225,ender="Justicar Mariel Trueheart",enderType="NPC",enderId=33817,poiX=8628,poiY=641,wowhead="https://www.wowhead.com/wotlk/quest=13702",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Congratulations, $N. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.$B$BJusticar Mariel Trueheart has asked to speak with you, $N, and to formally enter you in the champions' grand melee.",logDesc="Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.",rewards={{id=44998,qty=1},{id=44990,qty=10}}} end
if not DB[13703] then DB[13703]={id=13703,zoneId=-241,name="Valiant Of Ironforge",level=80,minLevel=77,giver="Lana Stouthammer",giverType="NPC",giverId=33312,ender="Lana Stouthammer",enderType="NPC",enderId=33312,poiX=8612,poiY=638,wowhead="https://www.wowhead.com/wotlk/quest=13703",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Ironforge's tournament delegation?$B$BYou will train and rise through the ranks as you have before, but when you are named a champion of Ironforge, your squire will have the option of carrying our banner into battle.",logDesc="Speak with Lana Stouthammer again if you wish to become a valiant of Ironforge."} end
