if not DB[13706] then DB[13706]={id=13706,zoneId=-241,name="Valiant Of Darnassus",level=80,minLevel=77,giver="Jaelyne Evensong",giverType="NPC",giverId=33592,ender="Jaelyne Evensong",enderType="NPC",enderId=33592,poiX=8631,poiY=656,wowhead="https://www.wowhead.com/wotlk/quest=13706",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Welcome, champion. I have heard of your accomplishments and we would be honored if you would join the delegation from Darnassus.$B$BYou will train and rise through the ranks as you have before, but when you are named a champion of Darnassus, your squire will have the option of carrying our banner into battle.",logDesc="Speak with Jaelyne Eveonsong again if you wish to become a valiant of Darnassus."} end
