if not DB[13732] then DB[13732]={id=13732,zoneId=-241,name="A Champion Rises",level=80,minLevel=77,giver="Lana Stouthammer",giverType="NPC",giverId=33312,ender="Justicar Mariel Trueheart",enderType="NPC",enderId=33817,poiX=8612,poiY=638,wowhead="https://www.wowhead.com/wotlk/quest=13732",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Congratulations, $N. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.$B$BJusticar Mariel Trueheart has asked to speak with you, $N, and to formally enter you in the grand melee.",logDesc="Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.",rewards={{id=44998,qty=1},{id=44990,qty=10}}} end
