if not DB[13740] then DB[13740]={id=13740,zoneId=-241,name="A Champion Rises",level=80,minLevel=77,giver="Eressea Dawnsinger",giverType="NPC",giverId=33379,ender="Justicar Mariel Trueheart",enderType="NPC",enderId=33817,poiX=8429,poiY=650,wowhead="https://www.wowhead.com/wotlk/quest=13740",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of Silvermoon!$B$BJusticar Mariel Trueheart has asked to speak with you, $N, and to formally enter you in the champions' grand melee.",logDesc="Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.",rewards={{id=45022,qty=1},{id=44990,qty=10}}} end
if not DB[13741] then DB[13741]={id=13741,zoneId=-241,name="A Blade Fit For A Champion",level=80,minLevel=77,giver="Lana Stouthammer",giverType="NPC",giverId=33312,ender="Lana Stouthammer",enderType="NPC",enderId=33312,poiX=8612,poiY=638,wowhead="https://www.wowhead.com/wotlk/quest=13741",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.$B$BThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, $N. Otherwise, you'll catch warts.",logDesc="Retrieve the Ashwood Brand and bring it to Lana Stouthammer at the Argent Tournament Grounds.",rewards={{id=44987,qty=2}}} end
if not DB[13742] then DB[13742]={id=13742,zoneId=-241,name="A Worthy Weapon",level=80,minLevel=77,giver="Lana Stouthammer",giverType="NPC",giverId=33312,ender="Lana Stouthammer",enderType="NPC",enderId=33312,poiX=8612,poiY=638,wowhead="https://www.wowhead.com/wotlk/quest=13742",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Of all the times to have such rotten luck!$B$BMy tournament blade has gone missing and I need it for a match this afternoon.$B$BOne of the bards tells me that travelers used to present winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to Drak'Mar lake in northeastern Dragonblight, near its border with Zul'Drak and Grizzly Hills.",logDesc="Bring the Blade of Drak'Mar to Lana Stouthammer at the Argent Tournament Grounds.",rewards={{id=44987,qty=2}}} end
if not DB[13743] then DB[13743]={id=13743,zoneId=-241,name="The Edge Of Winter",level=80,minLevel=77,giver="Lana Stouthammer",giverType="NPC",giverId=33312,ender="Lana Stouthammer",enderType="NPC",enderId=33312,poiX=8612,poiY=638,wowhead="https://www.wowhead.com/wotlk/quest=13743",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Curse that death knight for breaking my sword!$B$BIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.$B$BBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.$B$BProve your worth and earn the weapon that she has guarded for so long, $N.",logDesc="Lana Stouthammer at the Argent Tournament Grounds wants you to bring her Winter's Edge.",rewards={{id=44987,qty=2}}} end
if not DB[13744] then DB[13744]={id=13744,zoneId=-241,name="A Valiant's Field Training",level=80,minLevel=77,giver="Rollo Sureshot",giverType="NPC",giverId=33315,ender="Rollo Sureshot",enderType="NPC",enderId=33315,poiX=8615,poiY=637,wowhead="https://www.wowhead.com/wotlk/quest=13744",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.$B$BTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.",logDesc="Rollo Sureshot at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.",rewards={{id=44987,qty=1}}} end
if not DB[13745] then DB[13745]={id=13745,zoneId=-241,name="The Grand Melee",level=80,minLevel=77,giver="Clara Tumblebrew",giverType="NPC",giverId=33309,ender="Clara Tumblebrew",enderType="NPC",enderId=33309,poiX=8609,poiY=638,wowhead="https://www.wowhead.com/wotlk/quest=13745",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The grand melee is the most important of the tournament's competitions. The people of Ironforge are looking forward to hearing of our success. To that end, they've been honing their skills against the valiants representing the other Alliance capitals.$B$BI suggest you do the same. The valiants practice in the ring just outside our tent. Equip your lance, go to the stables outside the pavilion and mount the stabled Ironforge ram, then challenge other Alliance valiants.$B",logDesc="Bring 3 Marks of the Valiant to Clara Tumblebrew at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.",rewards={{id=44987,qty=1}}} end
if not DB[13746] then DB[13746]={id=13746,zoneId=-241,name="A Blade Fit For A Champion",level=80,minLevel=77,giver="Ambrose Boltspark",giverType="NPC",giverId=33335,ender="Ambrose Boltspark",enderType="NPC",enderId=33335,poiX=8598,poiY=644,wowhead="https://www.wowhead.com/wotlk/quest=13746",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.$B$BThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, $N. Otherwise, you'll catch warts.",logDesc="Retrieve the Ashwood Brand and bring it to Ambrose Boltspark at the Argent Tournament Grounds.",rewards={{id=44987,qty=2}}} end
