if not DB[13748] then DB[13748]={id=13748,zoneId=-241,name="The Edge Of Winter",level=80,minLevel=77,giver="Ambrose Boltspark",giverType="NPC",giverId=33335,ender="Ambrose Boltspark",enderType="NPC",enderId=33335,poiX=8598,poiY=644,wowhead="https://www.wowhead.com/wotlk/quest=13748",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="That's the last time I ever spar with a death knight.$B$BIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.$B$BBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.$B$BProve your worth and earn the weapon that she has guarded for so long, $N.$B",logDesc="Ambrose Boltspark at the Argent Tournament Grounds wants you to bring him Winter's Edge.",rewards={{id=44987,qty=2}}} end
if not DB[13749] then DB[13749]={id=13749,zoneId=-241,name="A Valiant's Field Training",level=80,minLevel=77,giver="Tickin Gearspanner",giverType="NPC",giverId=33648,ender="Tickin Gearspanner",enderType="NPC",enderId=33648,poiX=8600,poiY=641,wowhead="https://www.wowhead.com/wotlk/quest=13749",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.$B$BTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.",logDesc="Tickin Gearspanner at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.",rewards={{id=44987,qty=1}}} end
if not DB[13750] then DB[13750]={id=13750,zoneId=-241,name="The Grand Melee",level=80,minLevel=77,giver="Flickin Gearspanner",giverType="NPC",giverId=33649,ender="Flickin Gearspanner",enderType="NPC",enderId=33649,poiX=8596,poiY=646,wowhead="https://www.wowhead.com/wotlk/quest=13750",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The grand melee is the most important of the tournament's competitions. We know everyone's looking forward to seeing us in the competition. To that end, we've been honing our skills against the valiants representing the other Alliance capitals.$B$BI suggest you do the same.$B$BGo to the stables outside the pavilion, equip your lance, mount the stabled turbostrider, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.$B",logDesc="Bring 3 Marks of the Valiant to Flickin Gearspanner at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.",rewards={{id=44987,qty=1}}} end
if not DB[13752] then DB[13752]={id=13752,zoneId=-241,name="A Blade Fit For A Champion",level=80,minLevel=77,giver="Colosos",giverType="NPC",giverId=33593,ender="Colosos",enderType="NPC",enderId=33593,poiX=8629,poiY=672,wowhead="https://www.wowhead.com/wotlk/quest=13752",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.$B$BThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, $N. Otherwise, you'll catch warts.",logDesc="Retrieve the Ashwood Brand and bring it to Colosos at the Argent Tournament Grounds.",rewards={{id=44987,qty=2}}} end
if not DB[13753] then DB[13753]={id=13753,zoneId=-241,name="A Worthy Weapon",level=80,minLevel=77,giver="Colosos",giverType="NPC",giverId=33593,ender="Colosos",enderType="NPC",enderId=33593,poiX=8629,poiY=672,wowhead="https://www.wowhead.com/wotlk/quest=13753",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="Of all the times to have such rotten luck!$B$BMy tournament blade has gone missing and I need it for a match this afternoon.$B$BOne of the bards tells me that travelers used to present winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to Drak'Mar lake in northeastern Dragonblight, near its border with Zul'Drak and Grizzly Hills.",logDesc="Bring the Blade of Drak'Mar to Colosos at the Argent Tournament Grounds.",rewards={{id=44987,qty=2}}} end
if not DB[13754] then DB[13754]={id=13754,zoneId=-241,name="The Edge Of Winter",level=80,minLevel=77,giver="Colosos",giverType="NPC",giverId=33593,ender="Colosos",enderType="NPC",enderId=33593,poiX=8629,poiY=672,wowhead="https://www.wowhead.com/wotlk/quest=13754",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="That's the last time I ever spar with a death knight.$B$BIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.$B$BBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.$B$BProve your worth and earn the weapon that she has guarded for so long, $N.",logDesc="Colosos at the Argent Tournament Grounds wants you to bring him Winter's Edge.",rewards={{id=44987,qty=2}}} end
if not DB[13755] then DB[13755]={id=13755,zoneId=-241,name="A Valiant's Field Training",level=80,minLevel=77,giver="Saandos",giverType="NPC",giverId=33655,ender="Saandos",enderType="NPC",enderId=33655,poiX=8625,poiY=673,wowhead="https://www.wowhead.com/wotlk/quest=13755",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.$B$BTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.",logDesc="Saandos at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.",rewards={{id=44987,qty=1}}} end
if not DB[13756] then DB[13756]={id=13756,zoneId=-241,name="The Grand Melee",level=80,minLevel=77,giver="Ranii",giverType="NPC",giverId=33656,ender="Ranii",enderType="NPC",enderId=33656,poiX=8630,poiY=669,wowhead="https://www.wowhead.com/wotlk/quest=13756",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The grand melee is the most important of the tournament's competitions. The people of the Exodar are looking forward to seeing us win the melee. To that end, they've been honing their skills against the valiants representing the other Alliance capitals.$B$BI suggest you do the same.$B$BGo to the stables outside the pavilion, equip your lance, mount the stabled Azuremyst elekk, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.",logDesc="Bring 3 Marks of the Valiant to Ranii at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.",rewards={{id=44987,qty=1}}} end
