if not DB[14151] then DB[14151]={id=14151,zoneId=-181,name="Cardinal Ruby",level=-1,minLevel=65,giver="Linzy Blackbolt",giverType="NPC",giverId=28703,ender="Linzy Blackbolt",enderType="NPC",enderId=28703,poiX=5889,poiY=699,wowhead="https://www.wowhead.com/wotlk/quest=14151",image="assets/images/quests/placeholder.png",xpDiff=5,desc="The Cardinal Ruby is said to be the finest gem in all of Northrend.  It sparkles like a crystal rose under the sun.$b$bBefore I teach you this recipe, I ask that you perform five epic gem transmutes to prepare your mind.  You can do any you like, and even do the same transmute many times.$b$bReturn to me when you are truly ready.",logDesc="Linzy Blackbolt in Dalaran wants you to successfully transmute 5 epic gems with your alchemy skill.  Acceptable transmutes include Ametrine, Eye of Zul, Dreadstone, King's Amber, and Majestic Zircon."} end
if not DB[14152] then DB[14152]={id=14152,zoneId=-241,name="Rescue at Sea",level=80,minLevel=78,giver="Narasi Snowdawn",giverType="NPC",giverId=34880,ender="Narasi Snowdawn",enderType="NPC",enderId=34880,poiX=8606,poiY=662,wowhead="https://www.wowhead.com/wotlk/quest=14152",image="assets/images/quests/placeholder.png",xpDiff=4,money=58000,desc="Champion, Captain Wavecrest and her ship were sent north to disrupt the Kvaldir in Hrothgar's Landing when they were intercepted by a Kvaldir raiding party headed to the Tournament Grounds. Unfortunately, the Kvaldir far outnumber the crew on board and are slowly taking over the ship.$B$BWe need you to go north to The Wavecrest in The Sea Reaver's Run, between the Tournament Grounds and Hrothgar's Landing and help the crew fend off the attack.  You should see the ship on the east side of the pass.",logDesc="Head out to The North Sea and kill 8 Vrykul Berserkers and 3 Vrykul Harpooners attacking The Wavecrest.",rewards={{id=44990,qty=1}}} end
if not DB[14160] then DB[14160]={id=14160,zoneId=-373,name="Writ of Merit",level=-1,minLevel=1,ender="Timothy Jones",enderType="NPC",enderId=28701,wowhead="https://www.wowhead.com/wotlk/quest=14160",image="assets/images/quests/placeholder.png",desc="This fine parchment lists a great many accomplishments, achieved by $N, in the tradition of jewelcrafting.$b$bReturn this writ to Timothy Jones in Dalaran for a proper reward.",logDesc="Deliver the Writ of Merit to Timothy Jones in Dalaran.",rewards={{id=41596,qty=5}}} end
if not DB[14163] then DB[14163]={id=14163,zoneId=4710,name="Call to Arms: Isle of Conquest",level=-1,minLevel=71,wowhead="https://www.wowhead.com/wotlk/quest=14163",image="assets/images/quests/placeholder.png",xpDiff=7,money=74000,desc="As we get closer to victory in Icecrown, it's become more apparent that our armies are going to have to deal with the Horde before they can deal with the Lich King.$B$BThe elite guard known as the Kor'kron has been deployed to block our advance in the Isle of Conquest.  The isle is of vital strategic importance, $N.  See to it that our lads prevail!",logDesc="Win an Isle of Conquest battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath."} end
if not DB[14164] then DB[14164]={id=14164,zoneId=4710,name="Call to Arms: Isle of Conquest",level=-1,minLevel=71,wowhead="https://www.wowhead.com/wotlk/quest=14164",image="assets/images/quests/placeholder.png",xpDiff=7,money=74000,desc="Victory in Northrend will be ours soon... but not until we obtain a foothold in Icecrown to transport and supply our forces.$B$BThe Isle of Conquest is an ideal location.  It is easily defensible and rich in resources.  The Alliance have reached the same conclusion and have sent the Seventh Legion to wrest control of it from our forces.$B$BGo, $N, and ensure that the Horde prevails at any cost!",logDesc="Win an Isle of Conquest battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath."} end
if not DB[14166] then DB[14166]={id=14166,zoneId=-41,name="The Grateful Dead",level=-1,minLevel=1,giver="Cheerful Dalaran Spirit",giverType="NPC",giverId=35256,ender="Cheerful Dalaran Spirit",enderType="NPC",enderId=35256,poiX=5856,poiY=767,wowhead="https://www.wowhead.com/wotlk/quest=14166",image="assets/images/quests/placeholder.png",xpDiff=5,desc="It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!$B$BMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...$B$BChapman there sells the recipe, I think.",logDesc="Acquire some Bread of the Dead and give it to the Cheerful Dalaran Spirit in Dalaran's graveyard.$B$BUse an Orange Marigold to see the otherwise invisible spirit.",rewards={{id=46831,qty=1}}} end
