if not DB[24710] then DB[24710]={id=24710,zoneId=4813,name="Deliverance from the Pit",level=80,minLevel=78,giver="Martin Victus",giverType="NPC",giverId=37591,ender="3",enderType="NPC",enderId=38188,rewardNextId=24711,wowhead="https://www.wowhead.com/wotlk/quest=24710",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="We need to make our way up the main path and through the cave to Tyrannus' rise. There, he will be forced to confront us there lest we make our way into the citadel proper.$B$BGo now, $c. My men and I will be there to stand by you when the confrontation with Tyrannus comes.",logDesc="Kill Scourgelord Tyrannus.",rewards={{id=49426,qty=2}}} end
if not DB[24711] then DB[24711]={id=24711,zoneId=4820,name="Frostmourne",level=80,minLevel=78,giver="3",giverType="NPC",giverId=38188,ender="3",enderType="NPC",enderId=37221,wowhead="https://www.wowhead.com/wotlk/quest=24711",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="We must press on, hero. We've come so far... we're so close to our goal. I must delay a moment to send Elandra back to the airship. I'm uncertain how we're going to escape with so many men lost and so few to keep our path in secure - we will need any help they can send.$B$BContinue on. I will meet you in the Halls of Reflection. ",logDesc="Meet Lady Jaina Proudmoore at the entrance to the Halls of Reflection."} end
if not DB[24712] then DB[24712]={id=24712,zoneId=4813,name="Deliverance from the Pit",level=80,minLevel=78,giver="Gorkun Ironskull",giverType="NPC",giverId=37592,ender="3",enderType="NPC",enderId=38189,rewardNextId=24713,poiX=631,poiY=112,wowhead="https://www.wowhead.com/wotlk/quest=24712",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="We need to make our way up the main path and through the cave to Tyrannus' rise. There, he will be forced to confront us there lest we make our way into the citadel proper.$B$BGo now, $c. My men and I will be there to stand by you when the confrontation with Tyrannus comes.",logDesc="Kill Scourgelord Tyrannus.",rewards={{id=49426,qty=2}}} end
if not DB[24713] then DB[24713]={id=24713,zoneId=4820,name="Frostmourne",level=80,minLevel=78,giver="3",giverType="NPC",giverId=38189,ender="3",enderType="NPC",enderId=37223,wowhead="https://www.wowhead.com/wotlk/quest=24713",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="Keep moving, the sword is close.$B$BI need a moment to send one of my Dark Rangers back to the airship. With all of our fodder gone, I will not be caught unprepared - we will need any help they can send.$B$BGo. I will meet you in the Halls of Reflection. ",logDesc="Meet Lady Sylvanas Windrunner inside the entrance to the Halls of Reflection."} end
if not DB[24743] then DB[24743]={id=24743,zoneId=4812,name="Shadow's Edge",level=80,minLevel=80,giver="3",giverType="NPC",giverId=37120,ender="3",enderType="NPC",enderId=37120,poiX=-70,poiY=2156,wowhead="https://www.wowhead.com/wotlk/quest=24743",image="assets/images/quests/placeholder.png",rewards={{id=49888,qty=1}}} end
if not DB[24745] then DB[24745]={id=24745,zoneId=-376,name="Something is in the Air (and it Ain't Love)",level=80,minLevel=75,ender="Inspector Snip Snagglebolt",enderType="NPC",enderId=38066,wowhead="https://www.wowhead.com/wotlk/quest=24745",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle's investigators immediately!",logDesc="Bring the Faded Lovely Greeting Card to Inspector Snip Snagglebolt in Stormwind."} end
if not DB[24746] then DB[24746]={id=24746,zoneId=0,name="REUSE",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=24746",image="assets/images/quests/placeholder.png"} end
if not DB[24748] then DB[24748]={id=24748,zoneId=4812,name="The Lich King's Last Stand",level=80,minLevel=80,giver="3",giverType="NPC",giverId=37120,ender="3",enderType="NPC",enderId=37120,poiX=-70,poiY=2156,wowhead="https://www.wowhead.com/wotlk/quest=24748",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="Shadowmourne; a newly forged weapon already steeped in this world's history, reborn into an unrivaled destiny.$b$bWith this weapon you bear a solemn responsibility, and the time to carry out that charge is at hand.$b$bTake this weapon of myth and legend and march on the enemy. Avenge the countless heroes lost in his merciless campaign. Bring rest to their tortured souls.$b$bSteel yourself, $c, and guide Shadowmourne to fulfill the purpose of its creation.",logDesc="Highlord Darion Mograine in Icecrown Citadel wants you to kill the Lich King."} end
if not DB[24749] then DB[24749]={id=24749,zoneId=4812,name="Unholy Infusion",level=80,minLevel=80,giver="3",giverType="NPC",giverId=37120,ender="3",enderType="NPC",enderId=37120,rewardNextId=24756,poiX=-70,poiY=2156,wowhead="https://www.wowhead.com/wotlk/quest=24749",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Before your weapon can reach its full potential it must be endowed with its signature powers. First among them is unholiness.$b$bYou must seek out and defeat the one called Professor Putricide, but his death is not your only goal. You must use his resources against him.$b$bFind a way to absorb his mutated slime. Use the foul substance to infuse your weapon with the power of the unholy. Only when this has been done shall I reveal your next task.",logDesc="Highlord Darion Mograine wants you to infuse Shadow's Edge with Unholy power and slay Professor Putricide.$B$BThis quest may only be completed in 25 person difficulty of Icecrown Citadel."} end
if not DB[24756] then DB[24756]={id=24756,zoneId=4812,name="Blood Infusion",level=80,minLevel=80,giver="3",giverType="NPC",giverId=37120,ender="3",enderType="NPC",enderId=37120,rewardNextId=24757,poiX=-70,poiY=2156,wowhead="https://www.wowhead.com/wotlk/quest=24756",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Your weapon is ready to be endowed with the power of blood.$b$bYou must face Queen Lana'thel in battle and subject yourself to her Blood Mirror. This will cause Shadow's Edge to drink the blood of the nearest living being. That being would be you, $r.$b$bOnce the blade has been thus awakened, allow the Queen's Frenzied Bloodthirst to take hold of you, feed the blade thrice to sate it, and then give the queen an ignominious death.$b$bMay her screams pierce the ears of the Lich King as he awaits his fate.",logDesc="Highlord Darion Mograine wants you to infuse Shadow's Edge with blood and defeat Queen Lana'thel.$B$BThis quest may only be completed in 25 person difficulty of Icecrown Citadel."} end
if not DB[24757] then DB[24757]={id=24757,zoneId=4812,name="Frost Infusion",level=80,minLevel=80,giver="3",giverType="NPC",giverId=37120,ender="3",enderType="NPC",enderId=37120,poiX=-70,poiY=2156,wowhead="https://www.wowhead.com/wotlk/quest=24757",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="Shadow's Edge is prepared to receive its final infusion of power.$b$bSindragosa, the enemy's own mount, must fall. But before she is brought down, you must sustain four of her frozen breath attacks without tasting death.$b$bWithout his dragon, nothing shall stand between you and the Lich King.",logDesc="Highlord Darion Mograine has instructed you to slay Sindragosa after subjecting yourself to 4 of her breath attacks while wielding Shadow's Edge.$B$BThis quest may only be completed in 25 person difficulty of Icecrown Citadel."} end
