if not DB[24792] then DB[24792]={id=24792,zoneId=-376,name="Man on the Inside",level=-1,minLevel=78,giver="Inspector Snip Snagglebolt",giverType="NPC",giverId=38066,ender="Investigator Fezzen Brasstacks",enderType="NPC",enderId=38208,rewardNextId=14488,poiX=-8868,poiY=653,wowhead="https://www.wowhead.com/wotlk/quest=24792",image="assets/images/quests/placeholder.png",xpDiff=2,money=19000,desc="You look like you're fit enough to take on the mastermind behind this operation. The ledger says he's holed up in Shadowfang Keep, so that's where I'm sending you.$b$bWe have a man there already but he's not fit to take down an operation by himself. Head on in; the investigator will meet you there. And bring friends.",logDesc="Report to Investigator Fezzen Brasstacks in Shadowfang Keep."} end
