if not DB[24795] then DB[24795]={id=24795,zoneId=210,name="A Victory For The Silver Covenant",level=80,minLevel=80,giver="Caladis Brightspear",giverType="NPC",giverId=36624,ender="Justicar Mariel Trueheart",enderType="NPC",enderId=33817,poiX=5653,poiY=2106,wowhead="https://www.wowhead.com/wotlk/quest=24795",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="In spite of Queen Lana'thel's boasting, you have restored Quel'Delar, $N. Long have we dreamt of reclaiming Quel'Delar.$B$BThe Silver Covenant, and indeed all quel'dorei owe you a debt of gratitude.$B$BAs a $c, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? Perhaps the Argent Crusade can find one. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Silver Covenant.",logDesc="Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.",choiceRewards={{id=50050,qty=1},{id=50051,qty=1},{id=50052,qty=1}}} end
if not DB[24796] then DB[24796]={id=24796,zoneId=210,name="A Victory For The Silver Covenant",level=80,minLevel=80,giver="Caladis Brightspear",giverType="NPC",giverId=36624,ender="Vereesa Windrunner",enderType="NPC",enderId=30115,poiX=5653,poiY=2106,wowhead="https://www.wowhead.com/wotlk/quest=24796",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="In spite of Queen Lana'thel's boasting, you have restored Quel'Delar, $N. Long have we dreamt of reclaiming Quel'Delar.$B$BThe Silver Covenant, and indeed all quel'dorei owe you a debt of gratitude.$B$BVereesa Windrunner, the leader of the Silver Covenant, asked to see you after you returned from the Sunwell. Take Quel'Delar with you and go to Dalaran's Violet Citadel where she waits, $N.",logDesc="Bring the Restored Quel'Delar to Vereesa Windrunner at the Violet Citadel in Dalaran.",choiceRewards={{id=50048,qty=1},{id=50049,qty=1},{id=50046,qty=1},{id=50047,qty=1}}} end
if not DB[24797] then DB[24797]={id=24797,zoneId=4075,name="REUSE",level=80,minLevel=77,wowhead="https://www.wowhead.com/wotlk/quest=24797",image="assets/images/quests/placeholder.png"} end
if not DB[24798] then DB[24798]={id=24798,zoneId=210,name="A Victory For The Sunreavers",level=80,minLevel=80,giver="Myralion Sunblaze",giverType="NPC",giverId=36642,ender="Justicar Mariel Trueheart",enderType="NPC",enderId=33817,poiX=5630,poiY=2088,wowhead="https://www.wowhead.com/wotlk/quest=24798",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="At last, Quel'Delar is restored for the glory of the Sunreavers and the sin'dorei!$B$BAll of Silvermoon will celebrate you as a hero, $N.$B$BAs a $c, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? No worthy sin'dorei has come forward. Let us seek the Argent Crusade's counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.",logDesc="Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.",choiceRewards={{id=50050,qty=1},{id=50051,qty=1},{id=50052,qty=1}}} end
if not DB[24799] then DB[24799]={id=24799,zoneId=210,name="A Victory For The Sunreavers",level=80,minLevel=80,giver="Myralion Sunblaze",giverType="NPC",giverId=36642,ender="Justicar Mariel Trueheart",enderType="NPC",enderId=33817,poiX=5630,poiY=2088,wowhead="https://www.wowhead.com/wotlk/quest=24799",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="At last, Quel'Delar is restored for the glory of the Sunreavers!$B$BAll the Horde will celebrate you as a hero, $N.$B$BAs a $c, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? I will not conceal my disappointment; I had hoped it would be a worthy sin'dorei. Let us seek the Argent Crusade's counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.",logDesc="Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.",choiceRewards={{id=50050,qty=1},{id=50051,qty=1},{id=50052,qty=1}}} end
if not DB[24800] then DB[24800]={id=24800,zoneId=210,name="A Victory For The Sunreavers",level=80,minLevel=80,giver="Myralion Sunblaze",giverType="NPC",giverId=36642,ender="Archmage Aethas Sunreaver",enderType="NPC",enderId=30116,poiX=5630,poiY=2088,wowhead="https://www.wowhead.com/wotlk/quest=24800",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="At last, Quel'Delar is restored for the glory of the Sunreavers and the sin'dorei! All of Silvermoon will proclaim you a hero, as will all of the Horde.$B$BArchmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, $N and bring Quel'Delar with you. The archmage wishes to congratulate you personally!",logDesc="Bring the Restored Quel'Delar to Archmage Aethas Sunreaver at the Violet Citadel in Dalaran.",choiceRewards={{id=50048,qty=1},{id=50049,qty=1},{id=50046,qty=1},{id=50047,qty=1}}} end
if not DB[24801] then DB[24801]={id=24801,zoneId=210,name="A Victory For The Sunreavers",level=80,minLevel=80,giver="Myralion Sunblaze",giverType="NPC",giverId=36642,ender="Archmage Aethas Sunreaver",enderType="NPC",enderId=30116,poiX=5630,poiY=2088,wowhead="https://www.wowhead.com/wotlk/quest=24801",image="assets/images/quests/placeholder.png",xpDiff=7,money=222000,desc="At last, Quel'Delar is restored for the glory of the Sunreavers and the Horde! This is a blessing for our efforts against the Lich King.$B$BArchmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, $N and bring Quel'Delar with you. The archmage wishes to congratulate you personally!",logDesc="Bring the Restored Quel'Delar to Archmage Aethas Sunreaver at the Violet Citadel in Dalaran.",choiceRewards={{id=50048,qty=1},{id=50049,qty=1},{id=50046,qty=1},{id=50047,qty=1}}} end
if not DB[24802] then DB[24802]={id=24802,zoneId=4820,name="Wrath of the Lich King",level=80,minLevel=78,giver="Dark Ranger Loralen",giverType="NPC",giverId=37779,ender="5",enderType="NPC",enderId=37554,poiX=4900,poiY=2206,wowhead="https://www.wowhead.com/wotlk/quest=24802",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="Uther knew a great deal about how Arthas might be defeated. It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?$B$BMany questions remain, but the answers that you've uncovered may be critical to ensuring Arthas' defeat. You need to find Sylvanas and escape the Lich King while there's still time.",logDesc="Find Lady Sylvanas Windrunner and escape the Halls of Reflection",rewards={{id=49426,qty=2}}} end
