if not DB[24804] then DB[24804]={id=24804,zoneId=-376,name="Uncommon Scents",level=-1,minLevel=1,giver="Junior Inspector",giverType="NPC",giverId=38293,ender="Inspector Snip Snagglebolt",enderType="NPC",enderId=38066,rewardNextId=24655,poiX=-4933,poiY=-995,wowhead="https://www.wowhead.com/wotlk/quest=24804",image="assets/images/quests/placeholder.png",desc="Something's not right about this Crown Chemical Company. Steamwheedle's got eyes on 'em, and we could use a few more.$b$bHead to Stormwind if you're interested in helping us out. Inspector Snip Snagglebolt is heading up the investigation there, and he can use all the help he can get.",logDesc="Report to Inspector Snip Snagglebolt in Stormwind."} end
if not DB[24805] then DB[24805]={id=24805,zoneId=-376,name="Uncommon Scents",level=-1,minLevel=1,giver="Junior Detective",giverType="NPC",giverId=38295,ender="Detective Snap Snagglebolt",enderType="NPC",enderId=37172,rewardNextId=24536,poiX=-1240,poiY=56,wowhead="https://www.wowhead.com/wotlk/quest=24805",image="assets/images/quests/placeholder.png",desc="Something's not right about this Crown Chemical Company. Steamwheedle's got eyes on 'em, and we could use a few more.$b$bHead to Orgrimmar if you're interested in helping us out. Detective Snap Snagglebolt is heading up the investigation there, and he can use all the help he can get.",logDesc="Report to Detective Snap Snagglebolt in Orgrimmar."} end
