if not DB[24848] then DB[24848]={id=24848,zoneId=-376,name="Fireworks At The Gilded Rose",level=-1,minLevel=1,giver="Inspector Snip Snagglebolt",giverType="NPC",giverId=38066,ender="Marion Sutton",enderType="NPC",enderId=38325,rewardNextId=24849,poiX=-8868,poiY=653,wowhead="https://www.wowhead.com/wotlk/quest=24848",image="assets/images/quests/placeholder.png",money=7400,desc="Kid, this is about more than just perfume. There were some rockets in that crate, and they had some kind of chemical payload inside. I can't analyze it here, but I'll spare ya the trip to the lab.$B$BNah, you gotta find the guy who made these. I know the maker's mark. Snivel Rustrocket.$B$BI got a tip from a reliable source that Snivel's here in Stormwind, livin' it up at the Gilded Rose. What's more, he had some dame on his arm. Marion Sutton was the name. Go to the Gilded Rose and see what she knows.",logDesc="Speak to Marion Sutton at the Gilded Rose in Stormwind's Trade District."} end
if not DB[24849] then DB[24849]={id=24849,zoneId=-376,name="Hot On The Trail",level=-1,minLevel=1,giver="Marion Sutton",giverType="NPC",giverId=38325,ender="Marion Sutton",enderType="NPC",enderId=38325,rewardNextId=24657,poiX=-8881,poiY=669,wowhead="https://www.wowhead.com/wotlk/quest=24849",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I'd better start from the beginning. It was love at first sight, $N. There was just something about that goblin from the moment I set eyes on him.$B$BAfter a wonderful week together, Snivel said he had come into a lot of money and that he was going to take me on a long vacation to the South Seas! Can you believe it?$B$BAnyway, he told me to pack while he ran some errands to the bank, the auction house, and the barber shop, but he never came back! I'm beginning to think he's nothing but a big liar!",logDesc="Look for Snivel Rustrocket in the Stormwind Counting House, the Auction House, and the Barbershop in Stormwind City."} end
if not DB[24850] then DB[24850]={id=24850,zoneId=-376,name="Snivel's Sweetheart",level=-1,minLevel=1,giver="Detective Snap Snagglebolt",giverType="NPC",giverId=37172,ender="Roka",enderType="NPC",enderId=38328,rewardNextId=24851,poiX=1659,poiY=-4393,wowhead="https://www.wowhead.com/wotlk/quest=24850",image="assets/images/quests/placeholder.png",money=7400,desc="Kid, this is about more than just perfume. There were some rockets in that crate, and they had some kind of chemical payload inside. I can't analyze it here, but I'll spare ya the trip to the lab.$B$BNah, you gotta find the guy who made these. I know the maker's mark. Snivel Rustrocket.$B$BI hear Snivel's livin' it up here in Orgrimmar. What's more, he's got himself a girlfriend -- some orc dame named Roka. She's supposed to meet him at Gotri's Travelling Goods in the Drag before they make their escape.",logDesc="Speak to Roka at the Gotri's Travelling Goods in Orgrimmar's Drag district."} end
if not DB[24851] then DB[24851]={id=24851,zoneId=-376,name="Hot On The Trail",level=-1,minLevel=1,giver="Roka",giverType="NPC",giverId=38328,ender="Roka",enderType="NPC",enderId=38328,rewardNextId=24576,poiX=1776,poiY=-4508,wowhead="https://www.wowhead.com/wotlk/quest=24851",image="assets/images/quests/placeholder.png",xpDiff=5,money=74000,desc="I'd better start from the beginning. It was love at first sight, $N. There was just something about that goblin from the moment I set eyes on him.$B$BAfter a wonderful week together, Snivel said he had come into a lot of money and that he was going to take me on a long vacation to the South Seas! Can you believe it?$B$BAnyway, he told me to pack while he ran some errands to the bank, the auction house, and the barber shop, but he never came back! I'm beginning to think he's nothing but a big liar!",logDesc="Look for Snivel Rustrocket in the Orgrimmar Bank, the Auction House, and the Barbershop in Orgrimmar."} end
if not DB[24857] then DB[24857]={id=24857,zoneId=220,name="Attack on Camp Narache",level=4,minLevel=1,ender="Chief Hawkwind",enderType="NPC",enderId=2981,wowhead="https://www.wowhead.com/wotlk/quest=24857",image="assets/images/quests/placeholder.png",xpDiff=6,desc="After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.$b$bSurely Chief Hawkwind could use this information!",logDesc="Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.",rewards={{id=4911,qty=1}}} end
if not DB[24869] then DB[24869]={id=24869,zoneId=4812,name="Deprogramming",level=80,minLevel=80,giver="Infiltrator Minchar",giverType="NPC",giverId=38471,ender="Infiltrator Minchar",enderType="NPC",enderId=38471,poiX=-505,poiY=2184,wowhead="https://www.wowhead.com/wotlk/quest=24869",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="We had hoped to place a man on the inside of the Cult of the Damned, to give us an inside angle on the Lich King's machinations, but we... underestimated the persuasive powers of Arthas and his dark minister, Lady Deathwhisper.$B$BOur man, Darnavan, is one of them now.$B$BIf you plan on fighting your way through the Oratory ahead, please keep your eyes peeled for Darnavan. If you can bring him back to us alive, we can attempt to reverse the Cult's brainwashing.",logDesc="Defeat Lady Deathwhisper while ensuring that Darnavan survives.",rewards={{id=52006,qty=1}}} end
if not DB[24870] then DB[24870]={id=24870,zoneId=4812,name="Securing the Ramparts",level=80,minLevel=80,giver="Kor'kron Lieutenant",giverType="NPC",giverId=38491,ender="Kor'kron Lieutenant",enderType="NPC",enderId=38491,poiX=-533,poiY=2151,wowhead="https://www.wowhead.com/wotlk/quest=24870",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="As if this place weren't enough of a madhouse to begin with, we're fighting a war on two fronts up here, with the Scourge on one side and those blasted Alliance dogs on our other flank!$B$BWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.$B$BI'll be honest -- he's a bit much for us to handle, but you and your companions look up to the task.",logDesc="Slay the Rotting Frost Giant.",rewards={{id=52006,qty=1}}} end
if not DB[24871] then DB[24871]={id=24871,zoneId=4812,name="Securing the Ramparts",level=80,minLevel=80,giver="Skybreaker Lieutenant",giverType="NPC",giverId=38492,ender="Skybreaker Lieutenant",enderType="NPC",enderId=38492,wowhead="https://www.wowhead.com/wotlk/quest=24871",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="As if this place weren't enough of a madhouse to begin with, we're fighting a war on two fronts up here, with the Scourge on one side and those blasted Horde dogs on our other flank!$B$BWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.$B$BI'll be honest -- he's a bit much for us to handle, but you and your companions look up to the task.",logDesc="Slay the Rotting Frost Giant.",rewards={{id=52006,qty=1}}} end
if not DB[24872] then DB[24872]={id=24872,zoneId=4812,name="Respite for a Tormented Soul",level=80,minLevel=80,giver="3",giverType="NPC",giverId=38589,ender="Kalecgos",enderType="NPC",enderId=38017,wowhead="https://www.wowhead.com/wotlk/quest=24872",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="Take this Life Crystal, and have your companions take one as well. It contains potent energies from the verdant Dragonshrine in Dragonblight, and it was my own secret to resisting the dark magics of this place for so long.$B$BWhen you face Sindragosa, battle her until she is weakened, and then have your companions use these Crystals to coax out the essence that is dormant within her. If you then defeat her, you should be able to recover it and return it to Wyrmrest Temple in Dragonblight.",logDesc="Use the Life Crystals to preserve Sindragosa's Essence.",rewards={{id=52006,qty=1}}} end
if not DB[24873] then DB[24873]={id=24873,zoneId=4812,name="Residue Rendezvous",level=80,minLevel=80,giver="Alchemist Adrianna",giverType="NPC",giverId=38501,ender="Alchemist Adrianna",enderType="NPC",enderId=38501,poiX=4247,poiY=2753,wowhead="https://www.wowhead.com/wotlk/quest=24873",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="Professor Putricide has been holed up in his foul laboratory, experimenting and refining increasingly lethal strains of blight to be used against us. If only we could obtain pure samples of the toxins, our researchers could concoct an antidote that would save countless lives.$B$BBut there's a catch -- a proper sample will need to mix two active strains within a living host. Should you have the... misfortune... of becoming such a host, please return here immediately so that we can harvest you for study.",logDesc="Return to Alchemist Adrianna while infected with Orange and Green Blight.",rewards={{id=52006,qty=1}}} end
if not DB[24874] then DB[24874]={id=24874,zoneId=4812,name="Blood Quickening",level=80,minLevel=80,giver="Alrin the Agile",giverType="NPC",giverId=38551,ender="Alrin the Agile",enderType="NPC",enderId=38551,poiX=4466,poiY=2788,wowhead="https://www.wowhead.com/wotlk/quest=24874",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="These Scourge bloodsuckers -- San'layn they call themselves - give me the creeps. We've had one of our best men keeping an eye on them. But this morning he got sloppy and got himself taken prisoner. He's being interrogated by the Queen herself right now, and his cries echo through the Crimson Halls. Please, save him before it's too late!",logDesc="Rescue Infiltrator Minchar before he is executed.",rewards={{id=52006,qty=1}}} end
if not DB[24875] then DB[24875]={id=24875,zoneId=4812,name="Deprogramming",level=80,minLevel=80,giver="Infiltrator Minchar",giverType="NPC",giverId=38471,ender="Infiltrator Minchar",enderType="NPC",enderId=38471,poiX=-505,poiY=2184,wowhead="https://www.wowhead.com/wotlk/quest=24875",image="assets/images/quests/placeholder.png",xpDiff=8,money=296000,desc="We had hoped to place a man on the inside of the Cult of the Damned, to give us an inside angle on the Lich King's machinations, but we... underestimated the persuasive powers of Arthas and his dark minister, Lady Deathwhisper.$B$BOur man, Darnavan, is one of them now.$B$BIf you plan on fighting your way through the Oratory ahead, please keep your eyes peeled for Darnavan. If you can bring him back to us alive, we can attempt to reverse the Cult's brainwashing.",logDesc="Defeat Lady Deathwhisper while ensuring that Darnavan survives.",rewards={{id=52006,qty=1}}} end
