if not DB[24914] then DB[24914]={id=24914,zoneId=4812,name="Personal Property",level=80,minLevel=80,ender="3",enderType="NPC",enderId=37120,wowhead="https://www.wowhead.com/wotlk/quest=24914",image="assets/images/quests/placeholder.png",xpDiff=6,money=148000,desc="You can detect no hinges or openings on this box. Were it not for the shifting of items inside,it could easily be mistaken for solid metal.$b$bIf anyone could know the method of its opening,it would be Highlord Mograine.",logDesc="Bring the Sealed Chest to Highlord Darion Mograine in Icecrown Citadel.",rewards={{id=51316,qty=1}}} end
