if not DB[25253] then DB[25253]={id=25253,zoneId=1519,name="Prophecies Of Doom",level=-1,minLevel=5,rewardNextId=25282,wowhead="https://www.wowhead.com/wotlk/quest=25253",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="Harbingers of doom are nothing new on the streets of Stormwind,but I'm worried about the most recent ones. They've set up shop all over Old Town and they seem well coordinated.$B$BI've thought about rounding them up or otherwise disrupting their activities,but that will just drive them underground. We need to find out as much as we can about them. Would you go to Old Town,hear what idea these doomsayers are spreading,and see if you can collect any of their leaflets?",logDesc="Listen to a speech given by a Doomsayer in Old Town and obtain copies of the pamphlets \"Elemental Fire for the Soul\",\"What Does 'The End of All Things' Mean for Me?\",and \"Finding Security and Comfort in a Doomed World\"."} end
if not DB[25254] then DB[25254]={id=25254,zoneId=1637,name="Signs Of The Times",level=-1,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=25254",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="We've got to do something to reduce interest in this doomsday cult,but I'm hesitant to take much action until we know more about who is behind this group.$B$BI've had my men place markers around heavily traveled areas in Orgrimmar. Take these posters and set them up where you see the markers. They won't discourage the most determined of seekers,but it's a first step in exposing this cult. The Horde has enough to deal with as it is,without people wilfully spreading lies too.",logDesc="Setup 5 Warning Posters around the Valley of Strength,the Drag,or the Valley of Honor."} end
if not DB[25282] then DB[25282]={id=25282,zoneId=1519,name="Signs Of The Times",level=-1,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=25282",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="We've got to do something to reduce interest in this doomsday cult,but I'm hesitant to take much action until we know more about who is behind this group.$B$BI've had my men place markers around heavily traveled areas of the city. Take these posters and set them up where you see the markers. They won't discourage the most determined of seekers,but it's a first step in exposing this cult. The already king has enough enemies without his own people turning against him.",logDesc="Setup 5 Warning Posters in the Trade District,Mage District,or Cathedral District of Stormwind."} end
if not DB[25283] then DB[25283]={id=25283,zoneId=1,name="Prepping the Speech",level=-1,minLevel=1,giver="Toby Zeigear",giverType="NPC",giverId=39678,ender="Toby Zeigear",enderType="NPC",enderId=39678,poiX=-5462,poiY=-627,wowhead="https://www.wowhead.com/wotlk/quest=25283",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="High Tinker Mekkatorque asked me to write a speech that he could give before the battle starts, but I just can't tell which draft is good and which ones just stink.$b$bCould you try some of them out on the local gnome residents? This device creates an image of Mekkatorque saying a few lines from each of my speech drafts.$b$bLet me know which one works, okay?",logDesc="Use the Gnomish Playback Device in front of Ozzie Togglevolt north of Kharanos,Milli Featherwhistle at Steelgrill Depot and Tog Rustsprocket outside the Kharanos Inn.  Return to Toby Ziegear when all the speeches have been given."} end
if not DB[25285] then DB[25285]={id=25285,zoneId=1,name="In and Out",level=-1,minLevel=1,rewardNextId=25289,wowhead="https://www.wowhead.com/wotlk/quest=25285",image="assets/images/quests/placeholder.png",xpDiff=3,money=17,desc="We've gotta get these new mechano-tanks ready for the assault.  You ready to help test these bad boys out?!  Of course you are!$b$bFirst,we need to make sure that once you're in,you can get out.  In battle,if you think your tank is going to explode,get out!  I've seen many a gnome stay in 'til the bitter end... the tank blows up,and them along with it.$B$BWell,I've upgraded this tank with an ejection seat.  Try it out for me,will ya?",logDesc="Test out the ejection system in the Ejector Mechano-Tank."} end
if not DB[25286] then DB[25286]={id=25286,zoneId=1,name="Words for Delivery",level=75,minLevel=75,giver="Toby Zeigear",giverType="NPC",giverId=39678,ender="Captain Tread Sparknozzle",enderType="NPC",enderId=39675,rewardNextId=25287,poiX=-5462,poiY=-627,wowhead="https://www.wowhead.com/wotlk/quest=25286",image="assets/images/quests/placeholder.png",xpDiff=3,money=30000,desc="Here we go. This is the speech, $N!$b$bIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes. Never has a finer speech been written!$b$bTurn this in to Captain Tread Sparknozzle and get some transportation to High Tinker Mekkatorque!",logDesc="Give the speech to Captain Tread Sparknozzle at Steelgrill Depot.",rewards={{id=54651,qty=1}}} end
if not DB[25287] then DB[25287]={id=25287,zoneId=1,name="Words for Delivery",level=75,minLevel=75,rewardNextId=25393,wowhead="https://www.wowhead.com/wotlk/quest=25287",image="assets/images/quests/placeholder.png",xpDiff=1,money=6000,desc="All right,soldier. Time to prove your worth!$B$BTake the speech and board the flying machine \"Thunderflash\".  It's the fastest ship to High Tinker Mekkatorque and this speech is the only thing he's waiting on before starting Operation: Gnomeregan.$B$BGo! Now!",logDesc="Ride 'Thunderflash' from Steelgrill Depot to High Tinker Mekkatorque and deliver Toby's speech."} end
if not DB[25288] then DB[25288]={id=25288,zoneId=1637,name="Infiltrating The Cult",level=-1,minLevel=1,rewardNextId=25380,wowhead="https://www.wowhead.com/wotlk/quest=25288",image="assets/images/quests/placeholder.png",xpDiff=3,desc="The streets of Orgrimmar are wild with rumors about the cult's origins and practices. There's only one way to know the truth about this group,$N. You're going to join them.$B$BApproach one of the Doomsayers in the Drag and tell them you wish to join their group. With any luck,they will give you instructions to introduce yourself to one of the group's leaders and tell you where the group is hiding. Don any clothing given to you by the doomsayer; you'll need it to gain entry to the group's hideout.",logDesc="Speak to a Doomsayer Orgrimmar's Drag to join the cult,then put on your Recruit's Robe."} end
if not DB[25289] then DB[25289]={id=25289,zoneId=1,name="One Step Forward...",level=-1,minLevel=1,rewardNextId=25295,wowhead="https://www.wowhead.com/wotlk/quest=25289",image="assets/images/quests/placeholder.png",xpDiff=3,money=17,desc="With the ejection system working,I think we're ready to test out movement.  This tank has an extra special feature: Automatic Evasive Maneuvers!$b$bI want you to check out the servos on the left leg,the right leg and the Automatic Evasive Maneuver system.$b$bThis is easy stuff,so it shouldn't take too long.",logDesc="Test the the Scuttling Mechano-Tank's maneuverability."} end
if not DB[25290] then DB[25290]={id=25290,zoneId=1519,name="Infiltrating the Cult",level=-1,minLevel=1,rewardNextId=25415,wowhead="https://www.wowhead.com/wotlk/quest=25290",image="assets/images/quests/placeholder.png",xpDiff=3,desc="It's getting difficult to keep the cultists out of the public eye and rumors are spreading across the city. I want you to join the cult and learn as much as you can.$B$BApproach one of the doomsayers in Old Town and tell them you wish to join their group. The doomsayer will likely give you clothing and instructions to meet with other cultists in one of the group's hideouts. Follow those instructions,$N. It's the only way to gain their confidence.",logDesc="Speak to Doomsayer Stormwind's Old Town to join the doomsday cult,then equip the Doomsday Recruit's Robe you receive."} end
if not DB[25293] then DB[25293]={id=25293,zoneId=1637,name="The Missing",level=-1,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=25293",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="Aside from the disturbances and the paranoia spread by the cult,we've been inundated with reports of missing people. Mothers,fathers,brothers,and sisters have seemingly disappeared,but I have a feeling that they can be found in one of the cult's compounds outside the city. If I give you the names of some of the missing people,would you try to locate them in the cultist camp at the Jaggedswine Farm south of Orgrimmar? To blend in,you'll need to get a robe from one of the doomsayers in the Drag.",logDesc="While wearing your Cult Disguise,speak to Cultist Kagarn,Cultish Agtar,Cultist Tokka,and Cultist Rokaga at the Jaggedswine Farm in Durotar."} end
if not DB[25295] then DB[25295]={id=25295,zoneId=1,name="Press Fire",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=25295",image="assets/images/quests/placeholder.png",xpDiff=3,money=17,desc="Safety systems,online!  Motor functions,functioning!  Now all we need is to make sure that the guns will fire.$b$bThis shouldn't be too hard,$n.  The mechano-tank on the hill behind us has been loaded with harmless pellets. Just fire off a couple rounds at the nearby targets and report back to me.",logDesc="Test out the Shooting Mechano-Tank weapon systems on the nearby targets."} end
if not DB[25306] then DB[25306]={id=25306,zoneId=0,name="You're In The Army Gnow!",level=-1,minLevel=1,wowhead="https://www.wowhead.com/wotlk/quest=25306",image="assets/images/quests/placeholder.png",desc="[ph] War!",logDesc="[ph] Log Description"} end
if not DB[25343] then DB[25343]={id=25343,zoneId=14,name="The Master's Plan",level=-1,minLevel=5,rewardNextId=25347,wowhead="https://www.wowhead.com/wotlk/quest=25343",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You're fitting in well here,$N,but there is more to us than daily chores and spreading the message. I'm sure you heard a little bit about it when you first joined.$B$BAs you know,this world is ending and the unprepared will die painful deaths.$B$BWe have been given a gift,an opportunity to become something greater and more powerful. Overseer Golbaz is will be preparing a ritual before the altar at the eastern end of the farm. Wait there for him,and learn more of your new brothers and sisters.",logDesc="Learn more about the cult's plans at the altar in the eastern part of the Jaggedswine Farm."} end
if not DB[25347] then DB[25347]={id=25347,zoneId=1637,name="The Doomsday Plan",level=-1,minLevel=5,rewardNextId=25348,wowhead="https://www.wowhead.com/wotlk/quest=25347",image="assets/images/quests/placeholder.png",xpDiff=4,money=25,desc="The first batch of elemental devices are ready. Your task will be to conceal them inside the city of Orgrimmar. The devices will unleash their fire elementals at the proper time. Don't worry,$N,you'll be safely away before that happens.$B$BDo not do anything that would draw attention to yourself.$B$B<The overseer hands you a package containing several of the elemental devices. This is just the kind of proof that Blood Guard Torek was hoping you'd uncover. You should probably bring the devices to him.>",logDesc="Take the Elemental Devices to Blood Guard Torek in Orgrimmar's Valley of Strength."} end
if not DB[25348] then DB[25348]={id=25348,zoneId=1637,name="Thwarting Twilight's Hammer",level=-1,minLevel=5,rewardNextId=25351,wowhead="https://www.wowhead.com/wotlk/quest=25348",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="You can't have been the only person sent into Orgrimmar to deploy those devices containing fire elementals. We have to find and disable the rest of the devices before set their captive elementals free and burn down the city.$B$BAre you familiar enough with the devices to destroy them? You need to break them open before the fire elementals inside have had time to reach full strength. They should be easy to defeat if you open the devices early. The cultists have probably put them all over the city.",logDesc="Break Elemental Devices to release their elementals. You must defeat 5 Raging Fire Elementals."} end
if not DB[25351] then DB[25351]={id=25351,zoneId=1637,name="Alert The Warchief",level=-1,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=25351",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="You have successfully defended Orgrimmar from the threat posed by this Twilight's Hammer cult,$N,and without shedding the blood of our own people. Our enemy will not rest for long. I cannot imagine that Cho'Gall will accept defeat so easily.$B$BYou must take word to Thrall. Go to the Valley of Wisdom and speak to him in Grommash Hold. Tell the warchief that our enemies have shown themselves and we must be prepared for their return.",logDesc="Speak with Thrall at Grommash Hold in Orgrimmar's Valley of Wisdom."} end
if not DB[25380] then DB[25380]={id=25380,zoneId=14,name="Spreading The Word",level=-1,minLevel=5,rewardNextId=25343,wowhead="https://www.wowhead.com/wotlk/quest=25380",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Welcome to the farm,$N. Everyone here works to earn $g his:her; keep. For some,that means caring for the animals. Others are responsible for working on our construction projects. Still others work to spread our message among the people and I think that's a good place for you to start.$B$BTake this board. It bears a short message about our beliefs. While wearing the board,visit the eastern and western zeppelin towers outside Orgrimmar's gates,as well as the town square of Razor Hill,to the south.",logDesc="While wearing your Doomsday Message,visit the East Zeppelin Tower,the West Zeppelin Tower,and the town square of Razor Hill."} end
if not DB[25393] then DB[25393]={id=25393,zoneId=1,name="Operation: Gnomeregan",level=75,minLevel=0,wowhead="https://www.wowhead.com/wotlk/quest=25393",image="assets/images/quests/placeholder.png",xpDiff=5,money=59000,desc="Momentarily,the multi-phased assault upon Gnomeregan will begin and Mekgineer Thermaplugg and his men will be brought to justice!  Too long has Thermaplugg festered in the depths of our home,defended by a corrupt and irradiated army.$B$BThe assault begins in but a moment! Be ready recruit,this fight will not be for the faint-hearted.",logDesc="Help King Mekkatorque with the assault on Gnomeregan.",rewards={{id=53097,qty=1}}} end
if not DB[25414] then DB[25414]={id=25414,zoneId=1519,name="The Missing",level=-1,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=25414",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="The cult isn't just spreading fear and paranoia anymore. Now,I'm receiving reports of missing people. Mothers,fathers,brothers,and sisters have seemingly disappeared,but I have a feeling they can be found in one of the cult's camps outside the city. If I give you the names of some of the missing people,would you try to locate them in the cultist camp at Mirror Lake Orchard? It's southwest of the city gates. To blend in,you'll need join the cult and get a robe from one of the doomsayers in Old Town.",logDesc="While wearing your Doomdsay Recruit's Robe,speak to Cultist Lethelyn,Cultish Kaima,Cultist Wyman,and Cultist Orlunn at Mirror Lake Orchard in Elywnn Forest."} end
if not DB[25415] then DB[25415]={id=25415,zoneId=12,name="Spreading The Word",level=-1,minLevel=5,rewardNextId=25416,wowhead="https://www.wowhead.com/wotlk/quest=25415",image="assets/images/quests/placeholder.png",xpDiff=5,desc="Welcome to our orchard,$N. Everyone here works to earn $g his:her; keep. For some,that means tending the fruit trees. Others are responsible for working on our construction projects. Still others work to spread our message among the people and I think that's a good place for you to start.$B$BTake this board. It bears a short message about our beliefs. While wearing it,visit the Westbrook Garrison,southwest of here,the town square of Goldshire just to the east,and the Valley of Heroes in Stormwind.",logDesc="While wearing your Doomsday Message,visit the Westbrook Garrison,the Valley of Heroes in Stormwind,and the town square of Goldshire."} end
if not DB[25416] then DB[25416]={id=25416,zoneId=12,name="The Master's Plan",level=-1,minLevel=5,rewardNextId=25417,wowhead="https://www.wowhead.com/wotlk/quest=25416",image="assets/images/quests/placeholder.png",xpDiff=5,desc="You're fitting in well here,$N,but there is more to us than daily chores and spreading the message. I'm sure you heard a little bit about it when you first joined.$B$BAs you know,this world is ending and the unprepared will die painful deaths.$B$BWe have been given a gift,an opportunity to become something greater and more powerful. Overseer Talathor is preparing for a ritual at the altar just north of the orchard. Wait there for him,and learn more of your new brothers and sisters.",logDesc="Learn more about the cult's plans at the altar in the northern part of Mirror Lake Orchard."} end
if not DB[25417] then DB[25417]={id=25417,zoneId=1519,name="The Doomsday Plan",level=-1,minLevel=5,rewardNextId=25418,wowhead="https://www.wowhead.com/wotlk/quest=25417",image="assets/images/quests/placeholder.png",xpDiff=4,money=25,desc="The first batch of elemental devices are ready. Your task will be to conceal them inside populated areas of Stormwind. The devices will unleash their elementals at the proper time. Don't worry,$N,you'll be safely away before that happens.$B$BDo not do anything that would draw attention to yourself.$B$B<The overseer hands you a package containing several of the elemental devices. This is just the kind of proof that Captain Anton was hoping you'd uncover. You should probably bring the devices to him.>",logDesc="Take the Elemental Devices to Captain Anton in Stormwind's Trade District."} end
if not DB[25418] then DB[25418]={id=25418,zoneId=1519,name="Thwarting Twilight's Hammer",level=-1,minLevel=5,rewardNextId=25425,wowhead="https://www.wowhead.com/wotlk/quest=25418",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="You can't have been the only person sent into Stormwind to deploy those devices containing wind elementals. We have to find and disable the rest of the devices before set their captive elementals free to create storms in the city.$B$BAre you familiar enough with the devices to destroy them? Our best chance is to break the devices before the elementals inside can reach full strength. Look for the devices in the Trade District,Cathedral Square and the Mage District. Hurry!",logDesc="Destroy Elemental Devices to release their captive elementals. Defeat 5 Raging Wind Elementals."} end
if not DB[25425] then DB[25425]={id=25425,zoneId=1519,name="Warn King Wrynn",level=-1,minLevel=5,wowhead="https://www.wowhead.com/wotlk/quest=25425",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="You have successfully defended Stormwind from the threat posed by this Twilight's Hammer cult,$N,and without harming our own citizens. Our enemy will not rest for long. Indeed,Cho'Gall must already be busy planning his next move.$B$BYou must take word to King Varian Wrynn. Go directly to him in the throne room of Stormwind Keep. Tell the king that our enemies have shown themselves and we must be prepared for their return.",logDesc="Speak with King Varian Wrynn in Stormwind Keep."} end
if not DB[25444] then DB[25444]={id=25444,zoneId=14,name="Da Perfect Spies",level=-1,minLevel=1,giver="Vanira",giverType="NPC",giverId=40184,ender="Vanira",enderType="NPC",enderId=40184,rewardNextId=25446,poiX=-747,poiY=-5004,wowhead="https://www.wowhead.com/wotlk/quest=25444",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="Now,it would be foolish to go in blind 'ere,so I be creatin' some tiny spies to gather information for Vol'jin. He got to know what's goin' on over on de islands.$B$BI could use da help,if you be feelin' up to it. I tell ya how it's done. First,ya gotta catch de frogs. Dey like to stay in de shade of da palm trees around Sen'jin.$B$BOnce ya have de frogs,bring 'em over here to my sentry totem an' attune dem to me sight.",logDesc="Capture 5 Sen'jin Frogs and attune them to Vanira's sight at her Sentry Totem."} end
if not DB[25445] then DB[25445]={id=25445,zoneId=393,name="Zalazane's Fall",level=78,minLevel=0,ender="Vol'jin",enderType="NPC",enderId=40391,wowhead="https://www.wowhead.com/wotlk/quest=25445",image="assets/images/quests/placeholder.png",xpDiff=5,money=68000,desc="De time for battle is now!  We'd be headin' ova to da islands soon,so you'd betta be ready.$B$BZalazane doesn't have much time left.",logDesc="Help Vol'jin take back the Echo Isles and kill Zalazane.",rewards={{id=54617,qty=1}}} end
if not DB[25446] then DB[25446]={id=25446,zoneId=14,name="Frogs Away!",level=-1,minLevel=1,giver="Vanira",giverType="NPC",giverId=40184,ender="Vanira",enderType="NPC",enderId=40184,poiX=-747,poiY=-5004,wowhead="https://www.wowhead.com/wotlk/quest=25446",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="Wit de frogs ready to go,I be needin' ya to help me send 'em out to the isles.$B$BOn de eastern side of Sen'jin Village,ya can find Handler Marnlek. He be handlin' all the bats for Vol'jin's scouts and he can loan ya a bat to get ya out to de isles.$B$BTake dis sack' o frogs with ya. I been askin' de spirits for guidance. Dey've sent smoke to show ya where I need de eyes most. While ridin' de bat,reach into de sack and toss de frogs toward de white smoke.",logDesc="While riding a bat,use the Sack o' Frogs to place 12 attuned frogs on the markers in the Echo Isles."} end
if not DB[25461] then DB[25461]={id=25461,zoneId=14,name="Trollin' For Volunteers",level=-1,minLevel=1,giver="Champion Uru'zin",giverType="NPC",giverId=40253,ender="Champion Uru'zin",enderType="NPC",enderId=40253,poiX=-765,poiY=-5018,wowhead="https://www.wowhead.com/wotlk/quest=25461",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="Vol'jin has given me his war drums and put  me in charge of trainin' da new recruits here. Only problem is we be short on new recruits.$B$BSupposin' I loaned ya dis drum,would ya use it to sound de call to war on Vol'jin's behalf in Razor Hill? If ya could even inspire just a few trolls to join da cause,it would make a difference. Once ya've convinced dem to volunteer,bring dem back to me for trainin'. Go over an' talk to Handler Marnlek to de south. He can lend you a bat for de ride to Razor Hill.",logDesc="Use Vol'jin's War Drums to recruit 5 Troll Citizens in Razor Hill.$B$BYou can speak to Handler Marnlek for a bat ride to Razor Hill."} end
if not DB[25470] then DB[25470]={id=25470,zoneId=14,name="Lady Of Da Tigers",level=-1,minLevel=1,giver="Vanira",giverType="NPC",giverId=40184,ender="Vol'jin",enderType="NPC",enderId=40391,rewardNextId=25480,poiX=-747,poiY=-5004,wowhead="https://www.wowhead.com/wotlk/quest=25470",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="Remember de frogs ya made into me eyes and ears? Well,dey've found somethin' interestin'.$B$BOn an island to de southeast,dey've spied a tiger even de other cats seem to fear. Dis tiger,I've never seen anythin' like it.$B$BIt hunts wit' da instincts of a cat,but de mind of a person. It could be a powerful spirit and a strong ally.$B$BI'll be callin' down the spirit o' the tiger upon ya. Use its gifts to locate this cat and challenge it. See if ya can win its aid in our battle for the isles.",logDesc="While imbued with the Spirit of the Tiger,lure the Tiger Matriarch out of hiding and use your new abilities to best it in combat."} end
if not DB[25480] then DB[25480]={id=25480,zoneId=14,name="Dance Of De Spirits",level=-1,minLevel=1,giver="Vol'jin",giverType="NPC",giverId=40391,ender="Vol'jin",enderType="NPC",enderId=40391,poiX=-755,poiY=-4998,wowhead="https://www.wowhead.com/wotlk/quest=25480",image="assets/images/quests/placeholder.png",xpDiff=5,money=35,desc="De time has come to start thinkin' about when to make our move. Champion Uru'zin tells me his men be ready. You and Vanira done good work gatherin' information on de enemy and findin' us new allies.$B$BNow,we read de omens. We find out when to launch de attack.$B$BFind Witch Doctor Hez'tok near the circle of ritual dancers. He be startin' de ritual as soon as ya be ready.",logDesc="Talk to Witch Doctor Hez'tok near the circle of ritual dancers outside Sen'jin Village when you're ready to consult the omens.",rewards={{id=54653,qty=1}}} end
if not DB[25482] then DB[25482]={id=25482,zoneId=0,name="World Event Dungeon - Headless Horseman",level=80,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=25482",image="assets/images/quests/placeholder.png",xpDiff=7,money=148000,rewards={{id=54516,qty=1}}} end
if not DB[25483] then DB[25483]={id=25483,zoneId=0,name="World Event Dungeon - Coren Direbrew",level=80,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=25483",image="assets/images/quests/placeholder.png",xpDiff=7,money=148000,rewards={{id=54535,qty=1}}} end
if not DB[25484] then DB[25484]={id=25484,zoneId=0,name="World Event Dungeon - Ahune",level=80,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=25484",image="assets/images/quests/placeholder.png",xpDiff=7,money=148000,rewards={{id=54536,qty=1}}} end
if not DB[25485] then DB[25485]={id=25485,zoneId=0,name="World Event Dungeon - Hummel",level=80,minLevel=75,wowhead="https://www.wowhead.com/wotlk/quest=25485",image="assets/images/quests/placeholder.png",xpDiff=7,money=148000,rewards={{id=54537,qty=1}}} end
if not DB[25495] then DB[25495]={id=25495,zoneId=14,name="Preparin' For Battle",level=-1,minLevel=75,giver="Champion Uru'zin",giverType="NPC",giverId=40253,ender="3",enderType="NPC",enderId=39654,rewardNextId=25445,poiX=-765,poiY=-5018,wowhead="https://www.wowhead.com/wotlk/quest=25495",image="assets/images/quests/placeholder.png",xpDiff=1,desc="Vol'jin be gatherin' his gear and readyin' de warriors. He ask me to tell ya to meet with him an' Vanira on de island to de east.$B$BFrom dere,he and de warriors will launch de attack on Zalazane. May de ancestors go wit' you,$N. Without ya,dis campaign would only be a shadow of what it become. Speak to Handler Marnlek,just to de south,an' he give you a bat to fly out to de stagin' area.",logDesc="Speak to Handler Marnlek for a flight to the staging area. Meet Vol'jin on the island east of the war camp."} end
if not DB[25500] then DB[25500]={id=25500,zoneId=1,name="Words for Delivery",level=-1,minLevel=1,giver="Toby Zeigear",giverType="NPC",giverId=39678,ender="Captain Tread Sparknozzle",enderType="NPC",enderId=39675,poiX=-5462,poiY=-627,wowhead="https://www.wowhead.com/wotlk/quest=25500",image="assets/images/quests/placeholder.png",xpDiff=3,money=17,desc="Here we go. This is the speech, $N!$b$bIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes. Never has a finer speech been written!$b$bTurn this in to Captain Tread Sparknozzle and see if there's anything else he needs of you.",logDesc="Give the speech to Captain Tread Sparknozzle at Steelgrill Depot.",rewards={{id=54651,qty=1}}} end
if not DB[26012] then DB[26012]={id=26012,zoneId=4987,name="Trouble at Wyrmrest",level=82,minLevel=80,giver="5",giverType="NPC",giverId=16128,ender="Krasus",enderType="NPC",enderId=27990,rewardNextId=26013,poiX=5798,poiY=798,wowhead="https://www.wowhead.com/wotlk/quest=26012",image="assets/images/quests/placeholder.png",xpDiff=1,money=8000,desc="My old friend Krasus sends word of dire happenings at Wyrmrest, in Dragonblight. His missive was brief, but it seems that there has been some sort of attack on the Ruby Sanctum beneath the Temple.$B$BPressing business here in Dalaran keeps me from attending to the matter personally, but I have heard word of your exploits in the Lich King's Citadel and you are doubtless up to the task -- perhaps you could assist Krasus in my stead?",logDesc="Speak with Krasus at Wyrmrest Temple in Dragonblight."} end
if not DB[26013] then DB[26013]={id=26013,zoneId=4987,name="Assault on the Sanctum",level=82,minLevel=80,giver="Krasus",giverType="NPC",giverId=27990,ender="3",enderType="NPC",enderId=40429,rewardNextId=26034,poiX=3529,poiY=274,wowhead="https://www.wowhead.com/wotlk/quest=26013",image="assets/images/quests/placeholder.png",xpDiff=5,money=80000,desc="$R, something terrible has transpired within the Ruby Sanctum beneath the Temple.$B$BThe entry to the Sanctum is in ruins, and its guardians violently slain. We sent scouts to investigate, but they have not returned. I cannot help but fear the worst.$B$BEnter the Ruby Sanctum and discover what has befallen the home of my flight. Once we have more information, we can plan our next steps accordingly.",logDesc="Investigate the Ruby Sanctum beneath Wyrmrest Temple."} end
if not DB[26034] then DB[26034]={id=26034,zoneId=4987,name="The Twilight Destroyer",level=82,minLevel=80,giver="3",giverType="NPC",giverId=40429,ender="Krasus",enderType="NPC",enderId=27990,poiX=3156,poiY=342,wowhead="https://www.wowhead.com/wotlk/quest=26034",image="assets/images/quests/placeholder.png",xpDiff=7,money=240000,desc="This was no reckless attack, but rather a carefully orchestrated strike against the heart of the Red Dragonflight.$B$BZarithrian, on the bluff over there, is overseeing the assault, but the true leader of this force is a brash and powerful Twilight dragon named Halion. Not since Dargonax has a full-grown spawn of Sinestra's twisted experiments been seen.$B$BSlay him, $N, and then when the invasion has been fully repelled, report to Krasus regarding all you have seen here.",logDesc="Defeat Halion and repel the invasion of the Ruby Sanctum.",rewards={{id=49426,qty=5}}} end
